INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 1, 'V začetku je ustvaril Bog nebesa in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 2, 'In zemlja je bila pusta in prazna, in tema je bila nad breznom, in Duh Božji je plaval nad vodami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 3, 'In reče Bog: Bodi svetloba! In bila je svetloba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 4, 'In videl je Bog svetlobo, da je dobra; in ločil je Bog svetlobo od teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 5, 'In svetlobo je Bog imenoval dan, a temo je imenoval noč. In bil je večer, in bilo je jutro, dan prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 6, 'In reče Bog: Bodi raztežje med vodami, da bo ločilo vode te in one.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 7, 'Naredi torej Bog raztežje in loči vode, ki so pod raztežjem, od vod, ki so nad raztežjem. In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 8, 'Raztežje to pa je imenoval Bog nebo. In bil je večer, in bilo je jutro, dan drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 9, 'In reče Bog: Zberó se naj vode, ki so pod nebom, v en kraj, in prikaži se sušina. In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 10, 'In sušino je imenoval Bog zemljo, a stoke vodá je imenoval morja. In videl je Bog, da je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 11, 'Še reče Bog: Zemlja poženi travo, zelenjavo, ki rodi seme, rodovitno drevje, ki daje sadje po svojem plemenu, katerega seme bodi v njem na zemlji! In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 12, 'In pognala je zemlja travo, zelenjavo, ki rodeva seme po svojem plemenu, in drevje, ki daje sadje, katerega seme je v njem, po njegovem plemenu. In videl je Bog, da je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 13, 'In bil je večer, in bilo je jutro, dan tretji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 14, 'Nato reče Bog: Bodo naj luči na raztežju nebeškem, da ločijo dan in noč, in naj bodo za znamenja ter določujejo čase, dneve in leta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 15, 'in bodo naj za luči na raztežju nebeškem, da svetijo na zemljo! In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 16, 'In naredil je Bog tisti dve veliki luči: luč večjo, da gospoduje dnevu, in luč manjšo, da gospoduje noči, in zvezde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 17, 'In Bog jih je postavil na raztežje nebeško, da svetijo na zemljo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 18, 'ter da gospodujejo dnevu in noči in da ločijo svetlobo od teme. In videl je Bog, da je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 19, 'In bil je večer, in bilo je jutro, dan četrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 20, 'In reče Bog: Obilo naj rodé vode gibkih stvari, živečih, in ptice naj letajo nad zemljo proti raztežju nebeškemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 21, 'In ustvaril je Bog velike morske živali in vse žive stvari, ki se gibljejo, ki so jih obilo rodile vode, po njih plemenih, in vse ptice krilate po njih plemenih. In videl je Bog, da je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 22, 'In blagoslovi jih Bog, govoreč: Plodite in množite se ter napolnite vode po morjih, in ptice naj se množe po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 23, 'In bil je večer, in bilo je jutro, dan peti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 24, 'In reče Bog: Rodi naj zemlja žive stvari po njih plemenih, živino in laznino in zveri zemeljske po njih plemenih! In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 25, 'In naredil je Bog zveri zemeljske po njih plemenih in živino po njenih plemenih in vso laznino zemeljsko po njenih vrstah. In videl je Bog, da je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 26, 'In reče Bog: Naredimo človeka po svoji podobi, ki nam bodi sličen, in gospodujejo naj ribam morskim in pticam nebeškim in živini in vesoljni zemlji ter vsej laznini, lazeči po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 27, 'In ustvaril je Bog človeka po svoji podobi, po Božji podobi ga je ustvaril: moža in ženo ju je ustvaril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 28, 'In blagoslovi ju Bog, in reče jima Bog: Plodita in množita se in napolnita zemljo ter podvrzita si jo, in gospodujta ribam morskim in pticam nebeškim in vsem zverem, lazečim po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 29, 'In reče Bog: Glejta, dal sem vama vso zelenjavo, ki rodeva seme, katera je na površju vse zemlje, in vse drevje, na katerem je sad drevesni, ki rodeva seme: bodi vama v hrano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 30, 'Vsem živalim pa na zemlji in vsem pticam pod nebom in vsemu, kar lazi po zemlji, v katerih je duša živa, sem dal vso zelenjavo zeleno v hrano. In zgodilo se je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 1, 31, 'Tedaj pogleda Bog vse, kar je bil storil, in glej, dobro je bilo jako. In bil je večer, in bilo je jutro, dan šesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 1, 'In tako so bila dodelana nebesa in zemlja in vsa njih vojska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 2, 'In dodelal je Bog sedmi dan delo svoje, katero je bil storil, in počival je sedmi dan od vsega dela svojega, ki ga je bil storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 3, 'In blagoslovil je Bog sedmi dan in ga posvetil, ker je ta dan počival od vsega dela svojega, ki ga je bil Bog ustvaril in storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 4, 'To so početki nebes in zemlje, ko so bila ustvarjena, ob času, ko je Gospod Bog naredil zemljo in nebo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 5, 'in ni bilo še nobenega bilja poljskega na zemlji, in vsa zelenjava poljska še ni bila pognala; ker ni bil Gospod Bog poslal dežja na zemljo, in ni bilo človeka, ki bi obdeloval zemljo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 6, 'a sopar je vzhajal iz zemlje in namakal vse površje zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 7, 'Tedaj upodobi Gospod Bog človeka iz prahu zemeljskega in vdahne v nosnice njegove dih življenja, in tako je postal človek živa duša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 8, 'Zasadi pa Gospod Bog vrt v Edenu proti jutru in postavi vanj človeka, ki ga je bil upodobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 9, 'In stori Bog, da je pognalo iz tiste zemlje vsaktero drevje, prijetno očesu in dobro v jed, tudi drevo življenja sredi vrta in drevo spoznanja dobrega in hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 10, 'In reka je tekla iz Edena močit ta vrt, in odtod se je delila in izlivala v štiri glavne reke:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 11, 'Prvi je ime Pison, ta, ki obteka vso pokrajino Havilsko, kjer je zlato;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 12, 'in zlato tiste pokrajine je izvrstno; tam je bdelij in kamen oniks.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 13, 'In ime drugi reki je Gihon, ta, ki obteka vso pokrajino Kuševo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 14, 'In ime tretji reki Hidekel, ta, ki teče v ospredju Asirije. Reka četrta pa je Evfrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 15, 'Vzame torej Gospod Bog človeka ter ga postavi na vrt Edenski, da bi ga obdeloval in ga varoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 16, 'In Gospod Bog zapove človeku, rekoč: Od vsega drevja s tega vrta prosto jej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 17, 'a od drevesa spoznanja dobrega in hudega, od tega ne jej: zakaj tisti dan, ko bodeš jedel od njega, gotovo zapadeš smrti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 18, 'Reče pa Gospod Bog: Ni dobro biti človeku samemu; naredim mu pomoč njegove vrste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 19, 'Kajti Gospod Bog je bil upodobil iz prsti vse živali na polju in vse ptice pod nebom ter jih privedel k Adamu, da bi videl, kako bode imenoval posamezne; in s katerimkoli imenom bi jih klical Adam, vsaktero živo bitje, tako mu bodi ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 20, 'In Adam je imenoval z imeni vse živali in ptice pod nebom in vse zveri na polju; a za Adama ni se našla pomoč njegove vrste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 21, 'In Gospod Bog pošlje trdno spanje Adamu, in zaspi; in vzame mu eno izmed reber njegovih in vtakne meso na mesto njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 22, 'In Gospod Bog stvori iz tistega rebra, ki ga je vzel Adamu, ženo, in jo privede k Adamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 23, 'Tedaj reče Adam: To je sedaj kost iz mojih kosti in meso iz mojega mesa; ta se bode imenovala Možinja, zato ker je vzeta iz moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 24, 'Zato zapusti mož očeta svojega in mater svojo in držal se bo žene svoje in bodeta v eno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 2, 25, 'Bila sta pa oba naga, Adam in žena njegova, a ni ju bilo sram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 1, 'Kača je pa bila prekanjena, bolj nego katerabodi poljskih živali, ki jih je naredil Gospod Bog. Ona reče ženi: Ali vama je res rekel Bog, da ne jejta od vsakega drevesa s tega vrta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 2, 'In žena odgovori kači: Od sadu drevja s tega vrta uživava;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 3, 'ali za sad tistega drevesa, ki je sredi vrta, je rekel Bog: Ne jejta od njega, tudi se ga ne doteknita, da ne umreta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 4, 'Kača pa reče ženi: Nikakor ne umrjeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 5, 'Bog namreč ve, da tisti dan, ko bosta jedla od njega, se vama odpro oči, in bodeta kakor Bog ter bosta spoznala dobro in hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 6, 'In žena je videla, da je dobro tisto drevo za jed in da je veselje očem in da je zaželeti to drevo, ker dodeli spoznanje; vzela je torej od sadu njegovega ter jedla; in dala je tudi možu svojemu, ki je bil ž njo, in jedel je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 7, 'Tedaj se odpro oči obema in spoznata, da sta naga; in sešijeta listje figovo in si naredita krila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 8, 'In začujeta glas Gospoda Boga, da hodi po vrtu ob hladilnem vetriču dneva. In skrije se Adam in žena njegova pred obličjem Gospoda Boga med vrtnim drevjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 9, 'Pokliče pa Gospod Bog Adama in mu reče: Kje si?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 10, 'In odgovori: Glas tvoj sem slišal na vrtu, zbal sem se pa, zato ker sem nag, in skril sem se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 11, 'Reče pa Bog: Kdo pa ti je povedal, da si nag? Ali si mar jedel od drevesa, za katero sem ti zapovedal, da ne jej od njega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 12, 'Adam pa odgovori: Žena, ki si mi jo dal, da bodi z menoj, ona mi je dala od drevesa, in jedel sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 13, 'In reče Gospod Bog ženi: Kaj si to storila? Reče pa žena: Kača me je zapeljala, in jedla sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 14, 'In Gospod Bog reče kači: Ker si storila to, prokleta bodi pred vsemi živalmi in pred vsemi zvermi poljskimi; po trebuhu svojem hodi in prah jej vse dni svojega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 15, 'In sovraštvo stavim med tebe in ženo, in med seme tvoje in njeno seme: to ti stare glavo, ti pa mu stareš peto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 16, 'Ženi reče: Jako pomnožim bolečino tvojo in nosečnosti tvoje težave, v bolečini bodeš rodila otroke, in po možu tvojem bodi poželenje tvoje, in on ti gospoduj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 17, 'Adamu pa reče: Ker si poslušal žene svoje glas in si jedel od drevesa, za katero sem ti zapovedal, rekoč: Ne jej od njega – prokleta bodi zemlja zaradi tebe: s trudom se živi od nje vse dni svojega življenja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 18, 'trnje in osat naj ti poganja, ti pa jej zelenjavo poljsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 19, 'V potu obraza svojega uživaj kruh, dokler se ne povrneš v zemljo, ker si bil vzet iz nje; kajti prah si in v prah se povrneš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 20, 'In Adam je dal ime ženi svoji Eva, zato ker je ona mati vseh živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 21, 'In Gospod Bog naredi Adamu in ženi njegovi suknji iz kož, in ju je oblekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 22, 'In veli Gospod Bog: Glej, človek je postal kako eden izmed nas, v kolikor ve, kaj je dobro in hudo. Sedaj pa, da ne iztegne roke svoje ter ne vzame tudi od drevesa življenja, in bi jedel in živel vekomaj –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 23, 'ga odpravi torej Gospod Bog z vrta Edena, da naj obdeluje zemljo, iz katere je bil vzet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 3, 24, 'In je izgnal Adama in postavil ob vzhodni strani Edenskega vrta kerube in plamen meča švigajočega, da stražijo pot do drevesa življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 1, 'In Adam je spoznal Evo, ženo svojo, in spočela je in rodila Kajna ter rekla: Dobila sem moža s pomočjo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 2, 'In zopet je rodila brata njegovega Abela. In bil je Abel pastir ovac in Kajn je bil kmetovalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 3, 'Zgodi se pa čez mnogo dni, da prinese Kajn daritev od sadu zemeljskega Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 4, 'In tudi Abel prinese od prvencev črede svoje in od njih tolšče. In ozre se Gospod na Abela in na daritev njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 5, 'a na Kajna in daritev njegovo se ne ozre. In raztogoti se Kajn silno in upade obličje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 6, 'Tedaj reče Gospod Kajnu: Zakaj si se raztogotil in zakaj je upadlo obličje tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 7, 'Ne bode li ti, če dobro delaš, povišanja? če pa ne delaš dobrega, preži greh pred durmi, in proti tebi je poželenje njegovo, a ti mu gospoduj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 8, 'In govoril je Kajn z bratom svojim Abelom. Zgodi se pa, ko sta bila na polju, da se vzpne Kajn nad Abela, brata svojega, ter ga ubije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 9, 'In reče Gospod Kajnu: Kje je Abel, brat tvoj? On pa odgovori: Ne vem; sem li jaz varuh brata svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 10, 'In mu reče: Kaj si storil? Glas krvi brata tvojega vpije z zemlje do mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 11, 'Ti torej bodi sedaj proklet in pregnan z zemlje, ki je odprla usta svoja, da prejme kri brata tvojega iz roke tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 12, 'Ko bodeš obdeloval zemljo, ne dá ti odslej moči svoje; potikal se boš in begal po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 13, 'Tedaj reče Kajn Gospodu: Prevelika je krivda moja, da bi jo prenašal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 14, 'Glej, izganjaš me danes s tal te zemlje, in pred obličjem tvojim se mi je skrivati, in se bodem potikal in begal po zemlji, in zgodi se, kdor koli me dobi, me ubije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 15, 'Reče pa mu Gospod: Zato, kdorkoli ubije Kajna, kaznovan bodi sedemkrat. In Gospod je zaznamenjal Kajna, da bi ga ne ubil nihče, kdor ga dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 16, 'Kajn torej odide izpred obličja Gospodovega in se naseli v deželi Nodi, vzhodno od Edena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 17, 'In spozna Kajn ženo svojo, in je spočela in rodila Enoha. In zidal je mesto, in imenoval je tisto mesto po imenu sina svojega Enoh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 18, 'Potem se rodi Enohu Irad, in Irad rodi Mehujaela, Mehujael pa rodi Metuzaela, in Metuzael rodi Lameha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 19, 'Lameh pa si vzame dve ženi, prvi je bilo ime Ada, in ime drugi Zila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 20, 'In Ada rodi Jabala; ta je bil oče prebivajočih v šatorih in pastirjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 21, 'In ime brata njegovega je bilo Jubal; ta je bil oče vseh, ki se pečajo s strunami in piščalmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 22, 'Zila pa tudi rodi Tubalkajna, ki je bil kovač vsakršnega ostrega orodja iz brona in železa. In sestra Tubalkajnova je bila Naema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 23, 'In Lameh je dejal ženama svojima: O Ada in Zila, čujta glas moj, ženi Lamehovi, poslušajta govor moj: Res, moža sem ubil za rano svojo in mladeniča za bulo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 24, 'Ako je sedemkrat maščevati Kajna, Lameha bo sedemdesetkrat in sedemkrat!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 25, 'Spozna pa Adam zopet ženo svojo, in rodila je sina in ga je imenovala Seta: Kajti, reče, povrnil mi je Bog seme drugo za Abela, ker ga je Kajn ubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 4, 26, 'In tudi Setu se je rodil sin in imenoval je ime njegovo Enos. Tedaj so začeli klicati ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 1, 'To je knjiga rodov Adamovih. Tisti dan, ko je Bog ustvaril človeka, po svoji podobi ga je naredil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 2, 'moža in ženo ju je ustvaril, in blagoslovil ju je ter ju imenoval Adam tisti dan, ko sta bila ustvarjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 3, 'Adam pa je živel trideset in sto let in rodil sina po svoji podobi, po svoji sličnosti, in ga je imenoval Seta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 4, 'In bilo je dni Adamovih, potem ko je rodil Seta, osemsto let, in rodil je sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 5, 'In vseh dni, kar jih je živel Adam, je bilo devetsto trideset let; in umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 6, 'Set pa je živel sto in pet let in rodil Enosa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 7, 'In Set je živel, potem ko je rodil Enosa, osemsto sedem let, in rodil je sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 8, 'In bilo je vseh dni Setovih devetsto dvanajst let; in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 9, 'Živel pa je Enos devetdeset let in rodil Kenana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 10, 'In živel je Enos, rodivši Kenana, še osemsto petnajst let, in rodil je sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 11, 'In bilo je vseh dni Enosovih devetsto pet let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 12, 'Živel pa je Kenan sedemdeset let, ko je rodil Mahalalela;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 13, 'in živel je Kenan, rodivši Mahalalela, osemsto štirideset let in rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 14, 'tako je bilo vseh dni Kenanovih devetsto deset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 15, 'Živel pa je Mahalalel petinšestdeset let, ko je rodil Jareda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 16, 'in živel je Mahalalel, rodivši Jareda, osemsto trideset let in rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 17, 'tako je bilo vseh dni Mahalalelovih osemsto petindevetdeset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 18, 'Živel pa je Jared sto dvainšestdeset let, ko je rodil Enoha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 19, 'in živel je Jared, rodivši Enoha, osemsto let in rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 20, 'tako je bilo vseh dni Jaredovih devetsto dvainšestdeset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 21, 'Živel pa je Enoh petinšestdeset let, ko je rodil Metuselaha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 22, 'in Enoh je hodil neprestano z Bogom, potem ko je rodil Metuselaha, tristo let, v katerih je rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 23, 'in bilo je vseh dni Enohovih tristo petinšestdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 24, 'In Enoh je neprestano hodil z Bogom, in ni ga bilo več, ker ga je Bog vzel k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 25, 'Živel pa je Metuselah sto sedeminosemdeset let, ko je rodil Lameha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 26, 'in živel je Metuselah, rodivši Lameha, sedemsto dvainosemdeset let in rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 27, 'tako je bilo vseh dni Metuselahovih devetsto devetinšestdeset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 28, 'Živel pa je Lameh sto dvainosemdeset let, ko je rodil sina;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 29, 'in mu je dal ime Noe, rekoč: Ta nas bo tolažil ob delu našem in ob trudu naših rok, ki nam ga prizadeva zemlja, katero je proklel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 30, 'In živel je Lameh, rodivši Noeta, petsto petindevetdeset let in rodil sinove in hčere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 31, 'in bilo je vseh dni Lamehovih sedemsto sedeminsedemdeset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 5, 32, 'Ko je pa imel Noe petsto let, rodi Sema, Hama in Jafeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 1, 'Zgodilo se je pa, ko so jeli množiti se ljudje na površju zemlje in so se jim rodile hčere,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 2, 'da so videli sinovi Božji hčere človeške, da so lepe, in so si jemali od vsakršnih žene, katerekoli so si izbrali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 3, 'Zatorej reče Gospod: Duh moj se ne bo prepiral s človekom vekomaj, ker on je tudi le meso; zato bodi dni njegovih sto in dvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 4, 'Velikani so bili na zemlji tiste dni in tudi pozneje, ko so se sinovi Božji shajali s hčerami človeškimi in so jim rodile. To so tisti junaki, ki so bili v starodavnem času, možje preslavni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 5, 'Ko je torej videl Gospod, da se množi hudobnost človekova na zemlji, in da so vsi naklepi in misli srca njegovega samo hudo ves čas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 6, 'je bilo žal Gospodu, da je naredil človeka na zemlji, in bolelo ga je v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 7, 'In reče Gospod: Potrebil bom človeka, ki sem ga ustvaril, s površja zemlje; i človeka i živino in laznino in ptice pod nebom, ker žal mi je, da sem jih naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 8, 'Ali Noe je našel milost v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 9, 'To so rodovi Noetovi. Noe je bil mož pravičen, popoln med vrstniki svojimi; z Bogom je hodil Noe neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 10, 'Rodil je pa Noe tri sinove: Sema, Hama in Jafeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 11, 'In zemlja je bila popačena pred obličjem Božjim, in zemlja je bila napolnjena s silovitostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 12, 'In Bog je videl zemljo, in glej, popačena je bila, kajti vse meso je popačilo pot svojo na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 13, 'In reče Bog Noetu: Konec vsega mesa se je približal predme, zakaj zemlja je polna silovitosti od njih; zato, glej, pokončal jih bom z zemljo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 14, 'Naredi si ladjo iz lesa gofrovega; predele mnoge naredi v ladji, in zasmoli jo znotraj in zunaj s smolo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 15, 'In takó jo naredi: Tristo komolcev dolžava ladje, petdeset komolcev širjava njena in trideset komolcev njena višava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 16, 'Napravi ladji odprtino za luč, ki naj seže do komolca od vrha, in vrata ladji umesti na strani njeni, s spodnjim, drugim in tretjim nadstropjem jo naredi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 17, 'In jaz, glej, pošljem potop, vode čez zemljo, pogubit vse meso, v katerem je dih življenja pod nebom; karkoli je na zemlji, pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 18, 'S teboj pa ustanovim zavezo svojo, in pojdeš v ladjo, ti in sinovi tvoji in žena tvoja in žene sinov tvojih s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 19, 'In od vsega, kar živi, od vsakršnega mesa, od vsega po dvoje vzemi v ladjo, da jih pri življenju ohraniš s seboj: samec in samica naj bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 20, 'Izmed ptic po njih plemenih in izmed živine po plemenih njenih, izmed vse laznine zemeljske po vrstah njenih, izmed vseh po dvoje naj pride k tebi, da jih ohraniš pri življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 21, 'Ti pa si vzemi od vsake jedi, ki se jé, in vzeto spravi pri sebi, da bode tebi in njim v živež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 6, 22, 'To stori Noe; vse stori prav tako, kakor mu je zapovedal Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 1, 'Potem reče Gospod Noetu: Pojdi ti in vsa družina tvoja v ladjo, zakaj tebe sem videl pravičnega pred seboj v tem rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 2, 'Izmed vseh čistih živali si vzemi po sedmero, samca in samico njegovo; izmed zveri pa, ki niso čiste, po dvoje, samca in samico njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 3, 'tudi od ptic pod nebom po sedmero, samca in samico, da se ohrani pri življenju seme na površju vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 4, 'Zakaj še sedem dni, in jaz spustim dež na zemljo štirideset dni in štirideset noči, in pokončam s površja zemlje vsako bitje, ki sem ga naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 5, 'In Noe stori vse, kakor mu je zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 6, 'Noe pa je imel šeststo let, ko je bil tisti potop in so vode stopile čez zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 7, 'In Noe vstopi in sinovi njegovi in žena njegova in žene sinov njegovih ž njim v ladjo, pred vodami potopa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 8, 'Izmed živali čistih in izmed zveri, ki niso čiste, in izmed ptic in izmed vsega, kar lazi po suhem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 9, 'je šlo po dvoje k Noetu v ladjo, samec in samica, kakor je bil Noetu zapovedal Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 10, 'Zgodi se pa po sedmih dnevih, da pridero vode potopa čez zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 11, 'Ko je imel Noe šeststo let svojega življenja, v drugem mesecu, sedemnajsti dan meseca, prav ta dan se razkoljejo vsi studenci brezna vélikega in zatvornice neba se odpro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 12, 'In lil je dež na zemljo štirideset dni in štirideset noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 13, 'Prav tisti dan je šel Noe in Sem in Ham in Jafet, sinovi Noetovi, in žena Noetova in tri žene sinov njegovih ž njimi v ladjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 14, 'oni in vsaktera zver po plemenu svojem in vsaktera živina po plemenu svojem in vsaktera laznina, ki se giblje na zemlji, po vrsti svoji, in vsaktera letavina po plemenu svojem, vsi ptiči katerekoli peroti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 15, 'In prišli so k Noetu v ladjo po dvoje iz vsega mesa, v katerem je bil dih življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 16, 'In kar jih je šlo noter, šla sta samec in samica iz vsega mesa, kakor mu je bil zapovedal Bog; in Gospod je zaprl za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 17, 'In bil je potop štirideset dni po zemlji, in narasle so vode, da so vzdignile ladjo, in vzdigovala se je od zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 18, 'In vode so kipele ter silno rasle nad zemljo, in ladja je plavala po površju vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 19, 'In kipele so vode presilno nad zemljo in pokrile so vse gore visoke, ki so pod vsem nebom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 20, 'Petnajst komolcev kvišku so skipele vode, in gore so bile pokrite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 21, 'Poginilo je torej vse meso, ki se je gibalo na zemlji, kar je bilo ptic in živali in zveri in vse laznine, ki je lazila po zemlji, in vsak človek:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 22, 'vse, kar je imelo v nosnicah dih duha življenja, vse, kar je bilo na suhem, je pomrlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 23, 'In pokončal je sleherno živo bitje, ki je bilo na površju zemlje: ljudi in živali, laznino in ptice neba, in pokončani so bili z zemlje; in pri življenju je ostal samo Noe in kar je bilo ž njim v ladji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 7, 24, 'Kipele pa so vode nad zemljo sto petdeset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 1, 'Spomni pa se Bog Noeta in vseh zveri in vseh živali, ki so bile ž njim v ladji, in pošlje Bog veter nad zemljo, in vode upadejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 2, 'in zapro se brezna studenci in zatvornice neba, in ustavi se dež z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 3, 'In vode se neprenehoma vračajo s površja zemlje in se manjšajo, odkar je minilo stoinpetdeset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 4, 'In ladja je obstala sedmi mesec, sedemnajsti dan meseca na gorovju Araratskem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 5, 'In vode so vedno bolj upadale do desetega meseca: deseti mesec, prvi dan meseca se pokažejo vrhovi gorá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 6, 'In zgodi se, ko je minilo štirideset dni, da Noe odpre okno na ladji, ki ga je bil naredil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 7, 'in izpusti vrana; ta je letal semtertja, dokler se niso posušile vode na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 8, 'In izpusti goloba od sebe, da bi videl, so li že izginile vode s površja zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 9, 'Ali golob ni našel mesta stopalu noge svoje, in vrne se v ladjo k njemu, ker so bile še vode na površju zemlje. Noe pa iztegne roko svojo, ga prime in vzame k sebi v ladjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 10, 'Počaka torej še drugih sedem dni, in zopet izpusti goloba iz ladje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 11, 'In prileti k njemu golob o času večernem, in glej, mlado pero oljkovo v kljunu njegovem; in spozna Noe, da je zemlja vodovja prosta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 12, 'In počaka še drugih sedem dni in izpusti goloba, a ni se več vrnil k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 13, 'In bilo je v šeststo in prvem letu, prvi mesec, prvi dan meseca, ko so se posušile vode s površja zemlje, da je Noe odkril streho ladje in se oziral, in glej, posušena je površina zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 14, 'Drugi mesec pa, sedemindvajseti dan meseca je bila zemlja suha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 15, 'Tedaj zapove Bog Noetu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 16, 'Izidi iz ladje, ti in žena tvoja in sinovi tvoji in žene sinov tvojih s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 17, 'Vse živali, ki so s teboj, od vsakršnega mesa, kar jih je ptic in živine in vse laznine, ki lazi po zemlji, izpelji s seboj, da naj obilo rodé na zemlji, rodovitne naj bodo in se množé po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 18, 'Izide torej Noe in sinovi njegovi in žena njegova in žene sinov njegovih ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 19, 'Vse živali, vsa laznina in vse ptice, karkoli se giblje na zemlji, po rodovih svojih pridejo ven iz ladje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 20, 'Potem zgradi Noe oltar Gospodu, in vzame od vse čiste živine in izmed vseh čistih ptic ter daruje žgalen dar na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 21, 'In Gospod zaduha tisti duh prijetni, in reče Gospod v srcu svojem: Ne bodem več proklel zemlje zaradi človeka; zakaj misel srca človekovega je huda od mladosti njegove; in ne udarim več vsega, kar živi, kakor sem storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 8, 22, 'Dokler bode zemlja, ne preneha setev in žetev, ne mraz in vročina, ne leto in zima, ne dan in noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 1, 'Nato blagoslovi Bog Noeta in sinove njegove ter jim reče: Rodovitni bodite in množite se ter napolnite zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 2, 'In strah do vas in trepet pred vami obhajaj vse živali na zemlji in vse ptice pod nebom; vse, karkoli se giblje na suhem, in vse ribe v morju so vam dane v pest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 3, 'Vse, kar se giblje, kar je živega, bodi vam v živež; kakor zelena zelišča sem vam dal vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 4, 'Vendar mesa s krvjo njegovo, ki je duša njegova, ne jejte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 5, 'Saj bom tudi zahteval zadostitev za kri vašo, duš vaših kri, od vsake živali jo bom zahteval in od človeka, od vsakega, kdor umori brata svojega, bom zahteval dušo človekovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 6, 'Kdor prelije kri človekovo, po človeku bodi prelita kri njegova; zakaj po svoji podobi je naredil Bog človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 7, 'Vi torej bodite rodovitni in množite se, rodite obilo na zemlji in množite se po njej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 8, 'In govori Bog Noetu in sinovom njegovim ž njim, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 9, 'Glej, jaz ustanavljam z vami zavezo svojo in z vašim semenom, ki pride za vami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 10, 'in z vsako živo stvarjo, ki je z vami, kar je ptic, živine in vseh zemeljskih živali z vami, z vsem, kar je izšlo iz ladje, in z vsemi zvermi na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 11, 'Ustanavljam torej z vami zavezo svojo, in nikoli več ne bodi pokončano vse meso od vodá potopa, tudi ne bodi več potopa, da pogonobi zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 12, 'In reče Bog: To je znamenje zaveze, ki jo jaz narejam med seboj in vami in vsako živo stvarjo, ki je z vami, za neprenehljive rodove:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 13, 'mavro svojo sem razpel na oblačju, katera bodi v znamenje med menoj in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 14, 'In zgodi se, ko z oblaki prevlečem zemljo in se prikaže mavra na oblačju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 15, 'da se spomnim zaveze svoje, ki je med menoj in vami in vsako živo stvarjo od vsakršnega mesa: in ne bode več vodá v potop, v pokončanje vsega mesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 16, 'Kajti ko bode mavra na oblačju, se ozrem vanjo ter se spomnim večne zaveze med Bogom in vsako živo stvarjo od vsakršnega mesa, ki bode na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 17, 'In reče Bog Noetu: To je znamenje zaveze, ki sem jo ustanovil med seboj in vsem mesom, ki biva na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 18, 'In sinovi Noetovi, ki so izšli iz ladje, so bili: Sem in Ham in Jafet; Ham pa je oče Kanaanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 19, 'Ti trije so bili sinovi Noetovi, in od teh se je naselila vsa zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 20, 'In Noe je začel obdelovati zemljo, in zasadi vinograd;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 21, 'in ko pije od vina njegovega, se upijani ter se razodene sredi šatora svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 22, 'Ham pa, oče Kanaanov, zagleda nagoto očeta svojega ter pove dvema bratoma svojima odzunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 23, 'Sem pa vzame z Jafetom plašč njegov in ga zadeneta na rame svoje in nazaj obrnjena gresta ter pokrijeta ž njim očeta svojega nagoto; in obličje jima je bilo nazaj obrnjeno, da nista videla očeta svojega nagote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 24, 'Ko pa se je prebudil Noe iz vina svojega, zve, kaj mu je bil storil njegov najmlajši sin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 25, 'in reče: Proklet bodi Kanaan; hlapcev hlapec bodi bratom svojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 26, 'Še reče: Hvaljen Gospod, Bog Semov, in Kanaan mu bodi hlapec!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 27, 'Razširi naj Bog Jafeta, in naj prebiva v šatorih Semovih, in Kanaan mu bodi hlapec!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 28, 'Živel pa je Noe po potopu tristo petdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 9, 29, 'In bilo je vseh dni Noetovih devetsto petdeset let, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 1, 'Ti pa so rodovi sinov Noetovih, Sema, Hama in Jafeta; rodili so se jim sinovi po potopu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 2, 'Sinovi Jafetovi: Gomer in Magog in Madai in Javan in Tubal in Mesek in Tiras.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 3, 'In sinovi Gomerjevi: Askenaz in Rifat in Togarma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 4, 'In sinovi Javanovi: Elisa in Tarsis, Kitim in Dodanim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 5, 'Od teh je prišla razdelitev otokov narodov po njih deželah, vsakemu po njegovem jeziku, po njih rodovinah v njih narodih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 6, 'Sinovi Hamovi pa: Kuš in Mizraim in Put in Kanaan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 7, 'In sinovi Kuševi: Seba in Havila in Sabta in Ragma in Sabteka; in sinova Ragma: Šeba in Dedan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 8, 'In Kuš rodi Nimroda; ta je začel mogočen biti na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 9, 'On je bil junak-lovec pred Gospodom; zato je navada govoriti: Kakor Nimrod, junak-lovec pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 10, 'In začetek njegovega kraljestva je bil Babel in Erek in Akad in Kalne v deželi Sinearski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 11, 'Iz te dežele je šel v Asur in je zidal Ninive in Rehobotir in Kalah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 12, 'in Resen med Ninivami in Kalahom; to je véliko mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 13, 'Mizraim pa rodi Ludime, Anamime, Lehabime, Naftuhime,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 14, 'Patrusime in Kasluhime (od katerih so izšli Filistejci) in Kaftorime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 15, 'Kanaan pa je rodil Sidona, prvenca svojega, in Heta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 16, 'tudi Jebusejca, Amorejca in Girgasejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 17, 'Hevejca, Arkejca in Sinejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 18, 'Arvadejca, Zemarejca in Hamatejca; in pozneje so se raztrosile rodovine Kanaanove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 19, 'In bila je meja Kanaancev od Sidona v smeri proti Gerarju do Gaze; v smeri proti Sodomi in Gomori, Adami in Zeboimu do Leše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 20, 'To so sinovi Hamovi po svojih rodovinah, po svojih jezikih, v svojih deželah in narodih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 21, 'Semu pa se tudi rode otroci, očetu vseh sinov Heberjevih, Jafetovemu bratu, starejšemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 22, 'Sinovi Semovi so bili: Elam in Asur in Arpaksad in Lud in Aram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 23, 'In sinovi Aramovi: Uz in Hul in Geter in Maš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 24, 'Arpaksad pa rodi Šelaha, in Šelah rodi Heberja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 25, 'A Heberju se rodita dva sina, enemu je ime Peleg, ker je bila v dneh njegovih razdeljena zemlja, ime bratu njegovemu pa Joktan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 26, 'In Joktan rodi Almodada in Šelefa in Hazarmaveta in Jeraha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 27, 'Hadorama ter Uzala in Dikla,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 28, 'Obala in Abimaela in Šeba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 29, 'Ofirja in Havila in Jobaba; ti so bili vsi sinovi Joktanovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 30, 'In njih prebivališče je bilo od Mese v smeri proti Sefarju, k vzhodnemu gorovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 31, 'Ti so sinovi Semovi po rodovinah svojih, po jezikih svojih, v svojih deželah, po svojih narodih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 10, 32, 'Te so rodovine sinov Noetovih po svojih rodovih v svojih narodih; in od teh so se ločili narodi na zemlji po potopu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 1, 'Bila pa je po vsej zemlji ena govorica, iste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 2, 'Zgodi se pa, ko so potovali od jutra, da so našli ravnino v deželi Sinearski, ter so se nastanili tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 3, 'In rekli so drug drugemu: Dejte, naredimo opeko in jo izžgimo z ognjem! In bila jim je opeka za kamenje in zemeljska smola namesto malte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 4, 'In rekli so: Dejte, zgradimo si mesto in stolp, ki mu vrh bodi do neba, in naredimo si ime, da se morda ne razkropimo po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 5, 'Ali Gospod pride doli pogledat mesto in stolp, ki so ga gradili otroci človeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 6, 'In reče Gospod: Glej, ljudstvo je eno in vsem je edina gvorica, in to je samo začetek njih dela; sedaj pa se jim ne zabrani nič, kar so sklenili storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 7, 'Dejte, pojdimo doli in zmešajmo jim tam njih govorico, da ne bodo umeli drug drugega govorice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 8, 'Tako jih je razkropil Gospod odtod po vsej zemlji, in nehali so graditi tisto mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 9, 'Zato so imenovali ime njegovo Babel, ker je bil tam Gospod zmedel vse zemlje govorico, in odtod jih je Gospod razkropil po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 10, 'To so rodovi Semovi. Sem je imel sto let, ko je rodil Arpaksada, dve leti po potopu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 11, 'in Sem je živel, rodivši Arpaksada, še petsto let in rodil sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 12, 'Arpaksad pa je živel petintrideset let, ko je rodil Šelaha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 13, 'in živel je Arpaksad, rodivši Šelaha, štiristo in tri leta in rodil sine in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 14, 'Šelah pa je živel trideset let, ko je rodil Heberja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 15, 'in živel je Šelah, rodivši Heberja, še štiristo in tri leta in rodil sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 16, 'Heber pa je živel štiriintrideset let, ko je rodil Pelega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 17, 'in živel je Heber, rodivši Pelega, še štiristo trideset let in rodil sine in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 18, 'Peleg pa je živel trideset let, ko je rodil Reguja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 19, 'in živel je Peleg, rodivši Reguja, še dvesto devet let in rodil sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 20, 'Regu pa je živel dvaintrideset let, ko je rodil Seruga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 21, 'in živel je Regu, rodivši Seruga, še dvesto sedem let in rodil sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 22, 'Serug pa je živel trideset let, ko je rodil Nahorja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 23, 'in živel je Serug, rodivši Nahorja, še dvesto let in rodil sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 24, 'Nahor pa je živel devetindvajset let, ko je rodil Teraha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 25, 'in živel je Nahor, rodivši Teraha, še sto devetnajst let in rodil sine in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 26, 'Terah pa je živel sedemdeset let, ko je rodil Abrama, Nahorja in Harana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 27, 'In to so rodovi Terahovi: Terah rodi Abrama, Nahorja in Harana; Haran pa rodi Lota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 28, 'Umrl pa je Haran pred obličjem očeta svojega Teraha v svojem rojstnem kraju, v Uru Kaldejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 29, 'In vzameta si Abram in Nahor ženi; ime ženi Abramovi je bilo Saraj, ime ženi Nahorjevi pa Milka, hči Harana, očeta Milke in Jiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 30, 'In Saraj je bila nerodovitna, imela ni otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 31, 'Vzame pa Terah Abrama, sina svojega, in Lota, sina Haranovega, vnuka svojega, in Sarajo, snaho svojo, ženo Abrama, sina svojega, in odidejo skupaj iz Ura v Kaldejcih popotovat v deželo Kanaansko, ter pridejo do Harana in se nastanijo tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 11, 32, 'In bilo je dni Terahovih dvesto pet let; in umrl je Terah v Haranu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 1, 'In Gospod je rekel Abramu: Pojdi iz dežele svoje in od sorodovine svoje in iz očeta svojega hiše v deželo, ki ti jo pokažem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 2, 'in storil te bom v narod velik in te blagoslovil, in poveličam ime tvoje, in v blagoslov bodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 3, 'In blagoslovil bom nje, ki blagoslavljajo tebe, in kdor te proklinja, njega bom proklel, in blagoslovljene bodo v tebi vse rodovine zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 4, 'In Abram se napoti, kakor mu je bil zapovedal Gospod, in Lot je šel ž njim; imel pa je Abram petinsedemdeset let, ko je potoval iz Harana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 5, 'Vzame namreč Abram Sarajo, ženo svojo, in Lota, sina brata svojega, z vsem premoženjem svojim, katero so pridelali, in z dušami, ki so jih pridobili v Haranu, in odpotujejo, da bi šli v pokrajino Kanaansko. In prišli so v deželo Kanaansko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 6, 'In Abram preide deželo do kraja Sihema, do hrasta Morejevega. Bival je pa tedaj Kanaanec v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 7, 'In Gospod se prikaže Abramu ter reče: Semenu tvojemu hočem dati to deželo. Abram pa postavi tam oltar Gospodu, ki se mu je bil prikazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 8, 'In napoti se odtod v gorovje proti jutranji strani Betela in postavi šator svoj: Betel mu je bil od zahoda in Aj od vzhoda; in postavi tam oltar Gospodu, in klical je ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 9, 'Potem je potoval Abram dalje v južno stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 10, 'Bila pa je lakota v deželi, zatorej gre Abram doli v Egipt, da bi tujčeval ondi, ker huda lakota je bila v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 11, 'In ko je bil že blizu, da pride v Egipt, reče Saraji, ženi svoji: Glej, znam, da si žena lepe postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 12, 'Lahko se zgodi, ko te zagledajo Egipčani in reko: Ta je žena njegova, da me ubijejo, tebe pa ohranijo živo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 13, 'Reci, prosim, da si sestra moja, da mi bo dobro zaradi tebe in da bom živel zavoljo tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 14, 'In zgodi se, ko je prišel Abram v Egipt, da so videli Egipčani ženo, da je silno lepa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 15, 'In videli so jo knezi Faraonovi in so jo hvalili pred Faraonom, in žena je bila vzeta v hišo Faraonovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 16, 'Ta je Abramu dobro storil zaradi nje, tako da je imel ovac ter volov in oslov ter hlapcev in dekel in velblodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 17, 'Ali udari Gospod z velikimi stiskami Faraona in hišo njegovo zaradi Saraje, žene Abramove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 18, 'In pokliče Faraon Abrama ter reče: Kaj si mi to storil? Zakaj mi nisi povedal, da je tá žena tvoja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 19, 'Zakaj si rekel: Sestra je moja? In vzel sem jo, da mi bodi žena. In sedaj, glej, tu imaš ženo svojo, vzemi jo in odidi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 12, 20, 'Tedaj ukaže Faraon zanj možem, ki so ga spremili in ženo njegovo in vse, kar je imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 1, 'Šel je torej Abram iz Egipta, on in žena njegova in vse, kar je imel, tudi Lot ž njim, v južno stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 2, 'Bil je pa Abram silno bogat živine, srebra in zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 3, 'In šel je po svojih potih z južne strani do Betela, tja do kraja, kjer je bil prej šator njegov, med Betelom in Ajem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 4, 'do kraja onega oltarja, ki ga je prej ondi naredil; in tam je klical Abram ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 5, 'A tudi Lot, ki je šel z Abramom, je imel črede ovac in goved in šatore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 6, 'Zato jima je bila pretesna tista pokrajina, da bi skupaj bivala, ker imetja njunega je bilo mnogo, in nista mogla bivati skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 7, 'In bil je prepir med čredniki Abramovimi in čredniki Lotovimi; in Kanaanec in Ferizejec sta bivala tedaj v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 8, 'Reče torej Abram Lotu: Nikar ne bodi prepira med menoj in teboj, med mojimi pastirji in pastirji tvojimi, ker moža brata sva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 9, 'Ni li vsa dežela pred teboj? Loči se, prosim, od mene: če torej na levo, pojdem jaz na desno, če pa na desno, pojdem na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 10, 'In Lot povzdigne oči in vidi vso ravan Jordanovo, da jo je povsod namakala voda, preden je Gospod pokončal Sodomo in Gomoro, kakor vrt Gospodov, kakor deželo Egiptovsko, do tja, kjer se pride v Zoar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 11, 'In izvoli si Lot vso ravan Jordanovo; in napoti se Lot proti jutru, in ločita se drug od drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 12, 'Abram je bival v pokrajini Kanaanski, Lot pa je bival v mestih one ravnine in pomikal prav do Sodome šatore svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 13, 'Sodomljani pa so bili hudobni in veliki grešniki pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 14, 'In Gospod reče Abramu, potem ko se je Lot ločil od njega: Povzdigni sedaj oči ter se ozri s kraja, kjer si, proti severu in proti jugu in proti izhodu in zahodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 15, 'zakaj vso to deželo, ki jo vidiš, hočem dati tebi in semenu tvojemu na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 16, 'In naredim seme tvoje kakor prah zemlje: ako more kdo prah zemlje sešteti, sešteje tudi tvoje seme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 17, 'Vstani, obhodi deželo to po dolgosti njeni in po širokosti, zakaj dati ti jo hočem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 13, 18, 'Premakne torej Abram šatore ter pride in prebiva pri hrastih Mamrejevih, ki so pri Hebronu, in ondi postavi oltar Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 1, 'Zgodi se pa za časov Amrafela, kralja sinearskega, Arjoha, kralja elasarskega, Kedorlaomerja, kralja elamskega, in Tideala, kralja narodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 2, 'da so ti začeli vojsko zoper Bera, kralja v Sodomi, in zoper Birsa, kralja v Gomori, zoper Sineaba, kralja v Adami, in Semeberja, kralja v Seboimu, in zoper kralja v Beli, to je Zoar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 3, 'Vsi ti so šli združeni proti dolini Sidimski, to je sedaj Slano morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 4, 'Dvanajst let so bili služili kralju Kedorlaomerju, v trinajstem letu pa so se uprli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 5, 'In v štirinajstem letu so prišli Kedorlaomer in kralji, ki so bili ž njim, ter so porazili Refaime v Asterot-karnaimu in Zuzime v Hamu in Emime v ravnini pri Kirjataimu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 6, 'in Horejce na njih gorovju Seiru tja do El-parana, ki je poleg puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 7, 'In vrnili so se ter prišli v En-mišpat, ki je Kades, in ugonobili so vso poljano Amalekovcev in tudi Amorejce, ki so prebivali v Hazazontamaru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 8, 'In pride kralj sodomski in kralj gomorski in kralj adamski in kralj seboimski in kralj iz Bele, ki je Zoar, in uredili so se v boj zoper nje v dolini Sidimski:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 9, 'zoper Kedorlaomerja, kralja elamskega, in Tideala, kralja narodov, in Amrafela, kralja sinearskega, in Arjoha, kralja elasarskega: četvero kraljev zoper petero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 10, 'Dolina Sidimska pa je imela mnogo smolnih jam. Kralj sodomski in gomorski pa sta bežala in padla vanje, in kar jih je ostalo, so pobegnili v gorovje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 11, 'In oni so vzeli vse blago iz Sodome in Gomore in ves njih živež ter so odšli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 12, 'Ujeli so pa tudi Lota, sina brata Abramovega, ki je prebival v Sodomi, z blagom njegovim in so odšli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 13, 'In pride eden ubežnikov povedat to Abramu Hebrejcu, ki je bival pri hrastih Mamreja Amorejca, brata Eskolovega in Anerjevega, ki sta bila zaveznika Abramova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 14, 'Ko je torej slišal Abram, da so ujetega odpeljali bratiča njegovega, oboroži domačih hlapcev svojih tristo osemnajst, ki jih je bil izuril, in spusti se za njimi tja do Dana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 15, 'In se razdeli v trume proti njim po noči, on in hlapci njegovi, ter jih premaga in podi do Hobe, ki je na levo od Damaska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 16, 'In pripelje nazaj vse tisto blago in tudi Lota, bratiča svojega, z blagom njegovim privede nazaj in tudi žene in ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 17, 'In izide kralj sodomski Abramu naproti, ko se je vračal s poboja Kedorlaomerja in tistih kraljev, ki so bili ž njim, v dolino Šave, to je Kraljeva dolina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 18, 'Melhizedek pa, kralj v Salemu, prinese kruha in vina; bil je namreč duhovnik Boga mogočnega, Najvišjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 19, 'In blagoslovi ga, govoreč: Blagoslovljen bodi Abram od Boga mogočnega, Najvišjega, Stvarnika nebes in zemlje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 20, 'in hvaljen bodi Bog mogočni, Najvišji, ki je izdal sovražnike tvoje v roko tvojo! In dá mu Abram desetino od vsega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 21, 'In reče kralj sodomski Abramu: Daj mi le duše, blago pa si vzemi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 22, 'Abram pa veli kralju sodomskemu: Povzdigujem roko svojo proti Gospodu, Bogu mogočnemu, Najvišjemu, nebes in zemlje Stvarniku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 23, 'da ne vzamem ne niti, ne jermena, ne ničesar, kar je tvojega, da ne porečeš: Jaz sem obogatil Abrama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 14, 24, 'Meni ničesar! samo kar so pojedli mladeniči, in del teh mož, ki so šli z menoj: Aner, Eskol in Mamre, oni naj vzemo svoj del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 1, 'Po teh dogodkih je prišla beseda Gospodova Abramu v prikazni, rekoč: Ne boj se, Abram, jaz sem ti ščit, plačilo tvoje jako veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 2, 'Pa reče Abram: Gospod Jehova, kaj mi hočeš dati, ker jaz preminem brez otrok, in je on, ki bode posestnik hiše moje, Eliezer Damaščan?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 3, 'Še reče Abram: Glej, meni nisi dal zaroda, in glej, moj domači hlapec bode dedič moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 4, 'A glej, beseda Gospodova mu reče: Ta ne bode dedič tvoj, marveč kateri pride iz osrčja tvojega, on bode dedič tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 5, 'Nato ga pelje na plano in veli: Ozri se zdaj proti nebu in seštej zvezde, če jih moreš sešteti; in mu reče: Tako bode seme tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 6, 'In Abram je veroval Gospodu in on mu je štel to za pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 7, 'In mu reče: Jaz sem Gospod, ki sem te izpeljal iz Ura Kaldejcev, da ti dam to deželo, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 8, 'In ko je rekel Abram: Gospod Jehova, po čem naj spoznam, da jo posedem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 9, 'mu veli: Vzemi zame triletno telico in triletno kozo in triletnega ovna ter grlico in goloba mladiča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 10, 'Abram torej vzame zanj vse to, in ko je vsako žival prerezal po sredi, položi vsake polovico drugi polovici nasproti, ptic pa ni razpolovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 11, 'Ko so pa ptice roparice planile na trupla ta, jih je Abram odganjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 12, 'In ko se je solnce nagibalo, se loti Abrama trdno spanje, in glej, strah in tema velika ga obideta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 13, 'In reče Gospod Abramu: Vedi za gotovo, da bodo potomci tvoji tujci v deželi, ki ni njihna, in jih bodo zasužnjili in jih stiskali štiristo let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 14, 'A tudi narod, ki mu bodo sužnjevali, bom jaz sodil, in potem izidejo z blagom obilnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 15, 'Toda ti odideš k očetom svojim v miru, pokopan boš v lepi starosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 16, 'Oni pa se vrnejo sem v četrtem rodu; zakaj krivica Amorejcev ni dozdaj še dopolnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 17, 'In ko je solnce zatonilo in je bila trda noč, glej: peč kadeča in plamenica goreča, ki gre skozi med onimi deli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 18, 'Ta dan je sklenil Gospod zavezo z Abramom, govoreč: Semenu tvojemu sem dal to deželo od reke Egiptovske do one reke velike, reke Evfrata:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 19, 'Kenejce in Kenizejce ter Kadmonce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 20, 'in Hetejce in Ferizejce ter Refaime,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 15, 21, 'in Amorejce in Kanaance in Girgasejce ter Jebusejce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 1, 'Saraj pa, žena Abramova, mu ni rodila; a imela je deklo egiptovsko, po imenu Agara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 2, 'Reče torej Saraj Abramu: Glej sedaj, Gospod me je zaprl, da ne rodim; pojdi, prosim, k dekli moji, morda dobim otrok iz nje. In Abram je slušal Saraje glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 3, 'In Saraj, žena Abramova, vzame Agaro, egiptovsko deklo svojo, ko je bilo minilo deset let, odkar je Abram bival v deželi Kanaanski, in jo da Abramu, možu svojemu, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 4, 'In Abram je šel k Agari, in spočela je; in ko je videla, da je spočela, je štela gospodinjo svojo spričo sebe za malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 5, 'Zatorej reče Saraj Abramu: Krivica, meni storjena, pada nate: jaz sem dejala deklo svojo v naročje tvoje; ko je pa videla, da je spočela, me je štela spričo sebe za malo. Gospod naj sodi med menoj in teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 6, 'Abram pa reče Saraji: Glej, dekla tvoja je v roki tvoji, stóri ji, kar se ti zdi dobro. Torej jo je poniževala Saraj, in ona je pobegnila izpred obličja njenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 7, 'A najde jo angel Gospodov pri studencu v puščavi, pri tistem studencu, ki je na potu v Sur;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 8, 'ter reče: Agara, dekla Sarajina, odkod si prišla in kam greš? In odgovori: Izpred obličja Saraje, gospodinje svoje, bežim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 9, 'In angel Gospodov ji veli: Vrni se h gospodinji svoji in ponižaj se pod njeno roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 10, 'In reče ji angel Gospodov: Silno pomnožim seme tvoje, da ga ne bode moči šteti od množine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 11, 'In še ji reče angel Gospodov: Glej, ti si noseča, in rodila boš sina; imenuj ga pa Izmaela, zato ker je Gospod zaslišal stisko tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 12, 'On bode človek divjak, roka njegova bo zoper vse in vseh roke zoper njega, in nasproti vsem bratom svojim bo prebival.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 13, 'Tedaj imenuje Agara ime Gospoda, ki je ž njo govoril: Ti si Bog mogočni, ki vidiš; dejala je namreč: Tukaj sem res gledala odzadaj njega, ki me je videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 14, 'Zato se imenuje tisti vodnjak Ber-lahaj-roj, in je med Kadesom in Beredom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 15, 'Rodila je torej Agara Abramu sina; in Abram je imenoval sina svojega, ki ga je Agara rodila, Izmaela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 16, 16, 'Imel je pa Abram šestinosemdeset let, ko mu je Agara rodila Izmaela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 1, 'Ko je pa Abram imel devetindevetdeset let, se prikaže Gospod Abramu ter mu reče: Jaz sem Bog silni, Vsemogočni; neprestano hodi pred menoj in popoln bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 2, 'In zavezo svojo naredim med seboj in teboj in pomnožim te presilno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 3, 'Tedaj pade Abram na obličje svoje, in Bog je govoril ž njim, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 4, 'Jaz sem, glej, zaveza moja je s teboj, in oče bodeš množici narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 5, 'In ne bo se več imenovalo ime tvoje Abram, temuč ime tvoje bodi Abraham, zakaj za očeta množici narodov sem te postavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 6, 'In naredim te rodovitnega presilno, in storim te v narode, in kralji bodo izhajali iz tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 7, 'In ustanovitim zavezo svojo med seboj in teboj in semenom tvojim za teboj po rodovih njegovih, da bo zaveza večna, da sem ti jaz Bog in semenu tvojemu za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 8, 'In dam tebi in semenu tvojemu za teboj deželo tujčevanja tvojega, vso deželo Kanaansko, v večno posest, in bodem jim Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 9, 'In reče Bog Abrahamu: Ti torej hrani zavezo mojo, ti in seme tvoje za teboj po rodovih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 10, 'Ta je zaveza moja med menoj in vami in semenom tvojim za teboj, ki naj jo ohranite: Obrezan vam bodi vsak moški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 11, 'Obrezujte torej meso prednje kožice svoje; to bodi zaveza med menoj in vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 12, 'Osem dni po porodu naj se obreže vsak moški po rodovih vaših, rojen doma ali kupljen z denarjem od katerihkoli tujcev, ki niso iz tvojega semena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 13, 'Vsekakor bodi obrezan i rojeni na domu tvojem i kupljeni z denarjem tvojim: tako bode zaveza moja na vašem mesu za večno zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 14, 'Neobrezan moški pa, ki ne obreže mesa kožice svoje, ta duša bo iztrebljena izmed ljudstva svojega; prelomil je zavezo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 15, 'In Bog reče Abrahamu: Za Sarajo pa, ženo tvojo: ne imenuj je Saraje, ampak Sara ji bodi ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 16, 'Ker blagoslovil jo bom in tudi iz nje ti dam sina; blagoslovil jo bom, da bode mati narodov, kralji ljudstev bodo iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 17, 'Tedaj pade Abraham na obličje svoje in se zasmeje ter pravi v srcu svojem: Bo li sto let staremu se rodil otrok? in Sara, devetdeset let stara, bo li rodila?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 18, 'In reče Abraham Bogu: O da bi le Izmael živel pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 19, 'A Bog veli: Vendar ti pa Sara, žena tvoja, bo rodila sina, in ga imenuj Izaka; in zavezo svojo ustanovitim ž njim, da bodi večna zaveza semenu njegovemu za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 20, 'A tudi za Izmaela sem te uslišal: glej, blagoslovil sem ga, in ga storim rodovitnega in ga pomnožim presilno; dvanajst knezov bo rodil, in naredim ga za očeta velikega naroda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 21, 'Zavezo svojo pa ustanovim z Izakom, ki ti ga bo Sara rodila o ravno tem času ob letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 22, 'In nehal se je pogovarjati ž njim in šel je Bog gori od Abrahama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 23, 'Tedaj vzame Abraham Izmaela, sina svojega, in vse rojene v hiši svoji in kateregakoli je bil kupil z denarjem svojim: vsakega moškega iz domačih svojih, in še isti dan obreže meso njih kožic, kakor je ž njim Bog govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 24, 'Imel pa je Abraham devetindevetdeset let, ko je bilo obrezano meso neobreze njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 25, 'Izmael pa, sin njegov, trinajst let, ko je bilo obrezano meso neobreze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 26, 'Ravno tisti dan sta bila obrezana Abraham in Izmael, sin njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 17, 27, 'In vsi moški hiše njegove, i rojeni doma i kupljeni z denarjem od tujca, so bili obrezani ž njim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 1, 'In prikaže se mu Gospod pri hrastih Mamrejevih, ko je sedel pri vratih šatora svojega ob dnevni vročini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 2, 'In povzdigne oči in pogleda, in glej, trije možje se ustavijo pred njim; ko jih zazre, jim priteče naproti od vrat šatora svojega ter se prikloni do tal');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 3, 'in reče: Gospod moj, če sem našel milost v tvojih očeh, ne pojdi, prosim, mimo svojega hlapca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 4, 'Prineso naj nekoliko vode, in umijte si noge ter počijte pod drevesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 5, 'In prinesem grižljaj kruha in okrepčajte srce svoje; potem pojdete dalje; saj zato ste se namerili mimo svojega hlapca. Oni pa reko: Tako stóri, kakor si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 6, 'Hitel je torej Abraham v šator k Sari in rekel: Hitro zmesi tri merice bele moke in naredi podpepelnikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 7, 'Abraham pa teče h govedi in vzame najboljše tele pri sescu ter ga dá hlapcu, ki ga pripravljat hiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 8, 'Nato vzame masla in mleka in tele, ki ga je pripravil, in položi prednje; in sam je stal poleg njih pod drevesom, in jedli so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 9, 'Ko so mu pa rekli: Kje je Sara, žena tvoja? reče: Glej, v šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 10, 'In reče Gospod: Gotovo se vrnem k tebi, ko zopet pride ta čas, in glej, sina bo imela Sara, žena tvoja. Sara pa je slišala za durmi šatora, ki so bile za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 11, 'Abraham pa in Sara sta bila stara in priletna; nehalo se je bilo Sari goditi po ženski navadi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 12, 'Zato se je smejala Sara, govoreč pri sebi: Ko sem postala starka, bi imela veselje? vrhutega je gospod moj starec!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 13, 'In reče Gospod Abrahamu: Zakaj se pa smeje Sara, govoreč: Ali bi zares rodila, ko sem se postarala?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 14, 'Je li Gospodu kaka stvar nedosežna? Osorej pridem zopet k tebi, ko se ponovi ta čas, in sina bo imela Sara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 15, 'Sara pa je tajila, govoreč: Nisem se smejala, ker se je bala. A ji reče: Nikakor, ampak smejala si se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 16, 'Nato so možje vstali odondod ter so gledali proti Sodomi; Abraham pa je šel ž njimi, da bi jih spremil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 17, 'Reče pa Gospod: Ali bi naj skrival pred Abrahamom, kar nameravam storiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 18, 'Kajti Abraham bode gotovo naroda velikega in mogočnega oče, in vsi narodi zemlje bodo blagoslovljeni v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 19, 'Zakaj spoznal sem ga s tem namenom, da bo zapovedal otrokom svojim in rodbini svoji za seboj, naj se drže pota Gospodovega in strežejo pravičnosti in pravu, da bi izpolnil Gospod Abrahamu, kar mu je obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 20, 'Reče torej Gospod: Vpitje iz Sodome in Gomore je res veliko in njih greh res silno težak;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 21, 'zdaj pa pojdem doli in videl bom, ali so docela tako delali, kakor se glasi njih vpitje, ki je prišlo do mene; če pa ne, bom spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 22, 'In tedaj sta se obrnila onadva in šla proti Sodomi; Abraham pa je stal še pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 23, 'In pristopi Abraham in reče: Boš li tudi pravičnega pokončal s krivičnim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 24, 'Je morda petdeset pravičnih v onem mestu, ali boš vendar pokončal in ne prizanesel kraju zaradi petdesetih pravičnih, ki so v njem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 25, 'Ne bodi tega, da bi kaj takega storil ter v smrt dal pravičnega s krivičnim, da se godi enako pravičnemu kakor krivičnemu. Ne tako! Ali bi vse zemlje Sodnik ne delal po pravici?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 26, 'In reče Gospod: Ako najdem v Sodomi, sredi mesta, petdeset pravičnih, prizanesem vsemu kraju zaradi njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 27, 'Abraham pa odgovori ter reče: Glej, prosim, drznil sem se govoriti h Gospodu, jaz, ki sem prah in pepel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 28, 'morda jih bo onim petdesetim pravičnim manjkalo pet, boš li zaradi teh peterih pokončal vse mesto? In reče: Ne pokončam, ako jih tam najdem petinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 29, 'In zopet ga ogovori in reče: Morda se jih tam najde štirideset. In veli: Ne storim tega zaradi teh štiridesetih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 30, 'In reče: Ne srdi se, prosim, Gospod, in še bom govoril: Morda se jih najde ondi trideset. In veli: Ne storim tega, ako jih najdem ondi trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 31, 'In reče: Glej, prosim, drznil sem se govoriti h Gospodu: Morda se jih najde ondi dvajset. In reče: Ne pogubim zaradi tistih dvajsetih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 32, 'In reče: Ne srdi se, prosim, Gospod, in bom samo še enkrat govoril: Morebiti se jih najde ondi deset. In veli: Ne pokončam zaradi tistih desetih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 18, 33, 'In odide Gospod, ko je nehal govoriti z Abrahamom. Abraham pa se vrne v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 1, 'In ona dva angela sta prišla v Sodomo zvečer, in Lot je sedel pri vratih sodomskih. Ko ju zagleda Lot, vstane in jima gre naproti ter se prikloni ponižno do tal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 2, 'in reče: Glejta, gospoda moja, ustavita se, prosim, v hiši hlapca svojega, ter prenočita in umijta si noge. In zjutraj bosta vstala in šla svojim potem. Ona pa rečeta: Ne, ampak na ulicah bova prenočila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 3, 'Ali ker ju je zelo silil, se ustavita pri njem ter vstopita v hišo njegovo. In napravi jima večerjo ter speče opresnikov, in jedla sta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 4, 'Še nista bila legla, ko obsujejo moški iz mesta, moški sodomski, ono hišo, dečki in starci, vse ljudstvo iz vsega obmestja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 5, 'In klicali so Lota, govoreč mu: Kje sta tista moža, ki sta prišla k tebi nocoj? Pripelji ju ven k nam, da ju spoznamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 6, 'Lot pa izide k njim pred vrata in zapre duri za seboj');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 7, 'in reče: Ne, prosim, bratje, ne delajte zlega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 8, 'Glejte, imam dve hčeri, ki nista še spoznali moža; dejte, da ju pripeljem k vam in storite jima, kakor se vam poljubi. Samo tema možema ne storite nič žalega, ko sta prišla v senco strehe moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 9, 'Tedaj mu reko: Odstopi! In govoré: Ta sam je prišel uživat gostoljubje, pa se neprestano dela sodnika! Zdaj pa storimo več hudega tebi nego njima. In pritiskali so silno v moža, v Lota, in pristopijo, da bi ulomili vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 10, 'Ona moža pa iztegneta roke svoje in potegneta Lota k sebi v hišo in zapreta vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 11, 'A tiste može, ki so bili pri hišnih vratih, udarita s slepoto, od najmanjšega do največjega, tako da so onemogli in niso našli vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 12, 'Tedaj rečeta ona moža Lotu: Koga imaš še tu? zeta ali sine svoje ali hčere svoje, ali kogarkoli imaš v tem mestu, glej, da gredo iz tega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 13, 'Kajti pokončala bova ta kraj, zato ker je veliko njih vpitje pred obličjem Gospodovim, in poslal naju je Gospod ga pogubit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 14, 'Izide torej Lot ter ogovori zeta svoja, ki sta mislila v kratkem vzeti hčeri njegovi, ter reče: Vstanita, pojdita iz tega kraja, kajti Gospod pokonča mesto. Ali zetoma njegovima se je zdelo, kakor da se norčuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 15, 'Ko je pa vzhajala zarja, sta priganjala angela Lota, govoreč: Vstani, vzemi ženo svojo in dve hčeri svoji, ki sta pri tebi, da ne pogineš v kazni tega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 16, 'On pa se je obotavljal. Zato zgrabita ona moža roko njegovo in žene njegove roko in roke dveh hčer njegovih, ker mu je Gospod milostno prizanesel, in ga izpeljeta in ga postavita zunaj mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 17, 'In zgodi se, ko sta jih izpeljala ven, da mu veli: Reši se zaradi duše svoje, ne oziraj se za seboj in ne ustavi se na vseh tej ravnini; otmi se na ono goro, da ne pogineš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 18, 'Lot pa jima odgovori: Ah, ne tako, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 19, 'Glej, prosim, hlapec tvoj je našel milost v tvojih očeh in poveličal si milost svojo, ki si mi jo izkazal, ohranivši mi življenje; jaz pa se ne morem oteti na ono goro, da me ne dohiti zlo in ne umrem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 20, 'Glej, prosim, to mesto! Blizu je, lahko tja zbežim, in prav majhno je: tja naj se, prosim, otmem (ni li prav majhno?), da živi duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 21, 'In mu veli: Glej, ozrl sem se milostno nate tudi v tej stvari, da ne razdenem mesta, za katero si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 22, 'Hiti, otmi se tja, zakaj ničesar ne morem storiti, dokler ne dojdeš tja. Zato se imenuje mesto to Zoar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 23, 'Solnce je vzhajalo nad zemljo, ko je Lot prihajal v Zoar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 24, 'In Gospod je dežil nad Sodomo in Gomoro žveplo in ogenj od Gospoda z neba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 25, 'in pokončal je ta mesta in vso ravnino in vse prebivalce tistih mest in kar je raslo na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 26, 'In žena njegova, gredoča za njim, se je ozrla nazaj, in postala je solnat steber.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 27, 'Zjutraj zgodaj pa vstane Abraham in odide v oni kraj, kjer je prej stal pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 28, 'In pogleda proti Sodomi in Gomori in proti vsej zemlji one ravnine, in videl je, in glej: dim se je vzdigal od zemlje kakor dim apnenice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 29, 'Zgodilo se je torej, ko je Bog pokončaval mesta one ravnine, da se je Bog spomnil Abrahama in odpeljal Lota iz propasti, ko je podiral mesta, v katerih je bival Lot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 30, 'Lot pa je šel gori iz Zoara in prebival je na gori in dve hčeri njegovi ž njim, kajti bal se je bivati v Zoaru; in bival je v neki jami, on in obe hčeri njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 31, 'Reče pa prvenka mlajši: Oče najin je star, in v tej pokrajini ni moža, ki bi se združil z nama po navadi vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 32, 'Dej, dajva piti svojemu očetu vina in leziva ž njim, da v življenju ohraniva iz svojega očeta seme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 33, 'Dali sta torej očetu svojemu piti vina tisto noč, in pride prvenka ter je ležala z očetom svojim, in on ni zaznal, ne ko je legla, ne ko je vstala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 34, 'In drugi dan reče prvenka mlajši: Glej, ležala sem preteklo noč z očetom svojim; dajva mu piti vina tudi nocoj, potem pridi, lezi ž njim, da ohraniva iz očeta svojega seme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 35, 'Dali sta torej tudi tisto noč piti vina očetu svojemu; mlajša pa vstane ter je ležala ž njim, in on ni zaznal, ne ko je legla, ne ko je vstala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 36, 'Tako sta spočeli obe hčeri Lotovi iz očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 37, 'In rodila je prvenka sina in ga imenovala Moaba: on je oče Moabcev do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 19, 38, 'In tudi mlajša je rodila sina in mu je dala ime Ben-ami: on je oče sinov Amonovih do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 1, 'Šel pa je Abraham odondod v južno pokrajino, da bi prebival med Kadesom in Surom; in bival je kot tujec v Gerarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 2, 'In Abraham je rekel za Saro, ženo svojo: Sestra je moja. In Abimelek, kralj gerarski, pošlje ter vzame Saro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 3, 'Ali pride Bog k Abimeleku v nočnih sanjah in mu reče: Glej, takoj umreš zaradi te žene, ki si jo vzel, ker je možu poročena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 4, 'Abimelek pa se ji ni bil približal, zato reče: Gospod, ali bi pomoril tudi narod pravičen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 5, 'Ni li mi rekel sam: Sestra je moja? pa tudi ona je rekla: Brat je moj. V nedolžnosti srca svojega in v čistosti rok svojih sem storil to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 6, 'In mu reče Bog v sanjah: Saj jaz vem, da si storil to v nedolžnosti srca svojega, in tudi ubranil sem ti jaz, da nisi grešil zoper mene, zato ti nisem pustil dotekniti se je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 7, 'Zdaj torej vrni ženo onemu možu; prorok namreč je, in bo prosil zate, in živel boš; ako pa je ne vrneš, vedi, da vsekakor umreš, ti in vsi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 8, 'Zjutraj torej vstane Abimelek prav zgodaj, in ko je poklical vse hlapce svoje, jim pove vse te besede, da so slišali; in silno so se bali tisti možje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 9, 'Nato pokliče Abimelek Abrahama ter mu reče: Kaj si nam storil? Ali kaj sem grešil zoper tebe, da si pripravil nadme in nad kraljestvo moje veliko pregreho? Dela, katerih ni storiti, si storil zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 10, 'Še reče Abimelek Abrahamu: Kaj se ti je zdelo, ko si storil to reč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 11, 'Abraham pa reče: Ker sem dejal, da gotovo ni strahu Božjega v tem kraju, zato me bodo umorili zaradi žene moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 12, 'Ali tudi v resnici je sestra moja, očeta mojega hči, a ne hči matere moje; in vzel sem si jo za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 13, 'Bilo pa je, ko mi je velel Bog potovati iz hiše očeta mojega v daljavo, da sem ji rekel: Ta bodi prijaznost, ki mi jo izkazuj, v kateri kraj koli pridemo, da rečeš zame: Brat je moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 14, 'Tedaj vzame Abimelek ovce in goveda in hlapce in dekle, ter jih da Abrahamu in mu vrne Saro, ženo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 15, 'In mu veli Abimelek: Glej, dežela moja ti je na voljo; kjerkoli se ti poljubi, bivaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 16, 'Sari pa reče: Glej, dal sem tisoč srebrnikov bratu tvojemu, glej, to ti bodi v pregrinjalo oči pri vseh, ki so s teboj, in pred vsemi si opravičena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 17, 'In Abraham je molil k Bogu, in Bog ozdravi Abimeleka in ženo njegovo in dekle njegove, da so rodile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 20, 18, 'Bil je namreč dočista zaprl Gospod vsako maternico v hiši Abimelekovi zaradi Sare, žene Abrahamove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 1, 'In Gospod je obiskal Saro, kakor je bil rekel, in storil je Gospod Sari, kakor je bil govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 2, 'Spočne namreč in porodi Sara Abrahamu sina, v starosti njegovi, v določeni čas, ki ga je bil povedal Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 3, 'In Abraham je imenoval sina svojega, ki se mu je rodil, ki mu ga je porodila Sara, Izaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 4, 'In obreže Abraham Izaka, sina svojega, ko je imel osem dni, kakor mu je bil zapovedal Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 5, 'Imel je pa Abraham sto let, ko se mu je rodil Izak, sin njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 6, 'In Sara reče: Smeh mi je napravil Bog; kdorkoli bo slišal, smejal se bo z menoj vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 7, 'Še reče: Kdo bi bil rekel Abrahamu: Dojila bo otroke Sara! in vendar sem porodila sina v starosti njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 8, 'In dete je raslo in je bilo odstavljeno; in Abraham napravi pojedino veliko v dan, ko je bil Izak odstavljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 9, 'In Sara je videla sina Agare Egipčanke, ki ga je bila rodila Abrahamu, da se posmehuje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 10, 'in reče Abrahamu: Spódi to deklo in njenega sina; kajti sin te dekle ne bode dedič s sinom mojim, z Izakom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 11, 'To pa se je silno hudo videlo Abrahamu zaradi sina njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 12, 'A Bog veli Abrahamu: Ne zdi naj se ti hudo zaradi dečka in zaradi dekle tvoje; karkoli ti poreče Sara, poslušaj glas njen; zakaj v Izaku se ti bo imenovalo seme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 13, 'Pa tudi sina te dekle razmnožim v narod, ker je seme tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 14, 'Abraham torej vstane zgodaj tisto jutro, vzame kruha in meh vode ter izroči Agari in naloži na njeno ramo, in tudi dečka, pa jo odpravi. Šla je torej in tavala po puščavi Bersabejski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 15, 'Ko pa ji je pošla voda iz meha, odloži dečka pod grmovje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 16, 'In umakne se strani ter mu sede nasproti, tako daleč, kakor nese lok; dejala je namreč: Naj ne vidim, ko bo umiral deček. In njemu nasproti sedeč, je jokala naglas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 17, 'Slišal pa je Bog dečkov jok, in zakliče angel Božji Agari z neba ter ji reče: Kaj ti je, Agara? Ne boj se; zakaj Bog je čul dečkov glas tam, kjer je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 18, 'Vstani, dvigni dečka in ga primi z roko svojo; kajti naredim ga za očeta naroda velikega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 19, 'Tedaj odpre Bog oči njene, da vidi studenec; in gre in napolni meh svoj z vodo in da dečku piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 20, 'In Bog je bil z dečkom, da je odrastel; bival pa je v puščavi in bil strelec z lokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 21, 'In živel je v puščavi Paranski, in mati mu je dobila ženo iz Egiptovske dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 22, 'Zgodi se pa v tistem času, da ogovori Abimelek in Pikol, poveljnik vojske njegove, Abrahama, rekoč: Bog je s teboj v vsem, kar počenjaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 23, 'Zdaj torej mi prisezi pri Bogu tukaj, da se mi ne bodeš lagal, ne sinu mojemu, ne vnuku mojemu, temuč da boš izkazoval enako prijaznost, kakršno sem izkazal jaz tebi, meni in deželi, v kateri gostuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 24, 'In Abraham reče: Jaz prisežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 25, 'Grajal pa je Abraham Abimeleka zaradi vodnjaka, ki so se ga bili siloma polastili hlapci Abimelekovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 26, 'Abimelek pa reče: Ne vem, kdo je to storil, dá, tudi ti mi nisi povedal, niti jaz nisem slišal o tem, razen danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 27, 'In Abraham vzame čred in goved ter jih da Abimeleku; in obadva skleneta zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 28, 'Postavil pa je bil Abraham sedem mladih ovac od črede posebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 29, 'Zato reče Abimelek Abrahamu: Čemu tistih sedem mladih ovac, ki si jih postavil posebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 30, 'In on reče: Teh sedem mladih ovac prejmeš iz roke moje, in to mi bodi za pričevalo, da sem jaz izkopal ta vodnjak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 31, 'Zato je imenoval tisti kraj Bersebo, ker sta tam prisegla oba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 32, 'In tako sta sklenila zavezo pri Bersebi; in vstane Abimelek in Pikol, poveljnik vojske njegove, ter se vrneta v pokrajino Filistejsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 33, 'Abraham pa zasadi tamarisko pri Bersebi, in klical je tam ime Gospoda, večnega Boga mogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 21, 34, 'In bival je kot tujec v deželi Filistejcev mnogo dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 1, 'Zgodi se pa po teh dogodkih, da je Bog izkušal Abrahama, in mu reče: Abraham! On pa odgovori: Glej, tu sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 2, 'In mu veli: Vzemi sedaj sina svojega, edinca svojega, ki ga ljubiš, Izaka, in pojdi v deželo Morijo, ter daruj mi ga tam v žgalno daritev vrhu ene onih gor, ki ti jo bom povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 3, 'Vstane torej Abraham zgodaj tisto jutro, osedla osla svojega ter vzame dva hlapcev svojih s seboj in Izaka, sinu svojega. In nakolje drv za žgalno daritev, vstane ter odrine v kraj, o katerem mu je bil Bog povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 4, 'Tretji dan povzdigne Abraham oči in ugleda tisti kraj oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 5, 'In Abraham zapove hlapcema: Ostanita tukaj z oslom, jaz pa in deček pojdeva do tja, in ko odmoliva, se vrneva k vama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 6, 'In Abraham vzame drva za žgalno daritev, jih naloži Izaku, sinu svojemu, v roko svojo pa vzame ogenj in nož; tako sta šla oba skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 7, 'Ogovori pa Izak Abrahama, očeta svojega, in reče: Oče moj! On veli: Tu sem, sin moj! In reče: Glej, ogenj in drva, a kje je jagnje za žgalno daritev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 8, 'Abraham pa reče: Bog si preskrbi jagnje za žgalno daritev, sin moj. In tako sta šla oba skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 9, 'Ko sta pa prišla na tisti kraj, ki mu ga je bil povedal Bog, postavi ondi Abraham oltar ter razloži drva, in zveže Izaka, sina svojega ter ga položi na oltar nad drva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 10, 'In iztegne Abraham roko svojo in prime za nož, da bi zaklal sina svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 11, 'Ali angel Gospodov mu zakliče z neba ter reče: Abraham, Abraham! On pa reče: Tu sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 12, 'In veli: Ne iztezaj roke svoje na dečka in nič mu ne stori: kajti sedaj sem spoznal, da se bojiš Boga, ker mi nisi odrekel sinú svojega, edinca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 13, 'In Abraham povzdigne oči in pogleda, in glej, oven je za njim, z rogovi zapleten v trnje. Šel je torej Abraham ter vzel ovna in ga daroval v žgalno daritev namesto sina svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 14, 'Zato je imenoval Abraham tisti kraj Jehova jire, odtod se govori do dandanes: Na gori Gospodovi se preskrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 15, 'In zakliče angel Gospodov Abrahamu vdrugič z neba');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 16, 'in reče: Pri sebi samem prisegam, govori Gospod: Ker si to storil in mi nisi odrekel sinu svojega, edinca svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 17, 'te bom obiloma blagoslovil in silno pomnožil seme tvoje, kakor zvezde na nebu in kakor pesek ob morskem obrežju, in seme tvoje bo v last imelo vrata sovražnikov svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 18, 'in blagoslovljeni bodo vsi narodi zemlje v semenu tvojem, ker si poslušal moj glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 19, 'In Abraham se vrne k hlapcema, in vstanejo ter gredo skupaj v Bersebo. In bival je Abraham v Bersebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 20, 'In zgodi se po teh dogodkih, da so sporočili Abrahamu: Glej, porodila je tudi Milka sinove Nahorju, bratu tvojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 21, 'Uza, prvenca njegovega, in Buza, brata njegovega, in Kemuela, očeta Aramovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 22, 'in Keseda in Hazona in Pildasa in Jidlafa in Betuela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 23, 'Betuel pa je rodil Rebeko; teh osem je porodila Milka Nahorju, Abrahamovemu bratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 22, 24, 'Priležnica pa njegova, ki ji je ime Reuma, je tudi rodila Tebaha in Gahama in Tahasa in Maaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 1, 'Bilo je pa Sarinega življenja sto sedemindvajset let; to so leta Sarinega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 2, 'In umrla je Sara v Kirjat-arbi (ki je zdaj Hebron) v deželi Kanaanski; in prišel je Abraham žalovat zaradi Sare in jokat po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 3, 'Vstane pa Abraham izpred obličja mrliča svojega ter ogovori sinove Hetove, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 4, 'Tujec sem in priseljenec pri vas; dajte mi posest groba pri vas, da pokopljem mrliča svojega izpred obličja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 5, 'Odgovore pa sinovi Hetovi Abrahamu in mu reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 6, 'Poslušaj nas, gospod; knez Božji si ti med nami: v najlepšem grobov naših pokoplji mrliča svojega; nihče izmed nas ti ne zapre groba svojega, da bi ne pokopal svojega mrliča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 7, 'Tedaj vstane Abraham ter se prikloni pred ljudstvom tiste pokrajine, pred sinovi Hetovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 8, 'In govoril je ž njimi takole: Če vas je volja, da pokopljem mrliča svojega izpred obličja svojega, poslušajte me ter govorite zame Efronu, sinu Zoharjevemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 9, 'naj mi da jamo Makpelo, ki jo ima ob koncu njive svoje; za pravičen denar naj mi jo da med vami v groba posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 10, 'Efron pa je sedel med sinovi Hetovimi. Odgovori pa Efron Hetejec Abrahamu vpričo sinov Hetovih, vpričo vseh, ki so prihajali v vrata mesta njegovega, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 11, 'Nikakor, gospod moj! Poslušaj me. Dam ti ono njivo, in jamo, ki je na njej, ti dam, vpričo rojakov svojih ti jo dam: pokoplji mrliča svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 12, 'Tedaj se prikloni Abraham pred ljudstvom tiste pokrajine');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 13, 'ter ogovori Efrona vpričo ljudstva pokrajine, rekoč: O da bi me vendarle poslušal! izplačam vrednost te njive v denarju, le vzemi od mene; potem pokopljem ondi mrliča svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 14, 'Odgovori pa Efron Abrahamu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 15, 'Gospod moj, poslušaj me! Zemlja za štiristo seklov, kaj je to med menoj in teboj? Torej le pokoplji mrliča svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 16, 'Slušal je torej Abraham Efrona; in Abraham odtehta Efronu denar, ki ga je bil povedal vpričo sinov Hetovih, štiristo seklov srebra, veljavnih pri vsakem kupcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 17, 'Tako je bila njiva Efronova ob Makpeli, ki je nasproti Mamri, njiva z jamo, ki je na njej, in z vsem drevjem, ki je bilo na njivi, kar je bilo v njenih mejah okrog in okrog, potrjena');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 18, 'Abrahamu v posest vpričo sinov Hetovih, vseh, ki so prihajali v vrata mesta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 19, 'Nato šele pokoplje Abraham Saro, ženo svojo, v jamo na njivi Makpeli, Mamri nasproti (ki je Hebron) v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 23, 20, 'In tista njiva in jama na njej je bila potrjena Abrahamu v groba posest od sinov Hetovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 1, 'Abraham pa je bil starček prileten, in Gospod je bil blagoslovil Abrahama v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 2, 'In veli Abraham hlapcu svojemu, najstarejšemu hiše svoje, ki je bil nad vsem, kar je bilo njegovega: Položi, prosim, roko svojo pod ledje moje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 3, 'da te zavežem s prisego pri Gospodu, Bogu nebes in Bogu zemlje, da ne vzameš žene sinu mojemu izmed hčer Kanaancev, med katerimi bivam;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 4, 'ampak da pojdeš v mojo deželo in k sorodovini moji in vzameš ženo sinu mojemu Izaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 5, 'A hlapec mu reče: Morda ne bo hotela tista ženska iti z menoj v to deželo; ali naj popeljem sina tvojega nazaj v ono deželo, odkoder si prišel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 6, 'Abraham pa mu reče: Varuj se, da ne popelješ nazaj tja sina mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 7, 'Gospod, Bog nebes, ki me je vzel iz hiše očeta mojega in iz rojstne dežele moje in ki mi je govoril in ki mi je prisegel, govoreč: Semenu tvojemu dam to deželo, on pošlje angela svojega pred teboj, da vzameš odondod ženo mojemu sinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 8, 'Ako bi pa ženska ne hotela iti s teboj, bodeš prost te zarotitve moje; samo sina mojega ne vodi tja nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 9, 'Hlapec torej položi roko svojo pod ledje Abrahama, gospodarja svojega, in mu priseže za to reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 10, 'Nato vzame hlapec deset izmed velblodov gospoda svojega, da odpotuje; in imel je vsakršno blago gospodarja svojega v roki svoji; in vstane in odpotuje v Mezopotamijo, v mesto Nahorjevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 11, 'In ustavil se je z velblodi zunaj mesta zraven vodnjaka ob večernem času, ko hodijo ženske vodo zajemat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 12, 'In reče: O Gospod, Bog Abrahama, gospoda mojega, stóri, prosim, da se mi posreči danes, in izkaži milost gospodu mojemu Abrahamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 13, 'Glej, stojim pri studencu, in hčere prebivalcev tega mesta bodo hodile vodo zajemat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 14, 'Zgodi se naj, ko porečem kateri deklici: Nagni mi, prosim, vrč svoj, da pijem; in ona odgovori: Pij, pa še velblodom tvojim bom dala piti, da bode ta, ki si jo določil hlapcu svojemu Izaku, in po tem spoznam, da izkazuješ milost gospodu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 15, 'Zgodi se pa, še preden je dogovoril, da pride, glej, Rebeka, ki se je bila rodila Betuelu, sinu Milke, žene Nahorja, brata Abrahamovega, z vrčem svojim na rami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 16, 'Deklica ta pa je bila silno lepe postave, devica, ki je mož ni bil spoznal. In ona gre doli k studencu, napolni vrč in stopa gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 17, 'Priteče ji torej hlapec naproti in reče: Daj mi, prosim, malo piti iz svojega vrča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 18, 'In ona reče: Pij, gospod moj! In urno izpusti vrč čez roko svojo in mu da piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 19, 'In ko mu je dala piti, reče: Tudi velblodom tvojim zajmem, dokler se ne napojé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 20, 'In urno izprazni vrč v korito in zopet hiti k vodnjaku zajemat, in zajme vsem velblodom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 21, 'In mož jo strmé opazuje in molči, da bi spoznal, ali je srečno storil Gospod pot njegovo ali ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 22, 'Zgodi se pa, ko so se velblodi napili, da izloži mož zlat obodec, ki mu je bilo teže pol sekla, in za roke njene dve zapestnici, katerih teža je bila deset seklov zlata,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 23, 'in veli: Čigava hči si? povej mi, prosim. Je li v hiši očeta tvojega nam za prenočišče prostora?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 24, 'In ona mu reče: Hči sem Betuela, sina Milkinega, ki ga je porodila Nahorju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 25, 'Reče mu še: Tudi slame in krme je dosti pri nas, pa tudi za prenočišče prostora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 26, 'Tedaj se mož prikloni in moli Gospoda');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 27, 'ter reče: Hvaljen bodi Gospod, Bog gospoda mojega Abrahama, ki ni opustil milosti in zvestobe svoje do gospodarja mojega; mene je spremil Gospod na potu v hišo sorodnikov gospodarja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 28, 'Poteče torej deklica in sporoči vse to v hiši matere svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 29, 'Rebeka pa je imela brata, ki mu je bilo ime Laban; in Laban poteče k tistemu možu ven k studencu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 30, 'To pa se je zgodilo, ko je videl obodec in zapestnici okoli rok sestre svoje in ko je slišal besede Rebeke, sestre svoje, govoreče: Tako mi je govoril tisti mož. Pride torej k možu, ki je, glej, stal pri velblodih poleg studenca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 31, 'In reče: Pridi noter, blagoslovljenec Gospodov, kaj bi stal zunaj? saj sem pripravil hišo, in prostora je velblodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 32, 'In mož pride v hišo. In Laban razpravi velblode ter jim da slame in krme, in vode, da se umijejo noge njegove in noge mož, ki so bili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 33, 'Ali ko so mu postavili, da bi jedel, reče: Jedel ne bom nikakor, dokler ne povem svojih reči. In reče Laban: Govóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 34, 'Tedaj reče: Hlapec sem Abrahamov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 35, 'Gospod pa je blagoslovil gospodarja mojega silno, da je postal velik; dal mu je namreč čred in goved, srebra in zlata, hlapcev in dekel, velblodov in oslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 36, 'Vrhutega je rodila Sara, žena gospoda mojega, sina mojemu gospodu, ko se je bila postarala, in gospod mu je dal vse, kar ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 37, 'S prisego pa me je zavezal gospod moj, govoreč: Ne vzemi sinu mojemu žene izmed hčer Kanaancev, v katerih deželi jaz bivam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 38, 'Ampak na dom očeta mojega potuj in k rodovini moji, da vzameš ženo mojemu sinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 39, 'Ko sem pa rekel gospodu svojemu: Morda ona ženska ne bo hotela iti z menoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 40, 'mi reče: Gospod, pred čigar obličjem sem vedno hodil, pošlje angela svojega s teboj, in srečno stori tvojo pot, da vzameš ženo sinu mojemu iz rodovine moje in iz hiše očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 41, 'Tedaj bodeš prost zarotitve moje, ko prideš k rodovini moji; in če ti je ne dado, bodeš oproščen zarotitve moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 42, 'Prišel sem torej danes k studencu in rekel: Gospod, Bog gospoda mojega Abrahama, o, da bi res srečno storil pot mojo, po kateri hodim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 43, 'Glej, pri studencu stojim; zgodi se naj, da devica, ki pride zajemat vodo in ji porečem: Daj mi, prosim, piti malo vode iz svojega vrča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 44, 'in ona mi odgovori: Pij, in tudi velblodom tvojim zajmem, da ona bodi žena, ki jo je Gospod določil sinu gospodarja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 45, 'Še nisem končal govoriti v srcu svojem, ko, glej, izide Rebeka z vrčem svojim na rami in gre doli k studencu in zajme. Rekel pa sem ji: Daj mi piti, prosim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 46, 'Ona urno spusti vrč svoj z rame in reče: Pij, pa še velblodom tvojim bom dala piti. In ko sem se napil, dala je piti tudi velblodom mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 47, 'Zato sem jo vprašal, govoreč: Čigava hči si? In reče: Hči Betuela, sina Nahorjevega, katerega mu je rodila Milka. In del sem ji tisti obodec za lišp njenega obraza in zapestnice na roke njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 48, 'In priklonil sem se in molil Gospoda in hvalil sem Gospoda, Boga gospodarja mojega Abrahama, ker me je vodil po pravem potu, da dobim hčer brata gospoda svojega za njegovega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 49, 'Sedaj torej, če vas je volja, milost in zvestobo izkazati gospodu mojemu, mi povejte; če pa ne, mi povejte, da krenem na desno ali na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 50, 'In odgovorita Laban in Betuel ter rečeta: Od Gospoda je izšla ta reč, ne moreva ti reči slabega ali dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 51, 'Glej, Rebeka ti je na voljo, vzemi jo in odidi, in žena bodi sinu gospodarja tvojega, kakor je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 52, 'In ko je slišal hlapec Abrahamov njune besede, se prikloni pred Gospodom do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 53, 'In hlapec seže po dragotine srebrne in dragotine zlate ter oblačila in jih izroči Rebeki; enako dá dragocenosti bratu njenemu in materi njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 54, 'Nato so jedli in pili on in možje, ki so bili ž njim, in so prenočili. Zjutraj pa, ko vstanejo, reče: Pustite me k mojemu gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 55, 'Reče pa brat njen in mati njena: Naj ostane deklica še pri nas nekaj dni, vsaj deset; potem odpotuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 56, 'Reče jima on: Ne mudite me, ker je Gospod srečno storil pot mojo; pustite me, da grem k svojemu gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 57, 'Tedaj reko: Pokličimo deklico in poprašajmo, kaj ona poreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 58, 'In pokličejo Rebeko in ji reko: Hočeš li iti s tem možem? Ona pa reče: Pojdem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 59, 'In pustili so z doma Rebeko, sestro svojo, in dojnico njeno s hlapcem Abrahamovim in z možmi njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 60, 'In blagoslove Rebeko, govoreč ji: Ti sestra naša, bodi mati tisočkrat desettisočem, in v last naj bodo semenu tvojemu vrata sovražnikov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 61, 'Rebeka pa vstane in dekle njene ter sedejo na velblode, da bi šle z možem. In hlapec vzame Rebeko in odpotuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 62, 'Izak pa je ravno prišel s pota k vodnjaku Lahajroju; bival je namreč v južni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 63, 'In Izak je šel premišljat po polju, ko se je večerilo; in ko povzdigne oči in pogleda, glej velblode, ki so se bližali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 64, 'In Rebeka povzdigne oči in zagleda Izaka, in spusti se doli z velbloda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 65, 'In reče hlapcu: Kdo je oni mož, ki prihaja po polju nam naproti? In hlapec reče: Ta je gospod moj. Ona pa vzame zagrinjalo svoje ter se pokrije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 66, 'Tedaj pove hlapec Izaku vse, kar je bil opravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 24, 67, 'In Izak jo pelje v šator Sare, matere svoje, in vzame Rebeko, da mu bode žena, in ljubil jo je. Tako se je Izak potolažil po materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 1, 'Abraham pa vzame drugo ženo, čije ime Ketura.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 2, 'Ona mu porodi Zimrana in Joksana in Medana in Madiana ter Išbaka in Šuaha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 3, 'Joksan pa rodi Šeba in Dedana; sinovi pa Dedanovi so bili Asurim in Letusim in Leumim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 4, 'Sinovi pa Madianovi: Efa in Efer in Hanok in Abida in Eldaa. Vsi ti so bili Keture sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 5, 'In dal je Abraham, karkoli je imel, Izaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 6, 'Sinovom žen priležnic pa, katere je imel, je dal Abraham darov; in loči jih od Izaka, sina svojega, dokler je še živel, in pošlje jih proti vzhodu, v jutrovo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 7, 'Ta pa je doba let življenja Abrahamovega, kolikor jih je živel: sto petinsedemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 8, 'Potem izdahne in umre Abraham v lepi starosti, star in dni svojih sit; in je bil zbran k ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 9, 'In pokopala sta ga Izak in Izmael, sina njegova, v jamo Makpelo na njivi Efrona, sina Zoharja Hetejca, ki je Mamri nasproti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 10, 'na njivi tisti, ki jo je bil kupil Abraham od Hetovih sinov: tam je bil Abraham pokopan in Sara, žena njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 11, 'In bilo je po smrti Abrahamovi, da je Bog blagoslovil Izaka, sina njegovega. Bival pa je Izak blizu vodnjaka Lahajroja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 12, 'Ti pa so rodovi Izmaela, Abrahamovega sina, ki ga je porodila Agara, Sarina dekla egiptovska, Abrahamu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 13, 'in ta so imena sinov Izmaelovih, po njih priimkih, po njih rodovih: prvenec Izmaelov Nebajot, potem Kedar in Adbeel in Mibsam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 14, 'in Misma in Duma in Masa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 15, 'Hadad in Tema, Jetur, Nafis in Kedma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 16, 'Ti so sinovi Izmaelovi in ta so njih imena v njih seliščih in šatoriščih: dvanajst prvakov pri rodovih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 17, 'Ta pa so leta življenja Izmaelovega: sto in sedemintrideset let. Nato izdahne in umre, in je bil zbran k ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 18, 'Prebivali so pa od Havile do Sura, ki je Egiptu nasproti, in v smeri proti Asuru. Vsem bratom svojim nasproti se je naselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 19, 'Ti pa so rodovi Izaka, sina Abrahamovega: Abraham je rodil Izaka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 20, 'in Izak je imel štirideset let, ko si je vzel Rebeko, hčer Betuela Aramejca iz Padan-arama, sestro Labana Aramejca, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 21, 'In prosil je Izak srčno Gospoda za ženo svojo, zato ker je bila nerodovitna, in izprositi se mu je dal Gospod, in spočela je Rebeka, žena njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 22, 'In ko sta se med seboj pehala otročiča v njej, reče: Če je tako, čemu sem tukaj? In šla je posvetovat se z Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 23, 'Gospod pa ji veli: Dva naroda sta v telesu tvojem, in dve ljudstvi se bosta ločili že iz osrčja tvojega; izmed njiju narod eden bode močnejši od drugega, in večji bo služil manjšemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 24, 'Ko so se torej izpolnili dnevi njeni za porod, glej, dvojčka v telesu njenem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 25, 'Izide pa prvi, rjav, ves kakor kosmat plašč: zato so ga imenovali Ezava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 26, 'Potem pa izide brat njegov, čigar roka je držala Ezava za peto: zato so ga imenovali Jakoba. Imel pa je Izak šestdeset let, ko ju je rodila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 27, 'In dečka sta odrasla, in Ezav je bil dober lovec, mož poljski, Jakob pa krotak mož, bival je v šatorih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 28, 'Ljubil je pa Izak Ezava, ker je rad jedel od njegovega lova; a Rebeka je ljubila Jakoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 29, 'In Jakob je kuhal jed; in Ezav pride s polja, in bil je truden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 30, 'In Ezav reče Jakobu: Daj mi, prosim, zajeti od te rjave jedi, ker jako sem truden. Zato so ga imenovali Edoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 31, 'Jakob pa reče: Prodaj mi danes svoje prvorojenstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 32, 'Ezav pa reče: Glej, proti smrti hitim, čemu mi tisto prvorojenstvo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 33, 'In Jakob reče: Prisezi mi danes. In mu priseže in proda prvorojenstvo svoje Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 25, 34, 'In Jakob dá Ezavu kruha in lečne jedi; ta pojé in se napije, potem vstane ter odide. Tako je Ezav zaničeval prvorojenstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 1, 'Bila je pa lakota v deželi, razen one prejšnje lakote, ki je bila v dnevih Abrahamovih. Zatorej je šel Izak k Abimeleku, kralju filistejskemu, v Gerar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 2, 'Prikaže pa se mu Gospod ter veli: Ne hodi doli v Egipt, ampak bivaj v kraju, ki ti ga povem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 3, 'Kot tujec bivaj v tem kraju, in s teboj bodem in te bom blagoslovil, kajti tebi in semenu tvojemu dam vse te kraje, in izpolnim prisego, ki sem jo prisegel Abrahamu, tvojemu očetu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 4, 'in pomnožim seme tvoje kakor zvezde na nebu, in semenu tvojemu dam vse te kraje; in blagoslavljali se bodo v semenu tvojem vsi narodi zemlje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 5, 'zato ker je Abraham slušal moj glas in je pokoren bil poveljem mojim, zapovedim mojim, naredbam in postavam mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 6, 'Bival je torej Izak v Geraru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 7, 'In možje tistega kraja so ga vprašali za ženo njegovo, in reče: Sestra je moja; ker se je bal reči: žena moja, češ, da me ne umoré možje tega kraja zaradi Rebeke, ker je lepe postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 8, 'Zgodi se pa, ko je tam preživel mnogo dni, da je gledal Abimelek, kralj filistejski, skozi okno, in je videl, in glej, Izak se je igral z Rebeko, ženo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 9, 'Zato pokliče Abimelek Izaka ter reče: Glej, ta je vendarle žena tvoja; in kako si rekel: Sestra je moja? Izak pa mu reče: Ker sem menil, da ne umrem zaradi nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 10, 'Tedaj reče Abimelek: Kaj si nam storil to? Malo, da ni ležal eden izmed tega ljudstva z ženo tvojo, in si nas zapeljal v pregreho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 11, 'In Abimelek zapove vsemu ljudstvu svojemu, veleč: Kdor se dotakne tega moža ali žene njegove, smrt ga zadene gotovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 12, 'In Izak je sejal v tej deželi, in žel je isto leto stotero, tako ga je blagoslovil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 13, 'In rastel je ta mož in napredoval neprestano, da je postal silno mogočen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 14, 'in je imel črede ovac in črede goved in mnogo poslov, zato so mu zavidali Filistejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 15, 'In vse vodnjake, ki so jih bili izkopali hlapci očeta njegovega v dnevih Abrahama, očeta njegovega, so zasuli Filistejci in napolnili s prstjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 16, 'In Abimelek veli Izaku: Loči se od nas, ker postal si mnogo močnejši od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 17, 'Izak torej odide odondod ter razpne šatore v dolini Gerarski in prebiva tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 18, 'Izkoplje pa Izak zopet vodnjake, ki so jih bili izkopali v dnevih Abrahama, očeta njegovega, in ki so jih zasuli Filistejci po smrti Abrahamovi, in jih imenuje z imeni, katera jim je dal oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 19, 'In ko kopljejo hlapci Izakovi v dolini, najdejo tam vodnjak žive vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 20, 'Ali prepirali so se pastirji gerarski s pastirji Izakovimi, govoreč: Naša je ta voda. Zato je imenoval tisti vodnjak Esek, ker so se sprli ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 21, 'In ko so izkopali drugi vodnjak, so se prepirali tudi za tega; zato ga je imenoval Sitna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 22, 'Premakne pa odondod šatore in izkoplje drug vodnjak, in za tega se niso prepirali; zato ga je imenoval Rehobot. Rekel je namreč: Sedaj nam je Gospod razširil prostor, da bodimo plodni v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 23, 'Potem gre odondod gori v Bersebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 24, 'Tam se mu prikaže Gospod še tisto noč in reče: Jaz sem Bog Abrahama, očeta tvojega; ne boj se, zakaj jaz sem s teboj in te blagoslovim, in pomnožim seme tvoje zaradi Abrahama, svojega hlapca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 25, 'In postavi ondi oltar in kliče ime Gospodovo, in razpne ondi svoj šator; in hlapci Izakovi izkopljejo ondi vodnjak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 26, 'Abimelek pa pride k njemu iz Gerara z Ahuzatom, prijateljem svojim, in Pikolom, poveljnikom vojske njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 27, 'In reče jim Izak: Zakaj ste prišli k meni, ko me sovražite in ste me pognali od sebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 28, 'Oni pa reko: Razvideli smo jasno, da je Gospod s teboj; zato smo rekli: Bodi sedaj prisega med nami, med nami in teboj; sklenimo torej zavezo s teboj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 29, 'da nam ne storiš hudega, kakor se nismo doteknili tebe in kakor smo ti le dobro storili in odposlali te v miru. Ti si sedaj res blagoslovljenec Gospodov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 30, 'In napravi jim pojedino, in so jedli in pili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 31, 'Zjutraj pa vstanejo s svitom ter prisežejo drug drugemu; in Izak jih spremi ter odidejo od njega v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 32, 'Zgodi se pa še isti dan, da pridejo hlapci Izakovi ter mu sporočé o vodnjaku, ki so ga bili izkopali, ter mu reko: Našli smo vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 33, 'In imenoval ga je Siba; zato je ime tistega mesta Berseba do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 34, 'Ko je pa imel Ezav štirideset let, si vzame za ženo Judito, hčer Beerja Hetejca, in Basemato, hčer Elona Hetejca:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 26, 35, 'obe sta pa žalili srce Izaku in Rebeki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 1, 'Zgodi se pa, ko se je bil postaral Izak in so mu oči temnele, tako da ni videl, da pokliče Ezava, sina svojega starejšega, ter mu reče: Sin moj! In ta reče njemu: Tu sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 2, 'Nato veli: Glej, postaral sem se in ne vem dne smrti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 3, 'Vzemi torej, prosim, orodje svoje, tul in lok svoj, pa pojdi na polje ter ulovi mi lov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 4, 'in pripravi mi okusno jed, kakor jo rad imam, ter prinesi mi, da jem in da te blagoslovi duša moja, preden umrem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 5, 'Rebeka pa je slišala, ko je govoril Izak Ezavu, sinu svojemu. Odide torej Ezav na polje lov lovit, da ga prinese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 6, 'V tem ogovori Rebeka Jakoba, sina svojega: Glej, slišala sem očeta tvojega govorečega z Ezavom, bratom tvojim, ko mu je dejal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 7, 'Prinesi mi lov ter pripravi mi okusno jed, da jo jem in te blagoslovim pred Gospodom, preden umrem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 8, 'Sedaj torej, sin moj, poslušaj glas moj, kar ti jaz velim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 9, 'Pojdi k čredi, vzemi tam ter prinesi mi dva najboljša kozliča, da ju pripravim v okusno jed očetu tvojemu, kakršno ima rad;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 10, 'potem jo prineseš očetu svojemu ter jedel bo, da bi te blagoslovil, preden umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 11, 'Jakob pa reče Rebeki, materi svoji: Glej, Ezav, brat moj, je mož kosmat, jaz pa mož gladek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 12, 'Lahko me potiplje oče moj, in zdel se mu bom, kakor da ga zasmehujem, in pripravim nadse prokletstvo, ne pa blagoslova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 13, 'Pa mu reče mati njegova: Nadme pridi prokletstvo tvoje, sin moj; le poslušaj glas moj ter pojdi in mi prinesi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 14, 'Odide torej, vzame in prinese materi svoji; in mati njegova pripravi okusno jed, kakor je imel rad oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 15, 'Nato vzame Rebeka oblačila Ezava, sina svojega starejšega, najlepša, ki jih je imela pri sebi doma, in obleče Jakoba, sina svojega mlajšega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 16, 'in s kožicami kozličev obleče roke njegove in gladino vratu njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 17, 'In dene jed okusno s kruhom, ki ga je bila pripravila, v roko Jakoba, svojega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 18, 'In gre k očetu svojemu ter reče: Oče moj! Ta veli: Tu sem, kdo si ti, sin moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 19, 'Jakob odgovori očetu svojemu: Jaz sem, Ezav, prvenec tvoj; storil sem, kakor si mi ukazal. Vstani, prosim, sedi in jej od lova mojega, da me blagoslovi duša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 20, 'Izak pa reče sinu svojemu: Kako hitro si to dobil, sin moj! In ta reče: Ker je storil Gospod, Bog tvoj, da mi je prišlo naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 21, 'Tedaj reče Izak Jakobu: Pristopi, prosim, da te otipljem, sin moj, si li ti sin moj Ezav ali ne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 22, 'Pristopi torej Jakob k Izaku, očetu svojemu, ki ga otiplje ter reče: Glas je glas Jakobov, a te roke so roke Ezavove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 23, 'In ni ga spoznal, zato ker so bile roke njegove podobne rokam Ezava, brata njegovega, kosmate; in ga je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 24, 'In reče: Ti tukaj, si li sin moj Ezav? Jakob odgovori: Sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 25, 'In reče: Podaj mi in jedel bom od lova sina svojega, da te blagoslovi duša moja. In ko mu je podal, pojé, in ko mu je prinesel vina, popije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 26, 'Nato mu veli Izak, oče njegov: Pristopi le ter me poljubi, sin moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 27, 'Pristopil je torej in ga poljubil, in ko on začuti duh oblačil njegovih, ga blagoslovi in reče: Glej, duh sina mojega je kakor duh polja, ki ga je blagoslovil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 28, 'Daj ti torej Bog od rose nebeške in od rodovitnih poljan zemlje ter obilost žita in vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 29, 'Služijo naj ti ljudstva in klanjajo naj se ti narodi; gospodar bodi bratom svojim, in klanjajo naj se ti matere tvoje sinovi. Kdor te proklinja, vsak bodi proklet, in kdor te blagoslavlja, vsak bodi blagoslovljen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 30, 'Zgodi se pa, ko je nehal Izak blagoslavljati Jakoba in ko je bil komaj Jakob odšel izpred obličja Izaka, očeta svojega, da se Ezav vrne z lova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 31, 'In pripravi tudi on okusno jed in prinese očetu svojemu, ter reče očetu svojemu: Vstani, oče moj, ter jej od lova sina svojega, da me blagoslovi duša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 32, 'Reče mu pa Izak, oče njegov: Kdo si ti? In odvrne: Jaz, sin tvoj, prvenec tvoj, Ezav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 33, 'Tedaj zatrepeče Izak s trepetom silno velikim ter reče: Kdo pa je tisti, ki je ulovil lov in mi prinesel, in jedel sem od vsega, preden si prišel, in sem ga blagoslovil? Tudi ostane blagoslovljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 34, 'Ko je pa slišal Ezav očeta svojega besede, zavpije z vpitjem velikim in silno bridkim ter reče očetu svojemu: Blagoslovi me, tudi mene, oče moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 35, 'On pa reče: Prišel je brat tvoj po zvijači, in odnesel je blagoslov tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 36, 'In reče Ezav: Ni li se prav imenoval Jakob? kajti izpodrinil me je že vdrugič: ob prvenstvo me je pripravil, in glej, zdaj je odnesel blagoslov moj. Nato reče: Nisi li nič blagoslova mi prihranil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 37, 'Odgovarjajoč pa reče Izak Ezavu: Glej, za gospoda sem ti ga postavil, in vse brate sem mu izročil za hlapce, tudi z žitom in vinom sem ga podprl: tebi torej kaj naj še storim, sin moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 38, 'Reče pa Ezav očetu svojemu: Ali imaš le edin blagoslov, oče moj? Blagoslovi me, tudi mene, oče moj! In Ezav zažene svoj glas ter joka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 39, 'In odgovori Izak, oče njegov, in mu reče: Glej, daleč od rodovitnih poljan zemlje bode bivališče tvoje in daleč od rose nebeške odzgoraj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 40, 'in od meča svojega boš živel, in služil boš bratu svojemu; zgodi se pa, ko boš tako divjal, da otreseš jarem njegov z vratu svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 41, 'In sovražil je Ezav Jakoba zaradi blagoslova, s katerim ga je bil blagoslovil oče njegov. In Ezav reče v srcu svojem: Bližajo se dnevi žalovanja za mojim očetom, tedaj umorim Jakoba, brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 42, 'In sporočili so Rebeki besede Ezava, sina njenega starejšega; pošlje torej in pokliče Jakoba, sina svojega mlajšega, ter mu reče: Glej, Ezav, brat tvoj, se tolaži zate s tem, da te umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 43, 'Sedaj torej, sin moj, poslušaj glas moj: vstani ter pobegni k Labanu, bratu mojemu, v Haran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 44, 'Tam bivaj ž njim malo dni, dokler se ne uleže brata tvojega srd;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 45, 'dokler se ne obrne jeza brata tvojega od tebe ter pozabi tisto, kar si mu storil. Potem pošljem in te vzamem k sebi od tam. Zakaj bi naj izgubila vaju oba v enem dnevu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 27, 46, 'Izaku pa reče Rebeka: Studi se mi življenje moje zaradi hčerá Hetejcev. Če vzame Jakob ženo izmed hčer Hetejcev, kakršni sta oni dve, izmed hčer tega kraja, čemu mi življenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 1, 'Pokliče torej Izak Jakoba in ga blagoslovi ter mu zapove, rekoč: Ne jemlji žene izmed hčer Kanaancev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 2, 'Vstani, pojdi v Padan-aram, na dom Betuela, deda svojega po materi, in vzemi si odondod ženo izmed hčer Labana, ujca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 3, 'In Bog silni, Vsegamogočni te blagoslovi, in rodovitnega te stóri ter pomnóži, da bodeš oče množici narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 4, 'In daj ti blagoslov Abrahamov, tebi in semenu tvojemu s teboj, da podeduješ deželo tujčevanja svojega, ki jo je Bog dal Abrahamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 5, 'Tako pošlje Izak Jakoba, da je šel v Padan-aram k Labanu, sinu Betuela Aramejca, bratu Rebeke, matere Jakobove in Ezavove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 6, 'In Ezav je videl, da je Izak blagoslovil Jakoba in ga odposlal v Padan-aram, da si vzame odondod ženo, in ko ga je blagoslavljal, da mu je prepovedal, rekoč: Ne jemlji žene izmed hčer Kanaancev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 7, 'in da je Jakob poslušal očeta svojega in mater svojo in šel v Padan-aram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 8, 'Tudi je videl Ezav, da se slabe vidijo hčere Kanaancev v očeh Izaka, očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 9, 'Šel je torej Ezav k Izmaelcem ter si vzame poleg žen svojih še za ženo Mahalato, hčer Izmaela, sina Abrahamovega, sestro Nebajotovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 10, 'Ali Jakob odide iz Bersebe in se napoti v Haran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 11, 'In naleti na neki kraj, kjer je prenočil, ker je bilo solnce zašlo; in vzame od kamenja tistega kraja ter si napravi podglavje in leže počivat v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 12, 'In sanjalo se mu je, in glej, lestvica je bila postavljena na zemljo, a vrh njen je segal do neba; in glej angele Božje, stopajoče gori in doli po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 13, 'In glej Gospoda, stoječega nadnjo, in mu govori: Jaz sem Gospod, Bog Abrahama, očeta tvojega, in Bog Izakov: to deželo, na kateri ležiš, dam tebi in semenu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 14, 'In seme tvoje bode kakor prah zemlje, in razširiš se proti jutru in proti večeru in proti poldnevu in proti polnoči, in v tebi in v semenu tvojem bodo blagoslovljene vse rodovine zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 15, 'Glej pa, jaz sem s teboj in te ohranim, kamorkoli pojdeš, in te pripeljem nazaj v to deželo; kajti ne zapustim te, dokler ne izpolnim, kar sem ti obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 16, 'In ko se zbudi Jakob iz spanja, reče: Resnično, Gospod je v tem kraju, in jaz nisem vedel!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 17, 'In v svetem strahu reče: kako častitljiv je ta kraj! Ni nič drugega nego hiša Božja, in tu so vrata nebeška!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 18, 'In Jakob vstane zgodaj tisto jutro ter vzame kamenje, ki si ga je položil za podglavje, in ga postavi v spomenik in izlije olja na vrh njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 19, 'In imenuje ime tega kraja Betel; ali prej je bilo Luz ime tistemu mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 20, 'In Jakob stori obljubo, govoreč: Ako bode Bog z menoj ter me ohrani na tem potu, po katerem sedaj potujem, in mi da kruha za jed in oblačila, da ga oblečem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 21, 'in se vrnem srečno na dom očeta svojega: tedaj mi Gospod bodi Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 28, 22, 'in to kamenje, katero sem postavil v spomenik, bodi hiša Božja; in karkoli mi boš dal, od vsega ti dam desetino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 1, 'Potem odrine Jakob ter pride v deželo Jutrovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 2, 'Ko se pa ozira, glej, vodnjak na polju, in glej, tri črede ovac tam, ležečih poleg njega, ker so se iz tistega vodnjaka napajale črede, in kamen velik na vodnjakovi odprtini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 3, 'Sem namreč so navadno gonili vse črede, in odvalili so kamen z vodnjakove odprtine in napajali ovce, nato so kamen zopet položili na vodnjakovo odprtino na svoje mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 4, 'In Jakob jim reče: Bratje moji, odkod ste? Odgovoré: Iz Harana smo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 5, 'In jih vpraša: Poznate li Labana, sina Nahorjevega? Oni reko: Poznamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 6, 'Nato jim reče: Ali se mu dobro godi? Oni reko: Dobro; in glej Rahelo, hčer njegovo, ki gre z ovcami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 7, 'Tedaj reče: Glejte, še je dneva veliko; prezgodaj je zbirati živino: napojite te ovce ter pojdite in pasite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 8, 'Oni pa reko: Ne moremo, dokler se niso zbrale vse črede, tedaj šele odvalimo kamen z vodnjakove odprtine in napojimo ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 9, 'Ko je še govoril ž njimi, pride Rahela z ovcami svojega očeta; kajti pasla jih je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 10, 'In zgodi se, ko vidi Jakob Rahelo, hčer Labana, brata matere svoje, in ovce Labana, brata matere svoje, da pristopi Jakob ter odvali kamen z vodnjakove odprtine in napoji ovce Labana, brata matere svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 11, 'In Jakob poljubi Rahelo in glasno zajoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 12, 'In pove Jakob Raheli, da je sorodnik očeta njenega in da je sin Rebekin; ona pa poteče in sporoči očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 13, 'In zgodi se, ko začuje Laban sporočilo o Jakobu, sinu sestre svoje, da mu priteče naproti ter ga objame in poljubi in ga pelje v hišo svojo. In pripoveduje Labanu vse te dogodke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 14, 'In Laban mu reče: V istini, kost si moja in meso moje. In ostal je pri njem cel mesec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 15, 'Potem reče Laban Jakobu: Ali naj bi mi, ker si brat moj, služil brezplačno? Povej mi, kaj bodi plačilo tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 16, 'Imel je pa Laban dve hčeri: ime starejši Leja in mlajši ime Rahela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 17, 'Imela je pa Leja oči slabotne, ali Rahela je bila lepe postave in zalega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 18, 'In Jakob je ljubil Rahelo; in reče: Služil ti bom sedem let za Rahelo, mlajšo hčer tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 19, 'In Laban veli: Bolje bode, da jo dam tebi nego drugemu možu: ostani pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 20, 'Tako je služil Jakob za Rahelo sedem let, in so se mu zdela kakor nekoliko dni, zato ker jo je ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 21, 'Tedaj reče Jakob Labanu: Daj mi ženo mojo, ker so izpolnjeni dnevi moji, da grem k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 22, 'In Laban zbere vse može tistega kraja in napravi pojedino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 23, 'Zvečer pa vzame Lejo, hčer svojo, ter jo pripelje k njemu; in on se združi ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 24, 'In da ji Laban Zilpo, deklo svojo, da bodi Leji, hčeri njegovi, dekla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 25, 'In zjutraj, glej, bila je Leja. In reče Labanu: Kaj si mi to storil? Nisem li služil za Rahelo pri tebi? Zakaj si me torej okanil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 26, 'Njemu pa reče Laban: Ni navada tako v našem kraju, da se moži mlajša pred prvenko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 27, 'Izpolni njen teden; potem ti damo tudi ono za službo, ki jo boš opravljal pri meni še drugih sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 28, 'In Jakob stori tako ter izpolni njen teden, in Laban mu da Rahelo, hčer svojo, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 29, 'In Laban da Bilho, deklo svojo hčeri svoji Raheli za deklo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 30, 'In šel je tudi k Raheli; in ljubil je tudi Rahelo bolj nego Lejo. In služil je še drugih sedem let pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 31, 'Ko je pa videl Gospod, da za Lejo ni ljubezni, odpre maternico njeno, Rahelo pa pusti nerodovitno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 32, 'In Leja spočne ter porodi sina in mu da ime Ruben; dejala je namreč: Zato ker se je Gospod ozrl na ponižanje moje, kajti sedaj me bo ljubil moj mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 33, 'In spočne zopet in rodi sina ter reče: Ker je čul Gospod, da mi ni ljubezni, zato mi je dal tudi tega, in imenovala ga je Simeona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 34, 'In spočne vnovič ter rodi sina in reče: Sedaj se mi vendar priklene moj mož, ker sem mu rodila tri sinove, in imenovala ga je Levija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 29, 35, 'Potem spočne zopet in, rodivši sina, reče: Hvalila bom ta krat Gospoda, in ga je imenovala Juda. Tedaj pa je nehala roditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 1, 'Ko je pa videla Rahela, da ona ne rodi Jakobu, je zavidala sestri svoji, in reče Jakobu: Daj mi otrók, če ne, umrem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 2, 'In Jakob se raztogoti proti Raheli in reče: Ali sem jaz namesto Boga, ki ti je odrekel sad telesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 3, 'Ona pa reče: Glej, deklo mojo Bilho, pojdi k njej, da porodi na kolenih mojih, in dobim tudi jaz otrók iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 4, 'In dá mu Bilho, deklo svojo, za ženo; in združi se ž njo Jakob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 5, 'Tako spočne Bilha in porodi Jakobu sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 6, 'Tedaj reče Rahela: Bog mi je storil pravico in tudi uslišal glas moj ter mi dal sina, in ga je imenovala Dana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 7, 'Nato spočne Bilha, Rahelina dekla, vdrugič in porodi sina drugega Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 8, 'In Rahela reče: V bojih Božjih sem se borila s sestro svojo in zmogla sem, zato ga je imenovala Neftalija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 9, 'Ko je pa videla Leja, da je nehala roditi, vzame Zilpo, deklo svojo, in jo da Jakobu za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 10, 'In Zilpa, Lejina dekla, porodi Jakobu sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 11, 'In Leja reče: Na srečo! in imenovala ga je Gada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 12, 'In Zilpa, Lejina dekla, porodi Jakobu drugega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 13, 'In Leja reče: Blagor meni! kajti blagrovale me bodo žene, zato ga je imenovala Aserja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 14, 'In šel je Ruben ob času pšenične žetve in našel ljubezenska jabolčka na polju in jih prinesel Leji, materi svoji; in reče Rahela Leji: Daj mi, prosim, od ljubezenskih jabolčk svojega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 15, 'Ona pa ji reče: Ali se ti zdi premalo, da si vzela moža mojega, hočeš li tudi vzeti ljubezenskih jabolčk sina mojega? Njej pa reče Rahela: Zato naj on s teboj leži nocoj za ljubezenska jabolčka sina tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 16, 'In ko se je Jakob zvečer vračal s polja, mu pride Leja naproti ter reče: K meni prideš, zakaj prav za plačilo sem te najela za ljubezenska jabolčka svojega sina. In ležal je ž njo tisto noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 17, 'Bog pa je uslišal Lejo: spočne namreč ter porodi Jakobu sina petega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 18, 'In Leja reče: Bog mi je povrnil plačilo moje, zato ker sem dala deklo svojo možu svojemu, in ga je imenoval Isaharja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 19, 'In zopet spočne Leja in porodi sina šestega Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 20, 'In reče Leja: Oblagodaril me je Bog z blagodarom dobrim; zdaj vendar bo prebival moj mož z menoj, ker sem mu porodila šest sinov; zato ga je imenovala Zebulona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 21, 'pozneje pa porodi hčer, in imenovala jo je Dino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 22, 'Spomni se pa Bog Rahele, usliši jo Bog ter ji odpre maternico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 23, 'In spočne in rodi sina ter reče: Odvzel je Bog sramoto mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 24, 'In imenovala ga je Jožefa, rekoč: Pridaj mi Gospod še drugega sina!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 25, 'Zgodi se pa, ko je rodila Rahela Jožefa, da reče Jakob Labanu: Odpústi me, da odidem v svoj kraj in v deželo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 26, 'Daj mi ženi moji in otroke moje, za katere sem ti služil, da odidem; ti namreč znaš službo mojo, s katero sem ti služil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 27, 'Laban pa mu reče: O da bi našel milost v tvojih očeh! zaznal sem, da me je Gospod blagoslovil zaradi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 28, 'Reče torej: Določi mi plačilo svoje, in ti ga dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 29, 'Jakob mu reče: Ti veš, kako sem ti služil in kako se je godilo živini tvoji pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 30, 'Zakaj kar si malega imel pred prihodom mojim, to se je pomnožilo, in Gospod ter je blagoslovil, kamorkoli sem krenil. Sedaj pa, kdaj naj skrbim tudi jaz za hišo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 31, 'In veli: Kaj ti dam? In Jakob reče: Ne dajaj mi ničesar; pasel bom zopet čredo tvojo in stražil, če mi storiš to:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 32, 'danes pregledam vso čredo tvojo in odločim od nje vsako živinče pisano in marogasto, in vse čadasto med ovcami ter marogasto in pisano med kozami; in to bodi plačilo moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 33, 'In pričala bo pravičnost moja zame v prihodnosti, kadar prideš gledat plačilo moje, ki je pred teboj: karkoli ni pisano in marogasto med kozami ali čadasto med ovcami, bodi tatvina pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 34, 'In Laban reče: Glej, bodi, kakor si rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 35, 'In še tisti dan je odločil kozle progaste in marogaste in vse koze pisane in marogaste, vse, na katerih je bila bela lisa, potem vse čadasto med ovcami, in jih izroči v roko sinom svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 36, 'in določi tri dni hoda razdalja med seboj in Jakobom; in Jakob je pasel ostalo drobnico Labanovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 37, 'Vzame si pa Jakob zelene palice z bele topole in z mandeljnovca in platanove in izlupi po njih bele proge, da se je kazala belina, ki je bila na palicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 38, 'In tiste palice, ki jih je bil olupil, je pokladal v žlebove in v korita, ko so prihajale ovce pit, ovcam nasproti, da bi se mrkale, ko pridejo pit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 39, 'Tako so se ubrejile ovce pri tistih palicah in so rodile progaste, lisaste in marogaste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 40, 'In ta jagnjeta je odločeval Jakob, in obličja ovac je obračal proti pisanim in proti vsem čadastim v Labanovi čredi; in sebi je napravljal črede posebe, in jih ni mešal med ovce Labanove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 41, 'In kadar so se mrkale ovce krepkega života, je pokladal Jakob palice ovcam pred oči v žlebove, da bi se ubrejile pri tistih palicah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 42, 'kadar so se pa družile ovce slabotne, jih ni pokladal: tako so bile slabotne Labanove, krepke pa Jakobove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 30, 43, 'Tako je ta mož silno obogatel, in imel je veliko drobnice in dekel in hlapcev in velblodov in oslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 1, 'Slišal pa je Jakob besede sinov Labanovih, govorečih: Vzel je Jakob, karkoli je imel naš oče, in iz imetja našega očeta si je pridobil vso tisto slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 2, 'Videl je tudi Jakob obličje Labanovo, in glej, ni bilo do njega kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 3, 'In Gospod je velel Jakobu: Vrni se v deželo očetov svojih in k sorodovini svoji, in bodem s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 4, 'In pošlje Jakob in pokliče Rahelo in Lejo na polje k svoji čredi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 5, 'in jima reče: Vidim, da obličje očeta vajinega ni do mene kakor poprej; toda Bog očeta mojega je bil pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 6, 'In vedve vesta, da sem po vsej svoji moči služil vajinemu očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 7, 'Oče vajin pa me je varal in premenil plačilo moje desetkrat, a Bog mu ni dovolil, da bi me oškodoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 8, 'Ako je rekel: Kar je pestrega, bodi plačilo tvoje, tedaj so rodile vse črede pestro; ko je pa tako rekel: Kar je progastega, bodi plačilo tvoje, tedaj so rodile vse črede progasto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 9, 'Bog torej je vzel blago vajinega očeta in ga dal meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 10, 'Ob času namreč, ko se mrkajo ovce, sem povzdignil oči in videl v sanjah, in glej, ovni, ki zaskakujejo ovce, so pisani, marogasti in grahasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 11, 'In angel Božji mi reče v sanjah: Jakob! In rečem: Glej, tu sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 12, 'In veli: Povzdigni sedaj oči in poglej vse ovne, ki zaskakujejo ovce, da so progasti in pisani in grahasti; kajti videl sem vse, kar ti dela Laban.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 13, 'Jaz sem Bog mogočni iz Betela, kjer si pomazilil spomenik, kjer si mi storil obljubo. Sedaj vstani, pojdi iz tega kraja in vrni se v deželo rojstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 14, 'In odgovorita Rahela in Leja ter mu rečeta: Imamo li še delež in dedino v hiši najinega očeta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 15, 'Ali ni naju štel za tujki sebi? Saj naju je prodal in tudi izkupiček za naju je požrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 16, 'Kajti vse to bogastvo, katero je Bog odvzel najinemu očetu, najino je in najinih otrok; sedaj pa, karkoli ti je velel Bog, stóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 17, 'Vstane torej Jakob, vzame sinove svoje in ženi svoji ter jih posadi na velblode');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 18, 'in odpelje vso živino svojo in vse blago svoje, katero je bil nabral, živino lastnine svoje, ki jo je pridobil v Padan-aramu, da bi potoval k očetu svojemu Izaku v deželo Kanaansko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 19, 'Laban pa je bil odšel ovce svoje strič, in tedaj ukrade Rahela domače malike, ki so bili njenega očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 20, 'Jakob pa prekani dušo Labana Aramejca, ker mu ni dal zaznati, da beži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 21, 'Tako pobegne on z vsem, kar je imel; in vstane ter prekorači reko in nameri obličje svoje proti gori Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 22, 'A tretji dan sporoče Labanu, da je Jakob zbežal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 23, 'In vzame brate svoje s seboj ter gre za njim sedem dni hodá, in dohiti ga na gori Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 24, 'Bog pa pride k Labanu Aramejcu v nočnih sanjah ter mu reče: Varuj se, da ne govoriš z Jakobom bodi dobro, bodi hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 25, 'In dojde Laban Jakoba. Jakob pa je bil zasadil šator svoj na gori, tudi Laban z brati svojimi ga zasadi na gori Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 26, 'Tedaj reče Laban Jakobu: Kaj si storil, da si prekanil dušo mojo in si odpeljal hčeri moji, kakor da si ju ujel v vojski?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 27, 'Zakaj si pobegnil na skrivnem in si me prekanil? in mi nisi nič povedal, da bi te odpustil z radostjo in s petjem, z bobnom in s strunami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 28, 'In nisi mi dovolil, da poljubim sine svoje in hčere svoje? Zdaj si ravnal nespametno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 29, 'Bilo bi v moči roke moje, hudo vam storiti, ali Bog očeta vašega me je ogovoril snoči takole: Varuj se, da ne govoriš z Jakobom bodi dobro, bodi hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 30, 'Zdaj pa, ker si že ušel, kajti silno si hrepenel na svojega očeta dom, zakaj si ukradel bogove moje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 31, 'In odgovori Jakob in reče Labanu: Ker sem se bal; mislil sem namreč, da bi mi ti siloma odvzel hčeri svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 32, 'Pri komer najdeš bogove svoje, naj ne bode živel; vpričo bratov naših preglej, kaj je tvojega pri meni, in vzemi si. Jakob namreč ni vedel, da jih je bila ukradla Rahela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 33, 'Laban torej gre v šator Jakobov in v šator Lejin in v šator obeh dekel, a jih ne najde. In pride iz šatora Lejinega in stopi v šator Rahelin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 34, 'Rahela pa je vzela tiste malike in jih dejala na velbodovo sedlo in je sedla nanje. In Laban pretakne ves šator njen, a jih ne najde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 35, 'Ona pa reče očetu svojemu: Ne bodi žaljivo v očeh gospoda mojega, da ne morem vstati pred teboj, ker mi je po ženski navadi. Ko preišče torej vse, ne najde svojih malikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 36, 'Tedaj se razjezi Jakob in začne očitati Labanu; in odgovori Jakob ter reče Labanu: Kaj je moj prestopek, kaj je moj greh, da si hitel tako nagle jeze za mano?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 37, 'In ker si obtipal vse pohištvo moje, kaj si našel od vsega blaga hiše svoje? Položi sem, vpričo bratov mojih in bratov tvojih, da razsodijo med nama obema!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 38, 'Dvajset let je, odkar sem bil s teboj: ovce in koze tvoje niso bile jalove, in ovnov črede tvoje nisem jedel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 39, 'Raztrganih živali nisem prinesel k tebi: sam sem škodo trpel, iz moje roke si to zahteval, ukradeno mi po dnevi, ukradeno mi po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 40, 'Tako je bilo: po dnevi me je morila vročina in mraz po noči, in spanje se je umikalo mojim očem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 41, 'To mi je bilo dvajseto leto v hiši tvoji; služil sem ti štirinajst let za dve hčeri tvoji in šest let za čredo tvojo, a izpremenil si plačilo moje desetkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 42, 'Ako bi mi ne bil mojega očeta Bog, Bog Abrahamov in Strah Izakov, na strani, ti bi me bil sedaj odpustil praznega. Bog se je ozrl na ponižanje moje in rok mojih trud, in te je posvaril nocoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 43, 'Odgovarjaje pa Laban, reče Jakobu: Ti hčeri hčeri sta moji in ti sinovi sinovi so moji, in ta živina živina moja, skratka: vse, kar vidiš, je moje. A kaj bi storil danes tema hčerama svojima ali otrokom njijnim, ki sta jih rodili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 44, 'In sedaj, dej, skleniva zavezo, jaz in ti, in naj bode v pričevanje med menoj in teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 45, 'Jakob torej vzame kamen in ga postavi v spomenik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 46, 'In bratom svojim veli Jakob: Poberite kamenje! In vzemo kamenje in naredé kup; in jedli so tam na tem kupu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 47, 'In Laban ga je imenoval Jegar sahaduta, Jakob pa ga je imenoval Galed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 48, 'Rekel je namreč Laban: Ta kup bodi priča med teboj in menoj danes; zato mu je dano ime Galed,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 49, 'in tudi Micpa, ker je rekel Laban: Straži naj Gospod med menoj in teboj, ko ne bova drug drugega videla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 50, 'Ako boš grdo ravnal z mojima hčerama in če si vzameš še žene poleg hčer mojih, nobenega človeka ne bode med nama: glej, Bog bode priča med menoj in teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 51, 'Še reče Laban Jakobu: Glej ta kup in glej ta spomenik, ki sem ga postavil med seboj in teboj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 52, 'ta kup bodi priča in ta spomenik bodi priča, da ne pojdem jaz čez ta kup do tebe in da tudi ti ne pojdeš čez ta kup in ta spomenik do mene, na húdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 53, 'Bog Abrahamov in Bog Nahorjev, Bog njiju očeta, naj sodi med nama! In Jakob priseže pri Strahu očeta svojega Izaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 54, 'Nato zakolje Jakob žrtev na tisti gori in pokliče brate svoje, da použijejo jed. In použili so jed in prenočili na gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 31, 55, 'In zgodaj zjutraj vstane Laban in poljubi sine svoje in hčeri svoji in jih blagoslovi; in Laban odide ter se vrne v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 1, 'Jakob pa gre dalje svojim potem, in naproti mu pridejo angeli Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 2, 'In Jakob reče, ko jih je videl: Tabor vojske Božje je to; zato je imenoval tisti kraj Mahanaim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 3, 'In Jakob pošlje poročnike pred seboj do Ezava, brata svojega, v pokrajino Seirsko, poljano Edomsko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 4, 'in jim naroči, govoreč: Tako porečete gospodu mojemu Ezavu: Tako pravi hlapec tvoj Jakob: Pri Labanu sem živel kot tujec in bival do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 5, 'Imam pa volov in oslov, čred, hlapcev in dekel, zato sem poslal poročat to gospodu svojemu, da najdem milost v tvojih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 6, 'In poročniki so se vrnili k Jakobu, govoreč: Prišli smo k bratu tvojemu, ki ti gre tudi naproti in štiristo mož ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 7, 'In Jakob se silno zboji, in bil je zbegan; in razdeli ljudstvo, ki je bilo ž njim, in črede in goveda in velblode v dve krdeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 8, 'Dejal je namreč: Če napade Ezav eno krdelo ter je pobije, bo vsaj krdelo, ki ostane, moglo pobegniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 9, 'In reče Jakob: O Bog očeta mojega Abrahama in Bog očeta mojega Izaka, Gospod, ki si mi velel: Vrni se v deželo svojo in k sorodovini svoji, in obsujem te z dobrim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 10, 'Nevreden sem vseh milosti in vse zvestobe, ki si jo izkazal hlapcu svojemu; kajti samo s palico svojo sem prekoračil ta Jordan, sedaj pa sem gospodar dveh krdel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 11, 'Otmi me, prosim, iz brata mojega roke, iz Ezava roke, zakaj bojim se ga, da ne pride in me pobije, matere z otroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 12, 'Saj si rekel: Obsujem te z dobrotami in seme tvoje naredim kakor morski pesek, ki ga od množine ni mogoče sešteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 13, 'In prenoči ondi tisto noč; in vzame od imetka, ki mu je prišel v roko, da ponudi v dar Ezavu, bratu svojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 14, 'dvesto koz z dvajsetimi kozliči, dvesto ovac z dvajsetimi jagnjeti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 15, 'trideset molznih velblodov z njih mladiči, štirideset krav in deset juncev, oslic dvajset z desetimi osliči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 16, 'In da jih v roko hlapcem svojim, vsako čredo posebe, in ukaže hlapcem svojim: Idite pred menoj in pustite presledek med eno čredo in drugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 17, 'In ukaže prvemu, rekoč: Ko te sreča Ezav, brat moj, in te vpraša, rekoč: Čigav si? in kam greš? in čigavo je tisto pred teboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 18, 'tedaj porečeš: Hlapca tvojega, Jakoba. To je darilo, poslano gospodu mojemu Ezavu; in glej, tudi on sam gre za nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 19, 'Isto ukaže tudi drugemu in tretjemu in vsem, ki so spremljali črede, govoreč: Tako ogovorite Ezava, ko ga srečate;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 20, 'a porečete tudi: Glej, Jakob, hlapec tvoj, gre za nami. Rekel je namreč: Potolažim obličje njegovo s tem darilom, ki gre pred menoj, in potem zagledam obličje njegovo, morda me prijazno sprejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 21, 'In šlo je tisto darilo pred njim; on pa je prenočil to noč v šatorišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 22, 'In vstane še to noč ter vzame dve ženi svoji z dvema deklama svojima in enajst otrok svojih, in prebrede brod Jabok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 23, 'In ko jih je vzel in spravil čez reko, prevede tudi vse, kar je imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 24, 'In Jakob je ostal sam; in mož se je boril ž njim, dokler je vstala zarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 25, 'In ko je videl, da ga ne zmore, ga udari v kolkov sklep; in Jakobu se je izmaknil kolkov sklep, ko se je boril ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 26, 'In veli: Pusti me, kajti zarja že vzhaja! Jakob pa reče: Ne pustim te, razen če me blagosloviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 27, 'In mu reče: Katero je ime tvoje? On pa reče: Jakob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 28, 'Nato veli: Ne Jakob se bo imenovalo ime tvoje, ampak Izrael: zakaj boril si se z Bogom in z ljudmi in si zmagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 29, 'Jakob pa vpraša in reče: Povej, prosim, ime svoje. On pa veli: Čemu pa poprašuješ po mojem imenu? In ondi ga je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 30, 'Zato je Jakob imenoval ime tistega kraja Penuel: zakaj Boga sem videl z obličjem v obličje, in oteta je bila duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 31, 'Izšlo pa mu je solnce, ko je prešel Penuel, in hramal je od kolka svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 32, 32, 'Zato sinovi Izraelovi ne jedo do tega dne živčne kite, ki je na kolkovem sklepu, ker je udaril Jakobov kolkov sklep, živčno kito na kolku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 1, 'In Jakob povzdigne oči in vidi, in glej, Ezav prihaja in štiristo mož ž njim. In razdeli otroke na Lejo in na Rahelo in na dve dekli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 2, 'in postavi dekli in njune otroke spredaj in Lejo in otroke njene za njimi, Rahelo pa in Jožefa najzadnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 3, 'Sam pa gre naprej pred njimi in se prikloni do tal sedemkrat, dokler pride blizu brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 4, 'A Ezav mu priteče naproti, ga objame, se mu oklene vratu in ga poljubi; in oba jočeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 5, 'In Ezav povzdigne oči, in ko zagleda žene in otroke, reče: Kdo so tebi tile? On odgovori: Otročiči so, ki jih je Bog milostno podaril hlapcu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 6, 'Nato pristopita dekli, oni in njuni otroci, ter se priklonijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 7, 'Potem pristopi tudi Leja in otroci njeni ter se priklonijo; in naposled pristopi Jožef in Rahela ter se priklonita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 8, 'In vpraša Ezav: Kaj hočeš z vsem tistim krdelom, ki sem ga srečal? On pa reče: Da najdem milost v očeh gospoda svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 9, 'A Ezav veli: Jaz imam dovolj, brat moj; ti imej, kar je tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 10, 'In Jakob reče: Nikar; če sem res našel milost v tvojih očeh, prosim, sprejmi darilo moje iz roke moje; saj zategadelj sem zagledal obličje tvoje, kakor da bi bil zagledal obličje Božje, in blagovoljno si me sprejel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 11, 'Vzemi prosim, blagodar moj, ki so ga privedli k tebi, ker me je milostno obdaril Bog, da imam vsega dosti. In ker ga je silil, je sprejel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 12, 'Nato reče: Napotiva se in idiva dalje, in jaz te bom spremljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 13, 'Jakob mu reče: Gospod moj ve, da so ti otroci nežni in da imam pri sebi ovce in krave doječe; ako jih bodo preveč gnali en dan, mi pogine vsa čreda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 14, 'Ide naj, prosim, gospod moj pred hlapcem svojim: Jaz pa pojdem počasi in polahkoma po hoji živine, ki je pred menoj, in po hoji otrok, dokler ne pridem k svojemu gospodu v Seir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 15, 'Še reče Ezav: Postavim naj pri tebi nekoliko ljudstva, ki je z menoj. On pa reče: Čemu to? Da le milost najdem v očeh svojega gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 16, 'Vrne se torej še tisti dan Ezav po svojem potu proti Seiru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 17, 'Jakob pa se napoti v Sukot, kjer si zgradi hišo, živini pa svoji napravi stane. Zato se je imenoval tisti kraj Sukot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 18, 'In pride Jakob v miru do mesta Sihema, ki je v deželi Kanaanski, ko je dospel iz Padan-arama, in postavi šatore pred mestom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 19, 'In kupi kos polja, na katerem je razpel šator svoj, od sinov Hamorja, očeta Sihemovega, za sto kesit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 33, 20, 'In tu je postavil oltar in ga je imenoval: Bog mogočni je Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 1, 'Dina pa, Lejina hči, ki jo je bila rodila Jakobu, je šla gledat hčere tistega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 2, 'In videl jo je Sihem, sin Hamorja Hevejca, kneza v tistem kraju, in jo ugrabi ter leže ž njo in jo posili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 3, 'In srce njegovo se je prijelo Dine, Jakobove hčere, in je silno ljubil deklico in govoril, kar ji je segalo v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 4, 'In Sihem ogovori Hamorja, očeta svojega, rekoč: Vzemi mi to deklico za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 5, 'Jakob pa je slišal, da je on oskrunil Dino, hčer njegovo; a sinovi njegovi so bili na polju z živino njegovo; in molčal je Jakob dokler niso prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 6, 'Pride pa Hamor, Sihemov oče, k Jakobu, da ž njim govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 7, 'In pridejo sinovi Jakobovi s polja, brž ko so slišali; in žalost je obšla te može in razsrdili so se silno, kajti nesramnost je storil v Izraelu, ker je legel s hčerjo Jakobovo, in tako se ne sme storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 8, 'In snubil je pri njih Hamor, govoreč: Sihema, sinú mojega, srce je v ljubezni nagnjeno do hčere vaše; dajte mu jo, prosim, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 9, 'In svaštvo sklenite z nami: hčere svoje dajajte nam in jemljite naše hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 10, 'In z nami ostanite: ta pokrajina vam bodi na voljo, prebivajte in tržite po njej in posestniki postanite v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 11, 'In Sihem reče očetu deklice in bratom njenim: Milost naj najdem v vaših očeh, in kar mi ukažete, dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 12, 'Naložite mi kakorsibodi veliko doto in darilo, in dam, kolikor ukažete; samo dajti mi deklico za ženo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 13, 'Odgovoré pa sinovi Jakobovi zvijačno Sihemu in Hamorju, očetu njegovemu, ker je bil oskrunil Dino, njih sestro,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 14, 'ter jima reko: Ne moremo storiti tega, da damo sestro svojo možu neobrezancu, zakaj to nam je sramotno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 15, 'Vendar s tem pogojem vam privolimo: ako hočete biti nam enaki, da se med vami obreže vse moško,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 16, 'tedaj vam bomo dajali hčere svoje in si jemali hčere vaše, in prebivali bomo z vami in se združimo v eno ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 17, 'Ako pa nas ne boste poslušali, da se obrežete, vzamemo hčer svojo ter odidemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 18, 'In njih besede so ugajale Hamorju in Sihemu, Hamorjevemu sinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 19, 'In mladenič ni odlašal in je storil to, ker je imel veselje do hčere Jakobove; in on je bil najimenitnejši v vsej hiši očeta svojeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 20, 'Gresta torej Hamor in Sihem, sin njegov, k vratom svojega mesta in ogovorita someščane svoje, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 21, 'Ti možje so miroljubni proti nam, naj torej bivajo v deželi in tržijo po njej; saj dežela, glejte, je dovolj prostorna zanje; njih hčere si jemljimo za žene in hčere svoje dajajmo njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 22, 'Samo s tem pogojem nam privolijo oni možje, da bivajo z nami, da se združimo v eno ljudstvo, ako se med nami obrežejo vsi moški, kakor so obrezani oni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 23, 'Njih črede in njih posest in vsa njih živina ali ne bode naša? Samo privolimo jim, in prebivali bodo z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 24, 'Slušali so torej Hamorja in Sihema, sina njegovega, vsi, ki so hodili skozi vrata njegovega mesta, in obrezali so se vsi moški, vsi, ki so hodili skozi mestna vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 25, 'Zgodi se pa tretji dan, ko so bili v bolečinah, da vzameta dva sina Jakobova, Simeon in Levi, Dinina brata, vsak svoj meč ter napadeta tisto brezskrbno mesto ter pomorita vse moške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 26, 'Hamorja tudi in Sihema, sina njegovega, sta umorila z meča ostrino, ter vzameta Dino iz hiše Sihemove in odideta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 27, 'Sinovi Jakobovi planejo na pobite in oplenijo mesto, zato ker je odtod prišla oskrumba njih sestri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 28, 'Njih črede in njih goveda in osle, kar je bilo v mestu in kar je bilo na polju, vzemo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 29, 'tudi vse njih blago in vse njih otročiče in njih žene odvedo ujete in uplenijo sploh vse, kar je bilo v hišah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 30, 'Tedaj reče Jakob Simeonu in Leviju: V nesrečo sta me spravila, ker sta storila, da smrdim pri prebivalcih tega kraja, pri Kanaancu in Ferizejcu, ko imam le malo ljudi; če se zbero zoper mene, me pobijejo, in pokončan bom jaz in hiša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 34, 31, 'Ona pa rečeta: Ali naj se kakor z nečistnico dela s sestro našo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 1, 'Bog pa ukaže Jakobu: Vstani, idi gori v Betel in nastani se tam; in napravi tam oltar Bogu mogočnemu, ki se ti je prikazal, ko si bežal pred Ezavom, bratom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 2, 'In Jakob veli hiši svoji in vsem, ki so bili ž njim: Stran tuje bogove, ki so med vami, in očistite se ter preoblecite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 3, 'in vstanimo ter pojdimo gori v Betel, da napravim tam oltar Bogu mogočnemu, ki me je uslišal v dan stiske moje in mi je bil ob strani na potu, po katerem sem hodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 4, 'Izročé torej Jakobu vse tuje bogove, ki so bili v njih rokah, in obodce, ki so bili v njih ušesih; in Jakob jih zakoplje pod hrastom, ki je blizu Sihema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 5, 'Nato se napotijo, in strah Božji je navdajal mesta, ki so bila okrog njih, da niso podili sinov Jakobovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 6, 'In Jakob pride v Luz, ki je v deželi Kanaanski (to je Betel), on in vse ljudstvo, ki je bilo ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 7, 'In napravi tam oltar, in imenoval je tisto mesto El-Betel, ker se mu je bil ondi razodel Bog, ko je bežal pred bratom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 8, 'Umrla je pa Debora, Rebekina dojnica, in je bila pokopana pod hrastom doli za Betelom, zato ga je imenoval Alon bakut.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 9, 'Nato se prikaže Bog zopet Jakobu, ko je prišel iz Padan-arama, in ga blagoslovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 10, 'In mu reče Bog: Ime tvoje je Jakob; odslej se ne bo imenovalo ime tvoje Jakob, ampak Izrael bode ime tvoje; in imenoval je ime njegovo Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 11, 'Še mu reče Bog: Jaz sem Bog silni, Vsemogočni: rodoviten bodi in množi se; narod, da, množica narodov bodi iz tebe, tudi kralji naj pridejo iz ledij tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 12, 'Deželo pa, ki sem jo dal Abrahamu in Izaku, dam tebi, in semenu tvojemu za teboj dam deželo to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 13, 'In Bog je šel od njega na tistem mestu, kjer je govoril ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 14, 'In Jakob postavi spomenik na mestu, kjer je govoril ž njim, spomenik kamenen, in izlije nanj pitno daritev in ga oblije z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 15, 'In Jakob je dal mestu, kjer je Bog govoril ž njim, ime Betel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 16, 'In ko so zapustili Betel in je bilo še malo pota, da pridejo do Efrate, je imela Rahela težek porod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 17, 'In ko je trpela hude porodne bolečine, ji reče babica: Ne boj se, ker tudi zdaj imaš sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 18, 'In zgodi se, ko ji je uhajala duša in je umirala, da imenuje ime njegovo Benoni, ali oče njegov ga je imenoval Benjamina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 19, 'In umrla je Rahela in je bila pokopana na potu v Efrato (to je Betlehem).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 20, 'In Jakob postavi spomenik na njen grob, to je Spomenik Rahelinega groba do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 21, 'Nato se napoti Izrael in razpne šator svoj onkraj stolpa Ederja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 22, 'Zgodi se pa, ko je bival Izrael v tisti pokrajini, da je šel Ruben in ležal z Bilho, priležnico očeta svojega; in to je slišal Izrael. Bilo je pa sinov Izraelovih dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 23, 'Sinovi Leje: prvenec Jakobov Ruben, in Simeon in Levi in Juda, Isahar in Zebulon;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 24, 'sinova Rahele: Jožef in Benjamin;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 25, 'sinova pa Bilhe, ki je bila Rahelina dekla: Dan in Neftali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 26, 'in sinova Zilpe, ki je bila Lejina dekla: Gad in Aser. Ti so sinovi Jakobovi, ki so se mu rodli v Padan-aramu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 27, 'In pride Jakob k Izaku, očetu svojemu, v Mamro pri Kirjat-arbi, to je Hebron, kjer je nekdaj Abraham tujčeval in potem Izak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 28, 'Bilo je pa Izakovih dni sto osemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 35, 29, 'In izdihnil je Izak in umrl ter je bil zbran k ljudstvu svojemu, star in dni svojih sit; in pokopala sta ga Ezav in Jakob, sina njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 1, 'To pa so rodovi Ezava, ta je Edom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 2, 'Ezav je vzel žene svoje iz hčera Kanaanovih: Ado, hčer Elona Hetejca, in Oholibamo, hčer Anovo, vnukinjo Zibeona Hevejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 3, 'in Basemato, hčer Izmaelovo, sestro Nebajotovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 4, 'In rodila je Ada Ezavu Elifaza, Basemata pa je rodila Reguela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 5, 'In Oholibama je rodila Jeuša, Jalama in Koraha. Ti so sinovi Ezavovi, ki so se mu rodili v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 6, 'Ezav pa je vzel žene svoje in sinove in hčere svoje in vse domačine svoje, tudi drobnico in vso živino svojo in vso posest svojo, ki si jo je bil pridobil v deželi Kanaanski, in odšel je v drugo deželo, stran od Jakoba, brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 7, 'Kajti njuni imovini sta bili preobili, da bi mogla prebivati skupaj, in zemlja njunega tujčevanja jima je bila pretesna zavoljo njunih čred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 8, 'In prebival je Ezav na gori Seiru; Ezav, to je Edom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 9, 'To pa so rodovi Ezava, očeta Edomcev, na gori Seiru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 10, 'Ta so imena sinov Ezavovih: Elifaz, sin Ade, žene Ezavove; Reguel, sin Basemate, Ezavove žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 11, 'Sinovi pa Elifazovi: Teman, Omar, Zefo in Gatam in Kenaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 12, 'Timna pa je bila priležnica Elifaza, sinu Ezavovega, in je rodila Elifazu Amaleka. Ti so sinovi Ade, Ezavove žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 13, 'Ti pa so sinovi Reguelovi: Nahat in Zerah, Šama in Miza. Ti so bili sinovi Basemate, Ezavove žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 14, 'In ti so bili sinovi Oholibame, hčere Anove, vnukinje Zibeonove, Ezavove žene: rodila je Ezavu Jeuša, Jalama in Koraha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 15, 'To so vojvode sinov Ezavovih: sinovi Elifaza, prvenca Ezavovega: vojvoda Teman, vojvoda Omar, vojvoda Zefo, vojvoda Kenaz,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 16, 'vojvoda Korah, vojvoda Gatam, vojvoda Amalek. Ti so vojvode Elifazovi v deželi Edomovi; ti so sinovi Adini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 17, 'To pa so sinovi Reguela, sina Ezavovega: vojvoda Nahat, vojvoda Zerah, vojvoda Šama, vojvoda Miza. Ti so vojvode Reguelovi v deželi Edomovi; ti so sinovi Basemate, Ezavove žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 18, 'To pa so sinovi Oholibame, Ezavove žene: vojvoda Jeuš, vojvoda Jalam, vojvoda Korah. Ti so vojvode Oholibame, hčere Anove, Ezavove žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 19, 'Ti so sinovi Ezavovi in ti njih vojvode; to je Edom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 20, 'To so sinovi Seira Horejca, prejšnji prebivalci v deželi: Lotan, Šobal, Zibeon, Ana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 21, 'Dišon, Ezer in Dišan. Ti so vojvode Horejcev, sinov Seirovih, v deželi Edomovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 22, 'In sinova Lotanova sta bila: Hori in Hemam, in sestra Lotanova Timna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 23, 'Ti pa so sinovi Šobalovi: Alvan, Manahat in Ebal, Šefo in Onam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 24, 'In ta sta sinova Zibeonova: Aja in Ana. To je tisti Ana, ki je našel toplice v puščavi, ko je pasel osle Zibeonu, očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 25, 'Ta pa sta otroka Anova: Dišon in Oholibama, hči Anova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 26, 'In ti so sinovi Dišonovi: Hemdan, Ešban, Jitran in Keran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 27, 'Ti pa sinovi Ezerjevi: Bilhan in Zaavan in Akan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 28, 'Ta pa sinova Dišanova: Uz in Aran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 29, 'Ti so vojvode Horejcev: vojvoda Lotan, vojvoda Šobal, vojvoda Zibeon, vojvoda Ana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 30, 'vojvoda Dišon, vojvoda Ezer, vojvoda Dišan. To so vojvode Horejcev po njih vojvodstvih v deželi Seirski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 31, 'Ti pa so kralji, ki so kraljevali v deželi Edomovi, preden je vladal kralj sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 32, 'Bela, sin Beorjev, je zakraljeval na Edomskem, in ime mestu njegovemu je bilo Dinhaba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 33, 'in Bela je umrl, in zakraljeval je namesto njega Jobab, sin Zerahov iz Bozre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 34, 'In Jobab je umrl, in zakraljeval je namesto njega Hušam iz dežele Temančanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 35, 'In Hušam je umrl, in zakraljeval je namesto njega Hadad, sin Bedada, ki je pobil Madiane na poljani Moabski; in mestu njegovemu je bilo ime Avit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 36, 'In Hadad je umrl, in na mestu njegovem je zakraljeval Samla iz Masreke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 37, 'In Samla je umrl, in zakraljeval je namesto njega Savel iz Rehobota ob reki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 38, 'In Savel je umrl, in kraljeval je namesto njega Baal-hanan, sin Akborjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 39, 'In ko je umrl Baal-hanan, sin Akborjev, je zakraljeval namesto njega Hadar; in ime mestu njegovemu je bilo Pagu, ženi njegovi pa je bilo ime Mehetabela, hči Matrede, hčere Mezahabove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 40, 'In ta so imena vojvod Ezavovih, po njih rodbinah, po njih krajih, po njih imenih: vojvoda Timna, vojvoda Alva, vojvoda Jetet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 41, 'vojvoda Oholibama, vojvoda Ela, vojvoda Pinon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 42, 'vojvoda Kenaz, vojvoda Teman, vojvoda Mibzar,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 36, 43, 'vojvoda Magdiel, vojvoda Iram. Ti so bili vojvode Edomovi po svojih bivališčih, v deželi svoje posesti. To je Ezav, oče Edomcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 1, 'Jakob je torej bival v deželi tujčevanja očeta svojega, v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 2, 'Ti so rodovi Jakobovi: Jožef, star sedemnajst let, je pasel z brati svojimi čredo, in bil je kot deček pri sinovih Bilhe in pri sinovih Zilpe, žen očeta svojega. In Jožef je poročal njih očetu, kadar je šel hud glas o njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 3, 'Izrael pa je bolj ljubil Jožefa nego vse svoje sinove, zato ker mu je bil v starosti rojen, in naredil mu je dolgo, pisano suknjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 4, 'Ko so pa videli bratje njegovi, da ga bolj ljubi njih oče nego vse njegove brate, so ga sovražili in ga niso mogli prijazno ogovoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 5, 'Imel pa je Jožef sanje in jih je pripovedoval bratom svojim; zategadelj so ga še bolj sovražili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 6, 'Rekel jim je namreč: Poslušajte vendar sanje te, ki sem jih imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 7, 'Glejte, vezali smo snope na polju, in glejte, moj snop se je vzdignil in je stal, glejte pa, vaši snopi so hodili okrog in se priklanjali mojemu snopu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 8, 'Tedaj mu reko bratje njegovi: Hočeš li kar kraljevati nam ali kar gospodovati nam? In so ga še bolj sovražili zaradi sanj njegovih in zaradi njegovih besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 9, 'Nato je imel še druge sanje in jih je povedal bratom svojim ter rekel: Glejte, imel sem še sanje; glejte pa, solne in mesec in enajst zvezd se je klanjalo meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 10, 'Ko je pa pripovedoval očetu svojemu in bratom svojim, ga pokara oče in mu reče: Kake so te sanje, ki si jih imel? Pridemo li res jaz in mati tvoja in bratje tvoji, da se ti priklonimo do tal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 11, 'Zavidali so mu torej bratje njegovi, oče njegov pa je to besedo ohranil v misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 12, 'Ko so pa odšli bratje njegovi past čredo očeta svojega poleg Sihema,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 13, 'reče Izrael Jožefu: Ali ne paso bratje tvoji poleg Sihema? Pojdi, pošljem te k njim. On pa mu reče: Tukaj sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 14, 'Nato mu veli: Pojdi torej in poglej, ali so zdravi bratje tvoji in zdrava čreda, in sporoči mi kaj. Tako ga je poslal iz Hebronske doline, in Jožef krene proti Sihemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 15, 'Najde pa ga neki mož, ko je, glej, taval po polju, in vpraša ga tisti mož, rekoč: Kaj iščeš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 16, 'On pa reče: Brate svoje iščem; povej mi, prosim, kje neki pasejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 17, 'Mož pa reče: Šli so iz tega kraja, kajti slišal sem, ko so rekli: Pojdimo v Dotan. Jožef je šel torej za brati svojimi ter jih najde v Dotanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 18, 'Oni pa ga zagledajo oddaleč, in ko ni bil še prišel do njih, so skovali zvijačo zoper njega, da ga usmrte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 19, 'Reko namreč drug drugemu: Glejte, tisti gospod sanj prihaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 20, 'Sedaj torej, dejte, umorimo ga in vrzimo ga v enega tistih vodnjakov, pa porečemo: Huda zver ga je požrla; in bomo videli, kaj bode iz sanj njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 21, 'Ali ko je slišal Ruben, ga otme iz njih rok, rekoč: Ne udarimo ga smrtno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 22, 'In jim reče Ruben: Ne prelivajte krvi; vrzite ga v tisti vodnjak, ki je v puščavi, in ne položite roke nanj! – da bi ga otel iz njih rok ter ga pripeljal k svojemu očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 23, 'In zgodi se, ko je prišel Jožef k bratom svojim, da mu slečejo suknjo, tisto pisano, dolgo suknjo, s katero je bil oblečen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 24, 'in ga vzemo ter vržejo v tisti vodnjak. Vodnjak pa je bil prazen, vode ni bilo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 25, 'Nato sedejo, da použijejo kruh; in povzdignejo oči ter vidijo, in glej družbo popotnih Izmaelcev, ki so prihajali iz Gileada; njih velblodi otovorjeni z dišavami in mazilom in miro, in potovali so, da bi to prinesli v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 26, 'In Juda reče bratom svojim: Kaj bode dobička, če umorimo brata svojega in skrijemo kri njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 27, 'Dejte, prodajmo ga Izmaelcem, in roke naše naj se nad njim ne pregreše, zakaj brat je naš, meso naše. In poslušali so ga bratje njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 28, 'Ko so torej mimo šli kupci madianski, izvlečejo ter potegnejo Jožefa iz vodnjaka in ga prodado Izmaelcem za dvajset srebrnikov. Ti pa odpeljejo Jožefa v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 29, 'Ko se je pa vrnil Ruben k vodnjaku, glej, ni bilo Jožefa v vodnjaku; in raztrga oblačila svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 30, 'In se vrne k bratom svojim in reče: Dečka ni tu, jaz pa kam naj se obrnem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 31, 'Tedaj vzemo suknjo Jožefovo in zakoljejo kozliča in jo pomočijo v kri njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 32, 'Potem pošljejo tisto dolgo, pisano suknjo in jo velé nesti k njih očetu, ter reko: To smo našli; poglej vendar, je li ta suknja sinú tvojega ali ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 33, 'On pa jo je spoznal in reče: Suknja je sina mojega; huda zver ga je požrla; raztrgan, dá, raztrgan je Jožef!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 34, 'In Jakob raztrga oblačila svoja ter si ogrne ledja z žimovino, in žaloval je po sinu svojem mnogo dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 35, 'In vstali so vsi sinovi njegovi in vse hčere njegove, da bi ga tolažili, a branil se je tolažbe, govoreč: Ne, kajti doli pojdem žalosten k sinu svojemu v grob. In jokal je oče njegov za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 37, 36, 'Madiani pa ga prodado v Egipt Potifarju, dvorniku Faraonovemu, načelniku telesne straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 1, 'Zgodi se pa v tistem času, da je šel Juda od bratov svojih doli, in ustavi se pri nekem Adulamljanu, ki mu je bilo ime Hira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 2, 'In ko je Juda videl tam hčer nekega Kanaanca, ki mu je bilo ime Šuva, jo vzame ter se združi ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 3, 'In ona spočne ter rodi sina, ki ga je imenoval Gera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 4, 'Nato spočne v drugo ter rodi sina, ki ga je imenovala Onana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 5, 'Potem zopet rodi še sina in ga je imenovala Šela; bil je pa Juda v Kezibu, ko je tega rodila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 6, 'Juda pa vzame Geru, prvencu svojemu, ženo, ki ji je bilo ime Tamara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 7, 'A bil je Ger, prvenec Judov, hudoben v očeh Gospodovih; in Gospod ga je usmrtil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 8, 'Tedaj reče Juda Onanu: Združi se z ženo brata svojega in na ime bratovo jo vzemi in zbúdi seme svojemu bratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 9, 'Vedel je pa Onan, da tisto seme ne bode njegovo, zato ga je, kadar je šel k ženi brata svojega, iztresel na tla, da bi ne dal semena svojemu bratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 10, 'Ali hudobno je bilo v očeh Gospodovih, kar je počenjal; in usmrtil je tudi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 11, 'Zatorej reče Juda Tamari, snahi svoji: Ostani vdova v hiši svojega očeta, dokler ne doraste Šela, sin moj. Dejal je namreč: Da bi ne umrl tudi ta kakor bratje njegovi. In odide Tamara in ostane v hiši svojega očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 12, 'Ko pa je preteklo mnogo dni, umre hči Šuvova, Judova žena. In Juda, ko se je bil potolažil, je šel gori k strižcem črede svoje v Timno, on in Hira Adulamljan, prijatelj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 13, 'In sporoče Tamari, govoreč: Glej, tast tvoj gre gori v Timno strič ovce svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 14, 'In ona sleče oblačila vdovstva svojega, se odene z zagrinjačo ter sede pri vhodu v Enaim, ob potu proti Timni. Videla je namreč, da je Šela odrastel, ona pa da mu ni bila dana za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 15, 'Ko jo pa vidi Juda, meni, da je nečistnica, kajti zagrnila si je obličje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 16, 'Ustavi se torej pri njej ob potu ter reče: Dovoli mi, da se združim s teboj. Ni vedel namreč, da je snaha njegova. Ona pa reče: Kaj mi daš, da se združiš z menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 17, 'In on reče: Poslati ti hočem kozliča od črede. Ona pa reče: Daj mi zastavo, dokler mi ga ne pošlješ!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 18, 'Tedaj vpraša: Kakšno naj ti dam zastavo? In ona veli: Pečatnik svoj s trakom svojim in palico svojo, ki je v roki tvoji. In da ji to ter se združi ž njo, in spočela je od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 19, 'Nato vstane Tamara in odide ter sleče zagrinjačo svojo in obleče svojega vdovstva oblačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 20, 'Juda pa pošlje tistega kozliča po prijatelju svojem, onem Adulamljanu, da dobi nazaj zastavo od ženske; ali ne najde je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 21, 'In popraševal je može v njenem kraju, govoreč: Kje je tista ljubovnica, ki je bila v Enaimu pri potu? Reko: Ni bilo tu ljubovnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 22, 'Zato se vrne k Judi in reče: Nisem je našel; pa so tudi rekli ljudje tistega kraja: Ni bilo tu ljubovnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 23, 'In Juda reče: Naj si obdrži tisto! Da le ne prideva v zasmeh. Glej, poslal sem tega kozliča, ti pa je nisi našel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 24, 'Prigodi se pa blizu po treh mesecih, da so sporočili Judi, govoreč: Nečistovala je Tamara, snaha tvoja, in glej, tudi noseča je iz nečistovanja. In Juda reče: Peljite jo ven, da jo sežgo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 25, 'Ko so jo peljali ven, je poslala k tastu svojemu povedat: Od moža, čigaver je to, sem noseča. In reče: Spoznaj, prosim, čigavo je to: pečatnik in trak in palica ta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 26, 'In Juda je to spoznal in reče: Pravičnejša je od mene, zato ker je nisem dal Šelu, sinu svojemu. In ni je nikoli več spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 27, 'In ko pride čas njenega poroda, glej, dvojčka v njenem telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 28, 'In zgodi se, ko je rodila, da njiju eden pomoli roko, in babica vzame rdečo nit ter jo priveže na roko njegovo, rekoč: Ta je prišel prvi na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 29, 'In ko ta nazaj potegne roko svojo, glej, brat njegov pride na svet, in ona reče: Kako si ti predrl! tvoj je predor. Zato so ga imenovali Pereza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 38, 30, 'Potem pa izide brat njegov, na čigar roki je bila tista rdeča nit; in imenovali so ga Zeraha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 1, 'Jožefa torej pripeljejo doli v Egipt, in kupi ga Potifar, dvornik Faraonov, načelnik telesne straže, Egipčan, iz roke Izmaelcev, ki so ga bili pripeljali tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 2, 'A Gospod je bil ž Jožefom, in bil je mož, ki mu je šlo vse po sreči; in je bival v hiši gospodarja svojega, Egipčana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 3, 'In gospodar njegov je videl, da je Gospod ž njim in da vse, kar on počenja, pospešuje Gospod v roki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 4, 'In našel je Jožef milost v očeh njegovih in bil mu je za strežnika. In postavil ga je čez hišo svojo in vse, kar je imel, dal v roko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 5, 'In odkar ga je bil postavil čez hišo svojo in čez vse, kar je imel, je blagoslovil Gospod Egipčanovo hišo zaradi Jožefa, in bil je blagoslov Gospodov v vsem, kar je on imel, doma in na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 6, 'Zato je prepustil vse, kar je imel, roki Jožefovi, in ni se brigal za nobeno stvar pri njem razen za hrano, ki jo je sam užival. Bil je pa Jožef lepe postave in zalega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 7, 'Zgodi se pa po teh dogodkih, da nameri žena gospodarja njegovega oči svoje v Jožefa in reče: Lezi z menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 8, 'On pa se brani ter reče gospodarja svojega ženi: Glej, gospod moj se ne briga za nobeno stvar pri meni v hiši in vse, kar ima, je dal v roko mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 9, 'Še sam ni večji od mene v tej hiši, in ničesar mi ni odtegnil razen tebe, ker si žena njegova. Kako bi torej jaz storil toliko zlo in grešil zoper Boga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 10, 'In ko je ona ogovarjala Jožefa vsak dan, ni ji privolil, da bi ležal poleg nje, niti da bi se mudil ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 11, 'Zgodi se pa nekega takega dne, ko je prišel domov opravljat delo svoje, da ni bilo nikogar iz domačinov tam notri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 12, 'Tedaj ga zgrabi ona za obleko njegovo, rekoč: Lezi z menoj! On pa pusti obleko svojo v njeni roki in pobegne ter gre iz hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 13, 'Ko pa je videla, da je pustil obleko svojo v njeni roki in pobegnil iz hiše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 14, 'pokliče domačine svoje in jim reče: Glejte, pripeljal nam je moža Hebrejca, da nas sramoti. Ta je prišel k meni, da bi ležal z menoj, ali zavpila sem z glasom velikim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 15, 'in ko je slišal, da sem zagnala glas in klicala, je pustil obleko svojo poleg mene in pobegnil in šel iz hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 16, 'Položi pa obleko njegovo poleg sebe, dokler pride gospodar njegov v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 17, 'Nato ga ogovori s takimi besedami, rekoč: Prišel je k meni tisti hlapec Hebrejec, ki si ga nam pripeljal, da bi me sramotil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 18, 'Toda ko sem zagnala glas in klicala, je pustil obleko svojo poleg mene in pobegnil iz hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 19, 'In ko je gospodar njegov slišal žene svoje besede, s katerimi mu je povedala, rekoč: Takole mi je storil hlapec tvoj, se silno razsrdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 20, 'In zgrabi Jožefa gospodar njegov ter ga dene v stolp, v kraj, kjer so bili zvezani kraljevi jetniki; in bil je tam v stolpu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 21, 'Ali Gospod je bil z Jožefom in naklonil mu je blagovoljnost in mu dal milost svojo pred očmi načelnika stolpu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 22, 'In načelnik stolpa je dal Jožefu v roko vse zvezane v stolpu; in vse, kar so tam delali, je vodil on.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 39, 23, 'Načelnik stolpa ni gledal na nobeno stvar, ki je bila v roki Jožefovi, zato ker je bil Gospod ž njim, in kar je počel, vse je pospeševal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 1, 'Zgodi se pa po teh dogodkih, da sta se pregrešila točaj in pek kralja egiptovskega zoper gospoda svojega, kralja egiptovskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 2, 'In Faraon se raztogoti zoper dvornika svoja, zoper velikega točaja in zoper velikega peka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 3, 'in dene ju v zapor v hišo načelnika telesne straže, v stolp, tja, kjer je bil zvezan Jožef.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 4, 'In načelnik telesne straže jima je odkazal Jožefa, da jima je stregel; in bila sta nekaj časa v ječi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 5, 'Imela sta pa sanje oba, vsak sanje svoje v isti noči, vsak primerne razlagi sanj svojih, točaj in pek kralja egiptovskega, ki sta bila zvezana v stolpu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 6, 'In Jožef pride zjutraj k njima in ju pogleda, in glej, žalostna sta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 7, 'In vpraša dvornika Faraonova, ki sta bila ž njim v ječi v hiši njegovega gospoda, rekoč: Zakaj sta obraza vajina žalostna danes?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 8, 'Ona pa mu rečeta: Sanje sva imela oba, ali nikogar ni, da jih razloži. In Jožef jima reče: Ali ni razlaganje od Boga? Povejta mi, prosim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 9, 'Pove torej veliki točaj sanje svoje Jožefu in mu reče: V sanjah mojih, glej, je bila vinska trta pred menoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 10, 'in na trti tri mladike; in trta je ravno poganjala in se razcvetla, in šopki cvetja njenega so zoreli v jagode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 11, 'In bila je kupa Faraonova v roki moji, in trgal sem zrele grozde in jih izžemal v kupo Faraonovo; in podal sem kupo Faraonu v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 12, 'Jožef pa mu reče: To je njih razlaga: Tri mladike so trije dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 13, 'Ko bode še tretji dan, poviša Faraon glavo tvojo in te postavi nazaj v službo tvojo, in podajal boš kupo Faraonovo v roko njegovo po navadi prejšnji, ko si bil točaj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 14, 'Samo spomni se mene pri sebi, ko se ti bo dobro godilo, in izkaži mi, prosim, milost in me omeni pred Faraonom, da bi me izpeljal iz te hiše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 15, 'zakaj prav po tatinsko sem bil ukraden iz dežele Hebrejske, in tudi tukaj nisem storil ničesar, za kar naj sem bil dejan v to temnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 16, 'Ko je pa videl veliki pek, da je dobro razložil, reče Jožefu: Tudi v mojih sanjah so bile, glej, tri pletenice z belim pecivom na glavi moji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 17, 'v najvišji pletenici pa so bila vsakovrstna jedila za Faraona, izdelki pekovski; in ptiči so jih zobali iz pletenice, ki sem jo imel na glavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 18, 'Jožef odgovori in reče: To je njih razlaga: Tri pletenice so trije dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 19, 'Ko bode še tretji dan, poviša Faraon glavo tvojo, da jo izgubiš, in te obesi na les, in ptiči bodo zobali meso tvoje s tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 20, 'In zgodi se tretji dan, ki je bil dan Faraonovega rojstva, da je napravil pojedino vsem služabnikom svojim, in povišal je glavo velikega točaja in glavo velikega peka med svojimi služniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 21, 'In velikega točaja je postavil zopet v službo njegovo, in podajal je kupo Faraonu v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 22, 'Velikega peka pa je dal obesiti, kakor jima je bil razložil Jožef.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 40, 23, 'A veliki točaj se ni spomnil Jožefa, temuč ga je pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 1, 'Zgodi se pa, ko so pretekli dveh let dnevi, da se je Faraonu sanjalo, in glej, stoji ob Nilu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 2, 'Glej pa, iz reke stopa sedem krav, lepih in debelih, in pasle so se po travi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 3, 'In glej, sedem drugih krav pride za njimi iz reke, grdih in suhih, in postavijo se poleg onih krav na bregu reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 4, 'Tiste grde in suhe krave pa požro onih sedem lepih in debelih krav. Tedaj se prebudi Faraon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 5, 'Ali zopet zaspi, in sanja se mu v drugič. In glej, sedem klasov je zraslo na enem steblu, polnih in lepih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 6, 'Glej pa, sedem klasov drobnih, ki jih je vzhodni veter osmodil, požene za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 7, 'Drobni klasovi pa pogoltnejo sedem debelih in polnih klasov. In ko se Faraon zbudi, glej, sanje so bile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 8, 'In zjutraj, ko je bila zbegana duša njegova, pošlje in pokliče vse egiptovske pismouke in vse modrijane; njim pove Faraon sanje svoje, ali nobenega ni bilo, da bi jih razložil Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 9, 'Tedaj ogovori veliki točaj Faraona in reče: Svojih grehov se spominjam danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 10, 'Faraon se je raztogotil zoper hlapce svoje in me je dejal v zapor v hiši načelnika telesne straže, mene in velikega peka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 11, 'Imela sva pa sanje v isti noči jaz in on; primerno razlagi najinih sanj se je sanjalo nama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 12, 'Bil je pa tam z nama mladenič Hebrejec, hlapec načelnika telesne straže, ki nama je sanje najine razložil, kakor sva mu povedala; vsakemu primerno sanjam njegovim je razložil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 13, 'In zgodilo se je tako, kakor je nama razložil: mene je postavil Faraon zopet v službo mojo, onega pa je obesil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 14, 'Pošlje torej Faraon in pokliče Jožefa, in hitro so ga pustili iz temnice; in ko se je obril in preoblekel, pride k Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 15, 'Tedaj reče Faraon Jožefu: Imel sem sanje, a ni nikogar, da bi jih razložil. Slišal sem pa o tebi praviti: ko čuješ sanje, jih lahko razložiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 16, 'Odgovori pa Jožef Faraonu in reče: To ni moja reč: Bog bo odgovoril, kar je v srečo Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 17, 'Reče torej Faraon Jožefu: V sanjah svojih, glej, sem stal na bregu Nila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 18, 'In glej, iz reke stopa sedem krav, debelih in lepih, in pasle so se po travi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 19, 'Nato, glej, pride sedem drugih krav za njimi, suhih in zelo grdih in mršavih; nisem videl po grdosti njim podobnih v vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 20, 'In požrle so te krave mršave in grde prejšnjih sedem krav debelih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 21, 'in dasi so jim prišle v trebuh, ni bilo tega zaznati, ampak bile so videti grde kakor poprej. In prebudil sem se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 22, 'Še sem videl v sanjah svojih, in glej, sedem klasov je zraslo na enem steblu, polnih in lepih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 23, 'Glej pa, sedem klasov drobnih in suhih, ki jih je vzhodni veter osmodil, je pognalo za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 24, 'Tisti drobni klasi pa so pogoltnili sedem lepih klasov. In to sem povedal pismoukom, a nobenega ni bilo, ki bi mi razložil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 25, 'Tedaj reče Jožef Faraonu: Sanje Faraonove so ene: kar hoče storiti Bog, je razodel Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 26, 'Tistih sedem krav lepih je sedem let, in tistih sedem klasov lepih je sedem let; sanje so ene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 27, 'Sedem krav pa, mršavih in grdih, ki so prišle za onimi, je sedem let, tudi sedem klasov praznih, ki jih je vzhodni veter osmodil, je sedem let lakote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 28, 'To je beseda, ki sem jo rekel Faraonu: Kar hoče Bog storiti, je pokazal Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 29, 'Glej, sedem let pride, ko bo velika obilost po vsej Egiptovski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 30, 'A za njimi pride sedem let lakote, v katerih se pozabi vsa tista obilost po deželi Egiptovski: trla namreč bo lakota to deželo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 31, 'in nič se ne bo vedelo v deželi za obilost zavoljo lakote, ki pride potem, zato ker huda bode silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 32, 'Da so se pa ponovile sanje Faraonu dvakrat, pomeni, da je Bog to stvar trdno sklenil, in Bog jo v kratkem izpolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 33, 'Zdaj torej naj poskrbi Faraon za moža razumnega in modrega in ga naj postavi čez deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 34, 'To naj stori Faraon in postavi naj oblastnike tej deželi, da pobere petino pridelkov dežele Egiptovske v sedmih letih obilosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 35, 'Oni naj zbero vse žito dobrih let, ki pridejo, in zneso naj žito Faraonu pod roko, v živež po mestih, in ga shranijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 36, 'In ta živež bodi v zalogo deželi za tistih sedem let lakote, ki bode v deželi Egiptovski, da ne pogine dežela od lakote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 37, 'In ta beseda je bila dobra v očeh Faraonovih in v očeh vseh služabnikov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 38, 'In Faraon reče služabnikom svojim: Najdemo li mar temu enakega moža, ki je v njem duh Božji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 39, 'Nato veli Faraon Jožefu: Ker ti je Bog razodel vse to, nihče ni razumen in moder kakor ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 40, 'Ti bodeš čez hišo mojo in po povelju tvojem se bo ravnalo ljudstvo moje, samo za ta prestol bodem višji od tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 41, 'Dalje reče Faraon Jožefu: Glej, stavim te čez vso deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 42, 'In Faraon sname pečatni prstan z roke svoje ter ga natakne na roko Jožefovo in veli mu obleči oblačila iz tenčice in zlato verižico mu dene okoli vratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 43, 'In ukaže, naj ga peljejo na drugem vozu njegovem, in klicali so pred njim: Priklonite se! In postavil ga je čez vso deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 44, 'In reče Faraon Jožefu: Jaz sem Faraon, a brez tebe ne vzdigne nihče roke svoje ali noge svoje po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 45, 'Imenoval pa je Faraon ime Jožefovo Zafnat-paneah, in dal mu je za ženo Asnato, hčer Potiferja, svečenika v Onu. In Jožef je šel vladat deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 46, 'Imel pa je Jožef trideset let, ko je stal pred Faraonom, kraljem egiptovskim. In Jožef je šel izpred obličja Faraonovega in je obhodil vso deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 47, 'Rodila je pa zemlja v sedmih letih obilosti, kolikor so le nabrati mogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 48, 'Zbral je torej vse žito sedmih dobrih let, ki so bila v deželi Egiptovski, in shranil je živež po mestih; žito s polja okrog vsakega mesta je shranil v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 49, 'Tako je nabral Jožef žita silno mnogo, kakor peska morskega, da so nehali šteti, ker ga je bilo brez števila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 50, 'Jožefu pa sta se rodila dva sina, preden je prišlo leto lakote, katera mu je rodila Asnata, hči Potiferja, svečenika onskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 51, 'In imenoval je Jožef prvenca Manaseja, kajti, reče, Bog mi je dal pozabiti vse trpljenje moje in vso hišo mojega očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 52, 'Drugega pa je imenoval Efraima, kajti, reče, rodovitnega me je naredil Bog v deželi ponižanja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 53, 'In ko je preteklo sedem let obilosti, ki je bila v deželi Egiptovski,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 54, 'je nastopilo sedem let lakote, kakor je bil povedal Jožef, in bila je lakota po vseh deželah, v vsej pa deželi Egiptovski je bilo kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 55, 'In ko je vsa dežela Egiptovska trpela lakoto, je vpilo ljudstvo k Faraonu zaradi kruha; Faraon pa reče vsem Egipčanom: Pojdite k Jožefu, in kar vam veli, storite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 56, 'In lakota je bila po vsem površju zemlje. In Jožef je odprl vsa skladišča in prodajal Egipčanom, ker je lakota hudo stiskala deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 41, 57, 'In iz vseh dežel so hodili v Egipt k Jožefu kupovat, zato ker je lakota hudo stiskala vso zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 1, 'Ko je torej videl Jakob, da je žita v Egiptu, reče sinom svojim: Kaj gledate drug drugega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 2, 'Glejte, veli, slišal sem, da je žita v Egiptu; idite tja doli in nakupite nam ondi, da bomo živeli in ne umremo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 3, 'Šlo je torej deset bratov Jožefovih doli nakupit žita iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 4, 'Benjamina pa, brata Jožefovega, ni poslal Jakob z brati njegovimi, ker je dejal: Da ga ne zadene nesreča!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 5, 'In pridejo sinovi Izraelovi kupovat med drugimi, ki so prihajali, kajti lakota je bila v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 6, 'Jožef pa je bil vladar v deželi, on je vodil prodajo vsemu ljudstvu dežele; ko so torej prišli bratje Jožefovi, se mu priklonijo ponižno do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 7, 'In Jožef, ko je videl brate svoje, jih spozna, toda delal se jim je tujega, ter jih ogovori trdo in vpraša: Odkod ste prišli? Reko mu: Iz dežele Kanaanske kupit živeža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 8, 'Spoznal je torej Jožef brate svoje, a oni ga niso spoznali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 9, 'In spomni se Jožef tistih sanj, ki jih je imel o njih, in jim reče: Ogleduhi ste, prišli ste ogledovat nezavarovane kraje v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 10, 'Oni pa mu reko: Ne, gospod moj, hlapci tvoji so prišli kupit žita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 11, 'Mi vsi smo sinovi enega moža; pošteni smo, nikdar niso bili ogleduhi hlapci tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 12, 'On pa jim reče: Nikakor, marveč prišli ste ogledovat nezavarovane kraje v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 13, 'In reko: Dvanajst je bilo hlapcev tvojih; bratje smo, sinovi enega moža v deželi Kanaanski: najmlajši, glej, je sedaj pri očetu našem, enega pa ni več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 14, 'Veli jim Jožef: To je tisto, kar sem vam rekel: Ogleduhi ste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 15, 'To bodi izkušnja vaša: kakor res živi Faraon, ne pojdete odtod, dokler ne pride sem brat vaš najmlajši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 16, 'Pošljite enega izmed sebe, ki naj pripelje brata vašega; vi pa bodite jetniki, da se preizkusijo besede vaše, je li resnica pri vas; če pa ne, kakor res živi Faraon, ste ogleduhi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 17, 'In jih dene vse skup v zapor tri dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 18, 'Potem jim reče Jožef tretji dan: To storite in si ohranite življenje – Boga se bojim jaz:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 19, 'če ste pošteni, naj ostane eden brat vaš zvezan na mestu ječe vaše; vi pa pojdite, odnesite žito, da ne stradajo rodbine vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 20, 'Najmlajšega brata svojega pa pripeljite k meni, in resnične se izkažejo besede vaše in ne umrete. In oni store tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 21, 'Reko pa drug drugemu: Res, krivi smo zaradi svojega brata, ki smo videli bridkost duše njegove, ko nas je prosil usmiljenja, a nismo poslušali; zato nas je zadela ta stiska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 22, 'In odgovori jim Ruben: Ali vam nisem prigovarjal, rekoč: Ne grešite zoper dečka? Pa me niste poslušali; zato se tudi sedaj, glejte, zahteva kri njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 23, 'Niso pa vedeli, da Jožef ume, zato ker je bil tolmač med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 24, 'In obrne se od njih, in je jokal. A zopet se vrne k njim in govori ž njimi. In vzame izmed njih Simeona in ga zveže pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 25, 'In zapove Jožef, da naj napolnijo njih priprave z žitom ter jim vrnejo denar vsakemu v njegovo vrečo in jim podele brašna na pot. In so jim storili tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 26, 'Nalože torej žito svoje na osle in odidejo odondod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 27, 'Ko je pa razvezal eden vrečo svojo, da bi dal klaje svojemu oslu na prenočišču, zagleda denar svoj, ki je bil, glej, zvrha v vreči njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 28, 'In reče bratom svojim: Vrnil se mi je denar moj, in glejte ga v vreči moji! In upade jim srce in prestrašijo se ter reko drug drugemu: Kaj nam je to storil Bog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 29, 'In ko pridejo k Jakobu, očetu svojemu v deželo Kanaansko, mu povedo vse, kar se jim je prigodilo, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 30, 'Trdo je z nami govoril tisti mož, one dežele gospod, in sprejel nas je kakor ogleduhe dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 31, 'In rekli smo mu: Pošteni smo, nikdar nismo bili ogleduhi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 32, 'Dvanajst nas je bratov, sinov našega očeta: enega ni več in najmlajši je ta čas pri očetu našem v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 33, 'In reče nam tisti mož, one dežele gospod: Tako bom spoznal, da ste pošteni: brata izmed sebe enega pustite pri meni in tisto, česar stradajo rodbine vaše, vzemite ter odidite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 34, 'in pripeljite brata svojega najmlajšega k meni, da spoznam, da niste ogleduhi, ampak poštenjaki. In brata vašega vam vrnem, in tržiti boste smeli po tej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 35, 'Ko so pa praznili vreče svoje, glej, vsak je imel svoj zavitek denarja v vreči svoji; in ko so videli zavitke svojega denarja, so se bali oni in njih oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 36, 'In Jakob, njih oče, jim reče: Pripravite me ob otroke! Jožefa ni več, in Simeona ni več, in Benjamina bi mi radi vzeli; zoper mene je vse to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 37, 'A Ruben ogovori očeta svojega in reče: Ta dva sinova moja daj v smrt, ako ga ne pripeljem zopet k tebi. Daj ga meni v roko, in jaz ga pripeljem zopet k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 42, 38, 'On pa veli: Ne pojde doli sinček moj z vami; zakaj brat njegov je umrl, in ta je sam ostal, in če njega zadene nesreča na potu, na katerega se pripravljate, spravite sivo glavo mojo z žalostjo v grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 1, 'V tem je lakota jako stiskala deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 2, 'In ko so pojedli živež, ki so ga bili prinesli iz Egipta, jim veli njih oče: Pojdite zopet, kupite nam malo hrane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 3, 'A Juda mu odgovori in reče: Resno nam je zatrdil oni mož in rekel: Videli ne boste obličja mojega, ako ne bode brata vašega z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 4, 'Če hočeš poslati brata našega z nami, pojdemo doli in ti kupimo žita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 5, 'Ako ga pa nočeš poslati, ne pojdemo doli, zakaj oni mož nam je rekel: Videli ne boste obličja mojega, ako ne bode brata vašega z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 6, 'Tedaj reče Izrael: Zakaj ste mi tako hudo storili, ko ste povedali onemu možu, da imate še brata?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 7, 'Oni pa reko: Skrbno je popraševal tisti mož po nas in sorodovini naši, govoreč: Ali še živi vaš oče? imate li še brata? In povedali smo mu po tistih besedah. Kako smo neki mogli vedeti, da poreče: Pripeljite s seboj brata svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 8, 'In reče Juda Izraelu, svojemu očetu: Pošlji dečka z menoj, in vstanimo ter odidimo, da si ohranimo življenje in ne umremo, mi in ti in otročiči naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 9, 'Jaz sem porok zanj, iz moje roke ga zahtevaj; če ti ga ne pripeljem in ga ne postavim predte, naj bom kriv zoper tebe vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 10, 'Kajti ko bi ne bili odlašali, bi se bili že dvakrat vrnili v tem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 11, 'Veli torej Izrael, njih oče: Če mora biti tako, storite to: vzemite od najboljših pridelkov naše dežele v posodah svojih in nesite darilo onemu možu: malo balzama in malo medu, dišav in mire, kločkov in mandljev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 12, 'Denarja tudi vzemite dvojno v roko svojo, in tisti denar, ki je bil vrnjen zvrha v vrečah vaših, nesite nazaj v roki svoji, nemara je bila pomota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 13, 'Tudi brata svojega vzemite ter vstanite, vrnite se k onemu možu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 14, 'In Bog silni, Vsemogočni vam daj usmiljenje pred tistim možem, da vam izpusti onega brata vašega in Benjamina. Jaz pa, če bodem brez otrok, naj bom brez otrok!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 15, 'Možje torej vzemo tisto darilo in denarja še enkrat toliko v roko svojo in Benjamina, ter vstanejo in odidejo doli v Egipt ter stopijo pred obličje Jožefovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 16, 'Ko je videl Jožef Benjamina ž njimi, veli upravniku hiše svoje: Pelji noter te može in zakolji živali ter pripravi, z menoj namreč bodo jedli ti možje opoldne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 17, 'In mož stori, kakor je ukazal Jožef; in peljal je može v hišo Jožefovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 18, 'Ali bali so se možje, ker jih je peljal v Jožefovo hišo, in so rekli: Zaradi tistega denarja, ki je bil vrnjen prej v vreče naše, nas pelje noter, da zvrne to na nas in plane na nas in vzame za sužnje nas z našimi osli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 19, 'In pristopijo k možu, ki je upravljal hišo Jožefovo, in ga ogovore pred vrati hiše');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 20, 'in reko: Prosim, gospod moj! Prišli smo bili že preje kupit žita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 21, 'Ko smo pa prišli v prenočišče in razvezali vreče svoje, glej, denar vsakega je bil na vrhu v vreči njegovi, prav denar naš po teži svoji; prinesli smo ga torej nazaj v rokah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 22, 'In še drugega denarja smo prinesli sem v rokah svojih, da kupimo žita. Ne vemo, kdo je položil denar naš v vreče naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 23, 'In on reče: Mir vam, ne bojte se! Bog vaš in očeta vašega Bog vam je dal zaklad v vreče vaše; denar vaš sem prejel. In privede k njim Simeona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 24, 'In mož jih pripelje v hišo Jožefovo in jim da vode, da si umijejo noge, in da tudi klaje njih oslom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 25, 'V tem so pripravljali darilo svoje, da ga izroče, kadar pride Jožef opoldne; zakaj slišali so, da bodo tam obedovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 26, 'Ko je pa Jožef prišel domov, prineso noter k njemu darilo, ki so ga imeli v rokah svojih, in priklonijo se mu do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 27, 'In on jih vpraša, kako se jim godi, ter reče: Ali se dobro godi vašemu očetu, starčku, o katerem ste govorili? Ali še živi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 28, 'Oni pa reko: Dobro se godi hlapcu tvojemu, našemu očetu, še živi. In pripognejo teme in se priklonijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 29, 'In povzdigne oči in zagleda Benjamina, brata svojega, matere svoje sina, ter reče: Tale je tisti brat vaš najmlajši, o katerem ste mi govorili? In veli: Bog ti bodi milosten, sin moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 30, 'In Jožef odhiti, ker mu je srce gorelo do brata svojega, in poišče, kje bi se izjokal; in vstopi v stanico svojo, ter je jokal v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 31, 'Potem si umije obraz in pride ven ter, premagujoč se, reče: Prinesite jed!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 32, 'In prineso njemu posebe in njim posebe in Egipčanom, ki so ž njim jedli, posebe, zakaj Egipčani ne smejo jesti s Hebrejci, ker to je nagnusno Egipčanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 33, 'Sedeli so pa pred njim, prvenec po prvenstvu svojem in mlajši po mlajših letih svojih; in čudeč se so gledali ti možje drug drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 43, 34, 'In jemaje jedi pred seboj, je pošiljal k njim, in večji je bil petkrat delež Benjaminov nego kateregakoli izmed njih. Tako so se gostili in dosti so pili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 1, 'Nato zapove upravniku hiše svoje: Napolni vreče teh mož z žitom, kolikor bodo mogli nesti, in položi denar vsakega zgoraj v vrečo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 2, 'Kupo mojo pa, kupo srebrno, deni na vrh v vrečo najmlajšega in denar za žito njegovo. In stori po besedi Jožefovi, ki jo je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 3, 'Danilo se je že, ko so odpustili može ž njih osli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 4, 'Še niso bili prišli daleč iz mesta, ko veli Jožef upravniku hiše svoje: Vstani in híti za možmi, in ko jih dojdeš, jim reci: Zakaj vračate hudo za dobro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 5, 'Ali ni tisto, iz česar pije gospod moj in s česar pomočjo prorokuje? Hudo ste ravnali, ko ste storili to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 6, 'Dojde jih torej in ogovori s takimi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 7, 'Oni pa mu reko: Zakaj govori gospod naš take besede? Tega ne, da bi hlapci tvoji bili storili tako stvar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 8, 'Glej, denar, ki smo ga našli zvrha v vrečah svojih, smo prinesli zopet k tebi iz dežele Kanaanske: kako bi bili torej ukradli iz hiše gospoda tvojega srebro ali zlato?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 9, 'Pri katerem izmed hlapcev tvojih se najde, on naj umre, in tudi mi bodemo hlapci našemu gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 10, 'On pa reče: Bodi torej po vaši besedi: pri katerem se najde, on mi bodi hlapec, vi pa bodite nedolžni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 11, 'Hitro so torej deli vsak svojo vrečo na tla, in vsak razveže svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 12, 'In on je preiskoval, pri najstarejšem je začel in pri najmlajšem končal: našel pa je kupo v vreči Benjaminovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 13, 'Tedaj raztrgajo oblačila svoja in nalože tovor vsak na svojega osla, in se vrnejo v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 14, 'In Juda vstopi z brati svojimi v hišo Jožefovo, ko je bil on še tam, in popadajo pred obličje njegovo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 15, 'Jožef pa jim reče: Kakšna je to pregreha, ki ste jo storili? Niste li vedeli, da mož, kakršen sem jaz, more prorokovati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 16, 'Tedaj reče Juda: Kaj bi rekli gospodu svojemu? kaj bi pravili? ali kako bi se opravičili? Bog sam je našel krivico hlapcev tvojih. Glej, mi smo hlapci svojemu gospodu, mi in on, v čigar roki se je našla tista kupa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 17, 'In on veli: Ne tako, da bi jaz to storil! Mož, v čigar roki se je našla kupa, on mi bodi hlapec, vi pa pojdite v miru k očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 18, 'Ali Juda pristopi k njemu in reče: Prosim, gospod moj, govori naj hlapec tvoj besedo v prijazen posluh gospoda svojega, in ne razsrdi se zoper hlapca svojega: ti namreč si prav kakor Faraon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 19, 'Gospod moj je vprašal hlapce svoje in rekel: Imate li očeta ali brata?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 20, 'Rekli pa smo gospodu svojemu: Imamo očeta starčka in mladega dečka, ki se mu je rodil v starosti, brat njegov pa je umrl, in ostal je sam od matere svoje in ljubček je očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 21, 'In rekel si hlapcem svojim: Dejte, da pride doli k meni in ga vidim s svojimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 22, 'In čeprav smo rekli svojemu gospodu: Deček ne more zapustiti svojega očeta; ako ga zapusti, umre oče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 23, 'si dejal hlapcem svojim: Ako ne pride doli brat vaš najmlajši z vami, ne boste več videli mojega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 24, 'Ko smo pa prišli gori k hlapcu tvojemu, svojemu očetu, smo mu sporočili besede gospoda svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 25, 'Ko je potem rekel naš oče: Pojdite zopet, kupite nam malo žita,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 26, 'smo odgovorili: Ne moremo iti doli; samo če bode brat naš najmlajši z nami, pojdemo; ker ne smemo videti obličja onega moža, ako ne bode brata našega najmlajšega z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 27, 'In rekel nam je hlapec tvoj, moj oče: Vi veste, da mi je dva rodila žena moja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 28, 'prvi je šel od mene, in rekel sem: Gotovo je raztrgan, in nisem ga videl do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 29, 'Ako torej odpeljete še tegale izpred mojega obličja in ga zadene nesreča, pripravite sivo glavo mojo od nesreče v grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 30, 'Zdaj torej, kadar pridem k hlapcu tvojemu, svojemu očetu, in tega dečka ne bode z nami, ko je očetova duša zvezana ž njegovo dušo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 31, 'se zgodi, da umre, ko bo videl, da ni tu dečka: tako bodo hlapci tvoji sivo glavo hlapca tvojega, našega očeta, z žalostjo spravili v grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 32, 'Hlapec tvoj je namreč postal porok za dečka pred očetom svojim, ker je rekel: Ako ti ga ne pripeljem, kriv naj bodem zoper očeta svojega vse žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 33, 'Zdaj torej naj ostane, prosim, hlapec tvoj namesto dečka kot suženj svojemu gospodu, deček pa naj gre gori z brati svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 44, 34, 'Kajti kako naj grem gori k očetu svojemu, ko dečka ne bode z menoj? ne, naj ne vidim bridkosti, ki bo zgrabila mojega očeta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 1, 'Tedaj se Jožef ni mogel več premagovati vpričo vseh, ki so stali okrog njega, in zavpije: Dejte, da gredó vsi ven od mene! In nihče ni ostal pri njem, ko se je Jožef dal spoznati bratom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 2, 'Tedaj zažene glas svoj z jokom, tako da so slišali Egipčani, slišala je tudi hiša Faraonova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 3, 'In Jožef reče bratom svojim: Jaz sem Jožef! Ali še živi oče moj? A niso mu mogli odgovoriti bratje njegovi, ker zbegani so bili pred obličjem njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 4, 'Zato reče Jožef bratom svojim: Pristopite sem k meni! In pristopijo. Nato reče: Jaz sem Jožef, brat vaš, ki ste ga prodali v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 5, 'Ali sedaj se ne žalite in ne jezite se sami nad seboj, da ste me prodali sem: zakaj Bog me je poslal pred vami, da ohrani življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 6, 'Že je namreč dve leti lakota v deželi; še je pa pet let, v katerih ne bo oratve, ne žetve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 7, 'Toda Bog me je poslal pred vami, da vam zavaruje ostanek na zemlji in vas ohrani v življenju za veliko rešitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 8, 'Tako torej, nikakor me niste vi poslali sem, temuč Bog, ki me je postavil za očeta Faraonu in za gospodarja vsej hiši njegovi ter za oblastnika vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 9, 'Hitite in pojdite gori k očetu mojemu ter mu recite: Tako pravi sin tvoj Jožef: Postavil me je Bog za gospoda vsemu Egiptu; pridi doli k meni, ne odlašaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 10, 'In boš prebival v deželi Gosenski, in blizu mi bodeš ti in sinovi tvoji in sinov tvojih sinovi in črede tvoje in goveda tvoja in vse, kar imaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 11, 'In živil te bom tam, ker še pet let bode lakota, da ne obubožaš ti in rodbina tvoja in vse, kar imaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 12, 'Glejte pa, oči vaše vidijo in oči brata mojega Benjamina, da usta moja so, ki z vami govore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 13, 'Sporočite torej očetu mojemu vso slavo mojo v Egiptu in karkoli ste videli, in hitro pripeljite sem mojega očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 14, 'Nato se oklene vratu brata svojega Benjamina in se zjoka, tudi Benjamin je jokal ob vratu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 15, 'In poljubi vse brate svoje in joka ob njih vratu. Potem šele izpregovore bratje njegovi ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 16, 'In ko se je zaslišal ta glas v hiši Faraonovi, govoreč: Prišli so bratje Jožefovi, je bilo všeč Faraonu in služabnikom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 17, 'In Faraon veli Jožefu: Reci bratom svojim: To storite: obložite živino svojo in odpotujte, in ko pridete v deželo Kanaansko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 18, 'vzemite očeta svojega in rodbine svoje, ter vrnite se k meni; in dati vam hočem, kar je najboljšega v deželi Egiptovski, in uživali boste tolščobo zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 19, 'Ti pa imaš ukaz: To storite: vzemite si iz dežele Egiptovske voz za otročiče svoje in za žene svoje ter naložite očeta svojega, in vrnite se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 20, 'Oko vaše pa naj se ne žali za pohištvo vaše, kajti kar je najboljšega v vsej deželi Egiptovski, vaše je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 21, 'In sinovi Izraelovi so storili tako; in dal jim je Jožef voz po ukazu Faraonovem, dal jim tudi brašna na pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 22, 'In dal jim je vsakemu posebe praznično obleko, Benjaminu pa je dal tristo srebrnikov in petero prazničnih oblek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 23, 'Očetu pa svojemu pošlje to: deset oslov, nesočih od najboljših stvari v Egiptu, in deset oslic, nesočih žita in kruha in jedil, očetu svojemu na pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 24, 'In odpusti brate svoje, in ko so odhajali, jim veli: Ne prepirajte se po poti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 25, 'Tako so šli gori iz Egipta, in pridejo v deželo Kanaansko k Jakobu, očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 26, 'In so mu poročali, govoreč: Jožef še živi in je oblastnik čez vso deželo Egiptovsko. A srce mu ostane mrzlo, ker jim ni verjel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 27, 'In povedali so mu vse besede Jožefove, ki jim jih je bil govoril, in ko je videl vozove, ki jih je poslal Jožef, da bi ga pripeljali, je oživel duh Jakoba, njih očeta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 45, 28, 'in Izrael reče: Dovolj mi je! še živi Jožef, sin moj; pojdem in videl ga bom, preden umrjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 1, 'In Izrael se napoti z vsem, kar je imel, in pride v Bersebo in tu daruje klalne daritve Bogu očeta svojega Izaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 2, 'In Bog je govoril Izraelu v nočni prikazni, rekoč: Jakob, Jakob! Ta pa reče: Tukaj sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 3, 'In on veli: Jaz sem Bog mogočni, očeta tvojega Bog; ne boj se iti doli v Egipt, zakaj ondi te storim v narod velik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 4, 'Jaz pojdem s teboj doli v Egipt, jaz te gotovo tudi nazaj pripeljem gori; in Jožef položi roko svojo na tvoje oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 5, 'Jakob torej vstane iz Bersebe, in sinovi Izraelovi so peljali Jakoba, očeta svojega, in otročiče svoje in žene svoje na vozovih, ki jih je bil poslal Faraon, da ga pripeljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 6, 'Vzeli so tudi živino svojo in blago svoje, katero so bili pridobili v deželi Kanaanski, in prišli so v Egipt, Jakob in vse seme njegovo ž njim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 7, 'sinove svoje in sinov svojih sinove, hčere svoje in sinov svojih hčere, vse seme svoje je s seboj pripeljal v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 8, 'Ta pa so imena sinov Izraelovih, ki so prišli v Egipt: Jakob in sinovi njegovi: prvenec Jakobov Ruben.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 9, 'Sinovi Rubenovi pa: Hanok, Palu, Hezron in Karmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 10, 'In sinovi Simeonovi: Jemuel, Jamin, Ohad, Jakin, Zohar in Savel, sin Kanaanke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 11, 'In sinovi Levijevi: Gerson, Kahat in Merari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 12, 'In sinovi Judovi: Ger, Onan, Šela, Perez in Zerah; Ger in Onan pa sta umrla v deželi Kanaanski. In sinova Perezova sta bila: Hezron in Hamul.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 13, 'In sinovi Isaharjevi: Tola, Puva, Job in Simron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 14, 'In sinovi Zebulonovi: Sered, Elon in Jahleel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 15, 'Ti so sinovi Leje, ki jih je rodila Jakobu v Padan-aramu in hčer njegovo Dino. Vseh duš sinov in hčer njegovih je bilo trideset in tri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 16, 'In sinovi Gadovi: Zifjon in Hagi, Šuni in Ezbon, Eri in Arodi in Areli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 17, 'In Aserjevi sinovi: Jimna, Jišva, Jišvi, Berija in Seraha, njih sestra; sinova Berijeva pa: Heber in Malkiel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 18, 'Ti so sinovi Zilpe, ki jo je dal Laban Leji, hčeri svoji, in te je ona rodila Jakobu, šestnajst duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 19, 'Sinova Rahele, žene Jakobove: Jožef in Benjamin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 20, 'In Jožefu sta se rodila v deželi Egiptovski Manase in Efraim, ki mu ju je rodila Asnata, hči Potiferja, svečenika v Onu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 21, 'In sinovi Benjaminovi: Bela, Beker, Ašbel, Gera in Naaman, Ehi in Roš, Mupim in Hupim in Ard.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 22, 'Ti so Rahelini sinovi, ki so se rodili Jakobu; vseh duš štirinajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 23, 'Sinovi Danovi pa: Hušimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 24, 'In sinovi Neftalijevi: Jahzeel, Guni, Jezer in Šilem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 25, 'Ti so sinovi Bilhe, ki jo je dal Laban Raheli, hčeri svoji, in te je rodila Jakobu: vseh duš sedem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 26, 'Vseh duš kar jih je prišlo z Jakobom v Egipt, ki so izšli iz ledij njegovih, razen žen sinov Jakobovih, vseh duš je bilo šestdeset in šest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 27, 'Sina Jožefova pa, ki sta se mu rodila v Egiptu, dve duši. Vseh duš rodbine Jakobove, ki so prišle v Egipt, je bilo sedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 28, 'In Jakob pošlje Judo pred seboj k Jožefu, da bi uredil potrebno za njih prihod v Gosen. In dospeli so v deželo Gosen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 29, 'Tedaj Jožef napreže svoj voz ter ide naproti Izaelu, očetu svojemu, v Gosen; in se mu prikaže in se oklene vratu njegovega, in je jokal dolgo ob vratu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 30, 'Izrael reče Jožefu: Rad umrem sedaj, ko sem videl obličje tvoje, da še živiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 31, 'Nato reče Jožef bratom svojim in rodbini svojega očeta: Pojdem, da sporočim Faraonu in mu rečem: Bratje moji in rodbina očeta mojega, ki so bili v deželi Kanaanski, so prišli k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 32, 'So pa tisti možje pastirji čred, kajti živinorejci so bili, in drobnico svojo in goveda svoja in vse, kar so imeli, so privedli s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 33, 'Ko vas pa pokliče Faraon in reče: Kaj je vaše opravilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 46, 34, 'mu odgovorite: Živinorejci so bili hlapci tvoji od mladosti svoje do sedaj, mi in očetje naši: da boste mogli prebivati v deželi Gosenski, zakaj gnus je Egipčanom vsak pastir drobnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 1, 'Pride torej Jožef in sporoči Faraonu ter reče: Oče moj in bratje moji so prišli s čredami svojimi in svojimi govedi in z vsem, kar imajo, iz dežele Kanaanske, in glej, v deželi Gosenski so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 2, 'In vzame izmed bratov svojih pet mož in jih postavi pred Faraona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 3, 'In Faraon reče bratom njegovim: Kaj je opravilo vaše? Oni pa reko Faraonu: Pastirji drobnice so hlapci tvoji, mi in očetje naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 4, 'Reko še Faraonu: Prišli smo prebivat kot tujci v tej deželi, zato ker ni pašnika čredam hlapcev tvojih, ker hudo pritiska lakota v deželi Kanaanski; sedaj torej naj prebivajo, prosimo, hlapci tvoji v deželi Gosenski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 5, 'In Faraon ogovori Jožefa, rekoč: Oče tvoj in bratje tvoji so prišli k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 6, 'Dežela Egiptovska ti je na voljo, v najboljšem kraju te dežele naseli očeta svojega in brate svoje: prebivajo naj v pokrajini Gosenski. Če pa poznaš kaj vrlih mož med njimi, jih postavi za gospodarje živini moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 7, 'Jožef pripelje tudi očeta svojega Jakoba ter ga postavi pred Faraona; in Jakob blagoslovi Faraona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 8, 'In Faraon reče Jakobu: Koliko je dni življenja tvojega let?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 9, 'Jakob pa reče Faraonu: Dni popotovanja mojega let je sto trideset let. Malo je dni življenja mojega in hudi so bili in ne dosežejo let življenja očetov mojih v dnevih njih popotovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 10, 'In Jakob je blagoslovil Faraona, in odide izpred obličja Faraonovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 11, 'Naseli torej Jožef očeta svojega in brate svoje ter jim da posest v deželi Egiptovski, v najboljšem kraju dežele, v pokrajini Ramesesu, kakor je ukazal Faraon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 12, 'In Jožef je priskrboval živež očetu svojemu in bratom svojim in vsej rodbini očeta svojega, primerno številu njih otročičev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 13, 'In ni bilo kruha v vsej deželi, ker je bila lakota silno huda, in dežela Egiptovska in dežela Kanaanska sta bili docela izmolzeni vsled lakote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 14, 'In Jožef pobere ves denar, kar se ga je našlo v deželi Egiptovski in Kanaanski, za žito, ki so ga kupovali; in ta denar je Jožef nesel v hišo Faraonovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 15, 'Ko jim je torej pošel ves denar v deželi Egiptovski in v deželi Kanaanski, so prišli vsi Egipčani k Jožefu, govoreč: Daj nam kruha! zakaj bi neki umirali vpričo tebe? kajti denar je pošel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 16, 'Reče pa Jožef: Dajte živino svojo, in dam vam kruha za živino vašo, če nimate denarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 17, 'Pripeljavali so torej živino svojo k Jožefu, in Jožef jim je dajal kruha za konje in za njih črede in za njih goved in za osle, in tako jih je živil s kruhom za vso njih živino tisto leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 18, 'Ali ko je preteklo to leto, pridejo k njemu drugo leto ter mu reko: Prikrivati ne moremo gospodu svojemu, da nam je pošel ves denar, in živina je prišla v last našemu gospodu; nič ni ostalo pred gospodom našim kakor le naša telesa in polja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 19, 'Zakaj bi ginili tebi pred očmi, mi in zemlja naša? Kupi nas in zemljišča naša za kruh, in bodimo s poljem svojim v sužnosti Faraonu; in daj nam semena, da živimo in ne umremo in se zemlja ne izpremeni v puščo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 20, 'Pokupi torej Jožef vse polje v Egiptu za Faraona; kajti prodali so Egipčani vsak zemljišče svoje, zato ker jih je premagala lakota. Tako je prišla dežela Faraonu v last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 21, 'Ljudstvo pa je preselil v mesta, od skrajne meje Egipta do druge meje njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 22, 'Samo polja duhovnikov ni kupil, zakaj duhovniki so imeli delež od Faraona, in uživali so obrok svoj, ki jim ga je dal Faraon; zato niso prodali polja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 23, 'Reče pa Jožef ljudstvu: Glejte, kupil sem danes vas in polje vaše za Faraona: tu imate semena, da posejete zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 24, 'Ali kar bode pridelkov, dajte petino Faraonu, štirje deli pa bodo vaši za posetev polja in za živež vam in družini vaši in za živež otročičev vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 25, 'Oni pa reko: Ohranil si nam življenje; najdemo naj milost v očeh gospoda svojega, in bodemo hlapci Faraonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 26, 'In tisto je Jožef ustanovil za postavo do tega dne o poljih v Egiptu, da se daje Faraonu petina; samo polja duhovnikov niso prišla v last Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 27, 'In Izrael je prebival v deželi Egiptovski, v pokrajini Gosenski, in pridobili so si posest v njej, in so bili rodovitni in se pomnožili silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 28, 'Živel je pa Jakob v deželi Egiptovski sedemnajst let; in bilo je dni Jakobovih, življenja njegovega let, sto štirideset in sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 29, 'Ko se pa približajo Izraelu dnevi, da umre, pokliče sina svojega Jožefa ter mu reče: Če sem milost našel v tvojih očeh, položi, prosim, roko svojo pod ledje moje in izkaži mi ljubezen in zvestobo: Nikar me ne pokoplji v Egiptu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 30, 'Kadar bom ležal z očeti svojimi, nesi me nazaj iz Egipta in me pokoplji v njih grobišču. On pa reče: Storil bom po besedi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 47, 31, 'Ko pa veli: Prisezi mi! mu je prisegel. In Izrael se prikloni Bogu proti zglavju postelje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 1, 'In po teh dogodkih so sporočili Jožefu: Glej, oče tvoj je bolan. In vzame dva sina svoja s seboj, Manaseja in Efraima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 2, 'In povedali so Jakobu, rekoč: Glej, sin tvoj Jožef prihaja k tebi. In okrepča se Izrael in sede na postelji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 3, 'In Jakob reče Jožefu: Bog silni, Vsegamogočni, se mi je prikazal v Luzu v deželi Kanaanski ter me je blagoslovil');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 4, 'in mi rekel: Glej, storim te rodovitnega in pomnožim te in naredim te v množico ljudstev, in dam to deželo semenu tvojemu za teboj v večno posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 5, 'In sedaj sinova tvoja dva, ki sta se ti rodila v deželi Egiptovski, preden sem prišel k tebi v Egipt, bodeta moja; Efraim in Manase bodita moja kakor Ruben in Simeon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 6, 'Otroci pa, katere boš rodil za njima, naj bodo tvoji; po imenu dveh bratov svojih naj se imenujejo v dediščini svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 7, 'Jaz pa, ko sem se vračal iz Padana, je umrla meni v žalost Rahela v deželi Kanaanski na potu, ko je bilo še malo hoda do Efrate; in pokopal sem jo na potu v Efrato, to je Betlehem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 8, 'Ko pa zagleda Izrael sinova Jožefova, reče: Kdo sta ta dva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 9, 'In Jožef reče očetu svojemu: Sinova sta moja, ki mi ju je dal Bog tukaj. On pa veli: Privedi ju, prosim, k meni, da ju blagoslovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 10, 'Oči Izraelove namreč so bile otemnele od starosti, ni dobro videl. In privede ju blizu k njemu, in on ju je poljubljal in ju pritiskal k srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 11, 'In reče Izrael Jožefu: Nisem mislil, da bom videl obličje tvoje, in glej, Bog mi je dal videti tudi seme tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 12, 'Nato ju pelje Jožef izmed kolen njegovih in se prikloni z obličjem svojim do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 13, 'In vzame oba, Efraima z desno svojo na levo Izraelu, Manaseja pa z levo svojo na desno Izraelu, in privede ju bliže k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 14, 'Ali Izrael iztegne desnico svojo, jo položi na glavo Efraimu, dasi je ta bil mlajši, in levo svojo na glavo Manaseju; premišljeno je del križem roke svoje, kajti Manase je bil prvenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 15, 'In blagoslovi Jožefa, govoreč: Bog, pred čigar obličjem sta vedno hodila očeta moja, Abraham in Izak, Bog, ki mi je bil pastir, odkar živim do tega dne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 16, 'angel, ki me je rešil iz vsakega zla, blagoslovi mladeniča ta; in naj se imenujeta po imenu mojem in po imenu očetov mojih Abrahama in Izaka, in v množice naj zrasteta na zemlji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 17, 'Ko je pa videl Jožef, da oče njegov poklada desno roko svojo Efraimu na glavo, ni mu bilo povšeč, zato prime očeta svojega roko, da jo preloži z glave Efraimove Manaseju na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 18, 'In Jožef reče svojemu očetu: Ne tako, oče moj, ker ta je prvenec, položi desnico svojo na glavo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 19, 'Oče njegov pa se je branil in dejal: Vem, sin moj, vem: v ljudstvo bode tudi ta in tudi velik bode, vendar mlajši brat njegov bode večji od njega in seme njegovo bode množina narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 20, 'In blagoslovi ju tisti dan, rekoč: S teboj bodo blagoslavljali Izraelci, govoreč: Stóri ti Bog kakor Efraimu in kakor Manaseju! In postavil je Efraima pred Manaseja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 21, 'In reče Izrael Jožefu: Glej, skoraj umrem, a Bog bode z vami in vas pripelje nazaj v deželo očetov vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 48, 22, 'In jaz ti darujem kos zemlje več nego bratom tvojim, ki sem ga dobil iz roke Amorejca s svojim mečem in z lokom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 1, 'In Jakob skliče sinove svoje ter reče: Zberite se, da vam oznanim, kar se vam bo godilo v poznejših dnevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 2, 'Zberite se in čujte, sinovi Jakobovi, poslušajte, pravim, Izraela, očeta svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 3, 'Ruben, ti si prvenec moj, moč moja in začetek mogočnosti moje, prednji v visokosti in prednji v krepkosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 4, 'Vzkipel si kakor voda, ne boš imel prednosti, kajti vzpel si se na očeta svojega ležišče; tedaj si je onečastil. Šel je na postelj mojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 5, 'Simeon in Levi sta brata: silovitosti orodje njiju meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 6, 'V skrivni njun posvet ne pridi duša moja, v njiju shod se ne druži slava moja; zakaj v jezi svoji sta ubila moža, in v razuzdanosti svoji sta ohromila junca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 7, 'Prokleta njiju jeza, ker silna je bila, in njiju togota, ker neusmiljena je bila: razdelim ju v Jakobu in ju razkropim v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 8, 'Juda, tebe, da, tebe bodo slavili bratje tvoji; roka tvoja bode sovražnikom tvojim na tilniku, priklanjali se ti bodo očeta tvojega sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 9, 'Levov mladič je Juda; od plena, sin moj, si prišel kvišku. Počivajoč leži kakor lev in kakor levinja, kdo se ga drzne zbuditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 10, 'Ne vzame se žezlo od Jude, niti vladarska palica izmed nog njegovih, dokler ne pride Šilo, in njemu bode pokorščina narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 11, 'Priveže za trto osliča svojega in za plemenito trto oslice svoje mladiča ter pere v vinu obleko svojo in v krvi grozdja plašč svoj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 12, 'oči so mu žareče od vina in zobje beli od mleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 13, 'Zebulon bo prebival ob pristanišču morskem in pristanišče bo ladjam in stran njegova proti Sidonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 14, 'Isahar je osel močnih kosti, ležeč med ograjami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 15, 'Ko bo videl, da je pokoj dober in da je prijetna dežela njegova, podstavi ramo svojo, da nosi tovor, in postane davku podvržen tlačan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 16, 'Dan bo sodil ljudstvo svoje kakor eden rodov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 17, 'Dan bode kakor kača ob potu, gad ob stezi, ki pika konja v kopita, da se jezdec zvrne znak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 18, 'Rešenje tvoje čakam, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 19, 'Gad, bojna gneča bo pritiskala nanj, on pa jim bo pritiskal na pete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 20, 'Od Aserja pride maščoba, kruh njegov, in on bo dajal slaščice kraljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 21, 'Neftali je košuta izpuščena, on govori besede lepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 22, 'Sin rodovitnega drevesa je Jožef, sin rodovitnega drevesa ob studencu, mladike njegove se vzpenjajo čez zidovje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 23, 'Hudo so ga užalili in nanj streljali in ga preganjali lokostrelci:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 24, 'vendar nepremičen ostane lok njegov in gibčni lahti rok njegovih, po rokah Mogočnega Jakobovega. Odtod je pastir, kamen Izraelov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 25, 'od mogočnega Boga očeta tvojega, ki ti bo pomagal, in od Vsegamogočnega, ki te bo blagoslovil z blagoslovi nebes odzgoraj, z blagoslovi globine odspodaj, z blagoslovi prsi in maternice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 26, 'Blagoslovi očeta tvojega presegajo blagoslove prednikov mojih do meje hribov večnih; bivajo naj na glavi Jožefovi in na temenu Odličnega med svojimi brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 27, 'Benjamin je volk, ki trga; zgodaj uživa rop in na večer deli plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 28, 'Vsi ti so dvanajsteri rodovi Izraelovi; in to jim je govoril njih oče, ko jih je blagoslavljal; vsakega izmed njih je blagoslovil, kakor mu je bil določen blagoslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 29, 'In zapove jim in jim reče: Ko bom zbran k ljudstvu svojemu, pokopljite me pri mojih očetih, v jamo, ki je na njivi Efrona Hetejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 30, 'v jamo, ki je na njivi Makpeli, nasproti Mamri v deželi Kanaanski, ki jo je kupil Abraham ž njivo vred od Efrona Hetejca v groba posest:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 31, 'tam so pokopali Abrahama in Saro, ženo njegovo, tam so pokopali Izaka in Rebeko, ženo njegovo, in tam sem pokopal Lejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 32, 'Kupljena je ona njiva in jama, ki je na njej, od Hetovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 49, 33, 'In ko je Jakob nehal zapovedovati sinom svojim, potegne noge svoje v posteljo in umrje, in zbran je bil k svojim ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 1, 'Tedaj se skloni Jožef na obličje očeta svojega, in jokal je nad njim in ga poljubljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 2, 'In ukaže Jožef hlapcem svojim, zdravnikom, da naj z dišavami mazilijo njegovega očeta. In zdravniki so pomazilili z dišavami Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 3, 'In dopolnilo se mu je štirideset dni: v toliko namreč dneh se dovrši maziljenje z dišavami. In jokali so za njim Egipčani sedemdeset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 4, 'Ko so pa bili potekli dnevi jokanja za njim, ogovori Jožef dvor Faraonov, rekoč: Če sem res milost našel v vaših očeh, govorite, prosim, pred Faraonom tole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 5, 'Oče moj me je zavezal s prisego in rekel: Glej, skoraj umrem; v grobu mojem, ki sem si ga izkopal v deželi Kanaanski, tam me pokoplji. Zdaj torej dovoli, da grem gori in pokopljem očeta svojega, in potem se vrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 6, 'In reče Faraon: Idi gori in pokoplji očeta svojega, kakor te je zaprisegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 7, 'Šel je torej Jožef gori pokopat očeta svojega, in ž njim so šli vsi služabniki Faraonovi, starejšine hiše njegove in vsi starejšine dežele Egiptovske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 8, 'tudi vsa hiša Jožefova in bratje njegovi in očeta njegovega rodbina; samo otročiče svoje in črede svoje in goveda svoja so pustili v deželi Gosenski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 9, 'Šli so ž njim gori tudi vozovi in konjiki, tako da je bil izprevod silno velik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 10, 'Ko so pa prišli do Gumna divjih rož, ki je onkraj Jordana, so jokali tam z jokom velikim in silno hudim: napravil je namreč očetu svojemu žalovanje sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 11, 'Ko so torej videli tiste pokrajine prebivalci, Kanaanci, žalovanje na Gumnu divjih rož, so rekli: To je hudo žalovanje Egipčanov. Zato se je imenovalo ime tistega kraja Abel mizraim, ki je onkraj Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 12, 'Storili so mu tedaj sinovi njegovi natanko, kakor jim je bil zapovedal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 13, 'in nesli so ga sinovi njegovi v deželo Kanaansko in so ga pokopali na njivi Makpeli v jami, ki jo je bil Abraham kupil ž njivo vred v groba posest od Efrona Hetejca, Mamri nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 14, 'In ko je pokopal očeta svojega, se vrne Jožef v Egipt, on in bratje njegovi in vsi, kar jih je šlo ž njim pokopavat očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 15, 'Ko so pa videli bratje njegovi, da je umrl njih oče, so govorili: Morda nas bo sovražil Jožef in nam dočista povrnil vse hudo, kar smo mu storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 16, 'Zato pošljejo k Jožefu in reko: Oče tvoj je zapovedal pred smrtjo, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 17, 'Tako recite Jožefu: Ah, odpusti, prosim, prestopek bratov svojih in njih greh, da so ti hudo storili. Odpusti torej zdaj, prosimo, prestopek hlapcem Boga očeta svojega. Jožef pa se je jokal, ko so oni govoril ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 18, 'Nato pristopijo tudi bratje njegovi ter padejo pred obličje njegovo in reko: Glej, tvoji smo hlapci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 19, 'Jožef pa jim reče: Ne bojte se; kajti sem li jaz na mestu Božjem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 20, 'Vi ste res hudo nameravali zoper mene, a Bog je obrnil v dobro, da je storil, kakor je danes, in ohranil v življenju mnogo ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 21, 'Sedaj torej se ne bojte: jaz bom živil vas in otroke vaše. Tako jih je tolažil in govoril, da jim je seglo v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 22, 'In prebival je Jožef v Egiptu, on in hiša njegovega očeta; in živel je Jožef sto in deset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 23, 'In videl je Jožef Efraimove otroke do tretjega rodu; tudi sinovi Mahirja, sina Manasejevega, so se rodili Jožefu na kolenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 24, 'In Jožef reče bratom svojim: Skoraj umrem, Bog pa vas gotovo obišče in dá, da pojdete gori iz te dežele v deželo, ki jo je s prisego obljubil Abrahamu, Izaku in Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 25, 'In Jožef zapriseže sinove Izraelove, rekoč: Gotovo vas obišče Bog, odnesite potem kosti moje odtod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (1, 50, 26, 'Nato umre Jožef, star sto in deset let; in ko so ga pomazilili z dišavami, je bil položen v rakev v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 1, 'In ta so imena sinov Izraelovih, ki so prišli v Egipt z Jakobom; vsak je prišel z rodbino svojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 2, 'Ruben, Simeon, Levi in Juda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 3, 'Isahar, Zebulon in Benjamin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 4, 'Dan in Neftali, Gad in Aser.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 5, 'In bilo je vseh duš, ki so izšle iz ledij Jakobovih, sedemdeset; a Jožef je bil prej v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 6, 'In umrl je Jožef in vsi bratje njegovi in vse to pokolenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 7, 'In sinovi Izraelovi so bili plodoviti, rodili so se obilo, razmnoževali so se in postali so jako, jako mogočni; in napolnila se je zemlja ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 8, 'Nastopi pa v Egiptu nov kralj, ki ni poznal Jožefa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 9, 'Ta reče ljudstvu svojemu: Glejte, ljudstvo sinov Izraelovih je številnejše in mogočnejše od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 10, 'Dejte, pametno ravnajmo proti njemu, da se ne razmnoži, in zgodilo bi se, ako nastane vojna, da se tudi ono pridruži sovražnikom našim in se bo vojskovalo zoper nas in odšlo iz dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 11, 'Nastavijo torej nad njimi priganjače za raboto, da naj jih tlačijo pri njih težaškem delu. Zidali so pa Faraonu mesta za skladišča, Pitom in Rameses.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 12, 'A čim bolj so jih tlačili, tem bolj so se razmnoževali, tem bolj so se razširjali: in Egipčane je bilo groza sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 13, 'In neusmiljeno so Egipčani priganjali sinove Izraelove k delu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 14, 'in grenili so jim življenje s trdim delom z ilovico in z opeko in z vsakovrstnim opravilom na polju, z vsem njih delom, katero so jim nakladali neusmiljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 15, 'In ukaže kralj egiptovski dvema hebrejskima babicama, katerih prvi je bilo ime Šifra in drugi ime Pua,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 16, 'rekoč: Ko pomagate ženam hebrejskim pri porodu, pazite na rojenje: če je sin, usmrtite ga, če pa hči, naj ostane živa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 17, 'Bali sta se pa ti babici Boga in nista delali, kakor jima je bil ukazal kralj egiptovski, temuč pustili sta dečke živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 18, 'In pokliče kralj egiptovski ti babici in jima reče: Zakaj sta to storili in pustili dečke živeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 19, 'Babici pa odgovorita Faraonu: Niso Hebrejke kakor egiptovske žene: ker so krepke narave, porodijo, preden pride k njim babica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 20, 'In Bog je dobro storil tema babicama. Ljudstvo pa se je množilo in postalo zelo mogočno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 21, 'In ker sta se babici bali Boga, jima je napravil hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 1, 22, 'In zapove Faraon vsemu ljudstvu svojemu, rekoč: Vsakega sina, ki se jim narodi, vrzite v reko, a vsako hčer ohranite živo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 1, 'Odide pa mož iz hiše Levijeve in si vzame hčer Levijevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 2, 'In žena spočne ter rodi sina, in ko vidi, da je lep, ga skriva tri mesece.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 3, 'In ko ga ni mogla dalje skrivati, vzame zanj pletenico iz papirovega trstja in jo zamaže z ilovico in s smolo, potem položi dečka vanjo in jo dene v ločje na Nilovem bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 4, 'Njegova sestra pa se postavi oddaleč, da bi videla, kaj se bo ž njim zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 5, 'In pride doli hči Faraonova kopat se v reki; in njene dekle se izprehajajo poleg reke. In zagleda pletenico sredi ločja in pošlje svojo deklo, da jo prinese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 6, 'Ko jo pa odpre, vidi dete, in glej, deček joče. In stori se ji milo in reče: Izmed otrok Hebrejcev je ta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 7, 'In sestra njegova reče hčeri Faraonovi: Ali naj grem in ti pokličem ženo dojnico izmed Hebrejk, da ti odgoji to dete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 8, 'In hči Faraonova ji veli: Pojdi! In deklica gre in pokliče otrokovo mater.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 9, 'In hči Faraonova ji veli: Vzemi tega otročička in odgoji mi ga, in dam ti plačilo tvoje. In žena vzame otroka, in ga je vzgajala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 10, 'In ko je deček odrastel, ga je privedla k hčeri Faraonovi. In bil ji je za sina in imenovala je ime njegovo Mojzes, rekoč: Ker sem ga potegnila iz vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 11, 'In zgodi se v tistih dnevih, da pride Mojzes, ko je bil že velik, k bratom svojim in gleda njih težaško delo; in vidi moža Egipčana, da tepe moža Hebrejca, izmed bratov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 12, 'In ozre se sem in tja, in ko vidi, da ni nikogar blizu, ubije Egipčana in ga zagrebe v pesek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 13, 'In izide zopet drugi dan, in glej, dva moža, Hebrejca, se prepirata. In reče tistemu, ki je delal krivico: Zakaj tepeš bližnjega svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 14, 'Ta pa reče: Kdo te je postavil za kneza in sodnika nam? Misliš li me umoriti, kakor si umoril Egipčana? Tedaj se Mojzes prestraši in reče: Gotovo se je zvedela ta stvar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 15, 'In Faraon, ko je začul o tem dogodku, je nameraval Mojzesa umoriti. A Mojzes pobegne izpred obličja Faraonovega, in je prebival v deželi Madianski; in usede se pri nekem studencu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 16, 'Duhovnik madianski pa je imel sedmero hčera, ki so prišle zajemat vodo; in napolnile so korita, da bi napojile čredo očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 17, 'A pridejo pastirji in jih odženo. Mojzes pa vstane in jim pomaga in napoji njih čredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 18, 'In ko pridejo k Reguelu, očetu svojemu, jim reče: Zakaj ste se danes vrnile tako hitro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 19, 'In odgovore: Mož Egipčan nas je rešil iz rok pastirjev in tudi nam zajel vode in napojil je čredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 20, 'On pa reče hčeram svojim: In kje je on? zakaj ste popustile tistega moža? Pokličite ga, da jé z nami kruh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 21, 'In Mojzes privoli, da ostane pri tem možu; ta pa da Mojzesu Ziforo, hčer svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 22, 'In ko porodi sina, imenuje on ime njegovo Gersom, kajti reče: Priseljenec sem v tuji zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 23, 'In zgodi se v mnogih tistih dnevih, da umrje egiptovski kralj. In sinovi Izraelovi so zdihovali zaradi tlake in vpili so, in njih vpitje od tlačanstva je prišlo k Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 24, 'In uslišal je Bog njih stokanje, in spomnil se je Bog svoje zaveze z Abrahamom, z Izakom in z Jakobom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 2, 25, 'In Bog je pogledal na sinove Izraelove, in spoznal jih je Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 1, 'Mojzes pa je pasel čredo Jetra, tasta svojega, duhovnika madianskega. In žene čredo onkraj puščave in pride na goro Božjo, Horeb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 2, 'In prikaže se mu angel Gospodov v plamenu ognja iz sredi grma; in pogleda, in glej, grm gori v ognju, pa grm ne zgori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 3, 'In reče Mojzes: Stopim vendar tja in pogledam to veliko prikazen, zakaj grm ne zgori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 4, 'Ko pa vidi Gospod, da stopa bliže, da bi pogledal, mu zakliče Bog iz sredi grma in veli: Mojzes, Mojzes! On pa reče: Tukaj sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 5, 'In veli: Ne bližaj se semkaj! Sezuj obuvalo z nog svojih, zakaj mesto, ki na njem stojiš, je sveta zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 6, 'In reče: Jaz sem Bog očeta tvojega, Bog Abrahamov, Bog Izakov in Bog Jakobov. In Mojzes si zastre obraz, kajti boji se ozreti v Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 7, 'In Gospod reče: Videl sem, videl stisko ljudstva svojega, ki je v Egiptu, in njih vpitje pred njih priganjači sem slišal, kajti jaz poznam bolečine njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 8, 'In stopil sem doli, da ga otmem iz rok Egipčanov in odpeljem iz one dežele v dobro in prostrano deželo, v deželo, v kateri teče mleko in med, v kraj Kanaancev in Hetejcev in Amorejcev in Ferizejcev in Hevejcev in Jebusejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 9, 'In sedaj, glej, vpitje sinov Izraelovih je prišlo do mene, in videl sem tudi stisko, s katero jih stiskajo Egipčani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 10, 'Sedaj torej pojdi, da te pošljem k Faraonu, in popelji moje ljudstvo, sinove Izraelove, iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 11, 'In reče Mojzes Bogu: Kdo sem jaz, da naj grem k Faraonu ter popeljem sinove Izraelove iz Egipta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 12, 'On pa reče: Jaz bodem s teboj, in to ti bodi znamenje, da sem te jaz poslal: ko popelješ ljudstvo iz Egipta, boste služili Bogu na tejle gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 13, 'In Mojzes odgovori Bogu: Glej, ko pridem k sinovom Izraelovim in jim porečem: Bog očetov vaših me je poslal k vam, in mi oni reko: Katero je ime njegovo? kaj naj jim povem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 14, 'In Bog reče Mojzesu: JAZ SEM, KI SEM. In reče: Tako boš rekel sinovom Izraelovim: JAZ SEM me je poslal k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 15, 'In Bog reče dalje Mojzesu: Tako reci sinovom Izraelovim: Gospod, Bog očetov vaših, Bog Abrahamov, Bog Izakov in Bog Jakobov, me je poslal k vam. To je moje ime vekomaj in to je spomin moj od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 16, 'Pojdi in zberi starejšine Izraelove in jih govóri: Gospod, Bog očetov vaših, se mi je prikazal, Bog Abrahamov, Izakov in Jakobov, govoreč: Zares sem vas obiskal in videl, kako se vam godi v Egiptu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 17, 'in rekel sem: Izvesti vas hočem iz stiske egiptovske v deželo Kanaancev in Hetejcev in Amorejcev in Ferizejcev in Hevejcev in Jebusejcev, v deželo, v kateri teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 18, 'In poslušali bodo tvoj glas. Potem pojdeš ti in starejšine izraelski h kralju egiptovskemu in mu porečete: Gospod, Bog Hebrejcev, nam je prišel naproti. In sedaj dovoli, da gremo tri dni hoda v puščavo in darujemo Gospodu, Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 19, 'Pa jaz vem, da vam kralj egiptovski ne dovoli, da bi šli, tudi ne, če z mogočno roko pridem nadenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 20, 'In iztegnem roko svojo in udarim Egipt z vsemi čudovitimi deli svojimi, katera bom storil sredi njega; in potem vas izpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 21, 'In dam milost temu ljudstvu v očeh Egipčanov, in zgodi se, ko izidete, ne pojdete prazni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 3, 22, 'marveč vsaka žena bo izprosila od sosede in domačinke svoje srebrnih in zlatih dragotin ter oblačil, in naložite jih sinovom in hčeram svojim in oplenite Egipčane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 1, 'Mojzes pa odgovori in reče: Glej, pa oni mi ne bodo verovali in ne bodo poslušali glasu mojega, ampak porečejo: Ni se ti prikazal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 2, 'In Gospod mu reče: Kaj je to v tvoji roki? Odgovori: Palica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 3, 'In veli: Vrzi jo na tla! In vrže jo na tla, in postala je kača, in Mojzes zbeži pred njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 4, 'In Gospod reče Mojzesu: Iztegni roko in primi jo za rep. In iztegne roko in jo zgrabi, in bila je palica v roki njegovi –:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 5, 'da bi verovali, da se ti je prikazal Gospod, Bog njih očetov, Bog Abrahamov, Bog Izakov in Bog Jakobov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 6, 'Še mu veli Gospod: Vtakni roko v nedrije svoje! In vtakne roko v nedrije svoje, in ko jo iztegne, glej, roka njegova je gobava in bela kakor sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 7, 'In veli: Vtakni zopet roko v nedrije svoje! In vtakne zopet roko v nedrije, in ko jo iztegne izza nedrija, glej, je zopet kakor vse meso njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 8, 'In zgodi se, če ti ne bodo verovali ter ne poslušali glasu prvega znamenja, bodo pa verovali v glas drugega znamenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 9, 'In če ne bodo verovali tudi tema dvema znamenjema in ne bodo poslušali glasu tvojega, tedaj vzameš vode iz reke in jo izliješ na suho; in izpremeni se voda, ki jo vzameš iz reke, v kri na suhem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 10, 'In Mojzes reče Gospodu: Prosim, Gospod, jaz nisem zgovoren mož, niti nisem bil kdaj poprej, niti odkar si izpregovoril s hlapcem svojim; kajti imam okorna usta in težek jezik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 11, 'In Gospod mu reče: Kdo je naredil usta človeku? in kdo stori koga nemega ali gluhega ali videčega ali slepega? ali ne jaz, Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 12, 'In sedaj pojdi, in jaz bodem pri tvojih ustih in te naučim, kaj naj govoriš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 13, 'On pa reče: Prosim, Gospod, pošlji vendar onega, ki ga hočeš poslati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 14, 'In vname se srd Gospodov zoper Mojzesa, in reče: Ali nimaš brata Arona, ki je levit? Vem, da je on jako zgovoren. Pa glej, gre ti tudi že naproti, in ko te zagleda, se razveseli v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 15, 'Ti pa govóri k njemu in položi besede moje v usta njegova, in jaz bodem pri ustih tvojih in pri ustih njegovih, in učil vaju bom, kaj naj storita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 16, 'On naj govori ljudstvu namesto tebe; in zgodi se, da bode on tebi za usta in ti bodeš njemu kakor Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 17, 'In v roko svojo vzemi to palico, ki boš ž njo storil ona znamenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 18, 'In Mojzes odide in se vrne k Jetru, svojemu tastu, in mu reče: Daj, da grem in se povrnem k bratom svojim, ki so v Egiptu, in pogledam, če so še živi. In Jetro reče Mojzesu: Pojdi v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 19, 'In rekel je Gospod Mojzesu v Madianu: Pojdi, povrni se v Egipt, kajti pomrli so vsi ljudje, ki so ti stregli po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 20, 'Mojzes vzame torej ženo svojo in sinova svoja in jih posadi na osla in se napoti nazaj v deželo Egiptovsko. Vzame tudi palico Božjo v roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 21, 'In Gospod je govoril Mojzesu: Ker torej greš, da se povrneš v Egipt, pazi, da storiš pred Faraonom vse čudeže, ki sem jih položil v roko tvojo. Jaz pa otrdim srce njegovo, da ne bo hotel odpustiti ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 22, 'In govoril boš Faraonu: Tako pravi Gospod: Izrael je sin moj, prvenec moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 23, 'In velel sem ti, da odpustiš sina mojega, da mi služi; a ker si se branil ga pustiti, glej, umorim sina tvojega, prvenca tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 24, 'In zgodi se na potu, v prenočišču, da mu pride Gospod naproti, in hotel ga je usmrtiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 25, 'In vzame Zifora oster kamen in obreže kožico sinu svojemu in jo vrže Mojzesu k nogam, rekoč: Ker si mi ženin krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 26, 'In prizanesel mu je Gospod. Tedaj reče ona: Ženin krvi si, zaradi obreze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 27, 'In rekel je bil Gospod Aronu: Pojdi v puščavo Mojzesu naproti! In on odide, in sreča ga na gori Božji in ga poljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 28, 'In Mojzes sporoči Aronu vse besede Gospodove, s katerimi ga je poslal, in vsa znamenja, ki mu jih je ukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 29, 'Prideta torej Mojzes in Aron ter skličeta vse starejšine sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 30, 'In pripovedoval je Aron vse besede, ki jih je bil Gospod govoril Mojzesu, in delal je znamenja vpričo ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 4, 31, 'In ljudstvo je verovalo. In ko so slišali, da je Gospod obiskal sinove Izraelove in da se je ozrl na njih bedo, so se priklonili in molili Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 1, 'In potem sta šla Mojzes in Aron ter rekla Faraonu: Tako pravi Gospod, Bog Izraelov: Pusti ljudstvo moje, da mi obhajajo praznik v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 2, 'In Faraon odgovori: Kdo je Gospod, čigar glas naj poslušam, da izpustim Izraela? Ne poznam Gospoda, tudi Izraela ne bom pustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 3, 'In ona rečeta: Bog Hebrejcev nam je prišel naproti. Pústi nas, prosimo, da gremo tri dni hoda v puščavo in darujemo Gospodu, Bogu svojemu, da nas ne kaznuje s kugo ali z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 4, 'In kralj egiptovski jima reče: Zakaj hočeta, Mojzes in Aron, oprostiti ljudstvo dela njegovega? Pojdita le k raboti svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 5, 'In Faraon reče: Glejta, preveč je že ljudstva v deželi, in vidva mu hočeta dati počitek od rabote njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 6, 'In ukazal je Faraon tistega dne priganjačem ljudstva in nadzornikom njegovim, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 7, 'Ne smete več ljudstvu dajati slame za izdelovanje opeke kakor doslej; naj sami gredo in si naberejo slame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 8, 'Toda isto število opeke, kolikor so jo izdelovali doslej, jim morate naložiti, ne odštevši prav ničesar; kajti nič ne delajo, zato vpijejo, govoreč: Pojdimo darovat Bogu svojemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 9, 'Težavna bodi služba tem ljudem, da bodo imeli dosti opravila in ne bodo pazili na lažnive besede!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 10, 'In odšli so priganjači ljudstva in njegovi nadzorniki in govorili so ljudstvu: Tako pravi Faraon: Slame vam ne bom več dajal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 11, 'Pojdite sami, prinesite si slame, kjerkoli je kaj najdete; toda služba se vam nič ne olajša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 12, 'In razkropilo se je ljudstvo po vsej zemlji Egiptovski, da bi zbirali strn za slamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 13, 'Priganjači pa so jih pritiskali, govoreč: Opravljajte svoje delo, vsak dan svoje delo, kakor takrat, ko je bila slama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 14, 'In bili so tepeni nadzorniki sinov Izraelovih, ki so jih nad njimi postavili priganjači Faraonovi; rekli so jim: Zakaj niste dodelali svojega števila opeke, ne včeraj, ne danes, kakor ste poprej?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 15, 'In prišli so nadzorniki sinov Izraelovih k Faraonu in so vpili in rekli: Zakaj tako ravnaš s hlapci svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 16, 'Slame ne dajó hlapcem tvojim, vendar velevajo: Delajte opeko; in glej, hlapci tvoji so tepeni, in krivo je tvoje ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 17, 'On pa reče: Nič ne delate, nič ne delate! zato govorite: Pojdimo darovat Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 18, 'In zdaj pojdite in delajte! Slame vam ne bodo dajali, a število opeke morate oddati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 19, 'In izprevideli so nadzorniki sinov Izraelovih, da so v stiski, ker morajo reči: Nič manj ne delajte opeke; vsak dan svoje delo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 20, 'Ko so se torej sešli z Mojzesom in Aronom, ki sta stala, da bi jih srečala na poti od Faraona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 21, 'so jima rekli: Gospod poglej na vaju in naj sodi, ker sta naš duh smrdljiv storila pred Faraonom in pred služabniki njegovimi, da bi dala meč v njih roke, da nas pomoré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 22, 'In obrne se Mojzes h Gospodu in reče: Gospod, zakaj ravnaš tako hudo s tem ljudstvom? zakaj si me vendar poslal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 5, 23, 'Kajti odkar sem šel k Faraonu, da bi govoril v tvojem imenu, ravna še huje s tem ljudstvom, in ti nisi nikakor rešil ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 1, 'In Gospod reče Mojzesu: Sedaj boš videl, kaj storim Faraonu: kajti z mogočno roko storim, da jih odpošlje, in z mogočno roko, da jih izžene iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 2, 'In govoril je Bog Mojzesu in mu rekel: Jaz sem Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 3, 'In pokazal sem se Abrahamu, Izaku in Jakobu Bog silni, Vsegamogočni, ali po imenu svojem Jehova se jim nisem razodel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 4, 'Tudi zavezo svojo sem ustanovil ž njimi, da jim dam deželo Kanaansko, deželo njih popotovanja, ki so živeli v njej kot tujci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 5, 'Čul sem tudi stokanje sinov Izraelovih, ki jih Egipčani silijo k službi, in spomnil sem se zaveze svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 6, 'Zatorej govóri sinovom Izraelovim: Jaz sem Jehova; jaz vas hočem odpeljati izpod tlake Egipčanom in vas iztrgati iz njih službe in vas rešiti z iztegnjeno roko in z velikimi sodbami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 7, 'in sprejeti vas hočem za svoje ljudstvo, in bodem vam Bog, in spoznali boste, da sem jaz Jehova, Bog vaš, ki sem vas odpeljal izpod tlake Egipčanom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 8, 'in privesti vas hočem v deželo, za katero sem povzdignil svojo roko in prisegel, da jo dam Abrahamu, Izaku in Jakobu, in hočem vam jo dati v posest, jaz, Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 9, 'In govoril je Mojzes tako sinovom Izraelovim, a oni ga vsled bridkosti duha in vsled trde sužnosti niso poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 10, 'In govoril je Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 11, 'Pojdi noter, govóri Faraonu, kralju egiptovskemu, da odpusti sinove Izraelove iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 12, 'In Mojzes je pred Gospodom govoril, rekoč: Glej, sinovi Izraelovi me niso poslušali, kako me bode pač poslušal Faraon, ker sem okornega jezika?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 13, 'In Gospod je govoril Mojzesu in Aronu in jima dal zapoved za sinove Izraelove in za Faraona, kralja egiptovskega, da bi sinovi Izraelovi šli iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 14, 'To so prvaki očetovskih hiš svojih: Sinovi Rubena, prvenca Izraelovega: Hanok, Palu, Hezron in Karmi; to so rodovine Rubenove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 15, 'In sinovi Simeonovi: Jemuel, Jamin, Ohad, Jakin, Zohar in Savel, sin Kanaanke; to so rodovine Simeonove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 16, 'In ta so imena sinov Levijevih po svojih rodovih: Gerson, Kahat in Merari; in let življenja Levijevega je bilo sto sedemintrideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 17, 'Sinova Gersonova: Libni in Simej, po svojih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 18, 'In sinovi Kahatovi: Amram in Izhar, Hebron in Uziel; in let življenja Kahatovega je bilo sto in triintrideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 19, 'In sinova Merarijeva: Mahli in Musi; to so rodovine Levijeve po svojih rodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 20, 'In vzel si je Amram Jokebedo, teto svojo, za ženo; in porodila mu je Arona in Mojzesa; in bilo je let življenja Amramovega sto in sedemintrideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 21, 'In sinovi Izharjevi: Korah, Nefeg in Zikri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 22, 'In sinovi Uzielovi: Misael, Elzafan in Sitri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 23, 'In vzel si je Aron Elisebo, hčer Aminadabovo, sestro Nahsonovo, za ženo; in porodila mu je Nadaba, Abihuja, Eleazarja in Itamarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 24, 'In sinovi Korahovi: Asir, Elkana in Abiasaf; to so rodbine Korahovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 25, 'In Eleazar, sin Aronov, si je vzel eno izmed hčera Putielovih za ženo; in porodila mu je Pinehasa. To so prvaki, očetje levitov po svojih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 26, 'To sta Aron in Mojzes, ki jima je rekel Gospod: Izpeljita sinove Izraelove iz dežele Egiptovske po njih vojnih krdelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 27, 'Ona sta, ki sta govorila Faraonu, kralju egiptovskemu, zaradi odhoda sinov Izraelovih iz Egipta: ta Mojzes in Aron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 28, 'In zgodilo se je tisti dan, ko je govoril Gospod Mojzesu v deželi Egiptovski,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 29, 'da je velel Gospod Mojzesu takole: Jaz sem Gospod; govóri Faraonu, kralju egiptovskemu, vse, kar jaz tebi govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 6, 30, 'In Mojzes reče pred Gospodom: Glej, jaz sem okornega jezika, in kako naj bi me poslušal Faraon?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 1, 'In Gospod reče Mojzesu: Poglej, postavljam te za boga Faraonu, in Aron, brat tvoj, bode tvoj prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 2, 'Ti boš govoril vse, kar ti ukažem, in Aron, brat tvoj, bo govoril Faraonu, da pusti sinove Izraelove iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 3, 'Jaz pa zakrknem srce Faraonu in pomnožim znamenja svoja in čudeže svoje v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 4, 'In Faraon vas ne bo poslušal; in položim roko svojo na Egipt in izvedem svoje vojske, svoje ljudstvo, sinove Izraelove, iz Egiptovske dežele z velikimi sodbami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 5, 'In spoznali bodo Egipčani, da sem jaz Gospod, ko iztegnem roko svojo nad Egiptom in izpeljem sinove Izraelove izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 6, 'Mojzes in Aron sta torej storila tako; kakor jima je ukazal Gospod, tako sta storila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 7, 'In Mojzes je bil osemdeset let star, Aron pa triinosemdeset let, ko sta govorila Faraonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 8, 'In govoril je Gospod Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 9, 'Ko bo z vama govoril Faraon in rekel: Naredita za sebe kak čudež! tedaj véli Aronu: Vzemi palico svojo in vrzi jo na tla pred Faraonom; postane naj velika kača!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 10, 'In gresta Mojzes in Aron k Faraonu in storita, kakor je ukazal Gospod: Aron je namreč vrgel palico svojo na tla pred Faraonom in pred služabniki njegovimi, in postala je velika kača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 11, 'Tedaj pokliče tudi Faraon modrijane in čarodeje; in napravili so tudi oni, pismouki egiptovski, enako s čarovništvom svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 12, 'vsak je vrgel palico svojo na tla, in postale so velike kače; a Aronova palica je požrla njih palice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 13, 'Ali srce Faraonovo se je otrdilo, in ni ju poslušal, kakor je bil govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 14, 'In reče Gospod Mojzesu: Srce Faraonovo je trdo; brani se izpustiti ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 15, 'Idi k Faraonu zjutraj, glej, pojde ven k vodi; in stopi mu naproti ob bregu Nilovem, in palico, ki se je izpremenila v kačo, vzemi v roko svojo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 16, 'in govori k njemu: Gospod, Bog Hebrejcev, me je poslal k tebi s tem naročilom: Odpusti ljudstvo moje, da mi služi v puščavi; in glej, dozdaj nisi poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 17, 'Tako pravi Gospod: Po tem spoznaš, da sem jaz Gospod: glej, udarim s palico, ki je v roki moji, po vodi, ki je v reki, in izpremenila se bo v kri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 18, 'Ribe pa, ki so v reki, poginejo, in reka se usmradi, in gnusilo se bo Egipčanom piti vodo iz reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 19, 'In reče Gospod Mojzesu: Véli Aronu: Vzemi palico svojo in iztegni roko svojo nad vodami v Egiptu, nad njegovimi rekami, nad njegovimi vodotoki, nad njegovimi ribniki in nad vsemi vodnjaki njegovimi, da postanejo kri; in kri bode po vsej deželi Egiptovski, i v lesenih i v kamenitih posodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 20, 'In storila sta tako Mojzes in Aron, kakor je bil ukazal Gospod: povzdignil je palico in je udaril po vodi v reki, pred očmi Faraonovimi in pred očmi služabnikov njegovih; in vsa voda, kar je je bilo v reki, se je izpremenila v kri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 21, 'In ribe, ki so bile v reki, so poginile, in reka se je usmradila, in Egipčani niso mogli piti vode iz reke; in bila je kri po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 22, 'A pismouki egiptovski so naredili enako s čarovništvom svojim. In srce Faraonovo se je otrdilo in ni ju poslušal, kakor je bil govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 23, 'In obrnil se je Faraon in šel na svoj dom, in niti to mu ni seglo do srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 24, 'In vsi Egipčani so kopali poleg reke, da dobe pitne vode, zakaj vode iz reke niso mogli piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 7, 25, 'In preteklo je celih sedem dni, odkar je Gospod udaril reko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 1, 'Tedaj reče Gospod Mojzesu: Idi k Faraonu in mu reci: Tako pravi Gospod: Izpusti moje ljudstvo, da mi služi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 2, 'Če se boš pa branil ga izpustiti, glej, udarim vse pokrajine tvoje z žabami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 3, 'In v reki bo kar mrgolelo žab, in izlezle bodo in šle v hišo tvojo in v spalnico in na posteljo tvojo, in v hiše služabnikov tvojih in med ljudstvo tvoje in v peči tvoje in v nečke tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 4, 'tudi na tebe kakor na tvoje ljudstvo in na vse služabnike tvoje bodo prilezle žabe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 5, 'In Gospod reče Mojzesu: Véli Aronu: Iztegni roko s palico svojo nad rekami, nad vodotoki in nad ribniki in stóri, da pridejo žabe nad deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 6, 'In iztegne Aron roko svojo nad vodami Egipta, in žabe so prilezle na dan in pokrile deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 7, 'In storili so pismouki enako s čarovništvom svojim, in izpeljali so žabe nad zemljo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 8, 'Tedaj pokliče Faraon Mojzesa in Arona in reče: Prosite Gospoda, da odpravi žabe od mene in ljudstva mojega, in odpustil bom ljudstvo, da daruje Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 9, 'In Mojzes reče Faraonu: Čast ti bodi pred menoj, da določiš, za kateri čas naj prosim zate in za služabnike tvoje in za ljudstvo tvoje, da se zatró žabe pri tebi in po hišah tvojih, samo v reki naj ostanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 10, 'On pa reče: Za jutri. In Mojzes odgovori: Bodi po tvoji besedi, zato da spoznaš, da ni nikogar, kakor je Gospod, naš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 11, 'In zapustijo žabe tebe in hiše tvoje in služabnike tvoje in ljudstvo tvoje, samo v reki ostanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 12, 'In odideta Mojzes in Aron izpred Faraona; Mojzes pa je vpil h Gospodu zaradi žab, ki jih je bil poslal nad Faraona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 13, 'In storil je Gospod po besedi Mojzesovi, in poginile so žabe v hišah, v dvorih in na poljih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 14, 'In nagrabili so jih velike grmade, in smrdela je zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 15, 'Ko je pa videl Faraon, da je prišla olajšava, je zakrknil svoje srce in ni ju poslušal kakor je bil govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 16, 'In Gospod reče Mojzesu: Véli Aronu: Iztegni palico svojo in udari prah zemlje, in postanejo iz njega komarji po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 17, 'In storila sta tako; Aron namreč iztegne roko s palico svojo in udari prah zemlje, in prišli so komarji na ljudi in na živino; iz vsega prahu zemlje so postali komarji po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 18, 'In pismouki so poskušali isto s čarovništvom svojim, da napravijo komarje, a niso mogli. In bili so komarji na ljudeh in na živini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 19, 'Pismouki so torej rekli Faraonu: Prst Božji je to! Ali Faraonovo srce se je otrdilo in ni ju slušal, kakor je bil govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 20, 'In Gospod reče Mojzesu: Vstani zjutraj zgodaj in stopi pred Faraona; glej, on pride ven k vodi, in mu reci: Tako pravi Gospod: Izpusti ljudstvo moje, da mi služi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 21, 'Sicer, če ne izpustiš ljudstva mojega, glej, pošljem nad tebe in nad služabnike tvoje in nad ljudstvo tvoje in v tvoje hiše pasje muhe; in hiše Egipčanov bodo polne pasjih muh, pa tudi zemlja, v kateri so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 22, 'In tisti dan izločim deželo Gosensko, ki v njej prebiva ljudstvo moje, da tam ne bode nič muh, zato da spoznaš, da sem jaz Gospod sredi zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 23, 'In postavim znamenje rešitve med svojim ljudstvom in ljudstvom tvojim. Jutri se zgodi to znamenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 24, 'In Gospod je storil tako; in prišla je množica pasjih muh v hišo Faraonovo in v hiše služabnikov njegovih in nad vso deželo Egiptovsko, in pasje muhe so pokvarile deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 25, 'Tedaj pokliče Faraon Mojzesa in Arona ter reče: Idite, darujte Bogu svojemu tu v deželi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 26, 'In Mojzes odgovori: Ni spodobno, da tako storimo: zakaj gnusobo Egipčanov bi darovali Gospodu, Bogu svojemu; če pa darujemo gnusobo Egipčanov pred njih očmi, ali nas ne bodo kamenali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 27, 'Tri dni hoda pojdemo v puščavo, da darujemo Gospodu, Bogu svojemu, kakor nam bo velel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 28, 'In Faraon reče: Pustim vas torej, da darujete Gospodu, Bogu svojemu, v puščavi, samo ne hodíte predaleč. Molite zame!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 29, 'Mojzes pa reče: Glej, grem izpred tebe in prosil bom Gospoda; in jutri popuste pasje muhe Faraona in služabnike njegove in ljudstvo njegovo. Samo da nas Faraon nič več na vara, ne hoteč odpustiti ljudstva, da daruje Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 30, 'In šel je Mojzes ven od Faraona ter prosil Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 31, 'In Gospod je storil po besedi Mojzesovi, in odžene pasje muhe od Faraona, od služabnikov njegovih in od ljudstva njegovega: niti ena ni ostala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 8, 32, 'Ali Faraon je zakrknil srce svoje tudi takrat in ni izpustil ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 1, 'Tedaj je govoril Gospod Mojzesu: Idi k Faraonu in mu govóri: Tako pravi Gospod, Bog Hebrejcev: Izpusti ljudstvo moje, da mi služijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 2, 'Zakaj če se boš branil jih odpustiti in jih še dalje zadrževal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 3, 'glej, roka Gospoda bode nad tvojo živino, ki je na polju: nad konji, nad osli, nad velblodi, nad govedi in nad drobnico v jako hudi kugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 4, 'In Gospod napravi razloček med živino Izraelcev in med živino Egipčanov, in od vsega blaga, kar je sinov Izraelovih, ne pogine nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 5, 'In Gospod je določil rok, rekoč: Jutri napravi Gospod to v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 6, 'In storil je Gospod to drugi dan: in vsa živina Egipčanov je poginila, a izmed živine sinov Izraelovih še ena glava ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 7, 'Pošlje pa Faraon, in glej, niti ena glava ni poginila sinovom Izraelovim. In zakrknilo se je srce Faraonovo, in ljudstva ni izpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 8, 'Tedaj reče Gospod Mojzesu in Aronu: Vzemita si iz peči polne pesti pepela, in Mojzes naj ga iztrese proti nebu pred očmi Faraonovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 9, 'In bodi v prah nad vso deželo Egiptovsko, in ljudje in živali dobodo ugnide, ki se izrinejo z osepnicami, po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 10, 'Vzela sta torej pepela in se postavila pred Faraona, in Mojzes ga raztrese proti nebu; in nastalo je ugnidje, ki se je v osepnicah izrinilo po ljudeh in govedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 11, 'In pismouki niso mogli stati pred Mojzesom zaradi ugnidja, kajti pismouki so je imeli kakor vsi Egipčani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 12, 'Gospod pa je otrdil srce Faraonovo in ni ju slušal, kakor je bil govoril Gospod Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 13, 'In Gospod reče Mojzesu: Vstani zjutraj zgodaj in stopi pred Faraona ter mu reci: Tako pravi Gospod, Bog Hebrejcev: Izpusti ljudstvo moje, da mi služi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 14, 'Kajti to pot pošljem vse šibe svoje nad tvoje srce in nad služabnike tvoje in nad ljudstvo tvoje, zato da spoznaš, da nikogar ni meni enakega na vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 15, 'Kajti zdaj sem že iztegnil roko svojo, in ko bi bil s kugo udaril tebe in ljudstvo tvoje, bi bil iztrebljen z zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 16, 'Ali zaradi tega sem te ohranil, da ti pokažem svojo moč ter da se razglasi ime moje po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 17, 'Ako se še vzpenjaš zoper moje ljudstvo, ne hoteč ga izpustiti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 18, 'glej, jutri obsore storim, da bo padala debela toča, kakršne še ni bilo v Egiptu od dne, ko je bil postavljen, do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 19, 'Zdaj pa pošlji in spravi v zavetje živino svojo in karkoli imaš na polju; zakaj vsak človek in vsaka žival, ki bode na polju in se ne shrani v hiši, pogine, ko se usuje toča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 20, 'Kdorkoli izmed služabnikov Faraonovih se je bal besede Gospodove, je spravil svoje hlapce in živino svojo na varno v hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 21, 'Kdor si pa ni vzel besede Gospodove k srcu, je pustil svoje hlapce in živino na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 22, 'In Gospod reče Mojzesu: Iztegni roko proti nebu, da pride toča nad vso deželo Egiptovsko, nad ljudi in nad živali in nad vso poljsko zelenjavo v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 23, 'In Mojzes je iztegnil palico svojo proti nebu, in Gospod je dal grom in točo, in ogenj je švigal na zemljo, in Gospod je dežil točo na deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 24, 'In padala je toča in ogenj je neprestano švigal med točo, jako hudo, kakršne ni bilo v vsej deželi Egiptovski, odkar je last naroda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 25, 'In potolkla je toča po vsej deželi Egiptovski, karkoli je bilo na polju, od človeka do živine, in vso zelenjavo na polju je potolkla toča in polomila sleherno drevo na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 26, 'Samo v deželi Gosenski, kjer so bili sinovi Izraelovi, ni bilo toče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 27, 'In pošlje Faraon ter pokliče Mojzesa in Arona in jima reče: Pregrešil sem se ta krat. Gospod je pravičen, jaz pa in ljudstvo moje smo krivičniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 28, 'Prosite Gospoda, in dovolj bodi groma Božjega in toče, in izpustim vas, in ne ostanete več tukaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 29, 'In odgovori mu Mojzes: Ko pridem iz mesta, razprostrem roke svoje proti Gospodu: grmenje poneha in toče ne bode več, zato da spoznaš, da je zemlja Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 30, 'Vem pa, da se ti in služabniki tvoji še ne bojite Gospoda Boga. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 31, 'In lan in ječmen sta bila pokončana: kajti ječmen je bil že v klasju in lan je poganjal glavice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 32, 'Pšenica pa in pira nista bili pokončani, ker sta pozni. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 33, 'In ko pride Mojzes od Faraona ven iz mesta, razprostre roke proti Gospodu, in nehalo je grmeti, tudi dež ni več lil na zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 34, 'Ko je pa Faraon videl, da je konec dežju, toči in grmenju, je grešil nadalje, in zakrknil je srce svoje on in služabniki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 9, 35, 'In otrdilo se je srce Faraonovo, in ni izpustil sinov Izraelovih, kakor je bil govoril Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 1, 'In Gospod reče Mojzesu: Idi k Faraonu; kajti zakrknil sem srce njegovo in srce hlapcev njegovih zato, da bi napravil ta znamenja svoja med njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 2, 'in zato, da bi ti pripovedoval ušesom sinov svojih in otrok sinov svojih, kar sem izvršil v Egiptu, in o znamenjih mojih, ki sem jih naredil med njimi; da boste spoznali, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 3, 'In odideta Mojzes in Aron k Faraonu ter mu rečeta: Tako pravi Gospod, Bog Hebrejcev: Doklej se boš ustavljal ponižati se pred menoj? Izpusti ljudstvo moje, da mi služi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 4, 'Sicer ako se boš branil odpustiti ljudstvo moje, glej, jutri pošljem kobilice v pokrajine tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 5, 'In pokrijejo površje zemlje, da je ne boste nič videli; in pojedle bodo ostanek, kar se je ohranilo in kar vam je preostalo po toči, in oglodale bodo vsa drevesa, ki vam rasto na polju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 6, 'in napolnijo hiše tvoje in hiše vseh služabnikov tvojih in hiše vseh Egipčanov, kolikor jih niso videli očetje tvoji in dedje, odkar so na zemlji do današnjega dne. In obrne se in odide od Faraona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 7, 'Tedaj reko Faraonu hlapci njegovi: Doklej nam bode ta mož za zanko? Odpusti tiste ljudi, da služijo Gospodu, svojemu Bogu! Ali mar še ne veš, da je Egipt pri koncu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 8, 'In pokličejo nazaj Mojzesa in Arona k Faraonu, in on jima reče: Pojdite, služite Gospodu, Bogu svojemu! Kateri pa so tisti, ki naj gredo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 9, 'In Mojzes odgovori: S svojo mladino in s svojimi starci pojdemo; s sinovi in hčerami svojimi, z drobnico in govedjo svojo odidemo; ker imamo praznik Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 10, 'In on jima reče: Bodi tako Gospod z vami, kakor jaz odpuščam vas in otročiče vaše! Glejte, da imate v mislih kaj hudega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 11, 'Ne tako! Pojdite le vi možje, in služite Gospodu; zakaj to je, kar ste želeli. In izgnali so ju izpred obličja Faraonovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 12, 'Tedaj reče Gospod Mojzesu: Iztegni roko svojo nad deželo Egiptovsko zaradi kobilic, da pridejo nad Egiptovsko deželo in požro vsa zelišča na zemlji, vse, kar je preostalo po toči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 13, 'In Mojzes iztegne palico svojo nad deželo Egiptovsko, in Gospod zažene vzhodni veter v deželo ves tisti dan in vso noč; in ko se je zdanilo, prinese vzhodni veter kobilice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 14, 'In prišle so kobilice nad vso Egiptovsko deželo in posedle so vse kraje Egipta v silno veliki množici; nikdar poprej ni bilo takšnih kobilic, tudi pozneje ne bo takih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 15, 'Kajti pokrile so površje vse dežele, tako da se je stemnila dežela, in požrle so vsa zelišča na zemlji in vse sadje po drevju, kar je bilo preostalo po toči; in nič zelenega ni ostalo, ne drevja, ne zelišč na polju, po vsej deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 16, 'Tedaj pokliče Faraon hitro Mojzesa in Arona in reče: Grešil sem zoper Gospoda, vašega Boga, in zoper vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 17, 'Sedaj pa odpusti, prosim, greh moj, samo še zdaj, in prosita Gospoda, vašega Boga, da odvrne od mene vsaj to smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 18, 'In Mojzes odide od Faraona ter prosi Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 19, 'In Gospod stori, da potegne zahodni veter, jako silen, ki je vzdignil kobilice in jih zagnal v Rdeče morje. Ne ene kobilice ni ostalo v vseh krajih Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 20, 'Gospod pa je otrdil srce Faraonovo, da ni odpustil sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 21, 'In reče Gospod Mojzesu: Iztegnil roko proti nebu, in nastane tema nad Egiptovsko deželo, tema, da jo bodo kar tipali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 22, 'In Mojzes iztegne roko proti nebu, in bila je gosta tema po vsej deželi Egiptovski tri dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 23, 'Niso videli drug drugega, nihče tudi ni vstal s svojega mesta v teh treh dnevih; a vsi sinovi Izraelovi so imeli svetlo v prebivališčih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 24, 'In pokliče Faraon Mojzesa in reče: Idite, služite Gospodu; samo vaše ovce in vaši voli naj ostanejo tu, tudi otroci vaši naj gredo z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 25, 'Mojzes pa odgovori: Tudi klalne in žgalne daritve moraš dati v roke naše, da jih pripravimo Gospodu, Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 26, 'Tudi živina naša pojde z nami, tu ne sme ostati niti en parkelj, ker od nje vzamemo, s čimer bomo služili Gospodu, Bogu svojemu; kajti mi ne vemo, s čim naj služimo Gospodu, dokler ne pridemo tjakaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 27, 'Ali Gospod je otrdil srce Faraonovo, da jih ni hotel izpustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 28, 'In Faraon mu reče: Pojdi izpred mene! Varuj se, da ne vidiš več obličja mojega, zakaj v dan, kadar bi zagledal obličje moje, umrješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 10, 29, 'In Mojzes reče: Prav si povedal: nikoli več ne bom videl obličja tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 1, 'Govoril pa je bil Gospod Mojzesu: Še eno šibo pošljem nad Faraona in nad Egipt, potem vas izpusti odtod; ko vas res izpusti, vas še celo izžene odtod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 2, 'Govori zdaj na ušesa ljudstvu, naj prosi vsakdo od svojega soseda in vsaka od sosede svoje srebrnih in zlatih dragotin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 3, 'In dal je Gospod ljudstvu milost v očeh Egipčanov. Tudi Mojzes je bil jako imeniten mož v deželi Egiptovski, v očeh služabnikov Faraonovih in v očeh ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 4, 'In Mojzes reče: Tako pravi Gospod: Opolnoči pojdem sredi Egipta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 5, 'in umrjo vsi prvorojenci v Egiptovski deželi, od prvenca Faraonovega, ki bi mu bilo sedeti na njegovem prestolu, do prvenca dekle pri ročnem mlinu in vsa prvenščina živali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 6, 'In bo veliko vpitje po vsej deželi Egiptovski, kakršnega nikoli ni bilo in ga nikdar več ne bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 7, 'A pri vseh sinovih Izraelovih niti pes ne migne z jezikom svojim, ne proti ljudem, ne proti živini, zato da izprevidite, da Gospod dela razloček med Egipčani in med Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 8, 'In pridejo k meni doli vsi ti služabniki tvoji ter, priklanjajoč se mi, poreko: Izidi ti in vse ljudstvo, ki ti sledi; in potem izidem. In odšel je izpred Faraona v goreči jezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 9, 'In Gospod je rekel Mojzesu: Faraon vaju ne posluša, zato da se pomnožé čudeži moji v Egiptovski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 11, 10, 'In Mojzes in Aron sta storila vse te čudeže pred Faraonom; a Gospod je otrdil srce Faraonovo, in on ni odpustil sinov Izraelovih iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 1, 'In Gospod je govoril Mojzesu in Aronu v deželi Egiptovski, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 2, 'Ta mesec vam bodi začetek mesecev, ta vam bodi prvi med meseci v letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 3, 'Govorita vsemu zboru Izraelovemu, rekoč: Deseti dan tega meseca naj si priskrbi vsakdo jagnje za rodbinsko hišo, eno jagnje za hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 4, 'Če je pa hiša premajhna za eno jagnje, naj ga vzame on in njegov sosed, najbližji hiši njegovi, po številu duš; vsakterega štejte po tem, kolikor jé, na jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 5, 'Jagnje bodi brez madeža, samec, leto staro; vzemite ga izmed ovac ali pa izmed koz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 6, 'In hranili ga boste do štirinajstega dne tega meseca, in zakolje ga ves zbor občine Izraelove proti večeru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 7, 'In vzamejo naj krvi in pomažejo ž njo oba podboja in naddurje pri hišah, v katerih ga bodo jedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 8, 'In jedli bodo meso njegovo tisto noč, pečeno na ognju, in opresne kruhe; z grenkimi zelišči naj ga jedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 9, 'Ne smete jesti ničesar od njega sirovega, tudi ne v vodi kuhanega, temuč pečeno na ognju: glavo njegovo z njegovimi nogami in z njegovim drobom vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 10, 'In ne pustite, da bi od njega kaj ostalo do jutra; če pa preostane kaj do jutra, sežgite na ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 11, 'Takole ga pa boste jedli: Ledja imejte opasana, opanke svoje na nogah in palico v roki; in jedli ga boste, kakor da proč hitite. Gospodova je pasha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 12, 'Zakaj to noč pojdem skozi deželo Egiptovsko, in udarim vso prvenščino v deželi Egiptovski, od človeka do živali, in nad vsemi bogovi egiptovskimi napravim sodbo, jaz, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 13, 'In ona kri vam bodi v znamenje na hišah, v katerih bodete: in ko zagledam kri, pojdem mimo vas, in ne pride nad vas šiba, vam v pogubljenje, kadar udarim deželo Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 14, 'In ta dan vam bodi za spomin, in praznovali ga boste v praznik Gospodu; kot večno postavo v svojih prihodnjih rodovih ga praznujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 15, 'Sedem dni boste jedli opresne kruhe; takoj prvi dan odstranite kvas iz hiš svojih: zakaj kdorkoli bi jedel kaj kvašenega od prvega do sedmega dne, ta duša bo iztrebljena iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 16, 'In prvega dne imejte sveto zborovanje, tudi sedmega dne sveto zborovanje; nobenega dela ne boste ta čas opravljali, samo kar je treba vsakemu za živež, pripravite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 17, 'Spoštujte torej praznik opresnikov, zakaj ravno tisti dan sem odpeljal trume vaše iz dežele Egiptovske; hranite torej ta dan v prihodnjih rodovih svojih kot večno postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 18, 'Štirinajsti dan prvega meseca zvečer boste jedli opresnike do edenindvajsetega dne istega meseca zvečer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 19, 'Sedem dni ne bodi kvasu v hišah vaših, zakaj kdorkoli jé kaj kvašenega, iztrebljena bode duša njegova iz Izraelove občine, bodisi tujec ali rojen v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 20, 'Nič kvašenega ne boste jedli, v vseh prebivališčih svojih jejte kruhe opresne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 21, 'In pokliče Mojzes vse starejšine Izraelove in jim reče: Izberite in vzemite zase drobnico, po rodbinah svojih, in zakoljite pasho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 22, 'In vzemite šopek izopa in pomočite ga v kri, ki je v medenici, in pomažite naddurje in oba podboja s krvjo, ki je v medenici; a nihče izmed vas naj ne hodi ven skozi duri hiše svoje do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 23, 'Gospod namreč pojde skozi Egipt, da udari Egipčane; ko bo pa videl kri na naddurju in na obeh podbojih, pojde Gospod mimo hišnih duri ter ne dopusti, da bi šel morilec v hiše vaše vas pogubljat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 24, 'Izpolnjujte torej to kot postavo zase in za otroke svoje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 25, 'In ko pridete v deželo, ki vam jo da Gospod, kakor je bil obljubil, izpolnjujte to službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 26, 'In kadar vam poreko vaši otroci: Kaj vam pomeni ta služba?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 27, 'odgovorite: Daritev pashe je to Gospodu, ki je šel mimo hiš Izraelovih sinov v Egiptu, ko je tepel Egipčane, in naše hiše je otel. In ljudstvo se je priklonilo in molilo Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 28, 'In sinovi Izraelovi so šli in storili tako; kakor je bil Gospod ukazal Mojzesu in Aronu, tako so storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 29, 'In zgodilo se je opolnoči, da je Gospod udaril vse prvorojeno v Egiptovski deželi, od prvenca Faraonovega, ki bi bil sedel na njegovem prestolu, do prvenca jetnikovega, ki je bil v ječi, tudi vso prvenščino živali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 30, 'In vstane Faraon po noči, on in vsi služabniki njegovi in vsi Egipčani, in nastalo je veliko vpitje po Egiptu, kajti ni bilo hiše, v kateri bi ne bilo mrtveca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 31, 'In pokliče Mojzesa in Arona po noči in veli: Vstanite in odidite izmed ljudstva mojega, vidva in sinovi Izraelovi, in pojdite, služite Gospodu, kakor sta govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 32, 'Tudi črede svoje in goveda svoja vzemite s seboj, kakor sta govorila, in pojdite; in me tudi blagoslovite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 33, 'In Egipčani so ljudstvo silili, da se hitro odpravi iz dežele; kajti govorili so: Vsi poginemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 34, 'In vzelo je ljudstvo testo svoje, preden se je skisalo, in svoje ponvice za pečenje, zavite v plaščih, na rame svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 35, 'In storili so sinovi Izraelovi, kakor je bil govoril Mojzes, in izprosili so od Egipčanov srebrnih in zlatih dragotin in oblačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 36, 'Gospod pa je podelil ljudstvu milost v očeh Egipčanov, da so jim dali, česar so prosili. In oplenili so Egipčane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 37, 'In odrinili so sinovi Izraelovi iz Ramesesa v Sukot, okoli šeststo tisoč pešcev, mož brez otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 38, 'Pa tudi dosti mešane druhali je šlo gori ž njimi, in črede in goveda, živine jako veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 39, 'In spekli so iz testa, ki so ga prinesli iz Egipta, opresne podpepelnike; kajti ni bilo skvašeno, ker so jih spodili iz Egipta, da se niso smeli obotavljati, pa tudi brašna si niso utegnili pripraviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 40, 'In prebivanja Izraelovih sinov, odkar so bivali v Egiptu, je bilo štiristo in trideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 41, 'In zgodilo se je ob koncu teh štiristo in tridesetih let, zgodilo se je ravno tisti dan, da so odrinile vse vojske Gospodove iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 42, 'To je noč, ki naj se slovesno praznuje Gospodu, ker jih je odpeljal iz dežele Egiptovske; to je noč Gospodova, ki naj se slovesno praznuje pri vseh Izraelovih sinovih v njih pokolenjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 43, 'In govoril je Gospod Mojzesu in Aronu: To bodi postava o velikonočnem jagnjetu: Noben tujec ne sme jesti od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 44, 'Vsakega hlapca pa, ki ga je kdo kupil z denarjem, obreži, potem naj jé od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 45, 'Priseljenec in najemnik ne jej od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 46, 'V eni hiši se bo jedlo: nič mesa njegovega ne nosite iz hiše in kosti nobene mu ne zlomite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 47, 'Vsa občina Izraelova naj ga obhaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 48, 'Če pa pri tebi biva tujec in želi obhajati pasho Gospodu, naj se obreže vsak moški, in potem naj pristopi in jo praznuje, in bodi on kakor rojen v deželi. Ali noben neobrezanec ne jej od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 49, 'Ista postava veljaj za domačina in za tujca, ki biva med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 50, 'In vsi sinovi Izraelovi so to storili: kakor je bil ukazal Gospod Mojzesu in Aronu, tako so storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 12, 51, 'In zgodilo se je ravno tisti dan, da je Gospod peljal sinove Izraelove iz Egiptovske dežele po njih vojnih krdelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 1, 'In govoril je Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 2, 'Posveti meni vse prvorojeno, vse, kar predre maternico med sinovi Izraelovimi, od človeka do živali: moje bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 3, 'In Mojzes je govoril ljudstvu: Spominjajte se tega dne, katerega ste šli iz Egipta, iz hiše sužnosti, zakaj z mogočno roko vas je izpeljal Gospod odtod; in nič kvašenega ne smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 4, 'Današnjega dne, v mesecu Abibu, odhajate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 5, 'In ko te privede Gospod v deželo Kanaancev in Hetejcev in Amorejcev in Hevejcev in Jebusejcev, za katero je bil prisegel očetom tvojim, da ti jo dá, deželo, ki v njej teče mleko in med: tedaj opravljaj to službo v temle mesecu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 6, 'Sedem dni boš jedel opresnike, in sedmi dan bo praznik Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 7, 'Opresniki se bodo jedli sedem dni, in ne sme biti pri tebi nič okvašenega in ne sme biti pri tebi nič kvasu v vseh krajih tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 8, 'In oznaniš ta dan sinu svojemu, rekoč: Delam to zaradi tega, kar je meni storil Gospod, ko sem šel iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 9, 'In to ti bodi v znamenje na roki tvoji in kakor spominski list med tvojimi očmi, zato da bode zakon Gospodov v ustih tvojih: zakaj z mogočno roko te je peljal Gospod iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 10, 'Zatorej izpolnjuj to postavo v času za to določenem, leto za letom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 11, 'In ko te privede Gospod v deželo Kanaancev, kakor je prisegel tebi in očetom tvojim, in ko ti jo dá,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 12, 'tedaj odmeni vse, kar predre maternico, Gospodu; tudi vsakega prvenca živine, ki jo boš imel, moškega spola, daj Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 13, 'A vsakega prvenca od osla odkupi z jagnjetom, če ga pa ne odkupiš, zlomi mu šijnjak; tudi odkupi vse prvorojence ljudi med sinovi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 14, 'In če te v prihodnjih časih vpraša sin tvoj, rekoč: Kaj pomeni to? mu odgovori: Z roko mogočno nas je peljal Gospod iz Egipta, iz hiše sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 15, 'In ker je bil Faraon trdovraten in nas ni hotel izpustiti, je Gospod udaril vse prvorojence v Egiptovski deželi, od prvenca človeka do prvorojene živali: zato darujem Gospodu vse prvence samce, vse prvorojence izmed otrok svojih pa odkupujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 16, 'In to ti bodi za znamenje na roki tvoji in kakor bi viselo za spomin med tvojimi očmi; zakaj s premogočno roko nas je peljal Gospod iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 17, 'In zgodilo se je, ko je Faraon odpustil ljudstvo, da jih Bog ni peljal po poti skozi Filistejsko deželo, čeprav je bila blizu; rekel je namreč Bog: Morda bi bilo ljudstvu žal, ko bi videli vojno; in bi se povrnili v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 18, 'Ampak Bog jih je obrnil na pot preko puščave k Rdečemu morju; in sinovi Izraelovi so šli oboroženi iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 19, 'In Mojzes je vzel kosti Jožefove s seboj, kajti on je s prisego zavezal sinove Izraelove, rekoč: Gotovo vas obišče Bog; odnesite potem kosti moje odtod s seboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 20, 'In odrinili so iz Sukota, in taborili so v Etamu, kraj puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 21, 'In Gospod je šel pred njimi, po dnevi v oblakovem stebru, da bi jih vodil po poti, po noči pa v ognjenem stebru, da bi jim svetil: tako so mogli potovati po dne in po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 13, 22, 'Nikoli se ni umaknil oblakov steber po dnevi, ne ognjeni steber po noči izpred ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 2, 'Govóri sinovom Izraelovim, naj se vrnejo in tabore pred Pihahirotom, med Migdolom in morjem, pred Baalzefonom; njemu nasproti razpnite šatore pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 3, 'Kajti Faraon poreče o Izraelovih sinovih: Zašli so v deželi, puščava jih je obdala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 4, 'Jaz pa hočem otrditi srce Faraonovo, da bo hitel za njimi, in hočem se oslaviti na Faraonu in na vsej vojski njegovi; in Egipčani spoznajo, da sem jaz Gospod. In storili so tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 5, 'In ko so kralju egiptovskemu sporočili, da je ljudstvo zbežalo, se izpremeni srce Faraonovo in služabnikov njegovih proti ljudstvu, in reko: Kaj smo to storili, da smo odpustili Izraelce iz službe svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 6, 'Zapreže torej svoj voz ter vzame ljudstvo svoje s seboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 7, 'vzame namreč šeststo izbranih voz in vse vozove egiptovske in bojevnike na vsakem iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 8, 'In Gospod je otrdil srce Faraona, kralja egiptovskega, da je dirjal za sinovi Izraelovimi. A sinovi Izraelovi so odhajali po visoki roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 9, 'Egipčani pa so hiteli za njimi, in vsi konji in vozovi Faraonovi, konjiki njegovi in vojska njegova so jih došli, ko so taborili pri morju ob Pihahirotu, nasproti Baalzefonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 10, 'Ko se je pa bližal Faraon, povzdignejo sinovi Izrelovi oči, in glej, Egipčani gredo za njimi; in ustrašijo se sinovi Izrelovi zelo in vpijejo h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 11, 'In govore Mojzesu: Ni li morda bilo nobenih grobov v Egiptu, da si nas odpeljal, da umrjemo v puščavi? Zakaj si nam to storil, da si nas izvedel iz Egipta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 12, 'Ali to ni beseda, ki smo ti jo govorili v Egiptu, rekoč: Pusti nas, naj služimo Egipčanom, zakaj bolje nam je služiti Egipčanom nego umreti v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 13, 'In Mojzes veli ljudstvu: Ne bojte se, stojte trdno in glejte rešitev Gospodovo, ki jo za vas izvrši danes; zakaj Egipčanov, ki jih danes vidite, ne boste nikdar več videli na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 14, 'Gospod se bo za vas bojeval, vi pa bodite mirni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 15, 'In Gospod reče Mojzesu: Zakaj vpiješ k meni? Véli Izraelovim sinovom, naj gredo naprej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 16, 'Ti pa povzdigni palico svojo in iztegni roko nad morje ter ga razdeli, in šli bodo sinovi Izraelovi sredi morja po suhem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 17, 'In glej, jaz otrdim srce Egipčanov, da pojdejo za vami; in hočem se oslaviti na Faraonu in na vsej vojski njegovi in na vseh vozovih in konjikih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 18, 'In Egipčani spoznajo, da sem jaz Gospod, kadar se oslavim na Faraonu, na njegovih vozeh in konjikih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 19, 'In vzdignil se je angel Gospodov, ki je šel pred vojsko Izraelcev, in gre zadaj za njimi, in oblakov steber izgine izpred njih in se postavi za njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 20, 'in pride med vojsko Egipčanov in vojsko Izraelovo; in tam je oblak delal temo, tu pa je razsvetljeval noč. In eni se niso drugim približali celo noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 21, 'Mojzes torej iztegne roko nad morje, in Gospod je odpravil morje s silnim vzhodnikom, ki je pihal celo noč, in je napravil v morju suha tla, in voda se je razdelila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 22, 'In sinovi Izraelovi so šli sredi morja po suhem, in vode so jim bile kakor zidovje na desni in na levi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 23, 'In Egipčani so gnali za njimi, in prišli so vsi konji Faraonovi, vozovi in konjiki njegovi v sredo morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 24, 'In zgodi se ob jutranji straži, da pogleda Gospod na vojsko Egipčanov iz ognjenega in oblakovega stebra in napravi zmešnjavo v vojski Egipčanov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 25, 'in stori, da se kolesa vozom izmaknejo, tako da so s težavo vozili. In Egipčani reko: Bežímo pred Izraelom, kajti Gospod se bojuje zanje proti Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 26, 'In Gospod reče Mojzesu: Iztegni roko nad morje, da se vode povrnejo na Egipčane, na njih vozove in jezdece.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 27, 'Tedaj iztegne Mojzes roko po morju, in povrnilo se je morje ob jutranjem svitu v navadno valovanje svoje; in Egipčani so bežali proti njemu, in Gospod jih je pognal v sredo vodovja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 28, 'In povrnile so se vode in zagrnile vozove in konjištvo vse vojske Faraonove, ki je šla za Izraelci v morje; ni preostalo izmed njih še enega ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 29, 'Ali sinovi Izraelovi so šli sredi morja po suhem, in vode so jim bile v zidovje na desni in na levi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 30, 'Tako je otel Gospod tisti dan Izraela iz roke Egipčanov. In videl je Izrael Egipčane mrtve ob bregu morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 14, 31, 'In videl je Izrael preveliko moč, ki jo je bil Gospod pokazal nad Egipčani, in balo se je ljudstvo Gospoda in verovalo je Gospodu in Mojzesu, njegovemu služabniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 1, 'Tedaj je pel Mojzes in sinovi Izraelovi tole pesem Gospodu, govoreč takole: Pel bom Gospodu, ker se je slavno poveličal: konja in jezdeca njegovega je pahnil v morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 2, 'Moč moja in pesem moja je Gospod, on mi je postal rešitev. Ta je moj Bog mogočni, slavil ga bom, očeta mojega Bog, poveličeval ga bom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 3, 'Gospod je pravi vojščak, Gospod je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 4, 'Faraonove vozove in vojsko njegovo je pahnil v morje, in najizvrstnejši vojvode njegovi so se pogreznili v Rdeče morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 5, 'Valovje jih je zagrnilo, pogreznili so se v globočine kakor kamen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 6, 'Desnica tvoja, Gospod, se je poveličala v moči, desnica tvoja, Gospod, je strla sovražnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 7, 'In v obilosti svojega veličastva si porazil nje, ki so se vzpenjali zoper tebe; izpustil si jezo svojo, ta jih je požrla kot strnišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 8, 'In z dihom nozdrvi tvojih so se nakopičile vode, tekoče vode so se postavile kakor jez, zgostili so se valovi v srcu morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 9, 'Rekel je sovražnik: Poženem se za njim, dohitim ga, delil bom plen, nasitila se jih bo pohlepnost moja; izderem meč svoj, roka moja jih pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 10, 'A ti si pihnil z vetrom svojim – morje jih je zagrnilo, potopili so se kakor svinec v silnih vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 11, 'Kdo je tebi enak med bogovi, Gospod? kdo je kakor ti, poveličan v svetosti, poln vzvišene slave, čudeže delajoč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 12, 'Iztegnil si desnico svojo, in požrla jih je zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 13, 'Ti si peljal v usmiljenju svojem ljudstvo, ki si ga bil odkupil; peljal si jih v moči svoji k prebivališču svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 14, 'Začuvši to, so vztrepetali narodi, strah je prevzel prebivalce filistejske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 15, 'Tedaj so se prestrašili vojvode edomski, trepet se je polastil korenjakov moabskih, zbali so se prebivalci kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 16, 'Naj jih obidejo strahovi in prešine groza, zaradi mogočnosti tvoje roke naj otrpnejo kakor kamen, dokler ne prejde mimo ljudstvo tvoje, Gospod, dokler ne prejde mimo ljudstvo, ki si ga sebi pridobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 17, 'Vpeljal jih boš in jih zasadil na gori dediščine svoje, na mesto, ki si ga pripravil, Gospod, za prebivanje svoje, v svetišče, Gospod, ki so ga utrdile roke tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 18, 'Gospod bo kraljeval vselej in vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 19, 'Kajti konji Faraonovi ž njegovimi vozovi in konjiki so šli v morje, in Gospod je poslal nadnje vode morja, sinovi Izraelovi pa so šli po suhem sredi morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 20, 'In Mirjama prorokinja, sestra Aronova, je vzela boben v roko, in vse žene so šle za njo z bobni in v kolu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 21, 'In Mirjama jim je odpevala: Pojte Gospodu, ker se je slavno poveličal: konja in jezdeca njegovega je pahnil v morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 22, 'In Mojzes ukaže, da odrine Izrael od Rdečega morja, in šli so v puščavo Sursko. In potujoč tri dni po puščavi, niso našli vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 23, 'In prišli so v Maro, pa niso mogli piti vode iz Mare, ker je bila grenka. Zato se imenuje ta kraj Mara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 24, 'In ljudstvo je mrmralo zoper Mojzesa, govoreč: Kaj bomo pili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 25, 'On pa je klical h Gospodu, in pokaže mu Gospod les, in ko ga je vrgel v vodo, je voda postala sladka. Tu mu je dal postavo in pravice, in tu ga je izkusil');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 26, 'in rekel: Ako boš res poslušal glas Gospoda, svojega Boga, in delal, kar je prav v očeh njegovih, in pazil na zapovedi njegove in čuval vse postave njegove, ne pošljem nad te nobene teh bolezni, ki sem jih poslal nad Egipt, zakaj jaz sem Gospod, zdravnik tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 15, 27, 'In prišli so v Elim, kjer je bilo dvanajst studencev in sedemdeset palm, in utaborili so se tam pri vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 1, 'In odrinili so iz Elima, in prišla je vsa občina sinov Izraelovih v puščavo Sinsko, ki je med Elimom in med Sinajem, petnajsti dan drugega meseca po svojem odhodu iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 2, 'In mrmrala je vsa občina sinov Izraelovih zoper Mojzesa in Arona v puščavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 3, 'in rekli so jima sinovi Izraelovi: O, da bi bili umrli po roki Gospodovi v deželi Egiptovski, ko smo sedeli pri loncih mesa in jedli kruh dosita! kajti izpeljala sta nas v to puščavo, da vso tole množico pomorita z lakoto!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 4, 'Tedaj reče Gospod Mojzesu: Glej, dežil vam bom kruh z neba; ljudstvo pa naj hodi in pobira vsak dan, kolikor tisti dan potrebuje, da ga izkusim, ali bo po mojem zakonu živelo ali ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 5, 'In šesti dan naj pripravijo, kar so nabrali, in bode dvakrat toliko, po kolikor so nabrali vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 6, 'In Mojzes in Aron sporočita vsem sinovom Izraelovim: Zvečer spoznate, da vas je Gospod peljal iz dežele Egiptovske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 7, 'in zjutraj boste videli slavo Gospodovo, ker je on slišal mrmranje vaše zoper Gospoda, kajti kaj sva midva, da mrmrate zoper naju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 8, 'In reče Mojzes: Po tem to spoznate, ko vam Gospod dá zvečer jesti mesa in zjutraj kruha dosita; ker je Gospod slišal mrmranje vaše, s katerim ste godrnjali zoper njega. Kaj sva pač midva? Ne zoper naju je mrmranje vaše, ampak zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 9, 'In veli Mojzes Aronu: Govori vsej občini sinov Izraelovih: Približajte se Gospodu, kajti slišal je mrmranje vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 10, 'In zgodilo se je, ko je Aron govoril vsej občini sinov Izraelovih, da se obrnejo proti puščavi, in glej, slava Gospodova se je prikazala v oblaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 11, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 12, 'Slišal sem mrmranje Izraelovih otrok; povej jim tole: Proti večeru boste jedli meso in zjutraj se nasitili kruha, in spoznali boste, da sem jaz Gospod, vaš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 13, 'In zgodi se zvečer, da so priletele prepelice in pokrile tabor; in zjutraj je ležala rosa okrog tabora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 14, 'Ko se je pa rosa vzdignila, glej, po površju puščave je nekaj drobnega, luskinastega, drobnega kakor slana na tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 15, 'In sinovi Izraelovi, videč to, so rekli drug drugemu: Kaj je to? niso namreč vedeli, kaj je. In Mojzes jim reče: To je tisti kruh, ki vam ga je dal Gospod za jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 16, 'To je beseda, ki jo je zapovedal Gospod: Vsak naj nabere tega, kolikor more pojesti; gomer za vsako glavo, po številu vaših duš; vsak naj vzame tega za tiste, ki so v njegovem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 17, 'In storili so tako sinovi Izraelovi, in nabrali so, eden več, drugi manj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 18, 'In so merili z gomerom: in kdor je mnogo nabral, mu ni ničesar preostalo, in kdor je malo nabral, mu ni ničesar manjkalo; vsakdo je nabral, prav kolikor je mogel snesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 19, 'In Mojzes jim veli: Nihče naj ne pusti kaj tega do jutra!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 20, 'Toda niso Mojzesa poslušali, in nekateri so pustili ostanek do jutra; in zaredili so se v tem črvi, in usmradilo se je. In razsrdil se je Mojzes nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 21, 'In nabirali so jutro za jutrom, vsakdo, kolikor je mogel pojesti; kadar pa je solnce pripekalo, se je raztajalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 22, 'In zgodi se šesti dan, da nabero kruha dvakrat toliko, dva gomera za enega. In pridejo vsi prvaki občine povedat to Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 23, 'In on jim reče: To je, kar je govoril Gospod: Jutri bo praznik, svet počitek Gospodu; kar hočete peči, pecite, in kar hočete kuhati, kuhajte, in karkoli preostane, denite na stran, da se prihrani do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 24, 'Deli so torej to na stran do jutra, kakor je ukazal Mojzes, a ni se usmradilo, tudi ni bilo črvov v tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 25, 'In Mojzes reče: Jejte to danes, kajti danes je praznik Gospodu, danes ne najdete nič tega na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 26, 'Šest dni boste nabirali, a sedmi dan je počitek, tedaj ne bo tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 27, 'Zgodi se pa sedmi dan, da so šli nekateri izmed ljudstva nabirat, a niso ničesar našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 28, 'In Gospod reče Mojzesu: Doklej se pa boste upirali, da spoštujete ukaze moje in povelja moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 29, 'Glejte, ker vam je Gospod dal praznik, zato vam daje šesti dan kruha za dva dni. Vsakdo naj ostane na svojem, nihče ne odhajaj s svojega kraja sedmi dan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 30, 'Počivalo je torej ljudstvo sedmi dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 31, 'In imenovala je hiša Izraelova ta kruh mano; bil je pa kakor belo koriandrovo seme in njegov okus kakor medeni kolači.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 32, 'In Mojzes je rekel: To je, kar je ukazal Gospod: Poln gomer tega naj se shrani za prihodnje rodove vaše, zato da vidijo kruh, s katerim sem vas hranil v puščavi, ko sem vas peljal iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 33, 'Veli torej Mojzes Aronu: Vzemi posodo in deni vanjo poln gomer mane, in položi jo pred Gospodom, da se hrani za prihodnje rodove vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 34, 'Kakor je bil ukazal Gospod Mojzesu, tako jo je Aron položil pred pričevanjem, da bodi shranjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 35, 'In jedli so sinovi Izraelovi mano štirideset let, dokler niso prišli v naseljeno deželo; jedli so mano, dokler niso prišli do meje dežele Kanaanske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 16, 36, 'Gomer pa je deseti del efe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 1, 'In vsa občina sinov Izraelovih je šla iz puščave Sinske po postajah svojih na povelje Gospodovo in se je utaborila v Rafidimu; ali ni bilo vode, da bi ljudstvo pilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 2, 'In prepiralo se je ljudstvo z Mojzesom in govorilo: Dajta nam vode, da pijemo! Mojzes jim pa odgovori: Kaj se pričkate z menoj? Zakaj izkušate Gospoda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 3, 'In bilo je tam ljudstvo žejno vode in je mrmralo zoper Mojzesa, govoreč: Zakaj si nas izpeljal iz Egipta? da z žejo umoriš mene, otroke moje in živino mojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 4, 'In vpil je Mojzes h Gospodu, rekoč: Kaj naj storim s tem ljudstvom? Še malo, pa me bodo s kamenjem posuli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 5, 'In Gospod reče Mojzesu: Stopi na čelo ljudstva in vzemi s seboj nekoliko starejšin Izraelovih; in palico svojo, s katero si udaril reko, vzemi v roko in pojdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 6, 'Glej, jaz bom stal pred teboj na Horebu tam na skali; ti pa udari skalo, in voda priteče iz nje, da bo ljudstvo pilo. In storil je Mojzes tako pred očmi starejšin Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 7, 'In ime tega mesta je imenoval Masa in Meriba zaradi prepira sinov Izraelovih in ker so izkušali Gospoda, govoreč: Ali je Gospod sredi nas ali ga ni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 8, 'In prišel je Amalek in se je bojeval z Izraelom v Rafidimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 9, 'In Mojzes veli Jozuetu: Izberi nam može in pojdi, bojuj se z Amalekom; jaz bom jutri stal na vrhu hriba s palico Božjo v roki svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 10, 'In storil je Jozue, kakor mu je rekel Mojzes, da bi se bojeval z Amalekom. Mojzes pa in Aron in Hur so stopili na vrh hriba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 11, 'In dokler je Mojzes kvišku držal roko, je zmagoval Izrael, kadar pa je povesil roko, je premagal Amalek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 12, 'A roke Mojzesove so se utrudile. Vzameta torej kamen in mu ga podložita, in on sede nanj; Aron pa in Hur podpirata roke njegove, eden na tej, drugi pa na drugi strani. Tako so njegove roke ostale trdne do solnčnega zahoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 13, 'In porazil je Jozue Amaleka in ljudstvo njegovo z meča ostrino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 14, 'Tedaj je Gospod rekel Mojzesu: Zapiši to v knjigo za spomin in ponavljaj vpričo Jozueta, da bom dočista izbrisal spomin Amalekov izpod neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 15, 'In Mojzes postavi oltar in imenuje ime njegovo: Jehova nisi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 17, 16, 'in reče: Res, roka je vzdignjena proti prestolu Gospodovemu: vojska Gospodova bo zoper Amaleka od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 1, 'In slišal je Jetro, duhovnik madianski, tast Mojzesov, o vsem, kar je storil Bog Mojzesu in Izraelu, ljudstvu svojemu, da je Gospod odpeljal Izraela iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 2, 'In vzame Jetro, tast Mojzesov, Ziforo, Mojzesovo ženo (potem ko jo je bil nazaj poslal),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 3, 'in njena dva sinova, katerih imeni sta: prvega Gerson, ker je rekel Mojzes: „Priseljenec sem v tuji zemlji“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 4, 'in drugega Eliezer, „kajti Bog očeta mojega mi je bil v pomoč in me je otel meča Faraonovega“;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 5, 'in pride Jetro, tast Mojzesov, ž njegovima sinoma in njegovo ženo k Mojzesu v puščavo, kjer je taboril pri gori Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 6, 'In sporoči Mojzesu: Jaz, tast tvoj Jetro, sem prišel k tebi in tvoja žena in ž njo dva sinova njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 7, 'In Mojzes pride naproti tastu svojemu, in prikloni se ter ga poljubi; nato vprašata drug drugega, če se jima dobro godi, in gresta v šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 8, 'In Mojzes pripoveduje tastu svojemu vse, kar je storil Gospod nad Faraonom in nad Egipčani zaradi Izraela, in o vseh težavah, ki so jih prebili na potovanju, in kako jih je reševal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 9, 'In vzradostil se je Jetro ob vsej dobroti, ki jo je Gospod storil Izraelu, da ga je otel iz roke Egipčanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 10, 'In reče Jetro: Hvaljen bodi Gospod, ki vas je otel iz roke Egipčanov in iz roke Faraonove, ki je otel to ljudstvo izpod pesti Egipčanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 11, 'Zdaj vem, da je Gospod večji od vseh bogov: zakaj ravno v tem, s čimer so prevzetovali, se je povišal nad nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 12, 'In daroval je Jetro, tast Mojzesov, žgalne in klalne daritve Bogu; Aron pa in vsi starejšine Izraelovi so prišli, da bi jedli kruh s tastom Mojzesovim pred obličjem Božjim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 13, 'In zgodi se zjutraj, da se je usedel Mojzes, da bi sodil ljudstvu; in ljudstvo je stalo pred Mojzesom od jutra do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 14, 'In videl je tast Mojzesov vse, kar dela z ljudstvom, in je rekel: Kakšno opravilo je to, ki ga imaš z ljudstvom? Zakaj sediš ti edini, vse ljudstvo pa stoji pred teboj od jutra do večera?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 15, 'In odgovori Mojzes tastu svojemu: Ljudstvo prihaja k meni posvetovat se z Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 16, 'Ko imajo kako pravdo, pridejo k meni, in jaz razsojam med njimi in jim naznanjam Božja pravila in postave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 17, 'In njegov tast mu reče: Ni dobro, kar delaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 18, 'Preveč se utrudiš in tudi to ljudstvo, ki je pri tebi; pretežavno je to delo zate; sam ga ne moreš vršiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 19, 'Zdaj pa čuj moj glas, hočem ti dati svet, in Bog bode s teboj: Bodi zastopnik ljudstva pred Bogom in donašaj njih zadeve pred Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 20, 'in razjasnjuj jim pravila in postave in oznanjaj jim pot, po katerem naj hodijo, in delo, ki naj ga opravljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 21, 'Toda ozri se med vsem ljudstvom po vrlih možeh, bogaboječih, ki so vdani resnici, sovražni krivičnemu dobičku; in postavi jih za načelnike čez tisoč, načelnike čez sto, načelnike čez petdeset in za načelnike čez deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 22, 'Oni naj sodijo ljudstvu vsak čas; in vse velike zadeve naj razgrnejo tebi, karkoli pa bo manjšega, naj sodijo sami: tako olajšaj sebi, in oni naj nosijo breme s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 23, 'Če ta nasvet izpolniš in ti Bog to ukaže, boš mogel prestati, pa tudi to ljudstvo pride vse do kraja svojega v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 24, 'In Mojzes je slušal glas svojega tasta ter storil vse, kar mu je rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 25, 'In izbral je Mojzes vrlih mož izmed vseh Izraelcev in jih postavil za poglavarje nad ljudstvom: za načelnike čez tisoč, načelnike čez sto, načelnike čez petdeset in za načelnike čez deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 26, 'In sodili so ljudstvu vsakteri čas: težke stvari so razgrinjali Mojzesu, karkoli pa je bilo manjšega, so sodili sami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 18, 27, 'In Mojzes se je poslovil od svojega tasta, ta pa je šel v deželo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 1, 'Tretji mesec po odhodu sinov Izraelovih iz dežele Egiptovske, v isti dan so prišli v Sinajsko puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 2, 'Odrinili so bili iz Rafidima in prišli v Sinajsko puščavo, in utaborili so se v puščavi; tamkaj je Izrael gorovju nasproti razpel šatore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 3, 'In Mojzes je stopil gori k Bogu, in Gospod mu je klical z gore, govoreč: Tako govóri hiši Jakobovi in oznani sinovom Izraelovim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 4, 'Sami ste videli, kaj sem storil Egiptu in kako sem vas nosil na orlovih perotih in vas privedel k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 5, 'In sedaj, če boste resno poslušali glas moj in držali zavezo mojo, bodete moja dragotina pred vsemi narodi, kajti moja je vsa zemlja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 6, 'in bodete mi kraljestvo duhovnikov in svet narod. To so besede, ki jih boš govoril sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 7, 'In Mojzes pride in skliče starejšine ljudstva in jim predloži vse te besede, ki mu jih je ukazal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 8, 'In odgovori vse ljudstvo hkrati, rekoč: Storiti hočemo vse, kar je govoril Gospod. In sporočil je Mojzes besede ljudstva Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 9, 'In Gospod reče Mojzesu: Glej, jaz pridem k tebi v temnem oblaku, zato da bi čulo ljudstvo govor moj s teboj ter da bi ti tudi verovalo vekomaj. In Mojzes je oznanil Gospodu besede ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 10, 'In Gospod reče Mojzesu: Idi k ljudstvu in posveti jih danes in jutri, in naj operejo oblačila svoja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 11, 'in naj bodo pripravljeni za tretji dan, zakaj tretjega dne pride Gospod pred očmi vsega ljudstva na goro Sinaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 12, 'In napravi mejo ljudstvu okrog in reci: Varujte se stopiti na goro ali dotekniti se njenega kraja; kdorkoli se gore dotakne, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 13, 'Ne bo se ga doteknila nobena roka, ampak kamenali ga bodo ali ustrelili, bodi žival, bodi človek, živ ne sme ostati. Ko bo trobenta zategnjeno donela, pojdejo proti gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 14, 'In prišel je Mojzes doli z gore k ljudstvu, in posvetil je ljudstvo, in oprali so oblačila svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 15, 'In rekel je ljudstvu: Bodite pripravljeni za tretji dan, ne približajte se ženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 16, 'In ko napoči jutro tretjega dne, nastane grmenje in bliskanje in temni oblaki na gori in silno močne trombe glas; in treslo se je vse ljudstvo, ki je bilo v taboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 17, 'In Mojzes je vedel ljudstvo iz tabora Bogu naproti; in postavili so se spodaj ob gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 18, 'Vsa gora Sinaj pa se je kadila, zato ker je bil Gospod stopil nanjo v ognju, in njen dim se je valil kvišku kakor dim iz topilne peči; in vsa gora se je silno tresla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 19, 'In glas trombe je bil čimdalje močnejši; Mojzes je govoril, in Bog mu je odgovarjal z glasom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 20, 'In Gospod je stopil doli na goro Sinaj, na vrh gore, in poklical je Gospod Mojzesa na vrh gore, in Mojzes je šel tja gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 21, 'In Gospod reče Mojzesu: Stopi doli, posvari ljudstvo, naj nikar naprej ne silijo h Gospodu, hoteč gledati, da jih ne pade veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 22, 'Pa tudi duhovniki, ki pristopajo h Gospodu, naj se posveté, da se Gospod ne zažene vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 23, 'In Mojzes reče Gospodu: Ljudstvo ne more stopiti na goro Sinaj, ker si nas sam posvaril, rekoč: Napravi ograjo okoli gore in posveti jo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 24, 'In Gospod mu reče: Idi doli, in potem pridi sem ti in Aron s teboj; a duhovniki in ljudstvo naj ne silijo naprej, hoteč pristopiti h Gospodu, da se ne zažene vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 19, 25, 'In Mojzes je prišel doli k ljudstvu in jim povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 1, 'In Bog je govoril vse te besede, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 2, 'Jaz sem Gospod, Bog tvoj, ki sem te izpeljal iz dežele Egiptovske, iz hiše sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 3, 'Ne imej drugih bogov zraven mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 4, 'Ne delaj si rezanih podob niti nikakršnih podob tega, kar je zgoraj na nebu, kar je spodaj na zemlji in kar je v vodah pod zemljo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 5, 'ne moli jih in ne časti jih, zakaj jaz sem Gospod, Bog tvoj, Bog mogočni, goreči, ki obiskujem krivico očetov na sinovih do tretjega in četrtega pokolenja tistih, ki me sovražijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 6, 'in izkazujem milost tisočim onih, ki me ljubijo in izpolnjujejo zapovedi moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 7, 'Ne imenuj po nemarnem imena Gospoda, svojega Boga, zakaj Gospod ne pusti brez kazni njega, ki bi imenoval ime njegovo po nemarnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 8, 'Spominjaj se sobotnega dne, da ga posvečuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 9, 'Šest dni boš delal in opravljal ves posel svoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 10, 'ali sedmi dan je čas počitka Gospodu, Bogu tvojemu: v njem ne opravljaj nobenega dela, ne ti, ne sin tvoj, ne hči tvoja, ne hlapec tvoj, ne dekla tvoja, ne živina tvoja, niti tujec, ki je v vratih tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 11, 'Zakaj v šestih dneh je ustvaril Gospod nebo in zemljo, morje in vse, kar je v njih, in sedmi dan je počival: zato je blagoslovil sobotni dan in ga posvetil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 12, 'Spoštuj očeta svojega in mater svojo, da se podaljšajo dnevi tvoji v deželi, katero ti da Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 13, 'Ne ubijaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 14, 'Ne prešeštvuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 15, 'Ne kradi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 16, 'Ne govori krivega pričevanja zoper bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 17, 'Ne poželi hiše bližnjega svojega, ne poželi žene bližnjega svojega, ne hlapca njegovega, ne dekle njegove, ne vola, ne osla njegovega, ne ničesar, kar je bližnjega tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 18, 'In vse ljudstvo je čulo grmenje in trombe glas in videlo plamene in kadečo se goro; in ko je ljudstvo to videlo, je trepetalo in se postavilo oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 19, 'In rekli so Mojzesu: Govóri ti z nami, in poslušali bomo; nikar pa naj ne govori z nami Bog, da ne umrjemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 20, 'In Mojzes reče ljudstvu: Ne bojte se, kajti zato, da bi vas izkusil je prišel Bog, in zato, da bode strah njegov pred vašim obličjem da ne grešite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 21, 'In stalo je ljudstvo oddaleč, Mojzes pa se je približal temi, v kateri je bil Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 22, 'In govoril je Gospod Mojzesu: Tako porečeš sinovom Izraelovim: Sami ste videli, da sem iz nebes govoril z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 23, 'Ne delajte si ničesar zraven mene, bogov iz srebra in bogov iz zlata si nikar ne delajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 24, 'Napraviš mi oltar iz prsti, in na njem boš daroval svoje žgalne in mirovne daritve, svojo drobnico in goved svojo; na vsako mesto, kjerkoli storim, da se bo spominjalo imena mojega, bom prihajal k tebi in te blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 25, 'In če mi napraviš oltar iz kamenja, ne gradi ga iz rezanih kamenov: kajti ako si vihtel nad njim železo svoje, si ga oskrunil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 20, 26, 'Tudi ne boš stopal po stopnicah k oltarju mojemu, da se ne odkrije sramota tvoja pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 1, 'In to so sodne pravice, ki jim jih predložiš:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 2, 'Če kupiš hlapca Hebrejca, bo šest let služil, in sedmo leto odide v svobodo brezplačno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 3, 'Ako je prišel sam, sam tudi odide; ako je imel ženo, odide žena njegova ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 4, 'Ako mu je dal njegov gospodar ženo in mu je rodila sinove ali hčere, tedaj bodo žena in otroci njeni njenega gospodarja, in on odide sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 5, 'Ako bi pa rekel tisti hlapec: Ljubim gospodarja svojega, ženo svojo in otroke svoje, ne maram oditi v svobodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 6, 'tedaj ga pripelje njegov gospodar pred sodnike, in postavi ga k vratom ali k podboju in mu prebodi uho s šilom; in bode mu hlapec za vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 7, 'Če kdo proda svojo hčer za deklo, ne odide, kakor odhajajo hlapci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 8, 'Ako ne bi ugajala svojemu gospodu, ki si jo je zaročil, naj ji dovoli, da se odkupi; tujemu narodu je ne bo smel prodati, ker je nevzesto ravnal ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 9, 'Ako jo pa zaroči sinu svojemu, ji izkaži pravico, kakršno imajo hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 10, 'Ako si vzame drugo za ženo: njenega živeža, njene obleke in zakonske dolžnosti naj ji ne krati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 11, 'In ako ji ne da teh treh reči, naj odide brezplačno, brez odkupnine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 12, 'Kdor udari človeka, da umrje, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 13, 'Ako ga pa ni zalezoval, a Bog je pripustil, da je roka njegova smrtno zadela, ti odločim mesto, kamor naj zbeži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 14, 'Ako pa kdo snuje zlobo proti bližnjemu svojemu, da bi ga s prevaro usmrtil, ga odpraviš celo od oltarja mojega, da umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 15, 'In kdor udari očeta svojega ali mater svojo, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 16, 'In kdor ukrade človeka in ga proda, ali če ga najdejo v roki njegovi, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 17, 'In kdor preklinja očeta svojega ali mater svojo, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 18, 'Če se moža spreta in drug drugega udarita s kamenom ali pa s pestjo, pa ne umre, ampak obleži v postelji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 19, 'ko zopet vstane in hodi zunaj ob palici, ne bodi kaznjen tisti, ki ga je udaril; samo naj mu poplača, kar je zamudil, in poskrbi mu, da popolnoma ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 20, 'In če kdo tepe hlapca svojega ali deklo svojo s šibo, da umrjeta pod roko njegovo, mora biti kaznovan;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 21, 'ako pa preživita eden ali dva dni, ne bodi kaznovan, ker sta njegov denar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 22, 'In če se možje tepó in udari kdo nosečo ženo, da izgubi zarod, druga poškodba pa se ji ne zgodi: mora plačati kazen v denarju, kolikor mu naloži mož tiste žene, in plača naj, kakor bodo sodniki določili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 23, 'Če se pa zgodi poškodba, se mora dati življenje za življenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 24, 'oko za oko, zob za zob, roka za roko, noga za nogo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 25, 'opeklina za opeklino, rana za rano, bula za bulo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 26, 'In če kdo udari svojega hlapca ali svojo deklo v oko in ga skazi, naj ga odpusti v svobodo za oko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 27, 'In če izbije zob svojemu hlapcu ali dekli svoji, naj ga odpusti v svobodo za zob njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 28, 'In če vol pobode moža ali ženo, da umrjeta, bodi vol kamenan in mesa njegovega ne smejo jesti; volov gospodar pa bodi brez krivde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 29, 'Ako pa je bil vol bodljiv poprej in so posvarili gospodarja njegovega, pa ga ni zapiral, in usmrti moža ali ženo, naj kamenajo vola in tudi gospodarja njegovega naj umoré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 30, 'Če se mu pa naloži poravnava, naj plača za odrešitev življenja svojega vse, kolikor mu nalože.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 31, 'Najsi je pobodel sina ali hčer, naj ravnajo ž njim po tem sodnem pravu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 32, 'Ako pa vol pobode hlapca ali deklo, naj plača njegov lastnik njiju gospodarju trideset srebrnikov, in vola naj s kamenjem posujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 33, 'In če kdo odpre jamo ali če kdo izkoplje jamo in je ne pokrije, in pade vanjo vol ali osel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 34, 'naj povrne posestnik jame: v denarju naj plača njiju gospodarju, mrtva žival pa bodi njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 35, 'In če vol rani vola sosedovega, da pogine, naj prodasta živega vola in si razdelita izkupiček, pa tudi mrtvega vola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 21, 36, 'Ako pa se je vedelo, da je bil vol bodljiv poprej in ga ni zapiral njegov gospodar, naj povrne vola za vola, in mrtvi bodi njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 1, 'Če kdo ukrade vola ali ovco in zakolje ali proda živinče, naj povrne pet volov za vola in štiri ovce za ovco.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 2, 'Ako se zasači tat pri vlomu in ga kdo udari, da umrje, ne bodi kriv krvi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 3, 'ako pa mu je že izšlo solnce, bodi sojen zaradi krvi. Tat mora vsekakor povrniti: ako nima ničesar, bodi prodan za svojo tatvino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 4, 'Ako se najde v roki njegovi, kar je ukradel, živo, bodi vol ali osel ali ovca, naj povrne dvojno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 5, 'Če kdo popase njivo ali vinograd in izpusti živino svojo, da naj se pase na njivi drugega, povrne škodo z najboljšim, kar ima na njivi svoji in v vinogradu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 6, 'Ako nastane ogenj in se vname trnje in zgori kopica snopja ali rastoče žito ali polje, mora povrniti, kdor je zažgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 7, 'Če kdo shrani pri svojem prijatelju denar ali blago, in bode ukradeno iz hiše tega moža: ako se tat najde, mora dvojno povrniti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 8, 'ako tatu ne najdejo, naj se postavi hišni gospodar pred sodnike, ni li iztegnil roke svoje po blagu bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 9, 'Ob vsakem poneverjenju, če gre za vola, ali osla, ali ovco, ali obleko ali za katerokoli izgubljeno reč, o kateri se pravi: Moja je, naj pride pravda obeh strank pred sodnike: kogar sodniki spoznajo za krivega, ta naj dvojno plača bližnjemu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 10, 'Če kdo shrani pri svojem sosedu osla ali vola ali ovco ali kako drugo žival, in ta pogine ali bode poškodovana ali odpeljana, ne da bi kdo videl to:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 11, 'prisega Gospodova naj odloči med njima, ni li iztegnil roke svoje po blagu bližnjega svojega, in lastnik njegov jo sprejme, in oni ne bo dolžan povrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 12, 'Ako pa mu je bilo ukradeno, naj povrne lastniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 13, 'Če je zver raztrgala živinče, naj to prinese v potrdilo; raztrganega mu ni treba povrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 14, 'In če si kdo izposodi od svojega bližnjega živino, in bode poškodovana ali pogine v nenavzočnosti gospodarjevi, mu jo mora povrniti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 15, 'ako pa je gospodar zraven, mu je ne povrne: najeta je bila, in vštelo se je v najemščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 16, 'Če kdo zapelje devico, ki ni še zaročena, in leži ž njo, mora plačati doto in si jo vzeti za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 17, 'Če mu je pa njen oče nikakor noče dati, naj odšteje denarja primerno doti, navadni za device.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 18, 'Čarovnici ne daj živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 19, 'Kdorkoli leži z živino, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 20, 'Kdor daruje bogovom mimo samega Gospoda, bodi iztrebljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 21, 'Tujcu ne delaj sile in ga ne tlači, kajti tujci ste bili v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 22, 'Nobene vdove in sirote ne žalite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 23, 'Če jih kakorkoli razžališ in bodo vpile k meni, gotovo uslišim njih vpitje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 24, 'in razvname se jeza moja, in vas pomorim z mečem, da bodo žene vaše vdove in otroci vaši sirote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 25, 'Če denarja posodiš ljudstvu mojemu, ubožcu, ki biva zraven tebe, ne bodi mu kakor oderuh, tudi mu ne naloži obresti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 26, 'Če sploh prejmeš plašč bližnjega svojega v zastavo, povrni mu ga, preden solnce zaide;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 27, 'kajti to je edina odeja njegova, obleka za nagoto njegovo: v čem naj bi spal? In zgodi se, če bo vpil k meni, da ga uslišim, kajti jaz sem milostljiv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 28, 'Sodnikov ne kolni in kneza ljudstva svojega ne preklinjaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 29, 'Ne odlašaj darovati od obilosti žita svojega in tekočine svoje. Prvenca izmed sinov svojih daruj meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 30, 'Enako delaj z govedjo in drobnico svojo: sedem dni naj ostane pri materi svoji, osmi dan jo pa daruj meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 22, 31, 'In sveti možje mi bodite; zato mesa, ki je na polju raztrgano od zveri, ne jejte, temuč ga vrzite psom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 1, 'Ne raznašaj lažnivega govorjenja; ne podajaj roke svoje krivičniku, da bodeš priča za nepravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 2, 'Ne potegni z množico, da bi delal zlo; in v pravdi ne govóri iz nagnjenja do množice, da se izprevrne sodba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 3, 'Tudi na ubožca se ne oziraj v pravdi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 4, 'Ako srečaš vola sovražnika svojega ali osla, da je zašel, pripelji mu ga varno nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 5, 'Ako vidiš osla sovražilca svojega, da leži pod tovorom svojim, ne hodi mimo, ne da bi mu pomagal: rad mu pomozi ž njim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 6, 'Ne zavijaj pravice siromaku svojemu v pravdi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 7, 'Ogiblji se nepoštene reči. Nedolžnega in pravičnega ne ubijaj, zakaj krivičnega ne opravičim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 8, 'Ne jemlji daril, kajti darilo oslepi nje, ki gledajo z odprtimi očmi, in preobrne besede pravičnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 9, 'In tujca ne tlači, zakaj veste, kako je v duši tujcu, ker ste sami bili tujci v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 10, 'Šest let posevaj zemljo svojo in spravljaj pridelke njene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 11, 'a sedmo leto naj ti leži in počiva, da jo uživajo ubožci tvojega ljudstva, in kar po njih preostane, naj pojé poljska zverina. Prav tako delaj z vinogradom in z olivnikom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 12, 'Šest dni opravljaj posel svoj in sedmi dan počivaj, da se odpočijeta vol in osel tvoj in se oddahneta sin dekle tvoje in tujec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 13, 'In pazite na vse, kar sem vam rekel; in imena tujih bogov ne omenjajte, še sliši naj se ne iz vaših ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 14, 'Trikrat v letu mi posvečuj praznik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 15, 'Praznik opresnikov praznuj: sedem dni boš jedel opresen kruh, kakor sem ti zapovedal, v določeni čas v mesecu Abibu, kajti v njem si šel iz Egipta; in nihče naj se ne prikaže prazen pred mojim obličjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 16, 'in praznik žetve, prvin tvojega pridelka, tistega, kar seješ na polju; in praznik spravljanja ob koncu leta, kadar pospraviš svoje pridelke s polja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 17, 'Trikrat v letu naj se prikažejo vsi moški tvoji pred obličjem Gospoda Jehove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 18, 'Ne daruj krvi daritve moje zraven kvašenega kruha, in masti od mojega praznika naj ne ostane do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 19, 'Prve prvine plodov zemlje svoje prinesi v hišo Gospoda, svojega Boga. Ne kuhaj kozliča v matere njegove mleku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 20, 'Glej, jaz pošiljam angela svojega pred teboj, da te varuje na potu in te pripelje v kraj, katerega sem pripravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 21, 'Pazi se obličja njegovega in poslušaj njegov glas; ne upiraj se mu, ker ne izpregleda prestopkov vaših, zakaj moje ime je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 22, 'Če boš pa pazljivo poslušal njegov glas in delal vse, kar govorim: sovražnik bodem tvojim sovražnikom in nasprotnikom tvojim nasprotnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 23, 'Kajti angel moj pojde pred teboj in te privede k Amorejcem in Hetejcem in Ferizejcem in Kanaancem in Hevejcem in Jebusejcem, in jih iztrebim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 24, 'Ne klanjaj se njih bogovom in jim ne služi, tudi ne delaj po njih delih, marveč docela jih razruši in dočista poteri njih stebre s podobami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 25, 'In služite Gospodu, Bogu svojemu, in blagoslovil bo kruh tvoj in vodo tvojo, in odpravim bolezen izmed vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 26, 'Ne bode je, ki bi negodno rodila, ne nerodovitne v deželi tvoji; število dni tvojih dopolnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 27, 'Strah svoj pošljem pred teboj ter zbegam vsa ljudstva, h katerim prideš, in vse sovražnike tvoje poženem v beg pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 28, 'In pošljem pred teboj sršene, ki bodo pregnali Hevejce, Kanaance in Hetejce izpred tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 29, 'Ne preženem jih izpred tebe v enem letu, da se ne opustoši dežela in se ne pomnože poljske zveri zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 30, 'Pomalem jih preženem izpred tebe, dokler se ne razmnožiš in ne posedeš dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 31, 'In postavim mejo tvojo od Rdečega morja do morja Filistejcev in od puščave do velereke; kajti v roko tvojo dam prebivalce tiste dežele, in izgnal jih boš pred seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 32, 'Zaveze ne skleni ž njimi, ne ž njih bogovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 23, 33, 'Ne prebivajo naj v tvoji deželi, da te ne zapeljejo v greh zoper mene; zakaj če bi služil njih bogovom, bi ti gotovo bilo v zanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 1, 'In Mojzesu je rekel: Pridi gori h Gospodu, ti in Aron, Nadab in Abihu in sedemdeset izmed starejšin Izraelovih, in molite oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 2, 'In Mojzes sam naj pristopi h Gospodu, oni pa naj ne pristopijo, in tudi ljudstvo naj ne hodi gori ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 3, 'In Mojzes gre in pove ljudstvu vse besede Gospodove in vse sodne pravice; in vse ljudstvo odgovori z enim glasom, rekoč: Storiti hočemo vse besede, ki jih je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 4, 'In Mojzes je napisal vse besede Gospodove. In vstane zgodaj zjutraj in sezida oltar pod goro in dvanajst kamenenih spomenikov po številu dvanajstih rodov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 5, 'In pošlje izmed Izraelovih otrok mladeniče, ki so darovali žgalne daritve in klali mirovne daritve juncev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 6, 'In Mojzes vzame polovico krvi in jo dene v medenice, z drugo polovico krvi pa poškropi oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 7, 'In vzame knjigo zaveze in bere, da sliši ljudstvo. In rekli so: Storiti hočemo vse, kar je govoril Gospod, in pokorni bodemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 8, 'In Mojzes vzame kri in poškropi ž njo ljudstvo in reče: Glejte, kri zaveze, ki jo je Gospod z vami sklenil na podlagi vseh teh besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 9, 'Tedaj so šli gori Mojzes in Aron, Nadab in Abihu in sedemdeset izmed starejšin Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 10, 'In videli so Boga Izraelovega: in pod njegovimi nogami je bilo kakor tla iz safirovih plošč in kakor nebo, kadar je jasno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 11, 'In ni iztegnil roke svoje zoper plemenitnike Izraelovih sinov, in videli so Boga in so jedli in pili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 12, 'In Gospod reče Mojzesu: Stopi k meni na goro in bodi tukaj; in dam ti kameniti plošči ter postavo in zapoved, katero sem napisal, da jih učiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 13, 'Mojzes torej vstane in Jozue, strežnik njegov, in Mojzes stopi na goro Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 14, 'Starejšinam pa je bil rekel: Ostanite tukaj, dokler se k vam ne povrneva; in glejte, Aron in Hur sta pri vas: če ima kdo kako reč, naj pride k njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 15, 'In Mojzes stopi na goro, in oblak pokrije goro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 16, 'In slava Gospodova je počivala na gori Sinajski, in oblak jo je pokrival šest dni; in sedmi dan je poklical Mojzesa iz sredi oblaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 17, 'In kazala se je slava Gospodova kakor požirajoč ogenj na vrhu gore pred očmi sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 24, 18, 'In Mojzes je šel v sredo oblaka in stopil na goro; in bil je Mojzes na gori štirideset dni in štirideset noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 2, 'Véli sinovom Izraelovim, naj mi prineso dar povzdignjenja; od vsakega, kogar izpodbode srce njegovo, vzemite dar povzdignjenja meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 3, 'In to je dar povzdignjenja, ki ga jemljite od njih: zlato, srebro, bron,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 4, 'višnjevo in zagorelordeče blago in karmezin in tenčica in kozja dlaka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 5, 'rdeče barvane ovnove kože in jazbečeve kože in akacijev les;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 6, 'olje za svetilnice, dišave za mazilno olje in za dišeče kadilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 7, 'onihovi kameni in drugi kameni, ki se vdenejo na naramnik in naprsnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 8, 'In naredé naj mi svetišče, da bom prebival med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 9, 'Kakor ti kažem vzorec prebivališča in vzorce vse oprave njegove, prav tako naredite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 10, 'Narede naj torej skrinjo iz akacijevega lesa: dva in pol komolca bodi nje dolgost, poldrugi komolec nje širjava in poldrugi komolec visokost njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 11, 'In prevleci jo s čistim zlatom, odznotraj in odzunaj jo prevleci; in napravi vrhu nje zlat venec naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 12, 'In zliješ zanjo štiri zlate obode in jih deneš na njene štiri noge: dva oboda bodeta na eni strani in dva oboda na drugi strani njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 13, 'In naredi dva droga iz akacijevega lesa in ju okuj z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 14, 'In vtakni ta droga v obode na obeh straneh skrinje, da se skrinja prenaša ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 15, 'Droga naj ostaneta v obodih skrinje, ne smeta se odstraniti iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 16, 'V skrinjo pa deni pričevanje, ki ti ga dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 17, 'In naredi pokrov sprave iz čistega zlata: dva in pol komolca bodi dolg in poldrugi komolec širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 18, 'Naredi tudi dva kerubima iz zlata; s tolkljanim delom ju naredi na obeh koncih spravnega pokrova:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 19, 'enega keruba na tej strani in enega na drugi strani, sceloma s spravnim pokrovom naredi keruba na obeh koncih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 20, 'In keruba naj razprostirata peruti navzgor, zaslanjajoč s svojimi perutmi pokrov, z obrazoma drug proti drugemu; proti pokrovu sprave bodita obrnjeni obličji kerubov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 21, 'In deni pokrov sprave na vrh skrinje, in v skrinjo deni pričevanje, katero ti dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 22, 'In tam se bom shajal s teboj in ti govoril iznad spravnega pokrova, iz sredi dveh kerubov, ki sta na skrinji pričevanja, vse, kar ti bom zapovedoval za sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 23, 'Naredi tudi mizo iz akacijevega lesa: dva komolca bodi dolga in en komolec široka in poldrugi komolec visoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 24, 'In prevleci jo s čistim zlatom in napravi na njej zlat venec naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 25, 'In naredi k njej kroginkrog spojno deščico, za dlan široko, in napravi zlat venec tej deščici naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 26, 'In naredi zanjo štiri roče iz zlata in deni te roče na štiri vogle pri štirih njenih nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 27, 'Tik pod deščico naj bodo roči, da se vanje vtakneta droga, s katerima se bo prenašala miza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 28, 'In droga naredi iz akacijevega lesa in ju okuj z zlatom, in ž njima naj se prenaša miza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 29, 'In naredi zanjo sklede, torila, konvice in vrčke, s katerimi se bo izlivalo; iz čistega zlata jih naredi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 30, 'In položi na mizo kruhe obličja, ki naj bodo pred obličjem mojim neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 31, 'Napravi tudi svečnik iz čistega zlata: s tolkljanim delom naj ga narede, stojalo in deblo njegovo; čašice, glavice in cvetice njegove naj bodo sceloma delane ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 32, 'In šest vej naj se razpenja iz debla njegovega: tri veje od ene strani in tri veje od druge strani svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 33, 'Tri čašice, slične mandeljnovemu cvetu, naj bodo z glavico in cvetico na eni veji, in prav enako na veji drugi; in tako bodi na šesterih vejah, ki se razpenjajo iz svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 34, 'Na svečnikovem deblu pa naj bodo štiri čaše, slične mandeljnovemu cvetu, s svojimi glavicami in cveticami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 35, 'namreč ena glavica pod vsakima dvema vejama, ki se jih razpenja šest iz ene celote, iz svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 36, 'Njegove glavice in veje morajo biti ena celota ž njim, vse bodi enotno tolkljano delo, iz zlata čistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 37, 'In njegovih svetilnic naredi sedem; in prižgo naj svetilnice njegove, da svetijo prav v ospredje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 38, 'Njegova utrinjala in lončki za utrinke naj bodo iz čistega zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 39, 'Iz enega talenta čistega zlata bodi narejen z vsemi temi pripravami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 25, 40, 'Glej pa, da narediš vse reči po njih vzorcu, ki ti je bil pokazan na gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 1, 'In naredi prebivališče iz desetih preprog; iz sukane tenčice in iz višnjevega in zagorelordečega in karmezinovega blaga, s kerubi umetno pretkane jih narediš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 2, 'Dolgost preproge bodi osemindvajset komolcev, širjava pa štiri komolce: ista mera bodi vsem preprogam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 3, 'Pet preprog naj se zveže skupaj, tudi pet drugih preprog naj se stakne skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 4, 'In naredi pentlje iz višnjeve preje na robu ene preproge, ob kraju ene zveze, enako naredi tudi na robu druge preproge, ob kraju druge zveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 5, 'Petdeset pentelj napravi na prvi preprogi in petdeset pentelj napravi na robu druge preproge, kjer se bo vezala s prvo; pentlja bodi pentlji nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 6, 'In naredi petdeset zapon iz zlata in stakni preprogi drugo z drugo s temi zaponami, da bode prebivališče celota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 7, 'In naredi preproge iz kozje dlake, da bodo šator nad prebivališčem; enajst takih preprog narediš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 8, 'Dolgost ene preproge bodi trideset komolcev, širjava pa štiri komolce: isto mero imej enajstero preprog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 9, 'In stakni pet preprog posebe in šest preprog posebe, šesto preprogo pa dvojno podviješ v pročelju šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 10, 'In naredi petdeset pentelj na robu skrajne preproge pri prvi zvezi in petdeset pentelj na robu preproge pri drugi zvezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 11, 'In napravi petdeset bronastih zapon in vtakni te zapone v pentlje in spóji šator, da bo celota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 12, 'Glede tega pa, kar je prebitka šatorovih preprog: polovica preproge, ki preostaja, naj visi čez zadnjo stran šatora;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 13, 'in tisti komolec ob eni strani in komolec ob drugi strani, ki sta odveč po dolgosti šatorovih preprog, naj visita čez obe strani prebivališča, da ga pokrivata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 14, 'In napravi odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož vrhu nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 15, 'In naredi deske za prebivališče iz akacijevega lesa, pokonci stoječe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 16, 'deset komolcev bodi dolga vsaka deska, eden in pol komolca pa široka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 17, 'dva čepa imej vsaka deska spodaj, drug proti drugemu vstavljena: tako napravi pri vseh deskah prebivališča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 18, 'In narediš deske za prebivališče, dvajset desek bodi za poldansko stran, proti jugu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 19, 'in štirideset podstav naredi pod dvajset desek: dve podstavi pod eno desko za dva čepa njena in dve podstavi pod drugo desko za dva čepa njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 20, 'Na drugi strani prebivališča, na severni strani, bodi tudi dvajset desek');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 21, 'in zanje štirideset podstav srebrnih: dve podstavi pod eno desko in dve podstavi pod drugo desko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 22, 'In na zadnji strani prebivališča, proti zahodu, naredi šest desek;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 23, 'in dve deski naredi za vogla prebivališču ob zadnji strani;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 24, 'in bodeta naj dvojni odspodaj in enako naj bodeta skupaj sklenjeni ob vrhu svojem v enem obodu: tako naj bode pri obeh dveh, na obeh voglih naj bodeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 25, 'Bode torej osem desek in njih srebrnih podstav šestnajst, dve podstavi pod vsako desko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 26, 'In narédi zapahe iz akacijevega lesa: pet za deske na eni strani prebivališča');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 27, 'in pet zapahov za deske na drugi strani prebivališča in pet za deske na zadnji strani prebivališča, proti zahodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 28, 'in srednji zapah sredi desek naj sega od konca do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 29, 'In deske prevleci z zlatom, in njih obode, namreč shrambice za zapahe, napravi iz zlata in zapahe okuj z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 30, 'In tako postavi prebivališče, po predpisu, ki ti je bil pokazan na gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 31, 'In narédi zagrinjalo iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice; umetno tkano bodi, s podobami kerubov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 32, 'in obesi ga na štiri stebre iz akacijevega lesa, prevlečene z zlatom; njih kavlji naj bodo iz zlata, in stoje naj na štirih podstavah iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 33, 'Obesi pa zagrinjalo pod zapone preprog in ponesi tja, noter za zagrinjalo, skrinjo pričevanja. In zagrinjalo vam bo ločilo Sveto od Najsvetejšega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 34, 'In deni pokrov sprave na skrinjo pričevanja v Najsvetejšem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 35, 'Mizo pa postavi zunaj zagrinjala in svečnik mizi nasproti, na stran prebivališča proti jugu; mizo namreč postaviš na severno stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 36, 'In za vhod v šator naredi zaveso iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice, z umetno pisanim vezenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 26, 37, 'In za zaveso napravi pet stebrov iz akacijevega lesa in jih okuj z zlatom; njih kavlji naj bodo iz zlata, in ulij zanje pet podstav iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 1, 'In naredi oltar iz akacijevega lesa, pet komolcev dolg in pet komolcev širok – četverokoten bodi oltar – in tri komolce visok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 2, 'In naredi mu štiri rogove na štirih voglih njegovih, sceloma naj bodo delani ž njim tisti rogovi, in okuj ga z bronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 3, 'In naredi zanj pepelnjake in lopate in čaše in vilice in ponve za žerjavico: vse priprave njegove napravi iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 4, 'In naredi zanj bronasto omrežje, mrežastega dela, in na omrežju napravi štiri bronaste obode na štirih voglih njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 5, 'in postavi ga k obrobnemu podstavku oltarja, odspodaj, da seže omrežje do polovice oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 6, 'In naredi droga za oltar, droga iz akacijevega lesa, in ju okuj z bronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 7, 'In droga njegova naj se vtakneta v obode, da bosta droga na obeh straneh oltarja, ko ga bodo prenašali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 8, 'Votlega, iz desek ga naredi; kakor ti je bilo pokazano na gori, tako naj ga napravijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 9, 'Naredi tudi prebivališču dvorišče: na poldanski strani, proti jugu, naj bodo zastori iz sukane tenčice, sto komolcev dolgi na eni strani;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 10, 'in njih stebrov bodi dvajset, tudi njih bronastih podstavkov dvajset; kavlji za stebre in njih vezila naj bodo iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 11, 'In ravno tako na severni strani, po dolgosti, bodo zastori sto komolcev dolgi, in zanje dvajset stebrov in dvajset podstavkov iz brona, kavlji za stebre in njih vezila iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 12, 'Po širjavi dvorišča, na zahodni strani, pa bodi petdeset komolcev zastorov, njih stebrov deset in njih podstavkov deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 13, 'In širjava dvorišču na vzhodni strani bodi petdeset komolcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 14, 'petnajst komolcev zastorov ob eni strani vhoda, in njih stebrov troje in njih podstavkov troje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 15, 'tudi ob drugi strani vhoda petnajst komolcev zastorov, trije stebri in trije podstavki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 16, 'In za vrata na dvorišče bodi zavesa dvajsetih komolcev iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice, umetno pisano vezenje, in njeni stebri štirje in podstavki štirje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 17, 'Za vse stebre krog dvorišča naj se napravijo srebrna vezila, tudi njih kavlji bodo iz srebra, njih podstavki pa iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 18, 'Dolgost dvorišča bode sto komolcev, širjava pa petdeset z obeh strani, pet komolcev pa visokost zastorov iz sukane tenčice, in njih podstavki iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 19, 'Vse priprave prebivališča za vso službo pri njem in vsi kolčki njegovi in vsi kolčki ob dvorišču naj bodo iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 20, 'Ti pa zapovej sinovom Izraelovim, da ti prineso čistega oljkovega olja, z betom iztolčenega, za svetilo, da se prižigajo svetilnice neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 27, 21, 'V shodnem šatoru, zunaj zagrinjala, ki je razpeto pred pričevanjem, naj jih pripravljajo Aron in sinovi njegovi, da goré od večera do jutra pred Gospodom. Večna postava bodi to za njih rodove, ki naj jo izpolnjujejo sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 1, 'Ti pa vzemi k sebi Arona, brata svojega, in sinove njegove ž njim, izmed Izraelovih otrok, da mi služi kot duhovnik Aron, Nadab in Abihu, Eleazar in Itamar, sinovi Aronovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 2, 'In naredi Aronu, bratu svojemu, sveta oblačila, za čast in za kras.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 3, 'In ti govori z vsemi, ki so modrega srca, katere sem napolnil z duhom modrosti, naj napravijo Aronu oblačila, da bo posvečen v službo duhovniško meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 4, 'In ta so oblačila, ki jih izgotovijo: naprsnik, naramnik, vrhnja suknja in spodnja iz stanične tkanine, pokrivalo in pas; in narede sveta oblačila Aronu, bratu tvojemu, in sinovom njegovim, da služi meni za duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 5, 'In naj za to porabijo zlato, višnjevo in zagorelordeče blago in karmezin in tenčico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 6, 'Narede pa naj naramnik iz zlata, iz višnjevega in zagorelordečega blaga, iz karmezina in sukane tenčice, umetno tkano delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 7, 'Naj ima dva obramna dela, ki se zgoraj na koncih sklepata, da sta v eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 8, 'In umetno tkana preveza na njem, s katero se bo privezoval, enega dela bodi ž njim in iz istega blaga: iz zlata, višnjeve in zagorelordeče preje, karmezina in sukane tenčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 9, 'In vzemi dva onihova kamena in vreži vanju imena sinov Izraelovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 10, 'šest njih imen na en kamen in šest drugih na drugi kamen, po redu njih rojstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 11, 'Kamenorisarsko delo bodi, kakor se vrezuje v pečate; na oba kamena daj vrezati imena sinov Izraelovih; in opleti ju s pletežem iz zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 12, 'In priklopi oba kamena na obramna dela naramnikova, da bodeta kamena spomina na sinove Izraelove; in Aron naj nosi njih imena pred Gospodom na obeh ramah svojih v spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 13, 'In narédi okove iz zlata');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 14, 'in dve verižici iz čistega zlata, kakor vrvi ju napravi, s pletenjem, in tisti pleteni verižici pritakni k okovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 15, 'In napravi naprsnik sodbe, umetno tkano delo bodi kakor naramnik, iz zlata, iz višnjevega in zagorelordečega blaga, iz karmezina in sukane tenčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 16, 'Štirivoglat naj bode in v dve gubi, pedenj dolg in pedenj širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 17, 'In obloži ga z okovanimi kameni, v štirih vrstah: sardij, topaz in smaragd bodi prva vrsta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 18, 'druga vrsta pa: rubin, safir in diamant;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 19, 'tretja vrsta: hiacint, ahat in ametist;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 20, 'četrta vrsta: krizolit, onih in jaspis; obdani naj bodo z zlatom v svojih vrstah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 21, 'Primerno imenom sinov Izraelovih naj bode dvanajst kamenov, in na vsakem kamenu bodi vrezano po eno ime izmed dvanajsterih rodov, s pečatarjevim delom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 22, 'In narédi za naprsnik vrvčasti verižici, spleteni iz čistega zlata;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 23, 'in naredi dva zlata obročka k naprsniku in ju pritakni na oba konca njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 24, 'in pritrdi tisti dve spleteni zlati verižici v dva obročka na obeh koncih naprsnika;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 25, 'in druga dva konca obeh spletenih verižic zapni v obadva okova in ju pritakni na obramna dela naramnikova, spredaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 26, 'In naredi dva druga obročka iz zlata in ju pritakni na druga dva konca naprsnikova, na rob, ki je proti naramniku, odznotraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 27, 'Naredi še dva obročka iz zlata in ju prikleni na oba obramna dela naramnikova spodaj ob sprednji strani, ravno tam, kjer se sklepa, vrhu umetno tkane preveze naramnikove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 28, 'In privežejo naj naprsnik, njegove obročke k naramnikovim obročkom z višnjevo vrvico, da se gladko prilega nad umetno tkano prevezo naramnikovo ter da se naprsnik ne premakne raz naramnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 29, 'In Aron naj nosi imena sinov Izraelovih na naprsniku sodbe na srcu svojem, kadar pojde v svetišče, v spomin pred Gospodom vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 30, 'In v naprsnik sodbe deni Urim in Tumim, da bodeta na srcu Aronovem, kadar pojde pred obličje Gospodovo; in Aron naj nosi sodbo sinom Izraelovim, na srcu svojem pred Gospodom vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 31, 'In naredi vrhnjo suknjo pod naramnik iz višnjevega blaga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 32, 'In zgoraj sredi nje bodi odprtina, in tkano tvestje naj ima okoli odprtine, da bode odprtina kakor pri oklepu, da se ne razdere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 33, 'Spodaj okoli roba pa naredi margaranovih jabolk iz višnjevega, zagorelordečega blaga in iz karmezina, kroginkrog po njenem robu, in mednje zlate zvončke vseokoli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 34, 'da je zlat zvonček in margaranovo jabolko, in zopet zlat zvonček in margaranovo jabolko na robu suknje vseokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 35, 'In Aron jo imej na sebi za službo, da se sliši zvončkanje njegovo, kadar gre v svetišče pred obličje Gospodovo in kadar stopa ven, da ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 36, 'In napravi ploščo iz čistega zlata in vreži vanjo, kakor se vrezuje v pečate: SVETOST Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 37, 'in priveži jo z višnjevo prevezo, da bode na pokrivalu; spredaj bodi na pokrivalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 38, 'In bode na čelu Aronovem, in Aron bo nosil svetih reči krivico, ki je na vseh svetih darilih, katera posvečujejo Izraelovi sinovi; in bode na čelu njegovem vedno, da jih stori blagougodne obličju Gospodovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 39, 'In narédi spodnjo suknjo iz tenčice, staničastega tkanja; in naredi pokrivalo iz tenčice, in pas naredi z vezilnim delom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 40, 'In sinovom Aronovim naredi spodnje suknje in pase in visoke čepice, njim v čast in kras.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 41, 'In obleci vanje Arona, brata svojega, in sinove njegove ž njim vred; in pomazili jih ter jim napolni roke in jih posveti, da mi opravljajo duhovsko službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 42, 'Napravi jim tudi platnene hlače, da zakrijejo meso sramote svoje: od ledij do stegen naj segajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 28, 43, 'In Aron in sinovi njegovi naj jih imajo na sebi, kadar gredo v shodni šator ali kadar se bližajo oltarju, opravljat službo v svetišču, da si ne naložijo krivde in ne umro: večna to bodi postava njemu in semenu njegovemu za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 1, 'To pa je, kar jim storiš, da jih posvetiš, da bi mi opravljali duhovsko službo. Vzemi mladega junca in dva ovna brez madeža');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 2, 'in nekvašenega kruha in opresnih kolačev, z oljem zamešenih, in opresnih mlincev, z oljem pomazanih; iz čiste pšenične moke jih pripravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 3, 'V en koš jih deni in jih prinesi v košu, in junca in dva ovna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 4, 'Arona pa in njegove sinove privedeš k vhodu v shodni šator ter jih umiješ z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 5, 'Nato vzemi oblačila in obleci Arona v spodnjo suknjo in vrhnjo naramnikovo suknjo in naramnik in naprsnik in ga prepaši z umetno tkano naramnikovo prevezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 6, 'In mu deni pokrivalo na glavo in priveži zlati venec na pokrivalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 7, 'In vzemi mazilnega olja in ga izlij na glavo njegovo ter ga pomazili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 8, 'Tudi sinove njegove pripelji in jih obleci v spodnje suknje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 9, 'In opaši jih s pasovi, Arona in sinove njegove, ter jim priveži visoke čepice; in bode jim duhovništvo po večni postavi. In napolniš roke Aronu in sinom njegovim v posvečenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 10, 'In pripelji junca pred shodni šator, in Aron in sinovi njegovi naj polože roke svoje juncu na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 11, 'In zakolji junca pred Gospodom ob vhodu v shodni šator');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 12, 'ter vzemi junčeve krvi in jo deni s prstom na rogove oltarja, vso drugo kri pa izlij spodaj ob oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 13, 'In vzemi vso tolstino, ki pokriva drobje, in pečico na jetrih in obe ledici s tolstjo, ki je na njiju, in zažgi to na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 14, 'Ali junčevo meso in kožo in iztrebke njegove sežgi z ognjem zunaj šatorišča: daritev za greh je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 15, 'Nato vzameš enega ovna, in Aron in sinovi njegovi naj mu polože roke svoje na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 16, 'In zakolji ovna ter vzemi krvi njegove in škropi ž njo okrog po oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 17, 'Ovna pa razreži na kose, in operi drob njegov in stegna njegova ter jih položi na kose njegove in na glavo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 18, 'In zažgi vsega ovna na oltarju: žgalna žrtev je Gospodu, prijeten duh, daritev po ognju Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 19, 'Potem vzemi drugega ovna, in Aron in sinovi njegovi naj mu polože roke svoje na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 20, 'In zakolji ovna ter vzemi krvi njegove in jo deni na mečico desnega ušesa Aronovega in na mečico desnega ušesa sinov njegovih in na palec njih desnice in na palec desne noge; ostalo kri pa razškropi po oltarju okoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 21, 'In vzemi krvi, ki je na oltarju, in mazilnega olja ter pokropi Arona in oblačila njegova in sinove njegove in oblačila sinov njegovih ž njim vred; in posvečen bode in oblačila njegova in sinovi njegovi in sinov njegovih oblačila ž njim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 22, 'Vzemi tudi tolstine ovnove in tolsti rep in tolst, ki pokriva drob, in pečico na jetrih in obe ledici in tolst, ki je na njiju, in desno stegno (kajti je oven posvečenja)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 23, 'in hleb kruha in kolač z oljem zamešanega kruha in mlinec iz koša opresnikov, ki je pred Gospodom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 24, 'in položi vse to na roke Aronu in sinom njegovim, in majaj to kot daritev majanja pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 25, 'Potem vzemi to iz njih rok ter zažgi na oltarju vrhu žgalne daritve v prijeten duh pred Gospodom; ognjena daritev je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 26, 'In vzemi prsi od ovna posvetitve, ki je za Arona, ter jih daruj z majanjem pred Gospodom; in bodo tebi v delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 27, 'In posvetiš prsi daritve majanja, ki so se majale, in stegno povzdignjenja, ki se je povzdignilo od ovna posvetitve, ki je za Arona in za sinove njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 28, 'in dobi naj to Aron in sinovi njegovi kot vekomaj sebi določeno od sinov Izraelovih, kajti dar povzdignjenja je; in bode to dar povzdignjenja od sinov Izraelovih, od njih mirovnih daritev, njih dar povzdignjenja Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 29, 'Sveta oblačila Aronova pa bodo za sinove njegove za njim, da bodo v njih maziljeni ter da se jim v njih napolnijo roke v posvečenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 30, 'Sedem dni jih bo oblačil tisti iz sinov njegovih, ki bode duhovnik na mestu njegovem, ko pojde v šator pričevanja služit v svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 31, 'Ovna posvetitve pa vzemi in skuhaj meso njegovo na svetem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 32, 'In Aron in sinovi njegovi naj jedo meso ovnovo in kruh, ki je v košu, ob vhodu v shodni šator:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 33, 'jedo naj tiste reči, po katerih se je izvršila poravnava, da bi se jim napolnile roke, da bodo posvečeni; tujec pa jih ne sme jesti, ker so svete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 34, 'Ako pa ostane do jutra kaj mesa posvetitve in kruha, naj se sežge, kar je ostalo; ne sme se jesti, ker je sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 35, 'Stóri torej Aronu in sinom njegovim natanko po vsem, kar sem ti zapovedal. Sedem dni jim napolnjuj roke v posvetitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 36, 'In vsak dan daruj v poravnavo junca kot daritev za greh, in očistiš oltar greha, ko storiš poravnavo zanj; in ga pomazili, da ga posvetiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 37, 'Sedem dni opravljaj poravnavo za oltar in ga posvečuj; in oltar bodi presvet: karkoli se dotakne oltarja, bode sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 38, 'To pa je, kar boš pripravljal na oltar: vsak dan dve jagnjeti, po eno leto stari, neprenehoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 39, 'Eno jagnje daruj zjutraj, drugo jagnje proti večeru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 40, 'in k prvemu jagnjetu desetinko bele moke, zmešane s četrtino hina iztolčenega olja, in četrtino hina vina kot pitno darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 41, 'In drugo jagnje pripravi proti večeru; zastran jedilnega in pitnega darila ravnaj po jutranjem darovanju: v prijeten duh bodi, ognjena daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 42, 'To bodi neprestana žgalna daritev po rodovih vaših pri vhodu shodnega šatora pred Gospodom, kjer se bom shajal z vami, da govorim s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 43, 'In tam se bom shajal s sinovi Izraelovimi, in šator bo posvečen po slavi moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 44, 'In posvetim shodni šator in oltar, tudi Arona in sinove njegove posvetim, da mi opravljajo duhovsko službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 45, 'In prebival bom sredi sinov Izraelovih in jim bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 29, 46, 'In spoznajo, da sem jaz Gospod, njih Bog, ki sem jih odpeljal iz dežele Egiptovske, da bi prebival sredi njih. Jaz sem Gospod, njih Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 1, 'Naredi tudi oltar, na katerem se bo zažigalo kadilo; iz akacijevega lesa ga napravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 2, 'komolec bodi dolg, komolec širok, štirivoglat naj bo, in dva komolca visok; iz ene celote ž njim naj bodo rogovi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 3, 'In prevleci ga s čistim zlatom, njegov vrh in njegove stene kroginkrog in njegove rogove; in napravi mu zlat venec naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 4, 'In naredi mu dva zlata oboda pod vencem njegovim, ob voglih njegovih na obeh straneh, da se vanju vtakneta droga, ki se bo nosil ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 5, 'Droga pa tudi naredi iz akacijevega lesa in ju prevleci z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 6, 'In oltar postavi nasproti zagrinjalu, ki visi pred skrinjo pričevanja, in nasproti pokrovu sprave, ki je vrhu pričevanja, kjer se bom shajal s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 7, 'In Aron naj zažiga na njem blagodišeče kadilo; vsako jutro, ko pripravlja svetilnice, naj zakadi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 8, 'Tudi ko prižiga svetilnice proti večeru, naj zakadi: neprestano bodi kadilo pred Gospodom po rodovih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 9, 'Ne smete na njem darovati tujega kadila, ne žgalščine, ne jedilne daritve, tudi pitne daritve ne izlijte nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 10, 'A enkrat v letu naj opravi Aron poravnavo na rogovih njegovih s krvjo daritve za greh, ki je v spravo; enkrat v letu naj stori zanj poravnavo po prihodnjih rodovih vaših: presvet je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 11, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 12, 'Ko poizveš število sinov Izraelovih, kolikor jih gre v štetje, tedaj naj plača vsakdo odkupnino za dušo svojo Gospodu, kadar jih boš štel, da ne pride nadnje šiba, ko bodo šteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 13, 'To naj dado: vsakdo, ki preide k preštetim, pol sekla, po seklu svetišča (dvajset ger ima sekel), pol sekla kot dar povzdignjenja Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 14, 'Sleherni, ki preide k preštetim, dvajset let star in več, naj da Gospodu dar povzdignjenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 15, 'Bogatin ne da več in ubožec ne manj nego pol sekla, ko poklonite dar povzdignjenja Gospodu, da se stori poravnava za duše vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 16, 'In vzemi spravni denar od sinov Izraelovih ter ga obrni v službo v shodnem šatoru, da bodi to v spomin sinom Izraelovim pred Gospodom, v poravnavo za duše vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 17, 'Še je govoril Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 18, 'Naredi tudi bronast umivalnik z bronastim stojalom za umivanje in ga postavi med shodni šator in oltar in vlij vanj vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 19, 'In Aron in sinovi njegovi naj si iz njega umivajo roke in noge:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 20, 'kadar pojdejo v shodni šator, naj se umijejo z vodo, da ne umrjo, ali pa ko se bližajo oltarju služit, da zažgo ognjeno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 21, 'Umivajo pa naj si roke in noge, da ne umrjo. To jim bodi večna postava, njemu in semenu njegovemu od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 22, 'Dalje je govoril Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 23, 'Ti pa si vzemi najboljših dišav: petsto seklov mire, ki teče sama od sebe, in polovico sladke skorje, namreč dvesto in petdeset, in dvesto in petdeset dišečega trstja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 24, 'in kasije petsto, po seklu svetišča, in oljkovega olja mero hin;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 25, 'in naredi iz tega olje za sveto maziljenje, mešano dišavje po mazilarjevi umetnosti: sveto mazilno olje bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 26, 'In pomazili ž njim shodni šator in skrinjo pričevanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 27, 'mizo z vsemi posodami njenimi, svečnik s pripravo njegovo in kadilni oltar');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 28, 'in oltar za žgalščine z vsemi pripravami njegovimi in umivalnik in stojalo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 29, 'In tako jih posveti, in bodo presvete: karkoli se jih dotakne, bode sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 30, 'In pomazili Arona in sinove njegove ter jih posveti, da mi služijo za duhovnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 31, 'Sinom Izraelovim pa govori in reci: To mi bodi sveto mazilno olje po prihodnjih rodovih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 32, 'Na meso človeško se ne sme izliti, in po njega sestavi ne narejajte podobnega: sveto je, sveto vam bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 33, 'Kdor ga ponaredi ali kdor od njega da tujcu, bodi iztrebljen iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 34, 'In Gospod je velel Mojzesu: Vzemi si dišav: dišeče smole, kadilne školjke, galbana, sladkih vonjav in prečiščenega kadila, vsakega enako težo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 35, 'in naredi iz tega kadilo, dišečino, po mazilarjevi umetnosti, osoljeno, čisto, sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 36, 'In stolci nekoliko v prah in ga deni pred pričevanje v shodni šator, kjer se bom shajal s teboj; presveto vam bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 37, 'In kadila, kakršnega napraviš, sebi po isti sestavi ne narejajte; za sveto Gospodu naj ti velja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 30, 38, 'Kdor ga ponaredi, da bi ga duhal, bodi iztrebljen iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 2, 'Poglej, poklical sem po imenu Bezalela, sina Urija, sinu Hurovega, iz rodovine Judove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 3, 'in sem ga napolnil z duhom Božjim, ki se kaže v modrosti in razumnosti in znanosti in v vsakršni spretnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 4, 'da izumlja umetnine in izdeluje iz zlata in srebra in brona');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 5, 'in zna rezati kamene, da se denejo v okove, in izrezavati les in delati vsakovrstne izdelke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 6, 'In glej, dal sem mu tudi Oholiaba, sina Ahisamakovega, iz rodovine Danove; in modrost sem del v srce vsem, ki so modrega srca, da delajo vse, kar sem ti zapovedal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 7, 'šator shoda in skrinjo pričevanja in pokrov, ki je na njej, in vso šatorovo opravo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 8, 'in mizo in vso posodo njeno in čisti svečnik in vse priprave njegove in kadilni oltar');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 9, 'in oltar za žgalščine z vsemi pripravami in umivalnik in stojalo njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 10, 'službena oblačila in sveta oblačila za Arona duhovnika in oblačila sinov njegovih za duhovsko službo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 11, 'in mazilno olje in blagodišeče kadilo za svetišče: po vsem, kar sem ti zapovedal, naj delajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 12, 'In Gospod je dejal Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 13, 'Ti pa govori sinom Izraelovim in reci: Sobote moje res spoštujte, ker znamenje so med menoj in med vami po prihodnjih rodovih vaših, da veste, da sem jaz Gospod, ki vas posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 14, 'Imejte torej v čislih dan počitka, ker je svet za vas; kdorkoli ga oskruni, mora umreti; kajti kdorkoli bi delal kako delo v njem, ta duša bo iztrebljena izmed ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 15, 'Šest dni naj se opravlja delo, a dan sedmi je sobota slovesnega počitka, sveta Gospodu; kdorkoli opravlja kak posel sobotni dan, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 16, 'Zato naj ohranijo sinovi Izraelovi soboto, da praznujejo počitek po prihodnjih rodovih svojih, kot večno zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 17, 'Znamenje je to med menoj in med sinovi Izraelovimi na veke; zakaj v šestih dneh je naredil Gospod nebo in zemljo, dan sedmi pa je počival in se poživil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 31, 18, 'In dal je Mojzesu, ko je nehal govoriti ž njim na gori Sinaju, dve plošči pričevanja, kameneni plošči, popisani s prstom Božjim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 1, 'In ko je videlo ljudstvo, da se Mojzes obotavlja priti z gore, se zbere množica k Aronu in ga ogovori: Vstani, naredi nam bogove, ki naj gredo pred nami; zakaj tistemu možu Mojzesu, ki nas je odpeljal iz dežele Egiptovske, ne vemo, kaj se mu je prigodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 2, 'In Aron jim veli: Izderite zlate obodce, ki so v ušesih žen vaših, sinov in hčer vaših, in jih prinesite k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 3, 'In odtrga vse ljudstvo obodce zlate, ki so jih imeli v ušesih, in jih prinesejo k Aronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 4, 'On pa jih vzame iz njih rok in jih upodobi z dolbilom in napravi iz njih zlito tele. In reko: To je bog tvoj, o Izrael, ki te je pripeljal gori iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 5, 'In ko Aron to vidi, sezida oltar pred njim in razglasi, rekoč: Jutri bodi praznik Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 6, 'In zjutraj vstanejo zgodaj, in darovali so žgalne in prinesli mirovne daritve; in ljudstvo je sedlo jest in pit in vstalo igrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 7, 'Tedaj veli Gospod Mojzesu: Pojdi, stopi doli! Zakaj tvoje ljudstvo, ki si ga pripeljal iz dežele Egiptovske, se je skazilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 8, 'Hitro so zašli s pota, ki sem ga jim zaukazal: naredili so si ulito tele in se poklanjali pred njim in mu darovali, govoreč: To je bog tvoj, o Izrael, ki te je pripeljal iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 9, 'In reče Gospod Mojzesu: Videl sem to ljudstvo, in glej, trdovratno ljudstvo je;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 10, 'sedaj torej me pusti, da se vname srd moj zoper nje in jih pokončam; tebe pa storim v velik narod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 11, 'Mojzes pa milo prosi Gospoda, Boga svojega, govoreč: Zakaj, o Gospod, se vnema srd tvoj zoper ljudstvo tvoje, ki si ga peljal iz dežele Egiptovske z veliko močjo in z roko mogočno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 12, 'Zakaj naj bi govorili Egipčani: Za nesrečo jih je izpeljal, da jih pomori v gorah in zatre s površja zemlje? Obrni se od togote srda svojega in žal ti bodi hudega zoper ljudstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 13, 'Spomni se Abrahama, Izaka in Izraela, hlapcev svojih, ki si jim prisegel pri sebi in jim rekel: Pomnožim seme vaše kakor zvezde na nebu in vso to deželo, ki sem o njej govoril, dam zarodu vašemu, da jim je v dedno last vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 14, 'In žal je bilo Gospodu hudega, o katerem je bil govoril, da stori svojemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 15, 'In Mojzes se obrne in stopa doli z gore, držeč dve plošči pričevanja v roki svoji, plošči popisani na obeh straneh: na tej in na oni strani je bilo pisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 16, 'In plošči sta bili delo Božje, in pisava je bila pisava Božja, vdolbena v plošči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 17, 'In Jozue, ko je začul krik ljudstva, ki je ukalo, reče Mojzesu: Bojno vpitje je v taboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 18, 'On pa reče: To ni glas takih, ki ukajo zaradi zmage, ne glas takih, ki vpijejo v poboju; glas pevajočih slišim jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 19, 'In zgodi se, ko se približa taboru in zagleda tele in ples, da se razsrdi in vrže plošči iz roke in ju razbije pod goro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 20, 'In vzame tele, ki so ga bili naredili, in ga sežge v ognju in ga zdrobi v prah in iztrese v vodo in jo da piti sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 21, 'In Mojzes reče Aronu: Kaj ti je storilo to ljudstvo, da si nadnje pripravil velik greh?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 22, 'Aron pa reče: Ne razvnema naj se jeza gospoda mojega! Saj poznaš ljudstvo, da je hudobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 23, 'Rekli so mi namreč: Naredi nam bogove, ki naj gredo pred nami, zakaj tistemu možu Mojzesu, ki nas je pripeljal iz dežele Egiptovske, ne vemo, kaj se mu je prigodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 24, 'Jaz pa sem rekel: Kdo ima zlata? odtrgali so si ga in mi dali, in vrgel sem ga v ogenj, in izšlo je to tele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 25, 'In Mojzes je videl ljudstvo, da je razuzdano, kajti Aron ga je spravil v razuzdanost, v škodoželjen zasmeh pri sovražnikih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 26, 'Tedaj se postavi Mojzes med vrati v tabor in kliče: Sem k meni, kdor je Gospodu na strani! In zbero se k njemu vsi sinovi Levijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 27, 'In jim veli: Tako pravi Gospod, Bog Izraelov: Pripašite vsak meč svoj in pojdite semtertja, od vrat do vrat v taboru, in ubijte vsak brata svojega in vsak prijatelja svojega in vsak soseda svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 28, 'In storili so sinovi Levijevi po besedi Mojzesovi; in padlo jih je tisti dan izmed ljudstva blizu tri tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 29, 'In Mojzes reče: Posvetite se danes Gospodu, da, vsak proti sinu svojemu in proti bratu svojemu, da pripravite danes blagoslov nad sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 30, 'In zgodi se drugega dne, da reče Mojzes ljudstvu: Pregrešili ste se z velikim grehom; in sedaj hočem iti gori h Gospodu, morda dosežem pomirjenje za greh vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 31, 'Vrne se torej Mojzes h Gospodu in reče: Ah, pregrešilo se je to ljudstvo z velikim grehom, ko si je naredilo boga iz zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 32, 'In sedaj, o da bi odpustil njih greh! če pa ne, izbriši me, prosim, iz knjige svoje, ki si jo pisal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 33, 'In Gospod reče Mojzesu: Kdorkoli je grešil zoper mene, njega izbrišem iz knjige svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 34, 'In sedaj pojdi, vodi ljudstvo tja, kamor sem ti povedal. Glej, angel moj pojde pred teboj; ali v dan obiskovanja svojega bom na njih kaznoval njih greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 32, 35, 'In Gospod je udaril ljudstvo, zato ker so naredili tele, ki ga je napravil Aron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 1, 'In Gospod je govoril Mojzesu: Vstani, potuj gori odtod, ti in ljudstvo, ki si ga pripeljal iz dežele Egiptovske, v deželo, o kateri sem prisegel Abrahamu, Izaku in Jakobu in govoril: Semenu tvojemu jo hočem dati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 2, 'In pošljem angela pred teboj in izženem Kanaance, Amorejce in Hetejce in Ferizejce, Hevejce in Jebusejce;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 3, 'potuj v deželo, v kateri teče med in mleko; zakaj jaz ne pojdem med vami, ker si trdovratno ljudstvo, da te ne pokončam kje na potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 4, 'In ko je ljudstvo slišalo to hudo poročilo, so žalovali, in nihče ni oblekel lepotine svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 5, 'Zakaj Gospod je bil rekel Mojzesu: Reci sinovom Izraelovim: Ljudstvo trdovratno ste vi; ako bi šel en trenotek med vami, bi te pokončal. In sedaj odloži lepotičje svoje, da bom vedel, kaj naj ti storim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 6, 'In sneli so sinovi Izraelovi lepotičje s sebe pri gori Horebski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 7, 'In Mojzes vzame šator in si ga razpne zunaj tabora, daleč od taborišča, in ga je imenoval: Šator shoda. In bilo je, da je vsakdo, ki je iskal Gospoda, hodil k šatoru shoda, ki je bil zunaj tabora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 8, 'In kadarkoli je šel Mojzes ven k Šatoru, je vstalo vse ljudstvo, in vsakteri je stal ob vhodu šatora svojega in gledal za Mojzesom, dokler ni stopil v Šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 9, 'Ko je pa Mojzes stopil v Šator, je prišel doli oblakov steber in stal ob vhodu Šatora, in Gospod je govoril z Mojzesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 10, 'In videlo je vse ljudstvo oblakov steber ob vhodu v Šator; in vse ljudstvo je vstajalo in se poklanjalo, vsak ob vhodu šatora svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 11, 'In Gospod je govoril z Mojzesom iz obličja v obličje, kakor govori človek s prijateljem svojim. Potem se je vrnil v tabor; njegov strežnik pa, Jozue, sin Nunov, mladenič, ni šel iz Šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 12, 'In Mojzes reče Gospodu: Glej, ti mi velevaš: Vodi to ljudstvo gori, a nisi mi ga dal spoznati, koga pošlješ z menoj, čeprav si rekel: Poznam te po imenu, in našel si milost v mojih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 13, 'Zdaj torej, če sem našel milost v tvojih očeh, mi pokaži pot svojo, da te spoznam in vem, čemu najdem milost v tvojih očeh; in glej, ta narod je tvoje ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 14, 'On pa reče: Obličje moje te bo spremljalo, in dam ti pokoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 15, 'In Mojzes mu reče: Ako nas ne bo spremljalo obličje tvoje, ne pelji nas iz tega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 16, 'In po čem naj bo vendar očitno, da sem našel milost v tvojih očeh, jaz in ljudstvo tvoje? Ne li po tem, da hodiš z nami in smo odlikovani, jaz in ljudstvo tvoje, izmed vseh ljudstev, kar jih je na površju zemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 17, 'In Gospod reče Mojzesu: Tudi to reč, ki si jo govoril, hočem storiti, kajti našel si milost v mojih očeh in poznam te po imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 18, 'On pa reče: Pokaži mi, prosim, slavo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 19, 'In odgovori: Storim, da pojde mimo tebe vsa dobrota moja, in klical bom ime Gospodovo pred teboj; in milostiv bodem, komur hočem biti milostiv, in usmilim se, kogar se hočem usmiliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 20, 'In reče: Ne moreš videti obličja mojega, zakaj človek me ne more videti in ostati živ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 21, 'In Gospod reče: Glej, prostor je pri meni, tu se postavi na skalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 22, 'In zgodi se, ko pojde mimo slava moja, da te postavim v skalno razpoko in te pokrijem z roko svojo, dokler ne preidem mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 33, 23, 'Potem odmaknem roko svojo, in videl me boš odzadaj, a obličja mojega ne bode videti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 1, 'In Gospod veli Mojzesu: Izsekaj si dve kameniti plošči, kakršni sta bili prvi, in napišem nanju besede, ki so bile na prvih ploščah, ki si ju razbil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 2, 'In bodi pripravljen za jutro, in stopi zjutraj na goro Sinajsko in se postavi pred menoj na vrhu gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 3, 'Nihče naj s teboj ne gre gori, nihče naj se tudi ne prikaže po vsej gori, tudi drobnica in goved naj se ne paseta tej gori nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 4, 'In izsekal je dve kameniti plošči, kakršni sta bili prvi; in vstal je Mojzes zjutraj zgodaj in šel na goro Sinaj, kakor mu je bil zapovedal Gospod, in v roko svojo je vzel dve kameniti plošči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 5, 'In Gospod je prišel doli v oblaku in je stal ondi poleg njega in klical ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 6, 'In Gospod je šel mimo njega in klical: Gospod, Gospod, Bog mogočni, poln usmiljenja in milostiv, počasen za jezo in obilen v milosti in resnici,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 7, 'ki hrani milost tisočim, ki odpušča krivico in prestopek in greh, ki pa krivega nikakor ne šteje za nedolžnega, ki obiskuje očetov krivico nad sinovi in vnuki, nad tretjim in četrtim pokolenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 8, 'In Mojzes se hitro pripogne k zemlji in moli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 9, 'In reče: Če sem našel milost v tvojih očeh, o Gospod, naj gre, prosim, Gospod sam med nami; zakaj to ljudstvo je trdovratno; in odpusti krivico našo in greh naš in vzemi nas za svojo last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 10, 'In odgovori: Glej, jaz sklepam zavezo: vpričo vsega ljudstva tvojega hočem delati čudeže, kakršnih ni bilo storjenih na vsej zemlji in med vsemi narodi; in vse ljudstvo, med katerim bivaš, bo videlo delo Gospodovo; kajti strašno bode to, kar bom delal pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 11, 'Hrani, kar ti danes zapovedujem. Glej, izganjam pred teboj Amorejce in Kanaance in Hetejce in Ferizejce in Hevejce in Jebusejce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 12, 'Varuj se, da ne skleneš zaveze s prebivalci dežele, v katero prideš, da ti ne postanejo zanka v sredi tvoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 13, 'temuč njih oltarje poderite in njih poslikane stebre zdrobite in njih Ašere posekajte, –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 14, 'kajti drugemu bogu se ne smeš poklanjati, zakaj Gospod, čigar ime je Gorečnik, je goreč Bog; –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 15, 'da ne skleneš zaveze s prebivalci dežele, in ko bi nečistovali za svojimi bogovi in darovali bogovom svojim, bi te kdo povabil in ti bi jedel od njih daritve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 16, 'in jemal bi njih hčere za svoje sinove, in njih hčere bi nečistovale za svojimi bogovi in zapeljale sinove tvoje, da nečistujejo za njih bogovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 17, 'Ulitih bogov si ne delaj! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 18, 'Praznik opresnikov obhajaj! Sedem dni boš jedel opresnike, kakor sem ti zapovedal, določeni čas v mesecu Abibu: kajti meseca Abiba si odšel iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 19, 'Vse prvorojeno bodi moje, in vsa živina tvoja moškega spola, prvenci govedi in drobnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 20, 'Prvorojeno oslice pa odkupi z jagnjetom, a če ga ne odkupiš, zlomi mu šijnjak. Vsakega prvenca izmed sinov svojih odkupi. In nihče naj se prazen ne prikaže pred obličjem mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 21, 'Šest dni delaj, sedmi dan pa počivaj; ob času oranja in ob času žetve počivaj. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 22, 'In praznik tednov obhajaj, prvin žetve pšenične, tudi praznik spravljanja ob koncu leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 23, 'Trikrat v letu se naj prikažejo vsi moški tvoji pred obličjem Gospoda Jehove, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 24, 'Kajti izženem narode pred teboj in razširim meje tvoje; nihče tudi ne poželi dežele tvoje, ako se pojdeš prikazat pred obličjem Gospoda, Boga svojega, trikrat v letu. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 25, 'Ne smeš darovati krvi klalne daritve moje s skvašenim kruhom vred; tudi naj ne ostane daritev praznika pashe čez noč do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 26, 'Zemljišča svojega prve prvine prinesi v hišo Gospoda, Boga svojega. Kozliča ne kuhaj v mleku matere njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 27, 'In Gospod reče Mojzesu: Napiši si te besede, kajti po glasu teh besed sem sklenil s teboj zavezo in z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 28, 'In bil je tam pri Gospodu štirideset dni in štirideset noči, in kruha ni jedel in vode ni pil. In Gospod je napisal na plošči besede zaveze, desetero besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 29, 'In ko je potem šel Mojzes doli z gore Sinajske in je imel tisti dve plošči pričevanja v roki, ko je stopal z gore – ni vedel Mojzes, da se obraz njegov žari, ker je bil govoril ž Njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 30, 'Aron pa in vsi sinovi Izraelovi gledajo Mojzesa, in glej, koža obličja njegovega se žari; in bali so se k njemu približati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 31, 'A Mojzes jih pokliče, in vrnejo se k njemu Aron in vsi knezi občine; in Mojzes je govoril ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 32, 'In potem pristopijo vsi sinovi Izraelovi; in zapove jim vse, kar mu je Gospod govoril na gori Sinaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 33, 'In ko je Mojzes končal svoj govor ž njimi, dene zagrinjalo na obličje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 34, 'Kadar pa je šel Mojzes noter pred obličje Gospodovo ž njim govorit, je snel zagrinjalo, dokler ni šel ven; in ko je bil prišel ven, je govoril sinovom Izraelovim, kar mu je bilo ukazano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 34, 35, 'In sinovi Izraelovi so videli obličje Mojzesovo, da se je žarila koža obličja njegovega; in Mojzes je zopet del zagrinjalo na obličje svoje, dokler ni šel noter govorit ž Njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 1, 'In Mojzes zbere vso občino sinov Izraelovih in jim reče: Te so besede, ki jih je zapovedal Gospod, da jih izpolnjujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 2, 'Šest dni naj se opravlja delo, a sedmi dan vam bodi svet čas, sobota slovesnega počitka Gospodu; kdorkoli opravlja kak posel ta dan, umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 3, 'Ne zanetite ognja po vseh prebivališčih svojih sobotni dan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 4, 'Dalje govori Mojzes vsej občini Izraelovih otrok: To je beseda, ki jo je zapovedal Gospod, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 5, 'Odločite si dar povzdignjenja Gospodu; kdorkoli je radovoljnega srca, naj ga prinese, dar povzdignjenja Gospodu: zlato in srebro in bron,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 6, 'višnjevo in zagorelordeče blago in karmezin in tenčico in kozjo dlako,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 7, 'in rdeče pobarvane ovnove kože in kože jazbečeve in akacijev les,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 8, 'in olje za svetilo in dišave za mazilno olje in za dišeče kadilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 9, 'in onihove kamene in drago kamenje, ki se ž njim obloži naramnik in naprsnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 10, 'In kdorkoli je modrega srca med vami, naj pride in izdeluje vse, kar je zapovedal Gospod:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 11, 'prebivališče, njega šator in odejo za njega, njegove zapone in deske in zapahe in stebre in podstavke;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 12, 'skrinjo in njena droga, pokrov sprave in ločilno zagrinjalo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 13, 'mizo in droga zanjo in vso posodo njeno in kruh obličja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 14, 'svečnik za svetilo in njegove priprave in svetilnice in olje za svetilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 15, 'in kadilni oltar in droga zanj, mazilno olje in blagodišeče kadilo, zaveso za vhod, za vhod v prebivališče;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 16, 'in oltar za žgalne daritve ž njegovim bronastim omrežjem, njegova droga in vse priprave njegove, umivalnik z njegovim stojalom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 17, 'zastore za dvorišče in stebre njegove in njih podstavke in zaveso za vrata na dvorišče;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 18, 'kolčke za prebivališče in kolčke za dvorišče in njih vrvi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 19, 'dična oblačila za službo v svetišču, sveta oblačila za Arona duhovnika in oblačila sinom njegovim za duhovniško službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 20, 'In vsa občina sinov Izraelovih se razide izpred Mojzesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 21, 'In pridejo, kogarkoli je sililo srce njegovo, vsak, čigar duh je bil radovoljen, in prineso Gospodov dar povzdignjenja za zgradbo shodnega šatora in za vse službovanje pri njem in za sveta oblačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 22, 'In prihajali so možje in žene, kolikorkoli jih je bilo radovoljnega srca, noseč zapestnice in uhane in pečatne prstane in ovratnice, vsakovrstno zlatnino, in vsakdo, ki je daroval dar majanja od zlata Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 23, 'In vsak, kdor je imel višnjevo in zagorelordeče blago in karmezin in tenčico in kozjo dlako in rdeče ovnove kože in jazbečeve kože, jih je prinesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 24, 'Vsak, kdor je poklonil dar povzdignjenja od srebra in brona, je prinesel dar Gospodov; in kdorkoli je imel akacijevega lesa za katerokoli napravo službe, ga je prinesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 25, 'In vse žene, ki so bile modrega srca, so predle same in prinesle prejo: višnjevo in zagorelordečo in karmezin in tenčico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 26, 'In vse žene, ki jih je podpiralo njih srce v modrosti, so predle kozjo dlako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 27, 'Knezi so pa prinesli onihovih kamenov in dragega kamenja, ki se ž njim obloži naramnik in naprsnik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 28, 'in dišav in olja za svetilo in za mazilno olje in za blagodišeče kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 29, 'Sinovi Izraelovi so prinesli prostovoljno daritev Gospodu: vsak mož in vsaka žena, katere je izpodbujalo njih srce, da kaj prineso za vse delo, o katerem je Gospod zapovedal Mojzesu, da naj se izgotovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 30, 'In Mojzes reče sinovom Izraelovim: Glejte, Gospod je po imenu poklical Bezalela, sina Urija, sinu Hurovega, iz rodovine Judove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 31, 'in ga je napolnil z duhom Božjim, ki se kaže v modrosti, razumnosti in znanosti in v vsakršni spretnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 32, 'da izumlja umetnine ter jih izdeluje iz zlata in srebra in brona');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 33, 'in zna rezati kamene, da se denejo v okove, in izrezavati les in delati vsakovrstne umetne izdelke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 34, 'Dal mu je tudi v srce, da poučuje, njemu in Oholiabu, sinu Ahisamakovemu, iz rodu Danovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 35, 35, 'Napolnil ju je z modrostjo srca, da napravita vsakovrstno delo kovaško in rezbarsko in umetno tkano in pisano vezeno iz višnjeve in zagorelordeče in karmezinove preje in iz tenčice in tkalsko delo, kakor tisti, ki delajo vsakovrstna ročna dela in izmišljajo umetne stvari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 1, 'In Bezalel in Oholiab bosta delala in vsi možje modrega srca, ki jim je Gospod dal modrost in razumnost, da znajo delati vsako delo v službo svetišča, skladno z vsem, kar je bil zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 2, 'In Mojzes pokliče Bezalela in Oholiaba in vsakega moža, ki je bil modrega srca, v čigar srce je Bog dal modrost, vsakega, kogar je srce sililo, da se loti dela in ga izvrši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 3, 'In prejmejo od Mojzesa vse dari povzdignjenja, ki so jih prinesli sinovi Izraelovi za delo v službo svetišča, da se s tem naredi. In še so mu prinašali prostovoljne darove dan na dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 4, 'In pridejo tisti modri možje vsi, ki so se pečali z delom svetišča, vsak od svojega dela, ki ga je opravljal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 5, 'in ogovore Mojzesa, rekoč: Mnogo prinaša ljudstvo, več nego je treba za izvršitev dela, ki ga je napraviti ukazal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 6, 'Tedaj zapove Mojzes, in razglasijo po vsem taboru, rekoč: Ne mož, ne žena naj nič več ne dela za dar povzdignjenja svetišču. In nehalo je ljudstvo prinašati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 7, 'Kajti gradiva je bilo dovolj za vse delo, da se dogotovi, in še preveč ga je bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 8, 'Vsi torej, ki so bili modrega srca med delavci tistega dela, so delali prebivališče: deset preprog iz sukane tenčice in višnjevega in zagorelordečega blaga in karmezina, s kerubi umetno pretkane so jih naredili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 9, 'Dolgost ene preproge osemindvajset komolcev in štiri komolce širjava preproge: ista mera za vse preproge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 10, 'In zvezal je pet preprog, drugo ob drugo, tudi drugih pet preprog je zvezal, drugo ob drugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 11, 'In naredil je pentlje iz višnjevega blaga na robu ene preproge, ob kraju ene zveze; enako je naredil na robu skrajne preproge pri drugi zvezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 12, 'Petdeset pentelj je napravil na prvi preprogi in petdeset pentelj na robu preproge, ki je bila skrajna pri drugi zvezi; pentlje so bile druga drugi nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 13, 'In naredil je petdset zapon iz zlata in staknil preprogi, prvo z drugo, s temi zaponami: tako je bilo prebivališče celota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 14, 'In naredil je preproge iz kozje dlake, da bodo šator nad prebivališčem: enajst takih preprog je naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 15, 'Dolgost vsake preproge je bila trideset komolcev in širjava štiri komolce: isto mero je imelo enajst preprog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 16, 'In staknil je pet preprog posebe in šest preprog posebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 17, 'In naredil je petdeset pentelj na robu skrajne preproge v prvi zvezi in petdeset pentelj na robu skrajne preproge v drugi zvezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 18, 'In napravil je petdeset bronastih zapon, da se ž njimi spoji šator v celoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 19, 'In naredil je odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož vrhu nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 20, 'In naredil je deske za prebivališče iz akacijevega lesa, pokonci stoječe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 21, 'Deset komolcev je bila dolgost vsake deske, eden in pol komolca pa širjava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 22, 'Vsaka deska je imela dva čepa, drug proti drugemu vstavljena: tako je napravil pri vseh deskah za prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 23, 'In izgotovil je deske za bivališče: dvajset desek za poldansko stran, proti jugu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 24, 'in naredil je štirideset podstav iz srebra za dvajset desek: dve podstavi pod eno desko za dva čepa njena in dve podstavi pod drugo desko za dva čepa njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 25, 'In za drugo stran prebivališča, proti severu, je naredil dvajset desek');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 26, 'in njih podstav iz srebra štirideset: dve podstavi pod eno desko in dve podstavi pod drugo desko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 27, 'In za zadnjo stran prebivališča, proti zahodu, je naredil šest desek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 28, 'In dve deski je naredil za vogla prebivališča ob zadnji strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 29, 'In bili sta dvojni odspodaj in enako sta bili sklenjeni ob vrhu svojem v enem obodu: tako je napravil pri obeh na obeh voglih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 30, 'Bilo je torej osem desek in njih podstav srebrnih šestnajst: pod vsako desko dve podstavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 31, 'In naredil je zapahe iz akacijevega lesa: pet za deske ene strani prebivališča');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 32, 'in pet zapahov za deske druge strani in pet zapahov za deske ob zadnji strani, proti zahodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 33, 'In srednji zapah sredi desek je naredil, da je segal od konca do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 34, 'In deske je prevlekel z zlatom in njih obode, namreč shrambice za zapahe, je naredil iz zlata in zapahe je okoval z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 35, 'In napravil je zagrinjalo iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice; s kerubi umetno pretkano ga je naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 36, 'In zanj je napravil štiri stebre iz akacijevega lesa in jih prevlekel z zlatom, njih kavlji so bili iz zlata, in ulil je zanje štiri podstave iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 37, 'In napravil je zaveso za šatorov vhod iz višnjevega in zagorelordečega blaga in iz karmezina in sukane tenčice s pisanim vezenjem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 36, 38, 'in njenih pet stebrov ž njih kavlji; oglavja stebrov pa in njih vezila je prevlekel z zlatom, a njih petero podstavkov je bilo iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 1, 'In Bezalel je naredil skrinjo iz akacijevega lesa: dva in pol komolca je bila dolga in poldrugi komolec široka in poldrugi komolec visoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 2, 'In prevlekel jo je s čistim zlatom odznotraj in odzunaj in vrhu nje je napravil zlat venec naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 3, 'In zlil je zanjo štiri zlate obode, vstavljene v njene štiri noge, dva oboda na eni strani in dva oboda na drugi strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 4, 'In naredil je droga iz akacijevine in ju okoval z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 5, 'In vtaknil je droga v obode ob straneh skrinje, da se prenaša skrinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 6, 'In napravil je pokrov sprave iz čistega zlata, dva in pol komolca dolg in poldrugi komolec širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 7, 'In naredil je dva keruba iz zlata s tolkljanim delom na obeh koncih spravnega pokrova:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 8, 'kerub je bil na tem koncu, kerub na drugem koncu; s pokrovom sceloma je naredil tista keruba na obeh njegovih koncih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 9, 'In keruba sta razprostirala svoje peruti navzgor, zaslanjajoč ž njimi pokrov sprave, z obrazoma drug proti drugemu; proti pokrovu sprave sta bili obrnjeni obličji kerubov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 10, 'Naredil je tudi mizo iz akacijevega lesa: dva komolca je bila dolga in en komolec široka, poldrugi komolec pa visoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 11, 'In prevlekel jo je s čistim zlatom in ji napravil zlat venec naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 12, 'In naredil je k njej spojno deščico kroginkrog, za dlan široko, in napravil je zlat venec k tej deščici naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 13, 'In ulil je zanjo štiri obode iz zlata, in pritrdil je obode na štiri vogle pri štirih miznih nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 14, 'Tik pod deščico so bili obodi, shrambici za droga, da se prenaša miza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 15, 'In napravil je droga iz akacijevega lesa in ju okoval z zlatom, da se ž njima prenaša miza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 16, 'In naredil je iz čistega zlata posode, ki so bile na mizi, njene sklede, torila, konvice in vrčke, s katerimi se naj izliva pitna daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 17, 'Naredil je tudi svečnik iz čistega zlata, tolkljano delo je bil s podstavkom in deblom svojim; čašice njegove, glavice in cvetice njegove so bile sceloma delane ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 18, 'In šestero vej se je raztezalo iz debla njegovega: tri veje z ene strani in tri veje z druge strani svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 19, 'Tri čašice, slične mandeljnovemu cvetu, so bile z glavico in cvetico na eni veji, in tri čašice, slične mandeljnovemu cvetu, z glavico in cvetico na veji drugi: tako je bilo na šesterih vejah, raztezajočih se iz svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 20, 'In na deblu svečnika štiri čaše, slične mandeljnovemu cvetu, s svojimi glavicami in cveticami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 21, 'namreč ena glavica pod vsakima dvema vejama, katerih se je raztezalo šest iz celote, iz svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 22, 'Njih glavice in veje so bile sceloma delane ž njim: vse je bilo enotno tolkljano delo iz čistega zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 23, 'In naredil mu je sedem svetilnic in utrinjala in lončke za utrinke iz čistega zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 24, 'Iz enega talenta čistega zlata ga je naredil in vse njegove priprave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 25, 'In naredil je kadilni oltar iz akacijevega lesa: en komolec dolgost njegova in en komolec širjava njegova, štirivoglat je bil in dva komolca visok; rogovi njegovi so bili enotni ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 26, 'In prevlekel ga je s čistim zlatom, vrh njegov in stene njegove in rogove njegove, in mu je naredil zlat venec kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 27, 'In napravil je zanj dva oboda iz zlata, pod vencem njegovim, ob voglih njegovih na obeh straneh, da se vanju vtakneta droga, s katerima se bo nosil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 28, 'In droga je naredil iz akacijevega lesa ter ju prevlekel z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 37, 29, 'In naredil je sveto olje za maziljenje in čisto, blagodišeče kadilo na mazilarski način.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 1, 'In naredil je oltar za žgalščine iz akacijevega lesa: pet komolcev dolg in pet komolcev širok, štirivoglat in tri komolce visok;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 2, 'in na štirih voglih njegovih je na pravil štiri rogove, ki so bili iz ene celote ž njim; in prevlekel ga je z bronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 3, 'In naredil je vse priprave oltarjeve: lonce in lopate in čaše, vilice in ponve za žerjavico; vse te priprave so bile iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 4, 'Napravil je tudi omrežje oltarju, mrežastega dela, iz brona, pri obrobnem podstavku, spodaj do polovice oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 5, 'In zlil je štiri obode za štiri vogle bronastega omrežja, da se vanje vtakneta droga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 6, 'Droga pa je naredil iz akacijevega lesa ter ju prevlekel z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 7, 'In vtaknil je droga v oboda na obeh straneh oltarja, da se ž njima prenaša; votlega, iz desek ga je naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 8, 'In naredil je umivalnik in stojalo njegovo iz brona, iz zrcal žen, ki so se zbirale, da strežejo pri vhodu shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 9, 'In napravil je dvorišče. Za poldansko stran, proti jugu, je bilo zastorov iz sukane tenčice sto komolcev');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 10, 'in dvajset stebrov zanje in dvajset podstavkov iz brona, kavlji za stebre in njih vezila iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 11, 'In na severni strani je bilo sto komolcev zastorov in zanje dvajset stebrov in dvajset podstavkov iz brona, kavlji za stebre in njih vezila so bili iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 12, 'In na zahodni strani je bilo petdeset komolcev zastorov in zanje deset stebrov in deset podstavkov, kavlji za stebre in njih vezila so bili iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 13, 'In na jutranji strani, proti vzhodu, petdeset komolcev:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 14, 'petnajst komolcev zastorov ob eni strani vhoda, trije stebri zanje in trije podstavki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 15, 'in ob drugi strani (tu in tam ob vratih na dvorišče) petnajst komolcev zastorov, trije stebri in trije podstavki zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 16, 'Vsi zastori ob dvorišču kroginkrog so bili iz sukane tenčice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 17, 'in podstavki stebrov iz brona, kavlji za stebre in njih vezila iz srebra in prevlaka njih oglavij iz srebra; in vsi stebri ob dvorišču so bili opremljeni s srebrnimi vezili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 18, 'In zaveso k vratom na dvorišče je naredil z umetno pisanim vezenjem iz višnjevega in zagorelordečega in karmezinovega blaga in iz sukane tenčice, in to dvajset komolcev dolgo in pet komolcev visoko po širjavi, skladno z drugimi zastori ob dvorišču;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 19, 'k zavesi pa štiri stebre in štiri podstavke iz brona in kavlje zanje iz srebra, tudi prevlako za njih oglavja in njih vezila iz srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 20, 'In vsi kolčki za prebivališče in ob dvorišču okoli so bili iz brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 21, 'To je preračun o prebivališču, prebivališču pričevanja, kakor se je preštelo po Mojzesovem povelju s pomočjo levitov pod roko Itamarja, sinu Aronovega, duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 22, 'Bezalel pa, sin Urija, sinu Hurovega, iz rodu Judovega, je naredil vse, kar je bil Gospod zapovedal Mojzesu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 23, 'in ž njim je bil Oholiab, sin Ahisamakov, iz rodu Danovega, kovač in tesar in umeten tkalec in vezec višnjevega in zagorelordečega blaga in karmezina in tenčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 24, 'Vsega zlata, kar se ga je uporabilo pri delu za vse naprave svetišča, zlata, ki se je darovalo kot daritev majanja, je bilo devetindvajset talentov, sedemsto in trideset seklov, po seklu svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 25, 'Srebra pa od preštetih v občini je bilo sto talentov in tisoč sedemsto in petinsedemdeset seklov, po seklu svetišča:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 26, 'kolikor glav, toliko polseklov, po seklu svetišča, od vsakega dvajset let starega in več, ki je prešel k preštetim, od šeststo in tri tisoč, petsto in petdeset mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 27, 'In iz sto talentov srebra so ulili podstavke svetišču in podstavke zagrinjalu, sto podstavkov iz sto talentov, talent za podstavek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 28, 'In iz tisoč sedemsto in petinsedemdesetih seklov je naredil kavlje za stebre in prevlekel njih oglavja in napravil na njih vezila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 29, 'In brona, ki so ga darovali kot daritev majanja, je bilo sedemdeset talentov in dvatisoč in štiristo seklov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 30, 'In iz tega je naredil podstavke vhodu v shodni šator in bronast oltar in k njemu bronasto omrežje in vse priprave oltarjeve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 38, 31, 'in podstavke ob dvorišču okoli in podstavke k vratom v dvorišče in vse kolčke pri prebivališču in vse kolčke na dvorišču kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 1, 'In iz višnjevega in zagorelordečega blaga in karmezina so napravili dična oblačila za službo v svetišču; in sveta oblačila Aronu so naredili, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 2, 'In naredili so naramnik iz zlata, iz višnjevega in zagorelordečega blaga in iz karmezina in iz sukane tenčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 3, 'In zlato so skovali v tenke liste ter iz njih rezali niti, da se je moglo tkati med višnjeve in škrlatne in karmezinove niti in med tenčico, na način umetnega tkalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 4, 'Naredili so za naramnik dva poramna dela, ki sta se spenjala; na svojih dveh koncih se je sklepal v eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 5, 'In umetno tkana preveza, ki je bila ob njem, je bila iz istega blaga in enakega dela kakor naramnik: iz zlata, iz višnjevega in zagorelordečega blaga in karmezina in iz sukane tenčice, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 6, 'In napravili so onihova kamena, opletena z zlatom, in vanju so bila vrezana, kakor se vrezuje v pečate, imena sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 7, 'In deli so ju na poramna dela naramnikova, da bodeta kamena spomina za sinove Izraelove, prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 8, 'In naredil je naprsnik, delo umetnega tkalca, istega dela kakor naramnik: iz zlata, višnjevega in zagorelordečega blaga in karmezina in iz sukane tenčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 9, 'Štirivoglat je bil; naredili so ga v dve gubi, ped dolg, in pet širok, dvojnat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 10, 'In obložili so ga s štirimi vrstami kamenov; vrsta prva: sardij, topaz in smaragd;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 11, 'in druga vrsta: rubin, safir in diamant;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 12, 'tretja vrsta pa: hiacint, ahat in ametist;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 13, 'in četrta vrsta: krizolit, onih in jaspis; opleteni so bili z zlatom v svojih vrstah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 14, 'In kamenov je bilo po imenih sinov Izraelovih dvanajst, po njih imenih; kakor se vrezuje v pečate, na vsakem je bilo vrezano ime, za dvanajstere rodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 15, 'In naredili so na naprsnik vrvčasti verižici, spleteni iz čistega zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 16, 'In naredili so dva okova iz zlata in dva zlata obročka, in pritrdili so tista obročka na oba konca naprsnikova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 17, 'In dve spleteni zlati vrvci so pritrdili na dva zlata obročka na koncih naprsnikovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 18, 'druga dva konca tistih dveh spletenih vrvic so pritrdili na dva okova in ju priteknili na poramna dela naramnikova, spredaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 19, 'In iz zlata narejena dva obročka so priteknili na obeh koncih naprsnikovih, na robu njegovem, ki je proti naramniku, odznotraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 20, 'Še so naredili dva zlata obročka in ju priteknili na dva poramna dela naramnikova, spodaj ob sprednji strani, ravno tam, kjer se sklepa, vrhu umetno tkane preveze naramnikove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 21, 'In privezali so naprsnik, njegove obročke k naramnikovim obročkom z višnjevo vrvico, da se gladko prilega nad umetno tkano prevezo naramnikovo ter da se naprsnik ne premakne z naramnika; prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 22, 'In naredil je vrhnjo suknjo pod naramnik, izcela stkano iz višnjevega blaga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 23, 'In odprtina suknje je bila sredi nje kakor odprtina pri oklepu, in je imela tvestje kroginkrog, da se ne razdere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 24, 'In za rob suknje so naredili margaranovih jabolk iz višnjevega, zagorelordečega in karmezinovega sukanca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 25, 'In napravili so zvončke iz čistega zlata in jih obesili med margaranova jabolka na rob suknje okoliinokoli, med margaranova jabolka:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 26, 'zvonček in margaranovo jabolko, zvonček in margaranovo jabolko na rob suknje vseokoli za službo; prav kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 27, 'In izgotovili so spodnje suknje iz tenčice na tkalčev način Aronu in sinom njegovim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 28, 'in pokrivalo iz tenčice in lepe visoke čepice iz tenčice in platnene hlače iz sukane tenčice');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 29, 'in pas iz sukane tenčice in iz višnjevega, zagorelordečega blaga in iz karmezina, pisano vezilnega dela, prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 30, 'In naredili so ploščo, venec sveti, iz čistega zlata in vanjo napisali, kakor se vrezuje pisanje v pečate: SVETOST Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 31, 'In pripeli so nanjo višnjevo vrvico, da se ž njo priveže zgoraj na pokrivalo, prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 32, 'Tako je bilo dopolnjeno vse delo pri prebivališču shodnega šatora, in sinovi Izraelovi so ga naredili; kakor je bil Gospod zapovedal Mojzesu, prav tako so storili vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 33, 'In prinesli so prebivališče k Mojzesu: šator in vse njegove priprave, njegove zapone, deske, zapahe, stebre in podstavke njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 34, 'in odejo za šator iz rdečih ovnovih kož in odejo iz jazbečevih kož in ločilno zagrinjalo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 35, 'skrinjo pričevanja in droga njena in spravni pokrov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 36, 'mizo, vso posodo njeno in kruh obličja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 37, 'čisti svečnik, svetilnice njegove, svetilnice, ki jih je imeti v redu, in vse priprave njegove in olje za svetilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 38, 'zlati oltar in mazilno olje in blagodišeče kadilo; in zaveso za vhod v šator;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 39, 'bronasti oltar z bronastim omrežjem njegovim, droga zanj in vse priprave njegove; umivalnik in stojalo njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 40, 'zastore za dvorišče, stebre in podstavke zanj; in zaveso za vrata na dvorišče in vrvi in kolčke zanje; in vse priprave za službo v prebivališču, za shodni šator;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 41, 'službena oblačila za službo v svetišču, sveta oblačila za Arona duhovnika in sinov njegovih oblačila, da duhovniško službo opravljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 42, 'Po vsem, kar je bil Gospod zapovedal Mojzesu, so sinovi Izraelovi napravili vse delo natanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 39, 43, 'In Mojzes je ogledal vse delo, in glej, prav so ga naredili; kakor je bil Gospod zapovedal, tako so ga napravili; in Mojzes jih je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 2, 'Prvi dan prvega meseca postavi prebivališče, shodni šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 3, 'In postavi vanje skrinjo pričevanja in zasloni skrinjo z zagrinjalom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 4, 'In prinesi mizo v prebivališče in uredi na njej, kar je treba urediti, in prinesi svečnik in prižgi svetilnice njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 5, 'In postavi zlati oltar za kajenje pred skrinjo pričevanja in obesi zaveso k vhodu v prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 6, 'In postavi oltar za žgalščine pred vhod v prebivališče shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 7, 'In postavi umivalnik med shodni šator in oltar ter vlij vanj vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 8, 'In postavi dvorišče okoli in obesi zaveso k vratom na dvorišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 9, 'In vzemi mazilno olje ter pomazili prebivališče in vse, kar je v njem, in ga posveti in vso opravo njegovo; in bode sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 10, 'In pomazili oltar za žgalščine in vse priprave njegove in posveti oltar; in oltar bode presvet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 11, 'In pomazili umivalnik in stojalo njegovo ter ga posveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 12, 'In privedi Arona in sinove njegove k vhodu shodnega šatora in jih umij z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 13, 'In obleci Arona v sveta oblačila ter ga pomazili in posveti, da mi opravlja duhovniško službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 14, 'Sinove njegove tudi privedi in jih obleci v spodnje suknje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 15, 'in jih pomazili, kakor si pomazilil njih očeta, da mi opravljajo duhovniško službo. In njih maziljenje se zgodi, da jim ostane večno duhovništvo po njih prihodnjih rodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 16, 'In Mojzes je storil to; po vsem, kar mu je bil zapovedal Gospod, je storil prav tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 17, 'In zgodilo se je prvi mesec drugega leta, prvi dan meseca, da je bilo prebivališče postavljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 18, 'In Mojzes je postavil prebivališče in zasadil podstavke njegove in postavil deske njegove in vtaknil zapahe njegove in postavil stebre njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 19, 'In razpel je šator čez prebivališče in del vrhu njega šatorovo odejo, prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 20, 'In je vzel pričevanje in ga položil v skrinjo in vtaknil oboda v skrinjo in je del spravni pokrov vrhu nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 21, 'In prinesel je skrinjo v prebivališče, in ko je obesil ločilno zagrinjalo, je zaslonil skrinjo pričevanja, prav kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 22, 'In postavil je mizo v shodni šator na stran prebivališča proti severu, zunaj pregrinjala;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 23, 'in je razporedil na njej vrsto kruhov pred obličje Gospodovo, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 24, 'In postavil je svečnik v shodni šator, mizi nasproti, na južno stran prebivališča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 25, 'In prižgal je svetilnice pred Gospodom, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 26, 'In postavil je zlati oltar v shodni šator pred pregrinjalo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 27, 'in zažgal na njem blagodišeče kadilo, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 28, 'In obesil je zaveso k vhodu v prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 29, 'In oltar za žgalščine je postavil pred vhod v prebivališče shodnega šatora in je daroval na njem žgalno in jedilno daritev, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 30, 'In postavil je umivalnik med shodni šator in oltar in vlil vode vanj za umivanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 31, 'In Mojzes in Aron in sinovi njegovi so si iz njega umivali roke in noge;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 32, 'kadar so šli v shodni šator in kadar so se bližali oltarju, so se umivali, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 33, 'in postavil je dvorišče okoli prebivališča in oltarja in je obesil zaveso k vratom na dvorišče. Tako je dopolnil Mojzes delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 34, 'In oblak je pokril shodni šator, in slava Gospodova je napolnila prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 35, 'In Mojzes ni mogel iti v shodni šator, kajti oblak je počival nad njim, in slava Gospodova je napolnila prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 36, 'In kadar se je vzdignil oblak iznad prebivališča, so se odpravili sinovi Izraelovi na pot, dokler so bili na potovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 37, 'Ko se pa oblak ni vzdignil, se niso odpravili do dne, kadar se je vzdignil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (2, 40, 38, 'Zakaj oblak Gospodov je bil po dne na prebivališču, po noči pa ogenj v oblaku pred očmi vse hiše Izraelove, dokler so bili na potovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 1, 'In pokliče Gospod Mojzesa in mu govori iz shodnega šatora, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 2, 'Govóri sinovom Izraelovim in jim reci: Če hoče kdo izmed vas prinesti darilo Gospodu, od živine, od govedi ali drobnice, prinesite darilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 3, 'Čigar darilo je v žgalno daritev od govedi, naj prinese samca brez hibe; pri vhodu shodnega šatora naj ga daruje, da bo milo sprejet pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 4, 'In položi naj roko svojo na glavo žgalne žrtve, da bo milo sprejeta za njega, v poravnavo zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 5, 'In zakolje naj tisto mlado govedo pred Gospodom; in prineso sinovi Aronovi, duhovniki, kri njegovo in ž njo poškropé kroginkrog oltar, ki je proti vhodu v shodni šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 6, 'In odere žgalno daritev in jo razseka v njene kose.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 7, 'In sinovi Arona duhovnika denejo ogenj na oltar in polože drva na ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 8, 'Potem naj sinovi Aronovi, duhovniki, polože te kose, glavo in tolščobo na drva nad ognjem vrh oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 9, 'Njegovo drobje pa in noge njegove naj se opero v vodi; in duhovnik naj zažge vse to na oltarju: žgalna daritev je, ognjena žrtev v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 10, 'Če pa je darilo njegovo drobnica, od ovac ali koz, v žgalno daritev, prinese naj samca brez hibe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 11, 'In naj ga zakolje na polnočni strani oltarja pred Gospodom; in razškrope naj sinovi Aronovi, duhovniki, kri njegovo po oltarju kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 12, 'In naj ga razseka v kose njegove z glavo in tolščo njegovo, in duhovnik jih polóži na drva nad ognjem vrh oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 13, 'Drobje pa in noge naj umije z vodo, in duhovnik naj vse to daruje in zapali na oltarju: žgalna daritev je, ognjena žrtev v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 14, 'Ako pa je darilo njegovo ptica v žgalščino Gospodu, naj prinese grlico ali golobčka za darilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 15, 'In duhovnik prinesi ptico k oltarju in ji odščipni z nohtom glavico in jo zažgi na oltarju, njena kri pa naj se iztisne na oltarjevo steno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 16, 'Golžun in nesnago njeno pa naj odpravi ter vrže to poleg oltarja na vzhodno stran na pepelišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 1, 17, 'In naj jo nakrhne ob krilih, ne da bi jo pretrgal, in duhovnik naj jo zažge na oltarju, na drvih, ki so na ognju: žgalna daritev je, žrtev po ognju v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 1, 'Če pa hoče kdo prinesti darilo jedilne žrtve Gospodu, bela moka bodi darilo njegovo, in naj vlije olja nanjo in dene nanjo kadila');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 2, 'in jo prinese sinovom Aronovim, duhovnikom; in duhovnik naj vzame prgišče tega, moke in olja z vsem kadilom njenim, in naj to sežge na oltarju kot njen spomin: ognjena žrtev je v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 3, 'Kar pa ostane jedilne daritve, bodi Aronovo in sinov njegovih: presveto je od ognjenih žrtev Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 4, 'Če pa hočeš prinesti v darilo jedilne žrtve kaj v peči pečenega, naj bodo opresni kolači iz bele moke, zamešeni z oljem, ali pa opresni mlinci, pomazani z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 5, 'Ako je pa darilo tvoje jedilna žrtev, pečena v ponvi, naj bode iz bele moke, zamešena z oljem, brez kvasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 6, 'Zdrobi jo v grižljaje in vlij nanjo olja: jedilna daritev je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 7, 'Ako je pa darilo tvoje jedilna žrtev, skuhana v kotlu, bodi pripravljena iz bele moke z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 8, 'In prinesi jedilno daritev, ki si jo iz tega pripravil, Gospodu, in podaj jo duhovniku, in on pristopi ž njo k oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 9, 'In duhovnik naj vzame od jedilne daritve, kar je v njen spomin, in to zažge na oltarju: ognjena žrtev je v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 10, 'Kar pa ostane jedilne daritve, bodi Aronovo in sinov njegovih: presveto je od ognjenih daritev Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 11, 'Nobene jedilne daritve, ki jo prinesete Gospodu, ne pripravljajte s kvasom; kajti ničesar od kvasu, ne od medu ne smete žgati v žrtev Gospodu po ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 12, 'Kot daritev prvin jih smete prinesti Gospodu, a na oltar naj se ne pokladajo v prijeten duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 13, 'In sleherno darilo jedilne žrtve svoje osoli in ne daj, da bi zmanjkalo soli zaveze Boga tvojega pri jedilnih daritvah tvojih: z vsemi darili svojimi daruj soli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 14, 'In če hočeš prinesti Gospodu jedilno daritev od prvin, daruj zrnja v klasju, opraženega na ognju, zrnja raztolčenega, kot jedilno daritev od prvin svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 15, 'In vlij nanje olja in deni nanje kadila: jedilna daritev je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 2, 16, 'In duhovnik naj sežge del zrnja raztolčenega in del olja z vsem kadilom njegovim kot njen spomin: ognjena žrtev je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 1, 'In čigar darilo je mirovna žrtev: ako daruje govedo, bodisi samec ali samica, brezhibno naj prinese pred Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 2, 'In položi naj roko svojo na glavo darila svojega in ga zakolje pri vhodu shodnega šatora; in sinovi Aronovi, duhovniki, naj poškrope s krvjo oltar kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 3, 'In del mirovne daritve naj daruje kot ognjeno žrtev Gospodu, namreč tolstino, ki pokriva drobje, in karkoli je tolsti na črevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 4, 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 5, 'In zažgo naj to sinovi Aronovi na oltarju nad žgalno daritvijo na drvih, ki so na ognju: ognjena žrtev je v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 6, 'Ako pa je od drobnice darilo njegovo, Gospodu v mirovno daritev, bodisi samec ali samica, brezhibno naj prinese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 7, 'Če pokloni ovco v darilo svoje, naj jo daruje pred Gospodom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 8, 'in položi naj roko na glavo darila svojega in ga zakolje pred shodnim šatorom; in poškrope naj sinovi Aronovi s krvjo oltar kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 9, 'In daruj del mirovne daritve kot ognjeno žrtev Gospodu: njeno mast, ves tolsti rep, ki ga odreže tik hrbtenice, in tolstino, ki pokriva drobje, in vso tolstino na črevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 10, 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 11, 'In zažge naj to duhovnik na oltarju: živež je daritve po ognju Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 12, 'Ako je koza njegovo darilo, naj jo daruje pred Gospodom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 13, 'in naj ji položi roko svojo na glavo in jo zakolje pred shodnim šatorom; in sinovi Aronovi naj škrope njeno kri po oltarju naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 14, 'In del od nje naj prinese v darilo svoje kot ognjeno žrtev Gospodu: tolstino, ki pokriva drobje, in karkoli je tolstine na črevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 15, 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 16, 'In zažge naj to duhovnik na oltarju: živež je ognjene daritve v prijeten duh; vsa tolstina bodi Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 3, 17, 'Večna bodi to postava prihodnjim rodovom vašim po vseh prebivališčih vaših: ne tolstine, ne krvi nikar ne uživajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 2, 'Govóri sinovom Izraelovim in véli: Če se kdo pregreši po pomoti v čemerkoli, za kar je Gospod zapovedal, da se ne sme storiti, pa storí kaj takega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 3, 'če se pregreši pomaziljeni duhovnik, tako da spravi krivdo nad ljudstvo, naj daruje za svoj greh, ki ga je zagrešil, mladega junca brez hibe Gospodu v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 4, 'In naj privede junca k vhodu shodnega šatora pred Gospoda in mu položi roko na glavo in ga zakolje pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 5, 'In pomaziljeni duhovnik vzemi nekoliko krvi in jo nesi v shodni šator,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 6, 'in naj si omoči prst v krvi in škropi ž njo sedemkrat pred Gospodom, proti zagrinjalu svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 7, 'In dene naj duhovnik nekaj krvi na rogove oltarja blagodišečih kadil pred Gospodom, ki je v shodnem šatoru; in vso ostalo junčevo kri naj izlije v znožje oltarja žgalnih daritev, ki je proti vhodu v shodni šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 8, 'In vso tolstino junca, darovanega za greh, naj pobere ž njega: tolstino, ki pokriva drobje, in karkoli je tolstine na črevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 9, 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih: z ledicami vred naj to odreže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 10, 'kakor se jemlje od goveda mirovne daritve; in duhovnik naj to zažge na oltarju žgalnih daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 11, 'Kožo pa junčevo in vse meso njegovo z glavo, z nogami in drobom in blatom njegovim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 12, 'vsega junca naj odneso ven iz taborišča na čist kraj, kamor se siplje pepel, in sežgo naj ga na drvih z ognjem; na pepelišču naj ga sežgo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 13, 'In če se vsa občina Izraelova pregreši po pomoti in stvar bi bila prikrita očem zbora, in učinili so, kar je Gospod zapovedal, da se storiti ne sme, in so krivi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 14, 'ko spoznajo greh, s katerim so grešili, tedaj naj daruje zbor mladega junca v daritev za greh in ga privede pred shodni šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 15, 'In položé naj starejšine občine juncu roke na glavo pred Gospodom in naj ga zakoljejo pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 16, 'In pomaziljeni duhovnik naj nese junčeve krvi v shodni šator,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 17, 'in pomoči naj si prst v kri in škropi sedemkrat pred Gospodom proti zagrinjalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 18, 'In deni nekoliko krvi na rogove oltarja, ki je pred Gospodom v shodnem šatoru; in vso drugo kri naj izlije v znožje oltarja žgalnih daritev, ki je proti vhodu v shodni šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 19, 'In vso tolstino naj pobere ž njega in jo zažge na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 20, 'In naredi naj z juncem, kakor je naredil z juncem daritve za greh: prav tako naj ž njim stori. In tako naj izvrši duhovnik poravnavo zanje, in bode jim odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 21, 'In junca naj odneso ven iz šatorišča in ga sežgo, kakor so sežgali prvega junca: daritev za greh je to zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 22, 'Ko se pregreši knez in stori po pomoti katerokoli reč, ki je zanjo zapovedal Gospod, njegov Bog, da se storiti ne sme, in je kriv:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 23, 'kadar mu pride na vest greh, s katerim je grešil, naj prinese kozla, brezhibnega samca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 24, 'In naj položi kozlu roko na glavo in ga zakolje na mestu, kjer koljejo žgalne daritve pred Gospodom: daritev za greh je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 25, 'In duhovnik vzemi s prstom krvi daritve za greh in jo deni na rogove žgalnega oltarja, in ostalo kri izlij v znožje žgalnega oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 26, 'In vso tolstino njegovo naj sežge na oltarju, kakor tolst daritev mirovnih. In tako naj izvrši duhovnik poravnavo zanj zaradi njegovega greha, in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 27, 'Ako pa se pregreši kdo iz preprostega ljudstva po pomoti in stori zoper eno izmed prepovedi Gospodovih, kar se ne sme storiti, in je kriv:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 28, 'kadar mu pride na vest greh, s katerim je grešil, naj prinese darilo svoje, kozo brez hibe, samico, za greh svoj, ki ga je zakrivil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 29, 'In položi naj roko na glavo daritve za greh in zakolje daritev za greh na kraju za žgalščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 30, 'In duhovnik vzemi njene krvi s prstom in jo deni na rogove žgalnega oltarja, in vso ostalo kri njeno izlij v znožje oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 31, 'In odreže naj vso tolst njeno, kakor se odreže od daritev mirovnih; in duhovnik naj jo zažge na oltarju v prijeten duh Gospodu. In tako naj izvrši duhovnik poravnavo zanj, in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 32, 'Če pa prinese ovco kot darilo svoje v žrtev za greh, naj bode brez hibe samica, ki jo bo daroval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 33, 'In položi naj roko na glavo daritvi za greh in jo zakolje za greh na kraju, kjer se navadno koljejo žgalščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 34, 'In duhovnik vzemi krvi daritve za greh s prstom in jo deni na rogove žgalnega oltarja, in vso ostalo kri njeno izlij v znožje oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 4, 35, 'In vso tolstino njeno naj odreže, kakor se odreže tolst od ovce daritve mirovne; in duhovnik naj jo zažge na oltarju, na ognjenih daritvah Gospodu. In tako naj izvrši duhovnik poravnavo zanj, za greh njegov, in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 1, 'In če se kdo pregreši s tem, da čuje glas zaprisege, in sam je bil priča, bodi da je stvar videl ali zvedel, pa ničesar ne izpove, bo nosil krivico svojo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 2, 'ali pa če se kdo dotakne česa nečistega, bodi mrhovine nečiste zveri, ali mrhovine nečiste živali, ali mrhovine nečiste laznine, čeprav mu je prikrito, vendar je nečist in kriv;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 3, 'ali pa če se dotakne nečistosti človeka, najsi bo kakršnakoli nečistost njegova, s katero se onečisti, in mu je prikrito, kadar pa zazna, je kriv;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 4, 'ali pa če kdo priseže, nepremišljeno govoreč z usti svojimi, da stori zlo ali dobro, o čemerkoli človek lahko govori nepremišljeno s prisego, in mu je prikrito, kadar pa spozna, kriv je ene teh reči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 5, 'če je torej kriv česa takega, naj pripozna, s čimer je grešil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 6, 'in prinese naj daritev za krivdo Gospodu za greh, s katerim se je pregrešil: samico iz drobnice, ovco ali kozo, v daritev za greh; in duhovnik naj izvrši poravnavo zanj, zaradi greha njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 7, 'Če pa imetje njegovo ni zadostno za ovco, naj prinese za svojo krivdo, s katero se je pregrešil, dve grlici ali dva golobiča Gospodu, enega za greh, enega pa v žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 8, 'In prinese naj ju k duhovniku, ki naj daruje tistega, ki je v daritev za greh, najprej in mu odščipne glavico tik zatilnika, ne da bi jo odtrgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 9, 'In škropi naj kri daritve za greh na oltarjevo steno, in ostala kri naj se iztisne v znožje oltarja: daritev je za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 10, 'Drugega pa naj pripravi v žgalno daritev, po predpisu. In tako naj izvrši duhovnik poravnavo zanj, zaradi greha njegovega, s katerim je grešil, in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 11, 'Ako pa ne premore dveh grlic ali dveh golobičev, naj prinese tisti, ki je grešil, za svoje darilo desetino efe bele moke v daritev za greh; ne vlije pa naj olja nanjo in ne dene kadila nanjo, ker daritev za greh je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 12, 'In naj jo prinese k duhovniku, in duhovnik je vzemi prgišče kot njen spomin, in zažge naj to na oltarju, na ognjenih daritvah Gospodu: daritev za greh je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 13, 'In tako naj izvrši duhovnik poravnavo zanj, za njegov greh, ki ga je zagrešil v katerikoli teh reči, in bo mu odpuščeno; in kar preostane, bodi duhovnikovo kakor jedilna daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 14, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 15, 'Če kdo zakrivi iznevero in se ponevedoma pregreši pri tem, kar je sveto Gospodu, naj prinese daritev za krivdo Gospodu, ovna brez hibe izmed črede, po cenitvi tvoji v seklih srebrnih, po seklu svetišča, v daritev za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 16, 'In kolikor je zagrešil škode pri svetem, naj povrne in peti del še pridene in da duhovniku; in duhovnik naj izvrši poravnavo zanj z ovnom daritve za krivdo, in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 17, 'In če kdo greši in zakrivi katerokoli reč, za katero je Gospod zapovedal, da se ne sme storiti, dasi tega ni vedel, je kriv in bo nosil krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 18, 'Prinese naj torej brezhibnega ovna izmed črede, po cenitvi tvoji, k duhovniku v daritev za krivdo; in duhovnik naj izvrši poravnavo zanj, za pomoto njegovo, ki jo je učinil, ne da bi bil vedel; in bo mu odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 5, 19, 'Daritev za krivdo je; kriv je bil vsekakor pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 2, 'Če se kdo pregreši in zakrivi iznevero proti Gospodu s tem, da utaji bližnjemu svojemu stvar, ki mu jo je zaupal ali dal v zajem, ali mu utaji kaj ukradenega, ali če ga je opeharil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 3, 'ali pa je našel izgubljeno stvar in to zataji, in krivo priseže zavoljo česarkoli, kar lahko stori človek in s tem greši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 4, 'če se je torej pregrešil in je kriv, mora povrniti, kar je siloma vzel ali za kar je koga opeharil, ali tisto, kar mu je bilo zaupano, ali izgubljeno, kar je našel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 5, 'ali karkoli je, zaradi česar je krivo prisegel; povrne pa naj spolnoma in pridene še peti del; tistemu, čigar je, naj to da v dan svojega darovanja za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 6, 'In prinese naj k duhovniku svojo daritev za krivdo Gospodu, brezhibnega ovna izmed črede, ki je po cenitvi tvoji vreden daritve za krivdo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 7, 'in duhovnik naj izvrši poravnavo zanj pred Gospodom, in bode mu odpuščeno v vsem, kar kdo lahko stori, da se s tem okrivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 8, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 9, 'Zapovej Aronu in sinovom njegovim takole: To je postava za žgalno daritev: Žgalna daritev bodi na ognjišču, na oltarju, vso noč do jutra; in ogenj na oltarju naj se neti, da gori na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 10, 'In duhovnik naj obleče svoje platneno oblačilo in platnene hlače naj obleče na nagoto svojo; in pospravi naj z ognjišča pepel, ki je ostal po ognju žgalne daritve na oltarju, in ga dene poleg oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 11, 'Nato naj sleče svoja oblačila in obleče druga oblačila in naj nese pepel iz taborišča na čist kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 12, 'Ogenj pa na oltarju naj se neti, da gori, nikoli naj ne ugasne; in duhovnik naj priklada nanj drva vsako jutro in opravlja na njem žgalno daritev in sežiga na njem tolstino daritev mirovnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 13, 'Ogenj naj se neti, da gori na oltarju neprenehoma, nikoli naj ne ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 14, 'In to je postava za jedilno daritev: Sinovi Aronovi naj jo darujejo pred Gospodom, pred oltarjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 15, 'Eden njih naj vzame polno prgišče bele moke in olja od jedilne daritve in vse kadilo, ki je na jedilni daritvi, in zažge naj to na oltarju v prijeten duh, v njen spomin Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 16, 'Kar pa je preostane, naj použije Aron in sinovi njegovi; jedlo se bo brez kvasu na svetem kraju, na dvorišču shodnega šatora naj to použijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 17, 'Ne sme se peči s kvasom. Dal sem jim to v delež pri ognjenih daritvah meni, presveto je, kakor žrtev za greh in kakor daritev za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 18, 'Vsak moški med otroki Aronovimi bo to jedel: večna bodi to pravica prihodnjim rodovom vašim od ognjenih daritev Gospodovih. Karkoli se jih dotakne, bo sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 19, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 20, 'To je darilo Aronovo in sinov njegovih, ki je bodo darovali Gospodu v dan, ko bo maziljen: desetino efe bele moke kot stalno jedilno daritev, polovico tega zjutraj in polovico tega zvečer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 21, 'V ponvi bodi pripravljena z oljem, zamešeno z oljem jo prinesi; pečeno, kot jedilno daritev v grižljajih daruj to v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 22, 'In duhovnik, ki bo na njegovem mestu pomaziljen izmed sinov njegovih, naj to daruje; večna postava bodi: vse naj se to zažge Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 23, 'In vsaka jedilna daritev duhovnikova naj se vsa sežge, jesti se ne sme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 24, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 25, 'Govóri Aronu in sinom njegovim: To je postava daritve za greh: Na tistem kraju, kjer se koljejo žgalne daritve, naj zakoljejo daritev za greh pred Gospodom: presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 26, 'Duhovnik, ki jo daruje za greh, jo bo jedel; na svetem kraju naj se zaužije, na dvorišču shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 27, 'Karkoli se dotakne njenega mesa, bode sveto; in če se ž njeno krvjo oškropi kako oblačilo, operi tisto, kar je bilo oškropljeno, na svetem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 28, 'Prstena posoda pa, v kateri se je kuhala, naj se razbije; če se pa je kuhala v bronasti posodi, naj se odrgne in poplakne z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 29, 'Vsak moški izmed duhovnikov jo bo jedel: presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 6, 30, 'Ali nobena daritev za greh, katere kri se prinese v shodni šator, da se v svetišču izvrši poravnava, se ne sme jesti; z ognjem naj se sežge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 1, 'To pa je postava daritve za krivdo: presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 2, 'Na kraju, kjer se koljejo žgalne daritve, naj zakoljejo daritev za krivdo; in ž njeno krvjo naj duhovnik poškropi oltar kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 3, 'In daruje naj vso tolstino njeno, tolsti rep in vso tolst, ki pokriva drobje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 4, 'in obe ledici in tolst, ki je na njiju, ki je na obledju, in pečico na jetrih, z ledicama vred naj jo odreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 5, 'In duhovnik naj to zažge na oltarju kot ognjeno daritev Gospodu: daritev za krivdo je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 6, 'Vsak moški izmed duhovnikov jo bo jedel, na svetem kraju naj se zaužije: presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 7, 'Kakor daritev za greh, tako daritev za krivdo: ista postava velja za obe. Duhovnik, ki izvršuje poravnavo ž njo, naj jo dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 8, 'In duhovnik, ki daruje čigarkoli žgalno daritev, naj dobi zase kožo žgalščine, ki jo je daroval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 9, 'In vsako jedilno daritev, ki se peče v peči, ali kar koli se pripravlja v kotlu ali v ponvi, naj dobi duhovnik, ki to daruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 10, 'In vsako jedilno daritev, zamešeno z oljem ali pa suho, naj dobodo vsi sinovi Aronovi, eden kakor drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 11, 'In to je postava mirovne daritve, ki se prinaša Gospodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 12, 'Če jo kdo prinese v zahvalo, naj prinese z zahvalno daritvijo vred opresne kolače, mešane z oljem, in opresne mlince, pomazane z oljem, in zamešeno belo moko, kolače, zmešane z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 13, 'Zraven kolačev naj prinese kvašenih kruhov za darilo, s svojo zahvalno-mirovno daritvijo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 14, 'In naj daruje po en kolač od vsega darila kot podvig Gospodu; duhovnikov bodi, ki škropi kri mirovne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 15, 'Meso pa mirovne daritve, ki je v zahvalo, naj se použije v dan njegovega darovanja; nič je ne sme ostati do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 16, 'Ako pa je klalščina darila njegovega v izpolnitev obljube ali dobrovoljen dar, naj se použije v dan, ob katerem prinese žrtev svojo; in drugega dne se sme použiti, kar je preostane;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 17, 'kar pa ostane mesa klalščine do tretjega dne, bodi sežgano na ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 18, 'Če pa se bo kako jedlo meso njegove mirovne daritve tretji dan, ne bo milo sprejeto, tudi ne bo veljalo za tistega, ki jo je daroval: gnusoba bode, in duša, ki zaužije od tega, bo nosila krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 19, 'In meso, ki se dotakne kakršnekoli nečiste stvari, se ne sme jesti; z ognjem naj se sežge. Sicer sme jesti to meso vsak, kdorkoli je čist:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 20, 'ali duša, ki užije meso od mirovnih daritev, lastnih Gospodu, ko je nečistota njena na njej, ta duša bo iztrebljena iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 21, 'In če se kdo dotakne česa nečistega, nečistote človeka ali nečiste živali ali katerekoli nečiste gnusobe, pa zaužije meso mirovnih daritev, lastnih Gospodu, ta duša bo iztrebljena iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 22, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 23, 'Govóri sinovom Izraelovim in reci: Nobene tolstine od govedi, od ovac in koz ne jejte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 24, 'Tolst od mrline in tolst od raztrganega živinčeta pa vsakovrstno obrnite v prid, ali je nikar ne jejte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 25, 'Zakaj kdorkoli jé tolstino živine, od katere se prinaša ognjena daritev Gospodu: duša, ki to užije, bo iztrebljena iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 26, 'In nobene krvi ne uživajte, ne od ptic, ne od živine, po vseh prebivališčih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 27, 'Kdorkoli bi užival kakršnokoli kri, ta duša bo iztrebljena iz ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 28, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 29, 'Govori sinovom Izraelovim in reci: Kdor prinese mirovno daritev Gospodu, naj prinese darilo svoje Gospodu od mirovne daritve svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 30, 'V svojih rokah naj prinese, kar naj se po ognju daruje Gospodu; tolstino s prsmi vred naj prinese, da se prsi semtertja majejo v majanja dar pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 31, 'In duhovnik naj zažge tolstino na oltarju, prsi pa ostanejo Aronu in sinovom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 32, 'In desno stegno dajte kot dar povzdiga duhovniku od mirovnih daritev svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 33, 'Tistemu med sinovi Aronovimi, ki daruje kri mirovne daritve in tolst, bodi desno stegno v delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 34, 'Zakaj prsi majalne daritve in stegno povzdiga sem vzel od sinov Izraelovih, od njih mirovnih daritev, in sem jih dal Aronu duhovniku in sinovom njegovim kot vekomaj jim določeno od sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 35, 'To je delež maziljenja, določen Aronu in sinovom njegovim od ognjenih daritev Gospodovih od dne, ko jim je velel pristopiti, da opravljajo duhovniško službo Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 36, 'o katerem je Gospod zapovedal v dan, ko jih je pomazilil, da naj ga jim dajó sinovi Izraelovi. Večna to je določba za njih prihodnje rodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 37, 'To je postava žgalne in jedilne daritve in daritve za greh in za krivdo in daritve posvečevanja in mirovne daritve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 7, 38, 'ki jo je Gospod ukazal Mojzesu na gori Sinajski v dan, ob katerem je zapovedal sinovom Izraelovim, da naj prinašajo darila svoja Gospodu, v puščavi Sinajski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 2, 'Vzemi Arona in sinove njegove ž njim, in oblačila in mazilno olje in junca v daritev za greh in tista dva ovna in koš opresnikov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 3, 'in skliči vso občino k vhodu shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 4, 'In Mojzes stori, kakor mu je zapovedal Gospod, in občina se zbere pri vhodu shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 5, 'In Mojzes veli občini: To je, kar je zapovedal Gospod, da naj se izvrši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 6, 'In privede Arona in sine njegove in jih umije z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 7, 'In njega obleče v spodnjo suknjo in ga opaše s pasom in ga odene z vrhnjo suknjo in mu nadene naramnik in ga opaše z umetno tkano prevezo naramnikovo in mu ga priveže ž njo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 8, 'in nanj dene naprsnik in v naprsnik dene Urim in Tumim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 9, 'In na glavo mu dene pokrivalo in mu na pokrivalo priveže odspredaj zlato pločo, sveti venec; kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 10, 'In Mojzes vzame mazilno olje in pomazili prebivališče in vse, kar je bilo v njem, in posveti vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 11, 'In poškropi ž njim oltar sedemkrat, in pomazili oltar in vse priprave njegove in umivalnik in stojalo njegovo, da jih posveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 12, 'In vlije mazilnega olja Aronu na glavo in ga pomazili, da ga posveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 13, 'In privede Mojzes sinove Aronove in jih obleče v spodnje suknje ter jih opaše s pasovi in jim nasadi visoke čepice, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 14, 'In pripelje junca v daritev za greh; Aron pa in sinovi njegovi položé roke na glavo juncu, ki je za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 15, 'In ga zakolje, in Mojzes vzame kri in jo dene s prstom na rogove oltarja kroginkrog in očisti oltar greha; in ostalo kri izlije v znožje oltarja in ga posveti, storivši poravnavo zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 16, 'In vzame vso tolstino, ki je okoli drobja, in pečico ob jetrih in obe ledici in njuno tolst, in Mojzes zažge to na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 17, 'Junca pa in kožo njegovo in meso in blato njegovo sežge z ognjem zunaj taborišča, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 18, 'Potem pripelje ovna v žgalno daritev; Aron pa in sinovi njegovi polože roke ovnu na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 19, 'In ga zakolje, in Mojzes razškropi kri krog po oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 20, 'A ovna razseka na kose njegove, in Mojzes zapali glavo in kose in tolstino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 21, 'Drobje pa in goleni opere z vodo; in Mojzes zažge vsega ovna na oltarju: bila je žgalščina v prijeten duh, bila je ognjena daritev Gospodu, kakor je bil zapovedal Gospod Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 22, 'In pripelje drugega ovna, ovna posvečenja; Aron pa in sinovi njegovi položé roke ovnu na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 23, 'In ga zakolje, in Mojzes vzame krvi njegove ter jo dene na mečico desnega Aronovega ušesa in na palec desnice njegove in na palec desne noge njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 24, 'In veli pristopiti sinovom Aronovim, in Mojzes jim dene krvi na mečico desnega ušesa in na palec desnice in na palec desne noge; in Mojzes razškropi ostalo kri krog po oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 25, 'In vzame tolstino in tolsti rep in vso tolstino, ki je okoli drobja, in jetrno pečico in obe ledici in njuno tolst in desno stegno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 26, 'in vzame iz koša opresnikov, ki je bil pred Gospodom, opresen kolač in hlebček z oljem zamešenega kruha in mlinec, in jih položi na tisto tolstino in desno stegno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 27, 'in dene vse to na roke Aronu in na roke sinom njegovim, da naj se to maje kot daritev majanja pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 28, 'In Mojzes vzame to spet ž njih rok in zapali to na oltarju, na žgalni daritvi: bila je daritev posvečevanja, v prijeten duh, ognjena daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 29, 'In Mojzes vzame prsi in jih daruje z majanjem pred Gospodom: Mojzesov delež so bile od ovna posvetitve, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 30, 'Mojzes vzame tudi mazilnega olja in krvi, ki je bila na oltarju, in poškropi Arona in njegova oblačila in njegove sinove in sinov njegovih oblačila ž njim vred; in posvetil je Arona, oblačila njegova, in sinove njegove in oblačila sinov njegovih ž njim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 31, 'In Mojzes veli Aronu in sinom njegovim: Kuhajte meso pri vratih shodnega šatora in ga tam zaužijte ter kruh, ki je v košu posvetitve, kakor sem zapovedal, rekoč: Aron in sinovi njegovi naj to zaužijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 32, 'Kar pa preostane mesa in kruha, sežgite z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 33, 'Izpred vrat shodnega šatora ne hodite sedem dni, dokler se ne dopolnijo dnevi posvečenja vašega, ker sedem dni boste posvečevani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 34, 'Kakor se je danes storilo, tako je zapovedal Gospod storiti, da se izvrši poravnava za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 35, 'In pri vhodu shodnega šatora ostanite po dnevi in po noči, sedem dni, in na straži bodite, izpolnjujoč povelja Gospodova, da ne umrjete; zakaj tako mi je ukazano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 8, 36, 'In Aron in sinovi njegovi so storili vse, kar je bil Gospod zapovedal po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 1, 'In zgodi se osmi dan, da pokliče Mojzes Arona in sinove njegove in starejšine Izraelove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 2, 'ter veli Aronu: Vzemi si mlado tele v daritev za greh in ovna v žgalno daritev, brez hibe, in ju daruj pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 3, 'In sinovom Izraelovim govóri in reci: Vzemite kozla v daritev za greh in tele ter jagnje, oboje enoletno, brezhibno, v žgalno daritev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 4, 'in vola in ovna v mirovno daritev, da darujete pred Gospodom, in jedilno daritev, zamešeno z oljem; zakaj danes se vam prikaže Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 5, 'Prinesli so torej, kar je ukazal Mojzes, pred shodni šator, in vsa občina je pristopila in se postavila pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 6, 'In Mojzes reče: To je, kar je zapovedal Gospod, da storite; in prikaže se vam slava Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 7, 'Aronu pa reče Mojzes: Pristopi k oltarju in daruj svojo daritev za greh in svojo žgalščino in izvrši poravnavo zase in za ljudstvo; daruj tudi darilo ljudstva in izvrši poravnavo zanje, kakor je bil zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 8, 'In Aron pristopi k oltarju in zakolje tele daritve za greh, ki je bila za njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 9, 'In sinovi Aronovi mu podado kri; in si omoči prst v krvi in jo dene na rogove oltarja, in ostalo kri izlije v znožje oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 10, 'Tolstino pa in ledici in jetrno pečico od daritve za greh zapali na oltarju; kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 11, 'A meso in kožo sežge z ognjem zunaj šatorišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 12, 'In zakolje žgalno žrtev; in sinovi Aronovi mu izročé kri, in razškropi jo krog po oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 13, 'Žgalno žrtev pa mu prineso po njenih kosih in glavo, in zažge jo na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 14, 'In opere drob in noge in zažge to vrhu žgalne daritve na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 15, 'In prinese darilo ljudstva, in vzame kozla daritve za greh, ki je bila za ljudstvo, in ga zakolje in daruje za greh kakor ono prvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 16, 'In prinese žgalno daritev in jo daruje po predpisu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 17, 'In prinese jedilno daritev in je vzame polno prgišče, in zažge to na oltarju zraven zjutranje žgalne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 18, 'In zakolje vola in ovna, mirovno daritev, ki je bila za ljudstvo. Sinovi Aronovi pa mu podajajo kri, ki jo razškropi krog po oltarju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 19, 'in tolstino vola in ovnov tolsti rep in kar pokriva drob in ledici ter jetrno pečico,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 20, 'in polože tolstino na prsne kose, in zažge tolstino na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 21, 'A prsne kose in desno stegno daruje Aron z majanjem pred Gospodom, kakor je zapovedal Mojzes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 22, 'Potem povzdigne Aron roko proti ljudstvu in ga blagoslovi; in ko opravi daritev za greh in žgalno in mirovno daritev, stopi doli od oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 23, 'Nato gresta Mojzes in Aron v shodni šator; in ko prideta ven, blagoslovita ljudstvo: in prikaže se slava Gospodova vsemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 9, 24, 'In ogenj pride izpred Gospoda in požre na oltarju žgalno daritev in tolstino; in vse ljudstvo, videč to, zauka veselo in popada na obličje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 1, 'Aronova sinova pa, Nadab in Abihu, vzameta vsak kadilnico svojo in deneta ognja vanjo in položita nanj kadila, in prineseta tuj ogenj pred Gospoda, česar jim ni bil zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 2, 'Zato pride ogenj izpred Gospoda in ju usmrti, in umrla sta pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 3, 'Tedaj reče Mojzes Aronu: To je, kar je govoril Gospod, rekoč: Posvečen bom v njih, ki se mi bližajo, in pred obličjem vsega ljudstva se oslavim. Aron pa molči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 4, 'In Mojzes pokliče Misaela in Elzafana, sinova Uziela, strica Aronovega, in jima veli: Pristopita, odnesita brata svoja iz svetišča ven za taborišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 5, 'Stopita torej noter in ju odneseta v njunih suknjah ven za taborišče, kakor je rekel Mojzes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 6, 'In Mojzes reče Aronu in Eleazarju in Itamarju, njegovima sinoma: Ne odkrivajte si glav in oblačil svojih ne trgajte, da ne umrjete ter da se On ne razjezi nad vso občino Izraelovo; ampak bratje vaši, vsa Izraelova hiša naj plačejo zaradi tega požara, ki ga je napravil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 7, 'In iz vrat shodnega šatora ne odhajajte, da ne umrjete, zakaj olje maziljenja Gospodovega je na vas. In storili so po besedi Mojzesovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 8, 'In Gospod je govoril Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 9, 'Vina in opojne pijače ne pij, ne ti, ne sinovi tvoji s teboj, kadar vhajate v shodni šator, da ne umrjete. Večna bodi to postava po rodovih vaših,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 10, 'da morete razpoznati, kaj je sveto in kaj nesveto, kaj je čisto in kaj nečisto,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 11, 'in da učite sinove Izraelove vse postave, katere jim je govoril Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 12, 'In Mojzes ogovori Arona in Eleazarja in Itamarja, sinova njegova, ki sta ostala: Vzemite jedilno daritev, ki je ostala od ognjenih daritev Gospodovih, in uživajte jo z opresniki pri oltarju, kajti presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 13, 'Zato jo uživajte na svetem kraju, zakaj določena je tebi in določena je sinovom tvojim od ognjenih daritev Gospodovih; kajti tako mi je ukazano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 14, 'Prsi majanja pa in stegno podviga jejte na čistem kraju, ti in sinovi tvoji in hčere tvoje s teboj; zakaj kot tebi določeno in otrokom tvojim določeno je dano to od mirovnih daritev sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 15, 'Stegno podviga in prsi majanja naj prineso z ognjenimi žrtvami tolstine vred, da se darujejo z majanjem pred Gospodom: in tvoje bodi to in sinov tvojih s teboj kot tebi določeno vekomaj, kakor je Gospod zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 16, 'Mojzes pa se skrbno ozira, kje je kozlič v daritev za greh, in glej, sežgan je bil. In razsrdi se nad Eleazarjem in Itamarjem, Aronovima sinoma, ki sta ostala živa, in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 17, 'Zakaj nista zaužila daritve za greh na svetem kraju? saj je presveta, in On vama jo je dal, da bi nosila krivico občine, da storita poravnavo zanje pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 18, 'Glejta, njena kri se ni ponesla v svetišče: morala bi jo bila torej použiti na svetem kraju, kakor sem bil zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 19, 'Aron pa odgovori Mojzesu: Glej, danes sta darovala svojo daritev za greh in svojo žgalno daritev pred Gospodom, in mene je zadela taka reč; če bi bil jedel daritev za greh danes, ali bi bilo dobro v očeh Gospodovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 10, 20, 'Ko Mojzes to sliši, se mu prav vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč jima:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 2, 'Govorita sinovom Izraelovim in recita: To so živali, ki jih smete jesti izmed vse živadi, ki je na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 3, 'Vse, kar dvoji parklje, in sicer kar ima ves parkelj razdeljen, in prežvekuje, izmed četveronožcev, smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 4, 'Samo teh ne smete jesti izmed tistih, ki prežvekujejo, in izmed tistih, ki dvojé parkelj: velbloda, ki prežvekuje, pa nima razdvojenega parklja: nečist vam bodi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 5, 'in skalnega jazbeca, ki prežvekuje, a nima razdvojenega parklja: nečist vam bodi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 6, 'in zajca, ki prežvekuje, a ne dvoji parklja: nečist vam bodi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 7, 'in svinje, ki pač dvoji parklje in to popolnoma, pa ne prežvekuje: nečista vam bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 8, 'Njih mesa ne jejte in njih mrtvih trupel se ne dotikajte, nečiste naj vam bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 9, 'Tele pa smete jesti od vseh, ki žive v vodah: karkoli ima plavute in luske v vodah, v morjih in rekah, smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 10, 'Karkoli pa nima plavut in lusk v morjih in rekah, izmed vsega, kar se giblje po vodah in kar živi v vodi, bodi vam gnusoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 11, 'Gnusne naj vam bodo: njih mesa ne jejte in njih mrline naj se vam studijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 12, 'Vse, kar nima plavut in lusk v vodah, bodi vam gnusoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 13, 'In te naj vam bodo mrzke med pticami, ne jejte jih, gnusoba so: orel in brkati ser in morski orel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 14, 'in sokol in kanja po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 15, 'in vsak gavran po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 16, 'in noj in kukavica in morski galeb in jastreb po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 17, 'in skovir in potapljač in vir,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 18, 'in sova in pelikan in mrhar,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 19, 'in štorklja in čaplja po svojih plemenih, smrdokavra in netopir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 20, 'Vsa okriljena živad, ki hodi po štirih nogah, vam bodi gnusoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 21, 'Samo to smete jesti izmed vse krilate živadi, ki hodi po štirih: kar ima stegna na zgornjem delu nog, da ž njimi skače po zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 22, 'Te smete jesti izmed nje: arbo po njenih plemenih, solhamo po njenih plemenih, hargolo po njenih plemenih in hagabo po njenih plemenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 23, 'Toda vsa druga krilata živad, ki ima štiri noge, vam bodi gnusoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 24, 'In s temi se boste onečistili; kdorkoli se dotakne njih mrhovine, bode nečist do večera;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 25, 'in kdor koli ponese kaj njih mrhovine, naj si izpere oblačila, in nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 26, 'Vsaka žival, ki dvoji parklje, pa jih nima docela razdeljenih, tudi ne prežvekuje, vam bodi nečista: vsak, kdor se je dotakne, bode nečist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 27, 'In vse, kar hodi po svojih šapah med vso zverjadjo, ki hodi po štirih, vam bodi nečisto: kdorkoli se dotakne njih mrhovine, bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 28, 'In kdor bi nosil njih mrhovino, naj si izpere oblačila, in bode nečist do večera; nečiste naj vam bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 29, 'In te naj vam bodo nečiste med živalmi, ki lazijo po zemlji: podlasica, miš in kuščarica po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 30, 'in anaka in koah in letaa in komet in kameleon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 31, 'Te naj vam bodo nečiste med vso laznino: kdorkoli se jih dotakne, ko so mrtve, bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 32, 'In na karkoli pade katerekoli izmed njih mrlina, bode nečisto: vsaka lesena posoda ali oblačilo ali koža ali vreča, kakršnosibodi orodje, s katerim se kaj dela, se mora deti v vodo, in nečisto bode do večera; potem bode čisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 33, 'In vsaka prstena posoda, v katero pade ena izmed njih: vse kar je v njej, bode nečisto, in posoda naj se razbije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 34, 'Vsaka jed, ki se jé, ako vanjo pride taka voda, bode nečista; in vsaka pijača, ki se pije, bode nečista v vsaki taki posodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 35, 'In vse, na kar pade kaj njih mrline, bode nečisto; peč in ognjišče naj se zrušita, nečisto je, in nečisto vam bodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 36, 'Toda studenci in vodnjaki, kjer se steka voda, bodo čisti; ako se pa kdo dotakne mrhovine v njih, bode nečist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 37, 'In če kaj njih mrhovine pade na seme, ki je za setev, ostane čisto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 38, 'ako se pa voda izlije na seme in pade kaj njih mrhovine nanje, nečisto vam bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 39, 'In če pogine ena izmed živali, ki so vam v živež: kdor se dotakne mrline njene, nečist bode do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 40, 'In ako bi kdo jedel od mrline njene, naj si izpere oblačila, in bode nečist do večera; in kdor ponese mrhovino njeno, naj si izpere oblačila, in bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 41, 'In sleherna laznina, ki lazi po zemlji, je gnusoba; ne smete je jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 42, 'Vse, kar se plazi po trebuhu, in vse, kar hodi po štirih, in karkoli je mnogonožno med vso laznino, ki se giblje po zemlji: ne smete tega jesti, zakaj mrzko je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 43, 'Ne ognušajte sami sebe s katero koli lazečo črvadjo in ne onečiščajte se ž njimi, da bi se s tem omadeževali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 44, 'Zakaj jaz sem Gospod, Bog vaš, zato se posvečujte in bodite sveti, ker jaz sem svet. Ne oskrunite torej sami sebe s katerokoli črvadjo, ki se giblje na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 45, 'Zakaj jaz sem Gospod, ki sem vas pripeljal iz dežele Egiptovske, da vam bodem Bog: sveti torej bodite, ker jaz sem svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 46, 'To je postava zastran živali in letečine in zastran vsake žive stvari, ki se giblje po vodah, in vsake golazni, ki lazi po zemlji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 11, 47, 'da ločite med nečistim in čistim, med živalmi, ki se uživajo, in živalmi, ki se ne smejo jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 2, 'Govóri sinovom Izraelovim in reci: Če žena spočne in porodi moško dete, nečista bodi sedem dni; nečista bode kakor v dnevih ločitve v bolezni svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 3, 'In osmi dan naj se obreže meso kožice njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 4, 'Ona pa naj še ostane triintrideset dni v krvi svojega očiščevanja; ničesar svetega naj se ne dotakne in k svetišču naj ne hodi, dokler se ne dopolnijo dnevi očiščevanja njenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 5, 'Ako pa rodi žensko dete, bodi nečista dva tedna, kakor ob mesečni ločitvi svoji; in šestinšestdeset dni naj še ostane v krvi očiščevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 6, 'Ko pa se dopolnijo dnevi očiščevanja njenega za sina ali za hčer, naj prinese enoletno jagnje v žgalno daritev ali golobiča ali grlico v daritev za greh duhovniku pred vrata shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 7, 'Ta pa naj to daruje pred Gospodom in izvrši poravnavo zanjo, in čista bode toka krvi svoje. To je postava roditeljicam pri moškem ali ženskem detetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 12, 8, 'Ako pa imetje njeno ni zadostno za ovco, naj vzame dve grlici ali dva golobiča, enega v žgalščino in drugega v daritev za greh; in duhovnik naj stori poravnavo zanjo, in čista bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 2, 'Če dobi človek na koži mesa svojega izpuščaj ali krasto ali svetlo pego, kakor da bi bilo na koži mesa njegovega znamenje gob, naj ga privedejo k Aronu, duhovniku, ali h kateremu sinov njegovih, duhovnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 3, 'Duhovnik pa ogleda boleznivo reč na koži mesa njegovega: ako se je kosmatina na boleznivem kraju pobelila in boleznivina se vidi globokejša nego koža mesa njegovega, gobava bolezen je; duhovnik ga torej pregleda in ga proglasi za nečistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 4, 'Ako pa je bela pega na koži mesa njegovega, pa se ne vidi globokejša nego koža in tudi kosmatina na njem se ni pobelila, naj zapre duhovnik za tako boleznijo bolnega sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 5, 'In sedmi dan ga ogleda duhovnik, in glej, znamenje bolezni, kakor mu kažejo oči, je ostalo, a se ni razširilo po koži: tedaj ga duhovnik zapre sedem dni v drugič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 6, 'In sedmi dan naj ga ogleda duhovnik zopet, in glej, boleznivo znamenje je otemnelo in se ni razširilo po koži: duhovnik ga torej proglasi za čistega; krasta je, in opere naj si oblačila, in bode čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 7, 'Ako pa se razširi krasta po koži, potem ko se je pokazal duhovniku v očiščenje, naj se drugič pokaže duhovniku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 8, 'in duhovnik ga ogleda, in glej, krasta se je res razširila po koži: tedaj ga duhovnik proglasi za nečistega; gobe so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 9, 'Ko je znamenje gob na človeku, naj ga privedejo k duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 10, 'In duhovnik ga ogleda, in glej, na koži ima bel izrinek, od katerega se je kosmatina pobelila, in hudo meso je zraslo na izrinku:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 11, 'stare gobe so v koži njegovega mesa, zato naj ga duhovnik proglasi za nečistega; ne zapre naj ga, ker je nečist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 12, 'Ako pa se gobe izrinejo na koži in pokrijejo vso kožo bolnikovo od glave do nog njegovih, kamor koli pogleda duhovnik;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 13, 'in duhovnik ga ogleda, in glej, gobe pokrivajo vse telo njegovo: tedaj naj proglasi bolnika za čistega; če se je povsem premenilo v belo, je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 14, 'Kadarkoli pa se prikaže hudo meso na njem, bode nečist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 15, 'In zagleda li duhovnik hudo meso, naj ga proglasi za nečistega; hudo meso je nečisto, gobe so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 16, 'Če se pa hudo meso premeni in izprevrne v belo, naj pride k duhovniku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 17, 'in duhovnik ga ogleda, in glej, znamenje bolezni se je izprevrnilo v belo: tedaj naj proglasi duhovnik njega, ki ima to nadlogo, za čistega; čist je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 18, 'In če se naredi ulje na mesu, na njegovi koži, pa se zaceli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 19, 'in na mestu uljesa je bel izrinek ali svetlordeča pega: naj se pokaže duhovniku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 20, 'in duhovnik ga ogleda, in glej, vidi se to globočje nego koža in kosmatina se je ondi pobelila: tedaj naj ga duhovnik proglasi za nečistega; bolezen gob je, v uljesu so nastale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 21, 'Ali če ga duhovnik ogleda, in glej, ni bele kosmatine na njem in ni globočje od kože, a je otemnelo, naj ga zapre duhovnik sedem dni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 22, 'in ako se razširi po koži, naj ga duhovnik proglasi za nečistega; bolezen je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 23, 'Ako pa ostane pega na svojem mestu in se ne razraste: brazgotina je po uljesu, in duhovnik naj ga proglasi za čistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 24, 'Ali pa če je spečenina na mesu, na koži njegovi, in na hudem mesu spečenine se naredi svetlordeča ali bela pega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 25, 'in duhovnik ga ogleda, in glej, kosmatina se je pobelila na pegi in pega se vidi globočja nego koža: gobe so, v spečenini so se izpustile; duhovnik naj ga torej proglasi za nečistega; gobavost je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 26, 'Če ga pa duhovnik ogleda, in glej, nobene bele kosmatine ni ob pegi ter nižja ni nego koža in je otemnela: naj ga duhovnik zapre sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 27, 'In sedmi dan naj ga ogleda duhovnik; ako se je pega razširila po koži, naj ga duhovnik proglasi za nečistega; gobavost je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 28, 'Če pa je pega ostala na svojem mestu in se ni razširila po koži, a je temna: izrinek je spečenine, in duhovnik naj ga proglasi za čistega, kajti brazgotina je po spečenini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 29, 'In ako dobi mož ali žena boleznivo znamenje na glavi ali na bradi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 30, 'naj ogleda duhovnik boleznivino: in glej, kaže se globočja od kože in je na njej žolta, tenka kosmatina, naj ga torej duhovnik proglasi za nečistega: krastovina je, gobe so na glavi ali na bradi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 31, 'Če pa duhovnik pregleda krastavo znamenje, in glej, ne kaže se globočje od kože, tudi ni črne kosmatine na njem: zapre naj ga duhovnik krastavega sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 32, 'In ko ogleda duhovnik bolezen sedmi dan, in glej, kraste se niso dalje razrasle in ni žolte kosmatine na njih in krastovina se ne kaže globočja nego koža,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 33, 'naj se človek obrije, pa krastovine ne obrije; in duhovnik naj zapre krastavega sedem dni drugič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 34, 'In sedmi dan ogleda duhovnik kraste in razvidi, da se krastovina ni razširila po koži in se ne kaže globočja od kože: tedaj naj ga duhovnik proglasi za čistega, in opere naj si oblačila, in bode čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 35, 'Ako se pa krastovina razširi po koži, potem ko je bil za čistega proglašen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 36, 'in duhovnik ga pregleda, in glej, krastovina se je razrasla po koži, ne ozira naj se po žolti kosmatini: nečist je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 37, 'Ako pa se je, kakor mu oči kažejo, krastovina ustavila in zrasla na njej črna kosmatina, so se zacelile kraste: čist je, in duhovnik naj ga proglasi za čistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 38, 'In če dobi mož ali žena maroge po koži mesa svojega, belognojne maroge,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 39, 'in duhovnik jih pregleda, in glej, po koži njih mesa so blede, belognojne maroge: izpuščaj je, ki se je izrinil na kožo; človek je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 40, 'Ako možu lasje gredo z glave, je plešec, pa je čist;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 41, 'tudi če mu lasje opolznejo s prednje strani temena, je spredaj plešast, pa je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 42, 'Ako pa je na prednji ali na zadnji plešini belordečkasto znamenje, so gobe, ki so se izpehnile na prednji ali na zadnji plešini njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 43, 'In duhovnik ga ogleda, in glej, izrastek boleznivega znamenja je belordečkast na njegovi prednji ali zadnji pleši in se vidi kakor gobe na koži mesa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 44, 'tedaj je mož gobavec: nečist je, in duhovnik naj ga odločno proglasi za nečistega; bolezen svojo ima na glavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 45, 'Zastran gobavca pa, ki ima bolezen: oblačila naj ima natrgana in glavo razkrito in ustnice naj si pokriva ter vpije: Nečist, nečist!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 46, 'Vse dni, dokler ima bolezen, naj ga štejejo za nečistega; nečist je, sam naj prebiva, zunaj šatorišča bodi njegov stan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 47, 'In če se pojavi znamenje gob na obleki, bodisi volnata ali platnena obleka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 48, 'naj bo na osnutku ali na votku, platnenem ali volnatem, ali na koži, ali na kakršnikoli kožuhovini:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 49, 'če je znamenje zelenkasto ali rdečkasto na obleki ali na koži, ali na osnutku ali na votku, ali na kakršnikoli pripravi iz kože, tedaj je znamenje gob, in naj se pokaže duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 50, 'In duhovnik naj ogleda znamenje in zapre tisto, na čemer je znamenje, sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 51, 'In če zazna sedmi dan, da se je znamenje razširilo po obleki, ali po osnutku ali po votku, ali po koži, pri čemerkoli se rabi koža: znamenje to so razjedljive gobe; nečisto je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 52, 'Sežge naj se torej obleka, ali osnutek ali votek, volnat ali platnen, ali katerakoli priprava iz kože, ki je na njej znamenje to; zakaj razjedljive gobe so: mora se sežgati z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 53, 'Ako pa to duhovnik pregleda, in glej, znamenje se ni razširilo po obleki, ali po osnutku ali po votku, ali na kakršnikoli pripravi iz kože,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 54, 'naj zapove, da se opere tisto, na čemer je tako znamenje; potem naj zapre to sedem dni drugič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 55, 'In duhovnik ogleda znamenje, potem ko se je opralo, in glej, znamenje ni premenilo svoje podobe, čeprav se ni razširilo: nečisto je, z ognjem naj se sežge; razjedljiva stvar je na robu ali na licu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 56, 'In če to duhovnik ogleda, in glej, znamenje je obledelo po pranju, naj je odtrga od obleke, ali od kože, ali od osnutka ali od votka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 57, 'Ako se pa bo še videlo na obleki, ali na osnutku ali na votku, ali na čemerkoli iz kože: gobe so, ki se vnovič izpuščajo; z ognjem sežgi, na čemer je znamenje to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 58, 'Obleka pa, ali osnutek ali votek, ali katerakoli priprava iz kože, ki jo izpereš, in znamenje izgine: drugič se mora oprati, in potem je čista.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 13, 59, 'To je postava zastran znamenja gob na obleki, volnati ali platneni, ali na osnutku ali na votku, ali na katerikoli pripravi iz kože, kako naj se proglasi za čisto ali nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 2, 'To bodi postava gobavcu na dan očiščenja njegovega: Pripeljejo naj ga k duhovniku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 3, 'duhovnik pa naj pride ven iz šatorišča in ga ogleda, in glej, boleznivo znamenje gob je zaceljeno na gobavcu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 4, 'ukaži torej duhovnik, da naj vzamejo za njega, ki ima biti očiščen, dve živi, čisti ptici in cedrovega lesa in karmezina in izopa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 5, 'In ukaži duhovnik, naj zakoljejo eno teh ptic v prsteno posodo nad tekočo vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 6, 'Živo ptico pa vzame in cedrovino in karmezin in izop in omoči vse v krvi nad živo vodo zaklane ptice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 7, 'in poškropi naj sedemkrat njega, ki želi biti očiščen gob, in ga proglasi za čistega; potem spusti živo ptico, da zleti na plano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 8, 'Tisti pa, ki se očiščuje, naj si opere oblačila in si obrije vso kosmatino in se izkoplje v vodi, in je čist. In potem sme priti v šatorišče, ostane pa naj zunaj šatora svojega sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 9, 'In sedmi dan naj si obrije vso kosmatino, glavo ter brado in obrvi; da, vse lase naj si obrije in opere oblačila in telo si izkoplje v vodi; in je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 10, 'Osmi dan pa naj vzame dve jagnjeti, brez madeža, in ovco enoletno, brez hibe, in tri desetinke bele moke v jedilno daritev, pomešane z oljem, in log olja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 11, 'Duhovnik pa, ki ga očiščuje, naj postavi moža, ki ima biti očiščen, z vsem tem pred Gospoda, pri vratih shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 12, 'In duhovnik vzemi eno jagnje in ga daruj v daritev za krivdo in log olja, in majaj oboje kot daritev majanja pred Gospodom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 13, 'in zakolje naj jagnje na kraju, kjer se koljejo daritve za greh in žgalščine, na svetem kraju; zakaj kakor daritev za greh je duhovniku odmenjena tudi daritev za krivdo: presveta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 14, 'In vzame naj duhovnik krvi daritve za krivdo ter jo deni na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 15, 'In vzame naj duhovnik nekoliko od loga olja in si ga vlije na levo roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 16, 'in omoči naj desni prst svoj v olju, ki je na levi dlani njegovi, in s prstom naj škropi olje sedemkrat pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 17, 'Od ostanka olja pa, ki je na dlani njegovi, naj dene duhovnik na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove, vrh krvi daritve za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 18, 'Ostanek olja pa, ki je na roki duhovnikovi, naj dene očiščevancu na glavo; in tako naj izvrši duhovnik poravnavo zanj pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 19, 'In naj opravi duhovnik daritev za greh in stori poravnavo za očiščevanca zaradi nečistote njegove, in potem naj zakolje žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 20, 'Žgalno pa in jedilno daritev naj daruje duhovnik na oltarju ter izvrši poravnavo zanj, in bode čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 21, 'Ako je pa ubožen in toliko ne premore, naj vzame eno jagnje v dar za krivdo, v daritev majanja, da se stori poravnava zanj, in desetinko bele moke, oblite z oljem, v jedilno daritev, in log olja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 22, 'in dve grlici ali dva golobiča, kakršna si lahko priskrbi, in eden bodi v daritev za greh in drugi v žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 23, 'In naj to prinese osmi dan po očiščenju svojem k duhovniku, k vratom shodnega šatora, pred Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 24, 'Duhovnik pa vzemi jagnje, ki je v daritev za krivdo, in log olja, in daruj oboje kot daritev majanja pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 25, 'In zakolje naj jagnje v daritev za krivdo in vzame krvi daritve za krivdo ter jo deni na desno ušesno mečico očiščevanca in na desni palec roke in na desni palec noge njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 26, 'Od olja pa naj si vlije duhovnik na levo roko;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 27, 'in z desnim prstom svojim naj poškropi duhovnik olja, ki je na levi roki njegovi, sedemkrat pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 28, 'In naj dene duhovnik olja, ki ga ima na dlani, na desno ušesno mečico očiščevancu in na desni palec roke in na desni palec noge njegove, tja, kjer je kri daritve za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 29, 'Ostanek olja pa, ki je na dlani duhovnikovi, naj dene očiščevancu na glavo, da stori poravnavo zanj pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 30, 'In naj daruje eno izmed grlic ali golobičev, kakršna si lahko priskrbi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 31, 'taka, kakršna priskrbi, enega za greh in drugega v žgalno daritev, z jedilno daritvijo vred, in tako naj stori duhovnik poravnavo za očiščevanca pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 32, 'To je postava za njega, ki je gobav, čigar imetje ni zadostno pri očiščevanju njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 33, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 34, 'Ko pridete v deželo Kanaansko, ki vam jo jaz dam v posest, pa pošljem nadlogo gob nad katero hišo v deželi lastnine vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 35, 'tedaj naj pride tisti, čigar je hiša, in naznani duhovniku, rekoč: Kaže se mi, kakor da bi bilo znamenje gob na hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 36, 'Nato zapove duhovnik, da naj izpraznijo hišo, preden pride ogledovat znamenje, da bi ne postalo nečisto vse, kar je v hiši; in potem naj vstopi duhovnik, da ogleda hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 37, 'In ko pogleda znamenje, in glej, znamenje je na hišnih stenah, zelenkaste ali rdečkaste jamice, ki so se zajedle globoko v steno:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 38, 'tedaj naj gre duhovnik ven iz hiše k hišnim vratom in zapre hišo za sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 39, 'In ko pride zopet osmi dan in pogleda, in glej, znamenje se je razlezlo po steni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 40, 'tedaj zapovej duhovnik, naj izdero kamene, na katerih je tisto znamenje, in jih pomečejo za mesto na nečist kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 41, 'Hišo pa naj odznotraj vso ostrgajo in ostržke izsujejo za mesto na nečist kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 42, 'In druge kamene naj vzamejo in jih denejo namesto onih kamenov, in z drugim ilom naj omažejo hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 43, 'Ako se pa znamenje zopet pojavi in se izrine po hiši, potem ko so izdrli one kamene in potem ko so hišo ostrgali in omazali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 44, 'in duhovnik pride in vidi, da se je znamenje razširilo po hiši: razjedljive gobe so na hiši, nečista je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 45, 'Razrušijo naj hišo, kamene in les in ves omaz njen, in vse naj spravijo ven za mesto na nečist kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 46, 'In kdor bo vstopil v hišo, dokler bo zaprta, nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 47, 'In kdor bi spal v hiši, naj si izpere oblačila, in kdor bi jedel v hiši, naj si opere oblačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 48, 'Ko pa pride duhovnik in pogleda, in glej, znamenje se ni razširilo po hiši, potem ko so jo vnovič omazali: naj proglasi hišo za čisto, kajti znamenje se je izcelilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 49, 'In vzame naj, da očisti hišo greha, dve ptici in cedrovega lesa in karmezina in izopa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 50, 'In zakolji eno ptico v prsteno posodo nad tekočo vodo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 51, 'in vzemi cedrovino in izop in karmezin in živo ptico, in omóči vse v krvi zaklane ptice in v tekoči vodi, in poškrópi hišo sedemkrat;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 52, 'in tako naj hišo očisti greha s krvjo ptice in s tekočo vodo in z živo ptico in s cedrovino in z izopom in s karmezinom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 53, 'nato spústi živo ptico, da zleti ven iz mesta na plano. Tako naj izvrši poravnavo za hišo, in čista bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 54, 'To je postava za vsakršno gobavo nadlogo in za garje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 55, 'in za gobe na obleki in na hiši');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 56, 'in za izpuščaj in za kraste in za svetle pege:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 14, 57, 'v poučilo, kdaj je kaj nečisto in kdaj je kaj čisto. To je postava o gobah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 2, 'Govorita sinovom Izraelovim in jim recita: Če ima mož sluzotok iz mesa svojega, nečist je zaradi toka svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 3, 'In to bodi nečistost njegova pri toku njegovem: pušča li meso njegovo tok, da se cedi, ali pa se zapre meso njegovo pred tokom, v nečistost si štej to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 4, 'Vsako ležišče, na katerem leži, kdor ima tok, bodi nečisto, in na čimerkoli sedi, bodi nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 5, 'In kdor se dotakne ležišča njegovega, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 6, 'In kdor sede, kjer je sedel on, ki ima tok, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 7, 'In kdor se dotakne mesa tistega, ki ima tok, naj si opere oblačila in se izkoplje v vodi, in bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 8, 'In če tisti, ki ima tok, pljune na čistega, ta naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 9, 'Tudi vsako sedlo, na katerem jezdi, kdor ima tok, bode nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 10, 'In kdor koli se dotakne česa, kar je bilo pod njim, nečist bode do večera; in kdor nese tisto, naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 11, 'Vsakdo, ki se ga dotakne tisti, ki ima tok, ne da bi si prej roke umil, naj opere oblačila svoja in se izkoplje v vodi, in nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 12, 'Vsaka prstena posoda, ki se je dotakne tisti, ki ima tok, naj se razbije, lesena pa naj se pomije z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 13, 'Kadar pa bode tisti, ki ima tok, čist svojega toka, naj šteje sedem dni od svoje očistitve in si opere oblačila in izkoplje meso svoje v tekoči vodi, in bode čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 14, 'Osmi dan pa naj si vzame dve grlici ali dva golobiča in pride pred Gospoda k vratom shodnega šatora in ju izroči duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 15, 'In duhovnik ju daruj, eno v daritev za greh in eno v žgalno daritev, in stóri poravnavo zanj pred Gospodom zaradi toka njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 16, 'In če možu uide seme združenja, naj si izkoplje vse telo v vodi, in bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 17, 'In vsaka obleka in vsaka koža, na katero pride seme združenja, naj se opere z vodo, in nečista bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 18, 'In če bo z ženo ležal mož z iztokom semena, naj se izkopljeta v vodi, in bodeta nečista do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 19, 'In ko ima žena tok, in njen tok na mesu njenem je kri, naj bode sedem dni ločena; in kdorkoli se je dotakne, bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 20, 'In vse, na čemer leži ob ločitvi svoji, bode nečisto, in na čemerkoli sedi, bo nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 21, 'In vsak, ki se dotakne ležišča njenega, naj si opere oblačila in se izkoplje v vodi, in nečist bode do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 22, 'In kdor koli se dotakne česa, na čemer je sedela, naj si opere oblačila in se izkoplje v vodi, in bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 23, 'In če je kaj na ležišču ali na opravi, na kateri je sedela, kdor se tega dotakne, bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 24, 'In ako bi mož ležal ž njo in nečistota njena pride nanj, nečist bode sedem dni; in vsako ležišče, na katerem leži, bode nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 25, 'In ako ima žena krvotok mnogo dni zunaj časa ločitve svoje, ali če ima tok čez čas ločitve svoje: kolikorkoli dni traja tok nečistote njene, naj bode kakor v dnevih ločitve svoje: nečista je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 26, 'Vsako ležišče, na katerem leži v dnevih toka svojega, naj ji bode kakor ležišče ločitve njene, in vsaka oprava, na kateri sedi, bodi nečista kakor nečistota ločitve njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 27, 'In kdorkoli se teh reči dotakne, bode nečist, in naj si opere oblačila in se izkoplje v vodi, in nečist bodi do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 28, 'In kadar bode čista toka svojega, naj si šteje sedem dni, in potem bodi čista.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 29, 'In osmi dan naj vzame zase dve grlici ali dva golobiča in ju prinese duhovniku k vratom shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 30, 'In duhovnik daruj eno v daritev za greh, drugo pa v žgalno daritev. In tako naj stori duhovnik poravnavo zanjo pred Gospodom zaradi toka nečistosti njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 31, 'Tako učite sinove Izraelove, da se ločijo od nečistosti svoje, da ne umrjo v nečistosti svoji, oskrunivši šator moj, ki je sredi njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 32, 'To je postava za tistega, ki ima tok in ki mu seme uhaja, da se onečisti s tem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 15, 33, 'in za tisto, ki je bolna ob ločitvi, in za tiste, ki imajo tok, bodisi mož ali žena, in za moža, ki leži z nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 1, 'In Gospod je govoril Mojzesu po smrti onih dveh sinov Aronovih, ko sta se bližala Gospodu in sta umrla;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 2, 'in rekel je Gospod Mojzesu: Véli Aronu, bratu svojemu, da naj ne hodi vsakteri čas v svetišče za zagrinjalo pred pokrov sprave, ki je na skrinji, da ne umrje; zakaj v oblaku se bom prikazoval nad pokrovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 3, 'S tem pa naj prihaja Aron v svetišče: z mladim juncem v daritev za greh in z ovnom v žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 4, 'Sveto platneno suknjo naj obleče in platnene hlače naj ima ob nagoti svoji in s platnenim pasom naj se opaše in s platnenim pokrivalom pokrije: to so sveta oblačila; ko si izkoplje telo v vodi, naj jih obleče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 5, 'In od občine sinov Izraelovih naj vzame dva kozla v daritev za greh in enega ovna v žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 6, 'In Aron pripelji v daritev za greh junca, ki je za njega, da izvrši poravnavo za sebe in za hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 7, 'Potem naj vzame tista dva kozla in ju postavi pred Gospodom pri vhodu shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 8, 'In Aron naj vrže žreba za tista dva kozla, en žreb za Gospoda in en žreb za azazel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 9, 'In Aron naj pripelje kozla, ki ga je zadel žreb za Gospoda, in ga daruje v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 10, 'Kozla pa, ki ga je zadel žreb za azazel, naj postavijo živega pred Gospoda, da se stori poravnava nad njim in se pošlje za azazel v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 11, 'Aron torej naj privede v daritev za greh junca, ki je za njega, in naj izvrši poravnavo za sebe in hišo svojo ter zakolje najprej junca v daritev za greh za sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 12, 'In vzame naj kadilnico polno žerjavice z oltarja, ki je pred Gospodom, in obe prgišči polni blagodišečega kadila, na drobno stolčenega, in nese to noter za zagrinjalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 13, 'In naj položi kadilo na ogenj pred Gospodom, da oblak iz kadila pokrije pokrov sprave, ki je vrhu pričevanja, da ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 14, 'Potem naj vzame junčeve krvi in poškropi s prstom sprednjo stran pokrova proti vzhodu; pred pokrovom pa naj poškropi s tisto krvjo sedemkrat s prstom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 15, 'Nato naj zakolje kozla v daritev za greh, ki je za ljudstvo, in nese kri njegovo noter za zagrinjalo ter stori s to krvjo, kakor je storil z junčevo krvjo, in razškropi naj jo na pokrov in pred pokrov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 16, 'in tako naj izvrši poravnavo za svetišče zaradi nečistot sinov Izraelovih in zaradi njih prestopkov po vseh njih grehih; in enako naj stori za shodni šator, ki biva med njimi sredi njih nečistot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 17, 'Nobenega človeka ne sme biti v shodnem šatoru, kadar gre noter, da stori poravnavo v svetišču, dokler ne pride iz njega. In tako naj izvrši spravo za sebe in za hišo svojo in za ves zbor Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 18, 'In pride naj ven k oltarju, ki je pred Gospodom, in stori poravnavo zanj; in vzame naj krvi junčeve in krvi kozlove ter pomaže ž njo rogove na oltarju kroginkrog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 19, 'in ga poškropi s krvjo s prstom svojim sedemkrat ter ga očisti in posveti od nečistot sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 20, 'In ko dokonča spravo svetišča in shodnega šatora in oltarja, naj pripelje živega kozla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 21, 'In Aron naj položi obe roki svoji živemu kozlu na glavo in pripoznaj nad njim vse krivice sinov Izraelovih in vse njih prestopke po vseh njih grehih; in položi naj jih na glavo kozlu ter ga pošlje po pripravljenem možu v puščavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 22, 'da odnese kozel na sebi vse njih krivice v pusto deželo; zato naj ga odžene v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 23, 'Potem naj stopi Aron v shodni šator in sleče platnena oblačila, ki jih je bil oblekel, ko je šel v svetišče, in naj jih ondi pusti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 24, 'in naj si izkoplje telo v vodi na svetem kraju ter obleče oblačila svoja in pride ven in daruje žgalno daritev svojo in žgalno daritev ljudstva in stori poravnavo za sebe in za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 25, 'In naj zažge tolstino daritve za greh na oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 26, 'In tisti, ki odžene kozla za azazel, naj si opere oblačila in izkoplje telo v vodi; in potem sme priti v taborišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 27, 'A junca in kozla, ki sta bila v daritev za greh, katerih kri je bil Aron nesel za poravnavo v svetišče, naj odneso ven za taborišče, in njiju kožo, meso in blato naj sežgo z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 28, 'In kdor ju sežge, naj si opere oblačila in se izkoplje v vodi; in potem sme priti v taborišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 29, 'In to vam bodi večna postava: Deseti dan sedmega meseca pokorite duše svoje in nobenega dela ne opravljajte, ne domačin, ne tujec, ki biva med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 30, 'Zakaj ta dan se izvrši sprava za vas, da boste očiščeni; vseh grehov svojih bodete čisti pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 31, 'Sobota prazničnega počitka vam bodi ta dan, in pokorite duše svoje; večna postava je to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 32, 'Spravo pa naj izvrši duhovnik, ki je bil maziljen in posvečen v duhovnika namesto očeta svojega, in naj obleče platnena oblačila, ki so sveta oblačila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 33, 'in stori poravnavo za sveto svetišče in za shodni šator, tudi za oltar naj stori poravnavo, tudi za duhovnike in za vse ljudstvo občine naj izvrši poravnavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 16, 34, 'In to vam bodi večna postava: za sinove Izraelove je storiti spravo zavoljo vseh njih grehov, enkrat v letu. In storil je, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 2, 'Govóri Aronu in sinom njegovim in vsem sinovom Izraelovim ter jim reci: To je, kar je zapovedal Gospod, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 3, 'Vsakdo iz hiše Izraelove, ki zakolje vola ali ovco ali kozo v taborišču ali pa zunaj taborišča');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 4, 'ter jih ne prinese k vratom shodnega šatora, da jih daruje kot darilo pred bivališčem Gospodovim: kri se všteje tistemu možu, kri je prelil, in izrebljen bodi tisti mož izmed svojega ljudstva;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 5, 'zato da prinašajo sinovi Izraelovi klalščine svoje, ki jih darujejo na planem, da jih, pravim, prinašajo Gospodu k vratom shodnega šatora, k duhovniku, in jih koljejo kot mirovne daritve Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 6, 'In razškropi naj duhovnik kri na oltar Gospodov pri vhodu shodnega šatora in zažge tolstino v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 7, 'In naj ne darujejo klalščin svojih kozlom-malikom, za katerimi hodijo v nečistovanju. Večna postava jim to bodi po njih prihodnjih rodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 8, 'Zato jim véli: Vsak iz hiše Izraelove in izmed tujcev, ki gostujejo med vami, kdor daruje žgalno ali klalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 9, 'pa je ne prinese k vratom shodnega šatora, da bi jo daroval Gospodu: tisti mož bodi iztrebljen izmed ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 10, 'In vsakdo iz hiše Izraelove in izmed tujcev, ki gostujejo med vami, kdor uživa kakršnokoli kri: obličje obrnem zoper tistega, ki jé kri, in ga iztrebim izmed ljudstva njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 11, 'Zakaj duša mesa je v krvi, in jaz sem vam jo dal na oltar, da se ž njo izvrši sprava za duše vaše; kri je namreč, ki spravlja po duši v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 12, 'Zato sem rekel sinovom Izraelovim: Nobena duša izmed vas ne jej krvi, tudi noben tujec, ki biva med vami, ne jej krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 13, 'In vsakdo iz hiše Izraelove in izmed tujcev, ki bivajo med vami, ako ulovi kako zverino ali ptico, ki se sme jesti, ta naj izpusti njeno kri in jo pokrije s prstjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 14, 'Zakaj duša vsakega mesa je njega kri, združena z dušo njegovo; zato sem rekel sinovom Izraelovim: Krvi kateregakoli mesa ne smete jesti, kajti duša vsakega mesa je kri njegova; kdorkoli jo užije, bodi iztrebljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 15, 'In vsaka duša, ki bi jedla mrlino ali raztrgano od zveri, bodisi domačin ali tujec, ta naj si opere oblačila in se izkoplje v vodi, in bode nečist do večera; potem je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 17, 16, 'Ako jih pa ne izpere in mesa svojega ne izkoplje, bo nosil krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 2, 'Govóri sinovom Izraelovim in jim reci: Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 3, 'Ne delajte, kar delajo v deželi Egiptovski, ki ste v njej prebivali, niti ne počenjajte, kar uganjajo v deželi Kanaanski, v katero vas vodim, in po njih postavah nikar ne živite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 4, 'Moje sodbe izpolnjujte in moje postave spoštujte, da po njih živite. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 5, 'Pazite torej na moje postave in moje sodbe, po katerih bo človek, izpolnjujoč jih, živel. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 6, 'Noben človek naj se ne približa komurkoli iz sorodništva svojega, da bi odgrnil sramoto. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 7, 'Sramote očeta svojega in sramote matere svoje ne odgrni; mati tvoja je, sramote njene ne smeš odkriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 8, 'Sramote žene očeta svojega ne odgrni, sramota je očeta tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 9, 'Sramote sestre svoje, hčere očeta svojega ali hčere matere svoje, bodisi doma ali zunaj rojena, sramote njene ne odgrni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 10, 'Sramote hčerke sina svojega ali hčerke hčere svoje, sramote njene ne odgrni; kajti tvoja sramota je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 11, 'Sramota hčere od žene očeta tvojega, rojene od očeta tvojega, – sestra tvoja je, njene sramote ne odgrni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 12, 'Sramote sestre očeta svojega ne odgrni, sorodnica je očeta tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 13, 'Sramote sestre matere svoje ne odgrni, ker sorodnica je matere tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 14, 'Sramote brata očeta svojega ne odgrni, ženi njegovi se ne približaj, žena je strica tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 15, 'Sramote snahe svoje ne odgrni: žena je sinu tvojega, njene sramote ne odkrij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 16, 'Sramote žene brata svojega ne odgrni, sramota je brata tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 17, 'Sramote žene in hčere njene ne odkrij, hčerke sinú njenega in hčerke njene hčere si ne vzemi, da bi odkrival njiju sramoto: sorodnici sta; krvosramstvo je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 18, 'Sestre žene svoje si ne vzemi, da bi v njej zbujal ljubosumnost, odkrivaje nje sramoto zraven te, dokler živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 19, 'In ne približaj se ženi, da odgrneš sramoto njeno, dokler je ločena zaradi nesnage svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 20, 'Z ženo bližnjega svojega ne lezi v združenje, da bi se ž njo oskrunil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 21, 'In iz zaroda svojega ne daj, da bi kdo šel čez ogenj Molohu, in imena Gospoda, Boga svojega, ne onečasti. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 22, 'Z moškim se ne druži, kakor se je družiti z ženo: grdoba je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 23, 'Z nobeno živino se ne pečaj, da bi se ž njo oskrunil; tudi ženska naj ne stopi pred nobeno živino, da bi se pečala ž njo: grda oskrumba je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 24, 'Ne oskrunite se z nobeno teh reči, zakaj s temi vsemi so se oskrunjali pogani, ki jih preženem pred vami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 25, 'tudi dežela se je oskrunila, zato hočem kaznovati njene krivice na njej, in dežela izbljuje prebivalce svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 26, 'Vi torej izpolnjujte postave moje in sodbe moje in ne delajte nobene teh grdob, ne domačin, ne tujec, ki biva med vami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 27, '(zakaj vse te grdobe je uganjalo ljudstvo te dežele, ki je bilo pred vami, in dežela je bila oskrunjena;)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 28, 'da bi tudi vas dežela ne izbljuvala, ker ste jo oskrunili, kakor je izbljuvala narod, ki je bil pred vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 29, 'Zakaj kdorkoli stori katero teh grdobij, vse duše, ki to delajo, bodo iztrebljene izmed svojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 18, 30, 'Na straži torej bodite, da izpolnjujete povelja moja ter ne počenjate nobene tistih grdih navad, ki so jim stregli pred vami, in da se s tem ne oskrunite. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 2, 'Govóri vsej občini sinov Izraelovih in jim véli: Sveti bodite, zakaj jaz Gospod, Bog vaš, sem svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 3, 'Vsak se boj matere svoje in očeta svojega, in sobote moje praznujte. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 4, 'Ne obračajte se k ničevim malikom, tudi si ne delajte ulitih bogov: jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 5, 'In ko darujete mirovno daritev Gospodu, darujte tako, da boste milo sprejeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 6, 'Použije naj se tisti dan, kadar jo darujete, in drugi dan; če pa kaj preostane do tretjega dne, z ognjem naj se sežge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 7, 'Ako bi se pa kako zaužilo tretji dan, gnusoba je, ne bo milo sprejeto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 8, 'a kdorkoli bi to jedel, bo nosil krivico svojo, ker je onesvetil svetinjo Gospodovo, in ta duša bo iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 9, 'In ko boste želi žetev zemlje svoje, ne požanji docela obmejkov njive svoje, tudi ne pobiraj ob žetvi popuščenega klasja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 10, 'In v vinogradu svojem ne paberkuj ter raztresenih jagod ne pobiraj; pusti jih siromaku in tujcu. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 11, 'Ne kradite, tudi ne lažite in zvijačno ne ravnajte drug z drugim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 12, 'In ne prisegajte lažnivo pri mojem imenu, da bi onečastili ime Boga svojega. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 13, 'Ne opehari bližnjega svojega in ga ne oropaj. Plačilo najemniku tvojemu naj ne ostane pri tebi do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 14, 'Glušca ne preklinjaj in slepcu ne stavi spotikljaja, temuč boj se Boga svojega. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 15, 'V pravdi ne ravnajte krivično; ne oziraj se na osebo ubožčevo, tudi ne čislaj osebe mogočnikove, marveč s pravičnostjo sodi bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 16, 'Ne pohajaj kot opravljivec med ljudstvom svojim, in v krvavo sodbo ne spravi bližnjega svojega. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 17, 'Brata svojega ne sovraži v srcu svojem; resno posvari bližnjega svojega, da ne boš nosil greha zaradi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 18, 'Ne maščuj se, tudi se ne spominjaj krivega zoper otroke ljudstva svojega, ampak ljubi bližnjega svojega kakor samega sebe. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 19, 'Postave moje ohranite. Živini svoje ne puščaj pojati se z živino drugega plemena; njive svoje ne obsevaj z dvoje vrste semenom, in oblačil, stkanih iz dvoje preje, ne oblači.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 20, 'In kdor bi se telesno združil z žensko, ki je dekla, možu zaročena, pa nikakor ni odkupljena in tudi ne oproščena: naj se jima prisodi kazen; ne bodita umorjena, ker ona ni bila prosta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 21, 'On pa naj prinese daritev za krivdo Gospodu k vratom shodnega šatora, ovna v daritev za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 22, 'In duhovnik naj stori poravnavo z ovnom daritve za krivdo pred Gospodom za greh njegov, ki ga je zakrivil; in odpuščen mu bo greh, s katerim se je pregrešil. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 23, 'In ko pridete v deželo in zasadite vsake vrste drevesa v živež, prvo njih sadje štejte kot neobrezo; tri leta naj vam bodo kakor neobrezana, ne jejte od njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 24, 'a v četrtem letu bodi vse njih sadje sveto, v zahvalo Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 25, 'v petem letu pa jejte njih sad, da bi se vam pomnožil njih pridelek. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 26, 'Ničesar ne jejte s krvjo. Ne pečajte se z vedeževanjem, ne s čaranjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 27, 'Ne strizite si na okroglo las na glavi in ne grdite si brade ob kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 28, 'In zaradi mrtveca si ne delajte zarez v meso in nobenih znamenj si ne vžigajte. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 29, 'Ne onečasti hčere svoje, dopuščajoč, da je nečistnica, da ne bi se dežela vdala nečistovanju in se napolnila nesramnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 30, 'Sobote moje praznujte in svetišče moje spoštujte. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 31, 'Ne obračajte se k rotilcem mrtvih, ne k vražarjem, ne iščite jih, da bi se po njih oskrunili. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 32, 'Pred sivo glavo vstani in spoštuj obličje starčkovo, in boj se Boga svojega. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 33, 'In ako gostuje tujec pri tebi v deželi vaši, ga ne smete dreti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 34, 'kakor vaš rojak vam bodi tujec, ki biva med vami, in ljubi ga kakor samega sebe; saj ste tudi bili tujci v deželi Egiptovski. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 35, 'Ne delajte nič krivičnega v sodbi, pri dolgostni meri, pri tehtnici in votli meri;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 36, 'pravična tehtnica, poštene uteži, poštena efa in pošten hin bodi pri vas. Jaz sem Gospod, Bog vaš, ki sem vas peljal iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 19, 37, 'Pazite torej na vse postave moje in vse sodbe moje ter jih izpolnjujte. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 2, 'Še véli sinovom Izraelovim: Kdorkoli bodi izmed sinov Izraelovih in izmed tujcev, ki gostujejo v Izraelu, ki da iz semena svojega Molohu, mora umreti; ljudstvo domače naj ga posuje s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 3, 'Tudi jaz hočem obrniti obličje svoje zoper takega človeka in ga iztrebiti izmed ljudstva njegovega, zato ker je dal iz semena svojega Molohu, da bi onečastil svetišče moje ter onesvetil ime svetosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 4, 'In če domače ljudstvo zatisne kako oči pred takim človekom, ko je dal iz semena svojega Molohu, da ga ne usmrtijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 5, 'tedaj obrnem jaz obličje svoje zoper tega človeka in zoper rodovino njegovo ter iztrebim izmed njih ljudstva njega in vse, ki gredo v nečistosti za njim, da bi nečistovali z Molohom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 6, 'Tudi zoper dušo, ki se obrača k rotilcem mrtvih in k vražarjem, da bi šla v nečistosti za njimi, zoper tako dušo obrnem obličje svoje in ga iztrebim izmed ljudstva njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 7, 'Zatorej se posvečujte in bodite sveti, ker jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 8, 'In pazite na moje postave ter jih izpolnjujte; jaz sem Gospod, ki vas posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 9, 'Vsakdo, ki preklinja očeta svojega ali mater svojo, mora umreti; svojega očeta in svojo mater je klel, kri njegova bodi nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 10, 'In ako kateri mož prešeštvuje z ženo drugega moža, ako prešeštvuje z ženo bližnjega svojega, prešeštnik in prešeštnica morata umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 11, 'In mož, ki leži z ženo očeta svojega, je odkril sramoto očeta svojega: obadva morata umreti; njiju kri bode nad njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 12, 'In ako kdo leži s snaho svojo, oba morata umreti: grdo oskrumbo sta storila; njiju kri bode nad njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 13, 'In ako kdo leži z moškim, kakor se leži z žensko, oba sta storila grdobnost: morata umreti; njiju kri bode nad njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 14, 'In če si kdo vzame ženo in njeno mater, protinaturnost je: z ognjem naj se sežgo, on in oni, da ne bode protinaturnosti med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 15, 'In ako kdo leži z živino, mora umreti, tudi živino usmrtite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 16, 'In ako bi se žena približala živini, da bi se ž njo pečala, usmrti ženo in živino: morata umreti, njiju kri bode nad njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 17, 'In ako kdo vzame sestro svojo, očeta svojega hčer ali matere svoje hčer, in gleda njeno sramoto in ona gleda sramoto njegovo: rodoskrumba je, in iztrebljena bodita pred očmi otrok naroda svojega; on je odkril sramoto sestre svoje, naj nosi krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 18, 'In če mož leži z ženo v bolezni njeni in odgrne sramoto njeno, je razgalil njen tok in ona je odkrila tok krvi svoje; oba bodita iztrebljena izmed svojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 19, 'In ne odgrni sramote sestri matere svoje in sestri očeta svojega; zakaj tak odkriva nagoto sorodnice svoje: krivico svojo bosta nosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 20, 'In če kdo leži s svojega strica ženo, je odgrnil sramoto strica svojega: nosila bosta krivico svojo, umrjeta brez otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 21, 'In ako kdo vzame brata svojega ženo, nečistost je; odkril je sramoto brata svojega; brez otrok bodeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 22, 'Pazite torej na vse postave moje in na vse sodbe moje ter jih izpolnjujte, da vas ne izbljuje dežela, v katero vas vodim, da boste v njej prebivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 23, 'In ne živite po navadah poganskega naroda, ki ga ženem izpred vas; kajti vse to so počenjali in s tem so se mi pristudili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 24, 'A vam sem rekel: Vi podedujte njih deželo, ker vam jo hočem dati, da jo posedete, deželo, ki v njej teče mleko in med. Jaz sem Gospod, Bog vaš, ki sem vas ločil od drugih ljudstev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 25, 'Ločite torej tudi vi med čisto živino in nečisto in med nečistimi pticami in čistimi, da se ne oskrunite z živino ali letečino ali s čimerkoli, kar lazi po zemlji, kar sem izločil, da naj štejete za nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 26, 'In sveti bodite meni, ker svet sem jaz Gospod, in sem vas ločil izmed ljudstev, da bi bili moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 20, 27, 'Tudi če ima mož ali žena duha, ki se peča z rotenjem mrtvih ali vražarstvom, morata umreti: s kamenjem naj ju posujejo; njiju kri bode nad njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 1, 'In Gospod reče Mojzesu: Govóri duhovnikom, sinovom Aronovim, ter jim véli: Pri mrliču naj se nihče izmed vas ne oskruni med ljudstvom svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 2, 'samo pri bližjih sorodnikih svojih, pri materi in pri očetu, pri sinu in pri hčeri, pri bratu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 3, 'in pri sestri, devici, ki biva pri njem, ko se še ni omožila: pri teh se sme onečistiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 4, 'Ne oskruni se naj, ker je gospod med svojim ljudstvom, da bi se onesvetil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 5, 'Ne strižejo naj si pleše na glavi in ne brijejo ob kraju brade svoje, in na telesu naj si ne delajo nobenih zarez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 6, 'Sveti naj bodo Bogu svojemu in naj ne onesvetijo imena Boga svojega, zakaj ognjene daritve Gospodove, kruh Boga svojega, darujejo; zato naj bodo sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 7, 'Nečistnice in posiljene deve naj si ne jemljejo, tudi ne take, katero je njen mož odpahnil; zakaj duhovnik je svet Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 8, 'Zatorej ga štej za svetega, kajti daruje kruh Boga tvojega; svet ti bodi, ker jaz sem svet, Gospod, ki vas posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 9, 'Hči duhovnikova pa, ki se onesveti z nečistovanjem, onesveti očeta svojega: z ognjem bodi sežgana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 10, 'Tisti pa, ki je veliki duhovnik med brati svojimi, na čigar glavo je bilo izlito olje maziljenja in ki je bil posvečen, da se oblači v sveta oblačila: naj si ne razkriva glave ter ne trga oblačil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 11, 'tudi naj ne hodi k truplu mrtvemu, niti pri očetu svojem ali pri materi svoji naj se ne onečisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 12, 'In iz svetišča naj ven ne hodi, tudi ne onesveti svetišča Boga svojega, zakaj posvetitev mazilnega olja Boga svojega ima na sebi. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 13, 'In ženo naj si vzame v devištvu njenem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 14, 'Vdove in ločene ženske in posiljene, nečistnice, teh naj ne vzame, ampak devico iz ljudstva svojega naj vzame za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 15, 'In semena svojega naj ne onesveti med ljudstvom svojim, zakaj jaz sem Gospod, ki ga posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 16, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 17, 'Govóri Aronu in reci: Kdorkoli iz semena tvojega po prihodnjih rodovih ima telesno hibo na sebi, naj ne pristopa darovat kruha Boga svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 18, 'kajti nihče, na komer je telesna hiba, ne sme pristopiti: slepec ali hromec, ali kdor ima ploščat nos ali katerikoli ud prevelik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 19, 'ali mož, ki ima zlomljeno nogo ali zlomljeno roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 20, 'ali kdor je grbav ali pritlikav, ali kdor ima madež v očesu, ali kdor ima garje ali lišaj ali stlačen modnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 21, 'Nihče iz semena Arona duhovnika, ki ima kako hibo, naj ne pristopa darovat ognjene daritve Gospodove; hiba je na njem, ne sme pristopiti, da daruje kruh Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 22, 'Kruh Boga svojega sme uživati, od presvetega in od svetega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 23, 'samo za zagrinjalo naj ne hodi in k oltarju naj ne pristopa, ker ima hibo, da ne onesveti svetišč mojih: zakaj jaz sem Gospod, ki jih posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 21, 24, 'In Mojzes je tako govoril Aronu in sinovom njegovim in vsem sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 2, 'Véli Aronu in sinom njegovim, da naj zdržljivo rabijo svete reči, ki jih sinovi Izraelovi meni posvečujejo, in svetega imena mojega naj ne onečaščajo: jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 3, 'Reci jim: Kdorkoli iz semena vašega po vseh prihodnjih rodovih vaših se približa svetim rečem, ki jih sinovi Izraelovi posvečujejo Gospodu, ko ima nečistoto svojo na sebi, ta duša bodi iztrebljena izpred obličja mojega. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 4, 'Vsak iz semena Aronovega, ki je gobav ali ima tok, naj ne uživa svetih reči, dokler ni čist. In kdor se dotakne česarkoli, kar je nečisto od mrtveca, ali njega, ki ima semenotok,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 5, 'ali kdor se dotakne katere golazni, ki onečiščuje, ali človeka, od katerega lahko naleze nečistoto, kakršnakoli bodi nečistota njegova:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 6, 'tisti, ki se takega dotakne, nečist bode do večera; in ne uživa naj svetih reči, temuč izkoplji telo svoje v vodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 7, 'In ko zajde solnce, bode čist, in potem sme jesti od svete reči, ker to mu je v živež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 8, 'Mrline in raztrganega živinčeta ne jej nihče, da bi se s tem ognusil. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 9, 'Pazijo naj torej, da izpolnijo povelja moja, da si ne nakopljejo greha ter vsled tega umrjo, ker so oskrunili sveto. Jaz sem Gospod, ki jih posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 10, 'Noben tujec naj ne jé svetih reči; gostač in najemnik duhovnikov ne smeta jesti svetega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 11, 'Ako pa duhovnik kupi koga za denar, ta sme jesti od tega; in kateri so rojeni v hiši njegovi, naj uživajo kruh njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 12, 'In če se duhovnikova hči omoži s tujcem, ne sme jesti od podviga svetih reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 13, 'Ako je pa duhovnikova hči ovdovela ali se ločila in nima otrok, pa se vrne v hišo očeta svojega in tu biva kakor v mladosti svoji, sme jesti kruh očeta svojega; ali noben tujec naj ne jé od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 14, 'Kdor bi pa jedel sveto ponevedoma, naj pridene peti del k temu in povrne duhovniku tisto sveto reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 15, 'Nikar naj duhovniki ne oskrunijo svetih reči, ki jih sinovi Izraelovi poklanjajo Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 16, 'da jih ne obremene s krivico krivde, ko uživajo njih svete reči; zakaj jaz sem Gospod, ki jih posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 17, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 18, 'Govori Aronu in sinom njegovim in vsem sinom Izraelovim ter jim reci: Kdorkoli iz hiše Izraelove in izmed tujcev v Izraelu prinese darilo svoje, bodisi kaj obljubljenega ali kaj prostovoljnega, kar prinašajo Gospodu v žgalno daritev:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 19, 'da bi bili milo sprejeti, darujte brezhibnega samca, od govedi, od ovac ali koz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 20, 'Ničesar takega, na čemer je hiba, ne darujte, ker ne bo blagovoljno sprejeto za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 21, 'In če kdo prinese mirovno daritev Gospodu, da izpolni posebno obljubo, ali kot prostovoljno darilo, od govedi ali drobnice: bodi popolno, da bi bilo milo sprejeto, nobene hibe naj ne bo na tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 22, 'Slepo ali polomljeno ali pohabljeno ali kozavo ali garjavo ali krastavo: teh ne prinašajte Gospodu in teh ne devajte v ognjeno daritev na oltar za Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 23, 'Govedo ali ovco, ki ima predolg ali prekratek kak ud, smeš darovati kot prostovoljen dar, ali kot izpolnitev obljube ne bo milo sprejeto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 24, 'Ujalovljenega s stisnjenjem ali zmečkanjem ali odtrganjem ali skopljenjem ne darujte Gospodu, in kaj takega ne delajte v svoji deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 25, 'Tudi iz tujčeve roke ne darujte nič takega kot kruh Boga svojega; zakaj pokvara, hiba je na tem, ne bo milo sprejeto za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 26, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 27, 'Ko se stori tele, ovca ali koza, naj ostane sedem dni pri materi svoji, od osmega dne pa in poslej bode ugodno za darilo v ognjeno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 28, 'Bodisi pa krava ali ovca, nje in njenega mladiča ne koljite isti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 29, 'In ko darujete zahvalno daritev Gospodu, darujte jo tako, da boste milo sprejeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 30, 'Tisti dan jo zaužijte, nič je ne pustite do jutra; jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 31, 'Pazite torej na moje zapovedi in jih izpolnjujte. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 32, 'In ne onesvečujte imena svetosti moje, da bom posvečen med sinovi Izraelovimi. Jaz sem Gospod, ki vas posvečujem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 22, 33, 'ki sem vas odpeljal iz dežele Egiptovske, da bi vam bil Bog. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 2, 'Govori sinom Izraelovim in jim reci: Prazniki Gospodovi, ki jih razglasite za sveta zborovanja, le-ti so prazniki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 3, 'Šest dni naj se opravlja delo, a sedmi dan je sobota prazničnega počitka, sveto zborovanje; nobenega posla ne opravljajte: počitek je Gospodu po vseh prebivališčih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 4, 'To so prazniki Gospodovi, sveta zborovanja, ki jih razglasíte v njih določenih časih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 5, 'Prvi mesec, štirinajsti dan meseca proti večeru, je pasha Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 6, 'In petnajsti dan tega meseca je praznik opresnih kruhov Gospodu: sedem dni jejte opresnine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 7, 'Prvi dan imejte sveto zborovanje; nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 8, 'In sedem dni darujte ognjene daritve Gospodu; sedmi dan je sveto zborovanje, nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 9, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 10, 'Govóri sinovom Izraelovim in jim véli: Ko pridete v deželo, ki vam jo jaz dam, in boste želi letino njeno, prinesite prvi snop žetve svoje k duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 11, 'In on majaj snop pred Gospodom, da bo milo sprejet za vas; zjutraj po soboti naj ga maja duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 12, 'Tisti dan pa, ko darujete snop z majanjem, prinesite brezhibno enoletno jagnje v žgalno daritev Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 13, 'in ž njo vred jedilno daritev: dve desetinki bele moke, pomešane z oljem, kot ognjeno daritev Gospodu v prijeten duh; in ž njo vred pitno daritev: vina, četrtino hina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 14, 'A kruha in opraženega zrnja in svežega žita ne jejte prav do tistega dne, ko prinesete darilo Bogu svojemu: večna postava je to za prihodnje rodove vaše po vseh prebivališčih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 15, 'Potem štejte od prvega dne po soboti, od dneva, ko ste prinesli snop v dar majanja, sedem celih tednov naj bode;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 16, 'do jutra po sedmi soboti štejte petdeset dni, in tedaj darujte novo jedilno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 17, 'Iz prebivališč svojih prinesite dva hleba za majanje, iz dveh desetink bele moke, pečena s kvasom, kot prvine Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 18, 'In s kruhom vred prinesite sedem brezhibnih, enoletnih jagnjet in mladega junca in dva ovna, ki naj bodo v žgalno daritev Gospodu, in obenem jedilno in pitno daritev, ki k njim gre: ognjena žrtev bodi v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 19, 'In darujte kozla v daritev za greh in dve enoletni jagnjeti v mirovno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 20, 'In majaj jih duhovnik s kruhom prvin kot daritev majanja pred Gospodom z dvema jagnjetoma vred: sveti naj bodo Gospodu v prid duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 21, 'In razglasite istega dne: Sveto zborovanje vam bodi, nobenega službenega dela ne opravljajte! Večna postava bode to po vseh prebivališčih vaših od roda do roda. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 22, 'In ko žanjete letino dežele svoje, ne požanji docela obmejkov njive svoje in ne pobiraj ob žetvi popuščenega klasja: pusti jih ubožcu in tujcu. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 23, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 24, 'Govóri sinom Izraelovim in reci: Prvi dan sedmega meseca vam bodi slavnosten počitek, spomin s trobentanjem, sveto zborovanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 25, 'Nikakršnega službenega posla ne opravljajte in darujte ognjeno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 26, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 27, 'Ali deseti dan tega sedmega meseca je slavnostni dan sprave: sveto zborovanje imejte in pokoríte duše svoje ter darujte ognjeno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 28, 'Nobenega dela ne opravljajte tisti dan, zakaj slavnostni dan sprave je, da se izvrši poravnava za vas pred Gospodom, Bogom vašim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 29, 'Kajti vsaka duša, ki se ne pokori tisti dan, bodi iztrebljena izmed ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 30, 'In vsako dušo, ki bi opravljala kakršnokoli delo tisti dan, hočem pogubiti izmed njenega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 31, 'Nobenega dela ne opravljajte: večna je to postava za prihodnje rodove vaše po vseh prebivališčih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 32, 'Sobota prazničnega počitka vam bodi, in pokorite duše svoje, na večer devetega dne meseca, od večera do večera praznujte soboto svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 33, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 34, 'Govóri sinom Izraelovim in reci: Petnajsti dan tega sedmega meseca je praznik šatorov sedem dni Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 35, 'Prvi dan bodi sveto zborovanje, nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 36, 'Sedem dni darujte ognjeno daritev Gospodu, osmi dan imejte sveto zborovanje in darujte ognjeno daritev Gospodu; slovesno zborovanje je, nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 37, 'To so prazniki Gospodovi, ki jih razglasite za sveta zborovanja, da se daruje ognjena daritev Gospodu, žgalna in jedilna, klalna in pitna daritev, kolikor je za vsak dan določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 38, 'razen sobot Gospodovih in razen drugih daril vaših in razen vseh vaših obljub in razen vseh prostovoljnih daritev, ki jih dajete Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 39, 'Ali petnajsti dan sedmega meseca, ko boste spravili pridelke zemlje, obhajajte praznik Gospodov sedem dni; prvi dan bodi prazničen počitek in osmi dan bodi prazničen počitek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 40, 'In prvi dan si vzemite sadja žlahtnih dreves in palmovih mladik in vej z listnatih dreves in vrbja od potoka, in veselite se pred Gospodom, Bogom svojim, sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 41, 'In obhajajte to kot praznik Gospodu sedem dni v letu: večna to je postava za prihodnje rodove vaše; v sedmem mesecu praznujte to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 42, 'In prebivali boste v šatorih iz zelenja sedem dni; vsak, kdor se je rodil v Izraelu, naj prebiva v šatorih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 43, 'da bi vedeli prihodnji rodovi vaši, da sem dal sinovom Izraelovim prebivati v šatorih, ko sem jih vodil iz dežele Egiptovske. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 23, 44, 'In naznanil je Mojzes praznike Gospodove sinovom Izralovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 2, 'Ukaži sinovom Izraelovim, naj ti prineso čistega, iztolčenega oljkovega olja za svetilo, da bi gorele svetilnice neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 3, 'Zunaj zagrinjala, ki visi pred pričevanjem, v shodnem šatoru naj jih postavlja Aron, da svetijo od večera do jutra pred Gospodom neprestano: večna to bodi postava za prihodnje rodove vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 4, 'Na čistem svečniku naj razpostavlja svetilnice pred Gospodom neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 5, 'In vzemi bele moke in speci iz nje dvanajst hlebov; iz dveh desetink bodi vsak hleb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 6, 'In polóži jih v dve vrsti, po šest na vrsto, na čisto mizo pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 7, 'In vrh vsake vrste deni čistega kadila, ki bodi kruhov spomin, ognjena daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 8, 'Vsako soboto naj jih razvršča duhovnik pred Gospodom neprestano; od strani sinov Izraelovih je to večna zaveza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 9, 'In naj bodo Aronovi in sinov njegovih, da jih jedo na svetem kraju; zakaj to je presveto njemu od ognjenih daritev Gospodovih po večni določbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 10, 'In pride sin izraelske žene, čigar oče pa je bil Egipčan, med sinove Izraelove, in spreta se v taborišču sin izraelske žene in neki Izraelec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 11, 'In sin izraelske žene zasramuje ime Božje in preklinja. Pa ga pripeljejo k Mojzesu. In materi njegovi je bilo ime Šelomita, hči Dibrijeva, iz Danovega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 12, 'In ga denejo v zapor, dokler ne prejmejo odgovora, kaj veli Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 13, 'Tedaj ogovori Gospod Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 14, 'Izpelji tistega preklinjalca ven iz taborišča, in vsi, ki so ga slišali, naj mu položé roke svoje na glavo, in naj ga vsa občina posuje s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 15, 'Sinom Izraelovim pa sporóči, govoreč: Kdorkoli preklinja Boga svojega, bo nosil greh svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 16, 'In kdor zasramuje ime Gospodovo, mora umreti; brez ugovora naj ga vsa občina omeče s kamenjem: tujca in rojaka, ko zasramuje to ime, naj usmrte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 17, 'In kdor ubije kateregakoli človeka, mora umreti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 18, 'kdor pa ubije katero živino, jo mora povrniti: življenje za življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 19, 'In kdor povzroči poškodbo bližnjemu svojemu, naj se mu stori, kakor je storil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 20, 'rano za rano, oko za oko, zob za zob; kakor je prizadel poškodbo človeku, tako naj se mu povrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 21, 'Kdor torej ubije živino, naj se pobota, kdor pa ubije človeka, naj umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 22, 'Ista sodba bodi pri vas za tujca in za rojaka; zakaj jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 24, 23, 'In Mojzes sporoči to sinovom Izraelovim. In izpeljejo tistega, ki je preklinjal, ven iz šatorišča ter ga posujejo s kamenjem. In storili so sinovi Izraelovi, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 1, 'In Gospod je govoril Mojzesu na gori Sinaju, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 2, 'Govori sinovom Izraelovim ter jim reci: Ko pridete v deželo, ki vam jo jaz dam, naj praznuje dežela soboto Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 3, 'Šest let obsevaj njivo svojo in šest let obrezuj vinograd svoj in spravljaj sadove njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 4, 'ali sedmo leto naj dobi dežela soboto prazničnega počitka, čas počitka Gospodu: njive svoje ne obsevaj in vinograda svojega ne obrezuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 5, 'Kar ti samo od sebe zraste po zadnji žetvi, ne žanji, in grozdja neobrezane trte svoje ne spravljaj: leto prazničnega počitka naj bode zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 6, 'In sobotni obrodek dežele vam bodi v jed, tebi in hlapcu tvojemu in dekli tvoji, in najemniku tvojemu in tujcu, ki biva pri tebi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 7, 'tudi živini tvoji in zverini, ki je v tvoji deželi, bodi v živež ves njen obrodek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 8, 'Dalje si štej sedmero sobotnih let, sedem let sedemkrat, da ti bode dni sedmerih sobotnih let devetinštirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 9, 'In daj glasno trobentati deseti dan sedmega meseca; na dan sprave naj se razlega trobenta po vsej deželi vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 10, 'In posvetite petdeseto leto in razglasite svobodo po deželi vsem prebivalcem njenim; leto veselega trobentanja vam bodi, ko naj se vsakdo vrne k lastnini svoji in vsakdo zopet pride k rodovini svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 11, 'Leto veselega trobentanja vam bodi tisto petdeseto: ne sejte in ne žanjite tega, kar samo v njem zraste, in grozdja neobrezanih trt ne trgajte v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 12, 'Zakaj leto veselega trobentanja je, sveto vam bodi; kar obrodi, uživajte kar ž njive.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 13, 'V tem milostnem letu naj vsakdo zopet posede lastnino svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 14, 'In če kaj prodaste bližnjemu ali kaj kupite od bližnjega svojega, ne smete drug drugega opehariti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 15, 'Po številu let od milostnega leta kupi od bližnjega svojega in po število letin naj ti proda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 16, 'Čim več bode let, tem večja bodi kupnina, in čim manj let, tem manjša bodi; kajti število žetev se prodaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 17, 'Zato naj nihče ne opehari bližnjega svojega, temuč boj se Boga svojega; zakaj jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 18, 'Izpolnjujte torej moje postave in pazite na moje pravice in ravnajte po njih, in brezskrbno boste prebivali v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 19, 'In zemlja bo rodila sad svoj, in jedli boste dositega in prebivali v njej brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 20, 'Če pa porečete: Kaj bomo jedli sedmo leto? glej, ne bomo sejali, ne spravljali pridelkov svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 21, 'Zapovem, da vam pride blagoslov moj v šestem letu, in obrodi pridelkov za tri leta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 22, 'in boste sejali v osmem letu in jedli stare pridelke do devetega leta; dokler ne dozore njegovi pridelki, boste jedli starino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 23, 'In zemlja naj se ne prodaja za vselej, zakaj moja je zemlja, ker vi ste tujci in priseljenci pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 24, 'Zato dovolite po vsej deželi posestva svojega, da se zemlja odkupi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 25, 'Ako obuboža brat tvoj in proda kaj posesti svoje, naj pride odkupitelj njegov, njemu najbližji sorodnik, in odkupi prodani del brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 26, 'Ako bi pa komu ne bilo odkupitelja, pa si sam opomore in pridobi, kolikor je treba v odkup:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 27, 'naj šteje, na koliko let je prodal, in ostala leta poplačaj njemu, komur je prodal, in tako naj zopet dobi posest svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 28, 'Ako pa ne premore toliko, kolikor bi moral povrniti, naj ostane njegova prodana stvar kupcu v rokah do milostnega leta; in v milostnem letu se stvar oprosti, in on dobi zopet posest svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 29, 'Ako kdo proda hišo v mestu z obzidjem, naj jo sme odkupiti do konca leta, v katerem jo je prodal; celo leto imej pravico do odkupa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 30, 'Če je pa ne odkupi, ko preteče celo leto, naj ostane hiša v mestu z obzidjem v lasti njemu, ki jo je kupil, za prihodnje rodove; ne more se rešiti v milostnem letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 31, 'Toda hiše v vaseh, ki nimajo obzidja, naj se prištevajo njivam na deželi: smejo se odkupiti in v milostnem letu naj bodo proste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 32, 'Kar se pa tiče mest levitov, hiš v mestih njih posesti, vselej ostani levitom pravica do odkupa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 33, 'In če kdo izmed levitov ne odkupi, v milostnem letu naj mu zopet pripade hiša, ki je bila prodana v mestu posesti njegove; kajti hiše v levitskih mestih so njih posestvo med sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 34, 'Tudi polje v okolici njih mest se ne sme prodajati, ker jim je to večna posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 35, 'In ako brat tvoj poleg tebe obuboža in mu roka opeša, podpiraj ga, kakor tujec in naselnik naj živi pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 36, 'Ne jemlji od njega zakupnine in obresti, temuč boj se Boga svojega, da živi brat tvoj pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 37, 'Denarja svojega mu ne dajaj na obresti in hrane svoje ne zaradi dobička.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 38, 'Jaz sem Gospod, Bog vaš, ki sem vas peljal iz dežele Egiptovske, da bi vam dal deželo Kanaansko, da bi vam bil za Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 39, 'In ako brat tvoj obuboža poleg tebe in se ti proda, ne sili ga, naj ti služi za sužnja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 40, 'kakor najemnik in kakor naselnik bodi pri tebi, do milostnega leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 41, 'Tedaj naj odide prost od tebe, on in otroci njegovi ž njim, in se vrne zopet k rodovini svoji in zopet dobi posest očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 42, 'Zakaj moji hlapci so, ki sem jih peljal iz dežele Egiptovske: ne smeš jih prodajati kakor sužnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 43, 'Ne bodi mu neusmiljen gospodar, temuč boj se svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 44, 'In kar se tiče sužnjev in sužnic, ki jih boš imel: izmed narodov, ki bodo okoli vas, smete kupovati sužnje in sužnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 45, 'Tudi od priseljencev, ki bivajo pri vas, jih smete kupovati, in od njih rodovine, ki so jo rodili v deželi vaši, in bodo naj lastnina vaša;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 46, 'ne smete jih zapustiti kot dediščino otrokom svojim za sabo, da jim bodo v lastnino. Ti naj vam hlapčujejo za vselej; ali bratom svojim, sinovom Izraelovim, brat svojemu bratu, ne smete neusmiljeno gospodovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 47, 'Ako pa obogati tujec ali priseljenec pri tebi, in brat tvoj obuboža poleg njega in se proda tujcu, priseljencu pri tebi, ali pa komu iz zaroda tujčevega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 48, 'naj mu ostane pravica do odkupa, eden bratov njegovih naj ga odkupi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 49, 'ali stric njegov ali stričev sin, ali kdorkoli mu je bližnji iz rodbine njegove, naj ga odreši; ali pa če si opomore, naj se sam odkupi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 50, 'In naj računi s kupcem svojim od leta, ko se mu je prodal, do milostnega leta, in prodajna cena naj se odmeri po številu let; kakor najemniku naj se mu štejejo dnevi, kolikor jih je odslužil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 51, 'Če je še dosti let, njim primerno naj poplača za odkup od denarja, s katerim je bil kupljen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 52, 'in če ostaja malo let do milostnega leta, naj mu zaračuni to: proti letom naj poplača ceno odrešitve svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 53, 'Kakor najemnik leto za letom naj bode pri njem; oni mu ne bodi neusmiljen gospodar, tebi pred očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 54, 'In ako ne bo odkupljen na ta način, naj odide prost v milostnem letu, on in otroci njegovi ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 25, 55, 'Meni namreč so hlapci sinovi Izraelovi, moji hlapci so, ki sem jih peljal iz dežele Egiptovske. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 1, 'Ne delajte si malikov, tudi si ne postavljajte rezanih podob ali kipov in ne poslikanih kamenov v deželi svoji, da bi pred njimi molili; zakaj jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 2, 'Sobote moje praznujte in svetišče moje spoštujte. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 3, 'Ako boste živeli po postavah mojih in hranili zapovedi moje ter jih izpolnjevali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 4, 'vam bom dajal dež o pravem času, in zemlja bo rodila sad svoj in drevje na polju sadje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 5, 'In mlatitev vam bo trajala do trgatve in trgatev bo trajala do setve, in jedli boste kruh svoj dositega in brez skrbi prebivali v deželi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 6, 'In dam mir po deželi vaši, da boste spali in ne bo nikogar, ki bi vas strašil; in storim, da izginejo hude zverine iz pokrajine vaše, in meč ne pojde čez deželo vašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 7, 'In podili boste sovražnike svoje, in padali bodo pred vami od meča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 8, 'pet izmed vas jih bo podilo sto, in sto vaših jih bo podilo deset tisoč, in padali bodo pred vami pod mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 9, 'Oziral se bom na vas in storim vas rodovitne ter vas razmnožim in vzdržim zavezo svojo z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 10, 'In jedli boste stare pridelke, dolgo shranjene, in stare na stran devali pred novimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 11, 'In postavim prebivališče svoje sredi vas, in duša moja vas ne bo mrzila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 12, 'In izprehajal se bom med vami, in bodem vam Bog, vi pa bodete ljudstvo moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 13, 'Jaz sem Gospod, Bog vaš, ki sem vas odpeljal iz dežele Egipčanov, da jim ne bodete sužnji; in zlomil sem spone jarma vašega ter vas vzravnal, da hodite pokoncu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 14, 'Ako pa me ne boste poslušali in ne boste izpolnjevali vseh teh zapovedi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 15, 'nego boste zaničevali postave moje in duša vaša bo mrzila sodbe moje, tako da ne boste izpolnjevali vseh zapovedi mojih, temuč v nič devali zavezo mojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 16, 'hočem tudi jaz to storiti vam: izročim vas v oblast strahu, sušici in vročici, ki povzročajo, da ugasnejo oči in gine duša; in zaman boste sejali seme svoje, ker sovražniki vaši ga použijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 17, 'In obrnem obličje svoje zoper vas, da boste poraženi pred sovražniki svojimi, in sovražilci vaši vam bodo gospodovali, in bežali boste, ne da bi vas kdo podil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 18, 'Če me pa po vsem tem še ne boste poslušali, vas hočem sedemkrat bolj kaznovati za grehe vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 19, 'in potrem vaše moči prevzetnost in storim, da vam bode nebo kakor železo in zemlja kakor bron;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 20, 'in moči svoje boste trošili brezuspešno, in zemlja vam ne bo dajala pridelkov svojih in drevje v deželi ne prinašalo sadja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 21, 'In če mi boste na zoper živeli, ne hoteč me poslušati, pridenem sedemkrat več udarcev po grehih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 22, 'In pošljem nad vas poljske zveri, da vam ugrabijo otroke ter vam požro črede in zmanjšajo število vaše, in ceste vaše postanejo puste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 23, 'In če se po takem še ne boste popravili meni pogodi in mi boste na zoper živeli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 24, 'hočem tudi jaz vam nasprotovati in vas udarim tudi jaz sedemkrat za grehe vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 25, 'In pošljem nad vas meč, ki bode maščevalec zaveze moje; in ko se zberete v mestih svojih, pošljem kugo med vas, da boste izdani sovražniku v pest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 26, 'Ko strem podporo kruha vašega, vam bo deset žen peklo kruh v eni peči in vam ga bodo oddajale na tehtnico, in jedli boste, pa se ne nasitite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 27, 'In če me po vsem tem ne boste poslušali in mi še na zoper živeli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 28, 'vam hočem tudi jaz nasprotovati v togoti, in kaznoval vas bom sedemkrat za grehe vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 29, 'In jedli boste meso sinov svojih in hčer svojih meso boste uživali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 30, 'In zatreti hočem višave vaše in uničiti solnčne stebre vaše, in vržem mrtva trupla vaša na trupla grdih malikov vaših, in duša moja vas bo mrzila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 31, 'In porušim mesta vaša ter opustošim svetišča vaša, in ne bom maral duhati prijetnih dišav vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 32, 'In opustošim deželo vašo, da bodo strmeli nad njo sovražniki vaši, prebivajoči v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 33, 'Vas pa hočem razkropiti med narode in potegniti meč za vami, in dežela vaša bode pusta in mesta vaša postanejo samote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 34, 'Tedaj se naužije zemlja sobot svojih; vse dni opustošenja svojega, dokler bodete v deželi sovražnikov svojih, bo počivala zemlja in bo poravnala sobote svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 35, 'vse dni opustošenja svojega bo imela počitek, počitek, ki ga ni imela ob sobotnih letih vaših, ko ste prebivali v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 36, 'In kolikor jih izmed vas preostane, v njih srca denem plašljivost v pokrajinah njih sovražnikov, da jih plaši šumenje letečega listja ter bodo bežali kakor pred mečem in padali, dasi jih nihče ne podi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 37, 'in spotikali se bodo drug ob drugega, bežeč kakor pred mečem, ne da bi jih kdo podil; in ne boste si upali stati pred sovražniki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 38, 'In poginete med poganskimi narodi in dežela sovražnikov vaših vas požre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 39, 'In kar vas preostane, bodo sahnili v krivici svoji v pokrajinah sovražnikov vaših, in tudi v krivicah očetov svojih bodo sahnili ž njimi vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 40, 'In pripoznali bodo krivico svojo in krivico očetov svojih po nezvestobi, ki so jo zakrivili proti meni, pa tudi, ker so mi na zoper živeli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 41, 'da sem i jaz jim nasprotoval in jih odpeljal v njih sovražnikov deželo. Ako se tedaj poniža njih neobrezano srce in bo tedaj dosti kaznjena njih krivda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 42, 'spomnim se zaveze svoje z Jakobom, pa tudi zaveze svoje z Izakom in zaveze svoje z Abrahamom se spomnim, in dežele se spomnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 43, 'Zakaj dežela bo zapuščena od njih in bo uživala sobote svoje, ležeč pusta in daleč od njih; in dosti bo kaznjena njih krivda zato, prav zato, ker so zametali sodbe moje in so se njih duši gnusile postave moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 44, 'A tudi še takrat, ko bodo v deželi sovražnikov svojih, jih ne zavržem in se mi ne bodo pristudili, da bi jih celo pokončal in uničil zavezo ž njimi; zakaj jaz sem Gospod, njih Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 45, 'Spomnim se torej njim v prid zaveze svoje s predniki, ki sem jih peljal iz dežele Egiptovske pred očmi poganov, da naj bi jim bil Bog. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 26, 46, 'To so postave moje in sodbe in ukazi, ki jih je postavil Gospod med seboj in sinovi Izraelovimi na gori Sinaju po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 2, 'Govori sinovom Izraelovim in jim reci: Če kdo stori obljubo, po cenitvi tvoji naj bodo osebe Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 3, 'Bode pa cenitev tvoja za moškega od dvajsetega leta do šestdesetega leta: petdeset seklov srebra, po seklu svetišča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 4, 'ako je pa ženska, bodi cenitev tvoja trideset seklov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 5, 'in če je od petih let do dvajsetih let, bodi cenitev tvoja za moškega dvajset seklov in za žensko deset seklov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 6, 'in če je v starosti od enega meseca do petih let, bodi cenitev tvoja za moškega pet seklov srebra in za žensko tri sekle srebra;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 7, 'in če je šestdeset let in čez, moškega spola, bodi cenitev tvoja petnajst seklov, za žensko pa deset seklov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 8, 'Ako pa je ubožen za cenitev tvojo, naj ga postavijo pred duhovnika, da ga duhovnik oceni: po razmerju s tem, kar si obljubnik prisluži, naj ga duhovnik oceni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 9, 'Ako pa je živina, od katere se prinaša v darilo Gospodu, karkoli takega hoče kdo dati Gospodu, naj bode sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 10, 'Nikar naj tega ne premeni ali ne zameni, dobro za slabo ali slabo za dobro; če pa se kako zameni živina za drugo, bodi ona in njena zamena sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 11, 'Ako pa je katerakoli nečistih živali, od katerih se ne prinaša v darilo Gospodu, naj se postavi tista žival pred duhovnika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 12, 'in duhovnik naj jo oceni, je li dobra ali slaba; po tvoji cenitvi, duhovnik, naj velja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 13, 'Ako pa jo kdo hoče odkupiti, naj pridene peti del nad cenitev tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 14, 'In če kdo posveti hišo svojo, da bodi sveta Gospodu, naj jo oceni duhovnik, ali je dobra ali slaba; kakor jo oceni duhovnik, tako bodi določeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 15, 'In ako hoče hišo odkupiti tisti, ki jo je posvetil, naj pridene peti del denarja cenitve tvoje povrh, in hiša bodi njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 16, 'In če kdo posveti kaj polja posesti svoje Gospodu, bodi cenitev tvoja po tem, kolikor je ondi posevka: setev homera ječmena po petdeset seklov srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 17, 'Ako v začetku milostnega leta posveti njivo svojo, bodi določeno po cenitvi tvoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 18, 'ako pa jo po milostnem letu posveti, naj mu duhovnik računi denar po številu let, kar jih je še do milostnega leta, in naj se odšteje od cenitve tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 19, 'Ako pa hoče njivo tisti, ki jo je posvetil, odkupiti, naj pridene peti del denarja cenitve tvoje povrh, in njiva naj mu ostane;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 20, 'ako pa ne odkupi njive ali če jo proda drugemu možu, se ne more več odkupiti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 21, 'in njiva ta, ko bo v milostnem letu oproščena, bodi sveta Gospodu, kakor njiva posvečena: duhovniku naj pripade v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 22, 'Ako pa posveti Gospodu njivo, ki jo je kupil, ki ni od dednega polja njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 23, 'naj mu duhovnik računi znesek cenitve tvoje do milostnega leta, in on naj da, kolikor cene ti določiš, tisti dan kot sveto Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 24, 'V milostnem letu naj se povrne njiva spet tistemu, od kogar je bila kupljena, ki mu tudi gre kot posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 25, 'In vsaka cenitev tvoja bodi po seklu svetišča: dvajset ger imej sekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 26, 'Samo prvenca živine, ki se kot prvina daje Gospodu, naj nihče ne posvečuje: bodisi govedo ali drobnica, Gospodovo je že.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 27, 'Ako pa je od nečiste živine, naj se odkupi po cenitvi tvoji in se pridene peti del povrh; in če se ne odkupi, naj to prodado po cenitvi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 28, 'Ali vsaka posvečena reč, ki bi jo kdo z zaroto posvetil Gospodu od vsega, kar je njegovega, bodisi iz ljudi ali iz živine ali ž njive posesti njegove, se ne sme prodati in ne odkupiti; karkoli je z zaroto posvečenega, presveto je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 29, 'Vse posvečeno, kar se izmed ljudi z zaroto posveti, se ne sme odkupiti: mora se usmrtiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 30, 'In vse desetine zemlje, od semena njive in od sadja dreves, so Gospodove: sveto je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 31, 'Ako pa kdo hoče odkupiti kaj svojih desetin, naj pridene tega peti del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 32, 'In vse desetine od govedi in drobnice, od vsega, kar hodi pod pastirjevo palico, deseto bodi sveto Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 33, 'ni treba gledati, je li dobro ali slabo, tudi naj se ne zamenja; in če se vendarle zameni, bodi tisto sveto in zamena njegova sveta: ne sme se odkupiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (3, 27, 34, 'To so zapovedi, ki jih je Gospod zapovedal Mojzesu za sinove Izraelove na gori Sinaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 1, 'In Gospod je govoril Mojzesu v puščavi Sinajski, v shodnem šatoru, prvi dan drugega meseca, drugo leto potem, ko so bili šli iz dežele Egiptovske, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 2, 'Poizvedita število vse občine sinov Izraelovih, po njih rodovinah, po hišah njih zarodnikov, po številu imen, vse moške, od glave do glave;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 3, 'od dvajsetih let in više, vse, ki morejo na vojsko iti v Izraelu, seštejta jih po njih trumah ti in Aron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 4, 'In pri vaju bodi mož iz vsakega rodu, ki je glava hiši očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 5, 'In ta so imena mož, ki naj stoje pri vaju: iz Rubena: Elizur, sin Šedeurjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 6, 'iz Simeona: Šelumiel, sin Zurišadajev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 7, 'iz Jude: Nahson, sin Aminadabov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 8, 'iz Isaharja: Netanel, sin Zuarjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 9, 'iz Zebulona: Eliab, sin Helonov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 10, 'iz sinov Jožefovih: iz Efraima Elišama, sin Amihudov; iz Manaseja, Gamaliel, sin Pedazurjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 11, 'iz Benjamina: Abidan, sin Gideonijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 12, 'iz Dana: Ahiezer, sin Amišadajev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 13, 'iz Aserja: Pagiel, sin Okranov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 14, 'iz Gada: Eliasaf, sin Deguelov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 15, 'iz Neftalija: Ahira, sin Enanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 16, 'Ti so bili pooblaščenci občine, knezi rodovom očetov svojih, glave tisočim Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 17, 'Mojzes torej in Aron vzameta te može, ki so zaznamenjani po imenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 18, 'in skličeta vso občino prvi dan drugega meseca. In izpovedovali so rod svoj po svojih rodovinah, po hišah očetov svojih, po številu imen, od dvajsetih let in više, od glave do glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 19, 'Kakor je bil Gospod zapovedal Mojzesu, tako jih je preštel v puščavi Sinajski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 20, 'In bilo je sinov Rubena, Izraelovega prvenca, rojenih po njih rodovinah, po hišah njih zarodnikov, po številu imen od glave do glave, vseh moških od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 21, 'preštetih iz roda Rubenovega šestinštirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 22, 'Iz sinov Simeonovih, njih zarojencev po njih rodovinah, po hišah njih očetov, tistih, ki so bili šteti po številu imen, od glave do glave, vseh moških od dvajsetih let in više, kar jih moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 23, 'preštetih iz rodu Simeonovega je bilo devetinpetdeset tisoč in tristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 24, 'Iz sinov Gadovih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, vseh, ki so mogli iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 25, 'preštetih iz rodu Gadovega je bilo petinštirideset tisoč šeststo in petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 26, 'Iz sinov Judovih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 27, 'preštetih iz rodu Judovega je bilo štiriinsedemdeset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 28, 'Iz sinov Isaharjevih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 29, 'preštetih iz rodu Isaharjevega je bilo štiriinpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 30, 'Iz sinov Zebulonovih, njih zarojencev po njih rodovinah, po njih očetov hišah, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 31, 'preštetih iz rodu Zebulonovega je bilo sedeminpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 32, 'Iz sinov Jožefovih, in sicer iz sinov Efraimovih, njih zarojencev po njih rodovinah, po njih očetov hišah, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 33, 'preštetih iz rodu Efraimovega je bilo štirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 34, 'Iz sinov Manasejevih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 35, 'preštetih iz rodu Manasejevega je bilo dvaintrideset tisoč in dvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 36, 'Iz sinov Benjaminovih, njih zarojencev po njih rodovinah, po njih očetov hišah, po številu imen, od dvajsetih let in više, kar jih je mogli iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 37, 'preštetih iz rodu Benjaminovega je bilo petintrideset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 38, 'Iz sinov Danovih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 39, 'preštetih iz rodu Danovega je bilo dvainšestdeset tisoč in sedemsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 40, 'Iz sinov Aserjevih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 41, 'preštetih iz rodu Aserjevega je bilo edeninštirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 42, 'Iz sinov Neftalijevih, njih zarojencev po njih rodovinah, po hišah njih očetov, po številu imen, od dvajsetih let in više, kar jih je moglo iti na vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 43, 'preštetih iz rodu Neftalijevega je bilo triinpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 44, 'To so sešteti, ki so jih šteli Mojzes in Aron in knezi Izraelovi, katerih je bilo dvanajst: vsak njih je zastopal očetov svojih hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 45, 'Bilo je torej vseh, ki so bili šteti iz sinov Izraelovih po hišah očetov svojih, od dvajsetih let in više, kar jih je moglo iti na vojsko v Izraelu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 46, 'vseh preštetih je bilo šeststointri tisoč in petsto in petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 47, 'Levitov pa po rodu njih očetov niso šteli ž njimi vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 48, 'Govoril je namreč Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 49, 'Samo rodú Levijevega ne štej, tudi njih števila ne poizveduj med sinovi Izraelovimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 50, 'temuč postavi levite nad šatorom pričevanja ter nad vsemi pripravami njegovimi in nad vsem, kar pripada k njemu: oni naj nosijo šator in vse priprave njegove, in oni naj mu služijo in okoli šatora naj taborujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 51, 'In kadar bode šatoru odriniti, naj ga razložé leviti; kadar bo pa treba šator razpeti, naj ga postavijo leviti; nepoklicanec pa, ki se približa, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 52, 'In sinovi Izraelovi naj razpenjajo šatore svoje vsak na svojem šatorišču in vsak pri svojem praporu, po svojih trumah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 53, 'A leviti naj si razpenjajo šatore okoli prebivališča pričevanja, da ne pride srd nad občino sinov Izraelovih; leviti naj bodo torej na stražah, da strežejo šatoru pričevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 1, 54, 'In sinovi Izraelovi so storili po vsem, kakor je bil zapovedal Gospod Mojzesu: prav tako so storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 2, 'Sinovi Izraelovi naj stavijo šatore svoje vsakteri pri svojem praporu, ob znamenjih hiš očetov svojih; v smeri proti shodnemu šatoru kroginkrog naj si razpenjajo šatore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 3, 'Ob vzhodu proti jutru naj taborujejo tisti, ki so od prapora tabora Judovega, po trumah svojih, in vojvoda sinov Judovih bodi Nahson, sin Aminadabov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 4, 'In vojske njegove, seštetih izmed njih, je bilo štiriinsedemdeset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 5, 'In poleg njega naj taborujeta rod Isaharjev, in vojvoda sinov Isaharjevih bodi Netanel, sin Zuarjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 6, 'in vojske njegove, seštetih izmed njih, je bilo štiriinpetdeset tisoč in štiristo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 7, 'in rod Zebulonov, in vojvoda sinov Zebulonovih bodi Eliab, sin Helonov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 8, 'in vojske njegove, seštetih izmed njih, je bilo sedeminpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 9, 'Vseh, ki so bili šteti od Judovega tabora, je bilo sto in šestinosemdeset tisoč in štiristo, po trumah svojih. Oni naj hodijo spredaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 10, 'Na južni strani bodi prapor tabora Rubenovega po svojih trumah, in vojvoda sinov Rubenovih bodi Elizur, sin Šedeurjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 11, 'In vojske njegove, seštetih izmed njih, je bilo šestinštirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 12, 'In poleg njega naj taborujeta rod Simeonov, in vojvoda sinov Simeonovih bodi Šelumiel, sin Zurišadajev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 13, 'in vojske njegove, seštetih izmed njih, je bilo devetinpetdeset tisoč in tristo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 14, 'in rod Gadov, in vojvoda sinov Gadovih bodi Eliasaf, sin Reguelov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 15, 'in vojske njegove, seštetih med njimi, je bilo petinštirideset tisoč in šeststo in petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 16, 'Vseh, ki so bili šteti od tabora Rubenovega, je bilo stoedeninpetdeset tisoč in štiristo in petdeset, po njih trumah. In ti naj hodijo kot drugi voj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 17, 'In potem naj gre shodni šator s taborom levitov sredi taborov: kakor bodo utaborjeni, tako naj se odpravijo na potovanje, vsakteri na svojem mestu, pri svojih praporih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 18, 'Na zahodni strani bodi prapor tabora Efraimovega po svojih trumah, in vojvoda sinov Efraimovih bode Elišama, sin Amihudov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 19, 'In vojske njegove, seštetih izmed njih, je bilo štirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 20, 'In poleg njega bodi rod Manasejev, in vojvoda sinov Manasejevih bo Gamaliel, sin Pedazurjev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 21, 'in vojske njegove, seštetih izmed njih, je bilo dvaintrideset tisoč in dvesto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 22, 'in rod Benjaminov, in vojvoda sinov Benjaminovih bodi Abidan, sin Gideonijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 23, 'in vojske njegove, seštetih izmed njih, je bilo petintrideset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 24, 'Vseh, ki so bili šteti od tabora Efraimovega, je bilo stoinosem tisoč in sto, po svojih trumah. In ti naj hodijo kot tretji voj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 25, 'Na severni strani bodi prapor tabora Danovega po svojih trumah, in vojvoda sinov Danovih bodi Ahiezer, sin Amišadajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 26, 'In vojske njegove, seštetih izmed njih, je bilo dvainšestdeset tisoč in sedemsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 27, 'In poleg njega bodi rod Aserjev, in vojvoda sinov Aserjevih bo Pagiel, sin Okranov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 28, 'in vojske njegove, seštetih izmed njih, je bilo edeninštirideset tisoč in petsto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 29, 'in rod Neftalijev, in vojvoda sinov Neftalijevih bodi Ahira, sin Enanov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 30, 'in vojske njegove, seštetih izmed njih, je bilo triinpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 31, 'Vseh, ki so bili šteti od tabora Danovega, je bilo stosedeminpetdeset tisoč in šeststo. Ti naj hodijo poslednji po praporih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 32, 'Ti so, ki so bili šteti iz sinov Izraelovih po hišah svojih zarodnikov: vseh seštetih v taborih, po njih trumah, je bilo šeststo tri tisoč, petsto in petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 33, 'Leviti pa niso bili všteti v čislo sinov Izraelovih, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 2, 34, 'In sinovi Izraelovi so storili po vsem, kar je bil Gospod ukazal Mojzesu: prav tako so stavili šatore pri svojih praporih in prav tako se odpravljali na potovanje, vsak po svoji rodovini, pri očetov svojih družini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 1, 'Ti pa so rodovi Arona in Mojzesa ob času, ko je Gospod govoril z Mojzesom na gori Sinaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 2, 'In ta so imena sinov Aronovih: Nadab prvenec, in Abihu, Eleazar in Itamar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 3, 'Ta so imena sinov Aronovih pomaziljenih duhovnikov, ki so bili posvečeni, da opravljajo duhovniško službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 4, 'Nadab pa in Abihu sta umrla pred Gospodom, ko sta darovala tuj ogenj pred Gospodom, v puščavi Sinajski, in nista imela otrok; Eleazar in Itamar sta torej služila za duhovnika pod nadzorstvom Arona, očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 5, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 6, 'Pripelji bliže rod Levijev in postavi jih pred Arona duhovnika, da mu strežejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 7, 'In naj bodo na straži zanj in na straži za vso občino pred shodnim šatorom, da opravljajo službo pri prebivališču;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 8, 'in naj pazijo na vse priprave v shodnem šatoru ter bodo marljivi na straži za sinove Izraelove, da opravljajo službo pri prebivališču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 9, 'In daj levite Aronu in sinovom njegovim: njemu so v last dani izmed sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 10, 'Arona pa in sinove njegove postavi, da imajo na skrbi duhovniško službo svojo; nepoklicanec pa, ki se približa, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 11, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 12, 'Glej, vzel sem si levite izmed sinov Izraelovih namesto vsega prvorojenega, kar predere maternico med sinovi Izraelovimi; zatorej so leviti moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 13, 'Zakaj prvorojeno vse je moje; v dan, ko sem udaril vse prvorojeno v deželi Egiptovski, sem posvetil zase vse prvence v Izraelu, od človeka do živali, naj bodo moji. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 14, 'In Gospod je govoril Mojzesu v puščavi Sinajski, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 15, 'Seštej sinove Levijeve po hišah njih očetov, po njih rodovinah; štej pa vse moške, mesec dni stare in više.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 16, 'Mojzes jih torej prešteje po besedi Gospodovi, kakor mu je bilo ukazano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 17, 'In ti so bili sinovi Levijevi po svojih imenih: Gerson, Kahat in Merari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 18, 'In ta so imena sinov Gersonovih po njiju rodovinah: Libni in Simej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 19, 'In sinovi Kahatovi po svojih rodovinah: Amram in Izhar, Hebron in Uziel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 20, 'In sinova Merarijeva po rodovinah svojih: Mahli in Musi. To so rodovine levitov po hišah njih očetov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 21, 'Od Gersona je bila rodovina Libnijskih in Simejskih; ti sta rodovini Gersonovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 22, 'Sešteti pa izmed njih, po številu vseh moških, mesec dni starih in više, seštetih je bilo sedem tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 23, 'Rodovini Gersonovcev sta taborili ob zadnji strani Šatora, proti zahodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 24, 'In vojvoda očetove hiše Gersonovcev je bil Eliasaf, sin Laelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 25, 'In v oskrbovanje sinom Gersonovim dano pri shodnem šatoru: prebivališče in šator, njegova odeja in zavesa za vhod v shodni šator');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 26, 'in zastori ob dvorišču in zavesa za vrata na dvorišče, ki obdaja prebivališče in oltar, in njegove vrvi za vso službo pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 27, 'Od Kahata je bila rodovina Amramovcev in rodovina Izharjevcev in rodovina Hebronskih in rodovina Uzielskih: to so rodovine Kahatovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 28, 'Po številu vseh moških, mesec dni starih in više, jih je bilo osem tisoč in šeststo, pripravljenih za stražo svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 29, 'Rodovine sinov Kahatovih so taborile ob strani prebivališča proti jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 30, 'In vojvoda očetove hiše Kahatovih rodovin je bil Elizafan, sin Uzielov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 31, 'In v oskrbovanje jim dana skrinja in miza in svečnik in oltarja in posode svetišča, s katerimi službujejo, in zavesa in karkoli nanese služba pri tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 32, 'Eleazar pa, sin Arona duhovnika, je bil prvak vojvodam levitov in nadzornik njim, ki so na straži stregli svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 33, 'Od Merarija je bila rodovina Mahlijevih in rodovina Musijevih; ti sta rodovini Merarijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 34, 'In seštetih izmed njih, po številu vseh moških, mesec dni starih in više, je bilo šest tisoč in dvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 35, 'In vojvoda očetove hiše rodovin Merarijevih je bil Zuriel, sin Abihailov. Oni sta taborili na strani prebivališča proti severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 36, 'In v oskrbniško službo sinov Merarijevih so izročene deske od prebivališča in njegovi zapahi in stebri ter podstave njegove in vse priprave njegove in karkoli se rabi v službi pri njem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 37, 'in stebri, ki so okoli dvorišča, in njih podstavki, kolčki in vrvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 38, 'Pred prebivališčem ob vzhodu pa, pred shodnim šatorom proti solnčnemu izhodu, so taborili Mojzes in Aron in sinovi njegovi in so stregli službi v svetišču namesto sinov Izraelovih. Nepoklicanec pa, ki se približa, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 39, 'Vseh seštetih levitov, ki sta jih seštela Mojzes in Aron po ukazu Gospodovem, po njih rodovinah, vseh moških, mesec dni starih in više, je bilo dvaindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 40, 'In Gospod veli Mojzesu: Preštej vse prvorojene moške med sinovi Izraelovimi, mesec dni stare in više, in poizvedi število njih imen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 41, 'In vzemi zame levite - jaz sem Gospod - namesto vseh prvencev med sinovi Izraelovimi, živino levitov pa namesto vseh prvencev med živino sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 42, 'Tedaj sešteje Mojzes, kakor mu je Gospod ukazal, vse prvorojence med sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 43, 'In bilo je vseh moških prvencev po številu imen, mesec dni starih in više, vseh seštetih je bilo dvaindvajset tisoč, dvesto in triinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 44, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 45, 'Vzemi levite namesto vseh prvencev med sinovi Izraelovimi in živino levitov namesto njih živine, in moji naj bodo leviti. Jaz sem Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 46, 'In za odkup tistih dvesto in triinsedemdesetih prvencev sinov Izraelovih, ki jih je več nego levitov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 47, 'vzemi pet seklov za sleherno glavo; le po seklu svetišča jih sprejemaj (v ta sekel gre dvajset ger).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 48, 'In daj te denarje, s katerimi se odkupi onih presežno število, Aronu in sinovom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 49, 'Vzame torej Mojzes odkupnino od tistih, ki so presegali število odrešenih po levitih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 50, 'od prvencev sinov Izraelovih je vzel denar, tisoč tristo petinšestdeset seklov, po seklu svetišča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 3, 51, 'in Mojzes je dal odkupnino Aronu in sinovom njegovim, po ukazu Gospodovem, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 2, 'Poizvedita število sinov Kahatovih med sinovi Levijevimi, po njih rodovinah, po hišah njih očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 3, 'od tridesetletnih do petdesetletnih, vsakega, ki gre k vojski, da bi opravljal delo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 4, 'To je služba sinov Kahatovih v shodnem šatoru, pri najsvetejšem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 5, 'Kadar se vzdigne tabor, naj stopi Aron in sinovi njegovi v svetišče ter snamejo ločilno zagrinjalo in vanje zavijejo skrinjo pričevanja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 6, 'in jo še ogrnejo z odejo iz jazbečevih kož, vrhu nje pa razprostro prt, ves iz višnjeve tkanine, in naj ob njo vtaknejo drogova njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 7, 'In čez mizo kruhov obličja naj razprostro višnjev prt ter denejo nanjo sklede, torila, konvice in vrčke za pitno daritev, in neprenehljiv kruh naj ostane na njej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 8, 'in čez to vse naj razgrnejo karmezinast prt ter ga pokrijejo z odejo iz jazbečevih kož, in njena drogova naj vtaknejo vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 9, 'In vzamejo naj višnjev prt ter zagrnejo svečnik za razsvetljavo in svetilnice njegove in utrinjala in lončke za utrinke in vse posode za olje, s katerimi se mu služi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 10, 'in naj ga denejo in vse posode njegove v odejo iz jazbečevih kož ter ga postavijo na nosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 11, 'In čez zlati oltar naj razprostro višnjev prt in ga zavijejo v odejo iz jazbečevih kož ter vanj vtaknejo droga njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 12, 'Nato naj vzamejo vse službene priprave, s katerimi opravljajo službo v svetišču, in naj jih denejo v višnjev prt ter jih zavijejo v odejo iz jazbečevih kož in jih polože na nosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 13, 'Potem naj oltar očistijo pepela ter razprostro čezenj zagorelordeč prt');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 14, 'in denejo nanj vse priprave njegove, s katerimi se opravlja služba ob njem, ponve za žerjavico, vilice, lopate, čaše, vse posode oltarjeve; in naj razgrnejo čezenj odejo iz jazbečevih kož ter vanj vtaknejo droga njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 15, 'Ko pa to dovrše Aron in sinovi njegovi ter zavijejo svetišče in vse priprave svetišča, ko bo skoraj začel potovati tabor, naj pristopijo sinovi Kahatovi, da poneso svetišče, ali naj se ga ne dotaknejo, da ne umro. To je kar, bodo nosili sinovi Kahatovi od shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 16, 'Eleazar pa, sin Arona duhovnika, imej nadzorstvo nad oljem za svetilo in blagodišečim kadilom in neprestano jedilno daritvijo in mazilnim oljem, nadzorstvo nad vsem prebivališčem in vsem, kar je v njem, nad svetiščem in njega pripravami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 17, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 18, 'Pazite, da se ne iztrebi pokolenje rodovin Kahatovih izmed levitov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 19, 'ampak to jim storite, da živé in ne umrjejo, kadar pristopajo k najsvetejšemu: Aron in sinovi njegovi naj gredo v svetišče ter odkažejo vsakemu, kar bo delal in kar bo nosil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 20, 'Oni sami pa naj ne hodijo noter gledat svetih reči niti za trenotek, da ne umrjejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 21, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 22, 'Poizvedi število tudi sinov Gersonovih po hišah njih očetov, po njih rodovinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 23, 'od tridesetletnih do petdesetletnih jih seštej, vsakega, ki gre po vojaško služit, da opravlja delo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 24, 'To je služba Gersonovih rodovin, ko strežejo in nosijo bremena:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 25, 'Nosijo naj preproge prebivališča in shodni šator, namreč njegovo odejo in odejo iz jazbečevih kož, ki je vrhu nje, in zaveso ob vhodu v shodni šator');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 26, 'in zastore okoli dvorišča in zaveso pri vratih na dvorišče, ki obdaja šator in oltar kroginkrog, in njih vrvi in vse priprave za njih službo; in karkoli je treba delati pri tem, naj opravijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 27, 'Po ukazu Arona in sinov njegovih naj se vrši vsa služba sinov Gersonovih v vsem, kar bodo nosili in kar bodo delali; in poverite jim v stražo, kar jim je nositi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 28, 'To je služba rodovin Gersonovcev pri shodnem šatoru; in njih straža bodi pod nadzorstvom Itamarja, sina Arona duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 29, 'Sinove Merarijeve pa seštej po njih rodovinah, po hišah njih očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 30, 'od tridesetletnih do petdesetletnih jih seštej, vsakega, ki gre k vojski, da bi opravljal delo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 31, 'In to jim je poverjeno, da stražijo in nosijo v vsej službi svoji pri shodnem šatoru: deske od prebivališča in njih zapahe in stebre in podstave');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 32, 'in stebre, ki so okoli dvorišča, in njih podstavke in kolčke in vrvi, z vsem njih orodjem in z vsem, kar je treba streči pri njih; in po imenu jim odštejte orodje, ki naj ga stražijo in nosijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 33, 'To je služba rodovin sinov Merarijevih, kolikor so dolžni služiti pri shodnem šatoru pod nadzorstvom Itamarja, sina Arona duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 34, 'In Mojzes in Aron in prvaki občine so sešteli Kahatove sinove po njih rodovinah in po njih očetovskih hišah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 35, 'od tridesetletnih do petdesetletnih, vsakega, ki gre k vojski, za delo pri shodnem šatoru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 36, 'in seštetih je bilo, po njih rodovinah, dva tisoč sedemsto in petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 37, 'Ti so, ki so bili šteti iz rodovin Kahatovih, vsi, ki so služili pri shodnem šatoru, katere sta seštela Mojzes in Aron, kakor je bil zapovedal Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 38, 'In preštetih iz sinov Gersonovih, po njih rodovinah in po hišah njih očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 39, 'od tridesetletnih do petdesetletnih, vsi, ki so šli k vojski, za delo pri shodnem šatoru,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 40, 'tistih katere so sešteli po njih rodovinah, po hišah njih očetov, je bilo dva tisoč in šeststo in trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 41, 'Ti so bili šteti iz rodovin Gersonovcev, vsi, ki so služili pri shodnem šatoru, katere sta seštela Mojzes in Aron, kakor je bil zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 42, 'In seštetih iz rodovin sinov Merarijevih, po njih rodovinah, po hišah njih očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 43, 'od tridesetletnih do petdesetletnih, vsak, ki je šel k vojski, za delo pri shodnem šatoru,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 44, 'tistih, katere so sešteli po njih rodovinah, je bilo tri tisoč in dvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 45, 'Ti so bili sešteti iz rodovin Merarijevih, katere sta seštela Mojzes in Aron, kakor je bil zapovedal Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 46, 'Vseh seštetih iz levitov, katere so sešteli Mojzes in Aron in prvaki Izraelovi, po njih rodovinah in po hišah njih očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 47, 'od tridesetletnih do petdesetletnih, vsi, ki so prišli opravljat delo službe in nosit bremena pri shodnem šatoru,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 48, 'tistih, katere so sešteli, je bilo osem tisoč in petsto in osemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 4, 49, 'Po ukazu Gospodovem jih je postavil Mojzes, vsakterega k službi njegovi in k bremenu njegovemu, in vsak je bil postavljen, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 2, 'Zapovej sinovom Izraelovim, naj odpravijo iz tabora vsakega gobavca in vsakega, ki ima tok in kdorkoli se je onečistil pri mrliču;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 3, 'bodisi mož ali žena, odpravite jih, ven za taborišče jih pošljite, da ne bi oskrunjali taborov svojih, sredi katerih prebivam jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 4, 'In sinovi Izraelovi so storili tako in jih odpravili ven za taborišče; kakor je bil govoril Gospod Mojzesu, tako so storili sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 5, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 6, 'Véli sinovom Izraelovim: Ako mož ali žena stori katerikoli grehov, ki ž njimi ljudje zagreše nezvestobo proti Gospodu, in duša ta je kriva:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 7, 'tedaj naj pripozna greh, ki ga je storila, in naj da povračilo za krivdo svojo v celem znesku in pridene še peti del k temu, in naj da onemu, zoper katerega se je pregrešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 8, 'Če pa ni po dotičniku sorodnika, ki bi se mu dalo povračilo za krivdo, naj se da povračilo za krivdo Gospodu in naj pripade duhovniku, razen ovna sprave, s katerim se izvrši poravnava za krivca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 9, 'Tudi vsak dar povzdignjenja od vseh svetih reči sinov Izraelovih, ki ga prineso duhovniku, bode njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 10, 'In vsakega človeka posvečene reči pripadejo duhovniku; karkoli kdo da duhovniku, bodi njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 11, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 12, 'Govóri sinom Izraelovim in jim reci: Čigar žena se razuzda in se mu izneveri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 13, 'in drug mož se ž njo telesno združi, in bi bilo skrito očem njenega moža, ker se je na skrivnem oskrunila, ter bi ne bilo priče zoper njo in ne bi bila zasačena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 14, 'in njega obide duh ljubosumnosti in bi sumnil o ženi svoji, in ona bi bila oskrunjena; ali pa ga obide duh ljubosumnosti in bi sumnil o ženi svoji, in ona bi ne bila oskrunjena:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 15, 'tedaj naj pripelje mož ženo svojo k duhovniku ter prinese zaradi nje dar, desetino efe ječmenove moke, toda naj ne vlije vanjo olja in tudi ne dene nanjo kadila; zakaj jedilna daritev ljubosumnosti je, jedilna daritev spomina, ki spominja krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 16, 'In duhovnik jo privedi bliže in postavi pred Gospoda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 17, 'nato zajmi svete vode v prsteno posodo ter vzemi prahu, ki je na tleh prebivališča, in ga deni v vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 18, 'Potem postavi ženo pred Gospoda in ji razkrij glavo in ji daj v roke jedilno daritev spomina, ki je jedilna daritev ljubosumnosti; a v roki duhovnikovi bodi grenka voda, ki povzroča prokletstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 19, 'Nato naj jo duhovnik zaroti in reče ženi: Ako nihče ni ležal s teboj in nisi zašla v nečistoto od moža svojega, bodi prosta te grenke vode, ki povzroča prokletstvo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 20, 'ako pa si zašla od moža svojega in se oskrunila in se je kdo združil s teboj razen moža tvojega -');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 21, 'tedaj naj zaroti duhovnik ženo s preklinjajočo prisego in ji reče: Gospod naj te postavi v prokletstvo in zarotitev med ljudstvom tvojim s tem, da ti zgnijo bedra in oteče trebuh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 22, 'Izteče naj ta voda, ki povzroča prokletstvo, v telo tvoje in stori, da ti oteče trebuh in zgnijo bedra. In žena naj reče: Amen, amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 23, 'Nato napiši duhovnik te kletve na list in jih speri v tisto grenko vodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 24, 'in daj piti ženi grenko vodo, ki povzroča prokletstvo, da gre vanjo voda prokletstva in ji napravi grenkobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 25, 'In vzemi duhovnik jedilno daritev ljubosumnosti iz ženine roke, in majaj jedilno daritev pred Gospodom in jo prinesi k oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 26, 'Nato vzemi duhovnik prgišče jedilne daritve kot njen spomin in zažgi to na oltarju, in potem naj da ženi piti vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 27, 'In ko se napije vode, se zgodi, ako se je oskrunila in zagrešila nezvestobo proti možu svojemu, da ji ta voda prokletstva, ko pride vanjo, napravi grenkobo, in trebuh ji oteče in bedra ji segnijejo; žena pa bode v kletev med svojim ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 28, 'Ako pa se ni oskrunila in je čista, ji ne bo nič škodilo in prejme zarod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 29, 'To je postava za ljubosumnost, ko se žena razuzda od svojega moža in se oskruni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 30, 'ali pa če obide moža duh ljubosumnosti in sumni o ženi svoji: tedaj naj postavi ženo pred Gospoda, in duhovnik naj ž njo ravna po vsej tej postavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 5, 31, 'In mož bode prost krivice, tista žena pa naj nosi krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 2, 'Govori sinom Izraelovim in reci: Ko se mož ali žena odmeni s tem, da stori obljubo nazirca, da se posveti Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 3, 'naj se zdržuje vina in močne pijače; ne pije naj kisa iz vina ali kisa iz močne pijače, tudi naj ne pije soka iz grozdja ter ne jé sirovih ali suhih grozdov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 4, 'Dokler traja nazirstvo njegovo, naj ne jé ničesar, kar je narejeno od vinske trte, od pečkov do tropin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 5, 'Dokler traja obljuba nazirstva njegovega, naj ne pride britev na glavo njegovo; dokler se ne dopolnijo dnevi, za katere se je posvetil Gospodu, je svet; pusti naj, da prosto rasto lasje na glavi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 6, 'Vse dni, za katere se je posvetil Gospodu, naj se ne približa mrliču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 7, 'Pri očetu svojem in pri materi svoji, pri bratu svojem in sestri svoji naj se ne onečisti, kadar umrjejo; zakaj posvečenje Boga njegovega je na glavi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 8, 'Vse dni svojega nazirstva je svet Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 9, 'Ako pa kdo zraven njega nenadoma naglo umrje in se mu s tem onečisti posvečena glava, naj si ostriže glavo v dan očiščevanja svojega, sedmi dan naj jo ostriže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 10, 'In osmi dan naj prinese dve grlici ali dva golobiča k duhovniku, k vratom shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 11, 'Duhovnik pa vzemi eno v daritev za greh in drugo vžgalno daritev in izvrši poravnavo zanj, da se je pregrešil ob mrliču; on pa naj posveti glavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 12, 'In vnovič naj posveti Gospodu dneve nazirstva svojega ter prinese enoletno jagnje v daritev za krivdo; ali poprejšnji dnevi so neveljavni, ker je bilo ognušeno nazirstvo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 13, 'To je postava za nazirca: Ko se dopolnijo dnevi nazirstva njegovega, naj pride k vratom shodnega šatora;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 14, 'prinese pa naj Gospodu darilo svoje: enoletno jagnje brez hibe v žgalno daritev, enoletno ovco brez hibe v daritev za greh in ovna brez madeža v mirno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 15, 'in koš opresnikov, kolačev iz bele moke, zamešene z oljem, in nekvašenih mlincev, pomazanih z oljem, ž njih jedilno in pitno daritvijo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 16, 'Duhovnik pa naj jih prinese pred obličje Gospodovo ter daruje njegovo daritev za greh in žgalščino;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 17, 'ovna naj daruje Gospodu kot mirovno daritev s košem nekvašenih kruhov vred; tudi naj daruje duhovnik jedilno in pitno daritev njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 18, 'In nazirec naj ostriže posvečeno glavo svojo ob vhodu v shodni šator; potem naj vzame lase posvečene glave svoje in jih dene na ogenj, ki je pod mirovno daritvijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 19, 'Duhovnik pa vzemi kuhano ovnovo pleče, opresen kolač iz koša in opresen mlinec ter položi to nazircu na roke, potem ko si je ostrigel glavo nazirstva svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 20, 'in duhovnik majaj to kot daritev majanja pred Gospodom; sveto je duhovniku s prsmi majanja in s plečem povzdignjenja vred. In potem sme nazirec piti vino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 21, 'To je postava za nazirca, ki stori obljubo, in to je daritev njegova Gospodu zaradi posvečenja svojega, razen tega, kar sicer premore; po svoji obljubi, kakor je obljubil, naj stori po postavi posvečenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 22, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 23, 'Govóri Aronu in sinovom njegovim in véli: Takole blagoslavljajte sinove Izraelove, govoreč jim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 24, 'Gospod te blagoslóvi in te varuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 25, 'Gospod razsvétli obličje svoje proti tebi in ti bodi milostiv!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 26, 'Gospod obrni obličje svoje milo k tebi in ti daj mir!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 6, 27, 'Tako naj kličejo ime moje nad sinove Izraelove, in jaz jih hočem blagosloviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 1, 'In zgodi se v dan, ko je Mojzes končal urejevanje prebivališča, ko ga je pomazilil in posvetil z vsemi pripravami njegovimi, tudi oltar z vsemi njegovimi pripravami, ko jih je bil pomazilil in posvetil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 2, 'da so darovali knezi Izraelovi, poglavarji hiš očetov svojih; ti so bili knezi rodov, postavljeni nad seštetimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 3, 'In pripeljali so darila svoja pred Gospoda: šest pokritih voz in dvanajst volov; dva kneza sta dala en voz in enega vola sleherni izmed njih, in pripeljali so jih pred prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 4, 'Tedaj ogovori Gospod Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 5, 'Vzemi to od njih, da bodi v službo shodnega šatora, in daj levitom, vsakemu primerno službi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 6, 'Vzame torej Mojzes vozove in vole ter jih da levitom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 7, 'Dva voza in štiri vole izroči sinovom Gersonovim, primerno njih službi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 8, 'štiri voze in osem volov pa izroči sinovom Merarijevim, primerno njih službi, pod nadzorstvom Itamarja, sina Arona duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 9, 'Ali sinovom Kahatovim ne da od tega, zakaj služba svetišča jim je bila naložena: na ramah so ga nosili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 10, 'In prinesli so knezi dar oltarjevega posvečenja v dan, ko je bil maziljen, in darovali so darilo svoje pred oltarjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 11, 'Tedaj reče Gospod Mojzesu: Naj prinese darilo svoje vsak knez v svoj dan za posvečenje oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 12, 'Prvi dan je prinesel darilo svoje Nahson, sin Aminadabov, iz Judovega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 13, 'In darilo njegovo je bilo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, zamešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 14, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 15, 'mlad volič, oven, enoletno jagnje v žgalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 16, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 17, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Nahsona sina Aminadabovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 18, 'Drugi dan je daroval Netanel, sin Zuarjev, knez Isaharjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 19, 'In prinesel je v darilo svoje srebrno skledo, stointrideset seklov težko, srebrno kupo iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, zamešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 20, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 21, 'mladega voliča, ovna, enoletno jagnje v žgalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 22, 'kozla v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 23, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Netanela, sina Zuarjevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 24, 'Tretji dan Eliab, sin Helonov, knez sinov Zebulonovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 25, 'Darilo njegovo je bilo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem omešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 26, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 27, 'mlad volič, oven, enoletno jagnje v žgalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 28, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 29, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Eliaba, sina Helonovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 30, 'Četrti dan knez sinov Rubenovih, Elizur, sin Šedeurjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 31, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem omešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 32, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 33, 'mlad volič, oven, enoletno jagnje v žgalno žrtev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 34, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 35, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Elizurja, sina Šedeurjevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 36, 'Peti dan knez sinov Simeonovih, Šelumiel, sin Zurišadajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 37, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem zamešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 38, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 39, 'mlad volič, oven, enoletno jagnje v žgalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 40, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 41, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Šelumielovo, sina Zurišadajevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 42, 'Šesti dan knez sinov Gadovih, Eliasaf, sin Deguelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 43, 'Njegovo darilo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem omešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 44, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 45, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 46, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 47, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Eliasafa, sina Deguelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 48, 'Sedmi dan knez sinov Efraimovih, Elišama, sin Amihudov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 49, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem zamešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 50, 'torilce iz desetih seklov zlata, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 51, 'mlad volič, oven, enoletno jagnje v žgalno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 52, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 53, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Elišama, sina Amihudovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 54, 'Osmi dan knez sinov Manasejevih, Gamaliel, sin Pedazurjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 55, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, z oljem omešene, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 56, 'torilce iz zlata, deset seklov težko, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 57, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 58, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 59, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Gamaliela, sina Pedazurjevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 60, 'Deveti dan knez sinov Benjaminovih, Abidan, sin Gideonijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 61, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, umešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 62, 'torilce zlato, deset seklov težko, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 63, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 64, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 65, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Abidana, sina Gideonijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 66, 'Deseti dan knez sinov Danovih, Ahiezer, sin Amišadajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 67, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, omešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 68, 'torilce zlato, deset seklov težko, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 69, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 70, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 71, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Ahiezerja, sina Amišadajevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 72, 'Enajsti dan knez sinov Aserjevih, Pagiel, sin Okranov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 73, 'Darilo njegovo: skleda srebrna, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, omešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 74, 'zlato torilce, deset seklov težko, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 75, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 76, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 77, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Pagiela, sina Okranovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 78, 'Dvanajsti dan knez sinov Neftalijevih, Ahira, sin Enanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 79, 'Darilo njegovo: srebrna skleda, stointrideset seklov težka, srebrna kupa iz sedemdesetih seklov, po seklu svetišča, obe polni bele moke, umešene z oljem, v jedilno daritev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 80, 'zlato torilce, deset seklov težko, polno kadila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 81, 'mlad volič, oven, enoletno jagnje v žgalščino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 82, 'kozel v daritev za greh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 83, 'in v mirovno daritev dva vola, pet ovnov, pet kozlov, pet enoletnih jagnjet. To je bilo darilo Ahira, sina Enanovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 84, 'To je bil dar ob posvečenju oltarja v dan, ko je bil maziljen, od knezov Izraelovih: dvanajst srebrnih skled, dvanajst srebrnih kup, dvanajst zlatih torilc;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 85, 'vsaka skleda iz stointridesetih seklov srebra, vsaka kupa iz sedemdesetih seklov: vse srebro teh posod dva tisoč štiristo seklov, po seklu svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 86, 'Tistih dvanajst zlatih torilc, polnih kadila, je vsako imelo deset seklov, po seklu svetišča: vsega zlata teh torilc je bilo stoindvajset seklov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 87, 'Vse govedi v žgalno daritev je bilo dvanajst volov, dvanajst ovnov, enoletnih jagnjet dvanajst in k njim pristojna jedilna daritev; in dvanajst kozlov v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 88, 'V mirovno daritev je bilo govedi štiriindvajset volov, šestdeset ovnov, kozlov šestdeset in enoletnih jagnjet šestdeset. To je bilo posvečenje oltarja, potem ko je bil maziljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 7, 89, 'In kadar je Mojzes šel v shodni šator, da bi govoril ž Njim, tedaj je slišal Glas, govoreč k njemu iznad pokrova skrinje pričevanja, iz sredi dveh kerubov; in On je govoril k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 2, 'Govóri Aronu in mu reci: Ko prižgeš svetilnice, naj svetijo sedmere svetilnice proti ospredju svečnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 3, 'In Aron je storil tako: prižgal je svetilnice njegove, da bi svetile proti ospredju svečnika, kakor je bil Gospod ukazal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 4, 'In takšno je bilo svečnikovo delo: tolkljano delo iz zlata je bilo, deblo njegovo in cvetice njegove so bile tolkljane; po vzorcu, ki ga je bil Gospod pokazal Mojzesu, ga je naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 5, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 6, 'Vzemi levite izmed sinov Izraelovih ter jih očisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 7, 'In takole stóri ž njimi pri njih očiščevanju: Poškropi jih z očiščevalno vodo, oni pa naj si obrijejo vse telo z britvijo in opero oblačila svoja, da bodo čisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 8, 'Nato naj vzamejo mladega voliča in jedilno daritev, ki gre k njemu, belo moko, umešeno z oljem, in drugega voliča mladega vzemi v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 9, 'In véli levitom, naj pristopijo pred shodni šator, in skliči vso občino sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 10, 'Nato postavi levite pred Gospoda; sinovi Izraelovi pa naj polože roke svoje na levite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 11, 'In Aron naj daruje levite pred Gospodom kot daritev majanja od sinov Izraelovih, da opravljajo službo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 12, 'In leviti naj polože roke svoje voličema na glavo, in eden naj se daruje v daritev za greh, drugi pa v žgalščino Gospodu, da se stori poravnava za levite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 13, 'In postavi levite pred Arona in sinove njegove ter jih daruj kot daritev majanja Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 14, 'Tako odločiš levite izmed sinov Izraelovih, da bodo moji leviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 15, 'Potem naj nastopijo leviti, da strežejo shodnemu šatoru, ko si jih očistil in daroval kot daritev majanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 16, 'Zakaj dani so, meni so dani izmed sinov Izraelovih; namesto vsega, kar prodira maternico, namesto vsega prvorojenega sinov Izraelovih sem si jih vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 17, 'Zakaj moji so vsi prvenci sinov Izraelovih, med ljudmi in med živino: v dan, ko sem udaril vse prvorojeno v deželi Egiptovski, sem si jih posvetil zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 18, 'Levite pa sem si vzel namesto vseh prvorojencev sinov Izraelovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 19, 'in dal sem levite v dar Aronu in sinovom njegovim izmed sinov Izraelovih, da opravljajo službo sinov Izraelovih pri shodnem šatoru ter služijo v spravo za sinove Izraelove, da ne zadene sinov Izraelovih kaznilen udarec, kadar se sinovi Izraelovi bližajo svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 20, 'In tako so storili Mojzes in Aron in sinovi Izraelovi z leviti: prav kakor je Gospod Mojzesu zapovedal za levite, tako so storili sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 21, 'In leviti so se očistili greha ter oprali oblačila svoja, in Aron jih je daroval kot daritev majanja pred Gospodom ter storil poravnavo zanje v njih očiščenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 22, 'Potem so šli leviti opravljat službo svojo v shodnem šatoru pred Aronom in pred sinovi njegovimi. Kakor je bil Gospod zapovedal Mojzesu zastran levitov, tako so jim storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 23, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 24, 'To je, kar velja levitom: Od petindvajsetega leta in više naj prihajajo po vojaško služit v službi pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 25, 'A po petdesetem letu naj stopijo iz vojaške službe svoje in ne služijo več;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 8, 26, 'samo pomaga naj vsak bratom svojim pri shodnem šatoru, da so marljivi na stražah, ali službe naj se ne loti. Tako narédi z leviti pri njih službovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 1, 'In Gospod je govoril Mojzesu v puščavi Sinajski prvi mesec drugega leta, ko so bili šli iz dežele Egiptovske in rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 2, 'Gotovo naj sinovi Izraelovi praznujejo pasho v njej določenem času!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 3, 'Štirinajsti dan tega meseca, proti večeru, jo obhajajte v njej določenem času; po vseh njenih postavah in naredbah jo praznujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 4, 'Tedaj ogovori Mojzes sinove Izraelove, da naj pripravijo velikonočno jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 5, 'In obhajali so pasho v prvem mesecu štirinajsti dan proti večeru v puščavi Sinajski; kakor je bil Gospod zapovedal Mojzesu, tako so vse storili sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 6, 'Bilo je pa nekaj mož, ki so se onečistili z mrličem in niso mogli praznovati pashe tisti dan. Ti stopijo tisti dan pred Mojzesa in Arona');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 7, 'ter ga ogovore: Mi smo nečisti zaradi mrliča; zakaj bi bili prikrajšani, da ne smemo prinesti darila Gospodovega v določenem času med sinovi Izraelovimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 8, 'In Mojzes jim reče: Počakajte, hočem slišati, kaj vam Gospod zapove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 9, 'In Gospod je govoril Mojzesu takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 10, 'Govori sinovom Izraelovim in reci: Če se kdo onečisti pri mrtvem ali pa bo na daljnem potu, bodisi iz vas ali prihodnjih rodov vaših, vendar naj napravi velikonočno jagnje Gospodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 11, 'drugega meseca štirinajsti dan proti večeru naj ga taki obhajajo, z opresnim kruhom in grenkimi zelišči naj ga jedo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 12, 'nič naj ga ne puste do jutra, tudi nobene kosti v njem naj ne zlomijo; natančno po postavi pashe naj se ravnajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 13, 'Kdor pa je čist in ni na potovanju, a opusti praznovati pasho, tega duša bodi iztrebljena izmed ljudstva njegovega; kajti darila Gospodovega ni prinesel v določenem času, greh svoj naj nosi ta mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 14, 'Ako pa biva med vami tujec in hoče praznovati pasho Gospodu, naj se ravna po postavi pashe in njenih naredbah. Ista vam veljaj postava za tujca in za rojaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 15, 'V dan pa, ko je bilo postavljeno prebivališče, je pokril oblak prebivališče, šator pričevanja; in od večera do jutra je bila nad prebivališčem kakor podoba ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 16, 'Tako je bilo vsekdar: oblak ga je pokrival in po noči podoba ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 17, 'In kadar se je vzdignil oblak iznad Šatora, precej so se odpravili sinovi Izraelovi, in na mestu, kjer je počival oblak, ondi so se utaborili sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 18, 'Na povelje Gospodovo so odpotovali sinovi Izraelovi in na povelje njegovo so se utaborili; dokler je počival oblak nad prebivališčem, so taborili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 19, 'In ko je bil oblak na prebivališču veliko dni, so stregli sinovi Izraelovi na straži Gospodovi, in niso odhajali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 20, 'In če je ostal oblak nad prebivališčem le malo dni: na povelje Gospodovo so ostali v šatorih in na povelje Gospodovo so šli na pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 21, 'In če je bil oblak le od večera do jutra: ko se je vzdignil oblak zjutraj, so se odpravili; ali če je bil dan in noč: kadar se je vzdignil, so se tudi odpravili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 22, 'Ako pa je dva dni ali mesec dni ali več časa oblak počival nad prebivališčem, so ostali sinovi Izraelovi v šatorih in niso potovali; a brž, ko se je vzdignil, so se odpravili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 9, 23, 'Na povelje Gospodovo so razpenjali šatore in na povelje Gospodovo so potovali; stregli so na straži Gospodovi, kakor je zapovedal Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 2, 'Naredi si dve srebrni trobenti, s tolkljanim delom ju naredi, in uporabljaj ju v sklicevanje občine in kadar se kliče vojska na odhod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 3, 'Kadar se zatrobi na obe, naj se zbere občina vsa k tebi pred vhodom shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 4, 'Kadar pa se zatrobi na eno, naj se zbero k tebi knezi, glave tisočev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 5, 'Kadar pa bučno zatrobite, naj se vzdignejo vojske, ki so v šatorih proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 6, 'Ko pa v drugič bučno zatrobite, naj se vzdignejo vojske, ki so ušatorjene proti poldnevu. Kadar odhajajo naj trobijo bučno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 7, 'Ko se pa sklicuje zbor, tudi trobite, a ne bučno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 8, 'In sinovi Aronovi, duhovniki, naj trobijo na trobenti, in ti naj vam bodeta v večno postavo za prihodnje rodove vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 9, 'In kadar pojdete v deželi svoji na vojsko zoper zatiralca, ki vam bode sovražen, trobite bučno s trobentama, in pridete v spomin pred Gospodom, Bogom svojim, in rešeni boste sovražnikov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 10, 'In v dan veselja svojega, ob določenih praznikih in ob mlajih svojih trobite na trobenti pri svojih žgalnih in mirovnih daritvah, in bodeta vam v spomin pred Bogom vašim. Jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 11, 'In zgodilo se je v drugem letu, drugi mesec, dvajsetega dne tega meseca, da se je vzdignil oblak iznad prebivališča pričevanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 12, 'in sinovi Izraelovi so se odpravili po svojih krdelih iz puščave Sinajske, in oblak se je ustavil v puščavi Paranski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 13, 'Tedaj so prvič šli na pot po ukazu Gospodovem, danem Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 14, 'In najprej je odrinil prapor tabora sinov Judovih s trumami svojimi: nad vojsko njegovo je bil Nahson, sin Aminadabov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 15, 'in nad vojsko rodú sinov Isaharjevih je bil Netanel, sin Zuarjev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 16, 'in nad vojsko rodú sinov Zebulonovih Eliab, sin Helonov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 17, 'Medtem so razdeli prebivališče, in sinovi Gersonovi in Merarijevi so odrinili, noseč prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 18, 'Nato je odrinil prapor tabora Rubenovega s krdeli svojimi: nad vojsko njegovo je bil Elizur, sin Šedeurjev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 19, 'in nad vojsko rodú sinov Simeonovih Šelumiel, sin Zurišadajev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 20, 'in nad vojsko rodú sinov Gadovih Eliasaf, sin Deguelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 21, 'Potem so odrinili Kahatovci, noseč svetišče. Oni pa so postavljali prebivališče, dokler so ti prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 22, 'Za njimi je odrinil prapor tabora sinov Efraimovih s krdeli svojimi: nad vojsko njegovo je bil Elišama, sin Amihudov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 23, 'in nad vojsko rodu sinov Manasejevih Gamaliel, sin Pedazurjev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 24, 'in nad vojsko rodú sinov Benjaminovih Abidan, sin Gideonijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 25, 'Naposled je odrinil s krdeli svojimi prapor tabora sinov Danovih, zadnji voj vseh taborov: in nad vojsko njegovo je bil Ahiezer, sin Amišadajev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 26, 'in nad vojsko rodú sinov Aserjevih Pagiel, sin Okranov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 27, 'in nad vojsko rodú sinov Neftalijevih Ahira, sin Enanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 28, 'To je način odhodov sinov Izraelovih s svojimi vojskami, in tako so potovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 29, 'In Mojzes reče Hobabu, sinu Reguela Madianskega, tasta Mojzesovega: Popotujemo v kraj, o katerem je rekel Gospod: Vam ga hočem dati. Pojdi z nami, in dobro ti bomo storili, kajti dobro je Gospod obljubil Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 30, 'On pa mu odgovori: Ne pojdem z vami, ampak odidem v deželo svojo in k sorodstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 31, 'In reče: Ne zapústi nas, prosim; zakaj ti veš, kje naj taborimo v puščavi, in nam bodeš vodnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 32, 'Ako pojdeš z nami, gotovo izkažemo, karkoli nam Gospod stori dobrega, isto tudi tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 33, 'In potovali so tri dni hoda od gore Gospodove, in skrinja zaveze Gospodove je šla pred njimi tri dni pota, da jim najde počivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 34, 'Oblak Gospodov pa je bil po dnevi nad njimi, ko so šli iz tabora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 35, 'In bilo je, kadar je skrinja šla na pot, da je dejal Mojzes: Vstani, o Gospod, in naj se razkropé sovražniki tvoji, in tisti, ki te sovražijo, naj bežé pred obličjem tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 10, 36, 'Kadar pa je počivala, je dejal: Vrni se, o Gospod, k miriadam tisočev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 1, 'In ko je ljudstvo tožilo, govoreč hudo na ušesa Gospodu, in je Gospod slišal, se razsrdi, in vname se ogenj Gospodov med njimi ter požre najzadnji del tabora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 2, 'In ljudstvo vpije k Mojzesu, in Mojzes moli h Gospodu, in ogenj ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 3, 'In imenovali so ta kraj Tabera, ker se je razvnel ogenj Gospodov med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 4, 'Mešana druhal pa, ki je bila med njimi, se je vdala poželjivosti, pa tudi sinovi Izraelovi so vnovič jokali in govorili: Kdo nam da najesti se mesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 5, 'Spominjamo se na ribe, ki smo jih jedli v Egiptu brezplačno, in kumare in dinje in luk in čebulo in česen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 6, 'Sedaj pa je duša naša suha; ničesar nimamo tu, samo tisto mano vidijo naše oči. -');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 7, 'Mana pa je bila kakor koriandrovo seme in barva njena kakor bdelijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 8, 'Ljudstvo jo je hodilo pobirat in jo mlelo v mlinčkih ali trlo v možnarjih in kuhalo v loncih in pripravljalo iz nje kolače, in njen okus je bil kakor na olju pečenih kolačev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 9, 'in ko je po noči padala rosa na šatorišče, je padala mana ž njo vred. -');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 10, 'Tedaj čuje Mojzes, da ljudstvo joče po rodovinah svojih, vsakteri pri šatora svojega vratih; in razvname se srd Gospodov silno, in tudi Mojzesu se vidi prehudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 11, 'In reče Mojzes Gospodu: Zakaj tako hudo ravnaš s hlapcem svojim? In zakaj nisem našel usmiljenja v tvojih očeh, da mi nakladaš težo vsega tega ljudstva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 12, 'Sem li mar jaz spočel vse to ljudstvo ali ga rodil, da mi praviš: Nosi jih v naročju svojem, kakor nosi pestunja dojenčka, v deželo, ki si jo s prisego obljubil njih očetom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 13, 'Odkod naj vzamem mesa, da ga dam vsemu temu ljudstvu? Kajti jokajo pred mano ter govore: Daj nam mesa, da jemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 14, 'Ne morem sam nositi vsega tega ljudstva, ker mi je pretežko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 15, 'Ako pa hočeš tako z menoj ravnati, rajši me, prosim, usmrti, če sem našel usmiljenje v tvojih očeh, da ne gledam nesreče svoje! Tedaj veli Gospod Mojzesu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 16, 'Zberi mi sedemdeset mož iz starejšin Izraelovih, o katerih veš, da so starejšine ljudstva in oblastniki njegovi, in privedi jih k shodnemu šatoru, in naj stojé tam pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 17, 'Jaz pa stopim doli in bom ondi govoril s teboj, in vzamem od duha, ki je nad teboj, ter ga dam nadnje, da nosijo s teboj težo ljudstva, da ne bi tebe samega težilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 18, 'Ljudstvu pa véli: Posvetite se za jutri, in jedli boste meso; zakaj jokali ste na ušesa Gospodu in govorili: Kdo nam da jesti mesa? Res se nam je v Egiptu dobro godilo. Zato vam da Gospod mesa, da boste jedli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 19, 'ne eden dan ga boste jedli, ne dva, ne pet, ne deset, ne dvajset dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 20, 'marveč cel mesec dni, dokler vam ne poleze iz nosa in se vam zgnusi, zato ker ste zaničevali Gospoda, ki je sredi vas, in jokali pred njim, govoreč: Zakaj smo šli iz Egipta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 21, 'In Mojzes reče: Šeststo tisoč mož pešcev je tega ljudstva, med katerim jaz bivam, in ti praviš: Dam jim mesa, da ga uživajo mesec dni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 22, 'Pokolje li se toliko ovac in goved, da jim bode zadosti? Ali se jim bodo semkaj zbrale vse ribe morja, da jim bode zadosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 23, 'Gospod pa reče Mojzesu: Je li mar roka Gospodova prekratka? Zdaj pa boš videl, ali se ti zgodi po moji besedi ali ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 24, 'Mojzes torej gre ven ter sporoči ljudstvu besede Gospodove, in zbere sedemdeset mož iz starejšin ljudstva in jih postavi okoli Šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 25, 'In Gospod stopi doli v oblaku ter govori ž njim in vzame od duha, ki je bil nad njim, in ga da nad sedemdesetere starejšine. In zgodi se, ko počije duh nad njimi, da so prorokovali, pozneje pa nič več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 26, 'A v taboru sta ostala še dva moža, enemu ime Eldad in drugemu ime Medad, in duh je počil nad njima; bila sta namreč tudi med zapisanimi, a nista šla ven k Šatoru; in prorokovala sta v taborišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 27, 'Pa priteče deček in sporoči Mojzesu, rekoč: Eldad in Medad prorokujeta v taborišču!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 28, 'Tedaj izpregovori Jozue, sin Nunov, strežnik Mojzesov od mladosti svoje, in reče: Gospod moj Mojzes, brani jima!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 29, 'Mojzes pa mu reče: Kaj si tako vnet zame? O da bi vse ljudstvo Gospodovo bili proroki, da bi Gospod dal duha svojega nadnje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 30, 'In Mojzes krene proti taboru, on in starejšine Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 31, 'Tedaj pride veter od Gospoda in prinese prepelice od morja sem in jih spusti, da leté nad taboriščem, dan hoda po tej strani in dan hoda po oni strani okrog taborišča, dva komolca visoko nad zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 32, 'In ljudstvo vstane in nabirajo prepelice ves ta dan in vso noč in ves drugi dan. In kdor je najmanj nabral, je imel deset homerov; in razobešajo jih povsod okoli šatorišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 33, 'Še je bilo meso med njih zobmi, še ni bilo požrto, ko se vname srd Gospodov zoper ljudstvo, in Gospod udari ljudstvo s silno veliko šibo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 34, 'In imenovali so ime tega kraja Grobovi poželjivosti, ker so ondi pokopali ljudstvo, ki se je vdalo poželjivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 11, 35, 'Od Grobov poželjivosti je ljudstvo popotovalo v Hazerot, in ostali so v Hazerotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 1, 'In Mirjama in Aron sta govorila zoper Mojzesa zaradi kušitske žene, ki si jo je vzel; kajti oženil se je s kušitsko ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 2, 'In govorila sta: Ali je res Gospod govoril samo z Mojzesom? Ne govori li tudi z nami? In Gospod je slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 3, 'Bil pa je ta mož, Mojzes, zelo krotek, bolj kot vsi ljudje, ki so bili na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 4, 'In zdajci veli Gospod Mojzesu, Aronu in Mirjami: Pridite vi trije ven k shodnemu šatoru. In pridejo ti trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 5, 'In Gospod pride doli v oblakovem stebru in stopi k šatorovim vratom in pokliče Arona in Mirjamo. In pristopita oba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 6, 'In veli: Poslušajta besede moje: Če je kdo med vami prorok, njemu se dam jaz, Gospod, na znanje v prikazni, v sanjah bom govoril ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 7, 'Ali nikar tako hlapec moj, Mojzes; on je vsej hiši moji zvest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 8, 'Od ust do ust govorim ž njim, očitno in ne s temnimi besedami, in vidi podobo Gospodovo. Zakaj se torej nista bala govoriti zoper služabnika mojega, zoper Mojzesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 9, 'In vname se srd Gospodov zoper njiju, ter odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 10, 'In oblak se umakne iznad šatora. In glej, Mirjama je gobava, bela kakor sneg. In Aron se obrne k Mirjami, in glej, gobava je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 11, 'In Aron reče Mojzesu: Ah, gospod moj, prosim, ne nakladaj nama greha, ker sva nespametno ravnala in se pregrešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 12, 'Da ne bodi ona, prosim, kako mrtvo dete, čigar meso je napol trhlo, ko pride iz telesa matere svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 13, 'Tedaj zavpije Mojzes h Gospodu, rekoč: O Bog mogočni, prosim, ozdravi jo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 14, 'In Gospod reče Mojzesu: Ako bi ji bil njen oče pljunil v obraz, ali bi se ne morala sramovati sedem dni? Bodi torej zaprta zunaj taborišča sedem dni, in potem naj bo zopet sprejeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 15, 'In zaprli so Mirjamo zunaj taborišča sedem dni. Ljudstvo pa ni šlo naprej, dokler ni bila Mirjama zopet sprejeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 12, 16, 'Potem se je odpravilo ljudstvo iz Hazerota, in utaborili so se v puščavi Paranski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 2, 'Odpošlji može, da naj ogledajo deželo Kanaansko, ki jo dam sinovom Izraelovim; iz vsakega rodu njih očetov pošljite po enega moža, in sleherni bodi prvak med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 3, 'Nato jih je poslal Mojzes iz puščave Paranske po ukazu Gospodovem, samo take može, ki so bili glave Izraelovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 4, 'In ta so njih imena: za rod Rubenov Šamua, sin Zakurjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 5, 'za rod Simeonov Šafat, sin Horijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 6, 'za rod Judov Kaleb, sin Jefunov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 7, 'za rod Isaharjev Igal, sin Jožefov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 8, 'za rod Efraimov Hozea, sin Nunov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 9, 'za rod Benjaminov Palti, sin Rafujev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 10, 'za rod Zebulonov Gadiel, sin Sodijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 11, 'za rod Jožefov od rodu Manasejevega Gadi, sin Susijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 12, 'za rod Danov Amiel, sin Gemalijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 13, 'za rod Aserjev Setur, sin Mihaelov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 14, 'za rod Neftalijev Nahbi, sin Vofsijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 15, 'za rod Gadov Guel, sin Makijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 16, 'To so imena mož, ki jih je Mojzes poslal ogledovat deželo; Hozea pa, sina Nunovega, je imenoval Mojzes Jozueta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 17, 'In ko jih je Mojzes pošiljal ogledovat deželo Kanaansko, jim reče: Pojdite tod skozi Južno stran in stopite na gore,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 18, 'in oglejte si deželo, kakova je, ter ljudstvo, ki prebiva v njej, je li krepko ali slabotno, ga je li malo ali mnogo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 19, 'in kakšna je dežela, ki prebivajo v njej, je li dobra ali slaba, in kakšna so mesta, ki bivajo v njih, ali v šatorih ali v trdnjavah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 20, 'in kakšna zemlja, je li mastna ali puhličasta, ima li drevja ali ne. Hrabri bodite in prinesite sadu tiste dežele. Bil je pa čas zgodnjega grozdja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 21, 'Šli so torej gori in ogledali deželo od puščave Zinske tja do Rehoba, kjer se gre v Hamat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 22, 'Nato so šli skozi Južno stran in prispeli v Hebron, in tu so bili Ahiman, Sesaj in Talmaj, otroci Enakovi. Hebron pa je bil sezidan sedem let poprej nego Zoan v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 23, 'In prišli so do potoka Eškola in tu odrezali mladiko z enim grozdom, in nesli so ga na drogu po dva moža; nesli so tudi margaranovih jabolk in smokev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 24, 'Ta kraj se je imenoval potok Eškol zaradi grozda, ki so ga ondi odrezali sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 25, 'In ko so ogledali deželo, se vrnejo po štiridesetih dnevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 26, 'in gredo ter pridejo k Mojzesu in Aronu in k vsej občini Izraelovi v puščavo Paransko, v Kades; in prineso njima in vsej občini poročilo ter jim pokažejo sad dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 27, 'In pripovedujejo mu, govoreč: Prišli smo v deželo, kamor si nas poslal, in zares teče v njej mleko in med, in to je njen sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 28, 'Toda močno ljudstvo je, ki prebiva v njej, in mesta so trdna in prevelika, in vrhutega smo tam videli otroke Enakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 29, 'Amalek prebiva v pokrajini na jugu, Hetejci pa in Jebusejci in Amorejci prebivajo v gorah, a Kanaanci prebivajo ob morju in poleg Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 30, 'A Kaleb je tolažil ljudstvo pred Mojzesom in rekel: Dajte, da gremo gori in jo posedemo, zakaj prav lahko jo obvladamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 31, 'Ali možje, ki so bili šli gori ž njim, reko: Nikakor ne moremo iti gori proti tistemu ljudstvu, kajti močnejši so od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 32, 'In spravili so v slab glas deželo, ki so jo ogledali, med sinovi Izraelovimi, govoreč: Dežela, skozi katero smo šli, da si jo ogledamo, je dežela, ki požira prebivalce svoje, in kar smo videli ljudstva v njej, vsi so možje visoke postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 13, 33, 'Videli smo tam tudi velikane, sinove Enakove, ki so iz velikanov, in zdelo se nam je, da smo kakor kobilice, in taki smo tudi bili v njih hočeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 1, 'Tedaj zažene vsa občina krik in vpije, in ljustvo prejoka celo noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 2, 'In vsi sinovi Izraelovi mrmrajo zoper Mojzesa in Arona, in vsa občina jima govori: O da bi bili umrli v deželi Egiptovski ali da bi poginili v tej puščavi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 3, 'In zakaj nas vodi Gospod v to deželo, da pademo pod mečem? Žene naše in otročiči naši pridejo v plen: ni li nam bolje vrniti se v Egipt?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 4, 'In drug govori drugemu: Postavimo si poglavarja in pojdimo nazaj v Egipt?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 5, 'Tedaj padeta Mojzes in Aron z obličjem na zemljo pred vsem zborom občine sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 6, 'Jozue pa, sin Nunov, in Kaleb, sin Jefunov, ki sta tudi bila med ogledniki dežele, raztrgata oblačila svoja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 7, 'in rečeta vsej množici Izraelovih sinov: Dežela, ki smo jo prehodili, da si jo ogledamo, je jako dobra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 8, 'Če bomo po volji Gospodu, nas pripelje v tisto deželo ter nam jo dá, deželo, ki v njej teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 9, 'Samo ne upirajte se Gospodu, tudi se ne bojte ljudstva tiste dežele, kajti pojemo jih kakor kruh. Njih zaslomba se je od njih umeknila, a z nami je Gospod, ne bojte se jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 10, 'Tedaj se zgovarja vsa množica, da ju posujejo s kamenjem. Ali slava Gospodova se prikaže ob shodnem šatoru vsem sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 11, 'In Gospod reče Mojzesu: Doklej me bo zaničevalo to ljudstvo? in doklej ne bodo verovali v me po vseh tistih znamenjih, ki sem jih storil med njimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 12, 'Udariti jih hočem s kugo in zatreti, tebe pa storim v narod večji in močnejši, kakor je ta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 13, 'A Mojzes reče Gospodu: Ali Egipčani bodo to slišali, zakaj odpeljal si ljudstvo to v moči svoji izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 14, 'In povedali bodo to prebivalcem te dežele, ki so čuli, da si ti, Gospod, sredi tegale ljudstva, da se ti, Gospod, daješ videti iz obličja v obličje in da oblak tvoj stoji nad njimi in ti greš pred njimi v oblakovem stebru po dnevi in v ognjenem stebru po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 15, 'Ako torej usmrtiš to ljudstvo kakor enega moža, bodo govorili poganski narodi, ki so čuli tak glas o tebi, takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 16, 'Ker Gospodu ni bilo moči privesti tega ljudstva v deželo, ki jim jo s prisego obljubil, jih je pomoril v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 17, 'Naj se torej, prosim, velika izkaže moč Gospodova, kakor si govoril, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 18, 'Gospod je počasen za jezo in obilen v milosti, on odpušča krivico in prestopek, a krivca nikakor ne šteje za nedolžnega, temuč obiskuje očetov krivico na otrocih, v tretjem in četrtem pokolenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 19, 'Odpústi, prosim, krivico tega ljudstva po veliki milosti svoji in kakor si prizanašal temu ljudstvu od Egipta do semkaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 20, 'In Gospod reče: Odpustil sem, kakor si dejal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 21, 'Ali zares, kakor živim in kakor bo slave Gospodove napolnjena vsa zemlja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 22, 'ker so me vsi tisti možje, ki so videli slavo mojo in znamenja moja, katera sem storil v Egiptu in v puščavi, sedaj že desetkrat izkušali in glasu mojega niso poslušali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 23, 'nikakor ne bodo videli dežele, za katero sem prisegel njih očetom; vsi, ki so me zaničevali, je ne bodo videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 24, 'Ampak služabnika svojega Kaleba, ker je bil v njem drug duh in je zvesto hodil za menoj, njega hočem privesti v deželo, v katero je bil šel, in seme njegovo jo bo imelo v lasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 25, 'Amalekovci pa in Kanaanci prebivajo v oni dolini; jutri se obrnite in pojdite v puščavo po potu k Rdečemu morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 26, 'In Gospod ogovori Mojzesa in Arona, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 27, 'Kako dolgo naj prenašam to hudo množico, ki mrmra zoper mene? Slišal sem mrmranje sinov Izraelovih, koliko so godrnjali zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 28, 'Véli jim: Kakor res živim, pravi Gospod: kakor ste govorili na ušesa moja, prav tako vam hočem storiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 29, 'V tej puščavi bodo popadala trupla vaša; in kar vas je seštetih po vsem številu vašem, od dvajsetletnih in više, ki ste mrmrali zoper mene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 30, 'nikoli ne pridete v deželo, za katero sem povzdignil roko in prisegel, da vam dam prebivati v njej, razen Kaleba, sina Jefunovega, in Jozueta, sina Nunovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 31, 'Vaše otročiče pa, o katerih ste dejali, da pridejo v plen, nje popeljem tja, in uživali bodo deželo, ki ste jo vi zavrgli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 32, 'A vaša trupla bodo popadala v tej puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 33, 'In otroci vaši bodo pastirjevali po puščavi štirideset let in nosili kazen nečistosti vaše, dokler ne bo vaših trupel konec v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 34, 'Po številu štiridesetih dni, v katerih ste ogledovali deželo, za vsak dan eno leto, morate nositi krivice svoje štirideset let, in spoznate, kaj je to, ko se jaz odvrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 35, 'Jaz Gospod sem govoril; gotovo storim to vsej tej hudobni množici, ki se je zbrala zoper mene. V tej puščavi naj vzamejo konec in tu pomrjejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 36, 'In možje, ki jih je bil Mojzes poslal ogledovat deželo in ki so, ko so se bili vrnili, napeljali vso občino, da godrnja zoper njega, s tem, da so dali slab glas o deželi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 37, 'ti možje, pravim, ki so v slab glas pripravili deželo, so umrli od šibe pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 38, 'A Jozue, sin Nunov, in Kaleb, sin Jefunov, sta ostala živa izmed onih mož, ki so bili šli ogledovat deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 39, 'In Mojzes je govoril te besede vsem sinovom Izraelovim, in ljudstvo je silno žalovalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 40, 'In vstanejo navsezgodaj ter odrinejo na vrh gorovja in reko: Glej, tu smo in hočemo iti v kraj, ki ga je Gospod obljubil; zakaj grešili smo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 41, 'Mojzes pa reče: Zakaj tako prestopate besedo Gospodovo? Ne boste v tem imeli sreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 42, 'Ne hodite tja gori, zakaj Gospod ni sredi vas; da vas ne pobijejo sovražniki vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 43, 'Kajti Amalekovci in Kanaanci so tu pred vami, in padli boste pod mečem; ker ste se odvrnili, ne hoteč iti za Gospodom, ne bode Gospod z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 44, 'Oni pa so vendar v svoji prevzetnosti šli vrh gorovja; ali Gospodova skrinja zaveze in Mojzes se nista genila iz taborišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 14, 45, 'Tedaj pridejo Amalekovci in Kanaanci, ki so prebivali na onem gorovju, in jih porazijo ter razkrope prav do Horme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 2, 'Govóri sinovom Izraelovim in jim reci: Ko pridete v deželo domovanja svojega, ki vam jo dam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 3, 'in se namenite prinesti Gospodu ognjeno daritev, bodisi žgalščino ali klalščino, v izpolnjenje posebne obljube, ali v prostovoljen dar, ali v daritev ob praznikih vaših, da pripravite prijeten duh Gospodu od govedi ali drobnice:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 4, 'kdor hoče darovati darilo svoje Gospodu, naj prinese kot jedilno daritev desetinko bele moke, omešene s četrtino hina olja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 5, 'in vina v pitno daritev prinesi četrtino hina pri žgalščini ali klalščini, za vsako jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 6, 'Ali za ovna prinesi kot jedilno daritev dve desetinki bele moke, omešene s tretjino hina olja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 7, 'in kot pitno daritev prinesi tretjino hina vina, v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 8, 'Ako pa hočeš darovati vola v žgalščino ali klalščino kot posebno obljubo ali kot mirovno daritev Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 9, 'naj se z volom vred daruje jedilna daritev, tri desetinke bele moke, omešene s polovico hina olja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 10, 'kot pitno daritev pa prinesi polovico hina vina; to bodi ognjena daritev Gospodu v prijeten duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 11, 'Tako naj se stori pri vsakem volu, vsakem ovnu, vsaki ovci ali kozi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 12, 'Kolikorkoli jih boste darovali, pri slehernem storite takisto po njih številu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 13, 'Vsak deželjan naj to izvršuje prav tako, ko prinaša ognjeno daritev v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 14, 'In če biva tujec pri vas ali kdorkoli bi bil med vami v prihodnjih rodovih vaših in hoče prinesti ognjeno daritev v prijeten duh Gospodu, prav tako naj opravi, kakor vi opravljate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 15, 'O zbor, ena postava veljaj za vas in za tujca, gostujočega pri vas, večna postava vam od roda do roda: kakor vi, bodi tujec pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 16, 'En zakon in ena pravica veljajta vam in tujcu, ki gostuje pri vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 17, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 18, 'Govori sinovom Izraelovim in jim reci: Ko pridete v deželo, v katero vas vodim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 19, 'in boste uživali kruh dežele, poklonite dar povzdignjenja Gospodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 20, 'od prvine testa svojega dajte kolač kot dar povzdignjenja; darujte ga, kakor darujete dar povzdignjenja od gumna svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 21, 'Od prvine testa svojega prinašajte dar povzdignjenja Gospodu od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 22, 'In ako se nehotoma pregrešite in ne izpolnite katere teh zaspovedi, ki jih je Gospod govoril Mojzesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 23, 'vseh reči, ki vam jih je Gospod zapovedal po Mojzesu, od dne, ko je ukazal Gospod, in poslej po vseh prihodnjih rodovih vaših:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 24, 'ako se torej kaj zgodi po pomoti, brez vednosti občine, naj daruje vsa občina mladega voliča kot žgalno daritev v prijeten duh Gospodu z jedilno in pitno daritvijo, ki pristoji, kakor je določeno, in kozla v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 25, 'In duhovnik naj stori poravnavo za vso sinov Izraelovih občino, in bo jim odpuščeno; zakaj pomota je bila, in oni so prinesli darilo svoje, ognjeno daritev Gospodu in daritev za greh pred obličje Gospodovo, za pomoto svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 26, 'In vsej občini sinov Izraelovih bode odpuščeno, tudi tujcu, ki biva med njimi, ker je to bil vsega ljudstva pregrešek po pomoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 27, 'Ako se pa poedinec pregreši po pomoti, naj daruje enoletno kozo v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 28, 'In duhovnik naj stori poravnavo za dušo, ki se je pomotila, nehotoma storivši greh pred Gospodom, da jo spravi, in bo ji odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 29, 'En zakon veljaj za tiste, ki store kaj po pomoti, za rojaka med sinovi Izraelovimi in za tujca, ki biva med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 30, 'Toda če kdo kaj stori nalašč, bodisi domačin ali tujec, zasmehuje grdo Gospoda; tak bodi iztrebljen izmed ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 31, 'Zakaj besedo Gospodovo je zaničeval in prelomil zapoved njegovo; tak mora biti iztrebljen, krivica njegova ostani na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 32, 'In ko so bili sinovi Izraelovi v puščavi, zaloté moža, ki je nabiral drva sobotni dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 33, 'In tisti, ki so ga zasačili, ko je nabiral drva, ga privedejo k Mojzesu in Aronu in k vsej občini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 34, 'In ga denejo v zapor, ker ni bilo natanko določeno, kaj naj se stori ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 35, 'Tedaj veli Gospod Mojzesu: Umreti mora ta mož; s kamenjem naj ga posuje vsa občina zunaj taborišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 36, 'Odpelje ga torej vsa občina ven iz tabora ter ga posuje s kamenjem, da je umrl, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 37, 'In govoril je Gospod Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 38, 'Govóri sinovom Izraelovim in jim véli, naj si delajo šopke na voglih svojih plaščev po vseh rodovih svojih ter naj privežejo šopek k vsakemu voglu z višnjevo vrvico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 39, 'In imejte te šopke za to, da se, videč jih spominjate vseh zapovedi Gospodovih ter jih izpolnjujete in da se ne vdajate srcu svojemu in očem svojim, ki vas vlečejo v nezvestobo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 40, 'ampak da se spominjate vseh zapovedi mojih ter jih izpolnjujete in sveti bodete Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 15, 41, 'Jaz sem Gospod, Bog vaš, ki sem vas odpeljal iz dežele Egiptovske, da bi vam bil Bog; jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 1, 'Korah pa, sin Izharja, sinu Kahata, sinu Levijevega, se poprime upora in Datan in Abiram, sinova Eliabova, in On, sin Peletov, sinovi Rubenovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 2, 'in se vzdignejo proti Mojzesu z dvestoinpetdesetimi možmi izmed sinov Izraelovih, ki so bili prvaki v občini, pooblaščenci zbora, možje imenitni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 3, 'In zbero se zoper Mojzesa in Arona in ju ogovore: Dosti vama naj bo! Zakaj vsa občina, vsi so svetniki, in Gospod je sredi njih. Zakaj se vidva povzdigujeta nad zbor Gospodov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 4, 'In ko Mojzes to sliši, pade na obraz svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 5, 'In izpregovori Korahu in vsej družbi njegovi, rekoč: Jutri pokaže Gospod, kdo je njegov in kdo je svet in se Mu sme bližati; njemu, kogar si izvoli, veli, naj se Mu bliža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 6, 'Storite to: Vzemite si kadilnice, Korah in vsa družba njegova,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 7, 'in vložite vanje ognja ter denite nanj kadila jutri pred Gospodom; in mož, ki si ga izvoli Gospod, ta bodi svetnik. Dosti naj vam bode, sinovi Levijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 8, 'In Mojzes reče Korahu: Čujte, pravim, sinovi Levijevi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 9, 'Ali vam je premalo, da je prav vas Bog Izraelov odločil iz občine Izraelove, veleč, da bodite blizu njega, da bi opravljali službo pri prebivališču Gospodovem ter stopali pred občino, da jim strežete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 10, 'Premalo li je da je k sebi dovolil pristop tebi in vsem bratom tvojim s teboj? Iščete li še tudi duhovništva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 11, 'Zares, prav zoper Gospoda ste se zbrali, ti in vsa družba tvoja. Kaj neki je Aron, da zoper njega mrmrate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 12, 'In Mojzes pošlje klicat Datana in Abirama, sinova Eliabova; a odvrneta: Midva ne greva tja gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 13, 'Je li premalo, da si nas peljal iz dežele, v kateri teče mleko in med, da nas pomoriš v puščavi? Hočeš li se vzdigniti celo še za vladarja nad nami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 14, 'Saj nas nisi pripeljal v deželo, v kateri teče mleko in med, in nisi nam dal njiv in vinogradov v posest! Hočeš li še oči izdreti tem ljudem? Midva ne greva tja gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 15, 'Tedaj se silno razsrdi Mojzes in reče Gospodu: Ne ozri se na njih jedilno daritev. Niti osliča nisem vzel od njih in nikoli nikomur izmed njih nisem storil kaj žalega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 16, 'Nato veli Mojzes Korahu: Ti in vsa družba tvoja stopite jutri pred Gospoda, ti, oni in Aron,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 17, 'in vsakteri vzemi kadilnico svojo in deni vanjo kadila, in prinesite pred Gospoda vsak svojo kadilnico, torej dvestoinpetdeset kadilnic, tudi ti in Aron, vsak svojo kadilnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 18, 'Vzame torej vsak svojo kadilnico ter položi vanjo ognja in dene nanj kadila, in postavijo se pri vhodu shodnega šatora z Mojzesom in Aronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 19, 'In Korah zbere zoper njiju vso občino pred vhod shodnega šatora. A slava Gospodova se prikaže vsej množici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 20, 'Tedaj ogovori Gospod Mojzesa in Arona, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 21, 'Ločita se iz te občine, da jih namah pokončam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 22, 'Ona pa padeta na obličje svoje ter vzklikneta: O Bog mogočni, Bog duhov vsega mesa! Ta eden greši, in hočeš se li jeziti nad občino vso?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 23, 'Nato veli Gospod Mojzesu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 24, 'Govori občini in reci: Umeknite se iz okoliša šatora Korahovega, Datanovega in Abiramovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 25, 'In Mojzes vstane in gre k Datanu in Abiramu, in starejšine Izraelovi ga spremljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 26, 'In ogovori občino, rekoč: Odstopite, prosim, od šatorov teh brezbožnih ljudi in ne doteknite se nobene njih reči, da ne poginete v vseh njih grehih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 27, 'In umaknejo se od bivališč Koraha, Datana in Abirama na vseh straneh; Datan in Abiram pa prideta ven ter se postavita ob vhodu šatorov svojih s svojima ženama in s sinovi in otročiči svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 28, 'In Mojzes reče: Po tem spoznate, da me je Gospod poslal, da naj izvršim vsa ta dela, in da niso prišla iz mojega srca:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 29, 'Ako umrjo ti z navadno smrtjo vseh ljudi in bodo kaznovani, kakor se kaznujejo vsi ljudje, tedaj me ni poslal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 30, 'Ako pa ustvari Gospod novo stvar, da odpre zemlja svoje žrelo ter jih požre z vsem, kar imajo, da se živi pogreznejo v kraj mrtvih: tedaj spoznajte, da so ti možje zaničevali Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 31, 'In zgodi se, brž ko je izgovoril vse te besede, da razpoknejo tla pod njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 32, 'in zemlja odpre svoje žrelo ter jih požre ž njih družinami in vsemi pristaši Korahovimi in z vsem, kar so imeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 33, 'Tako se pogreznejo z vsem, kar so imeli, živi v kraj mrtvih, in zemlja se zapre nad njimi, in poginili so izmed občine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 34, 'In vsi Izraelci, ki so bili okoli njih, zbeže ob njih vpitju; zakaj dejali so: Da nas ne požre zemlja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 35, 'Pa tudi ogenj šine od Gospoda in požre tistih dvesto in petdeset mož, ki so darovali kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 36, 'Tedaj ogovori Gospod Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 37, 'Véli Eleazarju, sinu Arona duhovnika, naj pobere kadilnice na pogorišču, ogenj pa raztresi tja daleč; kajti posvečene so,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 38, 'namreč kadilnice onih grešnikov, ki so grešili zoper duše svoje, in razkuj jih na široke ploče v prevleko oltarja; ker so v njih darovali pred Gospodom, zato so svete, in naj bodo v znamenje sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 39, 'Vzame torej Eleazar, duhovnik, bronaste kadilnice, v katerih so darovali tisti, ki jih je požrl ogenj, in jih razkuje v prevleko oltarja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 40, 'za spomin sinovom Izraelovim, da naj ne pristopa zažigat kadila pred Gospodom noben nepoklicanec, ki ni iz rodu Aronovega, ker bi se mu zgodilo kakor Korahu in družbi njegovi - kakor mu je bil naročil Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 41, 'A drugi dan je mrmrala vsa občina sinov Izraelovih zoper Mojzesa in Arona, govoreč: Vidva sta usmrtila ljudstvo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 42, 'In zgodi se, ko se je vsa množica zbirala zoper Mojzesa in Arona, da se ozro proti shodnemu šatoru, in glej, oblak ga pokrije in slava Gospodova se prikaže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 43, 'V tem prideta Mojzes in Aron k pročelju shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 44, 'In Gospod ogovori Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 45, 'Umeknita se izmed te občine, da jih namah pokončam. Tedaj padeta na obličje svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 46, 'In Mojzes veli Aronu: Vzemi kadilnico svojo in položi vanjo ognja z oltarja in deni nanj kadila in hitro nesi med občino ter stóri spravo zanje, zakaj jeza je že prišla od Gospoda, šiba že razsaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 47, 'Aron jo vzame, kakor je Mojzes rekel, in teče med zbor, in glej, šiba je že pokončavala med ljudstvom, in dene vanjo kadila ter stori spravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 48, 'In stal je med mrtvimi in živimi, in šiba je bila ustavljena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 49, 'Tistih pa, ki so umrli v tem pomoru, je bilo štirinajst tisoč in sedemsto, razen onih, ki so umrli zaradi Koraha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 16, 50, 'In Aron se vrne k Mojzesu k vratom shodnega šatora, in šiba je bila ustavljena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 1, 'Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 2, 'Govori sinovom Izraelovim in vzemi od njih palice, eno za vsako očetovsko hišo, od vseh njih knezov po hišah njih očetov, torej dvanajst palic, in vsakega ime zapiši na palico njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 3, 'Ime Aronovo pa zapiši na palico Levijevo; zakaj ena palica bode za vsakega, ki je glava v očetovski hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 4, 'In položi jih v shodni šator pred pričevanje, kjer se shajam z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 5, 'In zgodi se, da njemu, kogar si izvolim, razcvete palica; tako utolažim in zvalim od sebe mrmranje sinov Izraelovih, s katerim mrmrajo zoper vaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 6, 'In Mojzes govori to sinovom Izraelovim, in vsi njih knezi mu izroče palice, za vsakega kneza eno, po njih očetovskih hišah, dvanajst palic, tudi Aronova palica je bila med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 7, 'Mojzes pa položi te palice pred Gospoda v šator pričevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 8, 'In drugi dan pride Mojzes v šator pričevanja, in glej: palica Aronova za hišo Levijevo je bila v cvetu: pognala je brstje in cvetje in rodila zrele mandlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 9, 'In prinese Mojzes vse palice izpred Gospoda vsem sinovom Izraelovim, in so jih videli in vsak je prejel palico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 10, 'Gospod pa reče Mojzesu: Palico Aronovo nesi nazaj pred pričevanje, da se ohrani v znamenje za te uporne otroke; da napraviš konec njih mrmranju pred menoj, da ne umrjejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 11, 'Mojzes stori tako; kakor mu je Gospod zapovedal, tako stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 12, 'In sinovi Izraelovi ogovore Mojzesa, rekoč: Glej, mrjemo in ginemo, da, mi vsi poginemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 17, 13, 'Kdorkoli se približa, kdor pristopi k prebivališču Gospodovemu, umrje. Je li torej nam vsem poginiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 1, 'In Gospod reče Aronu: Ti in sinovi tvoji in očeta tvojega hiša s teboj boste nosili pregrehe zoper svetišče; ti pa in sinovi tvoji boste nosili pregrehe duhovstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 2, 'Tudi brate svoje, rod Levijev, rod očeta svojega, postavi bliže Bogu pri sebi, da se te oklepajo in ti strežejo; ali ti in sinovi tvoji s teboj bodite pred šatorom pričevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 3, 'In naj strežejo v tvoji straži in v straži vsega šatora; samo naj se ne bližajo posodam svetišča in oltarju, da ne umrjo, ne oni, ne vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 4, 'Naj bodo torej združeni s teboj in naj strežejo v straži shodnega šatora, za vsako službo pri šatoru; nepoklicanec pa naj se vanj ne približa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 5, 'Tako strezite v straži pri svetišču in oltarju, da ne pride več jeza nad sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 6, 'Saj jaz sem, glejte, vzel levite, brate vaše, izmed sinov Izraelovih: vam so v dar, Gospodu dani v last, da opravljajo službo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 7, 'Ti pa in sinovi tvoji pazite na duhovsko službo svojo pri vsakterem opravilu ob oltarju in notri za pregrinjalom; tako torej služite. Kot službo vam dajem duhovništvo v darilo. Nepoklicanec pa, ki se približa, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 8, 'In Gospod je govoril Aronu: Glej, jaz sem ti dal oskrbovati daritve povzdignjenja meni; od vseh svetih reči Izraelovih sem jih dal kot delež maziljenja tebi in sinovom tvojim po večni postavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 9, 'To bodi tvoje od presvetih reči, kar ne pride na ogenj: vsako njih darilo pri vseh njih jedilnih daritvah in vseh daritvah za greh in za krivdo, ki mi jih prinašajo; to bodi presveto tebi in sinovom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 10, 'Kot presveto uživaj to: vsak moški naj jé od tega, ker sveto bode tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 11, 'In to bodi tvoje kot podvig njih darila: vse daritve majanja sinov Izraelovih sem dal tebi in sinovom in hčeram tvojim s teboj kot vekomaj ti odmenjeno: vsak, kdor je čist v hiši tvoji, sme jesti od tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 12, 'Vse najboljše od olja in vse najboljše od mošta in žita, njih prvine, ki jih dajejo Gospodu, sem dal tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 13, 'Prvine od vsega, kar je v njih deželi, kar prinašajo Gospodu, naj bodo tvoje; vsak čisti v hiši tvoji jih sme jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 14, 'Vse, kar se z zaroto posveti Gospodu v Izraelu, bodi tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 15, 'Karkoli pride prvo iz materinega telesa, od vsakterega mesa, kar prinašajo Gospodu, bodisi človečje ali živalsko, bodi tvoje; toda za prvorojeno od človeka prejmi odkupnino, tudi za prvostorjeno od nečiste živali prejmi odkupnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 16, 'Kar jih je odkupiti, ukaži odkupiti, ko so mesec dni stari, po cenitvi tvoji za pet seklov srebra, po seklu svetišča, ki ima dvajset ger.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 17, 'Ali prvostorjenega od goveda ali od ovce ali od koze ne daj odkupiti, sveto je namreč: njih kri razškropi po oltarju in njih tolstino zažgi kot ognjeno daritev v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 18, 'Njih meso pa bodi tvoje, kakor so tvoje prsi majanja in desno stegno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 19, 'Vse svete dari povzdignjenja, ki jih sinovi Izraelovi darujejo Gospodu, sem dal tebi in sinovom in hčeram tvojim s teboj po večni postavi. To je večna solna zaveza pred Gospodom zate in za seme tvoje s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 20, 'Še reče Gospod Aronu: V njih deželi ne boš imel dediščine, tudi deleža ne bo zate med njimi; jaz sem tvoj delež in dediščina tvoja med sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 21, 'Ali glej, sinovom Levijevim sem dal vse desetine v Izraelu v dediščino za njih službo, s katero mi strežejo, za službo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 22, 'Zato naj sinovi Izraelovi poslej ne pristopajo k shodnemu šatoru, da si ne nalože greha ter ne umrjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 23, 'A leviti naj skrbe za službo pri shodnem šatoru, in nosili bodo onih pregrehe: večna to bodi postava za prihodnje rodove vaše. Med sinovi Izraelovimi pa naj ne imajo dediščine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 24, 'kajti desetino sinov Izraelovih, ki jo prineso Gospodu kot dar povzdignjenja, sem dal levitom v dediščino; zatorej sem jim rekel: Med sinovi Izraelovimi vam ne bodi nobene dediščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 25, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 26, 'Govóri sinovom Levijevim in jim reci: Ko boste prejemali od sinov Izraelovih desetino, ki sem vam jo dal v vašo dediščino, prinašajte od nje dar povzdignjenja Gospodu: desetino od desetine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 27, 'In vaš dar povzdignjenja se vam bo štel, kakor da bi dali žita z gumna in obilnosti iz tlačilnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 28, 'Tako prinašajte tudi vi Gospodu dar povzdignjenja od vseh desetin svojih, ki jih prejemate od sinov Izraelovih; od njih torej dajajte Gospodov dar povzdignjenja Aronu duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 29, 'Od vsega, kar prejmete v dar, darujte Gospodu vselešnji dar povzdignjenja, od vsega, kar je najboljšega v tem in kar je posvečenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 30, 'Zato jim reci: Ko prinesete najboljše od tistega, se bo štelo levitom kakor pridelek gumna in pridelek tlačilnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 31, 'In jesti smete to na vsakterem mestu, vi in družine vaše, zakaj plačilo vaše je za službo vašo pri shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 18, 32, 'Tako si ne naložite greha, ko prinesete najboljše od tega v dar povzdignjenja; in svetih reči sinov Izraelovih ne smete onesvetiti, da ne umrjete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 1, 'In Gospod je govoril Mojzesu in Aronu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 2, 'To je naredba zakona, ki ga je zapovedal Gospod, govoreč: Govóri sinovom Izraelovim, naj ti pripeljejo rdečo junico, popolnoma zdravo, na kateri ni hibe in ki še ni nosila jarma;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 3, 'in izročite jo Eleazarju duhovniku, in on jo pelji ven za šatorišče, kjer naj jo zakoljejo pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 4, 'Nato naj vzame Eleazar duhovnik njene krvi s prstom svojim in škropi ž njeno krvjo ravno proti shodnemu šatoru sedemkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 5, 'In ukaže sežgati junico sebi pred očmi; njeno kožo, njeno meso in njeno kri ž njenim blatom vred naj sežgó.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 6, 'In duhovnik vzemi cedrovega lesa in izopa in karmezinove volne in vrzi to v plamen, ki požira junico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 7, 'In duhovnik naj si opere oblačila in si izkoplje v vodi telo in potem pride v tabor; in bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 8, 'In tisti, ki jo je sežgal, naj si opere oblačila ter izkoplje telo v vodi, in bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 9, 'In čist mož, naj pobere pepel junice in ga izsuje zunaj šatorišča na čist kraj, in naj se shrani občini sinov Izraelovih za vodo očiščevanja; daritev za greh je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 10, 'Tisti pa, ki je pobral junice pepel, naj si opere oblačila, in bode nečist do večera. To bodi sinovom Izraelovim in tujcu, ki biva med njimi, večna postava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 11, 'Kdor se dotakne mrliča, trupla kateregakoli človeka, bodi nečist sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 12, 'Ta naj se s tisto vodo očisti greha tretji in sedmi dan, in bode čist; ako se ne očisti tretji in sedmi dan, ne bode čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 13, 'Kdorkoli se dotakne trupla mrtvega človeka, pa se ne mara očistiti greha, onečisti s tem prebivališče Gospodovo; taka duša bodi iztrebljena iz Izraela, ker ni bil poškropljen z vodo očiščevanja: nečist bode, nečistota njegova ostane na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 14, 'To je postava, kadar umrje človek v šatoru: kdorkoli pride v šator in kdorkoli je v šatoru, bodi nečist sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 15, 'In vsaka odprta posoda, ki nima privezanega pokrova, je nečista.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 16, 'Tudi kdor se na polju dotakne z mečem ubitega ali mrtveca ali kosti človeške ali groba, bode nečist sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 17, 'In za nečistega naj se vzame pepela tiste sežgane junice za greh in se nanj v posodo vlije tekoča voda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 18, 'In čist mož vzemi izopa in ga omoči v vodi ter poškropi ž njo šator in vse posode in vse osebe, ki so bile v njem, tudi njega, ki se je dotaknil kosti ali ubitega ali mrtveca ali groba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 19, 'Čisti mož naj poškropi nečistega tretji in sedmi dan in ga očisti greha dan sedmi, in opere naj si oblačila in se izkoplje v vodi, in bode čist zvečer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 20, 'Kdor pa je nečist in se ne mara očistiti greha, tega duša bodi iztrebljena izmed zbora, zakaj onečistil je svetišče Gospodovo in z vodo očiščevanja ni bil poškropljen, nečist je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 21, 'In to jim bodi večna postava; kdor pa je škropil z vodo očiščevanja, naj si opere oblačila, in kdor se dotakne vode očiščevanja, bodi nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 19, 22, 'In vse, česar se dotakne nečisti, bode nečisto, in kdorkoli se njega dotakne, bode nečist do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 1, 'In vsa množica sinov Izraelovih je prišla v puščavo Zinsko v prvem mesecu, in ljudstvo je ostalo v Kadesu. Tu je umrla Mirjama in tu je bila pokopana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 2, 'In ni bilo vode za občino; zbrali so se torej zoper Mojzesa in Arona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 3, 'In prepiralo se je ljudstvo z Mojzesom, govoreč: O da bi bili poginili, ko so poginili bratje naši pred Gospodom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 4, 'Zakaj sta privedla zbor Gospodov v to puščavo, da tu umrjemo, mi in živina naša?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 5, 'In zakaj sta nas peljala gori iz Egipta, da nas spravita v ta slabi kraj, ki se ne da obsejati, ki ne rodi ne smokev, ne trte, ne margaranovih jabolk, še grla si tu ne moremo omočiti z vodo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 6, 'Tedaj se umakneta Mojzes in Aron izpred zbora k vratom shodnega šatora in padeta na obličje svoje; in prikaže se jima slava Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 7, 'In Gospod ogovori Mojzesa, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 8, 'Vzemi palico in skliči občino, ti in Aron, brat tvoj, in govorita skali pred njih očmi, da naj dá vode svoje. Tako jim izpelji vodo iz skale in napoji občino in njih živino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 9, 'Vzame torej Mojzes palico izpred Gospoda, kakor mu je bil zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 10, 'In Mojzes in Aron skličeta zbor pred skalo, in jim reče: Čujte vendar, uporneži! Bova li vam izpeljala vodo iz te skale?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 11, 'In vzdigne Mojzes roko in udari ob skalo dvakrat s palico svojo, in vode privre obilo, in občina je pila in njih živina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 12, 'A Gospod reče Mojzesu in Aronu: Ker nista verovala vame, da bi me svetega izkazala vpričo sinov Izraelovih, zato ne dovodita te občine v deželo, ki sem jo jim dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 13, 'To je voda Meriba, ker so se tam prepirali sinovi Izraelovi z Gospodom, in on se je izkazal svetega pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 14, 'In Mojzes pošlje selstvo iz Kadesa do kralja edomskega: Tako pravi brat tvoj Izrael: Ti poznaš vse težave, ki so nas zadele:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 15, 'kako so šli očetje naši doli v Egipt, in prebivali smo v Egiptu dolgo časa, a Egipčani so hudo ravnali z nami in z očeti našimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 16, 'In ko smo vpili h Gospodu, je uslišal naš glas ter poslal angela in nas peljal iz Egipta. In glej smo v mestu Kadesu ob skrajni meji tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 17, 'Dovoli nam, prosimo, iti skozi deželo tvojo: ne pojdemo čez njive ali skozi vinograde, tudi ne bomo pili vodo iz vodnjakov; po kraljevi cesti pojdemo in ne krenemo ne na desno, ne na levo, dokler ne prestopimo mej tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 18, 'Edom pa mu odgovori: Ne hodi čez moje, sicer ti pridem naproti z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 19, 'In sinovi Izraelovi mu reko: Radi bi šli po uglajenem potu, in ako bomo pili vode tvoje, mi in naša živina, hočemo plačati; ničesar več – samo da pojdemo peš skozi pokrajino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 20, 'On pa reče: Ne pojdeš skozi njo. In mu pride Edom nasproti z mnogim ljudstvom in z močno roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 21, 'Tako se je branil Edom dovoliti Izraelu prehod skozi pokrajino svojo; zato se mu je izognil Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 22, 'Odrinejo torej iz Kadesa, in vsa množica sinov Izraelovih pride h gori Horu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 23, 'In Gospod ogovori Mojzesa in Arona na gori Horu ob meji pokrajine Edomske, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 24, 'Aron se mora pridružiti ljudstvu svojemu, zakaj ne pride v deželo, ki sem jo dal sinovom Izraelovim, ker sta se upirala povelju mojemu pri vodi Meribi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 25, 'Vzemi Arona in sinu njegovega Eleazarja ter ju pelji vrh gore Hora,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 26, 'in sleci Aronu oblačila njegova in obleci vanje Eleazarja, sina njegovega. In Aron bo zbran k ljudstvu svojemu in tam umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 27, 'Tedaj stori Mojzes, kakor mu je bil zapovedal Gospod, in šli so na goro Hor pred očmi vse občine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 28, 'In Mojzes sleče Aronu oblačila njegova in obleče vanje Eleazarja, sina njegovega. Tam je umrl Aron na vrhu gore. Mojzes pa in Eleazar stopita doli z gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 20, 29, 'In ko je videla vsa občina, da je Aron mrtev, je jokala po njem trideset dni vsa hiša Izraelova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 1, 'In ko začuje Kanaanec, kralj v Aradu, ki je prebival proti jugu, da prihaja Izrael po poti oglednikov, začne vojno z Izraelom in nekatere izmed njih odpelje ujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 2, 'Tedaj se Izrael zaobljubi Gospodu, govoreč: Ako mi daš res to ljudstvo v roko, s prokletjem razderem njegova mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 3, 'In Gospod usliši glas Izraelov ter mu da Kanaance; in pokonča s prokletjem nje in njih mesta; zato so imenovali ta kraj Horma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 4, 'In šli so od gore Hora po poti, ki vodi k Rdečemu morju, da bi obšli deželo Edomsko. In ljudstvo je postalo malosrčno na potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 5, 'In govori ljudstvo zoper Boga in zoper Mojzesa: Zakaj ste nas peljali iz Egipta, da umrjemo v puščavi? kajti tu ni kruha, ne vode; in duši naši se že studi tista prelahka jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 6, 'Tedaj pošlje Gospod ognjene kače med ljudstvo, in so jih pikale, da jih je mnogo pomrlo iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 7, 'In pride ljudstvo k Mojzesu, govoreč: Grešili smo, ko smo govorili zoper Gospoda in zoper tebe; moli h Gospodu, da vzame od nas kače. In Mojzes je molil za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 8, 'In Gospod veli Mojzesu: Naredi si ognjeno kačo in jo povzdigni na drog; in vsak, kdor je pičen in jo pogleda, bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 9, 'Mojzes torej naredi kačo iz brona in jo povzdigne na drog. In bilo je tako: če je koga kača pičila in ta je pogledal na bronasto kačo, je živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 10, 'In odpotujejo sinovi Izraelovi in se raztabore v Obotu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 11, 'in iz Obota odrinejo in se utabore v Ije-abarimu, v puščavi, ki je pred Moabom, proti solnčnemu vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 12, 'Odtod odrinejo in se ušatorijo pri potoku Zeredu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 13, 'Ko odidejo odtod, se ušatore onkraj potoka Arnona, ki je v puščavi in prihaja iz pokrajine Amorejcev, zakaj Arnon je na meji moabski, med Moabom in Amorejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 14, 'Zato se pravi v knjigi o vojskah Gospodovih: Pribojevali smo Vaheb v Sufi in Arnonske doline');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 15, 'in strmine ob potokih, ki segajo do bivališča Ara in se naslanjajo na mejo moabsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 16, 'In odtod so šli v Ber, to je tisti vodnjak, o katerem je rekel Gospod Mojzesu: Skliči mi ljudstvo, in hočem jim dati vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 17, 'Takrat je pel Izrael to pesem: Privri, o studenec! Prepevajte mu naproti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 18, 'Vodnjak, ki so ga knezi izkopali, ki so ga plemenitniki ljudstva zaokrožili z žezlom, s palicami svojimi. - In iz puščave so šli v Matano,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 19, 'in iz Matane v Nahaliel, in iz Nahaliela v Bamot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 20, 'in iz Bamota v dolino, ki je na poljani Moabski, do vrha Pizge, ki strmi kvišku nad puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 21, 'In Izrael pošlje poročnike k Sihonu, kralju Amorejcev, da mu reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 22, 'Dovoli mi iti skozi deželo tvojo; nočemo kreniti na njive ali v vinograde, tudi ne piti vode iz vodnjakov; po kraljevi cesti pojdemo, dokler ne prestopimo tvojih mej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 23, 'Toda Sihon ni pripustil Izraelu iti skozi pokrajino svojo; temuč zbere vse ljudstvo svoje in pride Izraelu nasproti v puščavo. In ko prispe v Jahaz, se vojskuje z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 24, 'A Izrael ga udari z ostrino meča in posede deželo njegovo od Arnona do Jaboka in tja do sinov Amonovih; meja sinov Amonovih je namreč bila utrjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 25, 'In Izrael je zasedel vsa ta mesta in se naselil v vseh mestih Amorejcev, v Hesbonu in vseh njemu podložnih vaseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 26, 'Hesbon je namreč bilo mesto Sihona, kralja Amorejcev, ki se je bil bojeval zoper prejšnjega kralja Moabcev in mu odvzel vso pokrajino njegovo prav do Arnona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 27, 'Zato pravijo pesniki: Pridite v Hesbon, naj se zgradi in postavi mesto Sihonovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 28, 'Zakaj ogenj je prišel iz Hesbona, plamen iz mesta Sihonovega, požrl je Ar Moabcev, gospodo Arnonskih višin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 29, 'Gorje tebi, Moab! Izgubljeno si, o ljudstvo Kamosovo! Ta je storil, da so sinovi njegovi ubežniki, in hčere svoje je peljal v ujetništvo k Sihonu, kralju Amorejcev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 30, 'Streljali smo nanje: Hesbon je pokončan tja do Dibona; in pustošili smo prav do Nofoha - gorelo je do Medebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 31, 'Tako se je nastanil Izrael v deželi Amorejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 32, 'In Mojzes je poslal oglednike v Jazer, in zavzeli so njemu podložne vasi ter spodili Amorejce, ki so bili ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 33, 'Potem so se obrnili in šli v Basan. Og pa kralj basanski, jim pride nasproti z vsem ljudstvom svojim, da napravi bitko v Edreju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 34, 'A Gospod reče Mojzesu: Ne boj se ga, zakaj v roko tvojo sem dal njega, vse ljudstvo in deželo njegovo; stóri ž njim, kakor si storil s Sihonom, kraljem Amorejcev, ki je prebival v Hesbonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 21, 35, 'Porazili so ga torej in sinove njegove in vse ljudstvo njegovo, da nihče ni preostal, in posedli so deželo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 1, 'In sinovi Izraelovi odrinejo in se utabore na poljanah Moabskih, vzhodno od Jordana, Jerihu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 2, 'In Balak, sin Ziporjev, je videl vse, kar je storil Izrael Amorejcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 3, 'In zbali so se Moabci silno ljudstva izraelskega, ker ga je bilo veliko, in groza je zgrabila Moaba pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 4, 'In reče Moab starejšinam madianskim: Zdaj pa požre ta množica vse okrog nas, kakor pomuli vol vso travo na polju. Balak pa, sin Ziporjev, je bil kralj moabski v tem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 5, 'Ta pošlje poročnike k Balaamu, sinu Beorjevemu, v Petor, ki je pri veletoku, v deželo sinov ljudstva njegovega, da ga pokličejo, govoreč: Glej, iz Egipta je prišlo ljudstvo; glej, pokrilo je površje zemlje in ustanovilo se je tu meni nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 6, 'Pridi torej zdaj, prosim, in mi prekolni to ljudstvo, ker je močnejše od mene: morda se mi ga posreči poraziti ter izgnati iz dežele; zakaj vem, da je blagoslovljen, kogar ti blagosloviš, in preklet, kogar prekolneš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 7, 'Gredo torej starejšine Moabcev in Madiancev s plačilom za vedeževanje v rokah svojih; in ko pridejo k Balaamu, mu sporoče besede Balakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 8, 'In jim reče: Prenočite nocoj tu, in odgovorim vam, kakor mi bo govoril Gospod. In ostanejo knezi moabski pri Balaamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 9, 'Pride pa Bog k Balaamu in reče: Kdo so tisti možje pri tebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 10, 'In Balaam reče Bogu: Balak, sin Ziporjev, kralj Moabov, je poslal k meni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 11, 'Glej, ljudstvo, ki je prišlo iz Egipta, je pokrilo površje zemlje! Pridi torej in mi ga prekolni; morda se mi posreči, da jih premorem v boju ter izženem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 12, 'Bog pa veli Balaamu: Ne hodi ž njimi; ne kolni ljudstva, zakaj blagoslovljeno je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 13, 'In vstane Balaam zjutraj in reče knezom Balakovim: Pojdite v deželo svojo; zakaj Gospod mi noče dopustiti, da bi šel z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 14, 'Nato vstanejo knezi moabski in gredo k Balaku in sporoče: Balaam se je branil iti z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 15, 'Tedaj pošlje Balak še enkrat kneze, pa več in imenitnejših nego prej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 16, 'Ti pridejo k Balaamu in mu reko: Tako pravi Balak, sin Ziporjev: Ne daj si, prosim, z ničemer zabraniti, da ne bi prišel k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 17, 'Zakaj z mnogimi častmi te hočem obsipati, in karkoli mi porečeš, rad storim; pridi torej, prosim, prekolni mi to ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 18, 'Balaam pa odvrne in reče služabnikom Balakovim: Če mi da Balak polno hišo svojo srebra in zlata, vendar ne bom mogel prestopiti povelja Gospoda, Boga svojega, da bi storil kaj manj ali več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 19, 'Pa ostanite tudi vi, prosim, nocoj tu, da zvem, kaj mi bo dalje govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 20, 'In pride Bog po noči k Balaamu in reče: Ako so te prišli ti možje klicat, vstani in pojdi ž njimi; ali stóri samo to, kar ti bom govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 21, 'Nato vstane Balaam zjutraj, osedla oslico svojo ter odide s knezovi moabskimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 22, 'A vname se srd Božji, da je šel. In angel Gospodov mu stopi na pot kot nasprotnik. On pa je jezdil na oslici svoji in dva hlapca njegova sta bila pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 23, 'In oslica ugleda angela Gospodovega na poti stoječega, s potegnjenim mečem v roki; in ugane se oslica s pota ter gre po polju, Balaam po jo bije, da bi šla po poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 24, 'In postavi se angel Gospodov na ulico med vinogradi, kjer je bil zid na tej in zid na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 25, 'Ko ugleda oslica angela Gospodovega, se primakne k zidu in pritisne Balaamu nogo k zidu, in ta jo zopet tepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 26, 'In angel Gospodov gre dalje in se postavi v tesnino, kjer se ni bilo kam izogniti, ne na desno, ne na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 27, 'Oslica pa, videč angela Gospodovega, pade pod Balaamom, in Balaam se razvname od jeze in jo tepe s palico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 28, 'Tedaj odpre Gospod usta oslici, da izpregovori Balaamu: Kaj sem ti storila, da me že v tretjič tepeš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 29, 'Nato reče Balaam oslici: Ker se norčuješ z menoj! O da bi imel meč v roki, kar ubil bi te!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 30, 'In oslica reče Balaamu: Nisem li tvoja oslica, na kateri si od nekdaj jezdil do tega dne? ali sem ti kdaj storila tako? On reče: nikoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 31, 'Tedaj odpre Gospod Balaamu oči, da vidi angela Gospodovega na poti stoječega, s potegnjenim mečem v roki, in povesi teme ter pade na obraz svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 32, 'In angel Gospodov mu veli: Zakaj si tepel oslico svojo zdaj že trikrat? Glej, izšel sem, da ti bodem nasprotnik, ker tvoja pot drži v pogubo pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 33, 'In oslica me je videla in se mi že trikrat izognila; sicer bi te bil, ko bi se mi ne bila umeknila, takoj umoril, njo pa ohranil živo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 34, 'In Balaam reče angelu Gospodovemu: Grešil sem, zakaj nisem vedel, da ti stojiš na poti proti meni; in sedaj, če si ti vidi hudobno, se vrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 35, 'Angel Gospodov pa mu veli: Pojdi s temi možmi, ali govóri samo tisto besedo, ki ti jo naročim. Šel je torej Balaam z Balakovimi knezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 36, 'In ko zasliši Balak, da prihaja Balaam, mu pride naproti v mesto moabsko, ki je na meji Arnona, prav na skrajni meji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 37, 'In reče Balak Balaamu: Nisem li nujno poslal k tebi, da te pokličem? Zakaj nisi prišel k meni? ker bi te menda ne mogel dosti počastiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 38, 'Balaam pa odgovori Balaku: Glej, zdaj pa sem prišel k tebi; toda morem li sploh govoriti kaj? Besedo, katero Bog dene v usta moja, to moram govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 39, 'In gre Balaam z Balakom in prideta v Kirjat-huzot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 40, 'Balak pa zakolje v daritve govedi in drobnice ter pošlje od tega Balaamu in knezom, ki so bili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 22, 41, 'In zjutraj vzame Balak Balaama ter ga pelje na višave Baalove, in odondod je videl zadnji del ljudstva izraelskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 1, 'Balaam pa reče Balaku: Zgradi mi tu sedem oltarjev in pripravi sem sedem juncev in sedem ovnov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 2, 'In Balak stori, kakor mu je rekel Balaam. In darovala sta Balak in Balaam junca in ovna na vsakem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 3, 'Balaam pa veli Balaku: Postoj pri žgalni daritvi svoji, jaz pa pojdem: morda mi pride Gospod naproti, in karkoli mi pokaže, ti naznanim. In odide na gol hrib.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 4, 'Tedaj sreča Bog Balaama, in ta mu reče: Sedem oltarjev sem postavil in daroval sem junca in ovna na vsakem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 5, 'Gospod pa dene Balamu besedo v usta in reče: Vrni se k Balaku in tako govóri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 6, 'In vrne se k njemu, in glej, on stoji pri žgalni daritvi svoji z vsemi knezi Moabcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 7, 'Tedaj začne svoj govor in reče: Iz Arama, s planin jutrovih, me je poklical Balak, kralj moabski: Pridi, prekolni mi Jakoba, pridi, jezo skliči nad Izraela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 8, 'Kako naj kolnem, kogar Bog mogočni ne preklinja? in kako naj jezo skličem, na kogar se Gospod ne jezi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 9, 'Zakaj z vrhov skal ga vidim in s hribov ga gledam: glej, ljudstvo je, ki prebiva posebe in se med narode poganske ne šteje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 10, 'Kdo prešteje prah Jakobov in število četrtine Izraela? O, da bi umrl s smrtjo pravičnih in da bi bil konec moj podoben koncu teh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 11, 'Tedaj reče Balak Balaamu: Kaj si mi to naredil? Da prekolneš sovražnike moje, sem te poklical, in glej, ti si samo blagoslovil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 12, 'On odgovori, rekoč: Ni li mi treba paziti, da govorim to, kar mi Gospod dene v usta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 13, 'Pa mu reče Balak: Pojdi z menoj, prosim, na drug kraj, od koder jih boš videl; samo njih zadnji del boš videl, vseh pa nikar; in prekolni mi jih od ondod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 14, 'In pelje ga na Polje ogledovalcev, na vrh Pizge, in zgradi sedem oltarjev ter daruje junca in ovna na vsakem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 15, 'In on reče Balaku: Postoj tu pri žgalni daritvi svoji, jaz pa pojdem tja čakat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 16, 'In Gospod sreča Balaama ter mu dene besedo v usta in veli: Vrni se k Balaku in tako mu govóri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 17, 'In pride k njemu, in glej, stoji pri žgalni daritvi svoji in knezi moabski ž njim. In Balak ga nagovori: Kaj je govoril Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 18, 'tedaj začne svoj govor in reče: Vstani, Balak, in čuj, poslušaj me, sin Ziporjev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 19, 'Bog mogočni ni človek, da bi lagal, tudi sin človečji ni, da bi se kesal: rekel li je kaj, a tega ne bo storil, govoril je, pa ne bo izpolnil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 20, 'Glej, prejel sem, da blagoslavljam; on je blagoslovil, in jaz ne morem prevreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 21, 'Ne gleda krivičnosti v Jakobu in ne vidi nepravice v Izraelu. Gospod, Bog njegov, je ž njim, in kraljeve trobente glas v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 22, 'Bog mogočni ga je peljal iz Egipta; moč njegova je enaka bivolovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 23, 'Kajti ni vraževanja zoper Jakoba, ne vedeževanja zoper Izraela. Ob svojem času se bo povedalo o Jakobu in Izraelu, kaj je storil Bog mogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 24, 'Glej, ljudstvo vstaja kakor levinja in kakor lev se vzdiguje; ne uleže se, dokler ne požre plena in se ne napije krvi umorjencev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 25, 'In veli Balak Balaamu: Pa ga ne preklinjaj in tudi ne blagoslavljaj več!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 26, 'Balaam odgovori in reče Balaku: Nisem li ti povedal tako: Vse, kar bo velel Gospod, to hočem storiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 27, 'In reče Balak Balaamu: Pojdi, prosim, peljal te bom na drug kraj. Morda se bo Bogu videlo prav, da mi jih prekolneš od ondod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 28, 'Pelje torej Balak Balaama na vrh Peorja, ki strmi nad puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 29, 'In Balaam reče Balaku: Zgradi mi tu sedem oltarjev in pripravi sem sedem juncev in sedem ovnov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 23, 30, 'In Balak stori, kakor je rekel Balaam, in daruje junca in ovna na vsakem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 1, 'Ker pa je Balaam videl, da je dobro v očeh Gospodovih, če blagoslavlja Izraela, ni šel več kakor prvič in drugič za vražami svojimi, temuč obrne obličje svoje proti puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 2, 'In povzdigne Balaam oči ter vidi Izraela ušatorjenega po rodovih svojih. In pride nadenj duh Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 3, 'in začne svoj govor in reče: Tako pravi Balaam, sin Beorjev, tako pravi mož odprtih oči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 4, 'tako pravi, ki sliši besede Boga silnega, ki vidi prikazen Vsemogočnega, ki pade, a oči so mu odprte:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 5, 'Kako so lepi šatori tvoji, o Jakob, prebivališča tvoja, o Izrael!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 6, 'Kakor doline se razprostirajo, kakor vrtovi poleg reke, kakor alojeva drevesa, ki jih je Gospod zasadil, kakor cedre pri vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 7, 'Voda poteče zvrhoma iz veder njegovih in seme njegovo bode v obilnih vodah; višji od Agaga bo njegov kralj in kraljestvo njegovo se poviša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 8, 'Bog mogočni ga je vodil iz Egipta; moč njegova je enaka bivolovi. Požre narode, ki ga stiskajo, in zdrobi jim kosti in s pšicami svojimi jih razkrši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 9, 'Legel je, da bi počival, kakor lev in kakor levinja; kdo ga zbudi? Kdorkoli te blagoslovi, bodi blagoslovljen, in kdor te preklinja, bodi preklet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 10, 'Tedaj se vname srd Balakov zoper Balaama, ploskne z rokama in reče Balaamu: Da prekolneš neprijatelje moje, sem te poklical, in glej, ti si jih le blagoslovil že tretjič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 11, 'Zdaj pa se hitro poberi v svoj kraj! Mislil sem te s častmi obsipati, a glej, Gospod ti ni privoščil časti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 12, 'Balaam pa reče Balaku: Nisem li tudi rekel slom tvojim, ki si jih poslal k meni, takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 13, 'Če mi da Balak zlata in srebra polno hišo svojo, ne morem prestopiti povelja Gospodovega, da bi storil ali dobro ali hudo po svojih mislih, ampak da bom govoril, kar mi ukaže Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 14, 'In sedaj, glej, grem k ljudstvu svojemu; pristópi, da ti oznanim, kaj stori to ljudstvo tvojemu ljudstvu v poznejših časih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 15, 'In začne svoj govor in reče: Tako pravi Balaam, sin Beorjev, tako pravi mož odprtih oči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 16, 'tako pravi, ki sliši besede Boga silnega, ki ima spoznanje Najvišjega, ki vidi prikazen Vsemogočnega, ki pade, a oči mu so odprte:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 17, 'Vidim jo, ali ne sedaj, gledam jo, a ne od blizu: zvezda vzhaja iz Jakoba in žezlo se vzdiguje iz Izraela, ki potare obedve strani Moabcem in razdere vse sinove hruma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 18, 'In Edom mu bo posestvo, tudi Seir mu bo posestvo, sovražnika njegova; Izrael pa bo vršil junaške čine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 19, 'In iz Jakoba bo eden vladal in pogubil preostale iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 20, 'In ko je pogledal Amalekovce, poprime govor svoj in reče: Prvec narodov je Amalek, a konec njegov bode poguba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 21, 'In pogleda Kenejce, poprime govor svoj in reče: Močno je prebivališče tvoje, in na skalo si postavil svoje gnezdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 22, 'A vendar bo Kenejec iztrebljen! Doklej še? Asur te popelje ujetega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 23, 'In poprime govor svoj in reče: Gorje, kdo bo živel, kadar Bog mogočni to stori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 24, 'In ladje pridejo od obrežja Kitima in ponižajo Asurja in ponižajo Heberja. Tudi on dospe v pogubo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 24, 25, 'In Balaam vstane ter odpotuje v svoj kraj; tudi Balak je šel svojim potem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 1, 'Izrael pa je ostal v Sitimu; in ljudstvo začne nečistovati s hčerami Moabcev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 2, 'ki so povabile ljudstvo k daritvam svojih bogov; in jedlo je ljudstvo in se priklanjalo njih bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 3, 'In Izrael se je oprijel Baal-peorja, in srd Gospodov se je vnel zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 4, 'In Gospod veli Mojzesu: Vzemi vse prvake ljudstva in jih Gospodu obesi proti solncu, da se obrne togota Gospodova od Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 5, 'Reče torej Mojzes sodnikom Izraelovim: Vsak umóri svoje ljudi, ki so se oprijeli Baal-peorja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 6, 'In glej, pride eden izmed sinov Izraelovih ter privede k bratom svojim Madianko vpričo Mojzesa in vpričo vse občine Izraelovih sinov, prav ko so jokali pri vhodu shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 7, 'Pinehas pa, sin Eleazarja, sinú Arona duhovnika, videč to, vstane urno izmed množice in vzame sulico v roko');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 8, 'ter gre za tistim izraelskim možem v kočo ter ju prebode, izraelskega moža in tisto ženo, skozi trebuh. In šiba med sinovi Izraelovimi je bila ustavljena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 9, 'Tistih pa, ki so umrli od te šibe, je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 10, 'Nato ogovori Gospod Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 11, 'Pinehas, sin Eleazarja, sinú Arona duhovnika, je odvrnil jezo mojo od sinov Izraelovih s tem, da je gorel z mojo gorečnostjo sredi njih, in nisem pokončal sinov Izraelovih v gorečnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 12, 'Zato reci: Glej, dajem mu zavezo svojo, zavezo mirú;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 13, 'in njemu in zarodu njegovemu po njem naj velja večnega duhovništva zaveza, zato ker je gorel za svojega Boga in storil poravnavo za sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 14, 'Ime pa izraelskemu možu, ki je bil ubit z madiansko ženo, je bilo Simri, sin Salujev, knez očetovine med Simeonskimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 15, 'In Madianka, ki je bila ubita, se je imenovala Kozbi, hči Zura, ki je bil rodovinski poglavar očetovine med Madiani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 16, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 17, 'Sovražno ravnajte z Madianci in jih ubijajte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 25, 18, 'zakaj oni so sovražno ravnali z vami v svoji zvijači, s katero so vas prekanili v zadevi Peorja in v zadevi Kozbe, hčere kneza madianskega, sestre svoje, ki je bila ubita v dan šibe zaradi Peorja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 1, 'In zgodi se po tej šibi, da ogovori Gospod Mojzesa in Eleazarja, sina Arona duhovnika, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 2, 'Poizvedita število vse občine sinov Izraelovih, od dvajsetletnih in više, po njih očetovskih hišah, vseh Izraelcev, ki so zmožni iti na vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 3, 'Govorita torej Mojzes in Eleazar duhovnik ž njimi na poljanah Moabskih, pri Jordanu nasproti Jerihu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 4, 'Seštejte jih od dvajsetletnih in više, kakor je zapovedal Gospod Mojzesu in sinovom Izraelovim, ki so bili šli iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 5, 'Ruben je bil prvenec Izraelov. Sinovi Rubenovi: od Hanoka rodovina Hanoških, od Paluta rodovina Palutovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 6, 'od Hezrona rodovina Hezronskih, od Karmija rodovina Karmijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 7, 'To so rodovine Rubenove, in seštetih izmed njih je bilo triinštirideset tisoč sedemsto in trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 8, 'Sinovi pa Palutovi: Eliab,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 9, 'in sinovi Eliabovi: Nemuel, Datan in Abiram. To sta tista Datan in Abiram, pooblaščenca občine, ki sta se uprla Mojzesu in Aronu v družbi Korahovi, ko so se vzpeli zoper Gospoda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 10, 'in zemlja je odprla žrelo svoje in ju požrla s Korahom vred, družba ta pa je poginila, ko je ogenj požrl tistih dvesto in petdeset mož, in postali so svarilno znamenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 11, 'Ali sinovi Korahovi niso umrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 12, 'Sinovi Simeonovi po svojih rodovinah: od Nemuela rodovina Nemuelskih, od Jamina rodovina Jaminskih, od Jakina rodovina Jakinskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 13, 'od Zeraha rodovina Zerahovih, od Savla rodovina Savelcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 14, 'To so rodovine Simeoncev, dvaindvajset tisoč in dvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 15, 'Sinovi Gadovi po svojih rodovinah: od Zefona rodovina Zefonskih, od Hagija rodovina Hagijevih, od Šunija rodovina Šunijevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 16, 'od Oznija rodovina Oznijevih, od Erija rodovina Erijevih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 17, 'od Aroda rodovina Arodovih, od Arelija rodovina Arelijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 18, 'To so rodovine sinov Gadovih po seštetih izmed njih: štirideset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 19, 'Sinova Judova: Ger in Onan; umrla sta pa Ger in Onan v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 20, 'Sinovi Judovi po njih rodovinah so bili: od Šela rodovina Šelovih, od Pereza rodovina Perezovih, od Zeraha rodovina Zerahovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 21, 'In sinovi Perezovi: od Hezrona rodovina Hezronskih, od Hamula rodovina Hamulskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 22, 'To so rodovine Judove po seštetih izmed njih: šestinsedemdeset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 23, 'Sinovi Isaharjevi po svojih rodovinah: od Tola rodovina Tolovih, od Puva rodovina Puvanskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 24, 'od Jasuba rodovina Jasubskih, od Simrona rodovina Simronskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 25, 'To so rodovine Isaharjeve po seštetih izmed njih: štiriinšestdeset tisoč in tristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 26, 'Sinovi Zebulonovi po svojih rodovinah: od Sereda rodovina Seredskih, od Elona rodovina Elonskih, od Jahleela rodovina Jahleelskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 27, 'To so rodovine Zebulonove po seštetih izmed njih: šestdeset tisoč in petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 28, 'Sinova Jožefova po svojih rodovinah: Manase in Efraim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 29, 'Sinovi Manasejevi: od Mahirja rodovina Mahirskih; Mahir pa je rodil Gileada, od Gileada pa je rodovina Gileadskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 30, 'To so sinovi Gileadovi: od Ijezerja rodovina Ijezerskih, od Heleka rodovina Helekovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 31, 'od Asriela rodovina Asrielskih, od Sihema rodovina Sihemskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 32, 'od Semida rodovina Semidovih, od Heferja rodovina Heferskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 33, 'Zelofad pa, sin Heferjev, ni imel sinov, ampak hčere in imena tem so bila: Mahla, Noa, Hogla, Milka in Tirza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 34, 'To so rodovine Manasejeve, in seštetih izmed njih je bilo dvainpetdeset tisoč in sedemsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 35, 'Sinovi Efraimovi po svojih rodovinah: od Sutelaha rodovina Sutalhejcev, od Bekerja rodovina Bekerjevih, od Tahana rodovina Tahanskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 36, 'Sinovi Sutelahovi so pa bili: od Erana rodovina Eranskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 37, 'To so rodovine sinov Efraimovih po seštetih izmed njih: dvaintrideset tisoč in petsto. To so sinovi Jožefovi po svojih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 38, 'Sinovi Benjaminovi po svojih rodovinah: od Bela rodovina Belovih, od Ažbela rodovina Ažbelskih, od Ahirama rodovina Ahiramskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 39, 'od Sufama rodovina Sufamskih, od Hufama rodovina Hufamskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 40, 'Sinova Belova pa sta bila: Ard in Naaman; od Arda rodovina Ardovih, od Naamana rodovina Naamskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 41, 'To so rodovine Benjaminove po svojih rodovinah, in seštetih izmed njih: petinštirideset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 42, 'To so sinovi Danovi po svojih rodovinah: od Suhama rodovina Suhamskih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 43, 'to so rodovine Danove po svojih rodovinah. Vseh rodovin Suhamskih po njih seštetih: štiriinšestdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 44, 'Sinovi Aserjevi po svojih rodovinah: od Jimna rodovina Jimnovih, od Jišvija rodovina Jišvijskih, od Berija rodovina Berijskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 45, 'Od sinov Berijevih: od Heberja rodovina Heberskih, od Malkiela rodovina Malkielskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 46, 'Hči Aserjeva pa se je imenovala Seraha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 47, 'To so rodovine sinov Aserjevih po seštetih izmed njih: triinpetdeset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 48, 'Sinovi Neftalijevi po svojih rodovinah: od Jahzeela rodovina Jahzeelskih, od Gunija rodovina Gunijskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 49, 'od Jezerja rodovina Jezerskih, od Šilema rodovina Šilemskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 50, 'To so rodovine Neftalijeve po svojih rodovinah, in seštetih izmed njih: petinštirideset tisoč in štiristo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 51, 'To je število seštetih sinov Izraelovih: šesto in eden tisoč sedemsto in trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 52, 'In Gospod je govoril Mojzesu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 53, 'Temle naj se razdeli dežela v dediščino po številu imen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 54, 'Katerih je več, tem naj se da več, katerih pa manj, tem naj se da manj dediščine; vsakemu naj se da dediščina primerna njegovemu številu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 55, 'Toda z žrebanjem naj se razdeli zemlja; po imenih rodov svojih očetov naj jo podedujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 56, 'Po žrebanju naj se razdeli dediščina med tiste, katerih je več, in med tiste, ki jih je manj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 57, 'Ti pa so sešteti izmed levitov po svojih rodovinah: od Gersona rodovina Gersonovih, od Kahata rodovina Kahatovcev, od Merarija rodovina Merarskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 58, 'To so rodovine Levijeve: rodovina Libnijevih, rodovina Hebronovih, rodovina Mahlijevih, rodovina Musijevih, rodovina Korahovih. Kahat pa je rodil Amrama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 59, 'In ime Amramovi ženi je bilo Jokebeda, hči Levijeva, ki se je narodila Leviju v Egiptu; in ona je rodila Amramu Arona in Mojzesa in njiju sestro Mirjamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 60, 'Aronu pa se rodili Nadab in Abihu, Eleazar in Itamar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 61, 'A Nadab in Abihu sta umrla, ko sta darovala tuj ogenj pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 62, 'In tistih, ki so bili seštetih izmed njih, je bilo triindvajset tisoč, vsi moški, mesec dni stari in več; niso namreč bili šteti s sinovi Izraelovimi vred, ker jim ni bila dana dediščina med Izraelovimi otroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 63, 'To so ti, ki sta jih preštela Mojzes in Eleazar duhovnik, ko sta štela sinove Izraelove na poljanah Moabskih pri Jordanu nasproti Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 64, 'Med temile pa ni bilo onih, ki sta jih preštela Mojzes in Aron duhovnik, ko sta štela sinove Izraelove v puščavi Sinajski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 26, 65, 'Zakaj Gospod je rekel o onih: Gotovo umrjo v puščavi. Ni ostalo torej nobenega izmed njih razen Kaleba, sinu Jefunovega, in Jozueta, sinu Nunovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 1, 'Tedaj pristopijo hčere Zelofada, sinu Heferja, sinu Gileada, sinu Mahirja, sinu Manasejevega, izmed rodovin Manaseja, sinu Jožefovega; in ta so imena hčera njegovih: Mahla, Noa, Hogla, Milka in Tirza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 2, 'Te torej se postavijo pred Mojzesa in Eleazarja duhovnika in pred kneze in vso občino ob vratih shodnega šatora ter reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 3, 'Naš oče je umrl v puščavi, pa ni bil v družbi tistih, ki so se zbrali zoper Gospoda, v družbi Korahovi, ampak umrl je vsled svojega greha; sinov pa ni imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 4, 'Zakaj naj bi izginilo ime očeta našega med rodovino njegovo, ker ni imel sina? Dajte nam posestvo med brati očeta našega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 5, 'Tedaj prinese Mojzes njih pravdo pred Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 6, 'In Gospod mu odgovori, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 7, 'Prav so govorile hčere Zelofadove: moraš jim dati dedno posest med brati njih očeta; naredi torej, da preide dediščina njih očeta nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 8, 'Sinovom Izraelovim pa govóri, rekoč: Če kdo umrje brez sina, prenesite njegovo dediščino na hčer njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 9, 'ako pa nima hčere, dajte dediščino njegovo bratom njegovim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 10, 'ako pa nima bratov, dajte njegovo dediščino bratom očeta njegovega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 11, 'ako pa ni bratov očeta njegovega, dajte dediščino njegovo najbližjemu sorodniku iz rodovine njegove, da mu bodi v last. In to bodi sinovom Izraelovim sodna postava, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 12, 'In Gospod veli Mojzesu: Pojdi na to goro Abarim, in oglej ž nje deželo, ki sem jo dal sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 13, 'In ko si jo ogledaš, boš zbran tudi ti k ljudstvu svojemu, kakor je bil zbran Aron, brat tvoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 14, 'ker sta se upirala povelju mojemu v puščavi Zinski ob prepiru občine, ko bi me bila morala svetega izkazati pri vodah vpričo njih. (To je tista Voda prepira v Kadesu v Zinski puščavi.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 15, 'Mojzes pa ogovori Gospoda takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 16, 'Postavi naj Gospod, Bog duhov vsega mesa, nad občino moža,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 17, 'ki naj bi hodil pred njimi ven in noter ter jih vodil ven in noter, da ne bo Gospodova občina kakor ovce brez pastirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 18, 'Nato reče Gospod Mojzesu: Vzemi si Jozueta, sina Nunovega, moža, v katerem je Duh, in položi roko nanj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 19, 'ter ga postavi pred Eleazarja duhovnika in pred vso občino in mu zapovej vpričo njih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 20, 'in deni nanj časti svoje, da bi mu bila poslušna vsa občina Izraelovih otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 21, 'In naj stopi pred Eleazarja duhovnika, in ta naj vpraša zanj po sodbi Urima pred Gospodom: na njegovo povelje pridejo ven in na njegovo povelje pojdejo noter, on in vsi Izraelovi sinovi ž njim, vsa občina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 22, 'Tedaj je storil Mojzes, kakor mu je bil zapovedal Gospod; in vzame Jozueta ter ga postavi pred Eleazarja duhovnika in pred vso občino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 27, 23, 'in položi nanj roke in mu da zapoved, kakor je bil govoril Gospod po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 2, 'Zapovej Izraelovim sinovom in jim reci: Na daritve moje, kruh moj k ognjenim žrtvam mojim, ki so mi v prijeten duh, pazite, da mi jih darujete v času določenem zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 3, 'In véli jim: To je ognjena daritev, ki jo darujte Gospodu: dve enoletni jagnjeti brez hibe, dan na dan, v neprestano žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 4, 'Eno jagnje daruj zjutraj, drugo pa proti večeru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 5, 'in s tem desetinko efe bele moke v jedilno daritev, omešene s četrtino hina iztolčenega olja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 6, 'To je neprestana žgalna daritev, ki je bila ustanovljena na gori Sinajski v prijeten duh, ognjena daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 7, 'Pitna daritev pa, ki pristoji, bodi četrt hina za eno jagnje; v svetišču izlij pitno darilo močnega vina Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 8, 'Drugo jagnje pa daruj proti večeru; kakor jutranjo jedilno in ž njo pitno daritev, tako napravi zvečer ognjeno daritev v prijeten duh Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 9, 'V sobotni dan pa daruj dve enoletni jagnjeti brez hibe in dve desetinki bele moke v jedilno daritev, z oljem omešene, in pitno daritev, ki pristoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 10, 'To je žgalna daritev vsake sobote, razen neprestane žgalščine in pitne daritve, ki pristoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 11, 'A v začetku svojih mesecev darujte Gospodu žgalno daritev: dva mlada voliča, enega ovna, enoletnih, brezhibnih jagnjet sedmero,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 12, 'in po tri desetinke bele moke v jedilno daritev, z oljem omešene, k vsakemu voliču; in dve desetinki bele moke v jedilno daritev, z oljem omešene, k enemu ovnu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 13, 'in po eno desetinko bele moke v jedilno daritev, z oljem omešene, k vsakemu jagnjetu: to je žgalna daritev v prijeten duh, ognjena daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 14, 'In pitna daritev k temu bodi polovica hina vina k voliču, tretjina hina k ovnu in četrtina hina k jagnjetu. To je žgalna daritev o mlaju, v vsakem mesecu v letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 15, 'In kozel v daritev za greh Gospodu naj se daruje razen neprestane žgalščine in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 16, 'In v prvem mesecu, štirinajsti dan meseca, je pasha Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 17, 'petnajsti dan tega meseca pa je praznik; sedem dni naj se uživa nekvašen kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 18, 'Prvi dan bodi sveto zborovanje; nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 19, 'In darujte kot ognjeno daritev žgalščino Gospodu: dva mlada voliča, enega ovna, sedem enoletnih jagnjet, brez hibe naj vam bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 20, 'S tem pa v jedilno daritev: tri desetinke bele moke, z oljem omešene, darujte k voliču in dve desetinki k ovnu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 21, 'in po eno desetinko k vsakemu izmed teh sedmerih jagnjet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 22, 'Tudi enega kozla v daritev za greh, da se stori poravnava za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 23, 'Te darujte razen žgalščine za jutra, ki je v neprestano žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 24, 'Na ta način darujte dan na dan, sedem dni, kruh ognjene daritve v prijeten duh Gospodu; razen neprestane žgalne daritve in njene pitne daritve naj se to daruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 25, 'Sedmi dan pa imejte sveto zborovanje; nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 26, 'Tudi v dan prvin, ko prinesete Gospodu novo jedilno daritev, ob svojem prazniku tednov imejte sveto zborovanje in nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 27, 'In darujte žgalščino v prijeten duh Gospodu: dva mlada voliča, enega ovna, sedem enoletnih jagnjet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 28, 'in jedilno daritev k temu: belo moko, omešeno z oljem, tri desetinke k vsakemu voliču in dve desetinki k enemu ovnu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 29, 'po eno desetinko pa k vsakemu izmed sedmerih jagnjet');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 30, 'in enega kozla, da se stori poravnava za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 28, 31, 'Razen neprestane žgalščine in njene jedilne daritve jih darujte (naj vam pa bodo brez hibe!) in njih pitne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 1, 'V sedmem mesecu pa, prvi dan meseca, imejte sveto zborovanje; nobenega službenega dela ne opravljajte: dan je trobentnega glasu za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 2, 'In darujte kot žgalščino v prijeten duh Gospodu: mladega voliča, ovna, sedem enoletnih jagnjet brez hibe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 3, 'in k temu kot jedilno daritev: belo moko, omešeno z oljem, tri desetinke k voliču, dve desetinki k ovnu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 4, 'in desetinko k vsakemu izmed sedmerih jagnjet;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 5, 'in kozla v daritev za greh, da se stori poravnava za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 6, 'To darujte razen žgalščine o mlaju in njene jedilne daritve in razen neprestane žgalščine in jedilne daritve njene in razen pitnih daritev, ki pristoje po določilu, v prijeten duh; ognjena žrtev bodi to Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 7, 'In deseti dan istega sedmega meseca imejte sveto zborovanje; pokoríte duše svoje in ne opravljajte nikakršnega dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 8, 'Darujte pa kot žgalno daritev Gospodu v prijeten duh: mladega voliča, ovna, sedem enoletnih jagnjet; bodo naj vam brez hibe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 9, 'in jedilno daritev k njim: belo moko, omešeno z oljem, tri desetinke k voliču, dve desetinki k ovnu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 10, 'po eno desetinko k vsakemu izmed sedmerih jagnjet;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 11, 'in enega kozla v daritev za greh. To darujte razen daritve za greh v spravo in razen neprestane žgalščine in njene jedilne daritve in njenih pitnih daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 12, 'In petnajsti dan sedmega meseca imejte sveto zborovanje; nobenega službenega dela ne opravljajte; sedem dni posvečujte praznik Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 13, 'In darujte kot žgalščino ognjeno daritev v prijeten duh Gospodu: trinajst mladih voličev, dva ovna, štirinajst enoletnih jagnjet, brez hibe naj bodo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 14, 'In njih jedilno daritev: tri desetinke bele moke, z oljem omešene, k vsakemu izmed trinajsterih voličev, dve desetinki k vsakemu onih dveh ovnov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 15, 'in po desetinko k vsakemu izmed štirinajsterih jagnjet;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 16, 'in v daritev za greh enega kozla, razen neprestane žgalščine in jedilne in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 17, 'Drugi dan pa darujte: dvanajst mladih voličev, dva ovna, štirinajst enoletnih jagnjet brez hibe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 18, 'in njih jedilno daritev in njih pitne daritve k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 19, 'in v daritev za greh enega kozla, razen neprestane žgalščine ter jedilne in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 20, 'Tretji dan pa: enajst voličev, dva ovna, štirinajst enoletnih jagnjet brez graje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 21, 'in njih jedilno daritev in njih pitne daritev k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 22, 'in v daritev za greh enega kozla, razen neprestane žgalščine ter jedilne in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 23, 'Četrti dan pa: deset voličev, dva ovna, štirinajst enoletnih jagnjet brez hibe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 24, 'in njih jedilna daritev in njih pitne daritve k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 25, 'in za greh enega kozla, razen neprestane žgalščine in jedilne in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 26, 'Peti dan pa: devet voličev, dva ovna, štirinajst enoletnih jagnjet brez madeža');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 27, 'ž njih jedilno daritvijo in pitnimi daritvami k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 28, 'in v daritev za greh enega kozla razen neprestane žgalščine in jedilne in pitne daritve, ki pristoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 29, 'Šesti dan pa: osem voličev, dva ovna, štirinajst enoletnih jagnjet brez hibe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 30, 'ž njih jedilno daritvijo in pitnimi daritvami k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 31, 'in za greh enega kozla, razen neprestane žgalščine ter jedilne in pitnih daritev, ki pristoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 32, 'Sedmi dan pa: sedem voličev, dva ovna, štirinajst enoletnih jagnjet brez hibe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 33, 'ž njih jedilno daritvijo in pitnimi daritvami k voličem, ovnoma in jagnjetom po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 34, 'in v daritev za greh enega kozla, razen neprestane žgalščine ter jedilne in pitne daritve, ki pristoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 35, 'A osmi dan imejte sveto zborovanje; nobenega službenega dela ne opravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 36, 'Kot žgalščino pa darujte ognjeno daritev v prijeten duh Gospodu: enega voliča, enega ovna, sedem enoletnih jagnjet brez hibe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 37, 'ž njih jedilno daritvijo in pitnimi daritvami k voličem, k ovnoma in k jagnjetom, po njih številu, kakor je določeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 38, 'in v daritev za greh enega kozla, razen neprestane žgalščine ter jedilne in pitne daritve k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 39, 'Toliko boste darovali Gospodu ob določenih svojih praznikih razen obljub in prostovoljnih daril svojih, ki jih poklonite ali v žgalne ali jedilne ali pitne ali mirovne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 29, 40, 'In Mojzes je sporočil sinovom Izraelovim vse, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 1, 'In Mojzes je govoril poglavarjem nad rodovi sinov Izraelovih takole: To je, kar je zapovedal Gospod:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 2, 'Ko stori kdo obljubo Gospodu ali priseže, da veže v dolžnost svojo dušo, naj ne pogazi besede svoje, temuč stori vse, kar je prišlo iz ust njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 3, 'Ko pa ženska stori obljubo Gospodu in se zaveže v dolžnost, ko biva še v hiši očeta svojega, v mladosti svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 4, 'in oče njen čuje njeno obljubo in zavezo, s katero je zavezala dušo svojo, pa molči proti njej: tedaj naj veljajo vse njene obljube in vse vezi, s katerimi je zavezala dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 5, 'Ako pa ji njen oče brani v dan, kadar to sliši, ne velja nobena njenih obljub in vezi, s katerimi je zavezala svojo dušo; Gospod pa ji oprosti, zato ker ji je branil njen oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 6, 'Ako se omoži, pa ima obljubo na sebi ali kako nepremišljeno besedo ustnic svojih, s čimer je zavezala svojo dušo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 7, 'in njen mož začuje to, pa ji nič ne reče v dan, kadar to sliši: tedaj naj veljajo obljube in vezi, s katerimi je obvezala dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 8, 'Ako pa ji njen mož brani v dan, kadar to sliši, razveljavi s tem obljubo, ki je na njej, in nepremišljeno besedo njenih ustnic, s katero je zavezala dušo svojo, in Gospod ji odpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 9, 'Pri obljubi vdove ali ločene od moža ostani zanjo v veljavi vse, s čimer je zavezala svojo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 10, 'In če katera v hiši svojega moža stori obljubo ali zaveže s prisego dušo svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 11, 'in njen mož to sliši, pa ji nič ne reče in ne brani, tedaj veljajo vse obljube njene in vse vezi, s katerimi je zavezala dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 12, 'Ako pa jih kakorkoli razveljavi njen mož v dan, kadar o njih zasliši, tedaj ne bo veljalo nič tega, kar je prišlo iz njenih usten gledé obljub ali vezi, s katerimi bi bila zavezala dušo svojo; njen mož jih je razveljavil, in Gospod ji odpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 13, 'Vsaktero obljubo in vsaktero vežočo prisego duši v pokoro sme njen mož potrditi ali razveljaviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 14, 'Če molči njen mož in ji nič ne reče od dne do dne, potrjuje s tem vse obljube njene ali vse vezi, ki so na njej; potrdil jih je, ker jih je slišal, pa molčal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 15, 'Ako pa jih ovrže pozneje, potem ko jih je slišal, bo nosil njeno krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 30, 16, 'To so postave, ki jih je Gospod zapovedal Mojzesu zastran moža in njegove žene, zastran očeta in njegove hčere v mladosti njeni, dokler biva v hiši očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 2, 'Maščuj sinove Izraelove nad Madianci; potem boš zbran k svojemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 3, 'Nato ogovori Mojzes ljudstvo in veli: Oborožite može izmed sebe na vojsko, da pojdejo na Madiance, izvrševat nad njimi maščevanje za Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 4, 'Po tisoč iz vsakega rodu, iz vseh svojih rodov pošljite na vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 5, 'In odbrali so iz tisočev Izraelovih po en tisoč iz vsakega rodu, dvanajst tisoč oboroženih na vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 6, 'In Mojzes jih pošlje, tisoč iz vsakega rodu, na vojsko s Pinehasom, sinom Eleazarja duhovnika, in posode iz svetišča in trobenti za pozivanje so bile pod njegovo roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 7, 'In vojska je šla na Madiance, kakor je bil Gospod zapovedal Mojzesu, in pobili so vse moške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 8, 'Pobili so tudi madianske kralje z drugimi pobitimi vred: Evija, Rekema, Zura, Hura in Reba, pet madianskih kraljev; Balaama tudi, sina Beorjevega, so umorili z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 9, 'In ujeli so sinovi Izraelovi žene Madiancev in njih otroke; in vso njih živino in vse njih črede in vse njih blago so uplenili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 10, 'a vsa njih mesta po krajih, koder so prebivali, in vsa njih šatorišča so sežgali z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 11, 'In vzeli so ves rop in plen, bodisi ljudi, bodisi živino;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 12, 'in so pripeljali k Mojzesu, Eleazarju duhovniku in k vsej občini sinov Izraelovih ujetnike, rop in plen, v tabor na poljanah Moabskih, ki so pri Jordanu, nasproti Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 13, 'Mojzes pa in Eleazar duhovnik in vsi knezi občine jim pridejo naproti ven za tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 14, 'A Mojzes se razsrdi nad vojvodami vojske, poveljniki čez tisoč in čez sto, ki so se vračali od vojne službe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 15, 'in jim reče: Ali ste ohranili vse žene žive?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 16, 'Glejte, one so napeljale sinove Izraelove po Balaamovem nasvetu, da so zakrivili iznevero zoper Gospoda pri Peorju, zaradi česar je šiba zadela občino Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 17, 'Zdaj torej pobijte vse moško med otroki, tudi umorite vsako ženo, ki je spoznala moža v telesnem združenju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 18, 'Vse deklice pa, ki še niso spoznale moža v združenju, ohranite žive zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 19, 'In ušatorite se zunaj za taborom sedem dni; vsi, ki ste koga ubili ali se ubitega doteknili, očistite se greha v tretji in sedmi dan, vi in vaše ujetnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 20, 'Očistite tudi vsako oblačilo in vse, kar je iz kože narejeno, in vsako pripravo iz kozje dlake in vse lesene posode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 21, 'Nato reče Eleazar duhovnik vojščakom, ki so bili šli v boj: To je naredba postave, ki jo je Gospod zapovedal Mojzesu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 22, 'Zlato in srebro in bron in železo in kositer in svinec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 23, 'sploh vse, kar strpi ogenj, pretopite v ognju, in čisto bode; vendar naj se greha očisti z vodo očiščevanja. Vse pa, kar ne strpi ognja, dajte, da preide skozi vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 24, 'In operite si oblačila dan sedmi, in bodete čisti, in potem pridite v tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 25, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 26, 'Poizvedite število plena, koliko so ujeli ljudi in živine, ti in duhovnik Eleazar in poglavarji očetovin občine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 27, 'In razdéli plen na dvoje: vojskovalcem, ki so šli v boj, in vsej občini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 28, 'In vzemi od vojščakov, ki so šli v boj, davek za Gospoda, po eno glavo od petsto, izmed ljudi, govedi, oslov in drobnice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 29, 'to vzemite od njih polovice ter daj to Eleazarju duhovniku kot dar povzdignjenja za Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 30, 'Od polovice pa, ki je Izraelovih sinov, vzemi po eno glavo od petdesetih ljudi, tudi od govedi, oslov in ovac in od vsake živine, in jih daj levitom, ki strežejo v straži pri Gospodovem prebivališču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 31, 'In storita Mojzes in Eleazar duhovnik, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 32, 'In bilo je plena, kolikor ga je preostajalo od tega, kar si je priborilo vojno moštvo: šeststo petinsedemdeset tisoč drobnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 33, 'dvainsedemdeset tisoč goved,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 34, 'edeninšestdeset tisoč oslov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 35, 'in dvaintrideset tisoč vseh žensk, ki niso spoznale moža v združenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 36, 'Polovica pa, delež tistih, ki so bili šli v boj, je bila po številu: tristo sedemintrideset tisoč in petsto drobnice');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 37, 'in davek za Gospoda od nje šeststo in petinsedemdeset glav;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 38, 'in govedi je bilo šestintrideset tisoč in od nje davek za Gospoda dvainsedemdeset glav;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 39, 'oslov pa trideset tisoč in petsto in od njih davek za Gospoda enoinšestdeset glav;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 40, 'in ljudi je bilo šestnajst tisoč, davek pa od njih za Gospoda dvaintrideset duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 41, 'Mojzes je torej dal davek kot dar povzdignjenja za Gospoda Eleazarju duhovniku, kakor mu je bil Gospod zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 42, 'Od polovice sinov Izraelovih, ki jo je Mojzes razštel od deleža vojščakov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 43, '(bil je pa polovični delež občine: tristo in sedemintrideset tisoč in petsto drobnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 44, 'šestintrideset tisoč goved,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 45, 'trideset tisoč in petsto oslov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 46, 'in šestnajst tisoč ljudi)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 47, 'vzame Mojzes od te polovice sinov Izraelovih, kar je bilo odbranega, po eno od petdesetih, izmed ljudi in živine, in jih da levitom, ki so stregli v straži pri prebivališču Gospodovem, kakor je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 48, 'Tedaj pristopijo k Mojzesu vojvode, ki so bili nad tisočmi vojske, poveljniki čez tisoč in čez sto,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 49, 'in reko Mojzesu: Služabniki tvoji so poizvedeli število vojščakov, ki smo jih imeli pod svojo roko, in ne manjka izmed nas ne enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 50, 'Zato nesemo Gospodu darila, vsakdo od tega, kar je dobil, zlatih dragotin, obročkov, zapestnic, prstanov, uhanov in ovratnih verižic, da se izvrši poravnava za nas pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 51, 'In prejmeta od njih Mojzes in Eleazar duhovnik tisto zlato, vsakršne umetne dragotine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 52, 'In bilo je vsega zlata, kar so ga poveljniki čez tisoč in čez sto poklonili Gospodu kot dar povzdinjenja: šestnajst tisoč sedemsto in petdeset seklov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 53, '(Vojščaki so uplenili vsak nekaj sam zase.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 31, 54, 'In Mojzes in Eleazar duhovnik vzameta to zlato od poveljnikov čez tisoč in čez sto ter ga neseta v shodni šator, da bodi v spomin Izraelovim sinovom pred obličjem Gospodovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 1, 'Sinovi Rubenovi pa in sinovi Gadovi so imeli veliko množino čred, in videli so pokrajino Jazersko in Gileadsko, in glej, ta kraj je bil pripraven za živinorejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 2, 'Pridejo torej sinovi Rubenovi in sinovi Gadovi in ogovore Mojzesa, Eleazarja duhovnika in kneze občine, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 3, 'Atarot, Dibon, Jazer, Nimra, Hesbon, Eleale, Sebam, Nebo in Beon');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 4, 'v deželi, ki jo je Gospod udaril pred Izraelovo občino, je dežela za živino, in mi, hlapci tvoji, imamo dosti živine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 5, 'Reko torej: Ako smo našli milost v tvojih očeh, daj to deželo v posest nam hlapcem svojim; ne vodi nas onkraj Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 6, 'A Mojzes reče sinovom Gadovim in sinovom Rubenovim: Bratje vaši naj gredo v boj, vi pa hočete tu sedeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 7, 'In zakaj odvračate srce Izraelovih sinov, da ne bi šli tja v deželo, ki jim jo je dal Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 8, 'Tako so storili očetje vaši, ko sem jih poslal iz Kades-barnee ogledat deželo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 9, 'ko so prišli gori do doline Eškolske in si ogledali deželo, so odvrnili srce sinov Izraelovih, da ne bi šli v deželo, ki jim jo je dal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 10, 'In srd Gospodov se je razvnel tisti dan, in prisegel je, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 11, 'Nihče izmed mož, ki so šli sem iz Egipta, od dvajsetletnih in više, ne bo videl dežele, ki sem jo s prisego obljubil Abrahamu, Izaku in Jakobu, zato ker niso hodili zvesto za mano,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 12, 'razen Kaleba, sina Jefunovega, Kenizejca, in Jozueta, sina Nunovega, kajti ona sta zvesto hodila za Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 13, 'In razvnel se je srd Gospodov zoper Izraela, in naredil je, da so se morali klatiti po puščavi štirideset let, dokler ni pomrl ves rod, ki je hudo ravnal pred očmi Gospodovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 14, 'In glejte, vi ste stopili na mesto očetov svojih, izrastki grešnih ljudi, da še bolj pomnožite togoto srda Gospodovega zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 15, 'Zakaj če se odvrnete in ne boste hodili za njim, on ga pusti še dalje v puščavi, in tako pogubite vse to ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 16, 'In stopijo k njemu bliže in reko: Samo ograje hočemo tu postaviti za živino svojo in mesta za otročiče svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 17, 'sami pa pojdemo oboroženi pred Izraelovimi sinovi, da jih spremimo na njih kraj. Otroci naši naj ostanejo v ograjenih mestih zaradi prebivalcev te dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 18, 'Ne vrnemo se v hiše svoje, dokler ne posede sleherni sinov Izraelovih svoje dediščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 19, 'Zakaj ž njimi nočemo ničesar podedovati onkraj Jordana in tam dalje, ako nam pripade dediščina naša na tej strani Jordana, proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 20, 'Nato jim veli Mojzes: Ako izpolnite to besedo, ako se oborožite in pojdete v boj pred Gospodom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 21, 'in pride vsak oboroženec izmed vas čez Jordan pred Gospodom, dokler ne prežene sovražnikov svojih izpred sebe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 22, 'in bo zemlja podvržena pred Gospodom, in ako se šele potem vrnete, nedolžni bodete pred Gospodom in pred Izraelom, in ta dežela vam bodi v posest pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 23, 'Ako pa ne storite tako, glejte, grešili ste zoper Gospoda, in vedite, da vas greh vaš doleti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 24, 'Postavite si mesta za otročiče svoje in ograje za živino svojo in storite, kakor so govorila usta vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 25, 'In sinovi Gadovi in sinovi Rubenovi reko Mojzesu takole: Hlapci tvoji bodo storili, kakor je ukazal naš gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 26, 'Otroci naši, žene naše, črede naše in vsa naša živina ostanejo tu v gileadskih mestih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 27, 'mi pa, tvoji hlapci, pojdemo, vsi oboroženi za vojsko, pred Gospodom v boj, kakor je govoril naš gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 28, 'Tedaj zapove Mojzes glede njih Eleazarju duhovniku in Jozuetu, sinu Nunovemu, in poglavarjem očetovin iz rodov Izraelovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 29, 'In Mojzes jim reče: Ako pojdejo sinovi Gadovi in sinovi Rubenovi, vsi oboroženi, z vami čez Jordan v boj pred Gospodom in dežela vam bo podvržena, dajte jim pokrajino Gileadsko v posest;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 30, 'ako pa ne pojdejo oboroženi z vami na ono stran, naj imajo posestva med vami v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 31, 'Nato odgovore sinovi Gadovi in sinovi Rubenovi, rekoč: Kakor je govoril Gospod hlapcem tvojim, tako storimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 32, 'Pojdemo oboroženi pred Gospodom v deželo Kanaansko, a dedna posest nam ostani tostran Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 33, 'In dal je Mojzes sinovom Rubenovim in sinovom Gadovim in polovici rodu Manaseja, Jožefovega sinú, kraljestvo Sihona, kralja Amorejcev, in kraljestvo Oga, kralja basanskega, deželo in njena mesta ž njih okraji, mesta po deželi naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 34, 'In sinovi Gadovi so sezidali Dibon, Atarot, Aroer,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 35, 'Atrot-šofan, Jazer, Jogbeho,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 36, 'Bet-nimro in Bet-haran: utrjena mesta in ograje za ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 37, 'Sinovi Rubenovi so pa sezidali Hesbon, Eleale, Kirjataim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 38, 'Nebo, Baal-meon (katerim so premenili imena) in Sibmo, in dali so druga imena mestom, ki so jih zgradili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 39, 'A sinovi Mahirja, Manasejevega sinú, so šli v Gilead in zasedli ta kraj ter pregnali Amorejce, ki so bili v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 40, 'In dal je Mojzes Gilead Mahirju, Manasejevemu sinu, in prebival je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 41, 'Jair pa, sin Manasejev, je šel in zasedel njegove vasi in jih imenoval Jairove trge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 32, 42, 'Tudi Nobah je šel ter zasedel Kenat in podložne mu vasi in jih imenoval po svojem imenu Nobah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 1, 'To so postaje sinov Izraelovih, ko so šli iz Egiptovske dežele po svojih trumah pod vodstvom Mojzesa in Arona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 2, 'In Mojzes je opisal, kako so potovali in kod so postajali po ukazu Gospodovem, in to so njih postaje po njih potovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 3, 'Iz Ramesesa so odrinili petnajsti dan prvega meseca; zjutraj po pashi so odšli Izraelovi sinovi po visoki roki pred očmi vseh Egipčanov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 4, 'medtem ko so Egipčani pokopavali vse prvence svoje, ki jih je Gospod udaril med njimi; tudi nad vsemi njih bogovi je sodbo izvršil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 5, 'In ko so bili odrinili iz Ramesesa, so se utaborili sinovi Izraelovi v Sukotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 6, 'In odpotujejo iz Sukota in se utabore v Etamu, ki je kraj puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 7, 'In odpravijo se iz Etama in krenejo proti Pihahirotu, ki je nasproti Baalzefonu, in se ušatore pred Migdolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 8, 'In odrinejo izpred Hahirota in preidejo čez morje v puščavo, in potujejo tri dni hoda po Etamski puščavi, in razpno šatore v Mari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 9, 'In odpotujejo iz Mare in pridejo v Elim, in v Elimu je bilo dvanajst studencev in sedemdeset palmovih dreves, in tu se raztaboré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 10, 'Iz Elima se odpravijo in se ušatore ob Rdečem morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 11, 'In se odpravijo od Rdečega morja in se utabore v Sinski puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 12, 'Iz Sinske puščave pa odidejo in se ustavijo v Dofki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 13, 'In gredo iz Dofke in obstanejo v Alusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 14, 'In odrinejo iz Alusa in se utabore v Rafidimu, kjer ni bilo vode, da bi ljudstvo pilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 15, 'In odpravijo se iz Rafidima ter razpno šatore v Sinajski puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 16, 'Iz Sinajske puščave odidejo in se ušatoré ob Grobovih poželjivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 17, 'Od Grobov poželjivosti odrinejo in se ušatore v Hazerotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 18, 'Iz Hazerota odidejo in se utabore v Ritmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 19, 'Iz Ritme pa odpotujejo in se utabore v Rimon-perezu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 20, 'In iz Rimon-pereza odrinejo in se ušatore v Libni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 21, 'Iz Libne odpotujejo in se utabore v Risi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 22, 'Iz Rise odidejo in se ušatore v Kehelati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 23, 'Iz Kehelate odrinejo in se utabore na gori Seferi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 24, 'Z gore Sefere pa se odpravijo in se utabore v Haradi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 25, 'In iz Harade odidejo in se ušatore v Makhelotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 26, 'Iz Makhelota odrinejo in se utabore v Tahatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 27, 'Iz Tahata odidejo in se utabore v Tarahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 28, 'Iz Taraha odpotujejo in se ušatore v Mitki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 29, 'In gredo iz Mitke in se utabore v Hasmoni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 30, 'Iz Hasmone odrinejo in se utabore v Moserotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 31, 'Iz Moserota odidejo in se ustavijo v Bene-jaakanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 32, 'Iz Bene-jaakana se vzdignejo in se ušatore v Hor-gidgadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 33, 'Iz Hor-gidgada odidejo in se utabore v Jotbati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 34, 'In iz Jotbate odrinejo in se utabore v Abroni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 35, 'Iz Abrone se premaknejo in se ušatore v Ezion-geberju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 36, 'Iz Ezion-geberja se odpravijo in razpno šatore v puščavi Zinski, to je Kades.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 37, 'Iz Kadesa pa se vzdignejo in se ušatore na gori Horu ob meji dežele Edomske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 38, 'In Aron duhovnik je šel na goro Hor na ukaz Gospodov, in tam je umrl v štiridesetem letu po odhodu Izraelovih sinov iz Egipta, prvi dan petega meseca;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 39, 'in imel je Aron sto in triindvajset let, ko je umrl na gori Horu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 40, 'Kanaanski kralj v Aradu pa, ki je prebival proti jugu v deželi Kanaanski, je slišal, da prihajajo Izraelovi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 41, 'In z gore Hora odpotujejo in se utabore v Zalmoni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 42, 'Iz Zalmone pa odidejo in se ušatore v Punonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 43, 'Iz Punona odrinejo in se utabore v Obotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 44, 'In iz Obota odpotujejo in se ušatore v Ije-abarimu, na meji moabski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 45, 'In odpotujejo iz Ijima in se utabore v Dibon-gadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 46, 'Iz Dibon-gada se odpravijo in se ušatore v Almon-diblataimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 47, 'Iz Almon-diblataima pa se vzdignejo in se utabore na Abarimskih gorah, pred Nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 48, 'Z Abarimskih gor pa odrinejo in razpno šatore na poljanah Moabskih pri Jordanu, nasproti Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 49, 'In taborili so pri Jordanu od Bet-jesimota do Abel-sitima na Moabskih poljanah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 50, 'In Gospod je govoril Mojzesu na poljanah Moabskih pri Jordanu, nasproti Jerihu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 51, 'Govori sinovom Izraelovim in jim reci: Ko pridete čez Jordan v Kanaansko deželo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 52, 'preženite vse prebivalce v deželi izpred sebe in razbijte vse njih poslikane kamene in razdrobite vse njih ulite podobe in zrušite vse njih višave;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 53, 'in prilastite si deželo ter prebivajte v njej, zakaj vam sem dal to deželo, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 54, 'In razdelite zemljo z žrebom med svoje rodovine: katerih je več, jim dajte večjo dediščino, katerih pa manj, jim dajte manjšo dediščino. Kamorkoli pade komu žreb, ondi bodi njegovo; po rodovih svojih očetov si razdelite dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 55, 'Ako pa ne preženete prebivalcev v deželi izpred sebe, vam bodo tisti, katere od njih boste strpeli pri sebi, kakor trnje v očeh in kakor ostni v bokih, in pritiskali vas bodo v deželi, ki boste prebivali v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 33, 56, 'In zgodi se, da storim vam tako, kakor sem mislil storiti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 1, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 2, 'Zapovej sinovom Izraelovim ter jim reci: Ko pridete v deželo Kanaansko, to bodi dežela, ki vam pripade v dediščino: Kanaanova dežela po svojih mejah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 3, 'Poldnevna stran vam bodi pri Zinski puščavi in poleg Edoma, in vaša južna meja bodi od kraja Slanega morja proti vzhodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 4, 'in ta meja se obrni proti jugu od vzviška Akrabima in naj gre v Zin in sega proti jugu čez Kades-barneo, potem naj gre k vasi Adarju in poleg Azmona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 5, 'in od Azmona naj se obrne k Egiptovskemu potoku in se konča pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 6, 'Meja proti večeru pa: Veliko morje vam bodi za mejo; to bode vaša zahodna meja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 7, 'In to bodi vaša meja proti polnoči: od Velikega morja si merite tja do gore Hora,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 8, 'od gore Hora pa merite do poti v Hamat, in meja naj sega do Zedada;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 9, 'potem naj gre meja dalje v Zifron in se konča pri vasi Enanu. To bodi severna vaša meja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 10, 'Za mejo proti jutru si merite od vasi Enana do Sefama,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 11, 'in naj gre meja doli od Sefama k Ribli ob vzhodni strani Ajina; potem naj gre meja doli in krene k strani Kineretskega morja ob vzhodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 12, 'in meja naj gre doli po Jordanu in se konča pri Slanem morju. To bodi vaša dežela po njenih mejah naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 13, 'Mojzes torej zapove sinovom Izraelovim, rekoč: To je dežela, ki si jo v dedino razdelite po žrebu in ki je o njej zapovedal Gospod, da bodi dana deveterim rodovom in polovici rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 14, 'Zakaj rod Rubenovih sinov po svojih očetovinah in rod Gadovih sinov po svojih očetovinah in polovica Manasejevega rodu so prejeli svojo dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 15, 'Ta dva rodova in pol so prejeli svojo dediščino tostran Jordana, od Jeriha proti solnčnemu vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 16, 'Nato ogovori Gospod Mojzesa, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 17, 'Ta so imena mož, ki naj vam deželo razdele v dedino: Eleazar duhovnik in Jozue, sin Nunov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 18, 'In vzemite po enega kneza iz vsakega rodu, da razdele deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 19, 'In ta so imena tistih mož: za Judov rod Kaleb, sin Jefunov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 20, 'za rod Simeonovih sinov Samuel, sin Amihudov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 21, 'za Benjaminov rod Elidad, sin Kislonov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 22, 'za rod Danovih sinov knez Buki, sin Joglijev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 23, 'za Jožefova sinova: za rod Manasejevih sinov knez Haniel, sin Efodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 24, 'in za rod Efraimovih sinov knez Kemuel, sin Siftanov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 25, 'za rod Zebulonovih sinov knez Elizafan, sin Parnakov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 26, 'za rod Isaharjevih sinov knez Paltiel, sin Azanov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 27, 'za rod Aserjevih sinov knez Ahihud, sin Selomijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 28, 'za rod Neftalijevih sinov knez Pedahel, sin Amihudov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 34, 29, 'To so tisti, katerim je Gospod zapovedal prideliti Izraelovim sinovom dedino v deželi Kanaanski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 1, 'In Gospod je govoril Mojzesu na poljanah Moabskih pri Jordanu, nasproti Jerihu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 2, 'Zapovej Izraelovim sinovom, naj dado levitom od dednih posestev svojih mesta za prebivanje; in pašnike okoli teh mest dajte levitom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 3, 'In mesta naj imajo za prebivanje, njih pašnike pa za svojo živino in za imetje in za vse živali svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 4, 'Pašniki ob mestih pa, ki jih daste levitom, naj se zunaj raztezajo od mestnega zidovja do tisoč komolcev naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 5, 'Merite torej zunaj mesta na vzhodni strani dva tisoč komolcev, na južni strani dva tisoč komolcev, na zahodni strani dva tisoč komolcev in na severni strani dva tisoč komolcev, tako da bode mesto v sredi. To naj jim služi v pašnike pri njih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 6, 'Med mesti pa, ki jih daste levitom, bodi šest zavetnih mest, v katera dovolite ubijalcu pribežati, in razen teh dajte dvainštirideset mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 7, 'Vseh mest, ki jih daste levitom, bodi oseminštirideset mest in njih pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 8, 'Za mesta pa, ki jih daste levitom od posesti Izraelovih sinov, veljaj: od tistih, ki imajo več, vzemite več, in od tistih, ki imajo manj, vzemite manj; vsakteri rod naj da od svojih mest levitom primerno dediščini, ki jo dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 9, 'In Gospod je govoril Mojzesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 10, 'Govori sinovom Izraelovim in jim reci: Ko pridete čez Jordan v deželo Kanaansko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 11, 'si določite mesta, ki naj vam bodo zavetna mesta: tja naj pribeži ubijalec, ki ubije človeka neradovoljno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 12, 'In ta mesta naj vam bodo v zavetišča pred krvnim maščevalcem, da ne umrje ubijalec, dokler se ne postavi pred občino zaradi sodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 13, 'Takih mest, ki jih boste dali in ki vam bodo v zavetišča, bodi šest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 14, 'Tri mesta določite tostran Jordana in tri mesta v Kanaanski deželi; zavetna mesta naj bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 15, 'Za sinove Izraelove in za tujca in priseljenca med njimi naj bode teh šest mest v zavetišče, da zbeži vanje, kdorkoli neradovoljno ubije človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 16, 'Ako pa kdo koga udari z železnim orodjem, da umre, morilec je; umreti mora tak morilec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 17, 'In če ga udari s kamenom v roki, s kakršnim je lahko usmrtiti, tako da umre, morilec je; umreti mora tak morilec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 18, 'Ali če ga udari z lesenim orodjem, s kakršnim je lahko usmrtiti, tako da umre, morilec je; umreti mora tak morilec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 19, 'Maščevalec krvi naj usmrti morilca; kadar nanj naleti, naj ga usmrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 20, 'Ako pa pahne koga iz sovraštva ali zažene vanj kaj, zalezovaje ga, da umre;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 21, 'ali ga udari v neprijateljstvu z roko, tako da umre: kdor ga je udaril, mora umreti; morilec je, maščevalec krvi naj ga usmrti, kadar ga zaloti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 22, 'Ako ga pa pahne nenadoma, ne v neprijateljstvu, ali vrže nanj kako stvar, ne da bi ga zalezoval, da umre,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 23, 'ali, ne ga videč, zažene vanj kamen, kakršen lahko usmrti, tako da umre, pa mu ni bil sovražnik in ni iskal njegove nesreče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 24, 'tedaj naj občina razsodi med ubijalcem in maščevalcem krvi po teh pravicah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 25, 'in občina naj reši ubijalca iz roke krvnega maščevalca in ga da peljati nazaj v zavetno mesto, kamor je bil zbežal; ondi naj ostane dotlej, da umrje veliki duhovnik, ki je bil maziljen s svetim oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 26, 'Toda če ubijalec kdaj prekorači mejo zavetnega mesta, kamor je bil zbežal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 27, 'in krvni maščevalec ga zasači zunaj meje njegovega zavetišča in ga umori, ne bodi kriv krvi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 28, 'zakaj on bi bil moral ostati v zavetnem mestu svojem do smrti velikega duhovnika; ali po smrti velikega duhovnika se sme vrniti v pokrajino svojega posestva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 29, 'In to vam bodi sodna postava za vse prihodnje vaše rodove po vseh vaših stanovališčih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 30, 'Kdorkoli umori človeka, bodi umorjen po izpovedbi prič; samo ena priča naj ne govori zoper koga za smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 31, 'Nikar ne sprejmite odkupnine za življenje morilca, ki je kriv smrti; on mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 32, 'Tudi ne sprejmite odkupnine od njega, ki je zbežal v zavetno svoje mesto, da bi se smel vrniti in prebivati v deželi, preden umrje veliki duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 33, 'Ne ognušajte dežele, v kateri ste, zakaj kri ognuša deželo, in za kri, ki se je v deželi prelila, ni mogoča poravnava, razen po krvi tistega, ki jo je prelil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 35, 34, 'Ne onečiščajte dežele svojega domovanja, sredi katere jaz prebivam; zakaj jaz, Gospod, prebivam sredi Izraelovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 1, 'In poglavarji očetovinam iz rodovine sinov Gileada, sinu Mahirja, sinu Manasejevega, od rodovin Jožefovih sinov, pristopijo ter govore pred Mojzesom in pred knezi, poglavarji očetovinam Izraelovih sinov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 2, 'in reko: Gospod je ukazal tebi, gospodu mojemu, da naj se dežela da po žrebu sinovom Izraelovim v dediščino; tudi je gospodu mojemu ukazal Gospod, naj se dediščina našega brata Zelofada dodeli njegovim hčeram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 3, 'Toda če se omože s katerimi sinovi iz drugih rodov Izraelovih otrok, se vzame njih dedni delež od dediščine naših očetov in se prideli dediščini tistega rodu, kateremu bodo pripadale; tako pa se odtrga od deleža naše dediščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 4, 'In ko pride milostno leto Izraelovih sinov, tedaj se njih dediščina pridruži dediščini rodú, ki bodo v njem živele one hčere; od dediščine rodú naših očetov pa se odtrga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 5, 'Tedaj zapove Mojzes sinovom Izraelovim po ukazu Gospodovem, veleč: Prav je govoril rod Jožefovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 6, 'To je stvar, ki jo je Gospod zapovedal glede Zelofadovih hčera, rekoč: Omože naj se, s komer jim je všeč, toda le v rodovini očeta svojega rodu naj se omože:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 7, 'da se ne prenese nič dediščine Izraelovih sinov od roda na drug rod; zakaj sleherni sinov Izraelovih se mora držati dediščine, lastne rodu njegovih očetov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 8, 'Vsaka hči, ki ima dediščino v katerem rodu sinov Izraelovih, naj se omoži le z nekom iz rodovine očeta svojega rodu, da sleherni sinov Izraelovih obdrži dediščino svojih očetov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 9, 'in da se ne prenaša dediščina od roda na drug rod, temuč se vsakdo med rodovi Izraelovih sinov drži svoje dediščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 10, 'Kakor je Gospod zapovedal Mojzesu, prav tako so storile Zelofadove hčere:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 11, 'kajti Mahla, Tirza, Hogla, Milka in Noa, Zelofadove hčere, so se omožile s sinovi stricev svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 12, 'Prišle so za žene v rodovine sinov Manaseja, sinu Jožefovega, in njih dediščina je ostala pri rodu, pri rodovini njih očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (4, 36, 13, 'To so zapovedi in sodbe, ki jih je ukazal Gospod po Mojzesu sinovom Izraelovim na poljanah Moabskih pri Jordanu, nasproti Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 1, 'To so besede, ki jih je Mojzes govoril vsemu Izraelu vzhodno od Jordana v puščavi, v nižini nasproti Sufu, med Paranom in Tofelom in Labanom in Hazerotom in Dizahabom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 2, 'Enajst dni hoda je to od Horeba, na poti na Seirsko goro, do Kades-barnee.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 3, 'V štiridesetem letu, prvi dan enajstega meseca, je govoril Mojzes Izraelovim sinovom vse, kar mu je bil Gospod zapovedal zanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 4, 'potem ko je bil porazil Sihona, kralja Amorejcev, ki je prebival v Hesbonu, in Oga, kralja basanskega, ki je prebival v Astarotu in v Edreju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 5, 'Onostran Jordana, v deželi Moabovi, je začel Mojzes razlagati ta zakon, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 6, 'Gospod, Bog naš, nam je govoril na Horebu takole: Dosti dolgo ste prebivali na tej gori;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 7, 'obrnite se in odpotujte ter pojdite h gorovju Amorejcev in k vsem njih sosedom v nižini na gorovju in v nižavi, proti Jugu in proti morskemu obrežju, v deželo Kanaanca in k Libanonu, tja do reke, do velereke Evfrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 8, 'Poglejte, izročam vam to deželo; pojdite vanjo in posedite deželo, za katero je Gospod prisegel vašim očetom, Abrahamu, Izaku in Jakobu, da jo hoče dati njim in njih semenu za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 9, 'A jaz sem vam rekel v tistem času: Ne morem vas nositi sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 10, 'Gospod, vaš Bog, vas je razmnožil, da vas je danes, glejte, mnogo kakor zvezd na nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 11, 'Gospod, očetov vaših Bog, razmnóži vas še tisočkrat in blagoslovi vas, kakor vam je obljubil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 12, 'Kako pa naj sam prenašam vaše težave, vaše breme in vaše prepire?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 13, 'Oskrbite si modre može, razumne in poznane po vaših rodovih, da vam jih postavim za poglavarje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 14, 'In odgovorili ste mi, rekoč: Reč, o kateri praviš, je dobra, da jo storimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 15, 'Vzel sem torej načelnike vaših rodov, modre može in poznane, in postavil sem vam jih za poglavarje, za vojvode čez tisoč, vojvode čez sto, vojvode čez petdeset in vojvode čez deset, in za oblastnike po vaših rodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 16, 'In naročil sem takrat sodnikom vašim, rekoč: Zaslišujte pravde svojih bratov in pravično sodite vsakega in njegovega brata in tujca, ki biva ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 17, 'Ne ozirajte se na osebe v sodbi, temuč poslušajte malega kakor velikega; nikogar se ne bojte, zakaj Božja je sodba. Zadeva pa, ki bi vam bila pretežka, dejte, da pride predme, da jo slišim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 18, 'In zapovedal sem vam takrat vse, kar naj delate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 19, 'Tedaj smo odrinili s Horeba in šli skozi vso to puščavo, ki je velika in grozovita, kakor ste videli, po poti v gorovje Amorejcev, kakor nam je bil zapovedal Gospod, Bog naš; in prišli smo v Kades-barneo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 20, 'Tu sem vam rekel: Prišli ste h gorovju Amorejcev, katero nam daje Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 21, 'Poglej, izročil ti je deželo Gospod, Bog tvoj: pojdi gori, posedi jo, kakor ti je obljubil Gospod, očetov tvojih Bog. Ne boj se in ne plaši se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 22, 'Nato ste vsi pristopili k meni in dejali: Naj pošljemo može pred seboj, da nam razgledajo to deželo ter nam povedo, po kateri poti naj gremo vanjo in v katera mesta pridemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 23, 'To se mi je dobro videlo; vzel sem torej izmed vas dvanajst mož, iz vsakega rodu enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 24, 'Ti so krenili na pot in so šli v gore in prišli do potoka Eškola in si jo ogledali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 25, 'in so vzeli s sabo od tiste dežele sadu in prinesli sem k nam, in so nam sporočili, govoreč: Dobra je dežela, ki nam jo hoče dati Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 26, 'Ali niste hoteli iti gori; upirali ste se povelju Gospoda, Boga svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 27, 'in mrmrali ste po šatorih in govorili: Gospod nam je sovražen, zato nas je odpeljal iz Egiptovske dežele, da nas da Amorejcem v pest, da nas pokončajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 28, 'Kam hočemo iti? Naši bratje so nam v obup zapeljali srce, govoreč: To ljudstvo je večje in višje postave od nas, mesta so velika in do neba obzidana, vrhutega smo tam videli sinove Enakimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 29, 'Pa sem vam rekel: Ne strašite se in ne boj te se jih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 30, 'Gospod, Bog vaš, ki gre pred vami, se bo bojeval za vas, prav kakor vam je storil v Egiptu pred vašimi očmi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 31, 'in v puščavi, kjer si videl, da te je nosil Gospod, Bog tvoj, liki mož, ki nosi svojega sinčka, po vsej poti, po kateri ste šli, dokler niste dospeli do tega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 32, 'A navzlic temu niste verovali v Gospoda, Boga svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 33, 'ki je hodil po poti pred vami, da vam poišče mesta, kjer naj bi si razpeli šatore, po noči v ognju, da vidite pot, po kateri vam je iti, a po dne v oblaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 34, 'Ko pa je Gospod slišal glas vaših besed, se je razsrdil in prisegel, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 35, 'Nobeden teh mož, nihče iz tega hudega rodu ne bo videl tiste dobre dežele, za katero sem prisegel njih očetom, da jim jo dam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 36, 'razen Kaleba, sinu Jefunovega, on jo bo videl: njemu in njegovim otrokom hočem dati deželo, po kateri je stopal, zato ker je zvesto hodil za Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 37, 'Tudi nad menoj se je srdil Gospod zaradi vas in rekel: Tudi ti ne prideš vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 38, 'Jozue, sin Nunov, ki ti služi, pride vanjo: njega ohrabri! zakaj on razdeli Izraelu dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 39, 'Otročiči vaši pa, o katerih ste dejali, da pridejo v plen, in sinovi vaši, ki še ne poznajo ne dobrega, ne hudega, ti pridejo vanjo, njim jo dam in oni jo posedejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 40, 'Vi pa se obrnite in popotujte v puščavo po poti k Rdečemu morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 41, 'Tedaj ste odgovorili in mi rekli: Grešili smo zoper Gospoda; hočemo pa iti gori in se bojevati, prav kakor nam je zapovedal Gospod, Bog naš. In pripasali ste si vsak svoj meč, in lahkomiselno ste ubrali pot v gorovje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 42, 'Gospod pa mi je rekel: Véli jim, ne hodite gori in ne bojujte se, zakaj jaz nisem med vami, da ne boste poraženi pred sovražniki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 43, 'To sem vam povedal, toda vi niste poslušali, temuč uprli ste se povelju Gospodovemu in v prevzetnosti svoji šli na gorovje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 44, 'Tedaj pridejo vam nasproti Amorejci, ki so bivali na tistem gorovju, in so vas gonili, kakor delajo čebele, in so vas pobijali v Seiru prav do Horme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 45, 'In ko ste se vrnili, ste jokali pred Gospodom, a Gospod ni hotel vašega glasu poslušati ter ni nagnil k vam ušesa svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 1, 46, 'Zato ste ostali mnogo dni v Kadesu, kolikor dni ste morali ondi bivati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 1, 'Potem smo se obrnili in šli v puščavo po poti proti Rdečemu morju, kakor mi je bil velel Gospod, in smo dolgo časa hodili ob Seirskem gorovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 2, 'Tedaj me ogovori Gospod, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 3, 'Dosti ste že hodili ob tem gorovju, krenite proti severu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 4, 'Ljudstvu pa zapovej takole: Potovali boste skozi pokrajine svojih bratov, sinov Ezavovih, ki prebivajo v Seiru, in se vas bodo bali. Ali skrbno se varujte,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 5, 'da ne začnete boja ž njimi; zakaj njih dežele vam ne dam še za stopinjo noge ne, ker Ezavu sem dal Seirsko gorovje v lastnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 6, 'Živeža si od njih kupite za denar, da boste jedli, tudi vode kupite od njih za denar, da boste pili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 7, 'Zakaj Gospod, Bog tvoj, te je blagoslovil pri vsem delu tvojih rok; vedel je za potovanje tvoje po tej veliki puščavi, teh štirideset let je bil Gospod, Bog tvoj, s teboj, ničesar ti ni zmanjkalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 8, 'Tako smo šli mimo svojih bratov, sinov Ezavovih, prebivajočih v Seiru, strani od poti po nižini, od Elata in Ezion-geberja. In obrnili smo se in šli po poti Moabske puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 9, 'In Gospod mi je rekel: Ne vedite se sovražno proti Moabcem in ne spustite se v vojno ž njimi; zakaj od njih dežele ti ne dam posesti, ker sem dal Ar sinom Lotovim v lastnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 10, '(Emimi so prebivali ondi v prejšnjih časih, ljudstvo veliko, mnogoštevilno in visoke postave kakor Enakimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 11, 'Tudi nje so šteli za velikane kakor Enakime, in Moabci so jih imenovali Emime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 12, 'Tudi v Seiru so v prejšnjih časih prebivali Horejci, a sinovi Ezavovi so jih pregnali in zatrli pred seboj, in prebivali so na njih mestu; prav kakor so storili Izraelci deželi posestva svojega, ki jim jo je dal Gospod.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 13, 'Zdaj se torej vzdignite in pojdite čez potok Zered! In šli smo čez potok Zered.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 14, 'Časa pa, v katerem smo šli od Kades-barnee, dokler nismo prestopili potoka Zereda, je bilo osemintrideset let; v tem času je izumrl ves rod vojščakov izmed tabora, kakor jim je bil prisegel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 15, 'Da, roka Gospodova je bila proti njim, da bi jih potrebil izmed tabora, dokler niso pomrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 16, 'In zgodi se, ko so bili vsi ti vojščaki iztrebljeni in so umrli izmed ljudstva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 17, 'da me ogovori Gospod, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 18, 'Ti greš danes skozi pokrajino Moabcev, mimo Ara,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 19, 'in se skoraj približaš kraju Amonovih sinov: ne vedi se sovražno proti njim ter se ne bojuj ž njimi, zakaj od dežele Amonovih sinov ti ne dam posesti, ker sem jo dal sinovom Lotovim v lastnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 20, '(Tudi ta se šteje za deželo velikanov; velikani so ondi prebivali v prejšnjih časih, in Amonci so jih imenovali Zamzumime;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 21, 'bilo je ljudstvo veliko in mnogoštevilno in visoke postave kakor Enakimi; a Gospod jih je pokončal pred njimi, tako da so jih pregnali in se naselili na njih mestu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 22, 'prav kakor je storil za sinove Ezavove, prebivajoče v Seiru, ko je zatrl Horejce pred njimi, in so jih ti pregnali in prebivali v njih kraju do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 23, 'In Avimci so prebivali v vaseh v smeri do Gaze, a Kaftorimci so prišli iz Kaftorja ter jih pokončali, in prebivali so na njih mestu.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 24, 'Vstanite, odpravite se in pojdite čez potok Arnon! Poglej, dal sem ti v roko Sihona Amorejca, kralja v Hesbonu, in njegovo deželo: začni jo posedati in spusti se v boj ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 25, 'Danes začnem pošiljati strah in grozo pred teboj nad ljudstva pod vsem nebom, da se bodo, ko začujejo glas o tebi, tresli in trepetali pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 26, 'Nato sem poslal poročnike iz Kedemotske puščave k Sihonu, kralju v Hesbonu, z mirovnimi besedami, da mu reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 27, 'Dovoli mi, da grem skozi tvojo deželo; naravnost po cesti hočem iti, ne ganem se ne na desno, ne na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 28, 'Živeža mi prodaš za denar, da jem, in vode mi daš za denar, da pijem, samo mi dovoli iti peš skozi deželo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 29, 'kakor so mi storili sinovi Ezavovi, ki prebivajo v Seiru, in Moabci, ki prebivajo v Aru; dokler ne pridem prek Jordana v deželo, ki nam jo daje Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 30, 'Ali Sihon, kralj v Hesbonu, nam ni hotel dovoliti, da gremo po njegovem tja, zakaj Gospod, Bog tvoj, je otrdil njegovega duha in zakrknil srce njegovo, da bi ti ga izročil v pest, kakor se danes vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 31, 'In Gospod mi reče: Poglej, začel sem ti izročati Sihona in deželo njegovo; začni jo posedati, da ti pride v last dežela njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 32, 'In pride nam nasproti Sihon z vsem ljudstvom svojim, da se z nami vojskuje v Jahazu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 33, 'A Gospod, Bog naš, nam ga je izročil, in porazili smo njega, sinove njegove in vse ljudstvo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 34, 'In tisti čas smo se polastili vseh njegovih mest in s prokletjem uničili vsako mesto, može, žene in otroke, nihče nam ni ubežal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 35, 'samo živino smo vzeli zase in plen iz mest, katerih smo se polastili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 36, 'Od Aroerja, ki je ob bregu potoka Arnona, in od mesta, ki je pri potoku, tja do Gileada ni bilo mesta, ki bi nam bilo nepremagljivo: vse nam je izročil Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 2, 37, 'Samo k deželi Amonovih sinov se nisi približal, tudi ne k vsej strani potoka Jaboka in k mestom na gorah in k vsemu, kar nam je prepovedal Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 1, 'Nato smo se obrnili in šli gori v Basan; Og pa, basanski kralj, nam pride nasproti z vsem ljudstvom svojim, da napravi bitko v Edreju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 2, 'Gospod pa mi reče: Ne boj se ga, zakaj izročil sem njega in vse ljudstvo in deželo njegovo v tvojo roko, in stóri mu, kakor si storil Sihonu, kralju Amorejcev, ki je prebival v Hesbonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 3, 'Dal nam je torej Gospod, Bog naš, v pest tudi Oga, kralja basanskega, in vse ljudstvo njegovo, in porazili smo ga, da mu nihče ni ostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 4, 'Takrat smo se polastili vseh njegovih mest; ni bilo mesta, ki jim ga nismo vzeli; šestdeset mest, vso pokrajino Argob, kraljestvo Oga v Basanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 5, 'Vsa ta mesta so bila utrjena z visokimi zidovi, z vrati in zapahi, razen mnogoštevilnih trgov brez obzidja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 6, 'In s prokletjem smo jih razdrli, kakor smo storili Sihonu, kralju v Hesbonu; uničili smo vsako mesto, može, žene in otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 7, 'Vso živino pa in plen iz mest smo vzeli zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 8, 'Tako smo vzeli tisti čas deželo iz rok dvema kraljema Amorejcev, ki sta bila na tej strani Jordana, od potoka Arnona do gore Hermona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 9, '(Hermon imenujejo Sidonjani Sirion, Amorejci pa Senir)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 10, 'vsa mesta na ravnini, ves Gilead in ves Basan do Salke in Edreja, mesta kraljestva Oga basanskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 11, '(Og namreč, kralj basanski, je edini ostal od ostanka velikanov: glej, železna njegova postelja ni li še v Rabi sinov Amonovih? devet komolcev je dolga in štiri komolce široka, po moškem komolcu.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 12, 'To deželo smo si tisti čas vzeli v posest. Od Aroerja, ki je pri potoku Arnonu, in polovico Gileadskih gor in njih mesta sem dal Rubenskim in Gadskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 13, 'Drugi del Gileada pa in ves Basan, Ogovo kraljestvo, sem dal polovici Manasejevega rodu, vso pokrajino Argob. (Ves tisti Basan se imenuje dežela velikanov.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 14, 'Jair, sin Manasejev, je zavzel vso pokrajino Argob tja do meje Gesurcev in Maakatovcev, in imenoval je Basan po svojem imenu Jairove trge do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 15, 'Mahirju pa sem dal Gilead.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 16, 'In Rubenskim in Gadskim sem dal del Gileada, do potoka Arnona, sredino potoka in obmejni kraj, prav do potoka Jaboka, ki je na meji sinov Amonovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 17, 'tudi nižino in Jordan, da bodi v mejo od Kinerota do Morja v nižini ali Slanega morja, pod strmino Pizge proti vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 18, 'In zapovedal sem vam takrat, rekoč: Gospod, Bog vaš, vam je dal to deželo, da jo posedete; vi pa pojdite oboroženi na ono stran pred svojimi brati, sinovi Izraelovimi, kolikor vas je hrabrih mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 19, 'Samo vaše žene, vaši otroci in živina vaša (vem, da imate mnogo živine) naj vam ostanejo v mestih, ki sem vam jih dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 20, 'In ko da Gospod počitek vašim bratom kakor vam, da tudi oni posedejo deželo, ki jim jo Gospod, Bog vaš, daje onkraj Jordana, potem se vrnite vsakteri k svojemu posestvu, ki sem vam ga dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 21, 'In Jozuetu sem tisti čas zapovedal, rekoč: Oči tvoje so videle vse, kar je storil Gospod, Bog vaš, tema dvema kraljema: prav tako stori Gospod vsem kraljestvom, v katera prideš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 22, 'Ne bojte se jih, zakaj Gospod, Bog vaš, se za vas bojuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 23, 'Jaz pa sem prosil Gospoda tisti čas takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 24, 'Gospod Jehova, ti si začel kazati svojemu hlapcu velikost svojo in mogočno roko svojo; kajti kje je Bog mogočni v nebesih ali na zemlji, ki bi delal tebi enaka dejanja in tebi enaka mogočna dela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 25, 'Daj, prosim, da grem čez Jordan in vidim to dobro deželo na oni strani, to lepo gorovje in Libanon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 26, 'Gospod pa se je srdil name zaradi vas in me ni uslišal; in mi je rekel Gospod: Dosti ti bodi; nikar mi več ne govori o tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 27, 'Stopi na vrh Pizge in povzdigni oči proti zahodu in severu, proti jugu in jutru in jo poglej s svojimi očmi; zakaj čez ta Jordan ne pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 28, 'Jozuetu pa zapovej in ga ohrabri in pokrepčaj, zakaj on bo vodil to ljudstvo in on jim razdeli deželo, ki jo boš videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 3, 29, 'Ostali smo torej v dolini, nasproti Bet-peorju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 1, 'Sedaj pa poslušaj, o Izrael, postave in sodbe, katere vas učim izpolnjevati, da živite in pridete v deželo ter jo posedete, ki vam jo daje Gospod, očetov vaših Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 2, 'Ne pristavite ničesar besedi, ki vam jo zapovedujem, tudi ne vzemite ničesar od nje, da ohranite Boga svojega zapovedi, ki vam jih zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 3, 'Oči vaše so videle, kar je storil Gospod zaradi Baal-peorja; kajti vse, ki so šli za Baal-peorjem, je potrebil Gospod, Bog tvoj, izmed tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 4, 'Vi pa, ki ste se držali Gospoda, Boga svojega, ste vsi živi današnji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 5, 'Glejte, učim vas postave in sodbe, kakor mi je zapovedal Gospod, Bog moj, da tako ravnate v deželi, ki greste vanjo, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 6, 'Hranite jih torej in izpolnjujte; kajti to bode vaša modrost in razumnost vpričo ljudstev, ki bodo slišala vse te postave, tako da poreko: Res, modro in razumno ljudstvo je ta veliki narod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 7, 'Zakaj kje je velik narod, ki bi mu bili bogovi tako blizu, kakor nam je Gospod, Bog naš, kadarkoli ga kličemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 8, 'In kje je velik narod, ki ima postave in sodbe tako pravične, kakor je ves ta zakon, ki vam ga danes stavim pred oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 9, 'Varuj se samo in pazi skrbno na dušo svojo, da ne zabiš reči, ki so jih videle tvoje oči, ter da ti ne izginejo iz srca, dokler koli živiš; ampak oznanjaj jih svojim otrokom in otrok svojih otrokom –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 10, 'da ne zabiš dneva, ko si stal pred Gospodom, Bogom svojim, na Horebu, ko mi je rekel Gospod: Zberi mi ljudstvo, da slišijo moje besede, da bi se učili bati se mene vse svoje žive dni na zemlji in to učili tudi otroke svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 11, 'Tedaj ste pristopili in stali pod goro; gora pa je gorela s plamenom do sredi neba, in bila je tema, oblak in mrakota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 12, 'In Gospod vam je govoril iz sredi ognja: glas besed ste slišali, a podobe niste videli nobene, čujoč samo glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 13, 'In oznanil vam je svojo zavezo, ki vam jo je ukazal izpolnjevati, tistih deset besed, in napisal jih je na dve kameneni plošči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 14, 'Meni pa je zapovedal Gospod tisti čas, da naj vas učim postave in sodbe, da bi jih izpolnjevali v deželi, ki greste vanjo, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 15, 'Varujte torej skrbno svoje duše; zakaj nikakršne podobe niste videli v dan, ko vam je Gospod govoril na Horebu iz sredi ognja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 16, 'da se ne skazite in si ne naredite rezane podobe, obraza kakršnekoli podobe, slike moškega ali ženskega bitja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 17, 'slike katerebodi živine na zemlji ali katerega okriljenca, ki leta pod nebom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 18, 'slike katerebodi laznine na zemlji ali katere ribe v vodah pod zemljo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 19, 'ter da ne povzdigneš oči proti nebu, in ko ogleduješ solnce, mesec in zvezde, vso vojsko nebeško, da se ne daš premotiti, da bi jih molil in jim služil, ki jih je Gospod, Bog tvoj, razdelil vsem na rodom pod vsem nebom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 20, 'Vas pa je Gospod vzel in peljal iz železne peči, iz Egipta, da bodite ljudstvo njegove dediščine, kakor se vidi danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 21, 'In Gospod se je razsrdil nad mano zaradi vas, tako da je prisegel, da ne smem iti čez Jordan ter priti v tisto dobro deželo, ki ti jo daje v dediščino Gospod, Bog tvoj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 22, 'ampak umreti moram v tej deželi, ne smem iti čez Jordan, vi pa pojdete čezenj in dobite v last ono dobro deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 23, 'Varujte se torej, da ne pozabite zaveze Gospoda, Boga svojega, ki jo je sklenil z vami, in si ne delate rezane podobe v kakršnikoli obliki, kar ti je prepovedal Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 24, 'Zakaj Gospod, Bog tvoj, je ogenj, ki uničuje, je Bog mogočni, goreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 25, 'Ko boš rodil otroke in otrok otroke in boste že dalje časa domovali v deželi, pa se izpridite in si naredite rezano podobo. ali kakršnokoli podobo in boste počenjali, kar je hudo v očeh Gospoda, vašega Boga, da ga dražite v jezo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 26, 'kličem danes nebo in zemljo za priči proti vam, da hitro in docela poginete s površja zemlje, v katero ste namenjeni iti čez Jordan, da jo posedete; ne ostanete dolgo v njej, temuč boste docela iztrebljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 27, 'In Gospod vas razkropi med ljudstva in malo vas ostane po številu med narodi, h katerim vas odpelje Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 28, 'In ondi boste služili bogovom, rok človeških tvorini, lesu in kamenu, ki ne vidijo in ne slišijo, ne jedo in ne duhajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 29, 'Ali odondod boste iskali Gospoda, Boga svojega, in ga našli, ko boste vpraševali po njem iz vsega srca in z vso dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 30, 'V stiski, kadar te zadenejo vse te bridkosti, se v poslednjih dneh izpreobrneš h Gospodu, Bogu svojemu, in poslušal boš njegov glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 31, 'Zakaj Gospod, Bog tvoj, je Bog mogočni, poln usmiljenja: ne odtegne se ti in te ne pokonča, tudi ne pozabi tvojih očetov zaveze, za katero jim je prisegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 32, 'Vprašaj vendar po starih časih, ki so bili pred teboj, od dne, ko je Bog ustvaril človeka na zemlji, in od enega konca neba do drugega, se li je kdaj zgodila taka velika reč ali se je slišalo kaj enakega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 33, 'Je li katero ljudstvo slišalo glas Boga, govorečega iz sredi ognja, kakor si ti slišal, in je ostalo živo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 34, 'Je li poskusil kateri bog priti, da si vzame narod izmed naroda z izkušnjami, z znamenji, s čudeži in z bojem, z mogočno roko in z iztegnjeno ramo ter z velikimi in groznimi deli, kakor je storil Gospod, Bog vaš, vse to za vas v Egiptu vam pred očmi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 35, 'Tebi je bilo to pokazano, da bi spoznal, da Gospod je Bog in da razen njega ni drugega nobenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 36, 'Iz nebes ti je dal slišati glas svoj, da te pouči, in na zemlji ti je dal videti veliki ogenj svoj, in slišal si njegove besede iz ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 37, 'In ker je ljubil tvoje očete in si je izvolil njih zarod za njimi, te je peljal s svojim obličjem, z veliko močjo svojo iz Egipta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 38, 'da prežene narode pred teboj, ki so večji in močnejši od tebe, da te privede v njih deželo in ti jo da v dediščino, kakor danes vidiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 39, 'Spoznaj torej danes in v srce si vtisni, da Gospod sam je Bog v nebesih zgoraj in na zemlji zdolaj, ni ga drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 40, 'In hrani njegove postave in zapovedi, ki ti jih danes zapovedujem, da se bo dobro godilo tebi in tvojim otrokom za teboj ter da se ti podaljšajo dnevi v deželi, ki ti jo za vse čase da Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 41, 'Tedaj je oddelil Mojzes tri mesta onostran Jordana, proti solnčnemu vzhodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 42, 'da bi zbežal vanje ubijalec, ki nehotoma ubije svojega bližnjega in ga ni v prejšnjem času sovražil; ta naj zbeži v eno teh mest in ostani živ:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 43, 'Bezer v puščavi, na ravnini, med Rubenskimi, Ramot v Gileadu med Gadskimi in Golan v Basanu med Manasejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 44, 'In ta je zakon, ki ga je Mojzes predložil Izraelovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 45, 'To so pričevanja, postave in sodbe, ki jih je Mojzes govoril sinom Izraelovim, ko so bili odšli iz Egipta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 46, 'za Jordanom, v dolini nasproti Bet-peorju, v deželi Sihona, kralja Amorejcev, ki je prebival v Hesbonu, ki so ga porazili Mojzes in Izraelovi sinovi, ko so bili odšli iz Egipta –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 47, 'in prilastili so si deželo njegovo in deželo Oga, kralja basanskega, obeh kraljev Amorejcev, ki sta bivala na oni strani Jordana, proti solnčnemu vzhodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 48, 'od Aroerja, ki je ob bregu potoka Arnona, do gore Siona (ki je Hermon),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 4, 49, 'in vso nižavo ob Jordanu, proti solnčnemu vzhodu, tja do Morja v nižini pod strmino gore Pizge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 1, 'In Mojzes skliče vse Izraelce in jim reče: Poslušaj, o Izrael, zapovedi in sodbe, ki jih vam danes govorim na ušesa, učite se jih in pazite nanje, da jih izpolnjujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 2, 'Gospod, Bog naš, je sklenil z nami zavezo na Horebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 3, 'Ne z očeti našimi je sklenil tole zavezo, ampak prav z nami, ki tu smo danes vsi in živimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 4, 'Od obličja do obličja je govoril Gospod z vami na gori iz sredi ognja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 5, '(jaz sem stal med Gospodom in vami, da bi vam znanil besedo Gospodovo, kajti bali ste se zaradi ognja in niste stopili na goro), veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 6, 'Jaz sem Gospod, Bog tvoj, ki sem te peljal iz dežele Egiptovske, iz hiše sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 7, 'Ne imej drugih bogov zraven mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 8, 'Ne delaj si rezanih podob, ne nikakršnih podob tega, kar je zgoraj na nebu, kar je spodaj na zemlji in kar je v vodah pod zemljo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 9, 'ne moli jih in ne časti jih, zakaj jaz sem Gospod, Bog tvoj, Bog mogočni, goreči, ki obiskujem krivico očetov na sinovih do tretjega in četrtega pokolenja tistih, ki me sovražijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 10, 'in izkazujem milost tisočim onih, ki me ljubijo in izpolnjujejo zapovedi moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 11, 'Ne imenuj po nemarnem imena Gospoda, svojega Boga, zakaj Gospod ne pusti brez kazni njega, ki imenuje njegovo ime po nemarnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 12, 'Spoštuj sobotni dan, da ga posvečuješ, kakor ti je zapovedal Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 13, 'Šest dni delaj in opravljaj vsa opravila svoja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 14, 'ali sedmi dan je čas počitka Gospodu, Bogu tvojemu: v njem ne opravljaj nobenega dela, ne ti, ne sin tvoj, ne hči tvoja, ne hlapec tvoj, ne dekla tvoja, ne vol, ne osel tvoj, ne nobeno živinče tvoje, niti tujec, ki je v vratih tvojih, da se odpočije hlapec tvoj in dekla tvoja kakor ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 15, 'In spominjaj se, da si bil suženj v Egiptovski deželi in da te je Gospod, Bog tvoj, izpeljal odondod z mogočno roko in z iztegnjeno ramo: zato ti je Gospod, Bog tvoj, zapovedal praznovati dan sobotni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 16, 'Spoštuj očeta svojega in mater svojo, kakor ti je zapovedal Gospod, Bog tvoj, da se podaljšajo tvoji dnevi ter da se ti bo dobro godilo na zemlji, ki ti jo daje Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 17, 'Ne ubijaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 18, 'Ne prešeštvuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 19, 'Ne kradi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 20, 'Ne govori krivega pričevanja zoper bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 21, 'Ne poželi žene bližnjega svojega, tudi ne hrepeni po svojega bližnjega hiši, ne po njegovi njivi, ne po hlapcu in dekli njegovi, ne po volu ali oslu njegovem, ne po ničemer, kar je bližnjega tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 22, 'Te besede je govoril Gospod vsemu zboru vašemu na gori iz sredi ognja in oblaka in teme z velikim glasom, in ni ničesar pridel; in napisal jih je na dve kameneni plošči in ju je izročil meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 23, 'Ali ko ste slišali glas iz sredi teme in je gora gorela z ognjem, ste pristopili k meni, vsi načelniki vaših rodov in vaši starejšine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 24, 'in ste dejali: Glej, Gospod, Bog naš, nam je pokazal svojo slavo in velikost svojo, in njegov glas smo slišali iz sredi ognja; danes smo videli, da Bog govori s človekom, in ta ostane živ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 25, 'Sedaj pa, zakaj naj bi umrli? kajti ta veliki ogenj nas požre; ako bomo še dalje poslušali glas Gospoda, našega Boga, umrjemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 26, 'Kajti kdo je izmed vsega mesa, ki bi bil slišal glas živega Boga, govorečega iz ognja, kakor smo ga mi, in bi ostal živ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 27, 'Pristopi ti tja in poslušaj vse, kar pravi Gospod, Bog naš, in povej nam vse, kar ti bo govoril Gospod, Bog naš; slišati hočemo in storiti to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 28, 'In Gospod je slišal glas vaših besed, ko ste govorili k meni, in Gospod mi reče: Slišal sem glas tega ljudstva besed, ki so jih govorili k tebi; dobro je vse, kar so govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 29, 'O da bi imeli tako srce, da bi se me bali in hranili vse moje zapovedi vse dni, da bi se dobro godilo njim in njih otrokom vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 30, 'Pojdi, veli jim: Vrnite se v svoje šatore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 31, 'Sam pa ostani tu pri meni, in ti povem vso zapoved in postave in sodbe, katere jih uči, da se ravnajo po njih v deželi, ki jim jo dajem, da jo obvladajo. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 32, 'Pazite torej, da ravnate, kakor vam je zapovedal Gospod, Bog vaš; ne odstopite ne na desno, ne na levo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 5, 33, 'temuč hodite po vsem potu, ki vam ga je zapovedal Gospod, Bog vaš, da bi živeli in bi vam dobro bilo in da bi podaljšali svoje dni v deželi, ki jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 1, 'To pa so zapovedi, postave in sodbe, ki jih je Gospod, Bog vaš, zapovedal učiti vas, da bi jih izpolnjevali v deželi, ki greste vanjo jo obvladat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 2, 'da bi se bali Gospoda, Boga svojega, izpolnjujoč vse postave in zapovedi njegove, ki ti jih zapovedujem, ti in otroci tvoji in otrok tvojih otroci, vse svoje žive dni, in da bi se podaljšali tvoji dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 3, 'Poslušaj torej, Izrael, in pazi, da izpolnjuješ, da bi se ti dobro godilo, da se silno pomnožite, kakor ti je obljubil Gospod, tvojih očetov Bog, v deželi, v kateri teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 4, 'Poslušaj, Izrael: Gospod, naš Bog, je edini Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 5, 'Zato ljubi Gospoda, svojega Boga, iz vsega srca svojega in iz vse duše svoje in iz vse moči svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 6, 'In te besede, ki ti jih danes zapovedujem, naj bodo v tvojem srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 7, 'In marljivo jih uči otroke svoje ter govori o njih, sedeč v svojem domu in hodeč po poti, ko ležeš in ko vstaneš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 8, 'In priveži si jih za znamenje na roko in naj ti bodo kakor čelno vezilo med očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 9, 'Zapiši jih na podboje hiše svoje in na vrata svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 10, 'Ko te torej Gospod, Bog tvoj, pripelje v deželo, ki je zanjo prisegel tvojim očetom, Abrahamu, Izaku in Jakobu, da ti jo da: velika in lepa mesta, ki jih nisi zidal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 11, 'in hiše, vsega dobrega polne, ki jih nisi napolnil, in izkopane vodnjake, ki jih nisi izkopal, vinograde in oljkova drevesa, ki jih nisi zasadil, in ko boš od tega jedel in se nasitil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 12, 'varuj se, da ne pozabiš Gospoda, ki te je odpeljal iz Egipta, iz hiše sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 13, 'Gospoda, Boga svojega, se boj in njemu služi in pri njegovem imenu prisegaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 14, 'Nikar ne hodite za drugimi bogovi, za bogovi tistih ljudstev, ki so okoli vas;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 15, 'zakaj Bog mogočni, gorečnik, je Gospod, Bog tvoj, sredi tebe, da se ne vname srd Gospoda, tvojega Boga, zoper tebe in te ne zatare s površja zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 16, 'Ne izkušajte Gospoda, Boga svojega, kakor ste ga izkušali v Masi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 17, 'Resno pazi na zapovedi Gospoda, svojega Boga, in na njegova pričevanja in postave, ki ti jih je ukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 18, 'In delaj, kar je pravično in dobro v očeh Gospodovih, da se ti bo dobro godilo ter pojdeš in posedeš dobro deželo, ki jo je prisegel Gospod tvojim očetom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 19, 'ko preženeš vse sovražnike svoje pred seboj, kakor je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 20, 'Ko te sin tvoj povpraša v prihodnje in poreče: Kaj so tista pričevanja in postave in sodbe, ki vam jih je ukazal Gospod, Bog naš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 21, 'reci sinu svojemu: Sužnji smo bili Faraonu v Egiptu, a Gospod nas je izpeljal iz Egipta z mogočno roko;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 22, 'in Gospod je delal znamenja in čudeže, velike in pogubne, pri Faraonu in vsej hiši njegovi pred našimi očmi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 23, 'in nas je izpeljal odondod, da bi nas privedel v deželo ter nam jo dal, ki je zanjo prisegel našim očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 24, 'In Gospod nam je zapovedal, da izpolnjujmo vse te postave, da se bojmo Gospoda, Boga svojega, nam v dobro vse dni, da bi nas ohranil v življenju, kakor se vidi današnji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 6, 25, 'In to nam bode pravičnost, ako bomo pazili, da izpolnimo vso to zapoved pred Gospodom, Bogom svojim, kakor nam je zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 1, 'Ko te pripelje Gospod, tvoj Bog, v deželo, v katero greš, da jo posedeš, in zatre mnoge narode pred teboj, Hetejce, Girgasejce, Amorejce, Kanaance, Ferizejce, Hevejce in Jebusejce, sedem narodov, večjih in močnejših, nego si ti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 2, 'in ko ti jih izroči Gospod, tvoj Bog, in jih poraziš: tedaj jih pokončaš s prokletjem; ne skleni zaveze ž njimi, tudi se jih ne usmili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 3, 'Ne skleni svaštva ž njimi: svoje hčere ne daj njegovemu sinu, niti njegove hčere ne vzemi sinu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 4, 'Zakaj one bodo zapeljale sinove tvoje, da bi služili tujim bogovom; tako se vname Gospodov srd zoper vas in vas hitro pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 5, 'Ampak takole ravnajte ž njimi: poderite njih oltarje, zdrobite njih poslikane stebre in posekajte njih Ašere in njih izrezane podobe sežgite z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 6, 'Zakaj ti si sveto ljudstvo Gospodu, Bogu svojemu; tebe si je izvolil Gospod, tvoj Bog, da mu boš ljudstvo lastnine izmed vseh ljudstev, kar jih je na površju zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 7, 'Ni se k vam Gospod nagnil v ljubezni in vas izvolil, ker je vas več bilo nego kateregasibodi ljudstva, saj si najmanjše med vsemi ljudstvi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 8, 'marveč ker vas Gospod ljubi in hoče ohraniti prisego, ki jo je prisegel vašim očetom, vas je izpeljal z mogočno roko in odrešil iz hiše sužnosti, iz roke Faraona, kralja egiptovskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 9, 'Vedi torej, da Gospod, tvoj Bog, sam je Bog, zvesti Bog mogočni, ki hrani zavezo in milost do tisoč rodov tistim, ki ga ljubijo in drže njegove zapovedi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 10, 'ki pa povrne svojim sovražilcem v lice, da jih pogubi; ne odlaša sovražilcu svojemu, kar v lice mu povrača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 11, 'Hrani torej zapoved, postave in sodbe, ki ti jih danes zapovedujem, da jih izpolnjuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 12, 'In zgodi se, ko boste poslušali te sodbe, jih hranili in izpolnjevali, da ti ohrani Gospod zavezo in milost, ki jo je s prisego obljubil tvojim očetom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 13, 'ljubil te bo in te blagoslovil in razmnoževal; blagoslovil bo sad tvojega telesa in tvoje zemlje sad, žito, vino in olje tvoje, prirejo goved tvojih in drobnice tvoje, v deželi, ki jo je tebi dati prisegel tvojim očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 14, 'Blagoslovljen boš mimo vseh ljudstev; ne bode med vami nerodovitnega in nerodovitne, tudi ne med tvojo živino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 15, 'Gospod odvrne od tebe vsako bolezen in ne da, da bi te zadela katera kužnih egiptovskih bolezni, ki jih poznaš, ampak pošlje jih nad tvoje sovražilce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 16, 'In uničiš vsa ljudstva, katera ti izroči Gospod, tvoj Bog; oko tvoje naj jim ne prizanaša; tudi ne služi njih bogovom, zakaj to bi ti bilo v zanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 17, 'Ako pa porečeš v srcu svojem: Močnejši po številu so ti narodi od mene, kako naj jih preženem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 18, 'nič se jih ne boj; dobro pomni, kar je storil Gospod, tvoj Bog, Faraonu in vsemu Egiptu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 19, 'pomni velike izkušnje, ki so jih videle tvoje oči, in znamenja in čudeže in mogočno roko in ramo iztegnjeno, s katerimi te je izpeljal Gospod, tvoj Bog: enako stori Gospod, tvoj Bog, vsem narodom, katerih se bojiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 20, 'Tudi sršene pošlje Gospod, tvoj Bog, mednje, da poginejo še tisti, ki so preostali in ki so se poskrili pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 21, 'Ne straši se jih, zakaj Gospod, tvoj Bog, je sredi tebe, mogočni Bog, veliki in grozni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 22, 'Gospod pa, tvoj Bog, zatre one narode pred teboj malo po malo; ne moreš jih mahoma pokončati, da se ne pomnože zoper tebe zveri na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 23, 'A Gospod, tvoj Bog, ti jih izroči in napravi veliko zmešnjavo med njimi, dokler ne bodo iztrebljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 24, 'Njih kralje ti da v pest, in storiš, da izgine njih ime izpod neba. Nihče se ti ne more ustavljati, dokler jih ne potareš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 25, 'Podobe njih bogov sežgite z ognjem; srebra in zlata, ki je na njih, ne poželi, tudi si ga ne vzemi, da ne bi se s tem zapletel v zanko: zakaj to je gnusoba Gospodu, tvojemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 7, 26, 'In take gnusobe ne nosi v svojo hišo, da ne boš izročen prokletju, kakor je ona: nad vse mrzka in gnusna ti bodi, kajti prokleta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 1, 'Vso zapoved, ki ti jo danes zapovedujem, hrani in izpolnjuj, da bi živeli in se množili ter šli v deželo in se je polastili, ki jo je prisegel Gospod vašim očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 2, 'In spominjaj se vsega pota, po katerem te je vodil Gospod, tvoj Bog, teh štirideset let po puščavi, da bi te ponižal in izkusil, da spozna, kaj je v tvojem srcu, ali boš držal njegove zapovedi ali ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 3, 'In poniževal te je in te vodil v lakoto; in živil te je z mano, ki je nisi poznal ne ti, ne očetje tvoji, da ti pokaže, da ne živi človek ob samem kruhu, temuč ob vsem, kar prihaja iz ust Božjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 4, 'Obleka se ni prestarala na tebi in noga ti ni otekla teh štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 5, 'Spoznaj torej v srcu svojem, da te strahuje Gospod, tvoj Bog, kakor strahuje mož svojega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 6, 'In drži zapovedi Gospoda, Boga svojega, hodeč po njegovih potih in boječ se njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 7, 'Zakaj Gospod, tvoj Bog, te pelje v dobro deželo, v deželo potokov, studencev in jezer, ki izvirajo po dolinah in gorah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 8, 'v deželo, kjer je dosti pšenice in ječmena, vinske trte in smokovih dreves in margaranovih jabolk, v deželo, kjer je obilo oljk in medú,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 9, 'v deželo, kjer ne boš jedel kruha po siromaško, kjer ti ničesar ne bo manjkalo; v deželo, katere kameni so železo in ki iz njenih gorá lahko koplješ rude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 10, 'In ko boš jedel in se nasitil, hvali Gospoda, Boga svojega, za to dobro deželo, ki ti jo je dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 11, 'Varuj se, da ne pozabiš Gospoda, Boga svojega, da ne bi držal njegovih zapovedi, sodb in postav, ki ti jih danes zapovedujem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 12, 'da se ti ne bo, ko boš jedel in se nasitil, sezidal lepih hiš in v njih prebival,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 13, 'ko se ti pomnoži goved in drobnica ter poobili srebro in zlato ter poveča vse imetje tvoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 14, 'da se ti ne bo prevzelo srce in pozabiš Gospoda, Boga svojega, ki te je odpeljal iz dežele Egiptovske, iz hiše sužnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 15, 'ki te je vodil po puščavi, veliki in grozoviti, kjer so ognjene kače in škorpijoni, žejna tla, a vode nobene; ki ti je dal vodo iz kremenite skale,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 16, 'ki te je živil v puščavi z mano, ki je niso poznali očetje tvoji, da te poniža in izkusi, da bi ti dobro storil v tvoji prihodnosti –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 17, 'in ti bi govoril v srcu svojem: Moja moč in mojih rok krepkost mi je pridobila tole bogastvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 18, 'Ampak spominjaj se Gospoda, Boga svojega, zakaj on je, ki ti podeljuje moč, da pridobiš bogastvo, da potrdi, kakor danes, zavezo svojo, ki jo je prisegel tvojim očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 19, 'Ako pa pozabiš Gospoda, svojega Boga, in boš hodil za tujimi bogovi in jim služil ter jih molil, pričam zoper vas danes, da gotovo poginete;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 8, 20, 'kakor narodi, ki jih Gospod daje v pogubo pred vami, enako poginete vi, ker niste hoteli poslušati glasu Gospoda, svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 1, 'Poslušaj, Izrael: ti pojdeš v tem času čez Jordan, da v posest vzameš last narodov, večjih in močnejših od tebe, velika, do neba obzidana mesta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 2, 'veliko in visoke postave ljudstvo, sinove Enakimov, ki jih poznaš in si o njih slišal: Kdo more stati pred Enakovimi sinovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 3, 'Danes torej vedi, da Gospod, tvoj Bog, gre pred teboj kot požigajoč ogenj: on jih potere in on jih potlači pred teboj, ti pa jih preženeš in v kratkem pokončaš, kakor ti je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 4, 'Ko pa jih prepodi Gospod, tvoj Bog, pred teboj, nikar si ne govori v srcu: Zaradi moje pravičnosti me je vpeljal sem Gospod, da obvladam to deželo; ker zaradi brezbožnosti teh narodov jih prežene Gospod pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 5, 'A ne zaradi svoje pravičnosti in srca svojega poštenosti pojdeš tja, da dobiš v last njih deželo, marveč zaradi brezbožnosti teh narodov jih izžene Gospod, tvoj Bog, pred teboj ter da bi potrdil besedo, ki jo je prisegel tvojim očetom, Abrahamu, Izaku in Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 6, 'Vedi torej, da ti nikakor ne da Gospod, tvoj Bog, te dobre dežele v posest zaradi tvoje pravičnosti, zakaj trdovratno ljudstvo si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 7, 'Spominjaj se, ne pozabi, kako si v puščavi dražil v jezo Gospoda, svojega Boga: od dne, ko ste odšli iz dežele Egiptovske, in dokler ste potovali na ta kraj, ste bili uporni Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 8, 'Tudi na Horebu ste razdražili v jezo Gospoda, in Gospod se je razsrdil na vas, da vas je hotel pokončati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 9, 'Ko sem bil šel na goro, da prejmem kameneni plošči, plošči zaveze, ki jo je Gospod sklenil z vami, sem ostal na gori štirideset dni in štirideset noči; kruha nisem jedel in vode nisem pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 10, 'In Gospod mi je izročil dve kameneni plošči, popisani z Božjim prstom; in pisano je bilo na njiju soglasno z vsemi besedami, ki jih je vam Gospod govoril na gori iz sredi ognja v dan zbora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 11, 'Ko je minilo štirideset dni in štirideset noči, mi da Gospod tisti kameneni plošči, plošči zaveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 12, 'In Gospod mi reče: Vstani, hitro pojdi doli odtod; zakaj tvoje ljudstvo, ki si ga izpeljal iz Egipta, se je skazilo. Hitro so zašli s pota, ki sem ga jim zapovedal: naredili so si ulito podobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 13, 'Dalje mi je govoril Gospod takole: Videl sem to ljudstvo, in glej, trdovratno ljudstvo je;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 14, 'pusti mi, da jih pokončam in izbrišem njih ime izpod neba; tebe pa hočem storiti v narod močnejši in večji, nego so oni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 15, 'Obrnil sem se torej in stopal doli z gore, gora pa je z ognjem gorela, in tisti dve plošči zaveze sem držal z obema rokama:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 16, 'In pogledam, in glej, pregrešili ste se zoper Gospoda, svojega Boga, ko ste si naredili ulito tele; hitro ste zašli s pota, ki vam ga je zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 17, 'Tedaj zgrabim tisti plošči ter ju vržem iz rok, in razbil sem ju pred vašimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 18, 'In padel sem pred Gospodom in ležal kakor poprej štirideset dni in štirideset noči: kruha nisem jedel in vode nisem pil zaradi vseh vaših grehov, s katerimi ste se pregrešili, ker ste storili, kar je zlo v očeh Gospodovih, da ga dražite v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 19, 'Zakaj bal sem se srda in togote, s katero se je jezil Gospod nad vami, hoteč vas pokončati. Ali Gospod me je uslišal tudi to pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 20, 'Tudi nad Aronom se je srdil Gospod silno, hoteč ga pokončati; in molil sem tudi za Arona tisti čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 21, 'In vzamem vaš greh, tele, ki ste ga naredili, in ga sežgem v ognju in razbijem na kosce ter vsega strem, da je bil drobičken prah, in prah vržem v potok, ki teče z gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 22, 'Tudi v Taberi, v Masi in pri Grobeh poželjivosti ste dražili Gospoda v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 23, 'In ko vas je Gospod poslal iz Kades-barnee, rekoč: Pojdite gori, pripravite v svojo last deželo, ki sem vam jo dal, ste se uprli povelju Gospoda, svojega Boga, in niste mu verovali in niste poslušali njegovega glasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 24, 'Uporni ste bili Gospodu od dne, odkar vas poznam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 25, 'Padel sem torej in ležal pred Gospodom tistih štirideset dni in štirideset noči, ker je bil rekel Gospod, da vas pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 26, 'In molil sem h Gospodu in dejal: Gospod Jehova, ne pogubi ljudstva svojega in dediščine svoje, ki si jo odkupil po velikosti svoji, ki si jo izpeljal iz Egipta z mogočno roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 27, 'Spomni se svojih hlapcev, Abrahama, Izaka in Jakoba; ne oziraj se na trdokornost tega ljudstva, na njih brezbožnost in greh;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 28, 'da se ne bo govorilo v deželi, odkoder si nas izpeljal: Ker jih Gospodu ni bilo moči privesti v deželo, katero jim je obljubil, in ker jih je sovražil, jih je izpeljal, da jih pobije v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 9, 29, 'Saj ljudstvo so tvoje in dediščina tvoja, ki si jo izpeljal z veliko svojo močjo in z iztegnjeno ramo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 1, 'Tisti čas mi reče Gospod: Izsekaj si dve kameneni plošči, kakor sta bili prejšnji, in stopi k meni na goro, in naredi si leseno skrinjo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 2, 'in napišem na plošči besede, ki so bile na prejšnjih, ki si ju razbil, ti pa vloži v skrinjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 3, 'Naredil sem torej skrinjo iz akacijevega lesa in izsekal dve plošči iz kamena, kakor sta bili prejšnji, in stopil sem na goro z obema ploščama v roki svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 4, 'Tedaj je napisal na plošči soglasno s prvim pismom tistih deset besed, ki vam jih je Gospod govoril na gori, iz sredi ognja, v dan zbora; nato mi ju da Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 5, 'in jaz se obrnem in stopim doli z gore in položim plošči v skrinjo, ki sem jo naredil, in ondi sta, kakor mi je bil Gospod zapovedal. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 6, 'Sinovi Izraelovi pa so šli od Vodnjaka Jakanovih sinov v Mozero; tam je umrl Aron in tam je bil pokopan. In Eleazar, njegov sin, je služboval kot duhovnik na njegovem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 7, 'Odtod so potovali v Gudgodo in iz Gudgode v Jotbato, v pokrajino potokov vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 8, 'Tisti čas je Gospod oddelil rod Levijev, da naj nosi skrinjo Gospodove zaveze in stoji pred Gospodom, pripravljen za službo, ter blagoslavlja v njegovem imenu, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 9, 'Zato nima Levi deleža, ne dediščine s svojimi brati; Gospod je njegova dediščina, kakor mu je obljubil Gospod, tvoj Bog. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 10, 'Jaz pa sem ostal na gori kakor prvikrat štirideset dni in štirideset noči, in Gospod me je uslišal tudi to pot; ni te hotel Gospod pogubiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 11, 'A Gospod mi je velel: Vstani, odidi in pojdi pred ljudstvom, da dospejo v deželo in jo posedejo, ki sem zanjo prisegel njih očetom, da jim jo dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 12, 'Sedaj pa, o Izrael, kaj zahteva Gospod, tvoj Bog, od tebe? Samo to: da se bojiš Gospoda, svojega Boga, da hodiš po vseh njegovih potih, da ga ljubiš in služiš Gospodu, svojemu Bogu, iz vsega srca svojega in iz vse duše svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 13, 'da držiš Gospodove zapovedi in njegove postave, ki ti jih danes zapovedujem tebi v dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 14, 'Glej, Gospoda, tvojega Boga, je nebo in nebesa nebes, zemlja in vse, kar je na njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 15, 'Vendar se je samo k tvojim očetom milo nagnil Gospod, da bi jih ljubil, in izvolil si je njih seme za njimi, to je vas, mimo vseh ljudstev, kakor je danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 16, 'Obrežite torej neobrezo svojega srca in ne bodite več trdovratni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 17, 'Zakaj Gospod, vaš Bog, on je Bog bogov in gospodov Gospod, Bog mogočni, veliki, silni in grozni, ki se ne ozira, kdo je kdo, in ne jemlje podkupila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 18, 'ki se poteguje za pravdo sirote in vdove in ljubi tujca, podeljujoč mu živeža in oblačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 19, 'Zato ljubite tujca, kajti tujci ste bili v Egiptovski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 20, 'Gospoda, svojega Boga, se boj, njemu služi, njega se oklepaj in pri njegovem imenu prisegaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 21, 'On je hvala tvoja, on tvoj Bog, ki je zate storil tiste velike in strašne reči, ki so jih videle tvoje oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 10, 22, 'tvoji očetje so šli doli v Egipt s sedemdesetimi dušami, sedaj pa te je Gospod, tvoj Bog, pomnožil kakor zvezde na nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 1, 'Zatorej ljubi Gospoda, svojega Boga, in vse dni pazi na njegovo službo, na postave, sodbe in zapovedi njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 2, 'In spoznajte danes (zakaj ne govorim z vašimi otroki, ki niso spoznali in ki niso videli) strahovanje Gospoda, svojega Boga, njegovo velikost, mogočno roko in iztegnjeno ramo njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 3, 'znamenja in dela njegova, ki jih je storil sredi Egipta Faraonu, egiptovskemu kralju, in vsej njegovi deželi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 4, 'in kaj je storil vojski Egipčanov, njih konjem in njih vozovom: kako je privedel vode Rdečega morja nadnje, ko so se gnali za vami, in jih je Gospod pogubil do današnjega dne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 5, 'in koliko je za vas storil v puščavi, dokler niste prišli v ta kraj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 6, 'in kaj je storil Datanu in Abiramu, sinoma Eliaba, Rubenovega sinu: kako je odprla zemlja žrelo in ju požrla ž njih družinami in šatori in s slehernim živim bitjem, ki je šlo za njima, sredi vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 7, 'Zakaj vaše oči so videle vsa velika dela Gospodova, ki jih je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 8, 'Zato držite vso zapoved, ki vam jo danes zapovedujem, da bodete močni ter obvladate deželo, ko pridete vanjo, v katero greste, da jo posedete;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 9, 'in da podaljšate dni svoje v deželi, za katero je prisegel Gospod vašim očetom, da jim jo da in njih zarodu, deželo, kjer teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 10, 'Dežela namreč, ki jo greste posedat, ni kakor Egiptovska dežela, iz katere ste odšli, kjer si sejal seme in moral napeljevati vodo nanje s svojo nogo kakor na zelenjadni vrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 11, 'Ampak dežela, kamor potujete, da se je polastite, je dežela hribov in dolin in pije vodo od dežja z neba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 12, 'dežela je, za katero skrbi Gospod, tvoj Bog: vedno so oči Gospoda, tvojega Boga, obrnjene nanjo, od začetka do konca leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 13, 'Ako boste torej marljivo poslušali moje zapovedi, ki vam jih danes zapovedujem, da boste ljubili Gospoda, svojega Boga, in mu služili iz vsega srca svojega in iz vse duše svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 14, 'bo dajal dežja vaši deželi ob pravem času, zgodnjega in poznega dežja, da spraviš žito, vino in olje svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 15, 'tudi za živino tvojo ti dam trave na polju, in jedel boš in se nasitil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 16, 'Varujte se, da se ne da premotiti vaše srce, da bi odstopili s pota in služili tujim bogovom ter jih molili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 17, 'in Gospodova jeza bi se razvnela proti vam, in zaprl bi nebo, da ne bo dežja in da zemlja ne obrodi sadu svojega, in poginili bi hitro iz predobre dežele, ki vam jo da Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 18, 'Zato si vtisnite te besede moje v srce in v dušo svojo in privežite si jih za znamenje na roko in naj bodo kot čelno vezilo med vašimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 19, 'In učite jih svoje otroke, govoreč o njih, ko sediš v hiši svoji, ko hodiš po poti, ko greš spat in ko vstajaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 20, 'In napiši jih na podboje svoje hiše in na vrata svoja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 21, 'da se pomnože vaši in vaših otrok dnevi, kakor se množe dnevi neba nad zemljo, v deželi, ki jo je s prisego obljubil Gospod očetom vašim, da jim jo da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 22, 'Kaj ti če boste zvesto hranili vso to zapoved, ki vam jo zapovedujem, izpolnjujoč jo s tem, da ljubite Gospoda, svojega Boga, hodite po vseh potih njegovih in se ga oklepate,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 23, 'tedaj prežene Gospod vse te narode pred vami in posedete last narodov, ki so večji in močnejši od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 24, 'Vsak kraj, na katerega stopi vaša noga, bode vaš: od puščave in Libanona, od velereke Evfrata tja do Zahodnega morja bodo vaše meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 25, 'Nihče ne bo mogel obstati pred vami; strah in grozo pred vami pošlje Gospod, vaš Bog, nad vso tisto deželo, po kateri boste hodili, kakor vam je obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 26, 'Poglejte, danes stavim pred vas blagoslov in prokletstvo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 27, 'blagoslov, ako poslušate zapovedi Gospoda, svojega Boga, ki vam jih danes zapovedujem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 28, 'prokletstvo pa, ako ne poslušate zapovedi Gospoda, svojega Boga, temuč krenete s poti, ki vam jo danes zapovedujem, da bi šli za tujimi bogovi, ki jih niste poznali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 29, 'In zgodi se naj, ko te pripelje Gospod, tvoj Bog, v deželo, kamor jo greš posest, da deneš blagoslov na goro Garizim, prokletstvo pa na goro Ebal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 30, 'ki sta onostran Jordana, v smeri proti solnčnemu zahodu, v deželi Kanaancev, ki prebivajo v nižini, nasproti Gilgalu, pri hrastih Morejevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 31, 'Kajti skoraj pojdete čez Jordan, da se polastite dežele, ki vam jo daje Gospod, Bog vaš, in dobite jo v last in boste prebivali v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 11, 32, 'A pazite, da izpolnjujete vse postave in sodbe, ki vam jih predlagam danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 1, 'To so postave in sodbe, na katere vam je paziti, da jih izpolnjujete v deželi, ki ti jo je dal Gospod, Bog tvojih očetov, da jo posedete, vse dni, dokler boste živeli na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 2, 'Ugonobite docela vse kraje, v katerih so narodi, ki jih dobite v last, služili svojim bogovom, na visokih gorah, na hribih in pod vsakim zelenim drevesom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 3, 'in zrušite njih oltarje in zdrobite njih poslikane stebre in z ognjem požgite njih Ašere in podobe njih bogov posekajte, tudi njih ime potrebite iz teh krajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 4, 'Ne delajte pa tako Gospodu, svojemu Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 5, 'temuč iščite njegovo prebivališče na mestu, ki si ga izvoli Gospod, vaš Bog, izmed vseh rodov vaših, da ustanovi ondi ime svoje. In tja prihajajte,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 6, 'tja tudi prinašajte žgalščine in klalščine in desetine svoje in podvig iz rok svojih in obljube svoje in prostovoljna darila in prvorojeno govedi in drobnice svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 7, 'in tam jejte pred Gospodom, svojim Bogom, ter veselite se vi in vaše rodbine vsega pridelka svojih rok, ki ti ga je blagoslovil Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 8, 'Ne delajte tako, kakor delamo mi danes tu, vsakdo, karkoli se mu vidi prav:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 9, 'zakaj zdaj še niste prišli v pokoj in v dediščino, ki ti jo da Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 10, 'Toda ko preidete Jordan in boste prebivali v deželi, ki vam jo pripravlja v dediščino Gospod, vaš Bog, in ko vam da pokoj pred vsemi vašimi sovražniki naokrog, da boste prebivali brez skrbi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 11, 'tedaj bodi tako: na mesto, ki si ga izvoli Gospod, vaš Bog, da bi ondi prebivalo njegovo ime, tja prinašajte vse, kar vam zapovedujem: žgalne in klalne daritve in desetine svoje in podvig iz rok svojih in vso izbiro obljub, ki jih obetate Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 12, 'in veselite se pred Gospodom, svojim Bogom, vi in vaši sinovi in hčere in vaši hlapci in dekle in levit, ki je v vašem mestu, ker on nima deleža, ne dediščine kakor vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 13, 'Varuj se, da ne daruješ žgalnih daritev svojih na katerembodi mestu, ki ga ugledaš,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 14, 'temuč na mestu, ki ga Gospod izvoli v enem tvojih rodov, ondi daruj žgalščine in ondi izvršuj vse, kar ti zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 15, 'Vendar pa smeš po vsej želji duše svoje klati in jesti meso v vseh svojih mestih, po blagoslovu Gospoda, svojega Boga, ki ti ga je dodelil; čisti in nečisti naj jé od tega, kakor od srne in od jelena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 16, 'Samo krvi ne jejte, na zemljo jo izlijte kakor vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 17, 'Ne smeš jesti v svojih mestih desetine žita in vina in olja svojega, ne prvostorjenega govedi in drobnice svoje, ne vseh obljub, ki jih obljubiš, ne prostovoljnih daril, ne podviga rok svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 18, 'ampak uživaj jih pred Gospodom, svojim Bogom, na mestu, ki si ga izvoli Gospod, tvoj Bog, ti in sin tvoj in hči tvoja, hlapec tvoj in dekla tvoja in levit, ki je v tvojem mestu, in veséli se pred Gospodom, svojim Bogom, vsega pridelka svojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 19, 'Varuj se, da ne zapustiš levita vse dni, dokler živiš na zemlji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 20, 'Ko razširi Gospod, tvoj Bog, tvoje meje, kakor ti je obljubil, in porečeš: Hočem jesti meso, ker poželi tvoja duša jesti meso, po vsej želji svoje duše smeš jesti meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 21, 'Ako bode daleč od tebe mesto, ki si ga izvoli Gospod, tvoj Bog, da tja umesti svoje ime, tedaj smeš klati od govedi in drobnice, ki ti jo je dal Gospod, kakor sem ti velel, in jesti v mestu svojem po vsej želji duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 22, 'Kakor ješ srno in jelena, tako jej od tega; nečisti in čisti naj enako jesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 23, 'Samo v tem bodi neupogljiv, da ne ješ krvi, zakaj kri je duša, in ne smeš jesti duše z mesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 24, 'Ne jej je torej, na zemljo jo izlij kakor vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 25, 'Ne jej je, da bi se dobro godilo tebi in tvojim otrokom za teboj, ko boš delal, kar je prav v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 26, 'Samo svete reči svoje, kar jih imaš, in obljube svoje vzemi in pridi na mesto, ki si ga izbere Gospod;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 27, 'in daruj žgalne daritve svoje, meso in kri, na oltarju Gospoda, svojega Boga; in kri tvojih žrtev naj se izlije na oltar Gospoda, tvojega Boga, meso pa smeš užiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 28, 'Hrani in poslušaj vse te besede, ki ti jih zapovedujem, da se bo dobro godilo tebi in tvojim otrokom za teboj do vekomaj, ko delaš, kar je dobro in prav v očeh Gospoda, Boga tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 29, 'Ko iztrebi Gospod, tvoj Bog, narode pred teboj ondi, kamor greš, da posedeš njih last, in ko se jih polastiš in se naseliš v njih deželi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 30, 'varuj se, da se ne zapleteš v zanko, posnemaje jih, potem ko bodo pokončani izpred tebe, ter da ne vprašaš po njih bogovih, govoreč: Kako so služili ti narodi svojim bogovom? tudi jaz hočem kakor oni delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 31, 'Ne delaj tako Gospodu, svojemu Bogu, zakaj vse, kar je Gospodu gnusoba, kar on sovraži, so delali svojim bogovom; saj so celo svoje sinove in hčere sežigali v ognju bogovom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 12, 32, 'Na vse, karkoli vam zapovedujem, pazite, da izpolnjujete; ničesar ne pristavi in tudi ne vzemi od tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 1, 'Ako vstane sredi tebe prorok ali kdor ima sanje in ti pokaže znamenje ali čudež');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 2, 'in se zgodi tisto znamenje ali čudo, za katero ti je pravil, rekoč: Pojdimo za drugimi bogovi, katerih nisi poznal, in služimo jim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 3, 'ne poslušaj besed takega proroka ali tistega, ki ima sanje; zakaj Gospod, vaš Bog, vas izkuša, da se spozna, ali ljubite Gospoda, svojega Boga, iz vsega srca svojega in iz vse duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 4, 'Za Gospodom, svojim Bogom, hodite, njega se bojte, njegove zapovedi hranite in njegov glas poslušajte, njemu služite in njega se oklepajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 5, 'Tisti prorok pa ali tisti sanjač mora umreti, zato ker je svetoval odpad zoper Gospoda, vašega Boga, ki vas je izpeljal iz dežele Egiptovske in vas odkupil iz hiše sužnosti, da bi te pahnil s pota, po katerem ti je zapovedal Gospod hoditi. Tako odpraviš hudo izmed sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 6, 'Ako te izpodbuja na skrivnem tvoj brat, sin matere tvoje, ali tvoj sin, ali tvoja hči, ali žena, ki ti je v naročju, ali prijatelj, ki ti je kakor tvoje srce, govoreč: Pojdimo in služimo drugim bogovom, ki jih nisi poznal ne ti, ne očetje tvoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 7, 'izmed bogov tistih ljudstev, ki so okoli tebe, bodisi blizu tebe ali daleč od tebe, od enega do drugega konca zemlje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 8, 'ne vdaj se mu, tudi ga ne poslušaj, in naj se ga ne usmili oko tvoje, da bi mu prizanesel ali pa ga skrival,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 9, 'marveč umoriti ga moraš; tvoja roka bodi prva nad njim, da bo dan v smrt, in potem vsega ljudstva roka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 10, 'S kamenjem ga posuješ, da umre, ker te je hotel odvrniti od Gospoda, tvojega Boga, ki te je odpeljal iz dežele Egiptovske, iz hiše sužnosti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 11, 'da začuje to ves Izrael in se boji in nihče več ne počenja take hudobnosti sredi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 12, 'Ako zaslišiš, da kdo poreče o enem iz tvojih mest, ki ti jih Gospod, tvoj Bog, da v prebivanje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 13, 'Neki možje, otroci Belijalovi, so prišli izmed naših in odvrnili prebivalce svojega mesta, govoreč: Pojdimo in služimo drugim bogovom, ki jih niste poznali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 14, 'tedaj poišči, poizvedi in natanko izprašaj, in glej, resnično je in dokazano, da se je taka gnusoba storila sredi tebe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 15, 'udari torej prebivalce tistega mesta z ostrino meča in s prokletjem ga pokončaj in vse, kar je v njem, tudi živino, z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 16, 'In ves plen iz njega zberi sredi njegovih ulic in sežgi z ognjem mesto in ves njegov plen dočista Gospodu, svojemu Bogu; in grobljišče bodi vekomaj, nikoli več ne bodi sezidano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 17, 'In od tega v prokletje izročenega naj se nič ne prime tvoje roke; da se obrne Gospod od togote svojega srda in ti izkaže usmiljenje in te pomiluje in te pomnoži, kakor je prisegel očetom tvojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 13, 18, 'ker poslušaš glas Gospoda, svojega Boga, da bi držal vse njegove zapovedi, ki ti jih jaz danes zapovedujem, delajoč, kar je prav v očeh Gospoda, tvojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 1, 'Sinovi ste Gospodu, svojemu Bogu: ne delajte si zarez, tudi si ne delajte pleše med očmi zaradi mrtveca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 2, 'Zakaj sveto ljudstvo si Gospodu, svojemu Bogu, in Gospod si te je izvolil, da mu bodi ljudstvo lastnine izmed vseh ljudstev, kar jih je na zemlje površju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 3, 'Ne jej nikakršne gnusne stvari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 4, 'To so živali, ki jih smete jesti: govedo, ovca in koza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 5, 'jelen in srna, damjak, kozorog, divja koza, antilopa in semer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 6, 'In vsako žival, ki dvoji parklje in ima docela na dvoje razklane parklje in prežvekuje med živalmi, smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 7, 'Toda izmed tistih, ki prežvekujejo ali imajo razklane parklje, teh ne jejte: velbloda, zajca in skalnega jazbeca, ki sicer prežvekujejo, a nimajo razklanega parklja, nečisti naj vam bodo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 8, 'tudi svinje ne, ker dvoji parkelj, a ne prežvekuje, nečista vam bodi. Njih mesa ne jejte in njih mrline se ne doteknite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 9, 'Téle jejte izmed vseh, ki so v vodah: karkoli ima plavute in luske, smete jesti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 10, 'karkoli pa nima plavut in lusk, ne jejte: nečisto je za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 11, 'Vse čiste ptice smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 12, 'Te pa so, katerih ne jejte: orel, brkati ser in morski orel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 13, 'in ostrovidec in sokol in kanja po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 14, 'in vsak gavran po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 15, 'in noj, kukavica, morski galeb in jastreb po svojih plemenih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 16, 'skovir, vir in sova,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 17, 'pelikan in mrhar in potapljač,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 18, 'in štorklja in čaplja po svojih plemenih, smrdokavra in netopir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 19, 'In vsa okriljena laznina je nečista za vas, ne boste je jedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 20, 'Vso čisto perutnino smete jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 21, 'Ne jejte nobene mrline; smeš jo dati tujcu, ki je v tvojih vratih, da jo zaužije, ali pa prodati inostrancu; zakaj sveto ljudstvo si ti Gospodu, svojemu Bogu. Ne kuhaj kozliča v mleku njegove matere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 22, 'Odloči desetino vsega obrodka svoje setve, ki zraste na njivi leto za letom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 23, 'In uživaj pred Gospodom, svojim Bogom, na mestu, ki si ga izvoli, da bi ondi prebivalo ime njegovo, desetino žita, vina in olja svojega in prvence govedi in drobnice svoje, da se naučiš bati se Gospoda, svojega Boga, vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 24, 'In če ti bode pot predolga, da ne boš mogel prinesti, s čimer te oblagodari Gospod, tvoj Bog, ker je predaleč od tebe mesto, ki si ga izvoli Gospod, tvoj Bog, da ustanovi ondi svoje ime:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 25, 'tedaj zameni to za denar; in z zvezkom denarja v roki pojdi na mesto, ki si ga izvoli Gospod, tvoj Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 26, 'in kupi za denar vsega, česar poželi duša tvoja, goved, ovac, vina, močne pijače, in česarkoli zahteva duša tvoja, in tam jej pred Gospodom, svojim Bogom, ter se veséli ti in tvoja družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 27, 'Ali levita, ki bi bil v tvojem mestu, ne zapusti, kajti nima deleža, ne dediščine kakor ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 28, 'Ob koncu vsakega tretjega leta pa odloči vso desetino svojega pridelka istega leta in jo pusti v svojih vratih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 14, 29, 'da naj pride levit, ker nima deleža, ne dediščine kakor ti, in tujec, sirota in vdova, ki bivajo v tvojem mestu, in naj jedo ter se nasitijo, da bi te blagoslovil Gospod, tvoj Bog, pri vsem delu tvojih rok, ki ga opravljaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 1, 'Ob koncu vsakega sedmega leta napravi odpuščanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 2, 'In ta bodi način odpuščanja: odpusti naj vsak upnik, kar je posodil svojemu bližnjemu; ne terjaj za to svojega bližnjega ali svojega brata, ker je bilo Gospodovo odpuščanje razglašeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 3, 'inostranca smeš za to terjati, ali karkoli je tvojega pri tvojem bratu, mu odpústi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 4, 'Samo da ne bi bilo ubožca med vami; kajti Gospod te bo obilo blagoslovil v deželi, ki ti jo da Gospod, tvoj Bog, za dediščino, da jo posedeš;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 5, 'samo če boš zvesto poslušal glas Gospoda, svojega Boga, prizadevajoč si, da izpolnjuješ vso to zapoved, ki ti jo jaz danes zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 6, 'Ko te bo Gospod, tvoj Bog, blagoslovil, kakor ti je obljubil: tedaj boš posojeval mnogim narodom, sam pa ne boš ničesar jemal naposodo, vladal boš mnogim narodom, a tebi ne bo nihče vladal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 7, 'Ako bode med vami ubožec, eden bratov tvojih, v kateremkoli mestu v tvoji deželi, ki ti jo daje Gospod, vaš Bog, ne zakrkni srca svojega ter ne zapri roke svoje proti ubogemu svojemu bratu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 8, 'temuč rad mu odpri roko in voljno mu daj naposodo, kolikor zadostuje potrebi njegovi, česar strada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 9, 'Varuj se, da ne bo hudobne misli v tvojem srcu, da bi rekel: Bliža se sedmo leto, leto odpuščanja, in oko tvoje bi bilo hudobno proti ubogemu bratu tvojemu, in ničesar mu ne daš, in on bo vpil h Gospodu proti tebi, in greh bo na tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 10, 'Drage volje mu daj in ne bodi ti v srcu žal, ko mu daš, kajti za to stvar te bo blagoslovil Gospod, tvoj Bog, pri vsem tvojem delu in v vsem, česar se ti loti roka');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 11, 'Zakaj ubogih ne bo kar zmanjkalo v deželi, zatorej ti zapovedujem takole: Rad odpri roko svojemu bratu, potrebnemu in siromaku v deželi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 12, 'Če ti bo prodan tvoj brat, Hebrejec ali Hebrejka, naj ti služi šest let, v sedmem letu pa ga odpusti svobodnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 13, 'In ko ga odpustiš na svobodo, ne pusti ga praznega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 14, 'ampak obloži ga z darili od ovac svojih in z gumna svojega in iz tlačilnice svoje; daj mu od tega, s čimer te je blagoslovil Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 15, 'In spominjaj se, da si bil sužnik v deželi Egiptovski, in Gospod, tvoj Bog, te je odkupil: zato ti jaz danes to zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 16, 'Ako pa ti poreče: Ne pojdem od tebe – ker ljubi tebe in tvojo družino, ker se mu dobro godi pri tebi –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 17, 'vzemi šilo in mu prebodi uho na durih, in hlapec ti bode za vselej. Tudi s svojo deklo stori enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 18, 'Nikar naj se ti ne zdi težko, ko ga svobodnega odpuščaš, zakaj služil ti je vredno dvojnega najemnikovega plačila šest let; in Gospod, tvoj Bog, te bo blagoslovil v vsem, kar opravljaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 19, 'Vse prvorojeno, ki bo storjeno med tvojimi govedi in ovcami, kar jih bo samcev, posveti Gospodu, Bogu svojemu. V jarem ne vklepaj prvenca svoje govedi, tudi ne strizi prvencev svojih ovac.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 20, 'Pred Gospodom, Bogom svojim, jih použij ti in tvoja hiša, leto za letom, na mestu, ki si ga izvoli Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 21, 'Ako pa ima živinče kako hibo, da je hromo ali slepo, ali kakršnobodi hudo hibo, ga ne smeš darovati Gospodu, svojemu Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 22, 'temuč v svojih vratih ga zaužij. Čisti in nečisti naj to jé enako kakor srno in jelena,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 15, 23, 'samo krvi ne jej, na zemljo jo izlij kakor vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 1, 'Pazi na mesec Abib in pripravi pasho Gospodu, Bogu svojemu, zakaj v mesecu Abibu te je odpeljal Gospod, tvoj Bog, iz Egipta po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 2, 'Kot pasho daruj Gospodu, Bogu svojemu, ovco ali pa govedo na mestu, ki si ga izvoli Gospod, da bi ondi prebivalo ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 3, 'Nič kvašenega ne jej pri tem; sedem dni jej nekvašen kruh, kruh stiske, zakaj v naglici si odšel iz Egipta; da ohraniš v spominu dan svojega odhoda iz Egiptovske dežele vse svoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 4, 'In kvas naj se ne vidi pri tebi po vseh mejah tvojih sedem dni, tudi naj ne ostane nič od mesa, ki ga daruješ prvi dan zvečer, do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 5, 'Ne smeš darovati pashe v kateremkoli svojih mest, ki ti jih da Gospod, tvoj Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 6, 'marveč v kraju, ki si ga izvoli Gospod, tvoj Bog, da ondi prebiva ime njegovo, tam daruj pasho na večer, ob solnčnem zahodu, ob uri svojega odhoda iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 7, 'In speci jo in jej v kraju, ki si ga izvoli Gospod, tvoj Bog; zjutraj pa se lahko obrneš in pojdeš v šatore svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 8, 'Šest dni jej opresen kruh, in sedmi dan je slovesno zborovanje Gospodu, tvojemu Bogu, nobenega posla ne opravljaj tedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 9, 'Sedem tednov si štej: odkar prvič priložiš srp k žitu, začni šteti sedem tednov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 10, 'Nato praznuj praznik tednov Gospodu, svojemu Bogu, s tem, da daš prostovoljno darilo svoje roke, ki ga daj primerno, kakor te je blagoslovil Gospod, tvoj Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 11, 'in veseli se pred Gospodom, svojim Bogom, ti in sin tvoj in hči tvoja, hlapec tvoj in dekla tvoja, in levit, ki je v mestu tvojem, tujec, sirota in vdova, ki so med vami, na mestu, ki si ga izvoli Gospod, tvoj Bog, da ondi prebiva ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 12, 'In spominjaj se, da si bil sužnik v Egiptu; hrani te postave ter jih izpolnjuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 13, 'Praznik šatorov praznuj sedem dni, potem ko spraviš pridelke z gumna svojega in iz tlačilnice svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 14, 'in veseli se ob svojem prazniku, ti in sin tvoj in hči tvoja, hlapec tvoj in dekla tvoja in levit, tujec, sirota in vdova, ki so ob tvojih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 15, 'Sedem dni praznuj praznik Gospodu, svojemu Bogu, v kraju, ki si ga izvoli Gospod; zakaj Gospod, tvoj Bog, te bo blagoslovil pri vsem tvojem pridelku in pri vsakem delu tvojih rok, zato bodi le vesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 16, 'Trikrat v letu naj se prikažejo vsi moški tvoji pred Gospodom, tvojim Bogom, na mestu, ki si ga izvoli Gospod: o prazniku opresnikov, o prazniku tednov in o prazniku šatorov; a naj se ne prikažejo prazni pred Gospodom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 17, 'temuč vsak naj da, kolikor more, primerno blagoslovu, ki ti ga je dodelil Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 18, 'Sodnike in oblastnike si postavi po vseh svojih mestih, ki ti jih da Gospod, tvoj Bog, po svojih rodovih, in naj sodijo ljudstvo s pravično sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 19, 'Ne krivi pravice, ne oziraj se na osebo, tudi ne jemlji podkupila, zakaj podkupilo oslepi oči modrih in izprevrne besede pravičnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 20, 'Za pravičnost, le za pravičnost se poteguj, da boš živel in podedoval deželo, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 21, 'Ne zasadi si nobene Ašere, drevja kakršnekoli vrste, poleg oltarja Gospoda, svojega Boga, ki si ga zgradiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 16, 22, 'Tudi si ne postavi poslikanega stebra; to sovraži Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 1, 'Ne daruj Gospodu, svojemu Bogu, ne vola, ne ovce, ki ima hibo ali kaj hudega na sebi, zakaj gnusoba je to Gospodu, tvojemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 2, 'Ako se najde sredi tebe, v kateremkoli iz tvojih mest, ki ti jih da Gospod, tvoj Bog, mož ali žena, ki počenja, kar je hudo v očeh Gospoda, tvojega Boga, prestopajoč zavezo njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 3, 'ter gre in služi drugim bogovom in se jim klanja, ali pa solncu, ali mesecu, ali vsej vojski nebeški, kar sem prepovedal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 4, 'in tebi se sporoči in si slišal o tem: tedaj preišči to natanko. In ako je res in stvar dokazana in se je storila taka gnusoba v Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 5, 'izpelji tistega moža ali tisto ženo, ki sta izvršila to hudo reč, k vratom svojega mesta in posuj ju, tistega moža ali tisto ženo, s kamenjem, da umrjeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 6, 'Na izpovedbo dveh ali treh prič bodi izročen smrti, kdor mora umreti, ali na izpovedbo edine priče ga ne daj te v smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 7, 'Roka prič bodi prva nadenj, da ga usmrti, in potem roke vsega ljudstva. In tako potrebiš hudo izmed sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 8, 'Kadar ti bo pretežko kaj razsoditi med krvjo in krvjo, med pravdo in pravdo, med poškodbo in poškodbo, ko so preporne stvari v tvojih vratih, vstani in pojdi gori na mesto, ki si ga izvoli Gospod, tvoj Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 9, 'in pridi k duhovnikom levitom in k sodniku, ki bode tisti čas, in jih vprašaj, in oznanijo ti razsodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 10, 'Ti pa stori po glasu te razsodbe, ki ti jo oznanijo s tistega kraja, ki si ga izvoli Gospod; in pazi, da storiš vse, kakor te pouče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 11, 'Po glasu zakona, ki te ga bodo učili, in po sodbi, ki ti jo povedo, stóri; ne ugani se od izreka, ki ti ga naznanijo, ne na desno, ne na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 12, 'Mož pa, ki bi drzovito ravnal in ne poslušal duhovnika, ki tam stoji, da opravlja službo pred Gospodom, tvojim Bogom, ali pa sodnika, ta mož naj umrje; in potrebi hudo iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 13, 'In vse ljudstvo naj to sliši in se boji, in nikoli več naj ne ravna predrzno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 14, 'Ko prideš v deželo, ki ti jo daje Gospod, Bog tvoj, in si jo prilastiš in boš v njej prebival, in ko porečeš: Hočem si kralja postaviti, kakor ga imajo vsi narodi okoli mene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 15, 'tedaj si smeš postaviti za kralja le njega, ki si ga izvoli Gospod, tvoj Bog; enega izmed bratov svojih postavi za kralja nad seboj; inostranca, ki ni tvoj brat, si ne smeš postaviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 16, 'Samo naj se preveč ne peča s konji, tudi naj ne vodi ljudstva nazaj v Egipt, da bi si nabavil mnogo konj; zakaj Gospod vam je rekel: Nikoli več se ne vračajte po tem potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 17, 'Tudi ne imej mnogo žen, da ne bi se odvrnilo njegovo srce; tudi naj si ne nabira preveč srebra in zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 18, 'In ko zasede prestol svojega kraljestva, naj si zapiše v knjigo prepis tega zakona, ki ga hranijo duhovniki leviti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 19, 'in ima naj jo pri sebi ter jo bere vse dni svojega življenja, da se nauči bati se Gospoda, svojega Boga, hraniti vse besede tega zakona in te postave, da bi jih izpolnjeval;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 17, 20, 'da se ne povzdigne njegovo srce nad brate svoje ter da se ne gane od zapovedi ne na desno, ne na levo, da bi podaljšal dni svojega in tudi svojih sinov kraljevanja sredi Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 1, 'Duhovniki, leviti, ves Levijev rod, naj ne imajo deleža, ne dediščine z Izraelom vred; uživajo naj ognjene daritve Gospodove in njegov delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 2, 'Ali dediščine med svojimi brati naj ne imajo; Gospod je njih dediščina, kakor jim je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 3, 'To pa je določeno duhovniku, da dobi od ljudstva, od tistih, ki prinašajo daritev, bodisi vol ali ovca: naj dado duhovniku pleče, obe čeljusti in želodec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 4, 'Prvine žita, vina in olja svojega, prvine od ovčje striže svoje mu daj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 5, 'Zakaj njega je izvolil Gospod, tvoj Bog, izmed vseh tvojih rodov, da stoji pri svetišču, opravljaje službo v imenu Gospodovem, on in njegovi sinovi vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 6, 'Ko pa pride levit iz kateregakoli tvojih mest po vsem Izraelu, kjer gostuje, in pride, ker mu duša močno hrepeni, na mesto, ki si ga izvoli Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 7, 'in bo stregel v imenu Gospoda, svojega Boga, kakor vsi njegovi bratje leviti, ki stoje ondi pred Gospodom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 8, 'enake obroke naj jedo, razen tega naj ima, kar proda dednih stvari svojih očetov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 9, 'Ko prideš v deželo, ki ti jo daje Gospod, tvoj Bog, ne uči se posnemati gnusob tistih poganskih narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 10, 'Naj ne bo med vami nikogar, ki bi peljal svojega sina ali svojo hčer skozi ogenj, ne nikogar, ki vedežuje, ali tolmači znamenja, ali vražari, ali čaruje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 11, 'ne nobenega zaklinjalca, ne nikogar, ki se posvetuje z duhom pokojnih ali z vedežnim duhom ali izprašuje mrtve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 12, 'Zakaj gnusoba je Gospodu, kdorkoli dela kaj takega, in zaradi takih gnusob izganja Gospod, tvoj Bog, one pred vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 13, 'Ti pa bodi popoln pri Gospodu, Bogu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 14, 'Zakaj ti narodi, ki jih preženeš, poslušajo tolmače znamenj in vedeže; tebi pa ne dovoljuje Gospod, tvoj Bog, tako delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 15, 'Proroka izmed tebe, iz bratov tvojih, kakor sem jaz, ti obudi Gospod, tvoj Bog: njega poslušajte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 16, 'prav kakor si prosil Gospoda, svojega Boga, na Horebu, v dan zbora, govoreč: Daj, da ne slišim več glasu Gospoda, svojega Boga, in ne vidim tega ognja prevelikega, da ne umrjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 17, 'In Gospod mi je rekel: To so prav govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 18, 'Hočem jim obuditi proroka izmed njih bratov, kakor si ti, in denem svoje besede v njegova usta, in govoril jim bo vse, karkoli mu zapovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 19, 'In kdorkoli ne bo poslušal mojih besed, ki jih bo govoril v mojem imenu, jaz ga bom za to kaznoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 20, 'Ali prorok, ki se prevzame govoriti v mojem imenu besedo, ki mu je nisem ukazal govoriti, ali ki bo govoril v imenu drugih bogov, ta prorok naj umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 21, 'In ako boš vprašal v srcu svojem: Kako naj spoznamo besedo, ki je ni govoril Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 18, 22, 'vedi: Ko prorok govori v imenu Gospodovem, pa se ne izpolni njegova beseda in ne pride tisto, to je beseda, ki je ni govoril Gospod. V prevzetnosti svoji jo je govoril prorok, ne boj se ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 1, 'Ko Gospod, tvoj Bog, iztrebi narode, katerih deželo ti daje Gospod, tvoj Bog, in se je polastiš in boš prebival v njih mestih in hišah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 2, 'si oddeliš tri mesta sredi dežele, ki ti jo daje Gospod, tvoj Bog, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 3, 'Napravi si dobro pot do njih in razdeli ozemlje svoje dežele, ki ti jo da v dediščino Gospod, tvoj Bog, v tri dele, da zbeži tja vsak ubijalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 4, 'In to je pravilo zastran ubijalca, ki naj tja zbeži, da ostane živ: kdor udari svojega bližnjega nehotoma in ga ni v prejšnjem času sovražil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 5, 'kakor če gre kdo z bližnjim svojim v gozd drva sekat in zamahne s sekiro, da bi drevo posekal, in železo odleti s toporišča in zadene njegovega bližnjega, da umrje: tisti naj zbeži v eno teh mest, in ostane živ;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 6, 'da ne bi se maščevalec krvi spustil za njim, ko mu je še srce razljučeno, in ga dohitel, ker bi bila pot dolga, in ga smrtno udaril, ko vendar ni bil vreden smrti, ker ga doslej ni še sovražil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 7, 'Zatorej ti zapovedujem tole: Oddeli si tri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 8, 'In ko razširi Gospod, tvoj Bog, tvoje meje, kakor je prisegel tvojim očetom, in ti da vso deželo, ki jo je obljubil dati tvojim očetom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 9, 'ako boš pazil na vso to zapoved, ki ti jo danes zapovedujem, izpolnjujoč jo s tem, da ljubiš Gospoda, svojega Boga, in hodiš vse dni po njegovih potih: tedaj si prideni še tri mesta k onim trem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 10, 'da se ne prelije nedolžna kri v tvoji deželi, ki ti jo da v dediščino Gospod, tvoj Bog, in tako ne pride krivda krvi nad tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 11, 'A če je kdo sovražen bližnjemu svojemu in ga zalezuje, in vstane zoper njega in ga smrtno udari, da umrje, potem pa zbeži v eno teh mest:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 12, 'tedaj pošljejo starejšine njegovega mesta, da se pripelje odondod, in ga izroče maščevalcu krvi, da naj umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 13, 'Naj mu ne prizanese tvoje oko, temuč odpravi kri nedolžnih iz Izraela, da se ti bo dobro godilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 14, 'Ne premakni bližnjemu svojemu mejnika, ki so ga ob meji postavili predniki, ob tvoji dediščini, ki jo podeduješ v deželi, ki ti jo daje Gospod, tvoj Bog, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 15, 'Ne vstane naj edina priča zoper koga zaradi katerekoli krivice ali kateregakoli greha, s kakršnimkoli grehom se ta zagreši; na dveh ali treh prič izpovedbo naj se opira vsaka stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 16, 'Ako vstane zoper koga krivična priča, da ga okrivi prestopa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 17, 'naj stopita oba moža, med katerima je ta prepir, pred Gospoda, pred duhovnike in sodnike, ki bodo v tem času;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 18, 'in sodniki naj preiščejo vse natanko, in glej, ta pričevalec je kriva priča, laž je izpovedal zoper bližnjega svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 19, 'tedaj mu storite, kakor je hotel storiti bratu svojemu: tako odpraviš hudo izmed sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 20, 'In ko bodo slišali drugi, se bodo bali in poslej ne bodo počenjali takega hudega sredi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 19, 21, 'In tvoje oko ne prizanašaj: življenje za življenje, oko za oko, zob za zob, roka za roko, noga za nogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 1, 'Ko pojdeš v boj zoper svoje sovražnike in boš videl konje in bojne vozove in ljudstvo, številnejše od tebe, ne boj se jih; zakaj Gospod, tvoj Bog, je s teboj, ki te je gori pripeljal iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 2, 'In preden začnete bitko, naj pristopi duhovnik in ogovori ljudstvo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 3, 'ter mu reče: Čuj, o Izrael, danes se spopadete v boju s svojimi sovražniki: naj vam ne kopni srce, ne bojte se in ne trepetajte, tudi se jih ne plašite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 4, 'Zakaj Gospod, vaš Bog, vas spremlja, da se za vas bojuje zoper vaše sovražnike in vas reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 5, 'Oblastniki pa naj ogovore ljudstvo takole: Kdo je tu, ki je sezidal novo hišo in je še ni posvetil? pojdi in vrni se v hišo svojo, da ne bi umrl v boju in bi jo kdo drugi posvetil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 6, 'Kdo je, ki je zasadil vinograd in ga še ni začel uživati? vrni se in ostani doma, da ne bi umrl v boju in bi ga kdo drugi užival.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 7, 'In kdo je, ki si je zaročil mladenko, a je še ni domov peljal? vrni se in ostani doma, da ne bi umrl v boju in bi jo kdo drugi vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 8, 'In dalje naj govore oblastniki ljudstvu, rekoč: Kdo je boječ in plahega srca? pojdi in ostani v hiši svoji, da ne oplaši srca svojim bratom, kakor je njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 9, 'In ko nehajo oblastniki govoriti ljudstvu, postavijo vojvode trum ljudstvu na čelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 10, 'Ko se približaš mestu, da se ž njim bojuješ, ponudi mu najprej mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 11, 'Ako ti odgovori z mirom in ti odpre vrata, bodi ti vse ljudstvo, ki ga najdeš v njem, davku podvrženo in naj ti služi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 12, 'Ako pa noče miru skleniti, temuč začne boj s teboj, oblezi ga z vojsko;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 13, 'in ko ti ga v roko da Gospod, tvoj Bog, pobij vse moške v njem z ostrino meča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 14, 'toda žene, otroke, živino in vse, kar je v mestu: ves plen vzemi kot rop zase in uživaj sovražnikov svojih plen, ki ti ga je dal Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 15, 'Tako stori z vsemi mesti, ki so bolj daleč od tebe in niso iz mest tehle narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 16, 'Ali v mestih teh narodov, ki ti jih Gospod, tvoj Bog, daje v dediščino, ne pusti živega ničesar, kar diha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 17, 'ampak s prokletjem jih uniči: Hetejce, Amorejce, Kanaance, Ferizejce, Hevejce in Jebusejce, kakor ti je zapovedal Gospod, tvoj Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 18, 'da vas ne bodo učili delati vseh tistih gnusob, ki so jih delali svojim bogovom, da se ne pregrešite zoper Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 19, 'Ko boš dalj časa oblegoval mesto, bojevaje se ž njim, da ga dobiš, ne pokvari mu dreves s sekiro; ker lahko ješ njih sad, zato jih ne posekaj. Je li mar les na polju človek, da bi ga tudi oblegal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 20, 20, 'Samo drevje, ki ne rodi sadja za užitek, smeš pokvariti in iztrebiti ter oblegovalne naprave iz njega zgraditi zoper mesto, ki se s teboj bojuje, dokler ne pade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 1, 'Ko najdejo v deželi, ki ti jo daje Gospod, tvoj Bog, da jo posedeš, ubitega človeka, ki leži na polju, pa se ne ve, kdo ga je ubil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 2, 'naj pridejo starejšine in sodniki tvoji in merijo od ubitega do vsakega mesta, ki je v okolici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 3, 'Starejšine mesta pa, ki je najbliže ubitemu, naj vzamejo junico iz črede, s katero se še ni delalo in ki še ni vlekla v jarmu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 4, 'in starejšine tistega mesta naj peljejo junico v dolino, kjer vedno teče voda, v kateri se ne orje in ne seje, in naj ji zlomijo šijnjak tam v dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 5, 'Nato naj pristopijo duhovniki, sinovi Levijevi, zakaj nje je izvolil Gospod, tvoj Bog, da mu strežejo ter blagoslavljajo v imenu Gospodovem, in po njih besedi naj se poravna vsaka pravda in vsaka poškodba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 6, 'In vsi starejšine tistega mesta, ki je najbliže truplu ubitega človeka, naj si umijejo roke nad junico, ki so ji bili šijnjak zlomili v dolini,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 7, 'in izpregovore ter reko: Naše roke niso prelile te krvi in naše oči niso videle tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 8, 'Odpusti, o Gospod, svojemu ljudstvu Izraelu, ki si ga odrešil, in ne prištej nedolžne krvi ljudstvu svojemu Izraelu! In krivda krvi jim bo odpuščena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 9, 'Tako odpraviš nedolžno kri izmed sebe, ko storiš, kar je prav v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 10, 'Ko pojdeš na vojsko zoper svoje sovražnike in Gospod, tvoj Bog, ti jih da v roke ter odpelješ izmed njih ujetnike');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 11, 'in vidiš med ujetniki lepe postave žensko ter se vanjo zaljubiš, da bi jo vzel za ženo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 12, 'vpelji jo v hišo svojo in naj si postriže lase in obreže nohte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 13, 'In naj sleče oblačilo ujetništva svojega in ostane v hiši tvoji ter joka cel mesec po svojem očetu in po svoji materi; in potem pojdi k njej in bodi njen mož, in ona bodi žena tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 14, 'Ako pa nimaš veselja ž njo, pusti jo, kamor hoče iti, ali za denar je nikakor ne smeš prodati, tudi ne kot s sužnico ž njo ravnati, zato ker si jo ponižal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 15, 'Ako ima kdo dve ženi, eno, ki jo ljubi, in eno, ki mu je zoprna, in obe mu rodita otroke, ljubljena in neljubljena, in ako je prvorojenec tiste neljubljene:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 16, 'ko pride dan, da bo delil svojim sinovom v dediščino, kar ima, ne sme storiti sinú ljubljene za prvenca mimo sina neljubljene, ki je prvenec;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 17, 'temuč pripoznaj sina neljubljene za prvorojenca s tem, da mu da dvojni del vsega, kar ima; zakaj ta je začetek njegove moči in njegova je pravica prvenstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 18, 'Ako ima kdo svojevoljnega in upornega sina, ki ne posluša glasu svojega očeta in svoje matere, in ga kaznujeta, pa ju noče poslušati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 19, 'naj ga primeta oče in mati ter ga pripeljeta k starejšinam svojega mesta, k vratom svojega kraja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 20, 'ter rečeta mestnim starejšinam: Ta najin sin je svojevoljen in uporen, najinega glasu noče poslušati, požrešnik je in pijanec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 21, 'Nato naj ga vsi možje njegovega mesta posujejo s kamenjem, da umrje. Tako odpravi hudo izmed sebe, in vsak Izraelec bo slišal in se bal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 22, 'In če kdo zakrivi greh, ki je smrti vreden, in bo umorjen in ga obesiš na les,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 21, 23, 'naj ne ostane njegovo truplo čez noč na lesu, temuč ga moraš tisti dan pokopati, zakaj kletev Božja je obešenec; ti pa ne smeš onečiščati dežele svoje, ki ti jo da v dediščino Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 1, 'Kadar vidiš vola ali ovco svojega brata, da blodi, ne hodi vnemarno mimo, ampak ju pelji nazaj bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 2, 'Ako pa ni tvoj brat blizu tebe ali ga ne poznaš, vzemi ju v hišo svojo, da bodeta pri tebi, dokler ju ne poišče tvoj brat, in potem mu ju izroči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 3, 'Enako stori z njegovim oslom, z njegovim oblačilom in z vsaktero izgubljeno rečjo, ki jo izgubi tvoj brat in jo ti najdeš: ne smeš iti vnemarno mimo nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 4, 'Kadar vidiš, da je tvojega brata osel ali vol padel na poti, ne idi mimo vnemarno, temuč pomozi mu ju vzdigniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 5, 'Ženska naj ne nosi moške oprave in moški naj ne obleče ženskega oblačila, zakaj gnusoba je Gospodu, tvojemu Bogu, kdorkoli dela kaj takega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 6, 'Ko na poti najdeš ptičje gnezdo, na drevesu ali na tleh, z mladiči ali z jajci, ko na njih sedi mati, ne smeš vzeti matere z mladiči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 7, 'temuč pusti, da zleti mati, in vzemi si le mladiče, da se ti bo dobro godilo in da podaljšaš svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 8, 'Ko zidaš novo hišo, napravi obzidek okoli strehe svoje, da ne spraviš krvi na hišo, ko bi kdo padel ž nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 9, 'Ne obsevaj vinograda svojega še z drugim semenom, da ne bo posvečena dvojna obilost: seme, ki si ga posejal, in obrodek vinograda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 10, 'Ne orji z volom in oslom skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 11, 'Ne oblači tkanine, stkane iz volnene in lanene preje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 12, 'Naredi si šopke na štirih voglih plašča, s katerim se odevaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 13, 'Če si kdo vzame ženo in gre k njej in ji potem postane sovražen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 14, 'jo dolži nespodobnih reči in jo pripravi v hud glas, govoreč: To ženo sem vzel in, ko sem se ji približal, nisem našel znamenja devištva pri njej:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 15, 'tedaj naj vzameta oče in mati mlade žene znamenje devištva svoje hčere in je prineseta k mestnim starejšinam, ki so pri vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 16, 'In ogovori naj oče mlade žene starejšine: Dal sem hčer svojo temu možu za ženo, zdaj jo pa sovraži,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 17, 'in glejte, očital ji je nesramne reči, govoreč: Nisem našel znamenja devištva pri tvoji hčeri, in vendar tu je znamenje devištva najine hčere. In razgrneta naj oblačilo pred mestnimi starejšinami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 18, 'In mestni starejšine naj vzamejo tistega moža in ga kaznujejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 19, 'in mu nalože sto srebrnikov globe in jih dado očetu mlade žene, zato ker je pripravil v hud glas devico v Izraelu. In ona mu ostani žena, ne sme je pustiti vse svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 20, 'Toda ako je resnica, da se ni našlo znamenje devištva pri mladi ženi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 21, 'naj jo odpeljejo k durim njenega očeta hiše, in možje tega mesta naj jo posujejo s kamenjem, da umrje, ker je storila nesramnost v Izraelu, nečistujoč v hiši očeta svojega. In tako odpraviš hudo izmed sebe. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 22, 'Ako se zasači kdo, da leži z omoženo ženo, naj umrjeta obadva, mož, ki je ležal z ženo, in žena. Tako odpraviš hudo iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 23, 'Če je mladenka, devica, zaročena možu in jo kdo zalotí v mestu in leži pri njej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 24, 'tedaj ju izpeljite oba k vratom tistega mesta in ju posujte s kamenjem, da umrjeta, dekle, ker ni kričalo v mestu, in moža, ker je ponižal svojega bližnjega ženo. Tako odpravi hudo izmed sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 25, 'Ako pa mož zaloti zaročeno mladenko na polju in jo posili in leži pri njej, naj umrje samo mož, ki je ž njo ležal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 26, 'A dekletu ne stóri ničesar: ni zakrivila greha smrti vrednega; kajti enako je, kakor če se kdo vzdigne zoper bližnjega svojega ter ga ubije:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 27, 'na polju jo je namreč zalotil, zaročena mladenka je vpila, a ni bilo nikogar, ki bi ji bil pomagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 28, 'Ako zaloti kdo mladenko, devico, ki ni zaročena, ter jo zgrabi in leži pri njej in bosta zasačena:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 29, 'tedaj naj da mož, ki je ležal pri njej, očetu mladenke petdeset srebrnikov, in ona mu bodi žena, ker jo je ponižal; ne sme je pustiti vse svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 22, 30, 'Nihče naj ne vzame svojega očeta žene in ne odgrne svojega očeta odeje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 1, 'V zbor Gospodov naj ne pride nihče, ki ima stolčena moda ali odrezano sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 2, 'Nezakonski otrok naj ne pride v zbor Gospodov, tudi iz desetega pokolenja ne pridi nihče od njega v Gospodov zbor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 3, 'Noben Amonec, ne Moabec naj ne pride v zbor Gospodov, tudi njih deseto pokolenje naj ne pride v zbor Gospodov vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 4, 'zato ker vam niso prišli naproti s kruhom in z vodo na poti, ko ste šli iz Egipta, in ker so najeli zoper tebe Balaama, sina Beorjevega iz Petorja v Mezopotamiji, da bi te proklel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 5, 'Toda Gospod, tvoj Bog, ni hotel uslišati Balaama, in Gospod, tvoj Bog, ti je preobrnil tisto prokletstvo v blagoslov, ker te je ljubil Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 6, 'Ne prizadevaj si za mir ž njimi, ne za njih blaginjo vse svoje žive dni, vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 7, 'Ne studi Edomca, ker je tvoj brat; ne mrzi Egipčana, ker si bil tujec v njegovi deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 8, 'Otroci tretjega pokolenja, ki se jim bodo rodili, smejo stopiti v zbor Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 9, 'Ko pojdeš v tabor na boj zoper svoje sovražnike, varuj se vsaktere hude reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 10, 'Če je kdo med vami, ki se po noči v sanjah oskruni, naj gre ven iz taborišča in ne pride v tabor;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 11, 'ko pa se zvečeri, naj se izkoplje v vodi in po solnčnem zahodu se sme vrniti v tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 12, 'Imej tudi kraj zunaj taborišča, kamor boš hodil k svoji potrebi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 13, 'in lopatico imej med svojim orodjem, in kadar zunaj počeneš, koplji ž njo okrog, in obrni se in zagrebi, kar je šlo iz tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 14, 'Zakaj Gospod, tvoj Bog, hodi po tvojem taborišču, da bi te reševal in sovražnike tvoje ti izročal: zato naj bode tvoje taborišče sveto, da ne vidi nič mrzkega na tebi in se ne odvrne od tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 15, 'Ne daj njegovemu gospodarju nazaj hlapca, ki je k tebi pribežal od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 16, 'Pri tebi naj ostane, sredi tvojega ljudstva, na kraju, ki si ga izvoli v enem tvojih mest, kjer mu je všeč; ne delaj mu sile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 17, 'Nobene nečistosti prodane ženske naj ne bode med Izraelovimi hčerami in nobenega nečistosti posvečenega moškega med Izraelovimi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 18, 'Ne prinašaj kurbjega plačila, ne pasjega denarja v hišo Gospoda, svojega Boga, za kakršnokoli obljubo; zakaj oboje je gnusoba Gospodu, Bogu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 19, 'Ne jemlji obresti od brata svojega ne za denar, ne za hrano, ne za karkoli, kar se posoja na obresti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 20, 'Tujcu pač moreš posoditi na obresti, a svojemu bratu ne posojaj na obresti, da te bo blagoslovil Gospod, tvoj Bog, v vsem, česarkoli se loti tvoja roka, v deželi, v katero greš, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 21, 'Ko storiš obljubo Gospodu, svojemu Bogu, je ne odlašaj izpolniti, zakaj Gospod, tvoj Bog, te bo za to terjal, in bode ti v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 22, 'Ako pa ničesar ne obljubiš, ne boš imel greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 23, 'Ali kar je prišlo iz tvojih ust, ohrani in izpolni, prav kakor si prostovoljno obljubil Gospodu, Bogu svojemu, kar si govoril s svojimi usti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 24, 'Ko prideš v vinograd bližnjega svojega, smeš zobati grozdje dositega, kolikor se ti poljubi, ali v posodo svojo ga ne devaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 23, 25, 'Ko prideš k zorečemu žitu svojega bližnjega, smeš klasje trgati z roko, ali s srpom ne zamahni v žito svojega bližnjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 1, 'Ako vzame kdo ženo in se ž njo poroči in potem ona ne najde milosti v njegovih očeh, zato ker je odkril kaj mrzkega pri njej, naj ji napiše ločilni list ter ji ga da v roke in jo pošlje stran iz svoje hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 2, 'Ona pa odide iz njegove hiše in lahko gre in postane drugemu možu žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 3, 'A če jo drugi mož mrzi in ji napiše ločilni list ter ji ga da v roko in jo odslovi iz svoje hiše; ali pa če drugi mož umre, ki si jo je vzel za ženo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 4, 'prvi njen mož, ki jo je odslovil, si je ne sme zopet vzeti za ženo, potem ko je onečiščena, zakaj gnusoba je to pred Gospodom. Ti pa ne spravljaj v greh dežele, ki ti jo da Gospod, tvoj Bog, v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 5, 'Kdor se je pred kratkim oženil, naj ne hodi na vojsko, tudi naj se mu ne naloži opravilo: svoboden bodi doma eno leto in naj veseli ženo svojo, ki jo je vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 6, 'Ne jemlji v zastavo ne ročnega mlina, ne zgornjega mlinskega kamena, zakaj s tem bi vzel v zastavo življenje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 7, 'Ako se zve za moža, ki ukrade enega izmed svojih bratov, Izraelovih sinov, in ž njim ravna kot s sužnikom ali ga proda, tedaj naj umrje tisti tat. Tako odpravi hudo izmed sebe. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 8, 'Varuj se pri nadlogi gob, da marljivo paziš in delaš po vsem, kar vas uče duhovniki leviti, kakor sem jim zapovedal; pazite, da tako delate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 9, 'Spominjaj se, kar je storil Gospod, tvoj Bog, Mirjami, na poti, ko ste šli iz Egiptovske zemlje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 10, 'Ko daš svojemu bližnjemu kaj na up, ne stopi v njegovo hišo, da vzameš od njega zastavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 11, 'zunaj postoj, in mož, ki mu upaš, naj ti prinese ven zastavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 12, 'In ako je ubožec, ne pojdi spat z njegovo zastavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 13, 'marveč povrni mu zastavo, ko solnce za goro gre, da bi spal v svojem oblačilu in te blagoslovil; in to ti bode pravičnost pred Gospodom, tvojim Bogom. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 14, 'Ne tlači ubogega in potrebnega najemnika, bodi izmed tvojih bratov ali izmed tujcev, ki bivajo v deželi tvoji po tvojih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 15, 'Tisti dan, ko dela, mu daj plačilo, še preden zajde solnce, zakaj potreben je in duša mu hrepeni po njem; da ne bi zoper tebe vpil h Gospodu, in bilo bi ti v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 16, 'Očetje naj se ne obsodijo v smrt za otroke, tudi ne otroci za očete: sleherni naj umrje le za svoj greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 17, 'Ne ovrzi pravice tujcu in siroti, tudi ne jemlji vdovi oblačila v zastavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 18, 'In spominjaj se, da si bil suženj v Egiptu, in Gospod, tvoj Bog, te je odkupil odondod: zato ti zapovedujem, da tako ravnaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 19, 'Ko boš žel žito na njivi svoji, pa pozabiš kak snop na njej, ne vrni se, da ga vzameš: ostane naj tujcu, siroti in vdovi, da bi te blagoslovil Gospod, tvoj Bog, pri vsem delu tvojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 20, 'Ko boš tresel sad z oljk svojih, ne obiraj še veje za vejo: tujcu, siroti in vdovi ostani to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 21, 'Ko si trgal v vinogradu svojem, ne pobiraj jagod za seboj: tujcu, siroti in vdovi ostani to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 24, 22, 'In spominjaj se, da si bil suženj v Egiptovski deželi; zato ti zapovedujem, da tako ravnaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 1, 'Ako nastane prepir med možmi in pridejo na sodišče, da jih sodijo: tedaj naj opravičijo pravičnega, krivičnega pa obsodijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 2, 'In če je krivični zaslužil palico, ukaži sodnik, naj ga polože na tla ter ga tepo vpričo njega; udarcev število bodi primerno njegovi krivici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 3, 'Štirideset mu jih sme priložiti, več pa ne, da ne bi, ako bi nadaljeval in ga tepel še z mnogimi udarci, bil preveč ogrdobljen brat tvoj pred tvojimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 4, 'Ne zaveži gobca volu, ko vrši žito.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 5, 'Ko stanujeta brata skupaj in eden izmed njiju umre, pa nima sina, naj se žena umrlega ne omoži stran s tujim, temuč njen dever naj gre k njej in jo vzame za ženo in pri njej izvrši moževega brata dolžnost:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 6, 'prvenec namreč, ki ga bo rodila, nastopi v ime svojega brata, ki je umrl, da se ne iztrebi njegovo ime iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 7, 'Ako pa možu ni všeč vzeti svoje jetrve, naj gre ona k mestnim vratom pred starejšine in reče: Moža mojega brat se brani, obuditi ime bratu svojemu v Izraelu, noče izvršiti pri meni moževega brata dolžnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 8, 'Nato naj ga pokličejo starejšine njegovega mesta ter mu prigovarjajo. Ako ostane pri tem in poreče: Ni mi všeč vzeti je,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 9, 'naj pristopi njegovega brata žena k njemu pred očmi starejšin, mu sezuje čevelj z noge ter mu pljune v obraz, in naj izpregovori ter reče: Tako naj se stori vsakemu možu, ki noče obstanka ohraniti svojega brata rodbini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 10, 'In njegovo ime naj se imenuje v Izraelu: Sezutega hiša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 11, 'Ko se dva moža stepeta in priteče enega žena, da bi otela svojega moža pesti tistega, ki ga bije, pa iztegne roko in ga popade za njegov sram,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 12, 'tedaj ji odsekaj roko; naj ji ne prizanese tvoje oko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 13, 'Ne imej v mošnji svoji dvojnih uteži, malih in velikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 14, 'Ne imej v hiši svoji dvojne efe, večje in manjše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 15, 'Rabi popolne in pravične uteži, tudi popolno in pravično efo, da se podaljšajo tvoji dnevi na zemlji, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 16, 'Zakaj gnusoba Gospodu, tvojemu Bogu, so vsi, ki delajo kaj takega, vsi, ki ravnajo nepravično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 17, 'Spominjaj se, kaj ti je storil Amalek na poti, ko ste šli iz Egipta:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 18, 'kako te je napadel ob potu in pobil tvoj zadnji voj, vse slabotne, ki so zaostali, ko ste bili trudni in onemogli, in ni se bal Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 25, 19, 'Ko ti torej Gospod, tvoj Bog, da pokoj od vseh tvojih sovražnikov vseokrog, v deželi, ki ti jo da v dediščino Gospod, tvoj Bog, da si jo prilastiš, tedaj izbriši spomin Amaleka izpod neba. Ne pozabi tega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 1, 'Ko prideš v deželo, ki ti jo v dediščino daje Gospod, tvoj Bog, in ko si jo prilastiš in boš prebival v njej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 2, 'tedaj vzemi prvin vseh zemeljskih sadov, ki jih spraviš iz dežele, ki ti jo da Gospod, tvoj Bog, in jih deni v koš in pojdi na mesto, ki si ga izvoli Gospod, tvoj Bog, da ondi prebiva ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 3, 'In pridi k duhovniku, ki bode v tem času, in mu reci: Priznavam danes Gospodu, tvojemu Bogu, da sem prišel v deželo, za katero je prisegel Gospod našim očetom, da nam jo da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 4, 'In duhovnik naj ti vzame koš iz roke ter ga postavi pred oltar Gospoda, tvojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 5, 'In izpregovóri in reci pred Gospodom, Bogom svojim: Izgubljen Aramejec je bil oče moj in šel je doli v Egipt in ondi bival kot tujec z majhnim krdelcem, a postal je tam v narod velik, mogočen in mnogoštevilen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 6, 'Egipčani pa so grdo ravnali z nami, stiskali so nas ter nam nakladali težko službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 7, 'In klicali smo h Gospodu, Bogu svojih očetov, in Gospod je uslišal naš glas in videl našo revo, naš trud in našo stisko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 8, 'in izpeljal nas je Gospod iz Egipta z mogočno roko in iztegnjeno ramo, z veliko grozo, z znamenji in s čudeži,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 9, 'ter nas je privedel v ta kraj in nam dal to deželo, deželo, v kateri teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 10, 'In sedaj, glej, sem prinesel prvine zemeljskih sadov, ki si mi jih dal ti, o Gospod. In polóži jih pred Gospoda, svojega Boga, in moli pred Gospodom, Bogom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 11, 'In veséli se vseh dobrot, ki jih je Gospod, tvoj Bog, dodelil tebi in tvoji hiši, ti in levit in tujec, ki je pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 12, 'Ko spraviš docela vse desetine svojih prirastkov v tretjem letu, ki je leto desetinjenja, in daš levitu, tujcu, siroti in vdovi, da jedo znotraj tvojih vrat in se nasitijo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 13, 'tedaj reci pred Gospodom, Bogom svojim: Odnesel sem sveto darilo iz svoje hiše, tudi sem dal levitu, tujcu, siroti in vdovi po vsej zapovedi tvoji, ki si mi jo ukazal; nisem prestopil tvojih zapovedi, ne jih pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 14, 'V žalosti svoji nisem jedel od tega, tudi nisem ničesar tega odnesel, ko sem bil nečist, tudi nisem dal od tega za mrliča; poslušal sem glas Gospoda, svojega Boga, storil sem vse, kakor si mi zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 15, 'Poglej doli iz svetega prebivališča svojega, iz nebes, in blagoslovi ljudstvo svoje, Izraela, in deželo, ki si nam jo dal, kakor si bil prisegel očetom našim, deželo, kjer teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 16, 'Danes ti zapoveduje Gospod, tvoj Bog, da izpolnjuj vse te postave in sodbe: hrani jih torej in izpolnjuj iz vsega srca svojega in iz vse duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 17, 'Danes si se zarekel Gospodu, da bodi tvoj Bog in da hočeš hoditi po njegovih potih ter izpolnjevati postave in zapovedi in sodbe njegove in poslušati njegov glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 18, 'In Gospod se ti je danes zarekel, da mu bodi ljudstvo lastnine, kakor ti je bil obljubil, in da izpolnjuj vse njegove zapovedi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 26, 19, 'ter da te hoče storiti višjega mimo vseh narodov, ki jih je ustvaril, v hvali in v imenu in v časti, da bi ti bil sveto ljudstvo Gospodu, Bogu svojemu, kakor je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 1, 'In Mojzes in starejšine Izraelovi so zapovedali ljudstvu, rekoč: Ohranite vso to zapoved, ki vam jo danes zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 2, 'In v dan, ko pridete prek Jordana v deželo, ki ti jo daje Gospod, tvoj Bog, si postavi velike kamene in jih pobeli z apnom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 3, 'in nanje napiši vse besede tega zakona ob svojem prehodu; da dospeš v deželo, ki ti jo daje Gospod, tvoj Bog, deželo, ki v njej teče mleko in med, kakor ti je obljubil Gospod, tvojih očetov Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 4, 'Ko torej prestopite Jordan, postavite te kamene, o katerih vam jaz zapovedujem danes, na gori Ebalu, in jih prebelite z apnom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 5, 'In ondi zgradi oltar Gospodu, Bogu svojemu, oltar kamenov, nad katerimi ne boš vihtel železnega orodja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 6, 'Iz neobdelanih kamenov zgradi oltar Gospoda, svojega Boga, in na njem daruj žgalne daritve Gospodu, Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 7, 'Daruj tudi mirovne žrtve in jih zaužij ondi, in veseli se pred Gospodom, svojim Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 8, 'In napiši na tiste kamene vse besede tega zakona dobro in razločno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 9, 'In Mojzes in duhovniki leviti so govorili vsemu Izraelu, rekoč: Molči in čuj, o Izrael! Danes si postal ljudstvo Gospodu, Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 10, 'Poslušaj torej glas Gospoda, svojega Boga, in izpolnjuj zapovedi in postave njegove, ki ti jih jaz danes zapovedujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 11, 'In Mojzes zapove ljudstvu tisti dan, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 12, 'Tile naj stoje na gori Garizimu, da blagoslovijo ljudstvo, ko prestopite Jordan: Simeon, Levi, Juda, Isahar, Jožef in Benjamin;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 13, 'in tile naj stoje za proklinjanje na gori Ebalu: Ruben, Gad, Aser, Zebulon, Dan in Neftali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 14, 'In leviti naj izpregovore in reko vsem možem Izraelovim z velikim glasom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 15, 'Proklet bodi, kdor naredi rezano ali ulito podobo, kar je gnusoba Gospodu, tvorina umetnikove roke, in jo postavi na skrivnem! In vse ljudstvo naj odgovori in reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 16, 'Proklet bodi, kdor ne spoštuje očeta svojega in matere svoje! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 17, 'Proklet bodi, kdor prestavi svojega bližnjega mejnik! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 18, 'Proklet bodi, kdor zavede slepega s pota, da blodi! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 19, 'Proklet bodi, kdor zvija pravico tujcu, siroti in vdovi! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 20, 'Proklet bodi, kdor leži pri ženi svojega očeta, ker je odgrnil svojega očeta odejo! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 21, 'Proklet bodi, kdor se peča s kako živino! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 22, 'Proklet bodi, kdor leži pri svoji sestri, hčeri svojega očeta ali hčeri svoje matere! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 23, 'Proklet bodi, kdor leži pri svoji tašči! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 24, 'Proklet bodi, kdor skrivoma ubije svojega bližnjega! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 25, 'Proklet bodi, kdor sprejme darilo, da koga ubije in prelije nedolžno kri! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 27, 26, 'Proklet bodi, kdor ne potrdi besed te postave, izpolnjujoč jih! In vse ljudstvo naj reče: Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 1, 'In zgodi se, če boš marljivo poslušal glas Gospoda, svojega Boga, in pazil, da izpolnjuješ vse njegove zapovedi, ki ti jih jaz zapovedujem danes, da te Gospod, tvoj Bog, stori višjega mimo vseh narodov na zemlji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 2, 'in pridejo nadte vsi ti blagoslovi in te dohité, ako boš poslušal glas Gospoda, svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 3, 'Blagoslovljen boš v mestu, blagoslovljen na njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 4, 'Blagoslovljen bo sad tvojega telesa, obrodek tvoje zemlje, prirastek tvoje živine, mladiči tvoje govedi in jagnjiči tvoje drobnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 5, 'Blagoslovljen bo tvoj koš in kadunje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 6, 'Blagoslovljen boš, ko pojdeš noter, blagoslovljen tudi, ko pojdeš ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 7, 'Gospod stori, da bodo tvoji sovražniki, ki se vzpno zoper tebe, poraženi pred teboj; po enem potu pridejo zoper tebe, a po sedmih potih bodo bežali pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 8, 'Zapove Gospod blagoslovu, da ti pride v žitnico in k vsakemu delu tvojih rok, in blagoslovil te bo v deželi, ki ti jo daje Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 9, 'Potrdi te Gospod sebi za sveto ljudstvo, kakor ti je prisegel, ako boš hranil zapovedi Gospoda, svojega Boga, in hodil po njegovih potih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 10, 'In vsa ljudstva na zemlji bodo videla, da se imenuješ po imenu Gospodovem, in bala se te bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 11, 'In Gospod stori, da boš imel obilje dobrega: sadú svojega telesa, prirastka svoje živine in pridelka svoje zemlje, v deželi, za katero je prisegel Gospod tvojim očetom, da ti jo da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 12, 'Gospod ti odpre bogato zakladnico svojo, nebo, da daje dež tvoji deželi o pravem času in da blagoslovi vse delo tvoje roke; in posojal boš mnogim narodom, sam pa ničesar ne jemal naposodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 13, 'Postavi te Gospod, da bodeš glava, a ne rep; in bodeš samo zgoraj, ne pa spodaj, ako boš poslušal zapovedi Gospoda, svojega Boga, ki ti jih jaz zapovedujem danes, da jih hraniš in izpolnjuješ,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 14, 'in se ne ganeš od nobene besede, ki vam jih danes zapovedujem, ne na desno, ne na levo, da bi šel za drugimi bogovi in jim služil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 15, 'Ako pa ne boš poslušal glasu Gospoda, svojega Boga, da bi hranil in izpolnjeval vse zapovedi in postave njegove, ki ti jih danes zapovedujem: vse te prokletve pridejo nadte in te dohite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 16, 'Proklet boš v mestu, proklet na njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 17, 'Proklet bo tvoj koš in kadunje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 18, 'Proklet bo sad tvojega telesa, obrodek tvoje zemlje, prireja tvoje govedi in mladiči tvoje drobnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 19, 'Proklet boš, ko pojdeš noter, proklet tudi, ko pojdeš ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 20, 'Gospod pošlje nadte prokletstvo, zmešnjavo in grožnjo svojo v vsem, česar se lotiš z roko, da bi delal, dokler ne boš zatrt in dokler naglo ne pogineš, zaradi zla svojih dejanj, s katerimi si me zapustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 21, 'Gospod naredi, da se ti prilepi kuga, dokler te ne pokonča s površja zemlje, v katero greš, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 22, 'Gospod te udari z jetiko, mrzlico, vročico in s prisadom, s sušo, s snetjo in z rjo, in zasledovale te bodo nadloge, dokler ne pogineš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 23, 'Nebo, ki ti je nad glavo, bode bronasto, in zemlja, ki po njej hodiš, železna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 24, 'Gospod da tvoji deželi za dež prah in pepel, z neba bo padal nate, dokler ne boš pokončan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 25, 'Gospod dopusti, da te porazijo tvoji sovražniki pred seboj: po enem potu pojdeš proti njim, a po sedmih potih boš bežal pred njimi; in pestili te bodo po vseh kraljestvih na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 26, 'In truplo tvoje bode v živež vsem pticam pod nebom in zverem na zemlji, in nikogar ne bo, da bi jih preplašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 27, 'Gospod te udari z egiptovskim ugnidjem, s tvori, s skrumbami in z garjami, da ne boš mogel ozdraveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 28, 'Udari te Gospod z blaznostjo, slepoto in s plašljivostjo srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 29, 'Tipal boš opoldne, kakor slepec tiplje v temi, in na svojih potih ne boš imel nobene sreče; tlačili te bodo in oplenjevali vse dni, a ne bo nikogar, da bi te rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 30, 'Ženo si zaročiš, a drug bo spal pri njej; hišo si sezidaš, a ne boš prebival v njej; vinograd zasadiš, a njegovega sadu ne boš užival.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 31, 'Vol tvoj bo zaklan pred tvojimi očmi, a ne boš jedel njegovega mesa; osel tvoj ti bo s silo vzet izpred obličja, pa ga ne bo več nazaj; tvoje ovce bodo dane tvojim sovražnikom, in ne bo ti pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 32, 'Tvoji sinovi in hčere bodo izročeni drugemu narodu, da oči tvoje vidijo in ginejo od koprnenja po njih vse dni; a moči ne bo v tvojih rokah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 33, 'Sad tvoje zemlje in ves tvoj trud užije narod, ki ga ne poznaš; in bodo te samo tlačili in pestili vse tvoje žive dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 34, 'tako da izgubiš pamet spričo tega, kar bodo morale videti tvoje oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 35, 'Gospod te udari s hudimi grčami na kolenih in na mečih, da ti ne bode ozdravljenja od podplatov do temena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 36, 'Gospod popelje tebe in tvojega kralja, ki ga postaviš nad seboj, med narod, katerega nisi poznal ne ti, ne očetje tvoji, in ondi boš služil drugim bogovom, lesu in kamenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 37, 'In bodeš v grozo, v pregovore in zabavljice med vsemi ljudstvi, kamor te zažene Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 38, 'Veliko semena odneseš na polje, a malo spraviš, zakaj kobilice požro vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 39, 'Vinograde zasadiš in jih boš obdeloval, a ne boš ne vina pil, ne grozdja trgal, kajti črvi ga bodo snedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 40, 'Oljke boš imel po vseh krajih svojih, a ne boš se mazilil z oljem, zakaj tvoja oljka se sama otrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 41, 'Sinove in hčere boš rodil, in vendar ne bodo tvoji, ker pojdejo v ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 42, 'Vse tvoje drevje in sad tvoje zemlje posedejo kobilice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 43, 'Tujec, ki je pri tebi, bo stopal nadte više in više, ti pa boš padal vedno globokeje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 44, 'On ti bo posojal, ti pa mu nikdar ne posodiš; on bode glava, ti pa rep.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 45, 'In vsa ta prokletstva pridejo nad te in te bodo preganjala in te dohite, da pogineš, zato ker nisi poslušal glasu Gospoda, svojega Boga, da držiš zapovedi in postave njegove, ki ti jih je ukazal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 46, 'in ta prokletstva bodo nad teboj v znamenje in čudenje in nad tvojim zarodom vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 47, 'zato ker nisi služil Gospodu, svojemu Bogu, z veseljem in z radostnim srcem, ko si imel vsega obilost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 48, 'Zato ti bode služiti svojim sovražnikom, ki jih pošlje Gospod zoper tebe, ob lakoti in žeji, v nagoti in vsem pomanjkanju. Železen jarem ti položi na vrat, dokler te ne zatare.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 49, 'Gospod pripelje nadte narod od daleč, od kraja zemlje, ki leti kakor orel, narod, čigar jezika ne razumeš;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 50, 'narod trdega obličja, ki se ne ozira na osebo starčka in se mladine ne usmili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 51, 'Ta pojé prirastke tvoje živine in zemlje tvoje, dokler ne boš pokončan; in ne ostavi ti ničesar, ne žita, ne vina, ne olja, ne prireje tvoje govedi, ne mladičev tvoje drobnice, dokler te ne zatare.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 52, 'In pritiskal bo nate ob vseh vratih tvojih, dokler ne razruši po vsej deželi visokih in močnih tvojih zidov, na katere se zanašaš; pritiskal bo nate ob vseh vratih po vsej deželi tvoji, ki ti jo je dal Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 53, 'Tedaj boš jedel svojega telesa sad, meso sinov in hčer svojih, ki ti jih je dal Gospod, tvoj Bog, pri obleganju in v stiski, s katero te bo stiskal tvoj sovražnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 54, 'Mehak mož med vami in zelo razvajen bo nevoščljivo gledal svojega brata in ženo svojega naročja in ostale svoje otroke, ki mu še preostanejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 55, 'ne hoteč dati nikomur izmed njih mesa svojih otročičev, ki ga bo jedel, ker mu ničesar ne preostane pri obleganju in v stiski, s katero te bo stiskal sovražnik tvoj v vseh tvojih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 56, 'Mehka in razvajena ženska med vami, ki še od mehkosti in razvajenosti ni poskusila postaviti stopala svojega na tla, bo nevoščljivo gledala moža svojega naročja in svojega sina in hčer svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 57, 'zaradi trebeža, ki pride iz nje pri porodu, in zaradi otrok, katere porodi; kajti jedla jih bo skrivaj ob pomanjkanju vseh reči, pri obleganju in v stiski, s katero te bo stiskal sovražnik tvoj v tvojih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 58, 'Ako ne boš pazil, da izpolniš vse besede te postave, zapisane v tej knjigi, da bi se bal tega slavnega in grozovitega imena, Gospoda, svojega Boga:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 59, 'tedaj pripravi Gospod tebi in zarodu tvojemu čudovite nadloge, nadloge velike in dolgotrajne, hude in dolge bolezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 60, 'In pošlje nadte zopet vse kužne bolezni egiptovske, katerih si se bal, in te opne ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 61, 'Tudi vse bolezni in vse nadloge, ki niso zapisane v knjigi te postave, pošlje Gospod nadte, dokler ne boš iztrebljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 62, 'In malo število vas ostane, dasi vas je bila množica kakor zvezd na nebu, zato ker nisi poslušal glasu Gospoda, svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 63, 'In kakor je bilo Gospodu veselje, dobro vam storiti in vas množiti, tako mu bode veselje, vas pogubljati in pokončavati, in potrebljeni boste s površja dežele, v katero greste, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 64, 'In Gospod te razkropi med vsa ljudstva, od enega konca zemlje do drugega, in tam boš služil tujim bogovom, katerih nisi poznal ne ti, ne očetje tvoji, lesu in kamenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 65, 'In med temi narodi ti ne bode pokoja, in počivališča ne bo stopalu tvoje noge; in Gospod ti da trepetajoče srce, medle oči in onemoglo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 66, 'In tvoje življenje bo kakor na niti viseče tebi pred očmi, in v trepetu bodeš po noči in po dnevi, in ne boš si v svesti življenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 67, 'Zjutraj porečeš: O da bi bil že večer! in zvečer porečeš: O da bi bilo že jutro! zaradi strahu svojega srca, v katerem boš trepetal, in zaradi tega, kar boš moral gledati s svojimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 28, 68, 'In pripelje te Gospod nazaj v Egipt na ladjah, po potu, o katerem sem ti rekel: Ne boš ga več videl, in ondi se boste prodajali svojim sovražnikom za sužnje in za sužnjice, a kupcev ne bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 1, 'To so besede zaveze, ki jo je Gospod zapovedal Mojzesu skleniti s sinovi Izraelovimi v deželi Moabski, razen zaveze, ki jo je sklenil ž njimi na Horebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 2, 'In Mojzes je klical vsemu Izraelu in jim je govoril: Sami ste videli vse, kar je Gospod storil vam pred očmi v Egiptovski deželi Faraonu in vsem njegovim služabnikom in vsej deželi njegovi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 3, 'velike izkušnje, ki so jih videle vaše oči, tista znamenja in velike čudeže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 4, 'Toda Gospod vam ni dal srca, da bi umeli, in oči, da bi videli, in ušes, da bi slišali, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 5, 'In vodil sem vas štirideset let po puščavi; oblačilo se ni prestaralo na vas in obuvalo ne raztrgalo na nogah vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 6, 'Kruha niste jedli, tudi vina in močne pijače niste pili, da bi spoznali, da jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 7, 'In ko ste prišli v ta kraj, Sihon, kralj v Hesbonu, in Og, kralj v Basanu, sta prišla nam nasproti se vojskovat, in smo ju porazili');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 8, 'in zavzeli smo njiju deželo in jo dali v dediščino Rubenskim in Gadskim in polovici Manasejevega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 9, 'Hranite torej besede te postave in jih izpolnjujte, da boste imeli srečo v vsem, kar počenjate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 10, 'Danes stojite vsi pred Gospodom, Bogom svojim, vaši poglavarji, vaši rodovi, vaši starejšine in oblastniki, vsi Izraelovi možje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 11, 'vaši otročiči, vaše žene, tudi tujci vaši, ki bivajo v vašem taboru, od tistega, ki seka drva, do njega, ki nosi vodo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 12, 'da vstopite v zavezo Gospoda, svojega Boga, in v njegovo prisego, ki jo Gospod, tvoj Bog, sklepa danes s teboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 13, 'da te danes potrdi sebi za ljudstvo ter da ti bode za Boga, kakor ti je govoril in kakor je prisegel očetom tvojim, Abrahamu, Izaku in Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 14, 'A ne sklepam te zaveze in te prisege z vami samimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 15, 'marveč enako ž njim, ki tu danes stoji z nami pred Gospodom, našim Bogom, kakor ž njim, ki ga danes ni tukaj z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 16, 'Kajti veste, kako smo prebivali v deželi Egiptovski in kako smo prešli skozi narode, mimo katerih smo šli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 17, 'in videli ste njih ostude in njih malike, les in kamen, srebro in zlato, ki so bili med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 18, 'Pazite, da ne bo med vami moža ali žene, družine ali rodú, čigar srce se odvrača danes od Gospoda, našega Boga, da bi šel služit bogovom onih narodov; da ne bo med vami korenine, ki rodi strup in pelin;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 19, 'in čeprav sliši besede te kletve, vendar se blagoslavlja v svojem srcu in govori: Mir mi bode, čeprav živim po zakrknjenosti svojega srca; da naj pogine pijani z žejnim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 20, 'Ne bo mu hotel Gospod odpustiti, temuč takrat vzkipi Gospodova jeza in njegova gorečnost proti tistemu možu, in ležala bo na njem vsa kletev, ki je pisana v tej knjigi, in Gospod izbriše njegovo ime izpod neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 21, 'In Gospod ga odmeni v nesrečo izmed vseh Izraelovih rodov, soglasno z vsemi kletvami zaveze, zapisane v tej knjigi postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 22, 'In poreče prihodnji rod, otroci vaši, ki nastopijo za vami, in inostranec, ki pride iz daljne dežele, ko bodo videli nadloge te dežele in bolezni, s katerimi jo je bolno storil Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 23, 'ter da je vsa zemlja le žveplo in sol, pogorišče, ki se ne obseva in ki ne rodi, ki na njej ne raste bilje kakor v kraju razdejane Sodome in Gomore, Adame in Seboima, ki jih je Gospod pokončal v jezi in togoti svoji –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 24, 'da, vsi narodi poreko: Zakaj je Gospod tako storil tej deželi? kaj pomeni žar te jeze velike?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 25, 'Tedaj jim odgovore: Zato, ker so zapustili zavezo Gospoda, Boga svojih očetov, ki jo je sklenil ž njimi, ko jih je vodil iz dežele Egiptovske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 26, 'in so šli in služili drugim bogovom ter se jim poklanjali, bogovom, katerih niso poznali in katerih jim on ni bil pridelil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 27, 'Zato se je razvnela Gospodova jeza proti tej deželi, da je pripravil nadnjo vse prokletstvo, ki je pisano v tej knjigi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 28, 'in Gospod jih je izruval iz njih dežele v jezi in v srdu in v veliki togoti in jih pahnil v drugo deželo, kakor je danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 29, 29, 'Skrivne reči so Gospoda, našega Boga, a kar je razodetega, naše je in naših otrok vekomaj, da bi izpolnjevali vse besede tega zakona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 1, 'In zgodi se, ko pridejo nadte vse te besede, blagoslov in prokletstvo, ki sem ti ga predložil, in se jih spomniš v svojem srcu med vsemi narodi, kamor te je pognal Gospod, tvoj Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 2, 'in se izpreobrneš h Gospodu, svojemu Bogu, in boš poslušal njegov glas po vsem, kar ti danes zapovedujem, ti in tvoji otroci, iz vsega srca svojega in z vso dušo svojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 3, 'tedaj pripelje Gospod, tvoj Bog, nazaj ujetnike tvoje in se te usmili in te zopet zbere izmed vseh ljudstev, kamor te je razkropil Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 4, 'Ako bi bili razkropljenci tvoji ob koncu neba, tudi odondod te zbere Gospod, tvoj Bog, in odondod te prinese;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 5, 'in Gospod, tvoj Bog, te pripelje v deželo, ki so jo posedli očetje tvoji, in dobiš jo ti; in dobro ti stori in te pomnoži bolj nego očete tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 6, 'In Gospod, tvoj Bog, obreže srce tvoje in tvojega zaroda srce, da ljubiš Gospoda, svojega Boga, iz vsega srca svojega in z vso dušo svojo, da bi živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 7, 'In Gospod, tvoj Bog, dene vse te kletve na sovražnike tvoje in na tiste, ki te črté, ki so te preganjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 8, 'Ti pa se izpreobrneš in boš poslušal glas Gospodov in izpolnjeval vse zapovedi njegove, ki ti jih zapovedujem danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 9, 'In Gospod, tvoj Bog, stori, da boš imel obilje pri vsem delu svoje roke, v sadu svojega telesa, v prireji živine in v pridelku zemlje svoje, tebi v dobro; zakaj Gospod se te bo zopet veselil tebi v dobro, kakor se je bil veselil očetov tvojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 10, 'ko boš poslušal glas Gospoda, svojega Boga, izpolnjujoč njegove zapovedi in postave, ki so pisane v tej knjigi zakona, ko se izpreobrneš h Gospodu, svojemu Bogu, z vsem srcem svojim in z vso dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 11, 'Zakaj ta zapoved, ki ti jo jaz danes zapovedujem, ni previsoka zate, tudi ni daleč od tebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 12, 'ni v nebesih, da bi rekel: Kdo stopi za nas v nebesa in nam jo prinese, da bi jo slišali in po njej ravnali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 13, 'Tudi ni onostran morja, da bi rekel: Kdo pojde čez morje za nas ter nam jo prinese, da bi jo slišali in po njej ravnali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 14, 'Ampak prav blizu ti je ta beseda, v ustih tvojih in v srcu tvojem, da bi jo izpolnjeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 15, 'Poglej, predložil sem ti danes življenje in dobro, smrt in hudo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 16, 's tem, da ti danes zapovedujem, da ljubi Gospoda, svojega Boga, hodi po njegovih potih in drži zapovedi, postave in sodbe njegove, da bi živel in se množil ter da bi te blagoslovil Gospod, tvoj Bog, v deželi, v katero greš, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 17, 'Ako se pa odvrne tvoje srce in ne boš poslušal, ampak se daš premotiti ter se boš drugim bogovom poklanjal in jim služil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 18, 'oznanjam vam danes, da gotovo poginete; ne podaljšate svojih dni v deželi, v katero si namenjen iti čez Jordan, da jo posedeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 19, 'Za priči proti vam kličem danes nebo in zemljo. Predložil sem ti danes življenje in smrt, blagoslov in prokletstvo: izvoli si torej življenje, da bi živel ti in zarod tvoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 30, 20, 'da ljubiš Gospoda, svojega Boga, poslušaš njegov glas in se ga oklepaš; zakaj v tem je tvoje življenje in podaljšanje tvojih dni, da bi prebival v deželi, za katero je Gospod prisegel očetom tvojim, Abrahamu, Izaku in Jakobu, da jim jo da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 1, 'In šel je Mojzes in govoril te besede vsemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 2, 'In jim reče: Sto in dvajset let sem danes star, ne morem več hoditi ven in noter, tudi mi je rekel Gospod: Ne pojdeš čez ta Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 3, 'Gospod sam, tvoj Bog, pojde tja pred teboj, on iztrebi tiste narode pred teboj, da posedeš njih last; Jozue, ta pojde tja pred teboj, kakor je Gospod govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 4, 'In Gospod jim stori, kakor je storil Sihonu in Ogu, kraljema Amorejcev, in njih deželi, katere je pokončal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 5, 'In Gospod vam jih izroči, in storite jim po vsej zapovedi, ki sem vam jo zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 6, 'Bodite močni in srčni, ne bojte se in ne prestrašite se vpričo njih; zakaj Gospod, tvoj Bog, on je, ki gre s teboj; ne odtegne se ti in te ne zapusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 7, 'In Mojzes pokliče Jozueta in mu reče pred očmi vsega Izraela: Bodi močan in srčen; zakaj ti pojdeš s tem ljudstvom v deželo, ki je zanjo prisegel Gospod njih očetom, da jim jo da, in ti jim jo razdeliš v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 8, 'Gospod pa, on je, ki pojde pred teboj; on bode s teboj, ne odtegne se ti in te ne zapusti: ne boj se in ne plaši se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 9, 'In Mojzes je napisal ta zakon in ga je izročil duhovnikom, sinom Levijevim, ki so nosili skrinjo Gospodove zaveze, in vsem starejšinam Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 10, 'In Mojzes jim zapove, rekoč: Ob koncu vsakega sedmega leta, v določeni čas leta odpuščanja, pri prazniku šatorov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 11, 'ko pride ves Izrael prikazovat se pred Gospodom, tvojim Bogom, na mestu, ki si ga izvoli, beri ta zakon vpričo vsega Izraela, da vsi slišijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 12, 'Zberi ljudstvo, može in žene in otročiče in tujce, ki so v tvojih mestih, da bi čuli in da bi se učili bati se Gospoda, Boga vašega, in paziti, da izpolnjujejo vse besede tega zakona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 13, 'da bi slišali tudi njih otroci, ki še ne umejo tega, in se učili bati se Gospoda, vašega Boga, vse dni, dokler boste živeli v deželi, v katero greste čez Jordan, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 14, 'Tedaj reče Gospod Mojzesu: Glej, bližajo se ti dnevi, da umrješ. Pokliči Jozueta in postavita se v shodnem šatoru, da mu dam zapoved. Gresta torej Mojzes in Jozue in se postavita v shodnem šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 15, 'In Gospod se prikaže v šatoru v oblakovem stebru, in oblakov steber je stal ob vratih v šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 16, 'In Gospod reče Mojzesu: Glej, ko boš ležal z očeti svojimi, vstane to ljudstvo in pojde nečistujoč za tujimi bogovi tiste dežele, v katero gredo prebivat, in me zapuste in prelomijo zavezo mojo, ki sem jo sklenil ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 17, 'In jeza moja se vname zoper nje v tistem času, in zapustim jih in skrijem obličje svoje pred njimi, da bodo pokončani. In pridejo nadnje mnoge nesreče in bridkosti, tako da poreko v tistem času: Ni li prišlo tolikanj hudega nad nas, ker ni našega Boga med nami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 18, 'Jaz pa gotovo skrijem obličje svoje v tistem času zaradi vsega hudega, kar so storili s tem, da so se obračali k tujim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 19, 'Sedaj torej si napišite to pesem, in nauči jo sinove Izraelove in jo deni v njih usta, da mi bodi ta pesem priča zoper Izraelove sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 20, 'Kajti ko jih pripeljem v deželo, ki sem jo s prisego obljubil njih očetom, kjer teče mleko in med, in oni bodo jedli in se nasitijo in odebelé: tedaj se obrnejo k drugim bogovom in jim bodo služili, mene pa zaničevali in prelomili zavezo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 21, 'Ko jih torej zadenejo mnoge nesreče in bridkosti, naj govori ta pesem zoper nje kot priča; kajti ne odpravi je pozabljenje iz ust njih zaroda. Vem namreč njih misli, s katerimi se pečajo že zdaj, preden sem jih pripeljal v deželo, ki sem jim jo prisegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 22, 'Napisal je torej Mojzes to pesem tisti dan in jo učil lzraelove sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 23, 'In zapove Jozuetu, sinu Nunovemu, in reče: Bodi močan in srčen, zakaj ti pripelješ sinove Izraelove v deželo, za katero sem jim prisegel, in jaz bodem s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 24, 'Ko pa je Mojzes zapisal besede te postave v knjigo in je končal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 25, 'zapove levitom, ki so nosili skrinjo Gospodove zaveze, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 26, 'Vzemite to knjigo postave in jo položite ob strani skrinje zaveze Gospoda, svojega Boga, in tam naj ostane kot priča zoper tebe, Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 27, 'Zakaj jaz poznam upornost in trdovratnost tvojo. Glejte, do danes, ko še z vami živim, ste bili uporni Gospodu, koliko bolj bodete po moji smrti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 28, 'Zberite k meni vse starejšine svojih rodov in svoje oblastnike, da govorim na njih ušeša te besede in pozovem nebo in zemljo za priči zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 29, 'Vem namreč, da boste po moji smrti docela popačeno ravnali in odstopili s poti, katero sem vam zapovedal. Zato vas zadene nesreča v poslednjih dneh, ker boste počenjali, kar je hudo v Gospodovih očeh, da ga dražite v jezo z delom svojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 31, 30, 'In govoril je Mojzes besede te pesmi na ušesa vsega zbora Izraelovega prav do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 1, 'Poslušajte, nebesa, ker hočem govoriti, in zemlja naj čuje moj ih ust besede!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 2, 'Kaplja naj kot dež nauk moj, pada liki rosa govor moj, kakor pršica na mlado travo, kakor moča na zelenjavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 3, 'kajti oznanjati hočem ime Gospodovo. Priznajte velikost našemu Bogu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 4, 'On je Skala, njegovo delo je popolno, ker vse poti njegove so pravica; mogočen Bog zvestobe je, krivičnosti ni v njem, pravičen in resničen je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 5, 'Popačeno so ravnali ž njim, ne kot njegovi otroci, madež je na njih: izprijen rod so in zvit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 6, 'Ali tako povračaš Gospodu, o neumno in nespametno ljudstvo? Ni li on oče tvoj, ki si te je pridobil? On te je naredil in te utrdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 7, 'Spomni se starodavnih dni, pomisli na leta minulih rodov! Vprašaj očeta svojega, on ti oznani, starce svoje, in ti povedo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 8, 'Ko je Najvišji delil narodom dediščino, ko je razdruževal človeške otroke, je določil meje ljudstvom po številu Izraelovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 9, 'Zakaj Gospodov delež je ljudstvo njegovo, Jakob je njemu odmerjena dediščina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 10, 'Našel ga je v deželi puščave, v pustinji, v tuljenju divjega kraja; obdal ga je, pazil je nanj, varoval ga je kakor očesa svojega punčico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 11, 'Kakor orel izpodbuja k letanju gnezdnike svoje in nad svojimi mladiči leta, razprostira peruti svoje, jih nanje jemlje in jih nosi na krilih svojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 12, 'tako ga je Gospod sam vodil in ni bilo ž njim tujega boga nobenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 13, 'Dal mu je, da jezdi čez višine dežele, in jedel je sadove polja, in dal mu je srkati med iz skale in olje iz kremenja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 14, 'maslo od goved in mleko od ovac, s tolstino jagnjet pitanih in ovnov, basanskih sinov, in kozličev z najboljšim jedrom pšenice; tudi si pil grozdovo kri, vino močno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 15, 'In Ješurun je odebelel in je brcal; odebelil si se in izpital in močan si postal – tedaj je zapustil Boga, ki ga je ustvaril, in za malo je štel Skalo rešenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 16, 'Razvnemali so ga s tujimi bogovi, z gnusobami so ga dražili v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 17, 'Darovali so hudim duhovom, ki niso Bog, bogovom, ki jih niso poznali, novim bogovom, ki so pred kratkim nastopili, ki se jih niso bali vaši očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 18, 'Vnemar si pustil Skalo, ki te je plodila, in Boga mogočnega, ki te je rodil, si pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 19, 'In Gospod je videl, in jih je zavrgel, vznevoljen nad sinovi in hčerami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 20, 'Rekel je: Skriti jim hočem obličje svoje, gledal bom, kaj bode njih konec; ker so silno popačen rod, otroci, ki ni v njih nič vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 21, 'Razvneli so me s tistim, kar ni Bog mogočni, dražili so me v jezo z ničemurnostmi svojimi: tudi jaz jih razvnamem s tistimi, ki niso ljudstvo, razdražim jih z nespametnim poganskim narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 22, 'Kajti ogenj se je vnel po mojem srdu in bo gorel do najspodnjega pekla, in požre zemljo z obrodkom njenim in vžge podstave gorá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 23, 'Nakopičim nadnje nesreče; pšice svoje uporabim proti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 24, 'Obnemorejo od lakote, požre jih vročica in strupena kuga; pošljem mednje zobe zverin in strup tistih, ki se plazijo po prahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 25, 'Zunaj jih naj mori meč in v hišah strah, mladeniča in devico, dojenca in starca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 26, 'Rekel bi: Razpihnem jih, izbrišem njih spomin med ljudmi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 27, 'ako bi se ne bal sovražnikove žalitve, da ne bi njih zatiralci napak umeli, da ne bi govorili: Naša roka je vzvišena in Gospod ni vsega tega storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 28, 'Zakaj narod so, ki si ne zna svetovati, in razumnosti ni v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 29, 'O da bi bili modri, bi bili razumeli to, pomislili bi bili zadnji konec svoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 30, 'Kako bi mogel eden poditi jih tisoč in dva pognati v beg deset tisoč? Ne li zato, ker jih je prodala njih Skala in jih sovražnikom izročil Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 31, 'Ni namreč njih skala kakor naša Skala; sovražniki naši sami naj to presodijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 32, 'Zakaj njih vinska trta je od trte sodomske in s poljan Gomorskih: njih grozdje je strupeno grozdje, trpke so njih jagode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 33, 'Njih vino je kakor zmajev sline in grozoviti strup gadov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 34, 'Ni li to shranjeno pri meni, zapečateno med mojimi zakladi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 35, 'Moje je maščevanje, jaz povrnem ob času, ko jim opolzne noga: kajti blizu je dan njih pogube, in kar jim je določeno, pride hitro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 36, 'Zakaj Gospod se potegne za pravdo svojega ljudstva, in hlapcev svojih se usmili, ko uvidi, da je pošla njih moč in da nikogar ni več, ne uklenjenega, ne prostega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 37, 'In poreče: Kje so njih bogovi, skala, h kateri so pribegali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 38, 'ki so jedli njih žrtev tolstino in pili njih pitnih daritev vino? Vstanejo naj in vam pomorejo, bodo naj vam pokrovitelji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 39, 'Poglejte zdaj, da jaz, jaz sem vedno isti ter da ni boga zraven mene: jaz umorim in oživim, jaz udarim in ozdravim, in ni ga, ki bi otel iz moje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 40, 'Kajti roko svojo dvigam proti nebu in pravim: Vekomaj živim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 41, 'Kadar nabrusim bliskavi meč svoj in roka moja seže po sodbi, se bom maščeval nad nasprotniki svojimi in povrnem sovražilcem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 42, 'Upijanim pšice svoje s krvjo in meč moj bo žrl meso – s krvjo ubitih in ujetih, z glave vojvod sovražnikovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 43, 'Veselite se, poganski narodi, z ljudstvom njegovim! zakaj on bo maščeval kri svojih hlapcev in osveto povrne svojim nasprotnikom, in izvrši poravnavo za deželo svojo, za ljudstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 44, 'In prišel je Mojzes ter govoril vse besede te pesmi na ušesa ljudstvu, on in Jozue, sin Nunov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 45, 'In ko je do konca izgovoril vse te besede vsemu Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 46, 'jim reče: Vtisnite si v srce vse besede, ki vam jih danes izpričujem; zato da zapoveste otrokom svojim, da hranijo in izpolnjujejo vse besede tega zakona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 47, 'Zakaj to ni prazna beseda za vas, marveč to je vaše življenje, in po tej besedi boste podaljšali svoje dni v zemlji, v katero greste čez Jordan, da jo posedete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 48, 'In Gospod je govoril Mojzesu tisti dan, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 49, 'Pojdi na to gorovje Abarim, na goro Nebo, ki je v deželi Moabski nasproti Jerihu, in poglej deželo Kanaansko, ki jo dam v lastnino sinovom Izraelovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 50, 'in umri na gori, na katero pojdeš, in boš zbran k svojemu ljudstvu, kakor je umrl Aron, tvoj brat, na gori Horu in je bil zbran k ljudstvu svojemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 51, 'zato ker sta mi bila nezvesta med sinovi Izraelovimi pri Vodi prepira v Kadesu v Zinski puščavi, ker me nista svetega izkazala sredi sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 32, 52, 'Pred seboj boš pač videl deželo, ki jo dajem sinovom Izraelovim, ali tja v deželo samo ne prideš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 1, 'To pa je blagoslov, s katerim je blagoslovil Mojzes, mož Božji, Izraelove sinove pred svojo smrtjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 2, 'In dejal je: Gospod je prišel s Sinaja, in vstal jim je s Seira; prikazal se je v svetlobi iznad gore Paranske in prišel od desettisočev svetih; v njegovi desnici je bila ognjena postava zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 3, 'Res, On ljubi ljudstva! Vsi njih svetniki so v tvoji roki; sedli so pri nogah tvojih, vsak prejme od govorov tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 4, 'Postavo nam je zapovedal Mojzes, dedino zboru Jakobovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 5, 'In on je bil kralj v Ješurunu, ko so se zbrali poglavarji ljudstva, vsi rodovi Izraelovi skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 6, 'Živi naj Ruben in ne umrje, a malo bodi mož njegovih število.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 7, 'In to bodi Judi; in rekel je: Sliši, o Gospod, Judov glas in ga pripelji k ljudstvu njegovemu; s svojimi rokami naj se vojskuje zanje, in ti mu bodi pomoč zoper njegove zatiralce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 8, 'In za Levija je rekel: Tumim tvoje in Urim tvoje, Gospod, je pri možu, ki ga ljubiš, ki si ga izkušal v Masi, s katerim si se prepiral pri vodi Meribski;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 9, 'ki je rekel o svojem očetu in materi svoji: Nisem ju videl, tudi bratov svojih ni pripoznal in za otroke svoje ni vedel. Kajti leviti so ohranili tvojo besedo in vzdržali zavezo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 10, 'Učili bodo Jakoba tvoje sodbe in Izraela postavo tvojo; pokladali bodo kadilo pred tvoje obličje in cele žgalne daritve na oltar tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 11, 'Blagoslovi, Gospod, moč njegovo in milo sprejmi rok njegovih delo; udari ledja njih, ki se vzdigujejo zoper njega, in njih, ki ga sovražijo, da več ne vstanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 12, 'Za Benjamina je rekel: Ljubljenec Gospodov bo varno prebival pri njem; zaslanja ga ves dan in prebiva med ramami njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 13, 'In za Jožefa je rekel: Blagoslovljena bodi od Gospoda dežela njegova s predragim darom neba, z roso, in z globino, ki leži spodaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 14, 'in z najdražjimi pridelki od solnca, in z najdražjimi prirastki od mesecev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 15, 'in z najboljšimi rečmi starodavnih gorá, in z najdražjimi darovi večnih hribov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 16, 'in z najdražjimi rečmi zemlje in njene obilnosti. In blagovoljnost njega, ki je prebival v grmu, naj pride na glavo Jožefovo in na teme odličnega med svojimi brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 17, 'Veličastvo njegovo je kakor prvenca med junci in rogovi njegovi so kakor rogovi divjega bivola: ž njimi bo bodel vsa ljudstva tja do krajev zemlje; in to so desettisoči Efraimovi in to tisoči Manasejevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 18, 'Za Zebulona pa je rekel: Veséli se, Zebulon, svojega izhoda in, Isahar, svojih šatorov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 19, 'Pokličeta ljudstva na goro, tam bodo darovali pravičnosti daritve; kajti sesala bosta obilnost morja in skrite zaklade peska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 20, 'Za Gada pa je rekel: Blagoslovljen bodi, ki razširja prostor Gadu: kakor levinja počiva in raztrga ramo, tudi teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 21, 'In prvino dežele je izbral zase, kajti ondi je bil delež ohranjen postavodajalcu; in šel je s poglavarji ljudstva, izvršil je pravico Gospodovo in sodbe njegove z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 22, 'In za Dana je rekel: Dan je mlad lev, ki priskače iz Basana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 23, 'Za Neftalija pa je rekel: O Neftali, nasičen z blagovoljnostjo in poln blagoslova Gospodovega: posédi zahodno in južno stran!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 24, 'In za Aserja je rekel: Blagoslovljen bodi Aser s sinovi; prijeten bodi svojim bratom in naj pomaka v olje nogo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 25, 'Od železa in brona naj bodo zapahi tvoji, in kakršni dnevi tvoji, taka bodi moč tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 26, 'Ni ga, ki bi bil enak Bogu mogočnemu, o Ješurun, ki prijezdi po nebu tebi v pomoč in v veličastvu svojem na oblakih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 27, 'Bog večnosti ti je prebivališče in pod teboj so večne rame; in on žene sovražnika pred teboj in veli: Pokončaj jih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 28, 'In Izrael prebiva na varnem in posebe vrelec Jakobov, v deželi žita in vina, in izpod njegovega neba kaplja rosa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 33, 29, 'Blažen si, o Izrael! Kdo ti je enak, ljudstvo, rešeno po Gospodu, ki je ščit pomoči tvoje in meč veličastva tvojega! In sovražniki tvoji se ti bodo laskali, ti pa boš stopal po njih višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 1, 'In Mojzes je šel gori s planjav Moabskih na goro Nebo, na vrh Pizge, ki je nasproti Jerihu. In Gospod mu je pokazal vso pokrajino Gileadsko do Dana');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 2, 'in ves Neftalijev kraj in Efraimovo in Manasejevo pokrajino in vso deželo Judovo do zadnjega morja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 3, 'in južno stran in ravnino ob Jordanu, nižavo ob Jerihu, palmovem mestu, do Zoarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 4, 'In mu reče Gospod: To je dežela, ki sem zanjo prisegel Abrahamu, Izaku in Jakobu, rekoč: Dati jo hočem tvojemu semenu. Dal sem ti, da jo vidiš z očmi svojimi, vanjo pa ne pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 5, 'Umrl je torej Mojzes, hlapec Gospodov, ondi v Moabski deželi po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 6, 'In pokopal ga je v dolini, v deželi Moabski, nasproti Bet-peorju; ali nihče ne ve za njegov grob do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 7, 'Bil pa je Mojzes sto in dvajset let star, ko je umrl; oko mu ni otemnelo in moč njegova ni opešala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 8, 'In sinovi Izraelovi so plakali za Mojzesom na planjavah Moabskih trideset dni, in dopolnjeni so bili dnevi jokanja, žalovanja za Mojzesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 9, 'Jozue pa, sin Nunov, je bil napolnjen duha modrosti; zakaj Mojzes je bil položil svoje roke nanj. In sinovi Izraelovi so ga poslušali in delali, kakor je bil Gospod ukazal Mojzesu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 10, 'A ni nastopil več noben prorok v Izraelu, enak Mojzesu, katerega bi bil Gospod poznal od obličja do obličja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 11, 'po vseh znamenjih in čudežih, ki jih ga je poslal Gospod izvršit v deželi Egiptovski proti Faraonu in proti vsem njegovim služabnikom in proti vsej deželi njegovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (5, 34, 12, 'in po vsej mogočni roki in po vseh velikih in grozovitih delih, ki jih je storil Mojzes pred očmi vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 1, 'In zgodi se po smrti Mojzesa, hlapca Gospodovega, da je govoril Gospod Jozuetu, sinu Nunovemu, Mojzesovemu strežniku, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 2, 'Mojzes, hlapec moj je umrl; sedaj torej vstani, pojdi čez ta Jordan, ti in vse to ljudstvo, v deželo, ki jo jaz dajem njim, Izraelovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 3, 'Vsak kraj, ki stopi nanj vaše noge podplat, sem vam dal, kakor sem govoril Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 4, 'Od puščave in tega Libanona tja do velike reke, reke Evfrata, vsa dežela Hetejcev, in do velikega morja proti solnčnemu zahodu, bodi vaša meja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 5, 'Nihče se ti ne bo mogel ustavljati vse dni tvojega življenja; kakor sem bil z Mojzesom, tako bodem s teboj: ne odtegnem se ti in te ne zapustim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 6, 'Bodi močan in srčen, zakaj ti izročiš temu ljudstvu v dediščino deželo, za katero sem prisegel njih očetom, da jim jo dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 7, 'Samo močan bodi in silno srčen, da si prizadevaš delati po vsej postavi, ki ti jo je zapovedal Mojzes, hlapec moj; ne odstopi od nje ne na desno, ne na levo, da bi uspešno ravnal, kamorkoli pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 8, 'Ta knjiga postave naj ne gre od tvojih ust, temuč jo premišljaj dan in noč, da bi si prizadeval delati po vsem, kar je pisano v njej; zakaj tedaj storiš uspešno svojo pot, tedaj ti pojde po sreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 9, 'Nisem li ti zapovedal: Bodi močan in srčen? Ne straši se in ne boj se, kajti Gospod, tvoj Bog, je s teboj, kamorkoli greš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 10, 'Tedaj zapove Jozue oblastnikom ljudstva, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 11, 'Prehodite tabor in zapovejte ljudstvu ter recite: Pripravite si živeža, zakaj po treh dneh pojdete čez ta Jordan, da stopite v deželo in jo posedete, ki vam jo daje v posest Gospod, vaš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 12, 'Rubenskim pa in Gadskim in polovici Manasejevega rodu veli Jozue, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 13, 'Pomnite besede, ki vam jih je zapovedal Mojzes, služabnik Gospodov, rekši: Gospod, vaš Bog, vas je pripravil v pokoj in vam je dal to pokrajino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 14, 'Žene vaše, otročiči vaši in živina vaša naj ostane v pokrajini, ki vam jo je dal Mojzes, na tej strani Jordana; sami pa pojdite oboroženi pred svojimi brati, vsi junaški možje, in jim pomagajte,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 15, 'dokler Gospod ne pripravi pokoj vaših bratov, kakor je vas, in posedejo tudi oni deželo, katero jim daje Gospod, Bog vaš. Potem se zopet vrnete v lastno deželo in jo posedete, kakor vam jo je dal Mojzes, služabnik Gospodov, na tej strani Jordana, proti solnčnemu vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 16, 'In odgovore Jozuetu in reko: Vse, kar si nam zapovedal, storimo, in kamorkoli nas pošlješ, pojdemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 17, 'Kakor smo bili Mojzesu pokorni, bodemo tudi tebi; samo da bodi Gospod, tvoj Bog, s teboj, kakor je bil z Mojzesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 1, 18, 'Kdor se bo ustavljal povelju tvojemu in ne poslušal tvojih besed v vsem, kar nam zapoveduješ, naj umrje; samo močan bodi in srčen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 1, 'In Jozue, sin Nunov, pošlje skrivaj iz Sitima dva moža kot oglednika in veli: Pojdita, oglejta deželo in Jeriho! Ta gresta in prideta v hišo neke nečistnice, po imenu Rahab, in ondi počineta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 2, 'Povedal je pa nekdo kralju v Jerihu, rekoč: Glej, nocoj sta sem prišla moža od Izraelovih sinov, da ogledata deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 3, 'In pošlje kralj v Jerihu k Rahabi in ji sporoči: Izroči mi tista moža, ki sta prišla k tebi in sta stopila v hišo tvojo; zakaj prišla sta ogledovat vso deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 4, 'Žena pa je vzela moža in ju skrila. In reče: Res, prišla sta moža k meni, pa nisem vedela, odkod sta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 5, 'in ko so se zapirala vrata, pri temi, sta šla moža ven; kam sta šla, ne vem. Hitite precej za njima, ker ju še dotečete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 6, 'Ona pa ju je peljala na streho in ju skrila pod lanena stebla, ki jih je imela po strehi razgrnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 7, 'In možje so hiteli za njima po poti k Jordanu, do broda; in brž ko so odšli tisti, ki so ju zasledovali, so zaprli mestna vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 8, 'Preden pa sta legla, stopi ona k njima na streho');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 9, 'in reče možema: Vem, da vam je dal Gospod to deželo, ker nas je obšel strah spričo vas in zavoljo vas obupavajo vsi prebivalci te dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 10, 'Zakaj slišali smo, kako je posušil Gospod vode Rdečega morja pred vami, ko ste šli iz Egipta; in kar ste storili dvema kraljema Amorejcev, ki sta bila onostran Jordana, Sihonu in Ogu, ki ste ju s prokletjem pokončali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 11, 'In ko smo to slišali, nam je kopnelo srce in nič ni ostalo poguma v nikomer zaradi vas; zakaj Gospod, vaš Bog, je Bog v nebesih zgoraj in na zemlji spodaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 12, 'Sedaj pa, prisezita mi pri Gospodu, ker sem vama storila milost, da tudi storita milost hiši mojega očeta, in dajta mi zanesljivo znamenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 13, 'da žive ohranite mojega očeta in mater mojo, brate in sestre moje in vse, kar jih imajo, in otmete smrti duše naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 14, 'In moža ji odgovorita: Najino življenje bodi namesto vas v smrt! Če ne izdaste tega našega opravila, hočemo, ko nam da Gospod deželo, tebi izkazati milost in zvestobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 15, 'Potem ju spusti po vrvi skozi okno; kajti njena hiša je bila pri mestnem obzidju in na obzidju je prebivala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 16, 'In jima reče: Pojdita na gorovje, da vaju ne srečajo, ki so šli za vama, in ondi se skrijta tri dni, dokler se ne vrnejo vajini zasledovalci, in potem pojdita svojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 17, 'Moža pa ji rečeta: Prosta bodeva te prisege, s katero si naju zavezala:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 18, 'glej, kadar pridemo v deželo, priveži to vrvico iz karmezinastih niti na okno, skozi katero si naju doli spustila; zberi tudi k sebi v hišo svojega očeta in mater svojo, brate svoje in vso rodbino očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 19, 'In kdorkoli pride iz vrat tvoje hiše na ulice, njegova kri bodi nad glavo njegovo, in midva bodeva nedolžna; ako se pa kdo dotakne kogarkoli teh, ki bodo s teboj v hiši, njega kri pridi nad najino glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 20, 'Ali če izdaš to naše opravilo, prosta bodeva prisege, s katero si naju zavezala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 21, 'Ona reče: Bodi tako, kakor sta rekla. In odpravi ju, in odideta. In priveže karmezinasto vrvico na okno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 22, 'Ona pa gresta in prideta na gorovje, in ondi ostaneta tri dni, dokler se niso vrnili njiju zasledovalci; ti so ju iskali po vsej poti, a ju niso našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 23, 'Nato se vrneta tista dva moža doli z gorovja ter prestopita na ono stran in prideta k Jozuetu, sinu Nunovemu, in mu povesta vse, kar se jima je prigodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 2, 24, 'In rečeta Jozuetu: Res nam je dal Gospod v roke vso deželo, tudi vsi prebivalci v njej obupavajo spričo nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 1, 'In Jozue vstane zjutraj zgodaj, in odpravijo se iz Sitima in pridejo na Jordan on in vsi sinovi Izraelovi. In ondi ostanejo, dokler niso šli na drugo stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 2, 'In zgodi se po treh dneh, da so šli oblastniki sredi tabora');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 3, 'in velevali ljudstvu, rekoč: Kadar vidite skrinjo zaveze Gospoda, svojega Boga, in duhovnike levite, da jo neso, odrinite s svojega mesta in pojdite za njo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 4, 'Toda med vami in med njo bodi presledka okoli dva tisoč komolcev. Ne približajte se ji, da bi vedeli, po kateri poti vam je hoditi; zakaj niste šli po tej poti poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 5, 'In Jozue veli ljudstvu: Posvetite se! kajti jutri stori Gospod čudeže med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 6, 'In duhovnikom reče Jozue: Nesite skrinjo zaveze in pojdite pred ljudstvom! In nesli so skrinjo zaveze in šli pred ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 7, 'In Gospod reče Jozuetu: Danes te začnem poveličevati pred vsem Izraelom, da bi vedeli, kakor sem bil z Mojzesom, tako da bodem s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 8, 'Ti pa zapovej duhovnikom, ki nosijo skrinjo zaveze, rekoč: Kadar stopite ob kraju v jordansko vodo, tiho postojte v Jordanu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 9, 'In Jozue reče sinovom Izraelovim: Pristopite in čujte besede Gospoda, svojega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 10, 'In Jozue de: Po tem spoznajte, da je živi Bog mogočni med vami ter da gotovo izžene izpred vas Kanaance, Hetejce, Hevejce, Ferizejce, Girgasejce, Amorejce in Jebusejce:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 11, 'glejte, skrinja zaveze Gospoda vse zemlje pojde pred vami v Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 12, 'Vzemite si torej dvanajst mož iz Izraelovih rodov, po enega iz vsakega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 13, 'Ko pa obstanejo v vodi jordanski podplati nog duhovnikov, ki nosijo skrinjo Jehove, Gospoda vse zemlje, se razdeli voda Jordana, in voda, ki teče odzgoraj, se ustavi in bode kakor jez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 14, 'Ko se torej odpravi ljudstvo iz šatorov svojih, da bi šlo čez Jordan, in duhovniki so nesli skrinjo zaveze pred ljudstvom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 15, 'in ko so prišli tisti, ki so nesli skrinjo, k Jordanu in so se duhovnikom, s skrinjo na ramah, omočile noge kraj vode (Jordan pa je poln in stopa čez vse bregove ves čas žetve),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 16, 'tedaj se ustavijo vode, ki so tekle odzgoraj doli, in se vzdignejo kakor v jez in se kopičijo prav daleč, pri mestu Adamu, ki je poleg Zartana; vode pa, ki so tekle doli k morju v nižini, k Slanemu morju, izginejo docela. In ljudstvo je šlo preko Jordana prav nasproti Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 3, 17, 'Duhovniki pa, ki so nesli skrinjo zaveze, so stali trdno na suhem sredi Jordana, in ves Izrael je šel čez po suhem, dokler ni prešlo docela vse ljudstvo čez Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 1, 'In zgodi se, ko je vse ljudstvo docela prišlo čez Jordan, da veli Gospod Jozuetu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 2, 'Vzemite si izmed ljudstva dvanajst mož, po enega iz vsakega rodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 3, 'in jim ukažite in recite: Vzdignite iz sredi Jordana dvanajst kamenov, z mesta, kjer so trdno stale noge duhovnikov, in prinesite jih s seboj na ono stran, da jih položite v šatorišče, kjer nocoj ostanete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 4, 'Tedaj pokliče Jozue dvanajst mož, ki jih je bil pripravil izmed Izraelovih sinov, iz vsakega rodu po enega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 5, 'in jim reče: Pojdite tja pred skrinjo Gospoda, svojega Boga, v sredo Jordana, in vsak vzdigni po en kamen na ramo, po številu rodov sinov Izraelovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 6, 'da bodo v znamenje med vami. Ko bodo pozneje vprašali otroci vaši in rekli: Kaj vam pomenijo ti kameni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 7, 'jim odgovorite: Da so se razdelile vode jordanske pred skrinjo Gospodove zaveze; ko je šla čez Jordan, so se razdelile jordanske vode; in ti kameni naj bodo sinom Izraelovim v večen spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 8, 'In sinovi Izraelovi so storili tako, kakor jim je zapovedal Jozue, in vzdignili so dvanajst kamenov iz sredi Jordana, kakor je Gospod govoril Jozuetu, po številu rodov sinov Izraelovih, in so jih prinesli s seboj na mesto, kjer so prenočili, in jih ondi položili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 9, 'Jozue je tudi postavil dvanajst kamenov sredi Jordana, na mestu, kjer so stale noge duhovnikov, nesočih skrinjo zaveze, in tam so do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 10, 'Duhovniki pa, ki so nesli skrinjo, so stali sredi Jordana, dokler ni bilo dopolnjeno vse, kar je Gospod zapovedal Jozuetu, da naj govori ljudstvu, po vsem, kar je bil Mojzes ukazal Jozuetu. In ljudstvo je hitelo in prešlo na drugo stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 11, 'In ko je bilo docela prešlo vse ljudstvo, je šla tudi skrinja Gospodova čez in duhovniki, vpričo ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 12, 'In sinovi Rubenovi in Gadovi in polovica Manasejevega rodu so prešli oboroženi pred sinovi Izraelovimi, kakor jim je bil naročil Mojzes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 13, 'Okoli štirideset tisoč oboroženih za vojsko jih je prešlo pred Gospodom v boj na poljane ob Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 14, 'Tisti dan je poveličal Gospod Jozueta pred očmi vsega Izraela, in bali so se ga, kakor so se bali Mojzesa, dokler je živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 15, 'In Gospod reče Jozuetu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 16, 'Ukaži duhovnikom, ki nosijo skrinjo pričevanja, naj stopijo gori iz Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 17, 'Ukaže torej Jozue duhovnikom, rekoč: Stopite gori iz Jordana!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 18, 'In ko so stopili duhovniki, ki so nesli skrinjo Gospodove zaveze, iz Jordana in so se podplati njih nog povzdignili nad suhim, so se vrnile jordanske vode v svojo strugo in se razlivale po vseh svojih bregovih kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 19, 'Bilo pa je deseti dan prvega meseca, ko je stopilo ljudstvo iz Jordana, in utaborili so se v Gilgalu, proti vzhodu, na skrajni meji Jeriha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 20, 'In tistih dvanajst kamenov, ki so jih vzeli iz Jordana, je postavil Jozue v Gilgalu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 21, 'in je govoril sinovom Izraelovim in rekel: Ko bodo v prihodnjih časih vprašali otroci vaši očete svoje, rekoč: Kaj pomenijo ti kameni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 22, 'razložite jim in recite: Izrael je prešel ta Jordan po suhem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 23, 'Kajti Gospod, vaš Bog, je posušil jordanske vode pred vami, dokler niste prešli, kakor je Gospod, vaš Bog, storil ob Rdečem morju, katero je posušil pred nami, dokler nismo prešli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 4, 24, 'da bi spoznali vsi narodi zemlje roko Gospodovo, da je mogočna, da bi se vi bali Gospoda, svojega Boga, vse svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 1, 'Ko so pa slišali vsi kralji Amorejcev, ki so bili na tej strani Jordana proti zahodu, in vsi kralji Kanaancev, ki so bivali ob morju, kako je posušil Gospod jordanske vode pred sinovi Izraelovimi, dokler niso prešli, jim je skopnelo srce in jim ni ostalo nič poguma, zaradi sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 2, 'Tisti čas veli Gospod Jozuetu: Naredi si kamenenih nožev, in obreži zopet sinove Izraelove vdrugič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 3, 'In naredil si je Jozue kamenenih nožev in obrezal sinove Izraelove ob Hribu neobreze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 4, 'To pa je vzrok, zakaj jih je obrezal Jozue: vse ljudstvo, ki je šlo iz Egipta, kar jih je bilo moških, sposobnih za vojsko, so pomrli v puščavi po poti, ko so šli iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 5, 'In ljudstvo vse, ki je izšlo, je bilo obrezano; toda vse ljudstvo, kar se ga je rodilo v puščavi ob potovanju po odhodu iz Egipta, ni bilo obrezano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 6, 'Zakaj sinovi Izraelovi so hodili štirideset let po puščavi, dokler ni poginil ves tisti narod, vojaški možje, ki so bili odšli iz Egipta, zato ker niso poslušali Gospodovega glasu; katerim je prisegel Gospod, da jim ne da videti dežele, ki je zanjo prisegel Gospod njih očetom, da nam jo da, deželo, v kateri teče mleko in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 7, 'A njih otroke, ki jih je Gospod postavil na njih mesto, je obrezal Jozue; kajti bili so neobrezani, ker jih nihče ni obrezoval na poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 8, 'In ko so končali obrezo vsega naroda, so ostali utaborjeni na svojem mestu, dokler niso ozdraveli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 9, 'In Gospod reče Jozuetu: Danes sem odvalil z vas sramoto Egipčanov; zato se je imenovalo tisto mesto Gilgal do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 10, 'In ko so sinovi Izraelovi taborili v Gilgalu, so praznovali pasho štirinajsti dan meseca proti večeru, na poljanah Jerihovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 11, 'In jedli so od starega žita te dežele drugi dan po pashi, opresne kruhe in opraženo zrnje v isti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 12, 'In mana je preminila drugi dan, ko so jedli od žita tiste dežele, in Izraelovi sinovi niso več dobili mane, ampak jedli so od pridelkov Kanaanske dežele tisto leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 13, 'Zgodi se pa, ko je bil Jozue pri Jerihu, da povzdigne oči in gleda, in glej, nasproti mu stoji mož s potegnjenim mečem v roki. In Jozue gre k njemu in mu reče: Si li ti naš ali naših sovražnikov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 14, 'On reče: Ne, temuč knez sem vojske Gospodove; sedaj sem prišel. In Jozue pade z obličjem na tla in moli ter mu reče: Kaj pravi gospod moj svojemu hlapcu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 5, 15, 'In knez vojske Gospodove veli Jozuetu: Sezuj obuvalo z nog svojih, zakaj mesto, ki stojiš na njem, je sveto. In Jozue stori tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 1, 'Jeriho pa so zaprli in ostalo je zaprto zavoljo sinov Izraelovih: nihče ni šel ven in nihče noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 2, 'In Gospod reče Jozuetu: Poglej, dal sem ti v roko Jeriho in kralja in junaške može njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 3, 'Obkrožite torej mesto, vsi vojščaki, gredoč okoli mesta enkrat. Tako napravi šest dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 4, 'in sedem duhovnikov naj nese pred skrinjo sedem jubilejskih trobent; sedmi dan pa obkrožite mesto sedemkrat, in duhovniki naj trobijo na trobente.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 5, 'In kadar bodo zategnjeno trobili na jubilejsko trobento in zaslišite glas trobente, tedaj naj zavpije vse ljudstvo z močnim glasom: in mestno obzidje se podere na svojem kraju, in ljudstvo naj vstopi noter, vsak naravnost tja pred sabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 6, 'Nato pokliče Jozue, sin Nunov, duhovnike in jim reče: Vzdignite skrinjo zaveze, in sedem duhovnikov naj nese sedem jubilejskih trobent pred skrinjo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 7, 'Ljudstvu pa veli: Vstanite in pojdite okoli mesta, in oboroženci naj gredo pred skrinjo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 8, 'In zgodilo se je tako: ko naroči Jozue ljudstvu, gre naprej sedem duhovnikov, nesoč sedem jubilejskih trobent pred Gospodom, in trobijo s trobentami, in skrinja Gospodova je šla za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 9, 'In oboroženci gredo pred duhovniki, ki trobijo s trobentami, in zadnji voj gre za skrinjo, in neprestano trobijo s trobentami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 10, 'Jozue pa zapove ljudstvu in reče: Ne napravite bojnega krika, tudi naj se ne sliši glas vaš; še beseda naj ne pride iz vaših ust do dne, ko vam bom velel kričati; tedaj zaženite bojni krik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 11, 'Tako je šla skrinja Gospodova okoli mesta enkrat; in prišli so zopet v tabor in ondi prenočili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 12, 'In Jozue vstane zjutraj zgodaj, in duhovniki neso skrinjo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 13, 'in sedem duhovnikov nese sedem trobent milostnega leta pred skrinjo Gospodovo in gredoč trobijo neprestano s trobentami, in oboroženci gredo pred njimi, zadnji voj pa gre za skrinjo Gospodovo, in neprestano trobijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 14, 'Tako so drugi dan šli okoli mesta enkrat in se zopet vrnili v tabor. Enako so delali šest dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 15, 'Ali sedmi dan, ob jutranjem svitu, vstanejo zgodaj in gredo po istem načinu okoli mesta sedemkrat; samo tisti dan so obkrožili mesto sedemkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 16, 'In sedmi pot, ko duhovniki trobijo s trobentami, veli Jozue ljudstvu: Napravite bojni krik, zakaj Gospod vam je dal mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 17, 'Mesto pa in vse, kar je v njem, bodi v prokletje za Gospoda; samo Rahabo nečistnico ohranite živo, njo in vse, ki so ž njo v hiši, zato ker je skrila sla, ki smo ju bili poslali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 18, 'Vi pa se varujte prokletega, da ne bi, ko ste ga naredili v prokletje, vzeli česa iz prokletega in bi spravili tabor Izraelov v prokletje in v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 19, 'Toda vse srebro in zlato in bronaste in železne posode so svete Gospodu, pridejo naj v Gospodov zaklad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 20, 'Tedaj je ljudstvo zagnalo bojni krik, in trobili so na trobente. In ko je ljudstvo čulo glas trobente in zagnalo močan bojni krik, se je podrlo obzidje na svojem kraju, in ljudstvo je stopilo gori v mesto, vsak naravnost pred sabo, in zavzeli so mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 21, 'In s prokletjem so uničili vse, kar je bilo v mestu, može in žene, mlade in stare, vole, ovce in osle, z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 22, 'Jozue pa reče tistima dvema možema, ki sta ogledala deželo: Stopita v hišo tiste nečistnice in odpeljita odondod ženo z vsemi njenimi, kakor sta ji prisegla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 23, 'In ta dva mladeniča, oglednika, gresta noter in odpeljeta Rahabo venkaj, tudi njenega očeta in mater in njene brate in vse, kar jih je imela, vse sorodništvo njeno peljeta na plano; in pusté jih zunaj Izraelovega taborišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 24, 'Mesto pa so sežgali z ognjem in vse, kar je bilo v njem; samo srebro in zlato in bronasto in železno posodo so deli v zakladnico hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 25, 'A Rahabo nečistnico in njenega očeta rodbino in vse njene je Jozue ohranil v življenju; in prebivala je v Izraelu do današnjega dne, ker je bila skrila sla, ki ju je Jozue poslal ogledovat Jeriho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 26, 'Tisti čas je prisegel Jozue in rekel: Proklet bodi pred Gospodom mož, ki vstane, da sezida to mesto Jeriho: ko mu položi podstavo, naj izgubi prvorojenca svojega, in ko mu postavi vrata, naj izgubi svojega najmlajšega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 6, 27, 'Tako je bil Gospod z Jozuetom, in glas o njem je šel po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 1, 'Sinovi Izraelovi pa so zagrešili nezvestobo pri prokletem; zakaj Ahan, sin Karmija, sinu Zabdija, Zerahovega sinu, iz rodu Judovega, je vzel od prokletega. In srd Gospodov se je razvnel zoper Izraelove sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 2, 'Kajti Jozue je poslal može iz Jeriha proti Aju, ki je pri Betavenu, vzhodno od Betela, in jim rekel: Pojdite gori in oglejte deželo. In gredo in ogledajo Aj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 3, 'In ko se vrnejo k Jozuetu, mu reko: Naj ne hodi gori vse ljudstvo, a gre naj jih okoli dva ali tri tisoč in naj pokončajo Aj; ne pošlji tja vsega ljudstva, zakaj onih je malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 4, 'Šlo je torej tja gori ljudstva okoli tri tisoč mož; pa so pobegnili pred možmi iz Aja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 5, 'In možje iz Aja so pobili izmed njih šestintrideset mož, in so jih podili izpred vrat do Sebarima in jih pobijali, ko so navzdol bežali. In ljudstvu se je raztopilo srce in bilo je kakor voda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 6, 'Jozue pa si raztrga oblačila in pade z obličjem na zemljo pred skrinjo Gospodovo in leži do večera, on in starešine Izraelovi, in sipljejo prah na glave svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 7, 'In Jozue reče: Ah, Gospod, Jehova, zakaj si vendar peljal to ljudstvo čez Jordan, da nas daš v roke Amorejcem v pogubo? O da nismo rajši ostali onostran Jordana!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 8, 'Oh, Gospod, kaj naj rečem, ko je Izrael zbežal pred sovražniki svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 9, 'In slišali bodo to Kanaanci in vsi prebivalci v deželi, in nas obsujejo in iztrebijo naše ime z zemlje! In kaj storiš za veliko svoje ime?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 10, 'In Gospod reče Jozuetu: Vstani! zakaj tako ležiš na obličju svojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 11, 'Izrael je grešil, res, prestopili so zavezo mojo, ki sem jim jo zapovedal, ker so vzeli od prokletega, pa so tudi ukradli in še zatajili in tudi položili med svojo robo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 12, 'Zato ne morejo sinovi Izraelovi stati pred svojimi sovražniki, ampak bežati jim je, ker so v prokletstvu; več ne bodem z vami, dokler ne odpravite izmed sebe prokletstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 13, 'Vstani, posveti ljudstvo in reci: Posvetite se za jutrišnji dan, zakaj tako pravi Gospod, Bog Izraelov: Stvar prokleta je med teboj, o Izrael; ne moreš stati pred svojimi sovražniki, dokler ne odpraviš prokletstva izmed sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 14, 'Zjutraj torej pristopite sem po rodovih svojih, in rod, ki ga zadene Gospod, naj pristopi po svojih rodovinah, in rodovina, ki jo zadene Gospod, naj pristopi rodbina za rodbino; in rodbina, ki jo zadene Gospod, naj pristopi mož za možem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 15, 'In kdor bo zadet v prokletstvu, bodi v ognju sežgan z vsem, kar ima, ker je prestopil zavezo Gospodovo in ker je nespamet storil v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 16, 'Zjutraj zgodaj pa vstane Jozue in ukaže Izraelu pristopati po svojih rodovih, in zadet je bil rod Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 17, 'In ukaže pristopiti rodovinam Judovim, in zadeta je bila rodovina Zerahovcev. Ko pristopi rodovina Zerahovcev, gospodar za gospodarjem, je bil zadet Zabdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 18, 'In ko pristopi rodbina njegova, mož za možem, je bil zadet Ahan, sin Karmija, sinu Zabdija, sinu Zerahovega, iz Judovega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 19, 'In Jozue reče Ahanu: Sin moj, daj vendar slavo Gospodu, Izraelovemu Bogu, in pripoznaj njemu, in povej mi vendar, kaj si storil? Ničesar mi ne taji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 20, 'Tedaj odgovori Ahan Jozuetu in reče: Resnično, pregrešil sem se zoper Gospoda, Izraelovega Boga, in tako in tako sem storil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 21, 'videl sem med plenom dragocen babilonski plašč in dvesto seklov srebra in šibiko zlata, petdeset seklov težko, in sem se tega polakomnil ter sem vzel, in glej, zakopano je sredi mojega šatora v zemlji, in srebro je odspodaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 22, 'Jozue torej pošlje sle, in teko k šatoru, in glej, skrito je bilo v njegovem šatoru, in srebro odspodaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 23, 'In vzemo te stvari izpod šatora in prineso Jozuetu in pred vse sinove Izraelove in jih polože pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 24, 'Jozue pa in ves Izrael ž njim vzame Ahana, sina Zerahovega, in srebro in plašč in šibiko zlata, sinove in hčere njegove, tudi vole in osle in ovce njegove, in šator njegov in vse, kar je imel, in jih peljejo gori v dolino Ahor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 25, 'In Jozue reče: Kako si nas pripravil v nesrečo! Naj te Gospod spravi v nesrečo ta dan! In ves Izrael ga luča s kamenjem, in sežgo jih z ognjem in jih posujejo s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 7, 26, 'In napravijo nad njim velik kup kamenja, ki je do današnjega dne. In odvrnila se je togota jeze Gospodove. Zato se imenuje tisti kraj dolina Ahor do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 1, 'In Gospod veli Jozuetu: Ne boj se in ne plaši se! Vzemi vse vojščake s seboj in vstani ter pojdi gori zoper Aj! Poglej, dal sem ti v roko kralja v Aju ter ljudstvo in mesto in deželo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 2, 'In stori Aju in njegovemu kralju, kakor si storil Jerihu in kralju njegovemu, samo njegov plen in živino njegovo si razdelite med seboj. Postavi si zasedo zadaj za mestom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 3, 'Vstane torej Jozue in vsi vojščaki, da bi šli gori proti Aju; Jozue pa izbere trideset tisoč mož, krepkih junakov, in jih odpošlje po noči');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 4, 'ter jim zapove, rekoč: Pazite, vi bodete v zasedi zadaj za mestom; ne hodite pa daleč od mesta, temuč bodite vsi pripravljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 5, 'Jaz pa in vse ljudstvo, ki je z menoj, se približamo mestu. In ko pridejo ven zoper nas kakor onkrat, bomo bežali pred njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 6, 'in spusté se za nami, in tako jih odtegnemo od mesta; kajti poreko: Beže pred nami kakor poprej. In ko bomo bežali pred njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 7, 'planite iz zasede in zavzemite mesto, zakaj Gospod, vaš Bog, vam ga izda v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 8, 'In ko vzamete mesto, ga zažgite; delajte po besedi Gospodovi! Glejte, jaz sem vam to zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 9, 'Pošlje jih torej Jozue, in so šli v zasedo in ostali med Betelom in Ajem, na večerni strani mesta Aja. Jozue pa je prenočil med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 10, 'Zjutraj pa vstane Jozue zgodaj in prešteje ljudstvo in gre s starešinami Izraelovimi ljudstvu na čelu proti Aju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 11, 'Tudi vse vojaško moštvo, ki je bilo pri njem, gre gori ž njim, in približajo se ter pridejo pred mesto in se utabore na polnočni strani Aja, da je bila le dolina med njimi in Ajem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 12, 'Vzel pa je okoli pet tisoč mož in jih postavil v zasedo med Betelom in Ajem, na zahodni strani mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 13, 'In postavijo moštvo vsega tabora, da je bilo na polnočni strani mesta, zasednike pa na zahodni strani mesta. In Jozue je šel tisto noč v sredo doline.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 14, 'Ko pa vidi to kralj v Aju, pohite mestni možje ter vstanejo zgodaj in planejo ven, da se bojujejo z Izraelom, kralj in vse ljudstvo njegovo, na določen kraj pred ravnino; a ni vedel, da je zaseda zoper njega zadaj za mestom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 15, 'Jozue pa in ves Izrael zbeži kakor premagan pred njimi po poti proti puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 16, 'In skličejo vse ljudstvo, ki je bilo v mestu, da udero za njimi; in spuste za Jozuetom in se ločijo od mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 17, 'In ni ostalo enega moža v Aju ali Betelu, ki ne bi bil šel tirat Izraela; mesto pa so pustili odprto in se gnali za Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 18, 'Tedaj reče Gospod Jozuetu: Vzdigni sulico, ki jo imaš v roki, proti Aju; kajti dam ti ga v roko. In Jozue vzdigne sulico, ki jo je imel v roki, proti mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 19, 'In zasedniki se hitro vzdignejo s svojega mesta in teko, bržko je iztegnil roko, in pridejo v mesto ter se ga polaste in ga precej zažgo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 20, 'Ko se pa ajski možje ozro, vidijo, in glej, dim se vali iz mesta do neba; njim pa ni mogoče bežati ne sem, ne tja. A ljudstvo izraelsko, ki je bežalo proti puščavi, se obrne in plane nad svoje preganjalce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 21, 'Ko namreč vidi Jozue in ves Izrael, da so zasedniki dobili mesto ter da se vali dim iz njega, se zopet obrnejo in pobijajo može iz Aja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 22, 'In zasedniki pridejo iz mesta, njim nasproti, tako da Izraelci zajamejo Ajance po tej in po oni strani in jih porazijo, da nihče ni preostal, ne utekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 23, 'Ajskega kralja pa ujamejo živega in ga pripeljejo k Jozuetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 24, 'In ko je Izrael pobil vse prebivalce mesta Aja, na polju in v puščavi, kamor so bili za njimi pridrli, in so vsi popadali z ostrino meča, da jih je bilo konec, se obrne ves Izrael proti Aju in ga pokončajo z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 25, 'In vseh, ki so padli tisti dan, mož in žen, je bilo dvanajst tisoč, vsi iz Aja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 26, 'Jozue pa ni potegnil nazaj roke, s katero je vzdignil sulico, dokler ni s prokletjem uničil vseh ajskih prebivalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 27, 'Samo živino in plen mesta so si Izraelci razdelili med seboj, po besedi Gospodovi, ki jo je zapovedal Jozuetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 28, 'Tako je Jozue požgal Aj in napravil iz njega grobljišče za vselej, podrtino, ki je do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 29, 'Ajskega kralja pa je obesil na drevesu do večera; in ko je solnce zahajalo, ukaže Jozue, naj snamejo truplo njegovo z drevesa, in vrgli so ga ob vhodu v mestna vrata ter napravili nad njim veliko grobljo, do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 30, 'Tedaj zgradi Jozue oltar Gospodu, Bogu Izraelovemu, na gori Ebalu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 31, 'prav kakor je sinovom Izraelovim zapovedal Mojzes, hlapec Gospodov, kakor je pisano v knjigi Mojzesovega zakona, oltar iz neobdelanih kamenov, nad katerimi niso vihteli železa; in prinašali so na njem žgalne žrtve Gospodu in darovali mirovne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 32, 'In ondi napiše na kamene opis Mojzesovega zakona, ki ga je pisal vpričo sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 33, 'In ves Izrael s starejšinami in oblastniki in sodniki svojimi je stal ob tej in oni strani skrinje pred obličjem duhovnikov, levitov, ki so nosili skrinjo zaveze Gospodove, tujci in domačini; polovica njih proti gori Garizimu in polovica proti gori Ebalu, kakor je zapovedal Mojzes, hlapec Gospodov, da naj blagoslove Izraelovo ljudstvo najprvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 34, 'In potem je čital vse besede postave, blagoslov in prokletje, vse, kakor je pisano v knjigi postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 8, 35, 'Ni bilo besede iz tega, kar je zapovedal Mojzes, ki je ne bi bil omenil Jozue pred vsem zborom Izraelovim in pred ženami in otročiči in tujci, ki so bivali med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 1, 'Ko pa zaslišijo kralji, ki so bili tostran Jordana, po gorah in v nižavi in po vsem obrežju velikega morja tja do Libanona, Hetejci, Amorejci, Kanaanci, Ferizejci, Hevejci in Jebusejci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 2, 'so se zbrali vsi enodušno, da se vojskujejo z Jozuetom in z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 3, 'A prebivalci v Gibeonu, ko so slišali, kaj je storil Jozue Jerihu in Aju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 4, 'so tudi skovali zvijačo: gredo in se napravijo, kakor da bi bili poslanci, in denejo stare vreče na svoje osle in stare vinske mehove, razdrte in zašite,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 5, 'tudi staro in zakrpano obuvalo si nataknejo na noge in na sebe staro obleko; in ves kruh, ki so ga imeli za brašno, je bil trd in plesniv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 6, 'In pridejo k Jozuetu v tabor v Gilgalu in reko njemu in Izraelovim možem: Prišli smo iz daljnih dežel; sklenite torej zavezo z nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 7, 'Možje Izraelovi pa reko Hevejcem: Morebiti prebivate med nami, kako naj sklenemo zavezo z vami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 8, 'In reko Jozuetu: Hlapci smo tvoji. Jozue pa jih vpraša: Kdo ste? In odkod ste prišli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 9, 'Odgovore mu: Hlapci tvoji so prišli iz silno daljnih dežel zaradi imena Gospoda, tvojega Boga; zakaj slišali smo glas o njem in vse, kar je storil Egiptu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 10, 'tudi vse, kar je storil dvema kraljema Amorejcev onostran Jordana, Sihonu, kralju v Hesbonu, in Ogu, kralju v Basanu, ki je bil v Astarotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 11, 'Zato so nam rekli naši starejšine in vsi prebivalci naše dežele: Vzemite si živeža na pot in pojdite jim naproti in jim recite: Hlapci smo vaši. Zdaj torej sklenite zavezo z nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 12, 'Ta kruh naš, ki smo ga iz svojih hiš vzeli za brašno, je bil še gorak, ko smo odhajali na pot k vam, zdaj pa, glej, je trd in plesniv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 13, 'In te vinske mehove smo napolnili nove, pa glej, razdrti so. In ta naša obleka in naše obuvalo se je prestaralo po silno dolgem popotovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 14, 'In možje vzamejo od njih brašna, a ne vprašajo za svet Gospodovih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 15, 'In Jozue sklene mir ž njimi in jim stori zavezo, da bodo ohranjeni pri življenju; in knezi občine so jim prisegli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 16, 'Ali po treh dneh, potem ko so storili ž njimi zavezo, jim pride na vest, da so oni njih sosedi ter da prebivajo med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 17, 'Kajti ko so sinovi Izraelovi šli dalje, so tretji dan prispeli k njih mestom. Njih mesta pa so bila: Gibeon, Kefira, Beerot in Kirjat-jearim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 18, 'A sinovi Izraelovi jih niso pobili, zato ker so jim bili prisegli knezi občine pri Gospodu, Izraelovem Bogu. In mrmrala je vsa občina na kneze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 19, 'Vsi knezi pa reko vsej občini: Mi smo jim prisegli pri Gospodu, Izraelovem Bogu, zato se jih ne moremo dotekniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 20, 'Ali to jim hočemo storiti: ostanejo naj pri življenju, da ne pride srd nad nas zavoljo prisege, ki smo jim jo prisegli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 21, 'In reko jim knezi: Naj le žive! A morajo sekati drva in nositi vodo vsej občini, – kakor so jim knezi bili rekli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 22, 'Tedaj jih pokliče Jozue in jih ogovori, rekoč: Zakaj ste nas prekanili, govoreč: Silno daleč smo od vas, pa prebivate med nami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 23, 'Zato ste zdaj prokleti, da nikdar ne nehajo biti iz vas hlapci, ki sekajo drva in nosijo vodo za hišo mojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 24, 'Odgovore Jozuetu in reko: V istini je bilo povedano nam, hlapcem tvojim, kar je zapovedal Gospod, tvoj Bog, svojemu hlapcu Mojzesu, da vam da vso deželo in iztrebi vse prebivalce v njej izpred vas; torej smo se spričo vas silno bali za življenje svoje in smo storili to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 25, 'Sedaj pa glej, v roki smo tvoji: stóri, kar se ti zdi dobro in prav, da z nami storiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 26, 'In tako jim je storil in jih otel iz roke Izraelovih sinov, da jih niso pobili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 9, 27, 'In Jozue jih je tisti dan postavil, da sekajo drva in nosijo vodo občini in k oltarju Gospodovemu, do tega dne, na mestu, ki bi si ga izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 1, 'Ko pa sliši Adonizedek, kralj v Jeruzalemu, da je Jozue dobil Aj in ga s prokletjem pokončal, storivši z Ajem in njegovim kraljem enako, kakor je storil Jerihu in njegovemu kralju, in da so prebivalci v Gibeonu sklenili mir z Izraelci in bivali med njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 2, 'se silno zboji, ker Gibeon je bil veliko mesto, kakor kraljevo mesto, in ker je bilo večje nego Aj, in vsi meščani njegovi so bili junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 3, 'Zato pošlje Adonizedek, jeruzalemski kralj, k Hohamu, kralju v Hebronu, in k Piramu, kralju v Jarmutu, in k Jafiju, kralju v Lahisu, in k Debirju, kralju v Eglonu, in jim sporoči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 4, 'Pridite gori k meni in pomagajte mi, da pokončamo Gibeon, kajti mir je sklenil z Jozuetom in s sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 5, 'Zbere se torej petero amorejskih kraljev, kralj v Jeruzalemu, kralj v Hebronu, kralj v Jarmutu, kralj v Lahisu, kralj v Eglonu, in gredo gori z vsemi svojimi vojskami in se utabore proti Gibeonu in začno ž njim vojno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 6, 'Gibeonski možje pa pošljejo k Jozuetu v tabor v Gilgalu in mu sporoče: Ne odtegni roke svoje od hlapcev svojih; pridi hitro gori k nam in nas reši ter nam pomagaj: zakaj vsi kralji Amorejcev, ki prebivajo na gorah, so se zbrali zoper nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 7, 'Jozue se torej napoti gori iz Gilgala, on in ž njim vsi vojščaki in vsi junaški možje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 8, 'Gospod pa veli Jozuetu: Ne boj se jih, kajti dal sem jih v roke tvoje; nihče od njih ne bo mogel stati pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 9, 'In Jozue, ko je šel gori celo noč od Gilgala, plane nadnje iznenada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 10, 'In Gospod jih preplaši spričo Izraela in napravi med njimi velik poboj pri Gibeonu, in podili so jih po poti, ki drži k brdom Bethoronskim, ter jih pobijali do Azeke in do Makede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 11, 'In zgodi se, ko so bežali pred Izraelom in so šli doli po strmini Bethoronski, da je Gospod metal veliko kamenje z neba nanje prav do Azeke, in mrli so: več jih je pomrlo od kamenite toče, nego so jih pomorili sinovi Izraelovi z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 12, 'Takrat je govoril Jozue z Gospodom, v dan, ko je Gospod izročil Amorejce pogubi pred Izraelovimi sinovi, in je dejal vpričo Izraela: Solnce, stoj mirno v Gibeonu in, mesec, v dolini Ajalonu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 13, 'In mirno je stalo solnce in mesec je obstal, dokler se narod ni sovražnikom maščeval. Ni li to pisano v knjigi Pravičnega? In stalo je solnce sredi neba in ni hitelo, da bi zašlo, skoraj ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 14, 'In ni bilo temu enakega dne ne prej, ne poslej, da bi Gospod tako uslišal človekov glas; zakaj Gospod se je bojeval za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 15, 'In vrne se Jozue in ves Izrael ž njim v tabor v Gilgalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 16, 'A tistih pet kraljev je zbežalo, in skrili so se v votlini pri Makedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 17, 'In sporoči se Jozuetu: Našli so petero kraljev skritih v votlini v Makedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 18, 'In Jozue veli: Privalite velike kamene k vhodu v votlino in postavite prednjo može, da jih varujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 19, 'A vi ne stojte, zasledujte svoje sovražnike in pobijajte njih zadnje ostanke, ne dajte jim stopiti v njih mesta; zakaj dal vam jih je v roko Gospod, vaš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 20, 'Ko so jih torej Jozue in Izraelovi sinovi docela porazili z zelo velikim pobojem, da jih je bilo konec, in kar jih je preostalo, so ušli v utrjena mesta:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 21, 'tedaj se vrne vse ljudstvo v tabor k Jozuetu v Makedi v miru; nihče ne migne več z jezikom proti komu izmed sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 22, 'Nato reče Jozue: Odprite vhod v votlino in pripeljite mi tistih petero kraljev iz nje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 23, 'In store tako in mu pripeljejo tistih pet kraljev iz votline: kralja jeruzalemskega, kralja hebronskega, kralja jarmutskega, kralja lahiškega in kralja eglonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 24, 'In ko so pripeljali te kralje k Jozuetu, pokliče Jozue vse Izraelove može in reče načelnikom vojščakov, ki so bili šli ž njim: Pridite in stopite tem kraljem z nogami na tilnik! In gredo ter jim stopajo z nogami na tilnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 25, 'Jozue pa jim reče: Ne bojte se in ne bodi vas groza; močni bodite in srčni, zakaj tako stori Gospod vsem vašim sovražnikom, ki se bojujete zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 26, 'In potem jih Jozue udari in jih umori in obesi na pet dreves; in so viseli na drevesih do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 27, 'Ko pa je solnce zahajalo, zapove Jozue, naj jih snamejo z dreves in vržejo v votlino, ki so se vanjo bili zalezli; in polože velike kamene na vhod v votlino, ki so tam do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 28, 'Tisti dan je dobil Jozue Makedo in jo udaril z ostrino meča in kralja njenega; izvršil je prokletje nad njo in nad vsemi dušami, ki so bile v njej, pustil ni nikogar živega; in storil je kralju v Makedi, kakor je bil storil kralju v Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 29, 'In Jozue in ž njim ves Izrael je šel dalje iz Makede proti Libni in se bojeval z Libno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 30, 'In Gospod jo je tudi dal in kralja njenega v roko Izraelu; in udaril jo je z ostrino meča in vse duše, ki so bile v njej, nikogar ni pustil živega, in kralju njenemu je storil enako kakor kralju v Jerihu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 31, 'Potem je šel Jozue in ž njim ves Izrael dalje od Libne proti Lahisu, in raztaboril se je ob njem in se ž njim bojeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 32, 'In Gospod je dal Lahis Izraelu v roke, da so ga vzeli drugi dan in ga udarili z ostrino meča in vse duše, ki so bile v njem, prav tako, kakor je storil v Libni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 33, 'Tedaj pride gori Horam, kralj v Gezerju, pomagat Lahisu; a Jozue ga udari in vse ljudstvo njegovo, da mu ni preostalo ne enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 34, 'In Jozue in ž njim ves Izrael gre dalje iz Lahisa proti Eglonu, in se raztabori ob njem in se bojuje ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 35, 'in ga dobi še tisti dan v pest ter ga udari z ostrino meča in izvrši prokletje nad vsemi dušami, ki so bile v njem, tisti dan, prav tako, kakor je storil v Lahisu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 36, 'In Jozue in ves Izrael ž njim je šel gori od Eglona proti Hebronu, in se ž njim bojujejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 37, 'in ga dobe ter ga udarijo z ostrino meča, kralja njegovega in vsa mesta njegova in vse duše, ki so bile v njih; ni dal ubežati nikomur, prav kakor je storil v Eglonu; in izvršil je prokletje nad njim in nad vsemi dušami, ki so bile v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 38, 'Nato se obrne Jozue in ves Izrael ž njim proti Debirju in se ž njim bojuje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 39, 'in ga dobi in kralja njegovega in vsa mesta njegova, in jih udari z ostrino meča in prokletju izroči vse duše, ki so bile v njem; ubežal mu ni niti eden; kakor je storil Hebronu in kakor je storil Libni in njenemu kralju, tako je storil Debirju in kralju njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 40, 'Tako je Jozue premagal vso deželo, gorovje in vso južno stran in nižavo in strmine in vse njih kralje, ubežal ni niti eden; in izvršil je prokletje nad vsem, kar je dihalo, kakor je bil zapovedal Gospod, Izraelov Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 41, 'In Jozue jih je premagal od Kades-barnee do Gaze in vso Gosensko pokrajino prav do Gibeona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 42, 'In vse te kralje in njih dežele je zavzel Jozue naenkrat, kajti Gospod, Izraelov Bog, se je bojeval za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 10, 43, 'In Jozue in ž njim ves Izrael se je vrnil zopet v tabor v Gilgalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 1, 'Ko pa je slišal o tem Jabin, kralj v Hazorju, pošlje k Jobabu, kralju v Madonu, in h kralju v Simronu in h kralju v Aksafu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 2, 'in h kraljem, ki so bili proti severu po gorovju in v nižini južno od Kinerota in po nižavah in po Dorskih višinah proti morju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 3, 'h Kanaancem na vzhodni in zahodni strani in k Amorejcu, Hetejcu, Ferizejcu in Jebusejcu v gorah in k Hevejcu pod goro Hermonom v deželi Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 4, 'In ti se vzdignejo in vsa njih vojna krdela ž njimi, velika množina ljudstva kakor peska na morskem bregu, tudi silno veliko konj in voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 5, 'Vsi ti kralji se zbero in pridejo ter se utabore pri vodi v Meromu, da bi se bojevali z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 6, 'A Gospod reče Jozuetu: Ne bodi te strah spričo njih, zakaj jutri obsore ti jih izročim, da bodo vsi pobiti pred Izraelom; konje jim ohromi in njih vozove sežgi z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 7, 'In Jozue pride nagloma nadnje in ž njim vsi vojščaki k vodi Meromu, in planejo nadnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 8, 'In Gospod jih je dal Izraelu v roko, in porazijo jih ter jih pode do velikega Sidona in do Misrefotmajima in do doline Micpe proti jutru; in pobijejo jih, da jim ni ostalo nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 9, 'In Jozue jim stori, kakor mu je ukazal Gospod: ohromil jim je konje in sežgal vozove z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 10, 'In Jozue se povrne tisti čas in vzame Hazor in udari kralja njegovega z mečem; kajti Hazor je bil poprej glava vsem tem kraljestvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 11, 'In pobijejo vse ljudi, kar jih je bilo v njem, z ostrino meča, izročivši jih prokletju; ostalo ni ničesar, kar je dihalo, in sežgal je Hazor z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 12, 'In vsa mesta tistih kraljev in vse njih kralje zajame Jozue in jih udari z ostrino meča, izročivši jih prokletju, kakor je zapovedal Mojzes, hlapec Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 13, 'Samo tistih mest, ki so stala na hribih, ni sežgal Izrael nobenega, razen Hazorja, tisto je sežgal Jozue.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 14, 'In ves plen teh mest in živino so razdelili sinovi Izraelovi med seboj, ali vsakega človeka so udarili z ostrino meča, dokler jih niso zatrli, in pustili niso ničesar, kar je dihalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 15, 'Kakor je Gospod zapovedal Mojzesu, hlapcu svojemu, tako je Mojzes zapovedal Jozuetu; in tako je storil Jozue, ničesar ni pustil nestorjenega od vsega, kar je Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 16, 'Tako se je Jozue polastil vse te dežele, gorovja in vse južne strani in vse Gosenske dežele in ravnine in nižine in Izraelovega gorovja z njegovo nižavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 17, 'od Gole gore, ki se vzdiguje proti Seiru, prav do Baalgada v Libanonski dolini pod goro Hermonom; in zajame vse njih kralje in jih udari ter usmrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 18, 'Dosti časa se je Jozue vojskoval z vsemi temi kralji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 19, 'Ni bilo mesta, ki bi se bilo v miru vdalo sinovom Izraelovim, razen Hevejskih, ki so prebivali v Gibeonu; vsa druga so zavzeli z bojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 20, 'Kajti od Gospoda je bilo, da se je otrdilo njih srce za boj z Izraelom; zato da se izroče prokletju in jim ne bo milosti, ampak da bodo iztrebljeni, kakor je Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 21, 'In Jozue je prišel tisti čas in zatrl Enakime z gorovja, iz Hebrona, iz Debirja, iz Anaba in z vsega Judovskega gorovja in z vsega Izraelskega gorovja, in izročil jih je prokletju ž njih mesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 22, 'Nobenega teh Enakimov ni ostalo v deželi Izraelovih sinov, samo v Gazi, v Gatu in v Asdodu jih je preostalo nekaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 11, 23, 'Tako je zavzel Jozue vso deželo, skladno z vsem, kar je Gospod govoril Mojzesu; in Jozue jo je dal Izraelu v dediščino, vsakemu rodu njegov del. In počivala je dežela od vojne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 1, 'Ti pa so kralji dežele, ki so jih zmagali Izraelovi sinovi in posedli njih dežele za Jordanom proti solnčnemu vzhodu, od potoka Arnona do gore Hermona, in vso nižino proti vzhodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 2, 'Sihon, kralj Amorejcev, ki je prebival v Hesbonu in gospodoval od Aroerja, ki leži ob bregu potoka Arnona in sredi doline, in nad polovico Gileada tja do potoka Jaboka, ki je meja Amonovih sinov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 3, 'in nad ravnino do morja Kinerotskega proti vzhodu, in tja do morja v nižini, to je Slano morje, proti vzhodu, koder drži pot do Bet-jesimota, in ob južni strani pod strminami Pizge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 4, 'In pokrajina Oga, kralja basanskega, ki je preostal izmed velikanov in je prebival v Astarotu in Edreju');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 5, 'in gospodoval nad goro Hermonom in nad Salko in nad vsem Basanom tja do meje Gesurcev in Maakatovcev, in nad polovico Gileada do meje Sihona, kralja v Hesbonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 6, 'Mojzes, hlapec Gospodov, in sinovi Izraelovi so porazili ta dva kralja. In Mojzes, hlapec Gospodov, je dal njiju posest Rubenskim, Gadskim in polovici Manasejevega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 7, 'In ti so kralji dežele, ki jih je porazil Jozue in sinovi Izraelovi na tej strani Jordana, proti zahodu, od Baalgada v Libanonski dolini tja do Gole gore, ki se vzdiguje proti Seiru. In Jozue je dal to Izraelovim rodovom v posest, vsakemu njegov del;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 8, 'kar je bilo po gorovju in po nižavah in v nižini, po strminah, v puščavi in na južni strani, Hetejce, Amorejce, Kanaance, Ferizejce, Hevejce in Jebusejce:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 9, 'kralj v Jerihu, eden; kralj v Aju, ki je blizu Betela, eden;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 10, 'kralj v Jeruzalemu, eden, kralj v Hebronu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 11, 'kralj v Jarmutu, eden, kralj v Lahisu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 12, 'kralj v Eglonu, eden, kralj v Gezerju, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 13, 'kralj v Debirju, eden, kralj v Gederju, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 14, 'kralj v Hormi, eden, kralj v Aradu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 15, 'kralj v Libni, eden, kralj v Adulamu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 16, 'kralj v Makedi, eden, kralj v Betelu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 17, 'kralj v Tapuahu, eden, kralj v Heferju, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 18, 'kralj v Afeku, eden, kralj v Lašaronu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 19, 'kralj v Madonu, eden, kralj v Hazorju, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 20, 'kralj v Simron-meronu, eden, kralj v Aksafu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 21, 'kralj v Taanahu, eden, kralj v Megidu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 22, 'kralj v Kedesu, eden, kralj v Jokneamu pri Karmelu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 23, 'kralj v Doru na Dorskih višinah, eden, kralj Gojimov v Gilgalu, eden,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 12, 24, 'kralj v Tirzi, eden: vseh kraljev trideset in eden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 1, 'Ko pa je bil Jozue že star in prileten, mu reče Gospod: Star si in prileten, in še je ostalo dosti dežele, ki naj bi jo vzeli v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 2, 'To je dežela, ki je še ostala: vse pokrajine Filistejcev in vse Gesursko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 3, 'od Sihorja, ki teče poleg Egipta, tja do meje Ekrona ob severu, kar se šteje h Kanaancem; pet kneževin Filistejcev, Gaza, Asdod, Askelon, Gat, Ekron; tudi kraj Avimcev');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 4, 'proti jugu; vsa pokrajina Kanaancev in Meara, ki je Sidoncev, tja do Afeka, do meje Amorejcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 5, 'in vsa pokrajina Gebaljanov in ves Libanon, proti solnčnemu vzhodu, od Baalgada, spodaj ob gori Hermonu do poti v Hamat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 6, 'Vsi gorjanci od Libanona do Misrefotmajima in vsi Sidonci. Nje hočem izgnati pred sinovi Izraelovimi, samo razdéli jih po žrebu v dediščino Izraelu, kakor sem ti zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 7, 'Razdéli torej to deželo v dediščino devetim rodovom in polovici Manasejevega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 8, 'Kajti Rubenovci in Gadovci so prejeli svojo dediščino z drugo Manasejevo polovico, ki jo jim je dal Mojzes za Jordanom, proti vzhodu; kakor jim je oddelil Mojzes, hlapec Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 9, 'Od Aroerja, ki leži ob bregu potoka Arnona, in od mesta, ki je sredi doline, in vso ravnino Medebo do Dibona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 10, 'in vsa mesta Sihona, kralja Amorejcev, ki je gospodoval v Hesbonu, prav do meje Amonovih sinov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 11, 'k temu Gilead in pokrajino Gesurcev in Maakatovcev in vso goro Hermon in ves Basan tja do Salke;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 12, 'vse Ogovo kraljestvo v Basanu, ki je gospodoval v Astarotu in v Edreju in je bil iz ostanka velikanov; in Mojzes jih je premagal in pregnal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 13, 'A Izraelovi sinovi niso izgnali Gesurcev in Maakatovcev, temuč Gesur in Maakat sta prebivala med Izraelovimi sinovi do današnjega dne. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 14, 'Samo Levijevemu rodu ni dal dediščine; ognjene žrtve Gospodu, Izraelovemu Bogu, so njih dediščina, kakor mu je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 15, 'Dal pa je Mojzes rodu Rubenovih sinov po njih rodovinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 16, 'da je bila njih pokrajina od Aroerja, ki leži na bregu potoka Arnona, in mesto sredi doline in vsa ravnina pri Medebi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 17, 'Hesbon in vsa njegova mesta, ki so na ravnini: Dibon, Bamotbal, Betbalmeon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 18, 'Jahaz, Kedemot in Mefat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 19, 'Kirjataim, Sibma in Zeret-sahar na hribu v dolini,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 20, 'Bet-peor in strmine Pizge in Bet-jesimot');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 21, 'in vsa mesta na ravnini in vse kraljestvo Sihona, kralja Amorejcev, ki je gospodoval v Hesbonu; njega je Mojzes porazil in madianske kneze, Evija, Rekema, Zura, Hura in Reba, poglavarje Sihonove, ki so prebivali v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 22, 'Tudi Balaama sina Beorjevega, vedeža, so sinovi Izraelovi umorili z mečem med drugimi ubitimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 23, 'In meja Rubenovim sinovom je bil Jordan in njegovo obrežje. To je dediščina Rubenovih sinov po njih rodovinah, mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 24, 'In rodu Gadovih sinov je dal Mojzes po njih rodovinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 25, 'da je bila njih pokrajina: Jazer in vsa mesta v Gileadu in polovica dežele Amonovih sinov tja do Aroerja, ki je pred Rabo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 26, 'in od Hesbona do Ramat-micpe in Betonima in od Mahanaima do debirskih mej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 27, 'v dolini pa Bet-haram, Bet-nimra, Suhot in Zafon, ostanek kraljestva Sihona, kralja v Hesbonu, in Jordan z obrežjem do zadnjega kraja morja Kineretskega, ki je za Jordanom, proti vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 28, 'To je dediščina Gadovih sinov po njih rodovinah, mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 29, 'In Mojzes je dal dediščino polovici Manasejevega rodu; in prejela je polovica rodu Manasejevih sinov po svojih rodovinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 30, 'da je bila njih pokrajina: od Mahanaima ves Basan, vse kraljestvo Oga, kralja v Basanu, in vsi Jairovi trgi, ki so v Basanu, šestdeset mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 31, 'In polovico Gileada in Astarot in Edrej, mesta Ogovega kraljestva v Basanu, so dobili sinovi Mahirja, Manasejevega sinu, polovica Mahirjevih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 32, 'Te so dediščine, ki jih je Mojzes razdelil na poljanah Moabskih, vzhodno od Jordana, Jerihu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 13, 33, 'Ali Levijevemu rodu ni dal Mojzes dediščine, zakaj Gospod, Bog Izraelov, je njih dediščina, kakor jim je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 1, 'Te pa so dediščine, ki so jih dobili sinovi Izraelovi v Kanaanski deželi, ki so jih jim porazdelili Eleazar duhovnik in Jozue, sin Nunov, in poglavarji očetovinam vseh rodov Izraelovih sinov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 2, 'po žrebanju so jim pridelili dediščino, kakor je Gospod zapovedal po Mojzesu, devetim rodom in polovici rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 3, 'Dvema rodoma in polovici rodu je namreč Mojzes dal dediščino na oni strani Jordana. Levitom pa ni dal dediščine med njimi nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 4, 'Kajti Jožefovih sinov sta bila dva roda, Manase in Efraim; in levitom niso dali deleža v deželi, samo mesta za prebivanje in pašnike okoli njih njih živini in njih blagu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 5, 'Kakor je bil Gospod zapovedal Mojzesu, tako so storili Izraelovi sinovi in so razdelili deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 6, 'Tedaj pristopijo Judovi sinovi k Jozuetu v Gilgalu, in Kaleb, sin Jefunov, Kenizejec, ga ogovori: Ti veš, kar je rekel Gospod Mojzesu, možu Božjemu, zastran mene in tebe v Kades-barnei.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 7, 'Štirideset let sem bil star, ko me je poslal Mojzes, služabnik Gospodov, iz Kades-barnee ogledovat deželo; in prinesel sem mu poročilo, kakor mi je bilo pri srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 8, 'Toda moji bratje, ki so šli gori z menoj, so ljudstvu v obup zapeljali srce, jaz pa sem zvesto hodil za Gospodom, Bogom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 9, 'In Mojzes je prisegel tisti dan, rekoč: Gotovo bode dežela, po kateri je stopala tvoja noga, tebi in tvojim otrokom dediščina vekomaj, ker si zvesto hodil za Gospodom, Bogom mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 10, 'In sedaj, glej, Gospod me je ohranil v življenju, kakor je govoril teh štirideset in pet let, odkar je govoril besedo to Mojzesu, ko je Izrael potoval po puščavi. In sedaj, glej, danes sem petinosemdeset let star:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 11, 'in še danes sem tako krepak kakor tisti dan, ko me je Mojzes odposlal; kakršna je bila moja moč takrat, je tudi sedaj, da se bojujem in hodim ven in noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 12, 'Sedaj torej mi daj to gorovje, ki je o njem govoril Gospod tisti dan; kajti slišal si takrat, da so Enakimi ondi in velika in utrjena mesta. Morda bode Gospod z menoj, da jih preženem, kakor je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 13, 'Tedaj ga blagoslovi Jozue ter da Hebron v dediščino Kalebu, sinu Jefunovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 14, 'Zato je prišel Hebron v dedno posest Kalebu, Jefunovemu sinu, Kenizejcu, do današnjega dne, ker je zvesto hodil za Gospodom, Bogom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 14, 15, 'Hebron pa se je prej imenoval Arbovo mesto; ta je bil največji mož med Enakimi. In dežela je počivala od vojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 1, 'In delež rodu Judovih sinov po njih rodovinah je bil: do edomske meje, ob Zinski puščavi, južno, na skrajnem jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 2, 'In njih južna meja se je začela pri kraju Slanega morja, ob jeziku, ki se razteza proti jugu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 3, 'in je šla proti jugu do Akrabimskega vrha in čez njega do Zina in gori ob južni strani Kades-barnee in skozi Hezron in gori do Adarja in se obrnila do Karke;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 4, 'in je šla čez do Azmona in došla k Egiptovskemu potoku, da je bilo morje konec meji. To bodi vaša južna meja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 5, 'Vzhodna meja pa je bilo Slano morje do ustja Jordana. In meja severnega dela se je začela ob jeziku morja pri ustju Jordana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 6, 'in je šla gori proti Bethogli in dalje ob severni strani Bet-arabe, in šla gori do kamena Bohana, Rubenovega sinu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 7, 'in šla je gori k Debirju od doline Ahor in se obrnila severno proti Gilgalu, ki je nasproti višini Adumimu na južni strani potoka; in meja je šla dalje k vodi Ensemesu in njeni konci so bili pri studencu Rogelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 8, 'in je šla po dolini Hinomovega sinu proti južni strani Jebusejca (to je Jeruzalem); in je šla gori do vrha gore, ki je pred Hinomovo dolino proti zahodu in ob kraju doline Refaimov proti severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 9, 'Potem je šla meja od vrha gore do studenca pri Neftoahu in k mestom v Efronskem gorovju in navzdol k Baali (ki je Kirjat-jearim);');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 10, 'in meja se je obrnila od Baale proti zahodu k Seirskemu gorovju in je šla do slemena gore Jearima na severu (to je Kesalon) in se nagnila doli k Betsemesu in šla skozi Timno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 11, 'nato je šla dalje proti severu k slemenu Ekrona in se raztezala do Sikrona in šla čez goro Baalo in došla k Jabneelu, in morje je bilo konec tej meji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 12, 'In zahodna meja je bilo veliko morje in njegovo obrežje. To je meja Judovih sinov kroginkrog po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 13, 'Kalebu pa, sinu Jefunovemu, je dal delež med Judovimi sinovi po povelju Gospodovem Jozuetu, mesto Arbovo, ki je Hebron. (Arba je bil oče Enakov.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 14, 'In Kaleb je izgnal odondod tri Enakove sinove: Sesaja, Ahimana in Talmaja, Enakove otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 15, 'In odtod je šel gori proti prebivalcem v Debirju. Debir se pa je nekdaj imenoval Kirjat-sefer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 16, 'In Kaleb je dejal: Kdor udari Kirjat-sefer in ga dobi, njemu hočem dati Akso, svojo hčer za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 17, 'In Otniel, sin Kenaza, Kalebovega brata, ga je dobil; in dal mu je Akso, svojo hčer, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 18, 'In zgodi se, ko je šla k njemu, da ga je izpodbujala, naj prosi njenega očeta njive. In spustila se je z osla. In Kaleb ji reče: Kaj ti je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 19, 'Ona pa reče: Daj mi blagoslov; kajti dal si mi južni kraj, daj mi tudi studence voda. In dal ji je studence gornje in dolnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 20, 'To je dediščina rodu Judovih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 21, 'In mesta rodu Judovih sinov od kraja do edomske meje na jugu so bila: Kabzeel, Eder in Jagur,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 22, 'Kina, Dimona in Adada,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 23, 'Kedes, Hazor in Itnan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 24, 'Zif, Telem in Bealot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 25, 'Hazor-hadata, Kerjot-hezron (ki je Hazor),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 26, 'Amam, Sema, Molada,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 27, 'Hazar-gada, Hesmon in Betpelet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 28, 'Hazar-sual, Berseba in Bizjotja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 29, 'Baala, Ijim in Ezem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 30, 'Eltolad, Kesil in Horma,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 31, 'Ziklag, Madmana in Sansana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 32, 'Lebaot, Silhim, Ajin in Rimon: vseh mest devetindvajset in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 33, 'V nižavi pa: Estaol, Zora in Asna,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 34, 'Zanoah, Enganim, Tapuah in Enam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 35, 'Jarmut in Adulam, Soko in Azeka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 36, 'Saraim, Aditaim, Gedera in Gederotaim: štirinajst mest in njih sela –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 37, 'Zenan, Hadasa, Migdalgad,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 38, 'Dilan, Micpa, Jokteel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 39, 'Lahis, Bozkat, Eglon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 40, 'Kabon, Lahmam, Kitlis,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 41, 'Gederot, Betdagon, Naama in Makeda: šestnajst mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 42, 'Libna, Eter, Asan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 43, 'Jiftah, Asna, Nezib,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 44, 'Keila, Akzib in Maresa: devet mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 45, 'Ekron, njegove vasi in sela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 46, 'od Ekrona do morja, kar jih je bilo ob strani Asdoda, in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 47, 'Asdod, njegove podložne vasi in sela; Gaza, njene podložne vasi in sela do Egiptovskega potoka, in veliko morje in njegovo obrežje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 48, 'V gorovju pa: Samir, Jatir, Soko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 49, 'Dana in Kirjat-sana (to je Debir),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 50, 'Anab, Estemo, Anim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 51, 'Gosen, Holon in Gilo: enajst mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 52, 'Arab, Duma, Ešan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 53, 'Janim, Bet-tapuah, Afeka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 54, 'Humta, Kirjat-arba (to je Hebron) in Zior: devet mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 55, 'Maon, Karmel, Zif, Juta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 56, 'Jezreel, Jokdeam, Zanoah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 57, 'Kajn, Gibea in Timna: deset mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 58, 'Halhul, Betzur, Gedor,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 59, 'Maarat, Betanot in Eltekon: šest mest in njih sela. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 60, 'Kirjat-baal (to je Kirjat-jearim) in Raba: dve mesti in njiju sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 61, 'V puščavi: Betaraba, Midin, Sekaka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 62, 'Nibsan, in Solno mesto in Engedi: šest mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 15, 63, 'Ali Jebusejcev, ki so prebivali v Jeruzalemu, niso mogli izgnati Judovi sinovi. Prebivali so torej Jebusejci z Judovimi sinovi v Jeruzalemu do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 1, 'In delež Jožefovim sinovom je šel od Jordana pri Jerihu, poleg Jeriških vod ob vzhodu, puščava, ki gre gori od Jeriha čez gorovje do Betela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 2, 'In meja je šla od Betela do Luza in dalje do meje Arkičanov, do Atarota,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 3, 'in navzdol proti zahodu do meje Jafletskih, do meje nižjega Bethorona in do Gezerja, in njen konec je bil pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 4, 'To sta prejela v dediščino Jožefova sinova Manase in Efraim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 5, 'To pa je meja Efraimovih sinov po njih rodovinah: vzhodna meja njih dediščine sega od Atarot-adarja do gorenjega Bethorona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 6, 'in meja je šla proti zahodu do Mikmetata na severni strani in se obrnila proti vzhodu k Taanat-silu in šla mimo njega na vzhodno stran Janohe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 7, 'in šla doli od Janohe do Atarota in do Naare, in je segala do Jeriha in se končala pri Jordanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 8, 'Od Tapuaha je šla meja proti zahodu do potoka Kane in njen konec je bil pri morju. To je dediščina rodu Efraimovih sinov, po njih rodovinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 9, 'z mesti vred, ki so bila odločena za Efraimove sinove sredi dediščine Manasejevih sinov, vsa tista mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 16, 10, 'Niso pa izgnali Kanaancev, ki so prebivali v Gezerju; prebivali so torej Kanaanci med Efraimskimi, do tega dne, tlaki in davku podvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 1, 'In to je bil delež Manasejevemu rodu – kajti on je bil Jožefov prvenec –: Mahirju, Manasejevemu prvencu, očetu Gileadovemu, sta se pridelila Gilead in Basan, zato ker je bil vojščak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 2, 'Drugi Manasejevi sinovi so dobili tudi delež po svojih rodovinah, namreč otroci Abiezerjevi, otroci Helekovi, otroci Asrielovi, otroci Sihemovi, otroci Heferjevi in otroci Semidovi: to so bili moški potomci Manaseja, sinu Jožefovega, po svojih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 3, 'Ali Zelofad, sin Heferja, sina Gileada, sina Mahirja, sina Manaseja, ni imel sinov, ampak hčere, in njih imena so ta: Mahla, Noa, Hogla, Milka in Tirza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 4, 'Te stopijo pred duhovnika Eleazarja in pred Jozueta, sina Nunovega, in pred kneze in reko: Gospod je zapovedal Mojzesu, naj nam da dediščino med našimi brati. Zato jim je dal po zapovedi Gospodovi dediščino med brati njih očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 5, 'In tako je pripadlo Manaseju deset delov razen Gileadske dežele in Basana, ki je vzhodno od Jordana;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 6, 'kajti Manasejeve hčere so prejele dediščino med njegovimi sinovi, Gileadska dežela pa je pripadla drugim Manasejevim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 7, 'In Manasejeva meja je šla od Aserja do Mikmetata, ki je pred Sihemom, in je šla dalje na desno k prebivalcem Entapuaha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 8, 'Kajti pokrajina Tapuah je bila Manasejeva, ali Tapuah ob Manasejevi meji je bil Efraimovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 9, 'Potem je šla meja doli k potoku Kani, južno od potoka; ta mesta so bila Efraimova sredi med Manasejevimi mesti. Pokrajina Manasejeva pa je bila na severni strani potoka in njen konec je bil pri morju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 10, 'južno je bila Efraimova, severno pa Manasejeva, in morje mu je bilo v mejo; do Aserja se je raztezala proti severu in do Isaharja proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 11, 'Manase pa je imel v Isaharju in v Aserju: Betsean in njemu podložne vasi in Ibleam in njemu podložne vasi, in prebivalce v Doru in njih podložne vasi in prebivalce v Endoru in njih podložne vasi in prebivalce v Taanahu in njih podložne vasi in prebivalce v Megidu in njih podložne vasi, tiste tri višine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 12, 'Toda Manasejevi sinovi niso mogli pregnati prebivalcev tistih mest, in Kanaancem se je zljubilo ostati v tej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 13, 'Ko pa so se ojačili Izraelovi sinovi, so podvrgli Kanaance davku, a jih niso dočista pregnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 14, 'Jožefovi sinovi pa so govorili z Jozuetom in rekli: Zakaj si dal meni samo en delež in del v dediščino, ko sem vendar veliko ljudstvo, ker me je doslej blagoslovil Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 15, 'In Jozue jim reče: Ako si veliko ljudstvo, pojdi gori v gozd in si iztrebi ondi v deželi Ferizejcev in Refaimov, ko ti je Efraimsko gorovje pretesno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 16, 'A Jožefovi sinovi reko: To gorovje nam ne bode zadosti; vsi Kanaanci pa, ki prebivajo v ravnini, imajo železne vozove, i oni, ki so v Betseanu in njemu podložnih mestih, i oni, ki so na Jezreelski ravnini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 17, 'Tedaj reče Jozue Jožefovi hiši, Efraimu in Manaseju: Veliko si ljudstvo in veliko imaš moč, ne boš imel le enega deleža,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 17, 18, 'ampak gorovje bodi tvoje; ker pa je gozd, posekaj ga in do koncev gozda bodi tvoje; zakaj ti preženeš Kanaance, čeprav imajo železne vozove in čeprav so močni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 1, 'In vsa občina Izraelovih sinov se je zbrala v Silu, in tu so razpeli shodni šator; in dežela je bila premagana pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 2, 'Bilo je pa še sedem rodov Izraelovih sinov, ki se jim še ni pridelila njih dediščina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 3, 'In Jozue reče Izraelovim sinovom: Doklej bodete leni, da ne pojdete si prilastit dežele, ki vam jo je dal Gospod, vaših očetov Bog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 4, 'Določite si po tri može iz vsakega rodu, in hočem jih poslati, da vstanejo in preidejo deželo ter jo popišejo, kakor je treba za njih dediščine, in potem naj zopet pridejo k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 5, 'In naj razdelé deželo v sedem delov: Juda naj ostane v svoji pokrajini na jugu, in Jožefova hiša ostani v svoji pokrajini na severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 6, 'Vi pa napravite popis dežele v sedmih oddelkih in mi ga prinesite sem; in vržem za vas žreb tu pred Gospodom, Bogom našim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 7, 'Kajti leviti nimajo deleža med vami, temuč duhovska služba Gospodu je njih dediščina; Gad in Ruben in polovica Manasejevega rodu so prejeli svoj del onostran Jordana proti vzhodu, kakor jim je dal Mojzes, hlapec Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 8, 'Vstanejo torej tisti možje in se odpravijo. In Jozue jim zapove, ko hočejo iti popisovat deželo, rekoč: Pojdite ter prehodite deželo, in ko jo popišete, pridite zopet k meni, in vržem za vas tu, v Silu, žreb pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 9, 'In možje gredo ter obhodijo deželo in jo popišejo v knjigi po njenih mestih, v sedmih oddelkih, in pridejo k Jozuetu v tabor v Silo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 10, 'Tedaj vrže Jozue zanje žreb v Silu pred Gospodom in razdeli deželo med Izraelove sinove, vsakemu njegov del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 11, 'In žreb je padel za rod Benjaminovih sinov po njih rodovinah, in pokrajina njih deleža je šla med Judovimi sinovi in med Jožefovimi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 12, 'In njih meja na severni strani se je začela od Jordana in je šla gori za hrbtom Jeriha na severu in šla čez gore proti zahodu, in njen konec je bil pri Betavenski puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 13, 'In meja je šla dalje odtod k Luzu, za hrbtom Luza (ki je Betel) proti jugu; in je šla doli proti Atarot-adarju čez goro, ki je na južni strani ob nižjem Bethoronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 14, 'Potem se je raztezala in se obrnila proti zahodu, južno od gore, ki je pred Bethoronom na južni strani, in njen konec je bil pri Kirjat-baalu, ki je Kirjat-jearim, mesto Judovih sinov. To je zahodna stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 15, 'Južna stran pa se je začela ob koncu Kirjat-jearima, in meja je šla proti zahodu in se končala tik studenca pri Neftoahu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 16, 'in šla doli k zadnjemu koncu gore, ki je pred dolino Hinomovega sina, ki je v dolini Refaimov proti severu, in je šla doli po Hinomovi dolini ob strani Jebusejcev proti jugu in doli k studencu Rogelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 17, 'in se je raztezala na sever in prišla proti Ensemesu in dalje h Gelilotu, ki je nasproti griču Adumimu, in je šla doli h kamenu Bohana, Rubenovega sina;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 18, 'in je prešla k slemenu, ki je severno nasproti Arabi, in doli v Arabo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 19, 'in meja je šla dalje ob strani Bethogle proti severu in se je končala pri severnem jeziku Slanega morja, ob južnem koncu Jordana. To je južna meja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 20, 'Jordan pa je bil meja na vzhodni strani. To je bila dediščina Benjaminovih sinov po svoji meji kroginkrog, po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 21, 'Mesta pa rodu Benjaminovih sinov, po njih rodovinah so bila: Jeriho, Bethogla, Emek-keziz,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 22, 'Betaraba, Zemaraim, Betel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 23, 'Avim, Para, Ofra,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 24, 'Kefar-amoni, Ofni in Geba: dvanajst mest in njih sela;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 25, 'Gibeon, Rama, Beerot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 26, 'Micpe, Kefira, Moza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 27, 'Rekem, Irpeel, Tarala,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 18, 28, 'Zela, Elef in Jebusejec (to je Jeruzalem), Gibeat in Kirjat: štirinajst mest in njih sela. To je dediščina Benjaminovih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 1, 'In drugi žreb je padel za Simeona, v delež rodu Simeonovih sinov po njih rodovinah; in njih dediščina je bila sredi dediščine Judovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 2, 'In njim je bilo v dediščino: Berseba, Seba, Molada,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 3, 'Hazar-sual, Bala, Ezem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 4, 'Eltolad, Betul, Horma,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 5, 'Ziklag, Bet-markabot, Hazar-susa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 6, 'Betlebaot in Saruhen: trinajst mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 7, 'Ajin, Rimon, Eter in Asan: štiri mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 8, 'In vsa sela, ki so okoli teh mest tja do Baalat-beera, ki je Rama na jugu. To je dediščina rodu Simeonovih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 9, 'Od deleža Judovih sinov je bila dediščina Simeonovih sinov: kajti delež Judovih sinov je bil prevelik zanje, zato so dobili Simeonovi sinovi dediščino sredi njih dediščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 10, 'Tretji žreb je padel za Zebulonove sinove po njih rodovinah. In meja njih dediščine je segala do Sarida,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 11, 'in je šla gori proti zahodu in do Marala in segala do Dabeseta in šla tik potoka, ki teče pred Jokneamom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 12, 'in se je obrnila od Sarida vzhodno proti solnčnemu vzhodu do meje Kislot-tabora in je šla do Dabrata in gori k Jafiji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 13, 'in odtod dalje vzhodno proti vzhodu do Gat-heferja, do Etkazina, in prišla do Rimona, ki se razteza do Nea;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 14, 'in tu se je meja obrnila k severu proti Hanatonu in njen konec je bil v dolini Iftahela;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 15, 'in Katat, Nahalal, Simron, Idala, Betlehem: dvanajst mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 16, 'To je dediščina Zebulonovih sinov po njih rodovinah, ta mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 17, 'Četrti žreb je padel za Isaharja, Isaharjevim sinom po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 18, 'In njih pokrajina je bila: Jezreel, Kesulot, Sunem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 19, 'Hafaraim, Šion, Anaharat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 20, 'Rabit, Kisjon, Ebez,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 21, 'Remet, Enganim, Enhada in Betpazez;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 22, 'in meja je segala do Tabora, Sahazume in Betsemesa, in konec meji je bil Jordan: šestnajst mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 23, 'To je dediščina rodu Isaharjevih sinov po njih rodovinah, mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 24, 'Peti žreb je padel za rod Aserjevih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 25, 'In njih pokrajina je bila: Helkat, Hali, Beten, Aksaf,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 26, 'Alamelek, Amad, Misal, in meja je segala do Karmela ob morju in do Sihor-libnata;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 27, 'in se je obrnila proti solnčnemu vzhodu k Betdagonu in segala do Zebulona in do doline Iftahela proti severu, do Betemeka in Nehiela, in je šla naprej do Kabula na levi strani:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 28, 'in Ebron, Rehob, Hamon, Kana, tja do velikega Sidona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 29, 'in meja se je obrnila do Rame in do utrjenega mesta Tira in krenila proti Hosi, in njen konec je bil pri morju, ob okraju Akzibu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 30, 'tudi Uma, Afek in Rehob: dvaindvajset mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 31, 'To je dediščina rodu Aserjevih sinov po njih rodovinah, ta mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 32, 'Šesti žreb je padel za Neftalijeve sinove, Neftalijevim sinovom po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 33, 'In njih meja je bila od Helefa, od hrasta v Zaananimu in Adami-nekeba in Jabneela do Lakuma, in njen konec pri Jordanu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 34, 'in meja se je obrnila proti zahodu k Aznot-taboru in je šla odtod do Hukoka in je segala do Zebulona na jugu, na zahodu pa do Aserja in do Jude ob Jordanu, proti solnčnemu vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 35, 'In utrjena mesta so bila: Zidim, Zer, Hamat, Rakat, Kineret,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 36, 'Adama, Rama, Hazor,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 37, 'Kedes, Edrej, Enhazor,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 38, 'Iron, Migdalel, Horem, Betanat in Betsemes: devetnajst mest in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 39, 'To je dediščina rodu Neftalijevih sinov po njih rodovinah, ta mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 40, 'Sedmi žreb je padel za rod Danovih sinov po njih rodovinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 41, 'In pokrajina njih dediščine je bila: Zora, Estaol, Irsemes,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 42, 'Saalabin, Ajalon, Itla,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 43, 'Elon, Timnata, Ekron,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 44, 'Elteke, Gibeton, Baalat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 45, 'Jehud, Beneberak, Gat-rimon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 46, 'Mejarkon, Rakon z okrajem nasproti Jopi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 47, 'In meja Danovih sinov se je pozneje raztezala še dalje; zakaj Danovi sinovi so šli gori in se bojevali zoper Lesem in so ga dobili in udarili z ostrino meča, in so si ga prilastili ter v njem prebivali, in imenovali so Lesem Dan po imenu Dana, svojega očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 48, 'To je dediščina rodu Danovih sinov po njih rodovinah, ta mesta in njih sela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 49, 'Tako so končali delitev dežele v dediščine po njenih mejah; tudi Jozuetu, Nunovemu sinu, so dali Izraelovi sinovi dediščino sredi sebe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 50, 'po zapovedi Gospodovi so mu dali mesto, ki ga je želel, namreč Timnat-serah na gorovju Efraimskem. In sezidal je mesto in prebival v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 19, 51, 'To so dediščine, ki so jih po žrebu razdelili Eleazar duhovnik in Jozue, sin Nunov, in poglavarji očetovin vseh rodov Izraelovih sinov v Silu pred Gospodom, ob vhodu shodnega šatora. In končali so razdeljevanje zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 1, 'In Gospod je govoril Jozuetu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 2, 'Govori Izraelovim sinovom in reci: Določite si zavetna mesta, o katerih sem vam govoril po Mojzesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 3, 'da sme zbežati tja ubijalec, ki ubije človeka nehotoma in ponevedoma, da vam bodo v zavetišča pred maščevalcem krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 4, 'In kdor zbeži v eno teh mest, naj oznani, stoječ ob vhodu v mestna vrata, svojo stvar starejšinam tistega mesta, in vzamejo ga k sebi v mesto in mu dado prostora, da prebiva med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 5, 'In ako ga preganja maščevalec krvi, mu ne smejo izročiti ubijalca, kajti ubil je svojega bližnjega ponevedoma in ga ni poprej sovražil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 6, 'Naj ostane v tistem mestu, dokler se ne postavi pred občino zaradi sodbe in dokler ne umrje veliki duhovnik, ki bode v tem času. Tedaj naj se vrne ubijalec in pride v svoje mesto in v svojo hišo v mestu, odkoder je zbežal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 7, 'In odločili so Kedes v Galileji na Neftalijevem gorovju in Sihem na Efraimskem gorovju in Kirjat-arbo (ki je Hebron) na gorovju Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 8, 'In za Jordanom, vzhodno od Jeriha, so določili Bezer v puščavi, na ravnini, od Rubenovega rodu, in Ramot v Gileadu od Gadovega rodu in Golan v Basanu od Manasejevega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 20, 9, 'Ta so bila določena mesta za vse Izraelove sinove in za tujce, ki med njimi bivajo, da bi tja zbežal, kdor je ubil človeka nehotoma, da mu ne bo umreti po roki maščevalca krvi, dokler se ne postavi pred občino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 1, 'Tedaj pristopijo poglavarji levitskih očetov k Eleazarju duhovniku in k Jozuetu, sinu Nunovemu, in k poglavarjem očetov Izraelovih rodov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 2, 'in jih ogovore v Silu, v Kanaanski deželi, takole: Gospod je zapovedal po Mojzesu, da naj dobimo mesta v domovanje in njih okraje za živino svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 3, 'Dali so torej Izraelovi sinovi levitom od dediščine svoje, po povelju Gospodovem, tale mesta ž njih okraji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 4, 'In žreb je padel za rodovine Kahatovcev: in dobili so sinovi Arona duhovnika, leviti, po žrebu trinajst mest od rodu Judovega, od rodu Simeonovega in od rodu Benjaminovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 5, 'Drugi Kahatovi sinovi pa so dobili po žrebu deset mest od rodovin rodu Efraimovega, od rodu Danovega in od polovice rodu Manasejevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 6, 'Gersonovi sinovi pa so dobili po žrebu trinajst mest od rodovin rodu Isaharjevega, od rodu Aserjevega in od rodu Neftalijevega in od polovice Manasejevega rodu v Basanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 7, 'Merarijevi sinovi so dobili po svojih rodovinah dvanajst mest od rodu Rubenovega, od rodu Gadovega in od rodu Zebulonovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 8, 'Dali so torej Izraelovi sinovi po žrebu levitom ta mesta ž njih okraji, kakor je bil Gospod zapovedal po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 9, 'Od rodu sinov Judovih in od rodu sinov Simeonovih so dali ta mesta, ki so jih z imeni imenovali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 10, 'in bila so za Aronove sinove iz rodovin Kahatovcev, ki so bili Levijevi otroci; kajti njih je bil prvi delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 11, 'Dali so jim torej mesto Arba, ki je bil oče Enakov, v Judovih gorah (to je Hebron) in pašnike okoli njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 12, 'Ali njive tega mesta in njegova sela so dali v posest Kalebu, sinu Jefunovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 13, 'In sinovom Arona duhovnika so dali Hebron in njegove pašnike, zavetno mesto za ubijalca, in Libno s pašniki');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 14, 'in Jatir s pašniki in Estemoo s pašniki');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 15, 'in Holon in njegove pašnike in Debir s pašniki');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 16, 'in Ajin s pašniki in Juto s pašniki in Betsemes s pašniki: devet mest od teh dveh rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 17, 'Od Benjaminovega rodu pa Gibeon ž njegovimi pašniki, Gebo s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 18, 'Anatot s pašniki in Almon s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 19, 'Vseh mest Aronovih sinov, duhovnikov, je bilo trinajst in pašniki okoli njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 20, 'In rodovine Kahatovih sinov, leviti, drugi Kahatovi sinovi, kar jih je še preostajalo, so dobili mesta svojega žreba od rodu Efraimovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 21, 'In dali so jim Sihem, zavetno mesto za ubijalca, ž njegovimi pašniki v Efraimskem gorovju in Gezer s pašniki');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 22, 'in Kibzaim s pašniki in Bethoron s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 23, 'In od Danovega rodu: Elteke s pašniki, Gibeton s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 24, 'Ajalon s pašniki, Gat-rimon s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 25, 'Od polovice Manasejevega rodu pa dve mesti: Taanah s pašniki in Gat-rimon s pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 26, 'Vseh mest, ki so jih dobili tisti drugi sinovi Kahatove rodovine, je bilo deset in pašniki okoli njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 27, 'In Gersonovim sinovom, levitskim rodovinam, so dali od polovice Manasejevega rodu dve mesti: Golan v Basanu, zavetno mesto za ubijalca, ž njegovimi pašniki in Beastero s pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 28, 'Od Isaharjevega rodu pa Kisjon s pašniki, Dabrat s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 29, 'Jarmut s pašniki in Enganim s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 30, 'In od Aserjevega rodu: Misal s pašniki, Abdon s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 31, 'Helkat s pašniki in Rehob s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 32, 'In od Neftalijevega rodu: Kedes v Galileji, zavetno mesto za ubijalca, in njegove pašnike, Hamot-dor s pašniki in Kartan s pašniki: tri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 33, 'Vseh mest Gersonovcev po njih rodovinah je bilo trinajst in pašniki okoli njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 34, 'In rodovinam Merarijevih sinov, levitom, kar jih je še bilo, so dali od Zebulonovega rodu: Jokneam s pašniki, Karto s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 35, 'Dimno s pašniki, Nahalal s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 36, 'In od Rubenovega rodu: Bezer s pašniki, Jahaz s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 37, 'Kedemot s pašniki in Mefaat s pašniki: štiri mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 38, 'In od Gadovega rodu: Ramot v Gileadu, zavetno mesto za ubijalca, in njegove pašnike, in Mahanaim s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 39, 'Hesbon s pašniki, Jazer s pašniki: štiri mesta skup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 40, 'Vsa ta so bila mesta Merarijevih sinov po njih rodovinah, kolikor je še bilo levitskih rodovin: dvanajst mest so dobili po žrebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 41, 'Vseh levitskih mest sredi posestva Izraelovih sinov je bilo oseminštirideset mest ž njih pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 42, 'Ta mesta so imela vsako svoje pašnike okoli sebe; tako je bilo pri vseh teh mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 43, 'Tako je dal Gospod Izraelu vso deželo, ki jo je s prisego obljubil dati njih očetom, in so jo posedli in v njej prebivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 44, 'In Gospod jim je pripravil pokoj vsepovsod, po vsem, kar je bil prisegel njih očetom; in ni mogel stati ne eden izmed vseh njih sovražnikov pred njimi; vse njih sovražnike jim je dal Gospod v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 21, 45, 'Ni izginila besedica od vsega dobrega, kar je bil Gospod obljubil Izraelovi hiši; vse se je izpolnilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 1, 'Tedaj pokliče Jozue Rubenske in Gadske in polovico Manasejevega rodu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 2, 'in jim reče: Ohranili ste vse, kar vam je bil zapovedal Mojzes, hlapec Gospodov, in ste poslušali glas moj v vsem, kar sem vam zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 3, 'Niste zapustili svojih bratov vse tiste mnoge dni do dandanes, a zvesto ste pazili na zapoved Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 4, 'Ker pa je zdaj pripravil Gospod, vaš Bog, pokoj vašim bratom, kakor jim je bil obljubil, zato pojdite sedaj in se vrnite v svoje šatore, v posestva svojega deželo, ki vam jo je dal Mojzes, hlapec Gospodov, onostran Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 5, 'Samo prizadevajte si skrbno, da izpolnjujete zapoved in postavo, ki vam jo je zapovedal Mojzes, hlapec Gospodov: da ljubite Gospoda, Boga svojega, ter hodite po vseh potih njegovih in hranite zapovedi njegove in se njega oklepate in njemu služite iz vsega srca svojega in z vso dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 6, 'In blagoslovil jih je Jozue ter jih odpustil, in šli so k svojim šatorom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 7, 'Polovici Manasejevega rodu je bil dal Mojzes dediščino v Basanu, a drugi polovici je dal Jozue med njih brati tostran Jordana, proti zahodu. Vrhutega jih je Jozue, ko jih je odpuščal v njih šatore, blagoslovil');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 8, 'in jim govoril, rekoč: Vrnite se z mnogim blagom v svoje šatore, z jako mnogoštevilno živino, s srebrom, zlatom, bronom in z železom in z mnogimi oblačili; delite plen sovražnikov svojih s svojimi brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 9, 'In vrnili so se sinovi Rubenovi in sinovi Gadovi in polovica Manasejevega rodu, in ko so se odpravili od Izraelovih sinov iz Sila, ki je v deželi Kanaanski, so šli v Gileadsko pokrajino, v svojega posestva deželo, ki so jo bili posedli s poveljem Gospodovim po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 10, 'In ko pridejo v kraje pri Jordanu, ki so v deželi Kanaanski, zgrade ondi ob Jordanu oltar sinovi Rubenovi in Gadovi in polovica Manasejevega rodu, velik in očiten oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 11, 'In zaslišijo sinovi Izraelovi, da se govori: Glej, sinovi Rubenovi in sinovi Gadovi in polovica Manasejevega rodu so zgradili oltar na pročelju Kanaanske dežele, v krajih pri Jordanu, nasprotno Izraelovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 12, 'In ko so to slišali, se zbere vsa občina Izraelovih sinov v Silo, da bi šli zoper nje v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 13, 'In sinovi Izraelovi pošljejo k Rubenovim in Gadovim sinovom in k polovici Manasejevega rodu v Gileadsko pokrajino Pinehasa, sina Eleazarja duhovnika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 14, 'in ž njim deset knezov, po enega kneza očetovske hiše za vsak Izraelov rod; in vsak izmed njih je bil poglavar očetovske hiše med tisoči Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 15, 'In ko pridejo k Rubenovim in Gadovim sinovom in k polovici Manasejevega rodu v Gileadsko pokrajino, jih ogovore, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 16, 'Tako pravi vsa občina Gospodova: Kakšna je to nezvestoba, ki ste jo zagrešili proti Izraelovemu Bogu, ko ste se odvrnili danes, da ne bi hodili za Gospodom, in ste si zgradili oltar, upirajoč se danes Gospodu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 17, 'Majhna li nam je pregreha s Peorjem, ki se je nismo očistili do današnjega dne in zaradi katere je šiba zadela občino Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 18, 'da se odvračate danes, da ne bi šli za Gospodom? In zgodi se, ker se danes upirate Gospodu, da se bo jutri jezil nad vso občino Izraelovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 19, 'Ali če je dežela vašega posestva nečista, preidite v deželo posestva Gospodovega, kjer je prebivališče Gospodovo, in vzemite si last med nami; samo ne bodite uporni Gospodu in nam s tem, da si gradite oltar razen oltarja Gospoda, Boga našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 20, 'Ni li se pregrešil Ahan, sin Zerahov, z nezvestobo, ko je vzel od prokletega, in jeza Gospodova je prišla nad vso občino Izraelovo? In on ni poginil sam v svoji pregrehi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 21, 'Nato odgovore Rubenovi in Gadovi sinovi in polovica Manasejevega rodu ter reko poglavarjem tisoč Izraelovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 22, 'Bog bogov, Jehova, Bog bogov, Jehova, On ve, in tudi Izrael naj ve: Ako se je storilo v upornosti ali iz nezvestobe proti Gospodu, ne bodi nam v pomoč danes!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 23, 'Ako smo si zgradili oltar z namenom, da se odvrnemo ter ne bomo hodili za Gospodom, ali da bomo na njem darovali žgalne in jedilne daritve ali pokladali nanj mirovne žrtve, naj nas kaznuje zato Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 24, 'Marveč storili smo to v skrbi za dobro stvar, meneč: V prihodnjih časih bi lahko rekli otroci vaši našim otrokom: Kaj vam je do Gospoda, Boga Izraelovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 25, 'Saj je Gospod naredil Jordan v mejo med nami in vami, sinovi Rubenovi in sinovi Gadovi: nimate deleža v Gospodu! S tem bi vaši otroci odvrnili otroke naše od strahu Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 26, 'Zato smo rekli: Dejte, zgradimo si oltar, ne za žgalne žrtve, ne za klalne daritve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 27, 'ampak da bodi priča med nami in vami in za naše rodove za nami, da smemo opravljati Gospodu službo pred Njim s svojimi žgalnimi, klalnimi in mirovnimi žrtvami, ter da ne smejo vaši otroci reči našim otrokom v prihodnjih časih: Nimate deleža v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 28, 'Rekli smo torej: Ako nam tako poreko ali rodovom našim za nami v prihodnjih časih, bomo dejali: Glejte podobščino Gospodovega oltarja, ki so ga postavili očetje naši, ne za žgalno, ne za klalno daritev, ampak da bodi priča med nami in vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 29, 'Bog ne daj, da bi se uprli zoper Gospoda in se danes odvrnili, ne hoteč hoditi za Gospodom, da si zgradimo oltar za žgalno, jedilno in klalno daritev, razen oltarja Gospoda, Boga našega, ki je pred njegovim prebivališčem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 30, 'Ko so pa slišali Pinehas duhovnik in knezi občine, poglavarji tisoč Izraelovih, ki so bili ž njim, te besede, ki so jih govorili Rubenovi in Gadovi in Manasejevi sinovi, se jim je dobro videlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 31, 'In Pinehas, Eleazarjev sin, duhovnik, reče Rubenovim in Gadovim in Manasejevim sinovom: Danes spoznavamo, da je Gospod med nami, ker niste zagrešili te nezvestobe zoper Gospoda. Sedaj ste rešili Izraelove sinove roke Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 32, 'Tedaj se vrnejo Pinehas, sin Eleazarja duhovnika, in knezi od Rubenovih in Gadovih sinov iz Gileadske pokrajine v Kanaansko deželo k Izraelovim sinovom in jim prineso poročilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 33, 'In stvar se je dobra videla sinovom Izraelovim; in Izraelovi sinovi so hvalili Boga in niso več omenili, da pojdejo zoper nje v boj ugonabljat deželo, ki prebivajo v njej sinovi Rubenovi in sinovi gadovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 22, 34, 'In Rubenovi in Gadovi sinovi so imenovali oltar Priča, zakaj „on je priča med nami, da je Jehova Bog“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 1, 'In po mnogih dnevih, ko je bil dal Gospod pokoj Izraelu od vseh njegovih sovražnikov povsod okoli, in Jozue je bil že star in prileten,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 2, 'skliče Jozue vse Izraelce in njih starejšine, poglavarje, sodnike in oblastnike in jim reče: Star sem in prileten;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 3, 'vi pa ste videli vse, kar je storil Gospod, Bog vaš, vsem tem narodom spričo vas, zakaj Gospod, Bog vaš, on je, ki se je bojeval za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 4, 'Glejte, pridelil sem vam po žrebu te narode, kar jih je še ostalo, v dediščino vašim rodovom, od Jordana z vsemi narodi vred, ki sem jih iztrebil, do velikega morja proti solnčnemu zahodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 5, 'Gospod pa, vaš Bog, jih izpahne pred vami ter jih prežene izpred obličja vašega, in posedete njih deželo, kakor vam je obljubil Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 6, 'Bodite torej prav trdni, da hranite in izpolnjujete vse, kar je pisano v knjigi Mojzesovega zakona, da se od tega ne ganete ne na desno, ne na levo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 7, 'da ne pridete med te narode, med tiste, ki preostajajo med vami, in se ne spominjate imena njih bogov in ne prisegate pri njih, tudi jim ne služite in jih ne molite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 8, 'ampak oklepajte se Gospoda, Boga svojega, kakor ste delali do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 9, 'Zakaj Gospod je zatrl pred vami velike in mogočne narode, in kar se vas tiče, nihče ni mogel stati pred vami do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 10, 'Eden vaših jih lahko podi tisoč, kajti Gospod, Bog vaš, on je, ki se bojuje za vas, kakor vam je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 11, 'Zato skrbno čuvajte duše svoje, da ljubite Gospoda, svojega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 12, 'Sicer če kakorkoli pojdete nazaj in se oklenete ostanka teh narodov, tistih, ki so preostali med vami, in se boste ženili in možile ž njimi, da pridete med nje in oni med vas:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 13, 'vedite prav gotovo, da ne bo več Gospod, Bog vaš, zatiral teh narodov pred vami, temuč vam bodo v zanko in v zadrgo in kakor bič na bokih in trnje v očeh, dokler ne poginete s površja te dobre dežele, ki vam jo je dal Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 14, 'In glejte, jaz odhajam danes po poti vsega zemeljskega. Spoznajte torej z vsem svojim srcem in z vso dušo svojo, da ni izginila ne ena beseda iz vseh dobrih obljub, ki jih je za vas govoril Gospod, Bog vaš; vse se je uresničilo, ne ena beseda ni izginila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 15, 'Kakor pa se je izpolnila vsaka dobra beseda, ki jo je Gospod, vaš Bog, govoril za vas, tako stori Gospod, da se uresniči nad vami vsaka huda beseda, dokler vas ne iztrebi s površja te dobre zemlje, ki vam jo je dal Gospod, vaš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 23, 16, 'Ako prestopite zavezo Gospoda, Boga svojega, ki vam jo je zapovedal, in pojdete služit drugim bogovom in jih boste molili, tedaj se vname jeza Gospodova zoper vas, in hitro poginete s površja te dobre dežele, ki vam jo dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 1, 'In Jozue zbere vse Izraelove rodove v Sihemu in skliče starejšine Izraelove in poglavarje, sodnike in oblastnike njegove. In postavijo se pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 2, 'In Jozue reče vsemu ljudstvu: Tako pravi Gospod, Bog Izraelov: Vaši očetje so nekdaj prebivali onostran velereke, zlasti Terah, Abrahamov in Nahorjev oče, in služili drugim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 3, 'In vzel sem očeta vašega Abrahama z one strani velereke in sem ga vodil po vsej Kanaanski deželi ter pomnožil njegovo seme, ko sem mu dal Izaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 4, 'In Izaku sem dal Jakoba in Ezava, Ezavu pa sem dal Seirsko gorovje, da ga posede; a Jakob in njegovi sinovi so šli doli v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 5, 'In poslal sem Mojzesa in Arona, in bičal sem Egipt pri vsem, kar sem storil sredi njega, in potem sem vas izpeljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 6, 'Ko sem pa odpeljal vaše očete iz Egipta in ste prišli k morju, so se gnali Egipčani za vašimi očeti z vozovi in konjiki do Rdečega morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 7, 'In ko so zavpili h Gospodu, je postavil temo med vas in Egipčane in pripeljal morje čeznje, da jih je zagrnilo. In oči vaše so videle, kar sem storil v Egiptu. Potem ste bivali dosti časa v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 8, 'In privedel sem vas v deželo Amorejcev, ki so prebivali za Jordanom; in bojevali so se z vami, in dal sem vam jih v roke, in posedli ste njih deželo, in nje sem zatrl pred vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 9, 'Tedaj je vstal Balak, sin Ziporjev, kralj moabski, in se je bojeval z Izraelom; in je poslal ter poklical Balaama, sina Beorjevega, da vas prekolne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 10, 'A nisem hotel poslušati Balaama, zato vas je tembolj blagoslovil, in otel sem vas iz njegove roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 11, 'In ko ste šli čez Jordan in prišli do Jeriha, so se bojevali meščani iz Jeriha z vami, in Amorejci, Ferizejci, Kanaanci, Hetejci, Girgasejci, Hevejci in Jebusejci, in dal sem vam jih v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 12, 'In poslal sem sršene pred vami, ki so jih pregnali izpred vas, kakor dva kralja Amorejcev – ne z mečem tvojim, ne z lokom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 13, 'In dal sem vam deželo, ki je niste obdelovali, in mesta, ki jih niste zidali, in prebivate v njih in uživate od vinogradov in oljk, ki jih niste zasadili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 14, 'Zatorej se bojte zdaj Gospoda ter mu služite s popolno vdanostjo in v resnici, in odpravite bogove, ki so jim služili vaši očetje za velereko in v Egiptu, in služite Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 15, 'A če se vam zdi slabo služiti Gospodu, izberite si danes, komu boste služili: ali bogovom, ki so jim služili vaši očetje onostran velereke, ali bogovom Amorejcev, ki prebivate v njih deželi; jaz pa in moja hiša hočemo služiti Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 16, 'Nato odgovori ljudstvo in reče: Bog ne daj, da bi zapustili Gospoda in služili drugim bogovom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 17, 'Zakaj Gospod, Bog naš, je tisti, ki je nas in očete naše odpeljal iz Egiptovske dežele, iz hiše sužnosti, in je delal pred našimi očmi taka velika znamenja ter nas hranil po vsem potu, ki smo po njem šli, in med vsemi narodi, mimo katerih smo potovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 18, 'In Gospod je pred nami izpahnil vse narode, zlasti Amorejce, ki so prebivali v deželi. Tudi mi hočemo služiti Gospodu, zakaj on je naš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 19, 'Jozue reče ljudstvu: Vi ne morete služiti Gospodu, zakaj on je presveti Bog, goreči Bog; on ne bo prenašal prestopkov vaših in grehov vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 20, 'Ako zapustite Gospoda in boste služili tujim bogovom, se obrne on ter vam napravi hudo in vas pokonča, potem ko vam je dobro storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 21, 'Ljudstvo pa reče Jozuetu: Nikar, temuč Gospodu hočemo služiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 22, 'In Jozue reče ljudstvu: Priče ste zoper sebe, da ste si izvolili Gospoda, da mu boste služili. In reko: Da, priče smo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 23, 'Odpravite torej zdaj, veli, tuje bogove, ki so med vami, in nagnite srce svoje h Gospodu, Bogu Izraelovemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 24, 'In ljudstvo odgovori Jozuetu: Gospodu, Bogu svojemu, hočemo služiti in glas njegov poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 25, 'Tako je storil Jozue tisti dan zavezo z ljudstvom in mu je dal postavo in sodbo v Sihemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 26, 'In Jozue je napisal te besede v knjigo Božjega zakona, in vzame velik kamen in ga ondi postavi pod hrastom, ki je bil pri Gospodovem svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 27, 'In Jozue reče vsemu ljudstvu: Glej, ta kamen bodi priča zoper nas; kajti slišal je vse Gospodove besede, ki nam jih je govoril, zato bodi priča zoper vas, da ne zatajite Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 28, 'Potem razpusti Jozue ljudstvo, vsakega v dediščino njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 29, 'In zgodi se po teh rečeh, da umre Jozue, sin Nunov, hlapec Gospodov, ko je bil star sto in deset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 30, 'In pokopali so ga v kraju dediščine njegove, v Timnat-serahu, ki je v Efraimskem gorovju, severno ob gori Gaasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 31, 'In Izrael je služil Gospodu, dokler je živel Jozue in dokler so, še dosti časa za Jozuetom, živeli starejšine, ki so vedeli za vse Gospodovo delo, katero je storil za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 32, 'In Jožefove kosti, ki so jih prinesli sinovi Izraelovi iz Egipta, so pokopali v Sihemu na kosu zemljišča, ki ga je bil kupil Jakob od sinov Hemorja, očeta Sihemovega, za sto kesit, in tako so prišle v dediščino Jožefovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (6, 24, 33, 'Tudi Eleazar, sin Aronov, je umrl, in pokopali so ga v Gibei, ki je bila njegovega sinu Pinehasa, dana mu v Efraimskem gorovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 1, 'In zgodi se po smrti Jozuetovi, da vprašajo sinovi Izraelovi Gospoda in reko: Kdo izmed nas naj gre prvi proti Kanaancem, da se ž njimi vojskuje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 2, 'In Gospod veli: Juda naj gre! glej, dal sem deželo v roko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 3, 'Juda pa reče svojemu bratu Simeonu: Pojdi z menoj v moj delež, da se bojujemo s Kanaanci; in jaz tudi pojdem s teboj v tvoj delež. Šel je torej Simeon ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 4, 'In Juda se odpravi v boj, in Gospod je dal Kanaance in Ferizejce v njih roke, in pobili so jih v Bezeku deset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 5, 'In zasačijo Adonibezeka v Bezeku ter se ž njim bojujejo, in porazijo Kanaance in Ferizejce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 6, 'Adonibezek pa zbeži, in zasledujoč ga primejo in mu odsekajo palce na rokah in nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 7, 'Tedaj reče Adonibezek: Sedemdeset kraljev z odsekanimi palci na rokah in nogah je pobiralo hrano pod mojo mizo; kakor sem storil, tako mi je poplačal Bog. In ga pripeljejo v Jeruzalem, in ondi umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 8, 'Bojevali so se namreč sinovi Judovi zoper Jeruzalem ter ga dobili in jih pobili z ostrino meča in mesto zažgali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 9, 'Potem so šli sinovi Judovi doli bojevat se s Kanaanci, ki so prebivali na gorah in na jugu in v nižavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 10, 'Tudi je šel Juda zoper Kanaance, ki so prebivali v Hebronu (Hebron pa se je nekdaj imenoval Arbovo mesto); in pobili so Sesaja in Ahimana in Talmaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 11, 'In odtod je šel zoper prebivalce v Debirju. (Debir pa se je nekdaj imenoval Kirjat-sefer.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 12, 'In Kaleb reče: Kdor udari Kirjat-sefer in ga vzame, njemu dam svojo hčer Akso za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 13, 'In dobil ga je Otniel, sin Kenaza, ki je bil Kalebov mlajši brat. In dal mu je hčer svojo Akso za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 14, 'In zgodi se, ko je šla k njemu, da ga je izpodbujala, naj prosi njenega očeta njive. In spustila se je z osla; in Kaleb ji reče: Kaj ti je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 15, 'Ona mu reče: Daj mi blagoslov; kajti dal si mi južni kraj, daj mi tudi studence voda. In Kaleb ji je dal studence gornje in dolnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 16, 'In sinovi Kenejca, Mojzesovega svaka, so šli gori iz Palmovega mesta z Judovimi sinovi v Judejsko puščavo, ki je južno od Arada; in so šli in prebivali z ondotnim ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 17, 'Juda pa je šel s svojim bratom Simeonom, in udarijo Kanaance, ki so prebivali v Zefatu, in jih pokončajo s prokletjem. In imenovali so tisto mesto Hormo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 18, 'Juda je tudi dobil Gazo ž njeno pokrajino in Askelon ž njegovo pokrajino in Ekron ž njegovo pokrajino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 19, 'In Gospod je bil z Judo, da si je prilastil gorovje; zakaj prebivalcev v dolini ni mogel pregnati, ker so imeli železne vozove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 20, 'In dali so Kalebu Hebron, kakor je bil govoril Mojzes; on je izgnal odtod tri sinove Enakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 21, 'A Benjaminovi sinovi niso pregnali Jebusejcev, ki so prebivali v Jeruzalemu, ampak Jebusejci so bivali z Benjaminovimi sinovi do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 22, 'Enako je šla tudi Jožefova hiša gori zoper Betel, in Gospod je bil ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 23, 'In Jožefova hiša pošlje ogledovat Betel; prej se je pa mesto imenovalo Luz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 24, 'In ogledovalci vidijo moža, gredočega iz mesta, pa mu reko: Pokaži nam, prosimo, kod pridemo v mesto, in izkažemo ti milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 25, 'In pokaže jim vhod v mesto, in oni udarijo mesto z ostrino meča; tistega moža in vso rodovino njegovo pa izpustijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 26, 'Mož pa gre v deželo Hetejcev in sezida mesto ter ga imenuje Luz; tako mu je ime do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 27, 'Manase pa ni pregnal prebivalcev v Betseanu in po njegovih podložnih vaseh, tudi ne v Taanahu in po njegovih podložnih vaseh, ne prebivalcev v Doru in po njegovih podložnih vaseh, ne prebivalcev v Ibleamu in po njegovih podložnih vaseh, ne prebivalcev v Megidu in po njegovih podložnih vaseh; in Kanaancem se je zljubilo ostati v tisti deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 28, 'Ko pa se je ojačil Izrael, je podvrgel Kanaance davku, a ni jih dočista pregnal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 29, 'Tudi Efraim ni pregnal Kanaancev, ki so prebivali v Gezerju; in Kanaanci so prebivali v Gezerju med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 30, 'Zebulon ni pregnal prebivalcev v Kitronu, ne prebivalcev v Nahalolu, in Kanaanci so prebivali med njimi, davku podvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 31, 'Aser ni pregnal prebivalcev v Aku, ne prebivalcev v Sidonu, v Ahlabu, v Akzibu, v Helbi, v Afiku, ne v Rehobu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 32, 'temuč Aserjevci so prebivali med Kanaanci, ki so ostali v deželi; kajti niso jih izgnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 33, 'Neftali ni pregnal prebivalcev v Betsemesu, ne prebivalcev v Betanatu, temuč prebival je med Kanaanci, ki so ostali v deželi; toda prebivalci v Betsemesu in v Betanatu so jim plačevali davek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 34, 'Amorejci pa so spodili Danove sinove v gorovje in jih niso pustili, da bi šli doli v ravnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 35, 'In Amorejcem se je zljubilo ostati na gori Heresu, v Ajalonu in v Saalbimu; vendar pa jim je postala roka Jožefove hiše pretežka, in bili so davku podvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 1, 36, 'In meja Amorejcev je šla od vzviška Akrabima, od Sele dalje gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 1, 'Angel Gospodov pa pride od Gilgala gori do Bohima in reče: Jaz sem storil, da ste šli iz Egipta, in sem vas pripeljal v deželo, ki sem jo s prisego obljubil očetom vašim; in rekel sem: Vekomaj ne prelomim zaveze svoje z vami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 2, 'vi pa ne sklenite nobene zaveze s prebivalci te dežele, njih oltarje pa razrušite. Ali niste poslušali glasu mojega. Zakaj ste tako ravnali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 3, 'Zategadelj sem tudi rekel: Ne preženem jih izpred vas, temuč naj vam bodo kakor trnje v bokih, in njih bogovi naj vam bodo v zanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 4, 'In ko je angel Gospodov izgovoril te besede vsem sinovom Izraelovim, je ljudstvo zavpilo na ves glas in jokalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 5, 'In imenovali so ime tistega kraja Bohim; in ondi, so darovali Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 6, 'Ko je bil namreč Jozue razpustil ljudstvo, je šel vsak Izraelovih sinov v dediščino svojo, da posedejo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 7, 'In ljudstvo je služilo Gospodu, dokler je živel Jozue in starejšine, ki so še po Jozuetu živeli, ki so bili videli vse veliko delo Gospodovo, ki ga je storil za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 8, 'In ko je Jozue, sin Nunov, hlapec Gospodov, umrl v starosti sto in desetih let,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 9, 'so ga pokopali v kraju dediščine njegove v Timnat-heresu, v gorovju Efraimskem, severno ob gori Gaasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 10, 'In ko je tudi ves ta rod bil zbran k očetom svojim, je po njem nastopil drug rod, ki ni poznal Gospoda, ne del njegovih, ki jih je bil storil za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 11, 'In sinovi Izraelovi so počenjali, kar je bilo hudo v očeh Gospodovih, in služili so Baalom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 12, 'in zapustivši Gospoda, Boga očetov svojih, ki jih je bil odpeljal iz Egipta, so hodili za drugimi bogovi, za bogovi sosednjih ljudstev, in se jim poklanjali in dražili Gospoda v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 13, 'In zapustili so Gospoda in služili Baalu in Astarotam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 14, 'Tedaj se vname jeza Gospodova zoper Izraela, in dal jih je v roke roparjem, ki so jih oplenjevali, in jih prodal v njih sovražnikov roke vseokoli, da se niso mogli več vzdržati pred sovražniki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 15, 'Kamorkoli so šli, roka Gospodova je bila zoper nje v hudo, kakor je bil Gospod govoril in kakor jim je bil prisegel Gospod. In bili so bridko stiskani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 16, 'A Gospod jim je obujal sodnike, ki so jih otimali iz rok tistih roparjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 17, 'Ali tudi sodnikov svojih niso poslušali, temuč nečistovali so za drugimi bogovi in jih molili, hitro odstopivši s pota, po katerem so hodili njih očetje, poslušajoč zapovedi Gospodove. Oni niso tako delali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 18, 'In ko jim je Gospod obujal sodnike, je bil Gospod s sodniki ter jih reševal iz rok njih sovražnikov, dokler je živel sodnik; zakaj Gospodu se je smililo zaradi njih jokanja spričo tistih, ki so jih stiskali in mučili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 19, 'Ko pa je umrl sodnik, so se spet vrnili ter so huje ravnali nego njih očetje, hodeč za drugimi bogovi, da bi jim služili in jih molili; nič niso popustili od dejanj svojih in svojega trdovratnega vedenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 20, 'Zato se je vnel srd Gospodov zoper Izraela, in je rekel: Ker je to ljudstvo prestopilo zavezo mojo, ki sem jo bil zapovedal njih očetom, in ne posluša glasu mojega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 21, 'zato tudi jaz ne preženem nikogar več iz tistih narodov, ki so preostali ob Jozuetovi smrti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 22, 'da po njih izkusim Izraela, če se bodo držali pota Gospodovega, hodeč po njem, kakor so se ga držali njih očetje, ali če ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 2, 23, 'Zato je vzdržal Gospod tiste narode in jih ni pregnal v kratkem, tudi jih ni dal v roko Jozuetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 1, 'Ti pa so narodi, ki jih je vzdržal Gospod, da po njih izkusi Izraela, vse, ki niso poznali vseh vojen kanaanskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 2, 'samo da jih spoznajo prihodnji rodovi Izraelovih sinov in se nauče vojske, vsaj tisti, ki niso nič tega prej spoznali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 3, 'pet knezov Filistejcev in vse Kanaance in Sidonce in Hevejce, ki so prebivali na Libanonskem gorovju, od gore Baal-hermona do tja, kjer je vhod v Hamat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 4, 'Ti so ostali, da se izkusi Izrael in da se spozna, ali bodo poslušali Gospodove zapovedi, ki jih je zapovedal njih očetom po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 5, 'In sinovi Izraelovi so stanovali med Kanaanci, Hetejci, Amorejci, Ferizejci, Hevejci in Jebusejci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 6, 'in so si jemali njih hčere za žene ter dajali hčere svoje njih sinovom in služili njih bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 7, 'In delali so Izraelovi sinovi, kar je bilo zlo Gospodovim očem, in so, pozabivši Gospoda, Boga svojega, služili Baalom in Ašeram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 8, 'Zato se je razvnela jeza Gospodova zoper Izraela, in prodal jih je v roko Kušan-rišataima, kralja v Mezopotamiji; in sinovi Izraelovi so služili Kušan-rišataimu osem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 9, 'In ko so Izraelovi sinovi vpili h Gospodu, jim je obudil rešitelja, ki jih je rešil, Otniela, sina Kenaza, Kalebovega mlajšega brata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 10, 'In duh Gospodov je prišel nadenj, in sodil je Izraela; in odpravil se je v boj, in Gospod mu je dal v roko Kušan-rišataima, kralja v Mezopotamiji; in roka njegova je bila premočna Kušan-rišataimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 11, 'In dežela je imela pokoj štirideset let. In ko je umrl Otniel, sin Kenazov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 12, 'so Izraelovi sinovi zopet delali, kar je bilo hudo v očeh Gospodovih. In Gospod je ojačil Eglona, kralja Moabcev, zoper Izraela, zato ker so počenjali, kar je bilo hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 13, 'In zbral je k sebi Amonove sinove in Amalekovce, in gre ter udari Izraela in vzame Palmovo mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 14, 'In Izraelovi sinovi so služili Eglonu, moabskemu kralju, osemnajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 15, 'Ali ko so vpili sinovi Izraelovi h Gospodu, jim je obudil Gospod rešitelja, Ehuda, Gerajevega sina, Benjaminca, čigar desna roka je bila hroma. In sinovi Izraelovi so poslali po njem darilo Eglonu, kralju Moabcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 16, 'Tedaj si je Ehud naredil dvorezen meč majhen komolec dolg, in si ga je pripasal pod obleko ob desnem bedru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 17, 'In tako prinese darilo Eglonu, moabskemu kralju. Bil pa je Eglon silno debel mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 18, 'In ko izroči darilo, odpošlje ljudi, ki so nosili darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 19, 'Sam pa se vrne od kamenoloma pri Gilgalu in reče: Imam ti, o kralj, nekaj skrivnega povedati. On pa veli: Molči! In vsi, ki so stali pri njem, gredo ven od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 20, 'In Ehud vstopi k njemu; on pa je sedel v gornji hladilni sobi, ki mu je bila zasebna. In Ehud reče: Besedo Božjo imam zate. In vstane s svojega stola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 21, 'Ehud pa iztegne levo roko ter potegne meč s svojega desnega bedra in mu ga sune v trebuh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 22, 'da šine tudi držaj za rezilom vanj; in tolstina zadrži rezilo, ker mu ni potegnil meča iz trebuha, in ost pogleda zadaj ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 23, 'Nato gre Ehud ven v vežo in zapre vrata gornje sobe za seboj in jih zapahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 24, 'Ko pa je bil zunaj, pridejo služabniki in pogledajo, in glej, vrata so zapahnjena; in reko: Gotovo je v hladilni izbi pri svoji potrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 25, 'In čakajo tako dolgo, da se že sramujejo, in glej, on ne odpre sobnih vrat; tedaj vzamejo ključ in odklenejo, in glej, njih gospod leži na tleh, mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 26, 'Ehud pa je ušel medtem, ko so se oni mudili, in gredoč mimo kamenoloma beži do Seire.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 27, 'In ko pride tja, zatrobi na trobento na Efraimskem gorovju, in Izraelovi sinovi stopijo ž njim doli z gorovja in on jim gre na čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 28, 'In jim veli: Pojdite za menoj, kajti Gospod vam je dal v roko sovražnike vaše, Moabce. In gredo doli za njim, in vzamejo Moabcem jordanske brodove, in ne puste nikogar čez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 29, 'In pobijejo tisti čas Moabcev okoli deset tisoč mož, vse dobro rejene in junaške može, da ni eden ušel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 30, 'Tako je bil tisti čas Moab potlačen pod roko Izraelovo. In dežela je imela pokoj osemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 3, 31, 'In po njem je bil Samgar, sin Anatov, ki je pobil šeststo Filistejcev z volovskim ostnom; in tudi on je rešil Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 1, 'In sinovi Izraelovi so zopet delali, kar je bilo zlo v očeh Gospodovih, ko je bil Ehud umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 2, 'In Gospod jih je prodal v roko Jabina, kralja Kanaancev, ki je kraljeval v Hazorju, in vojski njegovi poveljnik je bil Sisera, ki je stanoval v Harosetu poganskem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 3, 'In sinovi Izraelovi so vpili h Gospodu; kajti on je imel devetsto železnih voz in hudo jih je stiskal dvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 4, 'In Debora, prorokinja, žena Lapidotova, je v tem času sodila Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 5, 'In sedevala je pod palmovim drevesom Debore med Ramo in Betelom v Efraimskem gorovju, in sinovi Izraelovi so hodili gori k njej s svojimi pravdami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 6, 'Ta pošlje in pokliče Baraka, sina Abinoamovega iz Kedes-neftalima, in mu reče: Ali ni zapovedal Gospod, Bog Izraelov: Pojdi in stopi na goro Tabor in vzemi s seboj deset tisoč mož iz Neftalijevih in Zebulonovih sinov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 7, 'Kajti jaz ti hočem pripeljati k potoku Kisonu Sisera, poveljnika Jabinove vojske, ž njegovimi vozovi in ž njegovo množico, in dam ti ga v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 8, 'In Barak ji reče: Ako greš z mano, pojdem, ako pa ne greš z mano, ne pojdem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 9, 'Ona reče: Seveda pojdem s teboj, toda pot, na katero greš, ne bode v tvojo čast, kajti v roko žene izda Gospod Sisera. In Debora vstane in gre z Barakom v Kedes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 10, 'Tedaj skliče Barak Zebulona in Neftalija v Kedes, in gre gori peš z deset tisoč možmi; tudi Debora ga spremlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 11, 'Heber pa, Kenejec, se je bil ločil od Kenejskih, od sinov Hobaba, Mojzesovega svaka, in je postavil svoje šatore tja do hrasta v Zaananimu, ki je poleg Kedesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 12, 'In sporoči se Siseru, da je šel Barak, sin Abinoamov, na goro Tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 13, 'In Sisera zbere vse vozove svoje, devetsto železnih voz, in vse ljudstvo, ki je bilo pri njem, od Haroseta poganskega k potoku Kisonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 14, 'Debora pa reče Baraku: Vstani, kajti to je dan, v katerem ti je dal Gospod Sisera v roko; ni li šel Gospod pred teboj? Tedaj stopi Barak doli z gore Tabora in deset tisoč mož za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 15, 'In Gospod je spravil v zmešnjavo Sisera in vse vozove njegove in vso vojsko njegovo z ostrino meča pred Barakom, tako da skoči Sisera s svojega voza in beži peš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 16, 'Barak pa tira vozove in vojsko do Haroseta poganskega, in vsa vojska Siserova pade z ostrino meča; ni ostalo enega moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 17, 'Sisera pa je bežal peš v šator Jaele, žene Heberja, Kenejca; kajti mir je bil med Jabinom, kraljem v Hazorju, in hišo Heberja Kenejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 18, 'In Jaela gre ven Siseru naproti ter mu reče: Stópi noter, gospod moj, stopi noter k meni in se ne boj! In stopi noter k njej v šator, in ona ga pokrije z odejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 19, 'On pa ji reče: Daj mi, prosim, malo vode piti, žejen sem. Ona odveže meh z mlekom in mu da piti in ga pokrije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 20, 'In on ji veli: Stoj ob vhodu v šator, in ako kdo pride in te vpraša, je li kdo tukaj, mu reci: Ni nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 21, 'Tedaj vzame Jaela, Heberjeva žena, klin od šatora in kladivo v roko in gre tiho noter k njemu ter mu zabije klin skozi sence, da predere do zemlje. Kajti utrujen je trdo zaspal, in tako je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 22, 'In glej, Barak se žene za Siserom; in Jaela mu pride naproti ter mu reče: Pojdi sem, jaz ti pokažem moža, ki ga iščeš. In stopi noter za njo, in glej, Sisera leži tu mrtev, in klin tiči v sencih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 23, 'Tako je Bog tisti dan potlačil Jabina, kralja Kanaancev, pred Izraelovimi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 4, 24, 'In roka Izraelovih sinov je bolj in bolj pritiskala na Jabina, kralja Kanaancev, dokler ga niso zatrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 1, 'In pela sta Debora in Barak, sin Abinoamov, tisti dan, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 2, 'Hvalite Gospoda, da so se vodniki postavili na čelo v Izraelu, da je šlo ljudstvo radovoljno v boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 3, 'Poslušajte, o kralji, nagnite uho, o knezi: jaz, jaz hočem peti Gospodu, hvalo čem citrati Gospodu, Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 4, 'O Gospod, ko si šel iz Seira, ko si stopal s poljane Edomske, stresla se je zemlja in nebesa so se rosila, da, oblaki so rosili vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 5, 'Gore so se raztapljale spričo Gospoda, Sinaj ondi se je topil pred obličjem Gospoda, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 6, 'V dnevih Samgarja, Anatovega sina, v dnevih Jaela so bile prazne ceste, in popotnikom, vajenim gladkih potov, je bilo hoditi po krivih stezah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 7, 'Ni bilo voditeljev v Izraelu, ni jih bilo, dokler nisem vstala jaz, Debora, dokler nisem, vstala, mati v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 8, 'Izvolil si je novih bogov Izrael; tedaj je bila vojna pred njih vrati, in ščita in sulice ni bilo videti med štiridesetimi tisoči v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 9, 'Srce moje je vdano voditeljem Izraelovim, radovoljnim med ljudstvom: Hvalite Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 10, 'Premišljajte to vi, ki jezdite na belih oslicah, ki sedite na lepih preprogah, in vi, ki greste po poti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 11, 'Daleč od vpitja strelcev, kjer se zajemlje voda, tam slavé pravična dejanja Gospodova, pravična dejanja njegovega vodstva v Izraelu. Tedaj je doli k vratom šlo ljudstvo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 12, 'Zbudi se, zbudi, Debora, zbudi se, zbudi, zapoj pesem; vstani, Barak, v ujetništvo pelji ujete svoje, sin Abinoamov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 13, 'Tedaj je stopil doli ostanek plemenitnikov in ljudstva; Gospod je zame prišel doli med mogočnimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 14, 'Iz Efraima so prišli tisti, ki je njih korenina v Amaleku, za teboj, Benjamin, med tvojimi ljudstvi; iz Mahirja so prišli voditelji, in iz Zebulona tisti, ki imajo v rokah vojskovodjevo palico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 15, 'a knezi Isaharjevi so bili z Deboro, in Isahar je bil enak Baraku; v dolino se je drevil, njemu za petami. Pri Rubenovih potokih so bili veliki sklepi srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 16, 'Zakaj si sedel med ograjami, da poslušaš piskanje pri čredah? Ob Rubenovih potokih so bile velike presoje srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 17, 'Gilead je ostal pokojno onostran Jordana, in zakaj se je Dan mudil pri ladjah? Aser je sedel na morskem obrežju in ostal pri svojih zatokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 18, 'Zebulon je ljudstvo, ki je žrtvovalo življenje svoje do smrti, tudi Neftali na visočinah poljan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 19, 'Kralji so prišli in se bojevali; takrat so se bojevali kralji Kanaancev v Taanahu pri Megidskih vodah: nič srebra niso dobili v plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 20, 'Z neba se je vojskovalo – zvezde so se raz svoje tire vojskovale zoper Sisera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 21, 'Potok Kison jih je odplavil, tisti potok od nekdaj imeniten, potok Kison. – O duša moja, krepko stopaj naprej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 22, 'Tedaj so topotala kopita konj, ker so jih v dir gonili, gonili njih junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 23, 'Preklinjajte Meroz, je dejal angel Gospodov, hudo preklinjajte prebivalce njegove, ker niso prišli Gospodu na pomoč, na pomoč Gospodu med junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 24, 'Blagoslovljena med ženami bodi Jaela, žena Heberja Kenejskega, blagoslovljena bodi med ženami v šatoru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 25, 'Prosil je vode, da mu mleka, v gosposki skledici mu prinese smetane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 26, 'Iztegne roko svojo po klinu in desnico po težkem kladivu, in udari s kladivom Sisera, mu prebije glavo, stare in predere sence njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 27, 'Pri nogah njenih se zvije, pade, obleži, pri nogah njenih se zvije in zgrudi; kjer se je zvil, tam je obležal mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 28, 'Skozi okno je gledala mati Siserova in vpila žalostna skozi omrežje: Zakaj se tako dolgo ne pelje voz njegov? Zakaj so tako počasna kolesa voz njegovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 29, 'Modre med njenimi kneginjami ji odgovarjajo, tudi ona si ponavlja odgovor svoj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 30, 'Niso li dobili, ne delijo li plena? ene ali dveh devojk za vsakega moža? Plen pisanega blaga za Sisera, plen pisanih umetnih tkanin, pisane in umetne tkanine za grlo gospe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 5, 31, 'Tako naj poginejo vsi sovražniki tvoji, o Gospod! a kateri ga ljubijo, naj bodo kakor solnce, ko vzhaja v moči svoji! In dežela je imela pokoj štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 1, 'In Izraelovi sinovi so delali, kar je bilo zlo v očeh Gospodovih. In Gospod jih je dal v pest Madiancem sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 2, 'In roka Madianova je hudo pritiskala na Izraela; iz strahu pred Madianci so si napravili tiste brloge, ki so na gorah, in jame in trdnjave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 3, 'In bilo je, ko so Izraelci kaj posejali, da so prišli Madianci in Amalekovci in Jutrovci; prišli so gori zoper nje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 4, 'in so se utaborili proti njim in pokončali pridelke zemeljske povsod tja do Gaze in niso pustili nič živil v Izraelu, ne ovce, ne vola, ne osla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 5, 'Kajti prišli so gori s svojo živino in s svojimi šatori, prišla jih je množica kakor roj kobilic; ne njih, ne njih velblodov ni bilo sešteti, in prišli so, da opustošijo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 6, 'In Izrael je silno obubožal zaradi Madiancev; in vpili so sinovi Izraelovi h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 7, 'In ko so vpili sinovi Izraelovi h Gospodu zavoljo Madiana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 8, 'pošlje Gospod proroka k Izraelovim sinovom. Ta jim reče: Tako pravi Gospod, Bog Izraelov: Jaz sem vas peljal gori iz Egipta in vas odvedel iz hiše sužnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 9, 'in sem vas otel Egipčanom iz roke in iz pesti vseh, ki so vas stiskali, in sem jih pregnal izpred vas ter vam dal njih deželo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 10, 'in dejal sem vam: Jaz sem Gospod, Bog vaš; ne bojte se bogov Amorejcev, ki prebivate v njih deželi. Ali niste poslušali glasu mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 11, 'In angel Gospodov pride ter sede pod hrast v Ofri, ki je bil Joasa Abiezrita; in sin njegov Gideon je otepal pšenico v tlačilnici, da bi ž njo bežal izpred Madiancev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 12, 'In prikaže se mu angel Gospodov in mu reče: Gospod s teboj, ti močni junak!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 13, 'Gideon pa mu reče: Ah, gospod moj, ako je Gospod z nami, zakaj nas je zadelo vse to? in kje so vsa čudežna dela njegova, ki so nam jih pripovedovali očetje naši, govoreč: Ni li nas Gospod odpeljal iz Egipta? A sedaj nas je Gospod zavrgel in dal Madiancem v pest!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 14, 'In Gospod se obrne do njega ter veli: Pojdi v tej moči svoji in reši Izraela Madianove roke! Nisem li te jaz poslal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 15, 'On pa mu reče: Ah, Gospod, s čim naj rešim Izraela? Glej, sorodništvo moje je najbolj siromašno v Manaseju in jaz sem najmanjši v očeta svojega hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 16, 'A Gospod mu reče: Resnično bodem s tabo, in pobiješ Madiance kakor enega moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 17, 'In on mu reče: Ako sem našel milost v tvojih očeh, prosim, daj mi znamenje, da si ti, ki govoriš z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 18, 'Ne umakni se odtod, prosim, dokler ne pridem k tebi in ne prinesem darila svojega in ga postavim pred tebe. On reče: Ostanem, dokler se ne vrneš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 19, 'In Gideon gre noter in pripravi kozliča in iz efe moke opresnih kruhov; in dene meso v jerbašček in vlije juho v lonec ter mu prinese ven pod hrast in postavi predenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 20, 'Angel Božji pa mu reče: Vzemi meso in opresne kruhe in položi na skalo tukaj in na vrh izlij juho! In stori tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 21, 'Tedaj iztegne angel Gospodov konec palice, ki jo je imel v roki, in se dotakne mesa in opresnikov, in ogenj pride iz skale in požre meso in opresnike. In angel Gospodov izgine izpred njegovih oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 22, 'In Gideon vidi, da je bil angel Gospodov, in reče: Gorje mi, Gospod Jehova, ker sem videl angela Gospodovega iz obličja v obličje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 23, 'A Gospod mu veli: Mir ti! ne boj se, ne umrješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 24, 'Tedaj zgradi Gideon ondi oltar Gospodu in ga imenuje Jehova šalom; ta je še do dandanes v Ofri Abiezritov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 25, 'In zgodi se isto noč, da mu reče Gospod: Vzemi junca očeta svojega, tistega drugega junca, sedem let starega, in poderi Baalov oltar, ki ga ima tvoj oče, in posekaj Ašero, ki je nad njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 26, 'ter zgradi Gospodu, Bogu svojemu, na vrhu te trdnjave oltar, prav po redu; in vzemi tistega drugega junca in ga daruj v žgalščino z drevjem Ašere, ki jo posekaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 27, 'Nato vzame Gideon deset mož izmed svojih hlapcev in stori, kakor mu je velel Gospod; a boječ se storiti to po dne zaradi očeta svojega družine in ljudi v mestu, je storil to po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 28, 'Ko pa ljudje iz mesta zarana vstanejo, glej, oltar Baalov je podrt in Ašera nad njim posekana, in tisti drugi junec je darovan na novozgrajenem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 29, 'In rečejo drug drugemu: Kdo je to naredil? In poizvedujejo in vprašajo, pa reko: Gideon, sin Joasov, je to storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 30, 'Tedaj reko možje iz mesta Joasu: Pripelji sem sina svojega, da umrje, kajti podrl je oltar Baalov in Ašero nad njim je posekal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 31, 'Joas pa reče vsem, ki so vstali zoper njega: Se li vi hočete pravdati za Baala? hočete ga li vi rešiti? Kdor bi se zanj potegoval, naj umrje še to jutro! Ako je bog, naj se pravda sam zase, ker mu je zrušil oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 32, 'Zato ga je od tega dne imenoval Jerub-baal, rekoč: Pravdaj se, Baal, zoper njega, ker ti je podrl oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 33, 'Tedaj se zbero vsi Madianci in Amalekovci in Jutrovci in preidejo Jordan in se utabore v Jezreelski dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 34, 'In duh Gospodov obleče v moč Gideona; in zatrobi na trobento, in zbero se k njemu Abiezriti, da bi šli za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 35, 'In pošlje sle po vsem Manaseju, in tudi od tega se jih zbere, da bi šli za njim; in pošlje sle k Aserju, Zebulonu in Neftaliju, in pridejo jim naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 36, 'In Gideon reče Bogu: Ako hočeš rešiti Izraela po moji roki, kakor si govoril,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 37, 'glej, položim runo na gumno: ako bode rosa le na samem runu, po vsej zemlji pa suho, tedaj spoznam, da rešiš Izraela po moji roki, kakor si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 38, 'In bilo je tako. Ko je namreč vstal zgodaj zjutraj, izžme runo in iztlači rose iz runa polno kupo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 39, 'In Gideon reče Bogu: Ne vname naj se jeza tvoja zoper mene, in govoril bom še enkrat: naj poskusim, prosim, samo še enkrat z runom: bodi zdaj suho samo na runu, a rosno po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 6, 40, 'In Bog je storil tako tisto noč: kajti bilo je suho samo na runu, a po vsej zemlji rosno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 1, 'Nato vstane zgodaj Jerub-baal, ki je Gideon, in vse ljudstvo, ki je bilo ž njim, in utabore se pri studencu Harodu; tabor Madiancev pa jim je bil na severni strani, pri Morejevem hribu v dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 2, 'Gospod pa reče Gideonu: Preveliko je ljudstva, ki je s teboj, da bi dal Madiana v njih roke, ker bi se Izrael hvalil zoper mene, govoreč: Moja roka me je rešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 3, 'Zatorej razglasi sedaj, da sliši ljudstvo, in véli: Kdor se boji in trepeta, obrni se in pojdi nazaj z Gileadskega gorovja. In vrnilo se je ljudstva dvaindvajset tisoč, deset tisoč pa jih je ostalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 4, 'In Gospod reče Gideonu: Še je preveč ljudstva. Pelji jih doli k vodi, in ondi jih izkusim zate, in za kogar ti porečem, da naj gre s teboj, pojde s teboj; in za kogarkoli ti porečem, naj ne hodi s teboj, ne pojde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 5, 'In pelje ljudstvo doli k vodi. In Gospod reče Gideonu: Vsakega, ki bo lokal z jezikom vodo, kakor pes loče, postavi posebej; enako tudi vsakega, ki se spusti na kolena, da pije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 6, 'In bilo je število tistih, ki so lokali, vodo noseč z roko k ustom, tristo mož; vse drugo ljudstvo pa se je spustilo na kolena, da pije vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 7, 'In Gospod reče Gideonu: Po tistih tristo možeh, ki so lokali, vas rešim in dam Madiance v roko tvojo; naj se torej razide ljudstvo, vsak v kraj svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 8, 'In vzemo živeža za ljudstvo s seboj in trobente svoje; a vse druge može Izraelove pošlje vsakega v njegov šator, pri sebi pa obdrži le tristo mož. Tabor Madiancev pa mu je bil spodaj v dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 9, 'In zgodi se tisto noč, da mu reče Gospod: Vstani, pojdi doli v tabor! zakaj dal sem ti ga v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 10, 'Ako pa se bojiš iti doli, naj gre s teboj tvoj hlapec Pura doli k taboru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 11, 'in slišal boš, kaj govore. Potem se ti ojačijo roke, da se zaženeš doli v tabor. Tedaj je stopil s svojim dečkom Purom doli k prednji straži, ki je bila ob taborišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 12, 'A Madianci in Amalekovci in vsi Jutrovci so bili pridrli v dolino kakor množica kobilic, in njih velblodov ni bilo sešteti, bilo jih je kakor peska ob morskem bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 13, 'In ko pride Gideon, glej, mož pripoveduje tovarišu svojemu sanje in pravi: Glej, imel sem sanje: videl sem, da se vali hlebec ječmenovega kruha k šatorišču Madiancev, in ko pride do šatora, butne vanj, da pade in se ves prevrne, in šator je bil podrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 14, 'In tovariš mu odgovori in reče: To ni nič drugega nego meč Gideona, Joasovega sina, izraelskega moža: njemu v roko je Bog dal Madiana in vso vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 15, 'In ko Gideon sliši, kako oni pripoveduje sanje in mu jih ta razloži, se prikloni Bogu; in vrne se v tabor Izraelov in veli: Vstanite! zakaj Gospod nam je dal v roko vojsko Madianskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 16, 'Nato razdeli tristo mož v tri krdela in da vsakemu trobento v roko in prazne vrče in bakle notri v vrčih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 17, 'ter jim reče: Glejte name in me posnemajte! glejte, ko pridem na kraj tabora, kar storim, storite tudi vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 18, 'Ko zatrobim na trobento in vsi, ki bodo pri meni, trobite tudi vi na trobente povsod okoli tabora in kličite: Za Gospoda in Gideona!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 19, 'Ko pride torej Gideon in sto mož, ki so bili pri njem, na kraj tabora, ob začetku opolnočne straže, ko so ravnokar postavili stražo, zatrobijo na trobente in razbijejo tiste vrče v svojih rokah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 20, 'In vsa tri krdela zatrobijo na trobente in razbijejo vrče, in drže prižgane bakle v levici, trobente pa v desnici, trobijo in kriče: Meč za Gospoda in za Gideona!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 21, 'In sleherni obstane na svojem mestu okoli tabora. In vsa vojska začne tekati, in vpijejo ter beže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 22, 'In onih tristo trobi na trobente, in Gospod obrne vsakega meč zoper njegovega tovariša, in to po vsem taboru. In vojska beži tja do Betsite, proti Zereri, tja do meje Abel-mehole pri Tabatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 23, 'In zbero se možje Izraelovi iz Neftalija in iz Aserja in iz Manaseja in pode Madiance.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 24, 'In Gideon pošlje sle po vsem Efraimskem gorovju in sporoči: Pridite doli, Madiancem nasproti, in obsedite pred njimi vodo tja do Betbare in tudi Jordan. In zbero se vsi efraimski možje in obsedejo vodo do Betbare in tudi Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 7, 25, 'In ujamejo dva madianska kneza, Oreba in Zeba, in umorijo Oreba na skali Orebovi in Zeba pri tlačilnici Zebovi; in podijo Madiance, in prineso glavi Oreba in Zeba Gideonu čez Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 1, 'A efraimski možje mu reko: Zakaj si nam to storil, da nas nisi poklical, ko si šel v boj zoper Madiana? In ostro so se besedili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 2, 'On pa jim reče: Kaj sem storil sedaj jaz in kaj vi! Ni li pobirek Efraimov boljši nego vsa trgatev Abiezerjeva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 3, 'Vam je dal Bog v roko madianska kneza, Oreba in Zeba, in sem li mogel storiti kaj takega kakor vi? In pomiril se je njih srd do njega, ko jim je tako govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 4, 'In Gideon dospe k Jordanu in ga preide s tristo možmi, ki so bili pri njem, in čeprav trudni, so vendar podili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 5, 'In reče možem v Sukotu: Dajte, prosim, ljudstvu, ki gre za menoj, nekoliko hlebov kruha, zakaj trudno je, in jaz se ženem za Zebahom in Zalmunom, kraljema Madiancev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 6, 'A sukotski plemenitaši reko: Je li mar pest Zebahova in Zalmunova že v roki tvoji, da bi dali vojski tvoji kruha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 7, 'Gideon reče: Dobro, ko mi da Gospod Zebaha in Zalmuna v roko, zmlatim vaše meso s trnjem iz puščave in z bodljikovjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 8, 'In pride gori v Penuel in jim govori enako; in možje v Penuelu mu odgovore, kakor so mu odgovorili Sukočani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 9, 'In tudi možem v Penuelu reče: Ko se vrnem v miru, razrušim ta stolp.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 10, 'Zebah in Zalmuna sta bila v Karkorju in njiju vojska ž njima, okoli petnajst tisoč mož, kar jih je preostalo od vse vojske Jutrovcev; kajti sto in dvajset tisoč jih je padlo, oboroženih z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 11, 'In Gideon je šel gori po poti tistih, ki stanujejo v šatorih, proti jutru ob Nobahu in Jogbehi, in udari vojsko, kajti bila je brezskrbna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 12, 'In Zebah in Zalmuna sta bežala, in ju je podil; in ujel je ta dva kralja Madiancev, Zebaha in Zalmuna, in razplašil je vso vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 13, 'In vrne se Gideon, sin Joasov, iz bitke od višine Heresa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 14, 'In zasači dečka izmed sukotskih mož in ga izpraša; in ta mu popiše sukotske plemenitaše in njih starejšine, sedeminsedemdeset mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 15, 'In pride k Sukočanom in reče: Glejte Zebaha in Zalmuna, ki ste me ž njima zasmehovali, govoreč: Ali je pest Zebahova in Zalmunova že v tvoji roki, da bi dali kruha utrujenim možem tvojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 16, 'in vzame mestne starejšine in trnje iz puščave in bodljikovje in kaznuje ž njim sukotske može.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 17, 'Stolp v Penuelu pa podere in pomori može v mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 18, 'In reče Zebahu in Zalmunu: Kakšni so bili tisti možje, ki sta jih umorila na Taboru? Odvrneta: Takšni so bili kakor ti: vsak lepe postave, kakor kraljevi otroci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 19, 'In reče: Bili so moji bratje, matere moje sinovi; kakor res živi Gospod, ko bi jih bila pri življenju ohranila, ne bi vaju umoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 20, 'In veli Jeteru, prvencu svojemu: Vstani, umori ju! A deček ne izdere meča, kajti bal se je, ker je bil še mlad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 21, 'Zebah in Zalmuna pa mu rečeta: Vstani ti in naju ubij, zakaj kakršen je mož, taka je njegova moč. In Gideon vstane in umori Zebaha in Zalmuna, in vzame lunice, ki so bile na vratu njiju velblodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 22, 'Tedaj reko možje Izraelci Gideonu: Bodi nam vladar, ti in sin tvoj in sina tvojega sin, ker si nas rešil roke Madiancev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 23, 'Ali Gideon jim reče: Ne bodem vam vladar, tudi sin moj vam ne bode vladar; Gospod vam bodi vladar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 24, 'Gideon pa jim še reče: Eno bi vas prosil: dajte mi vsakdo nosne obodce, ki ste jih uplenili. Kajti imeli so nosne obodce iz zlata, ker so bili Izmaelci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 25, 'In reko: Radi jih damo. In razgrnejo oblačilo, in vsi mečejo nanje nosne obodce iz svojega plena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 26, 'In teža zlatih obodcev, ki jih je izprosil, je bila tisoč in sedemsto seklov zlata, brez lunic in naušnic in škrlatnih oblačil, ki sta jih nosila madianska kralja, in brez verižic, ki so jih njih velblodi imeli okoli vratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 27, 'In Gideon je iz tega naredil naramnik in ga postavil v svojem mestu, v Ofri. In ves Izrael se je ondi vdajal nečistosti za njim; in to je bilo v zanko Gideonu in hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 28, 'A Madianci so bili potlačeni pred Izraelovimi sinovi in niso več vzdignili glav svojih. In dežela je imela pokoj štirideset let v dnevih Gideonovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 29, 'In Jerub-baal, sin Joasov, je šel in prebival v svoji hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 30, 'Imel pa je Gideon sedemdeset sinov, ki so prišli iz ledja njegovega, zakaj imel je mnogo žen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 31, 'In priležnica njegova, ki je bila v Sihemu, mu je tudi rodila sina, in dal mu je ime Abimelek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 32, 'In Gideon, sin Joasov, je umrl v lepi starosti in je bil pokopan v grobu očeta svojega Joasa v Ofri Abiezritov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 33, 'Ko pa je umrl Gideon, brž so se odvrnili sinovi Izraelovi in nečistovali za Baali in si postavili Baal-berita za boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 34, 'In niso se spominjali sinovi Izraelovi Gospoda, svojega Boga, ki jih je bil otel iz roke vseh njih sovražnikov vseokrog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 8, 35, 'tudi niso izkazali usmiljenja hiši Jerub-baal-Gideonovi, kakor je on storil vse dobro Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 1, 'Abimelek pa, sin Jerub-baalov, je šel v Sihem k bratom matere svoje, in ogovori jih in vse sorodništvo hiše očeta matere svoje, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 2, 'Govorite, prosim, v ušesa vseh sihemskih meščanov: Kaj vam je bolje, da vam vlada sedemdeset mož, vsi sinovi Jerub-baalovi, ali da vam vlada eden? Pomnite tudi, da sem vaša kost in vaše meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 3, 'In govorili so bratje matere njegove vse te besede v ušesa vseh sihemskih meščanov. In nagnilo se je njih srce k Abimeleku, zakaj rekli so: Brat naš je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 4, 'In dali so mu sedemdeset srebrnikov iz Baal-beritove hiše; in s temi si najme Abimelek praznoglavih in gizdavih mož, ki so hodili za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 5, 'In pride v očeta svojega hišo v Ofri in umori brate svoje, sinove Jerub-baalove, sedemdeset mož na enem kamenu. Jotam pa, najmlajši sin Jerub-baalov, je ostal, ker se je bil skril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 6, 'In zbero se vsi sihemski meščani in vsa družina v Milu in gredo ter postavijo Abimeleka za kralja pri spominskem hrastu, ki je v Sihemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 7, 'Ko to sporoče Jotamu, gre in stopi na vrh gore Garizima in povzdigne glas in zakliče, rekoč jim: Poslušajte me, gospoda sihemska, da Bog tudi vas sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 8, 'Drevesa so šla, da si pomazilijo kralja, in so dejala oljki: Kraljuj nad nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 9, 'A oljka odgovori: Ali naj opustim maščobo svojo, s katero po meni časté Boga in človeka, in naj grem, da bi se vznašala nad drevesi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 10, 'In drevesa reko smokovemu drevesu: Pridi ti in nam kraljuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 11, 'A smokva jim reče: Ali naj opustim sladkost svojo in svoj dobri sad in naj grem, da bi se vznašala nad drevesi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 12, 'Nato reko drevesa vinski trti: Pridi ti in kraljuj nad nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 13, 'Vinska trta pa jim reče: Ali naj opustim sok svoj, ki razveseljuje Boga in človeka, in naj grem, da se vznašam nad drevesi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 14, 'Reko torej vsa drevesa bodljiki: Pridi pa ti in nad nami kraljuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 15, 'In bodljika reče drevesom: Ako si me v resnici hočete pomaziliti za kralja, pridite, imejte zavetje pod senco mojo! Ako pa ne, naj pride ogenj iz bodljike in požre cedre libanonske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 16, 'Ako ste torej zvesto in pošteno ravnali, da ste si za kralja postavili Abimeleka, in ako ste dobro storili Jerub-baalu in hiši njegovi, ako ste mu poplačali delo rok njegovih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 17, '(zakaj moj oče se je bojeval za vas in žrtvoval življenje svoje in vas je rešil iz roke Madiancev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 18, 'vi pa ste se danes vzdignili zoper očeta mojega hišo in ste umorili sinove njegove, sedemdeset mož na enem kamenu, in ste postavili Abimeleka, sina dekle njegove, za kralja sihemskim meščanom, ker je vaš brat):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 19, 'ako ste torej zvesto in pošteno ravnali z Jerub-baalom in s hišo njegovo ta dan, veselite se Abimeleka, tudi on naj se vas veseli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 20, 'Ako pa ne, naj pride ogenj iz Abimeleka in požre sihemske meščane in hišo Milo, in pride naj ogenj iz sihemskih meščanov in iz hiše Mila in požre Abimeleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 21, 'Nato se umakne Jotam in pobegne, in uide v Beer in se ondi nastani, boječ se Abimeleka, brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 22, 'Ko pa je vladal Abimelek Izraelu tri leta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 23, 'pošlje Bog hudega duha med Abimeleka in sihemske meščane; in Sihemljani so izdajalsko ravnali z Abimelekom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 24, 'da pride osveta za nasilstvo, storjeno sedemdesetim sinovom Jerub-baalovim, in se njih kri povrne na Abimeleka, njih brata, ki jih je umoril, in na sihemske meščane, ker so mu ojačili roke, da ubije svoje brate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 25, 'In sihemski meščani so mu nastavili zasednike po vrhovih gorá, in ti so oplenjevali vse, ki so potovali mimo njih po cesti. In to se je sporočilo Abimeleku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 26, 'Gaal pa, sin Ebedov, pride s svojimi brati in se preseli v Sihem; in meščani sihemski so se zanesli nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 27, 'In gredo ven na njive in obirajo vinograde in tlačijo grozdje, in napravijo veselico ter gredo v svojega boga hišo in jedo in pijejo in preklinjajo Abimeleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 28, 'In Gaal, sin Ebedov, reče: Kdo je Abimelek, in kaj je Sihem, da bi mu služili? Ni li on sin Jerub-baalov? in Zebul, ni li njegov upravitelj? Služite rajši možem Hemorja, očeta Sihemovega! Ker zakaj bi mi služili onemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 29, 'O da bi bilo to ljudstvo pod mojo roko, in odpravil bi Abimeleka! In sporočijo Abimeleku: Pomnoži vojsko svojo in pridi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 30, 'Ko pa zasliši Zebul, mestni poglavar, besede Gaala, sina Ebedovega, se razvname srd njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 31, 'In v zvijači pošlje selstvo k Abimeleku in mu sporoči: Glej, Gaal, sin Ebedov, je prišel z brati svojimi v Sihem, in glej, silijo mesto, da se ti upre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 32, 'Sedaj torej, vstani po noči in ljudstvo, ki je pri tebi, in napravi zasedo na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 33, 'Zjutraj pa, ko vzide solnce, vstani zgodaj in plani na mesto; in glej, ko pride on in ljudstvo, ki je pri njem, tebi nasproti, lahko jim storiš, kar premoreš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 34, 'In Abimelek vstane po noči in vse ljudstvo, ki je bilo pri njem, in se skrijejo v zasedi proti Sihemu v štirih četah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 35, 'In Gaal, sin Ebedov, pride ven in se postavi ob vhodu v mestna vrata. Abimelek pa vstane iz zasede in ljudstvo, ki je bilo pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 36, 'In ko vidi Gaal ljudstvo, reče Zebulu: Glej, neko ljudstvo prihaja doli z vrhov gorá. Zebul pa mu odgovori: Vidiš senco gorá in zdi se ti, da so ljudje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 37, 'A Gaal zatrdi zopet in reče: Glej, ljudstvo prihaja z viška dežele, in ena četa gre sem po cesti k Hrastu čarovnikovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 38, 'Tedaj mu reče Zebul: Kje so zdaj usta tvoja, ki so dejala: Kdo je Abimelek, da bi mu služili? Ni li to tisto ljudstvo, ki si ga zaničeval? Sedaj pa pojdi vendar in bojuj se ž njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 39, 'In Gaal je šel na čelu sihemskih meščanov in se je bojeval zoper Abimeleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 40, 'Toda Abimelek ga zapodi v beg, in zbeži pred njim; in mnogo jih je popadalo ubitih na poti do mestnih vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 41, 'In Abimelek je prebival v Arumi; Zebul pa je pregnal Gaala in brate njegove, da niso smeli bivati v Sihemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 42, 'In ko se drugi dan ljudstvo odpravi na polje, se to sporoči Abimeleku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 43, 'In vzame svoje ljudstvo in ga razdeli v tri čete in preži v zasedi na polju; in pogleda, in glej, ljudstvo gre iz mesta, in plane nadnje ter jih pobije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 44, 'Abimelek namreč in četa, ki je bila pri njem, jih zaskoči in se postavi ob vhodu v mestna vrata; drugi dve četi pa naskočita vse, ki so bili na polju, ter jih pobijeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 45, 'In Abimelek se je bojeval zoper mesto ves tisti dan in ga dobil, in je pobil ljudstvo, ki je bilo v njem; in mesto je razdejal in ga posul s soljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 46, 'Ko pa to slišijo vsi gospodje sihemskega gradiča, stopijo v hram hiše boga Berita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 47, 'In sporoči se Abimeleku, da so se zbrali vsi gospodje sihemskega gradiča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 48, 'In Abimelek gre na goro Zalmon, on in vse ljudstvo, ki je bilo ž njim; in vzame sekiro v roko in odseka vejo z drevja, jo vzdigne in položi na ramo svojo in veli ljudstvu, ki je bilo ž njim: Kar ste me videli storiti, hitro storite po moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 49, 'In odseka tudi vse ljudstvo, sleherni svojo vejo, in gredo za Abimelekom in polože veje okrog hrama in zažgo ž njimi hram, tako da poginejo vsi ljudje na sihemskem gradiču, okoli tisoč mož in žen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 50, 'Potem gre Abimelek proti Tebezu in ga oblega in dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 51, 'Ali sredi mesta je bil močan stolp, kamor so zbežali vsi možje in žene in vsi mestni prvaki, in so zaprli za sabo in stopili na stolpovo streho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 52, 'In Abimelek pride do stolpa in se bojuje zoper njega in pristopi do samih duri v stolp, da jih zažge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 53, 'Neka žena pa vrže vrhnji kamen ročnega mlina Abimeleku na glavo in mu razbije lobanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 54, 'Tedaj pokliče Abimelek hitro mladeniča, ki mu je nosil orožje, in mu veli: Potegni svoj meč in me umori, da ne poreko o meni: Žena ga je ubila. In njegov hlapec ga prebode, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 55, 'Ko pa vidijo možje Izraelovi, da je Abimelek mrtev, odide vsak v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 56, 'Tako je Bog poplačal Abimeleku zlo, ki ga je storil očetu svojemu, umorivši sedemdeset bratov svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 9, 57, 'tudi vse zlo sihemskih mož je Bog povrnil na njih glavo; in prišlo je nadnje prokletje Jotama, sina Jerub-baalovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 1, 'In po Abimeleku je vstal, da reši Izraela, Tola, sin Pua, sina Dodovega, mož iz Isaharja; in prebival je v Samirju v Efraimskem gorovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 2, 'In sodil je Izraela trindvajset let, in je umrl in bil pokopan v Samirju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 3, 'In po njem je vstal Jair, Gileadski; in je sodil Izraela dvaindvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 4, 'In imel je trideset sinov, ki so jezdili na tridesetih mladih oslih in so imeli trideset mest, ki se imenujejo Jairovi trgi do današnjega dne in so v pokrajini Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 5, 'In Jair je umrl in je bil pokopan v Kamonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 6, 'In Izraelovi sinovi so še dalje delali, kar je bilo hudo v očeh Gospodovih, in služili so Baalom in Astartam in bogovom Sircev in bogovom Sidoncev in bogovom Moabcev in bogovom sinov Amonovih in bogovom Filistejcev, Gospoda pa so zapustili ter mu niso služili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 7, 'Tedaj se je vnela jeza Gospodova zoper Izraela in jih je prodal v roko Filistejcev in v roko Amonovih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 8, 'In stiskali so in mučili Izraelove sinove tisto leto; osemnajst let so stiskali vse sinove Izraelove, ki so bili za Jordanom, v deželi Amorejcev, ki je v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 9, 'Vrhutega so Amonovi sinovi prešli Jordan, da se bojujejo z Judo in z Benjaminom in z Efraimovo hišo; in Izrael je bil silno stiskan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 10, 'In sinovi Izraelovi so vpili h Gospodu, govoreč: Grešili smo zoper tebe, kajti zapustili smo Boga svojega in služili Baalom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 11, 'A Gospod reče sinovom Izraelovim: Nisem li vas rešil Egipčanov in Amorejcev, sinov Amonovih in Filistejcev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 12, 'Tudi Sidonjani in Amalekovci in Maonci so vas stiskali, in ko ste vpili do mene, sem vas rešil njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 13, 'In vendar ste me zapustili in služili drugim bogovom; zato vas ne bom več rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 14, 'Pojdite in kličite k bogovom, ki ste si jih izvolili: naj vas rešijo v dan stiske vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 15, 'Sinovi Izraelovi pa reko Gospodu: Grešili smo, stóri nam, karkoli se ti dobro zdi; samo reši nas, prosimo, tačas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 16, 'In odpravili so tuje bogove izmed sebe in so služili Gospodu. In njemu se je v srce smililo, da je Izrael tolikanj trpel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 17, 'In Amonovi sinovi so se sklicali in so se utaborili v Gileadu. Sinovi Izraelovi pa so se zbrali in se utaborili v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 10, 18, 'In ljudstvo, gileadski prvaki, so dejali drug drugemu: Kdo se začne vojskovati zoper Amonove otroke? Ta bodi poglavar vsem prebivalcem v Gileadu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 1, 'Jefta pa, Gileadec, je bil močan junak, pa je bil nečistnice sin; in Gilead je rodil Jefta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 2, 'Gileadova žena pa mu je rodila otrok, ali ko so te žene sinovi dorasli, pahnejo Jefta od sebe in mu reko: Ne boš ti dedoval v očeta našega hiši, ker si postranske žene sin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 3, 'Tedaj zbeži Jefta pred brati svojimi in se nastani v Tobski deželi. In zbero se k njemu postopači in hodili so ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 4, 'Za nekaj časa pa so se vojskovali Amonovi sinovi z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 5, 'Ko so torej začeli Amonovi sinovi vojsko z Izraelom, se napotijo gileadski starejšine, da pripeljejo Jefta iz Tobske dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 6, 'In reko Jeftu: Pridi in bodi nam poveljnik, da se bojujemo zoper Amonove sinove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 7, 'Jefta pa odvrne starejšinam iz Gileada: Niste li vi me sovražili in me pehnili iz mojega očeta hiše? Zakaj pa ste prišli k meni zdaj, ko ste v nadlogi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 8, 'In gileadski starejšine reko Jeftu: Zato smo se zdaj obrnili do tebe, da pojdeš z nami in se bojuješ zoper Amonove sinove, in bodi glava nam, vsem prebivalcem v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 9, 'Jefta reče gileadskim starejšinam: Ako me pripeljete domov, da se bom vojskoval s sinovi Amonovimi, in ako mi jih Gospod da v pest, ali vam bodem glava?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 10, 'Gileadski starejšine reko Jeftu: Gospod bodi med nami priča! Resnično storimo tako, kakor si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 11, 'Tedaj gre Jefta z gileadskimi starejšinami, in ljudstvo ga postavi za glavo in poveljnika nad seboj. In Jefta je govoril vse besede svoje pred Gospodom v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 12, 'Nato pošlje Jefta selstvo do kralja Amonovih sinov in sporoči: Kaj imaš opraviti z mano, da si prišel k meni vojskovat se zoper mojo deželo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 13, 'Kralj Amonovih sinov pa odgovori Jeftovim slom: Zato ker mi je Izrael vzel deželo, ko je prišel iz Egipta, od Arnona do Jaboka in tja do Jordana; zdaj torej mi jo povrni v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 14, 'Jefta, pa pošlje zopet sle h kralju Amonovih sinov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 15, 'in mu sporoči: Tako pravi Jefta: Izrael ni vzel dežele Moabcev, ne dežele Amonovih sinov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 16, 'temuč ko so Izraelci prišli iz Egipta in potovali po puščavi do Rdečega morja in dospeli v Kades,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 17, 'tedaj je poslal Izrael selstvo k edomskemu kralju, rekoč: Dovoli mi, prosim, iti skozi deželo tvojo, ali kralj edomski jih ni uslišal. Enako je sporočil kralju Moabcev, a ta tudi ni hotel; in Izraelu je bilo ostati v Kadesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 18, 'Potem je potoval po puščavi in obšel deželo Edomcev in deželo Moabcev in prišel ob vzhodni strani k pokrajini Moabcev, in raztaborili so se na oni strani Arnona; ali v pokrajino Moabcev niso prišli, ker Arnon je meja Moabcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 19, 'In Izrael je poslal poročnike k Sihonu, kralju Amorejcev, kralju v Hesbonu, in Izrael mu sporoči: Dovoli nam, prosim, iti skozi deželo tvojo do našega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 20, 'A Sihon ni zaupal Izraelu, da bi šel mirno čez mejo njegovo, ampak Sihon je zbral vse ljudstvo svoje in se je utaboril v Jahazu in se bojeval z Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 21, 'Gospod pa, Bog Izraelov, je dal Sihona z vsem ljudstvom njegovim Izraelcem v roke, in porazili so jih. Tako je Izrael zasedel vso deželo Amorejcev, ki so bivali v tisti pokrajini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 22, 'In posedli so vso pokrajino Amorejcev, od Arnona do Jaboka in od puščave do Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 23, 'Tako torej je Gospod, Bog Izraelov, razdedinil Amorejce pred ljudstvom svojim Izraelom, in ti hočeš zavzeti, kar je njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 24, 'Ni li prav, da vzameš tisto, kar ti da v posest Kamos, bog tvoj? Tudi mi hočemo obdržati, karkoli je pred nami pripravil v posest Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 25, 'Ali si mar kaj boljši od Balaka, sinu Ziporjevega, kralja Moabcev? ali se je on kdaj pravdal ali bojeval z Izraelom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 26, 'Ker pa je Izrael že tristo let prebival v Hesbonu in po njegovih podložnih vaseh in v Aroerju in po podložnih vaseh njegovih in po vseh mestih, ki so poleg Arnona, zakaj jih niste pridobili sebi v tem času?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 27, 'Jaz torej se nisem pregrešil zoper tebe, a ti hudo ravnaš z menoj, da se vojskuješ zoper mene. Gospod, Sodnik, naj danes razsodi med sinovi Izraelovimi in sinovi Amonovimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 28, 'Ali kralj Amonovih sinov ni poslušal Jeftovih besed, ki mu jih je sporočil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 29, 'Tedaj pride duh Gospodov nad Jefta, in ta preide Gilead in Manase in Micpo v Gileadu, in od Micpe v Gileadu preide proti Amonovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 30, 'In Jefta stori obljubo Gospodu in reče: Če mi res daš Amonove sinove v roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 31, 'karkoli pride skozi duri hiše moje, meni naproti, ko se bom vračal v miru od sinov Amonovih, bodi Gospodovo, in hočem to darovati kot žgalno žrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 32, 'Tako gre Jefta proti Amonovim sinovom, da se bojuje zoper nje; in Gospod jih da v roko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 33, 'In porazil jih je od Aroerja do tja, koder se gre v Minit, dvajset mest, in tja do Abelkeramima, v velikem poboju. Tako so bili Amonovi sinovi potlačeni pred Izraelovimi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 34, 'Ko se pa vrača Jefta v Micpo v dom svoj, glej, hči njegova mu pride naproti z bobnicami in plesom; in ona mu je bila edinica, razen nje ni imel ne sina, ne hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 35, 'In ko jo ugleda, si raztrga oblačila in reče: Ah, hči moja! hudo si me ponižala, ena si teh, ki me žalijo; kajti odprl sem usta svoja proti Gospodu, in ne morem preklicati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 36, 'Ona pa mu reče: Oče moj, odprl si usta svoja proti Gospodu, stóri mi torej, kakor je prišlo iz ust tvojih; samo da te je Gospod maščeval nad tvojimi sovražniki, Amonovimi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 37, 'Še reče očetu svojemu: Stóri mi le-to: pusti me dva meseca, da odidem in pojdem doli v hribe in bom objokovala devištvo svoje z družicami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 38, 'In ji veli: Pojdi. In odpusti jo za dva meseca. In ona odide s svojimi družicami in joče nad devištvom svojim po gorah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 39, 'In ko mineta dva meseca, pride nazaj k očetu svojemu, in on ji stori, kakor je bil obljubil. In ona ni spoznala moža. In prišlo je v navado v Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 11, 40, 'da so hodile Izraelove hčere vsako leto slavit hčer Jefta Gileadskega, po štiri dni v letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 1, 'A efraimski možje so se zbrali in prešli na sever, in reko Jeftu: Zakaj si se šel bojevat zoper Amonove sinove in nas nisi poklical, da idemo s teboj? Sežgemo hišo tvojo nad teboj z ognjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 2, 'Jefta jim reče: Jaz in ljudstvo moje smo bili v hudem sporu z Amonovimi sinovi, in ko sem vas klical, mi niste pomogli iz njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 3, 'In videč, da mi niste v pomoč, sem izpostavil nevarnosti življenje svoje in šel proti Amonovim sinovom, in Gospod mi jih je dal v roko. Zakaj pa danes hodite gori k meni, da se bojujete z menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 4, 'In Jefta zbere vse može iz Gileada in se vojskuje zoper Efraima. In gileadski možje udarijo Efraimce, ker so govorili: Begunci ste Efraimovi, vi Gileadovci, sredi Efraima in sredi Manaseja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 5, 'In Gileadovci zasedejo jordanske brodove proti Efraimskim; in ko je bežečih Efraimskih kdo rekel: Daj, da grem na ono stran, mu vele možje iz Gileada: Si li Efraimec? in ako je rekel: Nisem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 6, 'mu velé: Reci: Šibolet! on pa je rekel: Sibolet, ker ni pazil na pravo izreko. Tedaj ga zgrabijo in umorijo ob jordanskih brodovih. In padlo jih je tisti čas iz Efraima dvainštirideset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 7, 'Jefta pa je sodil Izraela šest let. Potem je umrl Jefta Gileadec in je bil pokopan v enem izmed, gileadskih mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 8, 'Po njem je sodil Izraela Ibzan iz Betlehema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 9, 'Ta je imel trideset sinov, in je vdal iz hiše svoje trideset hčera in trideset jih je vzel sinovom svojim oddrugod; in sodil je Izraela sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 10, 'In Ibzan je umrl in je bil pokopan v Betlehemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 11, 'In po njem je sodil Izraela Elon Zebulonovec; in sodil je Izraelu deset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 12, 'In Elon Zebulonovec je umrl in je bil pokopan v Ajalonu, v Zebulonovi deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 13, 'In po njem je sodil Izraelu Abdon, sin Hilelov, Piratončan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 14, 'Ta je imel štirideset sinov in trideset vnukov, ki so jezdili na sedemdesetih osličih; in sodil je Izraelu osem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 12, 15, 'In Abdon, sin Hilelov, Piratončan, je umrl in je bil pokopan v Piratonu v Efraimovi deželi, na gorovju Amalekovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 1, 'In sinovi Izraelovi so zopet delali, kar je bilo zlo v očeh Gospodovih, in Gospod jih je dal Filistejcem v roko štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 2, 'Bil pa je neki mož iz Zore, iz rodovine Danove, ki mu je bilo ime Manoah; in žena njegova je bila nerodovitna in ni rodila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 3, 'In angel Gospodov se prikaže ženi in ji reče: Glej, nerodovitna si in ne rodiš; pa spočneš in porodiš sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 4, 'Sedaj pa varuj se, pravim, da ne piješ vina in močne pijače in ne ješ nič nečistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 5, 'Kajti glej, spočela boš in rodila sina, ki mu ne sme britev priti na glavo, zakaj deček bode nazirec Božji od materinega telesa, in on začne reševati Izraela iz roke Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 6, 'In žena pride in pove možu svojemu, rekoč: Prišel je mož Božji k meni, in podoba njegova je bila kakor angela Božjega, silno strašna, da ga nisem vprašala, odkod je, pa on mi ni povedal, kako mu je ime;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 7, 'a dejal mi je: Glej, spočela boš in rodila sina, ne pij torej nič vina, ne močne pijače, in ne jej nič nečistega, zakaj deček bode nazirec Božji od materinega telesa do dne smrti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 8, 'Tedaj zaprosi Manoah Gospoda in reče: O Gospod, prosim, daj, da pride mož Božji, ki si ga bil poslal, zopet k nama ter naju pouči, kako naj ravnava z dečkom, ki se bo rodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 9, 'In Bog je slišal glas Manoahov: in angel Božji pride zopet k ženi, ko je sedela na polju, a Manoah, mož njen, ni bil pri njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 10, 'Žena pa hitro teče, in naznani možu svojemu in mu reče: Glej, prikazal se mi je tisti mož, ki je bil prišel k meni ondan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 11, 'In Manoah vstane in gre za ženo svojo, in pride k možu in mu reče: Ti li si tisti mož, ki si govoril z ženo? Odgovori: Sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 12, 'In reče Manoah: Ko se torej izpolnijo besede tvoje, kaj bodi pravilo za dečka in delo njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 13, 'In angel Gospodov reče Manoahu: Vsega, kar sem povedal ženi, naj se ona varuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 14, 'Naj ne uživa ničesar, kar pride iz vinske trte, niti ne pije vina, ne močne pijače in ne je nič nečistega; in vse, kar sem ji zapovedal, naj izpolnjuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 15, 'In Manoah reče angelu Gospodovemu: Prosim, rada bi te pomudila, da ti pripraviva kozliča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 16, 'Angel Gospodov pa reče Manoahu: Ko bi me tudi pomudil, ne bom jedel od tvojega kruha; če pa hočeš pripraviti žgalščino, jo moraš darovati Gospodu. Manoah namreč ni vedel, da je bil angel Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 17, 'In Manoah reče angelu Gospodovemu: Kako ti je ime? da ti izkažemo čast, ko pride, kar si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 18, 'Angel Gospodov pa mu odgovori: Čemu pa vprašuješ po mojem imenu, ki je čudovito?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 19, 'Tedaj vzame Manoah kozliča z jedilno daritvijo in ga daruje na skali Gospodu; in on je storil čudež, ko sta Manoah in žena njegova gledala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 20, 'Zgodi se namreč, ko je ogenj plapolal proti nebu z oltarja, da odide gori angel Gospodov v plamenu oltarja, ko sta Manoah in žena njegova gledala; in padla sta na obraz svoj na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 21, 'In ni se več prikazal angel Gospodov Manoahu in ženi njegovi. Tedaj je spoznal Manoah, da je bil angel Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 22, 'In Manoah reče ženi svoji: Gotovo skoraj umrjeva, ker sva videla Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 23, 'Ali žena njegova mu reče: Ko bi Gospodu ugajalo usmrtiti naju, ne bi bil sprejel žgalne in jedilne daritve iz roke najine, tudi bi nama ne bil pokazal vsega tega, ne v tem času nama dal slišati takih reči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 24, 'In žena je rodila sina in ga imenovala Samsona. In deček je rastel, in Gospod ga je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 13, 25, 'In duh Gospodov ga je začel izpodbadati v Danovem šatorišču, med Zoro in Estaolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 1, 'In Samson je šel doli v Timnato, in ondi je videl ženo izmed hčera Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 2, 'In ko pride gori, naznani očetu svojemu in materi svoji ter reče: Videl sem ženo v Timnati med hčerami Filistejcev, in sedaj mi jo vzemite za ženo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 3, 'Nato mu reče oče njegov in mati njegova: Ni li žene med hčerami bratov tvojih ali med vsem našim ljudstvom, da greš in jemlješ ženo od Filistejcev, tistih neobrezancev? A Samson reče očetu svojemu: Njo mi vzemi, ker ta je prava mojim očem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 4, 'Oče in mati njegova pa nista vedela, da je to od Gospoda; kajti iskal je prilike zoper Filistejce. Ta čas so namreč Filistejci vladali Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 5, 'Odpravi se torej Samson z očetom in materjo svojo doli v Timnato. In ko pridejo k timnatskim vinogradom, glej, mlad lev mu pride rjoveč nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 6, 'In duh Gospodov pride z močjo nad njega, da raztrga leva, kakor bi raztrgal kozliča, dasi ni ničesar imel v roki; pa ni povedal očetu svojemu ali materi svoji, kar je bil storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 7, 'In pride doli in govori s tisto ženo, in prava je bila očem Samsonovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 8, 'In za nekaj časa pride zopet, da jo vzame, in stopi s pota, da pogleda mrhovino tistega leva, in glej, roj čebel je bil v levovem truplu in med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 9, 'In vzame si ga v roke in ga spotoma je, in ko pride k očetu svojemu in materi svoji, jima da, in tudi jesta; pa jima ni povedal, da je vzel med iz levovega trupla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 10, 'In oče njegov pride doli k ženi, in Samson napravi ondi gostovanje; kajti tako je bilo v navadi pri mladeničih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 11, 'In ko ga Filistejci ugledajo, mu pridružijo trideset tovarišev, da bodo pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 12, 'In Samson jim reče: Dovolite, da vam dam uganko: ako mi jo uganete in zadenete v sedmih dneh gostovanja, vam hočem dati trideset spodnjih oblek in trideset prazničnih oblačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 13, 'Ako je pa ne boste mogli uganiti, morate meni dati trideset spodnjih in trideset prazničnih oblačil. In mu reko: Zastavi uganko svojo, da jo čujemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 14, 'In on jim reče: Iz požeruha je prišlo jedilo, in iz močnega je prišla sladkost. In po treh dnevih niso mogli uganke rešiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 15, 'In sedmi dan reko Samsonovi ženi: Pregovori moža svojega, da nam razloži tisto uganko, sicer sežgemo tebe in tvojega očeta hišo z ognjem. Ste li nas zato sem povabili, da nas pripravite v uboštvo, ali kaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 16, 'Tedaj je plakala Samsonova žena pred njim, govoreč: Ti me le sovražiš in me ne ljubiš. Uganko si dal ljudstva mojega sinovom, a meni je nisi povedal. On pa ji reče: Glej, očetu svojemu in materi svoji nisem povedal, tebi naj pa razodenem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 17, 'In plakala je pred njim sedem dni, dokler je trajalo njih gostovanje. In zgodi se sedmi dan, da ji razloži, ker ga je hudo nadlegovala. Ona pa izda uganko ljudstva svojega sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 18, 'Reko mu torej možje iz mesta sedmi dan, preden je zašlo solnce: Kaj je slajše nego med? in kaj močnejše nego lev? On pa jim reče: Ko bi ne bili orali z mojo junico, ne bi bili pogodili uganke moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 19, 'In duh Gospodov pride z močjo nad njega, in gre doli v Askelon in pobije trideset mož izmed njih, in vzame njih obleko in da praznična oblačila tistim, ki so razložili uganko. In jeza se mu razvname, in odide gori v očeta svojega hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 14, 20, 'Žena Samsonova pa je bila dana enemu izmed tovarišev njegovih, s katerim se je bil sprijateljil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 1, 'Zgodi se pa za nekaj časa, v dneh pšenične žetve, da obišče Samson ženo svojo in ji prinese kozliča. In reče: Pojdem noter k ženi svoji v stanico. A ni mu dovolil njen oče vstopiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 2, 'In reče oče njen: Res sem mislil, da si ji postal sovražen, in sem jo dal tovarišu tvojemu. Ni li mlajša sestra njena lepša nego ona? Ta bodi tvoja namesto one.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 3, 'Nato jim reče Samson: Sedaj pa ne bodem kriv proti Filistejcem, ako jim bom škodo delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 4, 'In Samson odide in ulovi tristo lisic in vzame bakle in zveže po dve in dve za repe ter dene vselej baklo med dva repa');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 5, 'in jih prižge z ognjem, in jih pusti v žito Filistejcev in požge tako snopje in še rastoče žito in tudi olivnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 6, 'Tedaj reko Filistejci: Kdo je to storil? In odgovore: Samson, zet Timnatejca, ker mu je vzel ženo in jo dal njegovemu tovarišu. In Filistejci pridejo ter sežgo njo in očeta njenega z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 7, 'In Samson jim reče: Če tako delate, gotovo ne neham, dokler se ne maščujem nad vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 8, 'In jim razbije pleča in ledja s hudimi udarci. Potem gre dol in prebiva v skalni razpoki v Etamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 9, 'Tedaj pridero Filistejci gori in se ušatore na Judovem in se razprostro v Lehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 10, 'Možje Judovi pa reko: Zakaj ste prišli gori zoper nas? Odgovore: Prišli smo zvezat Samsona, da mu storimo, kakor je storil nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 11, 'Nato gre tri tisoč mož iz Jude doli k skalni razpoki v Etamu, in reko Samsonu: Ali ne veš, da nam vladajo Filistejci? Kaj je torej to, kar si nam storil? In jim reče: Kakor so oni storili meni, tako sem storil njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 12, 'Reko mu: Prišli smo doli te zvezat in izdat Filistejcem v roke. Samson jim veli: Prisezite mi, da me vi ne ubijete!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 13, 'Odgovore mu, rekoč: Nikar, hočemo te le zvezati in te njim dati v roke; res te ne umorimo. In so ga zvezali z dvema novima vrvema in ga peljali gori od skale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 14, 'Ko pride v Leho, zavriskajo Filistejci in mu gredo naproti. A duh Gospodov pride z močjo nad njega, in vrvi na rokah njegovih postanejo kakor niti, ko jih ogenj osmodi, in vezila njegova padejo z rok njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 15, 'In najde čeljust oslovsko, še sirovo, ter iztegne roko in jo pobere in pobije ž njo tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 16, 'In Samson reče: Z oslovsko čeljustjo sem naredil eno kopo, dve kopi, z oslovsko čeljustjo sem pobil tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 17, 'In ko je to izrekel, vrže čeljust iz roke, in tisti kraj imenuje Ramat-lehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 18, 'Bil pa je silno žejen, in kliče h Gospodu in reče: Ti si dal tako veliko rešitev po roki hlapca svojega, in sedaj da bi umrl žeje in padel neobrezancem v roke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 19, 'Tedaj razkolje Bog votlino, ki je v Lehi, in priteče voda iz nje; in ko se napije, se mu povrne duh in oživi. Zatorej so jo imenovali Studenec kličočega, ki je v Lehi do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 15, 20, 'In on je sodil Izraela za časa Filistejcev dvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 1, 'In Samson je šel v Gazo in ondi videl nečistnico in je stopil noter k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 2, 'In povedalo se je Gažanom: Samson je prišel semkaj! In ga obkolijo in strežejo nanj vso noč ob mestnih vratih in se dogovore, da bodo tiho vso noč, češ, zjutraj, ko zasvita, ga umorimo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 3, 'In Samson leži do polnoči; opolnoči pa vstane in zagrabi obe durnici mestnih vrat z obema podbojema in ju vzdigne z zapahi vred ter si ju zadene na ramo in odnese na vrh gore, ki je pred Hebronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 4, 'Potem pa se zaljubi v ženo v dolini Soreku, ki ji je bilo ime Delila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 5, 'In knezi Filistejcev pridejo k njej ter ji reko: Pregovori ga in zvedi, v čem ima takovo veliko moč in s čim bi ga premagali, da ga zvežemo in ponižamo, in damo ti vsak tisoč in sto srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 6, 'Tedaj reče Delila Samsonu: Povej mi, prosim, v čem imaš veliko moč svojo in s čim bi te bilo zvezati, da te ukrote?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 7, 'In Samson ji reče: Ako me zvežejo s sedmimi novimi vrvmi, ki še niso posušene, oslabim in bom kakor drugi ljudje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 8, 'Nato ji prineso knezi Filistejcev sedem novih vrvi, ki se še niso posušile, in ona ga zveže ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 9, 'V izbi pri njej pa so sedeli na preži. In ona mu reče: Filistejci nad te, Samson! On pa raztrga vrvi, kakor pretrga kdo nit iz preje, če se dotakne ognja. In se ni zvedelo, v čem je njegova moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 10, 'In Delila reče Samsonu: Glej, norčeval si se z menoj in si mi lagal! Sedaj pa mi povej, prosim, s čim naj bi bil zvezan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 11, 'In ji odgovori: Ako me močno zvežejo z novimi vrvmi, ki se še niso rabile, oslabim in bodem kakor drugi ljudje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 12, 'Vzame torej Delila nove vrvi in ga zveže ž njimi ter mu reče: Filistejci nad te, Samson! V izbi pa so sedeli na preži. On pa raztrga vezi s svojih rok kakor nit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 13, 'In Delila reče Samsonu: Doslej si se norčeval z menoj in mi lagal! Povej mi, s čim naj bi bil zvezan. Odgovori ji: Ako spleteš sedem kit glave moje z osnutkom na vratilu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 14, 'In ona jih pribije s klinom in mu veli: Filistejci nad te, Samson! On pa se prebudi iz spanja in izdere klin z osnutkom in vratilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 15, 'In ona mu reče: Kako smeš reči, da me ljubiš, ko vendar srce tvoje ni z menoj? Že trikrat si se norčeval z menoj in mi nisi povedal, v čem je tvoja velika moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 16, 'In ko ga dan na dan nadleguje z besedami svojimi in ga pritiska, mu duša obnemore do smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 17, 'Tedaj ji odkrije vse srce svoje in ji reče: Nikoli mi ni prišla britev na glavo, kajti posvečenec Božji sem od materinega telesa. Ko bi me obrili, me zapusti moč moja, da oslabim in bodem kakor katerikoli človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 18, 'In ko Delila vidi, da ji je razodel vse srce svoje, pošlje in pokliče kneze Filistejcev ter jim sporoči: Pridite še enkrat, zakaj razodel mi je vse srce svoje. Tedaj pridejo k njej knezi Filistejcev in prineso srebro s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 19, 'In ona ga uspi na krilu svojem in pokliče moža, ki odstriže sedem kit na glavi njegovi. In ona ga je prva obvladala, in moč njegova ga je zapustila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 20, 'In mu reče: Filistejci nad te, Samson! In ko se prebudi iz spanja svojega, reče: Uidem, kakor sem čestokrat storil, in vsega se otresem! A ni vedel, da je Gospod odstopil od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 21, 'Filistejci pa ga ujamejo in mu iztaknejo oči, in ga peljejo doli v Gazo ter ga zvežejo z bronastimi verigami; in je moral mleti v jetnišnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 22, 'Ali lasje na glavi so mu začeli rasti precej, ko je bil obrit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 23, 'In knezi Filistejcev so se zbrali, da opravijo veliko daritev svojemu bogu Dagonu in se vesele; kajti rekli so: Naš bog nam je dal v pest Samsona, sovražnika našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 24, 'In ko ga vidi ljudstvo, hvalijo boga svojega, kajti reko: Naš bog nam je dal v pest sovražnika našega, ki je našo deželo pustošil in mnogo naših pobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 25, 'In ko se jim srce razveseli, reko: Pokličite Samsona, da igra pred nami. Pokličejo torej Samsona iz ječe, in igral je pred njimi. In postavili so ga med stebri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 26, 'In Samson veli dečku, ki ga je peljal za roko: Pusti me in daj, da otipam stebre, ki je na njih hiša postavljena, da se nanje naslonim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 27, 'Hiša pa je bila polna mož in žen. Tudi vsi knezi Filistejcev so bili tam in na strehi tri tisoč mož in žen, ki so gledali, kako je Samson igral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 28, 'Samson pa kliče h Gospodu in reče: O Gospod Jehova, spomni se me, prosim, in mi vsaj le to pot daj moč, o Bog, da se enkrat maščujem nad Filistejci za obe očesi svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 29, 'In prime za oba srednja stebra, ki se je nanju hiša opirala, in se upre ob nju, v enega s svojo desno in v drugega z levo roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 30, 'In Samson reče: Naj umrjem s Filistejci! In se nagne z vso močjo svojo, in hiša se zruši na kneze in na vse ljudstvo, ki je bilo v njej. In bilo je več mrtvih, ki jih je ubil v smrti svoji, nego njih, ki jih je pobil v življenju svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 16, 31, 'In pridejo doli bratje njegovi in vsa družina očeta njegovega, in ga vzdignejo in odneso gori in ga pokopljejo med Zoro in Estaolom v grobišču Manoaha, očeta njegovega. In on je sodil Izraela dvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 1, 'Bil je neki mož z Efraimskega gorovja, po imenu Miha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 2, 'Ta reče materi svoji: Tistih tisoč in sto srebrnikov, ki so ti bili ukradeni in si zaradi njih izrekla kletev in to si govorila na moja ušesa – glej, tisto srebro je pri meni, jaz sem si ga vzel. In mati njegova reče: Blagoslovljen bodi, sin moj, od Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 3, 'In povrnil je tistih tisoč in sto srebrnikov materi svoji. In mati njegova reče: Posvetila sem res to srebro Gospodu iz roke svoje za sina svojega, da se naredi rezana in ulita podoba; in zdaj ti ga povrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 4, 'In povrnil je srebro materi svoji. Mati njegova pa vzame dvesto srebrnikov in jih da zlatarju, ki naredi iz njih rezano in ulito podobo; in ta je bila v Mihovi hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 5, 'In Miha je imel hišo božjo in je napravil naramnik in hišne bogove in posvetil enega sinov svojih, da mu je bil duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 6, 'V tistih dneh ni bilo kralja v Izraelu: vsakdo je delal, kar se mu je zdelo prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 7, 'In bil je mladenič iz Betlehema Judovega, rodovinske lasti Judove, ki je bil levit in je prebival ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 8, 'Ta mož odide iz mesta, iz Betlehema Judovega, da se nastani, kjer dobi priliko. In ko potuje, pride na gorovje Efraimsko k hiši Mihovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 9, 'In Miha ga vpraša: Odkod greš? Odgovori mu: Levit sem iz Betlehema Judovega in potujem, da se nastanim, kjer dobim priliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 10, 'In Miha mu reče: Ostani pri meni in mi bodi oče in duhovnik, in dam ti na leto deset srebrnikov in obleko in živež tvoj. Levit torej vstopi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 11, 'in privoli ostati pri možu; in mladenič mu je bil kakor eden sinov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 12, 'In Miha je posvetil levita, da mu bodi duhovnik; in bival je v hiši Mihovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 17, 13, 'Miha pa je rekel: Sedaj vem, da mi bo Gospod dobro storil, ker mi je levit za duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 1, 'V tistih dneh ni bilo kralja v Izraelu. In v tistih dneh si je rod Danovcev iskal posesti, kjer bi prebival, zakaj do tistega časa niso dobili dediščine svoje med Izraelovimi rodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 2, 'In sinovi Danovi pošljejo iz svoje rodovine pet mož iz vsega števila svojega, hrabrih mož iz Zore in iz Estaola, da ogledajo deželo in jo preiščejo, in jim reko: Pojdite in preiščite deželo. In pridejo v Efraimsko gorovje k Mihovi hiši, in tam prenočijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 3, 'Ko so bili pri družini Mihovi, spoznajo glas mladeniča levita, in stopijo k njemu in mu reko: Kdo te je pripeljal semkaj? in kaj delaš v tem kraju? in kaj imaš tukaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 4, 'On jim odgovori: Tako in tako je storil Miha z menoj in me je najel, da mu bodem duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 5, 'In mu reko: Vprašaj Boga, prosimo, da vemo, če bomo imeli srečo na svojem potu, ki po njem gremo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 6, 'Duhovnik jim odgovori: Pojdite v miru! Pred Gospodom je pot vaša, ki greste po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 7, 'In tistih pet mož odide, in pridejo v Lais in vidijo tamošnje ljudstvo, da živi brezskrbno po načinu Sidoncev, pokojno in brez strahu, ker ni bilo nikogar v deželi, ki bi imel moč jih krotiti in ki bi jim kaj žalega storil, in bivajo daleč od Sidoncev in se z drugimi ljudmi ne družijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 8, 'Ko pridejo zopet k bratom svojim v Zoro in Estaol in jim njih bratje reko: Kako je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 9, 'odgovore: Vstanite, pojdimo proti njim! Kajti ogledali smo deželo, in glejte, silno je dobra! Vi pa mirno sedite? Ne bodite leni, ampak pojdite in posedite deželo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 10, 'Ko pojdete, pridete k brezskrbnemu ljudstvu in v prostrano deželo; kajti Bog vam jo je dal v roke, kraj, ki ničesar ne manjka v njem od vsega, kar je na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 11, 'In odrine odondod iz rodovine Danovcev, iz Zore in Estaola, šeststo mož z orožjem, pripravljenih na boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 12, 'In gredo gori in se utabore v Kirjat-jearimu na Judovem; zato se je imenoval ta kraj do današnjega dne Danov tabor, ki je za Kirjat-jearimom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 13, 'In odtod gredo dalje v gorovje Efraimsko in pridejo k Mihovi hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 14, 'Tedaj izpregovori tistih pet mož, ki so bili šli ogledovat deželo Lais, in reko bratom svojim: Veste, da je v teh hišah naramnik in hišni bogovi ter rezana in ulita podoba? In sedaj premislite, kaj vam je storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 15, 'In krenejo tja ter pridejo v hišo mladeniča levita, ob Mihovem domu, in ga vprašajo, kako se mu godi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 16, 'Tistih šeststo mož pa, pripravljenih z orožjem na boj, ki so bili izmed Danovih sinov, je stalo pred vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 17, 'In petero mož, ki so bili šli ogledovat deželo, gre gori, in stopijo noter in vzemo rezano podobo, naramnik in hišne bogove in ulito podobo. Medtem stoji duhovnik pred vrati pri tistih šeststo možeh, pripravljenih z orožjem na boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 18, 'In ko oni gredo v Mihovo hišo in prineso rezano podobo, naramnik, hišne malike in ulito podobo, jim reče duhovnik: Kaj delate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 19, 'Oni mu reko: Molči, položi roko na usta, pa pojdi z nami in nam bodi oče in duhovnik! Kaj je boljše zate, da si duhovnik enega moža družini ali da bodeš duhovnik celemu rodu in rodovini v Izraelu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 20, 'In duhovniku se vzraduje srce, in vzame naramnik in hišne malike in rezano podobo ter stopi med ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 21, 'In obrnejo se ter odidejo, ko so poslali pred sabo otročiče, živino in kar so imeli vrednosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 22, 'Ko so pa bili že daleč od Mihove hiše, se zbero možje, ki so bivali v hišah okoli Mihovega doma, in dohité Danove sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 23, 'In kličejo za Danovimi sinovi. Ti pa obrnejo svoje obličje in reko Mihu: kaj ti je, da greš s takim krdelom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 24, 'In reče: Moje bogove, ki sem si jih naredil, ste vzeli, in duhovnika, pa ste ušli! Kaj imam še? In vi še vprašujete: Kaj ti je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 25, 'Sinovi Danovi pa mu reko: Ne nadleguj nas s svojim vpitjem, da se ne spuste nad vas razkačeni možje, in izgubiš življenje svoje in družine svoje življenje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 26, 'In sinovi Danovi gredo svojim potem; Miha pa, videč, da mu so premočni, se obrne in gre nazaj v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 27, 'Oni pa, ko so vzeli to, kar je bil Miha naredil, in njega, ki mu je bil duhovnik, pridejo v Lais nad ljudstvo pokojno in brezskrbno in ga udarijo z ostrino meča, in mesto zažgo z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 28, 'In ni jim bilo rešitelja, zakaj daleč je bilo od Sidona in niso imeli zveze z drugimi ljudmi; in bilo je v dolini, ki se vije proti Bet-rehobu. Oni pa zopet sezidajo mesto in se nastanijo v njem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 29, 'in mu dado ime Dan, po imenu očeta svojega Dana, ki se je rodil Izraelu; a poprej se je mesto imenovalo Lais.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 30, 'In sinovi Danovi so si ondi postavili tisto rezano podobo. In Jonatan, sin Gersona, sina Mojzesovega, on in sinovi njegovi so bili duhovniki rodu Danovemu do časa, ko so šli v jetništvo prebivalci dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 18, 31, 'Tako so si postavili Mihovo rezano podobo, ki jo je bil naredil, in stala je ves čas, dokler je bila hiša Božja v Silu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 1, 'In v tistih dneh, ko ni bilo kralja v Izraelu, se zgodi, da si neki levit, ki je bival v zadnji strani Efraimskega gorovja, vzame priležnico iz Betlehema Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 2, 'Ta priležnica pa je proti njemu nečisto živela in mu je pobegnila v svojega očeta hišo, v Betlehem Judov, in ondi je bila štiri mesece.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 3, 'Tedaj se vzdigne njen mož in gre za njo, da bi ji govoril na srce in jo pripeljal nazaj; in s seboj je imel hlapca in dva osla. In ona ga vpelje v svojega očeta hišo. Ko ga vidi dekletin oče, ga sprejme z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 4, 'In tast njegov, dekletin oče, ga je zadržal, da je ostal pri njem tri dni; in jedli so in pili in ondi nočevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 5, 'Četrti dan pa vstanejo zgodaj zjutraj in se odpravljajo na pot. A dekletin oče reče možu hčere svoje: Okrepčaj si dušo z grižljajem kruha, potem pojdite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 6, 'Sedeta torej in jesta in pijeta obadva skupaj; in dekletin oče reče možu: Izvoli, prosim, ostati čez noč, in srce ti bodi dobre volje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 7, 'A mož vstane in hoče iti. Ali tast njegov ga primora, da se vrne in ondi prenoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 8, 'Zarana petega dne pa vstane, da odrine. A dekletin oče veli: Okrepčaj si, prosim, dušo in pomudite se, dokler se dan nagne. In jesta obadva vkup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 9, 'In ko mož vstane, da odide s priležnico svojo in s hlapcem svojim, mu reče tast njegov, dekletin oče: Glej, dan se je že nagnil, večer nastaja, ostanite tu, prosim, čez noč; glej, dan skoraj mine, prenoči tu in srce ti bodi dobre volje! In jutri se odpravite zgodaj na svoj pot, da prideš na dom svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 10, 'A mož ni hotel ostati to noč, temuč vstane in odide in dospe proti Jebusu (ki je Jeruzalem) in ž njim dva obložena osla in priležnica njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 11, 'Ko pa pridejo blizu Jebusa, je dan skoraj minil. In hlapec reče gospodarju svojemu: Pojdi, prosim, krenimo v to mesto Jebusejcev in prenočimo v njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 12, 'Gospodar pa mu reče: Ne pojdemo v mesto tujcev, ki ni od sinov Izraelovih, ampak pojdimo dalje v Gibeo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 13, 'Še reče hlapcu svojemu: Pojdi, da se prihližamo nekateremu teh selišč in prenočimo v Gibei ali v Rami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 14, 'Gredo torej naprej svojim potem, in solnce jim zaide prav pri Gibei, ki je last Benjaminova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 15, 'In krenejo tja, da prenočijo v Gibei. In ko pride noter, sede na ulico v mestu; in ni bilo nikogar, ki bi jih vzel čez noč pod streho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 16, 'Ali glej, star mož prihaja zvečer s polja od dela svojega, in ta mož je tudi bil z Efraimskega gorovja in je bival kot tujec v Gibei; ljudje tega mesta pa so bili Benjaminci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 17, 'In ko povzdigne oči in zagleda popotnika na ulici, reče tisti starec: Kam si namenjen? in odkod prihajaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 18, 'In mu odgovori: Gremo iz Betlehema Judovega na zadnjo stran Efraimskega gorovja, odkoder sem. Potoval sem pa v Betlehem Judov in zdaj grem k hiši Gospodovi, a nikogar ni, ki bi me vzel pod streho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 19, 'Saj imamo slame in krme za osla svoja, tudi kruha in vina zame in za deklo tvojo in za hlapca, ki je s služabnikoma tvojima; ne manjka nam ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 20, 'Stari mož reče: Mir ti! Vsekakor naj oskrbim jaz, česar ti treba; le na ulici ne nočuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 21, 'In ga vpelje v hišo svojo in da osloma krme, in umijejo si noge, in jedli so in pili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 22, 'In ko je njih srce bilo že dobre volje, glej, mestni možje, hudobni zanikarneži, obsujejo hišo in tolčejo ob duri in govore hišnemu gospodarju, tistemu starcu: Pripelji ven moža, ki je prišel v hišo tvojo, da ga spoznamo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 23, 'In mož, hišni gospodar, gre ven k njim in jim reče: Nikar, bratje moji, ne storite hudega, prosim; potem ko je ta mož stopil v hišo mojo, ne počenjajte nesramnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 24, 'Glejte, moja hči, še devica, in njegova priležnica: ti naj vam pripeljem ven, in osramotite ju in jima storite, kar vam ugaja; ali zoper tega moža ne storite take nesramnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 25, 'A možje ga niso hoteli poslušati. Tedaj zgrabi mož priležnico svojo in jim jo pripelje ven; in so jo spoznali in nesramno ž njo ravnali celo noč do jutra, in so jo šele pustili, ko se je dan zasvetil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 26, 'In žena pride ob svitu in pade ob vhodu v moževo hišo, kjer je bil njen gospodar, in tam leži do svetlega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 27, 'Njen gospodar pa vstane zjutraj in odpre hišna vrata in stopi ven, da pojde svojim potem, in glej, žena, priležnica njegova, leži pred vrati hiše in roke njene na pragu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 28, 'In ji veli: Vstani, pojdimo! A ni bilo odgovora. Tedaj jo mož vzame na osla, in vstane in odrine v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 29, 'In ko pride domov, vzame nož in zgrabi priležnico svojo ter jo razseka po njenih kosteh na dvanajst kosov in jih pošlje v vse Izraelove kraje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 19, 30, 'In vsi, ki so videli, so rekli: Kaj takega se ni storilo in se ni videlo od časa, ko so Izraelovi sinovi odšli iz Egiptovske dežele, do tega dne. Pomislite to, dajte svet in govorite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 1, 'Nato se odpravijo vsi sinovi Izraelovi, in vsa občina se zbere kakor en mož, od Dana tja do Bersebe, z Gileadsko pokrajino, pred Gospodom v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 2, 'In poglavarji vsega ljudstva, vseh rodov Izraelovih, so se sešli v zboru ljudstva Božjega, štiristo tisoč pešcev, ki so izdirali meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 3, 'Sinovi Benjaminovi so pa slišali, da so se sešli sinovi Izraelovi gori v Micpi. In sinovi Izraelovi reko: Povejte, kako se je zgodilo to zlo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 4, 'In levit, mož žene, ki je bila umorjena, odgovori in reče: Prišel sem s priležnico svojo v Gibeo, ki je Benjaminova, da bi tam prenočil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 5, 'A meščani v Gibei so se vzdignili zoper mene in so po noči obdali hišo zaradi mene; mene so mislili umoriti, mojo priležnico pa so sramotili, da je umrla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 6, 'Tedaj sem vzel priležnico svojo in jo razkrojil v kose in razposlal po vsej deželi dediščine Izraelove; kajti storili so grdobo in nesramnost v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 7, 'Poglejte, vi vsi sinovi Izraelovi, govorite tu in dajte svet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 8, 'Tedaj vstane vse ljudstvo kakor en mož in reče: Nihče izmed nas ne sme iti v šator svoj, nihče naj se ne vrne v hišo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 9, 'A to zdaj storimo Gibei: pojdemo proti njim, kakor določi kocka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 10, 'Vzemimo po deset mož iz sto in po sto iz tisoč in po tisoč iz deset tisoč od vseh rodov Izraelovih, da prinašajo hrano ljudstvu, ki naj gre nad Gibeo Benjaminovo in jim stori, kakor zasluži njih nesramnost, ki so jo storili v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 11, 'Tedaj so se zbrali vsi Izraelovi možje zoper tisto mesto, združeni kakor en mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 12, 'In Izraelovi rodovi pošljejo može po vseh Benjaminovih rodovinah, da sporoče: Kakšna hudobnost je to, ki se je med vami zgodila?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 13, 'Sedaj pa nam izročite tiste hudobne zanikarneže, ki so v Gibei, da jih usmrtimo in odpravimo hudobo izmed Izraela! A Benjaminci niso hoteli slušati glasu bratov svojih, sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 14, 'Ampak sinovi Benjaminovi se zbero iz svojih mest pri Gibei, da bi šli v boj zoper sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 15, 'In tisti dan so bili sešteti sinovi Benjaminovi iz mest: šestindvajset tisoč mož, ki so izdirali meč, razen prebivalcev v Gibei, katerih je bilo naštetih sedemsto izbraniln mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 16, 'Med vsem tem ljudstvom je bilo sedemsto izbranih mož, levičnikov; vsi so znali s pračo kamene v las metati, ne da bi zgrešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 17, 'In mož Izraelovih, brez Benjamincev, je bilo seštetih štirikrat sto tisoč mož, ki so izdirali meč; vsi ti so bili vojščaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 18, 'In sinovi Izraelovi vstanejo in gredo gori v Betel in vprašajo Boga in reko: Kdo naj gre iz nas prvi vojskovat se s sinovi Benjaminovimi? In Gospod veli: Juda naj gre prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 19, 'Zjutraj torej vstanejo sinovi Izraelovi in se utabore proti Gibei.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 20, 'In možje Izraelovi gredo v boj zoper Benjamince in se razvrste v bitko ž njimi pri Gibei.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 21, 'Sinovi Benjaminovi pa planejo iz Gibee in tisti dan pobijejo na tla iz Izraelcev dvaindvajset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 22, 'Ali ljudstvo, možje Izraelovi, se ohrabre med seboj in se zopet razvrste v bitko ob kraju, kjer so se razvrstili prvi dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 23, 'In Izraelovi sinovi so šli gori in plakali pred Gospodom do večera in vprašali so Gospoda, rekoč: Ali naj zopet grem bojevat se s sinovi Benjamina, brata svojega? Gospod veli: Pojdite gori zoper nje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 24, 'In sinovi Izraelovi se približajo Benjaminovim sinovom drugi dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 25, 'In Benjaminci planejo proti njini iz Gibee drugi dan, in zopet pobijejo na tla iz sinov Izraelovih osemnajst tisoč mož, ki so vsi izdirali meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 26, 'Nato gredo gori vsi sinovi Izraelovi in vse ljudstvo in pridejo v Betel in plakajo in ostanejo ondi pred Gospodom, in so se postili tisti dan do večera in so darovali žgalne in mirovne daritve pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 27, 'In sinovi Izraelovi vprašajo Gospoda (zakaj skrinja zaveze Božje je tam bila v tistih dneh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 28, 'in Pinehas, sin Eleazarja, sina Aronovega, je stal pred njo tiste dni), rekoč: Ali naj zopet grem, da se bojujem s sinovi Benjamina, brata svojega, ali naj mirujem? In Gospod veli: Pojdite gori, zakaj jutri vam jih dam v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 29, 'In Izrael postavi zasede proti Gibei vseokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 30, 'Nato gredo sinovi Izraelovi gori proti Benjaminovim sinovom tretji dan in razvrste se zoper Gibeo kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 31, 'In sinovi Benjaminovi pridero proti ljudstvu, in ko se oddaljijo od mesta, začno pobijati nekatere iz ljudstva kakor poprej ob cestah, katerih ena gre gori v Betel, druga pa v Gibeo na polju, in usmrte okoli trideset mož iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 32, 'Tedaj reko sinovi Benjaminovi: Padajo pred nami kakor prvikrat. A sinovi Izraelovi reko: Bežimo, da jih odpeljemo od mesta na ceste!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 33, 'In vstanejo sinovi Izraelovi s svojega kraja in se razvrste pri Baaltamarju; Izraelci, skriti v zasedi, pa planejo s svojega mesta, s planjave Gebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 34, 'In pridere proti Gibei deset tisoč izbranih mož iz vsega Izraela, in bitka je postala trda, a oni niso vedeli, da hiti nesreča nadnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 35, 'In Gospod je udaril Benjamina pred sinovi Izraelovimi, da so sinovi Izraelovi pobili tisti dan iz Benjamincev petindvajset tisoč in sto mož, ki so vsi izdirali meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 36, 'In sinovi Benjaminovi so videli, da so poraženi. Kajti možje Izraelovi so dali Benjamincem prostora, ker so se zanesli na zasede, ki so jih bili postavili proti Gibei.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 37, 'In zasedniki so hiteli in naskočili Gibeo in so se namerili na mesto in vse pobili z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 38, 'Dogovorili so se pa možje Izraelovi z zasedniki, da napravijo, da se vali kvišku velik dim iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 39, 'In obrnejo se možje Izraelovi v bitki, in Benjaminci jih začno biti in pomore iz Izraela okoli trideset mož; mislili so namreč: Zopet so poraženi pred nami kakor v prejšnji bitki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 40, 'Ko pa se iz mesta začne dim dvigati kakor steber, se Benjaminci ozro, in glej, vse mesto gre v plamenu proti nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 41, 'V tem se obrnejo možje Izraelovi, in možje Benjaminovi se prestrašijo, zakaj videli so, da jih je nesreča dohitela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 42, 'Krenili so sicer pred možmi Izraelovimi na pot k puščavi, ali vojska je pritiskala za njimi; in tisti, ki pridejo iz mest, jih obkolijo in pobijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 43, 'In obsujejo Benjamince od vseh strani, jih podijo in jih poteptajo na njih počivališču tja do one strani ob Gibei proti solnčnemu vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 44, 'In padlo je iz Benjamina osemnajst tisoč mož, vsi ti so bili hrabri možje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 45, 'In obrnejo se in beže proti puščavi, k Rimonski skali. Ali na tej cesti so jih pobili pet tisoč mož in so jim bili trdo za petami tja do Gidoma in so pobili izmed njih dva tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 46, 'Tako je bilo vseh, ki so tisti dan padli iz Benjamina, petindvajset tisoč mož, ki so izdirali meč in so bili vsi hrabri možje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 47, 'Samo šeststo mož se obrne in zbeži v puščavo, k Rimonski skali, in ostanejo na Rimonski skali štiri mesece.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 20, 48, 'A možje Izraelovi se zopet obrnejo na sinove Benjaminove in pobijejo z ostrino meča, kar jih je bilo v mestu, živino in vse, kar zasačijo; tudi vsa mesta, na katera so naleteli, požgo z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 1, 'In možje Izraelovi so prisegli v Micpi, rekoč: Nihče izmed nas ne sme dati hčere svoje Benjamincu za ženo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 2, 'In ljudstvo pride v Betel in sedi ondi pred Bogom do večera, in povzdignejo glasove svoje in silno plakajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 3, 'In reko: O Gospod, Bog Izraelov, zakaj se je zgodilo to v Izraelu, da danes manjka enega rodu v Izraelu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 4, 'Drugo jutro pa vstane ljudstvo zgodaj, in zgrade ondi oltar in darujejo žgalne in mirovne žrtve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 5, 'In sinovi Izraelovi reko: Je li kdo iz vseh rodov Izraelovih, ki ni prišel sem v zbor h Gospodu? Zakaj izrekli so bili veliko prokletje nad onim, ki ne bi prišel gori v Micpo h Gospodu, rekši: Gotovo mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 6, 'In sinovi Izraelovi so se kesali zaradi Benjamina, brata svojega, in dejali: Danes je bil odsekan en rod od Izraela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 7, 'Kako naj storimo, da tisti, ki so ostali, dobodo žene? Kajti prisegli smo pri Gospodu, da jim od svojih hčera ne damo žen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 8, 'Zato vprašajo: Ali je kdo iz rodov Izraelovih, ki ni prišel gori h Gospodu v Micpo? In glej, nihče ni prišel iz Jabesa v Gileadu v tabor k zborovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 9, 'Kajti ko so prešteli ljudstvo, glej, ni bilo ne enega iz prebivalcev v Gileadskem Jabesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 10, 'In pošlje občina tja dvanajst tisoč najboljših junakov in jim zapove, rekoč: Pojdite in pobijte z ostrino meča prebivalce v Gileadskem Jabesu z ženami in otročiči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 11, 'Ali to je stvar, ki jo storite: Pomorite vse moške in vsako ženo, ki se je združila z možem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 12, 'In dobe med prebivalci v Gileadskem Jabesu štiristo hčera, ki so bile device in niso poznale moža v združenju; te pridejo v tabor v Silo, ki je v Kanaanski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 13, 'In pošlje vsa občina in naroči govoriti s sinovi Benjaminovimi, ki so bili na Rimonski skali, in jim ponudi mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 14, 'Benjaminci se torej vrnejo tisti čas, in oni jim dado žene, ki so jih ohranili pri življenju izmed žen v Gileadskem Jabesu; toda ni jih jim bilo zadosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 15, 'In ljudstvo se je kesalo zaradi Benjamina, ker je Gospod storil pretrgo v rodovih Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 16, 'Tedaj reko starejšine občine: Kako naj storimo, da dobé preostali žene, ker so žene iztrebljene iz Benjamina?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 17, 'In reko: Dediščina mora ostati tistim, ki so zbežali iz Benjamina, da se ne zatre rod iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 18, 'Toda mi jim ne moremo dati hčer svojih za žene; zakaj sinovi Izraelovi so prisegli, rekoč: Proklet bodi, kdor da ženo Benjamincem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 19, 'Reko torej: Glejte, praznik Gospodov je vsako leto v Silu, ki je severno od Betela, na vzhodni strani ceste, ki drži iz Betela gori v Sihem, in južno od Lebone.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 20, 'In naroče sinovom Benjaminovim, rekoč: Pojdite in prežite po vinogradih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 21, 'Ko boste pa videli, da gredo hčere iz Sila na ples, planite iz vinogradov in si vsak ulóvi ženo iz silskih hčera ter odidite v deželo Benjaminovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 22, 'Ko pa pridejo njih očetje ali bratje pravdat se z nami, jim porečemo: Dajte jih v darilo nam; kajti za vsakega nismo dobili žene v boju; saj njim jih niste dali, sicer bi zdaj bili krivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 23, 'In sinovi Benjaminovi so storili tako in si vzeli žene, po številu svojem, iz plesalk, ki so jih ugrabili, in šli so in se vrnili v dediščino svojo in so zgradili mesta ter prebivali v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 24, 'Sinovi Izraelovi so se pa razšli odtod tisti čas, vsak v svoj rod in k rodovini svoji, in vsak je šel odtod v dediščino svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (7, 21, 25, 'V tistih dneh ni bilo kralja v Izraelu: vsakdo je delal, kar se mu je zdelo prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 1, 'In zgodi se v dneh, ko so sodniki vladali, da nastane lakota v deželi. In neki mož iz Betlehema Judovega odide, da prebiva kot tujec na Moabski poljani, on in žena njegova in dva sinova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 2, 'Možu pa je bilo ime Elimelek in ženi njegovi Naomi, njegova dva sinova pa sta se imenovala Mahlon in Kiljon, Efratejca iz Betlehema Judovega. In prišli so na Moabsko poljano in bivali ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 3, 'Elimelek pa, Naomin mož, je umrl, in ona je ostala z dvema sinoma svojima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 4, 'Ta si vzameta ženi Moabki, eni je bilo ime Orfa in drugi Ruta. In prebivali so ondi blizu deset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 5, 'Potem umrjeta obadva, Mahlon in Kiljon, in žena ostane za dvema sinoma svojima in za možem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 6, 'Tedaj vstane ona z dvema snahama svojima, da bi se povrnila z Moabske poljane; slišala je namreč v kraju moabskem, da je Gospod obiskal ljudstvo svoje, ko mu je dal kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 7, 'Odpravi se torej iz mesta, kjer je bivala, in ž njo dve snahi njeni, in nastopijo pot, da se vrnejo v deželo Judovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 8, 'In Naomi reče dvema snahama svojima: Pojdita in vrnita se, vsaka v svoje matere hišo! Gospod stóri vama milost, kakor ste jo storili mrtvima in meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 9, 'Daj vama Gospod, da najdeta pokoj, vsaka v svojega moža hiši. In ju poljubi. Oni pa povzdigneta glas svoj in jočeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 10, 'In ji rečeta: Nikar, ampak vrneva se s teboj k ljudstvu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 11, 'Naomi pa reče: Vrnita se, hčerki moji! Čemu bi hoteli z menoj iti? Nosim li še sinove v telesu svojem, ki bi vam bili možje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 12, 'Vrnita se, hčerki moji, in pojdita! Prestara sem že, da bi vzela moža. In ko bi tudi rekla: Upam, da dobim še to noč moža in porodim sinove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 13, 'bosta li hoteli čakati, dokler odrastejo? hočeta li zaradi njih odlašati, da ne bi vzeli moža? Ne, hčerki moji! zakaj meni je veliko bridkejše nego vama, ker roka Gospodova je iztegnjena zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 14, 'In oni povzdigneta glas svoj in jočeta še bolj. Orfa pa poljubi taščo svojo in odide. A Ruta se je oklene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 15, 'Ona pa reče: Glej, jetrva tvoja se je vrnila k svojemu ljudstvu in k svojemu bogu; vrni se tudi ti za jetrvo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 16, 'Ruta odgovori: Nikar me ne sili, da te zapustim in se obrnem, da ne bi šla za teboj! Ker kamor ti greš, hočem iti tudi jaz, in kjerkoli ostaneš, ostanem tudi jaz: tvoje ljudstvo je ljudstvo moje, in tvoj Bog je moj Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 17, 'Kjer umrješ, umrjem tudi jaz in ondi hočem biti pokopana. Gospod mi stóri to in ono, če sama smrt ne loči mene in tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 18, 'Ko torej vidi, da se je trdno namenila iti ž njo, neha jo odvračati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 19, 'In šli sta obedve, da sta dospeli v Betlehem. In zgodi se, ko prideta v Betlehem, da se vznemiri zanju vse mesto, in žene so dejale: Je li ta Naomi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 20, 'Ona pa reče: Ne imenujte me Naome, ampak kličite me Maro, ker me je Vsegamogočni prenapolnil z bridkostjo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 21, 'Polna sem šla odtod, a prazno me je pripeljal domov Gospod. Zakaj mi pravite Naomi, ker me je ponižal Gospod in Vsegamogočni mi hudo storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 1, 22, 'Tako se je vrnila Naomi in ž njo Ruta Moabka, njena snaha, ki je odšla z Moabske poljane; in dospeli sta v Betlehem, prav ko se je ječmenova žetev začela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 1, 'Imela je pa Naomi sorodnika po možu svojem, vrlega in bogatega moža, iz rodovine Elimelekove, in ime mu je bilo Boaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 2, 'In Ruta Moabka reče Naomi: Dovoli, naj grem na polje in pobiram klasje za njim, v čigar očeh najdem milost. Ona ji veli: Pojdi, moja hči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 3, 'Nato gre in pride in pobira za ženjci na polju. In prigodi se ji, da zaide na njivo Boazovo, ki je bil iz Elimelekove rodovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 4, 'In glej, Boaz pride iz Betlehema in reče ženjcem: Gospod bodi z vami! In oni mu odzdravijo: Blagoslovi te Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 5, 'Nato vpraša Boaz hlapca svojega, ki je bil postavljen čez ženjce: Čigava je ta mladenka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 6, 'Hlapec, ki je bil postavljen nad ženjci, odgovori: Mladenka je Moabka, ki je prišla z Naomo nazaj z Moabske poljane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 7, 'In mi je dejala: Naj pobiram, prosim, in spravljam med snopjem, za ženjci; in je prišla in vztrajala od jutra do sedaj, samo da je prav malo doma posedela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 8, 'Tedaj reče Boaz Ruti: Slišiš li, hči moja? Ne pojdi na drugo njivo pobirat, tudi ne hodi odtod, ampak pridruži se deklam mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 9, 'Glej, na kateri njivi žanjejo, in pojdi tja za njimi! Ali nisem zapovedal mladeničem, naj se te nihče ne dotakne? In kadar boš žejna, pojdi k posodam in pij, kar moji hlapci zajemajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 10, 'Tedaj pade ona na obličje svoje in se prikloni do tal in mu reče: S čim sem našla milost pred očmi tvojimi, da se prijazno oziraš po meni, ki sem tujka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 11, 'Boaz odgovori in ji reče: Natanko mi je bilo povedano vse, kar si storila tašči svoji, odkar ti je umrl mož, in kako si zapustila svojega očeta in mater svojo in zemljo, ki si v njej rojena, in si šla k ljudstvu, ki ga poprej nisi nič poznala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 12, 'Gospod ti poplačaj delo tvoje, in popolno povračilo ti pridi od Gospoda, Izraelovega Boga, ki si prišla k njemu, da imaš pribežališče pod perutmi njegovimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 13, 'In ona reče: Gospod moj, naj najdem milost v očeh tvojih; zakaj ti si me potolažil in na srce govoril dekli svoji, čeprav nisem kakor ena dekel tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 14, 'In ko je bil čas jedi, ji veli Boaz: Pridi sem in jej kruh in omakaj grižljaj svoj v kisu. In ona sede poleg ženjcev. In poda ji opraženega zrnja, in jedla je in se nasitila in ostanke shranila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 15, 'In ko vstane, da zopet pobira, ukaže Boaz hlapcem svojim, rekoč: Dajte, da pobira tudi med snopjem, in je nikar ne sramotite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 16, 'Tudi nalašč potegujte zanjo klasje iz snopkov in pustite na tleh, da pobira, in nihče je zato ne svari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 17, 'Tako je pobirala na polju do večera; in iztolkla je, kar je nabrala, in bilo je okoli efe ječmena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 18, 'In vzame to in gre v mesto; in njena tašča je videla, koliko je nabrala; in izname in ji poda, kar ji je preostalo, ko se je bila nasitila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 19, 'Nato ji reče tašča njena: Kod si danes pobirala in kje si delala? Blagoslovljen bodi, ki se je prijazno ozrl nate! In pove tašči svoji, pri kom je delala, in reče: Ime možu, pri katerem sem danes delala, je Boaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 20, 'In Naomi reče snahi svoji: Blagoslovljen bodi od Gospoda, čigar milost ne zapusti ne živih, ne mrtvih! Še ji pove Naomi: Ta mož je bližji sorodnik najin, eden teh, ki jim gre pravica odkupiti naju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 21, 'In Ruta Moabka reče: Tudi to mi je velel: Vztrajaj pri hlapcih mojih, dokler ne požanjejo vsega, kar je moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 22, 'Naomi pa reče snahi svoji Ruti: Dobro je, hči moja, da hodiš ven z deklami njegovimi, da te ne žalijo na kateri drugi njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 2, 23, 'Tako se je družila, pobirajoč klasje, Boazovim deklam, dokler ni minila ječmenova in pšenična žetev, in je prebivala s taščo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 1, 'Naomi pa, njena tašča, ji reče: Hči moja, ni li treba, da ti poiščem počitka, da se ti bo dobro godilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 2, 'In sedaj, ni li Boaz, s čigar deklami si bila, sorodnik naš? Glej, nocoj veja ječmen na gumnu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 3, 'Izkoplji se torej in se pomazili in obleci svoja oblačila, pa pojdi doli na gumno; a ne daj se spoznati možu, dokler ne neha jesti in piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 4, 'In ko potem pojde leč, zapomni si mesto, kam leže, pa pojdi tja ter odgrni odejo pri nogah njegovih in lezi; in on ti pove, kaj naj storiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 5, 'Ona ji reče: Vse, kar mi praviš, hočem storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 6, 'In odide doli na gumno in stori vse, kakor ji je bila velela tašča njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 7, 'Ko pa se je Boaz najedel in napil in srce mu je bilo dobre volje, pride in leže za kopico snopja; in ona pride tiho in odgrne odejo pri nogah njegovih in leže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 8, 'In zgodi se opolnoči, da se mož prestraši in se obrne, kajti glej, žena mu leži pri nogah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 9, 'In vpraša: Kdo si ti? Ona pa odgovori: Jaz sem Ruta, dekla tvoja; razprostri perut svojo čez svojo deklo, zakaj odkupitelj si mi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 10, 'A on reče: Blagoslovljena bodi od Gospoda, hči moja! Zdaj si se pa še milostnejša izkazala nego poprej, ker nisi hodila za mladeniči, ne za ubogimi, ne za bogatimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 11, 'Sedaj pa, hči moja, nič se ne boj! Vse ti storim, kar praviš, zakaj vse mesto ljudstva mojega ve, da si krepostna žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 12, 'In res je tudi, da sem odkupitelj; toda je odkupitelj bliže soroden nego jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 13, 'Počakaj to noč! Ako ti bo jutri hotel storiti sorodniško dolžnost, dobro, naj te odkupi. Če ga pa ne bo volja storiti ti sorodniško dolžnost, hočem te odkupiti jaz, kakor res Gospod živi! Ostani tu do jutra!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 14, 'In ležala je pri nogah njegovih do jutra. Potem vstane, preden je mogel kdo drugega spoznati. Zakaj on je dejal: Da bi tega kdo ne zvedel, da je prišla žena na gumno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 15, 'In veli ji: Podaj sem plašč, ki ga imaš na sebi, in drži ga. In ga drži, in on ji nameri vanj šest meric ječmena in ji ga zadene, ter odide v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 16, 'In ko pride k tašči svoji, reče ta: Kako je s teboj, hči moja? In ona ji pove vse, kar ji je storil tisti mož,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 17, 'in reče: Teh šest meric ječmena mi je dal, zakaj, rekel je: Prazna ne smeš iti k tašči svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 3, 18, 'Ona pa ji reče: Le mirna bodi, hči moja, dokler ne zveš, kako se stvar konča; zakaj ta mož si ne da pokoja, dokler ne dožene stvari še danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 1, 'Boaz pa je šel gori v mestna vrata in je sedel ondi; in glej, sorodnik – odkupitelj, ki je govoril Boaz o njem, gre mimo. Tedaj mu reče: Hej, ti, stopi sem in tu sedi! In krene tja in sede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 2, 'In Boaz pokliče deset mož iz mestnih starejšin in reče: Sedite tukaj! In so sedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 3, 'Nato ogovori sorodnika: Naomi, ki se je vrnila z Moabske poljane, ima naprodaj kos polja, ki je bil našega brata Elimeleka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 4, 'in hotel sem ti to razodeti in te pozvati: Kupi ga vpričo njih, ki tu sede, in vpričo starejšin mojega ljudstva. Če ga hočeš odkupiti, ga odkupi; ako pa ga nočeš odkupiti, povej mi, da vem; kajti ni ga, ki bi ga odkupil, razen tebe, in jaz sem za tabo. On odgovori: Hočem ga odkupiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 5, 'Na to veli Boaz: Kateri dan kupiš tisto polje iz roke Naomine, ga tudi pridobiš od Rute Moabke, žene umrlega sorodnika, da obudiš ime mrtvega za dediščino njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 6, 'In sorodnik reče: Ne morem ga odkupiti, da ne skazim svoje dediščine. Odkupi zase, kar bi moral odkupiti jaz, ker jaz ne morem odkupiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 7, 'Bila pa je v starih časih navada v Izraelu, če se je kaj kupilo ali zamenjalo, da se potrdi vsaka reč: da je mož sezul čevelj svoj in ga dal drugemu. To je bilo v potrdilo v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 8, 'Tako je rekel sorodnik Boazu: Kupi ga zase! In sezul je čevelj svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 9, 'Tedaj reče Boaz starejšinam in vsemu ljudstvu: Priče ste danes, da sem kupil vse, kar je bilo Elimelekovo, in vse, kar je bilo Kiljonovo in Mahlonovo, iz roke Naomine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 10, 'Vrhutega sem pridobil Ruto Moabko, ženo Mahlonovo, da bodi moja žena, da obudim ime umrlega za dediščino njegovo, da ne izgine ime mrtvega izmed bratov njegovih in iz vrat mesta njegovega. Temu ste priče danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 11, 'In vse ljudstvo, ki je bilo v vratih, in starejšine reko: Priče smo. Gospod stóri, da bodi žena, ki pride v hišo tvojo, kakor Rahela in Leja, kateri dve sta postavili dom Izraelov! In pridóbi krepost v Efrati in ime si ustanóvi v Betlehemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 12, 'In naj bode hiša tvoja kakor hiša Pereza, ki ga je Tamara rodila Judi, iz zaroda, ki ti ga da Gospod od te mlade žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 13, 'Vzame torej Boaz Ruto, in bila je žena njegova; in gre k njej, in Gospod ji da, da je spočela in rodila sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 14, 'In žene reko Naomi: Hvaljen bodi Gospod, ki te danes ni pustil brez odkupitelja, čigar ime naj bo slovelo v Izraelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 15, 'On poživi dušo tvojo in te bo podpiral v starosti tvoji; zakaj snaha tvoja, ki te ljubi, ga je rodila, in ona ti je boljša nego sedem sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 16, 'In Naomi vzame dete in si ga položi na kolena, in mu je bila pestunja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 17, 'In njene sosedinje so mu dale ime, rekoč: Rodil se je sin Naomi; in so ga imenovale Obeda. On je oče Jeseja, očeta Davidovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 18, 'Ti pa so rodovi Perezovi: Perez je rodil Hezrona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 19, 'Hezron je rodil Rama, in Ram je rodil Aminadaba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 20, 'Aminadab pa je rodil Nahsona, in Nahson je rodil Salmona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 21, 'Salmon pa je rodil Boaza, Boaz pa je rodil Obeda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (8, 4, 22, 'Obed pa je rodil Jeseja, in Jesej je rodil Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 1, 'Bil je mož iz Ramataim-zofima, z Efraimskega gorovja, ki mu je bilo ime Elkana, sin Jerohama, sina Elihuja, sina Tohuja, sina Zufovega, Efraimec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 2, 'In imel je dve ženi, eni je bilo ime Ana, drugi pa Penina; in Penina je imela otroke, Ana pa ni imela otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 3, 'In ta mož je hodil vsako leto gori iz mesta svojega, da bi molil in daroval Gospodu nad vojskami v Silu. Ondi sta bila duhovnika Gospodu dva sinova Elijeva, Ofni in Pinehas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 4, 'In kadar je prišel dan, da je Elkana daroval, je dal deleže Penini, ženi svoji, in vsem sinovom in hčeram njenim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 5, 'Ali Ani je dal dvojen delež, ker Ano je ljubil, a Gospod ji je zaprl maternico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 6, 'In njena soporočenka jo je hudo žalila, da bi jo ujezila, ker ji je bil Gospod zaprl maternico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 7, 'In ker je delal tisto vsako leto, kadarkoli je šla v hišo Gospodovo, jo je tako žalila; in Ana je plakala in ni ničesar jedla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 8, 'In Elkana, njen mož, ji reče: Ana, zakaj plačeš? in zakaj ne ješ? in zakaj ti je srce žalostno? Nisem li jaz boljši tebi nego deset sinov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 9, 'In vstala je Ana, potem ko so jedli in pili v Silu. In Eli duhovnik je sedel na stolu svojem pri podboju Gospodovega templja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 10, 'In njej je bilo bridko v duši, in molila je h Gospodu in silno jokala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 11, 'In stori obljubo in reče: O Gospod nad vojskami, ako se milo ozreš na ponižanje dekle svoje in se me spomniš in ne pozabiš dekle svoje, a daš dekli svoji moški zarod, tedaj ga posvetim Gospodu za vse žive dni njegove, in britev naj ne pride na glavo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 12, 'In ko je dolgo molila pred Gospodom, je Eli pazil na usta njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 13, 'Ana namreč je govorila v srcu svojem, le njena ustnica se je gibala, toda glasu njenega ni bilo slišati. Zato je Eli menil, da je vinjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 14, 'In ji reče Eli: Doklej boš pijana? Iztrezni se od vina svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 15, 'Ana pa odgovori ter reče: Nikar, gospod moj, žena sem otožnega duha; vina in močne pijače nisem pila, temuč srce svoje sem izlila pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 16, 'Ne rači šteti dekle svoje za hčer Belijalovo, zakaj od velikega žalovanja in razžaljenja sem doslej govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 17, 'Eliji odgovori in veli: Pojdi v miru! Bog Izraelov naj ti izpolni prošnjo, ki si jo prosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 18, 'Ona reče: Naj najde dekla tvoja milost v očeh tvojih! Nato je žena šla svojim potem, in je jedla in lice ji ni bilo več žalostno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 19, 'In zgodaj zjutraj vstanejo, in ko se poklonijo pred Gospodom, se napotijo nazaj in pridejo v hišo svojo v Rami. In Elkana spozna Ano, ženo svojo, in Gospod se je spomni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 20, 'In ko preteče čas, potem ko je Ana spočela, je rodila sina in ga imenovala Samuela, kajti „izprosila sem ga od Gospoda “.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 21, 'In ko je šel mož Elkana in vsa družina njegova, da prinese Gospodu vsakoletno daritev in obljubo svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 22, 'ni šla Ana ž njim, zakaj rekla je možu svojemu: Pojdem šele, ko bo deček odstavljen, potem ga popeljem, da se pokaže pred obličjem Gospodovim in ostane ondi vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 23, 'Elkana, mož njen, ji reče: Stóri, kakor se ti dobro vidi; ostani, dokler ga ne odstaviš! Samo da Gospod potrdi besedo svojo! In žena je ostala doma in dojila sina, dokler ga ni odstavila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 24, 'In ko ga je odstavila, ga je peljala s seboj gori s tremi junci in z eno efo moke in z mehom vina in ga je privedla v hišo Gospodovo v Silu; a deček je bil še mlad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 25, 'In zaklali so junca in pripeljali dečka k Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 26, 'In ona reče: Ah, gospod moj, kakor res živi duša tvoja, gospod moj, jaz sem tista žena, ki sem tu pri tebi stala in Gospoda prosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 27, 'Za tega dečka sem prosila, in Gospod mi je izpolnil prošnjo, ki sem jo prosila od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 1, 28, 'Zato ga tudi jaz izročam Gospodu; vse dni, dokler bo živel, je izročen Gospodu. In on se je ondi poklonil Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 1, 'In Ana je molila in rekla: Srce moje se raduje v Gospodu, rog moj je povišan po Gospodu; usta moja so se široko odprla zoper sovražnike moje, kajti veselim se zveličanja tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 2, 'Nihče ni tako svet kakor Gospod, kajti razen tebe ni nobenega; in ni nobene Skale, kakor je naš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 3, 'Ne množite govorov o visokih rečeh, predrznost naj ne pride iz vaših ust: kajti Gospod je Bog mogočni, ki vse pozna, in misli človeške na tehtnico deva on.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 4, 'Močnih lok je zlomljen, a slabotni so opasani z močjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 5, 'Kateri so bili siti, so v službo stopili za kruh, in kateri so lakoto trpeli, niso več lačni; in nerodovitna je rodila sedmero, in katera je veliko imela otrok, je onemogla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 6, 'Gospod mori in oživlja, pelje v kraj smrti in zopet nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 7, 'Gospod spravi v uboštvo in obogati, on ponižuje, pa tudi povišuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 8, 'On povišuje ubožca iz prahu, siromaka vzdiguje iz blata, da ga posadi med plemenitnike in mu da podedovati slave prestol; kajti Gospodovi so stebri zemlje, in on je nanje postavil svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 9, 'On bo varoval svojih svetnikov noge, ali brezbožniki umolknejo v temi; zakaj po svoji moči človek ne pride kvišku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 10, 'Zatrti bodo, kateri nasprotujejo Gospodu, zoper nje bo on grmel v nebesih. Gospod bo sodil kraje zemlje, in da moč kralju svojemu in poviša rog maziljenca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 11, 'In Elkana je šel v Ramo v hišo svojo. A deček je bil strežnik Gospodu pred očmi Elija duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 12, 'Sinova Elijeva pa sta bila otroka Belijalova; nista poznala Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 13, 'In navada duhovnikov proti ljudstvu je bila: Kadar je kdo prinesel daritev, je prišel, ko se je meso kuhalo, duhovnikov hlapec s trirogljatimi vilicami v roki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 14, 'in je ž njimi sunil v medenico ali v lonec ali v kotel ali v ponev, in karkoli je z vilicami izvlekel, je vzel duhovnik zase. Tako so delali v Silu vsem Izraelcem, ki so prihajali tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 15, 'Enako je prišel tudi, preden so zažgali tolstino, duhovnikov hlapec in rekel možu, ki je opravljal daritev: Daj mesa, da ga opečem duhovniku; zakaj ne bo vzel kuhanega mesa od tebe, temuč sirovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 16, 'Ako je rekel dotičnik: Saj bodo precej zažgali tolstino, potem vzemi, kolikor ti ugaja; tedaj mu je odgovoril: Ne, ampak daj mi ga zdaj, in če ne daš, vzamem s silo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 17, 'In greh mladeničev je bil silno velik pred Gospodom, kajti ljudje so zaničevali darila Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 18, 'Samuel pa je stregel pred obličjem Gospodovim, še deček, prepasan s platnenim naramnikom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 19, 'k temu mu je leto za letom napravila mati njegova suknjico in mu jo prinesla, ko je prišla gori z možem svojim opravljat vsakoletno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 20, 'In Eli je blagoslovil Elkana in ženo njegovo in rekel: Gospod ti daj zarod od te žene namesto darovanega, ki ga je izročila Gospodu! In šli so v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 21, 'In Gospod je obiskal Ano, da je spočela in rodila še tri sinove in dve hčeri. A deček Samuel je napredoval pri Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 22, 'Eli pa je bil silno star; in slišal je vse, kar počenjata sinova njegova z vsem Izraelom ter da se družita z ženami, ki so opravljale službo pri vratih shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 23, 'In dejal je jima: Zakaj to delata? slišim namreč o vajinih hudih dejanjih od vsega tega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 24, 'Nikar, sinova moja! zakaj to ni dober glas, ki ga slišim; povzročata, da Gospodovo ljudstvo prestopa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 25, 'Ako kdo greši zoper človeka, Bog mu je sodnik; ko pa kdo greši zoper Gospoda, kdo se potegne zanj? Ali nista poslušala glasu očeta svojega; kajti Gospod ju je hotel umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 26, 'A deček Samuel je vedno napredoval in je bil prijeten Gospodu in tudi ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 27, 'Pride pa mož Božji k Eliju in mu reče: Tako pravi Gospod: Nisem li se razodel očeta tvojega družini, ko so še bili v Egiptu, pri hiši Faraonovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 28, 'In njega sem si izvolil izmed vseh rodov Izraelovih, da bodi moj duhovnik, da daruje na mojem oltarju, da pali kadilo in naramnik nosi pred obličjem mojim; in očeta tvojega hiši sem dal vse daritve, ki jih po ognju darujejo sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 29, 'Zakaj teptate daritve moje in jedilna darila meni, ki sem jih zapovedal v prebivališču svojem? In sinova svoja bolj spoštuješ nego mene, da se redite z najboljšim od jedilnih daril Izraela, ljudstva mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 30, 'Zato pravi Gospod, Bog Izraelov: Rekel sem bil res, da naj bi hiša tvoja in tvojega očeta hiša hodili pred mano vekomaj; ali sedaj pravi Gospod: Ne bodi tako; zakaj tiste, ki me časte, počastim tudi jaz, in ki mene zaničujejo, malo jih bom cenil tudi jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 31, 'Glej, pridejo dnevi, da odsekam ramo tvojo in ramo hiši očeta tvojega, da ne bo starca v hiši tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 32, 'In videl boš le stisko prebivališča mojega, pri vsem dobrem, kar Bog dodeli Izraelu in priletnega ne bode v hiši tvoji vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 33, 'Nočem ti sicer slehernega zatreti od oltarja mojega, ker bi ti usahnile oči in duša ti skoprnela, ali vsa mladina hiše tvoje pomrje v moških letih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 34, 'In to ti bodi v znamenje, kar pride na oba sinova tvoja, Ofnija in Pinehasa: obadva umrjeta eden dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 35, 'In obudim si zvestega duhovnika, ki bo delal, kakor je po mojem srcu in po mojih mislih, in njemu sezidam stanovitno hišo; in hodil bo pred maziljencem mojim vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 2, 36, 'In zgodi se, da vsak, kdor preostane iz hiše tvoje, pride in se njemu pokloni za srebrn denar in hlebček kruha ter poreče: Prosim, pripusti me vsaj v eno duhovsko službo, da jem grižljaj kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 1, 'Deček Samuel pa je služil Gospodu pred Elijem. In beseda Gospodova je bila redka v tistih dneh, prikazen se ni ponavljala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 2, 'In zgodi se v tistem času, ko je Eli ležal na svojem mestu – oči njegove pa so bile že slabotne, da ni videl –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 3, 'in svetilnica Božja ni bila še ugasnjena, in Samuel je ležal ob svetišču Gospodovem, kjer je bila skrinja Božja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 4, 'da pokliče Gospod Samuela; in ta reče: Tu sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 5, 'In teče k Eliju in reče: Tu sem, ker si me klical. On veli: Nisem klical; vrni se in spi! In je šel in legel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 6, 'In Gospod zopet kliče: Samuel! In Samuel vstane ter pride k Eliju in reče: Tu sem, ker si me klical. Ta veli: Nisem klical, sin moj, vrni se in spi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 7, 'Samuel pa še ni poznal Gospoda, in beseda Gospodova mu še ni bila razodeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 8, 'In Gospod zopet kliče v tretje: Samuel! In vstane ter pride k Eliju in reče: Tu sem, ker si me klical. Tedaj spozna Eli, da je Gospod klical dečka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 9, 'Zato veli Eli Samuelu: Pojdi in spi! in če te še pokliče, reci: Govóri, Gospod, ker posluša hlapec tvoj. In Samuel odide in leže na svoje mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 10, 'In Gospod pride ter stoji in kliče kakor poprej: Samuel, Samuel! In Samuel reče: Govóri, ker posluša hlapec tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 11, 'In Gospod reče Samuelu: Glej, jaz storim stvar v Izraelu, da bo zvenelo v obeh ušesih vsakemu, kdor bo slišal o njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 12, 'Tisti dan uresničim proti Eliju vse, kar sem govoril o hiši njegovi; začnem to in dovršim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 13, 'Kajti povedal mu sem, da bom sodil hišo njegovo vekomaj zavoljo krivice, ki je vedel zanjo, da si spravljata sinova njegova prokletstvo nadse, pa jima ni zabranil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 14, 'In zato sem prisegel hiši Elijevi: Krivica hiše Elijeve se ne bo poravnala z žgalnimi in jedilnimi žrtvami na vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 15, 'In Samuel je ležal do jutra in je odprl vrata hiše Gospodove. Bal se pa je povedati prikazen Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 16, 'Tedaj pokliče Eli Samuela, rekoč: Samuel, sin moj! On reče: Glej, tu sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 17, 'In vpraša: Kaj je beseda, ki ti jo je govoril? Prosim, ne zamolči mi ničesar! Bog ti stóri to in ono, ako mi besede zamolčiš iz vsega, kar ti je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 18, 'In Samuel mu pove vse do besede, ničesar mu ne zataji. Eli pa reče: Gospod je; naj stori, kar se mu vidi prav!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 19, 'A Samuel je napredoval, in Gospod je bil ž njim in ni pustil, da pade na zemljo ne ena besed njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 20, 'In ves Izrael od Dana do Bersebe je spoznal, da je Samuel potrjen, da bodi prorok Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 3, 21, 'In Gospod se je zopet prikazoval v Silu; kajti Gospod se je razodeval Samuelu v Silu po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 1, 'In kar je rekel Samuel, je šlo po vsem Izraelu. In Izrael je šel v boj zoper Filistejce; in so se utaborili pri Eben-ezerju, Filistejci pa so se utaborili v Afeku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 2, 'In Filistejci so se bojno uvrstili zoper Izraela; in ko se je vnela bitka, je bil Izrael poražen pred Filistejci, in pobili so jih iz bojnih vrst na polju okoli štiri tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 3, 'In ko se ljudstvo zbere v taboru, reko starejšine Izraelovi: Zakaj nas je Gospod danes udaril pred Filistejci? Vzemimo k sebi iz Sila Gospodovo skrinjo zaveze, da pride med nas in nas reši roke sovražnikov naših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 4, 'In ljudstvo pošlje v Silo, in prineso odondod skrinjo zaveze Gospoda nad vojskami, ki stoluje nad kerubi; in dva sinova Elijeva, Ofni in Pinehas, sta bila tam s skrinjo zaveze Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 5, 'In ko je prišla skrinja zaveze Gospodove v tabor, je zaukal ves Izrael z močnim glasom, da je zemlja odmevala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 6, 'Ko pa Filistejci slišijo glas tega ukanja, vprašajo: Kaj pomeni glas takega močnega ukanja v taboru Hebrejcev? In zvedeli so, da je prišla skrinja Gospodova v tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 7, 'In Filistejci se zboje, kajti pravijo: Bog je prišel v tabor. In reko: Gorje nam! zakaj tega ni bilo včeraj in predvčerajšnjim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 8, 'Gorje nam! Kdo nas otme iz roke teh veličastnih bogov? To so bogovi, ki so udarili Egipt v puščavi z mnogoterimi šibami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 9, 'Trdni bodite in moški se držite, o Filistejci, da vam ne bo služiti Hebrejcem, kako so oni služili vam; moški se držite in bojujte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 10, 'In bojevali so se Filistejci in Izrael je bil premagan, in vsak je bežal v šator svoj; in poboj je bil silno velik, ker je padlo iz Izraela trideset tisoč pešcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 11, 'In skrinja Božja je bila vzeta, in dva sinova Elijeva, Ofni in Pinehas, sta poginila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 12, 'In tekel je neki Benjaminec iz bojnih vrst, in pride še ta dan v Silo. In raztrgal si je oblačilo in glavo posipal s prstjo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 13, 'In ko pride, glej, Eli sedi na stolu pri poti in pazi: kajti srce mu je bilo v strahu zavoljo skrinje Božje. In ko mož pride v mesto in oznani novico, zavpije vse mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 14, 'Ko pa Eli sliši glas vpitja, vpraša: Kakšen je to glasan šum? In mož hitro pristopi in pove Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 15, 'Eli pa je bil osemindevetdeset let star, in oči so mu bile ugasnile, da ni mogel videti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 16, 'In mož reče Eliju: Jaz sem prišel iz vojske, in sicer sem pobegnil iz bitke danes. On pa vpraša: Kako se je godilo, sin moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 17, 'In sporočnik odgovori in reče: Izrael je zbežal pred Filistejci, vrhutega je bil velik poboj med ljudstvom, tudi dva sinova tvoja, Ofni in Pinehas, sta mrtva, in skrinja Božja je vzeta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 18, 'Ko pa je oni imenoval skrinjo Božjo, pade Eli s stola znak pri vratih in si zlomi šijnjak in umre; kajti bil je star in težak mož. In on je sodil Izraela štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 19, 'Njegova snaha pa, žena Pinehasova, je bila noseča in je imela skoraj roditi. In ko zasliši vest, da je skrinja Božja vzeta in da je mrtev njen tast in njen mož, se sključi in porodi, kajti bolečine so jo prijele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 20, 'In ko se je bližala smrti, so rekle žene, ki so stale pri njej: Ne boj se, saj si rodila sina! A ona ni odgovorila ničesar in si srca ni utolažila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 21, 'in dete je imenovala Ikabod, rekoč: Slava je šla strani od Izraela – ker je bila vzeta skrinja Božja in zaradi njenega tasta in njenega moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 4, 22, 'In je dejala: Slava je šla strani od Izraela, ker je vzeta skrinja Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 1, 'Filistejci so pa vzeli skrinjo Božjo in jo donesli iz Eben-ezerja v Asdod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 2, 'In Filistejci vzemo skrinjo Božjo in jo prineso v hišo Dagonovo in jo postavijo poleg Dagona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 3, 'Ko pa Asdodci zgodaj zjutraj vstanejo, vidijo, da je Dagon padel z obrazom na tla pred skrinjo Gospodovo. In vzdignejo Dagona in ga zopet postavijo na mesto njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 4, 'Toda ko zgodaj vstanejo drugo jutro, glej, Dagon je bil spet padel z obrazom na tla pred skrinjo Gospodovo; in glava Dagonova in obe pesti rok njegovih so bile odsekane na pragu, samo ribasti trup ga je bil ostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 5, 'Zatorej ne stopajo duhovniki Dagonovi, ne drugi, kolikor jih hodi v hišo njegovo, na prag Dagonov v Asdodu do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 6, 'Roka Gospodova pa je bila težka nad Asdodci, in jih je trl ter jih udaril s tvori v Asdodu in po vsej okolici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 7, 'In ko so videli možje v Asdodu, da se jim tako godi, reko: Naj ne ostane skrinja Boga Izraelovega pri nas, kajti roka njegova je pretrda nad nami in nad našim bogom Dagonom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 8, 'In pošljejo in zbero k sebi vse kneze Filistejcev in reko: Kaj naj storimo s skrinjo Boga Izraelovega? Oni pa odgovore: Naj se prenese skrinja Boga Izraelovega v Gat! Prenesli so torej tja skrinjo Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 9, 'Zgodi se pa, potem ko so jo prenesli, da je bila roka Gospodova zoper mesto in je napravila silno veliko zmešnjavo, ker je udaril ljudi v mestu, od najmanjšega do največjega, da so se jim tvori izpustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 10, 'Pošljejo torej skrinjo Božjo v Ekron. Ali ko pride skrinja Božja v Ekron, zavpijejo Ekronci in reko: Prinesli so skrinjo Boga Izraelovega k nam, da nas pogubi in ljudstvo naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 11, 'Pošljejo torej in skličejo vse kneze Filistejcev in reko: Odpošljite skrinjo Boga Izraelovega, da se povrne na mesto svoje, da ne pogubi nas in ljudstva našega! Kajti smrtna zmešnjava je bila po vsem mestu; roka Božja je bila pretežka ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 5, 12, 'In kateri niso umrli, so bili udarjeni s tvori; in vpitje iz mesta je šlo gori proti nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 1, 'In skrinja Gospodova je bila v kraju Filistejcev sedem mesecev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 2, 'In Filistejci pokličejo svoje duhovnike in vedeže in reko: Kaj naj storimo s skrinjo Gospodovo? Poučite nas, s čim naj jo pošljemo v njen kraj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 3, 'Oni odgovore: Ako hočete vrniti skrinjo Boga Izraelovega, ne pošljite je prazne, temuč vsekakor mu dajte daritev za krivdo; tedaj ozdravite in spoznate, zakaj se roka njegova ni umeknila od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 4, 'In vprašajo: Kaj bodi za krivdo daritev, ki mu jo naj damo? Oni reko: Pet zlatih tvorov in pet zlatih miši, po številu knezov filistejskih; zakaj ista nadloga je bila nad vami vsemi in nad vašimi knezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 5, 'Naredite torej podobe tvorov svojih in podobe miši, ki so deželo vašo kazile, in dajte čast Bogu Izraelovemu; morda olajša roko svojo nad vami in nad vašim bogom in nad vašo zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 6, 'Zakaj pa zakrkujete srce svoje, kakor so si ga Egipčani in Faraon zakrknili? Ko je Bog izkazal med njimi moč svojo, niso li pustili ljudstva, da je odšlo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 7, 'Sedaj pa si pripravite nov voz in vzemite dve doječi kravi, ki še nista nosili jarma, in vprezite kravi v voz, njiju teleti pa, ko pojdeta za njima, odpeljite domov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 8, 'In vzemite skrinjo Gospodovo in jo postavite na voz, zlate dragotine pa, ki mu jih daste v daritev za krivdo, denite v skrinjico ob njeni strani, in pošljite jo tja, da odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 9, 'In glejte: če pojde po poti gori, proti svoji meji, k Betsemesu, je On nam storil vse tisto zlo veliko; ako pa ne, bomo vedeli, da nas ni njegova roka udarila, temuč po naključbi se nam je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 10, 'In možje so storili tako; in vzamejo dve doječi kravi in ju vprežejo v voz, njiju teleti pa zaklenejo doma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 11, 'In skrinjo Gospodovo nalože na voz, tudi skrinjico z zlatimi mišmi in podobami svojih tvorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 12, 'In kravi sta krenili naravnost proti Betsemesu, po cesti, in sta šli in mukali in se nista umeknili ne na desno, ne na levo. In knezi Filistejcev so šli za njimi do meje Betsemesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 13, 'Betsemeščani pa so ravno želi pšenico v dolini. In ko povzdignejo oči, ugledajo skrinjo in se razvesele, da jo vidijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 14, 'Voz pa pride na njivo Jozueta Betsemeščana in se tam ustavi. In bil je ondi velik kamen; in razsekajo les od voza in darujejo kravi v žgalno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 15, 'Leviti pa so vzdignili skrinjo Gospodovo in skrinjico, ki je bila pri njej in v kateri so bile tiste zlate dragotine, in ju postavili na tisti veliki kamen; in ljudje iz Betsemesa so ta dan darovali žgalščine in klalščine Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 16, 'In ko je to videlo petero knezov filistejskih, se vrnejo v Ekron še tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 17, 'To pa so zlati tvori, ki so jih dali Filistejci v dar za krivdo Gospodu: za Asdod eden, za Gazo eden, za Askelon eden, za Gat eden, za Ekron eden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 18, 'In zlatih miši so dali po številu vseh mest Filistejcev, podložnih peterim knezom, za ograjena mesta in za vasi po deželi. In priča je tisti veliki kamen, na katerem so postavili skrinjo Gospodovo, do današnjega dne na njivi Jozueta Betsemeščana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 19, 'Udaril pa je nekatere betsemeške može, ker so gledali v skrinjo Gospodovo; udaril je namreč izmed ljudstva sedemdeset mož iz petdesettisoč mož. In žalovalo je ljudstvo, ker je bil Gospod napravil tako velik pomor v ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 20, 'In betsemeški ljudje so dejali: Kdo more stati pred Gospodom, tem svetim Bogom? In h komu naj gre od nas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 6, 21, 'In pošljejo sle prebivalcem v Kirjat-jearimu in sporoče: Filistejci so nazaj pripeljali skrinjo Gospodovo; pridite doli, vzemite jo gori k sebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 1, 'In pridejo možje kirjat-jearimski in vzemo gori skrinjo Gospodovo in jo prineso v hišo Abinadabovo na griču, in Eleazarja, sina njegovega, posvetijo, da varuje skrinjo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 2, 'In preminilo je od dne, ko je ostala skrinja v Kirjat-jearimu, dosti časa, da je bilo dvajset let; in vsa hiša Izraelova je žalovala za Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 3, 'In Samuel ogovori vso družino Izraelovo, rekoč: Ako se hočete iz vsega srca izpreobrniti h Gospodu, odpravite izmed sebe tuje bogove in Astarte in obrnite srce svoje h Gospodu in služite njemu samemu; in otme vas iz pesti Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 4, 'Tedaj so sinovi Izraelovi odpravili izmed sebe Baale in Astarte, in so služili Gospodu samemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 5, 'In Samuel veli: Skličite vsega Izraela v Micpo, in molil bom za vas Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 6, 'In ko so se zbrali v Micpi, so zajemali vodo in jo izlivali pred Gospodom, in so se postili tisti dan in priznavali: Grešili smo zoper Gospoda. In Samuel je sodil sinove Izraelove v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 7, 'Ko pa zaslišijo Filistejci, da so se zbrali sinovi Izraelovi v Micpi, odrinejo knezi Filistejcev gori proti Izraelu. Ko to slišijo sinovi Izraelovi, se zboje Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 8, 'In reko sinovi Izraelovi Samuelu: Ne nehaj za nas vpiti h Gospodu, Bogu našemu, da nas reši roke Filistejcev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 9, 'In Samuel vzame jagnje od sesca ter celo daruje v žgalno žrtev za Izraela; in Samuel vpije h Gospodu zastran Izraela, in Gospod mu je odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 10, 'Ko je namreč Samuel daroval žgalno žrtev, se približajo Filistejci, da se vojskujejo z Izraelom, ali Gospod zagrmi tisti dan nad Filistejci z grmenjem velikim in jih zbega; in bili so poraženi pred Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 11, 'In možje Izraelovi pridejo iz Micpe ter pode Filistejce in jih pobijajo do kraja, ki je pod Betkarjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 12, 'Tedaj vzame Samuel kamen in ga postavi med Micpo in Šenom ter mu da ime Eben-ezer, rekoč: Doslej nam je pomagal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 13, 'Tako so bili Filistejci ponižani, in niso prišli več v Izraelovo pokrajino. In roka Gospodova je bila zoper Filistejce vse Samuelove dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 14, 'Tudi mesta, ki so jih bili vzeli Filistejci Izraelu, je dobil Izrael nazaj, od Ekrona do Gata; tudi njih pokrajine je otel Izrael iz roke Filistejcev. Bil pa je mir med Izraelom in Amorejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 15, 'In Samuel je sodil Izraela vse svoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 16, 'In hodeč vsako leto okrog, je postajal v Betelu, Gilgalu in Micpi, in je sodil Izraelu v vseh teh krajih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 7, 17, 'Potem se je vračal v Ramo, zakaj ondi je bila hiša njegova, in ondi je sodil Izraelu, in ondi je zgradil oltar Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 1, 'Ko pa se je postaral Samuel, je postavil svoja sinova za sodnika Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 2, 'Ime prvencu njegovemu je bilo Joel, drugemu pa Abija: ta sta bila sodnika v Bersebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 3, 'A sinova njegova nista hodila po njegovi poti, temuč sta se nagnila k lakomnosti in sta jemala darila in zavijala pravico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 4, 'Tedaj se zbero vsi starejšine Izraelovi in pridejo k Samuelu v Ramo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 5, 'in mu reko: Glej, ti si se postaral, in sinova tvoja ne hodita po tvojem potu: postavi nam torej kralja, da nas sodi, kakor imajo vsi narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 6, 'To pa se je hudo videlo Samuelu, da so rekli: Daj nam kralja, da nas sodi. In Samuel je molil h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 7, 'A Gospod reče Samuelu: Poslušaj ljudstva glas v vsem, kar so ti govorili, zakaj niso zavrgli tebe, ampak mene, da ne bi jim bil kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 8, 'Tudi tebi delajo, kakor so vselej delali od dne, ko sem jih peljal iz Egipta, do tega dne, ko so me zapuščali in služili drugim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 9, 'Zdaj torej poslušaj njih glas; toda resno jim izpričaj njih napako in jim naznani pravico kralja, ki jim bo kraljeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 10, 'In Samuel pove ljudstvu, ki je zahtevalo kralja, vse besede Gospodove');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 11, 'in reče: To bode pravica kralja, ki vam bo kraljeval: Jemal bo sinove vaše in si jih postavi, da so nad njegovimi vozovi in da so mu konjiki, in tekali bodo pred njegovimi vozovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 12, 'in si jih postavi za tisočnike in petdesetnike in nekatere, da mu orjejo njive in spravljajo njegove letine ter da mu izgotavljajo bojno orožje in naprave za vozove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 13, 'Vaše hčere pa bo jemal, da mu bodo mazilarice, kuharice in kruharice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 14, 'Tudi bo jemal vaše najboljše njive, vinograde in oljske vrtove ter jih dajal svojim hlapcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 15, 'Desetinil bo tudi vaše setve in vinograde in dajal dvornikom in hlapcem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 16, 'In bo jemal vaše hlapce in dekle in najlepše mladeniče in osle vaše ter ž njimi opravljal svoje delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 17, 'Tudi črede vaše bo desetinil, in vi mu boste morali biti hlapci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 18, 'In tisti čas boste vpili zaradi kralja svojega, ki ste si ga izvolili, a Gospod vas tisti čas ne bo uslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 19, 'Ljudstvo pa se brani poslušati glas Samuelov, in reko: Kratko ne; temuč kralja hočemo imeti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 20, 'da bodemo tudi mi kakor vsi drugi narodi ter da nas sodi naš kralj in hodi pred nami in vodi boje naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 21, 'In ko je Samuel slišal vse besede ljudstva, jih je povedal Gospodu na ušesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 8, 22, 'Gospod pa veli Samuelu: Poslušaj le njih glas in jim stóri kralja. In Samuel reče Izraelovim možem: Pojdite vsak v mesto svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 1, 'Bil pa je mož iz Benjamina, po imenu Kis, sin Abiela, sina Zerorja, sina Bekorata, sina Afija, sina enega Benjamincev, vrl junak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 2, 'In imel je sina z imenom Savla, mladega in lepega, in ni ga bilo med sinovi Izraelovimi lepšega od njega; za glavo je bil višji nego kdorkoli iz ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 3, 'Izgubile so se pa oslice Kisu, očetu Savlovemu. In Kis veli Savlu, sinu svojemu: Vzemi s sabo iz hlapcev enega ter vstani in pojdi iskat oslice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 4, 'In prehodi Efraimovo gorovje in gre dalje skozi pokrajino Saliso, a jih ne najdeta; nato prehodita pokrajino Salim, in ni jih bilo ondi, in potem prehodita deželo Benjamincev, a jih ne najdeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 5, 'Ko prideta v Zufsko pokrajino, reče Savel hlapcu svojemu, ki je bil ž njim: Pojdi, vrniva se domov, ker pusti oče moj iz misli oslice in bo skrbel za naju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 6, 'On pa mu reče: Poglej, prosim, v tem mestu je mož Božji, in njega čislajo visoko; vse, kar on pravi, se gotovo zgodi. Pojdiva torej tja; lahko nama pove pot, po kateri naj greva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 7, 'Nato reče Savel hlapcu svojemu: Ali, glej, če pojdeva, kaj prineseva tistemu možu? Kruh nama je pošel v torbah, in nimava daru, ki bi ga prinesla možu Božjemu. Kaj imava?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 8, 'Hlapec spet odgovori Savlu in reče: Glej, imam četrtino srebrnega sekla pri sebi, to hočem dati možu Božjemu, da nama pove najino pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 9, '(Nekdaj so dejali v Izraelu, ko so šli Boga vprašat: Pojdite, naj gremo k vidcu! Kdor se zdaj imenuje prorok, se je namreč nekdaj imenoval videc.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 10, 'Tedaj veli Savel hlapcu svojemu: Prav si govoril. Na noge, da greva! In šla sta v mesto, kjer je bil mož Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 11, 'Ko gresta gori po strmini proti mestu, srečata dekleta, ki so šla ven vodo zajemat, in jih vprašata: Je li videc tukaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 12, 'One jima odgovore in reko: Da, glej, pred teboj je; le híti, zakaj danes je prišel v mesto, ker ljudstvu je danes daritev opraviti na višavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 13, 'Ko prideta v mesto, ga precej najdeta, preden pojde na višavo jest; zakaj ljudstvo ne bo jedlo, dokler on ne pride, ker on blagoslovi daritev; potem jedo, kateri so povabljeni. Pojdita torej tja gori, kajti prav zdaj se bosta na njega namerila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 14, 'Šla sta torej gori v mesto. In ko stopita v sredo mesta, glej, Samuel izide, njima na proti, in hoče iti na višavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 15, 'Gospod pa je dan poprej, preden je bil prišel Savel, razodel Samuelu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 16, 'Jutri ob tem času ti pošljem moža iz Benjaminove dežele, in njega pomazili za vojvodo ljudstvu mojemu Izraelu, da reši ljudstvo moje iz roke Filistejcev; kajti pogledal sem na ljudstvo svoje, ker njegovo vpitje je prišlo do mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 17, 'In ko Samuel ugleda Savla, mu odgovori Gospod: Glej, to je mož, ki ti sem o njem povedal! Ta bo gospodoval ljudstvu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 18, 'V tem pristopi Savel k Samuelu med vrati in vpraša: Povej mi, prosim, kje je tu vidčeva hiša?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 19, 'Samuel odgovori in reče: Jaz sem videc. Pojdi pred menoj na višavo, zakaj danes bosta jedla z mano, in zjutraj te odpustim, in karkoli je v tvojem srcu, ti povem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 20, 'A za oslice, ki so se ti izgubile pred tremi dnevi, nič zdaj ne skrbi, kajti našli so jih. A na koga meri vsa želja Izraelova? Ne li nate in na tvojega očeta vso hišo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 21, 'Savel odgovori in reče: Nisem li jaz Benjaminec, iz najmanjšega rodu v Izraelu? in rodovina moja je najmanjša vseh rodovin Benjaminovega rodu. Zakaj mi takole govoriš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 22, 'Samuel pa vzame Savla in hlapca njegovega ju pelje v dvorano in ju posadi odzgoraj med povabljence, katerih je bilo okoli trideset mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 23, 'In Samuel veli kuharju: Daj sem tisti kos, ki sem ti ga dal in velel, da ga pri sebi ohraniš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 24, 'Tedaj prinese kuhar stegno in kar se ga je držalo ter položi to pred Savla. In Samuel reče: Glej, to smo prihranili, vzemi predse in jej; kajti za določeni čas se je ohranilo zate, ker sem rekel: Ljudstva sem povabil. In Savel je jedel s Samuelom tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 25, 'In ko so prišli doli z višave v mesto, je govoril s Savlom na strehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 26, 'In zjutraj zgodaj vstaneta. In ko zora vzhaja, pokliče Samuel Savla na strehi, rekoč: Vstani, da te spremim. In Savel vstane, in gresta ven obadva skupaj, on in Samuel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 9, 27, 'In ko sta prišla na konec mesta, veli Samuel Savlu: Reci hlapcu, naj pred nama gre naprej. In on gre naprej. Ti pa zdaj mirno stoj, da ti oznanim, kar je Bog govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 1, 'Tedaj vzame Samuel oljeníco in mu izlije olje na glavo ter ga poljubi in reče: Te li ni Gospod pomazilil, da bodi vojvoda dediščini njegovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 2, 'Ko pojdeš od mene danes, srečaš dva moža pri Rahelinem grobu, v Benjaminovi pokrajini, ob Zelzahu; in ona ti porečeta: Našle so se oslice, ki si jih šel iskat; in glej, oče tvoj je pustil iz misli oslice in skrbi za vaju, govoreč: Kaj naj počnem za sina svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 3, 'In ko pojdeš odondod dalje, prideš k hrastu Taboru, in ondi te srečajo trije možje, gredoči gori k Bogu v Betel: eden nese tri kozliče, drugi tri hlebe kruha, tretji meh vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 4, 'Pa te pozdravijo in ti dado dva hleba kruha, ki ju sprejmi iz njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 5, 'Potem prideš na hrib Božji, kjer stoje straže Filistejcev, in ko stopiš ondi v mesto, srečaš družbo prorokov, gredočih doli z višave, in pred njimi bodo psalmove brenklje in bobnice in piščal in harfa, in bodo prorokovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 6, 'In duh Gospodov pride z močjo nadte, in prorokoval boš ž njimi, in izpremenjen boš v drugega moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 7, 'In ko se ti dogode ta znamenja, stóri, kar ti pod roko pride, kajti Bog je s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 8, 'In pridi pred menoj doli v Gilgal, in glej, pridem tja k tebi, da darujem žgalne in mirovne daritve. Sedem dni počakaj, da pridem k tebi in ti naznanim, kar ti je storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 9, 'In bilo je, ko je obrnil hrbet in šel od Samuela, da mu je Bog izpremenil srce; in vsa tista znamenja so se dogodila ta dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 10, 'Kajti ko prideta tja k hribu, glej, družba prorokov ga sreča, in duh Božji pride z močjo nad njega, da je prorokoval med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 11, 'Ko ga pa vidijo tisti, ki so ga poprej poznali, da prorokuje s proroki, reko vsi drug drugemu: Kaj se je prigodilo sinu Kisovemu? Je li Savel tudi med proroki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 12, 'In nekdo ondotnih odgovori in reče: In kdo je njih oče? Odtod je prišlo v pregovor: Je li tudi Savel med proroki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 13, 'In neha prorokovati in pride na višavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 14, 'Savlov stric pa reče njemu in njegovemu hlapcu: Kam sta bila šla? Odgovori: Oslice iskat, in ko sva videla, da jih ni, sva šla k Samuelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 15, 'Nato de Savlov stric: Povej mi, prosim, kaj vama je povedal Samuel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 16, 'Savel odgovori stricu svojemu: Povedal je nama za gotovo, da so se oslice našle. Ali zastran kraljestva, o katerem je govoril Samuel, mu ničesar ne pove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 17, 'Samuel pa skliče ljudstvo h Gospodu v Micpo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 18, 'in ogovori sinove Izraelove: Tako pravi Gospod, Bog Izraelov: Jaz sem pripeljal Izraela iz Egipta in vas otel iz pesti Egipčanov in iz oblasti vseh kraljestev, ki so vas tlačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 19, 'A vi ste danes zavrgli svojega Boga, ki vas je sam rešil iz vseh nesreč in nadlog vaših, in ste mu rekli: Postavi nam kralja! Sedaj pa pristopite pred Gospoda po rodovih svojih in po tisočih svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 20, 'In ko je Samuel velel pristopiti vsem rodovom Izraelovim, je bil zadet rod Benjaminov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 21, 'In veli pristopiti Benjaminovemu rodu po njih rodovinah, in zadeta je bila rodovina Matri, in zadet je bil Savel, sin Kisov. In ga so iskali, pa ga niso našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 22, 'Zato vprašajo Gospoda še dalje: Pride li še ta mož semkaj? Gospod odgovori: Glej, skril se je med prtljago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 23, 'In tečejo tja ter ga pripeljejo. In ko stopi med ljudstvo, je bil za glavo višji nego kdorkoli iz ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 24, 'In Samuel reče vsemu ljudstvu: Vidite ga, ki si ga je izvolil Gospod? Saj mu ni enakega med vsem ljudstvom! Tedaj zauka vse ljudstvo in reče: Živel kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 25, 'Nato oznani Samuel ljudstvu pravice kraljestva in jih zapiše v knjigo in jo položi pred Gospoda. In odpusti Samuel vse ljudstvo, vsakega v hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 26, 'Tudi Savel je šel v hišo svojo v Gibei, in ž njim so šli vojščaki, katerih src se je Bog dotaknil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 10, 27, 'Belijalovi sinovi pa reko: Ta naj bi nam pomagal? In so ga zaničevali, in mu niso prinesli darov. Ali on se je delal, kakor da bi ne bil slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 1, 'Tedaj pride gori Nahas, Amonec, in se utabori proti Jabesu v Gileadu. In vsi prebivalci v Jabesu reko Nahasu: Skleni zavezo z nami, in hočemo ti služiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 2, 'Nahas pa, Amonec, jim reče: S tem pogojem se vam zavežem, da vam iztaknem vsem desno oko, in to sramoto spravim nad vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 3, 'In starejšine v Jabesu mu reko: Daj nam sedem dni odloga, da pošljemo sle po vseh Izraelovih krajih. Ako ne bo nikogar, da bi nas otel, pridemo k tebi ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 4, 'In pridejo sli v Gibeo Savlovo, in govore te besede vpričo ljudstva; in vse ljudstvo vzdigne glas in zaplaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 5, 'In glej, Savel pride gredoč za voli s polja in vpraša: Kaj je ljudstvu, da joče? In mu pripovedujejo besede mož v Jabesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 6, 'Ko sliši take besede, pride nadenj duh Božji z močjo, in srd njegov se silno razvname.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 7, 'In vzame par volov in ju razseka in pošlje kosce po slih v vse Izraelove kraje in sporoči: Kdorkoli ne pojde za Savlom in za Samuelom, ž njegovo govedjo naredimo enako! In prešine strah Gospodov ljudstvo, in se vzdignejo kakor en mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 8, 'In preštel jih je v Bezeku, in sinov Izraelovih je bilo tristokrat tisoč in mož Judovih trideset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 9, 'In reko slom, ki so bili prišli: Tako povejte možem v Gileadskem Jabesu: Jutri, ko bo solnce najbolj pripekalo, vam pride rešitev. Ko dospejo sli in oznanijo to možem v Jabesu, se razvesele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 10, 'Zato reko meščani v Jabesu sovražniku: Jutri pridemo k vam, in storite nam, karkoli se vam zdi prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 11, 'Drugega jutra razpostavi torej Savel ljudstvo v tri krdela, in ob jutranji straži pridero v tabor Amoncev in jih pobijajo, dokler ni dan prevroč; in kar jih je preostalo, so bili razkropljeni, da nista dva ostala vkup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 12, 'Tedaj reče ljudstvo Samuelu: Kdo je ta, ki je rekel: Ali nam bo Savel gospodoval? Dajte sem tiste može, da jih umorimo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 13, 'A Savel veli: Ta dan ne sme nihče umreti, zakaj danes je dal Gospod rešitev v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 14, 'Nato reče Samuel ljudstvu: Pojdite, naj gremo v Gilgal in ondi ponovimo kraljestvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 11, 15, 'In vse ljudstvo gre v Gilgal in ondi postavijo Savla za kralja pred Gospodom v Gilgalu, in tam so darovali žrtve, mirovne daritve pred Gospodom. In Savel in vsi Izraelovi možje so se ondi silno veselili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 1, 'Samuel pa reče vsemu ljudstvu: Glej, poslušal sem glas vaš v vsem, kar ste mi govorili, in postavil sem vam kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 2, 'Sedaj pa, glejte, kralj vaš vam hodi na čelu; a jaz sem se postaral in osivel, in glejte, sinova moja sta pri vas; in jaz sem pred vami živel od svoje mladosti do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 3, 'Glejte, tu sem! Izpričajte zoper mene pred Gospodom in pred maziljencem njegovim: komu sem vzel vola? ali komu sem vzel osla? ali sem komu krivico delal ali silo? iz čigave roke sem vzel darilo in si dal zagrniti oči zaradi njega? Vse vam hočem povrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 4, 'Odgovore: Nisi nam storil krivice, ne sile, tudi nisi iz nikogar roke kaj vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 5, 'On reče: Gospod je priča zoper vas in njegov maziljenec je priča današnji dan, da niste ničesar našli v roki moji. In reko: Priča je!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 6, 'In Samuel reče ljudstvu: Gospod je priča, ki je postavil Mojzesa in Arona in ki je peljal očete vaše iz Egiptovske dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 7, 'Sedaj pa postojte tu; da se z vami pravdam pred Gospodom za vsa pravična dela Gospodova, ki jih je storil vam in očetom vašim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 8, 'Ko je Jakob prišel v Egipt, so vaši očetje vpili h Gospodu, in Gospod je poslal Mojzesa in Arona; ta sta odvedla očete vaše iz Egipta, in dal jim je prebivališče v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 9, 'Ali ko so pozabili Gospoda, Boga svojega, jih je prodal v roko Siseru, poveljniku vojske v Hazorju, in v roko Filistejcem in v roko kralju Moabcev, in bojevali so se zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 10, 'Oni pa so vpili h Gospodu in dejali: Grešili smo, ker smo zapustili Gospoda in smo služili Baalom in Astarotam; sedaj pa nas otmi iz sovražnikov naših roke, in bomo ti služili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 11, 'In Gospod je poslal Jerub-baala in Bedana in Jefta in Samuela in vas je otel iz roke sovražnikov vaših kroginkrog, in prebivali ste brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 12, 'Ko pa ste videli, da je pridrl nad vas Nahas, kralj Amonovih sinov, ste mi rekli: Nikar, ampak kralj naj gospoduje nad nami, ko vam je vendar bil kralj Gospod, vaš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 13, 'Sedaj pa glejte kralja, ki ste si ga izvolili in si ga izprosili; kajti, glejte, Gospod je postavil kralja nad vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 14, 'Ako se boste bali Gospoda in njemu služili in glas njegov poslušali in se ne boste upirali povelju Gospodovemu, a boste hodili vi in kralj vaš za Gospodom, Bogom svojim, blagor vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 15, 'Ako pa ne boste poslušali glasu Gospodovega, temuč se boste upirali povelju Gospodovemu, bode roka Gospodova zoper vas, kakor je bila zoper očete vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 16, 'Sedaj pa postojte tu in glejte to reč veliko, ki jo stori Gospod pred vašimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 17, 'Ni li zdaj pšenična žetev? Jaz pa hočem klicati Gospoda, naj spusti grmenje in dež, da spoznate in vidite, kolikšno je zlo, ki ste ga storili pred očmi Gospodovimi, proseč si kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 18, 'Nato kliče Samuel h Gospodu, in Gospod pošlje grmenje in dež tisti dan; in vse ljudstvo se je silno balo Gospoda in Samuela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 19, 'In vse ljudstvo reče Samuelu: Prosi Gospoda, Boga svojega, za nas hlapce svoje, da ne umrjemo; zakaj vsem grehom svojim smo pridejali še to zlo, da smo si prosili kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 20, 'Samuel pa reče ljudstvu: Ne bojte se! Res ste vse to zlo storili, ali vendar ne odstopite, da ne bi šli za Gospodom, ampak služite Gospodu iz vsega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 21, 'Ne odstopite, da bi šli za ničevimi maliki, kajti ne morejo vam koristiti, ne vas rešiti, zakaj ničevosti so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 22, 'Zakaj Gospod ne zapusti ljudstva svojega zaradi velikega imena svojega, ker je blagovolil Gospod vas storiti sebi za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 23, 'Tudi jaz – Bog ne daj, da bi se tako pregrešil Gospodu, da neham moliti za vas, temuč učiti vas hočem dobro in pravo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 24, 'Bojte se le Gospoda in v resnici mu služite iz vsega srca svojega, kajti vidite, kakšne velike reči je storil za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 12, 25, 'Ako pa boste vendarle hudo delali, poginete vi in kralj vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 1, 'Savel je bil (trideset) let star, ko je zakraljeval, in ko je kraljeval dve leti Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 2, 'si je izbral tri tisoč mož iz Izraela, katerih sta bila dva tisoča s Savlom v Mikmasu in na Betelskem gorovju in en tisoč je bil z Jonatanom v Gibei Benjaminovi; drugo ljudstvo pa je razpustil, vsakega v šator njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 3, 'In Jonatan je pobil stražo Filistejcev, ki je bila v Gebi, in Filistejci so to slišali. Savel pa veli trobentati po vsej deželi, rekoč: Naj slišijo Hebrejci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 4, 'In ves Izrael je slišal praviti: Savel je pobil Filistejcev stražo, in tudi Izrael se je omrzil Filistejcem. In ljudstvo je bilo sklicano za Savlom v Gilgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 5, 'Tedaj se zbero Filistejci na boj zoper Izraela, trideset tisoč voz, šest tisoč konjikov in ljudstva množina, kolikor je peska na bregu morskem; in pridejo gori in se utabore v Mikmasu, vzhodno od Betavena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 6, 'In možje Izraelovi vidijo, da so v tesnobi, kajti ljudstvo je bilo prestrašeno. In ljudstvo se je poskrilo po votlinah in šumah in po skalnih razpoklinah in kleteh in jamah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 7, 'Nekateri Hebrejci pa so šli čez Jordan v Gadsko in Gileadsko pokrajino; a Savel je bil še v Gilgalu, in vse ljudstvo je šlo trepetajoč za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 8, 'In čakal je sedem dni, toliko, kolikor je bil določil Samuel. Samuel pa ni prišel v Gilgal, in ljudstvo se je raztekalo od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 9, 'Tedaj veli Savel: Prinesite žgalne in mirovne daritve sem k meni! In daroval je žgalščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 10, 'Komaj pa konča darovanje žgalščine, glej, pride Samuel. In Savel mu stopi naproti, da ga pozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 11, 'Samuel pa reče: Kaj si storil? Savel odgovori: Ko sem videl, da se mi ljudstvo razteka in da nisi prišel ob določenih dnevih ter da so se Filistejci zbrali v Mikmasu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 12, 'sem dejal: Zdaj pridero Filistejci doli nadme v Gilgal, in naklonjenosti Gospodove še nisem izprosil; tedaj sem se osmelil, in daroval sem žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 13, 'Samuel pa reče Savlu: Nespametno si ravnal, nisi ohranil zapovedi Gospoda, Boga svojega, ki ti jo je zapovedal; zakaj zdaj bi bil Gospod potrdil kraljestvo tvoje nad Izraelom za vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 14, 'Sedaj pa kraljestvu tvojemu ni obstanka. Poiskal si je Gospod moža po srcu svojem, in njemu je Gospod zapovedal, naj bo vojvoda ljudstvu njegovemu; ker ti nisi ohranil, kar ti je bil zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 15, 'In Samuel vstane ter odide gori iz Gilgala v Gibeo Benjaminovo. Savel pa prešteje ljudstvo, ki je bilo pri njem, okoli šeststo mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 16, 'In Savel in Jonatan, sin njegov, in ljudstvo, ki je bilo pri njiju, ostanejo v Gebi Benjaminovi; Filistejci pa so taborili v Mikmasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 17, 'In iz tabora Filistejcev pridejo tri krdela, da bi plenili deželo: prvo krdelo se obrne na pot, ki drži v Ofro, proti Sualski pokrajini;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 18, 'drugo krdelo pa krene na pot v Bet-horon, in tretje krene na pot proti meji, ki se vzdiguje nad Zeboimsko dolino proti puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 19, 'Kovača pa ni bilo dobiti po vsej Izraelovi deželi, kajti Filistejci so bili rekli: Da si ne napravijo Hebrejci mečev in sulic!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 20, 'Zato so morali vsi Izraelci hoditi doli k Filistejcem, kadar je kdo dal ostriti lemež svoj, motiko in sekiro in lopato svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 21, 'kadar se je skrhala ostrina na lopatah in motikah in vilah in sekirah; in tudi poostriti osten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 22, 'Tako je prišlo, ko je nastala vojska, da ni bilo ne meča ne sulice v roki vsega ljudstva, ki je bilo s Savlom in Jonatanom; samo Savel in Jonatan, sin njegov, sta imela nekaj orožja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 13, 23, 'In prednja straža Filistejcev se je pomeknila naprej do soteske pri Mikmasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 1, 'In zgodi se nekega dne, da veli Jonatan, sin Savlov, mladeniču, ki mu je nosil orožje: Pridi, pojdiva tja k prednji straži Filistejcev, ki je na oni strani. A očetu svojemu ni tega povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 2, 'In Savel je stanoval ob zadnjem koncu Gibee pod granatovcem, ki je v Migronu; bilo pa je pri njem ljudstva okoli šeststo mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 3, 'In Ahija, sin Ahituba, Ikabodovega brata, sina Pinehasa, sinu Elijevega, duhovnika Gospodovega v Silu, je nosil naramnik. In ljudstvo ni vedelo, da je Jonatan odšel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 4, 'Ob prelazu pa, koder je skušal Jonatan preiti k prednji straži Filistejcev, je bila rtasta skala na tej in rtasta skala na oni strani; ime prvi je bilo Bozez, drugi pa Sene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 5, 'En rt se vzpenja kakor steber na severu proti Mikmasu in drugi na jugu proti Gebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 6, 'In Jonatan reče mladeniču, oprodi svojemu: Pridi, pojdiva na ono stran k prednji straži teh neobrezancev! Morebiti da bo Gospod delal za naju; zakaj Gospodu ni težko storiti rešitve po velikem ali majhnem številu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 7, 'Nato mu odgovori oproda njegov: Stóri vse, kar ti je v srcu; kreni kamorkoli, glej, jaz sem s teboj po tvojem srcu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 8, 'Jonatan torej veli: Glej, ko prideva na on kraj k tem možem in se jim prikaževa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 9, 'ako nama poreko: Stojta, dokler ne pridemo k vama! obstaneva na svojem mestu in ne pojdeva gori k njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 10, 'Ako pa poreko: Pridita gori k nam! stopiva gori, zakaj Gospod jih je nama dal v roke. In to nama bodi znamenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 11, 'Prikažeta se torej oba straži Filistejcev; in Filistejci reko: Glej, Hebrejci lezejo iz lukenj, kamor so se bili poskrili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 12, 'In možje, ki so stali na straži, ogovore Jonatana in oprodo njegovega, rekoč: Pridita gori k nam, da vama nekaj pokažemo! In Jonatan veli oprodi svojemu: Stopaj za menoj, zakaj Gospod jih je dal v roke Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 13, 'In Jonatan leze gori po rokah in po nogah, in oproda njegov za njim. In oni padajo pred Jonatanom, in njegov oproda jih pobija za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 14, 'Tako sta jih Jonatan in oproda njegov v tej prvi bitki pobila okoli dvajset mož kakor na polovici brazde na orali njive.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 15, 'In strah je prišel v tabor na polju in med vse ljudstvo; tudi straže in plenilce je obšel strah, in zemlja se je tresla, kajti strah je bil od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 16, 'In stražarji Savlovi v Gibei Benjaminovi so gledali, in glej, množica se razpršuje in bega semtertja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 17, 'Tedaj veli Savel ljudstvu, ki je bilo pri njem: Preštejte se in oglejte, kdo je izmed naših odšel! In ko so prešteli, glej, Jonatana in oprode njegovega ni bilo tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 18, 'Nato veli Savel Ahiju: Prinesi sem skrinjo Gospodovo! Zakaj skrinja Gospodova je bila tisti čas s sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 19, 'In ko Savel še govori z duhovnikom, postane hrup v taboru Filistejcev večji in silnejši. In Savel reče duhovniku: Umakni roko svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 20, 'In Savel skliče vse ljudstvo, kar ga je bilo pri njem, in pohité tja v bitko, in glej, vsakega meč je sekal svojega bližnjega, in bila je velika zmešnjava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 21, 'Pa tudi Hebrejci, ki so bili prej pri Filistejcih in so iz okolice šli ž njimi gori v tabor, so se zdaj pridružili Izraelu, ki je bil pri Savlu in Jonatanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 22, 'Takisto se vsi Izraelovi možje, ki so se bili poskrili na Efraimskem gorovju, ko slišijo, da Filistejci beže, pridružijo svojim v boju ter jih podijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 23, 'Tako je rešil Gospod tisti dan Izraela; in bitka se je raztegnila do Betavena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 24, 'A možje Izraelovi so se preveč upehali tisti dan. Savel pa je zarotil vse ljudstvo, rekoč: Proklet bodi mož, ki bi kaj jedel do večera, da se maščujem nad sovražniki svojimi. Nihče torej iz ljudstva ni okusil kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 25, 'In vse ljudstvo je prišlo v gozd, in tam je bilo medu po tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 26, 'In ko je ljudstvo prišlo v gozd, glej, med se je cedil; ali nihče ga ni del z roko k ustom svojim, kajti ljudstvo se je balo tiste zakletve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 27, 'Jonatan pa ni bil slišal, ko je oče njegov zarotil ljudstvo; zato iztegne palico, ki jo je imel v roki, in njen konec pomoči v satovje medu in ga z roko poda k ustom svojim; in oči se mu razsvetijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 28, 'Tedaj izpregovori eden iz ljudstva in reče: Oče tvoj je z ostro prisego zavezal ljudstvo, veleč: Proklet bodi mož, ki bi danes jedel kaj; in ljudstvo je bilo že utrujeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 29, 'Nato reče Jonatan: V nesrečo je spravil oče moj deželo. Poglejte vendar, kako so se mi oči razsvetile, ker sem le malo okusil tega medu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 30, 'Koliko bolj, ako bi bilo ljudstvo svobodno jedlo od ropa svojih sovražnikov, ki ga je dobilo! Ali bi ne bil še večji poboj Filistejcev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 31, 'In pobijali so ta dan Filistejce od Mikmasa do Ajalona, dasi je bilo ljudstvo silno trudno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 32, 'Potem se ljudstvo loti ropa, in vzemo ovce in goveda in teleta in jih koljejo na tleh, in jih jedo s krvjo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 33, 'To pa oznanijo Savlu in reko: Glej, ljudstvo greši zoper Gospoda, ker jedo s krvjo vred! On veli: Spačeno ste delali! Privalite zdaj k meni velik kamen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 34, 'Še veli Savel: Razkropite se med ljudstvo in povejte jim, naj vsakdo pripelje svojega vola in ovco svojo sem k meni, in tu jih koljite in jejte, in ne grešite zoper Gospoda, jedoč s krvjo vred! Vse ljudstvo torej pripelje, vsak svoje živinče z roko svojo, po noči tja, in ondi jih koljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 35, 'In Savel zgradi oltar Gospodu; ta je bil prvi oltar, ki ga je postavil Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 36, 'In Savel reče: Spustímo se za Filistejci po noči in jih plenimo do jutranjega svita, in nihče izmed njih naj ne preostane! Odgovore: Stóri, karkoli se ti zdi prav. Ali duhovnik reče: Pristopimo sem k Bogu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 37, 'In Savel vpraša Boga: Ali naj grem doli za Filistejci? Hočeš jih li dati Izraelu v roke? A on mu ni odgovoril tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 38, 'In Savel veli: Naj pristopijo sem vsi poglavarji ljudstva, in zvedite ter poglejte, na kom je danes ta greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 39, 'Zakaj, kakor res živi Gospod, ki rešuje Izraela, ako bi tudi bilo na Jonatanu, sinu mojem, mora umreti. A ni ga bilo med vsem ljudstvom, da bi mu odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 40, 'On pa reče vsemu Izraelu: Bodite vi na oni strani, jaz pa in sin moj Jonatan bodeva na tej strani. In ljudstvo reče Savlu: Stóri, kar se ti zdi prav!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 41, 'Nato reče Savel Gospodu, Bogu Izraelovemu: Pokaži pravico! In zadeta sta bila Savel in Jonatan, ljudstvo pa je bilo prosto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 42, 'Savel reče: Vrzite kocko med menoj in Jonatanom, mojim sinom. In zadet je bil Jonatan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 43, 'In Savel reče Jonatanu: Povej mi, kaj si storil? In Jonatan mu pove in reče: Res sem okusil malo medu s koncem palice, ki sem jo imel v roki, in glej, moram umreti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 44, 'Savel pa reče: Bog mi stori to in ono, ako gotovo ne umreš, Jonatan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 45, 'Ali ljudstvo govori Savlu: Jonatan li naj umre, ki je storil to veliko rešitev v Izraelu? Nikakor ne! Kakor res Gospod živi, še las mu ne pade z glave na zemljo! zakaj z Bogom je delal danes. Tako je ljudstvo oprostilo Jonatana, da ni umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 46, 'Tedaj se je vrnil Savel in ni gonil Filistejcev, in Filistejci so odšli v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 47, 'Ko pa je bil Savel prejel kraljevanje nad Izraelom, se je bojeval zoper vse sovražnike svoje na vseh straneh, zoper Moabce, zoper sinove Amonove, zoper Edomce, zoper kralje v Zobi in zoper Filistejce; in kamorkoli se je obrnil, se je maščeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 48, 'In vedel se je hrabro in porazil Amalekovce in je otel Izraela iz roke plenilcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 49, 'Imel pa je Savel sinove: Jonatana, Išvija in Malhisuva. In dve hčeri njegovi sta se imenovali: prvenka Meraba in mlajša Mihala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 50, 'Ime Savlovi ženi pa je bilo Ahinoama, hči Ahimaazova. Poveljniku vojske njegove pa je bilo ime Abner, sin Nera, Savlovega strica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 51, 'Kis pa, oče Savlov, in Ner, oče Abnerjev, sta bila sinova Abielova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 14, 52, 'In dokler je Savel živel, je bila trda vojska zoper Filistejce. Zato kjerkoli je Savel videl kakega junaškega in hrabrega moža, ga je vzel k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 1, 'Samuel pa je govoril Savlu: Gospod me je poslal, da te pomazilim za kralja nad ljudstvom njegovim, nad Izraelom; sedaj torej poslušaj glas besed Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 2, 'Tako pravi Gospod nad vojskami: Ozrl sem se na to, kar je Amalek storil Izraelu, kako mu je založil pot, ko je šel sem iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 3, 'Pojdi torej in udari Amaleka ter s prokletjem pogubi vse, kar imajo; nič jim ne prizanašaj, temuč pomori može in žene, otroke in dojenčke, vole in ovce, velblode in osle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 4, 'Tedaj skliče Savel ljudstvo in ga prešteje v Telaimu: dvesto tisoč pešcev in deset tisoč mož iz Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 5, 'In Savel pride k mestu Amalekovcev in postavi zasedo v dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 6, 'In Savel sporoči Kenejcem: Pojdite, umaknite se, odpravite se izmed Amaleka, da vas ne potrebim ž njimi vred; kajti vi ste prijaznost storili vsem sinovom Izraelovim, ko so šli iz Egipta. Nato so se umeknili Kenejci izmed Amalekovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 7, 'In Savel udari Amalekovce od Havile tja do Sura, ki je Egiptu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 8, 'Agaga pa, kralja Amalekovcev, je ujel živega; a vse ljudstvo je kot prokleto pomoril z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 9, 'Toda Savel in ljudstvo je prizaneslo Agagu, in kar je bilo lepih ovac in goved in pitane živine in jagnjet in vsega, kar je bilo dobrega, niso hoteli kot prokleto pokončati; karkoli pa je bilo slabega in nevrednega, so pokončali kot prokleto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 10, 'Tedaj pride beseda Gospodova k Samuelu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 11, 'Žal mi je, da sem postavil Savla za kralja; zakaj odvrnil se je, da ne bi šel za menoj, in ni izpolnil besed mojih. In razsrdi se Samuel in vpije h Gospodu vso noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 12, 'In Samuel vstane zgodaj, da zjutraj sreča Savla. In sporočijo Samuelu: Savel je prišel v Karmel, in glej, postavil si je spomenik; potem je hodil okoli in šel naprej in stopil doli v Gilgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 13, 'Ko Samuel dospe k Savlu, mu reče Savel: Blagoslovljen bodi od Gospoda; izvršil sem povelje Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 14, 'Samuel odgovori: Kakovo je to torej beketanje ovac v mojih ušesih in mukanje volov, ki ga slišim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 15, 'Savel reče: Od Amalekovcev so jih pripeljali; zakaj ljudstvo je prizaneslo boljšim ovcam in volom, da naj se darujejo Gospodu, Bogu tvojemu; ostalo pa smo kot prokleto pokončali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 16, 'Tedaj reče Samuel Savlu: Postoj, da ti povem, kaj mi je govoril Gospod nocoj. On mu reče: Povej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 17, 'In Samuel pravi: Ni li tako: ko si bil majhen v svojih očeh, si bil postavljen za glavo rodovom Izraelovim? In Gospod te je pomazilil za kralja nad Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 18, 'In Gospod te je poslal na pot in rekel: Pojdi in kot proklete pogubi grešnike Amalekovce, in bojuj se ž njimi, dokler jih ne zatareš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 19, 'Zakaj nisi torej poslušal glasu Gospodovega, temuč si se lotil ropa in storil, kar je hudo v očeh Gospodovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 20, 'Savel pa reče Samuelu: Saj sem slušal glas Gospodov in sem šel po potu, ki me je nanj poslal Gospod, in sem pripeljal Agaga, kralja Amalekovcev, Amalekovce pa sem pogubil kot proklete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 21, 'Ljudstvo pa je vzelo od ropa, ovac in volov, kar je bilo najboljše med prokletim, da naj se daruje. Gospodu, Bogu tvojemu, v Gilgalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 22, 'Samuel pa reče: Ali so Gospodu toliko v veselje žgalne in klalne daritve, kakor da se posluša glas Gospodov? Glej, pokorščina je boljša, nego daritev, in poslušati je bolje nego prinašati tolstino ovnov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 23, 'Zakaj upor je kakor greh čaranja, in samovolja kakor malikovalstvo in podobočastje. Ker si pa zavrgel besedo Gospodovo, je tudi tebe Gospod zavrgel, da ne boš kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 24, 'In Savel reče Samuelu: Grešil sem, ker sem prestopil povelje Gospodovo in besede tvoje; zakaj bal sem se ljudstva in slušal njih glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 25, 'Sedaj pa, prosim, odpusti mi greh moj in vrni se z mano, da molim Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 26, 'Samuel odgovori Savlu: Ne vrnem se s teboj; zakaj ti si zavrgel besedo Gospodovo, in Gospod je tebe zavrgel, da ne boš kralj Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 27, 'In Samuel se obrne, da gre proč; on pa popade konec njegovega plašča, da se je odtrgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 28, 'Tedaj mu reče Samuel: Gospod je danes odtrgal kraljestvo Izraelovo od tebe in ga je dal bližnjiku tvojemu, ki je boljši nego ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 29, 'Pa tudi Stanovitnik Izraelov ne laže in se ne kesa; ker on ni človek, da bi se kesal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 30, 'On pa reče: Grešil sem; a sedaj me spoštuj, prosim, pred starejšinami ljudstva mojega in pred Izraelom, in vrni se z mano, da molim Gospoda, Boga tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 31, 'Vrne se torej Samuel za Savlom; in Savel je molil Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 32, 'Potem veli Samuel: Pripeljite sem k meni Agaga, kralja Amalekovcev! In Agag prikorači veselo k njemu. In Agag reče: Zares, grenkost smrti je minila!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 33, 'A Samuel reče: Kakor je meč tvoj mnogim materam vzel otroke, tako bodi mati tvoja brez otrok med ženami! In Samuel je razsekal Agaga v kose pred Gospodom v Gilgalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 34, 'Potem odide Samuel v Ramo; in Savel gre gori v hišo svojo v Gibei Savlovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 15, 35, 'In Samuel ni videl več Savla do dne smrti svoje; kajti Samuel je žaloval nad Savlom, ker je bilo Gospodu žal, da je postavil Savla za kralja Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 1, 'In Gospod reče Samuelu: Doklej boš žaloval nad Savlom, ker sem ga jaz zavrgel, da ne bo kralj Izraelu? Napolni rog svoj z oljem in pojdi, pošljem te k Jeseju Betlehemskemu; zakaj med njegovimi sinovi sem si ugledal kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 2, 'Samuel pa reče: Kako naj grem? Ako zve Savel, me umori. Gospod veli: Vzemi junico s seboj in reci: Prišel sem darovat Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 3, 'In povabi Jeseja k daritvi, in pokažem ti, kaj naj storiš; in pomazili mi njega, za katerega ti bom velel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 4, 'Samuel torej stori, kar je rekel Gospod, in pride v Betlehem. In mestni starejšine mu pridejo s trepetom naproti in reko: Je li tvoj prihod miren?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 5, 'On odgovori: Miren; prišel sem darovat Gospodu. Posvetite se in pridite z menoj k daritvi. In posvetil je Jeseja in sinove njegove ter jih povabil k daritvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 6, 'In ko pridejo noter, pogleda Eliaba in reče: Gotovo je maziljenec Gospodov pred Njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 7, 'Gospod pa veli Samuelu: Ne glej lica njegovega, ne visokosti njegove postave, ker sem ga zavrgel: zakaj ne gledam, kar gleda človek. Človek namreč gleda, kar je pred očmi, Gospod pa gleda v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 8, 'Nato pokliče Jesej Abinadaba in mu veli iti pred Samuela. In on reče: Tega tudi ni Gospod izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 9, 'In Jesej veli, naj pristopi Sama. A on reče: Tega tudi ni Gospod izbral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 10, 'Tako je velel Jesej sedmerim sinovom svojim iti pred Samuela. A Samuel reče: Gospod ni izvolil nobenega izmed teh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 11, 'Nato vpraša Samuel Jeseja: So li že dečki vsi? On odvrne: Še eden je, najmlajši, in glej, pase ovce! In Samuel veli Jeseju: Pošlji tja in ga pripelji, zakaj ne sedemo za mizo, dokler ne pride sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 12, 'Pošlje torej, in ga privede noter. In bil je rdečkast in lepega obličja in zale postave. In Gospod veli: Vstani in ga pomazili, zakaj ta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 13, 'Tedaj vzame Samuel rog z oljem in ga pomazili sredi bratov njegovih. In Duh Gospodov je prišel z močjo nad Davida od tega dne in poslej. In Samuel je vstal in šel v Ramo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 14, 'Duh Gospodov pa je šel od Savla, in hud duh od Gospoda ga je vznemirjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 15, 'In Savlovi služabniki mu reko: Glej, prosim, hud duh od Boga te vznemirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 16, 'Ukaži, gospod naš, služabnikom svojim, ki so pred teboj, naj ti poiščejo moža, ki zna dobro igrati na harfo; in kadar pride nate hudi duh od Boga, bo igral mož z roko svojo, in bolje ti bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 17, 'In Savel veli služabnikom svojim: Ozrite se mi torej po možu, ki dobro zna na strune, ter mi ga pripeljite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 18, 'Nato odgovori eden iz mladeničev in reče: Glej, videl sem sina Jeseja Betlehemskega, ta zna dobro na strune in je hraber junak in vojščak ter pameten v govoru in lepe postave mož, in Gospod je ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 19, 'Zato pošlje Savel sle k Jeseju in sporoči: Pošlji mi Davida, sina svojega, ki je pri ovcah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 20, 'Tedaj vzame Jesej osla in mu naloži kruha in meh vina in kozliča, in pošlje to Savlu po svojem sinu Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 21, 'Tako je prišel David k Savlu, in stal je v službo pred njim, in silno se mu je priljubil in je postal njegov oproda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 22, 'In Savel pošlje k Jeseju in sporoči: Prosim, naj ostane David pred mano, zakaj našel je milost v mojih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 16, 23, 'In bilo je, kadar je tisti duh od Boga prišel nad Savla, da je David vzel harfo in udarjal z roko na strune, in Savlu se je polajšalo in mu je bilo bolje, in hudi duh je šel od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 1, 'Filistejci pa zbero vojske svoje na boj in se skupijo pri Soku, ki je Judovo, in se ušatorijo med Sokom in Azeko, v Efesdamimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 2, 'Tudi Savel in možje Izraelovi se zbero in se utabore ob Hrastovi dolini, in se pripravljajo za boj zoper Filistejce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 3, 'In Filistejci so stali na gori po tej strani, Izraelci pa so stali na gori po oni strani, in dolina je bila med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 4, 'In iz tabora Filistejcev stopi dvobojnik, po imenu Goliat, iz Gata, visok šest komolcev in dlan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 5, 'In je imel bronasto čelado na glavi in luskinast oklep na sebi, in teža oklepa njegovega je bila pet tisoč seklov brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 6, 'In na nogah je imel bronaste škornje in bronast ščit na plečih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 7, 'in njegovo suličišče je bilo kakor tkalsko vratilo, in bodalo njegove sulice je imelo šeststo seklov železa; in tisti, ki mu je nosil ščit, je stopal pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 8, 'In se ustopi in kliče proti vojnim vrstam Izraelovim in jim reče: Čemu ste se šli pripravljat na boj? Nisem li jaz Filistejec in vi hlapci Savlovi? Izvolite moža za sebe, naj pride sem doli k meni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 9, 'Ako se more boriti z menoj in me ubije, bodemo vam hlapci; ako pa ga jaz premorem in ubijem, bodete nam hlapci in nam morate služiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 10, 'Še reče Filistejec: Danes sem spravil v sramoto vojne vrste Izraelove; dajte mi moža, da se skupaj bojujeva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 11, 'In ko Savel in vsi Izraelci slišijo te besede Filistejca, se prestrašijo in se silno bojé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 12, 'David pa je bil sin tistega Efratejca iz Betlehema na Judovem, ki mu je bilo ime Jesej in je imel osem sinov; in ta mož je bil že starec v Savlovih dnevih in prileten med možmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 13, 'In trije starejši sinovi Jesejevi so bili šli za Savlom na vojsko; in imena treh sinov njegovih, ki so šli na vojsko, so bila: Eliab prvenec, in po njem Abinadab, drugi, in tretji Sama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 14, 'David pa je bil najmlajši. In ko so bili šli trije starejši za Savlom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 15, 'je šel zopet David od Savla past očeta svojega ovce v Betlehemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 16, 'A Filistejec je prihajal zjutraj in na večer in se je kazal štirideset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 17, 'Tedaj veli Jesej Davidu, sinu svojemu: Vzemi za brate svoje to efo prepraženega zrnja in teh deset hlebov, in teci k bratom svojim v tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 18, 'In teh deset svežih sirov donesi poveljniku njih tisoča, in obišči svoje brate in poglej, ali se jim dobro godi, in prinesi znamenje od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 19, 'Savel pa in oni in vsi možje Izraelovi so bili v Hrastovi dolini, vojskujoč se s Filistejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 20, 'David torej vstane zgodaj zjutraj in izroči ovce varuhu in vzame darila ter odrine, kakor mu je Jesej zapovedal, in pride do vozne zagrade; vojska pa, ki je ravnokar šla ven v boj, je zagnala bojni krik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 21, 'Kajti Izraelci so se razvrstili za boj in tudi Filistejci, vojne čete proti četam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 22, 'David pa pusti svoje stvari v roki čuvaja prtljage in teče v vojne vrste ter dospe in pozdravi svoje brate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 23, 'In ko govori ž njimi, glej, dvobojnik, Filistejec iz Gata, po imenu Goliat, pride iz vrst Filistejcev in govori kakor poprej; in David je slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 24, 'Vsi možje Izraelovi pa, videč tega moža, so bežali pred njim in se silno bali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 25, 'In možje Izraelovi pravijo: Ste li videli tega moža, ki je stopal sem gori? Res, da postavi na sramoto Izraela, je stopil gori proti nam. Zatorej kdor ga ubije, njega kralj silno obogati in mu da hčer svojo in svobodno naredi njegovega očeta hišo v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 26, 'In David vpraša može, ki so stali okoli njega, rekoč: Kaj dobi mož, ki ubije tega Filistejca in sramote reši Izraela? Kdo je pač Filistejec, ta neobrezanec, da sme v sramoto spravljati živega Boga vojne vrste?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 27, 'In ljudstvo mu odgovori kakor poprej, rekoč: To dobi mož, ki ga ubije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 28, 'Ali Eliab, najstarejši brat njegov, ga je slišal govoriti z možmi; in razvname se Eliabu jeza zoper Davida, in reče: Zakaj si prišel doli? In pri kom si pustil tistih malo ovac v puščavi? Dobro poznam tvojo prevzetnost in srca tvojega hudobnost! Kajti prišel si doli, da gledaš bitko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 29, 'David pa reče: Kaj sem storil zdaj? Ni li mi razloga za to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 30, 'In obrne se od njega proti drugemu in govori kakor poprej; in ljudstvo mu zopet odgovori kakor prvikrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 31, 'In ko so slišali besede, ki jih je govoril David, jih povedo pred Savlom; in Savel pošlje ponj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 32, 'In David reče Savlu: Nikomur naj ne upade srčnost zaradi njega; hlapec tvoj pojde in se bo bojeval s tem Filistejcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 33, 'A Savel reče Davidu: Ne moreš iti proti temu Filistejcu, da se bojuješ ž njim; zakaj ti si mladenič, a on je vojščak od mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 34, 'David odgovori Savlu: Hlapec tvoj je pasel ovce očeta svojega; in kadar je prišel lev ali medved in odnesel ovčico iz črede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 35, 'sem šel za njim in ga udaril, in sem jo otel iz žrela njegovega. In ako se je postavil zoper mene, sem ga popadel za brado in ga udaril in ubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 36, 'I leva i medveda je ubil hlapec tvoj: bodi torej ta Filistejec, neobrezanec, kakor teh eden, zato ker je kidal sramoto na živega Boga vojne vrste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 37, 'Še reče David: Gospod, ki me je otel iz krempljev levu in medvedu, me otme iz tega Filistejca roke. In Savel veli Davidu: Pojdi, Gospod bodi s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 38, 'In Savel obleče Davida v svoje oblačilo ter mu posadi bronasto čelado na glavo in ga obda z oklepom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 39, 'Potem si David pripaše njegov meč čez obleko in poskusi iti; kajti ni bil vajen temu. Pa reče David Savlu: Ne morem iti v tem, zakaj nisem se privadil. Sleče torej to David.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 40, 'In vzame svojo palico v roko in si izbere pet gladkih kamenov iz potoka ter jih dene v pastirsko spravo, ki jo je imel, v torbo, in vzame pračo svojo v roko in gre proti Filistejcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 41, 'Tudi Filistejec prikoraka in se približa Davidu, in mož, ki mu je nosil ščit, gre pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 42, 'In ko se Filistejec ozre in ugleda Davida, ga zaničuje; zakaj bil je mladenček in rdečkast, pa lepega obraza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 43, 'In Filistejec reče Davidu: Sem li mar pes, da greš s palico k meni? In Filistejec preklinja Davida pri bogovih svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 44, 'in reče Davidu: Pridi k meni, in dam meso tvoje pticam pod nebom in zverem na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 45, 'Tedaj reče David Filistejcu: Ti greš k meni z mečem, s sulico in s kopjem, a jaz grem k tebi v imenu Gospoda nad vojskami, Boga vojnih vrst Izraelovih, ki si jih sramotil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 46, 'Današnji dan te Gospod izda v roko mojo, in udarim te in ti vzamem glavo, in dam danes trupla filistejske vojske pticam pod nebom in zverinam na zemlji; in vsa zemlja spozna, da je Bog v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 47, 'In ves ta zbor spozna, da Gospod rešuje, a ne z mečem, ne s sulico; zakaj Gospodov je boj, in on vas da v roko našo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 48, 'In ko se je vzdignil Filistejec in šel bliže proti Davidu, pohiti David in teče k bojnim vrstam Filistejcu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 49, 'In David seže z roko v torbo in vzame iz nje kamen in ga zaluči ter zadene Filistejca v čelo; in kamen mu predere čelo, in pade z obrazom na zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 50, 'Tako je David premogel Filistejca s pračo in s kamenom in ga je udaril in umoril; in ni bilo meča v roki Davidovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 51, 'In David priteče in stopi na Filistejca, in zgrabi meč njegov in ga potegne iz nožnice, ter ga usmrti in mu ž njim odseka glavo. In ko Filistejci vidijo, da je njih junak mrtev, zbeže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 52, 'Možje Izraelovi in Judovi pa vstanejo in zaženo bojni krik in pode Filistejce tja do doline in do vrat v Ekron. In padali so ranjeni izmed Filistejcev po poti do Saraima, do Gata in do Ekrona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 53, 'In ko so sinovi Izraelovi bili pregnali Filistejce, so se vrnili in oplenili njih taborišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 54, 'David pa je vzel glavo Filistejčevo in jo prinesel v Jeruzalem, njegovo orožje pa je zložil v šatoru svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 55, 'Ko pa je videl Savel Davida gredočega proti Filistejcu, reče Abnerju, poveljniku vojske: Abner, čigav sin je ta mladenič? Abner pa reče: Kakor res živi duša tvoja, o kralj, ne vem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 56, 'In kralj veli: Vprašaj torej, čigav sin je ta mladenič!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 57, 'Ko se vrne David po uboju Filistejca, ga vzame Abner in ga pripelje pred Savla, ko je še držal glavo Filistejčevo v roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 17, 58, 'In Savel mu reče: Čigav sin si, mladenič? David odgovori: Sin sem tvojega hlapca, Jeseja Betlehemskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 1, 'In ko konča pogovor s Savlom, se priklene duša Jonatanova duši Davidovi; in Jonatan ga je ljubil kakor svojo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 2, 'In Savel ga vzame k sebi ta dan in mu ne dovoli, da se vrne domov k očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 3, 'Tedaj skleneta Jonatan in David zavezo, ker ga je ljubil Jonatan kakor svojo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 4, 'In sleče vrhnjo suknjo, ki jo je imel na sebi, in jo da Davidu, pa tudi obleko svojo, celó meč svoj, lok in pas svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 5, 'In David je hodil, kamorkoli ga je Savel pošiljal, in v vsem je ravnal razumno; in Savel ga je postavil nad vojščaki, in vse ljudstvo si ga je priljubilo, pa tudi vsi služabniki Savlovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 6, 'Zgodi se pa, ko so šli domov, ko se je David vračal od uboja Filistejca, da pripojejo in priplešejo kralju Savlu naproti žene iz vseh Izraelovih mest z veseljem, z bobnicami in citrami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 7, 'In žene odpevajo druga drugi med godbo, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 8, 'Tedaj se Savel silno razsrdi in šteje za zlo to besedo; in reče: Davidu so dale deset tisoč, a meni le tisoč; samo še kraljestva mu je treba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 9, 'In Savel je grdo gledal Davida od tega dne in poslej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 10, 'In zgodi se drugi dan, da pride hud duh od Boga z močjo na Savla, da je razsajal sredi hiše svoje; David pa je igral na strune kakor vsak dan. In Savel je imel sulico v roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 11, 'In Savel vrže sulico, meneč: Pribodem Davida k steni. David pa se mu izogne dvakrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 12, 'In Savel se je bal Davida, zakaj Gospod je bil ž njim, Savla pa je bil zapustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 13, 'Zato ga je Savel odpravil od sebe in ga je postavil za tisočnika svojega. In David je hodil ven in noter na čelu ljudstva');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 14, 'in je ravnal razumno na vseh potih svojih, in Gospod je bil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 15, 'In ko je Savel videl, da ravna jako razumno, ga je bilo strah Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 16, 'Ali ves Izrael in Juda je ljubil Davida, kajti hodil je ven in noter njim na čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 17, 'In Savel reče Davidu: Glej, dam ti hčer svojo starejšo, Merabo, za ženo; samo mi bodi hraber mož in vojskuj se v bojih Gospodovih. Rekel si je pa Savel: Naj ne bo roka moja zoper njega, ampak roka Filistejcev bodi zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 18, 'David pa odgovori Savlu: Kdo sem jaz in kakšno je moje življenje ali očeta mojega rodovina v Izraelu, da bi bil kraljev zet?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 19, 'Toda ko pride čas, da bi se Meraba, hči Savlova, dala Davidu, je bila dana Adrielu Meholačanu za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 20, 'A Mihala, hči Savlova, je ljubila Davida. To so povedali Savlu, in videlo se mu je prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 21, 'Rekel si je namreč Savel: Dam mu jo, da mu bodi v zanko in da bodi roka Filistejcev zoper njega. Zato reče Savel Davidu: S to drugo mi danes postaneš zet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 22, 'In Savel ukaže hlapcem svojim: Govorite z Davidom na tihem in recite: Glej, kralj ti je blagovoljen in vsi služabniki njegovi te ljubijo; sedaj torej postani kraljev zet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 23, 'In hlapci Savlovi so govorili te besede Davidu pred ušesi. A David reče: Menite li, da je lahko v svaštvo stopiti s kraljem? Jaz sem vendar ubog in nizek človek!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 24, 'In hlapci Savlovi mu zopet povedo, rekoč: Take besede je govoril David.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 25, 'Savel pa reče: Tako povejte Davidu: Kralj ne želi nobene dote, ampak le sto sprednjih kožic Filistejcev, da se maščevanje izvrši nad kraljevimi sovražniki. Ali Savel je mislil, naj bi David poginil po roki Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 26, 'In ko so hlapci njegovi oznanili Davidu te besede, se mu je zdelo dobro, da postane kraljev zet. In še se niso dopolnili določeni dnevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 27, 'ko David vstane in odide, on in možje njegovi, in pobije od Filistejcev dvesto mož. In David prinese njih sprednje kožice, in jih izroče prav vse kralju, da bi bil kraljev zet. In Savel mu da Mihalo, hčer svojo, za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 28, 'In Savel je videl in spoznaval, da je Gospod z Davidom; in Mihala, hči Savlova, ga je ljubila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 29, 'In Savel se je še bolj bal Davida, in bil mu je sovražen vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 18, 30, 'In ko so knezi Filistejcev prišli se bojevat, je David ravnal, kadarkoli so prišli, bolj razumno nego vsi služabniki Savlovi; zato je močno slovelo ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 1, 'Savel pa je govoril Jonatanu, sinu svojemu, in vsem služabnikom svojim, da bi umorili Davida. Ali Jonatanu, sinu Savlovemu, je bil David zelo pogodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 2, 'In Jonatan sporoči Davidu in reče: Savel, oče moj, ti streže po življenju; sedaj torej, prosim, pazi ob jutru in ostani na skrivnem in se skrij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 3, 'Jaz pa pojdem in bom stal zraven očeta svojega na polju, kjer bodeš, in govoril bom z očetom svojim zate; in kar bom videl, ti oznanim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 4, 'In Jonatan je govoril najboljše o Davidu Savlu, očetu svojemu, in mu je rekel: Ne pregreši se, kralj, nad hlapcem svojim Davidom; zakaj on ni storil greha zoper tebe, ampak zelo koristno je zate, kar je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 5, 'Kajti izpostavil je nevarnosti življenje svoje in ubil Filistejca, in Gospod je pripravil slavno zmago vsemu Izraelu. Videl si to in se veselil. Zakaj se torej hočeš pregrešiti nad nedolžno krvjo, da ubiješ Davida brez vzroka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 6, 'In Savel je poslušal glas Jonatanov in prisegel: Kakor res Gospod živi, ne sme biti umorjen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 7, 'In Jonatan pokliče Davida in mu pove vse te besede. In Jonatan pripelje Davida k Savlu, in bival je pred njim kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 8, 'In bila je zopet vojna; in David gre in se bojuje s Filistejci in jih premaga v velikem poboju, in zbeže pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 9, 'A hud duh od Gospoda je prišel nad Savla, ko je sedel v hiši svoji in držal sulico v roki, David pa je igral na strune z roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 10, 'In Savel je mislil pribosti Davida s sulico k steni, a on se mu umakne, in sulica obtiči v steni; David pa zbeži in se reši to noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 11, 'Potem pošlje Savel sle k hiši Davidovi, da nanj pazijo in ga zjutraj umore.To oznani Davidu žena njegova Mihala, rekoč: Ako ne rešiš življenja svojega to noč, jutri boš mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 12, 'In Mihala spusti Davida skozi okno, da gre in pobegne in se reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 13, 'Mihala pa vzame domačega malika in ga položi v posteljo in mu dene ob glavo mrežasto čepico iz kozje dlake ter ga pokrije z odejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 14, 'In ko Savel pošlje sle, da pripeljejo Davida, reče ona: Bolan je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 15, 'Zopet pošlje Savel sle, da ogledajo Davida, veleč: Prinesite mi ga sem gori v postelji, da ga umorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 16, 'In ko stopijo sli noter, glej, malik je na postelji in mrežasta čepica iz kozine ob njegovi glavi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 17, 'In Savel reče Mihali: Zakaj si me tako prekanila in pustila neprijatelja mojega, da je pobegnil? Mihala pa odgovori Savlu: Dejal mi je: Pústi me, ali te umorim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 18, 'David torej pobegne in se reši; in ko pride k Samuelu v Ramo, mu pove vse, kar mu je storil Savel. In gre s Samuelom, in prebivala sta v Najotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 19, 'In povedo Savlu, rekoč: Glej, David je v Najotu v Rami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 20, 'Savel pa pošlje sle, da zgrabijo Davida. Ko so pa videli zbor prorokov, kako prorokujejo, in Samuela, stoječega njim na čelu, pride duh Božji nad sle Savlove, in prorokujejo tudi oni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 21, 'Ko to sporoče Savlu, pošlje druge sle, pa prorokujejo tudi oni. Zopet pošlje Savel sle v tretjič, a tudi oni prorokujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 22, 'Nato gre še sam v Ramo, in pride k velikemu studencu, ki je v Seku, in vpraša in reče: Kje je Samuel in David? Nekdo odgovori: Glej, v Najotu sta v Rami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 23, 'In gre tja v Najot v Rami, in duh Božji pride nad njega, in spotoma prorokuje, dokler ne pride v Najot v Rami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 19, 24, 'In tudi on sleče oblačilo svoje in tudi prorokuje pred Samuelom, in je padel in ležal slečen ves ta dan in vso noč. Odtod pravijo: Je li Savel tudi med proroki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 1, 'David pa pobegne iz Najota v Rami ter pride in govori z Jonatanom: Kaj sem storil? Kaj je krivica moja in kaj je greh moj vpričo očeta tvojega, da mi streže po življenju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 2, 'On pa mu reče: Bog ne daj! ne umrješ. Glej, oče moj ne stori ničesar, ne velikega, ne malega, da ne bi prej meni razodel. Zakaj bi mar to tajil pred mano oče moj? Tega ni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 3, 'In David še priseže in reče: Oče tvoj dobro ve, da sem našel milost v tvojih očeh, zato misli: Jonatan ne sme tega vedeti, ker bi ga bolelo! Pa zares, kakor Gospod živi in kakor živi duša tvoja, samo stopinja je med menoj in med smrtjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 4, 'Jonatan pa reče Davidu: Storiti hočem zate, karkoli želi srce tvoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 5, 'In David reče Jonatanu: Glej, jutri bo mlaj, ko bi moral sedeti pri mizi s kraljem. Toda pústi me, da se na polju skrijem do večera tretjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 6, 'Ako me oče tvoj pogreši in vpraša, reci: David me je silno prosil, da sme pohiteti v Betlehem, mesto svoje, ker ondi je letna daritev za vso rodovino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 7, 'Ako poreče: Dobro! pomeni to mir za hlapca tvojega, – ako pa se razjezi, vedi, da je hudo sklenil pri sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 8, 'Zato izkaži milost hlapcu svojemu, ker si me uvedel v zavezo Gospodovo s seboj. Ako pa je kaka krivica na meni, ubij me sam, ker zakaj bi me vodil k očetu svojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 9, 'In Jonatan reče: Nič tega se ti ne bo zgodilo! Kajti ako bi jaz res zaznal, da je sklenil oče moj hudo spraviti nadte, bi li tebi ne sporočil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 10, 'Nato reče David Jonatanu: Kdo mi pove, ako ti oče tvoj kaj trdega odgovori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 11, 'Jonatan veli Davidu: Pojdi, idiva ven na polje! In šla sta skupaj na polje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 12, 'In Jonatan reče Davidu: Gospod, Bog Izraelov, bodi priča: ko bom zvedel jutri ob tem času ali tretjega dne, da je moj oče dobre volje proti Davidu, ako ne pošljem k tebi in ti tega ne razkrijem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 13, 'Gospod stóri to ali ono Jonatanu, ako ti ne razodenem, če bi bila volja očeta mojega storiti ti hudo; in pošljem te stran, da v miru odideš, in Gospod bodi s teboj, kakor je bil z očetom mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 14, 'Ti pa boš ne samo meni, dokler živim, izkazoval milost Gospodovo, da me ne usmrtiš,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 15, 'ampak tudi hiši moji ne prikrati milosti svoje vekomaj, tudi ne, ko iztrebi Gospod sovražnike Davidove, vsakega s površja zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 16, 'Tako je Jonatan storil zavezo s hišo Davidovo, rekoč: Gospod naj kaznuje sovražnike Davidove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 17, 'In Jonatan je velel Davidu še enkrat priseči pri ljubezni, ki jo je imel do njega; zakaj ljubil ga je kakor svojo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 18, 'Nato reče Jonatan Davidu: Jutri bo mlaj, in pogrešali te bodo, ker sedež tvoj ostane prazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 19, 'In tretji dan stopi hitro sem doli in pridi na mesto, kjer si se bil skril ob onem delavniku, in sedi blizu kamena Azela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 20, 'Jaz pa izstrelim tri pšice mimo njega, kakor da bi se vadil v tarčo streljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 21, 'Pa pazi, pošljem dečka, veleč: Pojdi, išči pšice! Ako porečem dečku: Glej, pšice leže na tej strani za tabo, prinesi jih! – pridi, zakaj to pomeni mir tebi in nobene nevarnosti, kakor res Gospod živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 22, 'Ako pa porečem dečku takole: Glej, pšice so pred teboj dalje! pojdi, zakaj Gospod te pošilja proč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 23, 'Za stvar pa, ki sva o njej govorila ti in jaz, glej, Gospod je priča med teboj in med menoj vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 24, 'David se je torej skril na polju. In ko pride mlaj, sede kralj za mizo k jedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 25, 'In kralj je sedel na mestu svojem ob steni kakor navadno; in Jonatan vstane, da sede Abner zraven Savla; a Davidov sedež je bil prazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 26, 'Toda Savel ni rekel ničesar ta dan, zakaj mislil je: Njemu se je kaj primerilo, morda ni čist; gotovo ni čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 27, 'A drugi dan po mlaju, ko je bil Davidov sedež zopet prazen, reče Savel sinu svojemu Jonatanu: Zakaj ni prišel Jesejev sin k jedi, ne včeraj, ne danes?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 28, 'In Jonatan odgovori Savlu: David me je silno prosil, da bi smel iti v Betlehem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 29, 'dejal je: Dovoli mi, prosim, zakaj rodovina naša opravlja daritev v mestu, in brat moj sam me je povabil; če sem torej našel milost v tvojih očeh, naj grem, prosim, da vidim brate svoje. Zato ni prišel k mizi kraljevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 30, 'Tedaj se razvname srd Savlov zoper Jonatana in mu reče: Uporne popačenke sin! ali ne vem, da si izvolil sina Jesejevega na sramoto sebi in tudi materi svoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 31, 'Zakaj dokler bo živel sin Jesejev na zemlji, ne bodeš utrjen, tudi tvoje kraljestvo ne. Zatorej pošlji ponj in ga pripelji k meni, zakaj mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 32, 'Jonatan odgovori svojemu očetu Savlu in mu reče: Zakaj bi moral umreti? kaj je storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 33, 'A Savel mahne s sulico po njem, da bi ga prebodel. Tedaj spozna Jonatan, da je trdno sklenil oče njegov Davida umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 34, 'In vstane Jonatan izza mize v goreči jezi, in ne okusi jedi tisti drugi dan meseca, zakaj žalilo se mu je Davida, ker ga je oče njegov tako onečastil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 35, 'Zjutraj pa odide Jonatan na polje na kraj, določen Davidu, in majhen deček ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 36, 'In veli dečku: Teci in išči mi pšice, ki jih izstrelim! In ko deček teče, izstreli pšico, da je letela mimo njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 37, 'In ko dospe deček na mesto, kamor je padla pšica, kliče Jonatan za dečkom in reče: Ni li pšica dalje pred teboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 38, 'Še kliče Jonatan za dečkom: Hitro teci, ne stoj! In Jonatanov deček zbere pšice in se vrne h gospodu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 39, 'A deček ni vedel ničesar, samo Jonatan in David sta vedela, kaj to pomeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 40, 'Nato izroči Jonatan hlapcu svojemu orožje in mu veli: Pojdi, nesi je v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 41, 'Ko pa deček odide, vstane David iz svojega skrivališča ob južni strani in pade z obrazom na tla ter se trikrat pokloni; potem poljubita drug drugega in skupaj jočeta, a David najbolj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 20, 42, 'In Jonatan reče Davidu: Pojdi v miru! Kar sva obadva prisegla v imenu Gospodovem, rekoč: Gospod bodi med menoj in teboj in med semenom mojim in semenom tvojim, to veljaj vekomaj! In David vstane ter odide; Jonatan pa se vrne v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 1, 'In David dospe v Nob k Ahimeleku duhovniku. In Ahimelek pride s trepetom Davidu nasproti in mu reče: Zakaj si sam in nikogar ni s teboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 2, 'David reče duhovniku Ahimeleku: Kralj mi je nekaj ukazal in mi rekel: Naj nihče ne ve, po kaj sem te poslal in kaj sem ti ukazal. Hlapcem pa sem naročil, naj pridejo na ta in ta kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 3, 'In sedaj, kaj imaš pri roki? daj mi pet hlebov kruha v roko ali karkoli imaš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 4, 'Duhovnik pa odgovori in reče: Vsakdanjega kruha nimam pri roki, ampak le sveti kruh; če so se le mladeniči zdržali žen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 5, 'In David odgovori duhovniku in mu reče: Ni bilo žene z nami včeraj, ne predvčerajšnjim, ko sem odhajal, in posode mladeničev so svete; in tisti je že nekako vsakdanji kruh, tem bolj ker je danes novi posvečen v posodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 6, 'Tedaj mu da duhovnik svetega kruha, ker tam ni bilo drugega nego kruhi obličja, ki so jih jemali izpred Gospoda, da polože gorke kruhe v dan, ko so jih vzeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 7, 'Bil pa je ondi tisti dan mož iz služabnikov Savlovih, ki se je tam mudil pred Gospodom, in ime mu je bilo Doeg Edomec, načelnik Savlovih pastirjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 8, 'In David reče Ahimeleku: Nimaš li tu pri roki sulice ali meča? Zakaj nisem vzel s seboj ne meča, ne orožja svojega, ker je kraljeva reč zahtevala naglost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 9, 'Duhovnik odgovori: Meč Goliata Filistejca, ki si ga ubil v Hrastovi dolini, glej, je zavit v odevo za naramnikom; če hočeš tega, ga vzemi, ker tu ni drugega. In David reče: Ni mu enakega, daj mi ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 10, 'In David vstane in pobegne tisti dan iz strahu pred Savlom, in pride k Ahisu, kralju v Gatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 11, 'In služabniki Ahisovi mu reko: Ni li to David, kralj dežele? Ni li ta, ki so o njem v kolu odpevale druga drugi, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 12, 'David pa, ko je premislil te besede v srcu, se silno zboji Ahisa, kralja v Gatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 13, 'In premenil je svoje vedenje pred njimi, in je besnel v njih rokah in praskal po durih v vratih in sline cedil po bradi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 14, 'Tedaj reče Ahis služabnikom svojim: Poglejte, vidite, da je ta mož blazen! Čemu ste mi ga privedli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 21, 15, 'Imam li premalo norcev, da ste mi tegale pripeljali, da bi norel pred menoj? Ta li naj pride v hišo mojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 1, 'David torej odrine odtod in pobegne v Adulamsko votlino. Ko to slišijo bratje njegovi in vsa družina očeta njegovega, pridejo tja doli k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 2, 'In zbrali so se pri njem vsake vrste ljudje, kdorkoli je bil v stiski in kogar je pritiskal upnik in kdor je bil žalostnega srca, in on je postal njih poglavar; in bilo jih je pri njem okoli štiristo mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 3, 'In odondod odide David v Micpo na Moabskem, in reče kralju Moabcev: Prosim, naj oče moj in mati moja prideta in bivata pri vas, dokler ne zvem, kaj Bog stori z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 4, 'In pripeljal ju je pred kralja moabskega, in sta ostala pri njem vse dni, dokler je David bival na trdnjavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 5, 'A prorok Gad reče Davidu: Ne ostani na tej trdnjavi, vstani in pojdi v deželo Judovo. Tedaj odide David in pride v gozd pri Haretu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 6, 'In Savel je čul, da so zvedeli za Davida in za može, ki so bili ž njim. Savel pa je sedel v Gibei, pod tamarisko na višavi, v roki držeč sulico, in vsi hlapci njegovi so stali pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 7, 'In reče Savel vsem hlapcem svojim, pri njem stoječim: Čujte vendar, Benjaminci! Ali vam da vsakemu sin Jesejev njiv in vinogradov? Postavi li vas vse za poveljnike čez tisoč in poveljnike čez sto?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 8, 'Da ste se vsi zavezali zoper mene in ga ni, ki bi mi povedal, ko se moj sin veže s sinom Jesejevim? In ni ga med vami, ki bi mu bilo žal zaradi mene ali ki bi mi razodel, da je moj sin obudil mojega hlapca zoper mene, da preži name, kakor se danes vidi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 9, 'Nato odgovori Doeg Edomec, ki je stal poleg Savlovih hlapcev, in reče: Videl sem sina Jesejevega, da je prišel v Nob k Ahimeleku, sinu Ahitubovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 10, 'In on je zanj vprašal Gospoda in mu je dal živeža in meč Goliata Filistejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 11, 'Tedaj pošlje kralj, da pokličejo Ahimeleka duhovnika, sina Ahitubovega, in vso očeta njegovega družino, duhovnike, ki so bili v Nobu; in vsi pridejo pred kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 12, 'In Savel veli: Čuj zdaj, sin Ahitubov! On odgovori: Glej, tu sem, gospod moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 13, 'In Savel mu reče: Za kaj sta se zavezala zoper mene, ti in sin Jesejev, da si mu dal kruha in meč in si zanj vprašal Boga, da se vzdigne zoper mene, prežeč name, kakor se danes vidi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 14, 'Nato odgovori Ahimelek kralju in reče: In kdo je med vsemi služabniki tvojimi tako zvest kakor David, ki je kraljev zet in hodi v tvoje svetovalstvo in je spoštovan v hiši tvoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 15, 'Ali sem šele danes zanj začel vpraševati Boga? To ne bodi na meni! Kralj naj ne prisoja kaj takega hlapcu svojemu, ne vsej očeta mojega družini, zakaj hlapec tvoj ne ve nič tega, ne malega, ne velikega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 16, 'Toda kralj reče: Gotovo umreš, Ahimelek, ti in vsa očeta tvojega družina!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 17, 'In kralj veli stražarjem, ki so stali pri njem: Obrnite se in pobijte duhovnike Gospodove! Zakaj njih roka je tudi z Davidom, ker so vedeli, da beži, in mi niso naznanili. Ali kraljevi hlapci niso hoteli rok iztegniti na duhovnike Gospodove, da jih ubijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 18, 'In kralj veli Doegu: Obrni se ti in udari duhovnike! In Doeg Edomec se obrne in udari duhovnike, in je pobil tisti dan petinosemdeset mož, ki so nosili platneni naramnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 19, 'In Nob, mesto duhovnikov, je udaril z ostrino meča, može in žene, otroke in dojence, goved in osle in ovce z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 20, 'Le eden sinov Ahimeleka, sina Ahitubovega, po imenu Abiatar, se je rešil, bežeč za Davidom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 21, 'In Abiatar je oznanil Davidu, da je Savel pomoril duhovnike Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 22, 'David pa reče Abiatarju: Vedel sem tisti dan, ko je bil ondi Doeg Edomec, da gotovo oznani Savlu; jaz sem provzročil smrt vseh oseb iz očeta tvojega hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 22, 23, 'Ostani pri meni in se ne boj! Zakaj kdor meni streže po življenju, streže tebi po življenju, in pri meni boš dobro obvarovan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 1, 'Sporoče pa Davidu: Glej, Filistejci se vojskujejo zoper Keilo in plenijo gumna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 2, 'Tedaj vpraša David Gospoda, rekoč: Ali naj grem in udarim te Filistejce? In Gospod veli Davidu: Pojdi in udari Filistejce in reši Keilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 3, 'A možje Davidovi mu reko: Glej, strah nas je tu na Judovem; koliko bolj, ako pojdemo h Keili proti vojskam Filistejcev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 4, 'Tedaj vpraša David še enkrat Gospoda. In Gospod mu odgovori in reče: Vstani, pojdi doli v Keilo, kajti dam ti Filistejce v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 5, 'David torej gre z možmi svojimi proti Keili in se bojuje s Filistejci, in razžene njih živino ter jih porazi v velikem poboju. Tako je David rešil prebivalce v Keili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 6, 'Ko pa je bežal Abiatar, sin Ahimelekov, k Davidu proti Keili, je prišel doli z naramnikom v roki svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 7, 'Tedaj sporoče Savlu, da je David prišel v Keilo. In Savel reče: Bog ga je dal v roko mojo, kajti zaprt je, ko je prišel v mesto, ki ima vrata in zapahe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 8, 'In Savel skliče vse ljudstvo v boj, da gredo doli proti Keili oblegat Davida in može njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 9, 'Ko pa David zazna, da mu Savel snuje nesrečo, veli Abiatarju duhovniku: Prinesi sem naramnik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 10, 'In David reče: O Gospod, Bog Izraelov, hlapec tvoj je zvedel za gotovo, da namerava Savel priti v Keilo, da bi pogubil mesto zaradi mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 11, 'Me li bodo meščani v Keili izročili njemu? In pride li Savel doli, kakor je slišal hlapec tvoj? Gospod, Bog Izraelov, naznani, prosim, hlapcu svojemu! In Gospod reče: Pride doli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 12, 'Nato reče David: Izdado li meščani v Keili mene in može moje Savlu v roke? In Gospod odgovori: Izdado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 13, 'Tedaj vstane David in mož njegovih okoli šeststo, in uidejo iz Keile in gredo, kamorkoli so mogli iti. In ko sporoče Savlu, da je David pobegnil iz Keile, se neha tja pripravljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 14, 'David pa je bival v puščavi na trdnjavah in se je mudil na gorovju v Zifski puščavi. In Savel ga je iskal vse dni, a Bog mu ga ni izdal v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 15, 'Ko pa David zve, da je šel Savel streč mu po življenju, je bil David v Zifski puščavi v logu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 16, 'In Jonatan, sin Savlov, vstane in gre k Davidu v log in mu pokrepča roko v Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 17, 'In mu reče: Ne boj se, zakaj roka Savla, očeta mojega, te ne zaloti, in kraljeval boš nad Izraelom, in jaz bodem prvi pri tebi: to tudi ve Savel, oče moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 18, 'In oba sta sklenila zavezo pred Gospodom. In David je ostal v logu, a Jonatan je šel domov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 19, 'Potem pridejo Zifovci k Savlu gori v Gibeo in reko: Ne skriva li se David pri nas po trdnjavah v logu, na hribu Hahili, ki je ob južni strani puščave?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 20, 'Sedaj torej, o kralj, pridi doli po vsej želji srca svojega, in na nas je, da ga izdamo kralju v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 21, 'In Savel reče: Blagoslovljeni bodite od Gospoda, da ste se me usmilili!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 22, 'Pojdite tja, prosim, in še bolje se prepričajte, in zvedite in preglejte mesto, kjer ima brlog, in kdo ga je ondi videl; zakaj povedali so mi, da je zelo zvit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 23, 'Oglejte torej in pozvedite vsa zakotja, po katerih se skriva, in spet pridite k meni, kadar bodete gotovi, in pojdem z vami. Ako je v deželi, ga hočem iskati med vsemi tisoči Judovimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 24, 'In vstanejo in gredo v Zif pred Savlom. David pa in možje njegovi so bili v Maonski puščavi, v nižini ob južni strani puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 25, 'In Savel odrine z možmi svojimi ga iskat. A Davidu se sporoči to, in stopi po skali doli in ostane v Maonski puščavi. In ko to sliši Savel, pohiti za Davidom v Maonsko puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 26, 'In Savel je šel po tej strani gore, David in možje njegovi pa po oni strani gore. In David je hitel, da uide izpred Savla, a Savel in moštvo njegovo je obdalo Davida in može njegove, da bi jih ujeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 27, 'V tem dospe sel k Savlu in reče: Hiti in pridi, zakaj Filistejci so napadli deželo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 28, 'Savel se torej obrne, da ne bi podil Davida, in se napravi zoper Filistejce. Zato se imenuje tisto mesto Sela-hamah-lekot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 23, 29, 'David pa je šel od ondod gori in je bival v trdnjavah v Engediju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 1, 'In ko se Savel vrne od Filistejcev, mu sporoče, rekoč: Glej, David je v Engedijski puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 2, 'Tedaj vzame Savel tri tisoč izbranih mož iz vsega Izraela in odrine iskat Davida po skalah divjih koz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 3, 'In pride k ovčjim stanom pri poti, in ondi je bila votlina, in Savel stopi vanjo na potrebo. David in možje njegovi pa so sedeli zadaj v votlini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 4, 'In možje Davidovi mu reko: Glej, to je dan, o katerem ti je govoril Gospod: Glej, jaz ti dam sovražnika tvojega v roko, in storiš mu, kakor se ti bo zdelo prav. Tedaj vstane David in tiho odreže rob Savlovega plašča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 5, 'Potem pa očita Davidu srce njegovo, ker je odrezal Savlu rob plašča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 6, 'in reče možem svojim: Gospod me obvaruj, da ne storim te stvari gospodu svojemu, maziljencu Gospodovemu, da bi iztegnil roko zoper njega; kajti on je maziljenec Gospodov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 7, 'Tako je David ukrotil može svoje s temi besedami in jim ni dovolil vzdigniti se zoper Savla. In Savel vstane iz votline in gre svojim potom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 8, 'Potem vstane tudi David in stopi iz votline in kliče za Savlom, rekoč: Gospod moj, kralj! In ko se ozre Savel, se nagne David z obličjem k tlom in se prikloni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 9, 'In David reče Savlu: Zakaj poslušaš besede ljudi, ki pravijo, da išče David nesreče tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 10, 'Glej, danes so videle oči tvoje, da te je Gospod dal v votlini meni v roko, in bilo mi je rečeno, naj te umorim; ali oko moje ti je zaneslo, in dejal sem: Ne iztegnem roke zoper gospoda svojega, kajti on je maziljenec Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 11, 'Marveč glej, oče moj, glej rob plašča svojega v roki moji, da te res nisem hotel umoriti, ko sem odrezal rob plašča tvojega. Spoznaj in poglej, da nič hudega ni v roki moji, ne nobenega prestopka, in da nisem grešil zoper tebe, a ti mi strežeš po življenju, da bi mi ga vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 12, 'Gospod bo sodnik med menoj in teboj in me bo nad tabo maščeval, ali roka moja se te ne dotakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 13, 'Kakor pravi pregovor starih: Od krivičnih prihaja krivičnost; zato se te roka moja ne dotakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 14, 'Za kom se je gnal Izraelov kralj? Koga preganjaš? mrtvega psa? bolho edino?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 15, 'Gospod torej bodi sodnik in razsódi med menoj in teboj in oglej in prevzemi pravdo mojo in me oprosti roke tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 16, 'In ko David konča govor svoj Savlu, reče Savel: Ni li to tvoj glas, sin moj David? In Savel povzdigne glas svoj ter joka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 17, 'In reče Davidu: Pravičnejši si od mene: kajti ti si mi izkazal dobro, jaz pa sem ti povrnil hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 18, 'In ti si danes pokazal, da si mi dobroto storil: zakaj ko me je Gospod izdal tebi v roko, me vendar nisi umoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 19, 'Saj če kdo zaloti sovražnika svojega, ali ga pusti mirnim potom? Zato ti Gospod poplačaj z dobrim, kar si mi storil ta dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 20, 'In sedaj, glej, vem, da bodeš gotovo kralj ter da bo kraljestvo Izraelovo trdno stalo v tvoji roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 21, 'Prisezi mi torej zdaj pri Gospodu, da ne zatareš semena mojega po meni in da ne potrebiš imena mojega iz očeta mojega hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 24, 22, 'In David priseže Savlu. Tedaj odide Savel domov, David in možje njegovi pa se spravijo gori v trdnjavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 1, 'In Samuel je umrl, in ves Izrael se je zbral in žaloval po njem. In so ga pokopali v hiši njegovi v Rami. David pa vstane in gre doli v Paransko puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 2, 'Bil pa je v Maonu mož, ki je imel posestvo svoje v Karmelu, in ta mož je bil silno velik in je imel tri tisoč ovac in tisoč koz. In je strigel ovce svoje v Karmelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 3, 'Ime pa je bilo tistemu množu Nabal in ime ženi njegovi Abigaila; in žena je bila jako razumna in lepega lica, a mož neotesanec in hudoben v svojih dejanjih; bil pa je iz družine Kalebove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 4, 'Ko pa je David slišal v puščavi, da striže Nabal ovce svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 5, 'pošlje deset mladeničev in jim reče: Pojdite gori v Karmel, in ko pridete k Nabalu, ga prijazno pozdravite v mojem imenu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 6, 'in recite: Sreča! Mir bodi tebi in hiši tvoji mir in vsemu, kar imaš, mir!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 7, 'Slišal sem, da imaš strižce. Pastirji pa, kar jih imaš, so bili pri nas, in nismo jim bili nadležni, tudi niso ničesar pogrešali vse dni, dokler so bili ob Karmelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 8, 'Vprašaj mladeniče svoje, in ti bodo povedali. Zato naj najdejo moji mladeniči milost v tvojih očeh; zakaj prišli smo na dober dan. Daj, prosim, hlapcem svojim in sinu svojemu Davidu, kar ti pride v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 9, 'In ko pridejo mladeniči Davidovi, govore Nabalu po vseh teh besedah v imenu Davidovem, in umolknejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 10, 'Nabal pa odgovori hlapcem Davidovim in reče: Kdo je David? in kdo je Jesejev sin? Dandanes je čimdalje več hlapcev, ki uhajajo svojim gospodarjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 11, 'Ali naj vzamem kruh svoj in vodo svojo in meso živinčet, ki sem jih zaklal za strižce svoje, in naj to dam ljudem, za katere ne vem, od kod so?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 12, 'Tedaj se obrnejo mladeniči Davidovi na svojo pot. In pridejo nazaj k njemu in mu povedo vse te besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 13, 'In David veli možem svojim: Vsak si opaši meč! In vsi se opašejo z mečem, tudi David opaše svoj meč. In je šlo za njim gori blizu štiristo mož, dvesto jih je pa ostalo pri prtljagi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 14, 'Eden mladeničev pa oznani Abigaili, ženi Nabalovi, rekoč: Glej, David je poslal sle iz puščave, da pozdravijo našega gospodarja, a on je kriče planil nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 15, 'Toda tisti možje so nam bili dosti v prospeh, in žalega se nam ni nič zgodilo, tudi nismo ničesar pogrešali, dokler smo ž njimi občevali, ko smo bili na polju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 16, 'bili so nam kakor zidovje po noči in po dnevi, dokler smo pri njih pasli ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 17, 'Zdaj torej pazi in premisli, kaj ti je storiti; zakaj hudo je sklenjeno zoper gospodarja našega in zoper vso hišo njegovo. On pa je tak otrok Belijalov, da ne more nihče ž njim govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 18, 'Tedaj pohiti Abigaila, in vzame dvesto hlebov in dva mehova vina in pet pripravljenih ovac in pet meric opraženega zrnja in sto posušenih grozdov in dvesto kep smokev, in naloži to na osle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 19, 'In veli mladeničem svojim: Pojdite pred menoj, glejte, jaz pridem za vami! A možu svojemu Nabalu ni povedala nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 20, 'In ko sede na osla in jezdi doli po gorskem ovinku, pridejo ji nasproti David in možje njegovi, in jih sreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 21, 'David pa je rekel: Res sem zastonj varoval vse, kar je njegovega, v puščavi, da se ni ničesar pogrešilo tega, kar ima; še hudo mi je povrnil za dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 22, 'To naj stori Bog sovražnikom Davidovim in to naj doda, ako pustim od vsega, kar je njegovega, do jutranjega svita le enega moškega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 23, 'In ko vidi Abigaila Davida, spusti se hitro z osla in pade pred Davidom na obraz in se prikloni do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 24, 'In pade k nogam njegovim in reče: Na meni, gospod moj, na meni bodi ta pregreha, in dovoli, prosim, dekli svoji govoriti v ušesa tvoja, in čuj dekle svoje besede!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 25, 'Ne oziraj se, prosim, gospod moj, na tistega moža Belijalovega, na Nabala; zakaj kakršno je ime njegovo, takšen je on sam: Nabal mu je ime, in brezumnost je pri njem. Jaz pa, dekla tvoja, nisem videla mladeničev gospoda svojega, ki si jih poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 26, 'Zdaj pa, gospod moj, kakor res živi Gospod in živi duša tvoja: Gospod ti je zabranil, da nisi prišel prelivat krvi in se nisi maščeval z lastno roko. Naj torej bodo kakor Nabal sovražniki tvoji in kateri žele nesreče gospodu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 27, 'Tu je darilo, ki ga je služabnica tvoja prinesla gospodu svojemu; daj ga mladeničem, ki hodijo za gospodom mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 28, 'Odpusti, prosim, dekli svoji prestopek; zakaj Gospod bo gotovo ustanovil trdno hišo gospodu mojemu, ker gospod moj se vojskuje v bojih Gospodovih, in nič hudega se ni našlo na tebi, odkar živiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 29, 'In ako bi se vzdignil človek, da te preganja in ti streže po življenju, gospoda mojega duša bode zvezana v zvezi živečih pri Gospodu, Bogu tvojem; a dušo sovražnikov tvojih naj zaluči kakor s prače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 30, 'In kadar Gospod stori gospodu mojemu po vsem dobrem, kar ti je obljubil, in ti zapove, da bodi vojvoda Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 31, 'ti tega ne bode žal, tudi srce ti tega ne bo očitalo, da nisi prelil krvi brez razloga in da ni samega sebe maščeval gospod moj. In ko Gospod stori dobro gospodu mojemu, spomni se dekle svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 32, 'Nato reče David Abigaili: Hvaljen bodi Gospod, Bog Izraelov, ki te je poslal danes meni naproti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 33, 'In blagoslovljena bodi razumnost tvoja in ti bodi blagoslovljena, da si me danes zadržala, da nisem šel prelivat krvi in se maščevat z lastno roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 34, 'Zakaj v resnici, kakor res živi Gospod, Bog Izraelov, ki mi je ubranil, da ti nisem storil žalega, ako bi ne bila hitro prišla naproti, gotovo bi ne bil ostal Nabalu do jutranjega svita ne eden moški!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 35, 'David torej sprejme iz roke njene, kar mu je prinesla, in ji reče: Pojdi v miru gori v hišo svojo! Glej, slišal sem glas tvoj in se ozrl na tvojo osebo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 36, 'In Abigaila pride k Nabalu. In glej, pripravil je v hiši svoji gostijo, kakor kraljevo gostijo, in srce Nabalovo je bilo veselo v njem, zakaj bil je jako pijan. Zato mu ona ničesar ne pove, ne malega, ne velikega, do jutranjega svita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 37, 'Ko pa se je zdanilo in se je Nabalu izkadilo vino, mu pove žena njegova te reči. In srce mu je v životu omrtvelo, in bil je kakor kamen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 38, 'In kakih deset dni pozneje udari Gospod Nabala, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 39, 'In ko David zasliši, da je Nabal mrtev, reče: Hvaljen bodi Gospod, ki je prevzel pravdo mojo za sramotenje Nabalovo in je zadržal hlapca svojega, da ni storil hudega; in hudobnost Nabalovo mu je povrnil na glavo! In David pošlje in veli govoriti z Abigailo, da bi si jo vzel za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 40, 'In ko pridejo hlapci Davidovi k Abigaili v Karmel, jo ogovore in reko: David nas je poslal k tebi, da bi te vzel za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 41, 'Ona vstane in se prikloni z obličjem do tal in reče: Glej, tu je dekla tvoja, da bode služkinja in da umiva noge gospodarja svojega hlapcem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 42, 'In Abigaila hitro vstane in sede na osla in za njo gre pet njenih dekel, in je šla za sli Davidovimi in mu je postala žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 43, 'Tudi Ahinoamo iz Jezreela je vzel David za ženo. Tako sta bili obedve ženi Davidovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 25, 44, 'Savel pa je bil dal Mihalo, hčer svojo, ženo Davidovo, Faltimu, sinu Laisovemu, iz Galima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 1, 'Zifovci pa pridejo k Savlu v Gibeo in reko: Ali se ne skriva David na hribu Hahili, ki je pred puščavo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 2, 'Tedaj se vzdigne Savel in gre doli v Zifsko puščavo in ž njim tri tisoč izbranih mož iz Izraela, da iščejo Davida v puščavi pri Zifu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 3, 'In Savel se je ušatoril na hribu Hahili, ki je pred puščavo, ob poti. Ali David je ostal v puščavi, in ko vidi, da je Savel prišel za njim v puščavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 4, 'pošlje oglednike in zve, da je Savel že gotovo prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 5, 'In David vstane ter pride na mesto, kjer je Savel razpel šatore, in si ogleda kraj, kjer je ležal Savel in Abner, sin Nerov, poveljnik vojske njegove; in Savel je ležal sredi tabora za vozovi in moštvo je imelo šatore okrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 6, 'Tedaj izpregovori David in reče Ahimeleku Hetejcu in Abisaju, sinu Zervijinemu, bratu Joabovemu: Kdo pojde z menoj doli k Savlu v tabor? In Abisaj reče: Jaz pojdem s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 7, 'Prideta torej David in Abisaj k ljudstvu po noči. In glej, Savel je ležal speč sredi tabora za vozovi in sulica njegova je bila zabodena v zemljo pri glavi njegovi, Abner in ljudstvo pa je ležalo kroginkrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 8, 'Tedaj reče Abisaj Davidu: Bog ti je danes izdal sovražnika tvojega v roko. Sedaj pa naj ga, prosim, zabodem s sulico v zemljo z enim mahljajem, da v drugič ne bo treba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 9, 'A David reče Abisaju: Ne umori ga! Kajti kdo bi smel iztegniti roko zoper maziljenca Gospodovega, pa ostati brez kazni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 10, 'Še reče David: Kakor res Gospod živi, ako se ne zgodi, da ga Gospod udari ali pride dan njegov, da umrje, ali da pojde v boj in pogine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 11, 'mene Gospod obvaruj, da ne iztegnem roke na maziljenca Gospodovega! Sedaj pa vzemi, prosim, sulico, ki je pri glavi njegovi, in vrč vode, pa pojdiva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 12, 'Tako vzame David sulico in vrč vode od glave Savlove, in odideta; in nihče ju ne vidi, niti opazi, tudi se nihče ne prebudi, temuč so vsi spali, zakaj prišlo je nanje trdno spanje od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 13, 'Ko pa preide David na nasprotno stran, stopi na vrh hriba oddaleč, da je bila precejšnja razdalja med njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 14, 'in David zavpije proti ljudstvu in proti Abnerju, sinu Nerovemu, rekoč: Ne odgovoriš li, Abner? Tedaj odgovori Abner in reče: Kdo si ti, ki vpiješ proti kralju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 15, 'In David reče Abnerju: Ali nisi mož? in kdo je tebi enak v Izraelu? Zakaj torej nisi stražil gospoda svojega, kralja? Prišel je namreč nekdo iz ljudstva noter, da umori kralja, gospoda tvojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 16, 'To pa ni lepo, kar si storil. Kakor res Gospod živi, smrt ste zaslužili, ker niste stražili gospoda svojega, maziljenca Gospodovega. Sedaj pa, poglej, kje je kraljeva sulica in vrč vode, ki ju je imel pri glavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 17, 'V tem spozna Savel glas Davidov in reče: Ni li tvoj glas, sin moj David? In David odvrne: Moj glas, o gospod moj, kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 18, 'Dalje reče: Zakaj tako preganja gospod moj hlapca svojega? Ker kaj sem storil? in kaj je hudega v roki moji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 19, 'Sedaj pa poslušaj, prosim, gospod moj, kralj, besede hlapca svojega. Ako te Gospod draži zoper mene, naj se pomiri z daritvijo; ako pa to provzročajo otroci človeški, naj bodo prokleti pred Gospodom, ker so me spodili ta čas, da ne bi imel deleštva v dediščini Gospodovi, rekoč: Pojdi, služi drugim bogovom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 20, 'Sedaj torej, naj se ne prelije moja kri na zemljo, daleč od obličja Gospodovega; zakaj kralj Izraelov je šel iskat bolho edino, kakor če kdo lovi jerebico po planinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 21, 'Tedaj reče Savel: Grešil sem. Vrni se, sin moj David, zakaj ne storim ti več nobene žali, ker je drago bilo danes življenje moje v tvojih očeh; glej, nespametno sem ravnal in prehudo se motil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 22, 'David odgovori in reče: Glej, tu je sulica kraljeva, naj pride eden mladeničev sem ter jo odnese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 23, 'Gospod pa povrne vsakemu po pravičnosti in zvestobi njegovi; zakaj Gospod te je danes dal meni v roko, toda nisem hotel iztegniti roke zoper maziljenca Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 24, 'In glej, kakor je bilo danes dragoceno življenje tvoje v mojih očeh, tako bo življenje moje dragoceno v očeh Gospodovih, in on me otme iz vsake stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 26, 25, 'Nato reče Savel Davidu: Blagoslovljen bodi, sin moj David! Ti izvršiš veliko in gotovo zmagaš. In David je šel svojim potom, Savel pa se je vrnil v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 1, 'David pa reče v srcu svojem: Nekega dne pa vendar poginem pod roko Savlovo. Najbolje zame, da naglo zbežim v deželo Filistejcev, in Savel me neha iskati po vseh pokrajinah Izraelovih, in tako se rešim roke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 2, 'David torej vstane in gre na ono stran, on in šeststo mož, ki so bili ž njim, k Ahisu, sinu Maokovemu, kralju v Gatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 3, 'In David je prebival z Ahisom v Gatu, on in možje njegovi, vsak z družino svojo, tudi David z dvema ženama svojima, z Ahinoamo Jezreelsko in Abigailo Karmelsko, bivšo Nabalovo ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 4, 'In ko so povedali Savlu, da je David pobegnil v Gat, ga ni več iskal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 5, 'In David reče Ahisu: Ako sem, prosim, našel milost v očeh tvojih, naj mi dado prostora v kakem mestu na deželi, da bi v njem prebival; kajti čemu naj prebiva hlapec tvoj pri tebi v kraljevem mestu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 6, 'Tedaj mu da Ahis Ziklag tisti dan. Odtod je Ziklag last kraljev Judovih do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 7, 'In število dni, kar jih je David prebil v deželi Filistejcev, je bilo leto in štiri mesece.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 8, 'David pa in možje njegovi so hodili gori in so naskakovali Gesurske in Girzejce in Amalekovce, zakaj ti so bili prebivalci te dežele od starodavna, do tja, koder se gre v Sur in do Egiptovske dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 9, 'In David je pustošil deželo ter ni dal živeti ne možu, ne ženi, in ko je bil pobral ovce, goveda, osle, velblode in oblačila, se je vrnil in prišel k Ahisu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 10, 'In ko je Ahis vprašal: Kam ste vdrli danes? je rekel David: V južno stran Judovo, in v južno stran Jerahmelijcev, in v južno stran Kenejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 11, 'David pa ni ohranil živega ne moža, ne žene, da bi ju pripeljal v Gat, rekoč: Da bi nas ne ovadili in ne rekli: Tako je storil David! Tako je navadno delal, dokler je prebival v deželi Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 27, 12, 'Zato je Ahis veroval Davidu in menil: Omrzil se je pri ljudstvu svojem Izraelu, zato bode hlapec moj vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 1, 'Zgodi se pa v tem času, da skličejo Filistejci bojne trume svoje na vojsko, da se bojujejo z Izraelom. In Ahis veli Davidu: Vedi za gotovo, da pojdeš z mano na vojsko, ti in moštvo tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 2, 'In David reče Ahisu: Potem tudi zveš, kaj stori hlapec tvoj. Ahis pa reče Davidu: Zato te postavim za varuha glave svoje vse svoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 3, 'Samuel pa je bil umrl, in ves Iz rael je žaloval po njem. In pokopali so ga v Rami, v mestu njegovem. Savel pa je bil odpravil iz dežele rotilce mrtvih in vražarje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 4, 'Ko se torej zbero Filistejci ter pridejo in se utabore v Sunemu, zbere tudi Savel vse Izraelce, in utabore se na Gilboi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 5, 'In ko vidi Savel tabor Filistejcev, se zboji in srce mu obupa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 6, 'In Savel je vprašal za svet Gospoda, a Gospod mu ni odgovoril ne po sanjah, ne po Urimu, ne po prorokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 7, 'Tedaj veli Savel hlapcem svojim: Poiščite mi ženo, ki se peča z rotenjem mrtvih, da bi šel k njej in jo vprašal. In hlapci njegovi mu reko: Glej, v Endoru je žena, ki je rotilka mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 8, 'In Savel se preobleče za drugo osebo in gre tja, in dva moža ž njim; in pridejo po noči k ženi. In on reče: Vedežuj mi, prosim, po duhu mrtvega in pripelji mi gori, kogar ti bom imenoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 9, 'In žena mu reče: Glej, ti veš, kar je storil Savel, kako je potrebil iz dežele rotilce duhov in vražarje; zakal pa nastavljaš zanko duši moji, da me spraviš v smrt?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 10, 'In Savel ji priseže pri Gospodu, rekoč: Kakor res Gospod živi, za to te ne zadene nobena kazen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 11, 'Nato vpraša žena: Koga naj ti pripeljem gori? On reče: Pripelji mi Samuela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 12, 'In ko žena zagleda Samuela, zavpije z močnim glasom, in reče Savlu: Zakaj si me prekanil? ker ti si Savel!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 13, 'In kralj ji reče: Ne boj se! Kaj vidiš? Žena odgovori Savlu: Vidim boga stopati gori iz zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 14, 'On jo vpraša: Kakšna je njegova podoba? Ona reče: Star mož prihaja gori, ogrnjen s plaščem. In Savel zazna, da je Samuel, in se skloni z obličjem k tlom in stori poklon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 15, 'In Samuel reče Savlu: Zakaj me vznemirjaš s tem, da me kličeš gori? In Savel odgovori: V stiski sem veliki, kajti Filistejci se vojskujejo z menoj, in Bog me je zapustil in mi ne odgovarja več, ne po prorokih, ne po sanjah; zato sem dal poklicati tebe, da mi oznaniš, kaj naj storim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 16, 'Samuel reče: Čemu pa vprašuješ mene, ker te je Gospod zapustil in je postal tvoj nasprotnik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 17, 'In Gospod je storil zase, kakor je po meni govoril, in Gospod je odtrgal kraljestvo iz roke tvoje in ga je dal bližnjiku tvojemu, Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 18, 'Ker nisi poslušal glasu Gospodovega in nisi izvršil silne jeze njegove nad Amalekom, zato ti je takole storil Gospod sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 19, 'Vrhutega bo dal Gospod Izraela s teboj vred v roko Filistejcem, in jutri bodeš ti in sinovi tvoji pri meni; tudi vojsko Izraelovo da Gospod Filistejcem v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 20, 'Tedaj pade Savel naglo na tla, kakor je bil dolg, kajti silno se je prestrašil zaradi Samuelovih besed, in ni bilo nič moči več v njem, zakaj zaužil ni kruha cel dan in celo noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 21, 'In tista žena pristopi k Savlu in, videč, da je zelo preplašen, mu reče: Glej, dekla tvoja je poslušala glas tvoj, in izpostavila sem nevarnosti življenje svoje, poslušajoč besede tvoje, ki si mi jih govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 22, 'Sedaj pa poslušaj tudi ti, prosim, dekle svoje glas: predložim ti grižljaj kruha, in jej, da si opomoreš, ko pojdeš svojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 23, 'On pa se brani in reče: Nočem jesti. Ali hlapca njegova s tisto ženo vred ga silita, in poslušal je njih glas. In vstane s tal in sede na posteljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 24, 'Žena pa je imela v hiši pitano tele, in hitro ga zakolje, in vzame moke in jo zamesi in speče opresnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 28, 25, 'Potem prinese pred Savla in njegova hlapca, in jedli so. Nato vstanejo in odidejo še tisto noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 1, 'Filistejci pa so zbrali vse vojne trume svoje v Afeku; in Izrael se je utaboril ob studencu, ki je v Jezreelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 2, 'In knezi Filistejcev so šli pri sto in tisočih svojih, a David in možje njegovi so šli v zadnjem voju z Ahisom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 3, 'Tedaj reko knezi Filistejcev: Kaj hočejo tu ti Hebrejci? In Ahis reče knezom Filistejcev: Ali ta ni David, hlapec Savla, izraelskega kralja, ki je bil pri meni že mnogo dni ali let, in nisem ničesar našel na njem, odkar je uskočil k meni do tega dne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 4, 'Ali knezi Filistejcev se razsrde nanj in mu reko: Véli, da se vrne ta mož, da gre nazaj v mesto svoje, kamor si ga postavil, nikar naj ne hodi z nami doli v boj, da nam ne postane v bitki nasprotnik; kajti s čim bi si pridobil blagovoljnost gospoda svojega kakor z glavami teh mož?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 5, 'Ali ta ni David, o katerem so plešoč pele druga drugi, govoreč: Savel je pobil svoj tisoč, a David svojih deset tisoč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 6, 'Tedaj pokliče Ahis Davida in mu reče: Kakor res Gospod živi, pošten si, in všeč bi mi bilo, da hodiš z menoj ven in noter v vojski, zakaj nisem nič hudega našel na tebi, odkar si prišel k meni do tega dne; ali knezom nisi po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 7, 'Zato se zdaj vrni in pojdi v miru, da ne storiš, kar bi se videlo hudo filistejskim knezom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 8, 'David pa reče Ahisu: Kaj pa sem storil, ali kaj si našel na hlapcu svojem, dokler sem bil pred obličjem tvojim do tega dne, da ne smem iti in se bojevati zoper sovražnike gospoda svojega, kralja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 9, 'Ahis odgovori in reče Davidu: Vem, da si dober v mojih očeh kakor angel Božji; ali Filistejcev knezi so dejali: Naj ne gre ta z nami v boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 10, 'Zatorej vstani zgodaj zjutraj s hlapci gospoda svojega, ki so prišli s teboj. In ko zjutraj, kakor hitro se zdani, vstanete, kar odrinite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 29, 11, 'Tedaj vstane zgodaj David in možje njegovi, da odidejo zarana in se vrnejo v deželo Filistejcev. Filistejci pa so šli gori v Jezreel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 1, 'Ko pa pride David z možmi svojimi tretji dan proti Ziklagu, so bili Amalekovci naskočili južno stran in Ziklag, in so udarili v Ziklag in ga požgali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 2, 'in so ujeli žene in vse, kar jih je bilo v njem, male in velike: niso sicer nikogar ubili, a odgnali so jih in šli svojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 3, 'Ko torej pridejo David in možje njegovi k mestu, vidijo, da je požgano z ognjem, in njih žene in njih sinovi in hčere so odpeljani v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 4, 'Tedaj David in ljudstvo, ki je bilo ž njim, povzdigne glas svoj, in jočejo toliko, da niso mogli več jokati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 5, 'Tudi obe ženi Davidovi sta bili ujeti, Ahinoama Jezreelska in Abigaila, bivša žena Nabala Karmelskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 6, 'In David je bil v veliki stiski, zakaj ljudstvo se je dogovarjalo, da ga posujejo s kamenjem, ker je bilo vse ljudstvo v srcu užaljeno, vsak nad sinovi in hčerami svojimi. Ali David se ohrabri v Gospodu, Bogu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 7, 'In David veli Abiatarju duhovniku, sinu Ahimelekovemu: Prosim, prinesi mi sem naramnik! In Abiatar prinese tja naramnik k Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 8, 'In David vpraša Gospoda, rekoč: Ali naj udarim za tisto roparsko druhaljo? Jih li dohitim? On mu odgovori: Spusti se za njimi, zakaj gotovo jih dohitiš in izvršiš popolno rešitev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 9, 'David torej odrine, on in šeststo mož, ki so bili pri njem. In ko pridejo k potoku Besorju, jih nekaj obstane ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 10, 'Ali David in štiristo mož se žene dalje; kajti dvesto jih je zaostalo, ker so bili tako upehani, da niso mogli iti čez potok Besor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 11, 'In najdejo Egipčana na polju ter ga pripeljejo k Davidu, in mu dado kruha, in je jedel, in ga napojé z vodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 12, 'in mu dado kepo smokev in dve gruči posušenega grozdja: in ko se naje, se poživi, kajti ni jedel kruha, ne pil vode tri dni in tri noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 13, 'In David mu reče: Čigav si in odkod si? Odgovori: Mladenič iz Egipta sem, nekega Amalekovca hlapec, in gospodar moj me je zapustil, ker sem bil bolan pred tremi dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 14, 'Naskočili smo južno stran Keretejcev in Judovo in južno stran Kalebovo, in Ziklag smo požgali z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 15, 'In David mu reče: Me li hočeš doli peljati k tej druhali? On reče: Prisezi mi pri Bogu, da me ne umoriš in tudi ne izročiš gospodarja mojega rokam, in popeljem te doli k tej druhali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 16, 'Peljal ga je torej doli; in glej, bili so razkropljeni po vsem tistem kraju in so jedli in pili in praznovali zaradi vsega velikega ropa, ki so ga bili vzeli iz Filistejcev dežele in iz dežele Judove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 17, 'In David jih je pobijal od somraka do večera drugega dne, in nihče se ni rešil, samo štiristo mladeničev, ki so na velblodih pobegnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 18, 'In David je otel vse, kar so bili vzeli Amalekovci; tudi dve ženi svoji je osvobodil David.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 19, 'Nič se ni pogrešalo, ne malo, ne veliko, ne sinovi, ne hčere, prav nič, kar so jim bili poplenili: vse je David zopet dobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 20, 'In David je vzel vso drobnico in goved, in gnali so jo pred drugo živino in pravili: To je plen Davidov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 21, 'In David dospe k tistim dvesto možem, ki so bili tako upehani, da niso mogli iti za Davidom, zato so jim veleli ostati pri potoku Besorju; ti pridejo Davidu naproti in ljudstvu, ki je bilo ž njim. In ko pristopi David k ljudstvu, jih pozdravi prijazno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 22, 'Tedaj izpregovore vsi hudobni in Belijalovi možje med temi, ki so bili šli z Davidom, in reko: Ker niso šli z nami, ne dajmo jim nič plena, ki smo ga oteli; samo naj vzame sleherni svojo ženo in otroke svoje, pa naj odidejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 23, 'Nato veli David: Ne ravnajte tako, bratje moji, s tem, kar nam je dal Gospod, ki nas je obvaroval in nam dal v roke roparsko druhal, ki je bila prišla zoper nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 24, 'In kdo bi vas v tem poslušal? Marveč kakršen je del tistega, ki je šel v boj, takšen bodi del tega, ki je ostal pri prtljagi: po enako naj si razdelijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 25, 'In tako je bilo od tega časa in poslej, da je to ustanovil kot postavo in pravilo v Izraelu, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 26, 'In ko je David prišel v Ziklag, pošlje od plena starejšinam Judovim, prijateljem svojim, rekoč: Glejte, to vam je blagodar od plena sovražnikov Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 27, 'Namreč tem v Betelu in tem, ki so bili v Ramotu na jugu, in tem v Jatirju');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 28, 'in tem v Aroerju in tem v Sifmotu in tem v Estemoi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 29, 'in tem v Rahalu in tem, ki so bili v mestih Jerahmelijcev in v mestih Kenejcev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 30, 'in tem v Hormi in tem v Korašanu in v Atahu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 30, 31, 'in tem v Hebronu in v vseh mestih, v katera je kdaj zahajal David in možje njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 1, 'Filistejci pa so se bojevali z Izraelom, in Izrael je zbežal pred Filistejci, in so padali pobiti na gorovju Gilboi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 2, 'In Filistejci so bili trdo za petami Savlu in sinovom njegovim, in pobili so Jonatana in Abinadaba in Malhisua, sinove Savlove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 3, 'In bitka je hudo pritiskala na Savla, in lokostrelci so ga dohiteli, in v strahu je trepetal pred strelci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 4, 'Tedaj reče Savel svojemu oprodi: Izderi meč svoj in me prebodi, da ne pridejo ti neobrezanci in me ne prebodejo ter si smeh napravijo z menoj. Ali njegov oproda ni hotel, ker se je silno bal. Zato vzame Savel meč svoj in se nasadi nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 5, 'Ko pa vidi njegov oproda, da je Savel mrtev, nasadi se tudi on na svoj meč in umre ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 6, 'Tako je umrl Savel in trije sinovi njegovi in oproda njegov in možje njegovi, vsi skupaj tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 7, 'Ko pa vidijo možje Izraelovi, ki so bili onostran doline in ki so bili za Jordanom, da bežé možje Izraelovi ter da so Savel in sinovi njegovi mrtvi, zapuste mesta svoja, pa pobegnejo. In Filistejci pridejo in se nastanijo po njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 8, 'In drugi dan pridejo Filistejci, da slečejo pobite, in najdejo Savla in tri sinove njegove, ležeče na gorovju Gilboi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 9, 'In mu odsekajo glavo in snamejo z njega orožje njegovo, in pošljejo po deželi Filistejcev naokrog, da se ta vesela vest oznani v hiši njih malikov in med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 10, 'In orožje njegovo razpolože v hiši Astartini, truplo njegovo pa obesijo na zid v Betsanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 11, 'Ko pa slišijo prebivalci v Jabesu v Gileadu, kaj so storili Filistejci Savlu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 12, 'se vzdignejo, kar jih je bilo vojščakov, in gredo vso noč in snamejo truplo Savlovo in trupla sinov njegovih z zida v Betsanu, ter jih prineso v Jabes in jih ondi sežgo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (9, 31, 13, 'In vzamejo njih kosti in jih pokopljejo pod tamarisko v Jabesu in se postijo sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 1, 'Zgodi se pa po smrti Savlovi, ko se je bil David vrnil od poboja Amalekovcev in je bival dva dni v Ziklagu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 2, 'glej, tretjega dne pride mož iz tabora Savlove vojske z raztrganimi oblačili in s prstjo na glavi. In ko dospe k Davidu, pade na tla in se pokloni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 3, 'In David mu reče: Odkod prihajaš? On mu reče: Iz tabora Izraelovega sem ubežal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 4, 'David ga vpraša: Kako se je godilo? Povej mi, prosim. On odgovori: Ljudstvo je bežalo iz boja in je tudi dosti ljudstva padlo in poginilo, tudi Savel in njegov sin Jonatan sta mrtva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 5, 'In David reče mladeniču, ki mu je to pravil: Kako veš, da sta mrtva Savel in njegov sin Jonatan?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 6, 'Mladenič, ki mu je to pravil, reče: Po naključbi sem prišel na goro Gilboo, in glej, Savel se je bil naslonil na sulico svojo, in glej, vozovi in jezdeci so hiteli za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 7, 'In ko se ozre, me ugleda in me pokliče. In jaz odvrnem: Tu sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 8, 'On pa mi reče: Kdo si ti? Rečem mu: Amalekovec sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 9, 'Nato mi veli: Stopi k meni in me usmrti, kajti groza se me je lotila, ker še je duša docela v meni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 10, 'In stopil sem k njemu in ga usmrtil, ker sem vedel, da ne more živeti po svojem padcu. In vzel sem venec, ki ga je imel na glavi, in zapestnico z roke njegove, in sem ju zdaj prinesel tebi, gospodu svojemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 11, 'Tedaj prime David za oblačila svoja in jih raztrga, enako tudi vsi možje, ki so bili pri njem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 12, 'in so žalovali in jokali in se postili do večera po Savlu in po Jonatanu, sinu njegovem, in zavoljo ljudstva Gospodovega in hiše Izraelove, ker so bili padli po meču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 13, 'In David reče mladeniču, ki mu je to naznanil: Odkod si? Odgovori: Sin sem tujca, Amalekovca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 14, 'In David mu reče: Kako, da se nisi bal položiti roke svoje na maziljenca Gospodovega, da ga pogubiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 15, 'In pokliče David enega mladeničev svojih in veli: Stopi sem in ga umori! In ga je udaril, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 16, 'In David mu reče: Kri tvoja bodi na glavi tvoji! Zakaj tvoja usta so zoper tebe pričala, rekoč: Jaz sem usmrtil maziljenca Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 17, 'In David je pel to žalostinko nad Savlom in Jonatanom, sinom njegovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 18, 'in je velel, da se nauče sinovi Judovi pesem „o loku“; glej, zapisana je v knjigi Jašarjevi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 19, 'Slava tvoja, o Izrael, je bila ubita na višinah tvojih! Kako so padli junaki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 20, 'Ne pravite tega v Gatu, ne oznanjujte po ulicah v Askelonu, da se ne vesele hčere Filistejcev, da ne vriskajo radostno neobrezancev hčere!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 21, 'O gore Gilboe, da ne bi bilo rose ali dežja na vas, ne njiv, s katerih bi se prinašale daritve! Ker ondi je bil junakom ščit s sramoto odvržen, ščit Savlov, kakor bi ne bil z oljem maziljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 22, 'Brez krvi pobitih, brez tolstine junakov se ni vračal lok Jonatanov, in meč Savlov ni prišel nikoli prazen nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 23, 'Savel in Jonatan, ljubezniva in draga sta bila v življenju, tudi v smrti nista ločena; bila sta hitrejša nego orli, močnejša nego levi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 24, 'Hčere Izraelove, plakajte po Savlu, ki vas je mično oblačil v škrlat in je deval dragotine zlate na obleke vaše!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 25, 'Kako so padli junaki sredi boja! Jonatan je bil ubit na višinah tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 26, 'Žal mi je tebe, brat moj Jonatan; drag si mi bil jako! Divna mi je bila ljubezen tvoja, bolj nego žená ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 1, 27, 'Kako so padli junaki in je poginilo vojno orožje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 1, 'In zgodi se potem, da je David vprašal Gospoda, rekoč: Naj li grem gori v katero mest Judovih? In Gospod mu reče: Pojdi! In David vpraša: Kam naj grem? Veli: V Hebron!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 2, 'David torej gre gori in tudi dve ženi njegovi, Ahinoama Jezreelska in Abigaila, bivša žena Nabala Karmelskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 3, 'Tudi može, ki so bili pri njem, je pripeljal David gori, vsakega z družino njegovo, in prebivali so v hebronskih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 4, 'In prišli so možje Judovi in so ondi pomazilili Davida za kralja hiši Judovi. In ko so povedali Davidu, da so možje iz Jabesa v Gileadu pokopali Savla,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 5, 'pošlje sle k možem v Gileadski Jabes in jim sporoči: Blagoslovljeni bodite od Gospoda, da ste izkazali to milost gospodu svojemu, Savlu, in ste ga pokopali!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 6, 'Sedaj pa izkaži Gospod milost in zvestobo vam, pa tudi jaz povrnem to dobro delo vam, ki ste ga storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 7, 'Sedaj torej naj bodo močne roke vaše in hrabri bodite! Kajti Savel, gospod vaš, je mrtev, in mene je pomazilila hiša Judova sebi za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 8, 'Abner pa, sin Nerov, poveljnik Savlove vojske, je vzel Isboseta, Savlovega sina, ter ga je prepeljal v Mahanaim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 9, 'in postavil za kralja nad Gileadom in nad Asurskimi in nad Jezreelom in Efraimom in Benjaminom in nad vsem Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 10, 'Isboset, sin Savlov, je bil štirideset let star, ko je zakraljeval Izraelu, in vladal je dve leti. Samo hiša Judova je šla za Davidom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 11, 'Časa pa, ki je v njem kraljeval David v Hebronu hiši Judovi, je bilo sedem let in šest mesecev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 12, 'In Abner, sin Nerov, je odrinil s hlapci Isboseta, Savlovega sina, iz Mahanaima v Gibeon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 13, 'Tudi Joab, sin Zervijin, in hlapci Davidovi so odrinili, in so se srečali pri ribniku v Gibeonu; in sedejo eni na oni strani ribnika, drugi pa na tej strani ribnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 14, 'Abner pa reče Joabu: Vstanejo naj mladeniči in igrajo boj pred nami. In Joab reče: Naj vstanejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 15, 'Tedaj vstanejo in nastopijo po številu: dvanajst za Benjamina in za Isboseta, sina Savlovega, in dvanajst iz hlapcev Davidovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 16, 'In zgrabi vsakteri svojega nasprotnika za glavo in mu zasadi meč v stran, in popadajo skupaj. Zato se tisto mesto imenuje Helkat-hazurim, ki je v Gibeonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 17, 'In vnel se je zelo trd boj tisti dan, in hlapci Davidovi porazijo Abnerja in može Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 18, 'Bili so pa ondi trije sinovi Zervije: Joab in Abisaj in Asahel. In Asahel je bil lahkih nog kakor katera izmed srn, ki živé na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 19, 'In Asahel je podil Abnerja in se ni obrnil ne na desno, ne na levo, tekoč za Abnerjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 20, 'Tedaj se ozre Abner in reče: Si li ti Asahel? Odgovori: Sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 21, 'In Abner mu veli: Obrni se ali na desno ali na levo in primi teh mladeničev enega in si vzemi njegovo orožje! Ali Asahel se ni hotel odvrniti od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 22, 'In Abner zopet veli Asahelu: V stran kreni, ne hodi za menoj! Zakaj hočeš, da te pobijem na tla? Kako bi smel potem stopiti bratu tvojemu Joabu pred oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 23, 'Vendar pa ni hotel kreniti od njega; zato ga Abner udari z zadnjim koncem sulice v trebuh, da mu je pogledala sulica odzadaj, in pade ondi in umrje na tistem mestu. In kdorkoli je prišel na mesto, kjer je Asahel padel in umrl, se je ustavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 24, 'Joab in Abisaj pa sta podila Abnerja, in solnce je bilo zašlo, ko sta dospela do griča Ame, ki je pred Giahom, ob poti v Gibeonsko puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 25, 'In sinovi Benjaminovi se zbero pri Abnerju ter se skupijo v krdelo, in stopijo na vrh griča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 26, 'Tedaj kliče Abner proti Joabu in reče: Bode li meč žrl brez konca? Ne veš li, da nazadnje pride bridkost? Kako dolgo nočeš reči ljudstvu, da naj neha preganjati svoje brate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 27, 'In Joab reče: Kakor res Bog živi, ako bi ne bil ti govoril, bi se bilo ljudstvo že davi vrnilo, ne eden ne bi bil tiral brata svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 28, 'Tedaj zatrobenta Joab, in vse ljudstvo se ustavi, in niso več podili Izraela, niti se več bojevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 29, 'Abner in možje njegovi pa so šli vso noč po nižini in so prešli Jordan ter prehodili ves Bitron in prišli v Mahanaim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 30, 'In Joab se vrne od Abnerja, in ko je zbral vse ljudstvo, je manjkalo izmed hlapcev Davidovih devetnajst mož in Asahela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 31, 'A hlapci Davidovi so pobili iz Benjamincev in iz Abnerjevega moštva tristo in šestdeset mož, ki so umrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 2, 32, 'In so vzdignili Asahela in ga pokopali v grobu očeta njegovega v Betlehemu. Joab in možje njegovi pa so hodili vso noč, in dan jim je zasvital, ko so dospeli v Hebron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 1, 'In bil je dolgo boj med hišo Savlovo in hišo Davidovo. In David je čimdalje bolj napredoval, Savlova hiša pa je bolj in bolj pešala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 2, 'In Davidu so se rodili sinovi v Hebronu: prvenec je bil Amnon, iz Ahinoame Jezreelske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 3, 'drugi pa Kileab, iz Abigaile, bivše žene Nabala Karmelskega; in tretji Absalom, sin Maake, hčere Talmaja, kralja v Gesurju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 4, 'četrti Adonija, sin Hagite, in peti Sefatija, sin Abitale;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 5, 'in šesti Itream iz Egle, žene Davidove. Ti so se rodili Davidu v Hebronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 6, 'In bilo je, dokler sta se bojevali hiša Savlova in hiša Davidova, da se je Abner kazal močnega za hišo Savlovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 7, 'Savel pa je bil imel priležnico, po imenu Ricpo, hčer Ajevo. In Isboset reče Abnerju: Zakaj se družiš z očeta mojega priležnico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 8, 'In razjezi se Abner hudo zaradi teh besed Isbosetovih in reče: Sem li jaz pasja glava, ki se oklepa Jude? Danes izkazujem milost hiši očeta tvojega Savla, bratom in prijateljem njegovim, in tebe nisem izdal Davidu v roke, pa ti mi danes očitaš pregrešek s tisto žensko?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 9, 'Bog naj stori Abnerju to in ono naj pridene, ako ne izvršim, kakor je Gospod prisegel Davidu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 10, 'da se vzame kraljestvo od hiše Savlove in se postavi Davidov prestol nad Izraelom in nad Judo, od Dana do Bersebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 11, 'In ni mogel Abnerju odgovoriti besede, ker se ga je bal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 12, 'In pošlje Abner poročnike pri tej priči k Davidu in reče: Čigava je dežela? in sporoči: Skleni zavezo z menoj, in glej, roka moja bode s teboj, da potegnem vsega Izraela za teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 13, 'David reče: Dobro, hočem storiti zavezo s teboj; le eno reč zahtevam od tebe, namreč: ne boš videl obličja mojega, razen da mi prej pripelješ Mihalo, hčer Savlovo, ko prideš, da vidiš obličje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 14, 'Pošlje tudi David poročnike k Isbosetu, Savlovemu sinu, in sporoči: Daj mi ženo mojo Mihalo, ki sem si jo zaročil s sto sprednjimi kožicami Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 15, 'In Isboset pošlje in jo vzame od moža njenega, od Faltiela, sina Laisovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 16, 'In njen mož je šel ž njo in spotoma jokal, idoč za njo do Bahurima. Tedaj mu reče Abner: Pojdi, vrni se! In se je vrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 17, 'In Abner se je zmenil s starejšinami Izraelovimi in dejal: Nekdaj ste želeli, da vam bodi David kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 18, 'Sedaj pa izvršite to! Zakaj Gospod je govoril o Davidu: Po roki služabnika mojega Davida hočem rešiti ljudstvo svoje Izraela iz roke Filistejcev in iz vseh njih sovražnikov pesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 19, 'Enako je govoril Abner na ušesa Benjamincem. Potem je šel Abner govorit tudi na ušesa Davidu v Hebronu vse, kar se je dobro videlo Izraelu in vsej Benjaminovi hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 20, 'Pride tedaj Abner k Davidu v Hebron in dvajset mož ž njim. In David napravi gostijo Abnerju in možem, ki so bili pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 21, 'In Abner reče Davidu: Vstanem in pojdem in zberem vsega Izraela h gospodu svojemu, kralju, da bi sklenili zavezo s teboj in da boš vsem kraljeval, kakor želi duša tvoja. Nato odpošlje David Abnerja, in ta odide v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 22, 'In glej, hlapci Davidovi in Joab se vrnejo z bojnega obhoda in prineso veliko plena s seboj. Abner pa ni bil več pri Davidu v Hebronu, zakaj ta ga je bil odposlal, in on je šel v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 23, 'Ko torej pride Joab z vsem bojnim moštvom, povedo Joabu, rekoč: Abner, sin Nerov, je prišel h kralju, in on ga je pustil, da je šel v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 24, 'Tedaj gre Joab noter h kralju in reče: Kaj si storil? Glej, Abner je prišel k tebi: zakaj si ga odpustil, da je šel, kamor mu drago?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 25, 'Poznaš vendar Abnerja, Nerovega sina, da te je prišel varat in pozvedovat, kako hodiš ven in noter, da bi vedel vse, kar delaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 26, 'In ko pride Joab od Davida, pošlje sle za Abnerjem, in privedejo ga od vodnjaka Sire. A David ni vedel za to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 27, 'Ko pa se vrne Abner v Hebron, ga potegne Joab na stran pod vrata, da bi na tihem ž njim govoril, in tam ga zabode v trebuh, da je umrl, zaradi krvi Asahela, brata njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 28, 'Ko David poslej to zasliši, reče: Nedolžen sem in kraljestvo moje pred Gospodom vekomaj pri krvi Abnerja, sina Nerovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 29, 'Naj pride ta kri na glavo Joabu in na njegovega očeta vso hišo, in hiša Joabova ne bodi nikdar brez človeka, ki ima sluzotok ali gobe, ali ki hodi ob palici, ali ki pade pod mečem, ali ki mu primanjkuje kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 30, 'Tako sta Joab in Abisaj, brat njegov, umorila Abnerja, zato ker je usmrtil njiju brata Asahela v boju pri Gibeonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 31, 'David pa veli Joabu in vsemu ljudstvu, ki je bilo pri njem: Raztrgajte oblačila svoja in prepašite se z raševnikom in žalujte pred Abnerjem! In David kralj je šel za mrtvaškim odrom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 32, 'In pokopali so Abnerja v Hebronu, in kralj je povzdignil glas svoj in jokal pri grobu Abnerjevem, in vse ljudstvo je plakalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 33, 'In kralj je pel žalostinko nad Abnerjem, govoreč: Je li moral umreti Abner, kakor umre nespametnik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 34, 'Roke tvoje niso bile zvezane, ne noge tvoje vklenjene v spone; padel si, kakor pade človek pred malopridneži! In vse ljudstvo je plakalo za njim tem bolj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 35, 'In vse ljudstvo pride, da nagne Davida, da bi jedel kruh, dokler je še dan; a David priseže, rekoč: Bog mi stóri to in prideni še to, ako okusim kruh ali kaj drugega, dokler ne zajde solnce!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 36, 'In vse ljudstvo je to priznalo in mu je ugajalo, kakor je bilo sploh, karkoli je storil kralj, dobro v očeh ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 37, 'In spoznalo je vse ljudstvo in ves Izrael tisti dan, da ni prišlo od kralja, da je bil ubit Abner, sin Nerov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 38, 'In kralj reče hlapcem svojim: Ne veste li, da je danes padel knez in velikan v Izraelu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 3, 39, 'Jaz pa sem še slaboten, čeprav maziljeni kralj. In ta dva moža, sinova Zervijina, sta mi pretrda. Gospod poplačaj tistemu, ki ravna krivično, po krivičnosti njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 1, 'In ko je slišal Isboset, Savlov sin, da je Abner mrtev v Hebronu, mu omahnejo roke, in ves Izrael se ustraši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 2, 'Imel pa je Savlov sin dva moža, poveljnika trum: enemu je bilo ime Baana, drugemu pa Rekab, sinova Rimona Berotčana, izmed sinov Benjaminovih (kajti Berot se tudi šteje k Benjaminu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 3, 'bili so pa Berotčani bežali v Gitaim in so ondi prebivali do današnjega dne).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 4, 'Jonatan pa, Savlov sin, je imel sina, hromega na nogah. Pet let je bil star, ko je prišla vest o Savlu in Jonatanu iz Jezreela; in njegova dojka ga je vzela in bežala, in ko je hitela, da ubeži, je padel in ohromel. In ime mu je bilo Mefiboset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 5, 'In sinova Rimona Berotčana, Rekab in Baana, sta šla in dospela, ko je bil dan najbolj vroč, v hišo Isbosetovo, ko je počival na postelji opoldne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 6, 'In stopita sredi hiše, kakor da bi hotela vzeti pšenice, in ga zabodeta pod rebra, in Rekab in Baana, brat njegov, zbežita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 7, 'Ko sta namreč prišla v hišo in je on ležal v spalnici svoji na postelji, ga udarita in umorita ter mu odsekata glavo, in vzameta glavo njegovo in bežita po poti nižine Arabe vso noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 8, 'In prineseta glavo Isbosetovo Davidu v Hebron in rečeta kralju: Glej, glava Isboseta, sina Savlovega, tvojega sovražnika, ki ti je stregel po življenju! Gospod je danes maščeval gospoda mojega, kralja, nad Savlom in nad semenom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 9, 'David pa odgovori Rekabu in Baanu, bratu njegovemu, sinoma Rimona Berotčana, in jima reče: Kakor res živi Gospod, ki je odrešil dušo mojo vseh bridkosti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 10, 'ko mi je tisti oznanil, rekoč: Glej, Savel je mrtev! in je menil, da je vesela vest zame, pa sem ga prijel in umoril v Ziklagu ter mu dal s tem plačilo za vest njegovo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 11, 'koliko bolj, ko sta dva brezbožneža umorila pravičnega moža v njegovi hiši na postelji njegovi! nimam li zdaj zahtevati krvi njegove iz vajinih rok in vaju potrebiti z zemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 4, 12, 'In David zapove mladeničem svojim, in ti so ju umorili in jima odsekali roke in noge in so ju obesili pri ribniku v Hebronu. Glavo Isbosetovo pa so vzeli in jo pokopali v Abnerjevem grobu v Hebronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 1, 'Tedaj pridejo vsi rodovi Izraelovi k Davidu v Hebron in ga ogovore, rekoč: Glej, kost smo tvoja in meso tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 2, 'In že v prejšnjih časih, ko nam je kraljeval Savel, ti si vodil ven in noter Izraela; in tebi je rekel Gospod: Ti boš pasel ljudstvo moje Izraela in ti bodeš vojvoda Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 3, 'Tako so prišli vsi starejšine Izraelovi h kralju v Hebron; in kralj David je sklenil ž njimi zavezo v Hebronu pred Gospodom. In pomazilili so Davida za kralja Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 4, 'David je bil trideset let star, ko je zakraljeval, in vladal je štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 5, 'V Hebronu je kraljeval Judi sedem let in šest mesecev, v Jeruzalemu pa je kraljeval triintrideset let vsemu Izraelu in Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 6, 'In kralj in možje njegovi so šli v Jeruzalem zoper Jebusejce, prebivalce v deželi. Ti so govorili Davidu: Ne prideš sem noter, temuč slepci in hromci te odženejo – meneč, David ne more priti tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 7, 'Vendar pa je David dobil grad Sion, to je mesto Davidovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 8, 'Kajti David je dejal tisti dan: Kdor premaga Jebusejce in pride do žlebov in porazi tiste hromce in slepce, ki jih sovraži duša Davidova, bodi poglavar! Odtod pravijo: Slepci in hromci ne pridejo v hišo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 9, 'In David se je nastanil v tem gradu in ga je imenoval mesto Davidovo. In David je zidal okoli ob Milu in znotraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 10, 'In David je bolj in bolj napredoval, zakaj Gospod, Bog nad vojskami, je bil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 11, 'In Hiram, kralj v Tiru, je poslal poslance k Davidu in cedrovega lesa in tesarje in zidarje, in zgradili so Davidu hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 12, 'In David je spoznal, da ga je Gospod potrdil za kralja v Izraelu ter da je povišal kraljestvo njegovo zaradi ljudstva svojega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 13, 'In David si je vzel še več priležnic in žen v Jeruzalemu, potem ko je prišel iz Hebrona; in rodilo se je Davidu še več sinov in hčerá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 14, 'Ta pa so imena tistih, ki so se mu rodili v Jeruzalemu: Samua, Sobab, Natan in Salomon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 15, 'Ibhar, Elisua, Nefeg in Jafija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 16, 'in Elisama, Eliada in Elifelet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 17, 'Ko pa Filistejci začujejo, da so pomazilili Davida za kralja nad Izraelom, krenejo vsi gori iskat Davida; David pa, ko je zvedel, odide doli v grad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 18, 'Filistejci pa pridejo in se razpostavijo v dolini Refaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 19, 'In David je vprašal Gospoda, rekoč: Ali naj grem gori zoper Filistejce? In jih li hočeš dati v roko mojo? Gospod pa veli Davidu: Pojdi gori, kajti gotovo ti dam Filistejce v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 20, 'In David pride v Baalperazim [T. j. mesto pretrga.] in jih porazi ondi ter reče: Gospod je raztrgal sovražnike moje pred menoj, kakor ko vode pretrgajo jez. Zato je imenoval ime tistega kraja Baalperazim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 21, 'In pustili so svoje malike ondi, David pa in možje njegovi so jih odnesli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 22, 'In Filistejci pridejo zopet gori ter se razpostavijo v dolini Refaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 23, 'In ko David vpraša Gospoda, mu veli: Ne hodi gori, temuč obidi jih zadaj za njimi, da prideš nadnje od strani murvovih dreves.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 24, 'In ko začuješ šumenje iz vrhov dreves, kakor da prihaja vojska, tedaj se podvizaj: zakaj tedaj gre Gospod pred teboj, da premaga vojsko Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 5, 25, 'In David je storil, kakor mu je bil zapovedal Gospod, in pobijal je Filistejce od Gebe do tja, koder se hodi v Gezer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 1, 'In David je zopet zbral vse izbrano moštvo v Izraelu, trideset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 2, 'In vstane David ter gre z vsem ljudstvom, kar ga je bilo pri njem, iz Baale Judove, da prinese odondod skrinjo Božjo, ob kateri se kliče Ime, ime Gospoda nad vojskami, ki stoluje nad kerubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 3, 'In postavili so skrinjo Božjo na nov voz in jo odnesli iz Abinadabove hiše, ki je bila na griču. Uza in Ahio, sinova Abinadabova, sta vodila novi voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 4, 'In ko so ga peljali s skrinjo Božjo iz hiše Abinadabove na griču, je šel Ahio pred skrinjo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 5, 'a David in ves rod Izraelov je igral pred Gospodom na vsakovrstna godala iz cipresovine in na harfe in na strune s petjem in na bobne in zvončke in cimbale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 6, 'In ko so prišli h gumnu Nakonovemu, je Uza iztegnil roko po skrinji Božji in jo pridržal, zakaj volom se je izpoddrsnilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 7, 'In vname se jeza Gospodova zoper Uza, in Bog ga udari ondi za njegov pregrešek; in je umrl tam pri skrinji Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 8, 'In David je bil žalosten, ker je bil Gospod naredil pretrg z Uzom, in imenoval je ta kraj Perez Uza, do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 9, 'In David se zboji Gospoda tisti dan, in reče: Kako naj pride skrinja Gospodova k meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 10, 'In David ni hotel nesti skrinje Gospodove k sebi, v mesto Davidovo, temuč jo je dal odnesti v hišo Obededoma Gatovca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 11, 'In ostala je skrinja Gospodova v hiši Obededoma Gatovca tri mesece; in Gospod je blagoslovil Obededoma in vso hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 12, 'In povedali so kralju Davidu, rekoč: Gospod je blagoslovil hišo Obededomovo in vse, kar je njegovo, zaradi skrinje Božje. David pa gre in z veseljem prenese skrinjo Božjo iz hiše Obededomove gori v mesto Davidovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 13, 'In kolikorkrat so prestopili nosilci skrinje Gospodove šest korakov, je daroval vola in pitanca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 14, 'In David je plesal z vso močjo pred Gospodom in bil je opasan s platnenim naramnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 15, 'Tako je prenesel David in vsa hiša Izraelova skrinjo Gospodovo gori z radostnim petjem in glasom trombe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 16, 'In ko je prišla skrinja Gospodova v mesto Davidovo, je gledala Mihala, hči Savlova, skozi okno in je videla kralja Davida, da poskakuje in pleše pred Gospodom, in ga je zaničevala v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 17, 'Ko so pa prinesli skrinjo Gospodovo noter, jo postavijo na nje mesto sredi šatora, ki ga je bil David razpel zanjo. In David je daroval žgalne in mirovne daritve pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 18, 'In ko je David končal darovanje žgalščin in mirovnih žrtev, je blagoslovil ljudstvo v imenu Gospoda nad vojskami');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 19, 'in je podelil vsemu ljudstvu, vsej množici Izraelovi, možem in ženam, vsakemu hlebček kruha in kos mesa in kepo suhega grozdja. In ljudstvo se je razšlo, vsakdo v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 20, 'Potem se David vrne, da blagoslovi hišo svojo. In Mihala, hči Savlova, mu pride naproti in reče: Kako častit je danes bil kralj Izraelov, ki se je danes razodeval pred deklami hlapcev svojih, kakor se nesramno razodevajo lahkomiselneži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 21, 'David pa reče Mihali: Igral sem pred Gospodom, ki me je izvolil mimo očeta tvojega in mimo vse hiše njegove, da me postavi za vojvodo ljudstvu Gospodovemu, Izraelu, in še bom igral pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 22, 'In še bolj se hočem ponižati in nizek biti v svojih očeh, a pri deklah, ki si o njih govorila, si s tem pridobim čast!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 6, 23, 'In Mihala, hči Savlova, ni dobila zaroda do dne smrti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 1, 'In zgodi se, ko je prebival kralj v hiši svoji in mu je Gospod dal pokoj od vseh sovražnikov njegovih okoli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 2, 'da reče kralj Natanu proroku: Poglej zdaj, jaz stanujem v cedrovi hiši, skrinja Božja pa prebiva pod preprogami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 3, 'In Natan veli kralju: Pojdi, stóri vse, kar ti je v srcu, zakaj Gospod je s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 4, 'A še to noč pride beseda Gospodova k Natanu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 5, 'Pojdi in reci hlapcu mojemu, Davidu: Tako pravi Gospod: Ali mi boš ti zgradil hišo, da prebivam v njej?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 6, 'Saj nisem prebival v hiši od dne, ko sem odpeljal sinove Izraelove iz Egipta, do današnjega dne, temuč sem hodil ž njimi v šatoru in prebivališču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 7, 'Kamorkoli sem šel z vsemi sinovi Izraelovimi, sem li kdaj besedo govoril s katerim rodov Izraelovih, ki sem jim zapovedal pasti ljudstvo moje, Izraela, rekoč: Zakaj mi niste zgradili cedrove hiše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 8, 'Tako torej véli hlapcu mojemu, Davidu: Tako pravi Gospod nad vojskami: Jaz sem te vzel s pašnikov, ko si hodil za ovcami, da bodeš vojvoda ljudstvu mojemu, Izraelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 9, 'in sem bil s teboj, kamorkoli si šel, in sem zatrl vse sovražnike tvoje pred teboj in storil ti veliko ime, kakor ime velikašev, ki so na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 10, 'In hočem pripraviti mesto ljudstvu svojemu in jih posaditi, da bodo prebivali na svojem in se več ne premikali, da jih tudi ne bodo stiskali več sinovi krivice kakor poprej');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 11, 'in odkar sem zapovedal sodnikom, da naj bodo nad ljudstvom mojim, Izraelom. In dal sem ti pokoj pred vsemi sovražniki tvojimi. Vrhutega ti Gospod oznanja, da Gospod zgradi hišo tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 12, 'Ko se ti dopolnijo dnevi in boš ležal z očeti svojimi, hočem za tabo obuditi seme tvoje, ki pride iz osrčja tvojega, in utrditi kraljestvo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 13, 'On zgradi hišo imenu mojemu, in jaz utrdim kraljestva njegovega prestol na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 14, 'Jaz mu bodem za očeta, in on mi bode za sina. Kadar stori kaj krivega, ga bom pokoril s človeško šibo in kaznoval z udarci človečjih otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 15, 'Ali milost moja ne odstopi od njega, kakor sem jo odtegnil Savlu, ki sem ga odpravil izpred tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 16, 'Ampak hiša tvoja in kraljestvo tvoje bode stanovitno pred teboj vekomaj, prestol tvoj bodi utrjen na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 17, 'Po vseh teh besedah in po vsej tej prikazni je točno govoril Natan Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 18, 'Tedaj stopi David noter in sede pred Gospoda in reče: Kdo sem jaz, o Gospod Jehova, in kaj je hiša moja, da si me privedel tako daleč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 19, 'In to se je še premalo videlo tvojim očem, o Gospod Jehova, kajti govoril si tudi o hlapca svojega hiši za daljno prihodnost, in to po načinu človeka, Gospod Jehova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 20, 'In kaj more David še govoriti tebi? Saj poznaš hlapca svojega, o Gospod Jehova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 21, 'Zaradi besede svoje in po srcu svojem si storil vso to velikost, oznanivši jo hlapcu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 22, 'Zategadelj si velik, o Jehova Bog! kajti ni ga tebi enakega, tudi ni Boga razen tebe, po vsem tem, kar smo slišali z ušesi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 23, 'In je li en narod na zemlji podoben ljudstvu tvojemu, Izraelu, ki je zaradi njega šel Bog, da ga odkupi sebi v ljudstvo ter si napravi veliko ime in stori take velike in strašne reči zanj in za deželo svojo, vpričo ljudstva svojega, ki si ga sebi odkupil iz Egipta, izpod oblasti narodov in njih bogov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 24, 'In pripravil si sebi ljudstvo svoje, Izraela, da ti bodi ljudstvo na veke, ti pa, Jehova, si postal njih Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 25, 'Sedaj pa, o Jehova Bog, potrdi na vekomaj besedo, ki si jo govoril za hlapca svojega in za hišo njegovo, in stori, kakor si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 26, 'Da naj se poveličuje ime tvoje vekomaj in se govori: Gospod nad vojskami je Bog nad Izraelom. In hiša hlapca tvojega Davida bodi trdna pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 27, 'Zakaj ti, Gospod nad vojskami, Bog Izraelov, si razodel ušesu hlapca svojega, rekoč: Hišo ti hočem zgraditi. Zato se je hlapec tvoj osrčil, da moli to molitev tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 28, 'In sedaj, o Gospod Jehova, ti si Bog, in besede tvoje so resnica, in ti si govoril hlapcu svojemu to predobro obljubo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 7, 29, 'sedaj torej rači blagosloviti hlapca svojega hišo, da ostane pred teboj vekomaj, zakaj ti, o Gospod Jehova, si to obljubil. Bodi torej z blagoslovom tvojim blagoslovljena tvojega hlapca hiša vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 1, 'In zgodi se potem, da je porazil David Filistejce in jih ponižal. In David je vzel uzdo vladarstva iz rok Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 2, 'Porazil je tudi Moabce in jih premeril z vrvjo, ko jih je dal položiti na tla, in po dve vrvi jih je odmeril v smrt, po eno celo vrv pa, da žive. Tako so Moabci postali podložni Davidu in so mu prinašali darove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 3, 'David je tudi porazil Hadadezerja, sina Rehobovega, kralja v Zobi, ko je šel, da si spet pridobi oblast pri veletoku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 4, 'In David je iz njih ujel tisoč in sedemsto konjikov in dvajset tisoč pešcev ter je ohromil vse vprežne konje, ohranil jih je samo za sto voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 5, 'A Sirci so prišli iz Damaska pomagat Hadadezerju, kralju v Zobi. David pa je pobil Sircev dvaindvajset tisoč mož');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 6, 'in postavil posadko v Sirijo ob Damasku; tako so postali Sirci Davidu podložni in so mu prinašali darove. Kajti Gospod je pomagal Davidu, kamorkoli je šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 7, 'In David je vzel zlate ščite, ki so jih imeli hlapci Hadadezerjevi, in jih je prinesel v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 8, 'In iz Betaha in iz Berotaja, mest Hadadezerjevih, je kralj David vzel mnogo brona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 9, 'In ko začuje Toj, kralj v Hamatu, da je David porazil vso vojsko Hadadezerjevo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 10, 'pošlje sina svojega Jorama h kralju Davidu, da ga pozdravi ter mu čestita, da se je bojeval zoper Hadadezerja in ga je porazil; zakaj Toj se je vedno vojskoval s Hadadezerjem. In Joram je prinesel s seboj srebrne, zlate in bronaste posode;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 11, 'te je kralj David tudi posvetil Gospodu s srebrom in zlatom vred, ki ga je Gospodu posvetil od vseh narodov, kar si jih je bil podvrgel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 12, 'od Sircev, od Moabcev, od sinov Amonovih, od Filistejcev, od Amalekovcev in iz plena Hadadezerja sina Rehobovega, kralja v Zobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 13, 'In David si je pridobil ime, ko se je vrnil, porazivši Sirce v Solni dolini, osemnajst tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 14, 'In postavil je posadke v Edomu, po vsem Edomu je postavil posadke, in vsi Edomci so postali Davidovi podložniki. Kajti Gospod je pomagal Davidu, kamorkoli je šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 15, 'In David je kraljeval vsemu Izraelu, in izvrševal je sodbo in pravičnost vsemu ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 16, 'Joab pa, sin Zervijin, je bil nad vojsko, in Josafat, sin Ahiludov, je bil deželni letopisec;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 17, 'Zadok, sin Ahitubov, in Ahimelek, sin Abiatarjev, sta bila duhovnika, in Seraja je bil pisar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 8, 18, 'in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci, in sinovi Davidovi so bili prvi dvorjani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 1, 'In David je dejal: Je li še kdo, ki je preostal iz hiše Savlove, da mu izkažem milost zaradi Jonatana?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 2, 'Bil pa je hlapec iz hiše Savlove, po imenu Ziba; tega pokličejo k Davidu. In kralj ga vpraša: Si li ti Ziba? On reče: Da, hlapec tvoj je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 3, 'In kralj reče: Je li še kdo od hiše Savlove, da mu izkažem milost Božjo? Ziba odgovori kralju: Še je sin Jonatanov, hrom na nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 4, 'In kralj ga vpraša: Kje je? In Ziba reče kralju: Glej, on je v hiši Mahirja, sina Amielovega, v Lodebarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 5, 'Nato pošlje kralj David in ga da pripeljati iz hiše Mahirja, sina Amielovega, iz Lodebarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 6, 'In Mefiboset, sin Jonatana, sina Savlovega, pride k Davidu in pade na obraz in stori poklon. David pa reče: Mefiboset! On odgovori: Tu sem, hlapec tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 7, 'In David mu reče: Ne boj se! zakaj gotovo ti hočem izkazati milost zaradi Jonatana, očeta tvojega, in povrnem ti vse njive Savla, očeta tvojega, in jedel boš kruh pri moji mizi vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 8, 'On se pokloni in reče: Kaj je hlapec tvoj da se oziraš na mrtvega psa, kakor sem jaz?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 9, 'Tedaj pokliče kralj Ziba, Savlovega hlapca, in mu reče: Vse, kar je bilo Savlovega in vse njegove rodbine, sem dal sinu gospodarja tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 10, 'Obdeluj torej zemljo njegovo zanj ti in sinovi in hlapci tvoji, in spravljaj pridelke, da bodo kruh sinu gospodarja tvojega, da se s tem živi; ali Mefiboset, gospodarja tvojega sin, bo vsak dan jedel kruh pri mizi moji. Imel pa je Ziba petnajst sinov in dvajset hlapcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 11, 'Nato reče Ziba kralju: Po vsem, kar je zapovedal gospod moj, kralj, svojemu hlapcu, bo storil hlapec tvoj. Zastran Mefiboseta, veli kralj, ta bo jedel pri mizi kakor kraljevih otrok eden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 12, 'Mefiboset pa je imel majhnega sina, po imenu Miha. In vsi, ki so bivali v hiši Zibovi, so bili hlapci Mefibosetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 9, 13, 'In Mefiboset je prebival v Jeruzalemu, zakaj jedel je vsak dan pri kraljevi mizi. Bil pa je hrom na obeh nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 1, 'In zgodi se potem, da je umrl kralj Amonovih sinov, in Hanun, sin njegov, je zakraljeval na njegovem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 2, 'In David reče: Milost izkažem Hanunu, sinu Nahasovemu, kakor je njegov oče izkazal milost meni. Pošlje torej David in mu sporoči po hlapcih svojih sožalje zaradi očeta njegovega. Ko so pa prišli hlapci Davidovi v deželo Amonovih sinov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 3, 'reko knezi Amonovcev Hanunu, gospodu svojemu: Meniš li, da David spoštuje očeta tvojega, ker je poslal tolažnike k tebi? Ni li poslal David hlapcev svojih, da ogleda mesto in ga preišče in potem razvrne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 4, 'Nato vzame Hanun hlapce Davidove in jim obrije polovico brade in odreže njih oblačil polovico do pasa, in jih pošlje nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 5, 'Ko se to sporoči Davidu, jim pošlje naproti; zakaj ti možje so bili silno osramočeni. In kralj jim sporoči: Ostanite v Jerihu, dokler vam ne porasto brade, potem se vrnite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 6, 'In ko so videli sinovi Amonovi, da so se omrzili Davidu, pošljejo in najmejo Sirce iz Bet-rehoba in Sirce iz Zobe, dvajset tisoč pešcev, in kralja v Maaki s tisoč možmi in iz Toba dvanajst tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 7, 'Ko pa David to sliši, pošlje Joaba in vso vojsko junakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 8, 'In Amonovi sinovi gredo iz mesta in se pripravijo za boj ob vhodu v vrata. In Sirci iz Zobe in iz Rehoba in možje iz Toba in Maake so stali posebe na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 9, 'Ko torej Joab vidi, da je spredaj in zadaj naskok naperjen proti njemu, izbere iz vseh najboljših mož Izraelovih in se pripravi zoper Sirce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 10, 'Ostalo ljudstvo pa da pod roko brata svojega Abisaja, da jih postavi zoper Amonove sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 11, 'In veli: Ako mi bodo Sirci premočni, bodi mi v pomoč, ako bodo pa Amonovci tebi premočni, pridem ti v pomoč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 12, 'Bodi srčen, in junaški se bojujva za ljudstvo naše in za mesta Boga našega, in Gospod naj stori, kar se mu vidi dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 13, 'In Joab in ljudstvo, ki je bilo pri njem, se približa na boj zoper Sirce, in zbeže pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 14, 'Ko pa vidijo Amonovi sinovi, da so bežali Sirci, zbeže tudi oni pred Abisajem in pridejo v svoje mesto. Tedaj se vrne Joab od Amonovcev in pride v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 15, 'In ko vidijo Sirci, da so jih porazili Izraelci, se zbero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 16, 'In Hadarezer pošlje in veli pripeljati Sirce, ki so bili onostran reke, in pridejo v Helam s Sobahom, poveljnikom vojske Hadarezerjeve na čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 17, 'In to se oznani Davidu; in zbere vsega Izraela in preide Jordan in dospe v Helam. Sirci se pa pripravijo zoper Davida in se bojujejo ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 18, 'A Sirci zbeže pred Davidom; in David je pobil iz Sircev mož od sedemsto voz in štirideset tisoč konjikov, udaril je tudi Sobaha, poveljnika njih vojske, da je ondi umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 10, 19, 'In ko so videli vsi kralji, ki so bili v službi Hadarezerjevi, da so bili poraženi pred Izraelom, so sklenili mir z Izraelci in so jim bili podložni. In Sirci so se bali pomagati še dalje Amonovim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 1, 'In ko je preteklo leto, ob času, ko hodijo kralji ven na boj, pošlje David Joaba in hlapce svoje ž njim in vsega Izraela; in opustošili so deželo Amonovih sinov in oblegali Rabo. David pa je ostal v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 2, 'In zgodi se proti večeru, ko je vstal David iz postelje in se je izprehajal po strehi kraljeve hiše, da je videl s strehe ženo, ki se je kopala. Žena pa je bila silno lepega lica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 3, 'In David pošlje in vpraša po tisti ženi. In nekdo reče: Ni li Batseba, hči Eliamova, žena Urija Hetejca?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 4, 'In David pošlje tja sle in jo da pripeljati. In pride k njemu, in on je spal pri njej. In ko se je očistila nečistote svoje, se vrne v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 5, 'In žena je spočela; in pošlje ter oznani Davidu, rekoč: Spočela sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 6, 'In David sporoči Joabu: Pošlji mi Urija Hetejca! In Joab pošlje Urija k Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 7, 'In ko pride Urija k njemu, ga vpraša David, kako se godi Joabu in ljudstvu ter kako napreduje vojska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 8, 'In David veli Uriju: Pojdi doli v hišo svojo in umij si noge! In Urija odide iz kraljeve hiše, in za njim pride kraljevo darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 9, 'Ali Urija je spal pred vrati kraljeve hiše z vsemi hlapci gospoda svojega in ni šel doli v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 10, 'In ko so povedali Davidu: Urija ni šel doli v hišo svojo, reče David Uriju: Nisi li prišel s pota? Zakaj nisi stopil doli v hišo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 11, 'Urija pa odgovori Davidu: Skrinja in Izrael in Juda bivajo v šatorih, in Joab, gospod moj, in gospoda mojega hlapci tabore na polju, in jaz naj bi šel v hišo svojo, da jem in pijem in spim pri ženi svoji? Kakor res živiš in kakor živi duša tvoja, tega ne storim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 12, 'In David veli Uriju: Ostani tu še danes, jutri te odpošljem! Tako je ostal Urija v Jeruzalemu tisti in naslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 13, 'In David ga povabi, da bi jedel in pil pred njim, in ga upijani; ali on gre zvečer ven leč na ležišče svoje s hlapci gospoda svojega, in ni šel doli v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 14, 'Zjutraj pa napiše David list Joabu in ga pošlje po Uriju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 15, 'V list pa napiše takole: Postavite Urija prvega tja, kjer je bitka najhujša, in umeknite se od njega, da ga udarijo in umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 16, 'Ko je torej Joab obkolil mesto, postavi Urija na mesto, za katero je vedel, da so tam junaški možje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 17, 'In možje planejo iz mesta in se bojujejo z Joabom, in padejo nekateri iz ljudstva, iz hlapcev Davidovih, tudi Urija Hetejec umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 18, 'Nato pošlje Joab in naznani Davidu vse, kar se je v boju prigodilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 19, 'in zapove slu, rekoč: Ko kralju dopoveš vse, kar se je v boju zgodilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 20, 'in boš videl, da se razsrdi in ti poreče: Zakaj ste tako blizu pristopili k mestu, da se bojujete? Niste li vedeli, da bodo z ozidja doli streljali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 21, 'Kdo je ubil Abimeleka, sina Jerub-besetovega? ni li vrgla žena zgornjega mlinskega kamena nanj z obzidja, da je umrl v Tebezu? Zakaj ste pristopili tako blizu zidovja? – tedaj reci: Hlapec tvoj, Urija Hetejec, je tudi mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 22, 'Šel je torej sel, in pride in oznani Davidu vse, kar mu je sporočil Joab.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 23, 'In reče sel Davidu: Možje so bili močnejši nego mi in so planili nad nas na polje, mi pa smo jih potisnili nazaj do vhoda v mestna vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 24, 'In strelci so streljali na hlapce tvoje z obzidja, da so umrli nekateri hlapcev kraljevih, in hlapec tvoj, Urija Hetejec, je tudi mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 25, 'David reče slu: Reci Joabu: Naj se ti ne zdi prehuda ta reč, zakaj meč požre zdaj tega, zdaj onega; vztrajaj le v boju zoper mesto in ga razdeni! S tem ga ohrabri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 26, 'Ko pa je slišala žena Urijeva, da je umrl Urija, njen mož, je žalovala po svojem soprogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 11, 27, 'In ko je minilo žalovanje, pošlje David in jo vzame v hišo svojo, in je postala žena njegova in mu je rodila sina. Ali reč, ki jo je bil David storil, je bila huda v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 1, 'In Gospod pošlje Natana k Davidu. In pride k njemu ter mu reče: Dva moža sta bila v enem mestu: eden bogat, drugi ubog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 2, 'Bogatin je imel silno veliko ovac in goved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 3, 'A ubožec ni imel ničesar razen edine drobne ovčice, ki si jo je bil kupil in zredil; in zrasla je pri njem ž njegovimi otroki vred: od njegovega grižljaja je jedla in iz njegovega kozarca je pila in njemu v naročju je spavala, in bila mu je kakor hči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 4, 'Pa pride popotnik k bogatinu, in temu se je žalilo vzeti iz ovac in goved svojih, da pripravi jed popotniku, ki je prišel k njemu, ampak vzame ubožcu ovčico ter jo pripravi možu, ki je dospel k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 5, 'In Davidov srd se silno razvname zoper tistega moža, in veli Natanu: Kakor res Gospod živi, sin smrti je človek, ki je to storil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 6, 'tudi ovco mora povrniti četvero, ker je tako reč storil in ker se mu ni smililo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 7, 'Natan pa reče Davidu: Ti si tisti mož! Tako pravi Gospod, Bog Izraelov: Jaz sem te pomazilil za kralja nad Izraelom in jaz sem te otel iz roke Savlove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 8, 'in dal sem ti gospodarja tvojega hišo in gospodarja tvojega žene v naročje tvoje, in dal sem ti hišo Izraelovo in Judovo; in ako bi to bilo premalo, bi hotel pridejati še to in ono.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 9, 'Zakaj si zaničeval besedo Gospodovo, da si storil, kar je hudo v očeh Gospodovih? Urija Hetejca si udaril z mečem in ženo njegovo sebi vzel za ženo, njega pa si umoril z mečem Amonovih sinov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 10, 'Sedaj torej ne odstopi meč od hiše tvoje nikdar, ker si me zaničeval in si vzel Uriju Hetejcu ženo, da bodi tvoja žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 11, 'Tako pravi Gospod: Glej, hočem obuditi nesrečo zoper tebe iz hiše tvoje, in vzamem žene tvoje tebi pred očmi in jih dam bližnjemu tvojemu, da bo spal pri ženah tvojih pri svetlem solncu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 12, 'Ti si res to skrivaj storil, ali jaz to storim vpričo vsega Izraela, ob belem dnevu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 13, 'In David reče Natanu: Grešil sem zoper Gospoda. A Natan reče Davidu: Gospod je tudi odvzel greh tvoj, ne boš umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 14, 'Toda ker si s tem dejanjem dal priliko sovražnikom Gospodovim, da preklinjajo, zato tudi sin, ki se ti je rodil, gotovo umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 15, 'In Natan odide domov. In Gospod udari otroka, ki ga je rodila žena Urijeva Davidu, in razboli se na smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 16, 'In David je iskal Boga zavoljo dečka in se je postil in prišel in ležal vso noč na tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 17, 'Tedaj vstanejo starejšine hiše njegove in stopijo okrog njega, da bi ga vzdignili s tal, ali on ni hotel, tudi ni jedel kruha ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 18, 'In zgodi se sedmi dan, da umrje dete. Bali so se pa hlapci Davidovi mu povedati, da je dete mrtvo, kajti dejali so: Glej, ko je dete še živelo, smo mu govorili, pa ni poslušal našega glasu; kako naj mu povemo, da je dete mrtvo? Lahko stori kaj hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 19, 'David pa, videč, da šepetajo med seboj hlapci njegovi, zazna, da je umrlo dete, in vpraša hlapce: Je li dete umrlo? Reko: Umrlo je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 20, 'Tedaj vstane David s tal in se umije in pomaže in preobleče, ter pride v hišo Gospodovo in moli. In ko se vrne domov, veli, naj mu prineso kruha, in jedel je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 21, 'Nato mu reko hlapci njegovi: Kaj je to, kar počenjaš? Ko je dete živelo, si se postil in plakal zanje, ko pa je dete mrtvo, si vstal in ješ kruh?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 22, 'Odgovori: Dokler je dete še živelo, sem se postil in plakal, zakaj menil sem: Kdo ve, mi li ne bode Gospod milosten, da živo ostane dete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 23, 'Ali zdaj, ko je mrtvo, kaj bi se postil? Ga li morem v življenje povrniti? Jaz pač pojdem k njemu, a ono se ne vrne k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 24, 'In ko je David potolažil Batsebo, ženo svojo, je šel k njej in spal ž njo. In rodila je sina, tega je imenoval Salomona. In Gospod ga je ljubil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 25, 'in sporočil je po Natanu proroku, in on mu je dal ime Jedidija zaradi Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 26, 'Joab pa se je bojeval zoper Rabo sinov Amonovih in je zavzel kraljevo mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 27, 'In Joab pošlje sle k Davidu in sporoči: Bojeval sem se zoper Rabo in tudi zavzel Vodno mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 28, 'Sedaj pa zberi ostalo ljudstvo in oblezi mesto ter ga dobodi, da ga jaz ne dobim in se bo imenovalo po meni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 29, 'David torej zbere vse ljudstvo in gre proti Rabi in se bojuje zoper njo ter jo dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 30, 'In vzame krono njih kralja ž njegove glave, in njena teža je bila talent zlata in v njej so bili dragi kameni; in posadili so jo Davidu na glavo. Tudi plena iz mesta je odpeljal silno veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 12, 31, 'Ljudstvo pa, ki je bilo v njem, je odpeljal in jih je postavil k žagam in k železnim strojem in k železnim sekiram ter jim je velel iti v opekarnice. Tako je storil vsem mestom Amonovih sinov. Potem se je vrnil David in vse ljudstvo v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 1, 'Potem se zgodi, da je imel Absalom, sin Davidov, lepo sestro, po imenu Tamara, in Amnon, sin Davidov, se je zaljubil vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 2, 'In Amnon je bil ves zbegan, da je obolel zaradi sestre svoje Tamare, kajti bila je devica, in Amnonu se je zdelo nemogoče, da bi ji kaj storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 3, 'Imel pa je Amnon prijatelja, ki mu je bilo ime Jonadab, sin Simea, brata Davidovega; in Jonadab je bil jako prebrisan človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 4, 'In mu reče: Zakaj, kraljev sin, medliš od dne do dne bolj? Mi li ne moreš povedati? In Amnon mu pove: Ljubim Tamaro, svojega brata Absaloma sestro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 5, 'In Jonadab mu reče: Lezi na posteljo in delaj se bolnega, in ko pride oče tvoj, da te pogleda, mu reci: Prosim, naj pride sestra moja Tamara, da mi da jesti in pripravi jed vpričo mene, da bom videl, in jedel bom iz roke njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 6, 'Amnon torej leže in se naredi bolnega, in ko ga je prišel kralj pogledat, reče Amnon kralju: Prosim, naj pride sestra moja Tamara in mi pripravi dva kolača vpričo mene, da bi jedel iz roke njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 7, 'Tedaj pošlje David domov po Tamaro, veleč: Pojdi, prosim, v brata svojega Amnona hišo in mu pripravi jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 8, 'Tamara torej pride v hišo brata svojega Amnona, on pa je ležal. In ona vzame testo in ga ugnete in naredi kolačev pred njim in jih speče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 9, 'Potem vzame ponev in jih izsuje pred njega, ali on noče jesti. In Amnon veli: Spravite se vsi od mene ven! In ven so šli vsi od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 10, 'In Amnon reče Tamari: Prinesi jed v čumnato, da jem iz tvoje roke. In Tamara vzame kolače, ki jih je pripravila, in jih prinese v čumnato bratu svojemu Amnonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 11, 'In ko mu jih poda, da bi jedel, jo zagrabi in ji reče: Pridi, lezi z menoj, sestra moja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 12, 'Ona mu pa odgovori: Ne, brat moj, nikar me ne sili, ker kaj takega se ne sme storiti v Izraelu. Ne stori te neumnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 13, 'Jaz pa, kam bi se obrnila s sramoto svojo? In ti bi bil kakor eden nespametnežev v Izraelu. Sedaj pa, prosim, govóri s kraljem, ta me ne odreče tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 14, 'Toda on ni hotel poslušati glasu njenega, in jo je premogel in posilil ter ležal pri njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 15, 'Potem pa jo Amnon zasovraži s silno velikim sovraštvom, da je bilo sovraštvo, s katerim jo je sovražil, večje nego ljubezen, s katero jo je ljubil. In Amnon ji veli: Vstani, poberi se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 16, 'Ona pa mu reče: Nikar! to zlo, da me ženeš od sebe, je veliko hujše nego prvo, ki si mi ga storil. Ali on je ni hotel poslušati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 17, 'temuč pokliče dečka svojega, ki mu je stregel, in veli: Izženite to žensko od mene na ulico, in zakleni duri za njo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 18, 'Imela je pa pisano dolgo suknjo na sebi, zakaj tako so se oblačile kraljeve hčere, ki so bile device. Nato jo strežnik njegov odvede ven in zaklene duri za njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 19, 'In Tamara si posuje s pepelom glavo in raztrga dolgo pisano oblačilo, ki ga je imela na sebi, in dene roke na glavo ter gre in gredé vpije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 20, 'In Absalom, njen brat, ji reče: Je li bil Amnon pri tebi, tvoj brat? Sedaj torej molči, sestra moja! Brat tvoj je on; ne žali srca svojega s tem! In Tamara je ostala zapuščena v hiši Absaloma, svojega brata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 21, 'Ko pa je kralj David slišal vse to, se je silno srdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 22, 'In Absalom ni govoril z Amnonom ne dobrega, ne hudega, zakaj sovražil je Amnona, ker je bil posilil sestro njegovo Tamaro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 23, 'In ko sta minili dve leti, so strigli Absalomu ovce v Baal-hazorju, ki je pri Efraimu, in Absalom je povabil vse sinove kraljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 24, 'In Absalom gre h kralju in reče: Glej, hlapec tvoj striže ovce. Prosim, da bi šel kralj in njegovi hlapci s tvojim hlapcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 25, 'Kralj pa reče Absalomu: Nikar, sin moj, ne zahtevaj, naj gremo vsi, da ti ne bomo nadležni. In dasi ga je silil, vendar ni hotel iti; in ga je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 26, 'Tedaj reče Absalom: Če ne, sme li brat moj Amnon iti z nami? In kralj ga vpraša: Čemu bi šel s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 27, 'A ker ga je silil, dovoli Amnonu in vsem sinovom kraljevim iti ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 28, 'Absalom pa zapove hlapcem svojim, rekoč: Pazite! Ko bo srce Amnonovo dobre volje od vina in ko vam povelim: Udarite Amnona! tedaj ga ubijte, ne bojte se; nisem li vam jaz zapovedal? Srčni bodite in hrabri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 29, 'In hlapci Absalomovi so storili Amnonu, kakor jim je bil Absalom zapovedal. Tedaj vstanejo vsi kraljevi sinovi in sedejo vsak na svojega mezga ter zbeže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 30, 'In ko so še bili na poti, pride vest Davidu, da pravijo: Pobil je Absalom vse sinove kraljeve, niti eden iz njih ni ostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 31, 'Tedaj vstane kralj in raztrga oblačila svoja in leže na tla, in vsi hlapci njegovi stoje okoli z raztrganimi oblačili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 32, 'In Jonadab, sin Simea, brata Davidovega, izpregovori ter reče: Gospod moj, ne meni, da so pobili vse mladeniče, kraljeve sinove, zakaj Amnon sam je mrtev; to je namreč bilo na ustih Absalomovih, določeno od dne, ko je Amnon posilil Tamaro, sestro njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 33, 'Zdaj torej naj s tem ne žali gospod moj, kralj, srca svojega, meneč, da so vsi kraljevi sinovi mrtvi, kajti edini Amnon je mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 34, 'Absalom pa je zbežal. In mladenič, ki je bil na straži, povzdigne oči ter vidi, in glej: mnogo ljudstva prihaja po poti ob hribu, vzadaj za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 35, 'In Jonadab reče kralju: Glej, kraljevi sinovi prihajajo! Kakor je rekel hlapec tvoj, tako je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 36, 'In ko izgovori, pridejo kraljevi sinovi in povzdignejo glas svoj in zaplakajo; tudi kralj in vsi hlapci njegovi jokajo zelo bridko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 37, 'Absalom pa je zbežal in šel k Talmaju, sinu Amihurjevemu, kralju v Gesurju. In David je žaloval po svojem sinu vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 38, 'Absalom je torej zbežal in šel v Gesur in je bil ondi tri leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 13, 39, 'In kralj David si je želel iti tja k Absalomu, zakaj utolažil se je bil zaradi Amnona, ker je bil mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 1, 'Joab pa, sin Zervijin, je zaznal, da se je srce kraljevo nagnilo k Absalomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 2, 'In pošlje Joab v Tekoo ter da pripeljati odondod modro ženo in ji veli: Delaj se, prosim, žalujočo in obleci žalno obleko in ne pomaži se z oljem, temuč bodi kakor žena, ki je že dolgo časa žalovala po mrtvem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 3, 'Potem pojdi h kralju ter govóri na ta način ž njim! In Joab jo je poučil, kaj naj govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 4, 'In ko žena iz Tekoe ogovori kralja, pade z obrazom na tla ter stori poklon in reče: Pomagaj mi, o kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 5, 'In kralj jo vpraša: Kaj ti je? In odgovori: Resnično, vdova sem, ker moj mož je mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 6, 'In dekla tvoja je imela dva sinova, in ta sta se med sabo sprla na polju, in ker ga ni bilo, ki bi bil branil, je udaril brat brata in ga ubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 7, 'In glej, vsa rodovina je vstala zoper deklo tvojo in pravijo: Daj sem tistega, ki je ubil brata svojega, da ga usmrtimo za dušo brata, ki ga je umoril, in uničimo tudi dediča! Tako hočejo ugasiti mojo iskro, ki je preostala, da ne ostane možu mojemu ne imena, ne potomca na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 8, 'Kralj pa veli ženi: Pojdi domov, in zapovem zate!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 9, 'A žena iz Tekoe reče kralju: Gospod moj, kralj, na meni bodi ta pregreha in na mojega očeta hiši, kralj pa in prestol njegov bodi nedolžen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 10, 'In kralj reče: Kdorkoli govori kaj zoper tebe, tega pripelji k meni, in ne sme se te več dotekniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 11, 'Ona reče: Naj se kralj spomni, prosim, Gospoda, Boga svojega, da ne napravi krvni maščevalec še več pogube in ne iztrebijo sina mojega. On veli: Kakor res Gospod živi, še las ne pade sinu tvojemu na zemljo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 12, 'Nato reče žena: Pove naj, prosim, dekla tvoja besedo gospodu svojemu, kralju. On veli: Govóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 13, 'In žena reče: Zakaj si kaj takega mislil zoper ljudstvo Božje? Kajti s tem, kar je kralj rekel, se je sam obdolžil, ker noče kralj pripeljati domov izgnanca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 14, 'Zakaj gotovo umremo vsi in smo kakor voda, razlita po zemlji, ki se ne more več zbrati; tudi Bog ne jemlje življenja, ampak snuje načrte, da ne ostane tisti, ki je izgnan, izgnan od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 15, 'Da sem pa prišla govorit to gospodu svojemu, kralju, zgodilo se je, ker me je ljudstvo strašilo; in dekla tvoja je mislila: Govorila bom vsaj s kraljem, morebiti izpolni kralj prošnjo svoje dekle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 16, 'Kajti kralj usliši deklo svojo, da me otme iz roke moža, ki hoče zatreti mene in sina mojega z menoj iz dediščine Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 17, 'Zato si je rekla dekla tvoja: Beseda gospoda mojega, kralja, mi bodi v pomirjenje; zakaj kakor angel Božji je gospod moj, kralj, da razpozna dobro in hudo. In Gospod Bog tvoj bodi s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 18, 'Tedaj odgovori kralj in reče ženi: Ne taji mi, prosim, kar te bom vprašal. In žena reče: Govori naj, prosim, gospod moj, kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 19, 'Kralj pa vpraša: Ni li roka Joabova s teboj v vsem tem? In žena odgovori ter reče: Kakor res živi duša tvoja, gospod moj, kralj, ni ga človeka ne na desnici, ne na levici razen onega, ki ga je imenoval gospod moj, kralj: zakaj hlapec tvoj Joab mi je zapovedal in je položil vse te besede v usta dekle tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 20, 'Da se obrne lice te stvari, je hlapec tvoj Joab storil to; a gospod moj je moder, kakor je modrost angela Božjega, da zna za vse, kar se godi na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 21, 'In kralj veli Joabu: Glej torej, storil sem to reč; zato pojdi in pripelji mladeniča Absaloma nazaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 22, 'In Joab pade z obrazom na tla in stori poklon in blagoslovi kralja in reče: Danes je spoznal hlapec tvoj, da sem našel milost v tvojih očeh, gospod moj, kralj, v tem, da je kralj izpolnil prošnjo hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 23, 'In vstane Joab in odide v Gesur in pripelje Absaloma v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 24, 'Kralj pa veli: Naj krene v hišo svojo, a mojega obličja naj ne vidi! In Absalom je krenil v hišo svojo, a kraljevega obličja ni videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 25, 'V vsem Izraelu pa ga ni bilo moža, ki bi se smel hvaliti zaradi lepote kakor Absalom: od stopala do temena ni bilo hibe na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 26, 'In kadar si je dal striči glavo (to se je zgodilo vsako leto; ker so mu bili lasje pretežki, so jo morali striči), so tehtali lasje njegove glave dvesto seklov, po kraljevi tehtnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 27, 'In Absalomu so se rodili trije sinovi in ena hči, po imenu Tamara: ta je bila žena lepe postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 28, 'In Absalom je prebival v Jeruzalemu dve celi leti in ni videl kraljevega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 29, 'Tedaj pošlje Absalom po Joaba, da bi ga poslal h kralju, a ni hotel priti k njemu; in pošlje še enkrat, a ni hotel priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 30, 'Zatorej reče hlapcem svojim: Glejte, Joabova njiva je poleg moje in raste ječmen na njej: pojdite in jo zažgite. In Absalomovi hlapci so požgali njivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 31, 'Nato vstane Joab in pride na dom k Absalomu ter mu reče: Zakaj so požgali hlapci tvoji mojo njivo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 32, 'In Absalom odgovori Joabu: Glej, poslal sem k tebi, veleč: Pridi sem, da te pošljem h kralju sporočit: Čemu sem prišel iz Gesurja? Bolje bi mi bilo, da bi bil še tam. Zdaj torej poskrbi, da vidim obličje kraljevo; ako je pa krivica na meni, naj me umori!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 14, 33, 'Joab torej stopi h kralju in mu to pove. In ko ga pokliče, pride Absalom h kralju in se mu pokloni z obrazom do tal, in kralj poljubi Absaloma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 1, 'A potem se zgodi, da si oskrbi Absalom voz in konj in petdeset mož, da bi tekali pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 2, 'In Absalom je vstajal zgodaj in postajal pri poti v vrata, in kadar je kdo imel pravdo, ki je imela priti pred kralja v razsodbo, ga je Absalom poklical k sebi in vprašal: Iz katerega mesta si? In odgovori: Hlapec tvoj je iz enega rodov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 3, 'Absalom mu pa reče: Glej, tvoja stvar je dobra in pravična; a ni ga postavljenega od kralja, ki bi te zaslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 4, 'Tudi je Absalom dejal: O da bi me postavili za sodnika v deželi, da pride k meni vsak, kdor ima pravdo ali tožbo, in jaz bi mu poskrbel za pravico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 5, 'In če je kdo pristopil, da mu stori poklon, je iztegnil svojo roko ter ga zadržal in ga poljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 6, 'In na ta način je delal Absalom vsem Izraelcem, ki so prihajali h kralju na sodbo, in tako je kradel zase srca mož Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 7, 'In ko se mu je končalo štirideseto leto, reče Absalom kralju: Prosim, naj grem v Hebron in izvršim obljubo svojo, ki sem jo storil Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 8, 'Hlapec tvoj je namreč storil obljubo, ko je bival v Gesurju v Siriji, rekši: Ako me Gospod res pripelje spet v Jeruzalem, storim službo Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 9, 'In kralj mu veli: Pojdi v miru! Vstane torej in gre v Hebron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 10, 'Poslal pa je bil Absalom oglednike po vseh rodovih Izraelovih s poveljem: Kadar začujete trombe glas, recite: Zakraljeval je Absalom v Hebronu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 11, 'Z Absalomom pa je šlo iz Jeruzalema dvesto mož, ki so bili povabljeni in so šli v nedolžnosti svoji, ne da bi bili kaj vedeli za to reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 12, 'In Absalom pošlje po Ahitofela Gilonskega, svetnika Davidovega, naj pride iz mesta svojega, iz Gila, ko je klal daritve. In zarota se je jačila, ker se je ljudstvo bolj in bolj množilo pri Absalomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 13, 'V tem pride glasnik in sporoči Davidu: Srce mož Izraelovih se je vdalo Absalomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 14, 'In David reče vsem hlapcem svojim, ki so bili pri njem v Jeruzalemu: Vstanite, bežímo! sicer nam ne bo rešitve pred Absalomom. Hitite, da gremo, da nas ne prenagli in dohiti in spravi nesrečo nad nas in udari mesto z ostrino meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 15, 'In kraljevi hlapci mu reko: Glej, hlapci tvoji store, karkoli izvoli gospod moj, kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 16, 'In kralj gre iz mesta in vsa družina njegova za njim; samo deset žen, priležnic, je pustil doma, naj čuvajo hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 17, 'Gre torej kralj iz mesta in vse ljudstvo peš za njim, in ustavijo se pri Skrajni hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 18, 'In vsi hlapci njegovi so šli mimo njega, tudi vsi Keretejci in Peletejci in vsi Gatovci, šeststo mož, ki so bili prišli v spremstvu njegovem iz Gata, so šli pred obličjem kraljevim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 19, 'Tedaj reče kralj Itaju Gatovcu: Čemu greš tudi ti z nami? Vrni se in ostani pri kralju! Zakaj tujec si, pa tudi prognanec; vrni se v svoj kraj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 20, 'Šele včeraj si prišel, in danes že naj bi te pustil hoditi semtertja z nami, ker moram iti kamorkoli. Vrni se in pelji nazaj brate svoje; milost in resnica bodi s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 21, 'A Itaj odgovori kralju in reče: Kakor res Gospod živi in kakor živi gospod moj, kralj, gotovo, kjerkoli bode gospod moj, kralj, najsi gre za smrt ali za življenje, tam bode tudi hlapec tvoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 22, 'In David veli Itaju: Pridi in pojdi naprej! Šel je torej Itaj Gatovec naprej in vsi možje njegovi in vsi otročiči, ki so bili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 23, 'In vsa dežela je jokala z velikim glasom, in vse ljudstvo je šlo čez potok. In kralj preide čez potok Kidron, tudi vse ljudstvo preide, proti potu v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 24, 'In glej, Zadok je tudi prišel in vsi leviti ž njim, nesoč skrinjo zaveze Božje; in postavili so skrinjo Božjo, in Abiatar je šel gori, dokler ni prešlo vse ljudstvo, kar ga je šlo iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 25, 'Kralj pa veli Zadoku: Nesi skrinjo Božjo nazaj v mesto! Ako najdem milost v očeh Gospodovih, me privede nazaj in mi jo zopet da videti in njeno prebivališče;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 26, 'ako mi pa poreče takole: Nisi mi po volji – glej, tu sem, naj stori z mano, kakor se mu vidi prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 27, 'Še reče kralj Zadoku duhovniku: Nisi li videc? Vrni se v mesto v miru in dva sinova tvoja s teboj, Ahimaaz, sin tvoj, in Jonatan, sin Abiatarjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 28, 'Glej, počakam pri brodih ob puščavi, da pride vest od vas in mi sporočite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 29, 'Zadok torej in Abiatar sta zopet odnesla skrinjo Božjo v Jeruzalem, in ostala sta tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 30, 'David pa je šel gori po pobočju Oljske gore in je grede jokal, in glavo je imel pokrito in je šel bos; in vse ljudstvo, ki je bilo pri njem, je šlo gori s pokritimi glavami in je gredoč jokalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 31, 'In nekdo oznani Davidu, rekoč: Ahitofel je med zarotniki z Absalomom. David pa reče: O Gospod, prosim, obrni svet Ahitofelov v neumnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 32, 'In zgodi se, ko dospe David na vrh, kjer so molili Boga, glej, Husaj Arkičan mu pride naproti in suknjo je imel raztrgano in glavo posuto s prstjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 33, 'In David mu reče: Ako pojdeš z menoj, mi bodeš v težavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 34, 'ako se pa povrneš v mesto in porečeš Absalomu: Hlapec tvoj hočem biti, o kralj; kakor sem bil doslej očeta tvojega hlapec, bodem zdaj tvoj hlapec, ovržeš meni v prid svet Ahitofelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 35, 'Ne bodeta li tam s teboj Zadok in Abiatar, duhovnika? Zatorej, karkoli začuješ iz hiše kraljeve, naznani Zadoku in Abiatarju, duhovnikoma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 36, 'Glej, imata ondi pri sebi dva svoja sinova, Ahimaaza Zadokovega in Jonatana Abiatarjevega: po njiju mi sporočite, karkoli boste slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 15, 37, 'Odide torej Husaj, prijatelj Davidov, v mesto. In Absalom je prišel v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 1, 'In ko je David postopil malo dalje od vrha, glej, Ziba, hlapec Mefibosetov, mu pride naproti z dvema osedlanima osloma in na njiju pelje dvesto hlebov kruha in sto gruč suhih grozdov in stotino posušenih sadov in meh vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 2, 'In kralj vpraša Ziba: Kaj hočeš s tem? In Ziba reče: Osla sta za kraljevo družino, da bo na njiju jezdila, kruh pa in sadje za jed mladeničem, in vino, da bodo pili tisti, ki opešajo v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 3, 'In kralj vpraša: Kje pa je tvojega gospodarja sin? In Ziba reče kralju: Glej, ostal je v Jeruzalemu; zakaj dejal je: Danes mi povrne hiša Izraelova mojega očeta kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 4, 'Nato veli kralj Zibu: Glej, vse, kar ima Mefiboset, bodi tvoje! In Ziba reče: Poklanjam se! Da najdem milost v tvojih očeh, gospod moj, kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 5, 'In ko pride kralj David v Bahurim, glej, izide odondod mož iz rodovine hiše Savlove, po imenu Simej, sin Gerov; izide in grede preklinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 6, 'In kamene je lučal na Davida in na vse hlapce kralja Davida; in vse ljudstvo Davidovo in vsi junaki so mu bili ob desnici in ob levici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 7, 'In tako je govoril Simej, ko je preklinjal: Pojdi, pojdi, krvoločnik in mož Belijalov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 8, 'Gospod ti je povrnil vso kri hiše Savlove, na čigar mestu si zakraljeval, in Gospod je dal kraljestvo v roko Absalomu, sinu tvojemu, in glej, tičiš v nesreči svoji, ker si krvoločnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 9, 'Tedaj reče Abisaj, sin Zervijin, kralju: Zakaj bi smel ta mrtvi pes preklinjati gospoda mojega, kralja? Dovoli, da stopim tja in mu odsekam glavo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 10, 'Kralj pa reče: Kaj imam z vama opraviti, sinova Zervijina? Ko preklinja in ko mu je rekel Gospod: Prekolni Davida! kdo pa sme reči: Zakaj tako delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 11, 'še reče David Abisaju in vsem hlapcem svojim: Poglej, sin moj, ki je prišel iz osrčja mojega, mi streže po življenju, koliko bolj ta Benjaminec! Pustite ga, naj kolne; zakaj Gospod mu je velel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 12, 'Morda pogleda Gospod mojo revo in mi poplača Gospod z dobrim za to, da me kolne danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 13, 'Tako je šel David svojim potom z ljudmi svojimi; Simej pa je šel ob strani gore njemu nasproti in je grede preklinjal in lučal kamene na Davida in metal prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 14, 'Ko pa je kralj in ves ljud, ki je bil pri njem, dospel utrujen tja, se je okrepčal ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 15, 'Absalom pa in vse ljudstvo, vsi možje Izraelovi, so bili prišli v Jeruzalem, in Ahitofel ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 16, 'In ko pride Husaj Arkičan, prijatelj Davidov, k Absalomu, reče Absalomu: Živel kralj! Živel kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 17, 'Absalom pa reče Husaju: To li je milost tvoja s prijateljem tvojim? Zakaj nisi šel s prijateljem svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 18, 'Husaj pa odgovori Absalomu: Nikar, temuč kogar je izvolil Gospod in to ljudstvo in vsi možje Izraelovi, njegov bodem in pri njem ostanem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 19, 'In drugič, komu naj bi služil? Ne li pred obličjem sinu njegovega? Kakor sem bil sluga pred očetom tvojim, tako bodem pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 20, 'In Absalom veli Ahitofelu: Svetuj, kaj nam je storiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 21, 'Ahitofel reče Absalomu: Pojdi k priležnicam očeta svojega, ki jih je pustil, da čuvajo hišo; tako bo ves Izrael slišal, da si se omrzil očetu svojemu, in bodo roke vseh, ki so pri tebi, tem močnejše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 22, 'Nato razpno Absalomu šator na strehi, in Absalom je šel k priležnicam očeta svojega pred očmi vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 16, 23, 'Svet Ahitofelov pa, ki ga je dajal v tistem času, je bil, kakor da bi kdo vprašal besedo Božjo: tako se je štelo vse svetovanje Ahitofelovo i pri Davidu i pri Absalomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 1, 'Dalje reče Ahitofel Absalomu: Dovoli, da si izberem dvanajst tisoč mož in vstanem ter hitim za Davidom še nocoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 2, 'In planem nanj, dokler je truden in slab, ter ga prestrašim; in ko vse ljudstvo, ki je pri njem, zbeži, udarim kralja samega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 3, 'vse ljudstvo pa pripeljem nazaj k tebi. Ko pogine mož, ki ga iščeš, se vsi povrnejo k tebi, in pride vsemu ljudstvu mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 4, 'To se je zdelo dobro Absalomu in vsem starejšinam Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 5, 'Tedaj reče Absalom: Pokliči, prosim, še Husaja Arkičana, in zaslišimo, kaj on pravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 6, 'Ko pride Husaj k Absalomu, mu pove Absalom, rekoč: Tako in tako je svetoval Ahitofel. Ali naj storimo po besedah njegovih? Ako ne, govóri ti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 7, 'In Husaj reče Absalomu: Ni dober svet, ki ga je dal Ahitofel takrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 8, 'Še reče Husaj: Poznaš očeta svojega in ljudi njegove, da so junaki in srdite narave kakor medvedka na polju, ko so ji mladiče vzeli; oče tvoj je tudi vojščak in ne bo nočeval pri ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 9, 'Glej, lahko se je skril v kako jamo ali kam drugam; in ako se zgodi, da padejo nekateri iz njih kar s početka, kdorkoli zasliši, poreče: Poboj je bil med ljudstvom, ki je šlo za Absalomom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 10, 'Tako pa upade srce vsakomur, tudi če je kdo sicer hraber in ima srce kakor lev; zakaj ves Izrael ve, da je junak oče tvoj in tisti, ki so pri njem, da so vrli vojščaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 11, 'Ali jaz svetujem, da spraviš k sebi vsega Izraela od Dana do Bersebe, ki ga je po množini kakor peska ob morju, in ti sam pojdi v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 12, 'In tako ga naskočimo v kakem kraju, kjer ga zalotimo, in ga zalezemo, kakor rosa pade na zemljo, da ne preostane od njega in od vseh njegovih niti eden mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 13, 'Ako pa bi se umaknil v kako mesto, naj ves Izrael potegne vrvi okrog tistega mesta in ga povlečemo v potok, da se ne najde ne kamenček od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 14, 'Tedaj reko Absalom in vsi možje Izraelovi: Svet Husaja Arkičana je boljši nego svet Ahitofelov. Zakaj Gospod je tako obrnil, da je bil ovržen dobri svet Ahitofelov, zato, da spravi Gospod nesrečo nad Absaloma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 15, 'Husaj pa reče Zadoku in Abiatarju, duhovnikoma: Tako in tako je svetoval Ahitofel Absalomu in starejšinam Izraelovim, in takole sem svetoval jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 16, 'Zatorej pošljita hitro k Davidu in mu sporočita: Ne ostani to noč pri brodih ob puščavi, temuč vsekakor pojdi na ono stran, da ne bo požrt kralj z ljudstvom, ki je pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 17, 'Jonatan pa in Ahimaaz sta stala pri studencu Rogelu, in dekla je hodila in jima poročala; zakaj nista se smela prikazati, da hodita v mesto. In šla sta ter oznanila kralju Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 18, 'A neki deček ju zagleda in pove Absalomu; odideta torej hitro in stopita v hišo nekega moža v Bahurimu, ki je imel vodnjak na dvorišču; in spustita se vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 19, 'In žena vzame odejo in jo razgrne čez vodnjakovo odprtino in jo posuje z raztolčenim žitom, da se nič ne spozna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 20, 'Ko pa pridejo Absalomovi hlapci k ženi v hišo in vprašajo: Kje sta Ahimaaz in Jonatan? odgovori žena: Šla sta čez potoček! In ju iščejo; ko pa ju ne morejo najti, se vrnejo v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 21, 'In ko so odšli, stopita onadva gori iz vodnjaka ter gresta in naznanita kralju Davidu in mu rečeta: Vstanite, hitro pojdite čez vodo; kajti tako je svetoval zoper vas Ahitofel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 22, 'Tedaj vstane David in vse ljudstvo, ki je bilo pri njem, in prebredejo Jordan. Ko se je zjutraj svitalo, niso pogrešili ne enega, ki bi ne bil prišel čez Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 23, 'Ko pa je videl Ahitofel, da ne delajo, kakor je bil svetoval, osedla osla ter vstane in odide domov v mesto svoje in uredi hišo svojo ter se obesi, in je umrl in je bil pokopan v grobu očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 24, 'David pa je dospel v Mahanaim. In Absalom je šel čez Jordan, on in vsi možje Izraelovi ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 25, 'In Absalom je postavil Amasa nad vojsko namesto Joaba. Bil pa je Amasa sin moža, čigar ime je bilo Jitra Izraelit, ki je bil šel k Abigaili, hčeri Nahasovi, sestri Zervije, matere Joabove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 26, 'Izrael z Absalomom pa se je utaboril v Gileadski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 27, 'In ko je David prišel v Mahanaim, so prinesli Sobi, sin Nahasov iz Rabe sinov Amonovih, in Mahir, sin Amielov iz Lodebarja, in Barzilaj Gileadčan iz Rogelima');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 28, 'postelje, medenice, lončene posode, pšenice, ječmena, moke, opraženega zrnja, boba, leče, praže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 17, 29, 'medu, masla, ovac in sira za živež Davidu in ljudstvu, ki je bilo pri njem; zakaj dejali so: Ljudstvo je lačno, trudno in žejno v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 1, 'David pa sešteje ljudstvo, ki je bilo pri njem, in mu postavi poveljnike nad tisoč in poveljnike nad sto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 2, 'In David odpošlje ljudstvo, tretjino pod roko Joabovo, tretjino pod roko Abisaja, sina Zervije, brata Joabovega, in tretjino pod roko Itaja Gatovca. In kralj reče ljudstvu: Tudi jaz pojdem vsekakor z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 3, 'A ljudstvo reče: Ne pojdeš! Zakaj če pobegnemo, jim ne bode mar za nas; tudi če nas polovica pogine, ne bodo marali za nas; temuč ti si kakor nas deset tisoč. Zatorej je bolje, da boš pripravljen priskočiti nam v pomoč iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 4, 'Kralj jim reče: Kar se vam zdi najboljše, storim. In kralj se ustopi pri vratih, in vse ljudstvo gre ven po sto in po tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 5, 'In kralj zapove Joabu in Abisaju in Itaju, rekoč: Milo mi ravnajte z mladeničem, z Absalomom! In vse ljudstvo je slišalo, ko je kralj zapovedoval vsem poveljnikom za Absaloma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 6, 'Šlo je torej ljudstvo na polje v boj proti Izraelu, in bitka se je začela v Efraimskem gozdu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 7, 'In ljudstvo Izraelovo je bilo ondi poraženo pred hlapci Davidovimi, in bil je tam velik poboj tisti dan, ker je padlo dvajset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 8, 'Zakaj boj se je ondi razširil po vsej deželi, in gozd je požrl več ljudstva tisti dan, nego jih je pobil meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 9, 'Primeri se pa, da sreča Absalom hlapce Davidove. In Absalom je jezdil na mezgu svojem, in mezg je prišel pod debele veje košatega hrasta, in Absalomu je obtičala glava na hrastu, da je visel med nebom in zemljo, kajti mezg je izpod njega zdirjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 10, 'In neki mož vidi to in oznani Joabu in reče: Glej, videl sem Absaloma, da visi na hrastu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 11, 'Joab pa veli možu, ki mu je povedal: Glej, ako si ga videl, zakaj ga nisi ondi pobil na zemljo? In jaz bi ti bil dal deset srebrnikov in pas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 12, 'Mož pa odvrne Joabu: Da si mi odštel tisoč srebrnikov na roko, ne bi bil hotel iztegniti roke zoper sina kraljevega; zakaj kralj je pred našimi ušesi zapovedal tebi in Abisaju in Itaju, rekoč: Pazite, da se nihče ne dotakne mladeniča Absaloma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 13, 'Sicer pa, ako bi bil storil kaj žalega zoper življenje njegovo (kajti nič ne ostane kralju skrito), ti sam bi stal zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 14, 'Nato reče Joab: Ne bom tu časa tratil s teboj! In vzame tri sulice v roko in jih zasadi Absalomu v srce, ko je še živel viseč na hrastu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 15, 'In deset mladeničev, oprod Joabovih, stopi okoli Absaloma in ga bijejo in umore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 16, 'In Joab zatrobi v trobento, in ljudstvo se vrne, da ne podi več Izraela; zakaj Joab je zadržal ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 17, 'In vzamejo Absaloma ter ga vržejo v veliko jamo v gozdu in nanosijo nanj velik kup kamenja. In ves Izrael je bežal, vsak v šator svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 18, 'Absalom pa si je bil še za življenja svojega oskrbel in postavil spomenik, ki je v Kraljevi dolini; zakaj dejal je: Nimam sina, da se ohrani imena mojega spomin! In imenoval je tisti spomenik z imenom svojim, in imenuje se Absalomov spomenik do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 19, 'Ahimaaz pa, sin Zadokov, reče: Dovoli, da tečem in sporočim kralju, da mu je Gospod storil pravico in ga otel iz roke njegovih sovražnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 20, 'A Joab mu veli: Danes nisi poročevalec dobrega! Drugi dan lahko sporočiš blago vest, a danes nimaš kaj dobrega oznaniti, ker je kraljev sin mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 21, 'Potem veli Joab Kušitu: Pojdi, povej kralju, kar si videl! In Kušit se prikloni Joabu in teče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 22, 'Tedaj reče Ahimaaz, sin Zadokov, zopet Joabu: Bodisi kakorkoli, dovoli, da tečem tudi jaz za Kušitom! Joab pa reče: Čemu hočeš tja teči, sin moj! Saj nimaš poročila, ki bi zanje dobil pohvalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 23, 'On reče: Bodisi kakorkoli, potečem! In mu veli: Teci! In teče Ahimaaz po ravnini in prehiti Kušita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 24, 'David pa je sedel med dvojimi vrati. In stražar stopi na streho od vrat, na obzidju, povzdigne oči in gleda; in glej, mož teče sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 25, 'In stražar zakliče in oznani kralju. Kralj pa reče: Ako je sam, je dobro oznanilo v njegovih ustih. Ko pa ta prihaja bliže in bliže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 26, 'zagleda stražar drugega moža tekočega, in zakliče vratarju in reče: Glej, mož teče sam! Kralj pa veli: Tudi ta ima dobro oznanilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 27, 'In stražar reče: Zdi se mi, da tek prvega je kakor tek Ahimaaza, sina Zadokovega. In kralj veli: Dober mož je in prihaja z dobrim poročilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 28, 'In Ahimaaz zakliče in reče kralju: Mir! Potem se pokloni pred kraljem z obrazom do tal in pravi: Hvaljen bodi Gospod, Bog tvoj, ki nam je izdal može, ki so vzdignili roko svojo zoper gospoda mojega, kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 29, 'In kralj vpraša: Je li dobro mladeniču Absalomu? Ahimaaz pa odgovori: Ko je Joab pošiljal kraljevega hlapca, mene, hlapca tvojega, sem videl velik hrup, pa ne vem, kaj je bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 30, 'Kralj veli: Stopi strani in stoj tu! In stopi tja in obstoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 31, 'Glej, v tem pride Kušit in reče: Vesela vest gospodu mojemu kralju! Zakaj Gospod ti je danes pravico storil in te otel iz roke vseh, ki so se vzdignili zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 32, 'Kralj pa vpraša Kušita: Je li dobro z mladeničem Absalomom? In Kušit odvrne: Zgodi se naj kakor temu mladeniču sovražnikom gospoda mojega kralja in vsem, ki se vzdigujejo zoper tebe, da ti store hudo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 18, 33, 'In kralju se zelo užali in stopi v hram nad vrati in joče; in grede govori: O sin moj Absalom, sin moj, sin moj Absalom! Ah, da bi bil jaz umrl zate! O Absalom, sin moj, sin moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 1, 'In oznanili so Joabu: Glej, kralj joče in žaluje po Absalomu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 2, 'In zmaga se je tisti dan obrnila v žalost vsemu ljudstvu, zakaj ljudstvo je slišalo ta dan, da se je pravilo: Kralju je žal za svojega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 3, 'In ljudstvo se po tihem prikrade v mesto ta dan, kakor se ljudstvo s sramom ukrade, ko je bežalo v boju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 4, 'Kralj pa si je zagrnil obraz in vpil z velikim glasom: O sin moj Absalom! Absalom, moj sin, moj sin!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 5, 'In pride Joab v hišo h kralju in reče: Rdečico si danes pognal v obraze vseh hlapcev svojih, ki so ta dan rešili življenje tvoje in tvojih sinov in hčera, življenje tvojih žen in priležnic,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 6, 's tem, da ljubiš tiste, ki te sovražijo, in mrziš te, ki te ljubijo. Zakaj pokazal si danes, da ne maraš za svoje kneze in hlapce; kajti danes vidim, ako bi le Absalom bil ostal živ, mi vsi pa bi bili pomrli danes, tebi bi bilo prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 7, 'Sedaj pa vstani, pojdi ven in govori prijazno hlapcem svojim! Zakaj prisegam pri Gospodu: Ako ne pojdeš ven, ne ostane nocoj ne eden mož pri tebi, in to bo hujše zate nego vse hudo, ki te je zadelo od mladosti tvoje do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 8, 'Tedaj vstane kralj in sede med vrata. In oznanijo vsemu ljudstvu, rekoč: Glej, kralj sedi med vrati. In vse ljudstvo je prišlo pred kralja. Izrael pa je bil bežal, vsak v šator svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 9, 'In vse ljudstvo se je prepiralo po vseh rodovih Izraelovih, govoreč: Kralj nas je otel iz roke sovražnikov naših ter nas je oprostil pesti Filistejcev, in zdaj je moral bežati iz dežele pred Absalomom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 10, 'Absalom pa, ki smo ga pomazilili, da bodi nad nami, je mrtev na bojišču. Sedaj pa, zakaj ne izpregovorite besede, da pripeljemo kralja nazaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 11, 'In kralj David pošlje k Zadoku in Abiatarju, duhovnikoma, veleč: Govorita starejšinam Judovim in recita: Zakaj hočete biti poslednji, da bi pripeljali kralja nazaj v hišo njegovo! Kaj ti govor vsega Izraela se je donesel kralju, da ga hočejo privesti v hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 12, 'Bratje moji ste, moja kost in meso, čemu bi torej bili poslednji, ko bodo peljali kralja nazaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 13, 'In Amasu recita: Nisi li moja kost in meso? Bog mi stori to in še to prideni, ako ne boš vse svoje žive dni poveljnik vojske pred menoj na Joabovem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 14, 'In nagnil je vseh Judovih mož srce, kakor srce enega moža, da so sporočili kralju: Vrni se ti in vsi hlapci tvoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 15, 'Vrne se torej kralj in pride k Jordanu. In Judovci dospejo v Gilgal, gredoč naproti kralju, da ga prepeljejo čez Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 16, 'In Simej, sin Gerov, Benjaminec, ki je prebival v Bahurimu, pohiti in pride doli z možmi Judovimi naproti kralju Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 17, 'In bilo je ž njim tisoč mož iz Benjamina in Ziba, Savlove hiše služabnik, in petnajst sinov njegovih in dvajset hlapcev njegovih, in šli so čez Jordan pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 18, 'Napravili so namreč brod, da prepeljejo kraljevo družino in store, kar mu je ugajalo. Simej pa, sin Gerov, pade pred kralja, ko se je hotel peljati čez Jordan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 19, 'in reče kralju: Ne prištevaj mi, gospod moj, krivice, in ne spominjaj se, kako se je pregrešil hlapec tvoj tisti dan, ko je bil šel gospod moj, kralj, iz Jeruzalema, in naj ne ohrani tega kralj v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 20, 'Zakaj hlapec tvoj spoznava, da sem grešil; in poglej, jaz sem danes prvi šel od vse hiše Jožefove, da pridem doli naproti gospodu svojemu, kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 21, 'Abisaj pa, Zervijin sin, odgovori in reče: Ne bo li Simej usmrčen zato, ker je preklinjal maziljenca Gospodovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 22, 'A David veli: Kaj imam z vama opraviti, sinova Zervije, da mi danes hočeta biti nasprotnika? Ali naj danes umre kdo v Izraelu? Ne vem li namreč, da sem danes zopet kralj nad Izraelom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 23, 'In Simeju reče kralj: Ne umreš. In kralj mu je prisegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 24, 'Mefiboset, Savlov sin, je tudi prišel doli kralju naproti. Ni si pa snažil nog, ne ravnal brade, ne pral obleke od dne, ko je bil kralj odšel, do dne, ko se je vrnil domov v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 25, 'In zgodi se, ko pride v Jeruzalem kralju naproti, da ga kralj vpraša: Zakaj nisi šel z menoj, Mefiboset?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 26, 'On pa odgovori: O gospod moj, kralj, hlapec moj me je okanil! Zakaj hlapec tvoj je dejal: Osedlam si osla, da bom jezdil na njem in šel h kralju, ker hlapec tvoj je hrom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 27, 'A on je še ovadil hlapca tvojega pred gospodom mojim, kraljem. Ali gospod moj, kralj, je kakor angel Božji! Stóri torej, kar se ti dobro vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 28, 'Zakaj očeta mojega vsa družina ni bila nič drugega kakor ljudje, smrti izročeni pred gospodom mojim, kraljem; a vendar si posadil hlapca svojega med tiste, ki jedo pri mizi tvoji. Kaj imam torej še pravice, da bi dalje vpil h kralju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 29, 'In kralj mu veli: Kaj toliko govoriš o svojih rečeh? Rekel sem: Ti in Ziba si vkup delita tiste njive!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 30, 'In Mefiboset reče kralju: Lahko si tudi vse vzame, samo da se je gospod moj, kralj, vrnil v miru v hišo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 31, 'In Barzilaj Gileadčan je prišel doli iz Rogelima in je šel s kraljem čez Jordan, da bi ga spremil čez Jordan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 32, 'Barzilaj pa je bil silno star, dobrih osemdeset let, in je oskrboval kralja z živežem, dokler je bival v Mahanaimu, kajti bil je jako bogat mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 33, 'In kralj veli Barzilaju: Pojdi z menoj na ono stran in hočem te oskrbeti pri sebi v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 34, 'Barzilaj pa reče kralju: Koliko je še dni življenja mojega, da bi šel s kraljem gori v Jeruzalem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 35, 'Osemdeset let sem sedaj star: morem li razločevati med dobrim in hudim? More li hlapcu tvojemu tekniti, kar bo jedel in kar bo pil? Morem li še poslušati glas pevcev in pevk? Čemu naj torej bode hlapec tvoj še v nadlego gospodu svojemu, kralju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 36, 'Hlapec tvoj je samo hotel malo spremiti kralja čez Jordan, in zakaj bi mi kralj podelil tako povračilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 37, 'Naj se sme, prosim, vrniti hlapec tvoj, da umrjem v mestu svojem, pri grobu očeta svojega in matere svoje. A glej, tu je hlapec tvoj Kimham, ta naj gre na ono stran z mojim gospodom kraljem, in njemu stóri, kar se ti vidi prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 38, 'In kralj odgovori: Kimham naj torej gre z menoj, in storiti mu hočem, kar je dobro v tvojih očeh; tudi vse, česar boš želel od mene, storim zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 39, 'In ko je prešlo vse ljudstvo čez Jordan in je tudi kralj bil na oni strani, poljubi kralj Barzilaja in ga blagoslovi. On pa se vrne v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 40, 'Kralj pa je šel čez v Gilgal in Kimham je šel ž njim; in vse ljudstvo Judovo je spremljalo kralja na ono stran, tudi polovica ljudstva Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 41, 'In glej, vsi možje Izraelovi pridejo h kralju in mu reko: Zakaj so te ukradli bratje naši, možje Judovi, in so prepeljali kralja in družino njegovo čez Jordan in vse može Davidove ž njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 42, 'A vsi možje Judovi odgovore možem Izraelovim: Kralj je nam bliže! Zakaj se srdite zato? Ali smo dobili kaj kraljeve hrane ali kako darilo od njega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 19, 43, 'Možje Izraelovi pa odgovore možem Judovim in reko: Mi imamo desetkrat več pri kralju, in tudi Davidu smo več nego vi, zakaj ste nas torej zaničevali? In nismo li mi prvi govorili, da privedemo nazaj kralja svojega? Ali besede mož Judovih so bile trše nego mož Izraelovih besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 1, 'In prigodi se, da je bil ondi mož Belijalov, po imenu Seba, sin Bikrijev, Benjaminec; ta zatrobi v trobento in reče: Ni nam deleža pri Davidu, ne dediščine pri sinu Jesejevem. Vsak v šator svoj, o Izrael!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 2, 'Tedaj se vsi možje Izraelovi vzdignejo, da ne bi šli za Davidom, ter odidejo za Sebom, Bikrijevim sinom; ali možje Judovi so se držali kralja svojega od Jordana do Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 3, 'In David pride v hišo svojo v Jeruzalemu. In vzame kralj tistih deset žen priležnic, ki jih je bil popustil, da čuvajo hišo, in jih da v varstvo, ter jih je oskrboval z živežem, a ni hodil k njim. Tako so bile zaprte do dne smrti svoje, živeč v vdovstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 4, 'Nato veli kralj Amasu: Skliči mi može Judove na tretji dan, tudi sam pridi sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 5, 'In Amasa odide sklicat Judovce, a se zamudi, da ni prišel ob določenem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 6, 'Tedaj reče David Abisaju: Sedaj nam bo Seba, sin Bikrijev, več škodoval nego Absalom. Vzemi gospoda svojega hlapce in híti za njim, da si ne pridobi utrjenih mest ter nam uskoči izpred oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 7, 'šli so torej za njim možje Joabovi in Keretejci in Peletejci in vsi junaki; šli so iz Jeruzalema, da zasledujejo Seba, sina Bikrijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 8, 'Ko so bili pri tistem velikem kamenu, ki je v Gibeonu, jim pride Amasa naproti. Joab pa je bil oblečen v vojaško suknjo in čeznjo prepasan s pasom in na njem je visel meč v nožnici ob bedru njegovem, in ko je postopil, se je meč iztaknil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 9, 'In Joab reče Amasu: Se ti li dobro godi, brat moj? In Joab prime z desnico Amasa za brado, da ga poljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 10, 'Amasa pa ni opazil meča, ki je bil v roki Joabovi, in on ga je ž njim pobodel pod rebra, da so se mu čreva izsula na zemljo, in ni ga pobodel v drugič; in je umrl. A Joab in Abisaj, brat njegov, sta se gnala za Sebom, sinom Bikrijevim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 11, 'In eden iz Joabovih hlapcev stopi poleg Amasa in reče: Kdor ljubi Joaba in kdor je za Davida, naj gre za Joabom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 12, 'Amasa pa se je valjal v krvi svoji sredi ceste. In ko je videl mož, da se ustavlja vse ljudstvo, odnese Amasa s ceste na polje ter vrže nanj oblačilo, videč, da se ustavi, kdorkoli gre mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 13, 'Ko je torej bil odpravljen s ceste, je šlo vse ljudstvo naprej za Joabom, da pode Seba, sina Bikrijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 14, 'Ta pa je bil šel skozi vse rodove Izraelove do Abela in Betmaaka in skozi ves kraj Berimcev; in zbrali so se in šli tudi za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 15, 'Oni pa so prišli ter ga oblegli v Abel-Betmaaki in so napravili nasip okoli mesta, da je stal proti zidovju; in vse ljudstvo, ki je bilo z Joabom, je podkopalo zid, da bi ga podrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 16, 'Tedaj zakliče modra žena iz mesta: Čujte, čujte! Recite Joabu: Pristopi sem, da govorim s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 17, 'In on se ji približa. Žena pa vpraša: Si li ti Joab? Odgovori: Sem. Tedaj mu reče: Čuj besede dekle svoje! On reče: Poslušam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 18, 'Tedaj govori ona, rekoč: V starih časih so rekali: Povprašajte za svet v Abelu! In s tem so končali vsako stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 19, 'Jaz sem eno iz miroljubnih in zvestih mest v Izraelu, in ti hočeš ugonobiti mesto in mater v Izraelu? Zakaj hočeš požreti dediščino Gospodovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 20, 'In Joab odgovori in reče: Nikakor ne, nikakor ne, da bi jaz požiral ali razdeval!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 21, 'Stvar ni taka, ampak mož z Efraimskega gorovja, Seba, sin Bikrijev, po imenu, je vzdignil roko svojo zoper kralja, zoper Davida. Izročite njega samega, in odidem od mesta. In žena reče Joabu: Glej, glava njegova se ti bo vrgla čez zid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 22, 'Nato gre žena in govori vsemu ljudstvu v modrosti svoji. In odsekajo glavo Sebu, sinu Bikrijevemu, in jo vržejo ven Joabu. In zatrobi na trobento, in razidejo se od mesta, vsak v mesto svoje. Joab pa se vrne v Jeruzalem h kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 23, 'Bil pa je Joab nad vso vojsko Izraelovo, in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 24, 'in Adoram je bil nad robotniki, in Josafat, sin Ahiludov, je bil deželni letopisec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 25, 'in Seva je bil pisar, Zadok in Abiatar pa sta bila duhovnika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 20, 26, 'tudi Ira Jairski je bil prvi dvornik Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 1, 'In bila je lakota tri leta v dnevih Davidovih, leto za letom; in David je iskal obličja Gospodovega. In Gospod je dejal: Zaradi Savla je to in zaradi krvi, prelite od hiše njegove, ker je pomoril Gibeončane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 2, 'In kralj pokliče Gibeončane in govori ž njimi. (Gibeončani pa niso bili izmed sinov Izraelovih, ampak iz ostanka Amorejcev, in sinovi Izraelovi so jim prisegli mir. Toda Savel jih je poskušal iztrebiti v svoji gorečnosti za sinove Izraelove in Judove.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 3, 'In David reče Gibeončanom: Kaj naj storim za vas? In s čim naj storim poravnavo, da boste blagoslovili dediščino Gospodovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 4, 'In Gibeončani mu reko: Ni nam za srebro ali za zlato v zadevi med nami in med Savlom in hišo njegovo, niti za to, da se kdo umori v Izraelu. In jim reče: Kar porečete, storim za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 5, 'In reko kralju: Tistega moža, ki nas je pokončeval in ki je izmišljal zoper nas, da bi bili potrebljeni, da nas ne bo v nobenem kraju Izraelovem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 6, 'naj se nam da sedem iz sinov njegovih, in obesimo jih Gospodu v Gibei Savlovi, v mestu izvoljenca Gospodovega. In kralj reče: Dam vam jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 7, 'Ali kralj je prizanesel Mefibosetu, sinu Jonatana, sina Savlovega, zaradi prisege Gospodove, ki je bila med njima, med Davidom in Jonatanom, sinom Savlovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 8, 'Vzame pa kralj dva sinova Ricpe, hčere Ajeve, ki ju je rodila Savlu, Armonija in Mefiboseta, in pet sinov Mihale, hčere Savlove, ki jih je rodila Adrielu, sinu Barzilaja Meholačana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 9, 'in jih da Gibeončanom v roke, in obesijo jih na gori pred Gospodom, in poginilo je teh sedem skupaj; in bili so usmrčeni ob žetvi, v prvih dneh, ko se je začela ječmenova žetev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 10, 'A Ricpa, hči Ajeva, vzame raševnik in si ga razgrne na skali, od začetka žetve dotlej, ko je voda kapljala z neba na obešence, in ni dopustila ptičem nebeškim, da sedejo nanje po dne, ne zverinam poljskim po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 11, 'In povedali so Davidu, kaj je storila Ricpa, hči Ajeva, priležnica Savlova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 12, 'In David odide in vzame kosti Savlove in kosti Jonatana, sinu njegovega, od meščanov v Jabesu v Gileadu, ki so jih bili ukradli z ulic v Betsanu, kjer so ju Filistejci obesili v dan, ko so umorili Savla na Gilboi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 13, 'in prinese odondod kosti Savlove in kosti Jonatana, sina njegovega. Zbrali so tudi kosti tistih, ki so bili obešeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 14, 'In pokopali so kosti Savlove in Jonatana, sina njegovega, v pokrajini Benjaminovi v Zeli, v grobu Kisa, očeta njegovega, in storili so vse, kar je kralj zapovedal. In potem se je dal Bog izprositi za deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 15, 'In Filistejci so zopet začeli vojno z Izraelom. In David gre doli in služabniki njegovi ž njim in se bojujejo zoper Filistejce. In David je bil utrujen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 16, 'in Isbibenob, ki je bil iz sinov velikana, čigar sulica je tehtala tristo seklov brona, in je bil opasan z novim mečem, je nameraval ubiti Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 17, 'Ali Abisaj, sin Zervijin, mu je prišel v pomoč in je udaril Filistejca ter ga ubil. Tedaj so prisegli Davidu možje njegovi, rekoč: Nikdar več ne pojdeš z nami v boj, da ne ugasneš svetila Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 18, 'In zgodi se potem, da je bila zopet vojna s Filistejci v Gobu; tedaj je Sibekaj Husajec ubil Safa, ki je bil iz sinov velikanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 19, 'In zopet je bila vojna s Filistejci v Gobu, in Elhanan, sin Jaare-orgimov, Betlehemčan, je ubil brata Goliata Gatovca, čigar suličišče je bilo kakor tkalsko vratilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 20, 'In zopet je bila vojna v Gatu, kjer je bil mož velike postave, ki je imel na vsaki roki šest in na vsaki nogi šest prstov, štiriindvajset po številu; tudi ta se je bil rodil velikanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 21, 'Ko pa je ta sramoto kidal na Izraela, ga je ubil Jonatan, sin Simeja, brata Davidovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 21, 22, 'Ti štirje so se rodili velikanu v Gatu, in padli so po roki Davidovi in po roki služabnikov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 1, 'In David je govoril Gospodu besede te pesmi v dan, ko ga je Gospod otel iz roke vseh sovražnikov njegovih in iz roke Savlove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 2, 'in dejal je: Gospod je skala moja in visok grad moj in rešitelj moj, prav moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 3, 'Bog skale moje, v njem mi bode zavetje, ščit moj in rešenja mojega rog, visoka trdnjava moja in moje pribežališče. Moj rešitelj, ti me rešuješ nasilstva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 4, 'Hvale vrednega Gospoda bom klical in tako se rešim sovražnikov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 5, 'Kajti valovi smrti so me zagrnili, hudourniki Belijalovi so me prestrašili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 6, 'Peklenske vezi so me opele, smrtne zanke so me zajele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 7, 'V stiski svoji sem klical Gospoda, da, klical sem k Bogu svojemu, in začul je glas moj iz svetišča svojega in vpitje moje je prišlo do ušes njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 8, 'Tu se je zgenila in stresla zemlja, podstave nebes so se gibale in majale, ker se je srdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 9, 'Dim se je valil iz nosnic njegovih, in ogenj iz ust njegovih je požiral, žerjavica je prhala od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 10, 'Nagnil je nebo ter stopil doli, in oblačna temota mu je bila pod nogami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 11, 'In sedeč na kerubu, je letel, in videti ga je bilo na vetra perotih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 12, 'In temo si je napravil za šatore okoli sebe, grmade vodá, roje oblakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 13, 'Od svita pred njim se je vnela žerjavica ognjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 14, 'Na nebesih je grmel Gospod, in Najvišji je dal slišati svoj glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 15, 'In izstrelil je pšice ter sovražnike razkropil, strelo, in jih je zbegal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 16, 'Tedaj so se prikazale struge morja, podstave zemlje so se odgrnile po svarilu Gospodovem, od sape jeze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 17, 'Iz višine je posegel in me prijel, potegnil me je iz mnogih vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 18, 'Rešil me je močnega neprijatelja mojega, sovražilcev mojih, ker so mi bili premočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 19, 'Naskočili so me ob dnevu nesreče moje, a Gospod mi je bil podpora');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 20, 'in me je izpeljal na plano, rešil me je, ker me je ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 21, 'Podelil mi je Gospod po pravičnosti moji, po čistosti mojih rok mi je povrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 22, 'Kajti držal sem se poti Gospodovih ter se nisem zlobno odvrnil od Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 23, 'Zakaj vse sodbe njegove so bile pred mojimi očmi, in od postav njegovih nisem odstopil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 24, 'In popolnoma sem mu bil vdan ter sem se varoval, da ne ravnam krivično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 25, 'In povrnil mi je Gospod po pravičnosti moji, po čistosti moji pred njegovimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 26, 'Milosrčnemu se izkazuješ milosrčnega, popolnoma vdanemu se izkazuješ popolnega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 27, 'kdor je čist, njemu se kažeš čistega, a popačenemu nasprotnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 28, 'In ljudstvo ubogo otimlješ, proti prevzetnim pa so tvoje oči, da jih ponižaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 29, 'Kajti ti si svetilnica moja, o Gospod! Gospod razjasnjuje tmine moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 30, 'Kajti s teboj prodiram skozi krdelo, z Bogom svojim preskakujem zid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 31, 'Tega Boga mogočnega pot je brezmadežna; govor Gospodov je prečiščen; ščit je vsem, ki pribegajo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 32, 'Kajti kdo je Bog mogočni razen Gospoda? in kdo skala razen našega Boga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 33, 'Bog mogočni je močna trdnjava moja in vodi v popolnosti mojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 34, 'Stori noge moje enake jelenjim in me stavi na višine moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 35, 'Vadi za boj roke moje, da napnem z ramo svojo lok bronasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 36, 'Dal si mi tudi zveličanja svojega ščit, in ljubeznivost tvoja me je poveličala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 37, 'Razširil si prostor korakom mojim pod mano, in členki mojih nog niso omagovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 38, 'Zasledoval sem sovražnike svoje in jih zatiral, in nisem se vrnil, dokler niso bili pokončani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 39, 'Pokončal sem jih in zdrobil, da ne morejo vstati, da, padli so mi pod noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 40, 'Ker ti si me opasal z močjo za boj, upognil si podme nje, ki so se vzpenjali zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 41, 'In zapodil si v beg sovražnike moje, da jih ugonobim, ki me sovražijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 42, 'Ozirali so se, a ni ga bilo, ki bi jih rešil – h Gospodu, a ni jih uslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 43, 'Tedaj sem jih strl kakor prah zemlje, pogazil in razteptal sem jih kakor blato na ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 44, 'Ti si me tudi otel iz prepirov ljudstva mojega in si me ohranil, da bodem narodom za glavo; ljudstvo, ki ga nisem poznal, mi bo služilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 45, 'Tujci se mi bodo vdajali z laskanjem; komaj začujejo o meni, se mi bodo pokorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 46, 'Tujci bodo koprneli in pritrepetavali iz gradov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 47, 'Živ je Gospod; in hvaljena bodi skala moja in naj se povišuje Bog, skala rešenja mojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 48, 'ta Bog mogočni, ki mi daje maščevanje in spravlja ljudstva podme');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 49, 'in me izpeljava izsredi sovražnikov mojih. Da, ti me povzdiguješ nadnje, ki vstajajo zoper mene, siloviteža me otimlješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 50, 'Zato te bom hvalil, o Gospod, med narodi in psalme prepeval imenu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 22, 51, 'Veliko in obilo rešenje daje kralju svojemu in milost izkazuje maziljencu svojemu, Davidu, in semenu njegovemu na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 1, 'Te pa so zadnje besede Davidove. David, sin Jesejev, govori, mož, ki je bil visoko postavljen, maziljenec Boga Jakobovega, sladki pevec psalmov v Izraelu govori:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 2, 'Duh Gospodov je govoril po meni, in beseda njegova je bila na mojem jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 3, 'Bog Izraelov je rekel, Skala Izraelova je meni govorila: Pride vladar ljudem, pravičen, ki vlada v strahu Božjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 4, 'in bode kakor svetloba jutranja, ko solnce vzhaja, jutro brez oblakov: od njegovega sijaja po dežju poganja zelenjava iz zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 5, 'Čeprav ni taka moja hiša pri Bogu, a vendar je storil večno zavezo z menoj, urejeno v vsem in zavarovano; kajti to je vse rešenje moje in vsa želja moja. Ali bi ne dal, da to vzraste?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 6, 'Ali Belijalci bodo vsi kakor trnje, ki se zameta, ker ga ni jemati v roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 7, 'ampak mož, ki se ga dotakne, si preskrbi železo in suličišče; in popolnoma bodo sežgani z ognjem v kraju svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 8, 'Ta so imena junakov, ki jih je imel David: Joseb Basebet Tahkemončan, prvi poveljnikov; on je bil tisti Adino Ezni proti osemsto, ki jih je pobil naenkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 9, 'In za njim je bil Eleazar, sin Dodaja, sinu Ahohija, eden izmed treh junakov pri Davidu, ko so zasmehovali Filistejce, ki so bili ondi zbrani v boj, ko so odšli možje Izraelovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 10, 'on je vstal in pobijal Filistejce, dokler mu ni roka onemogla in otrpnila na meču; in Gospod je storil veliko rešitev tisti dan. Ljudstvo pa se je vrnilo za njim, samo da pobere plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 11, 'In za njim je bil Sama, sin Ageja Hararca. In Filistejci so se zbrali v eno krdelo, kjer je bila njiva polna leče, in ljudstvo je bežalo pred Filistejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 12, 'Tedaj se je on postavil sredi njive in jo je otel in pobil Filistejce; in Gospod je storil veliko rešitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 13, 'In trije izmed tridesetih načelnikov so šli doli in prišli k Davidu ob žetvi v Adulamsko votlino; in krdelo Filistejcev je bilo utaborjeno v dolini Refaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 14, 'David pa je bil takrat v trdnjavi, in straža Filistejcev je bila tedaj v Betlehemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 15, 'In Davida je obšla želja in je rekel: O, da bi mi kdo dal piti vode iz studenca v Betlehemu, ki je pri vratih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 16, 'In ti trije junaki so prodrli ostrog Filistejcev ter zajeli vode iz studenca v Betlehemu, ki je pri vratih, in so je vzeli ter prinesli Davidu. A on je ni hotel piti in jo je izlil kot pitno daritev Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 17, 'in je rekel: Nikakor ne, o Gospod, da bi jaz to storil! Naj li pijem kri mož, ki so šli tja in vnemar pustili življenje! In ni je hotel piti. To so storili ti trije junaki. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 18, 'In Abisaj, Joabov brat, sin Zervijin, je bil glava trem. On je mahnil s sulico svojo po treh sto in jih pobil; in imel je sloveče ime med tremi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 19, 'Ni li bil najslavnejši izmed teh treh, da jim je postal knez? Toda prvih treh ni dosegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 20, 'In Benaja, sin Jojadov, sin hrabrega moža iz Kabzeela, ki je storil velika dela, ta je ubil dva sina Ariela iz Moaba; ta je tudi stopil doli in ubil leva sredi jame, ko je bil sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 21, 'In ubil je Egipčana, velikega moža, in Egipčan je imel v roki sulico, a on je šel k njemu doli s palico in iztrgal sulico Egipčanu iz roke in ga je umoril z lastno sulico njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 22, 'To je storil Benaja, sin Jojadov, in imel je sloveče ime med tremi junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 23, 'On je bil slavnejši nego tistih trideset, ali prvih treh ni dosegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 24, 'Asahel, brat Joabov, je bil eden iz trideseterih, Elhanan, sin Dodov iz Betlehema,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 25, 'Sama Harodčan, Elika Harodčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 26, 'Helez Paltičan, Ira, sin Ikešev, Tekojčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 27, 'Abiezer Anatotčan, Mebunaj Husajec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 28, 'Zalmon Ahohovec, Maharaj Netofatčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 29, 'Heleb, sin Baanov, Netofatčan, Itaj, sin Ribajev iz Gibee sinov Benjaminovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 30, 'Benaja Piratončan, Hidaj od potokov v Gaasu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 31, 'Abialbon Arbatski, Azmavet Barhumčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 32, 'Eljahba Salbončan, iz sinov Jasenovih Jonatan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 33, 'Sama Hararovec, Ahiam, sin Sararjev, Ararovec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 34, 'Elifelet, sin Ahasbaja, sinu Maakatovca, Eliam, sin Ahitofela Gilonskega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 35, 'Hezro Karmelčan, Paaraj Arbski,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 36, 'Igal, sin Natana iz Zobe, Bani Gadovec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 37, 'Zelek Amonec, Naharaj Beerotčan, oproda Joaba, sinu Zervijinega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 38, 'Ira Jitričan, Gareb Jitričan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 23, 39, 'Urija Hetejec, vseh sedemintrideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 1, 'In srd Gospodov se je zopet vnel zoper Izraelce, in izpodbodel je Davida zoper nje, rekoč: Pojdi, seštej Izraela in Judo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 2, 'In kralj reče Joabu, poveljniku vojske, ki je bil pri njem: Prehodi, prosim, vse rodove Izraelove, od Dana do Bersebe, in preštejte ljudstvo, da bi vedel število ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 3, 'In Joab reče kralju: Naj prida Gospod, Bog tvoj, k ljudstvu, kolikorkoli ga je, še stokrat toliko, dokler to vidijo oči gospoda mojega, kralja! Ali zakaj to veseli gospoda mojega, kralja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 4, 'Toda beseda kraljeva je obveljala zoper Joaba in zoper poveljnike vojske. In odidejo Joab in poveljniki vojske od obličja kraljevega, da preštejejo ljudstvo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 5, 'In šli so čez Jordan in se utaborili v Aroerju, na desno ob mestu, ki je sredi doline Gadove, in proti Jazerju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 6, 'Potem so prišli v Gilead in v pokrajino Tahtim-hodši; in prišli so v Danjaan in v okolico Sidonsko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 7, 'in dospeli so k utrjenemu mestu Tiru in k vsem mestom Hevejcev in Kanaancev ter šli potem v južno stran Judovo, proti Bersebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 8, 'In prehodili so vso deželo in prišli v Jeruzalem ob koncu devetih mesecev in dvajsetih dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 9, 'In Joab je dal število preštetega ljudstva kralju; in bilo je v Izraelu osemsto tisoč vojakov, ki so izdirali meč, in v Judi petsto tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 10, 'A Davidu je očitalo srce, potem ko je bil seštel ljudstvo. In reče David Gospodu: Hudo sem grešil s tem, kar sem storil; ali sedaj, o Gospod, odpravi hlapca svojega krivico, kajti ravnal sem zelo nespametno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 11, 'In ko vstane David zjutraj, pride beseda Gospodova k proroku Gadu, vidcu Davidovemu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 12, 'Pojdi in veli Davidu: Tako pravi Gospod: Troje ti ponujam, izberi si eno, da naj ti storim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 13, 'Pride torej Gad k Davidu in mu pove ter mu reče: Ali naj ti pride sedem let lakote v deželo tvojo? Ali hočeš tri mesece bežati pred nasprotniki svojimi, da te oni podijo? Ali naj razsaja tri dni kuga v deželi tvoji? Sedaj pa premisli in poglej, kakšen odgovor naj dam njemu, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 14, 'In David reče Gadu: V stiski sem veliki! Naj rajši pademo v roko Gospodovo, kajti usmiljenje njegovo je veliko, in nikar naj ne padem v roko človeško!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 15, 'In Gospod je poslal kugo nad Izraela od jutra do določenega časa; in pomrlo je iz ljudstva od Dana do Bersebe sedemdeset tisoč ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 16, 'In ko iztegne angel roko proti Jeruzalemu, da ga pogubi, je bilo žal Gospodu hudega in veli angelu, ki je pokončeval ljudstvo: Dosti je, odtegni zdaj roko svojo! In angel Gospodov je bil pri gumnu Aravna Jebusejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 17, 'In David reče Gospodu, ko je videl angela, ki je pobijal ljudstvo: Glej, jaz sem grešil in jaz sem ravnal popačeno, te ovce pa, kaj so storili? Roka tvoja bodi, prosim, zoper mene in zoper očeta mojega hišo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 18, 'In Gad pride tisti dan k Davidu in mu reče: Pojdi gori, zgradi oltar Gospodu na gumnu Aravna Jebusejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 19, 'In David je šel gori po besedi Gadovi, kakor je ukazal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 20, 'In Aravna se ozre in zagleda kralja in služabnike njegove, da gredo proti njemu; in Aravna izide in se prikloni kralju z obrazom do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 21, 'In Aravna reče: Zakaj je prišel gospod moj, kralj, k hlapcu svojemu? David pa reče: Kupiti hočem gumno od tebe, da zgradim oltar Gospodu, da neha kuga med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 22, 'In Aravna reče Davidu: Vzame naj gospod moj, kralj, in daruje, kar se mu vidi dobro: glej, tu so voli za žgalno daritev in mlatilnice in oprava volovska za drva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 23, 'Vse to, o kralj, Aravna pokloni kralju. Še reče Aravna kralju: Gospod, Bog tvoj, te milo sprejmi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 24, 'A kralj reče Aravnu: Nikar, ampak res hočem to kupiti od tebe za ceno, ker nočem darovati žgalnih daritev Gospodu, Bogu svojemu, ki bi jih brez stroškov imel. Kupil je torej David gumno in vole za petdeset seklov srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (10, 24, 25, 'In David je ondi zgradil oltar Gospodu ter daroval žgalne in mirovne daritve. In Gospod se je dal izprositi za deželo, in kuga je nehala med Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 1, 'David kralj pa je bil že star in prileten, in pokrivali so ga z odejami, a se ni ogrel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 2, 'Zato so mu rekli služabniki njegovi: Poišče naj se za gospoda mojega, kralja, mlada devica, in naj stoji pri kralju in mu bodi strežnica ter naj spava v naročju njegovem, da se ogreje gospod moj, kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 3, 'In iskali so lepe mladenke po vseh krajih Izraelovih, in najdejo Abisago Sunamljanko ter jo pripeljejo h kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 4, 'Mladenka pa je bila zelo lepa, in postala je strežnica kralju in mu je služila; a kralj je ni spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 5, 'Tedaj se je Adonija, sin Hagitin, povzdignil, rekoč: Jaz bom kraljeval! In oskrbi si voz in konj in petdeset mož, ki naj bi tekali pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 6, 'In oče njegov ga nikdar ni užalil, da bi mu bil rekel: Zakaj si storil tako? Bil pa je tudi zelo lepe postave mož, in rojen je bil po Absalomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 7, 'In posvetoval se je z Joabom, sinom Zervijinim, in z duhovnikom Abiatarjem, in ona sta mu pomagala, hodeč za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 8, 'Ali Zadok duhovnik in Benaja, sin Jojadov, in Natan prorok in Simej in Rej in vojščaki, ki so bili Davidovi, niso bili pri Adoniju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 9, 'In Adonija pokolje ovac in volov in pitancev pri kamenu Zoheletu, ki je tik studenca Rogela, in povabi vse brate svoje, sinove kraljeve, in vse može Judove, kraljeve služabnike;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 10, 'toda Natana proroka in Benaja in vojščakov in Salomona, brata svojega, ni povabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 11, 'Tedaj govori Natan Batsebi, materi Salomonovi, rekoč: Nisi li slišala, da je zakraljeval Adonija, sin Hagitin, in David, gospod naš, ne ve za to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 12, 'Sedaj pa pridi, daj, da ti svetujem, da bi rešila življenje sebi in sinu svojemu Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 13, 'Pojdi in stopi h kralju Davidu in mu reci: Nisi li, gospod moj, kralj, prisegel meni, dekli svoji, in rekel: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem? Zakaj torej kraljuje Adonija?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 14, 'Glej, ko boš tam še govorila s kraljem, pridem tudi jaz noter za teboj in potrdim besede tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 15, 'In Batseba pride h kralju v čumnato. Kralj pa je bil zelo star, in Abisaga Sunamljanka je stregla kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 16, 'In Batseba se pripogne in stori poklon kralju. In kralj vpraša: Kaj želiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 17, 'Ona mu pa reče: Gospod moj, ti si prisegel pri Gospodu, Bogu svojem, dekli svoji: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 18, 'In sedaj, glej, Adonija kraljuje, in ti, gospod moj, kralj, ne veš tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 19, 'In je zaklal obilo volov in pitancev in ovec ter je povabil vse sinove kraljeve in Abiatarja, duhovnika, in Joaba, poveljnika vojske, a Salomona, hlapca tvojega, ni povabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 20, 'Ti pa, gospod moj, kralj – oči vsega Izraela se ozirajo v te, da jim poveš, kdo bo sedel na prestolu gospoda mojega, kralja, za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 21, 'Sicer se zgodi, ko bo legel gospod moj, kralj, k očetom svojim, da bodo šteli mene in sina mojega Salomona kakor dva grešnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 22, 'In glej, ko še govori s kraljem, pride Natan prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 23, 'In naznanijo kralju, rekoč: Glej, Natan prorok. In ko stopi pred kralja, se pokloni pred kraljem z obrazom do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 24, 'In Natan reče: Gospod moj, kralj, si li ti rekel: Adonija bo kraljeval za menoj in on bo sedel na prestolu mojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 25, 'Kajti danes je šel doli in zaklal obilo volov in pitancev in ovac ter je povabil vse sinove kraljeve in poveljnike vojske in Abiatarja duhovnika; in glej, jedo in pijejo pred njim ter govore: Živel kralj Adonija!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 26, 'Mene pa, mene hlapca tvojega, in Zadoka duhovnika in Benaja, sina Jojadovega, in hlapca tvojega Salomona ni povabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 27, 'Se li je ta stvar napravila po gospodu mojem, kralju? Pa nisi oznanil hlapcem svojim, kdo bo sedel na prestolu gospoda mojega, kralja, za njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 28, 'Nato kralj odgovori in reče: Pokličite mi Batsebo. In ona stopi pred kralja in se postavi pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 29, 'In kralj priseže in veli: Kakor res živi Gospod, ki je rešil dušo mojo iz vseh nadlog:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 30, 'kakor sem ti prisegel pri Gospodu, Bogu Izraelovem, rekši: Salomon, sin tvoj, bo kraljeval za menoj in on bo sedel na prestolu mojem namesto mene, res, tako storim danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 31, 'Tedaj se pripogne Batseba z obrazom do tal in stori kralju poklon ter reče: Naj živi gospod moj, kralj David, vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 32, 'In kralj David veli: Pokličite mi Zadoka duhovnika in Natana proroka in Benaja, sina Jojadovega. In pridejo pred kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 33, 'In kralj jim veli: Vzemite s seboj hlapce gospoda svojega in dajte Salomonu, sinu mojemu, jezditi na mojem mezgu ter ga peljite doli h Gihonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 34, 'In tam naj ga pomazili Zadok duhovnik in Natan prorok za kralja Izraelu, in trobite na trobento ter recite: Naj živi kralj Salomon!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 35, 'Potem pojdete gori za njim, in on pride sem ter sede na moj prestol, zakaj kraljeval bo na mojem mestu, in jaz sem ukazal zanj, da bodi vojvoda Izraelu in Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 36, 'In Benaja, sin Jojadov, odgovori kralju in reče: Amen! Gospod, Bog gospoda mojega, kralja, naj reče istotako!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 37, 'Kakor je bil Gospod z gospodom mojim, kraljem, tako bodi s Salomonom in poveličaj mu prestol bolj, nego ga je poveličal gospodu mojemu, kralju Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 38, 'Zadok duhovnik torej in Natan prorok in Benaja, sin Jojadov, in Keretejci in Peletejci gredo doli ter posade Salomona na mezga kralja Davida in ga peljejo h Gihonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 39, 'In Zadok duhovnik vzame rog z oljem iz Šatora in pomazili Salomona. In zatrobijo na trobento, in vse ljudstvo kliče: Naj živi kralj Salomon!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 40, 'In vse ljudstvo je šlo gori v mesto za njim, in množica je godla na piščali in se veselila z velikim veseljem, da je zemlja odmevala od njih glasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 41, 'In Adonija in vsi gostje, ki so bili ž njim, zaslišijo to, ko so končali pojedino. In ko Joab čuje trobente glas, reče: Čemu je ta šum v mestu kakor ob vstaji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 42, 'Ko še govori, glej, prispeje Jonatan, sin Abiatarja duhovnika, in Adonija reče: Pridi sem, kajti vrl si mož in neseš dobro poročilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 43, 'In Jonatan odgovori in reče Adoniju: V resnici je gospod naš, kralj David, postavil Salomona za kralja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 44, 'In kralj je ž njim poslal Zadoka duhovnika in Natana proroka in Benaja, sina Jojadovega, in Keretejce in Peletejce, in so ga posadili na kraljevega mezga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 45, 'in Zadok duhovnik in Natan prorok sta ga pomazilila za kralja pri Gihonu. In prišli so gori odondod z veseljem, da se je mesto razburilo. To je šum, ki ste ga slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 46, 'In Salomon je že tudi zasedel prestol kraljestva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 47, 'In vrhutega so prišli kraljevi hlapci blagoslavljat gospoda našega, kralja Davida, govoreč: Bog tvoj naj stori ime Salomonovo bolj sloveče nego tvoje ime in poveliča prestol njegov bolj nego tvoj prestol. In kralj se je poklonil Bogu na postelji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 48, 'In kralj je tudi rekel takole: Hvaljen bodi Gospod, Bog Izraelov, ki mi je dal danes sedečega na prestolu mojem, da moje oči to še vidijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 49, 'In vsi gostje Adonijevi se prestrašijo ter vstanejo in odidejo vsak svojim potom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 50, 'Adonija pa, boječ se Salomona, vstane in odide ter se oprime oltarjevih rogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 51, 'In povedali so Salomonu, rekoč: Glej, Adonija se boji kralja Salomona, in glej, drži se, rogov oltarja in govori: Naj mi priseže danes kralj Salomon, da ne ubije hlapca svojega z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 52, 'In Salomon veli: Ako se izkaže vrlega moža, mu las ne pade z glave na tla; ako se pa hudoba najde pri njem, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 1, 53, 'Pošlje torej Salomon in ga pripeljejo od oltarja. In pride ter se pokloni kralju Salomonu, in Salomon mu reče: Pojdi v hišo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 1, 'Davidu pa so se bližali dnevi, da umrje. In zapove sinu svojemu Salomonu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 2, 'Jaz odhajam po poti vsega zemeljskega; bodi torej. močan in kaži se moža');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 3, 'in strezi na službo Gospodu, Bogu svojemu, da hodiš po potih njegovih, da izpolnjuješ postave in zapovedi in sodbe njegove in pričevanja njegova, po tem, kar je pisano v zakonu Mojzesovem, da bi imel prospeh v vsem, kar počneš in kamorkoli se obrneš;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 4, 'da bi Gospod utrdil besedo svojo, ki jo je govoril zame, rekoč: Bodo li pazili sinovi tvoji na pot svojo, da hodijo pred menoj v resnici z vsem srcem svojim in z vso dušo svojo, ne bo ti zmanjkalo (je dejal) moža za prestol Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 5, 'Veš pa, kar mi je storil Joab, sin Zervijin, namreč kar je storil dvema poveljnikoma vojsk Izraelovih, Abnerju, sinu Nerovemu, in Amasu, sinu Jeterjevemu, ki ju je ubil in prelil kri kakor v vojni ob času miru in si okrvavil z zvijačno prelito krvjo pas okoli ledij in obuvalo na nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 6, 'Stóri torej ž njim po modrosti svoji in ne pústi sivi glavi njegovi, da gre v grob v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 7, 'Sinovom Barzilaja Gileadčana pa izkazuj milost ter naj bodo med tistimi, ki jedo pri mizi tvoji, kajti tako so prišli k meni, ko sem bežal pred Absalomom, bratom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 8, 'Glej tudi, izročen ti je Simej, sin Gerov, Benjaminec iz Bahurima, ki me je preklinjal s strašnim preklinjanjem v dan, ko sem šel v Mahanaim; ali prišel mi je naproti doli k Jordanu, in prisegel sem mu pri Gospodu, rekoč: Ne umorim te z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 9, 'Sedaj ga torej ne imej za nedolžnega, zakaj moder si mož in vedel boš, kako naj ž njim ravnaš, in spraviš sivo glavo njegovo v grob s krvjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 10, 'In legel je David k očetom svojim in je bil pokopan v mestu Davidovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 11, 'Dni pa, kar jih je David kraljeval Izraelu, je bilo štirideset let: sedem let je kraljeval v Hebronu, triintrideset let pa v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 12, 'In Salomon je zasedel prestol Davida, očeta svojega, in kraljestvo njegovo je bilo dobro utrjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 13, 'Tedaj pride Adonija, sin Hagitin, k Batsebi, materi Salomonovi. In ona vpraša: Je li tvoj prihod miren? On odgovori: Miren.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 14, 'Dalje reče: Imam s teboj nekaj govoriti. Ona veli: Govóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 15, 'In reče: Veš, da je bilo kraljestvo moje in da je ves Izrael obrnil proti meni obličje svoje, da bodem kralj; toda kraljestvo je šlo mimo mene ter pripadlo mojemu bratu, kajti njemu je bilo določeno od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 16, 'In zdaj imam eno prošnjo do tebe, ne zavrni me. Ona mu veli: Govóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 17, 'On pa reče: Govóri, prosim, s kraljem Salomonom, kajti on ne zavrne tebe, da naj mi da Abisago Sunamljanko za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 18, 'In Batseba reče: Dobro; hočem s kraljem govoriti zastran tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 19, 'Gre torej Batseba h kralju Salomonu govorit ž njim zastran Adonija. In vstane kralj ter ji pride naproti in se ji pokloni, potem sede na svoj prestol in veli postaviti prestol za mater kraljevo, in ona mu sede ob desnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 20, 'Tedaj reče: Majhno prošnjo imam do tebe, ne zavrni me! In kralj ji reče: Prosi, mati moja, kajti ne zavrnem te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 21, 'Ona reče: Naj se da Abisaga Sunamljanka bratu tvojemu Adoniju za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 22, 'In kralj Salomon odgovori ter reče materi svoji: Zakaj pa prosiš Abisage Sunamljanke za Adonija? Prosi zanj še tudi kraljestva – kajti on je moj starejši brat – in za njega in za Abiatarja duhovnika in za Joaba, sina Zervije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 23, 'Nato priseže kralj Salomon pri Gospodu, rekoč: To naj mi stori Gospod in to naj pridene, če ni govoril Adonija te besede zoper življenje svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 24, 'Zdaj torej, kakor res živi Gospod, ki me je potrdil in me posadil na očeta mojega Davida prestol in ki mi je ustanovil hišo, kakor je bil obljubil: gotovo danes mora Adonija umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 25, 'In pošlje kralj Salomon Benaja, sina Jojadovega, in ta ga je udaril, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 26, 'Abiatarju duhovniku pa je rekel kralj: Pojdi v Anatot na njive svoje, zakaj vreden si smrti, ali nočem te danes umoriti, ker si nosil skrinjo Gospoda Jehove pred Davidom, očetom mojim, in ker si vse stiske trpel ž njim, kadar je on bil v stiskah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 27, 'In Salomon je odstavil Abiatarja, da ni bil več duhovnik Gospodu; da se izpolni beseda Gospodova, ki jo je govoril za hišo Elijevo v Silu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 28, 'In glas o tem je prišel do Joaba, zakaj Joab se je odvrnil za Adonijem, dasi se za Absalomom ni bil odvrnil. In pobegne Joab v šator Gospodov ter se oprime rogov oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 29, 'In sporoče kralju Salomonu: Joab je zbežal v šator Gospodov, in glej, je pri oltarju. Tedaj pošlje Salomon Benaja, sina Jojadovega, in veli: Pojdi, udari ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 30, 'In pride Benaja v šator Gospodov ter mu reče: Tako pravi kralj: Pojdi ven! On odgovori: Nikar, kajti tu hočem umreti. In sporoči Benaja besedo kralju, rekoč: Tako je rekel Joab in tako mi je odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 31, 'In veli mu kralj: Stóri mu, kakor je rekel, in udari ga ter ga pokoplji, da odpraviš kri, ki jo je Joab prelil brez razloga, od mene in od hiše očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 32, 'In Gospod povrne kri na glavo njegovo, ker je udaril dva moža, pravičnejša in boljša, nego je bil sam, in ju je umoril z mečem, in oče moj, David, ni vedel za to: Abnerja, sina Nerovega, poveljnika vojske Izraelove, in Amasa, sina Jeterjevega, poveljnika vojske Judove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 33, 'Tako se povrne njiju kri na glavo Joabovo in na glavo zaroda njegovega vekomaj; ali Davidu in zarodu njegovemu in hiši njegovi in prestolu njegovemu bodi mir vekomaj od Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 34, 'Šel je torej gori Benaja, sin Jojadov, in ga je udaril in usmrtil; in pokopan je bil v svoji hiši v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 35, 'In kralj je postavil Benaja, sina Jojadovega, namesto njega nad vojsko, in Zadoka duhovnika je kralj postavil namesto Abiatarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 36, 'Pošlje tudi kralj in pokliče Simeja ter mu veli: Sezidaj si hišo v Jeruzalemu in tu prebivaj ter ne hodi odtod ne tja, ne sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 37, 'Kateri dan namreč pojdeš ven in preideš potok Kidron, vedi za gotovo, da moraš umreti; tvoja kri pride na tvojo glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 38, 'In Simej reče kralju: Dobra je ta beseda; kakor je velel gospod moj, kralj, tako bo storil hlapec tvoj. In Simej je prebival precej časa v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 39, 'Prigodi se pa po treh letih, da sta Simeju utekla dva hlapca k Ahisu, sinu Maakovemu, h kralju v Gatu. In sporoče Simeju, rekoč: Glej, hlapca tvoja sta v Gatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 40, 'In vstane Simej ter osedla osla ter gre v Gat k Ahisu, da poišče svoja hlapca; odide torej in pripelje hlapca svoja iz Gata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 41, 'In naznanijo Salomonu, da je šel Simej iz Jeruzalema v Gat in se zopet vrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 42, 'In kralj pošlje ter pokliče Simeja in mu reče: Te li nisem zaprisegel pri Gospodu in te resno posvaril, rekoč: Gotovo vedi, da moraš umreti, kateri dan greš ven in pojdeš sem ali tja? In si mi dejal: Dobra je beseda, ki sem jo slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 43, 'Zakaj nisi torej izpolnil prisege Gospodove in zapovedi, ki sem ti jo ukazal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 44, 'Še reče Salomon Simeju: Ti veš za vso hudobnost, katere si je v svesti srce tvoje, ki si jo storil Davidu, očetu mojemu; zato Gospod povrne hudobnost tvojo tebi na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 45, 'A kralj Salomon bo blagoslovljen in prestol Davidov bo utrjen pred Gospodom za vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 2, 46, 'In kralj ukaže Benaju, Jojadovemu sinu, in ta gre ven ter ga udari, da umrje. In kraljestvo je bilo utrjeno v roki Salomonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 1, 'In Salomon je sklenil svaštvo s Faraonom, egiptovskim kraljem, vzemši hčer Faraonovo; in pripeljal jo je v mesto Davidovo, dokler ni dozidal hiše svoje in hiše Gospodove in zidu okoli Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 2, 'Ali ljudstvo je darovalo na višavah, ker ni bilo hiše sezidane imenu Gospodovem do teh dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 3, 'In Salomon je ljubil Gospoda živeč po postavah Davida, očeta svojega, samo da je daroval in kadilo žgal na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 4, 'Šel pa je Salomon v Gibeon, da bi ondi daroval, kajti to je bila velika višava; tisoč žgalnih daritev je daroval Salomon na ondotnem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 5, 'V Gibeonu se je Gospod prikazal Salomonu v sanjah po noči; in Bog je dejal: Prosi, kaj naj ti dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 6, 'In Salomon reče: Ti si izkazal hlapcu svojemu Davidu, očetu mojemu, veliko milost, po tem, da je živel pred obličjem tvojim v resnici, v pravičnosti in poštenosti srca s teboj; in si mu ohranil to milost veliko, da si mu dal sina, da bi sedel na prestolu njegovem, kakor se danes vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 7, 'In sedaj, Gospod, Bog moj, si storil hlapca svojega za kralja namesto Davida, očeta mojega, jaz pa sem majhen deček, ne vem, kako hoditi ven in kako hoditi noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 8, 'In hlapec tvoj je sredi ljudstva tvojega, ki si ga izvolil, ki je ljudstvo veliko in se ne more prešteti, ne popisati zavoljo množine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 9, 'Daj torej hlapcu svojemu razumno srce, da more soditi ljudstvo tvoje in razpoznavati dobro in zlo; kajti kdo je zmožen soditi temu množnemu ljudstvu tvojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 10, 'In dobra je bila ta beseda v očeh Gospodovih, da je Salomon prosil take reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 11, 'In Bog mu reče: Ker si prosil te reči in nisi prosil sebi dolgega življenja, tudi ne bogastva zase, niti smrti svojih sovražnikov, marveč si prosil zase razumnosti, da znaš zasliševati pravde:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 12, 'glej, storil sem po besedi tvoji: dal sem ti srce modro in razumno, da ni bilo tebi enakega pred teboj in tudi za teboj enak ne vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 13, 'Pa tudi česar nisi prosil, sem ti dal, bogastva in slave, da ne bode tebi enakega med kralji vse tvoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 14, 'In ako boš hodil po mojih potih, izpolnjujoč moje postave in zapovedi, kakor je hodil oče tvoj David, podaljšam tvoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 15, 'In Salomon se prebudi, in glej, sanje so bile; in pride v Jeruzalem ter se postavi pred skrinjo zaveze Gospodove in daruje žgalne in mirovne daritve in napravi gostovanje vsem svojim hlapcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 16, 'Tedaj sta prišli dve ženski, nečistnici, h kralju in stopili predenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 17, 'In prva reče: Prosim, gospod moj, jaz in ta žena prebivava v eni hiši, in porodila sem pri njej v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 18, 'In tretji dan po mojem porodu je porodila tudi ona; in bili sva skupaj ter ni bilo tujca z nama v hiši, sami dve sva bili v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 19, 'In te žene sin je umrl po noči, ker ga je poležala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 20, 'In vstane opolnoči in vzame sina mojega od moje strani, ko je spala dekla tvoja, ter ga položi v naročje svoje, svojega mrtvega sina pa položi meni v naročje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 21, 'In ko vstanem proti jutru, da bi podojila sina svojega, glej, mrtev je bil; ali ko ga bolj skrbno pogledam za jutra, glej, ni bil moj sin, ki sem ga bila porodila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 22, 'In druga žena reče: Ni tako, ampak moj sin je živ, in tvoj sin je mrtev. Ta pa odvrne: Nikar, ampak mrtvi je tvoj, živi pa moj. Tako sta se prepirali pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 23, 'Tedaj reče kralj: Ta pravi: Ta je moj sin, ki živi, in mrtvi je tvoj; in druga pravi: Nikar, ampak tvoj sin je mrtev, moj pa živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 24, 'Veli kralj: Prinesite mi meč! In prineso pred kralja meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 25, 'Kralj pa veli: Razdelite živo dete na dvoje in dajte tej polovico ter polovico oni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 26, 'Tedaj izpregovori žena, katere je bilo živo dete, kajti njeno srce se je genilo nad njenim otrokom, in reče kralju: Prosim, gospod moj, dajte ji živo dete in nikar ga ne usmrtite! Druga pa reče: Ne bodi ne moje, ne tvoje, razdeli naj se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 27, 'Tedaj odgovori kralj in veli: Dajte oni živo dete, nikar ga ne umorite! ona je mati njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 3, 28, 'In slišal je ves Izrael sodbo, ki jo je razsodil kralj, in bali so se kralja, kajti videli so, da je modrost Božja v njem, da bi delil pravico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 1, 'In kralj Salomon je kraljeval vsemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 2, 'In ti so knezi, ki jih je imel: Azarija, sin Zadokov, duhovnik;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 3, 'Elihoref in Ahija, sinova Sisova, sta bila pisarja; Josafat, sin Ahiludov, je bil deželni letopisec;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 4, 'in Benaja, sin Jojadov, je bil nad vojsko, in Zadok in Abiatar sta bila duhovnika;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 5, 'Azarija pa, sin Natanov, je bil nad uradniki, in Zabud, sin Natanov, je bil prvi dvorjan, kraljev prijatelj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 6, 'in Ahisar je bil nad dvorcem in Adoniram, sin Abdov, je bil nad davščinami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 7, 'In Salomon je imel dvanajst uradnikov nad vsem Izraelom, ki so oskrbovali kralja in družino njegovo z živežem: vsak je imel oskrbovati po en mesec v letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 8, 'In ta so njih imena: Benhur na Efraimskem gorovju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 9, 'Bendeker v Makazu in v Saalbimu in Betsemesu in Elon-bethananu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 10, 'Benhesed v Arubotu, njemu je pripadalo Soko in vsa pokrajina Heferska;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 11, 'Ben-abinadab na vsem hribovju Dorskem; on je imel Tafato, hčer Salomonovo, za ženo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 12, 'Baana, sin Ahiludov, v Taanahu in Megidu in v vsem Betseanu, ki je poleg Zaretana pod Jezreelom, od Betseana do Abel-mehole, tja daleč nasproti Jokmeamu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 13, 'Bengeber v Ramot-gileadu; njemu so pripadali trgi Jaira, sina Manaseja, ki so v Gileadu, njegov je bil kraj Argob, ki je v Basanu, šestdeset velikih mest z okopi in bronastimi zapahi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 14, 'Ahinadab, sin Idov, v Mahanaimu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 15, 'Ahimaaz v Neftaliju; on je tudi vzel Basemato, hčer Salomonovo, za ženo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 16, 'Baana, sin Husajev, v Aserju in Alotu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 17, 'Josafat, sin Parnahov, v Isaharju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 18, 'Simej, sin Elov, v Benjaminu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 19, 'Geber, sin Urijev, v Gileadski pokrajini, v deželi Sihona, kralja Amorejcev, in Oga, kralja v Basanu; in on je bil edini uradnik v pokrajini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 20, 'Juda in Izrael sta bila mnogoštevilna kakor pesek, ki ga je ob morju obilo; jedli so in pili ter se veselili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 21, 'In Salomon je gospodoval vsem kraljestvom od velereke do dežele Filistejcev in do egiptovske meje: prinašali so mu darila in služili Salomonu vse dni življenja njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 22, 'In Salomonov potrebni živež na dan je bil: trideset meric bele moke in šestdeset meric druge moke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 23, 'deset pitanih volov in dvajset pašnih volov in sto ovac razen jelenov, srn in srnjakov in pitane perutnine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 24, 'Kajti imel je gospostvo nad vsemi pokrajinami na tej strani velereke, od Tifsaha do Gaze, nad vsemi kralji tostran reke; in imel je mir na vseh straneh naokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 25, 'In Juda in Izrael je prebival brez skrbi, vsak pod svojo trto in pod svojo smokvo, od Dana do Bersebe vse dni Salomonove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 26, 'In Salomon je imel štirideset tisoč jasli za vprežne konje in dvanajst tisoč konj za ježo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 27, 'In tisti uradniki so oskrbovali živež kralju Salomonu in vsem, ki so jedli pri kraljevi mizi, vsak v svojem mesecu, in so pazili, da ni ničesar primanjkalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 28, 'Tudi ječmen in slamo za konje in mezge so spravljali na mesto, kjer je bilo treba, vsak po svojem naročilu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 29, 'In Bog je dal Salomonu modrosti in razumnosti jako obilo in širokosti srca kakor peska, ki je ob morskem bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 30, 'In večja je bila modrost Salomonova nego modrost vseh sinov na Jutrovem in vsa modrost Egipčanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 31, 'Kajti modrejši je bil nego vsi ljudje, nego Etan Ezrahovec in Heman in Kalkol in Darda, sinovi Maholovi, in glas imena njegovega je šel po vseh narodih naokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 32, 'In govoril je tri tisoč pregovorov in pesmi njegovih je bilo tisoč in pet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 33, 'In govoril je o drevju, od cedre, ki je na Libanonu, do izopa, ki raste iz stene; govoril je tudi, o živini in o pticah in o laznini in o ribah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 4, 34, 'In prihajali so izmed vseh ljudstev poslušat modrost Salomonovo, od vseh kraljev zemlje, ki so začuli o modrosti njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 1, 'In Hiram, kralj tirski, je poslal služabnike svoje k Salomonu, zakaj slišal je bil, da so ga pomazilili za kralja namesto očeta njegovega; Hiram je namreč ljubil Davida vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 2, 'In Salomon pošlje k Hiramu sporočit:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 3, 'Ti veš, da ni mogel David, oče moj, zgraditi hiše imenu Gospoda, Boga svojega, spričo sosedov, ki so ga zapletali v vojne, dokler jih ni položil Gospod pod stopala nog njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 4, 'Sedaj pa mi je dal Gospod, Bog moj, mir vseokrog; nobenega ni nasprotnika, ne hude prigodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 5, 'Glej torej, zgraditi nameravam hišo imenu Gospoda, Boga svojega, kakor je Gospod govoril Davidu, očetu mojemu, rekoč: Sin tvoj, ki ga posadim na prestol tvoj na tvoje mesto, sezida hišo imenu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 6, 'Zdaj torej ukaži, da mi nasekajo ceder z Libanona, in hlapci moji bodo s hlapci tvojimi, tudi plačilo ti dam za hlapce tvoje, kakršnokoli boš zahteval; saj veš, da ga ni med nami, ki bi znal sekati les kakor Sidonci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 7, 'In ko je slišal Hiram besede Salomonove, se silno razveseli ter reče: Hvaljen bodi danes Gospod, ki je dal Davidu modrega sina nad tem velikim ljudstvom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 8, 'In Hiram pošlje Salomonu sporočit: Slišal sem, kar si mi sporočil. Storil bom vso voljo tvojo glede cedrovega in cipresovega lesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 9, 'Hlapci moji ga bodo spravljali z Libanona doli k morju, in zložim ga v splave, da pojde po morju do mesta, ki mi ga določiš; in tam ga dam razvezati, in ti si ga odpraviš. Ti pa izpolniš voljo mojo, da boš dajal živeža moji družini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 10, 'Tako je dal Hiram Salomonu cedrovega in cipresovega lesa po vsej volji njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 11, 'Salomon pa je dajal Hiramu po dvajset tisoč meric pšenice v živež njegovi družini in po dvajset meric čistega olja; toliko je dal Salomon Hiramu vsako leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 12, 'In Gospod je dal Salomonu modrost, kakor mu je obljubil; in bil je mir med Hiramom in Salomonom, in oba sta sklenila zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 13, 'In kralj Salomon je vzel davek od vsega Izraela, in davek je bil trideset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 14, 'In pošiljal jih je na Libanon, po deset tisoč vsak mesec, menoma: mesec dni so bili na Libanonu in dva meseca doma. Adoniram pa je bil nad temi robotniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 15, 'In Salomon jih je imel sedemdeset tisoč, ki so nosili bremena, in osemdeset tisoč njih, ki so sekali v gorah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 16, 'razen višjih uradnikov, ki so nadzorovali delo, tri tisoč in tristo; ti so gospodovali ljudstvu, ki je opravljalo delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 17, 'In kralj je ukazal, in pripravili so velikih in dragih kamenov, obsekanih kamenov za podstavo hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 5, 18, 'In obdelovali so jih Salomonovi stavbarji in Hiramovi stavbarji in Gebaljani; in pripravljali so les in kamenje za stavbo hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 1, 'In bilo je v štiristo in osemdesetem letu po izhodu sinov Izraelovih iz Egiptovske dežele, v četrtem letu Salomonovega kraljevanja Izraelu, v mesecu Zivu, ki je drugi mesec, da je zidal hišo Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 2, 'In hiša, ki jo je gradil kralj Salomon Gospodu, je bila šestdeset komolcev dolga, dvajset komolcev široka in trideset komolcev visoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 3, 'In veža pred templjevo dvorano je bila dvajset komolcev dolga, skladno s širjavo hiše, in deset komolcev široka spredaj pred hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 4, 'In hiši je naredil okna, široka znotraj in ozka zunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 5, 'In ob zidovju hiše, sporedno s hišnimi stenami, pri dvorani in pri govorišču, je zgradil tristropen prizidek in v njem stranske sobe kroginkrog:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 6, 'spodnje stropje je bilo široko pet komolcev, srednje šest komolcev in tretje sedem komolcev široko; kajti na zunanji strani hišnega zida je napravil odstavke, da ne bi bila bruna vtaknjena v hišni zid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 7, 'In ko so gradili hišo, so jo skladali iz kamenov, popolnoma obsekanih v kamenarnici, da ni bilo slišati kladiva, ne sekire, ne kakršnegakoli železnega orodja v hiši, ko so jo gradili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 8, 'Vrata do spodnjih obstranskih sob so bila na desni strani hiše, in po zavitih stopnicah se je hodilo v srednje sobe in iz srednjih v tretje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 9, 'In zidal je hišo in jo dokončal; in prekril je hišo z bruni in deskami iz cedrovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 10, 'In prizidek je zgradil ob vsej hiši, vsako nadstropje po pet komolcev visoko, in cedrovo brunovje jih je vezalo s hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 11, 'In beseda Gospodova je prišla Salomonu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 12, 'Zastran te hiše, ki jo gradiš –: ako boš živel po mojih postavah in izvrševal sodbe moje in pazil na vse moje zapovedi, da se po njih ravnaš, utrdim besedo svojo s teboj, ki sem jo govoril tvojemu očetu Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 13, 'In prebival bom med sinovi Izraelovimi in ne zapustim ljudstva svojega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 14, 'In Salomon je zidal hišo in jo dozidal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 15, 'In obložil je hišne stene odznotraj s cedrovimi deskami; od tal hiše do stropnih brun jih je znotraj opažil z lesom, tudi tla hiše je pokril s cipresovimi deskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 16, 'In pregradil je dvajset komolcev od zadnje strani hiše znotraj s cedrovo steno od tal do stropa, da bodi to notri v hiši za govorišče ali Najsvetejše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 17, 'Hiša pa, to je templjeva dvorana spredaj, je bila štirideset komolcev dolga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 18, 'In po hišnih stenah odznotraj je bila cedrovina in na njej izrezano bučkasto sadje in razvito cvetje; vse je bila cedrovina, kamena se ni nič videlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 19, 'In govorišče znotraj v hiši je pripravil, da tam postavi skrinjo zaveze Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 20, 'Bilo je pa govorišče znotraj dvajset komolcev dolgo, dvajset široko in dvajset visoko, in obložil ga je s čistim zlatom; tudi oltar iz cedrovine je obložil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 21, 'In Salomon je prevlekel hišo znotraj s čistim zlatom; in potegnil je zlate verižice pred govoriščem, ko ga je prevlekel z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 22, 'In vso hišo je prevlekel z zlatom, vso hišo popolnoma; tudi ves oltar, ki je bil ob govorišču, je prevlekel z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 23, 'In v govorišču je naredil dva keruba iz oljkovega lesa, deset komolcev visoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 24, 'In pet komolcev je imela ena perut keruba in pet komolcev druga perut: od kraja ene peruti do konca druge peruti je bilo deset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 25, 'In drugi kerub je imel deset komolcev; oba keruba sta bila ene mere in ene oblike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 26, 'Višava enega keruba je bila deset komolcev in takisto drugega keruba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 27, 'In postavil je keruba v notranjo hišo, in peruti kerubov so bile razprostrte, da se je perut enega dotikala tega zidu in perut drugega keruba onega zidu, a sredi hiše sta se dotikali druga druge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 28, 'In prevlekel je keruba z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 29, 'In dal je narediti po vseh stenah kroginkrog izrezane podobe kerubov in palm in razvitega cvetja, znotraj in zunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 30, 'In tla hiše je obložil z zlatom znotraj in zunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 31, 'In za vhod v govorišče je napravil vrata iz oljkovega lesa, naddurje s podboji je bilo dolgo petino zidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 32, 'In dve durnici sta bili iz oljkovega lesa, in naredil je na njiju izrezljane kerube in palme in razvito cvetje in ju prevlekel z zlatom, in raztegnil je zlato tudi po kerubih in po palmah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 33, 'Enako je napravil za vhod v templjevo dvorano podboje iz oljkovega lesa, za četrtino zida;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 34, 'in dvoje duri iz cipresovine, dve durnici enih duri sta se pregibali, tudi dve durnici drugih duri sta se pregibali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 35, 'In izrezal je na njih kerube in palme in razvito cvetje in jih prevlekel z zlatom, prikladnim za izrezljaje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 36, 'In zgradil je notranje dvorišče: tri vrste obsekanih kamenov in vrsto cedrovih brun.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 37, 'V četrtem letu je bil položen temelj hiši Gospodovi, v mesecu Zivu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 6, 38, 'V enajstem letu pa, v mesecu Bulu, ki je osmi mesec, je bila hiša dokončana z vso opravo svojo in po vsej uredbi svoji. Tako jo je zidal sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 1, 'Svojo hišo pa je Salomon zidal trinajst let, dokler je ni vse dokončal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 2, 'Zidal je namreč hišo libanonskega gozda; njena dolgost je bila sto komolcev in širjava petdeset komolcev in višava trideset komolcev, na štirih vrstah cedrovih stebrov, s cedrovimi bruni na stebrih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 3, 'In pokrita je bila po vrhu s cedrovino nad sobami, ki so slonele na stebrih, petinštirideset, po petnajst v eni vrsti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 4, 'In bilo je tri vrste brun, in okno proti oknu po treh vrstah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 5, 'In vsa vrata in podboji so bili štirivoglati, s tramovjem, in okno proti oknu po treh vrstah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 6, 'In naredil je stebrnato dvorano, ki je bila petdeset komolcev dolga in trideset komolcev široka, pred njo pa vežo iz stebrov in prag pred njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 7, 'Tudi je naredil dvorano za prestol, kjer je sodil, sodno dvorano, in jo je obložil s cedrovino, od konca do kraja tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 8, 'Tudi hiša njegova, ki je v njej prebival, na drugem dvorišču proti dvorani, je bila enako delana. Tudi je naredil hišo za hčer Faraonovo (ki si jo je bil vzel Salomon za ženo), enako tej dvorani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 9, 'To vse je bilo napravljeno iz dragih kamenov, po merilu obsekanih, z žago rezanih po znotranji in zunanji strani, od temelja do vrha sten in od zunaj do velikega dvorišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 10, 'Podstave pa so bile iz dragih velikih kamenov, po deset in po osem komolcev velikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 11, 'In vrhu njih so bili dragi kameni, obsekani po voglomeru, in cedrovina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 12, 'Veliko dvorišče pa je imelo naokoli tri vrste obsekanih kamenov in vrsto cedrovih brun, enako kakor notranje dvorišče hiše Gospodove in hišna veža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 13, 'Poslal pa je kralj Salomon ter dal poklicati Hirama iz Tira,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 14, 'ki je bil sin žene vdove iz rodu Neftalijevega, in oče njegov je bil mož iz Tira, umeten bronar. Ta je bil poln modrosti, razuma in umetelnosti, izgotavljati vsakovrstna dela iz kovine. In prišel je h kralju Salomonu in izvršil vse delo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 15, 'Ulil je namreč tista dva stebra iz brona; vsak je bil osemnajst komolcev visok, in vrvica, dvanajst komolcev dolga, ju je vsakega ovijala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 16, 'In napravil je dva glaviča iz litega brona, da se posadita gori na stebra, in vsak glavič je bil pet komolcev visok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 17, 'Mrežasta pletenina in spletene verižice so bile ob glavičih vrhu stebrov, sedmero na enem in sedmero na drugem glaviču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 18, 'In naredil je margaranova jabolka po dve vrsti okoli stebrov na eni pletenini, da bi prestirala glaviča, ki sta bila vrhu stebrov, in enako je napravil tudi pri drugem glaviču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 19, 'In glaviča, ki sta bila vrhu stebrov, sta bila lilijastega dela kakor v veži, štiri komolce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 20, 'In glaviča sta bila tudi zgoraj na obeh stebrih blizu trupa, ki je bil poleg pletenine; in bilo je margaranovih jabolk dvesto v vrstah okoli na drugem glaviču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 21, 'In postavil je ta stebra pri veži ob templju in desnega je imenoval Jakina in levega Boaza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 22, 'In na vrhu stebrov je bilo lilijasto delo. In tako sta bila stebra dodelana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 23, 'Naredil je tudi ulito morje, deset komolcev od roba do roba, okroglo okoli, pet komolcev visoko; in vrvica tridesetih komolcev ga je kroginkrog ovijala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 24, 'Pod njegovim robom kroginkrog je šel nakit bučkastega sadja, po deset buček na komolec; v dveh vrstah so bile bučke, ulite sceloma z morjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 25, 'Stalo je na dvanajstih volih, ki so trije gledali proti severu in trije proti zahodu, trije proti jugu in trije proti vzhodu; in morje je bilo položeno na njih, vsi njih zadki pa so bili pod morjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 26, 'ln debelost njegova je bila eno dlan, in njegov rob je bil zaokrožen kakor rob keliha, kakor lilijevo cvetje; in držalo je dva tisoč batov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 27, 'Naredil je tudi deset stojal iz brona: vsako stojalo štiri komolce dolgo in štiri komolce široko in tri komolce visoko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 28, 'In stojala so bila tako narejena, da so imela ploščine med obrobnimi letvicami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 29, 'in na ploščinah med obrobnimi letvicami izrezljane leve, vole in kerube; in na letvicah zgoraj je bil podstavek; zdolaj pa pod levi in voli so bili viseči venci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 30, 'In vsako stojalo je imelo štiri bronasta kolesa in bronaste osi; in na štirih voglih njegovih so bila držala, za pod umivalnik so bila držala prilita, ob vsakem so bili venci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 31, 'In odprtina je bila na njem vrh pokrova, komolec visoka in okrogla, v obliki stojala, en komolec in pol poprek; in tudi ob odprtini so bili izrezljaji. Njegove ploščine pa so bile štirivoglate, ne okrogle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 32, 'In tista štiri kolesa so bila pod letvicami; in osi koles so bile utrjene na stojalu; vsako kolo je bilo en komolec in pol visoko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 33, 'In kolesa so bila narejena kakor vozna kolesa; njih osi in platišča in napere in pesta, vse je bilo ulito.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 34, 'Bila so tudi štiri držala na štirih spodnjih voglih vsakega stojala, ki so izhajala iz stojala samega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 35, 'In vrhu stojal je bil pol komolca zvišek, okroglast kroginkrog; in na zgornjem kraju stojala so bila njegova držala in njegove ploščine enakega dela ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 36, 'In vdolbel je na deske njegovih držal in na njegove ploščine kerube, leve in palme, kolikor je bilo prostora na vsaki, in vence kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 37, 'Na ta način je naredil tistih deset stojal: vsa so bila enega zlitka, ene mere in ene oblike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 38, 'In naredil je deset bronastih umivalnikov, štirideset batov je držal eden in vsak je bil štiri komolce širok, in na vsakem tistih desetih stojal je bil po en umivalnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 39, 'Postavil pa je pet stojal na desno in pet na levo stran hiše; a morje je postavil na desno stran hiše ob vzhodu, proti jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 40, 'In Hiram je naredil lonce in lopate in čaše. Tako je dokončal Hiram vse delo, ki ga je delal za kralja Salomona v hiši Gospodovi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 41, 'dva stebra in dva vrčasta glaviča, ki sta bila vrhu stebrov; in dve mrežasti pletenini, ki sta bili v prestrtje obema vrčastima glavičema na vrhu stebrov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 42, 'in štiristo margaranovih jabolk k dvema pleteninama: po dve vrsti margaranov za vsako pletenino, v prestrtje obema vrčastima glavičema na vrhu stebrov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 43, 'in desetero stojal in deset umivalnikov na stojalih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 44, 'morje eno in dvanajst volov pod morjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 45, 'in lonce in lopate in čaše. In vse te priprave, ki jih je delal Hiram za kralja Salomona v hiši Gospodovi, so bile iz zlikane bronovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 46, 'V Jordanski dolini jih je dal kralj zliti, v ilovnati zemlji med Sukotom in Zaretanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 47, 'In Salomon je pustil vse te posode nepretehtane, zaradi prevelike množine niso mogli dognati teže bronovini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 48, 'In naredil je Salomon vse tiste posode, ki so bile v hiši Gospodovi: zlati oltar in zlato mizo, na kateri so bili kruhi obličja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 49, 'in svečnike, pet po desni in pet po levi strani pred govoriščem, iz prečiščenega zlata, in cvetlice, svetilnice in utrinjače iz zlata;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 50, 'in vrče, usekalnike, čaše, torila, kadilnice iz prečiščenega zlata, tudi tečaje za duri notranje hiše, Najsvetejšega, in za duri templjeve dvorane, iz zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 7, 51, 'In tako je bilo vse delo dokončano, ki ga je delal kralj Salomon v hiši Gospodovi. In Salomon je znesel tja reči, ki jih je posvetil David, oče njegov, srebro in zlato in posode, in zložil jih je v zakladih hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 1, 'Tedaj je zbral kralj Salomon k sebi v Jeruzalem starejšine Izraelove in vse poglavarje rodov, kneze očetovinam sinov Izraelovih, da prineso skrinjo zaveze Gospodove gori iz mesta Davidovega, to je Sion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 2, 'In vsi možje so se zbrali h kralju Salomonu v mesecu Etanimu, to je sedmi mesec, ob prazniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 3, 'In pridejo vsi starejšine Izraelovi, in duhovniki vzdignejo skrinjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 4, 'in neso gori skrinjo Gospodovo in shodni šator in vse svete posode, ki so bile v šatoru; duhovniki in leviti so jih prinesli gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 5, 'In kralj Salomon in vsa občina Izraelova, kar se jih je zbralo pri njem, so ž njim bili pred skrinjo in so darovali drobnice in govedi toliko, da se ni računila, ne štela zaradi množine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 6, 'In duhovniki prineso skrinjo zaveze Gospodove na njeno mesto, v govorišče hiše, v Najsvetejše, pod peruti kerubov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 7, 'zakaj keruba sta razprostirala peruti nad mestom skrinje, in keruba sta pokrivala skrinjo in njena droga odzgoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 8, 'Droga pa sta bila toliko dolga, da sta se njuna konca videla iz svetišča pred govoriščem, ali zunaj ju ni bilo videti; in ondi sta do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 9, 'Ničesar ni bilo v skrinji razen dveh kamenenih desek, ki ju je vanjo vložil Mojzes na Horebu, kjer je Gospod sklenil zavezo s sinovi Izraelovimi, ko so bili šli iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 10, 'In ko so šli duhovniki iz svetišča, je oblak napolnil hišo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 11, 'da niso mogli duhovniki stati, da opravljajo službo, spričo oblaka; kajti slava Gospodova je napolnila hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 12, 'Tedaj reče Salomon: Jehova je rekel, da bo prebival v mrakoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 13, 'Zidal in dozidal sem ti hišo v prebivališče, stan tebi za sedež na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 14, 'In kralj obrne obličje in blagoslovi ves zbor Izraelov; in ves zbor Izraelov je stal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 15, 'In reče: Hvaljen bodi Gospod, Bog Izraelov, ki je obljubil z usti svojimi očetu mojemu Davidu in z roko svojo to izpolnil, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 16, 'Od dne, ko sem odpeljal ljudstvo svoje Izraela iz Egipta, nisem izvolil nobenega mesta iz vseh rodov Izraelovih, da zgradi hišo, ki bi v njej prebivalo moje ime; ali izvolil sem Davida, da bodi nad mojim ljudstvom Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 17, 'Bilo je res na srcu Davidu, očetu mojemu, da sezida hišo imenu Gospoda, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 18, 'Toda Gospod je dejal očetu mojemu Davidu: Ker ti je bilo na srcu sezidati hišo mojemu imenu, si dobro storil, da si to imel v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 19, 'Ali ti mi ne boš zidal hiše, marveč sin tvoj, ki pride iz ledja tvojega, ta bo zgradil hišo mojemu imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 20, 'In Gospod je vzdržal besedo svojo, ki jo je bil govoril, in jaz sem nastopil na očeta svojega Davida mesto in sem sedel na prestol Izraelov, kakor je bil govoril Gospod, in zgradil sem hišo imenu Jehove, Boga Izraelovega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 21, 'in tam sem pripravil mesto za skrinjo, ki je v njej zaveza Gospodova, katero je sklenil z očeti našimi, ko jih je peljal iz Egiptovske dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 22, 'Nato stopi Salomon pred oltar Gospodov vpričo vsega zbora Izraelovega in razprostre roke proti nebu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 23, 'in reče: O Gospod, Bog Izraelov, tebi ni enakega Boga v nebesih gori in na zemlji doli, ki hraniš zavezo in milost hlapcem svojim, kateri hodijo pred obličjem tvojim z vsem srcem svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 24, 'ki si ohranil hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil; z usti svojimi si govoril in z roko svojo si to izpolnil, kakor se danes vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 25, 'In sedaj, Gospod, Bog Izraelov, ohrani hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil, govoreč: Ne bo ti zmanjkalo moža pred obličjem mojim, ki bo sedel na prestolu Izraelovem, samo če pazijo sinovi tvoji na svojo pot, da hodijo pred menoj, kakor si ti hodil pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 26, 'Sedaj torej, o Bog Izraelov, naj se, prosim, uresniči beseda tvoja, ki si jo govoril hlapcu svojemu Davidu, očetu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 27, 'Toda v resnici prebiva li Bog na zemlji? Glej, nebo in vseh nebes nebesa te ne morejo obseči, koliko manj ta hiša, ki sem jo sezidal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 28, 'Vendar se obrni k molitvi svojega hlapca in k njegovi prošnji, Gospod, moj Bog, da poslušaš glas in molitev, ki jo moli hlapec tvoj pred teboj danes:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 29, 'da bodo oči tvoje odprte proti tej hiši po dne in po noči, proti mestu, ki si o njem rekel: Moje ime bode ondi, da uslišiš molitev, ki jo bo molil hlapec tvoj na tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 30, 'Poslušaj torej prošnjo hlapca svojega in ljudstva svojega Izraela, ki jo bodo prosili obrnjeni proti temu mestu, poslušaj na mestu prebivanja svojega, v nebesih, poslušaj in odpuščaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 31, 'Ako se kdo pregreši zoper bližnjega svojega in se mu naloži prisega, da se zaveže s prisego, in prisega pride pred tvoj oltar v tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 32, 'ti poslušaj v nebesih in stóri, da se pravica zgodi hlapcem tvojim, s tem, da obsodiš krivičnega ter mu pripraviš pot njegovo nad glavo, pravičnega pa opravičiš ter mu poplačaš po pravičnosti njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 33, 'Kadar bo sovražnik porazil pred seboj ljudstvo tvoje, Izraela, ker so grešili zoper tebe, pa se zopet obrnejo k tebi in pripoznajo tvoje ime in bodo molili in ponižno prosili tebe v tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 34, 'ti poslušaj v nebesih in odpusti greh ljudstva svojega Izraela ter jih zopet pripelji v deželo, ki si jo dal njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 35, 'Kadar se zapre nebo, da ni dežja, ker so grešili zoper tebe, pa bodo molili obrnjeni proti temu mestu in pripoznavali tvoje ime, in se obrnejo od grehov svojih, ker si jih ponižal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 36, 'ti poslušaj v nebesih ter odpusti greh hlapcev svojih in ljudstva svojega Izraela, da jih učiš dobro pot, po kateri naj hodijo, in pošlješ dežja na deželo svojo, ki si jo dal v dediščino ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 37, 'Kadar bode v deželi lakota, kadar pride kuga ali snet ali rja, kobilice ali gosenice; ko jih bo sovražnik oblegal v deželi njih mest; katerakoli bode nadloga, katerakoli bolezen:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 38, 'kakršnokoli molitev in prošnjo opravlja kdo izmed vsega tvojega ljudstva Izraela, kadar spoznajo vsakteri srca svojega kazen in razprostro roke proti tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 39, 'ti poslušaj v nebesih, v mestu prebivanja svojega, in odpusti ter stóri, da daš vsakemu, kakor je živel, ker poznaš njegovo srce (zakaj ti, edini ti poznaš vseh človeških otrok srca),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 40, 'da bi se te bali vse svoje žive dni v deželi, ki si jo dal očetom našim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 41, 'Ako pa tudi inostranec, ki ni iz ljudstva tvojega Izraela, pride iz daljne dežele zaradi imena tvojega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 42, '(slišali bodo namreč o tvojem velikem imenu in o mogočni roki tvoji in o iztegnjeni rami tvoji), ko torej pride in bo molil proti tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 43, 'ti poslušaj v nebesih, v mestu prebivanja svojega, in stori vse, za kar te kliče inostranec; da spoznajo vsi narodi na zemlji tvoje ime, da bi se te bali kakor ljudstvo tvoje Izrael ter da se prepričajo, da se imenuje ta hiša, ki sem jo zgradil, po imenu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 44, 'Kadar pojde ljudstvo tvoje na vojsko zoper sovražnika svojega, po kateremkoli potu jih pošlješ, in bodo molili h Gospodu, ozirajoč se proti mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 45, 'ti poslušaj v nebesih njih molitev in prošnjo ter se potegni za njih pravdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 46, 'Kadar se pregreše zoper tebe (kajti ni človeka, ki ne greši) in se razsrdiš ter jih izročiš sovražniku, da jih ujete peljejo v sovražnikov deželo, daleč ali blizu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 47, 'pa se v svojem srcu premislijo v deželi, kamor so bili ujeti odpeljani, in se izpreobrnejo in te ponižno prosijo v deželi tistih, ki so jih ujete odvedli, govoreč: Grešili smo, krivično smo delali, brezbožno smo ravnali!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 48, 'ako se k tebi povrnejo iz vsega srca svojega in iz vse duše svoje v deželi sovražnikov svojih, ki so jih ujete odpeljali, in bodo molili k tebi, ozirajoč se proti deželi svoji, ki si jo dal njih očetom, proti mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 49, 'ti poslušaj njih molitev in prošnjo v nebesih, v mestu prebivanja svojega, ter se potegni za njih pravdo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 50, 'in odpusti ljudstvu svojemu, kar so grešili zoper tebe, in vse prestopke, s katerimi so prestopili zoper tebe, ter jim daj milost pred temi, ki jih imajo ujete, da se jih usmilijo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 51, 'kajti tvoje ljudstvo so in tvoja dediščina, ki si jo peljal iz Egipta, iz peči železne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 52, 'Tako naj bodo oči tvoje odprte proti prošnji hlapca tvojega in prošnji ljudstva tvojega Izraela, da jih slišiš, kadarkoli kličejo k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 53, 'Zakaj ti si jih odločil sebi v dediščino izmed vseh ljudstev zemlje, kakor si govoril po Mojzesu, hlapcu svojem, ko si peljal očete naše iz Egipta, o Gospod Jehova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 54, 'In ko je Salomon izmolil in končal vso to molitev in prošnjo do Gospoda, vstane izpred oltarja Gospodovega, kjer je pripognil kolena in iztegnil roke proti nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 55, 'In pristopi in blagoslovi ves zbor Izraelov z glasom velikim, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 56, 'Hvaljen bodi Gospod, ki je dal pokoj svojemu ljudstvu Izraelu po vsem, kakor je govoril! Ni izginila ena beseda izmed njegovih dobrih obljub, ki jih je govoril po Mojzesu, hlapcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 57, 'Gospod, naš Bog, bodi z nami, kakor je bil z očeti našimi, ne zapusti nas in ne zavrzi nas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 58, 'da nagne srca naša k sebi, da bi hodili po vseh potih njegovih in izpolnjevali zapovedi njegove, postave in sodbe njegove, ki jih je zapovedal očetom našim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 59, 'Te moje besede pa, s katerimi sem prosil pred Gospodom, naj bodo blizu Gospoda, našega Boga, po dne in po noči, da se poteguje za pravdo hlapca svojega in za pravdo svojega ljudstva Izraela, kolikor je vsak dan treba:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 60, 'da bi spoznala vsa ljudstva na zemlji, da Gospod je Bog, nobenega ni drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 61, 'Vaše srce pa bodi popolnoma vdano Gospodu, Bogu našemu, da živite po postavah njegovih in izpolnjujete zapovedi njegove, kakor je danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 62, 'In kralj in ves Izrael ž njim je daroval daritve pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 63, 'In Salomon je zaklal mirovnih daritev, ki jih je poklonil Gospodu, dvaindvajset tisoč goved in stoindvajset tisoč glav drobnice. Tako so posvečevali kralj in vsi sinovi Izraelovi hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 64, 'Tisti dan je kralj posvetil sredino dvorišča, ki je pred hišo Gospodovo; zakaj tam je daroval žgalne in jedilne žrtve in tolstino mirovnih daritev, ker bronasti oltar, ki je bil pred Gospodom, je bil premajhen, da bi prejel žgalne in jedilne žrtve in tolstino mirovnih daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 65, 'In Salomon in ves Izrael ž njim, velik zbor, ki se je sešel od vhoda v Hamat tja do Egiptovskega potoka, je praznoval tisti čas praznik pred Gospodom, našim Bogom, sedem dni in zopet sedem dni, to je štirinajst dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 8, 66, 'Osmi dan je razpustil ljudstvo; in oni so, blagoslovivši kralja, odšli v šatore svoje veseli in dobre volje zaradi vseh dobrot, ki jih je storil Gospod svojemu hlapcu Davidu in svojemu ljudstvu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 1, 'In ko je končal Salomon zidanje hiše Gospodove in kraljeve hiše in vse, kar je želel napraviti, kar ga je veselilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 2, 'se mu prikaže Gospod v drugič, kakor se mu je bil prikazal v Gibeonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 3, 'In Gospod mu reče: Uslišal sem molitev in prošnjo tvojo, ki si jo molil pred menoj. Posvetil sem to hišo, ki si jo zgradil, da tam postavim ime svoje za večno, in moje oči in srce moje bodo tam vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 4, 'Tebi pa, ako boš hodil pred menoj, kakor je hodil David, oče tvoj, s popolnoma vdanim srcem in v poštenosti, da boš delal vse, kakor sem ti zapovedal, izpolnjujoč moje postave in sodbe moje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 5, 'tebi utrdim kraljestva tvojega prestol nad Izraelom za večno, kakor sem obljubil očetu tvojemu Davidu, govoreč: Ne bo ti zmanjkalo moža na prestolu Izraelovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 6, 'Ako se pa odvrnete, da ne bi šli za menoj, vi in otroci vaši, in ne boste izpolnjevali zapovedi mojih, postav mojih, ki sem vam jih predpisal, temuč pojdete in boste služili drugim bogovom ter jih molili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 7, 'tedaj potrebim Izraela s površja zemlje, ki sem jim jo dal, in to hišo, ki sem jo posvetil imenu svojemu, vržem izpred svojega obličja, in Izrael bode v pregovor in v zabavljico med vsemi ljudstvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 8, 'In ob tej hiši, bodisi še tako visoka, se bo vsak mimogredoči zavzel in žvižgal; in poreko: Zakaj je Gospod tako storil tej deželi in tej hiši?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 9, 'In odgovore: Zato ker so zapustili Gospoda, Boga svojega, ki je izpeljal njih očete iz dežele Egiptovske, in se oklenili drugih bogov ter jih molili in jim služili. Zato je Gospod nadnje pripravil vso to nesrečo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 10, 'In zgodi se ob koncu dvajsetih let, v katerih je Salomon zidal tisti dve hiši, hišo Gospodovo in kraljevo hišo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 11, 'ki je zanju Hiram, kralj tirski, oskrboval Salomona s cedrovino in cipresovino in z zlatom, kolikor je le želel: tedaj da kralj Salomon Hiramu dvajset mest v Galilejski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 12, 'Nato se odpravi Hiram iz Tira, da ogleda mesta, ki mu jih je dal Salomon; a niso mu bila pogodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 13, 'In reče: Kakšna so ta mesta, ki si mi jih dal, brat moj? In jih je imenoval deželo Kabul do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 14, 'Poslal pa je Hiram kralju stoindvajset talentov zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 15, 'In to je razlog roboti, ki jo je nabral kralj Salomon: da bi zidal hišo Gospodovo in hišo svojo in Milo in obzidje jeruzalemsko in Hazor in Megido in Gezer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 16, 'Faraon namreč, egiptovski kralj, je bil prišel gori in dobil Gezer ter ga požgal z ognjem in pomoril Kanaance, ki so prebivali v mestu, ter ga je dal v delež hčeri svoji, ženi Salomonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 17, 'Salomon je torej sezidal Gezer in Bethoron Dolenji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 18, 'in Baalat in Tadmor v puščavi, v deželi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 19, 'in mesta za skladišča Salomonova in mesta za vozove in mesta za konjike njegove in kar je želel Salomon sezidati sebi v veselje v Jeruzalemu in na Libanonu in po vsej deželi gospostva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 20, 'Kar jih je pa preostalo od Amorejcev, Hetejcev, Ferizejcev, Hevejcev in Jebusejcev, ki niso bili iz sinov Izraelovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 21, 'iz njih otrok namreč, ki so po njih ostali v deželi in jih niso dočista mogli iztrebiti sinovi Izraelovi, iz teh je Salomon nabral robotnikov, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 22, 'A izmed sinov Izraelovih ni storil nikogar za sužnja, ampak bili so vojaki in služabniki njemu in vojvode njegovi in poveljniki in načelniki nad njegovimi vozovi in konjiki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 23, 'Višjih oblastnikov, ki so nadzorovali delo Salomonovo, je bilo petsto in petdeset, ki so gospodovali ljudstvu, opravljajočemu delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 24, 'Ko pa se je hči Faraonova preselila iz mesta Davidovega v hišo svojo, ki ji jo je zgradil, tedaj je sezidal Milo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 25, 'In trikrat na leto je daroval Salomon žgalne in mirovne žrtve na oltarju, ki ga je bil zgradil Gospodu, in je dal žgati kadilo na onem, ki je bil pred Gospodom. In tako je dokončal hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 26, 'In kralj Salomon je napravil ladje v Ezion-geberju, ki je pri Elotu, na bregu Rdečega morja, v Edomski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 27, 'In Hiram je poslal po ladjah hlapce svoje, brodarje, ki so bili zvedeni na morju, s hlapci Salomonovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 9, 28, 'In dospeli so v Ofir in tam naložili zlata štiristo in dvajset talentov ter ga pripeljali kralju Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 1, 'Ko pa je slišala kraljica v Sabi Salomonov sloves zaradi imena Gospodovega, ga je prišla izkušat z ugankami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 2, 'Pride torej v Jeruzalem z jako velikim spremstvom, z velblodi, ki so nesli dišave in zlata jako mnogo in drage kamene. In ko je dospela k Salomonu, je govorila ž njim o vsem, kar ji je bilo na srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 3, 'In Salomon ji je razložil vse, kar ga je vprašala; ni bilo besede, ki bi bila skrita kralju, da bi ji ne bil povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 4, 'Ko pa je čula kraljica iz Sabe vso modrost Salomonovo in videla hišo, ki jo je zgradil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 5, 'in jed na mizi njegovi in prebivališča hlapcev njegovih in strežbo služabnikov njegovih ter njih obleko in njegove točaje in njegove stopnice, po katerih je hodil gori v hišo Gospodovo, ji je od strmenja sapa zastala;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 6, 'in reče kralju: Resnična je bila beseda, ki sem jo slišala v deželi svoji o tvojih stvareh in o tvoji modrosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 7, 'Toda nisem hotela verjeti, dokler nisem prišla in sem s svojimi očmi videla vse. In glej, še polovice mi niso povedali: več imaš modrosti in dobrot, nego je bila govorica, ki sem jo slišala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 8, 'Blagor tvojim ljudem in blagor tem tvojim hlapcem, ki vedno stoje pred teboj, ki poslušajo modrost tvojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 9, 'Hvaljen bodi Gospod, Bog tvoj, ki ti je bil blagovoljen, da te je posadil na prestol Izraelov! Ker Gospod ljubi Izraela vekomaj, zato te je postavil za kralja, da izvršuješ sodbo in pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 10, 'In dala je kralju stoindvajset talentov zlata in silno veliko dišav in dragih kamenov; nikdar več ni prišla tolika množina dišav kakor ta, ki jo je dala kraljica iz Sabe Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 11, 'Vrhutega so pripeljale Hiramove ladje, ki so nosile zlato iz Ofirja, silno veliko sandalovine in dragih kamenov iz Ofirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 12, 'In kralj je dal napraviti iz sandalovine opirala za hišo Gospodovo in za kraljevo hišo, tudi harfe in citre pevcem. Take sandalovine ni prišlo več, tudi je ni bilo videti do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 13, 'In kralj Salomon je dal kraljici iz Sabe vse, kar je želela in kar je prosila, razen tega, kar ji je poklonil po kraljevi darežljivosti. In vrne se ter odide v deželo svojo, ona in njeni hlapci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 14, 'Teža zlata pa, ki se je prinašalo Salomonu na leto, je bila šeststo šestdeset in šest talentov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 15, 'razen tega, kar ga je prišlo s popotniki in s trgovci in od vseh kraljev arabskih in od namestnikov po deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 16, 'In kralj Salomon je dal napraviti dvesto ščitov iz tolkljanega zlata: šeststo seklov zlata je porabil za en ščit;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 17, 'in tristo malih ščitov iz tolkljanega zlata, po tri mine zlata je šlo na en ščit. In kralj jih je zložil v hiši libanonskega gozda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 18, 'Dalje je na pravil kralj velik prestol iz slonovih kosti in ga je prevlekel z najboljšim zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 19, 'Šestero stopnic je držalo do prestola, in vrh prestolov je bil okrogel odzadaj, in na obeh straneh pri sedežu sta bili naslonili, in dva leva sta stala ob naslonilih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 20, 'In dvanajst levov je stalo na tej in na oni strani ob šesterih stopnicah; kaj takega ni bilo videti v nobenem kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 21, 'Pa tudi vse posode, iz katerih je pil kralj Salomon, so bile zlate, in vsa oprava v hiši libanonskega gozda je bila iz čistega zlata, nič ni bilo srebrno, kajti srebra niso sploh cenili v Salomonovih dnevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 22, 'Kralj je imel tarsko brodovje na morju z brodovjem Hiramovim; po enkrat na tri leta so dospevale ladje tarske, noseč zlata in srebra, slonovih kosti, opic in pavov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 23, 'In kralj Salomon je nadkriljeval vse kralje zemlje v bogastvu in v modrosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 24, 'In vsa zemlja je hrepenela po obličju Salomonovem, da bi slišali modrost njegovo, ki mu jo je dal Bog v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 25, 'In prinašali so vsakdo svoje darilo: posode srebrne in posode zlate, oblačila in orožje in dišave, konje in mezge, vsako leto, kar je bilo pristojno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 26, 'In Salomon je nabral voz in konjikov in je imel tisoč in štiristo voz in dvanajst tisoč konjikov, ki jih je razstavil po voznih mestih in pri kralju v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 27, 'In kralj je storil, da je bilo v Jeruzalemu toliko srebra kakor kamenov, in ceder je napravil toliko kakor smokovega drevja, ki raste v ravnini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 28, 'In konje je Salomon dobival iz Egipta; družba kraljevih kupcev jih je privajala trume za kupno ceno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 10, 29, 'Voz pa je prišel gori, odpeljan iz Egipta, po šeststo seklov srebra, in konj po sto in petdeset. Tako so jih dobivali tudi vsi kralji Hetejcev in sirski kralji po njih roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 1, 'A kralj Salomon je ljubil mnogo inostranskih žen poleg hčere Faraonove: Moabke, Amonke, Edomke, Sidonke in Hetejke;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 2, 'iz narodov, o katerih je Gospod rekel sinovom Izraelovim: Ne hodite mednje, tudi oni naj ne hodijo med vas, kajti gotovo vam naklonijo srce, da pojdete za njih bogovi. Na te se je navezal Salomon v ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 3, 'In imel je sedemsto žen kneginj in tristo priležnic; in žene so odvrnile srce njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 4, 'In ko je bil Salomon star, so mu njegove žene naklonile srce, da je šel za drugimi bogovi; in ni bilo srce njegovo popolnoma vdano Gospodu, Bogu njegovemu, kakor je bilo srce njegovega očeta Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 5, 'In Salomon je hodil za Astoreto, boginjo Sidoncev, in za Milkomom, gnusobo Amoncev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 6, 'In Salomon je počenjal, kar je bilo hudo v očeh Gospodovih, ter ni hodil popolnoma za Gospodom kakor njegov oče David.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 7, 'Takrat je sezidal Salomon višavo Kamosu, gnusobi Moabcev, na gori, ki je pred Jeruzalemom, in Molohu, gnusobi sinov Amonovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 8, 'In tako je storil za vse svoje žene tujke, ki so žgale kadilo in darovale svojim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 9, 'In Gospod se je razsrdil nad Salomonom, ker je odvrnil srce svoje od Gospoda, Boga Izraelovega, ki se mu je bil prikazal dvakrat');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 10, 'in mu je prav o tem zapovedal, naj ne hodi za drugimi bogovi; a on ni izpolnil, kar mu je bil Gospod zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 11, 'Zato je dejal Gospod Salomonu: Ker je bilo to pri tebi ter nisi ohranil zaveze moje in postav mojih, ki sem ti jih zapovedal, gotovo ti odtrgam kraljestvo in ga dam hlapcu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 12, 'Ali v tvojih dneh ne storim tega zaradi Davida, očeta tvojega; sinu tvojemu ga odtrgam iz roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 13, 'Vendar pa nočem vsega kraljestva odtrgati, ali en rod dam tvojemu sinu, zaradi Davida, služabnika svojega, in zaradi Jeruzalema, ki sem ga izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 14, 'Obudil pa je Gospod nasprotnika Salomonu, Hadada Edomca; on je bil iz kraljevega rodu v Edomu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 15, 'Takrat namreč, ko je bil David v Edomu in je Joab, poveljnik vojske, šel gori pokopat pobite, in ko je bil pomoril vse moštvo v Edomu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 16, '(kajti Joab in ves Izrael je ostal šest mesecev ondi, dokler ni pokončal vsakega moškega v Edomu),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 17, 'je zbežal Hadad, on in nekateri Edomci iz hlapcev očeta njegovega ž njim, da pojdejo v Egipt. Hadad pa je bil še majhen deček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 18, 'In vstali so iz Madianske in prišli v Paran, in vzeli so s seboj može iz Parana in so prišli v Egipt k Faraonu, kralju egiptovskemu. Ta je dal Hadadu hišo in mu določil živež ter mu odkazal zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 19, 'In Hadad je našel veliko milost v očeh Faraonovih, tako da mu je dal za ženo sestro žene svoje, kraljice Tahpenese sestro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 20, 'In sestra Tahpenesina mu je rodila sina Genubata, in Tahpenes ga je vzgajala v hiši Faraonovi; Genubat je torej bil v Faraonovi hiši med sinovi Faraonovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 21, 'In ko je slišal Hadad v Egiptu, da je David zaspal z očeti svojimi ter da je Joab, poveljnik vojske, mrtev, reče Faraonu: Odpusti me, da grem v svojo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 22, 'Tedaj ga vpraša Faraon: Česa ti manjka pri meni, da hočeš iti v deželo svojo? Odgovori: Ničesar, pa me vsekakor pusti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 23, 'In Bog mu je obudil drugega nasprotnika, Rezona, sina Eljadovega, ki je bil pobegnil gospodarju svojemu Hadadezerju, kralju v Zobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 24, 'In zbral je k sebi mož in je postal načelnik trume, ko je David udaril Zobljane; in šli so v Damask in v njem prebivali in je zakraljeval v Damasku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 25, 'In bil je nasprotnik Izraelu vse dni Salomonove; in to je bilo nad zlo, ki mu ga je napravljal Hadad; in gnusilo se mu je do Izraela, in zakraljeval je v Siriji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 26, 'Tudi Jeroboam, sin Nebatov, Efraimec iz Zerede, hlapec Salomonov, (čigar mati se je imenovala Zerua, in bila je vdova), je vzdignil roko zoper kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 27, 'In to je vzrok, zakaj je vzdignil roko zoper kralja: Salomon je zidal Milo in je zadelal razpoklino mesta Davida, očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 28, 'Tisti mož pa, Jeroboam, je bil vrl junak, in ko je Salomon videl mladeniča, da je marljiv, ga je postavil nad vso tlako Jožefove hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 29, 'Zgodi se pa v tistem času, ko je Jeroboam šel iz Jeruzalema, da ga zaloti na potu prorok Ahija Silonski; ogrnil se je pa bil z novim oblačilom, in bila sta sama na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 30, 'In prime Ahija novo oblačilo, ki ga je imel na sebi, ter ga raztrga na dvanajst kosov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 31, 'in veli Jeroboamu: Vzemi si deset kosov! kajti tako pravi Gospod, Bog Izraelov: Glej, hočem odtrgati kraljestvo iz roke Salomonove in tebi dati deset rodov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 32, '(en rod pa naj mu ostane zaradi hlapca mojega Davida in zaradi Jeruzalema, mesta, ki sem ga izvolil izmed vseh rodov Izraelovih)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 33, 'zato, ker so me zapustili ter se priklanjali Astoreti, boginji Sidoncev, Kamosu, bogu Moabcev, in Milkomu, bogu sinov Amonovih, in niso hodili po mojih potih, da se ravnajo po tem, kar je prav v mojih očeh, in po mojih postavah in sodbah kakor David, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 34, 'Nočem mu pa vzeti vsega kraljestva iz roke, ampak postavim ga za kneza vse dni življenja njegovega zaradi Davida, hlapca svojega, ki sem ga izvolil, ki se je ravnal po zapovedih in postavah mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 35, 'Vzamem pa kraljestvo iz roke sinu njegovega ter ga dam tebi, namreč desetero rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 36, 'A sinu njegovemu dam en rod, da bo imel David, hlapec moj, svetilo vselej pred obličjem mojim v Jeruzalemu, v mestu, ki sem si ga izvolil, da ondi postavim ime svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 37, 'Tebe torej vzamem, in gospodoval boš vsemu, kakor želi duša tvoja, in bodeš kralj nad Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 38, 'In ako boš poslušal vse, kar ti zapovedujem, in hodil po mojih potih in delal, kar je prav v mojih očeh, izpolnjujoč moje postave in zapovedi, kakor je delal hlapec moj David: hočem biti s teboj in ti postaviti hišo stanovitno, kakor sem jo postavil Davidu, in ti dati Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 39, 'In zaradi tega bom poniževal seme Davidovo, a ne vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 40, 'Salomon pa je gledal, kako bi usmrtil Jeroboama, ali Jeroboam vstane in zbeži v Egipt k Sisaku, kralju egiptovskemu, in bil je v Egiptu do smrti Salomonove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 41, 'O drugih pa rečeh Salomonovih in o vsem, kar je storil, in o modrosti njegovi, ni li zapisano v knjigi dejanj Salomonovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 42, 'Časa pa, ki je v njem Salomon kraljeval v Jeruzalemu vsemu Izraelu, je bilo štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 11, 43, 'In legel je Salomon k očetom svojim in bil je pokopan v mestu Davida, očeta svojega; in Roboam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 1, 'In Roboam je šel v Sihem, kajti ves Izrael je prišel v Sihem, da ga postavijo za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 2, 'In slišal je o tem Jeroboam, sin Nebatov (bil pa je še v Egiptu, kamor je bil zbežal izpred kralja Salomona; prebival je torej Jeroboam v Egiptu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 3, 'in poslali so ter ga poklicali). In pride Jeroboam in ves zbor Izraelov in govoré k Roboamu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 4, 'Oče tvoj nam je preobtežal jarem; sedaj torej nam polajšaj pretrdo službo očeta svojega in težki jarem, ki nam ga je naložil, in bomo ti služili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 5, 'In on jim reče: Odidite še do tretjega dne, potem se vrnite k meni. In ljudstvo odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 6, 'In kralj Roboam se je posvetoval s starci, ki so stali v službi pri njegovem očetu Salomonu, ko je še živel, rekoč: Kako mi svetujete, da naj odgovorim temu ljudstvu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 7, 'In ga ogovore in reko: Ako se danes postrežljivega izkažeš temu ljudstvu in mu storiš po volji in če jih uslišiš in jim govoriš prijazne besede, ti bodo hlapci vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 8, 'Ali on je zavrgel svet starcev, ki so mu ga dali, in se je posvetoval z mladeniči, ki so vzrasli ž njim in so stali v službi pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 9, 'In jih vpraša: Kaj svetujete, da naj odgovorimo temu ljudstvu, ki so govorili k meni, rekoč: Polajšaj jarem, ki nam ga je naložil oče tvoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 10, 'Tedaj mu reko mladiči, ki so ž njim vzrasli: Ljudstvu, ki ti je dejalo: Oče tvoj nam je preobtežal jarem, ti pa nam ga polajšaj! takole odgovóri: Moj mali prst je večji nego mojega očeta ledje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 11, 'Sedaj torej: oče moj vas je obremenil s težkim jarmom, a jaz še pridenem jarmu vašemu; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 12, 'Tedaj pride Jeroboam in vse ljudstvo k Roboamu tretji dan, kakor je kralj velel, rekoč: Pridite k meni zopet tretji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 13, 'In kralj je odgovoril ljudstvu trdo in zapustil svet starcev, ki so mu ga bili dali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 14, 'ter jim je govoril po svetu mladičev takole: Oče moj vam je naložil težek jarem, jaz pa še pridenem jarmu vašemu; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 15, 'Kralj torej ni ugodil ljudstvu, kajti Gospod je tako ravnal, da potrdi besedo svojo, ki jo je govoril Gospod po Ahiju Silonskem Jeroboamu, sinu Nebatovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 16, 'In ko je videl ves Izrael, da jim kralj ni ugodil, odgovori ljudstvo kralju in reče: Kakšen delež nam je v Davidu? in dediščine nimamo v sinu Jesejevem. K svojim šatorom, o Izrael! Sedaj glej hišo svojo, David! In Izrael se je razšel v šatore svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 17, 'Samo sinovom Izraelovim, ki so prebivali v Judovih mestih, je kraljeval Roboam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 18, 'Nato pošlje kralj Roboam Adorama, ki je bil nad roboto, a ves Izrael ga je lučal s kamenjem, da je umrl. In pohiti kralj Roboam in stopi na svoj voz, da pobegne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 19, 'Tako je odstopil Izrael od hiše Davidove do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 20, 'In ko zasliši ves Izrael, da se je vrnil Jeroboam iz Egipta, pošljejo ga poklicat v ljudski zbor, ter ga postavijo za kralja nad vsem Izraelom. Nihče ni šel za hišo Davidovo nego Judov rod edini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 21, 'Ko pa dospe Roboam v Jeruzalem, zbere vso hišo Judovo in rod Benjaminov, sto in osemdeset tisoč izbranih vojščakov, da se bojujejo s hišo Izraelovo in zopet pridobe kraljestvo Roboamu, sinu Salomonovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 22, 'Pa pride beseda Božja Semaju, možu Božjemu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 23, 'Govóri Roboamu, sinu Salomonovemu, Judovemu kralju, in vsej hiši Judovi in Benjaminovi in drugemu ljudstvu, in véli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 24, 'Tako pravi Gospod: Ne hodite gori in ne bojujte se s svojimi brati, sinovi Izraelovimi; vrnite se vsak v hišo svojo, zakaj od mene je prišla ta reč. In slušali so besedo Gospodovo in se vrnili domov, kakor je velel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 25, 'Tedaj je Jeroboam sezidal Sihem na Efraimskem gorovju in prebival v njem; in odtod je šel dalje in sezidal Penuel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 26, 'Dejal je pa Jeroboam v srcu svojem: Kraljestvo bi se sedaj lahko povrnilo hiši Davidovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 27, 'Ako hodi to ljudstvo gori darovat žrtve v hiši Gospodovi v Jeruzalemu, se obrne srce tega ljudstva h gospodarju svojemu, k Roboamu, kralju Judovemu, in me bodo umorili ter se povrnili k Roboamu, kralju Judovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 28, 'Zato se je kralj posvetoval, ter naredi dve zlati teleti in jim veli: Preveč je za vas hoditi gori v Jeruzalem! Glej, to so bogovi tvoji, Izrael, ki so te pripeljali gori iz dežele Egiptovske!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 29, 'In postavi eno v Betel, eno pa v Dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 30, 'In ta reč je postala v greh, zakaj ljudstvo je hodilo molit pred tisto eno tele tja do Dana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 31, 'In napravil je hiše višav in postavil za duhovnike vsake vrste ljudi, ki niso bili izmed sinov Levijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 32, 'In določil je praznik v osmem mesecu, petnajsti dan meseca, po podobi praznika, ki je bil na Judovem, in je daroval na oltarju. Tako je storil v Betelu ter je daroval teletoma, ki ju je bil naredil; in namestil je v Betelu duhovnike višav, ki jih je napravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 12, 33, 'In stopil je gori k oltarju, ki ga je zgradil v Betelu, petnajsti dan osmega meseca, tistega meseca, ki si ga je izmislil v srcu svojem; in je napravil praznik sinovom Izraelovim ter je pristopil k oltarju zažigat kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 1, 'A glej, mož Božji pride z Judovega po besedi Gospodovi v Betel, in Jeroboam stoji pri oltarju, da zažge kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 2, 'In zakliče zoper oltar po besedi Gospodovi in reče: Oltar, oltar, tako pravi Gospod: Glej, sin se bo rodil hiši Davidovi, po imenu Josija, in na tebi bo daroval duhovnike višav, ki žgo kadilo na tebi, in človeške kosti bodo palili na tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 3, 'In dal je tisti dan znamenje, rekoč: To je znamenje, da je govoril Gospod: Glej, oltar se razpoči in pepel, ki je na njem, se razsuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 4, 'In ko zasliši kralj besedo moža Božjega, ki jo je vzkliknil zoper oltar v Betelu, iztegne Jeroboam roko svojo od oltarja pa veli: Primite ga! A roka njegova, ki jo je iztegnil zoper njega, je usehnila, da je ni mogel zopet potegniti k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 5, 'Oltar se je tudi razpočil in pepel se je razsul z oltarja natančno po znamenju, ki ga je bil dal mož Božji po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 6, 'In kralj izpregovori ter reče možu Božjemu: Poprosi, prosim, blagovoljnosti Gospoda, Boga svojega, in moli zame, da se mi zopet povrne roka moja. Nato zaprosi mož Božji blagovoljnosti Gospodove, in kralju se je roka povrnila in bila je zdrava kakor prej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 7, 'Tedaj ogovori kralj moža Božjega: Pojdi z mano domov in se pokrepčaj, in dam ti darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 8, 'A mož Božji reče kralju: Ko bi mi dal polovico hiše svoje, ne pojdem s teboj, ker nočem jesti kruha, ne piti vode na tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 9, 'Zakaj tako mi je zapovedano po besedi Gospodovi, ki mi je velela: Ne jej ondi kruha in ne pij vode, tudi se ne vračaj po potu, po katerem si šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 10, 'In odšel je po drugem potu, da se ne vrne po tistem potu, po katerem je prišel v Betel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 11, 'Neki star prorok pa je prebival v Betelu; k temu pridejo sinovi njegovi ter mu pripovedujejo vse, kar je storil mož Božji tisti dan v Betelu; tudi besede, ki jih je govoril kralju, povedo očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 12, 'In vpraša jih njih oče: Po katerem potu je odšel? In pokažejo mu sinovi njegovi pot, po katerem je odšel mož Božji, ki je bil prišel z Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 13, 'Nato veli sinovom svojim: Osedlajte mi osla! In ko so mu osedlali osla, je jezdeč na njem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 14, 'šel za možem Božjim ter ga je zalotil sedečega pod hrastom in mu reče: Si li ti mož Božji, ki je prišel z Judovega? Odgovori: Sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 15, 'Tedaj mu reče: Pojdi z mano domov in zaužij kruha!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 16, 'On pa reče: Ne smem se vrniti in s teboj iti, tudi nočem s teboj jesti kruha, ne piti vode na tem mestu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 17, 'zakaj bilo mi je rečeno po besedi Gospodovi: Ne jej ondi kruha in ne pij vode! po poti, po kateri si prišel, se zopet ne vračaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 18, 'Ta mu pa reče: Tudi jaz sem prorok kakor ti in angel mi je govoril po besedi Gospodovi, veleč: Pelji ga nazaj s seboj v hišo svojo, da užije kruha in pije vode. To pa se mu je zlagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 19, 'Vrne se torej ž njim, da zaužije kruha in se napije vode v hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 20, 'Ko sta pa sedela pri mizi, pride beseda Gospodova proroku, ki ga je nazaj pripeljal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 21, 'in zavpije proti možu Božjemu, ki je prišel z Judovega, rekoč: Tako pravi Gospod: Ker si bil nepokoren ustom Gospodovim in nisi izpolnil zapovedi, ki ti jo je zapovedal Gospod, Bog tvoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 22, 'temuč si se vrnil in jedel kruh in pil vodo na tem mestu, o katerem ti je velel: Ne jej ondi kruha in ne pij vode: zato ne pride truplo tvoje v očetov tvojih grob!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 23, 'In potem, ko je zaužil kruha in se napil, mu je osedlal osla, proroku, katerega je bil vrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 24, 'In ko je šel, naleti nanj lev na poti ter ga usmrti; in truplo njegovo je ležalo na poti in osel je stal pri njem, lev pa je tudi stal poleg trupla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 25, 'In glej, ljudje so šli mimo in videli truplo na tleh na poti in leva stoječega pri truplu, in pridejo ter oznanijo v mestu, kjer je prebival stari prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 26, 'In ko to začuje prorok, ki ga je nazaj pripeljal s pota, reče: Mož Božji je, ki je bil nepokoren ustom Gospodovim; zato ga je Gospod izročil levu, ki ga je raztrgal in usmrtil po besedi Gospodovi, ki mu jo je bil govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 27, 'In govori s sinovi svojimi in veli: Osedlajte mi osla! In osedlajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 28, 'In odide in najde truplo njegovo na poti ter osla in leva, stoječa pri truplu. Ni jedel lev trupla in ni strl osla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 29, 'Tedaj vzdigne prorok truplo moža Božjega ter ga dene na osla in prinese nazaj, in pridejo v mesto starega proroka, da žalujejo in ga pokopljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 30, 'In on položi truplo njegovo v svoj grob, in žalujejo nad njim, govoreč: Gorje, moj brat!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 31, 'In ko ga je pokopal, govori sinovom svojim in reče: Kadar umrjem, pokopljite me v grobu, v katerem je pokopan mož Božji; poleg njegovih kosti položite kosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 32, 'Zakaj gotovo se izpolni napoved, katero je po besedi Gospodovi klical zoper oltar v Betelu in zoper vse hiše višav, ki so po mestih Samarije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 33, 'Ali po tej zgodbi se Jeroboam ni odvrnil s hudobne poti svoje, ampak je postavil še več duhovnikov višavam izmed vsake vrste ljudi: kdorkoli mu je ugajal, njega je posvetil, da bodi duhovnik višavam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 13, 34, 'In ta reč je postala v greh hiši Jeroboamovi, da je morala izginiti in biti potrebljena s površja zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 1, 'V tem času je zbolel Abija, sin Jeroboamov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 2, 'In Jeroboam reče ženi svoji: Vstani, prosim, in preobleci se, da te ne spoznajo, da si žena Jeroboamova, ter pojdi v Silo; glej, tam je Ahija prorok, ki je govoril o meni, da bodem kralj temu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 3, 'In vzemi s seboj deset kruhov in kolačev in posodo medu ter pojdi k njemu; on ti naznani, kaj se zgodi z dečkom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 4, 'In žena Jeroboamova stori tako, in vstane ter odide v Silo in pride v hišo Ahijevo. Ahija pa ni mogel videti, kajti oči so mu bile premrle od starosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 5, 'A Gospod je rekel Ahiju: Glej, žena Jeroboamova prihaja, vprašat te besedo zastran sina svojega; bolan je namreč. Zato ji govóri tako in tako! Kajti ko pride noter, se bo delala za tujo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 6, 'Ko torej zasliši Ahija šum njenih nog, brž ko je stopila med duri, ji veli: Pridi le, žena Jeroboamova! Čemu se delaš za tujko? kajti jaz ti sem poslan s trdim poročilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 7, 'Pojdi, povej Jeroboamu: Tako pravi Gospod, Bog Izraelov: Ker sem te povišal izmed ljudstva in te postavil za vojvodo ljudstvu svojemu Izraelu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 8, 'in sem odtrgal kraljestvo od hiše Davidove ter ga dal tebi, ti pa nisi bil kakor hlapec moj David, ki je izpolnjeval zapovedi moje in hodil za menoj z vsem srcem svojim, da bi delal samo to, kar je prav v mojih očeh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 9, 'temuč si delal hudo bolj nego vsi, ki so bili pred teboj; odšel si in si naredil drugih bogov in ulitih podob, da bi me dražil v jezo, mene pa si vrgel za hrbet svoj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 10, 'zato, glej, pripravim nesrečo nad Jeroboamovo hišo in iztrebim od Jeroboamovih vsakega moškega, i sužnjega i prostega v Izraelu, in dočista izmetem hišo Jeroboamovo, kakor se blato izmete, da ga ni več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 11, 'Njega, ki od Jeroboamovih umre v mestu, bodo žrli psi, kdor pa umre na polju, njega bodo žrle ptice nebeške, kajti Gospod je govoril to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 12, 'Vstani torej in pojdi domov, in kadar stopi noga tvoja v mesto, umrje deček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 13, 'In ves Izrael bo žaloval po njem, in ga pokopljejo, zakaj on edini od Jeroboamovih pride v grob, ker se je na njem našlo nekaj dobrega proti Gospodu, Bogu Izraelovemu, v hiši Jeroboamovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 14, 'Gospod pa si obudi kralja nad Izraelom, ki zatre hišo Jeroboamovo tisti dan. In kako je že danes!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 15, 'In Gospod udari Izraela, da se bo majal kakor trst v vodi, in izdere Izraela iz te dobre dežele, ki jo je dal njih očetom, ter jih razkropi onostran velereke, zato ker so si napravili svoje Ašere, da bi dražili Gospoda v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 16, 'In izda Izraela sovražniku zaradi grehov Jeroboamovih, s katerimi je grešil in v greh zapeljeval Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 17, 'Vstane torej žena Jeroboamova in odide in dospe v Tirzo, in ko stopi na prag hiše, umrje deček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 18, 'In so ga pokopali, in ves Izrael je žaloval za njim, kakor je bil govoril Gospod po hlapcu svojem, Ahiju proroku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 19, 'Druge zgodbe Jeroboamove pa, kako se je bojeval in kako je kraljeval, glej, pisano je v knjigi letopisov kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 20, 'Dni pa, v katerih je kraljeval Jeroboam, je bilo dvaindvajset let. In legel je k očetom svojim, in Nadab, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 21, 'Roboam pa, sin Salomonov, je kraljeval na Judovem. Roboam je bil enoinštirideset let star, ko je zakraljeval, in sedemnajst let je vladal v Jeruzalemu, v mestu, ki si ga je izvolil Gospod iz vseh rodov Izraelovih, da ondi postavi ime svoje. In matere njegove ime je bilo Naama Amonka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 22, 'In Juda je delal, kar je bilo hudo v očeh Gospodovih, in dražili so ga h gorečnosti z grehi svojimi, ki so jih počenjali mimo vsega, kar so storili njih očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 23, 'Kajti napravljali so si tudi višave in stebre s podobami in Ašere na vsakem visokem hribu in pod vsakim zelenim drevesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 24, 'Pa tudi nečistosti posvečeni moški so bili v deželi, ti so počenjali vse gnusobe poganskih narodov, ki jih je bil Gospod pregnal pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 25, 'In zgodi se v petem letu kralja Roboama, da pride gori Sisak, kralj egiptovski, proti Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 26, 'Ta je pobral zaklade hiše Gospodove in zaklade hiše kraljeve in vse, kar se je dalo vzeti, tudi vse ščite zlate je pobral, ki jih je bil napravil Salomon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 27, 'Namesto njih je naredil kralj Roboam ščite iz brona ter jih je izročil poveljnikom straže, ki so čuvali vrata hiše kraljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 28, 'In kadarkoli je kralj šel v hišo Gospodovo, so jih nosili stražarji, in potem so jih zopet prinesli v stražarnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 29, 'Druge zgodbe Roboamove pa in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 30, 'Boj pa je bil med Roboamom in Jeroboamom vse njiju žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 14, 31, 'In Roboam je legel k očetom svojim, in pokopali so ga z očeti njegovimi v mestu Davidovem; ime matere njegove pa je bilo Naama Amonka. In Abijam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 1, 'V osemnajstem letu kralja Jeroboama, sina Nebatovega, je zakraljeval Abijam nad Judo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 2, 'Tri leta je kraljeval v Jeruzalemu; in materi njegovi je bilo ime Maaka, hči Abisalomova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 3, 'In živel je v vseh grehih očeta svojega, kar jih je on bil storil pred njim; in srce njegovo ni bilo popolnoma vdano Gospodu, Bogu svojemu, kakor je bilo srce Davida, očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 4, 'Ali zavoljo Davida mu je dal Gospod, Bog njegov, svetilo v Jeruzalemu, da je obudil njegovega sina za njim in ohranil obstanek Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 5, 'zato ker je David delal, kar je bilo prav v očeh Gospodovih, in se ni umaknil ničemur, kar mu je velel, vse svoje žive dni, razen v zadevi Urija Hetejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 6, 'Bil pa je boj med Roboamom in Jeroboamom, dokler je živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 7, 'Druge zgodbe Abijamove in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih? In bila je vojska med Abijamom in Jeroboamom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 8, 'In Abijam je legel k očetom svojim, in pokopali so ga v mestu Davidovem. Asa pa, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 9, 'V dvajsetem letu Jeroboama, kralja Izraelovega, je zakraljeval Asa nad Judo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 10, 'in je vladal enoinštirideset let v Jeruzalemu. In materi njegovi je bilo ime Maaka, hči Abisalomova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 11, 'In Asa je delal, kar je bilo prav v očeh Gospodovih, kakor David, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 12, 'Kajti odpravil je nečistosti posvečene moške iz dežele in odstranil vse ostudne malike, ki so jih napravili njegovi očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 13, 'Vrhutega je odstavil Maako, mater svojo, da ne bi imela kraljičje oblasti, ker je bila naredila ostudno podobo Ašeri. In Asa je zatrl njeno ostudno podobo ter jo je sežgal pri potoku Kidronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 14, 'Toda višav niso odpravili; vendar pa je bilo srce Asovo nerazdeljeno proti Gospodu vse njegove žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 15, 'In prinesel je v hišo Gospodovo, kar je bil posvetil oče njegov in kar je sam posvetil, srebro, zlato in posode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 16, 'Bil pa je boj med Asom in Baasom, kraljem Izraelovim, vse njiju žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 17, 'In Baasa, kralj Izraelov, je prišel gori proti Judi in je zidal Ramo, da bi nihče ne mogel hoditi sem ali tja na stran Asovo, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 18, 'Tedaj je Asa pobral vse srebro in zlato, kar ga je preostalo v zakladnici hiše Gospodove in v zakladnici kraljeve hiše, in ga je izročil hlapcem svojim, ter jih je poslal k Ben-hadadu, sinu Tabrimona, sina Heziona, kralja v Siriji, ki je prebival v Damasku, da naj sporoče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 19, 'Zaveza je med menoj in teboj, med mojim in tvojim očetom; glej, pošljem ti v dar srebra in zlata: pojdi, razderi zavezo svojo z Baasom, kraljem Izraelovim, da se umakne od mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 20, 'In Ben-hadad je ugodil kralju in je poslal vojsk svojih poveljnike zoper mesta Izraelova, in udarili so Ijon in Dan in Abel Betmaako in ves Kinerot z vso pokrajino Neftalijevo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 21, 'In ko je to slišal Baasa, je nehal zidati Ramo, in ostal je v Tirzi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 22, 'Nato je razglasil kralj Asa ukaz po vsem Judovem, da nikomur ni bilo izgovora. In pobrali so z Rame kamenje in les, s katerim je bil zidal Baasa, in kralj Asa je s tem zgradil Gebo Benjaminovo in Micpo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 23, 'Druge zgodbe Asove pa in vsa moč njegova in vse, kar je storil, in mesta, ki jih je sezidal, ali ni zapisano v knjigi letopisov kraljev Judovih? A v svoji starosti je bil bolan na nogah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 24, 'In legel je Asa k očetom svojim, in pokopali so ga ž njega očeti v mestu Davida, očeta njegovega. In Josafat, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 25, 'Nadab pa, sin Jeroboamov, je zakraljeval Izraelu v drugem letu Asa, kralja Judovega, in kraljeval je nad Izraelom dve leti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 26, 'in delal, kar je bilo zlo v očeh Gospodovih, in hodil po poti očeta svojega in v grehu njegovem, s katerim je bil v greh zavajal Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 27, 'Baasa pa, sin Ahijev, iz Isaharjevega rodu, je storil zavezo zoper njega; in Baasa je ubil Nadaba pri Gibetonu, ki je Filistejcev mesto; kajti Nadab in ves Izrael je oblegal Gibeton.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 28, 'V tretjem letu Asa, kralja Judovega, ga je usmrtil Baasa in je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 29, 'Komaj pa je bil nastopil kraljestvo, je pomoril vso hišo Jeroboamovo, in ni pustil od Jeroboamovih žive ne ene duše, dokler ga ni zatrl po besedi Gospodovi, ki jo je govoril po hlapcu svojem, Ahiju Silonskem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 30, 'zaradi grehov Jeroboamovih, ki jih je zagrešil in ž njimi zapeljeval v greh Izraela, zaradi draženja, s katerim je dražil v srd Gospoda, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 31, 'Druge pa zgodbe Nadabove in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 32, 'In bil je boj med Asom in Baasom, kraljem Izraelovim, vse njiju žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 33, 'V tretjem letu Asa, kralja Judovega, je zakraljeval Baasa, sin Ahijev, vsemu Izraelu v Tirzi in je vladal štiriindvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 15, 34, 'In delal je, kar je bilo hudo v očeh Gospodovih, in je hodil po poti Jeroboamovi in v grehu njegovem, ki je bil ž njim v greh zavajal Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 1, 'In pride beseda Gospodova k Jehuju, sinu Hananovemu, zoper Baasa in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 2, 'Ker sem te povišal iz prahu in te postavil za vojvodo ljudstvu svojemu, Izraelu, ti pa si hodil po poti Jeroboamovi in v greh zapeljeval ljudstvo moje, Izraela, da so me v jezo dražili z grehi svojimi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 3, 'glej, dočista hočem pomesti po Baasu in po hiši njegovi in storim s tvojo hišo, kakor sem storil s hišo Jeroboama, sina Nebatovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 4, 'Njega, ki umre od Baasovih v mestu, bodo žrli psi, in kdor njegovih umre na polju, ga bodo žrle ptice nebeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 5, 'Druge zgodbe Baasove in kar je storil in moč njegova, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 6, 'In Baasa je legel k očetom svojim, in pokopali so ga v Tirzi, in Ela, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 7, 'Po proroku Jehuju, sinu Hananovem, je tudi prišla beseda Gospodova zoper Baasa in zoper vso hišo njegovo zaradi vsega zla, ki ga je storil pred obličjem Gospodovim, da bi ga dražil v jezo z delom rok svojih, ravnajoč kakor hiša Jeroboamova, tudi zato, da jo je pokončal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 8, 'V šestindvajsetem letu Asa, kralja Judovega, je zakraljeval Ela, sin Baasov, nad Izraelom v Tirzi in je vladal dve leti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 9, 'In njegov služabnik Zimri, poveljnik polovice voz njegovih, je storil zavezo zoper njega. On pa je bil v Tirzi in je pil, da se je upijanil v hiši Arza, ki je bil oskrbnik dvorca v Tirzi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 10, 'In Zimri je prišel noter in ga je udaril in usmrtil v sedemindvajsetem letu Asa, kralja Judovega, in je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 11, 'In ko je zakraljeval, komaj je bil zasedel prestol njegov, je pobil vso hišo Baasovo; ni pustil živega ne enega moškega, ne iz sorodnikov, ne iz prijateljev njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 12, 'Tako je Zimri zatrl vso hišo Baasovo po besedi Gospodovi, ki jo je govoril po proroku Jehuju proti Baasu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 13, 'zaradi vseh grehov Baasovih in zaradi grehov sinu njegovega Ela, ki sta jih storila in ž njimi zapeljevala v greh Izraela, da bi dražili v srd Gospoda, Boga Izraelovega, z ničevostmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 14, 'Druge zgodbe Elove pa in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 15, 'V sedemindvajsetem letu Asa, kralja Judovega, je kraljeval Zimri sedem dni v Tirzi. Ljudstvo pa je bilo utaborjeno proti Gibetonu, ki je bilo mesto Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 16, 'Ko pa je ljudstvo, ki je bilo v taboru, slišalo poročilo: Zimri je storil zaroto in je tudi ubil kralja, je postavil ves Izrael tisti dan v taboru Omrija, poveljnika vojske, za kralja nad Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 17, 'In Omri je šel gori in ves Izrael ž njim od Gibetona, in so oblegali Tirzo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 18, 'In ko je videl Zimri, da je mesto dobljeno, je šel v trdnjavo kraljevega dvorca in zažgal kraljev dvorec nad seboj z ognjem in je poginil');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 19, 'za grehe svoje, ki jih je zagrešil, ker je delal, kar je bilo hudo v očeh Gospodovih, in ker je hodil po poti Jeroboamovi in v grehu njegovem, ki ga je bil začel, da zapelje v greh Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 20, 'Druge pa zgodbe Zimrijeve in zarota, ki jo je napravil, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 21, 'Takrat se je razdelilo ljudstvo Izraelovo v dve stranki: polovica ljudstva je šla za Tibnijem, sinom Ginatovim, da ga postavijo za kralja, in polovica je šla za Omrijem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 22, 'Ali ljudstvo, ki je šlo za Omrijem, je bilo močnejše nego ljudstvo, ki se je držalo Tibnija, sina Ginatovega. In Tibni je poginil, in zakraljeval je Omri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 23, 'V enemintridesetem letu Asa, kralja na Judovem, je zakraljeval Omri Izraelu; dvanajst let je vladal, šest let v Tirzi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 24, 'In kupil je goro Samarijo od Semerja za dva talenta srebra, in pozidal je goro in imenoval ime mesta, ki ga je sezidal, po imenu Semerja, gospodarja gore: Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 25, 'In Omri je delal, kar je bilo zlo v očeh Gospodovih, še huje je delal nego vsi, ki so bili pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 26, 'Kajti hodil je po vseh potih Jeroboama, sina Nebatovega, in v grehih njegovih, s katerimi je v greh vodil Izraela, da dražijo v jezo Gospoda, Boga Izraelovega, z ničevostmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 27, 'Druga pa dejanja Omrijeva, ki jih je storil, in hrabrost njegova, ki jo je izkazal, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 28, 'In Omri je legel k očetom svojim, in pokopali so ga v Samariji, in Ahab, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 29, 'V osemintridesetem letu Asa, kralja na Judovem, je zakraljeval Ahab, sin Omrijev, nad Izraelom, in vladal je Izraelu v Samariji dvaindvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 30, 'In Ahab, sin Omrijev, je delal, kar je bilo hudo v očeh Gospodovih, bolj nego vsi, kar jih je bilo pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 31, 'Zakaj kakor da bi mu bilo premalo, da je hodil v grehih Jeroboama, sinu Nebatovega, si je vzel za ženo še Jezabelo, hčer Etbaala, kralja Sidoncev, in je šel in služil Baalu ter ga je molil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 32, 'In zgradil je Baalu oltar v hiši Baalovi, ki jo je bil sezidal v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 33, 'Ahab je tudi naredil Ašero; sploh je Ahab več storil, da razdraži v jezo Gospoda, Boga Izraelovega, nego vsi kralji v Izraelu, ki so bili pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 16, 34, 'V dneh njegovih je zidal Hiel Betelski Jeriho: ko pa mu je položil podstavo, je izgubil Abirama, prvenca svojega, in ko mu je postavil vrata, je izgubil najmlajšega sina Seguba, po besedi Gospodovi, ki jo je govoril po Jozuetu, sinu Nunovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 1, 'In Elija, Tisbljan, iz prebivalcev Gileadskih, je govoril Ahabu: Kakor res živi Jehova, Bog Izraelov, ki stojim pred njega obličjem, ne bode ta leta ne rose, ne dežja, razen le po besedi moji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 2, 'In beseda Gospodova pride k njemu, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 3, 'Pojdi odtod in obrni se proti vzhodu ter se skrij pri potoku Keritu, ki teče proti Jordanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 4, 'In iz potoka boš pil, krokarjem pa sem zapovedal, da te ondi žive.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 5, 'Šel je torej in storil po besedi Gospodovi; šel je in bival pri potoku Keritu, ki teče proti Jordanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 6, 'Krokarji pa so mu prinašali kruha in mesa zjutraj ter kruha in mesa zvečer, in iz potoka je pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 7, 'In zgodi se za nekoliko časa, da je potok usahnil, zakaj dežja ni bilo v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 8, 'In pride mu beseda Gospodova, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 9, 'Vstani, pojdi v Sarepto pri Sidonu, in tam prebivaj; glej, zapovedal sem ondi ovdoveli ženi, da te oskrbuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 10, 'Vstane torej in odide v Sarepto, in ko pride do mestnih vrat, glej, vdova je bila ondi in je pobirala dračje. In jo pokliče ter veli: Prinesi mi, prosim, malo vode v posodi, da pijem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 11, 'Ko ona gre, da prinese, pokliče za njo in veli: Prosim, prinesi mi tudi grižljaj kruha v roki svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 12, 'Ona odvrne: Kakor res živi Gospod, Bog tvoj, nimam ničesar pečenega, samo prgišče moke v skrinji in malo olja v vrču, in glej, ravnokar sem nabrala malo dračja, da stopim noter in to pripravim sebi in sinu svojemu, da jeva in umrjeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 13, 'A Elija ji veli: Ne boj se! Pojdi in naredi, kakor si dejala, toda pripravi meni majhen kolač najprej ter mi ga prinesi in potem pripravi sebi in sinu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 14, 'Zakaj tako pravi Gospod, Bog Izraelov: Moka v skrinji ne bo pošla in olja v vrču ne bo zmanjkalo do dneva, ob katerem pošlje Gospod dež nad zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 15, 'In je šla in naredila po besedi Elijevi. In je jedla, tudi on in ona in njena družina dosti dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 16, 'Moka v skrinji ni pošla in olja v vrču ni zmanjkalo po besedi Gospodovi, ki jo je bil govoril po Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 17, 'Zgodi se pa po teh rečeh, da zboli sin tiste žene, hišne gospodinje, in bolezen mu je bila tako huda, da ni bilo več sape v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 18, 'In reče Eliju: Kaj je meni s teboj, mož Božji? Prišel si k meni, da spraviš v spomin krivico mojo in da umoriš sina mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 19, 'On pa veli: Daj mi sem sina svojega! In ga vzame iz njenega naročja ter ga odnese v zgornjo izbo, kjer je prebival, in ga položi na posteljo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 20, 'In kliče h Gospodu in reče: O Gospod, Bog moj, si li celo tej vdovi, pri kateri gostujem, hudo storil, ko si umoril sina njenega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 21, 'In se razprostre trikrat nad detetom in kliče h Gospodu, rekoč: Gospod, Bog moj, prosim, naj se vrne tega dečka duša zopet vanj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 22, 'In Gospod je uslišal glas Elijev, in duša dečkova se je povrnila vanj, in je oživel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 23, 'In Elija vzame dečka ter ga prinese iz zgornje izbe doli v hišo in ga izroči materi njegovi; in Elija reče: Glej, sin tvoj živi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 17, 24, 'In žena reče Eliju: Sedaj sem spoznala, da si ti mož Božji in da beseda Gospodova v ustih tvojih je resnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 1, 'In po mnogih dneh pride beseda Gospodova k Eliju, v tretjem letu, in veli: Pojdi, pokaži se Ahabu, da dam dežja na zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 2, 'Šel je torej Elija, da se pokaže Ahabu. Bila je pa velika lakota v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 3, 'In Ahab pokliče Obadija, ki je bil oskrbnik dvorca (Obadija se je pa silno bal Gospoda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 4, 'in zgodilo se je, ko je Jezabela morila proroke Gospodove, da je Obadija vzel sto prorokov in jih je skril v jami, tu petdeset in tam petdeset, ter jih je oskrboval s kruhom in z vodo).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 5, 'In Ahab veli Obadiju: Pojdi po deželi do vseh studencev in do vseh potokov, če morda kje najdemo trave in ohranimo konje in mezge, da ne izgubimo vse živine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 6, 'Razdelita si torej deželo, da jo prehodita; Ahab gre po eni poti sam in po drugem potu Obadija sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 7, 'In ko je Obadija na poti, glej, pride mu Elija naproti; in ga spozna ter pade na obraz in reče: Si li ti, gospod moj Elija?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 8, 'On odgovori: Jaz sem. Pojdi, povej svojemu gospodu: Glej, Elija je tu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 9, 'On pa reče: Kaj sem pregrešil, da hočeš dati mene, hlapca svojega, Ahabu v roko, da me umori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 10, 'Kakor resnično živi Gospod, Bog tvoj, ni ga naroda ali kraljestva, kamor ni poslal moj gospod te iskat; in ko so rekli: Ni ga tukaj, je zahteval prisego od tistega kraljestva in naroda, da te niso našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 11, 'In sedaj mi veliš: Pojdi, povej gospodu svojemu: Glej, Elija je tu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 12, 'Lahko se zgodi, ko odidem od tebe, da te duh Gospodov odnese ne vem kam; in ko pridem in povem Ahabu zate, on pa te ne najde, tedaj me umori. In hlapec tvoj se boji Gospoda od mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 13, 'Niso li tebi, gospodu mojemu, povedali, kaj sem storil, ko je Jezabela morila proroke Gospodove? Da sem jih skril sto izmed prorokov Gospodovih v jami, tu petdeset, tam petdeset, in sem jih oskrboval s kruhom in z vodo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 14, 'In sedaj mi veliš: Pojdi, povej gospodu svojemu: Glej, Elija je tu! In me umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 15, 'In Elija reče: Kakor res živi Gospod nad vojskami, ki stojim pred njega obličjem, gotovo se mu pokažem danes!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 16, 'Tedaj gre Obadija naproti Ahabu in mu to naznani. Ahab pa krene Eliju naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 17, 'In ko Ahab ugleda Elija, mu reče: Si li tu ti, ki spravljaš v nesrečo Izraela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 18, 'On odgovori: Nisem jaz spravil v nesrečo Izraela, temuč ti in tvojega očeta hiša s tem, da ste zapustili zapovedi Gospodove in si ti hodil za Baali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 19, 'Sedaj torej pošlji in zberi k meni vsega Izraela pri gori Karmelu in prorokov Baalovih štiristo in petdeset, tudi štiristo prorokov Ašerinih, ki jedo z mize Jezabeline.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 20, 'Ahab torej pošlje do vseh sinov Izraelovih in zbere proroke pri gori Karmelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 21, 'In Elija stopi pred vse ljudstvo in reče: Kako dolgo omahujete na dve strani? Je li Gospod Bog, hodite za njim, če pa je Baal, hodite za njim! In ljudstvo mu ne odgovori besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 22, 'Tedaj reče Elija ljudstvu: Jaz, jaz sam sem ostal prorok Gospodov, a prorokov Baalovih je štiristo in petdeset mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 23, 'Dajte nam torej dva junca, in oni naj si izbero junca zase in ga razsekajo in polože na drva, ognja pa naj ne zanetijo; in jaz pripravim drugega junca ter ga položim na drva, ognja pa ne zanetim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 24, 'In kličite ime svojega boga, jaz pa bom klical ime Gospodovo: in Bog, ki odgovori z ognjem, ta bodi Bog. In vse ljudstvo odgovori in reče: Prav si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 25, 'Nato reče Elija prorokom Baalovim: Izberite si enega junca in ga pripravite najprej, zakaj vas je veliko; in kličite ime svojega boga, ognja pa ne zanetite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 26, 'In vzamejo junca, ki jim je bil dan, in ga pripravijo, pa kličejo ime Baalovo od jutra do poldne, govoreč: O Baal, usliši nas! A ni bilo glasu, ne odgovora. In skačejo okoli oltarja, ki so ga naredili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 27, 'In ko je bilo že poldne, jih zasmehuje Elija in veli: Vpijte prav glasno, saj je vendar bog! nemara da je zatopljen v misli, ali je šel na stran, ali je na potovanju; morda spi in se prebudi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 28, 'In vpijejo glasno in se po svoji šegi bodejo z nožmi in sulicami, da je kri po njih tekla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 29, 'In ko je minil poldan, še prorokujejo, dokler ne pride čas, da se prinese večerna daritev, a ni bilo glasu, ne odgovora, ne nikogar, ki bi poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 30, 'Tedaj veli Elija vsemu ljudstvu: Pristopite k meni! In ko pristopi ljudstvo k njemu, popravi oltar Gospodov, ki je bil razdrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 31, 'In Elija vzame dvanajst kamenov, po številu rodov sinov Jakoba, ki se mu je zgodila beseda Gospodova, rekoč: Izrael bodi ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 32, 'In iz teh kamenov zgradi oltar v imenu Gospodovem; in okoli oltarja naredi jarek, širok in globok za dvojno žitno merico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 33, 'In pripravi drva ter razseka junca in ga položi na drva. Pa veli: Napolnite štiri vrče z vodo in jo izlijte na žgalno žrtev in na drva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 34, 'In veli: Še v drugič storite to! In ko storé v drugič, veli: Storite še v tretjič! In store v tretje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 35, 'In voda je tekla okoli oltarja; pa tudi jarek je napolnil z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 36, 'In ko pride čas, da se daruje večerna daritev, pristopi prorok Elija in reče: Gospod, Bog Abrahamov, Izakov in Izraelov, daj danes spoznati, da si ti Bog v Izraelu in da sem jaz hlapec tvoj in da sem storil vse to po besedi tvoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 37, 'Odgovóri mi, o Gospod, odgovori mi! da spozna to ljudstvo, da si ti, o Gospod, Bog in si ti sam preobrnil njih srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 38, 'Tedaj švigne doli ogenj Gospodov in požre žgalno daritev in drva in kamene in prst in poliže vodo, ki je bila v jarku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 39, 'In ko vse ljudstvo vidi to, popadajo na obraze in govore: Gospod je Bog! Gospod je Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 40, 'Elija pa jim veli: Primite proroke Baalove, da njih nobeden ne ubeži! In so jih prijeli. In Elija jih popelje doli k potoku Kisonu in jih ondi pomori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 41, 'In Elija veli Ahabu: Pojdi gori, jej in pij, kajti šumi, kakor da se bliža silen dež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 42, 'Ahab torej gre gori jest in pit. A Elija stopi na vrh Karmela in, pripognjen proti zemlji, skloni obraz svoj med kolena svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 43, 'In reče hlapcu svojemu: Pojdi gori in poglej proti morju! In gre gori in pogleda, pa reče: Ničesar ni. In mu veli: Pojdi spet tja, sedemkrat!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 44, 'In ob sedmem potu reče: Glej, oblaček vstaja iz morja, majhen kakor moška roka. Pa veli: Pojdi in reci Ahabu: Zaprezi in pelji se doli, da te dež ne zadrži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 45, 'In medtem malo po malo zatemni nebo z oblaki in vetrom, in nastane velik dež. In Ahab sede na voz in se pelje v Jezreel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 18, 46, 'Roka Gospodova pa je bila nad Elijem, in opasal si je ledje in tekel pred Ahabom do vhoda v Jezreel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 1, 'In Ahab je povedal Jezabeli vse, kar je storil Elija, tudi, kako je umoril vse proroke z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 2, 'In pošlje Jezabela sla k Eliju, da sporoči: Bogovi naj mi store to in to naj še pridenejo, ako ne storim jutri ob tem času z življenjem tvojim, kakor si storil z življenjem onih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 3, 'In ko je zvedel to, vstane in odide zaradi življenja svojega in pride v Bersebo na Judovem in pusti ondi hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 4, 'Sam pa gre dalje v puščavo, en dan hoda, in pride in sede pod brinov grm in prosi zase, da bi umrl, govoreč: Zadosti mi je! sedaj, o Gospod, vzemi dušo mojo; kajti nisem boljši nego očetje moji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 5, 'In leže in zaspi pod brinovim grmom. A glej, angel se ga dotakne in mu veli: Vstani in jej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 6, 'In se ozre, in glej, pri glavi njegovi je bil kruh, pečen na gorkih kamenih, pa vrč vode. In ko zaužije in se napije, leže zopet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 7, 'In angel Gospodov pride zopet, v drugič, se ga dotakne in veli: Vstani in jej! kajti predolga je pot zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 8, 'In vstane in je in pije in potuje v moči tiste jedi štirideset dni in štirideset noči, dokler ne pride do gore Božje, Horeba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 9, 'In ondi pride v votlino in tu prenoči. In glej, beseda Gospodova pride k njemu in mu reče: Kaj tu delaš, Elija?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 10, 'Odgovori: Silno sem gorel za Gospoda, Boga nad vojskami; zakaj sinovi Izraelovi so zapustili zavezo tvojo, oltarje tvoje so razdrli in proroke tvoje pomorili z mečem, in ostal sem jaz sam, pa še meni strežejo po življenju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 11, 'In veli mu: Pojdi ven in stopi na goro pred Gospoda! In glej, Gospod je šel mimo, in veter, velik in močan, je podiral gore in razbijal skale pred Gospodom; a Gospoda ni bilo v vetru. Za vetrom pa pride potres, a Gospoda ni v potresu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 12, 'In za potresom ogenj, a Gospoda ni v ognju. In za ognjem tih in mil glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 13, 'Ko pa to sliši Elija, si zagrne s plaščem obraz ter gre ven in se ustopi ob vhodu v votlino. In glej, glas mu izpregovori: Kaj delaš tu, Elija?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 14, 'On reče: Silno sem gorel za Gospoda, Boga nad vojskami; zakaj sinovi Izraelovi so zapustili zavezo tvojo, oltarje tvoje so razdrli in proroke tvoje pomorili z mečem, in ostal sem jaz sam, pa še meni strežejo po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 15, 'In Gospod mu veli: Pojdi, vrni se svojim potom po puščavi, v Damask; in ko prideš tja, pomazili Hazaela za kralja Siriji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 16, 'Jehuja pa, sina Nimsijevega, pomazili za kralja nad Izraelom, in Elizeja, sina Safatovega, iz Abel-mehole, pomazili za proroka namesto sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 17, 'In zgodi se, da kdor ubeži meču Hazaelovemu, ga umori Jehu, in kdor ubeži meču Jehujevemu, ga umori Elizej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 18, 'Storil sem pa, da mi jih ostane sedem tisoč v Izraelu, vsa kolena, ki se niso pripogibala gred Baalom, in vsaka usta, ki ga niso poljubljala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 19, 'In odide odondod ter zaloti Elizeja, sina Safatovega, da orje z dvanajstimi jarmi volov pred seboj, sam pa je bil pri dvanajstem. In Elija stopi k njemu in vrže svoj plašč na njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 20, 'In on popusti voli in teče za Elijem in reče: Dovoli mi, prosim, da poljubim očeta svojega in mater svojo, in potem pojdem za teboj! Ta mu veli: Idi, vrni se! Kajti kaj sem ti storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 19, 21, 'In se obrne in odide od njega in vzame jarem volov ter ju zakolje; in skuha meso pri opravi, ki je bila na volih, in da ljudstvu, in so jedli. Potem vstane in hodi za Elijem in mu streže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 1, 'Ben-hadad pa, kralj sirski, je zbral vso vojsko svojo, in bilo je pri njem dvaintrideset kraljev pa konj in vozov; in pride in oblega Samarijo in se bojuje zoper njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 2, 'In pošlje sporočnikov v mesto k Ahabu, kralju Izraelovemu, da mu reko: Tako pravi Ben-hadad:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 3, 'Tvoje srebro in zlato je moje, in najboljše žene tvoje in otroci tvoji so tudi moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 4, 'Kralj Izraelov pa odgovori in reče: Po besedi tvoji, gospod moj, kralj: tvoj sem in vse, kar imam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 5, 'A sporočniki pridejo zopet in reko: Tako govori Ben-hadad: Ker sem poslal k tebi, rekoč: Meni daš srebro in zlato svoje in žene in otroke svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 6, 'zato pošljem jutri ob tem času hlapce svoje k tebi, in preiščejo hišo tvojo in služabnikov tvojih hiše, in karkoli z veseljem gledaš, vzamejo v roke in odneso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 7, 'Tedaj skliče kralj Izraelov vse starejšine dežele in reče: Premislite, prosim, in glejte, da ima ta mož le hudo v mislih! Zakaj poslal je k meni po žene in otroke moje in po srebro in zlato moje, in mu nisem odklonil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 8, 'In vsi starejšine in vse ljudstvo mu reče: Ne poslušaj ga in ne vdaj se mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 9, 'Zatorej veli sporočnikom Ben-hadadovim: Povejte gospodu mojemu, kralju: Vse, kar si sporočil hlapcu svojemu najprej, sem hotel storiti, a tega ne morem. In sporočniki odidejo in mu prineso ta odgovor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 10, 'Tedaj pošlje Ben-hadad in mu sporoči: To naj mi bogovi store in to še pridenejo, ako bode dosti prahu v Samariji, da ga vzame vsak iz ljudstva mojega, ki ga vodim, le peščico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 11, 'Kralj Izraelov odgovori in reče: Povejte mu: Kdor se opasuje z mečem, naj se še ne hvali kakor oni, ki ga deva od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 12, 'In zgodi se, ko Ben-hadad sliši to sporočilo, ko je ravno pil s kralji v šatorih, da veli hlapcem svojim: Postavite se! In postavijo se v boj proti mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 13, 'In glej, prorok pristopi k Ahabu, kralju Izraelovemu, in reče: Tako pravi Gospod: Si videl vso to preveliko množico? Glej, jaz ti jo danes dam v roke, da spoznaš, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 14, 'In Ahab vpraša: Po kom? On odgovori: Tako pravi Gospod: Po mladeničih pokrajinskih poglavarjev. Nato vpraša: Kdo naj začne boj? Odgovori: Ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 15, 'Tedaj prešteje mladeniče pokrajinskih poglavarjev, in bilo jih je dvesto in dvaintrideset; in za njimi prešteje vse ljudstvo, vse sinove Izraelove, sedem tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 16, 'In gredo ven opoldne. Ben-hadad pa je pil in se opijanil v šatorih z dvaintridesetimi kralji, ki so mu bili prišli v pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 17, 'A mladeniči pokrajinskih poglavarjev so šli ven prvi. In Ben-hadad pošlje pogledat, in oznanijo mu, rekoč: Možje gredo sem iz Samarije!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 18, 'On veli: Bodisi, da prihajajo po mir, ali da se gredo vojskovat, primite jih žive!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 19, 'Oni torej gredo iz mesta, mladeniči pokrajinskih poglavarjev, druga vojska pa za njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 20, 'in vsak udari moža sebi nasproti; in Sirci zbeže, in Izrael dere za njimi. Ben-hadad pa, kralj sirski, je zbežal na konju z jezdeci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 21, 'In kralj Izraelov pride iz mesta in potolče konje in vozove in porazi Sirce z velikim pobojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 22, 'Potem pristopi prorok h kralju Izraelovemu in mu reče: Pojdi, ojači se in premisli in glej, kaj delaš; zakaj kralj Sirije pride gori zoper tebe, ko mine leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 23, 'In služabniki sirskega kralja mu reko: Njih bogovi so bogovi gorá, zato so nas premagali. Da bi se mogli ž njimi bojevati na ravnem, gotovo jih zmagamo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 24, 'Zatorej stóri to: Odstrani kralje, vsakega z njegovega mesta, in postavi namestnike na njih mesta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 25, 'In oskrbi si vojsko, kakor je bila vojska, ki si jo izgubil, tudi konje in vozove, enake prejšnjim; in bojevali se bomo zoper nje na ravnem, in gotovo jih premagamo! In slušal je njih glas in je storil tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 26, 'In ko je minilo leto, prešteje Ben-hadad Sirce in gre gori proti Afeku, da se bojuje zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 27, 'In sinovi Izraelovi se tudi preštejejo in oskrbe z živežem ter gredo proti njim; in sinovi Izraelovi se utabore nasproti njim kakor dve majhni čredi koz. Sircev pa je bilo polno v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 28, 'In mož Božji pristopi in reče kralju Izraelovemu: Tako pravi Gospod: Ker so dejali Sirci: Gospod je Bog gorá, a ni Bog dolin, zato dam vso to veliko množico v tvojo roko, in spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 29, 'In taborili so eni nasproti drugim sedem dni. Sedmi dan pa se vname bitka, in sinovi Izraelovi pobijejo izmed Sircev stotisoč pešcev v enem dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 30, 'Preostali pa so bežali v Afek, v mesto, in zidovje je padlo na preostalih sedemindvajset tisoč mož. Ben-hadad je tudi zbežal in pritekel v mesto, iz hrama v hram bežeč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 31, 'In hlapci njegovi mu reko: Poglej, slišali smo, da so kralji Izraelove hiše milostivi kralji; dovoli, prosimo, da si denemo raševnike okoli ledij in vrvi ob tilnike, pa pojdemo ven h kralju Izraelovemu; lahko da te ohrani v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 32, 'Opašejo si torej raševnike in denejo vrvi ob tilnike in pridejo h kralju Izraelovemu, pa reko: Hlapec tvoj Ben-hadad pravi: Prosim te, daj mi živeti! On pa reče: Živi li še? Brat je moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 33, 'To pa so smatrali možje za dobro znamenje in so hitro povzeli to besedo od njega in dejali: Brat tvoj je Ben-hadad. Nato on veli: Pojdite, pripeljite ga! Tedaj pride Ben-hadad ven k njemu, in on mu veli stopiti na svoj voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 34, 'In Ben-hadad reče: Mesta, ki jih je vzel moj oče tvojemu očetu, ti povrnem, in napravi si ulice v Damasku, kakor je oče moj napravil v Samariji. Jaz pa, reče Ahab, te izpustim s to zavezo. Storil je torej ž njim zavezo in ga je odpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 35, 'In neki mož izmed proroških sinov reče tovarišu svojemu po besedi Gospodovi: Udari me, prosim! A mož ga ni hotel udariti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 36, 'Tedaj mu reče: Ker nisi slušal glasu Gospodovega, glej, umori te lev, brž ko pojdeš od mene. In komaj je šel od njega, naleti nanj lev in ga umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 37, 'Nato se nameri na drugega moža ter mu reče: Udari me, prosim! In mož ga krepko udari in rani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 38, 'Prorok pa odide in se postavi kralju na poti in se pretvori z oglavno povezo nad očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 39, 'In ko gre kralj mimo, kliče kralju in reče: Hlapec tvoj je šel med boj, in glej, nekdo stopi vstran in mi pripelje moža in veli: Varuj tega moža! Ako ga bodo pogrešili, bode življenje tvoje namesto življenja njegovega, ali pa boš moral plačati talent srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 40, 'Ko pa je hlapec tvoj imel tu in tam opravilo, je mož izginil. In kralj Izraelov mu reče: Taka je sodba tvoja; sam si jo izrekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 41, 'Tedaj sname hitro povezo z oči; in kralj Izraelov ga spozna, da je izmed prorokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 42, 'On pa mu reče: Tako pravi Gospod: Ker si pustil iz roke svoje moža, ki sem ga jaz izročil pogubi, zato bo življenje tvoje za njega življenje in ljudstvo tvoje za njegovo ljudstvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 20, 43, 'In kralj Izraelov je šel hude volje in srdit v hišo svojo in je dospel v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 1, 'In zgodi se po teh rečeh, da je imel Nabot Jezreelčan vinograd, ki je bil v Jezreelu poleg palače Ahaba, kralja v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 2, 'In Ahab ogovori Nabota in reče: Daj mi svoj vinograd, da si napravim iz njega zelnik, ker je blizu, tik hiše moje, in dam ti zanj boljši vinograd, ali, če ti je prav, dam ti srebra zanj, kolikor je vreden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 3, 'Nabot pa reče Ahabu: Gospod mi ne daj, da bi dal očetov svojih dediščino tebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 4, 'In Ahab pride domov hude volje in srdit zaradi besede, ki mu jo je govoril Nabot Jezreelčan; kajti dejal mu je: Nikar ti ne dam očetov svojih dediščine! In leže na posteljo, obrne obraz in noče užiti kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 5, 'Tedaj pride noter k njemu Jezabela, žena njegova, in ga ogovori: Zakaj je duh tvoj tako užaljen, da še kruha ne ješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 6, 'In ji reče: Ker sem govoril z Nabotom Jezreelčanom in mu rekel: Daj mi vinograd svoj za denar, ali pa ti dam, če ti je pogodu, drug vinograd zanj; on pa mi je odgovoril: Ne dam ti vinograda svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 7, 'In Jezabela, žena njegova, mu reče: Ne vladaš li ti sedaj kraljestva Izraelovega? Vstani in jej kruh in bodi dobre volje! Jaz ti hočem dati vinograd Nabota Jezreelčana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 8, 'Nato napiše liste v imenu Ahabovem in jih zapečati ž njegovim pečatom, in pošlje liste starejšinam in plemenitnikom, ki so prebivali z Nabotom v mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 9, 'In pisala je v listih takole: Razglasite post in posadite Nabota med prvake ljudstva;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 10, 'in postavite dva moža, otroka Belijalova, proti njemu, da pričujeta zoper njega: Proklel si Boga in kralja. Nato ga peljite ven in ga lučajte s kamenjem, da umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 11, 'In njegovi someščani, starejšine in plemenitniki, ki so prebivali v mestu njegovem, store, kakor jim je Jezabela ukazala, prav kakor je bilo ukazano v listih, ki jih jim je poslala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 12, 'Razglasijo post in posade Nabota med prvake ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 13, 'In prideta tista dva moža, otroka Belijalova, in stopita predenj, in tista moža Belijalova izpričata zoper Nabota vpričo ljudstva, govoreč: Nabot je proklel Boga in kralja. Tedaj ga odvedejo iz mesta in ga lučajo s kamenjem, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 14, 'Nato pošljejo k Jezabeli in sporoče: Nabot je s kamenjem posut in mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 15, 'In kakor hitro zasliši Jezabela, da je Nabot s kamenjem posut in mrtev, veli Jezabela Ahabu: Vstani, posedi vinograd Nabota Jezreelčana, ki ti ga ni hotel dati za denar, kajti Nabot ne živi več, mrtev je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 16, 'In ko Ahab sliši, da je Nabot mrtev, vstane precej, da bi šel doli v vinograd Nabota Jezreelčana in ga vzel v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 17, 'A beseda Gospodova pride Eliju Tisbljanu, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 18, 'Vstani, pojdi doli naproti Ahabu, kralju Izraelovemu, ki prebiva v Samariji; glej, on je v vinogradu Nabotovem, kamor je šel, da ga vzame v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 19, 'In govóri mu, rekoč: Tako pravi Gospod: Nisi li ubil in po sili vzel? In govóri ž njim in reci: Tako pravi Gospod: Na mestu, kjer so psi lizali Nabotovo kri, bodo lizali tudi tvojo, prav tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 20, 'In Ahab reče Eliju: Si me li našel, sovražnik moj? On odgovori: Našel sem te, zato ker si se prodal, da delaš, kar je hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 21, 'Glej, jaz pripravim nesrečo nadte in dočista te izmetem, in iztrebim od Ahabovih vsakega moškega, sužnja in prostega v Izraelu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 22, 'in storim s hišo tvojo kakor s hišo Jeroboama, sina Nebatovega, in kakor s hišo Baasa, sina Ahijevega, zaradi draženja, s katerim si me dražil, in da si Izraela zapeljeval v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 23, 'Tudi o Jezabeli je govoril Gospod in rekel: Psi bodo žrli Jezabelo ob obzidju jezreelskem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 24, 'Kdor umre od Ahabovih v mestu, ga bodo žrli psi, in njega, ki umre na polju, bodo žrle ptice nebeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 25, '(Saj ni bilo nikogar mimo Ahaba, ki se je prodal, da bi delal, kar je zlo v očeh Gospodovih, ker ga je izpodbadala Jezabela, žena njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 26, 'In velike gnusobe je počenjal s tem, da je hodil za grdimi maliki, prav po vsem, kar so delali Amorejci, ki jih je Gospod zapodil pred sinovi Izraelovimi.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 27, 'In ko je Ahab slišal te besede, si raztrga oblačila in dene raševnik na telo in se posti in spi v raševniku ter hodi pohlevno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 28, 'Tedaj pride beseda Gospodova Eliju Tisbljanu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 21, 29, 'Vidiš li, kako se je Ahab ponižal pred menoj? Ker se ponižuje pred menoj, ne pripravim nesreče v dneh njegovih; v dneh sinu njegovega pošljem nesrečo nad hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 1, 'In tri leta so bivali v miru, da ni bilo vojske med Sirijo in Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 2, 'In zgodi se v tretjem letu, da pride Josafat, kralj Judov, doli h kralju Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 3, 'In reče kralj Izraelov služabnikom svojim: Ne veste li, da je Ramot v Gileadu naš? In mi mirujemo in ga ne vzamemo iz roke sirskega kralja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 4, 'In reče Josafatu: Pojdeš li z menoj v boj proti Ramotu v Gileadu? Josafat odgovori kralju Izraelovemu: Bodem naj kakor ti, ljudstvo moje kakor ljudstvo tvoje, konji moji kakor konji tvoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 5, 'Še reče Josafat kralju Izraelovemu: Vprašaj, prosim, danes besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 6, 'Tedaj skliče kralj Izraelov proroke, okoli štiristo mož, pa jih vpraša: Naj li grem v boj proti Ramotu v Gileadu ali naj to opustim? Odgovore: Pojdi gori, in Gospod ga da v roko kraljevo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 7, 'Josafat pa reče: Ni li sicer nobenega Gospodovega proroka tu, da bi ga povprašali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 8, 'In kralj Izraelov reče Josafatu: Še en mož je, po katerem moremo vprašati Gospoda, Mihaj, sin Imlov; ali jaz ga sovražim, zakaj ne prorokuje mi dobrega, nego zgolj hudo. Josafat reče: Ne govóri tako, kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 9, 'Tedaj pokliče kralj Izraelov enega dvornika in veli: Hitro pripelji sem Mihaja, sina Imlovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 10, 'Kralj Izraelov in Josafat, kralj Judov, pa sta sedela vsak na svojem prestolu, po kraljevsko oblečena, na trgu pri vhodu v vrata Samarije, in vsi proroki so prorokovali pred njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 11, 'In Zedekija, sin Kenaanov, si je naredil železne rogove in govoril: Tako pravi Gospod: S temi boš bodel Sirce, dokler jih celo ne zatareš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 12, 'Tudi vsi proroki so prorokovali tako in govorili: Pojdi proti Ramotu v Gileadu in srečno hodi, in Gospod ga da kralju v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 13, 'Sel pa, ki je šel poklicat Mihaja, mu govori in reče: Glej vendar: besede prorokov oznanjajo soglasno kralju dobro; bodi torej beseda tvoja kakor beseda enega izmed njih, in govóri dobro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 14, 'In Mihaj reče: Kakor res živi Gospod, kar mi poreče Gospod, bom govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 15, 'In ko pride h kralju, mu reče kralj: Mihaj, ali naj gremo v boj proti Ramotu v Gileadu ali naj opustimo? Odgovori: Pojdi in srečno hodi! Gospod ga da kralju v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 16, 'Kralj mu pa veli: Kolikokrat mi te je rotiti, da mi ne govoriš ničesar nego resnico v imenu Gospodovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 17, 'In reče: Videl sem vse Izraelce razkropljene po gorah kakor ovce, ki nimajo pastirja; in Gospod je dejal: Ti nimajo gospodarja! Vsak naj se vrne domov v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 18, 'Nato reče kralj Izraelov Josafatu: Nisem ti li rekel, da mi ne prorokuje nič dobrega, nego zgolj hudo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 19, 'On reče: Zatorej čuj besedo Gospodovo! Videl sem Gospoda, da sedi na prestolu svojem, in vso vojsko nebeško, da mu stoji ob desnici in ob levici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 20, 'In Gospod je vprašal: Kdo premoti Ahaba, da bi šel gori in padel pri Ramotu v Gileadu? In ta je rekel to in drugi je rekel ono.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 21, 'Tedaj pride duh in se postavi pred Gospoda in reče: Jaz ga premotim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 22, 'In Gospod ga vpraša: S čim? Odgovori: Pojdem tja in bodem lažniv duh v ustih vseh prorokov njegovih. In veli: Ti ga premotiš in se ti posreči. Pojdi tja in stóri tako!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 23, 'Sedaj torej glej, Gospod je dal lažnivega duha v usta vseh teh prorokov tvojih, a Gospod je govoril hudo zoper tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 24, 'Tedaj pristopi Zedekija, sin Kenaanov, in udari Mihaja v lice in reče: Kod je šel duh Gospodov od mene, da s tabo govori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 25, 'Mihaj odvrne: Glej, videl boš tisti dan, ko boš hodil iz hrama v hram, da se skriješ!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 26, 'Kralj Izraelov pa veli: Vzemi Mihaja in ga pelji nazaj k Amonu, mestnemu poglavarju, in k Joasu, sinu kraljevemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 27, 'pa reci: Tako pravi kralj: Denita tega moža v ječo in živita ga s kruhom bridkosti in z vodo stiske, dokler se ne vrnem v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 28, 'A Mihaj reče: Ako se vrneš v miru, ni govoril po meni Gospod! Še reče: Čujte, vsi ljudje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 29, 'Nato sta šla kralj Izraelov in Josafat, kralj Judov, gori proti Ramotu v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 30, 'In kralj Izraelov reče Josafatu: Jaz pojdem preoblečen v boj, ti pa obleci svoja oblačila! Preobleče se torej kralj Izraelov in gre v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 31, 'Kralj sirski pa je zapovedal dvaintridesetim poveljnikom svojih voz, rekoč: Ne bojujte se zoper male, ne zoper velike, ampak zgolj zoper kralja Izraelovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 32, 'Ko torej vidijo poveljniki vozov Josafata, reko: Gotovo je on kralj Izraelov! In zaženo se bojevat zoper njega; in zavpije Josafat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 33, 'Ko pa vidijo poveljniki voz, da ni kralj Izraelov, se obrnejo od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 34, 'Neki mož pa slučajno napne lok in ustreli kralja Izraelovega med stike v oklepu. Tedaj veli svojemu vozniku: Obrni voz in pelji me z bojišča, kajti hudo sem ranjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 35, 'A bitka se je razvnela tisti dan, in kralj je moral stati na vozu Sircem nasproti, in zvečer je umrl; in kri je tekla iz rane na dno voza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 36, 'In ko je solnce zahajalo, je šel klic po taborišču: Vsak pojdi v mesto svoje in v kraj svoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 37, 'ker kralj je mrtev! In pripeljali so ga v Samarijo in pokopali v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 38, 'In ko so omivali voz pri samarijskem ribniku, so lizali psi kri njegovo in nečistnice so se omivale ž njo po besedi Gospodovi, ki jo je bil govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 39, 'In druge zgodbe Ahabove in vse, kar je storil, in slonokoščena hiša, ki jo je postavil, in vsa mesta, ki jih je sezidal, ni li zapisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 40, 'Tako je legel Ahab k očetom svojim, in Ahazija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 41, 'In Josafat, sin Asov, je zakraljeval nad Judom v četrtem letu Ahaba, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 42, 'Josafat pa je bil petintrideset let star, ko je zakraljeval, in vladal je petindvajset let v Jeruzalemu. In materi njegovi je bilo ime Azuba, hči Silhijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 43, 'In hodil je po vsej poti Asa, očeta svojega; ni se ganil od nje in je delal, kar je bilo prav v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 44, 'Toda višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 45, 'In Josafat je imel mir s kraljem Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 46, 'Druge pa zgodbe Josafatove in hrabrost njegova, ki jo je dokazal, in kako se je bojeval, ni li pisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 47, 'On je tudi spravil iz dežele ostanke nečistoti posvečenih moških, ki so preostali v dneh Asa, očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 48, 'V Edomu pa ni bilo kralja, namestnik je vladal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 49, 'In Josafat je napravil tarske ladje, ki naj bi šle v Ofir po zlato; a niso šle, ker so se razbile v Ezion-geberju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 50, 'Tedaj je rekel Ahazija, sin Ahabov, Josafatu: Peljejo naj se hlapci moji na ladjah s hlapci tvojimi! A Josafat ni hotel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 51, 'In Josafat je legel k očetom svojim, in pokopali so ga pri očetih njegovih v mestu Davida, očeta njegovega. In Joram, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 52, 'Ahazija, sin Ahabov, je zakraljeval nad Izraelom v Samariji v sedemnajstem letu Josafata, kralja Judovega, in je vladal Izraelu dve leti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (11, 22, 53, 'in delal, kar je bilo hudo v očeh Gospodovih, hodeč po poti očeta svojega in po poti matere svoje in po poti Jeroboama, sinu Nebatovega, ki je zapeljeval Izraela v greh. In služil je Baalu in se mu poklanjal in dražil v jezo Gospoda, Boga Izraelovega, po vsem, kakor je bil delal oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 1, 'In po smrti Ahabovi so se izneverili Moabci Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 2, 'In Ahazija je padel skozi omrežje v svoji zgornji sobi v Samariji in je zbolel. In pošlje sle ter jim veli: Pojdite, vprašajte Baalzebuba, boga v Ekronu, ali ozdravim od te bolezni svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 3, 'Angel Gospodov pa reče Eliju Tisbljanu: Vstani, pojdi naproti slom kralja samarijskega in jim reci: Ni li Boga v Izraelu, da greste vpraševat Baalzebuba, boga v Ekronu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 4, 'Zatorej pravi tako Gospod: Ne vstaneš iz postelje, v katero si legel, temuč gotovo umrješ! In Elija je šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 5, 'In ko se sli vrnejo h kralju, jih vpraša: Kaj da ste se vrnili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 6, 'Oni mu reko: Neki mož nam je prišel naproti in nam je dejal: Pojdite, vrnite se h kralju, ki vas je poslal, in mu recite: Tako pravi Gospod: Ni li Boga v Izraelu, da pošiljaš vpraševat Baalzebuba, boga v Ekronu? Zato ne vstaneš iz postelje, v katero si legel, temuč gotovo umrješ!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 7, 'In jih vpraša: Kakšne podobe in obleke je bil mož, ki vam je prišel naproti in vam to govoril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 8, 'In mu odgovore: Lasat mož je bil in opasan z usnjenim pasom okoli ledij. In reče: Elija Tisbljan je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 9, 'Tedaj pošlje kralj petdesetnika in njegovih petdeset mož. Ta gre gori k njemu, in glej, on sedi na vrhu gore. In mu reče: Mož Božji, kralj je ukazal: Pojdi doli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 10, 'In Elija odgovori in reče petdesetniku: Ako sem mož Božji, naj švigne ogenj doli z neba in požre tebe in tvoje petdesetere. In švigne ogenj z neba in požre njega in petdesetere njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 11, 'In zopet pošlje k njemu drugega petdesetnika ž njegovo petdeseterico. In izpregovori in mu reče: Mož Božji, tako je ukazal kralj: Hitro pojdi doli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 12, 'In Elija odgovori in mu veli: Ako sem mož Božji, naj švigne ogenj doli z neba in požre tebe in tvoje petdesetere. In ogenj švigne z neba in požre njega in petdesetere njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 13, 'In zopet pošlje tretjega petdesetnika ž njegovo petdeseterico. In ko pride gori tretji petdesetnik, pade na kolena pred Elijem in ga prosi in mu reče: Mož Božji, prosim, bodi pred teboj drago življenje moje in teh petdesetih hlapcev tvojih življenje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 14, 'Glej, ogenj je prišel z neba in požrl prva dva petdesetnika in petdesetere, ki so bili ž njima; sedaj pa bodi drago življenje moje pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 15, 'In angel Gospodov govori Eliju: Pojdi doli ž njim in ne boj se ga! Vstane torej in gre ž njim doli h kralju');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 16, 'in mu reče: Tako pravi Gospod: Ker si poslal sle vprašat Baalzebuba, boga v Ekronu, kakor da ni nobenega Boga v Izraelu, za čigar besedo bi se vprašalo, zato ne vstaneš iz postelje, v katero si legel, temuč gotovo umrješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 17, 'Tako je umrl po besedi Gospodovi, ki jo je bil govoril Elija. In Joram je zakraljeval na mestu njegovem v drugem letu Jorama, sina Josafata, kralja na Judovem; kajti ni imel sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 1, 18, 'Druge zgodbe Ahazijeve pa, kaj je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 1, 'Zgodi se pa, ko je hotel Gospod vzeti Elija v viharju gori v nebesa, da je šel Elija z Elizejem iz Gilgala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 2, 'In Elija veli Elizeju: Ostani tukaj, prosim; zakaj Gospod me je poslal tja do Betela. A Elizej reče: Kakor res živi Gospod in kakor živi tvoja duša, jaz te ne zapustim. Gresta torej doli v Betel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 3, 'In proroški sinovi, ki so bili v Betelu, pridejo ven k Elizeju in mu reko: Veš li pa, da vzame danes Gospod tvojega učenika od tebe? On reče: Saj jaz vem, le molčite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 4, 'In Elija mu veli: Elizej, prosim, ostani tukaj; zakaj Gospod me je poslal v Jeriho. On reče: Kakor res živi Gospod in kakor živi duša tvoja, jaz te ne zapustim. In prideta v Jeriho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 5, 'In proroški sinovi, ki so bili v Jerihu, pristopijo k Elizeju in mu reko: Veš li pa, da vzame danes Gospod tvojega učenika od tebe? In odgovori: Saj jaz vem, le molčite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 6, 'In Elija mu veli: Ostani, prosim, tukaj; zakaj Gospod me je poslal k Jordanu. On reče: Kakor res živi Gospod in kakor živi duša tvoja, jaz te ne zapustim. In gresta obadva naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 7, 'A petdeset mož izmed proroških sinov je šlo, in postavijo se v nekoliki daljavi nasproti njima; onadva pa sta stala pri Jordanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 8, 'Tedaj vzame Elija svoj plašč ter ga zvije skup in udari ž njim ob vodo, in se razdeli na obe strani, in onadva preideta po suhem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 9, 'In ko sta šla na drugo stran, reče Elija Elizeju: Prosi, kaj naj ti storim, preden bodem vzet od tebe! In Elizej reče: Prosim, da dobim dvojen delež od tvojega duha!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 10, 'Odgovori: Težke reči si prosil; če me boš videl, kadar bom vzet od tebe, se ti zgodi; ako pa ne, ne bode tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 11, 'In ko gresta še skupaj in se pogovarjata, glej, ognjen voz in ognjeni konji, ki ju ločijo narazen. In Elija je šel v viharju gori v nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 12, 'In Elizej je videl to in je klical: Oče moj, oče moj! Vozovi Izraelovi in jezdeci njegovi! In ni ga videl več. Tedaj prime oblačila svoja ter jih raztrga na dva kosa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 13, 'In vzdigne plašč Elijev, ki mu je spadel, in se vrne ter stopi na breg Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 14, 'In vzame plašč Elijev, ki mu je spadel, in udari vodo in reče: Kje je Jehova, Bog Elijev? In ko je tudi udaril vodo, se razdeli na obe strani, in Elizej preide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 15, 'In ko ga vidijo proroški sinovi, ki so stali pri Jerihu njemu nasproti, reko: Duh Elijev počiva nad Elizejem. In pridejo mu naproti in se mu poklonijo do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 16, 'In mu reko: Glej, med nami, hlapci tvojimi, je petdeset močnih mož; naj gredo, prosimo, in iščejo učenika tvojega! Morda ga je duh Gospodov vzel in vrgel kje na goro ali v dolino. On pa veli: Nikar ne pošiljajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 17, 'Ali oni so silili vanj, da ga je bilo sram. In reče: Naj gredo! Pošljejo torej petdeset mož; ti ga iščejo tri dni, a ga ne najdejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 18, 'In ko se vrnejo k njemu (stanoval je pa v Jerihu), jim reče: Nisem vam li rekel, da ne hodite?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 19, 'In možje iz mesta reko Elizeju: Glej, prosimo, v tem mestu je dobro prebivati, kakor vidi gospod moj, ali voda je nezdrava in zemlja nerodovitna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 20, 'On veli: Prinesite mi novo čašo in denite soli vanjo! In mu prineso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 21, 'On pa gre ven k studencu in vrže vanj soli in reče: Tako pravi Gospod: Ozdravil sem to vodo, odslej ne bo iz nje več smrti ali nerodovitnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 22, 'In voda je bila zdrava do tega dne po besedi Elizeja, ki jo je bil govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 23, 'In šel je odondod gori v Betel. Ko pa gre gori po poti, pridejo mali dečki iz mesta in ga zasmehujejo in mu govore: Plešivec, pridi gori! Plešivec, pridi gori!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 24, 'In se ozre, in ko jih vidi, jih prekolne v imenu Gospodovem. In prideta dve medvedki iz gozda in raztrgata izmed njih dvainštirideset otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 2, 25, 'In šel je odtod na goro Karmel in odondod se je vrnil v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 1, 'Joram pa, sin Ahabov je zakraljeval nad Izraelom v Samariji v osemnajstem letu Josafata, kralja na Judovem, in je vladal dvanajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 2, 'In delal je, kar je bilo hudo v očeh Gospodovih, pa ne kakor oče njegov in mati njegova; kajti odpravil je Baalov steber, ki ga je bil naredil oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 3, 'Vendar pa se je oklepal grehov Jeroboama, sinu Nebafovega, s katerimi je ta zapeljeval v greh Izraela, ni jih opustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 4, 'Mesa pa, kralj Moabcev, je redil veliko ovac in je dajal kralju Izraelovemu volne od stotisoč jagnjet in od stotisoč ovnov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 5, 'Ko pa je Ahab umrl, se je izneveril moabski kralj kralju Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 6, 'V tem času je šel kralj Joram iz Samarije in preštel vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 7, 'In pošlje k Josafatu, kralju Judovemu, in mu sporoči: Kralj Moabcev se mi je izneveril; pojdeš li z menoj bojevat se zoper Moabce? On reče: Pojdem; bodem naj kakor ti, ljudstvo moje naj bo kakor ljudstvo tvoje, konji moji kakor konji tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 8, 'In vpraša: Po katerem potu pojdemo gori? Odgovori: Po poti Edomske puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 9, 'Gredo torej kralj Izraelov, kralj Judov in kralj edomski. In ko so hodili sedem dni okrog, ni bilo vode za vojsko in živino, ki je šla za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 10, 'In kralj Izraelov reče: Gorje! Gospod je sklical te tri kralje, da jih izda Moabcem v pest!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 11, 'Josafat pa reče: Ni li tu proroka Gospodovega, da vprašamo po njem Gospoda? In odgovori eden iz hlapcev kralja Izraelovega in reče: Elizej, sin Safatov, je tu, ki je vlival vodo Eliju na roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 12, 'Josafat pa reče: Pri njem je beseda Gospodova. Gredo torej doli k njemu kralj Izraelov in Josafat in kralj edomski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 13, 'A Elizej veli kralju Izraelovemu: Kaj imam s teboj? Pojdi k prorokom očeta svojega in k prorokom matere svoje! Kralj Izraelov mu reče: Nikar! Ni li Gospod poklical teh treh kraljev, da jih izda Moabcem v pest?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 14, 'Elizej reče: Kakor res živi Gospod, ki stojim pred njega obličjem, ako bi se ne oziral na Josafata, kralja Judovega, na tebe bi se ne ozrl, ne te pogledal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 15, 'Zdaj pa mi pripeljite igralca na strune! In ko je igralec udarjal na strune, je prišla nad njega roka Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 16, 'In veli: Tako pravi Gospod: Naredite v tej dolini struge tu in tam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 17, 'Kajti tako pravi Gospod: Ne boste videli ne vetra, ne dežja, in vendar se ta dolina napolni z vodo, da boste pili vi in vaša drobnica in goved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 18, 'To pa je še malo v očeh Gospodovih; on izda tudi Moabce vam v roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 19, 'da udarite vsako utrjeno mesto in vsako izbrano mesto in posekate vsako dobro drevo in zamašite vse studence in pokvarite vsako dobro njivo s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 20, 'In zgodilo se je zjutraj, ob času jedilne daritve, glej, voda se privali po edomski poti in se razlije po tistem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 21, 'Ko pa slišijo vsi Moabci, da se gredo kralji bojevat zoper nje, skličejo vse, ki so mogli nositi orožje, in še druge, ter stopijo na mejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 22, 'In ko zgodaj zjutraj vstanejo in solnce zasije nad vodo, se zdi Moabcem, da je voda njim nasproti rdeča kakor kri;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 23, 'in reko: To je kri! Kralji so se pač bojevali med seboj in ubili drug drugega. Sedaj pa, Moab, precej na plen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 24, 'Ko pa pridejo k taboru Izraelovemu, se vzdignejo Izraelci in pobijajo Moabce, da zbeže pred njimi; in oni pridero v Moabsko deželo ter jih pobijajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 25, 'In razvalijo mesta in na vsako dobro njivo mečejo vsi kamenje, da so ga bile polne, in zamaše vse studence in posekajo vsa dobra drevesa – da so ostali samo v Kir-haresetu še kameni; toda pračarji so ga obdali in streljali nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 26, 'In ko je videl moabski kralj, da je bitka prehuda zanj, vzame s seboj sedemsto mož, oboroženih z mečem, da se pririje do kralja edomskega; a niso mogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 3, 27, 'Tedaj vzame sina svojega prvenca, ki je imel kraljevati na mestu njegovem, in ga daruje v žgalno žrtev vrh zidu. In pride velika jeza zoper Izraela; in odrinejo od njega in se povrnejo v deželo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 1, 'Neka žena pa izmed žen proroških sinov kliče k Elizeju in reče: Hlapec tvoj, moj mož, je umrl, ti pa veš, da se je bal hlapec tvoj Gospoda. Pa je prišel upnik in hoče vzeti oba otroka moja sebi za hlapca!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 2, 'Elizej ji reče: Kaj naj ti storim? Povej mi, kaj imaš v hiši? Odgovori: Dekla tvoja nima ničesar v hiši kakor le vrček olja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 3, 'Tedaj veli: Pojdi, naprosi si zunaj posod od vseh svojih sosed, praznih posod in nikar le malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 4, 'In stopi noter in zakleni duri za seboj in za sinoma svojima in potem nalij vse te posode; in katera bo polna, jo postavi vstran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 5, 'In odide od njega ter zaklene duri za sabo in za sinoma svojima; ta ji prinašata posode in ona naliva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 6, 'In ko so bile posode polne, veli sinu svojemu: Še mi podaj posodo! A on ji reče: Ni več posode tu! In olje se ustavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 7, 'Nato gre in naznani možu Božjemu. On reče: Pojdi, prodaj olje in poplačaj dolg; in kar ostane, ob tem se živi s svojima sinoma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 8, 'In nekega dne gre Elizej skozi Sunam, in ondi je bila bogata žena; ta ga pridrži, da bi pri njej jedel. In kadarkoli je poslej šel mimo, je stopil k njej in zaužil kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 9, 'In ona reče možu svojemu: Glej, spoznavam, da je to svet mož Božji, ki vedno hodi mimo nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 10, 'Narediva mu, prosim, zidano zgornjo izbico in vanjo mu postavimo posteljo, mizo, stol in svečnik; in kadar pride k nam, naj vstopi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 11, 'In ko je neki dan dospel k njima, stopi v zgornjo izbico in tam počiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 12, 'Potem veli hlapcu svojemu Gehaziju: Pokliči to Sunamljanko! In ko jo pokliče, stopi ona predenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 13, 'In on mu veli: Reci ji, prosim: Glej, trudila si se za naju z vso to postrežbo; morem li kaj zate storiti? Ali naj govorim zate s kraljem ali s poveljnikom vojske? Ona odgovori: Prebivam sredi svojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 14, 'In on vpraša: Kaj torej naj se stori zanjo? Gehazi odgovori: Pač nekaj! Sina nima, in njen mož je star!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 15, 'In veli: Pokliči jo! In ko jo pokliče, stopi ona med duri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 16, 'In ji reče: Ko se ponovi ta čas, čez leto, boš pestovala sina! Ona reče: Nikar, gospod moj, mož Božji, ne laži dekli svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 17, 'A žena spočne in rodi sina ob tem času, ko se je ponovilo leto, kakor ji je bil rekel Elizej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 18, 'In ko je deček odrastel, se prigodi nekega dne, da gre ven k očetu svojemu, k ženjcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 19, 'Tu reče očetu svojemu: O glava moja, glava moja! On pa veli hlapcu: Nesi ga k materi njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 20, 'Ta ga vzdigne in odnese materi njegovi. Ona ga posadi na kolena svoja do opoldne, in nato je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 21, 'In ona stopi gori in ga položi na posteljo moža Božjega, zaklene in odide ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 22, 'In kliče možu svojemu in reče: Pošlji mi, prosim, enega izmed hlapcev in oslico, da pohitim do moža Božjega in se zopet vrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 23, 'On vpraša: Čemu hočeš k njemu danes? Saj ni mlaj, ne sobota. Ona reče: Dobro bode!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 24, 'In osedla oslico in veli hlapcu svojemu: ženi hitro naprej in ne zadržuj me v ježi, razen če ti povem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 25, 'Odpravi se torej in pride k možu Božjemu na goro Karmel. Ko jo zagleda mož Božji oddaleč, reče Gehaziju, hlapcu svojemu: Glej, tam je Sunamljanka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 26, 'Sedaj pa ji teci, prosim, naproti in jo vprašaj: Se ti li godi dobro? Dobro li možu tvojemu? Dobro li je dečku? Ona odgovori: Dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 27, 'Ko pa pride do moža Božjega na goro, se oklene nog njegovih. In Gehazi pristopi, da bi jo odrinil. Ali mož Božji veli: Pusti jo! kajti njena duša je v bridkosti, in Gospod mi je prikril in mi ni naznanil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 28, 'Tedaj reče ona: Sem li mar gospoda svojega prosila sina? Nisem li rekla, da me ne varaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 29, 'Nato veli on Gehaziju: opaši si ledja in vzemi palico mojo v roko in pojdi tja! Ako te kdo sreča, ga ne pozdravi, in če te kdo pozdravi, ga ne zahvali, in položi mojo palico dečku na obraz!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 30, 'A mati dečkova reče: Kakor res živi Gospod in kakor živi duša tvoja, tebe jaz te ne pustim! Vstane torej in gre zanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 31, 'Gehazi pa ju je bil prešel in položil palico dečku na obraz, a ni bilo glasu, ne čuta. Zatorej se vrne in mu pride naproti in mu pove, rekoč: Deček se ni prebudil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 32, 'In ko pride Elizej v hišo, glej, deček leži mrtev na postelji njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 33, 'In on stopi noter in zaklene duri pred njima obema in moli h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 34, 'In stopi gori in leže na dečka in položi usta svoja na njegova usta in oči svoje na njegove oči in roke svoje na njegove roke, in se razprostre nad njim, da se je ogrelo dečkovo meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 35, 'Potem se vzdigne in hodi po hiši sem in tja, in zopet stopi gori in se razprostre nad njim. In deček kihne sedemkrat, potem odpre oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 36, 'On pa pokliče Gehazija in veli: Pokliči to Sunamljanko! Pokliče jo torej, in ko pride noter k njemu, reče: Vzemi sina svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 37, 'Tedaj pristopi ona in mu pade pred noge in se prikloni do tal, nato vzame sina in odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 38, 'Elizej pa pride zopet v Gilgal. In bila je lakota v deželi, in proroški sinovi so sedeli pred njim; in veli svojemu hlapcu: Pristavi velik lonec in skuhaj jed iz zelenjadi proroškim sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 39, 'In eden gre na polje nabirat zelišč in najde nekaj kakor trto in nabere ž nje divjih buček polno oblačilo svoje; in ko se vrne, jih zreže v lonec za jed; niso namreč tega poznali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 40, 'In nalijejo možem, da bi jedli. In ko so jedli od te jedi, zavpijejo in reko: O mož Božji, smrt je v loncu! In niso mogli jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 41, 'On pa veli: Prinesite sem moke! In vrže moke v lonec in reče: Izlij ljudstvu, da bi jedli! In ni bilo nič hudega v loncu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 42, 'In pride mož iz Baal-salisa in prinese možu Božjemu od prvin svojih: dvajset ječmenovih kruhov in svežega klasja v vreči svoji. On pa veli: Daj ljudstvu, da bi jedli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 43, 'Njegov strežnik pa reče: Kaj? ali naj to dam sto možem? Pa on veli: Daj ljudstvu, da bi jedli! zakaj tako pravi Gospod: jedli bodo, in še preostane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 4, 44, 'Postavi torej prednje, in jedli so in je še ostalo po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 1, 'Naaman, poveljnik vojske sirskega kralja, je bil velik mož pri svojem gospodu in spoštovan, zakaj po njem je Gospod dal zmago Sircem; bil je tudi hraber vojščak, toda gobav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 2, 'Sirci pa so bili v plenilnih četah vdrli v Izraelovo deželo in ujeto s seboj pripeljali majhno deklico; in ta je stregla ženi Naamanovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 3, 'In reče gospodinji svoji: Ah, da bi bil gospod moj pri proroku, ki je v Samariji! Potem bi ga ozdravil njegovih gob!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 4, 'In Naaman gre noter h gospodu svojemu in mu pove, rekoč: Tako in tako je govorila deklica iz Izraelove dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 5, 'Nato veli sirski kralj: Odpravi se tja, jaz pošljem list kralju Izraelovemu. In odide, vzemši s seboj deset talentov srebra in šest tisoč zlatnikov in desetero prazničnih oblek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 6, 'In prinese list kralju Izraelovemu s tem besedilom: In sedaj, ko pride ta list do tebe, glej, poslal sem Naamana, služabnika svojega, k tebi, da ga ozdraviš njegovih gob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 7, 'Ko pa prebere kralj Izraelov ta list, si raztrga oblačila in reče: Ali sem Bog, da morem usmrtiti in oživiti, da ta pošilja k meni moža, naj ga ozdravim gob? Pa premislite, prosim, in glejte, da išče razloga za boj z menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 8, 'Ali ko Elizej, mož Božji, zasliši, da je kralj Izraelov raztrgal oblačila svoja, pošlje h kralju in sporoči: Zakaj si raztrgal oblačila svoja? Naj le pride k meni, in spozna, da je prorok v Izraelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 9, 'Tedaj pride Naaman s konji svojimi in z vozovi svojimi ter se ustavi pri vratih Elizejeve hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 10, 'Elizej pa pošlje sla k njemu, veleč: Pojdi in umij se v Jordanu sedemkrat, in meso se ti obnovi in bodeš čist!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 11, 'A Naaman se ujezi in odhajajoč govori: Glejte, menil sem, da pride gotovo ven k meni in pristopi in bo, klical ime Gospoda, Boga svojega, in potegne roko svojo čez boleznivino, in tako ozdravi gobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 12, 'Nista li Abana in Farfar, reki v Damasku, boljši nego vse vode Izraelove, da bi se v njiju umil in se očistil? Obrne se torej in jezen hoče oditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 13, 'Hlapci njegovi pa pristopijo in govore ž njim in reko: Oče moj, ako bi ti bil prorok ukazal kaj velikega, ne bi bil storil tega? Koliko bolj, ko ti je rekel samo: Umij se in bodi čist!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 14, 'Tedaj gre doli in se pogrezne sedemkrat v Jordanu, kakor je velel mož Božji: in meso se mu zopet naredi kakor majhnega dečka meso, in bil je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 15, 'In vrne se k možu Božjemu, on in vse spremstvo njegovo. In vstopi in se postavi predenj ter reče: Glej, sedaj vem, da ni Boga na vsej zemlji, samo v Izraelu! Zdaj torej vzemi, prosim, darilo od hlapca svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 16, 'On pa reče: Kakor res živi Gospod, ki stojim pred njega obličjem, ničesar ne vzamem! In ga sili, naj vzame, pa on odkloni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 17, 'Nato reče Naaman: Če torej nočeš, daj, prosim, hlapcu svojemu prsti, kolikor je moreta nesti dva mezga; zakaj hlapec tvoj ne bo odslej daroval žgalnih in klalnih žrtev drugim bogovom razen Gospodu samemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 18, 'Samo v tem bodi Gospod milostiv hlapcu tvojemu: Kadar gre moj gospodar v hišo Rimonovo molit in se nasloni na mojo roko in jaz se priklonim v hiši Rimonovi, naj prizanese Gospod temu priklanjanju mojemu v hiši Rimonovi iz tega razloga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 19, 'On mu veli: Pojdi v miru! In šel je od njega nekoliko poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 20, 'V tem si je rekel Gehazi, hlapec Elizeja, moža Božjega: Glej, gospodar moj je prevarčno ravnal s tem Naamanom Sircem, da ni vzel iz rok njegovih, kar je prinesel; kakor res Gospod živi, potečem za njim, da prejmem kaj od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 21, 'Žene se torej Gehazi za Naamanom: In ko Naaman in vidi, da teče nekdo za njim, stopi z voza in mu gre naproti ter vpraša: Je li dobro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 22, 'Ta reče: Dobro! Gospod moj me je poslal, naj sporočim: Glej, ravno sedaj sta k meni prišla dva mladeniča iz proroških sinov z Efraimskega gorovja. Daj jima, prosim, talent srebra in dve praznični obleki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 23, 'In Naaman veli: Izvoli vzeti dva talenta! In ga prisili ter mu zaveže dva talenta srebra v dve mošnji in dve praznični obleki in ju zadene dvema njegovima hlapcema; in ona to neseta pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 24, 'In ko pride do hriba, vzame to iz njunih rok in odloži v hišo; potem odpusti moža, in sta odšla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 25, 'A sam stopi noter in se postavi pred svojega gospodarja. Tedaj mu reče Elizej: Odkod si prišel, Gehazi? Odgovori: Hlapec tvoj ni hodil ne sem, ne tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 26, 'On pa mu veli: Ni li šlo srce moje s teboj, ko se je vrnil mož z voza svojega tebi naproti? Je li čas jemati srebro in oblačila in pridobivati oljkove vrte in vinograde, ovce in vole, hlapce in dekle?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 5, 27, 'Zatorej se bodo gobe Naamanove prijele tebe in semena tvojega vekomaj! In šel je od njega ven gobav in bel kakor sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 1, 'In proroški sinovi reko Elizeju: Glej vendar, kraj, kjer stanujemo pred teboj, je nam pretesen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 2, 'Dovoli, da gremo k Jordanu, in ondi naj vzame vsak lesa, in naredimo si tam domovališče. On odgovori: Pojdite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 3, 'Eden pa reče: Izvoli, prosim, iti s hlapci svojimi! Odgovori: Pojdem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 4, 'In šel je ž njimi. In ko pridejo doli k Jordanu, sekajo les.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 5, 'In ko eden seka drevo, mu pade železo v vodo, in zavpije in reče: Gorje, moj gospod, saj še to sem vzel naposodo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 6, 'A mož Božji vpraša: Kam je padlo? In pokaže mu tisti kraj. On pa odreže palico in jo porine tja in stori, da železo splava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 7, 'In veli: Vzdigni si ga! In iztegne roko ter ga vzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 8, 'Kralj sirski pa se je bojeval zoper Izraela; in se je posvetoval s služabniki svojimi in je rekel: Na tem in tem mestu bodi moj tabor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 9, 'A mož Božji pošlje h kralju Izraelovemu in sporoči: Varuj se, da ne greš na tisto mesto, kajti tja so se odpravili Sirci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 10, 'In kralj Izraelov je poslal na mesto, ki mu je o njem mož Božji bil povedal in ga posvaril, in se ga je ognil ne enkrat ali dvakrat samo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 11, 'In sirskemu kralju se je srce hudo vznemirilo zaradi tega; in pokliče služabnike svoje in jim veli: Mi li nočete povedati, kdo je od naših zvezan s kraljem Izraelovim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 12, 'Eden služabnikov njegovih pa mu reče: Ni tako, gospod moj, kralj, temuč Elizej prorok, ki je v Izraelu, pravi kralju Izraelovemu besede, ki jih govoriš v svoji spalnici!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 13, 'Kralj veli: Pojdite in poglejte, kje je, da pošljem in ga ujamem. In naznanijo mu, rekoč: Glej, v Dotanu je!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 14, 'Zatorej pošlje tja konje in vozove in veliko vojsko, in pridejo ponoči ter obkolijo mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 15, 'In ko vstane strežnik moža Božjega zarana in gre ven, vidi vojsko s konji in vozovi okoli mesta. In strežnik njegov mu reče: Gorje, gospod moj, kaj bomo počeli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 16, 'On odgovori: Ne boj se, zakaj več jih je z nami nego ž njimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 17, 'In Elizej moli in reče: Gospod, prosim, odpri mu oči, da bo videl. In Gospod je odprl mladeniču oči, in je videl, in glej: gora je bila polna konj in ognjenih voz okoli Elizeja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 18, 'In ko pridejo do njega, moli Elizej h Gospodu in reče: Udari, prosim, ta narod s slepoto! In udaril jih je s slepoto po besedi Elizejevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 19, 'In Elizej jim reče: To ni tista pot, ne tisto mesto; pojdite za menoj in privedem vas k možu, ki ga iščete. In pripelje jih v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 20, 'Ko pa pridejo v Samarijo, reče Elizej: Gospod, odpri oči tem možem, da vidijo. In Gospod je odprl njih oči, in videli so, in glej, bili so sredi Samarije!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 21, 'In ko jih ugleda kralj Izraelov, reče Elizeju: Ali naj jih pobijem, oče moj? Naj jih pobijem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 22, 'On odgovori: Ne pobijaj jih! Ali bi pobil tiste, ki si jih ujel z mečem in z lokom svojim? Postavi prednje kruha in vode, da jedo in pijo in se povrnejo h gospodu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 23, 'In jim je pripravil veliko gostovanje. In ko so bili jedli in pili, jih je odpustil, in šli so h gospodu svojemu. In sirske čete niso več vdirale v deželo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 24, 'In zgodi se potem, da zbere Ben-hadad, sirski kralj, vso vojsko in gre gori ter oblega Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 25, 'In nastane velika lakota v Samariji, in glej, oblegali so Samarijo toliko časa, da se je prodajala oslovska glava za osemdeset srebrnikov in četrtinka golobje piče za pet srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 26, 'In ko je kralj Izraelov šel mimo po zidovju, zavpije vanj žena in reče: Pomozi mi, gospod moj, kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 27, 'On pa reče: Ko ti Gospod ne pomore, odkod naj ti pomorem jaz? z gumna ali iz tlačilnice?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 28, 'In kralj jo vpraša: Kaj ti je? Ona reče: Ta žena mi je rekla: Daj sina svojega, da ga sneva danes, in mojega sina bova jedli jutri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 29, 'Skuhali sva torej mojega sina in ga snedli. In drugi dan ji velim: Daj sem sina svojega, da ga sneva! A ona ga je skrila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 30, 'Ko je slišal kralj besede žene, si je raztrgal oblačila; šel pa je naprej po zidovju, in ljudstvo je gledalo, in glej, imel je znotraj raševnik po životu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 31, 'Tedaj reče kralj: Bog mi stóri to in to še prideni, ako danes ostane glava Elizeja, sina Safatovega, na njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 32, 'Elizej pa je sedel v hiši svoji, in starejšine so sedeli pri njem. In kralj pošlje sla pred seboj; a preden dospe sel k njemu, reče Elizej starejšinam: Ne vidite li, kako je poslal tisti morilčev sin, da se mi odseka glava? Glejte, ko pride sel, da zaprete duri in ga z durmi nazaj pahnete! Ni li šum nog gospoda njegovega za njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 6, 33, 'Ko ž njimi še govori, glej, pride sel doli k njemu. In reče: Glej, to hudo je od Gospoda, čemu naj še čakam Gospoda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 1, 'Tedaj reče Elizej: Čujte besedo Gospodovo: Tako pravi Gospod: Jutri ob tem času bode mera bele moke po seklu in dve meri ječmena po seklu pri samarijskih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 2, 'Nato odgovori vojvoda, na čigar roko se je kralj naslanjal, možu Božjemu in reče: Glej, ko bi Gospod odprl zatvornice na nebu, bi li moglo to biti? On pa reče: Glej, videl boš s svojimi očmi, a ne boš jedel od tega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 3, 'Bili so pa štirje gobavci pred vhodom v vrata Samarije; in reko drug drugemu: Kaj tu sedimo, dokler umrjemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 4, 'Ako bi rekli: Pojdimo v mesto, lakota je v mestu, in tam nam je umreti; ako pa ostanemo tu, moramo tudi umreti! Pojdimo torej, vrinimo se v vojsko Sircev! Ako nas ohranijo v življenju, bomo živeli, ako nas pobijejo, umrjemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 5, 'Vstanejo torej v mraku, da bi šli v tabor Sircev. In ko pridejo do skrajnega konca v taborišču Sircev, glej, ni tu nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 6, 'Gospod je namreč dal sirski vojski slišati ropot voz in topotanje konj in hrup vojske velike; in rekli so drug drugemu: Glej, kralj Izraelov je najel zoper nas kralje Hetejcev in kralje Egipčanov, da pridero nad nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 7, 'Zato so vstali in pobegnili v mraku, zapustivši svoje šatore in svoje konje in osle v taboru, kakor je bil, in so bežali, da si otmo življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 8, 'Ko torej pridejo oni gobavci na skrajni konec taborišča, stopijo v najbližji šator, jedo in pijejo in odneso odtod srebro, zlato in oblačil ter gredo in skrijejo to; in pridejo zopet in stopijo v drugi šator in pobero ravno tako, odneso in skrijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 9, 'Tedaj reko drug drugemu: Ne delamo prav. Ta dan je veselega poročila dan, in mi molčimo, ako počakamo do jutranjega svita, nas doleti kazen. Sedaj torej pridite, pojdimo in naznanimo to hiši kraljevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 10, 'In pridejo in kličejo mestni straži, in povedo jim, rekoč: Prišli smo do tabora Sircev, in glej, ni bilo ondi nikogar, ne glasu človeškega, samo konji in osli privezani in šatori, kakor so bili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 11, 'In kličejo vratarjem, in ti povedo notri kraljevi družini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 12, 'In kralj vstane po noči ter reče hlapcem svojim: Povem vam zdaj, kaj so nam naredili Sirci. Vedo, da trpimo lakoto, zato so šli ven iz tabora in se poskrili na polju, češ: kadar pridejo iz mesta, jih ujamemo žive in se spravimo v mesto!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 13, 'Nato odgovori eden hlapcev njegovih in reče: Vzemimo petere ostale konje, ki so preostali v mestu (glej, godi se jim kakor vsej množici Izraelovi, ki je ostala v njem; glej, godi se jim kakor vsej množici Izraelovi, ki je poginila), te pošljimo in oglejmo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 14, 'Tedaj vzamejo dva, voza s konji, in kralj jih pošlje za sirsko vojsko, rekoč: Pojdite in oglejte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 15, 'In šli so za njimi do Jordana, in glej, vsa pot je bila polna oblačil in orodja, ki so ga Sirci od sebe vrgli v naglici svoji. In poslanci se vrnejo in sporoče kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 16, 'Tedaj gre ljudstvo ven in opleni tabor Sircev. In bila je mera bele moke po seklu in dve meri ječmena po seklu, kakor je bil rekel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 17, 'Kralj pa je postavil tistega vojvodo, na čigar roko se je naslanjal, da nadzoruje pri vratih; a ljudstvo ga je pogazilo med vrati, da je umrl, kakor je napovedal mož Božji v govoru svojem, ko je bil prišel k njemu kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 18, 'Kajti izpolnilo se je, kar je bil mož Božji povedal kralju, rekoč: Dve meri ječmena bosta po seklu in mera bele moke po seklu jutri ob tem času pri samarijskih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 19, 'In tisti vojvoda je odgovoril možu Božjemu in rekel: Pa glej, ko bi Gospod odprl zatvornice na nebu, bi li moglo to biti? On pa mu je rekel: Glej, videl boš s svojimi očmi, a ne boš jedel od tega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 7, 20, 'In tako se mu je zgodilo: kajti ljudstvo ga je pogazilo med vrati, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 1, 'In Elizej je bil dejal ženi, ki ji je sina oživil, rekoč: Vstani in odidi ti in družina tvoja in bivaj v tujini, kjerkoli moreš; zakaj Gospod je poklical lakoto, ki tudi pride v deželo in bo trpela sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 2, 'In žena vstane ter stori po besedi moža Božjega in odide z družino svojo in biva kot tujka v deželi Filistejcev sedem let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 3, 'Ko pa mine sedem let, se povrne iz dežele Filistejcev in gre, da se oglasi pri kralju za hišo in za njivo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 4, 'Kralj pa je ravnokar govoril z Gehazijem, hlapcem moža Božjega, in rekel: Pripoveduj mi, prosim, vse velike reči, ki jih je storil Elizej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 5, 'In zgodi se, ko pripoveduje kralju, kako je oživil mrtvega, glej, žena, ki ji je sina privedel v življenje, pride prosit kralja hiše svoje in njive svoje. Tedaj reče Gehazi: Gospod moj, kralj, tu je tista žena, in ta je njen sin, ki ga je oživil Elizej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 6, 'In kralj jo vpraša, in ona mu po vrsti pove. Nato ji kralj določi dvornika in mu veli: Povrni ji vse, kar je njenega, tudi vse pridelke njive od časa, ko je zapustila deželo, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 7, 'In Elizej pride v Damask. Ben-hadad, kralj sirski, pa je bil bolan; in so mu povedali, rekoč: Mož Božji je prišel sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 8, 'In kralj veli Hazaelu: Vzemi darilo v roko in pojdi naproti možu Božjemu in vprašaj Gospoda po njem in reci: Ali ozdravim od te bolezni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 9, 'Hazael mu torej gre naproti, vzemši s seboj daril od vsega blaga iz Damaska, tovora na štiridesetih velblodih; in pride in stopi predenj in reče: Sin tvoj Ben-hadad, kralj sirski, me je poslal k tebi, rekoč: Ali ozdravim od te bolezni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 10, 'In Elizej mu reče: Pojdi, reci mu: Gotovo ozdraviš. Toda Gospod mi je pokazal, da gotovo umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 11, 'In prorok vpre oči vanj in ga trdno gleda, da ga je bilo sram; in mož Božji se razjoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 12, 'In Hazael vpraša: Zakaj joče gospod moj? Odgovori: Ker vem, koliko zlega storiš sinovom Izraelovim: njih utrjena mesta požgeš z ognjem in njih mladeniče pobiješ z mečem in njih otročiče razbiješ ob skali in njih noseče prerežeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 13, 'In Hazael reče: Kaj je hlapec tvoj, ki je le pes, da bi storil to veliko reč? In Elizej odgovori: Gospod mi je pokazal, da bodeš kralj Siriji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 14, 'Tedaj odide od Elizeja in pride h gospodarju svojemu; ta ga vpraša: Kaj ti je rekel Elizej? On odgovori: Rekel mi je, da gotovo ozdraviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 15, 'Drugi dan pa vzame odejo in jo omoči v vodi ter mu jo razgrne čez obraz, da je umrl. In Hazael je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 16, 'V petem letu Jorama, sina Ahaba, kralja Izraelovega (ko je bil Josafat kralj Judov), je zakraljeval Joram, sin Josafata, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 17, 'Dvaintrideset let je imel, ko je zakraljeval, in vladal je osem let v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 18, 'In hodil je po potu kraljev Izraelovih, kakor je delala hiša Ahabova, kajti imel je hčer Ahabovo za ženo; in delal je, kar je bilo hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 19, 'Ali Gospod ni hotel uničiti Jude, zaradi Davida, hlapca svojega, kakor mu je bil obljubil, da mu da svetilo za sinove njegove vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 20, 'V njegovih dneh so odstopili Edomci izpod oblasti Judove in si postavili kralja zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 21, 'Tedaj je šel Joram proti Zairu in vsi vozovi njegovi ž njim; in vzdignil se je po noči ter pobil Edomce, ki so ga obdajali, in tudi poveljnike njih vozovom. In ljudstvo je bežalo v šatore svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 22, 'Vendar so se Edomci upirali oblasti Judovi do tega dne. Tudi Libna se je uprla v tistem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 23, 'A druge zgodbe Joramove in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 24, 'In legel je Joram k očetom svojim, in pokopali so ga z očeti njegovimi v mestu Davidovem. In Ahazija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 25, 'V dvanajstem letu Jorama, sina Ahaba, kralja Izraelovega, je zakraljeval Ahazija, sin Jorama, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 26, 'Dvaindvajset let je imel Ahazija, ko je zakraljeval, in vladal je eno leto v Jeruzalemu. In materi njegovi je bilo ime Atalija, hči Omrija, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 27, 'In hodil je po poti hiše Ahabove, delajoč, kar je bilo hudo v očeh Gospodovih, kakor je delala Ahabova hiša, kajti bil je zet Ahabove hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 28, 'In šel je z Joramom, sinom Ahabovim, na vojno zoper Hazaela, kralja sirskega, v Ramot v Gileadu; in Sirci so ranili Jorama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 8, 29, 'In vrnil se je kralj Joram, da bi si lečil v Jezreelu rane, ki so mu jih Sirci zadeli v Rami, ko se je bojeval s sirskim kraljem Hazaelom. Ahazija pa, sin Jorama, kralja Judovega, je prišel doli obiskat Jorama, sina Ahabovega, v Jezreelu, ker je ležal bolan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 1, 'Elizej prorok pa pokliče enega izmed proroških sinov in mu veli: Opaši si ledja in vzemi to oljenico v roko in pojdi v Ramot v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 2, 'In ko dospeš tja, poglej, kje je Jehu, sin Josafata, sina Nimsijevega, in stopi noter in véli mu vstati izmed bratov svojih in ga pelji v notranjo izbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 3, 'Potem vzemi oljenico in mu jo izlij na glavo in reci: Tako pravi Gospod: Pomazilil sem te za kralja Izraelu. Nato odpri duri in beži, nič se ne múdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 4, 'Gre torej tisti mladenič, mlad prorok, v Ramot v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 5, 'In ko pride tja, glej, vojni poglavarji so sedeli; in reče: Besedo imam do tebe, o poglavar! In Jehu vpraša: Do katerega nas vseh? Odgovori: Do tebe, o poglavar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 6, 'Tedaj vstane in stopi v hišo; on pa mu izlije olje na glavo in mu reče: Tako pravi Gospod, Bog Izraelov: Pomazilil sem te za kralja ljudstvu Gospodovemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 7, 'In udaril boš hišo Ahaba, gospoda svojega, da maščujem kri hlapcev svojih prorokov in kri vseh hlapcev Gospodovih nad Jezabelino roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 8, 'Kajti vsa hiša Ahabova pogine in pogubim od Ahabovih vsakega moškega, njega, ki je vklenjen, in njega, ki je prost v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 9, 'In naredim s hišo Ahabovo kakor s hišo Jeroboama, sina Nebatovega, in kakor s hišo Baasa sinu Ahijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 10, 'In psi bodo žrli Jezabelo na Jezreelski zemlji, in nikogar ne bode, ki bi jo pokopal. – Nato odpre duri in pobegne:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 11, 'Tedaj pride Jehu ven k služabnikom svojega gospoda, in eden ga vpraša: Je li mir? Zakaj je prišel ta neumnik k tebi? On pa jim reče: Saj poznate moža in govor njegov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 12, 'Oni reko: Lažeš; povej nam vendar! On reče: tako in tako je govoril z menoj in dejal: Tako pravi Gospod: Pomazilil sem te za kralja Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 13, 'Nato pohité in vsak vzame oblačilo svoje in ga dene podenj vrhu stopnic, ter zatrobijo v trobento in reko: Jehu je kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 14, 'Jehu torej, sin Josafata, sina Nimsijevega, je sklenil zaroto proti Joramu. (Joram pa je z vsem Izraelom stražil Ramot v Gileadu zaradi Hazaela, kralja sirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 15, 'A kralj Joram se je bil vrnil, da bi si zdravil v Jezreelu rane, ki so mu jih zadeli Sirci, ko se je bojeval s Hazaelom, sirskim kraljem.) Jehu pa je dejal: Ako je vaša volja, nihče naj ne ubeži in ne gre iz mesta, da bi povedal v Jezreelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 16, 'In Jehu stopi na voz in se pelje v Jezreel, zakaj Joram je ležal ondi. Ahazija pa, kralj Judov, je prišel doli obiskat Jorama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 17, 'In čuvaj, ki je stal na stolpu v Jezreelu, ugleda Jehujevo krdelo, da se bliža, in reče: Vidim neko krdelo. Tedaj veli Joram: Vzemi jezdeca in ga pošlji onim naproti, naj vpraša: Je li mir?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 18, 'In jezdec jim gre naproti in reče: Tako pravi kralj: Je li mir? Jehu pa odvrne: Kaj tebi do miru? Okreni se in hodi zadaj za menoj! In čuvaj to oznani, rekoč: Sel je prišel do njih, pa se ne vrača!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 19, 'Tedaj pošlje drugega jezdeca. Ta pride k njim in reče: Tako pravi kralj: Je li mir? Jehu odgovori: Kaj tebi do miru? Okreni se in hodi zadaj za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 20, 'In čuvaj to oznani, rekoč: Prišel je prav do njih, pa se ne vrača. Vožnja pa je kakor vožnja Jehuja, sina Nimsijevega; zakaj žene voz, kakor bi besnel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 21, 'In Joram veli: Zaprezite! In zaprežejo mu voz. In Joram, kralj Izraelov, in Ahazija, kralj Judov, se peljeta ven, vsak na vozu svojem, Jehuju naproti. In ga srečata na zemljišču Nabota Jezreelčana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 22, 'In ko Joram zagleda Jehuja, reče: Je li mir, Jehu? On pa odgovori: Kakšen mir, dokler je toliko nečistovanja in čarodejstva matere tvoje Jezabele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 23, 'Tedaj se obrne Joram, da zbeži, in reče Ahaziju: Izdajstvo je, o Ahazija!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 24, 'A Jehu prime krepko za lok in ustreli Jorama med pleča, da mu je šla pšica ven skozi srce, in zgrudil se je na vozu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 25, 'Nato veli Jehu Bidkarju, svojemu vojvodi: Vzemi in vrzi ga na zemljišče Nabota Jezreelčana; zakaj spomni se, ko sva jaz in ti jezdila skupaj za Ahabom, očetom njegovim, da je Gospod izrekel to grožnjo zoper njega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 26, 'Videl sem zares včeraj kri Nabotovo in kri sinov njegovih, govori Gospod; in poplačam ti na tem zemljišču, govori Gospod. Sedaj pa ga vzemi in vrzi na to zemljišče, po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 27, 'Ko pa je videl to Ahazija, kralj Judov, je zbežal po poti proti vrtni hiši. A Jehu se je gnal za njim in velel: Udarite tudi njega na vozu! In udarili so ga ob strmcu v Gur, ki je pri Ibleamu. In bežal je v Megido, in ondi je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 28, 'In hlapci njegovi so ga pripeljali na vozu v Jeruzalem in ga pokopali v grobu njegovem z njegovimi očeti v mestu Davidovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 29, 'Ahazija pa je bil zakraljeval nad Judom v enajstem letu Jorama, sina Ahabovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 30, 'In ko pride Jehu v Jezreel in Jezabel zasliši o tem, si namaže z lepotico obličje in nališpa glavo in gleda skozi okno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 31, 'In ko stopi Jehu v vrata, reče ona: Se li je dobro godilo Zimriju, morilcu gospoda svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 32, 'On pa povzdigne obličje proti oknu in reče: Kdo je z menoj? kdo? In pogledajo nanj dva ali trije komorniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 33, 'In on veli: Vrzite jo doli! In vrgli so jo doli, in stena je bila poškropljena ž njeno krvjo in konji; in jo je poteptal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 34, 'In ko je prišel noter, je jedel in pil, in je rekel: Poglejte vendar po tisti prokleti in pokopljite jo, ker kraljeva je hči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 35, 'In ko so jo šli pokopat, niso našli drugega od nje nego čepinjo in noge in dlani njenih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 36, 'Zato pridejo nazaj in mu povedo. On pa reče: Beseda Gospodova je, ki jo je govoril po hlapcu svojem, Eliju Tisbljanu, rekoč: Na Jezreelski zemlji bodo psi žrli Jezabelino meso');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 9, 37, 'in truplo Jezabelino bode kakor gnoj na površju polja, na Jezreelski zemlji, tako da ne bodo rekli: To je Jezabela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 1, 'Ahab pa je imel sedemdeset sinov v Samariji. In Jehu napiše liste in pošlje v Samarijo jezreelskim poglavarjem, namreč starejšinam in vzgojevalcem sinov Ahabovih, s tem besedilom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 2, 'Precej, ko prejmete ta list, ker so vašega gospoda sinovi pri vas in imate tudi vozove in konje, utrjeno mesto in orožje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 3, 'poglejte torej, kateri je najboljši in najpripravnejši izmed sinov gospoda vašega, in ga posadite na očeta njegovega prestol ter se bojujte za hišo gospoda svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 4, 'Oni pa se silno zboje in reko: Glejte, dva kralja nista mogla stati pred njim, kako naj mi stojimo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 5, 'In načelnik dvorca in mestni glavar in starejšine in vzgojevalci sinov pošljejo k Jehuju in sporoče: Hlapci smo tvoji in storimo vse, kar nam ukažeš. Ne postavimo nikogar za kralja. Stóri, kar se ti zdi prav!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 6, 'Tedaj jim napiše list v drugič s temi besedami: Ako ste na moji strani in hočete poslušati moj glas, vzemite glave tistih mož, sinov svojega gospoda, in pridite k meni v Jezreel jutri ob tem času! Bili so pa sinovi kraljevi, sedemdeset oseb, pri prvakih mesta, ki so jih vzgajali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 7, 'Ko so torej prejeli ta list, vzamejo kraljeve sinove in jih pobijejo, vseh sedemdesetero mož, in denejo njih glave v koše ter jih pošljejo k njemu v Jezreel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 8, 'In pride sporočnik ter mu naznani, rekoč: Prinesli so sinov kraljevih glave. On veli: Denite jih na dva kupa ob vhodu v vrata do jutra!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 9, 'Zjutraj pa, ko pride ven, se ustopi in reče vsemu ljudstvu: Pravični ste! Glejte, jaz sem napravil zaroto zoper gospodarja svojega in ga umoril. A kdo je pobil vse te?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 10, 'Vedite torej, da nič ne pade na zemljo iz besed Gospodovih, ki jih je govoril Gospod o hiši Ahabovi; zakaj Gospod je storil, kar je bil napovedal po hlapcu svojemu Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 11, 'Tako je pobil Jehu vse, ki so ostali od hiše Ahabove v Jezreelu, in vse prvake njegove in zaupnike in duhovnike njegove, da mu ni ostal ne eden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 12, 'In vstane in odide in gre v Samarijo. In ko je bil pri strižnici pastirjev ob potu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 13, 'sreča Jehu brate Ahazija, kralja Judovega, ter vpraša: Kdo ste? Odgovore: Bratje smo Ahazijevi in gremo doli pozdravljat sinove kraljeve in kraljice sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 14, 'In veli: Zgrabite jih žive! In zgrabili so jih žive in jih pomorili pri vodnjaku strižnice, dvainštirideset mož; ne enega od njih ni pustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 15, 'In ko gre odtod dalje, naleti na Jonadaba, sina Rehabovega, ki mu je šel naproti, in ga pozdravi in mu reče: Je li tvoje srce pošteno, kakor je moje srce proti tvojemu? In Jonadab odgovori: Je. Ako je, veli, podaj mi roko. In poda mu roko, in on ga vzame k sebi na voz');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 16, 'in reče: Pojdi z menoj in poglej gorečnost mojo za Gospoda! In so ga peljali na vozu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 17, 'In ko pride Jehu v Samarijo, pobije vse, kar jih je ostalo od Ahabovih v Samariji, da ga je dočista pogubil po besedi Gospodovi, ki jo je bil govoril Eliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 18, 'In Jehu skliče vse ljudstvo in jim reče: Ahab je malo služil Baalu, Jehu pa mu hoče bolj služiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 19, 'Zato mi sedaj skličite vse proroke Baalove, vse častilce in vse duhovnike njegove, da nikogar ne manjka, zakaj veliko daritev prinesem Baalu. Kogarkoli pogrešimo, ta ne bo živel. Ali Jehu je to storil zvito, da bi pokončal častilce Baalove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 20, 'In Jehu veli: Posvetite praznično zborovanje za Baala! In so ga oklicali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 21, 'Jehu pošlje tudi po vsem Izraelu, in vsi častilci Baalovi pridejo, da ni bilo moža, ki ne bi bil prišel. In šli so v hišo Baalovo, in hiša Baalova se je napolnila od konca do kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 22, 'In veli njemu, ki je bil nad oblačilnico: Prinesi oblačila vsem častilcem Baalovim! In prinese jim ven oblačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 23, 'In Jehu stopi z Jonadabom, sinom Rehabovim, v hišo Baalovo, in reče častilcem Baalovim: Preiščite in poglejte, da ne bo nikogar med vami izmed služabnikov Gospodovih, temuč da bodo Baalovi častilci sami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 24, 'In gredo noter darovat klalščine in žgalščine. Jehu pa si je postavil osemdeset mož zunaj; in jim reče: Ako kdo pobegne iz teh mož, ki vam jih izročam, življenje tistega, kdor ga pusti, bode za življenje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 25, 'In zgodi se, ko so končali darovanje žgalščine, da veli Jehu stražarjem in poveljnikom: Stopite noter in pobijte jih, da nihče ne uide! In jih udarijo z ostrino meča; in stražarji in poveljniki jih pomečejo ven. Nato gredo v mesto hiše Baalove');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 26, 'in prineso ven poslikane stebre, ki so bili v hiši Baalovi, ter jih sežgo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 27, 'In starejo steber Baalov in zrušijo hišo Baalovo ter narede iz nje stranišče do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 28, 'Tako je Jehu potrebil Baala iz Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 29, 'Toda od grehov Jeroboama, sina Nebatovega, ki je ž njimi zapeljeval v greh Izraela, ni odstopil Jehu, da bi ne hodil za zlatima teletoma, ki sta bili v Betelu in v Danu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 30, 'In Gospod je rekel Jehuju: Ker si dobro izvršil, kar je prav v mojih očeh, in si storil hiši Ahabovi po vsem, kar mi je bilo v srcu, bodo sedeli tvoji sinovi do četrtega roda na prestolu Izraelovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 31, 'Ali Jehu ni ohranil tega da bi bil živel po postavi Gospoda, Boga Izraelovega, z vsem srcem svojim: ni odstopil od grehov Jeroboamovih, ki je ž njimi zapeljeval v greh Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 32, 'V tistih dneh je začel Gospod prikrajševati Izraela; kajti Hazael jih je porazil po vseh mejah Izraelovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 33, 'ob Jordanu proti vzhodu vso deželo Gileadsko, Gadske, Rubenske in Manasejce, od Aroerja, ki je pri potoku Arnonu, Gileadsko in tudi Basansko deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 34, 'A druge zgodbe Jehujeve in vse, kar je storil, in vsa moč njegova, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 35, 'In Jehu je legel k očetom svojim, in pokopali so ga v Samariji. In Joahaz, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 10, 36, 'Dni pa, kar jih je vladal Jehu Izraelu v Samariji, je bilo osemindvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 1, 'Ko pa je videla Atalija, mati Ahazijeva, da je njen sin mrtev, vstane in pogubi vse seme kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 2, 'Ali Joseba, hči kralja Jorama, sestra Ahazijeva, vzame Joasa, sina Ahazijevega, in ga ukrade izmed kraljevih sinov, ki so jih morili, in potisne njega in njegovo pestunjo v spalnico; in skrili so ga pred Atalijo, da ni bil umorjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 3, 'In bil je ž njo skrit v hiši Gospodovi šest let. Atalija pa je gospodovala deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 4, 'A v sedmem letu pošlje Jojada in pokliče poveljnike nad sto Karejcev in stražarjev, ter jih pelje k sebi v hišo Gospodovo; in sklene zavezo ž njimi in vzame od njih prisego v hiši Gospodovi ter jim pokaže sina kraljevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 5, 'In jim zapove, rekoč: To je reč, ki jo boste storili: tretjina vas, ki prihajate noter ob sobotah, bodite na straži v hiši kraljevi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 6, 'tretjina pa bodi pri Surskih vratih in tretjina bodi pri vratih vzadaj za stražarji; tako boste stregli v hišni straži, v obrano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 7, 'A tista dva oddelka iz vas, vsi, ki odhajate ob sobotah, boste stregli v straži hiše Gospodove pri kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 8, 'In obkrožite kralja vseokrog, vsakdo držeč svoje orožje v roki; in kdor bi se vrinil v vaše vrste, bodi umorjen; in bodete pri kralju, ko pojde ven in ko pojde noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 9, 'In poveljniki nad sto so storili vse, kakor jim je zapovedal Jojada duhovnik: vsak vzame k sebi može svoje, tiste, ki so imeli priti služit v soboto, s tistimi, ki jim je bilo oditi v soboto, in pridejo k Jojadu duhovniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 10, 'In duhovnik izroči poveljnikom nad sto sulice in ščite, ki jih je imel kralj David in so bili v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 11, 'In stražarji so stali, vsak mož z orožjem v roki, od desne strani hiše do leve strani hiše, poleg oltarja in hiše, okoli kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 12, 'Potem pripelje ven sina kraljevega in dene nanj krono in mu da pričevanje; in ga postavijo za kralja ter ga pomazilijo, in ploskajo z rokami in govore: Živel kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 13, 'Ko pa je Atalija slišala glas straže in ljudstva, pride k ljudstvu v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 14, 'In pogleda, in glej, kralj stoji ob stebru, kakor je bila navada, in poveljniki in trobente pri njem, in vse ljudstvo dežele se veseli, in trobijo v trobente. Tedaj raztrga Atalija oblačila svoja in zavpije: Zarota, zarota!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 15, 'Jojada duhovnik pa zapove poveljnikom nad sto, ki so bili vojski na čelu, in jim reče: Odpeljite jo ven med vrstami, in kdor bi šel za njo, ubijte ga z mečem; kajti duhovnik je rekel: Ne sme umreti v hiši Gospodovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 16, 'In polože roke nanjo; in šla je po poti, koder hodijo konji v hišo kraljevo, in ondi so jo umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 17, 'Tedaj sklene Jojada zavezo med Gospodom in kraljem in ljudstvom, da bodo ljudstvo Gospodovo, enako tudi med kraljem in ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 18, 'In vse ljudstvo dežele je šlo v hišo Baalovo in so jo porušili; oltarje in podobe njegove pa so strli v kosce in Matana, duhovnika Baalovega, so umorili pred oltarji. In duhovnik je postavil nadzornike pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 19, 'In vzame poveljnike nad sto in Karejce in stražarje in vse ljudstvo dežele, in privedejo kralja doli od hiše Gospodove in pridejo skozi vrata straže k hiši kraljevi. In sedel je na kraljev prestol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 20, 'In vse ljudstvo dežele se je veselilo, in mesto je imelo mir. Atalijo pa so bili umorili z mečem pri kraljevi hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 11, 21, 'Joas je bil sedem let star, ko je zakraljeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 1, 'V sedmem letu Jehujevem je zakraljeval Joas in je vladal štirideset let v Jeruzalemu; in materi njegovi je bilo ime Zibija iz Bersebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 2, 'In Joas je delal, kar je bilo prav v očeh Gospodovih vse dni, dokler ga je poučeval Jojada duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 3, 'Toda višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 4, 'In Joas veli duhovnikom: Ves denar posvečenih daril, ki se prinaša v hišo Gospodovo, srebro vsakega preštetega, srebro duš, s katerim je vsaka ocenjena, in vse srebro, ki pride komu v srce, da bi ga prinesel v hišo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 5, 'duhovniki naj ga sprejmejo vsak od svojega znanca; in naj popravijo, kar je podrtega pri hiši, kjerkoli najdejo kaj razdrtega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 6, 'Ali do triindvajsetega leta kralja Joasa duhovniki niso popravili, kar je bilo podrtega pri hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 7, 'Tedaj pokliče kralj duhovnika Jojada in druge duhovnike in jim reče: Zakaj ne popravite, kar je podrtega pri hiši? Zatorej ne jemljite več denarja od znancev svojih, ampak dajte ga v popravo hiše!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 8, 'In duhovniki so privolili, da niso več jemali denarja od ljudstva, a hiše tudi niso popravljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 9, 'A Jojada duhovnik vzame skrinjo ter izvrta luknjo v njenem pokrovu in jo postavi ob desni strani oltarja, koder se hodi v hišo Gospodovo; in duhovniki, ki so bili čuvaji pri vratih, so devali vanjo ves denar, kar se ga je prineslo v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 10, 'In kadar so videli, da je dosti denarja v skrinji; je prišel gori kraljev pisar in veliki duhovnik, in sta preštela denar in ga spravila, kolikor so ga našli v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 11, 'In dajali so pretehtani denar v roke delovodjem, ki so bili postavljeni pri hiši Gospodovi, in ti so ga izplačevali tesarjem in delavcem, ki so popravljali hišo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 12, 'in zidarjem in kamenosekom ter v nakupovanje lesa in obsekanega kamenja v popravo podrtin pri hiši Gospodovi in za vse, kar se je porabilo v izboljšavo hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 13, 'A srebrnih čaš, usekalnikov, vrčev, trobent in nobene zlate ali srebrne posode za hišo Gospodovo niso delali iz denarja, ki se je prinašal v hišo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 14, 'temuč so ga dajali delovodjem, in popravljala se je ž njim hiša Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 15, 'Tudi niso zahtevali računa od mož, ki so jim dajali denar, da plačajo delavcem, ker so ž njim zvesto ravnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 16, 'Ali denarja od daritve za krivdo in od daritve za greh niso nosili za hišo Gospodovo, ker je bil duhovnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 17, 'Tedaj je šel gori Hazael, sirski kralj, in se je bojeval zoper Gat in ga dobil. In ko je obrnil Hazael obličje, da bi šel proti Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 18, 'vzame Joas, kralj Judov, vse posvečeno, kar so bili posvetili očetje njegovi: Josafat, Joram in Ahazija, kralji na Judovem, in kar je bil sam posvetil, tudi vse zlato, kar se ga je našlo v zakladnici hiše Gospodove in hiše kraljeve, in pošlje to Hazaelu, sirskemu kralju. In umaknil se je od Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 19, 'Druge zgodbe Joasove pa in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 20, 'In njegova služabnika sta se vzdignila ter sklenila zaroto in sta ubila Joasa v hiši Milu, ob poti, koder se gre doli v Silo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 12, 21, 'Jozakar namreč, sin Simeate, in Jozabad, sin Somerjev, njegova hlapca, sta ga ubila, da je umrl. In pokopali so ga z očeti njegovimi v mestu Davidovem, in Amazija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 1, 'V triindvajsetem letu Joasa, sina Ahazijevega, kralja na Judovem, je zakraljeval Joahaz, sin Jehujev, nad Izraelom v Samariji in je vladal sedemnajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 2, 'In delal je, kar je bilo hudo v očeh Gospodovih, in hodil za grehi Jeroboama, sina Nebatovega, s katerimi je ta zavajal v greh Izraela; ni odstopil od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 3, 'In razvnela se jeza Gospodova nad Izraelom, in dal jih je v pest Hazaelu, sirskemu kralju, in Ben-hadadu, sinu Hazaelovemu, vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 4, 'Joahaz pa je prosil blagovoljnosti Gospoda, in Gospod ga je uslišal; kajti videl je stisko Izraelovo, kako jih je zatiral sirski kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 5, '(In Gospod je dal Izraelu rešitelja, da so se oprostili izpod oblasti Sircev; in sinovi Izraelovi so prebivali v šatorih svojih kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 6, 'Vendar pa niso odstopili od grehov hiše Jeroboama, s katerimi je ta zavajal v greh Izraela, ampak hodili so v njih. In Ašera je tudi ostala v Samariji.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 7, 'Zakaj ni pustil Joahazu ljudstva, nego le petdeset konjikov in deset voz in deset tisoč pešcev; kralj sirski jih je namreč pogubil in strl, da so bili kakor prah o mlatvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 8, 'A druge zgodbe Joahazove in vse, kar je storil, in o moči njegovi, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 9, 'In Joahaz je legel k očetom svojim, in pokopali so ga v Samariji, in Joas, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 10, 'V sedemintridesetem letu Joasa, kralja Judovega, je zakraljeval Joas, sin Joahazov, nad Izraelom v Samariji in je vladal šestnajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 11, 'In delal je, kar je bilo hudo v očeh Gospodovih; ni odstopil od vseh grehov Jeroboama, sina Nebatovega, s katerimi je ta zavajal v greh Izraela, temuč živel je v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 12, 'A druge zgodbe Joasove in vse, kar je storil, in o moči njegovi, s katero se je bojeval zoper Amazija, kralja Judovega, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 13, 'In Joas je legel k očetom svojim, in Jeroboam je zasedel prestol njegov. In Joasa so pokopali v Samariji pri kraljih Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 14, 'Elizej pa je zbolel za svojo boleznijo, za katero je tudi umrl. In Joas, kralj Izraelov, pride doli k njemu in joče nad njim ter reče: Oče moj, oče moj, vozovi Izraelovi in jezdeci njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 15, 'In Elizej mu reče: Prinesi lok in strelice! In mu prinese lok in pšice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 16, 'In Elizej veli kralju Izraelovemu: Napni lok s svojo roko! In ga napne svojeročno. Elizej pa dene roke svoje na roke kraljeve');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 17, 'in reče: Odpri okno proti vzhodu! In ga odpre. Tedaj veli Elizej: Stréli! In izstreli. On pa reče: Pšica zmage od Gospoda, pšica zmage nad Sirijo! zakaj udaril boš Sirce v Afeku, da jih pokončaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 18, 'Nato veli: Vzemi pšice! In jih vzame. In veli kralju Izraelovemu: Udarjaj ob zemljo! In udari trikrat in obstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 19, 'Tedaj se razsrdi mož Božji nad njim in reče: Moral bi bil udariti petkrat ali šestkrat, pa bi bil udaril Sirijo, da bi jo bil pokončal. Sedaj pa boš udaril Sirijo samo trikrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 20, 'In ko je Elizej umrl in so ga pokopali, so vdrle plenilne čete Moabcev v deželo ob začetku leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 21, 'In zgodi se, ko so pokopavali nekega moža, da iznenada zagledajo tako četo; in vržejo moža v grob Elizejev. In brž, ko se dotakne mož kosti Elizejevih, oživi in stopi na noge svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 22, 'Hazael pa, kralj Sirije, je stiskal Izraela vse Joahazove dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 23, 'A Gospod jim je bil milosten in se jih je usmilil in se ozrl nanje zaradi zaveze svoje z Abrahamom, Izakom in Jakobom, in jih ni hotel pokončati, tudi jih ni zavrgel izpred svojega obličja do tega časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 24, 'In Hazael, kralj Sirije, je umrl, in sin njegov, Ben-hadad, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 13, 25, 'In Joas, sin Joahazov, je dobil zopet izpod roke Ben-hadada, sinu Hazaelovega, mesta, ki jih je ta v vojni vzel iz roke Joahaza, očeta njegovega. Trikrat ga je udaril Joas in dobil nazaj mesta Izraelova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 1, 'V drugem letu Joasa, sina Joahazovega, kralja v Izraelu, je zakraljeval Amazija, sin Joasa, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 2, 'Petindvajset let je bil star, ko je zakraljeval, in vladal je devetindvajset let v Jeruzalemu; in materi njegovi je bilo ime Joadina iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 3, 'In delal je, kar je bilo prav v očeh Gospodovih, a ne kakor David, oče njegov, ampak ravnal se je po vsem, kar je delal njegov oče Joas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 4, 'Toda višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 5, 'In ko mu je bilo kraljestvo trdno v rokah, je umoril hlapca svoja, ki sta bila ubila kralja, očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 6, 'Ali otrok morilcev ni usmrtil, po zapovedi Gospodovi, kakor je pisano v knjigi postave Mojzesove: Očetje naj se ne obsodijo v smrt za otroke, tudi ne otroci za očete; sleherni naj umrje za svoj greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 7, 'On je pobil iz Edomcev v Solni dolini deset tisoč in pridobil je Selo v vojni in jo imenoval Jokteel, do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 8, 'Potem pošlje Amazija sporočnikov k Joasu, sinu Joahaza, sina Jehujevega, kralju Izraelovemu, rekoč: Pridi, da si pogledava v lice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 9, 'Joas pa, kralj Izraelov, pošlje k Amaziju, kralju Judovemu, in sporoči: Osat, ki je bil na Libanonu, je poslal k libanonskemu cedru, rekoč: Daj svojo hčer sinu mojemu za ženo! V tem je šla mimo divja zver z Libanona in je poteptala osat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 10, 'Porazil si res Edoma, in tega se je srce tvoje prevzelo. Hvali se s tem in ostani doma! Zakaj siliš v nesrečo, da padeš ti in Juda s teboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 11, 'Ali Amazija ni hotel poslušati. Tedaj je šel gori Joas, kralj Izraelov, in pogledala sta si v lice on in Amazija, kralj Judov, v Betsemesu, ki je na Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 12, 'In Juda je izgubil bitko pred Izraelom, in bežal je vsak v šator svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 13, 'In Joas, kralj Izraelov, ujame Amazija, kralja Judovega, sina Joasa, sinu Ahazijevega, v Betsemesu, in ko pride v Jeruzalem, podere zidove jeruzalemske od Efraimovih vrat do Vogelnih vrat, štiristo komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 14, 'In vzame vse zlato in srebro in vse posode, kar se jih je našlo v hiši Gospodovi in v zakladih hiše kraljeve, tudi zastavljence, in se vrne v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 15, 'Druge zgodbe Joasove, kar je storil, in moč njegova in kako se je bojeval z Amazijem, kraljem Judovim, ni li zapisano v knjigi, letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 16, 'In Joas je legel k očetom svojim, in pokopali so ga v Samariji s kralji Izraelovimi. In Jeroboam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 17, 'Amazija pa, sin Joasov, kralj Judov, je živel še petnajst let po smrti Joasa, sina Joahazovega, kralja izraelskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 18, 'Druge pa zgodbe Amazijeve niso li zapisane v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 19, 'In napravili so zoper njega zaroto v Jeruzalemu; on pa je pobegnil v Lahis, in poslali so za njim v Lahis in ga tam ubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 20, 'In so ga prinesli na konjih in pokopali v Jeruzalemu z očeti njegovimi v mestu Davidovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 21, 'In vse ljudstvo Judovo vzame Azarija, ki je bil šestnajst let star, ter ga postavijo za kralja na mestu očeta njegovega Amazija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 22, 'On je zgradil Elat in ga je zopet prilastil Judi, potem ko je bil legel kralj k očetom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 23, 'V petnajstem letu Amazija, sinu Joasa, kralja Judovega, je zakraljeval Jeroboam, sin Joasa, kralja Izraelovega, v Samariji in je vladal enoinštirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 24, 'In delal je, kar je bilo hudo v očeh Gospodovih; ni odstopil od vseh grehov Jeroboama, sinu Nebatovega, ki je ž njimi zapeljeval Izraela v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 25, 'On je zopet pridobil Izraelu prejšnje meje od poti v Hamat do Morja v nižini, po besedi Gospoda, Boga Izraelovega, ki jo je govoril po hlapcu svojem Jonu, sinu Amitajevem, proroku, ki je bil iz Gat-heferja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 26, 'Videl je namreč Gospod prebridko stisko Izraelovo, da je uničen suženj in tudi svobodni in da ni bilo pomočnika Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 27, 'In Gospod ni bil rekel, da izbriše ime Izraelovo izpod neba; in rešil jih je po roki Jeroboama, sina Joasovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 28, 'Kar je pa več praviti o Jeroboamu in vse, kar je storil, in moč njegova, kako se je bojeval in kako je pridobil Damask in Hamat, ki sta bila nekdaj Judova, zopet Izraelu, ni li to zapisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 14, 29, 'In Jeroboam je legel k očetom svojim, h kraljem Izraelovim. In Zaharija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 1, 'V sedemindvajsetem letu Jeroboama, kralja Izraelovega, je zakraljeval Azarija, sin Amazija, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 2, 'Šestnajst let je bil star, ko je zakraljeval, in vladal je dvainpetdeset let v Jeruzalemu; in materi njegovi je bilo ime Jekolija iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 3, 'In je delal, kar je bilo prav v očeh Gospodovih, po vsem, kar je bil delal Amazija, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 4, 'Toda višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 5, 'In Gospod je udaril kralja, da je bil gobav do dne smrti svoje, in prebival je v hiši posebe. Jotam pa, kraljev sin, je bil nad kraljevo hišo in je sodil ljudstvu v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 6, 'Kar je pa več praviti o Azariju in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 7, 'In Azarija je legel k očetom svojim, in pokopali so ga z očeti njegovimi v mestu Davidovem; in Jotam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 8, 'V osemintridesetem letu Azarija, kralja Judovega, je kraljeval Zaharija, sin Jeroboamov, nad Izraelom v Samariji šest mesecev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 9, 'In delal je, kar je bilo hudo v očeh Gospodovih, kakor so delali očetje njegovi; ni odstopil od grehov Jeroboama, sina Nebatovega, ki je ž njimi zapeljeval v greh Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 10, 'In Salum, sin Jabesov, je napravil zaroto zoper njega in ga je udaril vpričo ljudstva in usmrtil, in zakraljeval je na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 11, 'Druge zgodbe Zaharijeve pa, glej, zapisane so v knjigi letopisov kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 12, 'To je bila beseda Gospodova, ki jo je govoril Jehuju, rekoč: Sinovi tvoji do tretjega rodu bodo sedeli na prestolu Izraelovem. In tako se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 13, 'Salum pa, sin Jabesov, je zakraljeval v devetintridesetem letu Uzija, kralja na Judovem, in vladal je mesec dni v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 14, 'Kajti Menahem, sin Gadijev, je šel gori iz Tirze, in ko je prispel v Samarijo, je udaril Saluma, sina Jabesovega v Samariji, in ga ubil, pa je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 15, 'Druge zgodbe Salumove pa in zarota, ki jo je napravil, glej, zapisano je to v knjigi letopisov kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 16, 'Takrat je Menahem udaril Tifsah in vse, ki so bili v njem, in njegovo pokrajino od Tirze, ker mu niso odprli vrat, zato jih je pobil, in vse njih noseče je razparal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 17, 'V devetintridesetem letu Azarija, kralja Judovega, je zakraljeval Izraelu Menahem, sin Gadijev, in vladal je deset let v Samariji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 18, 'In delal je, kar je bilo hudo v očeh Gospodovih, vse svoje žive dni ni odstopil od grehov Jeroboama, sina Nebatovega, ki je ž njimi zapeljeval v greh Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 19, 'In Pul, asirski kralj, pride v deželo. In Menahem je dal Pulu tisoč talentov srebra, da bi mu bil v pomoč in mu potrdil kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 20, 'In Menahem je naložil tisti denar Izraelu, vsem premožnim možem, vsakemu možu petdeset seklov srebra, da ga da kralju asirskemu. Kralj asirski je torej šel domov in ni ostal v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 21, 'Kar je pa več praviti o Menahemu in vse, kar je storil, ni li pisano v knjigi letopisov kraljev Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 22, 'In Menahem je legel k očetom svojim, in Pekahija, sin njegov, je zavladal na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 23, 'V petdesetem letu Azarija, kralja Judovega, je zakraljeval Pekahija, sin Menahemov, nad Izraelom v Samariji, in vladal je dve leti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 24, 'In delal je, kar je bilo zlo v očeh Gospodovih; ni odstopil od grehov Jeroboama, sina Nebatovega, ki je ž njimi v greh zapeljeval Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 25, 'In Pekah sin Remalijev, poveljnik njegov, je napravil zaroto zoper njega in ga je udaril v Samariji, v palači kraljeve hiše, z Argobom in Arjem. Ž njim pa je bilo petdeset mož iz Gileadčanov. In ko ga je ubil, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 26, 'Kar pa je več praviti o Pekahiju in vse, kar je storil, glej, zapisano je v knjigi letopisov kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 27, 'V dvainpetdesetem letu Azarija, kralja Judovega, je zakraljeval Izraelu v Samariji Pekah, sin Remalijev, in vladal je dvajset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 28, 'In delal je, kar je bilo hudo v očeh Gospodovih; ni odstopil od grehov Jeroboama, sina Nebatovega, ki je ž njimi zapeljeval v greh Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 29, 'V dneh Pekaha, kralja Izraelovega, je prišel Tiglat-pileser, kralj asirski, in je dobil Ijon in Abel-Betmako in Janoah in Kedes in Hazor in Gilead in Galilejo, vso pokrajino Neftalijevo, in odpeljal jih je ujete v Asirijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 30, 'In Hosea, sin Elov, je sklenil zaroto zoper Pekaha, sina Remalijevega, in udaril je nanj in ga ubil in zakraljeval na mestu njegovem v dvajsetem letu Jotama, sina Uzijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 31, 'Druge zgodbe Pekahove in vse, kar je storil, glej, pisano je v knjigi letopisov kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 32, 'V drugem letu Pekaha, sina Remalijevega, kralja Izraelovega, je zavladal Jotam, sin Uzija, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 33, 'Petindvajset let je imel, ko je zakraljeval, in vladal je šestnajst let v Jeruzalemu, in materi njegovi je bilo ime Jeruša, hči Zadokova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 34, 'In delal je, kar je bilo prav v očeh Gospodovih, ravnal se je po vsem, kar je bil delal Uzija, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 35, 'Ali višave niso bile odpravljene, ljudstvo je še darovalo in žgalo kadilo na višavah. On je zgradil gornja vrata pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 36, 'Kar je pa več praviti o Jotamu in vse, kar je storil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 37, 'V tistem času je Gospod začel pošiljati zoper Judo Rezina, kralja sirskega, in Pekaha, sina Remalijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 15, 38, 'In Jotam je legel k očetom svojim in je bil pokopan pri očetih svojih v mestu Davida, očeta svojega. In Ahaz, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 1, 'V sedemnajstem letu Pekaha, sinu Remalijevega, je zavladal Ahaz, sin Jotama, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 2, 'Dvajset let je bilo Ahazu, ko je zakraljeval, in vladal je šestnajst let v Jeruzalemu; in ni delal, kar bi bilo prav v očeh Gospoda, Boga njegovega, kakor oče njegov David,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 3, 'temuč hodil je po poti kraljev Izraelovih, celo sina svojega je daroval, da je šel skozi ogenj, po gnusobah poganov, ki jih je Gospod pregnal izpred sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 4, 'In daroval je ter žgal kadilo na višavah in po hribih in pod vsakim zelenim drevesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 5, 'Tedaj pride Rezin, kralj sirski, in Pekah, sin Remalijev, kralj Izraelov, gori zoper Jeruzalem se vojskovat; in oblegali so Ahaza, pa ga niso mogli zmagati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 6, 'V tistem času je Rezin, kralj sirski, pridobil Elat nazaj Siriji, izgnavši Jude iz Elata; in Sirci so prišli v Elat in ondi prebivajo do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 7, 'Ahaz pa pošlje sporočnike k Tiglat-pileserju, kralju asirskemu, rekoč: Hlapec sem tvoj in tvoj sin; pridi gori in me reši iz roke sirskega kralja in iz roke kralja Izraelovega, ki sta se vzdignila zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 8, 'In vzame Ahaz srebro in zlato, kar ga je bilo v hiši Gospodovi in v zakladih kraljeve hiše, ter pošlje darilo kralju asirskemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 9, 'In kralj asirski mu je ugodil. In kralj asirski gre gori proti Damasku in ga zasede in prebivalce njegove odvede v Kir, Rezina pa umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 10, 'Nato gre kralj Ahaz v Damask naproti Tiglat-pileserju, kralju asirskemu. In ko vidi oltar, ki je bil v Damasku, pošlje kralj Ahaz duhovniku Uriju podobo in posnetek tistega oltarja, po vsem, kakor je bil narejen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 11, 'In Urija duhovnik je napravil oltar; natančno po tem, kakor je bil sporočil kralj Ahaz iz Damaska, ga je izgotovil Urija duhovnik, preden je prišel kralj Ahaz iz Damaska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 12, 'In ko pride kralj iz Damaska in ogleda oltar, pristopi k njemu in daruje na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 13, 'In zažge svojo žgalščino in jedilno daritev in izlije pitni dar in škropi kri svoje mirovne daritve po oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 14, 'Bronasti oltar pa, ki je bil pred Gospodom, prenese s pročelja hiše, izmed svojega oltarja in hiše Gospodove, in ga postavi na severni strani svojega oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 15, 'In kralj Ahaz zapove Uriju duhovniku, rekoč: Na velikem oltarju zažigaj jutranjo žgalno daritev in večerno jedilno daritev in kraljevo žgalno in jedilno daritev z žgalščino vsega ljudstva v deželi in njih jedilno daritev in pitne dari; in nanj škropi vso kri žgalne daritve in vso drugo žrtveno kri; a bronasti oltar naj ostane, da se posvetujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 16, 'Tako je storil Urija duhovnik po vsem, kar je zapovedal kralj Ahaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 17, 'Kralj Ahaz je tudi dal odlomiti ploščine od stojal in vzeti umivalnike ž njih in sneti morje raz bronaste vole, ki so bili pod njim, in velel ga je postaviti na kamenita tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 18, 'Tudi pokriti mostovž za sobote, ki so ga bili zgradili v hiši, in kraljev vhod zunaj, je prestavil pri hiši Gospodovi zaradi kralja asirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 19, 'Kar je pa več praviti o Ahazu, kar je storil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 16, 20, 'In Ahaz je legel k očetom svojim, in pokopali so ga pri očetih njegovih v mestu Davidovem. In Ezekija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 1, 'V dvanajstem letu Ahaza, kralja na Judovem, je zakraljeval Hosea, sin Elov, nad Izraelom v Samariji, in vladal je devet let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 2, 'In delal je, kar je bilo hudo v očeh Gospodovih, pa ne kakor kralji Izraelovi, ki so bili pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 3, 'Zoper njega je prišel Salmaneser, kralj asirski, in Hosea mu je postal podložnik in mu dajal davek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 4, 'Ko pa je asirski kralj izvedel, da je Hosea napravil zaroto, ker je poslal sporočnikov do Soa, egiptovskega kralja, in ni prinašal davka asirskemu kralju kakor navadno leto za letom, ga je ujel in zvezanega poslal v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 5, 'Tedaj je šel asirski kralj gori po vsej deželi in prispel proti Samariji ter jo je oblegal tri leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 6, 'V devetem letu Hosea je kralj asirski dobil Samarijo in odpeljal Izraela v Asirijo in jih je naselil v Halahi in v Haborju, ob reki Gozanu, in v mestih Medov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 7, 'To pa se je zgodilo, ker so grešili sinovi Izraelovi zoper Gospoda, svojega Boga, ki jih je bil odpeljal iz Egipta, izpod oblasti Faraona, kralja egiptovskega, in ker so se bali drugih bogov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 8, 'in živeli po postavah poganov, ki jih je bil Gospod pregnal pred sinovi Izraelovimi, in po postavah kraljev Izraelovih, ki so jih naredili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 9, 'In sinovi Izraelovi so skrivaj počenjali stvari, ki niso bile prave, zoper Gospoda, Boga svojega, in so si zidali višave po vseh mestih svojih, od čuvajevega stolpa do utrjenega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 10, 'In postavljali so stebre s podobami in Ašere na vsakem visokem hribu in pod vsakim zelenim drevesom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 11, 'in tam so žgali kadilo po vseh višavah kakor poganski narodi, ki jih je bil Gospod pregnal izpred njih obličja, in delali so hudobne reči, da bi dražili Gospoda v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 12, 'In služili so malikom, o čemer jim je rekel Gospod: Ne storíte take reči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 13, 'In ko je Gospod pričal proti Izraelu in proti Judi po vseh prorokih in vseh vidcih, govoreč: Obrnite se od hudih poti svojih in izpolnjujte zapovedi in postave moje soglasno z vsem zakonom, ki sem ga zapovedal očetom vašim in ki sem vam ga pošiljal po hlapcih svojih prorokih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 14, 'vendar niso poslušali, ampak zatrdili so svoj zatilnik, da je bil enak zatilniku njih očetov, ki niso verovali v Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 15, 'In zaničevali so postave njegove in zavezo njegovo, ki jo je sklenil ž njih očeti, in pričevanja njegova, ki jih je pričal zoper nje, in hodeč za ničemurnostjo, so postali ničemurni in so sledili za pogani, ki so bivali okrog njih, za katere jim je Gospod ukazal, da naj ne delajo njim enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 16, 'In so zapustili vse zapovedi Gospoda, Boga svojega, in si napravili ulite podobe, zlasti dve teleti, in naredili Ašero in so molili vso vojsko nebeško in služili Baalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 17, 'In so darovali svoje sinove in svoje hčere, vodeč jih skozi ogenj, in se pečali z vedeževanjem in čaranjem in se prodali, da bi delali, kar je bilo hudo v očeh Gospodovih, da bi ga dražili v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 18, 'In razjezil se je Gospod silno nad Izraelom in ga je odpravil izpred svojih oči, da ni ostal nihče nego sam rod Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 19, 'Pa tudi Juda ni izpolnjeval zapovedi Gospoda, Boga svojega, temuč živel je po postavah Izraelovih, ki so si jih naredili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 20, 'Zato je Gospod zavrgel vse seme Izraelovo, in jih je stiskal in jih dal plenilcem v roke, dokler jih ni pognal izpred obličja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 21, 'Kajti odtrgal je Izraela od hiše Davidove, in postavili so za kralja Jeroboama, sina Nebatovega; in Jeroboam je odtegnil Izraela, da ni šel za Gospodom, in je povzročil, da so hudo grešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 22, 'In sinovi Izraelovi so hodili v vseh grehih Jeroboama, ki jih je storil, in niso odstopili od njih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 23, 'dokler ni Gospod odpravil Izraela izpred obličja svojega, kakor je bil govoril po vseh svojih hlapcih prorokih. Tako je bil Izrael preseljen iz svoje dežele v Asirijo, do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 24, 'Kralj asirski pa je pripeljal ljudi iz Babela in iz Kute in iz Ave, iz Hamata in Sefarvaima in jih je razstavil po mestih samarijskih namesto sinov Izraelovih. In prilastili so si Samarijo ter prebivali v njenih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 25, 'A v začetku, ko so prebivali ondi, se niso bali Gospoda; zato je Gospod poslal mednje leve, ki so jih morili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 26, 'Zatorej sporoče kralju asirskemu, rekoč: Narodi, ki si jih preselil in razstavil po mestih samarijskih, ne poznajo pravic deželnega Boga, zato je poslal leve mednje; in glej, ti jih more, ker ne poznajo pravic deželnega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 27, 'Tedaj zapove kralj asirski, rekoč: Peljite tja enega izmed duhovnikov, ki ste jih odondod privedli; ta naj gre in se ondi nastani in jih uči pravice Boga tiste dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 28, 'Nato pride eden duhovnikov, katere so odpeljali iz Samarije, in se nastani v Betelu ter jih uči, kako naj se boje Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 29, 'Ali vsak narod je naredil svojega boga, in postavili so jih v hiše višav, ki so jih bili Samarijani napravili, vsak narod po mestih svojih, v katerih so prebivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 30, 'Babelski možje so namreč naredili Sukot-benota, možje iz Kuta pa so naredili Nergala, možje iz Hamata Asima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 31, 'Avljani pa so naredili Nibhaza in Tartaka, a Sefarvaimci so sežigali svoje otroke v ognju Adrameleku in Anameleku, bogovoma Sefarvaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 32, 'Vendar so se bali Gospoda in si postavili izmed sebe duhovnike višavam, ki so darovali zanje v hišah po višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 33, 'Gospoda so se sicer bali, a služili so tudi svojim bogovom po navadi narodov, izmed katerih so bili sem priseljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 34, 'In do današnjega dne se ravnajo po prvotni navadi: Gospoda se ne boje; tudi ne delajo po svojih postavah in naredbah, pa tudi ne po postavi in zapovedi, ki jo je Gospod zapovedal sinovom Jakoba, ki mu je dal ime Izrael,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 35, 's katerim je Gospod sklenil zavezo, in jim je zapovedal, govoreč: Ne bojte se drugih bogov, tudi se jim ne klanjajte, ne služite jim in ne darujte jim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 36, 'ampak Gospoda, ki vas je z veliko močjo in z iztegnjeno ramo odpeljal iz Egiptovske dežele, njega se bojte, njemu se poklanjajte in njemu darujte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 37, 'in pazite na postave in naredbe, zakon in zapoved, ki vam jih je predpisal, da jih izpolnjujete vse svoje žive dni, in ne bojte se drugih bogov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 38, 'in zaveze, ki sem jo sklenil z vami, ne zabite, tudi se ne bojte drugih bogov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 39, 'marveč bojte se Gospoda, Boga svojega, in on vas otme iz roke vseh sovražnikov vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 40, 'Toda niso poslušali, temuč so delali po svoji prvotni navadi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 17, 41, 'Tako so se ti narodi sicer bali Gospoda, toda služili so svojim izrezanim podobam; enako delajo tudi njih otroci in njih otrok otroci do tega dne, kakor so delali njih očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 1, 'V tretjem letu Hosea pa, sinu Elovega, kralja Izraelovega, je zakraljeval Ezekija, sin Ahaza, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 2, 'Petindvajset let mu je bilo, ko je zavladal, in kraljeval je devetindvajset let v Jeruzalemu. Matere njegove ime pa je bilo Abi, hči Zaharijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 3, 'On je delal, kar je bilo prav v očeh Gospodovih, po vsem, kakor je delal David, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 4, 'On je odpravil višave in strl stebre in posekal Ašere in razdrobil bronasto kačo, ki jo je bil Mojzes naredil; zakaj do tega časa so ji žgali kadilo sinovi Izraelovi; in imenoval jo je Nehuštan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 5, 'On je upal v Gospoda, Boga Izraelovega, da ni bilo za njim njemu podobnega med vsemi kralji Judovimi, tudi ne med tistimi, ki so bili pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 6, 'Kajti oklepal se je Gospoda, ni se umaknil, hodeč za njim, temuč izpolnjeval je zapovedi njegove, ki jih je bil Gospod zapovedal Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 7, 'In Gospod je bil ž njim: kamor koli se je obrnil, je uspešno ravnal. Uprl se je tudi kralju asirskemu in mu ni služil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 8, 'On je udaril Filistejce tja do Gaze in njeno pokrajino od čuvajevega stolpa do utrjenega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 9, 'Zgodi se pa v četrtem letu kralja Ezekija, ki je bilo sedmo leto Hosea, sinu Ela, kralja Izraelovega, da pride Salmaneser, kralj asirski, gori zoper Samarijo in jo oblega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 10, 'In dobili so jo ob koncu tretjega leta; v šestem letu Ezekija, ki je bilo deveto leto Hosea, kralja Izraelovega, je bila dobljena Samarija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 11, 'In kralj asirski je odpeljal Izraelce v Asirijo in jih naselil v Halahu in Haborju, ob reki Gozanu, in v mestih Medov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 12, 'zato ker niso poslušali glasu Gospoda, Boga svojega, in so prelomili njegovo zavezo, vse, kar je zapovedal Mojzes, služabnik Gospodov, ne hoteč tega ne slišati, ne delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 13, 'A v štirinajstem letu kralja Ezekija pride Senaherib, kralj asirski, gori zoper vsa utrjena mesta na Judovem ter jih pridobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 14, 'In Ezekija, kralj Judov, pošlje h kralju asirskemu v Lahis in sporoči: Pregrešil sem se! Kreni od mene; kar mi naložiš, hočem nositi. In kralj asirski določi Ezekiju, kralju Judovemu, tristo talentov srebra in trideset talentov zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 15, 'In Ezekija mu je dal vse srebro, ki se je našlo v hiši Gospodovi in v zakladih kraljeve hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 16, 'V tem času je Ezekija odrezal zlato od durnic hiše Gospodove in od podbojev, ki jih je bil sam dal prevleči, in ga je dal kralju asirskemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 17, 'In kralj asirski je poslal iz Lahisa Tartana in Rabsarisa in Rabsaka h kralju Ezekiju proti Jeruzalemu z mnogoštevilno vojsko. In šli so gori in dospeli pred Jeruzalem. In ko so prišli gori, se ustavijo pri vodovodu zgornjega ribnika, ki je ob poti valjalčeve njive,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 18, 'in kličejo kralja. Tedaj pridejo ven k njim Eljakim, sin Hilkijev, ki je bil nad dvorcem, in Sebna pisar in Joah, sin Asafov, letopisec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 19, 'In Rabsak jim reče: Povejte vendar Ezekiju: Tako pravi kralj veliki, kralj asirski: Kakšno upanje je to, na katero se zanašaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 20, 'Praviš: Dosti je sveta in moči za vojskovanje – a prazna beseda je to. V koga torej upaš, da si se mi uprl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 21, 'Glej, se li mar zanašaš na palico iz nalomljenega trsta, na Egipt? katera se mu, kadar se kdo nasloni nanjo, zadere v roko in jo prebode. Tako je Faraon, egiptovski kralj, vsem, ki stavijo upanje vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 22, 'Ako mi pa porečete: V Gospoda, Boga svojega, upamo – ni li on tisti, čigar višave in oltarje je Ezekija odpravil in je velel Judi in Jeruzalemu: Molite pred tem oltarjem v Jeruzalemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 23, 'Sedaj torej, pravim, stavi z gospodom mojim, s kraljem asirskim: dam ti dvakrat tisoč konj, ako boš imel jezdecev, da jih posadiš nanje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 24, 'Kako bi mogel zavrniti le enega voditelja izmed najmanjših služabnikov gospoda mojega? A ti se zanašaš na Egipt zaradi voz in konjikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 25, 'Sem li mar sedaj brez Gospoda prišel gori zoper ta kraj, da ga pogubim? Gospod mi je velel: Idi gori zoper to deželo in pogubi jo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 26, 'Tedaj reče Eljakim, sin Hilkijev, in Sebna in Joah Rabsaku: Govóri, prosim, hlapcem svojim po sirsko, saj razumemo; in ne govori nam po judovsko, ker sliši ljudstvo, ki je na zidovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 27, 'Ali Rabsak jim reče: Me je li h gospodu tvojemu in k tebi poslal gospod moj, da naj govorim besede te? Ali ne k onim možem, ki sede po zidovju, da jedo blato svoje in pijo vodo svojo z vami vred?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 28, 'Rabsak torej se ustopi in zavpije z glasom velikim po judovsko in govori takole: Čujte besede velikega kralja, kralja asirskega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 29, 'Tako pravi kralj: Naj vas ne prekani Ezekija, kajti ne bo vas mogel oteti iz roke njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 30, 'In ne pregovóri vas Ezekija, da bi upali v Gospoda, govoreč: Gotovo nas otme Gospod, in to mesto ne bo dano kralju asirskemu v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 31, 'Ne poslušajte Ezekija; kajti tako pravi kralj asirski: Pogodite se z menoj za mir in pridite k meni; tako jejte vsak svoje trte sad in svoje smokve sad in pijte vsak svojega vodnjaka vodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 32, 'dokler ne pridem in vas vzamem v deželo, podobno vaši deželi, v deželo, kjer je obilo žita in vina, kruha in vinogradov, oljk in medú, da boste živeli in ne umrli. Ne poslušajte Ezekija, ko vas zapeljuje, govoreč: Gospod nas otme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 33, 'Ali je rešil kateri bogov drugih narodov deželo svojo iz roke kralja asirskega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 34, 'Kje so bogovi Hamata in Arpada? kje so bogovi Sefarvaima, Hene in Ive? so li mar rešili Samarijo iz moje roke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 35, 'Kateri so med vsemi bogovi teh dežel, ki so deželo svojo oteli iz roke moje? da bi Gospod otel Jeruzalem iz roke moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 36, 'Ljudstvo je pa molčalo, in niso mu odgovorili ničesar, zakaj kraljev ukaz je velel: Ne odgovarjajte mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 18, 37, 'Pride torej Eljakim, Hilkijev sin, ki je bil nad dvorcem, in Sebna, pisar, in Joah, Asafov sin, letopisec, k Ezekiju z raztrgano obleko, in naznanijo mu besede Rabsakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 1, 'In ko je to slišal kralj Ezekija, si je raztrgal oblačila in pokril se je z raševino in šel v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 2, 'In pošlje Eljakima, načelnika dvorca, in Sebna, pisarja, ter starejšine duhovnikov, pokrite z raševino, k proroku Izaiju, sinu Amozovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 3, 'In ti mu reko: Tako pravi Ezekija: Dan stiske in strahovanja in zasramovanja je ta dan; kajti otroci so prišli do poroda, a moči ni za porod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 4, 'Morda bo slišal Gospod, Bog tvoj, vse besede Rabsakove, s katerimi ga je poslal kralj asirski, gospod njegov, sramotit Boga živega, in bo kaznoval besede, ki jih je slišal Gospod, Bog tvoj. Zato povzdigni molitev za ostanke, kar jih še je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 5, 'Ko so torej prišli hlapci Ezekija kralja k Izaiju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 6, 'jim reče Izaija: Tako povejte gospodu svojemu: Tako pravi Gospod: Ne boj se zaradi tistih besed, ki si jih slišal, ki so me ž njimi preklinjali hlapci kralja asirskega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 7, 'Glej, jaz mu vdahnem duha, da bo slišal glas in se vrnil v deželo svojo, in storim, da pade od meča v deželi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 8, 'In ko se vrne Rabsak, najde kralja asirskega v boju zoper Libno; slišal je bil namreč, da se je umaknil od Lahisa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 9, 'V tem zasliši, da pravijo o Tirhaku, kralju v Etiopiji: Glej, prišel se je vojskovat zoper tebe! In pošlje zopet sporočnikov k Ezekiju z ukazom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 10, 'Tako govorite Ezekiju, kralju Judovemu, in recite: Naj te ne vara Bog tvoj, ki staviš nanj upanje, govoreč: Jeruzalem ne bo dan v roko kralja asirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 11, 'Glej, sam si slišal, kaj so storili kralji asirski vsem drugim deželam, pokončavši jih docela, in ti bi se otel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 12, 'Ali so bogovi narodov oteli tiste, ki so jih pogubili očetje moji, Gozana in Harana in Rezefa in sinove Edena, ki so bili v Telasarju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 13, 'Kje je kralj hamatski in kralj arpadski in kralj mesta Sefarvaima in Hene in Ive?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 14, 'In ko Ezekija prejme pismo iz roke sporočnikov in ga prebere, gre gori v hišo Gospodovo in ga razgrne pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 15, 'In molil je Ezekija pred Gospodom, govoreč: O Gospod, Bog Izraelov, ki stoluješ nad kerubi, ti si Bog, ti edini vsem kraljestvom na zemlji, ti si ustvaril nebesa in zemljo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 16, 'Nagni uho svoje, Gospod, in poslušaj, odpri oči svoje, Gospod, in poglej! In poslušaj besede Senaheriba, s katerimi ga je poslal sramotit Boga živega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 17, 'Res je, Gospod, opustošili so kralji asirski one narode in njih dežele');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 18, 'in so pometali njih bogove v ogenj, zakaj niso bili bogovi, ampak rok človeških delo, les in kamen; zato so jih pogubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 19, 'Sedaj torej, Gospod, Bog naš, reši nas, prosim, iz roke njegove, da naj spoznajo vsa kraljestva na zemlji, da si ti Gospod Bog, ti edini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 20, 'Tedaj pošlje Izaija, sin Amozov, k Ezekiju in sporoči: Tako pravi Gospod, Bog Izraelov: Kar si molil k meni spričo Senaheriba, kralja asirskega, sem slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 21, 'To je beseda, ki jo je govoril Gospod o njem: Zaničuje te, zasmehuje te devica, hči sionska, za teboj maje glavo hči jeruzalemska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 22, 'Koga si sramotil in preklinjal? in zoper koga si zagnal svoj glas in ošabno povzdignil svoje oči? Zoper Svetnika Izraelovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 23, 'Po poslancih svojih si sramotil Gospoda, ko si govoril: Z množico svojih voz sem prišel na vrh gorá, do najvišje strani Libanona; in posekam visoke cedre njegove in najboljše ciprese njegove; vstopim tudi v najdaljnejše prenočišče njegovo, v gaj na vrtu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 24, 'Jaz sem kopal in izpil tuje vodnjake, in s stopalom nog svojih hočem posušiti vse egiptovske reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 25, 'A nisi li slišal, da sem jaz to napravljal od zdavnaj in snoval od starih časov? Sedaj sem storil, da je prišlo to, da rušiš utrjena mesta v kupe razvalin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 26, 'Zato so bili njih prebivalci slabotnih rok, prestrašeni in zbegani; bili so kakor trava na polju in kakor zelenjava mehka, kakor trava na strehah in kakor žito posmojeno, preden gre v latje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 27, 'In sejo tvojo in odhod in prihod tvoj poznam, tudi divjanje tvoje zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 28, 'Ker divjanje tvoje zoper mene in lahkoživstvo tvoje je prišlo do mojih ušes, zato denem svoj obroček v tvoj nos in uzdo svojo med ustnice tvoje, in povedem te nazaj po tistem potu, po katerem si prišel. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 29, 'In to ti bodi v znamenje: to leto boste jedli, kar samo zraste, drugo leto pa, kar po tem priraste, v tretjem letu sejte in ženjite in sadite vinograde ter jejte njih sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 30, 'In kar se od hiše Judove ohrani, kar preostane, bo zopet poganjalo korenine spodaj in rodilo sad zgoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 31, 'Zakaj iz Jeruzalema izide ostanek in s Sionske gore tisti, ki se bodo rešili; gorečnost Gospoda nad vojskami stori to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 32, 'Zatorej pravi tako Gospod zastran kralja asirskega: Ne pride v to mesto in pšice ne ustreli sem, tudi ščita mu ne bo stavil nasproti, ne nanašal nasipov zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 33, 'Po istem potu, po katerem je prišel, se vrne, v to mesto pa ne pride, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 34, 'Zakaj branil bom to mesto, da ga rešim, zaradi sebe in zaradi Davida, hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 35, 'In zgodi se to noč, da izide angel Gospodov ter jih pobije v asirskem ostrogu sto petinosemdeset tisoč; in ko so vstali zjutraj, glej, bili so vsi tisti trupla mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 36, 'Senaherib torej, kralj asirski, se vzdigne in odide in se vrne in ostane v Ninivah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 19, 37, 'Tam je bilo, ko se je klanjal v hiši Nisroka, boga svojega, da ga Adramelek in Sarezer, sina njegova, udarita z mečem in pobegneta v deželo Araratsko. In kraljeval je sin njegov Esar-hadon namesto njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 1, 'V tistih dneh zboli Ezekija na smrt. In pride k njemu Izaija, sin Amozov, prorok, ter mu reče: Tako pravi Gospod: Oporôči za hišo svojo, kajti v kratkem umreš in ne boš živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 2, 'Tedaj obrne Ezekija obličje v steno in moli h Gospodu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 3, 'Ah, Gospod, spomni se, prosim, da sem neprestano hodil pred teboj v resnici in z nerazdeljenim srcem ter delal, kar je dobro v tvojih očeh. In plakal je Ezekija, silno plakal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 4, 'In zgodi se, ko ni bil Izaija še prešel sredine mesta, da pride beseda Gospodova do njega, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 5, 'Vrni se in reci Ezekiju, vojvodi ljudstva mojega: Tako pravi Gospod, Bog očeta tvojega Davida: Čul sem molitev tvojo, solze tvoje sem videl. Glej, ozdravim te; tretji dan pojdeš gori v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 6, 'In pridenem tvojim dnem petnajst let in iz roke asirskega kralja otmem tebe in to mesto, in branil bom to mesto zaradi sebe in zaradi Davida, hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 7, 'In Izaija veli: Prinesite gručo smokev! In jo prineso ter polože na ulje, in je ozdravel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 8, 'Rekel je pa Ezekija Izaiju: Kaj je znamenje, da me Gospod ozdravi in da pojdem tretji dan gori v hišo Gospodovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 9, 'In Izaija reče: To ti bodi znamenje od Gospoda, da bo storil Gospod, kar je govoril: Naj li gre senca deset stopinj naprej ali naj gre deset stopinj nazaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 10, 'Ezekija reče: Lahko se senca pomakne deset stopinj naprej; nočem tega, temuč naj se vrne senca deset stopinj nazaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 11, 'In Izaija prorok je klical h Gospodu; in on je storil, da je šla senca po stopinjah, po katerih je bila šla doli na sončni uri Ahazovi, za deset stopinj nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 12, 'V tistem času je poslal Berodak Baladan, sin Baladanov, kralj babilonski, pismo in dar Ezekiju; slišal je namreč, da je bil Ezekija bolan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 13, 'In Ezekija jih je zaslišal in jim je razkazal vso hišo dragocenosti svojih, srebro in zlato in dišave in najboljše olje in vso orožnico svojo in vse, kar se je našlo v zakladih njegovih; ničesar ni bilo v hiši njegovi, ne v vsej oblasti njegovi, da bi jim ne bil Ezekija pokazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 14, 'Tedaj pride Izaija prorok h kralju Ezekiju ter mu reče: Kaj so rekli oni možje? in odkod so prišli k tebi? Ezekija pa reče: Iz daljne dežele so prišli k meni, iz Babilona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 15, 'In vpraša: Kaj so videli v hiši tvoji? Ezekija odgovori: Karkoli je v hiši moji, so videli; ničesar ni bilo, da bi jim ne bil pokazal, v zakladih mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 16, 'Nato reče Izaija Ezekiju: Čuj besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 17, 'Glej, dnevi pridejo, ko se odnese vse, kar je v hiši tvoji in kar so shranili očetje tvoji do tega dne, v Babilon; nič ne bo ostalo, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 18, 'Tudi sinov tvojih, ki pridejo iz tebe, ki jih boš rodil, vzemo, da bodo dvorniki v gradu kralja babilonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 19, 'In Ezekija reče Izaiju: Dobra je beseda Gospodova, ki si jo govoril. Še reče: Ni li tako? samo da bode mir in stanovitnost v dnevih mojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 20, 'A druge zgodbe Ezekijeve in vsa moč njegova in kako je napravil ribnik in vodovod in napeljal vodo v mesto, ali ni zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 20, 21, 'In Ezekija je legel k očetom svojim, in Manasej, sin njegov, je kraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 1, 'Manasej je bil dvanajst let star, ko je zavladal, in vladal je petinpetdeset let v Jeruzalemu. Materi njegovi pa je bilo ime Hefziba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 2, 'In delal je, kar je bilo hudo v očeh Gospodovih, po gnusobah narodov, ki jih je Gospod izgnal pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 3, 'Zakaj zgradil je zopet višave, ki jih je bil zrušil njegov oče Ezekija, in je postavil oltarje Baalu in napravil Ašero, kakor je storil Ahab, kralj Izraelov, in poklanjal se vsej vojski nebeški in služil zvezdam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 4, 'In sezidal je oltarje v hiši Gospodovi, o kateri je bil rekel Gospod: V Jeruzalemu postavim ime svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 5, 'Sezidal je tudi oltarje vsej vojski nebeški na obeh dvoriščih pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 6, 'In svojega sina je daroval, da je šel skozi ogenj, in se je pečal z vedeževanjem in zaklinjanjem in podpiral rotilce duhov in čarodejnike: delal je mnogo hudega v očeh Gospodovih, da bi ga dražil v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 7, 'Postavil je tudi rezano podobo Ašere, ki jo je bil naredil, v hiši, o kateri je Gospod rekel Davidu in Salomonu, sinu njegovemu: V tej hiši in v Jeruzalemu, ki sem ga izvolil iz vseh rodov Izraelovih, postavim ime svoje za vekomaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 8, 'tudi ne pustim več, da bi šle noge Izraelove z zemlje, ki sem jo dal njih očetom, ako bodo le pazili, da delajo po vsem, kar sem jim ukazal, in po vsej postavi, ki jim jo je zapovedal hlapec moj Mojzes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 9, 'Ali niso poslušali; in Manasej jih je zapeljeval, da delajo, kar je hudo, bolj nego narodi, ki jih je Gospod potrebil pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 10, 'Tedaj je govoril Gospod po svojih hlapcih, prorokih, in dejal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 11, 'Ker je storil Manasej, kralj Judov, vse te gnusobe in delal krivično bolj, nego karkoli so delali Amorejci, ki so živeli pred njim, in je napeljal Judo, da tudi greši ž njegovimi maliki:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 12, 'zatorej pravi tako Gospod, Bog Izraelov: Glej, jaz pripravim takšno nesrečo nad Jeruzalem in nad Judo, da mu bode, kdorkoli bo o tem slišal, zvenelo po obeh ušesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 13, 'In potegnem čez Jeruzalem mersko vrvico samarijsko in grezilo hiše Ahabove, in izpraznim Jeruzalem, kakor če kdo obriše skledo: obrišejo in povezne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 14, 'In zavržem ostanek dediščine svoje in jih izdam v roko njih sovražnikov, in bodo v rop in v plen vsem sovražnikom svojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 15, 'ker so delali, kar je zlo v mojih očeh, in so me dražili v jezo od dne, ko so odšli njih očetje iz Egipta, do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 16, 'In Manasej je tudi prelil veliko nedolžne krvi, dokler ni ž njo napolnil Jeruzalema od enega konca do drugega, razen svojega greha, s katerim je zapeljeval Judo v greh, da so delali, kar je bilo hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 17, 'Druge zgodbe pa Manasejeve in vse, kar je storil, in greh, s katerim je grešil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 18, 'In Manasej je legel k očetom svojim in je bil pokopan na vrtu hiše svoje, na vrtu Uzovem. In zakraljeval je sin njegov Amon namesto njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 19, 'Dvaindvajset let je bil star Amon, ko je zakraljeval, in vladal je dve leti v Jeruzalemu; in materi njegovi je bilo ime Mesulemeta, hči Haruzova iz Jotbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 20, 'In delal je, kar je bilo hudo v očeh Gospodovih, kakor je bil delal oče njegov Manasej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 21, 'In hodil je po vsej poti, po kateri je hodil oče njegov, služeč malikom, ki jim je služil njegov oče, in klanjajoč se jim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 22, 'Gospoda pa, Boga očetov svojih, je opustil, in ni hodil po poti Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 23, 'In služabniki Amonovi so sklenili zaroto zoper njega in so kralja usmrtili v hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 24, 'A ljudstvo dežele je pobilo vse, ki so se bili zarotili zoper njega; in ljudstvo dežele je postavilo Josija, sina njegovega, za kralja na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 25, 'Kar je pa več praviti o Amonu, kar je storil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 21, 26, 'In pokopali so ga v grobu njegovem na vrtu Uzovem. In Josija, sin njegov, je zavladal na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 1, 'Josija je bil osem let star, ko je zakraljeval, in vladal je enointrideset let v Jeruzalemu; in materi njegovi je bilo ime Jedida, hči Adajeva, iz Bozkata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 2, 'In delal je, kar je bilo prav v očeh Gospodovih, in je hodil po vsej poti Davida, očeta svojega, ni se uklonil ne na desno, ne na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 3, 'In zgodi se v osemnajstem letu kralja Josija, da pošlje kralj Safana, sina Azaljevega, sinu Mesulamovega, pisarja, v hišo Gospodovo, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 4, 'Pojdi gori k Hilkiju, velikemu duhovniku, da naj sešteje denar, kar se ga je prineslo v hišo Gospodovo, ki so ga zbrali varuhi ob vratih od ljudstva;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 5, 'in naj ga izroče delovodjem, ki nadzorujejo v hiši Gospodovi, in ti naj ga dado delavcem v hiši Gospodovi, da se popravi, kar je podrtega pri hiši,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 6, 'namreč tesarjem, stavbarjem in zidarjem, in da se kupi les in obsekano kamenje v popravo hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 7, 'A račun se ni zahteval od njih o denarju, ki se je poveril njih rokam, ker so ž njim zvesto ravnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 8, 'In Hilkija, veliki duhovnik, je rekel Safanu pisarju: Knjigo postave sem našel v hiši Gospodovi. In Hilkija da knjigo Safanu, in ta jo je bral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 9, 'In Safan pisar pride h kralju in mu sporoči in reče: Hlapci tvoji so izsuli denar, kar se ga je našlo v hiši Gospodovi, in so ga dali v roke delovodjem, ki nadzorujejo v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 10, 'Dalje naznani Safan, pisar, kralju, rekoč: Knjigo mi je dal duhovnik Hilkija. In Safan jo je čital pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 11, 'Ko pa kralj sliši besede knjige postave, raztrga oblačila svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 12, 'In kralj zapove Hilkiju, duhovniku, in Ahikamu, sinu Safanovemu, in Akborju, sinu Mihajevemu, in Safanu pisarju in Asaju, kraljevemu hlapcu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 13, 'Pojdite, vprašajte Gospoda zame in za ljudstvo in za vse Judovo o besedah te knjige, ki se je našla; zakaj velik je srd Gospodov, ki se je vnel zoper nas, ker niso očetje naši poslušali besed te knjige, da bi delali po vsem, kar nam je v njej predpisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 14, 'Tedaj so šli Hilkija, duhovnik, Ahikam, Akbor, Safan in Asaja k Huldi prorokinji, ženi Saluma, sina Tikvaja, sina Harhasovega, varuha oblačilnice (ona je pa stanovala v Jeruzalemu, v drugem delu mesta), in so govorili ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 15, 'Ona jim pa reče: Tako pravi Gospod, Bog Izraelov: Povejte možu, ki vas je poslal k meni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 16, 'Tako pravi Gospod: Glej, jaz pripravim nesrečo nad ta kraj in nad prebivalce njegove, namreč vse besede tiste knjige, ki jo je čital kralj Judov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 17, 'ker so me zapustili in so žgali kadilo drugim bogovom, da bi me dražili v jezo z vsem delom svojih rok; zato se bo vnel srd moj zoper ta kraj, in ne bo ugašen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 18, 'Kralju Judovemu pa, ki vas je poslal vprašat Gospoda, recite tako: Tako pravi Gospod, Bog Izraelov, glede besed, ki si jih slišal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 19, 'Ker se je omečilo srce tvoje in si se ponižal pred Gospodom, ko si čul, kar sem govoril zoper ta kraj in zoper prebivalce njegove, da jih zadene opustošenje in preklinjanje, in si raztrgal oblačila svoja in jokal pred menoj: zato sem tudi tebe slišal, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 22, 20, 'Zato, glej, te zberem k očetom tvojim, in boš v miru zbran v grob svoj, da ne bodo oči tvoje videle vse nesreče, ki jo spravim nad ta kraj. In sporočili so ta govor kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 1, 'Nato pošlje kralj in zbere k sebi vse starejšine Judove in jeruzalemske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 2, 'In kralj gre gori v hišo Gospodovo in vsi možje Judovi in prebivalci jeruzalemski ž njim, tudi duhovniki in proroki in vse ljudstvo, mali in veliki; in čita, da vsi slišijo, vse besede knjige zaveze, ki se je našla v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 3, 'In kralj se ustopi ob stebru in stori zavezo pred Gospodom, da bo hodil za Gospodom in izpolnjeval zapovedi njegove in pričevanja njegova in postave njegove iz vsega srca in iz vse duše, da ostanejo veljavne te zaveze besede, ki so zapisane v tej knjigi. In vse ljudstvo je stopilo v to zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 4, 'In kralj zapove Hilkiju, velikemu duhovniku, in duhovnikom druge vrste in varuhom pri vratih, naj pomečejo iz templja Gospodovega vse priprave, ki so jih naredili Baalu in Ašeri in vsej vojski nebeški; in sežgal jih je zunaj Jeruzalema na Kidronskih poljanah, in njih prah so odnesli v Betel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 5, 'In odpravil je malikovalske svečenike, ki jih je bil kralj Judov postavil, da žgo kadilo na višavah po mestih Judovih in v okolišu Jeruzalema; tudi tiste, ki so žgali kadilo Baalu, solncu in mesecu, ozvezdjem in vsej vojski nebeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 6, 'Velel je tudi odnesti Ašero iz hiše Gospodove ven za Jeruzalem k potoku Kidronu, in jo je sežgal pri potoku Kidronu in zmel v prah, in prah je raztresel po grobovih nizkega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 7, 'In razdrl je nečistosti posvečene hiše, ki so bile pri hiši Gospodovi in so v njih ženske tkale Ašeri ogrinjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 8, 'Velel je tudi duhovnikom iti iz mest Judovih in je oskrunil višave, kjer so bili duhovniki žgali kadilo, od Gebe do Bersebe. In podrl je višave pri vratih, ki so bile pri vhodu v vrata Jozueta, mestnega poglavarja, po levi strani, koder se gre v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 9, 'Ali duhovniki višav niso smeli pristopiti gori k oltarju Gospodovemu v Jeruzalemu, jedli so samo opresnike med svojimi brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 10, 'In oskrunil je Tofet, ki je v dolini Hinomovih sinov, da bi nihče več ne peljal sina svojega ali hčere svoje skozi ogenj, darujoč ju Molohu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 11, 'Odpravil je tudi konje, ki so jih bili kralji Judovi postavili solncu, proti vhodu v hišo Gospodovo, poleg hrama dvornika Natanmeleka, ki je bival v Parvarimu, in solnčne vozove je sežgal z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 12, 'Oltarje pa, ki so bili na strehi gornje izbe Ahazove in so jih napravili kralji Judovi, in oltarje, katere je naredil Manasej na obeh dvoriščih hiše Gospodove, je zrušil kralj in pometal odondod, in njih prah je stresel v potok Kidron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 13, 'In višave pred Jeruzalemom, ki so bile na desni strani Gore pogube in jih je bil Salomon, kralj Izraelov, zgradil Astoreti, grdobi Sidoncev, in Kamosu, grdobi Moabcev, in Milkomu, gnusobi sinov Amonovih, je oskrunil kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 14, 'In strl je stebre s podobami in posekal Ašere, njih mesta pa je napolnil s človeškimi kostmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 15, 'Enako je tudi porušil oltar v Betelu in višavo, ki jo je napravil Jeroboam, sin Nebatov, ki je napotil Izraela v greh, tisti oltar in višavo je porušil; in sežgal je višavo in jo strl v prah, sežgal tudi Ašero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 16, 'In Josija se ozre in zagleda grobe, ki so bili ondi v gori, in pošlje in vzame kosti iz grobov ter jih sežge na oltarju in ga oskruni po besedi Gospodovi, katero je zaklical mož Božji, napovedujoč te reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 17, 'Nato vpraša: Kakšno je tu nadgrobno znamenje, ki ga vidim? In mestni možje mu reko: Grob je moža Božjega, ki je prišel z Judovega in zaklical te reči, ki si jih storil, zoper oltar betelski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 18, 'In veli: Naj leži, nihče ne gani njegovih kosti! Tako so ostale nedotaknjene kosti njegove in kosti proroka, ki je bil prišel iz Samarije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 19, 'Tudi vse hiše višav, kar jih je bilo po mestih samarijskiln, katere so napravili kralji Izraelovi, da dražijo Gospoda, je Josija odpravil in ž njimi storil prav tako, kakor je bil storil v Betelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 20, 'In daroval je vse duhovnike višav, ki so bili ondi, na oltarjih in je žgal človeške kosti na njih. Potem se vrne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 21, 'Tedaj zapove kralj vsemu ljudstvu, rekoč: Praznujte pasho Gospodu, Bogu svojemu, kakor je pisano v tej knjigi zaveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 22, 'Gotovo se ni praznovala taka pasha od dni sodnikov, ki so sodili Izraela, pa tudi ne v dnevih kraljev Judovih in kraljev Izraelovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 23, 'temuč v osemnajstem letu kralja Josija se je praznovala ta pasha Gospodu v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 24, 'Vrhutega je Josija iztrebil tudi rotilce mrtvih in čarodejnike in hišne bogove, malike in vse grdobe, kar se jih je zalotilo v deželi Judovi in v Jeruzalemu, da uveljavi besede postave, pisane v knjigi, ki jo je našel duhovnik Hilkija v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 25, 'In ni ga bilo njemu podobnega kralja pred njim, ki bi se bil preobrnil h Gospodu iz vsega srca in iz vse duše in iz vse moči svoje, po vsej postavi Mojzesovi, tudi za njim ni vstal nobeden njemu enak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 26, 'Vendar se Gospod ni odvrnil od togote velike jeze svoje, v kateri se je vnel srd njegov zoper Judo, zaradi vsega draženja, s katerim ga je bil dražil Manasej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 27, 'In Gospod je rekel: Odpravim tudi Judo izpred obličja svojega, kakor sem odpravil Izraela, in zavržem mesto to, ki sem si ga izvolil, Jeruzalem, tudi hišo, za katero sem rekel: Ime moje bode ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 28, 'Kar je pa več praviti o Josiju in vse, kar je storil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 29, 'V dnevih njegovih je šel gori Faraon Neko, kralj egiptovski, zoper kralja asirskega na reko Evfrat; njemu je šel Josija nasproti; Neko pa ga je umoril v Megidu, ko ga je bil videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 30, 'In hlapci njegovi so ga mrtvega odpeljali iz Megida in ga pripeljali v Jeruzalem ter pokopali v grobu njegovem. In ljudstvo dežele je vzelo Joahaza, sina Josijevega, in so ga pomazilili ter postavili za kralja namesto očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 31, 'Triindvajset let je bilo Joahazu, ko je zakraljeval, in vladal je tri mesece v Jeruzalemu. Materi njegovi je bilo ime Hamutala, hči Jeremijeva, iz Libne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 32, 'In delal je, kar je bilo hudo v očeh Gospodovih, po vsem, kar so delali očetje njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 33, 'In Faraon Neko ga je dejal v spone v Ribli, v hamatski pokrajini, da ne bi več kraljeval v Jeruzalemu; in naložil je deželi globo: sto talentov srebra in talent zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 34, 'In Faraon Neko je postavil Eljakima, sina Josijevega, za kralja namesto Josija, očeta njegovega, in premenil mu je ime v Jojakima. Joahaza pa je vzel s seboj; in ta je prišel v Egipt in je tam umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 35, 'In Jojakim je dal srebro in zlato Faraonu; toda naložil je doklade deželi, da bi dala tisti denar po Faraonovem povelju: izterjal je srebra in zlata od ljudstva v deželi, od vsakega po cenitvi njegovi, da plača Faraonu Neku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 36, 'Jojakim je bil petindvajset let star, ko je zakraljeval, in vladal je enajst let v Jeruzalemu. In materi njegovi je bilo ime Zebida, hči Pedajeva iz Rume.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 23, 37, 'In delal je, kar je bilo hudo v očeh Gospodovih, po vsem, kar so bili delali očetje njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 1, 'V dnevih njegovih je prišel gori Nebukadnezar, kralj babilonski, in Jojakim mu je postal podložnik za tri leta; potem se je odvrnil in se mu uprl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 2, 'In Gospod je poslal zoper njega trume Kaldejcev in trume Sircev in trume Moabcev in trume Amonovih sinov, poslal jih je zoper Judo, da ga pogube, po besedi Gospodovi, ki jo je govoril po hlapcih svojih, prorokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 3, 'Zares po povelju Gospodovem je to prišlo nad Judo, da jih odpravi izpred obličja svojega, zaradi grehov Manasejevih, za vse, kar je storil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 4, 'pa tudi za nedolžno kri, ki jo je prelil, zakaj napolnil je Jeruzalem z nedolžno krvjo. In Gospod ni hotel odpustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 5, 'Kar je pa več praviti o Jojakimu in vse, kar je storil, ni li zapisano v knjigi letopisov kraljev Judovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 6, 'In legel je Jojakim k očetom svojim, in Jojahin, sin njegov, je zavladal na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 7, 'A kralj egiptovski ni šel več ven iz dežele svoje, zakaj kralj babilonski je zavzel vse od potoka Egiptovskega do reke Evfrata, kar je bilo kralja egiptovskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 8, 'Osemnajst let je bil star Jojahin, ko je zakraljeval, in vladal je tri mesece v Jeruzalemu. Materi njegovi je bilo ime Nehusta, hči Elnatanova iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 9, 'In delal je, kar je bilo hudo v očeh Gospodovih, po vsem, kar je bil delal oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 10, 'V tistem času so prišli hlapci Nebukadnezarja, kralja babilonskega, gori proti Jeruzalemu, in mestu je nastalo obleganje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 11, 'In Nebukadnezar, kralj babilonski, je dospel k mestu, ko so ga hlapci njegovi oblegali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 12, 'Jojahin pa, kralj Judov, je šel iz mesta h kralju babilonskemu, on in mati njegova, hlapci njegovi, knezi in dvorniki njegovi; in kralj babilonski ga je sprejel kot jetnika v osmem letu svojega kraljevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 13, 'In odnesel je odondod vse zaklade hiše Gospodove in zaklade kraljeve hiše in razbil vse posode zlate, ki jih je napravil Salomon, kralj Izraelov, v templju Gospodovem, kakor je bil govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 14, 'In preselil je v ujetništvo ves Jeruzalem in vse kneze in vse hrabre junake, deset tisoč ujetnikov, tudi vse kovače in ključalničarje; nikogar ni ostalo, samo nekaj ubožnega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 15, 'In odpeljal je Jojahina v Babilon, tudi mater kraljevo in žene kraljeve in dvornike njegove in deželne prvake je odpeljal v ujetništvo iz Jeruzalema v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 16, 'In vse vojščake, sedem tisoč, in ključalničarje in kovače, en tisoč, vse krepke in za vojno sposobne je kralj babilonski odpeljal ujete v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 17, 'In kralj babilonski je postavil Matanija, strica Jojahinovega, za kralja namesto njega, premenivši mu ime v Zedekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 18, 'Zedekija je bil enaindvajset let star, ko je zakraljeval, in vladal je enajst let v Jeruzalemu. Materi njegovi je bilo ime Hamutala, hči Jeremijeva iz Libne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 19, 'In delal je, kar je bilo hudo v očeh Gospodovih, po vsem, kar je bil delal Jojakim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 24, 20, 'Zakaj vsled jeze Gospodove se je tako godilo z Jeruzalemom in z Judo, dokler jih ni zavrgel izpred obličja svojega. In Zedekija se je uprl kralju babilonskemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 1, 'Zgodi se pa v devetem letu kraljevanja njegovega, deseti dan desetega meseca, da pride Nebukadnezar, kralj babilonski, in vsa vojska njegova zoper Jeruzalem in se utabori proti njemu. In naredili so obležne ogradbe okrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 2, 'In mesto je bilo oblegano do enajstega leta kralja Zedekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 3, 'Deveti dan četrtega meseca je bila huda lakota v mestu, in ni bilo kruha za ljudstvo dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 4, 'Tedaj je bilo mesto predrto, in vsi vojščaki so pobegnili po noči skozi vrata med dvojnim zidom, ki so bila poleg kraljevega vrta (Kaldejci pa so oblegali mesto kroginkrog); in kralj je šel po poti proti nižini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 5, 'Ali vojska Kaldejcev se drevi za kraljem in ga dohiti na planjavah ob Jerihu; vsa vojska njegova pa se je bila razkropila od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 6, 'Tedaj ujamejo kralja ter ga pripeljejo gori h kralju babilonskemu v Riblo; in izrekli so sodbo nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 7, 'In poklali so sinove Zedekijeve njemu pred očmi, potem so mu oslepili oči ter ga zvezali z dvema bronastima verigama in ga odpeljali na Babilonsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 8, 'Potem pride sedmi dan petega meseca, ko je bilo devetnajsto leto kralja Nebukadnezarja, kralja babilonskega, Nebuzaradan, glavar telesne straže, služabnik kralja babilonskega, v Jeruzalem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 9, 'in požge hišo Gospodovo in hišo kraljevo in vse hiše v Jeruzalemu, namreč vsako večjo hišo požge z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 10, 'In vsa vojska Kaldejcev, kar je je bilo z glavarjem straže, poruši zidove jeruzalemske okroginokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 11, 'Preostanek ljudstva pa, kar ga je ostalo v mestu, in uskoke, ki so odpadli h kralju babilonskemu, in ostanek množice odpelje ujete Nebuzaradan, glavar telesne straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 12, 'Samo iz najubožnejših ljudstva jih je pustil ondi glavar straže, da naj bodo vinogradniki in kmetovalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 13, 'In bronasta stebra, ki sta bila v hiši Gospodovi, in stojala in bronasto morje, ki je bilo v hiši Gospodovi, so razbili Kaldejci ter odnesli njih bron v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 14, 'Tako tudi lonce, lopate, utrinjače in torila in vse bronasto orodje, s katerim se je opravljala služba, so odnesli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 15, 'Tudi ponve in čaše, kar je bilo od zlata, v zlatu, kar od srebra, v srebru je vzel glavar telesne straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 16, 'Tista dva stebra, eno morje in stojala, ki jih je bil napravil Salomon za hišo Gospodovo; tehtati ni bilo mogoče brona od vseh teh priprav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 17, 'Višina enega stebra je bila osemnajst komolcev in glavič na njem je bil iz brona, in višina glaviča je bila tri komolce z mrežastim delom in granatnimi jabolki na glaviču kroginkrog, vse iz brona; in enako tem je imel drugi steber na glaviču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 18, 'In glavar telesne straže je vzel Seraja, prvega duhovnika, in Zefanija, drugega duhovnika, in tri čuvaje pri vratih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 19, 'iz mesta pa je vzel enega dvornika, ki je bil postavljen nad vojščaki, in pet mož izmed tistih, ki so bili kralju najbližji in so se našli v mestu, in pisarja, vojnega poveljnika, ki je nabiral vojsko iz deželnega ljudstva, in šestdeset mož iz deželnega ljudstva, ki so se našli v mestu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 20, 'te je vzel Nebuzaradan, glavar telesne straže, ter jih odpeljal h kralju babilonskemu v Riblo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 21, 'In kralj babilonski jih je udaril in usmrtil v Ribli, v Hamatski deželi. Tako je bil Juda preseljen v ujetništvo iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 22, 'Kar se pa tiče ljudstva, ki je ostalo v deželi Judovi, kar ga je pustil ondi Nebukadnezar, kralj babilonski, nad tem je postavil Gedalija, sina Ahikama, sinu Safanovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 23, 'Ko so pa slišali vsi poveljniki trum, oni in njih možje, da je kralj babilonski postavil za namestnika Gedalija, pridejo v Micpo h Gedaliju, zlasti Izmael, sin Netanijev, in Johanan, sin Kareahov, in Seraja, sin Tanhumeta Netofatčana, in Jazanija, sin Maakatijev, oni s svojimi možmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 24, 'In Gedalija priseže njim in njih možem ter jim reče: Ne bojte se hlapcev Kaldejcev; ostanite v deželi in služite kralju babilonskemu, tako vam bode dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 25, 'Zgodi se pa sedmega meseca, da pride Izmael, sin Netanijev, sinu Elisamovega, iz kraljevega roda, in ž njim deset mož, in udarijo Gedalija, da umrje, tudi Jude in Kaldejce, ki so bili ž njim v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 26, 'In vse ljudstvo, malo in veliko, in poveljniki trum vstanejo ter odidejo v Egipt; bali so se namreč Kaldejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 27, 'Zgodi se pa v tridesetem in sedmem letu ujetništva Jojahinovega, kralja Judovega, dvanajsti mesec, sedemindvajseti dan meseca, da je Evil Merodah, kralj babilonski, v letu, ko je začel kraljevati, povišal glavo Jojahina, kralja Judovega, izpeljavši ga iz ječe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 28, 'In govoril je prijazno ž njim in prestol njegov je postavil nad prestol kraljev, ki so bili ž njim v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 29, 'In premenil mu je jetniško obleko; in je jedel kruh pred kraljem vedno, vse dni življenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (12, 25, 30, 'Kajti živež njegov, stalen živež mu je dajal kralj, odmerjen za vsak dan, vse dni njegovega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 1, 'Adam, Set, Enos,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 2, 'Kenan, Mahalalel, Jared,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 3, 'Enoh, Metuselah, Lameh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 4, 'Noe, Sem, Ham in Jafet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 5, 'Sinovi Jafetovi: Gomer, Magog, Madai, Javan, Tubal, Mesek in Tiras.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 6, 'In sinovi Gomerjevi: Askenaz, Difat in Togarma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 7, 'In sinovi Javanovi: Elisa, Tarsis, Kitim in Rodanim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 8, 'Sinovi Hamovi: Kuš, Mizraim, Put in Kanaan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 9, 'Sinovi Kuševi pa: Seba, Havila, Sabta, Ragma in Sabteka. In sinova Ragmova: Šeba in Dedan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 10, 'In Kuš je rodil Nimroda; ta je začel mogočen biti na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 11, 'Mizraim pa je rodil Ludime, Anamime, Lehabime, Naftuhime,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 12, 'Patrusime, Kasluhime (od katerih izvirajo Filistejci) in Kaftorime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 13, 'Kanaan pa je rodil Sidona, prvenca svojega, in Heta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 14, 'in Jebusejca, Amorejca, Girgasejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 15, 'Hevejca, Arkejca, Sinejca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 16, 'Arvadejca, Zemarejca in Hamatejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 17, 'Sinovi Semovi: Elam, Asur, Arpaksad, Lud, Aram, Uz, Hul, Geter in Mešek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 18, 'In Arpaksad je rodil Šelaha, Šelah pa Heberja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 19, 'Heberju pa sta se rodila dva sinova: ime enemu je bilo Peleg, ker se je v dneh njegovih razdelila zemlja, in bratu njegovemu je bilo ime Joktan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 20, 'In Joktan je rodil Almodada, Šelefa, Hazarmaveta, Jeraha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 21, 'Hadorama, Uzala, Dikla,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 22, 'Ebala, Abimaela, Šeba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 23, 'Ofirja, Havila in Jobaba. Vsi ti so bili sinovi Joktanovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 24, 'Sem, Arpaksad, Šelah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 25, 'Heber, Peleg, Regu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 26, 'Serug, Nahor, Terah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 27, 'Abram (to je Abraham).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 28, 'Sinova Abrahamova: Izak in Izmael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 29, 'To so njiju rodovi: Prvenec Izmaelov Nebajot, potem Kedar, Adbeel, Mibsam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 30, 'Misma, Duma, Masa, Hadad in Tema,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 31, 'Jetur, Nafiš in Kedema. Ti so sinovi Izmaelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 32, 'Sinovi Keture pa, priležnice Abrahamove: rodila je Zimrana, Joksana, Medana, Madiana, Išbaka in Šuaha. Sinova Joksanova: Šeba in Dedan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 33, 'In sinovi Madianovi: Efa, Efer, Hanok, Abida in Eldaa. Vsi ti so bili sinovi Keturini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 34, 'In Abraham je rodil Izaka. Sinova Izakova: Ezav in Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 35, 'Sinovi Ezavovi: Elifaz, Reguel, Jeuš, Jalam in Korah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 36, 'Sinovi Elifazovi: Teman, Omar, Zefi, Gatam, Kenaz, Timna in Amalek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 37, 'Sinovi Reguelovi: Nahat, Zerah, Šama in Miza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 38, 'In sinovi Seirovi: Lotan, Šobal, Zibeon, Ana, Dišon, Ezer in Dišan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 39, 'In sinova Lotanova: Hori in Homam; in sestra Lotanova Timna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 40, 'Sinovi Šobalovi: Aljan, Manahat, Ebal, Šefi in Onam. In sinova Zibeonova: Aja in Ana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 41, 'Sin Anov: Dišon; in sinovi Dišonovi: Hamran, Ešban, Jitran in Keran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 42, 'Sinovi Ezerjevi: Bilhan, Zaavan, Jaakan. Sinova Dišonova: Uz in Aran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 43, 'To pa so kralji, ki so kraljevali v deželi Edomovi, preden je vladal kralj sinovom Izraelovim: Bela, sin Beorjev; in mesto njegovo se je imenovalo Dinhaba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 44, 'In ko je Bela umrl, je vladal Jobab, sin Zerahov iz Bozre, namesto njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 45, 'In Jobab je umrl, in zakraljeval je namesto njega Hušam, iz dežele Temančanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 46, 'In Hušam je umrl, in vladal je na mestu njegovem Hadad, sin Bedadov, ki je porazil Madiana na Moabski poljani. In njegovo mesto se je imenovalo Avit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 47, 'In ko je umrl Hadad, je zakraljeval na mestu njegovem Samla iz Masreke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 48, 'In Samla je umrl, in Savel iz Rehobota ob reki je kraljeval namesto njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 49, 'In Savel je umrl, in Baal-hanan, sin Akborjev, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 50, 'In Baal-hanan je umrl, in Hadad je vladal namesto njega; in njegovo mesto se je imenovalo Pagi, in ženi njegovi je bilo ime Mehetabela, hči Matrede, hčere Mezahabove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 51, 'In Hadad je umrl. In vojvode v Edomu so bili: vojvoda Timna, vojvoda Alja, vojvoda Jetet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 52, 'vojvoda Oholibama, vojvoda Ela, vojvoda Pinon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 53, 'vojvoda Kenaz, vojvoda Teman, vojvoda Mibzar,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 1, 54, 'vojvoda Magdiel, vojvoda Iram. Ti so vojvode v Edomu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 1, 'Ti so sinovi Izraelovi: Ruben, Simeon, Levi in Juda, Isahar in Zebulon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 2, 'Dan, Jožef in Benjamin, Neftali, Gad in Aser.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 3, 'Sinovi Judovi: Ger, Onan in Šela, ti trije so se mu rodili iz hčere Šuvove, Kananejke. Ger pa, Judov prvenec, je bil hudoben v očeh Gospodovih, zato ga je usmrtil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 4, 'In Tamara, snaha in njegova, mu je rodila Pereza in Zeraha. Vseh sinov Judovih je bilo pet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 5, 'Sinova Perezova: Hezron in Hamul.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 6, 'In sinovi Zerahovi: Zimri, Etan, Heman, Kalkol, Dara, vseh skupaj petero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 7, 'In sinovi Karmijevi: Ahar, ki je v nesrečo spravil Izraela, ko se je bil pregrešil pri prokletem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 8, 'In sin Etanov: Azarija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 9, 'In sinovi Hezronovi, ki so se mu rodili: Jerahmeel, Ram in Kelubaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 10, 'In Ram je rodil Aminadaba, Aminadab pa je rodil Nahsona, vojvodo sinov Judovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 11, 'in Nahson je rodil Salma, Salma pa je rodil Boaza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 12, 'in Boaz je rodil Obeda, Obed pa je rodil Jeseja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 13, 'a Jesej je rodil Eliaba, prvenca svojega, in Abinadaba, drugega, in Simea, tretjega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 14, 'Netanela, četrtega, Radaja, petega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 15, 'Ozema, šestega, Davida, sedmega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 16, 'njih sestri pa sta bili Zervija in Abigaila. In sinovi Zervijini: Abisaj in Joab in Asahel, trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 17, 'In Abigaila je rodila Amasa; Amasov oče pa je bil Jeter Izmaelec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 18, 'Kaleb pa, sin Hezronov, je rodil otroke iz Azube, žene svoje, in iz Jeriote; in ti so bili sinovi njeni: Jeser, Sobab in Ardon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 19, 'In Azuba je umrla, in Kaleb si je vzel Efrato, ki mu je rodila Hura.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 20, 'In Hur je rodil Urija, Uri pa je rodil Bezalela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 21, 'Pozneje je šel Hezron k hčeri Mahirja, očeta Gileadovega, ki jo je vzel za ženo, ko mu je bilo šestdeset let; in ona mu je rodila Seguba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 22, 'In Segub je rodil Jaira, ki je imel triindvajset mest v Gileadski pokrajini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 23, 'A Gesurci in Aramci so vzeli Jairove trge s Kenatom in njemu podložnimi mesti vred, šestdeset mest. Vsi ti so bili sinovi Mahirja, očeta Gileadovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 24, 'In po smrti Hezronovi v Kaleb-efrati mu je rodila Abija, žena Hezronova, Ashurja, očeta Tekoa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 25, 'In sinovi Jerahmeela, prvenca Hezronovega, so bili: Ram, prvorojenec, in Buna, Oren, Ozem, Ahija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 26, 'In Jerahmeel je imel drugo ženo, ki ji je bilo ime Atara; ona je bila mati Onamova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 27, 'In sinovi Rama, prvenca Jerahmeelovega, so bili: Maaz, Jamin in Eker.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 28, 'In sinova Onamova sta bila: Šamaj in Jada; in sinova Šamajeva: Nadab in Abisur.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 29, 'In ženi Abisurjevi je bilo ime Abihaila in rodila mu je Ahbana in Molida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 30, 'In sinova Nadabova: Seled in Apaim; Seled pa je umrl brez otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 31, 'In sin Apaimov: Iši; in Išijev sin: Sesan; in sin Sesanov: Ahlaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 32, 'Sinova pa Jada, brata Šamajevega: Jeter in Jonatan; Jeter pa je umrl brez otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 33, 'In sinova Jonatanova: Pelet in Zaza. Ti so bili sinovi Jerahmeelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 34, 'Sesan pa ni imel sinov, samo hčere. In Sesan je imel hlapca, Egipčana, ki mu je bilo ime Jarha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 35, 'In Sesan je dal svojo hčer Jarhu, hlapcu svojemu, za ženo; in ona mu je rodila Ataja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 36, 'In Ataj je rodil Natana, Natan pa je rodil Zabada;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 37, 'in Zabad je rodil Eflala, in Eflal je rodil Obeda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 38, 'in Obed je rodil Jehuja, Jehu pa je rodil Azarija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 39, 'in Azarija je rodil Heleza, Helez pa je rodil Eleasa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 40, 'Eleasa pa je rodil Sismaja, Sismaj je pa rodil Saluma,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 41, 'Salum pa je rodil Jekamija, Jekamija pa je rodil Elisama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 42, 'In sinovi Kaleba, brata Jerahmeelovega, so bili: Mesa, prvenec njegov, ki je bil oče Zifov, in sinovi Maresa, očeta Hebronovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 43, 'In sinovi Hebronovi: Korah, Tapuah, Rekem in Sema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 44, 'In Sema je rodil Rahama, očeta Jorkeamovega, Rekem pa je rodil Šamaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 45, 'In sin Šamajev je bil Maon, Maon pa je bil oče Betzurjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 46, 'In Efa, Kalebova priležnica, je rodila Harana, Moza in Gazeza; Haran pa je rodil Gazeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 47, 'In sinovi Jahdajevi: Regem, Jotam, Gesan, Pelet, Efa in Saaf.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 48, 'Maaka, Kalebova priležnica, je rodila Seberja in Tirhana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 49, 'Rodila je tudi Saafa, očeta Madmana, Seva, očeta Mahbena, in očeta Gibejevega; hči Kalebova pa je bila Aksa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 50, 'Ti so bili sinovi Kalebovi: Sinovi Hura, prvenca Efrate: Šobal, oče Kirjat-jearima;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 51, 'Salma, oče Betlehema, Haref, oče Betgaderja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 52, 'Šobal pa, oče Kirjat-jearima, je imel sinove: Haroe, Hazi, Menuhota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 53, 'In rodovine Kirjat-jearima: Jitrovci, Putovci, Sumatljani in Misrajci; iz njih so prišli Zoratovci in Estaolci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 54, 'Sinovi Salmajevi: Betlehem in Netofatejci, Atrot iz hiše Joabove, in polovica Manahatovcev, Zorovci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 2, 55, 'In rodovine pisarjev, ki so prebivali v Jabezu: Tiratimci, Simeatimci, Sukatimci. Ti so Kenejci, ki so prišli iz Hamata, očeta hiše Rehabove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 1, 'Ti pa so sinovi Davidovi, ki so se mu rodili v Betlehemu: prvenec Amnon, iz Ahinoame Jezreelske; drugi Daniel, iz Abigaile Karmelske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 2, 'tretji Absalom, sin Maake, hčere Talmaja, kralja gesurskega; četrti Adonija, sin Hagite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 3, 'peti Sefatija, iz Abitale; šesti, Itream po Egli, ženi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 4, 'Šest se mu jih je rodilo v Hebronu; in tam je kraljeval sedem let in šest mesecev, v Jeruzalemu pa je kraljeval triintrideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 5, 'Ti pa so se mu rodili v Jeruzalemu: Simea, Sobab, Natan in Salomon, štirje, iz Batsuve, hčere Amieleve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 6, 'in Ibhar, Elisama, in Elifelet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 7, 'Noga, Nefeg, Jafija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 8, 'Elisama, Eliada in Elifelet, devet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 9, 'Vsi ti so bili sinovi Davidovi, razen sinov priležnic; Tamara pa je bila njih sestra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 10, 'Salomonov sin pa je bil Roboam, tega sin Abija, tega sin Asa, tega sin Josafat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 11, 'tega sin Joram, tega sin Ahazija, tega sin Joas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 12, 'tega sin Amazija, tega sin Azarija, tega sin Jotam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 13, 'tega sin Ahaz, tega sin Ezekija, tega sin Manasej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 14, 'tega sin Amon, tega sin Josija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 15, 'In sinovi Josijevi: prvenec Johanan, drugi Jojakim, tretji Zedekija, četrti Salum.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 16, 'Sinova pa Jojakimova: tega sin Jekonija, tega sin Zedekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 17, 'In sinovi Jekonija, jetnika: Sealtiel, sin njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 18, 'Malhiram, Pedaja, Senazar, Jekamija, Hosama in Nedabija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 19, 'In sinova Pedajeva: Zerubabel in Simej, in sinova Zerubabelova: Mesulam in Hananija, in Šelomita je bila njiju sestra;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 20, 'in Hasuba, Ohel, Berekija, Hasadija, Jušab-hesed, pet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 21, 'In sinova Hananijeva: Pelatija in Jesaja; sinovi Refajevi, sinovi Arnanovi, sinovi Obadijevi, sinovi Sekanijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 22, 'In sinovi Sekanijevi: Semaja in sinovi Semajevi: Hatuš, Igal, Bariah, Nearija in Safat, šest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 23, 'In sinovi Nearijevi: Eljoenaj, Ezekija in Azrikam, trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 3, 24, 'In sinovi Eljoenajevi: Hodavija, Eliasib, Pelaja, Akub, Johanan, Delaja in Anani, sedem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 1, 'Sinovi Judovi: Perez, Hezron, Karmi, Hur in Šobal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 2, 'Reaja, sin Šobalov, pa je rodil Jahata, in Jahat je rodil Ahumaja in Lahada. To so rodovine Zoratovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 3, 'In ti so bili sinovi očeta Etama: Jezreel, Išma in Idbaš, in njih sestri je bilo ime Hazelelpona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 4, 'in Penuel, oče Gedorjev, in Ezer, oče Husajev. Ti so sinovi Hura, prvenca Efrate, očeta Betlehema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 5, 'Ashur pa, oče Tekoa, je imel dve ženi, Helo in Naaro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 6, 'In Naara mu je rodila Ahuzama, Heferja, Temenija, Ahastarija; ti so bili sinovi Naare.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 7, 'Sinovi Hele pa so bili Zeret, Izhar in Etnan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 8, 'In Koz je rodil Anuba, Zobeba in rodovine Aharhela, sinú Harumovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 9, 'In Jabez je bil imenitnejši mimo svojih bratov; in mati njegova mu je dala ime Jabez, rekoč: Ker sem ga rodila z bolečino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 10, 'In Jabez je klical Boga Izraelovega, govoreč: O da bi me obilo blagoslovil in razširil mejo mojo ter da bi bila roka tvoja z menoj in bi me branil zlega, da me ne zadene bolečina! In Bog je dal, da je prišlo, česar je prosil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 11, 'In Kelub, brat Suhajev, je rodil Mehirja, ki je bil oče Estona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 12, 'In Eston je rodil Betrafa, Paseaha in Tehina, očeta mesta Nahasa. To so možje iz Reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 13, 'In sinova Kenazova: Otniel in Seraja; in sin Otnielov: Hatat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 14, 'In Meonotaj je rodil Ofra; in Seraja je rodil Joaba, očeta doline umetnikov; bili so namreč umetniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 15, 'In sinovi Kaleba, sina Jefunovega: Iru, Ela in Naam; in sinovi Elovi in Kenaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 16, 'In sinovi Jehalelelovi: Zif in Zifa,Tirja in Asarel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 17, 'In sinovi Ezrovi: Jeter, Mered, Efer in Jalon. In ona je rodila Mirjama, Šamaja in Isbaha, očeta Estemoa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 18, 'In žena njegova, Judinja, je rodila Jereda, očeta Gedorjevega, in Heberja, očeta Sokovega, in Jekutiela, očeta Zanoahovega. In ti so sinovi Bitije, hčere Faraonove, ki si jo je vzel Mered.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 19, 'In sinova žene Hodijeve, sestre Nahamove: oče Keile, Garmejec, in Estemoa, Maakatovec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 20, 'Simonovi sinovi pa: Amnon, Rina, Benhanan in Tilon. In sinova Išejeva: Zohet in Benzohet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 21, 'Sinovi Šela, sinu Judovega: Ger, oče Lekov, in Laeda, oče Maresov, in rodovine hiše tistih, ki so tkali tenčico, iz hiše Asbea;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 22, 'in Jokim in možje iz Kozebe, in Joas in Saraf, ki sta gospodovala Moabu in bivala v Lehemu. Ti zaznamki pa so stari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 23, 'Ti so bili lončarji in so stanovali po sadiščih in ograjah; prebivali so ondi pri kralju, da so delali zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 24, 'Sinovi Simeonovi: Nemuel in Jamin, Jarib, Zerah, Savel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 25, 'tega sin Salum, tega sin Mibsam, tega sin Misma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 26, 'In sinovi Mismovi: Hamuel, sin njegov, tega sin Zakur, tega sin Simej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 27, 'Simej pa je imel šestnajst sinov in šest hčer, ali bratje njegovi niso imeli veliko sinov, in vse njih rodovine se niso množile toliko, kolikor sinovi Judovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 28, 'In prebivali so v Bersebi, Moladi, Hazar-suvalu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 29, 'v Bilhi, Ezemu, Toladu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 30, 'v Betuelu, Hormi, Ziklagu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 31, 'Bet-markabotu, Hazar-susimu in v Bet-bireju in v Saaraimu. Ta so bila njih mesta do kraljevanja Davidovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 32, 'In njih vasi: Etam in Ajin, Rimon in Tohen in Asan, pet mest');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 33, 'in vse njih vasi, ki so bile okoli teh mest tja do Baala. To so bila njih prebivališča in so imeli svoj rodopis.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 34, 'In Mesobab, Jamleh in Josa, sin Amazijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 35, 'in Joel in Jehu, sin Josibijev, sinu Seraja, sinu Asiela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 36, 'in Eljoenaj, Jaakoba, Jesohaja, Asaja, Adiel, Jesimiel, Benaja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 37, 'in Ziza, sin Sifijev, sinu Alona, sinu Jedaja, sinu Simrija, sinu Semaja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 38, 'ti po imenih omenjeni so bili knezi v svojih rodovinah; in njih očetovske hiše so se množile silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 39, 'In šli so k vhodu v Gedor, proti vzhodu doline, da poiščejo pašnikov svoji drobnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 40, 'In našli so obilnih in dobrih pašnikov, in kraj je bil prostran in miren in tih; kajti tisti, ki so ondi nekdaj prebivali, so bili Hamovega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 41, 'In ti, zapisani po imenih, so prišli v dnevih Ezekija, kralja Judovega, in so razdejali njih šatore in Meunime, ki so bili ondi, in so jih s prokletjem zatrli, do tega dne, in se nastanili na njih mestu; kajti ondi je bila paša za njih drobnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 42, 'In nekateri iz njih, iz sinov Simeonovih, petsto mož, so šli na Seirsko gorovje, in Pelatija in Nearija in Refaja in Uziel, sinovi Išijevi, so jim bili na čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 4, 43, 'In pobili so ostanek Amalekovcev, ki so bili tja ušli, in nastanili so se ondi do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 1, 'In sinovi Rubena, prvenca Izraelovega (kajti on je bil prvorojenec, ali ker je onečastil očeta svojega posteljo, je bilo prvorojenstvo njegovo dano sinoma Jožefa, sinu Izraelovega; toda v rodopisu se to prvenstvo ne šteje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 2, 'Zakaj Juda je bil junak med svojimi brati in iz njega je prišel vojvoda; a pravica prvenstva je bila Jožefova),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 3, 'sinovi Rubena, prvenca Izraelovega: Hanok, Palu, Hezron in Karmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 4, 'Sinovi Joelovi: njegov sin Semaja, tega sin Gog, tega sin Simej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 5, 'tega sin Miha, tega sin Reaja, tega sin Baal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 6, 'tega sin Beera, ki ga je Tilgat-pilneser, kralj asirski, odvedel v ujetništvo; on je bil vojvoda Rubenovcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 7, 'In njegovi bratje po svojih rodovinah, kakor so bili zapisani po svojem rodosledju: poglavar Jegiel in Zeharija');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 8, 'in Bela, sin Azaza, sinu Sema, sinu Joela, ki je prebival v Aroerju tja do Neba in Baalmeona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 9, 'in proti vzhodu je prebival tja do vhoda v puščavo od reke Evfrata; ker njih črede so se pomnožile v deželi Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 10, 'V dnevih Savlovih pa so se bojevali zoper Hagarence, ki so padli po njih roki; in nastanili so se v njih šatorih po vsej deželi vzhodno od Gileada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 11, 'In sinovi Gadovi so prebivali njim nasproti, v Basánski deželi tja do Saleka:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 12, 'Joel, poglavar, in Safam, drugi, in Janaj in Safat v Basanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 13, 'In njih bratje po svojih očetovskih hišah: Mihael, Mesulam, Seba, Joraj, Jakan, Zia in Heber, sedem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 14, 'Ti so bili sinovi Abihaila, sinu Hurija, sinu Jaroaha, sinu Gileada, sinu Mihaela, sinu Jesisaja, sinu Jahda, sinu Buza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 15, 'Ahi, sin Abdielov, sinu Gunija, je bil poglavar njih očetovske hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 16, 'In prebivali so v Gileadu v Basanu in po njega vaseh in po vseh Saronskih pašnikih tja do njih mej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 17, 'Vsi ti so bili zapisani v rodopise v dnevih Jotama, kralja Judovega, in v dnevih Jeroboama, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 18, 'Sinov Rubenovih in Gadovih in polovice rodu Manasejevega, kar jih je bilo hrabrih mož, ki so nosili ščit in meč in streljali z lokom in so bili vešči vojni, je bilo štiriinštirideset tisoč sedemsto in šestdeset, ki so bili sposobni iti v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 19, 'In vojskovali so se s Hagarenci in z Jeturjem in Nafisom in Nodabom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 20, 'In Bog jim je pomagal zoper nje, in Hagarenci so jim bili dani v roko in vsi, ki so bili ž njimi; kajti klicali so k Bogu v boju, in dal se jim je izprositi, ker so zaupali vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 21, 'In odpeljali so si njih živino: petdeset tisoč njih velblodov, dvestoinpetdeset tisoč glav drobnice, dva tisoč oslov in sto tisoč ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 22, 'Kajti padlo jih je mnogo ranjenih, ker je bil boj od Boga. In prebivali so na njih mestu do preselitve v ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 23, 'In sinovi polovice rodu Manasejevega so prebivali v deželi: razmnožili so se od Basana do Baal-hermona in Senirja in do Hermonske gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 24, 'In ti so bili poglavarji svojih očetovskih hiš: Efer, Iši, Eliel, Azriel, Jeremija, Hodavija in Jahdiel, vojni junaki, imenitni možje, glavarji svojih očetovskih hiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 25, 'Ali izneverili so se Bogu očetov svojih in so nečistovali za bogovi narodov te dežele, ki jih je Bog iztrebil izpred njih obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 5, 26, 'Tedaj je Bog obudil duha Pula, kralja asirskega, in duha Tilgat-pilneserja, kralja asirskega, in odpeljal jih je, namreč Rubence, Gadovce in polovico rodu Manasejevega, in jih je preselil v Halah in Habor in Haro in k reki Gozanu do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 1, 'Sinovi Levijevi: Gerson, Kahat in Merari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 2, 'In sinovi Kahatovi: Amram, Izhar, Hebron in Uziel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 3, 'In otroci Amramovi: Aron, Mojzes in Mirjama. In sinovi Aronovi: Nadab in Abihu, Eleazar in Itamar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 4, 'Eleazar je rodil Pinehasa, Pinehas je rodil Abisua;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 5, 'Abisua pa je rodil Bukija, in Buki je rodil Uzija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 6, 'Uzi pa je rodil Zerahija, in Zerahija je rodil Merajota,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 7, 'Merajot je rodil Amarija, in Amarija je rodil Ahituba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 8, 'Ahitub pa je rodil Zadoka, in Zadok je rodil Ahimaaza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 9, 'in Ahimaaz je rodil Azarija, Azarija pa je rodil Johanana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 10, 'in Johanan je rodil Azarija; ta je tisti, ki je izvrševal duhovniško službo v hiši, ki jo je Salomon sezidal v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 11, 'Azarija pa je rodil Amarija, in Amarija je rodil Ahituba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 12, 'in Ahitub je rodil Zadoka, in Zadok je rodil Saluma,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 13, 'Salum pa je rodil Hilkija, in Hilkija je rodil Azarija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 14, 'Azarija pa je rodil Seraja, in Seraja je rodil Jehozadaka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 15, 'in Jehozadak je šel v ujetništvo, ko je Gospod preselil Judo in Jeruzalem po roki Nebukadnezarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 16, 'Sinovi Levijevi: Gersom, Kahat in Merari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 17, 'In ti sta imeni sinov Gersomovih: Libni in Simej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 18, 'Sinovi Kahatovi pa so bili Amram, Izhar, Hebron in Uziel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 19, 'Sinova Merarijeva: Mahli in Musi. To so rodovine levitov po njih očetovskih hišah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 20, 'Od Gersoma: tega sin Libni, tega sin Jahat, tega sin Zima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 21, 'tega sin Joah, tega sin Ido, tega sin Zerah, tega sin Jeatraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 22, 'Sinovi Kahatovi: njegov sin Aminadab, tega sin Korah, tega sin Asir,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 23, 'tega sin Elkana, tega sin Ebiasaf, tega sin Asir,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 24, 'tega sin Tahat, tega sin Uriel, tega sin Uzija, tega sin Savel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 25, 'In sinovi Elkana: Amasaj in Ahimot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 26, 'sinovi Elkanovi: tega sin Zofaj, in tega sin Nahat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 27, 'tega sin Eliab, tega sin Jehoram, tega sin Elkana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 28, 'In sinova Samuelova: prvenec Vašni-Joel, drugi Abija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 29, 'Sinovi Merarijevi: Mahli, tega sin Libni, tega sin Simej, tega sin Uza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 30, 'tega sin Simea, tega sin Hagija, tega sin Asaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 31, 'Ti pa so, ki jih je David postavil v vodstvo za petje v hiši Gospodovi, potem ko je skrinja dobila mesto počivanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 32, 'In služili so s petjem pred prebivališčem shodnega šatora, dokler ni sezidal Salomon hiše Gospodove v Jeruzalemu, in so stali v službi svoji po svojem redu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 33, 'In ti so, ki so stali v službi, in njih sinovi: od sinov Kahatovcev: Heman, pevec, sin Joela, sinu Samuela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 34, 'sinu Elkana, sinu Jerohama, sinu Eliela, sinu Toaha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 35, 'sinu Zufa, sinu Elkana, sinu Mahata, sinu Amasaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 36, 'sinu Elkana, sinu Joela, sinu Azarija, sinu Zefanija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 37, 'sinu Tahata, sinu Asirja, sinu Ebiasafa, sinu Koraha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 38, 'sinu Izharja, sinu Kahata, sinu Levija, sinu Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 39, 'In brat njegov je bil Asaf, ki je stal na njegovi desnici, namreč Asaf, sin Berekija, sinu Simea,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 40, 'sina Mihaela, sinu Baaseja, sinu Malkija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 41, 'sinu Etnija, sinu Zeraha, sinu Adaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 42, 'sinu Etana, sinu Zima, sinu Simeja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 43, 'sinu Jahata, sinu Gersoma, sinu Levijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 44, 'Na levici so stali njih bratje, sinovi Merarijevi: Etan, sin Kisija, sinu Abdija, sinu Maluka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 45, 'sinu Hasabija, sinu Amazija, sinu Hilkija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 46, 'sinu Amzija, sinu Banija, sinu Semerja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 47, 'sinu Mahlija, sinu Musija, sinu Merarija, sinu Levijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 48, 'In njih bratje, leviti, so bili določeni za vso službo pri prebivališču hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 49, 'Aron in sinovi njegovi pa so darovali na žgalnem oltarju in na kadilnem oltarju in so bili za vso službo Najsvetejšega ter da opravljajo spravo za Izraela, po vsem, kar je bil Mojzes, hlapec Božji, zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 50, 'In ti so sinovi Aronovi: Eleazar, sin njegov, tega sin Pinehas, tega sin Abisua,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 51, 'tega sin Buki, tega sin Uzi, tega sin Zerahija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 52, 'tega sin Merajot, tega sin Amarija, tega sin Ahitub,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 53, 'tega sin Zadok, tega sin Ahimaaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 54, 'To pa so njih bivališča, po njih seliščih v njih mejah: Sinovom Aronovim iz rodu Kahatovcev (njim je bil namreč prvi delež)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 55, 'so dali Hebron v deželi Judovi in njegove pašnike okoli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 56, 'a njive mesta in njegove vasi so dali Kalebu, sinu Jefunovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 57, 'In sinovom Aronovim so dali zavetna mesta: Hebron, Libno s pašniki, Jatir in Estemoo s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 58, 'Holon s pašniki, Debir s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 59, 'Asan s pašniki, Betsemes s pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 60, 'In od rodu Benjaminovega: Gebo in njene pašnike, Alemet s pašniki in Anatot s pašniki. Vseh njih mest po njih rodovinah je bilo trinajst mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 61, 'Drugim sinom Kahatovim so po žrebu dali od rodovin rodu... od polovice rodu, polovice Manaseja, deset mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 62, 'In sinovom Gersomovim, po njih rodovinah, od rodu Isaharjevega in od rodu Aserjevega in od rodu Neftalijevega in od rodu Manasejevega v Basánu: trinajst mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 63, 'Sinovom Merarijevim so dali po žrebu, po njih rodovinah, od rodu Rubenovega in od rodu Gadovega in od rodu Zebulonovega: dvanajst mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 64, 'Dali so torej sinovi Izraelovi levitom mesta ž njih pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 65, 'In so dali po žrebu od rodu sinov Judovih in od rodu sinov Simeonovih in od rodu sinov Benjaminovih ta mesta, ki so jih imenovali po imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 66, 'In nekatere rodovine sinov Kahatovih so dobile mesta v svojo oblast od rodu Efraimovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 67, 'In dali so jim zavetna mesta: Sihem v Efraimskem gorovju in njegove pašnike, tudi Gezer s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 68, 'Jokmean s pašniki, Bethoron s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 69, 'Ajalon s pašniki, Gat-rimon s pašniki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 70, 'in od polovice rodu Manasejevega: Aner s pašniki, Bileam s pašniki. Ta so dali rodovinam ostalih sinov Kahatovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 71, 'Sinovom Gersomovim so dali: od polovice rodu Manasejevega: Golan v Basánu in njegove pašnike, Astarot s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 72, 'in od rodu Isaharjevega: Kedes s pašniki, Daberat s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 73, 'Ramot s pašniki, Anem s pašniki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 74, 'in od rodu Aserjevega: Masal in njegove pašnike, Abdon s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 75, 'Hukok s pašniki, Rehob s pašniki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 76, 'in od rodu Neftalijevega: Kedes v Galileji in njegove pašnike, Hamon s pašniki in Kirjataim s pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 77, 'Drugim sinovom Merarijevim: od rodu Zebulonovega: Rimono s pašniki, Tabor s pašniki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 78, 'in za Jordanom pri Jerihu, na vzhodni strani Jordana, so jim dali od rodu Rubenovega: Bezer v puščavi in njegove pašnike, Jahzo s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 79, 'Kedemot s pašniki, Mefaat s pašniki;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 80, 'in od rodu Gadovega: Ramot v Gileadu in njegove pašnike, Mahanaim s pašniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 6, 81, 'Hesbon s pašniki in Jazer s pašniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 1, 'In sinovi Isaharjevi so bili: Tola in Puva, Jasub in Simron, štirje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 2, 'In sinovi Tolovi: Uzi, Refaja, Jeriel, Jahmaj, Ibsam in Samuel, poglavarji očetovskih hiš svojih, Tolovih, hrabri junaki po svojih rodovinah; njih število v dnevih Davidovih je bilo dvaindvajset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 3, 'In sinovi Uzijevi: Izrahija, in sinovi Izrahijevi: Mihael, Obadija, Joel, Išija, pet, vsi poglavarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 4, 'In pri njih so bile, po njih rodovih, po njih očetovskih hišah, vojne čete, šestintrideset tisoč mož; kajti imeli so mnogo žen in sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 5, 'In njih bratov, po vseh rodovinah Isaharjevih, hrabrih junakov, vseh zapisanih v rodopisu, je bilo sedeminosemdeset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 6, 'Benjaminovi sinovi: Bela, Beker in Jediael, trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 7, 'In sinovi Belovi: Ezbon, Uzi, Uziel, Jerimot in Iri, pet, poglavarji v hišah svojih očetov, hrabri možje; in bilo jih je v rodopisu zapisanih dvaindvajset tisoč in štiriintrideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 8, 'In sinovi Bekerjevi: Zemira, Joas, Eliezer, Eljoenaj, Omri, Jeremot, Abija, Anatot in Alemet. Vsi ti so bili sinovi Bekerjevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 9, 'In vpisanih je bilo v rodopisu, po svojih rodovih, poglavarji hiš svojih očetov, hrabrih mož, dvajset tisoč in dvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 10, 'In sinovi Jediaelovi: Bilhan, in Bilhanovi sinovi: Jeuš, Benjamin, Ehud, Kenaana, Zetan, Tarsis in Ahisahar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 11, 'Vsi ti so bili sinovi Jediaelovi, po svojih zarodnikih, hrabri junaki, sedemnajst tisoč in dvesto, ki so bili sposobni iti z vojsko v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 12, 'Tudi Supimi in Hupimi, sinovi Irijevi. Husimi, sinovi Aherjevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 13, 'Sinovi Neftalijevi: Jahziel, Guni, Jezer in Salum, sinovi Bilhe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 14, 'Sinovi Manasejevi: Asriel, ki ga je rodila...; njegova aramejska priležnica je rodila Mahirja, očeta Gileadovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 15, 'Mahir pa si je vzel ženo od Hupimov in Supimov, in ime sestri njeni je bilo Maaka. In ime drugemu sinu je bilo Zelofad; Zelofad pa je imel hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 16, 'In Maaka, žena Mahirjeva, je rodila sina in ga je imenovala Peresa; in bratu njegovemu je bilo ime Seres, in sinova njegova sta bila Ulam in Rekem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 17, 'In sin Ulamov: Bedan. Ti so bili sinovi Gileada, sina Mahirja, sinu Manasejevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 18, 'In sestra njegova Moleketa je rodila Ishoda in Abiezerja in Mahla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 19, 'In sinovi Semidovi so bili: Ahian, Sihem, Likhi in Aniam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 20, 'In sinovi Efraimovi: Sutelah, in Bered, sin njegov, in tega sin Tahat, tega sin Elada, tega sin Tahat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 21, 'tega sin Zabad in tega sin Sutelah, in Ezer in Elad. In umorili so jih možje iz Gata, rojeni v deželi, ker so prišli doli, da se polaste njih živine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 22, 'In njih oče Efraim je žaloval veliko dni, in bratje njegovi so ga prišli tolažit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 23, 'In šel je k svoji ženi, in je spočela in rodila sina; in imenoval je ime njegovo Berija, ker je bila hiša njegova v nesreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 24, 'In hči njegova je bila Seera, ki je postavila Dolenji in Zgornji, Bethoron in Uzen-seero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 25, 'In Refah je bil sin njegov in Resef, in tega sin Telah, in tega sin Tahan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 26, 'tega sin Ladan, tega sin Amihud, tega sin Elisama,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 27, 'tega sin Nun, tega sin Jozue.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 28, 'In njih posestva in bivališča so bila: Betel in njemu podložne vasi, proti vzhodu pa Naaran in proti zahodu Gezer in njegove podložne vasi, tudi Sihem in njemu podložne vasi tja do Aze in njenih podložnih vasi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 29, 'in poleg meje sinov Manasejevih: Betsean in njegove podložne vasi, Taanah in njemu podložne vasi, Megido in njemu podložne vasi, Dor in njemu podložne vasi. V teh so prebivali sinovi Jožefa, sina Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 30, 'Sinovi Aserjevi: Jimna, Jišva, Jišvi, Berija in Seraha, njih sestra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 31, 'In sinova Berijeva: Heber in Malkiel, ki je bil oče Birzavita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 32, 'In Heber je rodil Jafleta in Somerja in Hotama in Suvo, njih sestro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 33, 'In sinovi Jafletovi: Pasak, Bimhal in Asvat. To so otroci Jafletovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 34, 'In sinovi Somerjevi: Ahi, Rohga, Huba in Aram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 35, 'In. sinovi Helema, brata njegovega: Zofah, Imna, Seles in Amal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 36, 'Sinovi Zofahovi: Suah, Harnefer, Sual, Beri, Imra,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 37, 'Bezer, Hod, Sama, Silsa, Jitran in Beera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 38, 'In sinovi Jeterjevi: Jefune, Pispa in Ara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 39, 'In sinovi Ulovi: Arah, Haniel in Rizja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 7, 40, 'Vsi ti so bili sinovi Aserjevi, poglavarji očetovskih hiš, izbrani in junaški možje, prvaki knezov. In število njih vpisanih v rodopise za službo pri vojski je bilo šestindvajset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 1, 'Benjamin pa je rodil Bela, prvenca svojega, Ašbela, drugega, in Aheraha, tretjega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 2, 'Noha, četrtega, in Rafa, petega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 3, 'In Bela je imel sinove: Adarja, Gera in Abihuda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 4, 'Abisua, Naamana in Ahoaha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 5, 'Gera, Sefufana in Hurama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 6, 'In ti so sinovi Ehudovi, ti so bili poglavarji očetovskih hiš prebivalcem v Gebi, in odpeljali so jih ujete v Manahat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 7, 'namreč Naaman, Ahija in Gera, ta jih je odpeljal; in rodil je Uza in Ahihuda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 8, 'Saharaim je rodil otroke v Moabski deželi, potem ko je bil odslovil Husimo in Baaro, ženi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 9, 'In rodil je s Hodeso, ženo svojo: Jobaba, Zibija, Mesa, Malkama,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 10, 'Jeuza, Sakija in Mirma. Ti so bili sinovi njegovi, poglavarji očetovskih hiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 11, 'S Husimo pa je rodil Abituba in Elpaala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 12, 'In sinovi Elpaalovi: Heber, Misam in Semed, ki je sezidal Ono in Lod in njemu podložne vasi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 13, 'in Berija in Sema, ki sta bila poglavarja očetovskih hiš prebivalcem v Ajalonu, ki sta zapodila v beg prebivalce iz Gata;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 14, 'in Ahio, Sasak in Jeremot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 15, 'Zebadija, Arad in Eder,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 16, 'Mihael, Ispa in Joha, sinovi Berijevi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 17, 'in Zebadija, Mesulam, Hizki, Heber,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 18, 'Ismeraj, Izlija in Jobab, sinovi Elpaalovi. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 19, 'In Jakim, Zihri, Zabdi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 20, 'Elienaj, Ziletaj, Eliel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 21, 'Adaja, Beraja in Simrat, sinovi Simejevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 22, 'Ispan, Heber, Eliel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 23, 'Abdon, Zihri, Hanan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 24, 'Hananija, Elam, Antotija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 25, 'Ifdeja in Penuel, sinovi Sasakovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 26, 'In Samseraj, Seharija, Atalija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 27, 'Jaaresija, Elija in Zihri, sinovi Jerohamovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 28, 'Ti so bili poglavarji očetovskih hiš po svojih rodovinah, prvaki; ti so prebivali v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 29, 'In v Gibeonu je prebival oče Gibeonov, čigar ženi je bilo ime Maaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 30, 'In prvorojeni sin njegov je bil Abdon, potem Zur, Kis, Baal, Nadab,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 31, 'Gedor, Ahio in Zeher.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 32, 'In Miklot je rodil Simea. Ti so tudi prebivali z brati svojimi v Jeruzalemu, bratom svojim nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 33, 'In Ner je rodil Kisa, Kis pa je rodil Savla, Savel pa je rodil Jonatana in Malhisua in Abinadaba in Esbaala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 34, 'In sin Jonatanov je bil Merib-baal, in Merib-baal je rodil Miha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 35, 'In sinovi Mihovi: Piton, Melek, Tarea in Ahaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 36, 'In Ahaz je rodil Jehoada, in Jehoada je rodil Alemeta in Azmaveta in Zimrija; Zimri pa je rodil Moza;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 37, 'Moza pa je rodil Binea; in njegov sin je bil Rafa, tega sin Eleasa, tega sin Azel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 38, 'In Azel je imel šest sinov, katerih imena so ta: Azrikam, Bokeru, Izmael, Searija, Obadija in Hanan. Vsi ti so bili sinovi Azelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 39, 'In sinovi Eseka, njegovega brata: Ulam, prvenec njegov, Jeuš, drugi, in Elifelet, tretji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 8, 40, 'In sinovi Ulamovi so bili hrabri junaki, lokostrelci, in so imeli mnogo otrok in vnukov, sto in petdeset. Vsi ti so bili od sinov Benjaminovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 1, 'In ves Izrael je bil zaznamovan v rodopisih; in glej, zapisani so v knjigo kraljev Izraelovih. In Juda je bil preseljen v ujetništvo v Babilon zaradi nezvestobe svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 2, 'Prvi prebivalci pa, ki so bivali na svojih posestvih, v svojih mestih, so bili Izraelci, duhovniki, leviti in Netinimci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 3, 'In v Jeruzalemu so prebivali od sinov Judovih in od sinov Benjaminovih in od sinov Efraimovih in Manasejevih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 4, 'Utaj, sin Amihuda, sinu Omrija, sinu Imrija, sinu Banija, iz sinov Pereza, sina Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 5, 'In od Silonovih: Asaja, prvenec, in njegovi sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 6, 'In od sinov Zerahovih: Jeguel in bratje njegovi, šeststo in devetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 7, 'In od sinov Benjaminovih: Salu, sin Mesulama, sinu Hodavija, sinu Hasenuva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 8, 'in Ibneja, sin Jerohamov, in Ela, sin Uzija, sinu Mikrijevega, in Mesulam, sin Sefatija, sinu Reguela, sinu Ibnija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 9, 'in njih bratje po svojih rodovih, devetsto in šestinpetdeset. Vsi ti možje so bili zarodniki v hišah očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 10, 'In od duhovnikov: Jedaja, Jehojarib in Jakin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 11, 'in Azarija, sin Hilkija, sinu Mesulama, sinu Zadoka, sinu Merajota, sinu Ahituba, poglavar v hiši Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 12, 'in Adaja, sin Jerohama, sina Pashurja, sina Malkija, in Masaj, sin Adiela, sinu Jahzerja, sinu Mesulama, sinu Mesilemita, sinu Imerja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 13, 'in njih bratje, poglavarji svojim očetovskim hišam, sedemnajststo in šestdeset, jako vrli možje v opravilu službe v hiši Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 14, 'In od levitov: Semaja, sin Hašuba, sinu Azrikama, sinu Hasabija, od sinov Merarijevih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 15, 'in Bakbakar, Heres, Galal, Matanija, sin Miha, sinu Zihrija, sinu Asafa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 16, 'in Obadija, sin Semaja, sinu Galala, sinu Jedutuna, in Berekija, sin Asa, sinu Elkana, ki je prebival v vaseh Netofatčanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 17, 'In vratarji: Salum, Akub, Talmon, Ahiman in njih bratje; Salum je bil načelnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 18, 'In doslej čuvajo ob kraljevih vratih proti vzhodu. Oni so bili vratarji tabora sinov Levijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 19, 'In Salum, sin Korejev, sinu Ebiasafa, sinu Koraha, in bratje njegovi od hiše očeta njegovega, Korahovci, so oskrbovali službo kot varuhi na pragu šatora; in njih očetje so bili nad taboriščem Gospodovim, varuhi pri vhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 20, 'Pinehas pa, sin Eleazarjev, jim je bil svoje dni glavar; Gospod je bil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 21, 'Zeharija, sin Meselemija, je bil varuh pri vratih shodnega šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 22, 'Vseh teh, izbranih za varuhe ob vratih, je bilo dvesto in dvanajst. Ti so bili vpisani v rodovnike v svojih vaseh; David in Samuel, videc, jih je postavil v službo zaradi njih zvestobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 23, 'Oni in njih sinovi so imeli nadzorstvo pri vratih hiše Gospodove, ob hiši šatora, kot straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 24, 'Proti štirim vetrovom so stali vratarji, proti vzhodu, zahodu, severu in jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 25, 'In njih bratje v svojih vaseh so morali prihajati vsak sedmi dan, vrsteč se, da bodo ž njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 26, 'zakaj tisti štirje načelniki straže, ki so bili leviti, so imeli določeno službo in so bili nad hrami in nad zakladi v hiši Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 27, 'In prenočevali so okoli hiše Božje, ker jih je vezalo straženje, in dolžni so bili od pirati vsako jutro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 28, 'In nekaterim od njih je bilo streči službenim posodam, zakaj po številu so se prinašale in po številu odnašale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 29, 'Nekateri od njih pa so bili nastavljeni za orodje in za vse priprave svetišča in za belo moko in za vino in olje in kadilo in za dišave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 30, 'In nekateri sinovi duhovnikov so mešali mazilo iz dišav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 31, 'In Matitiju, izmed Levitov – on je bil prvenec Saluma Korahovca – je bilo poverjeno, kar se je peklo v ponvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 32, 'In nekateri njih bratov, sinov Kahatovcev, so skrbeli za vrstitev kruhov, da jih pripravljajo vsako soboto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 33, 'Oni pa, pevci, poglavarji levitskih očetovin, so prebivali, druge službe prosti, v hramih, kajti njih služba jih je vezala po dne in po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 34, 'Ti so bili poglavarji očetovin levitskih, po svojih rodovinah, načelniki; ti so prebivali v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 35, 'V Gibeonu pa so prebivali: oče Gibeonov, Jegiel, čigar ženi je bilo ime Maaka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 36, 'in prvenec njegov Abdon, potem Zur, Kis, Baal, Ner, Nadab,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 37, 'Gedor, Ahio, Zeharija in Miklot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 38, 'In Miklot je rodil Simeama. Tudi ti so prebivali pri svojih bratih v Jeruzalemu, bratom svojim nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 39, 'In Ner je rodil Kisa, in Kis je rodil Savla, Savel pa je rodil Jonatana in Malhisua, in Abinadaba in Esbaala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 40, 'In sin Jonatanov je bil Merib-baal, in Merib-baal je rodil Miha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 41, 'In sinovi Mihovi: Piton in Melek in Tahrea in Ahaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 42, 'Ahaz pa je rodil Jara, in Jara je rodil Alemeta in Azmaveta in Zimrija, Zimri pa je rodil Moza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 43, 'Moza je rodil Binea, tega sin je bil Refaja, tega sin Eleasa, tega sin Azel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 9, 44, 'Azel pa je imel šest sinov, katerih imena so ta: Azrikam, Bokeru, Izmael, Searija, Obadija in Hanan: ti so bili sinovi Azelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 1, 'Filistejci pa so se bojevali z Izraelom; in možje Izraelovi so zbežali pred Filistejci in so padali pobiti na gorovju Gilboi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 2, 'In Filistejci so bili trdo za petami Savlu in sinom njegovim, in Filistejci so pobili Jonatana, Abinadaba in Malhisua, sinove Savlove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 3, 'In bitka je hudo pritiskala na Savla, in lokostrelci so ga dohiteli, in trepetal je pred strelci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 4, 'Tedaj veli Savel svojemu oprodi: Izderi meč svoj in me ž njim prebodi, da ne pridejo ti neobrezanci ter si smeh napravijo z menoj. Ali njegov oproda ni hotel, ker se je silno bal. Zato vzame Savel meč svoj in se nasadi nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 5, 'Ko pa vidi njegov oproda, da je Savel mrtev, se nasadi tudi on na svoj meč in umre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 6, 'Tako je umrl Savel in trije sinovi njegovi; in vsa družina njegova je umrla skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 7, 'Ko so pa videli možje Izraelovi, ki so bili v dolini, da bežé ter da so Savel in sinovi njegovi mrtvi, zapuste svoja mesta in zbeže. In Filistejci so prišli in se nastanili v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 8, 'Zgodi se pa drugi dan, ko pridejo Filistejci slačit pobite, da najdejo Savla in sinove njegove na gorovju Gilboi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 9, 'In ga slečejo ter vzemo glavo njegovo in orožje njegovo in pošljejo po deželi Filistejcev kroginkrog, da se ta vesela vest oznani njih malikom in ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 10, 'In orožje njegovo razpoložé v hiši bogov svojih, njegovo lobanjo pa pribijejo v hiši Dagonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 11, 'Ko so pa slišali vsi v Gileadskem Jabesu vse, kar so bili storili Filistejci Savlu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 12, 'se vzdignejo vsi vojščaki in vzamejo truplo Savlovo in trupla sinov njegovih in jih prineso v Jabes. In pokopali so njih kosti pod hrastom v Jabesu in se postili sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 13, 'In tako je umrl Savel v nezvestobi svoji, ki se je ž njo izneveril Gospodu, zoper besedo Gospodovo, ki je ni izpolnil, pa tudi zato, ker je poiskal rotilko mrtvih, da jo je vprašal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 10, 14, 'Gospoda pa ni vprašal. Zato ga je usmrtil in naklonil je kraljestvo Davidu, sinu Jesejevemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 1, 'Tedaj se zbere ves Izrael pri Davidu v Hebronu in reko: Glej, kost smo tvoja in meso tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 2, 'In v prejšnjih časih, ko je kraljeval Savel, si vodil ti ven in noter Izraela; in Gospod, Bog tvoj, je rekel tebi: Ti boš pasel ljudstvo moje Izraela in ti bodeš vojvoda ljudstvu mojemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 3, 'Tako so prišli vsi starejšine Izraelovi h kralju v Hebron, in David je sklenil zavezo ž njimi v Hebronu pred Gospodom. In pomazilili so Davida za kralja Izraelu, soglasno z besedo Gospodovo po Samuelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 4, 'In David in ves Izrael so šli v Jeruzalem (to je Jebus); ondi so bili Jebusejci, prebivalci dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 5, 'In prebivalci v Jebusu so rekli Davidu: Ne prideš sem noter. Vendar pa je David zavzel grad Sion, to je mesto Davidovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 6, 'In David je rekel: Kdorkoli udari Jebusejce prvi, bode poglavar in poveljnik. In Joab, sin Zervijin, je zlezel gori prvi, in postal je poglavar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 7, 'In David se je nastanil v gradu, zato so ga imenovali mesto Davidovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 8, 'In obzidal je mesto, od Mila in krog, do koder je segalo. Joab pa je popravil drugo po mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 9, 'In David je bolj in bolj napredoval, zakaj Gospod nad vojskami je bil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 10, 'Ti pa so prvi izmed junakov, ki jih je imel David in ki so mu bili vrli pomočniki v kraljestvu njegovem z vsem Izraelom vred, da ga postavijo za kralja po besedi Gospodovi o Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 11, 'In to je število junakov, ki jih je imel David: Jasobeam, sin Hakmonija, prvi iz tridesetih; on je vzdignil sulico svojo zoper tristo in jih je pobil naenkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 12, 'In za njim je bil Eleazar, sin Dodov, Ahohovec, eden izmed treh junakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 13, 'On je bil z Davidom v Pasdamimu, in ondi so bili Filistejci zbrani na boj; bil pa je tam kos njive, poln ječmena, in ljudstvo je bežalo izpred Filjstejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 14, 'In postavita se sredi zemljišča in ga obranita ter pobijeta Filistejce; in Gospod jih je rešil z zmago veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 15, 'In trije izmed tridesetih načelnikov so šli doli v skalo k Davidu, v Adulamsko votlino; in vojska Filistejcev je bila utaborjena v dolini Rafaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 16, 'In David je bil takrat v trdnjavi, in straža Filistejcev je takrat bila v Betlehemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 17, 'In Davida je obšla želja in je rekel: O da bi mi kdo dal piti vode iz studenca v Betlehemu, ki je pri vratih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 18, 'In ti trije so predrli skozi tabor Filistejcev in zajeli vode iz studenca v Betlehemu, ki je bil pri vratih, in so jo vzeli in prinesli Davidu. A David je ni hotel piti, temuč jo je izlil kot daritev Gospodu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 19, 'in je rekel: Bog mi ne daj, da bi to storil! Naj li pijem kri teh mož, ki so vnemar pustili življenje svoje? kajti z nevarnostjo svojega življenja so jo prinesli sem! Zato je ni hotel piti. To so storili ti trije junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 20, 'In Abisaj, brat Joabov, je bil glava drugim trem; zakaj mahnil je s sulico svojo po treh sto in jih je pobil; in imel je sloveče ime med temi tremi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 21, 'Izmed teh treh druge vrste je bil najbolj slaven in jim je postal poveljnik; toda prvih treh ni dosegel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 22, 'Benaja, sin Jojadov, sin hrabrega; moža iz Kabzeela, ki je bil storil velika dela, ta je ubil dva sina Ariela iz Moaba; ta je stopil tudi doli v jamo in ubil leva v njej, ko je bil sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 23, 'In ubil je Egipčana, moža visoke postave, pet komolcev dolgega, in Egipčan je imel v roki sulico kakor tkalčje vratilo, a on je šel doli k njemu s palico in iztrgal sulico Egipčanu iz roke ter ga prebodel z lastno sulico njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 24, 'To je storil Benaja, sin Jojadov, in je imel sloveče ime med temi tremi junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 25, 'Glej, on je bil slavnejši nego tistih trideset, ali prvih treh ni dosegel; in David ga je postavil med svoje svetovalce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 26, 'In junaki v vojskah so bili: Asahel, brat Joabov, Elhanan, sin Dodov iz Betlehema,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 27, 'Samot Harorčan, Helez Pelonjan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 28, 'Ira, sin Ikešev, Tekojčan, Abiezer Anatotčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 29, 'Sibekaj Husajec, Ilaj Ahohovec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 30, 'Maharaj Netofatčan, Heled Netofatčan, sin Baanov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 31, 'Itaj, sin Ribajev iz Gibee sinov Benjaminovih, Benaja Piratončan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 32, 'Huraj od potokov v Gaasu, Abiel Arbatski,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 33, 'Azmavet Baharumčan, Eljahba Salbončan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 34, 'sinovi Hasema Gizonca, Jonatan, sin Sageja Hararovca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 35, 'Ahiam, sin Sakarja Hararovca, Elifal, sin Urov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 36, 'Hefer Mekerajec, Ahija Pelonjan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 37, 'Hezro Karmelčan, Naaraj, sin Ezbajev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 38, 'Joel, brat Natanov, Mibhar, sin Hagrijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 39, 'Zelek Amonec, Naharaj Berotčan, oproda Joaba, sinu Zervijinega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 40, 'Ira Jitričan, Gareb Jitričan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 41, 'Urija Hetejec, Zabad, sin Ahlajev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 42, 'Adina, sin Sizov, Rubenovec, načelnik Rubenovcev in tridesetih ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 43, 'Hanan, sin Maake, Josafat Mitnejec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 44, 'Uzija Astarotčan, Sama in Jegiel, sinova Hotama Aroerskega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 45, 'Jediael, sin Simrijev, in brat njegov Joha Tizijčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 46, 'Eliel Mahavim, Jeribaj in Josavija, sinova Elnaama, in Itma Moabec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 11, 47, 'Eliel in Obed in Jaasiel Mezobajan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 1, 'In ti so, ki so prišli k Davidu v Ziklag, ko se je še skrival pred Savlom, sinom Kisovim; in bili so tudi med junaki, ki so mu pomagali v boju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 2, 'oboroženi z loki, in so z desno in levo roko s prač metali kamenje in pšice streljali z loka; bili so pa od bratov Savlovih, iz Benjamina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 3, 'Načelnik jim je bil Ahiezer, potem Joas, sinova Semaa Gibeatčana; Jeziel in Pelet, sinova Azmavetova; Beraka in Jehu Anatotčan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 4, 'Ismaja Gibeončan, korenjak med tridesetimi in njih poveljnik; Jeremija, Jahaziel, Johanan, Jozabad Gederčan;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 5, 'Eluzaj, Jerimot, Bealija, Semarija, Sefatija Harufjan;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 6, 'Elkana, Išija, Azarel, Joezer in Jasobeam, Korahovci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 7, 'in Joela in Zebadija, sinova Jerohama iz Gedorja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 8, 'Tudi izmed Gadovcev so se ločili nekateri, da bi bili z Davidom na trdnjavi v puščavi, hrabri junaki, izurjeni za vojsko, ki so bili spretni s ščitom in sulico, katerih obličja so bila kakor levja in ki so bili hitri kakor srne v gorah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 9, 'Ezer, prvi, Obadija, drugi, Eliab, tretji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 10, 'Mismana, četrti, Jeremija, peti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 11, 'Ataj, šesti, Eliel, sedmi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 12, 'Johanan, osmi, Elzabad, deveti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 13, 'Jeremija, deseti, Makbanaj, enajsti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 14, 'Ti, izmed sinov Gadovih, so bili poveljniki vojski; najmanjšega je bilo šteti za sto, največjega pa za tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 15, 'Ti so, ki so šli čez Jordan v prvem mesecu, kadar navadno stopa čez vse svoje bregove, in zapodili so v beg vse prebivalce po dolinah, proti jutru in proti zahodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 16, 'In prišli so nekateri iz sinov Benjaminovih in Judovih v trdnjavo k Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 17, 'In David jim gre ven naproti in izpregovori ter jim reče: Ako ste prišli v miru k meni, da mi pomagate, se sklene srce moje z vami; ako ste pa prišli izdajat me mojim nasprotnikom, ko vendar ni krivice v rokah mojih, poglej to očetov naših Bog in kaznuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 18, 'Tedaj pride duh nad Amasaja, ki je bil poglavar med trideseterimi, in reče: Tvoji smo, David, in na tvoji strani, sin Jesejev! Mir, mir bodi tebi in mir tvojim pomočnikom, kajti Bog tvoj ti pomaga! Nato jih David sprejme in jih postavi za poglavarje trumi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 19, 'Od Manaseja so tudi nekateri uskočili k Davidu, ko je prišel s Filistejci bojevat se zoper Savla, a ni jim smel pomagati, zakaj knezi Filistejcev so ga odslovili, ko so se bili posvetovali, rekoč: Za glavo bi nam šlo, ko bi uskočil h gospodu svojemu Savlu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 20, 'Ko je nato šel v Ziklag, so uskočili k njemu od Manaseja: Adnah, Jozabad, Jediael, Mihael, Jozabad, Elihu in Ziletaj, poveljniki tisočim Manasejevim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 21, 'In pomagali so Davidu zoper roparske čete, zakaj vsi so bili hrabri junaki; in postali so vojni poveljniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 22, 'Dan za dnevom so namreč prihajali nekateri k Davidu mu pomagat, da je bila velika vojska, kakor vojska Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 23, 'In to so števila glav tistih, ki so bili oboroženi za vojsko in so prišli k Davidu v Hebron, da mu naklonijo kraljestvo Savlovo po povelju Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 24, 'Sinov Judovih, ki so nosili ščit in sulico, jo bilo šest tisoč osemsto, oboroženih za vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 25, 'Od sinov Simeonovih: vrlih junakov za vojsko sedem tisoč in sto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 26, 'Od sinov Levijevih: štiri tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 27, 'In Jojada je bil vojvoda med Aronovimi in ž njim jih je bilo tri tisoč in sedemsto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 28, 'in Zadok mladenič, hrabri junak, in iz družine očeta njegovega dvajsetindva poveljnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 29, 'In od sinov Benjaminovih, bratov Savlovih: tri tisoč; kajti do takrat se je večina zvesto držala hiše Savlove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 30, 'In od sinov Efraimovih: dvajset tisoč in osemsto hrabrih junakov in slovečih mož v hišah očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 31, 'In od polovice rodu Manasejevega: osemnajst tisoč, ki so bili določeni po imenih, naj gredo in postavijo Davida za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 32, 'In od sinov Isaharjevih: možje, ki so imeli razsodnost glede časov, da bi vedeli, kaj ima Izrael storiti, njih poglavarjev je bilo dvesto, in vsi njih bratje so bili pod njih poveljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 33, 'Od Zebulona tistih, ki so hodili na vojsko in se postavljali v bojne vrste z raznovrstnim vojnim orožjem, je bilo petdeset tisoč, pripravljenih, uvrstiti se v boj z nerazdeljenim srcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 34, 'In od Neftalija tisoč poveljnikov, in ž njimi nosečih ščit in sulico sedemintrideset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 35, 'In od Danovcev, zmožnih, postaviti se v bojne vrste: osemindvajset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 36, 'In od Aserja štirideset tisoč, zmožnih iti na vojsko, da se postavijo v bojne vrste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 37, 'In z druge strani Jordana, od Rubenovcev in Gadovcev in od polovice rodu Manasejevega, z raznovrstnim bojnim orožjem: stoindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 38, 'Vsi ti vojščaki, zmožni, postaviti se v bojne vrste, so prišli z nerazdeljenim srcem v Hebron, da postavijo Davida za kralja vsemu Izraelu. Pa tudi vsi drugi v Izraelu so bili enega srca, da postavijo Davida za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 39, 'In bili so tam pri Davidu tri dni, in jedli so in pili, kajti njih bratje so jim bili pripravili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 12, 40, 'Tudi so prinesli tisti, ki so bivali bliže, celó od Isaharja, Zebulona in Neftalija, na oslih in na velblodih in na mezgih in na volih kruha in močnatih jedi, gruče smokev, suhega grozdja, vina in olja, govedi in drobnice obilo; kajti radost je bila v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 1, 'In David se je posvetoval s poveljniki čez tisoč in čez sto, z vsemi vojvodami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 2, 'In David reče vsemu zboru Izraelovemu: Ako se vam zdi prav in ako je ta stvar od Gospoda, našega Boga, pošljimo povsod k ostalim bratom našim po vseh pokrajinah Izraelovih in ž njimi vred k duhovnikom in levitom, ki so v mestih okrajev svojih, da naj se zbero k nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 3, 'In prinesimo skrinjo Boga svojega sem k sebi; kajti nismo vprašali po njej v dnevih Savlovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 4, 'In ves zbor je dejal, naj se to stori, zakaj stvar se je videla dobra vsemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 5, 'Zbral je torej David vse Izraelce od Sihorja, potoka egiptovskega, tja do vhoda v Hamat, da preneso skrinjo Božjo iz Kirjat-jearima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 6, 'In David in vsi Izraelci so šli gori v Baalo, v Kirjat-jearim, ki je na Judovem, da prineso odondod skrinjo Boga, Gospoda, ki stoluje nad kerubi, kjer se kliče njegovo ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 7, 'In peljali so skrinjo Božjo na novem vozu iz hiše Abinadabove. Uza in Ahio pa sta vodila voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 8, 'In David in ves Izrael so igrali pred Bogom na vso moč s petjem, na harfe in na strune in na bobne in cimbale in na trombe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 9, 'In ko so prišli h gumnu Kidonovemu, je iztegnil Uza roko, da pridrži skrinjo, kajti volom se je izpoddrsnilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 10, 'In vname se jeza Gospodova zoper Uza in ga udari, ker je iztegnil roko svojo po skrinji; in umrl je tam pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 11, 'In David je bil žalosten, ker je bil Gospod napravil pretrg z Uzom, in imenoval je ta kraj Perez Uza, do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 12, 'In David se zboji Gospoda tisti dan in reče: Kako naj pripeljem skrinjo Božjo k sebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 13, 'David torej ni odpravil skrinje k sebi v mesto Davidovo, temuč je krenil ž njo v hišo Obededoma Gatovca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 13, 14, 'In skrinja Božja je ostala z družino Obededomovo v hiši njegovi tri mesece; in Gospod je blagoslovil hišo Obededomovo in vse, kar je imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 1, 'In Hiram, kralj v Tiru, je poslal poslance k Davidu in cedrovega lesa in zidarje in tesarje, da mu zgrade hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 2, 'In David je zaznal, da ga je Gospod potrdil za kralja nad Izraelom, kajti kraljestvo njegovo je bilo visoko povišano zaradi ljudstva njegovega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 3, 'In David si je vzel še več žen v Jeruzalemu; in David je rodil še več sinov in hčer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 4, 'In ta so imena otrok, ki jih je imel v Jeruzalemu: Samua, Sobab, Natan in Salomon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 5, 'Ibhar, Elisua, Elpelet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 6, 'Noga, Nefeg, Jafija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 7, 'Elisama, Beeliada in Elifelet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 8, 'Ko so pa Filistejci slišali, da je bil David pomaziljen za kralja nad vsem Izraelom, pridejo vsi Filistejci gori iskat Davida. In ko je David zvedel za to, jim je šel naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 9, 'Filistejci so pa prišli in se razgrnili po dolini Refaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 10, 'In David je vprašal Boga, rekoč: Ali naj grem gori zoper Filistejce? In mi jih li hočeš dati v roko? In Gospod mu veli: Pojdi gori, kajti dam ti jih v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 11, 'Oni pa so prišli v Baalperazim, in David jih porazi ondi. In David reče: Gospod je raztrgal sovražnike moje po moji roki, kakor vode pretrgajo jez. Zato so dali ime tistemu kraju Baalperazim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 12, 'Popustili so pa svoje bogove tamkaj. In David ukaže, in sežgali so jih v ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 13, 'In Filistejci so zopet pridrli in se razgrnili po dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 14, 'David pa zopet vpraša Boga, in Bog mu reče: Ne hodi gori za njimi, kreni od njih in pojdi nadnje od strani murvovih dreves.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 15, 'In ko začuješ šumenje iz vrhov murvovih dreves, kakor da prihaja vojska, tedaj pojdi ven v boj: zakaj Bog gre pred teboj, da udari vojsko Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 16, 'In David je storil, kakor mu je bil zapovedal Bog, in pobijali so vojsko Filistejcev od Gibeona do Gezerja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 14, 17, 'In Davidovo ime se je razglasilo po vseh deželah, in Gospod je spravil v strah pred njim vse narode');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 1, 'In David si je sezidal hiše v mestu Davidovem; in pripravil je mesto za skrinjo Božjo in razpel šator zanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 2, 'Tedaj je rekel David: Nihče ne sme nositi skrinje Božje razen levitov, kajti nje je izvolil Gospod, da nosijo skrinjo Božjo in služijo njemu vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 3, 'In David zbere vsega Izraela v Jeruzalemu, da prineso skrinjo Gospodovo na mesto njeno, ki ga je bil pripravil zanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 4, 'David zbere tudi sinove Aronove in levite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 5, 'Iz sinov Kahatovih: Uriela, poglavarja, in njegovih bratov sto in dvajset;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 6, 'iz sinov Merarijevih: Asaja, poglavarja, in njegovih bratov dvesto in dvajset;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 7, 'iz sinov Gersomovih: Joela, poglavarja, in njegovih bratov sto in trideset;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 8, 'iz sinov Elizafanovih: Semaja, poglavarja, in njegovih bratov dvesto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 9, 'iz sinov Hebronovih: Eliela, poglavarja, in njegovih bratov osemdeset;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 10, 'iz sinov Uzielovih: Aminadaba, poglavarja, in bratov njegovih sto in dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 11, 'In David pokliče Zadoka in Abiatarja, duhovnika, in levite, namreč Uriela, Asaja, Joela, Semaja, Eliela in Aminadaba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 12, 'in jim veli: Vi ste poglavarji očetovinam levitov: posvetíte se vi in bratje vaši, da prinesete gori skrinjo Gospoda, Boga Izraelovega, na mesto, ki sem ga pripravil zanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 13, 'Zakaj ker je niste nosili onikrat, je storil Gospod, naš Bog, pretrg med nami, ker ga nismo iskali, kakor je prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 14, 'Posvetili so se torej duhovniki in leviti, da prineso gori skrinjo Gospoda, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 15, 'In sinovi Levijevi so nesli skrinjo Božjo na ramah, zadevši nase droga njena, kakor je bil zapovedal Mojzes po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 16, 'In David je velel poglavarjem levitov, naj postavijo svoje brate, pevce, z glasbenim orodjem, s psalmovimi citrami, s harfami in cimbali, da glasno pojo, povzdigujoč glas z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 17, 'Nastavili so torej leviti Hemana, sina Joelovega, in od bratov njegovih Asafa, sina Berekijevega, in od sinov Merarijevih brate svoje: Etana, sina Kusajevega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 18, 'in ž njimi njih brate druge vrste: Zeharija, Bena, Jaaziela, Semiramota, Jehiela, Unija, Eliaba, Benaja, Maaseja, Matitija, Elifeleha, Mikneja, Obededoma in Jegiela, vratarje; –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 19, 'in sicer pevce, Hemana, Asafa in Etana, da glasno godejo na medene cimbale;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 20, 'Zeharija pa in Aziela, Semiramota, Jehiela, Unija, Eliaba, Maaseja in Benaja s psalmovimi citrami na visoke glasove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 21, 'Matitija pa in Elifeleha, Mikneja, Obededoma, Jegiela, Azazija, s harfami na globoke glasove, da vodijo petje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 22, 'In Kenanija je bil načelnik levitom pri petju; on je učil petje, ker je bil veščak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 23, 'In Berekija in Elkana sta bila vratarja pri skrinji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 24, 'A Sebanija, Josafat, Netanel, Amasaj, Zeharija, Benaja in Eliezer, duhovniki, so trobili na trombe pred skrinjo Božjo. In Obededom in Jehia sta bila vratarja pri skrinji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 25, 'David in starejšine Izraelovi in poveljniki tisočim so torej šli, da prineso gori skrinjo zaveze Gospodove iz hiše Obededomove z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 26, 'In ker je Bog pomagal levitom, ki so nesli skrinjo zaveze Gospodove, so darovali sedem juncev in sedem ovnov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 27, 'David pa je bil oblečen v vrhnjo suknjo iz tenčice in tudi vsi leviti, ki so nesli skrinjo, in pevci in Kenanija, pevovodja, pri pevcih; in David je imel na sebi platnen naramnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 28, 'Tako je ves Izrael prenesel gori skrinjo Gospodove zaveze z veselim ukanjem in z glasom roga in s trobentami in cimbali, z glasnim petjem pri psalmovih citrah in harfah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 15, 29, 'In ko je prišla skrinja zaveze Gospodove v mesto Davidovo, je gledala Mihala, hči Savlova, skozi okno, in videč kralja Davida, da poskakuje in igra, ga je zaničevala v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 1, 'In prinesli so skrinjo Božjo noter ter jo postavili sredi šatora, ki ga je bil David razpel zanjo; in darovali so žgalne in mirovne daritve pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 2, 'In ko je David končal darovanje žgalščin in mirovnih žrtev, je blagoslovil ljudstvo v imenu Gospodovem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 3, 'in je razdelil za vsakega izmed Izraela, moža in ženo, da je vsakdo dobil hleb kruha in kos mesa in suhega grozdja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 4, 'In postavil je nekatere iz levitov za strežnike pred skrinjo Gospodovo, da naj s hvalo spominjajo in zahvaljujejo in slavijo Gospoda, Boga Izraelovega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 5, 'Asafa, načelnika, in Zeharija, drugega po njem, Jegiela, Semiramota, Jehiela, Matitija, Eliaba, Benaja, Obededoma in Jegiela, s psalmovimi citrami in s harfami, in Asafa s cimbali, da glasno gode,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 6, 'in Benaja in Jahaziela, duhovnika, s trobentami, da stojita vedno pred skrinjo zaveze Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 7, 'Tedaj je, tisti dan, David v prvič ukazal Asafu in bratom njegovim, naj hvalijo Gospoda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 8, 'Hvalite Gospoda, kličite ime njegovo, oznanjujte med ljudstvi dejanja njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 9, 'Pojte mu, psalme mu prepevajte, govorite o vseh čudovitih delih njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 10, 'Hvalite se v svetem imenu njegovem; veseli se naj srce njih, ki iščejo Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 11, 'Iščite Gospoda in moči njegove, iščite vedno obličje njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 12, 'Spominjajte se čudes njegovih, ki jih je storil, čudovitih znamenj in razsodkov ust njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 13, 'o seme Izraela, njegovega hlapca, otroci Jakobovi, izvoljenci njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 14, 'On, Gospod, je Bog naš, po vsej zemlji se vrše sodbe njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 15, 'Spominjajte se vekomaj zaveze njegove, besede, katero je zapovedal tisoč rodovom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 16, 'zaveze, ki jo je sklenil z Abrahamom, in njegove prisege Izaku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 17, 'ki jo je potrdil Jakobu za postavo, Izraelu za večno zavezo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 18, 'gororeč: Tebi hočem dati deželo Kanaansko kot vam odmerjeno dedno posest!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 19, 'ko vas je bilo po številu še malo, prav malo, in ste kot tujci bivali v njej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 20, 'in so hodili od naroda do naroda in iz enega kraljestva k drugemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 21, 'Ni jih dovolil zatirati nikomur, še kralje je strahoval zaradi njih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 22, '„Ne doteknite se maziljencev mojih in ne storite žalega prorokom mojim!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 23, 'Pojte Gospodu, vsa zemlja, veselo oznanjajte od dne do dne zveličanje njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 24, 'Pripovedujte med poganskimi narodi veličastvo njegovo, med vsemi ljudstvi čudovita dela njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 25, 'Kajti velik je Gospod in velike hvale vreden, strašen je on nad vse bogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 26, 'Zakaj vsi bogovi ljudstev so ničevi maliki, Gospod pa je naredil nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 27, 'Slava in lepota sta pred njim, moč in radost v mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 28, 'Dajajte Gospodu, ljudstev rodovine, dajajte Gospodu čast in moč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 29, 'Dajajte Gospodu slavo imena njegovega, prinesite dar in pridite pred obličje njegovo; klanjajte se Gospodu v diki svetosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 30, 'Trepetajte pred njim, vsa zemlja! Zemlje obod je tudi utrjen, da ne omahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 31, 'Veselé se naj nebesa in raduj se zemlja, in govore naj med narodi: Gospod kraljuje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 32, 'Grmi naj morje in kar je v njem, raduj se polje in vse, kar je na njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 33, 'Tedaj bo veselo pevalo vse drevje v gozdu pred obličjem Gospodovim, kajti prihaja sodit zemljo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 34, 'Hvalite Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 35, 'In recite: Reši nas, o Bog zveličanja našega, in zberi nas in otmi poganov, da hvalimo sveto ime tvoje in se veličamo v hvali tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 36, 'Slava Gospodu, Bogu Izraelovemu, od vekomaj do vekomaj! In vse ljudstvo je dejalo: Amen! in je hvalilo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 37, 'Postavil je torej tam pred skrinjo zaveze Gospodove Asafa in brate njegove, da strežejo vedno pred skrinjo, kolikor je bilo treba vsak dan;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 38, 'in Obededoma ž njegovimi brati, oseminšestdeset, tudi Obededoma, sina Jedutunovega, in Hosa, da sta vratarja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 39, 'Zadoka pa, duhovnika, in brate njegove, duhovnike, pred prebivališčem Gospodovim na višavi, ki je bila v Gibeonu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 40, 'da darujejo žgalne žrtve Gospodu na žgalnem oltarju vsekdar zjutraj in zvečer, po vsem, kar je pisano v zakonu Gospodovem, ki ga je zapovedal Izraelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 41, 'in ž njimi Hemana in Jedutuna in druge, kar jih je bilo izbranih, ki so bili zaznamenovani po imenih, da bi hvalili Gospoda, ker vekomaj traja milost njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 42, 'in ž njimi Hemana in Jedutuna s trompetami in cimbali za tiste, ki jim je bilo glasno igrati, in z glasbenim orodjem v hvalo Božjo; in sinom Jedutunovim je bilo stati pri vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 16, 43, 'In vse ljudstvo se je razšlo, vsak v hišo svojo; in David se je vrnil, da blagoslovi hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 1, 'In zgodi se, ko je David prebival v hiši svoji, da reče Natanu proroku: Glej, jaz stanujem v cedrovi hiši, a skrinja zaveze Gospodove prebiva pod preprogami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 2, 'In Natan reče Davidu: Stori vse, kar ti je v srcu, kajti Bog je s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 3, 'Še to noč pa pride beseda Gospodova k Natanu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 4, 'Pojdi in reci hlapcu mojemu Davidu: Tako pravi Gospod: Ne boš mi ti gradil hiše, da prebivam v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 5, 'Saj nisem prebival v hiši od dne, ko sem pripeljal Izraela semkaj, do današnjega dne, ampak hodil sem iz šatora v šator, iz enega bivališča v drugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 6, 'Kamorkoli sem šel z vsem Izraelom, sem li besedo govoril s katerim sodnikov Izraelovih, ki sem jim zapovedal pasti ljudstvo moje, rekoč: Zakaj mi niste zgradili cedrove hiše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 7, 'Tako torej véli hlapcu mojemu Davidu: Tako pravi Gospod nad vojskami: Jaz sem te vzel s pašnikov, ko si hodil za ovcami, da bodeš vojvoda ljudstvu mojemu Izraelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 8, 'in sem bil s teboj, kamorkoli si šel, in sem zatrl vse sovražnike tvoje pred teboj in ti storil ime kakor ime velikašev, ki so na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 9, 'In hočem pripraviti kraj ljudstvu svojemu Izraelu in jih zasaditi, da bodo prebivali na svojem in se več ne premikali; tudi jih ne bodo več gonobili sinovi krivice kakor poprej');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 10, 'in odkar sem zapovedal sodnikom, da bodo nad ljudstvom mojim Izraelom; in ponižam vse sovražnike tvoje. Vrhutega ti pravim, da Gospod zgradi hišo tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 11, 'Ko se ti dopolnijo dnevi, da pojdeš k očetom svojim, hočem postaviti seme tvoje za teboj, ki bode izmed sinov tvojih, in hočem utrditi kraljestvo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 12, 'On mi bo zgradil hišo, in jaz utrdim prestol njegov na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 13, 'Jaz mu bodem za očeta, in on mi bode za sina; in mu ne odtegnem milosti svoje, kakor sem jo odtegnil njemu, ki je bil pred teboj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 14, 'temuč ustanovitim ga v hiši svoji in v kraljestvu svojem za vekomaj, in prestol njegov bo utrjen vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 15, 'Po vseh teh besedah in po vsej tej prikazni je točno govoril Natan Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 16, 'Tedaj stopi David noter in sede pred Gospoda in reče: Kdo sem jaz, o Gospod Bog, in kaj je hiša moja, da si me privedel tako daleč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 17, 'In to se je še premalo videlo tvojim očem, o Bog, in govoril si o hlapca svojega hiši za daljno prihodnost, in pogledal si me po načinu vzvišenega človeka, Gospod Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 18, 'Kaj more David še govoriti tebi zastran časti, izkazane hlapcu tvojemu? Saj ti poznaš hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 19, 'O Gospod, zaradi hlapca svojega in po srcu svojem si storil vso to velikost, da oznaniš vse te velike reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 20, 'O Gospod, ni ga tebi enakega, tudi ni Boga razen tebe, po vsem, kar smo slišali na ušesa svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 21, 'In kje je edino ljudstvo na zemlji kakor ljudstvo tvoje Izrael, ki ga je šel Bog odkupit sebi za ljudstvo, da si napraviš ime z velikimi in strahovitimi rečmi, ko si pregnal narode izpred ljudstva svojega, ki si ga odkupil iz Egipta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 22, 'Kajti storil si ljudstvo svoje, Izraela, sebi za ljudstvo na vekomaj, in ti si, Gospod, postal njih Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 23, 'In sedaj, o Gospod: beseda, ki si jo govoril o hlapcu svojem in o hiši njegovi, ostani veljavna na vekomaj, in stóri, kakor si govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 24, 'Da, veljavna ostani in ime tvoje bodi poveličevano vekomaj, ko bodo govorili: Gospod nad vojskami, Bog Izraelov, je Bog za Izraela! In hiša tvojega hlapca Davida bodi utrjena pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 25, 'Zakaj ti, moj Bog, si razodel hlapcu svojemu, da mu zgradiš hišo; zato se je osrčil hlapec tvoj moliti pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 26, 'In sedaj, o Gospod, ti si Bog, in ti si govoril hlapcu svojemu to predobro obljubo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 17, 27, 'In sedaj rači blagosloviti hlapca svojega hišo, da ostane pred teboj vekomaj; ker ti si jo, o Gospod, blagoslovil, zato bo blagoslovljena vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 1, 'In zgodi se potem, da je porazil David Filistejce in jih pripravil ob moč ter vzel Gat in ž njim združena mesta iz rok Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 2, 'Porazil je tudi Moaba; in Moabci so postali podložni Davidu in so prinašali darove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 3, 'David je tudi porazil Hadarezerja, kralja v Zobi pri Hamatu, ko je šel, da si utrdi oblast pri reki Evfratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 4, 'In David mu je vzel tisoč voz in sedem tisoč konjikov in dvajset tisoč pešcev; in David je ohromel vse vozne konje, ohranil jih je samo pri sto vozeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 5, 'Ko pa so prišli Sirci iz Damaska pomagat Hadarezerju, kralju v Zobi, je David pobil izmed Sircev dvaindvajset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 6, 'Tedaj je David postavil posadko v Sirijo ob Damasku; in Sirci so postali podložni Davidu in so prinašali darove. Kajti Gospod je pomagal Davidu, kamorkoli je šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 7, 'In David je vzel ščite iz zlata, ki so jih imeli hlapci Hadarezerjevi, in jih je prinesel v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 8, 'Tudi iz Tibhata in iz Kuna, mest Hadarezerjevih, je David vzel veliko brona, in iz njega je napravil Salomon bronasto morje in stebra in bronaste posode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 9, 'Ko pa začuje Tov, kralj v Hamatu, da je David porazil vso vojsko Hadarezerja, kralja v Zobi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 10, 'pošlje Hadorama, sina svojega, h kralju Davidu, da ga pozdravi in mu čestita na tem, da se je bojeval zoper Hadarezerja in ga porazil (kajti Hadarezer se je vedno bojeval zoper Tova); in prinese s seboj vsakovrstne posode zlate in srebrne in bronaste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 11, 'Te je tudi kralj David posvetil Gospodu s srebrom in zlatom vred, kar ga je prinesel od vseh narodov: od Edomcev in Moabcev in od sinov Amonovih, od Filistejcev in od Amalekovcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 12, 'In Abisaj, sin Zervijin, je porazil iz Edomcev v Solni dolini osemnajst tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 13, 'In postavil je posadke po Edomskem, in vsi Edomci so postali podložni Davidu. Kajti Gospod je pomagal Davidu, kamorkoli je šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 14, 'In David je kraljeval vsemu Izraelu in izvrševal je sodbo in pravičnost vsemu ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 15, 'Joab pa, sin Zervijin, je bil nad vojsko, in Josafat, sin Ahiludov, je bil deželni letopisec;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 16, 'in Zadok, sin Ahitubov, in Abimelek, sin Abiatarjev, sta bila duhovnika, in Savsa je bil pisar,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 18, 17, 'in Benaja, sin Jojadov, je bil nad Keretejci in Peletejci, in sinovi Davidovi so bili prvi pri kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 1, 'In zgodi se potem, da je umrl Nahas, kralj sinov Amonovih, in sin njegov je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 2, 'In David reče: Milost izkažem Hanunu, sinu Nahasovemu, kajti oče njegov mi je izkazal milost. Pošlje torej David sporočnike, da ga potolaži za očetom njegovim. In Davidovi hlapci pridejo v deželo sinov Amonovih k Hanunu, tolažit ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 3, 'Ali knezi sinov Amonovih reko Hanunu: Meniš li, da David spoštuje očeta tvojega, ker je poslal tolažnike k tebi? Niso li prišli hlapci njegovi k tebi, da preiščejo deželo in jo ugonobe, ko jo ogledajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 4, 'Hanun vzame torej hlapce Davidove in jih obrije in jim odreže polovico oblačil do ledja, in jih pošlje nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 5, 'In nekateri so šli in povedali Davidu o tistih možeh. In pošlje jim naproti; kajti tisti možje so bili silno osramočeni. In kralj sporoči: Ostanite v Jerihu, dokler vam ne porasto brade, potem se vrnite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 6, 'In ko so videli sinovi Amonovi, da so se naredili mrzke Davidu, pošljejo Hanun in sinovi Amonovi tisoč talentov srebra, da si najmejo voz in konjikov iz Mezopotamije in iz Aram-Maake in iz Zobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 7, 'Najeli so torej dvaintrideset tisoč voz in kralja iz Maake z moštvom njegovim; ti pridejo in se utabore pred Medebo. In sinovi Amonovi se zbero iz svojih mest in pridejo na boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 8, 'Ko pa to izve David, pošlje Joaba in vso vojsko, hrabre može.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 9, 'In sinovi Amonovi izidejo in se pripravijo za boj ob mestnih vratih; kralji pa, ki so prišli od drugod; so bili posebe na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 10, 'Ko torej Joab vidi, da je spredaj in zadaj naskok naperjen proti njemu, izbere iz vseh najboljših mož Izraelovih in jih postavi v boj zoper Sirce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 11, 'Ostalo ljudstvo pa da pod roko bratu svojemu Abisaju, in pripravijo se na boj zoper sinove Amonove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 12, 'In veli: Ako mi bodo Sirci premočni, bodi mi v pomoč; ako pa bodo sinovi Amonovi tebi premočni, pomorem ti jaz!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 13, 'Bodi srčen in junaški se bojujva za naše ljudstvo in za mesta Boga našega, in Gospod naj stori, kar se mu vidi dobro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 14, 'Joab torej in ljudstvo, ki je bilo pri njem, se približa Sircem na boj, in zbeže pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 15, 'Ko pa vidijo sinovi Amonovi, da beže Sirci, pobegnejo tudi oni pred Abisajem, bratom njegovim, in priteko v mesto. Tedaj pride Joab v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 16, 'In ko vidijo Sirci, da so morali pobegniti pred Izraelom, pošljejo poslance in izvabijo Sirce, ki so bili onkraj reke, in Sofaha, poveljnika vojske Hadarezerjeve, ki jim je bil na čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 17, 'In to se sporoči Davidu; in zbere vsega Izraela in preide čez Jordan in pride nadnje ter se pripravi na boj ž njimi. In ko se je David postavil zoper Sirce, so se bojevali ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 18, 'A Sirci zbeže pred Izraelom; in David je pobil izmed Sircev sedemtisoč bojevnikov na vozeh in štirideset tisoč pešcev; usmrtil je tudi Sofaha, poveljnika vojske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 19, 19, 'In ko so videli hlapci Hadarezerjevi, da so bili poraženi pred Izraelom, so sklenili mir z Davidom in so mu bili podložni. In niso hoteli Sirci več pomagati sinovom Amonovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 1, 'In ko je preteklo leto, ob času, ko hodijo kralji na boj, je peljal Joab ven vojne trume in opustošil deželo sinov Amonovih, in pride in oblega Rabo. David pa je ostal v Jeruzalemu. In Joab je udaril Rabo in jo razdejal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 2, 'In David vzame krono njih kralja z glave njegove, težko talent zlata in obloženo z dragimi kameni; in posadili so jo Davidu na glavo. Tudi plena iz mesta je odpeljal silno veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 3, 'In izpeljal je ljudstvo, ki je bilo v njem, in jih je postavil pri žagah in pri železnih mlatilnicah in pri sekirah. Tako je storil David vsem mestom sinov Amonovih. In David in vse ljudstvo se vrne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 4, 'Potem se vname vojska v Gezerju s Filistejci. Takrat je udaril Sibekaj Husajec Sipaja, iz sinov velikanovih; in bili so ponižani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 5, 'In zopet je bila vojna s Filistejci; in Elhanan, sin Jairov, je udaril Lahmija, brata Goliata Gatovca, ki je imel suličišče pri svoji sulici kakor tkalsko vratilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 6, 'In zopet je bila bitka v Gatu, kjer je bil mož visoke postave, ki je imel po šest prstov na rokah in na nogah, skupaj štiriindvajset; tudi ta se je bil rodil velikanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 7, 'Ko je ta sramotil Izraela, ga je ubil Jonatan, sin Simea, brata Davidovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 20, 8, 'Ti so se bili rodili velikanu v Gatu, in padli so po roki Davidovi in po roki služabnikov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 1, 'In Satan se je vzdignil zoper Izraela in izpodbodel Davida, da naj sešteje Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 2, 'In David veli Joabu in poglavarjem ljudstva: Pojdite, seštejte Izraelce od Bersebe do Dana, in prinesite mi poročilo, da vem njih število!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 3, 'In Joab reče: Gospod pridaj k ljudstvu svojemu stokrat toliko, kolikor jih je! Ali, gospod moj, kralj, niso li vsi gospoda mojega hlapci? Čemu zahteva to gospod moj? Zakaj se naj to šteje v pregreho Izraelu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 4, 'Vendar pa je obveljala beseda kraljeva zoper Joaba. Zatorej odide Joab in prehodi vse Izraelovo in se vrne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 5, 'In dal je Joab število preštetega ljudstva Davidu; in bilo je vsega Izraela tisočkrat tisoč in sto tisoč mož, ki so izdirali meč; iz Jude pa štiristo in sedemdeset tisoč mož, ki so izdirali meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 6, 'A Levija in Benjamina ni štel ž njimi vred, kajti beseda kraljeva se je mrzila Joabu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 7, 'To povelje pa se je hudo videlo v očeh Božjih, in udaril je Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 8, 'In David reče Bogu: Hudo sem grešil, da sem storil to; a sedaj, prosim, odpravi krivico hlapca svojega, kajti ravnal sem zelo nespametno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 9, 'In Gospod je govoril Gadu, Davidovemu vidcu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 10, 'Pojdi in govóri Davidu in reci: Tako pravi Gospod: Troje ti ponujam, izberi si eno, da naj ti storim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 11, 'Pride torej Gad k Davidu in mu reče: Tako pravi Gospod: Izberi si:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 12, 'bodisi tri leta lakote, ali da tri mesece bežiš pred nasprotniki svojimi, ko te dohiteva meč sovražnikov tvojih, ali pa tri dni meč Gospodov in kugo v deželi in angela Gospodovega, ki bo pogubljal po vseh mejah Izraelovih. Sedaj pa premisli, kakšen odgovor naj dam njemu, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 13, 'In David reče Gadu: V stiski sem veliki! Rajši padem, prosim, v roko Gospodovo, kajti veliko je usmiljenje njegovo; le nikar naj ne padem v roko človeško!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 14, 'Poslal je torej Gospod kugo nad Izraela, in pomrlo je iz Izraela sedemdeset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 15, 'In Bog pošlje angela proti Jeruzalemu, da ga pogubi; in ko je pogubljal, je pogledal Gospod in žal mu je bilo hudega; in veli angelu, ki je pokončeval: Dosti je, odtegni zdaj roko svojo! In angel Gospodov je stal pri gumnu Ornana Jebusejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 16, 'David pa povzdigne oči in vidi angela Gospodovega stoječega med zemljo in nebom in v roki njegovi potegnjen meč, naperjen proti Jeruzalemu. Tedaj padejo David in starejšine, oblečeni v raševino, na obraze svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 17, 'In David reče Bogu: Nisem li jaz velel, naj se sešteje ljudstvo? Jaz sem tisti, ki sem grešil in zelo krivično ravnal, te ovce pa, kaj so storili? Roka tvoja, prosim, o Gospod, Bog moj, bodi zoper mene in zoper očeta mojega hišo, nikar zoper tvoje ljudstvo, da ga tepe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 18, 'Tedaj zapove angel Gospodov Gadu, da veli Davidu, naj gre gori in zgradi oltar Gospodu na gumnu Ornana Jebusejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 19, 'In David je šel gori po besedi Gadovi, ki jo je govoril v imenu Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 20, 'Ornan pa se ozre in zagleda angela, in štirje sinovi njegovi, ki so bili pri njem, se skrijejo; Ornan je namreč mlatil pšenico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 21, 'In ko David pride do Ornana, se ta ozre in zagleda Davida in gre z gumna ter se Davidu prikloni z obrazom do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 22, 'Tedaj reče David Ornanu: Prepústi mi kraj tega gumna, da na njem zgradim oltar Gospodu, prepústi mi ga za polno ceno, da bi nehala kuga med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 23, 'Ornan pa reče Davidu: Vzemi si ga, in stori naj ž njim gospod moj, kralj, kar se mu dobro vidi; glej, dam ti voli v žgalno daritev in mlatilnice za drva in pšenico v jedilno daritev: vse dam rad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 24, 'A kralj David reče Ornanu: Nikar, ampak res hočem to kupiti od tebe za polno ceno, ker ne vzamem, kar je tvojega, za Gospoda, in ne bom daroval žgalne daritve brez stroškov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 25, 'Dal je torej David Ornanu za tisti kraj šeststo zlatih seklov po teži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 26, 'In David je zgradil ondi oltar Gospodu in je daroval žgalne in mirovne daritve in klical Gospoda; on pa mu je odgovoril iz nebes po ognju na oltarju žgalnih daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 27, 'In Gospod ukaže angelu, in angel vtakne meč zopet v nožnico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 28, 'V tistem času, ko je David videl, da mu je Gospod odgovoril na gumnu Ornana Jebusejca, je daroval ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 29, 'Kajti šator Gospodov, ki ga je naredil Mojzes v puščavi, in oltar žgalnih daritev, sta bila tisti čas na višavi v Gibeonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 21, 30, 'A David ni mogel predenj tja hoditi, da bi iskal Boga, tako je bil prestrašen zaradi meča angela Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 1, 'In David reče: Tu bodi hiša Gospoda, Boga, in tu bodi oltar za žgalne daritve Izraelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 2, 'In David ukaže, naj zbero tujce, ki so bili v deželi Izraelovi; in nastavi kamenarje, da sekajo kamene na štiri ogle za zgradbo hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 3, 'In David je pripravil obilico železa za žeblje k durnicam pri vratih in za spojke, brona tudi toliko, da ga ni bilo moči stehtati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 4, 'tudi cedrovega lesa brez števila; kajti Sidonci in Tirci so pripeljali mnogo cedrovine Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 5, 'In David je rekel: Salomon, sin moj, je mlad in šibek, hiša pa, ki se ima zidati za Gospoda, mora biti silno velika, da gre njen glas in njena slava po vseh deželah: pripravim torej zanjo. Oskrbel je torej David mnogo gradiva pred smrtjo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 6, 'In pokliče sina svojega Salomona in mu zapove zgraditi hišo Gospodu, Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 7, 'In veli David Salomonu: Sin moj, jaz sem se namenil v srcu svojem, da zgradim hišo imenu Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 8, 'Ali beseda Gospodova je prišla k meni, govoreč: Prelil si mnogo krvi in imel velike boje; ti ne boš zidal hiše imenu mojemu, ker si prelil mnogo krvi na zemljo vpričo mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 9, 'Glej, sin se ti bo rodil, ki bode mož pokoja, in pripravim mu pokoj pred vsemi sovražniki njegovimi okoli; kajti Salomon mu bode ime, ker mir in pokoj dam Izraelu v dnevih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 10, 'On zgradi hišo imenu mojemu; in on mi bode sin, in jaz mu bodem oče, in kraljestva njegovega prestol utrdim nad Izraelom za vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 11, 'Sedaj pa bodi Gospod s teboj, sin moj, da ti gre po sreči in postaviš hišo Gospodu, Bogu svojemu, kakor je govoril zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 12, 'Gospod ti samo daj razum in previdnost in ti poveri vlado nad Izraelom, da bi izpolnjeval zakon Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 13, 'Tedaj boš imel srečo, ako boš pazil, da izpolnjuješ postave in sodbe, ki jih je Gospod ukazal Mojzesu za Izraela. Bodi močan in srčen, ne boj se in ne plaši se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 14, 'In glej, v trudovitem življenju svojem sem pripravil za hišo Gospodovo sto tisoč talentov zlata in tisočkrat tisoč talentov srebra, brona in železa pa, da ga ni moči stehtati, kajti preobilo ga je; lesa in kamenja sem tudi pripravil, ti pa lahko še prideneš k temu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 15, 'Vrhutega imaš pri sebi dosti delavcev, kamenosekov, klesarjev in obdelovalcev lesa in vsakršnih veščakov za vsakovrstna dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 16, 'Zlatu, srebru, bronu, železu ni števila. Vstani in delaj, in Gospod bodi s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 17, 'David je tudi zapovedal vsem knezom Izraelovim, naj pomagajo Salomonu, sinu njegovemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 18, 'Ni li z vami Gospod, Bog vaš? in ni li vam oskrbel pokoja na vseh straneh? Kajti prebivalce te dežele je dal v mojo roko, in dežela je podvržena Gospodu in ljudstvu njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 22, 19, 'Dajte torej srca svoja in duše svoje, da iščete Gospoda, Boga svojega! In vstanite in zidajte svetišče Gospoda Boga, da prineso skrinjo zaveze Gospodove in svete posode Božje v hišo, ki se ima zgraditi imenu Gospodovemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 1, 'David je torej, ko je bil star in dni svojih sit, postavil Salomona, sina svojega, za kralja nad Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 2, 'In zbral je vse kneze Izraelove in duhovnike in levite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 3, 'Leviti pa so bili prešteti, od tridesetletnih in više, in njih število, od glave do glave, je bilo osemintrideset tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 4, 'Iz teh je bilo štiriindvajset tisoč, ki naj bi nadzorovali delo pri hiši Gospodovi, in šest tisoč je bilo oblastnikov in sodnikov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 5, 'in štiri tisoč vratarjev in štiri tisoč, ki naj hvalijo Gospoda z godali, ki sem jih napravil, je rekel David, da se ž njimi poje hvala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 6, 'In David jih je razdelil v oddelke po sinovih Levijevih, po Gersonu, Kahatu in Merariju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 7, 'Gersonovci: Ladan in Simej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 8, 'Sinovi Ladanovi: Jehiel poglavar, Zetam in Joel, trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 9, 'Sinovi Simejevi: Selomit, Haziel in Haran, trije. Ti so bili glave očetovinam Ladanovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 10, 'Sinovi Simejevi pa: Jahat, Ziza, Jeuš in Berija. Ti štirje so bili sinovi Simejevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 11, 'In Jahat je bil prvak in Ziza je bil drugi; a Jeuš in Berija nista imela mnogo sinov, zato so jih šteli za eno očetovsko hišo. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 12, 'Sinovi Kahatovi: Amram, Izhar, Hebron in Uziel, štirje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 13, 'Sinova Amramova: Aron in Mojzes. Aron pa je bil izločen, da bodi posvečen za najsvetejše, on in sinovi njegovi vekomaj, da naj palijo kadilo pred Gospodom, mu služijo in blagoslavljajo v njegovem imenu na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 14, 'Kar se tiče Mojzesa, moža Božjega – sinovi njegovi so bili imenovani med rodom Levijevim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 15, 'Sinova Mojzesova: Gersom in Eliezer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 16, 'Sin Gersomov: Sebuel, poglavar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 17, 'In sin Eliezerjev: Rehabija, poglavar. In Eliezer ni imel več sinov, ali sinov Rehabijevih je bilo mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 18, 'Sin Izharjev: Selomit, poglavar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 19, 'Sinovi Hebronovi: Jerija poglavar, Amarija, drugi, Jahaziel, tretji, in Jekameam, četrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 20, 'Sinova Uzielova: Miha, poglavar, in Išija, drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 21, 'Sinova Merarijeva: Mahli in Musi. Sinova Mahlijeva: Eleazar in Kis.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 22, 'In Eleazar je umrl, imel ni sinov, samo hčere; in njih bratranci, sinovi Kisovi, so jih vzeli za žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 23, 'Sinovi Musijevi: Mahli, Eder in Jeremot, trije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 24, 'Ti so bili sinovi Levijevi po svojih očetovskih hišah, glave očetovinam, kakor so bili sešteti po imenih, od glave do glave, od dvajsetega leta in više, ki so opravljali delo službe pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 25, 'Kajti David je rekel: Gospod, Bog Izraelov, je pripravil pokoj ljudstvu svojemu, in on prebiva v Jeruzalemu na vekomaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 26, 'zato tudi ni treba levitom nositi več šatora in vseh njegovih priprav za službo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 27, 'Kajti po zadnjih besedah Davidovih so bili sinovi Levijevi prešteti od dvajsetletnih in više.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 28, 'Zakaj njih stojišče je bilo ob strani sinovom Aronovim pri službi doma Gospodovega, da nadzirajo dvorišča in hrame in očiščevanje vseh svetih reči in opravljajo službo hiše Božje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 29, 'in naj skrbe za razporedbo kruhov in za belo moko k jedilni daritvi, bodisi od nekvašenih mlincev ali pa kar se peče v ponvi ali kar se praži, in za vsakršno težo in mero,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 30, 'ter naj stojé vsako jutro, da hvalijo in slave Gospoda, takisto zvečer,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 31, 'in darujejo vse žgalne daritve Gospodu ob sobotah, ob mlajih in ob določenih praznikih po predpisanem številu neprenehoma pred Gospodom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 23, 32, 'in naj strežejo v straži pri shodnem šatoru in v straži svetišča in v straži pri sinovih Aronovih, bratih svojih, v službi hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 1, 'Ti pa so oddelki sinov Aronovih: Sinovi Aronovi so bili: Nadab in Abihu, Eleazar in Itamar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 2, 'Nadab in Abihu pa sta umrla pred obličjem očeta svojega in nista imela otrok; zato sta bila Eleazar in Itamar duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 3, 'In razdelili so jih David in Zadok, iz sinov Eleazarjevih, in Ahimeleh, iz sinov Itamarjevih, po vrstah njih službe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 4, 'In med sinovi Eleazarjevimi se je našlo več moških glav nego med sinovi Itamarjevimi; in so jih takole razdelili: od sinov Eleazarjevih jih je bilo šestnajst poglavarjev očetovskih hiš in od sinov Itamarjevih osem poglavarjev očetovskih hiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 5, 'Tako so bili razdeljeni po žrebu, ti kakor oni, kajti bili so knezi svetišča in knezi Božji od sinov Eleazarjevih in od sinov Itamarjevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 6, 'In pisar Semaja, sin Netanelov, izmed levitov, jih je zapisal vpričo kralja in knezov in Zadoka duhovnika in Ahimeleha, sinu Abiatarjevega, in poglavarjev duhovniških in levitskih hiš: po eno očetovsko hišo se je jemalo za Eleazarja in po eno za Itamarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 7, 'Prvi žreb pa je zadel Jehojariba, drugi Jedaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 8, 'tretji Harima, četrti Seorima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 9, 'peti Malkija, šesti Mijamina,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 10, 'sedmi Hakoza, osmi Abija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 11, 'deveti Jesua, deseti Sekanija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 12, 'enajsti Eliasiba, dvanajsti Jakima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 13, 'trinajsti Hupa, štirinajsti Jesebeaba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 14, 'petnajsti Bilga, šestnajsti Imerja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 15, 'sedemnajsti Hezirja, osemnajsti Hapizeza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 16, 'devetnajsti Petahija, dvajseti Jehezkela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 17, 'enaindvajseti Jakina, dvaindvajseti Gamula,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 18, 'triindvajseti Delaja, štiriindvajseti Maazija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 19, 'To so bile njih vrste za službo, v katerih jim je bilo hoditi v hišo Gospodovo po naredbi njih očeta Arona, kakor mu je bil zapovedal Gospod, Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 20, 'Od drugih sinov Levijevih pa: od sinov Amramovih: Subael; od sinov Subaelovih: Jehdeja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 21, 'Od Rehabija, iz sinov Rehabijevih: Išija, poglavar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 22, 'Od Izharjevcev: Selomot, iz sinov Selomotovih: Jahat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 23, 'In sinovi Hebronovi: Jerija, prvak, Amarija, drugi, Jahaziel tretji, Jekameam četrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 24, 'Sinovi Uzielovi: Miha, iz sinov Mihovih: Samir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 25, 'Brat Mihov: Išija, iz sinov Išijevih: Zeharija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 26, 'Sinovi Merarijevi: Mahli in Musi; sinovi Jaazija, sinu njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 27, 'Sinovi Merarijevi od Jaazija, sinu njegovega: Soham, Zakur in Ibri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 28, 'Od Mahlija: Eleazar, ki ni imel sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 29, 'Od Kisa, sinovi Kisovi: Jerahmeel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 30, 'In sinovi Musijevi: Mahli, Eder in Jerimot. Ti so bili sinovi levitov po svojih očetovskih hišah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 24, 31, 'Tudi ti so žrebali kakor njih bratje, sinovi Aronovi, vpričo Davida kralja in Zadoka in Ahimeleka in poglavarjev duhovniških in levitskih hiš, in sicer enako glava očetovske hiše kakor njega najmanjši brat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 1, 'In David in poveljniki vojske so odločili za službo od sinov Asafovih, Hemanovih in Jedutunovih tiste, ki so imeli prorokovati s harfami, s psalmovimi citrami in s cimbali. In število mož, ki so opravljali to službo, je bilo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 2, 'od sinov Asafovih: Zakur, Jožef, Netanija in Asarela, sinovi Asafovi, pod vodstvom Asafa, ki je prorokoval po naredbi kraljevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 3, 'Od Jedutuna, sinovi Jedutunovi: Gedalija, Zeri, Jesaija, Hasabija, Matitija in Simej, šest, pod vodstvom očeta svojega Jedutuna s harfo, ki je prorokoval, pojoč zahvalo in slaveč Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 4, 'Od Hemana, sinovi Hemanovi: Bukija, Matanija, Uziel, Sebuel, Jerimot, Hananija, Hanani, Eliata, Gidalti, Romamtiezer, Josbekasa, Maloti, Hotir, Mahaziot;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 5, 'vsi ti so bili sinovi Hemana, kraljevega vidca v besedah Božjih; da bi povišal njegov rog, je dal Bog Hemanu štirinajst sinov in tri hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 6, 'Vsi ti so bili pod vodstvom očetov svojih pevci v hiši Gospodovi s cimbali, psalmovimi citrami in harfami, za službo doma Gospodovega. Asaf, Jedutun in Heman pa so bili odgovorni kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 7, 'In njih število ž njih brati vred, ki so bili poučeni v petju Gospodu, vseh izvežbanih je bilo dvesto oseminosemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 8, 'In žrebali so zavoljo svoje službe, vsi enako, mali in veliki, učitelj in učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 9, 'Prvi žreb pa je zadel Asafa in je veljal Jožefu. Drugi Gedaliju, njemu in bratom in sinovom njegovim, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 10, 'Tretji Zakurju, sinovom bratom njegovim, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 11, 'Četrti Izriju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 12, 'Peti Netaniju, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 13, 'Šesti Bukiju, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 14, 'Sedmi Jesarelu, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 15, 'Osmi Jesaiju, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 16, 'Deveti Mataniju, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 17, 'Deseti Simeju, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 18, 'Enajsti Azarelu, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 19, 'Dvanajsti Hasabiju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 20, 'Trinajsti Subaelu, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 21, 'Štirinajsti Matitiju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 22, 'Petnajsti Jeremotu, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 23, 'Šestnajsti Hananiju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 24, 'Sedemnajsti Josbekasu, njegovim sinom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 25, 'Osemnajsti Hananu, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 26, 'Devetnajsti Malotiju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 27, 'Dvajseti Eliatu, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 28, 'Edenindvajseti Hotirju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 29, 'Dvaindvajseti Gidaltu, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 30, 'Triindvajseti Mahaziotu, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 25, 31, 'Štirindvajseti Romamtiezerju, njegovim sinovom in bratom, dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 1, 'Oddelki vratarjev pa so bili: iz Korahovcev: Meselemija, sin Korejev, iz sinov Asafovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 2, 'In Meselemija je imel sinove: Zeharija, prvenec, Jediael, drugi, Zebadija, tretji, Jatniel, četrti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 3, 'Elam, peti, Johanan, šesti, Eljehoenaj, sedmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 4, 'In Obededom je imel sinove: Semaja, prvenec, Jozabad, drugi, Joah, tretji, Sakar, četrti, Netanel, peti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 5, 'Amiel, šesti, Isahar, sedmi, Peuletaj, osmi; kajti Bog ga je blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 6, 'Tudi Semaju, sinu njegovemu, se je rodilo sinov, ki so vladali hiši očeta svojega; kajti bili so vrli junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 7, 'Sinovi Semajevi: Otni, Refael, Obed, Elzabad, čigar bratje so bili vrli možje, Elihu in Semahija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 8, 'Vsi ti od sinov Obededomovih, so bili s svojimi brati in sinovi vred vrli možje, sposobni za službo, dvainšestdeset od Obededomovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 9, 'In Meselemija je imel sinove in brate, vrle može, osemnajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 10, 'Tudi Hosa, iz sinov Merarijevih, je imel sinove: Simri, prvak (kajti dasi ni bil prvenec, ga je oče njegov postavil za prvaka),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 11, 'Hilkija, drugi, Tebalija, tretji, Zeharija, četrti; vseh sinov in bratov Hosovih je bilo trinajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 12, 'Ti oddelki vratarjev, poglavarski možje, so imeli straže enako kakor njih bratje, da služijo v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 13, 'In žrebali so, enako mali kakor veliki, po očetovskih svojih hišah, za vsaka vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 14, 'In žreb za vrata proti vzhodu je bil Selemiju. Potem so vrgli kocko za Zeharija, sina njegovega, razumnega svetovalca, in njega je zadel žreb za vrata proti severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 15, 'Obededomu vrata proti jugu, sinom njegovim pa skladišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 16, 'A Supimu in Hosu proti zahodu ob vratih Saleheta, na cesti, ki se vije kvišku, straža proti straži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 17, 'Proti vzhodu je bilo šest levitov; proti polnoči na dan štiri, proti poldnevu na dan štiri in pri skladišču po dva in dva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 18, 'Pri Parbarju pa, proti zahodu, štirje na cesti in dva ob Parbarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 19, 'To so bili oddelki vratarjev, iz sinov Korahovcev in iz sinov Merarijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 20, 'Iz levitov pa je bil Ahija nad zakladi hiše Božje in nad zakladi posvečenih reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 21, 'Sinovi Ladanovi, sinovi Gersonovcev od Ladana, poglavarji očetovskih hiš od Ladana Gersonovca, so bili Jehielci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 22, 'Sinova Jehielova, Zetam in Joel, brat njegov, sta bila nad zakladi hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 23, 'Iz Amramovcev, iz Izharjevcev, iz Hebroncev, iz Uzielcev...');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 24, 'in Sebuel, sin Gersoma, sinu Mojzesovega, je bil poglavar nad zakladi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 25, 'In bratje njegovi, od Eliezerja: tega sin Rehabija, tega sin Jesaija, tega sin Joram, tega sin Zihri, tega sin Selomot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 26, 'Ta Selomot in bratje njegovi so bili nad zakladi posvečenih reči, ki so jih bili posvetili David kralj in poglavarji očetovin, poveljniki čez tisoč in čez sto in poveljniki vojske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 27, 'Od plena, ki so ga pridobili v vojni, so posvetili v podporo hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 28, 'In vse, kar je posvetil Samuel videc in Savel, sin Kisov, in Abner, sin Nerov, in Joab, sin Zervijin, kdorkoli je kaj posvetil, je bilo pod roko Selomota in bratov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 29, 'Iz Izharjevcev, Kenanija in sinovi njegovi so bili za zunanja opravila nad Izraelom, za oblastnike in sodnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 30, 'Iz Hebroncev, Hasabija in bratje njegovi, sedemnajststo vrlih mož, so nadzorovali Izraela tostran Jordana, proti zahodu, za vsakršna opravila Gospodova in za službo kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 31, 'Iz Hebroncev je bil Jerija, poglavar Hebroncem po njih rodovih, po njih očetovinah. V štiridesetem letu vladanja Davidovega so jih iskali, in našli so med njimi vrle junake v Jazerju v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 26, 32, 'In bratov njegovih, vrlih mož, je bilo dva tisoč sedemsto, poglavarjev očetovin, ki jih je David postavil v nadzorstvo Rubenovcev, Gadovcev in polovice Manasejevega rodu, za vse Božje reči in za zadeve kraljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 1, 'In to so sinovi Izraelovi po njih številu, poglavarji očetovin in poveljniki čez tisoč in čez sto in njih oblastniki, ki so služili kralju po redu oddelkov, kakor so prihajali in odhajali mesec za mesecem, vse mesece v letu; vsak oddelek je štel štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 2, 'Nad prvim oddelkom v prvem mesecu je bil Jasobeam, sin Zabdielov, in v njegovem oddelku jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 3, 'On je bil iz sinov Perezovih prvak vseh poveljnikov vojske za prvi mesec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 4, 'In nad oddelkom drugega meseca je bil Dodaj Ahohovec in v oddelku njegovem je bil knez Miklot, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 5, 'Tretji poveljnik vojske v tretjem mesecu je bil Benaja, sin Jojada duhovnika, glavar, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 6, 'To je tisti Benaja, ki je bil eden izmed tridesetih junakov in nad tridesetimi; in nad oddelkom njegovim je bil Amizabad, sin njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 7, 'Četrti poveljnik v četrtem mesecu je bil Asahel, brat Joabov, in za njim Zebadija, sin njegov, in v oddelku njegovem jih je bilo štiriiindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 8, 'Peti poveljnik v petem mesecu je bil Samhut Izrahovec, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 9, 'Šesti v šestem mesecu je bil Ira, sin Ikeša Tekojčana, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 10, 'Sedmi v sedmem mesecu je bil Helez Pelonjan iz sinov Efraimovih, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 11, 'Osmi v osmem mesecu je bil Sibekaj Husajec iz Zerahovcev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 12, 'Deveti v devetem mesecu je bil Abiezer Anatotčan iz Benjamincev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 13, 'Deseti v desetem mesecu je bil Maharaj Netofatčan iz Zerahovcev, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 14, 'Enajsti v enajstem mesecu je bil Benaja Piratončan iz sinov Efraimovih, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 15, 'Dvanajsti v dvanajstem mesecu je bil Heldaj Netofatčan, od Otniela, in v oddelku njegovem jih je bilo štiriindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 16, 'Dalje nad rodovi Izraelovimi: Rubenovcem je bil vojvoda Eliezer, sin Zihrijev; Simeoncem Sefatija, sin Maake;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 17, 'Levitskim Hasabija, sin Kemuelov, Aronovim pa Zadok;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 18, 'Judovcem Elihu, eden iz bratov Davidovih; Isaharjevcem Omri, sin Mihaelov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 19, 'Zebulonovcem Ismaja, sin Obadija; Neftalijevim Jeremot, sin Azrielov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 20, 'sinom Efraimovim Hosea, sin Azazijev; polovici rodu Manasejevega Joel, sin Pedajev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 21, 'polovici rodu Manasejevega v Gileadu Ido, sin Zeharijev; Benjamincem Jaasiel, sin Abnerjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 22, 'Danovim Azarel, sin Jerohamov. Ti so bili poveljniki rodovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 23, 'David pa ni poizvedoval števila tistih, ki jim je bilo manj nego dvajset let, zakaj Gospod je bil rekel, da razmnoži Izraela enako zvezdam nebeškim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 24, 'Joab, sin Zervijin, je začel šteti, a dokončal ni; in prišla je jeza Božja zaradi tega nad Izraela. Zato ni bilo to število vpisano v letopise kralja Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 25, 'In nad kraljevimi zakladi je bil Azmavet, sin Adielov; in nad zakladi po deželi, v mestih in po vaseh in gradovih je bil Jonatan, sin Uzijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 26, 'In nad delavci na polju, ki so obdelovali zemljo, je bil Ezri, sin Helubov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 27, 'In nad vinogradi je bil Simej Ramatejec; nad pridelki vinogradov, nad zalogami v vinskih hramih je pa bil Zabdi Sifmijan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 28, 'Nad oljkovim in smokovim drevjem, ki je bilo v nižini, je bil Baalhanan Gederski; in nad shrambami olja Joas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 29, 'In nad govedi, ki so se pasla v Saronu, je bil Sitraj Saronski, nad govedi v dolinah pa Safat, sin Adlajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 30, 'In nad velblodi Obil Izmaelec, nad oslicami pa Jehdeja Meronotičan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 31, 'nad drobnico pa Jaziz Hagarenec. Vsi ti so bili oskrbniki imetja kralja Davida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 32, 'A Jonatan, stric Davidov, je bil svetovalec, razumen mož in pismouk. In Jehiel, sin Hakmonijev, je bil pri kraljevih sinovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 33, 'Ahitofel pa je bil kraljev svetovalec, a Husaj Arkičan kraljev prijatelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 27, 34, 'Za Ahitofelom je bil Jojada, sin Benaja, in Abiatar. In poveljnik kraljevi vojski je bil Joab.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 1, 'In David zbere v Jeruzalem vse poglavarje Izraelove, vojvode rodov in poveljnike trum, ki so stregli kralju zaporedoma, in poveljnike čez tisoč in čez sto in oskrbnike imetja in posestev kraljevih in sinov njegovih, z dvorniki in junaki in z vsemi hrabrimi možmi vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 2, 'Tedaj se postavi kralj David na noge in govori: Poslušajte me, bratje moji in ljudstvo moje! Jaz sem se namenil v srcu svojem, da zgradim hišo počivanja skrinji zaveze Gospodove in podnožju nog Boga našega, in sem se pripravljal za zidanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 3, 'Ali Bog mi je rekel: Ti ne boš gradil hiše mojemu imenu, ker si mož vojščak in si kri prelival.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 4, 'Toda mene je Gospod, Bog Izraelov, izvolil iz vse hiše očeta mojega, da bodem kralj Izraelu vekomaj; zakaj Judo si je izbral, da bodi vojvoda, in v družini Judovi hišo očeta mojega, in med sinovi očeta mojega si je blagovoljno izbral mene, da me postavi za kralja vsemu Izraelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 5, 'a med vsemi sinovi mojimi – kajti mnogo sinov mi je dal Gospod – si je izvolil Salomona, sina mojega, da bo sedel na prestolu kraljestva Gospodovega nad Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 6, 'In mi je dejal: Salomon, sin tvoj, bo zgradil hišo mojo in veže moje, zakaj izvolil sem ga, da mi bodi sin in jaz mu bodem oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 7, 'In utrdim kraljestvo njegovo na vekomaj, ako bode stanovitno izpolnjeval zapovedi in sodbe moje, kakor se danes godi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 8, 'Sedaj torej, vpričo vsega Izraela, zbora Gospodovega, in vpričo Boga našega velim: Izpolnjujte in v čislih imejte vse zapovedi Gospoda, Boga svojega, da bi dedno vladali to dobro deželo in jo v dedno last zapustili otrokom svojim za seboj na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 9, 'Ti pa Salomon, sin moj, spoznaj Boga, ki je Bog očeta tvojega, in mu služi z nerazdeljenim srcem in z radovoljnim duhom! Kajti Gospod preiskuje vsa srca in razume vse naklepe misli. Ga li boš iskal, ga najdeš; ako ga pa zapustiš, te zavrže vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 10, 'Sedaj torej pazi, kajti Gospod te je izvolil, da zgradiš hišo za svetišče; močan bodi in delaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 11, 'Nato je dal David Salomonu, sinu svojemu, načrt veže pri templju in njegovih hiš in zakladnic in zgornjih sob in notranjih hramov in prostora za spravni pokrov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 12, 'in načrt vsega, kar mu je bilo v duhu: o dvorih hiše Gospodove in o vseh hramih naokoli, o zakladnicah hiše Božje in zakladnicah posvečenih reči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 13, 'tudi o oddelkih duhovnikov in levitov in o vsem delu službe v hiši Gospodovi in o vseh pripravah za službo v hiši Gospodovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 14, 'o zlatu po teži za vsakovrstne zlate posode v službo, o teži srebra za vse srebrne posode, za vsakovrstno posodje v službo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 15, 'in je določil težo zlata za zlate svečnike in njih svetilnice po teži za vsak svečnik in njegove svetilnice, in za svečnike srebrne po teži, kolikor treba za vsak svečnik in njegove svetilnice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 16, 'tudi težo zlata za mize z razvrščenimi kruhi, za vsako mizo, in srebra za srebrne mize;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 17, 'tudi čistega zlata za vilice in čaše in konvice, in za zlate kupe, za vsako kupo po njeni teži, in za srebrne kupe, za vsako po njeni teži,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 18, 'in za kadilni oltar prečiščenega zlata po teži, in za podobo voza kerubov, ki razprostirata peruti in pokrivata skrinjo zaveze Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 19, 'O vsem tem, je rekel David, o vseh posameznostih načrta me je poučil Gospod v pismu, ko je bila roka njegova nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 20, 'In David je dejal Salomonu, sinu svojemu: Bodi močan in srčen, in delaj! ne boj se in ne plaši se, zakaj Gospod Bog, moj Bog, je s teboj, ne odtegne se ti in te ne zapusti, dokler ne dokončaš vsega dela za službo hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 28, 21, 'In glej, so tu oddelki duhovnikov in levitov za vso službo hiše Božje, in bodo pri tebi prostovoljniki za vsako delo, izurjeni v vsakovrstnem delu, tudi poveljniki in vse ljudstvo ti. bo povsem na razpolago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 1, 'In kralj David reče vsemu zboru: Salomon, sin moj, ki je njega samega izvolil Bog, je še mlad in šibek, in delo je veliko, kajti tista palača ni za človeka, ampak za Gospoda Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 2, 'Jaz pa sem z vsemi močmi svojimi pripravil za hišo Boga svojega zlata za zlate, srebra za srebrne, brona za bronaste, železa za železne, lesa za lesene stvari; kamenov oniksovih in vdelanih, kamenov za olepšavo in raznobarvnih in vsakovrstnih dragih kamenov in belega marmornjaka v obilici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 3, 'Razen tega, ker me veseli hiša mojega Boga, sem dal iz lastnega zaklada zlata in srebra za hišo Boga svojega poleg vsega, kar sem oskrbel za sveto hišo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 4, 'tri tisoč talentov zlata, zlata iz Ofirja, in sedem tisoč talentov prečiščenega srebra, da se ž njim prevlečejo hišne stene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 5, 'zlata pa za zlate in srebra za srebrne stvari in za vsakovrstne naprave po rokah umetnikov. In kdo je radovoljen, danes napolniti roko svojo za Gospoda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 6, 'Tedaj so se izkazali radovoljne poglavarji očetovin in knezi rodov Izraelovih in poveljniki čez tisoč in čez sto in oskrbniki kraljevih opravil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 7, 'in so darovali za službo hiše Božje pet tisoč talentov zlata in deset tisoč dárikov, srebra pa deset tisoč talentov in brona osemnajst tisoč talentov in železa sto tisoč talentov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 8, 'In tisti, pri katerih so se našli dragi kameni, so jih dali v zaklad hiše Gospodove, pod roko Jehiela Gersonovca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 9, 'Tedaj se je ljudstvo veselilo, da so radovoljno darovali, ker z nerazdeljenim srcem so to poklonili Gospodu prostovoljno, tudi kralj David se je radoval z velikim veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 10, 'In David je hvalil Gospoda vpričo vsega zbora in je dejal: Hvaljen bodi, o Gospod, Bog Izraela, očeta našega, od vekov na veke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 11, 'Tvoja, o Gospod, je velikost in moč in slava in dika in veličastvo; zakaj vse, kar je v nebesih in na zemlji, je tvoje. Tvoje je kraljestvo, o Gospod, in ti si povišan kot glava nad vsem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 12, 'Bogastvo in čast prihaja od tebe, in ti si vladar vsemu, in v roki tvoji je moč in oblast, in v tvoji roki je poveličati in ojačiti vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 13, 'Sedaj torej, Bog naš, te zahvaljujemo in hvalimo ime slave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 14, 'Saj kdo sem jaz in kdo ljudstvo moje, da bi imeli moč, toliko radovoljno darovati tebi? Kajti od tebe je vse, in iz roke tvoje smo prejeli in dali tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 15, 'Zakaj mi smo tujci pred teboj in priseljenci, kakor so bili vsi očetje naši; dnevi naši na zemlji so kakor senca in ni upanja, da tu ostanemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 16, 'O Gospod, Bog naš, vsa ta obilna množina, ki smo jo pripravili v zgradbo hiše tvoje, svetemu imenu tvojemu, je iz roke tvoje in vse to je tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 17, 'Vem tudi, moj Bog, da preiskuješ srce in prijetna ti je preprostost. Jaz torej sem iz preprostosti srca svojega vse to radovoljno daroval, in sedaj sem z veseljem videl ljudstvo tvoje, ki je tu pričujoče, da je radovoljno darovalo tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 18, 'O Gospod, Bog Abrahama, Izaka in Izraela, očetov naših, ohrani vekomaj tako misel in namero v srcu tvojega ljudstva in obračaj njih srca k sebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 19, 'In daj Salomonu, sinu mojemu, nerazdeljeno srce, da izpolnjuje zapovedi tvoje, pričevanja tvoja in postave tvoje in da stori vse in zgradi palačo, ki sem oskrbel zanjo priprave!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 20, 'In David je rekel vsemu zboru: Hvalite sedaj Gospoda, Boga svojega! In ves zbor je hvalil Gospoda, očetov svojih Boga, in pripognili so se in storili poklon Gospodu in kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 21, 'In darovali so žrtve Gospodu, in drugo jutro potem so darovali Gospodu žgalne daritve: tisoč juncev, tisoč ovnov, tisoč jagnjet ž njih pitnimi daritvami vred, in obilo klalnih daritev za vsega Izraela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 22, 'in so jedli in pili pred Gospodom tisti dan z veliko radostjo. In so postavili Salomona, sina Davidovega, v drugič za kralja in ga pomazilili Gospodu za vojvodo in Zadoka za duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 23, 'In Salomon je zasedel prestol Gospodov kot kralj namesto Davida, očeta svojega, in uspevalo mu je, in ves Izrael ga je poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 24, 'In vsi poglavarji in junaki, tudi vsi sinovi kralja Davida so se podvrgli kralju Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 25, 'In Gospod je jako poveličal Salomona pred očmi vsega Izraela in mu je dodelil tako veličastno kraljevanje, kakršnega ni imel pred njim noben kralj v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 26, 'Tako je bil David, sin Jesejev, kralj vsemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 27, 'Časa pa, kar je kraljeval Izraelu, je bilo štirideset let: sedem let je vladal v Hebronu in triintrideset v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 28, 'In umrl je v lepi starosti, sit svojih dni, bogastva in časti. In Salomon, sin njegov, je kraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 29, 'Dejanja Davidova pa, prva in poslednja, glej, zapisana so v zgodbah Samuela vidca in v zgodbah Natana proroka in v zgodbah Gada vidca');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (13, 29, 30, 'z vsem njegovim kraljevanjem in z močjo njegovo in s časi, ki so prešli pod njim čez Izraela in čez vsa kraljestva dežel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 1, 'In Salomon, Davidov sin, se je okrepil v svojem kraljestvu, in Gospod, Bog njegov, je bil ž njim ter ga je jako poveličal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 2, 'In Salomon je govoril vsemu Izraelu, poveljnikom čez tisoč in čez sto, sodnikom in vsem knezom po vsem Izraelu, poglavarjem očetovin;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 3, 'in šli so, Salomon in ves zbor ž njim, na višavo, ki je bila v Gibeonu; zakaj ondi je bil Božji shodni šator, ki ga je bil naredil Mojzes, služabnik Gospodov, v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 4, 'Toda skrinjo Gospodovo je bil David prenesel iz Kirjat-jearima gori na mesto, ki ga ji je pripravil David; postavil ji je namreč šator v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 5, 'A bronasti oltar, ki ga je napravil Bezalel, sin Urija, sina Hurovega, je bil ondi pred šatorom Gospodovim, in Salomon in zbor ga je obiskoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 6, 'In Salomon je daroval ondi pred Gospodom na bronastem oltarju, ki je bil pri shodnem šatoru; in daroval je na njem tisoč žgalnih daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 7, 'Tisto noč se prikaže Bog Salomonu in mu reče: Prosi, kaj naj ti dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 8, 'In Salomon reče Bogu: Ti si izkazal veliko milost Davidu, očetu mojemu, in si me storil za kralja na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 9, 'In sedaj, o Gospod Bog, daj, da se uresniči obljuba tvoja Davidu, očetu mojemu; kajti postavil si me za kralja ljudstvu tolikemu, kolikor je prahu na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 10, 'Daj mi torej modrosti in znanja, da morem hoditi ven in noter pred tem ljudstvom; zakaj kdo more soditi temu velikemu ljudstvu tvojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 11, 'In Bog reče Salomonu: Ker je to bilo v srcu tvojem in nisi prosil zakladov, bogastva in časti, ne smrti sovražnikov svojih, tudi nisi prosil dolgega življenja, temuč si prosil zase modrosti in spoznanja, da bi mogel soditi ljudstvu mojemu, nad katero sem te postavil za kralja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 12, 'modrost in spoznanje je dano tebi, in še ti dam zakladov, bogastva in časti, kolikor niso imeli kralji pred teboj, pa tudi za teboj ne bodo imeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 13, 'In prišel je Salomon z višave, ki je bila v Gibeonu, izpred shodnega šatora, v Jeruzalem; in kraljeval je Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 14, 'In Salomon je nabral voz in konjikov, in imel je tisoč in štiristo voz in dvanajst tisoč konjikov, ki jih je razstavil po voznih mestih in pri kralju v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 15, 'In kralj je storil, da je bilo v Jeruzalemu srebra in zlata kakor kamenja, in ceder je pripravil toliko, da jih je bilo obilo kakor smokovega drevja, ki raste v ravnini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 16, 'In konje so vodili Salomonu iz Egipta; družba kraljevih kupcev jih je privedla trumo za kupno ceno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 1, 17, 'In so hodili gori iz Egipta in pripeljavali odondod vozove po šeststo seklov srebra in konje po sto in petdeset. Tako so jih dobivali vsi kralji Hetejcev in sirski kralji po njih roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 1, 'In Salomon se je namenil zgraditi hišo imenu Gospodovemu in hišo za svoje kraljevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 2, 'In Salomon je odštel sedemdeset tisoč mož, da nosijo bremena, in osemdeset tisoč mož, da sekajo les v gorah, in tri tisoč in šeststo, da jih nadzorujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 3, 'In poslal je k Huramu, kralju tirskemu, in sporočil: Kakor si storil z očetom mojim Davidom, ko si mu poslal cedrovine, da si zgradi hišo za prebivanje, enako stóri z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 4, 'Glej, hišo hočem zidati imenu Gospoda, Boga svojega, da mu jo posvetim, da bi se pred njim žgalo sladkodišeče kadilo in se vsekdar vrstili kruhi in darovale žgalščine zjutraj in zvečer, ob sobotah in ob mlajih in ob določenih praznikih Gospoda, našega Boga; večna je to postava Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 5, 'Hiša pa, ki jo hočem graditi, bode velika, zakaj velik je Bog naš mimo vseh bogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 6, 'A kdo je zmožen graditi mu hišo? Saj nebo in nebesa nebes ga ne morejo obseči; kdo sem torej jaz, da bi mu zgradil hišo, samo le da se zažiga kadilo pred njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 7, 'Sedaj mi torej pošlji modrega moža, ki zna delati iz zlata, srebra, brona, železa in iz zagorelordečega, karmezinovega in višnjevega blaga in ki umeje izrezljavati rezbe, da dela z veščaki, ki so pri meni v Judeji in v Jeruzalemu, katere je priskrbel oče moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 8, 'Pošlji mi tudi cedrovega, cipresovega in sandalovega lesa z Libanona; kajti vem, da znajo hlapci tvoji sekati libanonski les; in glej, hlapci moji bodo s hlapci tvojimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 9, 'da mi pripravijo veliko lesa, zakaj hiša, ki jo hočem graditi, bo nenavadno velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 10, 'In glej, jaz dam hlapcem tvojim, delavcem, ki bodo tesali les, v živež dvajset tisoč meric pšenice in dvajset tisoč meric ječmena in dvajset tisoč batov vina in dvajset tisoč batov olja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 11, 'Nato odgovori Huram, kralj tirski, v pismu, katero pošlje Salomonu: Ker Gospod ljubi ljudstvo svoje, zato te je postavil za kralja nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 12, 'Še reče Huram: Hvaljen bodi Gospod, Bog Izraelov, ki je naredil nebesa in zemljo, da je dal kralju Davidu modrega sina, obdarovanega s previdnostjo in razumnostjo, ki bo gradil hišo Gospodu in hišo za svoje kraljevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 13, 'In sedaj pošiljam modrega moža, obdarovanega z razumnostjo, Hurama, svojega očeta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 14, 'ki je sin žene izmed Danovih hčera, oče njegov pa je bil Tirec. Ta zna delati iz zlata, srebra, brona, železa, kamena, lesa, iz zagorelordečega in višnjevega blaga, iz tenčice in karmezina, tudi izrezljavati vsakovrstno rezbo ter izmišljati kakršnokoli umetnino, ki se mu naloži, da dela s tvojimi umetniki in z umetniki gospoda mojega Davida, očeta tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 15, 'Poslej naj pošilja torej gospod moj hlapcem svojim pšenice in ječmena, olja in vina, kakor je obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 16, 'Mi pa bomo sekali les z Libanona, kolikor ti ga bo treba, in ti ga spravimo na plaveh po morju v Japo, ti pa poskrbiš, da ga peljejo gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 17, 'In Salomon je preštel vse tujce v deželi Izraelovi, po štetju, po katerem jih je preštel David, oče njegov, in našteli so jih sto in triinpetdeset tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 2, 18, 'In postavil jih je sedemdeset tisoč, da nosijo bremena, in osemdeset tisoč, da sekajo les v gorah, in tri tisoč in šeststo za nadzornike, da priganjajo ljudstvo k delu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 1, 'In Salomon je začel zidati hišo Gospodovo v Jeruzalemu na gori Moriji, kjer se je Gospod prikazal Davidu, očetu njegovemu, na mestu, ki ga je David pripravil, na gumnišču Ornana, Jebusejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 2, 'Začel pa je zidati drugi dan drugega meseca, četrto leto vladanja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 3, 'In to je podlaga, ki jo je Salomon položil za zgradbo hiše Božje: Dolgost po prejšnji meri je bila šestdeset komolcev in širokost dvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 4, 'In veža, ki je bila pred hišo, vzporedno s širjavo hiše, je bila dolga dvajset komolcev in stoindvajset visoka, in prevlekel jo je znotraj s čistim zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 5, 'In veliko hišo je obil s cipresovimi deskami, ki jih je prevlekel s suhim zlatom in naredil na njih palme in verižice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 6, 'In okrasil je hišo z dragimi kameni, zlato pa je bilo zlato parvaimsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 7, 'Prevlekel je tudi hišo, bruna, pragove, stene in vrata z zlatom, in izrezal je kerube po stenah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 8, 'In napravil je hišo Najsvetejšega. Njena dolgost je bila, po širjavi hiše, dvajset komolcev in širjava njena dvajset komolcev; in prevlekel ga je z najboljšim zlatom, do šeststo talentov teže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 9, 'In teža žebljev je bila petdeset seklov zlata. In prevlekel je zgornje sobe z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 10, 'In v hiši Najsvetejšega je naredil dva keruba na podobarski način, in povlekli so ju z zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 11, 'In peruti kerubov so bile dvajset komolcev dolge; perut enega je imela pet komolcev in se je dotikala hišne stene, in druga perut je imela tudi pet komolcev in se je dotikala peruti drugega keruba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 12, 'Enako je imela perut drugega keruba pet komolcev in se je dotikala hišne stene, in druga perut je imela pet komolcev in je segala do peruti drugega keruba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 13, 'Peruti teh kerubov so se razprostirale dvajset komolcev narazen, in stala sta na svojih nogah in njiju obličje je bilo obrnjeno proti sredi hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 14, 'In napravil je zagrinjalo iz višnjevega blaga in iz škrlata in karmezina in tenčice in je vtkal vanje kerubime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 15, 'In pred hišo je naredil dva stebra, petintrideset komolcev visoka, in glavič, ki je bil vrhu vsakega, je imel pet komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 16, 'In naredil je verižice v govorišču in jih nataknil vrh na stebra, in napravil je sto margaranovih jabolk in jih obesil na verižice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 3, 17, 'In postavil je stebra pred templjem, enega na desno, drugega na levo, in imenoval je tistega na desnici Jakina in tistega na levici Boaza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 1, 'In naredil je bronast oltar, dvajset komolcev dolg in dvajset komolcev širok in deset komolcev visok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 2, 'In naredil je ulito morje, deset komolcev od roba do roba, zaokroženo okoli, in pet komolcev visoko, in vrvica tridesetih komolcev ga je objemala naokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 3, 'In pod njim so bile podobe volov, ki so ga obdajali kroginkrog, po deset na komolec, oklepajoč morje naokoli; dve vrsti volov je bilo, ulitih obenem z morjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 4, 'Stalo je na dvanajstih volih, trije so gledali proti severu, trije proti zahodu, trije proti jugu in trije proti vzhodu; in morje je ležalo na njih, in vsi njih zadnji konci so bili znotraj pod morjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 5, 'In debelost njegova je bila eno dlan, in njegov kraj je bil izdelan kakor okrajek keliha in kakor lilijevo cvetje, in je držalo tri tisoč batov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 6, 'In naredil je deset umivalnikov, in pet jih je postavil na desno in pet na levo stran, da so v njih umivali; kar je bilo od žgalnih daritev, so izpirali v njih; morje pa je bilo, da so se v njem umivali duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 7, 'Naredil je tudi deset zlatih svečnikov, kakor je bilo zanje predpisano, in postavil jih je v templju, pet po desni in pet po levi strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 8, 'In naredil je deset miz in jih postavil v templju, pet po desni in pet po levi strani. In naredil je sto zlatih čaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 9, 'In napravil je dvorišče za duhovnike in veliko dvorišče in duri na dvorišče in je okoval njih durnice z bronom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 10, 'In morje je postavil na desno stran ob vzhodu, proti jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 11, 'In Huram je naredil lonce in lopate in čaše. In dokončal je Huram delo, ki ga je delal kralju Salomonu pri hiši Božji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 12, 'dva stebra in dva vrčasta glaviča vrhu stebrov, in dve mrežasti pletenini v prestrtje obema vrčastima glavičema na vrhu stebrov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 13, 'štiristo margaranovih jabolk za tisti dve pletenini, po dve vrsti jabolk na vsako pletenino, v prestrtje obema vrčastima glavičema, ki sta bila zgoraj na stebrih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 14, 'In naredil je stojala in umivalnike na stojala,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 15, 'morje eno in dvanajst volov pod morjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 16, 'in lonce in lopate in vilice. Vse te posode je izgotovil oče Huram kralju Salomonu za hišo Gospodovo iz zlikane bronovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 17, 'V Jordanski dolini jih je dal kralj liti v ilovnati prsti, med Sukotom in Zeredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 18, 'In Salomon je napravil vseh posod veliko množino; kajti teže bronovini niso mogli dognati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 19, 'In Salomon je napravil vse tiste posode, ki so bile v hiši Božji, in zlati oltar in mize, na katerih so bili kruhi obličja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 20, 'in svečnike ž njih svetilnicami, ki naj bi gorele po predpisu pred govoriščem, iz čistega zlata,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 21, 'in cvetličje in svetilnice in utrinjače iz zlata (bilo je popolno zlato),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 4, 22, 'in usekalnike in čaše in torila in kadilnice iz čistega zlata; tudi vhod v hišo, njene notranje durnice k Najsvetejšemu in durnice ob templjevi hiši so bile iz zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 1, 'Tako je bilo dokončano vse delo, ki ga je delal Salomon za hišo Gospodovo. In Salomon je ponesel vanjo, kar je bil posvetil David, oče njegov, namreč srebro in zlato in vse posode, in del jih je v zaklade hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 2, 'Tedaj je zbral Salomon starejšine Izraelove in vse poglavarje rodov, kneze očetovinam sinov Izraelovih, v Jeruzalem, da preneso skrinjo zaveze Gospodove iz mesta Davidovega, ki je Sion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 3, 'In zbero se pri kralju vsi možje Izraelovi ob prazniku, ki je sedmi mesec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 4, 'In ko so prišli vsi starejšine Izraelovi, vzdignejo leviti skrinjo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 5, 'in jo prineso gori, in shodni šator in vse svete posode, ki so bile v šatoru; duhovniki, leviti, so jih prinesli gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 6, 'In kralj Salomon in vsa občina Izraelova, kar jih je bilo zbranih ob skrinji pri njem, so darovali ovac in volov tolikanj, da jih ni bilo moči sešteti ali oceniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 7, 'In duhovniki so ponesli skrinjo zaveze Gospodove na njeno mesto, v govorišče hiše, v Najsvetejše, pod peruti kerubov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 8, 'Kajti keruba sta razprostirala peruti nad mestom skrinje, in keruba sta pokrivala skrinjo in njena droga odzgoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 9, 'In potegnili so droga, da je bilo videti njuna konca od skrinje ob sprednji strani govorišča, ali zunaj ju ni bilo videti. In skrinja je ondi do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 10, 'Ničesar ni bilo v skrinji razen dveh plošč, ki ju je Mojzes položil vanjo na Horebu, kjer je Gospod storil zavezo s sinovi Izraelovimi, ko so šli iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 11, 'In zgodi se, ko so prišli duhovniki iz svetišča (zakaj vsi duhovniki, kar se jih je zbralo, so se bili posvetili brez ozira na svoje vrste)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 12, 'in ko so vsi leviti-pevci, Asaf, Heman in Jedutun ter njih bratje in sinovi, oblečeni v tenčico, stali s cimbali in psalmovimi strunami in harfami ob vzhodni strani oltarja in pri njih sto in dvajset duhovnikov, ki so trobili na trobente –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 13, 'zgodi se torej, ko so trobentači in pevci bili kakor eden, da bi se slišal le eden glas v proslavo in zahvalo Gospoda, in ko so povzdignili glas svoj s trobentami, cimbali in drugimi godali in hvalili Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova: tedaj se je hiša, hiša Gospodova, napolnila z oblakom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 5, 14, 'da niso mogli duhovniki stati, da bi opravljali službo, spričo oblaka, zakaj slava Gospodova je napolnila hišo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 1, 'Tedaj reče Salomon: Jehova je rekel, da bo prebival v mrakoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 2, 'A jaz sem ti zgradil hišo v prebivališče, stan tebi za sedež na veke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 3, 'In kralj obrne obličje in blagoslovi ves zbor Izraelov; in ves zbor Izraelov je stal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 4, 'In reče: Hvaljen bodi Gospod, Bog Izraelov, ki je obljubil z usti svojimi Davidu, očetu mojemu, in z roko svojo je to izpolnil, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 5, 'Od dne, ko sem odpeljal ljudstvo svoje iz dežele Egiptovske, nisem izvolil nobenega mesta iz vseh rodov Izraelovih, da se v njem zgradi hiša, ki naj bi v njej bilo ime moje; tudi nisem izvolil nikogar, da bodi vojvoda ljudstvu mojemu Izraelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 6, 'ali izvolil sem Jeruzalem, da bodi v njem moje ime, in izvolil sem Davida, da bodi nad ljudstvom mojim Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 7, 'Bilo pa je na srcu Davidu, očetu mojemu, da zgradi hišo imenu Gospoda, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 8, 'Ali Gospod je rekel Davidu, očetu mojemu: Ker ti je bilo na srcu, sezidati hišo mojemu imenu, si dobro storil, da si to imel v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 9, 'Vendar pa ti ne boš zidal tiste hiše, temuč sin tvoj, ki pride iz ledja tvojega, ta bo zgradil hišo mojemu imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 10, 'In Gospod je vzdržal besedo svojo, ki jo je govoril: kajti jaz sem nastopil na očeta svojega Davida mestu in sedim na prestolu Izraelovem, kakor je bil Gospod obljubil, in zgradil sem hišo imenu Jehove, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 11, 'In vanjo sem postavil skrinjo, v kateri je zaveza Gospodova, ki jo je sklenil s sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 12, 'In stopi pred oltar Gospodov vpričo vsega zbora Izraelovega in razprostre roke');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 13, '(naredil je bil namreč Salomon bronast oder, pet komolcev dolg in pet komolcev širok in tri komolce visok, in ga je postavil sredi dvorišča; in nanj stopivši, poklekne na kolena pred vsem zborom Izraelovim in razprostre roke proti nebu)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 14, 'in reče: O Gospod, Bog Izraelov, tebi ni enakega Boga v nebesih ali na zemlji, ki hraniš zavezo in milost hlapcem svojim, ki hodijo pred obličjem tvojim z vsem srcem svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 15, 'ki si ohranil hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil. Z usti svojimi si govoril in z roko svojo si to izpolnil, kakor se danes vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 16, 'In sedaj, Gospod, Bog Izraelov, ohrani hlapcu svojemu Davidu, očetu mojemu, kar si mu bil obljubil, govoreč: Ne bo ti zmanjkalo pred obličjem mojim moža, ki bo sedel na prestolu Izraelovem, samo če pazijo sinovi tvoji na pot svojo, da hodijo po moji postavi, kakor si ti hodil pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 17, 'Sedaj torej, Gospod, Bog Izraelov, naj se uresniči beseda tvoja, ki si jo govoril hlapcu svojemu Davidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 18, 'Toda prebiva li v istini Bog z ljudmi na zemlji? Glej, nebo in nebes nebesa te ne morejo obseči, koliko manj ta hiša, ki sem jo sezidal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 19, 'Vendar se ozri na molitev svojega hlapca in na njegovo prošnjo, Gospod, Bog moj, da poslušaš vpitje in molitev, ki jo moli hlapec tvoj pred teboj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 20, 'da bodo oči tvoje odprte proti tej hiši po dne in po noči, proti mestu, o katerem si rekel, da postaviš tam ime svoje, da uslišiš molitev, ki jo bo molil hlapec tvoj na tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 21, 'Poslušaj torej prošnjo hlapca svojega in ljudstva svojega Izraela, ki jo bodo prosili, obrnjeni proti temu mestu, poslušaj na mestu prebivanja svojega, v nebesih, in ko poslušaš, odpuščaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 22, 'Ako se kdo pregreši zoper bližnjega svojega in se mu naloži prisega, da se zaveže s prisego, in ta prisega pride pred tvoj oltar v tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 23, 'ti poslušaj v nebesih in stóri, da se pravica zgodi hlapcem tvojim s tem, da obsodiš krivičnega ter mu spraviš pot njegov na glavo, pravičnega pa opravičiš in mu poplačaš po pravičnosti njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 24, 'Kadar bo ljudstvo tvoje izraelsko poraženo pred sovražnikom, ker so grešili zoper tebe, pa se zopet obrnejo in pripoznajo tvoje ime in bodo molili in ponižno prosili pred teboj v tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 25, 'ti poslušaj v nebesih in odpusti greh ljudstva svojega, Izraela, ter jih zopet pripelji v deželo, ki si jo dal njim in njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 26, 'Kadar se zapre nebo, da ne bo dežja, ker so grešili zoper tebe, pa bodo molili, obrnjeni proti temu kraju, in pripoznavali tvoje ime in se izpreobrnejo od grehov svojih, ker si jih ponižal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 27, 'ti poslušaj v nebesih in odpusti greh hlapcev svojih in ljudstva svojega, Izraela, da jih učiš dobro pot, po kateri naj hodijo, in pošlješ dežja deželi svoji, ki si jo dal ljudstvu svojemu v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 28, 'Kadar bode v deželi lakota, kadar pride kuga ali snet ali strupena rosa, kobilice ali gosenice; ko jih bodo sovražniki oblegali v deželi njih mest; katerakoli pridi nadloga, katerakoli bolezen:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 29, 'kakršnokoli molitev in prošnjo bo molil kdo ali vse ljudstvo tvoje izraelsko, kadar spozna vsakteri svojo kazen in svojo nadlogo in iztegne roke proti tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 30, 'ti poslušaj v nebesih, v mestu prebivanja svojega, in odpusti in vsakemu povrni po vsem življenju njegovem, kakor spoznaš srce njegovo (zakaj ti, edini ti poznaš srca otrok človeških),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 31, 'da bi se te bali in hodili po potih tvojih, dokler žive v deželi, ki si jo dal njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 32, 'Ako pa tudi inostranec, ki ni iz ljudstva tvojega, Izraela, pride iz daljne dežele zaradi imena tvojega velikega in zaradi močne roke tvoje in iztegnjene rame tvoje; ko torej pridejo in bodo molili proti tej hiši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 33, 'ti poslušaj v nebesih, v mestu prebivanja svojega, in stóri vse, za kar te kliče inostranec; da spoznajo vsa ljudstva na zemlji tvoje ime, da bi se te bali kakor ljudstvo tvoje, Izrael, ter da se prepričajo, da se imenuje ta hiša, ki sem jo zgradil, po imenu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 34, 'Kadar pojde ljudstvo tvoje v vojno zoper sovražnike svoje, po kateremkoli potu jih pošlješ, in bodo molili k tebi, ozirajoč se proti temu mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 35, 'ti poslušaj v nebesih njih molitev in prošnjo ter se potegni za njih pravdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 36, 'Kadar se pregreše zoper tebe (kajti ni ga človeka, ki ne greši) in se razsrdiš nad njimi in jih izročiš sovražniku, da jih ujete peljejo v deželo daljno ali bližnjo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 37, 'ako pa se premislijo v deželi, kamor so bili odpeljani v ujetništvo, in se izpreobrnejo in te ponižno prosijo v deželi ujetništva svojega, govoreč: Grešili smo, krivično smo delali, brezbožno smo ravnali!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 38, 'ako se k tebi povrnejo iz vsega srca svojega in iz vse duše svoje v deželi ujetništva svojega, kamor so jih ujete odpeljali, in molijo, ozirajoč se proti deželi svoji, ki si jo dal njih očetom, in mestu, ki si ga izvolil, in proti hiši, ki sem jo zgradil imenu tvojemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 39, 'ti poslušaj v nebesih, v mestu prebivanja svojega, njih molitev in prošnjo ter se potegni za njih pravdo, in odpusti ljudstvu svojemu, ki je grešilo zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 40, 'Sedaj torej, Bog moj, prosim, naj bodo odprte oči tvoje in pazijo naj ušesa tvoja na molitev, ki se opravlja na tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 41, 'Sedaj torej vstani, o Gospod Bog, pridi v počivališče svoje, ti in skrinja moči tvoje! Duhovniki tvoji, o Gospod Bog, naj bodo oblečeni z zveličanjem, in svetniki tvoji naj se vesele dobrote!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 6, 42, 'O Gospod, Bog, ne zavrni obličja maziljenca svojega! Spominjaj se dobrot, obljubljenih Davidu, hlapcu svojemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 1, 'In ko je Salomon izmolil, švigne ogenj z neba in požre žgalno in klalno daritev. In slava Gospodova je napolnila hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 2, 'In duhovniki niso mogli stopiti v hišo Gospodovo, ker je slava Gospodova napolnila hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 3, 'In vsi sinovi Izraelovi so gledali, ko je prišel ogenj doli in je bila slava Gospodova nad hišo; in pripognili so se z obrazom do tal, na tlak, in so molili in zahvaljevali Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 4, 'In kralj in vse ljudstvo so darovali klalne daritve pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 5, 'In kralj Salomon je daroval dvaindvajset tisoč goved in stoindvajset tisoč glav drobnice. Tako so posvetili hišo Božjo kralj in vse ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 6, 'In stali so duhovniki in stregli po svoji službi, tudi leviti z glasbenim orodjem Gospodovim, ki ga je bil napravil kralj David, da zahvaljujejo Gospoda, ker vekomaj traja milost njegova, s psalmi Davidovimi v roki; in duhovniki so trobili na trobente njim nasproti, in ves Izrael je stal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 7, 'In kralj Salomon je posvetil sredo dvorišča, ki je bilo pred hišo Gospodovo; zakaj tam je daroval žgalne daritve in tolstino mirovnih daritev, ker bronasti oltar, ki ga je bil Salomon napravil, je bil premajhen, da bi sprejel žgalne in mirovne daritve in tolstino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 8, 'In tisti čas je praznoval Salomon praznik sedem dni in ves Izrael ž njim, silno velik zbor, ki se je sešel od vhoda v Hamat do Egiptovskega potoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 9, 'In osmi dan so imeli slovesno zborovanje; kajti praznovali so posvečevanje oltarja sedem dni, praznik pa tudi sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 10, 'In triindvajseti dan sedmega meseca je razpustil ljudstvo v njih šatore veselo in dobre volje zaradi dobrot, ki jih je izkazal Gospod Davidu in Salomonu in Izraelu, ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 11, 'Tako je dokončal Salomon hišo Gospodovo in hišo kraljevo; in vse, kar je prišlo Salomonu v srce, da napravi v hiši Gospodovi in v lastni hiši, je uspešno dovršil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 12, 'In Gospod se prikaže Salomonu po noči in mu reče: Uslišal sem molitev tvojo in sebi izvolil to mesto za daritveno hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 13, 'Kadar zaprem nebo, da ne bo dežja, ali če zapovem kobilicam, da pojedo deželo, ali če pošljem kugo med ljudstvo svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 14, 'ako se bo ljudstvo moje, ki je imenovano po mojem imenu, ponižalo in molilo in iskalo obličje moje ter se odvrnilo od hudobnih poti svojih: tedaj uslišim iz nebes in odpustim njih greh in ozdravim njih deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 15, 'Sedaj bodo oči moje odprte in ušesa moja bodo pazila na molitev, ki se opravlja na tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 16, 'Kajti sedaj sem izvolil in posvetil to hišo, da bodi moje ime tukaj vekomaj, in moje oči in srce moje naj bodo vselej tu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 17, 'Ti pa, če boš hodil pred menoj, kakor je hodil David, oče tvoj, da storiš po vsem, kar sem ti zapovedal, in boš držal postave in sodbe moje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 18, 'tedaj utrdim stol kraljestva tvojega, kakor sem se zavezal Davidu, očetu tvojemu, rekoč: Ne bo ti zmanjkalo moža, ki bo vladal Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 19, 'Ako se pa boste odvrnili in zapustili postave in zapovedi moje, ki sem vam jih predložil, in pojdete služit drugim bogovom ter jih boste molili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 20, 'tedaj jih izkoreninim iz svoje dežele, ki sem jo jim dal, in hišo to, ki sem jo posvetil za svoje ime, zavržem izpred obličja svojega in jo dam v pregovor in v zabavljico med vsemi ljudstvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 21, 'In ob tej hiši, ki je bila tako visoka, bo vsak strmel, kdor pojde mimo, in dejal: Zakaj je Gospod tako storil tej deželi in tej hiši?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 7, 22, 'In poreko: Ker so zapustili Gospoda, očetov svojih Boga, ki jih je izpeljal iz dežele Egiptovske, in so se oklenili drugih bogov ter jih molili in jim služili: zato je pripravil nadnje vso to nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 1, 'In zgodi se ob koncu dvajsetih let, v katerih je Salomon zidal hišo Gospodovo o in svojo hišo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 2, 'da je zidal Salomon tudi mesta, ki jih je bil dal Huram Salomonu, in je naselil vanje sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 3, 'In Salomon je šel proti Hamat-zobi in jo je premagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 4, 'In sezidal je Tadmor v puščavi in vsa mesta za skladišča, ki jih je zgradil v Hamatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 5, 'Tudi je sezidal Bethoron Gorenji in Bethoron Dolenji, utrjeni mesti z obzidjem, z vrati in zapahi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 6, 'in Baalat in vsa mesta za skladišča, ki jih je imel Salomon, in vsa mesta za vozove in vsa mesta za konjike njegove in vse, kar je želel Salomon sezidati sebi v veselje v Jeruzalemu in na Libanonu in po vsej deželi gospostva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 7, 'Vse ljudstvo pa, kar ga je preostalo od Hetejcev, Amorejcev, Ferizejcev, Hevejcev in Jebusejcev, ki niso bili iz Izraela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 8, 'njih otroke, ki so za njimi ostali v deželi in jih niso iztrebili sinovi Izraelovi, iz teh je Salomon nabral robotnikov do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 9, 'A izmed sinov Izraelovih ni storil nikogar za tlačana pri svojem delu, ampak bili so vojaki in prvi poveljnikov njegovih in višji nad njegovimi vozovi in nad njegovimi konjiki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 10, 'In teh višjih oblastnikov kralja Salomona je bilo dvesto in petdeset, ki so gospodovali ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 11, 'Hčer Faraonovo pa je Salomon prepeljal iz mesta Davidovega v hišo, ki jo je bil sezidal zanjo, kajti dejal je: Žena moja ne bo prebivala v hiši Davida, kralja Izraelovega, kajti tisti kraji, ki je vanje prišla skrinja Gospodova, so sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 12, 'Poslej je daroval Salomon žgalne daritve Gospodu na oltarju Gospodovem, ki ga je bil zgradil pred vežo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 13, 'in sicer kakor je bilo obvezno za vsak dan, je daroval po zapovedi Mojzesovi, ob sobotah in ob mlajih in ob prazničnih dneh trikrat na leto: ob prazniku opresnikov, ob prazniku tednov in ob prazniku šatorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 14, 'In postavil je, po predpisu očeta svojega Davida, oddelke duhovnikov v njih službo in levite na njih stražo, da hvalijo Boga in strežejo pred duhovniki, kolikor je bilo treba za vsak dan; tudi vratarje po njih oddelkih pri vsakih vratih, zakaj tako je bil zapovedal David, mož Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 15, 'In niso odstopili od kraljeve zapovedi za duhovnike in levite v nobenem oziru, tudi glede zakladov ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 16, 'In bilo je pripravljeno vse delo Salomonovo do dne, ko se je položila podstava hiši Gospodovi, in dokler se ni dokončala. Tako je bila dogotovljena hiša Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 17, 'Tedaj je šel Salomon v Ezion-geber in v Elot na morskem bregu v Edomski deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 8, 18, 'In Huram mu je poslal ladje po hlapcih svojih in hlapce, ki so bili izvedeni na morju; in prišli so s hlapci Salomonovimi v Ofir in pripeljali so odondod štiristo in petdeset talentov zlata in ga prinesli kralju Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 1, 'Ko pa je slišala kraljica v Sabi Salomonov sloves, je prišla z ugankami izkušat Salomona v Jeruzalem s silno velikim spremstvom in z velblodi, ki so nesli dišav in zlata jako mnogo in dragega kamenja. In ko je dospela k Salomonu, je govorila ž njim o vsem, kar ji je bilo na srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 2, 'In Salomon ji je razložil vse, kar ga je vprašala; in ni bilo stvari, ki bi bila skrita Salomonu, da bi ji ne bil povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 3, 'Ko pa je čula kraljica iz Sabe modrost Salomonovo in videla hišo, ki jo je zgradil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 4, 'in jed na mizi njegovi in bivališče hlapcev njegovih in strežbo služabnikov njegovih in njih obleko, njegove točaje in njih obleko in stopnice njegove, po katerih je hodil v hišo Gospodovo, ji je od strmenja sapa zastala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 5, 'In reče kralju: Resnična je bila beseda, ki sem jo slišala v deželi svoji o tvojih stvareh in o tvoji modrosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 6, 'Toda nisem hotela verjeti njih besedam, dokler nisem prišla in tega videla s svojimi očmi. In glej, ne polovice mi niso povedali o velikosti tvoje modrosti: vsega več je pri tebi nego v govorici, ki sem jo slišala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 7, 'Blagor tvojim ljudem in blagor tem tvojim hlapcem, ki vedno stoje pred teboj in poslušajo modrost tvojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 8, 'Hvaljen bodi Gospod, Bog tvoj, ki ti je bil blagovoljen, da te je posadil na prestol svoj za kralja Gospodu, Bogu tvojemu! Kajti Bog tvoj ljubi Izraela in ga hoče vzdržati na vekomaj, zato te je postavil za kralja nad njimi, da izvršuješ sodbo in pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 9, 'In dala je kralju sto in dvajset talentov zlata in veliko množino dišav in dragih kamenov; ni bilo več takih dišav kakor tiste, ki jih je dala kraljica iz Sabe Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 10, 'Pa tudi hlapci Huramovi in hlapci Salomonovi, ki so peljali zlato iz Ofirja, so pripeljali sandalovine in dragih kamenov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 11, 'In kralj je dal narediti iz sandalovega lesa stopnice za hišo Gospodovo in za hišo kraljevo, tudi harfe in psalmove citre pevcem; kaj takega ni bilo poprej videti v deželi Judovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 12, 'In kralj Salomon je dal kraljici iz Sabe vse, kar je želela in kar je prosila, razen tega, kar je bila sama prinesla kralju. In vrnila se je ter odšla v deželo svojo, ona in njeni hlapci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 13, 'Teža zlata pa, ki je prišlo Salomonu na leto, je bila šeststo šestdeset in šest talentov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 14, 'razen tega, kar so prinesli popotniki in trgovci; tudi vsi kralji arabski in deželni namestniki so prinašali zlata in srebra Salomonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 15, 'In kralj Salomon je naredil dvesto ščitov iz tolkljanega zlata: šeststo seklov tolkljanega zlata je porabil za en ščit;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 16, 'in tristo malih ščitov iz tolkljanega zlata, po tristo seklov zlata je šlo na en ščit. In kralj jih je zložil v hiši libanonskega gozda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 17, 'In kralj je napravil velik prestol iz slonovih kosti in ga je prevlekel s čistim zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 18, 'Imel je pa prestol šest stopnic, s podnožjem zlatim, priklenjenih k sebi, in dve naslonili na obeh straneh pri sedežu in dva leva, stoječa ob naslonilih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 19, 'In dvanajst levov je stalo na tej in na oni strani ob šesterih stopnicah; kaj takega ni bilo videti v nobenem kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 20, 'Pa tudi vse posode, iz katerih je pil kralj Salomon, so bile zlate, in vsa oprava v hiši libanonskega gozda je bila iz čistega zlata; srebra niso nič čislali v dnevih Salomonovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 21, 'Zakaj kralj je imel ladje, ki so vozile v Tarsis s hlapci Huramovimi; po enkrat v treh letih so dospevale tarske ladje, nesoč zlata in srebra, slonovih kosti, opic in pavov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 22, 'In kralj Salomon je nadkriljeval vse kralje na zemlji v bogastvu in v modrosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 23, 'In vsi kralji zemlje so hrepeneli po obličju Salomonovem, da bi slišali modrost njegovo, ki mu jo je dal Bog v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 24, 'In prinašali so mu vsak darilo svoje: posode srebrne in posode zlate, oblačila, orožje in dišave, konje, mezge, vsako leto, kar je bilo pristojno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 25, 'In Salomon je imel štiri tisoč stanov za konje in vozove ter dvanajst tisoč konjikov, ki jih je razstavil po voznih mestih in pri kralju v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 26, 'In vladal je vsem kraljem od velereke do dežele Filistejcev in do meje Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 27, 'In kralj je storil, da je bilo v Jeruzalemu srebra kakor kamenja, in ceder je omislil toliko, da jih je bilo kakor smokovega drevja, ki raste v ravnini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 28, 'In konje so vodili Salomonu iz Egipta in iz vseh dežel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 29, 'A druge zgodbe Salomonove, prve in poslednje, niso li zapisane v zgodovini Natana proroka in v prorokovanju Ahija Silonskega in v prikaznih Ida vidca o Jeroboamu, sinu Nebatovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 30, 'In Salomon je vladal v Jeruzalemu nad vsem Izraelom štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 9, 31, 'In Salomon je legel k očetom svojim in je bil pokopan v mestu Davida, očeta svojega; in Roboam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 1, 'In Roboam je šel v Sihem, kajti ves Izrael se je sešel v Sihemu, da ga postavijo za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 2, 'In zgodi se, ko je slišal o tem Jeroboam, sin Nebatov (bil je namreč v Egiptu, kamor je bil zbežal izpred kralja Salomona), da se vrne iz Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 3, 'In pošljejo ter ga pokličejo. In pride Jeroboam in ves Izrael ter ogovore Roboama, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 4, 'Oče tvoj nam je preobtežal jarem; sedaj torej nam polajšaj pretrdo službo očeta svojega in težki jarem, ki nam ga je naložil, in bomo ti služili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 5, 'In on jim reče: Pridite zopet k meni po treh dneh. In ljudstvo odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 6, 'In kralj Roboam se je posvetoval s starci, ki so stali v službi pred Salomonom, očetom njegovim, ko je še živel, in reče: Kako svetujete, da naj odgovorim temu ljudstvu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 7, 'In mu odgovore, rekoč: Ako boš dobrotljiv temu ljudstvu in jim ugodiš in jim izpregovoriš prijazne besede, ti bodo hlapci vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 8, 'Ali on je zavrgel svet starcev, ki so mu ga dali, in se je posvetoval z mladeniči, ki so zrasli ž njim, ki so stali v službi pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 9, 'In jih vpraša: Kaj svetujete, da naj odgovorimo temu ljudstvu, ki so govorili meni, rekoč: Polajšaj jarem, ki ga nam je naložil oče tvoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 10, 'Tedaj mu reko mladiči, ki so ž njim zrasli: Ljudstvu, ki ti je dejalo: Oče tvoj nam je preobtežal jarem, ti pa nam ga polajšaj! odgovóri takole: Moj mali prst je večji nego očeta mojega ledje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 11, 'Sedaj torej, če vas je obremenil oče moj s težkim jarmom, jaz še pridenem jarmu vašemu; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 12, 'Tedaj pride Jeroboam in vse ljudstvo k Roboamu tretji dan, kakor je kralj velel, rekoč: Pridite k meni zopet tretji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 13, 'In kralj Roboam odgovori ljudstvu trdo, kajti zavrgel je svet starcev');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 14, 'in jim govoril po svetu mladičev takole: Oče moj vam je naložil težek jarem, jaz pa še pridenem; oče moj vas je tepel z biči, jaz pa vas bom s trnovkami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 15, 'Kralj torej ni uslišal ljudstva, kajti Bog je tako vodil, da potrdi Gospod besedo svojo, ki jo je govoril po Ahiju Silonskem Jeroboamu, sinu Nebatovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 16, 'In ko je videl ves Izrael, da jih kralj ni uslišal, odgovori ljudstvo kralju in reče: Kakšen delež nam je v Davidu? in dediščine nimamo v sinu Jesejevem. Vsakdo k svojim šatorom, o Izrael! Sedaj glej hišo svojo, David! In ves Izrael se je razšel v šatore svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 17, 'Samo sinovom Izraelovim, ki so prebivali v Judovih mestih, je kraljeval Roboam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 18, 'Nato pošlje kralj Roboam Hadoroma, ki je bil nad roboto, a sinovi Izraelovi so ga posuli s kamenjem, da je umrl. In pohiti kralj Roboam in stopi na svoj voz, da pobegne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 10, 19, 'Tako je odstopil Izrael od hiše Davidove do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 1, 'In ko Roboam dospe v Jeruzalem, zbere hišo Judovo in Benjaminovo, sto in osemdeset tisoč izbranih mož vojščakov, da se bojujejo zoper Izraela in zopet pridobé kraljestvo Roboamu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 2, 'Ali beseda Gospodova pride Semaju, možu Božjemu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 3, 'Govóri Roboamu, sinu Salomonovemu, kralju Judovemu, in vsemu Izraelu na Judovem in Benjaminovem, in véli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 4, 'Tako pravi Gospod: Ne hodite gori in ne bojujte se z brati svojimi; vrnite se vsak v hišo svojo, zakaj od mene je prišla ta reč. In poslušali so besedo Gospodovo in so se vrnili, da ne bi šli zoper Jeroboama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 5, 'In Roboam je prebival v Jeruzalemu in prezidal je mesta na Judovem v trdnjave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 6, 'Pozidal je namreč Betlehem, Etam, Tekoo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 7, 'Betzur, Soko, Adulam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 8, 'Gat, Mareso, Zif,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 9, 'Adoraim, Lahis, Azeko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 10, 'Zoro, Ajalon in Hebron, utrjena mesta na Judovem in Benjaminovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 11, 'In utrdil je trdnjave in namestil poveljnike vanje in preskrbel živeža, olja in vina,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 12, 'in v vsako posamezno mesto je del ščite in sulice ter jih je povsem dobro utrdil. In Juda in Benjamin sta bila njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 13, 'In duhovniki in leviti, ki so bili po vsem Izraelu, so prišli k njemu iz vseh svojih krajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 14, 'Kajti leviti so zapustili svoje okraje in posestva ter so se priselili na Judovo in v Jeruzalem; Jeroboam in sinovi njegovi so jih namreč zavrgli, da ne bi opravljali duhovniške službe Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 15, 'in postavil si je duhovnike za višave in za mališke kozle in za teleti, ki si ju je bil naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 16, 'In za duhovniki so prihajali iz vseh rodov Izraelovih tisti, ki so nagnili srce svoje, da bi iskali Gospoda, Izraelovega Boga, v Jeruzalem darovat Gospodu, Bogu očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 17, 'S tem so pomagali do moči kraljestvu Judovemu in utrjevali Roboama, sina Salomonovega, tri leta; kajti tri leta so hodili po poti Davidovi in Salomonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 18, 'In Roboam si vzame za ženo Mahalato, hčer Jerimota, sina Davidovega, in Abihaile, hčere Eliaba, sina Jesejevega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 19, 'in ona mu je rodila sinove: Jeuša, Semarija in Zahama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 20, 'Po tej si vzame še Maako, hčer Absalomovo, in ta mu je rodila Abija, Ataja, Ziza in Selomita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 21, 'Ljubil je pa Roboam Maako, hčer Absalomovo, bolj nego vse žene in priležnice svoje (vzel si je namreč osemnajst žen in šestdeset priležnic in je rodil osemindvajset sinov in šestdeset hčera).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 22, 'In Roboam je postavil Abija, sina Maake, da bodi glava, knez med svojimi brati, zakaj hotel ga je postaviti za kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 11, 23, 'In ravnal je previdno in razstavil je vse sinove svoje po vseh krajih Judovih in Benjaminovih, po vseh utrjenih mestih, in oskrbel jim je živeža v obilici; in snubil jim je mnogo žen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 1, 'In zgodi se, ko je bilo utrjeno kraljestvo Roboamovo in se je on ojačil, da je zapustil postavo Gospodovo in ves Izrael ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 2, 'In v petem letu kralja Roboama je prišel gori Sisak, kralj egiptovski, proti Jeruzalemu, zato ker so bili nezvesti Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 3, 'z dvanajststo vozovi in šestdeset tisoč konjiki in brezštevilnim moštvom, ki je prišlo ž njim iz Egipta: Lubimi, Sukimi in Etiopci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 4, 'In dobil je utrjena mesta, ki so bila Judova, in dospel je k Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 5, 'Tedaj pride Semaja, prorok, k Roboamu in k poglavarjem Judovim, ki so se zaradi Sisaka zbrali v Jeruzalemu, in jim reče: Tako pravi Gospod: Vi ste zapustili mene, zato sem tudi jaz vas pustil v roke Sisakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 6, 'Tedaj se ponižajo poglavarji Izraelovi in kralj in reko: Pravičen je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 7, 'In ko je videl Gospod, da so se ponižali, pride beseda Gospodova k Semaju, govoreč: Ponižali so se, ne bom jih pokončal, temuč dam jim malo pomoči, in srd moj se ne bo razlil nad Jeruzalemom po roki Sisakovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 8, 'Vendar pa mu morajo biti podložni, da spoznajo, kaj je meni služiti in kaj služiti zemeljskim kraljestvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 9, 'Pride torej Sisak, kralj egiptovski, proti Jeruzalemu in vzame zaklade hiše Gospodove in zaklade hiše kraljeve, pobere vse, vzame tudi zlate ščite, ki jih je napravil Salomon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 10, 'In kralj Roboam naredi namesto njih ščite iz brona in jih izroči poveljnikom stražarjev, ki so čuvali vrata kraljeve hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 11, 'In kadarkoli je šel kralj v hišo Gospodovo, so prišli stražarji in jih nosili in potem jih zopet odnesli v stražnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 12, 'In ko se je ponižal, se je odvrnila od njega jeza Gospodova, da ga ni docela pokončal. Tudi je bilo pri Judi še nekoliko dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 13, 'In okrepil se je Roboam zopet v Jeruzalemu in je kraljeval. Zakaj enainštirideset let je bilo Roboamu, ko je zakraljeval, in vladal je sedemnajst let v Jeruzalemu, v mestu, ki si ga je izvolil Gospod iz vseh rodov Izraelovih, da postavi ondi ime svoje. In materi njegovi je bilo ime Naama, Amonka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 14, 'In delal je, kar je bilo hudo, ker ni pripravil srca svojega, da bi iskal Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 15, 'A dejanja Roboamova, prva in poslednja, niso li zapisana v zgodbah Semaja proroka in Ida vidca med rodopisi? In boji so bili med Roboamom in Jeroboamom vse njiju dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 12, 16, 'In Roboam je legel k očetom svojim in pokopali so ga v mestu Davidovem; in Abija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 1, 'V osemnajstem letu kralja Jeroboama je Abija zavladal Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 2, 'Tri leta je vladal v Jeruzalemu. Materi njegovi pa je bilo ime Mikaja, hči Uriela iz Gibea. In bila je vojna med Abijem in Jeroboamom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 3, 'In Abija je šel na boj z armado hrabrih vojščakov, štiristo tisoč izbranih mož; Jeroboam pa se razvrsti v boj zoper njega z osemsto tisoč izbranimi možmi, hrabrimi junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 4, 'In Abija stopi na goro Zemaraim v Efraimskem gorovju in reče: Poslušajte me, Jeroboam in ves Izrael!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 5, 'Ne veste li, da je Gospod, Bog Izraelov, dal kraljestvo nad Izraelom Davidu na vekomaj, njemu in sinom njegovim po solni zavezi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 6, 'Ali Jeroboam, sin Nebatov, hlapec Salomona, sinu Davidovega, je vstal in se uprl gospodu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 7, 'In zbrali so se pri njem praznoglavi ljudje, otroci Belijalovi, ki so se ohrabrili zoper Roboama, sina Salomonovega, ko je bil Roboam še mlad in plahega srca in se jim ni mogel ubraniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 8, 'Vi pa sedaj mislite, da se morete postaviti zoper Gospodovo kraljestvo, ki je v roki sinov Davidovih, ker vas je velika množica in imate pri sebi zlati teleti, ki vam ju je naredil Jeroboam za bogove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 9, 'Niste li pregnali duhovnikov Gospodovih, sinov Aronovih in levitov, in niste si li postavili duhovnikov po načinu ljudstev v drugih deželah? Kdorkoli pride, da se posveti z mladim juncem in sedmimi ovni, postane duhovnik tistim, ki niso bogovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 10, 'Toda z nami je Gospod, naš Bog, ki ga nismo zapustili, in imamo duhovnike, ki strežejo Gospodu, sinove Aronove in levite v svojem opravilu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 11, 'ti zažigajo Gospodu vsako jutro in vsak večer žgalne daritve in sladkodišeče kadilo in skrbe za razvrstitev kruhov na čisti mizi ter za zlati svečnik ž njegovimi svetilnicami, da se prižigajo vsak večer; kajti mi opravljamo stražo Gospoda, svojega Boga, vi pa ste ga zapustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 12, 'In glejte, Bog je z nami, nam na čelu, in duhovniki njegovi z donečimi trobentami, da bučno trobentajo zoper vas. O Izraelovi otroci, ne bojujte se zoper Gospoda, svojih očetov Boga, ker ne boste imeli sreče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 13, 'Ali Jeroboam je velel zasedi, naj po ovinkih pridejo nadnje odzadaj; tako je stal on pred Judovimi, in zaseda je bila za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 14, 'In ko so se Judovi ozrli, glej, boj jim je bil spredaj in zadaj! In vpijejo h Gospodu, in duhovniki so močno trobili na doneče trobente.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 15, 'In možje Judovi zaženo bojni krik, in ko so Judovi kričali, je Bog porazil Jeroboama in vsega Izraela pred Abijem in Judovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 16, 'In sinovi Izraelovi zbeže pred Judovimi, in Bog je dal nje v njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 17, 'In Abija in ljudstvo njegovo jim je prizadelo velik poraz, da je padlo ubitih v Izraelu petsto tisoč izbranih mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 18, 'Tako so bili tisti čas Izraelovi sinovi ponižani, a sinovi Judovi so se ojačili, ker so se opirali na Gospoda, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 19, 'In podil je Abija bežečega Jeroboama in mu je vzel mesta: Betel in njemu podložne vasi, Ješano in njej podložne vasi ter Efron in njegove vasi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 20, 'Tudi si ni opomogel Jeroboam nič več v dnevih Abijevih; in Gospod ga je udaril, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 21, 'A Abija je prihajal močnejši in si je vzel štirinajst žen ter je rodil dvaiindvajset sinov in šestnajst hčera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 13, 22, 'Kar je pa več praviti o Abiju, njegovi poti in njegovi govori so zapisani v razlagi Ida proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 1, 'In Abija je legel k očetom svojim, in pokopali so ga v mestu Davidovem; in Asa, sin njegov, je zakraljeval na mestu njegovem. V dnevih njegovih je imela dežela mir deset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 2, 'In Asa je delal, kar je bilo dobro in pravično v očeh Gospoda, njegovega Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 3, 'kajti odpravil je tuje oltarje in višave in je strl stebre in posekal Ašere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 4, 'In ukazal je Judi, naj išče Gospoda, Boga očetov svojih, in izpolnjuje postavo in zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 5, 'Odpravil je tudi iz vseh mest Judovih višave in solnčne podobe. In kraljevina je imela mir pod njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 6, 'In sezidal je utrjena mesta na Judovem, kajti dežela je imela mir in ni bilo vojne zoper njega v tistih letih, ker mu je Gospod dal pokoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 7, 'Velel je namreč Judi: Zgradimo ta mesta in napravimo zidove okoli njih in stolpe, vrata in zapahe! Dežela je še pred nami, kajti iskali smo Gospoda, svojega Boga, iskali smo ga, in dal nam je pokoj naokoli. Nato so zidali, in šlo jim je po sreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 8, 'In Asa je imel vojake, ki so nosili ščite in sulice, iz Jude tristo tisoč, iz Benjamina pa, ki so nosili ščite in z loka streljali, dvesto in osemdeset tisoč; ti so vsi bili vrli junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 9, 'Prišel je pa nadnje Zerah, Etiopec, z vojsko tisočkrat tisoč mož in tristo voz; in prišel je do Marese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 10, 'Tedaj mu pride Asa nasproti, in pripravijo se na boj v dolini Zefati pri Maresi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 11, 'In Asa vpije h Gospodu, Bogu svojemu, in reče: Gospod, pri tebi ni razločka pomagati, kjer je veliko ali kjer nobene ni moči. Pomagaj nam, o Gospod, Bog naš! zakaj na tebe se opiramo in v tvojem imenu smo prišli zoper to množico. Ti, Gospod, si naš Bog; zoper tebe noben smrtnik ne premore ničesar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 12, 'In Gospod je udaril Etiopce pred Asom in pred Judo; in Etiopci so zbežali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 13, 'Asa pa in ljudstvo, ki je bilo pri njem, jih je zasledovalo do Gerarja, in padlo jih je iz Etiopcev toliko, da se niso mogli okrepiti, kajti strti so bili pred Gospodom in pred njegovo vojsko. In Judovi so odnesli silno veliko plena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 14, 'In udarili so vsa mesta okoli Gerarja, kajti strah Božji jih je obšel; in oplenili so vsa mesta, ker je bilo veliko plena v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 14, 15, 'Vdrli so tudi v ovčje staje in odvedli veliko ovac in velblodov ter so se vrnili v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 1, 'In duh Božji pride nad Azarija, sina Odedovega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 2, 'in pride naproti Asu ter mu reče: Poslušajte me, Asa in ves Juda in Benjamin! Gospod je z vami, dokler ste vi ž njim. In ko ga iščete, ga najdete; ako ga pa zapustite, zapusti on vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 3, 'Saj dosti dni je bil Izrael brez pravega Boga in brez duhovnika-učitelja in brez postave;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 4, 'ali ko so se v stiski svoji obrnili h Gospodu, Bogu Izraelovemu, in ga iskali, so ga našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 5, 'In v tistih časih ni bilo miru njemu, ki je odhajal, ne njemu, ki je prihajal, temuč velika nemirnost je vladala nad vsemi prebivalci dežel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 6, 'In narod se je ljuto bojeval z narodom in mesto z mestom, kajti Bog jih je vznemirjal z vsakovrstno bridkostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 7, 'A vi bodite močni, in naj vam ne omagajo roke! zakaj delo vaše prejme plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 8, 'In ko je slišal Asa te besede in prorokovanje sinu Odedovega, proroka, se ohrabri in odpravi gnusobe iz vse dežele Judove in Benjaminove in iz mest, ki jih je dobil na Efraimskem gorovju, ter obnovi oltar Gospodov, ki je stal pred vežo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 9, 'In skliče ves rod Judov in Benjaminov in tiste, ki so tujčevali pri njih iz Efraima in Manaseja in iz Simeona, kajti veliko jih je iz Izraela bilo prestopilo k njemu, ko so videli, da je bil ž njim Gospod, njegov Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 10, 'In zbero se v Jeruzalemu tretji mesec v petnajstem letu kraljevanja Asovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 11, 'In darovali so Gospodu tisti dan iz plena, ki so ga bili pripeljali, sedemsto volov in sedem tisoč ovac.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 12, 'In so stopili v zavezo, da bodo iskali Gospoda, Boga očetov svojih, iz vsega srca in iz vse duše svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 13, 'ter da mora umreti, kdorkoli bi ne iskal Gospoda, Boga Izraelovega, bodisi majhen ali velik, bodisi mož ali žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 14, 'In prisegli so Gospodu z močnim glasom in z ukanjem ob donenju trobent in rogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 15, 'In ves Juda je bil vesel te prisege, zakaj prisegli so iz vsega srca svojega in iskali Gospoda z vso voljo svojo, ter so ga našli; in Gospod jim je dal pokoj vseokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 16, 'In kralj Asa je tudi odstavil Maako, mater svojo, da ne bo v kraljičji časti, ker je bila naredila ostudno podobo Ašeri. In Asa je posekal njeno ostudno podobo in jo stolkel v prah ter sežgal pri potoku Kidronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 17, 'Toda višave niso bile odpravljene iz Izraela, vendar pa je bilo srce Asovo nerazdeljeno vse njegove žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 18, 'In ponesel je v hišo Božjo, kar je bil posvetil oče njegov in kar je bil sam posvetil, srebro, zlato in posode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 15, 19, 'In vojne ni bilo nobene do petintridesetega leta Asovega vladanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 1, 'V šestintridesetem letu Asovega kraljevanja pride gori Baasa, kralj Izraelov, proti Judi in sezida Ramo, da bi nihče ne mogel hoditi sem ali tja od strani Asa, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 2, 'Tedaj pobere Asa srebro in zlato iz zakladnic hiše Gospodove in hiše kraljeve ter pošlje k Ben-hadadu, kralju sirskemu, ki je prebival v Damasku, in sporoči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 3, 'Zaveza je med menoj in teboj, kakor je bila med mojim in tvojim očetom; glej, pošiljam ti srebra in zlata; pojdi, razderi zavezo svojo z Baasom, kraljem Izraelovim, da se umakne od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 4, 'In Ben-hadad je ugodil kralju Asu in pošlje vojsk svojih poveljnike zoper mesta Izraelova, in udarijo Ijon, Dan in Abel-maim in vsa mesta Neftalijeva, v katerih so bila skladišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 5, 'In ko je Baasa slišal o tem, je nehal zidati Ramo in opustil delo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 6, 'Tedaj vzame Asa vse Judovce in jim veli odnesti od Rame kamenje in les, s katerim je gradil Baasa; in sezidali so s tem Gebo in Micpo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 7, 'In tisti čas pride Hanani, videc, k Asu, kralju Judovemu, in mu reče: Ker si se opiral na kralja sirskega in se nisi zanašal na Gospoda, Boga svojega, zato je sirskega kralja vojna moč ubežala tvoji roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 8, 'Niso li imeli Etiopci in Lubimi velikanske vojske in jako mnogo voz in konjikov? Vendar, ker si se opiral ob Gospoda, ti jih je dal v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 9, 'Zakaj oči Gospodove gledajo po vsej zemlji, da se izkaže močnega pri teh, katerih srce je nerazdeljeno proti njemu. V tem si nespametno storil, kajti poslej boš imel vojne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 10, 'In Asa se razsrdi nad vidcem in ga dene v ječo; kajti jezen je bil nad njim za to reč. In Asa je tisti čas delal silo nekaterim iz ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 11, 'In glej, zgodbe Asove, prve in poslednje, zapisane so v knjigi kraljev Judovih in Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 12, 'V devetintridesetem letu svojega kraljevanja je pa zbolel Asa na nogah, in bolezen njegova je bila silno huda. A tudi v svoji bolezni ni iskal Gospoda, ampak zdravnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 13, 'In legel je Asa k očetom svojim in umrl v štiridesetem in prvem letu kraljevanja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 16, 14, 'In pokopali so ga v njegovem grobu, ki si ga je izsekal v mestu Davidovem, položivši ga na ležišče njegovo, ki je bilo napolnjeno z dišečim kadilom in različnimi dišavami, narejenimi na lekarnarski način; in so zanj napravili silno velik ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 1, 'In zakraljeval je Josafat, sin njegov, na mestu njegovem in se je ojačil zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 2, 'Kajti namestil je vojaštvo po vseh utrjenih mestih Judovih in postavil posadke po deželi Judovi in po mestih Efraimovih, ki jih je bil pridobil Asa, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 3, 'In Gospod je bil z Josafatom, kajti hodil je po prvih potih Davidovih in ni maral za Baale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 4, 'Temuč iskal je Boga očeta svojega, živeč po zapovedih njegovih, in ni delal kakor Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 5, 'Zato je utrdil Gospod kraljestvo v roki njegovi; in ves Juda mu je prinašal darila, in imel je obilo bogastva in časti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 6, 'In ko se mu je srce ohrabrilo na potih Gospodovih, je poslej odpravil višave in Ašere z Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 7, 'In v tretjem letu kraljevanja svojega pošlje poglavarje: Benhaila, Obadija, Zeharija, Netanela in Mikaja, da bi učili v mestih Judovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 8, 'in ž njimi levite: Semaja, Netanija, Zebadija, Asahela, Semiramota, Jonatana, Adonija, Tobija, Tobadonija, levite, in ž njimi Elisama in Jorama, duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 9, 'In učili so po Judovem, imajoč s seboj knjigo zakona Gospodovega, in hodili so okrog po vseh mestih Judovih in učili ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 10, 'In strah od Gospoda je obšel vsa kraljestva dežel, ki so bile okoli Jude, da se niso bojevali zoper Josafata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 11, 'In nekateri Filistejcev so prinašali darila Josafatu in srebro v davek; tudi Arabci so mu pripeljali drobnice, sedem tisoč sedemsto ovnov in sedem tisoč sedemsto kozlov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 12, 'Tako je Josafat rastel in bil čimdalje večji, in sezidal je na Judovem gradove in mesta za skladišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 13, 'In je imel velike priprave v mestih Judovih in vojščake, vrle junake v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 14, 'In to je njih razvrstitev po njih očetovskih družinah: v Judi so bili poveljniki čez tisoč: Adna poveljnik in ž njim je bilo hrabrih junakov tristo tisoč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 15, 'in poleg njega je bil Johanan poveljnik in ž njim jih je bilo dvesto in osemdeset tisoč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 16, 'in poleg njega je bil Amasija, sin Zihrijev, ki se je radovoljno daroval Gospodu, in ž njim je bilo dvesto tisoč vrlih junakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 17, 'V Benjaminu pa: Eliada, hraber junak, in ž njim dvesto tisoč oboroženih z lokom in ščitom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 18, 'in poleg njega je bil Jozabad in ž njim sto in osemdeset tisoč, z orožjem pripravljenih na boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 17, 19, 'Ti so vsi stregli kralju, razen tistih, ki jih je bil kralj namestil v utrjenih mestih po vsem Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 1, 'In Josafat je imel obilo bogastva in časti. In sklenil je svaštvo z Ahabom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 2, 'In po nekoliko letih je šel doli k Ahabu v Samarijo. In Ahab je dal zaklati množino ovac in volov za njega in za ljudstvo, ki je bilo ž njim, in ga je pregovoril, naj gre ž njim v Ramot v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 3, 'Reče namreč Ahab, kralj Izraelov, Josafatu, kralju Judovemu: Pojdeš li z menoj v Ramot v Gileadu? On mu odgovori: Hočem biti kakor ti, ljudstvo moje kakor ljudstvo tvoje, in pojdemo s teboj v boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 4, 'In Josafat reče kralju Izraelovemu: Vprašaj, prosim, danes besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 5, 'Tedaj skliče kralj Izraelov proroke, štiristo mož, in jim reče: Naj li gremo v boj proti Ramotu v Gileadu, ali naj to opustim? Odgovore: Pojdi gori, kajti Bog ga da v roko kraljevo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 6, 'A Josafat reče: Ni li tu sicer nobenega proroka Gospodovega, da bi ga po vprašali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 7, 'In kralj Izraelov reče Josafatu: Še en mož je, po katerem moremo vprašati Gospoda, ali jaz ga sovražim, zakaj ne prorokuje mi nikdar dobrega, ampak vsekdar hudo; ta je Mihaj, sin Imlov. Josafat reče: Ne govóri tako, kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 8, 'Tedaj pokliče kralj Izraelov dvornika in veli: Hitro pripelji sem Mihaja, sina Imlovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 9, 'Kralj Izraelov in Josafat, kralj Judov, pa sta sedela vsak na svojem prestolu, po kraljevsko oblečena. In sedela sta na trgu pri vhodu v vrata Samarije, in vsi proroki so prorokovali pred njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 10, 'In Zedekija, sin Kenaanov, si je naredil železne rogove in je govoril: Tako pravi Gospod: S temi boš bodel Sirce, dokler jih docela ne zatareš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 11, 'In vsi proroki so prorokovali tako in govorili: Pojdi gori v Ramot v Gileadu in srečno hodi, kajti Gospod ga da kralju v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 12, 'Sel pa, ki je šel poklicat Mihaja, mu govori in reče: Glej, besede prorokov oznanjajo soglasno kralju dobro, bodi torej beseda tvoja kakor enega iz njih in govóri dobro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 13, 'In Mihaj reče: Kakor res živi Gospod, kar mi poreče Bog moj, to bom govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 14, 'In ko pride h kralju, ga vpraša kralj: Mihaj, ali naj gremo v boj proti Ramotu v Gileadu ali naj to opustim? Odgovori: Pojdite in srečno hodite! dani vam bodo v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 15, 'Kralj mu pa veli: Kolikokrat naj te zarotim, da mi ne govoriš ničesar nego resnico v imenu Gospodovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 16, 'On reče: Videl sem vsega Izraela razkropljenega po gorah kakor ovce, ki nimajo pastirja; in Gospod je dejal: Ti nimajo gospodarja! Vsak naj se vrne domov v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 17, 'Nato reče kralj Izraelov Josafatu: Ti li nisem rekel, da mi ne bo prorokoval dobrega nego hudo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 18, 'On reče: Zatorej čujte besedo Gospodovo! Videl sem Gospoda sedečega na prestolu svojem in vso vojsko nebeško, da mu stoji ob desnici in ob levici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 19, 'In Gospod je vprašal: Kdo premoti Ahaba, da bi šel gori in padel pri Ramotu v Gileadu? In ta je svetoval in rekel to in drugi je rekel ono.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 20, 'Tedaj pride duh in se postavi pred Gospoda in reče: Jaz ga premotim! In Gospod ga vpraša: S čim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 21, 'Odgovori: Pojdem tja in bodem lažniv duh v ustih vseh prorokov njegovih. In veli: Ti ga premotiš in se ti posreči. Pojdi tja in stóri tako!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 22, 'Sedaj torej, glej, Gospod je dal lažnivega duha v usta vseh teh tvojih prorokov, a Gospod je govoril hudo zoper tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 23, 'Tedaj pristopi Zedekija, sin Kenaanov, in udari Mihaja v lice in reče: Kod je šel duh Gospodov od mene, da s teboj govori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 24, 'Mihaj odvrne: Glej, videl boš tisti dan, ko boš hodil iz hrama v hram, da se skriješ!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 25, 'Kralj Izraelov pa veli: Vzemite Mihaja in ga peljite nazaj k Amonu, mestnemu poglavarju, in k Joasu, sinu kraljevemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 26, 'in recite: Tako pravi kralj: Denita tega moža v ječo in živita ga s kruhom bridkosti in z vodo stiske, dokler se ne vrnem v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 27, 'A Mihaj reče: Ako se vrneš v miru, ni govoril po meni Gospod! Še reče: Slišite, ljudje, vsi iz vas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 28, 'Nato sta šla kralj Izraelov in Josafat, kralj Judov, gori proti Ramotu v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 29, 'In kralj Izraelov reče Josafatu: Jaz pojdem preoblečen v boj, ti pa obleci svoja oblačila! Preobleče se torej kralj Izraelov, in gresta v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 30, 'Kralj sirski pa je zapovedal poveljnikom voz svojih, rekoč: Ne bojujte se zoper malega, ne zoper velikega, temuč zgolj zoper kralja Izraelovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 31, 'Ko torej vidijo poveljniki vozov Josafata, reko: Kralj Izraelov je! In zaženo se bojevat zoper njega; Josafat pa zavpije, in Gospod mu je pomogel in Bog jih je odvedel od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 32, 'Kajti ko so videli poveljniki voz, da ni kralj Izraelov, se obrnejo od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 33, 'Neki mož pa slučajno napne lok in ustreli kralja Izraelovega med stike v oklepu. Zato veli svojemu vozniku: Obrni voz in pelji me z bojišča, kajti hudo sem ranjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 18, 34, 'A bitka se je razvnela tisti dan; toda kralj Izraelov je stal naslonjen na vozu Sircem nasproti do večera, in ko je solnce zahajalo, je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 1, 'Josafat pa, kralj Judov, se je vrnil v miru domov v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 2, 'In Jehu, sin Hananov, videc, mu pride naproti in reče kralju Josafatu: Imaš li ti pomagati brezbožniku in ljubiti tiste, ki sovražijo Gospoda? Zato gre zoper tebe srd izpred Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 3, 'Vendar pa se je našlo nekaj dobrega pri tebi v tem, da si odpravil Ašere iz dežele in pripravil srce svoje, da iščeš Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 4, 'In Josafat je ostal v Jeruzalemu. Potem je zopet šel med ljudstvo, od Bersebe do Efraimskega gorovja, ter jih je izpreobrnil h Gospodu, njih očetov Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 5, 'In postavil je sodnike v deželi po vseh utrjenih mestih Judovih, v vsakem mestu nekaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 6, 'in je velel sodnikom: Glejte, kaj delate! zakaj ne vršite pravde za človeka, temuč za Gospoda, in on je pri vas v sodbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 7, 'Zato bodi strah Gospodov na vas; pazite, kako delate! kajti pri Gospodu, našem Bogu, ni nobene krivice: on ne gleda na zunanjost oseb in ne jemlje darov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 8, 'Tudi v Jeruzalemu je Josafat postavil nekaj levitov in duhovnikov in poglavarjev očetovin Izraelovih, da vrše sodbo Gospodovo in druge pravde. In povrnili so se v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 9, 'In zapove jim, rekoč: Tako ravnajte v strahu Gospodovem, v zvestobi in z nerazdeljenim srcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 10, 'In kadarkoli pride pred vas kaka pravda bratov vaših, ki stanujejo v mestih svojih, med krvjo in krvjo, med zakonom in zapovedjo, med postavami in pravicami, poučujte jih, da se ne okrivičijo proti Gospodu in ne pride srd nad vas in nad brate vaše; to delajte, in ne bodete krivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 19, 11, 'In glejte, Amarija, višji duhovnik, je nad vami v vseh zadevah Gospodovih, in Zebadija, sin Izmaelov, poglavar hiše Judove, v vseh kraljevih zadevah, tudi leviti so kot načelniki pred vami. Srčno pojdite na delo, in Gospod bodi z dobrim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 1, 'In zgodi se potem, da pridejo sinovi Moabovi in sinovi Amonovi in ž njimi nekateri iz Meunimov bojevat se zoper Josafata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 2, 'Pridejo pa in sporoče Josafatu, rekoč: Prihaja velika množica zoper tebe z one strani morja, od Sirije; in glej, že so v Hazazon-tamarju (to je Engedi).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 3, 'In Josafat se zboji in obrne obraz, da bi iskal Gospoda, in razglasi post po vsem Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 4, 'In Juda se zbere, da išče pomoči od Gospoda; prav iz vseh mest Judovih so prišli iskat Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 5, 'In Josafat se postavi v zboru Judovem in Jeruzalemcev, v hiši Gospodovi pred novim dvoriščem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 6, 'in reče: O Gospod, Bog očetov naših, nisi li Bog v nebesih? in nisi li ti vladar vsem kraljestvom narodov? in v roki tvoji je krepkost in moč, da se ti ne more nihče ustavljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 7, 'Nisi li ti, o Bog naš, pregnal prebivalcev te dežele pred ljudstvom svojim Izraelom ter si jo dal semenu Abrahama, prijatelja svojega, na vekomaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 8, 'In prebivali so v njej in zgradili ti v njej svetišče za ime tvoje in dejali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 9, 'Ako pride nad nas nesreča, meč, sodba, ali kuga, ali lakota, postavimo se pred to hišo in pred teboj (kajti v tej hiši je ime tvoje) in bomo vpili k tebi v stiski svoji, in ti boš slišal in pomagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 10, 'In sedaj, glej, sinovi Amonovi in Moabovi in s Seirske gore, med katere nisi dovolil iti Izraelu, ko so šli iz dežele Egiptovske, temuč izognili so se jim ter jih niso pokončali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 11, 'glej, oni nam to povračajo s tem, da so prišli nas podit iz tvoje posesti, ki si jo nam dal v last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 12, 'O Bog naš, jih li ne boš sodil? Zakaj v nas ni moči proti temu velikemu krdelu, ki gre semkaj zoper nas; mi ne vemo, kaj storiti, temuč oči naše gledajo po tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 13, 'In ves Juda je stal pred Gospodom z otročiči svojimi, s svojimi ženami in sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 14, 'Tedaj pride, sredi zbora, na Jahaziela, sina Zeharija, sinu Benaja, sinu Jegiela, sinu Matanija, levita, iz sinov Asafovih, duh Gospodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 15, 'in reče: Poslušajte mene, ves Juda in prebivalci v Jeruzalemu in ti, kralj Josafat! Tako vam pravi Gospod: Ne bojte se, ne plašite se spričo te velike množice, zakaj boj ni vaš, ampak Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 16, 'Jutri pojdite doli proti njim; glejte, gredo sem gori po klancu Zizu, in zalotite jih ob koncu doline, pred Jeruelsko puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 17, 'Vam se ni treba bojevati v tej bitki: razpostavite se in tiho stojte ter glejte rešenje Gospodovo pri sebi, Juda in Jeruzalem! Ne bojte se, ne plašite se; jutri pojdite ven proti njim, Gospod je z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 18, 'Nato se Josafat pripogne z obrazom do tal, in ves Juda in prebivalci jeruzalemski padejo pred Gospodom in molijo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 19, 'Leviti pa izmed sinov Kahatovih in sinov Korahovih vstanejo hvalit Gospoda, Boga Izraelovega, s silno velikim glasom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 20, 'In zjutraj zgodaj vstanejo in gredo ven proti Tekojski puščavi. In ko odhajajo, stoji Josafat in govori: Poslušajte me, Juda in vsi prebivalci jeruzalemski! Verujte v Gospoda, svojega Boga, in varni bodete, verujte prorokom njegovim, in srečo boste imeli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 21, 'In ko se je posvetoval z ljudstvom, postavi pevce, da naj pojo Gospodu in ga hvalijo v diki svetosti, gredoč pred oboroženci in govoreč: Hvalite Gospoda, ker vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 22, 'In ko so začeli peti in hvaliti, je Gospod storil, da je šla zaseda zoper sinove Amonove in Moabove in tiste s Seirske gore, ki so bili prišli proti Judi; in bili so poraženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 23, 'Kajti sinovi Amonovi in Moabovi so se vzdignili zoper prebivalce na Seirski gori, da bi jih docela pokončali in zatrli. In ko so storili konec prebivalcem Seira, pomagali so drug drugemu uničiti sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 24, 'Ko pa pridejo Judovi k stražnemu stolpu ob puščavi, so se ozrli po množici, in glej, tu so ležala mrtva trupla po zemlji, nihče ni ubežal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 25, 'In ko pride Josafat in ljudstvo njegovo pobirat plen, so ga našli veliko množino pri njih, blaga in obleke in dragocenega orodja, in so toliko zase naplenili, da niso mogli nesti. In tri dni so pobirali plen, ker ga je toliko bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 26, 'In četrti dan so se zbrali v Dolini zahvale; ondi so namreč hvalili Gospoda, zato so imenovali ta kraj Dolino zahvale do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 27, 'Potem so se obrnili, vsi možje Judovi in jeruzalemski in njim na čelu Josafat, da se vrnejo v Jeruzalem z veseljem; zakaj Gospod jih je razveselil nad njih sovražniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 28, 'In dospejo v Jeruzalem in stopijo v hišo Gospodovo s psalmovimi strunami in harfami in trobentami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 29, 'In strah Božji je obšel vsa kraljestva po deželah, ko so slišali, da se je Gospod bojeval zoper sovražnike Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 30, 'In kraljevina Josafatova je uživala mir, kajti Bog njegov mu je dal pokoj z vseh strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 31, 'Josafat je torej kraljeval nad Judo; petintrideset let je bil star, ko je zakraljeval, in vladal je petindvajset let v Jeruzalemu. In materi njegovi je bilo ime Azuba, hči Silhijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 32, 'In hodil je po poti Asa, očeta svojega, ni se ganil od nje in je delal, kar je bilo prav v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 33, 'Toda višave niso bile odpravljene, ljudstvo tudi še ni obrnilo srca svojega k Bogu očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 34, 'Druge zgodbe Josafatove pa, prve in poslednje, glej, zapisane so v zgodovini Jehuja, sina Hananovega, ki je sprejeta v knjigo kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 35, 'A potem se je združil Josafat, kralj Judov, z Ahazijem, kraljem Izraelovim; ta je ravnal brezbožno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 36, 'Združil se je pa ž njim, da napravita ladje, ki bi vozile v Tarsis; in zgradila sta ladje v Ezion-geberju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 20, 37, 'Tedaj je prorokoval Eliezer, sin Dodavahov iz Marese, zoper Josafata, govoreč: Ker si se združil z Ahazijem, je razbil Gospod dela tvoja. In razbile so se ladje, da se niso mogli peljati v Tarsis.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 1, 'In Josafat je legel k očetom svojim, in bil je pokopan z očeti svojimi v mestu Davidovem; in Joram, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 2, 'In imel je brate, sinove Josafatove: Azarija, Jehiela, Zeharija, Azarija, Mihaela in Sefatija. Ti vsi so bili sinovi Josafata, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 3, 'In njih oče jim je dal veliko darov od srebra, zlata in dragocenih reči z utrjenimi mesti vred na Judovem. A kraljestvo je dal Joramu, ker je bil prvenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 4, 'Ko pa je Joram zavladal svojega očeta kraljestvu in se ojačil, je pobil vse brate svoje z mečem in nekatere poglavarje Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 5, 'Joram je bil dvaintrideset let star, ko je začel vladati, in kraljeval je osem let v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 6, 'In hodil je po poti kraljev Izraelovih, kakor je delala hiša Ahabova, kajti imel je hčer Ahabovo za ženo; in delal je, kar je bilo hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 7, 'Ali Gospod ni hotel uničiti hiše Davidove zaradi zaveze, ki jo je bil sklenil z Davidom, in ker je obljubil, da dá svetilo njemu in sinovom njegovim vsekdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 8, 'V dneh njegovih so odstopili Edomci izpod oblasti Judove in si postavili zase kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 9, 'Nato je Joram šel tja s poveljniki svojimi in vsi njegovi vozovi ž njim; in vzdignil se je po noči ter pobil Edomce, ki so ga obdajali, in poveljnike voz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 10, 'Vendar so se Edomci upirali oblasti Judovi do tega dne. Potem se je uprla tudi Libna oblasti njegovi v tistem času; zakaj zapustil je bil Gospoda, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 11, 'Tudi je naredil višave po gorah Judovih in zapeljeval prebivalce jeruzalemske, da so nečistovali, in zapeljal je tudi Judo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 12, 'In prišlo mu je pismo od Elija proroka, ki se je glasilo: Tako pravi Gospod, Bog Davida, očeta tvojega: Ker nisi hodil po potih Josafata, očeta svojega, ne po potih Asa, kralja Judovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 13, 'temuč hodiš po poti kraljev Izraelovih in zapeljuješ Judo in prebivalce jeruzalemske v nečistovanje, kakor je hiša Ahabova nečistovala, in si tudi umoril brate svoje iz očeta svojega hiše, ki so bili boljši od tebe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 14, 'glej, zato Gospod udari s hudo šibo ljudstvo tvoje, otroke in žene tvoje in vse blago tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 15, 'ti pa boš veliko trpel od bolezni na črevih, dokler ne pojde drob od tebe vsled tvoje bolezni dan za dnevom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 16, 'In Gospod je obudil zoper Jorama duha Filistejcev in Arabcev, ki prebivajo poleg Etiopcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 17, 'in prišli so gori zoper Judo in so vdrli v deželo in odnesli vse blago, kar ga je bilo v hiši kraljevi, tudi sinove in žene njegove, da mu ni ostalo sina, samo Joahaz, najmlajši sinov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 18, 'In po vsem tem ga je Gospod udaril na njegovih črevih z neozdravljivo boleznijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 19, 'In to je trpelo od dne do dne, in ko je tako minil čas dveh let, so šla od njega čreva vsled bolezni, in umrl je v hudih bolečinah. In ljudstvo njegovo ni zanj napravilo nobenega ognja, kakršnega so priredili očetom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 21, 20, 'Dvaintrideset let je bil star, ko je zakraljeval, in vladal je v Jeruzalemu osem let. In odšel je, ne da bi bili žalovali za njim; in pokopali so ga v mestu Davidovem, a ne v grobih kraljevskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 1, 'In prebivalci jeruzalemski so postavili Ahazija, njegovega najmlajšega sina, za kralja na mestu njegovem; zakaj vse starejše je umorila četa, ki je bila prišla z Arabci v tabor. Tako je zakraljeval Ahazija, sin Jorama, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 2, 'Dvainštirideset let je bil star Ahazija, ko je zavladal, in vladal je eno leto v Jeruzalemu. In materi njegovi je bilo ime Atalija, hči Omrijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 3, 'Tudi on je hodil po potih hiše Ahabove, kajti mati njegova mu je bila svetovalka, da bi ravnal brezbožno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 4, 'Delal je torej, kar je bilo hudo v očeh Gospodovih, kakor je delala hiša Ahabova; zakaj ti so mu bili svetovalci po smrti očeta njegovega, njemu v pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 5, 'On je tudi ravnal po njih svetu, in je šel z Joramom, sinom Ahabovim, kraljem Izraelovim, v boj zoper Hazaela, kralja sirskega, pri Ramotu v Gileadu. In Sirci so ranili Jorama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 6, 'In vrnil se je, da bi mu celili v Jezreelu rane, ki so mu jih vsekali pri Rami, ko se je bojeval zoper Hazaela, kralja sirskega. In Ahazija, sin Jorama, kralja Judovega, je šel doli obiskat Jorama, sina Ahabovega, v Jezreelu, ker je bil bolan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 7, 'To pa je bilo od Boga, v pogubo Ahazijevo, da je šel k Joramu. Zakaj ko je bil dospel, je šel z Joramom naproti Jehuju, sinu Nimsijevemu, ki ga je bil pomazilil Gospod, da iztrebi hišo Ahabovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 8, 'In zgodi se, ko je Jehu izvrševal sodbo na hiši Ahabovi, da zaloti poglavarje Judove in sinove bratov Ahazijevih, ki so stregli Ahaziju, ter jih pomori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 9, 'Iskal je tudi Ahazija, in ujeli so ga (skrival se je namreč v Samariji) in pripeljali k Jehuju, ki ga je umoril; in pokopali so ga, kajti dejali so: On je sin Josafatov, ki je iskal Gospoda iz vsega srca. In ni bilo nikogar več iz hiše Ahazijeve, ki bi imel moč vzdržati kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 10, 'Ko pa je videla Atalija, mati Ahazijeva, da je njen sin mrtev, vstane in pomori vse kraljevo seme hiše Judove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 11, 'Ali Josabata, hči kraljeva, vzame Joasa, sina Ahazijevega, in ga ukrade izmed kraljevih sinov, ki so jih morili, in potisne njega in njegovo pestunjo v spalnico. Tako ga je Josabata, hči kralja Jorama, žena Jojada duhovnika (zakaj bila je sestra Ahazijeva), skrila pred Atalijo, da ni bil umorjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 22, 12, 'In bil je ž njimi skrit v hiši Božji šest let. Atalija pa je gospodovala deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 1, 'V sedmem letu se pa ojunači Jojada in vzame k sebi poveljnike čez sto, Azarija, sina Jerohamovega, in Izmaela, sina Johananovega, in Azarija, sina Obedovega, in Maaseja, sina Adajevega, in Elisafata, sina Zihrijevega, ter sklene ž njimi zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 2, 'Ti gredo okoli po Judovem in zbero levite iz vseh mest Judovih in poglavarje očetovin Izraelovih, in pridejo v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 3, 'In ves ta zbor sklene zavezo s kraljem v hiši Božji. In Jojada jim reče: Glejte, kraljev sin ima kraljevati, kakor je Gospod govoril za sinove Davidove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 4, 'To je reč, ki jo boste storili: tretjina vas duhovnikov in levitov, ki prihajate noter v soboto, bodete na straži med vrati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 5, 'tretjina pa bodi ob hiši kraljevi in tretjina pri temeljnih vratih; in vse ljudstvo bodi na dvoriščih hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 6, 'A nihče naj ne stopi v hišo Gospodovo razen duhovnikov in tistih levitov, ki strežejo: oni smejo iti noter, ker so sveti; ali vse ljudstvo bodi služno na straži Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 7, 'In leviti obkrožijo kralja vseokrog, vsak držeč orožje v roki; in kdor bi stopil v hišo, bodi umorjen; in bodite pri kralju, ko pojde ven in ko pojde noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 8, 'Leviti torej in ves Juda so storili vse, kakor jim je zapovedal Jojada duhovnik: vsak vzame k sebi može svoje, tiste, ki so imeli priti služit v soboto, s tistimi, ki jim je bilo oditi v soboto, zakaj Jojada ni bil odpustil teh oddelkov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 9, 'In Jojada duhovnik izroči poveljnikom nad sto sulice in ščite in orožje kralja Davida, ki je bilo v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 10, 'In razpostavil je vse ljudstvo, vsakega z orožjem v roki, od desne do leve strani hiše, poleg oltarja in poleg hiše, okoli kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 11, 'Nato pripeljejo ven sina kraljevega in denejo krono nanj ter mu dado pričevanje in ga postavijo za kralja, in Jojada in sinovi njegovi ga pomazilijo; in kličejo: Živel kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 12, 'Ko pa je Atalija slišala glas ljudstva, ki je pritekalo in kralja hvalilo, pride k ljudstvu v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 13, 'In pogleda in glej, kralj stoji ob svojem stebru pri vhodu in poveljniki in trobente okoli kralja, in vse ljudstvo dežele se veseli in trobijo na trobente, pevci pojo tudi z glasbenim orodjem hvalospeve. Tedaj si raztrga Atalija oblačila in reče: Zarota, zarota!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 14, 'In Jojada duhovnik gre ven s poveljniki nad sto, ki so bili na čelu vojske, in jim veli: Odpeljite jo ven med vrstami, in kdor bi šel za njo, njega ubijte z mečem! kajti duhovnik je rekel: Ne ubijte je v hiši Gospodovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 15, 'In polože roko nanjo; in šla je skozi vhod Konjskih vrat do kraljeve hiše, in ondi so jo umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 16, 'Tedaj sklene Jojada zavezo med seboj in vsem ljudstvom in kraljem, da bodo ljudstvo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 17, 'In vse ljudstvo je šlo v hišo Baalovo in so jo porušili, oltarje in podobe njegove pa so strli v kosce, in Matana, duhovnika Baalovega, so umorili pred oltarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 18, 'In Jojada je poveril službe hiše Gospodove oblasti duhovnikov levitov, ki jih je porazdelil David v hiši Gospodovi, da darujejo žgalščine Gospodove, kakor je pisano v zakonu Mojzesovem, z veseljem in petjem, po naredbi Davidovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 19, 'In postavil je vratarje pri vratih hiše Gospodove, da ne bi noter šel nihče, ki bi bil kakorkoli nečist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 20, 'In vzame poveljnike nad sto in plemenitnike ter oblastnike v ljudstvu in vse ljudstvo dežele ter pripelje kralja doli iz hiše Gospodove, in pridejo skozi zgornja vrata v hišo kraljevo in posade kralja na kraljestva prestol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 23, 21, 'In vse ljudstvo dežele se je veselilo in mesto je imelo mir. Atalijo pa so bili umorili z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 1, 'Joas je bil sedem let star, ko je zakraljeval, in vladal je štirideset let v Jeruzalemu; in materi njegovi je bilo ime Zibija iz Bersebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 2, 'In Joas je delal, kar je bilo prav v očeh Gospodovih vse dni, dokler je živel Jojada duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 3, 'In Jojada mu je zasnubil dve ženi, in rodil je sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 4, 'In zgodi se potem, da se nameni Joas obnoviti hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 5, 'In skliče duhovnike in levite in jim veli: Pojdite po mestih Judovih in zbirajte denar od vsega Izraela v popravo hiše Boga svojega leto za letom; hitite pa s tem! Ali leviti niso hiteli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 6, 'Tedaj pokliče Joas poglavarja Jojada ter mu reče: Zakaj ne siliš levitov, da bi nosili z Judovega in iz Jeruzalema davek, ki ga je naložil Mojzes, hlapec Gospodov, zboru Izraelovemu za šator pričevanja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 7, 'Kajti tista brezbožnica Atalija in njeni sinovi so razdrapali hišo Božjo in vse, kar je bilo posvečenega hiši Božji, so zapravili za Baale!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 8, 'Kralj torej zapove, in narede skrinjo ter jo postavijo zunaj pri vratih hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 9, 'In objavijo razglas po Judovem in Jeruzalemu, naj se prinaša Gospodu davščina, ki jo je Mojzes, hlapec Gospodov, naložil Izraelu v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 10, 'In veselili so se vsi poglavarji in vse ljudstvo, in prinašali so ter metali v skrinjo, dokler niso dokončali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 11, 'In kadar je prišel čas, da leviti prineso skrinjo kraljevim uradnikom, in ko so videli, da je v njej mnogo denarja, je prišel kraljev pisar in prvega duhovnika uradnik, in sta izpraznila skrinjo; in zopet so jo odnesli na njeno mesto. Tako so delali vsak dan, da so nabrali veliko denarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 12, 'In kralj in Jojada sta ga dajala tistim, ki so vodili delo službe pri hiši Gospodovi, in oni so najemali kamenoseke in tesarje, da obnove hišo Gospodovo, tudi obdelovalce železa in brona, da se popravi hiša Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 13, 'In delavci so pridno delali, da je poprava dobro napredovala po njih rokah, in postavili so hišo Božjo v njen prejšnji stan in jo utrdili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 14, 'In ko so dokončali, so prinesli, kar je bilo ostalo denarja, pred kralja in Jojada; iz tega so se napravile posode za hišo Gospodovo, priprave za službo in darovanje, torila in zlate in srebrne posode. In darovali so žgalne daritve v hiši Gospodovi neprenehoma, dokler je Jojada živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 15, 'A Jojada se je postaral in je, dni svojih sit, umrl; sto in trideset let je bil star, ko je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 16, 'In pokopali so ga v mestu Davidovem med kralji, zato ker je dobro delal Izraelu in proti Bogu in hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 17, 'Po smrti Jojadovi pa pridejo poglavarji Judovi in store poklon kralju. In kralj jim je ugodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 18, 'In zapustili so hišo Gospoda, Boga očetov svojih, in služili Ašeram in malikom. In srd Božji je prišel nad Judo in nad Jeruzalem zavoljo te njih pregrehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 19, 'Pošiljal pa je k njim proroke, da jih izpreobrnejo do Gospoda, in ti so jih svarili, ali niso hoteli poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 20, 'Tedaj obleče duh Božji v moč Zaharija, sina Jojada duhovnika, in se ustopi nad ljudstvom ter jim reče: Tako pravi Bog: Zakaj prestopate zapovedi Gospodove? To vam ne prinese sreče! Ker ste zapustili Gospoda, je tudi on, zapustil vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 21, 'Oni so se pa zarotili zoper njega in ga posuli s kamenjem po kraljevi zapovedi na dvorišču hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 22, 'In Joas kralj se ni spomnil dobrote, ki jo je bil storil oče Jojada njemu, ampak je umoril sina njegovega. Ko je ta umiral, je dejal: Gospod to poglej in kaznuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 23, 'In zgodilo se je ob koncu leta, da je šla gori vojska Sircev zoper njega, in ko so prišli na Judovo in v Jeruzalem, pobijejo vse ljudske vojvode izmed ljudstva in ves njih plen pošljejo kralju v Damask.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 24, 'Dasi je prišla vojska Sircev z maloštevilnim moštvom, je vendar Gospod dal jako veliko vojsko njej v roke, ker so bili zapustili Gospoda, Boga očetov svojih. In tako so Sirci izvršili sodbo nad Joasom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 25, 'In ko so bili odšli od njega – kajti zapustili so ga v velikih bolečinah – so se zarotili zoper njega hlapci njegovi zaradi krvi sinov Jojadovih ter ga umorili na postelji njegovi; in umrl je in so ga pokopali v mestu Davidovem, ali ne v grobih kraljevskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 26, 'In ta sta, ki sta se zarotila zoper njega: Zabad, sin Simeate Amonke, in Jozabad, sin Simrite Moabke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 24, 27, 'O njegovih sinovih pa in o velikosti naloženih mu bremen ter o popravljanju hiše Božje, glej, pisano je v razlagi knjige kraljev. In Amazija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 1, 'Amazija je bil petindvajset let star, ko je zakraljeval, in vladal je devetindvajset let v Jeruzalemu; in materi njegovi je bilo ime Joadana iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 2, 'In delal je, kar je bilo prav v očeh Gospodovih, ali nikar z nerazdeljenim srcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 3, 'In ko mu je bilo kraljestvo utrjeno, je pobil hlapce svoje, ki so bili ubili kralja, očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 4, 'Ali njih otrok ni usmrtil, temuč storil je po tem, kar je pisano v zakonu, v knjigi Mojzesovi, kakor je zapovedal Gospod, rekoč: Očetje naj se ne usmrte za otroke, tudi ne otroci za očete, temuč sleherni umrje za svoj greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 5, 'Amazija je tudi zbral Judo in jih je postavil po očetovskih družinah, po poveljnikih nad tisoč in po poveljnikih nad sto, z vsega Judovega in Benjaminovega; in preštel jih je od dvajsetletnih in više ter jih je našel tristo tisoč izbranih mož, zmožnih iti v vojno, ki so mogli nositi sulico in ščit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 6, 'Vrhutega je najel iz Izraela sto tisoč močnih vojščakov za sto talentov srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 7, 'A mož Božji pride k njemu in reče: O kralj, ne jemlji vojske iz Izraela s seboj; zakaj Gospod ni z Izraelom, ni z vsemi Efraimovimi otroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 8, 'Ampak pojdi sam, delaj, ojači se za boj; Bog te sicer pahne na tla pred sovražnikom, zakaj Bog ima moč i pomagati i poraziti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 9, 'Amazija pa reče možu Božjemu: A kaj je storiti zastran tistih sto talentov, ki sem jih dal četam izraelskim? In mož Božji odgovori: Dosti ima Gospod, da ti da več nego to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 10, 'Nato jih Amazija oddeli, namreč čete, ki so prišle k njemu iz Efraima, naj gredo v svoj kraj. Zato se njih srd silno razvname nad Judo, in povrnejo se domov v silni jezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 11, 'Amazija pa se ohrabri in pelje ven ljudstvo svoje ter gre v Solno dolino in porazi iz sinov Seirovih deset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 12, 'Deset tisoč pa so jih ujeli sinovi Judovi živih ter so jih peljali na vrh skale in pometali s skalnega vrha v globočino, da so se vsi razpočili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 13, 'Ali možje iz čet, ki jih je bil Amazija odslovil, da ne bi šli ž njim v boj, so vdrli v mesta Judova, od Samarije do Bet-horona, in jih pobili tri tisoč ter pobrali mnogo plena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 14, 'Zgodi se pa, ko se je vrnil Amazija s poboja Edomcev, da prinese bogove sinov Seirovih in jih postavi za svoje bogove, in je molil pred njimi ter jim kadil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 15, 'Zato se razvname jeza Gospodova zoper Amazija in pošlje k njemu proroka, ki mu reče: Čemu iščeš tistega ljudstva bogove, ki niso oteli svojega ljudstva iz tvoje roke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 16, 'In ko je govoril k njemu, mu veli kralj: Smo li tebe postavili kralju za svetovalca? Nehaj! čemu hočeš biti ubit? In neha prorok in reče: Vem, da je Bog sklenil te končati, ker si storil to in nisi poslušal sveta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 17, 'Potem se posvetuje Amazija, kralj Judov, in pošlje h kralju Izraelovemu Joasu, sinu Joahaza, sinú Jehujevega, ter sporoči: Pridi, da si pogledava v lice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 18, 'Joas pa, kralj Izraelov, pošlje k Amaziju, kralju Judovemu, in sporoči: Osat, ki je bil na Libanonu, je poslal k cedri libanonski sporočit: Daj svojo hčer sinu mojemu za ženo! V tem je šla mimo divja zver z Libanona in je poteptala osat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 19, 'Ti misliš: Poglej, jaz sem porazil Edomce! in srce tvoje te povzdiguje, da si pridobiš slavo. Ostani doma! Zakaj siliš v nesrečo, da padeš ti in Juda s teboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 20, 'Ali Amazija ni hotel poslušati, kajti od Boga je bilo, da jih izroči njih sovražnikom v pest, zato ker so iskali bogov Edomcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 21, 'Tedaj je šel gori Joas, kralj Izraelov, in pogledala sta si v lice on in Amazija, kralj Judov, v Betsemesu, ki je na Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 22, 'In Juda je izgubil bitko pred Izraelom, in bežal je vsak v šator svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 23, 'In Joas, kralj Izraelov, je ujel Amazija, kralja Judovega, sina Joasa, sinu Joahazovega, v Betsemesu ter ga pripeljal v Jeruzalem, in podrl je zidove jeruzalemske od vrat Efraimovih do Vogelnih vrat, štiristo komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 24, 'In vzel je vse zlato in srebro in vse posode, kar jih je bilo v hiši Božji pri Obededomu, tudi zaklade hiše kraljeve, tudi zastavljence, in vrnil se je v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 25, 'Amazija pa, sin Joasov, kralj Judov, je živel po smrti Joasa, sina Joahaza, kralja Izraelovega, še petnajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 26, 'Druge zgodbe Amazijeve, prve in poslednje, glej, niso li zapisane v knjigi kraljev Judovih in Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 27, 'A potem, odkar je Amazija odstopil od Gospoda, so napravili zaroto zoper njega v Jeruzalemu; on pa je pobegnil v Lahis, in poslali so za njim v Lahis in ga tam usmrtili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 25, 28, 'In prinesli so ga na konjih in ga pokopali z očeti njegovimi v stolnem mestu Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 1, 'In vse ljudstvo Judovo vzame Uzija, ki je bil šestnajst let star, ter ga postavijo za kralja namesto očeta njegovega Amazija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 2, 'On je sezidal Elot, pridobivši ga za Judo, potem ko je bil kralj legel k očetom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 3, 'Šestnajst let star je bil Uzija, ko je zakraljeval, in vladal je dvainpetdeset let v Jeruzalemu; in materi njegovi je bilo ime Jekolija iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 4, 'In delal je, kar je bilo prav v očeh Gospodovih, po vsem, kar je bil delal Amazija, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 5, 'In iskal je Boga v dnevih Zeharija, ki je razumel prikazni Božje; in dokler je iskal Gospoda, mu je Bog dajal srečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 6, 'In šel je in se bojeval zoper Filistejce, in razdrl je obzidje v Gatu in obzidje v Jabni in obzidje v Asdodu, in sezidal je mesta v kraju Asdodskem in med Filistejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 7, 'In Bog mu je pomagal zoper Filistejce in zoper Arabce, ki so prebivali v Gurbaalu, in zoper Meunime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 8, 'In Amonci so dajali darove Uziju; in ime njegovo je zaslovelo povsod, celo v Egiptu; kajti postal je silno mogočen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 9, 'In Uzija je tudi zgradil stolpe v Jeruzalemu na Vogelnih vratih in na Dolinskih vratih in na voglu zidovja ter jih je utrdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 10, 'In sezidal je stolpe v puščavi in izkopal mnogo vodnjakov, kajti imel je veliko živine v nižavi in na planjavi; imel je tudi kmetovalcev in vinogradnikov v gorah in na rodovitnih poljanah, zakaj ljubil je poljedelstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 11, 'Vrhutega je imel Uzija vojsko, pripravno za boj, ki je hodila na vojno po četah, po številu, kakor jih je preštel Jegiel, pisar, in Maaseja, oblastnik, pod roko Hananija, enega kraljevih poveljnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 12, 'Vse število poglavarjev očetovin, hrabrih junakov, je bilo dva tisoč in šeststo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 13, 'In pod njih roko je bila izurjena vojska, trikrat sto tisoč in sedem tisoč in petsto, ki so se bojevali v krepki moči, da pomagajo kralju zoper sovražnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 14, 'In Uzija je oskrbel njim, vsej vojski, ščite in sulice, čelade in oklepe, loke in kamenje za prače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 15, 'Naredil je tudi stroje v Jeruzalemu, iznajdbe umetnikov, da bodo na stolpih in utrdbah, da se ž njimi streljajo pšice in veliki kameni. In ime njegovo je daleč slovelo, ker mu je bilo čudno pomagano, da je postal mogočen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 16, 'Toda ko je postal mogočen, se je prevzelo srce njegovo, njemu v pogubo, in ravnal je nezvesto zoper Gospoda, Boga svojega; kajti šel je v tempelj Gospodov kadit na kadilnem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 17, 'A Azarija duhovnik je šel noter za njim in ž njim osemdeset duhovnikov Gospodovih, junaški možje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 18, 'in so stopili proti Uziju kralju in mu dejali: Tebi se ne spodobi, Uzija, da žgeš kadilo Gospodu, temuč duhovnikom, sinovom Aronovim, ki so posvečeni, da žgo kadilo. Idi ven iz svetišča, zakaj pregrešil si se, in to ti ne bode nikakor v čast pred Gospodom Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 19, 'Tedaj se Uzija razjezi, držeč kadilnico v roki, da bi kadil; in ko izpušča jezo svojo proti duhovnikom, se mu izrinejo gobe po čelu vpričo duhovnikov v hiši Gospodovi, pred kadilnim oltarjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 20, 'In Azarija, prvi duhovnik, in vsi duhovniki se ozro nanj, in glej, gobav je po čelu! Tedaj ga hitro izženo odondod, da, sam je hitel ven, ker ga je udaril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 21, 'In kralj Uzija je bil gobav do dne smrti svoje in prebival je v hiši posebe kot gobavec; zakaj izločen je bil od hiše Gospodove. In Jotam, sin njegov, je bil nad kraljevim dvorom in je sodil ljudstvo dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 22, 'A druga dejanja Uzijeva, prva in poslednja, je zapisal prorok Izaija, sin Amozov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 26, 23, 'In legel je Uzija k očetom svojim, in pokopali so ga na pogrebnem polju, ki je bilo kraljevsko, zakaj dejali so: Gobavec je! In Jotam, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 1, 'Jotam je bil petindvajset let star, ko je zakraljeval, in vladal je šestnajst let v Jeruzalemu; in materi njegovi je bilo ime Jerusa, hči Zadokova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 2, 'In delal je, kar je bilo prav v očeh Gospodovih, po vsem, kar je bil delal Uzija, oče njegov, samo da ni šel v tempelj Gospodov. A ljudstvo je še ravnalo popačeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 3, 'On je sezidal gorenja vrata pri hiši Gospodovi, tudi na zidu Ofelovem je zidal veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 4, 'Dalje je sezidal mesta na Judovem gorovju, in v gozdih je zgradil gradove in stolpe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 5, 'Bojeval se je tudi s kraljem sinov Amonovih in ga je premagal. In sinovi Amonovi so mu tisto leto dali sto talentov srebra in deset tisoč mer pšenice in deset tisoč ječmena. Toliko so mu dali sinovi Amonovi v drugem in v tretjem letu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 6, 'Tako je postal Jotam mogočen, ker je uravnal poti svoji pred Gospodom, svojim Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 7, 'Kar pa je več praviti o Jotamu, o vseh vojskah in vseh potih njegovih, glej, zapisano je v knjigi kraljev Izraelovih in Judovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 8, 'Petindvajset let je bil star, ko je zakraljeval, in vladal je šestnajst let v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 27, 9, 'In legel je Jotam k očetom svojim, in pokopali so ga v mestu Davidovem, in Ahaz, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 1, 'Ahaz je bil dvajset let star, ko je začel vladati, in vladal je šestnajst let v Jeruzalemu; in ni delal, kar bi bilo prav v očeh Gospodovih, kakor David, oče njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 2, 'temuč hodil je po poti kraljev Izraelovih, in je tudi napravil ulite podobe za Baale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 3, 'Vrhutega je žgal kadilo v dolini sina Hinomovega in otroke svoje je peljal kot daritev skozi ogenj, po gnusobah poganov, ki jih je pregnal Gospod izpred sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 4, 'In daroval je in žgal kadilo na višavah in po hribih in pod vsakim zelenim drevesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 5, 'Zato ga je Gospod, njegov Bog, dal v roko kralju Sircev; in porazili so ga ter veliko množico njegovih odpeljali kot ujetnike in jih privedli v Damask. Bil je tudi izdan v roko kralja Izraelovega, ki mu je pripravil velik poraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 6, 'Zakaj Pekah, sin Remalijev, je pobil iz Judovih sto in dvajset tisoč v enem dne, zgolj junaških mož, ker so bili zapustili Gospoda, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 7, 'In Zihri, mogočen mož v Efraimu, je ubil Maaseja, sina kraljevega, in Azrikama, načelnika palače, in Elkana, drugega za kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 8, 'In sinovi Izraelovi so odpeljali ujetih iz bratov svojih dvesto tisoč žen, sinov in hčera, ter so pobrali od njih veliko plena in prinesli plen v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 9, 'Bil je pa tam prorok Gospodov, po imenu Oded; ta pride naproti vojski, ki je prihajala v Samarijo, in jim reče: Glejte, ker se je Gospod, očetov vaših Bog, razsrdil nad Judovimi, jih vam je dal v roko, in vi ste jih tako grozovito pomorili, da sega do neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 10, 'In sedaj še mislite teptati otroke Judove in jeruzalemske, da vam bodo sužnji in sužnice! Niste li pa tudi sami dosti krivi proti Gospodu, Bogu svojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 11, 'Zato me sedaj poslušajte in pošljite nazaj ujetnike, ki ste jih ujeli iz bratov svojih; zakaj srd Gospodov je vzplamtel zoper vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 12, 'Tedaj vstanejo nekateri poglavarji Efraimovih sinov, Azarija, sin Johananov, Berekija, sin Mesimelotov, in Jehizkija, sin Salumov, in Amasa, sin Hadlajev, zoper tiste, ki so prišli iz vojske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 13, 'in jim vele: Ne smete dovesti sem tistih ujetnikov; zakaj da bi spravili nad nas krivdo proti Gospodu, nameravate to, da se pomnože grehi in krivde naše! in naša krivda je že dosti velika, in srd Božji plamti zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 14, 'Nato so oboroženci ostavili ujetnike in plen pred knezi in pred vsem zborom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 15, 'In oni možje, ki so bili po imenu imenovani, se vzdignejo in vzamejo ujetnike v svojo skrb ter ogrnejo gole med njimi z oblačili iz plena, in ko so jih oblekli in obuli ter jim dali jesti in piti in jih pomazilili ter posadili slabe izmed njih na osle, so jih peljali v Jeriho, palmovo mesto, k njih bratom; potem se vrnejo v Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 16, 'Tisti čas pošlje kralj Ahaz h kraljem v Asiriji, da bi mu pomagali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 17, 'Zakaj Edomci so zopet bili prišli in porazili Judo in odpeljali ujetnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 18, 'Filistejci so tudi naskočili mesta v ravnini in na južni strani Judovi ter dobili Betsemes, Ajalon, Gederot, Soko in njemu podložne vasi in Timno s podložnimi vasmi in Gimzo ž njenimi vasmi ter so se v njih nastanili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 19, 'Zakaj Gospod je poniževal Judo zavoljo, Ahaza, kralja Izraelovega, ker je razuzdano ravnal v Judi in se je povsem izneveril Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 20, 'In Tilgat-pilneser, kralj asirski, je prišel k njemu in ga je stiskal, a utrdil ga ni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 21, 'Kajti Ahaz je oropal Gospodovo hišo in kraljevo in hiše poglavarjev ter dal rop kralju asirskemu, a nič mu ni koristilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 22, 'In ob času stiske svoje se je še bolj izneveril Gospodu, on, tisti kralj Ahaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 23, 'Zakaj daroval je bogovom Damaščanov, ki so ga porazili, in je dejal: Ker jim bogovi kraljev asirskih pomagajo, jim hočem darovati, da mi tudi pomagajo. A bili so v pogubo njemu in vsemu Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 24, 'In Ahaz je zbral posode hiše Božje in je razbil posode hiše Božje; in zaprl je duri v hiši Gospodovi ter si je napravil oltarje po vseh kotih v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 25, 'In v vsakem posameznem mestu Judovem je naredil višave, da bi se kadilo drugim bogovom, in dražil v jezo Gospoda, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 26, 'Druge zgodbe njegove pa in vse poti njegove, prve in poslednje, glej, zapisane so v knjigi kraljev Judovih in Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 28, 27, 'In legel je Ahaz k očetom svojim, in pokopali so ga v mestu, v Jeruzalemu, kajti niso ga prinesli v grobe kraljev Izraelovih. In Ezekija, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 1, 'Ezekija je začel vladati v svojem petindvajsetem letu in je vladal devetindvajset let v Jeruzalemu; in materi njegovi je bilo ime Abija, hči Zaharijeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 2, 'In delal je, kar je bilo prav v očeh Gospodovih, po vsem, kar je bil delal David, oče njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 3, 'On je prvo leto vladanja svojega, v prvem mesecu, odprl duri hiše Gospodove ter jih popravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 4, 'In velel je priti duhovnikom in levitom, in ko jih zbere na široki ulici ob vzhodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 5, 'jim reče: Poslušajte me, leviti! Posvetite se zdaj in posvetite hišo Gospoda, Boga očetov svojih, in odpravite nečednost iz svetinje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 6, 'Zakaj očetje naši so se izneverili in delali, kar je hudo v očeh Gospoda, našega Boga, in so ga zapustili; in okrenili so obraz od prebivališča Gospodovega in so mu hrbet obrnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 7, 'Zaklenili so tudi duri do veže in pogasili svetilnice ter niso žgali kadila, ne darovali nobene žgalščine v svetišču Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 8, 'Odtod je prišel srd Gospodov nad Judo in Jeruzalem, in izdal jih je, da jih peste, zatirajo in nad njimi žvižgajo, kakor vidite na svoje oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 9, 'Kajti, glejte, očetje naši so padli po meču in sinovi naši in hčere in žene naše so v ujetništvu zavoljo tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 10, 'Sedaj pa sem se na menil v srcu svojem skleniti zavezo z Gospodom, Bogom Izraelovim, da bi se odvrnila togota jeze njegove od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 11, 'Sinovi moji, ne bodite zdaj leni, zakaj vas je Gospod izvolil, da imate stati v službi pred njim ter da mu bodete strežaji in kadilci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 12, 'Tedaj vstanejo leviti: Mahat, sin Amasajev, in Joel, sin Azarijev, iz sinov Kahatovcev; in izmed sinov Merarijevih Kis, sin Abdijev, in Azarija, sin Jehalelelov, in iz Gersonovcev Joah, sin Zimov, in Eden, sin Joahov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 13, 'in iz sinov Elizafanovih Simri in Jegiel, in iz sinov Asafovih Zeharija in Matanija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 14, 'in iz sinov Hemanovih Jehiel in Simej, in iz sinov Jedutunovih Semaja in Uziel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 15, 'In zbero brate svoje in se posvete ter stopijo noter, kakor je velel kralj po besedah Gospodovih, da očistijo hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 16, 'In duhovniki stopijo v notranji del hiše Gospodove, da bi očiščevali, in izneso vso nesnago, ki se je našla v templju Gospodovem, na dvorišče hiše Gospodove. Leviti pa jo nakladajo in nosijo ven k potoku Kidronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 17, 'Začeli so pa s posvečevanjem prvi dan prvega meseca, in osmi dan meseca so šli v vežo Gospodovo in posvečevali hišo Gospodovo osem dni; in šestnajsti dan prvega meseca so dokončali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 18, 'In stopijo v palačo h kralju Ezekiju in reko: Očistili smo vso hišo Gospodovo in oltar žgalnih daritev z vsemi njegovimi pripravami in mizo razvrščenih kruhov z vsemi posodami njenimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 19, 'Tudi vse posode, ki jih je bil kralj Ahaz, dokler je kraljeval, v zaničevanje spravil v verolomnosti svoji, smo pripravili in posvetili, in glej, pred Gospodovim oltarjem so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 20, 'Tedaj vstane kralj Ezekija zgodaj zjutraj in zbere mestne poglavarje ter gre gori v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 21, 'In prineso sedem juncev in sedem ovnov in sedem jagnjet in sedem kozlov v daritev za greh za kraljestvo in za svetišče in za Judo. In veli duhovnikom, sinovom Aronovim, naj jih darujejo na oltarju Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 22, 'Tedaj zakoljejo goveda, in duhovniki so prejeli kri in kropili ž njo oltar; potem zakoljejo ovne in krope ž njih krvjo oltar; zakoljejo tudi jagnjeta in krope kri na oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 23, 'In pripeljejo kozle daritve za greh pred kralja in zbor, in oni polože roke nanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 24, 'in duhovniki jih zakoljejo in denejo njih kri v daritev za greh na oltar, da se izvrši poravnava za vsega Izraela; kajti za vsega Izraela, je velel kralj, bodi žgalna daritev in daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 25, 'In postavil je levite v hiši Gospodovi s cimbali, s psalmovimi citrami in s harfami po zapovedi Davida in Gada, kraljevega vidca, in Natana proroka; zakaj ta zapoved je bila od Gospoda po prorokih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 26, 'In leviti so stali z glasbili Davidovimi in duhovniki s trobentami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 27, 'In Ezekija ukaže, naj darujejo žgalno daritev na oltarju. In ko se je pričelo darovanje žgalščine, se začne tudi petje Gospodovo in trobentanje vred z glasbili Davida, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 28, 'In ves zbor je molil, in pevci so peli in trobentači so trobili toliko časa, dokler se ni končala žgalna daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 29, 'In ko so končali darovanje, poklekne kralj in vsi, ki so bili pri njem, ter molijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 30, 'In kralj Ezekija in poglavarji so veleli levitom, naj pojo hvalnice Gospodu z besedami Davida in Asafa vidca. In peli so hvalnice z veseljem in pripogibaje se molili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 31, 'Nato izpregovori Ezekija in reče: Sedaj ste se posvetili Gospodu, pristopite in prinesite klalne in zahvalne daritve v hišo Gospodovo! Tedaj prinese zbor klalne in zahvalne daritve, in vsi, kolikor jih je bilo radovoljnega srca, prineso žgalne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 32, 'In število žgalnih daritev, ki jih je prinesel zbor, je bilo sedemdeset goved, sto ovnov in dvesto jagnjet: vse to v žgalno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 33, 'In posvečenih daril je bilo šeststo volov in tri tisoč ovac.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 34, 'Duhovnikov pa je bilo premalo, da niso mogli vseh žgalščin iz kože dejati; zato so jim pomagali njih bratje, leviti, dokler ni bilo delo končano in dokler se niso posvetili duhovniki; kajti leviti so bili bolj pripravnega srca, da se posvetijo, nego duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 35, 'Pa tudi žgalnih žrtev je bilo obilo s tolstino mirovnih daritev vred in s pitnimi darovi za vsako žgalščino. In tako je bila v red spravljena služba hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 29, 36, 'In Ezekija se je veselil z vsem ljudstvom tega, kar je Bog bil pripravil ljudstvu svojemu, zakaj povelje se je hitro izvršilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 1, 'In Ezekija pošlje k vsemu Izraelu in Judi ter napiše liste tudi Efraimu in Manaseju, da bi prišli v hišo Gospodovo v Jeruzalem praznovat pasho Gospodu, Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 2, 'Kajti kralj se je bil posvetoval z vsemi poglavarji in z vsem zborom v Jeruzalemu in sklenil, naj se praznuje pasha v drugem mesecu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 3, 'Niso je namreč mogli praznovati tisti čas, ker se ni posvetilo zadosti duhovnikov, pa ljudstvo se tudi ni bilo zbralo v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 4, 'In stvar se je zdela prava kralju in vsemu zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 5, 'In so ustanovili, da bi se to oklicalo po vsem Izraelu, od Bersebe do Dana, da naj pridejo praznovat pasho Gospodu, Bogu Izraelovemu, v Jeruzalem; zakaj že dolgo časa je niso praznovali tako, kakor je predpisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 6, 'In brzi sli so šli z listi od kralja in njegovih poglavarjev po vsem Izraelovem in Judovem, poročajoč po zapovedi kraljevi takole: Sinovi Izraelovi, preobrnite se h Gospodu, Abrahamovemu, Izakovemu in Izraelovemu Bogu, da se povrne k ostanku vas, ki ste ubežali roki kraljev asirskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 7, 'In ne bodite kakor očetje vaši in kakor bratje vaši, ki so se izneverili Gospodu, očetov svojih Bogu, da jih je izdal opustošenju, kakor vidite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 8, 'Sedaj torej ne bodite trdovratni kakor očetje vaši, temuč podajte roko svojo Gospodu in pridite v njegovo svetišče, ki ga je posvetil za vekomaj, ter služite Gospodu, svojemu Bogu, da se odvrne od vas togota jeze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 9, 'Kajti če se preobrnete h Gospodu, zadobe bratje in otroci vaši usmiljenje pred tistimi, ki so jih zavedli v ujetništvo, in smeli se bodo povrniti v to deželo. Zakaj Gospod, Bog vaš, je usmiljen in milosten ter ne odvrne obličja od vas, ako se k njemu preobrnete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 10, 'In brzoteki so šli od mesta do mesta po deželi Efraimovi in Manasejevi prav do Zebulona; ali smejali so se jim in jih zasmehovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 11, 'Ali vsaj nekateri Aserjevi, Manasejevi in Zebulonovi so se ponižali in prišli v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 12, 'Tudi na Judovem je bila roka Božja, da jim je dal eno srce, da izpolnijo zapoved kralja in knezov po besedi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 13, 'Zbralo se je torej v Jeruzalemu mnogo ljudstva, da bi obhajali praznik opresnikov v drugem mesecu, jako velik zbor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 14, 'In vzdignejo se in razvale oltarje, ki so bili v Jeruzalemu, in odpravijo vse kadilne oltarje ter jih pomečejo v potok Kidron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 15, 'In zakoljejo pasho štirinajsti dan drugega meseca. In duhovniki in leviti so se sramovali ter se posvetili; potem so prinašali daritve v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 16, 'In stali so na svojem mestu po svojem redu, soglasno s postavo Mojzesa, moža Božjega: duhovniki so kropili kri, prejemajoč jo iz rok levitov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 17, 'Kajti bili so v zboru mnogi, ki se niso bili očistili; zato je bilo levitom klati daritve pashe za vse, ki niso bili čisti, da bi jih posvetili Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 18, 'Veliko ljudstva namreč, zlasti mnogi iz Efraima in Manaseja, Isaharja in Zebulona, se niso bili očistili, vendar so jedli velikonočno jagnje, čeprav ne, kakor je pisano. Ali Ezekija je molil zanje, govoreč: Gospod, ki je dobrotljiv, naj odpusti vsakemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 19, 'ki je pripravil srce svoje, da išče Boga, Gospoda, očetov svojih Boga, čeprav ni očiščen po očiščevanju svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 20, 'In Gospod je uslišal Ezekija in je ozdravil ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 21, 'Tako so sinovi Izraelovi, kar jih je bilo v Jeruzalemu, praznovali slavnost opresnikov sedem dni z velikim veseljem; in leviti in duhovniki so hvalili Gospoda vsak dan, pojoč z glasbili v hvalo Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 22, 'In Ezekija je govoril na srce vsem levitom, ki so se izkazali razumne v spoznanju Gospodovem; in uživali so sedem dni, kar je bilo določeno, in darovali mirovne daritve in proslavljali Gospoda, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 23, 'In ves zbor se je posvetoval in sklenil, da bodo praznovali še drugih sedem dni; in praznovali so še sedem dni z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 24, 'Kajti Ezekija, kralj Judov, je podaril zboru tisoč juncev in sedem tisoč glav drobnice; knezi pa so podarili zboru tisoč juncev in deset tisoč glav drobnice. In veliko število duhovnikov se je posvetilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 25, 'In veselil se je ves zbor Judov in duhovniki in leviti, in ves zbor, ki je prišel iz Izraela, tudi tujci, ki so prišli iz dežele Izraelove in ki so prebivali na Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 26, 'In bilo je veliko veselje v Jeruzalemu, kajti od časa Salomona, sina Davidovega, kralja nad Izraelom, ni bilo nič takega v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 30, 27, 'Potem so duhovniki leviti vstali in blagoslovili ljudstvo, in njih glas je bil uslišan in njih molitev je prišla v sveto prebivališče njegovo, v nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 1, 'In ko je bilo vse to opravljeno, so šli vsi Izraelci, ki so bili navzočni, v mesta Judova in so strli poslikane stebre ter posekali Ašere in razvalili višave in oltarje po vsem Judovem in Benjaminovem, tudi po Efraimovem in Manasejevem, da so jih vse zatrli. Tedaj so se vrnili vsi sinovi Izraelovi, vsak na svoj dom, v svoje mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 2, 'Ezekija pa je postavil oddelke duhovnikov in levitov po njih vrstah, vsakega pri službi njegovi, oboje, duhovnike in levite, za darovanje žgalščin in mirovnih daritev, da bi služili in zahvaljevali in hvalili med vrati tabora Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 3, 'In kralj je dal del svojega imetja za žgalščine, da se darujejo zjutraj in zvečer, ob sobotah in mlajih in ob določenih praznikih, kakor je pisano v zakonu Mojzesovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 4, 'Zapovedal je tudi ljudstvu, ki prebiva v Jeruzalemu, naj dajo deleže duhovnikom in levitom, da bi se mogli marljivo pečati s postavo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 5, 'In ko se je to razglasilo, brž so sinovi Izraelovi dali obilo prvin žita, vina, olja in medu in vse poljščine, in prinašali so desetino vsega v obilici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 6, 'In sinovi Izraelovi in Judovi, ki so prebivali v Judovih mestih, so tudi pripeljali desetino goved in drobnice in desetino posvečenih reči, ki so bile posvečene Gospodu, njih Bogu, in so jih pokladali na kupe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 7, 'V tretjem mesecu so začeli skladati kupe in v sedmem mesecu so jih dovršili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 8, 'In Ezekija in knezi so prišli in, videč kupe, so hvalili Gospoda in ljudstvo njegovo, Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 9, 'In Ezekija je vprašal duhovnike in levite o teh kupih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 10, 'In Azarija, prvi duhovnik, iz hiše Zadokove, mu odgovori in reče: Odkar so začeli nositi darila v hišo Gospodovo, smo jedli in dosti imeli in obilo je še ostalo, zakaj Gospod je blagoslovil ljudstvo svoje; in ta velika zaloga je preostala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 11, 'Tedaj Ezekija zapove, naj pripravijo shramb v hiši Gospodovi; in so jih pripravili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 12, 'In vanje denejo zvesto darila in desetine in posvečene reči. In višji nadzornik temu je bil Konanija, levit, in Simej, brat njegov, je bil drugi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 13, 'Jehiel pa in Azazija, Nahat, Asahel, Jerimot, Jozabad, Eliel, Ismahija, Mahat in Benaja so bili nadzorniki pod roko Konanija in Simeja, brata njegovega, po naredbi kralja Ezekija in Azarija, poglavarja hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 14, 'In Kore, sin Jimnov, levit, vratar na vzhodnih vratih, je bil nad prostovoljnimi darovi Bogu, da razdeljuje darila Gospodova in presvete reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 15, 'In pod njim so bili Eden, Miniamin, Jesua, Semaja, Amarija in Sekanija po duhovniških mestih, katerim je bilo poverjeno, da dajo deleže svojim bratom po njih oddelkih, malim enako kakor velikim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 16, '(razen tistih od njih svojcev, triletnih in starejših, ki so bili zapisani v rodopis moških), vsem, ki so hodili v hišo Gospodovo, kakor je zahtevala vsakdanja dolžnost, na službo po svojih opravilih, po svojih oddelkih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 17, 'enako tistim, ki so bili zapisani v rodopis duhovnikov po svojih očetovinah, kakor tudi levitom, dvajsetletnim in starejšim, z ozirom na njih službe, po njih oddelkih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 18, 'in tistim, ki so bili zapisani v rodopise od vseh njih otročičev, njih žen, njih sinov in hčerá, po vsej občini. Kajti v svoji zvestobi so se posvetili, da bodo sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 19, 'Tudi za sinove Aronove, duhovnike, po njivah v okraju njih mest, so bili v vsakem posameznem mestu postavljeni možje, po imenu določeni, da dajo vsakemu moškemu med duhovniki in vsakemu v rodopis zapisanemu levitu deleže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 20, 'In takisto je naredil Ezekija po vsem Judovem. In delal je, kar je bilo dobro in prav in zvesto pred Gospodom, Bogom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 31, 21, 'In vse svoje delo, ki ga je začel v službi hiše Božje in po postavi in zapovedi, da bi iskal svojega Boga, je delal iz vsega srca svojega, in šlo mu je po sreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 1, 'Po teh dogodbah in po tej zvestobi je prišel Senaherib, kralj asirski, in je vdrl na Judovo in oblegal utrjena mesta, da bi jih pograbil zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 2, 'In ko vidi Ezekija, da je prišel Senaherib ter da se je namenil bojevati zoper Jeruzalem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 3, 'se posvetuje s svojimi knezi in oblastniki, da bi zamašili studence, ki so bili zunaj mesta; in oni so mu pomagali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 4, 'Zbere se torej veliko ljudi in zamaše vse studence in potok, ki teče po sredi dežele, rekoč: Čemu naj najdejo kralji asirski veliko vode, kadar pridejo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 5, 'In Ezekija se ohrabri in popravi vse zidovje, ki je bilo luknjasto, ter zgradi stolpe na njem in še drugi zid odzunaj in utrdi Milo v mestu Davidovem in napravi veliko orožja in ščitov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 6, 'In postavi vojne poveljnike nad ljudstvom in jih zbere k sebi v široko ulico ob mestnih vratih ter jim govori na srce takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 7, 'Bodite močni in srčni, ne bojte se in ne plašite se pred asirskim kraljem, ne pred vso to množico, ki je pri njem! Zakaj večji je z nami nego ž njim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 8, 'ž njim je mesena roka, z nami pa je Gospod, naš Bog, da nam pomaga in za nas vodi boj. In ljudstvo se je zaneslo na besede Ezekija, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 9, 'Potem pošlje Senaherib, kralj asirski, hlapce svoje v Jeruzalem (stal pa je pred Lahisom in vsa vojna moč njegova ž njim) k Ezekiju, kralju Judovemu, in k vsem Judovim, ki so bili v Jeruzalemu, in sporoči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 10, 'Tako pravi Senaherib, kralj asirski: Na koga stavite upanje, da sedite v obleganem Jeruzalemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 11, 'Vas li ne zapeljuje Ezekija, da vas izda v smrt z lakoto in žejo, govoreč: Gospod, Bog naš, nas otme iz roke kralja asirskega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 12, 'Ni li on tisti Ezekija, ki je odpravil njegove višave in oltarje in velel Judi in Jeruzalemu: Pred edinim oltarjem molite in na njem žgite kadilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 13, 'Ne veste li, kaj sem storil jaz in očetje moji vsem narodom po deželah? So li mar bili bogovi narodov po deželah kaj zmožni, da bi oteli deželo svojo iz moje roke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 14, 'Kateri je med vsemi bogovi tistih narodov, ki so jih pokončali očetje moji, ki je mogel oteti ljudstvo svoje iz moje roke, da bi vaš Bog vas mogel oteti iz moje roke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 15, 'Naj vas torej sedaj ne prekani Ezekija, tudi se mu ne dajte pregovoriti in ne verujte mu! Zakaj ako ni mogel noben bog kateregakoli naroda ali kraljestva oteti ljudstva svojega iz moje in mojih očetov roke, kako bi li vas otel vaš Bog iz roke moje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 16, 'In še več so govorili hlapci njegovi zoper Gospoda Boga in zoper hlapca njegovega Ezekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 17, 'Tudi liste je pisal, da bi kidal sramoto na Gospoda, Izraelovega Boga, in zoper njega govoril, češ, kakor bogovi narodov po deželah niso svojega ljudstva oteli iz roke moje, tako tudi ne otme Ezekijev Bog iz moje roke ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 18, 'In glasno so vpili po judovsko proti ljudstvu iz Jeruzalema, ki je bilo na obzidju, da ga spravijo v strah in obup, da bi tako dobili mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 19, 'In govorili so o Bogu Jeruzalema kakor o bogovih ljudstev po deželah, ki so človeških rok delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 20, 'Kralj Ezekija pa in prorok Izaija, sin Amozov, sta spričo tega molila in vpila v nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 21, 'In Gospod je poslal angela, ki je pobil vse močne junake in vojvode in poveljnike v taboru kralja asirskega, da se je z očitno sramoto vrnil v deželo svojo. In ko je prišel v svojega boga hišo, sta ga ondi z mečem umorila, ki sta bila po rodu njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 22, 'Tako je Gospod rešil Ezekija in prebivalce v Jeruzalemu roke Senaheriba, kralja asirskega, in roke vseh drugih in jih je vodil, da so bili varni z vseh strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 23, 'In mnogi so prinašali darila Gospodu v Jeruzalem in dragocenosti Ezekiju, kralju Judovemu, tako da se je odslej povišal pred očmi vseh narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 24, 'V tistih dneh zboli Ezekija na smrt. Tedaj je molil h Gospodu, in on mu je govoril ter mu dal čudno znamenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 25, 'Ali Ezekija ni povrnil dobrote, ki mu je bila dana. Zakaj njegovo srce se je prevzelo, in zato je prišel srd nad njega in nad Judo in Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 26, 'Ko pa se je Ezekija ponižal zato, ker se je bilo prevzelo srce njegovo, s prebivalci jeruzalemskimi vred, ni prišel srd Gospodov nadnje v dnevih Ezekijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 27, 'In Ezekija je imel silno veliko bogastva in časti in si je oskrbel zakladnice za srebro in za zlato, za drage kamene in za dišave, za ščite in za vsakovrstno dragoceno orodje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 28, 'Imel je tudi skladišča za pridelke žita, vina in olja, in hleve za vsakovrstno živino in tamare za drobnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 29, 'Napravil si je tudi mesta in imel je veliko drobnice in govedi, kajti Bog mu je dal silno veliko imetja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 30, 'On, Ezekija, je tudi bil tisti, ki je zamašil gorenji iztok Gihonske vode ter jo napeljal naravnost doli po zahodni strani mesta Davidovega. In Ezekija je imel srečo v vseh svojih podjetjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 31, 'Toda ko so bili k njemu poslani vojvod babilonskih poslanci, da bi vprašali po čudnem znamenju, ki se je bilo zgodilo v deželi, ga je Bog zapustil, da ga je izkusil, da bi spoznal vse, kar je bilo v srcu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 32, 'A druge zgodbe Ezekijeve in njegova pobožna dela, glej, zapisana so v prikazni Izaija proroka, sinu Amozovega, v knjigi kraljev Judovih in Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 32, 33, 'In Ezekija je legel k očetom svojim, in pokopali so ga ob stopnicah, ki vodijo gori h grobovom sinov Davidovih; in ves Juda in prebivalci jeruzalemski so mu izkazali čast ob njegovi smrti. In Manase, sin njegov, je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 1, 'Manase je bil dvanajst let star, ko je zakraljeval, in vladal je petinpetdeset let v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 2, 'In delal je, kar je bilo hudo v očeh Gospodovih, po gnusobah poganov, ki jih je bil Gospod pregnal pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 3, 'Kajti zgradil je zopet višave, ki jih je razvalil oče njegov Ezekija, in postavil je oltarje Baalom in napravil Ašere in molil vso vojsko nebeško ter jim je služil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 4, 'Zgradil je tudi oltarje v hiši Gospodovi, za katero je bil rekel Gospod: V Jeruzalemu bode ime moje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 5, 'In sezidal je oltarje vsej vojski nebeški na obeh dvoriščih pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 6, 'Peljal je tudi otroke svoje skozi ogenj v dolini sinu Hinomovega; in pečal se je s tolmačenjem znamenj in z vražami in s čarovništvom in podpiral zaklinjalce duhov in vedeževalce; delal je mnogo hudega v očeh Gospoda, da bi ga dražil v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 7, 'In postavil je izrezano podobo malika, ki ga je bil naredil, v hišo Božjo, za katero je rekel Bog Davidu in Salomonu, sinu njegovemu: V tej hiši in v Jeruzalemu, ki sem ga izvolil izmed vseh rodov Izraelovih, postavim ime svoje na vekomaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 8, 'tudi ne dopustim več, da bi se noga Izraelova genila ven iz dežele, ki sem jo določil očetom vašim, samo če bodo pazili, da delajo vse, kar sem jim zapovedal, ves zakon in postave in sodbe, po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 9, 'A Manase je v blodnjo vodil Judo in prebivalce Jeruzalema, da so delali hudo bolj nego narodi, katere je Gospod pokončal pred sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 10, 'In Gospod je govoril Manaseju in ljudstvu njegovemu, a niso poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 11, 'Zato je Gospod pripeljal nadnje poveljnike vojski kralja asirskega, ki so ujeli Manaseja v spone, ga zvezali z dvema bronastima verigama in odvedli v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 12, 'In ko je bil v bridkosti, je prosil blagovoljnosti Gospoda, Boga svojega, in se silno ponižal pred Bogom očetov svojih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 13, 'in molil k njemu. In dal se mu je izprositi ter uslišal prošnjo njegovo in ga zopet privedel v Jeruzalem v kraljestvo njegovo. Tedaj je spoznal Manase, da Gospod je Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 14, 'Potem je zidal zunanje zidovje ob mestu Davidovem, na zahodni strani Gihona, pri potoku, prav do vhoda v Ribja vrata, in je obkrožil z zidom Ofel ter ga napravil jako visokega in postavil mogočne poveljnike po vseh utrjenih mestih Judovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 15, 'Odstranil je tudi tuje bogove in odpravil malika iz hiše Gospodove in vse oltarje, ki jih je bil zgradil na gori hiše Gospodove in v Jeruzalemu, in jih pometal ven iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 16, 'In pripravil je oltar Gospodov ter daroval na njem mirovne in zahvalne daritve in zapovedal Judi, naj služijo Gospodu, Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 17, 'Vendar pa je ljudstvo še darovalo po višavah, dasi le Gospodu, Bogu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 18, 'Druge zgodbe Manasejeve pa in molitev njegova k njegovemu Bogu in besede vidcev, ki so mu govorili v imenu Gospodovem, glej, zapisane so med zgodbami kraljev Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 19, 'Molitev njegova in kako se mu je dal Bog izprositi in ves greh njegov in njegovo verolomstvo in mesta, na katerih je zgradil višave in postavil Ašere in izrezane podobe, preden se je ponižal: glej, zapisano je v zgodovini Hozajevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 20, 'In legel je Manase k očetom svojim, in pokopali so ga v hiši njegovi; in sin njegov Amon je zakraljeval na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 21, 'Amon je bil dvaindvajset let star, ko je zakraljeval, in vladal je dve leti v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 22, 'In delal je, kar je bilo hudo v očeh Gospodovih, kakor je bil delal Manase, oče njegov; daroval je namreč vsem izrezanim podobam, ki jih je bil naredil oče njegov, ter jim služil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 23, 'A ni se ponižal pred Gospodom, kakor se je bil ponižal njegov oče Manase, temuč je kopičil krivdo za krivdo nadse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 24, 'In hlapci njegovi so se zarotili zoper njega in ga usmrtili v hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 33, 25, 'Ljudstvo dežele pa je pobilo vse tiste, ki so se bili zarotili zoper kralja Amona; in ljudstvo dežele je postavilo Josija, sina njegovega, za kralja na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 1, 'Josija je bil osem let star, ko je zakraljeval, in vladal je enointrideset let v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 2, 'In delal je, kar je bilo prav v očeh Gospodovih, in hodil po potih Davida, očeta svojega, in se ni ganil ne na desno, ne na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 3, 'V osmem letu namreč kraljevanja svojega, ko je bil še deček, je začel iskati Boga očeta svojega Davida, in v dvanajstem letu je začel očiščevati Judo in Jeruzalem višav in Ašer ter izrezanih in ulitih podob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 4, 'In podrli so oltarje Baalov vpričo njega in solnčne stebre, ki so bili vrhu njih, je posekal, Ašere pa in izrezane in ulite podobe je strl ter jih zdrobil v prah in prah raztresel po grobovih tistih, ki so jim bili darovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 5, 'In kosti duhovnikov je sežgal na njih oltarjih, in tako je očistil Judo in Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 6, 'Tudi v mestih Manasejevih in Efraimovih in Simeonovih, prav do Neftalija, vse okrog po njih razvalinah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 7, 'je porušil oltarje ter razbil v prah Ašere in izrezane podobe in posekal solnčne stebre po vsej deželi Izraelovi, in se je vrnil v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 8, 'V osemnajstem letu kraljevanja svojega pa, ko je bil očistil deželo in hišo, pošlje Safana, sina Azaljevega, in Maaseja, mestnega poglavarja, in Joaha, sina Joahazovega, deželnega letopisca, da bi popravili hišo Gospoda, njegovega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 9, 'Ti pridejo k Hilkiju, velikemu duhovniku, ter izroče denar, kar se ga je prineslo v hišo Božjo, ki so ga bili nabrali leviti, varuhi ob vratih, od Manaseja in Efraima in od vsega ostanka Izraelovega in od vseh Judovih in Benjaminovih in od prebivalcev jeruzalemskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 10, 'In ga izroče delovodjem, ki so nadzorovali v hiši Gospodovi, in ti ga dado delavcem, ki so delali v hiši Gospodovi, da se popravi in izboljša hiša;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 11, 'dado ga tesarjem in stavbarjem, da nakupijo obsekanega kamenja in lesa za veznike ter napravijo tramov za hiše, ki so jih bili skazili kralji Judovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 12, 'In tisti možje so zvesto opravljali delo. In njih nadzorniki so bili: Jahat in Obadija, levita, iz sinov Merarijevih, Zeharija in Mesulam pa iz sinov Kahatovcev, da bodo na čelu; in drugi leviti, ki so vsi znali peti ob glasbilih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 13, 'so bili tudi nad bremenarji in na čelu vsem, ki so se trudili v katerikoli službi; in drugi leviti so bili pisarji, uradniki in vratarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 14, 'Ko so pa jemali ven denar, ki je bil prinešen v hišo Gospodovo, je našel duhovnik Hilkija knjigo postave Gospodove, dane po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 15, 'In Hilkija izpregovori ter reče Safanu, pisarju: Našel sem knjigo postave v hiši Gospodovi. In Hilkija izroči knjigo Safanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 16, 'Safan pa prinese knjigo h kralju in razen tega sporoči kralju, rekoč: Hlapci tvoji delajo vse, kar je bilo njih rokam poverjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 17, 'In izsuli so denar, ki je bil zbran v hiši Gospodovi, in so ga oddali v roke nadzornikom in delovodjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 18, 'Še pove Safan, pisar, kralju, rekoč: Knjigo mi je dal duhovnik Hilkija. In Safan jo je čital pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 19, 'Ko pa kralj sliši besede postave, raztrga oblačila svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 20, 'In kralj zapove Hilkiju in Ahikamu, sinu Safanovemu, in Abdonu, sinu Mihovemu, in pisarju Safanu in Asaju, kraljevemu hlapcu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 21, 'Pojdite, vprašajte Gospoda zame in za tiste, ki so preostali v Izraelu in Judi, o besedah te knjige, ki se je našla; zakaj velik je srd Gospodov, ki se je zgrnil na nas, kajti naši očetje niso pazili na besedo Gospodovo, da bi delali po vsem, kar je pisano v tej knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 22, 'Tedaj so šli Hilkija in tisti, ki jim je kralj velel, k Huldi prorokinji, ženi Saluma, sinu Tokhata, sinu Hasrahovega, varuha oblačilnice (ona pa je stanovala v Jeruzalemu, v drugem delu mesta), in so govorili ž njo po tem povelju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 23, 'Ona jim pa reče: Tako pravi Gospod, Bog Izraelov: Povejte možu, ki vas je poslal k meni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 24, 'Tako pravi Gospod: Glej, jaz pripravim nesrečo nad ta kraj in nad prebivalce njegove, namreč vse kletve, ki so zapisane v knjigi, iz katere so čitali pred kraljem Judovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 25, 'ker so me zapustili in so žgali kadilo drugim bogovom, da bi me dražili v jezo z vsem delom svojih rok; zato se je zgrnil srd moj nad tem krajem in ne bo ugasnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 26, 'Kralju Judovemu pa, ki vas je poslal vprašat Gospoda, tako mu recite: Tako pravi Gospod, Bog Izraelov, zastran besed, ki si jih slišal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 27, 'Ker se je omečilo srce tvoje in si se ponižal pred Bogom, ko si čul besede njegove zoper ta kraj in zoper njegove prebivalce, in si se ponižal pred menoj in si raztrgal oblačila svoja in jokal pred mano: zato sem tudi tebe slišal, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 28, 'Glej, zberem te k očetom tvojim, in boš v miru zbran v grob svoj, da ne bodo oči tvoje videle vse nesreče, ki jo spravim nad ta kraj in nad prebivalce njegove. In sporočili so ta govor kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 29, 'Nato pošlje kralj in zbere k sebi vse starejšine Judove in jeruzalemske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 30, 'In kralj gre gori v hišo Gospodovo in vsi možje Judovi in prebivalci jeruzalemski in duhovniki in leviti in vse ljudstvo, veliki in mali; in čita, da vsi slišijo, vse besede knjige zaveze, ki se je našla v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 31, 'In kralj se ustopi na svojem mestu in stori zavezo pred Gospodom, da bo hodil za Gospodom in pazil na zapovedi njegove in pričevanja in postave njegove iz vsega srca svojega in iz vse duše svoje, da izpolni besede zaveze, ki so pisane v tej knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 32, 'In velel je vsem, ki so bili v Jeruzalemu in po Benjaminovem, pristopiti k tej zavezi. In prebivalci jeruzalemski so storili po zavezi Božji, Boga očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 34, 33, 'In Josija je odpravil vse gnusobe iz pokrajin, ki so bile sinov Izraelovih, in je priganjal vse, ki so bivali v Izraelu, da služijo Gospodu, svojemu Bogu. Vse njegove dni niso odstopili od Gospoda, očetov svojih Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 1, 'In Josija je praznoval pasho Gospodu v Jeruzalemu, in zaklali so velikonočno jagnje štirinajsti dan prvega meseca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 2, 'In postavil je duhovnike na njih straže ter jih ohrabril za službo hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 3, 'In dejal je levitom, ki so učili vsega Izraela, ki so bili sveti Gospodu: Denite sveto skrinjo v hišo, ki jo je zgradil Salomon, sin Davidov, kralj Izraelov! Ni vam več v breme na rami, zato služite sedaj Gospodu, Bogu svojemu, in ljudstvu njegovemu, Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 4, 'In pripravite se po svojih očetovskih hišah, po svojih oddelkih, kakor je predpisal David, kralj Izraelov, in kakor je predpisal Salomon, sin njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 5, 'In stojte v svetišču po vrstah očetovskih hiš bratov svojih, sinov naroda, in sicer vsakikrat en oddelek očetovske hiše levitov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 6, 'In zakoljite pasho in posvetite se in pripravite jo za brate svoje, da storite po besedi Gospodovi, dani po Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 7, 'In Josija je podaril sinom naroda drobnice, jagnjet in kozličev, trideset tisoč po številu, vse za daritve pashe vsem, ki so bili pričujoči, in tri tisoč goved; to je bilo od imetja kraljevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 8, 'Njegovi knezi pa so podarili radovoljno ljudstvu, duhovnikom in levitom. Hilkija in Zeharija in Jehiel, poglavarji hiše Božje, so dali duhovnikom za daritve pashe dva tisoč in šeststo glav drobnice in tristo goved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 9, 'Konanija pa, Semaja in Netanel, njegova brata, in Hasabija in Jegiel in Jozabad, prvaki levitov, so podarili levitom za daritve pashe pet tisoč glav drobnice in petsto goved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 10, 'In tako je bila služba pripravljena, in duhovniki so stali na mestu svojem, tudi leviti po svojih oddelkih, kakor je bil kralj ukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 11, 'In zaklali so pasho in duhovniki so škropili kri, prejemajoč jo iz njih roke, in leviti so devali daritve iz kože.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 12, 'In denejo vstran žgalne daritve, da bi jih porazdelili vrstam očetovskih hiš, sinovom naroda, da jih darujejo Gospodu, kakor je pisano v knjigi Mojzesovi. In enako store tudi z govedjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 13, 'In pekli so pasho na ognju po predpisu; kar pa je bilo posvečeno, so kuhali v loncih, v kotlih in v ponvah, in hitro to delili vsem sinovom naroda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 14, 'In potem so pripravili za sebe in za duhovnike; kajti duhovniki, sinovi Aronovi, so imeli opravek z darovanjem žgalščin in tolstine do noči, zato so leviti pripravili zase in za duhovnike, sinove Aronove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 15, 'In pevci, sinovi Asafovi, so bili na svojem mestu, po zapovedi Davida in Asafa, Hemana in Jedutuna, kraljevega vidca, in vratarji so bili pri vseh vratih, ni jim bilo treba odhajati od svoje službe, ker so njih bratje, leviti, pripravili zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 16, 'Tako je bila tisti dan pripravljena vsa služba Gospodu, da se praznuje pasha ter da se darujejo žgalne daritve na oltarju Gospodovem, po zapovedi kralja Josija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 17, 'In praznovali so tisti čas sinovi Izraelovi, ki so bili navzočni, pasho in praznik opresnikov sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 18, 'In ni se praznovala pasha v Izraelu enaka tej od dni Samuela proroka, tudi noben kraljev Izraelovih ni priredil take pashe, kakor jo je Josija praznoval z duhovniki vred in z leviti in z vsemi Judovimi in z Izraelci, ki so bili pričujoči, in s prebivalci jeruzalemskimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 19, 'V osemnajstem letu kraljevanja Josijevega se je praznovala ta pasha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 20, 'Po vsem tem, ko je bil kralj Josija spravil v red tempelj, pride gori Neko, kralj egiptovski, da bi se bojeval zoper Karkemiš pri Evfratu; in Josija mu pride nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 21, 'On pa mu pošlje poslance in sporoči: Kaj imam s teboj, kralj Judov? Ne grem zoper tebe ta dan, ampak zoper hišo, ki je v boju z menoj, in Bog mi je velel, da naj hitim. Nehaj se vtikati v boj z Bogom, ki je z menoj, da te ne pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 22, 'A Josija ni hotel odvrniti obraza od njega, temuč preoblekel se je, da bi se bojeval ž njim, in ni poslušal besed Nekovih iz Božjih ust, pa je šel bojevat se na ravnini pri Megidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 23, 'In strelci so ustrelili kralja Josija, in kralj je velel hlapcem svojim: Peljite me stran, kajti hudo sem ranjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 24, 'Hlapci njegovi ga torej preneso z voza in ga polože na drugi voz, ki ga je imel, ter ga pripeljejo v Jeruzalem; in umrl je, in bil je pokopan v grobovih očetov svojih. In ves Juda in Jeruzalem je žaloval po Josiju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 25, 'In Jeremija je spesnil žalostinko za Josija, in vsi pevci in pevke so govorili o Josiju v svojih žalostinkah do tega dne, in vpeljali so jih v navado v Izraelu. In glej, zapisane so v žalostinkah Jeremijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 26, 'Kar je pa več praviti o Josiju, in njegova pobožna dela po vsem, kar je pisano v zakonu Gospodovem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 35, 27, 'in dejanja njegova, prva in poslednja, glej, zapisana so v knjigi kraljev Izraelovih in Judovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 1, 'Tedaj vzame ljudstvo dežele Joahaza, sina Josijevega, in ga postavijo za kralja na mestu očeta njegovega v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 2, 'Joahaz je bil triindvajset let star, ko je zakraljeval, in vladal je tri mesece v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 3, 'A kralj egiptovski ga je odstavil v Jeruzalemu in naložil deželi globo: sto talentov srebra in talent zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 4, 'In kralj egiptovski je postavil Eljakima, brata njegovega, za kralja nad Judo in Jeruzalemom in mu premenil ime v Jojakima. Joahaza pa, brata njegovega, je Neko vzel in odpeljal v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 5, 'Jojakim je bil petindvajset let star, ko je zakraljeval, in vladal je enajst let v Jeruzalemu in delal, kar je bilo hudo v očeh Gospoda, Boga njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 6, 'Zoper njega je prišel Nebukadnezar, kralj babilonski, in ga zvezal z dvema bronastima verigama, da bi ga peljal v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 7, 'Nebukadnezar je prinesel tudi nekaj posod iz hiše Gospodove v Babilon in jih je del v svoj tempelj v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 8, 'Kar je pa več praviti o Jojakimu, in gnusobe njegove, ki jih je počenjal, in kar se je našlo pri njem, glej, zapisano je v knjigi kraljev Izraelovih in Judovih. In Jojahin, sin njegov, je zavladal na mestu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 9, 'Jojahin je bil osemnajst let star, ko je zakraljeval, in vladal je tri mesece in deset dni v Jeruzalemu; in delal je, kar je bilo hudo v očeh Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 10, 'Ko je pa to leto minilo, pošlje Nebukadnezar ter ga veli peljati v Babilon z dragocenimi posodami iz hiše Gospodove vred, in postavi Zedekija, brata njegovega, za kralja nad Judo in Jeruzalemom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 11, 'Zedekija je bil enoindvajset let star, ko je zakraljeval, in vladal je enajst let v Jeruzalemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 12, 'in delal je, kar je bilo hudo v očeh Gospoda, njegovega Boga, in se ni ponižal pred prorokom Jeremijem, ko mu je govoril iz ust Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 13, 'On se je tudi izneveril kralju Nebukadnezarju, ki ga je bil zavezal s prisego pri Bogu. In otrdil je zatilnik svoj in zakrknil svoje srce, da ne bi se preobrnil h Gospodu, Bogu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 14, 'Vrhutega so vsi poglavarji duhovnikov in ljudstvo jako množili verolomnost, delajoč po vseh gnusobah poganov, in onečistili so hišo Gospodovo, ki jo je bil posvetil v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 15, 'In Jehova, Bog njih očetov, jih je opominjal po svojih poslancih, od ranega jutra in neprenehoma, ker se mu je smililo ljudstvo njegovo in prebivališče njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 16, 'A oni so zasmehovali poslance Božje in zaničevali besede njegove in za norce imeli njegove proroke, dokler ni zrasla jeza Gospodova nad ljudstvom njegovim, da ni bilo več lečitve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 17, 'Zato je pripeljal nadnje kralja Kaldejcev, ki so pomorili njih mlado moštvo z mečem v hiši njih svetinje in niso prizanesli mladeniču, ne devici, ne starcu, ne sivolascu; vse jih je izdal njemu v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 18, 'In vse posode hiše Božje, velike in male, in zaklade hiše Božje in zaklade kralja in knezov njegovih, vse te je odpeljal v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 19, 'In sežgali so z ognjem hišo Božjo in porušili zidovje jeruzalemsko in požgali vse palače v njem in uničili vse dragocene posode v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 20, 'In kar jih je preostalo po meču, so odvedli ujete v Babilon, in bili so hlapci njemu in sinovom njegovim, dokler ni zavladalo kraljestvo perzijsko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 21, 'da bi se dopolnila beseda Gospodova po ustih Jeremijevih, „dokler se ne bo dežela naužila sobot svojih“. Dokler je ležala pusta, je uživala soboto, da se je izpolnilo sedemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 22, 'V prvem letu pa Cira, kralja Perzije, da bi se dopolnila beseda Gospodova po ustih Jeremijevih, je Gospod obudil duha Cira, kralja Perzije, da je velel proglasiti po vsej kraljevini svoji, pa tudi pismeno naznaniti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (14, 36, 23, 'Tako pravi Cir, kralj Perzije: Vsa kraljestva zemlje mi je dal Gospod, Bog nebes, in mi je naročil zgraditi mu hišo v Jeruzalemu, ki je na Judovem. Kdorkoli torej je med vami iz vsega ljudstva njegovega, s tem bodi Gospod, njegov Bog, in pojdi tja gori!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 1, 'V prvem letu Cira, kralja v Perziji, je Gospod, da bi se dopolnila beseda Gospodova, govorjena po ustih Jeremijevih, obudil duha Cira, kralja v Perziji, da je dal razglasiti po vsej kraljevini svoji, pa tudi pismeno naznaniti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 2, 'Tako pravi Cir, kralj Perzije: Vsa kraljestva zemlje mi je dal Gospod, Bog nebes, in mi je naročil, naj mu zgradim hišo v Jeruzalemu, ki je na Judovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 3, 'Kdor je med vami iz vsega ljudstva njegovega, s tem bodi njegov Bog, in pojdi gori v Jeruzalem na Judovem in zidaj hišo Gospoda, Boga Izraelovega (on je Bog!), ki je v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 4, 'Vsakemu torej, ki je preostal na kateremkoli mestu, kjer biva kot tujec, naj mu pomagajo ljudje tega kraja s srebrom in zlatom, z blagom in z živino, razen tega, kar dobrovoljno darujejo za hišo Božjo, ki je v Jeruzalemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 5, 'Nato se vzdignejo prvaki očetovin Judovih in Benjaminovih ter duhovniki in leviti, vsi, katerih duha je bil obudil Bog, da pojdejo gori gradit hišo Gospodovo, ki je v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 6, 'In vsi, ki so bili okoli njih, so jim podpirali roke s srebrnimi potrebščinami, z zlatom, z blagom, z živino in z dragotinami, razen vsega, kar so dali dobrovoljno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 7, 'Cir pa je velel prinesti ven posode hiše Gospodove, ki jih je bil Nebukadnezar pripeljal iz Jeruzalema ter jih je dejal v svojega boga hišo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 8, 'te je dal Cir, kralj Perzije, prinesti po Mitredatu, zakladničarju, in jih je odštel Sesbazarju, vojvodu Judovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 9, 'In to je njih število: trideset zlatih skled, tisoč srebrnih skled, devetindvajset nožev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 10, 'trideset zlatih čaš, srebrnih čaš druge vrste štiristo in deset in drugih posod tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 1, 11, 'Vseh zlatih in srebrnih posod je bilo pet tisoč in štiristo. Te vse je prinesel Sesbazar s seboj, ko so šli iz ujetništva v Babilonu gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 1, 'Ti pa so sinovi pokrajine Judove, kateri so šli iz sužnosti tistih, ki so bili odpeljani v ujetništvo, ki jih je bil Nebukadnezar, kralj babilonski, ujete odpeljal v Babilon in ki so se zopet vrnili v Jeruzalem in na Judovo, vsak v svoje mesto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 2, 'ki so prišli z Zerubabelom, Jesuom, Nehemijem, Serajem, Reelajem, Mardohejem, Bilsanom, Misparjem, Bigvajem, Rehumom, Baanom. Število mož iz ljudstva Izraelovega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 3, 'Sinovi Paroševi: dva tisoč sto dvainsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 4, 'Sinovi Sefatijevi: tristo dvainsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 5, 'Sinovi Arahovi: sedemsto petinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 6, 'Sinovi Pahat-moabovi, iz otrok Jesua in Joaba: dva tisoč osemsto in dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 7, 'Sinovi Elamovi: tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 8, 'Sinovi Zatujevi: devetsto petinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 9, 'Sinovi Zakajevi: sedemsto in šestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 10, 'Sinovi Banijevi: šeststo dvainštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 11, 'Sinovi Bebajevi: šeststo triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 12, 'Sinovi Azgadovi: tisoč dvesto in dvaindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 13, 'Sinovi Adonikamovi: šeststo šestinšestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 14, 'Sinovi Bigvajevi: dva tisoč šestinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 15, 'Sinovi Adinovi: štiristo štiriinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 16, 'sinovi Aterjevi, od Hezekija: osemindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 17, 'Sinovi Bezajevi: tristo in triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 18, 'Sinovi Jorovi: sto in dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 19, 'Sinovi Hasumovi: dvesto triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 20, 'Sinovi Gibarjevi: petindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 21, 'Sinovi Betlehemovi: sto triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 22, 'Možje iz Netofe: šestinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 23, 'Možje iz Anatota: sto osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 24, 'Sinovi iz Azmaveta: dvainštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 25, 'Sinovi iz Kirjat-arima, Kefire in Beerota, sedemsto triinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 26, 'Sinovi iz Rame in Gebe: Šeststo in edenindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 27, 'Možje iz Mikmasa: sto dvaindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 28, 'Možje iz Betela in Aja: dvesto triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 29, 'Sinovi Nebovi: dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 30, 'Sinovi Magbiševi: sto šestinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 31, 'Sinovi drugega Elama: tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 32, 'Sinovi Harimovi: tristo in dvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 33, 'Sinovi Loda, Hadida in Ona: sedemsto petindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 34, 'Možje iz Jeriha: tristo petinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 35, 'Sinovi od Senaa: tri tisoč šeststo in trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 36, 'Duhovniki: Sinovi Jedaja, iz hiše Jesuove: devetsto triinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 37, 'Sinovi Imerjevi: tisoč dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 38, 'Sinovi Pashurja: tisoč dvesto sedeminštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 39, 'Sinovi Harima: tisoč in sedemnajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 40, 'Leviti: Sinovi Jesua in Kadmiela, od sinov Hodavijevih: štiriinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 41, 'Pevci, sinovi Asafovi: sto osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 42, 'Sinovi vratarjev: sinovi Saluma, sinovi Aterja, sinovi Talmona, sinovi Akuba, sinovi Hatita, sinovi Sobaja, skupaj sto devetintrideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 43, 'Netinimci: Sinovi Zihovi, sinovi Hasufovi, sinovi Tabaotovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 44, 'sinovi Kerosovi, sinovi Siahovi, sinovi Padonovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 45, 'sinovi Lebanovi, sinovi Hagabajevi, sinovi Akubovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 46, 'sinovi Hagabovi, sinovi Samlajevi, sinovi Hananovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 47, 'sinovi Gidelovi, sinovi Gaharjevi, sinovi Reajevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 48, 'sinovi Rezinovi, sinovi Nekodovi, sinovi Gazamovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 49, 'sinovi Uzovi, sinovi Paseahovi, sinovi Besajevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 50, 'sinovi Asnovi, sinovi Meunimov, sinovi Nefisimov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 51, 'sinovi Bakbukovi, sinovi Hakufovi, sinovi Harhurjevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 52, 'sinovi Bazlutovi, sinovi Mehidovi, sinovi Harsajevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 53, 'sinovi Barkosovi, sinovi Siserjevi, sinovi Tamahovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 54, 'sinovi Neziahovi, sinovi Hatifovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 55, 'Sinovi hlapcev Salomonovih: sinovi Sotajevi, sinovi Soferetovi, sinovi Perudovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 56, 'sinovi Jaalovi, sinovi Darkonovi, sinovi Gidelovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 57, 'sinovi Sefatijevi, sinovi Hatilovi, sinovi Pohereta iz Hazebaima, sinovi Amijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 58, 'Vseh Netinimcev in sinov hlapcev Salomonovih je bilo tristo dvaindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 59, 'In ti so tudi šli gori iz Telmelaha, Telharsa, Keruba, Adana, Imerja, ali niso mogli izkazati svojih očetov hiše in svoje rodovine, da so iz Izraela:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 60, 'sinovi Delajevi, sinovi Tobijevi, sinovi Nekodovi: šeststo dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 61, 'In iz sinov duhovnikov: sinovi Habajevi, sinovi Hakozovi, sinovi Barzilaja, ki si je vzel ženo iz hčera Barzilaja Gileadčana in je bil po njih imenu imenovan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 62, 'Ti so iskali svojega rodu imenik, pa ga niso našli, zato so jih šteli za nečiste za duhovništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 63, 'In Tirsata jim je rekel, da naj ne jedo od najsvetejšega, dokler ne vstane duhovnik z Urimom in Tumimom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 64, 'Ves zbor je štel dvainštirideset tisoč tristo in šestdeset,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 65, 'brez njih hlapcev in dekel, katerih je bilo sedem tisoč tristo sedemintrideset; imeli so tudi dvesto pevcev in pevk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 66, 'Njih konj je bilo sedemsto šestintrideset, njih mezgov dvesto in petinštirideset,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 67, 'njih velblodov štiristo in petintrideset, oslov pa šest tisoč sedemsto in dvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 68, 'In nekateri poglavarji očetovin, ko so prišli k hiši Gospodovi, ki je v Jeruzalemu, so dali prostovoljnih daril za zgradbo hiše na mestu njenem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 69, 'po premožnosti svoji so dali v stavbni zaklad: edeninšestdeset tisoč darikov in pet tisoč min srebra in sto duhovniških oblačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 2, 70, 'In nastanili so se duhovniki in leviti in kar jih je bilo iz ljudstva in pevci in vratarji in Netinimci v mestih svojih in ves Izrael po mestih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 1, 'In ko se je približal sedmi mesec in so že bili sinovi Izraelovi v svojih mestih, tedaj se zbere ljudstvo kakor en mož v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 2, 'Tedaj vstane Jesua, sin Jozadakov, in bratje njegovi, duhovniki, in Zerubabel, sin Sealtielov, in bratje njegovi, in zgrade oltar Boga Izraelovega, da se darujejo na njem žgalne daritve, kakor je pisano v postavi Mojzesa, moža Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 3, 'In postavili so oltar na njegovi podstavi, kajti strah jih je bilo zaradi ljudstev sosednjih dežel; in darovali so na njem žgalne daritve Gospodu, žgalne daritve zjutraj in zvečer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 4, 'In praznovali so praznik šatorov, kakor je predpisano, in darovali žgalščine vsak dan po številu, soglasno s predpisom, kakor je bilo vsak dan obvezno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 5, 'In potem stalno žgalno daritev in daritve ob mlajih in ob vseh določenih praznikih Gospodovih, ki so bili posvečeni, in daritve vsakega, ki je Gospodu prinesel prostovoljno darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 6, 'Prvi dan sedmega meseca so začeli darovati žgalščine Gospodu, ko še ni bila položena podstava templju Gospodovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 7, 'In dali so denarja kamenosekom in tesarjem in živeža, pijače in olja tistim iz Sidona in iz Tira, da bi privažali cedrov les z Libanona na morje v Jafo, kakor jih je pooblastil Cir, kralj Perzije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 8, 'In v drugem letu po njih prihodu k hiši Božji v Jeruzalem, v drugem mesecu, so začeli Zerubabel, sin Sealtielov, in Jesua, sin Jozadakov, in ostali njih bratje, duhovniki in leviti, in vsi, ki so bili prišli iz ujetništva v Jeruzalem, in so postavili levite, dvajsetletne in starejše, da nadzorujejo delo hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 9, 'Tedaj so stali, kakor en mož, Jesua s sinovi in z brati svojimi, Kadmiel in sinovi njegovi, sinovi Hodavijevi, da bi nadzorovali delavce pri hiši Božji, tudi sinovi Henadadovi s svojimi sinovi in brati, leviti, vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 10, 'In ko so stavbarji pokladali podstavo templju Gospodovemu, so postavili duhovnike v njih oblačilih s trobentami in levite, sinove Asafove, s cimbali, da hvalijo Gospoda po naredbi Davida, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 11, 'In odpevali so drugi drugim, hvaleč in zahvaljujoč Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova nad Izraelom. In vse ljudstvo je zagnalo radostno ukanje ob hvali Gospodovi, ker je položil temelj hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 12, 'A mnogi iz duhovnikov in levitov in poglavarjev očetovskih družin, stari možje, ki so bili videli prejšnjo hišo, so glasno jokali, ko se je pokladal temelj tej hiši pred njih očmi; mnogi so pa glasno vriskali od veselja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 3, 13, 'tako da ljudstvo ni moglo razločiti veselega vriskanja od glasnega jokanja med ljudstvom, zakaj ljudstvo je vriskalo z močnim glasom, in glas se je daleč razlegal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 1, 'Ko so pa slišali nasprotniki Judovi in Benjaminovi, da grade sinovi ujetništva tempelj Gospodu, Bogu Izraelovemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 2, 'pristopijo k Zerubabelu in k poglavarjem očetovin in jim reko: Naj zidamo z vami, kajti mi iščemo vašega Boga prav tako kot vi. Ali mu ne darujemo od časa Esar-hadona, kralja asirskega, ki nas je pripeljal sem gori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 3, 'Toda Zerubabel in Jesua in drugi poglavarji Izraelovih očetovin jim reko: Ne spodobi se vam, da z nami zidate hišo našemu Bogu, temuč mi sami hočemo zidati Gospodu, Bogu Izraelovemu, kakor nam je zapovedal kralj Cir, kralj Perzije!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 4, 'Tedaj je ljudstvo dežele slabilo roke ljudstvu Judovemu ter jih s strašenjem motilo pri zidanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 5, 'In najemali so svetnike zoper nje, da podkopljejo njih namero, vse dni Cira, kralja perzijskega, do kraljevanja Darija, kralja Perzije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 6, 'In ob vladanju Ahasvera, v začetku njegovega kraljevanja, so tožbo pisali zoper prebivalce na Judovem in v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 7, 'In v dnevih Artakserksa so pisali Bislam, Mitredat, Tabeel in drugi njegovi tovariši Artakserksu, kralju v Perziji. In pisava pisma je bila sirska in po sirsko se je bralo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 8, 'Rehum, deželni poglavar, in Simsaj, pisar, sta napisala pismo zoper Jeruzalem kralju Artakserksu takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 9, '(Takrat so pisali Rehum, deželni poglavar, in Simsaj, pisar, in drugi njih tovariši, Dinaji, Afarsatkaji, Tarpelaji, Afarsaji, Arkovci, Babilonci, Susančani, Dehaji, Elamljani');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 10, 'in drugi tistih narodov, ki jih je veliki in presvetli Oznapar sem pripeljal in jih naselil v mestih Samarije in v ostali deželi na tej strani reke Evfrata, in tako dalje.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 11, 'To je prepis lista, ki so ga poslali Artakserksu kralju: Tvoji hlapci, možje tostran reke, in tako dalje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 12, 'Znano bodi kralju, da so Judje, ki so prišli gori od tebe, dospeli k nam v Jeruzalem; oni zidajo tisto uporno in hudobno mesto in izpolnjujejo obzidje ter popravljajo podstave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 13, 'Znano torej bodi kralju: ako bode to mesto dozidano in obzidje dovršeno, ne bodo dajali davkov, ne užitnine, ne cestnine, in to naposled oškoduje kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 14, 'Zatorej, ker jemo sol palače, ne smemo gledati škode kraljeve, pa pošiljamo h kralju in mu to poročamo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 15, 'naj se poišče v spominski knjigi očetov tvojih; in najdeš v knjigi spominov in izveš, da je to mesto uporno mesto in škodljivo kraljem in deželam ter da so se v njem snovale vstaje od starodavna; zategadelj je tudi bilo to mesto porušeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 16, 'Zagotavljamo kralja, ako se to mesto dozida in obzidje dovrši, da ne boš vsled tega imel nobene posesti tostran reke. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 17, 'Nato pošlje kralj odgovor Rehumu, deželnemu poglavarju, in Simsaju, pisarju, in drugim njih tovarišem, ki prebivajo v Samariji in drugih krajih tostran reke: Mir! in tako dalje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 18, 'List, ki ste ga nam poslali, se je umljivo bral pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 19, 'In velel sem, naj se preišče, in našlo se je, da je tisto mesto rovalo zoper kralje od starodavna ter da so upore in vstaje snovali v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 20, 'In bili so tudi mogočni kralji v Jeruzalemu, ki so gospodovali vsej deželi onostran reke, ki jim je bilo dajati davke, užitnino in cestnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 21, 'Izdajte torej povelje, da se zabrani tistim možem in da se to mesto ne bo zidalo, dokler ne izide moje povelje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 22, 'In glejte, da ne storite v tem pomote; čemu naj raste škoda, da bodo kralji na izgubi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 23, 'ko se je opis lista kralja Artakserksa prečital pred Rehumom in Simsajem, pisarjem, in pred njih tovariši, so hitro šli gori v Jeruzalem k Judom in so jim branili z močno pestjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 4, 24, 'Takrat je nehalo delo pri hiši Božji, ki je v Jeruzalemu, in bilo je ustavljeno do drugega leta vlade Darija, kralja Perzije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 1, 'Prorokovala sta pa Hagaj, prorok, in Zaharija, sin Idov, proroka, Judom, ki so bili na Judovem in v Jeruzalemu; v imenu Boga Izraelovega sta jim prorokovala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 2, 'Tedaj vstane Zerubabel, sin Sealtielov, in Jesua, sin Jozadakov, ter začneta zidati hišo Božjo, ki je v Jeruzalemu, in ž njima proroka Božja, ki sta ju podpirala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 3, 'V istem času pride k njim Tatenaj, deželski oblastnik tostran reke, in Setar-bozenaj in njiju tovariši ter jim reko takole: Kdo vam je ukazal zidati to hišo in dokončati to obzidje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 4, 'Nato smo jim povedali, katera so imena mož, ki so se lotili zidanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 5, 'A oko njih Boga je bilo obrnjeno v starejšine Judov, da se jim ni branilo, dokler se ni stvar sporočila Dariju in se je potem odposlal pismen odgovor o tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 6, 'To pa je opis lista, ki so ga poslali Tatenaj, deželski oblastnik tostran reke, in Setar-bozenaj in njegovi tovariši Afarsakaji, ki so bili tostran reke, kralju Dariju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 7, 'Poslali so mu poročilo, v katerem je bilo pisano takole: Kralju Dariju ves mir!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 8, 'Znano bodi kralju, da smo šli v pokrajino Judovo, k hiši velikega Boga, ki jo grade z velikimi kameni in ji brune pokladajo v stene, in delo to, ker so marljivi, je uspešno v njih rokah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 9, 'Tedaj smo vprašali tiste starejšine in jim rekli takole: Kdo vam je ukazal zidati to hišo in dokončati to obzidje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 10, 'Vprašali smo jih tudi za njih imena, da tebi oznanimo, da bi zapisali imena mož, ki jim načelujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 11, 'Oni pa so nam dali tak odgovor, rekoč: Mi smo hlapci Boga nebes in zemlje ter zidamo hišo, ki je bila prej zgrajena pred mnogimi leti, ki jo je velik kralj Izraelov zidal in dokončal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 12, 'A potem, ko so očetje naši dražili v jezo Boga nebes, jih je dal v roko Nebukadnezarja, kralja babilonskega, Kaldejca, ki je podrl to hišo in ljudstvo odpeljal v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 13, 'Toda v prvem letu Cira, kralja babilonskega, je kralj Cir izdal povelje, da naj se zida ta hiša Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 14, 'Tudi zlate in srebrne posode hiše Božje, ki jih je bil vzel Nebukadnezar iz templja v Jeruzalemu in jih prinesel v tempelj v Babilonu, je vzel kralj Cir iz templja v Babilonu in jih izročil tistemu, po imenu Sesbazarju, ki ga je postavil za oblastnika v deželi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 15, 'in mu je velel: Vzemi te posode, pojdi, deni jih v tempelj, ki je v Jeruzalemu, in naj se hiša Božja gradi na mestu njenem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 16, 'Takrat je prišel tisti Sesbazar in je položil podstave hiši Božji, ki je v Jeruzalemu, in od tega časa do sedaj jo zidajo, in ni še dokončana. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 5, 17, 'Sedaj torej, ako se vzvidi kralju, naj poiščejo v kraljevi hiši, v zakladnici, ki je tam v Babilonu, če je tako, da je izdal kralj Cir povelje zidati to hišo Božjo v Jeruzalemu, in naj nam kralj sporoči svojo voljo za to stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 1, 'Nato ukaže kralj Darij, naj poiščejo v pismarnici v hiši, kjer so bili zloženi zakladi v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 2, 'In našli so v Ahmeti, na gradu, ki je v pokrajini Medijski, zavitek, in v njem je bilo takole pisano v spomin:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 3, 'V prvem letu kralja Cira, je izdal kralj Cir povelje: Zastran hiše Božje v Jeruzalemu: Ta hiša naj se zida kot kraj, kjer se darujejo daritve. Njene podstave naj se trdno postavijo; višava njena bodi šestdeset komolcev, širjava njena šestdeset komolcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 4, 'tri lege imej štirivoglatih kamenov in eno lego iz novega lesa. In stroški naj se plačajo iz kraljeve hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 5, 'Tudi zlate in srebrne posode hiše Božje, ki jih je vzel Nebukadnezar iz templja v Jeruzalemu ter prinesel v Babilon, naj se povrnejo in zopet prineso na svoje mesto v tempelj v Jeruzalemu, in naj jih zlože v hiši Božji. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 6, 'Sedaj torej, Tatenaj, deželni oblastnik za reko, Setar-bozenaj in vajini tovariši Afarsakaji, ki ste za reko, umeknite se daleč od njih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 7, 'Pustite jim delati pri tej hiši Božji; naj poglavar Judov in starejšine Judov grade to hišo Božjo na mestu njenem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 8, 'Vrhutega sem izdal povelje, kako naj pomagate tistim starejšinam Judov pri stavbi te hiše Božje, namreč, da se iz kraljevega imetja, iz davkov onostran reke, plačujejo stroški z vso natančnostjo tem možem, da jim ne bode ovire.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 9, 'In kar potrebujejo, telet, ovnov in jagnjet v žgalne daritve Bogu nebes, pšenice, soli, vina in olja, po zahtevi duhovnikov v Jeruzalemu, naj se jim daje dan za dnevom neprestano,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 10, 'da morejo darovati daritve v prijetno dišavo Bogu nebes in da molijo za kraljevo in za sinov njegovih življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 11, 'Tudi sem izdal povelje: Vsakemu, ki premeni ta ukaz, naj vzamejo gredo iz hiše njegove in jo pokonci postavijo ter ga na njej obesijo, njegova hiša pa bodi v kup gnoja zavoljo tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 12, 'A Bog, ki je storil, da bi ondi prebivalo ime njegovo, razdeni vse kralje in ljudstva, ki bodo iztegnili roko svojo, da premene ta ukaz, da se poruši ta hiša Božja v Jeruzalemu. Jaz, Darij, sem izdal povelje; naj se natančno izvrši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 13, 'Tedaj so storili Tatenej, deželni oblastnik za reko, Setar-bozenaj in njiju tovariši natančno tako, za kar je bil kralj Darij sporočil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 14, 'In starejšine Judovi so zidali in uspevalo jim je delo po prorokovanju Hagaja, proroka, in Zaharija, sinu Idovega. Tako so zidali in dokončali po zapovedi Boga Izraelovega in po povelju Cira in Darija in Artakserksa, kraljev v Perziji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 15, 'In ta hiša je bila dokončana tretji dan meseca Adarja, ko je bilo šesto leto vladanja kralja Darija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 16, 'In sinovi Izraelovi, duhovniki, leviti in drugi sinovi ujetništva so praznovali posvečevanje te hiše Božje z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 17, 'In prinesli so ob posvečevanju te hiše Božje sto juncev, dvesto ovnov, štiristo jagnjet; in v daritev za greh za vsega Izraela dvanajst kozlov, po številu rodov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 18, 'In postavili so duhovnike po njih vrstah in levite po njih oddelkih v službo Bogu, ki je v Jeruzalemu, kakor je pisano v knjigi Mojzesovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 19, 'In sinovi ujetništva so praznovali pasho štirinajsti dan prvega meseca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 20, 'Zakaj duhovniki in leviti so se očistili kakor en mož; bili so vsi čisti. In zaklali so pasho za vse sinove ujetništva in za brate svoje, duhovnike, in zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 21, 'In sinovi Izraelovi, ki so se bili vrnili iz ujetništva, in vsi, ki so se ločili od nečistote poganov v deželi in k njim pristopili, da bi iskali Gospoda, Boga Izraelovega, so jedli');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 6, 22, 'in so praznovali praznik opresnikov sedem dni z veseljem; zakaj Gospod jim je bil dal veselje in jim je naklonil srce kralja asirskega, da bi jim okrepčal roke na delu pri hiši Boga, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 1, 'A po teh zgodbah, ob vladanju Artakserksa, kralja v Perziji, je šel Ezra, sin Seraja, sinu Azarija, sinu Hilkija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 2, 'sinu Saluma, sinu Zadoka, sinu Ahituba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 3, 'sinu Amarija, sinu Azarija, sinu Merajota,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 4, 'sinu Zerahija, sinu Uzija, sinu Bukija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 5, 'sinu Abisua, sinu Pinehasa, sinu Eleazarja, sinu Arona, prvega duhovnika –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 6, 'ta Ezra je šel gori iz Babilona. Ta je bil Pismouk, izurjen v zakonu Mojzesovem, ki ga je bil dal Gospod, Bog Izraelov. In ker je bila roka Gospoda, Boga njegovega, nad njim, mu je dal kralj vse, kar je prosil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 7, 'In ž njim je šlo nekaj sinov Izraelovih in duhovnikov in levitov in pevcev in vratarjev in Netinimcev gori v Jeruzalem, v sedmem letu kralja Artakserksa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 8, 'In dospel je v Jeruzalem v petem mesecu, ko je bilo sedmo leto kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 9, 'Zakaj prvi dan prvega meseca je bil določen odhod iz Babilona, prvi dan petega meseca pa je dospel v Jeruzalem, kjer je bila dobrotljiva roka Boga njegovega nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 10, 'Zakaj Ezra je pripravil srce svoje, da bo preiskoval zakon Gospodov in ga izpolnjeval ter da bo učil v Izraelu postave in sodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 11, 'To pa je prepis lista, ki ga je dal kralj Artakserks duhovniku in pismouku Ezru, pismouku v besedah zapovedi Gospodovih in njegovih postav za Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 12, 'Artakserks, kralj kraljev, Ezru duhovniku, popolnemu pismouku zakona Boga nebes, in tako dalje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 13, 'Izdajem ukaz, da naj pojdejo s teboj vsi od ljudstva Izraelovega in njih duhovnikov in levitov v državi moji, ki hočejo rade volje iti v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 14, 'Ker si poslan od kralja in od njegovih sedmih svetovalcev, da napraviš preiskavo o Judi in Jeruzalemu na podlagi zakona Boga svojega, ki je v roki tvoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 15, 'in da odneseš tja srebro in zlato, ki so ga kralj in svetniki njegovi radovoljno darovali Bogu Izraelovemu, čigar prebivališče je v Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 16, 'in vse srebro in zlato, ki ga dobiš v vsej pokrajini Babilonski, s tem vred, kar bo ljudstvo in duhovništvo prostovoljno darovalo za hišo Boga svojega, ki je v Jeruzalemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 17, 'zato nakupi z vso marljivostjo s temle denarjem govedi, ovnov, jagnjet in njim pristojnih jedilnih in pitnih daril ter jih daruj na oltarju v hiši Boga vašega, ki je v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 18, 'In kar se tebi in bratom tvojim vzvidi storiti z ostalim srebrom in zlatom, storíte po volji Boga svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 19, 'In posode, ki so ti dane za službo v hiši Boga tvojega, oddaj pošteno pred Bogom v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 20, 'In karkoli bo še potrebno za hišo Boga tvojega, kar se ti naključi izdati, daj iz kraljeve zakladnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 21, 'In jaz, kralj Artakserks, ukazujem vsem zakladnikom, ki so za reko, storite z vso marljivostjo, karkoli vas bo prosil Ezra duhovnik, pismouk v zakonu Boga nebes;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 22, 'dajte do sto talentov srebra in do sto meric pšenice in do sto batov vina in sto batov olja in soli brez mere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 23, 'Karkoli je zapovedano po Bogu nebes, naj se natančno stori za hišo Boga nebes, kajti čemu naj pride srd božji nad državo kraljevo in njegovih sinov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 24, 'Tudi se vam naznanja, da nimate oblasti, nakladati davke, užitnino in cestnino kateremukoli iz duhovnikov, levitov, pevcev, vratarjev, Netinimcev in služabnikov te hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 25, 'Ti pa, Ezra, po modrosti tvojega Boga, katera je v tvoji roki, postavi za sodnike in pravdnike, ki naj sodijo vse ljudstvo onostran reke, vse take, ki poznajo tvojega Boga postave. In kdor jih ne pozna, tega naučite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 26, 'In kdorkoli ne bo izpolnjeval postave Boga tvojega in postave kraljeve, nad tem naj se izvrši sodba z vso strogostjo, bodisi na smrt ali v prognanstvo ali v zaplenjenje imetja ali v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 27, 'Hvaljen bodi Jehova, naših očetov Bog, ki je to dal kralju v srce, da se odiči hiša Gospodova, ki je v Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 7, 28, 'in ki mi je naklonil milost pred kraljem in svetovalci njegovimi in pred vsemi kraljevimi močnimi vojvodami! In tako sem se ohrabril po roki Gospoda, Boga svojege, ki je bila nad menoj, in izbral sem prvake Izraelove, da bi šli gori z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 1, 'Ti pa so poglavarji očetovin in to je rodopis tistih, ki so šli z menoj gori iz Babilona ob vladanju kralja Artakserksa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 2, 'Od sinov Pinehasovih: Gersom; od sinov Itamarjevih: Daniel; od sinov Davidovih: Hatuš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 3, 'Od sinov Sekanijevih, od sinov Paroševih: Zeharija, in ž njim je bilo štetih po rodopisu stoinpetdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 4, 'Od sinov Pahat-moaba: Eljoenaj, sin Zerahijev, in ž njim dvesto moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 5, 'Od sinov Sekanijevih: sin Jahazielov in ž njim tristo moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 6, 'Od sinov Adinovih: Ebed, sin Jonatanov, in ž njim petdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 7, 'Od sinov Elamovih pa: Jesaja, sin Atalijev, in ž njim sedemdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 8, 'Od sinov Sefatijevih: Zebadija, sin Mihaelov, in ž njim osemdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 9, 'Od sinov Joabovih: Obadija, sin Jehielov, in ž njim dvesto in osemnajst moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 10, 'Od sinov Selomitovih: sin Josifijev in ž njim sto in šestdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 11, 'Od sinov Bebajevih: Zeharija, sin Bebajev, in ž njim osemindvajset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 12, 'Od sinov Azgadovih: Johanan, sin Hakatanov, in ž njim sto in deset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 13, 'Od sinov Adonikamovih, ki so bili zadnji, in njih imena so: Elifelet, Jegiel in Semaja in ž njimi šestdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 14, 'In od sinov Bigvajevih: Utaj in Zabud in ž njimi sedemdeset moških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 15, 'In zbral sem jih ob reki, ki teče v Ahavo, in tam smo taborili tri dni. In ko sem razgledoval ljudstvo in duhovnike, nisem ondi našel nikogar iz sinov Levijevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 16, 'Tedaj pošljem po Eliezerja, Ariela, Semaja, Elnatana, Jariba, Elnatana, Natana, Zeharija in Mesulama, prvake, tudi po Jojariba in Elnatana, zvedenca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 17, 'Tem dam sporočilo za Ida, prvaka v kraju Kasifiji, in jim velim, kaj jim je govoriti z Idom in z brati njegovimi, Netinimci, v kraju Kasifiji, da bi nam privedli strežaje za hišo našega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 18, 'In privedli so nam, ker je bila dobrotljiva roka Boga našega nad nami, razsodnega moža iz sinov Mahlija, sinu Levija, sinu Izraelovega, in Serebija ž njegovimi sinovi in brati, osemnajst,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 19, 'in Hasabija in ž njim Jesaja iz sinov Merarijevih, brate njegove in njih sinove, dvajset,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 20, 'od Netinimcev pa, ki jih je bil določil David in poglavarji, da bi stregli levitom, dvesto in dvajset Netinimcev; vsi iz njih so bili imenovani z imenom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 21, 'Nato sem oklical post ondi, pri reki Ahavi, da bi se ponižali pred Bogom svojim, da izprosimo od njega ravno pot za sebe in za otročiče svoje in za vse blago svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 22, 'Sramoval sem se namreč prositi kralja čete vojakov in konjikov, da bi nam pomagali zoper sovražnike na poti; kajti dejali smo bili kralju: Roka Boga našega je nad vsemi, ki ga iščejo, v dobro, a moč in jeza njegova je zoper vse, ki ga zapuščajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 23, 'Postili smo se torej in Boga svojega prosili tega, in dal se nam je izprositi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 24, 'Nato sem odločil dvanajstero poglavarjev duhovnikov, Serebija in Hasabija in deset njiju bratov ž njima;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 25, 'in odtehtal sem jim srebro in zlato in posode, dar povzdignjenja za hišo Boga našega, ki so ga bili darovali kralj in svetovalci in vojvode njegovi in vsi Izraelci, kar jih je bilo ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 26, 'Odtehtal sem, pravim, njim v roko šesto in petdeset talentov srebra in srebrnih posod za sto talentov, zlata pa sto talentov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 27, 'in dvajset zlatih čaš, vrednih tisoč darikov, in dve zlatožarni bronasti posodi, dragi ko zlato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 28, 'In sem jim velel: Vi ste sveti Gospodu, in te posode so svete, in srebro in zlato je dobrovoljen dar Gospodu, vaših očetu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 29, 'Bodite bedljivi in jih čuvajte, dokler jih ne stehtate pred poglavarji duhovnikov in levitov in poglavarji očetovin Izraelovih v Jeruzalemu, v hramih hiše Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 30, 'Vzeli so torej duhovniki in leviti stehtano srebro in zlato in posode, da jih doneso v Jeruzalem, v hišo Boga našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 31, 'Potem smo odrinili od reke Ahave, dvanajsti dan prvega meseca, da potujemo v Jeruzalem; in roka Boga našega je bila nad nami, in otel nas je iz roke sovražnikov in opotnih zasednikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 32, 'In dospeli smo v Jeruzalem in ondi ostali tri dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 33, 'In četrti dan so srebro in zlato in posode stehtali v hiši Boga našega v roke Meremotu, sinu Urija duhovnika, in ž njim je bil Eleazar, sin Pinehasov, ž njima pa Jozabad, sin Jesuov, in Noadija, sin Binuja, levita;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 34, 'vse po številu in po teži, in vsa teža je bila tisti čas zapisana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 35, 'Sinovi ujetništva, ki so se bili vrnili iz prognanstva, so darovali žgalne daritve Bogu Izraelovemu: dvanajst juncev za vsega Izraela, šestindevetdeset ovnov, sedeminsedemdeset jagnjet, dvanajst kozlov v daritev za greh, vse to v žgalščino Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 8, 36, 'In izročili so kraljeve ukaze kraljevim namestnikom in deželskim oblastnikom tostran reke. Ti pa so podpirali ljudstvo in hišo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 1, 'Ko pa je to vse bilo opravljeno, pristopijo k meni poglavarji, govoreč: Ljudstvo Izraelovo in duhovniki in leviti se niso ločili od ljudstev dežele, delajoč po njih gnusobah, Kanaancev in Hetejcev, Ferizejcev, Jebusejcev, Amoncev, Moabcev, Egipčanov in Amorejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 2, 'Zakaj jemali so njih hčere zase in za svoje sinove in so se, sveto seme, zmešali z ljudmi teh dežel, in roka poglavarjev in načelnikov je bila prva v tej nezvestobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 3, 'Ko sem to zaslišal, sem si raztrgal suknjo in plašč ter si pulil lase iz glave in brado in sedel potrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 4, 'Tedaj se zbero k meni vsi, ki so trepetali ob besedah Boga Izraelovega zaradi nezvestobe tistih, ki so prišli iz ujetništva. Jaz pa sem sedel potrt do večerne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 5, 'In ob večerni daritvi vstanem od svojega ponižanja z raztrgano suknjo in raztrganim plaščem, in padem na kolena in razprostrem roke proti Gospodu, Bogu svojemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 6, 'in rečem: O Bog moj, sramujem se in bojim se povzdigniti obličje k tebi, moj Bog; zakaj krivice naše so nam zrasle nad glavo in krivda naša je dospela do neba!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 7, 'Od očetov naših časa smo v veliki krivdi do tega dne, in zaradi krivic svojih smo bili izročeni mi, kralji naši in duhovniki naši rokam kraljev dežel, meču, ujetništvu, plenjenju in očitni sramoti, kakor je danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 8, 'In sedaj nam je za kratek trenutek izkazal milost Gospod, naš Bog, da nam je pustil ostanek rešencev in dal, da smemo zabiti šatorov klin na svetem kraju njegovem, da bi nam Bog naš razsvetlil oči ter nas malo poživil v sužnosti naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 9, 'Zakaj sužnji smo; vendar pa nas ni zapustil Bog naš v sužnosti naši, ampak nam je naklonil milost pred kralji Perzije, da bi nam pripravili oživitev, da postavimo hišo Božjo in popravimo razvaline njene, ter da bi nam dali zid v Judi in v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 10, 'In sedaj, Bog naš, kaj hočemo reči po vsem tem? Kajti zapustili smo tvoje zapovedi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 11, 'ki si jih zapovedal po hlapcih svojih, prorokih, rekši: Zemlja, v katero greste, da jo posedete, je nečista dežela vsled nečistosti poganskih ljudstev v deželi, vsled njih gnusob, s katerimi so jo napolnili od konca do kraja po svojem oskrunjevanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 12, 'Sedaj torej ne dajajte hčer svojih njih sinovom, tudi ne jemljite njih hčer sinovom svojim, niti ne iščite njih miru in blaginje vekomaj, da bodete mogočni in boste uživali dobrino dežele ter jo zapustili v dediščino otrokom svojim vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 13, 'Po vsem tem pa, kar je prišlo nad nas za huda dela naša in za našo krivdo veliko (ker si ti, Bog naš, nas kaznoval manj, nego zaslužijo krivice naše, in si nam dal toliko rešencev tukaj),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 14, 'bomo li zopet prelamljali zapovedi tvoje in svaštvo sklepali z ljudstvi, ki počenjajo te gnusobe? Bi se li ne srdil nad nami, dokler nas ne bo konec, da ne ostane nikogar in se nihče ne reši?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 9, 15, 'O Gospod, Bog Izraelov, ti si pravičen; kajti preostali smo kot rešenci, kakor se danes vidi. Glej, pred teboj smo v krivdi svoji, kajti nihče ne more stati pred teboj zaradi tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 1, 'In ko je Ezra molil in pripoznaval jokaje in sklonjen na tleh pred hišo Božjo, se je zbrala k njemu iz Izraela silno velika množica mož in žen in otrok. Kajti ljudstvo je grozno jokalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 2, 'In Sekanija, sin Jehielov, iz sinov Elamovih, izpregovori in reče Ezru: Nezvesto smo ravnali proti svojemu Bogu, ker smo si jemali žene tujke iz ljudstev dežele. A zdaj je še upanje Izraelu ob tem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 3, 'Sedaj torej sklenimo zavezo z Bogom svojim, da izločimo vse tiste žene in te, ki so se iz njih rodili, po svetu Gospodovem in tistih, ki trepetajo ob zapovedi Boga našega; in naj se ravna po postavi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 4, 'Vstani, ker to je tvoj posel, in mi bodemo pri tebi, bodi srčen in izvrši to!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 5, 'Nato vstane Ezra in zapriseže poglavarje duhovnikov, levitov in vsega Izraela, da bodo storili po tej besedi. In so prisegli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 6, 'In Ezra vstane izpred hiše Božje in stopi v izbo Johanana, sinu Eliasibovega. In ko pride tja, ne je kruha in ne pije vode, ker je žaloval zaradi nezvestobe tistih, ki so bili iz ujetništva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 7, 'In so poslali oklic po Judovem in Jeruzalemu za vse sinove ujetništva, naj se zbero v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 8, 'In kdor ne pride v treh dneh, po svetu poglavarjev in starejšin, naj zapade vse imetje njegovo prokletju in bodi izključen iz zbora tistih, ki so iz ujetništva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 9, 'Tedaj se zbero vsi možje Judovi in Benjaminovi v Jeruzalemu, v treh dneh; bilo je dvajseti dan devetega meseca. In vse ljudstvo je sedelo na široki ulici pred hišo Božjo, trepetaje zaradi te reči in od dežja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 10, 'Tedaj vstane Ezra duhovnik in jih ogovori: Nezvesto ste ravnali, ker ste si vzeli žene tujke, da še pomnožite krivdo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 11, 'Sedaj torej pripoznajte Gospodu, očetov svojih Bogu, in storite, kar mu ugaja, ter se ločite od ljudstev dežele in od žen tujk!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 12, 'In ves zbor odgovori in reče z velikim glasom: Dolžni smo storiti, kakor si nam povedal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 13, 'Ali ljudstvo je veliko in vreme je deževno in ne moremo stati tu zunaj, tudi se ne da opraviti v enem dnevu ali v dveh, kajti mnogoterno smo prestopali v tej reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 14, 'Postavijo naj se, prosimo, naši poglavarji za ves zbor, in vsi, ki bivajo v naših mestih, oženjeni z ženami tujkami, naj prihajajo, dokler ta reč traja, ob določenih časih in ž njimi starejšine vsakega dotičnega mesta in njega sodniki, dokler se od nas ne odvrne togota srda Boga našega. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 15, 'Samo Jonatan, sin Asahelov, in Jahzeja, sin Tikva, sta se temu ustavljala, in Mesulam in Sabetaj levit sta jima pomagala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 16, 'In sinovi ujetništva so storili tako. In bili so izvoljeni: Ezra, duhovnik, možje, poglavarji očetovin po svojih očetovinah, in vsi po imenu. In imeli so sejo prvi dan desetega meseca, da bi preiskali to zadevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 17, 'In do prvega dne prvega meseca so končno rešili vse zadeve mož, ki so vzeli žene tujke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 18, 'In našli so se med sinovi duhovnikov, ki so vzeli žene tujke: od sinov Jesua, sinu Jozadakovega, in bratov njegovih: Maaseja, Eliezer, Jarib in Gedalija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 19, 'In dali so svoje roke, da hočejo odpustiti svoje žene, in ker so bili krivi, so darovali ovna iz črede za svojo krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 20, 'In iz sinov Imerjevih: Hanani in Zebadija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 21, 'In iz sinov Harimovih: Maaseja, Elija, Semaja, Jehiel in Uzija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 22, 'In iz sinov Pashurjevih: Eljoenaj, Maaseja, Izmael, Netanel, Jozabad in Elasa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 23, 'In iz levitov: Jozabad, Simej, Kelaja (ta je Kelita), Petahija, Juda in Eliezer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 24, 'In iz pevcev: Eliasib; iz vratarjev: Salum, Telem in Uri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 25, 'In iz Izraela: iz sinov Paroševih: Ramija, Izija, Malkija, Mijamin, Eleazar, Malkija in Benaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 26, 'In iz sinov Elamovih: Matanija, Zeharija, Jehiel, Abdi, Jeremot in Elija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 27, 'In iz sinov Zatujevih: Eljoenaj, Eliasib, Matanija, Jeremot, Zabat in Aziza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 28, 'In iz sinov Bebajevih: Johanan, Hananija, Zabaj, Atlaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 29, 'In iz sinov Banijevih: Mesulam, Maluk, Adaja, Jasub, Seal, Jeremot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 30, 'In iz sinov Pahat-moaba: Adna, Kelal, Benaja, Maaseja, Matanija, Bezalel, Binuj in Manase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 31, 'In iz sinov Harimovih: Eliezer, Išija, Malkija, Semaja, Simeon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 32, 'Benjamin, Maluk, Semarija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 33, 'Iz sinov Hasumovih: Matenaj, Matata, Zabad, Elifelet, Jeremaj, Manase, Simej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 34, 'Iz sinov Banijevih: Maadaj, Amram in Uel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 35, 'Benaja, Bedeja, Keluhi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 36, 'Vanija, Meremot, Eliasib,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 37, 'Matanija, Matenaj in Jaasaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 38, 'Bani in Binuj, Simej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 39, 'Selemija, Natan, Adaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 40, 'Maknadebaj, Sasaj, Saraj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 41, 'Azarel, Selemija, Semarija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 42, 'Salum, Amarija, Jožef.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 43, 'Iz sinov Nebovih: Jegiel, Matitija, Zabad, Zebina, Jadaj in Joel, Benaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (15, 10, 44, 'Vsi ti so vzeli žene tujke in nekatere tistih žen so že rodile otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 1, 'Zgodbe Nehemija, sinu Hakalijevega. Zgodilo se je v mesecu Kislevu, v dvajsetem letu, ko sem bil na gradu Susanu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 2, 'da pride Hanani, eden bratov mojih, in ž njim nekaj mož z Judovega; in poprašam jih za Jude, ki so se rešili, ki so preostali iz ujetništva, in za Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 3, 'In oni mi reko: Tisti, kar jih je preostalo iz ujetništva, so ondi v deželi v veliki stiski in v zasramovanju; in zidovje Jeruzalema je razvaljeno in vrata njegova sežgana z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 4, 'In ko sem zaslišal te besede, sem sedel in jokal in žaloval nekoliko dni, in postil sem se ter molil pred Bogom nebes');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 5, 'in rekel: Prosim te, o Gospod, Bog nebes, Bog mogočni, veliki in grozni, ki hraniš zavezo in milost tistim, ki te ljubijo in izpolnjujejo zapovedi tvoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 6, 'Pazijo naj, prosim, ušesa tvoja in oči tvoje naj bodo odprte, da poslušaš hlapca svojega molitev, ki jo molim pred teboj ta čas, po dne in po noči, za sinove Izraelove, hlapce tvoje, ko pripoznavam grehe sinov Izraelovih, ki smo jih zagrešili zoper tebe. Tudi mi, jaz in mojega očeta hiša, smo grešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 7, 'Zelo krivo smo ravnali zoper tebe in nismo držali zapovedi, ne postav, ne sodb, ki si jih zapovedal hlapcu svojemu Mojzesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 8, 'Spomni se, prosim, besede, ki si jo velel hlapcu svojemu Mojzesu, govoreč: Ako se izneverite, vas razkropim daleč med ljudstva;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 9, 'ako se pa izpreobrnete k meni in boste držali zapovedi moje ter jih izpolnjevali, čeprav bi bili razskropljenci vaši ob koncu neba, tudi odondod jih zberem in jih privedem na kraj, ki sem ga izvolil, da umestim tam ime svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 10, 'Saj ti so hlapci tvoji in ljudstvo tvoje, ki si ga odrešil z veliko močjo svojo in z mogočno roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 1, 11, 'Ah, Gospod, prosim, pazi naj uho tvoje na hlapca tvojega molitev in na molitev hlapcev tvojih, ki se želé bati imena tvojega, in dodeli danes uspeh hlapcu svojemu ter mu daj usmiljenje v očeh tega moža. – Bil sem namreč kraljev točaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 1, 'Zgodi se pa v mesecu Nisanu, v dvajsetem letu kralja Artakserksa, ko je vino stalo pred njim, da vzamem vino in ga podam kralju. A prej nisem bil nikoli žalosten pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 2, 'In kralj mi reče: Zakaj je obraz tvoj žalosten? saj nisi bolan? To ni nič drugega nego bolečina v srcu! Tedaj sem se silno bridko bal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 3, 'In rečem kralju: Kralj, živi vekomaj! Kako ne bi bil žalostnega obraza, ko pusto leži mesto, kjer je očetov mojih grobišče, in vrata njegova so z ognjem požgana!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 4, 'Nato mi kralj reče: Kaj torej prosiš? V tem sem molil k Bogu nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 5, 'In rečem kralju: Ako se vidi dobro kralju in ako je hlapec tvoj prijeten v očeh tvojih, prosim, da me pošlješ na Judovo, v mesto, kjer so pokopani očetje moji, da ga pozidam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 6, 'In kralj mi veli (kraljica pa je sedela zraven njega): Koliko časa boš hodil? in kdaj se vrneš? In kralju je bilo ugodno, in me je poslal, ko sem mu določil čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 7, 'Še sem rekel kralju: Ako se vidi kralju dobro, naj prejmem list do deželnih oblastnikov onostan reke, da mi dovolijo iti skozi svoje kraje, dokler ne pridem na Judovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 8, 'in list Asafu, varuhu kraljevega gozda, da bi mi dal lesa, da napravim bruna za vrata gradu, ki je pri hiši, in za mestno obzidje in za hišo, v katero pojdem. In kralj mi jih je dal, ker je bila dobrotljiva roka Božja nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 9, 'In ko sem prišel k deželnim oblastnikom za reko, sem jim oddal kraljeve liste. Kralj pa je z menoj poslal vojne poveljnike in konjike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 10, 'Ko pa je slišal Sanbalat Horončan in hlapec Tobija, Amonec, ju je hudo peklo, da je prišel človek, da skrbi za blaginjo sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 11, 'In dospel sem v Jeruzalem. In ko sem bil ondi tri dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 12, 'vstanem po noči in malo mož z menoj; nisem namreč povedal nobenemu človeku, kaj mi je bil dal moj Bog v srce, da storim za Jeruzalem; tudi ni bilo živinčeta pri meni razen tega, na katerem sem jezdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 13, 'In jezdil sem ponoči skozi Dolinska vrata ven proti Zmajevemu studencu in h Gnojnim vratom in pregledoval zidovje Jeruzalemsko, ki je bilo razsuto in vrata njegova z ognjem požgana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 14, 'In šel sem dalje k Studenčnim vratom in h kraljevemu ribniku, a ondi ni bilo prostora mojemu živinčetu, da bi moglo iti pod mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 15, 'Šel sem torej po noči gori ob potoku in pregledoval zidovje; potem sem se vrnil zopet skozi Dolinska vrata in prišel domov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 16, 'Načelniki pa niso vedeli, kam sem šel ali kaj sem delal, kajti doslej nisem bil ničesar povedal Judom in duhovnikom, ne plemenitnikom in načelnikom in drugim, ki so opravljali delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 17, 'Tedaj sem jim rekel: Vidite nesrečo, v kateri smo, da Jeruzalem leži pust in njega vrata so sežgana z ognjem? Pojdimo in zidajmo zidovje jeruzalemsko, da ne bodemo več ljudem v zasrambo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 18, 'In povedal sem jim o roki svojega Boga, ki je bila dobrotljiva nad mano, tudi kraljeve besede, ki mi jih je bil govoril. Nato reko: Vstanimo in zidajmo! In potrjene so bile njih roke za dobro delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 19, 'Ko je pa to slišal Sanbalat Horončan in Tobija hlapec, Amonec, in Gesem Arabec, so nas zasmehovali in nas zaničevali in dejali: Kaj pomeni to, kar počenjate? Hočete se li vi upreti kralju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 2, 20, 'Tedaj sem jim odgovoril in rekel: Bog nebes nam da srečo, in mi, hlapci njegovi, hočemo vstati in zidati. Vam pa ni deleža, ne pravice, ne spomina v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 1, 'In Eliasib, veliki duhovnik, vstane z brati svojimi duhovniki in sezidajo Ovčja vrata ter jih posvetijo in vanje vstavijo duri. Posvetili so vse prav do stolpa Mea, do stolpa Hananela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 2, 'In poleg njega so zidali možje iz Jeriha. Zraven njega je tudi zidal Zakur, sin Imrijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 3, 'Ribja vrata pa so sezidali sinovi iz Senaa; napravili so v njih bruna in vstavili vanje duri in njih ključalnice in zapahe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 4, 'Poleg njih je zidal Meremot, sin Urijev, sinu Hakozovega. In poleg njega je zidal Mesulam, sin Berekija, sinu Mesezabelovega. In poleg njiju je popravljal Zadok, sin Baanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 5, 'In njim ob strani so popravljali Tekojčani; a njih imenitniki niso upognili vratu k službi svojega Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 6, 'In Stara vrata sta popravljala Jojada, sin Paseahov, in Mesulam, sin Besodejev: prekrila sta jih z bruni in vstavila vanje duri in njih ključalnice in zapahe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 7, 'In poleg njiju je popravljal Melatija Gibeonski in Jadon Meronotičan, možje iz Gibeona in iz Micpe, do tja, kjer je bila stolica deželnega oblastnika tostran reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 8, 'Njim ob strani je popravljal Uziel, sin Harhajev, eden od zlatarjev. In poleg njega je popravljal Hananija, eden od lekarnikov. In so pustili Jeruzalem, kakor je bil, do širokega zida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 9, 'In poleg njega je popravljal Refaja, sin Hurov, glavar polovice kraja Jeruzalemskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 10, 'In poleg njega je popravljal Jedaja, sin Harumafov, proti svoji hiši vprek. In poleg njega je popravljal Hatuš, sin Hasabnejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 11, 'Malkija, sin Harimov, in Hašub, sin Pahat-moabov, sta pa popravljala drugi kos zidovja in Pečni stolp.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 12, 'In poleg njiju je popravljal Salum, sin Halohešev, glavar druge polovice Jeruzalemskega kraja, on in hčere njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 13, 'Dolinska vrata je popravljal Hanun in prebivalci v Zanoahu; sezidali so jih ter vstavili vanje duri in njih ključalnice in zapahe in so zidali tisoč komolcev zidu do Gnojnih vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 14, 'Gnojna vrata pa je popravljal Malkija, sin Rehabov, glavar kraja Bet-keremskega; sezidal jih je in vtaknil duri vanje in njih ključalnice in zapahe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 15, 'Studenčna vrata pa je popravljal Salun, sin Kol-hozejev, glavar okraja Micpenskega; sezidal jih je ter pokril in vtaknil duri vanje in njih ključalnice in zapahe, in postavil je zid ob ribniku Silojskem pri kraljevem vrtu prav do stopnic, ki gredo doli iz mesta Davidovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 16, 'Za njim je popravljal Nehemija, sin Azbukov, glavar polovice okraja Betzurskega, tja do konca nasproti grobom Davidovim in do ribnika, ki so ga bili napravili, in do hiše junakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 17, 'Za njim so popravljali leviti, Rehum, sin Banijev. Poleg njega je popravlal Hasabija, glavar polovice okraja Keilskega, za svoj okraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 18, 'Za njim so popravljali njih bratje, Bavaj, sin Henadadov, vladar druge polovice okraja Keilskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 19, 'In poleg njega je popravljal Ezer, sin Jesujev, glavar v Micpi. Drugi kos zidu nasproti vzhodu k orožarni, pri zidnem ovinku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 20, 'Za njim je marljivo popravljal Baruk, sin Zabajev, drugi kos zidu, od ovinka k vratom hiše Eliasiba, velikega duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 21, 'Za njim je popravljal Meremot, sin Urijev, sinu Hakozovega, drugi kos zidu od vrat hiše Eleasibove do konca hiše Eliasibove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 22, 'In za njim so popravljali duhovniki, ki so prebivali na Jordanski ravnini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 23, 'Za njimi sta popravljala Benjamin in Hašub hišam svojim nasproti. Za njima je popravljal Azarija, sin Maaseja, sinu Ananijevega, pri hiši svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 24, 'Za njim je popravljal Binuj, sin Henadadov, drugi kos zidu, od hiše Azarijeve do ovinka in do vogla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 25, 'Palal, sin Uzajev, je popravljal proti ovinku in visokemu stolpu vprek, ki moli iznad hiše kraljeve, ki je ob dvoru jetnišnice; za njim pa Pedaja, sin Parošev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 26, '(Netinimci pa so stanovali na Ofelu do Vodnih vrat proti jutru in do stolpa, ki kvišku moli.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 27, 'Za njim so Tekojčani popravljali drugi kos zidu, nasproti visokemu stolpu, ki kvišku moli, in do zidu Ofela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 28, 'Od konjskih vrat gori so popravljali duhovniki vsak hiši svoji nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 29, 'Za njimi je popravljal Zadok, sin Imerjev, hiši svoji nasproti. In za njim je popravljal Semaja, sin Sekanijev, varuh Vzhodnih vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 30, 'Za njim je popravljal Hananija, sin Selemijev, in Hanun, šesti sin Zalafov, drugi kos zidu. Za njim je popravljal Mesulam, sin Berekijev, hramu svojemu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 31, 'Za njim je popravljal Malkija, eden od zlatarjev, do hiše Netinimcev in trgovcev, vratom Mifkadovim nasproti, in do stolpove veže na voglu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 3, 32, 'In med vežo stolpovo in Ovčjimi vrati so popravljali zlatarji in trgovci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 1, 'In ko je slišal Sanbalat, da stavimo obzidje, mu to silno zamrzi in se razjezi ter zasmehuje Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 2, 'In govori pred brati svojimi in pred vojsko v Samariji in reče: Kaj delajo ti slabotni Judje? Ali naj se jim to pripusti? Bodo li darovali? bodo li neki dan dokončali? hočejo li v življenje povrniti kamenje z grobljišča, ki je vendar sežgano?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 3, 'Tobija Amonec, stoječ poleg njega, reče: Karkoli naj zidajo, če lisica pride nanj, poruši njih kameneni zid!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 4, 'Poslušaj, o naš Bog, ker smo zaničevani, in obrni njih zasmehovanje njim na glavo ter izroči jih oplenjenju v deželi ujetništva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 5, 'Ne zakrivaj njih krivice in ne izbriši njih greha izpred obličja svojega! Ker so te dražili v jezo spričo zidalcev. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 6, 'Mi pa smo zidali obzidje, in smo sklenili ves zid okrog do polovice višave, kajti ljudstvo je imelo pogum za delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 7, 'Ko pa so slišali Sanbalat in Tobija in Arabci in Amonci in Asdodci, da napreduje popravljanje zidovja jeruzalemskega in da že zazidavamo, kar je bilo razdrto, tedaj se silno razjeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 8, 'In vsi se vkup zarote, da pojdejo bojevat se zoper Jeruzalem in delat zmešnjavo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 9, 'Mi pa smo molili k Bogu svojemu in postavili stražo zoper nje, dan in noč, boječ se jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 10, 'In Juda reče: Moč je bremenarjem oslabela in groblje so še velike, tako da ne moremo zidati zidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 11, 'Naši nasprotniki so pa rekli: Ne bodo zvedeli, ne videli, dokler ne pridemo mednje ter jih pobijemo, in tako ustavimo delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 12, 'Zgodi se pa, ko so prišli Judje, ki so poleg njih prebivali, in so nam dobro desetkrat povedali, od vseh krajev: Morate se vrniti k nam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 13, 'tedaj sem postavil na spodnje kraje prostora za zidom, na goljave, ljudstvo po njih rodovinah ž njih meči, sulicami in loki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 14, 'In ko sem vse ogledal, sem vstal in velel plemenitnikom in načelnikom in drugemu ljudstvu: Nikar se jih ne bojte, spominjajte se Gospoda, velikega in groznega, in bojujte se za brate svoje, za sinove in hčere svoje, za žene in hiše svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 15, 'Ko so pa slišali sovražniki naši, da nam je bilo povedano, in je Bog uničil njih naklep, smo se vrnili vsi na zid, vsak k delu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 16, 'In bilo je od tega dne, da je polovica mojih hlapcev opravljala delo, druga polovica pa je držala sulice in ščite, loke in oklepe, in poglavarji so stali za vso družino Judovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 17, 'ki je delala na zidu. In bremenarji so nakladali, vsak z eno roko delajoč, z drugo pa držeč orožje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 18, 'In zidar je vsak imel meč pripasan k ledju, in tako so zidali. In trobentač je stal poleg mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 19, 'In dejal sem plemenitnikom in načelnikom in drugemu ljudstvu: Dela je veliko in na široko in daleč smo narazen raztrošeni po zidu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 20, 'na kateremkoli kraju zaslišite trobente glas, tja se zberite k nam. Bog naš se bo bojeval za nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 21, 'Tako smo se trudili pri delu in polovica jih je držala sulice od jutranje zarje, dokler so zvezde prisvetile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 22, 'Tudi sem velel tisti čas ljudstvu: Slednji ostani s hlapcem svojim čez noč v Jeruzalemu, da nam bodo po noči v stražo in po dne za delo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 4, 23, 'Niti jaz, ne bratje moji, ne možje na straži za mano, nihče ni slekel obleke, vsakemu je bilo orožje ob desnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 1, 'In nastalo je veliko vpitje ljudstva in njih žen zoper svoje brate, Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 2, 'Nekateri so namreč bili, ki so dejali: Naših sinov in naših hčerá, nas je veliko: moramo dobiti žita, da jemo in ostanemo živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 3, 'In nekateri so bili, ki so govorili: Morali smo zastaviti njive svoje, vinograde in hiše svoje, da smo dobili žita ob tej draginji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 4, 'Nekateri pa so dejali: Izposodili smo si denarja na svoje njive in vinograde za davke kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 5, 'Vendar pa je telo naše kakor naših bratov telo in naši otroci so kakor njih otroci. In glej, moramo deti sinove in hčere svoje pod jarem sužnosti, in nekatere naše hčere so že pod jarmom, in ni v moči naših rok, da jih odkupimo; saj imajo drugi njive in vinograde naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 6, 'Ko sem pa slišal njih vpitje in take besede, sem se silno razsrdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 7, 'In posvetoval sem se sam pri sebi v srcu ter potem okaral plemenitnike in načelnike in jim dejal: Vi lihvarite, vsak proti bratu svojemu! In priredil sem veliko zborovanje zoper nje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 8, 'in jim dejal: Mi smo odkupili, kolikor smo jih mogli, brate svoje, Jude, ki so bili prodani poganom. Vi pa hočete prodajati brate svoje? in nam li naj se prodado? Nato so molčali in niso vedeli odgovoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 9, 'Še sem rekel: Kar delate, ni dobro. Ne bi li imeli hoditi v strahu Boga našega, da ne bodemo v zasmeh poganom, sovražnikom svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 10, 'Pa tudi jaz, bratje moji in hlapci moji, smo jim posodili denarja in žita za obresti. Prosim vas, odpustímo jim to posojilo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 11, 'Povrnite jim, prosim, še danes njih njive in vinograde, njih oljkove vrte in hiše in stotnino denarja in žita, vina in olja, ki ste ga jim posojali na obresti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 12, 'Tedaj reko: Povrnemo jim in ne bomo jih terjali za nič, ampak hočemo storiti, kakor praviš. Nato pokličem duhovnike in jih zavežem s prisego, da store po tej obljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 13, 'Iztresel sem tudi nedrije svoje, rekoč: Tako iztresi Bog vsakega, ki ne izpolni te obljube, iz hiše njegove in s posla njegovega, in tako bodi iztresen in prazen! In ves zbor je dejal: Amen! in so hvalili Gospoda. In ljudstvo je storilo po tej obljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 14, 'Tudi od časa, ko mi je bilo ukazano, naj bodem njih deželni poglavar v deželi Judovi, namreč od dvajsetega do dvaintridesetega leta kralja Artakserksa, dvanajst let, nisem živil sebe in bratov svojih s poglavarjevim živežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 15, 'Ali prejšnji deželni oblastniki, ki so bili pred menoj, so nadlegovali ljudstvo in so jemali od njih živeža in vina, vrhutega po štirideset seklov srebra, in še njih hlapci so samovoljno gospodovali ljudstvu. A jaz nisem ravnal tako, zaradi Božjega strahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 16, 'Pa tudi dela na zidu sem se udeležil, in njive nismo nobene kupili in vsi moji hlapci so ondi morali prihajati na delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 17, 'Vrhutega so jedli pri moji mizi Judje in načelniki, sto in petdeset mož, in tisti, ki so k nam dohajali izmed poganov v okolišu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 18, 'In pripravili so mi vsak dan: enega vola in šest izbranih ovac, tudi perotnine so mi pripravljali in enkrat v desetih dneh zalogo vsakovrstnega vina; pri vsem tem nisem zahteval živeža deželnega oblastnika, ker služba je hudo težila ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 5, 19, 'Spominjaj se mi, o Bog moj, v dobro vsega, kar sem storil za to ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 1, 'Zgodi se pa, ko so zvedeli Sanbalat, Tobija in Gesem Arabec in drugi naših sovražnikov, da sem dozidal obzidje ter da v njem ni bilo več vrzeli (dasi še nisem do tedaj obesil durnic na vrata),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 2, 'da pošljeta k meni Sanbalat in Gesem ter sporočita: Pridi, in naj se snidemo v kateri vasi na Onski ravnini. Ona sta pa mislila storiti mi hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 3, 'In pošljem sle in jima sporočim: Opravljam veliko delo, ne morem priti tja doli. Čemu naj počiva delo, če bi ga popustil in prišel doli k vam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 4, 'Štirikrat sta k meni poslala z istimi besedami, in odgovarjal sem jima na ta način.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 5, 'Tedaj pošlje Sanbalat petič istotako hlapca svojega k meni z odprtim listom v roki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 6, 'v katerem je bilo pisano: Pripoveduje se med narodi, in Gesem to pravi, da se ti in Judje mislite izneveriti; zato gradiš obzidje, in ti jim hočeš biti kralj, kakor se govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 7, 'In postavil si tudi proroke, da oznanjajo o tebi v Jeruzalemu, govoreč: Kralj je na Judovem! In sedaj lahko zasliši kralj to, kar se govori. Sedaj torej pridi, da se posvetujemo skupaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 8, 'Nato pošljem k njemu in sporočim: Nič takega se ni zgodilo, kar ti praviš, temuč v srcu svojem si to izmislil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 9, 'Zakaj vsi oni so nas hoteli prestrašiti, češ, da bodo roke naše nehale od dela, da se ne dovrši. –Sedaj pa, Bog, pokrepčaj moje roke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 10, 'In šel sem v hišo Semaja, sinu Delaja, sinu Mehetabela, ki se je bil zaklenil. In on je rekel: Snidiva se v hiši Božji, sredi templja, in zapriva duri templjeve; zakaj pridejo, da te umore, po noči pridejo, da te ubijejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 11, 'Jaz pa sem dejal: Mož, kakršen sem jaz, naj beži? In kako bi smel tak, kakršen sem jaz, iti v tempelj, da ostane živ? Ne pojdem vanj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 12, 'In razpoznal sem, da ga ni poslal Bog, temuč govoril je to prorokovanje zoper mene, in Tobija in Sanbalat sta mu bila dala denarja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 13, 'in je bil najet v ta namen, da se zbojim in storim tako in se pregrešim in da bi imela kaj hudega poročati, da bi me mogla zasramovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 14, 'Spominjaj se, moj Bog, Tobija in Sanbalata, primerno tem njiju delom, in tudi prorokinje Noadije in drugih prorokov, ki so me hoteli spraviti v strah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 15, 'In obzidje je bilo dokončano petindvajseti dan meseca Elula, v dvainpetdesetih dneh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 16, 'In ko so to slišali vsi sovražniki naši, so se zbali vsi pogani, ki so živeli okoli nas, in bili so zelo uplašeni sami v sebi, kajti spoznali so, da je to delo dognal Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 17, 'Tudi so v teh dneh plemenitniki Judovi pošiljali mnogo listov Tobiju, jim pa so dohajali listi od Tobija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 18, 'Dosti jih je namreč bilo na Judovem, ki so se ž njim bili s prisego zvezali, ker je bil zet Sekanija, sinu Arahovega, in se je sin njegov Johanan oženil s hčerjo Mesulama, sinu Berekijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 6, 19, 'Govorili so tudi vpričo mene o njegovih dobrih dejanjih in njemu skrivaj donašali besede moje; in Tobija je pošiljal liste, da bi me spravil v strah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 1, 'In ko je bilo obzidje dodelano, sem obesil durnice nanje, in vratarji in pevci in leviti so bili postavljeni v službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 2, 'In brata svojega Hanana in Hananija, višjega v gradu, sem postavil nad Jeruzalemom, zakaj bil je zvest mož in bogaboječ mimo mnogih drugih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 3, 'In sem jima velel: Vrata jeruzalemska naj se ne odpirajo, dokler solnce vroče ne sije; in dokler še stoje na straži, naj zaprejo duri, in zaklenita jih. In postavita straže iz prebivalcev jeruzalemskih, vsakega na stražišče njegovo in vsakega nasproti hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 4, 'Mesto pa je bili prostrano na vse strani in veliko, a malo ljudstva v njem, in hiše niso bile pozidane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 5, 'In Bog moj mi je dal v srce, da sem zvabil plemenitnike in načelnike in ljudstvo, da bi jih preštel po rodovih. In našel sem zapis rodov tistih, ki so prišli prvi gori iz Babilona, in našel sem v njem pisano takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 6, 'Ti so otroci pokrajine Judove, ki so šli gori iz ujetništva izmed tistih, ki so bili pripeljani, ki jih je preselil Nebukadnezar, kralj babilonski, in ki so se povrnili v Jeruzalem in na Judovo, vsak v mesto svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 7, 'ki so prišli z Zerubabelom, Jesuom, Nehemijem, Azarijem, Raamijem, Nahamanom, Mardohejem, Bilsanom, Misperetom, Bigvajem, Nehumom, Baanom. Število mož iz ljudstva Izraelovega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 8, 'Sinov Paroševih dva tisoč in sto in dvainsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 9, 'Sinov Sefatijevih tristo in dvainsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 10, 'Sinov Arahovih šeststo dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 11, 'Sinov Pahat-moaba, od sinov Jesujevih in Joabovih, dva tisoč in osemsto osemnajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 12, 'Sinov Elamovih tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 13, 'Sinov Zatujevih osemsto petinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 14, 'Sinov Zakajevih sedemsto in šestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 15, 'Sinov Binujevih šeststo oseminštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 16, 'Sinov Bebajevih šeststo osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 17, 'Sinov Azgadovih dva tisoč tristo dvaindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 18, 'Sinov Adonikamovih šeststo sedeminšestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 19, 'Sinov Bigvajevih dva tisoč sedeminšestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 20, 'Sinov Adinovih šeststo petinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 21, 'Sinov Aterjevih, od Hezekija, osemindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 22, 'Sinov Hasumovih tristo osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 23, 'Sinov Bezajevih tristo štiriindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 24, 'Sinov Harifovih sto in dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 25, 'Sinov Gibeonovih petindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 26, 'Mož iz Betlehema in Netofe sto oseminosemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 27, 'Mož iz Anatota sto osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 28, 'Mož iz Bet-azmaveta dvainštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 29, 'Mož iz Kirjat-jearima, Kefire in Beerota sedemsto triinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 30, 'Mož iz Rame in Gebe šeststo edenindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 31, 'Mož iz Mikmasa sto dvaindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 32, 'Mož iz Betela in Aja sto triindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 33, 'Mož iz drugega Neba dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 34, 'Sinov drugega Elama tisoč dvesto štiriinpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 35, 'Sinov Harimovih tristo in dvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 36, 'Sinov Jerihovih tristo petinštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 37, 'Sinov iz Loda, Hadida in Ona sedemsto edenindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 38, 'Sinov iz Senaa tri tisoč devetsto in trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 39, 'Duhovnikov: sinov Jedajevih, iz hiše Jesujeve, devetsto triinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 40, 'Sinov Imerjevih tisoč dvainpetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 41, 'Sinov Pashurjevih tisoč dvesto sedeminštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 42, 'Sinov Harimovih tisoč in sedemnajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 43, 'Levitov: sinov Jesujevih, od Kadmiela, od sinov Hodevovih, štiriinsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 44, 'Pevcev: sinov Asafovih sto oseminštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 45, 'Vratarjev: sinov Salumovih, sinov Aterjevih, sinov Talmonovih, sinov Akubovih, sinov Hatitovih, sinov Sobajevih: sto osemintrideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 46, 'Netinimci: sinovi Zihovi, sinovi Hasufovi, sinovi Tabaotovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 47, 'sinovi Kerosovi, sinovi Siahovi, sinovi Padonovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 48, 'sinovi Lebanovi, sinovi Hagabovi, sinovi Salmajevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 49, 'sinovi Hananovi, sinovi Gidelovi, sinovi Gaharjevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 50, 'sinovi Reajevi, sinovi Rezinovi, sinovi Nekodovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 51, 'sinovi Gazamovi, sinovi Uzovi, sinovi Paseahovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 52, 'sinovi Bezajevi, sinovi Meunimov, sinovi Nefusimov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 53, 'sinovi Bakbukovi, sinovi Hakufovi, sinovi Harhurjevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 54, 'sinovi Bazlitovi, sinovi Mehidovi, sinovi Harsovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 55, 'sinovi Barkosovi, sinovi Siserjevi, sinovi Tamahovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 56, 'sinovi Neziahovi, sinovi Hatifovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 57, 'Sinovi hlapcev Salomonovih: sinovi Sotajevi, sinovi Soferetovi, sinovi Peridovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 58, 'sinovi Jaalovi, sinovi Darkonovi, sinovi, Gidelovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 59, 'sinovi Sefatijevi, sinovi Hatilovi, sinovi Poheret-hazebaimovi, sinovi Amonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 60, 'Vseh Netinimcev in sinov hlapcev Salomonovih je bilo tristo dvaindevetdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 61, 'Ti pa so bili, ki so šli gori iz Telmelaha, Telharsa, Keruba, Adona in Imerja, toda niso mogli izkazati hiš svojih očetov, ne svojega rodu, ali so iz Izraela:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 62, 'sinovi Delajevi, sinovi Tobijevi, sinovi Nekodovi, šeststo dvainštirideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 63, 'In od duhovnikov: sinovi Hobajevi, sinovi Hakozovi, sinovi Barzilaja, ki si je vzel ženo iz hčerá Barzilaja Gileadčana in je bil imenovan po njih imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 64, 'Ti so iskali zapis svojih rodov, pa ga niso našli, zato so jih šteli za nečiste za duhovništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 65, 'In Tirsata jim je velel, da naj ne jedo od najsvetejšega, dokler ne vstane duhovnik z Urimom in Tumimom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 66, 'Ves zbor je štel dvainštirideset tisoč tristo in šestdeset,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 67, 'brez njih hlapcev in dekel, katerih je bilo sedem tisoč tristo sedemintrideset; imeli so tudi dvesto petinštirideset pevcev in pevk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 68, 'Njih konj je bilo sedemsto šestintrideset, njih mezgov dvesto petinštirideset,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 69, 'velblodov štiristo petintrideset in oslov šesttisoč sedemsto in dvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 70, 'In nekateri izmed poglavarjev očetovin so dali v prospeh dela. Tirsata je dal v zaklad: zlata tisoč darikov, petdeset čaš, petsto in trideset duhovniških sukenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 71, 'In nekateri iz poglavarjev očetovin so dali v zaklad za delo: zlata dvajset tisoč darikov in srebra dva tisoč in dvesto min.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 72, 'In tega, kar so dali drugi iz ljudstva, je bilo v zlatu dvajset tisoč darikov in v srebru dva tisoč min in sedeminšestdeset duhovniških sukenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 7, 73, 'In duhovniki in leviti, vratarji in pevci in nekateri iz ljudstva in Netinimci in vsi Izraelci so se naselili v svoja mesta. In ko je prišel sedmi mesec, so bili sinovi Izraelovi že v svojih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 1, 'Tedaj se je zbralo vse ljudstvo kakor en mož na široki ulici pred Vodnimi vrati; in rekli so Ezru pismouku, naj prinese knjigo zakona Mojzesovega, ki ga je Gospod zapovedal Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 2, 'In Ezra duhovnik je prinesel postavo pred zbor, pred može in žene in vse, ki so jo mogli slišati in razumeti, prvi dan sedmega meseca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 3, 'In čital jo je na široki ulici, ki je pred Vodnimi vrati, od jutranjega svita do poldne vpričo mož in žen in tistih, ki so mogli razumeti; in vsega ljudstva ušesa so bila obrnjena h knjigi postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 4, 'In Ezra, pismouk, je stal na visokem lesenem stolu, ki so ga bili napravili v ta namen; in zraven njega so stali Matitija, Sema, Anaja, Urija, Hilkija in Maaseja, njemu na desni, na levi pa Pedaja, Misael, Malkija, Hasum, Hasbadana, Zeharija in Mesulam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 5, 'In Ezra razgane knjigo pred očmi vsega ljudstva (kajti stal je više nego vse ljudstvo), in ko jo je razganil, vstane vse ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 6, 'In Ezra hvali Gospoda, vélikega Boga. In vse ljudstvo odgovori: Amen, Amen! povzdigujoč roke svoje. In pripognejo se in poklonijo Gospodu z obrazom do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 7, 'Tudi Jesua, Bani, Serebija, Jamin, Akub, Sabetaj, Hodija, Maaseja, Kelita, Azarija, Jozabad, Hanan, Pelaja, leviti, so razlagali ljudstvu pouk postave; in ljudstvo je stalo na mestu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 8, 'In čitali so knjigo, postavo Božjo, razumljivo in razložili pomen, da se je prečitano razumelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 9, 'In Nehemija, ki je bil Tirsata, in Ezra, duhovnik pismouk, in leviti, ki so učili ljudstvo, so rekli vsemu ljudstvu: Ta dan je svet Gospodu, vašemu Bogu; ne bodite žalostni in ne plakajte! Zakaj vse ljudstvo je plakalo, ko so slišali besede postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 10, 'Zato jim je velel: Pojdite, jejte tolsto in pijte sladko in pošljite tudi darila tem, ki niso ničesar zase pripravili, zakaj ta dan je svet Gospodu našemu; zato se ne žalostite, kajti radost Gospodova je vaša moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 11, 'In leviti so tolažili vse ljudstvo, govoreč: Molčíte, kajti ta dan je svet, ne žalostite se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 12, 'In šlo je vse ljudstvo, da bi jedli in pili in darila pošiljali in napravili veliko veselico; kajti razumeli so besede, ki so jih jim bili oznanjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 13, 'In drugega dne so se zbrali poglavarji očetovin vsega ljudstva, duhovniki in leviti k Ezru pismouku, da bi pazili na besede postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 14, 'In našli so pisano v postavi, da je bil Gospod zapovedal po Mojzesu, da naj prebivajo sinovi Izraelovi v šatorih iz zelenja ob prazniku v sedmem mesecu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 15, 'ter naj oznanijo in pošljejo oklic po vseh mestih svojih in po Jeruzalemu, rekoč: Pojdite na gore in prinesite oljkovih mladik in vej z divje oljke in mirtovih in palmovih vej in mladičja z listnatih dreves, da se napravijo iz njih šatori, kakor je pisano!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 16, 'Ljudstvo je torej šlo ven, in so prinesli ter si napravili šatore, vsak na strehi svoji, in na svojih dvoriščih in na dvoriščih hiše Božje in na široki ulici pri Vodnih vratih in na široki ulici pri Efraimovih vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 17, 'In ves zbor tistih, ki so se bili vrnili iz ujetništva, si je napravil šatore, in prebivali so v njih. Kajti sinovi Izraelovi niso bili tako slovesno praznovali od dni Jozueta, sina Nunovega, do tega dne. In bilo je veselje silno veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 8, 18, 'In bral je v knjigi Božje postave vsak dan, od prvega dne do poslednjega. In so praznovali praznik sedem dni, in osmi dan je bilo slovesno zborovanje, po predpisu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 1, 'A štiriindvajseti dan tega meseca so se zbrali sinovi Izraelovi s postom in v žalni obleki in s prstjo na glavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 2, 'In seme Izraelovo se je ločilo od vseh otrok tujcev, in ustopili so se in pripoznavali grehe svoje in očetov svojih kriva dejanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 3, 'In stali so na mesto svojem in so brali v knjigi postave Gospoda, svojega Boga, četrti del dne. In drugi četrti del dne so pripoznavali in se poklanjali Gospodu, svojemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 4, 'Nato stopijo na stopnice levitov Jesua, Bani, Kadmiel, Sebanija, Buni, Serebija, Bani in Kenani, in so vpili z velikim glasom h Gospodu, svojemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 5, 'In leviti: Jesua, Kadmiel, Bani, Hasabneja, Serebija, Hodija, Sebanija in Petahija so dejali: Vstanite in hvalite Gospoda, svojega Boga, od vekomaj do vekomaj! In hvaljeno bodi ime slave tvoje, ki je vzvišeno nad vsako hvalo in proslavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 6, 'Ti si Gospod, ti edini! Ti si naredil nebo, nebesa nebes in vso njih vojsko, zemljo in vse, kar je na njej, morja in karkoli je v njih, in ti jim vsem vzdržuješ obstanek; in vojske nebeške te molijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 7, 'Ti si Jehova, Bog, ki si izvolil Abrama ter ga pripeljal iz Ura Kaldejcev, in dal si mu ima Abraham.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 8, 'In našel si srce njegovo zvesto pred seboj ter sklenil ž njim zavezo, da mu daš deželo Kanaancev, Hetejcev, Amorejcev, Ferizejcev, Jebusejcev in Girgasejcev, da jo daš semenu njegovemu, in si vzdržal besede svoje, zakaj ti si pravičen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 9, 'Ti si videl nadlogo očetov naših v Egiptu in slišal njih vpitje ob Rdečem morju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 10, 'in storil si znamenja in čudeže nad Faraonom in nad vsemi hlapci njegovimi in nad vsem ljudstvom dežele njegove, zakaj vedel si, da so prevzetno ravnali proti njim; in si sebi storil ime, kakor je današnji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 11, 'Razklal si morje pred njimi, da so šli sredi morja po suhem; njih preganjalce pa si vrgel v globočine, kakor kamen v silne vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 12, 'In vodil si jih v oblakovem stebru po dne in v ognjenem stebru po noči, da bi jim svetil na poti, ki so po njej šli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 13, 'In prišel si doli na goro Sinaj in govoril si ž njimi iz nebes ter jim dal pravične sodbe in zakone resnične ter dobre postave in zapovedi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 14, 'in znano si jim storil sveto soboto svojo in jim zapovedal zapovedi in postave in zakon po Mojzesu, hlapcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 15, 'In kadar so bili lačni, si jim dajal kruha iz nebes in izpeljal si zanje vodo iz skale, ko so bili žejni, in si jim velel, naj gredo posest deželo, za katero si s povzdignjeno roko prisegel, da jim jo daš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 16, 'Ali oni, očetje naši, so ravnali prevzetno in postali so trdovratni in niso poslušali zapovedi tvojih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 17, 'in so se branili poslušati in se niso spominjali čudovitih del tvojih, ki si jih storil med njimi, temuč v trdovratnosti svoji in v uporu svojem so si postavili glavarja, da bi se vrnili v sužnost svojo. Ali ti si Bog mnogega odpuščanja, milostiv in poln usmiljenja, počasen v jezi in obilen v milosti, ti jih nisi zapustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 18, 'Ko so si celo naredili ulito tele in rekli: To je tvoj Bog, ki te je izpeljal iz Egipta, in so počenjali grozno zasmehovanje Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 19, 'ti jih vendar nisi zapustil v mnogoterem usmiljenju svojem v puščavi: oblakov steber se ni umaknil iznad njih po dne, da bi jih vodil po poti, ne ognjeni steber po noči, da bi jim svetil na pot, po kateri naj gredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 20, 'Ti si tudi dal dobrega duha svojega, da jih poučuje, in njih ustom nisi odrekel mane svoje, in dajal si jim vode, ko so bili žejni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 21, 'Štirideset let si jih oskrboval v puščavi, da jim ničesar ni pomanjkovalo; njih obleka se ni razdrapala in njih noge niso otekle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 22, 'In dal si jim kraljestva in ljudstva in ta jim pridelil po posameznih pokrajinah; tako so posedli deželo Sihona, kralja hesbonskega, in deželo Oga, kralja v Basanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 23, 'In njih otroke si pomnožil kakor zvezde na nebu in si jih pripeljal v deželo, za katero si bil govoril njih očetom, da pridejo vanjo in jo posedejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 24, 'njih otroci so torej prišli vanjo in jo posedli, in ti si ponižal pred njimi prebivalce te dežele, Kanaance, in si jih dal njim v roke ž njih kralji in z ljudstvi vred v deželi, da so ž njimi storili po volji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 25, 'In zavzeli so utrjena mesta in mastno zemljo in dobili v last hiše, polne vsakršnega blaga, vodnjake izkopane, vinograde, oljkove vrte in sadnih dreves obilo: in jedli so in se nasitili in odebeleli, dobro živeč po veliki dobroti tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 26, 'Ali postali so nepokorni in se uprli zoper tebe in so vrgli zakon tvoj za hrbet svoj in pomorili proroke tvoje, ki so pričevali zoper nje, da bi jih zopet preobrnili k tebi, in so počenjali grozno zasmehovanje Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 27, 'Zato si jih dal v roke njih zatiralcem, ki so jih tlačili; ali ko so ob času nadloge vpili k tebi, ti si jih uslišal iz nebes in po svojem mnogoterem usmiljenju si jim dal rešitelje, ki so jih oteli iz roke njih zatiralcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 28, 'A komaj so imeli pokoj, so zopet delali hudo pred teboj. Zato si jih prepustil pesti njih sovražnikov, da so jim gospodovali; pa zopet so vpili k tebi, in slišal si jih iz nebes in mnogokrat si jih otel po mnogem usmiljenju svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 29, 'In pričeval si zoper nje, da bi jih izpreobrnil k postavi svoji, oni pa so se vedli prevzetno in niso poslušali zapovedi tvojih, ampak so grešili zoper pravice tvoje (katere kdor izpolnjuje, bo živel po njih) in pleča svoja umeknili izpod jarma tvojega; vdali so se trdovratnosti in niso hoteli poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 30, 'A veliko let si imel potrpljenje ž njimi in po duhu svojem si pričeval zoper nje, po svojih prorokih, a niso poslušali; zato si jih dal v roke ljudstvom dežel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 31, 'Vendar pa v mnogoterem usmiljenju svojem jih nisi docela pokončal, ne jih zapustil, zakaj ti, Bog mogočni, si milostiv in poln usmiljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 32, 'In sedaj, o Bog naš, Bog mogočni, veliki, silni in grozni, ki hraniš zavezo in milost, naj se ti ne vidi majhna vsa tista težava, ki je zadela nas in kralje naše in kneze in duhovnike in proroke in očete naše in vse ljudstvo tvoje, od dni kraljev asirskih do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 33, 'Ali ti si pravičen v vsem, kar je prišlo nad nas: zakaj ti si ravnal po resnici, mi pa smo delali krivično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 34, 'In naši kralji, knezi, duhovniki in očetje niso delali po postavi tvoji in niso pazili na zapovedi tvoje in pričevanja, s katerimi si pričeval zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 35, 'Kajti niso ti služili v kraljestvu svojem in ob veliki dobroti tvoji, ki si jo jim podeljeval, in v tej postrani in mastni deželi, ki si jo jim bil izročil, in se niso preobrnili od hudih dejanj svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 36, 'Glej, hlapci smo danes, in dežela, ki si jo dal očetom našim, da uživajo njene sadove in dobrote – glej, v tej smo hlapci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 37, 'In ona dohodke svoje množi kraljem, ki si jih nam postavil zavoljo grehov naših, in ti gospodujejo telesom našim in živini naši, kakor jim je drago, in v veliki smo nadlogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 9, 38, 'A pri vsem tem narejamo in pišemo trdno zavezo, in vojvode naši, leviti in duhovniki naši, jo s pečati potrjujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 1, 'Ti pa, ki so pečatili, so bili: Nehemija Tirsata, sin Hakalijev, in Zedekija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 2, 'Seraja, Azarija, Jeremija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 3, 'Pashur, Amarija, Malkija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 4, 'Hatuš, Sebanija, Maluk,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 5, 'Harim, Meremot, Obadija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 6, 'Daniel, Gineton, Baruk,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 7, 'Mesulam, Abija, Mijamin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 8, 'Maazija, Bilgaj, Semaja: ti so bili duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 9, 'Leviti pa: Jesua, sin Azanijev, Binuj iz sinov Henadovih, Kadmiel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 10, 'in njih bratje: Sebanija, Hodija, Kelita, Pelaja, Hanan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 11, 'Miha, Rehob, Hasabija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 12, 'Zakur, Serebija, Sebanija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 13, 'Hodija, Bani, Beninu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 14, 'Poglavarji ljudstva: Paroš, Pahat-moab, Elam, Zatu, Bani,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 15, 'Buni, Azgad, Bebaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 16, 'Adonija, Bigvaj, Adin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 17, 'Ater, Hezekija, Azur,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 18, 'Hodija, Hasum, Bezaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 19, 'Harif, Anatot, Nobaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 20, 'Magpias, Mesulam, Hezir,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 21, 'Mesezabel, Zadok, Jadua,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 22, 'Pelatija, Hanan, Anaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 23, 'Hosea, Hananija, Hašub,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 24, 'Haloheš, Pilha, Sobek,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 25, 'Rehum, Hasabna Maaseja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 26, 'in Ahija, Hanan, Anan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 27, 'Maluk, Harim, Baana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 28, 'In drugo ljudstvo, duhovniki, leviti, vratarji, pevci, Netinimci in vsi, ki so se bili ločili od ljudstev dežel za postavo Božjo, njih žene, njih sinovi in hčere, katerikoli so bili razsodni in pametni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 29, 'so se oklenili bratov svojih, svojih plemenitnikov, in so vzeli nase prekletje in prisego, da bodo živeli po zakonu Božjem, ki je bil dan po Mojzesu, hlapcu Božjem, in da bodo hranili in izpolnjevali vse zapovedi Jehove, Gospoda našega, in sodbe in postave njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 30, 'ter da ne bomo dajali hčer svojih ljudem dežele, ne jemali njih hčer sinom svojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 31, 'in kadar ljudje dežele prineso blaga ali kakršnegakoli živeža naprodaj sobotni dan, da ne kupimo od njih ob soboti in ob svetih dneh, in da se odpovemo pravice do sedmega leta in do vsakega posojila v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 32, 'In zavezali smo se z naredbo, da si naložimo na leto tretjino sekla za službo hiše Boga svojega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 33, 'za razvrstitev kruhov in za stalno jedilno daritev in za stalno žgalno daritev in za posebno ob sobotah in v začetku mesecev in ob določenih praznikih, in za svete reči in za daritev za greh v poravnavo za Izraela in za vse opravilo v hiši Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 34, 'In žrebali smo, duhovniki, leviti, in ljudstvo, za daritev drv, da bi jih prinašali vsako leto, ob določenih časih, po hišah svojih očetov, v hišo Boga svojega, da bodo gorela na oltarju Gospoda, našega Boga, kakor je pisano v postavi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 35, 'in smo se zavezali, da bomo prinašali prvine zemlje svoje in prvine vsega sadu vsakovrstnih dreves leto za letom v hišo Gospodovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 36, 'tudi prvence sinov svojih in živine svoje, kakor je pisano v postavi, in prvence govedi in drobnice svoje, da bomo vse prinašali v hišo Boga svojega, duhovnikom, ki strežejo v hiši Boga našega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 37, 'tudi da bomo prinašali prvine testa svojega in svoje dari povzdignjenja in sadove vsakovrstnih dreves, vino in olje, duhovnikom, v hrame pri hiši Boga svojega, desetino zemlje svoje pa levitom; zakaj oni, leviti, imajo dobivati desetine v vseh naših poljedeljskih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 38, 'In duhovnik, sin Aronov, bodi pri levitih, ko bodo prejemali desetino. In leviti so dolžni prinesti desetino od desetin v hišo Boga našega, v shrambe pri zakladnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 10, 39, 'Kajti sinovi Izraelovi in sinovi Levijevi imajo prinašati dari povzdignjenja od žita, od vina in od olja v shrambe, kjer so posode svetišča in duhovniki, ki strežejo, vratarji in pevci. In nočemo zapustiti hiše Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 1, 'In poglavarji ljudstva so prebivali v Jeruzalemu. In drugo ljudstvo je žrebalo, da se naroči enemu med desetimi, naj pride prebivat v Jeruzalem, sveto mesto, devet delov pa naj jih ostane v drugih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 2, 'In ljudstvo je blagoslovilo vse može, ki so se rade volje ponudili, da bodo prebivali v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 3, 'Ti pa so prvaki pokrajine, ki so prebivali v Jeruzalemu; a po mestih Judovih so prebivali, vsak na svojem posestvu, v mestih svojih, Izraelci, duhovniki in leviti in Netinimci in sinovi hlapcev Salomonovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 4, 'in v Jeruzalemu so prebivali nekateri sinov Judovih in sinov Benjaminovih. Iz sinov Judovih: Ataja, sin Uzija, sinu Zeharija, sinu Amarija, sinu Sefatija, sinu Mahalalela, od sinov Perezovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 5, 'in Maaseja, sin Baruka, sinu Kolhozeja, sinu Hasaja, sinu Adaja, sinu Jojariba, sinu Zeharija, sinu Silonita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 6, 'Vseh sinov Perezovih, ki so prebivali v Jeruzalemu, je bilo štiristo oseminšestdeset junaških mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 7, 'Ti pa so sinovi Benjaminovi: Salu, sin Mesulama, sinu Joeda, sinu Pedaja, sinu Kolaja, sinu Maaseja, sinu Itiela, sinu Jesaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 8, 'In za njim Gabaj, Salaj, devetsto osemindvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 9, 'In Joel, sin Zihrijev, jim je bil nadzornik, in Juda, sin Hasenujev, je bil drugi nad mestom. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 10, 'Iz duhovnikov: Jedaja, sin Jojaribov, Jakin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 11, 'Seraja, sin Hilkija, sinu Mesulama, sinu Zadoka, sinu Merajota, sinu Ahituba, ta je bil poglavar hiše Božje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 12, 'in njih bratov, ki so opravljali delo v hiši, je bilo osemsto dvaindvajset; in Adaja, sin Jerohama, sinu Pelalija, sinu Amzija, sinu Zeharija, sinu Pashurja, sinu Malkija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 13, 'in njegovih bratov, poglavarjev očetovin, je bilo dvesto dvainštirideset; in Amasaj, sin Azarela, sinu Ahzaja, sinu Mesilemota, sinu Imerja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 14, 'in njih bratov, hrabrih junakov, sto osemindvajset. In nadzornik jim je bil Zabdiel, sin Hagedolimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 15, 'In iz levitov: Semaja, sin Hašuba, sinu Azrikama, sinu Hasabija, sinu Bunija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 16, 'in Sabetaj in Jozabad, iz levitskih načelnikov, ki sta bila nad zunanjim delom pri hiši Božji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 17, 'in Matanija, sin Mika, sinu Zabdija, sinu Asafa, ki je bil vodja in je začenjal hvalopetje ob molitvi; in Bakbukija, drugi med svojimi brati, in Abda, sin Samua, sinu Galala, sinu Jedutuna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 18, 'Vseh levitov v svetem mestu je bilo dvesto štiriinosemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 19, 'Dalje vratarji, Akub, Talmon in njiju bratov, ki so čuvali pri vratih, je bilo sto dvainsedemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 20, 'Drugi Izraelci pa, duhovniki in leviti, so bili po vseh mestih Judovih, vsak na svojem posestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 21, 'A Netinimci so prebivali na Ofelu, in Ziha in Gispa sta bila nad Netinimci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 22, 'In v Jeruzalemu je bil nadzornik levitom Uzi, sin Banija, sinu Hasabija, sinu Matanija, sinu Mika, iz sinov Asafovih, pevcev za službo hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 23, 'Kajti bila je zapoved kraljeva o njih in določen živež pevcem, kolikor je bilo vsak dan treba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 24, 'In Petahija, sin Mesezabelov, iz sinov Zeraha, sinu Judovega, je bil kralju pri roki v vsem, kar je zadevalo ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 25, 'In po vaseh na svojem polju so prebivali nekateri sinov Judovih v Kirjat-arbi in njenih podložnih selih in v Dibonu in njemu podložnih vaseh in v Jekabzeelu in njemu podložnih vaseh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 26, 'in v Jesui in v Moladi in Betpeletu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 27, 'in v Hazar-sualu in v Bersebi in njenih podložnih vaseh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 28, 'in v Ziklagu in v Mekoni in v njenih podložnih vaseh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 29, 'in v En-rimonu in v Zori in v Jarmutu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 30, 'v Zanoahu, v Adulamu in njemu podložnih vaseh, v Lahisu in na njegovem polju, v Azeki in njenih podložnih vaseh. In šatorili so od Bersebe do doline Hinomove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 31, 'Sinovi Benjaminovi so tudi prebivali od Gebe naprej v Mikmasu in v Aju in v Betelu in njegovih podložnih vaseh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 32, 'v Anatotu, Nobu, Ananiji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 33, 'Hazorju, Rami, Gitaimu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 34, 'Hadidu, Zeboimu, Nebalatu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 35, 'Lodu in v Onu, dolini obrtnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 11, 36, 'In od levitov nekateri oddelki Judovi so se pridružili Benjaminu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 1, 'Ti pa so duhovniki in leviti, ki so šli gori z Zerubabelom, sinom Sealtielovim, in z Jesuom: Seraja, Jeremija, Ezra,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 2, 'Amarija, Maluk, Hatuš,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 3, 'Sekanija, Rehum, Meremot,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 4, 'Ido, Ginetoj, Abija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 5, 'Mijamin, Maadija, Bilga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 6, 'Semaja, Jojarib, Jedaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 7, 'Salu, Amok, Hilkija, Jedaja. Ti so bili poglavarji duhovnikov in njih bratov v dneh Jesujevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 8, 'Dalje leviti: Jesua, Binuj, Kadmiel, Serebija, Juda in Matanija, ki je s svojimi brati vodil hvalopetje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 9, 'in Bakbukija in Uno, njih brata, sta jim bila nasproti, po svojih stražah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 10, 'In Jesua je rodil Jojakima, in Jojakim je rodil Eliasiba, Eliasib pa je rodil Jojada,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 11, 'Jojada pa je rodil Jonatana, Jonatan pa je rodil Jadua.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 12, 'In v dnevih Jojakima so bili duhovniki, poglavarji očetovin: Serajeve je bil Meraja, Jeremijeve: Hananija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 13, 'Ezrove: Mesulam, Amarijeve: Johanan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 14, 'Malukijeve: Jonatan; Sebanijeve: Jožef,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 15, 'Harimove: Adna, Merajotove: Helkaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 16, 'Idove: Zeharija, Ginetonove: Mesulam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 17, 'Abijeve: Zihri, Miniaminove... Moadijeve: Piltaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 18, 'Bilgove: Samua, Semajeve: Jonatan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 19, 'Jojaribove: Matenaj, Jedajeve: Uzi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 20, 'Salajeve: Kalaj, Amokove: Heber,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 21, 'Hilkijeve: Hasabija, Jedajeve: Netanel. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 22, 'V dneh Eliasiba, Jojada, Johanana in Jadua so bili zapisani poglavarji očetovin levitov in duhovnikov, ob vladanju Darija Peržana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 23, 'Sinovi Levijevi, poglavarji očetovin, so bili zapisani v knjigi letopisov, do dni Johanana, sinu Eliasibovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 24, 'In poglavarji levitov: Hasabija, Serebija in Jesua (sin) Kadmiela in njih bratje, njim nasproti, da hvalijo in zahvaljujejo po zapovedi Davida, moža Božjega, službeni oddelki drug za drugim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 25, 'Matanija in Bakbukija, Obadija, Mesulam, Talmon, Akub so bili vratarji, stoječi na straži pri skladiščih ob vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 26, 'Ti so bili v dneh Jojakima, sinu Jesua, sinu Jozadaka, in v dneh Nehemija, deželnega oblastnika, in Ezra duhovnika, pismouka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 27, 'In ob posvečevanju obzidja jeruzalemskega so poiskali levite iz vseh njih mest, da bi jih pripeljali v Jeruzalem, da se praznuje posvečevanje z veseljem in z zahvaljevanjem in s petjem, s cimbali, s psalmovimi strunami in s harfami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 28, 'In sinovi pevcev so se zbrali iz vse okolice jeruzalemske in tudi iz netofatskih vasi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 29, 'in iz Betgilgala in s poljan Gebe in Azmaveta; zakaj pevci so si zgradili sela okoli Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 30, 'In duhovniki in leviti so se očistili, in očistili so ljudstvo in vrata in obzidje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 31, 'In velel sem knezom Judovim stopiti na obzidje, in postavil sem dva velika zahvalna zbora in priredil obhod: eden je šel na desno, gori po obzidju, proti Gnojnim vratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 32, 'In za njimi je šel Hosaja in polovica knezov Judovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 33, 'in Azarija, Ezra, Mesulam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 34, 'Juda, Benjamin, Semaja in Jeremija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 35, 'in nekoliko duhovniških sinov s trobentami: Zeharija, sin Jonatana, sinu Semaja, sinu Matanija, sinu Mika, sinu Zakurija, sinu Asafa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 36, 'in bratje njegovi: Semaja, Azarel, Milalaj, Gilalaj, Maaj, Netanel, Juda, Hanani, z glasbili Davida, moža Božjega, in Ezra pismouk je bil pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 37, 'In šli so proti Studenčnim vratom, in so stopali naravnost naprej po stopnicah mesta Davidovega, koder se hodi gori na zid, zgoraj nad Davidovo hišo, prav do Vodnih vrat proti vzhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 38, 'Drugi zahvalni zbor pa jim je šel naproti, in jaz za njim s polovico ljudstva, vrhu obzidja, nad Pečnim stolpom ven do širokega zidu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 39, 'in nad Efraimovimi vrati in čez Stara vrata in čez Ribja vrata in stolp Hananel in stolp Mea tja do Ovčjih vrat, in obstali so pri vratih jetnišnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 40, 'Tako sta stala obadva zahvalna zbora ob hiši Božji in jaz in polovica načelnikov ljudstva z menoj –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 41, 'in duhovniki: Eliakim, Maaseja, Minjamin, Mihaja, Eljoenaj, Zeharija in Hananija s trobentami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 42, 'in Maaseja, Semaja, Eleazar, Uzi, Johanan, Malkija, Elam in Ezer. In pevci so glasno peli, in Jizrahija je bil njih vodja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 43, 'In tisti dan so darovali velike žrtve in se veselili; kajti Bog jih je obveselil z veliko radostjo, da so se tudi žene in otroci veselili. In jeruzalemsko veselje se je daleč slišalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 44, 'V tistem času so bili možje postavljeni čez shrambe za zaklade, za dari povzdignjenja, za prvine in za desetine, da spravljajo vanje po obmestnih njivah, deleže, določene po postavi za duhovnike in levite; zakaj Juda se je veselil duhovnikov in levitov, ki so stali v službi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 45, 'In stregli so v straži Boga svojega in pazili na očiščevanje; enako tudi pevci in vratarji, po zapovedi Davida in Salomona, sinu njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 46, 'Kajti nekdaj v dneh Davidovih in Asafovih, so bili načelniki pevcev in hvalopetja in zahvale Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 12, 47, 'In ves Izrael je v dneh Zerubabelovih in v dneh Nehemijevih dajal delež pevcem in vratarjem, kolikor je bilo treba vsak dan; in so del tega posvečevali levitom, in leviti so del posvečevali sinovom Aronovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 1, 'Tisti čas se je čitalo pred ušesi ljudstva v knjigi Mojzesovi, in se je našlo pisano v njej, da ne sme Amonec in Moabec priti v zbor Božji vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 2, 'zato ker niso prišli naproti sinovom Izraelovim s kruhom in z vodo, temuč so zoper nje najeli Balaama, da bi jih proklel; toda naš Bog je kletev preobrnil v blagoslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 3, 'In ko so slišali postavo, so ločili izmed Izraela vse mešano ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 4, 'Pred tem pa je duhovnik Eliasib, ki je bil postavljen nad shrambami hiše našega Boga, ker je bil po rodu zvezan s Tobijem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 5, 'pripravil njemu veliko shrambo, kamor so bili poprej polagali jedilne daritve, kadilo in posode in desetine žita, vina in olja, po zapovedi pristojne levitom, pevcem in vratarjem, tudi dari povzdignjenja za duhovnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 6, 'Ali ob vsem tem nisem bil v Jeruzalemu. Zakaj v dvaintridesetem letu Artakserksa, kralja babilonskega, sem šel h kralju; in čez nekoliko dni sem si izprosil dopust od kralja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 7, 'in ko sem dospel v Jeruzalem, sem opazil zlo, ki ga je bil storil Eliasib Tobiju na voljo s tem, da mu je pripravil shrambo na dvorišču hiše Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 8, 'In bilo mi je silno žal, in sem pometal vse stvari hiše Tobijeve iz shrambe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 9, 'Nato sem ukazal, in očistili so shrambe, in sem zopet vanje znosil posode hiše Božje, jedilne daritve in kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 10, 'In zvedel sem, da niso dajali levitom njih deležev, in da so se zato umeknili leviti in pevci, ki so opravljali posel, vsak na svojo njivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 11, 'Tedaj sem okaral načelnike in sem dejal: Zakaj je zapuščena hiša Božja? In sklical sem one ter jih postavil na njih mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 12, 'Tedaj je prinesel ves Juda desetino žita in vina in olja v založne shrambe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 13, 'In za paznike nad zalogami sem postavil Selemija duhovnika in Zadoka pismouka in izmed levitov Pedaja in njim v pomoč Hanana, sina Zakurja, sinu Matanija; zakaj oni so bili šteti za zveste, in bilo jim je poverjeno, da delijo svojim bratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 14, 'Spominjaj se mi tega, o Bog moj, in ne izbriši mojih del usmiljenja, ki sem jih storil pri Boga svojega hiši in za postrežbo pri njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 15, 'Tisti čas sem videl v Judeji, da so nekateri ob soboti tlačili tlačilnice in spravljali snopovje in ž njimi obkladali osle, pa tudi z vinom, z grozdjem in s smokvami in z vsakršnimi tovori, ki so jih prinašali v Jeruzalem ob sobotnem dnevi. In posvaril sem jih tisti dan, ko so prodajali živež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 16, 'Tudi so prebivali v mestu Tirci, ki so prinašali ribe in različno blago ter prodajali ob sobotah sinovom Judovim in v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 17, 'Tedaj sem okaral plemenitnike Judove in jim dejal: Kakšna je to huda razvada, ki jo imate, da oskrunjate sobotni dan?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 18, 'Niso li vaši očetje delali tudi tako, in ni li spravil Bog naš vseh teh nesreč nad nas in nad to mesto? In vi pripravljate še več srda nad Izraela s tem, da oskrunjate soboto!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 19, 'In ko se je začelo mračiti med vrati Jeruzalema pred soboto, velel sem, naj zapro duri, in naročil, da jih smejo odpreti šele po soboti; in nekatere svoje hlapce sem postavil, da bi se ne prinesla nobena butara v mesto ob sobotnem dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 20, 'Tedaj so kramarji in prodajalci raznovrstnega blaga ostali čez noč zunaj pred Jeruzalemom, enkrat ali dvakrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 21, 'In okaral sem jih in jim dejal: Zakaj ostajate čez noč okoli obzidja? Ako še enkrat to storite, položim na vas roko! Od tega časa niso več prišli v soboto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 22, 'In ukazal sem levitom, naj se očistijo in pridejo stražit vrata, da bi se sobotni dan posvečeval. Tudi tega se mi spominjaj, o Bog moj, in prizanesi mi po veliki milosti svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 23, 'Tudi sem videl v tistem času Jude, ki so se poročili z ženami iz Asdoda, Amona in Moaba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 24, 'in njih otroci so polovico govorili asdotski in niso znali po judovsko, temuč govorili so po jeziku tega ali onega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 25, 'In sem jih karal in klel ter nekatere izmed njih sem tepel in jim ruval lase, in velel sem jim priseči pri Bogu, da ne bodo dajali hčer svojih njih sinovom, ne jemali njih hčer sinom svojim ali sami sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 26, 'Ni li grešil zaradi tujk Salomon, kralj Izraelov? In vendar mu ni bilo med mnogimi narodi enakega kralja, in ljub je bil svojemu Bogu, in Bog ga je postavil za kralja vsemu Izraelu: a celo njega so zapeljale tuje žene v greh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 27, 'In naj li poslušamo vas, ki delate tako veliko zlo in nezvesto ravnate zoper Boga svojega, ko se poročate z drugorodnimi ženami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 28, 'In eden izmed sinov Jojada, sinu Eliasibovega, velikega duhovnika se je bil posvačil s Sanbalatom Horončanom; zato sem ga odgnal od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 29, 'Spominjaj se jih, o Bog moj, da so onečistili duhovništvo in zavezo duhovništva in levitov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 30, 'Tako sem jih očistil vsega tujega in postavil službena opravila duhovnikov in levitov, vsakega k svojemu poslu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (16, 13, 31, 'in sem oskrbel, da se prinašajo drva ob določenih časih in prvine. Spominjaj se me, o Bog moj, meni v dobro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 1, 'In zgodi se v dneh Ahasvera (to je tisti Ahasver, ki je kraljeval od Indije do Etiopije nad sto in sedemindvajsetimi pokrajinami),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 2, 'v tistih dneh, ko je sedel kralj Ahasver na kraljestva svojega prestolu, ki je bil v gradu Susanskem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 3, 'v tretjem letu vladanja svojega, da je napravil gostovanje vsem knezom in hlapcem svojim: vojaštvo Perzije in Medije, plemenitniki in pokrajinski poglavarji so bili zbrani pred njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 4, 'ko jim je dal videti bogastvo slavnega kraljestva svojega in dragoceno sijajnost veličastva svojega mnogo dni, namreč sto in osemdeset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 5, 'In ko so se dopolnili ti dnevi, je kralj naredil gostovanje vsemu ljudstvu, ki je bilo navzočno v Susanu v gradu, velikim in malim, sedem dni, na dvorišču ob vrtu pri kraljevi palači.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 6, 'Beli in škrlatnomodri bombaževi zastori so bili razobešeni z vrvicami iz bele tenčice in škrlata na srebrnih obročkih in na marmornih stebrih; počivalnice iz zlata in srebra so stale na tleh, vloženih z zelenim in belim marmorjem in z bisernjakom in s črnim marmorjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 7, 'In piti so jim dajali iz zlatih posod, in posode so bile vselej druge in druge, in kraljevega vina je bilo obilo po kraljevi darežljivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 8, 'In pitje je bilo po redu, ne da bi bil kdo silil; zakaj tako je kralj naročil vsem upravnikom hiše svoje, da naj vsakemu store, kakor mu je všeč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 9, 'Tudi kraljica Vasti je napravila gostovanje ženam v kraljevi hiši, ki je bila kralja Ahasvera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 10, 'In sedmi dan, ko je bil kralj dobre volje od vina, je velel Mehumanu, Biztu, Harbonu, Bigtu, Abagtu, Zetarju in Karkasu, sedmim komornikom, ki so služili pred kraljem Ahasverom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 11, 'naj predenj pripeljejo kraljico Vasto s kraljevsko krono, da bi pokazal ljudstvom in knezom nje lepoto, zakaj lepa je bila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 12, 'Ali kraljica Vasti ni hotela priti po kraljevi besedi, ki so jo sporočili komorniki. Zato se kralj razsrdi in jeza se razvname v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 13, 'Tedaj veli kralj modrijanom, ki so bili vešči časom (kajti tako se je reševala vsaka stvar kraljeva vpričo vseh, ki so znali zakon in pravo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 14, 'in njemu najbližji so bili Karsena, Setar, Admata, Tarsis, Meres, Marsena in Memukan, sedmero vojvod Perzije in Medije, ki so gledali obličje kraljevo in na prvem mestu sedeli v kraljestvu):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 15, 'Kaj je storiti po zakonu kraljici Vasti, ker ni izvršila povelja kralja Ahasvera, ki so ga sporočili komorniki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 16, 'In Memukan odgovori pred kraljem in vojvodami: Kraljica Vasti se ni pregrešila samo zoper kralja, ampak tudi zoper vse kneze in zoper vsa ljudstva, kar jih je v vseh pokrajinah kralja Ahasvera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 17, 'Kajti to dejanje kraljice se raznese do vseh žen in bodo prezirale svoje može, ko se bo pravilo: Kralj Ahasver je velel kraljici Vasti, naj pride predenj, ali ni prišla!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 18, 'In še danes bodo kneginje v Perziji in Mediji, ki so slišale o kraljičinem dejanju, pravile isto vsem kraljevim knezom; odtod bode dosti zaničevanja in srda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 19, 'Ako se zdi kralju dobro, naj izide njegovo povelje in bodi zapisano v postave Peržanov in Medov nepremenljivo: Da ne sme Vasti priti več pred kralja Ahasvera. In kralj naj da njeno kraljevo dostojanstvo drugi, ki je boljša nego ona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 20, 'In ko se zasliši kraljev razglas, ki ga izda, po vsej kraljevini njegovi (kajti je velika), bodo spoštovale vse žene svoje može, od velikega do malega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 21, 'Ta nasvet se je videl dober kralju in knezom; in kralj je storil po besedi Memukanovi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 1, 22, 'kajti poslal je liste v vse kraljeve pokrajine, v vsako pokrajino po njenem pismu in vsakemu ljudstvu po njegovem jeziku, da naj bode vsak mož v hiši svoji gospodar in govori po jeziku ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 1, 'Po teh dogodbah, ko se je pomiril srd kralja Ahasvera, se je spomnil Vaste in kar je bila storila in kar je bilo zanjo določeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 2, 'Tedaj mu reko hlapci kraljevi, ki so mu stregli: Naj se kralju poiščejo mladenke, device, lepega obraza;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 3, 'in kralj naj postavi pooblaščence v vseh pokrajinah kraljevine svoje, da naj zbero vse lepe mladenke, device, v grad Susan v žensko hišo pod roko Hegaja, kraljevega komornika, varuha žen, in naj se jim dado potrebščine za očiščevanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 4, 'in katera devica se bo priljubila kralju, ta bodi kraljica namesto Vaste. Ta nasvet se je zdel dober kralju, in storil je tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 5, 'Bil je v gradu Susanu neki Jud, njega ime Mardohej, sin Jaira, sinu Simeja, sinu Kisa, Benjaminec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 6, 'ki je bil odpeljan iz Jeruzalema z jetniki, kateri so bili na tuje odgnani z Jekonijem, kraljem Judovim, ki jih je peljal v ujetništvo Nebukadnezar, kralj babilonski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 7, 'Ta je redil Hadaso (ta je Estera), svojega strica hčer; zakaj ni imela ne očeta, ne matere. In ta mladenka je bila lepe postave in zalega obraza. In ko sta bila umrla njen oče in mati, si jo je Mardohej vzel za hčer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 8, 'In tako se zgodi, ko se je razglasila beseda kraljeva in njegova zapoved in ko so veliko deklic zbrali v grad Susan pod roko Hegajevo, da vzemo tudi Estero v kraljevo hišo pod varstvo Hegaja, varuha žen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 9, 'In deklica mu je ugajala in našla milost pred njim. In podvizal se je, da ji da njene potrebščine za očiščevanje in njene deleže in sedem deklet, ki so bile zanjo izbrane iz kraljeve hiše; in prestavil jo je ž njenimi deklicami v najboljši kraj ženske hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 10, 'Estera pa ni naznanila ljudstva svojega, ne rodovine svoje, zakaj Mardohej ji je bil zapovedal, naj tega ne pove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 11, 'In Mardohej se je vsak dan izprehajal pred dvoriščem ženske hiše, da bi zvedel, ali se dobro vede Esteri in kaj se ž njo godi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 12, 'Ko pa je prišla vrsta posamezni deklici, da bi šla noter h kralju Ahasveru, potem ko so ji bili delali po določilu za žene dvanajst mesecev (kajti tako so se dopolnjevali dnevi njih očiščevanja, namreč šest mesecev z mirovim oljem in šest mesecev z dišavami in s čistilnimi mazili za ženske),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 13, 'tedaj je šla deklica h kralju; karkoli je želela, ji je bilo dano, da s tem odičena gre iz hiše ženske v hišo kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 14, 'Zvečer je šla in zjutraj se je vrnila v drugo žensko hišo pod roko Saasgaza, kraljevega komornika, ki je varoval priležnice; ni šla več h kralju, razen če si jo je kralj priljubil in je bila poklicana po imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 15, 'Ko pa je prišla vrsta na Estero, hčer Abihaila, strica Mardohejevega, ki si jo je bil vzel za hčer, ni zahtevala ničesar, samo kar je rekel Hegaj, komornik kraljev, varuh žen. In Estera si je pridobila milost v očeh vseh, ki so jo gledali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 16, 'Estera je bila torej vzeta h kralju Ahasveru, v njegovo hišo kraljevo, v desetem mesecu, ki je mesec Tebet, v sedmem letu njegovega kraljevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 17, 'In kralj je ljubil Estero mimo vseh žen, in pridobila si je naklonjenost in milost v očeh njegovih bolj nego vse device, tako da ji je bil posadil kraljičino krono na glavo in jo storil za kraljico namesto Vaste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 18, 'Tedaj je kralj napravil veliko gostovanje vsem svojim knezom in hlapcem svojim, Esterine gostí; in napravil je praznovanje po pokrajinah in delil darove s kraljevo darežljivostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 19, 'In ko so v drugič zbirali device, je sedel Mardohej med kraljevimi vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 20, 'Estera pa še ni naznanila rodovine svoje, ne ljudstva svojega, kakor ji je bil zapovedal Mardohej; kajti Estera se je ravnala po povelju Mardohejevem, kakor ko je bila v njegovi odgoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 21, 'V tistih dneh, ko je Mardohej sedel med kraljevimi vrati, sta se ujezila dva kraljeva komornika, Bigtan in Teres, iz tistih, ki so čuvali vrata, in sta mislila položiti roke na kralja Ahasvera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 22, 'To je zvedel Mardohej in povedal kraljici Esteri, Estera pa je naznanila kralju v imenu Mardohejevem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 2, 23, 'In ko se je stvar preiskala in dokazala, so oba obesili na drevje, in zapisano je bilo v knjigo letopisov pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 1, 'Po teh dogodbah je kralj Ahasver velikega storil Hamana, sina Hamedata, Agagejca, in ga je povišal ter postavil stol njegov nad vse kneze, ki so bili pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 2, 'In vsi hlapci kraljevi, ki so bili ob kraljevih vratih, so pripogibali kolena in padali na tla pred Hamanom, kajti tako je bil kralj zapovedal za njega. Ali Mardohej ni pripogibal kolen in ni padal na tla pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 3, 'Tedaj reko kraljevi hlapci, ki so bili ob kraljevih vratih, Mardoheju: Zakaj prestopaš kraljevo zapoved?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 4, 'In ko so mu tako vsak dan govorili in jih on ni slušal, naznanijo to Hamanu, da bi videli, bodo li obstale besede Mardohejeve; zakaj bil je jim povedal, da je Jud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 5, 'In ko je videl Haman, da Mardohej ne pripogiba kolen in se mu ne klanja do tal, se je ves razsrdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 6, 'A zdelo se mu je premalo, da se loti Mardoheja samega; zakaj oznanili so mu, katerega ljudstva je Mardohej; zato je nameraval pokončati vse Jude, ki so bili po vsej kraljevini Ahasverovi, narod Mardohejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 7, 'V prvem mesecu, ki je mesec Nisan, v dvanajstem letu kralja Ahasvera, so vrgli pur, to je žreb, pred Hamanom, vrgli so ga od dne do dne, od meseca do meseca, in zadeli so dvanajsti mesec, ki je mesec Adar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 8, 'In Haman reče kralju Ahasveru: Neko ljudstvo živi razkropljeno in zase ločeno med ljudstvi po vseh deželah kraljestva tvojega, in njega postave so drugačne nego vseh ljudstev, in po kraljevih postavah se ne ravna; zato ni kralju v prid, če ga trpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 9, 'Ako je kralju ugodno, piši, da naj ga pogube; in jaz odtehtam deset tisoč talentov srebra v roke tistim, ki oskrbujejo kraljeva opravila, da ga neso v kraljevo zakladnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 10, 'Tedaj si sname kralj prstan z roke ter ga da Hamanu, sinu Hamedata, Agagejcu, nasprotniku Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 11, 'In kralj reče Hamanu: Srebro bodi dano tebi, tudi tisto ljudstvo, da se ž njim stori, kar se ti dobro vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 12, 'Nato pokličejo kraljeve pisarje trinajsti dan v prvem mesecu, in napisalo se je po vsem, kakor je velel Haman, namestnikom kraljevim in oblastnikom, ki so bili nad vsako pokrajino, in knezom vsakega ljudstva, za vsako pokrajino po njeni pisavi in vsakemu ljudstvu v njegovem jeziku; v imenu kralju Ahasvera je bilo pisano in zapečateno s kraljevim prstanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 13, 'In listi so bili poslani po hitrih slih v vse kraljeve pokrajine, da naj pokončajo, pomore in pogube vse Jude, mlade in stare, otročiče in žene, enega dne, na trinajsti dan dvanajstega meseca, ki je mesec Adar, in naj zaplenijo njih imetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 14, 'In da bi se povelje izdalo v vsaki posamezni pokrajini, so objavili vsebino lista vsem ljudstvom, da naj bodo pripravljeni na ta dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 3, 15, 'Brzi sli so hitro šli po besedi kraljevi, ko je bilo povelje izdano v Susanu v palači. Kralj in Haman pa sta sedla, da pijeta, mesto Susan pa je bilo zbegano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 1, 'Ko je Mardohej zvedel, kaj se je zgodilo, raztrga svojo obleko in se ogrne z raševnikom in potrese s pepelom in gre ven v mesto ter vpije glasno in bridko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 2, 'In pride prav do vrat kraljevih; kajti nihče ni smel stopiti skozi vrata kraljeva, oblečen v raševnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 3, 'In v vsaki pokrajini, kamorkoli je dospelo kraljevo povelje in njegov ukaz, je bila velika žalost med Judi, in postili so se in plakali in jadikovali ter mnogi so ležali na raševini in pepelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 4, 'In Esterine dekle in njeni komorniki so prišli in so ji povedali o Mardoheju, in kraljica se je silno prestrašila. In pošlje oblačila, da bi se Mardohej vanje preoblekel in raševino dejal od sebe; on jih pa ni sprejel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 5, 'Tedaj pokliče Estera Hataha, enega kraljevih komornikov, ki ga ji je kralj dal v postrežbo, in mu naroči, naj gre k Mardoheju in zve, kaj je to in čemu tako dela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 6, 'Hatah torej gre ven k Mardoheju na mestni trg, ki je bil pred kraljevimi vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 7, 'In Mardohej mu pove vse, kar se mu je prigodilo, in število srebra, ki ga je Haman obljubil odtehtati v kraljevo zakladnico za Jude, da jih pogube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 8, 'Dal mu je tudi prepis lista s poveljem, ki je bilo izdano v Susanu, da se pokončajo, naj ga pokaže Esteri in ji to naznani ter naj ji veli, da gre noter h kralju in ga prosi usmiljenja ter pred obličjem njegovim milo prosi za ljudstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 9, 'In Hatah pride in sporoči Esteri besede Mardohejeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 10, 'Tedaj govori Estera s Hatahom ter mu da sporočilo za Mardoheja, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 11, 'Vsi kraljevi hlapci in ljudje kraljevih pokrajin vedo, da je ena postava za vsakega, bodisi mož ali žena, ki bi vstopil h kralju v notranji dvor, ne da bi bil poklican, da tak mora umreti, razen tistega, proti kateremu seže kralj z zlatim žezlom, da ostani živ. A jaz nisem bila pozvana, naj pridem noter h kralju, že trideset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 12, 'In sporoče Mardoheju besede Esterine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 13, 'Mardohej pa veli odgovoriti Esteri: Ne misli pri sebi, da se otmeš v kraljevi hiši sama mimo vseh Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 14, 'Kajti ako boš docela molčala v tem času, pride olajšava in rešitev Judom iz drugega kraja, ti pa in očeta tvojega hiša bosta pokončani. In kdo ve, ali nisi za tak čas, kakršen je sedaj, dosegla kraljestva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 15, 'Nato veli Estera odgovoriti Mardoheju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 16, 'Pojdi, zberi vse Jude, ki bivajo v Susanu, in postite se zame, da ne jeste in ne pijete tri dni, ne dan, ne noč; tudi jaz s svojimi deklami se bomo enako postile. In potem pojdem noter h kralju, dasi ni po postavi; in ako poginem, naj poginem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 4, 17, 'Odšel je torej Mardohej in storil vse, prav kakor mu je velela Estera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 1, 'In zgodi se tretji dan, da se Estera obleče v svoje kraljevsko oblačilo in stopi v notranji dvor kraljeve hiše, nasproti hiši kraljevi; kralj pa je sedel na svojega kraljestva prestolu v kraljevi palači, proti vhodu v hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 2, 'In ko je kralj zagledal kraljico Estero na dvoru stoječo, je dobila milost v očeh njegovih; in kralj seže proti Esteri z zlatim žezlom, ki ga je imel v roki. In Estera pristopi in se dotakne žezla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 3, 'Tedaj ji kralj reče: Kaj ti je, kraljica Estera? in kaj je prošnja tvoja? Do polovice kraljestva ti bo dano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 4, 'In Estera reče: Ako je kralju všeč, naj pride kralj s Hamanom danes k obedu, ki sem ga zanj pripravila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 5, 'Nato veli kralj: Hitro poskrbite, da Haman stori, kakor je rekla Estera! Prideta torej kralj in Haman k obedu, ki ga je bila pripravila Estera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 6, 'Ko so potem pili vino, vpraša kralj Estero: Kaj je prošnja tvoja? ker dano ti bo. In česa želiš? Do polovice kraljestva, in zgodi se ti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 7, 'Nato odgovori Estera in reče: Moja prošnja in moja želja je:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 8, 'Ako sem našla milost pred kraljem in ako kralj blagovoli uslišati prošnjo mojo ter izpolniti željo mojo, naj prideta kralj in Haman k obedu, ki ga jima pripravim, in jutri storim, kakor je kralj dejal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 9, 'In Haman odide tisti dan vesel in dobre volje. Ali ko vidi Haman Mardoheja med kraljevimi vrati, da ni vstal niti se zganil pred njim, se raztogoti zoper Mardoheja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 10, 'Ali vendar se zdrži, in ko pride domov, pošlje in skliče k sebi prijatelje svoje in Zereso, ženo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 11, 'In Haman jim razklada slavo svojega bogastva in koliko ima sinov in vse, s čimer ga je kralj poveličal in kako ga je povzdignil nad kneze in služabnike kraljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 12, 'Dalje reče Haman: Tudi kraljica Estera ni pozvala nikogar s kraljem na obed, ki ga je pripravila, nego samo mene; pa tudi jutri sem s kraljem povabljen k njej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 13, 'A tega vsega mi ni zadosti, dokler vidim Mardoheja, tistega Juda, sedečega med kraljevimi vrati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 5, 14, 'Nato mu reče Zeresa, žena njegova, in vsi prijatelji njegovi: Naj se napravijo vislice, petdeset komolcev visoke, in zjutraj reci kralju, naj obesijo nanje Mardoheja; potem pojdeš vesel s kraljem k obedu! In to je ugajalo Hamanu, in velel je pripraviti vislice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 1, 'Tisto noč ni mogel kralj spati, in ukaže, naj prineso spominsko knjigo letopisov; in brali so jo pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 2, 'In najdejo zapisano, da je Mardohej ovadil Bigtana in Teresa, dva kraljevih komornikov, iz tistih, ki so čuvali vrata, kako sta hotela položiti roke na kralja Ahasvera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 3, 'In kralj reče: Kaka čast in odlika se je podelila za to Mardoheju? Nato odgovore kraljevi hlapci, ki so mu stregli: Nič se mu ni podelilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 4, 'In kralj vpraša: Kdo je na dvoru? Haman pa je ravnokar prišel na zunanji dvor kraljeve palače, da ogovori kralja, naj obesijo Mardoheja na vislice, ki jih je pripravil zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 5, 'In kraljevi hlapci mu reko: Glej, Haman stoji na dvoru! Kralj veli: Naj stopi sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 6, 'In ko Haman pristopi, mu kralj reče: Kaj naj se zgodi možu, ki ga kralj želi počastiti? Haman pa je mislil v srcu svojem: Koga bi sicer kralj želel počastiti nego mene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 7, 'In reče Haman kralju: Možu, ki ga kralj želi počastiti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 8, 'naj prineso kraljevsko oblačilo, ki ga kralj nosi, in privedo konja, na katerem jezdi kralj, in na glavo naj se mu posadi kraljev venec;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 9, 'in oblačilo in konj naj se dasta v roko enemu najodličnejših knezov kraljevih, da ž njim oblečejo moža, ki ga kralj želi počastiti, in ga posade na konja in vodijo po mestnih ulicah ter kličejo pred njim: Tako se godi možu, ki ga kralj želi počastiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 10, 'In kralj veli: Hiti, vzemi oblačilo in konja, kakor si rekel, in tako stori Mardoheju Judu, ki sedi ob kraljevih vratih. Ne opusti ničesar, kar si govoril!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 11, 'Tedaj vzame Haman oblačilo in konja ter obleče Mardoheja in ga spremlja, jezdečega po mestnih ulicah, in kliče pred njim: Tako se godi možu, ki ga kralj želi počastiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 12, 'In Mardohej se zopet vrne k vratom kraljevim; Haman pa hiti domov žalosten in z zakrito glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 13, 'In Haman pripoveduje Zeresi, ženi svoji, in vsem prijateljem svojim vse, kar se mu je prigodilo. Tedaj mu reko modrci njegovi in Zeresa, žena njegova: Ako je Mardohej, pred katerim si začel padati, iz semena Judov, ničesar ne premoreš zoper njega, temuč gotovo boš padel pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 6, 14, 'Ko so še ž njim govorili, pridejo kraljevi komorniki, in mudi se jim, da odvedo Hamana k obedu, ki ga je Estera pripravila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 1, 'Prideta torej kralj in Haman gostit se pri kraljici Esteri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 2, 'In kralj zopet vpraša Estero drugi dan, ko so pili vino: Kaj je prošnja tvoja, kraljica Estera? in dano ti bo. In česa želiš? Do polovice kraljestva, in zgodi se ti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 3, 'Tedaj odgovori kraljica Estera in reče: Ako sem našla milost v očeh tvojih, o kralj, in ako se kralju vzvidi: Dano mi bodi moje življenje za prošnjo mojo in moje ljudstvo za željo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 4, 'Zakaj prodani smo, jaz in ljudstvo moje, da nas pokončajo, pomore in pogube. In ako bi nas bili prodali vsaj za sužnje in sužnice, bi molčala, dasi bi zatiralec ne mogel kralju povrniti škode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 5, 'In deje kralj Ahasver in reče kraljici Esteri: Kdo pa je ta in kje je ta, ki ga je obvladalo zlobno srce njegovo, da to stori?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 6, 'In Estera reče: Zatiralec in sovražnik je tale hudobni Haman. Tedaj se Haman prestraši pred kraljem in pred kraljico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 7, 'In kralj vstane v jezi svoji od pitja vina in gre na vrt pri palači. Haman pa ostane, da prosi kraljico Estero za življenje svoje: zakaj videl je, da mu je že pripravljeno hudo od kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 8, 'V tem se vrne kralj z vrta pri palači v hišo, kjer so pili vino; Haman pa se je bil zgrudil na počivalnico, na kateri je sedela Estera. Tedaj veli kralj: Hoče li še kraljici silo delati pred menoj v hiši? Komaj je prišla ta beseda kralju iz ust, so Hamanu zagrnili obraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 9, 'V tem reče Harbona, eden komornikov, ki so stali pred kraljem: Saj, glej, stoje pri hiši Hamanovi vislice, katere je Haman naredil za Mardoheja, ki je dobro govoril za kralja. In kralj veli: Obesite ga nanje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 7, 10, 'In obesili so Hamana na vislice, ki jih je bil pripravil za Mardoheja. In srd kraljev se je pomiril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 1, 'Tisti dan je podaril kralj Ahasver kraljici Esteri hišo Hamana, nasprotnika Judov. In Mardohej je prišel pred kralja, zakaj Estera je povedala, kaj je on bil njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 2, 'In kralj je snel svoj prstan, ki ga je bil vzel Hamanu, in ga je dal Mardoheju. Estera pa je postavila Mardoheja nad hišo Hamanovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 3, 'In Estera je zopet govorila pred kraljem ter je padla kralju pred noge in ga plakaje prosila, naj uniči zlobnost Hamana Agagejca in njegov naklep, ki ga je nasnoval zoper Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 4, 'Tedaj seže kralj proti Esteri z žezlom zlatim. In Estera vstane in stopi pred kralja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 5, 'in reče: Ako je kralju všeč in ako sem našla milost v očeh njegovih in se stvar vidi kralju prikladna in ako sem mu mila, naj se napiše, da se prekličejo listi z naklepom Hamana, sinu Hamedata, Agagejca, ki jih je napisal, da bi pogubil Jude po vseh pokrajinah kraljevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 6, 'Ker kako bi mogla gledati nesrečo, ki zadene ljudstvo moje? in kako bi mogla videti pogubo rodovine svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 7, 'Nato reče kralj Ahasver kraljici Esteri in Mardoheju Judu: Glej, dal sem Esteri hišo Hamanovo in njega so obesili na vislice, ker je položil roko svojo na Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 8, 'Pišita torej vidva za Jude, kakor se vama zdi prav, v kraljevem imenu in zapečatita s kraljevim prstanom; zakaj pisma, ki je pisano v kraljevem imenu in zapečateno s kraljevim prstanom, nihče ne more preklicati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 9, 'Tedaj so bili poklicani kraljevi pisarji tisti čas, v tretjem mesecu, ki je mesec Sivan, na triindvajseti dan; in bilo je pisano, prav kakor je velel Mardohej, Judom in namestnikom kraljevim in deželskim oblastnikom in knezom v pokrajinah, ki se raztezajo od Indije do Etiopije, stoinsedemindvajset pokrajin, vsaki pokrajini v njeni pisavi in vsakemu ljudstvu v njegovem jeziku, tudi Judom v njih pisavi in v njih jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 10, 'In pisal je v imenu kralja Ahasvera in zapečatil s kraljevim prstanom in razposlal liste po brzih slih, jezdečih na gosposkih konjih, zrejenih v kraljevi kobilarni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 11, 'da je kralj dovolil Judom po vseh mestih, da se zbero in branijo življenje svoje, da pokončajo in pomore in pogube vso vojno moč ljudstva in pokrajin, ki bi napadla nje, njih otročiče in žene, in da zaplenijo njih imetje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 12, 'enega dne po vseh pokrajinah kralja Ahasvera, namreč trinajstega dne dvanajstega meseca, ki je mesec Adar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 13, 'In da bi se povelje izdalo v vsaki posamezni pokrajini, se je objavila vsebina lista vsem ljudstvom, da naj bodo Judje pripravljeni na tisti dan, da se maščujejo nad sovražniki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 14, 'Brzi sli, ki so jezdili na kraljevih konjih, so odšli, podvizaje se po kraljevi zapovedi. In ukaz se je izdal na gradu Susanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 15, 'In Mardohej je šel izpred obličja kraljevega v kraljevskem oblačilu iz modrega škrlata in belega bombaža in z velikim vencem zlatim in s plaščem iz tenčice in škrlata; in mesto Susan je ukalo in se veselilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 16, 'Judom je nastala luč in veselje, radost in čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 8, 17, 'In v vsaki pokrajini in po vseh mestih, kamorkoli je dospelo kraljevo povelje in njegova postava, so imeli Judje veselje in radost, gostijo in praznik. In mnogi izmed ljudstev dežele so postali Judje, kajti strah pred Judi jih je prevzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 1, 'V dvanajstem mesecu pa, ki je mesec Adar, trinajstega dne tega meseca, ko bi se bila imela izvršiti kraljeva beseda in njegovo povelje, tisti dan, ko so se sovražniki Judov nadejali, da jih bodo premogli, se je obrnilo, da so Judje premogli sovražilce svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 2, 'tedaj so se zbrali Judje v mestih svojih po vseh pokrajinah kralja Ahasvera, da polože roko na tiste, ki so iskali njih nesreče. In nihče ni mogel stati pred njimi, zakaj strah pred njimi je obvladal vsa ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 3, 'In vsi knezi pokrajin in kraljevi namestniki in deželski oblastniki in oskrbniki kraljevih opravil so podpirali Jude, kajti navdal jih je strah pred Mardohejem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 4, 'Zakaj Mardohej je bil velik v kraljevi hiši in glas o njem je šel po vseh deželah; kajti mož Mardohej je postajal čimdalje večji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 5, 'In pobili so Judje vse sovražnike svoje z udarci meča in so jih pomorili in pogubili, in po svoji volji so ravnali s sovražilci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 6, 'In v gradu Susanu so Judje pobili in pomorili petsto mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 7, 'In Parsandata, Dalfona, Aspata,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 8, 'Porata, Adalija, Aridata,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 9, 'Parmasta, Arisaja, Aridaja in Vajzata,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 10, 'desetero sinov Hamana, sinu Hamedata, sovražnika Judov, so pobili, ali po plenu niso segli s svojo roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 11, 'Tisti dan so poročali število pomorjenih v gradu Susanu pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 12, 'In reče kralj kraljici Esteri: Judje so pobili in pomorili petsto mož v gradu Susanu in desetero sinov Hamanovih, kaj so pač storili po drugih pokrajinah kraljevih! Pa kaj je prošnja tvoja? ker dano ti bo. In česa želiš še? ker se ti zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 13, 'Tedaj reče Estera: Ako se vzvidi kralju, naj se dovoli Judom, ki so v Susanu, da delajo tudi jutri po današnjem ukazu, desetero sinov Hamanovih pa naj obesijo na vislice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 14, 'In kralj je velel, naj se tako zgodi, in ukaz je bil izdan v Susanu; in deset sinov Hamanovih so obesili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 15, 'In Judje, ki so bili v Susanu, so se zbrali na štirinajsti dan meseca Adarja in pomorili v Susanu tristo mož ali po plenu niso segli s svojo roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 16, 'Drugi Judje pa, ki so živeli po kraljevih pokrajinah, so se zbrali in branili življenje svoje in si pridobili pokoj od svojih sovražnikov ter pobili petinsedemdeset tisoč sovražilcev svojih ali po plenu niso segli s svojo roko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 17, 'trinajsti dan meseca Adarja; in štirinajsti dan meseca so počivali in ga naredili za dan gostovanja in veselja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 18, 'Judje pa, ki so bili v Susanu, so se zbrali trinajsti in štirinajsti dan meseca, in petnajsti dan so počivali ter ga naredili za dan gostovanja in veselja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 19, 'Zato praznujejo Judje, ki stanujejo po deželi v neobzidanih mestih, štirinajsti dan meseca Adarja kot dan veselja in gostovanja in prazničen dan, in pošiljajo darila drug drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 20, 'In Mardohej je spisal te zgodbe in poslal liste vsem Judom, ki so bili po vseh pokrajinah kralja Ahasvera, bližnjim in daljnim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 21, 'naročajoč jim, naj praznujejo štirinajsti dan meseca Adarja in petnajsti dan vsako leto');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 22, 'kot dneva, v katerih so Judje dosegli pokoj od sovražnikov svojih, in kot mesec, v katerem se jim je premenila žalost v veselje in plakanje v prazničen dan; in naj ju postavijo za dneva gostovanja in veselja in pošiljanja daril drug drugemu in podeljevanja ubogim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 23, 'In Judje so sprejeli v izpolnjevanje, kar so bili že začeli in kar jim je pisal Mardohej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 24, 'Kajti Haman, sin Hamedatov, Agagejec, nasprotnik vseh Judov, je skoval naklep zoper Jude, da jih pogube, in je vrgel pur, to je žreb, da jih zatro in pokončajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 25, 'Ko pa je Estera prišla pred kralja, je zapovedal z listi, naj se mu povrne njegov hudobni naklep, ki ga je nasnoval zoper Jude, na glavo njegovo; in obesili so njega in sinove njegove na vislice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 26, 'Zato so imenovali tiste dni purim, po imenu pur. Zategadelj, zaradi vseh besed tega lista in zaradi tega, kar so sami videli iz te reči in kar jih je doletelo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 27, 'so Judje določili in vzeli nase in na seme svoje in na vse, ki se bodo k njim pridružili, kot neminljivo postavo: da bodo praznovali ta dva dneva, kakor je zanju predpisano in njiju čas določen, vsako leto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 28, 'in da se je spominjati teh dni in ju praznovati v slehernem rodu, v sleherni rodbini, v vsaki pokrajini in v vsakem mestu; in da ne smeta ta dneva purima izginiti izmed Judov niti njiju spomin nehati pri njih zarodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 29, 'In kraljica Estera, hči Abihailova, in Mardohej Jud, sta pisala z vsem poudarkom, da se potrdi ta drugi list o purimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 30, 'In poslali so se listi vsem Judom v sto in sedemindvajsetih pokrajinah kraljestva Ahasverovega z besedami miru in resnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 31, 'da se potrdita ta dneva purima v njiju določenih časih, kakor sta jim ukazala Mardohej Jud in kraljica Estera in kakor so si ustanovili zase in za seme svoje, namreč določbo o postih in žalovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 9, 32, 'In ukaz Esterin je potrdil te zadeve purima in zapisano je bilo v knjigo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 1, 'In kralj Ahasver je naložil davek zemlji in otokom na morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 2, 'In vsa dejanja njegove oblasti in moči njegove in natančno poročilo o velikosti Mardohejevi, do katere ga je kralj povzdignil, ni li zapisano v knjigi letopisov kraljev Medije in Perzije?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (17, 10, 3, 'Zakaj Mardohej Jud je bil drugi za kraljem Ahasverom in velik med Judi in priljubljen množici bratov svojih, ker si je prizadeval za dobrine ljudstva svojega in govoril mir vsemu zarodu njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 1, 'Živel je mož v deželi Uzovi, ime mu je bilo Job, in ta mož je bil popoln in pošten, ki se je bal Boga in se varoval hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 2, 'In rodilo se mu je sedem sinov in troje hčer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 3, 'In imel je živine sedem tisoč ovac, tri tisoč velblodov, petsto jarmov volov in petsto oslic in zelo veliko družino. In ta mož je bil imenitnejši od vseh, ki so bivali na Jutrovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 4, 'In sinovi njegovi so hodili in prirejali gostije, vsak v hiši svoji na svoj dan, in so poslali in povabili tri sestre svoje, da bi jedle in pile ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 5, 'In bilo je, ko so minili zaporedoma dnevi njih gostovanja, da je Job poslal ponje in jih posvečeval: vstal je zgodaj zjutraj in daroval žgalne daritve po njih vseh številu; zakaj Job je rekal: Morebiti so se pregrešili sinovi moji in se odrekli Boga v srcu svojem. Tako je delal Job vsekdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 6, 'In zgodi se nekega dne, da pridejo sinovi Božji postavit se pred Gospoda, pa pride tudi satan med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 7, 'Gospod pa reče satanu: Odkod si prišel? Satan odgovori Gospodu in reče: Po zemlji sem letal semtertja in vseokrog jo obhajal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 8, 'In Gospod reče satanu: Si li opazoval hlapca mojega Joba? Kajti njemu ni na zemlji enakega, mož je popoln in pošten, ki se boji Boga in varuje hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 9, 'Tedaj odgovori satan Gospodu in reče: Mar je brez plačila, da se Job boji Boga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 10, 'Nisi li kroginkrog varno ogradil njega in hiše njegove in karkoli ima? Delo njegovih rok si blagoslovil in imetje njegovo se je razraslo po deželi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 11, 'Pa le iztegni roko svojo in se dotakni vsega, kar ima, gotovo se ti v obraz tebe odreče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 12, 'In Gospod veli satanu: Glej, vse, kar ima, v tvoji je roki, samo nanj ne sezi s svojo roko! In ven je šel satan izpred obličja Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 13, 'In zgodi se nekega dne, ko so jedli in pili vino sinovi njegovi in hčere njegove v prvorojenega brata hiši,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 14, 'da pride sel k Jobu in mu reče: Voli so orali in oslice so se pasle poleg njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 15, 'v tem so pridrli Sabejci in jih odgnali, hlapce pa pobili z ostrino meča, in zbežal sem sam edini, da ti to sporočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 16, 'Ta je še govoril, ko pride drugi in reče: Ogenj Božji je šinil z neba in zapalil ovce in hlapce ter jih požgal, in zbežal sem sam edini, da ti sporočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 17, 'Ta je še govoril, ko pride drugi in reče: Kaldejci so naredili tri čete ter naskočili velblode in so jih vzeli ter pobili hlapce z ostrino meča, in zbežal sem sam edini, da ti sporočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 18, 'Ta je še govoril, ko pride drugi ter reče: Sinovi tvoji in hčere tvoje so jedli in vino pili v prvorojenega brata svojega hiši,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 19, 'in glej, pritisne močan veter od puščave sem in butne ob štiri vogle hiše, da se je zrušila na mladino, in mrtvi so; in zbežal sem sam edini, da ti sporočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 20, 'Tedaj vstane Job in raztrga svoj plašč in si obrije glavo ter pade na zemljo in moli');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 21, 'in reče: Gol sem prišel iz telesa matere svoje in gol se povrnem tja; Gospod je dal, Gospod je vzel, Gospodovo ime bodi hvaljeno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 1, 22, 'Pri vsem tem ni grešil Job in ni očital Bogu nič napačnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 1, 'Zopet se zgodi nekega dne, da pridejo sinovi Božji postavit se pred Gospoda, in pride tudi satan med njimi, da se postavi pred Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 2, 'In Gospod reče satanu: Odkod si prišel? Satan pa odgovori Gospodu in reče: Po zemlji sem letal semtertja in vseokrog jo obhajal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 3, 'In Gospod reče satanu: Si li opazoval hlapca mojega Joba? Kajti njemu ni na zemlji enakega, mož je popoln in pošten, ki se boji Boga in varuje hudega; in še se drži popolnosti svoje! Ti pa si me nadražil zoper njega, da ga uničim brez vzroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 4, 'A satan odgovori Gospodu in reče: Kožo za kožo, in vse, kar ima človek, da za življenje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 5, 'Pa le iztegni roko svojo in se dotakni njegovega okostja in mesa, gotovo se ti v obraz tebe odreče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 6, 'Nato veli Gospod satanu: Glej, v tvoji je roki, samo življenje mu ohrani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 7, 'In ven je šel satan izpred obličja Gospodovega, in udaril je Joba s hudimi tvori od stopal do temena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 8, 'In Job vzame čepinjo, da bi se ž njo praskal, in sede sredi pepela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 9, 'Tedaj mu reče žena njegova: Ali se še držiš popolnosti svoje? Odpovej se Bogu in umri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 10, 'On pa ji reče: Govoriš kakor nespametne ženske. Dobro smo li sprejeli od Boga, a ne sprejmemo naj tudi hudega? Pri vsem tem ni grešil Job z ustnicami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 11, 'Ko so pa slišali trije prijatelji Jobovi o vsej tej nesreči, ki ga je bila zadela, pridejo vsak iz kraja svojega: Elifaz Temančan, Bildad Šuhec in Zofar Naamatec, in se dogovore, da ga pojdejo skupaj milovat in tolažit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 12, 'In ko so oddaleč povzdignili oči, ga niso spoznali; in zaženo svoj glas ter plakajo, in vsak raztrga obleko svojo in si potrese prahu na glavo proti nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 2, 13, 'In sedeli so ž njim na tleh sedem dni in sedem noči, in nihče mu ni govoril besede, zakaj videli so, da je njegova bolest silno velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 1, 'Potem odpre Job usta in kolne svoj dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 2, 'In izpregovori Job in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 3, 'Izgine naj dan, ki sem v njem bil rojen, in noč, ki je rekla: Deček je spočet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 4, 'Tisti dan – naj postane teman, ne vprašaj po njem Bog od zgoraj, svit mu ne zasij nikdar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 5, 'Tema in senca smrti naj si ga prisvojita, mrak naj se ušatori nad njim, vse, kar temni dan, naj ga prestraši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 6, 'Tista noč – tema jo prevzemi, naj se ne veseli med dnevi leta, naj ne pride v mesecev število!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 7, 'Da, tista noč bodi nerodovitna, veselega glasu ne bodi v njej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 8, 'Prekolnite jo, čarovniki, ki preklinjate dan, ki ste zmožni zbuditi leviatana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 9, 'Potemné naj zvezde njenega somraka, pričakuje naj svetlobe, pa je ne bodi, tudi utripanja jutranje zarje naj ne zagleda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 10, 'zato ker mi ni zaprla materinega telesa, ni skrila nadloge mojim očem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 11, 'Zakaj nisem umrl kar ob rojstvu, izpustil duše, ko sem prišel iz materinega telesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 12, 'Zakaj sem bil vzet na kolena in zakaj na prsi, da sem sesal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 13, 'Kajti sedaj bi ležal in bi počival in spal – in imel bi pokoj');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 14, 's kralji in svetovalci zemlje, ki so si zgradili podrtine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 15, 'ali s knezi, ki so imeli zlata, ki so napolnili hiše svoje s srebrom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 16, 'Ali da bi me sploh ne bilo kakor ni izpovitka, ki so ga zagrebli, kakor otročiči, ki nikdar niso videli luči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 17, 'Tam je nehalo krivičnikov divjanje, tam počivajo, ki jim je opešala moč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 18, 'tam mirno ležé vkup vsi zasužnjenci, ne slišijo več glasu priganjalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 19, 'Mali in veliki – tam eno je in isto, in hlapec je prost gospodarja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 20, 'Čemu je dal Bog siromaku luč in življenje onim, ki so v bridkosti duše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 21, 'ki čakajo smrti, pa je ni, in hrepene po njej bolj, nego kdor koplje zaklade,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 22, 'ki bi se silno veselili in radovali, ko bi našli grob?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 23, 'Čemu je luč možu, čigar pot je prikrita in ki ga je Bog ogradil s trnjem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 24, 'Zakaj kadar bi imel jesti, mi je zdihovati, in stokanje moje se razliva kakor voda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 25, 'Kajti česar sem se bal, to je prišlo nadme, česar me je bilo strah, to me je zadelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 3, 26, 'Ni mi miru, ne pokoja, ne počitka, a nova prihaja bridkost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 1, 'In odgovori Elifaz Temančan in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 2, 'Če poskusimo govoriti s teboj, morda ti bo nadležno? Ali kdo se more zdržati govora?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 3, 'Glej, mnoge si učil in trudne roke si krepčal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 4, 'Besede tvoje so bodrile omahujoče, in šibeča se kolena si utrjeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 5, 'A ker je sedaj nad tebe prišlo, ti je bridko, in ker je tebe zadelo, si se prestrašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 6, 'Ni li tvoja bogaboječnost upanje tvoje in popolnost potov tvojih nada tvoja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 7, 'Spomni se, prosim te, kdo je kdaj poginil nedolžen, kje so zatrli poštenjake?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 8, 'Kolikor sem videl jaz: tisti, ki orjejo krivico in sejejo nesrečo, jo tudi žanjejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 9, 'Od diha Božjega ginejo, in sapa jeze njegove jih pokončava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 10, 'Rjovenje leva, glas ljutega leva utihne, in zobje levičevi bodo strti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 11, 'krepek lev pogine, ker nima plena, in levinjina mladina se mora razkropiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 12, 'In mene je skrivoma došla beseda, uho moje je ujelo njeno šepetanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 13, 'v premišljevanju, ki ga sprožijo nočne prikazni, ko trdno spanje objema ljudi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 14, 'strah me je obšel in trepet, in vse kosti moje so se pretresle;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 15, 'kajti duh je šel mimo mene – vstali so pokoncu lasje telesa mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 16, 'Ustopil se je, a nisem mu spoznal obraza, podoba mi je bila pred očmi, šepet in glas sem začul:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 17, '„Je li smrtnik pravičen pred Bogom ali mož čist pred Stvarnikom svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 18, 'Glej, hlapcem svojim ne upa in angele svoje lahko okrivi zmote:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 19, 'koliko bolj one, ki prebivajo v ilovih hišah, ki jim je podlaga v prahu, ki jih je lahko zatreti kakor molje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 20, 'Od jutra do večera se stro, in preden kdo opazi, izginejo za vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 4, 21, 'Ni li tako? Ko se jim izdere vrv, ki veže njih šator telesni, umirajo, in to brez modrosti.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 1, 'Kliči, pravim! Je li kdo, ki ti odgovori? in h kateremu iz svetnikov se obrneš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 2, 'Kajti neumneža umori srd, in bedaka ubije goreča jeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 3, 'Sam sem videl neumneža, da se je ukoreninjeval, a precej sem proklel prebivališče njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 4, 'Daleč so ostali otroci njegovi od sreče in poteptani so bili med vrati, in nikogar ni bilo, ki bi jih bil rešil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 5, 'njegovo žetev je pojedel lačnež, celó iz trnjeve ograje jo je pobral, in po imetju njegovem so hlastali žejni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 6, 'Kajti nesreča ne prihaja iz prahu, in iz zemlje ne poganja nadloga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 7, 'ampak človek se rodi za nadlogo, kakor iskre letajo kvišku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 8, 'Jaz pa, do Boga mogočnega bi se proseč obrnil in poročil pravdo svojo Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 9, 'ki nareja reči velike, da jih ni doumeti, čudna dela brez števila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 10, 'ki daje dežja na površje zemlje in vode pošilja na površino poljan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 11, 'da bi postavil ponižne v višavo in da se žalostni povzdignejo v srečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 12, 'On uničuje zvijačnih naklepe, da njih roke ne morejo izvršiti, kar so začeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 13, 'On zasačuje modre v njih lastni zvijači, in premetencev namera se izvrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 14, 'Po dnevi nalete na temo in opoldne tavajo kakor po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 15, 'On rešuje potrebnega od meča, ki gre iz njih ust, in iz pesti mogočneža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 16, 'In tako vzklije ubožcu upanje, in nepravičnost mora stisniti usta svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 17, 'Glej, blagor možu, ki ga Bog strahuje! Zato ne zaničuj kazni Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 18, 'Kajti on napravi rano, pa jo tudi obveže, udari, a roke njegove zacelijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 19, 'Iz šestih stisk te otme, tudi v sedmerih se te ne dotakne nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 20, 'V lakoti te odreši smrti in v vojski oblasti meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 21, 'Skrit boš biču jezika in ne boš se bal pustošenja, kadar pride.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 22, 'Pustošenju in draginji se boš smejal in zverin zemlje se ne boš bal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 23, 'kajti zavezo boš imel s kamenjem na polju, in zverina poljska se bo prijateljila s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 24, 'In spoznaš, da ima mir šator tvoj, in če pogledaš bivališče svoje, ne pogrešiš ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 25, 'Vedel boš tudi, da bo semena tvojega veliko in potomcev tvojih kakor trave zemeljske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 26, 'Čvrst bodeš, še ko pojdeš v grob, kakor kopica snopja, ko se spravlja ob svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 5, 27, 'Glej, to smo preiskovali, tako je; poslušaj to in dobro pomni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 1, 'In Job odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 2, 'O da bi se stehtala nevolja moja in da bi na tehtnico položili nesrečo mojo vso!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 3, 'Kajti sedaj je težja nego morski pesek. Zato so bile nepremišljene besede moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 4, 'Zakaj pšice Vsemogočnega tiče v meni, katerih strup mora piti duh moj, Božje strahote so postavljene v boj zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 5, 'Ali divji osel riga, kadar ima dosti trave, ali muka vol pri svoji krmi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 6, 'Ali se more jesti neslastno in neslano? ali je okus v jajčjem beljaku?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 7, 'Česar se ni hotelo moji duši dotekniti, to mi je kakor gnusna jed sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 8, 'O da bi se zgodila prošnja moja, in da bi mi dal Bog, česar želim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 9, 'da me Bog izvoli streti, da oprosti roko svojo in me odreže!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 10, 'Tako bi mi še ostala tolažba, in radoval bi se v bolečini, ki mi ne prizanaša, da nisem zatajil besede Svetega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 11, 'Kaj je moja moč, da naj stanovitno čakam, in kaj konec moj, da naj ostanem potrpežljiv?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 12, 'Trdna li kot kamen je moja moč in meso moje je li iz brona?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 13, 'Ni li pač tako, da nimam pomoči v sebi nobene, in vsaka pospešitev rešenja je daleč od mene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 14, 'Prijatelj mora kazati usmiljenje obupujočemu, sicer se odreče strahu Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 15, 'Bratje moji so varali kakor hudournik, kakor struga hudournikov, ki se gubé,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 16, 'ki se kalé od ledu, v katere se zateka sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 17, 'Ob času, ko solnce vanje pripeka, presihajo, in ko je vroče, izginejo s svojega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 18, 'Vijejo se semtertja poti njih toka, gredo v puščavo in se razgube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 19, 'Gledale so tja karavane iz Teme, potne družbe iz Sabe so upale vanje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 20, 'osramočene so bile, ker so se zanašale nanje, prišle so do tja, in rdečica jih je oblila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 21, 'Res, tako ste mi postali v nič; strahoto ste zazrli in se preplašili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 22, 'Ali sem morda rekel: Dajte mi, ali: Žrtvujte zame darilo od svojega blaga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 23, 'ali: Oprostite me iz pesti zatiralčeve, ali: Odkupite me iz roke silovitnikove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 24, 'Poučite me, in molčal bom, in v čem sem se motil, razodenite mi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 25, 'Kako krepke so poštene besede! A kaj dokazuje karanje vaše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 26, 'Mislite li grajati besede moje? Saj v veter gredo govori obupujočega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 27, 'Še za siroto bi vi vrgli kocko in prodali prijatelja svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 28, 'In sedaj se blagovolite ozreti vmé, kajti v lice vam vendar ne bom lagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 29, 'Povrnite se, ne zgodi naj se krivica, da, povrnite se, pravda moja je pravična!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 6, 30, 'Je li nepravičnost na jeziku mojem? ali ne more okus moj razpoznati, kaj je pogubljivo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 1, 'Ni li vojna služba človekovo življenje na zemlji in dnevi njegovi enaki dnevom najemnikovim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 2, 'Kakor si suženj želi sence in kakor najemnik pričakuje mezde:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 3, 'tako sem dobil v delež mesece ničemurnosti in trudapolne noči so mi odmenjene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 4, 'Kadar ležem, pravim: Kdaj vstanem? A večer se vleče prepočasno in dosita mi je premetavanja po postelji do svita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 5, 'Moje meso je oblečeno s črvadjo in prašno skorjo, koža se mi grbanči in iznova prepušča gnoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 6, 'Dnevi moji so hitrejši nego tkalčev čolnek in minevajo brez nade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 7, 'Pomni, da je življenje moje sapa! Ne bo zopet sreče gledalo moje oko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 8, 'Ne bo me gledalo oko tistega, ki me vidi; obrneš li oči svoje vame, ne bo me več!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 9, 'Kakor oblak gine in izgine, tako ne pride več gori, kdor stopi v šeol;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 10, 'ne vrne se več v hišo svojo, ne pozna ga več kraj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 11, 'Zato ne morem tudi jaz braniti ustom svojim, govoril bom v duha svojega stiski, žaloval v duše svoje bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 12, 'Sem li mar morje ali pošast morska, da si postavil stražo zoper mene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 13, 'Kadar si rečem: Postelja moja me potolaži, ležišče moje mi pomore trpeti žalovanje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 14, 'tedaj me strašiš s sanjami in s prikaznimi me spravljaš v trepet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 15, 'da voli duša moja zadušenje in bi rajši bil mrtev nego suho okostje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 16, 'Zamrzelo mi je življenje – ne hotel bi živeti vekomaj. Odnehaj! kajti kakor sapa so dnevi moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 17, 'Kaj je človek, da ga toliko ceniš in da ga imaš v mislih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 18, 'in ga vsako jutro obiskuješ in vsak hip izkušaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 19, 'Kako dolgo se ne ozreš stran od mene, ne odnehaš, da požrem svojo slino?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 20, 'Ako sem grešil, kaj morem storiti tebi, o opazovalec ljudi! Zakaj si me postavil za cilj svojim pšicam, da sem postal breme samemu sebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 7, 21, 'Zakaj ne odpustiš prestopka mojega in ne odpraviš krivice moje? Kajti sedaj ležem v prah, in če me boš iskal jutri, me ne bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 1, 'Nato odgovori Bildad Šuhec in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 2, 'Doklej še boš tako govoril in doklej bodo besede tvoje kakor silovit veter?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 3, 'Ali Bog mogočni prevrača sodbo in Vsegamogočni prevrača li pravičnost?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 4, 'Ako so grešili sinovi tvoji zoper njega, jih je izročil kazni za njih pregreho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 5, 'Ako boš zgodaj iskal Boga mogočnega in milosti prosil pri Vsegamogočnem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 6, 'če si čist in pošten: res se prebudi on tebi v prid in blagostanje povrne hiši pravičnosti tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 7, 'in prejšnja sreča tvoja bode majhna proti poslednji, ki silno vzraste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 8, 'Kajti vprašaj, prosim, prejšnji rod in premisli, kar so preiskali njih očetje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 9, '(zakaj mi smo od včeraj in ničesar ne vemo, ker so naši dnevi le senca na zemlji):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 10, 'te li ne bodo poučili in ti povedali, ne prineso li besed iz srca svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 11, 'Kjer ni močvirja, zraste li trstičje? in brez vode obrodi li bičje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 12, 'ki prej nego druge rastline, še neporezano, usahne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 13, 'Take so poti vsakemu, ki zabi Boga mogočnega, in kdor Ga zaničuje, njemu izgine upanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 14, 'česar se nadeja, se mu izjalovi, pajčevinast je vsak njegov up.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 15, 'Nasloni se na hišo svojo, pa ne bo stala, trdno se je oprime, pa se ne bo vzdržala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 16, 'Čvrst in sočnat na solncu se greje in po vsem vrtu razteza veje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 17, 'po kupu kamenja razvija svoje korenine, navzgor se oklepa hiše kamenene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 18, 'Ko ga pa iztrebi Gospodar, kraj njegov ga zataji: Nisem te videl nikdar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 19, 'Glej, to je pota njegovega slast! In iz prahu za njim zrastejo drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 20, 'Glej, Bog mogočni ne zavrže popolnega in ne bo podpiral roke hudobnežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 21, 'Kadar ti napolni usta s smehom in ustnice z radostnim ukanjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 8, 22, 'bodo v sramoto oblečeni tvoji sovražilci, in šatora brezbožnikov ne bode več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 1, 'Tedaj odgovori Job in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 2, 'Resnično, vem, da je tako; a kako more smrtni človek biti pravičen pred Bogom mogočnim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 3, 'Ako bi se hotel pravdati ž Njim, Mu ne more odgovoriti ene na tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 4, 'Modrega je srca in presilne moči – kdo Mu je kdaj kljuboval in ni škode imel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 5, 'On premakne gore, in nihče ne zapazi, da jih je prevrnil v jezi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 6, 'On strese zemljo ž njenega mesta, in stebri njeni se pretresejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 7, 'On veli solncu, in ne vzide, in zapečati zvezde v temo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 8, 'On razprostira nebo sam in hodi po valovih morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 9, 'On nareja voz na nebu in rimščice in gostosevce in ozvezdja na jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 10, 'On nareja velike reči, ki se ne morejo preiskati, čudna dela, ki jim ni števila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 11, 'Glej, on gre poleg mene, pa ga ne vidim, hodi mimo mene, pa ga ne zapazim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 12, 'Če plen pograbi, kdo mu zabrani? kdo mu poreče: Kaj delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 13, 'Bog ne odvrača jeze svoje. Pomočniki Rahaba se pred Njim morajo ukloniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 14, 'Koliko manj bi Mu mogel jaz odgovarjati, kje naj dobim besed, da bi se prepiral ž Njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 15, 'Tudi ko bi prav imel, bi mu ne mogel odgovoriti – milosti bi rajši prosil sodnika svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 16, 'Ko bi ga klical in bi mi odgovoril, jaz bi ne veroval, da je slišal moj glas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 17, 'on, ki me streti hoče v viharju in množi rane moje brez vzroka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 18, 'še sape mi ne da vase potegniti, a siti me z bridkostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 19, 'Če gre za moč močnega, On reče: „Glej, tu sem!“in če za sodbo: „Kdo si me upa pozvati?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 20, 'Ako bi tudi prav imel, bi me vendar usta moja obsodila, ako bi bil popoln, bi On dokazal, da sem popačenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 21, 'Nedolžen sem! ne maram za dušo svojo, zaničujem življenje svoje –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 22, 'vse eno je! Zato pravim: I nedolžnega i brezbožnega uničuje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 23, 'Ko bič nagloma ubije, smeje se On izkušnji nedolžnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 24, 'Zemlja je izročena oblasti krivičnikov, On zakriva obraz njenim sodnikom. Če On ne, kdo pa drugi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 25, 'Dnevi moji teko h koncu hitreje nego tekač, beže, sreče ne vidijo nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 26, 'Lete naprej kakor čolni iz bičja, kakor orel, ko šine doli na plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 27, 'Ko rečem: Hočem pozabiti žalovanje svoje, opustim svoj tožni obraz in razvedrim si lice –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 28, 'groza me je vseh bolečin mojih; vem, da me ne spoznaš za nekrivega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 29, 'Moram veljati za krivca – čemu bi se pa trudil zaman?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 30, 'Ko bi se umil s snežnico in z lugom si očistil roke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 31, 'ti me vtakneš v mlakužo, in celo svoji obleki se bom gnusil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 32, 'Zakaj On ni mož kakor jaz, da bi mu odgovarjal, da bi skupaj šla pred sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 33, 'Ni ga med nama razsodnika, ki bi smel na oba položiti roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 34, 'Naj umakne od mene šibo svojo in naj me ne plaši strah njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 9, 35, 'in govoril bom in ne bom se Ga bal; kajti nisem tak sam v sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 1, 'Duši moji se gnusi življenje; zato naj tožba moja teče, govoril bodem v bridkosti duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 2, 'Rečem Bogu: Ne obsojaj me; povej mi, zakaj se prepiraš z menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 3, 'Ti li dobro de, da tlačiš, da zametaš rok svojih delo, s svetlobo pa obsevaš namero brezbožnih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 4, 'Imaš li oči mesene, ali pa vidiš, kakor človek vidi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 5, 'So li dnevi tvoji kakor dnevi smrtnika, ali leta tvoja omejena kakor dnevi človeka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 6, 'da vprašuješ tako po krivdi moji in greh moj zasleduješ,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 7, 'dasi veš, da nisem kriv in da nikogar ni, ki more oteti iz tvoje roke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 8, 'Roke tvoje so me upodobile in naredile vsega, kakor sem kroginkrog – in sedaj me zatiraš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 9, 'Spomni se vendar, da si me kakor glino napravil, in hočeš me zopet vrniti v prah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 10, 'Me li nisi kakor mleko ulil in strdil kakor sir?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 11, 'S kožo in mesom si me oblekel, s kostmi in kitami si me prepletel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 12, 'Življenje in milost si mi daroval in s svojo skrbjo mi duha varoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 13, 'A tole si skrival v srcu svojem, vem, da ti je bilo to v mislih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 14, 'ako bom grešil, da name boš strogo pazil in krivde moje me ne boš oprostil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 15, 'Ako sem krivično ravnal, gorje mi! in čeprav bi bil pravičen, si ne upam povzdigniti glave, nasičen sramote in zroč bedo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 16, 'In ako bi povzdignil glavo, podil me boš kakor lev in zopet izkazoval čudovito moč svojo na meni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 17, 'vnovič postaviš priče svoje proti meni in pomnožiš nevoljo svojo zoper mene, vedno nova krdela in vojske boš pošiljal nadme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 18, 'Zakaj si mi dal priti iz materinega telesa? Naj bi bil umrl in nobeno oko me ne bi bilo videlo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 19, 'Naj bi bil, kakor bi ne bil živel nikdar, od materinega telesa naj bi bil prenesen v grob!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 20, 'Ni li dni mojih malo? Odnehaj, obrni se od mene, da se malo razvedrim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 21, 'preden odidem, odkoder se ne vrnem, v deželo temine in smrtne sence,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 10, 22, 'v deželo temnejšo od mraka, kjer je le senca smrti in nered, kjer noč najbolj črna se šteje za svetlost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 1, 'Tedaj odgovori Zofar Naamatec in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 2, 'Mnogobesedje ali naj ostane brez odgovora, in jezičnik bo li opravičen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 3, 'Govoričenje tvoje naj sapo zapre ljudem, da bi se posmehoval, ne da te kdo osramoti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 4, 'in da bi dejal: „Čist je moj nauk in čist sem pred Tvojim obličjem“?!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 5, 'O da bi pa Bog govoril in usta svoja odprl zoper tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 6, 'Da ti naznani skrivnosti prave modrosti, da je mnogotera v znanju; potem bi spoznal, da Bog tebi v prid mnogo pozablja iz krivde tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 7, 'Moreš li globokost Božjo z umom doseči, ali popolnosti Vsegamogočnega do dna priti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 8, 'Višave so to nebeške – kaj hočeš početi? globočja je nego šeol – kaj moreš vedeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 9, 'daljša nego zemlja je mera njena in širša nego morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 10, 'Če gre On poleg koga in ga dene v zapor in skliče sodni zbor, kdo mu zabrani?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 11, 'Kajti On pozna ničemurne ljudi in vidi krivico, ne da bi mu bilo treba paziti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 12, 'A puhloglavec dobi šele razum, kadar se divjega osla žrebe prerodi v človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 13, 'Ako obrneš v pravo smer srce svoje in boš k Njemu razprostiral roke –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 14, 'če je krivica na roki tvoji, odpravi jo in nepravičnosti ne daj prebivati v šatorih svojih –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 15, 'res, tedaj boš smel vzdigniti obličje brez madeža in bodeš nepremakljiv in se ne boš bal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 16, 'Kajti tedaj pozabiš nadlogo, spominjal se je boš kot vodá, ki so potekle mimo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 17, 'in življenje ti zasije jasneje nego poldnevna svetloba, in zmrači li se kdaj, mine mrak kakor ob jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 18, 'In boš upal, ker je nada zate, in ogledoval boš svoje, spaval brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 19, 'Počival boš in nihče te ne bo plašil, mnogi bodo pa prosili blagovoljnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 11, 20, 'Brezbožnikom pa bodo oči od koprnenja hirale, in pribežališče jim izgine in njih upanje bo, da izdahnejo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 1, 'In Job odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 2, 'Zares, vi sami ste ljudje in z vami bo modrost umrla!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 3, 'Tudi jaz imam razum kakor vi, nisem nižji od vas; in kdo bi onega ne vedel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 4, 'V posmeh moram biti prijatelju svojemu jaz, ki sem klical k Bogu in mi je odgovarjal, v posmeh sem – pravični, brezmadežni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 5, 'Nesreči gre po mnenju lahkoživca preziranje; pripravljeno je tistim, ki jim omahuje noga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 6, 'Pokojni ostajajo šatori razbojnikom, in varnost uživajo, kateri dražijo mogočnega Boga, ki nosijo boga v pesti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 7, 'Toda vprašaj, prosim, le živino, in nauči te, in ptice nebeške, pa ti povedo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 8, 'ali ogovóri zemljo, in te pouči, in ribe morske naj ti pripovedujejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 9, 'Kdo bi ne spoznal iz vsega tega, da je roka Gospodova storila to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 10, 'V Njegovi roki je duša vsega, kar živi, in duh vseh človeških teles.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 11, 'Ali naj ne presoja uho besed kakor grlo okusa jedi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 12, 'Pri osivelih je li modrost in dolgost življenja daje li razumnost?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 13, 'Pri Njem je modrost in moč, Njegov je svet in razumnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 14, 'Glej, kar On razdene, se več ne sezida, in kogar On zapre, se mu ne more odpreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 15, 'Glej, On zadrži vode, in se posuše, zopet jih izpusti, in razrujejo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 16, 'Pri Njem je moč in pravo znanje, Njegov je, kdor je varan in kdor vara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 17, 'Svetovalce vodi oplenjene vstran in sodnike napravlja neumne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 18, 'Gospostvo kraljev razdira, spone jim pripasuje na ledja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 19, 'Duhovnike vodi oplenjene vstran in podira močno utrjene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 20, 'Govor jemlje tistim, ki se nanje mnogi zanašajo, in starejšinam jemlje razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 21, 'Zaničevanje izliva nad plemenitnike in odpenja pas mogočnežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 22, 'On odkriva globoke reči izpod teme in smrtno senco prinaša v luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 23, 'On povečava narode in jih uničuje, razmnožuje narode in jih vodi v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 24, 'On jemlje razum glavarjem narodov zemeljskih in dela, da tavajo po praznoti, ki je brez potov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 12, 25, 'tipljejo po temi brez luči, in On dela, da se opotekajo kakor pijanci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 1, 'Glejte, to vse je videlo moje oko, slišalo je moje uho in je razumelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 2, 'Kolikor vi veste, vem tudi jaz, nisem nižji od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 3, 'Toda jaz hočem govoriti k Vsegamogočnemu, želja mi je, predložiti pravdo svojo Bogu mogočnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 4, 'Saj vi ste kovači laži, ničevi zdravniki vi vsi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 5, 'Da bi vendar docela molčali, ker štelo bi se vam v modrost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 6, 'Čujte, prosim, pravičenje moje in poslušajte dokaze mojih ustnic!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 7, 'Boste li mogočnemu Bogu v prid govorili krivično, njemu na ljubav govorili prevaro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 8, 'Boste se li potegovali za Njegovo stran? ali pa hočete biti pravdniki Bogu mogočnemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 9, 'Dobro li bo, če vas preišče? ali pa ga morete prekaniti, kakor se človek prekani?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 10, 'Gotovo vas bo kaznoval, ako postopate pristransko na skrivnem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 11, 'Ne spravi li vas njegova visokost v trepet in strah njegov ne prešine li vas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 12, 'Vaši modri izreki so prislovice iz pepela, vaši zagovori so okopi iz blata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 13, 'Molčíte, pustíte mi, da jaz govorim, pridi name karkoli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 14, 'Čemu naj vzamem meso svoje med zobe in nevarnosti izpostavim življenje svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 15, 'Glej, čeprav me usmrti, čakal Ga bom; samo poti svoje bom zagovarjal Njemu v obraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 16, 'Tudi to mi bo služilo v rešenje, da ne sme bogapozabnik stopiti pred Njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 17, 'Čujte, čujte govor moj, in moje izrecilo pridi v ušesa vaša!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 18, 'Glejte vendar, pripravil sem pravdo svojo, vem, da se mi prizna pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 19, 'Kdo je, ki se more z menoj prepirati? Kajti potem hočem molčati in preminiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 20, 'Samo dvojega mi ne stóri, tedaj se ne bom skrival obličju Tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 21, 'Odtegni od mene roko svojo, in strah tvoj me ne plaši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 22, 'Potem kliči, in odgovorim, ali jaz bom govoril, in ti mi odgovarjaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 23, 'Koliko je mojih krivic in grehov? pokaži mi prestopek moj in greh moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 24, 'Zakaj skrivaš obličje svoje in me šteješ za sovražnika sebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 25, 'Hočeš li plašiti list, ki ga že veter odnaša, in preganjati suho strn?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 26, 'Kajti prisojaš mi mnoge bridkosti in v dedino mi daješ grehe moje mladosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 27, 'Noge mi devaš v klado in paziš na vse steze moje, zaznamljaš mojih nog stopinje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 13, 28, 'dasi razpadam kakor črvojedina, kakor obleka, ki jo je razjedel molj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 1, 'Človek, rojen iz žene, je kratkih dni in dosita ima nadlog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 2, 'je kakor cvetka, ki se dvigne iz popka, pa uvene, in beži kakor senca in nima obstanka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 3, 'In nad takim še odpiraš oko svoje, in mene vodiš v sodbo s seboj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 4, 'O, da bi kdaj prišel čist iz nečistega! Niti eden!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 5, 'Ker so torej določeni njegovi dnevi in meseci po številu pri tebi, ker si mu napravil meje, ki jih ne sme prestopiti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 6, 'ozri se stran od njega, da dobi pokoj, dokler ne dokonča kakor najemnik dneva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 7, 'Kajti za drevo je upanje: če ga posekajo, zopet požene odrastke, in njegovo mladje ne prestane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 8, 'Ko se v zemlji mu postara korenina in mu parobek umira v prahu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 9, 'da le začuti duh vode, vnovič ozeleni in požene veje kakor mlada sajenica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 10, 'Mož pa umre in leži strt, človek izpusti duha, in kje je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 11, 'Kakor se voda razteče iz jezera in reka usahne in se posuši,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 12, 'tako leže človek in ne vstane; dokler bodo nebesa, se ne prebude in nič jih ne vzdrami iz spanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 13, 'O da bi me shranil v šeolu, da bi me skril, dokler ne mine jeza tvoja, mi določil rok, in potem se me spomnil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 14, '(Ko človek umre, bo li spet živel?) Vse dni, dokler sem v vojni službi, bi hotel čakati, dokler mi ne pride prememba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 15, 'Ti bi poklical, in jaz bi ti odgovoril; tožilo bi se ti po svojih rok stvari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 16, 'Kajti sedaj šteješ korake moje; ne paziš li na greh moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 17, 'Zapečatena je v zvezku pregreha moja, in še pridevaš h krivici moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 18, 'Saj še gora se sesuje in razdrobi in skalovje preperi z mesta svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 19, 'vode prevotlijo kamene, njih nalivi odplavijo zemeljski prah: enako uničuješ smrtniku upanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 20, 'Ti ga ukrotiš za vselej, in odide; ko mu onespodobiš lice, ga pošlješ v grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 21, 'Ako so v časti otroci njegovi, on tega ne ve, in so li ponižani, tega ne zazna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 14, 22, 'Samo meso njegovo občuti ob njem bolečine in duša njegova žaluje v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 1, 'Tedaj odgovori Elifaz Temančan in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 2, 'Bo li moder mož odgovarjal z vetrovitim znanjem in napihoval notranjščino svojo z vzhodnim vetrom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 3, 'prepirajoč se z govori, ki ničesar ne pospešujejo, in z besedami, s katerimi nič ne koristi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 4, 'Res, v nič devaš bogaboječnost in kratiš molitev pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 5, 'Kajti krivičnost tvoja ti poučuje usta, in voliš govor prekanjencev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 6, 'Tvoja usta te obsojajo, ne jaz, in ustne tvoje pričajo zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 7, 'Si li ti prvi človek, ki se je rodil, ali si bil ustvarjen, preden so bili hribi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 8, 'Si li poslušal v tajnem svetu Božjem in zase pokupil vso modrost?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 9, 'Kaj ti veš, česar mi ne vemo, kaj razumeš, in nam ni znano?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 10, 'Med nami so i osiveli i starčki, številnejših dni nego tvoj oče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 11, 'Ali so ti malovažne tolažitve Božje in pohlevna beseda do tebe ti je li ničvredna?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 12, 'Kaj ti je ujelo srce in zakaj se iskrijo oči tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 13, 'da obračaš zoper Boga mogočnega togoto svojo in take besede bruhaš iz svojih ust?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 14, 'Kaj je smrtnik, da bi bil čist, in rojeni od žene, da bi bil pravičen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 15, 'Glej, svetnikom svojim ne upa in nebesa niso čista v njegovih očeh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 16, 'Koliko manj ostudnež in popačenec, mož, ki pije krivico kakor vodo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 17, 'Naj ti povem, poslušaj me, in kar sem videl, ti bom pripovedoval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 18, 'kar so modri oznanjali in niso zakrivali, sprejemši to od očetov svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 19, 'ki je njim samim bila izročena dežela in tujec ni prešel sredi njih –:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 20, 'Vse svoje žive dni se zvija brezbožnik v mukah in majhno število let je prihranjeno silovitežu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 21, 'Groze glas mu doni po ušesih; ko je mir, prihruje naj pogubnik;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 22, 'nima nade, da se vrne iz temine, in namerjen nanj ga čaka meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 23, 'Blodi okrog zaradi kruha, govoreč: Kje ga dobim? Ve, da blizu njega je pripravljen dan teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 24, 'Bridkost in stiska ga plašita, premagujeta ga kakor kralj, ki je pripravljen za naskok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 25, 'Ker je iztegnil roko zoper Boga mogočnega in je prevzetoval proti Vsegamogočnemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 26, 'zaletaval se je vanj z vzpetim vratom, z debelimi grbami ščitov svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 27, 'ker se je obraz njegov pokril z mastjo, na ledjih se mu je nabrala tolšča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 28, 'in prebival je v porušenih mestih, v hišah, v katerih bi se ne bilo smelo stanovati, ki zanje je določeno, da ostanejo v razvalinah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 29, 'zato ne obogati, imetje njegovo ne ostane in posestvo njegovo se ne razširi v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 30, 'Ne uteče iz temine, plamen posuši mladike njegove, in on izgine od diha iz ust Njegovih. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 31, 'Naj se ne zanaša na laž, prevaran bo, kajti prevara mu bo v povračilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 32, 'Še preden pride dan njegov, se to dopolni, in palmova mladika mu več ne ozeleni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 33, 'bode kakor trta, ki trebi kislo grozdje svoje, in kakor oljka, ki stresa cvetje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 34, 'Kajti družina bogapozabnikova je nerodovitna, in ogenj pokonča podkupljivčev šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 15, 35, 'Bogapozabniki nosijo nadlogo, rode krivico, njih srce pripravlja prevaro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 1, 'In Job odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 2, 'Enakih reči sem že slišal veliko; sitni ste vi tolažniki vsi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 3, 'Je li že konec vetrovitim besedam? ali kaj te draži, da odgovarjaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 4, 'Lahko bi tudi jaz govoril kakor vi! Ako bi duša vaša bila na mojem mestu, lahko bi spletal besede zoper vas in zmajeval z glavo nad vami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 5, 'rad bi vas krepčal z usti svojimi in usten mojih tolažba naj bi vam lajšala bol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 6, 'Ako govorim, se ne ustavi bolečina moja, ako pa molčim, koliko pojemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 7, 'Res me je že Bog trudnega storil; – opustošil si vso družino mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 8, 'Trdo si me zgrabil, za pričo zoper mene; in postavila se je proti meni moja shiranost, pričujoč zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 9, 'Raztrgal me je v jezi svoji in preganjal, škripal je z zobmi nad menoj; kot nasprotnik moj me ostro gleda z očmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 10, 'Razdrli so usta svoja zoper mene, zasramujoč so me bili v lice, v trumo se zbirajo zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 11, 'Bog mogočni me je izročil malopridnežem, pahnil me je v roke brezbožnežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 12, 'Užival sem mir, pa me je strl, zgrabil me je za tilnik in me raztrupal, postavil me je za cilj svojim pšicam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 13, 'Obkolili so me strelci njegovi, razklal mi je obisti nemilo, na tla je cedil žolč mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 14, 'Vsekava mi rano za rano, zaganja se vame kakor vojni junak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 15, 'Raševino sem sešil vrh kože svoje, onečedil sem v prahu rog svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 16, 'Moj obraz gori od jokanja in na trepalnicah mi je senca smrti –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 17, 'dasi ni nasilstva na rokah mojih in je čista molitev moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 18, 'O zemlja, ne zakrij moje krvi, in vpitju mojemu ne bodi počivališča!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 19, 'Ali že sedaj, glej, v nebesih je priča moja in ta, ki zame pričuje, je na višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 20, 'Moji prijatelji so mi zasmehovalci: moje oko se solzi k Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 21, 'da izvrši pravico za moža proti Bogu in razsodi med sinom človeškim in prijateljem njegovim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 16, 22, 'Kajti ko mine malo let, odidem po poti, po kateri se ne vrnem več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 1, 'Duh moj je raztresen, dnevi mi dotekajo, grobovi me čakajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 2, 'Res zasmehljivci so pri meni, in oko moje mora gledati njih bridko žaljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 3, 'Zastavi se, prosim, jamči zame pri sebi! kdo mi sicer v roko udari za poroštvo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 4, 'Kajti njih srca si zaprl razumu, zato jim ne daš prevladovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 5, 'Če kdo ponuja prijatelje v plen, otrokom njegovim morajo oči shirati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 6, 'On me je tudi postavil v prislovico ljudem, in obraz moj jim je v pljuvanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 7, 'In oko moje je potemnelo od nevolje, in kakor senca je slednji moj ud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 8, 'Pošteni ostrme ob tem, in nedolžni se ujezi nad bogapozabnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 9, 'A pravični bo vztrajal na poti svoji, in kdor je čistih rok, bo dobival vedno več moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 10, 'Ali vi vsi, le prihajajte zopet sem! modrega vendar ne najdem med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 11, 'Dnevi moji so minili, načrti so se mi izjalovili, kar sem jih gojil v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 12, 'Noč mi izpreminjajo v dan, svetloba, pravijo, je blizu tam, kjer je tema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 13, 'Ako čakam, da dobim v šeolu dom, ako sem si v temoti postlal ležišče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 14, 'ako sem dejal grobu: Oče moj si! in črvadi: Mati si moja in sestra moja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 15, 'kje je potem nada moja? da, nada moja, kdo jo bo gledal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 17, 16, 'Zaide doli do zapahov šeola, ko bomo vsi vkup počivali v prahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 1, 'Tedaj odgovori Bildad Šuhec in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 2, 'Doklej boste lovili besede? Hotite razumeti, in potem bomo govorili!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 3, 'Zakaj nas smatrate za živino? smo li toliko neumni v očeh vaših?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 4, 'Ti, ki sam sebe razmesarjaš v jezi svoji, meniš li, da naj bo zemlja zaradi tebe zapuščena? ali skala s svojega mesta prestavljena?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 5, 'A vendar brezbožniku luč ugasne, in ne bo svetil ognja njegovega plamen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 6, 'Svetloba se pomrači v šatoru njegovem, in svetiljka njegova ugasne nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 7, 'Koraki njegove moči pridejo v tesnobo, in svet njegov ga pahne v pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 8, 'Kajti v mrežo ga vodijo noge njegove, in čez nastave bo hodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 9, 'Zadrga ga ujame za peto in tesno ga stisne zanka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 10, 'Progla je zanj skrita v tleh in past ga čaka na stezi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 11, 'Grozote ga strašijo z vseh strani in ga plašijo, dreveč mu za petami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 12, 'Njegovo moč požira glad, poguba preti mu spred in zad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 13, 'Pojeda ude telesa njegovega, pojeda mu jih smrti prvenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 14, 'Izrujejo mu iz šatora, na kar je stavil upanje, in stopati mora do kralja groze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 15, 'Kar ni njegovo, bo prebivalo v šatoru njegovem, žveplo se bo sipalo na stan njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 16, 'Odzdolaj usahnejo njegove korenine, odzgoraj mu uvene vejevje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 17, 'Spomin njegov izgine z zemlje in po ulicah ne bodo imenovali njegovega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 18, 'Pehnili ga bodo iz svetlobe v temo in pognali s sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 19, 'Ne bo imel ne sina, ne potomstva med svojim ljudstvom, ne kakega ostanka po svojih selih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 20, 'Ob dnu nesreče njegove ostrme, ki pridejo za njim, kakor je nje, ki so bili prej, zgrabila groza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 18, 21, 'Da, tako se godi prebivališčem nepravičnika in tako kraju tistega, ki ne spoznava Boga mogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 1, 'A Job odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 2, 'Doklej hočete žaliti dušo mojo in me tlačiti z besedami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 3, 'Desetkrat ste me že zasramovali, in vas ni sram, da me tolikanj žalite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 4, 'Ako sem pa res kriv, krivda moja ostaja pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 5, 'Če pa se res hočete veličati zoper mene in mi očitati sramoto mojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 6, 'vedite, da me je Bog okrivičil in me obdal z mrežo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 7, 'Glej, vpijem: Sila se mi godi! a nihče me ne sliši, kličem za pomoč, pa ni sodbe zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 8, 'Zagradil mi je pot, da ne morem preiti, in steze moje je zavil v temino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 9, 'Slekel me je moje slave in venec mi je snel z glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 10, 'Na vseh straneh me je podrl, da ginem, in izruval je kakor drevo upanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 11, 'Storil je, da zoper mene plamti srd njegov in šteje me med nasprotnike svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 12, 'Čete njegove so hkrati pridrle in napravile svojo pot zoper mene, in raztaborile so se okrog šatora mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 13, 'Brate moje je oddalil od mene, in znanci moji so se mi docela odtujili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 14, 'Odtegujejo se mi bližnji sorodniki moji in zaupniki moji so me pozabili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 15, 'Gostači hiše moje in dekle moje me štejejo za tujca, inostranec sem postal v njih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 16, 'Kličem hlapca svojega, a ne da mi odgovora, z usti svojimi ga milo moram prositi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 17, 'Dih moj se gnusi ženi moji in smrad moj matere moje otrokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 18, 'Celo deca me zaničuje; ko hočem vstati, govore zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 19, 'Mrzé me vsi, ki sem se ž njimi srčno družil, in katere sem ljubil, so se obrnili zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 20, 'Kosti mi lepé na koži in mesu, komaj zobrnice so mi ostale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 21, 'Usmilite se me, usmilite se me, prijatelji moji, kajti roka Božja me je zadela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 22, 'Zakaj me preganjate kakor Bog mogočni in se ne morete nasititi mesa mojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 23, 'O da bi se zapisale besede moje, o da bi se začrtale v knjigo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 24, 'Da bi jih v skalo vsekali z železnim pisalom in s svincem zalili za vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 25, 'A jaz vem, da živi Odrešenik moj, in On, ki je poslednji, se postavi nad prahom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 26, 'in ko bo za kožo mojo to telo strto, vendar bom gledal iz svojega mesa Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 27, 'ki ga jaz sam bom gledal sebi v dobro, in ga bodo videle moje oči, in ne bodem mu tujec. Obisti moje koprne v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 28, 'Ako govorite, kako ga bomo preganjali! češ, da se je korenina hudobne stvari našla v meni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 19, 29, 'bojte se meča! kajti meč bo maščeval krivice, da bi vedeli, da je sodba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 1, 'Tedaj odgovori Zofar Naamatec in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 2, 'Zato mi odgovarjajo misli moje in zaradi tega sem znotraj razburjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 3, 'Svarilo, sebi v sramoto, mi je poslušati! A duh moj po razsodnosti svoji mi odgovarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 4, 'Ne veš li tega, kar je od vekomaj, odkar je bil človek postavljen na zemljo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 5, 'da je zmagoslavje brezbožnih kratko in radost bogapozabnika le za trenotek?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 6, 'Najsi celó do neba stopa visokost njegova in glava njegova se dotika oblakov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 7, 'kakor blato njegovo pogine za vselej; kateri so ga videli, poreko: Kje je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 8, 'Kakor sen odleti, in ne bodo ga našli, izgubi se kakor ponočna prikazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 9, 'Oko ga je ugledalo, a ne bo ga videlo več, in nikdar več ga ne bo gledalo mesto njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 10, 'Njegovi otroci bodo iskali prijaznosti ubogih in njih roke bodo povračale oškodovancem imetje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 11, 'Kosti so mu bile polne mladostne moči, ta pa zdaj leži ž njim v prahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 12, 'Čeprav mu je hudoba sladka v ustih in jo skriva pod jezikom svojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 13, 'jo slastno goji in je noče pustiti, ampak jo zadržuje v grlu svojem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 14, 'vendar se izpremeni hrana v životu njegovem, kačji strup bode v notranjščini njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 15, 'Bogastvo je požrl, pa ga bo izbljuval, iz trebuha mu ga potegne Bog mogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 16, 'Sesal je kačji strup: gadji jezik ga usmrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 17, 'Ne bo gledal veselja svojega v potokih, v tekočih rekah medu in smetane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 18, 'Povrniti mora, kar je pridelal, ne sme tega uživati; primerno imetju, ki ga je pridobil, se ne more veseliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 19, 'Kajti potrl je in zapustil ubožce, hiše si je siloma vzel, a ne bo jih dozidal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 20, 'Kajti pokoja ni poznal v osrčju svojem, zato ne ohrani ničesar, kar mu je drago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 21, 'Nič ni ušlo njegovi požrešnosti, zato ne bode trpežno blagostanje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 22, 'Ko bode v obilni obilosti, ga zadene stiska, roka vsakega trpina pride nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 23, 'Ko si bo hotel napolniti trebuh, Bog spusti nanj jeze svoje togoto, in deževala bo nanj, njemu v jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 24, 'Bežal bo pred železnim orožjem, a prestreli ga bronasti lok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 25, 'Izdere pšico, in pride ven iz telesa njegovega, svetlo jeklo iz žolči njegove, strahote ga objamejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 26, 'Zgolj nesreča je prihranjena za vse zaklade njegove, požre ga ogenj, ki ga človek ne podpihava, požge, kar je preostalo v šatoru njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 27, 'Nebesa razkrijejo njegovo krivico, in zemlja se vzdigne zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 28, 'Dobiček hiše njegove se spravi vstran, povodenj ga odplavi v dan jeze Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 20, 29, 'To je človeku brezbožnemu delež od Boga in dediščina, prisojena mu od Boga mogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 1, 'Nato odgovori Job in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 2, 'Pazljivo poslušajte govorjenje moje, in to bodi namesto vaših tolažb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 3, 'Potrpite, in tudi jaz bom govoril, in ko dogovorim, se posmehujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 4, 'Mar tožba moja velja ljudem? ali kako naj ne bi bil žalosten duh moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 5, 'Obrnite se k meni in strmite in položite roko na usta svoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 6, 'Res, kadar se tega spomnim, se prestrašim in trepet prešine meso moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 7, 'Zakaj žive brezbožniki, dočakajo starosti, množe si tudi bogastvo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 8, 'Njih seme stoji trdno ž njimi vred vpričo njih in njih zarod pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 9, 'Njih hiše so v miru, brez straha, in Božje šibe ni nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 10, 'Njih junci skačejo in ne neplodno, njih krave se lahko otele in ne izvržejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 11, 'Deco odpošiljajo kakor ovac krdelo in njih otroci plešejo veselo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 12, 'Pevajo glasno z bobnicami in citrami in se vesele ob glasu piščali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 13, 'V sreči prežive svoje dni, in v trenutku se pogreznejo v kraj mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 14, 'In vendar govore Bogu mogočnemu: Pojdi od nas, ker spoznanja tvojih potov ne želimo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 15, 'Kaj je Vsemogočni, da bi mu služili, ali kaj nam hasni, če se mu z molitvijo bližamo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 16, 'Glej, njih sreča vendar ni v njih rokah. Svetovanje brezbožnih bodi daleč od mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 17, 'Kolikokrat se dogodi, da ugasne svetilo brezbožnikov in pridrevi nadnje njih poguba? da jim Bog podeli žalosti v srdu svojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 18, 'da so kakor rezanica pred vetrom in kakor pleve, ki jih razpiše vihar?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 19, 'Bog hrani, pravite, krivdo brezbožnikovo za otroke njegove. Njemu naj jo povrne, da jo on čuti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 20, 'S svojimi očmi naj gleda svojo pogubo in pije naj od togote Vsegamogočnega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 21, 'Kajti kaj bo maral za hišo svojo za seboj, ko se prestreže število mesecev njegovih? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 22, 'More li kdo Boga mogočnega učiti spoznanja, ko vendar on sodi tiste, ki so na višavah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 23, 'Tale umrje v obili moči svoji, ko je popolnoma brez skrbi in v miru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 24, 'posode njegove so polne mleka in kosti njegove z mozgom pitane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 25, 'Oni umrje v bridkosti duše, in nikdar ni okusil dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 26, 'Skupaj ležita v prahu, črvad ju oba pokriva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 27, 'Glejte, jaz poznam misli vaše in naklepe, s katerimi me nadlegujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 28, 'Kajti pravite: Kje je hiša mogočneža in kje šator, ki so v njem prebivali brezbožni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 29, 'Niste li vprašali popotnikov? in njih znamenita poročila boste pač pripoznali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 30, 'da Bog hrani hudobneža do dne pogube, da ga odpravi v dan jeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 31, 'Kdo mu sme očitati v obraz pot njegovo? in kdo mu povrne, kar je storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 32, 'Prav njega spremijo s častjo do groba, in nad gomilo ga še čuvajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 33, 'Lahke mu so grude v dolini; in za njim pojdejo vsi ljudje, kakor jih je šlo brezštevilno pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 21, 34, 'Kako me torej zaman tolažite? Od vaših odgovorov ostane le nezvestoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 1, 'Tedaj odgovori Elifaz Temančan in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 2, 'More li mož koristiti Bogu mogočnemu? Marveč sebi koristi razumnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 3, 'Hasni li Vsegamogočnemu, da si pravičen, ali pa ima kaj dobička, ko brezmadežne hraniš poti svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 4, 'Je li zaradi tvoje bogaboječnosti, da te svari, s teboj hodi v pravdo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 5, 'Ali ni velika tvoja hudobnost in krivic tvojih ni li brez konca?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 6, 'Brate svoje si rubil brez vzroka in polunagim si slekel obleko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 7, 'Utrujenega nisi napojil z vodo in lačnemu si odrekel kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 8, 'A siloviti mož si je lastil deželo, in imenitnik je prebival v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 9, 'Vdove si pošiljal prazne od sebe, in rame sirot so bile strte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 10, 'Zato je okrog tebe zadrga za zadrgo in plaši te nagel strah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 11, 'Ali pa ne vidiš temine in povodnji, ki te zagrinja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 12, 'Ni li Bog visok kakor nebesa? Poglej le najvišje zvezde, kako so vzvišene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 13, 'A ti praviš: Kaj bi vedel Bog mogočni? more li skozi oblačno temino soditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 14, 'Oblačje Mu je ovoj, da ne vidi, in po okrožju nebes se izprehaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 15, 'Hočeš se li držati davnega veka steze, po kateri so hodili hudobni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 16, 'ki so bili odpravljeni pred svojim časom? njih trdna tla so se razlila kakor reka –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 17, 'ki so rekali Bogu mogočnemu: Pojdi od nas! in: Kaj more pač Vsemogočni storiti za nas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 18, 'In vendar je On napolnil njih hiše z blaginjo! – Toda svetovanje brezbožnih bodi daleč od mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 19, 'Pravični to vidijo in se vesele, in nedolžni jih zasmehuje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 20, 'govoreč: Res, iztrebljeni so, ki so se vzpenjali zoper nas, in ogenj je požrl, kar je ostalo za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 21, 'Sprijazni se, pravim, ž Njim in imej mir, in blagostanje ti s tem pride.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 22, 'Sprejmi vendar pouk iz ust Njegovih in vtisni si besede Njegove v srce!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 23, 'Ako se obrneš k Vsemogočnemu, te zopet ustanovi, če odpraviš nepravičnost iz šatorov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 24, 'In vrzi v prah drago kovino in med kamenčke v potoku ofirsko zlato:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 25, 'potem bode Vsemogočni zaklad tvoj in drago srebro tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 26, 'Kajti tedaj se boš razveseljeval Vsemogočnega in k Bogu povzdigneš obličje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 27, 'Molil boš k njemu, in te usliši, in obljube svoje boš opravljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 28, 'Ko ukreneš kako stvar, se ti uresniči, in luč ti bo sijala nad poti tvojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 29, 'Ko bodo vodile doli, boš velel: Navzgor! in ponižanemu daje Bog pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 22, 30, 'Rešil bo tudi njega, ki ni brez krivde, da, rešen bo po čistosti tvojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 1, 'In Job odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 2, 'Tudi danes še je kljubovalen odgovor moj; udarec moj je težji nego zdihovanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 3, 'O da bi vedel, kje Ga morem najti, da bi prišel prav do Njegovega stola!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 4, 'Razložil bi pravdo svojo pred Njim, usta svoja bi napolnil z dokazi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 5, 'Hotel bi znati besede, ki mi jih odgovori, in poslušati, kar mi poreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 6, 'Ali bi se prepiral z menoj v veliki moči svoji? Ne; On bi samo pazil name.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 7, 'Tedaj bi se jaz poštenjak pravdal ž njim, in za večno bi se rešil sodnika svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 8, 'Glej pa, če grem proti vzhodu, tam ga ni, in proti zahodu, ga ne zasledim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 9, 'če proti severu, ko vrši delo, ga ne zagledam, zavije se proti jugu, in ga ne vidim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 10, 'Kajti On pozna pot, katere se držim; ko bi me preizkušal, bi se izkazal kakor zlato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 11, 'Koraka njegovega se je trdno držala noga moja, na pot njegovo sem pazil in nisem stopil ž nje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 12, 'od zapovedi njegovih usten se nisem umaknil; bolj nego lastno postavo sem hranil ust njegovih besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 13, 'Ali on si je vedno enak, in kdo ga more odvrniti od njegovih misli? Česar želi duša njegova, to stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 14, 'Kajti on dopolni, kar je določeno zame; in takih reči je veliko pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 15, 'Zato se strašim pred njegovim obličjem; ko to premišljam, se ga bojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 16, 'Ker Bog mogočni mi je preplašil srce in Vsegamogočni me je prestrašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 23, 17, 'Kajti nisem poginil od temine, tudi ne, ker mi je mrak zakril obraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 1, 'Zakaj ni vnaprej določil Vsemogočni sodnih rokov? in zakaj ne vidijo, kateri ga poznajo, njegovih sodnih dni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 2, 'Krivičniki prestavljajo mejnike, plenijo črede in jih sebi pasejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 3, 'Osle sirotam odganjajo in vdovam jemljejo v zastavo vole.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 4, 'Ubožce pehajo s cest, krotki, kar jih je v deželi, se morajo skrivati vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 5, 'Glej, kakor divji osli v pustinji hodijo ubožci na delo svoje, marljivo iščoč plena: puščava jim daje hrane za njih otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 6, 'Na polju žanjejo žito krivičnikovo in paberkujejo v njegovem vinogradu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 7, 'Nagi leže vso noč, ker nimajo obleke, in nimajo odeje v mrazu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 8, 'Lijak z gora jih premoči, in ker nimajo strehe, se oklepajo skalovja. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 9, 'Siroto od prsi trgajo krivičniki, in kar ima na sebi ubožec, jemljejo v zastavo. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 10, 'Goli hodijo, brez oblačila, in lačni nosijo bogatinom snope;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 11, 'v njih hramih jim morajo delati olje, tlačijo v tlačilnici in žeje se suše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 12, 'Iz mesta se sliši ječanje umirajočih, in duša ranjencev vpije. A Bog tega ne šteje za nepristojnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 13, 'Drugi pa so sovražniki svetlobe: njenih potov ne poznajo, na njenih stezah ne ostajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 14, 'Ob jutranjem svitu vstaja razbojnik, mori ubožca in potrebnega, in po noči je kakor tat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 15, 'In oko prešeštnikovo čaka, da nastane mrak, češ: Nobeno oko me ne zagleda, in krinko si dene na obraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 16, 'V temi vdirajo v hiše; po dnevi se zapirajo, svetlobe ne poznajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 17, 'Kajti najbolj črna tema jim je vsem jutro, ker vsak izmed njih je vešč grozotam črne teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 18, 'Hiter je v teku svojem po površju vodá; njih delež je proklet na zemlji; ne hodi več po poti proti vinogradom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 19, 'Suša in vročina odpravita snežnico: enako šeol tiste, ki so grešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 20, 'Mati pozabi takega, črvadi bo dobro teknil, ne bodo se ga več spominjali; tako bo strta kakor drevo nepravičnost');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 21, 'tistega, ki je plenil nerodovitno, ki ni rodila, in vdovi ničesar ni storil dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 22, 'Bog pa z močjo svojo dolgo vzdržuje mogočneže; marsikateri še vstane, ko je že obupal nad življenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 23, 'Bog mu daje varnosti, in on se naslanja nanjo; toda oči Njegove so nad njih poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 24, 'Stopijo visoko, a malo le, pa jih ni več; zvrnejo se, smrt jih pograbi kakor vse druge, posečeni bodo kakor dozoreli klasovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 24, 25, 'Ni li tako? Kdo dokaže, da lažem, in dene v nič govor moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 1, 'In Bildad Šuhec odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 2, 'Vladarstvo in strah je pri Njem; On napravlja mir na svojih višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 3, 'Je li mogoče prešteti vojske Njegove? in Njegova luč nad kom se ne vzdiguje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 4, 'Kako pa more smrtni človek biti pravičen pred mogočnim Bogom? in kakor bi mogel biti čist rojeni od žene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 5, 'Glej, še mesec ne sveti jasno in zvezde niso čiste v očeh Njegovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 25, 6, 'koliko manj smrtni človek, ki je črv, in sin človečji, ki je črvič!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 1, 'Job pa odgovori in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 2, 'Kako lepo si podprl šibkega, kako si pomagal rami slabotnega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 3, 'kako si izvrstno svetoval njemu, ki nima modrosti, in temeljitega znanja obilo pokazal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 4, 'Komu si govoril besede, in čigav duh je šel iz tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 5, 'Mrtvi strepetavajo pred Bogom globoko pod vodami in njih prebivalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 6, 'Smrtna država je odkrita pred Njim in peklenska globočina nima pokrova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 7, 'On razteza severno nebo čez praznino in zemljo obeša na ničemer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 8, 'Vkup veže vode v oblakih svojih, in oblačje se pod njimi ne razdere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 9, 'Zastira lice prestola svojega, ko ob njem razgrinja oblake svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 10, 'Zakrožil je mejo na površju vodá do zadnjega kraja, kjer mejita svetloba in tema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 11, 'Stebrovi neba se stresajo in se groze od njegovega karanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 12, 'Po svoji moči razburja morje in po svoji previdnosti razbija morsko pošast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 13, 'Duh njegov razvedruje nebo, roka njegova je prebodla bežečega zmaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 26, 14, 'Glej, to je majhen obris dejanja Njegovega; in kako rahlo šepetanje, ki ga slišimo o Njem! A grmenje Njegove vsemogočnosti kdo more razumeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 1, 'In Job je nadaljeval govor svoj in rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 2, 'Kakor res živi Bog silni, ki mi je odvzel pravico, in Vsegamogočni, ki žali dušo mojo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 3, '(kajti življenje moje je še v meni in duh Božji v nosnicah mojih):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 4, 'ustne moje ne govore krivičnega in jezik moj ne izreče prevare!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 5, 'Vam nikakor ne priznam pravičnosti; dokler ne umrem, ne dam si vzeti brezmadežnosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 6, 'Pravičnosti svoje se držim in je ne pustim; srce mi ne očita ne enega mojih dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 7, 'Sovražnik moj naj se pokaže kot brezbožnik, in kdor se stavi zoper mene, kakor krivičnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 8, 'Kajti kaj je bogapozabnikova nada, če mu Bog prestriže življenje in vzame dušo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 9, 'Bo li Bog mogočni slišal njegovo vpitje, ko pride stiska nadenj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 10, 'More se li veseliti Vsemogočnega in klicati Boga vsakteri čas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 11, 'Naj vas poučim o roki Boga silnega; kar je pri Vsegamogočnem, nočem utajiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 12, 'Glejte, sami ste to vsi videli, zakaj torej blebetate ničevo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 13, 'To je delež krivičnega človeka pri Bogu mogočnem in silovitnikov dediščina, ki jo dobivajo od Vsemogočnega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 14, 'Ko se mu množe otroci, množe se za meč, in potomci njegovi nimajo kruha dositega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 15, 'Kar preostane njegovih, bodo pokopani v pomoru, in vdove njegove ne bodo žalovale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 16, 'Ako si nakopiči srebra kakor prahu in si oblačil oskrbi kakor blata:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 17, 'pripravi si jih, a pravičnik jih bo oblekel, in nedolžni si med seboj razdele srebro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 18, 'Zida si hišo, ki je kakor moljava in kakor koča, ki si jo napravi čuvaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 19, 'Bogat gre spat, a ne leže v drugič, odpre oči, in ni ga več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 20, 'Grozote ga dohite kakor voda, po noči ga ugrabi vihar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 21, 'Vzhodni veter ga vzame, da odide, in ga odnese z mesta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 22, 'In Bog bo lučal vanj brez prizanašanja, roki Njegovi zaman bo poskušal ubežati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 27, 23, 'Ploskali bodo nad njim z rokami in izžvižgajo ga z mesta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 1, 'Kajti srebro ima svoje žile in zlato kraj, kjer se čisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 2, 'Železo se dobiva iz zemlje in iz kamenja izpuščajo s topljenjem bron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 3, 'Temi napravljajo konec in preiskujejo do najskrajnejših mej kamene, skrite v temini in v smrtni senci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 4, 'Navpik izkopljejo predor, koder popotnik ne hodi, po stezah, ki nanje noga ne stopi, se spuščajo doli in zibljejo semtertja daleč od ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 5, 'Iz zemlje raste kruh, a pod njo rijejo kakor ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 6, 'Med njenimi kameni se nahaja safir in gruče zlata so v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 7, 'Te steze ropna ptica ni poznala in kraguljevo oko je ni videlo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 8, 'ni po njej stopala ponosna zver in lev rjoveči ni po njej hodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 9, 'Trdega kamena se loti človek z roko svojo, izpodkopava gore od dna;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 10, 'prekope izsekava skozi skalovje in raznotere dragocenosti ugleda oko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 11, 'Zajezuje struge, da ne solzé, in kar je skrito, prinaša na luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 12, 'Ali modrost, kje se nahaja? in kje je kraj razumnosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 13, 'Smrtni človek ne pozna njene cene, in v deželi živečih je ni najti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 14, 'Brezno pravi: Ni je v meni, in morje govori: Ni je pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 15, 'Prečiščenega zlata ne moreš zanjo dati, ne dosti srebra odtehtati, da bi jo plačal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 16, 'Ne more se ceniti s čistim zlatom ofirskim, z dragocenim oniksom ali safirjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 17, 'Zlato in steklo se ji ne moreta primerjati, ne posoda iz prečiščenega zlata zanjo zamenjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 18, 'Koraljev in kristala ni poleg nje omenjati, in pridobiti modrost je veliko dražje nego bisere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 19, 'Ne more se ji enačiti topas iz Etiopije, ne da se oceniti s čistim zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 20, 'Odkod torej prihaja modrost, in kje je kraj razumnosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 21, 'Prikrita je očem vseh živih bitij in skrita pticam pod nebom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 22, 'Pogubljenje in smrt pravita: Glas o njej smo čuli z ušesi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 23, 'Bog ve pot do nje, in on pozna njen kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 24, 'Zakaj on gleda do koncev zemlje in vidi vse, kar je pod nebom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 25, 'Ko je vetru določal težo in vode tehtal in meril,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 26, 'ko je ustanavljal postavo dežju in pot blisku in gromu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 27, 'tedaj jo je videl in jo naznanil, jo postavil, pa tudi preizkusil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 28, 28, 'In človeku je dejal: Glej, strah Gospodov je modrost, in ogibati se hudega je razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 1, 'In Job je nadaljeval govor svoj in rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 2, 'O da bi bil še kakor v nekdanjih mesecih, kakor v dneh, ko me je Bog varoval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 3, 'ko mi je svetilnica njegova sijala nad glavo in ko sem pri njegovi luči hodil po temi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 4, 'kakor sem bil v dneh zrelosti svoje, ko je bilo prijateljstvo Božje nad šatorom mojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 5, 'ko je bil še Vsemogočni z menoj, otroci moji okoli mene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 6, 'ko sem si umival noge v smetani in je skala poleg mene izlivala potoke olja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 7, 'Ko sem šel skozi vrata v mesto, stol svoj si postavil na ulici,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 8, 'mladeniči so me videli in se skrili, in starci so se vzdignili in stali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 9, 'knezi so zadrževali besede, položivši roko na usta svoja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 10, 'plemenitnikov glas je onemel in jezik se jim je k nebesu prilepil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 11, 'Ker ko je uho slišalo o meni, je blagrovalo mene, in ko me je oko videlo, je pričalo zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 12, 'Zakaj otel sem ubožca, ki je vpil za pomoč, in siroto, ki ji ni bilo pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 13, 'Blagoslov tistega, ki bi bil skoro poginil, je prišel nadme, in srce vdove sem spravil v radostno petje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 14, 'Oblačil sem pravičnost – bila mi je v obleko, in gorečnost za pravico mi je bila kakor plašč in venec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 15, 'Slepcu sem bil oko in noga hromcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 16, 'Oče sem bil potrebnim in pravdo tistega, ki ga nisem poznal, sem preiskoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 17, 'Strl sem nepravičniku kočnike in zobom njegovim sem iztrgal plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 18, 'Zato sem dejal: V gnezdu svojem bom umrl in pomnožim kakor pesek dni svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 19, 'Korenina moja se bo raztezala kraj vode in rosa bo nočevala na mojem vejevju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 20, 'slava moja ostane vedno nova pri meni in lok moj se bo pomlajeval v roki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 21, 'Mene so poslušali in čakali in molče na uho vlekli moj svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 22, 'Po mojih besedah ni nihče govoril, in govorjenje moje je nanje kapljalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 23, 'Čakali so me kakor dežja in odpirali usta svoja kakor zemlja, hrepeneč po poznem dežju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 24, 'Nasmehljaval sem se jim, kadar so obupavali, in svetlobe obličja mojega niso mogli omračiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 29, 25, 'Rad sem krenil na pot k njim in sedel kot glava, in stoloval sem pri njih kakor kralj med vojsko, kot tisti, ki tolaži žalujoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 1, 'Sedaj pa se mi smejejo mlajši od mene, ki njih očetov nisem maral pridružiti psom črede svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 2, 'Kaj bi mi bila tudi koristila krepkost njih rok? saj jim je izginila mladostna čvrstost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 3, 'Shujšani od stradanja in lakote, glojejo suho zemljo, ki je od nekdaj pusta in prazna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 4, 'Trgajo lobodo ob grmeh, in korenina bodičevja je njih hrana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 5, 'Izganjajo jih ljudje izmed sebe, vpijejo za njimi kakor za tatovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 6, 'Po strašnih prepadih morajo bivati, po jamah in skalnih votlinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 7, 'Izza grmovja vreščijo, med koprivami se zbirajo –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 8, 'otroci bedakov, da, otroci brezčastnežev, z bičem izgnani iz dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 9, 'In tem sem sedaj v zabavljivo pesem, postal sem jim v prislovico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 10, 'Gnusim se jim, stopajo daleč od mene in ne prizanašajo licu mojemu s pljuvanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 11, 'Kajti Bog mi je razrešil vrv življenja in me ponižal, zato so si popustili uzdo pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 12, 'Na desnici se mi postavlja tista zalega, noge mi odpahujejo stran, zoper mene napravljajo poti svoje, meni v pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 13, 'Razdirajo stezo mojo, pospešujejo mi pogubo, oni, ki sami so brez pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 14, 'Kakor skozi širok predor se rinejo sem, lomasteč se vale nadme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 15, 'Strahote so se obrnile proti meni. Čast moja se je razprhnila kakor v viharju, in sreča moja je minila kakor leteč oblak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 16, 'In sedaj se razliva v meni duša moja; dohiteli so me bede polni dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 17, 'Noč mi vrta po kosteh, da se mi drobé, in glodajoče bolečine mi ne mirujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 18, 'Vsled velike sile bolezni se mi grdo prilega obleka, oklepa me kakor telovnika mojega ovratnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 19, 'Pahnil me je v blato, da sem enak prahu in pepelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 20, 'Vpijem k tebi, a mi ne odgovarjaš, stojim proseč, pa me le strmo gledaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 21, 'Izpreobrnil si se v grozovitnega meni, z močjo roke svoje me preganjaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 22, 'Vzdiguješ me gori na veter, da bi odletel in se razrušil v šumu viharja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 23, 'Kajti vem, da me odpelješ v smrt in v hišo, ki je določena vsem živečim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 24, 'Toda ne iztegne li kdo roke svoje, ko pada? in če kdo gine, ne vpijejo li za pomoč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 25, 'Ali nisem jokal nad njim, ki ga je zadela nesreča? ni li mi bilo v duši žal siromaka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 26, 'Kajti čakal sem dobrega, a prišlo je hudo, nadejal sem se svetlobe, a prišla je tema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 27, 'Osrčje moje v bridkosti kipi in ne miruje, zadeli so me mučni dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 28, 'Žalujoč hodim semtertja, brez solnca, stojim v zboru in vpijem za pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 29, 'Brat sem postal šakalom, nojem pa tovariš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 30, 'Koža mi je očrnela in se lupi raz mene, kosti moje goré od vročine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 30, 31, 'In tako se je premenila harfa moja v žalostinko in piščal moja v jokanja glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 1, 'Zavezo sem sklenil s svojimi očmi, in kako bi se bil smel ozirati po devici?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 2, 'A kaj mi je delež Božji odzgoraj in dediščina Vsemogočnega iz visokosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 3, 'Ni li poguba nepravičniku in nesreča njim, ki delajo krivico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 4, 'Ne vidi li On potov mojih in ne šteje li vseh korakov mojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 5, 'Ako sem se pečal z ničemurnostjo in je noga moja hitela v prevaro');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 6, '(naj me pretehta na tehtnici pravičnosti, in spozna Bog brezmadežnost mojo!),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 7, 'ako je krenil korak moj s prave poti in mi je srce hodilo za očmi mojimi in se je madež prijel mojih rok:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 8, 'sejem naj, a drug uživaj, in kar sem zasadil, naj se s korenino izdere!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 9, 'Ako mi je znorelo srce za katero ženo in sem prežal pri vratih bližnjega svojega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 10, 'naj žena moja melje drugemu in drugi naj se nadnjo sklanjajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 11, 'Kajti to je ostudnost, to je pregreha, ki jo morajo kaznovati sodniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 12, 'Kajti to je ogenj, ki požira do pogubljenja in ki bi s korenom izdrl vse, kar sem pridelal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 13, 'Ako nisem spoštoval pravice hlapca svojega in dekle svoje, ko sta se prepirala z menoj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 14, 'kaj si počnem, če vstane Bog mogočni, in ko bo preiskoval, kaj mu odgovorim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 15, 'Ni li tudi njega Stvarnik moj naredil v materinem telesu, in ni li eden naju pripravil v materini otrobi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 16, 'Ako sem ubožcem odrekel, kar so želeli, in povzročil, da so vdovine oči medlele,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 17, 'ali če sem jedel grižljaj svoj sam in ni tudi jedla od njega sirota');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 18, '(pač od mladosti moje je rasla pri meni kakor pri očetu in od materinega telesa sem bil vdovi vodnik);');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 19, 'ako sem koga videl blizu pogina, ker ni imel oblačila, in potrebnega brez odeje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 20, 'in če me ni blagoslavljalo ledje njegovo in če se z volno mojih ovac ni ogreval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 21, 'ako sem vihtel roko proti siroti, ker sem videl, da mi je pomoč med vrati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 22, 'odpadi mi pleče od lopatice svoje in rama moja se odlomi od njene cevi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 23, 'Zakaj pogubljenje od Boga mogočnega mi je bilo v strah in vpričo Njegove vzvišenosti nisem mogel ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 24, 'Ako sem postavil zlato za nado svojo in čistemu zlatu rekel: Upanje moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 25, 'ako sem se veselil, da mi je bilo imetja veliko ter da je moja roka mnogo pridobila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 26, 'ako sem gledal solnce, kako je sijalo, in v diki plavajoči mesec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 27, 'in srce mi je bilo skrivaj omamljeno, da sem njima v čast poljubljal roko svojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 28, 'tudi to bi bila pregreha, kazni vredna pred sodniki, ker bi bil zatajil Boga mogočnega, ki je gori!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 29, 'Ako sem se veselil nesreče sovražilca svojega in se vzradoval, ko ga je zadelo zlo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 30, '(a nikoli nisem dopustil grlu svojemu grešiti, da bi bil s kletvijo zahteval smrt njegovo!),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 31, 'ako niso rekali šatora mojega ljudje: Kdo bi se ne bil nasitil mesa njegove živine?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 32, 'na ulicah ni bilo treba prenočevati tujcu, duri svoje sem odprl popotniku –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 33, 'ako sem, kakor Adam, prikrival prestopke svoje, skrivaje v nedrijih krivdo svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 34, 'ker sem se bal velike množice in me je strašilo zaničevanje rodovin, tako da sem molčal in nisem stopil ven iz duri...');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 35, 'O da bi imel koga, ki bi me poslušal! (tu je moj podpis, Vsemogočni naj mi odgovori!) in da bi imel tožbenico, ki jo je pisal nasprotnik moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 36, 'Res, na rami svoji bi jo nosil in si jo navezal kakor venec!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 37, 'Korakov svojih število bi mu naznanil, pristopil bi k njemu kakor knez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 38, 'Ako vpije nad menoj njiva moja in brazde njene vse vkup jokajo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 39, 'ako sem užival njen pridelek, ne da bi bil plačal, in sem provzročil, da je njen posestnik izdahnil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 31, 40, 'tedaj mi rasti osatje namesto pšenice in namesto ječmena grd plevel! Konec je besedam Jobovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 1, 'In oni trije možje so nehali odgovarjati Jobu, ker je bil pravičen v svojih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 2, 'Tedaj se vname jeza Elihuju, sinu Barakela, Buzovcu, iz rodovine Ramove; zoper Joba se mu vname jeza, ker je sebe bolj opravičeval nego Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 3, 'Tudi zoper tri prijatelje njegove se je razsrdil, zato ker niso našli odgovora in so vendar obsojali Joba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 4, 'Elihu pa je čakal Joba z besedami, ker oni so bili starejši nego on.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 5, 'In ko je videl Elihu, da ni bilo odgovora v ustih tistih treh mož, tedaj se mu razvname jeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 6, 'In izpregovori Elihu, sin Barakelov, Buzovec, in reče: Mlad sem po letih, vi pa ste starci, zato me je bilo sram in sem se bal vam povedati svoje misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 7, 'Dejal sem: Naj leta govore in visoka starost naj oznani modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 8, 'Toda duh v smrtnikih je in dih Vsemogočnega, ki jih dela razumne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 9, 'Priletni niso vselej modri in starci ne umejo vsekdar, kar je prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 10, 'Zato pravim: Poslušaj mene, tudi jaz hočem povedati misli svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 11, 'Glejte, čakal sem besed od vas, poslušal sem vašo razsodnost, dokler bi bili iznašli, kar je odgovoriti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 12, 'in skrbno sem pazil na vas; a glejte, ni ga med vami, ki je prepričal Joba in odgovoril besedam njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 13, 'Nikar torej ne pravite: Našli smo modrost; Bog mogočni ga premore, ne človek!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 14, 'Kajti proti meni ni nameril besed; in z vašimi govori mu ne bom odgovarjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 15, 'Osupnili so, ne odgovarjajo več, pošle so jim besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 16, 'In jaz naj čakam, ker oni ne govore, ker tu stoje in ne odgovarjajo več?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 17, 'Odgovoril bom tudi jaz svoj del, tudi jaz povem mnenje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 18, 'Kajti poln sem besed, pritiska me duh moj v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 19, 'Glej, život mi je kakor vino, ki nima duška, kakor novi sodi hoče počiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 20, 'Moram govoriti, da se oddahnem, odprem torej ustne svoje in odgovorim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 21, 'Da bi le z nikomer pristranski ne potegnil! In nobenemu človeku se nočem prilizovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 32, 22, 'Saj tudi ne poznam prilizovanja: sicer bi me v kratkem vzel Stvarnik moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 1, 'Sedaj pa, o Job, prosim, poslušaj govore moje in sprejmi v ušesa vse besede moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 2, 'Glej, odprl sem usta svoja, jezik moj govori v ustih mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 3, 'Besede moje bodo izrekale srca mojega poštenost, in kar vedo ustne moje, čisto povedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 4, 'Duh Boga mogočnega me je storil in dih Vsemogočnega me oživlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 5, 'Ako moreš, mi odgovori, pripravi si besede proti meni, postavi se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 6, 'Glej, Boga mogočnega sem stvar kakor ti, iz ila sem narejen tudi jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 7, 'Glej, strah do mene te ne spravi v trepet in pest moja ti ne bode pretežka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 8, 'Zares, rekel si pred mojimi ušesi, in slišal sem glas besed:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 9, 'Čist sem, brez prestopka, nedolžen sem in krivice ni na meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 10, 'Glej, On išče prilike v nasprotovanju meni, šteje me sebi za sovražnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 11, 'Noge mi stiska v klado, pazi na vse steze moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 12, 'Glej, o tem ne sodiš prav, ti odgovarjam, zakaj Bog je višji nego smrtni človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 13, 'Čemu se prepiraš ž Njim? kajti On ni dolžen odgovoriti za nobeno svojih dejanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 14, 'Pač govori Bog mogočni enkrat ali dvakrat, a človek ne opazi tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 15, 'V sanjah, v nočni prikazni, kadar trdno spanje objema ljudi, ko dremljejo na ležišču:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 16, 'tedaj odpira uho ljudem in pritiska pečat na pouk, ki jim ga daje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 17, 'da odvrne človeka od njegove nakane ter ga obvaruje napuha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 18, 'da odtegne dušo njegovo izpred jame in življenje njegovo, da ne leti v strelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 19, 'Kaznovan je tudi z bolečinami na ležišču svojem in z neprestano borbo v kosteh svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 20, 'tako da se mu studi kruh v življenju in duši njegovi najljubša jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 21, 'Meso mu gine, da ga ni videti, in gole so kosti njegove, ki jih prej ni bilo videti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 22, 'in duša njegova se bliža jami in življenje njegovo pogubnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 23, 'Ako se zanj potegne angel posredovalec, eden iz tisoč, da pokaže človeku pravo pot njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 24, 'tedaj mu bo On milostiv in poreče: Reši ga, da ne pade v jamo; našel sem zanj odkupnino!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 25, 'Potem bo meso njegovo bohotnejše nego otročje, povrne se k dnevom mladostne kreposti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 26, 'Prosil bo Boga, in On ga blagovoljno sprejme, da bo videl obličje Njegovo z veselim ukanjem; in Bog povrne človeku pravičnost njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 27, 'Pred ljudmi bo pel in govoril: „Grešil sem in izprevrnil, kar je bilo prav, a ni mi povrnil, kakor sem zaslužil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 28, 'Odrešil je dušo mojo, da ne bi šla v jamo, in življenje moje z veseljem gleda svetlobo.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 29, 'Glej, vse to stori Bog mogočni dvakrat, trikrat pri človeku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 30, 'da odvrne dušo njegovo od jame, da bi bila razsvetljena z lučjo življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 31, 'Pazi, Job, poslušaj me, molči, in jaz naj govorim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 32, 'Ako imaš besede, odgovori mi, govóri, saj te želim opravičiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 33, 33, 'Ako pa nimaš, poslušaj le mene, molči, in učil te bom modrosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 1, 'Še izpregovori Elihu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 2, 'Poslušajte, modrijani, besede moje, in veščaki, naklonite mi posluh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 3, 'Kajti uho presoja besede kakor grlo okus jedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 4, 'Izvolímo zase, kar je prav, spoznajmo med seboj, kar je dobro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 5, 'Kajti Job je rekel: „Pravičen sem, in Bog mogočni mi je vzel pravico mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 6, 'Vkljub svoji pravici veljam za lažnika; rana moja je nezaceljiva, dasi sem brez prestopka.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 7, 'Kje je mož kakor Job, ki pije roganje kakor vodo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 8, 'in s hudodelniki hodi v družbi in občuje z brezbožnimi ljudmi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 9, 'Zakaj dejal je: Nič ne hasni možu, če rad občuje z Bogom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 10, 'Zato me poslušajte, možje razumni! Daleč bodi krivičnost od Boga silnega in od Vsemogočnega nepravičnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 11, 'Toda dejanje človekovo mu povrača in dela, da se mu godi po tem, kakor je živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 12, 'Da zares, Bog mogočni ne ravna krivično in Vsemogočni ne skrivi pravice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 13, 'Kdo mu je poveril zemljo? in kdo je postavil ves zemeljski krog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 14, 'Ako bi srce obrnil le na sebe, duha svojega in svoj dih potegnil nase,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 15, 'vse meso bi hkratu pomrlo in človek bi se povrnil v prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 16, 'Ako si torej pameten, poslušaj to, čuj besed mojih glas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 17, 'More li tudi vladati, kdor sovraži pravico? ali hočeš obsoditi Njega, ki je pravičen in mogočen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 18, 'Sme se li reči kralju: Belijal! plemenitnikom: Brezbožniki!?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 19, 'Koliko manj Njemu, ki se ne ozira na veljavo knezov in bogatina ne ceni više nego siromaka! Kajti vsi so rok Njegovih delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 20, 'V trenotku umirajo, kar sredi noči se pretrese ljudstvo in premine, in mogočne odpravljajo brez roke človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 21, 'Kajti oči Njegove so obrnjene na poti človekove in vidi vse korake njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 22, 'Ni teme, ni smrtne sence, da bi se v njej skrili, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 23, 'Ker ni Mu treba dolgo opazovati človeka, da bi prišel pred Boga mogočnega na sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 24, 'On pokončava mogočneže brez preiskovanja in stavi druge na njih mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 25, 'Tako pozna njih dejanja, in podere jih po noči, da so strti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 26, 'Tepe jih kakor hudodelnike na očitnem mestu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 27, 'zato ker so vstran stopili, ne hoteč hoditi za Njim, in se niso menili za nobenega potov Njegovih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 28, 'in so storili, da je k Njemu doletelo vpitje ubožcev, da je slišal trpinov krik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 29, 'Ko On dodeli mir, kdo obsodi? in skriva li obličje svoje, kdo Ga more videti? Bodisi narod ali poedinec, vse enako vodi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 30, 'da ne bi vladal človek bogapozabni, da nihče ne bo v zanko ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 31, 'Kajti rekel li je Job Bogu mogočnemu: „Trpim kazen, ne bom več napačno delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 32, 'Česar ne vidim, pokaži mi ti; ako sem krivico storil, ne storim je več“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 33, 'Mar naj povrača po tvoji misli? Saj si zavrgel plačilo Njegovo; zato moraš voliti ti, in ne jaz. Govóri torej, kar veš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 34, 'Možje razumni mi poreko in moder mož, ki me čuje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 35, 'Job ne govori s spoznanjem in besede njegove so brez razsodnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 36, 'Ah, da bi bil Job zopet in zopet izkušan zaradi svojih odgovorov po načinu krivičnikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 34, 37, 'Zakaj grehu svojemu še prideva prestopek, ploska med nami zasmehljivo z rokami in množi besede zoper Boga mogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 1, 'Še spregovori Elihu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 2, 'Meniš li, da je to prav? Rekel si: Pravičnost moja je večja nego Boga mogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 3, 'Kajti vprašuješ, kaj hasni tebi? „Kaj pridobim več, nego ko bi grešil?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 4, 'Jaz ti odgovorim besede in tvojim tovarišem s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 5, 'Ozri se proti nebu in glej in ogleduj nebeški obok – višji je nego ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 6, 'Če grešiš, kaj Mu škodiš? in če se množe prestopki tvoji, kaj Mu prizadeneš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 7, 'Če si pravičen, kaj Mu daješ? ali kaj prejemlje iz roke tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 8, 'Možu, kakor si sam, more škoditi tvoja brezbožnost in sinu človeškemu koristiti tvoja pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 9, 'Zaradi mnogega nasilstva vpijejo, kriče za pomoč zaradi rame mogočnežev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 10, 'A nihče ne pravi: Kje je Bog, Stvarnik moj, ki daje hvalospeve po noči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 11, 'ki nas bolj poučuje nego živali zemeljske in nam več modrosti daje nego pticam nebeškim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 12, 'Ondi vpijejo zaradi napuha hudobnih, a On ne odgovarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 13, 'Samo praznega vpitja ne sliši Bog silni in Vsegamogočni se nanje ne ozira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 14, 'Če praviš tudi, da Ga ne vidiš – pravda tvoja je pred Njim, Ga le čakaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 15, 'In sedaj, ker še ni kaznoval srd njegov, ne pozna li dobro drzovitosti tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 35, 16, 'Zatorej brezuspešno odpira Job usta svoja, množi besede brez spoznanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 1, 'Še je Elihu nadaljeval, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 2, 'Počakaj še malo, in te poučim, kajti še imam besed za Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 3, 'Prinesem znanje svoje iz daljave in pripoznam pravičnost Stvarniku svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 4, 'Kajti zares, besede moje niso lažnive; popoln v spoznanju je, ki stoji pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 5, 'Glej, Bog je mogočen, vendar ne zaničuje nikogar; mogočen je v moči razuma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 6, 'Brezbožnih ne hrani v življenju, trpinom pa pridobiva pravico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 7, 'Ne odvrača oči svojih od pravičnih, ampak s kralji na prestolu jim da sedeti za vedno, da so povišani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 8, 'In ko so zvezani v sponah in ujeti v vezeh revščine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 9, 'tedaj jim oznani njih dejanje in njih prestopke, da so prevzetovali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 10, 'in jim odpre uho za svarilo in veli, naj se preobrnejo od krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 11, 'Ako poslušajo in se mu podvržejo, prežive dni svoje v blaginji in leta svoja v prijetnostih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 12, 'Ako pa ne poslušajo, lete v strelo in mrjo v nerazumu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 13, 'Kateri pa so bogapozabni v srcu, gojé jezo: ne kličejo za pomoč, kadar jih je zvezal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 14, 'Njih duša umrje v mladosti in njih življenje pogine med nečistosti prodanimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 15, 'A trpina otimlje v trpljenju njegovem in po stiski jim odpira uho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 16, 'Tudi tebe bi bil iz žrela stiske odpeljal v prostranost, kjer ni tesnobe, in kar se postavi na mizo tvojo, bi bilo polno tolščobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 17, 'Ali napolnjen si s sodbo brezbožnikovo: sodba in obsodba te zadeneta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 18, 'Zato glej, da te togota ne zapelje v zasmehovanje Boga, in obilost podkupnine naj te ne prekani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 19, 'Pomore ti li tvoje vpitje tja, kjer ni stiske, in vse napenjanje moči tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 20, 'Ne žéli si noči, v kateri bodo ljudstva iztrebljena z mesta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 21, 'Varuj se, ne obračaj se h krivici, kajti njo rajši voliš nego trpljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 22, 'Glej, Bog mogočni ravna vzvišeno v moči svoji; kdo je tak učitelj kakor On?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 23, 'Kdo Mu je predpisal pot Njegovo in kdo sme reči: Nepravo si storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 24, 'Pomisli, da ti je poveličevati delo Njegovo, katero opevajo ljudje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 25, 'Vsi ljudje je z veseljem gledajo, smrtnik je zagleda oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 26, 'Glej, Bog mogočni je prevzvišen za naše spoznanje, število let Njegovih je nedoumno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 27, 'Kajti On dviga gori kapljico vode; od sopare, ki jo napravlja, solzé kot dež,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 28, 'ki ga visoki oblaki izlivajo in kapljajo na človeka v obilosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 29, 'In ume li kdo razprostrtje oblakov, prasketanje šatora Njegovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 30, 'Glej, On razširja svetlobo svojo okoli sebe in s koreninami morja se ogrinja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 31, 'kajti s tem sodi narode, s tem daje jedi v izobilju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 32, 'Roke svoje odeva z bliskom in ga pošilja, da zadene protivnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 36, 33, 'Njegovo grmenje Ga naznanja, celo živina čuti, da prihaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 1, 'Da, ob tem mi srce trepeta in poskakuje s svojega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 2, 'Čujte, čujte glasu Njegovega hrum in šumljanje, ki prihaja iz ust Njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 3, 'Pod vsa nebesa ga pošilja in blisk svoj do robov zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 4, 'Za bliskom rjove grom; On grmi z veličastnim glasom svojim in ne zadržuje bliskov, ko se čuje glas Njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 5, 'Bog mogočni grmi čudovito z glasom svojim, velike dela reči, ki jih ne razumemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 6, 'Zakaj snegu veli: Padaj na zemljo! enako nalivu in silnim ploham svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 7, 'Vsakemu človeku zapečati roko, da bi vsi ljudje spoznali delo Njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 8, 'Tedaj gre zver v svoja skrivališča in ostaja v svojih brlogih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 9, 'Iz hrama na jugu prihaja vihar, od severa pa mraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 10, 'Po dihu Boga mogočnega se naredi mraz in široke vode se stisnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 11, 'Z množino mokrote obtežuje oblake, daleč razprostira oblake strelonosne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 12, 'Pod Njegovim vodstvom se zasukajo, da opravijo, karkoli jim zapove, nad površjem obseljene zemlje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 13, 'bodisi, da jim veli izprazniti se v šibo, če je treba zemlji Njegovi, ali v dokaz Njegove milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 14, 'Čuj to, Job, stoj in opazuj čudovita dela Boga mogočnega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 15, 'Veš li, kako Bog obtežava oblake svoje in veli sijati njih svetlobi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 16, 'Umeš li plavanje in valovanje oblakov, čudovita dela tistega, ki je popoln v znanju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 17, 'Ti, ki ti obleka postane gorka, kadar jug vleče po zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 18, 'moreš li ti kakor On razpeti nebeški obok, da trdno stoji kakor zlito zrcalo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 19, 'Poúči nas, kaj naj Mu rečemo? Mi ne moremo urediti besed zaradi tmine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 20, 'Ali naj se Mu oznani, da hočem govoriti? Kdo bo li želel, da bo uničen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 21, 'Sedaj sicer ne vidimo luči, ki na oblake svetlo sije, a veter potegne in jih očisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 22, 'Od severa prihaja zlat lesk – okoli Boga je strašna veličast;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 23, 'Vsemogočnega ne moremo doseči, prevzvišen je v moči; a v sodbi in v obili pravičnosti nikomur ne dela sile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 37, 24, 'Zato se ga boje ljudje; on se ne ozira na nikogar, kakorkoli je modrega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 1, 'Tedaj spregovori Gospod iz viharja in reče Jobu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 2, 'Kdo je ta, ki v mrak zavija Božje sklepe z besedami brez spoznanja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 3, 'Opaši, pravim, kakor mož ledja svoja! jaz te bom vprašal, in ti me pouči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 4, 'Kje si bil, ko sem postavljal temelje zemlji? Povej, če kaj imaš razuma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 5, 'Kdo je določil mero njeno, če menda veš? ali kdo je čeznjo potegnil merno vrvico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 6, 'V kaj so vtaknjeni podstavni stebri njeni? ali kdo je položil njen vogelni kamen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 7, 'ko so pele vkup jutranje zvezde in vsi sinovi Božji radostno ukali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 8, 'In kdo je zaprl morje z zatvornicami, ko je ven pridrlo kakor iz materinega telesa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 9, 'ko sem mu naredil oblake za oblačilo in megleno tmino za plenice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 10, 'in sem mu določil stalno mejo in postavil zapahe in vrata');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 11, 'in velel: Dotod pojdeš in nikar naprej, in tu bodi mejnik kljubovalnim valovom tvojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 12, 'Ali si kdaj, odkar živiš, ukazal jutru se svitati, si li odkazal jutranji zarji mesto njeno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 13, 'veleč, naj zgrabi robove zemlje in ž nje otrese brezbožnike?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 14, 'Kakor pečatna glina se premenjuje zemlja in vse na njej se kaže kakor v oblačilu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 15, 'a brezbožnim se jemlje njih luč, in povzdignjena rama bo strta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 16, 'Ali si stopil v studence morja, si li prehodil dno globočine?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 17, 'Odprla so se ti vrata smrti in videl si vrata smrtne sence?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 18, 'Si li prav pregledal širjavo zemlje? Povej, če vse to veš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 19, 'Katera je pot do bivališča luči in kje je temi rodni kraj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 20, 'da bi ju pripeljal do njiju mej in da bi znal steze k njiju hiši?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 21, 'Pač to veš? saj si bil takrat rojen in dni tvojih število je veliko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 22, 'Si li dospel do skladišč snega in videl zaloge toče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 23, 'ki sem jih prihranil za čas nadloge, za dan boja in vojske?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 24, 'Kateri je pot, ki se na njem svetloba delí, vzhodni veter se razširja nad zemljo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 25, 'Kdo je razklal v oblakih lijaku tok in odpira pot blisku in grmenju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 26, 'da bi deževalo na zemljo brez ljudi, na puščavo, kjer ni človeka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 27, 'da se nasiti pušča in puščava in poganja zelena trava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 28, 'Ima li dež očeta in kdo plodi rosne kapljice?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 29, 'Iz čigavega telesa prihaja led in kdo rodi slano nebeško?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 30, 'Vode se zgoščujejo, da so kakor kamen, in gladina globočine se stakne vkup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 31, 'Moreš li zvezati zveze gostosevcev ali razdreti spojine rimščic?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 32, 'Storiš li, da se prikažejo znamenja zverokroga o svojem času, moreš li voditi medveda ž njegovimi mladiči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 33, 'Poznaš li postave neba, ali pa urejaš vlado njegovo nad zemljo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 34, 'Moreš li povzdigniti glas svoj do oblakov, da te množina vode pokrije?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 35, 'Moreš li bliske izpuščati, da švigajo, da ti reko: Tu smo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 36, 'Kdo je del v notranjščino modrost, ali kdo je dal duhu razum?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 37, 'Kdo šteje najvišje oblake z modrostjo in kdo izliva nebeške mehove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 38, 'ko se strdi prah, da je kakor ulitina, in se grude prilepijo druga drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 39, 'Mar levinji loviš plen in tešiš mladih levov glad,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 40, 'ko čepe v brlogih svojih, v goščavi na preži sede?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 38, 41, 'Kdo pripravlja vranu hrano njegovo, ko mladiči njegovi kriče k Bogu mogočnemu, letajo semtertja, ker nimajo živeža?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 1, 'Veš li za čas, kdaj rode divje koze v skalah, ali si opazoval, kdaj so košute v porodnih bolečinah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 2, 'Si li preštel njih mesece, katere jim je dopolniti, in veš li čas, kdaj rode?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 3, 'kako se zvijajo, mlade svoje izpuščajo, bolečin se oproščajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 4, 'Njih mladiči se ojačujejo, rastó pod milim nebom, jih zapuste in se k njim več ne povrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 5, 'Kdo je pustil divjega osla v prostost in vezi njegove kdo je razklenil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 6, 'ki sem mu jaz naredil puščavo v hišo in solnato puščo za prebivališče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 7, 'Njemu je v smeh mestni hrup, za krik gonjačev se ne meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 8, 'Gleda po gorah, kod je kaj paše, in išče povsod zelenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 9, 'Ali bo hotel divji bivol služiti tebi, bo li prenočeval pri jaslih tvojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 10, 'Ga li moreš v jarem vkleniti, da bi delal brazde, ali bo za teboj vlačil brano po dolini?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 11, 'Boš li mu zaupal, ker je velika moč njegova, in prepustiš mu li delo svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 12, 'Moreš se li zanesti nanj, da spravi žetev tvojo in zbere žito na gumnu tvojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 13, 'Veselo fofota nojica s perutjo svojo: a je li je njeno perutje in perje kakor štorkljino?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 14, 'Kajti jajca svoja pušča na zemlji in jih ogreva v prahu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 15, 'a zabi, da jih utegne noga poteptati in zverina poljska streti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 16, 'Trdo ravna s svojimi mladiči, kakor da niso njeni, nič je ne skrbi, da se je trudila zaman.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 17, 'Kajti Bog ji je prikratil modrost in razumnosti ji ni podelil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 18, 'Kadar se vzdigne, da leti, zasmehuje konja in jezdeca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 19, 'Si li dal konju moč njegovo in mu vrat ogrnil z vihrajočo grivo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 20, 'Naredil si, da skače kakor kobilica? Rezgetanje njegovo je krasno in strašno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 21, 'Grebe tla s kopiti, veseli se moči svoje, dirja oborožencem naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 22, 'Posmehuje se bojazni in se ne ustraši, in meču se ne umakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 23, 'Nad njim zvenči strelni tulec, bliska se kopje in sulica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 24, 'Silovito jezno dirja naprej in ne da se udržati, ko se zglasi trobenta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 25, 'Kadar zadoni tromba, kliče: huj! in oddaleč že čuje boj, grmeči glas poveljnikov in bojni krik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 26, 'Tvoj li razum napravlja, da se jastreb dviga, razpenja peruti proti poldnevu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 27, 'In zleti li orel visoko na tvoje povelje in postavi v višavi gnezdo svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 28, 'V skalah prebiva in gnezdi po pečinah in planinskih vrheh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 29, 'Odondod preži na živež, v daljavo gledajo oči njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 39, 30, 'in mladiči njegovi srebajo kri, in kjer je mrtvo truplo, je tudi on.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 1, 'In Gospod odgovori Jobu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 2, 'Pravdal se li bo grajač z Vsemogočnim? Kdor svari Boga, odgovóri na to!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 3, 'In Job odgovori Gospodu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 4, 'Glej, premajhen sem, kaj naj odgovorim? Roko denem na usta svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 5, 'Enkrat sem govoril, pa nočem izpregovoriti več, da, dvakrat, a ne bom zopet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 6, 'Tedaj odgovori Gospod Jobu iz viharja in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 7, 'Opaši, pravim, kakor mož ledja svoja; jaz te bom vprašal, in ti me pouči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 8, 'Hočeš li celó ovreči mojo pravico, mene li obsoditi, da bodeš ti pravičen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 9, 'Ali pa imaš ramo kakor Bog mogočni in moreš grmeti z glasom kakor on?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 10, 'Odeni se torej z močjo in visokostjo in obleci diko in veličastvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 11, 'Izlij reke jeze svoje, in poglej vsakega ošabneža in ga ponižaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 12, 'Poglej vsakega ošabneža in ga potlači, in pogazi brezbožnike na njih mestu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 13, 'Skrij jih v prah vse vkup, njih obličja zakleni v skritost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 14, 'Potem bom tudi jaz te hvalil, da te more rešiti desnica tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 15, 'Glej vendar behemota, ki sem ga storil kakor tebe: travo muli kakor vol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 16, 'Glej, pravim, moč svojo ima v ledjih in silo svojo v kitah podtrebušnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 17, 'Pregiblje rep kakor cedro, kite na bedru so mu gosto spletene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 18, 'Kosti njegove so kakor piščali brončene, rebra njegova kakor palice železne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 19, 'On je prvina tvornosti Boga mogočnega; On, ki ga je naredil, mu je oskrbel meč njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 20, 'Kajti krmo mu prinašajo gore, koder se igrajo vse divje zveri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 21, 'Pod lotosovo drevje leže počivat, v skrivališča trstja in močvirja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 22, 'lotosovo drevje ga pokriva s senco svojo, vrbje ob potoku ga obdaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 23, 'Glej, reka močno narašča – ne zbeži plašno, dobre volje je, če pridere Jordan do žrela njegovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 40, 24, 'Ulove ga njemu pred očmi, prevrta mu li kdo nas z lovilnimi vrvmi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 1, 'Moreš li leviatana potegniti iz reke s trnkom, stisneš mu li z vrvjo jezik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 2, 'Moreš mu li potegniti ločkasto vrvco skozi nos in čeljust prebosti z obodcem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 3, 'Bo te li veliko prosil ali sladke besede ti govoril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 4, 'Sklene li s teboj zavezo, da ga sprejmeš za hlapca za vekomaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 5, 'Se li boš z njim igral kakor s ptičkom in ga privezal k deklam svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 6, 'Ali ga bodo prodajali tovariši ribičev, ga razdelili med trgovce?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 7, 'Moreš mu li kožo napolniti s sulicami in glavo njegovo z ostvami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 8, 'Položi le roko nanj – a pomni boj, ne boš tega storil v drugič!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 9, 'Glej, prazno je upanje, da ga dobiš; saj že njega pogled vrže človeka na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 10, 'Ni ga človeka toliko drznega, da bi ga dražil. – In kdo je, ki bi se smel postaviti pred moje obličje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 11, 'Kdo mi je dal kaj poprej, da bi mu moral povrniti? Kar je pod vesoljnim nebom, je moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 12, 'Ne bom molčal o udih njegovih, ne o veliki moči in lepoti rasti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 13, 'Kdo mu odgrne povrhnje oklopje in kdo se osmeli seči mu med dvojno ozobje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 14, 'Kdo odpre vrata njegovega obličja? Okoli zob njegovih je groza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 15, 'Ponos njegov so močni ščiti, ščit s ščitom sklenjen s trdnim pečatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 16, 'Drug z drugim se tesno skladajo, da še sapica ne pihne skozi nje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 17, 'drug na drugem vise trdno, med sabo staknjeni se ne ločijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 18, 'Kihanje njegovo zažiga svetlobo, oči njegove so kakor trepalnice jutranje zarje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 19, 'Iz ust mu pohajajo goreče bakle, ognjene iskre se sipljejo iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 20, 'Iz nozdrvi se mu vali dim kakor iz lonca, kipečega nad gorečim dračjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 21, 'Sapa njegova razžiga žerjavico, iz ust pa mu šviga plamen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 22, 'Na vratu njegovem prebiva moč in strah skače pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 23, 'Podgrlje na telesu mu visi trdno, tesno se ga oklepa, se ne gane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 24, 'Srce njegovo je trdo kakor kamen, trdo kakor spodnji kamen mlinski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 25, 'Kadar se vzdigne, se boje močni, od osupnosti ne dosežejo namere svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 26, 'Če ga kdo zadene z mečem, ne obtiči v njem, tudi ne kopje, ne strela, ne ostve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 27, 'Za železo se toliko meni kakor za slamo in za bron kakor za gnil les.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 28, 'Nobena pšica ga ne požene v beg, kameni s prače so mu kakor pleve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 29, 'kiji kakor bilke in svrčeči sulici se smeje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 30, 'Spodnja stran njegova so ostre čepinje; kakor mlatilni voz gre čez blato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 31, 'Napravlja, da vre v globočini kakor v loncu, da je morje kakor kotel z vročim mazilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 32, 'Svetlo stezo za sabo dela, da se kaže kakor glava osivela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 33, 'Na zemlji mu ga ni para, njemu, ki je ustvarjen, da bodi brez strahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 41, 34, 'Vse visoko smelo gleda, kralj je vsem zverem ponosnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 1, 'Nato odgovori Job Gospodu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 2, 'Spoznavam, da moreš vse in da ni mogoče zabraniti nobene namere tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 3, 'Kdo je, ki zagrinja Božje sklepe brez spoznanja? Zato sem govoril, česar nisem razumel, kar je prečudovito zame, česar nisem spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 4, 'Čuj, prosim, in bom govoril, jaz te bom vprašal, in ti me pouči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 5, 'Le s sluhom ušesa sem slišal o tebi, a sedaj te oko moje vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 6, 'Zato zaničujem sebe in kesam se v prahu in pepelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 7, 'In zgodi se, ko je bil Gospod govoril te besede Jobu, da veli Gospod Elifazu Temančanu: Srd moj je razvnet zoper tebe in zoper oba prijatelja tvoja, ker niste govorili o meni pravega kakor hlapec moj Job.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 8, 'In sedaj si vzemite sedem juncev in sedem ovnov in pojdite k hlapcu mojemu Jobu in darujte žgalno daritev za sebe. Job pa, hlapec moj, naj prosi za vas, zakaj nanj se milostno ozrem, da ne bom z vami ravnal po nespameti vaši, ker niste govorili o meni pravega kakor hlapec moj Job.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 9, 'Tedaj so šli Elifaz Temančan in Bildad Šuhec in Zofar Naamatec in so storili, kakor jim je velel Gospod; in Gospod se je milostno ozrl na Joba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 10, 'In Gospod je obrnil ujetništvo Jobovo, ko je prosil za prijatelje svoje; in Gospod je dvojno pomnožil vse, kar je prej imel Job.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 11, 'Tedaj so prišli k njemu vsi bratje njegovi in vse sestre njegove in vsi prejšnji znanci njegovi in so jedli ž njim kruh v hiši njegovi ter ga milovali in tolažili zaradi vse nesreče, ki jo je bil nadenj dopustil Gospod, in vsak mu je dal zlatnik in zlat uhan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 12, 'In Gospod je blagoslovil poslednje življenje Jobovo bolj nego prejšnje: dobil je štirinajst tisoč glav drobnice in šest tisoč velblodov in tisoč jarmov volov in tisoč oslic.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 13, 'Dobil je tudi sedem sinov in tri hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 14, 'In prvo je imenoval Golobico, drugo pa Dišavko in tretjo Lepotico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 15, 'In takih lepih devojk, kakor so bile hčere Jobove, ni bilo najti po vsej deželi. In njih oče jim je dal dediščino sredi njih bratov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 16, 'Job pa je živel potem sto in štirideset let in videl je otroke svoje in svojih otrok otroke, štiri pokolenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (18, 42, 17, 'In Job je umrl, star in dni svojih sit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 1, 'Blagor možu, ki ne hodi po svetu brezbožnih in ne stopa na pot grešnikov ter ne sedeva v družbi zasmehovalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 2, 'Temuč veselje njegovo je v postavi Gospodovi in postavo njegovo premišljuje noč in dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 3, 'Je namreč kakor drevo, zasajeno ob potokih vodá, ki rodi svoj sad ob svojem času in ki mu listje ne uvene, in karkoli počenja, se mu posreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 4, 'Ne tako brezbožni, ampak kakor pleve so, ki jih veter raznaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 5, 'Zatorej ne obstoje brezbožni v sodbi, ne grešniki v zboru pravičnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 1, 6, 'Kajti Gospod pozna pravičnih pot, pot pa brezbožnih izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 1, 'Zakaj hrumé narodi in ljudstva si izmišljajo prazne reči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 2, 'Vzdigujejo se kralji zemlje in knezi se skupaj posvetujejo zoper Gospoda in zoper Maziljenca njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 3, 'govoreč: Raztrgajmo njih vezi in s sebe vrzimo njih spone!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 4, 'On, ki stoluje v nebesih, se smeje, zasmehuje jih Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 5, 'Tedaj jih ogovori v jezi svoji in v srdu svojem jih prestraši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 6, 'Jaz pa sem vendar postavil kralja svojega na Sionu, na gori svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 7, 'Oznanim naj vam sklep: Gospod mi je rekel: Sin moj si ti, jaz sem te danes rodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 8, 'Prosi me, in narode ti dam v dediščino in kraje zemlje v posest tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 9, 'Zdrobiš jih s palico železno, kakor prsteno posodo jih razbiješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 10, 'Zdaj torej, o kralji, bodite pametni, dajte se poučiti, o zemlje sodniki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 11, 'V svetem strahu služite Gospodu in radujte se s trepetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 2, 12, 'Poljubite Sina, da se ne razsrdi in ne poginete na potu, ker skoraj se razvname jeza njegova. Blagor vsem, ki imajo v njem zavetje svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 1, '{Psalm Davidov, ko je bežal pred Absalomom, sinom svojim.} Gospod, koliko je nasprotnikov mojih! Mnogo jih je, ki vstajajo proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 2, 'Mnogo jih je, ki govore o duši moji: Ni zanj rešitve v Bogu nobene. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 3, 'Ti pa, o Gospod, ščit si meni, slava moja, in ti povzdiguješ glavo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 4, 'Z glasom svojim vpijem h Gospodu, in mi odgovarja z gore svetosti svoje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 5, 'Legel sem in spal, in zbudil sem se, ker Gospod me podpira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 6, 'Ne bom se bal ljudstva miriad, ki so se okrog razpostavile proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 7, 'Vstani, o Gospod, reši me, moj Bog! ker ti si udaril vse sovražnike moje po čeljustih, brezbožnikom si zdrobil zobe ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 3, 8, 'Gospodova je rešitev. Na ljudstvo tvoje pridi blagoslov tvoj! (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 1, '{Načelniku godbe; z godbo na strune.Psalm Davidov.} Ko kličem, odgovori mi, o Bog pravičnosti moje, ki si mi v stiski napravil prostora; milosten mi bodi in poslušaj molitev mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 2, 'Sinovi odličnih mož, doklej bode slava moja v nečast? Boste li ljubili ničemurnost in iskali laži? (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 3, 'Spoznajte vendar, da si je Gospod posebe odbral pobožnega; Gospod čuje, ko kličem k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 4, 'Prestrašite se in ne grešite; razgovarjajte se v srcu svojem na ležiščih svojih in pomirite se! (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 5, 'Darujte daritve pravičnosti in upajte v Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 6, 'Mnogi govore: „O da bi uživali dobro!“Dvigni nad nas svetlobo obličja svojega, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 7, 'Ti si mi dal veselja v srce, več nego ga imajo oni, ko se jim žita in vina obrodi na prebitek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 4, 8, 'V miru ležem in zdajci zaspim, zakaj ti, Gospod, mi v samoti daješ, da prebivam brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 1, '{Načelniku godbe; s piščalmi. Psalm Davidov.} Besede moje čuj, Gospod, ozri se na premišljevanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 2, 'Poslušaj vpitja mojega glas, Kralj moj in Bog moj, kajti k tebi molim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 3, 'Gospod, zgodaj boš slišal glas moj, zgodaj položim prošnjo pred teboj in bom čakal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 4, 'Ker ti nisi Bog mogočni, ki bi mu bila všeč brezbožnost, hudobnež ne sme bivati pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 5, 'Samohvalniki ne zdrže pred očmi tvojimi, sovražiš vse, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 6, 'Pogubiš nje, ki govore laž; moža krvoželjnega in zvijačnega mrzi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 7, 'Jaz pa vnidem, obdan z obilostjo milosti tvoje, v hišo tvojo, priklonim se proti hramu svetosti tvoje v svetem strahu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 8, 'Gospod, vodi me v pravičnosti svoji zavoljo zalezovalcev mojih, ravno stóri pot svojo pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 9, 'Zakaj v njih ustih ni nič resničnega, njih notranjost je poguba, grob odprt njih grlo, z jezikom svojim se dobrikajo zvijačno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 10, 'Pokori jih, o Bog, padejo naj po naklepih svojih; pahni jih doli v obilosti njih pregreh, ker se upirajo zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 11, 'In veselili se bodo vsi, ki pribegajo k tebi, in na veke bodo prepevali, ker si jim bramba, in radovali se bodo v tebi ljubitelji tvojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 5, 12, 'Zakaj ti blagoslavljaš pravičnega, ti, Gospod, delaš, da ga milost krije kakor ščit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 1, '{Načelniku godbe; s strunami, za globoke glasove. Psalm Davidov.} Gospod, v jezi svoji me ne karaj, niti v srdu svojem me ne kaznuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 2, 'Milosten mi bodi, Gospod, ker opešal sem, ozdravi me, Gospod, ker preplašene so kosti moje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 3, 'in duša moja je preplašena silno – ti pa, o Gospod, doklej?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 4, 'Povrni se, Gospod, otmi dušo mojo, reši me zaradi milosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 5, 'Kajti spomina nate v smrti ni, v grobu kdo bi te slavil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 6, 'Utrujen sem v zdihovanju svojem, vsako noč močim s solzami posteljo svojo, plava mi ležišče v solzah preobilih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 7, 'Otemnelo je od žalovanja oko moje, postaralo se je zbok zatiralcev mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 8, 'Poberite se od mene vsi, ki delate krivico, ker Gospod je slišal mojega joka glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 9, 'Slišal je Gospod prošnjo mojo, Gospod sprejme molitev mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 6, 10, 'Osramočeni bodo in silno se preplašijo vsi sovražniki moji, odriniti morajo v sramoti naglo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 1, '{Pesem Davidova, ki jo je pel Gospodu z ozirom na besede Kusa Benjaminca.} O Gospod, Bog moj, v tebi imam zavetje, reši me vseh preganjalcev mojih in oprosti me,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 2, 'da ne zgrabi sovražnik kakor lev duše moje in je ne raztrga, ko ni pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 3, 'O Gospod, Bog moj, ako sem storil tisto, ako je krivica na rokah mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 4, 'ako sem storil hudo njemu, ki je v miru živel z menoj (ko sem vendar rad pomagal njemu, ki me je zatiral po krivem):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 5, 'preganja naj sovražnik dušo mojo in jo dohiti ter potepta na tla življenje moje in v prah potlači slavo mojo. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 6, 'Vstani, Gospod, v jezi svoji, vzdigni se proti razkačenosti zatiralcev mojih in prebudi se meni na pomoč; saj si sodbo zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 7, 'Tako naj te obda zbor narodov in nad njim se vrni zopet v višavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 8, 'Gospod bo sodil ljudstva. Sodi me, Gospod, po pravičnosti moji in po nedolžnosti, ki je na meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 9, 'Preneha naj, prosim, zloba brezbožnikov, pravičnega pa utrdi; saj preiskuješ srca in obisti, Bog pravični.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 10, 'Ščit moj je Bog, rešitelj tistih, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 11, 'Bog je pravičen sodnik, Bog mogočni se srdi nad brezbožnikom vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 12, 'Ako se ne izpreobrne, nabrusi svoj meč, lok svoj je že napel in ga pripravil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 13, 'pomeril je vanj smrtno orožje, ognjene je naredil pšice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 14, 'Glej, brezbožnik rodi krivico; spočel je nadlogo, rodil bo laž.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 15, 'Jamo je kopal in jo poglobil, a pade vanjo sam, ki jo je naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 16, 'Povrne se nadloga njegova na glavo njegovo in nad teme njegovo pride njegovo nasilstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 7, 17, 'Hvalil bom Gospoda po pravičnosti njegovi in psalme prepeval imenu Gospoda Najvišjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 1, '{Načelniku godbe; na gitit. Psalm Davidov.} O Jehova, Gospod naš, kako veličastno je ime tvoje na vsej zemlji, ki si odel s slavo svojo nebesa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 2, 'Iz ust otrok in dojencev si ustanovil sebi hvalo zavoljo nasprotnikov svojih, da ukrotiš neprijatelja in maščevalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 3, 'Ko ogledujem nebesa tvoja, prstov tvojih delo, mesec in zvezde, ki si jih postavil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 4, 'govorim: Kaj je človek, da se ga spominjaš, ali sin človekov, da ga obiskuješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 5, 'Le malo si ga storil nižjega nego angele, a venčal si ga s slavo in veličastvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 6, 'Postavil si ga za vladarja delom svojih rok, vse si mu podložil pod noge:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 7, 'drobnico in goved, kolikor je je, in tudi poljske živali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 8, 'ptice pod nebom in ribe v morju, karkoli se izprehaja po morskih stezah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 8, 9, 'Jehova, Gospod naš, kako veličastno je ime tvoje na vsej zemlji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 1, '{Načelniku godbe; na ‚Smrt sinu‘. Psalm Davidov.} Hvalil te bom, Gospod, iz vsega srca svojega, pripovedoval vsa čudovita dela tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 2, 'Veselil se bom in radoval v tebi, psalme bom prepeval tvojemu imenu, Najvišji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 3, 'Ker sovražniki moji se umikajo, padajo in ginejo pred obličjem tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 4, 'Zakaj ti si vodil sodbo mojo in pravdo mojo, sedel si na prestolu kot pravičen sodnik;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 5, 'pokaral si narode, pogubil krivičnika, njih ime si izbrisal na večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 6, 'Sovražnikov je konec, razdejani so na veke, njih mesta si uničil, da, njih spomin je izginil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 7, 'A Gospod stoluje na veke, pripravil je za sodbo prestol svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 8, 'On bo sodil vesoljni svet v pravičnosti, pravde razsojal narodom po pravici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 9, 'Gospod bode tudi grad na višini siromaku, grad na višini ob časih stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 10, 'In bodo upali v te, kateri poznajo ime tvoje, ker ne zapustiš njih, ki te iščejo, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 11, 'Hvalnice pojte Gospodu, ki prebiva na Sionu, oznanjujte ljudstvom dela njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 12, 'Kajti on, ki maščuje kri v moritvi prelito, se jih je spomnil, ni pozabil vpitja trpinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 13, 'Usmili se me, Gospod, ozri se v ponižanje moje od sovražnikov mojih, da me vzdigneš izpred smrtnih vrat:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 14, 'da oznanjam vso slavo tvojo, med vrati hčere sionske se radujem v zveličanju tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 15, 'Pogreznili so se narodi v jamo, ki so jo sami napravili; v mrežo, ki so jo skrito nastavili, se je ujela njih noga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 16, 'Pokazal se je Gospod po sodbi, katero je storil: v rok njegovih delo je zapletel brezbožnika. (Pomisleka vredno! Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 17, 'Brezbožniki se morajo obrniti v pekel, vsi narodi, ki so pozabili Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 18, 'Kajti siromak ne bode na veke pozabljen, ubožcev upanje ne pogine za večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 19, 'Vstani, o Gospod, da se ne šopiri človek umrljivi, sojeni naj bodo narodi pred obličjem tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 9, 20, 'V strah jih primi, Gospod, spoznajo naj narodi, da so umrjoči. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 1, 'Zakaj stojiš oddaleč, o Gospod? Zakaj se skrivaš ob časih stiske?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 2, 'Prevzetnost brezbožnika hudo straši ubožca. Ujamejo se naj v naklepih, katere izmišljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 3, 'Kajti brezbožnik se hvali z željami duše svoje in lakomnik se odreka Gospoda in ga zaničuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 4, 'Brezbožnik v napuhu obraza svojega govori: Saj ne bo kaznoval, ni Boga. To so vse misli njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 5, 'Varna so pota njegova v vsakem času; previsoko so pogledu njegovemu sodbe tvoje; na svoje nasprotnike piha prezirljivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 6, 'V srcu svojem govori: Ne ganem se, od roda do roda bodem brez nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 7, 'Kletve polna so usta njegova in zvijač in zatiranja; pod jezikom njegovim je nadloga in krivica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 8, 'Poseda na preži po vaseh, v zakotju ubija nedolžnega, oči njegove prežé na onemoglega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 9, 'V skrivališču preži kakor lev v svojem brlogu, preži, da zgrabi siromaka; že ga prijema ter vleče vstran v mreži svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 10, 'Sključi se, potuhne se, in onemogli padajo v krepke kremplje njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 11, 'V srcu svojem govori: Pozabil je Bog mogočni, obličje svoje skriva, nikoli ne bo videl tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 12, 'Vstani, o Gospod! Bog mogočni, dvigni roko svojo, ne pozabi ubogih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 13, 'Zakaj sme brezbožnik zaničevati Boga in v srcu svojem govoriti, da ne boš kaznoval?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 14, 'Videl si to; zakaj ti gledaš nadlogo in gorje, da povrneš s svojo roko; brambi tvoji se izroča nesrečni, siroti si ti pomočnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 15, 'Zdróbi roko brezbožniku in hudobneža krivico kaznuj, dokler je ne najdeš več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 16, 'Gospod je Kralj vedno in vekomaj, poginili so pogani z zemlje njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 17, 'Hrepenenje krotkih si uslišal, Gospod: potolažiš jim srce, nagneš k njim svoje uho,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 10, 18, 'da maščuje siroto in stiskanega, da ju ne straši več človek, ki je iz zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 1, '{Načelniku godbe. Psalm Davidov.} Gospod mi je zavetje – kako da govorite duši moji: Léti na vašo goro, ptica!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 2, 'Kajti glej, krivičniki natezajo lok, pšico svojo pokladajo na tetivo, da streljajo v temi na njé, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 3, 'Ko se celo stebri podirajo, kaj naj počne pravični?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 4, 'Gospod je v templju svetosti svoje, Gospod, čigar prestol je v nebesih; njegove oči vidijo, njegove trepalnice preiskujejo sinove človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 5, 'Gospod preiskuje pravičnika, brezbožnika pa in siloljubnega sovraži duša njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 6, 'Dežil bo na brezbožne zanke, ogenj in žveplo in pekoč veter bode njih čaše delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 11, 7, 'Kajti pravičen je Gospod in ljubi pravičnost; kdor je pošten, bo gledal obličje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 1, '{Načelniku godbe; za globoke glasove. Psalm Davidov.} Pomagaj, Gospod, ker preminil je dobrodelnik, ker izginila so zvesta srca izmed sinov človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 2, 'Lažnivost govoré drug z drugim, s priliznjenimi ustnami in z dvojnim srcem govoré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 3, 'Gospod pokonča vse priliznjene ustne in jezik, ki bahavo govori,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 4, 'nje, ki govore: Našega jezika moč obvelja, ustne naše so v naši oblasti; kdo bi nam bil gospodar?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 5, 'Zavoljo zatiranja ubožcev, zavoljo zdihovanja revežev vstanem sedaj, govori Gospod; na varno postavim njega, ki po tem koprni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 6, 'Besede Gospodove so čiste besede, kakor srebro, očiščeno v topilni peči na zemlji, osnaženo sedemkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 7, 'Ti, Gospod, ohraniš uboge, branil jih boš tega rodu na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 12, 8, 'Brezbožni šopirno hodijo vseokrog, ko se povzdiguje malopridnost med človeškimi otroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 1, '{Načelniku godbe. Psalm Davidov.} Doklej, o Gospod? Boš li zabil me večno? Doklej boš skrival obličje svoje pred menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 2, 'Doklej naj gojim skrbi v duši svoji, žalost v srcu svojem vse dni? Doklej se bo vzpenjal sovražnik moj proti meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 3, 'Ozri se sem, odgovóri mi, Gospod, moj Bog, razsvetli oči moje, da ne zaspim na smrt;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 4, 'da ne poreče sovražnik moj: Premagal sem ga; da se ne bodo radovali nasprotniki moji, če bi omahnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 5, 'Jaz pa upam v milost tvojo; radovalo se bo srce moje v zveličanju tvojem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 13, 6, 'prepeval bom Gospodu, ker mi je storil dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 1, '{Načelniku godbe. Psalm Davidov.} Nespametnež govori v srcu svojem: Ni Boga. Izprijeni so, ostudno je, kar počenjajo, ni ga, ki bi delal dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 2, 'Gospod je pogledal iz nebes na sinove človeške, da bi videl, je li kateri razumen, je li kdo, ki išče Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 3, 'Vsi so odstopili, vsi skupaj so se pokazili; ni ga, ki bi delal dobro, enega samega ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 4, 'Nimajo li nič spoznanja vsi, ki delajo krivico? ki žro ljudstvo moje, kakor da jedo kruh, in Gospoda ne kličejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 5, 'Tu se preplašijo od groze, ker Bog je na strani pravičnemu rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 6, 'Sklep siromaka sramotite, seveda! ker Gospod je zavetje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 14, 7, 'O da bi prišlo s Siona zveličanje Izraelovo! Ko bo Gospod nazaj peljal iz sužnosti ljudstvo svoje, radoval se bo Jakob, veselil se Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 1, '{Psalm Davidov.} Gospod, kdo sme prebivati v šatoru tvojem, kdo stanovati na gori svetosti tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 2, 'Kdor živi brezmadežno in ravna pravično ter govori resnico iz srca svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 3, 'kdor ne obrekuje z jezikom svojim, ne dela hudega bližnjemu svojemu in ne obklada s sramoto soseda svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 4, 'v čigar očeh je zaničevan od Boga zavrženi, spoštuje pa nje, ki se bojé Gospoda; ko priseže, čeprav v škodo svojo, ne prevrača besede;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 15, 5, 'kdor ne lihvari z denarjem svojim in darila ne sprejme zoper nedolžnega. Kdor tako ravna, ne omahne nikdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 1, '{Zlata pesem Davidova.} Varuj me, Bog mogočni, ker v tebi iščem zavetja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 2, 'Gospodu govorim: Ti si mi Gospod, ni sreče zame zunaj tebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 3, 'in svetnikom, ki so na zemlji: To so slavni, v katerih je vse veselje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 4, 'Mnoge bodo bolečine tistih, ki hité za drugim bogom; daroval ne bom njih krvavih daritev, ne jemal njih imen na ustne svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 5, 'Gospod je delež posesti moje in mojega keliha; ti vzdržuješ odmerjeno mi dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 6, 'Merilne vrvi so mi padle v prekrasnih krajih, res, dobil sem prelepo dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 7, 'Slavil bom Gospoda, ki mi je dobro svetoval: tudi po noči me poučujejo obisti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 8, 'Predočujem si Gospoda neprestano; ker je na desnici moji, ne omahnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 9, 'Tega se veseli srce moje in raduje se slava moja, tudi meso moje bo počivalo brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 10, 'Ker ne zapustiš duše moje v državi smrti, ne daš, da vidi ljubljenec tvoj trohnobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 16, 11, 'Daš mi spoznati življenja stezo: najslajših radosti obilica je pred obličjem tvojim, polno milin v desnici tvoji vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 1, '{Molitev Davidova.} Čuj, o Gospod, pravičnost, poslušaj stokanje moje, uho nagni k molitvi moji, ki je brez ustnic zvijačnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 2, 'Od tvojega obličja naj pride sodba moja, ker oči tvoje gledajo, kar je pravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 3, 'Preiskal si srce moje, pregledal me po noči, z ognjem si me preizkusil, in nisi našel ničesar; kar mislim, ne prestopi mojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 4, 'Gledé na dejanja ljudi, po besedi ustnic tvojih sem se čuval potov siloviteža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 5, 'Vzdržal sem korake svoje na stezah tvojih, niso se spoteknile noge moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 6, 'Jaz kličem k tebi, ker me čuješ, Bog mogočni; nagni k meni uho svoje in poslušaj govor moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 7, 'Čudovito pokaži milost svojo, rešitelj tistih, ki pribegajo izpred sovražnih upornikov na desnico tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 8, 'Hrani me kakor zenico v očesu, v senci peruti svojih me skrivaj');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 9, 'pred brezbožniki, ki me napadajo, pred sovražniki duše moje, ki me oblegajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 10, 'Brezčutno srce svoje so zaprli, z usti svojimi govoré ošabno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 11, 'Pri vsakem koraku me že obstopajo, z očmi svojimi pazijo, da me pahnejo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 12, 'Podoben je sovražnik moj levu, ki želi raztrgati, mlademu levu, ki čepi v skrivališču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 13, 'Vstani, Gospod, stopi mu nasproti, zvrni ga na tla, reši dušo mojo brezbožnika z mečem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 14, 'Oprosti me ljudi z roko svojo, Gospod, ljudi tega sveta, katerih delež je v tem življenju, katerim polniš trebuh z zakladom svojim; sinov imajo dosita in preobilje svoje zapuščajo otrokom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 17, 15, 'Jaz pa bom v pravičnosti gledal obličje tvoje, sitil se bom, ko se zbudim, s podobo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 1, '{Načelniku godbe. Psalm Davida, hlapca Gospodovega, ki je govoril Gospodu te pesmi besede v dan, ko ga je bil rešil Gospod iz pesti vseh sovražnikov njegovih in iz roke Savlove; in rekel je:} Srčno te ljubim, o Gospod, moja moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 2, 'Gospod je skala moja in visoki grad moj in rešitelj moj, Bog mogočni moj, zavetje moje, kamor pribegam, ščit moj in rešenja mojega rog, visoka trdnjava moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 3, 'Gospoda kličem, ki je hvale vreden, in tako se rešujem sovražnikov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 4, 'Objele so me smrti vezi in hudourniki pogube so me prestrašili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 5, 'pekla vezi so me obdale, smrtne zanke so me zajele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 6, 'V stiski svoji sem klical Gospoda in k Bogu svojemu sem vpil; iz svetišča svojega je začul moj glas in vpitje moje pred njim je prišlo do ušes njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 7, 'Tu se je zgenila in stresla zemlja, tudi podstave gorá so se zmajale, gibale so se, ker se je srdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 8, 'Dim se je valil iz nosnic njegovih in ogenj požrešen iz ust njegovih, žerjavica goreča je prhala od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 9, 'Nagnil je nebo ter stopil doli, in oblačna temota mu je bila pod nogami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 10, 'In sedeč na kerubu, je letel in plaval na vetra perutih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 11, 'Temo si je napravil za ogrinjalo, za šator svoj okoli sebe, mrak vodá in roje oblakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 12, 'Iz svita pred njim je švigala skozi oblake njegove toča in žerjavica ognjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 13, 'Na nebesih je grmel Gospod in Najvišji je dal slišati svoj glas – toča in žerjavica ognjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 14, 'In izstrelil je pšice svoje in sovražnike razkropil, metal je strelo za strelo, in jih je izbegal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 15, 'In prikazale so se struge vodá, in odgrnile so se podstave vesoljne zemlje od svarjenja tvojega, Gospod, od sape jeze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 16, 'Iz višine je posegel in me prijel, potegnil me je iz mnogih vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 17, 'Rešil me je neprijatelja mojega močnega in sovražilcev mojih, krepkejših od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 18, 'Naskočili so me v dan nesreče moje, a Gospod mi je bil podpora,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 19, 'in me je izpeljal na plano, rešil me je, ker me je ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 20, 'Podelil mi je Gospod po pravičnosti moji, po čistosti mojih rok mi je povrnil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 21, 'kajti držal sem se potov Gospodovih ter se nisem zlobno odvrnil od Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 22, 'Zakaj vse sodbe njegove so pred mojimi očmi, in postav njegovih ne zavračam od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 23, 'In bil sem mu popolnoma vdan ter sem se pazil, da ne ravnam krivično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 24, 'Zato mi je povrnil Gospod po pravičnosti moji, po čistosti mojih rok pred njegovimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 25, 'Dobrotljivemu se izkazuješ dobrotljivega, popolnoma vdanemu se izkazuješ popolnega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 26, 'čistemu se kažeš čistega, ali popačenemu nasprotuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 27, 'Zakaj ti otimlješ ljudstvo ubogo, prevzetne oči pa ponižuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 28, 'Da, svetilo moje razsvetljuješ; Gospod, moj Bog, razjasnjuje moje tmine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 29, 'S teboj namreč prodiram skozi krdelo in z Bogom svojim preskakujem zid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 30, 'Tega Boga mogočnega pot je brezmadežna, govor Gospodov ves čist; ščit je vsem, ki pribegajo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 31, 'Ker kdo je Bog razen Gospoda? in kdo skala razen našega Boga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 32, 'Ta Bog mogočni, ki me opasuje z močjo in brezmadežno dela mojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 33, 'Dela, da so moje noge kakor jelenje, in me stavi na višino mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 34, 'Vadi za boj roke moje, da napnem z ramo svojo lok bronasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 35, 'Dal si mi tudi zveličanja svojega ščit, in desnica tvoja me je podpirala in ljubeznivost tvoja me je poveličala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 36, 'Razširil si prostor korakom mojim pod mano, in členki mojih nog niso omahovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 37, 'Zasledoval sem sovražnike svoje in jih dohitel, in nisem se vrnil, dokler jih nisem izničil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 38, 'Zdrobil sem jih tako, da ne morejo več vstati, padli so mi pod noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 39, 'Ker ti si me opasal z močjo za vojsko, upognil si podme nje, ki so se vzpenjali zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 40, 'In zapodil si v beg nasprotnike moje, sovražilce moje, da jih ugonobim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 41, 'Vpili so, a ni ga bilo, ki bi jih rešil, h Gospodu so vpili, a ni jim odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 42, 'Tu sem jih strl, da so kakor prah pred vetrom, kakor blato na ulicah sem jih poteptal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 43, 'Otel si me iz prepirov ljudstva in postavil narodom za glavo; ljudstvo, ki ga nisem poznal, mi je služilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 44, 'Le slišali so o meni, in so se mi pokorili, tujci so se mi vdajali z laskanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 45, 'Tujci so v strahu koprneli in pritrepetavali iz gradov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 46, 'Živ je Gospod; in slavljena bodi skala moja in naj se povišuje Bog rešenja mojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 47, 'Bog ta mogočni, ki mi daje maščevanje in spravlja ljudstva podme;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 48, 'ki me rešuje sovražnikov mojih; da, ti si me povzdignil nadnje, ki vstajajo zoper mene, možu silovitemu si me iztrgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 49, 'Zatorej te bom hvalil med narodi, Gospod, in psalme prepeval tvojemu imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 18, 50, 'On daje rešenje, veliko in obilo, kralju svojemu in izkazuje milost maziljencu svojemu, Davidu in semenu njegovemu na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 1, '{Načelniku godbe. Psalm Davidov.} Nebesa oznanjajo slavo Boga mogočnega in delo rok njegovih kaže oblok nebesni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 2, 'Dan kliče dnevu vest o njem in noč poroča noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 3, 'Ni govora, ne besed, a vendar umejo njih glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 4, 'Po vsej zemlji se razlega njih oznanilo, do kraja vesoljnega sveta njih govor; solncu pa je postavil šator na njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 5, 'In ono izhaja kakor ženin iz stanice svoje, raduje se kakor korenjak, da poteče svojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 6, 'Od kraja nebes je vzhod njegov in tek njegov do njih roba, in ničesar ni, kar bi se skrilo njegovemu žaru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 7, 'Postava Gospodova je popolna, oživlja dušo; pričevanje Gospodovo zanesljivo, modrost daje nevednemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 8, 'zapovedi Gospodove so prave, razveseljujejo srce; povelje Gospodovo čisto, razsvetljuje oči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 9, 'strah Gospodov je čist, vekomaj ostane; sodbe Gospodove zgolj resnica, pravične so vse;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 10, 'zaželjene bolj nego zlato, da, nego mnogo čistega zlata, in slajše nego med, nego samotok medeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 11, 'Služabnik tvoj prejema tudi opomine po njih; kdor jih hrani, plačilo ima veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 12, 'A zmote – kdo jih zaznava? I skritih me odveži pregreškov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 13, 'Tudi grehov iz prezaupnosti obvaruj služabnika svojega, da ne gospodujejo meni; tedaj bodem brez madeža in čist velike pregrehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 19, 14, 'Prijetne naj bodo ust mojih besede in srca mojega premišljevanje pred teboj, o Gospod, skala moja in odrešenik moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 1, '{Načelniku godbe. Psalm Davidov.} Usliši te naj Gospod v dan stiske; na višavo naj te postavi ime Boga Jakobovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 2, 'Pošlje naj ti pomoč iz svetišča in s Siona naj te podpira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 3, 'Pomni naj vse daritve tvoje in všečno naj sprejme žgalno daritev tvojo. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 4, 'Dá naj ti po srcu tvojem in izpolni naj vse namere tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 5, 'Veselo hočemo peti o rešenju tvojem in v imenu Boga našega dvignemo zastave. Gospod naj izpolni vse prošnje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 6, 'Sedaj vem, da Gospod pomaga maziljencu svojemu, mu odgovori iz nebes svetosti svoje po mogočnih rešilnih delih desnice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 7, 'Ti se zanašajo na vozove in oni na konje, mi pa se hvalimo z imenom Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 8, 'Oni se spotikajo in padajo, mi pa se vzdignemo in ostanemo trdni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 20, 9, 'Gospod, reši! Kralj naj usliši nas, kadar ga kličemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 1, '{Načelniku godbe. Psalm Davidov.} Gospod, moči tvoje se veseli kralj, in rešitve tvoje kako se silno raduje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 2, 'Željo srca njegovega si mu dal in prošnje ustnic njegovih mu nisi odrekel. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 3, 'Kajti prinašaš mu naproti blagoslove dobrote, na glavo njegovo pokladaš venec iz zlata čistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 4, 'Življenja te je prosil, ti si mu ga dal, dni dolgost na vedno večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 5, 'Velika je slava njegova vsled rešitve tvoje, diko in veličastvo si položil nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 6, 'Kajti postavil si ga za blagoslov na veke, razjasnil ga z radostjo pri svojem obličju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 7, 'Zakaj kralj upa v Gospoda, in po milosti Najvišjega ne omahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 8, 'Z roko svojo dosežeš vse neprijatelje svoje, z desnico svojo dosežeš vse sovražilce svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 9, 'Narediš, da bodo kakor peč razbeljena ob času srditega obličja tvojega; Gospod jih uniči v jezi svoji in ogenj jih požre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 10, 'Sad njih pokončaš z zemlje in njih seme izmed sinov človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 11, 'Kajti nameravali so ti hudo, snovali so naklep, a ne morejo ga izvršiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 12, 'Ker ti jih zapodiš v beg, na tetive svoje položiš pšice in jih pomeriš njim v obraz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 21, 13, 'Vzdigni se, Gospod, v moči svoji; in peli bomo in s psalmi proslavljali hrabrost tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 1, '{Načelniku godbe; kakor ‚Košuta jutranje zarje‘. Psalm Davidov.} Bog moj, Bog moj, zakaj si me zapustil? Daleč si od rešitve moje, od stoka mojega besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 2, 'O Bog moj, kličem po dnevi, a ne odgovarjaš, tudi po noči, in ni mi pokoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 3, 'Ti si vendar svet, ki stoluješ nad slavospevi Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 4, 'V tebe so upali očetje naši, upali so, in osvobodil si jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 5, 'K tebi so vpili, in oteti so bili, v tebe so upali, in niso bili osramočeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 6, 'Jaz pa sem črv in ne mož, poroga ljudem in zaničevan od ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 7, 'Vsi, ki me vidijo, me zasmehujejo, režé se in z glavo majó:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 8, 'Zanašal se je na Gospoda! Ta naj ga reši, otme ga naj, ker ima veselje nad njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 9, 'Saj ti si, ki si me potegnil iz materinega telesa, vdahnil si mi upanje pri prsih matere moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 10, 'Nate sem oprt od rojstva, od telesa matere moje si Bog moj mogočni ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 11, 'Ne bivaj daleč od mene, ker je blizu stiska, ker ni pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 12, 'Obsuli so me junci mnogi, krepki junci basánski so me obstopili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 13, 'Žrelo svoje odpirajo zoper mene kakor lev zgrabljiv in rjoveč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 14, 'Kakor voda se razlivam in vse kosti moje se razklepajo; srce moje je podobno vosku, taja se v osrčju mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 15, 'Moč moja je usehnila, da je kakor čepinja, in jezik moj se prijemlje nébesa mojega, in v prah smrti si me položil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 16, 'Kajti obdali so me psi, hudobnikov krdelo me je obkrožilo, prebodli so moje roke in noge moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 17, 'Seštel bi lahko vse svoje kosti; oni pa gledajo, všečno se ozirajo v me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 18, 'Oblačila moja delé med seboj in za suknjo mojo mečejo kocko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 19, 'Ti pa, Gospod, ne bivaj daleč, moč moja, hiti mi na pomoč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 20, 'Otmi meču dušo mojo, iz moči psa edino mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 21, 'Reši me iz žrela levovega! Da, izpred rogovja divjih bivolov si me uslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 22, 'Oznanjati hočem ime tvoje bratom svojim, sredi zbora te bom hvalil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 23, 'Vi, ki se bojite Gospoda, hvalite ga; vse seme Jakobovo, slavite ga, in boj se ga vse seme Izraelovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 24, 'Ker ni zaničeval in ni mrzel trpljenja trpinovega, tudi ni skril obličja svojega pred njim; temuč ko je vpil do njega, ga je uslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 25, 'Od tebe izvira hvalospev moj v zboru velikem; obljube svoje bom opravljal vpričo njih, ki se ga boje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 26, 'Jedli bodo krotki in se nasitili, hvalili bodo Gospoda, kateri ga iščejo; živi naj srce vaše vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 27, 'Spomnijo se in izpreobrnejo se h Gospodu vsi kraji zemlje, in klanjale se bodo pred teboj vse družine poganskih narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 28, 'Kajti Gospodovo je kraljestvo in on vlada nad narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 29, 'Jedli bodo in priklanjali se vsi zemlje bogatini; pred njim bodo padali vsi, ki gredo v prah in ki ne morejo ohraniti duše svoje v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 30, 'Potomstvo mu bo služilo; pripovedovali bodo o Gospodu prihodnjemu rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 22, 31, 'Pridejo in oznanjali bodo pravičnost njegovo ljudstvu, ki se porodi, da je to izvršil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 1, '{Psalm Davidov.} Gospod je moj pastir, slabo se mi ne more goditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 2, 'Na pašnikih zelenih me pase, k tihim vodam me vodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 3, 'Poživlja dušo mojo, vodi me po pravičnosti stezah zavoljo svojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 4, 'Tudi ko bi hodil po dolini smrtne sence, ne bojim se zlega, ker ti si z menoj: šiba tvoja in palica tvoja me tolažita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 5, 'Pred menoj pripravljaš mizo, sovražnikom mojim nasproti; z oljem maziliš glavo mojo, kelih moj je poln do vrha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 23, 6, 'Zgolj dobrota in milost me bosta spremljali vse dni življenja mojega, in prebival bom v hiši Gospodovi na večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 1, '{Psalm Davidov.} Gospodova je zemlja in kar jo napolnjuje, vesoljni svet in prebivalci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 2, 'Kajti on jo je utemeljil nad morji, nad rekami jo je trdno postavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 3, 'Kdo pojde na goro Gospodovo in kdo bo stal na mestu svetosti njegove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 4, 'Kdor je nedolžnih rok in srca čistega, kdor ne žene za nečimurnostjo duše svoje in ne priseza na goljufijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 5, 'Ta prejme blagoslov od Gospoda in pravičnost od Boga rešenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 6, 'To je zarod onih, ki Ga iščejo, ki iščejo obličje tvoje, Bog Jakobov. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 7, 'Dvignite, vrata, glave svoje in dvignite se, večne duri, da vstopi slave Kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 8, 'Kdo pa je ta slave Kralj? Gospod, krepak in mogočen, Gospod, mogočen v boju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 9, 'Dvignite, vrata, glave svoje, dvignite se, pravim, večne duri, da vstopi slave Kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 24, 10, 'Kdo je on, ta slave Kralj? Gospod nad vojskami, on je slave Kralj. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 1, '{Psalm Davidov.} K tebi, o Gospod, povzdigujem dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 2, 'Bog moj, v tebe upam, naj ne pridem v sramoto, sovražniki moji naj se ne radujejo nad mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 3, 'Saj kdorkoli čaka tebe, ne pride v sramoto; osramočeni pa bodo, ki nezvesto ravnajo brez vzroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 4, 'Pota svoja mi kaži, Gospod, steze svoje me uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 5, 'Vodi me, da hodim po resnici tvoji, in uči me, ker ti si Bog rešenja mojega, tebe čakam ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 6, 'Spomni se, o Gospod, mnogega usmiljenja svojega in milosti svojih, ki so od vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 7, 'Grehov mladosti moje in prestopkov mojih se ne spominjaj, po milosti svoji se me spominjaj ti, zavoljo dobrote svoje, o Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 8, 'Dober in zvestih misli je Gospod, zatorej uči grešnike pravi pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 9, 'Vodi krotke, da hodijo po pravici, in krotke uči pot svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 10, 'Vse steze Gospodove so milost in resnica njim, ki hranijo zavezo njegovo in pričevanja njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 11, 'Zaradi imena svojega, Gospod, odpusti krivico mojo, ker velika je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 12, 'Kdo je tak mož, ki se boji Gospoda? On ga pouči, katero pot naj izvoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 13, 'Duša njegova bo prebivala v dobrem, in seme njegovo bo podedovalo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 14, 'Skrivnost Gospodova je očitna njim, ki se ga boje, in zavezo svojo jim razodeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 15, 'Oči moje gledajo neprestano v Gospoda, zakaj on potegne iz mreže noge moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 16, 'Ozri se v me in milost mi stóri, ker osamel sem in ubožen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 17, 'Stiske srca mojega so se pomnožile, iz nadlog mojih me reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 18, 'Poglej siromaštvo moje in težave moje, in odpusti vse grehe moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 19, 'Poglej sovražnike moje, veliko jih je, in z zlovoljnim sovraštvom me sovražijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 20, 'Varuj dušo mojo in reši me, ne pridem naj v sramoto, ker v tebi iščem zavetja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 21, 'Brezmadežnost in poštenost naj me stražita, ker tebe čakam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 25, 22, 'Reši, Bog, Izraela vseh nadlog njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 1, '{Psalm Davidov.} Za sodnika mi bodi, Gospod, ker sem hodil v brezgrajnosti svoji; in v Gospoda sem upal, ne omahnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 2, 'Izkušaj me, Gospod, in preišči me, z ognjem preizkusi obisti moje in srce moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 3, 'Zakaj milost tvoja mi je pred očmi in neprestano hodim v resnici tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 4, 'Ne posedam z ničemurnimi ljudmi in z licemerci se ne shajam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 5, 'Hudobnežev zbor sovražim in z brezbožniki nočem sedeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 6, 'V nedolžnosti umivam roke svoje, oltar tvoj hočem obhajati, o Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 7, 'da zapojem hvalno pesem in oznanjam vsa čuda tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 8, 'Gospod, prebivališče ljubim hiše tvoje in mesto, kjer prebiva slava tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 9, 'Ne pograbi z grešniki duše moje in z možmi krvoželjnimi življenja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 10, 'V njih rokah je hudodelstvo, desnica njih je polna daril podkupnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 11, 'Jaz pa hodim v brezgrajnosti svoji, reši me in milost mi stóri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 26, 12, 'Noga moja stoji na ravnem, v zborih bom slavil Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 1, '{Psalm Davidov.} Gospod je luč moja in rešitev moja, koga bi se bal? Gospod je življenja mojega obrana, koga bi se plašil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 2, 'Ko so se mi bližali hudobniki, da pojedo moje meso, zatiralci moji in sovražilci moji, spoteknili so se in padli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 3, 'Če bi se vojska utaborila proti meni, brez strahu mi je srce, če bi nastal boj zoper mene, upajoč še veselim se tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 4, 'Eno sem prosil Gospoda, to samo želim: da smem bivati v hiši Gospodovi vse dni življenja svojega, da gledam lepoto Gospodovo in jo preiskujem v svetišču njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 5, 'Kajti on me skrije v koči svoji ob dnevu nesreče, prikrije me v skrivališču šatora svojega in me vzdigne na skalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 6, 'In tako bo povišana glava moja nad sovražnike moje, stoječe okrog mene, in daroval bom v šatoru njegovem daritve glasnega veselja, pel bom in psalme citral Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 7, 'Sliši me, o Gospod, ko kličem z glasom svojim, usmili se me in odgovóri mi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 8, 'Ker veliš: Iščite obličje moje! srce moje ti govori: Obličje tvoje bom iskal, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 9, 'Ne skrivaj mi obličja svojega, ne zapodi v jezi hlapca svojega; pomoč moja si bil, ne zavrzi me in ne zapusti me, o Bog zveličanja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 10, 'Kajti oče moj in mati moja sta me zapustila, Gospod pa me k sebi privije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 11, 'Uči me, Gospod, svoj pot in vodi me po ravni stezi zavoljo njih, ki name preže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 12, 'Ne izdajaj me želji zatiralcev mojih, ker zoper mene stoje lažnive priče in ki pihajo silovitost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 13, 'Ko bi ne veroval, da bom užival dobroto Gospodovo v deželi živečih, bi bil poginil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 27, 14, 'Čakaj Gospoda, bodi močan in naj se ohrabri srce tvoje, da čakaj Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 1, 'K tebi, o Gospod, kličem, skala moja, ne delaj mi se gluhega, da ne postanem, ako mi bodeš nem, podoben njim, ki se pogrezajo v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 2, 'Čuj prošenj mojih glas, ko vpijem k tebi, ko iztezam roke svoje proti hramu tvoje svetosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 3, 'Ne vleci me v pogubo z brezbožniki in ž njimi, ki delajo krivico, ki govore mir z bližnjimi svojimi, hudobija pa biva v njih srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 4, 'Daj jim po njih delu in po hudobnosti njih dejanj, po delu njih rok jim daj, povrni jim, kar so zaslužili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 5, 'Kajti ne menijo se za dejanja Gospodova in za delo rok njegovih – podere jih, a postavi jih ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 6, 'Hvaljen bodi Gospod, ker je uslišal prošenj mojih glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 7, 'Gospod je moč moja in ščit moj; njemu je zaupalo srce moje, in pomagal mi je, zato se silno raduje srce moje in slavil ga bom s pesmijo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 8, 'Gospod je moč svojim in rešilna obrana maziljencu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 28, 9, 'O, reši ljudstvo svoje in blagoslovi dediščino svojo, in pasi jih ter podpiraj jih na veke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 1, '{Psalm Davidov.} Dajajte Gospodu, sinovi Božji, dajajte Gospodu slavo in hvalo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 2, 'Dajajte Gospodu slavo njegovega imena, priklanjajte se Gospodu v diki svetosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 3, 'Glas Gospodov se razlega nad vodami, slave Bog mogočni grmi, Gospod nad velikimi vodami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 4, 'Glas Gospodov doni mogočno, glas Gospodov doni veličastno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 5, 'Glas Gospodov lomi cedre, Gospod lomi cedre na Libanonu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 6, 'in dela, da skačejo kakor tele, Libanon in Sirion kakor divjega bivola mladič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 7, 'Glas Gospodov šviga plamene ognjene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 8, 'Glas Gospodov pretresa puščavo, Gospod pretresa puščavo Kadeško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 9, 'Glas Gospodov dela, da košute pred časom rodé, in veje lomi gozdom – ali v svetišču njegovem vse kliče: Slava!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 10, 'Gospod je sedel kot kralj o potopu, in Gospod kralj stoluje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 29, 11, 'Gospod dá moč svojemu ljudstvu, Gospod bo blagoslovil ljudstvo svoje z mirom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 1, '{Psalm Davidov; pesem pri posvečevanju hiše njegove.} Poveličeval te bom, Gospod, ker si me povzdignil in nisi dal sovražnikom mojim radovati se nad mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 2, 'Gospod, Bog moj, ko sem vpil k tebi, si me ozdravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 3, 'Gospod, izpeljal si iz kraja mrtvih dušo mojo, ohranil me živega izmed njih, ki padajo v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 4, 'Pojte psalme Gospodu, svetniki njegovi, in slavite spomin svetosti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 5, 'Kajti jeza njegova je le za trenotek, dobrota njegova pa za ves vek; jok se pač zvečer naseli, a zjutraj so spevi veseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 6, 'Jaz pa sem govoril v sreči svoji: Ne omahnem vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 7, 'Gospod, po blagovoljnosti svoji si storil, da je trdno stala gora moja; ko si pa skril obličje svoje, sem bil izbegan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 8, 'K tebi sem klical, Gospod, in Gospoda sem milo prosil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 9, 'Kaj pridobiš v moji krvi, ko pojdem doli v jamo? ali te bo prah slavil? bode li oznanjal resnico tvojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 10, 'Čuj, o Gospod, in usmili se me, Gospod, bodi mi pomočnik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 11, 'Izpreobrnil si mi jok moj v ples, razpasal si raševnik moj in opasal me z radostjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 30, 12, 'da ti prepeva slava moja in ne umolkne. Gospod, Bog moj, hvalil te bom vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 1, '{Načelniku godbe. Psalm Davidov.} Pri tebi, Gospod, iščem zavetja; naj ne bodem osramočen vekomaj; po pravičnosti svoji me osvobodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 2, 'Nagni k meni uho svoje, hitro me otmi; skala pribežališča mi bodi, trden grad, da se rešim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 3, 'Kajti skala moja si in trdnjava moja, torej zavoljo imena svojega me vodi in me spremljaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 4, 'Izpelji me iz mreže, katero so skrili zoper mene, saj ti si obrana moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 5, 'V roko tvojo izročam duha svojega. Odrešil si me, o Gospod, resnice Bog mogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 6, 'Sovražim nje, ki časté ničemurnosti prazne, jaz pa upam v Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 7, 'Radoval se bom in veselil usmiljenja tvojega, ker si se ozrl na siromaštvo moje, spoznal duše moje stiske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 8, 'in nisi me izdal sovražniku v roko, a v prostoren kraj si postavil noge moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 9, 'Usmili se me, Gospod, ker v stiski sem, od žalovanja hira oko moje, duša moja in telo moje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 10, 'Kajti v žalosti je minilo življenje moje in leta moja v zdihovanju; vsled moje krivice hira krepkost moja in kosti moje ginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 11, 'Zavoljo vseh sovražnikov svojih sem prišel v zasmeh, da, celo sosedom svojim, strah pa sem znancem svojim; ko me zagledajo zunaj, beže od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 12, 'V pozabljenje me zagreba srce kakor mrtvega, postal sem kakor orodje podrto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 13, 'Kajti zasramovanje čujem od mnogih, strašenje od vseh strani; posvetujoč se skupaj zoper mene, mislijo, kako bi prestregli dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 14, 'Jaz pa upam v tebe, Gospod, govorim: Bog moj si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 15, 'V rokah tvojih so časi moji; otmi me iz rok sovražnikov mojih in preganjalcev mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 16, 'Daj, da sveti obličje tvoje nad tvojim hlapcem, reši me po milosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 17, 'Gospod, naj ne pridem v sramoto, ker tebe kličem; osramočeni naj bodo brezbožni in molče naj gredo v pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 18, 'Onemé naj ustne lažnive, ki govoré zoper pravičnega trdo, z napuhom in zaničevanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 19, 'O, kako obila je dobrota tvoja, ki jo hraniš njim, kateri se te bojé, in jo izkazuješ njim, kateri pribegajo k tebi, vpričo otrok človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 20, 'Skrivaš jih v skrivališču obličja svojega pred zarotami ljudi, varuješ jih v koči svoji prepira jezikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 21, 'Hvaljen bodi Gospod, ker mi je izkazal čudovito milost svojo v utrjenem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 22, 'Jaz sem bil sicer rekel v malodušnosti svoji: Iztrebljen sem izpred oči tvojih. Vendar si slišal molitev mojih glas, ko sem k tebi vpil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 23, 'Ljubite Gospoda, vsi svetniki njegovi: Gospod hrani zvestobo in povrača preobilo njemu, ki ravna ošabno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 31, 24, 'Močni bodite in naj se vam ohrabri srce, vi vsi, ki čakate Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 1, '{Psalm Davidov. Pouk.} Blagor mu, komur so odpuščeni prestopki, čigar greh je prikrit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 2, 'Blagor človeku, ki mu Gospod ne všteva krivice in čigar duh nima v sebi zvijače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 3, 'Ko sem molčal, so perele kosti moje vsled stoka mojega po cele dneve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 4, 'Ker po dnevi in po noči je bila težka nad mano roka tvoja, da se mi je sok životni sušil kakor v poletni vročini. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 5, 'Greh svoj sem ti razodel in krivice svoje nisem prikril; dejal sem: Izpovedam se prestopkov svojih Gospodu. In ti si odpustil krivdo mojega greha. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 6, 'Zato naj te ponižno prosi vsak pobožni ob času, ko te lahko najde; zares, ko pride povodenj velikih vodá, njega ne doseže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 7, 'Ti si zavetje meni; stiske me obraniš, s pesmimi oproščenja me obdaš. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 8, 'Jaz ti dam razumnost in kazal ti bom, po kateri poti naj hodiš; svetoval ti bom, v te vpirajoč svoje oko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 9, 'Ne bodite kakor konj, kakor mezeg brez razuma, ki jima je z uzdo in vajetom, njiju opravo, brzdati gobec, sicer se ti ne pokorita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 10, 'Mnoge bolečine zadenejo brezbožnika; kdor pa stavi upanje v Gospoda, njega obdaja milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 32, 11, 'Veselite se v Gospodu in radujte, pravični, in glasno pojte vsi, ki ste pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 1, 'Radujte se, pravični, v Gospodu, poštenim se spodobi hvalno petje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 2, 'Slavite Gospoda s citrami, z desetostrunjem mu pojte psalme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 3, 'Pojte mu novo pesem, krepko udarjajte na strune z radostnim vpitjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 4, 'Ker prava je beseda Gospodova in vsako delo njegovo se vrši v zvestobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 5, 'Pravičnost ljubi in sodbo, milosti Gospodove polna je zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 6, 'Z besedo Gospodovo so ustvarjena nebesa in z dihom ust njegovih vsa vojska nebeška.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 7, 'Morske vode zbira kakor na kup in v shrambe deva valove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 8, 'Boj se Gospoda vsa zemlja, pred njim naj trepetajo vsi prebivalci sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 9, 'Kajti on je rekel, in se je zgodilo, on je zapovedal, in stalo je trdno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 10, 'Gospod uničuje narodov sklepe, misli ljudstev podira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 11, 'Sklep Gospodov pa ostane vekomaj, misli srca njegovega od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 12, 'Blagor narodu, čigar Bog je Gospod, ljudstvu, katero si je izvolil v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 13, 'Iz nebes gleda Gospod, vidi vse sinove človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 14, 'Z mesta prebivališča svojega gleda na vse prebivalce zemlje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 15, 'on, ki obrazuje srca njih vseh, ki pazi na vsa njih dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 16, 'Ni ga kralja, ki bi se rešil z množico krdel, junak se ne otme z veliko močjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 17, 'Vara se, kdor se upa s konjem rešiti, velika moč njegova ga na varno ne odnese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 18, 'Glej, Gospod vpira oko svoje na njé, ki se ga bojé, na njé, ki čakajo milosti njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 19, 'da reši smrti njih dušo in jih žive ohrani v lakoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 20, 'Duša naša čaka Gospoda, on je pomoč naša in ščit naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 21, 'Kajti v njem se razveseli srce naše, ker smo zaupali njegovemu svetemu imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 33, 22, 'Milost tvoja, o Gospod, bodi nad nami, kakor te zaupno čakamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 1, '{Psalm Davidov, ko je premenil vedenje svoje pred Abimelekom in je odšel, ko ga je on spodil.} Slavil bom Gospoda vsak čas, vedno bodi hvala njegova v ustih mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 2, 'V Gospodu se bo ponašala duša moja, čuli bodo to krotki ter se veselili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 3, 'Poveličujte Gospoda z menoj in skupno povišujmo ime njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 4, 'Iskal sem Gospoda, in mi je odgovoril, in iz vseh strahov mojih me je rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 5, 'Kateri gledajo vanj, bodo razsvetljeni in obličje jim ne zardi od sramote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 6, 'Ta ubožec je klical, in Gospod je uslišal, in rešil ga je iz vseh stisk njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 7, 'Šatorišče stavi angel Gospodov okrog njih, ki se ga boje, in jih otimlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 8, 'Okusite in vidite, kako dober je Gospod! Blagor možu, ki išče v njem zavetja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 9, 'Bojte se Gospoda, svetniki njegovi, ker stradanja ni njim, ki se ga boje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 10, 'Mladi levi so v potrebi in stradajo, kateri pa iščejo Gospoda, ne pogrešajo nobene dobrote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 11, 'Pridite, otroci, poslušajte me, strahu Gospodovega vas bom učil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 12, 'Kdo je oni mož, ki se veseli življenja, želi mnogo dni, da uživa dobro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 13, 'Varuj jezik svoj hudega in ustne svoje, da ne govore zvijače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 14, 'Umikaj se hudemu in delaj dobro, išči mirú in hodi za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 15, 'Oči Gospodove pazijo na pravične in ušesa njegova na njih vpitje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 16, 'Srdito pa je njim, ki delajo hudo, obličje Gospodovo, da iztrebi z zemlje njih spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 17, 'Ko kličejo pravični, jih sliši Gospod in jih iz vseh stisk otimlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 18, 'Blizu je Gospod tistim, ki so potrtega srca, in ponižne v duhu rešuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 19, 'Mnoge so pravičnega nadloge, ali iz njih vseh ga reši Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 20, 'Vse kosti njegove ohrani, ena izmed njih se ne zlomi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 21, 'Brezbožnika pa zaduši hudoba, in sovražilci pravičnega se bodo pokorili za krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 34, 22, 'Gospod otimlje dušo hlapcev svojih in ne pogubi se nodeden, ki išče zavetja v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 1, '{Psalm Davidov.} Bojuj se, Gospod, zoper nje, ki se bojujejo z menoj, vojskuj se ž njimi, ki se vojskujejo z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 2, 'Zgrabi ščit veliki in mali in vstani meni v pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 3, 'In potegni sulico in zapri pot njim, ki me preganjajo; reci duši moji: Jaz sem rešenje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 4, 'Sramujejo se naj in v sramoto pridejo, kateri iščejo duše moje, umekniti se morajo in rdečica naj jih oblije, kateri mi nameravajo hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 5, 'Bodo naj kakor pleve pred vetrom, in angel Gospodov naj jih podi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 6, 'Temna bodi njih pot in polzka, in angel Gospodov naj jih preganja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 7, 'Ker brez vzroka so mi skrito nastavili mrežo svojo, brez vzroka jamo izkopali duši moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 8, 'Poguba naj pride nanj iznenada, in naj ga ujame mreža njegova, ki jo je skril, v pogubo naj pade vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 9, 'In duša moja se bo radovala v Gospodu, veselila se v rešenju njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 10, 'Vse kosti moje bodo govorile: Gospod, kdo je tebi enak? Siromaka otimlješ iz rok močnejšega od njega, siromaka in ubožca iz rok njega, ki ga pleni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 11, 'Priče vstajajo krivične, česar si nisem v svesti, me izprašujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 12, 'Hudo mi vračajo za dobro; zapuščena je duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 13, 'In vendar sem jaz, ko so bili bolni, oblečen v raševino, s postom pokoril dušo svojo, in molitev moja se je vračala v nedrije moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 14, 'Vedel sem se, kakor bi mi bil prijatelj ali brat, kakor žalujoč po materi, sem hodil sključen v žalni obleki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 15, 'Oni pa so se radovali moje hromote in se zbirali, zbirali so se zoper mene, druhal hudobna, in nisem tega vedel, psovali so me in niso nehali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 16, 'kakor brezbožni zabavljivci pri pojedinah so s svojimi zobmi režali name.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 17, 'Gospod, doklej boš gledal? Reši dušo mojo njih pogube, mladih levov edino mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 18, 'Slavil te bom v velikem zboru, med ljudstvom obilim bom te hvalil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 19, 'Naj se ne radujejo nad menoj, ki so mi neprijatelji iz krivih vzrokov; kateri me sovražijo brez vzroka, naj ne mežikajo z očesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 20, 'Miru namreč ne govore, temuč zoper mirne v deželi izmišljajo zvijačne stvari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 21, 'In proti meni široko režé, govoreč: Prav, prav, oko naše vidi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 22, 'Vidiš to, Gospod, ne molči torej; Gospod, ne bivaj daleč od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 23, 'Zbúdi se in vstani na sodbo mojo, Bog moj in Gospod moj, na pravdo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 24, 'Sodi me po pravičnosti svoji, Gospod, Bog moj, in naj se ne veselé nad mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 25, 'Naj ne govoré v srcu svojem: Aha, tako smo želeli! ne govoré naj: Pogoltnili smo ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 26, 'Osramočeni naj bodo in zardé vsi skupaj, ki se vesele nesreče moje; s sramoto naj se zagrnejo in nečastjo, kateri se povzdigujejo proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 27, 'A prepevajo naj in se radujejo, kateri se veselé pravičnosti moje, in govoré naj vedno: Poveličevan bodi Gospod, ki se veseli miru svojega hlapca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 35, 28, 'In jezik moj bo oznanjal pravičnost tvojo, ves dan hvalo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 1, '{Načelniku godbe. Psalm hlapca Gospodovega, Davida.} Sodba o grehotnosti brezbožnika se glasi v srca mojega globini: Pred očmi njegovimi ni strahu Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 2, 'Kajti pregreha se mu sladká v oči, da se ne bo našla krivica njegova in sovražila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 3, 'Besede ust njegovih so zloba in zvijača, opustil je razum, da bi delal dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 4, 'Zlobo izmišlja v postelji svoji, stopa na pot, ki ni dobra, hudo se mu ne gnusi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 5, 'Gospod, do nebes sega milost tvoja, zvestoba tvoja do najvišjih oblakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 6, 'Pravičnost tvoja je kakor gore Božje, sodbe tvoje kakor velika globočina; ljudi in živali ohranjaš, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 7, 'Kako dragocena je milost tvoja, Bog, in sinovi človeški pribegajo v senco peruti tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 8, 'Nasičujejo se od obilosti hiše tvoje, in iz reke sladkosti svoje jih napajaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 9, 'Kajti pri tebi je življenja vir, v svetlobi tvoji vidimo svetlobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 10, 'Ohrani milost svojo njim, ki te poznajo, in pravičnost svojo tistim, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 11, 'Ne zadeni me prevzetnega noga in roka krivičnih naj me ne prežene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 36, 12, 'Glej, tam so padli hudodelniki, na tleh ležé in ne morejo vstati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 1, '{Psalm Davidov.} Ne srdi se zaradi hudobnežev, ne zavidaj njim, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 2, 'Ker hitro se pokosé kakor trava in zvenejo kakor bujno zelenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 3, 'Upaj v Gospoda in delaj dobro, prebivaj v deželi in goji zvestobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 4, 'In razveseljuj se v Gospodu, in on ti dá, česar želi srce tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 5, 'Zvrni na Gospoda žitja svojega pot in upaj vanj; on vse prav stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 6, 'In stori, da zasije kakor luč pravičnost tvoja in pravica tvoja kakor opoldansko solnce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 7, 'Molčé se naslanjaj na Gospoda in čakaj ga strpljivo, ne srdi se zaradi njega, ki ima srečo na poti svoji, zaradi moža, ki izvršuje hude naklepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 8, 'Odjenjaj od jeze in pústi togoto, ne srdi se, ker bi le hudo storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 9, 'Zakaj hudodelniki bodo iztrebljeni, čakajoči pa Gospoda bodo podedovali deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 10, 'Še malo namreč, in brezbožnika ne bo več, in ogledoval boš mesto njegovo, a njega ne bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 11, 'Krotki pa bodo podedovali deželo in se radovali v obilosti miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 12, 'Brezbožnik hudo misli zoper pravičnega in škriplje z zobmi proti njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 13, 'Gospod pa se mu smeje, ker vidi, da prihaja dan njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 14, 'Meč so potegnili brezbožni in lok svoj napeli, da podero ubožca in siromaka, da pobijejo tiste, ki pošteno živé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 15, 'A njih meč jim predere srce in njih loki se zdrobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 16, 'Boljše je malo, kar ima pravičnik, nego velika bogastva brezbožnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 17, 'Kajti roke brezbožnih bodo strte, pravične pa podpira Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 18, 'Gospod pozna dneve popolnoma mu vdanih, in njih dediščina ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 19, 'Ne bodo osramočeni ob hudem času in v dnevih lakote bodo nasičeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 20, 'Toda brezbožni poginejo, in sovražniki Gospoda bodo kakor krasota livad, minevajo in izginejo kakor dim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 21, 'Napósodo jemlje brezbožnik, a ne vrne, pravičnik pa je milosten in darežljiv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 22, 'Kajti blagoslovljenci Božji podedujejo deželo, katere pa prokletstvo Njegovo zadene, bodo iztrebljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 23, 'Gospod utrjuje stopinje vrlega moža in pot njegova Mu je po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 24, 'Kadar pade, ne obleži, ker Gospod podpira roko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 25, 'Mlad sem bil in sem se postaral, a nisem videl pravičnega zapuščenega, ne otrok njegovih prositi kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 26, 'Ves dan deli miloščino in posoja, in v blagoslovu je seme njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 27, 'Odstopi od hudega in delaj dobro, in prebival boš v deželi vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 28, 'Kajti Gospod ljubi pravico in ne zapusti svetih svojih, na veke jih bo hranil; seme brezbožnikov pa se iztrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 29, 'Pravični podedujejo deželo in prebivali bodo večno v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 30, 'Pravičnega usta uče modrost in jezik njegov govori pravico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 31, 'V srcu njegovem je postava njegovega Boga, neomahljivi mu bodo koraki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 32, 'Brezbožnik zalezuje pravičnika in ga želi umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 33, 'A Gospod ga ne pusti v roki njegovi, tudi ga ne obsodi, ko ga bodo sodili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 34, 'Čakaj Gospoda in drži se poti njegove, tedaj te poviša, da podeduješ deželo; ko bodo iztrebljeni brezbožni, boš videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 35, 'Videl sem brezbožnika silovitega, in razprostiral se je kakor zeleneče drevo v domači zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 36, 'In šel sem mimo, in glej, ni ga bilo več, in iskal sem ga, a ni ga bilo najti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 37, 'Opazuj poštenega in glej pravičnega: res, bodočnost ima mož miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 38, 'Prestopniki pa poginejo vsi skupaj, zarod brezbožnik se iztrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 39, 'A rešitev pravičnih je od Gospoda, on je njih zavetišče ob času stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 37, 40, 'In pomaga jim Gospod ter jih otimlje, otimlje jih brezbožnikov in jih rešuje, ker so pribegli v zavetje k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 1, '{Psalm Davidov, v spomin.} Gospod, v srdu svojem me ne pokori in v togoti svoji me ne kaznuj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 2, 'Kajti pšice tvoje so se zabodle vame in težko me tlači roka tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 3, 'Nič zdravega ni na mesu mojem zavoljo srda tvojega, miru ni v kosteh mojih zavoljo greha mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 4, 'Zakaj krivice moje mi presezajo glavo, kakor težko breme me tlačijo, pretežke so zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 5, 'Rane moje smrdé in se gnojé, zavoljo nespameti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 6, 'Mučim se in sključen sem jako, ves dan hodim v žalni obleki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 7, 'Kajti ledja moja so polna prisada in nič ni zdravega na mesu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 8, 'Oslabljen sem in potrt presilno, tulim od stokanja svojega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 9, 'Gospod, pred teboj je vse hrepenenje moje in zdihovanje moje ti ni skrito.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 10, 'Srce moje polje, zapustila me je moja krepkost, tudi luč mojih oči mi je zamrla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 11, 'Ljubljenci moji in prijatelji moji so stopili vstran zavoljo nadloge moje, in sorodniki moji stoje oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 12, 'Tisti pa, ki mi prežé po življenju, mi stavijo zanke, in kateri iščejo nesreče moje, govoré o pogubi in izmišljajo ves dan zvijače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 13, 'Jaz pa kakor glušec ne slišim in sem kakor mutec, ki ne odpre svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 14, 'Res, postal sem kakor on, ki ne sliši in ki mu ni dokazov v ustih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 15, 'Kajti tebe čakam, o Gospod, ti zame odgovoriš, Gospod Bog moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 16, 'Ker rekel sem: Da se pač ne radujejo nad menoj! Ko omahuje noga moja, se povzdigujejo proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 17, 'Zdajpazdaj padem, in bolečina moja mi je vedno pred očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 18, 'Kajti krivico svojo pripoznavam in greh moj me skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 19, 'Neprijatelji moji pa so čvrsti in močni, in množijo se, kateri me sovražijo iz krivih vzrokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 20, 'In vračajoč hudo za dobro, mi nasprotujejo, zato ker hodim za dobrim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 21, 'Ne zapústi me, o Gospod, Bog moj, ne bivaj daleč od mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 38, 22, 'Hiti mi na pomoč, o Gospod, rešenje moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 1, '1{Načelniku godbe, Jedutunu. Psalm Davidov.} Rekel sem: Pazil bom na pota svoja, da ne grešim z jezikom svojim; z uzdo bom čuval usta svoja, dokler bo brezbožnik pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 2, 'Onemel sem in se vdal tihoti, tih sem bil, ne meneč se niti za dobro; ali hujšala se je bolečina moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 3, 'Srce moje se je vnemalo v meni, v premišljevanju mojem se je vžgal ogenj; govoril sem z jezikom svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 4, 'Daj, da zvem, o Gospod, konec svoj in kolika je mera mojih dni, da vem, kako sem minljiv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 5, 'Glej, le po dlan dolge si naredil dni moje, in vek moj je kakor nič pred teboj; zares, zgolj ničevost je vsak človek, čeprav stoji trdno. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 6, 'Zares, kakor senčna podoba hodi človek, res, za nič se toliko vznemirja: kopiči imetje, a ne ve, kdo to pograbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 7, 'In sedaj, česa naj pričakujem, o Gospod? Nada moja se ozira v te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 8, 'Vseh prestopkov mojih me reši, nespametnežem v zasmeh me ne izpostavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 9, 'Molčim, ne odprem ust svojih, ker ti si vse prav storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 10, 'Obrni od mene bič svoj, od udarca roke tvoje omahujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 11, 'Ko s kaznimi za krivde pokoriš človeka, uničuješ kakor molj sukno lepoto njegovo –zares, zgolj ničevost je sleherni človek. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 12, 'Čuj molitev mojo, o Gospod, in uho nagni k vpitju mojemu; nikar ne molči solzam mojim, kajti tujec sem pri tebi in naselnik kakor vsi očetje moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 39, 13, 'Prizanesi mi, da se okrepčam, preden odidem in me več ne bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 1, '{Načelniku godbe. Psalm Davidov.} Stanovitno sem čakal Gospoda, in on je, nagnivši se k meni, slišal vpitje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 2, 'In me je potegnil iz jame pogube, iz kaluže, in je postavil noge moje na skalo, utrdil korake moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 3, 'In v usta moja je del novo pesem, hvalno pesem našemu Bogu: mnogi bodo to videli in se bali ter upali v Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 4, 'Blagor možu, ki stavi v Gospoda upanje svoje ter se ne ozira v prevzetnike in nje, ki odstopajo za lažjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 5, 'Mnoga so čuda tvoja, o Gospod, Bog moj, ki si jih storil, in mnoge misli tvoje za nas; nihče ni tebi enak; če bi jih hotel oznanjati in pripovedovati, preveliko jih je, da bi jih naštel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 6, 'Klalnih in jedilnih darov se nisi veselil, a ušesa si mi odprl, žgalnih žrtev in daritev za greh nisi zahteval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 7, 'Tedaj sem rekel: Glej, jaz grem – v zvitku knjige je pisano o meni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 8, 'veselje mi je delati tvojo voljo, Bog moj, in postava tvoja je v mojem srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 9, 'Blagovestje o pravičnosti sem oznanjal v zboru velikem, glej, ustnic svojih nisem zadržaval, o Gospod, ti veš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 10, 'Pravičnosti tvoje nisem skrival v srcu svojem, zvestobo tvojo in zveličanje tvoje sem razglasil, nisem utajil milosti in resnice tvoje velikemu zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 11, 'Ti pa, o Gospod, ne odtezaj mi usmiljenja svojega, milost in resnica tvoja naj me hranita vedno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 12, 'Kajti obsula so me zla, ki jim ni števila, zgrabile so me krivice moje tako, da ne morem pregledati; več jih je nego glave moje las, in srce moje me je zapustilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 13, 'Blagovoli me oteti, o Gospod, hiti mi na pomoč, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 14, 'Osramočeni naj bodo in rdečica naj jih oblije vse vkup, ki iščejo duše moje, da jo pogube; umaknejo se naj in pridejo v nečast, ki želé nesreče moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 15, 'Ostrmé naj nad plačilom sramote svoje, ki mi pravijo: Aha, aha!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 16, 'Vesele se naj in radujejo v tebi vsi, ki te iščejo; kateri ljubijo rešenje tvoje, govore naj vedno: Poveličan bodi Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 40, 17, 'Ubog sem res in potreben, ali Gospod skrbi zame. Pomoč si moja in rešitelj moj, o Bog moj, ne odlašaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 1, '{Načelniku godbe. Psalm Davidov.} Blagor mu, kdor se sočutno ozira na siromaka: ob dnevu nesreče ga otme Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 2, 'Gospod ga bo zaslanjal in ga ohranil življenju, da ga bodo blagrovali na zemlji; in ne izdajaj ga želji sovražnikov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 3, 'Gospod ga bo podpiral na postelji slabosti; vse ležišče mu v bolezni njegovi premeniš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 4, 'Jaz sem rekel: Gospod, usmili se me, ozdravi dušo mojo, ker tebi sem grešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 5, 'Sovražniki moji pa govore hudo o meni: Kdaj bo umrl in izgine ime njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 6, 'In če me kdo pride obiskat, govori laž; srce njegovo si zbira krivico, in gre ven in jo raznaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 7, 'Skupaj šepetajo zoper mene vsi sovražilci moji, zoper mene izmišljajo, kar bi mi bilo v zlo, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 8, 'Stvar silno huda se ga je prijela, in ker je obležal, ne vstane več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 9, 'Celo prijatelj moj, ki sem mu zaupal, ki je jedel moj kruh, je vzdignil peto proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 10, 'Ti pa, Gospod, usmili se me in me vzdigni, da jim povrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 11, 'V tem spoznam, da se me veseliš, ko ne bo sovražnik moj ukal nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 12, 'Mene pa vzdržuješ v brezmadežnosti moji in me staviš pred obličje svoje za večno. —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 41, 13, 'Slava Gospodu, Bogu Izraelovemu, od vekomaj do vekomaj. Amen in Amen! Knjiga druga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 1, '{Načelniku godbe. Pouk sinov Korahovih.} Kakor jelen koprni po potokih vodá, tako duša moja koprni po tebi, o Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 2, 'Žejna je duša moja Boga, mogočnega, živega Boga: Kdaj pridem in se prikažem pred obličjem Božjim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 3, 'Solze moje so mi za hrano po dnevi in po noči, ko mi rekajo ves dan: Kje je Bog tvoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 4, 'Tega se spominjam, ko izlivam v sebi dušo svojo: kako sem šel s krdelom in jih spremljal do hiše Božje, z glasom radostnega petja in hvale, v množici, ki praznuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 5, 'Kaj si tako žalostna, duša moja, in nepokojna v meni? Čakaj Boga, kajti še ga bom slavil, da je pomoč obličja mojega in moj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 6, 'Žalostna je v meni duša moja, zatorej se spominjam tebe iz dežele Jordanske in Hermonske, z gore Micarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 7, 'Brezno kliče breznu ob šumenju slapov tvojih, vsi valovi in zagoni tvoji so se zgrnili name.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 8, 'Vendar mi pošlje Gospod od dnevi milost svojo, in po noči bo z menoj hvalna pesem njemu, molitev k Bogu mogočnemu življenja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 9, 'Govoril bom Bogu mogočnemu, skali svoji: Zakaj me zabiš? zakaj mi je v žalosti hoditi zaradi zatiranja sovražnikovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 10, 'Kakor bi drobili kosti moje, me sramoté zatiralci moji, govoreč mi ves dan: Kje je Bog tvoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 42, 11, 'Kaj si tako žalostna, duša moja, in nepokojna v meni? Čakaj Boga, kajti še ga bom slavil, da je pomoč obličja mojega in moj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 1, 'Sodi me, o Bog, in prevzemi pravdo mojo zoper ljudstvo nesveto; moža zvijačnega in krivičnega reši me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 2, 'Kajti ti si Bog moči moje, zakaj me zametaš? zakaj mi je v žalosti hoditi zaradi zatiranja sovražnikovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 3, 'Pošlji luč svojo in resnico svojo, oni naj me vodita, pripeljeta naj me na goro svetosti tvoje in v šatore tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 4, 'da stopim pred oltar Božji, pred Boga mogočnega, ki je veselje radosti moje, in te slavim s citrami, o Bog, Bog moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 43, 5, 'Kaj si tako žalostna, duša moja, in nepokojna v meni? Čakaj Boga, kajti še ga bom slavil, da je pomoč obličja mojega in moj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 1, '{Načelniku godbe. Psalm sinov Korahovih. Pouk.} O Bog, z ušesi svojimi smo slišali, očetje naši so nam pripovedovali, kako delo si storil v njih časih, v časih starodavnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 2, 'Ti si z roko svojo izgnal poganske narode in naselil njé, zatrl si ljudstva in razširil njé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 3, 'Niso namreč z mečem svojim dobili dežele v oblast, in njih rama jim ni dala rešenja, marveč desnica tvoja in rama tvoja in obličja tvojega luč, ker blagovoljen si jim bil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 4, 'Ti sam si kralj moj, o Bog: Pošlji vsakršno rešenje Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 5, 'S teboj poderemo na tla zatiralce svoje, v imenu tvojem pogazimo nje, ki se vzpenjajo zoper nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 6, 'Ker na lok svoj se ne zanašam, in meč moj me ne reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 7, 'Ali ti nas otimlješ zatiralcev naših in sovražilce naše osramočuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 8, 'Z Bogom se hvalimo vse dni in ime tvoje bomo slavili vekomaj. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 9, 'Zdaj pa si nas zavrgel in izdal v sramoto in ne hodiš z našimi vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 10, 'Storil si, da smo se umaknili sovražniku, in neprijatelji naši si kopičijo plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 11, 'Izdal si nas kakor ovce v hrano in med pogane si nas razkropil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 12, 'Prodal si ljudstvo svoje za malo in povišal nisi cene njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 13, 'Izpostavil si nas v zasrambo sosedom našim, v zasramovanje in zasmehovanje njim, ki so okoli nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 14, 'Za pregovor si nas postavil med narodi in da ljudstva majejo z glavo nad nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 15, 'Ves dan mi je nečast moja pred očmi in obličja mojega sramota me pokriva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 16, 'Zaradi glasu zasramovalca in preklinjalca, spričo sovražnika in maščevalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 17, 'Vse to nas je zadelo, in vendar te nismo pozabili niti nezvesto ravnali proti zavezi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 18, 'Ni se umeknilo srce naše in stopinja naša ni zavila v stran od steze tvoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 19, 'da si nas tako potrl v kraju šakalov in pokril s senco smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 20, 'Ko bi bili pozabili ime Boga svojega in iztegnili roke svoje k bogu tujemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 21, 'ali bi ne bil Bog tega poiskal? Saj on pozna srca skrivnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 22, 'Toda zavoljo tebe nas moré ves dan, cenijo nas kakor ovce za klanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 23, 'Zbúdi se, zakaj spiš, o Gospod? Vstani, ne zametaj nas na večno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 24, 'Zakaj skrivaš obličje svoje, pozabljaš bedo našo in zatiranje naše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 25, 'Ker v prah je ponižana duša naša, tal se je prijelo telo naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 44, 26, 'Vstani na pomoč nam in reši nas zavoljo milosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 1, '{Načelniku godbe. O lilijah. Psalm sinov Korahovih. Pouk. Pesem ljubezni.} Iz srca mojega vre lepa beseda; pravim: Kralju pesem moja! jezik moj bodi kakor pero spretnega pisarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 2, 'Mnogo lepši si od sinov človeških, miloba je razlita po ustnah tvojih, zatorej te je Bog blagoslovil vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 3, 'Meč svoj si opaši okoli ledij, o junak mogočni, slavo svojo in veličastvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 4, 'In v veličastvu svojem srečno hodi v prospeh resnice ter krotkosti in pravičnosti, in pokaže ti desnica tvoja strahotna dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 5, 'Pšice tvoje so ostre, ljudstva bodo padala podte – zasadé se sovražnikom kraljevim v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 6, 'Prestol tvoj, o Bog, ostane vselej in vekomaj, pravičnosti žezlo je tvojega kraljestva žezlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 7, 'Ljubil si pravičnost in sovražil krivico, zato te je pomazilil Bog, Bog tvoj, z oljem veselja pred tovariši tvojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 8, 'Vsa oblačila tvoja dišé miro in aloo in kasijo, iz palač slonokoščenih te razveseljuje godba na strune.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 9, 'Hčere kraljeve so med dragimi tvojimi, kraljica stoji tebi na desno v zlatu iz Ofirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 10, 'Čuj, hči, in glej in nagni uho svoje ter pozabi ljudstvo svoje in hišo očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 11, 'In radoval se bo kralj lepote tvoje; zakaj on je Gospod tvoj: poklanjaj se njemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 12, 'In hči tirska pride z darilom, bogatini izmed ljudstev bodo prosili blagovoljnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 13, 'Vsa krasna je hči kraljeva v notranjščini hiše, obleka njena z zlatom je pretkana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 14, 'V pisanih oblačilih jo privedo h kralju, zanjo pa device, njene tovarišice, pripeljejo k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 15, 'Vodili jih bodo z največjim veseljem in radovanjem in stopijo v palačo kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 16, 'Na mestu očetov tvojih bodo sinovi tvoji, za vojvode jih postaviš po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 45, 17, 'Spominjal bom imena tvojega od roda do roda, zato te bodo slavila ljudstva vedno in na večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 1, '{Načelniku godbe; psalm sinov Korahovih; za visoke glasove. Hvalna pesem.} Bog nam je pribežališče in moč, v stiskah pomoč najhitrejša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 2, 'Zato se pa ne bojimo, čeprav se premakne zemlja, če se gore pogreznejo v globino morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 3, 'Šumé naj in se penijo njegove vode, in gore naj se gibljejo od navala njegovega. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 4, 'Je reka, potoki njeni razveseljujejo mesto Božje, kraj presveti prebivališč Najvišjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 5, 'Bog je v sredi njegovi, ne gane se, Bog mu pomore zjutraj ob svitu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 6, 'Ko hrume narodi in se gibljejo kraljestva, oglasi se on, in taja se zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 7, 'Gospod vojnih krdel je z nami, grad visok je nam Bog Jakobov. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 8, 'Pridite, glejte dela Gospodova, kakšno pustošenje je naredil na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 9, 'Vojske mirí tja do krajev zemlje, lok lomi in sulico krši, bojne vozove sežiga z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 10, '„Odnehajte in spoznajte, da sem jaz Bog! Povišan naj bodem med narodi, povišan na zemlji.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 46, 11, 'Gospod vojnih krdel je z nami, grad visok je nam Bog Jakobov. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 1, '{Načelniku godbe. Sinov Korahovih psalm.} Vsa ljudstva ploskajte z rokami, ukajte Bogu z donečim glasom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 2, 'Kajti Gospod, Najvišji, je strašen, kralj velik nad vso zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 3, 'Ljudstva nam sili v oblast, narode pod noge naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 4, 'Odbira nam posestvo naše, ponos Jakoba, ki ga je ljubil. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 5, 'Bog je šel v višavo z veselim glasom, Gospod s trombe bučanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 6, 'Pevajte Bogu, pevajte psalme, pevajte Kralju našemu, pevajte psalme!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 7, 'Zakaj vse zemlje kralj je Bog, pevajte psalme poučno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 8, 'Bog kraljuje nad narodi, Bog sedi na prestolu svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 47, 9, 'Plemenitniki narodov so se zbrali v ljudstvo Boga Abrahamovega; zakaj Božji so zaščitniki zemlje, silno je vzvišen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 1, '{Pesem. Psalm sinov Korahovih.} Velik je Gospod in visoke hvale vreden v mestu Boga našega, na gori svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 2, 'Krasno se dviga, veselje vse zemlje je gora Sion, na severni strani, mesto Kralja velikega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 3, 'Znan je Bog v dvorih njegovih kot grad visok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 4, 'Kajti glej, kralji so se zbrali, pripodili so se skupaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 5, 'a videli so in so ostrmeli, zmedli so se in zbežali urno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 6, 'Trepet jih je obšel tam, bolečina kakor porodnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 7, 'Z vzhodnim vetrom razbijaš ladje tarsiške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 8, 'Kakor smo slišali, tako smo videli v mestu Gospoda nad vojskami, v mestu Boga našega: Bog ga utrjuje na veke. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 9, 'Premišljali smo milost tvojo, o Bog, sredi svetišča tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 10, 'Kakor ime tvoje, tako je slava tvoja do krajev zemlje; pravičnosti je polna desnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 11, 'Veseli se naj gora Sion, radostno naj poskakujejo hčere Judove zavoljo sodb tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 12, 'Obhodite Sion in obkrožite ga, štejte stolpe njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 13, 'Ogledujte natančno trdno zidovje njegovo, preglejte palače njegove, da boste mogli pripovedovati prihodnjemu rodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 48, 14, 'Zakaj ta Bog je Bog naš vselej in vekomaj. Ta nas bo vodil preko smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 1, '{Načelniku godbe. Sinov Korahovih psalm.} Čujte to, vsa ljudstva, poslušajte, vsi sveta prebivalci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 2, 'nizki in visoki, bogatini in ubožci vsi skupaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 3, 'Usta moja bodo govorila modrost in srca mojega premišljevanje bo razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 4, 'Uho svoje nagnem h govoru v prilikah, na strune igraje, bom razodeval uganko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 5, 'Kaj bi se bal v dnevih nesreče, kadar me obdaja krivičnost tistih, ki mi so za petami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 6, 'njih, ki zaupajo v premoženje svoje in se ponašajo v obilosti bogastva svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 7, 'Brata nikakor ne more odkupiti nihče, ne more dati Bogu zanj spravnega denarja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 8, '(predrag namreč je njih duše odkup, zato ga ne zmore vekomaj),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 9, 'da bi živel za večno, ne moral videti jame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 10, 'Saj vidi bogatin: mrjó modri, enako ginevajo nespametni in neumni in drugim puščajo bogastvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 11, 'Menijo, da njih hiše bodo trajale za veke, njih prebivališča za vse rodove; zato imenujejo dežele s svojimi imeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 12, 'In vendar človek v veličju nima obstanka, podoben je živalim, ki poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 13, 'To je usoda njih, ki tako v sebe zaupajo; vendar njih nasledniki odobravajo njih govorjenje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 14, 'Kakor ovce bodo razpostavljeni v šeolu, smrt jim bo pastir; in pravični jim bodo gospodovali tisto jutro, in njih obliko pokonča šeol, da ji ne bo več bivališča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 15, 'Ali dušo mojo reši Bog iz oblasti šeola, ker me vzame k sebi. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 16, 'Ne boj se, ko kdo zabogati, ko se pomnoži slava hiše njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 17, 'Ker ob smrti ne vzame nič tega s seboj, za njim ne pojde slava njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 18, 'Čeprav blagruje dušo svojo v življenju svojem – i tebe hvalijo, ko si privoščiš –,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 19, 'vendar pride k rodu očetov svojih, ki vekomaj ne bodo uživali luči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 49, 20, 'Človek, ki je v veličju, a ni razumen, je podoben živini, ki pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 1, '{Psalm Asafov.} Bog mogočni, Bog, Gospod je govoril in poklical zemljo od vzhoda solnčnega do zahoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 2, 'S Siona, najvišje lepote, se je zasvetil Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 3, 'Pride Bog naš in nikar ne bo molčal; ogenj požirajoč gre pred njim in okrog njega silen vihar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 4, 'Nebesom kliče odzgoraj in zemlji, da sodi ljudstvo svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 5, '„Zberite mi svetnike moje, ki so storili zavezo z menoj pri daritvi!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 6, 'In nebesa oznanjajo pravičnost njegovo, kajti Bog je sodnik. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 7, 'Čuj, ljudstvo moje, in govoril bom, o Izrael, in zoper tebe bom pričal! Bog, tvoj Bog sem jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 8, 'Nočem te grajati zavoljo daritev tvojih, saj žgalne daritve tvoje so vedno pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 9, 'Ni mi treba jemati iz tvoje hiše junca, ne kozličev iz tvojih ograj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 10, 'Ker moja je vsaka zver v gozdih, živali na tisočerih gorah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 11, 'Vso perutnino gorsko poznam, in kar se poja po polju, je v moji oblasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 12, 'Ko bi bil gladen, ne rekel bi tebi, ker moja je zemlja vesoljna in vse, kar je na njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 13, 'Ali mar jem meso volovsko, ali pijem kozlov kri?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 14, 'Hvalne daritve prinašaj Bogu in Najvišjemu opravljaj obljube svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 15, 'In kliči me v dan stiske, rešil te bom, in ti me boš častil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 16, 'Toda krivičniku pravi Bog: Kaj da naštevaš zapovedi moje in jemlješ zavezo mojo v usta svoja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 17, 'Saj ti sovražiš svarjenje in besede moje si vrgel vzad zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 18, 'Kadar vidiš tatú, se ž njim hitro sprijazniš in s prešeštniki se družiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 19, 'Usta svoja rabiš za hudo in z jezikom svojim spletaš zvijačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 20, 'Sedé obrekuješ svojega brata, matere svoje sina spravljaš v sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 21, 'To si delal, in ker sem molčal, si menil, da sem prav tebi enak. A karal te bom in vse ti postavil pred oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 22, 'Pazite vendar na to vi, ki zabite Boga, da ne zgrabim, in ga ne bode, ki bi rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 50, 23, 'Kdor daruje hvalo, me prav časti, in kdor uravnava pot svojo, mu pokažem zveličanje Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 1, '1 {Načelniku godbe. Psalm Davidov, ko je prišel k njemu Natan prorok, potem ko se je bil sešel z Batsebo.} Milosten mi bodi, o Bog, po dobroti svoji, po obilosti svojega usmiljenja izbriši pregrehe moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 2, 'Čisto me operi krivice moje in greha mojega me očisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 3, 'Kajti pregrehe svoje spoznavam in greh moj mi je vedno pred očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 4, 'Tebi, tebi samemu sem grešil in storil, kar je zlo tvojim očem, da se ti izkažeš pravičnega, kadar govoriš, in čistega, kadar sodiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 5, 'Glej, v krivici sem se rodil in v grehu me je spočela mati moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 6, 'Glej, ti želiš resničnost v notranjščini, zato mi v skritosti srca razodevaj modrost svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 7, 'Očisti me z izopom, da bodem čist, operi me, da bodem bel bolj nego sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 8, 'Daj mi slišati veselje in radost, da veselja poskakujejo kosti, ki si jih potrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 9, 'Skrij srdito obličje svoje grehom mojim in vse krivice moje izbriši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 10, 'Srce čisto mi ustvari, o Bog, in trdnega duha ponovi v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 11, 'Ne zavrzi me izpred svojega obličja in svetega Duha svojega ne jemlji od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 12, 'Povrni mi zopet veselje zveličanja svojega in z duhom radovoljnosti me podpiraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 13, 'Učil bom prestopnike pota tvoja, in grešniki se povrnejo k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 14, 'Reši me krivde prelite krvi, o Bog, Bog zveličanja mojega, in radostno bo hvalil jezik moj pravičnost tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 15, 'Gospod, odpri moje ustne, in usta moja bodo oznanjala hvalo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 16, 'Ker ti se ne veseliš daritev, pač bi jih dal rad, tudi žgalnih daritev ne maraš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 17, 'Daritve Božje so duh potrt, srca potrtega in pobitega, o Bog, ne zametaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 18, 'Z dobrotami obsiplji Sion po blagovoljnosti svoji, sezidaj zidovje jeruzalemsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 51, 19, 'Tedaj se boš veselil daritev pravičnosti, žgalnih in celih daritev, tedaj bodo pobožni pokladali junce tebi na oltar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 1, '{Načelniku godbe. Pouk Davidov; ko je Doeg Edomec prišel in naznanil Savlu ter mu rekel: David je prišel v hišo Ahimelekovo.} Kaj se hvališ s hudobijo, o mogočni? Milost Boga mogočnega traja vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 2, 'Nesrečo napravljaš z jezikom svojim, podoben je ostri britvi, ti zvijače snovatelj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 3, 'Hudo ljubiš bolj ko dobro, laž bolj ko govorico pravice. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 4, 'Ljubiš zgolj besede pogubne, o jezik zvijačni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 5, 'Zatorej te tudi Bog mogočni podere na vekomaj, zgrabi te in prežene iz šatora tvojega, in s korenom te izpuli iz dežele živečih. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 6, 'To bodo videli pravični v božjem strahu in njemu se smejali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 7, 'Glejte onega moža, ki si ni vzel Boga za brambo, marveč se je zanašal na bogastva svojega obilost in utrjeval se v hudobnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 8, 'Jaz pa sem kakor oljka zeleneča v hiši Božji, upam v milost Božjo vselej in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 52, 9, 'Slavil te bom vekomaj, ker si storil to; in čakal bom imena tvojega, ker je dobro, vpričo svetih tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 1, '{Načelniku godbe; na mahalat. Pouk Davidov.} Nespametnež govori v svojem srcu: Ni Boga. Izprijeni so in ostudno krivico delajo, ni ga, ki bi činil dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 2, 'Bog je z neba gledal doli na sinove človeške, da bi videl, je li kateri razumen, je li kdo, ki išče Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 3, 'Vsak izmed njih je odstopil, izpridili so se vsi vkup; ni ga, ki bi delal dobro, ne enega samega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 4, 'Ali so docela brezpametni, kateri delajo krivico, ki žró ljudstvo moje, kakor bi jedli kruh, Boga pa ne kličejo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 5, 'Tam so se preplašili od groze, kjer ni bilo groze; ker Bog je razsul kosti vsakega, ki se je utaboril zoper tebe; osramotil si jih, ker Bog jih je zavrgel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 53, 6, 'O da bi prišlo zveličanje s Siona Izraelu! Ko bo Bog nazaj peljal iz sužnosti ljudstvo svoje, veselil se bo Jakob, radoval se Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 1, '{Načelniku godbe; na strune. Pouk Davidov; ko so prišli Zifovci in rekli Savlu: Ali ni skrit David pri nas?} Bog, reši me po imenu svojem in po moči svoji stori mi pravico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 2, 'Bog, čuj molitev mojo, uho nagni besedam mojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 3, 'Kajti tujci so se vzdignili zoper mene in silovitniki strežejo po življenju mojem; Boga nimajo pred očmi. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 4, 'Glej, Bog mi je pomočnik, Gospod je ž njimi, ki podpirajo dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 5, 'On povrne zlo zalezovalcem mojim; po resničnosti svoji jih pokončaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 6, 'Radovoljno ti bom daroval, slavil bom ime tvoje, Gospod, ker je dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 54, 7, 'Kajti rešil me je vsake stiske, in na sovražnike moje z veseljem gleda moje oko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 1, '{Načelniku godbe; na strune. Pouk Davidov.} Sliši, o Bog, molitev mojo in prošnji moji se ne skrivaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 2, 'Ozri se v me in mi odgovori; blodim v žalovanju svojem in ječati mi je');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 3, 'zavoljo glasú sovražnikovega, zavoljo stiskanja krivičnika. Ker name zvračajo krivico in v jezi me preganjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 4, 'Srce se mi krči v životu, in smrtni strahovi so me obšli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 5, 'Strah in trepet me napadata, in groza me je prevladala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 6, 'In sem rekel: O, da bi imel peruti kakor golob, zletel bi, kjer bi mogel počivati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 7, 'Glej, kar najdalje bi pobegnil, prebival bi v puščavi. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 8, 'Hitel bi, da si najdem zavetja pred besnečim vetrom, pred viharjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 9, 'Pogúbi, Gospod, razdeli njih jezik; ker silovitost in prepir vidim v mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 10, 'Po dnevi in po noči prežeč pohajajo po zidovju njegovem, krivica in hudobnost pa sta sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 11, 'Škodoželjnost je sredi njega, in z ulic njegovih se ne umakneta zatira in zvijača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 12, 'Kajti ne nasprotnik me sramoti, to bi prenašal; ne sovražilec moj se vzpenja proti meni, njemu bi se skril, –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 13, 'temuč ti, človek, meni enak, prijatelj moj in zaupnik moj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 14, 'ki sva skupaj sladko se družila, v hišo Božjo hodila z veselo množico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 15, 'Smrt naj jih preseneti! živi naj se pogreznejo v kraj mrtvih, ker hudobnost je v njih prebivališču, sredi med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 16, 'Jaz pa bom klical Boga, in Gospod me bo rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 17, 'Zvečer in zjutraj in opoldne bom tožil in stokal, dokler ne usliši mojega glasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 18, 'Otel je in v mir postavil dušo mojo iz boja zoper mene; kajti z mnogimi krdeli so se vojskovali proti meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 19, 'Slišal bo Bog mogočni in jim odgovoril, saj on sedi na prestolu od vekomaj (Sela.), njim, v katerih ni premembe misli in se ne boje Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 20, 'Nezvestnik je iztegnil roko svojo zoper nje, ki so živeli v miru ž njim; zavezo svojo je oskrunil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 21, 'Gladke so, maslene besede njegove, a vojska tiči v njegovem srcu; mehkejši od olja so govori njegovi, in vendar so goli meči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 22, 'Vrzi na Gospoda breme svoje, in on te bo podpiral; nikdar ne pripusti, da omahne pravičnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 55, 23, 'In ti, o Bog, jih pahneš v jamo pogube; ljudje krvoločni in zvijačni ne dožive dni svojih polovice. Jaz pa bom v tebe upal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 1, '{Načelniku godbe, kakor ‚Nema golobica v oddaljenih krajih‘. Davidova zlata pesem, ko so ga prijeli Filistejci v Gatu.} Milosten mi bodi, o Bog, ker rohneč me preganja človek, ves dan se z menoj bojuje in me stiska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 2, 'Rohne zalezovalci moji ves dan, ker mnogo jih je, ki se zoper mene vojskujejo ošabno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 3, 'Ob dnevu, ko me strah obhaja, stavim svoje upanje vate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 4, 'V Bogu bom hvalil besedo njegovo; v Boga upam, ne bom se bal: Kaj mi more storiti meso?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 5, 'Ves dan prevračajo moje besede, zoper mene merijo vse njih misli v hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 6, 'Zbirajo se in skrivajo se v prežo, pazijo mi na stopinje, ker mi strežejo po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 7, 'Se li bodo rešili ob taki hudobnosti? V jezi pahni ljudstva, o Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 8, 'Ti imaš seštete ure tavanja mojega. Deni v lagvico svojo vsako solzo mojo, ali bi jih ne imel v zaznamku svojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 9, 'Potem se umaknejo sovražniki moji v dan, ko bom klical; to vem, da mi je Bog na strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 10, 'V Bogu bom hvalil besedo, v Gospodu hvalil besedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 11, 'V Boga upam, ne bom se bal: Kaj mi more storiti človek?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 12, 'Dolžan sem ti, o Bog, obljube; hvalne daritve ti bom opravljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 56, 13, 'Ker ti si otel dušo mojo smrti, tudi noge moje padca, da neprestano hodim pred Bogom v življenja luči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 1, '{Načelniku godbe; kakor ‚Ne pogubi!‘Davidova zlata pesem, ko je bežal pred Savlom v votlino.} Milosten mi bodi, Bog, milosten mi bodi, ker k tebi je pribežala duša moja, in v senci peruti tvojih iščem zavetja, dokler ne minejo težave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 2, 'Klical bom k Bogu Najvišjemu, k Bogu mogočnemu, ki vse izvršuje zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 3, 'Pošlje iz nebes in mi da rešenje, osramoti njega, ki me rohneč preganja. (Sela.) Pošlje Bog milost svojo in resnico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 4, 'Duša moja je sredi levov, ležati mi je med razkačenimi, med ljudmi, katerih zobje so sulice in pšice, in jezik njih je oster meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 5, 'Povišaj se nad nebesa, o Bog, nad vso zemljo bodi slava tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 6, 'Mrežo so nastavili stopinjam mojim, sovražnik je potlačil dušo mojo, jamo so izkopali pred menoj, a sami so popadali vanjo. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 7, 'Utrjeno je srce moje, o Bog, utrjeno je srce moje, pel bom in na strune brenkal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 8, 'Prebudi se slava moja, prebudite se, brenklje in strune, zbudim naj jutranjo zarjo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 9, 'Slavil te bom med ljudstvi, Gospod, psalme ti prepeval med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 10, 'Zakaj velika je do nebes milost tvoja, do nebeških višav resnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 57, 11, 'Povišaj se nad nebesa, o Bog, nad vso zemljo bodi slava tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 1, '{Načelniku godbe; kakor ‚Ne pogubi!‘Davidova zlata pesem.} Ali res v molčanju govorite pravičnost? po pravici li sodite, sinovi človeški?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 2, 'Ne, v srcu počenjate hudodelstvo, v deželi tehtate rok svojih silovitost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 3, 'Spačeni so brezbožniki od rojstva, tavajo od materinega telesa, laž govoreč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 4, 'Strup imajo podoben kačjemu strupu, so kakor gluh gad, ki si maši uho,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 5, 'ki ne posluša glasu rotilcev, ne čarodeja, ki je vešč zagovoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 6, 'O Bog, zdróbi jim zobe v njih ustih, mladih levov kočnike izderi, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 7, 'Stopé se naj kakor voda, ki se razteče; ko nastavi sovražnik pšice svoje, naj bodo, kakor bi jih bil kdo okrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 8, 'Bodo naj kakor polž, ki se topi in gine, kakor žene splav, ki ni videl solnca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 9, 'Še preden občutijo vaši lonci ogenj od trnja, odpravi Bog z vihrom surovo meso in žar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 10, 'Radoval se bo pravični, ko bo videl maščevanje, noge svoje bo umival v krvi brezbožnikovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 58, 11, 'In ljudje poreko: Zares, je plačilo za pravičnega, zares, je Bog, ki sodi na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 1, '{Načelniku godbe; kakor ‚Ne pogubi!‘Davidova zlata pesem, ko je poslal Savel može, in so stražili hišo njegovo, da bi ga umorili.} Otmi me sovražnikov mojih, moj Bog, na varno me postavi nad njimi, ki se vzpenjajo zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 2, 'Otmi me njih, ki delajo krivico, in ljudi krvoločnih me reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 3, 'Zakaj, glej, na dušo mojo preže, zbirajo se zoper mene krepki, ne zavoljo prestopka, ne zavoljo greha mojega, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 4, 'Brez krivde moje se stekajo in pripravljajo; vstani, pridi mi naproti in poglej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 5, 'Ti torej, Gospod Bog nad vojskami, Bog Izraelov, zbúdi se, da obiščeš vse poganske narode, naj se ti ne smili ne eden hudodelcev verolomnih. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 6, 'Vračajo se zvečer, renče kakor psi in okrog tekajo po mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 7, 'Glej, iz ust jim vre hudo, meči so v njih ustnah, kajti: Kdo sliši? pravijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 8, 'Ti pa, Gospod, se jim boš smejal, zasmehoval boš vse tiste narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 9, 'Moč moja, nate bom pazil, ker Bog je moj grad visoki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 10, 'Bog moj mi pride naproti z milostjo svojo, Bog mi dá, da bom z veseljem gledal sovražnike svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 11, 'Ne pobij jih, da ne pozabi ljudstvo moje, s svojo močjo jih izženi, da naj blodijo, in pahni jih, o Gospod, ščit naš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 12, 'Greh njih ust je njih ustnic beseda; bodo naj torej ujeti v napuhu svojem in zavoljo kletvine in laži, ki jo izgovarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 13, 'Pokončaj jih v srdu, pokončaj, da jih ne bode več; in spoznajo naj, da Bog gospoduje v Jakobu in tja do mej zemlje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 14, 'In zvečer se vračajo, renče kakor psi in okrog tekajo po mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 15, 'Klatijo se okoli zavoljo jedi; ko se ne nasitijo, tu prenočujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 16, 'Jaz pa bom pel o moči tvoji in veselo pel o milosti tvoji, ker ti si mi bil grad visoki in pribežališče ob dnevi stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 59, 17, 'O moč moja, tebi bom prepeval psalme, zakaj Bog je grad moj visoki, Bog milosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 1, '{Načelniku godbe; kakor ‚Lilija pričevanja‘. Zlata pesem Davidova, v poučevanje, ko se je boril s Sirci iz Mezopotamije in s Sirci Zobejskimi in se je Joab vrnil in pobil Edomcev v Solni dolini dvanajst tisoč.} O Bog, zavrgel si nas, razkropil nas, srdit si bil, a zopet nas ustanovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 2, 'Zmajal si deželo, raztrgal jo, zaceli razpoke njene, ker omahuje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 3, 'Storil si, da je ljudstvo tvoje čutilo trdost, dal si nam piti vina omotnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 4, 'Dal si njim, ki se tebe bojé, zastavo, da naj se povzdigne zaradi resnice. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 5, 'Da bodo oteti ljubljenci tvoji, stóri rešenje z desnico svojo in usliši nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 6, 'Bog je govoril v svetosti svoji: Radoval se bom, razdelim Sihem in dolino Sukotsko premerim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 7, 'Moj je Gilead in moj Manase in Efraim glave moje bramba, Juda moje žezlo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 8, 'Moab umivalnica moja, na Edoma vržem obuvalo svoje, nad mano, o Filisteja, ukaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 9, 'Kdo me popelje v mesto utrjeno, kdo me pripelje noter do Edomeje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 10, 'Ali ne ti, o Bog, ki si nas bil zavrgel, in nisi hodil, Bog, z našimi vojskami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 11, 'Daj nam pomoč zoper sovražnika, ker ničeva je pomoč človeška.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 60, 12, 'V Bogu delajmo junaške čine, in on bo poteptal zatiralce naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 1, '{Načelniku godbe; na strune. Psalm Davidov.} Sliši, o Bog, vpitje moje, pazi na molitev mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 2, 'Od kraja zemlje kličem k tebi, ko oslabeva srce moje; pelji me na skalo, višjo od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 3, 'Kajti bil si mi pribežališče, stolp krepak v bran pred sovražnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 4, 'Bival bom v šatoru tvojem na veke, pribežim pod zaščito peruti tvojih. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 5, 'Zakaj ti, o Bog, si poslušal obljube moje, dal si mi dediščino tistih, ki se bojé imena tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 6, 'Dni dodaj dnevom kraljevim, leta njegova naj bodo kakor mnogih rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 7, 'Ostane naj vekomaj pred Bogom, milost in resnico pripravi, da naj ga varujeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 61, 8, 'Tako bom psalme peval tvojemu imenu večno, opravljajoč dan na dan obljube svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 1, '{Načelniku godbe; za Jedutuna. Psalm Davidov.} Samo Bogu tiho vdana je duša moja, od njega pride rešenje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 2, 'Samo on je skala moja in rešitev moja, grad visoki moj, ne omahnem mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 3, 'Doklej se hočete zaganjati v moža? da ga poderete vi vsi kakor nagnjeno steno in omajano ograjo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 4, 'Posvetujejo se samo, kako bi ga z višave njegove pehnili; laž jim ugaja: z usti svojimi vsak blagoslavlja, znotraj v sebi pa preklinja. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 5, 'Samo Bogu bodi tiho vdana, duša moja, zakaj od njega pride pričakovanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 6, 'Samo on je skala moja in rešitev moja, grad moj visoki, ne omahnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 7, 'Na Boga je oprta rešitev moja in slava moja; skalo moči svoje, pribežališče svoje imam v Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 8, 'Zaupajte vanj vsak čas, o ljudstvo; pred njim izlijte srce svoje: Bog nam je pribežališče. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 9, 'Le ničevost so preprosti ljudje, laž pa odlični možje; na tehtnico vkup položeni, poskočili bi nad ničevost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 10, 'Ne upajte v odiranje in plen naj vas ne dela ničemurnih; ako se množi bogastvo, ne navezujte nanje srca!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 11, 'Enkrat je govoril Bog, dvakrat sem slišal: da Božja je moč');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 62, 12, 'in tvoja, o Gospod, milost – zakaj ti povrneš vsakemu po delu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 1, '{Psalm Davidov, ko je bil v puščavi Judovi.} O Bog, Bog mogočni moj si ti, zgodaj te iščem; po tebi žeja dušo mojo, po tebi hrepeni meso moje v deželi suhi in pusti, kjer ni vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 2, 'Tako sem te gledal v svetem kraju, da bi videl tvojo moč in slavo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 3, 'Kajti boljša je milost tvoja od življenja; hvalijo naj te ustne moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 4, 'Tako te bom slavil, dokler bodem živ, v imenu tvojem bom povzdigaval roke svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 5, 'Kakor mozga in tolšče se nasiti duša moja, in z blagoglasnimi ustnami te bodo hvalila usta moja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 6, 'ko se spominjam tebe na ležišču svojem, vse nočne straže so misli moje pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 7, 'Kajti bil si mi velika pomoč, zato bom radostno prepeval v senci peruti tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 8, 'Duša moja se tebe drži in gre za teboj, ko me podpira desnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 9, 'Ali oni, ki preže na pogubo duše moje, pojdejo v najspodnje kraje zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 10, 'Izročeni bodo oblasti meča, lisicam bodo v delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 63, 11, 'Toda kralj se bo radoval v Bogu, ponašal se bo, kdorkoli priseza pri njem; kajti zamašila se bodo usta laž govorečim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 1, '{Načelniku godbe. Psalm Davidov.} Čuj, o Bog, glas moj, ko žalujem, strahu sovražnikovega varuj življenje moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 2, 'Skrivaj me skrivnemu naklepu hudobnih, hrumeči množici njih, ki delajo krivico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 3, 'ki so nabrusili kakor meč jezik svoj, namerili pšico – grenko besedo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 4, 'da ustrele iz zakotja nedolžnega; nenadoma streljajo vanj in se nič ne boje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 5, 'Potrjujejo si hudobni dogovor, pogovarjajo se, kako naj skrijejo zanke, pravijo: Kdo bi jih videl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 6, 'Izmišljajo si hudobije: Dognali smo, pravijo, zvit naklep! In notranje mišljenje vsakega in srce je pregloboko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 7, 'Ali Bog ustreli vanje, naglo prileti pšica, hipoma bodo ranjeni');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 8, 'in pasti morajo; naklep njih jezika pride nadnje; kdorkoli jih bo videl, bo majal z glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 9, 'In vsi ljudje se bodo bali in oznanjali delo Božje in premišljevali dejanje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 64, 10, 'Veselil se bo pravični v Gospodu in upal vanj, in hvalili se bodo vsi, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 1, '{Načelniku godbe. Psalm Davidov, pesem.} Tebi velja molčanje in hvala, o Bog na Sionu, in tebi se opravljajo obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 2, 'K tebi, ki poslušaš molitev, prihaja vse meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 3, 'Krivičnosti so me preveč obtežile; prestopke naše ti nam odpustiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 4, 'Blagor mu, kogar izvoliš in pripuščaš, da se ti bliža, da prebiva v vežah tvojih! Nasitimo se z dobroto hiše tvoje, s svetimi rečmi tvojega svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 5, 'S strašnimi rečmi nam odgovarjaš v pravičnosti, o Bog zveličanja našega, upanje vseh krajev zemlje in najdaljnejših morij!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 6, 'Ki gore utrjaš v kreposti svoji, z močjo opasan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 7, 'Ki miriš šum morja, šum valov njegovih in narodov hrum;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 8, 'tako da se bojé prebivalci najdaljnejših krajev znamenj tvojih; delaš, da se veselé, kjer je jutra svit in večera mrak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 9, 'Ti si obiskal zemljo in ji dal obilost, močno jo obogatil. Potok Božji je napolnjen z vodami. Pripravljaš jim žito, ko si jo tako obdelal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 10, 'napojil njene brazde in ji razmočil njene grude; z deževjem si jo zrahljal, kal njeno blagoslovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 11, 'Venčal si leto dobrote svoje, in sledovi tvoji kapljajo maščobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 12, 'Kapljajo i trate v puščavi, in griči so kakor opasani z radostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 65, 13, 'Pašniki so vsi polni čred in doline so pogrnjene z obilim žitom. Vse veselo uka in poje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 1, '{Načelniku godbe. Pesem in psalm.} Ukajte Bogu po vsej zemlji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 2, 'S strunami pojte o slavi njegovega imena, slavo pridevajte hvali njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 3, 'Govorite Bogu: Kako strašna so dela tvoja! Zavoljo velike moči tvoje se ti z laskanjem vdajajo sovražniki tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 4, 'Vsa zemlja se ti bo klanjala in ti psalme prepevala, vsi bodo pevali o tvojem imenu. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 5, 'Pridite in glejte velika dela Božja, strašen je v dejanju proti sinovom človeškim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 6, 'Morje je izpremenil v suho, prek velike reke so šli peš; tam smo se radovali v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 7, 'Z močjo svojo gospoduje vekomaj, oči njegove opazujejo narode; kateri so uporni, naj se ne povišujejo pri sebi! (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 8, 'Slavite, ljudstva, našega Boga in glas hvale njegove naj se razlega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 9, 'Ki je dušo našo postavil v življenje in ni pripustil, da omahnejo noge naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 10, 'Kajti izkušal si nas, o Bog, z ognjem si nas izčistil, kakor se čisti srebro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 11, 'Peljal si nas v mrežo, del si nam težko breme na ledja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 12, 'Storil si, da so jezdili ljudje čez glavo našo, šli smo skozi ogenj in skozi vodo; a slednjič si nas pripeljal v obilo blaginjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 13, 'Z žgalnimi darovi pojdem v hišo tvojo in ti opravim svoje obljube,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 14, 'ki so jih izrekle ustne moje in govorila usta moja v stiski moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 15, 'Žgalne daritve pitanih ovác ti prinesem in kadilo ovnov, daroval bom vole s kozliči vred. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 16, 'Pridite, poslušajte vsi, ki se bojite Boga, da povem, kaj je storil duši moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 17, 'K njemu sem klical s svojimi usti in hvalnica mi je bila na jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 18, 'Ako bi se bil namenil v hudobnost v svojem srcu, Gospod bi ne bil slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 19, 'Ali slišal je Bog, ozrl se je v prošnje moje glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 66, 20, 'Slavljen bodi Bog, ki ni zavrgel prošnje moje in mi ni odtegnil milosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 1, '{Načelniku godbe, na strune. Psalm in pesem.} Bog nam bodi milosten in blagoslovi nas, razsvetli naj obličje svoje proti nam, (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 2, 'da se spozna na zemlji pot tvoja, med vsemi narodi zveličanje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 3, 'Slavé te naj ljudstva, o Bog, slavé naj te ljudstva vsa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 4, 'Veselé se naj in glasno pojo narodi, ker boš pravično sodil ljudstva in vodil narode na zemlji. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 5, 'Slavé te naj ljudstva, o Bog, slavé te naj ljudstva vsa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 6, 'Zemlja daje sad svoj; blagoslovil nas bo Bog, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 67, 7, 'Blagoslovil nas bo Bog, in bali se ga bodo vse meje zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 1, '{Načelniku godbe. Davidov psalm in pesem.} Da vstane Bog! razkropé se naj neprijatelji njegovi in sovražilci njegovi naj bežé pred njegovim obličjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 2, 'Kakor bi puhnil dim, jih puhneš; kakor se staja vosek pri ognju, izginejo naj brezbožni izpred Božjega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 3, 'Pravični pa naj se veselé, poskakujejo pred Bogom in se veselé v radosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 4, 'Pojte Bogu, prepevajte psalme njegovemu imenu, pripravite pot njemu, ki se pelje po puščavah, Gospod mu je ime, in radujte se pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 5, 'Oče je sirotam in sodnik vdovam Bog v prebivališču svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 6, 'Bog množi samotarje v rodovine, pelje vklenjene iz spon v blaginjo; uporniki pa prebivajo v kraju presuhem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 7, 'O Bog, ko si šel na čelu ljudstva svojega, ko si stopal po puščavi (Sela),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 8, 'tresla se je zemlja, tudi nebesa so se rosila od pričujočnosti Božje, pa tisti Sinaj je trepetal od pričujočnosti Boga, Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 9, 'Dež preobilen si rosil, o Bog; dediščino svojo, ko je hirala, si oživljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 10, 'Krdelo tvoje je prebivalo v njej; ti si jo pripravil po dobroti svoji siromaku, o Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 11, 'Gospod dá besedo, in njih, ki naj bi blagovest oznanjale, bo velika množica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 12, 'Kralji vojnih krdel zbežé, zbežé, in ona, ki biva doma, bo delila plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 13, 'Ko boste ležali med ograjami, bodete podobni perutim goloba, ki so prevlečene s srebrom in njega perje z zelenorumenim zlatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 14, 'Ko Vsemogočni razkropi kralje v tej deželi, bode svetlo, kakor da je Zalmon s snegom posut.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 15, 'Gora Božja je gora Basánska, vrhovata gora je gora Basanska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 16, 'Zakaj gledate nevoščljivo, gore vrhovate, na goro, ki si jo je Bog želel za svoj sedež? Gospod tudi bo prebival tu vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 17, 'Voz Božjih je dvakrat deset tisoč, tisoč krat tisoč; Gospod je med njimi, kakor na Sinaju, v svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 18, 'Šel si gori v višavo, ujeto si peljal ujetnikov množico, prejel si darove med ljudmi, celo od upornikov, da prebiva med njimi Gospod, Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 19, 'Slavljen bodi Gospod! dan za dnevom nosi breme naše; on, Bog mogočni, je naše zveličanje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 20, 'On, Bog mogočni, je nam Bog za vsaktero pomoč, in pri Jehovi, Gospodu, je rešitev tudi iz smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 21, 'Gotovo, Bog razbije glavo sovražnikov svojih, teme lasato njega, ki hodi neprestano v krivicah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 22, 'Rekel je bil Gospod: Iz Basana pripeljem nazaj, nazaj jih pripeljem iz globočin morja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 23, 'da pomočiš nogo svojo v kri in jezik psov tvojih delež svoj ima na sovražnikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 24, 'Videli so svečanostni izprevod tvoj, o Bog, svečanostni izprevod Boga mojega, kralja mojega, v svetišče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 25, 'spredaj so šli pevci, potem godci na strune sredi deklic, ki so bile na bobnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 26, 'V zborih slavíte Boga, Gospoda, kateri ste iz vira Izraelovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 27, 'Tam je Benjamin, najmlajši, njih gospodar, knezi Judovi in njih krdelo, knezi Zabulonovi, knezi Neftalijevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 28, 'Bog tvoj je zapovedal, da bodi moč tvoja. Ohrani v moči, o Bog, kar si učinil za nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 29, 'Zaradi templja tvojega v Jeruzalemu ti prineso kralji darila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 30, 'Zagrozi zverini v trstju, čredi juncev s teleti ljudstev; vsak se ti podvrže s kosovi srebra. Razkropi ljudstva, ki jih vojske veselé!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 31, 'Pridejo velikaši iz Egipta, Etiopija hitro iztegne roke svoje proti Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 32, 'Kraljestva zemlje, pojte Bogu, psalme prepevajte Gospodu, (Sela)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 33, 'njemu, ki se pelje po nebesih nebes, ki so od starodavna; glej, glas svoj daje slišati, glas krepak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 34, 'Dajajte moč Bogu! Veličastvo njegovo je nad Izraelom in moč njegova v višavah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 68, 35, 'Strašen si, Bog, iz svetišč svojih; Bog mogočni Izraelov daje moč in obilo sile svojemu ljudstvu. Proslavljen bodi Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 1, '{Načelniku godbe; kakor ‚Lilije‘. Psalm Davidov.} Reši me, o Bog, ker vode so mi prišle že do duše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 2, 'Pogrezam se v blato pregloboko, kjer ni tal pod nogo, zašel sem v globočino vodá, roj valov pritiska name.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 3, 'S kričanjem sem se utrudil, vnelo se je grlo moje, oči moje pešajo, ko čakam svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 4, 'Več jih je, nego glave moje las, ki me črté brez vzroka, močni so, ki me hočejo uničiti, sovražniki mi po krivici; česar nisem vzel, me silijo vrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 5, 'O Bog, ti poznaš nespamet mojo in prestopki moji ti niso skriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 6, 'Ne bodi jih spričo mene sram, ki tebe čakajo, o Gospod, Gospod nad vojskami; rdečica naj ne oblije zaradi mene njih, ki iščejo tebe, Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 7, 'Zakaj zavoljo tebe prenašam zasmehovanje, sramota je pokrila obličje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 8, 'Tujec sem postal bratom svojim in neznanec matere svoje sinovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 9, 'Kajti gorečnost za hišo tvojo me je razjedla, in zasmehovanje njih, ki tebe zasmehujejo, je zadelo mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 10, 'Ko sem jokal in s postom pokoril dušo svojo, bilo mi je le v zasmehovanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 11, 'Ko sem se oblačil v raševino, tedaj sem jim bil v pregovor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 12, 'O meni govoričijo, kateri posedajo pri vratih, za pesem pa sem njim, ki pijejo opojno pijačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 13, 'Jaz pa – prošnja moja je do tebe, Gospod, ob času milosti. O Bog, po obilosti milosti svoje me usliši, po zveličalni resnici svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 14, 'Potegni me iz blata, da se ne pogreznem, otet naj bodem sovražilcev svojih in iz globočin vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 15, 'Valovje vodá naj me ne potopi in globočina naj me ne pogoltne, in jama naj ne zapre žrela svojega nad mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 16, 'Odgovóri mi, Gospod, ker dobra je milost tvoja, po obilosti usmiljenja svojega ozri se v me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 17, 'In ne skrivaj obličja svojega svojemu hlapcu, ker v stiski sem, hitro mi odgovóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 18, 'Približaj se duši moji, reši jo, zavoljo sovražnikov mojih me odkupi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 19, 'Ti poznaš zasramovanje moje in mojo sramoto ter nečast mojo, pred teboj so vsi sovražniki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 20, 'Sramotenje je potrlo srce moje in hudo sem bolan; in čakal sem, da bi me kdo miloval, pa ni bilo nikogar, čakal sem tolažiteljev, pa jih nisem dobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 21, 'Dá, za jed so mi dali žolča in v žeji moji so mi dali piti octa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 22, 'Njih miza bodi pred njimi za zanko in brezskrbno njih življenje za zadrgo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 23, 'Otemné naj njih oči, da ne vidijo, in daj, da ledja njih omahujejo neprestano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 24, 'Izlij nanje jezo svojo in srd tvoj naj jih dohiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 25, 'Pusto bodi njih bivališče, v šatorih njih ne bodi prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 26, 'Kajti preganjajo njega, ki si ga ti udaril, in spletajo pripovedke o bolečini prebodencev tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 27, 'Pridevaj krivico njih krivici, in ne dosežejo naj pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 28, 'Izbrišejo naj se iz življenja knjige, in s pravičnimi naj se ne zapišejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 29, 'Jaz pa sem ubožen in v bolečini; rešitev tvoja, o Bog, postavi me na varno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 30, 'Hvalil bom ime Božje s pesmijo in poveličeval ga z zahvaljevanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 31, 'To bode všeč Gospodu bolj nego vol, junec z rogovi in z razdeljenimi parklji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 32, 'Ko bodo to videli krotki, se bodo veselili; naj oživi srce vaše, ki iščete Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 33, 'Zakaj Gospod se ozira na potrebne in jetnikov svojih ne zameta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 34, 'Hvalijo naj ga nebesa in zemlja, morja in karkoli lazi po njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 35, 'Zakaj Bog dá rešitev Sionu in sezida mesta Judova, da bodo stanovali tam in podedovali deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 69, 36, 'In zarodi hlapcev njegovih jo bodo posedli, in kateri ljubijo ime njegovo, v njej prebivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 1, '{Načelniku godbe. Psalm Davidov, za spomin.} Bog, hiti me otet, Gospod, hiti mi na pomoč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 2, 'Osramoté se naj in z rdečico oblijo, kateri mi strežejo po življenju; umaknejo se naj in v nečast pridejo, ki se veselé nesreče moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 3, 'Nazaj naj zbežé v plačilo sramote svoje, kateri govoré: Aha, aha!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 4, 'Veselé se naj in radujejo v tebi vsi, ki te iščejo, in kateri ljubijo rešenje tvoje, govoré naj vedno: Poveličan bodi Bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 70, 5, 'Jaz pa sem ubožen in potreben; o Bog, hiti k meni! Pomoč moja in rešitelj moj si ti, o Gospod, ne odlašaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 1, 'K tebi, Gospod, zaupno pribegam, sram me ne bodi nikdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 2, 'Po pravičnosti svoji me otmi in oprosti, nagni k meni uho svoje in reši me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 3, 'Bodi mi skala prebivališča, kamor naj se vedno umikam; zapoved si dal, da bodem rešen, ker skala moja in trdnjava moja si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 4, 'Bog moj, reši me iz roke brezbožnika, iz pesti krivičneža in nasilnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 5, 'Zakaj ti si nada moja, Gospod Jehova, upanje moje od moje mladosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 6, 'Nate sem se opiral od rojstva, od osrčja matere moje si me odtrgal ti; tebi vedno velja hvalospev moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 7, 'Kakor čudo sem bil mnogim, toda ti si moje pribežališče trdno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 8, 'Usta moja bodo polna hvale tvoje, ves dan slave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 9, 'Ne zavrzi me ob starosti času, ko peša krepkost moja, ne zapusti me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 10, 'Kajti sovražniki moji govoré o meni, in oni, ki prežé na dušo mojo, se posvetujejo vkup,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 11, 'govoreč: Bog ga je zapustil, podite in zgrabite ga, ker nikogar ni, ki bi ga rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 12, 'Bog, ne bivaj daleč od mene, Bog moj, na pomoč mi hiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 13, 'Osramoté se naj in poginejo nasprotniki duše moje, pokrijejo naj se z nečastjo in sramoto, kateri iščejo hudega meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 14, 'Jaz pa bom stanovitno čakal in vedno bolj te hvalil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 15, 'Usta moja hočejo oznanjati pravičnost tvojo, ves dan zveličalno pomoč tvojo, ker ne znam števil njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 16, 'Pridem opevat mogočna dela Gospoda Jehove, s hvalo bom oznanjal pravičnost tvojo, samega tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 17, 'Bog, učil si me od mladosti, in še do sedaj oznanjam čuda tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 18, 'Zatorej tudi do starosti in do sivosti me ne zapusti, o Bog, da še oznanjam rame tvoje prihodnjemu rodu in moč tvojo vsem, ki še pridejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 19, 'In pravičnost tvoja, o Bog, seza do nebes višave; kar si storil, je veliko; Bog, kdo je tebi enak?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 20, 'Ti, ki si nam dal izkusiti stiske velike in hude, nas zopet oživiš in nas zopet izvlečeš iz brezen zemlje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 21, 'velikost mojo pomnožiš in se obrneš, da me potolažiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 22, 'Tudi jaz te bom slavil s strunami in resnico tvojo, moj Bog; prepeval ti bodem s citrami, o svetnik Izraelov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 23, 'Glasno se bodo radovale ustne moje, ko ti bom prepeval psalme, in duša moja, ki si jo odrešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 71, 24, 'Tudi jezik moj bo oznanjal ves dan pravičnost tvojo, ker so osramočeni, ker so z rdečico obliti, ki iščejo hudega meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 1, '{Psalm Salomonov.} Bog, sodbe svoje daj kralju in pravičnost svojo sinu kraljevemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 2, 'Sodi naj ljudstvo tvoje pravično in uboge tvoje po pravici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 3, 'Mir naj ljudstvu gore rodé in griči, po pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 4, 'On oskrbi pravico ubožcem ljudstva, pomoč sinom siromakov, stiskalca pa zdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 5, 'Bali se te bodo, dokler bo svetilo solnce in dokler trajal mesec, od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 6, 'Pride kakor vlaga na pokošen travnik, kakor deževje, ki namaka zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 7, 'Pravični bode v cvetu ob času njegovem, in mirú bo obilost, dokler ne izgine luna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 8, 'In gospodoval bo od morja do morja in od velereke do mej zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 9, 'Pred njim se bodo klanjali prebivalci puščave, in sovražniki njegovi bodo lizali prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 10, 'Kralji tarsiški in kralji z otokov mu bodo nosili dari, kralji iz Sabe in Sebe mu prineso davek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 11, 'In molili ga bodo vsi kralji, vsi narodi mu bodo služili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 12, 'Kajti rešil bo siromaka, ki vpije na pomoč, in ubožca, ki mu ni pomočnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 13, 'Usmili se slabotnega in potrebnega ter duše potrebnih bo rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 14, 'Zatiranja in silovitosti oprosti njih dušo, ker draga je njih kri v očeh njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 15, 'In živel bo ubožec, in kralj mu bo dajal zlata sabejskega, in on bo prosil zanj neprestano, ves dan ga blagoslavljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 16, 'Preobilo bode žita v deželi, do vrhov gorá, šumel bo kakor Libanon sad njegov; in ljudstva bo zacvetlo po mestih kakor trave zemeljske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 17, 'Ime njegovo bode vekomaj; dokler bo trajalo solnce, bo poganjalo ime njegovo, in blagoslavljali se bodo v njem in ga blagrovali vsi narodi. —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 18, 'Slava Gospodu, Bogu, Bogu Izraelovemu, ki sam dela čuda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 19, 'In slava bodi slavnemu imenu njegovemu vekomaj, in slave njegove naj se napolni vsa zemlja! Amen in Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 72, 20, 'Konec molitev Davida, sina Jesejevega. Knjiga tretja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 1, '{Psalm Asafov.} Zares, dober je Bog Izraelu, njim, ki so čistega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 2, 'Jaz pa – malo da se niso spoteknile noge moje, skoraj nič, da niso izpoddrsnili koraki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 3, 'Zakaj zavidal sem prevzetnikom, ko sem gledal brezbožnih blagostanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 4, 'Ker ni ga trpljenja do njih smrti, poln zdravja je njih život.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 5, 'Njim se ni truditi kakor drugim smrtnikom, in kakor druge ljudi jih ne tepo nadloge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 6, 'Zato jim je ošabnost okrog vratu kot verižica, silovitost jih pokriva kakor obleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 7, 'Oči jim gledajo debele iz polti zalite, v domišljavosti srca prestopajo vse meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 8, 'Rogajo se in hudobno govoré o zatiranju, govoré kot vzvišeni nad vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 9, 'Proti nebu dvigajo usta in kar izreče njih jezik, mora veljati na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 10, 'Zato hiti za njimi njih ljudstvo, in njih nauke srkajo kot vodo obilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 11, 'In govoré: Kako naj Bog ve? Ali je pač kaj znanja pri Najvišjem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 12, 'Glejte! ti so brezbožni in, vsekdar živeč brez skrbi, kopičijo bogastvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 13, 'Res, zastonj sem čistil srce svoje in v nedolžnosti umival svoje roke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 14, 'ker sem bil vendarle tepen ves dan, in kazen me je iznova zadela vsako jutro. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 15, 'Ako bi bil jaz rekel: Govoril bom istotako, glej, nezvest bi bil rodu tvojih otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 16, 'Tedaj sem premišljal, da bi to razumel, a pretežavno je bilo očem mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 17, 'Dokler nisem stopil v svetišča Boga mogočnega in zagledal njih konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 18, 'Zares, na polzka tla si jih postavil, treščiš jih, da bodo v podrtine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 19, 'Kako so hipoma opustošeni, konec jih je, poginili so v grozah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 20, 'So kakor sanje, ko se je zbudil kdo; tako, Gospod, ko se zbudiš, uničiš njih podobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 21, 'Ko se mi je grenkobe polnilo srce in me je bodlo v ledicah mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 22, 'tedaj sem bil brezpameten in nisem vedel ničesar, kakor živina sem bil pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 23, 'A vendar sem vedno s teboj, ker si me prijel za desnico mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 24, 'Po svetu svojem me boš vodil in naposled sprejel v slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 25, 'Kdo bi mi bil v nebesih razen tebe? in če tebe imam, se ne veselim ničesar na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 26, 'Najsi peša meso moje in srce moje – skala srca mojega in delež moj je Bog vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 27, 'Ker glej, kateri so daleč od tebe, poginejo; pokončaš ga, kdorkoli se s prešeštvovanjem izneveri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 73, 28, 'Jaz pa – dobro mi je, da sem blizu Boga; v Gospoda Jehovo stavim pribežališče svoje, da oznanjam vsa dela tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 1, '{Nauk, Asafov.} Zakaj, o Bog, nas zametaš vedno? zakaj se kadi jeza tvoja zoper čredo paše tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 2, 'Spomni se občine svoje, ki si jo pridobil oddavnaj in odkupil za rod posesti svoje, gore Sionske, ki si na njej prebival!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 3, 'Prispej k podrtinam večnim! Vse zlo je storil sovražnik v svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 4, 'Rjuli so nasprotniki tvoji sredi zbirališča tvojega, postavili so svoja znamenja za znamenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 5, 'Bilo je videti, kakor da vsak dviga kvišku sekiro v goščavi gozdni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 6, 'In zdaj razbijajo rezbe njegove vse s sekirami in s kladivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 7, 'Zažgali so svetišče tvoje, do tal so oskrunili prebivališče tvojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 8, 'Rekli so v srcu svojem: Ugonobimo jih vse vkup! Požgali so vsa zbirališča Boga mogočnega v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 9, 'Znamenj naših ne vidimo, ni več proroka, in ni ga med nami, ki bi vedel, doklej –?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 10, 'Doklej, o Bog, bo zasramoval stiskalec, večno li bo zaničeval sovražnik ime tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 11, 'Zakaj odtezaš roko svojo in desnico svojo? Potegni jo iz nedrij svojih in naredi konec!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 12, 'Vendar pa je Bog kralj moj že od nekdaj, ki dela rešitve na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 13, 'Ti si razklal v moči svoji morje, razbil si zmajem glave na vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 14, 'Ti si raztreskal leviatanu glave, dal si ga za jed rodu, zverinam puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 15, 'Ti si odprl studenec in potok, ti si posušil reke neusahljive.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 16, 'Tvoj je dan, tvoja tudi noč, ti si napravil luč njeno in solnce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 17, 'Ti si določil vse meje zemlji, poletje in zimo napravil si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 18, 'Spomni se vendar, da je sovražnik sramotil Gospoda in da ljudstvo nespametno zaničuje ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 19, 'Ne daj tisti zveri duše grlice svoje, krdela ubožcev svojih ne zabi vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 20, 'Ozri se na zavezo, ker po kotih dežele je polno bivališč silovitosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 21, 'Ponižanec naj se ne vrne osramočen, ubožec in siromak naj hvalita ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 22, 'Vstani, o Bog; potegni se za pravdo svojo, spomni se zasramovanja, ki ti ga delajo nespametneži vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 74, 23, 'Ne pozabi glasu sovražnikov svojih, ropota vzpenjajočih se zoper tebe, ki se vedno vzdiguje kvišku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 1, '{Načelniku godbe; kakor ‚Ne pogubi!‘Psalm Asafov in pesem.} Slavimo te, o Bog, slavimo; ker blizu je ime tvoje, čuda tvoja se oznanjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 2, 'Zakaj „ko pride določeni čas, jaz bom sodil pravično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 3, 'Raztaja se zemlja in vsi prebivalci njeni – jaz sem utrdil stebre njene“. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 4, 'Govorim prevzetnikom: Nikar se ne ponašajte! in krivičnikom: Ne dvigajte rogov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 5, 'Ne dvigajte visoko rogov svojih, ne govorite drzno s trdim vratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 6, 'Zakaj ne od vzhoda, ne od zahoda, tudi ne od puščave ne pride povišanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 7, 'Marveč Bog je sodnik: tega poniža, onega poviša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 8, 'Kajti čaša je v roki Gospodovi in se peni od vina, polna je mešanice, in iz nje on naliva: še njeno goščo bodo srkajoč pili vsi krivičniki na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 9, 'Jaz pa bom oznanjal vekomaj, prepeval psalme Bogu Jakobovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 75, 10, 'In vse rogove polomim brezbožnikom; zvišajo pa se naj rogovi pravičnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 1, '{Načelniku godbe; na strune. Psalm Asafov in pesem.} Znan je v Judu Bog, v Izraelu je veliko ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 2, 'V Salemu je koča njegova in prebivališče njegovo na Sionu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 3, 'Tamkaj je strl ognjene pšice lokov, ščit in meč in vojsko. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 4, 'Svetel si ti, veličasten, bolj nego gore roparske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 5, 'Plen so postali srčni korenjaki, zaspali so v svoje spanje, in nobeden tistih junakov ni našel moči v rokah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 6, 'Od hudovanja tvojega, o Bog Jakobov, sta onemogla voz in konj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 7, 'Ti, ti si strašen, in kdo more stati pred teboj, kadar se jeziš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 8, 'Z neba si dal slišati sodbo, zemlja se je zbala in utihnila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 9, 'ko je na sodbo vstal Bog, da bi rešil vse krotke na zemlji. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 10, 'Res, srd človeški ti je v slavo, z zalogo obilega srda svojega se opašeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 11, 'Obetajte in izvršujte obljube Gospodu, Bogu svojemu; vsi, ki so okoli njega, naj mu prineso dari, strašnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 76, 12, 'Ki uničuje napuh prvakov, strašen je zemeljskim kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 1, '{Načelniku godbe; za Jedutuna. Psalm Asafov.} Z glasom svojim hočem vpiti k Bogu, z glasom svojim k Bogu, in nagne uho k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 2, 'Ob dnevi stiske svoje sem iskal Gospoda, roka moja je bila po noči proti nebu iztegnjena neprenehoma, duša moja se je branila pripustiti tolažbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 3, 'Spominjam se Boga in stokam, premišljam, in duh moj omaguje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 4, 'Ne daš mi zatisniti oči, izbegan sem tako, da govoriti ne morem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 5, 'Čase premišljujem starodavne, prejšnjih vekov leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 6, 'Spominjam se ponočne godbe svoje na strune, v srcu svojem premišljam in duh moj preiskuje, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 7, 'Ali bi na večne čase zametal Gospod, ali ne bode nikdar več milostiv?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 8, 'Je li pri kralju milost njegova za vselej? Je li konec obljubi njegovi od roda do roda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 9, 'Ali je pozabil Bog mogočni deliti milost, ali je pa v jezi zaprl usmiljenje svoje? (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 10, 'Nato si rečem: To je moja bolezen, leta trpljenja, namenjena mi od desnice Najvišjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 11, 'S hvalo bom spominjal dejanj Gospodovih, da, spominjal se bom vseh čudes tvojih od starodavnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 12, 'In premišljal bom vsaktero delo tvoje in o dejanjih tvojih bom razmišljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 13, 'O Bog, v svetosti je steza tvoja; kdo je velik Bog mogočni kakor Bog naš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 14, 'Ti si sam Bog mogočni, čudodelni, pokazal si moč svojo med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 15, 'Odrešil si s povzdignjeno roko ljudstvo svoje, sinove Jakobove in Jožefove. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 16, 'Videle so te vode, o Bog, videle so te vode in se tresle, da, potresla so se brezna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 17, 'Izlili so oblaki vode, glas so zagnali gornji oblaki, tudi pšice tvoje so švigale semtertja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 18, 'Bobnel je grom tvoj v viharju, bliski so razsvetljevali vesoljni svet, potresla se je zemlja in trepetala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 19, 'Skozi morje je šla pot tvoja in steza tvoja skozi široke vode, kjer sledovi tvoji niso znani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 77, 20, 'Vodil si kakor čredo ljudstvo svoje po Mojzesu in Aronu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 1, '{Pouk Asafov.} Poslušaj, ljudstvo moje, nauk moj, nagnite uho svoje govoru mojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 2, 'V prilikah odprem usta svoja, razglasim uganke iz starih časov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 3, 'Kar smo slišali in spoznali, kar so nam pripovedovali očetje naši,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 4, 'ne bomo prikrivali njih otrokom, pripovedujoč naslednjemu rodu preslavna dela Gospodova in moč njegovo in čuda njegova, ki jih je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 5, 'Kajti ustanovil je pričevanje v Jakobu in postavil zakon v Izraelu, kar je zapovedal očetom našim, da naj jih oznanjajo svojim otrokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 6, 'Da to spozna naslednji rod, otroci, ki bodo rojeni, in ti vstanejo ter pripovedujejo otrokom svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 7, 'Upanje svoje da naj stavijo na Boga in ne pozabijo naj dejanj Boga mogočnega, temuč hranijo naj zapovedi njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 8, 'In ne bodo naj kakor njih pradedje, rod trdovraten in uporen, rod, ki ni obrnil v pravo smer srca svojega in čigar duh ni bil zvest Bogu mogočnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 9, 'Sinovi Efraimovi, lokostrelci oboroženi, so obrnili hrbte ob času bitve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 10, 'Ohranili niso zaveze Božje in so se branili hoditi po zakonu njegovem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 11, 'pozabivši dejanja njegova in čudovita dela njegova, katera jim je bil pokazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 12, 'Delal je čuda pred njih pradedi v deželi Egiptovski, na polju Zoanskem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 13, 'Razklal je morje in peljal jih čez, in postavil je vode kakor jez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 14, 'In spremljal jih je z oblakom po dnevi in vso noč s svetlobo ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 15, 'Razklal je skale v puščavi in jih je obilo napojil kakor iz globočin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 16, 'Potoke je izpeljal iz skale in storil, da so vode tekle doli kakor reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 17, 'Vendar so še dalje grešili zoper njega, upirali se Najvišjemu v pustinji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 18, 'In izkušajoč Boga mogočnega v srcu svojem, so zahtevali jed po svojega srca želji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 19, 'In grdo govoreč zoper Boga, so rekli: Ali bi mogel Bog mogočni pripraviti mizo v tej puščavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 20, 'Glejte, ob skalo je udaril, da so tekle vode, in potoki so se udrli – ali bo mogel dati tudi kruha ali pa oskrbeti mesa ljudstvu svojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 21, 'Zato se je Gospod, ko je to slišal, razsrdil, in ogenj se je vnel zoper Jakoba in tudi jeza se je kadila zoper Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 22, 'Ker niso verovali v Boga in niso upali v rešenje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 23, 'In vendar je zapovedal oblakom zgoraj in odprl vrata nebeška,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 24, 'in dežil nanje mano za jed in jim dajal žito nebeško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 25, 'Kruh močnih je jedel človek; brašna jim je pošiljal dositega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 26, 'Zagnal je vzhodni veter na nebu in z močjo svojo je pripeljal jug,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 27, 'in je dežil nanje meso kakor prah in kakor morski pesek ptiče krilate,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 28, 'metal jih je med njih šatore, okoli njih prebivališč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 29, 'In jedli so in bili so zelo nasičeni, in česar so poželeli, jim je prinesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 30, 'Še se niso iznebili poželenja svojega, še jim je bila jed v ustih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 31, 'ko je jeza Božja vzplamtela proti njim in morila med močnimi izmed njih in pokončavala mladeniče Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 32, 'Ob vsem tem so še grešili in niso verovali v čudovita dela njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 33, 'Zato je storil, da so v ničevosti potekali njih dnevi in njih leta v naglici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 34, 'Ko jih je pobijal, tedaj so povpraševali po njem, in so se izpreobrnili ter zjutraj že iskali Boga mogočnega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 35, 'spomnivši se, da je bil Bog njih skala in Bog mogočni, Najvišji, njih odrešenik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 36, 'Tedaj so ga z usti svojimi dobrikali in z jezikom svojim so se mu lagali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 37, 'a njih srce ni bilo utrjeno pri njem in niso se izkazali zvesti zavezi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 38, 'Toda on je usmiljen, odpušča krivico in ne pokončuje; in mnogokrat je ustavil svoj srd in ni vnemal vse jeze svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 39, 'Spominjal se je namreč, da so meso, sapa, ki gre in se ne vrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 40, 'Kolikokrat so se mu uprli v puščavi, so ga žalili v samoti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 41, 'Zopet in zopet so izkušali Boga mogočnega in žalili Svetega Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 42, 'Niso se spominjali roke njegove, ne dne, ko jih je bil otel zatiralca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 43, 'ko je v Egiptu delal znamenja svoja in čuda svoja na polju Zoanskem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 44, 'V kri je izpremenil njih potoke, da niso mogli piti tekočih vod svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 45, 'Poslal je nanje pasje muhe, ki so jih žrle, in žabe, ki so jih ugonabljale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 46, 'In dal je njih sadež cvrčku, in kobilici, kar so s trudom posejali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 47, 'Uničil je s točo njih trte in smokve njih z mrazom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 48, 'Izročil je toči tudi njih živino in njih črede bliskom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 49, 'Izpustil je nanje jeze svoje žar, srd in nevoljo in stisko, celo krdelo angelov nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 50, 'Prosto pot je napravil svoji jezi, smrti ni ubranil njih duš in življenje njih je izročil kugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 51, 'In udaril je vse prvorojence v Egiptu, prvino moči v šatorih Hamovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 52, 'Svoje ljudstvo pa je odpeljal kakor ovce, in vodil jih je kakor čredo po puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 53, 'In peljal jih je varno, da se jim ni bilo bati, a njih sovražnike je pokrilo morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 54, 'Pripeljal jih je do meje svetišča svojega, gore te, ki si jo je pridobila desnica njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 55, 'Izgnal je izpred njih obličja narode in jih je po žrebu razmeril Izraelu v posest in v njih šatorih je dal prebivati Izraelovim rodovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 56, 'Vendar so izkušali Boga Najvišjega in se mu upirali in pričevanj njegovih se niso držali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 57, 'Temuč obrnili so se in nezvesto ravnali kakor njih pradedje, obrnili so se kakor lok, ki strelja napačno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 58, 'Dražili so ga z višavami svojimi in s podobami malikov svojih so razvneli gorečnost njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 59, 'Slišal je Bog in se razsrdil, in Izrael se mu je silno zastudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 60, 'In zapustil je prebivališče v Silu, šator, ki ga je bil postavil med ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 61, 'In dal je v sužnost svojo moč in slavo svojo zatiralcu v pest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 62, 'Izročil je meču ljudstvo svoje in zoper dedino svojo se je razsrdil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 63, 'Ogenj je požrl mladeniče njegove, in devicam njegovim se ni pela svatovska pesem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 64, 'Duhovniki njegovi so padli pod mečem, in vdove njegove niso mogle žalovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 65, 'Tedaj se je zbudil Gospod, kakor da bi bil spal, kakor junak, ki vriska od vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 66, 'In udaril je sovražnike svoje od zadaj, sramoto večno jim je naložil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 67, 'Zavrgel je pa šator Jožefov in rodu Efraimovega ni izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 68, 'Temuč izvolil je rod Judov, goro Sionsko, ki jo je ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 69, 'In sezidal si je enako nebeškim višavam svetišče svoje, enako zemlji, ki jo je utrdil na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 70, 'In izvolil je Davida, hlapca svojega, vzemši ga iz ovčje ograje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 71, 'izza doječih ga je pripeljal, da bi pasel Jakoba, ljudstvo njegovo, in Izraela, dediščino njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 78, 72, 'Ki jih je pasel po poštenosti srca svojega in vodil jih je z obilo razsodnostjo svojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 1, '{Psalm Asafov.} O Bog, pridrli so pogani v dediščino tvojo, oskrunili so hram svetosti tvoje, v groblje so izpremenili Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 2, 'Dali so hlapcev tvojih trupla ptičem nebeškim, meso svetnikov tvojih zverinam zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 3, 'Prelivali so njih kri kakor vodo okrog Jeruzalema, in ni ga bilo, ki bi jih pokopaval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 4, 'V zasramovanje smo sosedom svojim, v zasmehovanje in norčevanje njim, ki so okoli nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 5, 'Doklej, Gospod, boš li se jezil večno? Bo li gorela kakor ogenj gorečnost tvoja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 6, 'Izlij srd svoj na pogane, ki te ne spoznavajo, in na kraljestva, ki ne kličejo tvojega imena!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 7, 'Kajti pojedli so Jakoba in razdejali so prebivališče njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 8, 'Ne spominjaj se krivic prednikov naših zoper nas, brzo naj nam pride naproti usmiljenje tvoje, ker obubožali smo silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 9, 'Pomagaj nam, Bog zveličanja našega, zavoljo časti svojega imena, in reši nas ter prikrij grehe naše zaradi svojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 10, 'Zakaj naj bi govorili pogani: Kje je njih Bog? Znano bodi med pogani pred našimi očmi maščevanje prelite krvi hlapcev tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 11, 'Pred obličje tvoje naj pride zdihovanje jetnikov, po velikosti moči svoje ohrani v življenju, katere že izročajo smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 12, 'In povrni sosedom našim sedemkrat v njih naročje sramoto, s katero so te zasramovali, o Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 79, 13, 'Mi pa, ljudstvo tvoje in čreda paše tvoje, te bomo slavili večno; od roda do roda bomo oznanjali hvalo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 1, '{Načelniku godbe; kakor ‚Lilije‘. Pričevanje. Psalm Asafov.} O pastir Izraelov, poslušaj, ki vodiš Jožefa kakor čredo, ki stoluješ nad kerubi, pokaži se v svetlobi svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 2, 'Pred Efraimom, Benjaminom in Manasejem zbudi moč svojo ter pridi nam v rešitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 3, 'O Bog, postavi nas v prejšnji stan, razjasni obličje svoje, in rešeni bomo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 4, 'Gospod, Bog nad vojskami, doklej se bode kadila jeza tvoja ob molitvi tvojega ljudstva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 5, 'Pasel si jih s solznim kruhom in piti si jim dal solz obilo mero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 6, 'Postavil si nas za prepir sosedom našim, in sovražniki se nam smejejo med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 7, 'O Bog nad vojskami, postavi nas v prejšnji stan, razjasni obličje svoje, in rešeni bomo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 8, 'Trto si bil prestavil iz Egipta, pregnal si narode, da bi jo zasadil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 9, 'Pripravil si prostor pred njo, da se je ukoreninila in prerasla deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 10, 'Senca njena je pokrivala gore in njene veje cedre največje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 11, 'Iztezala je mladike svoje do morja in proti reki rozge svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 12, 'Zakaj si podrl ograje njene, da jo obirajo vsi mimohodeči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 13, 'Razriva jo merjasec iz gozda in divjačina poljska jo objeda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 14, 'O Bog nad vojskami, povrni se, prosimo, ozri se iz nebes ter glej, in skrbi za to trto');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 15, 'in ohrani, kar je bila vsadila desnica tvoja, in sina, ki si ga močnega storil sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 16, 'Požgana je z ognjem, odrezana; od hudovanja obličja tvojega vsi ginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 17, 'Roka tvoja bodi nad možem desnice tvoje, nad sinom človeka, ki si ga močnega storil sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 18, 'In ne umaknemo se od tebe; oživi nas zopet, in klicali bomo ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 80, 19, 'Gospod, Bog nad vojskami, postavi nas v prejšnji stan, razjasni obličje svoje, in rešeni bomo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 1, '{Načelniku godbe; na gitit. Psalm Asafov.} Pojte glasno Bogu, moči naši, ukajte Bogu Jakobovemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 2, 'Zapojte hvalnice in udarite na boben, na citre milozvočne in brenklje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 3, 'Zatrobite ob mlaju na rog, ob ščipu, v dan praznika našega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 4, 'Ker postava je to za Izraela, naredba Boga Jakobovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 5, 'ki je to za pričevanje postavil v Jožefu, ko je šel proti deželi Egiptovski, kjer sem slišal govor neznan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 6, 'Odtegnil sem izpod bremena ramo njegovo, roke njegove sem oprostil tovorne košare.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 7, 'Ko si vpil v oni stiski, sem te rešil; odgovoril sem ti izza ogrinjala groma, izkušal sem te pri vodi Meribski. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 8, 'Čuj, ljudstvo moje, in izpričeval ti bom; o Izrael, da bi me poslušal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 9, 'Ne bodi v tebi boga tujega, nikar se ne klanjaj bogu inostrancev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 10, 'Jaz sem Gospod, Bog tvoj, ki sem te izpeljal iz dežele Egiptovske: odpri široko usta svoja, in jaz jih napolnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 11, 'Ali ljudstvo moje ni poslušalo glasu mojega in Izrael mi ni bil pokoren.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 12, 'Zatorej sem jih pustil, naj hodijo po srca svojega zakrknjenosti, in hodili so po krivih naklepih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 13, 'O, ko bi me bilo poslušalo ljudstvo moje, ko bi bil Izrael hodil po mojih potih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 14, 'Kar mahoma bi bil potlačil njih sovražnike in zoper njih zatiralce bi bil obrnil roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 15, 'Sovražilci Gospodovi bi se mu bili vdajali z laskanjem, in njegov čas bi bil trajal večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 81, 16, 'In živil bi ga bil s pšenico najboljšo in z medom iz skalovja bi te bil sitil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 1, '{Psalm Asafov.} Bog stoji v zboru Božjem, sodi sredi bogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 2, 'Doklej boste sodili krivično in se ozirali na brezbožnih zunajnost? (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 3, 'Potegujte se za pravdo ubožca in sirote, nesrečnemu in siromaku pomagajte do pravice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 4, 'Oprostite ubogega in potrebnega, iz roke krivičnih ga rešite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 5, 'A ne vedo in ne umejo ničesar, v temi hodijo neprestano: majó se vse podstave dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 6, 'Jaz sem rekel: Bogovi ste in Najvišjega sinovi vi vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 7, 'Toda umrjete kakor navaden človek in padete kakor kdorkoli izmed poglavarjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 82, 8, 'Vstani, o Bog, sodi zemljo; zakaj ti dobiš vse narode v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 1, '{Pesem in psalm Asafov.} O Bog, ne molči, ne delaj se gluhega in ne miruj, o Bog mogočni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 2, 'Zakaj, glej, neprijatelji tvoji ropočejo in sovražilci tvoji dvigajo glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 3, 'Zoper ljudstvo tvoje kujejo prekanjene naklepe in posvetujejo se zoper varovance tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 4, 'Govoré: Pridite, in potrebimo jih, da ne bodo narod, da se nihče ne spominja več imena Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 5, 'Kajti naklep so storili v srcu enih misli; zoper tebe so sklenili zavezo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 6, 'šatori Edomovi in Izmaelci, Moab in Hagarenci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 7, 'Gebal in Amon in Amalek, Filisteja s Tira prebivalci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 8, 'tudi Asirec se jim je pridružil v pomoč so bili sinovom Lotovim. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 9, 'Stóri jim kakor Madiancem, kakor Siseru, kakor Jabinu ob potoku Kisonu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 10, 'ki so bili pokončani pri Endoru, postali so zemlje gnoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 11, 'Naredi njih plemenitnike kakor Oreba in kakor Zeba, kakor Zebaha in Zalmuna vse njih poglavarje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 12, 'Ker so rekli: Vzemimo si v last prebivališča Božja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 13, 'Bog moj, naredi jih kakor prah v vrtincu, kakor pleve pred vetrom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 14, 'Kakor ogenj požiga gozd in kakor plamen, ki popali gore,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 15, 'tako jih podi z viharjem svojim in z vrtincem svojim jih preplaši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 16, 'S sramoto napolni njih obličje, da bodo iskali ime tvoje, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 17, 'Rdečica naj jih oblije in izbegajo naj se za ves čas, sramujejo se naj in poginejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 83, 18, 'da spoznajo, da si ti, ki ti je ime Jehova, sam Najvišji nad vesoljno zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 1, '{Načelniku godbe; na gitit. Sinov Korahovih psalm.} Kako ljuba so prebivališča tvoja, o Gospod nad vojskami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 2, 'Duša moja hrepeni in koprni po vežah Gospodovih, srce moje in meso moje radostno kličeta v hrepenenju po živem Bogu mogočnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 3, 'Saj vrabec je našel dom in lastovka si gnezdo, kamor položi mladiče svoje – oltarje tvoje, o Gospod nad vojskami, kralj moj in Bog moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 4, 'Blagor jim, ki prebivajo v hiši tvoji, vedno te bodo hvalili. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 5, 'Blagor človeku, čigar moč je v tebi: njim so v srcu pripravljene poti na Sion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 6, 'Gredé po Solzni dolini, si jo obračajo v kraj studencev; saj tudi rani dež jo pokriva z blagoslovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 7, 'Gredo od kreposti do kreposti, vsak njih se prikaže pred Bogom na Sionu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 8, 'Gospod, Bog nad vojskami, čuj molitev mojo, poslušaj, o Bog Jakobov. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 9, 'Poglej, o Bog, ki si ščit naš, in glej maziljenca svojega obličje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 10, 'Kajti boljši je en dan v vežah tvojih nego tisoč drugje; rajši hočem stati ob pragu v hiši Boga svojega nego prebivati v brezbožnosti šatorih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 11, 'Zakaj solnce in ščit je Gospod, Bog, milost in slavo daje Gospod, dobrega ne krati njim, ki hodijo v popolnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 84, 12, 'Gospod nad vojskami, blagor človeku, čigar upanje je v tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 1, '{Načelniku godbe. Psalm sinov Korahovih.} Blagovoljen si bil nekdaj, o Gospod, deželi svoji, nazaj si pripeljal iz sužnosti Jakoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 2, 'Odpustil si krivico ljudstvu svojemu, pokril si ves njih greh. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 3, 'Umaknil si ves srd svoj, odvrnil si se od jeze svoje, da ni kipela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 4, 'Postavi nas v prejšnji stan, o Bog zveličanja našega, in potolaži nevoljo svojo proti nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 5, 'Ali se boš večno jezil nad nami, raztezal jezo svojo od roda do roda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 6, 'Ali nas zopet ne postaviš v življenje, da se ljudstvo tvoje raduje v tebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 7, 'Pokaži nam, Gospod, milost svojo, in daj nam zveličanje svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 8, 'Pa poslušal bom, kaj govori Bog mogočni, Gospod. Da, mir govori ljudstvu svojemu in svetnikom svojim, samo v nespamet naj se ne povrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 9, 'Res, blizu je njim, ki se njega bojé, zveličanje njegovo, da bi zopet slava prebivala v deželi naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 10, 'Milost in resnica se bosta srečavala, pravičnost in mir se poljubita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 11, 'Zvestoba požene iz zemlje, in pravičnost bo gledala iz nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 12, 'Gospod bo tudi dal, kar je dobro, in zemlja naša obrodi svoj sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 85, 13, 'Pravičnost bo pred njim hodila in nas postavila na pot stopinj njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 1, '{Molitev Davidova.} Nagni, Gospod, uho svoje in usliši me, ker siromak sem in ubožen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 2, 'Ohrani dušo mojo, ker tisti sem, ki mu deliš milost; reši hlapca svojega, ti Bog moj, ki ima upanje v tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 3, 'Milost mi izkaži, Gospod, ker k tebi kličem ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 4, 'Razveseli dušo svojega hlapca, ker do tebe, Gospod, povzdigujem dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 5, 'Saj ti si, Gospod, dobrotljiv in rad prizanašaš, in obilen si v milosti vsem, ki te kličejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 6, 'Čuj molitev mojo, o Gospod, in poslušaj prošenj mojih glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 7, 'V dan stiske svoje te kličem, ker me uslišiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 8, 'Ni ti enakega med bogovi, o Gospod, in del ni tvojim enakih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 9, 'Vsi narodi, kar si jih ustvaril, pridejo in klanjali se bodo pred teboj, o Gospod, in čast dado tvojemu imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 10, 'Zakaj ti si velik in delaš čuda, ti sam si Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 11, 'Uči me, Gospod, pot svojo, in hodil bom v resnici tvoji; zberi srce moje, da se bo balo tvojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 12, 'Slavil te bom, Gospod, Bog moj, iz vsega srca svojega, in poveličeval bom ime tvoje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 13, 'Ker velika je milost tvoja do mene, in rešil si dušo mojo, da ni šla v najglobočji pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 14, 'O Bog, prevzetniki so se vzdignili zoper mene in silovitnikov krdelo preži po življenju mojem, in tebe si niso predstavili pred oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 15, 'Ti pa, Gospod, Bog mogočni, usmiljen si in milosten, počasen v jezo in obilen v milosti in resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 16, 'Ozri se v me in stori mi milost; daj moč svojo hlapcu svojemu in reši dekle svoje sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 86, 17, 'Stóri mi znamenje v dobro, da vidijo sovražilci moji in se s sramoto oblijo, ker si mi ti, Gospod, pomagal in me potolažil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 1, '{Sinov Korahovih psalm in pesem.} Ustanovitev svojo na svetih gorah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 2, 'vrata sionska ljubi Gospod bolj ko vsa prebivališča Jakobova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 3, 'Prečastno je, kar se govori o tebi, o mesto Božje. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 4, '„Imenoval bom Egipt in Babilon med njimi, ki me poznajo; glej, Filisteja in Tir z Etiopijo – ta je rojen ravno tam.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 5, 'Zato se bode govorilo o Sionu: Ta in oni je rojen v njem, in on, Najvišji, ga utrdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 6, 'Gospod bo našteval, popisujoč narode: Ta je rojen ravno tam. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 87, 7, 'In pevaje in plešoč, poreko: Vsi studenci moji so v tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 1, '{Pesem in psalm sinov Korahovih. Načelniku godbe; na mahalat leanot. Pouk Hemana Ezrahovca.} O Gospod, Bog zveličanja mojega, po dnevi kličem in po noči pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 2, 'Pred obličje tvoje pridi molitev moja, nagni uho svoje k mojemu vpitju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 3, 'Kajti nasičena je z nadlogami duša moja in življenje moje je dospelo do kraja mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 4, 'Štejejo me med tiste, ki se pogrezajo v jamo; podoben sem možu, ki mu je minila življenja moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 5, 'Med mrtvimi sem zapuščen kakor pobiti, ležeči v grobu, ki se jih ne spominjaš več, ker so ločeni od tvoje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 6, 'Položil si me v jamo najglobočjo, v kraje temne, v globočine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 7, 'Trdo me tlači jeza tvoja in vse valove svoje zaganjaš v me. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 8, 'Oddalil si od mene znance moje, storil si me njim v najhujšo gnusobo; zajet sem, in pobegniti ne morem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 9, 'Oko moje mrli od bede; kličem te, Gospod, vsak dan, k tebi razpenjam roke svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 10, 'Boš li na mrtvih delal čudeže? Ali mrtvi vstajajo, da bi te slavili? (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 11, 'Ali naj bi se v grobu oznanjala milost tvoja, zvestoba tvoja v kraju pogube?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 12, 'Ali se mar v temini spoznajo čuda tvoja in pravičnost tvoja v pozabljenja deželi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 13, 'Jaz pa vpijem, Gospod, k tebi, že zjutraj ti hiti naproti molitev moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 14, 'Zakaj zametaš dušo mojo, o Gospod, skrivaš mi obličje svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 15, 'Siromak sem in blizu smrti od mladosti svoje, strahove tvoje prenašam in sem izbegan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 16, 'Jeze tvoje žar gre čezme, strahote tvoje me uničujejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 17, 'obdajajo me kakor vode ves dan, obstopajo me vse skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 88, 18, 'Oddalil si od mene prijatelja in tovariša, temine so mi znanci edini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 1, '{Pouk Etana Ezrahovca.} O milostih Gospodovih bom peval vekomaj, rodu za rodom bom oznanjal z usti svojimi zvestobo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 2, 'Rekel sem namreč: Vekomaj se bo milost sezidavala, v samih nebesih utrdiš zvestobo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 3, '„Sklenil sem zavezo z izvoljencem svojim, prisegel sem Davidu, svojemu hlapcu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 4, 'Na vekomaj utrdim seme tvoje in stavil bom prestol tvoj od roda do roda.“(Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 5, 'Zato slavé nebesa čudovito delo tvoje, o Gospod, tudi zvestobo tvojo v zboru svetnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 6, 'Zakaj kdo naj se v nebeških višavah primerja Gospodu, kdo je Gospodu podoben med sinovi Božjimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 7, 'On je Bog mogočni, jako strašen v zboru svetnikov in strašnejši mimo vseh, ki so okrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 8, 'O Gospod, Bog nad vojskami, kdo je tebi enako mogočen, Gospod? In zvestoba tvoja biva okrog tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 9, 'Ti gospoduješ nad morja divjostjo; ko se vzpenjajo valovi njegovi, ti jih krotiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 10, 'Zdrobil si Egipt, da je kakor strt, z ramo svoje moči si razkropil sovražnike svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 11, 'Tvoja so nebesa, tvoja tudi zemlja; vesoljni svet in česar je poln, ustanovil si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 12, 'Sever in jug, ti si ju ustvaril; Tabor in Hermon veselo pojeta o imenu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 13, 'Velemožna je rama tvoja, krepka je roka tvoja, vzvišena desnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 14, 'Pravičnost in prava sodba sta podstava tvojemu prestolu, milost in resnica hodita pred obličjem tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 15, 'Blagor ljudstvu, ki pozna trobente radostni glas! Ti hodijo v svetlobi obličja tvojega, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 16, 'V imenu tvojem se radujejo ves dan in po pravičnosti tvoji se povišujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 17, 'Zakaj dika njih moči si ti, in po blagovoljnosti tvoji bo zvišan rog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 18, 'Gospod namreč je naš ščit in Svetnik Izraelov naš kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 19, 'Nekdaj si v prikazni govoril svetnikom svojim in rekel: Pomoč sem podelil junaku, povzdignil sem izvoljenega iz ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 20, 'Našel sem Davida, hlapca svojega, pomazilil sem ga s svetim oljem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 21, 'Ž njim bodi roka moja stanovitna in rama moja naj ga krepča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 22, 'Ne bo ga stiskal sovražnik in sin krivice ga ne bo tlačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 23, 'Temuč starem izpred njega nasprotnike njegove in sovražilce njegove udarim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 24, 'In moja zvestoba in milost moja bo ž njim, in v imenu mojem se povzdigne rog njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 25, 'In nad morje položim roko njegovo in nad reke njegovo desnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 26, 'On me bo klical: Oče moj si ti, Bog moj mogočni in skala rešenja mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 27, 'Jaz pa ga postavim za prvorojenca, za najvišjega kraljem zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 28, 'Vekomaj mu ohranim milost svojo, in zaveza moja mu ostani zvesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 29, 'In postavim seme njegovo, da večno traja, in prestol njegov kakor dnevi nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 30, 'Ako zapusté sinovi njegovi zakon moj in ne bodo hodili v sodbah mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 31, 'ako oskrunijo postave moje in ne bodo ravnali po zapovedih mojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 32, 'obiščem s šibo njih pregreho in z udarci njih krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 33, 'Toda milosti svoje mu ne odtegnem in lagal ne bom zoper zvestobo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 34, 'Ne oskrunim zaveze svoje in ne izpremenim ustnic svojih obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 35, 'Enkrat sem prisegel pri svetosti svoji; zares, Davidu ne bom lagal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 36, 'Večno bodi seme njegovo in prestol njegov kakor solnce pred mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 37, 'Kakor luna bode stanoviten vekomaj. In priča v nebeških višavah je zvesta. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 38, 'Ti pa si zavrgel in zaničeval, razsrdil si se zoper maziljenca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 39, 'Zaničeval si hlapca svojega zavezo, oskrunil in vrgel na tla venec njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 40, 'Podrl si vse ograje njegove, trdnjave njegove si izpostavil razdoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 41, 'Plenili so ga vsi mimohodeči, v zasmeh je dan sosedom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 42, 'Povzdignil si zatiralcev njegovih desnico, veselje napravil vsem sovražnikom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 43, 'Skrhal si tudi meča njegovega ostrino in mu nisi dal zmagati v vojski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 44, 'Storil si, da je minila bleščoba njegova, in prestol njegov si zvrnil na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 45, 'Okrajšal si dni mladosti njegove, pokril si ga s sramoto. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 46, 'Doklej, Gospod, boš li se skrival vekomaj? gorela bo kakor ogenj jeza tvoja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 47, 'Spomni se me – kako sem kratkih dni! Za kako ničevost si ustvaril vse otroke človeške!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 48, 'Kateri mož je, ki živi in ne bo videl smrti, ki zavaruje dušo svojo zoper oblast groba? (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 49, 'Kje so, o Gospod, milosti tvoje nekdanje, ki si jih prisegel Davidu v zvestobi svoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 50, 'Spomni se, Gospod, sramote hlapcev svojih, da nosim v prsih svojih zasramovanje vseh teh mnogih ljudstev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 51, 's katerim so sramotili sovražniki tvoji, Gospod, s katerim so sramotili maziljenca tvojega stopinje. —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 89, 52, 'Slava Gospodu vekomaj! Amen in Amen! Knjiga četrta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 1, '{Molitev Mojzesa, moža Božjega.} O Gospod, ti si nam bil prebivališče od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 2, 'Ko niso bile še rojene gore in nisi bil naredil zemlje in vesoljnega sveta, da, od vekomaj do vekomaj si ti Bog mogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 3, 'Pripraviš človeka, da razpade v prah, in veliš: Povrnite se, otroci človeški!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 4, 'Zakaj tisoč let je v tvojih očeh kakor včerajšnji dan, ko je minil, in kakor čas ponočne straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 5, 'Kakor s povodnijo jih pokončavaš, kot spanje so; zjutraj so kakor trava, ki vnovič poganja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 6, 'Zjutraj cvete in poganja, zvečer jo pokose in usahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 7, 'Kajti ginemo od jeze tvoje in vsled srda tvojega smo preplašeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 8, 'Pred oči svoje si postavil krivice naše, skrivnosti naše v luč obličja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 9, 'Kajti vsi dnevi naši minevajo v srdu tvojem, leta nam prelete kot misel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 10, 'Dnevi naših let – vseh jih je sedemdeset let ali, ako smo prav krepki, osemdeset let; in kar je naš ponos v njih, je le trud in težava; zakaj hitro vse poteče in mi odletimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 11, 'A kdo spoznava jeze tvoje moč in tvoj srd, boječ se te, kakor se spodobi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 12, 'Uči nas torej prav šteti naše dni, da si pridobimo srce modro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 13, 'Vrni se, Gospod! doklej –? in žal ti bodi za hlapce svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 14, 'Nasiti nas že ob jutranjem svitu z milostjo svojo, da veselo pojemo in se radujemo vse svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 15, 'Razveseli nas po številu dni, v katerih si nas ponižaval, in let, v katerih smo izkušali hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 16, 'Očitno bodi hlapcem tvojim delo tvoje in veličastvo tvoje nad njih otroki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 90, 17, 'Nad nami pa bodi ljubeznivost Gospoda, Boga našega, in delo naših rok podpiraj pri nas, delo, pravim, naših rok podpiraj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 1, 'Kdor stanuje v zavetju Najvišjega, bo počival v senci Vsemogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 2, 'Zato pravim Gospodu: Pribežališče si moje in grad moj, Bog moj, v katerega upam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 3, 'Kajti on te bo rešil iz zanke ptičarjeve in kuge pogubne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 4, 'S perutjo svojo te pokrije, in pod krili njegovimi ti bo zavetje, ščit in bran je resnica njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 5, 'Ne boj se nočnega strahu, ne pšice, ki šviga po dnevi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 6, 'ne pogube, ki lazi v temi, ne kuge, ki razsaja opoldne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 7, 'Pade jih ob strani tvoji tisoč in desetkrat tisoč na desnici tvoji, a k tebi se ne približa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 8, 'Samo z očmi svojimi boš to gledal in videl povračilo brezbožnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 9, 'Ker si rekel: Ti, Gospod, si pribežališče moje, Najvišjega si postavil za prebivališče svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 10, 'ne zadene te nesreča nobena in šiba se ne približa šatoru tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 11, 'Zakaj angelom svojim zapove zate, da te hranijo po vseh potih tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 12, 'Na rokah te bodo nosili, da ne zadeneš z nogo svojo ob kamen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 13, 'Po divjem levu boš hodil in po kači, teptal boš leva mladiča in zmaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 14, 'Ker mi je vdan v ljubezni, pravi Bog, ga hočem oteti; na varno ga postavim, ker pozna ime moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 15, 'Kadar me zakliče, ga uslišim, na strani mu bodem v stiski; rešim ga in počastim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 91, 16, 'Nasitim ga z dolgostjo življenja in storim, da z veseljem gleda zveličanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 1, '{Psalm in pesem za sobotni dan.} Dobro je slaviti Gospoda in psalme pevati imenu tvojemu, o Najvišji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 2, 'Oznanjati zjutraj milost tvojo in zvestobo vsako noč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 3, 'z desetostrunjem in z brenkljami, z umetno godbo na citre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 4, 'Kajti razveseljuješ me, Gospod, z delom svojim, glasno bom prepeval o tvojih rok dejanjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 5, 'Kako velika so dela tvoja, Gospod, silno globoke so misli tvoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 6, 'Človek živinski ne spoznava in nespametnež ne umeje tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 7, 'Ko poganjajo brezbožni kakor trava in cveto vsi, ki delajo krivico, se to godi, da bi se pogubili vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 8, 'Ti pa si vzvišen vekomaj, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 9, 'Ker glej, sovražniki tvoji, Gospod, ker glej, sovražniki tvoji poginejo, razprše se vsi, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 10, 'Rog moj pa povzdigneš kakor samorogov, maziljen bodem s presnim oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 11, 'In oko mi bo gledalo z veseljem na zalezovalce moje, o hudodelcih, ki vstajajo zoper mene, na svoja ušesa zaslišim, kar mi bo všeč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 12, 'Kakor palma bo zelenel pravičnik, kakor cedra na Libanonu bo rastel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 13, 'Zasajeni v hiši Gospodovi bodo v vežah Boga našega poganjali mladike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 14, 'Še v sivosti bodo dajali sad, čvrsti ostanejo in zeleneči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 92, 15, 'da oznanjajo, da je pravičen Gospod, skala moja, in krivice v njem ni nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 1, 'Gospod kraljuje, z veličastvom se je oblekel, oblekel se je Gospod, opasal z močjo; zato trdno stoji vesoljni svet, ne omahuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 2, 'Trdno stoji prestol tvoj od nekdaj, od vekomaj si ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 3, 'Vzdignili so se reke, o Gospod, vzdignile so reke šum svoj, vzdigujejo reke bobnenje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 4, 'Večji ko šum mnogih vodá, ko vršenje morskih valov, še tako veličastnih, veličastnejši je Gospod v višavah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 93, 5, 'Pričevanja tvoja so zanesljiva jako; hiši tvoji se spodobi svetost, o Gospod, na večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 1, 'Bog mogočni maščevanja, o Gospod, Bog mogočni maščevanja, prikaži se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 2, 'Dvigni se, o zemlje sodnik, daj povračilo prevzetnim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 3, 'Doklej bodo brezbožni, o Gospod, doklej bodo veselja poskakovali brezbožni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 4, 'Ustijo se in govore predrzno, ponašajo se vsi, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 5, 'Tvoje ljudstvo, Gospod, teptajo v prah in tlačijo tvojo dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 6, 'Moré vdovo in tujca in ubijajo sirote,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 7, 'govoreč: Ne vidi Gospod in ne pazi Bog Jakobov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 8, 'Doumejte vendar, nespametni med ljudstvom, in neumneži, kdaj bodete razumni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 9, 'Ali on, ki je vsadil uho, bi ne slišal? ali on, ki je naredil oko, bi ne videl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 10, 'Ali on, ki pokori narode, bi ne grajal, on, ki uči ljudi modrosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 11, 'Gospod pozna misli človeške, da so zgolj ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 12, 'Blagor možu, ki ga pokoriš, Gospod, in ga učiš iz zakona svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 13, 'da mu pripraviš pokoj od dni nesreče, dokler se ne izkoplje brezbožniku jama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 14, 'Kajti Gospod ne zavrže ljudstva svojega in dediščine svoje ne zapusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 15, 'Temuč k pravičnosti se mora vrniti sodba, in za njo pojdejo vsi, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 16, 'Kdo bi vstal zame zoper hudodelnike? kdo bi se postavil zame zoper one, ki delajo krivico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 17, 'Ko bi mi ne bil Gospod pomoč, malo da ne bi prebivala v kraju molčanja duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 18, 'Ko pravim: Omahuje noga moja, milost tvoja, o Gospod, me podpira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 19, 'Kadar mi je premnogo skrbi na srcu, tolažbe tvoje razveseljujejo dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 20, 'Ali bi bil s teboj združen prestol pogube, ki snuje hudobnost pod pretvezo postave?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 21, 'Četoma se zbirajo proti pravičnega duši in obsojajo kri nedolžno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 22, 'A Gospod mi je grad visoki in Bog moj skala pribežališča mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 94, 23, 'On obrača proti njim njih krivico in po njih hudobnosti jih pokonča; pokonča jih Gospod, naš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 1, 'Pridite, veselo pevajmo Gospodu, ukajmo skali zveličanja svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 2, 'Pojdimo pred obličje njegovo s hvalo, psalme pojoč mu ukajmo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 3, 'Zakaj velik Bog mogočni je Gospod in velik kralj nad vse bogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 4, 'V roki njegovi so podstave zemlje in v njegovi oblasti višine gorá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 5, 'Njegovo je morje, on ga je naredil, in suho zemljo so ustvarile roke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 6, 'Pridite, priklonimo se in padimo na tla, pripognimo kolena pred Gospodom, ki nas je ustvaril!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 7, 'Zakaj on je Bog naš, mi pa ljudstvo paše njegove in čreda vodbe njegove. Danes če slišite glas njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 8, 'nikar ne zakrknite srca svojega kakor v prepiru, kakor ob dnevi izkušnjave kakor ob dnevi izkušnjave [Hebr. Masa.] v puščavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 9, 'ko so me izkušali očetje vaši; izkušnjo so mi napravili, dasi so videli dela moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 10, 'Štirideset let sem imel težave s tistim rodom in sem rekel: Ljudstvo je srca tavajočega. A oni niso spoznali potov mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 95, 11, 'Zatorej sem prisegel v jezi svoji: Nikakor ne pridejo v pokoj moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 1, 'Pojte Gospodu novo pesem, pojte Gospodu, vse dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 2, 'Pojte Gospodu, slavite ime njegovo, z veseljem oznanjajte od dne do dne zveličanje njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 3, 'Pripovedujte med poganskimi narodi veličastvo njegovo, med vsemi ljudstvi čudovita dela njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 4, 'Ker velik je Gospod in velike hvale vreden, strašen je on nad vse bogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 5, 'Kajti vsi bogovi ljudstev so maliki, Gospod pa je naredil nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 6, 'Slava in lepota sta pred njim, moč in veličastvo v svetišču njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 7, 'Dajajte Gospodu, ljudstev rodovine, dajajte čast in moč Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 8, 'Dajajte Gospodu slavo imena njegovega, prinesite dar in pridite v veže njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 9, 'Klanjajte se Gospodu v diki svetosti; trepetajte pred njim, vse dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 10, 'Govorite med pogani: Gospod kraljuje, tudi zemlje obod je utrjen, da ne omahne; sodil bo ljudstva pravično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 11, 'Veselé se naj nebesa in poskakuj zemlja, šumi naj morje in kar je v njem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 12, 'raduj se polje in vse, kar je na njem! Tedaj bo veselo prepevalo vse drevje v gozdu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 96, 13, 'pred obličjem Gospodovim, kajti prihaja; kajti prihaja sodit zemljo. Sodil bo vesoljni svet v pravičnosti in ljudstva v zvestobi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 1, 'Gospod kraljuje, poskakuj zemlja, vesele se naj otoki mnogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 2, 'Oblaki in tema ga obdajajo, pravičnost in sodba sta podstava njegovemu prestolu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 3, 'Ogenj gre pred njim in požiga okrog sovražnike njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 4, 'Bliski njegovi razsvetljujejo vesoljni svet; videč to, trepeta zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 5, 'Gore se tope kakor vosek vpričo Gospoda, vpričo vse zemlje Gospodarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 6, 'Nebesa oznanjajo pravičnost njegovo, da vidijo vsa ljudstva njegovo čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 7, 'Osramočeni bodo vsi, ki služijo podobam, ki se ponašajo z maliki; klanjajte se mu, vsi bogovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 8, 'Sion to sliši in se veseli, in hčere Judove veselja poskakujejo zaradi sodb tvojih, o Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 9, 'Zakaj ti, Gospod, si najvišji nad vso zemljo, silno povišan si nad vse bogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 10, 'Kateri ljubite Gospoda, sovražite hudo! On hrani duše svojih, ki jim izkazuje milost, iz rok brezbožnikov jih otimlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 11, 'Luč povsod vzhaja pravičnemu in veselje njim, ki so pravega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 97, 12, 'Veselite se, pravični, v Gospodu in slavite spomin svetosti njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 1, '{Psalm.} Pojte Gospodu novo pesem, ker storil je čudovita dela; rešitev mu je pridobila desnica njegova in rama njegove svetosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 2, 'Naznanil je Gospod rešitev svojo, pred očmi narodov je razodel pravičnost svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 3, 'Spomnil se je milosti svoje in zvestobe svoje do hiše Izraelove; vse meje zemlje so videle Boga našega rešitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 4, 'Ukajte Gospodu, vse dežele, vriskajte in pevajte psalme!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 5, 'Pojte psalme Gospodu s citrami, s citrami in ubranimi glasovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 6, 'S trobentami in z glasom roga ukajte pred kraljem Gospodom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 7, 'Šumi naj morje in kar je v njem, vesoljni svet in prebivalci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 8, 'Reke naj ploskajo z rokami, ž njimi vred naj pojó gore');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 98, 9, 'pred Gospodom, kajti prihaja sodit zemljo! Sodil bo vesoljni svet v pravičnosti in ljudstva po pravici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 1, 'Gospod kraljuje, ljudstva trepetajo; sedeč na kerubih, kraljuje, maje se zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 2, 'Gospod je velik na Sionu in visok je on nad vse ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 3, 'Slavé naj ime tvoje veliko in strašno, – On je svet! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 4, 'in moč kralja, ki ljubi pravico! Ti si utrdil, kar je pravično, pravo sodbo in pravičnost ti izvršuješ v Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 5, 'Povišujte Gospoda, Boga našega, in pokleknite pred podnožjem nog njegovih: On je svet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 6, 'Mojzes in Aron sta bila med njegovimi duhovniki in Samuel med njimi, ki kličejo ime njegovo; klicali so h Gospodu, in on jim je odgovarjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 7, 'V oblakovem stebru jim je govoril; hranili so pričevanja njegova in postavo, katero jim je dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 8, 'Gospod, Bog naš, ti si jim odgovarjal, bil si jim Bog mogočni, odpuščajoč grehe, pa tudi kaznujoč njih dejanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 99, 9, 'Povišujte Gospoda, Boga našega, in pokleknite na gori svetosti njegove! Zakaj svet je Gospod, Bog naš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 1, '{Psalm za hvalno daritev.} Ukajte Gospodu, vse dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 2, 'Služite Gospodu z veseljem, pridite pred obličje njegovo z radostnim pitjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 3, 'Spoznajte, da je Gospod Bog, on nas je ustvaril, ne pa mi sebe; ljudstvo njegovo smo in ovce paše njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 4, 'Vstopite v vrata njegova s hvalno daritvijo, s poveličevanjem v veže njegove: zahvaljujte se mu, slavite ime njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 100, 5, 'Ker dober je Gospod, vekomaj traja milost njegova in od roda do roda zvestoba njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 1, '{Psalm Davidov.} Milost in pravico bom opeval, tebi, o Gospod, pel psalme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 2, 'Pazil bom na pot popolnosti, o kdaj prideš k meni? hodil bom vedno v poštenosti srca svojega v hiši svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 3, 'Stavil si ne bom pred oči stvari pregrešne, čine razuzdanosti sovražim, ne primejo se me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 4, 'Srce lokavo bodi daleč od mene, hudega ne poznam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 5, 'Kdor skrivno obrekuje bližnjega svojega, njega iztrebim; kdor je ošabnih oči in srca napihnjenega, tega ne strpim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 6, 'Oči moje se bodo vpirale na zveste v deželi, da naj sedajo z menoj; kdor hodi po potu popolnosti, ta mi bo stregel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 7, 'Stanoval ne bo v hiši moji, kdor dela zvijačo; kdor govori laž, ne bo obstal pred mojimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 101, 8, 'Vsako jutro bom zatiral vse brezbožnike iz dežele, da potrebim iz mesta Gospodovega vse, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 1, '{Molitev trpina, ko omaguje in pred Gospodom izliva žalovanje svoje.} Gospod, čuj molitev mojo, in vpitje moje pridi do tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 2, 'Ne skrivaj mi obličja svojega v dan stiske moje, nagni mi uho svoje; ob dnevi, ko kličem, me hitro usliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 3, 'Kajti ginejo kakor dim dnevi moji in kosti moje goré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 4, 'Opaljeno je kakor trava in velo srce moje, kajti pozabil sem jesti kruh svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 5, 'Od glasu zdihovanja mojega se držé kosti moje mojega mesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 6, 'Podoben sem pelikanu v puščavi, sem kakor sova v podrtinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 7, 'Bedim in sem kakor samoten vrabec na strehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 8, 'Ves dan me sramoté sovražniki moji; kateri divjajo zoper mene, se rotijo pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 9, 'Kajti pepel jem kakor kruh in pijačo svojo mešam s solzami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 10, 'zaradi srda tvojega in togote tvoje, ker vzdignil si me in me vrgel na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 11, 'Dnevi moji so kakor senca pred mrakom in sam usiham kakor zél.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 12, 'Ti pa, Gospod, ostajaš vekomaj in spomin tvoj od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 13, 'Ti boš vstal in se usmilil Siona, ker čas je storiti mu milost, ker čas določen je prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 14, 'Kajti hlapcem tvojim je drago njega kamenje in smili se jim njega prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 15, 'In bali se bodo pogani imena Gospodovega in vsi kralji zemlje slave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 16, 'Ko sezida Gospod Sion in se prikaže v slavi svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 17, 'se ozre na molitev zapuščenca, in ne bo zametal njih molitve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 18, 'Zapiše se to naslednjemu rodu, in ljudstvo, ki bode ustvarjeno, bo hvalilo Gospoda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 19, 'ker je pogledal z višave svetosti svoje, ozrl se Gospod iz nebes na zemljo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 20, 'da usliši jetnikov zdihovanje, da oprosti nje, ki so izročeni smrti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 21, 'da oznanjajo na Sionu ime Gospodovo in hvalo njegovo v Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 22, 'ko se zbero ljudstva vsa in kraljestva, da služijo Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 23, 'Potlačil je na tem potu moč mojo, dni moje skrajšal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 24, 'Dejal sem: Bog moj mogočni, ne vzemi me sredi mojih dni! Skozi vse rodove so dnevi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 25, 'Saj ti si nekdaj ustanovil zemljo in delo tvojih rok so nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 26, 'Ona preidejo, ti pa ostaneš; da, vse tisto se postara kakor oblačilo, kakor obleko jih izpremeniš, in se izpremené.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 27, 'Ti pa si večno isti in let tvojih ni konca!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 102, 28, 'Sinovi hlapcev tvojih bodo prebivali v deželi in njih seme se utrdi pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 1, '{Psalm Davidov.} Slavi, duša moja, Gospoda, in vse, kar je v meni, sveto ime njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 2, 'Slavi, duša moja, Gospoda in ne pozabi vseh dobrot njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 3, 'Ki ti odpušča vse krivice tvoje, ki ozdravlja vse bolezni tvoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 4, 'ki otimlje iz jame življenje tvoje, ki te venča z milostjo in usmiljenjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 5, 'ki napolnjuje z vsem dobrim usta tvoja, da se kakor orlu ponavlja mladost tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 6, 'Kar je pravično, dela Gospod in pravosodje vrši za vse zatirance.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 7, 'Razodel je Mojzesu pota svoja, sinovom Izraelovim dela svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 8, 'Usmiljen in milostiv je Gospod, počasem v jezo in obilen v milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 9, 'Ne huduje se vekomaj in večno ne drži jeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 10, 'Ne dela nam po grehih naših in ne povrača nam po krivicah naših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 11, 'Temuč kakor so visoko nebesa nad zemljo, tako močna je milost njegova nad njimi, ki se ga bojé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 12, 'Kakor daleč je vzhod od zahoda, tako daleč spravlja od nas prestopke naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 13, 'Kakor se oče usmili otrok, usmili se Gospod njih, ki se ga bojé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 14, 'Kajti on pozna, kakšna stvar smo, spominja se, da smo prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 15, 'Človekovi dnevi so kakor trava, on cvete kakor cvetica na polju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 16, 'ko veter potegne čeznjo, je ni več in mesta njenega ni več poznati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 17, 'A milost Gospodova se razteza od veka do veka nanje, ki se ga bojé, in pravičnost njegova je za sinov sinove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 18, 'zanje, ki hranijo zavezo njegovo in se spominjajo njegovih zapovedi, da jih izpolnjujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 19, 'Gospod je v nebesih postavil prestol svoj, in kraljestvo njegovo gospoduje vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 20, 'Slavite Gospoda, angeli njegovi, vi junaki v moči, ki izvršujete povelje njegovo, poslušajoč glas njegove besede!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 21, 'Slavite Gospoda, vse vojske njegove, služabniki njegovi, izpolnjujoči voljo njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 103, 22, 'Slavite Gospoda, vsa dela njegova, po vseh krajih njegovega gospostva! Slavi, duša moja, Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 1, 'Slavi, duša moja, Gospoda! Gospod, Bog moj, velik si silno, lepoto in veličastvo si oblekel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 2, 'ogrinjaš se s svetlobo kakor z obleko, nebesa razpenjaš kakor šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 3, 'Kateri stavi v vodah tramovje hramov svojih, ki nareja oblake za voz svoj, ki hodi po vetrov perutih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 4, 'ki dela vetrove za poslance svoje, za služabnike svoje ogenj plamteči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 5, 'Postavil je zemljo na podstave njene, da se ne gane na večne čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 6, 'Z valovjem si jo ogrnil kakor z odejo, čez gore so stale vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 7, 'Na karanje tvoje so pobegnile, pred groma tvojega glasom so urno bežale –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 8, 'dvignile so se gore, pogreznile se doline – na mesto, katero si jim bil ustanovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 9, 'Mejo si jim postavil, da je ne prestopijo, da se ne povrnejo pokrit zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 10, 'Ti izpuščaš studence po dolinah, da tečejo med gorami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 11, 'napajajo vse poljske živali, žejo svojo si gasé divji osli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 12, 'Poleg njih prebivajo ptice nebeške, glasijo se izmed vej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 13, 'On namaka gore iz hramov svojih, s sadom del tvojih se siti zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 14, 'On daje, da raste trava živini in zelišče človeku v rabo, da si pripravi hrano iz zemlje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 15, 'in vino, ki razveseljuje srce človeku, in olje, ki svetel nareja obraz, in kruh, ki podpira srce človeku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 16, 'Siti se drevje Gospodovo, cedre na Libanonu, ki jih je vsadil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 17, 'kjer gnezdijo ptički, tudi štorklja, ki ima hišo svojo na jelkah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 18, 'Gore visoke so divjim kozlom, pečine skalnim jazbecem prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 19, 'Naredil je mesec, da meri čase, in solnce, ki pozna zahod svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 20, 'Temo narejaš, da je noč, tedaj so vse gozdne živali pokonci:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 21, 'mladi levi rjovejo za plenom in zahtevajo od Boga mogočnega hrane svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 22, 'Ko izhaja solnce, se poskrijejo in ležé v brlogih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 23, 'Človek pa gre na delo svoje in po opravilu svojem do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 24, 'Kako mnogotera so dela tvoja, o Gospod, v modrosti si jih naredil vsa, polna je zemlja stvorov tvojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 25, 'Ondi morje, veliko in prostrano, v njem je laznine brez števila, živali velikih in malih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 26, 'Tod hodijo ladje in leviatan, ki si ga ustvaril, naj se v njem igra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 27, 'Vse to čaka tebe, da jim daš njih živeža o svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 28, 'Kadar jim daješ, pobirajo, odpreš jim roko svojo, in sitijo se z dobrotami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 29, 'Kadar jim skriješ obličje svoje, se prestrašijo; vzameš jim sapo, in ginejo ter se povračajo v prah svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 30, 'Pošiljaš sapo svojo in jih spet ustvarjaš, in tako obličje obnavljaš zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 31, 'Slava Gospodova traja naj vekomaj! Veseli se naj Gospod v delih svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 32, 'Ko pogleda na zemljo, se trese ona, ko se dotakne gorá, se kadé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 33, 'Pel bom Gospodu vse svoje žive dni, psalme prepeval Bogu svojemu, dokler bodem živ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 34, 'O da bi mu bilo prijetno premišljevanje moje! Jaz se hočem radovati v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 104, 35, 'Izginejo naj grešniki z zemlje in brezbožnikov več ne bodi! Slavi, duša moja, Gospoda! Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 1, 'Hvalite Gospoda, razglašujte ime njegovo, med ljudstvi oznanjujte dejanja njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 2, 'Pojte mu, psalme mu prepevajte, razgovarjajte se o vseh čudovitih delih njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 3, 'Hvalite se v svetem imenu njegovem; veseli se naj srce njih, ki iščejo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 4, 'Iščite Gospoda in moči njegove, iščite vedno njegovega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 5, 'Spominjajte se čudes njegovih, ki jih je storil, čudovitih del njegovih in razsodkov ust njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 6, 'O seme Abrahama, njegovega hlapca, sinovi Jakobovi, izvoljenci njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 7, 'On, Gospod, je Bog naš, po vsej zemlji se vršé sodbe njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 8, 'Spominja se vekomaj zaveze svoje, besede, ki jo je zapovedal do tisoč rodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 9, 'zaveze, ki jo je sklenil z Abrahamom, in prisege svoje Izaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 10, 'In jo je dal Jakobu v postavo, Izraelu v večno zavezo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 11, 'govoreč: Tebi hočem dati deželo Kanaansko kot vam odmerjeno dedno posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 12, 'Ko jih je bilo po številu malo, prav malo, pa so še kot tujci bivali v njej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 13, 'in so hodili od naroda do naroda, iz enega kraljestva k drugemu ljudstvu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 14, 'ni dovolil zatirati jih nikomur in kralje je strahoval zavoljo njih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 15, 'Ne doteknite se maziljencev mojih in ne storite žalega prorokom mojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 16, 'Tu je poklical lakoto nad deželo in strl ljudem vso podporo kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 17, 'Poslal je pred njimi moža, ki je bil v sužnost prodan, Jožefa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 18, 'Noge njegove so vklenili v spone, železo ga je stiskalo do duše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 19, 'do časa, ko se je uresničila beseda njegova: govor Gospodov ga je bil prečistil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 20, 'Poslal je kralj in velel ga razvezati, poglavar ljudstev, in ga je oprostil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 21, 'Postavil ga je za gospoda družini svoji in za poglavarja vsej svoji posesti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 22, 'da bi zvezaval kneze njegove po volji svoji in učil modrosti njegove starejšine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 23, 'Nato je prišel Izrael v Egipt in Jakob je tujčeval v deželi Hamovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 24, 'Tam je storil Bog ljudstvo svoje silno rodovitno in ga je naredil močnejše od tlačiteljev njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 25, 'Izpremenil je njih srce, da so sovražili ljudstvo njegovo, da so zvijačne naklepe snovali zoper hlapce njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 26, 'Poslal je Mojzesa, hlapca svojega, Arona, ki ga je bil izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 27, 'Delala sta pred njimi besede znamenj njegovih in čudeže v deželi Hamovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 28, 'Poslal je temé in omračil je deželo, in nista se upirala besedi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 29, 'Izpremenil je v kri njih vode in pokončal je njih ribe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 30, 'Obilo je rodila njih dežela žab, mrgolelo jih je po kraljevih sobanah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 31, 'Rekel je, in prišle so pasje muhe, komarji na vso njih pokrajino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 32, 'Dal jim je za dež točo, ogenj plamteč spustil na njih kraj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 33, 'in pobil je njih trte in smokve in polomil drevje njih pokrajine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 34, 'Rekel je, in prišle so kobilice in hrošči, in to brez števila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 35, 'in so požrli vso travo v njih deželi in požrli njih poljski sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 36, 'Slednjič je udaril vse prvorojeno v njih deželi, prvino vse njih moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 37, 'Tedaj jih je izpeljal s srebrom in zlatom, in ni ga bilo, ki bi bil pešal med njih rodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 38, 'Veselili so se Egipčani, ko so šli ti, ker strah pred njimi jih je bil obšel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 39, 'Razgrnil je oblak, da jih zaslanja, in ogenj, da razsvetljuje noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 40, 'Prosili so, in poslal jim je prepelic in s kruhom nebeškim jih je sitil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 41, 'Odprl je skalo, in pritekle so vode, tekle so po pušči kakor reka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 42, 'Ker se je spominjal besede svetosti svoje in Abrahama, hlapca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 43, 'Zato je izpeljal ljustvo svoje z veseljem, s petjem izvoljence svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 44, 'in dal jim je dežele poganov in pridelke ljudstev v last,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 105, 45, 'da se naj držé postav njegovih in hranijo zakone njegove. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 1, 'Aleluja! Hvalite Gospoda, ker je dober, ker traja vekomaj milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 2, 'Kdo bi dopovedal mogočna dela Gospodova, oznanil vso hvalo njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 3, 'O blagor jim, ki se oklepajo pravice, ki delajo pravičnost vsak čas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 4, 'Spomni se me, Gospod, po blagovoljnosti, ki jo izkazuješ svojemu ljudstvu, obišči me z rešilno pomočjo svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 5, 'da uživam izvoljenih tvojih srečo, da se veselim radosti naroda tvojega, da se ponašam z dedino tvojo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 6, 'Grešili smo kakor očetje naši, krivično smo delali, brezbožno ravnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 7, 'Očetje naši v Egiptu niso uvaževali čudovitih del tvojih, spominjali se niso milosti tvojih množine, temuč bili so uporni pri morju, pri morju Rdečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 8, 'Vendar jih je rešil zavoljo imena svojega, da bi pokazal svojo moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 9, 'Zapretil je Rdečemu morju, in posušilo se je, in peljal jih je skozi valove kakor po planjavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 10, 'Tako jih je otel sovražilcu iz roke, odrešil jih je iz roke neprijateljeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 11, 'Vode pa so pokrile njih zatiralce, eden izmed njih ni ostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 12, 'Tedaj so verjeli besedam njegovim, peli hvalo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 13, 'Pa hitro so pozabili del njegovih, čakali niso sveta njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 14, 'ampak vdali so se poželjivosti v puščavi, izkušali Boga mogočnega v samoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 15, 'In dal jim je, česar so želeli, a poslal jim je suhoto v njih duše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 16, 'Ko so bili nevoščljivi Mojzesu v taborišču in Aronu, svetniku Gospodovemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 17, 'se je odprla zemlja in požrla Datana, in zagrnila je druhal Abiramovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 18, 'In ogenj se je vnel v njih druhali, in plamen je požgal krivičnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 19, 'Naredili so tele pri Horebu in so se klanjali uliti podobi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 20, 'in so zamenili čast svojo s podobo vola, ki muli travo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 21, 'Pozabili so Boga mogočnega, rešitelja svojega, ki je bil storil velike reči v Egiptu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 22, 'čudovita dela v deželi Hamovi, strašna pri Rdečem morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 23, 'Zato je rekel, da jih pogubi; ko bi ne bil Mojzes, izvoljenec njegov, stopil v oni prepad pred njim, da je odvrnil jezo njegovo, da jih ni pogubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 24, 'Zaničevali so tudi zaželjeno deželo, ne verujoč besedi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 25, 'Godrnjali so v šatorih svojih in niso poslušali glasu Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 26, 'Tu je dvignil roko svojo proti njim ter prisegel, da morajo popadati v puščavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 27, 'in da raznese njih seme med narode in jih razkropi po deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 28, 'Združili so se tudi z malikom Baal-peorjem in jedli daritve mrtvim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 29, 'Tako so dražili Boga s počenjanjem svojim, da je prihrul nadnje pomor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 30, 'Tu se je vzdignil Pinehas in storil sodbo, in pomor je bil ustavljen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 31, 'to se mu je štelo za pravičnost, od roda do roda vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 32, 'Enako so razdražili Boga pri Vodi prepira, da se je slabo godilo Mojzesu zavoljo njih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 33, 'kajti upirali so se duhu njegovemu, in govoril je nepremišljeno z ustnami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 34, 'Pokončali niso onih ljudstev, za katera jim je bil zapoveddal Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 35, 'ampak pomešali so se s poganskimi narodi in naučili se njih del;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 36, 'in so služili njih malikom, in ti so jim bili v spotiko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 37, 'In darovali so sinove svoje in hčere svoje hudim duhovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 38, 'In prelivali so nedolžno kri, kri sinov in hčer svojih, ki so jih darovali malikom kanaanskim, da je bila dežela oskrunjena ž njih moritvami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 39, 'In onečistili so se s svojimi deli, prešeštvovali so z dejanji svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 40, 'Zato se je razsrdil Gospod nad ljudstvom svojim in pristudila se mu je dedina njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 41, 'In dal jih je v roko poganom, da bi jim gospodovali njih črtilci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 42, 'In stiskali so jih njih sovražniki, in bili so potlačeni pod njih roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 43, 'Mnogokrat jih je rešil, in vendar so bili uporni v naklepih svojih, in bili so ponižani zavoljo krivice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 44, 'Vendar se je oziral na njih stisko, ko je slišal njih vpitje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 45, 'In spominjal se je zanje zaveze svoje in kesal se je po obilosti milosti svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 46, 'In dal jim je doseči usmiljenje pred vsemi, kateri so jih imeli v sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 47, 'Reši nas, Gospod, Bog naš, in zberi nas izmed tistih poganov, da slavimo sveto ime tvoje in se hvalimo v hvali tvoji. —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 106, 48, 'Slava Gospodu, Bogu Izraelovemu, od veka do veka! In vse ljudstvo naj reče: Amen! Aleluja! Knjiga peta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 1, 'Hvalite Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 2, 'Tako naj govoré rešenci Gospodovi, ki jih je rešil iz rok tlačitelja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 3, 'in ki jih je zbral iz dežel, od vzhoda in od zahoda, od severa in od morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 4, 'Tavali so po puščavi, po potih samotnih, mesta za prebivališče niso našli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 5, 'lačni so bili in žejni, njih duša je hirala v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 6, 'Tedaj so klicali h Gospodu v nadlogi svoji, in rešil jih je iz njih stiske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 7, 'in vodil jih je po pravem potu, da bi dospeli v mesto za prebivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 8, 'Slavé naj Gospoda za milost njegovo in za čudovita dela njegova pri sinovih človeških:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 9, 'da on siti dušo potrebno in dušo gladno napolnjuje z dobrim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 10, 'Kateri so sedeli v temoti in v smrtni senci, v bridkosti sponah in v železju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 11, 'ker so se upirali besedam Boga mogočnega in so zavrgli sklep Najvišjega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 12, 'zato je ponižal njih srce z nadlogo, padli so, in ni ga bilo, ki bi jim bil pomagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 13, 'Tedaj so klicali h Gospodu v nadlogi svoji, in rešil jih je iz njih stiske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 14, 'izpeljal jih je iz temin in smrtne sence in raztrgal je njih vezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 15, 'Slavé naj Gospoda za milost njegovo in za čudovita dela njegova pri sinovih človeških,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 16, 'da je strl vrata bronasta in zdrobil zapahe železne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 17, 'Nespametni zavoljo pota pregrehe, zavoljo krivic svojih so prišli v trpljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 18, 'Vsaka hrana se je studila njih duši, smrtnim vratom so se približali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 19, 'Tedaj so klicali Gospoda v nadlogi svoji, in rešil jih je iz njih stiske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 20, 'poslal je besedo svojo in jih ozdravil, in jih je otel pogina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 21, 'Slavé naj Gospoda za milost njegovo in za čudovita dela njegova pri sinovih človeških');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 22, 'in naj darujejo hvalne daritve ter oznanjajo z radostnim petjem dela njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 23, 'Kateri so šli na morje v ladjah, za opravilom svojim po velikih vodah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 24, 'oni so videli dela Gospodova in čuda njegova v globočini:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 25, 'Ukaže namreč in napravi vihar, ki visoko žene valove njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 26, 'da se zdaj vzpenjajo do neba, zdaj zopet padajo v globočino, duša jim koprni v nadlogi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 27, 'vrtijo se in opotekajo kakor pijani, in vsa njih spretnost je izginila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 28, 'Tedaj so klicali h Gospodu v nadlogi svoji, in rešil jih je iz njih stiske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 29, 'premenil je vihar v tišino, in utihnili so jim valovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 30, 'Tedaj se razveselé, da so se pomirili valovi, in tako jih je peljal v pristanišče zaželjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 31, 'Slavé naj Gospoda za milost njegovo in za čudovita dela njegova pri sinovih človeških;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 32, 'in naj ga poveličujejo v zboru ljudstva ter v seji starejšin naj ga hvalijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 33, 'Reke izpreminja v puščavo in studence vodá v žejna tla,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 34, 'zemljo rodovitno v solnato puščo zavoljo hudobnosti prebivalcev njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 35, 'Puščavo izpreminja v jezero in suhotna tla v studence vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 36, 'In tja naseli lačne, da zidajo mesto za prebivanje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 37, 'in da posejejo njive in zasadé vinograde in pridelajo vsakoleten sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 38, 'Blagoslavlja jih tako, da se množijo silno, in njih živine ne zmanjšuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 39, 'Zmanjšani so pač bili in ponižani vsled zatiranja, nesreče in bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 40, 'On, ki izliva zaničevanje nad kneze in dela, da tavajo po praznoti, ki je brez potov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 41, 'na višavo je postavil siromaka iz bede in mu razmnožil rodovine kakor črede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 42, 'Vidijo to pravični in se veselé, vsa malopridnost pa zapre usta svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 107, 43, 'Kdorkoli je moder, naj pazi na to, in uvažujejo naj milosti Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 1, '{Pesem in psalm Davidov.} Utrjeno je srce moje, o Bog, pel bodem in psalme prepeval, tudi slava moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 2, 'Prebudite se, brenklje in strune, zbudim naj jutranjo zarjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 3, 'Hvalil te bodem med ljudstvi, Gospod, in psalme ti prepeval med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 4, 'Zakaj velika je nad nebesa milost tvoja in do nebeških višav resnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 5, 'Povzdigni se nad nebesa, o Bog, in čez vso zemljo slava tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 6, 'Da bodo rešeni ljubljenci tvoji, stóri rešitev z desnico svojo in usliši me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 7, 'Bog je govoril v svetosti svoji: Radoval se bom, razdelim Sihem in dolino Sukotsko premerim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 8, 'Moj je Gilead, moj Manase in Efraim glave moje bramba, Juda moje žezlo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 9, 'Moab umivalnica moja, na Edoma vržem svoje obuvalo, nad Filistejo bom ukal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 10, 'Kdo me popelje v mesto utrjeno, kdo me pripelje do Edomeje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 11, 'Ali nisi bil, o Bog, zavrgel nas in nisi hodil, o Bog, z našimi vojskami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 12, 'Daj nam pomoč zoper zatiralca, ker ničeva je pomoč človeška.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 108, 13, 'V Bogu delajmo junaške čine, in on potepta zatiralce naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 1, '{Načelniku godbe. Psalm Davidov.} O Bog hvale moje, ne molči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 2, 'Kajti usta krivičnega in usta zvijačna so se odprla zoper mene, govorila so zoper mene z lažnivim jezikom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 3, 'in z besedami sovražnimi so me obdali, se vojskovali z menoj brez vzroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 4, 'Za ljubezen mojo so mi črtilci, jaz pa stanovitno molim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 5, 'in vračajo mi hudo za dobro in sovraštvo za ljubezen mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 6, 'Postavi čezenj brezbožnika in protivnik naj mu stoji kot tožnik na desni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 7, 'Ko pride pred sodbo, odide naj obsojen; in molitev njegova bodi mu v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 8, 'Malo bodi dni njegovih in službo njegovo naj prejme drug.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 9, 'Otroci njegovi naj bodo sirote in žena njegova bodi vdova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 10, 'In neprestano naj se klatijo in beračijo otroci njegovi in iščejo naj kruha daleč od podrtih bivališč svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 11, 'Upnik naj ga odere za vse, kar ima, in tujci naj uplenijo, kar si je pridobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 12, 'Ne bodi mu nikogar, ki mu dobroto pomoli, in nihče naj ne izkaže usmiljenja sirotam njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 13, 'Pokončan bodi zarod njegov, v drugem rodu bodi izbrisano njih ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 14, 'V spominu bodi krivica očetov njegovih pri Gospodu in greh matere njegove se ne izbriši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 15, 'Bodo naj vedno pred očmi Gospodu, da iztrebi z zemlje njih spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 16, 'Zato ker ni maral izkazovati usmiljenja, ampak je preganjal moža ubogega in potrebnega in njega, ki mu je srce potrto, da ga usmrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 17, 'In ljubil je prokletstvo, zato ga je zadelo, in ni se veselil blagoslova, zato mu je daleč ostalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 18, 'Oblačil se je s prokletstvom kakor z oblačilom svojim, in šlo mu je v notranjščino kakor voda in kakor olje v kosti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 19, 'Bodi mu torej kakor suknja, ki se ž njo ogrinja, in kakor pas, ki se ž njim vedno opasuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 20, 'To bodi plačilo protivnikom mojim od Gospoda in njim, ki hudo govoré zoper dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 21, 'Ti pa, o Jehova Gospod, ravnaj milostno z menoj zavoljo imena svojega; ker je dobra milost tvoja, reši me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 22, 'Kajti ubožen sem in potreben, in srce moje je prebodeno v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 23, 'Kakor senca, ko se nagiblje, ginem; kakor kobilico me semtertja podé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 24, 'Kolena moja se šibé od posta in meso mi hujša, da ni več tolščobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 25, 'Vrhutega sem jim v zasramovanje; ko me vidijo, majejo z glavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 26, 'Pomagaj mi, o Gospod, Bog moj, reši me po milosti svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 27, 'da spoznajo, da je to roka tvoja, da si ti, Gospod, to storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 28, 'Preklinjajo naj, ti me blagoslavljaj! Ko se povzdignejo, bodo osramočeni, a hlapec tvoj se bo veselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 29, 'Z nečastjo se morajo odeti protivniki moji in ogrniti se kakor s plaščem s sramoto svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 30, 'Hvalil bom močno z usti svojimi Gospoda in sredi mnogih ga bom proslavljal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 109, 31, 'da stoji na desni siromaku, da ga reši njih, ki mu obsojajo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 1, '{Psalm Davidov.} Rekel je Gospod mojemu Gospodu: „Sédi meni na desni, dokler ne denem sovražnikov tvojih nogam tvojim za podnožje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 2, 'Žezlo moči tvoje pošlje Gospod s Siona: „Gospoduj sredi sovražnikov svojih!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 3, 'Ljudstvo tvoje pojde radovoljno ob dnevi, ko boš skliceval vojno moč svojo; v krasotah svetosti, iz naročja zore ti pride rosa mladega moštva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 4, 'Prisegel je Gospod in ne bode se kesal: „Ti si duhovnik vekomaj po redu Melhizedekovem“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 5, 'Gospod na desnici tvoji potare kralje ob dnevi jeze svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 6, 'sodil bo med narodi, polno bode mrličev. Razbije glavo nad mnogimi kraji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 110, 7, 'Iz potoka bo pil na potu, zatorej povzdigne glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 1, 'Aleluja! Hvalil bom Gospoda iz vsega srca v zboru pravičnih in na njih shodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 2, 'Velika so dela Gospodova, preiskujejo jih vsi, ki se jih veselé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 3, 'Slavno in krasno je delo njegovo, in pravičnost njegova ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 4, 'Spomin je napravil čudežem svojim, milostiv in usmiljen je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 5, 'Jedi je dal njim, ki se ga bojé; spominja se vekomaj zaveze svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 6, 'Moč del svojih je naznanil ljudstvu svojemu s tem, da jim je dal posest poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 7, 'Dela rok njegovih so resnica in prava sodba, zanesljive so vse zapovedi njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 8, 'utrjene za vedno in na veke, storjene v zvestobi in pravično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 9, 'Odrešitev je poslal ljudstvu svojemu, na vekomaj je sklenil zavezo svojo; sveto in strašno je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 111, 10, 'Začetek modrosti je strah Gospodov; dobro razumnost imajo vsi, ki se po zapovedih ravnajo. Hvala Njegova ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 1, 'Aleluja! Blagor mu, kdor se boji Gospoda, v zapovedih njegovih se veseli močno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 2, 'Mogočno bode na zemlji seme njegovo, pravičnih rod se blagoslavlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 3, 'Obilost in bogastvo je v hiši njegovi, in pravičnost njegova ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 4, 'V temi vzhaja luč poštenim; milosten je, usmiljen in pravičen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 5, 'Dobro človeku, ki je radodaren in posoja: obdržal bo svoje reči na sodbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 6, 'Kajti vekomaj ne omahne, v večnem spominu bode pravičnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 7, 'Hudega glasu se ne zboji, utrjeno je srce njegovo, upajoč v Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 8, 'V svojem srcu podprt, se ne boji, dokler ne vidi na zatiralcih svojih, kar mu je všeč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 9, 'Razsiplje, daje potrebnim, pravičnost njegova ostane vekomaj, rog njegov se dviguje v časti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 112, 10, 'Brezbožnik, videč to, se bo jezil, z zobmi svojimi škripal in pešal; brezbožnih želja pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 1, 'Aleluja! Hvalite, hlapci Gospodovi, hvalite ime Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 2, 'Slavljeno bodi ime Gospodovo odslej in na vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 3, 'Od vzhoda solnčnega do zahoda naj se hvali ime Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 4, 'Vzvišen nad vse narode je Gospod, nad sama nebesa slava njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 5, 'Kdo je enak Gospodu, Bogu našemu, ki stoluje v višavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 6, 'ki se ponižava, da vidi, karkoli je v nebesih in na zemlji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 7, 'ki iz prahu povišuje ubožca, iz blata dviguje siromaka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 8, 'da ga posadi med plemenitnike, med ljudstva svojega plemenitnike;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 113, 9, 'daje, da ona, ki je bila nerodovitna v hiši, gospodari in je mati, otrok vesela. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 1, 'Ko je izhajal Izrael iz Egipta, družina Jakobova izmed ljudstva tujega jezika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 2, 'je postal Juda svetišče njegovo, Izrael gospostvo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 3, 'Morje je to videlo in bežalo, Jordan se je obrnil nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 4, 'Hribi so poskakovali kakor ovni, kakor mlada jagnjeta griči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 5, 'Kaj ti je, morje, da bežiš? o Jordan, da si se obrnil nazaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 6, 'O hribi, zakaj poskakujete kakor ovni, griči kakor jagnjeta mlada?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 7, 'Pred obličjem Gospodovim trepetaj, zemlja, pred obličjem Boga Jakobovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 114, 8, 'ki je izpremenil skalo v jezero, kremenje v studence vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 1, 'Ne nam, Gospod, ne nam, temuč svojemu imenu daj čast, zaradi milosti svoje, zaradi resnice svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 2, 'Zakaj bi govorili pogani: Kje je torej njih Bog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 3, 'A Bog naš je v nebesih, stori vse, karkoli hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 4, 'Njih maliki pa so srebro in zlato, delo rok človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 5, 'Usta imajo, pa ne govore, oči imajo, pa ne vidijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 6, 'ušesa imajo, pa ne slišijo, nos imajo, pa ne duhajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 7, 'roke, pa ne tipajo, noge, pa ne hodijo, z grlom svojim še ne črhnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 8, 'Njim so podobni, ki jih delajo, vsi, ki vanje upajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 9, 'Izrael, upaj v Gospoda! Pomoč je tem in ščit je tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 10, 'Družina Aronova, upajte v Gospoda! Pomoč je tem in ščit je tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 11, 'Kateri se bojite Gospoda, upajte v Gospoda! Pomoč je tem in ščit je tem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 12, 'Gospod, spomnivši se nas, bo blagoslavljal, blagoslavljal družino Izraelovo, blagoslavljal družino Aronovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 13, 'Blagoslavljal bo vse, ki se boje Gospoda, male in velike vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 14, 'Množil vas bo Gospod, vas in otroke vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 15, 'Blagoslovljeni ste od Gospoda, ki je naredil nebo in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 16, 'Nebesa so nebesa Gospodova, a zemljo je dal sinom človeškim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 17, 'Ne kateri so umrli, hvalijo Gospoda, ne nihče teh, ki doli gredo v kraj molčanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 115, 18, 'ampak mi, mi bomo slavili Gospoda odslej in veke. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 1, 'Ljubim Gospoda, ker sliši glas moj, molitve moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 2, 'Ker je uho svoje nagnil k meni, zatorej ga bom klical vse svoje dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 3, 'Obdale so me smrtne vezi in me zadele peklenske stiske, prišel sem v nadlogo in žalost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 4, 'Tedaj sem klical ime Gospodovo: Prosim, Gospod, reši dušo mojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 5, 'Milosten je Gospod in pravičen in Bog naš je usmiljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 6, 'Preproste hrani Gospod; bil sem ponižan, in me je rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 7, 'Povrni se v pokoj svoj, duša moja, ker Gospod je dobro storil tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 8, 'Zakaj ti si otel dušo mojo smrti, oči moje solz, nogo mojo padca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 9, 'Neprestano bom hodil pred Gospodom v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 10, 'Veroval sem, kajti govoril sem, jaz, ki sem bil potlačen jako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 11, 'Jaz sem rekel v svoji osuplosti: Vsi ljudje so lažnivci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 12, 'Kaj naj povrnem Gospodu za vse dobrote njegove meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 13, 'Kelih obilega zveličanja primem in klical bom ime Gospodovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 14, 'obljube svoje izpolnim Gospodu, da, izpolnim jih vpričo vsega njegovega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 15, 'Draga je pred obličjem Gospodovim smrt svetih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 16, 'O Gospod, zares hlapec tvoj sem jaz, hlapec tvoj sem, dekle tvoje sin: ti si raztrgal vezi moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 17, 'Tebi bom daroval hvalne daritve in klical ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 18, 'Obljube svoje opravim Gospodu, da, opravim vpričo vsega njegovega ljudstva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 116, 19, 'v vežah hiše Gospodove, sredi tebe, Jeruzalem! Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 1, 'Hvalite Gospoda, vsi narodi, slavite ga, vi vsa ljudstva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 117, 2, 'Zakaj velika je do nas milost njegova, in resnica Gospodova traja vekomaj. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 1, 'Hvalite Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 2, 'Reci torej, Izrael: Da, vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 3, 'Recite torej, družina Aronova: Da, vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 4, 'Rekó naj, kateri se boje Gospoda: Da, vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 5, 'Iz stiske svoje sem klical Gospoda, odgovoril mi je in me postavil na plano Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 6, 'Gospod mi je na strani, ne bom se bal: kaj bi mi storil človek?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 7, 'Gospod mi je na strani med mojimi pomočniki, zato ugledam veselje svoje na sovražilcih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 8, 'Bolje je iskati zavetja v Gospodu nego upati v človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 9, 'Bolje je pribegati h Gospodu nego upati v poglavarje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 10, 'Vsi narodi so me obdali, zares, v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 11, 'Obdali so me, obdali vsenaokrog, zares v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 12, 'Obdali so me kakor čebele, a ugasnili so kakor trnov ogenj; zares, v imenu Gospodovem sem jih uničil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 13, 'Močno si me bil pahnil, sovražnik, da bi padel, ali Gospod mi je bil na pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 14, 'Moč moja in pesem moja je Gospod, on mi je bil v rešenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 15, 'Glas petja in rešenja je v pravičnikov šatorih: Desnica Gospodova dela junaške čine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 16, 'desnica Gospodova je povzdignjena, desnica Gospodova dela junaške čine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 17, 'Ne bom umrl, ampak živel, da oznanjam dela Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 18, 'Ostro me je pokoril Gospod, ali smrti me ni izdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 19, 'Odprite mi vrata pravičnosti, da vstopim vanje in slavim Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 20, 'Ta so vrata Gospodova, pravični vhajajo skozi nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 21, 'Hvalil te bom, ker si me uslišal in si mi bil v rešenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 22, 'Kamen, ki so ga bili zavrgli zidarji, je postal glavni vogalnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 23, 'Od Gospoda se je to zgodilo, čudovito je v naših očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 24, 'To je dan, ki ga storil Gospod, radujmo in veselimo se v njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 25, 'Prosimo, Gospod, reši zdaj, prosimo, Gospod, dobro srečo daj zdaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 26, 'Blagoslovljen, ki prihaja v imenu Gospodovem! blagoslavljamo vas iz hiše Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 27, 'Gospod je Bog mogočni, on nam je dal luč: Privezujte praznične daritve z vrvmi prav do rogov oltarja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 28, 'Bog mogočni si moj, zato te bom hvalil, Bog moj, poviševati te hočem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 118, 29, 'Hvalite Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 1, 'Alef. Blagor njim, ki hodijo brezmadežno po pravem potu, ki živé po postavi Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 2, 'Blagor njim, ki hranijo pričevanja njegova, ki ga iščejo iz vsega srca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 3, 'ki tudi ne delajo krivice, ampak hodijo po potih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 4, 'Ti si zapovedal ukaze svoje, da naj se izpolnjujejo pridno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 5, 'O, da bi pota moja šla tako, da bi izpolnjeval postave tvoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 6, 'Tedaj ne pridem v sramoto, ko bom gledal na vse zapovedi tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 7, 'Hvalil te bom s pravim srcem, ko se bom učil razsodkov pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 8, 'Postave tvoje bom izpolnjeval, le ne zapusti me nikar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 9, 'Bet. Kako ohrani mladenič stezo svojo brez madeža? Držeč se je po besedi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 10, 'Iz vsega srca svojega te iščem, ne daj, da izgrešim zapovedi tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 11, 'V srcu svojem sem shranil govor tvoj, da ne grešim zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 12, 'Hvaljen si, Gospod, uči me postave svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 13, 'Z ustnami svojimi pripovedujem vse sodbe tvojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 14, 'Veselim se pota pričevanj tvojih kakor vseh zakladov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 15, 'Ukaze tvoje bom premišljeval in pazil na steze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 16, 'V postavah tvojih se razveseljujem, besede tvoje ne zabim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 17, 'Gimel. Dobrotno ravnaj s hlapcem svojim, da bom živel, in hraniti hočem besedo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 18, 'Odgrni oči moje, da gledam čuda v zakonu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 19, 'Tujec sem na tej zemlji, ne skrivaj mi zapovedi svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 20, 'Duša moja gine od hrepenenja po pravicah tvojih vsak čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 21, 'Ti pretiš prevzetnim in preklinjaš, kateri izgrešajo zapovedi tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 22, 'Odvali od mene sramoto in zaničevanje, ker hranim pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 23, 'Tudi knezi sedé in govoré zoper mene, a hlapec tvoj premišlja postave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 24, 'Pričevanja tvoja so vendarle razveseljevanja moja, svetovalci moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 25, 'Dalet. V prahu tiči duša moja, oživi me po besedi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 26, 'Pota svoja sem ti naznanjal, in odgovoril si mi; úči me postav svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 27, 'Daj, da umem pot ukazov tvojih, in premišljeval bom čudovita dela tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 28, 'Od otožnosti se v solzah taja duša moja, vzdrži me po besedi svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 29, 'Lažnivosti pot odvrni od mene in pouk zakona svojega mi podéli milostno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 30, 'Zvestobe pot sem izvolil, sodbe tvoje si postavil pred oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 31, 'Držim se tvojih pričevanj, Gospod, ne daj, da se osramotim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 32, 'Po poti zapovedi tvojih bom tekel, ko razširiš srce moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 33, 'He. Uči me, Gospod, postav svojih pot, da jo ohranim do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 34, 'Daj mi razum, da hranim zakon tvoj in ga izpolnjujem iz vsega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 35, 'Daj, da hodim po zapovedi tvojih stezi, ker tá me veseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 36, 'Nagni srce moje k pričevanjem svojim in ne k dobičku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 37, 'Odvrni oči moje, da ne gledajo ničemurnosti, in na potih svojih me oživi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 38, 'Utrdi hlapcu svojemu obljubo svojo, ki je dana v pospeševanje strahu do tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 39, 'Odvrni sramoto mojo, ki se je bojim, ker dobre so sodbe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 40, 'Glej, ukazov tvojih želim, v pravičnosti tvoji daj mi živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 41, 'Vav. Pridejo naj mi milosti tvoje, Gospod, zveličanje tvoje po obljubi tvoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 42, 'tako bom imel kaj odgovoriti njemu, ki me sramoti, ker upanje imam v besedo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 43, 'In ne vzemi docela iz ust mojih besede resnice, ker sodb tvojih čakam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 44, 'In izpolnjeval bom zakon tvoj stanovitno, vedno in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 45, 'In neprestano bom hodil v svobodi, ker postav tvojih iščem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 46, 'Govoriti hočem o pričevanjih tvojih tudi pred kralji, in ne bode me sram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 47, 'In razveseljeval se bom v zapovedih tvojih, ki so se mi omilile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 48, 'In dvignem roke svoje do zapovedi tvojih, ki jih ljubim, in preudarjal bom postave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 49, 'Zajin. Spomni se besede, ki si jo dal hlapcu svojemu, s katero si me utrdil v upanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 50, 'To mi je tolažilo v bridkosti moji, da me je beseda tvoja oživila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 51, 'Prevzetniki so se mi posmehovali silno, a od postave tvoje nisem krenil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 52, 'Spominjal sem se sodb tvojih od nekdaj in se tolažil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 53, 'Togota me je zgrabila spričo brezbožnikov, ki zapuščajo zakon tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 54, 'Sladki spevi so mi postave tvoje v hiši mojega tujčevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 55, 'Po noči se spominjam imena tvojega, Gospod, in zakon tvoj izpolnjujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 56, 'To mi je bilo dano, ker sem hranil ukaze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 57, 'Het. Delež moj je Gospod, rekel sem, da bi izpolnjeval besede tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 58, 'Ponižno molim pred obličjem tvojim iz vsega srca svojega, milost mi izkaži po obljubi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 59, 'Premislil sem pota svoja in obrnil sem noge svoje k pričevanjem tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 60, 'Hitim in se ne obotavljam izpolnjevati zapovedi tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 61, 'Zadrge brezbožnih so me ovile, a postave tvoje ne zabim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 62, 'Opolnoči vstajam hvalit te zavoljo sodb pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 63, 'Tovariš sem vsem, ki se te bojé in izpolnjujejo povelja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 64, 'Milosti tvoje, o Gospod, polna je zemlja, postav svojih me úči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 65, 'Tet. Dobro si storil hlapcu svojemu, Gospod, po besedi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 66, 'Dobre razsodnosti in spoznanja me úči, ker zapovedim tvojim verujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 67, 'Preden sem bil ponižan, sem zahajal v zmote, sedaj pa izpolnjujem govor tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 68, 'Dober si in dobro delaš, úči me postav svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 69, 'Zvijačo so skovali zoper mene prevzetniki, jaz pa iz vsega srca hranim povelja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 70, 'Debelí se kakor z mastjo njih srce, jaz pa se zakona tvojega radujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 71, 'V dobro mi je bilo, da sem bil ponižan, da bi se učil postav tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 72, 'Boljši mi je zakon tvojih ust nego tisoči zlata in srebra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 73, 'Jod. Roke tvoje so me naredile in pripravile, stóri me razumnega, da se učim zapovedi tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 74, 'Kateri se te boje, me bodo videli ter se veselili, ker imam v besedi tvoji nado svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 75, 'Spoznavam, Gospod, da so pravične sodbe tvoje in da si me v zvestobi ponižal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 76, 'Bodi, prosim, milost tvoja mi v tolažbo, po obljubi tvoji hlapcu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 77, 'Dojde naj mi usmiljenje tvoje, da živim, ker zakon tvoj je vse veselje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 78, 'Osramoté se naj prevzetniki, ker so me z lažjo tlačili; jaz pa premišljujem povelja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 79, 'Povrnejo se naj k meni, ki se boje tebe, in tisti, ki poznajo pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 80, 'Srce moje se popolnoma pokoravaj postavam tvojim, da ne pridem v sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 81, 'Kaf. Duša moja koprni po zveličanju tvojem, besede tvoje čakam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 82, 'Oči moje koprne po obljubi tvoji, ko govorim: Kdaj me potolažiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 83, 'Dasi sem podoben mehu v dimu, postav tvojih nisem pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 84, 'Koliko bode dni hlapca tvojega? Kdaj boš sodil nje, ki me preganjajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 85, 'Jame mi kopljejo prevzetniki, ki se ne ravnajo po zakonu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 86, 'Vse zapovedi tvoje so resnica; po krivem me preganjajo, pomagaj mi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 87, 'Skoraj so me uničili na zemlji, jaz pa se nisem izneveril ukazom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 88, 'Po milosti svoji me oživi, in hranil bom pričevanja tvojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 89, 'Lamed. Na vekomaj, o Gospod, je utrjena beseda tvoja v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 90, 'Od roda do roda traja zvestoba tvoja: ustanovil si zemljo, in ona stoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 91, 'Po tvojih naredbah stoji vse še danes, kajti vse stvari služijo tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 92, 'Ako bi ne bil zakon tvoj vse veselje moje, zdavnaj bi že bil poginil v nadlogi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 93, 'Nikdar ne pozabim povelj tvojih, ker ž njimi si me oživil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 94, 'Tvoj sem, reši me, ker ukazov tvojih iščem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 95, 'Ko name prežé brezbožni, da me pogubé, pregledujem pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 96, 'Videl sem, da sleherna stvar, še tako popolna, ima svoj konec, a zapoved tvoja je širna brez meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 97, 'Mem. Kako ljubim zakon tvoj! ves dan je o njem premišljevanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 98, 'Modrejšega od sovražnikov mojih me delajo zapovedi tvoje, ker vekomaj so moja last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 99, 'Razumnejši sem postal od vseh učenikov svojih, ker pričevanja tvoja so premišljevanje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 100, 'Previdnejši sem od starcev, ker hranim povelja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 101, 'Od vsake hudobne steze zadržujem noge svoje, da bi izpolnjeval besedo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 102, 'Od sodb tvojih se ne ganem, ker ti me poučuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 103, 'Kako sladke so grlu mojemu besede tvoje, slajše od medú ustom mojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 104, 'Po poveljih tvojih pridobivam razumnost, zato sovražim vsako stezo lažnivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 105, 'Nun. Svetilo nogi moji je beseda tvoja in stezi moji luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 106, 'Prisegel sem, tudi uveljavil: izpolnjevati razsodke pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 107, 'Ponižan sem silno, Gospod, oživi me po besedi svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 108, 'Prostovoljne daritve ust mojih milo sprejemaj, Gospod, in razsodkov svojih me úči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 109, 'Duša mi je vedno v nevarnosti, vendar ne zabim zakona tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 110, 'Brezbožniki so mi nastavili zanko, vendar od ukazov tvojih ne zahajam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 111, 'Pričevanja tvoja sem prejel v posest na veke, ker so veselje mojemu srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 112, 'Srce svoje sem nagnil, da izpolnjuje postave tvoje vedno do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 113, 'Sameh. Ljudi dvojih misli sovražim, zakon tvoj pa ljubim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 114, 'Zatišje si moje in ščit moj, v besedi tvoji imam nado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 115, 'Umeknite se od mene, hudodelniki, jaz hočem hraniti zapovedi svojega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 116, 'Bodi mi podpora po obljubi svoji, da živim, in ne pusti, da se osramotim v nadi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 117, 'Podpiraj me in varen bodem in gledal bom vedno na postave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 118, 'Vse, ki izgrešujejo postave tvoje, zametaš, kajti laž je, s čimer se slepijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 119, 'Kakor žlindro odpravljaš vse brezbožne na zemlji; zatorej ljubim pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 120, 'Od strahu pred teboj trepeče meso moje in bojim se tvojih sodb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 121, 'Ajin. Pravo sem delal in pravičnost; ne izročaj me njim, ki me stiskajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 122, 'Porok bodi hlapcu svojemu na dobro; naj me ne zatirajo prevzetni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 123, 'Oči moje koprné po zveličanju tvojem in po obljubi pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 124, 'Ravnaj po milosti svoji s hlapcem svojim, in postav svojih me uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 125, 'Hlapec sem tvoj, stori me razumnega, da spoznam pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 126, 'Čas je, da delaš, Gospod, ker v nič so deli zakon tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 127, 'Zatorej bolj ljubim zapovedi tvoje nego zlato, nego najčistejše zlato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 128, 'Zato spoznavam vse ukaze tvoje za prave, vsako stezo lažnivosti sovražim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 129, 'Pe. Čudovita so pričevanja tvoja, zato jih hrani duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 130, 'Komur se beseda tvoja razodene, prejme luč, in razumnost daje ona preprostim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 131, 'Usta svoja sem odprl v hrepenenju, ker žejen sem zapovedi tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 132, 'Ozri se v me in usmili se me, kakor je prav za tiste, ki ljubijo ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 133, 'Noge moje utrdi s poveljem svojim in ne daj, da gospoduje kaka krivica nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 134, 'Otmi me zatiranja ljudi, da izpolnjujem ukaze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 135, 'Daj, da sveti obličje tvoje nad hlapcem tvojim, in uči me postav svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 136, 'Potoki vodá teko iz mojih oči zaradi njih, ki se ne pokoré zakonu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 137, 'Cade. Pravičen si, Gospod, in prave so sodbe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 138, 'Kar si zaukazal v svojih pričevanjih, je pravičnost, in zvestoba popolnoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 139, 'Od gorečnosti svoje ginem, ker so pozabili besede tvoje zatiralci moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 140, 'Dobro preizkušena kakor z ognjem je beseda tvoja, zato jo ljubi hlapec tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 141, 'Majhen sem jaz in zaničevan, a povelj tvojih ne zabim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 142, 'Pravičnost tvoja je pravičnost večna in postava tvoja je resnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 143, 'Zatira in stiska sta me zadeli, zapovedi tvoje pa so veselje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 144, 'Pričevanja tvoja so pravična vekomaj; dodeli mi razumnost, in živel bom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 145, 'Kof. Iz vsega srca kličem, usliši me, o Gospod! hraniti hočem tvoje postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 146, 'Ko te kličem, reši me, in hranil bom pričevanja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 147, 'Jutranji svit sem prehitel, da vpijem; besede tvoje sem čakal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 148, 'Oči moje so prehitevale nočne straže, da bi premišljal govor tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 149, 'Glas moj poslušaj po milosti svoji, Gospod, oživi me po pravdnih naredbah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 150, 'Bližajo se mi tisti, ki jim gre za sramotno delo, ki so daleč od zakona tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 151, 'A ti si blizu, Gospod, in vse zapovedi tvoje so resnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 152, 'Zdavnaj vem iz pričevanj tvojih, da si jih ustanovil na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 153, 'Reš. Ozri se na nadlogo mojo in reši me, ker zakona tvojega ne zabim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 154, 'Prevzemi pravdo mojo in odreši me, po obljubi svoji oživi me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 155, 'Daleč od krivičnih je zveličanje, ker jim ni mar za postave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 156, 'Usmiljenje tvoje je preobilo, Gospod, po sodbah svojih oživi me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 157, 'Dasi je mnogo preganjalcev in stiskalcev mojih, od pričevanj tvojih ne krenem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 158, 'Videl sem nezvestnike, in gnusilo se mi je, ker se ne držé govora tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 159, 'Glej, da ljubim povelja tvoja, Gospod, po milosti svoji oživi me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 160, 'Vsebina besed tvojih je sama resnica, in vekomaj velja vsak razsodek tvoje pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 161, 'Šin. Knezi so me preganjali po nedolžnem, samo pred besedo tvojo je trepetalo moje srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 162, 'Veselim se besede tvoje, kakor kdor je našel plen obilen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 163, 'Laž sovražim in mrzim, zakon tvoj pa ljubim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 164, 'Sedemkrat te hvalim na dan zaradi sodb pravičnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 165, 'Velik mir imajo, kateri ljubijo zakon tvoj, in ni jim spotike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 166, 'Zveličanja tvojega čakam, Gospod, in zapovedi tvoje izpolnjujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 167, 'Duša moja hrani pričevanja tvoja in ljubim jih močno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 168, 'Povelja tvoja hranim in pričevanja tvoja, ker vsa pota moja so pred teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 169, 'Tav. Vpitje moje se bližaj tvojemu obličju, Gospod, daj mi razumnost po besedi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 170, 'Prošnja moja pridi pred obličje tvoje, po obljubi svoji otmi me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 171, 'Hvala bo vrela iz ustnic mojih, ko me boš učil postav svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 172, 'Jezik moj bo prepeval govor tvoj, kajti vse zapovedi tvoje so pravične.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 173, 'V pomoč mi bodi roka tvoja, ker sem izvolil povelja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 174, 'Po zveličanju tvojem hrepenim, Gospod, in zakon tvoj je vse veselje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 175, 'Živi naj duša moja, da hvali tebe, in sodbe tvoje naj pomagajo meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 119, 176, 'Blodim kakor ovca izgubljena, išči svojega hlapca, ker zapovedi tvojih nisem pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 1, '{Pesem stopinj.} H Gospodu sem klical v stiski svoji, in uslišal me je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 2, 'O Gospod, reši dušo mojo usten lažnivih, zvijačnega jezika!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 3, 'Kaj naj ti Bog dá in kaj še pridene, o jezik zvijačni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 4, 'Ostre pšice mogočnega z žerjavico brinovo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 5, 'Gorje meni, da na tujem bivam v Meseku, da stanujem med šatori Kedarcev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 6, 'Predolgo že biva duša moja ž njimi, ki sovražijo mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 120, 7, 'Jaz ljubim mir, ali ko govorim, kličejo oni na boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 1, '{Pesem stopinj.} Oči svoje povzdigam tja h goram: Odkod pride pomoč moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 2, 'Pomoč moja je od Gospoda, ki je naredil nebesa in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 3, 'Saj ne dopusti, da omahne noga tvoja, in varuh tvoj ne zadremlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 4, 'Glej, ne dremlje in ne spi varuh Izraelov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 5, 'Gospod je varuh tvoj, Gospod zaslanjalo tvoje ob desni roki tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 6, 'Po dnevi te ne zadene solnce, ne mesec po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 7, 'Gospod te bo varoval vsega zlega, varoval bo dušo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 121, 8, 'Gospod bo varoval tvoj odhod in tvoj prihod, od tega časa do vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 1, '{Pesem stopinj, Davidova.} Veselim se tega, ko mi pravijo: Pojdimo v hišo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 2, 'Noge naše že stojé med vrati tvojimi, Jeruzalem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 3, 'Jeruzalem, sezidan si kot mesto, popolnoma zvezano med sabo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 4, 'kamor hodijo rodovi, rodovi Gospodovi v pričevanje Izraelu, da hvalijo ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 5, 'Zakaj tam so postavljeni prestoli za sodbo, prestoli hiše Davidove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 6, 'Prosite mirú Jeruzalemu! V blaginji naj živé, ki ljubijo tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 7, 'Mir bodi v obzidju tvojem, pokoj v palačah tvojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 8, 'Zaradi bratov svojih in prijateljev svojih hočem govoriti: Mir v tebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 122, 9, 'Zaradi hiše Gospoda, Boga našega, bom iskal blaginje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 1, '{Pesem stopinj.} K tebi dvigam oči svoje, o ti, ki stoluješ v nebesih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 2, 'Glej, kakor hlapcev oči gledajo na roko gospodarja svojega, kakor dekle oči na roko gospodinje svoje: tako gledajo oči naše v Gospoda, Boga našega, dokler se nas ne usmili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 3, 'Usmili se nas, Gospod, usmili se nas, ker dovolj je, siti smo zaničevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 123, 4, 'Dosti je nasičena duša naša sramočenja lahkoživcev in zaničevanja prevzetnežev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 1, '{Pesem stopinj, Davidova.} Ako bi nam Gospod ne bil na strani, reci zdaj, Izrael,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 2, 'ako bi nam Gospod ne bil na strani, ko so vstali ljudje zoper nas:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 3, 'žive bi nas bili tedaj pogoltnili, ko se je vnela njih jeza proti nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 4, 'Tedaj bi nas bile poplavile vode, hudournik bi bil šel čez dušo našo –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 5, 'tedaj bi bile šle čez dušo našo vode silno prevzetne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 6, 'Slavljen Gospod, ki nas ni izpostavil za plen njih zobem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 7, 'Duša naša je odprhnila kakor ptičica iz ptičarjev zanke: zanka se je pretrgala, in mi smo odprhnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 124, 8, 'Pomoč naša je v imenu Gospodovem, ki je naredil nebesa in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 1, '{Pesem stopinj.} Kateri upajo v Gospoda, so podobni gori Sionski, ki se ne gane, vekomaj trdna ostane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 2, 'Kakor obdajajo Jeruzalem gore, tako obdaja Gospod ljudstvo svoje od tega časa na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 3, 'Zakaj žezlo krivice ne bo počivalo nad deležem pravičnih, da ne iztegnejo pravični po krivici rok svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 4, 'Z dobrotami obsiplji, o Gospod, dobre in nje, ki so pošteni v srcih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 125, 5, 'Kateri pa zavijajo na kriva pota svoja – zapodi naj jih Gospod s hudodelci vred! Mir nad Izraelom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 1, '{Pesem stopinj.} Ko je Gospod nazaj peljal jetnike sionske, nam je bilo kakor v sanjah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 2, 'Tedaj so se smeha napolnila usta naša in jezik naš z radostnim petjem. Tedaj so rekli med pogani: Veličastne reči je ž njimi storil Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 3, 'Veličastne reči je storil z nami Gospod, veseli smo bili!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 4, 'Pripelji nazaj, o Gospod, jetnike naše kakor potoke v suho deželo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 5, 'Kateri sejejo s solzami, z radostnim bodo želi petjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 126, 6, 'Kdorkoli hodi semtertja z jokom, noseč seme za setev, vrne se domov z glasnim petjem, noseč snope svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 1, '{Pesem stopinj, Salomonova.} Ako Gospod ne zida hiše, zaman se trudijo, ki jo zidajo. Ako Gospod ne varuje mesta, zaman bedi priden čuvaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 2, 'Zaman je, da vstajate pred svitom in pozno hodite počivat in jeste kruh mnogega truda: toliko daje Bog ljubljencu svojemu v spanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 3, 'Glej, posest Gospodova so otroci, plačilo njegovo sad telesni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 4, 'Kakor pšice v roki junakovi, tako so otroci mladih let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 127, 5, 'O, blagor možu, ki je napolnil tul svoj ž njimi! Ne bodo osramočeni, ko govore s sovražniki svojimi med vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 1, '{Pesem stopinj.} Blagor mu, kdorkoli se boji Gospoda, kdor hodi po potih njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 2, 'Delo namreč rok svojih boš užival, srečen bodeš in dobro ti bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 3, 'Žena tvoja bode kakor trta rodovitna znotraj v hiši tvoji, otroci tvoji kakor oljkovo mladje okrog mize tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 4, 'Glej, tako bode blagoslovljen mož, ki se boji Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 5, 'Blagoslovi naj te Gospod s Siona, in uživaj srečo Jeruzalema vse dni življenja svojega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 128, 6, 'in glej sinov svojih sinove! Mir nad Izraelom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 1, '{Pesem stopinj.} Mnogo so me stiskali od mladosti moje, govori naj sedaj Izrael,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 2, 'mnogo so me stiskali od mladosti moje, vendar me niso zmogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 3, 'Po hrbtu so mi orali orači, dolge so rezali brazde svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 4, 'Gospod je pravičen: presekal je debele vrvi brezbožnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 5, 'Osramočeni naj bodo in nazaj pognani vsi sovražilci Siona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 6, 'Bodo naj kakor trava na strehah, ki usahne, preden vzraste,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 7, 's katero ne napolni roke svoje ženjec, ne naročja svojega, kdor veže snopke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 129, 8, 'in mimogredoči ne poreko: Blagoslov Gospodov bodi z vami! Blagoslavljamo vas v imenu Gospodovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 1, '{Pesem stopinj.} Iz globočin vpijem k tebi, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 2, 'Gospod, poslušaj glas moj, ušesa tvoja naj pazijo na prošenj mojih glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 3, 'Ako boš gledal na krivice, Jehova, Gospod, kdo more obstati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 4, 'Toda pri tebi je odpuščenje, da te časté s svetim strahom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 5, 'Čakam Gospoda, čaka duša moja, in v besedi njegovi imam nado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 6, 'Duša moja hrepeni po Gospodu bolj ko stražarji po jutru, ki čujejo do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 7, 'Nado imej, Izrael, v Gospodu, ker pri Gospodu je milost in obilo je pri njem odrešenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 130, 8, 'In on odreši Izraela vseh krivic njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 1, '{Pesem stopinj, Davidova.} Gospod, srce moje se ne napihuje in oči se ne povzdigujejo, in ne pečam se z rečmi, ki so prevelike in prečudovite zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 2, 'Zares, pomiril sem in utešil srce svoje; kakor dete, odstavljeno od prsi, pri materi svoji, kakor odstavljeno dete je pri meni duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 131, 3, 'Nado imej, Izrael, v Gospodu, od tega časa in na vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 1, '{Pesem stopinj.} Spominjaj se, o Gospod, Davidu vsega truda njegovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 2, 'Kako je prisegel Gospodu, obljubil Mogočnemu Jakobovemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 3, 'Ne pojdem v hiše svoje šator, ne stopim na posteljo ležišča svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 4, 'spanja ne dam očem svojim, dremanja trepalnicam svojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 5, 'dokler ne najdem mesta za Gospoda, bivališča za Mogočnega Jakobovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 6, 'Glej, skrinja zaveze je bila, kakor smo slišali, v Efrati, našli smo jo na poljanah Jaarskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 7, 'Pojdimo v šatore njegove, priklanjajmo se pred nog njegovih podnožjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 8, 'Vstani, Gospod, stopi v počivališče svoje, ti in skrinja moči tvoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 9, 'Duhovniki tvoji naj se oblečejo s pravičnostjo in sveti tvoji naj pojó veselo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 10, 'Zavoljo Davida, hlapca svojega, ne zavrni maziljenca svojega obličja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 11, 'Prisegel je Gospod Davidu resnico, od katere ne bo odstopil: „Od sadú telesa tvojega posadim na prestol tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 12, 'Ako se bodo držali zaveze moje sinovi tvoji in pričevanj mojih, katerih jih bom učil, bodo tudi njih sinovi vekomaj sedeli na prestolu mojem.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 13, 'Zakaj Gospod je izvolil Sion, želel si ga je za prebivališče svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 14, 'To je počivališče moje vekomaj, tu bom prebival, ker njega sem si želel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 15, 'Hrano njegovo bom bogato blagoslovil, potrebne njegove nasitim s kruhom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 16, 'in duhovnike njegove oblečem z zveličanjem, in sveti njegovi bodo veselo peli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 17, 'Storim, da tam požene rog Davidu, kjer sem pripravil svetilo maziljencu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 132, 18, 'Sovražnike njegove ogrnem s sramoto, nad njim pa bo cvetel venec njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 1, '{Pesem stopinj, Davidova.} Glej, kako dobro in kako prijetno, da složno bratje prebivajo skupaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 2, 'Kakor dragoceno mazilo, razlito čez glavo, ki kaplja na brado, brado Aronovo, ki kaplja tja do roba obleke njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 133, 3, 'Kakor rosa hermonska, ki pada na gore sionske; kajti tja pošilja Gospod blagoslov svoj, življenje do vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 1, '{Pesem stopinj.} Glejte, slavite Gospoda, vsi hlapci Gospodovi, ki služite v hiši Gospodovi vsako noč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 2, 'Povzdigujte roke svoje proti svetišču in slavite Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 134, 3, 'Blagoslóvi te s Siona Gospod, ki je naredil nebesa in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 1, 'Aleluja! Hvalite ime Gospodovo, hvalite ga, Gospodovi hlapci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 2, 'ki stojite v hiši Gospodovi, v vežah hiše našega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 3, 'Hvalite Gospoda, ker dober je Gospod, prepevajte psalme imenu njegovemu, ker je sladko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 4, 'Kajti Jakoba si je izvolil Gospod, Izraela sebi v last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 5, 'Zakaj jaz vem, da je velik Jehova in Gospod naš nad vse bogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 6, 'Karkoli mu je po volji, dela Gospod v nebesih in na zemlji, v morjih in v vseh breznih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 7, 'On pripeljava sopare od kraja zemlje, bliske dela za dež, vetrove jemlje iz zakladnic svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 8, 'On je udaril prvorojence v Egiptu, od človeka pa do živine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 9, 'Poslal je znamenja in čuda v sredo tvojo, Egipt, zoper Faraona in vse hlapce njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 10, 'On je udaril narode mnoge in pobil kralje mogočne,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 11, 'Sihona, kralja amorejskega, in Oga, kralja basánskega, in vsa kraljestva kanaanska,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 12, 'in dal je njih deželo v dediščino, v dediščino Izraelu, ljudstvu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 13, 'O Gospod, ime tvoje traja vekomaj, Gospod, spomin tvoj od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 14, 'Kajti Gospod se potegne za pravdo ljudstva svojega in žal mu bode hlapcev svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 15, 'Maliki poganov so zlato in srebro, rok človeških delo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 16, 'usta imajo, a ne govore, oči imajo, a ne vidijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 17, 'ušesa imajo, ali ne slišijo, tudi sape ni nič v njih ustih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 18, 'Enaki jim naj bodo, kateri jih delajo in kdorkoli vanje upa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 19, 'Hiša Izraelova! slavite Gospoda! hiša Aronova, slavite Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 20, 'Hiša Levijeva, slavite Gospoda! kateri se bojite Gospoda, slavite Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 135, 21, 'Slava Gospodu s Siona, ki prebiva v Jeruzalemu! Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 1, 'Zahvaljujte Gospoda, ker je dobrotljiv, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 2, 'Zahvaljujte Boga bogov, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 3, 'Zahvaljujte gospodov Gospoda, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 4, 'Njega, ki edini dela čuda velika, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 5, 'Ki je ustvaril nebesa z umnostjo, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 6, 'Ki je razprostrl zemljo nad vodami, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 7, 'Ki je naredil luči velike, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 8, 'Solnce, da gospoduje po dnevi, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 9, 'Mesec z zvezdami, da gospodujejo po noči, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 10, 'Ki je udaril Egipčane v njih prvorojencih, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 11, 'In je izpeljal Izraela izmed njih, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 12, 'Z močno roko in z iztegnjeno ramo, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 13, 'Ki je razdelil Rdeče morje, ker vekomaj traja milost njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 14, 'in peljal Izraela po sredi njegovi, ker vekomaj traja milost njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 15, 'in pahnil Faraona in vojsko njegovo v Rdeče morje, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 16, 'Ki je peljal ljudstvo svoje skozi puščavo, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 17, 'Ki je udaril kralje velike, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 18, 'In pobil je kralje veličastne, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 19, 'Sihona, kralja amorejskega, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 20, 'In Oga, kralja basánskega, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 21, 'In dal je njih deželo v dediščino, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 22, 'V dediščino Izraelu, svojemu hlapcu, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 23, 'Ki se nas je spomnil v ponižanju našem, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 24, 'In nas je otel nasprotnikov naših, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 25, 'Ki daje hrane vsemu mesu, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 136, 26, 'Zahvaljujte Boga mogočnega nebes, ker vekomaj traja milost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 1, 'Ob rekah babilonskih, tam smo sedevali in jokali, spominjajoč se Siona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 2, 'Na vrbe sredi one dežele smo obesili strune svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 3, 'Kajti ondi so zahtevali od nas besede pesmi tisti, ki so nas odpeljali v sužnost, in naši mučitelji so hoteli veselost: Pojte nam katero pesmi sionskih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 4, 'Kako naj bi peli pesem Gospodovo v tujcev deželi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 5, 'Če pozabim tebe, Jeruzalem, pozabi naj mi desnica zmožnosti svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 6, 'Jezik naj se mi prijemlje nébesa, ako se ne spominjam tebe, ako ne stavim Jeruzalema nad največje veselje svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 7, 'Spomni se, Gospod, zoper Edomce dneva jeruzalemskega, ki so rekli: Razvalite, razvalite, dokler bode kaj podzidja v njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 8, 'O hči babilonska, boš pokončana; blagor mu, kdor ti povrne tisto, kar si nam storila!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 137, 9, 'Blagor mu, kdor zgrabi in razbije otroke tvoje ob skalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 1, '{Psalm Davidov.} Hvalil te bom iz vsega srca svojega, vpričo oblastev ti bom psalme prepeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 2, 'Priklanjal se bom proti templju svetosti tvoje in slavil ime tvoje zavoljo milosti in resnice tvoje; kajti poveličal si čez vse ime svoje besedo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 3, 'V dan, ko sem vpil, si mi odgovoril: vdahnil si mi pogum, duša se mi je pokrepčala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 4, 'Hvalili te bodo, Gospod, vsi kralji zemlje, ko bodo slišali govor tvojih ust,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 5, 'in opevali bodo poti Gospodove, da je velika slava Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 6, 'Kajti vzvišen je Gospod, vendar gleda na nizkega, a prevzetnega spozna oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 7, 'Ako hodim po sredi stiske, ohraniš me živega; zoper jezo sovražnikov mojih iztegneš roko svojo, in desnica tvoja me reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 138, 8, 'Gospod dovrši vse za mene. Gospod, milost tvoja traja vekomaj, del rok svojih ne zapústi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 1, '{Načelniku godbe. Psalm Davidov.} Gospod, preiskal si me in me poznaš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 2, 'Ti poznaš sedenje moje in vstajanje moje, mišljenje moje umeš oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 3, 'Hojo mojo in ležo mojo zasleduješ in znana so ti vsa pota moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 4, 'Ko ni še beseda na jeziku mojem, glej, Gospod, jo poznaš docela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 5, 'Zadaj in spredaj me obdajaš in name pokladaš roko svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 6, 'Taka vednost je prečudovita zame, visoka je, ne morem je doseči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 7, 'Kam naj grem pred duhom tvojim, ali kam naj bežim pred tvojim obličjem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 8, 'Ko bi stopil na nebesa, tam si ti, ali bi ležišče si izbral v kraju mrtvih, tudi ondi si.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 9, 'Ko bi si vzel zarje peruti in odletel prebivat ob najzadnjem kraju morja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 10, 'tudi tja bi me spremljala roka tvoja in zgrabila bi me desnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 11, 'Ko bi pa rekel: Teme me bodo vsaj pokrile in svetloba okoli mene postane naj noč –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 12, 'tudi teme ti ne morejo ničesar omračiti, noč ti je svetla kakor dan, temina ti je kakor noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 13, 'Zakaj ti si imel v lasti ledice moje, stkal si me v telesu matere moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 14, 'Hvalim te, da sem storjen na strašen, čudovit način; čudovita so dela tvoja, predobro to pozna duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 15, 'Ni ti bilo skrito okostje moje, ko sem bil ustvarjen na skrivnem, umetno narejen, kakor v zemlje globočinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 16, 'Zarodek moj so videle tvoje oči, in v knjigo tvojo je bilo vpisano vse to; dnevi so mi bili določeni, ko še eden njih ni bil napočil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 17, 'Zatorej kako so mi dražestne misli tvoje, o Bog mogočni, kako ogromna so njih števila!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 18, 'Hotel bi jih našteti, a več jih je od peska; kadar se zdramim, sem z mislimi še pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 19, 'O da bi pokončal, o Bog, brezbožnika! In vi, možje krvoločni: Poberite se izpred mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 20, 'Kajti zoper tebe govoré pregrešno, tvoje ime rabijo za laž tvoji sovražniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 21, 'Ali naj bi ne sovražil, o Gospod, sovražilcev tvojih, ali naj mi ne mrzé, ki se vzpenjajo zoper tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 22, 'S skrajnim sovraštvom jih sovražim, za neprijatelje so meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 23, 'Preiskuj me, Bog mogočni, in spoznaj srce moje, izkusi me in spoznaj misli moje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 139, 24, 'in glej, hodim li po potu, ki pelje v trpljenje, in vodi me po večnem potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 1, '{Načelniku godbe. Psalm Davidov.} Reši me, Gospod, hudobnih ljudi, moža silovitega me brani,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 2, 'kateri mislijo hudo v srcu, vsak dan se shajajo, da snujejo vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 3, 'Brusijo jezik svoj, da je podoben kačjemu, strup gadji je pod njih ustnami. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 4, 'Obvaruj me, Gospod, rok krivičnika, moža silovitega me brani, ki mi mislijo izpodbiti noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 5, 'Skrivaj so mi nastavili prevzetniki zanko in vrvi, razgrnili so mi mrežo poleg pota, zadrge mi napravili. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 6, 'Rekel sem Gospodu: Bog mogočni moj si ti; čuj, Gospod, prošenj mojih glas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 7, 'Jehova, Gospod, je moč zveličanja mojega; glavo mojo si pokril ob dnevi boja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 8, 'Ne dopusti, Gospod, da se brezbožniku izpolnijo želje, hude naklepe njegove ne pospešuj, povzdigovali bi se! (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 9, 'Glave njih, ki me obdajajo – ustnic njih nadloga naj jih pokrije!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 10, 'Žerjavica pridi nadnje, v ogenj naj jih vržejo, v jame, odkoder več ne vstanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 11, 'Mož zbadljivega jezika se ne utrdi na zemlji; mož silovitosti – hudo ga bo gonilo do pogube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 12, 'Vem, da se bo Gospod potegnil za pravdo siromaku, za pravico potrebnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 140, 13, 'Res, pravični bodo hvalili ime tvoje, pošteni bivali pred tvojim obličjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 1, '{Psalm Davidov.} O Gospod, kličem te, hiti k meni, čuj glas moj, ko te kličem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 2, 'Molitev moja pridi kakor kadilo pred tebe, povzdigovanje mojih rok kakor daritev večerna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 3, 'Postavi, Gospod, stražo ustom mojim, čuvaj vrata ustnic mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 4, 'Ne daj, da se mi nagne srce k hudobni reči, da bi brezbožno izvrševal hudobije z možmi, ki delajo krivice; tudi naj ne okusim njih slaščic!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 5, 'Udari naj me pravični, ljubezen je to, in posvari naj me, je kakor mazilo glavi: ne brani se glava moja; zakaj tudi pri njih krivičnosti vztrajam v molitvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 6, 'Ko popadajo raz skale njih sodniki, bodo poslušali besede moje, ker so prijetne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 7, 'Kakor bi kdo razsekal in razklal zemljo, so raztresene kosti naše do žrela groba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 8, 'Toda k tebi, Jehova, Gospod, se ozirajo oči moje, v tebi iščem zavetja, ne zapústi duše moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 9, 'Obvaruj me zadrge, ki so mi jo razpeli, in zank tistih, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 141, 10, 'Zapleto naj se v mreže svoje brezbožni, a jaz grem varno mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 1, '{Pouk Davidov, ko je bil v votlini. Molitev.} Z glasom svojim kličem h Gospodu, z glasom svojim milo prosim Gospoda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 2, 'pred njim izlivam skrbi svoje, stisko svojo oznanjam pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 3, 'Ko je omagoval moj duh v meni, takrat si ti poznal stezo mojo. Na poti, po kateri sem hodil, so mi skrivaj nastavili zanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 4, 'Ozri se na desno in poglej: ni ga, ki bi me poznal; izginilo mi je vsako zavetje, ni ga, ki bi skrbel za dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 5, 'K tebi kličem, Gospod, govoreč: Ti si zavetje moje, delež moj v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 6, 'Poslušaj vpitje moje, ker ponižan sem silno, otmi me preganjalcev mojih, ker močnejši so od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 142, 7, 'Izpelji iz zapora dušo mojo, da hvalim ime tvoje; tedaj me bodo obdali pravični, ko mi izkažeš dobroto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 1, '{Psalm Davidov.} O Gospod, sliši molitev mojo, ušesa nagni k prošnjam mojim; v zvestobi svoji mi odgovori in v pravičnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 2, 'In ne hodi v sodbo s hlapcem svojim, ker pravičen ni pred tabo nihče, ki živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 3, 'Kajti sovražnik preganja dušo mojo, tlači na tla življenje moje, dela, da sedim v teminah kakor tisti, ki so mrtvi za vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 4, 'In duh moj v meni omaguje, srce mi je otrpnilo v notranjščini moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 5, 'Spominjam se dni nekdanjih, premišljujem vse delo tvoje, dejanje tvojih rok preudarjam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 6, 'Roke svoje razprostiram proti tebi, duša moja kakor zemlja razsušena hrepeni po tebi. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 7, 'Hitro mi odgovóri, Gospod! duh moj hira; ne skrivaj mi obličja svojega, da ne postanem podoben njim, ki se pogrezajo v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 8, 'Daj, da slišim zgodaj milost tvojo, ker nate stavim upanje; naznani mi pot, po kateri naj hodim, zakaj k tebi povzdigujem dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 9, 'Otmi me sovražnikov mojih, Gospod! pri tebi sem skrit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 10, 'Uči me delati po volji tvoji, ker ti si moj Bog, z dobrim duhom svojim me spremljaj po ravni zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 11, 'Zavoljo imena svojega, Gospod, me ohrani živega, v pravičnosti svoji izpelji iz stiske dušo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 143, 12, 'In zavoljo milosti svoje iztrebi sovražnike moje, pokončaj vse, ki stiskajo dušo mojo, ker jaz sem hlapec tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 1, '{Davidov.} Hvaljen bodi Gospod, skala moja, ki vadi roke moje za boj, prste moje za vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 2, 'milost moja in grad moj, visoka trdnjava moja in rešitelj moj, ščit moj in zavetje, kamor pribegam, ki mi podložno dela ljudstvo moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 3, 'Gospod, kaj je človek, da ti je v čislu, sin smrtnikov, da se meniš zanj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 4, 'Človek je podoben dihu, dnevi njegovi so kakor mimogredočega senca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 5, 'Gospod, nagni nebesa svoja ter stopi doli, dotakni se gorá, in se bodo kadile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 6, 'Strelo zaženi in razkropi jih, izstreli pšice svoje in zbegaj jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 7, 'Iztegni roko svojo z višave, reši me in otmi me iz mnogih vodá, iz roke tujcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 8, 'Njih usta govore ničevost in njih desnica je lažnivosti desnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 9, 'Bog, novo pesem ti bom pel, na deseterostrunje ti psalme prepeval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 10, 'tebi, ki daješ rešitev kraljem, otimlješ Davida, hlapca svojega, pogubnega meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 11, 'Reši me in otmi me iz roke tujcev, katerih usta govoré ničevost, in njih desnica je lažnivosti desnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 12, 'Da bodo sinovi naši kakor rastline, dobro zrejene v nežni dobi svoji, in hčere naše kakor vogelni stebri, obdelani po zidavi svetišča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 13, 'žitnice naše da bodo polne in bodo dajale mnogoteren živež, naše ovce da tisočero rodevajo, desettisočkrat da bodo pomnožene na pašnikih naših,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 14, 'in goved naša breja; nič napada, nič predaje, nič jadikovanja da ne bode v ulicah naših!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 144, 15, 'Blagor ljudstvu, ki se mu tako godi, blagor ljudstvu, čigar Bog je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 1, '{Hvalnica Davidova.} Poviševati te hočem, Bog moj in Kralj, in slaviti ime tvoje vedno in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 2, 'Vsak dan te bom slavil in hvalil ime tvoje vedno in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 3, 'Velik je Gospod in hvale vreden jako in velikosti njegove ni preiskati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 4, 'Rod naj rodu slavi dela tvoja in oznanjajo naj junaške čine tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 5, 'Lepoto in slavo tvojega veličastva in čudovite stvari tvoje bom premišljeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 6, 'In moč strašnih del tvojih naj slavé; in velika dela tvoja bom pripovedoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 7, 'Spomin obile dobrote tvoje naj vre iz njih in o pravičnosti tvoji naj glasno pojó.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 8, 'Milosten in usmiljen je Gospod, počasen v jezo in velik v milosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 9, 'dobrotljiv je Gospod vsem in usmiljenje njegovo gre čez vsa dela njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 10, 'Hvalijo te naj, Gospod, vsa dela tvoja, in slavé te naj tisti, ki jim izkazuješ milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 11, 'Slavo kraljestva tvojega naj razglašajo in govoré o mogočnosti tvoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 12, 'da oznanijo sinom človeškim slavne čine njegove in slavo in lepoto njegovega kraljestva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 13, 'Kraljestvo tvoje je vseh vekov kraljestvo in gospostvo tvoje od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 14, 'Gospod podpira vse, ki padajo, in kvišku pomaga vsem potlačenim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 15, 'Vseh oči zaupno gledajo vate, in ti jim daješ njih jed o pravem času;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 16, 'roko svojo odpiraš in sitiš, karkoli živi, po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 17, 'Pravičen je Gospod na vseh potih svojih in milostiv v vseh svojih delih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 18, 'Blizu je Gospod vsem, ki ga kličejo, vsem, ki ga kličejo v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 19, 'Voljo izpolnjuje njim, ki se ga bojé, vpitje njih sliši in jih rešuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 20, 'Gospod hrani vse, kateri ga ljubijo, vse brezbožnike pa pogublja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 145, 21, 'Hvalo Gospodovo naj torej govore usta moja, in vse meso naj slavi sveto ime njegovo vedno in vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 1, 'Aleluja! Hvali, duša moja, Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 2, 'Hvalil bom Gospoda v življenju svojem, psalme prepeval Bogu svojemu, dokler bodem živ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 3, 'Ne zanašajte se na poglavarje, na sina človeškega, pri katerem ni rešitve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 4, 'Duh njegov izide, pa se povrne v prah svoj, isti dan minejo vse misli njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 5, 'Blagor mu, komur je pomočnik Bog mogočni Jakobov, čigar nada je v Gospodu, Bogu njegovem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 6, 'ki je ustvaril nebesa in zemljo, morje in karkoli je v njih; ki hrani resnico vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 7, 'ki pridobiva pravico zatiranim, hrane daje lačnim. Gospod oprošča jetnike,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 8, 'Gospod odpira oči slepim, Gospod vzdiguje potrte, Gospod ljubi pravične,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 9, 'Gospod brani tujce, siroto in vdovo podpira, pot brezbožnih pa podira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 146, 10, 'Vladal bo Gospod vekomaj, Bog tvoj, o Sion, od roda do roda. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 1, 'Hvalite Gospoda! Zakaj dobro je pevati psalme Bogu našemu, ker prijetno je to, in spodobno je hvaljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 2, 'Stavitelj Jeruzalema je Gospod, on zbira razkropljence Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 3, 'On ozdravlja potrte v srcu in obvezuje njih rane;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 4, 'prešteva zvezd število, kliče jih, kolikor jih je, po imenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 5, 'Velik je Gospod naš in mnoga moč njegova, modrost njegova je brezmerna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 6, 'Krotke podpira Gospod, brezbožnike pa potiska prav do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 7, 'Pojte hvalne pesmi Gospodu, s strunami prepevajte psalme Bogu našemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 8, 'Ki zagrinja z gostimi oblaki nebo, ki pripravlja dež zemlji, ki daje, da seno rojevajo gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 9, 'Živini daje njen živež in mladim krokarjem, ki čivkajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 10, 'Moči konjeve se ne veseli, stegna vojščakova mu niso po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 11, 'Po volji so Gospodu tisti, ki se ga bojé, ki imajo nado v milosti njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 12, 'S hvalo slávi, Jeruzalem, Gospoda, hvali Boga svojega, o Sion!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 13, 'Zakaj utrdil je zapahe tvojih vrat, sinove tvoje je blagoslovil sredi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 14, 'On, ki daje mir pokrajinam tvojim, z mezgo pšenice te siti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 15, 'ki pošilja povelje svoje na zemljo, urno teče beseda njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 16, 'ki daje sneg kakor volno, slano razsiplje kakor pepel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 17, 'led svoj meče doli kakor kosčke, mraz njegov kdo prebije?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 18, 'Besedo svojo pošlje, in vse raztaja; kakor hitro pihne veter njegov, že tekó vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 19, 'Besedo svojo je naznanil Jakobu, postave svoje in pravice Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 147, 20, 'Ni storil tako nobenemu narodu, zato sodb njegovih niso spoznali. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 1, 'Aleluja! Hvalite Gospoda, vsi iz nebes, hvalite ga na višavah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 2, 'Hvalite ga, vsi angeli njegovi, hvalite ga, vse vojske njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 3, 'Hvalite ga, solnce in mesec, hvalite ga, vse svetle zvezde!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 4, 'Hvalite ga, nebes nebesa, in vode, katere so nad nebom –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 5, 'hvalijo naj ime Gospodovo! kajti on je rekel, in so bili ustvarjeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 6, 'in utrdil jih je za vselej in na veke; dal je zapoved, ki je nihče ne prestopi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 7, 'Hvalite Gospoda, vsi iz zemlje, zmaji in brezna vsa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 8, 'ogenj in toča, sneg in sopara, veter viharni, ki izpolnjuješ besedo njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 9, 've gore in vsi hribi, drevesa sadonosna in vse cedre,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 10, 'ti zverina in vsa živina, laznina in ptiči krilati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 11, 'kralji zemeljski in narodi vsi, knezi in vsi zemljé sodniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 12, 'mladeniči in tudi device, starci z dečki vred –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 13, 'naj hvalijo ime Gospodovo! kajti vzvišeno je ime njegovo, On sam, slava njegova sega čez zemljo in nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 148, 14, 'In povišal je rog svojemu ljudstvu, hvalo vseh svetih svojih, sinom Izraelovim, ljudstvu, ki mu je blizu. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 1, 'Aleluja! Pojte Gospodu pesem novo in hvalo njegovo v zboru svetih njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 2, 'Izrael naj se veseli v njem, ki ga je ustvaril, sinovi sionski naj se radujejo v Kralju svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 3, 'Hvalijo naj ime njegovo s plesom, z bobnom in s strunami naj mu psalme prepevajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 4, 'Kajti veseli se Gospod ljudstva svojega, krotke diči z zveličanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 5, 'Radujejo se naj v slavi sveti njegovi, pojó naj od veselja na ležiščih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 6, 'Hvala, povišujoča Boga mogočnega, naj jim polni grlo in meč dvorezni naj imajo v roki svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 7, 'da izvršé maščevanje nad narodi in pokoré ljudstva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 8, 'da zvežejo z verigami njih kralje in njih plemenitnike z vezmi železnimi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 149, 9, 'da nad njimi izvršé sodbo, ki je pisana. Čast je to vsem svetim njegovim. Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 1, 'Aleluja! Hvalite Boga mogočnega v svetišču njegovem, hvalite ga v veličastva njegovega gradu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 2, 'Hvalite ga zaradi junaških činov njegovih, hvalite ga po velikem veličastvu njegovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 3, 'Hvalite ga s trombe glasom, hvalite ga s citrami in harfami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 4, 'Hvalite ga z bobni in s plesom, hvalite ga s strunami in piščalmi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 5, 'Hvalite ga z miloglasnimi cimbali, hvalite ga z gromkimi cimbali! —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (19, 150, 6, 'Vsak duh naj hvali Gospoda! Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 1, 'Pregovori Salomona, sina Davidovega, kralja izraelskega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 2, 'da se spozna modrost in uk, da se umejo razumnosti besede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 3, 'da se sprejme pouk v modrem vedenju, v pravičnosti, pravi sodbi in poštenosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 4, 'da se dá preprostim pamet, mladeniču spoznanje in razsodnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 5, 'Čul jih bo modri in napredoval v znanosti, in razumnik si pridobode modrih vodil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 6, 'da razume pregovore in skrivnostne izreke, besede modrih in njih uganke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 7, 'Strah Gospodov je začetek znanja; modrost in pouk zaničujejo neumneži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 8, 'Poslušaj, sin moj, očeta svojega pouk in ne zametuj nauka matere svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 9, 'kajti krasen venec je to glavi tvoji in verižica zlata tvojemu grlu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 10, 'Sin moj, ako te vabijo grešniki, se jim ne vdaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 11, 'Ako govore: „Pojdi z nami, na kri prežímo, nedolžnega zalezujmo brez vzroka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 12, 'pogoltnimo jih žive, kakor jih požira smrtni kraj, in nepoškodovane, kakor da bi naglo padli v jamo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 13, 'vsakršno drago blago si pridobimo, s plenom napolnimo hiše svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 14, 'srečo izkusi sredi nas, ena mošnja bodi nam vsem!“–');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 15, 'sin moj, ne hodi po poti ž njimi, zdrži nogo svojo od njih steze!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 16, 'Ker njih noge tečejo za hudim in kri hité prelivat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 17, 'Res, zaman se razpenja mreža pred očmi vsakega ptiča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 18, 'oni pa – sami na svojo kri preže, zalezujejo lastne duše svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 19, 'Take so steze njih, ki iščejo krivičnega dobička: jemlje dušo njim, ki si ga lasté.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 20, 'Modrost glasno kliče zunaj, na ulicah zaganja svoj glas;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 21, 'vpije, kjer se največ ljudstva gnete, ob vhodu v vrata, v mestu, govori besede svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 22, 'Doklej, o preprosti, boste ljubili nespamet in, zasmehovalci, imeli veselje v zasmehovanju in, bedaki, sovražili znanje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 23, 'Obrnite se k svarjenju mojemu! Glejte, izlijem vam duha svojega, oznanjala vam bom besede svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 24, 'Toda, ko sem klicala, ste se branili, ko sem iztezala roko svojo, nihče se ni zmenil zanjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 25, 'temuč prezirali ste vse svete moje in svarila mojega si niste želeli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 26, 'zato se bom tudi jaz smejala v nesreči vaši in vas zasmehovala, kadar pride, česar se bojite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 27, 'kadar pride kakor besneča uima, česar se bojite, in se približa nesreča vaša kakor nevihta, ko pridere nad vas stiska in nadloga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 28, 'Tedaj me bodo klicali, pa jim ne odgovorim, skrbno me bodo iskali, a ne najdejo me:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 29, 'zato ker so sovražili znanje in strahu Gospodovega niso izvolili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 30, 'svetov mojih niso hoteli, a zaničevali so vse svarjenje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 31, 'Zato bodo jedli od sadu pota svojega in sitili se z naklepi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 32, 'Zakaj bebcev upor jih ubije in brezkrbnost bedakov jih pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 1, 33, 'Kdor pa mene posluša, brez skrbi bo prebival in mir užival, ne boječ se hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 1, 'Sin moj, ako sprejmeš besede moje in pri sebi shraniš zapovedi moje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 2, 'tako da nagneš uho svoje k modrosti in srce obrneš k razumnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 3, 'če zakličeš previdnost in do umnosti zaženeš svoj glas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 4, 'če je iščeš kakor srebra in jo zasleduješ kakor skrite zaklade:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 5, 'tedaj boš razumel strah Gospodov in dosežeš spoznanje Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 6, 'Kajti Gospod daje modrost, iz njegovih ust prihaja spoznanje in razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 7, 'On je zavaroval uspeh poštenim, ščit je njim, ki žive brezmadežno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 8, 'da bi vztrajali na potih pravice; on čuva hojo svetnikov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 9, 'Tedaj boš razumel pravičnost in pravo sodbo in karkoli je pošteno, sleherno dobro stezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 10, 'Kajti modrost pride v srce tvoje in znanje bode prijetno duši tvoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 11, 'razsodnost bo pazila nate, umnost te bo stražila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 12, 'da te otme slabega pota, mož, ki spačenosti govoré,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 13, 'ki zapuščajo pota poštenja, da bi hodili po stezah teme,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 14, 'ki jim je veselje delati zlo, radujejo se v spačenostih najhujših,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 15, 'katerih pota so kriva, trdovratni so na stezah svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 16, 'da te otme žene tuje, tujke, ki se dobrika z besedami gladkimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 17, 'ki zapušča mladosti svoje vodnika in zabi Boga svojega zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 18, 'Kajti v smrt se nagiblje hiša njena in v smrtne sence njene steze:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 19, 'katerikoli zahajajo k njej, ne povrnejo se in ne dosežejo življenja potov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 20, 'Zato hódi po potu dobrih in vztrajaj na stezah pravičnikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 21, 'Zakaj pošteni bodo prebivali v deželi in brezmadežni ostanejo v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 2, 22, 'Brezbožne pa bodo iztrebili iz dežele in nezveste izpulili iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 1, 'Sin moj, nauka mojega ne zabi, temuč zapovedi moje naj hrani srce tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 2, 'kajti dni dolgost in življenje mnogoletno in mir ti dodelé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 3, 'Milost in resnica naj te ne zapustita; priveži ju okrog grla svojega, zapiši ju na srca svojega deščico:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 4, 'tako dosežeš milost in uspeh najboljši, pred očmi Božjimi in človeškimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 5, 'Upaj v Gospoda iz vsega srca svojega, na umnost svojo pa se ne zanašaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 6, 'Na vseh potih svojih ga spoznavaj, in on ravne naredi steze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 7, 'Ne štej sam sebe za modrega; boj se Gospoda in ogiblji se hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 8, 'To bode zdravilo životu tvojemu in krepilo tvojim kostem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 9, 'Časti Gospoda z blagom svojim in s prvinami vseh pridelkov svojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 10, 'tako se bodo polnile z obilostjo žitnice tvoje, in mošt poteče zvrhoma iz kadi tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 11, 'Karanja Gospodovega, sin moj, ne zametaj in strahovanje njegovo naj ti ne preseda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 12, 'zakaj kogar Gospod ljubi, tega strahuje, in to kakor oče sina, katerega ima rad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 13, 'Blagor človeku, ki doseza modrost, in človeku, ki napreduje v umnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 14, 'Boljša je namreč nje pridobitev od pridobljenega srebra in dobiček pri njej dražji od zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 15, 'Dražja je od biserov, in vse, kar te veseli, se ne more enačiti ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 16, 'Dni dolgost je v desnici njeni, v levici njeni bogastvo in čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 17, 'Pota njena so miline pota in vse steze njene mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 18, 'Drevo življenja imajo, ki se nje poprimejo, in srečen je, kdor se je drži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 19, 'Gospod je z modrostjo ustanovil zemljo, nebesa je postavil z umnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 20, 'Po znanju njegovem so se razklala brezna in oblaki kapljajo roso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 21, 'Sin moj, naj ti to ne izgine izpred oči: hrani zdravo pamet in premišljenost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 22, 'in bodeta življenje duši tvoji in lepotina grlu tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 23, 'Tedaj boš stopal brez skrbi po poti svoji in noga tvoja se ne zadene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 24, 'Ko ležeš, ne bo te strah, ležal boš in sladko spal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 25, 'Ne boj se naglega strahú, ne pustošenja brezbožnih, ko prihaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 26, 'Zakaj Gospod bode upanje tvoje in ohrani nogo tvojo, da se ne ujame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 27, 'Ne odtezaj dobrotnosti njim, katerim je je treba, ko jo more storiti roka tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 28, 'Ne reci bližnjemu svojemu: „Pojdi, in zopet pridi, in jutri ti dam,“ko imaš to pri sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 29, 'Ne snuj zlega zoper bližnjega svojega, ko stanuje brez skrbi s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 30, 'Ne prepiraj se z nobenim človekom brez sile, ako ti ni hudega storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 31, 'Ne zavidaj nobenemu silovitniku in ne izvoli nobenih potov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 32, 'Kajti gnusoba je Gospodu izprijenec, pri poštenih pa je skrivnost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 33, 'Prokletstvo Gospodovo je na brezbožnega hiši, pravičnih bivališče pa blagoslavlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 34, 'Res, zasmehovalce on zasmehuje, krotkim pa daje milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 3, 35, 'Modri podedujejo slavo, neumneže pa razglasi sramota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 1, 'Poslušajte, sinovi pouk očetov in pazite, da spoznate razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 2, 'Kajti dobro izročilo vam dajem, nauka mojega ne zapuščajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 3, 'Tudi jaz sem bil sin pri očetu svojem, nežen in edinec v varstvu matere svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 4, 'In on me je učil in mi rekal: Ohrani naj besede moje srce tvoje; izpoljnjuj zapovedi moje in žívi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 5, 'Pridóbi modrost, pridóbi razumnost, ne zabi je in ne kreni od govorov mojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 6, 'Ne zapusti je, in ohranila te bo, ljubi jo, in stražila te bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 7, 'Začetek modrosti je: Pridóbi modrost! in za ves svoj imetek pridobi si razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 8, 'Povzdiguj jo, in povišala te bo, v čast te spravi, ko jo bodeš objemal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 9, 'Na glavo ti dene krasen venec, krono slave ti podari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 10, 'Čuj, sin moj, in sprejmi besede moje; tako si ti pomnožijo življenja leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 11, 'Modrosti pot te učim, vodim te po stezah poštenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 12, 'Ko boš hodil, nič ne bo oviralo stopinje tvoje, in če potečeš, se ne spotakneš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 13, 'Oprimi se pouka, ne pusti ga, hrani ga, ker je življenje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 14, 'Ne stopi na stezo brezbožnih in po poti hudobnih ne hodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 15, 'Ogni se je, ne prehajaj čeznjo, kreni od nje in idi mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 16, 'Zakaj ne spe, če niso storili hudega, in spanje jim mine, če niso koga izpodnesli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 17, 'Kajti kruh brezbožnosti jedo in vino silovitosti pijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 18, 'Toda pravičnikov pot je kakor luč zore, ki sveti bolj in bolj do popolnega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 19, 'Brezbožnih steza je podobna temi: ne vedo, ob kaj se bodo spoteknili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 20, 'Sin moj, na besede moje pazi, h govorom mojim nagni uho svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 21, 'Nikar naj ti ne izginejo izpred oči, hrani jih v globočini srca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 22, 'Kajti življenje so njim, ki jih dosežejo, in zdravje vsemu njih telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 23, 'Bolj nego vse, kar je stražiti, čuvaj srce svoje, kajti v njem so viri življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 24, 'Iznebi se spačenosti ust, in zvitost ustnic spravi daleč od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 25, 'Oči tvoje naj zro naravnost in trepalnice tvoje naj gledajo ravno predse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 26, 'Izmeri stezo noge svoje in stanovitna naj bodo vsa pota tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 4, 27, 'Ne kreni na desno ali na levo, odvrni nogo svojo od hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 1, 'Sin moj, na modrost mojo pazi, proti umnosti moji nagni uho svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 2, 'da obdržiš premišljenost in ustne tvoje ohranijo spoznanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 3, 'Zakaj med cede ustne tujke in glajša od olja so usta njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 4, 'Ali njen konec je grenek kakor pelin, oster kakor dvorezen meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 5, 'Noge njene gredo v smrt, v kraj mrtvih držé stopinje njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 6, 'Še mar ji ni, da bi krenila na pot življenja; po krivih stezah hodi, a ne ve tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 7, 'Sedaj torej, sinovi, poslušajte me in ne odstopajte od besed mojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 8, 'Daleč od nje hodi svojo pot in ne bližaj se durim hiše njene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 9, 'da ne bi dal drugim dike svoje in let svojih grozovitniku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 10, 'da ne bi se sitili tujci s premoženjem tvojim in trudi tvoji ostali v hiši inostranca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 11, 'In ne bi zdihoval ob koncu svojem, ko se ti posuši meso in telo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 12, 'in govoril: „Kako sem sovražil pouk in svarjenje je zametalo srce moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 13, 'Poslušal nisem glasú učiteljev svojih, ne ušesa svojega nagibal k njim, ki so me učili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 14, 'Skoraj da nisem obtičal v vsej nesreči sredi zbora in občine!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 15, 'Pij vodo iz lastnega vodnjaka in kar ti priteka iz tvojega studenca!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 16, 'Ali naj se ven razlivajo viri tvoji, po ulicah tvoji potoki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 17, 'Imej jih sam zase, a ne za tujce s seboj vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 18, 'Blagoslovljen bodi vrelec tvoj in veseli se žene mladosti svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 19, 'košute predrage, gazele drežestne –! prsi njene naj te mamijo vsak čas, vedno hodi zamaknjen v njeno ljubezen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 20, 'Ker zakaj bi taval, sin moj, s tujko in bi objemal prsi tuje ženske?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 21, 'Kajti pred očmi Gospodovimi so pota vsakega in on meri vse steze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 22, 'Brezbožnika ujamejo krivice njegove in vrvi greha njegovega ga bodo držale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 5, 23, 'Umre, ker mu nedostaje pouka, in v obilosti nespameti svoje bo blodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 1, 'Sin moj, če si postal porok bližnjemu svojemu, če si s podano roko obljubil za tujca:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 2, 'zadrgnil si se z besedami svojih ust, ujet si z besedami svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 3, 'Stóri tisto skoraj, sin moj, in reši se, ker si prišel bližnjemu svojemu v roko; pojdi, spusti se na kolena in s prošnjami nadleguj bližnjega svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 4, 'Ne dovoli spanja svojim očem, ne dremanja trepalnicam svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 5, 'reši se kakor gazela iz roke lovčeve in kakor ptica iz ptičarjeve pesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 6, 'Pojdi k mravlji, o lenuh, oglej si pota njena in uči se modrosti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 7, 'nima vodnika, nadzornika ali zapovednika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 8, 'vendar pripravlja poleti hrano svojo, ob žetvi znaša, kar bo uživala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 9, 'Doklej boš polegal, lenuh? kdaj vstaneš iz spanja svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 10, 'Malo boš pospančkal, malo podremal, malo sklenil roke in poležal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 11, 'v tem ti pride uboštvo kakor uren popotnik in nuja nadte kakor oboroženec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 12, 'Belijalov človek, krivičen mož je, kdor hodi s spačenimi usti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 13, 'mežika z očmi, beseduje z nogami, pomiguje s prsti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 14, 'Vsakršna spačenost tiči v srcu njegovem, zlo snuje sleherni čas, prepire napravlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 15, 'Zatorej pride nagloma nesreča njegova, v hipu se razbije in ne bo ozdravljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 16, 'Šestero je reči, ki jih sovraži Gospod, in sedmero se jih studi duši njegovi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 17, 'oči visoke, jezik lažnjiv in roke, prelivajoče nedolžno kri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 18, 'srce, ki snuje hudobne naklepe, noge, urno tekoče v hudo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 19, 'kriva priča, ki raznaša laži, in kdor prepire seje med brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 20, 'Hrani, sin moj, zapoved očeta svojega in ne zametuj nauka matere svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 21, 'privezuj ju na srce svoje vedno, pripenjaj ju na grlo svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 22, 'Kamor koli pojdeš, te bosta spremljala, ko boš ležal, bosta pazila nate, in ko se zbudiš, se pogovarjala s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 23, 'Kajti zapoved je svetilnica in nauk je luč; in poučna svarila so pot življenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 24, 'da te obvarujejo ženske hudobne, prilizovanja jezika tujke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 25, 'Ne poželi si lepote njene v srcu in s trepalnicami svojimi naj te ne ujame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 26, 'Kajti zaradi nečiste ženske se izgubi kruhek in prešeštnica lovi dušo dragoceno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 27, 'Ali vzame kdo ogenj v nedrje svoje, in oblačila se mu ne osmode?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 28, 'Ali pa more kdo hoditi po žerjavici, da bi se mu noge ne obžgale?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 29, 'Tako, kdor se shaja z bližnjega svojega ženo, kdorkoli se je dotakne, ne ostane brez kazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 30, 'Ne zadene zaničevanje tatu, ako ukrade, da uteši poželenje svoje, ko je gladen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 31, 'vendar zasačen mora povrniti sedemkrat, dati mora vse blago hiše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 32, 'A kdor prešeštvuje z ženo, norí; kdor se hoče pogubiti, naj to stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 33, 'Šiba in nečast ga zadeneta, in sramota njegova se ne izbriše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 34, 'Ker ljubosumnost razvname srd moža, zato ne prizanese v dan maščevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 6, 35, 'Ne mara nobene odkupnine in ne sprejme, ponujaj še toliko darov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 1, 'Sin moj, pazi na besede moje in zapovedi moje hrani pri sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 2, 'Pazi na zapovedi moje in žívi, pazi na nauk moj kakor na zenico svojih oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 3, 'Priveži si jih na prste, zapiši jih na srca svojega ploščo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 4, 'Reci modrosti: sestra si moja! in razumnost imenuj sorodnico svojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 5, 'da te varuje žene vnanje, tujke, ki se dobrika z gladkimi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 6, 'Kajti skozi okno hiše svoje, preko omrežja svojega gledajoč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 7, 'sem videl med abotnimi, zazrl med sinovi brezumnega mladeniča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 8, 'ki se je po ulicah klatil, blizu njenega vogla, stopal po potu do hiše njene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 9, 'v mraku, na večer dneva, v noči črni in temni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 10, 'In glej, ženska mu pride naproti, v kurbji opravi in odrevenelega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 11, 'Jezična je in trdovratna, v njeni hiši ne bivajo noge njene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 12, 'zdaj se klati po ulicah, zdaj po trgih in pri vsakem voglu zalezuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 13, 'In ga prime ter ga poljubi in s predrznim licem mu reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 14, 'Hvalne daritve sem bila dolžna, danes sem opravila obljube svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 15, 'Zato sem ti prišla naproti, hrepeneč po obličju tvojem, in sem te našla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 16, 'S preprogami sem prestrla posteljo svojo, s pisanimi odejami iz platna egiptovskega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 17, 'pokadila sem ležišče svoje z miro, aloo in cimetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 18, 'Dej, radujva se obilo v ljubezni prav do jutra, oslajujva se z ljubkovanjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 19, 'Kajti moža ni v hiši, odšel je na daljni pot;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 20, 'mošnjo denarja je vzel s seboj, povrne se domov šele ob ščipu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 21, 'Nagnila ga je z mnogim pregovarjanjem svojim, s prilizovanjem ust svojih ga je potegnila:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 22, 'za njo gre takoj, kakor gre vol v klalnico in kakor neumnež v kazen v okovih –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 23, 'dokler mu pšica jeter ne razkolje; kakor ptič hiti v zanko, ne vedoč, da je zoper življenje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 24, 'Zato sedaj, sinovi, poslušajte me in pazite na ust mojih besede!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 25, 'Ne kreni na njena pota srce tvoje, ne zavij na steze njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 26, 'Ker mnogo jih je prebodla in na tla zvrnila, in veliko jih je, katere je vse pomorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 7, 27, 'Hiša njena je pot v kraj mrtvih, gredoča doli v smrtne hrame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 1, 'Ali ne kliče modrost in razumnost ne zaganja svojega glasu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 2, 'Na vrhu višav pri cesti, na razpotjih stoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 3, 'na strani vrat, ob izhodu mesta, pri vhodu v duri vpije, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 4, 'Vas, možje, kličem in glas moj je do sinov človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 5, 'Umejte, o preprosti, previdnost, in neumni, srce vam bodi razumno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 6, 'Čujte, ker vzvišene reči bom govorila, usta svoja odprem, da oznanim, kar je prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 7, 'Kajti resnico govoré usta moja in gnusoba je ustnam mojim krivica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 8, 'Pravične so vse besede mojih ust, nič ni skrivljenega ali spačenega v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 9, 'Jasne so vse razumnemu in ravne njim, ki pridobivajo umnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 10, 'Sprejmite nauk moj in ne srebra in znanje rajši nego izbrano zlato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 11, 'Zakaj boljša je modrost od biserov, in vse, kar si more kdo želeti, se ne more enačiti ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 12, 'Jaz, modrost, prebivam s previdnostjo in imam pri sebi spoznanje dobrih sklepov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 13, 'Strah Gospodov je sovražiti hudo; napuh in prevzetnost in hudobno pot in usta, spačenostim vdana, jaz sovražim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 14, 'Moj je svét in zdrava pamet, jaz sem razumnost, moja je moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 15, 'Po meni kraljujejo kralji in vladarji določajo pravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 16, 'Po meni vladajo knezi in plemenitniki in vsi sodniki zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 17, 'Ljubim tiste, ki mene ljubijo, in kateri me zgodaj iščejo, me najdejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 18, 'Bogastvo in čast sta pri meni, blago stanovitno in pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 19, 'Boljši je sad moj nego zlato, prečisto zlato, in kar donašam, je boljše nego izbrano srebro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 20, 'Po poti pravičnosti hodim, posredi stezá postavnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 21, 'da dam onim, ki me ljubijo, stalno blago v dediščino in napolnim njih zakladnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 22, 'Gospod me je imel v začetku poti svoje, pred vsemi deli svojimi, od nekdaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 23, 'Od vekomaj sem postavljena, od začetka, pred početkom zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 24, 'Ko še ni bilo brezen nobenih, sem bila rojena, ko še ni bilo nobenih studencev, polnih vodá;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 25, 'ko se niso še bile pogreznile gore na zemljo, preden so bili griči, sem bila rojena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 26, 'še ni bil ustvaril zemlje ali polja, ne začetka prahu vesoljne zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 27, 'Ko je pripravljal nebesa, bila sem tam, ko je odmerjal krog na brezna površju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 28, 'ko je zgoraj utrjal nebesni oblok, ko so izbruhnili brezna studenci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 29, 'ko je morju postavljal meje, da vode ne prestopijo njegovega ukaza, ko je stavil zemlji podlago:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 30, 'tedaj sem bila pri njem kot delovodja in veselje njegovo vsak dan, igrala sem pred njim vsak čas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 31, 'igrala sem si na naseljeni zemlji njegovi, in veselje mi je bilo bivati pri otrocih človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 32, 'Zdaj torej, sinovi, poslušajte me; ker blagor njim, ki se držé potov mojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 33, 'Čujte pouk in bodite modri, in ne odklanjajte ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 34, 'Blagor človeku, ki me posluša, ki čuje pri vratih mojih vsak dan, ki pazi na podboje duri mojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 35, 'Kajti kdor zadobi mene, zadobi življenje in prejme milost od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 8, 36, 'Kdor pa greši zoper mene, dela silo duši svoji; vsi, ki me sovražijo, ljubijo smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 1, 'Modrost je sezidala hišo svojo, izsekala je sedem stebrov svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 2, 'zaklala je živali svoje, zmešala vino svoje, tudi mizo svojo je pripravila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 3, 'poslala je dekle svoje vabit po najvišjih krajih v mestu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 4, '„Kdorkoli je preprost, naj se obrne sem!“In kdor je brezumen, njemu reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 5, '„Pridite, jejte kruh moj in pijte vino, ki sem ga zmešala!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 6, 'Zapustite abotnost in živíte in ravno stopajte po poti razumnosti!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 7, 'Kdor poučuje zasmehovalca, nakopava si sramoto; in kdor kara brezbožnika, pridobi si madež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 8, 'Ne karaj zasmehovalca, da te ne sovraži; karaj modrega, in ljubil te bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 9, 'Nakloni pouk modremu, in bode še bolj moder, pouči pravičnega, in napredoval bo v znanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 10, 'Strah Gospodov je začetek modrosti, in spoznanje Najsvetejšega je razumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 11, 'Kajti po meni se bodo pomnožili dnevi tvoji in pridejala se ti bodo življenja leta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 12, 'Ako si moder, sebi si moder, ako pa si zasmehovalec, sam boš trpel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 13, 'Gospa neumščina veliko ropoče, abotna je in ničesar ne ve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 14, 'In sedeva pri durih hiše svoje, na stolu, na mestnih višinah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 15, 'da kliče mimohodeče, ki ravno stopajo po potih svojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 16, '„Kdorkoli je preprost, naj se obrne sem!“In kdor je brezumen, njemu reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 17, '„Vode ukradene so sladke in kruh, ki se skrivaj jé, prijeten.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 9, 18, 'Ali on ne ve, da so mrtvi tam, v globočinah smrtnega kraja povabljenci njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 1, 'Pregovori Salomonovi. Sin moder razveseljuje očeta, sin bedak pa je žalost materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 2, 'Krivičnosti zakladi nič ne koristijo, a pravičnost rešuje smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 3, 'Gospod ne pusti stradati duše pravičnega, poželenje brezbožnih pa zavrača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 4, 'Kdor dela z leno roko, obuboža, pridnih roka pa bogatí.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 5, 'Kdor po leti znaša, je sin previden; kdor pa trdno spava ob žetvi, je sin, ki pripravlja sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 6, 'Blagoslovi bivajo na glavi pravičnika, usta brezbožnih pa skrivajo silovitost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 7, 'Spomin na pravičnega ostane blagoslovljen, ime brezbožnih pa strohni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 8, 'Kdor je modrega srca, sprejema zapovedi, neumen blebetač pa pade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 9, 'Kdor hodi brezmadežno, hodi varno; kdor pa pači pota svoja, bode v svarilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 10, 'kdor mežika z očesom, napravlja žalitev, in neumen blebetač pade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 11, 'Vrelec življenja so pravičnega usta, usta brezbožnih pa skrivajo silovitost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 12, 'Sovraštvo zbuja prepire, a ljubezen prikriva vse pregreške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 13, 'Na ustnah razumnega je modrost, za hrbet brezumnega pa raste palica!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 14, 'Modri hranijo znanje, neumneža ustom pa je blizu nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 15, 'Blago bogatinovo je trden grad njegov; v nesrečo je siromakom njih uboštvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 16, 'Kar z delom svojim spravi pravični, spravi za življenje, pridelek krivičnega pa je za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 17, 'Na potu do življenja je, kdor pazi na pouk, kdor pa zapušča svarjenje, zabrede v zmoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 18, 'Kdor skriva sovraštvo, ima ustne lažnive, in kdor raznaša obrekovanje, je bedak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 19, 'Kjer je veliko besed, ni brez greha, kdor pa brzda ustne svoje, je razumen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 20, 'Pravičnega jezik je kakor srebro izbrano, srce brezbožnih pa je malo prida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 21, 'Ustnice pravičnega sitijo mnoge, neumni pa mrjo, ker jim nedostaje uma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 22, 'Blagoslov Gospodov bogatí, trud pa ničesar ne pridene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 23, 'Igrača bedaku je storiti sramotnost, razumnemu možu pa kaj pametnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 24, 'Česar se boji brezbožnik, se mu zgodi, česar pa želé pravični, dá jim Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 25, 'Kadar pridere nevihta, ne obstane brezbožnik, pravičnik pa ima podstavo večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 26, 'Kakor ocet zobém in kakor dim očém, tako je lenuh njim, ki ga pošiljajo na delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 27, 'Strah Gospodov pridaje dni, brezbožnih leta pa se krajšajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 28, 'Čakanje pravičnih bode veselje, krivičnih pričakovanje pa izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 29, 'Trdnjava popolnemu je pot Gospodov, poguba pa njim, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 30, 'Pravični nikdar ne omahne, krivičniki pa ne bodo prebivali v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 31, 'Usta pravičnega dajo obilo modrosti iz sebe, jezik spačenosti pa bo iztrebljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 10, 32, 'Ustne pravičnega poznajo, kaj je prijetno, a usta brezbožnikov polna so spačenosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 1, 'Tehtnica lažniva je gnusoba Gospodu, polna teža pa mu je po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 2, 'Ko pride napuh, pride tudi sramota; pri skromnih pa je modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 3, 'Poštene spremlja njih nedolžnost, nezvestnike pa pokonča njih spačenost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 4, 'Ne pomaga blago ob dnevi srda, pravičnost pa reši smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 5, 'Pravičnost popolnega uravnava pot njegov, brezbožni pa pade po krivici svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 6, 'Poštene rešuje njih pravičnost, nezvestniki pa se ujemo v svoji hudobiji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 7, 'Ko umre brezbožen človek, mu pogine upanje in pričakovanje krivičnikov se izniči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 8, 'Pravičnik bo rešen iz stiske, in brezbožnik pride na mesto njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 9, 'Z usti uničuje bogapozabnik bližnjega svojega, a pravične otme njih spoznanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 10, 'O pravičnih sreči se raduje mesto, in ko ginejo brezbožni, spev se glasi v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 11, 'Blagoslov poštenih povzdiguje mesto, usta brezbožnih pa ga podirajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 12, 'Brez uma je, kdor zaničuje bližnjega svojega, a mož pameten molči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 13, 'Kdor hodi z opravljanjem, razodeva skrivnost, zvestega srca človek pa skriva reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 14, 'Kjer ni razumnega vodstva, propada ljudstvo, blaginjo pa pospešuje množica svetovalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 15, 'Hudo bo njemu, kdor je porok za tujca, kdor pa mrzi poroštvo, je brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 16, 'Žena ljubezniva zadobi čast, in silovitniki zadobe bogastvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 17, 'Usmiljen človek sebi dobro pripravlja, neusmiljenec pa lastnemu telesu bolečine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 18, 'Brezbožnik si pridobi prevarljiv dobiček, kdor pa seje pravičnost, resnično plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 19, 'Kdor se drži pravičnosti, seje za življenje, kdor se pa žene za hudim, za svojo smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 20, 'Gnusoba so Gospodu spačeni v srcu, a po volji mu so, kateri so popolni na svojem potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 21, 'Roko dam na to! hudobnež ne ostane brez kazni, pravičnih seme pa se reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 22, 'Zlat obroček svinji na rilcu je žena lepa, ki pamet zameta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 23, 'Pravičnih želja je samo dobro, brezbožni pa dočakajo le srd.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 24, 'Nekateri razdaja obilo in bogatí še bolj; drugi zadržuje celó, kar se spodobi, pa gre v siromaštvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 25, 'Duša radodarna se obilo nasiti, in kdor napaja, tudi sam bo napojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 26, 'Kdor zadržuje žito, ga bodo preklinjali, blagoslov pa bo na glavi njemu, ki ga prodaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 27, 'Kdor si prizadeva za dobro, išče blagougodja Božjega; kdor pa išče hudega, njega bo zadelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 28, 'Kdor upa v bogastvo svoje, propade, kakor veja pa se razcvetó pravični.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 29, 'Kdor dela zmešnjavo v hiši svoji, podeduje veter; in neumnež bo hlapčeval njemu, ki je modrega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 30, 'Pravičnega sad je drevo življenja, in modri pridobiva duše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 11, 31, 'Glej, pravičnemu na tej zemlji se povrača, kolikanj bolj brezbožniku in grešniku!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 1, 'Kdor ljubi pouk, ljubi znanje, kdor pa sovraži svarjenje, je kakor živina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 2, 'Dobrega obsuje z blagovoljnostjo Gospod, njega pa, ki kuje zvijače, obsodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 3, 'Ne ustanoviti se človek z brezbožnostjo, korenina pravičnih pa se nikdar ne gane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 4, 'Vrla žena je možu svojemu venec, ali kakor gniloba v kosteh njegovih ona, ki dela sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 5, 'Pravičnih misli so pravične, sveti brezbožnih pa zvijačni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 6, 'Brezbožnih besede zalezujejo kri, poštene pa otimljejo njih usta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 7, 'Zvrnejo se brezbožni, da jih ne bode, pravičnih hiša, pa bo stala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 8, 'Po meri razuma njegovega bodo hvalili moža, kdor pa je spačenega srca, bo zaničevan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 9, 'Boljši je ki ga nizko cenijo, pa si sam streže, nego kdor sebe veliča in kruha strada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 10, 'Pravični skrbi za življenje živine svoje, srce brezbožnih pa je neusmiljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 11, 'Kdor obdeluje zemljo svojo, se bo sitil s kruhom, kdor pa pohaja za praznimi rečmi, je brezumen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 12, 'Brezbožnik želi lova hudobnih, pravičnih korenina pa daje sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 13, 'V nezvestobi usten tiči huda zadrga, pravični pa izide iz stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 14, 'Od sadú svojih ust se nasiti mož dobrega in del svojih povračilo prejme človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 15, 'Neumneža pot je raven v očeh njegovih, kdor pa je moder, si dá svetovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 16, 'Neumnega nevolja se spozna takoj, kdor pa prikriva sramoto, je razumen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 17, 'Kdor govori resnico, naznanja, kar je pravično, priča lažniva pa zvijačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 18, 'Nekateri blebeta kakor meč, ki prebada, modrih jezik pa je kakor zdravilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 19, 'Ustne resnične se utrdijo na večno, jezik lažnivi pa le za trenutek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 20, 'Zvijača biva v srcu njih, ki snujejo hudo, kateri pa svetujejo mir, imajo veselje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 21, 'Pravičnemu se ne prigodi nesreča nobena, brezbožnim pa bode obilo nezgod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 22, 'Gnusoba so Gospodu lažnive ustne, kateri pa ravnajo zvesto, so mu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 23, 'Človek umen skriva znanje, srce bedakov pa oklicuje nespamet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 24, 'Roka pridnih bo gospodovala, lenoba pa davek plačevala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 25, 'Skrb v srcu tare moža, a dobra beseda ga razveseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 26, 'Pravični je vodnik bližnjemu svojemu, pot brezbožnih pa jih zapeljuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 27, 'Zanikarnež ne bo pekel svoje divjačine, a blago velike cene je človeku marljivost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 12, 28, 'Na stezi pravičnosti je življenje, in kdor stopa po njej, ne pride v smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 1, 'Sin moder posluša pouk očetov, a zasmehovalec ne posluša nobenega svarjenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 2, 'Od sadú ust svojih uživa človek dobro, duša nezvestnikov pa krivičnosti sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 3, 'Kdor straži usta svoja, obvaruje dušo svojo, kdor pa odpira ustne nepremišljeno, pride mu poguba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 4, 'Želi, a ničesar ne doseže duša lenuhova, pridnih pa duša se bo redila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 5, 'Pravičnik sovraži lažnivost, brezbožnik pa dela smrad in sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 6, 'Pravičnost straži nedolžnega na potu, krivica pa grešnika izpodnaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 7, 'Nekateri se kaže bogatega, pa vsega pogreša, nekateri se dela ubožnega, a ima obilo blaga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 8, 'Odkupnina življenja je možu bogastvo njegovo, ali siromak ne čuje pretenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 9, 'Luč pravičnih daje vesele žarke, brezbožnih svetilnica pa ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 10, 'Prevzetnost napravlja samo prepire, pri njih pa, ki sprejemajo svet, je modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 11, 'Blago, ki se je dobilo s sleparijo, se zmanjša, kdor pa s pošteno roko zbira, ga pomnoži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 12, 'Predolgo upanje dela srce bolno, življenja drevo pa je želja, ki se izpolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 13, 'Kdor zaničuje besedo Božjo, sebi škoduje; kdor pa se boji zapovedi, njemu se poplača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 14, 'Nauk modrega je vrelec življenja, da se ogne smrtnih zadrg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 15, 'Razbornost pridobiva milost, pot nezvestnikov pa je hrapav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 16, 'Razumni dela vse premišljeno, bedak pa razseva neumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 17, 'Brezbožen glasnik zaide v nesrečo, a zvest poslanec je kakor zdravilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 18, 'Uboštvo in sramota bode njemu, ki se odteguje pouku, kdor pa se pokori svarjenju, pride v čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 19, 'Želja izpolnjena je sladka duši, bedakom pa je gnusno umikati se zlemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 20, 'Kdor hodi z modrimi, postane modrejši; kdor pa se druži z bedaki, se pohujša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 21, 'Grešnike preganja nesreča, pravičnim pa Bog povrača dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 22, 'Dobri zapušča dediščino sinov sinovom, grešnikovo premoženje pa je shranjeno za pravičnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 23, 'Mnogo kruha imajo ubogi, ki orjejo ledino, mnogi pa pride na nič, ker mu ni pravice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 24, 'Komur je žal šibe, sovraži sina svojega, kdor ga pa ljubi, kaznuje ga zgodaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 13, 25, 'Pravični jé do sitosti duše svoje, trebuh brezbožnih pa strada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 1, 'Modra žena zida hišo svojo, neumna pa jo z rokami svojimi podira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 2, 'Kdor hodi v poštenosti svoji, se boji Gospoda, a kdor je trdovraten na potih svojih, ga zaničuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 3, 'V neumnega ustih je šiba za prevzetnost, modre pa ohranijo njih ustne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 4, 'Kjer ni volov, so prazne jasli, obilost pridelkov pa je po volovi moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 5, 'Priča zvesta ne laže, kriva priča pa govori laži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 6, 'Ko zasmehovalec išče modrosti, ni je, razumnemu pa je znanje lahko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 7, 'Umakni se izpred oči bedaku, ker ne začuješ pri njem pametne besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 8, 'Modrost razumnega je paziti na svojo pot, bedakov neumnost pa je prevara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 9, 'Neumni se smejejo krivdi, odkritosrčni pa so si dobrohotni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 10, 'Srce pozna lastno bridkost svojo, in v veselje njegovo se ne mešaj drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 11, 'Brezbožnih hiša se pokonča, šator poštenih pa bode cvel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 12, 'Nekatera pot se zdi prava človeku, toda njen konec je pot v smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 13, 'Tudi v smehu žaluje srce in konec veselja je žalost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 14, 'Potov svojih se nasiti, čigar srce se odvrača od Boga, mož dobri pa tistega, kar je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 15, 'Abotni vsemu verjame, prebrisani pa pazi na stopinje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 16, 'Modri se boji in se ogiblje hudega, bedak pa se lahko raztogoti in je predrzen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 17, 'Mož nagle jeze napravlja neumnost; in kdor dela spletke, njega sovražijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 18, 'Tepci podedujejo neumnost, razumni pa si pleto venec znanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 19, 'Hudobni se klanjajo pred dobrimi in brezbožni pri pravičnika vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 20, 'Ubogega sovraži tudi bližnjik njegov, bogatina prijateljev pa je mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 21, 'Kdor zaničuje bližnjega svojega, greši, kdor pa milost deli ubogim, o blagor mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 22, 'Ali se ne motijo, kateri snujejo hudo? Milost pa in resnica pride njim, ki snujejo dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 23, 'V vsakem trudu je dobiček, klepetanje pa donaša le uboštvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 24, 'Venec modrih je njih bogastvo; neumnost bedakov ostane neumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 25, 'Priča resnična otimlje duše, kdor pa govori laž, jih le slepi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 26, 'Kdor se boji Gospoda, trdno upa v Njega; in On bode pribežališče otrokom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 27, 'Strah Gospodov je vrelec življenja, da se ognemo smrtnih zadrg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 28, 'V množici ljudstva je dika kraljeva; kjer se pa narod zmanjšuje, preti vladarju poguba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 29, 'Počasni za jezo je poln razuma, nagli pa pospešuje neumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 30, 'Srce mirno je življenje vsemu telesu, nevoščljivost pa je gniloba v kosteh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 31, 'Kdor zatira siromaka, sramotí Stvarnika njegovega, njega pa časti, kdor se usmili potrebnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 32, 'V nesreči svoji vzame konec brezbožnik, a nado ima tudi v smrti pravičnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 33, 'V razumnega srcu tiho počiva modrost, ali kar je v bedakih, glasno se kaže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 34, 'Pravičnost povišuje narod, greh pa je ljudstvu v nečast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 14, 35, 'Blagovoljnost kraljeva je gotova umnemu hlapcu, srd njegov pa zadene njega, ki ravna sramotno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 1, 'Rahel odgovor odvrača togoto, zbadljiva beseda pa zbuja jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 2, 'Modrih jezik oznanja dobro znanje, usta bedakov pa bruhajo neumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 3, 'Na vsakem kraju so oči Gospodove, gledajoč dobre in hudobne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 4, 'Krotkost jezika je drevo življenja, prešernost njegova pa rani duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 5, 'Neumnež zaničuje pouk očeta svojega, kdor pa pazi na svarjenje, zmodri jako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 6, 'Hiša pravičnega je velika zakladnica v pridelku brezbožnika pa tiči nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 7, 'Ustne modrih trosijo znanje, srce bedakov pa nikakor ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 8, 'Daritev brezbožnih je gnusoba Gospodu, molitev poštenih pa mu je po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 9, 'Gnusoba je Gospodu brezbožnikova pot, njega pa, ki hodi za pravičnostjo, ljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 10, 'Huda kazen zadene njega, ki zapušča pravi pot, in kdor sovraži svarjenje, umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 11, 'Pekel in poguba sta pred Gospodom, kolikanj bolj srca otrok človeških!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 12, 'Zasmehovalec ne ljubi njega, ki ga svari, zato ne hodi k modrim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 13, 'Veselo srce razvedruje obličje, bolečina srca pa tare duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 14, 'Srce razumnega išče znanje, usta bedakov pa se pasejo z neumnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 15, 'Vsi dnevi trpina so slabi, a če je srce veselo, ima pojedino vedno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 16, 'Boljše je malo s strahom Gospodovim nego obilen zaklad z nemirom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 17, 'Boljša skleda zelja, kjer je ljubezen, nego pitan vol, kjer je sovraštvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 18, 'Mož togoten dela zdražbo, potrpežljiv pa potolaži prepir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 19, 'Lenuha pot je kakor trnjev plot, poštenih steza pa je uglajena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 20, 'Moder sin razveseljuje očeta, človek bedak pa zaničuje mater svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 21, 'Neumnost je brezumnemu v veselje, mož razumni pa stopa naravnost naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 22, 'Skazé se načrti, kjer ni sveta, izvršé se pa, če je obilo svetovalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 23, 'Veselje napravi možu odgovor ust njegovih; kajti beseda o pravem času, o kako dobra!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 24, 'Pot življenja gre umnemu navzgor, da se ogne pekla navzdol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 25, 'Prevzetnih hišo podira Gospod, vdovi pa utrjuje meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 26, 'Gnusoba so Gospodu zlobni naklepi, a čistih besede so mile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 27, 'Nesrečno dela hišo svojo, kdor se žene za dobičkom, kdor pa sovraži darila, bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 28, 'Pravičnega srce premišlja, kaj naj govori, brezbožnih usta pa kar bruhajo hudobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 29, 'Daleč je Gospod od brezbožnih, pravičnih molitev pa sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 30, 'Svetlost oči razveseljuje srce in dobro poročilo krepča kosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 31, 'Uho, ki posluša svarjenje življenja, bo bivalo med modrimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 32, 'Kdor se odteza pouku, zaničuje dušo svojo, kdor pa posluša svarjenje, pridobiva srce modro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 15, 33, 'Strah Gospodov je šola modrosti, in pred častjo gre ponižnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 1, 'Načrti srca so človekovi, od Gospoda pa je govor jezikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 2, 'Človeku se zde vse poti njegove čiste, Gospod pa je, ki tehta duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 3, 'Na Gospoda zváli dela svoja, in izpolnile se bodo namere tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 4, 'Vse je Gospod naredil v svoj namen in tudi brezbožnega za hudi dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 5, 'Gnusoba je Gospodu vsak prevzetni v srcu; roko dam na to, da ne ostane brez kazni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 6, 'Milost in resnica prikrivata krivico, in po strahu Gospodovem se ogneš hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 7, 'Ko so koga pota Gospodu po volji, pomiri mu tudi sovražnike njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 8, 'Bolje, da imaš malo s pravičnostjo nego veliko dohodkov s krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 9, 'Srce človekovo izmišlja pot svojo, ali Gospod vodi korake njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 10, 'Božji izrek je na ustnah kraljevih, v sodbi se ne smejo motiti usta njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 11, 'Prava mera in tehtnica sta od Gospoda; kakor jih je naredil, take naj bodo vse uteži v mošnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 12, 'Gnusoba je kraljem storiti krivico, ker s pravičnostjo se utrjuje prestol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 13, 'Drage so kraljem pravične ustne in njega, ki odkritosrčno govori, ljubijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 14, 'Kraljev srd je glasnik smrti, ali moder mož ga potolaži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 15, 'V svetlosti obličja kraljevega je življenje in blagovoljnost njegova je kakor oblak poznega dežja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 16, 'Koliko bolje je, pridobiti si modrost nego zlato! in pridobiti si razumnost rajši izvóli nego srebro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 17, 'Poštenih cesta je: ogibati se hudega; dušo svojo ohrani, kdor pazi na pot svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 18, 'Pred pogubo prevzetnost in pred padcem napuh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 19, 'Bolje pohleven biti v duhu s krotkimi nego plen deliti s prevzetnimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 20, 'Kdor pazi na besedo, doseže dobro, in kdor upa v Gospoda, blagor mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 21, 'Kdor je modrega srca, ga bodo imenovali razumnega, in sladkost ustnic pospešuje nauk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 22, 'Studenec življenja je pamet njemu, kdor jo ima, neumne pa kara njih neumnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 23, 'Kdor je modrega srca, govori pametno in nikdar mu ne zmanjka nauka na ustnah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 24, 'Dobrohotne besede so kakor satovje medú, sladkost duši in zdravilo kostem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 25, 'Je pot, ki se zdi ravna človeku, njen konec pa je pot v smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 26, 'Glad delavca dela za njega, ker usta njegova ga izpodbadajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 27, 'Mož malopridni koplje zlo in na ustnah mu je paleč ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 28, 'Mož, spačenosti vdan, dela zdražbo in podpihovalec loči zaupne prijatelje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 29, 'Silovitnik izvablja bližnjega svojega, da ga vodi po poti, ki ni dobra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 30, 'Kdor zatiska oči svoje, da izmišlja reči spačene, kdor nalašč tišči ustne svoje, izvršuje hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 31, 'Prelep venec je siva glava, ki se nahaja na potu pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 32, 'Boljši je potrpežljivi od močnega, in kdor gospoduje svojemu srcu, od onega, ki mesto pribori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 16, 33, 'V naročje se vrže kocka, od Gospoda pa je vsa razsodba njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 1, 'Boljši je grižljaj suhega kruha s pokojem nego hiša, polna zaklanih živali, s prepirom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 2, 'Umen hlapec bo gospodoval sinu, ki dela sramoto, in delil dediščino med brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 3, 'Topilnica je za srebro in peč za zlato, srce pa izkuša Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 4, 'Hudobnež pazi na hudobna usta in lažnik rad posluša poguben jezik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 5, 'Kdor zasmehuje ubožca, sramoti Stvarnika njegovega; kdor se veseli nesreče, ne ostane brez kazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 6, 'Starčkom venec so otrok otroci in ponos sinom njih očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 7, 'Nespodobi se neumnežu govor izvrsten, še manj pa plemenitniku govor lažniv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 8, 'Darilo je kakor drag kamen v očeh njega, ki ga prejme: kamor koli se obrne, uspeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 9, 'Kdor greh zakriva, išče ljubezni, kdor pa stvar ponavlja, loči dobre prijatelje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 10, 'Razumnega se prime eno posvarilo bolj, nego ko bi stokrat udaril bedaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 11, 'Samo upora išče človek hudoben, zato bo poslan grozoviten poročnik zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 12, 'Medvedka, ki so ji mladiče vzeli, naj sreča moža, a ne bedak v neumnosti svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 13, 'Kdor vrača hudo za dobro, od njegove hiše se ne gane nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 14, 'Začetek prepira je, kakor če kdo vodo pušča iz jeza, zato preden izbruhne, zapústi spor!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 15, 'Kdor opravičuje krivičnega in kdor obsoja pravičnega, gnusoba sta Gospodu oba enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 16, 'Čemu kupnina v roki bedaka? da si kupi modrost? Saj za to nima razuma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 17, 'Vsak čas ljubi, kdor je prijatelj, in brat se izkaže v stiski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 18, 'Brezumen človek je, ki udari v roko in se stavi za poroka bližnjemu svojemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 19, 'Greh ljubi, kdor ljubi prepir, in kdor visoko zida vrata svoja, si pripravlja podrtje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 20, 'Kdor je spačenega srca, ne doseže dobrega, in kdor je prekanjenega jezika, zaide v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 21, 'Kdor rodi bedaka, rodi sebi v žalost, in neumnega oče se ne bo veselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 22, 'Srce veselo daje dobro zdravilo, duh potrt pa kosti suši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 23, 'Dar izza nedrij skrivaj prejme brezbožnik, da preobrne pota pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 24, 'Pred očmi razumnemu je modrost, bedakove oči pa tekajo do krajev zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 25, 'V žalost je očetu svojemu sin bedak in v bridkost porodnici svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 26, 'Pokoriti tudi pravičnega ni dobro ali tepsti plemenite zaradi poštenosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 27, 'Govore svoje brzda, kdor je napredoval v spoznanju, in kdor je hladnega duha, je mož pameten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 17, 28, 'Tudi neumneža, ko molči, imajo za modrega, in kdor stiska ustne svoje, velja za razumnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 1, 'Kdor se razdružuje, svojega išče poželenja in protivi se vsemu, kar bi mu bilo v blaginjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 2, 'Ne veseli se bedak umnosti, marveč samo, da se razodeva srce njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 3, 'Ko pride brezbožni, pride tudi zaničevanje, in z nečastjo pride zasramovanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 4, 'Vode globoke so besede iz ust vrlega moža, potok vrvrajoč je modrosti vrelec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 5, 'Ni dobro potegniti se za brezbožnega, da se pravičnemu zvije pravica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 6, 'Govori bedaka napravijo prepir in usta njegova prikličejo tepež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 7, 'Usta bedakova so mu v pogubo in ustne njegove so zadrge duši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 8, 'Podpihovalčeve besede so kakor slaščice in prodirajo do notranjščine života.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 9, 'Tudi kdor je nemaren v opravilu svojem, je brat zapravljivcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 10, 'Stolp močan je ime Gospodovo: tja priteče pravični in je na varnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 11, 'Bogatega blago je trden grad njegov in kakor zid visok v misli njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 12, 'Preden se stare, vzpne se srce človekovo, in pred častjo gre ponižnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 13, 'Kdor odgovarja, preden je slišal, mu štejejo to za neumnost in sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 14, 'Duh moški prenaša bridkost svojo, če pa je duh potrt, kdo ga povzdigne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 15, 'Srce razumnega pridobiva znanje in modrih uho išče znanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 16, 'Dar človekov mu razširi pot in ga pripelje pred obličje mogočnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 17, 'Pravičen se vidi, kdor je prvi v pravdi svoji, dokler ne pride bližnji njegov ter ga izpraša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 18, 'Prepire konča kocka in razsodi med močnimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 19, 'Brat, z grehom razžaljen, bolj se upira nego trdno mesto, in prepiri so kakor zapah grada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 20, 'Ust svojih sadú se nasiti život vsakega, s pridelkom usten svojih vsak se siti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 21, 'Smrt in življenje sta jeziku v oblasti; in kdor ga rad rabi, bo jedel sad njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 22, 'Kdor je dobil ženo, je dobil kaj dobrega, in prejel je milosti od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 23, 'Ponižno prosi ubožec, bogati pa odgovarja osorno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 18, 24, 'Mož, ki ima mnogo prijateljev, pride na nič; toda je prijatelj, ki je zvestejši od brata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 1, 'Boljši ubožec, ki hodi v nedolžnosti svoji, nego spačeni v ustnah svojih, pa bedak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 2, 'Res ni dobro duši brez spoznanja, in kdor je nagel z nogami, greši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 3, 'Neumnost človekova prevrača pot njegovo in proti Gospodu se srdi srce njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 4, 'Bogastvo daje prijateljev mnogo, od siromaka pa se loči prijatelj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 5, 'Kriva priča ne bode brez kazni, in kdor govori laži, ne bo ubežal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 6, 'Mnogi molijo obličje prvakovo in vsakdo je prijatelj možu radodarnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 7, 'Ubožca sovražijo vsi bratje njegovi; kolikanj bolj se ga ogibljejo prijatelji njegovi! Žene se za besedami, ki nič ne veljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 8, 'Kdor pridobiva razumnost, ljubi dušo svojo, in kdor pazi na umnost, bo dosegel dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 9, 'Kriva priča ne bode brez kazni, in kdor govori laži, bo poginil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 10, 'Bedaku ne pristoji lahko in dobro življenje, mnogo manj hlapcu, da gospoduje knezom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 11, 'Razum zadržuje človeku jezo, in v čast mu je izpregledati pregrešek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 12, 'Kakor rjovenje mladega leva je nevolja kraljeva, a kakor rosa na travo blagovoljnost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 13, 'Preglavice vir je očetu svojemu sin bedak in neprestano kapanje žene prepiri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 14, 'Hiša in blago je dedina po očetih, od Gospoda pa je žena pametna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 15, 'Lenoba potaplja v trdno spanje in nemarna duša bo stradala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 16, 'Kdor drži zapoved, ohrani dušo svojo, kdor pa ne pazi na pota svoja, pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 17, 'Gospodu posoja, kdor milostno deli siromaku, in dobroto njegovo mu bo povrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 18, 'Strahuj sina svojega, dokler je upanje, pa ubiti ga, ti ne hodi na misel!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 19, 'Človek naglojezen ponese svojo kazen; kajti če posežeš vmes, še huje narediš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 20, 'Poslušaj svet in sprejmi pouk, da bodeš moder v prihodnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 21, 'Mnogo je namer v srcu človekovem, a sklep Gospodov sam bo ostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 22, 'Radovoljnost človekova kaže dobrotljivost njegovo, in boljši je ubožec nego lažnivec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 23, 'Strah Gospodov ti je za življenje: v obilosti boš prebival in zlo te ne obišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 24, 'Lenuh pač vtakne roko v skledo, a k ustom je ne mara prinesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 25, 'Če udariš zasmehovalca, preprostega bo izmodrilo, in če posvariš pametnega, napredoval bo v znanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 26, 'Kdor silo dela očetu in mater podi, je sin, ki pripravlja ostudo in sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 27, 'Nehaj, sin moj, poslušati pouk, in zablodiš od besed znanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 28, 'Priča malopridna zasmehuje sodbo, in usta brezbožnih slastno požirajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 19, 29, 'Zasmehovalcem so pripravljene sodbe in udarci hrbtom bedakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 1, 'Vino je zasmehovalec, pijača opojna razgrajalec, in kdorkoli se opoteka po njej, si ne izbistri uma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 2, 'Kakor rjovenje leva je strah kraljev; kdor ga zoper sebe razdraži, greši zoper življenje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 3, 'Na čast je možu odjenjati od prepira, kdorkoli pa je neumen, rad se vanj zaplete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 4, 'Lenuh noče orati zaradi zime, zato bo beračil ob žetvi, a ničesar ne dobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 5, 'Voda globoka je naklep v srcu možá, toda mož razumen mu pride do dna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 6, 'Največ ljudi hvali vsak svojo dobrotljivost, moža pa vseskozi resničnega kdo najde?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 7, 'Neprestano hodi v popolnosti svoji pravični, blagor otrokom njegovim za njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 8, 'Kralj, sedeč na sodnem stolu, razganja z očmi svojimi vse hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 9, 'Kdo bi mogel reči: Očistil sem srce svoje, čist sem svojega greha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 10, 'Dvojne uteži in dvojna mera, oboje je enaka gnusoba Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 11, 'Po dejanjih svojih se dá spoznati tudi deček, je li čisto in je li pošteno delo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 12, 'Uho, ki sliši, in oko, ki vidi, Gospod je oboje enako naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 13, 'Ne ljubi spanja, da ne obubožaš; odpri oči svoje, in nasitiš se kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 14, '„Slabo, slabo je!“pravi, kdor kupuje kaj, ali ko je odšel, se hvali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 15, 'Zlatá je in biserov obilo, ali najdražje orodje so ustne razumne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 16, 'Vzemi obleko njemu, kdor je bil porok za tujca, in za neznane ljudi ga rubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 17, 'Sladek je možu prisleparjeni kruh, ali pozneje dobi polna usta peska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 18, 'Sklepi se utrdé s posvetovanjem, in z razumnim vodstvom se le vojskuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 19, 'Kdor hodi okrog kot obrekovalec, razodeva skrivnost, zato se ne druži ž njim, ki široko odpira usta svoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 20, 'Njemu, ki preklinja očeta svojega ali mater svojo, ugasne svetilnica v črnih teminah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 21, 'Posest, ki se naglo pridobi v začetku, ne bode blagoslovljena ob koncu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 22, 'Ne reci: Povrnil bom hudo! Čakaj Gospoda, in rešil te bo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 23, 'Gnusoba so Gospodu dvojne uteži in prevarljiva tehtnica ni dobra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 24, 'Od Gospoda so stopinje moževe; človek pa kako naj umeje pot svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 25, 'Zadrga je človeku nepremišljeno veleti: Sveti! in po obljubah šele preudarjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 26, 'Brezbožne razmetava kralj moder in pelje čeznje mlatilno kolo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 27, 'Duh v človeku je Gospodova svetilnica, ki preiskuje vso notranjost telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 28, 'Dobrotljivost in zvestoba stražita kralja in z dobrotljivostjo vzdržuje prestol svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 29, 'Dika mladeničem je njih moč in starčkom kras siva glava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 20, 30, 'Modrine od ran so zdravilo za hudo in udarci, ki gredo do živega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 1, 'Kakor potoki vodá je srce kraljevo v roki Gospodovi: kamorkoli hoče, ga nagne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 2, 'Vsakteri pot človeka je raven v očeh njegovih, ali Gospod je, ki tehta srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 3, 'Po pravičnosti in pravici ravnati je ljubše Gospodu nego daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 4, 'Visoke oči in ošabno srce – svetilnica brezbožnih je greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 5, 'Misli marljivega merijo le na korist, vsak naglež pa drevi v pomanjkanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 6, 'Zakladi, nabrani z lažnivim jezikom, so preminljiv hlap, mreža smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 7, 'Silovitost, ki jo delajo brezbožni, nje same razdene, ker se branijo ravnati po pravici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 8, 'Grozno zamotana je pot njega, ki je obremenjen s krivdo, čisti pa dela odkritosrčno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 9, 'Bolje je prebivati v podstrešnem kotu nego z ženo prepirljivo v skupni hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 10, 'Brezbožnega srce želi hudega: bližnji njegov ne najde usmiljenja v očeh njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 11, 'Ko je kaznovan zasmehovalec, spametuje se preprosti, in modri, ko ga poučujejo, sprejema znanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 12, 'Na hišo brezbožnih pazi Pravični in pahne brezbožne v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 13, 'Kdor si maši ušesa pred vpitjem siromaka, bo tudi sam vpil, a nihče ga ne usliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 14, 'Dar na skrivnem odvrača jezo in darilo v nedrju silno togoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 15, 'Veselje je pravičnemu izvrševanje sodbe, a groza njim, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 16, 'Človek, ki zaide od umnosti pota, bo počival v družbi mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 17, 'Stradal bo, kdor ljubi veselje; kdor ljubi vino in olje, ne bode bogat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 18, 'Odkupnina za pravične je brezbožnik, in na mesto poštenih pride izdajalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 19, 'Bolje je prebivati v pusti deželi nego z ženo prepirljivo in togotno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 20, 'Zaklad predrag in mazilo je v modrega prebivališču, človek bedak pa ga pogoltne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 21, 'Kdor teži za pravičnostjo in dobrotljivostjo, doseže življenje, pravičnost in čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 22, 'V mogočnih mesto pride modri in razdene trdnjavo, ki vanjo zaupajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 23, 'Kdor čuva usta svoja in jezik, obvaruje stiske dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 24, 'Prevzetnik, ošabnež – zasmehovalec mu je ime – ravna s predrznim napuhom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 25, 'Lenega ubija želja njegova, ker se roke njegove branijo dela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 26, 'ves dan ga je sama želja; pravičnik pa daje in ne stiska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 27, 'Brezbožnih daritev je gnusoba; kolikanj bolj, ko jo s hudim namenom daruje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 28, 'Krivična priča pogine, mož pa, ki posluša, sme vedno govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 29, 'Brezbožnik kaže predrznost na obličju, poštenjak pa sam uravnava pot svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 30, 'Ni modrosti, ni znanja, ni sveta proti Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 21, 31, 'Konja pripravljajo na dan boja, ali zmaga pride od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 1, 'Boljše je dobro ime od obilega bogastva, boljša od srebra in zlata priljubljenost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 2, 'Bogati in ubogi se srečavajo; Gospod jih je ustvaril vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 3, 'Razumni vidi hudo ter se skrije, abotni pa gredo naprej in morajo trpeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 4, 'Plačilo krotkosti in strahu Gospodovega je bogastvo in čast in življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 5, 'Trnje in zadrge so na potu spačenega; kdor hoče ohraniti dušo svojo, daleč bodi od njih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 6, 'Vzgajaj dečka po lastnosti poti njegove; tudi ko se postara, ne krene od nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 7, 'Bogatin gospoduje ubogim, in kdor jemlje naposodo, je hlapec posojevalcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 8, 'Kdor seje krivico, žel bo nadlogo in šiba togote njegove mine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 9, 'Kdor je blagega očesa, bo blagoslovljen, ker daje od kruha svojega siromaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 10, 'Spodi zasmehovalca, in odide prepir in pravdanja bode konec in sramote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 11, 'Kdor ljubi srca čistost, v čigar ustnah biva miloba, njemu je kralj prijatelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 12, 'Oči Gospodove stražijo znanje, izdajalčeve besede pa podira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 13, 'Lenuh pravi: „Lev je zunaj, sredi trga bi me lahko umoril!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 14, 'Jama globoka so usta ljubovnic; kogar mrzi Gospod, pade vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 15, 'Neumnost je pripeta k dečkovemu srcu, a šiba strahovanja jo odpravi daleč od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 16, 'Kdor tlači siromaka, ga obogati; kdor daje bogatinu, daje le v potrato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 17, 'Nagni uho svoje ter poslušaj modrih besede, in srce svoje obrni k mojemu znanju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 18, 'kajti prijetno bode, če jih ohraniš v srcu svojem; o da bi vse skup se utrdile na ustnah tvojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 19, 'Da bode v Gospoda upanje tvoje, te danes učim, prav tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 20, 'Ali ti nisem pisal izvrstnih reči v svetih in naukih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 21, 'da bi ti naznanil pravilo besed resničnih, da odgovarjaš z besedami resnice njim, ki te bodo pošiljali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 22, 'Ne pleni siromaka zato, ker je siromak, in ne teptaj ubožca med vrati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 23, 'Zakaj Gospod se potegne za njiju pravdo in opleni dušo njih, ki ju plenijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 24, 'Ne imej prijateljstva z naglojeznim in s togotnim se ne druži:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 25, 'da se ne učiš potov njegovih in pripraviš zanke samemu sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 26, 'Ne bodi izmed njih, ki v roke segajo in jamčijo, izmed njih, ki so poroki za dolgove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 27, 'Ko nimaš, s čimer bi plačal, zakaj naj bi upnik jemal ležišče tvoje izpod tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 28, 'Ne premikaj starega mejnika, ki so ga postavili pradedje tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 22, 29, 'Če vidiš moža, ki je spreten v delu svojem – pred kralji bo služeč stal, ne bo služil nizkim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 1, 'Kadar boš sedel, da ješ z vladarjem, pazi pridno na njega, ki je pred teboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 2, 'drugače nastaviš nož na goltanec svoj, ako bi bil poželjivosti poln.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 3, 'Ne požéli slaščic njegovih, ker je jed varljiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 4, 'Ne trudi se, da bi obogatel: te razumnosti svoje se odvadi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 5, 'Ali naj bi oči vpiral v to, česar skoraj ne bode? Kajti bogastvo si res dela peruti, kakor orel zleti proti nebu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 6, 'Ne uživaj jedi njega, ki ima oko nevoščljivo, in ne poželi slaščic njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 7, 'kajti odmerja ti vse v srcu svojem. „Jej in pij!“ti veli, toda srce njegovo ni s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 8, 'Grižljaj, ki si ga pojedel, boš izbljuval, in izgubil si sladke besede svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 9, 'Vpričo bedaka ne govóri, kajti zaničeval bo razumnost tvojih besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 10, 'Ne premikaj starega mejnika in ne stopaj na njive sirot!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 11, 'Močan je namreč njih odrešenik, on se potegne za njih pravdo zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 12, 'Nagni k pouku srce svoje in ušesa svoja k besedam znanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 13, 'Ne odtezaj dečku strahovanja, kajti če ga udariš s šibo, ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 14, 'Opletaj ga s šibo, in otmeš dušo njegovo iz pekla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 15, 'Sin moj, če je modro srce tvoje, veselilo se bo tudi moje srce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 16, 'in radovale se bodo ledice moje, ko bodo govorile ustne tvoje, kar je pošteno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 17, 'Srce tvoje naj ne zavida grešnikom, ampak góri za strah Gospodov ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 18, 'Zares, še je zate bodočnost, in upanje tvoje se ne bo iztrebilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 19, 'Poslušaj, sin moj, in bodi moder in po ravnem potu vodi srce svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 20, 'Ne bivaj med popivači vina, ne med požeruhi mesa:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 21, 'zakaj požrešnik obuboža in pijanec, in s cunjami se bo oblačil zaspanec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 22, 'Poslušaj očeta svojega, ki te je rodil, in ne zaničuj matere svoje, ko se postara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 23, 'Resnico kupi in je ne prodaj, nabavi si modrosti, pouka in razumnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 24, 'Silno se raduje oče pravičnega, in kdor je rodil modrega, se ga veseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 25, 'Veseli se naj oče tvoj in mati tvoja, in naj se raduje roditeljica tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 26, 'Daj mi, sin moj, srce svoje, in oči naj se ti vesele na potih mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 27, 'Kajti jama globoka je nečistnica in tesen vodnjak tuja žena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 28, 'ker ona kakor razbojnik preži in nezvestnike množi med ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 29, 'Komu gorjé, komu joj? čigavi so prepiri, čigavo jadikovanje? čigave rane brez vzroka? čigava motnost oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 30, 'Njih, ki pozno sedevajo pri vinu, ki hodijo okušat mešano pijačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 31, 'Ne glej vina, ko se zlati, ko kaže v kozarcu barvo svojo! Gladko teče po grlu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 32, 'a naposled piči kakor kača in zbode kakor gad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 33, 'Oči tvoje bodo čudne videle stvari in srce tvoje bo govorilo napačnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 34, 'In bodeš, kakor kdor leži sredi morja in kakor kdor leži na vrhu jadrnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 23, 35, 'Bíli so me, porečeš, a ni me bolelo, tepli so me, nisem čutil. Ko se zbudim, bom nadaljeval, zopet ga poiščem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 1, 'Ne zavidaj hudobnim ljudem in ne želi bivati ž njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 2, 'ker na pogubo misli njih srce in nadlego govore njih ustnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 3, 'Z modrostjo se hiša zida in z umnostjo se utrdi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 4, 'in po znanju se napolnijo hrami z vsem blagom dragim in prijetnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 5, 'Mož modri je močan in umni mož utrjuje krepkost svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 6, 'Kajti z razumnim vodstvom se boš srečno vojskoval in zmago pridobil z množico svetovalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 7, 'Previsoka je neumnežu modrost, pri vratih ne odpre svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 8, 'Kdor misli kaj hudega storiti, imenovali ga bodo gospodarja spletk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 9, 'Namera neumnosti je greh in zasmehovalec je gnusoba ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 10, 'Če ti srce upade v čas stiske, majhna je krepost tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 11, 'Otmi nje, ki jih vlečejo v smrt, in ustavi jih, ki gredo na morišče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 12, 'Če praviš: Glej, nismo vedeli tega! – ali ne bode on, ki srca pretehtava, pazil na to, in ki straži dušo tvojo, ne bo vedel tega? In ne povrne li vsakemu po delu njegovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 13, 'Jej med, sin moj, ker je dober, in čisto strd, sladko tvojemu grlu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 14, 'spoznaj tudi, da je modrost dobra duši tvoji: če si jo dosegel, je zate bodočnost, in upanje tvoje se ne bo iztrebilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 15, 'Ne preži, o brezbožnik, na pravičnega prebivališče, ne razdevaj počivališča njegovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 16, 'Kajti sedemkrat pade pravični, a zopet vstane, brezbožni pa se zvrnejo v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 17, 'Ko pade sovražnik tvoj, ne veseli se, in ko se zgrudi, ne radúj se srce tvoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 18, 'da ne zagleda Gospod in ne bo hudo v očeh njegovih ter ne obrne od njega v tebe jeze svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 19, 'Ne srdi se zaradi hudodelnikov, ne zavidaj brezbožnim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 20, 'kajti prihodnosti ne bode hudemu, brezbožnih svetilnica ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 21, 'Boj se Gospoda, sin moj, in kralja, in z uporniki se ne druži:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 22, 'kajti hipoma vstane njih nesreča, in kdo ve, kakšen bode konec njih let?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 23, 'Tudi to so izreki modrih: Ozirati se na osebo v sodbi ni dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 24, 'Kdor pravi krivičniku: Pravičen si, klela ga bodo ljudstva, mrzeli narodi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 25, 'tistim pa, ki ga karajo, bode prijaznost in pride jim blagoslov dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 26, 'Ustne poljublja, kdor besede prave odgovarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 27, 'Opravi zunaj delo svoje in pripravi si ga na polju, potem lahko zidaš hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 28, 'Ne bodi brez sile priča zoper bližnjega svojega, in zakaj bi varal z ustnami svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 29, 'Ne govóri: Kakor mi je storil, tako mu storim, vsakemu povrnem po delu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 30, 'Šel sem mimo polja lenega moža in mimo vinograda človeka brezumnega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 31, 'pa glej, plevel ga je docela porastel, s koprivami je bilo pokrito površje njegovo in kamenena ograja njegova je bila podrta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 32, 'Tedaj sem gledal in v srcu preudarjal in, videč to, sem posnel nauk:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 33, 'Malo zaspati, malo zadremati, malo roke sklenivši ležati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 24, 34, 'v tem pride kakor uren popotnik uboštvo tvoje in potreba tvoja kakor oboroženec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 1, 'Tudi ti so pregovori Salomonovi, ki so jih zbrali možje Ezekija, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 2, 'Bogu v čast je prikrivati reč, čast kraljev pa izsledovati reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 3, 'Neba višina, zemlje globočina in srca kraljev so nedosežna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 4, 'Vzemi srebru žlindro, in prikaže se zlatarju posoda:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 5, 'vzemi brezbožnega kralju izpred oči, in utrdi se po pravičnosti prestol njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 6, 'Ne prisvajaj si časti pred kraljem in ne stopaj na mesto velikašev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 7, 'kajti bolje je, da ti reko: Pomakni se sem gori! nego da te ponižajo pred knezom, ki so ga videle oči tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 8, 'Ne spuščaj se naglo v prepir, da ob njega koncu ne prideš v zadrego, kaj naj storiš, ko te je osramotil bližnji tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 9, 'Pravdo svojo pravdaj z bližnjim svojim sam, ali skrivnosti drugega ne odkrivaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 10, 'da te ne ograja, kdor to sliši, in ostaneš na slabem glasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 11, 'Kakor zlata jabolka v srebrnih pletenicah je beseda ob pravem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 12, 'Kakor zlata naušnica in okras iz čistega zlata je svaritelj moder pri njem, ki posluša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 13, 'Kakor snežno hladilo ob žetve času je zvest poslanec njemu, ki ga pošilja: kajti dušo gospodarja svojega oživlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 14, 'Oblaki in veter, pa nič dežja – je mož, ki se ponaša z darom lažnivim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 15, 'S potrpežljivostjo se sodnik pridobi in jezik mehak kosti zdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 16, 'Ko najdeš medú, jej, kolikor ti je dosti, da se ga ne presitiš ter ga izbljuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 17, 'Redkoma zahajaj v bližjega svojega hišo, da se te ne naveliča in te ne črti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 18, 'Kladivo in meč in pšica ostra je mož, ki priča krivo zoper bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 19, 'Kakor zdrobljen zob in izvinjena noga je zaupanje v izdajalca v stiske dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 20, 'Kakor kdor sleče obleko o času mraza ali ocet lije na sodo, je, kdor pesmi poje žalostnemu v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 21, 'Če je sovražnik tvoj lačen, siti ga s kruhom, in če je žejen, napoji ga z vodo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 22, 'kajti žerjavice mu nakopičiš na glavo, in Gospod ti bo povrnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 23, 'Severni veter rodi dež: tako obrekljiv jezik lice nejevoljno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 24, 'Bolje je prebivati v podstrešnem kotu nego z ženo prepirljivo v skupni hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 25, 'Kakor mrzla voda duši onemogli, je dobra novica iz daljne dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 26, 'Kakor skaljen studenec in izprijen vrelec je pravičnik, ki umahne pred brezbožnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 27, 'Pojesti preveč medú ni dobro, ali preiskavati težavne stvari je čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 25, 28, 'Mesto razrušeno brez zidú je mož, ki nima duha svojega v oblasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 1, 'Kakor ne sneg poletju in dež žetvi, tako ne pristoji neumnežu čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 2, 'Kakor vrabec, ki semtertja leta, kakor lastovka, ki se izpreletava, tako je kletev nezaslužena: nikogar ne zadene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 3, 'Konju bič, oslu uzdo, bedaku pa šibo na hrbet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 4, 'Ne odgovarjaj bedaku po neumnosti njegovi, da mu ne bodeš tudi ti enak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 5, 'Odgovóri bedaku po neumnosti njegovi, da ne bode moder v svojih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 6, 'Kdor pošilja po bedaku poročilo, odsekava si sam noge in pripravlja si škodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 7, 'Ohlapno so zvezane noge hromčeve: istotako moder izrek v ustih bedakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 8, 'Kakor kdor vrže mošnjo žlahtnih kamenov v grobljo, tako dela, kdor čast izkazuje bedaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 9, 'Kakor trn, ki pride pijanemu v roko, tako je moder izrek v ustih bedakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 10, 'Strelec, ki rani vse, in kdor najme bedaka in postopača, sta enaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 11, 'Kakor se pes vrne k izbljuvku svojemu, tako bedak ponavlja neumnost svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 12, 'Vidiš li moža, ki šteje sam sebe za modrega – več je upanja za bedaka nego za njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 13, 'Lenuh govori: Lev rjoveč je zunaj, lev hodi po ulicah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 14, 'Vrata se vrte na tečaju svojem: tako lenuh na postelji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 15, 'Lenuh pač vtakne roko v skledo, a težko mu jo je pritegniti k ustom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 16, 'Modrejši je lenuh v svojih očeh nego sedmero njih, ki pametno odgovarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 17, 'Za ušesa prime psa, kdor se nepoklican žene v tuj prepir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 18, 'Kakor brezumnik, ki meče ognjene in smrtne pšice:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 19, 'tako je, kdor prekani bližnjega svojega in potem reče: Saj sem se le šalil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 20, 'Ko poidejo drva, ogenj ugasne, in ko ni podpihovalca, molči prepir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 21, 'Oglja je treba za žerjavico in drv za ogenj, moža prepirljivega pa, da vname prepir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 22, 'Besede podpihovalčeve so kakor slaščice, vendar prodirajo v notranjščino telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 23, 'Kakor čepinja, prevlečena s srebrno peno, so goreče ustne in srce hudobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 24, 'Z ustnami svojimi se hlini sovražilec, a v srcu svojem snuje zvijačo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 25, 'ko z blagomilim glasom govori, ne upaj mu, zakaj sedmero gnusob je v srcu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 26, 'Zakriva se sovraštvo s prevaro, a zloba njegova se razodene v zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 27, 'Kdor koplje jamo, vanjo pade, in kdor kamen vali, nanj se zvrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 26, 28, 'Lažnivi jezik sovraži tistega, kogar je zbadal, in medena usta pripravljajo padec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 1, 'Ne ponašaj se z jutrišnjim dnem, kajti ne veš, kaj bo dan rodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 2, 'Hvalijo naj te drugi, ne pa usta tvoja, rajši tujec nego ustnice tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 3, 'Težak je kamen in pesek bremenit, ali neumneža nejevolja je težja od obeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 4, 'Grozovita je togota in jeza je kakor povodenj, ali kdo naj obstane pred nevoščljivostjo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 5, 'Boljša je graja očita nega ljubezen prikrita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 6, 'Udarci prijateljevi so iz zvestih misli, sovražilec pa mnogo poljublja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 7, 'Duša sita tepta satovje, a lačni duši vse grenko je sladko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 8, 'Kakršna je ptica, ki odleti iz svojega gnezda, tak je mož, ki uteče s svojega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 9, 'Mazilo in dišava razveseljujeta srce, ali prijatelj je sladek duši po svetu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 10, 'Prijatelja svojega in očeta svojega prijatelja ne zapústi, a v brata svojega hišo ne hodi v dan nesreče svoje; boljši je bližnji sosed od daljnega brata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 11, 'Bodi moder, sin moj, in razveseljuj srce moje, da lahko odgovorim njemu, ki bi mi kaj očital.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 12, 'Razumni vidi hudo ter se skrije, abotni pa gredo naprej in morajo trpeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 13, 'Vzemi obleko njega, ki je bil porok za tujca, in rubi ga, ki je jamčil za neznanko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 14, 'Njemu, ki navsezgodaj vstane in z močnim glasom blagoslovi prijatelja svojega, se bo štelo za preklinjanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 15, 'Neprestano kapljanje v dan hudega dežja in žena, ki se rada prepira, sta si enaka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 16, 'kdor jo kroti, ustavlja veter: kakor olje se mu izmuzne iz desnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 17, 'Železo se z železom ostri, in mož ostri pogled drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 18, 'Kdor goji smokev, bo jedel sad njen, in kdor skrbno streže gospodarju svojemu, bo spoštovan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 19, 'Kakor se v vodi obraz kaže obrazu, tako srce srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 20, 'Grob in poguba se ne nasitita, tudi oči človeške se ne nasitijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 21, 'Srebro v topilniku in zlato v peči, moža pa izkusimo po tem, s čimer se hvali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 22, 'Ko bi neumneža v stopi z betom stolkel kakor pšeno, ne šla bi neumnost njegova od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 23, 'Skrbno pregleduj stanove živine svoje, pazi na črede svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 24, 'Kajti premožnost ni za vekomaj, in ostane li krona za vse rodove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 25, 'Ko je pod streho spravljeno seno in se prikaže nežna trava in je nabrano gorskih zelišč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 26, 'tedaj so jagnjeta za obleko tvojo in kupna cena za njivo so kozliči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 27, 27, 'in zadosti je kozjega mleka za hrano tvojo, za hrano družine tvoje in živeža deklam tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 1, 'Brezbožni bežé, ko jih nihče ne preganja, pravični pa so kakor mlad lev brez strahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 2, 'Zaradi pregrehe dežele nastopa ji mnogo knezov, a človek razumen in izkušen podaljša pravno vlado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 3, 'Mož, ki je sam ubog in tare siromake, podoben je dežju, ki vse odplavi in kruha ne prinese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 4, 'Kateri zapuščajo postavo, hvalijo brezbožne, kateri pa se držé postave, jim nasprotujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 5, 'Zlobni ljudje ne razumejo, kar je pravo, kateri pa iščejo Gospoda, umejo vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 6, 'Boljši je ubogi, ki hodi v nedolžnosti svoji, nego spačeni, ki se zvija semtertja, če je še tako bogat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 7, 'Kdor hrani postavo, sin je razumen, kdor se pa druži s požrešniki, dela sramoto očetu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 8, 'Kdor blago svoje množi z oderuštvom in podraževanjem, nabira ga njemu, ki bo milostno delil siromakom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 9, 'Kdor odvrača uho svoje, da ne sliši postave, tudi molitev njegova je gnusoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 10, 'Kdor zapeljuje poštene na slabo pot, pade sam v svojo jamo, nedolžni pa podedujejo dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 11, 'Za modrega se sam ima bogatin, ali siromak, ki je razumen, ga spozna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 12, 'Ko zmago slavé pravični, velika je sijajnost, ko se pa povzdigujejo brezbožni, se ljudje skrivajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 13, 'Kdor prikriva pregrehe svoje, ne bo imel sreče, kdor pa se jih obtoži in jih zapusti, doseže usmiljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 14, 'Blagor človeku, ki je v strahu vedno, kdor pa zakrkne srce svoje, zvrne se v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 15, 'Kakor rjoveč lev in gladen medved je brezbožen vladar siromaškemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 16, 'Knez, ki je brez razuma, silno zatira, kdor pa sovraži kriv dobiček, si podaljša dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 17, 'Človek, obremenjen s krvjo človeško, je na begu prav do groba; nihče ga ne zadržuj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 18, 'Kdor hodi nedolžno, se reši, kdor pa je spačen in hodi po dveh potih, pade hipoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 19, 'Kdor obdeluje zemljo svojo, nasiti se kruha, kdor pa hodi za ničemurnimi, nasiti se uboštva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 20, 'Zvest mož je bogat v blagoslovih, kdor pa je nagel, da bi obogatel, ne bode brez kazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 21, 'Ozirati se na zunanjost osebe ni dobro, ker za grižljaj kruha bi grešil mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 22, 'Mož z nevoščljivim očesom hití, da obogati, in ne ve, da mu pride potreba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 23, 'Kdor svari človeka, dobi pozneje več naklonjenosti, nego kdor se dobrika z jezikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 24, 'Kdor krade očetu svojemu ali materi svoji ter pravi: To ni greh! tovariš je možu ubijalcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 25, 'Prešernež vnema prepir, kdor pa ima nado v Gospoda, obilo mu bode vsega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 26, 'Kdor se zanaša na srce svoje, je bedak, kdor pa hodi modro, bo rešen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 27, 'Kdor daje ubogemu, ne bode mu potrebe, kdor pa zagrinja oči svoje, ga obsipajo s kletvinami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 28, 28, 'Ko se povzdigujejo brezbožni, skrivajo se ljudje, ko pa pogibljejo, množijo se pravični.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 1, 'Mož, ki, večkrat posvarjen, postane trdovraten, se zdrobi nagloma, tako da mu ne bode zdravila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 2, 'Ko se množe pravični, veseli se ljudstvo, ko pa gospoduje brezbožnik, ljudstvo vzdihuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 3, 'Kdor ljubi modrost, razveseljuje očeta svojega, kateri se pa druži z vlačugami, zapravlja blago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 4, 'Kralj s pravo sodbo utrjuje deželo, oni pa, ki zahteva dari, jo razdeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 5, 'Mož, ki se prilizuje prijatelju svojemu, razpenja mrežo nogam njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 6, 'V pregrehi hudobneža je zadrga, pravični pa prepeva in je vesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 7, 'Pravični spoznava pravdo siromakov, brezbožni se ne zmeni, da bi jo spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 8, 'Ljudje zasmehovalci zažigajo mesto, modri pa odvračajo jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 9, 'Če se modri prepira z neumnim, naj se jezi, naj se smeje, vendar ni nobenega miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 10, 'Ljudje krvoželjni sovražijo brezmadežnega, pošteni pa skrbé za dušo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 11, 'Ves svoj gnev izliva bedak, modri pa ga zadržuje in miri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 12, 'Ako vladar rad posluša lažnivosti besede, bodo vsi služabniki njegovi brezbožni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 13, 'Ubožec in oderuh se srečujeta; obeh oči razsvetljuje Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 14, 'Kralju, ki zvesto sodi siromake, bo prestol utrjen na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 15, 'Šiba in strah dajeta modrost, deček pa, sam sebi prepuščen, dela sramoto materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 16, 'Ko se množe brezbožni, množi se greh, pravični pa bodo videli njih padec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 17, 'Strahúj sina svojega, in pripravi ti pokoj in veselje duši tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 18, 'Ko ni razodetja, se ljudstvo razuzda; kdor pa se drži postave, o blagor mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 19, 'Z golimi besedami se ne poboljša hlapec: umeje jih pač, a ne ravna se po njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 20, 'Ali si videl moža, naglega v besedah svojih? Več je upanja za bedaka nego za njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 21, 'Kdor mehkužno od mladega vzreja svojega hlapca, dočaka, da se bo naposled vedel kot sin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 22, 'Naglojezni napravlja prepire in togotni je greha poln.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 23, 'Napuh človeka poniža, kdor pa je ponižnega duha, doseže slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 24, 'Kdor deli s tatom, sovraži dušo svojo; preklinjanje sliši, pa greha ne naznani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 25, 'Kdor se človeka boji, si stavi zanko; kdor pa upa v Gospoda, bode obvarovan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 26, 'Mnogo jih išče obličje vladarjevo, ali od Gospoda je vsakega pravica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 29, 27, 'Krivičnik je gnusoba pravičnim, in brezbožnemu je gnusoba, kdor pošteno hodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 1, 'Besede Agurja, Jakejevega sina; proroški govor. Govoril je mož Itielu, Itielu in Ukalu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 2, 'Res, nespameten sem, bolj nego drugi, in umnosti človeške nimam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 3, 'in nisem se učil modrosti in spoznanja Najsvetejšega nimam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 4, 'Kdo je šel gori v nebesa in zopet stopil doli? kdo je zbral veter v pesteh svojih? kdo je zvezal vode v oblačilo? kdo je določil vse meje zemlje? katero je ime njegovo in katero sina njegovega ime? Povej, če veš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 5, 'Vsak govor Božji je prečiščen: on je ščit njim, ki pribegajo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 6, 'Ne pridevaj besedam njegovim, da te ne ustrahuje in te ne zasači v laži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 7, 'Dvojega te prosim, ne odrekaj mi tega, dokler živim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 8, 'Ničemurnost in besedo lažnivo odpravi daleč od mene; ne uboštva, ne bogastva mi ne dajaj, hrani me s kruhom, kolikor mi je potreba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 9, 'da se ne presitim in, zatajivši Te, ne rečem: Kdo je Gospod? ali da ne obubožam in ne kradem in zlo ne rabim imena Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 10, 'Ne črni hlapca pred gospodom njegovim, da te ne bo klel in ne boš trpel za krivdo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 11, 'Je rod, ki kolne očeta svojega in matere svoje ne blagoslavlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 12, 'Je rod, ki je čist v svojih očeh, dasi ni opran nesnage svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 13, 'Je rod – o kako visoko gledajo njegove oči in trepalnice njegove se povzdigujejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 14, 'Je rod, čigar zobje so meči in kočniki njegovi noži, da požre uboge z zemlje in potrebne izmed ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 15, 'Pijavka ima dve hčeri: Daj, daj! Troje je nenasitno, in četvero, ki nikdar ne reče: Dovolj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 16, 'Grob in maternica neplodna, zemlja, ki se ne napoji vode, in ogenj, ki ne pravi: Dovolj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 17, 'Oko, ki zasmehuje očeta in zameta pokorščino materi – izkljujejo krokarji potočni in požro mladi orli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 18, 'Troje mi je prečudno, in četvero, česar ne umejem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 19, 'pot orla pod nebom, pot kače na skali, pot ladje na morju globokem in moža pot k dekletu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 20, 'Enako je pot ženske, ki prešeštvuje! Ona jé, potem si obriše usta in pravi: Nisem storila krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 21, 'Pod trojim se giblje zemlja in pod četverim, česar ne more prenašati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 22, 'pod hlapcem, ko postane kralj, in pod malopridnežem, ko ima zadosti kruha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 23, 'pod zoprno žensko, ko se omoži, in pod deklo, ko se za dedinjo naredi gospodinji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 24, 'To četvero je majhno na zemlji, ali modrejše od modrijanov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 25, 'mravlje, ljudstvo slabotno, vendar znašajo po leti hrano svojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 26, 'skalni jazbeci, ljudstvo nejako, vendar si delajo v skalovju hiše svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 27, 'kobilice nimajo kralja, vendar gredó redoma skupaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 28, 'kuščarica, ki jo lahko primeš z rokami, a biva v palačah kraljevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 29, 'To troje ima lepo hojo, in četvero lepo stopa:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 30, 'lev, junak med živalmi, ki se nikomur ne umakne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 31, 'z opasanim ledjem konj, tudi kozel, in kralj, pri katerem je sklicana vojska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 32, 'Če si bil neumen, povzdigujoč sebe, ali si kaj slabega mislil, položi roko na usta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 30, 33, 'Kajti stiskanje mleka da maslo in nos stiskan izpusti kri: draženje pa rodi prepir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 1, 'Besede Lemuela kralja; proroški govor, s katerim ga je poučevala mati njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 2, 'Kaj naj ti svetujem, sin moj? kaj pač, sin telesa mojega, in kaj, sin obljub mojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 3, 'Ne dajaj ženskam moči svoje in potov svojih pogubnicam kraljev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 4, 'Ne spodobi se kraljem, o Lemuel, ne kraljem, da pijo vino, ne knezom, da vprašujejo: Kje je pijača opojna?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 5, 'Da ne bi, ko so pili, pozabili postave in prevračali pravice komu, ki je v nadlogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 6, 'Dajajte močne pijače njemu, ki pogiblje, in vina njim, ki so v bridkosti duše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 7, 'pije naj in pozabi uboštvo svoje in se nadloge svoje ne spominja več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 8, 'Odpri usta svoja za nemega, za pravdo vseh osirotelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 9, 'Odpri usta svoja, sodi pravično, potezaj se za pravico siromaku in potrebnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 10, 'Vrlo ženo kdo najde? kajti visoko presega bisere cena njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 11, 'Zaupa ji srce moža njenega, in dobička mu ne zmanjka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 12, 'Ona mu izkazuje dobro in ničesar hudega vse dni življenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 13, 'Skrbi za volno in lan, in veselo dela z rokami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 14, 'Podobna je ladjam trgovskim: oddaleč prinaša hrano svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 15, 'In vstaja, ko je še noč, ter deli jed družini svoji in delo deklam svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 16, 'Ogleda si njivo in jo pridobi, in z dobičkom rok svojih si zasadi vinograd.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 17, 'Z močjo opazuje ledje svoje in roke svoje utrjuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 18, 'Izkuša, da dober je prislužek njen: ne ugasne svetilnica njena ponoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 19, 'Roke svoje izteguje po preslici in prsti njeni držé vreteno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 20, 'Dlan svojo odpira ubogemu in potrebnemu podaja roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 21, 'Ne boji se snega za družino svojo, kajti vsa družina njena se oblači s karmezinasto volno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 22, 'Odeje si pripravlja, tenčica in škrlat je oblačilo njeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 23, 'Znan je pri vratih mož njen, ko zboruje s starejšinami dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 24, 'Tenko platno dela in prodaja, tudi pas izroča trgovcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 25, 'Moč in dostojnost je obleka njena in smeje se časom prihodnjim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 26, 'Usta svoja odpira modro in ljubezni uk ji je na jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 27, 'Družine svoje pota pregleduje in lenobe kruha ne jé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 28, 'Sinovi njeni vstajajo ter jo blagrujejo, mož njen jo hvali enako:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 29, '„Mnoge hčere so vrlo ravnale, ti pa jih vse presegaš!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 30, 'Lažniva je prijetnost in ničeva lepota: žena, ki se boji Gospoda, njej veljaj hvala!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (20, 31, 31, 'Dajte ji od sadú njenih rok in pri vratih naj jo hvalijo dela njena!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 1, 'Besede Propovednika, sinu Davidovega, kralja v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 2, 'Ničemurnost nečimurna! pravi Propovednik; ničemurnost ničemurna, vse je ničemurno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 3, 'Kaj ima dobička človek od vsega truda svojega, s katerim se trudi pod solncem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 4, 'Rod mineva, rod prihaja, a zemlja vedno ostaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 5, 'In solnce vzhaja in solnce zahaja in hiti k mestu svojemu, odkoder izhaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 6, 'Veter gre proti poldnevu in se obrača proti polnoči in kroži in kroži, in krožitve svoje vedno ponavlja veter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 7, 'Vse reke teko v morje, in morje se ne prepolni; v kraj, kamor teko reke, tja vedno in vedno teko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 8, 'Vse stvari so trudapolne: človek ne more tega dopovedati; oko se ne nasiti gledanja, ne uho poslušanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 9, 'Kar je bilo, bode zopet, in kar se je storilo, se bo zopet storilo, in nič novega ni pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 10, 'Je li kaj, o čemer pravijo: Glej, to je novo? Zdavnaj je že bilo v vekih, ki so bili pred nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 11, 'Ni spomina prejšnjih rodov, in prihodnjim, ki še bodo, tudi ne bo spomina pri tistih, ki pozneje nastanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 12, 'Jaz, Propovednik, sem bil kralj nad Izraelom v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 13, 'In obrnil sem srce svoje v to, da bi z modrostjo preiskoval in zasledoval vse, kar se godi pod nebom: težko opravilo, ki ga je naložil Bog sinom človeškim, da se ž njim ukvarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 14, 'Videl sem vse dejanje, ki se godi pod solncem, in glej, vse je ničemurnost in lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 15, 'Kar je krivo, se ne more zravnati, in česar ni, se ne more šteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 16, 'Govoril sem v srcu svojem in rekel: Glej, dobil sem veliko modrost in prekosil vse, ki so bili pred menoj v Jeruzalemu, in srce moje je videlo obilost modrosti in spoznanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 17, 'In obrnil sem srce svoje v to, da spoznam modrost in da spoznam nespamet in neumnost: spoznal sem, da je tudi to lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 1, 18, 'Zakaj pri mnogi modrosti je mnogo nejevolje, in kdor množi znanje, množi bolečino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 1, 'Rekel sem v srcu svojem: Daj le, da te izkusim z veseljem; uživaj, kar je dobro! A glej, tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 2, 'Smehu sem dejal, da je nespamet, in veselju, kaj pač napravi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 3, 'Namenil sem se v srcu, streči telesu svojemu z vinom, a vodi naj me pri tem z modrostjo srce moje, in se poprijeti nespameti, dokler spoznam, kaj bi bilo dobro sinovom človeškim delati vse svoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 4, 'Lotil sem se velikih del: zidal sem si hiše, zasajal si vinograde,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 5, 'napravljal sem si vrte in nasade in v njih zasajal vsakršno sadno drevje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 6, 'naredil sem si vodnjake, da bi iz njih namakal gozd rastočega drevja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 7, 'Kupil sem si hlapcev in dekel in imel doma rojene hlapce; tudi sem imel velike črede govedi in drobnice, več nego vsi, ki so bili pred menoj v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 8, 'Nakopičil sem si tudi srebra in zlata in dragotin, lastnih kraljem in deželam; oskrbel sem si pevcev in pevk in kar je sinom človeškim v veselje: ženo in žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 9, 'Tako sem postal velik in sem prekosil vse, ki so bili pred menoj v Jeruzalemu; tudi modrost moja je ostala pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 10, 'In karkoli so želele moje oči, nisem jim odrekel; srcu svojemu nisem zabranil nobenega veselja, kajti srce moje se je veselilo ob vsem trudu mojem, in to je bil moj delež od vsega truda mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 11, 'Potem sem se ozrl po vseh delih svojih, ki so jih storile roke moje, in po trudu, ki sem si ga prizadel, da bi bil vse dovršil; in glej, vse je bilo ničemurnost in lovljenje vetra, in dobička ni pod solncem nobenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 12, 'In obrnil sem se, da bi gledal modrost in nespamet in budalost. Ker kaj more delati človek, ki pride za kraljem? To, kar so oddavnaj delali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 13, 'In videl sem, da je boljša modrost nego budalost, prav kakor je boljša svetloba od teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 14, 'Modri ima oči v glavi, bedak pa hodi po temi. A hkrati sem tudi zaznal, da se jim vsem godi po isti naključbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 15, 'Tedaj sem dejal v srcu svojem: Kakor se godi bedaku, se naključi tudi meni, in čemu sem potem tolikanj moder? In rekel sem v srcu svojem, da je ničemurnost tudi to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 16, 'Zakaj modremu in enako bedaku ne bode večnega spomina, ker v prihodnjih dneh bode že vse pozabljeno. Ah, kako da mora umreti modrec takisto kakor bedak!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 17, 'Tedaj sem sovražil življenje, ker mi ni ugajalo dejanje, ki se godi pod solncem; kajti vse je ničemurnost in lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 18, 'In zasovražil sem ves trud svoj, s katerim sem se trudil pod solncem, zato ker ga moram zapustiti človeku, ki bode za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 19, 'In kdo ve, bode li moder ali nespameten? Pa vendar bo vladal vsemu, kar sem s težkim trudom in z modrostjo pridobil pod solncem. Ničemurnost je tudi to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 20, 'Tedaj sem se obrnil, da bi izročil srce obupu nad vsem trudom, s katerim sem se trudil pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 21, 'Kar si je namreč kdo težko pridobil z modrostjo in z znanjem in s spretnostjo, to mora zapustiti v delež človeku, ki se ni trudil za to. Tudi to je ničemurnost in veliko zlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 22, 'Ker kaj ima človek pri vsem trudu svojem in pri srca svojega teženju, s katerim se trudi pod solncem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 23, 'Kajti vse dni svoje trpi bolečine in nejevoljo pri opravilu svojem, celo po noči ni počitka njegovemu srcu. Tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 24, 'Nič ni boljšega za človeka, nego da bi jedel in pil in dal duši svoji uživati dobro v trudu svojem. A videl sem, da je tudi to iz roke Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 25, 'Kajti kdo more jesti in kdo more uživati kaj brez Njega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 2, 26, 'Človeku namreč, ki Mu ugaja, daje Bog modrost, spoznanje in veselje; ali grešniku daje težavo, da spravlja in kopiči, pa vse zapusti njemu, ki Bogu ugaja. Tudi to je ničemurnost in lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 1, 'Vse ima svoj določeni čas in vsako početje pod nebom svojo dobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 2, 'Je čas rojenja in je čas smrti; je čas, da se sadi, in čas, da se vsajeno izruje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 3, 'je čas morjenja in čas ozdravljanja, čas podiranja in čas zidanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 4, 'čas jokanja in čas smejanja, čas žalovanja in čas plesanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 5, 'čas razmetavanja kamenov in čas zbiranja kamenov, čas objemanja in čas, zdrževati se objemanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 6, 'čas iskanja in čas izgubljanja, čas spravljanja in čas zametanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 7, 'čas, da se raztrga, in čas, da se sešije, čas molčanja in čas govorjenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 8, 'čas ljubezni in čas sovraštva, čas vojne in čas miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 9, 'Kaj ima koristi, kdor karkoli dela, od tega, s čimer se trudi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 10, 'Videl sem trudno opravilo, ki ga je Bog dal otrokom človeškim, da se ž njim ukvarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 11, 'On je vse storil, da je lepo ob svojem času; tudi večnost jim je položil v srce, samo da ne more človek doumeti dela, ki ga je Bog napravil, od začetka do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 12, 'Spoznal sem, da ni nič boljšega med njimi, nego da se veselé in delajo dobro v življenju svojem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 13, 'pa tudi, ko človek jé in pije in uživa dobro pri vsem trudu svojem, da je to vsakemu dar Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 14, 'Spoznal sem, da bode vse, kar Bog dela, za večno: nič se temu ne more prideti, nič od tega vzeti; in Bog je to storil, da se ga boje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 15, 'Kar je, je bilo že preje, in kar bode, je bilo zdavnaj, in Bog gleda, da pride na svetlo, kar je minilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 16, 'Dalje sem videl pod solncem: na mestu sodbe je bila nepravda in na mestu pravičnosti je bila brezbožnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 17, 'Rekel sem v srcu svojem: Bog bo sodil pravičnega in brezbožnega, zakaj on je določil čas vsakemu počenjanju in vsakemu delu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 18, 'Rekel sem v srcu svojem: Zaradi otrok človeških se tako godi, da jih Bog izkusi in da vidijo, da sami ob sebi so kakor živina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 19, 'Kajti kar se naključi otrokom človeškim in kar se naključi živalim, je ista naključba: kakor te umrjo, umrjo tudi oni, in enak dih imajo vsi, in človek nima prednosti proti živini; zakaj vse je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 20, 'Vse gre na eno mesto; vse je postalo iz prahu in vse se vrača zopet v prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 21, 'Kdo pozna dih otrok človeških, če gre navzgor, in dih živine, če gre navzdol k zemlji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 3, 22, 'Tako sem videl, da ni nič boljšega, nego da se človek veseli del svojih, zakaj to je delež njegov. Kajti kdo ga privede nazaj, da bi videl, kaj bode za njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 1, 'In obrnil sem se in sem videl vse stiskanje, kar se ga godi pod solncem; in glej, solze stiskanih, in niso imeli tolažitelja; in na strani njih tlačiteljev je bila moč in ni jim bilo tolažitelja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 2, 'Zato sem blagroval mrtve, ki so bili davno umrli, bolj nego žive, ki so še v življenju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 3, 'in za srečnejšega nego oboje sem štel njega, ki ga še ni bilo, ki še ni videl zlega dejanja, ki se godi pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 4, 'Tedaj sem videl ves trud in ves uspeh v delu, da zaradi tega zavidajo drug drugemu. Tudi to je ničemurnost in lovljenje vetra!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 5, 'Bedak sklepa roke in jé svoje lastno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 6, 'Boljša je peščica s pokojem nego dve pesti, polni truda in lovljenja vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 7, 'In obrnil sem se in sem videl ničemurnost pod solncem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 8, 'Samec je in nima druga, tudi nima sina, ne brata, a mnogemu trudu njegovemu ni konca; pri vsem tem se ne nasitijo bogastva oči njegove. Ne misli: Za koga se trudim in kratim duši svoji dobro? Tudi to je ničemurnost in prehudo opravilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 9, 'Bolje je dvema nego enemu, ker imata dobro plačilo za svoj trud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 10, 'Zakaj če padeta, vzdigne tovariš tovariša; ali gorje samemu, ko pade in nima druga, da bi ga vzdignil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 11, 'Tudi kadar dva vkup ležita, se grejeta; a kako se hoče kdo zgreti, ko je sam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 12, 'In če enega siloma napadejo, se dva v bran postavita; in trojna vrvica se ne raztrga lahko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 13, 'Boljši ubog in moder deček nego star in bedast kralj, ki nima več toliko uma, da bi se dal posvariti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 14, 'Zakaj iz jetnišnice je prišel deček, da bi kraljeval, čeprav se je ubog rodil v kraljestvu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 15, 'Videl sem vse živeče, ki hodijo pod solncem, da so bili pri dečku, drugem, ki je imel stopiti na onega mesto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 4, 16, 'ni bilo konca vsemu tistemu ljudstvu, ki mu je bil na čelu; a potomci se ga ne bodo veselili. Res, tudi to je ničemurnost in lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 1, 'Pazi na nogo svojo, kadar greš v hišo Božjo! Kajti bližati se, da poslušaš, je bolje nego darovati bedakov daritve; nimajo namreč spoznanja, da delajo hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 2, 'Ne bodi nagel s svojimi usti in srcu svojemu ne daj hiteti, da izreče besedo pred Bogom; zakaj Bog je v nebesih, ti pa si na zemlji: zato bodi tvojih besed malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 3, 'Kajti sanje prihajajo po mnogem trudu in bedak se oglaša z mnogimi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 4, 'Kadar storiš obljubo Bogu, je ne odlašaj izpolniti; kajti Njemu ne ugajajo bedaki. Kar obljubiš, izpolni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 5, 'Bolje, da ne obljubiš, nego da obljubiš, a ne izpolniš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 6, 'Ne dopusti ustom svojim, da v greh zapeljejo meso tvoje, in ne govóri pred poslancem Božjim: Bila je pomota! Čemu naj bi se jezil Bog nad glasom tvojim in uničil rok tvojih delo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 7, 'Zakaj pri mnogih sanjah in besedah je tudi mnogo ničemurnosti. Le Boga se boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 8, 'Kadar vidiš, da stiskajo uboge ter da siloma dero sodbo in pravičnost v deželi, ne čudi se tej reči; kajti visok čuva nad visokim, a nad njima je še višji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 9, 'A kralj, ki služi poljedelstvu, je vsekakor deželi v prid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 10, 'Kdor ljubi srebro, ne bo nikoli srebra sit, in kdor ljubi bogastvo, ne dobi nikdar dosti. Tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 11, 'Ko se množi imovina, se množe tudi tisti, ki jo uživajo; in kakšen užitek ima posestnik, nego da jo z očmi gleda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 12, 'Delavcu je spanje sladko, če je jedel veliko ali malo; bogatinu pa sitost ne da mirno spati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 13, 'Je hudo zlo, ki sem ga videl pod solncem: bogastvo, ki si ga hrani njega posestnik sebi v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 14, 'Ker tako bogastvo se izgubi po zli nezgodi, in sinu, ki ga je rodil, ga ne ostane nič v roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 15, 'Kakor je prišel nag iz telesa matere svoje, prav tako zopet odide in za trud svoj ne vzame še kaj malega ne, kar bi v roki odnesel s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 16, 'Pa tudi to je hudo zlo, da mora oditi prav tako, kakor je prišel; in kaj ima dobička od tega, da se trudi za veter?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 17, 'Vrhutega mora vse svoje dni jesti v temi in ima dosti nejevolje, bolezni in jeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 18, 'Glej, kar sem spoznal za dobro in za lepo: da človek jé in pije in uživa dobro pri vsem trudu svojem, s katerim se trudi pod solncem, vse dni svojega življenja, kar mu jih je Bog dal; kajti to je delež njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 19, 'Saj vsakemu človeku, ki mu je Bog dal bogastvo in zaklade in ga je pooblastil, da to uživa in vzame delež svoj in se veseli pri trudu svojem, prav to je dar Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 5, 20, 'Kajti ne bo se veliko spominjal dni življenja svojega; ker mu Bog odgovarja v veselju srca njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 1, 'Je zlo, ki sem ga videl pod solncem, in težko tlači ljudi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 2, 'Bog podeli komu bogastva in zakladov in časti, da ne manjka duši njegovi ničesar, karkoli bi si želel: a Bog mu ne da oblasti, da bi to užival, ampak tujec bo užil! To je ničemurnost in huda bolečina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 3, 'Ako bi kdo rodil sto otrok in živel mnogo let, kakorkoli veliko bi bilo let njegovih število, a duša njegova bi se ne nasitila dobrega in nazadnje bi mu ne napravili pogreba, tedaj rečem: Izpovitek je srečnejši od njega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 4, 'Ker ta pride v ničevosti in se odpravi v temi in njegovo ime ostane skrito v temi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 5, 'solnca tudi ni videl, ne česa spoznal. Ta počiva bolje nego on.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 6, 'In ako bi bil tudi dvakrat tisoč let živel, pa ne videl nič dobrega: ne gre li vse v en kraj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 7, 'Ves trud človekov je za usta njegova, a duša se mu vendar ne nasiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 8, 'Ker kaj ima modri več nego bedak? kaj ubožec, ki se ume vesti pred živečimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 9, 'Bolje, da oči kaj vidijo, nego da želje okoli tavajo. Tudi to je ničemurnost in lovljenje vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 10, 'Kar je postalo, je bilo že zdavnaj imenovano. In Bogu je znano, kaj bode človek, in ta se ne more pravdati z Onim, ki je močnejši od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 11, 'In ker je mnogo besed, ki pomnožujejo ničemurnost, kaj ima dobička človek od tega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 6, 12, 'Kajti kdo ve, kaj je dobro človeku v življenju, vse dni ničemurnega življenja njegovega, ki jih preživi kakor senca? Kajti kdo more povedati človeku, kaj bode za njim pod solncem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 1, 'Dobro ime je boljše nego dišeče mazilo in dan smrti boljši nego dan rojstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 2, 'Bolje je iti v hišo žalosti nego v hišo pojedine, ker v oni se vidi konec vseh ljudi, in živeči si to vtisne v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 3, 'Boljša je žalost nego smeh, kajti po otožnem obličju se poboljšava srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 4, 'Srce modrih je v hiši žalosti, bedakov srce pa v hiši veselja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 5, 'Bolje je poslušati karanje modrega nego petje bedakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 6, 'Kajti smeh bedakov je kakor prasketanje trnja, gorečega pod loncem. Tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 7, 'Res, nasilstvo omami modrega in podkupilo uniči razum.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 8, 'Boljši je konec reči nego njen začetek; boljši je potrpežljivi nego ošabni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 9, 'Ne bodi prenaglega duha za jezo, kajti jeza počiva v nedrjih bedakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 10, 'Ne govóri: Kako da so bili prejšnji dnevi boljši nego sedanji? Kajti tega ne vprašuješ v modrosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 11, 'Modrost je enako dobra kakor dediščina in še boljša njim, ki gledajo solnce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 12, 'Kajti modrost je obrana in denar je obrana, toda prednost znanja je ta, da modrost ohrani v življenju njega, kdor jo ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 13, 'Glej delo Božje! Kajti kdo more zravnati, kar je on skrivil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 14, 'Ob dnevi blagostanja bodi vesel, a ob dnevi nesreče pomisli: Tudi ta dan je Bog naredil z onim vred, da človek ne iznajde, kar bode za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 15, 'Marsikaj sem videl v dnevih ničemurnosti svoje: je pravičnik, ki gine v pravičnosti svoji, in je brezbožnik, ki podaljša življenje svoje v hudobnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 16, 'Ne bodi prepravičen in ne kaži se modrega čez mero: zakaj bi se pogubljal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 17, 'Ne bodi preveč brezbožen in ne bodi bedast: zakaj bi umrl, preden pride tvoj čas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 18, 'Dobro je, da se oprimeš tega, pa tudi onega ne izpustiš iz roke, zakaj kdor se boji Boga, uide vsem tem skrajnostim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 19, 'Modrost jači modrega bolj nego deset mogotcev, ki so v mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 20, 'Res, na zemlji ni pravičnega človeka, ki dela dobro in ne greši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 21, 'Naj ti tudi ne sega do srca vse, kar se govori, da ne boš moral slišati, kako te hlapec tvoj preklinja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 22, 'kajti mnogoterikrat, tvoje srce ve, si tudi ti druge klel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 23, 'Vse to sem preizkušal v modrosti. Dejal sem: Hočem biti moder, a daleč je ostala od mene modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 24, 'Daleč je, kar je, in pregloboko: kdo more to doseči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 25, 'Obrnil sem se in srce mi je bilo namenjeno, spoznavati in zasledovati in iskati modrost in pravi razsodek, da bi spoznal, kako je brezbožnost neumna in nespamet besna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 26, 'In našel sem, kar je grenkejše nego smrt: ženo, čije srce se mreže in zadrge in roke njene spone. Kdor je ugoden Bogu, ji ubeži, grešnika pa ulovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 27, 'Poglej, to sem našel, pravi Propovednik, ko sem zlagal drugo z drugim, da bi dobil pravi razsodek:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 28, 'Česar duša moja še vedno išče, pa nisem našel, je to: enega moža iz tisoč sem našel, ali žene med temi vsemi nisem našel nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 7, 29, 'Poglej, samo to sem našel, da je Bog ustvaril človeka poštenega, oni pa iščejo veliko spletk!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 1, 'Kdo je kakor modrijan? in kdo zna razlago stvari? Modrost razsvetljuje človeku obraz, in trma z lica njegovega izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 2, 'Jaz ti svetujem: Ukaz kraljev spoštuj, in to z ozirom na prisego Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 3, 'Ne prenagli se, da greš izpred obličja njegovega, in ne vtikaj se v hudo reč! Zakaj on stori vse, kar hoče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 4, 'ker beseda kraljeva ima moč, in kdo mu more reči: Kaj delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 5, 'Kdor izpolnjuje zapoved, se ne ozira na nič hudega; in srce modrega razpoznava čas in pravo sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 6, 'Zakaj za vsako početje je čas in sodba; kajti težko obremenja človeka zlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 7, 'Zakaj on ne ve, kaj se zgodi; ker kdo mu oznani, kako se zgodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 8, 'Noben človek ni vladar duhu, da bi zadržal duha; in nihče nima vlade nad dnevom smrti; in v vojski ni nobenega oproščenja; in brezbožnost ne reši tistega, ki ji je vdan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 9, 'Vse to sem videl, in obrnil sem srce svoje k vsemu dejanju, ki se godi pod solncem, ob času, ko človek vlada ljudem v njih nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 10, 'In tako sem videl brezbožne, da so jih pokopavali in so prišli v grob; tisti pa, ki so prav ravnali, so morali oditi iz svetega kraja in so jih pozabili v mestu. Tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 11, 'Ker se hitro ne izvrši sodni izrek proti hudemu dejanju, zato je srce otrok človeških polno smelosti, da delajo hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 12, 'Čeprav grešnik stokrat stori hudo in se mu daljšajo dnevi, vendar vem za gotovo, da se bo njim, ki se Boga boje, dobro godilo, ker se ga boje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 13, 'ali brezbožniku se ne bo dobro godilo, tudi ne podaljša dni svojih, ki so kakor senca, ker se Boga ne boji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 14, 'Je ničemurnost, ki se dogaja na zemlji: da so pravični, katerim se godi po delih brezbožnikov, in so brezbožni, katerim se godi po delih pravičnikov. Rekel sem, da tudi to je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 15, 'Tedaj sem hvalil veselje, ker ni nič boljšega človeku pod solncem, nego da jé in pije in se veseli, in to naj pri njem ostane ob trudu njegovem vse njegove žive dni, kar mu jih je dal Bog pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 16, 'Ko sem obrnil srce svoje v to, da bi spoznaval modrost in ogledoval počenjanje, ki se godi na zemlji (saj tudi ne okusi človek ne po dne, ne po noči spanja s svojimi očmi):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 8, 17, 'tedaj sem videl glede vsega dela Božjega, da človek ne more doumeti dela, ki se godi pod solncem; kakorkoli se napenja, da ga izsledi, ga z umom ne doseže; in čeprav bi modrijan menil, da ga razume, ga vendar ne bo mogel doseči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 1, 'Kajti vse to sem premišljeval v srcu, da bi vse to preizkusil: da so pravični in modri in njih dela v roki Božji; bodisi ljubezen ali sovraštvo, človek tega vnaprej ne pozna; vse je pred njimi v prihodnosti skrito.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 2, 'Vse je enako vsem, eno naključje za pravičnega in brezbožnega, za dobrega in čistega in nečistega, za njega, ki daruje, in za njega, ki ne daruje; enako dobremu kakor grešniku, enako njemu, ki prisega, kakor njemu, ki se prisege boji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 3, 'To je zlo v vsem, kar se godi pod solncem, da eno naključje zadeva vse, pa tudi srce otrok človeških je polno zlobe in blaznosti, dokler žive, in potem gredo k mrtvim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 4, 'Zakaj njemu, ki je združen z vsemi živečimi, je še upanje; ker tudi živečemu psu je bolje nego mrtvemu levu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 5, 'Kajti živeči vedo, da jim je umreti, mrtvi pa ničesar ne vedo ter nimajo plačila več, ker je njih spomin pozabljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 6, 'Kakor njih ljubezen, tako je njih sovraštvo in njih gorečnost davno izginila, in nimajo več deleža vekomaj na vsem, kar se godi pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 7, 'Pojdi, jej z veseljem kruh svoj in pij vino svoje z blagim srcem; kajti Bog je že zdavnaj odobril dejanje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 8, 'Ob vsakem času naj bodo čista oblačila tvoja in olja naj ne manjka na glavi tvoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 9, 'Uživaj življenje z ženo, ki jo ljubiš, vse dni svojega ničemurnega življenja, ki ga ti je dal pod solncem, vse dni ničemurnosti svoje; kajti to je tvoj delež v življenju in v trudu, s katerim se trudiš pod solncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 10, 'Čvrsto se poprimi vsega, kar ti pride pod roko, da storiš z močjo svojo; kajti ni ne dela, ne preudarjanja, ne znanja, ne modrosti v kraju smrti, kamor greš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 11, 'Obrnil sem se, in videl sem pod solncem, da ni hitrim zagotovljen tek, ne junakom zmaga, tudi ne modrim kruh, a tudi ne razumnim bogastvo, in tudi ne veščakom priljubljenost, kajti čas in razmere naklanjajo vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 12, 'Kajti tudi svojega časa ne ve človek; kakor ribe, ki se ujamejo v pogubno mrežo, in kakor ptice, ki se zadrgnejo v zanko, tako se zapleto otroci človeški v mrežo ob času nesreče, ko jih nenadoma zadene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 13, 'Tudi to sem videl kot modrost pod solncem, in zdelo se mi je veliko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 14, 'Bilo je majhno mesto in malo ljudi v njem, in prišel je zoper njega velik kralj in ga obkolil in zgradil obležne nasipe proti njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 15, 'A živel je v njem ubog, pa moder mož, ki je rešil mesto po modrosti svoji; ali nihče se ni spomnil tega ubogega človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 16, 'Tedaj sem rekel: Modrost je boljša nego moč; toda modrost ubožčevo zaničujejo in besed njegovih ne poslušajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 17, 'Besede modrih, ki jih slišimo na tihem, so boljše nego vpitje vladarja med bedaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 9, 18, 'Modrost je boljša nego vojno orožje, ali eden grešnik pokazi mnogo dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 1, 'Mrtve muhe napravijo, da se mazilarju mazilo skazi in usmradi: enako malo neumnosti lahko prevlada modrost in slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 2, 'Modrega srce je na pravi strani njegovi, a bedakovo na napačni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 3, 'Saj tudi ko po poti gre, manjka bedaku razuma in vsakemu pove, da je bedak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 4, 'Ako se vzdigne vladarjeva jeza zoper tebe, ne zapusti mesta svojega; kajti krotkost zabrani velike pregrehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 5, 'Je zlo, ki sem ga videl pod solncem, pomota namreč, ki jo povzroča vladar:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 6, 'neumnost posajajo na najvišja mesta in bogatini morajo sedeti na nizkih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 7, 'Videl sem hlapce na konjih, knezi pa so šli peš kakor hlapci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 8, 'Kdor koplje jamo, lahko pade vanjo, in kdor predira ograjo, ga piči gad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 9, 'Kdor lomi kamenje, se lahko ž njim poškoduje, in kdor kolje drva, je v nevarnosti od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 10, 'Kadar se železo skrha in ostrine kdo ne nabrusi, tedaj mora človek bolj napenjati svojo moč; ali modrost je koristna, da dosežeš uspeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 11, 'Če kača piči, preden jo zakolne, nima nič dobička zaklinjalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 12, 'Besede iz ust modrega moža so milobne, ustnice bedakove pa njega samega pogoltnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 13, 'Začetek besed ust njegovih je neumnost in konec govorjenja njegovega je zlobna blaznost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 14, 'Bedak rad govori veliko besed; toda človek ne ve, kaj bode, in kar pride za njim, kdo mu oznani?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 15, 'Trud bedaka izmozgava, ker niti ne ve, kako bi šel v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 16, 'Gorje ti, o dežela, ako je tvoj kralj otrok in tvoji knezi se gosté že zjutraj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 17, 'Srečna si, o dežela, če je tvoj kralj sin plemenitnikov in tvoji knezi jedo o pravem času v okrepčavo in ne iz požrešnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 18, 'Vsled lenobe gnije streha in po zanikarnosti kaplje v hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 19, 'Gostí se napravljajo v razveseljevanje in vino razvedruje življenje, denar pa zagotovi vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 10, 20, 'Ne preklinjaj kralja, še v svojih mislih ne, in v svoji spalnici ne kolni bogatina, kajti ptice nebeške bi odnesle glas in krilatci bi oznanil besedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 1, 'Meči kruh svoj po vodi, kajti po mnogih dneh ga najdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 2, 'Daj po kosu sedmerim, tudi osmerim; zakaj ne veš, kaka nesreča se utegne pripetiti na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 3, 'Kadar so oblaki polni dežja, se izpraznjujejo na zemljo; in ko pade drevo proti jugu ali proti severu, na kateri kraj pade, tam obleži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 4, 'Kdor pazi na veter, ne bo sejal, in kdor gleda na oblake, ne bo žel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 5, 'Kakor ne veš, po kateri poti hodi veter in kako rasto kosti v materinem telesu, tako ne veš za delo Božje, ki dela vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 6, 'Zjutraj sej seme svoje in zvečer ne daj počivati roki svoji; zakaj ne veš, katero bo raslo, ali to ali ono, in ako oboje hkratu zraste, tem bolje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 7, 'Res, sladka je svetloba in dobro de očem gledati solnce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 8, 'Zatorej če živi človek veliko let, naj se veseli v njih vseh, a pomni naj dni teme, da jih bode mnogo. Vse, kar prihaja, je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 9, 'Veseli se, o mladenič, v mladosti svoji in srce ti bodi dobre volje v dnevih mladosti tvoje, in hodi po potih, ki jih voli srce tvoje in jih gledajo oči tvoje, ali vedi, da te za to vse Bog privede na sodbo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 11, 10, 'Zato odpravi nevoljo iz srca svojega in odstrani hudo od telesa svojega; kajti mladost in jutro življenja je ničemurnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 1, 'In spominjaj se Stvarnika svojega v dnevih mladosti svoje, preden pridejo hudi dnevi in se približajo leta, o katerih porečeš: Niso mi všeč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 2, 'preden otemni solnce in svetloba in mesec in zvezde ter se oblaki povrnejo po dežju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 3, 'ob dnevi, ko bodo trepetali hišni varuhi in se močni možje skrivé in bodo mlinarji praznovali, ker jih je že malo, in se omračijo, ki skozi okna gledajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 4, 'in se duri proti ulicam zapro; ko potihne mlina klopotanje in človek vztrepeče ob glasu ptička in se zamolklo glasé vse hčere petja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 5, 'ko se tudi bojí višine in strahote vidi na poti, in ko mandljevec cvete in se kobilica težko vzdigne in jed ne diši več; kajti človek odhaja v večno domovje svoje in žalujoči pohajajo po ulicah –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 6, 'preden se utrga vrvica srebrna in se razbije zlata oljenica in se razpoči vedro pri studencu in se razdere črpalno kolo nad vodnjakom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 7, 'in prah se povrne v zemljo, kakor je bil, duh pa se vrne k Bogu, ki ga je dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 8, 'Ničemurnost ničemurna! pravi Propovednik; vse je ničemurnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 9, 'In ne samo moder je bil Propovednik, tudi ljudstvo je učil spoznanja, in globoko je premišljal in izpraševal, tudi je sestavil mnogo pregovorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 10, 'Propovednik si je prizadeval, da najde prijetnih besed; in napisano je bilo, kar je pošteno, besede resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 11, 'Besede modrih so kakor ostni in kakor globoko zabiti žeblji so zbrani izreki; in izdal jih je eden pastir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 12, 'Sicer pa, sin moj, daj se posvariti: sestavljanje mnogih knjig nima konca, in mnogo učenja utruja telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 13, 'Poslušajmo konec vse propovedi: Boga se boj in zapovedi njegove izpolnjuj, kajti to je vsa dolžnost človekova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (21, 12, 14, 'Zakaj Bog privede vsako delo, bodisi dobro ali hudo, na sodbo o vsem skritem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 1, 'Pesem pesmi, ki je Salomonova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 2, 'O da bi me poljubil z ust svojih poljubom! ker ljubezen tvoja je boljša nego vino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 3, 'Mazila tvoja sladko diše, ime tvoje je kakor izlito mazilo; zato te ljubijo device.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 4, 'Vleci me, in pohitimo za teboj! Vpeljal me je kralj v hrame svoje: radovati se hočemo in v tebi veseliti, hvaliti čemo ljubezen tvojo bolj nego vino. Iskreno te ljubijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 5, 'Črna sem, ali ljubka, o hčere jeruzalemske, kakor kedarski šatori, kakor Salomonovi zastori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 6, 'Ne glejte me, ker sem začrnela, ker me je sonce opalilo. Matere moje sinovi so se srdili z mano, postavili so me za varuhinjo v vinogradih – a vinograda, ki je moj, nisem varovala!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 7, 'Povej mi, o ti, ki ga ljubi duša moja, kje paseš čredo svojo? kje ji daješ počivati opoldne? ker čemu naj bi bila kakor tavajoča pri čredah tovarišev tvojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 8, 'Ako ne veš, o najlepša med ženami, pojdi ven, po stopinjah ovac, in pasi kozliče svoje pri prebivališčih pastirjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 9, 'Konju pri krasnem vozu Faraonovem te primerjam, o prijateljica moja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 10, 'Ljubka so lica tvoja med verižicami, vrat tvoj z nizom biserov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 11, 'Naredimo ti verižice zlate s srebrnimi kroglicami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 12, 'Dokler je kralj sedel pri omizju svojem, je vonjala narda moja vonjavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 13, 'Ljubi moj mi je kitica mire, ki leži med mojimi prsmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 14, 'Ljubi moj mi je šopek ciprovih cvetlic iz vinogradov v Engedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 15, 'Glej, lepa si, prijateljica moja, glej, lepa si, oči tvoje so kakor golobice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 16, 'Glej, lep si, ljubi moj, da, ljubezniv, tudi najino ležišče je mlado zelenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 1, 17, 'Tramovje hiše najine je cedrovo in obložci najini cipresovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 1, 'Jaz sem roža saronska, lilija v dolinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 2, 'Kakor lilija med trnjem, tako je prijateljica moja med hčerami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 3, 'Kakor jablan med drevjem v gozdu, tako je ljubi moj med sinovi. V senci njegovi sem želela sedeti in sedim, in sad njegov je sladak grlu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 4, 'Vpeljal me je v hišo, kjer se gostujejo, in zastava njegova nad menoj je ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 5, 'Okrepčajte me z grozdnimi gručami, poživite me z jabolki, ker sem bolna od ljubezni!...');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 6, 'Levica njegova je pod glavo mojo in z desnico svojo me objema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 7, 'Rotim vas, hčere jeruzalemske, pri gazelah in pri košutah poljskih, da ne prebudite in ne predramite ljubezni, dokler ji je drago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 8, 'Glas ljubega svojega čujem! glej, on prihaja, skače po gorah, poskakuje po hribih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 9, 'Ljubi moj je podoben gazeli ali mlademu jelenu. Glej, stoji za našim zidom, gleda skozi okno, zre skozi omrežje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 10, 'Izpregovoril je ljubi moj in mi veli: „Vstani, prijateljica moja, lepa moja, in pridi ven!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 11, 'Zakaj, glej, zima je minila, deževje je prešlo, konec mu je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 12, 'Cvetje se prikazuje po zemlji, čas petja je prišel, in grlice glas se sliši v deželi naši;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 13, 'smokovec rumeni zarodke smokev svojih, in vinske trte poganjajo očesca in vonjajo duh svoj. Vstani, prijateljica moja, lepa moja, in pridi ven!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 14, 'Golobica moja v razpoklinah pečevja, v skrivališču skalnih sten, daj, da vidim tvoj obraz, daj mi slišati svoj glas, ker glas tvoj je sladak in obraz tvoj miloviden.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 15, 'Polovite nam lisice, male lisice, ki kvarijo vinograde, zakaj naši vinogradi so v cvetu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 16, 'Ljubi moj je moj in jaz sem njegova; on pase čredo svojo med lilijami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 2, 17, 'Ko se ohladi dan in sence zbeže, vrni se ljubi moj, in podoben bodi gazeli ali mlademu jelenu na razpokanih gorah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 1, 'Na ležišču svojem po noči sem iskala njega, ki ga ljubi duša moja; iskala sem ga, a nisem ga našla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 2, 'Rečem: Naj vstanem in prehodim mesto, po ulicah in po trgih hočem iskati njega, ki ga ljubi duša moja. Iskala sem ga, a nisem ga našla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 3, 'Zalotili so me stražarji, ki hodijo po mestu; vprašam jih: Ste ga li videli, ki ga ljubi duša moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 4, 'Le malo sem prešla mimo njih, ko sem ga našla, ki ga ljubi duša moja. Prijela sem ga in ga nisem pustila, dokler ga nisem vpeljala v matere svoje hišo in v hram porodnice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 5, 'Rotim vas, hčere jeruzalemske, pri gazelah in pri košutah poljskih, da ne prebudite in ne predramite ljubezni, dokler ji je drago!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 6, 'Kdo je ona, ki prihaja gori iz puščave, podobna stebru dima, polna vonja mire in kadila, vsakršnega dišečega prahu trgovčevega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 7, 'Glejte tu, prenosna postelja Salomonova: šestdeset junakov okoli nje, izmed Izraelovih junakov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 8, 'Vsi znajo sukati meč, so vešči vojni; slednji ima meč ob bedru svojem zaradi strahu po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 9, 'Nosilnico krasno si je napravil kralj Salomon iz lesa libanonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 10, 'Stebre njene je naredil iz srebra, slonilo iz zlata, sedalo iz škrlata, znotraj pa je umetno vezena z ljubeznijo od hčera jeruzalemskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 3, 11, 'Pojdite ven, o hčere sionske, in glejte kralja Salomona v vencu, s katerim ga je ovenčala mati njegova v dan poroke njegove in v dan veselja njegovega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 1, 'Glej, lepa si, prijateljica moja, glej, lepa si; oči tvoje so kakor golobice za pajčolanom tvojim; lasje tvoji so kakor čreda koz, ki leže po strmini gore Gileadske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 2, 'Zobje tvoji so kakor čreda ostriženih ovčic, ki stopajo gori iz kopeli, katerih vsaka ima dvojčeti in nerodovitne ni med njimi nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 3, 'Ustne tvoje so kakor karmezinasta vrvica in usta tvoja so ljubka; kakor odrezan kos margaranovega jabolka so senca tvoja izza pajčolana tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 4, 'Vrat tvoj je kakor stolp Davidov, ki je zgrajen za orožnico, na njem visi tisoč ščitov, vsi ščiti junakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 5, 'Prsi tvoje so kakor dve srnici, dvojčeti gazelini, ki se paseta med lilijami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 6, 'Dokler se ohladi dan in sence zbeže, pojdem h gori mirovi in k hribu kadila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 7, 'Vsa si lepa, prijateljica moja, in madeža ni na tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 8, 'Z menoj doli z Libanona, nevesta moja, z menoj prideš z Libanona; z vrha Amane boš gledala doli, z vrha Senirja in Hermona, od ležišč levov, od gorá leopardov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 9, 'Obvladala si mi srce, sestra moja, nevesta, obvladala si mi srce z enim pogledom svojih oči, z eno verižico na vratu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 10, 'Kako je lepa ljubav tvoja, sestra moja, nevesta! koliko boljša je ljubav tvoja nego vino in mazil tvojih duh boljši nego vseh dišav!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 11, 'Z usten tvojih, nevesta, kaplja strd, med in mleko sta pod jezikom tvojim, in oblačil tvojih duh je kakor Libanona vonj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 12, 'Zaklenjen vrt je sestra moja, nevesta, zaklenjen vrelec, zapečaten studenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 13, 'Mladike tvoje so margaranov gaj z žlahtnim sadjem, s ciprovim cvetjem in z nardovimi rastlinami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 14, 'narda in žafran, kolmež in sladka skorjica, z vsakršnim kadilnim drevjem, mira in lopatika z vsemi najboljšimi dišavami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 15, 'Ti si studenec na vrtu, vodnjak žive vode in potoki, ki teko od Libanona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 4, 16, 'Vstani, severni veter, in pridi, jug, vej skozi moj vrt, da kapljajo njega dišave! Naj pride ljubi moj na vrt svoj in uživa sadove, njemu dragocene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 1, 'Prišel sem na vrt svoj, sestra moja, nevesta, trgal sem miro svojo in balzam svoj, jedel sem satovje svoje s svojim medom vred, pil sem vino svoje z mlekom svojim vred. Jejte, prijatelji, pijte in napijte se, ljubljeni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 2, 'Spala sem, ali moje srce je bedelo – v tem začujem glas! Ljubi moj trka: „Odpri mi, sestra moja, ljubav moja, golobica moja, popolna moja! Zakaj glava moja je polna rose, kodri moji nočnih srag.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 3, '„Slekla sem suknjo svojo, kako bi jo spet oblekla? umila sem si noge, kako bi jih zopet oblatila?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 4, 'Ljubi moj seže z roko skozi luknjo v durih, in srce mi vztrepeta zaradi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 5, 'Vstala sem, da odprem ljubemu svojemu, in z rok mi je kapljala mira in s prstov tekoča mira na držaj ključalnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 6, 'Odprla sem ljubemu svojemu; ali ljubi moj se je bil obrnil in odšel. Duša mi je ušla za njim, ko je govoril. Iskala sem ga, a nisem ga našla, klicala sem ga, a ni mi odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 7, 'Zalotili so me stražarji, ki hodijo po mestu, zbili so me, ranili so me, varuhi na zidu so mi vzeli moje ogrinjalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 8, 'Rotim vas, hčere jeruzalemske, ako najdete ljubega mojega, kaj mu povejte? Da sem bolna od ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 9, 'Kaj je tvoj ljubi mimo drugih ljubovnikov, o najlepša med ženami, kaj je tvoj ljubi mimo drugih ljubovnikov, da nas tako rotiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 10, 'Moj ljubi je bel in rdeč, odličnik med desetimi tisoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 11, 'Glava njegova je kakor najčistejše zlato, kodri njegovi so valoviti, črni kakor vran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 12, 'Oči njegove so kakor golobice ob bistrih potokih, z mlekom umite, lepo posajene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 13, 'Lica njegova so kakor grede balzama, kakor lehe dišečih rastlin; usta njegova kakor lilije, s katerih kaplja tekoča mira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 14, 'Roke njegove so kakor valjci zlati, obloženi s topazi, telo njegovo kakor umotvor iz slonove kosti, pokrit s safiri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 15, 'Goleni njegove so kakor marmornati stebri, postavljeni na podstavkih iz čistega zlata, rast njegova kakor Libanon, odličen je kakor cedre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 5, 16, 'Usta njegova so sladka in ves je ljubezniv. Tak je ljubi moj, tak je prijatelj moj, o hčere jeruzalemske!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 1, 'Kam je šel ljubi tvoj, o najlepša med ženami, kam se je obrnil ljubi tvoj? Iskati ga hočemo s teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 2, 'Ljubi moj je šel doli na vrt svoj, h gredicam balzamovim, da bi pasel po vrtih in trgal lilije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 3, 'Jaz sem ljubega svojega in ljubi moj je moj, on pase čredo svojo med lilijami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 4, 'Lepa si, prijateljica moja, kakor Tirza, milovidna kakor Jeruzalem, strašna kakor vojske z zastavami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 5, 'Obrni oči od mene, ker me premagujejo. Lasje tvoji so kakor čreda koz, ki ležé po strmini Gileadski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 6, 'Zobje tvoji so kakor čreda ovac, ki stopajo gori iz kopeli, katerih vsaka ima dvojčeti in nerodovitne ni med njimi nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 7, 'Senca tvoja so kakor odrezan kos margaranovega jabolka za pajčolanom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 8, 'Šestdeset je kraljic in osemdeset priležnic in mladenk brez števila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 9, 'A edina je golobica moja, popolna moja; edinica je materi svoji, izvoljenka porodnici svoji. Hčere so jo videle in so jo blagorovale, tudi kraljice in priležnice in so jo hvalile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 10, 'Kdo je ona, ki prisvitava kakor jutranja zarja, lepa kakor mesec, čista kakor sonce, strašna kakor vojske z zastavami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 11, 'Šel sem doli na orehov vrt, da si ogledam zelene mladike v dolini, da pogledam, če dela vinska trta popke, če cveto margaranova jabolka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 12, 'A preden sem zaznal, me je posadila duša moja na krasni voz mojega plemenitega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 6, 13, 'Vrni se, vrni se, o Šulamljanka, vrni se, vrni se, da te bomo gledali! [6:14] Kaj hočete gledati Šulamljanko? kakor ples mahanaimski...');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 1, 'Kako lepe so noge tvoje v opankah, o knežja hči! Pregibi tvojega bedra so kakor nakitne verižice, rok umetnikovih delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 2, 'Popek tvoj je kakor lepo okrogla čašica, v kateri ne manjka mešanega vina; život tvoj je kakor kup pšenice, z lilijami obtaknjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 3, 'Prsi tvoje so kakor dve srnici, dvojčeti gazelini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 4, 'Vrat tvoj je podoben stolpu iz slonove kosti, oči tvoje so kakor ribniki v Hesbonu, pri vratih ljudnatega mesta; nos tvoj kakor libanonski stolp, ki gleda proti Damasku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 5, 'Glava tvoja na tebi je podobna Karmelu, in lasje glave tvoje so kakor škrlat: kralj je v sponah kodrov tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 6, 'Kako si ti lepa in mila, o ljubav, med vsemi radostmi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 7, 'Ta rast tvoja je podobna palmovemu drevesu in prsi tvoje grozdom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 8, 'Dejal sem: Zlesti hočem na palmovo drevo in prijeti za njegove mladice; in naj mi bodo prsi tvoje kakor grozdje na vinski trti in tvojega diha vonj kakor jabolka');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 9, 'in usta tvoja kakor najboljše vino... Ki mojemu ljubemu gladko teče, ki daje govor ustom spečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 10, 'Jaz sem ljubega svojega, in poželenje njegovo je po meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 11, 'Pridi, ljubi moj, pojdiva ven na polje, prenočujva v vaseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 12, 'Zgodaj vstaneva in pojdiva k vinogradom, poglejva, če dela vinska trta popke in če se njen cvet odpira in če cveto margaranove jablani: tam ti dam ljubezni svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 7, 13, 'Ljubezenska jabolčka vonjajo svoj vonj in nad našimi durmi je vsakršnega sadja, novega in starega, ki sem ga prihranila tebi, ljubi moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 1, 'O da bi bil kakor moj brat, ki je sesal prsi matere moje! Ako bi te zalotila zunaj, bi te poljubila, in nihče bi me ne smel zaničevati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 2, 'Peljala bi te, privedla te v matere svoje hišo, ti bi me poučeval; jaz bi te napajala z dišečim vinom, s sokom svojih margaranovih jabolk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 3, 'Levica njegova je pod glavo mojo in z desnico svojo me objema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 4, 'Rotim vas, hčere jeruzalemske, da ne prebudite in ne predramite ljubezni, dokler ji je drago!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 5, 'Kdo je ta, ki prihaja sem od puščave in se naslanja na ljubega svojega? Pod jablano sem te zbudil k ljubezni. Tam je bila v bolečinah s teboj mati tvoja, tam je trpela bolečine porodnica tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 6, 'Deni me kakor pečat na srce svoje, kakor pečat na ramo svojo! Kajti ljubezen je silna kakor smrt, njena gorečnost trdna [Ali: stanovitna.] kakor grob; kakor grob; njen žar je žar ognja, plamen Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 7, 'Velike vode ne morejo ugasiti ljubezni, ne reke je poplaviti. Ako bi hotel kdo dati vse imetje hiše svoje za ljubezen, le zaničevanje bi dobil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 8, 'Sestro imamo, majhno, ki še nima prsi: kaj bomo storili s sestro svojo v dan, ko jo bodo snubili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 9, 'Ako je zid, zgradimo na njej srebrn nadzidek v utrdbo; ako je ona duri, ogradimo jo z deskami cedrovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 10, 'Jaz sem zid, in prsi moje so kakor stolpi. Tedaj sem bila v očeh njegovih kakor ona, ki je našla mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 11, 'Salomon je imel vinograd v Baal-hamonu; izročil je vinograd varuhom, da bi vsakteri prinesel za njegov sad tisoč srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 12, 'Moj vinograd, ki je meni izročen, je pred menoj; tisoč bodi tebi, o Salomon, in dvesto varuhom sadov njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 13, 'Ti, ki prebivaš na vrtih, tovariši poslušajo glas tvoj; daj mi ga slišati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (22, 8, 14, 'Híti, ljubi moj, in bodi podoben gazeli ali mlademu jelenu v gorah balzamovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 1, 'Prikazen Izaiju, sinu Amozovemu, ki jo je videl za Judo in za Jeruzalem v dneh Uzija, Jotama, Ahaza in Ezekija, kraljev Judovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 2, 'Čujte, o nebesa, in poslušaj, o zemlja, kajti Gospod je govoril: Otroke sem vzredil in povišal, oni pa so se uprli zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 3, 'Vol pozna gospodarja svojega in osel gospoda svojega jasli, ali Izrael ne pozna, ljudstvo moje ne ume.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 4, 'Gorje grešnemu narodu, ljudstvu obloženemu s krivdo, zarodu hudodelnikov, otrokom, ki popačeno ravnajo! Zapustili so Gospoda, zavrgli so Svetnika Izraelovega, odvrnili so se od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 5, 'Čemu naj bi vas še tepel, ko le bolj in bolj odpadate! Vsa glava je bolna in vse srce medlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 6, 'Od stopala do temena ni nič zdravega na njem: zgolj rane in proge in vedno novi tvori, ki jih ne iztiskajo in ne obvezujejo in ne mečé z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 7, 'Dežela vaša je pusta, mesta vaša so požgana z ognjem; zemlja vaša – tujci jo požirajo vpričo vas, in opustošena je že tako, kakor da so jo razdejali tujci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 8, 'In hči sionska je ostala zapuščena kakor koča v vinogradu, kakor hišica na kumarišču, kakor oblegano mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 9, 'Ko bi nam ne bil Gospod nad vojskami ostavil ostanka, čeprav majhnega, bi bili kakor Sodoma, bi bili podobni Gomori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 10, 'Čujte besedo Gospodovo, vodniki sodomski, poslušajte Boga našega postavo, ljudstvo gomorsko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 11, 'Čemu mi daritev vaših množina? pravi Gospod; sit sem žgalnih daritev ovnov in masti pitane živine ter krvi juncev in jagnjet in kozlov se ne veselim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 12, 'Ko prihajate, da se prikažete pred obličjem mojim – kdo je zahteval to od roke vaše, da teptate veže moje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 13, 'Ne prinašajte več daril ničevih! Kadilo mi je gnusoba; ob mlaju in v soboto in kadar sklicujete zbor, ne morem prenašati krivice in hkrati prazničnega zborovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 14, 'Mlaje vaše in praznike vaše sovraži duša moja, zoprni so mi, težko jih prenašam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 15, 'In ko iztezate roke svoje, skrivam oči svoje pred vami; ko tudi mnogo molite, ne slišim: roke vaše so polne krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 16, 'Umijte se, očistite se, odpravite hudobnost dejanj svojih izpred mojih oči, nehajte delati hudo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 17, 'učite se delati dobro, iščite pravice, tlačenemu pomagajte, pravico sodite siroti, potezajte se za vdovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 18, 'Pridite vendar, in razložimo si pravdo svojo, pravi Gospod. Ako so grehi vaši kakor škrlat, bodo beli kakor sneg; ako so rdeči kakor karmezin, bodo beli kakor volna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 19, 'Če ugodite in boste poslušali, boste uživali dobrote dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 20, 'Ako pa se boste branili in se upirali, bodete pokončani z mečem; zakaj usta Gospodova so govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 21, 'O kako se je v nečistnico izprevrglo mesto zvesto! Polno je bilo pravice, pravičnost je stanovala v njem, a sedaj morilci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 22, 'Srebro tvoje se je izpremenilo v žlindro, žlahtno vino tvoje je z vodo zmešano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 23, 'Knezi tvoji so uporniki in tovariši tatov; vsak izmed njih ljubi darila in hodi za podkupili, siroti ne sodijo pravice in vdove pravda ne prihaja do njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 24, 'Zato pravi Gospod, Jehova nad vojskami, Mogočni Izraelov: Aha, tolažbe si dobodem pri svojih nasprotnikih in maščeval se bom nad svojimi sovražniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 25, 'In iztegnem roko svojo proti tebi, da dočista izžgem žlindro tvojo in odpravim vso primes kovine tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 26, 'In zopet postavim sodnike tvoje, kakor so bili prej, in svetovalce tvoje kakor v začetku. Potem te bodo imenovali Mesto pravičnosti, zvesto mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 27, 'Sion bo odkupljen s sodbo in njegovi, ki se vrnejo, s pravičnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 28, 'Ali odpadniki in grešniki bodo vsi hkrati strti, in kateri zapuste Gospoda, poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 29, 'Zakaj osramočeni bodo spričo malikovalskih hrastov, ki ste jih želeli, in rdečica vas oblije zaradi vrtov, ki ste jih izvolili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 30, 'Kajti podobni bodete hrastu, ki mu vene listje, in podobni vrtu, ki nima nič vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 1, 31, 'In najhrabrejši bode kakor predivo in delo njegovo kakor iskra, in oboje bo gorelo skupaj, in ne bode nikogar, ki bi pogasil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 1, 'Beseda, ki jo je v prikazni slišal za Judo in Jeruzalem Izaija, sin Amozov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 2, 'In zgodi se v poslednjih dneh, da bo gora hiše Gospodove trdno postavljena na vrhu drugih gorá in povišana nad hribe, in vsi narodi se bodo stekali k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 3, 'In mnoga ljudstva pojdejo, govoreč: Pridite, da gremo na goro Gospodovo, v hišo Boga Jakobovega, da bi nas učil o potih svojih in da bomo hodili po stezah njegovih! Zakaj s Siona izide nauk in beseda Gospodova iz Jeruzalema;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 4, 'in on bo sodil med narodi in pravico izvršil mnogim ljudstvom. In pokujejo meče svoje v lemeže in sulice svoje v srpe; narod ne dvigne meča nad narod, in več se ne bodo učili bojevati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 5, 'O hiša Jakobova, pridite in hodimo v svetlobi Gospodovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 6, 'Kajti zavrgel si, Bog, ljudstvo svoje, hišo Jakobovo, ker so polni razvad z Jutrovega in so vedeži kakor Filistejci in se družijo z otroki tujcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 7, 'In njih dežela je polna srebra in zlata in njih zakladom ni konca; polna je tudi njih dežela konj in njih vozom ni konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 8, 'Polna je tudi njih dežela malikov; klanjajo se rok svojih delu, temu, kar so njih prstje storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 9, 'A pripognjen bo človek prostak in ponižan bo mož odličnjak, ker jim ne moreš prizanesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 10, 'Zlezi v pečino ter skrij se v prahu izpred groze Gospodove in izpred slave veličastva njegovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 11, 'Ponižan bo človek prevzetnih oči in visokost človeška se potlači, in povišan bo Gospod sam tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 12, 'Kajti Gospod nad vojskami ima določen dan proti vsemu, kar je prevzetno in visoko, in proti vsakemu, ki se povišuje, da se poniža;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 13, 'in proti vsem cedram na Libanonu, visokim in ponosnim, in proti vsem hrastom v Basanu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 14, 'in proti vsem visokim goram in proti vsem vzvišenim gričem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 15, 'in proti vsakemu visokemu stolpu in proti vsakemu trdnemu zidu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 16, 'in proti vsem ladjam tarsiškim in proti vsem podobam najmilejšim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 17, 'Tedaj se potlači prevzetnost človeška in vzvišenost ljudi se poniža, in povišan bo Gospod sam tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 18, 'In maliki izginejo dočista.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 19, 'In pojdejo v skalne brloge in v razpoke zemlje izpred groze Gospodove in izpred slave veličastva njegovega, kadar se vzdigne, da ostraši zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 20, 'Tisti dan vrže človek krtom in netopirjem malike svoje srebrne in zlate malike svoje, ki so mu jih naredili, da se jim poklanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 21, 'da bi zlezel v votline pečin in v skalne razpoke izpred groze Gospodove in izpred slave veličastva njegovega, ko se vzdigne, da ostraši zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 2, 22, 'Opustite up v človeka, ki mu je dihanje v nosu! kajti koliko ga je ceniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 1, 'Kajti glej, Gospod, Jehova nad vojskami, vzame iz Jeruzalema in od Jude oporo in podporo, vso podporo kruha in vso podporo vode,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 2, 'junaka in vojščaka, sodnika in proroka, vedeža in starca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 3, 'petdesetnika in veljaka, svetovalca in spretnega umetnika in izvedenca v čarovništvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 4, 'In dati jim hočem dečke za kneze, in razposajenci jim bodo gospodovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 5, 'In zatirali se bodo v ljudstvu med seboj, vsak svojega bližnjega; prešerno se bo vedel deček proti starcu in nizki proti imenitnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 6, 'Ako zgrabi brat brata v svojega očeta hiši, rekoč: Obleko imaš, vodnik nam bodi in ta razsip bodi pod tvojo roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 7, 'zažene on svoj glas tisti dan in poreče: Ne morem biti ranocelnik, zakaj še kruha ni v hiši moji, ne obleke; nikar me ne stavite za vodnika ljudstvu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 8, 'Kajti Jeruzalem je porušen in Juda je padel, ker njih jezik in njih dejanja so zoper Gospoda, da dražijo oči slave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 9, 'Pogled njih obraza priča zoper nje, in greh svoj razglašajo kakor Sodomljani, ga ne skrivajo. Gorje njih duši, ker pripravljajo hudo sami sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 10, 'Recite o pravičnem, da mu bode dobro; kajti uživali bodo dejanja svojega sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 11, 'Gorje krivičnemu! hudo mu bode, ker se mu povrne, kar so zaslužile roke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 12, 'Oni, ki tlačijo ljudstvo moje, so otroci, in ženske mu gospodujejo. O ljudstvo moje! oni, ki te vodijo, te zapeljujejo ter v zmešnjavo spravljajo stezo potov tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 13, 'Gospod je nastopil, da začne pravdo, stoji, da sodi ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 14, 'Gospod se bliža, da bo sodil ljudstva svojega starejšine in kneze njegove: Vi ste, ki ste popasli ta vinograd, rop siromakov je v hišah vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 15, 'Zakaj tarete ljudstvo moje ter razbijate siromakom obličje? govori Gospod, Jehova nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 16, 'Še pravi Gospod: Ker so hčere sionske prevzetne ter hodijo z napetim grlom in drzno migajoč z očmi in vedno stopajo z drobnimi stopinjami in rožljajo z obročki na nogah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 17, 'zato udari Gospod hčere sionske s plešo na temenu, in Gospod ogolí njih sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 18, 'Tisti dan jim pobere Gospod lepotino obročkov na nogah in načelke in lunice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 19, 'ušesne zvončke, zapestne verižice, zastore,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 20, 'oglavnice, drobilke na nogah, pasove, vonjalnice, amulete,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 21, 'prstane in nosne obročke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 22, 'praznična oblačila in plašče, ogrinjače in mošnje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 23, 'ogledala, tenčice, turbane in lahka krila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 24, 'In zgodi se, da bode namesto dišave smrad po plesnobi in namesto pasa vrv in namesto spletenih las pleša in namesto dičnega plašča raševnik, opeklina namesto lepote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 25, 'Možje tvoji padejo od meča in junaki tvoji v vojski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 3, 26, 'In vrata hčere sionske bodo žalovala in plakala, ko bo opustošena sedela na tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 1, 'In sedem žen zgrabi enega moža tisti dan, govoreč: Jed svojo bomo jedle in v obleko svojo se oblačile, samo da se imenujemo po tvojem imenu; odvzemi nam sramoto!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 2, 'Tisti dan bode Odraslek Gospodov v diko in slavo in sad zemlje v odliko in hvalo njim, ki se ohranijo Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 3, 'In zgodi se: Kdor preostane na Sionu in kdor preostane v Jeruzalemu, ga bodo svetega imenovali, vsakega, ki je za življenje zapisan v Jeruzalemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 4, 'ko bo Gospod opral nesnago hčer sionskih in kri, v Jeruzalemu prelito, poplaknil izsredi njega z duhom sodbe in z duhom pokončanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 5, 'In Gospod ustvari nad vsakim prebivališčem gore Sionske in nad zbori njenimi oblak in dim po dnevi in svit plamtečega ognja po noči; zakaj nad vso slavo bo okrilje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 4, 6, 'In koča bode za senčnico proti vročini po dnevi in za pribežališče in zavetje pred viharjem in pred dežjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 1, 'Daj, da zapojem o ljubljencu svojem, ljubega svojega pesem o vinogradu njegovem: Vinograd je imel ljubljenec moj na griču prerodovitnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 2, 'Prekopal ga je in mu potrebil kamenje in ga posadil s plemenitimi trtami; in sezidal je stolp sredi njega in tudi tlačilnico je izdolbel v njem. In je čakal, da obrodi grozdje, toda rodil je viniko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 3, 'Sedaj pa, prebivalci jeruzalemski in možje Judovi, sodite vendar med menoj in vinogradom mojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 4, 'Kaj bi se še storilo vinogradu mojemu, česar bi ne bil že storil v njem? Zakaj, ko sem čakal, da obrodi grozdje, je rodil viniko?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 5, 'Sedaj torej naj vam naznanim, kaj bom storil vinogradu svojemu: ograjo njegovo odpravim, da se bo paslo po njem, obzidje mu razvalim, da bodo teptali po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 6, 'Dam ga v opustošenje: ne bo se obrezaval ne okopaval, a grmovje požene v njem in trnje, vrhutega zapovem oblakom, naj ne izpuščajo dežja nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 7, 'Vinograd Gospoda nad vojskami je namreč hiša Izraelova in možje Judovi so rastlina radosti njegove. In ko je čakal pravoljubja, glej krvoprelitje, pravičnosti, a glej tožno vpitje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 8, 'Gorje vam, ki stikate hišo s hišo, ki devate njivo k njivi, da ni več prostora za druge, in vi sami prebivate sredi dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 9, 'Meni na ušesa je rekel Gospod nad vojskami: Res, mnoge hiše bodo opustošene, velike in lepe, da ne bode prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 10, 'Zakaj deset oral vinogradov bo dalo le eno vedro in homer semena bo dal efo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 11, 'Gorje jim, ki vstajajo rano zjutraj, da hodijo za pijačo opojno, ki sede pozno v noč, da jih vname vino!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 12, 'Pri njih pojedinah so strune in harfe, bobnice in piščal in vino; ali dela Gospodovega ne gledajo in stvaritve rok njegovih ne premišljajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 13, 'Zato pojde ljudstvo moje v sužnost, ker nima spoznanja; in imenitniki njegovi bodo stradali in množica njegova bode suha od žeje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 14, 'Zato poveča pekel pohlepnost svojo in razširi žrelo svoje brezmerno, in vanj pade Jeruzalemcev dika in njih množica s hrupom svojim in kdor se raduje med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 15, 'In pripognjen bo človek prostak in ponižan mož odličnjak in oči prevzetnih se ponižajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 16, 'A povišan bo Gospod nad vojskami po sodbi, in Bog mogočni, Sveti, se izkaže svetega v pravičnosti. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 17, 'In ovce se bodo ondi pasle kakor na pašniku svojem in tujci se bodo živili na opustošenih njivah bogatinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 18, 'Gorje jim, ki vlečejo za seboj krivico z vrvmi ničemurnosti, greh pa kakor z debelo žrdjo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 19, 'ki govore: Hiti naj, pospeši naj delo svoje, da bomo videli; in približa se naj in pride, kar je sklenil Svetnik Izraelov, da to spoznamo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 20, 'Gorje jim, ki pravijo hudemu dobro in dobremu hudo, ki imajo temo za luč in luč za temo, ki delajo grenko za sladko in sladko za grenko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 21, 'Gorje jim, ki so modri v svojih očeh in razumni sami pri sebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 22, 'Gorje jim, ki so junaki v pitju vina in vrli v mešanju pijače opojne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 23, 'ki opravičujejo krivičnega zaradi daru in pravičnim jemljejo njih pravico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 24, 'Zato kakor pokončuje strnišče ognja jezik in kakor gine suha trava od plamena, tako postane njih korenina kakor trhljad in njih cvet sprhne kakor prašek: ker so zaničevali postavo Gospoda nad vojskami in zavrgli besedo Svetnika Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 25, 'Zato se je vnel srd Gospodov zoper ljudstvo njegovo, in je iztegnil roko svojo in ga udaril tako, da so se potresle gore, in njih trupla so bila kakor smetje po ulicah. Pri vsem tem se ne odvrne jeza Njegova, še je roka Njegova iztegnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 26, 'In povzdigne zastavo narodom iz daljave in jih sikajoč pokliče k sebi od kraja zemlje, in glej, hitro, urno pridejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 27, 'Nobeden ne bo pešal in nobeden se zadeval med njimi, nobeden ne bo dremal, ne spal, tudi se ne bo razvezaval pas ledja njegovega in ne bo se trgalo jermenje obuvala njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 28, 'Njih pšice bodo preostre in vsi njih loki napeti; njih konj kopita bodo podobna skali in njih kolesa podobna vrtincu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 29, 'Njih rjovenje bo kakor levinje, rjoveli bodo kakor mladi levi; in rohneč bodo zgrabili plen in ga odnesli na varno, in nihče jim ga ne iztrga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 5, 30, 'In rohneli bodo nad Judo tisti dan, kakor ko besni morje; in če kdo pogleda na zemljo, glej, tema in stiska, in svetloba je otemnela vsled oblakov njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 1, 'V letu, ko je umrl kralj Uzija, sem videl Gospoda, sedečega na prestolu visokem in vzvišenem, in vlečke oblačila njegovega je bilo polno svetišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 2, 'Serafi so mu stali odzgoraj, vsak je imel šest peruti: z dvema si je pokrival obličje in z dvema je pokrival noge in z dvema je letal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 3, 'In klicali so drug proti drugemu, govoreč: Svet, svet, svet Gospod nad vojskami, vsa zemlja je polna slave njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 4, 'In tresle so se podstave pragov od glasu kličočih in hiša se je napolnila z dimom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 5, 'Tedaj sem rekel: Gorje mi, ker poginem, kajti mož sem z nečistimi ustnami in bivam sredi ljudstva nečistih usten; zakaj oči moje so videle Kralja, Gospoda nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 6, 'A prileti k meni tistih serafov eden, v roki držeč živ ogel, ki ga je bil s kleščami vzel z oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 7, 'In ž njim se dotakne mojih ust in reče: Glej, to se je doteknilo usten tvojih; že je odvzeta krivica tvoja in greh tvoj je očiščen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 8, 'In slišal sem glas Gospodov, ki je dejal: Koga naj pošljem? in kdo nam pojde? Tedaj rečem: Glej, jaz; pošlji me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 9, 'In veli: Pojdi in reci temu ljudstvu: Poslušajoč čujte, a ne umejte, in gledajoč vidite, a ne spoznajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 10, 'Stóri, da se odebeli temu ljudstvu srce, in zamaši mu ušesa in zatisni mu oči, da ne bi videli z očmi svojimi in ne slišali z ušesi svojimi in ne umeli s srcem svojim, da se ne izpreobrnejo ter jim ne pride zdravje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 11, 'Nato rečem: Doklej, Gospod? In odgovori: Dokler se ne opustošijo mesta, da ne bo prebivalca, in hiše, da bodo brez ljudi, in dokler ne bo dežela opustošena in zapuščena');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 12, 'in Gospod ne požene daleč ljudi ter bode veliko zapuščenih krajev v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 6, 13, 'In ako jih še desetina ostane v njej, pokonča se tudi ta; toda kakor od terebinte in od hrasta, ko se posekata, ostane korenika, tako je sveto seme njih korenika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 1, 'In zgodilo se je v dnevih Ahaza, sinu Jotama, sinu Uzija, kralja Judovega, da je šel Rezin, kralj sirski, in Pekah, sin Remalijev, kralj Izraelov, gori bojevat se zoper Jeruzalem; ali ni ga mogel vzeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 2, 'In sporočili so hiši Davidovi, rekoč: Sirija se zanaša na Efraima! In srce njegovo je trepetalo in srce njegovega ljudstva, kakor trepečejo drevesa v gozdu od vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 3, 'Tedaj veli Gospod Izaiju: Pojdi vendar Ahazu naproti, ti in sin tvoj Šear-jašub, na konec vodotoka gornjega ribnika, proti potu ob valjalčevi njivi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 4, 'in mu povej: Pazi, da bodeš miren; ne boj se in srce naj se ti ne plaši spričo teh dveh glavenj, ki se toliko kadita, spričo razvnete jeze Rezina in Sirije in Remalijevega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 5, 'Ker je osnovala Sirija hudoben naklep zoper tebe, tudi Efraim in Remalijev sin, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 6, 'Idimo gori nad Judejo, da jo spravimo v strah ter jo siloma odpremo sebi in postavimo za kralja v njej Tabeelovega sina;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 7, 'zato pravi tako Gospod Jehova: Ne zgodi se in ne bode tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 8, 'Kajti Siriji je glava Damask in Damasku glava Rezin; in še po petinšestdesetih letih bo zrušen Efraim, da ne bode več ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 9, 'In glava Efraimu je Samarija in Samariji glava sin Remalijev. Ako ne verjamete, zares, nimate obstanka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 10, 'In Gospod je še dalje govoril Ahazu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 11, 'Prosi si znamenja od Gospoda, Boga svojega, prosi ga iz globočine ali z višine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 12, 'Ahaz pa reče: Ne bom prosil, ne izkušal Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 13, 'Nato reče prorok: Čujte torej, hiša Davidova! Je li vam kaj malega nadlegovati ljudi, da celo nadlegujete Boga mojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 14, 'Zatorej vam da Gospod sam znamenje: Glej, devica bo spočela in rodila sina, in imenovala bo ime njegovo Imanuel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 15, 'Smetano in med bo jedel, ko bo vedel zametati hudo in voliti dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 16, 'Kajti še preden bo vedel ta deček zametati hudo in voliti dobro, bo zapuščena dežela, ki te je groza dveh kraljev njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 17, 'Gospod stori, da pridejo nad tebe in nad ljudstvo tvoje in nad hišo očeta tvojega dnevi, kakršnih ni bilo, odkar se je Efraim ločil od Jude: pripelje nadte kralja asirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 18, 'In zgodi se tisti dan, da Gospod požvižga muhi, ki je ob koncih potokov egiptovskih, in čebeli, ki je v deželi Asirski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 19, 'In pridejo in posedejo vse, kar jih je, po dolih med strminami in po skalnih razpokah in po vsem grmovju in po vseh pašnikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 20, 'Tisti dan obrije Gospod z najeto britvijo, ki je onkraj velereke, namreč s kraljem asirskim, lase po glavi in po nogah, celó brado pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 21, 'In v tistem času bode, da bo kdo redil le kravico in dve ovci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 22, 'a ker bo molzel obilo mleka, bo jedel smetano; kajti smetano in med bo jedel, kdorkoli preostane v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 23, 'Zgodi se tudi v tistem času, da bo vsak kraj, kjer je bilo tisoč vinskih trt vrednih tisoč srebrnikov, preraslo grmovje in trnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 24, 'S pšicami in z lokom bodo morali hoditi tja, ker bo z grmovjem in trnjem obrasla vsa dežela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 7, 25, 'Na vse gore pa, ki so jih kopali z motiko, tja ne prideš boječ se grmovja in trnja, ondi pa bode kraj, kamor bodo izpuščali vole in po katerem bo teptala drobnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 1, 'In Gospod mi je rekel: Vzemi si veliko ploščo in nanjo napiši z razločnimi črkami: Maher-šalal-haš-baz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 2, 'In vzel sem si zvesti priči: Urija, duhovnika, in Zeharija, sina Jeberekijevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 3, 'In približal sem se prorokinji, in je spočela in rodila sina. Tedaj mi je rekel Gospod: Imenuj ga Maher-šalal-haš-baz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 4, 'Zakaj preden bo deček znal klicati ‚Oče moj‘in ‚Mati moja‘, bodo nesli bogastvo iz Damaska in plen iz Samarije v Asirijo pred kraljem asirskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 5, 'In Gospod je zopet govoril k meni, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 6, 'Zato ker je to ljudstvo zaničevalo vodo v Siloahu, lahno tekočo, in mu je veselje pri Rezinu in Remalijevem sinu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 7, 'zato, glej, stori Gospod, da pridere nadnje voda velereke, presilna in preobilna, namreč kralj asirski in vsa slava njegova; in prestopi vse svoje struge in se prevali čez vse bregove svoje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 8, 'in pridere na Judovo, ga preplavi in se razlije, da mu bo do grla segalo; in razpete peruti njegove napolnijo širokost dežele tvoje, Imanuel!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 9, 'Združite se na upor, o ljudstva, a bodite potrti! In ušesa nagnite, kolikorkoli vas je po daljnih deželah! Opasujte se na boj in bodite potrti, opasujte se in bodite potrti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 10, 'Storite sklep, in uničen bo; govorite besedo, a ne obvelja; zakaj Bog je z nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 11, 'Kajti tako mi je govoril Gospod, ko me je roka njegova močno prijela in ko me je učil, da mi ni hoditi po tega ljudstva potu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 12, 'Ne imenujte zarotbe vsega, kar to ljudstvo imenuje zarotbo, in ne bojte se tega, česar se oni boje, in ne plašite se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 13, 'Gospoda nad vojskami samega posvečujte, in on vam bodi strah, on vam bodi groza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 14, 'In on vam bode v zavetno svetišče, toda za kamen spotike in skalo pohujšanja obema hišama Izraelovima, za zanko in za zadrgo prebivalcem jeruzalemskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 15, 'In mnogo izmed njih se jih spotakne in padejo in bodo strti, se zapleto v mrežo in ujamejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 16, 'Zaveži to pričevanje, zapečati postavo med mojimi učenci! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 17, 'In jaz bom čakal Gospoda, ki skriva obličje svoje pred hišo Jakobovo, in upal bom vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 18, 'Glej, jaz in otroci, ki mi jih je dal Gospod, smo za znamenja in predpodobe v Izraelu od Gospoda nad vojskami, ki prebiva na gori Sionski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 19, 'In ko vam poreko: Povprašajte rotilce mrtvih in vedeže, ki čivkajo in ki šepetajo, recite: Ali naj ne povprašuje ljudstvo Boga svojega? Za žive naj vpraša mrtve?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 20, 'Postave in pričevanja naj se oklepajo! Ako ne govore po tej besedi, ni zanje jutranje zarje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 21, 'in bode se jim klatiti po deželi hudo pobitim in gladnim, in zgodi se, ko bodo stradali, da se bodo srdili in kleli s kraljem svojim in z Bogom svojim; in če se ozro kvišku');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 8, 22, 'in če bodo gledali v tla: glej, povsod le nadloga in tema, tesnoben mrak; in bodo zagnani v gosto temo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 1, 'Toda ne ostane v temi dežela, ki je sedaj v stiski. V prejšnjem času je v zaničevanje spravil deželo Zebulonovo in deželo Neftalijevo, a v poslednjem jo pripravi v čast, ono na poti k morju, onkraj Jordana, Galilejo poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 2, 'Ljudstvo, ki je hodilo po temi, je videlo svetlobo veliko; in kateri so bivali v deželi smrtne sence, jim je zasijala luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 3, 'Pomnožil si narod, povečal si mu veselje: veselé se pred teboj kakor v veselju ob žetvi in enako njim, ki se radujejo, ko plen delé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 4, 'Zakaj ti si zlomil bremena njegovega jarem in šibo za njegova pleča, palico zatiralca njegovega, kakor ob dnevi Madiana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 5, 'Kajti vsako obuvalo tistih, ki obuti stopajo v bojnem hrupu, in vsaka okrvavljena obleka se sežge, bode za jed ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 6, 'Zakaj dete nam je rojeno, sin nam je dan, in vladarstvo pride na ramo njegovo, in ime njegovo se bo imenovalo: Čudoviti, Svetovalec, Mogočni Bog, Oče večnosti, Knez miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 7, 'Pomnoževanju njegovega vladarstva in miru ne bode konca na prestolu Davidovem in nad kraljestvom njegovim, da ga utrdi in podpre s pravico in pravičnostjo od tega časa do vekomaj. Gorečnost Gospoda nad vojskami stori to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 8, 'Besedo je poslal Gospod zoper Jakoba in je zadela Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 9, 'In vse ljudstvo jo bo spoznalo, Efraim in prebivalci v Samariji, ki govore s ponosnim in prevzetnim srcem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 10, 'Opeka je razpadla, ali zidali bomo iz rezanega kamena, posekane so divje smokve, ali nadomestimo jih s cedrami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 11, 'A Gospod povzdigne zoper njega nasprotnike Rezinove in razdraži sovražnike njegove:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 12, 'Sirce od vzhoda in Filistejce od zahoda, da požro Izraela na vsa usta. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 13, 'A to ljudstvo se ni obrnilo k njemu, ki ga tepe, in niso iskali Gospoda nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 14, 'Zato bo Gospod odsekal Izraelu glavo in rep, vejevje palmovo in bičje na en dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 15, 'Starček in imenitnik je glava, prorok pa, ki uči krivo, je rep.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 16, 'Kajti voditelji tega ljudstva so zapeljivci in ti, katere vodijo, so pogubljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 17, 'Zato se mladeničev njegovih ne bo radoval Gospod in ne bo se usmilil sirot in vdov njegovih; zakaj vsi vkup so hinavci in hudobneži in vsaka usta govore budalost. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 18, 'Kajti krivičnost se je vnela kakor ogenj, pokončava trnje in grmovje, požiga gosto drevje v gozdu, vije se navzgor v debelih oblakih dima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 19, 'Od srda Gospoda nad vojskami je zemlja požgana, tudi ljudstvo je kakor paša ognju; nihče ne prizanaša bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 20, 'Požirajo na desno, pa vendar so lačni, in jedo na levo, pa vendar niso siti. Vsak jé svoje rame meso:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 9, 21, 'Manase Efraima in Efraim Manaseja, in oba skupaj sta zoper Judo. Pri vsem tem se ne odvrne jeza Njegova, a še je roka Njegova iztegnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 1, 'Gorje jim, ki sklepajo krivične postave, in pisateljem, ki spisujejo nadlogo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 2, 'da izpodrinejo siromake iz pravde in da ugrabijo pravico ubožcem ljudstva mojega, da jim bodo vdove za plen ter da oropajo sirote!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 3, 'Kaj boste počeli ob dnevi obiskovanja in ob nevihti, ki pride iz daljave? h komu se zatečete za pomoč? in kam spravite bogastvo svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 4, 'Nič drugega vam ne bo mogoče, nego sključiti se med ujetniki in pasti med ubitimi. Pri vsem tem se ne odvrne jeza Njegova, a še je iztegnjena Njegova roka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 5, 'Gorje Asircu, ki je šiba jeze moje in palica v roki njegovi togota moja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 6, 'Nad hinavski rod ga pošljem in zoper ljudstvo, s katerim se srdim, mu dam povelje, da naj pleni plen in da naj ropa rop in naj jih potepta kakor na ulicah blato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 7, 'On seveda ne meni tako in srce njegovo ne misli tako; pogubiti mu je le namera in potrebiti narodov ne malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 8, 'Kajti govori: Niso li vsi knezi moji tudi kralji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 9, 'Ni li Kalno kakor Karkemiš? ni li Hamat kakor Arpad? ni li kakor Damask Samarija?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 10, 'Kakor je roka moja dosegla kraljestva malikov, katerih rezane podobe so bile lepše od jeruzalemskih in samarijskih –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 11, 'ali ne bom, kakor sem storil Samariji in malikom njenim, enako storil Jeruzalemu in njegovim podobam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 12, 'Zato se zgodi, ko Gospod dovrši vse delo svoje na gori Sionski in v Jeruzalemu, da bom kaznoval sad prevzetnega srca kralja asirskega in bahanje ponosnih oči njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 13, 'Kajti govoril je: Z roke svoje krepkostjo sem storil to in z modrostjo svojo, ker sem razumen; in premaknil sem ljudstvom meje in uplenil sem njih zaklade in pahnil kot mogočnjak s prestolov nje, ki so na njih sedeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 14, 'in roka moja je dosegla kakor gnezdo bogastvo ljudstev, in kakor bi pobiral jajca zapuščena, sem obral vso deželo, in ni ga bilo, da bi bil ganil s perutjo ali odprl usta ali začivkal. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 15, 'Se li more ponašati sekira proti njemu, ki seka ž njo? ali rezilo se poviševati proti njemu, ki ga rabi? kakor da bi šiba vihtela njega, ki jo dviga, kakor da bi privzdigovala palica človeka, ki ni od lesa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 16, 'Zato pošlje Gospod, Jehova nad vojskami, med debeluhe njegove sušico, in pod slavo njegovo se vname požar, podoben ognjenemu požaru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 17, 'In luč Izraelova bode za ogenj in Svetnik njegov za plamen, ki zapali in požge grmovje in trnje njegovo en dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 18, 'In pokonča slavo gozda njegovega in rodovitnih njiv njegovih z dušo in z mesom, da bode, kakor ko hira jetičnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 19, 'In majhen bode ostanek drevja v gozdu njegovem, da ga bo deček mogel zapisati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 20, 'In zgodi se tisti dan, da se ne bode ostanek Izraelov in kdor se ohrani hiši Jakobovi več opiral nanj, ki jih je tepel, marveč opiral se bo na Gospoda, Svetnika Izraelovega, v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 21, 'Ostanek se preobrne, ostanek Jakobov k mogočnemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 22, 'Kajti ko bi bilo ljudstva tvojega, Izrael, kakor peska morskega, le ostanek se preobrne iz njega. Določeno je pokončanje, ki razliva obilno pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 23, 'Zakaj pokončanje, in to določeno, dovrši Gospod, Jehova nad vojskami, sredi vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 24, 'Zatorej pravi tako Gospod, Jehova nad vojskami: Ne boj se, ljudstvo moje, ki prebivaš na Sionu, Asirca! S šibo te bo tepel in palico svojo bo vzdignil zoper tebe, kakor se je v Egiptu godilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 25, 'Kajti še malo, prav malo časa, potem bode konec srditosti in jeza moja se obrne nanje, da jih pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 26, 'In Gospod nad vojskami zavihti zoper njega bič kakor v poboju Madiancev pri skali Orebski; in palica Njegova bode nad morjem in jo vzdigne, kakor jo je vzdignil nad Egiptom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 27, 'In zgodi se v tistem času, da se razprta breme njegovo z rame tvoje in jarem njegov z vratu tvojega, da, jarem razpade spričo maziljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 28, 'Pride v Ajat, pojde skozi Migron, pri Mikmasu odloži prtljago svojo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 29, 'preidejo prelaz, veleč: v Gebi bo naše prenočišče! Rama trepeta, Gibea Savlova beži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 30, 'Glasno vpij, hči galimska! Poslušaj, o Lajsa! O ubožica Anatot!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 31, 'Madmena beži, prebivalci gebimski so se zbrali, da pobegnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 32, 'Še danes se ustavi v Nobu, že zavihti roko svojo proti gori hčere sionske, proti hribu jeruzalemskemu. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 33, 'Glej, Gospod, Jehova nad vojskami, poseka veje z grozno močjo, in tisti, ki so visoke postave, bodo posekani, in prevzetni bodo ponižani;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 10, 34, 'in posekal bo gozdno goščavo z železom svojim, in Libanon pade po Veličastnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 1, 'In mladika požene iz obsekanega debla Jesejevega, in odraslek iz korenin njegovih prinese sad;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 2, 'in duh Gospodov bo počival nad njim, duh modrosti in razumnosti, duh sveta in moči, duh spoznanja in strahu Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 3, 'In blagougodje njegovo bode v strahu Gospodovem; in ne bo sodil po videzu svojih oči, ne pravde odločeval po sluhu svojih ušes;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 4, 'temuč v pravičnosti bo sodil siromake in nepristranski bo odločeval pravdo krotkim na zemlji. In udari zemljo s šibo svojih ust in z dihom usten svojih usmrti krivičnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 5, 'In pravičnost bode ledij njegovih pas in zvestoba pas bedra njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 6, 'In prebival bo volk z jagnjetom in leopard bo ležal pri kozliču, in tele in mladi lev in pitana ovca bodo skupaj, in majhen deček vodnik med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 7, 'In krava in medvedka se bosta skupaj pasli, njuni mladiči skupaj ležali; lev pa bo jedel slamo kakor vol.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 8, 'In dete dojeno se bo igralo nad modrasovo luknjo, in odstavljenec bo ročico vtikal v gadovo votlino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 9, 'Nič zlega ne bodo storili, nič pogubnega naredili po vsej gori svetosti moje; zakaj vsa zemlja bode polna spoznanja Gospodovega, kakor vode pokrivajo morja globočino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 10, 'In zgodi se v tistem času: po korenini Davidovi, ki stoji v znamenje ljudstvom, bodo vprašali poganski narodi; in počivališče njegovo bode slavno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 11, 'In zgodi se v tistem času, da iztegne zopet, v drugič, Gospod roko svojo, da odkupi ostanek ljudstva svojega, ki preostane v Asiriji, v Egiptu, v Patrosu, v Etiopiji, v Elamu, v Sinearju, v Hamatu in na otokih morskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 12, 'In vzdigne znamenje poganskim narodom, in spravi vkup pregnance Izraelove in zbere razkropljence Judove od četverih koncev zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 13, 'Izgine tudi zavist Efraimova, in zatiralci Judovi bodo zatrti; Efraim ne bo zavidal Judi in Juda ne bo ravnal sovražno z Efraimom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 14, 'A poletita na ramo Filistejcem proti zahodu, skupaj bosta plenila sinove jutrovih dežel; na Edomce in Moabce iztegneta roko svojo, in sinovi Amonovi jima bodo pokorni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 15, 'In Gospod s prokletjem uniči zaliv Egiptovskega morja, in zavihti roko svojo z žarom diha svojega nad velereko in jo udari ter razdeli na sedem tokov in stori, da bodo mogli iti čeznjo obuti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 11, 16, 'In tako bo cesta napravljena ostanku ljudstva njegovega, kar ga preostane, iz Asirije, kakor je bila cesta Izraelu v dan, ko je šel gori iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 1, 'In tisti dan porečeš: Zahvaljujem te, o Gospod, ker si se jezil nad menoj, ali odvrnila se je jeza tvoja, in potolažil si me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 2, 'Glej, Bog mogočni je rešenje moje; upal bom in ne bode me strah, zakaj Gospod, Jehova, je moč in pesem moja, in on mi je bil v zveličanje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 3, 'In zajemali boste vodo iz studencev zveličanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 4, 'in porečete tisti dan: Hvalite Gospoda, razglašajte ime njegovo, med ljudstvi oznanjujte dejanja njegova, spominjajte, da je vzvišeno ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 5, 'Psalme pojte Gospodu, kajti prekrasno je storil; razvedi se to po vsej zemlji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 12, 6, 'Glasno vpij in radostno poj, prebivalka sionska! zakaj velik je sredi tebe Svetnik Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 1, 'Prorokovanje o Babilonu, ki ga je v prikazni prejel Izaija, sin Amozov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 2, 'Na goli gori vzdignite zastavo, zaženite glas k njim, vihtite roko, da stopijo skozi vrata prvakov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 3, 'Jaz sem ukazal posvečencem svojim, tudi sem poklical na jezo svojo junake svoje, ki se radujejo v moji veličasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 4, 'Množice glas se čuje na gorah kakor obilega ljudstva, hrup kraljestev narodov, ki so se zbrali! Gospod nad vojskami pregleduje vojno krdelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 5, 'Prihajajo iz daljne dežele, od kraja nebes – Gospod in srda njegovega orodje – pogubit vso deželo Babilonsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 6, 'Tulite, ker blizu je dan Gospodov, prihaja kot razdejanje od Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 7, 'Zatorej bodo omahovale vse roke in tajalo se bo vsako srce človeško;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 8, 'in izbegani bodo, krč in bolečine jih zgrabijo, kakor porodnica bodo imeli bolečine; vsak bo strmel ob bližnjem svojem, zaripljeno obličje bode njih obličje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 9, 'Glej, dan Gospodov prihaja, grozoviten, poln srda in goreče jeze, da izpremeni v puščavo to deželo, da iztrebi njene grešnike iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 10, 'Kajti zvezde nebes in njih ozvezdja ne bodo dajala luči svoje; mračno bode solnce ob vzhodu svojem, in mesec ne bo svetil z lučjo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 11, 'In izpokorim naseljeno zemljo za njih hudobnost in brezbožnike za njih krivico, in konec storim napuhu prevzetnih ter silovitnikov ponos ponižam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 12, 'Storim, da bode mož dražji mimo prečistega zlata in človek mimo zlata ofirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 13, 'Zato hočem potresti nebesa, in zemlja se gane s svojega mesta v togoti Gospoda nad vojskami in v dan goreče jeze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 14, 'In godilo se jim bo kakor srni splašeni in kakor čredi, ko je nihče ne zbira: obrnejo se vsak k svojemu ljudstvu in zbeže vsakteri v svojo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 15, 'Vsak, kogar najdejo, bo preboden, in vsak, kogar zasačijo, pade od meča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 16, 'In njih otročiče bodo razbijali pred njih očmi, njih hiše bodo plenili in njih žene oskrunjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 17, 'Glej, obudim zoper nje Medce, ki ne bodo čislali srebra in ne radovali se samega zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 18, 'In njih loki bodo prestreljevali mladeniče, in smilil se jim ne bo sad telesa, otrokom ne bo prizanašalo njih oko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 19, 'In Babilon, dika kraljestev, s katerim so se ponašali prevzetni Kaldejci, bode podoben Sodomi in Gomori, ki ju je Bog razdejal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 20, 'Ne bo se vekomaj v njem prebivalo, nihče se v njem ne nastani od roda do roda, tudi Arabec ne postavi tam šatora, niti pastirjem ne bodo tam počivale črede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 21, 'Ampak ležale bodo tam zverine puščave, in njih hiše bodo polne sov, in bivali bodo tam noji ter pošasti bodo tam skakale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 13, 22, 'In volkovi bodo tulili po njih opustošenih palačah in šakali po njih zabavnih gradovih. Skoraj pa pride čas njegov, in dnevi njegovi se ne podaljšajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 1, 'Zakaj Gospod se usmili Jakoba in še enkrat izvoli Izraela, in jih postavi na domača tla; in tujci se jim pridružijo ter se bodo oklepali hiše Jakobove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 2, 'In ljudstva jih vzemo pod svojo skrb ter jih pripeljejo na njih mesto; in hiša Izraelova si jih prisvoji v deželi Gospodovi, da bodo hlapci in dekle; tako bodo ujete peljali nje, katerim so bili prej ujetniki, in bodo gospodovali njim, ki so jih nekdaj tlačili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 3, 'In zgodi se tisti dan, ko ti Gospod podeli pokoj po trudu tvojem in po nepokoju tvojem in po trdi službi, v katero so te usužnjili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 4, 'da boš pravil to zabavljico o kralju babilonskem, ter porečeš: Kako je preminil tlačilec, kako je minilo oderuštvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 5, 'Zlomil je Gospod palico krivičnikov, žezlo gospodovalčevo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 6, 'ki je tepel ljudstva v togoti z udarci neprenehoma, ki je gospodoval v jezi narodom z zatiranjem brez zadržka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 7, 'Pokojna, mirna je zdaj vsa zemlja; nastalo je glasno petje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 8, 'Tudi ciprese se radujejo nad teboj, cedre na Libanonu: „Odkar si se zvrnil, ne hodi nihče sem gori, da bi nas posekal!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 9, 'Pekel zdolaj se je vznemiril zaradi tebe, ker čaka prihoda tvojega: drami zavoljo tebe mrtve, vse mogotce zemlje, vsem kraljem narodov veli vstati s prestolov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 10, 'Vsi izpregovore tebi in poreko: „Tudi ti si brez moči kakor mi, nam si postal podoben?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 11, 'V pekel je stopilo veličastvo tvoje in strun tvojih šum. Glist je polno pod teboj in črv te pokriva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 12, 'Kako si padel z neba, o lucifer, jutranje zarje sin! kako si posekan na tla, ki si poraze napravljal narodom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 13, 'Ti si pač govoril v srcu svojem: V nebesa se dvignem, nad zvezde Boga mogočnega povišam prestol svoj, in sedel bom na gori zborovanja, na skrajnem severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 14, 'Dvignem se nad višave, ogrnjene z oblaki, enak bodem Najvišjemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 15, 'Ali pahnjen boš v pekel, v jamo najglobočjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 16, 'Kateri te vidijo, te natanko ogledujejo in se ozirajo v te, govoreč: „Je li ta tisti mož, ki je majal zemljo, ki je pretresal kraljestva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 17, 'ki je delal iz naseljenega sveta puščavo in je podiral mesta ne njem, ki jetnikov svojih ni izpuščal domov?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 18, 'Vsi kralji narodov, kolikor jih je, so zaspali s častjo, vsak v hiši svoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 19, 'tebe pa so vrgli daleč od tvojega groba kakor ostuden izrastek. Pokrit si z ubitimi, s prebodenimi z mečem, ki so jih vrgli v jamo in zasuli s kamenjem, si kakor razteptano truplo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 20, 'Ne združiš se ž njimi v grobu, ker si ugonabljal deželo svojo, moril ljudstvo svoje. Hudobnikov seme se ne bo imenovalo vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 21, 'Pripravite se, da pokoljete sinove njegove zaradi krivice njih očetov! Da ne vstanejo ter ne podedujejo dežele in površja zemlje ne napolnijo z mesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 22, 'In vstanem zoper nje, govori Gospod nad vojskami, in iztrebim ime in ostanek Babilona, sina in vnuka, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 23, 'In naredim, da bode Babilon posestvo ježu in močvirje, in pometem ga z metlo pokončanja, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 24, 'Prisegel je Gospod nad vojskami, rekoč: Gotovo, kakor sem se namenil, tako se zgodi, in kakor sem sklenil, tako ostane:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 25, 'da zdrobim Asurja v deželi svoji in ga pogazim na gorah svojih. Tako se jim razprta jarem njegov in njegovo breme jim pade z rame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 26, 'To je tisti sklep, ki je storjen nad vso zemljo, in to je roka, ki je iztegnjena nad vsemi narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 27, 'Zakaj Gospod nad vojskami je storil sklep, in kdo naj ga uniči? in roka njegova je iztegnjena, kdo naj jo odvrne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 28, 'V letu, v katerem je umrl kralj Ahaz, je bilo to prorokovanje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 29, 'Ne raduj se, ti vsa Filisteja, ker je zlomljena šiba, ki te je tepla; kajti iz korenine kačje pride modras, in sad njegov bode ognjen leteč zmaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 30, 'In prvenci siromakov bodo pasli in ubožni počivali brez skrbi; a tvojo korenino pokončam z lakoto in ostanek tvoj pomori zmaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 31, 'Tulite, vrata, vpij, mesto, obup te zgrabi, vsa Filisteja; kajti od severa prihaja sovražnik kakor dim in presledka ni v četah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 14, 32, 'Kaj torej naj se odgovori poslancem narodovim? Da je Gospod ustanovil Sion in da ne njem dobé zavetje ubožci ljudstva njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 1, 'Prorokovanje o Moabu. Res, po noči bo razdejan Ar Moabov, uničen; da, po noči bo razdejan Kir Moabov, uničen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 2, 'Pojdejo gori v tempelj in v Dibon na višave jokat; nad Nebom in nad Medebo bo tulil Moab, na vseh glavah njegovih bode pleša, ostrižena bo vsaka brada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 3, 'Po ulicah njegovih se bodo opasovali z raševnikom, po strehah njegovih in po trgih njegovih bo vse tulilo, razlivajoč se v solzah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 4, 'In vpil bo Hesbon in Eleale, do Jahaza se bo čul njih glas; zato bodo kričali vojščaki moabski, duša jim bo trepetala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 5, 'Duša moja vpije zaradi Moaba; ubežniki njegovi bežé v Zoar kakor k triletni junici; jokaje stopajo gori po klancu Luhitskem, ker na potu proti Horonaimu vpijejo o pogubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 6, 'Kajti vode nimrimske se premenijo v puščavo; zakaj trava se je posušila, nežno zelišče vene, ni več zelenjave nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 7, 'Zato odneso ostanek svojega imetja, kolikor so še mogli spraviti, čez Vrbov potok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 8, 'Kajti tisto vpitje se razlega okoli po mejah moabskih, tja do Eglaima stokanje njegovo in do Ber-elima tuljenje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 15, 9, 'Kajti vode dimonske so polne krvi; da, jaz pripravim še več nad Dimon: leva za nje, ki beže iz Moaba, in za ostanek v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 1, 'Pošljite jagnje gospodovalcu dežele od Sele tja po puščavi do gore hčere sionske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 2, 'In zgodi se, da bodo hčere moabske ob brodih arnonskih kakor ptice tavajoče, kakor razpuščeno gnezdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 3, 'Posvetuj se, odloči se; senco svojo, Sion, naredi temno kakor noč opoldne; skrij pregnance, tavajočega ne izdaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 4, 'Bivajo naj pri tebi pregnanci moji, skrivališče bodi Moabu pred pokončevalcem! Kajti stiskalcu je določen konec, pokončevanje bo nehalo, zatiralci izginejo z zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 5, 'In prestol se utrdi po milosti, in na njem bo sedel v resnici v šatoru Davidovem on, ki bo sodil in iskal pravice in bo vrlo izvrševal pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 6, 'Slišali smo o prevzetnosti Moabovi, da je silno ošaben, o napuhu njegovem in oholosti njegovi in togoti njegovi; bahanje njegovo je ničevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 7, 'Zato bo tulil Moab nad Moabom, vsak bo tulil. Za grozdne gruče kir-haresetske boste zdihovali, zelo pobiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 8, 'Kajti njive hesbonske so zvenile, tudi trta sibemska; narodov gospodje so razbili prelepe rozge njene: segale so tja do Jazerja, vile so se po puščavi, mladike njene so se razširjale, šle čez morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 9, 'Zato jokam z jokom Jazerjevim za trto sibemsko, rosim te s solzami svojimi, o Hesbon in Eleale; kajti ob spravljanju letnih sadežev tvojih in ob trgatvi tvoji te je doletelo bojno vpitje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 10, 'In vzeto je veselje in radovanje z rodovitnega polja, in v vinogradih ne pojo, ni veselega vpitja, vina v kadi ne masti tlačilec; petju v tlačilnici sem naredil konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 11, 'Zato zveni kakor harfa osrčje moje zavoljo Moaba in moj drob zaradi Kir-heresa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 12, 'In zgodi se, ko se Moab prikaže, ko se bo trudil na mališki višavi in stopi v svetišče svoje, da bi molil, da nič ne opravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 13, 'To je beseda, ki jo je Gospod takrat govoril o Moabu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 16, 14, 'Sedaj pa govori Gospod takole: V treh letih, kakor so leta najemnikova, pride slava Moabova v nečast z vso svojo veliko množico vred; in ostanek bode jako majhen in neznaten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 1, 'Prorokovanje o Damasku. Glej, Damask neha biti mesto in bode kup razvalin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 2, 'Mesta aroerska so prazna, prepuščena čredam, ki bodo ondi ležale, in nihče jih ne bo plašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 3, 'In konec bode trdnjavi v Efraimu in kraljestvu v Damasku, tudi ostanku Sirije: ž njimi bode kakor s slavo sinov Izraelovih, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 4, 'Zgodi se pa v tistem času, da se zmanjša slava Jakobova in shujša mesa njegovega tolšča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 5, 'In bode, kakor če kdo ob žetvi prijema žitna stebla in z ramo svojo žanje klase; bode, pravim, kakor če kdo pobira klasje v dolini Refaimov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 6, 'Vendar pa ostanejo paberki v njem, kakor ko se otrese oljka in dvoje ali troje jagod obvisi v vršiču drevesa, četvero ali petero na vejah rodovitnega debla, govori Gospod, Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 7, 'V tistem času se bo oziral človek v Stvarnika svojega in oči njegove bodo gledale na Svetnika Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 8, 'In ne bo se oziral v oltarje, v delo rok svojih; tudi ne bo gledal tega, kar so storili prstje njegovi, ne Ašer, ne solnčnih stebrov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 9, 'V tistem času bodo trdna mesta njegova podobna zapuščenim podrtinam v gozdu in na vrhu gorá, ki so jih zapustili Kanaanci pred sinovi Izraelovimi, in bode pustinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 10, 'Ker si pozabil Boga zveličanja svojega in se nisi spominjal Skale moči svoje: zato si napravljaš prelepe nasade in jih obsajaš z inostranskimi trtami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 11, 'v dan, ko jih sadiš, jih precej ogradiš, in zjutraj skrbiš, da se razcvete seme tvoje – a žetev ti izgine v dan bridkosti in smrtne bolečine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 12, 'Gorje, upor ljudstev mnogobrojnih, ki šume kakor šume morja! in bučanje narodov, ki je kakor bučanje mogočnih vodá!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 13, 'Narodi buče kakor velike vode bučeče! A On se zadere nad njimi, in pobegnejo kar najdalje, in podili se bodo kakor pleva na gorah pred vetrom in kakor se prah vrtinči v nevihti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 17, 14, 'Ob času večernem, glej, smrtni strah! in preden nastane jutro, jih ni več. To je delež njih, ki nas plenijo, in usoda njih, ki naše siloma jemljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 1, 'Gorje deželi s šumečimi perutmi, ki je onkraj rek etiopskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 2, 'ki pošilja poslance po morju in v ladjah iz papirovega trstja po površju vodá: Pojdite, hitri sli, k narodu visoke postave in gladkemu, k ljudstvu strahovitemu od svojega začetka in doslej, k narodu, ki strogo zapoveduje in vse tepta, čigar deželo cepijo reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 3, 'Vsi prebivalci naseljenega sveta in stanovalci zemeljski, ko se povzdigne zastava na gorah, glejte tja, ko se zatrobi na trombo, čujte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 4, 'Kajti tako mi je rekel Gospod: Mirno hočem gledati v svojem prebivališču, bom kakor jasna vročina ob solnčnem svitu, kakor gosta rosa ob gorki žetvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 5, 'Kajti pred trgatvijo, ko je trtje odcvetlo in jagode dozorevajo, poreže trte s kosirjem in odpravi ročice, poseče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 6, 'Vsi vkup bodo prepuščeni ropnim pticam gorskim in zemeljskim zverinam, in ropne ptice prežive na njih leto, vse zveri zemeljske pa bodo zimovale na njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 18, 7, 'V tistem času prineso Gospodu nad vojskami v dar: ljudstvo visoke postave in gladko; in ljudstvo strahovito od svojega začetka in doslej, narod, ki strogo zapoveduje in vse tepta, čigar deželo cepijo reke, pride na mesto imena Gospoda nad vojskami, na goro Sionsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 1, 'Prorokovanje o Egiptu. Glej, Gospod, sedeč na hitrem oblaku, pride v Egipt; in maliki egiptovski bodo trepetali pred njegovim obličjem in Egipčanom se bo srce tajalo v životu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 2, 'In razdražim, pravi, Egipčane med seboj, da se bodo bojevali vsak zoper svojega brata in vsak zoper prijatelja svojega, mesto zoper mesto, kraljestvo zoper kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 3, 'In duh Egiptov bo opešal sredi njega, in uničim svet njegov, in popraševali bodo malike in zaklinjalce duhov in rotilce mrtvih in vedeže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 4, 'In zaklenem Egipčane v roko trdega gospoda, in neusmiljen kralj jim bo gospodoval, pravi Gospod, Jehova nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 5, 'In vode se razteko iz morja, in reka se posuši in usahne,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 6, 'in panoge reke bodo smrdele, vodotoki Spodnjega Egipta postanejo plitvi in se posuše, trstje in ločje zvene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 7, 'Trate poleg Nila, ob potokih njegovih in vsa setev ob potokih usahne, izgine in ne bode je več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 8, 'Tedaj bodo žalovali ribiči in plakali vsi, ki mečejo trnke v Nil, in kateri razgrinjajo mrežo po vodnem površju, bodo medleli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 9, 'In rdečica oblije nje, ki obdelujejo omikani lan in ki tkó bombaževino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 10, 'In stebri države bodo potrti, vsi, ki delajo za plačilo, bodo žalostni v duši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 11, 'Zgolj neumneži so knezi zoanski, kar so svetovali modri svetovalci Faraonovi, se je izkazalo abotno. Kako morete praviti Faraonu: „Modrijanov sin sem, sin kraljev starodavnih“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 12, 'Kje neki so modrijani tvoji? Naj ti vendar naznanijo in naj spoznajo, kaj je sklenil Gospod nad vojskami zoper Egipt!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 13, 'Pamet so izgubili knezi zoanski, prevarani so knezi v Nofu; zapeljali so Egipt, kateri so vogelni kameni njegovim rodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 14, 'Gospod je razlil sredi njega duha vrtoglavosti, in povzročili so, da je Egipt taval v vseh dejanjih svojih, kakor se bljujoč zaletava pijanec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 15, 'In Egipt ne bo imel nikogar, ki bi kaj prav dovršil, bodisi glava ali rep, palmova veja ali trst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 16, 'Tisti dan bodo Egipčani podobni ženskam, ker bodo v trepetu in strahu zavoljo vihteče roke Gospoda nad vojskami, ki jo bo vihtel proti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 17, 'In dežela Judova bode Egiptu v strah: kadar jo omeni kdo pri Egipčanih, se bodo tresli zavoljo sklepa Gospoda nad vojskami, ki ga je sklenil zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 18, 'Tisti dan bode v deželi Egiptovski petero mest, ki bodo govorila v jeziku kanaanskem in prisegala pri Gospodu nad vojskami; eno se bo imenovalo Ir-heres.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 19, 'Tisti dan bo imel Gospod oltar sredi dežele Egiptovske in spomenik Gospodu bo stal blizu njene meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 20, 'In to bode v znamenje in v pričevanje za Gospoda nad vojskami v deželi Egiptovski; zakaj klicali bodo h Gospodu zaradi zatiralcev, in pošlje jim rešitelja in branilca in jih otme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 21, 'In Gospod se razodene Egipčanom, in spoznajo Egipčani Gospoda tisti dan, in služili mu bodo s klalnimi in jedilnimi daritvami in obljube bodo delali Gospodu in jih izpolnjevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 22, 'Tako udari Gospod Egipt; udari ga in zopet ozdravi; in obrnejo se do Gospoda, in dá se jim izprositi ter jih ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 23, 'Tisti dan bode iz Egipta v Asirijo cesta, po kateri bodo hodili Asirci v Egipt in Egipčani v Asirijo, in Egipčani bodo služili Gospodu z Asirci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 24, 'Tisti dan bode Izrael tretji v zvezi z Egiptom in z Asirijo, blagoslov sredi zemlje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 19, 25, 'zato ker ga Gospod nad vojskami blagoslovi, govoreč: Blagoslovljeno bodi ljudstvo moje, Egipt, in rok mojih delo, Asirija, in Izrael, dediščina moja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 1, 'V letu, ko je prišel Tartan v Asdod, poslan od Sargona, kralja asirskega, in ko je oblegal Asdod in ga zmagal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 2, 'v tistem času je govoril Gospod po Izaiju, sinu Amozovem, rekoč: Pojdi in sleci si tisti raševnik z ledij in sezuj obuvalo z nog svojih. In storil je tako, hodeč slečen in bos.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 3, 'Tedaj reče Gospod: Kakor je hodil hlapec moj Izaija slečen in bos tri leta v znamenje in zgled Egiptu in Etiopiji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 4, 'tako odpelje kralj asirski usužnjene Egipčane in pregnane Etiopce, mlade in stare, slečene in bose in z nago zadnjo oplatjo, Egiptu v sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 5, 'In bodo prestrašeni in se bodo sramovali Etiopije, ki so vanjo upali, in Egipta, s katerim so se hvalili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 20, 6, 'In prebivalci tega primorja poreko tisti dan: Glejte, takšno je upanje naše, kamor smo se zatekali po pomoč, da bi bili oteti izpred kralja asirskega! In kako bi mogli ubežati mi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 1, 'Prorokovanje o morski puščavi. Kakor besné silni viharji na Jugu, tako pride poguba iz puščave, iz grozovite dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 2, 'Prikazen trda se mi poroča: „Nezvestnik ravna nezvesto in pokončevalec pokončuje. Idi gori, Elam! oblezite ga, o Medi! Vsemu zdihovanju pred njim storim konec.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 3, 'Vsled tega so ledja moja polna bolečine, muke me popadajo kakor muke porodnice; krč me vije, da ne slišim, prestrašen sem, da ne vidim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 4, 'Srce mi divje polje, groza me plaši; mrak, ki sem ga želel, mi je napravil trepetanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 5, 'Pripravljajo mizo, postavljajo stražo, jedo, pijejo... „Vstanite, o knezi, mažite ščit!“–');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 6, 'Kajti tako mi je velel Gospod: Pojdi, postavi pazuna; kar bo videl, naj naznani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 7, 'In videl je vozove, dvojne jahače, jezdece na oslih in jezdece na velblodih. In poslušal je napeto, z največjo pozornostjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 8, 'in je zavpil kakor lev: Gospod, na stražnem stolpu vedno stojim po dnevi in pazeč postajam cele noči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 9, 'in glej, v tem prihaja truma mož, dvojni jahači... In je izpregovoril, rekoč: „Padel je, padel Babilon, in vse izdolbene podobe bogov njegovih je treščil ob tla!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 10, 'O mlatev moja in žito gumna mojega! Kar sem slišal od Gospoda nad vojskami, Boga Izraelovega, sem vam oznanil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 11, 'Prorokovanje o Dumi. K meni kličejo iz Seira: Čuvaj, mine li skoraj noč? Čuvaj, mine li skoraj noč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 12, 'Čuvaj pravi: Pride jutro, pa tudi noč. Če hočete vpraševati, vprašajte; vrnite se, pridite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 13, 'Prokovanje o Arabiji. Po gozdih v Arabiji boste prenočevale, o potujoče čete Dedancev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 14, 'Prinesite žejnemu naproti vode! Prebivalci Temske pokrajine naj postrežejo s kruhom ubežniku!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 15, 'Kajti beže zaradi mečev, pred potegnjenim mečem in pred napetim lokom in pred nadlogami vojne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 16, 'Zakaj tako mi je dejal Gospod: V enem letu, kakor so leta najemnikova, propade vsa slava kedarska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 21, 17, 'In preostalo število lokostrelcev junakov in sinov kedarskih bode neznatno; kajti Jehova, Bog Izraelov, je govoril to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 1, 'Prorokovanje o dolini prikazni. Kaj ti je že, da si stopilo vse na strehe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 2, 'O ropota polno, hrumeče mesto, o grad, radosti poln! Prebodeni tvoji niso prebodeni z mečem in ne umorjeni v vojski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 3, 'Vsi voditelji tvoji so zbežali skupaj, zvezani so bili, ne da bi bil kdo lok napel zoper nje; kar se je zasačilo tvojih, so bili zvezani skupaj, dasi so hoteli daleč zbežati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 4, 'Zato pravim: Obrnite se od mene, da bridko jočem; ne trudite se, tolažeč me zaradi pokončanja hčere ljudstva mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 5, 'Kajti dan je prestrašenja in teptanja in zmešnjave od Gospoda, Jehove nad vojskami, v dolini prikazni, dan podiranja zidu in kričanja proti gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 6, 'In Elam nosi tul, pelje zasedene vozove in konjike, in Kir odkriva ščit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 7, 'In zgodi se, da bodo tvoje izbrane doline polne voz, in konjiki se razpostavijo proti vratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 8, 'In odgrnejo ogrinjalo Judovo. In oziral se boš tisti dan po orožju v gozdni hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 9, 'In ogledujoč razpoke mesta Davidovega, vidite, da jih je mnogo; in nabirate vode iz spodnjega ribnika;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 10, 'in štejete hiše jeruzalemske in podirate hiše, da utrdite zid;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 11, 'in nabirališče delate med dvema zidoma za vode starega ribnika – ali ne ozirate se v Njega, ki je to naredil, in ne gledate Njega, ki je to osnoval zdavnaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 12, 'Gospod, Jehova nad vojskami, pač kliče tisti dan na jok in plakanje in britje in opasovanje z raševino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 13, 'ali glej: pri vas radost in veselje, pobijanje goved in klanje drobnice, uživanje mesa in pitje vina: „Jejmo in pijmo, kajti jutri umremo!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 14, 'A razodel se je Gospod nad vojskami ušesom mojim: Res, ta krivica vam ne bo odpuščena, dokler ne umrete! govori Gospod, Jehova nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 15, 'Tako pravi Gospod, Jehova nad vojskami: Dej, stopi k tistemu oskrbniku, Sebnu, ki gospoduje hiši, in reci:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 16, 'Kaj hočeš ti tukaj? in koga imaš tukaj, da si tu izsekal grob sebi? izsekavaš si grob na višini, votliš v skali prebivališče sebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 17, 'Glej, Gospod te s silo stran vrže kakor močan mož in krepko te zgrabi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 18, 'in trdo te zvije v klobčič, kakor kepo te vrže v kraj prostoren; tam umreš in tam ostanejo slavni vozovi tvoji, ti sramota hiši gospodarja svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 19, 'Odslovim te iz službe tvoje, s stališča tvojega te zvrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 20, 'In zgodi se tisti dan, da pokličem hlapca svojega Eljakima, Hilkijevega sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 21, 'In oblečem ga v suknjo tvojo in ga utrdim s tvojim pasom, in tvoje gospostvo dam njemu v roke, in bode za očeta prebivalcem jeruzalemskim in hiši Judovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 22, 'In ključ hiše Davidove položim na ramo njegovo: ko on odpre, nihče ne zapre, in ko zapre, nihče ne odpre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 23, 'In zabijem ga kakor klin na trdnem mestu, in za časten prestol bode očetovi hiši svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 24, 'Nanj obesijo vso slavo očetove hiše njegove: mladike in izrastke, vsako posodico, od pitnih posod do vrčev. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 22, 25, 'Tisti dan, govori Gospod nad vojskami, se gane tisti klin, ki je bil zabit na trdnem mestu, in se zlomi in pade, breme pa, ki je na njem viselo, izgine; kajti Gospod nad vojskami je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 1, 'Prorokovanje o Tiru. Tulite, ladje tarsiške! kajti opustošen je Tir, da ni hiše nobene, nobenega vhoda več. Iz dežele Kitimske jim je prišlo naznanilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 2, 'Molčite, prebivalci otoka Tirskega! Kupci sidonski, ki se prepeljavajo po morju, so te napolnjevali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 3, 'in po velikih vodah je bila setev Sihorjeva, žetev Nilova njegov pridelek, in bil je tržišče narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 4, 'Sram te bodi, Sidon, ker morje govori, trdnjava morska pravi: Nisem imela porodnih bolečin, nisem porodila, ne vzredila mladeničev, ne odgojila devic.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 5, 'Ko pride poročilo v Egipt, bodo trepetali ob tem naznanilu iz Tira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 6, 'Pojdite na drugo stran v Tarsis; tulite, prebivalci na otoku!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 7, 'Je li to vaše veselo mesto, ki mu je postanek od starodavnih dni, ki ga noge vodijo, da se naseli v daljavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 8, 'Kdo je sklenil to zoper Tir, ki je dajal krone drugim, katerega kupci so bili knezi, katerega trgovci najbolj češčeni na zemlji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 9, 'Gospod nad vojskami je sklenil to, da oskruni vse slave napuh, da spravi v zaničevanje vse najbolj češčene na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 10, 'Razlij se po deželi svoji kakor Nil, o hči tarsiška; ni več brzde zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 11, 'Roko svojo je iztegnil Bog čez morje, potresel je kraljestva; Gospod je ukazal zoper Kanaana pogubiti trdnjave njegove');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 12, 'in je velel: Nič več se ne raduj, o devica oskrunjena, hči sidonska! Vstani, pojdi na ono stran v Kitim; tudi tam ti ne bode pokoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 13, 'Glej deželo Kaldejcev – to ljudstvo, ki ga prej ni bilo (Asur jo je določil zverem v puščavi), si gradi obležne stolpe, razdeva palače njegove, ga ruši v razvaline.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 14, 'Tulite, ladje tarsiške, ker je trdnjava vaša pokončana!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 15, 'In zgodi se v tistem času, da bo Tir pozabljen sedemdeset let, kolikor je življenja enega kralja; ko preteče sedemdeset let, se bo godilo Tiru, kakor se poje v pesmi o vlačugi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 16, '„Vzemi strune, hodi po mestu, o vlačuga pozabljena! vrlo bij na strune, pevaj pridno, da se ponovi spomin tvoj.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 17, 'Zgodi se namreč, ko preteče sedemdeset let, da obišče Gospod Tir, ki se povrne k svojemu zaslužku in bode ljubovnica vsem kraljestvom zemlje, po vsem svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 23, 18, 'A njegova kupčija in zaslužek njegov bode svet Gospodu, ne položi se v zaklad in shranjeval se ne bo; kajti njegova kupčija bode za nje, ki stanujejo pred Gospodom, da jedo dositega in se krasno oblačijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 1, 'Glej, Gospod izprazni deželo in jo pokonča; in preobrnivši ji lice, razkropi prebivalce njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 2, 'In godilo se bo kakor ljudstvu tako duhovniku, kakor hlapcu tako gospodarju njegovemu, kakor dekli tako gospodinji njeni, kakor kupcu tako prodajalcu, kakor posojevalcu tako njemu, ki naposodo jemlje, kakor dolžniku tako upniku njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 3, 'Docela bo izpraznjena dežela in vsa oplenjena, kajti Gospod je govoril to besedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 4, 'Žaluje, vene dežela; medli in hira naseljeni svet; medlé prvaki ljudstva v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 5, 'Tudi zemlja je oskrunjena pod prebivalci svojimi, ker so prestopali zakone, preobračali postavne naredbe, prelomili večno zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 6, 'Zato je prokletstvo požrlo zemljo, in pokoriti se morajo, ki prebivajo na njej; zato so pogoreli prebivalci zemlje, in malo ljudi je ostalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 7, 'Žaluje trgatev, hira trta, zdihujejo vsi, ki so bili veselega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 8, 'Konec je veselju bobnov, minil je radujočih se šum, konec je radosti strun.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 9, 'S petjem ne bodo več pili vina, grenela bo opojna pijača njim, ki jo pijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 10, 'Razdrto je mesto zmešnjave; zaprta je sleherna hiša, ni več nobenega vhoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 11, 'Jadikovanje zaradi vina je po ulicah; zatonilo je vse veselje, izginila je radost zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 12, 'Po mestu je ostalo le razdejanje, in v razvaline so razbita vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 13, 'Kajti tako se bo godilo sredi zemlje, med ljudstvi, kakor ko se otresajo oljke, kakor ob paberkovanju, ko je trgatev končana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 14, 'Ti ohranjenci bodo zagnali svoj glas, veselo bodo peli. Zaradi veličasti Gospodove se močno oglašajo tam od morja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 15, 'Zato poveličujte Gospoda v jutrovih krajih, ime Gospoda, Boga Izraelovega, na otokih morskih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 16, 'Od zadnjega kraja zemlje čujemo petje: Slava pravičnemu! – A jaz pravim: Hiram, hiram, gorje mi! Nezvestniki ravnajo nezvesto in krivičen rop ropajo roparji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 17, 'Groza in jama in zadrga ti prete, o prebivalec zemlje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 18, 'In zgodi se, da kdor zbeži, ker začuje grozo, pade v jamo; in kdor prileze iz jame, se ujame v zadrgo. Kajti zatvornice se odpro na višavi, in stresnejo se podslombe zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 19, 'Zemlja se vsepovsod podere, zemlja vsa se razpoči, zemlja se bo hudo majala;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 20, 'zemlja bo omahovala kakor pijanec, zibala se bo kakor viseča rogoznica; in hudo jo bo težila pregreha njena, in padla bo, da več ne vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 21, 'In zgodi se tisti dan, da bo Gospod kaznoval vojsko višave na višavi in pozemeljske kralje na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 22, 'In zbrani bodo, kakor zbirajo ujetnike v zaporu, in bodo vklenjeni in čez mnogo dni bodo obiskani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 24, 23, 'Tedaj se zastre mesec s sramom in solnce se bo sramovalo, zakaj Gospod nad vojskami bo kraljeval na gori Sionu in v Jeruzalemu, in pred starejšinami njegovimi bode slava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 1, 'O Gospod, ti si moj Bog; poviševal te bom, poveličeval ime tvoje; kajti storil si čuda, sklepe od starodavna, zvestobo in resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 2, 'Zakaj naredil si kup kamenja iz mesta, iz trdnega gradu razvalino, tujcev palačo si podrl, da ne bodi več mesto, na veke se ne sezida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 3, 'Zato te bo slavilo mogočno ljudstvo, mesta silovitih narodov te bodo častila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 4, 'Kajti bil si grad siromaku, grad potrebnemu, ko je bil v stiski, zavetje pred nevihto, senca pred vročino, ko je bilo srdito pihanje silovitnikov podobno nalivu, ki podira zid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 5, 'Kakor vročina na suhem kraju skrči vse, tako si ukrotil tujcev ropotanje, kakor oblakova senca uteši vročino, si zadušil zmagovalno petje silovitnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 6, 'In Gospod nad vojskami napravi vsem ljudstvom na tej gori gostovanje z mastnimi jedili, gostovanje s čistim vinom, pojedino s tolstimi pitanci, z vinom, očiščenim droži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 7, 'In na tej gori uniči tisto zagrinjalo, ki zagrinja vsa ljudstva, in tisti zastor, ki je razprostrt čez vse narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 8, 'Smrt bo požrta za vekomaj; in Gospod, Jehova, obriše solze z obličij vseh in ljudstva svojega sramoto odpravi z vse zemlje. Kajti govoril je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 9, 'In poreko tisti dan: Glej, Bog naš je ta! čakali smo ga, da nas reši; ta je Gospod, ki smo ga čakali! Poskakovali bomo in se radovali zveličanja njegovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 10, 'Zakaj na tej gori bo počivala roka Gospodova; in Moab bo poteptan na mestu svojem, kakor se tepta slama v gnojnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 11, 'In razpne roke svoje v deželi svoji, kakor jih razpenja plavač, da bi plaval; On pa poniža prevzetnost njegovo, čeprav je tako umetnih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 25, 12, 'In trdnjave tvojih trdnih, visokih zidov zvrne, podere in zruši na tla, prav v prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 1, 'Tisti dan bodo peli to pesem v deželi Judovi: Trdno mesto imamo; zveličanje nam Bog postavlja za obzidje in nasip.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 2, 'Odprite vrata, da vnide narod pravični, ki hrani vso zvestobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 3, 'Njemu, ki je stanoviten v misli, hraniš večni mir, ker upa vate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 4, 'Upajte v Gospoda vekomaj, kajti v Gospodu Jehovi je skala vekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 5, 'Zakaj on je ponižal stanujoče na visokem, ponižal je kvišku moleči grad; podrl jih je, zvrnil na tla, položil prav v prah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 6, 'Tepta jih noga, ubožcev noge, siromakov stopinje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 7, 'Pot pravičnega je ravna; naravnost ravnaš stezo pravičnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 8, 'Da, na potu sodb tvojih, o Gospod, smo te čakali; k imenu tvojemu in k spominu tvojemu je bilo hrepenenje duše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 9, 'Iz srca sem te želel po noči in z duhom svojim znotraj sebe sem zgodaj hitel k tebi: zakaj ko zadevajo sodbe tvoje zemljo, se uče pravičnosti prebivalci sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 10, 'Če se izkaže milost brezbožniku, se ne uči pravičnosti: v deželi pravičnosti ravna krivično in noče videti visokosti Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 11, 'Gospod, roka tvoja se je vzdignila, pa ne vidijo. A videli bodo gorečnost tvojo za to ljudstvo, in bodo osramočeni; da, ogenj pokonča nasprotnike tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 12, 'Za nas pa, Gospod, pripraviš mir; saj si tudi dovršil vsa dela naša za nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 13, 'Gospod, Bog naš, zapovedovali so nam drugi gospodje razen tebe; samo s teboj združeni hvalno spominjamo imena tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 14, 'Mrtvi so, ne ožive, mrliči so, ne vstanejo več: zato ker si jih obiskal in pogubil, in pokončal si ves njih spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 15, 'Pomnožil si ta narod, o Gospod, pomnožil si ta narod, poveličal si sebe; razširil si vse meje dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 16, 'Gospod, v stiski so te iskali; molili so ponižno, kadar jih je trla pokora tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 17, 'Kakor se noseča blizu poroda zvija in vpije v bolečinah svojih, tako smo bili pred obličjem tvojim, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 18, 'Noseči smo bili, zvijali smo se, a bilo je, kakor da bi rodili le sapo: rešitve nobene nismo napravili zemlji in niso se porodili prebivalci svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 19, 'Ožive mrtveci tvoji; mrtva trupla moja vstanejo. Zbudite se in veselo pojte, kateri prebivate v prahu! kajti rosa svetlobe je rosa tvoja, in zemlja izvrže mrtve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 20, 'Pojdi, ljudstvo moje, stopi v hrame svoje in zapri si duri za seboj: skrij se za malo časa, dokler ne preide jeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 26, 21, 'Zakaj, glej, Gospod prihaja iz kraja svojega, kaznovat prebivalce zemlje za njih krivico; in zemlja odkrije kri svojo in ne bo pokrivala več ubitih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 1, 'Tisti dan bo Gospod kaznoval z mečem svojim, trdim in velikim in močnim, leviatana, hitro bežečo kačo, in leviatana, kačo zvito, in ubije zmaja, ki je v morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 2, 'Tisti dan prepevajte o prekrasnem vinogradu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 3, 'Jaz, Gospod, ga stražim, vsak trenotek ga bom močil; da ga kdo ne oškodi, ga bom stražil noč in dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 4, 'Srda ni pri meni. O da bi imel trnje in grmovje pred seboj, v boju bi stopal po njem, požgal bi ga hkratu docela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 5, 'Ali pa naj se izroči v varstvo meni, sklene mir z menoj, sklene naj mir z menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 6, 'V prihodnjih dneh se ukoreni Jakob, Izrael bo cvetel in popke poganjal; in napolnijo površje vsega sveta s sadom. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 7, 'Ali ga je Bog udaril, kakor je udaril tiste, ki so ga tepli? ali pa je ubit, kakor so bili ubiti morilci njegovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 8, 'Zmerno ga je kaznoval, ko ga je poslal v pregnanstvo, odpodil ga je s silovitim dihom svojim ob dnevi vzhodnega vetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 9, 'Zato bo s tem poravnana krivica Jakobova; in to bode obilni sad, ko se odpravi greh njegov: da naredi vse oltarjevo kamenje enako zdrobljenemu apnencu in ne postavi več nobene Ašere in solnčne podobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 10, 'Kajti trdno mesto je postalo samotno, bivališče porušeno in zapuščeno kakor puščava; tam se bodo pasla teleta in tam ležala in objedala brstje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 11, 'Ko mu usahnejo veje, jih odlomijo, žene pridejo ter jih zažgo; zakaj to ljudstvo nima nikakega razuma, zato se ga ne usmili on, ki ga je ustvaril, in on, ki ga je upodobil, mu ne izkaže milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 12, 'In zgodi se tisti dan, da bo Gospod sadje otepal od toka Evfrata do potoka Egiptovskega, in vi boste zbrani vkup, drug k drugemu, o sinovi Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 27, 13, 'In tisti dan se zatrobi na veliko trobento, in pridejo oni, ki so bili blizu pogina v deželi Asirski in ki so bili pregnanci v deželi Egiptovski, in molili bodo Gospoda na sveti gori v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 1, 'Gorje kroni napuha pijancev v Efraimu in venočemu cvetju slavne dike njegove, ki biva na vrhu rodovitne doline njih, ki so ubiti od vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 2, 'Glej, krepak in močan od Gospoda pride, podoben viharju s točo, vrtincu pogubnemu; podoben povodnji močnih vodá deročih, bo podiral na tla s silo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 3, 'Krona napuha pijancev v Efraimu bo z nogami poteptana;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 4, 'in venočemu cvetju slavne dike, ki biva na vrhu rodovitne doline, se bo godilo kakor zgodnji smokvi pred poletjem: komaj jo dobi v roke, kdor jo zagleda, jo precej pogoltne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 5, 'Tisti dan bode Gospod nad vojskami za krono slave in za venec dike ostanku ljudstva svojega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 6, 'in za duha pravice njemu, ki bo vodil sodbo, in za junaško moč njim, ki potiskajo boj nazaj do vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 7, 'A tudi ti tavajo od vina in od pijače opojne blodijo: duhovnik in prorok tavata od pijače opojne, vino ju utaplja, blodita vsled pijače opojne; tavajo, ko vidijo prikazen, omahujejo, ko vrše sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 8, 'Kajti vse mize so polne izbljuvkov in nesnage, mesta čistega ni več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 9, 'Koga naj bi učil znanja? in komu naj bi podajal poročilo, da ga umeje? Odstavljenim od mleka, odtrganim od prsi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 10, 'Kajti zapoved je na zapoved, zapoved na zapoved, ukaz na ukaz, ukaz na ukaz, nekoliko tu, nekoliko tam! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 11, 'Da, po ljudstvu brbljavih usten in tujega jezika bo govoril temu ljudstvu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 12, 'on, ki jim je rekel: To je pravi pokoj, pokoja dajte trudnemu; in to je odpočitek! A niso hoteli poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 13, 'Zato jim bode beseda Gospodova „zapoved na zapoved, zapoved na zapoved, ukaz na ukaz, ukaz na ukaz, nekoliko tu, nekoliko tam“, da gredo dalje ter padejo vznak in se polomijo, se zapleto in ujamejo v mrežo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 14, 'Zato čujte besedo Gospodovo, možje posmehovalci, gospodarji tega ljudstva, ki je v Jeruzalemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 15, 'Ker pravite: Sklenili smo zavezo s smrtjo in s peklom smo storili pogodbo; ko pojde bič povodnji mimo, ne zadene nas, zakaj storili smo laž za zavetje svoje in zvijača nam je skrivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 16, 'Zatorej pravi tako Gospod Jehova: Glej, za podstavo sem jaz položil na Sionu kamen, kamen izkušen, dragocen vogelnik, za temelj najtrdnejši; kdor veruje, se ne prenagli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 17, 'In pravo sodbo storim za pravilo in pravičnost za tehtnico; in toča iztrebi zavetje laži in vode poplavijo njih skrivališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 18, 'Tedaj se ovrže zaveza vaša s smrtjo in pogodba vaša s peklom ne ostane; ko pojde bič povodnji mimo, tedaj vas pogazi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 19, 'Kadar pojde mimo, vas prestreže; kajti vsako jutro pojde mimo, po noči in po dnevi; in samo groza vas bode, ko le začujete poročilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 20, 'Kajti prekratka je postelja, da bi se iztegnil, in odeja preozka, da bi se zavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 21, 'Kajti kakor na gori Perazimski vstane Gospod, razsrdi se kakor v dolini ob Gibeonu, da opravi dejanje svoje – čudno je dejanje njegovo, in da izvrši delo svoje – neobičajno je delo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 22, 'Sedaj torej se ne posmehujte, da se ne utrdijo vezi vaše; zakaj čul sem od Gospoda, Jehove nad vojskami, da je pokončanje trdno določeno nad vso zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 23, 'Nagnite ušesa in čujte glas moj, poslušajte in čujte govor moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 24, 'Ali neprestano orje oratar za setev? brazdi li in vlači vedno zemljo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 25, 'Ni li tako? Ko je poravnal površje njeno, seje koper ali trosi kumino ali deva vanjo po vrsti pšenico in ječmen na obtaknjeno leho in pirjevico na obmejek njen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 26, 'Tako ga poučuje Bog njegov, da prav ravna, in ga uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 27, 'Kajti kopra ne mlatijo z mlatilnico, tudi po kumini ne vlačijo voznega kolesa, temuč s palico otepajo koper in s šibo kumino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 28, 'Drobi se li krušno žito? Ne, ne bo ga neprenehoma trl; ko žene kolesa voza svojega in konje svoje čeznje, ga ne razdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 28, 29, 'Tudi to prihaja od Gospoda nad vojskami, ki je čudovit v svetu, velik v razumnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 1, 'Gorje Arielu, Arielu, mestu, v katerem si je David napravil stanišče! Pridenite leto k letu, vrsté naj se zaporedoma prazniki –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 2, 'vendar pripravim v stisko Ariela in bo v njem žalovanje in javkanje. In bode mi pravi Ariel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 3, 'In napravim ostrog okoliinokoli zoper tebe in te tesno obkrožim z vojnimi stražami in naredim nasipe proti tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 4, 'Tedaj boš ponižan govoril na tleh in iz prahu bo zamolklo šumel govor tvoj, in glas tvoj bode kakor kakega duha iz zemlje, iz prahu bo šepetal govor tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 5, 'In kakor droben prah bode sovražnikov tvojih množica in kakor pleva mimo leteča silnikov množica, in zgodi se naglo, v trenotku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 6, 'Od Gospoda nad vojskami pride obiskovanje z gromom in potresom in ropotom močnim, z vrtincem in nevihto in s plamenom požrešnega ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 7, 'In kakor sanje, prikazen ponočna, bode množica vseh tistih narodov, ki se vojskujejo zoper Ariela, in izginejo vsi, ki se bojujejo zoper njega in grad njegov ter ga stiskajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 8, 'Bode, pravim, kakor ko se lačnemu sanja, in glej, jé, ko se pa prebudi, je prazna duša njegova; ali kakor ko se sanja žejnemu, in glej, pije, ko se pa zbudi, glej, truden je in duša njegova čuti poželenje: tako bode množica vseh tistih narodov, ki se vojskujejo zoper goro Sionsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 9, 'Osupnite in strmíte, zaslepite se in oslepite! Pijani so, ali ne od vina, opotekajo se, a ne od pijače opojne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 10, 'Kajti oblil vas je Gospod z duhom trdnega spanja in je zatisnil oči vaše, proroke, in pokril glave vaše, vidce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 11, 'Zato vam je vsaka prikazen podobna besedam zapečatenega pisma, katero dado branju veščemu človeku, rekoč: Beri, prosim, to! On pa reče: Ne morem, ker je zapečateno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 12, 'In dado pismo neveščemu branju, veleč: Beri, prosim, to! pa reče: Brati ne znam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 13, 'In Gospod je rekel: Zato ker se mi bliža to ljudstvo in me časti z usti in z ustnami, srce pa obrača daleč od mene, in ker je njih strah do mene le zapoved človeška, kakor so se je naučili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 14, 'glej, zato bom še dalje čudno ravnal s tem ljudstvom, čudno in čudovito; in modrost modrijanov njegovih mine in razumnost razumnikov njegovih se skrije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 15, 'Gorje jim, ki se zagrebajo globoko, da skrijejo svoje naklepe pred Gospodom, in katerih dela se vrše v temi in govore: Kdo nas vidi? in kdo nas pozna?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 16, 'O vi popačenci! Lončar naj se šteje ilovici za enakega? da bi reklo delo za mojstra svojega: Ni me naredil! in tvorina za svojega tvorilca: Nima razuma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 17, 'Ni li še malo časa, le prav malo, in izpremeni se Libanon v rodovitno njivo, in rodovitna njiva se bo štela za gozd?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 18, 'In tisti dan bodo glušci slišali besede pisma, in iz mraka in teme bodo videle slepcev oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 19, 'In krotki bodo pomnožili veselje svoje v Gospodu, in ubožni med ljudmi se bodo radovali v Svetniku Izraelovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 20, 'Kajti konec bode silovitniku in zasmehovalec izgine, in iztrebljeni bodo vsi, ki se potegujejo za krivico,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 21, 'ki obsojajo človeka zaradi besede in stavijo zanko njemu, ki med vrati pravdo prisoja, in ki brez vzroka izpodrivajo pravičnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 22, 'Zato pravi tako Gospod, ki je odrešil Abrahama, za hišo Jakobovo: Odslej ne bo več osramočen Jakob in obličje njegovo odslej ne obledi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 23, 'temuč ko bo videl, namreč otroci njegovi, rok mojih delo sredi sebe, bodo posvečevali ime moje, da, posvečevali bodo Svetnika Jakobovega in se bali Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 29, 24, 'In kateri so se v duhu motili, zadobe razsodnost, in godrnjači bodo dovzetni za nauk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 1, 'Gorje sinom upornim, pravi Gospod, ki delajo naklepe, ali ne iz mene, in narejajo pogodbe, ali ne po duhu mojem, da bi kopičili greh na greh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 2, 'ki se napotujejo doli v Egipt, a niso poprašali ust mojih, da se okrepčajo z močjo Faraonovo in si oskrbe zavetje v senci Egipta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 3, 'Zato vam bode moč Faraonova v sramoto in zavetje v senci Egipta v nečast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 4, 'Ko bodo v Zoanu knezi Judovi in pridejo poslanci njegovi v Hanes,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 5, 'vsi se bodo sramovali ljudstva, ki jim ne more koristiti, ki jim ni v pomoč, ne v korist, temuč v sramoto in zasmeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 6, 'Prorokovanje o živini na jugu. Skozi deželo stiske in nadloge, odkoder so levinja in lev, gad in ognjena kača leteča, poneso na oslovskih plečih bogastvo svoje in na grbah velblodov zaklade svoje k ljudstvu, ki jim nič ne koristi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 7, 'Kajti Egipt bo ničevo pomagal in brez uspeha. Zato ga imenujem Rahab, ki mirno sedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 8, 'Sedaj pojdi, zapiši to na desko vpričo njih in v knjigo začrkaj to, da bode za prihodnji čas, v pričevanje na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 9, 'Zakaj to je uporno ljudstvo, otroci lažnivi, otroci, ki nočejo poslušati postave Gospodove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 10, 'ki velevajo videčim: Ne vidite! in gledalcem prikazni: Ne prorokujte nam, kar je prav! govorite nam dobrikavo, vidite varljive nam prikazni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 11, 'Zapustite pot, krenite s steze, dejte, da se umakne nam izpred obličja Svetnik Izraelov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 12, 'Zatorej pravi tako Svetnik Izraelov: Ker zametate to besedo, a se zanašate na zatiranje in napačno vedenje ter se opirate nanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 13, 'zato vam bode tista krivičnost kakor razpoka v zidu, ki že hoče pasti, kakor izpah v visokem zidu, ki se nagloma, mahoma podere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 14, 'In zdrobi ga, kakor se zdrobi posoda lončarjeva, ki jo človek razbije brez usmiljenja, in od katere, ko je razbita, ni najti čepinje, da se ž njo vzame ogenj z ognjišča ali se zajme voda iz luže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 15, 'Kajti tako pravi Gospod Jehova, Svetnik Izraelov: Če se vrnete in bodete pokojni, boste rešeni, v mirovanju in upanju bode vaša moč. Ali niste hoteli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 16, 'temuč ste rekli: „Nikakor, kajti sedeč na konjih bomo bežali!“zato boste bežali; in: „Na brzih živalih bomo jezdili!“zato vas bodo preganjalci vaši prehiteli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 17, 'Tisoč vas bo bežalo pred grožnjo enega, pred grožnjo petih boste bežali vsi, dokler ne ostanete kakor kol na vrhu gore in kakor praporec na griču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 18, 'In zato bo Gospod odlašal storiti vam milost in zato se umakne v višavo, preden se vas usmili; kajti Gospod je Bog sodbe. Blagor jim vsem, ki ga čakajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 19, 'Zakaj ljudstvo bo prebivalo na Sionu, v Jeruzalemu; ne boš se nikdar več jokalo, gotovo ti stori milost na glas vpitja tvojega: kakor hitro te začuje, ti odgovori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 20, 'Dal vam bo res Gospod stiske kruh in vodo nadloge; a učitelji tvoji se ne bodo več skrivali, temuč oči tvoje bodo videle učitelje svoje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 21, 'in ušesa tvoja bodo slišala, ko krenete na desno ali na levo, besedo zadaj za teboj govorečih: To je tisti pot, hodite po njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 22, 'In oskrunili boste prevleko svojih rezanih podob iz srebra in obleko svojih ulitih podob iz zlata; in jih proč vržeš kakor skrunobo: „Poberi se!“porečeš jim vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 23, 'Tedaj bo dal dežja setvi tvoji, s katero poseješ zemljo, in kruha kot pridelek zemlje, in ta bode obilen in tečen. Črede tvoje se bodo pasle tisti dan po pašniku širokem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 24, 'in voli in osliči, ki obdelujejo zemljišče, bodo jedli osoljeno zmes, ki je prevejana z velnico in rešetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 25, 'In na vsaki visoki gori in na vsakem griču vzvišenem bodo potoki in reke vodá ob dnevi velikega klanja, ko bodo padali stolpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 26, 'In lune svetloba bode kakor solnca svetloba, solnčna svetloba pa bode sedemkrat močnejša, kakor sedmih dni svetloba, tisti dan, ko Gospod obveže poškodbo ljudstva svojega in ozdravi vsekane mu rane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 27, 'Glej, ime Gospodovo prihaja iz daljave. Jeza njegova gorí in gost dim se vzdiguje; ustne njegove so polne nevolje in jezik njegov je kakor uničujoč ogenj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 28, 'in dih njegov je kakor poplavljajoč hudournik, ki sega prav do grla, da bi presejal narode na situ ničemurnosti in dejal uzdo, v zmotnjavo vodečo, ljudstvom na čeljusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 29, 'Vi pa boste peli kakor v noči, ko se posvečuje praznik, in srčno se veselili kakor tisti, ki gredo s piščaljo, da stopijo na goro Gospodovo, k Skali Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 30, 'In Gospod stori, da se začuje glasa njegovega veličastvo, in pokaže ramo svojo iztegnjeno z ljuto togoto in s plamenom požrešnega ognja, s povodnijo in z viharjem in s kameneno točo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 31, 'Kajti po glasu Gospodovem bo potrt Asirec, ki je bil vajen tepsti s šibo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 32, 'In vsak udarec določene šibe, ki bo ž njo švigal Gospod po njem, se bo godil med glasom bobnov in strun; in mahaje z ramo proti njemu, se bo bojeval ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 30, 33, 'Zakaj pripravljen je že oddavna pogube kraj; ta je tudi kralju samemu namenjen: globokega in širokega so ga naredili, v grmadi njegovi je ognja in drv obilo; dih Gospodov jo zapali kakor s hudournikom žveplenim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 1, 'Gorje njim, ki gredo doli v Egipt po pomoč in se opirajo na konje, ki zaupajo vozém, ker jih je mnogo, in konjikom, ker je njih število veliko, a ne ozirajo se v Svetnika Izraelovega in ne iščejo Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 2, 'Ali tudi On je moder, in pošlje nesrečo in ne dopusti, da bi se premeknile besede njegove, ampak vzpne se nad hišo hudodelnikov in nad pomoč njih, ki delajo krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 3, 'Egipčan pa je človek in ne Bog mogočni, in njih konji so meso, ne pa duh; in ko iztegne Gospod roko svojo, se zgrudi pomočnik in podpiranec pade, in skupaj poginejo ti vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 4, 'Kajti tako mi pravi Gospod: Kakor lev in levič rjoveta pri plenu svojem, ko se skliče zoper nju množica pastirjev, in se ne ustrašita njih glasu in se ne vdasta zaradi njih ropotanja: tako pride doli Gospod nad vojskami vojskovat se na gori Sionski in na višavi njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 5, 'Kakor ptiči mahljajo s perutmi, tako bo Gospod nad vojskami branil Jeruzalem, branil ga bo in otel, prizanesel mu in ga oprostil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 6, 'Povrnite se k njemu, od katerega ste tako daleč zašli, sinovi Izraelovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 7, 'Kajti tisti dan zavržejo vsak svoje malike srebrne in zlate malike svoje, ki so vam jih vaše roke naredile v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 8, 'Tedaj pade Asirec pod mečem, pa ne moževim, in ugonobi ga meč, pa ne človeški; in bežal bo v strahu pred mečem, in mladeniči njegovi bodo sužnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 31, 9, 'In skala njegova izgine od groze in knezi njegovi bodo potrti spričo prapora, govori Gospod, ki ima svoj ogenj na Sionu in svojo peč v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 1, 'Glej, v pravičnosti bo kraljeval kralj in po pravici bodo kneževali knezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 2, 'In mož bode kakor zavetje pred vetrom in pribežališče pred povodnjijo, kakor potoki vodá na suhem kraju, kakor senca skale velike v žejni deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 3, 'In vidcev oči ne bodo več zalepljene in ušesa poslušalcev bodo pazljivo poslušala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 4, 'In srce nepremišljencev bo razumelo znanje in jecljajočih jezik bo hitro govoril in gladko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 5, 'In nespametneža ne bodo več nazivali plemenitnika, in zvijačnika ne bodo imenovali blagosrčneža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 6, 'Kajti nespametnež govori nespametnost in srce njegovo se peča s krivico, da počenja bogoskrunstvo in govori zapeljive zmote proti Gospodu, da napravi prazno dušo lačnemu in žejnemu umakne pijačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 7, 'Orodje zvijačnega je tudi hudobno: dela pregrešne naklepe, da pogubi ponižne z lažnivimi govori, tudi ko potrebni zagovarja pravico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 8, 'Ali plemeniti misli plemenito in stanoviten je v stvareh plemenitih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 9, 'Žene brezskrbne, vstanite, čujte glas moj, hčere prezaupne, poslušajte govor moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 10, 'V teh dneh, ko mine leto, bodete v strahu, prezaupne, kajti propade trgatev, pobiranja ne bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 11, 'Trepetajte, o brezskrbne, strah vas bodi, o prezaupljive, slecite se in bodite nage, in opašite si z raševnikom ledja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 12, 'Trkali se bodo na prsi zaradi prekrasnih njiv, zaradi trte rodovitne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 13, 'Po zemlji ljudstva mojega bo raslo trnje in bodljikovje, tudi na vseh hišah veselih v mestu radostnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 14, 'Kajti grad bode prazen, šumovito mesto bode zapuščeno, grič Ofel in stražni stolp bosta za brlog vekomaj, na veselje divjim oslom, čredam za pašnik –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 15, 'dokler se ne razlije nad nas duh z višave in se puščava izpremeni v njivo rodovitno, in rodovitna njiva se bo štela za gozd.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 16, 'In v puščavi se nastani pravica, in pravičnost bo prebivala na rodovitni njivi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 17, 'in delo pravičnosti bode mir in obrodek pravičnosti pokoj in varnost vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 18, 'In ljudstvo moje bo prebivalo v domovju miru in v varnih prebivališčih in v krajih za pokoj mirnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 19, 'A prej se bo toča usipala, ko se bo podiral gozd, in mesto bo globoko ponižano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 32, 20, 'Blagor vam, ki sejete poleg vseh vodá in puščate, da prosto hodijo noge volov in oslov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 1, 'Gorje ti, pokončevalec, ki sam nisi bil pokončan, in tebi, nezvestnik, zoper katerega niso delali nezvesto! Brž ko dovršiš pokončevanje, bodo tebe pokončali, brž ko nehaš ravnati nezvesto, se bo delalo nezvesto proti tebi. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 2, 'O Gospod, stóri nam milost! tebe čakamo: bodi svojim rama sleherno jutro in rešenje naše ob času stiske! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 3, 'Od donečega glasu tvojega beže ljudstva, če se ti vzdigneš, razkrope se narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 4, 'In pobere se vaš plen, kakor pobira kobilica; kakor skače kobilica, bodo skakali nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 5, 'Vzvišen je Gospod, kajti prebiva na višavi; napolnil je Sion s sodbo in pravičnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 6, 'In vernost bode v tvojih časih, obilost rešenja, modrosti in znanja; strah Gospodov bo zaklad Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 7, 'Glej, njih junaki vpijejo zunaj, poslanci miru jokajo bridko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 8, 'Ceste so zapuščene, popotnik več ne hodi. Prelomil je zavezo, zaničeval je mesta, zmenil se ni za človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 9, 'Žaluje, hira dežela; Libanon se sramuje in vene; Saron je kakor puščava in Basan in Karmel stresata perje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 10, 'Sedaj vstanem, reče Gospod, sedaj se vzdignem, sedaj bom povišan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 11, 'Spočenjate suho travo, rodili boste strnišče; dih vaš je ogenj, ki vas pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 12, 'In ljudstva bodo kakor žgano apno in kakor trnje porezano, ki se žge v ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 13, 'Čujte, ki ste daljni, kaj sem storil, in kateri ste bližnji, spoznajte mogočnost mojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 14, 'Preplašeni so grešniki na Sionu, trepet se je polastil hinavcev: Kdo izmed nas more bivati s požrešnim ognjem? kdo izmed nas more bivati z večno žerjavico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 15, 'Kdor hodi pravično in govori pošteno, kdor zaničuje dobiček po zvijači, kdor stresa roke svoje, da ne prejme podkupila, kdor si maši uho, da ne sliši naklepov o prelitju krvi, in zatiska oči, da ne vidi zlega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 16, 'ta bo prebival v krajih previsokih, skalni branik bode grad njegov, kruh njegov se mu bo dajal, vode mu ne bodo usehnile. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 17, 'Kralja v lepoti njegovi bodo videle tvoje oči, gledale bodo deželo daleč razprostranjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 18, 'Srce tvoje bo preudarjalo strahoto: Kje je cenilec davkov? kje pretehtovalec? kje stolpov nadzornik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 19, 'Ljudstva drznega ne boš videl, ljudstva s preglobokim govorom, da bi ga umel, tuje govorice, ki je ni razumeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 20, 'Poglej Sion, mesto slavnostnih zborov naših! Oči tvoje bodo videle Jeruzalem, mirno prebivališče, šator, ki se ne bo prenašal več, ki se mu nikoli noben klin ne izruje in nobena vrv nikdar ne potrga –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 21, 'marveč tam bode Gospod z nami, Veličastni, – kraj širokih rek in potokov, kamor ne pride ladja z vesli in velik brod ne bo plul skozi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 22, 'Zakaj Gospod je naš sodnik, Gospod postavodajec naš, Gospod kralj naš, on nas bo rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 23, 'Rahlo visé vrvi tvoje, ne drže postavljenega jadrnika, ne morejo razpeti jader. Tedaj se razdeli plen velikega ropa, še hromi bodo grabili plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 33, 24, 'In noben prebivalec ne poreče: Bolan sem! Ljudstvu, ki v njem prebiva, bo odpuščena krivica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 1, 'Pristopite, narodi, da poslušate, in ljudstva, čujte! Sliši naj zemlja in kar jo napolnjuje, naseljeni svet in vse, kar se rodeva na njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 2, 'Zakaj goreča je jeza Gospodova zoper vse narode in srditost zoper vso njih vojsko; proklel jih je v pokončanje, izročil jih je v klanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 3, 'In njih prebodenci bodo tja pometani, in od njih mrličev bo prihajal smrad, in gore se bodo topile v njih krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 4, 'In izgine vsa vojska nebeška, in nebo se zvije kakor knjiga, in vsa njegova vojska odpade, kakor odpade listje s trte in kakor odpade list s smokve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 5, 'Kajti upijanil se je moj meč v nebesih; glej, nad Edomce pride doli v sodbo in nad ljudstvo, ki sem ga odmenil v prokletje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 6, 'Meč Gospodov je poln krvi, masten od tolšče, od krvi jagnjet in kozlov, od tolšče ovnovih ledij: kajti žrtvovanje je Gospodu v Bozri in veliko klanje v deželi Edomcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 7, 'Padejo tudi divji bivoli ž njimi in junci s krepkimi biki, tako da se zemlja upijani njih krvi in prah bo napojen ž njih mastjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 8, 'Kajti dan Gospodovega maščevanja je leto povračila, da se reši pravda Sionova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 9, 'In potoki Edomovi se premene v smolo in prah njegov v žveplo, in zemlja njegova bo kakor goreča smola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 10, 'Po dnevi in po noči ne ugasne, vekomaj bo vzhajal dim njen; od roda do roda ostane pusta, vekomaj nihče ne pojde skozi njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 11, 'Ali podedovala jo bosta pelikan in jež ter sova in vran bosta prebivala v njej. In potegne čez njo mersko vrvico pustote in svinčnico praznote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 12, 'Plemenitnikov njenih ne bode nobenega, da bi oklical kraljestvo, in vsi knezi njeni bodo v nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 13, 'In v gradovih njenih požene trnje, kopriva in osat po trdnjavah njenih, in bode v brlog šakalom, za pašo mladim nojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 14, 'In stekale se bodo zveri puščave z divjimi psi in kosmatin bo klical druga svojega; ponočni škrat bo bival ondi in našel si pokoja mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 15, 'Tam si napravi kača gnezdo in bo legla jajca, in ko se izvalé mladiči, jih bo zbirala v senco svojo; ondi se bodo zbirali jastrebi, vsak z družetom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 16, 'Preiskujte knjigo Gospodovo in čitajte! Enega od teh ne bo manjkalo, eden ne bo pogrešal drugega, kajti usta Njegova so zapovedala in duh Njegov jih je zbral vkup;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 34, 17, 'in On je vrgel kocko zanje in jim je z roko svojo razdelil to zemljo po merski vrvi: v lasti jo bodo imeli vekomaj, od roda do roda bodo prebivali v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 1, 'Veselila se bosta puščava in samotni kraj, in radovala se bo pustinja in cvela kakor roža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 2, 'Prekrasno bo cvela in se radovala v samem radovanju in petju; slava libanonska ji bo dana, lepota Karmela in Sarona. Gledali bodo slavo Gospodovo, lepoto Boga našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 3, 'Pokrepčajte onemogle roke in šibeča se kolena utrdite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 4, 'Recite njim, ki so plašljivega srca: Srčni bodite, ne bojte se! Glejte, Bog vaš se bliža, maščevanje prihaja, povračilo Božje; on sam pride rešit vas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 5, 'Tedaj izpregledajo oči slepim in gluhim se odpro ušesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 6, 'Tedaj bo hromec skakal kakor jelen in nemega jezik bo prepeval; zakaj privrele so v puščavi vode in potoki v samoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 7, 'Peščeno zrcaljenje se je izpremenilo v jezero in žejna tla v vrelce vodá; v brlogu šakalov, kjer leže, bode trava s trstjem in bičjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 8, 'In bode tam cesta in pot, ki se bo imenovala Pot svetosti, po kateri ne bo hodil oskrunjeni, temuč bode zanje same; kdor hodi po tej poti, tudi nespametni, ne more zaiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 9, 'Tam ne bode leva in nobena zver silovita ne pride nanjo in je ne bode najti tam; a odrešenci pojdejo po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 35, 10, 'In odrešenci Gospodovi se povrnejo ter pridejo na Sion s petjem, in večno veselje bode nad njih glavo; veselje in radost jih objame, a žalovanje in zdihovanje pobegne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 1, 'In zgodilo se je v štirinajstem letu kralja Ezekija, da je šel Senaherib, kralj asirski, gori zoper vsa utrjena mesta Judova in se jih polastil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 2, 'Pošlje pa kralj asirski Rabsaka iz Lahisa v Jeruzalem proti kralju Ezekiju z mnogoštevilno vojsko. Ta se ustavi pri vodovodu gornjega ribnika ob poti valjalčeve njive.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 3, 'Tedaj pride ven k njemu Eljakim, sin Hilkijev, ki je bil nad dvorcem, in pisar Sebna in Joah, sin Asafov, letopisec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 4, 'Njim reče Rabsak: Povejte vendar Ezekiju: Tako pravi kralj veliki, kralj asirski: Kakšno upanje je to, na katero se zanašaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 5, 'Pravim ti: Tvoj svet in moč za vojskovanje je le prazna beseda. Na koga se torej zanašaš, da si se mi uprl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 6, 'Glej, zanašaš se na palico iz zlomljenega trsta, na Egipt; katera se mu, ko se kdo nasloni nanjo, zadere v dlan in jo prebode. Tako je Faraon, kralj egiptovski, vsem, ki stavijo upanje vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 7, 'Ako mi pa porečeš: V Gospoda, Boga svojega, upamo! ali ni on tisti, čigar višave in oltarje je odpravil Ezekija in je velel Judi in Jeruzalemu: Pred tem oltarjem molite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 8, 'A sedaj, naredi vendar stavo z gospodom mojim, kraljem asirskim, in dam ti dvakrat tisoč konj, ako boš imel jezdecev, da jih posadiš nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 9, 'Kako bi torej mogel zapoditi le enega voditelja najmanjših hlapcev gospoda mojega? Ali ti se zanašaš na Egipt zaradi voz in konjikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 10, 'Sem li mar sedaj brez Gospoda prišel gori zoper to deželo, da jo pogubim? Gospod mi je velel: Idi gori v tisto deželo ter pogubi jo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 11, 'Tedaj reko Eljakim in Sebna in Joah Rabsaku: Govóri, prosim, hlapcem svojim po sirsko, saj razumemo, in ne govori nam po judovsko, ker sliši ljudstvo, ki je na zidovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 12, 'Ali Rabsak reče: Me je li h gospodu tvojemu in k tebi poslal gospod moj, da naj govorim besede te? Ali ne k onim možem, ki sede po zidovju, da jedo blato svoje in pijo vodo svojo z vami vred?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 13, 'Rabsak torej se ustopi in zavpije z glasom velikim po judovsko in reče: Čujte besede velikega kralja, kralja asirskega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 14, 'Tako pravi kralj: Naj vas ne prekani Ezekija, kajti ne bo vas mogel oteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 15, 'In ne pregovóri vas Ezekija, da bi upali v Gospoda, govoreč: Gotovo nas otme Gospod; to mesto ne bo dano kralju asirskemu v roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 16, 'Ne poslušajte Ezekija! Kajti tako pravi kralj asirski: Pogodite se z menoj za mir in pridite k meni ter jejte vsak svoje trte sad in vsak svoje smokve sad in pijte vsak svojega vodnjaka vodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 17, 'dokler ne pridem ter vas vzamem v deželo, podobno vaši deželi, v deželo, kjer je obilo žita in vina, kruha in vinogradov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 18, 'Ne zapelji vas Ezekija, govoreč: Gospod nas otme. Ali so bogovi narodov oteli vsak svojo deželo iz roke kralja asirskega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 19, 'Kje so bogovi Hamata in Arpada, kje bogovi Sefarvaima? Ali so neki oteli Samarijo iz moje roke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 20, 'Kateri so med vsemi bogovi tistih dežel, ki so deželo svojo oteli iz roke moje, da bi Gospod otel Jeruzalem iz roke moje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 21, 'A oni so molčali in mu niso odgovorili besede, zakaj kraljev ukaz je velel: Ne odgovarjajte mu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 36, 22, 'Pride torej Eljakim, Hilkijev sin, ki je bil nad dvorcem, in Sebna pisar in Joah, Asafov sin, letopisec, k Ezekiju z raztrgano obleko in mu naznanijo besede Rabsakove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 1, 'In ko je to slišal kralj Ezekija, si raztrga oblačila in se ogrne z raševino in stopi v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 2, 'In pošlje Eljakima, ki je bil nad dvorcem, in Sebna pisarja ter starejšine duhovnikov, odete z raševino, k proroku Izaiju, sinu Amozovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 3, 'In ti mu reko: Tako pravi Ezekija: Dan stiske in strahovanja in zasramovanja je ta dan, kajti otroci so blizu do poroda, a moči ni za porod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 4, 'Morda bo slišal Gospod, Bog tvoj, besede Rabsakove, ki ga je poslal kralj asirski, gospod njegov, sramotit Boga živega, in bo kaznoval besede, ki jih je slišal Gospod, Bog tvoj. Zato povzdigni prošnjo za ostanke, kar jih še je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 5, 'Ko so torej prišli hlapci Ezekija kralja k Izaiju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 6, 'jim reče Izaija: Tako povejte gospodu svojemu: Tako pravi Gospod: Ne boj se spričo tistih besed, ki si jih slišal, s katerimi so me preklinjali hlapci kralja asirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 7, 'Glej, jaz mu vdahnem duha, da začuje glas in se vrne v deželo svojo, in storim, da pade od meča v deželi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 8, 'In Rabsak se vrne in najde kralja asirskega, vojskujočega se z Libno; slišal je bil namreč, da je odpotoval od Lahisa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 9, 'V tem zasliši, da govorijo o Tirhaku, kralju v Etiopiji: Gre se vojskovat zoper tebe. Ko je to slišal, pošlje poslance k Ezekiju z ukazom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 10, 'Tako govorite Ezekiju, kralju Judovemu, in recite: Naj te ne vara Bog tvoj, ki nanj staviš upanje, govoreč: Jeruzalem ne bo dan kralju asirskemu v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 11, 'Glej, sam si slišal, kar so storili kralji asirski vsem drugim deželam, pokončavši jih docela, in ti bi se otel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 12, 'So li mar oteli bogovi narodov tiste, ki so jih pogubili očetje moji, Gozana in Harana in Rezefa in sinove Edena, ki so bili v Telasarju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 13, 'Kje je kralj hamatski in kralj arpadski in kralj mesta Sefarvaima, Hene in Ive?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 14, 'In ko Ezekija prejme pismo iz roke poslancev in ga prebere, gre gori v hišo Gospodovo in ga razgrne pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 15, 'In molil je Ezekija h Gospodu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 16, 'Gospod nad vojskami, Bog Izraelov, ki stoluješ nad kerubi, ti si Bog, ti edini, vsem kraljestvom na zemlji, ti si ustvaril nebesa in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 17, 'Nagni, o Gospod, uho svoje in poslušaj, odpri, Gospod, oči svoje in glej, in poslušaj vse besede Senaheriba, ki je poslal sramotit živega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 18, 'Res je, Gospod, opustošili so kralji asirski vse one narode in njih deželo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 19, 'in vrgli so njih bogove v ogenj, ker niso bili bogovi, ampak rok človeških delo, les in kamen; zato so jih pogubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 20, 'Sedaj torej, Gospod, Bog naš, reši nas iz roke njegove, da bi spoznala vsa kraljestva na zemlji, da si ti Gospod, ti edini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 21, 'Tedaj pošlje Izaija, sin Amozov, k Ezekiju, da mu reko: Tako pravi Gospod, Bog Izraelov: Ker si me prosil spričo Senaheriba, kralja asirskega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 22, 'to je beseda, ki jo je govoril Gospod za njega: Zaničuje te, zasmehuje te devica, hči sionska, za teboj maje glavo hči jeruzalemska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 23, 'Koga si sramotil in preklinjal? in zoper koga si zagnal svoj glas in ošabno povzdignil oči svoje? Zoper Svetnika Izraelovega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 24, 'Po hlapcih svojih si sramotil Gospoda, ko si govoril: Z množico voz svojih sem prišel na vrh gorá, do najvišje strani Libanona; in posekam na njem visoke cedre in izbrane ciprese njegove, stopim tudi na največjo višino njegovo, v gaj na vrtu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 25, 'Jaz sem kopal vodnjake in izpil vode, in s stopalom nog svojih hočem posušiti vse reke v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 26, 'A nisi li slišal, da sem jaz to delal od zdavnaj in snoval od starih časov? Sedaj sem storil, da je prišlo to, da rušiš utrjena mesta v kupe razvalin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 27, 'Zato so bili njih prebivalci slabotnih rok, prestrašeni in izbegani; bili so kakor trava na njivi in kakor mehka zelenjava, kakor seno po strehah in žito posmojeno, preden gre v latje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 28, 'In sejo tvojo in odhod in prihod tvoj poznam, tudi divjanje tvoje zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 29, 'Ker divjanje tvoje zoper mene in lahkoživstvo tvoje je prišlo do ušes mojih, zato denem obroček svoj v tvoj nos in uzdo svojo med ustnice tvoje, in povedem te nazaj po tistem potu, po katerem si prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 30, 'In to ti bodi znamenje: letos boste jedli, kar samo zraste, drugo leto pa, kar po tem priraste, v tretjem letu pa sejte in ženjite in sadite vinograde ter jejte njih sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 31, 'In ohranjenci hiše Judove, kar jih preostane, bodo poganjali zopet korenine spodaj in rodili sad zgoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 32, 'Zakaj iz Jeruzalema izide ostanek in s Sionske gore tisti, ki se bodo ohranili; gorečnost Gospoda nad vojskami stori to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 33, 'Zatorej pravi tako Gospod za kralja asirskega: Ne pride v to mesto in pšic ne sproži sem, tudi ščita mu ne postavi nasproti in nasipov ne napravi zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 34, 'Po istem potu, po katerem je prišel, se vrne, v to mesto pa ne pride, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 35, 'Kajti branil bom to mesto, da ga rešim, zaradi sebe in zaradi Davida, svojega hlapca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 36, 'In šel je angel Gospodov ter jih pobil v asirskem ostrogu sto in petinosemdeset tisoč. In ko so vstali zjutraj, glej, bili so vsi tisti trupla mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 37, 'Zato se vzdigne Senaherib, kralj asirski, in odide in se vrne ter ostane v Ninivah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 37, 38, 'In zgodilo se je, ko se je klanjal v hiši Nisroka, boga svojega, da ga Adramelek in Sarezer, sinova njegova, udarita z mečem in pobegneta v deželo Araratsko. In kraljeval je sin njegov Esar-hadon namesto njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 1, 'V tistih dneh zboli Ezekija na smrt. In pride k njemu Izaija, sin Amozov, prorok, ter mu reče: Tako pravi Gospod: Uredi hišo svojo, kajti v kratkem umreš in ne boš živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 2, 'Tedaj obrne Ezekija obličje svoje v steno in moli h Gospodu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 3, 'in reče: Ah, Gospod, spomni se, prosim, da sem neprestano hodil pred teboj v resnici in z nerazdeljenim srcem in delal, kar je dobro v tvojih očeh! In jokal je Ezekija, silno jokal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 4, 'Tedaj pride beseda Gospodova Izaiju, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 5, 'Pojdi in reci Ezekiju: Tako pravi Gospod, Bog očeta tvojega Davida: Čul sem molitev tvojo, solze tvoje sem videl. Glej, dnem tvojim pridenem petnajst let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 6, 'In iz roke kralja asirskega otmem tebe in to mesto, in branil bom to mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 7, 'In to ti bodi znamenje od Gospoda, da stori Gospod tisto, kar je govoril:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 8, 'glej, onih stopinj senco, ki je šla doli po solnčni uri Ahazovi, pomaknem za deset stopinj nazaj. In vrnilo se je solnce za deset stopinj po solnčnem kazalniku, po katerem je bilo šlo doli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 9, 'Spis Ezekija, kralja Judovega, ko je bil zbolel in ozdravel bolezni svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 10, 'Rekel sem: V pokojnih mi dnevih moram stopiti v vrata šeola; oropan sem ostanka svojih let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 11, 'Dejal sem: Ne bom videl Gospoda, Gospoda v deželi živečih; ondi, kjer prebivajo mrtvi, ne bom več ugledal človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 12, 'Dom moj je razrušen in ga nosijo od mene kakor pastirski šator. Dotkal sem kakor tkalec življenje svoje; od statev me je odrezal. Od dne do noči me boš končal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 13, 'Tolažil sem se do jutra – kakor lev je zdrobil vse kosti moje. Od dne do noči me boš končal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 14, 'Kakor lastovka in žerjav sem cvičal, grulil sem kakor golob. Koprneče so mi zrle oči kvišku: O Gospod, v stiski sem, bodi mi porok!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 15, 'Kaj naj rečem? On mi je obljubil in On je tudi izpolnil. Tiho bom hodil vsa leta svoja zaradi bridkosti duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 16, 'O Gospod, ob tem žive ljudje in vsekakor je v tem življenje duha mojega; in me ozdraviš in ohraniš v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 17, 'Glej, v mir mi je bilo, da me je zadela bridkost prebridka; ali ti si v ljubezni potegnil dušo mojo iz jame pogube, kajti vse grehe moje si vrgel za hrbet svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 18, 'Saj šeol te ne slavi, smrt te ne hvali; ni upanja v zvestobo tvojo njim, ki se pogrezajo v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 19, 'Živeči, živeči te bo slavil kakor jaz danes; oče bo sinom oznanjal zvestobo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 20, 'Gospod je bil pripravljen rešiti me, zato bomo pesmi moje s strunami peli, dokler živimo, v hiši Gospodovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 21, 'Izaija pa je bil velel, naj vzemo gručo smokev in jo polože na ulje, in ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 38, 22, 'Ezekija pa je vprašal: Kaj je znamenje, da pojdem gori v hišo Gospodovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 1, 'V tistem času je poslal Merodak Baladan, sin Baladanov, kralj babilonski, pismo in dar Ezekiju; slišal je namreč, da je bil zbolel in zopet okreval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 2, 'In Ezekija se jih je oveselil in jim pokazal hišo dragocenosti svojih: srebro, zlato, dišave in najboljše olje, in vso orožnico svojo in vse, kar je bilo v zakladih njegovih; ničesar ni bilo v hiši njegovi in pod vso oblastjo njegovo, da bi jim tega Ezekija ne bil razkazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 3, 'Tedaj pride prorok Izaija h kralju Ezekiju in mu reče: Kaj so rekli oni možje in odkod so prišli k tebi? In Ezekija reče: Iz daljne dežele so prišli k meni, iz Babilona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 4, 'In vpraša: Kaj so videli v tvoji hiši? In Ezekija odgovori: Karkoli je v hiši moji, so videli; ničesar ni bilo v zakladih mojih, česar bi jim ne bil pokazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 5, 'Tedaj reče Izaija Ezekiju: Čuj besedo Gospoda nad vojskami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 6, 'Glej, pridejo dnevi, ko se odnese v Babilon vse, kar je v hiši tvoji in kar so nabrali očetje tvoji do tega dne; nič ne ostane, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 7, 'Tudi sinov tvojih, ki pridejo iz tebe, ki jih boš rodil, vzemo, in bodo dvorniki v palači babilonskega kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 39, 8, 'In Ezekija reče Izaiju: Dobra je beseda Gospodova, ki si jo govoril. Še reče: Saj bode mir in stanovitnost v dneh mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 1, 'Tolažite, tolažite ljudstvo moje, govori Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 2, 'Govorite na srce Jeruzalemu in kličite mu, da je dopolnjena vojna služba njegova, da je poravnana krivica njegova, da je dobil dvojno iz roke Gospodove za vse grehe svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 3, 'Glas vpijočega v puščavi: Pripravljajte pot Gospodu, ravnajte v pustinji cesto Bogu našemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 4, 'Vsaka dolina naj se dvigne in vsako goro in vsak grič znižajte, in kar je krivega, naj se poravna, in hribasto bodi ravnina!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 5, 'In razodene se slava Gospodova in vse meso vkup jo bo videlo; kajti usta Gospodova so govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 6, 'Glas govorečega: Oznanjaj! In vpraša: Kaj naj oznanjam? „Vse meso je trava in vsa milina njegova kakor cvetica na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 7, 'Trava sahne, cvetica vene, ker veje nanjo dih Gospodov. Res, ljudstvo je trava!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 8, 'Trava sahne, cvetica vene, a beseda Boga našega ostane vekomaj!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 9, 'Idi na goro visoko, o Sion, ki oznanjaš veselo vest; povzdigni močno glas svoj, Jeruzalem, ki oznanjaš veselo vest; povzdigni ga, ne boj se, reci mestom Judovim: Glejte, Bog vaš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 10, 'Glejte, Gospod, Jehova, prihaja kot mogočni in rama njegova gospoduje zanj; glejte, plačilo njegovo je pri njem in povračilo njegovo pred njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 11, 'Kakor pastir bo pasel čredo svojo, z roko svojo bo zbiral jagnjeta in jih nosil v naročju svojem, in doječe bo vodil rahlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 12, 'Kdo je izmeril z dlanjo svojo vode in s pedjo svojo premeril nebesa in vtlačil zemlje prah v merico in s tehtnico pretehtal gore in hribe na njenih torilih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 13, 'Kdo je vodil duha Gospodovega, in kdo mu je bil svetovalec ter ga je učil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 14, 'S kom se je posvetoval, da bi mu dodelil razuma in ga učil poti pravice in ga vadil v znanju in mu pokazal najvišje razumnosti pot?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 15, 'Glej, narodi so kakor kapljica v vedru in se čislajo kakor prašek na tehtničnem torilu; glej, otoke vzdiguje kakor trohico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 16, 'Tudi Libanona ne bi bilo dovolj za ogenj in živali njegovih ne bi bilo dovolj za žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 17, 'Vsi narodi so kakor nič pred njim, manj nego nič in ničevost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 18, 'Komu torej hočete primerjati Boga mogočnega? in kako podobo hočete postaviti poleg njega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 19, 'Podobo ulije umetnik in zlatar jo prevleče z zlatom in ji privari verižice srebrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 20, 'Kdor je ubožen, da ne more toliko darovati, izbere les, ki ne trohni; poišče si spretnega umetnika, da mu napravi podobo, ki se ne omaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 21, 'Ali ne veste? ali ne čujete? ali se vam ne oznanja od začetka? ali ne umejete ustanovitve zemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 22, 'On je, ki stoluje nad zemlje okrožjem, in prebivalci njeni so kakor kobilice, ki razprostira nebesa kakor tenčico in jih razpenja kakor šator v prebivanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 23, 'ki deva v nič kneze, sodnike na zemlji nareja kakor ničevo stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 24, 'Komaj so zasajeni, komaj zasejani, komaj se ukorenini v zemlji njih deblo, že pihne on vanje, in posuše se in piš jih odnese kakor slamico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 25, 'Komu me torej hočete pripodobiti, da bi mu bil enak? pravi Sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 26, 'Povzdignite kvišku oči in glejte: Kdo je ustvaril vse te zvezde? On, ki vodi po številu njih vojsko, jih kliče vse po imenu; vsled presilne moči njegove in ker je mogočen v krepkoti, se niti ena ne pogreša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 27, 'Zakaj praviš, o Jakob, in govoriš, Izrael: Skrita je pot moja pred Gospodom in pravda moja gre mimo Boga mojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 28, 'Ali ne veš? in nisi li slišal? Gospod je Bog večni, Stvarnik krajev zemlje; on ne opeša in se ne utrudi, nedoumna je razumnost njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 29, 'Trudnemu daje krepkosti in onemoglemu podeljuje obilo moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 30, 'Pešajo res mladi in se utrujajo, in mladeniči se spotikajo in padajo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 40, 31, 'oni pa, ki čakajo Gospoda, dobivajo nove moči, dvigajo se na perutih kakor orli, teko, a se ne utrudijo, hodijo, pa ne opešajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 1, 'Obrnite se molče do mene, otoki, in narodi naj si oskrbe nove moči; pridejo naj bliže in tedaj govoré; snidimo se na skupno pravdo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 2, 'Kdo je obudil od vzhoda tistega, ki ga pravičnost srečava pri vsakem koraku? On daje narode pred njega in spravlja kralje pod njegovo oblast; nareja jih prahu podobne z mečem njegovim in razvejani plevi enake z lokom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 3, 'On jih podi in gre mimo v miru po poti, ki po njej nikdar ni šel z nogami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 4, 'Kdo je osnoval to in storil? On, ki kliče rodove od začetka. Jaz, Gospod, ki sem prvi in pri poslednjih večno isti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 5, 'Otoki so to videli in so se bali, kraji zemlje so trepetali; bližali so se in se shajali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 6, 'Drug drugemu je pomagal in bratu svojemu govoril: Bodi srčen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 7, 'In podobar je osrčeval zlatarja in on, ki gladi s kladivom, njega, ki bije na nakovalo, govoreč o spajanju: Dobro je! in je malika pritrjal z žeblji, da se ne gane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 8, 'Ti pa, Izrael, hlapec moj, Jakob, ki sem te izvolil, seme Abrahama, prijatelja mojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 9, 'ti, ki sem te zgrabil od koncev zemlje in te poklical od skrajnih kotov njenih in ti rekel: Hlapec si moj, izvolil sem te in te nisem zavrgel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 10, 'Ne boj se, ker jaz sem s teboj, ne oziraj se plaho, ker jaz sem Bog tvoj; krepčam te, res, pomagam ti, res, podpiram te z desnico pravičnosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 11, 'Glej, osramočeni bodo in z nečastjo obliti vsi, ki se hudujejo nad teboj; kakor nič bodo in poginejo nasprotniki tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 12, 'Ko jih boš iskal, jih ne najdeš, tistih, ki so se prepirali s tabo; kakor nič in ničevost bodo možje, ki se bore zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 13, 'Zakaj jaz, Gospod, Bog tvoj, primem desnico tvojo, veleč ti: Ne boj se, jaz ti pomagam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 14, 'Ne boj se, črviček Jakobov, krdelce Izraelovo; jaz ti pomagam, govori Gospod, in odkupitelj tvoj je Svetnik Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 15, 'Glej, naredim te za novo mlatilnico z ostrimi dvoreznimi zobmi: mlatil boš in drobil gore in hribe boš storil v pleve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 16, 'Vejal jih boš, in veter jih odnese in vrtinec jih razkropi; ti pa se boš radoval v Gospodu, v Svetniku Izraelovem se boš ponašal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 17, 'Ubožce in siromake, ki iščejo vode, pa je ni, ki jim jezik suši od žeje, jaz, Gospod, jih uslišim, jaz, Bog Izraelov, jih ne zapustim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 18, 'Na golih višavah odprem reke in sredi dolin studence, v jezero vodá izpremenim puščavo in žejno zemljo v vrelce vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 19, 'Cedro zasadim v puščavi, akacijo, mirto in oljkovo drevje, v pustinji hkratu postavim ciprese, platane in zelenike;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 20, 'da bi videli in spoznali in v srce si vtisnili in razumeli vsi vkup, da je to storila roka Gospodova in da je Svetnik Izraelov to ustvaril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 21, 'Pridite sem s pravdo svojo, pravi Gospod; prinesite trdne dokaze svoje, veli Kralj Jakobov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 22, 'Predlože naj nam in naznanijo, kar se bo zgodilo; kaj so prejšnje stvari, razložite, da to razmislimo v srcu in spoznamo njih konec; ali kaj je prihodnjega, povejte nam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 23, 'Naznanite, kar pride pozneje; spoznamo naj, da ste bogovi! Storite vsaj kaj dobrega ali slabega kaj, da se ozremo drug na drugega in si skupaj ogledamo tisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 24, 'Glejte, vi ste manj nego nič in delo vaše je ničevost; gnusoben je, kdor vas voli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 25, 'Obudil sem ga od severa in je prišel – od solnčnega vzhoda njega, ki kliče ime moje. In pride in pogazi vladarje kakor blato in kakor lončar gnete ilovico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 26, 'Kdo je to naznanil od početka, da bi vedeli? in od starodavnosti, da rečemo: Prav pravi! A ni ga bilo, da bi bil naznanil, ni ga bilo, ki bi bil napovedal, ni ga bilo, ki bi bil slišal besede vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 27, 'Prvi jaz sem rekel Sionu: Glej, glej, tu je! In Jeruzalemu dam blagovestnika!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 28, 'In ozrl sem se, in ni bilo nikogar, in med temi ni bilo svetovalca, da bi bil odgovoril besedo, ko sem jih vprašal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 41, 29, 'Glej, vsi ti skup so ničemurnost, nič niso njih dela; veter in pusta blodnja so njih ulite podobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 1, 'Glej, hlapec moj, ki ga podpiram, izvoljenec moj, ki je duši moji po volji: duha svojega sem del nanj, pravico bo oznanjal poganskim narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 2, 'Vpil ne bo, ne hrupa napravljal, in glas njegov se ne bo čul po ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 3, 'Trsta nalomljenega ne zlomi in tlečega stenja ne pogasi; po resnici bo oznanjeval pravico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 4, 'Ne bo opešal, ne bo potrt, dokler ne ustanovi pravice na zemlji; in otoki bodo čakali nauka njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 5, 'Tako pravi Bog mogočni, Jehova, ki je ustvaril nebesa in jih razpel, ki je raztegnil zemljo ž njenim rastlinjem, ki daje dihanje ljudstvu, živečemu na njej, in duhá njim, ki hodijo po njej:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 6, 'Jaz, Gospod, sem te poklical v pravičnosti, in primem te za roko in te bom čuval, in dam te v zavezo ljudstvu, v svetlobo poganskim narodom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 7, 'da odpreš slepe oči, da izvedeš iz zapora jetnike, iz ječe nje, ki sede v temi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 8, 'Jaz sem Gospod, to je ime moje, in slave svoje ne dam drugemu, ne hvale svoje rezanim podobam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 9, 'Prejšnje, glejte, se je zgodilo in novo naznanjam; preden nastane, vam napovedujem to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 10, 'Pojte Gospodu novo pesem, hvalo njegovo od konca zemlje vi, ki se vozite po morju, in vse, kar je v njem, otoki in njih prebivalci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 11, 'Zaženo naj glas puščava in mesta njena, vasi, v katerih prebiva Kedar; pojo naj prebivalci skalnega kraja, s temena gorá naj vpijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 12, 'Dajo naj slavo Gospodu in hvalo njegovo naj oznanjajo po otokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 13, 'Gospod izide kakor junak, kakor mož bojevit zbudi gorečnost svojo, vpil bo in bojni krik zagnal, zoper sovražnike svoje se bo vedel junaško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 14, 'Molčal sem dolgo časa, bil sem tih in se zdrževal; sedaj pa bom vpil kakor porodnica in sopihal in hkrati duškal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 15, 'Opustošim gore in hribe in vso njih travo posušim in reke naredim v otoke in jezera posušim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 16, 'In popeljem slepce po potu, ki ga ne poznajo, po stezah, ki so jim tuje, jim dam hoditi; temo pred njimi naredim v svetlobo in hribast kraj v ravan. Te reči storim in jih ne opustim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 17, 'Umakniti se morajo, sramota jih oblije, kateri upajo v rezane podobe, kateri pravijo ulitim podobam: Vi ste bogovi naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 18, 'Oj glušci, poslušajte, in vi slepci, odprite oči, da vidite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 19, 'Kdo je slep, če ne hlapec moj? in gluh kakor poslanec moj, ki ga pošiljam? Kdo je slep kakor on, ki je v miru z menoj, slep kakor hlapec Gospodov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 20, 'Videl si mnogo, a ne meniš se za to; ušesa odpira, vendar ne sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 21, 'Gospod je blagovolil zaradi pravičnosti svoje poveličati postavo in jo postaviti v čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 22, 'A to je ljudstvo oplenjeno in oropano; vsi vkup so ujeti v luknjah in skrivajo se po ječah; v plen so, in nihče jih ne otimlje, ropanju so izročeni, in nihče ne pravi: Povrni jim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 23, 'Kdo je med vami, ki bi nagnil ušesa za to, ki bi pazil in poslušal v prihodnje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 24, 'Kdo je dal Jakoba v ropanje in Izraela njim, ki plenijo? Ali ne Gospod, zoper katerega smo grešili? Niso namreč hoteli hoditi po potih njegovih, in poslušali niso postave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 42, 25, 'Zato je razlil čezenj jeze svoje srd in vojske silo; ali dasi ga je zažgala kroginkrog, ni spoznal, zapalila ga je, a ni mu seglo v srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 1, 'Sedaj pa pravi tako Gospod, ki te je ustvaril, Jakob, in ki te je upodobil, Izrael: Ne boj se! kajti odkupil sem te, poklical sem te po imenu tvojem; ti si moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 2, 'Ko pojdeš skozi vode, bodem pri tebi, in preko rek, te ne poplavijo; ko pojdeš skozi ogenj, ne zgoriš in plamen te ne zapali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 3, 'Zakaj jaz sem Gospod, tvoj Bog, Svetnik Izraelov, rešitelj tvoj; v odkup tvoj sem dal Egipt, Etiopijo in Sebo zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 4, 'Zato ker si drag v mojih očeh in čislan in ker te ljubim, hočem dati ljudi zate in narode za življenje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 5, 'Ne boj se, ker jaz sem s teboj. Od vzhoda privedem nazaj seme tvoje in zberem te od zahoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 6, 'Severu zapovem: Daj nazaj! in poldnevu: Ne pridržuj, privedi sinove moje iz daljave in hčere moje od kraja zemlje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 7, 'vsakega, ki se imenuje po imenu mojem, ki sem ga ustvaril v slavo svojo, ki sem ga upodobil in naredil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 8, 'Izpelji ljudstvo slepo, ki ima oči, in glušce, ki imajo ušesa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 9, 'Vsi narodi naj se zbero in ljudstva naj se snidejo! Kdo med njimi more napovedati to? ali prejšnje reči naj nam oznanijo! postavijo naj priče svoje, da se opravičijo, da se bo slišalo in reklo: Res je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 10, 'Vi ste priče moje, govori Gospod, in hlapec moj, ki sem ga izvolil: da bi spoznali in verovali meni in umeli, da sem jaz večno isti. Pred menoj ni bil upodobljen Bog mogočni in ne bode ga za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 11, 'Jaz, jaz sem Gospod, in ni ga razen mene rešitelja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 12, 'Jaz sem napovedoval in reševal in oznanjal, ne pa tuj bog med vami; in vi ste mi priče, govori Gospod, da sem jaz Bog mogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 13, 'Tudi od tega dne bodem večno isti, in ni ga, ki bi rešil iz roke moje. Delam, in kdo more zabraniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 14, 'Tako pravi Gospod, odrešenik vaš, Svetnik Izraelov: Zaradi vas sem poslal v Babilon, in hočem jih vse kakor ubežnike gnati doli, tudi Kaldejce na ladjah, katerih so se veselili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 15, 'Jaz, Gospod, sem Svetnik vaš, stvarnik Izraelov, kralj vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 16, 'Tako pravi Gospod, ki dela pot po morju in stezo po silnih vodah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 17, 'ki izpeljava vozove in konje, krdela in moč – vkup bodo ležali, ne vstanejo več, izdahnejo, ugasnejo kakor predivo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 18, 'Ne spominjajte se prejšnjih reči in ne pečajte se za stare!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 19, 'Glej, jaz storim novo stvar: zdajci že klije, ali bi je ne spoznali? Da, v puščavi naredim pot in reke v samoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 20, 'Častila me bo žival poljska, šakali in noji, ker dam v puščavo vode, reke v samoto, da bodo v pijačo mojemu ljudstvu, izvoljenemu mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 21, 'To ljudstvo, ki sem si ga izobrazil, bo pripovedovalo hvalo mojo. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 22, 'Kajti mene nisi klical, o Jakob, da bi se bil utrudil zame, o Izrael!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 23, 'Nisi mi prinašal drobnice žgalnih darov svojih in z žrtvami svojimi me nisi častil. Nisem te tlačil, da mi služiš z jedilnim darom, in nisem ti prizadeval truda s kadilom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 24, 'nisi mi kupil z denarjem trsta dišečega in s tolščo žrtev svojih me nisi krepčal. Ali hlapčevsko delo si mi storil z grehi svojimi, utrudil si me s krivicami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 25, 'Jaz, jaz sam izbrisujem prestopke tvoje zaradi sebe, in grehov tvojih se ne spominjam več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 26, 'Opomni me, pravdajva se skupaj, razloži vendar svoje, da se opravičiš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 27, 'Tvoj prvi oče je grešil, in sredniki tvoji so se mi izneverili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 43, 28, 'Zato sem onečastil poglavarje svetišča in prokletstvu izročil Jakoba in Izraela zasramovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 1, 'Sedaj pa poslušaj, Jakob, hlapec moj, in Izrael, ki sem ga izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 2, 'Tako pravi Gospod, ki te je ustvaril in upodobil iz materinega telesa, ki ti pomaga: Ne boj se, hlapec maj Jakob, in Ješurun, ki sem te izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 3, 'Kajti vode razlijem čez žejno in potoke na suho; duha svojega razlijem na seme tvoje in blagoslov svoj na potomce tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 4, 'In razcveto se kakor med travo, kakor vrbe poleg vodotokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 5, 'Ta poreče: Gospodov sem! in oni proglasi ime Jakobovo za svoje; oni pa se zapiše z roko svojo Gospodu, in častno ime mu bode Izrael.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 6, 'Tako pravi Gospod, kralj Izraelov in odrešenik njegov, Gospod nad vojskami: Jaz sem prvi in jaz poslednji, in razen mene ni Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 7, 'In kdo kakor jaz more oznanjati – naj torej oznani in mi po vrsti ražloži! – odkar sem ustanovil starodavno ljudstvo? Naj torej oznanijo, kar bode in kar se zgodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 8, 'Ne plašite se in ne bojte se! Nisem li tega oddavnaj ti dal slišati in ti naznanil? in vi ste priče moje. Ali je Bog razen mene? Gotovo ni nobene Skale, ne poznam nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 9, 'Kateri izrezujejo podobe, so vsi ničemurneži, in njih ljubčki ne morejo koristiti; in kateri so malikom priče, ne vidijo ničesar in ne spoznavajo, da bi jih bilo sram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 10, 'Kdo je kdaj upodobil boga in ulil podobo, da ne bi bil hotel nobene koristi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 11, 'Glej, vsi, ki se družijo z malikom, bodo osramočeni, in podobarji so goli ljudje. Zbero naj se vsi in skup se postavijo: preplašeni, osramočeni bodo vsi skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 12, 'Kovač napravlja sekiro in dela z žerjavico in s kladivi upodablja malika in ga obdelava s krepko roko svojo; strada tudi, da mu peša moč, ne pije vode, da onemore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 13, 'Lesorezec potegne ravnalo, očrta s črtalom, izgladi s stružcem in nariše s šestilom, in ga naredi kakor podobo moža, kakor človeško lepoto, da prebiva v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 14, 'Poseka si cedro ali vzame graden ali hrast in si izbira med drevjem v gozdu; in ko je vsadil jesen in ga je dež vzredil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 15, 'tedaj je človeku v sežig, ker vzame od njega, da se ogreje, in zakuri ž njim, da speče kruh; naredi tudi iz njega boga in se mu klanja; napravi iz njega podobo in pada prednjo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 16, 'Polovico ga je požgal v ognju, pri polovici njegovi jé meso, peče pečenko in se siti; tudi greje se in pravi: Aha! ogrel sem se, čutim ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 17, 'Iz ostanka njegovega naredi boga, podobo svojega malika, pada na tla pred njim ter se klanja in ga prosi, govoreč: Reši me, kajti bog mogočni si moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 18, 'Ne spoznajo in ne razvidijo; zakaj zalepil jim je oči, da ne vidijo, in srca, da ne umejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 19, 'In nihče ne pomisli v srcu in nima spoznanja in razsodnosti, da bi rekel: Polovico njega sem požgal v ognju in tudi pri žerjavici njegovi sem pekel kruh, pekel meso in sem jedel; in kar je ostalo od njega, naj napravim v stvar ostudno? pred lesenim hlodom naj padam na tla?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 20, 'S pepelom se pase, srce prevarano ga zapeljuje, da ne more rešiti duše svoje, niti ne reče: Ni li prevara v desnici moji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 21, 'Spominjaj se tega, o Jakob, in Izrael, ker si hlapec moj. Upodobil sem te, hlapec si moj, Izrael, ne pozabim te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 22, 'Izbrisal sem kakor gost oblak prestopke tvoje in kakor meglo grehe tvoje. Vrni se k meni, kajti odkupil sem te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 23, 'Pojte, nebesa, zakaj Gospod je storil to! Ukajte, zemlje globočine, pojoč bobnite, gore, gozd in sleherno drevo v njem, zakaj Gospod je odkupil Jakoba in v Izraelu se oslavlja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 24, 'Tako pravi Gospod, odkupitelj tvoj in obrazovatelj tvoj iz materinega telesa: Jaz, Gospod, sem, ki delam vse: nebesa sem razpel sam, zemljo sem raztegnil – kdo je bil z menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 25, 'Jaz sem, ki uničujem znamenja lažnikov in iz vedeževalcev narejam neumneže, ki zavračam modre in abotno delam njih znanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 26, 'ki potrjujem hlapca svojega besedo in dovršujem poslancev njegovih svèt, ki govorim o Jeruzalemu: Imel bo prebivalce! in o mestih Judovih: Zidala se bodo, in podrtine njegove postavim pokonci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 27, 'ki velim globočini: Posúši se, in reke tvoje posušim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 44, 28, 'ki velim Ciru: Pastir moj je, in dopolni vso voljo mojo, ko ukaže za Jeruzalem: Bodi sezidan! in za tempelj: Ustanovi se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 1, 'Tako pravi Gospod maziljencu svojemu, Ciru, ki sem ga prijel za desnico, da porazim pred njim narode, in hočem razpasati ledje kraljem, da odprem duri pred njim in vrata ne ostanejo zaprta:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 2, 'Jaz bom hodil pred teboj in poravnaval, kar ni ravno; vrata jeklena razbijem in polomim železne zapahe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 3, 'in dam ti zaklade, zakopane v temi, in blago, shranjeno na skrivnem, da spoznaš, da sem jaz Gospod, ki sem te poklical po imenu tvojem, Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 4, 'Zaradi hlapca svojega Jakoba in Izraela, izvoljenca svojega, sem te klical po imenu tvojem, dal ti priimek, dasi me nisi poznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 5, 'Jaz sem Gospod in nobenega drugega ni, razen mene ni Boga. Opašem te, dasi me ne poznaš,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 6, 'da naj spoznajo od solnčnega vzhoda in od zahoda njegovega, da ni nobenega drugega razen mene. Jaz sem Gospod in nobenega drugega ni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 7, 'ki ustvarjam svetlobo in delam temo, narejam mir in napravljam nesrečo; jaz Gospod sem, ki delam vse to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 8, 'Rosite z viška, nebesa, in najvišji oblaki, dežíte pravičnost! odpri se, zemlja, in ródi zveličanje in hkratu naj vzraste pravičnost. Jaz, Gospod, sem ustvaril to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 9, 'Gorje mu, ki se prepira z obrazovateljem svojim, čepinja med čepinjami prstenimi! Sme li pač reči glina obrazovatelju svojemu: Kaj delaš? ali tvoje delo o tebi: Rok nima!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 10, 'Gorje njemu, ki pravi očetu: Čemu rodiš? in ženi: Čemu si v porodnih bolečinah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 11, 'Tako pravi Gospod, Svetnik Izraelov in obrazovatelj njegov: Vprašajte me za to, kar ima priti, za otroke moje in za rok mojih delo mi naročajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 12, 'Jaz sem naredil zemljo in ustvaril človeka na njej; jaz, moje roke so razpele nebesa in sleherni njih vojski sem dal povelja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 13, 'Jaz sem ga zbudil v pravičnosti in poravnam vsa pota njegova; on sezida mesto moje in odgnance moje pošlje nazaj, ne za kupno ceno ne za denar, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 14, 'Tako pravi Gospod: Pridelek egiptovski in dobiček Etiopije in Sabejci, možje visoke postave, preidejo na tvojo stran in bodo tvoji; za teboj pojdejo, zvezani preidejo k tebi in tebi se bodo klanjali, tebe bodo prosili, govoreč: Zares, Bog mogočni je pri tebi, in nobenega drugega Boga ni nikjer drugod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 15, 'Resnično, ti si Bog mogočni, skrivajoči se, o Bog Izraelov, Rešitelj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 16, 'Sramovali se bodo in osramočeni bodo vsi, s sramoto odidejo vsi podobarji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 17, 'Izrael bo rešen po Gospodu z večnim rešenjem; ne bode vas sram in osramočeni ne boste na večne veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 18, 'Kajti tako pravi Gospod, stvarnik nebes (on sam je Bog!), obrazovatelj zemlje in stvaritelj njen; on jo je utrdil, ni je ustvaril puste, ampak upodobil jo je v prebivanje: Jaz sem Gospod in drugega ni nobenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 19, 'Nisem govoril na skrivnem, v kraju temne zemlje; nisem velel semenu Jakobovemu: Iščite me brezuspešno! Jaz sem Gospod, ki govorim pravičnost, oznanjam, kar je pravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 20, 'Zberite se in pridite, bližajte se vsi, ki ste ušli iz poganskih narodov! Nimajo spoznanja, ki nosijo les rezane podobe svoje in molijo k bogu, ki ne more rešiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 21, 'Napovejte in blizu prinesite! Tudi posvetujejo naj se med seboj! Kdo je oznanjal to od prvih dni, kdo je napovedoval to od davnega časa? Ali ne jaz, Gospod? in nobenega drugega Boga ni razen mene; mogočnega Boga, pravičnega in rešitelja ni drugega razen mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 22, 'Ozrite se v mene in rešeni bodete, vsi kraji zemlje, zakaj jaz sem Bog mogočni in drug nobeden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 23, 'Pri sebi sem prisegel, iz ust pravičnosti je prišla beseda, ki se ne prekliče: da se meni pripogne vsako koleno, meni bo prisegal vsak jezik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 24, 'Samo v Gospodu, poreko o meni, je vsa pravičnost in moč. K njemu pridejo, ali osramočeni bodo vsi, ki so se vnemali zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 45, 25, 'V Gospodu bo opravičeno in se bo hvalilo vse seme Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 1, 'Zgrudil se je Bel, omahnil je Nebo; njih maliki so bili naloženi živalim in govedom; stvari, ki ste jih prenašali, so tovor, breme utrujeni živali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 2, 'Omahnili so, zgrudili so se vsi, niso mogli oteti bremena, temuč sami so odšli v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 3, 'Poslušajte me, o hiša Jakobova in ves ostanek hiše Izraelove, ki vas nosim od materinega telesa, pestujem od materinega naročja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 4, 'In prav do starosti sem jaz vedno isti, in do sivosti vas bom jaz nosil; jaz sem storil in jaz bom prenašal, jaz, pravim, bom nosil in rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 5, 'Komu me hočete prilikovati in enačiti ali me primerjati, da bi bili podobni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 6, 'Kateri trosijo zlato iz mošnje in tehtajo srebro na tehtnici, najmejo za plačo zlatarja, ki naj naredi iz njega boga; padajo na tla ter se mu klanjajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 7, 'vzdigujejo ga, nosijo ga na rami, nato ga postavijo na mesto svoje, kjer stoji; z mesta svojega se ne gane. Tudi vpijejo k njemu, a ne odgovori, nikogar ne reši iz stiske njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 8, 'Pomnite to in bodite možje, premislite v srcu, odpadniki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 9, 'Spominjajte se početkov od večnosti, da sem jaz Bog mogočni in nobenega ni drugega, da sem Bog, in nihče ni meni enak,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 10, 'ki oznanjam od početka konec in od starodavnosti, kar se ni še zgodilo; ki velim: Sklep moj bo stal in storil bom vse, kar me veseli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 11, 'ki kličem od vzhoda ptico roparico, iz daljne dežele izvršitelja svojega sklepa. Govoril sem in tudi storim, da pride tisto; načrt sem napravil, pa tudi izvršim tisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 12, 'Poslušajte me, uporni v srcu, ki ste daleč od pravičnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 46, 13, 'Blizu sem pripravil pravičnost svojo, ni daleč, in zveličanje moje se ne bo obotavljalo; in na Sionu dam zveličanje, Izrael bode slava moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 1, 'Stopi doli in sedi v prah, o devica, hči babilonska! Sedi na tla, brez prestola, hči Kaldejcev! kajti ne boš se več imenovala nežna in mehkužna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 2, 'Vzemi mlinske kamene in melji moko; odgrni zastor svoj, vzdigni vlečke, odkrij stegno, gazi skozi reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 3, 'Odkrije se nagota tvoja, videla se bo tudi sramota tvoja. Maščeval se bom in ne prizanesem nobenemu človeku. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 4, 'Naš odrešenik, Gospod nad vojskami je ime njegovo, Svetnik Izraelov. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 5, 'Sédi molčé in pojdi v temo, hči Kaldejcev! zakaj ne boš se več imenovala Gospa kraljestev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 6, 'Razsrdil sem se bil zoper ljudstvo svoje, oskrunil sem dediščino svojo in dal sem jih tebi v pest: nisi jim izkazala nobene milosti, celó starcu si nakladala težki jarem svoj silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 7, 'In rekla si: Večno bodem gospa! in tako nisi tega premislila v srcu, pomislila nisi konca temu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 8, 'Sedaj torej čuj to, razkošnica, ki brez skrbi sediš in praviš v srcu svojem: Jaz sem, in nobene več ni razen mene; ne bom sedela vdova in okusila ne bom brezotročnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 9, 'Ali prigodi se ti oboje nagloma, v isti dan: brezotročnost in vdovstvo; docela te zadene oboje navzlic obilemu vražarstvu tvojemu, vkljub silno številnemu čaranju tvojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 10, 'Zakaj ti si se zanašala na hudobnost svojo, govorila si: Nihče me ne vidi. Modrost tvoja in vednost tvoja, ti sta te premotili; in govorila si v srcu svojem: Jaz sem, in nobene druge več razen mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 11, 'Zatorej te zadene nesreča, ki je ne boš znala s čaranjem odpraviti, zgrne se nadte poguba, ki je ne boš mogla odvrniti, in zadene te nagloma pokončanje, ki ga še ne slutiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 12, 'Postavi se, pravim, s čaranjem svojim in z množino svojega vražarstva, v katerem si se trudila od mladih nog svojih, če boš morda imela kaj uspeha, če morebiti koga prestrašiš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 13, 'Opešala si vsled tolikega posvetovanja svojega. Postavijo naj se torej razkladalci nebes, ogledovalci zvezd, ki oznanjajo na mesece, kar te bo zadelo, in naj te rešijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 14, 'Glej, kakor strnišče so, ogenj jih požge, ne rešijo se sami plamena; ne ostane od njih žerjavice, da bi se človek grel, ne ognja, da bi mu sedel nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 47, 15, 'Tako ti bodo oni, za katere si se trudila, s katerimi si kupčevala od mladosti svoje: vsak bo blodil na svojo stran, nihče te ne reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 1, 'Poslušajte to, hiša Jakobova, ki se kličete po imenu Izraelovem in ste izšli iz vodá Judovih, ki prisegate pri imenu Gospodovem in hvalno omenjate Boga Izraelovega, a ne v resnici in ne v pravičnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 2, 'zakaj imenujejo se po svetem mestu in opirajo se na Boga Izraelovega, Gospod nad vojskami je ime njegovo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 3, 'Prejšnje sem naznanjal od nekdaj, in iz mojih ust je izšlo in sem to razglasil; mahoma sem to dopolnil, in zgodilo se je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 4, 'Ker sem vedel, da si trd in da je kita železna tilnik tvoj in čelo tvoje jekleno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 5, 'zato sem ti to naznanjal od nekdaj; ko se ni še zgodilo, sem ti povedal to, da bi ne govoril: Malik moj je storil to in izdolbena ali ulita podoba moja je zapovedala tisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 6, 'Slišal si to; ogleduj vse to! in vi, nočete li tega priznati? Odslej ti napovedujem novo in dosihdob skrito, česar nisi vedel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 7, 'Sedaj se to ustvarja, ne pa oddavna, in pred tem dnevom nisi slišal za to, da ne porečeš: Glej, vedel sem to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 8, 'Niti slišal nisi nič niti vedel, tudi od nekdaj ni bilo odprto uho tvoje; kajti poznal sem te, da ravnaš silno nezvesto in da se imenuješ prestopnik od materinega telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 9, 'Zaradi imena svojega zadržujem jezo svojo in zaradi hvale svoje jo krotim, tebi v prid, da te ne iztrebim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 10, 'Glej, prečistil sem te, a ne kot srebro; izbranega sem te naredil v topilnici bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 11, 'Zaradi sebe, zaradi sebe storim to, kajti kako bi se oskrunilo ime moje! in slave svoje ne dam drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 12, 'Poslušaj me, o Jakob, in Izrael, poklicanec moj! Jaz sem večno isti, jaz sem prvi, jaz tudi poslednji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 13, 'Moja roka je vendar ustanovila zemljo in desnica moja razpela nebesa; ko sem jih poklical, brž so bila vsa tu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 14, 'Zberite se vi vsi in čujte: Kdo izmed onih je naznanil tisto? Ki ga Gospod ljubi, ta izpolni voljo njegovo nad Babilonom in roka njegova bode nad Kaldejci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 15, 'Jaz, jaz sem govoril, jaz sem ga tudi poklical; pripeljal sem ga, in pot njegova bode uspešna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 16, 'Pristopite k meni, čujte to! Od početka nisem na skrivnem govoril; od tistega časa, ko se je zgodilo to, sem bil pri tem. In sedaj me je poslal Gospod Jehova in duh njegov. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 17, 'Tako pravi Gospod, odrešenik tvoj, Svetnik Izraelov: Jaz sem Gospod, Bog tvoj, ki te učim, kar ti je v korist, ki te spremljam po potu, po katerem ti je hoditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 18, 'O da bi bil pazil na zapovedi moje! tedaj bi bil kakor reka mir tvoj in pravičnost tvoja kakor morsko valovje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 19, 'in kakor pesek bi bil zarod tvoj in rojeni iz osrčja tvojega kakor kamenjiče njegovo; njegovo ime bi se ne zatrlo in ne pogubilo izpred mojega obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 20, 'Pojdite ven iz Babilona, bežite od Kaldejcev; z zmagoslavnim glasom naznanjajte, pripovedujte to, razširjajte to do kraja zemlje! Govorite: Odkupil je Gospod hlapca svojega Jakoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 21, 'In žejni niso bili, ko jih je vodil po puščavah; točil jim je vode iz skale: razklal je skalo, in vode so tekle!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 48, 22, 'Ni ga miru, pravi Gospod, brezbožnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 1, 'Poslušajte me, otoki, in pazite, ljudstva iz daljave! Gospod me je poklical od materinega telesa, od osrčja matere moje se me je spominjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 2, 'In naredil je usta moja kakor oster meč, s senco roke svoje me je zakril; in naredil me je za pšico izbrušeno, v tulu svojem me je skril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 3, 'In mi je rekel: Hlapec si moj, Izrael, po katerem se bom oslavljal. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 4, 'Jaz pa sem rekel: Brezuspešno sem se trudil, brezkoristno in za nič sem potratil moč svojo; vendar pa je pravica moja pri Gospodu in plačilo moje je pri Bogu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 5, 'Sedaj pa govori Gospod, ki me je izobrazil od materinega telesa za hlapca svojega, naj Jakoba nazaj pripeljem k njemu in da bodi Izrael zbran k njemu (ker sem slaven v očeh Gospodovih in Bog moj je postal moja moč),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 6, 'govori, pravim: Malo je, da si mi hlapec, da bi povzdignil rodove Jakobove ter nazaj pripeljal ohranjence Izraelove; tudi te postavim za luč poganskim narodom, da bodeš zveličanje moje prav do konca zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 7, 'Tako pravi Gospod, odrešenik Izraelov, Svetnik njegov, njemu, ki ga zaničuje vsakdo, ki je gnus narodov, hlapcu gospodovalcev: Kralji te bodo videli in spoštljivo vstali, knezi se bodo klanjali zaradi Gospoda, ki je zvest, Svetnika Izraelovega, ki te je izvolil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 8, 'Tako pravi Gospod: Ob času milosti sem te uslišal in v dan zveličanja sem ti pomagal; in stražil te bom in te dal v zavezo ljudstvu, da povzdigneš deželo, da v posest razdeliš opustošene dediščine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 9, 'da porečeš jetnikom: Pojdite ven! njim, ki sede v teminah: Pridite na svetlo! Po potih se bodo pasli in po vseh golih hribih imeli svojo pašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 10, 'Lačni ne bodo, ne žejni, tudi zračna prikazen jih ne omami in solnce ne zadene; kajti njih milostnik jih bo vodil in poleg vrelcev vodá jih bo peljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 11, 'In vse svoje gore naredim, da bodo prelazne, in moje ceste se bodo z nasipom povišale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 12, 'Glej, ti pridejo od daleč, in glej, ti od severa in od zahoda, in ti iz dežele Sinimcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 13, 'Prepevajte, nebesa, in raduj se, zemlja, in pojoč bobnite, gore! zakaj Gospod je potolažil ljudstvo svoje in se je usmilil siromakov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 14, 'A Sion je rekel: Jehova me je zapustil in Gospod me je pozabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 15, 'More li žena pozabiti dojenca svojega, da bi se ne usmilila sina telesa svojega? In ko bi tudi matere pozabile, jaz vendar ne pozabim tebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 16, 'Glej, na obe dlani sem si te vdolbel; zidovi tvoji so vedno pred mano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 17, 'Hiteli bodo k tebi otroci tvoji; podiralci tvoji in opustoševalci tvoji odidejo iz tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 18, 'Ozri se kroginkrog in glej: tisti vsi se zbirajo in prihajajo k tebi. Kakor res živim, govori Gospod, z vsemi tistimi se boš oblekla kakor z lepotičjem, obvezala si jih boš kakor nevesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 19, 'Zakaj, kar se tiče tvojih razvalin in podrtih mest tvojih in porušene dežele tvoje – sedaj bodeš res pretesna za prebivalce; in tisti, ki so te požirali, odidejo daleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 20, 'Še poreko, da boš slišala, otroci osamljenja tvojega: Pretesno mi je to mesto; naredi mi prostora, da morem prebivati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 21, 'Tedaj porečeš v srcu svojem: Kdo mi je rodil tiste, ko sem bila brez otrok in nerodovitna, pregnana in sem se semtertja potikala? in kdo mi je vzredil téle? Glej, saj sem bila zapuščena samica, kje so bili tile?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 22, 'Tako pravi Gospod Jehova: Glej, proti narodom povzdignem roko svojo in proti ljudstvom postavim zastavo svojo, in prineso sinove tvoje v naročju in hčere tvoje bodo nosili sem na svojih ramah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 23, 'In kralji bodo redniki tvoji in njih kneginje dojke tvoje; klanjali se ti bodo z obličjem do tal in prah tvojih nog bodo lizali. In spoznaš, da sem jaz Gospod: ne osramoté se, ki me čakajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 24, 'Se li more velikanu odvzeti plen? ali se morejo oteti, ki so ujeti po pravici?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 25, 'Res, tako pravi Gospod: Tudi jetniki velikanovi se mu vzamejo in plen siloviteža se otme; kajti jaz se bom boril zoper tiste, ki se s teboj bore, in otroke tvoje rešim jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 49, 26, 'In storim, da bodo zatiralci tvoji jedli lastno svoje meso, in kakor z vinom se bodo upijanjali s svojo krvjo; in spozna vse meso, da sem jaz Gospod zveličar tvoj in odrešenik tvoj, Mogočni Jakobov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 1, 'Tako pravi Gospod: Kje je matere vaše ločitni list, s katerim sem jo odslovil? ali kdo je izmed upnikov mojih, ki sem mu vas prodal? Glejte, zaradi svojih krivic ste prodani in zaradi vaših prestopkov je odslovljena mati vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 2, 'Zakaj ni bilo nikogar, ko sem prišel? ko sem klical, nihče ni odgovoril? Je li mar roka moja prekratka, da bi otela? ali pa ni v meni moči nobene za rešenje? Glej, s karanjem svojim posušam morje, reke izpreminjam v puščavo, da njih ribe gnijejo in mrjo od žeje, zato ker ni vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 3, 'Nebesa oblačim v črnino in raševino jim napravljam za odejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 4, 'Gospod Jehova mi je dal izurjen jezik, da znam o pravem času izreči besedo trudnemu. Zbuja me sleherno jutro, zbuja mi uho, da poslušam kakor učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 5, 'Gospod Jehova mi je odprl uho, in jaz se nisem upiral, ne se umaknil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 6, 'Život svoj sem izpostavil njim, ki so me bili, in lice svoje njim, ki so me tezali; obličja svojega nisem skril sramotenju in pljuvanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 7, 'Kajti Gospod Jehova mi pomaga, zato nisem bil osramočen; zatorej sem nastavil obličje svoje kakor pretrd kamen in vem, da ne pridem v sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 8, 'Blizu je on, ki me opravičuje; kdo se bo prepiral z menoj? Stopiva si nasproti! Kdo hoče poskusiti pravdo zoper mene? naj pride k meni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 9, 'Glej, Gospod Jehova mi bo pomagal: kdo je, ki bi me obsodil? Glej, vsi skup se postarajo kakor sukno, molj jih pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 10, 'Kdo je med vami, ki se boji Gospoda, ki posluša hlapca njegovega glas? Kdor hodi po temi, komur ni svetlobe, upaj v ime Gospodovo in opiraj se na Boga svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 50, 11, 'Glejte, vi vsi, ki vžigate ogenj, z ognjenimi strelami se oborožujete: pojdite v žar ognja svojega in v požare, ki ste jih zapalili. To se vam zgodi od moje roke, v bolesti boste ležali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 1, 'Poslušajte me vi, ki hodite za pravičnostjo, ki iščete Gospoda! Glejte na skalo, iz katere ste izsekani, in v votlino jame, iz katere ste izkopani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 2, 'Glejte na Abrahama, očeta svojega, in na Saro, ki vas je rodila: kajti poklical sem ga, ko je bil edinec, in sem ga blagoslovil in ga pomnožil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 3, 'Zakaj Gospod je potolažil Sion, potolažil je vse razvaline njegove in je naredil puščavo njegovo kakor raj in samoto njegovo kakor vrt Gospodov; veselje in radost bo na njem, zahvala in psalmov glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 4, 'Poslušajte me, ljudstvo moje, in narod moj, obrnite ušesa v me! kajti postava pride od mene, in pravico svojo postavim ljudstvom za svetlobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 5, 'Blizu je pravičnost moja, izšlo je zveličanje moje, in roke moje bodo sodile ljudstva, v meni bodo imeli upanje otoki in čakali bodo rame moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 6, 'Povzdignite proti nebesom oči in glejte zemljo spodaj! zakaj nebesa izginejo kakor dim in zemlja se postara kakor obleka, in prebivalci njeni pomrjo enako. Ali zveličanje moje bode vekomaj in pravičnost moja se ne okruši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 7, 'Poslušajte me vi, ki poznate pravičnost, ljudstvo, ki ima postavo mojo v srcu svojem: Ne bojte se zasramovanja smrtnega človeka in ne plašite se njih preklinjanja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 8, 'Zakaj kakor sukno jih razje molj in kakor volno jih razgrize črvič; pravičnost moja pa bode vekomaj in zveličanje moje od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 9, 'Zbudi se, zbudi, obleci moč, o rama Gospodova! Zbudi se kakor v starih časih, pri nekdanjih rodovih! Ali nisi ti tista, ki je razdrobila Egipt, ki je presunila morskega velikana?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 10, 'Ali nisi ti tista, ki je posušila morje, velikega brezna vode, ki je naredila morske globočine za pot, po katerem naj preidejo odkupljeni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 11, 'In odrešenci Gospodovi se vrnejo ter pridejo na Sion s petjem, in večna radost bode nad njih glavo; veselje in radost jih objame, a žalovanje in zdihovanje pobegne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 12, 'Jaz, jaz sam sem tolažitelj vaš. Kdo si ti, da se bojiš človeka, ki umrje, in sina človekovega, ki izgine kakor seno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 13, 'in da zabiš Gospoda, stvarnika svojega, ki je razpel nebo in ustanovil zemljo, in si v strahu vedno, vsak dan, zaradi togote stiskalčeve, ko se pripravlja, da bi pogubil? In kje je togota stiskalčeva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 14, 'Hitro bo izpeljan v prostost tisti, ki je sključen v okovih, in ne umre in ne pade v jamo, tudi ne bo pogrešal kruha svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 15, 'Zakaj jaz sem Gospod, Bog tvoj, ki razburjam morje, da bučé njegovi valovi; Gospod nad vojskami je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 16, 'In položil sem besede svoje v usta tvoja in zakril sem te z roke svoje senco, da zgradim nebesa in ustanovim zemljo ter rečem Sionu: Ljudstvo si moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 17, 'Zbudi se, zbudi, vstani, jeruzalemska hči, ki si iz roke Gospodove pila togote njegove čašo; kupo, čašo omotno si pila, izsrebala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 18, 'Nikogar ni bilo, da bi jo bil vodil, izmed vseh otrok, ki jih je rodila, ne enega, ki bi jo bil prijel za roko, izmed vseh sinov, ki jih je vzredila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 19, 'Tisto dvoje se ti je prigodilo, kdo bi te miloval? –: razdejanje in podrtje, lakota in meč. Kako naj te potolažim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 20, 'Otroci tvoji so onemogli, leže po vseh ulicah in voglih kakor jelen v mreži; polni so togote Gospodove, grožnje Boga tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 21, 'Zato čuj vendar, o ponižana in pijana, a ne vina:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 22, 'Tako govori Gospod tvoj, Jehova, in Bog tvoj, ki se poteguje za pravdo ljudstva svojega: Glej, iz roke tvoje jemljem čašo omotno, čašo togote svoje: ne boš je več pila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 51, 23, 'Ampak dam jo v roko njih, ki te ponižujejo, ki so govorili duši tvoji: Vrzi se na tla, da pojdemo čeznjo! In ti si naredila kakor tla hrbet svoj in kakor cesto čezenj gredočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 1, 'Zbudi se, zbudi, obleci moč svojo, o Sion; obleci oblačila dike svoje, o Jeruzalem, sveto mesto! Kajti odslej ne stopi več v te neobrezani in nečisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 2, 'Otresi si prah, vstani, sedi, Jeruzalem; reši se vezi vratu svojega, o ujeta hči sionska!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 3, 'Kajti tako pravi Gospod: Brez plačila ste bili prodani in brez denarja boste odkupljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 4, 'Zakaj tako pravi Gospod Jehova: V Egipt doli je bilo šlo ljudstvo moje s početka, da bi tujčevalo tam, in Asirec ga je tlačil za nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 5, 'Sedaj pa, kaj mi je tukaj storiti? govori Gospod; kajti ljudstvo moje so na tuje vzeli brez plačila! gospodovalci njegovi ukajo, govori Gospod, in neprestano, ves dan je v zaničevanju ime moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 6, 'Zato bo ljudstvo moje spoznalo ime moje; zato spoznajo prav tisti dan, da sem jaz tisti, ki govori: Glej, tukaj sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 7, 'Kako lepe so na gorah noge blagovestnika, ki proglaša mir, oznanja blagovest o dobrem, proglaša zveličanje, ki govori Sionu: Bog tvoj kraljuje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 8, 'Glas ogledovalcev tvojih! Povzdigujejo glas, skupaj veselo pojo, kajti vidijo iz oči v oči, da pelje Gospod nazaj Sion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 9, 'Vdajte se radosti, skupaj pojte veselo, razvaline jeruzalemske! zakaj Gospod je potolažil ljudstvo svoje, odrešil Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 10, 'Razgalil je Gospod svetosti svoje ramo pred očmi vseh narodov, in vsi kraji zemlje bodo videli našega Boga zveličanje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 11, 'Odstopite, odstopite, idite odondod, ničesar nečistega se ne doteknite! Pojdite izsredi njega, očistite se vi, ki nosite posode Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 12, 'Kajti ne odidete v naglici in ne boste hodili begoma; ker Gospod bo hodil pred vami in zadnja straža vam bode Bog Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 13, 'Glej, hlapec moj bo modro ravnal; povzdigne se in vzviša, in visok bode silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 14, 'Kakor so o tebi osupnili mnogi (tako je bil obraz njegov spačen, bolj nego katerega moža, in podoba njegova bolj nego otrok človeških),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 52, 15, 'tako pripravi v strmenje mnogo narodov; zaradi njega si kralji zatisnejo usta. Zakaj videli bodo, kar jim ni bilo povedano, in česar niso čuli, bodo razumeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 1, 'Kdo je veroval oznanilu našemu in komu se je razodela rama Gospodova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 2, 'Kajti on je vzrastel kakor mladika pred njim in kakor korenina iz suhe zemlje. Ni imel podobe, ne lepote; in ko smo ga videli, ni imel mične zunanjosti, da bi si ga bili želeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 3, 'Zaničevan je bil in preziran med možmi, mož bolečin in izkušen v trpljenju, in kakor človek, pred katerim skrivajo obličje, je bil zaničevan, in nič ga nismo čislali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 4, 'Zares, on je nosil bolezni naše in si je naložil bolečine naše; mi pa ga smo šteli za kaznjenega, ki ga je Bog udaril in ponižal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 5, 'A on je bil ranjen zaradi naših prestopkov, je bil potrt zaradi naših krivic; kazen ga je zadela zaradi našega miru in rane njegove so bile nam v ozdravljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 6, 'Mi vsi smo tavali kakor ovce, obrnili smo se vsak na svoj pot; in Gospod mu je naložil nas vseh krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 7, 'Mučili so ga, a ponižal se je in ni odprl ust svojih kakor jagnje, ki ga peljejo v zakol, in kakor ovca, ki molči pred strižci svojimi; in ni odprl svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 8, 'Iz stiske in iz sodbe je bil vzet – a izmed njegovih vrstnikov kdo je pomislil, da je bil odrezan iz dežele živečih? zaradi prestopka ljudstva mojega ga je zadel udarec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 9, 'In dali so mu grob pri brezbožnih, a pri bogatinu je bil po mučni smrti svoji, zato ker ni storil krivice in ni bilo zvijače v ustih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 10, 'Ali Gospod ga je hotel streti, on ga je izročil trpljenju. Ko izvrši duša njegova daritev za greh, bo videl zarod, podaljšal dni svoje, in kar je Gospodu po volji, bo uspevalo v roki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 11, 'Od nadloge duše svoje bo videl sad in se sitil. S poznanjem svojim bo pravični hlapec moj mnoge storil pravične; in njih krivice bo naložil nase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 53, 12, 'Zato mu dam velike v delež in delil bo plen z mogočnimi; zato ker je žrtvoval dušo svojo v smrt in je bil grešnikom prištet; on je nesel greh mnogih in prosil za grešnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 1, 'Prepevaj, nerodovitna, ki nisi rodila; vdaj se radosti in glasno vpij, ki nisi trpela porodnih bolečin! zakaj več sinov bo imela zapuščena nego omožena, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 2, 'Razširi prostor šatora svojega in pregrinjala stanov tvojih naj raztegnejo, ne brani! Podaljšaj vrvi svoje in kole svoje pritrdi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 3, 'Kajti na desno in na levo prodereš in seme tvoje podeduje narode in opustošena mesta napolni z ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 4, 'Ne boj se, ker ne boš osramočena, in ne bodi oblita z nečastjo, ker ne prideš v sramoto; temuč sramoto mladosti svoje pozabiš in vdovstva svojega nečasti se ne boš več spominjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 5, 'Kajti soprog tvoj je on, ki te je ustvaril, Gospod nad vojskami je ime njegovo; in odrešenik tvoj je Svetnik Izraelov; Bog vse zemlje se bo imenoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 6, 'Zakaj kakor ženo zapuščeno, žalostno v srcu te pokliče Gospod, kakor ženo mladosti, ko je zavržena, pravi Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 7, 'Za kratek trenotek sem te bil zapustil, ali zberem te z usmiljenjem velikim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 8, 'v nekolikem srdu sem bil za trenotek skril obličje svoje pred teboj, ali v večni milosti se te usmilim, govori Gospod, odrešenik tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 9, 'Kajti kakor vode Noetove mi je to: kakor sem prisegel, da ne pridejo več vode Noetove na zemljo, tako sem prisegel, da se ne razsrdim zoper tebe in te ne pokaram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 10, 'Kajti gore se bodo pač umeknile in hribi se genili, a milost moja se ne umakne od tebe in miru mojega zaveza se ne gane, govori Gospod, milostnik tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 11, 'O ubožica, ki te preganjajo nevihte, ki nimaš tolažbe! glej, jaz položim kamene tvoje v svinčeni sijajnik in v podstavo ti denem safire;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 12, 'in iz rubina naredim line tvoje in vrata tvoja iz ognjencev in vso mejo tvojo iz milovidnih kamenov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 13, 'In vsi otroci tvoji bodo učenci Gospodovi in obilen mir bode otrokom tvojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 14, 'Po pravičnosti boš utrjena. Daleč se umakni bridkosti, ker se ti ni ničesar bati, in strahu, ker se ti ne bo bližal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 15, 'Glej, čeprav se zbirajo zoper tebe, to ni od mene; kdor se zbira zoper tebe, pade ob tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 16, 'Glej, jaz sem ustvaril kovača, ki piha v goreče oglje in nareja orodje za delo svoje; enako sem jaz ustvaril morilca, da pokončuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 54, 17, 'Nobeno orodje, narejeno zoper tebe, ne bo imelo uspeha, in sleherni jezik, ki se postavi zoper tebe na sodbo, obsodiš. To je dediščina hlapcev Gospodovih in njih pravičnost, ki prihaja od mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 1, 'Hej, vsi, katerikoli ste žejni, pridite k vodam, in kateri nimate denarja, pridite, kupite in jejte! Pridite, pravim, kupite brez denarja in brez plačila vina in mleka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 2, 'Čemu trošite denar za to, kar ni kruh, in trud svoj za to, kar ne more nasititi? Poslušajte vendar mene in jejte, kar je dobro, in tolstino veselo uživaj duša vaša!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 3, 'Nagnite uho in pridite k meni, poslušajte, in duša vaša bo živela! In sklenem z vami zavezo večno: milosti Davidove, stanovitne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 4, 'Glej, za pričo narodom sem ga postavil, za vojvodo in zapovednika narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 5, 'Glej, rod, ki ga nisi spoznal, pokličeš, in rodovi, ki te niso spoznali, priteko k tebi, zaradi Gospoda, Boga tvojega, in zavoljo Svetnika Izraelovega, ker te je oslavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 6, 'Iščite Gospoda, dokler ga morete najti, kličite ga, dokler je blizu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 7, 'Zapusti naj brezbožnik pot svoj in mož krivični misli svoje in povrni se h Gospodu, in usmilil se ga bo, in k Bogu našemu, ker je bogat v odpuščanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 8, 'Kajti misli moje niso vaše misli, tudi vaša pota niso moja pota, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 9, 'Marveč kakor so nebesa višja od zemlje, tako so pota moja višja nego vaša pota in misli moje nego vaše misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 10, 'Kajti kakor pada dež ali sneg z neba in se ne vrača tja, temuč napaja zemljo ter jo dela rodovitno, da iz nje raste, da daje seme sejalcu in lačnemu kruh:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 11, 'tako bode beseda moja, ki prihaja iz mojih ust: ne povrne se k meni prazna, temuč izvrši, kar me veseli, in bo uspeh imela v tem, za kar jo pošljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 12, 'Zakaj z radostjo izidete in z mirom vas bodo spremljali; gore in hribi zaženo pred vami radostno vpitje in vsa drevesa poljska bodo z rokami ploskala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 55, 13, 'Namesto grmovja zrastejo ciprese, namesto koprive vstane mirta: in bode Gospodu v slavno ime, v znamenje večno, ki se ne iztrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 1, 'Tako pravi Gospod: Pazite na pravico in strezite pravičnosti! kajti skoraj pride zveličanje moje in pravičnost moja se razodene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 2, 'Blagor človeku, ki dela to, in sinu človekovemu, ki se trdno drži tega: ki hrani soboto, da bi je ne oskrunil, in varuje roko svojo, da bi ne storil nič zlega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 3, 'Inozemec pa, ki se je pridružil Gospodu, naj ne govori, rekoč: Gospod me gotovo loči od svojega ljudstva; in skopljenec ne govóri: Glej, jaz sem suho drevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 4, 'Zakaj tako govori Gospod o skopljencih, ki spoštujejo sobote moje in volijo to, kar mene veseli, in trdno drže zavezo mojo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 5, 'njim dam v hiši svoji in sredi zidov svojih prostora in ime boljše mimo sinov in hčer; ime večno jim dam, ki se ne iztrebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 6, 'Inozemce pa, ki so se pridružili Gospodu, da mu strežejo in da ljubijo ime Gospodovo, da mu bodo hlapci: kdorkoli hrani soboto, da bi je ne oskrunil, in kateri trdno drže zavezo mojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 7, 'nje tudi pripeljem h gori svetosti svoje in jih razveselim v molitveni hiši svoji, njih žgalne in klalne daritve bodo prijetne na oltarju mojem. Kajti hiša moja se bo imenovala dom molitve vsem ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 8, 'Gospod Jehova, ki zbira razkropljence Izraelove, govori: Še druge bom zbral k njemu, k zbranim njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 9, 'Vse živali poljske, pridite jest, vsa živad v gozdu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 10, 'Njegovi čuvaji so slepi, vsi so brez spoznanja; kolikor jih je, so nemi psi, ki ne morejo lajati; sanjajoč ležé, ljubijo spanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 11, 'In tisti psi so požrešni, ne vedo, kdaj so siti; in to so pastirji! Niso zmožni kaj razumeti, vsi se obračajo na svojo pot, vsak se žene za svojim dobičkom od vseh strani:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 56, 12, '„Pridite, vina vzamem, in izpirali si bomo grlo s pijačo opojno; in jutrišnji dan bodi današnjemu podoben in še veliko boljši!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 1, 'Pravični gine, a nihče ne premisli v srcu, in z milostjo obdarovane pobira smrt, a nihče se ne zmeni, da se izpred nesreče pobira pravični.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 2, 'V pokoj gre pravični; počivajo na ležiščih svojih, katerikoli hodijo v poštenosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 3, 'Vi pa, približajte se, vražarice otroci, prešeštnika in nečistnice zarod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 4, 'Zoper koga se razveseljujete? komu se režite in kažete jezik? Ali niste rojeni v grehu, niste li seme lažnivo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 5, 'ki se razvnemate za malike pod slehernim drevesom zelenečim, ki koljete otročiče po dolinah, pod skalnimi razpokami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 6, 'Med gladkimi kameni v potoku je tvoj del, nečistnica; oni, oni so delež tvoj; tudi njim si izlivala pitno daritev, darovala jedilno daritev. Ali naj se za to potolažim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 7, 'Na visoki, vzvišeni gori si napravila ležišče svoje; tudi si hodila tja gori opravljat daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 8, 'In za vrati in za podbojem si postavila spomenik svoj. Kajti izneverila si se meni in si šla gori razkrit se, razširila si ležišče svoje in izgovorila sebi plačilo od njih; rada si se družila ž njimi, ozirala se po njih migljaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 9, 'In hodila si h kralju z oljem in mnogo si rabila dišeča mazila, in pošiljala si poslance svoje daleč in se poniževala prav do pekla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 10, 'Na svojih mnogih potih si bila trudna, a nisi rekla: Zaman je! Poživila se je moč tvoja, zato nisi opešala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 11, 'In koga si se plašila in bala, da si se lagala in se nisi spominjala mene, ne premislila tega v srcu? Nisem li jaz molčal, in to od nekdaj? in mene se nisi bala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 12, 'Jaz razglasim pravičnost tvojo in dela tvoja, nič ti ne bodo koristila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 13, 'Ko boš vpila, naj te rešijo zbrani maliki tvoji! toda nje vse pobere veter, sapa jih odnese. Kdor pa se zateka k meni, dobi deželo v last in podeduje goro svetosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 14, 'In govorili bodo: Nasipajte, nasipajte, napravite pot, odpravite vsako spotiko s pota ljudstva mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 15, 'Zakaj tako pravi Visoki in Vzvišeni, ki prebiva v večnosti in ki mu je ime Sveti: Na višavi in v svetišču prebivam, tudi ž njim, ki je potrtega in ponižanega duha, da oživim duha ponižanih in oživim srce potrtih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 16, 'Kajti vekomaj se ne bom prepiral in brezkončno se ne srdil, ker bi njih duh onemogel pred obličjem mojim in duše, ki jih sem jaz ustvaril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 17, 'Zaradi krivične dobičkoželjnosti njegove sem se razsrdil in ga udaril, skril sem se in se srdil; on pa se je tem bolj odvrnil po srca svojega potu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 18, 'Pota njegova vidim, ali ozdravim ga; in vodil ga bom in dajal tolažbe njemu in žalujočim njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 19, 'Ustvarjam sad ustnic: Mir, mir njemu, ki je daleč, in njemu, ki je blizu, pravi Gospod; in hočem ga ozdraviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 20, 'Brezbožni pa so kakor morje razdraženo: mirovati ne more in vode njegove izmetavajo blato in nesnago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 57, 21, 'Ni ga miru, pravi Bog moj, brezbožnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 1, 'Vpij iz vsega grla, ne prenehaj! kakor tromba povzdigni glas svoj in oznanjaj ljudstvu mojemu njih pregreho in hiši Jakobovi njih grehe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 2, 'Iščejo me pač vsak dan in žele znati pota moja kakor narod, ki streže pravičnosti in ni zapustil pravice Boga svojega; vprašujejo me po pravičnih naredbah, žele, da bi se jim Bog približal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 3, '„Zakaj se postimo, in ti ne vidiš? ponižujemo dušo svojo, in se ne zmeniš za to?“Glejte, tisti dan, ko se postite, iščete, kar vam je v veselje, in pritiskate vse delavce svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 4, 'Glejte, postite se, da bi se pravdali in prepirali in da bi tepli s krivično pestjo. Ne postite se dandanašnji, da bi se slišal glas vaš na višavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 5, 'Ali je tak post, kakršnega volim? dan, ko človek muči dušo svojo? Pripogibati kakor bičje glavo svojo in postlati si ležišče z raševnikom in pepelom: ali boš to imenoval post in dan po volji Gospodu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 6, 'Ali ni to post, kakršnega volim: da razrešite krivičnosti spone, da snamete sužnji jarem ter oprostite tlačene in razbijete sleherni jarem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 7, 'Ne li, da deliš lačnemu kruh svoj in da siromake izgnane pripelješ domov? ko vidiš nagega, da ga pokriješ, in se ne skrivaš pred sorodnim mesom svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 8, 'Tedaj napoči kakor zarja svetloba tvoja in zdajci zacvete zdravje tvoje, in pred teboj pojde pravičnost tvoja, slava Gospodova bode zadnja straža tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 9, 'Tedaj boš klical, in Gospod te usliši, vpil boš, in odgovori ti: Glej, tu sem! Ako odpraviš izmed sebe jarem, iztezanje prsta v zasmeh in ničemurno govorjenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 10, 'podeliš pa gladnemu iz srca svojega in nasitiš dušo potrto: tedaj prisije v temi svetloba tvoja in temina tvoja postane kakor poldan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 11, 'In Gospod te bo vodil vedno in v najhujši suši ti bo sitil srce in kosti tvoje naredil čile; in bodeš kakor namočen vrt in kakor vrelec vodá, ki se nikdar ne posuše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 12, 'In kateri so od tebe, sezidajo stare razvaline: podstave prejšnjih rodov postaviš zopet, in imenoval se boš Zagrajevalec vrzeli, Popravljalec cest v prebivanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 13, 'Če obrneš od sobote nogo svojo, da ne boš delal, kar te veseli, v sveti dan moj, in boš soboto imenoval naslado, sveti dan Gospodov častitljiv, in če ga boš častil, ne hodeč po svojih potih, ne delajoč, kar te veseli, in ne govoreč praznih besed:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 58, 14, 'tedaj se boš razveseljeval v Gospodu, in dam ti, da boš jezdil po višinah zemlje, in storim, da boš užival dediščino Jakoba, očeta svojega; zakaj usta Gospodova so govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 1, 'Glejte, ni prekratka roka Gospodova, da ne more rešiti, tudi uho njegovo ni gluho, da ne more slišati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 2, 'ali krivice vaše so postale pregrada med vami in Bogom vašim, in grehi vaši so zagrnili obličje njegovo pred vami, da ne sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 3, 'Zakaj roke vaše so oskrunjene s krvjo in prsti vaši s krivico, ustne vaše govore laži, jezik vaš golči krivičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 4, 'Nihče ne kliče po pravičnosti in nihče se ne poteguje za pravdo v resnici; stavijo up na ničemurnost in govore laž, spočenjajo nadlogo in rode zlobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 5, 'Jajca modrasova vale in pajčevine tko; kdor jé njih jajca, umre, in če se katero stare, skoči iz njega gad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 6, 'Njih tkanina ni za obleko in ni se mogoče odevati ž njih izdelki: njih dejanja so dejanja krivična in delo silovitosti je v njih rokah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 7, 'Njih noge teko k hudemu in hite prelivat kri nedolžno; njih misli se pečajo z zlobo; razdevanje in podiranje je na njih cestah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 8, 'Pota miru ne poznajo in nobene pravice ni po njih sledovih; steze svoje si kvarijo: kdorkoli stopi na katero izmed njih, nima miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 9, 'Zato je daleč od nas pravica in pravičnost ne prihaja do nas. Čakamo svetlobe, a glej: le tema! čakamo jasnega svita, a hodimo po črni temini!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 10, 'Kakor slepci otipavamo steno, tavamo kakor brez oči; zadevamo se prav opoldne kakor ob mraku; med zdravimi smo kakor mrtvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 11, 'Renčimo vsi kakor medvedje, žalostno grulimo kakor golobje. Čakamo pravice, ali ni je, rešenja, a daleč je od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 12, 'Kajti pomnožile so se pregrehe naše pred teboj in grehi naši pričajo zoper nas; zakaj pregreh svojih smo si v svesti in krivice svoje poznamo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 13, 'da odpadamo od Gospoda in ga tajimo in se obračamo, da ne bi šli za Bogom svojim; zatiranje govorimo in odpad, sprejemamo v se besede lažnive in jih iz srca govorimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 14, 'Tako je odvrnjena pravica, in pravičnost stoji oddaleč; zakaj resnica je padla na ulicah in poštenost ne more vstopiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 15, 'In resnica je redka reč, in kdor se ogiblje hudega, je drugim v plen. To je videl Gospod, in hudo je bilo v očeh njegovih, da ni nikake pravice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 16, 'In videl je, da ni nobenega moža, in se je zavzel, da ni nobenega posrednika. Zato mu je rešitev napravila rama njegova, in pravičnost njegova, ta ga je podpirala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 17, 'In oblekel je pravičnost kakor oklep in dejal si čelado zveličanja na glavo; oblekel je, pravim, maščevanja oblačilo in ogrnil se je z gorečnostjo kakor s plaščem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 18, 'Prav po dejanjih, prav po njih bo povračal, togoto nasprotnikom svojim, kazen sovražnikom svojim; še otokom bo plačal povračilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 19, 'In bali se bodo od zahoda imena Gospodovega in slave njegove od solnčnega vzhoda. Ko se kakor reka privali sovražnik, ga dih Gospodov zapodi v beg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 20, 'In Sionu pride odrešenik in njim, ki se odvračajo od pregrehe v Jakobu, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 59, 21, 'Jaz pa – to je moja zaveza ž njimi, pravi Gospod: Duh moj, ki je nad teboj, in besede moje, ki sem jih položil v usta tvoja, se ne umaknejo iz tvojih ust, ne iz zaroda tvojega ust, ne iz ust potomcev tvojega zaroda, pravi Gospod, od tega časa vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 1, 'Vstani, svéti se, hči sionska! zakaj svetloba tvoja je prišla in slava Gospodova je zasijala nad teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 2, 'Kajti glej, tema pokriva zemljo in mrak narode; a nad teboj zasije Gospod in slava njegova bode očitna nad teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 3, 'In pridejo narodi k svetlobi tvoji in kralji k svitu, ki ti sije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 4, 'Povzdigni oči kroginkrog in poglej: vsi oni se zbirajo in prihajajo k tebi; sinovi tvoji gredo iz daljave in hčere tvoje prinašajo v naročju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 5, 'Tedaj boš videla in od veselja sijala, in srce ti bo močno utripalo in se širilo; zakaj obilnost morja se obrne do tebe, bogastvo narodov dospe k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 6, 'Velblodov roj te pokrije, dromedarji iz Madiana in Efe; vsi pridejo iz Sabe, zlata prineso in kadila in veselo bodo oznanjali slavna dela Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 7, 'Vse črede kedarske se bodo zbirale k tebi; ovni nebajotski ti bodo stregli; prišli bodo na moj oltar v blagougodje meni; in okrasil bom hišo dike svoje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 8, 'Kdo so oni, ki se zletavajo kakor gost oblak in kakor golobje k linam svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 9, 'Kajti mene bodo čakali otoki in tarsiške ladje najprej, da pripeljejo sinove tvoje iz daljave, srebro in zlato svoje s seboj, za ime Gospoda, Boga tvojega, in za Svetnika Izraelovega, ker te je odičil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 10, 'In zidali bodo tujci zidove tvoje in njih kralji ti bodo stregli; zakaj v srdu svojem sem te udaril, a v blagovoljnosti svoji sem se te usmilil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 11, 'In vrata tvoja bodo odprta neprestano, noč in dan se ne zapro, da pripeljejo k tebi bogastvo narodov ob spremstvu njih kraljev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 12, 'Kajti tisti narod in tisto kraljestvo, ki ti ne bo služilo, pogine, in ti narodi se popolnoma pokončajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 13, 'Slava libanonska dojde k tebi, ciprese, platane in zelenike skupno, dičit mesto svetišča mojega; in oslavim nog svojih mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 14, 'In pripognjeni pridejo k tebi sinovi tlačiteljev tvojih, in priklonijo se pred stopali nog tvojih vsi zaničevalci tvoji, in imenovali te bodo Mesto Gospodovo, Sion Svetnika Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 15, 'V odmeno, da si bila zapuščena in sovražena, da ni šel nihče skozi te, te napravim v lepoto večno, v veselje od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 16, 'Sesala boš tudi mleko narodov in prsi kraljev boš sesala, in spoznaš, da sem jaz, Gospod, tvoj Zveličar in jaz, Mogočni Jakobov, tvoj Odrešenik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 17, 'Namesto brona prinesem zlata in namesto železa pripeljem srebra in namesto lesa brona in železa namesto kamenja. In postavim ti za oblastvo mir in za upravništvo pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 18, 'Več ne bode slišati o silovitosti v deželi tvoji, o pustošenju in podiranju po pokrajinah tvojih; temuč imenovala boš obzidje svoje Zveličanje in vrata svoja Hvalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 19, 'Ne bode ti več solnce za svetlobo po dnevi in za svit nočni ti ne bo svetil mesec, marveč Gospod ti bode svetloba večna in Bog tvoj tebi za diko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 20, 'Ne zajde več solnce tvoje in mesec tvoj se ne skrije, zakaj Gospod ti bode svetloba večna. In konec bode žalovanja tvojega dnevom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 21, 'In ljudstvo tvoje – vsi bodo pravični, za vekomaj bodo podedovali deželo, kakor mladika, ki sem jo zasadil, rok mojih delo, meni v poveličanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 60, 22, 'Iz najmanjšega jih bode tisoč, iz šibkega mogočen narod. Jaz Gospod pospešim to ob svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 1, 'Duh Gospoda Jehove je nad mano, zato ker me je Gospod pomazilil, da naj oznanjam blagovestje krotkim; poslal me je obvezovat potrte v srcu, oznanjat svobodo jetnikom in zaprtim, da se jim odpira ječa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 2, 'da oklicujem milostno leto Gospodovo in dan maščevanja Boga našega, da tolažim vse žalujoče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 3, 'da poskrbim za žalujoče na Sionu in jim dam diko namesto pepela, olje veselja namesto žalosti, hvalni plašč namesto duha obupnega; da bi se imenovali hrasti pravičnosti, sadež Gospodov, njemu v poveličanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 4, 'In pozidajo stare razvaline in postavijo, kar je bilo v nekdanjih časih porušeno, ter obnove zapuščena mesta, pustišča mnogih rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 5, 'In tujci bodo stali in pasli črede vaše in inozemci bodo oratarji in vinogradniki vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 6, 'Vi pa se boste imenovali duhovniki Gospodovi, strežaje Boga našega vas bodo zvali. Uživali boste bogastvo narodov in ž njih slavo se ponašali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 7, 'Za svojo sramoto dobite dvojno; in namesto nečasti se bodo veselili svojega deleža; kajti dobodo v svoji deželi dvojno posest in veselje bodo imeli večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 8, 'Zakaj jaz, Gospod, ljubim pravico, sovražim zlobno plenjenje; in dam jim njih povračilo v resnici in večno zavezo sklenem ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 9, 'In znano bode med poganskimi narodi njih seme in njih rojenci med ljudstvi: vsi, ki jih bodo videli, pripoznajo, da so seme, ki ga je blagoslovil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 10, 'Veselil se bom, veselil v Gospodu, raduje se naj duša moja v Bogu svojem! Kajti odel me je z obleko zveličanja, s plaščem pravičnosti me ogrnil, kakor se ženin po duhovniško pokriva z vencem in kakor se nevesta diči z dragotinami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 61, 11, 'Kakor namreč zemlja rodi svoje rastline in kakor vrt poganja setev svojo, tako stori Gospod Jehova, da bo rasla pravičnost in hvala pred vsemi narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 1, 'Zavoljo Siona ne bom molčal in zaradi Jeruzalema ne bom miroval, dokler ne vzide kakor svit pravičnost njegova in zveličanje njegovo ne zagorí kakor plamenica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 2, 'In narodi bodo videli pravičnost tvojo in vsi kralji slavo tvojo, in imenovali te bodo z novim imenom, katero izreko usta Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 3, 'In prekrasen venec bodeš v roki Gospodovi in kraljevo naglavje v roki Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 4, 'Ne bodo ti več rekli: Zapuščenka! in deželi tvoji ne bodo več pravili Puščava, marveč imenovali te bodo: Hefziba in deželo tvojo: Beula; zakaj Gospod se bo radoval v tebi in dežela tvoja bo omožena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 5, 'Kajti kakor se poroči mladenič z devico, se poroče s teboj sinovi tvoji, in kakor se ženin veseli neveste, se bo veselil tebe Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 6, 'Na zidove tvoje, o Jeruzalem, sem postavil čuvaje; ves dan in vso noč ne bodo za trenotek molčali. Vi, ki spominjate Gospoda, ne privoščite si pokoja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 7, 'in ne dajajte Mu pokoja, dokler ne utrdi Jeruzalema in dokler ga ne napravi v hvalo na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 8, 'Prisegel je Gospod pri desnici svoji in pri rami moči svoje: Ne dam več žita tvojega za jed sovražnikom tvojim in inozemci ne bodo pili vina tvojega, za katero si se trudil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 9, 'Temuč kateri spravljajo žito, ga bodo jedli in hvalili Gospoda, in kateri zbirajo vino, ga bodo pili v vežah svetišča mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 10, 'Idite, idite skozi vrata! Pripravljajte ljudstvu pot! Nasipajte, nasipajte cesto, odpravljajte kamenje! Visoko povzdignite zastavo ljudstvom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 11, 'Glej, Gospod je razglasil prav do kraja zemlje: Povejte hčeri sionski: Glej, rešenje tvoje se bliža! glej, plačilo njegovo je pri njem in povračilo njegovo pred njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 62, 12, 'In imenovali jih bodo Sveto ljudstvo, Rešence Gospodove; in tebe bodo imenovali Mesto, ki po njem vsi vprašujejo, ki ne bo več zapuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 1, 'Kdo je ta, ki prihaja od Edoma, v rdeče pobarvani obleki iz Bozre? Krasen je v svoji obleki, ponosno stopa v obili moči svoji! – Jaz sem, ki govorim v pravičnosti, premogočen za rešenje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 2, 'Zakaj si rdeč po obleki in oblačila tvoja kakor njega, ki tlači v tlačilnici? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 3, 'Tlačil sem v tlačilnici sam, in izmed ljudstev ni bilo nikogar z menoj; zatorej sem jih teptal v jezi svoji in jih gazil v togoti svoji, da se je ž njih životnim sokom oškropila obleka moja in sem si vsa oblačila omadeževal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 4, 'Zakaj dan maščevanja je bil v srcu mojem in moje leto odrešenja je prišlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 5, 'In oziral sem se, a ni bilo nobenega pomočnika, in strmel sem, da ni nikogar, ki bi podpiral. Tedaj mi je rešenje prinesla rama moja, in togota moja, ta me je podpirala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 6, 'In teptal sem ljudstva v jezi svoji in sem jih upijanil v togoti svoji, in njih životni sok sem izlil na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 7, 'Milosti Gospodovih se bom hvalno spominjal, slavnih del Gospodovih, po vsem, kar nam je podelil Gospod, in obilne dobrote hiši Izraelovi, ki jim jo je izkazal po usmiljenju svojem in po obilosti milosti svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 8, 'Kajti rekel je: Res, ljudstvo moje so, sinovi, ki ne bodo ravnali lažnivo. Torej jim je bil rešitelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 9, 'V vsej njih stiski je bil sam stiskan, in angel obličja njegovega jih je reševal. V svoji ljubezni in usmiljenosti jih je odkupil sam in dvignil jih je nase ter jih nosil vse dni nekdanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 10, 'Ali oni so se uprli in žalili duha svetosti njegove; zato se jim je izpremenil v sovražnika, sam se je boril proti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 11, 'Tedaj se je spominjalo ljudstvo njegovo dni nekdanjih, dni Mojzesovih: Kje je, ki jih je izpeljal z morja s pastirji črede svoje vred? Kje je, ki je mednje dal duha svetosti svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 12, 'ki jih je spremljal Mojzesu na desnici z veličastno ramo svojo? ki je razklal vode pred njimi, da bi si napravil ime večno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 13, 'ki jih je vodil skozi globočine kakor konja po puščavi, da se niso spoteknili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 14, 'Kakor žival stopa nazaj v dolino, jih je peljal duh Gospodov v pokoj: tako si vodil ljudstvo svoje, da si napraviš ime veličastno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 15, 'Ozri se iz nebes in poglej iz prebivališča svetosti in veličasti svoje! kje je gorečnost tvoja in kje mogočna dela tvoja? Nagib svojega srca in svojo usmiljenost zadržuješ meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 16, 'Saj ti si oče naš; kajti Abraham ne ve za nas in Izrael nas ne pozna, ti, o Gospod, si oče naš; odrešenik naš od vekomaj ti je ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 17, 'Zakaj pripuščaš, o Gospod, da zahajamo od potov tvojih, zakaj si nam zakrknil srce, da se te ne bojimo? Vrni se k nam zaradi hlapcev svojih, zavoljo rodov dediščine svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 18, 'Le malo časa jo je imelo v posesti ljudstvo svetosti tvoje: sovražniki naši so razteptali svetišče tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 63, 19, 'Postali smo kakor tisti, ki jim nikoli nisi gospodoval, ki se niso imenovali po tvojem imenu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 1, 'O da bi predrl nebesa in prišel doli, da bi se od obličja tvojega raztopile gore');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 2, '(kakor ogenj požiga protje in voda vre od ognja), da oznaniš ime svoje nasprotnikom svojim, da bi strepetali narodi pred obličjem tvojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 3, 's tem, da delaš strahovite reči, ki jih nismo pričakovali; o da stopiš doli, da bi se od obličja tvojega raztopile gore!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 4, 'Zakaj od veka se ni slišalo, nikdar niso čula ušesa, tudi oko ni videlo Boga razen tebe, ki bi toliko delal za njega, ki ga čaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 5, 'Naproti prihajaš njemu, ki se veseli pravičnosti in ji streže, njim, ki se spominjajo tebe na potih svojih. Glej, ti si se srdil, in mi smo grešili; v tem smo že dolgo časa, bomo li rešeni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 6, 'In vsi vkup smo postali kakor neznažnik in vse pravičnosti naše so kakor umazana cunja; in venemo kakor listje, kolikorkoli nas je in krivice naše nas odnašajo kakor veter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 7, 'In ni ga, ki bi klical ime tvoje, ki bi se zbudil, da se poprime tebe; kajti skril si obličje svoje pred nami in nas izročil oblasti krivic naših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 8, 'Ali sedaj, o Gospod, ti si oče naš; mi smo glina, ti pa si nam lončar, in vsi smo tvoje roke delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 9, 'Ne togóti se, o Gospod, presilno in ne spominjaj se vekomaj krivice! Glej, ozri se na nas, prosimo, mi vsi smo ljudstvo tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 10, 'Mesta svetosti tvoje so puščava, Sion je puščava, Jeruzalem je pustinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 11, 'Sveta in prekrasna hiša naša, ki so te v njej hvalili očetje naši, je požgana z ognjem in vse, kar nam je bilo dragoceno, je v razvalinah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 64, 12, 'Hočeš li, o Gospod, ob toliki revi v sebi zadržavati usmiljenje, boš li molčal in nas tepel presilno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 1, 'Dal sem se iskati njim, ki niso po meni vpraševali; dal sem se najti njim, ki me niso iskali. Narodu, ki se ni imenoval po mojem imenu, sem rekel: Tu sem, tu sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 2, 'Iztezal sem roke svoje ves dan k ljudstvu upornemu, ki hodijo po svojih mislih, po potu, ki ni dober,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 3, 'k ljudstvu, ki me vedno dražijo v lice s tem, da darujejo po vrtih in žgo kadilo na opeki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 4, 'ki sede med grobovi in prenočujejo v skritih krajih, ki jedo meso svinjsko in imajo juho od gnusnega mesa v posodah svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 5, 'ki govore: Ostani zase, meni se ne približaj, ker svetejši sem od tebe: ti so dim v mojem nosu, ogenj, goreč ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 6, 'Glej, pisano je to pred menoj. Ne bom molčal, ako ne povrnem; da, povrnem njim v nedrje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 7, 'krivice vaše in očetov vaših krivice vkup, pravi Gospod, ki so kadilo žgali na gorah in me sramotili na gričih; zatorej odmerim najprej njih plačilo njim v nedrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 8, 'Tako pravi Gospod: Kakor se reče o grozdu, če je soka v njem: Ne pogúbi ga, ker je blagoslov v njem: tako hočem storiti zaradi hlapcev svojih, da ne pogubim vsega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 9, 'In storim, da pride seme iz Jakoba in iz Jude dedič mojih gorá; in izvoljenci moji bodo podedovali deželo in hlapci moji bodo prebivali ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 10, 'In Saron bode pašnik čredam in dolina Ahor ležišče govedi za ljudstvo moje, ki me je iskalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 11, 'Vi pa, ki zapuščate Gospoda, ki zabite goro svetosti moje, ki pripravljate mizo Sreči in natakate pitne dari Usodi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 12, 'vas sem prisodil meču, da se morate vsi pripogniti v zakol, zato ker mi niste odgovorili, ko sem klical, in niste poslušali, ko sem govoril, temuč ste delali, kar je hudo v mojih očeh, in ste izvolili, kar mi ni po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 13, 'Zatorej pravi tako Gospod Jehova: Glej, hlapci moji bodo jedli, vi pa boste lačni; glej, hlapci moji bodo pili, vi pa boste žejni; glej, hlapci moji se bodo veselili, vi pa se boste sramovali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 14, 'glej, hlapci moji bodo peli od srčnega veselja, vi pa boste kričali od srčne bolečine in tulili od dušne bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 15, 'In zapustite ime svoje v kletvico izvoljencem mojim; in s smrtjo te udari Gospod Jehova. Hlapcem svojim pa da drugo ime,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 16, 'da se bo blagoslavljal v Bogu resnice, kdor se hoče blagoslavljati na zemlji, in bo prisegel pri Bogu resnice, kdor se hoče blagoslavljati na zemlji, in bo prisegel pri Bogu resnice, kdor hoče prisegati na zemlji; kajti pozabijo se stiske prejšnje in bodo skrite pred očmi mojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 17, 'Zakaj, glej, jaz ustvarjam nova nebesa in zemljo novo, in o prejšnjem ne bode spomina in ne pride več na misel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 18, 'Ali veselite in radujte se vekomaj tega, kar jaz ustvarjam. Zakaj, glejte, jaz preustvarjam Jeruzalem v radost in ljudstvo njegovo v veselje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 19, 'In radoval se bom nad Jeruzalemom in veselil se ljudstva svojega, in ne bo se več čul v njem joka glas, ne vpitja glas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 20, 'Ne bode odondod več otroka, ki bi živel le malo dni, ne starca, ki bi ne dopolnil svojih dni; kajti kdor umre stoleten, bode še mladenič, a grešnik, sto let star, bo proklet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 21, 'In zidali bodo hiše ter v njih prebivali, in sadili vinograde in jedli njih sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 22, 'Ne bodo zidali, kdo drugi pa prebival, ne bodo sadili, kdo drugi pa užival; zakaj kakor so dnevi drevesa, bodo ljudstva mojega dnevi, in rok svojih delo bodo dolgo uživali izvoljenci moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 23, 'Trudili se ne bodo brezuspešno in rodili ne bodo otrok za naglo smrt; kajti seme bodo blagoslovljenih od Gospoda in njih zarod ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 24, 'In zgodi se, da odgovorim, preden bodo klicali; ko bodo še govorili, jih uslišim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 65, 25, 'Volk in jagnje se bosta pasla skupaj in lev bo slamo grizel kakor vol, kači pa bode prah hrana. Ne bodo delali škode, ne pogubno ravnali po vsej gori svetosti moje, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 1, 'Tako pravi Gospod: Nebo je prestol moj in zemlja nogam mojim podnožje. Kakšna bi neki bila hiša, ki bi jo mi zidali? in kje li počivanju mojemu mesto?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 2, 'Saj vse to je naredila roka moja in po njej je vse to postalo, govori Gospod. Ali na tega se ozrem: na ubožca in potrtega v duhu in na njega, ki trepeče pred besedo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 3, 'Kdor kolje vola, je, kakor kdor ubija moža, kdor daruje drobnico, kakor kdor seče glavo psu, kdor prinaša pitni dar, kakor bi daroval kri svinjsko, kdor žge kadilo v spomin, kakor kdor hvali malika: res, oni so izvolili pota svoja in gnusob svojih se veseli njih duša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 4, 'Tudi jaz izvolim, kar jih boli, in pripeljem nadnje, česar jih je strah; zato ker mi, ko sem klical, ni nihče odgovoril, ko sem govoril, niso poslušali, temuč so delali, kar je hudo v očeh mojih, in so izvolili tisto, kar mi ni po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 5, 'Čujte besedo Gospodovo, ki trepetate pred besedo njegovo! Bratje vaši, ki vas sovražijo in vas pehajo od sebe zaradi imena mojega, govore: Naj se Gospod izkaže častit, da vidimo radost vašo! Toda osramočeni bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 6, 'Čujte, hrupa glas iz mesta! glas iz svetišča! glas Gospodov, ki povrača sovražnikom svojim, kar so zaslužili!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 7, 'Ko je niso še obšle porodne težave, je rodila; ko je ni še napadla bolečina, je povila moško dete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 8, 'Kdo je slišal kaj takega, kdo je videl kaj enakega? More li dežela biti rojena v enem dnevi? se li porodi narod mahoma? Komaj so Sion obšle težave, in že je rodil sinove svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 9, 'Ali bi jaz odprl maternico, a ne dal poroditi? pravi Gospod; ali bi jaz, ki dajem roditi, zopet zadržal? veli Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 10, 'Veselite se z Jeruzalemom in radujte se nad njim vsi, ki ga ljubite, udeležujte se veselja ž njim, ki ste žalovali nad njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 11, 'da sesate in se nasitite na prsih tolažb njegovih, da se nasrkate in se vam dobro godi od obilnosti slave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 12, 'Kajti tako pravi Gospod: Glej, jaz napeljem proti njemu kakor reko mir in kakor poplavljajoč potok slavo narodov, in boste sesali; v naročjih vas bodo nosili in na kolenih ljubkali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 13, 'Kakor če koga tolaži mati njegova, tako hočem jaz tolažiti vas; in v Jeruzalemu boste obliti s tolažbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 14, 'In boste videli, in veselilo se bo srce vaše, in kosti vaše se razcveto kako nežna trava. In očitna bo roka Gospodova pri hlapcih njegovih in nevolja proti sovražnikom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 15, 'Zakaj, glej, Gospod pride z ognjem in vozovi njegovi bodo podobni vrtincu, da povračuje jezo svojo s togoto in karanje svoje z gorečimi plameni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 16, 'Kajti Gospod bo sodbo vršil z ognjem in z mečem svojim proti vsemu mesu, in mnogo jih bode, ki jih prebode Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 17, 'Kateri se posvečujejo in se očiščajo za malikovanje na vrtih, za enim v sredi, kateri jedo meso svinjsko, gnusobo in miši, skup se pokončajo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 18, 'Jaz pa vem njih dela, njih misli. Pride čas, da zberem vse narode in jezike; in pridejo in bodo gledali slavo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 19, 'In postavim znamenje med njimi, in izmed njih ubežnikov pošljem k narodom v Tarsis, Pul in Lud, ki streljajo z lokom, v Tubal in Javan, na daljne otoke, ki niso slišali vesti o meni in niso videli slave moje; in oznanjali bodo slavo mojo med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 20, 'In pripeljejo vse brate vaše izmed vseh narodov v dar Gospodu na konjih, na vozeh in nosilih, na mezgih in dromedarjih na goro svetosti moje, v Jeruzalem, pravi Gospod, kakor sinovi Izraelovi prinašajo pitno daritev v snažni posodi v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 21, 'In tudi izmed njih jih vzamem za duhovnike in levite, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 22, 'Zakaj kakor bodo ona nova nebesa in zemlja nova, ki jih hočem narediti, stala pred menoj, tako bo stalo seme vaše in ime vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 23, 'In zgodi se, da bo od mlaja do mlaja in od sobote prihajalo vse meso molit pred mene, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (23, 66, 24, 'In pojdejo ven in videli bodo mrtva trupla tistih ljudi, ki so odpadli od mene; zakaj njih črv ne umre in njih ogenj ne ugasne, in gnusoba bodo vsemu mesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 1, 'Besede Jeremija, Hilkijevega sina, izmed duhovnikov v Anatotu, v deželi Benjaminovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 2, 'ki mu je prišla beseda Gospodova v dnevih Josija, sinu Amonovega, v trinajstem letu njegovega kraljevanja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 3, 'prišla mu je tudi v dnevih Jojakima, sinu Josijevega, kralja Judovega, do konca enajstega leta Zedekija, sinu Josijevega, kralja Judovega, do dne, ko je bil Jeruzalem preseljen v ujetništvo, v petem mesecu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 4, 'Prišla mi je torej beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 5, 'Preden sem te bil upodobil v materinem telesu, sem te spoznal, in ko nisi bil še rojen, sem te posvetil, za proroka sem te postavil narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 6, 'Jaz sem pa rekel: Oh, Gospod Jehova, govoriti ne znam, ker otrok sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 7, 'Gospod pa mi je rekel: Ne pravi: Otrok sem; ampak kamorkoli te pošljem, pojdi, in karkoli ti velim, govóri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 8, 'Ne boj se jih; ker jaz sem s teboj, da te rešim, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 9, 'In Gospod iztegne roko svojo in se dotakne mojih ust, in Gospod mi reče: Glej, besede svoje pokladam v tvoja usta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 10, 'Glej, stavim te današnji dan nad narode in kraljestva, da iztrebljaš in podiraš in pogubljaš in pokončuješ, da zidaš in sadiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 11, 'In prišla mi je beseda Gospodova, rekoč: Kaj vidiš, Jeremija? in odgovorim: Palico mandljevo vidim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 12, 'Tedaj mi reče Gospod: Dobro vidiš; kajti čuval bom nad besedo svojo, da jo izpolnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 13, 'In prišla mi je beseda Gospodova v drugič, rekoč: Kaj vidiš? In odgovorim: Lonec kipeč vidim, ki mu lice gleda od severa sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 14, 'Tedaj mi reče Gospod: Od severa pridere tista nesreča nad vse prebivalce te dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 15, 'Kajti glej, jaz pokličem vse rodove kraljestev na severu, govori Gospod, in pridejo in postavijo vsak svoj stol ob vhodu v vrata jeruzalemska in zoper vse zidovje njegovo kroginkrog in zoper vsa mesta Judova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 16, 'In izrečem sodbe svoje zoper nje zavoljo vse njih hudobnosti, ker so me zapustili in kadili tujim bogovom in se klanjali delu svojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 17, 'Ti torej si opaši ledja in vstani in jim govóri, karkoli ti velim; ne bodi potrt vpričo njih, da te ne potrem vpričo njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 18, 'Kajti jaz, glej, te storim danes v trdno mesto in železen steber in bronast zid proti vsej deželi, proti kraljem, knezom in duhovnikom Judovim in proti ljudstvu dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 1, 19, 'In borili se bodo zoper tebe, ali premagali te ne bodo, kajti jaz sem s teboj, govori Gospod, da te rešim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 1, 'In prišla mi je beseda Gospodova, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 2, 'Pojdi in kliči Jeruzalemu na ušesa, govoreč: Tako pravi Gospod: Spominjam se ti milote mladosti tvoje, ljubezni zaročitve tvoje, ko si hodila za menoj po puščavi, po deželi, kjer ničesar ne sejejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 3, 'Svet je bil Izrael Gospodu, prvenec njegovih pridelkov; vsem, ki so ga hoteli žreti, se je štelo v krivdo: nesreča je prišla nadnje, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 4, 'Poslušajte besedo Gospodovo, hiša Jakobova in vse rodovine hiše Izraelove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 5, 'Tako pravi Gospod: kaj so našli očetje vaši krivice pri meni, da so se ločili od mene in so šli za ničemurnostjo in postali ničemurni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 6, 'In niso rekli: Kje je Gospod, ki nas je peljal iz dežele Egiptovske? ki nas je vodil po puščavi, po deželi pusti in jamnati, po deželi suše in smrtne sence, po deželi, koder ne hodi nihče in kjer ne prebiva noben človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 7, 'In pripeljal sem vas v deželo njiv, da bi uživali njen sad in dobroto njeno; ko ste pa prišli vanjo, ste oskrunili deželo mojo in dediščino mojo ste napravili v gnusobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 8, 'Duhovniki niso rekli: Kje je Gospod? In oni, ki imajo v rokah postavo, me niso spoznali, in pastirji so odpadli od mene, in proroki so prorokovali v imenu Baalovem in hodili za stvarmi, ki nič ne koristijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 9, 'Zato se bom še pravdal z vami, govori Gospod; še z otroki vaših otrok se bom pravdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 10, 'Pojdite vendar čez morje na otoke Kitimcev in poglejte, in pošljite v Kedar in pazite dobro, glejte pravim, se li je zgodilo kaj takega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 11, 'Ali je kateri narod zamenil bogove, čeprav niso bogovi? Ljudstvo moje pa je zamenilo slavo svojo za to, kar nič ne koristi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 12, 'Strmite, nebesa, nad tem in strah vas bodi, zgrozite se silno! govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 13, 'Zakaj dvoje zlo je storilo ljudstvo moje: mene, vir živih vodá, so zapustili, da si izkopljejo vodnjake, počene vodnjake, ki ne drže vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 14, 'Je li Izrael hlapec? ali je v hiši rojen suženj? Zakaj je v plen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 15, 'Zoper njega rjovejo mladi levi, zaganjajo svoj glas in pustošijo deželo njegovo; mesta njegova so požgana, da nihče ne prebiva v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 16, 'Tudi sinovi iz Nofa in Tahpanesa se ti pasejo po temenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 17, 'Nisi li sebi tega provzročila, ker si zapustila Gospoda, Boga svojega, ko te je vodil po svojem potu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 18, 'In zdaj, kaj si hočeš s potom v Egipt, da piješ vodo iz Sihorja? in kaj si hočeš s potom v Asirijo, da piješ vodo iz velereke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 19, 'Kaznuje te hudobnost tvoja in odpadi tvoji te pokoré; spoznaj torej in glej, kako je zlo in bridko, da si zapustila Gospoda, Boga svojega, in da se me nič ne bojiš, govori Gospod, Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 20, 'Kajti že nekdaj si zlomila jarem svoj, raztrgala vezi svoje in si dejala: Ne maram sužnjevati! Toda na vsakem hribu visokem, pod vsakim zelenim drevesom si se vdajala nečistovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 21, 'In vendar sem te bil jaz zasadil plemenito trto od pristne sadike; in kako si se mi izpremenila v spačene ročice tuje trte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 22, 'Res, ako bi se oprala s sodo in bi si vzela premnogo mila, ostane umazana krivica tvoja pred menoj, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 23, 'Kako smeš govoriti: Nisem se oskrunila, za Baali nisem hodila? Glej pot svoj po dolini, spoznaj, kaj si storila, kamela hitra, ki križem teka po svojih potih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 24, 'Divja oslica, vajena puščave, ki v poželenju duše svoje hlasta po sapi! Kdo bi oviral priložnost njeno? Vsi, ki je iščejo, se ne utrudijo, v mesecih njenih jo najdejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 25, 'Varuj nogo svojo, da se ne izbosi, in grlo svoje, da se ne užeja! Ali praviš: Zaman je! nikakor, kajti tujce ljubim in hočem za njimi tekati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 26, 'Kakor je v sramoto tatu, ko ga zgrabijo, tako je v sramoto prišla hiša Izraelova, oni, njih kralji in knezi, njih duhovniki in proroki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 27, 'ki pravijo lesu: Oče si moj, in kamenu: Ti si me rodil. Kajti obrnili so proti meni tilnik, ne pa obličja; ob času nesreče svoje pa govore: Vstani in reši nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 28, 'Kje neki so bogovi tvoji, ki si jih naredil sebi? Vstanejo naj, če te morejo rešiti ob času nesreče tvoje! Kajti kolikor mest, toliko bogov imaš, Juda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 29, 'Zakaj se prepirate z menoj? Saj ste se mi vsi izneverili, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 30, 'Zastonj sem tepel sinove vaše, nauka niso sprejeli; vaš meč je pokončal proroke vaše kakor lev morilec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 31, 'O rod, kakršen ste, pazite na besedo Gospodovo! ali sem bil puščava Izraelu, ali dežela črne teme? Zakaj govori ljudstvo moje: Gospodarji smo sami sebi, ne pridemo več k tebi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 32, 'Ali pozabi devica lepotičje svoje in nevesta svoj pas? Ljudstvo moje pa je pozabilo mene dni brez števila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 33, 'Kako lepo napravljaš pot svojo, da iščeš ljubezni! Zato si se tudi navadila hudobnosti na potih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 34, 'Celo na robu oblačil tvojih je kri duš nedolžnih ubožcev, ki jih nisi zalotila pri vlomu, ampak vsled vse tiste zlobe svoje si jih morila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 35, 'Vendar praviš: Nedolžna sem; gotovo se je obrnila jeza njegova od mene. Glej, jaz pojdem v sodbo s teboj zato, ker praviš: Nisem grešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 36, 'Kaj toliko tekaš, da premeniš pot svojo? Tudi zavoljo Egipta se ti bode sramovati, kakor si bila osramočena zavoljo Asirije;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 2, 37, 'tudi od tega pojdeš, položivši roke na glavo svojo. Zakaj Gospod zameta nje, na katere se zanašaš, in ne pojde ti po sreči ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 1, 'Rekel je Gospod: Ako bi kdo odslovil ženo svojo in ona bi šla od njega in se omožila z drugim, ali bi se povrnil zopet k njej? Ali bi se s tem silno ne oskrunila tista dežela? Ti pa, čeprav si nečistovala z mnogimi prijatelji, se vendar povrni k meni! govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 2, 'Povzdigni oči tja na gole višine in glej: Kje nisi bila oskrunjena? Poleg potov si jim sedela kakor Arabec v puščavi, in omadeževala si deželo z nečistovanjem svojim in s svojo hudobnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 3, 'Zaradi tega se je zadrževalo deževje in ni bilo poznega dežja; toda ti si imela čelo kurbje in nisi hotela zardeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 4, 'Ne boš li vsaj od tega časa me klicala: Oče moj, voditelj mladosti moje si ti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 5, 'Ali hoče jezo hraniti vekomaj, jo li bo hranil brez konca? Glej, tako govoriš, pa delaš hudo in se ne daš braniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 6, 'Rekel mi je še Gospod v dnevih kralja Josija: Ali si videl, kaj je storila odpadnica Izrael? Šla je na vsako visoko goro in pod vsako zeleno drevo, in ondi je nečistovala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 7, 'In rekel sem: Ko je storila vse to, se povrne k meni. A ni se povrnila. In to je videla nezvesta sestra njena Juda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 8, 'In videl sem: čeprav sem odslovil odpadnico Izrael, ker je prešeštvovala, in ji dal ločitno pismo, vendar se ni bala nezvesta sestra njena Juda, ampak šla je in nečistovala tudi ona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 9, 'In tako je prišlo, da je od glasu nečistovanja svojega oskrunila deželo; in prešeštvovala je s kamenom in lesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 10, 'In vendar po vsem tem se ni povrnila k meni nezvesta njena sestra Juda iz vsega srca svojega, ampak samo lažnivo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 11, 'In rekel mi je Gospod: Odpadnica Izrael se je pravičnejša izkazala nego nezvesta Juda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 12, 'Pojdi oznanjat te besede proti severu, govoreč: Vrni se, odpadnica Izrael, govori Gospod; ne bom vas jezno gledal, kajti dobrotljiv sem, govori Gospod, ne držim jeze vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 13, 'Samo spoznaj krivico svojo, da si odpadla od Gospoda, Boga svojega, in na vse strani si tekala k tujcem pod vsako zeleno drevo, in glasu mojega niste poslušali, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 14, 'Povrnite se, sinovi verolomni, pravi Gospod, kajti jaz sem vam soprog; in sprejmem vas, po enega iz mest in po dva iz rodbin, in vas pripeljem na Sion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 15, 'In dam vam pastirjev po svojem srcu, in pasli vas bodo z vednostjo in razumnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 16, 'In zgodi se, ko se boste množili in bodete rodovitni v tej deželi v tistih časih, govori Gospod, ne bodo več pravili: „Skrinja zaveze Gospodove “, in ne pride jim na misel, ne bodo se je spominjali, ne je obiskovali, tudi je ne bodo več napravljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 17, 'Tisti čas bodo Jeruzalem imenovali prestol Gospodov, in tja se bodo zbirali vsi poganski narodi zaradi imena Gospodovega v Jeruzalemu; in ne bodo več hodili po trmi hudobnega srca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 18, 'V tistih dnevih pojde hiša Judova s hišo Izraelovo; skupaj prideta iz dežele severne v deželo, ki sem jo v dediščino dal očetom vašim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 19, 'Jaz pa sem rekel: Kako te hočem postaviti med sinove in ti dati deželo zaželjeno, dediščino, ki je najlepša lepota narodov! In dejal sem: Kličite me: Oče moj! in hodeč za menoj, ne krenete od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 20, 'Res, kakor ženska nezvesto zapušča prijatelja svojega, tako ste nezvesto ravnali proti meni, o hiša Izraelova, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 21, 'Glas se čuje po golih višinah, jok in moledovanje sinov Izraelovih, zato ker so spačili svojo pot, pozabili Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 22, 'Povrnite se, sinovi verolomni, poravnal bom nezvestobe vaše. „Glej, prihajamo k tebi, ker ti si Gospod, naš Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 23, 'Res, le v prevaro je pomoč, ki je čakamo s hribov, hrup množice na gorah; gotovo v Gospodu, Bogu našem je rešenje Izraelovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 24, 'Kajti tista sramota požira trud očetov naših od naše mladosti, njih drobnico in goveda, njih sinove in hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 3, 25, 'Ležati nam je v sramoti svoji in nečast naša nas pokriva, zakaj grešili smo zoper Gospoda, Boga svojega, mi in očetje naši, od svoje mladosti prav do današnjega dne; in poslušali nismo glasu Gospoda, Boga našega.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 1, 'Če se hočeš povrniti, Izrael, govori Gospod, povrni se k meni! In če odpraviš gnusobe svoje izpred mojega obličja in ne boš begal za maliki');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 2, 'in boš prisegal: Kakor živi Gospod! v resnici, pošteno in pravično: tedaj se bodo v Njem blagrovali narodi in se ž Njim hvalili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 3, 'Kajti tako pravi Gospod možem Judovim in Jeruzalemcem: Orjite si novino in ne sejte med trnje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 4, 'Obrežite se Gospodu in odpravite kožico srca svojega, možje Judovi in prebivalci v Jeruzalemu, da ne izide kakor ogenj jeza moja in ne gori tako, da je ne pogasi nihče, zavoljo hudobnosti vaših del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 5, 'Oznanjujte na Judovem in v Jeruzalemu proglašajte in govorite: Trobite s trobento v deželi! glasno kličite in recite: Zberite se in pojdimo v utrjena mesta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 6, 'Povzdignite zastavo proti Sionu, bežite na varno, na postajajte! zakaj nesrečo hočem pripeljati od severa in stisko veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 7, 'Lev izhaja iz goščave svoje, in ubijalec narodov prihaja, gre iz kraja svojega, da pripravi deželo tvojo v pustinjo, da se razdenejo mesta tvoja in ne bo nihče prebival v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 8, 'Zatorej se opašite z raševino, jokajte in tulite; kajti ni se obrnila goreča jeza Gospodova od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 9, 'Zgodi se namreč tisti dan, govori Gospod, da upade srce kralju in srce knezom, in od straha ostrme duhovniki in otrpnejo proroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 10, 'Tedaj sem rekel: Oh, Gospod, Jehova! res si kar prekanil to ljudstvo in Jeruzalem, govoreč: Mir vam bode; in meč je zadel prav do duše! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 11, 'V tistem času se poreče temu ljudstvu in Jeruzalemu: Žgoč veter z golih višin v puščavi piše proti ljudstva mojega hčeri, ne da veja in ne da čisti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 12, 'veter močnejši nego za tisto mi pride. Sedaj izrečem tudi jaz sodbe nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 13, 'Glej, kakor oblak prihaja in kakor vrtinec so vozovi njegovi, hitrejši od orlov so konji njegovi. Gorje nam! ker smo opustošeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 14, 'Operi hudobnosti srce svoje, o Jeruzalem, da se rešiš! Doklej bodo v srcu tvojem prebivale hudobne misli tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 15, 'Kajti glas oznanja iz Dana in proglaša nesrečo z Efraimovih gorá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 16, 'Sporočite tistim narodom, glej, dajte, da se čuje nad Jeruzalemom: Oblegovalci gredo iz daljne dežele in zaganjajo svoj glas zoper mesta Judova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 17, 'kakor čuvaji na polju so razpostavljeni proti tebi. Zakaj Jeruzalem se je uprl zoper mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 18, 'Pota tvoja in dejanja tvoja so ti napravila tisto; to je nasledek hudobnosti tvoje; res, grenko je, res zbada srce tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 19, 'Osrčje moje, osrčje moje! Bolečino trpim v globini srca svojega! Razgraja mi srce moje! Molčati ne morem! Kajti trombe glas čuješ, duša moja, ropot vojske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 20, 'podiranje za podiranjem se oznanja. Zakaj opustošena je vsa dežela, naglo so razdejani šatori moji, bliskoma pregrinjala moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 21, 'Doklej naj gledam zastavo in poslušam trombe glas? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 22, 'Kajti nespametno je ljudstvo moje, mene ne poznajo; sinovi so neumni in brez razsodnosti. Modri so za huda dela, a nerodni storiti kaj dobrega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 23, 'Gledam na zemljo, in glej, pusta je in prazna, in na nebo, a ni luči na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 24, 'Gledam na gore, in glej, tresejo se in vsi hribi se gibljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 25, 'Gledam, in glej, ni človeka, tudi vse ptice nebeške so odletele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 26, 'Gledam, in glej, rodovitna zemlja je puščava in vsa mesta na njej so razdejana pred Gospodom, pred žarečo jezo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 27, 'Kajti tako pravi Gospod: Puščava bode vsa ta dežela, a docela je še ne pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 28, 'Zavoljo tega bo žalovala dežela in temno bode nebo, ker sem govoril, sklenil to; in ne bode mi žal in ne opustim tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 29, 'Od vrišča konjikov in lokostrelcev beži vse mesto: teko v goščave in lezejo na skale; vsako mesto je zapuščeno, in ni človeka, ki bi prebival v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 30, 'Ti pa, opustošena, kaj boš počela? Čeprav se oblačiš v škrlat, čeprav se lepotičiš z dragotino zlato, čeprav si mažeš z lepotico oči: zaman se delaš lepo; ne marajo te ljubitelji, strežejo ti po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 4, 31, 'Kajti glas čujem kakor porodnice, stisko kakor prvorodnice, glas hčere sionske, ki sopiha, razprostira roke: Ah, gorje mi! ker obnemaguje duša moja od morilcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 1, 'Obletite ulice jeruzalemske in poglejte ter izvedite in iščite po trgih njegovih, ali najdete moža, ali je kdo, ki dela pravico, ki išče zvestobe: in odpustim mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 2, 'A čeprav pravijo: Kakor Gospod živi, vendar prisegajo po krivem. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 3, 'O Gospod, ali se ne ozirajo oči tvoje v zvestobo? Tepel si jih, a ni jih bolelo, potrl si jih, a branili so se sprejeti nauk; obličje svoje so napravili trše od skale, nočejo se povrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 4, 'Tedaj sem rekel: Samo siromaki so taki; nespametno ravnajo, ker ne poznajo pota Gospodovega, ne pravice svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 5, 'Pojdem pa k prvakom in bom ž njimi govoril, zakaj oni poznajo pot Gospodov, pravico svojega Boga. Ali oni so vsi vkup zlomili jarem, raztrgali spone.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 6, 'Zato jih bo udaril lev iz gozda, večerni volk jih bo ugonobil, pard bo prežal po njih mestih: kdorkoli izmed njih pride na plano, ga raztrga zver; kajti premnogi so njih prestopki, mnogoštevilni njih odpadi. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 7, 'Kako naj ti odpustim? Sinovi tvoji so me zapustili in prisegajo pri njih, ki niso bogovi. Kakor hitro sem jih nasitil, so prelomili zakon in v nečistničini hiši so se zbirali kupoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 8, 'Kakor napaseni konji so, ko vstanejo zjutraj; vsak rezgeta proti bližnjega svojega ženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 9, 'Ali bi jih ne obiskal zavoljo tega? govori Gospod; in ali bi se nad takim narodom ne maščevala duša moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 10, 'Splezajte na zidove njene in razgrajajte, a docela je ne pokončajte; potrebite odrastke njene, ker oni niso Gospodovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 11, 'Zakaj zelo nezvesto so ravnali proti meni, hiša Izraelova in hiša Judova, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 12, 'Zatajili so Gospoda in govorili: „Njega ni; in ne zgodi se nam hudo in meča in gladu ne izkusimo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 13, 'in tisti proroki preidejo kakor veter, in besede Božje ni v njih; njim samim se tako zgodi!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 14, 'Zatorej pravi tako Gospod, Bog nad vojskami: Zato ker govorite to besedo, glej, storim besede svoje v tvojih ustih v ogenj, to ljudstvo pa v les, in ogenj ga pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 15, 'Glej, jaz pripeljem zoper vas narod od daleč, o hiša Izraelova, govori Gospod: narod močan, narod starodaven, narod, čigar jezika ne poznaš, in ne razumeš, kaj govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 16, 'Njih tul je kakor grob odprt, vsi so junaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 17, 'In pojedó žetev tvojo in hrano tvojo, katero naj bi pojedli sinovi tvoji in hčere tvoje, pojedó črede tvoje in goveda tvoja, vinske trte in smokve tvoje, razdenejo z mečem trdna mesta tvoja, na katera se zanašaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 18, 'Toda tudi v tistih dnevih, govori Gospod, vas docela ne pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 19, 'In zgodi se, ko porečete: Zakaj je nam storil Gospod, naš Bog, vse to? tedaj jim reci: Kakor ste me zapustili in ste služili tujim bogovom v svoji deželi, tako boste služili tujcem v deželi, ki ni vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 20, 'Oznanjujte to v hiši Jakobovi in proglašajte v Judi, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 21, 'Poslušajte zdaj to, ljudstvo neumno in brez srca, ki imajo oči, in ne vidijo, ki imajo ušesa, in ne slišijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 22, 'Mene li se ne bojite, govori Gospod, pred mojim li obličjem ne boste trepetali? ki sem naredil pesek morju v mejo, večno ograjo, ki je ne prestopi; čeprav se valovi zaletavajo, vendar ne premagajo, čeprav močno pljuskajo, vendar ne morejo preskočiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 23, 'Ali to ljudstvo ima srce trmasto in uporno; odstopili so in še dalje zahajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 24, 'In ne govore v srcu svojem: Bojmo se zdaj Gospoda, Boga svojega, ki daje dež zgodnji in pozni ob svojem času, nam hrani gotove tedne za žetev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 25, 'Krivice vaše odvračajo to in grehi vaši odganjajo to dobro od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 26, 'Kajti med ljudstvom mojim so brezbožni; preže kakor ptičarji, stavijo pogubne zanke, lové ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 27, 'Kakor ptičev polna ptičnica, tako so njih hiše polne zvijače, zato so veliki in bogati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 28, 'Debeli, gladki so, da, stopajo predaleč v hudobnih dejanjih; ne potegujejo se za pravdo, pravdo sirotam, da bi jim šlo po sreči, in siromakom ne prisojajo pravice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 29, 'Ali bi jih ne obiskal zavoljo tega? govori Gospod; ali bi se nad takim narodom ne maščevala duša moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 30, 'Reč strahovita in grozna se godi v tej deželi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 5, 31, 'proroki prorokujejo lažnivo in duhovniki gospodujejo ž njih pomočjo, in ljudstvo moje vidi to rado. Kaj storite pa nazadnje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 1, 'Bežite na varno, otroci Benjaminovi, izsredi Jeruzalema in v Tekoi trobite na trombo in proti Bet-keremu vzdignite znamenje; kajti nesreča grozi od severa in velika stiska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 2, 'Hčer sionsko, lepo in nežno, izničim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 3, 'K njej bodo hodili pastirji s čredami svojimi; šatore bodo stavili proti njej kroginkrog, vsak popase svoj prostor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 4, '„Na vojsko se pripravljajte proti njej! Vstanite in idimo gori že opoldne!... Gorje nam! ker dan je minil, ker nagnile so se sence večerne!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 5, 'Vstanite in idimo gori še po noči in pokončajmo njene palače!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 6, 'Kajti tako je velel Gospod vojnih krdel: Sekajte les in napravite nasip zoper Jeruzalem! Prav to mesto je treba obiskati; kolikršno je, zgolj zatiranje je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 7, 'Kakor voda teče iz vodnjaka, tako teče iz njega hudobija; silovitost in pustošenje se čuje v njem; pred obličjem mojim je vedno bridkost in uboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 8, 'Daj se posvariti, o Jeruzalem, da se ne odtrga duša moja od tebe, da te ne naredim pustega, za deželo brez prebivalcev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 9, 'Tako pravi Gospod nad vojskami: Paberkovali bodo kakor po trtah ostanke Izraelove. Izteguj zopet roko kakor trgač po rozgah! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 10, 'Komu naj govorim in pričujem, da bi slišali? Glej, neobrezano je njih uho in ne morejo biti pozorni; glej, beseda Gospodova jim je v zasmehovanje, ne vesele se je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 11, 'Zato sem poln srda Gospodovega, utrujen sem od zadržavanja. Izlij ga nad otroke po ulicah in nad druščino mladeničev; kajti tudi mož z ženo bosta zadeta, starček in prileten mož;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 12, 'in njih hiše preidejo v last drugim z njivami in ženami vred. Kajti iztegnem roko svojo nad prebivalce tiste dežele, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 13, 'Zakaj od največjega do najmanjšega izmed njih so vsi vdani dobičku; in od proroka do duhovnika, kar jih je, delajo krivično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 14, 'In hčeri ljudstva mojega zdravijo rano prav lahkomiselno, govoreč: Mir, mir! dasi ni miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 15, 'Ali jih je bilo sram, ko so delali gnusobo? Ne, sram jih ni nikakor in zardeti ne znajo. Zato padejo med padajočimi; zgrudijo se tisti čas, ko jih obiščem, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 16, 'Tako pravi Gospod: Stopite na pota in glejte ter poprašujte po starih stezah, katera je pot dobrega, in hodite po njej, in najdete pokoj dušam svojim. Ali pravijo: Nočemo hoditi po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 17, 'In postavil sem čuvaje nad vas, veleče: Pazite na glas trobente! A rekli so: Nočemo paziti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 18, 'Zato poslušajte, o narodi, in spoznaj, občina, kaj se godi med njimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 19, 'Poslušaj, o zemlja! Glej, jaz pripeljem nesrečo nad to ljudstvo, njih misli sad; kajti niso pazili na besede moje in postavo mojo so zavrgli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 20, 'Čemu mi kadilo, ki prihaja iz Sabe, in dišeči trst predragi iz daljne dežele? Žgalne daritve vaše niso prijetne in žrtve vaše mi niso ljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 21, 'Zato je rekel Gospod tako: Glej, jaz naredim temu ljudstvu spotike, ob katere se bodo hkratu spotikali očetje in sinovi, sosed in prijatelj njegov, in poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 22, 'Tako pravi Gospod: Glej, ljudstvo prihaja iz severne dežele in narod velik se vzdiguje od krajev zemlje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 23, 'Za lok in sulico prijemljejo, krvoločni so in brez usmiljenja; glas njih šumi kakor morje in na konjih jezdijo; vsakdo je pripravljen zoper tebe, hči sionska, kakor mož na vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 24, 'Slišali smo glas o njem, omahnile so nam roke, groza nas je obšla, bolečina kakor porodnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 25, 'Ne hodi na polje in na potu ne postajaj, kajti meč ima sovražnik, strah je kroginkrog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 26, 'O hči ljudstva mojega, opaši se z raševino, valjaj se po pepelu, kakor po edinorojencu žaluj, jokaj prebridko! kajti nagloma pride razdejalec zoper nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 27, 'Postavil sem te za izkuševalca in za trdnjavo med svojim ljudstvom, da spoznavaš in preiskuješ njih pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 28, 'Vsi so trdovratni uporniki, pohajajo z obrekovanjem; jekleni so in železni, popačeno ravnajo vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 29, 'Žari se meh, ogenj pokončava svinec; zaman tope in tope: zakaj hudobni se nočejo izločiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 6, 30, 'Srebro zavrženo jih bodo imenovali, kajti Gospod jih je zavrgel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 2, 'Stopi med vrata hiše Gospodove in oznanjaj tam besedo to in reci: Poslušajte besedo Gospodovo, vsi Judovci, ki greste noter skozi ta vrata molit Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 3, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Dobra naredite svoja pota in dejanja, pa storim, da boste prebivali v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 4, 'Ne zanašajte se na lažnive besede, govoreč: Tempelj Jehove, tempelj Jehove, tempelj Jehove je to!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 5, 'Zakaj če res dobra naredite svoja pota in dejanja, če boste resnobno delali pravico med možem in možem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 6, 'če tujca, sirote in vdove ne boste tlačili in nedolžne krvi ne prelivali v tem kraju, tudi za tujimi bogovi ne hodili v svojo nesrečo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 7, 'storim, da boste prebival v tem kraju, v deželi, ki sem jo dal očetom vašim, od veka do veka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 8, 'Glejte, zanašate se na lažnive besede, ki ne morejo nič koristiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 9, 'Hočete li krasti, ubijati in prešeštvovati ter prisegati po krivem in kaditi Baalu pa hoditi za tujimi bogovi, ki jih ne poznate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 10, 'pa boste prišli in stopili predme v tej hiši, ki se imenuje po mojem imenu, in porečete: Rešeni smo! da bi mogli uganjati vse te gnusobe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 11, 'Je li ta hiša, ki je imenovana po mojem imenu, postala v vaših očeh jama razbojnikov? Tudi jaz, glejte, sem videl to, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 12, 'Pojdite pa, pravim, v moj kraj, ki je bil v Silu, kjer sem bil storil, da je prvič prebivalo ondi ime moje, in glejte, kaj sem mu storil zavoljo hudobnosti ljudstva svojega Izraela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 13, 'In sedaj, ker ste delali vsa tista dejanja, govori Gospod, in ko sem vam govoril od ranega jutra in neprenehoma, a niste poslušali, in sem vas klical, a niste odgovorili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 14, 'zato storim tej hiši, ki se imenuje po mojem imenu, na katero se vi zanašate, in temu kraju, ki sem ga dal vam in očetom vašim, kakor sem storil Silu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 15, 'In zavržem vas izpred obličja svojega, kakor sem zavrgel vse brate vaše, vse seme Efraimovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 16, 'Ti torej ne prosi za to ljudstvo in ne povzdiguj vpitja, ne prošnje zanje in ne posreduj pred menoj; kajti nikakor bi te ne poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 17, 'Ali ne vidiš, kaj delajo oni v mestih Judovih in po ulicah jeruzalemskih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 18, 'Otroci pobirajo drva in očetje zažigajo ogenj in žene gnetejo testo, da narede kolače kraljici nebeški in da darujejo pitne daritve drugim bogovom, da me dražijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 19, 'Ali je zoper mene, ko delajo zdražbo? govori Gospod; ni li zoper nje same, v osramočenje njih obličja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 20, 'Zato pravi tako Gospod Jehova: Glej, jeza moja in srditost moja se razlije nad to mesto, nad ljudi in nad živino, nad drevje na polju in nad sad zemlje; in gorela bo in ne ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 21, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Žgalne daritve svoje pridenite žrtvam svojim in jejte meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 22, 'Kajti nisem govoril z očeti vašimi in nisem jim zapovedal tisti dan, ko sem jih izpeljal iz dežele Egiptovske, o žgalnih daritvah in žrtvah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 23, 'ampak to sem jim zapovedal, govoreč: Poslušajte glas moj, in bodem vaš Bog in vi mi bodete ljudstvo; in hodite po vsem tistem potu, ki vam ga bom ukazal, da bi se vam dobro godilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 24, 'Ali niso poslušali in niso nagnili ušesa svojega, temuč hodili so po lastnih sklepih, po trmi hudobnega srca svojega; obrnili so mi hrbet in ne obličja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 25, 'Od dne, ko so bili odšli očetje vaši iz dežele Egiptovske, prav do tega dne sem pošiljal k vam vse hlapce svoje proroke vsak dan zgodaj zjutraj in neprenehoma;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 26, 'vendar me niso poslušali in niso nagnili ušesa svojega, ampak bili so trdovratni, huje so delali nego njih očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 27, 'In ko govoriš pred njimi vse te besede, te tudi ne poslušajo, in ko jih kličeš, ti ne odgovarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 28, 'Zatorej jim porečeš: To je narod, ki ne posluša glasu Gospoda, svojega Boga, in ne sprejema nauka; konec je zvestobi in iztrebljena je iz njih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 29, 'Ostrizi si lase, hči sionska, in vrzi jih stran in na golih višinah zaženi žalovanje, ker je Gospod zavrgel in zapustil rod, ki se mu srdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 30, 'Kajti sinovi Judovi so storili, kar je hudo v mojih očeh, govori Gospod; postavili so gnusobe svoje v hišo, ki se imenuje po mojem imenu, da jo oskrunijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 31, 'In sezidali so višave Tofetu, ki je v dolini sinu Hinomovega, da bi žgali na ognju sinove in hčere svoje, česar nisem bil zapovedal in mi ni bilo prišlo na misel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 32, 'Zatorej, glej, pridejo dnevi, govori Gospod, ko se ne bo več dejalo Tofet, ne dolina sinu Hinomovega, marveč Dolina moritve, in bodo pokopavali v Tofetu, ker drugje ne bode prostora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 33, 'In mrliči tega ljudstva bodo paša ptičem izpod neba in zemeljskim zverem, in nihče jih ne bo plašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 7, 34, 'Tedaj storim, da potihne v mestih Judovih in po ulicah jeruzalemskih glas veselja in glas radosti, glas ženina in glas neveste, zakaj razdejana bo ta dežela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 1, 'V tistem času, govori Gospod, bodo izgrebli kosti kraljev Judovih in kosti njegovih knezov in kosti duhovnikov in kosti prorokov ter kosti prebivajočih v Jeruzalemu iz njih grobov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 2, 'in jih bodo razmetali pod solnce in mesec in pod vso vojsko nebeško, ki so jih ljubili in so jim služili in za katerimi so hodili in katere so iskali in se jim klanjali; ne bodo se zbirale in ne bodo se pokopavale, za gnoj bodo na licu zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 3, 'In smrt bo rajši volil nego življenje ves ostanek, tisti, ki bodo preostali iz te rodovine hudobne, preostali v vseh krajih, kamor jih zapodim, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 4, 'Še jim porečeš: Tako pravi Gospod: Ali kdo, kadar pade, rad ne vstane? ali kadar kdo zajde, ne mara se povrniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 5, 'Zakaj se je torej odvrnilo to ljudstvo jeruzalemsko z neprenehljivim odpadanjem? Trdno se drže zvijače, nočejo se povrniti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 6, 'Pazil sem in poslušal: govoré, kar ni prav; nihče se ne kesa hudobnosti svoje, da bi rekel: Kaj sem storil? Vsakdo izmed njih se je obrnil v teku svojem kakor konj, ki strmoglavo hiti v boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 7, 'Tudi čaplja pod nebom pozna svoje gotove čase, in grlica in žerjav in lastovka se drže časa svojega prihoda; ljudstvo moje pa ne pozna pravice Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 8, 'Kako govorite: Modri smo in postava Gospodova je pri nas? Glejte, res je lažnivo pisalo pismoukov iz nje napravilo laž.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 9, 'Modri bodo osramočeni, oplašeni in ujeti; glej, besedo Gospodovo so zavrgli, in kakšna modrost bi bila v njih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 10, 'Zato izročim njih žene drugim, njih polja njim, ki jih bodo posedli. Kajti od najmanjšega do največjega so vsi vdani dobičku, od proroka do duhovnika, kolikor jih je, se pečajo s prevaro,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 11, 'in hčeri ljudstva mojega zdravijo rano prav lahkomiselno, govoreč: Mir, mir! dasi ni miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 12, 'Ali jih je bilo sram, ko so delali gnusobo? Ne, sram jih ni nikakor in zardeti ne znajo. Zato padejo med padajočimi; tisti čas, ko jih obiščem, se zgrudijo, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 13, 'Čisto jih iztrebim, govori Gospod; nobenega grozdja ne bo na trti in nobene smokve na smokvi in listje odpade, in karkoli sem jim dal, jim premine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 14, '„Čemu posedamo? Zberimo se in idimo v trdna mesta, da poginemo tam! kajti Gospod, Bog naš, nas je določil v pogubo in nam dal piti sok trobelični, ker smo grešili zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 15, 'Čakali smo miru, toda nič ni prišlo dobrega, časa ozdravljenja, a glej, le strah!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 16, 'Od Dana sem se čuje prhanje konj njegovih; od glasu rezgetanja krepkih konj njegovih se trese vsa dežela; kajti gredo, da požro deželo in kar jo napolnjuje, mesto in nje, ki prebivajo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 17, 'Kajti jaz, glejte, pošljem med vas kače, modrase, zoper katere ne pomaga nobeno rotenje, da vas zgrizejo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 18, 'O da bi se mogel poživiti v žalosti! V meni hira srce moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 19, 'Glej, vpitje hčere ljudstva mojega se glasi močno iz daljne dežele: „Ali ni Gospoda na Sionu? ni li Kralja njegovega v njem?“Zakaj so me razdražili z rezanimi podobami svojimi, z ničemurnostmi inozemcev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 20, '„Minila je žetev, konec je poletju, in mi nismo rešeni!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 21, 'Zavoljo pobitosti hčere ljudstva mojega sem pobit; črno hodim oblečen, groza me je objela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 8, 22, 'Ali ni nič balzama v Gileadu? ali ni nobenega zdravnika tam? Zakaj torej ni ozdravela hči ljudstva mojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 1, 'O da bi dosti imel vode v glavi in oči da bi mi bile studenci solzá, da bi objokoval noč in dan prebodence ljudstva svojega hčere!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 2, 'O kdo bi me postavil v puščavo, v prenočišče popotnikov, da zapustim ljudstvo svoje in odidem od njih! Zakaj vsi so prešeštniki, skupščina nezvestnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 3, 'In jezik svoj napenjajo kakor lok za laž; v deželi so se utrdili, a ne v prid resnici, kajti od hudobije hite do hudobije in mene ne spoznajo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 4, 'Vsak se varuj svojega prijatelja in nobenemu bratu ne upajte, zakaj vsak hoče lokavo izpodriniti drugega in vsak prijatelj hodi z natolcevanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 5, 'In vsak vara prijatelja svojega in resnice ne govore; jezik svoj uče govoriti laž, učijo se delati krivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 6, 'Tvoje prebivališče je sredi zvijače; zaradi zvijače se branijo spoznati me, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 7, 'Zatorej pravi tako Gospod nad vojskami: Glej, jaz jih bom topil in jih preizkušal; kajti kako naj bi drugače delal zavoljo hčere ljudstva svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 8, 'Pšica moreča je njih jezik; zvijačo govore; z usti govori mir prijatelj s prijateljem, ali v srcu svojem preži nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 9, 'Ali bi jih ne obiskal zavoljo tega? govori Gospod; ali bi se nad takim narodom ne maščevala duša moja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 10, 'Zavoljo teh gorá napravim jok in žalovanje in zavoljo pašnikov v puščavi tožbo; kajti požgani so tako, da nihče ne hodi mimo in ni slišati glasu živine: ptice nebeške in goveda so zbežala, odšla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 11, 'In iz Jeruzalema naredim groblje, prebivališče šakalov, in iz mest Judovih naredim puščavo, da nihče ne bo prebival v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 12, 'Kdo je tisti modri mož, ki bi to razumel? in komu so govorila usta Gospodova, da bi oznanjal to? Zakaj je ta dežela pokončana in požgana kakor puščava, da nihče ne hodi po njej?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 13, 'In Gospod je rekel: Ker so zapustili postavo mojo, ki sem jo jim bil razložil, in niso poslušali glasu mojega in niso hodili po njej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 14, 'ampak so šli po trmi srca svojega in za Baali, kar so jih učili njih očetje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 15, 'zatorej pravi tako Gospod nad vojskami, Bog Izraelov: Glej, jaz jih bom, to ljudstvo, sitil s pelinom in jim piti dajal sok trobelični;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 16, 'in razkropim jih med narode, ki jih niso ne sami, ne njih očetje poznali, in za njimi pošljem meč, dokler jih ne pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 17, 'Tako pravi Gospod nad vojskami: Pazite in pokličite žene žalovalke, da pridejo, in k modrim ženam pošljite, da pridejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 18, 'in urno naj zaženo žalovanje o nas, da bi nam kapljale solze iz oči in s trepalnic naših tekla voda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 19, 'Kajti žalovanja glas se sliši s Siona: Kako smo opustošeni! silno smo osramočeni, zakaj bilo nam je zapustiti deželo, ker so nam podrli domovališča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 20, 'Poslušajte torej, žene, besedo Gospodovo in uho vaše naj sprejme besedo njegovih ust, in učite žalovati hčere svoje in druga drugo peti žalostinke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 21, 'Zakaj smrt je k nam prilezla skozi okna, prišla je v palače naše, da pokonča otroke z ulic in mladeniče s trgov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 22, 'Govóri: Tako pravi Gospod: Trupla človeška bodo ležala kakor gnoj na polju in kakor snopki za ženjci, in nihče jih ne bo pobiral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 23, 'Tako pravi Gospod: Ne hvali se modri z modrostjo svojo, in ne hvali se mogočni z mogočnostjo svojo, tudi ne bogati z bogastvom svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 24, 'ampak s tem se naj hvali, kdor se hvali, da ume in spozna mene, da sem jaz Gospod, ki delam milost, sodbo in pravičnost na zemlji; kajti to mi je po volji, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 25, 'Glej, dnevi pridejo, govori Gospod, ko obiščem vse obrezane v njih neobrezi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 9, 26, 'Egipčane in Jude in Edomce in sinove Amonove in Moabce ter vse, ki so ostriženi ob krajih glave, ki prebivajo v puščavi; kajti vsi poganski narodi so neobrezani, vsa hiša Izraelova pa je neobrezanega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 1, 'Poslušajte to besedo, ki jo vam govori Gospod, o hiša Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 2, 'Tako pravi Gospod: Ne učite se pota poganskih narodov in ne plašite se znamenj nebeških, ker se jih plašijo tisti narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 3, 'Kajti postave ljudstev so ničemurnost; zakaj samo les je, ki ga kdo poseka v gozdu, delo roke in sekire umetnikove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 4, 'Naredi ga lepega s srebrom in zlatom; pritrdijo ga z žeblji in kladivi, da se ne zvrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 5, 'Kakor ostrugani stebri so maliki, še govore ne; nositi jih je treba, ker ne morejo hoditi. Ne bojte se jih, ker ne morejo storiti hudega, tudi dobro delati ni v njih moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 6, 'Prav nihče ni tebi enak, o Jehova; ti si velik in veliko je ime tvoje v moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 7, 'Kdo bi se te ne bal, o Kralj narodov! ker tebi se spodobi. Zakaj med vsemi modrimi pri narodih in v vseh njih kraljestvih ni nobeden tebi enak,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 8, 'temuč vsi skupaj so nespametni in trapasti. Pouk malikov je njim enak: les.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 9, 'Srebrne ploščice vozijo iz Tarsisa in zlato iz Ufaza, delo umetnikov iz rok topilčevih; višnjevo in rdeče jim napravljajo oblačilo, delo umetnikov so vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 10, 'Gospod pa je Bog v resnici, živi Bog in kralj večni; od jeze njegove se trese zemlja, in narodi ne morejo prenašati nevolje njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 11, 'Tako jim recite: Bogovi, ki niso ustvarili nebes in zemlje, izginejo iznad zemlje in izpod neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 12, 'On je naredil zemljo s krepostjo svojo, ustanovil vesoljni svet z modrostjo svojo in z razumnostjo svojo je razpel nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 13, 'Ko se on oglaša, nastane šum voda na nebu; on vzdiguje sopare od krajev zemlje, bliske dela za dež in pripeljava veter iz zakladnic svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 14, 'Nespameten je postal vsak človek, je brez spoznanja; vsak zlatar se osramočuje z mališko podobo; kajti lažniva je ulita podoba njegova in sape ni v nobeni med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 15, 'Ničemurnost so, smeha vredno delo; ob času njih obiskovanja poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 16, 'Njim ni podoben on, ki je Jakobov delež; kajti on je upodobil vse, in Izrael je rod posesti njegove: Gospod nad vojskami je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 17, 'Poberi iz dežele blago svoje ti, ki sediš v oblegi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 18, 'Kajti tako pravi Gospod: Glej, jaz bom s pračo ven pometal prebivalce te dežele in jih stiskal, da bodo čutili. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 19, 'Gorje mi zavoljo nadloge moje! Skeleča je rana moja. Toda pravim: Res, to je trpljenje moje, moram ga pretrpeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 20, 'Šator moj je razdejan in vse vrvi moje pretrgane; otroci moji so šli od mene in ni jih več; nihče ne razpenja več šatora mojega in nanj ne razveša mojih preprog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 21, 'Kajti pastirji so postali nespametni in se niso posvetovali z Gospodom: zato niso imeli sreče, in vsa njih čreda se je razkropila. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 22, 'Čuj, kaj se sliši: glej, on prihaja, in velik hrup iz severne dežele, da se naredi iz mest Judovih puščava, prebivališče šakalov. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 23, 'Vem, o Gospod, da ni človeku v oblasti pot njegova, ne v moči moža, kako naj hodi in ravna stopinje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 24, 'Kaznuj me, Gospod, ali zmerno, ne v jezi svoji, da me ne uničiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 10, 25, 'Razlij srd svoj nad narode, ki te ne spoznavajo, in nad rodove, ki ne kličejo tvojega imena; kajti pojedli so Jakoba in ga požrli ter ga pokončali in opustošili prebivališče njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 2, 'Poslušajte besede te zaveze in govorite možem Judovim in prebivalcem jeruzalemskim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 3, 'Porečeš jim torej: Tako pravi Gospod, Bog Izraelov: Proklet bodi mož, ki ne bo poslušal besede zaveze,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 4, 'ki sem jo ukazal očetom vašim tisti dan, ko sem jih peljal iz dežele Egiptovske, iz peči železne, veleč: Poslušajte moj glas in delajte te besede, kakor vam ukazujem, in bodete mi za ljudstvo in jaz vam bodem Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 5, 'da izpolnim prisego, ki sem jo prisegel očetom vašim, da jim dam deželo, kjer se mleko in med cedi, kakor je danes. Tedaj sem odgovoril in rekel: Amen, o Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 6, 'In Gospod mi veli: Oznani vse te besede po mestih Judovih in po ulicah jeruzalemskih, govoreč: Poslušajte besede te zaveze in jih izpolnjujte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 7, 'Kajti rotil sem očete vaše tisti dan, ko sem jih peljal iz dežele Egiptovske, do tega dne, od ranega jutra in neprenehoma, govoreč: Poslušajte moj glas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 8, 'Vendar niso poslušali in niso nagnili svojih ušes, ampak hodili so vsak po trmi hudobnega srca svojega; zato sem poslal nadnje vse besede te zaveze, ki sem jo bil ukazal izpolnjevati, in niso jih izpolnjevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 9, 'In Gospod mi reče: Zarota je tu med možmi Judovimi in jeruzalemskimi prebivalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 10, 'Vrnili so se h krivicam prvih očetov svojih, ki so se branili poslušati besede moje; in oni so šli za tujimi bogovi, da jih časté; prelomila je hiša Izraelova in hiša Judova zavezo mojo, ki sem jo bil sklenil z njih očeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 11, 'Zatorej pravi tako Gospod: Glej, jaz pošljem nadnje zlo, ki mu ne bodo mogli ubežati; in klicali bodo k meni, a ne uslišim jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 12, 'Tedaj pojdejo mesta Judova in prebivalci jeruzalemski in bodo klicali bogove, ki so jim kadili, ali nikakor jih ne rešijo v času njih nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 13, 'Kajti kolikor mest, toliko bogov imaš, o Juda, in kolikor je ulic v Jeruzalemu, toliko ste postavili oltarjev tisti sramoti, oltarjev, da na njih kadite Baalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 14, 'Ti torej ne prosi za to ljudstvo in ne povzdiguj zanje vpitja in prošnje; zakaj ne uslišim jih tisti čas, ko bodo klicali k meni spričo nesreče svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 15, 'Kaj je ljubemu mojemu storiti v moji hiši, ker tu mnogi kujejo zvijače? Bo li sveto meso odpravilo zlo tvoje od tebe? tedaj šele se raduj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 16, 'Oljko zeleno, krasno, z lepim sadom je imenoval Gospod ime tvoje. Ob glasu velikega hrupa je zažgal ogenj na njej, in polomile so se veje njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 17, 'Kajti Gospod nad vojskami, ki te je bil zasadil, je govoril hudo zoper tebe zaradi hudobije hiše Izraelove in hiše Judove, ki so jo delali sebi v kvar, da bi me dražili, ko so kadili Baalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 18, 'In Gospod mi je pokazal to, da sem spoznal; takrat si mi razodel njih dejanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 19, 'In jaz sem bil kakor krotko jagnje, ki ga peljejo v zakol; in nisem vedel, da so naklepe ukrepali proti meni: „Pokončajmo drevo s sadom njegovim vred in iztrebimo ga iz dežele živih, da se ne bo več omenjalo ime njegovo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 20, 'Ali, o Gospod nad vojskami, ki sodiš pravično, ki preiskuješ ledice in srca, daj mi videti maščevanje svoje nad njimi, kajti tebi sem razodel pravdo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 21, 'Zatorej pravi tako Gospod o možeh v Anatotu, ki ti strežejo po življenju, govoreč: Ne prorokuj v imenu Gospodovem, in ne umreš od naših rok –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 22, 'zato pravi tako Gospod nad vojskami: Glej, jaz jih bom pokoril: mladeniči umro pod mečem, njih sinov in hčere umro od glada,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 11, 23, 'in ostanka jim ne bode; kajti pošljem nesrečo nad može anatotske, leto, ko bodo obiskani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 1, 'Pravičen ostaneš, o Gospod, ko bi se hotel prepirati s teboj; vendar si drznem govoriti o pravdi s teboj: Zakaj je uspešna pot brezbožnih? zakaj žive v blaginji, katerikoli delajo nezvesto?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 2, 'Sadil si jih, in so se tudi ukoreninili; rasto, pa tudi dajó sad. V njih ustih si blizu, a daleč od njih ledic.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 3, 'Ali ti, o Gospod, me poznaš, vidiš v me in izkušaš srce moje, kakšno je do tebe. Zvleci jih kakor ovce v klanje in pripravi jih za dan moritve!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 4, 'Doklej naj žaluje dežela in vene rastlina po vsem polju? Od hudobnosti prebivalcev njenih peša živina in ptiči, ker govore: Ne vidi našega konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 5, 'Ko si tekel s pešci in so te utrudili, kako torej bi se poskušal s konji? In ako se počutiš varnega v deželi miru, kaj boš počel ob veličju Jordanovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 6, 'Zakaj tudi bratje tvoji in očeta tvojega družina, tudi oni ravnajo nezvesto proti tebi, tudi oni vpijejo glasno za teboj. Ne veruj jim, čeprav te ogovarjajo prijazno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 7, 'Zapustil sem hišo svojo, zavrgel dediščino svojo; izdal sem njo, ki jo je ljubila duša moja, v roko sovražnikov njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 8, 'Dediščina moja mi je postala kakor lev v gozdu: zoper mene je zagnala svoj glas, zato jo sovražim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 9, 'Je li mi dediščina moja kakor pisana ropna ptica, da so roparice kroginkrog zoper njo? Pojdite, zberite vse zveri v gozdu, storite, da pridejo požirat!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 10, 'Mnogi pastirji so pokončali moj vinograd, poteptali delež moj, naredili so zaželjeni delež moj v prepusto puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 11, 'Naredili so jo v pustinjo, žaluje po meni, opustošena. Vsa dežela je opustošena, ker ni nikogar, da bi premislil v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 12, 'Na vse gole griče po puščavi so prišli razdejalci; kajti meč Gospodov pokončava od kraja do kraja zemlje: miru ne bo imelo nobeno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 13, 'Posejali so pšenico, in želi trnje; upehali so se, a nič prida niso opravili. Tako boste osramočeni pri pridelkih svojih zavoljo goreče jeze Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 14, 'Tako pravi Gospod o vseh hudobnih sosedih mojih, ki se dotikajo dediščine, katero sem v last dal ljudstvu svojemu Izraelu: Glej, jaz jih izpulim iz njih dežele in družino Judovo izpulim izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 15, 'In zgodi se, ko jih izpulim, da se jih zopet usmilim in vsakega izmed njih pripeljem nazaj v njegovo dediščino in vsakega v deželo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 16, 'Zgodi se tudi, če se bodo pridno učili poti ljudstva mojega, da bi prisegali pri mojem imenu: Kakor resnično Gospod živi! kakor so moje ljudstvo učili prisegati pri Baalu: tedaj se ustanové sredi mojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 12, 17, 'Ako pa ne bodo poslušali, tedaj izpulim tisti narod, izpulim ga in pokončam, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 1, 'Tako mi je velel Gospod: Pojdi in si kupi prten pas in opaši ž njim ledja svoja, ali v vodo ga ne deni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 2, 'Torej sem po besedi Gospodovi kupil pas in si opasal ž njim ledja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 3, 'Nato mi je prišla beseda Gospodova v drugič, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 4, 'Vzemi tisti pas, ki si ga kupil, ki so ž njim opasana ledja tvoja, in vstani, odidi k Evfratu in ga skrij tam v skalnato luknjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 5, 'Tedaj sem odšel in ga skril pri Evfratu, kakor mi je bil zapovedal Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 6, 'Ko pa je minilo mnogo dni, mi reče Gospod: Vstani, oditi k Evfratu in vzemi zopet odondod tisti pas, ki sem ti bil zapovedal, da ga skrij ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 7, 'Šel sem torej k Evfratu, izkopal in vzel pas s tistega kraja, kjer sem ga bil skril: ali glej! pas je bil pokvarjen, ni bil za nobeno rabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 8, 'Tedaj mi je prišla beseda Gospodova:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 9, 'Tako pravi Gospod: Prav tako hočem pokvariti prevzetnost Judovo in veliko prevzetnost jeruzalemsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 10, 'To ljudstvo hudobno, ki se brani poslušati besede moje, ki ravna po trmi svojega srca in hodi za drugimi bogovi, da bi jih častilo in se jim klanjalo, bode podobno temu pasu, ki ni za nobeno rabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 11, 'Kajti kakor se pas oklene ledij moževih, tako sem storil, da se oklepaj mene vsa hiša Izraelova in vsa hiša Judova, govori Gospod, da bodo meni v ljudstvo in za ime in za hvalo in za lepoto; ali niso poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 12, 'Zato jim porečeš besedo to: Tako pravi Gospod, Bog Izraelov: Vsak meh se napolni z vinom. Ko ti pa poreko: Ali res ne vemo, da se vsak meh napolni z vinom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 13, 'tedaj jim reci: Tako pravi Gospod: Glejte, jaz napolnim s pijanostjo vse prebivalce te dežele, i kralje, ki sede za Davida na prestolu njegovem, i duhovnike in proroke in vse prebivalce v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 14, 'In storim, da trčijo drug ob drugega, očetje in sinovi se spopadejo med seboj, govori Gospod; ne prizanesem, ne bode mi jih žal, ne usmilim se, da bi jih ne pogubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 15, 'Poslušajte in z ušesi sprejmite, ne povzdigujte se! zakaj Gospod je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 16, 'Dajajte slavo Gospodu, svojemu Bogu, preden naredi temo in preden se vam noge opotaknejo ob mračne gore, in ko boste pričakovali luči, vam jo naredi v senco smrti in izpremeni v gosto temo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 17, 'Če pa ne boste poslušali tega, bo na skrivnem plakala duša moja zavoljo prevzetnosti vaše in oči moje bodo hudo jokale in iz njih tekle solze, ker se bo v sužnost peljala čreda Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 18, 'Reci kralju in kraljici: Ponižno sédita na tla, kajti doli pojde prvaštvo vaju obeh, venec slave vajine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 19, 'Mesta na Jugu so zaprta, in nikogar ni, da bi jih odprl; Juda je ves odpeljan v sužnost, docela je odpeljan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 20, 'Povzdignite oči in poglejte jih, ki gredo od severa! Kje je tista čreda, ki ti je bila izročena, čreda slave tvoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 21, 'Kaj porečeš, ko postavi prijatelje tvoje nad teboj za glavo, ker si jih sama navadila zoper sebe? Ali te ne bodo zgrabile bolečine kakor ženo porodnico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 22, 'Če pa rečeš v srcu svojem: Zakaj me je to zadelo? Zavoljo množine krivice tvoje so se odgrnila krila tvoja, po sili so bili oskrunjeni podplati tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 23, 'More li črnec izpremeniti svojo polt? ali pard lise svoje? potem bi tudi vi mogli dobro delati, kos te se navadili hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 24, 'Zato jih raztrosim kakor pleve, ki lete ob vetru v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 25, 'To je usoda tvoja, delež, ki sem ti ga odmeril, govori Gospod, ker si pozabila mene in stavila upanje v laž.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 26, 'Zato ti tudi jaz potegnem rob tvoj čez obraz, da se bo videla sramota tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 13, 27, 'Prešeštva tvoja in rezgeti tvoji, pregrešno nečistovanje tvoje na hribih, na polju: videl sem gnusobe tvoje. Gorje ti, Jeruzalem! Ti se nočeš očistiti – koliko časa še?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 1, 'Beseda Gospodova, ki je prišla Jeremiju o sušah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 2, 'Judeja žaluje in vrata njena hirajo, v žalni obleki ležé na tleh in tožno vpitje Jeruzalema gre kvišku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 3, 'Tudi njih plemenitniki pošiljajo najmanjše svoje po vodo: pridejo k vodnjakom, in ne najdejo vode, povrnejo se s praznimi posodami; sram jih je in s sramoto obliti si pokrivajo glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 4, 'Zavoljo žejne zemlje, ker ni bilo dežja v deželi, so kmetovalci osramočeni in si pokrivajo glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 5, 'Da, tudi košuta na polju zapušča mladiče, ko jih je rodila, ker ni nobene trave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 6, 'In divji osli, stoječ na golih gričih, duškajo kakor šakali; hirajo jim oči, ker ni zelenjave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 7, 'Dasi pričajo krivice naše zoper nas, o Gospod, delaj z nami zaradi imena svojega; kajti mnogi so odpadi naši, tebi smo grešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 8, 'O upanje Izraelovo, rešitelj njegov v času stiske, zakaj si kakor tujec v tej deželi in kakor popotnik, ki se ustavi, da prenoči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 9, 'Zakaj bi bil kakor prestrašen mož, kakor junak, ki ne more rešiti? Saj si vendar sredi nas, Gospod, in po imenu tvojem se zovemo, ne zapusti nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 10, 'Tako pravi Gospod o tem ljudstvu: Tako radi tekajo semintja, nog svojih ne zdržujejo, zato jih Gospod ne sprejema prijazno; sedaj se spomni jih krivic in kaznoval bo njih grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 11, 'In Gospod mi je velel: Nikar ne prosi temu ljudstvu v prid!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 12, 'Ko se bodo postili, ne uslišim njih vpitja, in ko bodo prinašali žgalne in jedilne daritve, jih milo ne sprejmem, temuč z mečem in lakoto in kugo jih pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 13, 'Tedaj rečem: Oh, Gospod Jehova! glej, tisti proroki jim govore: Ne boste izkusili meča in lakote vam ne bode, ampak stanoviten mir vam dam v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 14, 'Nato mi reče Gospod: Lažnivo prorokujejo tisti proroki v mojem imenu; nisem jih poslal, ne zapovedal jim, še ogovoril jih nisem: sami vam prorokujejo z lažnivo prikaznijo in vedeževanjem in ničnostjo in z zvijačo svojega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 15, 'Zato pravi Gospod zoper tiste proroke, ki prorokujejo v mojem imenu, ko jih jaz nisem poslal, in govore: „Meča ali lakote ne bode v tej deželi“, z mečem in lakoto poginejo tisti proroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 16, 'Ljudstvo pa, ki mu oni prorokujejo, bo ležalo po ulicah jeruzalemskih od lakote in meča, in nikogar ne bodo imeli, da bi pokopaval nje, njih žene in njih sinove in hčere; tako razlijem nadnje njih hudobnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 17, 'Porečeš jim torej to besedo: Iz mojih oči kapajo solze noč in dan in ne prenehajo liti; zakaj z velikim potrtjem je potrta devica, hči mojega ljudstva, s prehudim udarcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 18, 'Če grem na polje, glej, tam prebodeni z meči; če pa stopim v mesto, glej, tam bolni od lakote! kajti i prorok i duhovnik hodita po deželi in nimata spoznanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 19, 'Ali si docela zavrtel Judo? ali se je Siona naveličala duša tvoja? Zakaj nas biješ tako, da nam ni zdravila? Ko čakamo miru, ni nič dobrega, in čas zdravljenja, glej, tolik strah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 20, 'Spoznavamo, Gospod, brezbožnost svojo, očetov svojih krivico; kajti grešili smo zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 21, 'Ne zaničuj nas zaradi imena svojega, ne onečaščuj prestola slave svoje, spomni se, ne prelomi zaveze svoje z nami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 14, 22, 'Ali so med ničevimi maliki poganov kateri, da dajó dežja? ali pa nebesa morejo dati deževje? Nisi li ti tisti, o Gospod, Bog naš? Zato čakamo tebe, ker ti sam si naredil vse to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 1, 'In rekel mi je Gospod: Ko bi stopila Mojzes in Samuel predme, bi srce moje nikakor ne bilo nagnjeno temu ljudstvu: spodi jih izpred mene, in naj odidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 2, 'In če ti poreko: Kam hočemo iti? reci jim: Tako pravi Gospod: Kdor na smrt, na smrt, in kdor na meč, na meč, in kdor na lakoto, na lakoto, in kdor na sužnjost, na sužnjost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 3, 'Postavim namreč nadnje štiri reči, govori Gospod: meč, da pobija, in pse, da trgajo, in ptice nebeške in zveri zemeljske, da požirajo in pokončavajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 4, 'In izdam jih v pestitev vsem kraljestvom zemlje; zaradi Manaseja, sina Ezekijevega, kralja Judovega, zavoljo tistega, kar je zakrivil v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 5, 'Kajti kdo bi imel usmiljenje s teboj, o Jeruzalem? ali kdo bi te miloval? ali kdo bi pristopil, poprašat o sreči tvoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 6, 'Ti si me zapustil, govori Gospod, nazaj si krenil; zato iztezam roko svojo zoper tebe, da te pogubim, utrujen sem od milovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 7, 'Zato jih bom vejal z vejalnico iz vrat te dežele ven; osirotil, pogubil bom ljudstvo svoje, ker se niso povrnili s potov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 8, 'Več mi bode vdov njegovih kakor morskega peska; pripeljem jim zoper matere mladega moštva razdejalca opoldne, storim, da jih nagloma objame strah in groza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 9, 'Hira ona, ki jih je rodila sedmero, izdiha dušo svojo; zaide solnce njeno, ko bode še dan, rdečica jo oblije in sram jo bode; in njih ostanek izpostavim meču vpričo njih sovražnikov, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 10, '„Gorje mi, mati moja, ker si rodila mene, ki mi napoveduje pravdo in prepir vsa ta dežela; nisem jim posojal in posojali mi niso, a vsakdo me preklinja.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 11, 'Gospod pravi: Resnično, okrepčam te za dobro, resnično storim, da te bo sovražnik milo prosil ob času nesreče in ob času stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 12, 'More li kdo železo zlomiti, železo severno in bron? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 13, 'Premoženje tvoje in zaklade tvoje bom dal v plenjenje brez cene, in to zavoljo vseh grehov tvojih, in po vseh mejah tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 14, 'In storim, da jih preneso sovražniki tvoji v deželo, ki je ne poznaš; zakaj ogenj se je vnel v jezi moji, ki bo plamtel zoper vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 15, 'O Gospod, ti veš vse; spomni se me in obišči me in maščuj me nad preganjalci mojimi! Ko si jim potrpežljiv, ne iztrebi me: spoznaj, da nosim sramoto zaradi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 16, 'Ko so prišle besede tvoje, sem jih sprejel, in bila mi je beseda tvoja v veselje in radost srca mojega, kajti kličem se po imenu tvojem, o Gospod, Bog vojnih krdel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 17, 'Nisem sedel v družbi šaljivcev in se radoval; zavoljo roke tvoje sem sedel samoten, ker si me napolnil z nevoljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 18, 'Zakaj je bolečina moja večna in rana moja smrtna? noče se zaceliti. Mi li boš res podoben prevarljivemu studencu, nestanovitnim vodam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 19, 'Zato pravi tako Gospod: Ako se preobrneš, te pripeljem nazaj, da bi stal pred menoj; in ako ločiš drago stvar od malovredne, bodeš kakor usta moja: obrniti se morajo oni k tebi, ne pa se ti obrniti k njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 20, 'In napravim te temu ljudstvu za bronast zid pretrden, in borili se bodo zoper tebe, a ne zmorejo te, zakaj jaz sem s teboj, da ti pomagam in te rešujem, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 15, 21, 'In otmem te iz roke hudobnih in rešim te iz pesti silovitnežev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 1, 'In prišla mi je beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 2, 'Ne jemlji si žene in ne imej sinov ali hčer v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 3, 'Kajti tako pravi Gospod o sinovih in hčerah, rojenih v tem kraju, in o njih materah, ki jih rodé, in o njih očetih, ki so jih rodili v tej deželi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 4, 'Za najhujšimi boleznimi bodo umrli, ne bode joka po njih in pokopani ne bodo; za gnoj bodo na površju zemlje; in od meča in glada bodo padali in njih trupla bodo za jed pticam pod nebom in zverem zemeljskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 5, 'Kajti tako pravi Gospod: Ne stopaj v hišo žalosti in ne hodi jokat in ne miluj jih; kajti vzel sem nazaj svoj mir od tega ljudstva, govori Gospod, blagovoljnost in usmiljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 6, 'I veliki i mali bodo pomrli v tej deželi; ne bodo jih pokopali in jokali se ne bodo za njimi, ne bodo si delali vrezkov, ne pleše zanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 7, 'in ne bodo jim delili kruha ob žalovanju, da bi potolažili koga za umrlega, in piti jim ne bodo dajali iz čaše tolažbe za očeta ali za mater katerega izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 8, 'Tudi v hišo pojedine ne hodi, da bi sedel med njimi, da bi jedel in da bi pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 9, 'Zakaj tako pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz storim, da pojde iz tega kraja pred vašimi očmi in v vaših dneh glas veselja in radosti glas, glas ženina in glas neveste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 10, 'In ko naznaniš temu ljudstvu vse te besede, če ti poreko: Zakaj je izgovoril Gospod zoper nas vso tisto preveliko nesrečo? in kaka je krivica naša ali kakšen je greh naš, s katerim smo grešili zoper Gospoda, Boga našega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 11, 'tedaj jim reci: Zato ker so me zapustili očetje vaši, govori Gospod, in so hodili za tujimi bogovi ter jih častili in se jim klanjali; mene pa so zapustili in niso držali postave moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 12, 'Vi pa ste delali huje kakor očetje vaši; kajti glej, vsak hodi po trmi hudobnega srca svojega, tako da ne poslušate mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 13, 'Zato vas vržem ven iz te dežele v deželo, ki je niste poznali ne vi, ne očetje vaši, in tam boste služili tujim bogovom noč in dan, ker vam ne dam milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 14, 'Zatorej, glej, pridejo dnevi, govori Gospod, ko se ne bo več reklo: Kakor resnično živi Gospod, ki je izpeljal Izraelce iz dežele Egiptovske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 15, 'ampak: Kakor resnično živi Gospod, ki je izpeljal Izraelce iz dežele severne in iz vseh krajev, kamor jih je bil izgnal. In jih bom pripeljal nazaj v njih deželo, katero sem bil dal njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 16, 'Glej, jaz pošljem k mnogim ribičem, govori Gospod, da jih bodo lovili kakor ribe; in nato pošljem k mnogim lovcem, da jih bodo lovili z vsake gore in z vsakega hriba, tudi iz skalnih lukenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 17, 'Kajti moje oči gledajo na vse njih poti, niso skrite obličju mojemu, tudi njih krivica ni prikrita mojim očem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 18, 'Ali poprej poplačam dvojno njih krivico in njih greh, zato ker so oskrunili deželo mojo s trupli svojih ostudnih stvari in so z gnusobami napolnili dediščino mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 19, 'O Gospod, moč moja in grad moj in pribežališče moje v dan stiske! K tebi pridejo narodi od koncev zemlje in poreko: Samo laž so podedovali očetje naši, ničemurnost in kar nič ne koristi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 20, 'Kako si more človek delati bogove, ki vendar niso bogovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 16, 21, 'Zato, glej, jim pokažem, takrat jim pokažem roko svojo in svojo moč, in spoznajo, da je ime moje Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 1, 'Greh Judov je zapisan s pisalom železnim, z ostjo demantovo, začrtan je na plošči njih srca in na rogovih vaših oltarjev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 2, 'njih otroci pa spominjajo svojih oltarjev in svojih Ašer pri zelenih drevesih, na gričih visokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 3, 'Goro Sionsko svojo s poljem, premoženje tvoje in vse zaklade tvoje izpostavim plenjenju in višave tvoje zavoljo greha po vseh mejah tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 4, 'In ti boš, to pa vsled krivde svoje, moral zapustiti dediščino svojo, ki sem ti jo bil dal; in storim, da boš hlapčeval sovražnikom svojim v deželi, ki je ne poznaš; kajti ogenj ste zanetili v jezi moji, ki bo gorel vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 5, 'Tako pravi Gospod: Proklet mož, ki ima upanje v človeka in meso šteje za ramo svojo, od Gospoda pa odstopa srce njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 6, 'Kajti podoben bode čisto golemu drevesu v pustinji in ne bo videl, da prihaja dobro, temuč prebival bo v suhih krajih v puščavi, v solnati, neobljudeni deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 7, 'Blagoslovljen mož, ki se zanaša na Gospoda in čigar upanje je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 8, 'Kajti podoben bode drevesu, vsajenemu poleg vodá; po reki zaganja korenine svoje in se ne boji, ko prihaja vročina, ampak zeleno je listje njegovo, in v letu suše ni v skrbi in ne preneha donašati sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 9, 'Varljivo je srce nad vse in hudo popačeno: kdo ga more doumeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 10, 'Jaz Gospod preiskujem srce in preizkušam ledice, da dam vsakemu po potih njegovih, po sadu dejanj njegovih. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 11, 'Kdor pridobiva bogastvo, pa po krivici, je kakor jerebica, ki sedi na jajcih, ki jih sama ni znesla; sredi svojih dni ga mora zapustiti in ob koncu svojem je neumen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 12, 'Prestol slave, vzvišen od začetka, je kraj svetišča našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 13, 'O upanje Izraelovo, Gospod! vsi, ki te zapuščajo, bodo osramočeni. Kateri odstopajo od mene, bodo v prst zapisani, ker so zapustili studenec živih vodá, Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 14, 'Ozdravi me, Gospod, in ozdravljen bom; reši me, in rešen bom, ker si hvala moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 15, 'Glej, oni mi pravijo: Kje je beseda Gospodova? Pride naj skoraj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 16, 'In vendar se jaz nisem umikal, da bi ne bil pastir za teboj, in pogubnega dne nisem želel; ti veš. Kar je prišlo iz ustnic mojih, je bilo pred tvojim obličjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 17, 'Ne bodi mi za strah, pribežališče moje si ob dnevi nesreče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 18, 'Osramočeni naj bodo preganjalci moji, jaz pa naj ne bom osramočen; obupavajo naj oni, a ne daj, da bi jaz obupal; pripelji zoper nje dan nesreče in z dvojno pogubo jih poteri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 19, 'Tako mi je velel Gospod: Pojdi, postavi se med vrata sinov ljudstva, skozi katera hodijo ven in noter kralji Judovi, in med vsaka vrata jeruzalemska');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 20, 'in jim reci: Poslušajte besedo Gospodovo, kralji Judovi in vsi Judje in vsi prebivalci v Jeruzalemu, ki hodite skozi ta vrata!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 21, 'Tako pravi Gospod: Varujte se zavoljo duš svojih, da si ne zadenete nobenega bremena v sobotni dan in ga ne prinesete v vrata jeruzalemska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 22, 'Tudi ne nosite bremen iz svojih hiš v sobotni dan in ne opravljajte nobenega dela, temuč posvečujte sobotni dan, kakor sem zapovedal vašim očetom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 23, 'ki pa niso poslušali in niso nagnili ušesa svojega, ampak postali so trdovratni, da niso poslušali in ne sprejeli nauka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 24, 'In če me boste pridno poslušali, govori Gospod, in ne boste nosili bremen skozi vrata tega mesta sobotni dan in boste posvečevali sobotni dan in ne opravljali v njem nobenega dela, se zgodi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 25, 'da bodo hodili skozi vrata tega mesta kralji in knezi, sedeči na prestolu Davidovem; na vozovih se bodo peljali in na konjih bodo jezdili oni in njih knezi, možje Judovi in prebivalci jeruzalemski; in to mesto bo obseljeno vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 26, 'In pride jih iz mest Judovih in iz krajev okoli Jeruzalema in iz dežele Benjaminove in iz nižave in gorovja in z Juga ter prineso žgalne in klalne in jedilne daritve in kadilo in prineso zahvalno žrtev v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 17, 27, 'Če me pa ne boste poslušali, da bi posvečevali sobotni dan in ne nosili bremen, gredoč skozi vrata jeruzalemska sobotni dan, tedaj zažgem ogenj v njegovih vratih, ki pokonča palače jeruzalemske in ne ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 2, 'Vstani in pojdi doli v hišo lončarjevo, in tam storim, da boš slišal besede moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 3, 'Šel sem torej doli v hišo lončarjevo, in glej opravljal je delo svoje na kolovratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 4, 'In posoda, ki jo je narejal iz ilovice, se je skazila v roki lončarjevi; in naredil je zopet iz nje drugo posodo, kakor se mu je prav zdelo narediti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 5, 'Tedaj mi je prišla beseda Gospodova, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 6, 'Ali bi vam ne mogel storiti kakor ta lončar, o hiša Izraelova? govori Gospod; glej, kakor ilovica v roki lončarjevi, tako ste vi, o hiša Izraelova, v roki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 7, 'Kadar govorim zoper kateri narod in zoper kraljestvo, da ga hočem iztrebiti in podreti in pogubiti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 8, 'pa se obrne tisti narod, ki sem zoper njega govoril, od hudobnosti svoje, tedaj mi bode žal zla, ki sem mu ga mislil storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 9, 'Kadar pa govorim o narodu in kraljestvu, da bom zidal in sadil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 10, 'pa stori, kar je hudo v mojih očeh, ne poslušaje glasu mojega, žal mi bode dobrot, ki sem ž njimi ga menil oblagodariti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 11, 'Zdaj torej ogovóri može Judove in prebivalce jeruzalemske, rekoč: Tako pravi Gospod: Glejte, jaz snujem zoper vas nesrečo in naklep mislim zoper vas; povrnite se vendar vsak s hudobnega pota svojega in dobra naredite pota svoja in dejanja svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 12, 'Pravijo pa: Zaman je; kajti po mislih svojih hočemo hoditi in vsak delati po trmi hudobnega srca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 13, 'Zatorej pravi tako Gospod: Poprašujte le med narodi, kdo je slišal kaj takega? Devica Izraelova je storila prav grdo stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 14, 'Ali zapusti sneg na Libanonu skalo na planjavi? Se li morejo posušiti mrzle vode, oddaleč šumljajoče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 15, 'Kajti pozabilo je mene ljudstvo moje; ničemurnim malikom je kadilo, in ti so storili, da se je spoteknilo na potih svojih, stezah starodavnih, da hodi po drugih hodnikih, po potu neuglajenem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 16, 'da napravi deželo svojo v stvar strmenju, vednemu zasmehovanju; kdorkoli pojde skozi njo, naj strmi in maje z glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 17, 'Kakor z jutrovim vetrom jih razkropim pred sovražnikom; s hrbtom, ne pa z obličjem se bom oziral vanje v času njih nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 18, 'Tedaj so pravili: Dejte, zmislimo naklepe zoper Jeremija; kajti postava ne pogine od duhovnika in svet od modrega in beseda od proroka; dejte, udarimo ga z jezikom in ne poslušajmo nobenih besed njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 19, 'Ozri se name, Gospod, in čuj glas prepirajočih se z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 20, 'Ali naj se vrača za dobro slabo? kajti izkopali so jamo za dušo mojo. Spomni se, da sem stal pred teboj, da bi dobro govoril zanje, da bi odvrnil od njih tvoj srd.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 21, 'Zato izpostavi njih sinove lakoti in izroči jih oblasti meča; in njih žene naj bodo brez otrok in vdove in njih možje naj umrjo pobiti; njih mladeniče naj meč zadene v boju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 22, 'Sliši naj se vpitje iz njih hiš, ko boš naglo pripeljal zoper nje krdelo, ker so kopali jamo, da bi me ujeli, in so zanke skrivaj stavili mojim nogam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 18, 23, 'Ti pa, Gospod, poznaš ves njih naklep meni v smrt; ne očisti njih krivice in njih greha ne izbriši izpred svojega obličja; temuč pahnejo se naj v spotiko pred tvojimi očmi, v času jeze svoje ravnaj zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 1, 'Tako pravi Gospod: Pojdi kupit lončen vrč od lončarja ter vzemi s seboj starejšin ljudstva in starejšin duhovnikov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 2, 'in pojdi ven iz mesta v dolino sinú Hinomovega, ki je pred vhodom Čepinjskih vrat, ter oznanjaj tam besede, ki ti jih bom rekel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 3, 'in reci: Poslušajte besedo Gospodovo, kralji Judovi in prebivalci jeruzalemski! Tako pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz pripeljem nesrečo nad ta kraj; kdorkoli jo bo slišal, mu bo zvenelo po ušesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 4, 'Zato ker so me zapustili in so tuj storili ta kraj, ker so na njem kadili tujim bogovom, ki jih niso poznali ne oni, ne njih očetje in kralji Judovi, in so napolnili ta kraj s krvjo nedolžnih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 5, 'in so sezidali višave Baalu, da bi z ognjem žgali otroke svoje v žgalne daritve Baalu, česar nisem bil zapovedal in ne govoril in kar mi ni prišlo na misel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 6, 'zato, glej, pridejo dnevi, govori Gospod, ko se ta kraj ne bo več imenoval Tofet ali dolina sinú Hinomovega, ampak Dolina moritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 7, 'In prazen naredim sklep Judov in Jeruzalemov na tem kraju in storim, da se zgrudijo od meča pred sovražniki svojimi in pod pestjo njih, ki jim strežejo po življenju; in njih trupla dam za jed pticam nebeškim in zverem zemeljskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 8, 'In to mesto postavim za stvar strmenju in zasmehovanju; kdorkoli pojde mimo njega, bo strmel in žvižgal zavoljo vseh šib njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 9, 'In storim, da bodo jedli meso sinov svojih in hčer svojih meso, in vsak bo jedel prijatelja svojega meso, v obleganju in stiski, s katero jih bodo stiskali njih sovražniki in oni, ki jim strežejo po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 10, 'Nato stareš tisti vrč pred očmi mož, ki pojdejo s teboj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 11, 'in jim porečeš: Tako pravi Gospod nad vojskami: Tako starem to ljudstvo in to mesto, kakor kdor stare lončarjevo posodo, ki se ne more več popraviti. In v Tofetu se bodo pokopavali, ker ne bode nobenega drugega kraja za pokopavanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 12, 'Tako storim temu kraju in njegovim prebivalcem, govori Gospod, in to mesto naredim podobno Tofetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 13, 'In hiše jeruzalemske in hiše kraljev Judovih bodo kakor kraj Tofetov vse nesnažne: vse tiste hiše, na katerih strehah so kadili vsej vojski nebes in pitne daritve darovali tujim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 14, 'Nato se vrne Jeremija iz Tofeta, kamor ga je bil poslal Gospod prorokovat, in stopi v vežo hišo Gospodove ter reče vsemu ljudstvu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 19, 15, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz pripeljem zoper to mesto in zoper vsa mesta njegova vso tisto nesrečo, ki sem jo izgovoril zoper njega, ker so postali trdovratni, da niso poslušali mojih besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 1, 'Ko je pa Pashur, Imerjev sin, duhovnik, ki je bil višji glavar v hiši Gospodovi, slišal Jeremija, prorokujočega te besede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 2, 'udari Pashur Jeremija proroka in ga dene v klado, ki je bila v zgornjih vratih Benjaminovih pri hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 3, 'Bilo je pa drugi dan, ko je bil Pashur Jeremija potegnil iz klade, da mu reče Jeremija: Ne Pashur kliče Gospod ime tvoje, ampak Magor misabib.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 4, 'Kajti tako pravi Gospod: Glej, jaz te hočem navdati s strahom, tebe in vse prijatelje tvoje; in zgrudijo se od meča sovražnikov svojih, in tvoje oči bodo videle to; in izdam vsega Judo v roko kralja babilonskega, ki jih ujete odpelje v Babilon in jih udari z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 5, 'Dam tudi vse bogastvo tega mesta in ves pridelek njegov in karkoli ima dragega, sploh vse zaklade kraljev Judovih izdam v roko njih sovražnikov: in jih oplenijo in ujemó in jih odpeljejo v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 6, 'Tudi ti, Pashur, in vsi domačini tvoji pojdete v sužnost; in prideš v Babilon in tam umreš, in ondi boš pokopan ti in vsi prijatelji tvoji, ki si jim prorokoval lažnivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 7, 'Pregovarjal si me, Gospod, in dal sem se pregovoriti; močnejši si od mene, zato si zmagal. V posmeh sem ves dan, vsak me zasmehuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 8, 'Kajti kadarkoli izpregovorim, moram vpiti, ‚Silovitost in razdejanje‘kričati; tako mi je beseda Gospodova v sramoto in v zasmeh ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 9, 'Ko pa rečem: Ne bom Ga omenjal, ne govori več v imenu Njegovem, tedaj je to srcu mojemu kakor goreč ogenj, zaprt v mojih kosteh, in pešam od prenašanja in strpeti ne morem več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 10, 'Kajti slišal sem pregrešni govor mnogih, strašenje od vseh strani: „Ovadite, pa ga ovadimo!“Vsi zaupni prijatelji moji strežejo na padec moj, govoreč: „Morda se da pregovoriti in ga zmagamo, in maščevali se bomo nad njim!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 11, 'Ali Gospod je z menoj, podoben junaku strašnemu, zato se bodo oni, ki me preganjajo, spoteknili in ne zmagali; sram jih bode silno, ker se jim ne posreči; večna njih sramota se ne bo mogla pozabiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 12, 'Torej, Gospod nad vojskami, ki izkušaš pravičnega, pregleduješ obisti in srce, vidim naj maščevanje tvoje nad njimi, ker sem tebi razodel pravdo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 13, 'Prepevajte Gospodu, hvalite Gospoda, ker je otel dušo siromakovo iz roke hudobnikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 14, 'Proklet dan, ko sem se rodil; dan, ko me je povila mati moja, ne bodi blagoslovljen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 15, 'Proklet tisti mož, ki je sporočil očetu mojemu, rekoč: Rodil se ti je sin, in silno ga je razveselil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 16, 'In tisti mož bodi podoben mestom, ki jih je razdejal Gospod, in ni se kesal, in sliši naj zjutraj vpitje in bojno kričanje v času opoldanskem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 17, 'ker me ni usmrtil že v maternici; in bila bi mati moja moj grob in nje maternica vedno noseča!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 20, 18, 'Zakaj sem prišel iz maternice, da bi videl preglavico in žalost in bi v sramoti ginili dnevi moji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, ko je k njemu poslal kralj Zedekija Pashurja, Malkijevega sina, in Zefanija, Maasejevega sina, duhovnika, da naj rečeta:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 2, 'Poprašaj, prosim, za nas Gospoda, ker se Nebukadnezar, kralj babilonski, vojskuje zoper nas; morebiti stori Gospod z nami po vseh čudovitih delih svojih, da pojde on od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 3, 'Rekel pa jima je Jeremija: Tako recita Zedekiju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 4, 'Tako pravi Gospod, Bog Izraelov: Glej, jaz obrnem nazaj vojno orožje, ki je v vaših rokah, ki se ž njim bojujete zoper kralja babilonskega in zoper Kaldejce, ki vas oblegajo zunaj zida, in ga skupim sredi tega mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 5, 'In sam se bom bojeval z vami z iztegnjeno roko in z močno ramo, in to z jezo in srdom in s togoto veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 6, 'In udarim prebivalce tega mesta, ljudi in živino; od kuge velike bodo mrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 7, 'Potem pa, govori Gospod, izdam Zedekija, kralja Judovega, in hlapce njegove in ljudstvo, kar ga namreč preostane v tem mestu od kuge, od meča in od glada, v roko Nebukadnezarja, kralja babilonskega, in v roko njih sovražnikov in v roko onih, ki jim strežejo po življenju; in on jih udari z ostrino meča, ne bo jim prizanašal in milosti ne bo poznal in usmiljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 8, 'Temu ljudstvu pa reci: Tako pravi Gospod: Glejte, jaz vam predlagam pot življenja in pot smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 9, 'Kdor ostane v tem mestu, umre od meča ali glada ali kuge; kdor pa pojde ven in uskoči h Kaldejcem, ki vas oblegajo, bo živel in življenje njegovo mu bode namesto plena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 10, 'Kajti obrnil sem srdito obličje svoje proti temu mestu v hudo in ne v dobro, govori Gospod; v roko kralja babilonskega bo izdano, in ga sežge z ognjem. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 11, 'Kar se pa tiče hiše kralja Judovega, poslušajte besedo Gospodovo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 12, 'O hiša Davidova, tako pravi Gospod: Delajte vsako jutro pravico in otmite ga, ki trpi ropanje, iz roke zatiralca, da ne šine kakor ogenj srd moj in gorí neugasno zavoljo hudobe vaših dejanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 13, 'Glej, jaz sem zoper tebe, o prebivalka v dolini in na skali tiste ravnine, govori Gospod, zoper vas, ki govorite: Kdo pride doli proti nam? ali kdo stopi v prebivališča naša?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 21, 14, 'In pokoril vas bom po sadu vaših dejanj, govori Gospod; in zanetim ogenj v gozdu njenem, ki pokonča vse, kar stoji okoli nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 1, 'Tako pravi Gospod: Idi doli v hišo kralja Judovega in govóri tam to besedo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 2, 'in reci: Poslušaj besedo Gospodovo, kralj Judov, ki sediš na prestolu Davidovem, ti in hlapci tvoji in ljudstvo tvoje, ki hodite skozi ta vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 3, 'Tako pravi Gospod: Strezite sodbi in pravičnosti in otmite ga, ki trpi rop, iz roke zatiralca; tujcu, siroti in vdovi ne delajte sile, ne bodite siloviti ter nedolžne krvi ne prelivajte v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 4, 'Kajti če boste res izpolnjevali to besedo, pojdejo skozi vrata te hiše kralji, sedeči za Davida na prestolu njegovem, na vozovih in na konjih, sam kralj s hlapci svojimi in z ljudstvom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 5, 'Toda če ne boste poslušali teh besed, pri sebi prisegam, govori Gospod, da pride v razdejanje ta hiša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 6, 'Kajti tako pravi Gospod o hiši kralja Judovega: Gilead si mi, glava Libanona; resnično te premenim v puščavo, v mesto brez prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 7, 'In pripravim zoper tebe pogubnike, vsakega z orodjem svojim, ki posekajo najlepše cedre tvoje in jih vržejo na ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 8, 'Ko torej pojdejo mnoga ljudstva mimo tega mesta, če vprašajo drug drugega: Zakaj je Gospod storil tako temu velikemu mestu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 9, 'tedaj poreko: Zato ker so zapustili zavezo Gospoda, Boga svojega, in so se klanjali tujim bogovom ter jih častili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 10, 'Ne jokajte po mrtvem in ne tožite po njem; pač pa jokajte po odhajajočem, ker se ne povrne več, da bi videl svoje domovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 11, 'Kajti tako pravi Gospod o Salumu, sinu Josijevem, kralju Judovem, ki je vladal namesto Josija, očeta svojega, in ki je odšel iz tega kraja: Ne povrne se več sem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 12, 'ampak v kraju, kamor so ga odpeljali, tam umrje; in ne bo več videl te dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 13, 'Gorje mu, kdor zida hišo svojo s krivico in izbe svoje z nepravičnostjo, ki zastonj zahteva hlapčevanje prijatelja svojega in mu ne daje zaslužka njegovega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 14, 'ki govori: „Sezidam si hišo prostorno in izbe obširne“, in si napravi mnogo oken in cedrovo streho in stene prebarva z rumenico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 15, 'Boš li zato kraljeval, ker se hočeš odlikovati s cedrovino? Ali ni jedel in pil tvoj oče in delal pravice in pravičnosti? Takrat se mu je godilo dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 16, 'Sodil je pravdo siromakovo in ubožčevo, tedaj je bilo dobro. Se li to ne pravi: spoznati mene? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 17, 'Nikamor ne gledajo oči tvoje in srce tvoje kakor na dobiček tvoj in na nedolžno kri, katero bi prelival, in na odiranje in na zatiranje, katero bi počenjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 18, 'Zatorej govori tako Gospod o Jojakimu, sinu Josijevem, kralju Judovem: Ne bodo se jokali za njim: Gorje, moj brat, ali: Gorje, sestra! Ne bodo se jokali za njim: Gorje, gospod, ali: Gorje, lepota njegova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 19, 'Kakor osel bo pokopan, vlekli ga bodo in vrgli onkraj vrat jeruzalemskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 20, 'Pojdi gori na Libanon in vpij in na Basanu povzdigni svoj glas; vpij tudi z Abarima, kajti pobiti so vsi ljubitelji tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 21, 'Govoril sem ti v blagostanju tvojem; rekla si: Ne bom poslušala. Ta je bila pot tvoja od otročjih let tvojih, da nisi poslušala mojega glasú.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 22, 'Vse pastirje tvoje odnese veter in ljubitelji tvoji odidejo v sužnost. Res, tedaj te bode sram in z rdečico se obliješ zavoljo vse hudobnosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 23, 'O ti, ki posedaš na Libanonu, ki gnezdiš na samih cedrah, koliko boš pomilovanja vredna, ko te popadejo muke, bolečina kakor porodnice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 24, 'Kakor res živim jaz, govori Gospod: ko bi bil tudi Konija, sin Jojakima, kralja Judovega, pečatni prstan na desni roki moji, vendar bi te odtrgal odondod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 25, 'In izdam te v roko tistih, ki iščejo duše tvoje, in v roko njih, ki se jih bojiš, namreč v roko Nebukadnezarja, kralja babilonskega, in v roko Kaldejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 26, 'In vržem te ven in mater tvojo, ki te je rodila, v tujo deželo, kjer nista bila rojena, in tam umreta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 27, 'V deželo pa, kamor jih bo vleklo hrepenenje, da bi se povrnili tja, tja se ne vrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 28, 'Ali je tisti mož, Konija, zaničevana, razbita posoda? je li orodje, v katerem ni nobenega veselja? Zakaj bi bili ven vrženi, on in seme njegovo, in vrženi v deželo, katere ne poznajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 29, 'O dežela, dežela, dežela, poslušaj besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 22, 30, 'Tako pravi Gospod: Zapišite tega moža, da bode brez otrok, mož, ki ne bo imel sreče v svojih dneh; kajti nobeden ne bo imel sreče iz zaroda njegovega, da bi sedel na prestolu Davidovem in gospodoval dalje Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 1, 'Gorje pastirjem, ki pogubljajo in raztresajo ovce paše moje, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 2, 'Zatorej pravi tako Gospod, Bog Izraelov, zoper tiste pastirje, ki paso ljudstvo moje: Vi raztresate ovce moje in jih razganjate, pa jih ne obiskujete; glej, jaz bom kaznoval nad vami hudobnost vaših dejanj, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 3, 'Jaz zberem ostanek svojih ovac iz vseh krajev, kamor sem jih razkropil, in jih pripeljem nazaj v njih stajo, in se bodo plodile in množile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 4, 'In jim postavim pastirje, ki jih bodo pasli; in ne bodo se več bale, ne plašile, in nobene več ne bodo pogrešili, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 5, 'Glej, dnevi pridejo, govori Gospod, ko zbudim Davidu Odraslek pravičen; in bo vladal kot kralj, srečo bo imel in delal pravo in pravičnost v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 6, 'V dnevih njegovih bo rešen Juda, in Izrael bo na varnem prebival; in to je ime njegovo, s katerim ga bodo klicali: Gospod, pravičnost naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 7, 'Zato, glej, pridejo dnevi, govori Gospod, ko se ne poreče več: Kakor res živi Gospod, ki je peljal Izraela iz dežele Egiptovske,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 8, 'ampak: Kakor živi Gospod, ki je izpeljal in pripeljal seme hiše Izraelove iz severne dežele in iz vseh krajev, kamor sem jih bil odgnal! In bodo prebivali v deželi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 9, 'O prorokih. Potrto je srce v meni, drobé se vse kosti moje; sem kakor pijan in podoben možu, ki ga je premagalo vino, zavoljo Gospoda in zavoljo besed svetosti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 10, 'Kajti prešeštnikov polna je ta dežela, kajti zavoljo prokletstva žaluje ta dežela, suhi so pašniki v puščavi; in njih tek je hudoben in njih moč krivična.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 11, 'Ker prorok in duhovnik sta enako skrunilca svetega; celo v hiši svoji sem našel njiju hudobnost, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 12, 'Zato jim bode njih pot kakor prepolzki kraji v temi, zadenejo se na njem in padejo; zakaj pošljem nesrečo zoper nje, leto njih obiskovanja, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 13, 'Pri prorokih samarijskih vidim nespamet: prorokovali so po Baalu in zapeljevali ljudstvo moje Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 14, 'Ali na prorokih jeruzalemskih vidim strahovito reč: prešeštvujejo in hodijo v lažnivosti in potrjujejo roke hudodelcem, da se ne povrne nobeden od hudobnosti svoje; vsi tisti so mi kakor Sodoma in prebivalci njegovi kakor Gomora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 15, 'Zatorej pravi tako Gospod nad vojskami o tistih prorokih: Glej, jaz jih bodem sitil s pelinom in jih napajal s sokom trobeličnim; ker od prorokov jeruzalemskih je šla skrunitev svetega po vsej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 16, 'Tako pravi Gospod nad vojskami: Ne poslušajte besed tistih prorokov, ki vam prorokujejo; ničermurnosti vas učijo, svojega srca prikazen vam govore, ne iz ust Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 17, 'Govoré neprenehoma njim, ki me zametajo: Rekel je Gospod: mir vam bode; in vsakemu, ki hodi po trmi svojega srca, govoré: Ne pride nesreča nad vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 18, 'Kajti kdo je stal v svetu Gospodovem in je videl ali čul besedo njegovo? Kdo je pazil na besedo njegovo in jo slišal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 19, 'Glej, vihar Gospodov, iz srda njegovega, je prihrumel, vrtinčast vihar: zgrne se nad glavo brezbožnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 20, 'Ne odvrne se jeza Gospodova, dokler ne izpolni in dokler ne izvrši misli srca svojega. V poslednjih dnevih boste to jasno razumeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 21, 'Nisem pošiljal tistih prorokov, sami so tekali; nisem jim govoril, sami so prorokovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 22, 'Ko bi bili pa stali v svetu mojem, bi bili oznanjali ljudstvu mojemu besede moje in jih odvrnili ž njih hudobnega pota in od hudobnosti njih dejanj. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 23, 'Ali sem jaz Bog le od blizu, govori Gospod, ne tudi Bog v daljavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 24, 'Ali se more kdo skriti v zakotju, da bi ga ne videl jaz? govori Gospod. Ali nisem jaz, ki polnim nebesa in zemljo? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 25, 'Slišal sem, kaj govore tisti proroki, ki prorokujejo laži v imenu mojem in pravijo: Sanjalo se mi je, sanjalo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 26, 'Doklej neki bode to v srcu tistih prorokov, ki prorokujejo laži, ki prorokujejo prevare srca svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 27, 'ki nameravajo storiti, da ljudstvo moje pozabi moje ime, s sanjami svojimi, ki jih pripovedujejo drug drugemu, prav kakor so njih očetje pozabili ime moje zavoljo Baala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 28, 'Prorok, ki ima sanje, naj pripoveduje sanje; in kdor ima besedo mojo, naj govori besedo mojo v resnici. Kaj tista slama s pšenico? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 29, 'Ni li beseda moja kakor ogenj, govori Gospod, in kakor kladivo, ki raztrupa skalo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 30, 'Zatorej, glej, jaz sem zoper tiste proroke, govori Gospod, ki kradejo besede moje drug drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 31, 'Glej, jaz sem zoper proroke, govori Gospod, ki rabijo svoj jezik in pravijo: Govor Božji je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 32, 'Glej, jaz sem zoper nje, ki prorokujejo sanje lažnive, govori Gospod, ki jih pripovedujejo in zapeljujejo ljudstvo moje s svojimi lažmi in z bahanjem svojim; jaz pa jih vendar nisem poslal in jim nisem zapovedal, in ne koristijo temu ljudstvu nikakor, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 33, 'Ko te bo torej vprašalo to ljudstvo ali kak prorok ali duhovnik, rekoč: Kaj je breme Gospodovo? tedaj jim povej: Vi ste breme, in: Zavržem vas, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 34, 'Zastran proroka in duhovnika in ljudstva, ki poreče: Breme Gospodovo –: kaznoval bom tistega moža in hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 35, 'Takole bi morali govoriti vsak svojemu prijatelju in vsak svojemu bratu: Kaj je odgovoril Gospod? in: Kaj je rekel Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 36, '„Bremena Gospodovega “pa ne omenjajte več; kajti breme bode vsakemu njegova lastna beseda, ker preobračate besede živega Boga, Gospoda nad vojskami, našega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 37, 'Tako reci proroku: Kaj ti je odgovoril Gospod? in: Kaj je rekel Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 38, 'Toda ker pravite „Breme Gospodovo “, zato pravi Gospod: Ker rabite tisto besedo „Breme Gospodovo “, dasi sem poslal k vam sporočat: Ne govorite: „Breme Gospodovo “:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 39, 'zatorej, glejte, vas zapustim docela in zavržem vas in mesto, katero sem dal vam in očetom vašim, izpred obličja svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 23, 40, 'in naložim vam večno sramoto in večno nečast, ki se ne bo mogla pozabiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 1, 'Videti mi je dal Gospod – in glej: dva koša smokev, postavljena pred tempelj Gospodov, potem ko je bil Nebukadnezar, kralj babilonski, odpeljal v ujetništvo Jekonija, sina Jojakima, kralja Judovega, in kneze Judove in rokodelce in kovače iz Jeruzalema in jih pripeljal v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 2, 'V enem košu so bile prav dobre smokve, kakršne so zgodnje smokve, v košu drugem pa so bile smokve prav slabe, ki jih ni moči jesti, tako so bile slabe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 3, 'In Gospod mi reče: Kaj vidiš Jeremija? In rečem: Smokve; dobre smokve so prav dobre, slabe pa so prav slabe, da jih ni moči jesti, tako so slabe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 4, 'Tedaj pride beseda Gospodova k meni, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 5, 'Tako pravi Gospod, Bog Izraelov: Kakor tiste dobre smokve, tako bom spoznal ujetnike Judove, ki sem jih poslal iz tega kraja v deželo Kaldejsko, na dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 6, 'Ker obrniti hočem svoje oči nanje v njih dobro, in jih nazaj pripeljem v to deželo, in jih bom zidal in ne podiral, in sadil jih bom, ne roval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 7, 'In dal jim bom srce, da me spoznajo, da sem Gospod, in bodo mi ljudstvo in jaz jim bodem Bog, ko se povrnejo k meni iz vsega srca svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 8, 'Kakor pa tiste slabe smokve, ki jih ni moči jesti, ker so tako slabe: res, tako pravi Gospod, tako izpostavim Zedekija, kralja Judovega, in kneze njegove in ostanek Jeruzalemov, kar jih je ostalo v tej deželi in kar jih prebiva v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 9, 'Izpostavim jih, pravim, pestenju, nesreči po vseh kraljestvih zemlje, da bodo v sramoto in pregovor, v zasmehovanje in preklinjane v vseh krajih, kamor jih odženem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 24, 10, 'In pošljem nadnje meč, lakoto in kugo, dokler ne poginejo iz dežele, ki sem jo bil dal njim in njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 1, 'Beseda, ki je prišla Jeremiju zoper vse ljudstvo Judovo v četrtem letu Jojakima, sinú Josijevega, kralja Judovega, ki je bilo prvo leto Nebukadnezarja, kralja babilonskega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 2, 'katero je govoril prorok Jeremiju vsemu ljudstvu Judovemu in vsem prebivalcem jeruzalemskim, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 3, 'Od trinajstega leta Josija, sinu Amonovega, kralja Judovega, do tega dne, to je triindvajset let, je govoril Gospod k meni, in govoril sem vam od ranega jutra in neprenehoma, pa niste poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 4, 'Pošiljal je tudi Gospod k vam vse hlapce svoje, proroke, od ranega jutra in neprenehoma, pa niste poslušali in še ušesa svojega niste nagnili, da bi poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 5, 'In je govoril: Povrnite se vendar vsak s svojega hudobnega pota in od hudobnosti dejanj svojih, in ostanete v deželi, ki vam jo je podelil Gospod in očetom vašim, od veka do veka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 6, 'in ne hodite za tujimi bogovi, da bi jih častili in se jim klanjali, in ne dražite me z delom svojih rok, in ne storim vam hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 7, 'Ali niste me poslušali, govori Gospod, da bi me dražili z delom svojih rok, sebi v nesrečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 8, 'Zatorej pravi tako Gospod nad vojskami: Zato ker niste poslušali besed mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 9, 'glejte, pošljem in zberem vse severne rodovine, govori Gospod, pošljem tudi k Nebukadnezarju, kralju babilonskemu, in jih pripeljem zoper to deželo in zoper prebivalce njene in zoper vse te okolne narode; in jih s prokletjem pokončam in jih dam v strmenje in posmehovanje in razdejanje brez konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 10, 'In storim, da izgine izmed njih glas veselja in radosti glas, glas ženina in glas neveste, ropot mlinov in svetilnice luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 11, 'In vsa ta dežela bo razdejana in opustošena, in ti narodi bodo služili kralju babilonskemu sedemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 12, 'In zgodi se, ko se izpolni sedemdeset let, da bom kaznoval kralja babilonskega in oni narod, govori Gospod, za njih krivičnost, tudi deželo Kaldejsko, in jo premenim v puščavo večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 13, 'In nad ono deželo izpolnim vse besede svoje, ki sem jih govoril zoper njo; karkoli je pisano v tej knjigi, kar je prorokoval Jeremija zoper vse narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 14, 'Kajti tudi nje bodo zasužnjili mnogi narodi in veliki kralji; tedaj jim povrnem po njih delih in po tem, kar so storile njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 15, 'Kajti tako mi je rekel Gospod, Bog Izraelov: Vzemi to čašo vina srdú iz roke moje ter jo daj piti vsem narodom, h katerim te pošiljam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 16, 'da naj pijo in tavajo in divjajo, zavoljo meča, ki ga jaz pošljem mednje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 17, 'Torej sem vzel čašo iz roke Gospodove in jo dal piti vsem tistim narodom, h katerim me je poslal Gospod:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 18, 'Jeruzalemu in mestom Judovim in njih kraljem in njih knezom, izdavši jih v opustošenje, strmenje, zasmehovanje in preklinjanje, kakor je današnji dan;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 19, 'Faraonu, kralju egiptovskemu, in hlapcem njegovim in knezom njegovim in vsemu njegovemu ljudstvu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 20, 'in vsej tisti mešanici in vsem kraljem v deželi Uzovi in vsem kraljem v deželi Filistejcev, Askelonu in Gazi in Ekronu in ostanku v Asdodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 21, 'Edomu in Moabu in sinom Amonovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 22, 'in vsem kraljem tirskim in vsem kraljem sidonskim in kraljem na otokih, ki so onkraj morja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 23, 'Dedanu in Temi in Buzu in vsem ob strani glave ostriženim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 24, 'in vsem kraljem arabskim in vsem kraljem mešanega ljudstva, ki prebiva v puščavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 25, 'in vsem kraljem v Zimri in vsem kraljem v Elamu in vsem kraljem medskim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 26, 'in vsem kraljem na severu, bližnjim in daljnim, zaporedoma, in vsem kraljestvom sveta, kar jih je na površju zemlje; in kralj v Šešaku bo pil za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 27, 'In porečeš jim: Tako pravi Gospod nad vojskami, Bog Izraelov: Pijte in upijanite se; tudi bljujte in padite tako, da ne vstanete več, zavoljo meča, ki ga jaz pošljem med vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 28, 'Ako se pa bodo branili prejeti čašo iz roke tvoje, da pijo, jim reci: Tako pravi Gospod nad vojskami: Vsekakor boste pili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 29, 'Kajti glejte, v tistem mestu, ki se kliče po mojem imenu, sem jaz začel tepsti z nesrečami, in vi bi bili čisto brez kazni? Ne bodete brez kazni, kajti meč pokličem jaz zoper vse prebivalce zemlje, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 30, 'Ti torej jim prorokuj vse tiste besede in jim reci: Gospod bo rjovel z višave in iz prebivališča svetosti svoje bo zagnal svoj glas, močno bo rjovel zoper stajo svojo, zažene vpitje, kakršno je mastilcev, zoper vse prebivalce na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 31, 'Šum pride prav do kraja zemlje; zakaj Gospod ima prepir z narodi, pravdal se bo z vsem mesom; brezbožnike izroči meču, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 32, 'Tako pravi Gospod nad vojskami: Glej, nesreča pojde od naroda do naroda, in silen vihar se vzdigne od skrajnih strani zemeljskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 33, 'In ubitih od Gospoda bo tisti dan ležalo od enega konca zemlje do drugega; ne bo se žalovalo po njih, ne bodo jih pobirali, ne pokopavali; za gnoj bodo na površju zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 34, 'Tulite, pastirji, in vpijte in valjajte se po pepelu, vi prvaki črede! kajti dopolnjeni so dnevi vaši, da boste poklani; in razkropim vas, ko popadate kakor drage posode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 35, 'In pribežališče premine pastirjem in prilika rešiti se prvakom črede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 36, 'Čuj! vpijte pastirjev in tuljenje prvakov črede; kajti Gospod pustoši njih pašnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 37, 'In podero se staje, ki imajo mir, zavoljo srdite jeze Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 25, 38, 'Zapustil je kakor mlad lev brlog svoj; kajti njih dežela je postala puščava pod ostrino pokončevalnega meča in od togote jeze Njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 1, 'V začetku kraljestva Jojakima, sinú Josijevega, kralja Judovega, je prišla ta beseda od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 2, 'Tako pravi Gospod: Stopi na dvorišče hiše Gospodove, da govoriš pred vsemi mesti Judovimi, ki se pridejo klanjat v hiši Gospodovi, vse besede, ki ti jih ukazujem govoriti jim; ne odtegni besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 3, 'Morebiti bodo poslušali ter se odvrnili vsak s svojega hudobnega pota, da mi bode žal hudega, katero jim mislim storiti zavoljo hudobnosti njih dejanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 4, 'Zato jim porečeš: Tako pravi Gospod: Ako me ne boste poslušali, da bi hodili po moji postavi, ki sem vam jo postavil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 5, 'poslušajoč besede služabnikov mojih prorokov, ki jih jaz pošiljam k vam; od ranega jutra jih pošiljam, pa niste še poslušali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 6, 'gotovo naredim to hišo podobno Silu in to mesto dam v prokletstvo pri vseh narodih na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 7, 'Slišali pa so duhovniki in proroki in vse ljudstvo Jeremija, govorečega te besede v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 8, 'In zgodi se, ko je Jeremija nehal govoriti vse, kar mu je bil ukazal Gospod govoriti vsemu ljudstvu, da ga zgrabijo duhovniki in proroki in vse ljudstvo, rekoč: Umreti moraš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 9, 'Zakaj si prorokoval v imenu Gospodovem, govoreč: Podobna bode Silu ta hiša in to mesto bo razdejano, da ne bode nobenega prebivalca? In zbiralo se je vse ljudstvo okrog Jeremija v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 10, 'Ko so pa slišali knezi Judovi te besede, pridejo iz hiše kraljeve v hišo Gospodovo in sedejo pri vhodu novih vrat Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 11, 'Nato ogovore duhovniki in proroki kneze in vse ljudstvo, rekoč: Smrti vreden je ta mož, kajti prorokoval je zoper to mesto, kakor ste slišali na svoja ušesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 12, 'Tedaj ogovori Jeremija vse kneze in vse ljudstvo in reče: Gospod me je poslal prorokovat zoper to hišo in zoper to mesto vse besede, ki ste jih slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 13, 'Sedaj torej naredite dobra svoja pota in dejanja in poslušajte glas Gospoda, Boga svojega: in žal bode Gospodu zla, katero je izrekel zoper vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 14, 'Kar se pa tiče mene, glejte, v roki vaši sem, storite mi, kar se vidi dobro in pravo v vaših očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 15, 'Vendar vsekakor vedite, če me umorite, nedolžno kri naložite sebi in temu mestu in prebivalcem njegovim; zakaj v resnici me je Gospod poslal, govorit vam na ušesa vse tiste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 16, 'Tedaj so rekli knezi in vse ljudstvo duhovnikom in prorokom: Ta mož ni vreden smrti, ker nam je govoril v imenu Gospoda, našega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 17, 'In vstali so nekateri izmed deželnih starejšin in govorili vsemu zboru ljudstva, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 18, 'Miha iz Moraste je prorokoval v dnevih Ezekija, kralja Judovega, in govoril je vsemu ljudstvu Judovemu takole: Tako pravi Gospod nad vojskami: Sion se bo oral kakor njiva in mesto jeruzalemsko bode groblja in gora te hiše bo z gozdom obrasten grič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 19, 'So li ga kar usmrtili Ezekija, kralj Judov, in ves Juda? Ali se ni bal Gospoda in prosil blagovoljnosti Gospodove? In žal je bilo Gospodu hudega, kar je bil izrekel proti njim. Mi pa hočemo storiti veliko hudobnost zoper duše svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 20, '(In bil je tudi mož, prorokujoč v imenu Gospodovem, Urija, sin Semajev iz Kirjat-jearima; in prorokoval je zoper to mesto in zoper to deželo prav kakor Jeremija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 21, 'In ko je slišal kralj Jojakim besede njegove in vsi mogočniki njegovi in vsi knezi, ga je iskal usmrtiti kralj; to je slišal Urija in se zbal ter je pobegnil in prišel v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 22, 'Ali poslal je kralj Jojakim nekatere v Egipt, Elnatana, sina Akborjevega, in druge može ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 23, 'ki so izpeljali Urija iz Egipta in ga pripeljali pred kralja Jojakima; ta ga je udaril z mečem in vrgel truplo njegovo na grobe preprostega ljudstva.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 26, 24, 'Toda roka Ahikama, sina Safanovega, je bila na strani Jeremiju, da ga niso izdali v roko ljudstva, da bi ga usmrtilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 1, 'V začetku kraljestva Jojakima, sina Josijevega, kralja na Judovem, je prišla ta beseda Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 2, 'Tako mi je rekel Gospod: Napravi si spone in jarme ter si jih deni na vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 3, 'Nato jih pošlji kralju Edomcev in kralju Moabcev in kralju sinov Amonovih in kralju v Tiru in kralju v Sidonu po poslancih, ki pridejo v Jeruzalem k Zedekiju, kralju Judovemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 4, 'in véli jim, da naj sporoče svojim gospodom: Tako pravi Gospod nad vojskami, Bog Izraelov: Povejte gospodom svojim tole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 5, 'Jaz sem naredil zemljo, ljudi in živali, ki so na površju zemeljskem, s svojo veliko krepkostjo in z iztegnjeno ramo svojo; zato jo dajem, komur se mi prav vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 6, 'In zdaj sem dal jaz vse dežele v roko Nebukadnezarju, kralju babilonskemu, hlapcu svojemu, in tudi zveri poljske sem mu dal, da naj mu služijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 7, 'In služili mu bodo vsi narodi in sinu in vnuku njegovemu, dokler ne pride tudi njegovi deželi čas, ko ga v sužnost spravijo mnogi narodi in veliki kralji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 8, 'Narod pa in kraljestvo, ki ne bo hotelo služiti Nebukadnezarju, kralju babilonskemu, in ne ukloni vratu svojega v jarem kralja babilonskega, tisti narod, govori Gospod, bom kaznoval z mečem in lakoto in kugo, dokler jih ne pokončam z roko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 9, 'Vi torej ne poslušajte prorokov in vedežev svojih in sanj svojih in zvezdogledov in čarovnikov svojih, ki vam govore in pravijo: Ne boste služili kralju babilonskemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 10, 'Kajti laž vam oni prorokujejo, da bi vas spravili daleč od dežele vaše in da vas bom pregnal, da poginete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 11, 'Narod pa, ki ukloni vrat svoj v jarem kralja babilonskega in mu bo služil, pustim v njegovi deželi, govori Gospod, da naj jo obdeluje in prebiva v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 12, 'In govoril sem Zedekiju, kralju Judovemu, po vseh teh besedah, rekoč: Vteknite vratove svoje v jarem kralja babilonskega ter služite njemu in ljudstvu njegovemu, in ohranite si življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 13, 'Zakaj hočete umirati ti in ljudstvo tvoje od meča, lakote in kuge, kakor je govoril Gospod o narodu, ki ne bo podložen kralju babilonskemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 14, 'Ne poslušajte torej besed tistih prorokov, ki vam govore in pravijo: Ne boste služili kralju babilonskemu; kajti laž vam oni prorokujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 15, 'Zakaj nisem jih poslal, govori Gospod, ampak sami prorokujejo v mojem imenu krivo, da vas bom pregnal in da bi poginili vi in proroki, ki vam prorokujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 16, 'Tudi duhovnikom in vsemu temu ljudstvu sem govoril, rekoč: Tako pravi Gospod: Ne poslušajte besed prorokov svojih, ki vam prorokujejo in pravijo: Glejte, posode hiše Gospodove se skoraj pripeljejo nazaj iz Babilona; kajti laž vam prorokujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 17, 'Ne poslušajte jih; služite kralju babilonskemu, da boste živeli! čemu naj pride v razvalino to mesto?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 18, 'Če pa so res proroki in če je beseda Gospodova ž njimi, naj vendar stopijo pred Gospoda nad vojskami, proseč, da ne pridejo v Babilon posode, ki so ostale v hiši Gospodovi in v hiši kralja Judovega in v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 19, 'Kajti tako pravi Gospod nad vojskami o templjevih stebrih in o morju in o stojalih in o drugem posodju, kar ga je ostalo v tem mestu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 20, 'ki ga ni vzel Nebukadnezar, kralj babilonski, ko je odpeljaval Jekonija, sinu Jojakimovega, kralja Judovega, iz Jeruzalema v Babilon in vse plemenitnike z Judovega in iz Jeruzalema;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 21, 'da, tako pravi Gospod nad vojskami, Bog Izraelov, o tistem posodju, ki je ostalo v hiši Gospodovi in v hiši kralja Judovega in v Jeruzalemu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 27, 22, 'V Babilon se odnese in tam ostane do dne, ko se ozrem po njih govori Gospod; tedaj storim, da pojdejo gori in jih nazaj pripeljem v ta kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 1, 'In zgodi se tisto leto, v začetku kraljevanja Zedekija, kralja Judovega, četrto leto, v petem mesecu, da mi je govoril Hananija, sin Azurjev, prorok, ki je bil iz Gibeona, v hiši Gospodovi, pred očmi duhovnikov in vsega ljudstva, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 2, 'Tako pravi Gospod nad vojskami, Bog Izraelov, rekoč: Zlomil sem jarem kralja babilonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 3, 'V dveh letih natanko pripeljem nazaj v ta kraj vse posode hiše Gospodove, ki jih je vzel Nebukadnezar, kralj babilonski, iz tega kraja ter jih odpeljal v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 4, 'Tudi Jekonija, sina Jojakimovega, kralja Judovega, in vse preseljence iz dežele Judove, ki so prišli na Babilonsko, pripeljem nazaj, govori Gospod, kajti zlomim jarem kralja babilonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 5, 'Tedaj je govoril prorok Jeremija Hananiju proroku vpričo duhovnikov in vpričo vsega ljudstva, ki je zraven stalo v hiši Gospodovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 6, 'rekel je prorok Jeremija: Amen, tako naj stori Gospod! izpolni naj Gospod besede tvoje, ki si jih prorokoval, da se pripeljejo nazaj posode hiše Gospodove in vsi ujetniki iz Babilona v ta kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 7, 'Vendar pa čuj to besedo, ki jo govorim tebi na ušesa in na ušesa vsemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 8, 'Proroki, ki so bili pred menoj in pred teboj od starih časov, so prorokovali mnogim deželam in velikim kraljestvom vojsko in nesrečo in kugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 9, 'Prorok, ki prorokuje mir, ko se zgodi beseda njegova, se spozna, da je prorok, ki ga je Gospod poslal zares.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 10, 'Tedaj vzame Hananija tisti jarem z vratu Jeremiju ter ga zlomi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 11, 'In govori Hananija vpričo vsega ljudstva, rekoč: Tako pravi Gospod: Tako zlomim jarem Nebukadnezarja, kralja babilonskega, v dveh letih natanko z vratu vseh narodov. Tedaj je odšel prorok Jeremija po svoji poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 12, 'Ali prišla je beseda Gospodova Jeremiju, ko je bil prorok Hananija zlomil tisti jarem z vratu Jeremija proroka, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 13, 'Pojdi in govori Hananiju tole: Tako pravi Gospod: Spone lesene si zlomil, a namesto njih napraviš spone železne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 14, 'Kajti tako pravi Gospod nad vojskami, Bog Izraelov: Železen jarem sem položil na vrat vsem tistim narodom, da naj služijo Nebukadnezarju, kralju babilonskemu, in služili mu bodo; pa tudi zveri poljske sem mu dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 15, 'Nato reče prorok Jeremija Hananiju proroku: Poslušaj vendar, Hananija! Ni te poslal Gospod, ampak ti si zapeljal to ljudstvo, da je zaupalo lažnivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 16, 'Zatorej pravi tako Gospod: Glej, jaz te odpravim s površja zemlje; to leto umrješ, ker si svetoval odpad zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 28, 17, 'In umrl je Hananija prorok tisto leto, v sedmem mesecu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 1, 'To pa so besede pisma, ki ga je poslal prorok Jeremija iz Jeruzalema ostalim starejšinam preseljencev in duhovnikom in prorokom in vsemu ljudstvu, ki ga je bil odpeljal Nebukadnezar iz Jeruzalema v Babilon');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 2, '(ko je odšel iz Jeruzalema, Jekonija kralj in kraljica in dvorniki, knezi iz Jude in Jeruzalema, in rokodelci in kovači),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 3, 'po Elasu, sinu Safanovem, in Gemariju, sinu Hilkijevem, ki ju je poslal Zedekija, kralj Judov, v Babilon h kralju Nebukadnezarju, in se je glasilo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 4, 'Tako pravi Gospod nad vojskami, Bog Izraelov, vsem preseljencem, ki sem jih dal odpeljati iz Jeruzalema v Babilon:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 5, 'Zidajte hiše in prebivajte v njih; sadite vrtove in uživajte njih sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 6, 'Jemljite žene in rodite sinove in hčere, dobivajte tudi sinom svojim žene in svoje hčere možite, da rode sinove in hčere, in množite se in se ne manjšajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 7, 'In iščite blaginje tistemu mestu, kamor sem vas preselil, in prosite zanje Gospoda; ker v blaginji njegovi bode vam blaginja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 8, 'Kajti tako pravi Gospod nad vojskami, Bog Izraelov: Naj vas ne varajo vaši proroki, ki so med vami, in vedeži vaši; in ne poslušajte svojih sanj, ki si jih sami radi sanjate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 9, 'Zakaj krivo vam oni prorokujejo v mojem imenu; nisem jih poslal, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 10, 'Kajti tako pravi Gospod: Brž ko se izpolni Babilonu sedemdeset let, vas obiščem in vam izpolnim tisto svojo besedo predobro in vas pripeljem nazaj v ta kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 11, 'Zakaj jaz dobro vem misli, ki jih mislim za vas, govori Gospod, misli o miru, ne pa o nadlogi, da vam dam srečen konec in upanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 12, 'In klicali me boste in pojdete molit k meni, in uslišim vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 13, 'In ko me boste iskali, me najdete, ker boste vprašali po meni iz vsega srca svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 14, 'in dal se bom najti vam, govori Gospod. In pripeljem nazaj ujetnike vaše in vas zberem izmed vseh narodov in iz vseh krajev, kamor sem vas pregnal, govori Gospod, in vas pripeljem nazaj v ta kraj, odkoder sem vas preselil v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 15, 'Ker pravite: Obudil nam je Gospod proroke v Babilonu –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 16, 'zato pravi tako Gospod o kralju, ki sedi na prestolu Davidovem, in o vsem ljudstvu, ki prebiva v tem mestu, o vaših bratih, ki niso šli z vami v sužnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 17, 'tako pravi Gospod nad vojskami: Glejte, jaz pošljem nadnje meč, lakoto in kugo in jih naredim, da bodo kakor smokve ostudne, ki jih ni moči jesti, tako so slabe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 18, 'In preganjal jih bom z mečem, lakoto in kugo, in dam jih v pestenje vsem kraljestvom na zemlji, v preklinjanje in strmenje ter v zasmehovanje in zasramovanje pri vseh narodih, kamor jih preženem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 19, 'zato ker niso poslušali besed mojih, govori Gospod, s katerimi sem k njim pošiljal hlapce svoje, proroke, od ranega jutra in neprenehoma; tudi vi niste poslušali, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 20, 'Vi torej čujte besedo Gospodovo, vsi preseljenci, ki sem jih poslal iz Jeruzalema v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 21, 'Tako pravi Gospod nad vojskami, Bog Izraelov, o Ahabu, sinu Kolajevem, in o Zedekiju, sinu Maasejevem, ki vam laž prorokujeta v mojem imenu: Glej, jaz ju dam v roko Nebukadnezarju, kralju babilonskemu, da ju umori pred vašimi očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 22, 'In od njiju se vzame kletev pri vseh preseljencih Judovih, ki so v Babilonu, da bodo govorili: Stóri s teboj Gospod kakor z Zedekijem in Ahabom, ki ju je kralj babilonski pekel na ognju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 23, 'zato ker sta storila nesramnost v Izraelu, prešeštvujoč s prijateljev svojih ženami in govoreč lažnive besede v mojem imenu, česar jima nisem ukazal. Jaz pa vem za to in sem priča, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 24, 'Semaju Nehelamljanu pa govóri in veli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 25, 'Tako pravi Gospod nad vojskami, Bog Izraelov, rekoč: Zato ker si poslal v imenu svojem pismo vsemu ljudstvu, ki je v Jeruzalemu, in Zefaniju, sinu Maasejevemu, duhovniku, in vsem duhovnikom in si rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 26, 'Gospod te je postavil za duhovnika namesto Jojada duhovnika, da bodo nadzorniki v hiši Gospodovi zoper vsakega blaznega moža, ki se dela proroka, da ga deneš v klado in v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 27, 'Zdaj torej, zakaj nisi pokaral Jeremija Anatotčana, ki vam prorokuje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 28, 'ker je vsled tega poslal k nam v Babilon s sporočilom: Dolga bo še sužnost; zidajte hiše in prebivajte v njih, in sadite vrtove in uživajte njih sad...');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 29, 'Bral je pa Zefanija, duhovnik, to pismo, da je slišal prorok Jeremija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 30, 'In prišla je beseda Gospodova Jeremiju, veleč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 31, 'Pošlji k vsem preseljencem in sporoči: Tako pravi Gospod o Semaju Nehelamljanu: Ker vam prorokuje Semaja, dasi ga jaz nisem poslal, in stavi vaše upanje na lažnivost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 29, 32, 'zato pravi Gospod tako: Glej, jaz bom kaznoval Semaja Nehelamljana in seme njegovo: ne bo imel nikogar, ki bi prebival sredi tega ljudstva, in ne bo videl dobrote, ki jo storim svojemu ljudstvu, govori Gospod, ker je odpad svetoval zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 2, 'Tako pravi Gospod, Bog Izraelov, veleč: Zapiši si v knjigo vse besede, ki ti jih govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 3, 'Kajti glej, dnevi pridejo, govori Gospod, ko nazaj pripeljem ujeto množico ljudstva svojega Izraelovega in Judovega, pravi Gospod; in pripeljem jih nazaj v deželo, ki sem jo bil dal njih očetom, da bi jo posedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 4, 'In to so besede, ki jih je govoril Gospod o Izraelu in o Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 5, 'Kajti tako pravi Gospod: Glas trepeta čujemo, strah je in nič miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 6, 'Le vprašajte in vidite, ali rodi moški? Zakaj vidim roke vsakega moža na ledju njegovem, kakor porodnica, in vseh obličja so obledela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 7, 'Gorje! ker velik je ta dan, da mu ni enakega: to je čas stiske Jakobove; vendar bo rešen iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 8, 'Kajti tisti dan se zgodi, govori Gospod nad vojskami, da zlomim jarem njegov s tvojega vratu in raztrgam vezi tvoje, in sužnosti ne bodo več zahtevali od tebe tujci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 9, 'ampak vsi bodo služili Gospodu, Bogu svojemu, in Davidu, kralju svojemu, ki ga jim obudim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 10, 'Ti torej se ne boj, hlapec moj Jakob, govori Gospod, in ne plaši se, Izrael! zakaj, glej, jaz te otmem iz daljave in zarod tvoj iz dežele sužnosti njegove; in vrne se Jakob in bo počival in mirno živel, in nihče ga ne bo strašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 11, 'Kajti na strani sem ti, govori Gospod, da te rešim; zakaj docela pokončam vse narode, med katere sem te razkropil; samo tebe ne pokončam docela, temuč strahoval te bom primerno in te ne bom pustil čisto brez kazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 12, 'Kajti tako pravi Gospod: Smrtna je rana tvoja, prehud udarec tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 13, 'Nihče se ne mara potegniti za pravdo tvojo; za rano svojo nimaš zdravila, ne obveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 14, 'Vsi ljubčki tvoji so te pozabili, ne vprašujejo nič po tebi; kajti udaril sem te z udarcem sovražnikovim, z grozovitim strahovanjem, zato ker je velika krivičnost tvoja, mnogi so grehi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 15, 'Kaj vpiješ zavoljo rane svoje, da je neozdravljiva bolečina tvoja? Zato ker je velika krivičnost tvoja, ker so mnogi grehi tvoji, sem ti storil to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 16, 'Zato bodo, katerikoli te žro, požrti in vsi zatiralci tvoji, kolikor jih je, pojdejo v sužnost, in kateri te teptajo, bodo poteptani, in vse, ki te plenijo, izročim plenjenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 17, 'Kajti povrnem ti zdravje in rane tvoje zacelim, govori Gospod, ker so te „pregnanko“imenovali, rekoč: Ta je Sion, po kateri nihče ne vprašuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 18, 'Tako pravi Gospod: Glej, jaz pripeljem nazaj ujetnike šatorov Jakobovih in se usmilim njegovih prebivališč. In mesto se zopet zgradi na svojem nasipu in v gradu se bo prebivalo po navadi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 19, 'In iz njih bo donelo zahvaljevanje in glas smejočih; in razmnožim jih, in se ne zmanjšajo; in poveličam jih, in ne bodo ponižani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 20, 'In sinovi njegovi bodo kakor prej in njih občina se ustanoviti pred menoj; kaznoval pa bom vse, ki jih stiskajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 21, 'In veličastnik njegov bode iz njega in vladar njegov pride izmed njega; in njemu zapovem pristopiti, da se mi približa; kajti kdo je on, ki je prorok za srce svoje, da se sme približati meni? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 22, 'In bodete mi ljudstvo in jaz vam bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 23, 'Glej, vihar Gospodov, srdit, je nastal, vihar, vse podirajoč: zgrne se brezbožnim na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 30, 24, 'Ne odvrne se kipeča jeza Gospodova, dokler ne stori in dokler ne izpolni misli srca svojega. V poslednjih dnevih boste razumeli to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 1, 'V tistem času, govori Gospod, bodem Bog vsem rodovinam Izraelovim in oni mi bodo moje ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 2, 'Tako pravi Gospod: Milost je našlo v puščavi ljudstvo njih, ki so ubežali meču, namreč Izrael, ko sem šel, da ga pripeljem v pokoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 3, '„Od daleč se mi je prikazal Gospod.“A on veli: Z večno ljubeznijo te ljubim, zato ti stanovitno izkazujem dobrotljivost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 4, 'Zopet te bom zidal, in bodeš sezidana, o devica Izraelova! Zopet se boš dičila z bobnicami svojimi in hodila z zborom plesočih in se veselečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 5, 'Zopet boš sadila vinograde na gorah v Samariji; sadili bodo sadilci in uživali sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 6, 'Kajti pride dan, ko bodo vpili čuvaji na Efraimskem gorovju: Vstanite in idimo gori na Sion h Gospodu, Bogu svojemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 7, 'Kajti tako pravi Gospod: Z veseljem prepevajte zaradi Jakoba in ukajte zaradi glave narodov! Oznanjajte, hvalite in govorite: Reši, o Gospod, ljudstvo svoje, ostanek Izraelov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 8, 'Glej, jaz jih pripeljem iz severne dežele in jih zberem od skrajnih koncev zemlje, med njimi slepega in hromega, nosečo in porodnico skupaj: v velikem zboru se vrnejo sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 9, 'Z jokom pridejo, in milo proseče jih popeljem; storim, da pojdejo poleg potokov vodá po ravnem potu, na katerem se ne spotaknejo; zakaj oče sem Izraelu in Efraim je moj prvorojenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 10, 'Čujte besedo Gospodovo, o narodi, in oznanjujte jo po otokih daljnih ter recite: On, ki je razkropil Izraela, ga zbere, in čuval ga bo kakor pastir čredo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 11, 'Kajti Gospod je odkupil Jakoba in ga oprostil iz roke močnejšega od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 12, 'In prišli bodo in veselo peli na višavi Sionski, in vreli bodo vkup k dobrotam Gospodovim: k žitu in vinu in olju in k mladi drobnici in govedi; in njih duša bode podobna namočenemu vrtu, in stradali ne bodo nikdar več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 13, 'Tedaj se bo radovala devica s plesom, mladeniči in starci skupaj, ker izpremenim njih žalost v veselje ter jih potolažim in razveselim po njih žalosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 14, 'In poživim dušo duhovnikov z mastjo in ljudstvo moje se nasiti z dobroto mojo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 15, 'Tako pravi Gospod: Glas se sliši v Rami, žalovanje in prebridek jok. Rahel se plače po svojih otrocih, brani se tolažbe za otroke svoje, ker jih ni več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 16, 'Tako pravi Gospod: Zdržuj glas svoj joka in solzá svoje oči, kajti plačilo je delu tvojemu, govori Gospod, ker se povrnejo iz dežele sovražnikove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 17, 'In upanje je za tvojo prihodnost, govori Gospod, in otroci tvoji se povrnejo v pokrajino svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 18, 'Slišal sem, slišal Efraima, da toži: Strahoval si me, da sem bil strahovan kakor ižesu neprivajeno tele; izpreobrni me, da se izpreobrnem, zakaj ti si Gospod, Bog moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 19, 'Kajti ko bodem izpreobrnjen, se bom kesal, in ko pridem k spoznanju, se bom tolkel po stegnih. Sram me je in z rdečico sem oblit, ker nosim sramoto mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 20, 'Ali mi je drag sin Efraim? ali otrok dražesten? Kajti kadarkoli govorim zoper njega, se ga vendar milo spominjam še. Zatorej polje osrčje moje zaradi njega; gotovo se ga usmilim, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 21, 'Postavi si spomenike ob potu, naredi si kažipote, obrni srce svoje na cesto, na pot, po kateri si hodila! Povrni se, o devica Izraelova, povrni se k tem mestom svojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 22, 'Kako dolgo se boš še obračala semtertja, o hči odpadnica? Kajti Gospod je ustvaril kaj novega na zemlji: Žena bo obdajala moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 23, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Še bodo govorili to besedo v deželi Judovi in v mestih njegovih, ko nazaj pripeljem njih ujetnike: Blagoslóvi te Gospod, o prebivališče pravičnosti, gora svetosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 24, 'In Juda in vsa mesta njegova bodo stanovala v njej skupaj, kmetovalci in kateri hodijo s čredami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 25, 'Zakaj obilo napojim od žeje opešano dušo in vsako dušo, ki medleva, nasitim. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 26, 'Ob tem sem se prebudil in pogledal, in spanje moje mi je bilo sladko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 27, 'Glej, dnevi pridejo, govori Gospod, ko posejem hišo Izraelovo in hišo Judovo s semenom človeškim in s semenom živinskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 28, 'In kakor sem čul nad njimi, da bi roval in razdiral, rušil, končaval in tepel, tako bom čul nad njimi, da zidam in sadim, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 29, 'V tistih dneh ne poreko več: Očetje so jedli kislo grozdje in otrokom so zato zobje skominasti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 30, 'temuč vsak umre zavoljo svoje krivice: vsakemu človeku, ki bo jedel kislo grozdje, bodo zobje skominasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 31, 'Glej, dnevi pridejo, govori Gospod, ko sklenem s hišo Izraelovo in s hišo Judovo novo zavezo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 32, 'ne po zavezi, ki sem jo sklenil ž njih očeti v dan, ko sem prijel njih roko, da jih izpeljem iz dežele Egiptovske, katero mojo zavezo so sami prelomili, dasi sem jaz jim bil soprog, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 33, 'Kajti to je zaveza, ki jo sklenem s hišo Izraelovo po tistih dnevih, govori Gospod: postavo svojo dam v njih osrčje in v srce jim jo zapišem, in bodem jim Bog in oni mi bodo ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 34, 'In ne bodo več učili vsak svojega prijatelja in vsak svojega brata, govoreč: Spoznajte Gospoda! zakaj kolikor jih bode, me bodo spoznali vsi, od najmanjšega do največjega, govori Gospod. Kajti odpustim njih krivico in ne bom se več spominjal njih grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 35, 'Tako pravi Gospod, ki daje solnce za luč po dnevi, mesec in zvezde po njih postavah za luč po noči, ki razburkava morje, da šumé valovi njegovi, Gospod nad vojskami je njegovo ime:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 36, 'Če se odpravijo te postave izpred mojega obličja, govori Gospod, neha tudi seme Izraelovo biti narod pred mojim obličjem vse dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 37, 'Tako pravi Gospod: Če se bodo mogla meriti nebesa gori in preiskati podstave zemlje doli, zavržem tudi jaz vse seme Izraelovo zavoljo vsega, kar so storili, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 38, 'Glej, dnevi pridejo, govori Gospod, ko se zgradi to mesto Gospodu od stolpa Hananelovega do Vogelnih vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 39, 'In merska vrvica pojde še dalje proti hribu Garebu in krene proti Goahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 31, 40, 'In vsa dolina mrličev in pepela in vse njive do potoka Kidrona, do vogla Konjskih vrat proti jutru, ves ta prostor bode svet Gospodu; ne pokonča se, ne poruši nikdar več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 1, 'Beseda, ki je prišla Jeremiju od Gospoda v desetem letu Zedekija, kralja Judovega; tisto leto je osemnajsto leto Nebukadnezarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 2, 'Tedaj pa so krdela kralja babilonskega oblegala Jeruzalem; in Jeremija prorok je bil zaprt v veži straže, ki je bila v hiši kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 3, 'Kajti zaprl ga je bil Zedekija, kralj Judov, rekoč: Zakaj prorokuješ in govoriš: Tako pravi Gospod: Glej, jaz dam to mesto v roko kralju babilonskemu, da ga vzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 4, 'Tudi Zedekija, kralj Judov, se ne reši iz rok Kaldejcev, ampak gotovo bo dan v roko kralju babilonskemu, in usta njegova mu bodo govorila v usta in oči tega bodo videle onega oči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 5, 'in odpelje Zedekija v Babilon, kjer ostane, dokler ga ne obiščem, govori Gospod. Ker se bojujete s Kaldejci, ne boste imeli sreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 6, 'Reče torej Jeremija: Prišla mi je beseda Gospodova, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 7, 'Glej, Hanamel, sin Saluma, strica tvojega, pride k tebi, da reče: Kupi si polje moje, ki je v Anatotu, kajti tvoja je odkupna pravica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 8, 'Nato je prišel k meni Hanamel, sin strica mojega, po besedi Gospodovi, v vežo straže ter mi rekel: Kupi, prosim, polje moje, ki je v Anatotu, ki je v deželi Benjaminovi; kajti tvoja je pravica za dedovanje in odkup; kupi si ga! Tedaj sem spoznal, da je beseda Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 9, 'In kupil sem od Hanamela, sina strica mojega, tisto polje, ki je v Anatotu, in odtehtal sem mu denar, sedemnajst seklov srebra;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 10, 'in pisal sem kupno pismo in ga zapečatil, in privzel sem priče, in odtehtal denar na tehtnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 11, 'Nato vzamem kupno pismo, zapečateno, z določbami in s pogoji, in odprt prepis,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 12, 'in izročim kupno pismo Baruhu, sinu Nerija, sina Mahsejevega, pred očmi svojega stričiča Hanamela in pred očmi prič, ki so podpisale kupno pismo, pred očmi vseh Judov, ki so sedeli v veži straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 13, 'In ukažem Baruhu vpričo njih, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 14, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Vzemi ti pismi, to zapečateno kupno pismo in to odprto pismo, in položi ju v prsteno posodo, da tam ostaneta mnogo dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 15, 'Zakaj tako pravi Gospod nad vojskami, Bog Izraelov: Še se bodo kupovale hiše in njive in vinogradi v tej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 16, 'In ko sem dal kupno pismo Baruhu, sinu Nerijevemu, sem prosil Gospoda, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 17, 'Oh, Gospod, Jehova! Glej, ti si naredil nebesa in zemljo z močjo svojo preveliko in z iztegnjeno ramo svojo: tebi ni pretežka nobena stvar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 18, 'ki izkazuješ milost tisočim in poplačuješ očetov krivice v naročje njih sinov za njimi. Ti Bog mogočni, veliki, silni, čigar ime je Gospod nad vojskami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 19, 'velik v svetu in mogočen v dejanju, ti, čigar oči so odprte nad vsemi poti človeških otrok, da daš vsakemu po njegovih potih in po sadu njegovih del;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 20, 'ki si delal znamenja in čudeže v deželi Egiptovski in še do tega dne i v Izraelu i med drugimi ljudmi in sebi pridobil ime, kakršno je dandanašnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 21, 'In izpeljal si ljudstvo svoje Izraela iz dežele Egiptovske z znamenji in čudeži in z mogočno roko in z iztegnjeno ramo in z velikim strahom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 22, 'in dal si jim to deželo, ki si bil zanjo prisegel njih očetom, da jim jo daš, deželo, ki se cedi mleka in medu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 23, 'Ali ko so prišli vanjo ter jo posedli, niso poslušali glasu tvojega in niso hodili po postavi tvoji; karkoli si jim zapovedal storiti, niso storili. Zato si storil, da jih je zadela vsa ta nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 24, 'Glej, nasipe so nanesli proti temu mestu, da ga vzemo; in mesto bo dano v roke Kaldejcem, ki ga oblegajo, zavoljo meča in lakote in kuge. In kar si govoril, se godi; in glej, ti to vidiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 25, 'In vendar si mi velel, Gospod, Jehova: Kupi si tisto polje z denarjem in privzemi priče; – in mesto je dano v roke Kaldejcem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 26, 'Prišla je pa beseda Gospodova Jeremiju, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 27, 'Glej, jaz sem Gospod, Bog vsega mesa; ali bi mi bila pretežka kaka stvar?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 28, 'Zato pravi tako Gospod: Glej, jaz dam to mesto v roko Kaldejcev in v roko Nebukadnezarja, kralja babilonskega, da ga vzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 29, 'In Kaldejci, ki se bojujejo zoper to mesto, pridejo vanje in ga zapalijo z ognjem ter požgo s hišami vred, ki so na njih strehah kadili Baalu in pitne daritve darovali tujim bogovom, da bi me dražili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 30, 'Ker so sinovi Izraelovi in sinovi Judovi delali od mladih nog samo, kar je bilo hudobno v mojih očeh; kajti sinovi Izraelovi so me samo dražili z delom svojih rok, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 31, 'Ker v jezo in v srd mi je bilo to mesto od dne, ko so ga sezidali, do tega dne, da bi ga odpravil izpred svojega obličja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 32, 'zavoljo vse hudobnosti sinov Izraelovih in sinov Judovih, ki so jo počenjali, da bi me razdražili, oni in njih kralji in knezi, proroki in možje Judovi in prebivalci jeruzalemski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 33, 'Obrnili so mi hrbet, ne pa obličja; in ko sem jih učil od ranega jutra in neprenehoma, me niso nikakor poslušali, da bi sprejeli nauk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 34, 'Ampak postavili so gnusobe svoje v hišo, ki se imenuje po mojem imenu, da jo oskrunijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 35, 'In zidali so Baalu višave, ki so v dolini sina Hinomovega, da bi peljali sinove in hčere svoje skozi ogenj Molohu; česar jim nisem bil zapovedal in mi ni prišlo na misel, da store to gnusobo, da bi zapeljevali Judo v greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 36, 'Zdaj torej pravi tako Gospod, Bog Izraelov, o tem mestu, za katero vi pravite, da je dano v roko kralja babilonskega po meču in po lakoti in kugi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 37, 'Glej, jaz jih zberem iz vseh pokrajin, kamor sem jih pregnal v svoji jezi in v srdu svojem in v veliki togoti, in pripeljem jih nazaj v ta kraj in jim dam prebivati na varnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 38, 'In ljudstvo mi bodo in jaz jim bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 39, 'In dam jim eno srce in en pot, da se me bodo bali vse dni, njim v dobro in njih otrokom za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 40, 'In sklenem ž njimi zavezo večno, da se ne obrnem od njih, da bi jim ne delal dobrega; in strah svoj dam v njih srce, da ne krenejo od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 41, 'In veselil se jih bom in jim delal dobro, in vsadim jih v to deželo v resnici iz vsega srca svojega in iz vse duše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 42, 'Kajti tako pravi Gospod: kakor sem pripeljal nad to ljudstvo vso to veliko nesrečo, tako pripeljem nadnje vse to dobro, katero jim obetam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 43, 'Tedaj se bo kupovalo polje v tej deželi, ki pravite, da je opustošena, da ni v njej ne človeka, ne živali, da je dana v roko Kaldejcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 32, 44, 'Njive bodo kupovali za denar in vpisavali v pismo in pečatili in privzemali priče v deželi Benjaminovi in v krajih okoli Jeruzalema in v mestih Judovih in v pogorskih mestih in v mestih na nižavi in v mestih na Jugu; kajti pripeljem nazaj njih ujetnike, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 1, 'Prišla je pa beseda Gospodova Jeremiju v drugo, ko je bil še zaprt v veži straže, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 2, 'Tako pravi Gospod, ki to napravlja, Gospod, ki snuje in uresniči to, Gospod mu je ime:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 3, 'Kliči me, in odgovorim ti in pokažem ti velike reči in nedosežne, katerih ne poznaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 4, 'Kajti tako pravi Gospod, Bog Izraelov, o hišah tega mesta in o hišah kraljev Judovih, ki jih podirajo v obrambo zoper nasipe in meč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 5, 'Gredo se sem bojevat zoper Kaldejce le zato, da napolnijo tiste hiše s trupli ljudi, ki sem jih udaril v svoji jezi in v srdu svojem in zavoljo katerih vse krivice sem skril obličje svoje temu mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 6, 'Glej, jaz ga pripravim v pravi stan in zdravje, ter jih ozdravim in jim razodenem obilost miru in resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 7, 'In nazaj pripeljem ujetnike Judove in ujetnike Izraelove, in sezidam jih kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 8, 'In očistim jih vse njih krivice, s katero so grešili zoper mene, in jim odpustim vse krivice, s katerimi so grešili zoper mene in s katerimi so se mi izneverili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 9, 'In to mesto mi bode v ime, v veselje in hvalo in diko pri vseh narodih zemeljskih, ki bodo slišali vse to dobro, katero jim storim; in bali se bodo in tresli ob vsem tem dobrem in ob vsem tem miru, ki jim ga dodelim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 10, 'Tako pravi Gospod: Še se bo slišal v tem kraju, ki o njem pravite: „Opustošen je, da ni ne človeka, ne živali“, v mestih Judovih in po ulicah jeruzalemskih, opustošenih tako, da ni v njih človeka, ne prebivalca, ne živine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 11, 'slišal se bo glas veselja in radosti glas, glas ženina in neveste glas, glas govorečih: Hvalite Gospoda nad vojskami, ker dober je Gospod, ker vekomaj traja milost njegova, glas njih, ki prinašajo žrtve v zahvalo v hišo Gospodovo. Zakaj nazaj pripeljem ujetnike te dežele, da bode kakor poprej, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 12, 'Tako pravi Gospod nad vojskami: Zopet bode v tem kraju, ki je opustošen, da ni v njem človeka ali živine, in v vseh mestih njegovih domovanje pastirjem, ki vodijo črede na počitek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 13, 'V mestih na gorah, v mestih v nižavi in v mestih na Jugu in v deželi Benjaminovi in v krajih okoli Jeruzalema in v mestih Judovih bodo zopet prehajale črede pod roko njega, ki jih šteje, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 14, 'Glej, dnevi pridejo, govori Gospod, ko izpolnim tisto dobro besedo, ki sem jo obljubil za hišo Izraelovo in za hišo Judovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 15, 'V tistih dneh in v tistem času storim, da požene Davidu Odraslek pravičnosti, in izvrševal bo sodbo in pravičnost v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 16, 'V tistih dneh bo rešen Juda, in Jeruzalem bo prebival na varnem, in to je ime, s katerim ga bodo imenovali: Gospod, pravičnost naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 17, 'Zakaj tako pravi Gospod: Ne bo Davidu zmanjkalo moža, ki bo sedel na prestolu hiše Izraelove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 18, 'tudi duhovnikom, levitom, ne zmanjka moža izpred mojega obličja, ki bo daroval žgalno daritev in zažigal jedilni dar ter opravljal klalno daritev vse dni. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 19, 'In beseda Gospodova je prišla Jeremiju, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 20, 'Tako pravi Gospod: Ako razveljavite zavezo mojo z dnevom in zavezo mojo z nočjo, da ne bode dneva in noči ob svojem času,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 21, 'bo tudi zaveza moja z Davidom, hlapcem mojim, razveljavljena, da ne bo imel sina, kraljujočega na prestolu njegovem, in z duhovniki, leviti, strežniki mojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 22, 'Kakor se ne more šteti vojska nebeška in se ne more meriti pesek morski, tako pomnožim seme Davida, hlapca svojega, in levite, ki mi strežejo. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 23, 'Zopet je prišla beseda Gospodova Jeremiju, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 24, 'Nisi li opazil, kaj govori to ljudstvo, ki pravi: „Tisti dve družini, ki ju je bil izvolil Gospod, je že zavrgel“? in tako zaničujejo ljudstvo moje, da ne velja več za narod v njih očeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 25, 'Tako pravi Gospod: Ako ne velja zaveza moja z dnevom in z nočjo, ako nisem ustanovil postav nebesom in zemlji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 33, 26, 'zavržem tudi seme Jakoba in Davida, hlapca svojega, da jih ne vzamem več od semena njegovega, kateri naj gospodujejo semenu Abrahamovemu, Izakovemu in Jakobovemu. Zakaj jaz pripeljem nazaj njih ujetnike ter se jih usmilim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, ko se je vojskoval Nebukadnezar, kralj babilonski, in vsa vojska njegova in vsa kraljestva zemlje, ki so bila pod njegovo oblastjo, in vsa ljudstva zoper Jeruzalem in zoper vsa mesta njegova:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 2, 'Tako pravi Gospod, Bog Izraelov: Pojdi in govori Zedekiju, kralju Judovemu, in mu reci: Tako pravi Gospod: Glej, jaz izročam to mesto v roko kralja babilonskega, da ga požge z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 3, 'Ti pa ne ubežiš roki njegovi, ampak ujet boš gotovo in dan v roko njegovo; in oči tvoje bodo gledale kralju babilonskemu v oči, in usta njegova bodo govorila tvojim ustom, in prideš v Babilon!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 4, 'Vendar čuj besedo Gospodovo, Zedekija, kralj Judov! Tako pravi Gospod o tebi: Ne umrješ z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 5, 'V miru umrješ, in kakor so napravili očetom tvojim, prejšnjim kraljem, ki so bili pred teboj, tako napravijo ogenj tebi, in bodo tožili po tebi: Gorje, gospod! Kajti to besedo govorim jaz, veli Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 6, 'Tedaj je Jeremija prorok govoril Zedekiju, kralju Judovemu, vse te besede v Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 7, 'ko so se krdela kralja babilonskega bojevala zoper Jeruzalem in zoper vsa ostala mesta Judova, zoper Lahis in Azeko, kajti ti sta bili ostali od mest Judovih, mesti utrjeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 8, 'Beseda, ki je prišla Jeremiju od Gospoda, potem ko je bil kralj Zedekija sklenil zavezo z vsem ljudstvom v Jeruzalemu, da jim okliče svobodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 9, 'da naj oprosti vsak svojega hlapca in vsak svojo deklo, Hebrejca in Hebrejko, da naj ne zahteva nihče več sužnosti od Juda, brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 10, 'In poslušali so vsi knezi in vse ljudstvo, ki je stopilo v zavezo, da naj odpusti v prostost vsak svojega hlapca in vsak svojo deklo, da naj ne zahteva več sužnosti od njih. Poslušali so, pravim, in jih odpustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 11, 'Zopet pa so pozneje nazaj vzeli tiste hlapce in dekle, ki so jih bili odpustili, in jih prisilili za hlapce in za dekle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 12, 'Prišla je torej beseda Gospodova Jeremiju od Gospoda, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 13, 'Tako pravi Gospod, Bog Izraelov: Jaz sem bil sklenil zavezo z očeti vašimi tisti dan, ko sem jih izpeljal iz dežele Egiptovske, iz hiše sužnjev, in rekel sem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 14, 'Konec sedmih let odpustite vsak svojega brata Hebrejca, ki se ti je prodal; potem ko ti je služil šest let, odpusti ga prostega od sebe. Ali niso me poslušali očetje vaši in niso nagnili ušesa svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 15, 'Vi ste se res povrnili danes in storili, kar se vidi pravo v očeh mojih: oklicali ste svobodo vsak svojemu bližnjiku in ste sklenili zavezo vpričo mene v hiši, ki se kliče po mojem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 16, 'Ali zopet ste se odvrnili in oskrunili moje ime, ko ste vzeli nazaj vsak svojega hlapca in vsak svojo deklo, ki ste jih bili odpustili proste po njih želji, in jih silite, da naj vam bodo hlapci in dekle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 17, 'Zatorej pravi tako Gospod: Niste me poslušali, ko ste oklicali svobodo vsak svojemu bratu in vsak svojemu bližnjiku; glejte, zato jaz oklicujem zoper vas svobodo, govori Gospod, meču, kugi in lakoti in vas dam v pestenje vsem kraljestvom na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 18, 'In tiste može, ki so prestopili zavezo mojo, ki niso držali besed zaveze, katero so bili sklenili vpričo mene, storim enake teletu, ki so ga razrezali na dvoje in so šli skozi med telečjima polovicama:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 19, 'kneze Judove in kneze jeruzalemske, dvornike in duhovnike in vse ljudstvo te dežele, ki so šli skozi med polovicama tistega teleta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 20, 'izdam v roko njih sovražnikov in v pest njim, ki jim strežejo po življenju; in njih trupla bodo v jed pticam nebeškim in živalim zemeljskim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 21, 'Tudi Zedekija, kralja Judovega, in njegove kneze dam v roko njih sovražnikov in v pest njim, ki jim strežejo po življenju, v roko vojske kralja babilonskega, ki je odšla od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 34, 22, 'Glej, jaz ukažem, govori Gospod, in jih pokličem nazaj zoper to mesto, da ga oblegajo in ga vzamejo in požgo z ognjem, in mesta Judova dam v pustošenje, tako da v njih ne bode prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 1, 'Beseda, ki je prišla Jeremiju od Gospoda v dnevih Jojakima, sinu Josijevega, kralja na Judovem, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 2, 'Pojdi k družini Rehabovcev in govori ž njimi in jih pripelji v hišo Gospodovo v kateri hram in jim daj priti vina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 3, 'Vzamem torej Jazanija, sinu Jeremija, sinu Habazinijevega, in brate njegove in vse sine njegove in vso družino Rehabovcev');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 4, 'in jih privedem v hišo Gospodovo v hram sinov Hanana, sinu Jigdalija, moža Božjega, ki je blizu hrama knezov, ta pa nad hramom Maaseja, sinu Salumovega, ki je bil čuvaj vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 5, 'In ko sem postavil pred sinove družine Rehabovcev kupe polne vina in čaše, jim rečem: Pijte vino!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 6, 'Oni pa reko: Ne pijemo vina, kajti Jonadab, sin Rehabov, naš oče, nam je zapovedal, rekoč: Ne pijte vina, ne vi, ne otroci vaši, nikdar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 7, 'in hiše ne zidajte in semena ne sejte in vinograda ne sadite in ga v lasti ne imejte, temuč v šatorih prebivajte vse svoje dni, da boste mnogo dni živeli v deželi, kjer ste tujci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 8, 'In poslušali smo glas Jonadaba, sinu Rehabovega, očeta svojega v vsem, kar nam je zapovedal: da ne pijemo vina vse svoje dni, mi, žene naše, sinovi naši in hčere naše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 9, 'in ne zidajmo hiš v domovanje svoje; tudi nimamo vinograda ali polja ali setve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 10, 'temuč prebivamo v šatorih in poslušamo in delamo, prav kakor nam je zapovedal Jonadab, naš oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 11, 'Ko pa je šel Nebukadnezar, kralj babilonski, gori v to deželo, smo rekli: Dejte, pojdimo v Jeruzalem pred vojsko Kaldejcev in pred vojsko Sircev! Tako smo se nastanili v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 12, 'Tedaj pride beseda Gospodova Jeremiju, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 13, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Pojdi in reci možem Judovim in prebivalcem jeruzalemskim: Ali ne sprejmete nauka, da bi poslušali besede moje? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 14, 'Besede Jonadaba, sinú Rehabovega, ki je ž njimi prepovedal otrokom svojim, naj ne pijo vina, se izpolnjujejo; kajti niso pili do tega dne, ker poslušajo zapoved očeta svojega. Jaz pa sem vam govoril od ranega jutra in neprenehoma, a niste me poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 15, 'In pošiljal sem k vam vse hlapce svoje, proroke, od ranega jutra in neprenehoma, govoreč: Povrnite se vendar s hudobnega pota svojega in dobra naredite dejanja svoja in ne hodite za tujimi bogovi, da bi jih častili, tako ostanete v tej deželi, ki sem jo izročil vam in očetom vašim: toda niste nagnili ušesa svojega in niste me poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 16, 'Pač izpolnjujejo otroci Jonadaba, sinu Rehabovega, zapoved očeta svojega, ki jim jo je zapovedal; to ljudstvo pa ne posluša mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 17, 'Zatorej pravi tako Gospod, Bog nad vojskami, Bog Izraelov: Glej, jaz pripeljem nad Judo in nad vse prebivalce jeruzalemske vso tisto nesrečo, ki sem jo izgovoril zoper nje; zato ker me niso poslušali, ko sem jim govoril, in niso odgovorili, ko sem jih klical.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 18, 'In družini Rehabovcev je rekel Jeremija: Tako pravi Gospod nad vojskami, Bog Izraelov: Ker poslušate zapoved Jonadaba, očeta svojega, in se držite vseh zapovedi njegovih in delate vse, kakor vam je zapovedal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 35, 19, 'zato pravi Gospod nad vojskami, Bog Izraelov: Jonadabu, sinu Rehabovemu, ne bo zmanjkalo moža, ki bo stal pred obličjem mojim, vse čase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 1, 'Bilo pa je v četrtem letu Jojakima, sinu Josijevega, kralja na Judovem, ko pride ta beseda Jeremiju od Gospoda, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 2, 'Vzemi si zvitek knjige in zapiši vanj vse besede, ki sem ti jih govoril o Izraelu in o Judi in o vseh narodih od dne, ko sem te ogovoril, od dni Josijevih do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 3, 'Morda bo hiša Judova slišala vse tisto hudo, katero jim jaz mislim storiti, in se povrnejo vsak s hudobnega pota svojega, da jim odpustim njih krivico in njih greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 4, 'Zato je Jeremija poklical Baruha, sinu Nerijevega; in zapisal je Baruh iz ust Jeremijevih vse besede Gospodove, ki mu jih je govoril, v zvitek knjige.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 5, 'Nato zapove Jeremija Baruhu, rekoč: Jaz sem zadržan, ne morem iti v hišo Gospodovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 6, 'zato pojdi ti in beri v tem zvitku, kar si zapisal iz mojih ust, besede Gospodove, da sliši ljudstvo v hiši Gospodovi v postni dan; in beri, da slišijo tudi vsi Judovi, ki so prišli iz svojih mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 7, 'Morda popadajo na tla in prosijo pred Gospodom in se povrnejo vsak s hudobnega pota svojega; kajti velika je jeza in togota, ki jo je izrekel Gospod zoper to ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 8, 'In Baruh, Nerijev sin, je storil, prav kakor mu je bil zapovedal prorok Jeremija, in je bral v tisti knjigi besede Gospodove v hiši Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 9, 'In zgodi se v petem letu Jojakima, sinu Josijevega, kralja na Judovem, deveti mesec, da je bil post pred Gospodom napovedan vsemu ljudstvu v Jeruzalemu in vsemu ljudstvu, ki je prišlo iz mest Judovih v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 10, 'In Baruh je bral v knjigi besede Jeremijeve v hiši Gospodovi, v hramu Gemarija, sinu Safana pisarja, na gorenjem dvorišču pri vhodu novih vrat hiše Gospodove, da je slišalo vse ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 11, 'Ko je pa slišal Mihaj, sin Gemarija, sinu Safanovega, vse besede Gospodove iz tiste knjige,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 12, 'je šel doli v hišo kraljevo, v hram pisarjev, kjer so, glej, sedeli vsi knezi: Elisama pisar in Delaja, sin Semajev, in Elnatan, sin Akborjev, Gemarija, sin Safanov, in Zedekija, sin Hananijev, in vsi knezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 13, 'In povedal jim je Mihaj vse besede, ki jih je slišal, ko je Baruh bral v knjigi, da je ljudstvo poslušalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 14, 'Tedaj so poslali vsi knezi k Baruhu Jehudija, sinu Netanija, sinu Selemija, sinu Kusijevega, da naj reče: Tisti zvitek, v katerem si bral, da je poslušalo ljudstvo, tega vzemi v roko svojo in pridi. Vzame torej Baruh, Nerijev sin, tisti zvitek v roko svojo in pride k njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 15, 'Pa mu reko: Sedi zdaj in beri tisto, mi bomo pa poslušali; in Baruh je bral, oni so pa poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 16, 'In ko so slišali vse tiste besede, so prestrašeni gledali drug drugega in rekli Baruhu: Gotovo bomo kralju povedali vse te besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 17, 'Baruha pa so vprašali, rekoč: Povej nam vendar, kako si zapisal vse te besede iz ust njegovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 18, 'Baruh pa jim reče: Iz svojih ust mi je govoril vse te besede, in jaz sem pisal v knjigo s črnilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 19, 'Tedaj reko knezi Baruhu: Pojdi, skrij se ti in Jeremija, in nihče ne vedi, kje sta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 20, 'In šli so h kralju v dvorec, ko so bili tisti zvitek položili v hram Elisama pisarja; in povedali so, da je slišal kralj, vse tiste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 21, 'Pošlje torej kralj Jehudija, da prinese tisti zvitek. In vzame ga iz hrama Elisama pisarja. In bere ga Jehudija, da je slišal kralj in so slišali vsi knezi, ki so stali poleg kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 22, 'Kralj pa je sedel v zimski hiši deveti mesec, in gorelo je na ognjišču pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 23, 'In ko je bil prebral Jehudija tri liste ali štiri, je kralj prerezal zvitek s pisarskim nožem in ga vrgel v ogenj, ki je bil na ognjišču, da je bil ves zvitek pokončan z ognjem na ognjišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 24, 'Niso se pa zbali in niso pretrgali obleke svoje kralj in vsi hlapci njegovi, ki so slišali vse tiste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 25, 'In dasi so Elnatan in Delaja in Gemarija prosili kralja, naj ne zažiga zvitka, jih vendar ni poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 26, 'In zapovedal je kralj Jerahmielu, sinu kraljevemu, in Seraju, sinu Azrielovemu, in Selemiju, sinu Abdeelovemu, da naj primejo Baruha pisarja in Jeremija proroka; ali skril ju je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 27, 'Prišla je pa beseda Gospodova Jeremiju (ko je bil kralj sežgal tisti zvitek in besede, ki jih je bil Baruh zapisal iz ust Jeremijevih), govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 28, 'Zopet si vzemi drug zvitek in zapiši vanj vse poprejšnje besede, ki so bile v onem prejšnjem zvitku, ki ga je sežgal Jojakim, kralj Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 29, 'O Jojakimu pa, kralju Judovem, reci: Tako pravi Gospod: Ti si sežgal oni zvitek, rekoč: Zakaj si pisal v njem: Gotovo pride kralj babilonski in pogubi deželo to in stori, da izginejo iz nje ljudje in živina?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 30, 'Zatorej pravi tako Gospod o Jojakimu, kralju Judovem: Ne bo ga imel, da bi sedel na prestolu Davidovem, in truplo njegovo bo vrženo v vročino po dnevi in v mraz po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 31, 'Kajti kaznoval ga bom in seme njegovo in hlapce njegove za njih krivico; in pripeljem zoper nje in zoper prebivalce jeruzalemske in zoper može Judove vso tisto nesrečo, ki sem jo jim oznanjal, pa me niso poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 36, 32, 'Torej vzame Jeremija drug zvitek in ga da Baruhu, sinu Nerijevemu, pisarju. In on je zapisal vanj iz ust Jeremijevih vse besede knjige, ki jo je bil sežgal Jojakim, kralj Judov, v ognju; in še so jim bile pridejane mnoge take besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 1, 'In Zedekija, Josijev sin, ki ga je Nebukadnezar, kralj babilonski, postavil za kralja v deželi Judovi, je vladal kot kralj namesto Konija, sinu Jojakimovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 2, 'Ali ni poslušal ne on, ne hlapci njegovi, ne ljudstvo v deželi besed Gospodovih, ki jih je govoril po Jeremiju proroku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 3, 'Poslal je bil pač kralj Zedekija Jehukala, sina Selemijevega, in Zefanija, Maasejevega sina, duhovnika, k Jeremiju proroku, da naj rečeta: Prosi vendar za nas Gospoda, Boga našega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 4, 'Takrat je Jeremija prosto bival sredi ljudstva, ker ga še niso bili deli v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 5, 'In vojska Faraonova je šla iz Egipta; in Kaldejci, ki so oblegali Jeruzalem, so slišali glas o njih ter odšli od Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 6, 'In prišla je beseda Gospodova Jeremiju proroku, naj govori:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 7, 'Tako pravi Gospod, Bog Izraelov: Tako recite kralju Judovemu, ki vas je poslal vprašat me za svet: Glej, vojska Faraonova, ki je vam hotela priti na pomoč, se vrne v deželo svojo, v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 8, 'In Kaldejci se vrnejo in bodo oblegali to mesto, in ga bodo vzeli ter sežgali z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 9, 'Tako pravi Gospod: Ne slepite sami sebe, govoreč: Gotovo pojdejo od nas ti Kaldejci! kajti ne pojdejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 10, 'Da, ko bi pobili vsa krdela Kaldejcev, ki se bojujejo zoper vas, in bi ostalo od njih le nekoliko mož prebodenih, vstanejo vsak v svojem šatoru in požgo to mesto z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 11, 'In zgodi se, ko se je odpeljavala vojska Kaldejcev od Jeruzalema zavoljo vojske Faraonove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 12, 'da je šel Jeremija ven iz Jeruzalema, da bi popotoval med ljudstvo v deželo Benjaminovo, da prejme svoj delež odondod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 13, 'In ko je bil med vrati Benjaminovimi, kjer je stal poveljnik straže, po imenu Jerija, sin Selemija, sinu Hananija, zgrabi on Jeremija proroka, rekoč: H Kaldejcem hočeš uskočiti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 14, 'Jeremija pa reče: Ni res, nočem uskočiti h Kaldejcem! Vendar ga ni poslušal Jerija, ampak zgrabi Jeremija proroka in ga odpelje h knezom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 15, 'Tedaj so se raztogotili knezi zoper Jeremija in so ga pretepli in vrgli v ječo v hiši Jonatana pisarja; kajti to so bili pripravili za ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 16, 'In ko je prišel Jeremija v tisto luknjo in v izbice njene, kjer je ostal mnogo dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 17, 'tedaj pošlje kralj Zedekija in ga pokliče, in vpraša ga kralj v svoji hiši na skrivnem, rekoč: Je li neka beseda od Gospoda? In Jeremija reče: Je, namreč: V roko kralja babilonskega boš izdan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 18, 'Potem reče Jeremija kralju Zedekiju: Kaj sem grešil tebi ali hlapcem tvojim ali temu ljudstvu, da ste me deli v ječo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 19, 'Kje neki so proroki vaši, ki so vam prorokovali in govorili: Ne pride kralj babilonski zoper vas in zoper to deželo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 20, 'Zdaj pa poslušaj, prosim, gospod moj, kralj: Predte padam in te prosim, ne pošlji me nazaj v hišo Jonatana pisarja, da ne umrjem tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 37, 21, 'Tedaj je zapovedal kralj Zedekija, da naj denejo Jeremija v vežo straže; in dajali so mu hleb kruha na dan iz ulice pekovske, dokler ni bil ves kruh použit v mestu. Tako je ostal Jeremija v veži straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 1, 'In slišal je Sefatija, sin Matanov, in Gedalija, sin Pashurjev, in Jukal, sin Selemijev, in Pashur, sin Malkijev, besede, ki jih je Jeremija govoril vsemu ljudstvu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 2, 'Tako pravi Gospod: Kdor ostane v tem mestu, umrje od meča, lakote ali kuge; kdor pa pojde ven h Kaldejcem, bo živel, in življenje mu bo namesto plena in se ohrani v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 3, 'Tako pravi Gospod: Vsekakor bo to mesto dano v pest vojski kralja babilonskega, in on ga vzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 4, 'In rekli so knezi kralju: Usmrti naj se vendar ta mož! ker on dela, da pešajo roke bojevalcem, ki so še ostali v tem mestu, in roke vsemu ljudstvu, ko jim govori take besede; zakaj ta mož nikakor ne išče blaginje temu ljudstvu, ampak le nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 5, 'Njim pa reče kralj Zedekija: Glejte, v vaši roki je; kajti nič ne more kralj zoper vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 6, 'Vzemo torej Jeremija in ga vržejo v jamo Malkija, sinu kraljevega, ki je bila ob veži straže, spustivši Jeremija doli po vrveh. V jami pa ni bilo nič vode, ampak blato, in Jeremija se je pogreznil v blato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 7, 'In slišal je Ebedmelek, Etiopec, komornik, ki je bil v hiši kraljevi, da so vrgli Jeremija v tisto jamo; kralj pa je tedaj sedel v vratih Benjaminovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 8, 'In šel je Ebedmelek ven iz hiše kraljeve ter govoril kralju, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 9, 'Gospod moj, kralj! hudobno so delali ti možje v vsem, kar so storili Jeremiju proroku, ki so ga vrgli v jamo; umrje skoraj tam, kjer je, od glada, ker ni več kruha v tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 10, 'In kralj ukaže Ebedmeleku Etiopcu takole: Vzemi si s seboj odtod trideset mož in potegni Jeremija proroka iz jame, dokler še ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 11, 'Tedaj vzame Ebedmelek s seboj tiste može ter stopi v hišo kraljevo, v kraj pod zakladnico, odkoder vzame stare cunje in strohnele krpe; te spusti doli k Jeremiju v jamo po vrveh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 12, 'In reče Ebedmelek Etiopec Jeremiju: Deni si te stare cunje in strohnele krpe pod pazduhe in na vrvi! In Jeremija stori tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 13, 'In vlekli so Jeremija po vrveh in ga potegnili iz jame. Potem je ostal Jeremija v veži straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 14, 'In pošlje kralj Zedekija in pokliče Jeremija proroka k sebi k tretjemu vhodu, ki je bil pri hiši Gospodovi. In kralj veli Jeremiju: Prosim te besede božje, nič mi ne prikrivaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 15, 'In reče Jeremija Zedekiju: Če ti jo naznanim, me li gotovo ne usmrtiš? In če ti svetujem, me ne boš poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 16, 'Tedaj priseže kralj Zedekija skrivaj Jeremiju, rekoč: Kakor res živi Gospod, ki nam je ustvaril to dušo, ne usmrtim te in te ne dam v roko tistih mož, ki ti strežejo po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 17, 'Reče torej Jeremija Zedekiju: Tako pravi Gospod, Bog nad vojskami, Bog Izraelov: Če pojdeš in se vdaš knezom kralja babilonskega, ohraniš svoje življenje in to mesto ne bo sežgano z ognjem; in živel boš ti in hiša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 18, 'Če pa ne pojdeš h knezom kralja babilonskega, bo to mesto dano v roko Kaldejcem, ki ga požgo z ognjem; ti pa se ne otmeš iz njih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 19, 'Ko je pa rekel kralj Zedekija Jeremiju: Hudo se bojim Judov, ki so uskočili h Kaldejcem, da bi me ne dali v njih roko in se ne norčevali z menoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 20, 'je dejal Jeremija: Ne bodo te dali. Poslušaj, prosim, glas Gospodov, ki ti ga jaz oznanjam, in bode ti dobro in živela bo duša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 21, 'Če se pa braniš iti tja, je to beseda, katero mi je pokazal Gospod:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 22, 'Glej, vse žene, ki so ostale v hiši kralja Judovega, bodo odpeljane h knezom kralja babilonskega, in one bodo govorile: Premamili so te in premagali prijatelji tvoji; zdaj, ko so v blato pogreznjene noge tvoje, so se umeknili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 23, 'In vse žene tvoje in sinove tvoje odpeljejo h Kaldejcem, in ne iztrgaš se njih roki tudi ti ne, ampak roka kralja babilonskega te zgrabi in boš kriv, da se to mesto požge z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 24, 'Tedaj reče Zedekija Jeremiju: Nihče naj ne zve teh besed, da ne umrješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 25, 'Če pa slišijo knezi, da sem govoril s teboj, ter pridejo k tebi in ti reko: Povej nam brž, kaj si govoril kralju, nič nam ne prikrivaj, pa te ne usmrtimo; in kaj je kralj rekel tebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 26, 'tedaj jim porečeš: Padel sem pred kralja in ga prosil, naj mi ne pusti zopet iti v hišo Jonatanovo, da tam ne umrjem. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 27, 'Prišli so pa vsi knezi k Jeremiju ter ga vprašali; in jim je povedal po vseh tistih besedah, ki mu jih je zapovedal kralj. Tako so molčali in ga pustili, ker se ni razvedela ona beseda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 38, 28, 'In ostal je Jeremija v veži straže prav do dne, ko je bil vzet Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 1, 'In zgodilo se je, ko je bil vzet Jeruzalem (v devetem letu Zedekija, kralja Judovega, deseti mesec, je prišel Nebukadnezar, kralj babilonski, in vsa vojska njegova pred Jeruzalem, in oblegali so ga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 2, 'v enajstem letu Zedekija, četrti mesec, deveti dan meseca, so predrli v mesto),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 3, 'da so vstopili vsi knezi kralja babilonskega in sedli pri Srednjih vratih: Nergal-sarezer, Samgar-nebu, Sarsekim, glavar dvornikov, Nergal-sarezer, glavar magov, in vsi drugi knezi kralja babilonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 4, 'Ko jih pa zagleda Zedekija, kralj Judov, in vsi vojščaki, pobegnejo in uidejo iz mesta po noči po potu kraljevega vrta, skozi vrata med dvojnim zidom. In šel je po potu proti nižini Arabi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 5, 'Ali šla je za njimi vojska Kaldejcev, in došli so Zedekija na planjavi ob Jerihu; in ujeli so ga ter peljali k Nebukadnezarju, kralju babilonskemu, v Riblo, v deželi Hamatski. In on je izrekel sodbo zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 6, 'In poklal je kralj babilonski sine Zedekijeve v Ribli njemu pred očmi, tudi vse plemenitnike iz Judeje je umoril kralj babilonski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 7, 'In Zedekiju je oslepil oči in ga zvezal z dvema bronastima verigama, da ga odpelje v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 8, 'Hišo kraljevo pa in hiše ljudske so požgali Kaldejci z ognjem in obzidje jeruzalemsko so podrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 9, 'In ostanek ljudstva, kar jih je bilo še v mestu, in ubežnike, ki so uskočili k njemu, in ostanek ljudstva, kar jih je bilo še, je odpeljal Nebuzaradan, glavar telesne straže, v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 10, 'A izmed ljudstva najubožnejše, ki niso imeli ničesar, je Nebuzaradan, glavar telesne straže, pustil v deželi Judovi in jim dal vinogradov in njiv tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 11, 'Povelje pa je dal Nebukadnezar, kralj babilonski, Nebuzaradanu, glavarju telesne straže, zastran Jeremija, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 12, 'Vzemi ga in dobro pazi nanj in ne stori mu nič hudega, temuč delaj ž njim, kakor ti poreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 13, 'In poslal je Nebuzaradan, glavar telesne straže, in Nebusazban, glavar dvornikov, in Nergal-sarezer, glavar magov, in vsi mogočniki kralja babilonskega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 14, 'so poslali ter vzeli Jeremija iz veže straže in ga izročili Gedaliju, sinu Ahikama, sina Safanovega, naj ga pelje v hišo svojo. In tako je prebival sredi ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 15, 'In beseda Gospodova je prišla Jeremiju, ko je bil zaprt v veži straže, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 16, 'Pojdi in reci Ebedmeleku, Etiopcu, tole: Tako pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz izpolnim besede svoje o tem mestu v hudo, ne pa v dobro, in pred očmi tvojimi se uresničijo tistega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 17, 'Ali otmem te tisti dan, govori Gospod, in dan ne boš v roke možem, ki se jih bojiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 39, 18, 'Kajti gotovo te oprostim in od meča ne padeš; in življenje ti bode namesto plena, ker si stavil upanje na mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 1, 'Beseda, ki je prišla Jeremiju od Gospoda, potem ko ga je izpustil Nebuzaradan, glavar telesne straže, iz Rame, ko ga je bil dobil zvezanega z verigami sredi vseh ujetnikov iz Jeruzalema in iz Judeje, ki so jih odpeljavali v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 2, 'Sprejme torej glavar telesne straže Jeremija ter mu reče: Gospod, Bog tvoj, je napovedal to nesrečo zoper ta kraj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 3, 'in Gospod jo je pripeljal in storil, kakor je bil govoril, ker ste grešili zoper Gospoda in niste poslušali glasu njegovega; zato se vam je to zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 4, 'A sedaj glej, danes te oproščam teh verig, ki so na tvojih rokah; če se ti dobro vidi priti z menoj v Babilon, pridi; pazil bom dobro nate. Če se ti pa slabo zdi iti z menoj v Babilon, ostani tu. Glej, vsa dežela ti je odprta: kamor se ti zdi dobro in prav iti, tja pojdi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 5, 'Toda ker se on še ne more odločiti, mu veli: Povrni se h Gedaliju, sinu Ahikama, sina Safanovega, ki ga je kralj babilonski postavil čez mesta Judova, in bivaj pri njem sredi ljudstva; ali kamorkoli se ti prav vidi iti, tja pojdi! In glavar telesne straže mu je dal brašna in darilo ter ga je odpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 6, 'In Jeremija je prišel h Gedaliju, sinu Ahikamovemu, v Micpo, in prebival je ž njim sredi ljudstva, ki je bilo ostalo v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 7, 'Ko so pa slišali vsi poveljniki vojske, ki so bili na polju, oni in njih moštvo, da je kralj babilonski postavil čez deželo Gedalija, sina Ahikamovega, in da mu je izročil može in žene in otroke in nekaj ubožnega ljudstva dežele izmed tistih, ki se niso odpeljali v Babilon,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 8, 'pridejo v Micpo h Gedaliju: Izmael, sin Netanijev, in Johanan in Jonatan, sinova Kareahova, in Seraja, sin Tanhumetov, in sinovi Ofaja Netofatčana in Jezanija, sin Maakatovca, oni s svojimi možmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 9, 'In Gedalija, sin Ahikama, sinú Safanovega, priseže njim in njih možem in reče: Ne bojte se služiti Kaldejcem; ostanite v deželi in služite kralju babilonskemu, in vam bode dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 10, 'Kar se pa mene tiče, glejte, ostanem v Micpi, da služim Kaldejcem, ki pridejo k vam. Vi pa berite vino in poletni sad in olje in shranjujte jih v posode svoje; in stanujte v mestih svojih, ki ste jih posedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 11, 'In tudi vsi Judje, ki so bili v Moabu in med Amonci in med Edomci in v vseh tistih pokrajinah, ko so slišali, da je kralj babilonski ostavil ostanek na Judovem in da je čezenj postavil Gedalija, sina Ahikama, sinu Safanovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 12, 'so se vrnili vsi tisti Judje iz vseh krajev, kamor so bili odgnani, in prišli so v deželo Judovo h Gedaliju v Micpo. In nabrali so vina in poletnega sadu prav mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 13, 'Johanan pa, sin Kareahov, in vsi vojaški poveljniki, ki so bili na polju, pridejo h Gedaliju v Micpo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 14, 'in mu reko: Ali pač veš, da je Baalis, kralj Amoncev, poslal Izmaela, sina Netanijevega, da te pripravi ob življenje? Ali jim ni verjel Gedalija, sin Ahikamov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 15, 'In Johanan, sin Kareahov, je govoril skrivaj v Micpi Gedaliju, rekoč: Naj grem vendar in ubijem Izmaela, sina Netanijevega, in nihče ne bo vedel. Čemu naj te pripravi ob življenje, da bi se razkropili vsi Judje, ki so se zbrali pri tebi, in bi poginil ostanek Judov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 40, 16, 'Ali Gedalija, sin Ahikamov, je rekel Johananu, sinu Kareahovemu: Ne stori tega, kajti lažnivo govoriš o Izmaelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 1, 'Zgodi se pa sedmi mesec, da pride Izmael, sin Netanija, sina Elisamovega, iz kraljevega zaroda in iz kraljevih glavarjev, in deset mož ž njim h Gedaliju, sinu Ahikamovemu, v Micpo; in jedli so skupaj jed tam v Micpi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 2, 'Vstane pa Izmael, sin Netanijev, in deseteri možje, ki so bili ž njim, in so udarili Gedalija, sina Ahikama, sinu Safanovega, z mečem in so usmrtili njega, ki ga je bil kralj babilonski postavil nad deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 3, 'In vse Jude, ki so bili ž njim, z Gedalijem, v Micpi, je pobil Izmael, in tudi Kaldejce, vojščake, tam pričujoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 4, 'Zgodi se pa drugi dan, odkar je usmrtil Gedalija, ko ni še nihče vedel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 5, 'da pridejo možje iz Sihema, iz Sila in iz Samarije, osemdeset mož, z obrito brado in raztrgano obleko in razpraskani, z jedilnim darom in kadilom v roki, da ga prineso v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 6, 'In šel je Izmael, sin Netanijev, ven iz Micpe njim naproti, in gredoč je neprestano jokal, in ko jih je srečal, jim reče: Pridite h Gedaliju, sinu Ahikamovemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 7, 'Ali ko so prišli sredi mesta, jih umori Izmael, sin Netanijev, in jih vrže v jamo, on in možje, ki so bili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 8, 'Desetero mož pa je bilo med njimi, ki so rekli Izmaelu: Ne usmrti nas! kajti skrite zaklade imamo na polju, pšenice in ječmena in olja in medu. Torej je odnehal in jih ni usmrtil ž njih brati vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 9, 'Jama pa, ki je vanjo vrgel vsa trupla mož, ki jih je bil pobil, poleg Gedalija, je bila tista, ki jo je naredil Asa v strahu pred Baasom, kraljem Izraelovim; njo je napolnil s pobitimi Izmael, sin Netanijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 10, 'In Izmael je odpeljal v ujetništvo ves ostanek ljudstva, ki je bilo v Micpi: hčere kraljeve in vse ljudstvo, kar ga je preostalo v Micpi in ki ga je izročil Nebuzaradan, glavar telesne straže, Gedaliju, sinu Ahikamovemu; nje je ujete odpeljal Izmael, sin Netanijev, ter odrinil, da bi prešel k sinom Amonovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 11, 'In ko je slišal Johanan, sin Kareahov, in vsi vojaški poveljniki, ki so bili ž njim, vse tisto zlo, ki ga je napravil Izmael, sin Netanijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 12, 'skličejo vse može in odrinejo bojevat se zoper Izmaela, sina Netanijevega, ter ga zalotijo pri veliki vodi, ki je ob Gibeonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 13, 'In ko vidi vse ljudstvo, ki je bilo z Izmaelom, Johanana, sina Kareahovega, in vse vojaške poveljnike ž njim, se razveseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 14, 'Vse ljudstvo torej, ki ga je peljal Izmael ujeto iz Micpe, se izpremisli in se obrne in gre k Johananu, sinu Kareahovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 15, 'Izmael pa, sin Netanijev, je zbežal z osmimi možmi izpred Johanana ter odšel k sinom Amonovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 16, 'Tedaj vzame Johanan, sin Kareahov, in vsi vojaški poveljniki, ki so bili ž njim, ves ostanek ljudstva, ki ga je nazaj dobil od Izmaela, sina Netanijevega, iz Micpe, – potem ko je bil ubil Gedalija, sina Ahikamovega, – in peljali so može, vojščake, in žene in otroke in komornike nazaj iz Gibeona;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 17, 'in so šli ter se ustavili v prenočišču Kimhamovem, ki je blizu Betlehema, da bi se napotili in odšli v Egipt');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 41, 18, 'zavoljo Kaldejcev, ker so se jih bali, zato ker je Izmael, sin Netanijev, umoril Gedalija, sina Ahikamovega, ki ga je bil kralj babilonski postavil nad deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 1, 'Nato pristopijo vsi vojaški poveljniki in Johanan, sin Kareahov, in Jezanija, sin Hosajev, in vse ljudstvo od najmanjšega do največjega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 2, 'in reko Jeremiju proroku: Sprejmi milo prošnjo našo in prosi za nas Gospoda, svojega Boga, za ves ta ostanek; kajti ostalo nas je malo od mnogih, kakor nas vidiš;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 3, 'da nam pokaži Gospod, tvoj Bog, pot, po katerem naj hodimo, in reč, katero naj storimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 4, 'In reče jim Jeremija prorok: Slišal sem vas; glejte, prosil bom Gospoda, vašega Boga, po vaših besedah; in katerokoli besedo vam odgovori Gospod, vam jo naznanim, ne zadržim vam nobene besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 5, 'In Oni reko Jeremiju: Gospod bodi zoper nas priča resnična in zvesta, če ne bomo ravnali po vsaki besedi, s katero te pošlje k nam Gospod, tvoj Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 6, 'Bodisi dobro ali slabo, bomo poslušali glas Gospoda, Boga svojega, ki te k njemu pošiljamo; da bi se nam dobro godilo, ko bomo poslušali glas Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 7, 'Ko pa je minilo deset dni, je prišla beseda Gospodova Jeremiju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 8, 'Tedaj pokliče Johanana, sina Kareahovega, in vse vojaške poveljnike, ki so bili ž njim, in vse ljudstvo od najmanjšega do največjega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 9, 'in jim reče: Tako pravi Gospod, Bog Izraelov, ki ste me k njemu poslali, da padem predenj z vašo prošnjo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 10, 'Če hočete ostati v tej deželi, vas bom zidal in ne podiral ter vas sadil in ne roval, ker mi je žal hudega, katero sem vam storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 11, 'Ne bojte se kralja babilonskega, ki se ga bojite; ne bojte se ga, govori Gospod, ker jaz sem z vami, da vas ohranim in vas otmem iz roke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 12, 'In izkažem vam usmiljenje, da se vas usmili in vam dovoli vrniti se na domača tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 13, 'Ako pa porečete: Ne ostanemo v tej deželi, in ne boste poslušali glasu Gospoda, Boga svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 14, 'pa boste govorili: Nikar, ampak v deželo Egiptovsko pojdemo, kjer ne bomo videli nobene vojske, ne slišali glasu trobente, ne stradali kruha, in tam bomo prebivali –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 15, 'zdaj torej čujte besedo Gospodovo, ostanek Judov! Tako pravi Gospod nad vojskami, Bog Izraelov: Če res obrnete obličje svoje, da bi šli v Egipt, in če pojdete tja prebivat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 16, 'zgodi se, da vas meč, ki se ga bojite, dojde tam v deželi Egiptovski; in lakota, katere vas je groza, vas bo preganjala tam v Egiptu, in tam umrjete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 17, 'In zgodi se, da vsi možje, ki so obrnili obličje svoje, da bi šli v Egipt in tam prebivali, pomrjejo od meča, lakote in kuge, in nihče ne preostane, tudi ne ubeži tisti nesreči, ki jo jaz pošljem nadnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 18, 'Kajti tako pravi Gospod nad vojskami, Bog Izraelov: Kakor se je izlila jeza in togota moja nad prebivalce jeruzalemske, tako se izlije togota moja nad vas, ko pridete v Egipt; in bodete v preklinjanje in strmenje in v kletev in sramoto, in ne boste več videli tega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 19, 'Govoril vam je Gospod, o ostanek Judov: Ne hodite v Egipt! Dobro vedite, da sem vam to danes resno izpričal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 20, 'Varate se namreč duši svoji v škodo. Zakaj poslali ste me h Gospodu, Bogu svojemu, rekoč: Prosi za nas Gospoda, našega Boga; in vse, karkoli zapove Gospod, naš Bog, nam natanko naznani, in storili bomo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 21, 'In danes sem vam naznanil, a ne poslušate glasu Gospoda, Boga svojega in vsega, za kar me pošilja k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 42, 22, 'Zdaj torej, vedite dobro, da umrjete od meča, lakote in kuge v kraju, kamor se vam hoče iti, da bi prebivali ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 1, 'Zgodi se pa, ko je nehal Jeremija naznanjati vsemu ljudstvu vse besede Gospoda, njih Boga, zavoljo katerih ga je poslal Gospod k njim, vse tiste besede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 2, 'da je rekel Azarija, sin Hosajev, in Johanan, sin Kareahov, in vsi oni prevzetni možje so rekli Jeremiju: Lažnivo govoriš! Ni te poslal Gospod, Bog naš, da veliš: Ne hodite v Egipt, da bi tam prebivali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 3, 'temuč Baruh, Nerijev sin, te ščuje zoper nas, da nas dá v roko Kaldejcem, ki naj nas usmrte ali odpeljejo v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 4, 'In ni poslušal Johanan, sin Kareahov, in vsi vojaški poveljniki in vse ljudstvo glasu Gospodovega, da bi ostali v deželi Judovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 5, 'ampak Johanan, Kareahov sin, in vsi vojaški poveljniki so vzeli vse ostanke Judove, ki so se bili vrnili od vseh narodov, kamor so bili odgnani, hoteč bivati v deželi Judovi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 6, 'može in žene, otroke in kraljeve hčere in vse duše, ki jih je bil ostavil Nebuzaradan, glavar telesne straže, pri Gedaliju, sinu Ahikama, sina Safanovega, tudi proroka Jeremija in Baruha, Nerijevega sina,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 7, 'in napotili so se v deželo Egiptovsko, kajti niso poslušali glasu Gospodovega. In dospeli so v Tahpanhes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 8, 'Prišla pa je beseda Gospodova Jeremiju v Tahpanhesu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 9, 'Vzemi v roko svojo velike kamene in jih skrij v ilovico ob opekarnici, ki je v Tahpanhesu pri vhodu v hišo Faraonovo, pred očmi mož Judovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 10, 'in jim reci: Tako pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz pošljem in vzamem Nebukadnezarja, kralja babilonskega, hlapca svojega, in prestol njegov postavim nad te kamene, ki sem jih skril, in nad njimi razpne svoj kraljevski šator.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 11, 'Kajti pride in udari deželo Egiptovsko: kdor je za smrt, bode za smrt, in kdor za sužnost, za sužnost, in kdor pod meč, pod meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 12, 'In ogenj zažgem v hišah bogov egiptovskih, da jih požge in odpelje v ujetništvo. In obleče se v Egiptovsko deželo, kakor se pastir obleče v svoj plašč; in odide odtod v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 43, 13, 'In razbije stebre v Bet-semesu, ki je v deželi Egiptovski, in požge z ognjem hiše bogov egiptovskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 1, 'Beseda, ki je prišla Jeremiju zoper vse Jude, ki so prebivali v deželi egiptovski, stanujoč v Migdolu in Tahpanhesu in Nofu in v deželi Patroški, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 2, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Vi ste videli vso tisto nesrečo, ki sem jo pripeljal nad Jeruzalem in nad vsa mesta Judova, tako da so, glej, puščava današnji dan, nihče ne prebiva v njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 3, 'zavoljo njih hudobnosti, ki so jo počenjali, da bi me dražili, ko so hodili kadit in častit tuje bogove, ki jih niso poznali ne oni, ne vi ali očetje vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 4, 'Ko sem pa k vam pošiljal vse služabnike svoje, proroke, od ranega jutra in neprenehoma, govoreč: Ne delajte vendar te gnusobe, ki jo sovražim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 5, 'vendar niso poslušali in niso nagnili ušesa svojega, da bi se izpreobrnili od hudobnosti svoje, da bi ne kadili tujim bogovom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 6, 'Zato se je razlila togota in jeza moja, in vnela se je v mestih Judovih in po ulicah jeruzalemskih, da so bile opustošene, zapuščene, kakor so dandanašnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 7, 'Sedaj pa pravi tako Gospod, Bog nad vojskami, Bog Izraelov: Zakaj počenjate to veliko hudobnost zoper svoje duše, da bi pokončali moža in ženo, otroka in dojenca iz Jude, da si ne zapustite več ostankov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 8, 'Dražite me z deli svojih rok, kadeč tujim bogovom v deželi Egiptovski, kamor ste prišli prebivat, da bi pokončali sebe in bi postali kletev in sramota pri vseh narodih na zemlji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 9, 'Ali ste mar pozabili hudobnosti očetov svojih in hudobnosti kraljev Judovih in hudobnosti njih žen in svoje hudobnosti in hudobnosti žen svojih, ki so jih počenjali v deželi Judovi in po ulicah jeruzalemskih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 10, 'Niso bili potrti do tega dne in niso se bali, tudi niso hodili po postavi in po naredbah mojih, ki sem jih del pred oči vam in očetom vašim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 11, 'Zatorej pravi tako Gospod nad vojskami, Bog Izraelov: Glej, jaz obrnem obličje svoje proti vam v hudo, da iztrebim vse Judove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 12, 'In vzamem ostanke Judove, ki so obrnili obličje svoje, da pojdejo v deželo Egiptovsko prebivat, in uničeni bodo vsi, padli bodo v deželi Egiptovski: meč, lakota jih uniči, od najmanjšega do največjega pomrjo po meču in lakoti; in bodo v preklinjanje in strmenje, v kletev in sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 13, 'Kajti kaznoval bom nje, ki prebivajo v deželi Egiptovski, kakor sem kaznoval Jeruzalem z mečem, lakoto in kugo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 14, 'tako da ga ne bode izmed ostankov Judovih, ki so šli v deželo Egiptovsko prebivat, ki bi ušel ali ostal in bi se povrnil v deželo Judovo, kamor jih vleče hrepenenje, da se smejo povrniti in prebivati tam; kajti ne povrnejo se, razen nekoliko ubežnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 15, 'Odgovore pa Jeremiju vsi možje, ki so vedeli, da njih žene kade tujim bogovom, in vse ženske, ki jih je tu stala velika množica, in vse ljudstvo prebivajočih v deželi Egiptovski v Patrosu in reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 16, 'Kar se tiče besede, ki si jo nam oznanil v imenu Gospodovem, ne bomo te poslušali nikakor;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 17, 'ampak gotovo storimo, kar koli pride iz naših ust, kadeč kraljici nebeški in darujoč ji pitne daritve, kakor smo delali mi in očetje naši, kralji in knezi naši v mestih Judovih in po ulicah jeruzalemskih. Takrat smo imeli obilo kruha in bili smo veseli in hudega nismo izkusili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 18, 'Odkar pa smo nehali kaditi nebeški kraljici in ji darovati pitne daritve, pogrešamo vsega in meč in lakota nas pokončujeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 19, 'Ko smo pa kadile nebeški kraljici in ji darovale pitne daritve, ali ji brez vednosti svojih mož delamo kolače, da jo počastimo, in ji darujemo pitne daritve?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 20, 'A Jeremija reče vsemu ljudstvu, možem in ženam in vsemu ljudstvu, ki so mu tako odgovorili, in veli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 21, 'Tistega kadila, ki ste ga palili v mestih Judovih in po ulicah jeruzalemskih vi in očetje vaši, kralji in knezi vaši in ljudstvo dežele, ali se ga ni spomnil Gospod in ni li mu prišlo v misli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 22, 'In Gospod ni mogel tega več trpeti zavoljo hudobnosti vaših del, zavoljo gnusob, ki ste jih delali. Zato je dežela vaša postala puščava, stvar strmenja in preklinjanja, brez prebivalcev, kakor je dan današnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 23, 'Zato ker ste kadili in ker ste grešili zoper Gospoda in niste poslušali glasu Gospodovega in niste živeli po njegovi postavi in po naredbah in pričevanjih njegovih: zato vas je zadela ta nesreča, kakor je dan današnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 24, 'Še reče Jeremija vsemu ljudstvu in vsem ženam: Poslušajte besedo Gospodovo, vsi Judovi, ki ste v deželi Egiptovski:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 25, 'Tako pravi Gospod nad vojskami, Bog Izraelov: Vi in žene vaše ste govorili z usti svojimi in svojeročno ste to dopolnili, ko ste rekli: Gotovo izpolnimo obljube svoje, ki smo jih obljubili, da bomo kadili kraljici nebeški in ji darovali pitne daritve. Torej le opravljajte obljube svoje in vsekakor izpolnjujte obljube svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 26, 'Zato poslušajte besedo Gospodovo, vsi Judje, ki prebivate v deželi Egiptovski: Glejte, jaz sem prisegel pri svojem velikem imenu, pravi Gospod, da se ne bo nikdar več imenovalo ime moje z usti katerega moža judovskega v vsej deželi Egiptovski, da bi rekel: Kakor res živi Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 27, 'Glej, jaz čujem nad njimi v hudo, a ne v dobro; in vse može Judove, ki so v deželi Egiptovski, končata meč in lakota, dokler ne poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 28, 'In kateri ubeže meču, se vrnejo iz dežele Egiptovske v deželo Judovo, neznatni po številu. In izkusi ves ostanek Judov, kolikor jih je šlo v deželo Egiptovsko, da bi tam prebivali, čigava beseda obvelja, moja ali njihna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 29, 'In to vam bodi znamenje, govori Gospod, da vas bom kaznoval na tem kraju, da bi vedeli, da res obveljajo besede moje zoper vas v hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 44, 30, 'Tako pravi Gospod: Glej, jaz dam Faraona Hofra, kralja egiptovskega, v roko sovražnikov njegovih in v pest njim, ki mu strežejo po življenju, kakor sem dal Zedekija, kralja Judovega, v roko Nebukadnezarja, kralja babilonskega, sovražnika njegovega in ki mu je stregel po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 1, 'Beseda, ki jo je govoril Jeremija prorok Baruhu, sinu Nerijevemu, ko je pisal v knjigo te besede iz ust Jeremijevih, v četrtem letu Jojakima, sinu Josijevega, kralja Judovega, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 2, 'Tako pravi Gospod, Bog Izraelov, zastran tebe, Baruh:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 3, 'Ti govoriš: Gorje meni! ker Gospod je pridel togo žalosti moji; utrujen sem v zdihovanju svojem in ne najdem pokoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 4, 'Tako mu boš govoril: Glej, kar sem sezidal, podiram, in kar sem vsadil, rujem, in to po vsej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 45, 5, 'In ti bi iskal sebi velikih reči? Ne išči jih! zakaj, glej, jaz pripeljem nesrečo nad vse meso, govori Gospod; tebi pa dam dušo tvojo za plen v vseh krajih, kamorkoli pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 1, 'Beseda Gospodova, ki je prišla Jeremiju proroku zoper poganske narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 2, 'O Egiptu. Zoper vojsko Faraona Nekona, kralja egiptovskega, ki je bila v Karkemišu pri reki Evfratu, ki jo je udaril Nebukadnezar, kralj babilonski, v četrtem letu Jojakima, sinu Josija, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 3, 'Pripravite ščite male in velike ter bližajte se boju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 4, 'Vprezite konje in zasedite jih, o konjiki! in postavite se v šlemih, gladite sulice, oblačite oklepe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 5, 'Zakaj jih vidim preplašene, zavrnjene? in njih junaki so pobiti in begoma beže in se ne ozirajo – strah je povsod, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 6, 'Ne ubeži, kdor je lehak, in ne otme se, kdor je mogočen; proti severu ob reki Evfratu se spotikajo in padajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 7, 'Kdo je ta, ki vzhaja kakor Nil, kakor reke se vale vode njegove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 8, 'Egipčan vzhaja kakor Nil in kakor reke se vale vode njegove; in govori: Gori pojdem, zemljo pokrijem, pogubim mesto in prebivalce njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 9, 'Dirjajte gori, o konji, in besno drdrajte, o vozovi; in pridejo naj junaki: Kuš in Put, ki sučeta ščit, in Ludimi, ki nosijo in napenjajo lok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 10, 'Ali tisti dan bode Gospodu, Jehovi nad vojskami, maščevanja dan, da bi se maščeval nad svojimi sovražniki; in žrl bo meč in se sitil in napajal z njih krvjo. Zakaj Gospod, Jehova nad vojskami, ima klalno žrtev v severni deželi pri reki Evfratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 11, 'Idi gori v Gilead in prinesi balzama, hči, devica egiptovska! Zaman rabiš mnoga zdravila, ni ozdravitve zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 12, 'Narodi so slišali o sramoti tvoji, in vpitja tvojega je zemlja polna; kajti junaka sta zadela drug ob drugega in oba sta padla skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 13, 'Beseda, ki jo je govoril Gospod Jeremiju proroku o prihodu Nebukadnezarja, kralja babilonskega, da udari zemljo Egiptovsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 14, 'Oznanjujte v Egiptu in oklicujte v Migdolu, oklicujte tudi v Nofu in Tahpanhesu! Recite: Stoj in pripravljaj se! kajti meč pokončava vse kroginkrog tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 15, 'Zakaj so ob tla vrženi vsi junaki tvoji? Nobeden ni obstal, ker ga je zvrnil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 16, 'Storil je, da so se spoteknili mnogi, da, mož čez moža so padli, in rekli so: Vstanimo, da se povrnemo k ljudstvu svojemu in k rojstnim tlem svojim, iz strahu pred zatirajočim mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 17, 'Vpijejo tam: Faraon, kralj egiptovski, je izgubljen; zamudil je ustanovljeni čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 18, 'Kakor res živim, govori Kralj, ki mu je ime Jehova nad vojskami: Kakor Tabor med gorami in kakor Karmel ob morju pride kralj babilonski!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 19, 'O hči, prebivalka v Egiptu! pripravi si svoje reči za selitev; kajti Nof postane puščava in požgan bo, da ne bo nihče v njem prebival.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 20, 'Telica prelepa je Egipt; a obad ji pride, pride od severa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 21, 'Tudi najeti vojaki njegovi sredi njega so kakor pitana teleta, tudi oni so se obrnili, bežali skupaj, niso se ustavili; kajti prišel je nadnje njih pogube dan, čas njih obiskovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 22, 'Glas njegov je kakor kače šum, ko vstran hiti; kajti Kaldejci se bodo bližali s krdeli in prišli s sekirami nadenj kakor drvarji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 23, 'posekajo gozd njegov, govori Gospod, ker jih ni moči sešteti; zakaj več jih je nego kobilic in ni jim števila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 24, 'Osramočena bo hči egiptovska, dana v pest severnemu ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 25, 'Pravi Gospod nad vojskami, Bog Izraelov: Glej, jaz bom kaznoval Amona iz Tebena in Faraona in Egipt, njegove bogove in njegove kraljiče, da, Faraona in nje, ki upajo vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 26, 'In dam jih v pest njim, ki jim strežejo po življenju, namreč v roko Nebukadnezarja, kralja babilonskega, in v roko hlapcev njegovih. Pozneje pa se bo zopet prebivalo v njem kakor v prejšnjih dnevih, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 27, 'Ti pa se ne boj, hlapec moj Jakob, in ne plaši se, o Izrael! zakaj, glej, jaz te ohranim iz daljave in zarod tvoj iz dežele sužnosti njegove; in povrne se Jakob in bo počival in mirno živel, in nihče ga ne bo strašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 46, 28, 'Ti se ne boj, hlapec moj Jakob, govori Gospod, zakaj na strani sem ti. Kajti pokončanje napravim med vsemi narodi, kamor sem te pregnal; s teboj pa ne napravim pokončanja, ampak strahoval te bom zmerno, a te ne pustim čisto brez kazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 1, 'Beseda Gospodova, ki je prišla Jeremiju proroku zoper Filistejce, ko ni bil še Faraon porazil Gaze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 2, 'Tako pravi Gospod: Glej, vode derejo sem od severa in naraščajo v preplavljajoč hudournik, da preplavijo deželo in vse, kar je v njej, mesto in nje, ki prebivajo v njem. In vpili bodo ljudje in vsi prebivalci v deželi bodo tulili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 3, 'Od glasu bonenja kopit močnih konj njegovih, od stresavanja voz njegovih, od ropotanja koles njegovih se ne ozro očetje po sinovih svojih, ker jim bodo omahovale roke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 4, 'zavoljo tistega dneva, ki pride, da bi bili oplenjeni vsi Filistejci, da bi bil zatrt v Tiru in Sidonu vsak pomočnik, ki še preostaja; kajti Gospod opustoši Filistejce, ostanek primorja Kaftorskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 5, 'Pleša je prišla nad Gazo, uničen je Askelon, ostanek njih doline. Doklej si boš delal vrezke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 6, 'Gorje! meč Gospodov, doklej ne boš počival? Vrni se v nožnico, pokojen bodi in miruj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 47, 7, 'Kako bi počival? Saj mu je ukazal Gospod. Zoper Askelon in zoper morsko obrežje, tja ga je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 1, 'O Moabu. Tako pravi Gospod nad vojskami, Bog Izraelov: Gorje Nebu! kajti opustošeno je. Osramočen, vzet je Kirjataim; osramočena je trdnjava na visočini in zbegana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 2, 'Nobene slave ni Moabu več. V Hesbonu izmišljajo hudo zoper njega: „Pridite in iztrebimo ga, da ne bode več narod!“Tudi ti, Madmen, boš uničen; meč pojde za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 3, 'Čuj! vpitje od Horonaima: Opustošenje in podrtje veliko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 4, 'Polomljen je Moab; vpitje zaganjajo otročiči njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 5, 'Kajti po klancu ob Luhitu bodo stopali navzgor z neprestanim jokom; zakaj po potu doli v Horonaim se je slišalo vpitje v strahu o razdejanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 6, 'Bežite, rešite si življenje ter bodite kakor golo drevo v puščavi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 7, 'Kajti zato, ker ti je bilo upanje v delih tvojih in zakladih tvojih, boš tudi ti ujet; ven pojde Kamos v pregnanstvo, duhovniki njegovi in knezi njegovi vsi skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 8, 'In pride razdejalec zoper vsako mesto, nobeno se ne reši; in dolina bo ugonobljena in ravan pogubljena, kakor je govoril Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 9, 'Dajte Moabu peruti, da leteč odide; kajti mesta njegova bodo zapuščena, da ne bo nihče prebival v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 10, 'Proklet, kdor opravlja delo Gospodovo nemarno, in proklet, kdor meč svoj zadržuje od krvi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 11, 'Brezskrbno je živel Moab od mladosti svoje in mirno je sedel na svojih drožeh, in ni se prelival iz posode v posodo in v pregnanstvo ni šel nikdar: zato je ostal okus njegov v njem in duh njegov se ni izpremenil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 12, 'Zatorej, glej, pridejo dnevi, govori Gospod, ko pošljem nadenj tiste, ki izlivajo posode, in ga izlijejo, in izpraznijo posode njegove in razdrobé vrče njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 13, 'Tedaj se bo sramoval Moab Kamosa, kakor se je sramovala hiša Izraelova Betela, ki so vanj upali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 14, 'Kako govorite: Junaki smo in možje vrli v vojski?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 15, 'Opustošen je Moab, na gradove njegove so zlezli sovražniki, in izbrani mladeniči njegovi so šli doli v klanje, govori Kralj, ki mu je ime Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 16, 'Blizu je poguba Moabova, da pride, in nesreča njegova hiti silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 17, 'Žalujte nad njim, kateri bivate okoli njega, in vsi, ki poznate ime njegovo, govorite: Kako je zlomljeno žezlo tako močno, palica veličastna!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 18, 'Stopi doli s slave svoje in sedi v žejnem kraju, o hči, ki prebivaš v Dibonu! kajti razdejalec Moabov je prišel gori zoper tebe, je podrl trdnjave tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 19, 'Poleg pota se postavi in opazuj, prebivalka aroerska, poprašuj bežečega in ženo, ki se otimlje, in reci: Kaj se je zgodilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 20, 'Sramuje se Moab, ker je potrt. Tulite in vpijte, oznanjujte pri Arnonu, da je Moab opustošen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 21, 'In sodba je prišla nad deželo ravnine, nad Holon in nad Jahzo in nad Mefaat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 22, 'in nad Dibon in nad Nebo in nad Bet-diblataim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 23, 'in nad Kirjataim in nad Bet-gamul in nad Bet-meon');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 24, 'in nad Kerjot in nad Bozro in nad vsa mesta dežele Moabove, daljna in bližnja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 25, 'Odsekal se je rog Moabu in rama njegova se je zlomila, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 26, 'Upijanite ga, ker se je poveličeval zoper Gospoda, da naj se valja po tem, kar izbljuje, in bode v posmeh tudi sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 27, 'Ali ti ni bil v posmeh Izrael? ali je bil zasačen med tatovi, da si zmajeval z glavo, kadar koli si govoril o njem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 28, 'Zapustite mesta in prebivajte v skalah, o prebivalci na Moabskem, in bodite podobni golobu, ki gnezdi ob robu prepada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 29, 'Čuli smo prevzetnost Moabovo, da je silno ošaben, visokost njegovo in oholost in nadutost njegovo in kako se mu je srce poviševalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 30, 'Jaz poznam, govori Gospod, togoto njegovo in ničevo bahanje njegovo; nepošteno je delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 31, 'Zato tulim zavoljo Moaba in zavoljo vsega Moaba vpijem; zaradi mož v Kir-heresu zdihujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 32, 'Bolj nego nad Jazerjem se jokam nad teboj, o trta v Sibmi! odrastki tvoji so šli čez morje, prav do morja Jazerskega so segali. Nad poletno sadje tvoje in nad trgatev tvojo je planil razdejalec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 33, 'in veselje je izginilo in radost z rodovitne njive in iz dežele Moabove. Storil sem, da je minilo vino iz kadi; tlačili ne bodo več vriskaje: vriskanje ne bode več vriskanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 34, 'V Hesbonu so vpili in tja do Eleala, tja do Jahaza se je razlegal njih glas, od Zoarja do Horonaima, do Eglat-šelišije; kajti tudi vode nimrimske se izpremene v pustinjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 35, 'In storim, da pogine v Moabu, govori Gospod, kdor daruje na višavi in kdor kadi bogovom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 36, 'Zato poje žalno srce moje kakor piščali zavoljo Moaba, in srce moje žalno piska zavoljo ljudi v Kir-heresu, ker se pogubi zaloga, ki jo je nahranil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 37, 'Kajti vsaka glava ima plešo in vsaka brada je ostrižena; po vseh rokah so zareze in na ledjih raševina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 38, 'Po vseh strehah Moabovih in po ulicah njegovih je zgolj žalovanje; kajti strl sem Moaba kakor posodo, ki ni nobenega veselja v njej, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 39, 'Kako je potrt! kako tulijo! Kako je obrnil Moab tilnik v sramoti! Tako bode Moab v posmeh in v strmenje vsem, ki prebivajo okoli njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 40, 'Kajti tako pravi Gospod: Glej, orlu podoben prileti sovražnik in peruti svoje razpne čez Moaba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 41, 'Kerjot je vzet in trdnjave so zasedene; in srce junakov v Moabu bo tisti dan kakor srce žene, ki trpi porodne bolečine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 42, 'In pokončan bo Moab, da ne bode ljudstvo, ker se je poveličeval zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 43, 'Groza in jama in zanka ti preté, o prebivalec v Moabu! govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 44, 'Kdor ubeži grozi, pade v jamo, in kdor prileze iz jame, se ujame v zanko; kajti privedem nanj, na Moaba, leto njegovega obiskovanja, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 45, 'V senci hesbonski stoje brezmočni tisti, ki so bežali pred silo; ali ogenj pride iz Hesbona in plamen izsredi Sihona, ki pokonča stran Moaba in teme njih, ki samo ropotajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 46, 'Gorje ti, o Moab! ljudstvo Kamosovo pogine; kajti sinovi tvoji bodo vlečeni v ujetništvo in hčere tvoje v sužnost. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 48, 47, 'Vendar pripeljem nazaj ujetnike Moabove v poslednjih dneh, govori Gospod. Dotlej sodba Moabova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 1, 'O sinovih Amonovih. Tako pravi Gospod: Ali nima sinov Izrael? ali nima nobenega dediča? Zakaj ima Malkom v lasti Gad in ljudstvo njegovo prebiva v mestih Izraelovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 2, 'Zatorej, glej, pridejo dnevi, govori Gospod, ko storim, da se bo slišal proti Rabi sinov Amonovih vojni hrup, in bode v kup podrtin in njene vasi se požgo z ognjem. In Izrael bode dedič njih, ki so njegovo last podedovali, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 3, 'Tuli, o Hesbon, kajti opustošen je Aj! Vpijte, hčere Rabe, opašite se z raševino; jokajte in tekajte semtertja med ograjami! kajti Malkom pojde v pregnanstvo, duhovniki in knezi njegovi vsi skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 4, 'Kaj se ponašaš z dolinami, da je polna dolina tvoja, o hči verolomna? ki se zanašaš na zaklade svoje, govoreč: Kdo bi me napadel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 5, 'Glej, jaz izpustim zoper tebe grozo od vseh okoličanov tvojih, govori Gospod, Jehova nad vojskami; in odženo vas, vsakega v stran njegovo, in nikogar ne bode, da bi zbiral tavajoče. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 6, 'Vendar pripeljem potem nazaj ujetnike sinov Amonovih, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 7, 'O Edomu. Tako pravi Gospod nad vojskami: Ali ni nobene modrosti več v Temani? Je li izginil svèt med razumnimi, minila njih modrost?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 8, 'Bežíte, obrnite se, iščite globoka prebivališča, o prebivalci v Dedanu; zakaj nesrečo Ezavovo pripeljem nadenj, čas, ko ga obiščem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 9, 'Če ti pridejo trgači, ali bi ne pustili paberkov grozdja? če tatje po noči, bi pokončali, kar bi jim bilo zadosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 10, 'Ali jaz sem ogolil Ezava, odkril, kar je bilo skritega, in ne bo se mogel skriti; opustošeno je seme njegovo in bratje njegovi in sosedje njegovi, in ni jih več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 11, 'Popústi sirote svoje, jaz jih ohranim žive, in vdove tvoje naj stavijo up svoj name.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 12, 'Kajti tako pravi Gospod: Glej, katerim ni bilo sojeno piti to čašo, jo morajo piti; ti pa sam naj bi bil čisto brez kazni? Ne bodeš brez kazni, ampak gotovo boš pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 13, 'Kajti pri sebi sem prisegel, govori Gospod, da bode Bozra v strmenje, sramoto, razdejanje in preklinjanje; in vsa mesta edomska bodo večne puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 14, 'Glas sem čul od Gospoda, in poslanec je poslan k narodom: Zberite se in napadite ga in vstanite na boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 15, 'Zakaj, glej, majhnega sem te naredil med narodi, zaničevanega med ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 16, 'Groznost tvoja in prevzetnost duše tvoje te je premotila, o ti, ki prebivaš v brlogih skalnatih, ki si zasedel griča višino. Če napraviš visoko kakor orel gnezdo svoje, vržem te odondod doli, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 17, 'In Edom postane stvar strmenja: kdorkoli pojde mimo njega, bo strmel in žvižgal zavoljo vseh kazni njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 18, 'Kakor so bila podrta Sodoma in Gomora in sosednja mesta, pravi Gospod: nihče ne bo stanoval ondi in bival ne bo v njem sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 19, 'Glej, kakor lev gre gori od veličja Jordanovega zoper trdno prebivališče; ali pri tej priči ga zapodim v beg iz te dežele, in njega, ki je izvoljen, postavim nadnjo. Kajti kdo je meni enak? ali kdo bi me pozval na sodbo? in kdo je tisti pastir, ki bi mogel stati pred menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 20, 'Zatorej čujte sklep Gospodov, ki ga je storil zoper Edoma, in misli njegove, ki jih je nameraval zoper prebivalce Temanove: Gotovo jih odvlečejo, najmanjše iz črede; gotovo se opustoši njih prebivališče ž njimi vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 21, 'Od glasu njih padca se potrese zemlja; vpitja glas se bo slišal do Rdečega morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 22, 'Glej, kakor orel pride sovražnik gori in prileti in razpne peruti svoje nad Bozro; in srce junakov Edomovih bode tisti dan kakor srce ženske, trpeče porodne bolečine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 23, 'O Damasku. Hamat je osramočen in Arpad; kajti zaslišala sta hudo poročilo, obupavata; na morju je nemir, počivati se ne more.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 24, 'Malosrčen je postal Damask, obrača se, da bi bežal, treslica ga prevzema; težava z bolečinami ga popada kakor ženo o porodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 25, '„Kako da ni zapuščeno mesto, tako hvaljeno, mesto veselja mojega?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 26, 'Zato bodo padali mladeniči njegovi po ulicah njegovih in vsi vojskovalci njegovi bodo pokončani tisti dan, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 27, 'In ogenj zažgem na zidovju v Damasku, ki pokonča Ben-hadadove gradove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 28, 'O Kedarju in o kraljestvih Hazorjevih, ki jih je porazil Nebukadnezar, kralj babilonski. Tako pravi Gospod: Vstanite, idite gori nad Kedar in pustošite otroke Jutrove dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 29, 'Njih šatore, in njih črede vzamejo; njih šatorske preproge in vse njih orodje in njih velblode odpeljejo zase; in zoper nje bodo klicali: Groza okroginokrog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 30, 'Bežite, hitro zapustite deželo, iščite globoka prebivališča, o prebivalci v Hazorju! govori Gospod; kajti Nebukadnezar, kralj babilonski, je storil sklep zoper vas in je zasnoval naklep proti vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 31, 'Vstanite, idite gori k pokojnemu narodu, ki prebiva brez skrbi, govori Gospod, ki nimajo ne vrat, ne zapaha, sami prebivajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 32, 'In njih velblodi bodo ugrabljeni in množica njih ovac uplenjena; in razkropim jih na vse vetrove, nje, ki so ostriženi ob krajih glave; in od vseh strani pripeljem njih nesrečo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 33, 'Tako bode Hazor prebivališče šakalom, puščava za vselej: nihče ne bo stanoval ondi in bival ne bo v njem sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 34, 'Beseda Gospodova, ki je prišla Jeremiju proroku zoper Elama, v začetku kraljevanja Zedekija, kralja Judovega, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 35, 'Tako pravi Gospod nad vojskami: Glej, jaz zlomim lok Elamov, vrhunec njegove moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 36, 'In pripeljem zoper Elama štiri vetrove od štirih krajev nebes in jih razkropim na vse tiste vetrove, da ne bode naroda, kamor bi ne prišel kak pregnanec iz Elama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 37, 'In preplašenega storim Elama spričo njegovih sovražnikov in spričo njih, ki jim strežejo po življenju, ter spravim nadnje nesrečo, gorečo jezo svojo, govori Gospod; in meč pošljem za njimi, dokler jih ne pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 38, 'In postavim prestol svoj v Elamu in pogubim odtam kralja in kneze, govori Gospod. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 49, 39, 'Ali zgodi se v poslednjih dneh, da pripeljem nazaj ujetnike Elamove, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 1, 'Beseda, ki jo je govoril Gospod zoper Babilon in zoper deželo Kaldejsko po Jeremiju proroku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 2, 'Oznanjajte med narodi in poročajte! Dvignite prapor, razglasite, ne prikrivajte! Recite: Babilon je vzet, Bel osramočen, Merodak potrt; v sramoti so njih podobe, potrti so njih grdi maliki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 3, 'Kajti zoper njega pride narod od severa: ta opustoši zemljo njegovo, da ne bode prebivalca v njej; zbeže, odidejo ljudje in živina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 4, 'V tistih dneh in v tistem času, govori Gospod, pridejo sinovi Izraelovi, oni s sinovi Judovimi vred; spotoma bodo venomer jokali in iskali Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 5, 'Za Sion bodo povpraševali, tja gledajoč z obličjem in govoreč: Pridite in pridružite se Gospodu z večno zavezo, ki se ne pozabi! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 6, 'Čreda izgubljenih ovac je bilo ljudstva moje; njih pastirji so jih zavajali na gore, kjer se je gojila verolomnost: hodili so z gore na hrib, pozabili so počivališče svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 7, 'Katerikoli so jih zalotili, so jih žrli, in njih zatiralci so govorili: Ne bomo krivi, zato ker so grešili zoper Gospoda, prebivališče pravičnosti, zoper Gospoda, ki je bil upanje njih očetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 8, 'Bežite izsredi Babilona in odidite iz dežele Kaldejske in bodite kakor kozli pred čredo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 9, 'Zakaj, glej, jaz obudim in pripeljem zoper Babilon zbor velikih narodov iz severne dežele, in postavijo se v bojni red zoper njega; odtod bo vzet. Njih pšice bodo kakor izurjenega junaka, ki se ne vrne z boja prazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 10, 'In Kaldejska bode v plen; vsi, ki jo plenijo, se nasitijo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 11, 'Čeprav se veselite, čeprav se radujete, o plenilci posesti moje, čeprav poskakujete kakor junica, ki vrši žito, čeprav rezgetate kakor krepki konji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 12, 'vendar se bo sramovala mati vaša silno, v sramoto pride porodnica vaša: glejte, zadnja bode med narodi, puščava, suha zemlja in samota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 13, 'Od srda Gospodovega se ne bo prebivalo v njej, ampak docela bo zapuščena. Kdorkoli pojde mimo Babilona, bo strmel in žvižgal zavoljo vseh kazni njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 14, 'Razpostavite se zoper Babilon kroginkrog vsi, ki napenjate lok! Prožite vanj strelice, ne hranite pšic! zakaj zoper Gospoda je on grešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 15, 'Ukajte zoper njega kroginkrog! Že podaja roko svojo: padle so utrdbe njegove, podrti so zidovi njegovi; ker to je maščevanje Gospodovo. Maščujte se nad njim, kakor je storil, mu storite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 16, 'Pokončajte sejalca iz Babilona in njega, ki suče srp ob žetvi! Od strahu pred zatirajočim mečem se povrnejo vsak k svojemu ljudstvu in zbeže vsak v svojo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 17, 'Ovca razkropljena je Izrael, levi so jo pregnali. Prvi jo je žrl kralj asirski in sedaj, zadnjič, ta Nebukadnezar, kralj babilonski, ji je zdrobil kosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 18, 'Zatorej pravi tako Gospod nad vojskami, Bog Izraelov: Glej, jaz bom kaznoval kralja babilonskega in deželo njegovo, kakor sem kaznoval kralja asirskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 19, 'In storim, da se vrne Izrael na pašnik svoj in se bo pasel po Karmelu in Basanu, in duša njegova se bo sitila na gorovju Efraimskem in v Gileadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 20, 'V tistih dneh in v tistem času, govori Gospod, se bo iskala krivica Izraelova, pa ne bode nobene, in grehi Judovi, a ne najde se jih nič, ker jim odpustim, katerim dam, da preostanejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 21, 'Pojdi gori zoper deželo „Dvojni upor“, prav proti njej in zoper prebivalce v „Obiskovanju“! Pustoši in docela pokončuj zadaj za njimi, govori Gospod, in delaj prav po vsem, kar sem ti ukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 22, 'Vojske hrup je v deželi in velik poboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 23, 'Kako je razsekano in zdrobljeno kladivo vse zemlje! Kako je Babilon v strmenje med narodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 24, 'Zanko sem ti nastavil, in ujel si se tudi, o Babilon, ne da bi bil zaznal; zalotili so te in zgrabili, ker si se vojskoval zoper Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 25, 'Odprl je Gospod orožnico svojo in vzel je iz nje orožje nevolje svoje; zakaj Gospod, Jehova nad vojskami, ima delo pokončevalno v deželi Kaldejski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 26, 'Zberite se nadnjo od vseh strani, odprite žitnice njene; nakopičite je kakor kupe snopja in jo docela pokončajte; naj nima nobenega ostanka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 27, 'Pomorite vse junce njene, naj gredo doli v klanje! Gorje jim! ker je prišel njih dan, čas njih obiskovanja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 28, 'Čuj! glas bežečih in uhajajočih iz dežele Babilonske, da naznanijo na Sionu maščevanje Gospoda, Boga našega, svetišča njegovega maščevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 29, 'Skličite strelce proti Babilonu, vse, ki napenjajo lok! utaborite se ob njem kroginkrog, nihče naj ne ubeži! Povrnite mu po delu njegovem, prav kakor je storil, mu storite; zakaj zoper Gospoda se je ponašal, zoper Svetega Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 30, 'Zatorej bodo popadali mladeniči njegovi po ulicah njegovih in vsi vojščaki njegovi poginejo tisti dan, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 31, 'Glej, jaz sem zoper tebe, o prevzetnež, govori Gospod, Jehova nad vojskami; zakaj tvoj dan je prišel, čas, ko te bom obiskoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 32, 'Tedaj se spotakne prevzetnež in se zgrudi, da ga nihče ne zravna; in ogenj zažgem v mestih njegovih, ki pokonča vso okolico njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 33, 'Tako pravi Gospod nad vojskami: Silo trpé sinovi Izraelovi in sinovi Judovi skupaj, in katerikoli so jih ujeli, jih trdo drže, branijo se jih izpustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 34, 'Njih odrešenik je močan, Gospod nad vojskami je ime njegovo: gotovo se potegne za njih pravdo, da upokoji deželo in vznemiri prebivalce v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 35, 'Meč nad Kaldejce, veli Gospod, in nad prebivalce v Babilonu in nad kneze njegove in modrijane njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 36, 'meč nad blebetače njegove, da poneumijo, meč nad oblastnike njegove, da obupajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 37, 'meč nad konje in vozove njegove in nad vse mešano ljudstvo, ki je sredi njega, da naj bodo kakor ženske! meč nad zaklade njegove, da se plenijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 38, 'suša nad vode njegove, da se posušé! ker to je dežela izrezanih podob in pri pošastnih malikih ravnajo brezumno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 39, 'Zato bodo tam prebivale zveri puščave z divjimi psi in noji bodo v njem gnezdili; in nikdar več se ne bo prebivalo v njem in naselitve ne bo v njem od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 40, 'Enako se podere, kakor je Bog podrl Sodomo in Gomoro in sosednja mesta njuna, govori Gospod: nihče ne bo ondi stanoval in bival ne bo v njem sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 41, 'Glej, ljudstvo pride od severa in narod velik in mnogi kralji vstanejo od skrajnega konca zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 42, 'Lok in sulico bodo držali, krvoločni bodo in brez usmiljenja; njih glas bo bučal kakor morje in na konjih bodo jahali: vsak je oborožen zoper tebe, o hči babilonska, kakor mož na vojsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 43, 'Slišal bo kralj babilonski glas o njih, in omahnejo mu roke; groza ga obide, bolečina kakor porodnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 44, 'Glej, kakor lev gre gori od veličja Jordanovega zoper trdno prebivališče; zdajci ga zapodim v beg od tod, in njega, ki je izvoljen, postavim nad to deželo. Kajti kdo je meni enak? in kdo bi me pozval na sodbo? in kdo je tisti pastir, ki bi mogel stati pred menoj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 45, 'Zatorej čujte Gospodov sklep, ki ga je sklenil zoper Babilon, in misli njegove zoper deželo Kaldejcev: Gotovo jih odvlečejo, najmanjše iz črede, gotovo se opustoši njih prebivališče ž njimi vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 50, 46, 'Od glasu: Babilon je vzet! se potrese zemlja, in vpitje se bo čulo med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 1, 'Tako pravi Gospod: Glej, obudim podirajoč veter zoper Babilon in zoper nje, ki prebivajo v njem, srcu meni se upirajočih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 2, 'In pošljem v Babilon tujce, ki ga bodo vejali in izpraznili deželo njegovo; kajti oblegali ga bodo v dan nesreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 3, 'Zoper njega, ki napenja, napenjaj strelec svoj lok in zoper njega, ki se vzdiguje v oklepu svojem; in ne imejte milosti do mladeničev njegovih, docela pokončajte vso vojsko njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 4, 'In prebodeni bodo padali v deželi Kaldejski in presunjeni po ulicah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 5, 'Kajti Izrael in Juda nista kot vdova, zapuščena od Boga svojega, od Gospoda nad vojskami; ker je njih dežela polna krivice proti Svetemu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 6, 'Bežite iz sredi Babilona in rešite vsak življenje svoje, ne bodite pokončani zavoljo krivice njegove; zakaj to je čas maščevanja Gospodovega: kar je zaslužil, mu povrača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 7, 'Zlata čaša je bil Babilon v roki Gospodovi, ki je upijanila vso zemljo; od vina njegovega so pili narodi, zato so zbesneli narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 8, 'Mahoma pade Babilon in bo potrt. Tulite nad njim, oskrbite mazilo za bolečino njegovo, če morebiti ozdravi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 9, '„Hoteli smo ozdraviti Babilon, a ni bil ozdravljen. Zapustite ga in pojdimo vsak v svojo deželo; kajti do nebes sega sodba njegova in vzdiguje se do najvišjih oblakov.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 10, 'Na dan je spravil Gospod pravičnost našo; pridite in pripovedujmo na Sionu delo Gospoda, Boga našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 11, 'Le ostrite pšice, primite za ščite! Gospod je zbudil duha kraljev medskih, ker je zoper Babilon namera njegova, da ga pogubi: zakaj to je maščevanje Gospodovo, svetišča njegovega maščevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 12, 'Na zidovju babilonskem dvignite prapor, pomnožite stražo, postavite čuvaje, pripravite zasede! Kajti kakor se je namenil Gospod, tako izvrši, kar je rekel zoper prebivalce v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 13, 'O ti, ki prebivaš poleg mnogih vodá, bogat zakladov, prišel je konec tvoj, po meri dobičkaželjnosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 14, 'Gospod nad vojskami je prisegel sam pri sebi: Čeprav sem te napolnil z ljudmi kakor s kobilicami, vendar zaženo zmagoslavno vpitje nad teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 15, 'On je ustvaril zemljo s krepostjo svojo, ustanovil vesoljni svet z modrostjo svojo in z razumnostjo svojo razpel nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 16, 'Ko se on oglaša, šum vodá na nebu vrši; on pripeljava sopare od kraja zemlje, dela bliske za dež in izpušča veter iz zakladov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 17, 'Nespameten je postal vsak, brez spoznanja; vsak zlatar se osramočuje s podobo; kajti lažniva je ulita podoba njegova in sape ni v njih nobeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 18, 'Ničemurnost so, delo, smeha vredno; tisti čas, ko bodo obiskani, poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 19, 'Njim ni podoben on, ki je Jakobov delež, kajti on je upodobil vse; in Izrael je rod posesti njegove: Gospod nad vojskami je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 20, 'Kladivo si mi, bojno orožje; in s teboj razbijem narode in s teboj pogubim kraljestva');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 21, 'in s teboj zdrobim konja z jezdecem njegovim in s teboj raztrupam voz in njega, ki sedi na njem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 22, 'in s teboj raztrupam moža in ženo in raztrupam s teboj starčka in dečka ter raztrupam s teboj mladeniča in devico');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 23, 'in s teboj razkropim pastirja in čredo njegovo in s teboj raztrupam kmetovalca z volmi njegovimi v jarmu ter razbijem s teboj deželne poglavarje in namestnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 24, 'In povrnem Babilonu in vsem prebivalcem v Kaldeji vsa njih huda dela, ki so jih storili na Sionu, pred očmi vašimi, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 25, 'Glej, jaz sem zoper tebe, o gora pogubnica, ki pogubljaš vso zemljo, govori Gospod; in iztegnem roko zoper tebe in te zvalim s skalovja in te izpremenim v goro pogorišča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 26, 'da ne dobé iz tebe kamena za vogel ali kamena za podzidje, kajti puščava bodeš vekomaj, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 27, 'Dvignite prapor v deželi, trobite na trobento med narodi, pripravite zoper njega narode, skličite proti njemu kraljestva Ararat, Mini in Askenaz! postavite zoper njega vojskovodjo, pripeljite konj gori kakor grozovitih kobilic!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 28, 'Pripravite zoper njega narode, kralje iz Medije, njene deželne poglavarje in namestnike in vso deželo njih gospostva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 29, 'In potrese se zemlja in začuti bolečine; kajti izpolnijo se misli Gospodove, da se opustoši dežela Babilonska, da nihče ne bo prebival v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 30, 'Nehajo se bojevati korenjaki v Babilonu, sedeli bodo v trdnjavah, opeša jim moč, kakor ženske bodo; sovražniki zažgo prebivališča njegova, starejo zapahe njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 31, 'Tekač bo tekel tekaču naproti in oznanjevalec srečaval oznanjevalca, naznanit kralju babilonskemu, da je mesto njegovo vzeto od kraja do konca');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 32, 'in da so celo tesni vhodi zasedeni; tudi luže so izsušili z ognjem, in vojščaki so izbegani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 33, 'Kajti tako pravi Gospod nad vojskami, Bog Izraelov: Hči babilonska je kakor gumno ob času, ko se s topotanjem utrjuje; še malo, potem ji pride žetve čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 34, 'Žrl me je, zatiral me je Nebukadnezar, kralj babilonski, naredil me je kakor prazno posodo, požiral me je kakor zmaj, napolnil si je trebuh z mojimi slaščicami, odpahnil me je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 35, 'Krivica, ki se je godila meni in mesu mojemu, pridi nad Babilon, govori naj prebivalka sionska; in kri moja pridi nad prebivalce kaldejske, govori naj Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 36, 'Zatorej pravi tako Gospod: Glej, jaz se potegnem za pravdo tvojo in izvršim maščevanje zate; in posušim morje njegovo in storim, da usahnejo studenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 37, 'In Babilon bode v kupe kamenja, prebivališče šakalov, v grozo in žvižganje brez prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 38, 'Enako kakor mladi levi rjovejo, kriče kakor levov mladiči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 39, 'Ko se ugrejejo, jim napravim pitje in jih upijanim, da se bodo razveseljevali in potem zaspali večno spanje, in ne zbude se, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 40, 'Popeljem jih kakor jagnjeta v klanje, kakor ovne s kozliči. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 41, 'Kako je vzet Šešak in zasedena vse zemlje hvala! Kako je postal Babilon predmet strmenju med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 42, 'Zoper Babilon je prišlo morje, bučeči valovi njegovi so ga pokrili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 43, 'Mesta njegova so izpremenjena v puščavo, v suho deželo in samoto, v deželo, kjer ne prebiva nihče in preko nje ne hodi sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 44, 'In kaznoval bom Bela v Babilonu, in kar je požrl, potegnem iz ust njegovih; in ne bodo se več k njemu stekali narodi; tudi zid babilonski se zruši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 45, 'Pojdite ven iz njega, ljudstvo moje, in rešite vsak dušo svojo izpred goreče jeze Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 46, 'In ne oméči se srce vaše in ne bojte se zavoljo govorice, ki se bo slišala v deželi! kajti v tem letu pride ta govorica in potem drugo leto ona govorica, in silovitost bode v deželi, vladar zoper vladarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 47, 'Zato glej, pridejo dnevi, ko bom strahoval izrezane podobe babilonske, in vsa dežela njegova bo osramočena in vsi prebodeni njegovi padejo sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 48, 'Tedaj bodo veselo pela nad Babilonom nebesa in zemlja in kar je na njih; kajti od severa pridejo k njemu razdejalci, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 49, 'Kakor je Babilon povzročil, da so padli prebodeni Izraelovi, tako padejo ob Babilonu prebodeni vse zemlje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 50, 'O vi, ki ste ubežali meču, umeknite se, ne stojte! spominjajte se iz daljave Gospoda in Jeruzalem vam pridi na misel! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 51, 'Sram nas je, ker slišimo očitanje; nečast pokriva obličje naše, ker tujci so vdrli v svetinje hiše Gospodove. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 52, 'Zato glej, pridejo dnevi, ko bom strahoval izrezane podobe njegove, in po vsej deželi njegovi bodo vpili prebodeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 53, 'Tudi ko bi se Babilon vzdignil do neba, tudi ko bi nedostopno storil višino trdnjave svoje, od mene pridejo razdejalci zoper njega, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 54, 'Čuj! vpitje od Babilona in velik poboj se sliši od dežele Kaldejcev sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 55, 'zakaj Gospod razdeva Babilon in preganja iz njega velike množice hrum; in bobne njih valovi kakor mnoge vode, razlega se šum njih glasú.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 56, 'Kajti pride zoper njega, zoper Babilon, razdejalec, ujeti bodo junaki njegovi, zdrobljeni vsi loki njegovi, zakaj Bog mogočni, ki obilo povrača, je Gospod, on gotovo povrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 57, 'In upijanim kneze njegove in modrijane njegove, deželne poglavarje in namestnike in junake njegove; in spali bodo večno spanje in se ne prebude, govori Kralj, ki mu je ime Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 58, 'Tako pravi Gospod nad vojskami: Zidovje Babilona preširoko bo docela razrušeno in visoka vrata njegova se požgo z ognjem. In tako se trudijo ljudstva za nič in narodi za ogenj, in pešajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 59, 'Beseda, ki jo je ukazal prorok Jeremija Seraju, sinu Nerija, sina Mahsejevega, ko je šel z Zedekijem, kraljem Judovim, v Babilon v četrtem letu njegovega kraljevanja; bil je pa Seraja knez posteljnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 60, 'In Jeremija je zapisal vse gorje, ki pride nad Babilon, v eno knjigo, vse te besede, ki so pisane zoper Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 61, 'In Jeremija je velel Seraju: Ko prideš v Babilon, pazi, da prečitaš vse te besede');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 62, 'in porečeš: O Gospod, ti si govoril zoper ta kraj, da ga pokončaš, tako da ne bode v njem prebivalca niti izmed ljudi niti izmed živali, temuč da bode puščava vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 63, 'Nato ko prečitaš to knjigo, ji priveži kamen in jo vrzi sredi Evfrata');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 51, 64, 'in reci: Tako se pogrezne Babilon in se ne vzdigne spričo nesreče, ki jo pripeljem zoper njega; in opešajo. Dotlej besede Jeremijeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 1, 'Zedekija je imel enoindvajset let, ko je zakraljeval, in kraljeval je enajst let v Jeruzalemu. Materi njegovi pa je bilo ime Hamutala, hči Jeremijeva iz Libne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 2, 'In delal je, kar je hudobno v očeh Gospodovih, prav tako, kakor je bil delal Jojakim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 3, 'Kajti vsled jeze Gospodove se je tako godilo Jeruzalemu in Judi, dokler jih ni zavrgel izpred obličja svojega. In Zedekija se je uprl kralju babilonskemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 4, 'Zgodi se pa v devetem letu kraljevanja njegovega, deseti dan desetega meseca, da je prišel Nebukadnezar, kralj babilonski, on in vsa vojska njegova zoper Jeruzalem, in se utabore proti njemu. In naredili so obležne ogradbe okrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 5, 'In mesto je bilo oblegano do enajstega leta kralja Zedekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 6, 'Deveti dan četrtega meseca je nastala huda lakota v mestu, in ni bilo kruha za ljudstvo dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 7, 'Tedaj je bilo mesto predrto, in vsi vojščaki so pobegnili in šli iz mesta po noči skozi vrata med dvojnim zidom, ki so bila poleg kraljevega vrta (Kaldejci pa so oblegali mesto kroginkrog), in šli so po poti proti nižini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 8, 'Ali vojska Kaldejcev se je drevila za kraljem, in dohiteli so ga na planjavah ob Jerihu; vsa vojska njegova pa se je bila razkropila od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 9, 'In ujeli so kralja in ga pripeljali gori h kralju babilonskemu, v Riblo v deželi Hamatski, in on je izrekel sodbo nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 10, 'In kralj babilonski je poklal sinove Zedekijeve njemu pred očmi, poklal je tudi vse kneze Judove v Ribli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 11, 'Nato mu je oslepil oči in ga zvezal z dvema bronastima verigama; in kralj babilonski ga je odpeljal na Babilonsko ter ga del v zapor do dne smrti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 12, 'Potem pride deseti dan petega meseca, ko je bilo devetnajsto leto kralja Nebukadnezarja, kralja babilonskega, Nebuzaradan, glavar telesne straže, ki je stal pred kraljem babilonskim, v Jeruzalem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 13, 'in požge hišo Gospodovo in hišo kraljevo in vse hiše v Jeruzalemu, namreč vsako večjo hišo požge z ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 14, 'In vsa vojska Kaldejcev, kar je je bilo pri glavarju straže, poruši vse zidove jeruzalemske okroginokrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 15, 'In nekaj nizkih ljudi in ostanek ljudstva, kar ga je ostalo v mestu in uskoke, ki so odpadli h kralju babilonskemu, in ostanek množice odpelje ujete Nebuzaradan, glavar straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 16, 'Samo iz najubožnejših ljudstva jih je pustil ondi Nebuzaradan, glavar telesne straže, da naj bodo vinogradniki in kmetovalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 17, 'In Kaldejci so razbili bronasta stebra, ki sta bila ob hiši Gospodovi, in stojala in bronasto morje, ki je bilo v hiši Gospodovi, ter odnesli ves njih bron v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 18, 'Odnesli so tudi lonce, lopate, utrinjače, čaše in torila in vse bronasto orodje, s katerim se je opravljala služba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 19, 'Tudi vrče in kadilnice in čaše, lonce, svečnike, torila in konvice, kar je bilo od zlata, v zlatu, kar od srebra, v srebru je vzel glavar telesne straže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 20, 'Tista dva stebra, eno morje in dvanajst volov pod njim in stojala, ki jih je bil napravil Salomon za hišo Gospodovo; tehtati ni bilo mogoče brona od vseh teh priprav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 21, 'Višina enega stebra je bila osemnajst komolcev in vrvica, dvanajst komolcev dolga, ga je obdajala; debel pa je bil štiri prste, votel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 22, 'In glavič na njem je bil iz brona, in višina glaviča je bila pet komolcev z mrežastim delom in granatnimi jabolki na glaviču kroginkrog, vse iz brona; in enak temu je bil drugi steber in na njem granatna jabolka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 23, 'In granatnih jabolk je bilo šestindevetdeset na vsako stran; vseh granatnih jabolk je bilo sto ob mrežastem delu kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 24, 'In glavar telesne straže je vzel Seraja, prvega duhovnika, in Zefanija, drugega duhovnika, in tri čuvaje pri vratih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 25, 'iz mesta pa je vzel enega dvornika, ki je bil postavljen nad vojščaki, in sedem mož izmed tistih, ki so bili kralju najbližji in so se našli v mestu, in pisarja, vojnega poveljnika, ki je nabiral vojsko iz deželnega ljudstva, in šestdeset mož iz deželnega ljudstva, ki so se našli v mestu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 26, 'te je vzel Nebuzaradan, glavar telesne straže, ter jih odpeljal h kralju babilonskemu v Riblo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 27, 'In kralj babilonski jih je udaril in usmrtil v Ribli, v Hamatski deželi. Tako je bil Juda preseljen v ujetništvo iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 28, 'To je ljudstvo, katero je odpeljal Nebukadnezar: v sedmem letu tri tisoč triindvajset Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 29, 'V osemnajstem letu Nebukadnezarja je odpeljal iz Jeruzalema duš osemsto trideset in dve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 30, 'V letu dvajsetem in tretjem Nebukadnezarja je Nebuzaradan, glavar telesne straže, odpeljal iz Judov duš sedemsto štirideset in pet; vseh duš štiri tisoč šest sto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 31, 'Zgodi se pa v tridesetem in sedmem letu ujetništva Jojahinovega, kralja Judovega, dvanajsti mesec, petindvajseti dan meseca, da je Evil Merodak, kralj babilonski, v letu, ko je začel kraljevati, povišal glavo Jojahina, kralja Judovega, izpeljavši ga iz ječe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 32, 'In govoril je prijazno ž njim in prestol njegov je postavil nad prestol kraljev, ki so bili ž njim v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 33, 'In premenil mu je jetniško obleko; in je jedel kruh pred kraljem vedno, vse dni življenja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (24, 52, 34, 'Kajti živež njegov, stalen živež mu je dajal kralj babilonski, odmerjen za vsak dan do smrti, vse dni njegovega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 1, 'Kako samotno je ostalo mesto, ki je bilo polno ljudstva! Vdovi je podobno – prej oblastno med narodi, kneginja med pokrajinami, sedaj plačuje davek!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 2, 'Joka in joka po noči in solze ji teko po licih; nihče je ne tolaži izmed vseh ljubiteljev njenih; vsi prijatelji njeni so se ji izneverili, postali so ji sovražniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 3, 'Juda je šel v pregnanstvo zaradi stiske in velike sužnosti: prebiva med pogani, pokoja ni našel; vsi preganjalci njegovi so ga dohiteli v tesnobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 4, 'Pota na Sion žalujejo, ker nihče ne pride na praznovanje; vsa vrata njena so zapuščena, duhovniki njeni zdihujejo; device njene so žalostne in sama je v bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 5, 'Zatiralci njeni so ji postali glava, sovražniki njeni živé mirno; kajti Gospod jo je užalil zavoljo obilosti pregreh njenih; otročiči njeni gredo v sužnost vpričo zatiralca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 6, 'In hčer sionsko je minila vsa krasota njena; njeni knezi so kakor jeleni, ki ne najdejo paše, in onemogli so odšli preganjalcu pred očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 7, 'V dneh stiske svoje in tavanja svojega se spominja Jeruzalem vseh svojih dragotin, ki jih je imel od starih dni, ker je ljudstvo njegovo padlo po roki zatiralčevi in mu nihče ni prišel na pomoč. Zatiralci ga vidijo, posmehujejo se njegovi pogubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 8, 'Hudo je grešila Jeruzalem, zato je kakor zavoljo nesnage ločena; vsi, ki so jo častili, jo zaničujejo, ker so videli nagoto njeno; tudi sama zdihuje in se ozira za seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 9, 'Nesnaga njena je na robu obleke njene; ni se spominjala konca svojega, zato je čudovito prišla na nič; nihče je ne tolaži. Ozri se, Gospod, v ponižanje moje, zakaj poveličal se je sovražnik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 10, 'Roko svojo je iztegnil zatiralec po vseh dragotinah njenih; kajti videla je, kako so šli v svetišče njeno pogani, o katerih si zapovedal, da ne smejo stopiti v zbor tvoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 11, 'Vse ljudstvo njeno zdihuje in išče kruha; svoje dragotine dajó za jed, da se požive. Ozri se, Gospod, in glej, kako me zaničujejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 12, 'Nič vam mari, vi vsi, ki greste mimo po poti? Glejte in vidite, je li bolečina enaka bolečini moji, ki so jo storili meni, ki me je Gospod napolnil z bridkostjo v dan goreče jeze svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 13, 'Z višave je poslal ogenj v kosti moje in jih je premagal; mrežo je razpel nogam mojim, pognal me je nazaj; naredil me je opustošeno in hirajočo ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 14, 'Steknila je jarem pregreh mojih roka njegova: spletene so, spenjajo se čez vrat moj – uničena je moč moja. Gospod me je dal v pesti, iz katerih se ne morem iztrgati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 15, 'Poteptal je Gospod vse junake moje sredi mene; zoper mene je sklical prazničen shod, da potare mladeniče moje. Gospod je teptal kakor v tlačilnici devico, hčer Judovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 16, 'Zato jokam, iz oči mojih teče voda navzdol, ker je daleč od mene tolažnik, ki bi mi poživil dušo; otroci moji so izgubljeni, ker je prevladal sovražnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 17, 'Roke svoje izteza hči sionska: nikogar ni, ki bi jo tolažil. Zapovedal je Gospod o Jakobu, naj ga obstopijo zatiralci njegovi; kakor ženska, zavoljo nesnage ločena, je Jeruzalem med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 18, 'Pravičen je Gospod, zato ker sem bila nepokorna ustom njegovim. Poslušajte, prosim, vsa ljudstva, in poglejte bolečino mojo! Device moje in mladeniči moji so šli v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 19, 'Klicala sem ljubitelje svoje, a oni so me obnorili; duhovniki in starejšine moji so izdehnili dušo v mestu, ko so si iskali jedi, da bi se poživili ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 20, 'Poglej, o Gospod, kajti v stiski sem, v osrčju mojem kipi bridkost, premetava se srce moje v meni, ker sem se grozno uprla. Zunaj mi mori otroke meč, doma je kakor smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 21, 'Slišali so, da zdihujem: nihče me ne tolaži; vsi sovražniki moji so slišali za nesrečo mojo, veselili so se, da si to storil. Ko pripelješ dan, ki si ga napovedal, tedaj mi bodo enaki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 1, 22, 'Pred obličje tvoje pridi vsa njih hudobnost in stóri jim, kakor si storil meni zavoljo vseh prestopkov mojih; kajti preobili so zdihljaji moji in srce moje hira silno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 1, 'Kako je pokril Gospod z gostim oblakom hčer sionsko v jezi svoji! Iz nebes na zemljo je vrgel diko Izraelovo in ni se spomnil podnožja nog svojih v jeze svoje dan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 2, 'Podrl je Gospod neusmiljeno vsa prebivališča Jakobova, v srdu svojem je porušil trdnjave hčere Judove; na tla je zvrnil, kakor oskrunjeno je zavrgel kraljestvo s knezi njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 3, 'V srditi jezi je zdrobil vsak rog Izraelov; umaknil je desnico svojo, ko je prišel sovražnik, in požgal je Jakoba kakor ogenj plameneč, ki vse požira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 4, 'Lok svoj je napel kako sovražnik, postavil se je z desnico svojo kakor nasprotnik in pomoril je vse, kar je bilo očem drago; v šatoru hčere sionske je izlil kakor ogenj togoto svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 5, 'Ravnal je Gospod kakor sovražnik: pokončal je Izraela, pokončal vse gradove njegove, razdrl vse trdnjave njegove, in mnogo je prizadel hčeri Judovi žalosti in jadikovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 6, 'In s silo je podrl kočo svojo kakor plot na vrtu, porušil je kraj shoda svojega; Gospod je storil, da se je pozabilo praznično zborovanje in sobota na Sionu, in v nevolji jeze svoje je zavrgel kralja in duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 7, 'Gospod je zavrgel oltar svoj, zastudil je svetišče svoje, v roko sovražnikovo je dal zidove njenih palač: hrumeli so v hiši Gospodovi, kakor da je prazničnega shoda dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 8, 'Gospod je sklenil razvaliti zidove hčere sionske: potegnil je mersko vrv, ni umaknil roke svoje, da bi ne pokončal; in žalovanje je pripravil nasipu in zidu, oboje žalostno leži skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 9, 'V zemljo so se pogreznila vrata njena, polomil in zdrobil je zapahe njene; kralj njen in knezi njeni so med poganskimi narodi, kjer ni postave, tudi proroki njeni ne prejemajo več prikazni od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 10, 'Na tleh sede molče starejšine hčere sionske; s pepelom so si potresli glave, prepasali se z raševnikom; na tla povešajo glavo device jeruzalemske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 11, 'Od solzá mi pešajo oči, v osrčju mi kipi bridkost, na zemljo se usipljejo jetra moja zavoljo potrtja hčere ljudstva mojega, ko otročiči in dojenci koprne po mestnih ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 12, 'Materam svojim govore: Kje je žito in vino? ko omedlevajo kakor smrtno ranjeni po ulicah mestnih, ko se njih duša izliva materam v naročje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 13, 'Kaj naj ti izpričam, kak zgled naj ti dam, o hči jeruzalemska? Kaj naj primerjam tebi, da te potolažim, o devica, hči sionska? Kajti veliko je kakor morje potrtje tvoje, kdo te more ozdraviti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 14, 'Proroki tvoji so ti videli prikazni prazne in neslane ter niso odkrivali krivičnosti tvoje, da bi bili odvrnili preselitev tvojo v sužnost; ali videli so zate praznih reči bremena [T. j. prorokovanja.] in takih, zaradi katerih si morala biti odgnana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 15, 'Z rokami ploskajo nad teboj vsi, ki gredo mimo po potu, žvižgajo in majejo z glavami proti hčeri jeruzalemski, češ: Je li to tisto mesto, katero so imenovali Dovršenost lepote, Veselje vse zemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 16, 'Zoper tebe širijo usta vsi sovražniki tvoji, žvižgajo in škripljejo z zobmi, pravijo: Požrli smo jo! res, to je tisti dan, ki smo ga pričakovali, zdaj ga imamo in vidimo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 17, 'Gospod je storil, kar je sklenil, izpolnil je govor svoj, ki ga je sporočil od starodavnih dni. Rušil je brez milosti in sovražniku je dal veseliti se nad teboj, povzdignil je rog neprijateljev tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 18, 'Srce jim vpije h Gospodu. O zid hčere sionske, stóri, da teko solze kakor reka po dnevi in po noči; ne dovoli si prestanka, ne počivaj punčica očesa tvojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 19, 'Vstani, vpij po noči, ob začetku straž, izlivaj kakor vode srce svoje pred obličjem Gospodovim, povzdiguj k njemu roke svoje za dušo otročičev svojih, ki koprne od glada po vseh ulicah in voglih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 20, 'Ozri se, o Gospod, in glej, komu delaš tako! Ali bodo žene jedle sad svoj, otročiče, ki jih nosijo v naročju? V svetišču Gospodovem ali naj moré duhovnika in proroka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 21, 'Na tleh leže po ulicah dečki in starčki; device moje in mladeniči moji so padli od meča, pomoril si jih v dan jeze svoje, poklal brez milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 2, 22, 'Sklical si kakor na dan prazničnega shoda strašila moja od vseh strani, in ni ga bilo, ki bi bil ubežal ali ostal živ v dan jeze Gospodove; nje, ki sem jih nosila v naročju in vzredila, je pokončal sovražnik moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 1, 'Jaz sem tisti mož, ki okuša bridkost po šibi togote njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 2, 'Mene vodi in goni po temi, ne pa po svetlobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 3, 'Samo meni nasprotujoč, obrača proti meni roko svojo ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 4, 'Storil je, da se je postaralo meso moje in koža moja, kosti moje je potrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 5, 'Zidal je zoper mene in me obdal s strupeno grenkobo in nadlogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 6, 'Velel mi je bivati v temnih krajih, kakor tisti, ki so mrtvi za vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 7, 'Ogradil me je, da ne morem uiti, dejal me je v težko železje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 8, 'Ko tudi kličem in vpijem, ne pusti k sebi prošnje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 9, 'Pota moja je zagradil z rezanim kamenjem, steze mi je izprevrgel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 10, 'Kakor prežeč medved mi je, kakor lev v zasedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 11, 'Pota moja je napravil tavajoča in me je raztrgal, me opustošil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 12, 'Napel je lok svoj in me je postavil pšici svoji za cilj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 13, 'V ledice moje je izpustil tula svojega strelice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 14, 'V smeh sem vsemu ljudstvu svojemu, njih pesmica ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 15, 'Nasitil me je z najhujšo bridkostjo, upijanil me je s pelinom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 16, 'In s kamenjem mi je zdrobil zobe, povalil me je v pepel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 17, 'In vržena je daleč od miru duša moja, pozabil sem, kar je sreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 18, 'In rekel sem: Izginila je moč moja in moje upanje v Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 19, 'Spomni se edinščine moje in tavanja mojega, pelina in grenkega strupa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 20, 'Spominja se tega vedno duša moja in je potrta v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 21, 'To si hočem vtisniti v srce, zato bom upal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 22, 'Prevelika dobrotljivost Gospodova je, da nismo docela pokončani, ker nima konca usmiljenje njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 23, 'novo je vsako jutro; preobila je zvestoba tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 24, 'Delež moj je Gospod, govori duša moja, zato bom upal vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 25, 'Dober je Gospod njim, ki ga čakajo, duši, ki ga išče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 26, 'Dobro je možu, da upa in tiho čaka rešitve Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 27, 'Dobro je možu, da je nosil jarem v mladosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 28, 'Samoten naj sedi in molči, ker mu ga je naložil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 29, 'V prah naj položi usta: morda je še upanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 30, 'Njemu, ki ga bije, naj pomoli lice svoje; nasiti se naj s sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 31, 'Kajti Gospod ne zameta vekomaj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 32, 'marveč, ko je užalostil, se tudi usmili po obilosti dobrot svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 33, 'Nikakor ne muči iz srca, ne žali otrok človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 34, 'Če kdo gazi vse zvezane na zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 35, 'če zavija pravico možu pred obličjem Najvišjega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 36, 'če prekanja človeka v pravdi njegovi: ne bo li Gospod pazil na to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 37, 'Kdo je, ki je velel, in se je zgodilo, če ni tega zapovedal Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 38, 'Ali ne prihaja iz ust Najvišjega hudo in dobro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 39, 'Kaj bi tožil človek, dokler živi? Vsakdo naj toži zaradi svojih grehov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 40, 'Preiskujmo ter izsledujmo pota svoja in vrnimo se do Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 41, 'Povzdignimo dušo svojo z rokami vred k Bogu mogočnemu v nebesih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 42, 'Mi, mi smo se pregrešili in se uprli; ti nisi odpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 43, 'Ogrnil si se z jezo in preganjal nas, moril si brez milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 44, 'Z oblakom si se ogrnil, da ne predere molitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 45, 'Za nesnago in izmeček si nas postavil sredi ljudstev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 46, 'Vsi sovražniki naši so usta svoja razširili zoper nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 47, 'Groza in jama sta blizu nas, razdejanje in poguba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 48, 'Potoke vodá toči oko moje zavoljo pogube hčere mojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 49, 'Oko moje se solzi in ne neha, ni nobenega prestanka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 50, 'dokler se Gospod iz nebes ne ozre in ne vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 51, 'Oko moje mi žali srce zavoljo vseh hčer mesta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 52, 'Lovili so me hudo kakor ptičico, kateri me sovražijo brez vzroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 53, 'V jamo so pehnili življenje moje, da me uničijo, in kamenje so lučali v me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 54, 'Vode so mi kipele čez glavo, dejal sem: Pokončan sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 55, 'Klical sem ime tvoje, o Gospod, iz jame pregloboke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 56, 'Glas moj si čul; ne skrivaj ušesa svojega zdihovanju mojemu, vpitju mojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 57, 'Približal si se tisti dan, ko sem klical; rekel si: Ne boj se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 58, 'Sodil si, Gospod, pravdo duše moje, odrešil si življenje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 59, 'Videl si, o Gospod, krivico, ki se mi godi; razsodi pravdo mojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 60, 'Videl si vse njih maščevanje in vse njih naklepe zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 61, 'Slišal si njih zasramovanje, o Gospod, in vse njih namere zoper mene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 62, 'govorjenje tistih, ki so vstali nadme, in njih izmišljevanje zoper mene ves dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 63, 'Glej jih, ko sede in ko vstajajo, da jim sem za pesmico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 64, 'Plačaj jim povračilo, Gospod, po njih rok delu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 65, 'Daj jim zaslepljenost srca, prokletje tvoje pridi nadnje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 3, 66, 'Preganjaj jih v jezi in zatri jih izpod nebes Gospodovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 1, 'Kako je otemnelo zlato, se izpremenilo odlično zlato! Kako je raztreseno kamenje svetišča po vseh voglih in ulicah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 2, 'Sinovi Siona, predragi, ki bi jih bilo ceniti z zlatom najčistejšim, kako se čislajo za vrče prstene, za izdelek rok lončarjevih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 3, 'Celo šakali ponujajo prsi, dojé mladiče svoje, ali ljudstva mojega hči je neusmiljena kakor noji v puščavi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 4, 'Jezik lepí dojenčku na nebesu od žeje; otročiči prosijo kruha, a ni ga, da bi ga delil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 5, 'Oni, ki so jedli slaščice, premirajo po ulicah; oni, ki so bili vzrejeni v škrlatu, objemajo blato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 6, 'In hujša je krivda ljudstva mojega hčere nego krivda Sodome, ki je bila podrta nagloma, roke se niso utrudile ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 7, 'Čistejši nego sneg so bili knezi njeni, bolj beli nego mleko, bolj rdeči po životu nego korale, gladki kakor safir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 8, 'Temnejša od črnine je sedaj njih podoba, ne poznajo jih na ulicah; njih koža se je zrasla ž njih kostmi, suha je kakor les.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 9, 'Bolje je pomorjenim z mečem nego pomorjenim z lakoto, ker ti umirajo prebodeni s stradanjem, ker ni poljskega sadú.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 10, 'Roke žen usmiljenih so kuhale otroke svoje, za hrano so jim bili ob razdejanju hčere ljudstva mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 11, 'Gospod je dopolnil togoto svojo, srdito jezo svojo je izlil in ogenj zažgal na Sionu, ki je požrl podstave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 12, 'Ne bi bili verjeli kralji zemeljski in vsi prebivalci vesoljnega sveta, da pride zatiralec in sovražnik v vrata jeruzalemska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 13, 'Zgodilo se je zavoljo grehov prorokov njegovih, krivic duhovnikov njegovih, ki so prelivali sredi njega kri pravičnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 14, 'Kakor slepci so tavali po ulicah, ognušeni so bili s krvjo, da se niso hoteli ljudje dotekniti njih oblačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 15, '„Umeknite se, nečisti!“so vpili proti njim, „umeknite se, umeknite, ne doteknite se!“Ko so bežali, so tudi tavali, in med narodi se je govorilo: Ne smejo več pri nas prebivati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 16, 'Srdito obličje Gospodovo jih je razkropilo, ne bo jih gledal več. Na duhovnike se niso ozirali, starčkom niso prizanašali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 17, 'Še nam oči hirajo v hrepenenju po prazni pomoči; z ogledovalnice svoje gledamo proti narodu, ki ne bo rešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 18, 'Lové stopinje naše, da ne moremo hoditi po ulicah svojih. Bliža se konec naš, dovršujejo se dnevi naši, da, konec naš je že prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 19, 'Hitrejši so bili naši preganjalci nego orli pod nebom: po gorah so nas podili, v puščavi so nas zalezovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 20, 'Dih življenja našega, maziljenec Gospodov, je bil ujet v njih jamah; o katerem smo rekli: V senci njegovi bomo živeli med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 21, 'Veséli in raduj se, o hči Edomova, prebivalka v deželi Uzovi! Tudi k tebi pride čaša, upijaniš se in slečeš se do nagega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 4, 22, 'Končana je kazen krivde tvoje, o hči sionska! ne bo te več vodil v pregnanstvo. Ozre se v krivico tvojo, o hči Edomova, odkrije grehe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 1, 'Spomni se, o Gospod, kaj nas je zadelo, ozri se in poglej sramoto našo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 2, 'Dediščina naša je pripadla tujcem, hiše naše inozemcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 3, 'Sirote smo, brez očeta, matere naše so kakor vdove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 4, 'Vode svoje pijemo za denar, drva svoja dobivamo za plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 5, 'Preganjalci naši nam stopajo na vrat; utrujeni smo, ne dovolijo nam pokoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 6, 'Egipčanu molimo roko, tudi Asircu, da se nasitimo kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 7, 'Očetje naši so grešili, in ni jih več; nam pa je nositi njih krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 8, 'Hlapci nam gospodujejo; nikogar ni, ki bi nas oprostil iz njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 9, 'Z nevarnostjo življenja svojega prinašamo kruh svoj spričo meča puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 10, 'Koža naša je začrnela kakor peč zavoljo vroče lakote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 11, 'Žene na Sionu so oskrunjali, device po mestih Judovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 12, 'Poglavarje obešajo njih roke, starčkov obličje se ne časti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 13, 'Mladeniči nosijo mlinske kamene in dečki padajo pod lesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 14, 'Starci so nehali shajati se med vrati, mladeniči na petje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 15, 'Minilo je srca našega veselje, v žalost se je preobrnil naš ples.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 16, 'Venec naše glave je padel. Gorje nam! ker smo grešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 17, 'Zato omedleva srce naše, zavoljo tega so nam otemnele oči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 18, 'zavoljo gore Sionske, ki je opustošena; lisice prosto hodijo po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 19, 'Ti, Gospod, ostaneš vekomaj, prestol tvoj od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 20, 'Zakaj nas vekomaj pozabljaš, hočeš li nas zapustiti za dolge čase?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 21, 'Pelji nas nazaj k sebi, o Gospod, da se povrnemo; ponovi dni naše kakor v prejšnjih časih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (25, 5, 22, 'Ali bi nas popolnoma zavrgel, razsrdil se zoper nas tako silno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 1, 'In zgodi se v tridesetem letu, peti dan četrtega meseca, ko sem bil med odpeljanci v sužnost pri reki Kebarju, da so se odprla nebesa, in videl sem prikazni Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 2, 'Peti dan meseca, ko je bilo peto leto ujetništva kralja Jojahina,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 3, 'je prišla beseda Gospodova izrečno do Ezekiela duhovnika, sina Buzijevega, v deželi Kaldejcev pri reki Kebarju, in tam je bila roka Gospodova nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 4, 'In videl sem, in glej: vihar privrši od severa, velik oblak in med njim ogenj, neprestano švigajoč, in svetloba okoli njega; in izsredi njega se je svetilo kakor lice kovine, izsredi ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 5, 'In izsredi njega se je kazala podoba štirih živih stvari, in bile so videti kakor človekova podoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 6, 'In vsaka je imela štiri obraze in vsaka štiri perutnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 7, 'Njih noge so bile ravne noge in stopala njih nog so bila kakor telečja stopala, in iskrile so se kakor likan bron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 8, 'In pod perutnicami so imele človečje roke na štirih svojih straneh; in vse štiri so imele svoje obraze in svoje perutnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 9, 'Njih perutnice so bile združene druga z drugo; niso se obračale, kadar so hodile: vsaka je šla naravnost predse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 10, 'In podoba njih obrazov je bila: spredaj človečje obličje, in na desni so imele vse štiri obraz leva in na levi obraz vola, in orlov obraz so imele zadaj vse štiri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 11, 'Njih obličja pa in njih perutnice so bile zgoraj razdeljene; dve peruti vsake sta se stikali in dve sta pokrivali telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 12, 'In šle so vsaka naravnost predse; kamor je hotel iti duh, so šle; niso se obračale, kadar so šle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 13, 'In podoba četverih živih stvari: videti jih je bilo kakor živo žerjavico, kakor plamenice. Ogenj je švigal semtertja med četverimi živimi stvarmi, in ogenj je bil presvetel in iz ognja so švigali bliski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 14, 'In tiste žive stvari so letale semtertja kakor blisk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 15, 'Ko sem pa gledal tiste žive stvari, glej: kolo na zemlji poleg živih stvari, ob njih štirih sprednjih straneh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 16, 'Kolesa in njih delo je bilo videti kakor lice hrizolita, in vsa štiri so imela enako podobo, in njih podoba in njih delo je bilo, kakor da bi bilo kolo v kolesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 17, 'Kadar so šla, so šla na svoje štiri strani; niso se obračala, ko so šla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 18, 'Njih platišča so bila visoka in strašna, in platišča so bila polna oči kroginkrog na vseh štirih kolesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 19, 'In ko so žive stvari hodile, so hodila kolesa zraven njih, in ko so se žive stvari vzdignile od zemlje, so se vzdignila kolesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 20, 'Kamorkoli je bilo iti duhu, so šle, tja, kamor je hotel iti duh, in kolesa so se vzdignila vzporedno ž njimi, zakaj duh žive stvari je bil v kolesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 21, 'Kadar so šle, so šla tudi ona, in kadar so stale, so stala ona, kadar so se pa vzdignile nad zemljo, so se vzdignila kolesa vzporedno ž njimi, zakaj duh žive stvari je bil v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 22, 'In nad glavami živih stvari se je razpenjalo liki nebesno raztežje, katerega lice je bilo kakor čudovitega kristala, razprostrto zgoraj nad njih glavami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 23, 'In pod raztežjem so bile njih perutnice naravnost urejene druga proti drugi; vsaka je imela dve ob tej strani in dve ob oni strani, ki sta pokrivali nje život.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 24, 'In ko so šle, sem slišal šum njih perutnic kakor šumenje velikih vodá, kakor glas Vsemogočnega, šum vrenja kakor hrup vojske. Ko so stale, so pobešale perutnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 25, 'In bilo je grmenje zgoraj nad raztežjem, ki se je razpenjalo nad njih glavami. Ko so stale, so pobešale perutnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 26, 'In vrhu raztežja, ki se je razpenjalo nad njih glavami, je bila podoba prestola, ki je bil videti kakor kamen safir; in na podobi prestola je bila podoba liki človekova, zgoraj na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 27, 'In videl sem kakor lice svetle kovine, ki se je zdelo kakor ogenj znotraj njega kroginkrog; od njegovega ledja gori in od njegovega ledja doli sem videl kakor podobo ognja, in svetloba je bila okoli njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 1, 28, 'Kakor se vidi mavrica, ki je na oblakih v dan dežja, taka se je videla svetloba okoli. To je bila prikazen podobe slave Gospodove. In ko sem to videl, padem na obraz in začujem glas govorečega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 1, 'In veli mi: Sin človečji, postavi se pokonci, in govoril bom s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 2, 'In ko me je ogovoril, pride duh v mene in me postavi pokonci; in čul sem glas, ki mi je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 3, 'In mi reče: Sin človečji, jaz te pošiljam k sinovom Izraelovim, k narodom upornežem, ki so se uprli meni; oni in njih očetje so odpadli od mene prav do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 4, 'In ti sinovi so brezsramnega obličja in trdega srca; k njim te pošiljam, in reci jim: „Tako pravi Gospod Jehova!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 5, 'Oni pa, najsi poslušajo ali ne poslušajo (kajti uporna so družina), vendar bodo vedeli, da je bil prorok med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 6, 'Ti pa, sin človečji, ne boj se jih in ne prestraši se njih besed, čeprav so res koprive in trnje okoli tebe in prebivaš med škorpijoni. Ne boj se njih besed in ne ustraši se njih obličja, kajti uporna so družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 7, 'In govóri jim besede moje, najsi poslušajo ali ne, kajti uporneži so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 8, 'Ali ti, sin človečji, poslušaj, kar ti govorim; ne bodi uporen kakor tista uporna družina: odpri usta in jej, kar ti dam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 9, 'In videl sem, in glej: roka iztegnjena proti meni, in glej, v njej je zvitek knjige.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 2, 10, 'In razgane jo pred menoj, in bila je popisana spredaj in zadaj, in bilo je pisano v njej žalovanje in zdihovanje in gorje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 1, 'In mi veli: Sin človečji, jej, kar najdeš; jej ta zvitek in pojdi, govóri hiši Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 2, 'In odprem usta, in on mi da jesti tisti zvitek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 3, 'In mi reče: Sin človečji, nasiti si trebuh in napolni život svoj s tem zvitkom, ki ti ga dajem. In použil sem ga, in bil je v ustih mojih sladek kakor med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 4, 'Nato mi veli: Sin človečji, pojdi k Izraelovi hiši in govori jim z mojimi besedami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 5, 'Zakaj nisi poslan k ljudstvu globokega govora in neznanega jezika, temuč k hiši Izraelovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 6, 'ne k mnogim ljudstvom globokega govora in neznanega jezika, katerih besede ne moreš umeti. Res, ko bi te k takim poslal, bi te radi poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 7, 'Ali hiša Izraelova te ne bo hotela poslušati, ker nočejo mene poslušati; zakaj vsa hiša Izraelova je trdega čela in otrplega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 8, 'Glej, jaz sem naredil obličje tvoje trdo proti njih obličju in čelo tvoje trdo proti njih čelu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 9, 'kakor demant, trše od skale sem naredil čelo tvoje. Ne boj se jih in ne ustraši se njih obličja, kajti uporna so družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 10, 'Še mi veli: Sin človečji, vse besede moje, ki ti jih bom govoril, sprejmi v srce svoje in poslušaj z ušesi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 11, 'Vstani pa idi k odpeljanim v sužnost, k svojega ljudstva otrokom, pa jim govori in jim reci: „Tako pravi Gospod Jehova!“najsi poslušajo ali pa ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 12, 'Tedaj me je vzdignil duh, in slišal sem za seboj glas velikega grmenja, govoreč: „Hvaljena bodi slava Gospodova s svojega mesta!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 13, 'in šumenje perutnic živih stvari, ki so se dotikale druga druge, in ropot koles vzporedno ž njimi in glas velikega grmenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 14, 'In duh me je vzdignil in odnesel, in šel sem v bridkosti, v gorečnosti duha svojega in roka Gospodova je bila mogočna nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 15, 'In prišel sem v Telabib k preseljenim v sužnost, bivajočim pri reki Kebarju, in ondi, kjer so oni sedeli, sem sedel strmeč sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 16, 'In zgodi se ob koncu sedmih dni, da mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 17, 'Sin človečji, za čuvaja sem te postavil hiši Izraelovi, da bi jih, čujoč besedo iz mojih ust, svaril v mojem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 18, 'Ako rečem brezbožniku: Gotovo umreš! A ti ga ne posvariš in ne govoriš, da odvrneš brezbožnika s krivične poti njegove, da ga ohraniš v življenju; umre ta brezbožnik v krivici svoji, ali kri njegovo bom zahteval iz tvojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 19, 'Toda če posvariš brezbožnika, on pa se ne preobrne od svoje brezbožnosti in od krivične poti svoje: umre v krivici svoji, ali ti si otel dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 20, 'In ko se odvrne pravični od pravičnosti svoje in bo delal krivico in mu nastavim spotikljaj: umre; ako ga nisi posvaril, umre v grehu svojem in pravičnih del njegovih, ki jih je storil, se ne bo spominjalo, toda kri njegovo bom zahteval iz tvojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 21, 'Ako pa posvariš pravičnega, da bi ne grešil, pa ne bo grešil, gotovo bo živel, ker se je dal posvariti; ti pa si otel dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 22, 'In roka Gospodova je bil tam nad menoj, in mi veli: Vstani, pojdi v nižavo, in tam bom govoril s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 23, 'Vstanem torej in odidem v nižavo. In glej, ondi je stala slava Gospodova, enaka slavi, ki sem jo videl pri reki Kebarju. In padem na obraz svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 24, 'A duh pride v me in me postavi pokonci. In govori z menoj in mi reče: Pojdi, zakleni se v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 25, 'In ti, sin človečji, glej: vrvi denejo nate in te zvežejo ž njimi, da ne boš mogel iti ven mednje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 26, 'In storim, da se ti jezik prilepi k nebesu, da onemiš in jim ne boš svarilec; kajti uporna so družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 3, 27, 'Ali ko bom govoril s teboj, odprem usta tvoja, in porečeš jim: Tako pravi Gospod Jehova: Kdor hoče poslušati, poslušaj, kdor pa noče, naj ne posluša; kajti uporna so družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 1, 'Ti pa, sin človečji, si vzemi opeko, jo položi predse in zariši na njej mesto, Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 2, 'In napravi oblego proti njemu in postavi obležne utrdbe zoper njega in zgradi obzidje okoli njega, in zasadi zidolome zoper njega kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 3, 'In vzemi zase železno ponev in jo postavi kot železen zid med seboj in mestom; in vpri obličje svoje vanj, da bodi obleženo in da ga ti oblegaš. To bodi znamenje hiši Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 4, 'Dalje lezi na svojo levo stran in deni nanjo krivico hiše Izraelove: kolikor dni boš ležal na njej, boš nosil njih krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 5, 'Zakaj jaz sem ti premenil leta njih krivice v število dni: tristo in devetdeset dni; in tako boš nosil hiše Izraelove krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 6, 'In potem, ko jih dopolniš, lezi na desno stran svojo in nosi krivico hiše Judove štirideset dni; dan sem ti določil za leto, dan, pravim, za leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 7, 'In vpri obličje z odkrito ramo svojo proti oblegi Jeruzalema in prorokuj zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 8, 'In glej, jaz denem vrvi nate, da se ne boš mogel obrniti s strani na stran, dokler nisi dopolnil dni obleganja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 9, 'Tudi si vzemi pšenice in ječmena in boba in leče in prosa in pirjevice ter deni to v eno posodo in si pripravi iz te zmesi toliko hlebov, kolikor dni boš ležal na svoji strani: tristo in devetdeset dni boš jedel to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 10, 'In tvoja jed, ki jo boš užival, bodi odtehtana, po dvajset seklov na dan; od roka do roka jo boš jedel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 11, 'Tudi vodo boš pil na mero, šesti del hina; od roka do roka jo boš pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 12, 'In jedel jih boš kakor ječmenove kolače in pekel pred njih očmi s človeškim blatom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 13, 'In Gospod je rekel: Tako bodo morali sinovi Izraelovi jesti nečisti kruh svoj med poganskimi narodi, kamor jih razženem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 14, 'Jaz pa sem rekel: Ah, Gospod Jehova! Glej, duša moja ni nikdar bila ognušena, kajti od mladosti svoje pa do zdaj nisem jedel mrline ali od zveri raztrganega in nikoli ni prišlo nečisto meso v usta moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 15, 'Tedaj mi reče: Glej, dovolim ti govejaka namesto človeškega blata, da na njem pripraviš kruh svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 16, 'Še mi reče: Sin človečji, glej, jaz potarem podporo kruha v Jeruzalemu – jedli bodo kruh na tehto in v skrbi in vodo pili na mero in strmeč –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 4, 17, 'zato da bi jim zmanjkalo kruha in vode in da bi strmo gledali drug ob drugem in ginili v krivici svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 1, 'Ti pa, sin človečji, vzemi si oster meč, da ti rabi kakor britev, in obrij si glavo in brado; potem si vzemi tehtnico ter razdeli lase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 2, 'Tretjino jih sežgi z ognjem sredi mesta, ko bodo dopolnjeni dnevi obleganja; tretjino jih pa vzemi in razmahaj z mečem okoli mesta; in tretjino jih raztresi po vetru, in jaz izderem meč za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 3, 'In prav malo jih vzemi ter jih zaveži v rob svojega plašča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 4, 'Pa teh vzemi še nekaj in jih vrzi v ogenj in jih sežgi v ognju: odtod plane ogenj proti vsej Izraelovi hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 5, 'Tako pravi Gospod Jehova: To je Jeruzalem; postavil sem ga sredi med poganske narode in dežele okoli njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 6, 'A uprl se je mojim sodbam, ravnajoč brezbožno bolj nego pogani, in mojim postavam bolj nego dežele, ki so okoli njega; kajti sodbe moje so zavrgli in po postavah mojih niso živeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 7, 'Zatorej pravi tako Gospod Jehova: Ker ste divjali bolj nego poganski narodi okoli vas in niste živeli po zapovedih mojih in niste izpolnjevali sodb mojih, pa še po pravicah narodov, ki so okoli vas, niste delali –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 8, 'zato pravi Gospod Jehova takole: Glej, jaz, tudi jaz bodem zoper tebe in izvršim sodbe sredi tebe pred očmi tistih narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 9, 'In hočem v tebi storiti, česar še nisem storil in nikdar več ne bom storil, zavoljo vseh gnusob tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 10, 'Zato bodo sredi tebe očetje jedli otroke in otroci bodo jedli očete, in izvršim sodbo v tebi in ves tvoj ostanek raztresem na vse vetrove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 11, 'Zategadelj, kakor res živim, govori Gospod Jehova, ker si oskrunil svetinjo mojo z vsemi ostudami svojimi in z vsemi gnusobami svojimi, zato te tudi jaz obrijem, in oko moje ne zanese; tudi jaz se ne usmilim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 12, 'Tretji del tebe umrje za kugo in z lakoto bo pokončan sredi tebe; in tretji del pade pod mečem povsod okoli tebe, in tretji del raztresem na vse vetrove in izderem meč za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 13, 'Tako se dopolni jeza moja, in pomirim togoto svojo nad njimi in se potolažim; in spoznajo, da sem jaz, Gospod govoril v gorečnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 14, 'In storim te v pustinjo in v zasmeh med narodi, ki so okoli tebe, pred očmi vseh, ki gredo mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 15, 'In bodeš v zasmeh in zasramovanje, v svarilo in strmenje narodom, ki so okoli tebe, ko bom nad teboj vršil sodbe v srdu in togoti in v jeznem svarjenju. Jaz, Gospod, sem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 16, 'Kadar bom vanje streljal hude pšice lakote, ki bodo v pogubo, ki jih pošljem pogubit vas, tedaj pomnožim lakoto nad vami in starem vašo podporo kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 5, 17, 'In pošljem nad vas lakoto in najhujše zveri, da vam ugonobe otroke; tudi kuga in kri pojdeta skozi tebe, in meč prinesem nadte. Jaz, Gospod, sem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 1, 'In prišla mi je beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 2, 'Sin človečji, obrni obličje na gore Izraelove in prorokuj zoper nje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 3, 'in reci: Gore Izraelove, poslušajte besedo Gospoda Jehove! Tako pravi Gospod Jehova goram in hribom, rupam in dolinam: Glejte, jaz pripeljem meč nad vas in pokončam višave vaše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 4, 'in vaši oltarji se razrušijo in solnčni stebri vaši bodo strti. In storim, da bodo popadali prebodenci vaši pred grdimi maliki vašimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 5, 'in vržem trupla sinov Izraelovih pred grde njih malike in raztrosim kosti vaše okoli vaših oltarjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 6, 'Kjerkoli prebivate, bodo mesta razdejana in višave opustošene, da se razrušijo oltarji vaši ter opustošijo in uničijo grdi maliki vaši in da se posekajo solnčni stebri vaši in iztrebijo stvarine vaše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 7, 'in prebodenci bodo padali sredi vas. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 8, 'Vendar vam pustim ostanek, tako da boste med narodi imeli nekatere, ki ubeže meču, ko boste razkropljeni po deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 9, 'In tisti ubežniki vaši se bodo spominjali mene med narodi, kamor jih ujete odpeljejo, kadar potarem njih nečistosti vdano srce, ki je odstopilo od mene, in njih oči, ki so nečisto za njih maliki gledale; in sami sebi se bodo studili zavoljo hudobnosti, ki so jih zakrivili ob vseh gnusobah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 10, 'Tedaj bodo vedeli, da sem jaz Gospod. Nisem zaman govoril, da jim hočem storiti to zlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 11, 'Tako pravi Gospod Jehova: Ploskni z roko in ob tla udari z nogo in reci: Gorje zaradi vseh hudih gnusob hiše Izraelove; zakaj popadati morajo po meču, lakoti in kugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 12, 'Kdor je daleč, umre za kugo, in kdor je blizu, pade pod mečem, kdor pa preostane in bo obvarovan, umre lakote: tako dopolnim togoto svojo nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 13, 'In spoznate, da sem jaz Gospod, ko bodo njih prebodenci ležali med njih maliki, okoli njih oltarjev, na vsakem hribu visokem in na vseh vrhovih gora in pod vsakim zelenim drevesom in pod vsakim košatim hrastom, na tistih krajih, kjer so vsem grdim malikom svojim prinašali prijetne dišave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 6, 14, 'In iztegnem roko zoper nje in storim njih deželo pusto in opustošeno bolj nego je puščava Diblat, kjerkoli prebivajo. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 1, 'Še mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 2, 'In ti, sin človečji, tako pravi Gospod Jehova zemlji Izraelovi: Konec! konec prihaja nad štiri kraje dežele!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 3, 'Zdaj prihaja konec tebi, ker pošljem jezo svojo nadte in te bom sodil, kakor zaslužiš, in spravim vse gnusobe tvoje nadte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 4, 'In oko moje ti ne prizanese in ne usmilim se, temuč ti dam, kakor si zaslužila, in gnusobe tvoje spravim nadte. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 5, 'Tako pravi Gospod Jehova: Nesreča, edina nesreča, glej, prihaja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 6, 'Konec gre, konec prihaja, zbudil se je zoper tebe; glej, prihaja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 7, 'Usoda tvoja prihaja nadte, o prebivalec dežele! Čas je prišel, dan je blizu, dan hrupne zmešnjave, a ne radostnega vriskanja na gorah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 8, 'Zdaj, zdaj izlijem togoto svojo nadte in dopolnim jezo svojo zoper tebe, in sodil te bom, kakor si zaslužil, in spravim nadte vse gnusobe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 9, 'In oko moje ne bo prizanašalo in ne usmilim se: kakor so bile tvoje poti, tako ti poplačam, in gnusobe tvoje pripravim nadte. In spoznate, da sem jaz Gospod, ki tepem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 10, 'Glej, tisti dan, glej, prihaja! Usoda tvoja je nastopila, šiba cvete, prevzetnost zeleni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 11, 'silovitost se vzdiguje do šibe brezbožnosti. Ničesar od njih ne ostane, ničesar od njih množice, ničesar od njih bogastva, in nič krasnega ne bo na njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 12, 'Čas je prišel, dan se bliža! Kupec se ne veséli in prodajalec ne žaluj: zakaj srd leti nad vso njih množico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 13, 'Kajti prodajalec ne dobi nazaj, kar je prodano, tudi ako bi še živeli; zakaj prikazen se tiče vse njih množice, nihče se ne povrne, tudi nihče ne utrdi življenja svojega po krivičnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 14, 'Trobijo s trombo in vse pripravljajo, a nihče ne gre v boj; kajti srd moj leti nad vso njih množico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 15, 'Meč je zunaj, kuga pa in lakota notri: kdor je na polju umre od meča, in kateri so v mestu, jih požreta lakota in kuga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 16, 'In ubežniki, če se izmed njih rešijo, bodo na gorah enaki golobom v dolinah, vsi žalostno gruleč, vsak zaradi krivice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 17, 'Vsem obnemorejo roke in vsa kolena se razlijejo kakor voda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 18, 'In opasovali se bodo z raševnikom, in groza jih obide in rdečica oblije vse obraze in glave jim oplešijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 19, 'Srebro svoje pomečejo na ulice in njih zlato se bo štelo za nesnago. Njih srebro in zlato jih ne bo moglo oteti v dan jeze Gospodove; gladu si ne utešé ž njim in života si ne napolnijo: kajti bilo jim je v spotiko, da pomnože krivdo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 20, 'Svoje dragotine so obračali v napuh in grde podobe in ostude svoje so delali iz njih: zato sem jim jih storil v nesnago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 21, 'In dam jih v roko tujcem za plen in brezbožnim v deželi za rop, in jih ognusijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 22, 'Odvrnem tudi obličje svoje od njih, in oskrunijo skriti zaklad moj; in razbojniki vdero vanj in ga oskrunijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 23, 'Naredi verigo! Kajti dežela je polna krvavih zločinov in mesto je polno silovitosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 24, 'Zato pripeljem najhujše izmed narodov, da posedejo njih hiše; naredim tudi konec prevzetnosti mogočnikov, in njih svetišča bodo oskrunjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 25, 'Poguba prihaja, in iskali bodo miru, a ga ne bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 26, 'Nesreča za nesrečo pride in žalostna novica za novico; in povpraševali bodo o prikazni pri prorokih, ali postava izgine duhovniku in svet starejšinam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 7, 27, 'Kralj bo žaloval in knez se bo oblačil v grozo, in roke ljudstva v deželi se bodo tresle. Storil jim bom, kakor so živeli, in jih sodil, kakor so zaslužili. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 1, 'In zgodilo se je v šestem letu, peti dan šestega meseca, ko sem sedel v hiši svoji in starejšine Judovi so sedeli pred menoj, da je tam name prišla roka Gospoda Jehove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 2, 'In videl sem, in glej: podoba, ki se je videla kakor ogenj; od njenega ledja doli ogenj in od njenega ledja gori se je videlo kakor blišč, kakor lice svetle kovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 3, 'In je iztegnil kakor roko in me prijel za lase moje glave, in duh me je vzdignil med zemljo in nebo, in nesel me je v prikaznih Božjih v Jeruzalem, k vhodu notranjih vrat, ki gledajo proti severu, kjer je bila postavljena podoba ljubosumnosti, ki vnema gorečnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 4, 'In glej, slava Boga Izraelovega je bila tam, enaka prikazni, ki sem jo videl v dolini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 5, 'In mi veli: Sin človečji, obrni zdaj oči proti polnoči! Povzdignem torej oči proti polnoči, in glej, severno ob vratih oltarjevih je bila tista podoba ljubosumnosti, pri vhodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 6, 'In mi reče: Sin človečji, vidiš li, kaj delajo? te velike gnusobe, ki jih počenja hiša Izraelova tukaj, da me odženo daleč od svetišča mojega? Ali še druge velike gnusobe boš videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 7, 'In pripelje me k vhodu do dvorišča, in ko pogledam, glej, luknja je v zidu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 8, 'Tedaj mi veli: Sin človečji, prederi zid! In prederem zid in vidim duri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 9, 'In mi reče: Vstopi in poglej prehudobne gnusobe, ki jih tu delajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 10, 'In stopim noter in vidim, in glej: mnogotere podobe grde laznine in zverjadi in vsi ostudni maliki hiše Izraelove, naslikani kroginkrog po steni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 11, 'In sedemdeset mož iz starejšin hiše Izraelove je stalo pred podobami in sredi njih Jaazanija, sin Safanov, vsak držeč kadilnico v roki, in duh kadilnega oblaka se je dvigal kvišku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 12, 'In mi reče: Sin človečji, ali si videl, kaj počenjajo starejšine Izraelovi v temi, vsak v hramu podob svojih? kajti pravijo: Gospod nas ne vidi, Gospod je zapustil deželo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 13, 'Pa mi reče: Videl boš še druge velike gnusobe, ki jih počenjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 14, 'Nato me pripelje k vhodu v vrata hiše Gospodove, ki so proti severu; in glej, tam sede žene, ki jočejo nad bogom Tamuzom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 15, 'In mi reče: Si li to videl, sin človečji? Videl boš še druge večje gnusobe nego te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 16, 'In pripelje me na notranje dvorišče hiše Gospodove, in glej, pri vhodu v svetišče Gospodovo, med vežo in oltarjem, je petindvajset mož, s hrbtom obrnjenih proti svetišču Gospodovemu in z obrazom proti jutru; in klanjajo se solncu proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 17, 'Tedaj mi reče: Si li to videl, sin človečji? Je li malo hiši Judovi, da počenjajo gnusobe, ki jih delajo tukaj? da še polnijo zemljo s silovitostjo in me venomer dražijo? In glej, vejice držé pod nos.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 8, 18, 'Zato bom tudi jaz ravnal v togoti: oko moje ne bo prizanašalo in ne usmilim se; in čeprav mi bodo z velikim glasom vpili na ušesa, jih vendar ne uslišim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 1, 'In vpil mi je na ušesa z glasom velikim govoreč: Bližajte se, ki vam je kaznovati mesto, vsak s svojo morilno pripravo v roki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 2, 'In glej, šest mož pride po poti od zgornjih vrat, ki so obrnjena proti severu, vsak s svojo rušilno pripravo v roki, in eden sredi njih v platnenem oblačilu s pisarsko pripravo ob strani. In vstopijo in se postavijo pri bronastem oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 3, 'Slava Boga Izraelovega pa se je vzdignila od keruba, nad katerim je bila, proti hišnemu pragu. In zakliče možu v platnenem oblačilu, ki je imel pisarsko pripravo ob strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 4, 'In Gospod mu veli: Pojdi posredi mesta, posredi Jeruzalema in začrkaj znamenje na čela ljudem, ki zdihujejo in žalujejo nad vsemi gnusobami, ki se v nje godé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 5, 'Drugim pa reče, da sem slišal: Idite po mestu za njim in pobijajte; oko vaše ne prizanesi in ne usmilite se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 6, 'Pomorite jih do zadnjega starce, mladeniče in device, otročiče in žene, a ne približajte se nikomur, ki ima znamenje na sebi; začnite pa pri mojem svetišču. Začno torej pri starih možeh, ki so bili pred hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 7, 'In jim veli: Omadežite hišo in napolnite dvorišča s pomorjenimi; potem pojdite ven! In šli so ven in pobijali po mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 8, 'In zgodi se, ko so pobijali, in jaz sem ostal sam, da padem na obličje in zavpijem in rečem: Ah, Gospod Jehova! hočeš li pokončati ves ostanek Izraelov, ko izlivaš srd svoj nad Jeruzalem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 9, 'Pa mi reče: Krivda hiše Izraelove in Judove je silno velika, in dežela je polna krvi in v mestu vlada spačevanje pravice; kajti pravijo: Gospod je zapustil deželo in Gospod ne vidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 10, 'Tako tudi jaz: moje oko ne prizanese in ne usmilim se, ampak spravim jim njih ravnanje na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 9, 11, 'In glej, mož v platnenem oblačilu, ki je imel pisalno pripravo ob strani, prinese sporočilo, rekoč: Storil sem, kakor si mi zapovedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 1, 'In videl sem, in glej, na nebesnem raztežju, ki se je razpenjalo nad glavami kerubimov, se je prikazalo kakor safirov kamen in se je videlo kakor podoba prestola, kažočega se nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 2, 'In ogovori moža v platnenem oblačilu in veli: Stopi noter med vrteča se kolesa pod kerubom in napolni si prgišča z živo žerjavico izmed kerubimov in jo raztresi čez mesto. In stopil je tja vpričo mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 3, 'Kerubimi pa so stali na desni strani hiše, ko je šel mož noter, in oblak je polnil notranje dvorišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 4, 'In slava Gospodova se je povznesla iznad keruba in je stala nad hišnim pragom; in hiša se je napolnila z oblakom in dvorišče je bilo polno sijaja slave Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 5, 'In šumenje perutnic kerubimov se je slišalo prav do zunanjega dvora kakor glas Boga silnega, Vsegamogočnega, kadar govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 6, 'In ko je zapovedal možu v platnenem oblačilu, rekoč: Vzemi ognja izmed vrtečih se koles, izmed kerubimov! šel je mož noter in stopil zraven kolesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 7, 'In kerub iztegne roko izmed kerubimov k ognju, ki je bil med kerubimi, in vzame od njega ter da v roke tistemu, ki je bil v platno oblečen; ta pa vzame in gre ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 8, 'In prikazala se je na kerubimih podoba človeške roke, pod njih perutnicami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 9, 'In videl sem, in glej: štiri kolesa poleg kerubimov, po eno kolo pri vsakem kerubu. Podoba koles pa je bila videti kakor lice kamena hrizolita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 10, 'Po videzu so imela vsa štiri eno podobo, kakor da bi bilo kolo sredi kolesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 11, 'Kadar so šli, so šli na svoje štiri strani; niso se obračali, kadar so šli, temuč proti mestu, kamor je bila obrnjena glava, so šli za njo; niso se obračali, kadar so šli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 12, 'In ves njih život in njih hrbet in njih roke in njih perutnice, tudi kolesa, vse je bilo polno oči kroginkrog; vsi štirje so imeli svoja kolesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 13, 'In tista kolesa so bila imenovana, da sem slišal: vrteča se kolesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 14, 'In vsako je imelo štiri obličja: obličje prvo je bilo obličje kerubovo in obličje drugo človekovo, tretje obličje pa levovo in četrto orlovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 15, 'In kerubimi so se vznašali. Bili so tiste žive stvari, katere sem bil videl pri reki Kebarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 16, 'In kadar so hodili kerubimi, so šla kolesa poleg njih; kadar pa so kerubimi peruti razprostrli, da se povzpno od zemlje, se tudi kolesa niso odmikala od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 17, 'Ko so se ustavili, so tudi obstala, in ko so se povzpeli, so se vzdignila ž njimi vred, zakaj duh žive stvari je bil v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 18, 'In slava Gospodova je odšla iznad hišnega praga in se je ustopila nad kerubimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 19, 'In kerubimi so razpostrli peruti in se vzdignili kvišku od zemlje vpričo mene, in ž njimi, gredočimi ven, so vzporedno šla kolesa. In ustopili so se ob vhodu v vzhodna vrata hiše Gospodove, in slava Boga Izraelovega je bila zgoraj nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 20, 'To je bila živa stvar, katero sem videl pod Bogom Izraelovim pri reki Kebarju; in spoznal sem, da so bili kerubimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 21, 'Vsak je imel štiri obličja in vsak štiri perutnice, in podoba rok človeških je bila pod njih perutnicami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 10, 22, 'Kar se pa tiče sličnosti njih obrazov, so bila ista obličja, ki sem jih videl pri reki Kebarju, enaka so se videla in enaka so bila. Vsak je hodil naravnost predse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 1, 'In duh me je vzdignil in me prenesel k vzhodnim vratom hiše Gospodove, ki so obrnjena proti vzhodu. In glej, ob vhodu v vrata je bilo petindvajset mož; in videl sem sredi njih Jaazanija, sina Azurjevega, in Pelatija, sina Benajevega, kneza ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 2, 'In mi je rekel: Sin človečji, to so tisti možje, ki izmišljajo krivico in sklepajo hudobne svete v tem mestu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 3, 'ki govore: Ni blizu čas, da bi zidali hiše; to mesto je lonec, mi pa meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 4, 'Zatorej prorokuj zoper nje, prorokuj, sin človečji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 5, 'In duh Gospodov pride nadme in mi veli: Reci: Tako pravi Gospod: Tako ste govorili, o hiša Izraelova; kajti jaz vem, kar preudarjate v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 6, 'Vi ste pomnožili prebodence svoje v tem mestu in ulice njegove ste napolnili s prebodenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 7, 'Zato pravi tako Gospod Jehova: Prebodenci vaši, ki ste jih ob tla pometali sredi mesta, oni so meso, to mesto pa je lonec; vas pa odpeljejo ven iz njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 8, 'Meča ste se bali, in meč pripeljem nad vas, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 9, 'In peljal vas bom iz mesta in vas dal v roke tujcem, in izvršim sodbe nad vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 10, 'Od meča boste padali: ob meji Izraelovi vas bom sodil. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 11, 'To mesto vam ne bo lonec, tudi vi ne boste meso sredi njega: ob meji Izraelovi vas bom sodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 12, 'In spoznate, da sem jaz Gospod, po čigar postavah niste živeli in čigar ustanovil niste izpolnjevali, temuč ravnali ste po naredbah poganskih narodov, ki so okoli vas. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 13, 'In zgodilo se je, ko sem prorokoval, da je umrl Pelatija, sin Benajev. Tedaj padem na obraz in zavpijem z močnim glasom in rečem: Ah, Gospod Jehova! hočeš li docela pokončati ostanek Izraelov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 14, 'In beseda Gospodova pride do mene, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 15, 'Sin človečji, tvoji bratje, tvoji bratje, tvojega sorodništva možje in vsa družina Izraelova, vsi sploh so tisti, katerim so govorili prebivalci v Jeruzalemu: Ostanite daleč od Gospoda! nam je ta dežela dana v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 16, 'Zato reci: Tako pravi Gospod Jehova: Čeprav sem jih daleč pregnal med narode in čeprav sem jih razkropil po deželah, jim vendar hočem biti majhno svetišče po deželah, kamor so prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 17, 'Zato reci: Tako pravi Gospod Jehova: Res, zberem vas izmed ljudstev in skupim vas iz dežel, v katere ste se razkropili, in dam vam zemljo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 18, 'In ko pridejo vanjo, odpravijo iz nje vse ostude njene in vse gnusobe njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 19, 'In dam jim eno srce in dodelim novega duha v njih osrčje, in vzamem kameneno srce iz njih telesa in jim dam meseno srce:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 20, 'da bi živeli po mojih postavah in sodbe moje izpolnjevali in po njih ravnali. In bodo mi ljudstvo in jaz jim bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 21, 'Tistim pa, katerih srce živi po mislih njih grdob in gnusob, tistim spravim njih dejanje nad glavo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 22, 'Tedaj so vzdignili kerubimi peruti in kolesa so šla vzporedno ž njimi; in slava Boga Izraelovega je bila zgoraj nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 23, 'In slava Gospodova se je vzdignila iznad sredi mesta in se je ustavila na gori, ki je proti jutru pred mestom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 24, 'In duh me vzdigne kvišku in me prenese v prikazni po duhu Božjem k ujetnikom v Kaldejo. In prikazen, ki sem jo videl, izgine gori pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 11, 25, 'In govoril sem ujetnikom besede Gospodove, ki mi jih je bil pokazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 1, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 2, 'Sin človečji, prebivaš sredi uporne družine: imajo oči, da bi videli, a ne vidijo, ušesa, da bi slišali, a ne slišijo, ker so uporna družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 3, 'Zato si ti, sin človečji, pripravi reči za selitev, in seli se po dnevi pred njih očmi. In preseliš se z mesta svojega v drugi kraj, njim pred očmi: morebiti spoznajo, da so uporna družina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 4, 'In po dnevi pred njih očmi iznosi svoje reči kakor za selitev; sam pa odrini zvečer vpričo njih, kakor odidejo ljudje v pregnanstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 5, 'Pred njih očmi si prederi steno in skozi njo jih iznosi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 6, 'njim pred očmi jih zadeni na ramo in odnesi v temi; obraz si zagrni, da ne vidiš zemlje; zakaj v zgledno znamenje sem te postavil hiši Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 7, 'In storil sem, kakor mi je bilo ukazano. Reči svoje sem odnesel kakor za selitev po dnevi in zvečer sem predrl steno z roko svojo; iznosil sem jih v temi in jih na ramo zadeval pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 8, 'In zjutraj mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 9, 'Sin človečji, ni li ti rekla družina Izraelova, tista uporna družina: Kaj delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 10, 'Reci jim: Tako pravi Gospod Jehova: To breme se tiče kneza v Jeruzalemu in vse hiše Izraelcev, ki so sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 11, 'Reci: Jaz sem vam v zgledno znamenje. Kakor sem storil, tako se bo godilo ž njimi: pojdejo v pregnanstvo, v ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 12, 'In knez, ki je med njimi, ponese svoje reči na rami v črni temi in pojde strani; predrli bodo steno, da spravijo ven prtljago; on si zagrne obraz, da ne bo videl zemlje z očmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 13, 'In vržem mrežo nanj in ga ujamem v lovnico svojo; in storim, da pride v Babilon, v zemljo Kaldejcev, ali ne bo je videl, dasi umrje ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 14, 'In vse, ki so okoli njega, njegove pomočnike in vsa krdela njegova razkropim na vse vetrove in meč potegnem za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 15, 'In spoznajo, da sem jaz Gospod, kadar jih razkropim med narode in raztresem po deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 16, 'Ali pridržim malo mož izmed njih, ki ostanejo po meču, po lakoti in po kugi, da naj pripovedujejo vse gnusobe svoje med narodi, kamor pridejo. In vedeli bodo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 17, 'In pride mi beseda Gospodova in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 18, 'Sin človečji, jej kruh z drgetom in pij vodo s trepetom in strahom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 19, 'In reci ljudstvu dežele: Tako pravi Gospod Jehova o prebivalcih v Jeruzalemu in o deželi Izraelovi: Jedli bodo kruh s strahom in vodo pili strmeč, ker opustoši se njih dežela in izprazni svoje obilosti zaradi zlobnosti vseh prebivalcev svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 20, 'In mesta, ki v njih mnogi prebivajo, bodo razdejana, in dežela bode pustinja. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 21, 'Še mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 22, 'Sin človečji, kaj pomeni ta pregovor, ki ga imate v deželi Izraelovi, ko pravite: Dnevi se na dolgo vlečejo in vsaka prikazen pride v nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 23, 'Povej jim torej: Tako pravi Gospod Jehova: Konec storim temu pregovoru, in ne sme se več rabiti v rek v Izraelu. In povej jim tudi: Blizu so dnevi in izpolnitev vsake prikazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 24, 'Kajti ne bode več ničeve prikazni in laskavega vedeževanja v hiši Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 25, 'Zakaj jaz, Gospod, govorim; beseda, ki jo govorim, se mora zgoditi, ne bo se več zavlačevala. Kajti v vaših dneh, o družina uporna, izgovorim besedo in jo tudi izpolnim, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 26, 'Zopet mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 27, 'Sin človečji, glej, hiša Izraelova govori: Prikazen, ki jo ta vidi, velja za mnogo dni, in prorokuje za čase, ki so še daleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 12, 28, 'Zatorej jim reci: Tako pravi Gospod Jehova: Nobena mojih besed se ne bo zavlačevala več, temuč beseda, ki jo izgovorim, se mora zgoditi, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 1, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 2, 'Sin človečji, prorokuj zoper proroke Izraelove, ki prorokujejo, in reci njim, ki prorokujejo iz lastnega srca svojega: Čujte besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 3, 'Tako pravi Gospod Jehova: Gorje brezpametnim prorokom, ki gredo za lastnim duhom svojim in za tistim, česar niso videli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 4, 'Kakor lisice v razvalinah so bili tvoji proroki, o Izrael!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 5, 'Niste stopali pred razpoke zidov in niste gradili obzidja pri hiši Izraelovi, da bi trdno stala v boju na dan Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 6, 'Ničevost in lažnivo vedeževanje so videli, kateri pravijo: „ Gospod govori!“dasi jih ni poslal Gospod; in tolažijo jih z nado, da se njih beseda potrdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 7, 'Niste li videli ničeve prikazni in niste li govorili lažnivega vedeževanja, ko ste pravili: „ Gospod govori!“in vendar jaz nisem govoril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 8, 'Zato pravi tako Gospod Jehova: Ker ste govorili ničemurnost in videli laž, zato, glejte, sem jaz zoper vas, govori Gospod Jehova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 9, 'in roka moja bode zoper proroke, ki vidijo ničemurnost in ki pripovedujejo laž. Ne bodo v svetovalstvu ljudstva mojega in v popisu družine Izraelove ne bodo zapisani, tudi v zemljo Izraelovo ne pridejo. In spoznate, da sem jaz Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 10, 'Zato, prav zato, ker zapeljujejo ljudstvo moje, govoreč: Mir! In ga ni miru; in če kdo gradi steno, jo mažejo z belilom –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 11, 'reci tistim mazačem z belilom, da bo padla; ploha se ulije nanjo in toča bo padala in vihar jo razdere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 12, 'Glejte, ko pade stena, ali vam ne bodo pravili: Kje je belilo, s katerim ste jo mazali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 13, 'Zato pravi tako Gospod Jehova: V togoti svoji naredim, da jo razdere hrumeč vihar, in vsled srda mojega se ulije nanjo ploha in usuje toča od jeze moje v pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 14, 'Tako razvalim steno, ki ste jo mazali z belilom, in porušim jo do tal, da se odkrije njena podlaga; in padla bo in vi poginete sredi nje. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 15, 'In tako dopolnim togoto svojo nad steno in nad njimi, ko so jo mazali z belilom, in vam porečem: Stene ni več, tudi tistih ni, ki so jo mazali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 16, 'prorokov Izraelovih, ki prorokujejo o Jeruzalemu in vidijo zanj prikazni miru, dasi ni miru, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 17, 'Ti pa, sin človečji, obrni obličje proti hčeram ljudstva svojega, ki prorokujejo iz lastnega srca svojega, in prorokuj zoper nje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 18, 'in reci: Tako pravi Gospod Jehova: Gorje jim, ki šivajo obveze za vse členke rok in obglavne zavoje, prilične vsaki postavi, da bi lovile duše! Hočete li uloviti duše pri ljudstvu mojem, a svoje duše ohraniti v življenju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 19, 'In mene ste onečastile med ljudstvom mojim za peščico ječmena in za nekoliko grižljajev kruha, da se v smrt pripravijo duše, ki bi ne imele umreti, in pri življenju ohranijo duše, ki bi ne imele živeti, s tem, da lažete ljudstvu mojemu, ki posluša laži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 20, 'Zato pravi tako Gospod Jehova: Glejte, jaz sem zoper obveze vaše, s katerimi lovite duše kakor ptice, in jih vam iztrgam iz rok, duše pa pustim v prostost, duše, ki jih lovite kakor ptice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 21, 'Tudi obglavne zavoje vaše raztrgam in otmem ljudstvo svoje iz vaše roke, da vam ne bodo več za plen v pesti vaši. In zvedele boste, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 22, 'Ker ste z lažmi užalostile srce pravičnega, ki mu jaz nisem žalosti prizadel, in krepčale ste roke brezbožnega, da se ne bi vrnil s hudobne poti svoje, da se ohrani v življenju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 13, 23, 'zato ne boste več videle ničemurnosti in se več ne pečale z vedeževanjem; in otmem ljudstvo svoje iz roke vaše. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 1, 'In pridejo k meni možje izmed starejšin Izraelovih ter sedejo pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 2, 'Tedaj mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 3, 'Sin človečji, ti možje so si vzeli grde malike svoje v srce in predse postavili spotiko za svojo krivico: ali naj jim odgovorim, ko me vprašajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 4, 'Zato jih ogovori in jim reci: Tako pravi Gospod Jehova: Vsak mož iz hiše Izraelove, ki si jemlje grde malike svoje v srce in si stavi spotiko za krivico svojo pred obličje, pa prihaja k proroku: jaz Gospod mu odgovorim primerno, po množini grdih malikov njegovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 5, 'da ujamem hišo Izraelovo za njih srce, ker so se mi vsi vkup odtujili po grdih malikih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 6, 'Zato reci hiši Izraelovi: Tako pravi Gospod Jehova: Vrnite se in opustite grde malike svoje in odvrnite obraze od vseh gnusob svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 7, 'Zakaj vsakdo iz hiše Izraelove in izmed tujcev, ki bivajo v Izraelu, ki se loči od mene, da ne bi šel za menoj, in si v srce jemlje grde malike svoje in stavi predse spotiko za krivico svojo ter prihaja k proroku mene vpraševat zase: jaz Gospod mu odgovorim po svojem načinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 8, 'In obrnem obličje svoje zoper tistega moža in ga naredim v stvar strmenju, za znamenje in pregovor in ga iztrebim iz ljudstva svojega. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 9, 'Ako se pa prorok da premotiti in govori besedo, jaz Gospod sem premotil tistega proroka, in iztegnem roko zoper njega in ga pokončam izmed ljudstva svojega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 10, 'In nosila bosta krivico svojo: krivica prorokova bode kakor krivica tistega, ki ga povprašuje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 11, 'da ne bi več blodila hiša Izraelova od mene, tudi da bi se več ne onečiščevali z vsemi pregrehami svojimi; in bodo mi v ljudstvo in jaz jim bodem Bog, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 12, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 13, 'Ko se dežela pregreši zoper mene s tem, da se mi izneveri, in iztegnem roko svojo zoper njo in ji starem podporo kruha in pošljem lakoto nadnjo in zatarem v njej človeka in živino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 14, 'pa bi bili ti trije možje v njej, Noe, Daniel in Job: oni bi po pravičnosti svoji oteli samo svoje duše, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 15, 'Ko pripeljem hude zveri v deželo, da ji pogube prebivalce, da postane pustinja in nihče ne bo hodil skozi njo zavoljo zveri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 16, 'pa bi bili ti trije možje v njej, res, kakor živim, govori Gospod Jehova: oni ne otmo ne sinov, ne hčeri; sami bodo oteti, a dežela bode pustinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 17, 'Ali če pripeljem meč nad tisto deželo in velim: Meč, pojdi skozi deželo! in tako zatarem v njej človeka in živino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 18, 'pa bi bili ti trije možje v njej, res, kakor živim, govori Gospod Jehova, oni ne otmo ne sinov, ne hčeri, toda sami bodo oteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 19, 'Ali če pošljem kugo v tisto deželo in izlijem togoto svojo nadnjo v krvi, da zatarem v njej človeka in živino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 20, 'pa bi bili v njej Noe, Daniel in Job, res, kakor živim, govori Gospod Jehova: ne otmo ne sinov, ne hčeri, oteli bodo samo svoje duše po pravičnosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 21, 'Toda tako pravi Gospod Jehova: Ko pošljem nad Jeruzalem svoje štiri sodbe: meč, lakoto, hude zveri in kugo, da zatarem v njem ljudi in živino,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 22, 'vendar, glej, v njem ostanejo ohranjenci, sinovi in hčere, katere popeljejo ven; glej, pridejo k vam ven, in videli boste njih življenje in njih dejanja; in potolaženi boste zastran nesreče, ki sem jo pripeljal nad Jeruzalem, zastran vsega, kar sem pripeljal nadenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 14, 23, 'In bodo vas tolažili, ko boste videli njih življenje in njih dejanje; in spoznate, da nisem brez vzroka storil vsega, karkoli sem storil v njem, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 1, 'In beseda Gospodova mi pride, govore:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 2, 'Sin človečji, je li les vinske trte boljši mimo drugega lesa, mladika, ki je med gozdnimi drevesi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 3, 'Vzamejo li lesa od nje, da ga porabijo pri kaki pripravi? ali pa vzamejo klin od nje, da bi nanj obesili kako orodje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 4, 'Glej, v ogenj ga vržejo, da zgori. Ko je ogenj sežgal obadva konca in sredino njegovo prežgal, je li še čemu v prid?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 5, 'Glej, ko je bil nepoškodovan, se ni mogel porabiti za nobeno pripravo: koliko manj je pripraven za kaj, ko ga je ogenj sežgal in prežgal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 6, 'Zato pravi tako Gospod Jehova: Kakor sem dal les vinske trte med gozdnimi drevesi ognju, da ga sežge, tako dam prebivalce jeruzalemske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 7, 'in obrnem obličje svoje zoper nje: ven pojdejo iz ognja, a ogenj jih požre. In spoznate, da sem jaz Gospod, ko obrnem obličje svoje zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 15, 8, 'Deželo pa naredim v pustinjo, zato ker so zakrivili nezvestobo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 1, 'Zopet mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 2, 'Sin človečji, oznani Jeruzalemu gnusobe njegove');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 3, 'in reci: Tako pravi Gospod Jehova Jeruzalemu: Izvir tvoj in rojstvo tvoje je iz dežele Kanaancev; oče tvoj je bil Amorejec, mati tvoja pa Hetejka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 4, 'In kar se tiče rojstva tvojega – v dan, ko si bila rojena, ti ni bil popek odrezan, tudi nisi bila z vodo umita, da bi bila očiščena, niti s soljo nisi bila odrgnjena, ne v plenice povita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 5, 'Nobeno oko se ni milosrčno ozrlo nate, da ti stori teh reči eno, da se ti izkaže usmiljenje; bila si pa na polje vržena, ker jim je mrzelo življenje tvoje, v dan rojstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 6, 'Tedaj sem šel mimo tebe in, videč te, da se valjaš v krvi svoji, sem ti rekel: Čeprav si v krvi svoji, žívi! res, rekel sem ti: v krvi svoji žívi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 7, 'V desettisoči, kakor rastline na polju, sem te naredil, in vzrasla si in postala velika in dospela do dražestne milobe: prsi so se ti napele in lasje ti zrasli; ali naga si bila in gola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 8, 'Ko sem pa šel mimo tebe in te pogledal, glej, čas tvoj je bil čas ljubezni; tedaj sem čezte pregrnil krilo svoje in zakril goloto tvojo; in prisegel sem ti ter zavezo storil s teboj, govori Gospod Jehova, in postala si moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 9, 'Nato sem te umil z vodo in te opral tvoje krvi in te pomazilil z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 10, 'In oblekel sem te s pisanim oblačilom in ti obul tjulenje kože in te opasal s tenčico in ogrnil s svilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 11, 'in olepotil sem te z lepotičjem: zapestnice sem ti del na roke in verižico na grlo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 12, 'in vtaknil sem ti obroček v nos in uhane v ušesa in ti položil krasen venec na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 13, 'In tako si bila olepšana z zlatom in srebrom, in obleka tvoja je bila iz tenčice, svile in pisane tkanine; jedla si belo moko in med in olje. In bila si silno lepa ter si dosegla kraljestva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 14, 'In tvoje ime je zaslovelo med narodi zaradi lepote tvoje, ker je bila dovršena po veličastju mojem, s katerim sem te obdal, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 15, 'Ali ti si se zanesla na lepoto svojo in si se vdala nečistovanju vsled slovečega imena svojega, trosila si nečistosti svoje na vsakega mimogredočega: lahko je užival lepote tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 16, 'In vzela si od svojih oblačil in sebi napravila pisane višave in na njih nečistovala – kaj takega se več ne primeri in ne zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 17, 'Vzela si tudi krasne dragotine svoje iz mojega zlata in iz mojega srebra, ki sem ti jih bil dal, in naredila si sebi moških podob in nečistovala ž njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 18, 'in s pisanimi oblačili svojimi si jih pregrinjala in moje olje in kadilo si prednje polagala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 19, 'Tudi kruh moj, ki sem ti ga dal, belo moko in olje in med, s katerim sem te hranil, si polagala prednje v prijetno dišavo. To se je godilo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 20, 'Vrhutega si jemala sinove in hčere svoje, ki si jih rodila meni, in jih darovala njim v žrtje. Je li majhna reč nečistovanje tvoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 21, 'da si morila otroke moje ter jih izročala, naj gredo njim v čast skozi ogenj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 22, 'In pri vseh gnusobah svojih in nečistovanju svojem se nisi spominjala dni mladosti svoje, kako si bila naga in gola in si se valjala v krvi svoji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 23, 'In zgodilo se je po vsej hudobnosti tvoji (gorje, gorje ti! govori Gospod Jehova),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 24, 'da si si zgradila hram in naredila vzvišen kraj v vsaki ulici;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 25, 'ob vsakem razpotju si zgradila vzvišen kraj svoj, in skrunila si lepoto svojo in svoje noge razvirala vsem, ki so mimo šli, in množila si nečistovanje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 26, 'Nečistovala si tudi z Egipčani, sosedi svojimi velikih udov, in si množila nečistovanje svoje, da bi me dražila v jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 27, 'In glej, iztegnil sem roko svojo zoper tebe in zmanjšal določeni ti živež in te izročil volji sovražilk tvojih, hčer filistejskih, ki jih je bilo sram nesramnega počenjanja tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 28, 'Vdala si se nečistovanju tudi z Asirci, ker se nisi mogla nasititi, in nečistovala si ž njimi, pa še nisi bila sita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 29, 'Potem si pomnožila nečistovanje svoje proti deželi tržnikov, proti Kaldeji, a še tega nisi bila sita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 30, 'Kako ti omedleva srce, govori Gospod Jehova, ko vse to počenjaš, delo razuzdane nečistnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 31, 'da si gradiš hram ob vsakem razpotju in vzvišen kraj svoj v vsaki ulici. In nisi bila kakor navadna nečistnica, ker si zaničevala plačilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 32, 'tudi ne kakor žena prešeštnica, ki namesto svojega moža sprejema druge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 33, 'Vsem nečistnicam dajó darila, ali ti si dajala darila vsem ljubovnikom svojim in si jih podkupovala, da bi od vseh strani prihajali k tebi nečistovat s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 34, 'In bilo je pri tebi naopak kakor pri drugih ženskah, da niso hodili za teboj nečistovat: zakaj sama si dajala plačilo, tebi pa niso dajali plačila, bilo je torej s teboj naopak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 35, 'Zato čuj, nečistnica, besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 36, 'Tako pravi Gospod Jehova: Ker se je razlila nesramnost tvoja in je nagota tvoja bila odkrita v nečistovanju tvojem z ljubovniki tvojimi in zaradi vseh pregnusobnih malikov tvojih in za kri otrok tvojih, ki si jih jim dala:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 37, 'zato, glej, zberem vse ljubovnike tvoje, ki si jim bila prijetna, in vse, ki si jih ljubila, z vsemi, ki si jih sovražila, zberem jih od vseh strani zoper tebe in odgrnem pred njimi nagoto tvojo, da bi videli vso nagoto tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 38, 'In sodil te bom, kakor so sojene žene, ki kršijo zakon in moré otroke, in pustim te izkrvaveti v srdu in gorečnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 39, 'In izročim te v njih pest, da podero hrame tvoje in porušijo vzvišene kraje tvoje ter strgajo s tebe oblačilo in pobero krasne dragotine tvoje in te puste nago in razodeto ležati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 40, 'In pripeljejo gori nadte zbor sovražnikov in te s kamenjem posujejo in razsekajo z meči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 41, 'In požgó hiše tvoje z ognjem ter store sodbo nad teboj pred očmi mnogih žen. In tako storim, da nehaš nečistovati in plačila tudi ne boš več dajala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 42, 'In s tem pomirim togoto svojo nad teboj in gorečnost moja se umakne od tebe, in bodem miren in se ne bom več jezil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 43, 'Ker se nisi spominjala dni mladosti svoje, temuč si me dražila z vsem tem, zato, glej, sem ti spravil tvoje dejanje na glavo, govori Gospod Jehova, da ne bi več počenjala te nesramnosti poleg vseh gnusob svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 44, 'Glej, sleherni, kdor rabi pregovore, obrne ta pregovor nate, govoreč: Kakršna mati, taka njena hči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 45, 'Ti si matere svoje hči, ki je odpahnila moža svojega in otroke svoje, in sestra si svojih sester, ki so se iznebile mož in otrok svojih. Mati vaša je bila Hetejka in oče vaš Amorejec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 46, 'Starejša sestra tvoja pa je Samarija s hčerami svojimi, ki prebiva tebi na levici; in mlajša sestra, ki prebiva tebi na desno, je Sodoma s hčerami svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 47, 'Toda nisi hodila po njih potih, ne delala po njih gnusobah; ali kakor da bi to bilo malo, si bolj popačeno ravnala na vseh svojih potih nego one.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 48, 'Resnično, kakor živim, govori Gospod Jehova: Sodoma, sestra tvoja, ona in hčere njene niso delale kakor ti s svojimi hčerami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 49, 'Glej, to je bila pregreha sestre tvoje Sodome: v prevzetnosti, v vsem obilju in brezskrbnem pokoju je živela s hčerami svojimi, roke pa ubogim in potrebnim ni pokrepčala;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 50, 'a prevzetovale so in počenjale gnusobe pred mojimi očmi. Zato sem jih odpravil, ko sem bil to videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 51, 'Samarija tudi polovice tvojih grehov ni zagrešila; ti si pomnožila gnusobe svoje bolj nego onidve in si pravičnejši izkazala sestri svoji po vseh gnusobah, kar si jih zakrivila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 52, 'Zatorej nosi tudi ti sramoto svojo, ki si jo prisodila svojima sestrama; po tvojih grehih, ki si jih gnusneje počenjala nego onidve, sta oni pravičnejši od tebe. Torej bodi tudi ti osramočena in nosi sramoto svojo, ker si pravičnejši izkazala sestri svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 53, 'Hočem pa nazaj pripeljati njiju ujetništvo, ujetnike Sodome in njenih hčera in ujetnike Samarije in njenih hčera, pa tudi tvoje ujetnike med njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 54, 'da naj nosiš sramoto svojo in se sramuješ vsega, kar si storila, ko jima bodeš v tolažbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 55, 'In tvoji sestri, Sodoma in hčere njene, tudi Samarija in hčere njene se povrnejo v prejšnji stan svoj, pa tudi ti in hčere tvoje se povrnete v prejšnji stan svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 56, 'Kajti o Sodomi, sestri tvoji, ni bilo slišati iz ust tvojih v dan prevzetovanja tvojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 57, 'preden je bila razodeta hudobnost tvoja, kakor ob času, ko so te zasmehovale hčere sirske in vse, ki so okoli nje, hčere filistejske, ki so te zaničevale kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 58, 'Nesramnost svojo in gnusobe svoje, ti jih boš nosila, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 59, 'Kajti tako pravi Gospod Jehova: Prav tako bom s teboj delal, kakor si ti delala, ki si v nič dejala prisego, prelomivši zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 60, 'Vendar se bom spominjal zaveze svoje s teboj v dneh mladosti tvoje in ti ustanovim zavezo večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 61, 'Tedaj se boš spominjala potov svojih in se sramovala, ko prejmeš k sebi sestri svoji, starejši od tebe, z mlajšimi vred, ko ti jih dam za hčere, ali ne na podlagi zaveze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 62, 'In ustanovim s teboj zavezo svojo, in spoznaš, da sem jaz Gospod:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 16, 63, 'da bi se spominjala in sramovala in nikdar ne odprla ust svojih zaradi sramote svoje, ko ti odpustim vse, kar si storila, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 1, 'In beseda Gospodova mi pride, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 2, 'Sin človečji, zastavi uganko in govóri priliko hiši Izraelovi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 3, 'in reci: Tako pravi Gospod Jehova: Velik orel z velikimi perutnicami in dolgimi letalnimi peresi, poln pisanega perja, je priletel na Libanon in odtrgal vrh cedrovega drevesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 4, 'Najgorenjo vejico je odtrgal in jo odnesel v deželo tržnikov in jo postavil v mestu kupčevalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 5, 'In vzame semena dežele ter ga vseje na žitno njivo; nesel ga je k obilim vodam, gojil ga je kakor vrbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 6, 'In vzraslo je in postalo bohotna vinska trta nizke rasti, da so se njene veje obračale proti orlu in korenine njene bile pod njim; tako je postala vinska trta in poganjala mladike in raztezala grebenice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 7, 'Bil je pa drug velik orel z velikimi perutnicami in obilim perjem. In glej, ta vinska trta je od gredic svojega sadišča krivo iztezala korenine svoje žejno do njega in razgibala svoje veje proti njemu, da bi jo namakal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 8, 'Na dobri njivi, pri obilnih vodah je bila zasajena, da bi poganjala mladike in rodila sad, da postane slavna vinska trta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 9, 'Reci: Tako pravi Gospod Jehova: Bo li imela srečo? Ne izruje li oni korenin njenih in odreže njenega sadu, da usahne? Vse njeno mlado listje, ki ga je pognala, se posuši; in ne bode treba velike moči in mnogega ljudstva, da jo vzdignejo od korenin njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 10, 'In glej, čeprav zasajena, bo li imela srečo? Se li ne posuši docela, kakor hitro se je dotakne vzhodni veter? Usahne na gredicah, na katerih raste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 11, 'Še mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 12, 'Govóri vendar tisti uporni družini: Ne veste li, kaj to pomeni? Reci: Glejte, kralj babilonski je prišel v Jeruzalem in je vzel kralja in kneze v njem ter jih odpeljal k sebi v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 13, 'In vzel je enega od kraljevega semena in ž njim sklenil zavezo in ga zaprisegel; mogočnike v deželi pa je vzel s seboj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 14, 'da bodi kraljestvo ponižno, da bi se ne povzdignilo, temuč da bi, držeč zavezo svojo, obstalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 15, 'Ali on se mu je uprl; poslal je sporočnike svoje v Egipt, da naj mu dado konj in dosti ljudstva. Bo li imel srečo? ubeži li, ko je to storil? Prelomil je zavezo, pa bi ubežal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 16, 'Kakor res živim, govori Gospod Jehova: v kraju, kjer prebiva kralj, ki ga je postavil za kralja, pa mu je prisego v nič dejal in zavezo ž njim prelomil, pri njem umre v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 17, 'In nič ne opravi Faraon zanj z veliko vojsko in z veliko množico v boju, ko bodo nanašali nasipe in zidali obležne utrdbe, da iztrebijo mnogo duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 18, 'Ker je v nič dejal prisego, prelomivši zavezo, – in glej, v roko je bil nanjo segel, in vendar je storil vse to – ne ubeži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 19, 'Zatorej pravi tako Gospod Jehova: Kakor resnično živim, prisego meni, ki jo je v nič dejal, in zavezo z menoj, ki jo je prelomil, prav to mu pripravim nad glavo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 20, 'In vržem mrežo svojo nanj in ulovljen bo v lovnici moji, in privedem ga v Babilon in tam se bom ž njim pravdal zaradi nezvestobe, ki jo je zagrešil zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 21, 'In vsi ubežniki njegovi od vseh krdel njegovih popadajo pod mečem, in kar jih preostane, bodo razkropljeni na vse vetrove. In spoznate, da sem jaz, Gospod, govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 22, 'Tako pravi Gospod Jehova: Tudi jaz vzamem od vršiča visoke cedre in ga zasadim; od najgorenjih vejic njenih odtrgam eno mlado in jo zasadim ne gori visoki in vzvišeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 23, 'Na visoki gori Izraelovi jo zasadim, in požene mladike in prinese sad in postane slavna cedra; in pod njo bodo prebivali vsi ptiči, vsakršna perutnina: v senci mladik njenih se nastanijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 17, 24, 'In spoznajo vsa drevesa na polju, da sem jaz, Gospod, ponižal visoko drevo, povišal nizko drevo, posušil zeleno drevo in suhemu drevesu dal zeleneti. Jaz, Gospod, sem govoril in storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 1, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 2, 'Kaj menite, da rabite ta pregovor o zemlji Izraelovi, govoreč: Očetje so zobali kislo grozdje in otrokom so zobje skominasti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 3, 'Kakor resnično živim, govori Gospod Jehova, ne boste več rabili tega pregovora v Izraelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 4, 'Glej, vse duše so moje; kakor duša očetova, tako duša sinova je moja; duša, ki greši, umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 5, 'In ako je kdo pravičen, in dela, kar je postavno in pravično,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 6, 'po gorah ne jé in oči ne vzdiguje proti grdim malikom Izraelove hiše, bližnjega svojega žene ne oskrunja in ženi v nesnagi njeni se ne bliža,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 7, 'nikomur ne škoduje, ampak dolžniku povrne zastavo, s silo ne vzame ničesar, lačnemu podeli kruh svoj in nagega odene z obleko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 8, 'na obresti ne posoja in ne lihvuje, od krivice odvrača roko, po resnici sodi med možem in možem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 9, 'po postavah mojih živi in pazi na sodbe moje, da bi stregel resnici: ta je pravičen, gotovo bo živel, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 10, 'Ako rodi sina silovitneža, ki preliva kri in stori katero onih reči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 11, 'tistih čednosti pa ne dela, marveč jé po gorah in oskrunja bližnjega svojega ženo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 12, 'ubožcu in potrebnemu škoduje, siloma jemlje, zastave ne vrne in oči vzdiguje h grdim malikom, počenja gnusobe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 13, 'posoja na obresti in lihvuje: ali bo živel? Ne bo živel! Vse te gnusobe je počenjal, mora umreti; kri njegova bodi nad njim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 14, 'A glej, rodi sina, ki vidi vse očeta svojega grehe, ki jih ta dela, pa se boji in enakega ne počenja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 15, 'ne jé po gorah, ne vzdiguje oči h grdim malikom Izraelove hiše, ne oskrunja bližnjega svojega žene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 16, 'ne škoduje nikomur, ne zahteva ničesar v zastavo, ne jemlje s silo, ampak daje lačnemu kruh svoj in odeva nagega z obleko;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 17, 'varuje se roko položiti na reveža, ne posoja na obresti in ne lihvari, izpolnjuje sodbe moje in živi po postavah mojih: ta ne umrje zaradi krivičnosti očeta svojega, gotovo bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 18, 'Oče njegov, ker je kruto stiskal, brata svojega siloma plenil in počenjal med ljudstvom svojim, kar ni dobro: glej, ta umre zaradi krivičnosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 19, 'A vi pravite: Zakaj ne nosi sin krivice očeta svojega? Ker je sin delal, kar je postavno in pravično, in je hranil vse postave moje ter jih izpolnjeval: gotovo bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 20, 'Duša, ki greši, umrje. Sin ne bo nosil očeta svojega krivice, tudi oče ne krivice sina svojega; pravičnost pravičnega ostane na njem, in brezbožnost ostane na brezbožnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 21, 'Ako pa se brezbožnik odvrne od vseh grehov svojih, ki jih je storil, in bo hranil vse postave moje in delal, kar je postavno in pravično, gotovo bo živel, ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 22, 'Nobeden od prestopkov njegovih, ki jih je zakrivil, se mu ne bo spominjal; zaradi pravičnosti svoje, ki jo je storil, bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 23, 'Ali mi je res po volji smrt brezbožnikova? govori Gospod Jehova; ni li mi bolj všeč, da se izpreobrne od svojega dejanja ter živi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 24, 'Ako pa se odvrne pravičnik od pravičnosti svoje ter dela nepravičnost po vseh gnusobah, ki jih počenja brezbožnik, ali naj živi? Nobeno od pravičnih del njegovih, ki jih je storil, se ne bo spominjalo: zavoljo nezvestobe svoje, s katero se je pregrešil, in zavoljo greha svojega, ki ga je zakrivil, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 25, 'In še pravite vi: Ni ravna pot Gospodova! Poslušajte vendar, o družina Izraelova: Moja li pot ni ravna? Ni li tako, da vaše poti niso ravne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 26, 'Ko se pravičnik odvrne od pravičnosti svoje in se vda nepravičnosti in umre v tem: umre zavoljo nepravičnosti svoje, ki jo je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 27, 'In ko se brezbožnik izpreobrne od brezbožnosti svoje, s katero je grešil, in dela, kar je postavno in pravično, ohrani dušo svojo v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 28, 'Ker je izprevidel in se je izpreobrnil od vseh prestopkov svojih, ki jih je zakrivil, gotovo bo živel, ne umrje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 29, 'A vendar govori družina Izraelova: Pot Gospodova ni ravna. O družina Izraelova, moja li pot ni ravna? Ni li tako, da vaše poti niso ravne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 30, 'Zatorej vas bom sodil, družina Izraelova, vsakega po dejanju njegovem, govori Gospod Jehova. Izpreobrnite se in odvrnite se od vseh prestopkov svojih, in krivica vam ne bo v padec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 31, 'Vrzite od sebe vse prestopke svoje, s katerimi ste se pregrešili, in oskrbite si novo srce in novega duha! kajti čemu naj bi mrli, o družina Izraelova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 18, 32, 'Zakaj meni ni po volji smrt njega, ki gine, govori Gospod Jehova. Zato se izpreobrnite in živite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 1, 'Ti pa zapoj žalostinko nad knezi Izraelovimi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 2, 'in reci: Kaj je bila mati tvoja? Levinja; med levi je ležala, sredi levičev je redila mladino svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 3, 'In vzredila je enega mladičev svojih, ta je postal mlad lev in se je navadil plen loviti, požiral je ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 4, 'In slišali so o njem narodi; ujet je bil v njih jami in peljali so ga z obroči v nosnicah v deželo Egiptovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 5, 'In ko je videla, da zaman čaka, da je izginila nada njena, vzame drugega mladičev svojih in stori iz njega mladega leva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 6, 'Ta je hodil med levi in postal mlad lev in se je navadil plen loviti, požiral je ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 7, 'In podiral je njih palače in pustošil njih mesta; in opustošena je bila dežela in kar je bilo v njej od glasu njegovega rjovenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 8, 'Tedaj so se postavili zoper njega narodi iz sosednjih pokrajin in so razpeli mrežo nad njim, v njih jami je bil ujet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 9, 'In dejali so ga z obroči v nosnicah v kletko ter ga pripeljali h kralju babilonskemu; spravili so ga v trdnjavo, da bi se ne slišal več glas njegov na gorah Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 10, 'Mati tvoja je bila kakor vinska trta, kakor ti pri vodi zasajena; rodovitna je bila in bogata z mladikami, ker je rasla ob obilih vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 11, 'In je zaredila močne veje, pripravne za palice vladarjem, in nje rast se je visoko vzpenjala med košatimi mladicami, in daleč jo je bilo videti zaradi visokosti njene, zaradi mnogih mladik njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 12, 'A izruvana je bila v togoti, na tla vržena, in vzhodni veter je posušil njen sad: močne veje njene so se zlomile in usahnile, ogenj jih je požgal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 13, 'In sedaj je zasajena v puščavi, v suhi in žejni zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 19, 14, 'In ogenj je švignil iz mladičja njenih vej in požrl nje sad, da ni na njej nobene močne veje, pripravne za palico vladarjem. To je žalostinka in bodi za žalostinko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 1, 'In zgodi se v sedmem letu, deseti dan petega meseca, da so prišli nekateri iz starejšin Izraelovih vpraševat Gospoda in so sedli predme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 2, 'In beseda Gospodova pride do mene, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 3, 'Sin človečji, ogovori starejšine Izraelove in jim reci: Tako pravi Gospod Jehova: Ste li prišli mene vpraševat? Kakor resnično živim, govori Gospod Jehova, ne bom vam odgovoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 4, 'Jih li hočeš soditi, sin človečji? hočeš li soditi? Oznani jim gnusobe njih očetov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 5, 'ter jim reci: Tako pravi Gospod Jehova: V dan, ko sem izvolil Izraela in povzdignil roko v prisego semenu hiše Jakobove in sem se jim dal spoznati v deželi Egiptovski in jim, povzdignivši roko svojo, rekel: Jaz sem Gospod, Bog vaš –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 6, 'tisti dan sem jim povzdignil roko v prisego, da jih izpeljem iz dežele Egiptovske v deželo, ki sem jo razgledal zanje, kjer teče mleko in med, ki je lepota vsem deželam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 7, 'In sem jim rekel: Sleherni vrzi od sebe ostude, ki so mu pred očmi, in ne oskrunjajte se z grdimi maliki Egipčanov; jaz sem Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 8, 'Ali oni so se mi uprli in me niso hoteli poslušati; nobeden ni vrgel od sebe ostude, ki jih je imel pred očmi, in grdih malikov Egipčanov niso zapustili. Zato sem mislil izliti srd svoj nadnje, da dopolnim jezo svojo zoper nje sredi dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 9, 'Ali ravnal sem z ozirom na ime svoje, da ne bodi onečaščeno pred očmi narodov, med katerimi so bivali, vpričo katerih sem se jim dal spoznati, da bi jih peljal iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 10, 'In storil sem, da so šli iz Egipta, in sem jih pripeljal v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 11, 'In dal sem jim postave svoje in jim oznanil sodbe svoje, po katerih bo živel človek, če jih izpolnjuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 12, 'Pa tudi sobote svoje sem jim dal, naj bodo znamenje med menoj in njimi, da bi spoznali, da sem jaz Gospod, ki jih posvečujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 13, 'Toda hiša Izraelova se mi je uprla v puščavi: niso živeli po postavah mojih in so zaničevali sodbe moje, po katerih bo živel človek, če jih izpolnjuje; in silno so oskrunjali sobote moje. Zato sem mislil izliti nadnje srd svoj, da jih pokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 14, 'Ali ravnal sem z ozirom na ime svoje, da ne bodi onečaščeno pred očmi narodov, vpričo katerih sem jih izpeljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 15, 'Vendar pa sem povzdignil roko svojo njim v prisego v puščavi, da jih ne bom peljal v deželo, ki sem jo jim dal, kjer teče mleko in med, ki je lepota vsem deželam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 16, 'ker so zavrgli sodbe moje in niso živeli po mojih postavah in oskrunili sobote moje; zakaj njih srce je šlo za njih grdimi maliki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 17, 'Ali prizaneslo jim je oko moje, da jih nisem pogubil ter jih nisem dočista pokončal v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 18, 'In dejal sem njih otrokom v puščavi: Po postavah očetov svojih ne živite in po njih šegah se ne ravnajte, tudi ž njih maliki se ne oskrunjajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 19, 'Jaz sem Gospod, Bog vaš: po mojih postavah živite in moje pravde izpolnjujte ter po njih ravnajte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 20, 'in sobote moje posvečujte, da bodo v znamenje med menoj in vami, da bi vedeli, da sem jaz Gospod, Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 21, 'Ali otroci so se mi uprli: niso živeli po postavah mojih in niso hranili pravd mojih, da bi jih izpolnjevali, po katerih bo živel človek, če jih izpolnjuje; sobote moje so oskrunjevali. Tedaj sem mislil izliti nadnje srd svoj, da dopolnim jezo svojo nad njimi v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 22, 'A zadržal sem roko svojo in ravnal sem z ozirom na ime svoje, da ne bodi oskrunjeno pred očmi narodov, vpričo katerih sem jih izpeljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 23, 'Tudi sem povzdignil roko in jim prisegel v puščavi, da jih razkropim med narode in raztresem po deželah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 24, 'ker niso izvrševali sodb mojih, ampak zaničevali so postave moje in oskrunjevali sobote moje in njih oči so gledale za maliki očetov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 25, 'Pa tudi jaz sem jim dal postave, ki niso dobre, in sodbe, po katerih se niso mogli ohraniti v življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 26, 'In oskrunil sem jih ž njih darili, s tem, da so vodili skozi ogenj vse prvorojeno: da bi jih opustošil, da spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 27, 'Zatorej, sin človečji, govori družini Izraelovi in jim reci: Tako pravi Gospod Jehova: Še s tem so me zasramovali očetje vaši, ko so zagrešili nezvestobo zoper mene:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 28, 'Ko sem jih pripeljal v deželo, za katero sem povzdignil roko svojo, da jim jo dam, so gledali po vsakem visokem griču in po vsakem košatem drevesu, in ondi so darovali klalne žrtve svoje in dajali darila svoja v draženje nevolje in ondi napravljali prijeten duh in izlivali pitne daritve svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 29, 'In rekel sem jim: Kaj pomeni tista višava, na katero hodite? In imenuje se njeno ime „višava“do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 30, 'Zato reci hiši Izraelovi: Tako pravi Gospod Jehova: Kako? skrunite se po navadi očetov svojih in hodite nečistovat za njih grdobami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 31, 'in skrunite se še do tega dne ob vseh grdih malikih svojih, ko darujete darila svoja, ko vodite sinove svoje skozi ogenj! in jaz naj vam odgovorim, ko me vprašujete, družina Izraelova? Kakor res živim, govori Gospod Jehova, ne maram, da bi me vprašali!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 32, 'In tisto, kar preudarjate v srcu, se nikakor ne uresniči; ko govorite: Enaki hočemo biti poganskim narodom, rodovinam po deželah, da služimo lesu in kamenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 33, 'Kakor res živim, govori Gospod Jehova, gotovo bom z mogočno roko in z iztegnjeno ramo in v razlitem srdu kraljeval nad vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 34, 'In izpeljem vas izmed ljudstev in zberem vas iz dežel, po katerih ste raztreseni, z mogočno roko in z iztegnjeno ramo in v razlitem srdu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 35, 'In pripeljem vas v puščavo ljudstev in tam se bom pravdal z vami od obličja do obličja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 36, 'kakor sem se pravdal z očeti vašimi v puščavi dežele Egiptovske, tako se bom pravdal z vami, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 37, 'In velel vam bom preiti pod palico in peljal vas bom v vezi zaveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 38, 'In izločim izmed vas upornike in tiste, ki so odpadli od mene; odpeljem jih iz dežele, kjer bivajo kot tujci, ali v zemljo Izraelovo ne pridejo. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 39, 'Vi torej, družina Izraelova, tako pravi Gospod Jehova: Pojdite, služite vsak malikom svojim! A pozneje – me boste resnično poslušali in imena svetosti moje ne boste več oskrunjevali z darili svojimi in z grdimi maliki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 40, 'Zakaj na gori svetosti moje, na gori višine Izraelove, govori Gospod Jehova, tam mi bo vsa družina Izraelova služila, vsi čiherni v deželi; tam jih milo sprejmem in tam bom zahteval vaše dari povzdignjenja in prvine vaših daril z vsem vred, kar posvečujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 41, 'Kakor prijeten duh vas milo sprejmem, ko vas odpeljem izmed ljudstev in vas zberem iz dežel, po katerih ste bili razkropljeni, in se nad vami izkažem svetega pred očmi poganskih narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 42, 'In spoznate, da sem jaz Gospod, ko vas pripeljem v zemljo Izraelovo, v tisto deželo, za katero sem povzdignil roko svojo, da jo dam očetom vašim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 43, 'In ondi se spomnite vseh potov svojih in vseh dejanj svojih, s katerimi ste se oskrunjali, in sami sebi se boste studili zavoljo vseh hudobnosti, ki ste jih zakrivili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 44, 'In spoznate, da sem jaz Gospod, ko bom z vami ravnal z ozirom na svoje ime, ne po vaših hudobnih potih in ne po vaših izprijenih dejanjih, o družina Izraelova, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 45, 'In beseda Gospodova mi pride, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 46, 'Sin človečji, obrni obličje proti poldnevu in kapljaj besede proti jugu in prorokuj zoper gozd poljane na Jugu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 47, 'in reci gozdu na Jugu: Čuj besedo Gospodovo! Tako pravi Gospod Jehova: Glej, jaz podnetim ogenj v tebi, ki požre vse zeleno drevje v tebi in vse suho drevje; plamteči ogenj ne bo mogel pogasniti in osmodil bo vse obraze od poldneva do polnoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 48, 'In vse meso bo videlo, da sem ga podnetil jaz Gospod; ne ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 20, 49, 'Tedaj sem rekel: Ah Gospod Jehova! Oni govore o meni: Ali ne govori ta zgolj v prilikah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 1, 'In beseda Gospodova mi pride, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 2, 'Sin človečji, obrni obličje proti Jeruzalemu in kapljaj besede proti svetinjam in prorokuj zoper zemljo Izraelovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 3, 'in reci zemlji Izraelovi: Tako pravi Gospod: Glej, jaz sem zoper tebe in izderem meč iz njegovih nožnic in zatarem v tebi pravične in brezbožne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 4, 'Zatorej, ker zatarem v tebi pravične in brezbožne, pojde meč moj iz svojih nožnic zoper vse meso od poldneva do polnoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 5, 'In vse meso spozna, da sem jaz, Gospod, potegnil meč svoj iz nožnic njegovih; ne vrne se več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 6, 'Ti pa, sin človečji, zdihuj, kakor da te ledje boli, v bridki bolečini zdihuj vpričo njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 7, 'In ko ti poreko: Zakaj zdihuješ? odgovóri: Zavoljo govorice, ki prihaja; in kopnelo bo vsako srce in vse roke opešajo in vsak duh omedli in vsa kolena se raztajejo kakor voda. Glej, prihaja in zgodi se to, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 8, 'Še mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 9, 'Sin človečji, prorokuj in reci: Tako pravi Gospod: Reci: Meč, meč, nabrušen in zlikan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 10, 'Da napravi klanje, je nabrušen, da se bliska, je zlikan. Ali naj se razveseljujemo? Palica, določena za mojega sina, zaničuje vse drevje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 11, 'Dali so ga zlikati, da se more prijeti v roko. Meč je nabrušen in zlikan, da se da morilcu v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 12, 'Vpij in tuli, sin človečji! kajti zoper moje ljudstvo je namerjen, zoper vse kneze Izraelove: meču so izročeni z mojim ljudstvom vred; zato se tolci po stegnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 13, 'Kajti izkušnja se je naredila; kaj pa, če palice, ki zaničuje vse, ne bode več? govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 14, 'Ti pa, sin človečji, prorokuj in ploskaj z roko ob roko; in dvojen bodi meč, trojen bodi meč, ki smrtno rani; morilni meč, veliki morilni meč je, ki jih obkroža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 15, 'Nameril sem ost meča proti vsem njih vratom, da jim skopni srce in jih mnogo popada. Gorje! narejen je, da se bliska, priostrili so ga za morjenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 16, 'Mahaj zadaj, na desno, spredaj, na levo, kamorkoli je namerjena ostrica tvoja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 17, 'Pa tudi jaz bom ploskal z roko ob roko, in potolažim srd svoj. Jaz, Gospod, sem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 18, 'Zopet mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 19, 'In ti, sin človečji, napravi si dva pota, po katerih naj pride meč kralja babilonskega; iz ene dežele naj držita oba; in nariši kažipot, ob začetku pota v mesto ga nariši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 20, 'Napravi pot, da bi prišel meč v Rabo sinov Amonovih in na Judovo v utrjeni Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 21, 'Zakaj kralj babilonski se ustavi ob razpotju, ob začetku tistih dveh potov, da se posvetuje z vedeževanjem: pretresa pšice, vprašuje hišne malike, ogleduje jetra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 22, 'V desnico njegovo pride vedeževanje „Jeruzalem!“, da naj nastavi zidolome, odpre usta, veleč moriti, povzdigne glas z bojnim vpitjem, nastavi zidolome zoper vrata, nanosi nasipe, zgradi obležne utrdbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 23, 'In zdelo se jim bo, kakor da je lažnivo vedeževanje; s prisego so jim potrdili; a on napelje v spomin krivdo, da bi bili ujeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 24, 'Zatorej pravi tako Gospod Jehova: Ker ste napeljali v spomin krivdo svojo s tem, da so se odkrili prestopki vaši, tako da se vidijo v vseh dejanjih vaših grehi vaši – ker ste prišli v spomin, boste ujeti z roko morilčevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 25, 'Ti pa, skrunilec svetega, brezbožnik, knez Izraelov, čigar dan je prišel ob času, ko se krivičnosti naredi konec,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 26, 'tako pravi Gospod Jehova: Snemite mu pokrivalo z glave, vzemite mu krono! Kar je, ne bode več tako. Nizko bodi povišano in visoko ponižano!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 27, 'Uničim, uničim, uničim jo; tudi ta ne bode več – dokler ne pride, kateri ima pravico do nje: njemu jo dam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 28, 'Ti pa, sin človečji, prorokuj in reci: Tako pravi Gospod Jehova zastran sinov Amonovih in zastran njih sramotenja, in reci: Meč, meč, izdrt v morjenje, poostren, da požira, da se bliska');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 29, '(oni pa vidijo ničemurne prikazni zate, ti prorokujejo laži), da ga denejo na vratove skrunilcem svetega, brezbožnikom, katerih dan je prišel ob času, ko se krivičnosti naredi konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 30, 'Vtakni ga zopet v nožnice svoje! Tam, kjer si bil ustvarjen, v rojstva tvojega deželi te bom sodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 31, 'In izlijem srd svoj nadte, ogenj jeze svoje bom pihal zoper tebe; in dam te v roko ljudem živinskim, ki kujejo pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 21, 32, 'Ognju bodeš v jed; kri tvoja bo sredi dežele; ne bo ti spomina več. Zakaj jaz, Gospod, sem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 1, 'Še mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 2, 'In ti, sin človečji, hočeš li soditi, hočeš li soditi mesto, ki je prelivalo kri? tedaj mu oznani vse gnusobe njegove');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 3, 'in reci: Tako pravi Gospod Jehova: Mesto, ki preliva kri v svoji sredi, da pride njegov čas, in ki si dela malike zoper sebe, da se ognuša!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 4, 'Krivdo si nadse spravilo s krvjo, ki si jo prelilo, in ognusilo si se z grdimi maliki svojimi, ki si jih naredilo; in storilo si, da so se približali dnevi tvoji, in dospelo si v leta svoja. Zato sem te postavil v zasramovanje vsem narodom in v zasmeh po vseh deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 5, 'Bodisi, da so blizu ali daleč od tebe, zasmehovali te bodo, ker si umazanega imena in obilo v zmešnjavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 6, 'Glej, v tebi so bivali knezi Izraelovi, vsak po moči svoji, da bi prelivali kri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 7, 'Očeta in mater so zaničevali v tebi; sredi tebe so delali silo tujcu, siroto in vdovo so žalili v tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 8, 'Svetinje moje si zaničevalo in sobote moje si skrunilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 9, 'Opravljivci so bili v tebi, da prelivajo kri; in izmed tebe so jedli mališke žrtve po gorah; sredi tebe so počenjali nesramnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 10, 'V tebi so odkrivali očetov svojih nagoto; v tebi so se pečali ž njo, ki je ločena zavoljo nesnage svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 11, 'In eden je počenjal gnusobo z ženo bližnjega svojega, in drugi je nesramno oskrunil snaho svojo, še drugi pa je v tebi posilil sestro svojo, očeta svojega hčer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 12, 'V tebi so darila jemali, da prelivajo kri; obresti in namečke si jemalo in s silo si dobičkarilo na svojih bližnjih. Mene pa si pozabilo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 13, 'Zato, glej, sem udaril v svojo roko v jezi nad dobičkaželjnostjo tvojo, s katero si ravnalo, in nad krivdo krvi, ki se je prelila sredi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 14, 'Bo li tvoje srce preneslo to, ali bodo roke tvoje zadosti močne v dneh, ko bom obračunjal? Jaz, Gospod, sem govoril in tudi storim to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 15, 'In razkropim te med poganske narode in razženem te po deželah in docela odpravim nesnažnost tvojo iz tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 16, 'In oskruniš se samo po sebi pred očmi narodov; in spoznaš, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 17, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 18, 'Sin človečji, hiša Izraelova mi je postala v žlindro: vsi izmed njih so bron in kositer in železo in svinec sredi peči; srebrna žlindra so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 19, 'Zatorej pravi tako Gospod Jehova: Ker ste vsi postali žlindra, zato, glejte, vas zberem sredi Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 20, 'kakor spravijo srebro in bron in železo in svinec in kositer v peč in ogenj spodaj podpihajo, da to raztope: tako vas skopičim v jezi in togoti svoji in vas vsadim v ogenj ter vas raztopim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 21, 'Da, zberem vas in ogenj jeze svoje bom pihal zoper vas, in raztapljali se boste sredi Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 22, 'Kakor se srebro topi sredi peči, tako se boste topili sredi njega. In spoznate, da sem jaz, Gospod, izlil srd svoj nad vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 23, 'In beseda Gospodova mi pride, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 24, 'Sin človečji, reci ji: Ti si dežela, ki nisi oplaknjena, ki si ostala brez dežja v dan jeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 25, 'Njeni proroki so napravili zaroto v njej: kakor rjoveči lev, ki trga plen, žro duše, jemljejo zaklade in dragotine, vdove pomnožujejo v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 26, 'Duhovniki njeni delajo silo postavi moji in skrunijo svetinje moje; med svetim in nesvetim ne delajo razločka, tudi ne uče razločevati med nečistim in čistim; in zagrinjajo si oči pred sobotami mojimi in mene onečaščujejo med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 27, 'Knezi njeni v njej so kakor volkovi, ki trgajo plen, da prelivajo kri, v pogubo spravljajo duše, samo da dobe krivičen dobiček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 28, 'In proroki njeni jim mažejo vse z belilom s tem, da gledajo ničemurne prikazni in jim vedežujejo laži, govoreč: Tako pravi Gospod Jehova, ko vendar Gospod ni govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 29, 'Ljudstvo na deželi je zabredlo v nasilstvo in goji grabež; ubožca in potrebnega tlačijo in tujcem delajo silo in krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 30, 'In iskal sem moža med njimi, ki bi zazidal zid in stopil proti meni v razpoko za deželo, a nisem ga našel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 22, 31, 'Zato izlije nadnje srd svoj, z ognjem jeze svoje jih pokončam; njih dejanje jim spravim na glavo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 1, 'Zopet mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 2, 'Sin človečji, bili sta dve ženi, ene matere hčeri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 3, 'In sta nečistovali v Egiptu, nečistovali sta v mladosti svoji; tam so jima segali v nedrje, ondi so jima otipavali deviške prsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 4, 'Njiju imeni pa sta bili: Ohola, starejša, in Oholiba, mlajša. In postali sta moji in rodili sta sinove in hčere. Kar se pa tiče njiju imen: Samarija je Ohola, Jeruzalem pa je Oholiba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 5, 'In Ohola je nečistovala, ko je bila moja; in od ljubezni je gorela do ljubovnikov svojih, do Asircev, ki so bili blizu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 6, 'oblečeni v višnjevo, poglavarji in namestniki, vsi zgolj ljubeznivi mladeniči, jezdeci, jahajoči konje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 7, 'In dala se jim je v nečistovanje, vsem tem izbrancem Asurjevih sinov; in z vsemi, do katerih je gorela v ljubezni, ž njih maliki se je oskrunjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 8, 'Tudi ni opustila svojega nečistovanja, ki ga je začela v Egiptu; kajti v njeni mladosti so ležali pri njej in otipavali deviške prsi njene in so počenjali ž njo svojo nečistost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 9, 'Zato sem jo dal v roko njenim ljubovnikom, v roko Asircev, do katerih je v ljubezni gorela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 10, 'Ti so odgrnili nje sramoto; vzeli so sinove in hčere njene in njo samo so usmrtili z mečem; in postala je razvpita med ženami, in vršili so sodbe nad njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 11, 'In njena sestra Oholiba je videla to, a razvnela se je še bolj v ljubezni nego ona in v nečistovanju svojem, ki je bilo hujše nego sestre njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 12, 'Gorela je do Asircev, poglavarjev in namestnikov, ki so ji bili blizu, krasno oblečeni, jezdeci, jahajoči konje, vsi zgolj ljubeznivi mladeniči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 13, 'In videl sem, da se je oskrunila; obe sta delali enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 14, 'A ona je še pomnožila nečistovanje svoje; kajti videla je može, naslikane na steni, podobe Kaldejcev, slikane z rumenico,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 15, 'okoli ledja opasane, s širokimi pokrivali na glavah, vse jih je bilo videti kakor viteze, slične Babiloncem, ki jim je Kaldeja rojstna dežela;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 16, 'in ko jih je bila ugledala, se je razvnela v ljubezni do njih, in je poslala sporočnike k njim v Kaldejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 17, 'In Babilonci so prišli k njej uživat ljubezen in so jo oskrunili s svojo nečistostjo; in ko je bila ognušena ž njimi, se je odvrnila duša njena od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 18, 'In ko je odkrila nečistovanje svoje in odgrnila sramoto svojo, tedaj se je odvrnila duša moja od nje, kakor se je bila odvrnila od sestre njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 19, 'A še je množila nečistovanje svoje, spominjajoč se dni mladosti svoje, v katerih se je vdajala nečistovanju v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 20, 'In razvnela se je do njih priležnikov, katerih meso je kakor meso oslovsko in njih tok kakor konjski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 21, 'Tako si hrepenela po pohotnosti mladosti svoje, ko so ti Egipčani v nedrje segali zavoljo mladostnih prsi tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 22, 'Zatorej, Oholiba, tako pravi Gospod Jehova: Glej, jaz obudim zoper tebe ljubovnike tvoje, od katerih se je odvrnila duša tvoja, in pripeljem jih nadte od vseh strani:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 23, 'Babilonce in vse Kaldejce, Pekoda, Šoa in Koa, in vse Asirce ž njimi, ljubeznive mladeniče, zgolj poglavarje in namestnike vse, viteze in pooblaščence, vsi bodo jahali konje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 24, 'In pridejo nadte z orožjem, z vozovi in kolesi in z množico ljudstev; s ščitki in ščiti in čeladami se razpostavijo zoper tebe; in izročim jim sodbo, in sodili te bodo po svojih pravicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 25, 'In namerim gorečnost svojo zoper tebe, da bodo s teboj ravnali v togoti: nos in ušesa ti odrežejo, in kar tvojih ostane, padejo pod mečem; sinove in hčere tvoje ti vzamejo, in kar ti ostane, požre ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 26, 'Slečejo ti tudi obleko in vzemo lepe dragotine tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 27, 'In tako storim, da te mine nesramnost tvoja in nečistovanje tvoje, navajeno iz dežele Egiptovske, da več ne povzdigneš oči do njih in se ne boš več spominjala Egipta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 28, 'Kajti tako pravi Gospod Jehova: Glej, jaz te izdam v roko tistih, ki jih sovražiš, v pest njim, od katerih se je odvrnila duša tvoja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 29, 'in ravnali bodo s teboj v sovraštvu in vzemo vse, kar si pridelala, pa te puste nago in golo; in sramota tvojega nečistovanja se odkrije, nesramnost in nečistost tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 30, 'To se ti zgodi, zato ker si hodila nečistovat za pogani in ker si se oskrunila ž njih grdimi maliki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 31, 'Po poti sestre svoje si hodila, zato tudi dam nje čašo v roko tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 32, 'Tako pravi Gospod Jehova: Piti moraš iz sestre svoje čaše, globoke in široke, v kateri je zate toliko zasmeha in zasrambe, kolikor le zajme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 33, 'Polna bodeš pijanosti in žalosti; ker čaša groze in otožnosti je sestre tvoje Samarije čaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 34, 'Dočista jo izpiješ in izsrkaš in še črepinje njene boš lizala in si raztrgala prsi; zakaj jaz sem govoril, pravi Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 35, 'Zatorej pravi tako Gospod Jehova: Ker si mene pozabila ter si me vrgla za hrbet svoj, zato trpi tudi ti kazen nesramnosti in nečistosti svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 36, 'Dalje mi reče Gospod: Sin človečji, hočeš li soditi Oholo in Oholibo? Oznani jima torej njiju gnusobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 37, 'Kajti prelomili sta zakon in kri je na njiju rokah; in s svojimi maliki sta prešeštvovali, in celo otroke svoje, ki sta jih rodili meni, sta jim v čast vodili skozi ogenj, da bi bili požrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 38, 'Vrhutega sta mi storili to: isti dan oskrunjali sta svetišče moje in moje sobote ognušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 39, 'Zakaj ko sta zaklali otroke svoje v čast malikom, sta prišli še isti dan v svetišče moje, da ga oskrunita: glej torej, tako sta delali v hiši moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 40, 'Vrhutega sta celo pošiljali k možem, naj pridejo iz daljave, – h katerim je bil poslan sel, in glej, prišli so – za katere si se umivala, si mazala z lepotico oči in z lepotičjem se zaljšala,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 41, 'in si sedla na prelepo posteljo, pred katero je bila pripravljena miza, in nanjo si postavila kadilo moje in olje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 42, 'In pri tem se je glasilo vpitje vesele množice. In k možem iz prostaških ljudi so bili pripeljani še pijanci iz puščave, in deli so jima naročnice na roke in lepe vence na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 43, 'Tedaj sem dejal o njej, ki je opešala vsled prešeštvovanja: Bodo li še zdaj prešeštvovali ž njo, in ona tudi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 44, 'In hodili so k njej, kakor se hodi k nečistnici; tako so hodili k Oholi in k Oholibi, nesramnima ženskama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 45, 'Pravični možje pa ju bodo sodili s sodbo prešeštnic in s sodbo prelivalk krvi; kajti prešeštnici sta in kri je na njiju rokah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 46, 'Zakaj tako pravi Gospod Jehova: Pripeljem zbor gori proti njima in ju izročim, da ju pojajo semtertja in plenijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 47, 'In zbor ju bo pobijal s kamenjem in prebodel z meči; njiju sinove in hčere pomore in z ognjem požgo njih hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 48, 'In tako storim konec nesramnosti v deželi, vsem ženam v svarilo, da ne delajo po vajini nesramnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 23, 49, 'In spravijo nesramnost vajino nad vaju, in nosili bosta grehe grdih malikov svojih. In spoznate, da sem jaz Gospod, Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 1, 'In deveto leto, deseti dan desetega meseca je prišla beseda Gospodova do mene, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 2, 'Sin človečji, zapiši si ime tega dneva, današnjega dneva! Ta današnji dan je pritisnil kralj babilonski na Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 3, 'In govóri priliko uporni družini in jim reci: Tako pravi Gospod Jehova: Pristavi lonec, pristavi ga in vlij vode vanj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 4, 'Deni vanj kose, vse najboljše kose, stegno in pleče; napolni ga z izbranimi kostmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 5, 'Vzemi najboljše iz drobnice, zlóži tudi kup drv za kosti podenj; daj, da močno vre, da se tudi kosti v njem razkuhajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 6, 'Zatorej pravi tako Gospod Jehova: Gorje mestu, ki je prelivalo kri, loncu, ki se ga je prijela rja in rja ne gre od njega! Kos za kosom izmeči iz njega, ne da bi se vadljalo zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 7, 'Kajti kri njegova je sredi njega: na golo skalo jo je prelilo, ni je izlilo na zemljo, da bi jo mogli pokriti s prstjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 8, 'Da pride nadenj srd in se izvrši maščevanje, sem del njegovo kri na golo skalo, da ne bodi pokrita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 9, 'Zato pravi tako Gospod Jehova: Gorje mestu, ki je prelivalo kri! Tudi jaz naredim veliko grmado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 10, 'Nanosi sem drv, razneti ogenj, dobro prekuhaj meso, naj se zvari juha, kosti naj se sežgo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 11, 'Nato ga deni praznega na žerjavico njegovo, da se njegova bronina razbeli in raztopi in da se njegova nečistost v njem razpusti, rja njegova izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 12, 'Vse prizadevanje je utrudilo, pa obila rja njegova ne gre od njega; še po ognju ostane rja njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 13, 'V nečistosti tvoji je nesramnost. Ker sem te očiščeval, a nisi bilo očiščeno, ne boš več očiščeno nečednosti svoje, dokler ne pomirim togote svoje nad teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 14, 'Jaz, Gospod, sem govoril. Pride čas, in storim to; ne odneham, ne prizanesem, tudi žal mi ne bode. Po tvojih potih in po tvojih dejanjih te bodo sodili, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 15, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 16, 'Sin človečji, glej, vzamem ti željo tvojih oči z enim udarcem; ali ne žaluj in ne plakaj in solz ne toči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 17, 'Molče zdihuj, žalovanja po mrtvem ne napravljaj; z zalim pokrivalom si ovij glavo in obuj čevlje na noge, in ne zagrinjaj si brade in ne jej kruha od ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 18, 'In ko sem zjutraj govoril ljudstvu, mi je umrla žena na večer. In drugo jutro sem storil, kakor mi je bilo ukazano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 19, 'In ljudstvo mi reče: nočeš li nam povedati, kaj nam to pomeni, kar delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 20, 'Nato jim rečem: Beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 21, 'Govori družini Izraelovi: Tako pravi Gospod Jehova: Glej, jaz onesvetim svetišče svoje, ponos vaše moči, željo oči vaših in hrepenenje vaših duš; in sinovi vaši in hčere vaše, ki ste jih pustili za sabo, padejo pod mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 22, 'Takrat boste storili, kakor sem jaz storil: brade ne boste zagrinjali, ne jedli kruha od ljudi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 23, 'in zala pokrivala bodo na vaših glavah in čevlje boste imeli na nogah; ne boste žalovali, ne jokali, temuč ginili boste v krivicah svojih in zdihovali drug proti drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 24, 'Tako vam bode Ezekiel v zgledno znamenje: vse, kakor je storil, boste storili. Kadar to pride, spoznate, da sem jaz Gospod, Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 25, 'Ti pa, sin človečji, tisti dan, ko jim vzamem njih moč, veselje njih krasote, željo njih oči in hrepenenje njih duš, namreč njih sinove in hčere,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 26, 'tisti dan pride k tebi ubežnik, da naznani ušesom tvojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 24, 27, 'tisti dan se odpro usta tvoja proti ubežniku, in govoril boš in ne boš več molčal. In tako jim bodeš v zgledno znamenje, in vedeli bodo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 1, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 2, 'Sin človečji, obrni obličje proti sinovom Amonovim in prorokuj zoper nje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 3, 'ter govóri sinom Amonovim: Poslušajte Gospoda Jehove besedo! Tako pravi Gospod Jehova: Zato ker praviš o mojem svetišču: Haha! ker je onesvečeno, in o zemlji Izraelovi, ker je opustošena, in o družini Judovi, ker je šla v ujetništvo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 4, 'zato, glej, te dam sinom jutrovim v posest; in postavijo v tebi šatorišča svoja in narede v tebi bivališča svoja; oni bodo jedli sad tvoj, oni bodo pili mleko tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 5, 'In dal bom Rabo za trato velblodom in mesta sinov Amonovih za ležišče drobnicam. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 6, 'Zakaj tako pravi Gospod Jehova: Zato ker si ploskal z rokami in topotal z nogami ter se veselil z vsem zaničevanjem v duši svoji spričo zemlje Izraelove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 7, 'zato, glej, iztegnem roko svojo zoper tebe ter te dam narodom v plen, in iztrebim te izmed ljudstev in pogubim te iz dežel; jaz te uničim, in spoznaš, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 8, 'Tako pravi Gospod Jehova: zato ker Moab in Seir govorita: Glej, družina Judova je kakor vsi poganski narodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 9, 'zato, glej, odprem stran Moabovo (odstranivši mesta njegova, ki so po vsej meji njegovi, dika dežele, Betjesimot, Baal-meon in Kirjataim)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 10, 'sinom jutrovim s sinovi Amonovimi vred in ga dam njim v posest, da ne bi bilo spomina sinom Amonovim med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 11, 'In izvršim sodbo nad Moabom; in spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 12, 'Tako pravi Gospod Jehova: Zato ker je Edom maščevalno ravnal zoper družino Judovo in so se zelo pregrešili, ko so se maščevali nad njimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 13, 'zato pravi tako Gospod Jehova: Iztegnem roko svojo proti Edomu ter iztrebim iz njega ljudi in živino; in ga naredim v puščavo od Temana naprej, in prav do Dedana bodo padali pod mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 14, 'In izvršim maščevanje nad Edomom po roki ljudstva svojega Izraela; in ravnali bodo z Edomom po jezi moji in po togoti moji. In spoznajo maščevanje moje, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 15, 'Tako pravi Gospod Jehova: Zato ker so Filistejci maščevalno ravnali in so se maščevali z zaničevanjem v duši svoji, da pokončajo z večnim sovraštvom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 16, 'zato pravi tako Gospod Jehova: Glej, iztegnem roko svojo proti Filistejcem in iztrebim Keretejce in pogubim ostanek v primorju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 25, 17, 'In izvršim veliko maščevanje nad njimi s srditimi kaznimi. In spoznajo, da sem jaz Gospod, ko izvršim maščevanje svoje nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 1, 'V enajstem letu, prvi dan meseca, mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 2, 'Sin človečji, zato ker pravi Tir o Jeruzalemu: Ahá! strt je, ki je bil vrata narodom; k meni se je obrnil; napolnjen bodem, ker je on opustošen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 3, 'zato pravi tako Gospod Jehova: Glej, jaz sem zoper tebe, Tir, in storim, da se vzdignejo mnogi narodi zoper tebe, kakor morje zaganja valove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 4, 'In razvalé zidove Tira in podero stolpe njegove; in prst njegovo postržem ž njega in ga naredim v golo skalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 5, 'Postane prostor sredi morja, na katerem bodo razprostirali mreže. Kajti jaz sem to rekel, govori Gospod Jehova. In bode v plen narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 6, 'In hčere njegove, ki so na poljani, bodo umorjene z mečem. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 7, 'Zakaj tako pravi Gospod Jehova: Glej, privedem nad Tir Nebukadnezarja, kralja babilonskega, kralja kraljev, od severa, s konji in z vozmi in s konjiki, in veliko množico ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 8, 'On umori z mečem hčere tvoje na poljani in postavi obležne stolpe zoper tebe in okrog tebe nanosi nasip in ščite povzdigne zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 9, 'In nameri metalnice svoje proti zidovom tvojim in s svojimi kladivi podre stolpe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 10, 'Konj njegovih bode toliko, da te njih prah pokrije; vsled ropota jezdecev in koles in voz njegovih se bodo tresli zidovi tvoji, kadar pojde skozi vrata tvoja, kakor vhajajo v mesto, v katero so naredili predor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 11, 'S kopiti konj svojih potepta vse ulice tvoje, ljudstvo tvoje pomori z mečem, in stebri moči tvoje se zvrnejo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 12, 'In bogastvo tvoje pobero kot rop in kupčijsko blago tvoje jim bode v plen; in porušijo zidove tvoje in krasne hiše tvoje razdenejo; in tvoje kamenje in lesovje tvoje in prah tvoj pomečejo v vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 13, 'In storim, da umolkne glas pesmi tvojih in brenk citer tvojih se ne bo slišal več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 14, 'In naredim te v golo skalo; prostor bodeš, kjer bodo razprostirali mreže; ne boš sezidan več. Zakaj jaz, Gospod, sem to rekel, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 15, 'Tako pravi Gospod Jehova Tiru: Ali se ne bodo tresli otoki od hrupa padca tvojega, ko bodo ranjenci zdihovali, ko se bo morilo sredi tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 16, 'Tedaj stopijo vsi pomorski knezi s prestolov svojih in odlože plašče in slečejo pisana oblačila. Obleka jim bo trepet, na tleh sedeč, bodo vztrepetali vsak trenotek in strmeli ob tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 17, 'In napravijo žalovanje zate in ti poreko: Kako si poginilo, sloveče mesto, ki so v tebi prebivali pomorščaki! ki je bilo močno na morju, ono in njegovi prebivalci, ki je strahovalo vse, ki so v njem prebivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 18, 'Tedaj se bodo tresli otoki v dan padca tvojega, da, otoki daleč na morju bodo prestrašeni ob tvojem koncu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 19, 'Zakaj tako pravi Gospod Jehova: Ko te naredim v mesto opustošeno, enako mestom, ki v njih ne stanujejo več, ko pripeljem nadte povodenj in te pokrijejo velike vode,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 20, 'tedaj te pahnem doli k njim, ki gredo v jamo, k ljudstvu starodavnemu, in storim, da boš prebival v spodnjih krajih zemlje, v razvalinah od starodavnega, ž njimi vred, ki so šli v jamo, da ti ne ostane prebivalcev; a slavo postavim v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 26, 21, 'V strahoto te naredim, in ne bode te več; in iskali te bodo, a ne najdejo te nikdar več, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 1, 'Zopet mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 2, 'Ti pa, sin človečji, zapoj žalostinko nad Tirom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 3, 'in reci Tiru: O ti, ki prebivaš ob dohodih na morje, ki si trgovec ljudstvom na mnogih otokih, tako pravi Gospod Jehova: Ti, o Tir, si rekel: Jaz sem popoln v lepoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 4, 'Meja tvoja sega v srce morja, zgraditelji tvoji so te popolnega storili v lepoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 5, 'Iz cipres s Senirja so ti zgradili vse dvojne deske; ceder z Libanona so vzeli, da so ti napravili jadrnik;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 6, 'hraste z Basana so stesali v vesla tvoja, krov tvoj so naredili iz slonovih kosti, vloženih v zelenikov les z otokov Kitimcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 7, 'Pisanotkana tenčica iz Egipta je bila jadrovina tvoja, da ti je služila za zastavo; višnjeva in zagorelordeča tkanina z otokov Eliških je bila odeja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 8, 'Prebivalci s Sidona in Arvada so bili veslači tvoji; modrci tvoji, ki so bili v tebi, Tir, so bili krmarji tvoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 9, 'starejšine iz Gebala in modrci njegovi so bili v tebi, da so popravljali razpoke tvoje. Vse morske ladje in njih mornarji so bivali v tebi, da so spravljali v promet blago tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 10, 'Perzijci in Lud in Put so bili v vojski tvoji vojščaki tvoji, ščit in čelado so obešali v tebi, v sijajnost so ti dajali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 11, 'Možje iz Arvada so stali z vojsko tvojo kroginkrog na obzidju tvojem in junaki so bili na stolpih tvojih; ščite svoje so razobešali po zidovih tvojih; popolno so storili lepoto tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 12, 'Tarsis je bil v trgovski zvezi s teboj zaradi obilosti raznoterega blaga; s srebrom, železom, kositerjem in svincem so kupovali blago tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 13, 'Javan, Tubal in Mesek so bili kupci tvoji, duše človeške in posode bronaste so zamenjevali za robo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 14, 'Oni iz družine Togarmove so dajali konje, vojne konje in mezge za blago tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 15, 'Sinovi Dedanovi so bili kupci tvoji. Mnoga pomorja so bila v kupčijski zvezi s teboj: slonove zobe in ebenov les so ti dajali v plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 16, 'Sirija je bila v trgovski zvezi s teboj zaradi obilosti izdelkov tvojih: ognjenec, škrlat, pisano tkanino, tenčico, korale in rubine so dajali za blago tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 17, 'Juda in dežela Izraelova sta bili v kupčiji s teboj: pšenico iz Minita in sladko pecivo, med, olje in balzam so zamenjavali za robo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 18, 'Damask je bil v trgovski zvezi s teboj za mnoge izdelke tvoje, zaradi obilosti raznoterega blaga, z vinom iz Helbona in z volno iz Zaharja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 19, 'Vedan in Javan iz Uzala so z obdelanim železom kupovali blago tvoje; cimet in kolmež sta bila med kupčijsko robo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 20, 'Dedan je bil v kupčiji s teboj z dragimi preprogami za ježo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 21, 'Arabija in vsi knezi kedarski so bili v kupčijski zvezi s teboj: s pitanimi jagnjeti in ovni in kozli so tržili s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 22, 'Trgovci iz Sabe in Ragme so bili tebi trgovci: z najboljšimi dišavami in z vsemi dragimi kameni in zlatom so kupovali blago tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 23, 'Haran in Kane in Eden, trgovci iz Sabe, Asurja in Kilmada so kupčevali pri tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 24, 'Kupčevali so s teboj za krasna oblačila, za plašče iz višnjeve in pisanotkane robe, za zaklade sukane preje, za pletene in trdne vrvi na tržišču tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 25, 'Ladje tarsiške so bile karavane tvoje za tvojo menjalno kupčijo. In bil si z vsem napolnjen in silno slaven v srcu morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 26, 'Brodarji tvoji so te zavozili v velike vode; vzhodni veter te je strl v srcu morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 27, 'Bogastvo tvoje in blago tvoje, menjalna kupčija tvoja, mornarji in krmarji tvoji, popravljalci razpoklin tvojih in menjalci blaga tvojega in vsi vojščaki tvoji, ki so v tebi, z vsem krdelom tvojim, ki je sredi tebe, popadajo v srce morja v dan padca tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 28, 'Od glasnega vpitja krmarjev tvojih se potresejo poljane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 29, 'In vsi, ki vladajo veslo, mornarji, vsi krmarji na morju, stopijo z ladij svojih, se postavijo na kopno');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 30, 'in bodo glasno nad teboj vpili, bridko žalovali, in sipali si bodo prah na glave ter se valjali po pepelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 31, 'Lase si bodo zavoljo tebe obrili in z raševnikom se opasali, in plakali bodo zaradi tebe v bridkosti duše v prebridkem žalovanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 32, 'V tarnanju svojem začno peti žalostinko o tebi in bodo žalovali po tebi, govoreč: Kdo li je kakor Tir, ki je umolknil sredi morja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 33, 'Ko se je tvoje blago rodevalo iz morja, si sitil mnoga ljudstva; z obilostjo bogastva svojega in kupčije svoje si obogatil kralje zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 34, 'Sedaj, ko si strt od morja v globočinah voda in je tvoje blago in vse krdelo tvoje padlo sredi tebe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 35, 'strme ob tebi vsi prebivalci otokov in njih kralji se grozno boje, njih obličja trepetajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 27, 36, 'Kupci med ljudstvi žvižgajo nad teboj. Strahota si vsem, in nikdar več te ne bo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 1, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 2, 'Sin človečji, reci knezu v Tiru: Tako pravi Gospod Jehova: Ker se je prevzelo srce tvoje in govoriš: „Jaz sem bog, na božjem sedežu sedim v srcu morja!“ko vendar si človek in ne Bog, čeprav si naredil srce svoje kakor srce božje –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 3, 'glej, modrejši si od Daniela, ni skrivnosti, ki bi ti bila skrita,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 4, 'po svoji modrosti in po razumu svojem si sebi dobil bogastva in spravil zlata in srebra v zakladnice svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 5, 'po veliki modrosti svoji si s svojo trgovino razmnožil bogastvo svoje in srce se ti je prevzelo zaradi bogastva tvojega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 6, 'zato pravi tako Gospod Jehova: Ker si naredil srce svoje kakor srce božje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 7, 'zato, glej, pripeljem nad tebe tujce, silovitnike med narodi: ti potegnejo meče svoje zoper lepoto modrosti tvoje in oskrunijo veličje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 8, 'V jamo te pahnejo, in umrješ mučno smrt prebodencev v srcu morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 9, 'Porečeš li pač vpričo morilca svojega: „Jaz sem bog!“ko vendar si človek in ne Bog v roki tistih, ki te ubijajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 10, 'Smrt neobrezancev umreš po roki tujcev; kajti jaz sem to rekel, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 11, 'Še mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 12, 'Sin človečji, zapoj žalostinko nad kraljem tirskim in mu reci: Tako pravi Gospod Jehova: Pečat dovršenosti si bil, poln modrosti in popoln v lepoti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 13, 'bil si v Edenu, vrtu Božjem; vsakovrstno žlahtno kamenje je bilo pokrivalo tvoje: sard, topaz in demant, hrizolit, oniks in jaspid, safir, rubin in smaragd in zlato. Umetno delo tvojih bobničev in piščali je bilo pri tebi, v dan, ko si bil ustvarjen, so jih pripravili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 14, 'Bil si maziljenec, kerub, ki zaslanja; in jaz sem te postavil, da si bil na sveti gori Božji; sredi ognjenih kamenov si se izprehajal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 15, 'Popoln si bil v svojih dejanjih od dne, ko si bil ustvarjen, dokler se ni našla nepravičnost na tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 16, 'Vsled velike kupčije tvoje se je napolnila notranjščina tvoja s silovitostjo, in si grešil; zato sem te pahnil kot nesvetega z gore Božje in sem te, o kerub zaslanjajoči, pogubil izmed ognjenih kamenov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 17, 'Srce se ti je prevzelo zavoljo lepote tvoje, pokvaril si modrost svojo spričo sijaja svojega; zvrnil sem te na tla, kraljem pred oči sem te del, da bi te gledali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 18, 'Po množini krivic svojih, v nepravičnosti kupčije svoje si onečastil svetišča svoja; zato sem izpeljal izsredi tebe ogenj, ki te je požrl, in izpremenil sem te v pepel na zemlji pred očmi vseh tistih, ki te gledajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 19, 'Vsi, ki te poznajo med narodi, strme ob tebi; strahota si vsem, in nikdar več te ne bo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 20, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 21, 'Sin človečji, obrni obličje proti Sidonu in prorokuj zoper njega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 22, 'in reci: Tako pravi Gospod Jehova: Glej, jaz sem zoper tebe, o Sidon, in hočem se oslaviti sredi tebe; in spoznajo, da sem jaz Gospod, ko izvršim sodbe v njem in se izkažem svetega pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 23, 'In pošljem vanj kugo in kri na ulice njegove; in ranjenci bodo padali sredi njega pod mečem, ki pride nanj od vseh strani. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 24, 'Družini Izraelovi pa ne bode več bodečega trnja, ne ostna, ki napravlja bolečino, med vsemi, ki so okoli njih, ki so jih zaničevali. In spoznajo, da sem jaz Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 25, 'Tako pravi Gospod Jehova: Ko zberem družino Izraelovo iz ljudstev, med katera so bili razkropljeni, in se oslavim pri njih pred očmi poganskih narodov, tedaj bodo prebivali v svoji deželi, ki sem jo dal hlapcu svojemu Jakobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 28, 26, 'In bodo varno v njej prebivali, da, hiše zidali in vinograde zasajali in brezskrbno prebivali, ko izvršim sodbe nad vsemi tistimi, ki so jih zaničevali v njih sosedstvu. In spoznajo, da sem jaz, Gospod, njih Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 1, 'V desetem letu, dvanajsti dan desetega meseca, mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 2, 'Sin človečji, obrni obličje proti Faraonu, kralju v Egiptu, in prorokuj zoper njega in zoper ves Egipt,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 3, 'govori in reci: Tako pravi Gospod Jehova: Glej, jaz sem zoper tebe, Faraon, kralj egiptovski, veliki zmaj, ki ležiš sredi svojih rek, ki si rekel: Moja reka je moja in jaz sem jo sebi naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 4, 'A denem ti trnek v čeljusti in storim, da se prilepijo ribe tvojih rek tebi na luskine, in izvlečem te gori iz rek tvojih z vsemi ribami tvojih rek vred, ki se tvojih luskin drže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 5, 'In vržem te v puščavo, tebe in vse ribe tvojih rek; na planem polju padeš; ne pobero te, ne spravijo te: zverinam zemlje in pticam nebeškim sem te dal za jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 6, 'In zvedeli bodo vsi prebivalci Egipta, da sem jaz Gospod, zato ker so bili trstovec hiši Izraelovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 7, 'Kadar so te z roko prijeli, si se zlomil in jim predrl vse rame; kadar so se pa nate oprli, si se prelomil in storil, da jim je omahovalo vse ledje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 8, 'Zatorej pravi tako Gospod Jehova: Glej, pripeljem meč nadte ter iztrebim ljudi in živino iz tebe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 9, 'in dežela Egiptovska bode v puščavo in samoto. In spoznajo, da sem jaz Gospod. Ker Faraon govori: Reka je moja in jaz sem jo naredil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 10, 'zato, glej, sem jaz zoper tebe in zoper reke tvoje, in naredim deželo Egiptovsko v suhe, puste pustinje, od Migdola do Siene, prav do meje Etiopije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 11, 'Ne bo hodila skozi njo ne človeška, ne živalska noga, in ne bodo v njem prebivali štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 12, 'In naredim deželo Egiptovsko v puščavo sredi opustošenih dežel in mesta njegova bodo puščava med pustimi mesti štirideset let; in razkropim Egipčane med narode ter jih razženem pa deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 13, 'Ali tako pravi Gospod Jehova: Ob koncu štiridesetih let zberem Egipčane izmed narodov, med katere so bili razkropljeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 14, 'in pripeljem nazaj ujetništvo egiptovsko in jih privedem v deželo Patros, v deželo njih rojstva, in tam bodo neznatno kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 15, 'In bode nižje nego druga kraljestva in ne bo se več poviševalo nad narodi; in zmanjšam jih, da ne bodo več gospodovali narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 16, 'In ne bode več hiši Izraelcev v upanje, ki jih spominja njih krivice, da so se k njemu obračali. In spoznajo, da sem jaz Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 17, 'In zgodilo se je v sedemindvajsetem letu, prvi dan prvega meseca, da mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 18, 'Sin človečji! Nebukadnezar, kralj babilonski, je naložil svoji vojski trdo službo zoper Tir. Vsaka glava je oplešena in vsaka rama je oguljena; od Tira pa ni bilo nobenega plačila njemu in vojski njegovi za službo, ki jo je storil zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 19, 'Zatorej pravi tako Gospod Jehova: Glej, jaz dam Nebukadnezarju, kralju babilonskemu, deželo Egiptovsko, da odnese bogastvo njeno ter jo oropa in opleni, in to bode plačilo vojski njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 20, 'V povračilo, za katero je delal, sem mu dal deželo Egiptovsko, ker so delali zame, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 29, 21, 'Tisti dan storim, da zraste hiši Izraelovi rog, in tebi odprem usta sredi njih; in spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 1, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 2, 'Sin človečji, prorokuj in reci: Tako pravi Gospod Jehova: Tulite! Gorje tisti dan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 3, 'Kajti blizu je tisti dan; res, blizu je dan Gospodov, dan oblakov: čas poganov bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 4, 'In meč pride nad Egipt; in trepet bode v Etiopiji, ko bodo ranjeni padali v Egiptu in ko odpeljejo njegovo množico in bodo razdejana njegova podzidja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 5, 'Etiopija, Put in Lud in vse mešano ljudstvo in Kub in sinovi dežele zavezne padejo ž njimi vred pod mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 6, 'Tako pravi Gospod: Tudi tisti, ki podpirajo Egipt, padejo, in zgrudi se napuh moči njegove; od Migdola do Siene bodo v njem padali pod mečem, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 7, 'In bodo kot pustota sredi opustošenih dežel in njih mesta sredi med razdejanimi mesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 8, 'In spoznajo, da sem jaz Gospod, ko zanetim ogenj v Egiptu in bodo strti vsi pomočniki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 9, 'Tisti dan pojdejo poslanci izpred mene na ladjah, da prestrašijo brezskrbne Etiopce; in velik strah jih pretrese v dan egiptovski, zakaj, glej, prihaja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 10, 'Tako pravi Gospod Jehova: Storim tudi, da vzame konec hrup množice egiptovske po roki Nebukadnezarja, kralja babilonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 11, 'On in ljudstvo njegovo ž njim, silovitniki med narodi, bodo pripeljani, da pogubé deželo; in potegnejo meče svoje zoper Egipt ter napolnijo deželo z ubitimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 12, 'In posušim reke Nila in prodam deželo v roko hudobnežev in opustošim deželo in karkoli je v njej po roki tujcev. Jaz Gospod sem govoril to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 13, 'Tako pravi Gospod Jehova: Tudi uničim grde malike in odpravim ničeve podobe iz Nofa, in ne bode nobenega kneza več iz dežele Egiptovske; in pošljem strah v Egiptovsko deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 14, 'In opustošim Patros in ogenj zanetim v Zoanu in sodbe izvršim nad Tebami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 15, 'In izlijem jezo svojo nad Sin, trdnjavo egiptovsko, in množico iz Teb iztrebim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 16, 'In zanetim ogenj v Egiptu; Sin bo trepetal v strahu in Tebe bodo predrte, Nof pa dobi sovražnike po dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 17, 'Mladeniči v Avenu in Pibezetu padejo pod mečem, in drugi prebivalci pojdejo v ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 18, 'In v Tahpanhesu se zmrači dan, ko ondi polomim ižesa egiptovska in se v njem naredi konec napuhu njegove moči; oblaki ga pokrijejo, in njemu podložna mesta pojdejo v ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 19, 'In tako izvršim sodbe nad Egiptom; in spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 20, 'In zgodilo se je v enajstem letu, sedmi dan prvega meseca, da mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 21, 'Sin človečji, zlomil sem ramo Faraonu, kralju egiptovskemu; in glej, ni bila obvezana, da bi se uporabilo zdravilo, ni se ovila preveza, da se zaceli, da bi dobila moč in prijela meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 22, 'Zatorej pravi tako Gospod Jehova: Glej, jaz sem zoper Faraona, kralja egiptovskega, in zlomim obedve rami njegovi, zdravo in zlomljeno, in storim, da mu pade meč iz roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 23, 'In razkropim Egipčane med narode in jih razženem po deželah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 24, 'In okrepčam rami kralja babilonskega in denem meč svoj v roko njegovo; rami Faraonovi pa zlomim, da bo kakor prebodenec milo ječal pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 25, 'In okrepčam rami kralju babilonskemu, rami Faraonovi pa upadeta. In spoznajo, da sem jaz Gospod, ko denem meč svoj kralju babilonskemu v roko, in on ga potegne proti deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 30, 26, 'In razkropim Egipčane med narode ter jih raztresem po deželah; in spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 1, 'In zgodilo se je v enajstem letu, prvi dan tretjega meseca, da mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 2, 'Sin človečji, govori Faraonu, kralju egiptovskemu, in vsej množici njegovi: Komu si enak v velikosti svoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 3, 'Glej, Asur je bil ceder na Libanonu, z lepimi vejami, košat za senco in silno visok, in vrh njegov je segal med oblake.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 4, 'Vode so storile, da se je tako povzpel, globočina, da je visoko vzrastel: reke njene so tekle povsod okoli njegovih korenin in potoke svoje je izlivala do vseh dreves na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 5, 'Zato je vzrastel više nego vsa drevesa na polju in mladike njegove so se pomnožile ter veje njegove podaljšale vsled obilnih vod, ko se je razširjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 6, 'Vsi ptiči nebeški so gnezdili v njegovih vejah in vse zverine poljske so rodile pod njegovimi mladikami, in v senci njegovi so prebivali vsi veliki narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 7, 'In bil je prelep v velikosti svoji in ker je imel široko raztegnjene odrastke: kajti korenine njegove so bile ob obilih vodah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 8, 'Cedre na vrtu Božjem ga niso nadkriljevale, ciprese se niso mogle enačiti z vejami njegovimi in javori niso bili kakor mladike njegove; nobeno drevo na vrtu Božjem mu ni bilo enako v lepoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 9, 'Lepega sem ga naredil z množino odrastkov njegovih; in zavidala so mu vsa drevesa edenska, ki so bila na vrtu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 10, 'Zato je tako rekel Gospod Jehova: Ker si tako visoko vzrastel – da, vrh je iztezal tja med oblake in srce njegovo se je prevzelo zaradi visokosti njegove:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 11, 'zato ga dam v pest mogočniku med narodi, naj le ravna ž njim, kakor hoče; zaradi brezbožnosti njegove sem ga zavrgel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 12, 'In tujci, silovitniki med narodi, so ga posekali ter vrgli na tla: njegovi odrastki so popadali po gorah in po vseh dolinah in veje njegove so se polomile in obležale po vseh globinah dežele; in vsa zemeljska ljudstva so šla izpod sence njegove in se niso več zanj zmenila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 13, 'na podrti trup njegov so sedli vsi ptiči nebeški in po vejah njegovih čepé vse zverine zemlje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 14, 'da naj se ne povzdiguje nobeno drevo ob vodah zaradi visokosti svoje ter ne izteza vrha tja med oblake, da se tudi njih mogočneži ne zanašajo nase zaradi visokosti svoje, ker vsi pijejo vodo; zakaj vsi so izročeni smrti v spodnje kraje zemlje, sredi med sinove človeške, k njim, ki se pogrezajo v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 15, 'Tako pravi Gospod Jehova: V dan, ko je šel doli v pekel, sem napravil žalovanje; zagrnil sem globočino zaradi njega in ustavil njene reke, in velike vode so se zajezile; Libanonu pa sem velel žalovati po njem, in zaradi njega so omedlevala vsa drevesa na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 16, 'Storil sem, da so se od hrupa njegovega padca tresli narodi, ko sem ga pahnil doli v pekel k njim, ki so se pogreznili v jamo. In potolažila so se vsa drevesa Božja, vsa izbrana in najboljša drevesa libanonska, vsa, ki jih namaka voda, v spodnjih krajih zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 17, 'Tudi ona so šla ž njim doli v pekel k pobitim od meča, ki so kot njegovi pomočniki sedeli v senci njegovi med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 31, 18, 'Komu si enak v taki slavi in velikosti med drevesi edenskimi? A pahnjen boš z drevesi edenskimi v spodnje kraje zemlje, med neobrezanci boš ležal ž njimi, ki so pobiti z mečem. To je Faraon in vsa množica njegova, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 1, 'In zgodilo se je v dvanajstem letu, prvi dan dvanajstega meseca, da mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 2, 'Sin človečji, zapoj žalostinko nad Faraonom, kraljem egiptovskim, in mu reci: Mlademu levu med narodi si bil podoben; ali bil si kakor zmaj v morju in drl si po svojih rekah in motil vode z nogami svojimi in razrival njih reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 3, 'Tako pravi Gospod Jehova: Zato razpnem mrežo svojo nad teboj v zboru mnogih narodov, in izvlečejo te z mojim sakom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 4, 'In potegnem te na suho, vržem te na površje polja, in vse ptice nebeške posadim nate in zverine vse zemlje se bodo sitile od tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 5, 'In razmečem meso tvoje po gorah ter doline napolnim z mrlino tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 6, 'In deželo namočim tja do hribov z rekami krvi tvoje, in globine bodo napolnjene s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 7, 'In ko te ugasnem, zagrnem nebo in otemnim zvezde njegove; solnce pokrijem z oblaki in luna ne bo svetila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 8, 'Vse sveteče luči na nebu storim nad tabo črne in temo spravim nad deželo tvojo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 9, 'In užalostim mnogih ljudstev srce, ko razglasim padec tvoj med narodi po deželah, ki jih nisi poznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 10, 'In storim, da bo veliko ljudstev strmelo nad teboj, in njih kralji bodo silno prestrašeni zavoljo tebe, ko zavihtim meč svoj pred njimi; in trepetali bodo vsak trenotek, vsakdo za življenje svoje, v dan padca tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 11, 'Zakaj tako pravi Gospod Jehova: Pride nadte kralja babilonskega meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 12, 'Storim, da pade množica tvoja pod meči junakov, ki so vsi najbolj silovitni med narodi; in pokončajo napuh Egipta, in vsa množica njegova bo zatrta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 13, 'Pogubim tudi vso živino njegovo ob mnogih vodah, da jih ne bo več motila noga človeška, ne kalil parkelj živalski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 14, 'Tedaj storim, da se njih vode učistijo ter njih reke poteko kakor olje, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 15, 'Ko opustošim deželo Egiptovsko, ko izpraznim deželo vsega, česar je bila polna, ko udarim vse prebivalce njene, tedaj spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 16, 'To je žalostinka in s to bodo žalovali; hčere narodov jo bodo žalujoč pele; žalujoč jo bodo pele nad Egiptom in nad vso množico njegovo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 17, 'In zgodilo se je v dvanajstem letu, petnajsti dan meseca, da mi pride beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 18, 'Sin človečji, žaluj nad množico egiptovsko in pahni jo doli, njo in hčere slavnih narodov, v spodnje kraje zemlje k tistim, ki so padli v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 19, 'Koga nadkriljuješ v milini? Doli stópi in lezi z neobrezanci!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 20, 'Padejo naj sredi pobitih z mečem! Meč je že izročen; privlecite sem Egipt in vso množico njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 21, 'Mogočni izmed junakov bodo govorili o njem izsredi pekla s pomočniki njegovimi vred. Padli so doli, tam leže tisti neobrezanci, pobiti z mečem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 22, 'Tam je Asur in ves zbor njegov; okoli njega njih grobi: vsi ti so pobiti, padli so pod mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 23, 'Grobi njegovi so v najglobočji jami in zbor njegov je okrog groba njegovega. Vsi so pobiti, padli so pod mečem, ki so strah napravljali v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 24, 'Tam je Elam in vsa množica njegova okoli njegovega groba. Ti vsi so pobiti, padli so pod mečem, ki so neobrezani šli doli v spodnje kraje zemlje, ki so strah napravljali v deželi živečih; in nosijo sramoto svojo ž njimi, ki so šli doli v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 25, 'Sredi med pobitimi so mu napravili ležišče z vso množico njegovo; okoli njega so njih grobi; vsi ti, neobrezani, so z mečem pobiti. Ker so strah delali v deželi živečih, nosijo sramoto svojo ž njimi, ki so šli doli v jamo. Sredi med pobite je položen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 26, 'Tam je Mesek, Tubal in vsa množica njegova; okoli njega so njih grobi. Vsi ti, neobrezani, so z mečem pobiti, ker so strah delali v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 27, 'In ne leže pri junakih, ki so padli v starodavnih časih, ki so šli doli v pekel z bojnim orožjem in so jim položili pod glave njih meče; a njih krivice so nad njih kostmi, kajti v strah so bili ti junaki v deželi živečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 28, 'Tudi ti, Egipt, bodeš strt sredi neobrezancev, in ležal boš ž njimi, ki so pobiti z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 29, 'Tam je Edom, kralji njegovi in vsi knezi njegovi, ki so bili vkljub svoji hrabrosti položeni k pobitim z mečem; pri neobrezancih leže, pri njih, ki so šli doli v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 30, 'Tam so vsi knezi od severa in vsi Sidonci, ki so stopili doli k pobitim; osramočeni so vkljub grozi, ki je šla pred njih močjo, in leže neobrezani pri pobitih z mečem ter nosijo sramoto svojo ž njimi, ki so šli doli v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 31, 'Faraon jih bo videl in se potolaži nad vso množico svojo. Z mečem pobita sta Faraon in vsa vojska njegova, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 32, 32, 'Zakaj dopustil sem, da se je strah njegov razširjal v deželi živečih; ali položen bo sredi neobrezancev k pobitim od meča Faraon in vsa množica njegova, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 1, 'In prišla mi je beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 2, 'Sin človečji, govori ljudstva svojega sinovom ter jim reci: Če pošljem meč nad deželo, ljudstvo dežele pa vzame koga izmed sebe in ga sebi postavi za čuvaja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 3, 'in če ta, videč meč prihajati nad deželo, zatrobenta in posvari ljudstvo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 4, 'kdorkoli bi slišal trobente glas, a se ne bi dal posvariti, njega pobere prišli meč, in njegova kri bodi na glavi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 5, 'Glas trobente je slišal, pa se ni dal posvariti: njega kri bodi nad njim samim; kajti ko bi bil sprejel posvarilo bi si otel dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 6, 'Ako pa čuvaj vidi meč prihajati, a ne zatrobenta in ljudstvo ne bo posvarjeno, meč pa pride ter pobere koga izmed njih: ta bo vzet v krivici svoji, ali kri njegovo bom zahteval iz roke čuvajeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 7, 'Tebe torej, sin človečji, sem postavil hiši Izraelovi za čuvaja, da bi jih, čujoč besedo iz mojih ust, svaril v mojem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 8, 'Ako rečem brezbožnemu: Brezbožnik, moraš umreti! ti pa ne govoriš, da bi posvaril in odvrnil brezbožnega s poti njegove: tedaj umrje on, brezbožnik, zaradi krivice svoje, ali kri njegovo bom zahteval iz tvoje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 9, 'Ako pa posvariš brezbožnega zavoljo poti njegove, da naj se obrne od nje, pa se ne obrne od poti svoje, on umrje zavoljo krivice svoje, ti pa si otel dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 10, 'Ti torej, sin človečji, govóri družini Izraelovi: Tako govorite in pravite: Prestopki naši in grehi naši leže na nas, in mi ginemo v njih; kako bi neki mogli živeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 11, 'Reci jim: Kakor res živim, govori Gospod Jehova, nikakor mi ni po volji smrt brezbožnikova, temuč da se brezbožnik obrne od svojega pota in živi. Obrnite se, obrnite se od hudobnih potov svojih! ker čemu bi hoteli mreti, o družina Izraelova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 12, 'Ti pa, sin človečji, govori ljudstva svojega sinovom: Pravičnost pravičnega ga ne reši v dan, ko se pregreši; in vsled krivičnosti svoje ne pade brezbožnik v dan, ko se izpreobrne od krivičnosti; pravični pa ne bo mogel živeti po pravičnosti svoji v dan, ko bo grešil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 13, 'Ko rečem pravičnemu, da bo gotovo živel, pa se zanaša na pravičnost svojo in počenja krivičnost: tedaj se ne bo spominjalo nobeno iz pravičnih del njegovih, temuč zaradi krivičnosti svoje, ki jo je storil, mora umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 14, 'Ako pa rečem brezbožnemu: Moraš umreti! in se izpreobrne od greha svojega in streže pravici in pravičnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 15, 'tako da povrne zastavo, kar je po sili vzel, prinese nazaj, ravna po postavah življenja, ne delajoč nič krivičnega; gotovo bo živel, ne umrje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 16, 'nobeden iz grehov njegovih, ki jih je zagrešil, se mu ne bo spominjal; pravici in pravičnosti je stregel: gotovo bo živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 17, 'Toda ljudstva tvojega sinovi pravijo: Ni ravna pot Gospodova! ko vendar njih pot ni ravna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 18, 'Ko se odvrne pravični od pravičnosti svoje in počenja krivičnost, umrje zategadelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 19, 'In ko se odvrne brezbožni od krivičnosti svoje in streže pravici in pravičnosti, bo živel zaradi tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 20, 'A vi vendar pravite: Ni ravna pot Gospodova. Vsakega izmed vas bom sodil po potih njegovih, o družina Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 21, 'In zgodilo se je v dvanajstem letu našega ujetništva, peti dan desetega meseca, da pride k meni ubežnik iz Jeruzalema in reče: Mesto je premagano!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 22, 'Gospodova roka pa je prišla nadme zvečer, preden je ubežnik prišel; in odprl mi je usta, dokler ni prišel oni k meni zjutraj, in tako so bila usta moja odprta in nisem več molčal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 23, 'In pride mi beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 24, 'Sin človečji, prebivalci tistih razvalin po zemlji Izraelovi govore in pravijo: Abraham je bil edinec in je dobil to deželo v posest; nas je pa veliko, nam je dežela dana v posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 25, 'Zatorej jim reci: Tako pravi Gospod Jehova: Jeste meso s krvjo in obračate oči h grdim malikom svojim ter prelivate kri, in vi naj bi posedli deželo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 26, 'Zanašate se na svoj meč, gnusobe počenjate in oskrunjate ženo drug drugemu, in vi naj bi posedli deželo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 27, 'Tole jim povej: Tako pravi Gospod Jehova: Kakor res živim, kateri bivajo v razvalinah, padejo pod mečem; in kdor je na polju, tega dam divjim zverinam v žrtje, in kateri so v trdnjavah in votlinah, pomrjejo za kugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 28, 'In storim deželo v puščavo in pustinjo, da preneha napuh moči njene; in opustošene bodo gore Izraelove, da nihče ne bo hodil po njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 29, 'Tedaj spoznajo, da sem jaz Gospod, ko storim deželo v puščavo in pustinjo zaradi vseh njih gnusob, ki so jih počenjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 30, 'Kar se pa tiče tebe, sin človečji, ljudstva tvojega sinovi se pogovarjajo o tebi ob zidovih in med hišnimi vrati in drug pravi drugemu, brat bratu: Pojdiva vendar in poslušajva, kakšna je beseda, ki prihaja od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 31, 'In hodijo k tebi, kakor ko se ljudstvo shaja, in sedé pred teboj kakor ljudstvo moje in poslušajo besede tvoje, pa ne delajo po njih; kajti ljubeznivo govore s svojimi usti, njih srce se pa žene za njih dobičkom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 32, 'In glej, ti si jim kakor pesem o ljubezni, kakor če kdo zna lepo peti in sladko gosti: poslušajo besede tvoje, a ne delajo po njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 33, 33, 'In kadar pride to (glej, že prihaja!), tedaj spoznajo, da je bil prorok med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 1, 'In prišla mi je beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 2, 'Sin človečji, prorokuj zoper pastirje Izraelove, prorokuj in reci tistim pastirjem: Tako pravi Gospod Jehova: Gorje pastirjem Izraelovim, ki pasejo sami sebe! Ni li pastirjem pasti črede?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 3, 'Vi pa jeste tolstino ter se oblačite z volno, pitance koljete; črede ne pasete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 4, 'Slabotnih niste krepčali, bolnih niste zdravili, ranjenih niste obvezovali; njih, ki so zašle, niste nazaj pripeljavali; kar je bilo izgubljenega, niste iskali, temuč trdo in nemilo ste jim gospodovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 5, 'In ovce so se razkropile, ker jim ni bilo pastirja, in so postale za jed vsem zverinam na polju, in bile so razkropljene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 6, 'Moje ovce tavajo po vseh gorah in po vseh visokih hribih, in po vsem površju zemlje so razkropljene ovce moje, in ni ga, ki bi po njih vprašal ali jih iskal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 7, 'Zatorej, pastirji, čujte besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 8, 'Kakor res živim, govori Gospod Jehova: Zato ker so bile moje ovce izročene plenjenju in ker so bile v jed vsem zverinam na polju, kajti ni bilo pastirja in moji pastirji ne vprašujejo po ovcah mojih, marveč pasejo sami sebe, a ne pasejo ovac mojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 9, 'zato, pastirji, čujte besedo Gospodovo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 10, 'Tako pravi Gospod Jehova: Glej, jaz sem zoper tiste pastirje in zahteval bom ovce iz njih rok in jih odstavim, da ne bodo več pasli ovac, tudi ne bodo več pasli sami sebe, in otmem ovce svoje iz njih grla, da jim ne bodo več v užitek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 11, 'Zakaj tako pravi Gospod Jehova: Glej, jaz sam, jaz poiščem ovce svoje in jih vzamem v svojo skrb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 12, 'Kakor pastir skrbi za ovce svoje v dan, kadar je med razkropljenimi ovcami svojimi, tako bom skrbel za ovce svoje in jih otmem iz vseh krajev, kamor so se porazgubile oblačnega in temnega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 13, 'In pripeljem jih izmed ljudstev ter jih zberem po deželah in jih privedem v njih zemljo ter jih bom pasel po gorah Izraelovih, po dolinah in ob vseh selih dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 14, 'Na dobri paši jih bom pasel in po visokih gorah Izraelovih bodo njih pašniki; tam, na gorah Izraelovih, bodo ležale v pokojnih stanih in uživale tolsto pašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 15, 'Jaz sam bom pasel ovce svoje in jaz jih vodil počivat, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 16, 'Izgubljene poiščem, razgnane pripeljem nazaj, ranjene obvežem in bolne pokrepčam; kar je pa debelo in močno zatrem; pasel jih bom, kakor je prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 17, 'Vi torej, črede moje – tako pravi Gospod Jehova: Glejte, sodil bom med ovco in ovco, med ovni in kozli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 18, 'Je li vam malo, da najboljšo pašo popasete, treba li, da še poteptate ostanke paše? malo li, da pijete čisto vodo, da še kalite ostanek z nogami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 19, 'In mojim ovcam bodi za pašo, kar ste poteptali, in v pijačo, kar ste skalili z nogami svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 20, 'Zato pravi tako Gospod Jehova: Glejte, jaz sam bom sodil med debelimi in medlimi ovcami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 21, 'Zato ker z boki in ramami odrivate in z rogovi bodete vse slabotne, dokler jih ne razkropite:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 22, 'zato rešim ovce svoje, da vam ne bodo več v plen; in sodil bom med ovco in ovco.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 23, 'in obudim jim Pastirja edinega, ki naj jih pase, hlapca svojega Davida: ta jih bo pasel in jim bode pastir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 24, 'In jaz, Jehova, jim bodem Bog in hlapec moj David bode knez sredi njih. Jaz, Gospod, sem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 25, 'In sklenem ž njimi zavezo miru in iztrebim hude zveri iz dežele, da bodo varno prebivale v puščavi in spale v gozdih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 26, 'In storim nje in kar je okoli hriba mojega v blagoslov in dam, da bo dež prihajal ob svojem času, dež blagoslova bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 27, 'In drevje na polju bo rodilo sad svoj in zemlja bo dajala prirastke svoje, in varni bodo v svoji zemlji. In spoznajo, da sem jaz Gospod, ko zlomim palice njih jarma ter jih otmem iz roke tistih, ki so si jih usužnjili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 28, 'In ne bodo več v plen poganom, tudi zveri zemlje jih ne bodo žrle, ampak varno bodo prebivali in nihče jih ne bo plašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 29, 'In obudim jim saditev v sloveče ime, in ne bo jih več morila lakota v deželi, tudi ne bodo več trpeli zasramovanja narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 30, 'In spoznajo, da sem jaz Gospod, njih Bog, ž njimi ter da so oni, hiša Izraelova, moje ljudstvo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 34, 31, 'Ve pa, črede moje, ovce paše moje, ste ljudje, in jaz sem Bog vaš, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 1, 'Še mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 2, 'Sin človečji, obrni obličje proti gori Seiru in prorokuj zoper njo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 3, 'ter ji reci: Tako pravi Gospod Jehova: Glej, jaz sem zoper tebe, o gora Seir, in iztegnem roko svojo nadte in te storim v puščavo in pustinjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 4, 'Mesta tvoja naredim pusta in sama boš opustošena. In spoznaš, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 5, 'Ker si neprestano gojila sovraštvo in izročila sinove Izraelove oblasti meča ob času njih stiske, ob času zadnje krivice:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 6, 'zato, kakor res živim, govori Gospod Jehova, te naredim v kri, in kri te bo preganjala; ker nisi sovražila krvi, te bo kri preganjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 7, 'Naredim torej goro Seir v samoto in pustinjo in potrebim ž nje njega, ki prihaja, in njega, ki odhaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 8, 'In gore Edomove napolnim s pobitimi njegovimi; na hribih tvojih in po tvojih dolinah in globinah popadajo pomorjeni z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 9, 'V večne pustinje te naredim, in v mestih tvojih se ne bo več prebivalo. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 10, 'Ker si rekel: Moja bodeta ta dva naroda in ti dve deželi, in vzemimo si to v posest, čeprav je bil Gospod tam:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 11, 'zato, kakor resnično živim, govori Gospod Jehova, bom ravnal po jezi in zavisti tvoji, ki si jo izkazal proti njima vsled sovraštva svojega; in storim, da me spoznajo, kadar te bom sodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 12, 'In zveš, da sem jaz, Gospod, slišal vse sramotitve, ki si jih govoril zoper gore Izraelove, rekoč: Opustošene so, nam so dane v požrtje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 13, 'In veličali ste se proti meni z usti svojimi ter množili zoper mene besede svoje; jaz sem slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 14, 'Tako pravi Gospod Jehova: Kadar se bo vsa zemlja veselila, ti pripravim opustošenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 35, 15, 'Kakor si se veselila dedne posesti doma Izraelovega, ker je bila opustošena, prav tako storim tebi: puščava postaneš, o gora Seir, in ves Edom sploh! In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 1, 'Ti pa, sin človečji, prorokuj o gorah Izraelovih in reci: Gore Izraelove, čujte besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 2, 'Tako pravi Gospod Jehova: Ker govori sovražnik o vas: Aha! In: Te večne višave nam so dane v posest!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 3, 'zato prorokuj in reci: Tako pravi Gospod Jehova: Zato, prav zato, ker so vas pustošili in požirali od vseh strani, da postanete posest ostanku poganskih narodov, in ste prišle v govorico jezikom in v slab glas pri ljudeh:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 4, 'zato, o gore Izraelove, čujte besedo Gospoda Jehove: Tako pravi Gospod Jehova goram in hribom, globinam in dolinam, pustim razvalinam in mestom zapuščenim, ki so postala plen in zasmeh ostanku poganskih narodov, ki so okoli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 5, 'zatorej pravi tako Gospod Jehova: Resnično, v ognju gorečnosti svoje sem govoril zoper ostanek tistih narodov in zoper ves Edom, ki so določili deželo mojo sebi v posest z vso radostjo svojega srca in z vsem zaničevanjem duše, da bi jo izpraznili in oplenili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 6, 'Zato prorokuj o zemlji Izraelovi in reci goram in hribom, globinam in dolinam: Tako pravi Gospod Jehova: Glejte, v gorečnosti svoji in v jezi svoji sem govoril, ker ste trpeli zasrambo poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 7, 'Zato pravi tako Gospod Jehova: Jaz sem povzdignil roko svojo, rekoč: Gotovo morajo pogani, ki so okoli vas, trpeti zasrambo svojo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 8, 'Ali ve, gore Izraelove, poganjajte svoje mladike in rodite svoj sad ljudstvu mojemu, Izraelu, kajti blizu so, da pridejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 9, 'Zakaj, glejte, jaz sem za vas in se obrnem k vam, da vas bodo obdelovali in obsevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 10, 'In pomnožim na vas ljudi, vso družino Izraelovo, vso vkup; in v mestih se bo prebivalo in razvaline se bodo nanovo sezidale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 11, 'In pomnožim na vas ljudi in živino, in bodo se množili ter bodo rodovitni, in storim, da boste naseljene kakor v prejšnjih vaših časih, in obsujem vas z dobrotami bolj nego v vašem začetku. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 12, 'In storim, da bodo ljudje, ljudstvo moje Izraelovo, po vas hodili in vas imeli v lasti, in bodete jim v dediščino ter jih nikdar več ne napravite brez zaroda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 13, 'Tako pravi Gospod Jehova: Zato ker vam pravijo: Ti, dežela, žreš ljudi in pripravljaš narod svoj ob otroke –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 14, 'zato ne boš več žrla ljudi, tudi ne pripravljala ob otroke naroda svojega, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 15, 'Tudi ti ne dam več slišati zasrambe poganov in roganja ljudstev ne boš več trpela in naroda svojega ne boš več spravljala v spotiko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 16, 'Še mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 17, 'Sin človečji, ko je prebivala družina Izraelova v svoji deželi, so jo ognušali s svojimi dejanjem in ravnanjem; njih dejanje je bilo pred menoj kakor nečistost žene v nje bolezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 18, 'Zato sem izlil jezo svojo nadnje zavoljo krvi, ki so jo prelili v deželi, in ker so jo ognusili z grdimi maliki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 19, 'In razkropil sem jih med narode in bili so raztreseni po deželah: po njih dejanju in ravnanju sem jih sodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 20, 'In ko so prišli k narodom, kamorkoli so dospeli, so oskrunili ime svetosti moje, ker se je pravilo o njih: Ljudstvo Gospodovo je in iz dežele njegove so prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 21, 'A meni se smili imena svetosti moje, ki ga je oskrunila družina Izraelova, kamorkoli so prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 22, 'Zato govóri družini Izraelovi: Tako pravi Gospod Jehova: Ne storim tega zaradi vas, o družina Izraelova, marveč zaradi imena svetosti svoje, ki ste ga oskrunili med narodi, kamorkoli ste prišli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 23, 'Posvetim zopet svoje veliko ime, ki je bilo oskrunjeno med narodi, ki ste ga vi oskrunili sredi njih. In spoznajo narodi, da sem jaz Gospod, govori Gospod Jehova, ko se izkažem svetega na vas pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 24, 'Vzamem vas namreč izmed narodov in vas zberem iz vseh dežel in pripeljem v deželo vašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 25, 'In pokropim vas s čisto vodo, da bodete čisti: vseh nečistot vaših in vseh grdih malikov vaših vas očistim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 26, 'In dam vam novo srce in novega duha denem v vas, in vzamem kameneno srce iz telesa vašega in dam vam meseno srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 27, 'In vdahnem v vas duha svojega in storim, da boste živeli po mojih postavah ter hranili in izpolnjevali sodbe moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 28, 'In prebivali boste v deželi, ki sem jo dal očetom vašim, in bodete mi ljudstvo in jaz vam bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 29, 'In oprostim vas vseh nečistosti vaših; in pokličem žita, ter ga razmnožim, in lakote vam več ne naložim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 30, 'Tudi pomnožim sad dreves in pridelke polja, da bi vas ne zadel več posmeh med narodi zavoljo lakote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 31, 'Tedaj se spomnite hudobnih potov in dejanj svojih, ki niso bila dobra, in sami sebi se boste studili zavoljo krivic in gnusob svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 32, 'Ne zaradi vas storim to, pravi Gospod Jehova, pomnite to! sramujte se in rdečica naj vas oblije zavoljo dejanj vaših, o družina Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 33, 'Tako pravi Gospod Jehova: Tisti dan, ko vas očistim vseh krivic vaših, storim, da se bo prebivalo v mestih vaših in se bodo nanovo sezidale razvaline.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 34, 'In dežela, ki je bila opustošena, se bo obdelovala; ne bo več puščava pred očmi slehernega, ki gre mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 35, 'In bodo pravili: Ta dežela, ki je bila opustošena, je postala kakor vrt v Edenu, in opustošena in zapuščena in porušena mesta so utrjena ter prebivajo v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 36, 'Tedaj spoznajo narodi, ki preostanejo okoli vas, da jaz, Gospod, gradim, kar je porušeno, in obsajam, kar je opustošeno. Jaz, Gospod, sem govoril, jaz tudi storim to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 37, 'Tako pravi Gospod Jehova: Tudi še v tem se dam izprositi družini Izraelovi, da jim to izpolnim: Pomnožil jih bom z ljudmi kakor čredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 36, 38, 'Kakor sveta čreda, kakor čreda Jeruzalema ob njegovih praznikih, tako bodo mesta, prej opustošena, polna čred ljudi. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 1, 'Roka Gospodova je bila nad menoj, in peljal me je ven v duhu Gospodovem in me je postavil sredi doline, in ta je bila polna kosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 2, 'In mi je velel iti mimo njih kroginkrog; in glej, bilo jih je silno veliko po dolini, in glej, bile so silno usehle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 3, 'In mi reče: Sin človečji, bodo li te kosti oživele? In odgovorim: Gospod Jehova, ti veš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 4, 'Tedaj mi veli: Prorokuj nad temi kostmi in jim reci: O kosti usehle, čujte besedo Gospodovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 5, 'Tako pravi Gospod Jehova tem kostem: Glejte, jaz pošljem duha v vas, da oživite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 6, 'S kitami vas obložim in storim, da zraste meso na vas, in s kožo vas odenem ter dam duha v vas, in oživite. In spoznate, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 7, 'In prorokoval sem, kakor mi je bilo ukazano. In nastane šumenje, ko prorokujem, in glej, gibanje: kosti rinejo k sebi, kost h kosti svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 8, 'In gledam, in glej: kite so bile na njih in meso je zraslo in koža jih je odela povrhu; ali duha ni bilo v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 9, 'Tedaj mi veli: Prorokuj duhu, prorokuj, sin človečji, in reci duhu: Tako pravi Gospod Jehova: Od štirih vetrov pridi, o duh, in dihni v te pobite, da ožive!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 10, 'In prorokoval sem, kakor mi je ukazal; in prišel je duh vanje. In oživele so in stopile pokonci – prav silno velika vojska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 11, 'In mi reče: Sin človečji, te kosti so vsa družina Izraelova. Glej, oni govore: Kosti naše so usehle in upanje naše je izginilo; izgubljeni smo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 12, 'Zato prorokuj in jim reci: Tako pravi Gospod Jehova: Glejte, jaz odprem grobe vaše in vas, ljudstvo svoje, izpeljem iz grobov vaših in vas privedem v zemljo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 13, 'In spoznate, da sem jaz Gospod, kadar odprem grobe vaše ter vas izpeljem iz grobov vaših, ljudstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 14, 'In dam duha svojega v vas, da živite, in vas naselim v vaši zemlji. In zvedeli boste, da sem jaz Gospod rekel in izvršil to, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 15, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 16, 'In ti, sin človečji, si vzemi les ter zapiši nanj: Judi in sinovom Izraelovim, tovarišem njegovim. In vzemi drug les in zapiši nanj: Jožefu, les Efraimov in vse družine Izraelove, tovarišev njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 17, 'In ju združi drug z drugim, sebi v eno drevo, da bodeta zedinjena v roki tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 18, 'In kadar te ogovore ljudstva tvojega sinovi, rekoč: Ali nam ne naznaniš, kaj ti pomeni to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 19, 'jim reci: Tako pravi Gospod Jehova: Glejte, jaz vzamem les Jožefov, ki je v roki Efraimovi, in rodove Izraelove, tovariše njegove, in jih pridenem njemu, lesu Judovemu, in jih storim v eno drevo, da bodo zedinjeni v roki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 20, 'Lesova pa, na katera si pisal, imej v roki pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 21, 'In jim govori: Tako pravi Gospod Jehova: Glejte, jaz vzamem sinove Izraelove izmed narodov, kamorkoli so prišli, in jih zberem z vseh strani ter jih pripeljem v njih zemljo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 22, 'in jih združim v eno ljudstvo v deželi, na gorah Izraelovih in en kralj bo vsem kraljeval in ne bodo več v dva naroda in se ne bodo delili več v dve kraljestvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 23, 'Tudi se ne bodo več oskrunjali z grdimi maliki in z ostudami svojimi, ne s katerokoli iz pregreh svojih; in rešim jih iz vseh prebivališč, v katerih so grešili, ter jih očistim: in bodo mi ljudstvo in jaz jim bodem Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 24, 'In moj hlapec David bode kralj nad njimi in vsem bode eden pastir; in živeli bodo po sodbah mojih in postave moje bodo hranili in jih izpolnjevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 25, 'In prebivali bodo v deželi, ki sem jo dal Jakobu, hlapcu svojemu, ki so v njej prebivali očetje vaši; in domovali bodo v njej oni, njih sinovi in njih sinov otroci vekomaj; in moj hlapec David jim bode knez na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 26, 'In sklenem ž njimi zavezo miru, večna zaveza jim bode, in jih naselim ter jim pomnožim in postavim svetišče svoje v njih sredi na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 27, 'In prebivališče moje bode nad njimi, in bodem jim Bog in oni mi bodo ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 37, 28, 'In narodi spoznajo, da sem jaz Gospod, ki posvečujem Izraela, ko bode svetišče moje v njih sredi na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 1, 'In beseda Gospodova mi je prišla, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 2, 'Sin človečji, obrni obličje proti Gogu v deželi Magogovi, knezu v Rosu, Meseku in Tubalu, ter prorokuj zoper njega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 3, 'in reci: Tako pravi Gospod Jehova: Glej, jaz sem zoper tebe, o Gog, knez v Rosu, Meseku in Tubalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 4, 'In vodil te bom in ti dejal obroček v čeljusti; in popeljem te ven in vso vojsko tvojo, konje in konjike, vse sijajno oblečene, veliko krdelo z majhnimi in velikimi ščiti, ki vsi znajo sukati meč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 5, 'Perzijce, Etiopce in Puta ž njimi, vse s ščiti in čeladami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 6, 'Gomerja in vse trume njegove, družino Togarmovo na najskrajnejšem severu in vse trume njegove: mnogo ljudstev bode s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 7, 'Bodi pripravljen in pripravi si vse, ti in vsa krdela tvoja, ki so se zbrala k tebi, in bodi jim načelnik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 8, 'Čez veliko dni boš obiskan; v poslednjih letih prideš v deželo, katere ljudstvo, zbrano iz mnogih ljudstev, se je rešilo meča, na gore Izraelove, ki so bile vedno opustošene; ali odpeljano je izmed ljudstev, in varno prebivajo vsi, kar jih je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 9, 'In pojdeš gori, pridreviš kakor nevihta, bodeš kakor oblak, da pokriješ deželo, ti in vse trume tvoje in mnogo ljudstev s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 10, 'Tako pravi Gospod Jehova: In zgodi se tisti dan, da boš preudarjal v srcu svojem in snoval hude naklepe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 11, 'ter porečeš: Pojdem gori v deželo z neobzidanimi vasmi, planem na pokojne, ki brezskrbno prebivajo vsi, ki stanujejo brez zidov in nimajo zapahov, ne vrat:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 12, 'da zgrabiš rop in dobiš plen, da roko nameriš zoper razvaline, ki so jih zopet obljudili, in zoper ljudstvo, ki je zbrano izmed narodov, ki si je pridobilo blaga in imovine, ki prebiva v sredini zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 13, 'Saba in Dedan in trgovci iz Tarsisa in vsi njih mogočniki ti porečejo: Prihajaš, da pograbiš rop? si li zbral krdela svoja, da vzameš plen? da odneseš srebro in zlato, pobereš blago in imovino, da dobiš velik plen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 14, 'Zatorej, sin človečji, prorokuj in reci Gogu: Tako pravi Gospod Jehova: Tisti dan, ko bo ljudstvo moje brezskrbno prebivalo, ne zveš li tega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 15, 'In prideš iz svojega kraja, od najskrajnejšega severa, ti in mnoga ljudstva s teboj, na konjih jezdeč vsi, veliko krdelo in mnogoštevilna vojska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 16, 'In pojdeš gori zoper ljudstvo moje, Izraela, kakor oblak, da pokriješ deželo. V poslednjih dneh se zgodi, da te pripeljem zoper deželo svojo, da bi me spoznali narodi, ko se izkažem svetega nad teboj, o Gog, pred njih očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 17, 'Tako pravi Gospod Jehova: Nisi li tisti, o katerem sem govoril v nekdanjih časih po služabnikih svojih, prorokih Izraelovih, ki so prorokovali v onih časih po mnoga leta, da te pripeljem zoper nje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 18, 'Zgodi se pa tisti dan, v dan, ko pride Gog v zemljo Izraelovo, govori Gospod Jehova, da vzplamti togota moja v srdu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 19, 'Kajti v gorečnosti svoji, v ognju srda svojega sem govoril: Res, tisti dan pride velik potres na zemljo Izraelovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 20, 'In trepetale bodo pred obličjem mojim ribe v morju in ptice nebeške in zveri na polju in vsa laznina, ki se giblje na zemlji, in vsi ljudje, kar jih je na površju zemlje; in gore se razvalein strme višave popadajo in vsak zid se poruši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 21, 'In pokličem meč zoper njega na vse gore svoje, govori Gospod Jehova; vsakterega meč bo obrnjen proti bratu njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 22, 'In izvršim sodbo nad njim s kugo in s krvjo; in poplavljajočo ploho in točo, ogenj in žveplo bom dežil na njega in na trume njegove in na narode mnoge, ki so ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 38, 23, 'In izkažem se velikega in svetega ter se dam spoznati očem mnogih narodov. In vedeli bodo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 1, 'Ti pa, sin človečji, prorokuj zoper Goga in reci: Tako pravi Gospod Jehova: Glej, jaz sem zoper tebe, o Gog, knez v Rosu, Meseku in Tubalu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 2, 'In vodil te bom in te pripeljal in naredim, da prideš od najskrajnejšega severa, in te privedem na gore Izraelove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 3, 'in izbijem ti lok iz leve roke ter storim, da padejo pšice iz desnice tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 4, 'Na gorah Izraelovih padeš ti in vse trume tvoje in vsa ljudstva, ki so s teboj; dam te v žrtje ropnim pticam, okriljencem vsake vrste in poljskim zverinam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 5, 'Na širnem polju padeš, kajti jaz sem to rekel, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 6, 'In pošljem ogenj nad Magoga in nad nje, ki prebivajo varno v primorjih. In spoznajo, da sem jaz Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 7, 'In znano storim ime svetosti svoje med ljudstvom svojim, Izraelom, in ne dopustim, da bi se dalje onesvečevalo ime svetosti moje. In narodi spoznajo, da sem jaz Gospod, Sveti v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 8, 'Glej, prihaja in zgodi se to, govori Gospod Jehova; to je dan, ki sem o njem govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 9, 'In prebivalci v mestih Izraelovih pridejo ven in zanetijo ogenj. In kurili bodo z orožjem in s ščiti malimi in velikimi, z loki in pšicami in s kiji in sulicami, in sedem let jih bodo žgali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 10, 'da jim ne bo treba hoditi po drva na polje, ne jih po gozdih sekati, zakaj z orožjem bodo netili ogenj. In ropali bodo nje, katerim so bili v rop, in plenili bodo svoje plenitelje, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 11, 'In zgodi se tisti dan, da dam Gogu kraj, kjer bo njegovo grobišče: dolino popotnikov, ob sprednji strani morja; in to zagradi pot tod potujočim; in ondi pokopljejo Goga in vso množico njegovo ter jo bodo imenovali: Dolina množice Gogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 12, 'In družina Izraelova jo bo pokopavala, da se očisti dežela, sedem mesecev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 13, 'in vse ljudstvo dežele bo pokopavalo, in to jim bode v sloveče ime v dan, ko bom oslavljen, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 14, 'In odbero stanovitne može, ki naj hodijo četoma po deželi pokopavat nje, ki preostanejo na površju zemlje, da jo očistijo; ko mine sedem mesecev, jo bodo preiskovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 15, 'In hodili bodo povsod po deželi, in če kdo zagleda človeško kost, postavijo pri njej znamenje, dokler je pogrebniki ne pokopljejo v Dolini množice Gogove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 16, 'Tudi se bo neko mesto ondi imenovalo Množica. In tako očistijo deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 17, 'In ti, sin človečji, tako pravi Gospod Jehova: Véli pticam vsake vrste in vsem zverinam na polju: Zberite se in pridite! Snidite se z vseh strani h klalni daritvi moji, ki vam jo zakoljem, k veliki klalščini na gorah Izraelovih; jejte meso in pijte kri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 18, 'Jedle boste meso junakov in pile kri zemeljskih knezov, ovnov, jagnjet, kozlov in juncev, ki so bili v Basanu pitani vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 19, 'In jedle boste tolstino dositega in pile kri do pijanosti od moje klalščine, ki sem jo zaklal za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 20, 'In nasitite se pri mizi moji konj in konjikov, junakov in vsakovrstnih vojščakov, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 21, 'In izkažem slavo svojo med narodi, in videli bodo vsi narodi sodbo mojo, ki sem jo izvršil, in roko mojo, ki sem jo položil nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 22, 'In od tistega dne in poslej bo vedela družina Izraelova, da sem jaz, Gospod, njih Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 23, 'Narodi pa bodo vedeli, da je šla družina Izraelova v ujetništvo zaradi krivice svoje, ker so mi bili nezvesti in sem jim skril obličje svoje in jih dal v pest njih zatiralcem, da so padli pod mečem vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 24, 'Po njih nečistosti in po njih prestopkih sem ravnal ž njimi in jim skril obličje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 25, 'Zatorej pravi tako Gospod Jehova: Sedaj pripeljem nazaj ujetništvo Jakobovo ter se usmilim vse hiše Izraelove in bom gorel za ime svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 26, 'In nosili bodo sramoto svojo in vso nezvestobo svojo, s katero so se mi izneverili, kadar bodo na varnem prebivali v zemlji svoji in jih nihče ne bo plašil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 27, 'ko jih nazaj pripeljem iz ljudstev ter jih zberem iz dežel njih sovražnikov in se izkažem svetega nad njimi pred očmi mnogih narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 28, 'In v tem spoznajo, da sem jaz, Gospod, njih Bog: da sem jih odpeljal v ujetništvo med narode, pa jih zopet zberem v njih deželo in nobenega izmed njih ne pustim v tujini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 39, 29, 'In ne bom jim nikdar več skril obličja svojega, kajti izlil sem duha svojega na družino Izraelovo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 1, 'V petindvajsetem letu našega ujetništva, v začetku leta, deseti dan meseca, v štirinajstem letu potem, ko je bilo mesto premagano, tisti dan je bila roka Gospodova nad menoj in me je pripeljal tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 2, 'V prikaznih Božjih me je pripeljal v deželo Izraelovo in me spustil na silno visoko goro, in na njej, proti jugu, je bilo kakor stavba mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 3, 'In ko me je pripeljal tja, glej, bil je tam mož, čigar podoba je bila kakor podoba brona, in v roki njegovi vrvica iz prediva in merilna palica; in stal je med vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 4, 'In tisti mož me ogovori: Sin človečji, glej z očmi svojimi in z ušesi poslušaj ter si vtisni v srce vse, kar ti pokažem; zakaj da ti to pokažem, zato si pripeljan semkaj. Oznani družini Izraelovi vse, karkoli vidiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 5, 'In glej, zid je bil zunaj hiše kroginkrog in v roki moževi merilna palica, šest komolcev dolga, katerih vsak je imel komolec in dlan. In meril je širjavo stavbe: eno palico, in višavo: eno palico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 6, 'Nato je šel k vratom, ki gledajo proti vzhodu, in stopil gori po njih stopnicah. In meril je prag pod vrati: eno palico širjave, in sicer prvi prag eno palico širjave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 7, 'In vsaka stražnica je bila eno palico dolga in eno palico široka; med stražnicami pa je bilo pet komolcev prostora; in prag pod vrati poleg vratne veže proti hiši je imel eno palico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 8, 'Meril je tudi vratno vežo proti hiši: eno palico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 9, 'Potem je meril vratno vežo: osem komolcev, in njene opore: dva komolca debele; in vratna veža je bila proti hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 10, 'In stražnice vrat proti vzhodu so bile tri na tej in tri na oni strani; isto mero so imele vse tri in isto mero opore na tej in na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 11, 'In meril je širjavo odprtine med vrati: deset komolcev, dolgost hodišča v vratih: trinajst komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 12, 'In prostora pred stražnicami je en komolec na tej strani in en komolec prostora na oni strani; stražnice pa so bile po šest komolcev na tej in na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 13, 'In meril je vrata od strehe ene stražnice do strehe druge: petindvajset komolcev širjave, duri proti durim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 14, 'In naredil je opore, šestdeset komolcev, in na oporah je slonel preddvor, vrata okoliinokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 15, 'In od pročelja vhodnih vrat do pročelja veže notranjih vrat je bilo petdeset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 16, 'In okna, znotraj široka, zunaj ozka, so bila na stražnicah in na njih oporah, proti notranjščini vrat, vseokoli, in enako na stenskih napustkih, in tako so bila okna okoli navznoter; in na oporah so bile palme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 17, 'Tedaj me je peljal na zunanje dvorišče, in glej, tu so bili hrami in kamenat tlak kroginkrog po dvorišču; trideset hramov je bilo na kamenatem tlaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 18, 'In kamenat tlak je bil ob straneh vrat, primerno dolžini vrat, namreč nižji kamenat tlak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 19, 'In meril je širjavo od pročelja vrat pri nižjem dvorišču do čela notranjega dvorišča odzunaj, sto komolcev, enako na vzhodni in na severni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 20, 'In vrata, ki so gledala proti severu, pri zunanjem dvorišču: meril je njih dolžino in njih širjavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 21, 'in njih stražnic je bilo troje na tej in troje na oni strani; in njih opore in njih stenski napustki so bili iste mere kot prvih vrat: petdeset komolcev njih dolžina in petindvajset komolcev njih širjava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 22, 'In njih okna in njih stenski napustki in njih palme so bile iste mere kakor pri vratih proti vzhodu; in po sedmih stopnicah se je hodilo gori, in njih stenski napustki so bili pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 23, 'In bila so vrata do notranjega dvorišča nasproti drugim vratom, na severu in na vzhodu. In meril je od vrat do vrat sto komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 24, 'In peljal me je proti jugu. In glej, vrata so bila proti jugu, in meril je njih opore in njih stenske napustke po onih merah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 25, 'In okna so bila na njih in na njih stenskih napustkih kroginkrog, kakor okna pri onih vratih; dolžina je bila petdeset komolcev in širjava petindvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 26, 'In sedem stopnic so imeli njih vzhodi, in njih stenski napustki so bili pred njimi, in so imela palmi na oporah, eno na tej in drugo na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 27, 'In bila so vrata do notranjega dvorišča proti jugu; in meril je od vrat do vrat proti jugu, sto komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 28, 'Nato me je pripeljal skozi južna vrata na notranje dvorišče. In meril je južna vrata po onih merah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 29, 'in njih stražnice in njih opore in stenske napustke po onih merah; in okna so bila na njih in na njih stenskih napustkih okoliinokoli: dolžina je bila petdeset komolcev in širjava petindvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 30, 'In stenski napustki so bili kroginkrog, dolžina petindvajset komolcev in širjava pet komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 31, 'In njih stenski napustki so bili proti zunanjemu dvorišču, in palme so bile na njih oporah, in osem stopnic so imeli njih vzhodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 32, 'In pripeljal me je na notranje dvorišče proti vzhodu. In meril je vrata po onih merah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 33, 'in njih stražnice in njih opore in stenske napustke po onih merah; in bila so okna na njih in na njih stenskih napustkih okoliinokoli; dolžina je bila petdeset komolcev in širjava petindvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 34, 'In njih stenski napustki so bili proti zunanjemu dvorišču, in palme so bile na njih oporah na tej in na oni strani; in osem stopnic so imeli njih vzhodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 35, 'In pripeljal me je k severnim vratom. In meril jih je po onih merah:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 36, 'njih stražnice, njih opore in stenske napustke; in okna so bila na njih kroginkrog; dolžina je bila petdeset komolcev in širjava petindvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 37, 'In njih opore so bile proti zunanjemu dvorišču, in palme so bile na tej in na oni strani, in osem stopnic so imeli njih vzhodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 38, 'In hram s svojimi durmi je bil pri oporah vrat, tam so prali žgalne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 39, 'In v veži pred vrati sta bili dve mizi na tej in dve mizi na oni strani, da so nanje pokladali zaklano žgalščino in daritev za greh in za krivdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 40, 'In na zunanji strani, severni, če greš gori k vratnemu vhodu, sta bili dve mizi, in na drugi strani veže pred vrati veže dve mizi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 41, 'štiri mize na tej in štiri mize na oni strani, po strani vrat: osem miz, na katere so pokladali zaklane daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 42, 'In štiri mize iz rezanih kamenov so bile za žgalščino, po poldrugi komolec dolge in poldrugi komolec široke in po en komolec visoke; na te so pokladali orodje, s katerim so klali žgalne in klalne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 43, 'In robovi, dlan široki, so bili privihani okoliinokoli, in na mize so devali meso za daritev. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 44, 'In zunaj notranjih vrat sta bila dva hrama na notranjem dvorišču: eden na strani severnih vrat s pročeljem proti jugu, eden na strani južnih vrat s pročeljem proti severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 45, 'In mi reče: Ta hram, ki mu je pročelje obrnjeno proti jugu, je za duhovnike, ki strežejo službi v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 46, 'Hram pa, ki mu je pročelje obrnjeno proti severu, je za duhovnike, ki strežejo službi pri oltarju; to so sinovi Zadokovi, ki pristopajo izmed sinov Levijevih h Gospodu, da mu služijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 47, 'In izmeril je dvorišče: sto komolcev dolgo in sto komolcev široko, štirivoglato. In oltar je bil pred hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 48, 'In pripeljal me je k hišni veži; in meril je opore vežne: pet komolcev na tej in pet komolcev na oni strani; in širjava vratom je bila trije komolci na tej in trije komolci na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 40, 49, 'Dolgost veže je bila dvajset komolcev in širjava enajst komolcev, in to ob stopnicah, po katerih se je hodilo do nje. In stebra sta bila pri oporah, eden na tej in eden na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 1, 'In pripeljal me je v tempelj. In meril je opore: šest komolcev širjave na tej in šest komolcev širjave na oni strani, kakor je bila širjava Šatora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 2, 'In širjava vhoda je bila deset komolcev, durnici vhoda pa sta merili pet komolcev na tej in pet komolcev na oni strani. In izmeril je dolgost templja: štirideset komolcev, in širjavo njegovo: dvajset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 3, 'In šel je v notranjščino; in meril je obe opori vhoda: dva komolca, in vhod šest komolcev visok in sedem komolcev širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 4, 'In meril je njeno dolgost: dvajset komolcev, in širjavo: dvajset komolcev proti templju. In mi reče: To je Najsvetejše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 5, 'In meril je hišno steno: šest komolcev, in širjavo postranskih sobic: štiri komolce, kroginkrog pri hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 6, 'Bilo je pa postranskih sobic, sobica nad sobico, po trideset v treh nadstropjih; in odstavki so bili na zidu okrog hiše za postranske sobice, da so slonele na njih in ne na zidu hiše same.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 7, 'In širjava in prostornost tistih sobic je bila više večja, kajti prostornost ob hiši se je navzgor večala bolj in bolj, da je bilo širše ob hiši proti višku. In hodilo se je iz spodnjih sobic po srednjih v zgornje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 8, 'In videl sem odstavek spodaj okoli hiše: postranske sobe so imele podzid eno šibo širok, šest komolcev do stika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 9, 'Debelost zida, ki so ga imele postranske sobice na zunaj, je bila pet komolcev; in plan ob poslopju postranskih sobic, med hišo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 10, 'in med hrami, ki so bili okoli hiše, je bila dvajset komolcev široka na vse strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 11, 'In duri postranskih sobic so bile proti temu planemu prostoru, ene duri proti severu in druge duri proti jugu. In širjava praznega prostora je bila pet komolcev okoliinokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 12, 'In poslopje spredaj ob odločenem prostoru na zahodni strani templja je bilo sedemdeset komolcev široko, in zid poslopja pet komolcev debel kroginkrog, in dolgost njegova devetdeset komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 13, 'In izmeril je tempelj: dolgost sto komolcev, in odločeni prostor, poslopje in njegove zidove: dolgost sto komolcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 14, 'širjava pa hišnega pročelja in odločenega prostora proti vzhodu: sto komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 15, 'In meril je dolgost tistega poslopja, ki je bilo ob sprednji strani odločenega prostora in je segalo do zadnje strani; in mostovže njegove na tej in na oni strani: sto komolcev; in notranji tempelj in hrame na dvorišču –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 16, 'prage in poševna okna in mostovže okoli tistih treh poslopij – nasproti pragom je bilo vse kroginkrog obito z lesom in od tal do oken (okna pa so bila pokrita) –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 17, 'prostor nad vrati in vso hišo, znotraj in zunaj, in prostor poleg vseh sten okrog, znotraj in zunaj: vse je imelo svojo mero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 18, 'In bili so narejeni kerubimi in palme, in palma je bila med kerubom in kerubom; vsak kerub je imel dvoje obličje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 19, 'človekovo obličje proti palmi na tej in levovo obličje proti palmi na oni strani; tako je bilo narejeno pa vsej hiši kroginkrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 20, 'Od tal do vrh vrat so bili narejeni kerubimi in palme: taka je bila templjeva stena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 21, 'Podboji v templju so bili na štiri vogle; in tisti na pročelju svetišča so imeli enako podobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 22, 'Oltar je bil iz lesa, tri komolce visok in dva komolca dolg, in imel je svoje vogle in njegov podstavek in stene njegove so bile iz lesa. In mi reče: To je miza, ki je pred Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 23, 'In tempelj in svetišče sta imeli dvojne duri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 24, 'In duri so imele dve durnici, ki sta se vrteli; dve durnici za ene duri in dve durnici za druge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 25, 'In na njih, na durih templjevih, so bili narejeni kerubimi in palme, kakor so bili narejeni na stenah. In leseno strešno tramovje je bilo ob sprednji strani veže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 41, 26, 'In poševna okna in palme so bile na tej in na oni strani, na vežnih stenah in na postranskih hišnih sobicah in na tramovju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 1, 'In peljal me je ven na zunanje dvorišče po poti proti severu. In me privede k hramom, ki so bili nasproti odločenemu prostoru in nasproti poslopju proti severu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 2, 'k podložni strani, mereči sto komolcev, kjer je bil severni vhod, širjava pa je bila petdeset komolcev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 3, 'nasproti dvajsetim komolcem notranjega dvorišča in nasproti tlaku zunanjega dvorišča. Mostovž je bil proti mostovžu v tretjem nadstropju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 4, 'Pred hrami je bil hodnik deset komolcev širok, do notranjega dvorišča je bilo sto komolcev. Njih duri pa so bile proti severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 5, 'In ker so jim mostovži krajšali prostor, so bili zgornji hrami ožji nego spodnji in srednji na poslopju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 6, 'Kajti bili so trojni, drug nad drugim, a niso imeli stebrov kakor stebri na dvoriščih; zato so bili zgornji ožji nego spodnji in srednji od tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 7, 'In zunanji zid, vzporeden hramom, proti zunanjemu dvorišču, je bil ob sprednji strani hramov, petdeset komolcev dolg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 8, 'Kajti dolgost hramov ob zunanjem dvorišču je bila petdeset komolcev, in glej, templju nasproti sto komolcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 9, 'In pod temi hrami je bil vhod do vzhoda, če se je k njim šlo do zunanjega dvorišča. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 10, 'Na širnem zidu na dvorišču proti jugu, pred odločenim prostorom in pred poslopjem, so bili tudi hrami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 11, 'in pred njimi je bila pot kakor pri hramih proti severu; enako so bili dolgi in široki kakor oni, in vsi njih izhodi, naprave in duri so bile enake.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 12, 'In kakor vhodi onih so bili tudi vhodi hramov, ki so stali proti jugu: vhod v začetku poti, tiste poti, ki je bila poleg vzporednega zida proti vzhodu, če se je k njim šlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 13, 'In mi reče: Hrami na severu in hrami na jugu, ki so pred odločenim prostorom, so sveti hrami, v katerih naj jedo presvete reči duhovniki, ki se bližajo Gospodu. Tam naj pokladajo presvete reči, jedilno daritev in žrtev za greh in za krivdo; kajti ta kraj je svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 14, 'Kadar stopijo duhovniki v svetišče, ne smejo iti ven na zunanje dvorišče, ampak tam naj si slečejo oblačila, v katerih služijo, ker so sveta; oblečejo naj druga oblačila in tako naj se bližajo prostoru, določenemu za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 15, 'In ko je premeril vso notranjo hišo, me je peljal ven skozi vrata, ki so gledala proti jutru, in meril je povsod okoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 16, 'Meril je vzhodno stran z mersko palico, petsto palic po merski palici okrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 17, 'Meril je severno stran, petsto palic po merski palici okrog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 18, 'Meril je južno stran, petsto palic po merski palici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 19, 'Potem je krenil proti zahodni strani in meril petsto palic po merski palici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 42, 20, 'Meril je prostor na štiri strani; okoli njega je bil zid povsod okrog: dolgost je bila petsto in širjava petsto, da bi se ločilo med tem, kar je sveto, in tem, kar je v občno porabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 1, 'Potem me je peljal k vratom, k tistim vratom, ki so gledal proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 2, 'In glej, slava Boga Izraelovega je prišla od vzhoda, in glas njegov je bil kakor glas mnogih vodá in zemlja je sijala od slave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 3, 'In prikazen, ki sem jo videl, je bila kakor prikazen, ki sem jo videl, ko sem bil prišel razdevat mesto; in bile so prikazni kakor prikazen, ki sem jo videl ob reki Kebarju. In padel sem na obraz svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 4, 'In slava Gospodova je prišla v hišo po poti vrat, katerih pročelje je obrnjeno proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 5, 'In duh me povzdigne ter me pripelje na notranje dvorišče; in glej, slava Gospodova je napolnila hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 6, 'In slišal sem nekoga govoriti k meni iz hiše, mož mi je pa stal ob strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 7, 'In mi govori: Sin človečji, to je mesto prestola mojega in mesto stopal mojih, kjer bom vekomaj prebival sredi sinov Izraelovih. In hiša Izraelova ne bo več skrunila svetega imena mojega, ne oni, ne njih kralji, z nečistovanjem svojim in z mrliči svojih kraljev na svojih višavah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 8, 'ko so stavili svoj prag poleg mojega praga in svoje podboje pri mojih podbojih, da je bila le stena med menoj in njimi; in oskrunjali so ime svetosti moje z gnusobami, ki so jih počenjali, zato sem jih pokončal v jezi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 9, 'Sedaj spravijo izpred mene nečistovanje svoje in mrliče svojih kraljev, in prebival bom sredi njih vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 10, 'Ti, sin človečji, pokaži ta dom hiši Izraelovi, da bi se sramovali krivic svojih, in naj izmerijo stavbni načrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 11, 'In kadar se bodo sramovali vsega, kar so počenjali, jim razlóži podobo hiše in njeno uredbo in njene izhode in vhode in vse njene podobe in vse naprave njene in vse podobe in vse zakone njene, in nariši to pred njih očmi, da ohranijo vso podobo njeno in vse naprave njene ter se po njih ravnajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 12, 'To je postava za hišo: Na vrhu gore je ves njen okraj kroginkrog presvet. Glej, to je postava za hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 13, 'To pa je mera za oltar, po komolcih (komolec bodi komolec in dlan dolg): žlebina bo komolec globoka in komolec široka, in njen zidec ob kraju njenem kroginkrog dlan visok; in to bode podzid oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 14, 'In od žlebine ob tleh do nižjega odstavka bo dva komolca višine in en komolec širjave; in od malega odstavka do velikega odstavka bo štiri komolce višine in komolec širjave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 15, 'In ognjišče božje bo štiri komolce visoko, in od ognjišča božjega kvišku bodo štirje rogovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 16, 'In ognjišče božje bo dvanajst komolcev dolgo in dvanajst široko; četverovoglato bo proti svojim štirim stranem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 17, 'In odstavek bo štirinajst komolcev dolg in štirinajst širok proti štirim stranem njegovim; in zidec okoli njega bo pol komolca, in žlebina ob njem komolec široka; in stopnice njegove bodo obrnjene proti jutru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 18, 'In mi reče: Sin človečji, tako pravi Gospod Jehova: To so postave za oltar na dan, ko ga napravijo, da se daruje na njem žgalščina in škropi kri po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 19, 'Duhovnikom, levitom, ki so iz semena Zadokovega, ki so mi blizu, da bi mi stregli, govori Gospod Jehova, daj mladega junca v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 20, 'In vzemi krvi njegove in jo deni na štiri rogove njegove in na štiri vogle odstavkove in na zidec kroginkrog; tako ga očisti greha in stori poravnavo zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 21, 'In vzemi za greh darovanega junca, in naj ga sežgo na določenem mestu v hiši, zunaj svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 22, 'Drugi dan pa daruj kozla brez madeža za greh, in naj očistijo oltar greha, kakor so ga očistili z juncem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 23, 'Ko dokončaš njega očiščevanje, daruj mladega junca brez madeža in brezmadežnega ovna izmed črede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 24, 'In ju daruj pred Gospodom, in duhovniki naj ju potresejo s soljo ter ju darujejo kot žgalno daritev Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 25, 'Sedem dni daruj vsak dan kozla za greh; naj tudi darujejo mladega junca in ovna izmed črede brez madeža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 26, 'Sedem dni naj se opravlja poravnava za oltar in naj ga očisitijo in posvetijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 43, 27, 'In ko se dopolnijo tisti dnevi, bodo osmi dan in dalje opravljali na oltarju žgalne in mirovne daritve vaše; in milo vas sprejmem, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 1, 'Nato me je peljal nazaj po potu k zunanjim vratom svetišča, ki gledajo proti jutru; a bila so zaprta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 2, 'In Gospod mi reče: Ta vrata bodo zaprta; ne bodo se odpirala in nihče ne pojde skozi nje, kajti Gospod, Bog Izraelov, je šel noter skozi nje, zato naj bodo zaprta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 3, 'Kar se tiče kneza, bo sedel v njih kot knez, da jé kruh pred Gospodom; vstopi noter skozi vežo ob vratih in pojde ven po isti poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 4, 'Potem me je peljal po potu severnih vrat pred hišo; in pogledam, in glej, slava Gospodova je napolnila hišo Gospodovo; in padem na obraz svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 5, 'In Gospod mi reče: Sin človečji, pazi s srcem svojim in glej s svojimi očmi in poslušaj s svojimi ušesi vse, kar ti govorim zastran vseh postav hiše Gospodove in vseh zakonov njenih; in pazi s srcem svojim na vhod v hišo in na vse izhode iz svetišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 6, 'In reci upornikom, hiši Izraelovi: Tako pravi Gospod Jehova: Dosti vam bodi vaših gnusob, o hiša Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 7, 'ker ste vodili tujce neobrezanega srca in neobrezanega mesa, da bivajo v svetišču mojem, da bi oskrunjali hišo mojo, ko ste darovali kruh moj, tolstino in kri; in razdrli so zavezo mojo poleg vseh gnusob vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 8, 'In niste stregli na straži svetinj mojih, ampak postavili ste one namesto sebe, da strežejo na straži moji v svetišču mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 9, 'Tako pravi Gospod Jehova: Noben tujec neobrezanega srca in neobrezanega mesa ne sme stopiti v svetišče moje izmed vseh tujcev, kar jih je med sinovi Izraelovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 10, 'Toda leviti, ki so zašli daleč od mene v blodnji Izraela, ki je blodil od mene za bogovi svojimi, ti bodo nosili krivico svojo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 11, 'vendar pa bodo strežaji v svetišču mojem, kot čuvaji ob hišnih vratih in strežniki v hiši: oni naj koljejo žgalščine in klalščine za ljudstvo in oni naj stoje pred njimi in jim strežejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 12, 'Ker so jim stregli pred njih bogovi in so bili hiši Izraelovi spotikljaj v krivico, zato sem povzdignil roko svojo in prisegel proti njim, govori Gospod Jehova, da morajo nositi krivico svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 13, 'In k meni naj se ne bližajo, opravljat mi duhovniško službo, tudi naj ne pristopajo k nobeni izmed mojih svetinj, ki so presvete; temuč naj nosijo sramoto svojo in gnusobe svoje, ki so jih počenjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 14, 'Le za strežaje na straži hiše jih postavim, za vso službo njeno in za vse, kar se opravlja pri njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 15, 'Ali duhovniki, leviti, sinovi Zadokovi, ki so stregli na straži svetišča mojega, ko so sinovi Izraelovi zahajali od mene, ti se mi bodo bližali, da mi strežejo, in stali bodo pred menoj, da mi darujejo tolstino in kri, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 16, 'Ti naj hodijo v hišo mojo in pristopajo k mizi moji, da mi služijo, in naj strežejo na straži moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 17, 'Kadar pa vstopijo skozi vrata notranjega dvorišča, naj oblečejo platnena oblačila; in nič volnenega naj ne imajo na sebi, dokler služijo med vrati notranjega dvorišča in v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 18, 'Platnene čepice naj imajo na glavah in platnene hlače okoli ledja; naj se ne opasujejo z ničimer, kar napravlja znoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 19, 'Kadar pa pojdejo ven na zunanje dvorišče, na zunanji dvor k ljudstvu, naj slečejo oblačila, v katerih so službovali, in jih spravijo v svete sobice, in naj oblečejo druga oblačila, da ne posvetijo ljudstva s svojimi oblačili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 20, 'In naj si ne brijejo glave in tudi naj ne nosijo dolgih las, spodobno naj si jih strižejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 21, 'Tudi vina naj ne pije noben duhovnik, ko mu je iti na notranje dvorišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 22, 'In za žene naj si ne jemljejo vdov, ne razporočenih, temuč naj se oženijo z devico iz zaroda hiše Izraelove ali z vdovo, ki je osamela za duhovnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 23, 'In naj uče ljudstvo moje, kakšen je razloček med svetim in nesvetim, in mu velevajo razpoznavati med čistim in nečistim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 24, 'In ob pravdi bodo stali, da sodijo; po mojih sodbah naj sodijo; in naj izpolnjujejo zakone in postave moje ob določenih praznikih mojih in naj posvečujejo sobote moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 25, 'Tudi ne pojdejo k nobenemu mrliču, da bi se onečistili; samo pri očetu ali materi ali sinu ali hčeri ali bratu ali sestri, ki se ni še omožila, se smejo onečistiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 26, 'In ko se kdo očisti, mu odštejejo sedem dni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 27, 'in v dan, ko mu je iti v svetišče, na notranje dvorišče, da služi v svetišču, naj daruje svojo daritev za greh, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 28, 'In to jim bodi v dediščino: jaz sem njih dediščina; in posesti jim ne dajte v Izraelu, jaz sem njih posest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 29, 'Jedilno daritev in daritev za greh in za krivdo naj jedo; dobé naj vse, kar se z zaroto posveti v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 30, 'In prve vseh prvencev od vsega in vse podvige od vsega, od vseh podvigov vaših naj dobé duhovniki; tudi prvino svoje moke daj duhovniku, da počiva blagoslov nad hišo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 44, 31, 'Nobene mrline pa ali raztrganega, bodisi od ptičev ali od živine, naj ne jedo duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 1, 'In ko si boste delili po žrebu deželo v dediščino, oddelite dar povzdignjenja Gospodu, sveti del dežele: petindvajset tisoč komolcev na dolgost in deset tisoč na širjavo; to bodi sveto po vsej meji svoji naokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 2, 'Od tega bodi za svetišče petsto na dolgost in petsto na širjavo, štirivoglato okoli in petdeset komolcev planega prostora okrog njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 3, 'In od one mere izmeriš dolgost petindvajset tisoč in širjavo deset tisoč, in na tem bodi svetišče, Najsvetejše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 4, 'Sveti del dežele je; duhovnikov bodi, služabnikov svetišča, ki pristopajo služit Gospodu, in bodi jim prostor za hiše in sveti prostor za svetišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 5, 'In petindvajset tisoč na dolgost in deset tisoč na širjavo bodi levitom, strežnikom hiše, v njih last, za prebivanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 6, 'In v posest mestu določite pet tisoč širjave in petindvajset tisoč dolgosti, vzporedno s podvigom, ki je sveti del dežele: to bodi za vso hišo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 7, 'In knezu dajte posest na tej in na oni strani svetega podviga in mestnega posestva, poleg svetega in poleg mestnega posestva, na zahodni strani proti zahodu in na vzhodni strani proti jutru, in po dolgosti primerno deležu enega rodu, od zahodne do vzhodne meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 8, 'V deželi bodi to njemu v posest v Izraelu; in knezi moji ne bodo več stiskali ljudstva mojega, temuč izroče deželo hiši Izraelovi po njih rodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 9, 'Tako pravi Gospod Jehova: Dosti vam bodi, o knezi Izraelovi! Opustite nasilstvo in odiranje in vršite sodbo in pravičnost; nehajte tirati ljudstvo moje s posestva njegovega, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 10, 'Imejte pravično tehtnico, pravično efo in pravičen bat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 11, 'Efa in bat bodita enake mere, da gre v bat desetina homerja in v efo desetina homerja; po homerju naj se ravna njiju mera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 12, 'In sekel naj ima dvajset ger. Dvajset seklov, petindvajset seklov, petnajst seklov bodi vaša mina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 13, 'To je podvig, ki ga darujte: šestinko efe od homerja pšenice in šestinko efe od homerja ječmena dajajte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 14, 'in določeni del olja, od bata olja: desetinko bata od kora, od desetih batov ali od homerja, kajti deset batov je homer,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 15, 'in glavo drobnice, od dvesto z Izraelovih pašnikov, ki jih močijo vode – v jedilno in žgalno in mirovno daritev, da se izvrši poravnava zanje, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 16, 'Vse ljudstvo dežele naj se udeležuje tega podviga za kneza v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 17, 'In knezova dolžnost bode skrbeti za žgalščine in za jedilno in pitno daritev ob praznikih in ob mlajih in ob sobotah, ob vseh določenih slovesnostih hiše Izraelove: on pripravi daritev za greh in jedilno in žgalno in mirovno daritev, da se izvrši poravnava za hišo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 18, 'Tako pravi Gospod Jehova: Prvi dan prvega meseca vzemi mladega junca brez madeža in očisti svetišče greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 19, 'In duhovnik naj vzame krvi daritve za greh in jo dene na podboje hiše in na štiri vogle oltarjevega odstavka in na podboje pri vratih notranjega dvorišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 20, 'Tako delaj tudi sedmi dan meseca za tega, ki greši iz zmote in ki je neveden. In tako opravljajte poravnavo za hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 21, 'Štirinajsti dan prvega meseca praznujte pasho, sedemdnevni praznik; opresnike jejte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 22, 'In ta dan naj daruje knez zase in za vse ljudstvo dežele junca v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 23, 'In sedem dni praznika naj daruje žgalščino Gospodu, sedem juncev in sedem ovnov brez madeža, vsak dan teh sedem dni, in kozla vsak dan v daritev za greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 24, 'In kot jedilno daritev naj pripravijo efo bele moke za vsakega junca in efo za vsakega ovna in hin olja k vsaki efi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 45, 25, 'Petnajsti dan sedmega meseca, ob prazniku, naj stori enako: sedem dni daruj daritve za greh in žgalščine in jedilne daritve z oljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 1, 'Tako pravi Gospod Jehova: Vrata notranjega dvorišča, ki gledajo proti jutru, bodo zaprta šest delavnikov, ali v sobotni dan naj se odpro, tudi v dan mlaja naj se odpro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 2, 'In knez naj vstopi skozi vežo ob vratih, od zunaj, in se postavi ob podbojih pri vratih; in duhovniki naj darujejo žgalščino njegovo in mirovne daritve njegove, on pa naj moli na pragu pri vratih; potem pojde ven, vrata pa naj se ne zapro do večera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 3, 'In ljudstvo dežele naj moli ob vhodu teh vrat pred Gospodom ob sobotah in ob mlajih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 4, 'In žgalščina, ki naj jo knez daruje Gospodu v sobotni dan, bodi: šest jagnjet brez madeža in oven brez madeža,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 5, 'in kot jedilna daritev: efa bele moke za ovna, in jedilna daritev za jagnjeta bodi po zmožnosti njegovi, in hin olja k vsaki efi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 6, 'In v dan mlaja bodi mlad junec brez madeža in šest jagnjet in oven, brezmadežni naj bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 7, 'In kot jedilno daritev naj pripravi: efo za junca in efo za ovna, za jagnjeta pa po zmožnosti svoji, in hin olja k vsaki efi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 8, 'In kadar pride knez, naj vstopi skozi vežo ob vratih in po isti poti naj gre ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 9, 'Ko pa pride ljudstvo dežele pred Gospoda ob določenih praznikih: kdor vnide skozi severna vrata, da bi molil, naj gre ven skozi južna vrata, in kdor vstopi skozi južna, naj gre ven skozi severna vrata; naj se ne vrača po poti tistih vrat, skozi katera je prišel noter, temuč naj izide skozi nasprotno stoječa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 10, 'Knez pa, ko pojdejo noter, naj gre sredi njih, in ko gredo ven, naj gredo skupno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 11, 'In ob določenih praznikih in prazničnih časih bodi jedilna daritev: efa bele moke za junca in efa za ovna, za jagnjeta pa bodi po zmožnosti njegovi, in hin olja k vsaki efi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 12, 'In kadar hoče knez darovati prostovoljno žgalščino ali prostovoljno mirovno daritev Gospodu, naj se mu odpro vrata, ki gledajo proti vzhodu; in naj opravi svojo žgalno daritev in mirovne daritve svoje, kakor jih opravlja sobotni dan; potem pojde ven, in ko odide, naj se zapro vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 13, 'In vsak dan daruj Gospodu enoletno brezmadežno jagnje v žgalno daritev, vsako jutro ga daruj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 14, 'In s tem vred daruj jedilno daritev vsako jutro: šestinko efe in olja tretjinko hina, da se pokropi bela moka – kot jedilno daritev Gospodu: večne postave so to, ki naj neprenehoma veljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 15, 'Tako naj darujejo jagnje in jedilno daritev in olje vsako jutro v neprestano žgalno daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 16, 'Tako pravi Gospod Jehova: Ako podeli knez kateremu svojih sinov dar, je njegova dediščina; njegovih sinov bodi, njih dedna posest je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 17, 'Ako pa pokloni kateremu hlapcev svojih dar od dediščine svoje, bodi njegovo do leta svobode, potem pa pripadi zopet knezu; dediščina je namreč njegova, sinom njegovim lastna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 18, 'Knez pa ne sme ničesar vzeti od dediščine ljudstva, da bi jih siloma spravil iz njih posesti; od svoje lastnine naj podeli dediščino sinom svojim, da se ne razkropi ljudstvo moje, drug za drugim iz posesti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 19, 'In peljal me je skozi vhod, ki je bil ob strani vrat, v svete sobice za duhovnike, ki so gledale proti severu; in glej, ondi je bil prostor v skrajnem kotu proti zahodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 20, 'In mi reče: To je prostor, kjer naj duhovniki kuhajo daritev za krivdo in za greh, kjer naj pečejo jedilno daritev, da jim jih ne bo treba nositi na zunanje dvorišče, da ne posvetijo ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 21, 'Nato me pelje ven na zunanje dvorišče in me vodi mimo štirih dvornih voglov; in glej, na vsakem voglu dvorišča je bil dvorec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 22, 'V štirih kotih dvorišča so bili ograjeni dvori, po štirideset komolcev dolgi in trideset široki; vsi štirje dvorci so imeli enako mero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 23, 'In zid je bil okoli vseh štirih naokrog; in ognjišča so bila narejena pod zidom okoliinokoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 46, 24, 'In mi reče: To so kuhinje, kjer naj hišni strežaji kuhajo klalno daritev ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 1, 'In peljal me je nazaj k hišnim durim, in glej, vode so tekle izpod hišnega praga proti vzhodu, kajti pročelje hiše je bilo proti jutru; vode pa so tekle doli odspodaj, od desne strani hiše, južno ob oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 2, 'Nato me pelje ven skozi severna vrata ter me vodi zunaj okoli do zunanjih vrat po poti vrat, ki gledajo proti jutru; in glej, vode so šumljale sem od desne strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 3, 'In ko je šel mož ven proti vzhodu, je imel vrvico v roki; in je izmeril tisoč komolcev ter mi je velel iti skozi vode, ki so segale do gležnjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 4, 'Zopet je odmeril tisoč komolcev in mi velel iti skozi vode, ki so segale do kolen; še je odmeril tisoč in mi velel iti skozi vode, ki so segale do ledja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 5, 'Nato je odmeril tisoč, in bila je reka, ki je nisem mogel prebresti; kajti vode so se napele, da je bilo treba plavati po njih – reka, ki je ni bilo mogoče prebresti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 6, 'In mi reče: Sin človečji, si li to videl? In me je zopet peljal nazaj na breg reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 7, 'Ko sem se pa vračal, glej, ob reki je bilo mnogo drevja na tej in na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 8, 'Tedaj mi reče: Te vode tečejo ven proti vzhodnemu okraju, in pridero doli v nižino Arabo in se izlijejo v Mrtvo morje; ko pridejo v morje, se morska voda ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 9, 'In zgodi se: kamorkoli pride ta dvojna reka, bo živelo vse, kar živi in se giblje; in rib bode velika množina, kajti ko pridejo tja te vode, se ozdravi vse in bo živelo, kamorkoli pride reka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 10, 'In zgodi se, da bodo stali ob njej ribiči: od Engede do Eneglaima bode prostora za razpenjanje mrež; rib njenih bode jako veliko po svojih plemenih kakor rib morja velikega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 11, 'A luže in mlake njene ne bodo ozdravele, v solišča bodo odločene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 12, 'In ob reki, na njenem bregu, na tej in oni strani, bo raslo drevje za jed, ki mu listje ne uvene in sad ne mine; vsak mesec bo rodilo zrel sad, ker vode njene teko iz svetišča; in njegov sad bode za jed in listje njegovo v zdravilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 13, 'Tako pravi Gospod Jehova: To bodi meja, po kateri si razdelite deželo v dediščino po dvanajsterih rodovih Izraelovih: Jožefu dva dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 14, 'In podedovali jo boste eden kakor drugi, ki sem zaradi nje povzdignil roko svojo v prisego, da jo dam očetom vašim; in pripade vam v dediščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 15, 'In to bodi meja deželi: Na severni strani, od velikega morja, po poti proti Hetlonu, tja do Zedada:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 16, 'Hamat, Berota, Sibraim, ki je med mejo Damaska in mejo Hamata; srednji Hazer, ki je ob meji Havrana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 17, 'Meja torej od morja do vzhoda bodi Hazar-enon, ob meji Damaska, in kar se tiče severa, proti severu bodi meja Hamat. To je severna stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 18, 'In kar se tiče vzhodne strani, med Havranom in Damaskom in Gileadom in med deželo Izraelovo bodi Jordan; od severne meje do vzhodnega morja merite. To je vzhodna stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 19, 'In južna stran proti jugu: od Tamarja tja do Vod prepira v Kades in do potoka Egiptovskega, prav do velikega morja. To je južna stran proti jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 20, 'In zahodna stran bodi veliko morje od južne meje do tja, koder se pride nasproti Hamatu. To je zahodna stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 21, 'In to deželo si razdelite po rodovih Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 22, 'In po žrebu jo razdelite v dediščino sebi in tujcem, ki bivajo med vami, ki so rodili otroke sredi vas, in naj vam bodo kakor domačini med sinovi Izraelovimi; z vami naj dobe dediščino sredi rodov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 47, 23, 'In zgodi se naj: v katerem rodu gostuje tujec, tam mu dajte dediščino njegovo, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 1, 'Ta pa so imena rodov: Od severnega konca, ob poti v Hetlon, tja proti Hamatu in Hazar-enonu, ob meji Damaska, proti severu, kraj Hamata – od vzhodne strani do zahodne naj ima Dan, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 2, 'In poleg Danove meje, od vzhodne do zahodne strani: Aser, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 3, 'In poleg Aserjeve meje, od vzhodne do zahodne strani: Neftali, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 4, 'In poleg meje Neftalijeve, od vzhodne do zahodne strani: Manase, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 5, 'In poleg meje Manasejeve, od vzhodne do zahodne strani: Efraim, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 6, 'In poleg meje Efraimove, od vzhodne do zahodne strani: Ruben, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 7, 'In poleg meje Rubenove, od vzhodne do zahodne strani: Juda, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 8, 'In poleg Judove meje, od vzhodne do zahodne strani, bodi dar povzdignjenja, ki ga darujte: petindvasjet tisoč komolcev po širjavi in po dolgosti kakor eden deležev od vzhodne do zahodne strani, in sredi njega bodi svetišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 9, 'Dar povzdignjenja, ki ga darujte Gospodu, bodi petindvajset tisoč komolcev dolg in deset tisoč širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 10, 'In njim, namreč duhovnikom, naj pripade sveti dar povzdignjenja: proti severu petindvajset tisoč dolg in proti zahodu deset tisoč širok in proti vzhodu deset tisoč širok in proti jugu petindvajset tisoč dolg, in svetišče Gospodovo bodi sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 11, 'Duhovnikom, ki so posvečeni izmed sinov Zadokovih, ki so stregli straži moji, ki niso zašli v blodnji Izraelovi, kakor so zašli leviti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 12, 'njim bodi podvig od podviga dežele, presvet, poleg meje levitov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 13, 'Leviti pa naj dobe, vzporedno z mejo duhovnikov, petindvajset tisoč po dolgosti in deset tisoč po širjavi; vsa dolgost bodi petindvajset tisoč in širjava deset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 14, 'In tega ne smejo nič prodati, ne zameniti; in prvina dežele ne sme preiti v last drugemu, kajti sveta je Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 15, 'In tistih pet tisoč komolcev, ki preostanejo po širjavi, spredaj poleg petindvajsetih tisoč, naj bo v občno porabo mestu za prebivališča in za plan prostor; mesto pa bodi sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 16, 'In to naj bodo mere mestu: severna stran štiri tisoč in petsto, južna stran štiri tisoč in petsto, na vzhodni strani štiri tisoč petsto in zahodna stran štiri tisoč petsto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 17, 'In plan prostor bodi okrog mesta: proti severu dvesto petdeset komolcev, proti jugu dvesto petdeset, proti vzhodu dvesto petdeset in proti zahodu dvesto petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 18, 'In kar preostane po dolgosti, vzporedno s svetim podvigom, desettisoč komolcev proti vzhodu in desettisoč proti zahodu (vzporedno je s svetim podvigom), pridelek iz tega naj bo v živež njim, ki delajo v mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 19, 'Kateri delajo v mestu, iz vseh rodov Izraelovih, naj to obdelujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 20, 'Ves dar povzdignjenja bodi petindvajset tisoč do petindvajset tisoč; četverokoten bodi sveti podvig, ki ga darujte k posesti mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 21, 'Kar pa ostane, naj dobi knez; na tej in na oni strani svetega podviga in posesti mesta, poleg petindvajsetih tisoč podviga prav do vzhodne meje, in proti zahodu poleg petindvajsetih tisoč proti zahodni meji, vzporedno z deleži rodov, bodi knezovo. In sveti dar povzdignjenja in svetišče hiše bodi sredi tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 22, 'In od posesti levitov in od posesti mesta, ki je sredi tega, kar je knezovo, kolikor je med mejo Judovo in mejo Benjaminovo, naj bode knezova last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 23, 'In drugi rodovi: Od vzhodne do zahodne strani: Benjamin, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 24, 'In poleg Benjaminove meje, od vzhodne do zahodne strani: Simeon, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 25, 'In poleg meje Simeonove, od vzhodne do zahodne strani: Isahar, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 26, 'In poleg Isaharjeve meje, od vzhodne do zahodne strani: Zebulon, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 27, 'In poleg Zebulonove meje, od vzhodne do zahodne strani: Gad, en delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 28, 'In poleg meje Gadove, ob južni strani proti jugu, bodi meja od Tamarja do Vod prepira v Kades in do potoka Egiptovskega, prav do velikega morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 29, 'To je dežela, ki jo razdelite po žrebu rodovom Izraelovim v dediščino, in to so posamezni deleži njeni, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 30, 'To pa so izhodi mesta: od severne strani štiri tisoč in petsto komolcev mere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 31, 'in mestna vrata naj bodo po imenih rodov Izraelovih; troje vrat proti severu: vrata Rubenova, ena; vrata Judova, ena; vrata Levijeva, ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 32, 'In proti vzhodni strani štiri tisoč in petsto komolcev in troje vrat: vrata Jožefova, ena; vrata Benjaminova, ena; vrata Danova, ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 33, 'In ob južni strani, štiri tisoč in petsto komolcev mere in troje vrat: vrata Simeonova, ena; vrata Isaharjeva, ena; vrata Zebulonova, ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 34, 'Ob zahodni strani štiri tisoč in petsto komolcev in njenih troje vrat: vrata Gadova, ena; vrata Aserjeva, ena; vrata Neftalijeva, ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (26, 48, 35, 'Kroginkrog osemnajst tisoč komolcev. In ime mestu bodi od tistega dne: Gospod prebiva tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 1, 'V tretjem letu kraljevanja Jojakima, kralja Judovega, je prišel Nebukadnezar, kralj v Babilonu, pred Jeruzalem in ga je oblegal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 2, 'In Gospod mu je dal v roko Jojakima, kralja na Judovem, in nekatere izmed posod hiše Božje. In prepeljal jih je v deželo Sinear, v svojega boga hišo: posode tiste je dejal v zakladnico boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 3, 'In kralj je ukazal Aspenazu, načelniku svojih dvornikov, naj pripelje mladeničev iz sinov Izraelovih od kraljevega zaroda in od plemenitnikov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 4, 'brez kakršnega koli madeža, lepe postave in dovzetnih za pouk v vsej modrosti, bistre pameti in obdarovanih z razumnostjo in sposobnih, da stoje v palači kraljevi ter da bi jih učili pismenstva in jezika Kaldejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 5, 'In kralj jim je določil vsakdanji obrok kraljevih jedil in vina, ki ga je sam pil, in da jih tako vzgajajo tri leta, in potem naj bi stali pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 6, 'Bili so pa med njimi, iz sinov Judovih: Daniel, Hananija, Misael in Azarija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 7, 'In knez dvornikov jim je dal imena, in je imenoval Daniela Beltsazarja in Hananija Sadraha in Misaela Mesaha in Azarija Abednega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 8, 'Ali Daniel se je namenil v srcu, da se ne bo omadeževal s kraljevo jedjo in z vinom, ki ga je kralj pil; zato poprosi kneza dvornikov, da mu ne bodi treba se omadeževati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 9, 'Bog pa je dal Danielu doseči milost in usmiljenje pri knezu dvornikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 10, 'In reče knez dvornikov Danielu: Bojim se gospoda svojega, kralja, ki vam je določil jed in pijačo; kajti čemu naj vidi, da so vaši obrazi medlejši nego drugih mladeničev vaše starosti? Tako bi bili krivi, če bi mi kralj vzel glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 11, 'Tedaj reče Daniel oskrbniku, ki ga je bil postavil knez dvornikov nad Danielom, Hananijem, Misaelom in Azarijem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 12, 'Prosim, izkusi nas, hlapce svoje, deset dni, in naj nam dajo jesti sočivja in piti vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 13, 'Potem naj ogledajo obraze naše vpričo tebe in obraze mladeničev, ki jedo kraljevo jed, in kakor boš videl, tako stóri s hlapci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 14, 'Poslušal jih je torej v tej reči in naredil poskušnjo ž njimi deset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 15, 'In po desetih dneh so se kazali njih obrazi boljši in mesnatejši nego vseh mladeničev, ki so jedli jed kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 16, 'Tedaj jim oskrbnik odvzame jed in vino, ki jim ga je bilo piti, in jim je dajal sočivja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 17, 'Tem štirim mladeničem pa je Bog dal znanje in razumnost v vsem slovstvu in modrosti, in Daniel je znal razbirati vse prikazni in sanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 18, 'In ko so minili dnevi, po katerih je bil kralj določil, da jih pripeljejo k njemu, jih je privedel knez dvornikov pred Nebukadnezarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 19, 'In kralj je govoril ž njimi; a med njimi vsemi ni bilo nobenega kakor Daniel, Hananija, Misael in Azarija; zato so stali v službi pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 20, 'In v vsaki stvari modrosti in razumnosti, za katero jih je vprašal kralj, jih je našel desekrat boljše nego vse pismouke in rotilce, ki so bili po vsej državi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 1, 21, 'In Daniel je ostal do prvega leta kralja Cira.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 1, 'In v drugem letu kraljevanja Nebukadnezarjevega je imel Nebukadnezar sanje; in duh njegov se vznemiri in spanje ga mine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 2, 'Tedaj veli kralj, naj pokličejo pismouke in rotilce in čarodeje in Kaldejce, da povedo kralju sanje njegove. Pridejo torej in se postavijo pred kraljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 3, 'In kralj jim reče: Imel sem sanje in duh moj je vznemirjen, da bi se zavedel tistih sanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 4, 'Nato ogovore Kaldejci kralja po sirski: Kralj, žívi vekomaj! Povej nam, hlapcem svojim sanje, pa ti oznanimo razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 5, 'Kralj odgovori in reče Kaldejcem: Stvar je pri meni gotova: ako mi ne oznanite sanj in njih razlage, boste na kosce razsekani in hiše vam bodo izprevrnjene v gnojišča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 6, 'ako pa razodenete sanje in jih razložite, prejmete od mene darove, plačilo in veliko čast. Zato mi oznanite sanje in njih razlago!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 7, 'Odgovore drugič in reko: Kralj naj pove hlapcem svojim sanje, pa oznanimo razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 8, 'Kralj odgovori in reče: Za gotovo vem, da hočete pridobiti časa, ker vidite, da je pri meni trden sklep:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 9, 'Če mi ne oznanite sanj, ostane za vas le ena sodba; zakaj namenili ste se govoriti lažnive in mamljive besede pred menoj, dokler se ne premeni čas. Zatorej mi povejte sanje, in vedel bom, da mi morete oznaniti njih razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 10, 'Kaldejci odgovore pred kraljem in reko: Ni človeka na zemlji, ki bi mogel razodeti stvar kraljevo; kajti noben kralj, še tako velik in mogočen, ni nikdar zahteval take stvari od katerega koli pismouka ali rotilca ali Kaldejca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 11, 'Saj stvar, ki jo kralj zahteva, je pretežka; in nikogar ni drugega, ki bi jo pred kraljem mogel razodeti, razen bogov, katerih domovanje ni pri mesu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 12, 'Zaradi tega se kralj raztogoti in bridko srdit zapove, naj pomoré vse modrijane v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 13, 'In povelje je izšlo, in začeli so moriti modrijane; in iščejo Daniela in tovariše njegove, da jih usmrté.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 14, 'Tedaj odgovori Daniel previdno in modro Ariohu, glavarju telesne straže kraljeve, ki je šel morit modrijane babilonske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 15, 'izpregovori in reče Ariohu, mogočniku kraljevemu: Zakaj tako prenaglo kraljevo povelje? Tedaj razloži Arioh Danielu stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 16, 'Nato stopi Daniel noter in si izprosi od kralja, da mu dovoli rok, ob katerem mu oznani razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 17, 'Potem gre Daniel v hišo in razloži stvar tovarišem svojim Hananiju, Misaelu in Azariju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 18, 'da si izprosijo od Boga nebes usmiljenje zastran te skrivnosti, da bi ne poginili Daniel in tovariši njegovi z drugimi babilonskimi modrijani vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 19, 'Nato je bila Danielu v ponočni prikazni razodeta tista skrivnost. In Daniel je hvalil Boga nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 20, 'Daniel izpregovori in reče: Hvaljeno bodi ime Božje od vekomaj do vekomaj! Zakaj njegova je modrost in moč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 21, 'in on izpreminja čase in ure, on odstavlja kralje in postavlja kralje, modrost daje modrim in razumnim razumnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 22, 'razodeva globoke in skrite stvari; on ve, kar je v temi, in pri njem je zgolj svetloba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 23, 'Tebe, o Bog očetov mojih, zahvaljujem in slavim, da si mi dal modrost in moč in si mi sedaj oznanil, česar smo te prosili: zakaj ti si nam oznanil stvar kraljevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 24, 'Zategadelj je šel Daniel noter k Ariohu, ki ga je bil kralj postavil, da pomori babilonske modrijane; vstopi in mu reče takole: Ne móri modrijanov babilonskih; pelji me pred kralja, in oznanim kralju razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 25, 'Tedaj pripelje Arioh Daniela hitro pred kralja in mu reče takole: Našel sem moža med ujetniki z Judovega, ki bo povedal kralju razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 26, 'Kralj odgovori in reče Danielu, ki mu je bilo ime Beltsazar: Si li tisti, ki mi moreš povedati sanje, kakor sem jih videl, in njih razlago?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 27, 'Daniel izpregovori pred kraljem in reče: Skrivnosti, za katero je kralj vpraševal, ne morejo kralju oznaniti modrijani, rotilci, pismouki in čarodeji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 28, 'Ali Bog je v nebesih, ki razodeva skrivnosti, in on je oznanil kralju Nebukadnezarju, kar se zgodi v poslednjih dneh. Tvoje sanje in prikazni tvoje glave na ležišču tvojem so bile te:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 29, 'Tebi, o kralj, je bilo v mislih na ležišču tvojem, kaj se bo godilo po tem času; in on, ki razodeva skrivnosti, ti je oznanil, kaj se zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 30, 'Kar se pa tiče mene, ta skrivnost se mi ni razodela vsled modrosti, ki bi v meni bila mimo vseh živečih, temuč zategadelj, da se kralju oznani razlaga in ti zveš srca svojega misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 31, 'Ti, o kralj, si videl, in glej: podoba velika. Ta podoba, ogromna in prelepe svetlosti, je stala proti tebi in bila je videti grozna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 32, 'Te podobe glava je bila iz čistega zlata, prsi in rami njeni iz srebra, trebuh njen in ledje iz brona,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 33, 'stegna njena iz železa, noge njene nekaj iz železa in nekaj iz ila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 34, 'Gledal si, dokler se ni kamen odtrgal brez rok in je udaril podobo na njene noge, železne in ilovnate, ter jih je razdrobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 35, 'Tedaj je hkratu bilo razdrobljeno železo, il, bron, srebro in zlato, in bilo je kakor pleve na gumnu po leti: veter je odnesel vse, da temu ni bilo najti sledu. Kamen pa, ki je bil udaril podobo, je postal velika gora in je napolnil vso zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 36, 'To so tiste sanje; njih razlago pa hočemo povedati pred kraljem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 37, 'Ti, o kralj, si kralj kraljev, ki mu je dal Bog nebes kraljestvo, moč in oblast in slavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 38, 'in kjerkoli bivajo sinovi človeški, poljske zveri in ptice nebeške, tebi jih je dal v roko in tebe postavil za vladarja njim vsem – ti si tista glava iz zlata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 39, 'A za teboj nastopi drugo kraljestvo, slabše od tvojega, in potem tretje kraljestvo iz brona, ki bo gospodovalo vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 40, 'In četrto kraljestvo bode močno kakor železo; prav kakor železo zdrobi in razbije vse, tako bo ono, enako razruševalnemu železu, zdrobilo in razrušilo vse tisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 41, 'In da si videl noge in prste deloma iz lončarjevega ila in deloma iz železa, pomeni, da bode razdeljeno kraljestvo; ali bode v njem nekaj trdnosti železa, kajti videl si železo zmešano z ilovino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 42, 'In kakor prsti na nogah, deloma iz železa in deloma iz ila, tako bode kraljestvo deloma močno, deloma razdrobljivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 43, 'Da si pa videl železo zmešano z ilovino, pomeni, da se bodo med seboj mešali z ženitvijo, pa se vendar ne bodo držali drug drugega, kakor se železo ne more zmešati z ilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 44, 'A v dneh teh kraljev ustanovi Bog nebes kraljestvo, ki vekomaj ne bo razdejano in njegovo gospostvo se ne prepusti nobenemu drugemu ljudstvu; vsa ona kraljestva pa zdrobi in uniči, a samo bo stalo na veke:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 45, 'prav kakor si videl, da se je raz goro odtrgal kamen brez človeških rok in je zdrobil železo, bron, il, srebro in zlato. Véliki Bog je oznanil kralju, kaj se zgodi po tem času; in resnične so tiste sanje in njih razlaga zanesljiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 46, 'Tedaj pade kralj Nebukadnezar na obraz in se pokloni Danielu in zapove, naj mu darujejo jedilno daritev in kadilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 47, 'Kralj odgovori Danielu in reče: V resnici vaš Bog je Bog bogov in kraljem Gospod in razodevalec skrivnosti, ker si mogel razodeti to skrivnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 48, 'Potem je poveličal kralj Daniela in mu dal mnogo velikih darov ter ga postavil za vladarja nad vso pokrajino Babilonsko in za prvega načelnika vsem modrijanom v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 2, 49, 'Daniel pa je prosil kralja, in ta je poveril poslovodstvo pokrajine Babilonske Sadrahu, Mesahu in Abednegu; a Daniel je bil na dvoru kraljevem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 1, 'Nebukadnezar kralj je napravil podobo iz zlata, šestdeset komolcev visoko, šest komolcev široko; postavil jo je v ravnini Duri, v pokrajini Babilonski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 2, 'Nato je Nebukadnezar kralj poslal sklicat namestnike, deželne glavarje in oblastnike, višje sodnike, blagajnike, svetovalce, pravoznance in vse višje uradnike v pokrajinah, da pridejo k posvečevanju podobe, ki jo je bil postavil Nebukadnezar kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 3, 'Zbero se torej namestniki, deželni glavarji in oblastniki, višji sodniki, blagajniki, svetovalci, pravoznanci in vsi višji uradniki v pokrajinah k posvečevanju podobe, ki jo je postavil Nebukadnezar kralj; in stali so pred podobo, ki jo je postavil Nebukadnezar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 4, 'In glasnik je klical na vso moč: Vam se ukazuje, o ljudstva, narodi in jeziki:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 5, 'Brž ko zaslišite glas roga, piščali, citer, sambuke, strun, soglasnic in vsaktere godbe, padite in molite podobo zlato, ki jo je postavil Nebukadnezar kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 6, 'Kdor pa ne pade in ne moli, zdajci bo vržen v gorečo, razbeljeno peč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 7, 'Zatorej so padla, brž ko so slišali glas roga, piščali, citer, sambuke, strun in vsaktere godbe, vsa ljudstva, narodi in jeziki, poklanjajoč se podobi zlati, ki jo je postavil Nebukadnezar kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 8, 'Zato pristopijo tisti čas kaldejski možje, ki tožijo Jude.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 9, 'Izpregovore in reko kralju Nebukadnezarju: Kralj, žívi vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 10, 'Ti si, o kralj, izdal povelje, naj vsak, kdor zasliši glas roga, piščali, citer, sambuke, strun, soglasnic in katere koli godbe, pade in moli podobo zlato;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 11, 'in kdor ne pade in ne moli, bodi vržen v gorečo, razbeljeno peč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 12, 'So pa tu judovski možje, ki si jim poveril poslovodstvo pokrajine Babilonske: Sadrah, Mesah in Abednego; ti možje, o kralj, se ne menijo zate: tvojim bogovom ne služijo in podobe zlate, ki si jo postavil, ne molijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 13, 'Tedaj zapove Nebukadnezar, srdit in togoten, naj privedejo k njemu Sadraha, Mesaha in Abednega. In pripeljejo te može pred kralja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 14, 'Nebukadnezar izpregovori ter jim reče: Je li z namenom, Sadrah, Mesah in Abednego, da ne služite mojim bogovom in ne molite podobe zlate, ki sem jo postavil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 15, 'Sedaj pa, ako ste pripravljeni, kadar zaslišite glas roga, piščali, citer, sambuke, strun, soglasnic in vsaktere godbe, da padete in molite podobo, ki sem jo napravil, dobro; ako pa je ne boste molili, zdajci boste vrženi v gorečo, razbeljeno peč. In kdo je tisti bog, ki vas otme iz roke moje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 16, 'Sadrah, Mesah in Abednego odgovore in reko kralju: Nebukadnezar, ni nam treba tebi odgovarjati v tej reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 17, 'Bodisi, da nas Bog naš, ki mu služimo, more oteti iz goreče, razbeljene peči – in on nas otme iz tvoje roke, o kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 18, 'bodisi da ne, znano bodi tebi, kralj, da ne bomo služili bogovom tvojim in podobe zlate, ki si jo postavil, ne bomo molili!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 19, 'Tedaj se Nebukadnezar napolni jeze in pogled njegovega obličja se izpremeni zoper Sadraha, Mesaha in Abednega. In izpregovori pa veli, naj razbelijo peč sedemkrat bolj nego sicer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 20, 'In ukaže možem, najmočnejšim možem v vojski svoji, naj zvežejo Sadraha, Mesaha in Abednega ter jih vržejo v gorečo, razbeljeno peč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 21, 'Zvežejo torej tiste može v njih spodnjih in vrhnjih suknjah in plaščih in v drugih njih oblačilih in jih vržejo v gorečo, razbeljeno peč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 22, 'Vsled tega pa, ker je bilo kraljevo povelje naglo in peč nenavadno razgreta, je plamen umoril tiste može, ki so nesli gori Sadraha, Mesaha in Abednega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 23, 'A ti trije možje, Sadrah, Mesah in Abednego, so padli zvezani v sredo goreče, razbeljene peči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 24, 'Tedaj se prestraši Nebukadnezar kralj, hitro vstane in izpregovori ter reče svetovalcem svojim: Nismo li vrgli treh mož zvezanih v ogenj? Odgovore in reko kralju: Res je, o kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 25, 'Odgovori in reče: Glejte, vidim štiri može razvezane, hodeče posredi ognja, in ni jim nič zlega; in četrti je videti kakor sin bogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 26, 'Nato stopi Nebukadnezar pred isteje razbeljene peči, izpregovori in veli: Sadrah, Mesah in Abednego, Najvišjega Boga služabniki, pojdite ven in pridite sem! Tedaj pridejo Sadrah, Mesah in Abednego ven iz ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 27, 'In namestniki, deželni glavarji in oblastniki in svetovalci kraljevi so se zbrali in so videli, da ni imel ogenj nobene moči do njih teles: lasje na njih glavah niso bili osmojeni, tudi njih spodnje suknje se niso nič izpremenile in smod ognja jih ni bil prešinil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 28, 'Nebukadnezar izpregovori in reče: Hvaljen bodi Bog Sadrahov, Mesahov in Abednegov, ki je poslal angela svojega in otel služabnike svoje, ki so upali vanj in prestopili povelje kraljevo in žrtvovali telesa svoja, da ne bi služili nobenemu bogu in ga ne molili razen le svojega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 29, 'Zatorej bodi moja zapoved: V vsakem ljudstvu, narodu ali jeziku, kdor bi izrekel kaj pregrešnega zoper Boga Sadrahovega, Mesahovega in Abednegovega, bodi na kosce razsekan in hiša mu bodi izprevrnjena v gnojišče; zato ker ni drugega boga, ki more tako rešiti kakor ta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 3, 30, 'Nato je kralj povišal Sadraha, Mesaha in Abednega v pokrajini Babilonski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 1, 'Nebukadnezar kralj vsem ljudstvom, narodom in jezikom, ki prebivajo po vsej zemlji: Mir naj se vam pomnoži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 2, 'Vzvidelo se mi je, da oznanjam znamenja in čudeže, ki jih je Bog najvišji storil pri meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 3, 'Kako velika so znamenja njegova in čudeži njegovi kako mogočni! Kraljestvo njegovo je kraljestvo večno in gospostvo njegovo od roda do roda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 4, 'Jaz Nebukadnezar, ko sem pokojno živel v hiši svoji in srečo užival v palači svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 5, 'sem videl sanje, ki so me prestrašile; in premišljevanje na ležišču mojem in prikazni glave moje so me plašile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 6, 'Zato sem dal povelje, naj privedejo predme vse modrijane babilonske, da bi mi oznanili tistih sanj razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 7, 'Pridejo torej pismouki, rotilci, Kaldejci in vedeževalci, in jim povem sanje; ali niso mi oznanili njih razlage.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 8, 'Nazadnje pa stopi predme Daniel, ki mu je bilo ime Beltsazar po imenu boga mojega in v katerem je duh svetih bogov; in njemu povem sanje, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 9, 'Beltsazar, višji pismoukov, ker vem, da je v tebi svetih bogov duh ter da ti nobena skrivnost ni pretežka, povej mi prikazni mojih sanj, ki sem jih videl, in njih razlago!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 10, 'Prikazni glave moje na ležišču mojem pa so bile te: Videl sem, in glej: drevo stoji sredi zemlje, in višina njegova ogromna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 11, 'Drevo je postalo veliko in močno in visokost njegova je segala do neba, in bilo ga je videti do konca vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 12, 'Listje njegovo je bilo lepo in sad njegov obilen in živeža je bilo na njem dosti za vse; poljske zveri so imele senco pod njim in ptice nebeške so gnezdile na njegovih vejah in ž njim se je živilo sleherno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 13, 'Videl sem v prikaznih glave svoje na ležišču svojem, in glej: varuh in svetnik stopi doli z neba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 14, 'glasno vpije in tako veli: Posekajte drevo in mu porežite veje, posmukajte mu listje ter raztresite sad njegov! Zveri naj zbežé izpod njega in ptiči z vej njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 15, 'Toda panj njegov s koreninami pustite v zemlji, to pa v okovih železnih in bronastih, v travi na polju; in rosa nebeška naj ga moči in z zvermi mu bodi delež v travi zemeljski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 16, 'Človeško srce njegovo bodi izpremenjeno in dá naj se mu zverinsko srce; in sedem časov naj mine nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 17, 'Po sklepu varuhov je to poročilo in povelje svetih je ta beseda, da bi spoznali živeči, da vlada Najvišji v kraljestvu človeškem ter ga dá, komur hoče, in more najnižjega izmed ljudi postaviti nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 18, 'Te sanje sem videl jaz Nebukadnezar kralj; ti pa, Beltsazar, povej njih razlago, ker mi jih ne morejo razložiti vsi modrijani kraljestva mojega; ali ti moreš, ker v tebi je svetih bogov duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 19, 'Tedaj postoji Daniel, ki mu je ime Beltsazar, strmeč skoraj eno uro, in misli njegove ga plašijo. Kralj izpregovori in reče: Beltsazar, ne plašijo naj te sanje in njih razlaga! Beltsazar odgovori in reče: Gospod moj, da bi veljale sanje tvojim sovražilcem in neprijateljem tvojim njih razlaga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 20, 'Drevo, ki si ga videl, da je postalo veliko in močno in visokost njegova je segala do neba in ga je bilo videti po vesoljni zemlji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 21, 'in listje njegovo je bilo lepo in sad njegov obilen in živeža na njem dosti za vse, pod katerim so bivale poljske zveri in na njegovih vejah so gnezdile ptice nebeške:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 22, 'to si ti, o kralj, ki si postal velik in mogočen; kajti tvoja velikost je vzrasla in sega do neba in gospostvo tvoje do konca zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 23, 'A da je videl kralj varuha in svetnika, da je stopil z neba in velel: Posekajte drevo in ga izničite, toda panj njegov s koreninami pustite v zemlji, to pa v okovih železnih in bronastih, v travi na polju, in rosa nebeška naj ga moči in z zvermi poljskimi mu bodi delež, dokler ne mine sedem časov nad njim –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 24, 'to je razlaga, o kralj, in to je sklep Najvišjega, ki pride nad gospoda mojega, kralja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 25, 'Pahnejo te ven izmed ljudi in pri zverini poljski bode bivališče tvoje, in travo ti bodo dajali jesti kakor volom in rosa nebeška te bo močila, in sedem časov mine nad teboj, dokler ne spoznaš, da vlada Najvišji v kraljestvu človeškem ter ga dá, komur hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 26, 'In da so veleli, naj ostane drevesu panj s koreninami, pomeni, da ti bode kraljestvo zopet utrjeno, brž ko spoznaš, da vladajo nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 27, 'Zatorej ti bodi, o kralj, ugoden svet moj, da pretrgaj grehe svoje s pravičnostjo in krivice svoje z usmiljenostjo do ubogih, da se podaljša blagostanje tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 28, 'Vse to je prišlo nad kralja Nebukadnezarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 29, 'Ob koncu dvanajstih mesecev se je izprehajal po kraljevem dvoru v Babilonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 30, 'In je izpregovoril ter rekel: Ni li to veliki Babilon, ki sem ga zgradil za kraljevsko prebivališče z močjo mogočnosti svoje in v čast slave svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 31, 'Še je bila tista beseda v ustih kraljevih, pa pride glas z neba: Tebi, o kralj Nebukadnezar, se pravi: Kraljestvo ti je odvzeto!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 32, 'In spode te izmed ljudi in pri zverini poljski bode bivališče tvoje, travo ti bodo dajali jesti kakor volom in sedem časov mine nad teboj, dokler ne spoznaš, da vlada Najvišji v kraljestvu človeškem ter ga dá, komur hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 33, 'To uro se je izpolnila ta beseda pri Nebukadnezarju: bil je vržen izmed ljudi, in jedel je travo kakor voli in telo njegovo se je močilo z roso nebeško, da so mu lasje zrasli kakor orlom perje in nohti kakor ptičji kremplji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 34, 'Ob koncu tistih dni pa sem povzdignil jaz Nebukadnezar oči proti nebesom, in razum moj se mi je povrnil; in hvalil sem Najvišjega in slavil sem in poveličeval njega, ki večno živi, čigar gospostvo je večno gospostvo in kraljestvo njegovo od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 35, 'In vse prebivalce zemlje je šteti za nič, in po volji svoji ravna z vojsko nebeško in s prebivalci zemlje, in nikogar ni, ki more njegovi roki braniti in mu reči: Kaj delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 36, 'V tistem času se mi je povrnil razum moj in v čast mojega kraljestva se mi je povrnila slava moja in svetlost; in moji svetovalci in mogočneži so me iskali, in bil sem zopet postavljen v kraljestvo svoje in posebna velikost mi je bila pridejana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 4, 37, 'Sedaj jaz Nebukadnezar slavim, povišujem in poveličujem Kralja nebes, zakaj vsa dela njegova so resnica in pota njegova pravica; in tiste, ki žive prevzetno, zna on ponižati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 1, 'Belsazar kralj je napravil tisočim mogočnežem svojim veliko gostovanje in je pil vino pred tisočimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 2, 'Belsazar zapove, ko se je napil vina, naj prineso zlate in srebrne posode, ki jih je bil oče njegov Nebukadnezar vzel iz templja v Jeruzalemu, da bodo pili iz njih kralj in mogočneži njegovi, žene in priležnice njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 3, 'Tedaj prineso zlate posode, ki so bile vzete iz svetišča hiše Božje v Jeruzalemu; in pili so iz njih kralj in mogočneži njegovi, žene in priležnice njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 4, 'Pili so vino in hvalili bogove iz zlata in srebra, iz brona, železa, lesa in kamena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 5, 'V isti uri se pokažejo prsti človeške roke in pišejo, svetilniku nasproti, po pobeljeni steni kraljeve palače. In kralj je videl konec roke, ki je pisala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 6, 'Tedaj se izpremeni jasno lice kraljevo in misli njegove ga preplašijo, in vezi njegovega ledja se razrešijo in koleni trkata drugo ob drugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 7, 'Kralj glasno zakliče, naj pripeljejo noter rotilce, Kaldejce in vedeževalce. Potem kralj izpregovori in veli modrijanom babilonskim: Kdor koli prečita to pismo in mi oznani njega razlago, bo oblečen v škrlat, dobi zlato verižico na vrat in bode tretji oblastnik v kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 8, 'Nato pridejo vsi modrijani kraljevi; a niso mogli čitati pisma, ne oznaniti kralju razlage njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 9, 'Tedaj se kralj Belsazar silno prestraši in barva v licu se mu izpremeni, in mogočneži njegovi so bili v strahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 10, 'Vsled besed kraljevih in mogočnežev njegovih stopi stara kraljica v jedilno dvorano. Kraljica izpregovori in reče: Kralj, žívi vekomaj! Naj te ne plašijo misli tvoje in ne izpremeni se naj jasnost lica tvojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 11, 'Je mož v kraljestvu tvojem, v katerem je svetih bogov duh; in v dneh očeta tvojega se je pokazalo v njem razsvetljenje in razumnost in modrost enaka modrosti bogov; in kralj Nebukadnezar, oče tvoj, ga je postavil za višjega pismoukov, rotilcev, Kaldejcev in vedeževalcev, tvoj oče, o kralj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 12, 'zato ker je imel tisti Daniel, ki mu je kralj dal ime Beltsazar, odličnega duha in znanje in razumnost, da je razlagal sanje in razjasnjeval zagonetke in razreševal zamotane reči. Pokličejo naj torej Daniela, in on oznani razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 13, 'Nato so pripeljali Daniela pred kralja. Kralj izpregovori in reče Danielu: Si li ti Daniel, eden iz ujetnikov Judovih, ki jih je pripeljal z Judovega kralj, oče moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 14, 'Slišal sem zate, da je duh bogov v tebi ter da so našli pri tebi razsvetljenje in razumnost in izredno modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 15, 'In sedaj so bili pripeljani predme modrijani, rotilci, da bi prečitali to pismo in mi oznanili njega razlago; ali ne morejo pomena stvari razložiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 16, 'O tebi sem pa slišal, da moreš dati razlago in razrešiti zamotane reči. Če torej moreš prečitati to pismo in mi njega razlago oznaniti, boš oblečen v škrlat, zlato verižico dobiš na vrat in tretji oblastnik bodeš v kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 17, 'Tedaj odgovori Daniel in reče kralju: Darovi tvoji naj ostanejo tebi in darila svoja daj drugemu; vendar prečitam pismo kralju in mu oznanim razlago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 18, 'Ti, o kralj! Bog Najvišji je dal Nebukadnezarju, očetu tvojemu, kraljestvo in velikost in čast in slavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 19, 'in zavoljo velikosti, ki mu jo je dal, so trepetala vsa ljudstva, vsi narodi in jeziki in se ga bali. Kogar je hotel, je ubil, in kogar je hotel, je ohranil živega; kogar je hotel, je poveličal, in kogar je hotel, je ponižal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 20, 'Toda ko se je prevzelo srce njegovo in se je zakrknil duh njegov in je postal prezaupen, je bil pahnjen s kraljevskega prestola in njegovo veličastvo mu je bilo vzeto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 21, 'In vržen je bil izmed otrok človeških in srce mu je postalo enako zverinskemu in bivališče je imel z divjimi osli; redili so ga s travo kakor vole in telo njegovo se je močilo z roso nebeško, dokler ni spoznal, da Bog Najvišji vlada v kraljestvu človeškem ter postavi čezenj, kogar hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 22, 'In ti, Belsazar, sin njegov, si nisi ponižal srca svojega, čeprav si vedel to vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 23, 'A ti si se povzdignil zoper Gospoda nebes; in prinesli so predte posode hiše njegove, ti pa in mogočneži tvoji, žene in priležnice tvoje, vi ste pili vino iz njih. In hvalil si bogove iz srebra in zlata, iz brona, železa, lesa in kamena, ki ne vidijo, ne slišijo in ne čutijo; Boga pa, v čigar roki je dihanje tvoje in pri katerem so vsa pota tvoja, nisi poslavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 24, 'Tedaj je bil poslan del tiste roke izpred Njega in to pismo narisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 25, 'In to je pismo, ki je bilo narisano: MENE, MENE, TEKEL UFARSIN.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 26, 'To pa je razlaga reči: MENE: seštel je Bog kraljevanje tvoje in mu naredil konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 27, 'TEKEL: pretehtan si bil na tehtnici in prelehak si se izkazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 28, 'PERES: razdeljeno je kraljestvo tvoje in dano Medom in Peržanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 29, 'Tedaj zapove Belsazar, in oblekli so Daniela v škrlat in mu deli zlato verižico okoli grla in razglasili, da bodi tretji oblastnik v kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 30, 'Še to noč je bil umorjen Belsazar, kralj Kaldejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 5, 31, 'In Darij Medec je dobil kraljestvo, ko je bil blizu dvainšestdeset let star.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 1, 'Vzvidelo se je pa Dariju postaviti nad kraljevino sto in dvajset namestnikov, ki naj bodo po vsej kraljevini,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 2, 'in čeznje tri vojvode, katerih eden je bil Daniel: da jim bodo dajali račune tisti namestniki ter da kralj ne bo imel škode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 3, 'Tedaj je ta Daniel nadkriljeval vojvode in namestnike, ker je bil odličen duh v njem; in kralj ga je mislil postaviti nad vse kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 4, 'Tedaj so vojvode in namestniki gledali, kako bi našli kaj zoper Daniela, da bi ga tožili zastran kraljestva; ali niso mogli dobiti razloga za tožbo, ne hudega dejanja, zato ker je bil zvest in pregreška ali hudega dejanja ni bilo zaslediti pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 5, 'Nato so rekli tisti možje: Ne dobimo razloga za tožbo zoper tega Daniela, razen če najdemo kaj zoper njega, kar zadeva Boga njegovega postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 6, 'Potem se ta vojvoda in namestniki pripodé h kralju ter ga ogovore takole: Kralj Darij, žívi vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 7, 'Vsi vojvode kraljestva, oblastniki in namestniki, svetovalci in deželni glavarji, so se posvetovali in sklenili, naj se postavi kraljev zakon in izda ostra prepoved: kdorkoli bo v tridesetih dneh kaj prosil kateregasibodi boga ali človeka razen tebe, o kralj, bodi vržen v levnjak!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 8, 'Sedaj torej, o kralj, izdaj to prepoved in podpiši spis, ki se ne sme izpremeniti po postavi Medov in Peržanov, ki je neomajna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 9, 'Zatorej je kralj Darij podpisal spis in prepoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 10, 'In ko je Daniel zvedel, da je spis podpisan, je šel v hišo svojo (imel pa je v zgornji sobi svoji odprta okna proti Jeruzalemu) in je trikrat vsak dan padel na kolena in molil in se zahvaljeval pred Bogom svojim, prav kakor je delal poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 11, 'Tedaj se pripode ti možje in zalotijo Daniela, da moli in milo prosi pred Bogom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 12, 'Potem pristopijo in govore pred kraljem glede kraljeve prepovedi: Nisi li podpisal prepovedi, da bodi vsak, ki bo v tridesetih dneh prosil kaj katerega boga ali človeka razen tebe, o kralj, vržen v levnjak? Kralj odgovori in reče: Res je to po postavi Medov in Peržanov, ki je neomajna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 13, 'Nato odgovore in reko pred kraljem: Tisti Daniel, ki je izmed ujetnikov iz Judeje, se ne meni zate, o kralj, ne za prepoved, ki si jo podpisal, temuč trikrat na dan opravlja svojo molitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 14, 'Kralju pa, ko je slišal te besede, ni bilo nikakor pogodu in se je namenil v srcu, da reši Daniela; in do solnčnega zahoda si je prizadeval ga oteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 15, 'Tedaj se pripode ti možje h kralju in mu reko: Vedi, o kralj, da je pri Medih in Peržanih postava, da se ne sme izpremeniti nobena prepoved, ne naredba, ki jo je kralj postavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 16, 'Nato kralj zapove, in pripeljejo Daniela ter ga vržejo v levnjak. Kralj izpregovori in reče Danielu: Bog tvoj, ki mu služiš neprestano, on naj te reši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 17, 'In prineso kamen ter ga polože vrhu jame, in kralj ga zapečati s prstanom svojim in s svojih mogočnežev prstani, da bi se glede Daniela nič ne izpremenilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 18, 'Nato odide kralj v palačo svojo ter prenoči ob postu, ne dovoli žen pripeljati predse, in spanje ga mine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 19, 'In vstane kralj z jutranjo zarjo, ko se je svitalo, in hitro gre k levnjaku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 20, 'In ko se približa jami, zavpije po Danielu z žalostnim glasom. Kralj izpregovori in reče Danielu: O Daniel, živega Boga služabnik, ali te je mogel Bog tvoj, ki mu služiš neprestano, rešiti levov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 21, 'Nato reče Daniel kralju: O kralj, žívi vekomaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 22, 'Moj Bog je poslal angela svojega, in zaprl je žrela levom, da mi niso škodovali, kajti pred njim sem bil spoznan za nedolžnega, in tudi pred teboj, kralj, nisem storil nič žalega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 23, 'Tega se kralj silno oveseli in zapove, naj izvlečejo Daniela iz jame. In potegnejo Daniela iz jame, in nobene poškodbe ni bilo videti na njem, ker je upal v Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 24, 'In kralj zapove, in pripeljejo tiste može, ki so ovadili Daniela, in vržejo v levnjak nje, njih otroke in žene; in niso še prileteli do tal v jamo, že so jih levi zgrabili ter jim vse kosti strli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 25, 'Tedaj je kralj Darij pisal vsem ljudstvom, narodom in jezikom, ki prebivajo po vsej zemlji: Mir naj se vam pomnoži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 26, 'Povelje dajem, da naj po vsej kraljevini, kamor sega gospostvo moje, ljudje trepetajo in se boje Boga Danielovega; zakaj on je živi Bog in ostane večno, in gospostvo njegovo bo trajalo do konca;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 27, 'on rešuje in otimlje ter dela znamenja in čudeže na nebu in na zemlji: ta je otel Daniela iz oblasti levov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 6, 28, 'In ta Daniel je imel srečo ob kraljevanju Darija in ob kraljevanju Cira, Perzijca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 1, 'V prvem letu Belsazarja, kralja v Babilonu, je videl Daniel sanje in prikazni glave svoje na ležišču svojem. Potem je spisal sanje in razložil vsebino stvari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 2, 'Daniel je govoril in rekel: Videl sem v prikazni svoji po noči, in glej, štirje vetrovi neba so se zagnali nad veliko morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 3, 'In štiri zveri velike, med seboj različne, so prišle iz morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 4, 'Prva je bila kakor lev in je imela peruti orlove; gledal sem, dokler niso bile nje peruti izpukane, in bila je povzdignjena od zemlje in postavljena na noge kakor človek, in človeško srce ji je bilo dano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 5, 'In glej, druga zver in drugačna, podobna medvedu; in vzdignila se je po eni strani, in tri rebra je imela v gobcu med zobmi. In tako ji je bilo rečeno: Vstani, požri veliko mesa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 6, 'Potem sem gledal, in glej, druga zver, podobna pardu, in imela je na hrbtu štiri peruti kakor ptica; in ta zver je imela štiri glave in dano ji je bilo gospostvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 7, 'Potem sem videl v prikaznih po noči: in glej, četrta zver, grozovita in strašna in silno močna, in imela je velike zobe železne; žrla je in v kosce drobila in, kar je ostalo, je poteptala z nogami; in bila je različna od vseh zveri, ki so bile pred njo, in je imela deset rogov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 8, 'Ko sem opazoval tiste rogove, glej, vzrastel je med njimi drug rog, prav majhen, pred katerim so bili izdrti prvih rogov trije; in glej, na tem rogu so bile oči kakor človeške oči in usta, govoreča velike reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 9, 'Gledal sem, dokler so postavili prestole, in Predvečni se je posadil: oblačilo njegovo je bilo belo kakor sneg in lasje glave njegove kakor čista volna, prestol njegov plameni ognja in kolesa pri njem goreč ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 10, 'Reka ognjena je izvirala in tekla izpred njega: tisoči tisočev so mu služili in miriad miriade so stale pred njim. Sodba je sedla in knjige so se odprle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 11, 'Gledal sem vedno, kaj bo zaradi glasu prevelikih besed, ki jih je rog govoril; gledal sem, dokler ni bila zver ubita in telo njeno umorjeno in izročeno ognju v sežig.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 12, 'In kar se tiče drugih zveri: gospostvo jim je bilo vzeto, ali življenje jim je bilo podaljšano do časa in ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 13, 'Videl sem v prikaznih po noči, in glej, z oblaki nebeškimi je prihajal eden kakor sin človekov, in prišel je k Predvečnemu, in privedli so ga predenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 14, 'In dano mu je bilo gospostvo in slava in kraljestvo, da naj mu služijo vsa ljudstva, narodi in jeziki; njegovo gospostvo je večno gospostvo, ki nikdar ne mine, in kraljestvo njegovo takšno, ki se nikoli ne pokonča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 15, 'Meni pa, Danielu, je bil duh izbegan v telesu, in prikazni glave moje so me plašile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 16, 'Pristopim k enemu tam stoječih, da ga poprosim resnice glede vsega tega. In povedal mi je in oznanil razlago teh reči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 17, 'Te zveri velike, ki so štiri, so štirje kralji, ki vstanejo iz zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 18, 'Toda svetniki Najvišjega prejmejo kraljestvo in obdrže kraljestvo na vekomaj, da, do vekov večnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 19, 'Nato sem želel vedeti resnico glede četrte zveri, ki je bila različna od vseh drugih, silno grozovita, imela zobe železne in kremplje bronaste, ki je žrla, na kosce drobila in ostanek teptala z nogami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 20, 'in glede deseterih rogov na njeni glavi in glede drugega roga, ki je vzrastel in so spričo njega odpadli trije, tistega roga, ki je imel oči in usta, govoreča velike reči, in ki je bil videti debelejši nego tovariši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 21, 'Videl sem, kako se je tisti rog vojskoval s svetimi in jih premagoval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 22, 'dokler ni prišel Predvečni, in sodba je bila izročena svetim Najvišjega, in prišel je čas, da so sveti v last dobili kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 23, 'Tako mi je dejal: Četrta zver bo četrto kraljestvo na zemlji, ki bode različno od vseh kraljestev, in požre vso zemljo ter jo pogazi in razdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 24, 'In zastran tistih desetih rogov: iz tega kraljestva vstane deset kraljev; in drug kralj vstane za njimi in ta bode različen od prejšnjih in poniža tri kralje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 25, 'In govoril bo besede zoper Najvišjega in zatiral svetnike Najvišjega, in namerjal bo premeniti čase in postavo, in dani bodo v roko njegovo čas, dva časa in pol časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 26, 'Ali sodba bo sedla; in vzeli mu bodo gospostvo, da se uniči in zatre do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 27, 'In kraljestvo in gospostvo in velikost kraljestev pod vsem nebom se bo dala ljudstvu svetnikov Najvišjega. Njegovo kraljestvo je večno kraljestvo in vsa gospostva mu bodo služila ter ga poslušala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 7, 28, 'Dotlej konec stvari. Mene, Daniela, so plašile misli moje silno in jasnost lica mojega se je na meni izpremenila; a stvar sem ohranil v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 1, 'V tretjem letu kraljevanja kralja Belsazarja sem videl jaz, Daniel, prikazen po tisti, ki se mi je prikazala v začetku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 2, 'In videl sem v prikazni; bilo pa je, ko sem videl, da sem bil v gradu Susanu, ki je v Elamski pokrajini; in videl sem v prikazni, in bil sem pri reki Ulaju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 3, 'In povzdignem oči in vidim: in glej, oven stoji pred reko, ta ima dva roga, in tista rogova sta visoka, in eden je bil višji od drugega, in višji je vzrastel naposled.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 4, 'Videl sem, da oven drega proti zahodu in proti severu in proti jugu, in nobena zver ne more stati pred njim, tudi ni nikogar, ki bi otel iz roke njegove; in delal je, kakor ga je bila volja, in je postal velik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 5, 'In ko sem opazoval, glej, kozel pride od zahoda čez vso zemljo, a tal se ni dotaknil; in tisti kozel je imel imeniten rog med očmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 6, 'In pride k tistemu ovnu z dvema rogoma, ki sem ga videl stoječega pred reko; in se zaleti vanj v togoti moči svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 7, 'In videl sem ga, da se prižene prav do ovna in se razkači zoper njega in udari ovna ter zlomi obadva roga njegova; in ni bilo moči v ovnu, da bi stal pred njim. In zvrne ga na tla in ga pogazi, in ni ga bilo, ki bi otel ovna iz roke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 8, 'Kozel pa se je silno poveličal; in ko je postal mogočen, se mu zlomi veliki rog, in štirje imenitni rogovi zrastejo namesto njega proti štirim vetrovom neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 9, 'In iz enega od njih priraste majhen rog in postane nenavadno velik proti jugu in proti vzhodu in proti deželi dike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 10, 'In povzdigne se proti vojski nebeški in vrže nekaj vojske in zvezd nebeških doli na zemljo ter jih pogazi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 11, 'Celo proti Vojvodi vojske se je povzdignil in mu vzel neprestano daritev in svetišča Njegovega kraj je porušil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 12, 'In vojska mu je bila dana zoper neprestano daritev zavoljo pregrehe; in zvrnil je resnico na tla in delal je po volji svoji in imel srečo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 13, 'In slišal sem svetnika govoriti, in drug svetnik reče tistemu, ki je govoril: Doklej velja ta prikazen o neprestani daritvi in o pregrehi, ki povzroča opustošenje, da se izročita svetišče in vojska v poteptanje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 14, 'In mi reče: Do dva tisoč tristo večerov in juter; potem bo svetišče očiščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 15, 'Zgodi se pa, ko sem jaz, Daniel, videl prikazen, da sem jo želel razumeti; in glej, stoji pred menoj kakor podoba moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 16, 'In slišim človeški glas izmed ulajskih bregov, ki kliče in veli: Gabriel, razloži temu prikazen, da jo razume!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 17, 'In stopi tja, kjer sem stal, in ko pristopi, se ustrašim in padem na obraz. In mi reče: Pazi, sin človečji! kajti ta prikazen meri na čas konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 18, 'In ko govori z menoj, padem omamljen z obrazom na zemljo; on pa se me dotakne in me postavi, kjer sem stal prej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 19, 'In reče: Glej, jaz ti oznanim, kar se zgodi ob poslednjem času jeze Božje; kajti to meri na določeni čas konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 20, 'Oven z dvema rogoma, ki si ga videl, so kralji Medije in Perzije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 21, 'Kosmati kozel pa je kralj grški, in veliki rog, ki je bil med njegovimi očmi, je kralj prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 22, 'In da se je zlomil in so štirje zrasli namesto njega, pomeni: štiri kraljestva vstanejo iz tega naroda, ali ne z močjo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 23, 'In ob koncu njih kraljestva, ko dovrše pregrešniki mero, vstane kralj drznega obraza in zvijačen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 24, 'In njegova mogočnost se okrepi, ali ne po lastni moči njegovi; in napravi čudovito pogubo in bo imel srečo in bo delal po svoji volji; in pogubljal bo mogočne in ljudstvo svetih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 25, 'In po prebrisanosti njegovi bo prevara napredovala v njegovi roki; in veličal se bo v srcu svojem in iznenada pogubi mnoge; vzpne se tudi zoper Kneza knezov, ali zatrt bo brez roke človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 26, 'In prikazen o večerih in jutrih, o kateri se je govorilo, je resnica; ti pa hrani na skrivnem to prikazen, ker še je mnogo dni dotlej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 8, 27, 'Jaz Daniel pa sem oslabel in sem bil bolan nekoliko dni. Potem sem vstal in opravljal posle kraljeve; in strmel sem nad prikaznijo, in ni ga bilo, ki bi razumel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 1, 'V prvem letu Darija, sinu Ahasverjevega, iz zaroda Medcev, ki je zakraljeval državi Kaldejcev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 2, 'v prvem letu kraljevanja njegovega sem jaz Daniel obrnil pozornost v pismih na število let, o katerih se je zgodila beseda Gospodova Jeremiju proroku, da se ima dopolniti razvalinam Jeruzalema sedemdeset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 3, 'In obrnil sem obličje h Gospodu Bogu, da bi ga iskal z molitvijo in s prošnjami, ob postu, raševniku in pepelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 4, 'In molil sem h Gospodu, svojemu Bogu, in sem pripoznaval grehe ter dejal: Ah, Gospod! veliki in strašni Bog mogočni, ki hrani zavezo in milost tistim, ki ga ljubijo in izpolnjujejo zapovedi njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 5, 'Grešili smo in popačeno ravnali in brezbožno delali, in uprli smo se, ker smo odstopili od zapovedi in pravic tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 6, 'In nismo poslušali služabnikov tvojih, prorokov, ki so v tvojem imenu govorili kraljem našim, knezom in očetom našim in vsemu ljudstvu dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 7, 'Tebi, o Gospod, gre pravičnost, nam pa osramotitev obraza, kakor je danes: možem Judovim in prebivalcem jeruzalemskim in vsem Izraelcem, ki so blizu in ki so daleč po vseh deželah, kamor si jih razkropil zavoljo nezvestobe, ki so jo zakrivili zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 8, 'O Gospod, nam gre osramotitev obraza, našim kraljem, našim knezom in očetom, ker smo grešili zoper tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 9, 'Pri Gospodu, našem Bogu, je obilo usmiljenje in odpuščenje; kajti uprli smo se mu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 10, 'in nismo poslušali glasu Gospoda, Boga svojega, da bi hodili po postavah njegovih, ki nam jih je del pred oči po hlapcih svojih, prorokih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 11, 'Ampak ves Izrael je prestopil postavo tvojo in se odvrnil, da ni poslušal tvojega glasu. Zato se je razlilo na nas prokletstvo in prisega, ki je zapisana v zakonu Mojzesa, hlapca Božjega, ker smo grešili zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 12, 'In izpolnil je besede svoje, ki jih je govoril zoper nas in zoper naše sodnike, ki so nas sodili, s tem, da je spravil nad nas veliko nesrečo, da se ni zgodilo pod vsem nebom kaj takega, kakor se je zgodilo v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 13, 'Prav tako, kakor je pisano v zakonu Mojzesovem, je prišla vsa ta nesreča nad nas; vendar nismo ponižno prosili obličja Gospoda, Boga svojega, da bi se bili odvrnili od krivic svojih in prejeli razumnost v resnici tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 14, 'Zato je Gospod čuval nad nesrečo in jo pripeljal nad nas. Kajti pravičen je Gospod, Bog naš, v vseh delih svojih, ki jih dela, mi pa nismo poslušali glasu njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 15, 'In sedaj, o Gospod, Bog naš, ki si peljal ljudstvo svoje iz dežele Egiptovske z mogočno roko in si storil sebi ime, kakor je današnji dan: grešili smo, brezbožno smo ravnali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 16, 'O Gospod, po vsej svoji pravičnosti odvrni, prosim, jezo svojo in srd svoj od mesta Jeruzalema, gore svetosti svoje! zakaj zaradi grehov naših in krivic naših očetov je prišel Jeruzalem in ljudstvo tvoje v zasrambo vsem, ki so okoli nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 17, 'In sedaj poslušaj, o Bog naš, molitev hlapca svojega in ponižne prošnje njegove in razjasni obličje svoje nad svojim svetiščem, ki je opustošeno, zavoljo Gospoda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 18, 'Nagni uho, o Bog moj, in čuj, odpri oko in poglej pustote naše in mesto, ki se zove po imenu tvojem. Kajti ne na podlagi pravičnosti svoje padamo na tla in milo prosimo pred tvojim obličjem, ampak na podlagi preobilega usmiljenja tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 19, 'O Gospod, čuj, Gospod, odpusti, Gospod, poslušaj in delaj! ne odlašaj, zaradi sebe, o Bog moj! ker mesto in ljudstvo tvoje se zoveta po tvojem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 20, 'Ko sem še govoril in molil in pripoznaval greh svoj in greh ljudstva svojega Izraela in ponižno prosil pred obličjem Gospoda, svojega Boga, za sveto goro svojega Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 21, 'ko sem še govoril v molitvi, prileti hitro mož Gabriel, ki sem ga bil videl v prikazni v začetku, in se me dotakne v času večerne daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 22, 'In poučil me je ter je z menoj govoril in dejal: Daniel, zdaj sem prišel, da ti razsvetlim razum.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 23, 'V začetku prošenj tvojih je izšla beseda, in prišel sem, da ti jo oznanim, ker si drag in ljubljen. Zato pazi na besedo in umej prikazen:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 24, 'Sedemdeset tednov je odločenih nad ljudstvom tvojim in nad svetim mestom tvojim, da preneha odpad in se naredi konec grehom ter da se stori poravnava za krivico in se privede večna pravičnost in se zapečati prikazen in proroštvo in da se pomazili Najsvetejše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 25, 'Vedi torej in razumej: Odkar izide povelje, da naj se obnovi in pozida Jeruzalem, do Maziljenca, Vojvode, bode sedem tednov, in dvainšestdeset tednov. Mesto se obnovi in pozida z ulicami in z obzidjem, in to v časih stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 26, 'In po tistih dvainšestdesetih tednih bo Maziljenec iztrebljen in nič mu ne ostane. In ljudstvo vojvode, kateri pride, razdene mesto in svetišče; in konec tega bode v povodnji, in prav do konca bode vojska, določene pustote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 9, 27, 'In trdno zavezo sklene z mnogimi za en teden in sredi tedna stori, da neha klalna in jedilna daritev. In na perutih gnusob pride pustošnik; in do pokončanja, trdno določenega, se izlije jeza nad pustošnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 1, 'V tretjem letu Cira, kralja v Perziji, je bila beseda razodeta Danielu, čigar ime je bilo Beltsazar; in beseda je resnica in govori o veliki stiski. In umel je besedo in je dobil razumnost o prikazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 2, 'V tistih tednih sem jaz Daniel žaloval tri cele tedne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 3, 'Dobrih jedi nisem užival, tudi meso in vino ni prišlo v usta moja, tudi se nisem nič mazilil, dokler se niso dopolnili trije celi tedni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 4, 'In štiriindvajseti dan prvega meseca sem bil na bregu velike reke, ki je Hidekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 5, 'In povzdignem oči in vidim, glej, moža oblečenega v platno, čigar ledje je bilo opasano s čistim zlatom iz Ufaza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 6, 'in telo njegovo je bilo kakor hrizolit in obraz se mu je svetil kakor blisk, in oči njegove kakor plamenice goreče, roke pa in noge njegove kakor lice svetlega brona, in glas besed njegovih kakor glas množice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 7, 'In jaz, Daniel, sem videl to prikazen sam, možje pa, ki so bili z menoj, je niso videli, toda prevzel jih je velik strah, da so zbežali ter se skrili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 8, 'In ostal sem sam in videl to veliko prikazen; in moči ni ostalo v meni in barva v licu se mi je izpremenila, da je bilo spačeno, in nič moči nisem imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 9, 'Vendar sem slišal besed njegovih glas, in ko zaslišim glas njegovih besed, padem omamljen na obraz, z obrazom na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 10, 'In glej, roka se me dotakne in mi pomore na omahujoča kolena moja in roke moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 11, 'In mi reče: Daniel, mož dragi in ljubljeni! umej besede, ki ti jih govorim, in stoj na svojem mestu; kajti k tebi sem poslan sedaj. In ko mi je izgovoril to besedo, vstanem, tresoč se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 12, 'Tedaj mi veli: Ne boj se, Daniel! zakaj od prvega dne, ko si namenil srce svoje, da dobiš razumnost in da se ponižaš pred Bogom svojim, so bile uslišane besede tvoje; in jaz sem prišel zaradi besed tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 13, 'Ali stal mi je nasproti knez kraljestva perzijskega edenindvajset dni, in glej, Mihael, eden prvih knezov, mi je prišel na pomoč, in zmagal sem tam pri kraljih perzijskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 14, 'In prišel sem, da ti dodelim uma za to, kar se bo godilo ljudstvu tvojemu poslednje dni; kajti prikazen velja še za mnoge dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 15, 'In ko mi je govoril s temi besedami, sem pobesil lice k zemlji in sem onemel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 16, 'In glej, nekdo, podoben sinom človeškim, se dotakne ustnic mojih; tedaj odprem usta in govorim in rečem tistemu, ki je stal pred menoj: Gospod moj, zavoljo te prikazni so me prevzele bolečine in nič moči mi ni ostalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 17, 'Kajti kako more tega mojega gospoda hlapec govoriti s tem mojim gospodom? In odsedaj ni nič več moči v meni in sape mi ni ostalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 18, 'Tedaj se me zopet dotakne nekdo, ki je bil videti kakor človek, in me pokrepča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 19, 'In veli: Ne boj se, mož dragi in ljubljeni! mir tebi, bodi močan, bodi, pravim, močan! In ko mi je govoril, sem bil pokrepčan in sem dejal: Govóri, gospod moj, kajti pokrepčal si me.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 20, 'Tedaj mi reče: Veš li, zakaj sem prišel k tebi? In sedaj se vrnem, da se bom bojeval s knezom Perzije; a brž ko izidem, pride knez grškega kraljestva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 10, 21, 'Vendar ti hočem povedati, kaj je zapisano v knjigi resnice. In ni nikogar, ki bi mi bil na strani zoper one razen Mihaela, kneza vašega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 1, 'In tudi jaz sem v prvem letu Darija Meda stal pri njem kot pomočnik in zaščitnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 2, 'In sedaj ti oznanim resnico: Glej, še trije kralji vstanejo v Perziji; in četrti pridobi večje bogastvo nego vsi, in ko postane mogočen po bogastvu svojem, nadraži vse proti grškemu kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 3, 'In vstane mogočen kralj, ki bo gospodoval z veliko močjo in delal, kar mu bode pogodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 4, 'In kakor vstane hitro, se razdrobi kraljestvo njegovo in se razdeli na štiri vetrove neba. A ne bode za potomce njegove in ne ostane v taki moči, s kakršno je on gospodoval; kajti kraljestvo njegovo bo raztrgano in da dobé drugi, mimo teh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 5, 'In kralj na jugu postane mogočen, in sicer eden iz knezov njegovih, in bode mogočnejši nego on in bo gospodoval: gospostvo njegovo bode veliko gospostvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 6, 'In ko mine nekoliko let, se bosta zvezala; in hči kralja na jugu pride k severnemu kralju, da napravi poravnavo. A ne ohrani moči rame svoje, tudi on se ne vzdrži, ne rama njegova; in bo izdana v smrt, ona in kateri so jo pripeljali in njen roditelj, ki jo je podpiral v tistih časih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 7, 'Vstane pa na mestu njegovem odrastek iz njene korenine, ki pride zoper vojsko in vdere v trdnjavo kralja na severu, in bo svojevoljno ravnal zoper nje in zmagal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 8, 'in odpelje tudi njih bogove z ulitimi njih podobami in ž njih dragimi posodami iz srebra in zlata v ujetništvo v Egipt; in bo vztrajal dosti let pred kraljem na severu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 9, 'Ta pride sicer v državo kralja na jugu, a vrne se zopet v deželo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 10, 'Toda sinovi njegovi bodo pripravljali vojno in zbero množico velikih vojsk, in eden pridere in poplavi vse kakor povodenj; in vrne se, in bodo se bojevali tja do trdnjave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 11, 'In južni kralj se razkači in pride in se bo bojeval ž njim, kraljem na severu; in ta postavi v boj veliko množico, ali množica bo dana v roke južnemu kralju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 12, 'In ko bo množica odpravljena, mu vzraste pogum; in jih podere na tisoče, a močan ne ostane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 13, 'In severni kralj pride zopet in postavi v boj množico večjo, nego je bila prejšnja; in ko minejo časi let, pridere na čelu vojske velike in obilo preskrbljene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 14, 'In v tistih časih jih mnogo vstane zoper kralja na jugu; in siloviti sinovi tvojega ljudstva se vzdignejo, da izpolnijo prikazen, toda padejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 15, 'In pride severni kralj in nanosi nasip in se polasti utrjenega mesta; in vojne moči z juga se ne vzdrže, tudi izbrano moštvo njegovo ne bo imelo moči, da se vzdrži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 16, 'In tisti, ki je prišel zoper njega, bo delal, kar mu bode pogodi, in nihče se ne bo mogel vzdržati vpričo njega; in nastani se v deželi dike, in pokončevanje bode v roki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 17, 'In obličje nameri v to, da pride z močjo vsega kraljestva svojega in stori ž njim poravnavo; in dá mu hčer žená, da jo pogubi; a ona se ne vzdrži in nič mu ne bo koristila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 18, 'In obrne obličje proti otokom in se polasti mnogih; toda vojskovodja stori konec njegovemu zasramovanju, gotovo mu povrne zasramovanje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 19, 'In obrne obličje proti trdnjavam dežele svoje, a izpoddrsne se mu in pade, in ne bo ga več najti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 20, 'In na mestu njegovem vstane eden, ki bo velel izterjevalcu davkov, naj prehodi kras kraljestva; a v malo dneh bo strt, in sicer ne po jezi, ne po vojski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 21, 'In na njegovem mestu vstane zaničevanec, ki mu ne namenijo kraljevske časti; pride pa iznenada in se polasti kraljestva s prilizovanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 22, 'In vojne moči, ki vse preplavljajo, bodo pred njim poplavljene in strte in celo knez njegove zaveze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 23, 'Kajti odkar se je zavezal ž njim, bo ravnal prekanljivo, in pojde gori in si pridobi moč z neznatnim ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 24, 'V času miru pridere v najbolj rodovitne kraje dežele, in delal bo, česar niso delali očetje njegovi, ne njegovih očetov očetje; rop in plen in blago jim razmeče in snoval bo naklepe svoje zoper trdnjave, nekoliko časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 25, 'In obudi moč svojo in pogum svoj zoper južnega kralja z veliko vojsko. In kralj na jugu se bo pripravljal na boj z veliko in jako močno vojsko; toda ne vzdrži se, ker bodo kovali naklepe zoper njega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 26, 'in kateri jedo z mize njegove jed, ga uničijo, in vojska njegova se razkropi; in prebodeni padejo mnogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 27, 'In tista dva kralja bosta imela hudobno nakano v srcu in pri isti mizi bosta govorila laž; ali ne posreči se, kajti konec pride šele ob določenem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 28, 'In vrne se severni kralj v deželo svojo z obilnim blagom, in srce njegovo bode zoper sveto zavezo, in delal bo po svoji volji in se vrnil v deželo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 29, 'Ob določenem času se vrne in pride na jug, toda ne bode poslednje, kakor je bilo v začetku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 30, 'Kajti ladje s Kitima pridejo zoper njega, zato obupa in se vrne, in raztogoti se zoper sveto zavezo in bo delal po svoji volji; povrne se in bo pazil na tiste, ki opuščajo sveto zavezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 31, 'In vojne trume mu bodo stale na strani, in oskrunijo svetišče, trdnjavo, in odpravijo neprestano daritev in postavijo gnusobo, ki povzroča opustošenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 32, 'In s prilizovanjem zapelje v odpad tiste, ki krivično ravnajo zoper zavezo; ljudstvo pa, ki pozna Boga svojega, se izkaže močno in bo po junaško delalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 33, 'In razumni med ljudstvom bodo poučevali mnoge, toda padali bodo pod mečem in v ognju, v ujetništvu in po plenjenju dosti dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 34, 'Ko pa bodo padali, jim pride v olajšanje majhna pomoč; in veliko se jih jim pridruži po hinavsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 35, 'In izmed razumnih bodo nekateri popadali, da se prečistijo, pretrebijo in ubelijo do časa konca; kajti trajalo bo prav do določenega časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 36, 'In kralj bo delal, kar mu bode pogodi, in se bo povzdigoval in poveličeval nad vsakega boga ter bo govoril čudovito zoper Boga bogov; in srečo bo imel, dokler ne bode konec togoti; kajti kar je trdno določeno, se mora dovršiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 37, 'Tudi ne bo čislal boga očetov svojih, tudi se ne oziral po hrepenenju žen, ne po kateremsibodi bogu, temuč sam se bo poveličeval nad vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 38, 'Namesto tega bo častil boga trdnjav, boga, ki ga niso poznali očetje njegovi, bo častil z zlatom, srebrom, žlahtnim kamenjem in z dragotinami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 39, 'In ravnal bo z utrjenimi gradovi kakor s tujim bogom: kdorkoli ga pripozna, mu pomnoži čast in mu podeli gospostvo nad mnogimi in zemljo razdeli v plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 40, 'A ob času konca udari nanj kralj z juga; in severni kralj prihrumi nanj z vozmi in s konjiki in z mnogimi ladjami, in pridere v dežele in poplavi vse kakor povodenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 41, 'In pridere v deželo dike, in mnoge dežele bodo ugonobljene; ali ti bodo oteti iz roke njegove: Edom, Moab in prvaki sinov Amonovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 42, 'In iztegne roko po deželah, tudi dežela Egiptovska ne ubeži;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 43, 'in dobi v oblast svojo zaklade zlata in srebra in vse dragotine egiptovske; in Lubimi in Etiopci bodo v spremstvu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 44, 'Toda govorica z jutrovega in s severa ga preplaši, in pojde z velikim srdom, da jih veliko uniči in pomori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 11, 45, 'In postavi šatore svoje palače med morjem in goro svete dike. In dospe do svojega konca, in nihče mu ne pomore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 1, 'In tisti čas nastopi Mihael, veliki knez, ki se poteguje za sinove ljudstva tvojega; in bode čas stiske, kakršne ni bilo, odkar je narod, do tistega časa. A v tistem času bo oteto ljudstvo tvoje, vsak, kogar najdejo zapisanega v knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 2, 'In mnogi iz teh, ki spe v prahu zemlje, se bodo prebudili: ti za večno življenje, oni pa za sramoto, za večno gnusobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 3, 'In razumni se bodo svetili kakor svetlost nebesnega obloka in tisti, ki mnoge vodijo v pravičnost, kakor zvezde vselej in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 4, 'Ti pa, Daniel, hrani na skrivnem te besede in zapečati knjigo do časa konca. Mnogi bodo to preiskovali in spoznanje se pomnoži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 5, 'Tedaj pogledam jaz Daniel in glej: druga dva stojita tu, eden na tem bregu, drugi na onem bregu reke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 6, 'In eden reče možu, oblečenemu v platno, ki je bil nad vodo reke: Kdaj bo konec teh čudovitih reči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 7, 'In slišal sem moža, oblečenega v platno, ki je bil nad vodo reke, ko je povzdignil desnico in levico proti nebu in prisegel pri njem, ki živi vekomaj: Čas, dva časa in pol časa; in ko dokončajo drobljenje moči svetega ljudstva, se vse te reči dopolnijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 8, 'In jaz sem slišal, a nisem razumel; in rečem: Gospod moj, kaj bode posledek teh reči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 9, 'In veli: Pojdi, Daniel, kajti besede bodo na skrivnem hranjene in zapečatene do časa konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 10, 'Mnogi se bodo čistili in belili in precejali, a brezbožni bodo brezbožno delali; nobeden brezbožni pa ne bo umel, ali razumni bodo umeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 11, 'In od časa, ko bo odpravljena neprestana daritev in se postavi gnusoba, ki povzroča opustošenje, bode tisoč dvesto in devetdeset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 12, 'Blagor mu, kdor bo čakal in dosegel tisoč tristo petintrideset dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (27, 12, 13, 'Ti pa pojdi, dokler ne pride konec! Počival boš in vstaneš, da prejmeš delež svoj ob koncu dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 1, 'Beseda Gospodova, ki je prišla Ozeu, sinu Beerijevemu, v dneh Uzija, Jotama, Ahaza in Ezekija, kraljev Judovih, in v dneh Jeroboama, sina Joasa, kralja Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 2, 'Ko je Gospod vprvič govoril po Ozeu, mu je rekel: Pojdi, vzemi si ženo nečistnico in otroke, rojene iz nečistosti; kajti dežela nesramno nečistuje, ne hoteč hoditi za Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 3, 'Šel je torej in vzel Gomero, hči Diblaimovo; in spočela je in mu rodila sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 4, 'In Gospod mu veli: Daj mu ime Jezreel; zakaj še malo časa, in maščeval bom kri, prelito v Jezreelu, nad hišo Jehujevo in storim konec kraljestvu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 5, 'In zgodi se tisti dan, da starem lok Izraelov v dolini Jezreelski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 6, 'In zopet je spočela in rodila hčer. In Gospod mu reče: Daj ji ime Lo-ruhama; zakaj ne bom več pomilostil hiše Izraelove, da bi jim kakorkoli odpuščal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 7, 'Ali hiše Judove se usmilim in jim dam rešitev po Gospodu, njih Bogu, in jih ne rešim z lokom, ne z mečem, ne z vojsko, ne s konji in ne z jezdeci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 8, 'Ko pa je odstavila Lo-ruhamo, je spočela in rodila sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 9, 'In Gospod reče: Daj mu ime Lo-ami; zakaj vi niste ljudstvo moje in jaz nočem biti Bog vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 10, 'Vendar bode število sinov Izraelovih enako morskemu pesku, ki se ne more premeriti, ne prešteti; in zgodi se, da se jim na mestu, kjer se jim je reklo: „Niste ljudstvo moje“, poreče: Sinovi ste mogočnega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 1, 11, 'In zbero se enodušno sinovi Judovi in sinovi Izraelovi in si postavijo edino glavo in pojdejo gori iz dežele; kajti velik bode dan v Jezreelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 1, 'Recite bratom svojim: Ami, in sestram svojim: Ruhama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 2, 'Pravdajte se z materjo svojo, pravdajte! Kajti ona ni moja žena in jaz nisem njen mož; in naj odpravi nečistovanje svoje izpred svojega obličja in prešeštvovanje svoje izmed svojih prsi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 3, 'da je ne slečem do nagega in je ne postavim, kakor je bila v dan svojega rojstva, in je ne naredim kakor puščavo in kakor suho zemljo ter je ne dam v smrt od žeje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 4, 'In njenih otrok se ne usmilim, ker so otroci nečistosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 5, 'Kajti njih mati je nečistovala, sramotno se je vedla njih roditeljica; zakaj dejala je: Hodila bom za ljubovniki svojimi, ki mi dajo kruh moj in vodo mojo, volno mojo in predivo moje, olje moje in pijačo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 6, 'Zato, glej, zagradim pot tvojo s trnjem in postavim zid zoper njo, da ne najde svojih stezá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 7, 'In tekla bo za svojimi ljubovniki, a ne dohiti jih, ter jih bo iskala, pa jih ne najde; tedaj poreče: Pojdem in se povrnem k prvemu možu svojemu, ker se mi je bolje godilo takrat nego sedaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 8, 'A ona ni spoznala, da sem jaz ji dajal žito in vino in olje ter ji množil srebro in zlato, kar so vse trošili za Baala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 9, 'Zato vzamem nazaj žito svoje ob svojem času in vino svoje ob določenem času in ji iztrgam volno svojo in predivo svoje, ki naj bi bilo pokrilo njeno nagoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 10, 'In sedaj odkrijem njeno sramoto vpričo ljubovnikov njenih, in nihče je ne otme iz moje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 11, 'Storim tudi konec vsej njeni veselosti, njenim praznikom, njenim mlajem in sobotam in vsem prazničnim časom njenim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 12, 'In opustošim njene vinske trte in njeno smokovo drevje, o čemer je govorila: To je plačilo moje, ki so mi ga dajali ljubovniki moji. In naredim iz tega gozd, in poljske zveri bodo objedale vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 13, 'In kaznoval jo bom za dneve, posvečene Baalom, ob katerih jim je zažigala kadilo, ko se je lišpala s svojimi obročki in z drago ovratnino in hodila za svojimi ljubovniki, mene pa je pozabila, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 14, 'Zato, glej, jaz jo izvabim in popeljem v puščavo in govoril ji bom na srce;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 15, 'in dam ji odondod njene vinograde in dolino Ahor, da ji bode vrata upanja; in zapoje tam, kakor je pela v dneh mladosti svoje in kakor v dan, ko je šla gori iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 16, 'In zgodi se tisti dan, govori Gospod, da me boš imenovala: moj mož, in ne boš me več imenovala: moj Baal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 17, 'Kajti vzamem imena Baalov iz njenih ust, da se nikoli več ne omenijo njih imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 18, 'In tisti dan sklenem zanje zavezo z zvermi na polju in s pticami nebeškimi in z laznino po zemlji ter starem lok, meč in vojno orožje v deželi in storim, da bodo varno počivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 19, 'In zaročim se s teboj na vekomaj; in zaročim se s teboj v pravičnosti in v sodbi in v milosti in v usmiljenju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 20, 'zaročim se, pravim, s teboj v zvestobi, in spoznaš Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 21, 'In zgodi se tisti dan, da odgovorim, pravi Gospod: odgovorim nebu, in to odgovori zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 22, 'in zemlja odgovori žitu in vinu in olju, in ta odgovore Jezreelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 2, 23, 'In zasejem si jo po deželi, in usmilim se Lo-ruhame; in porečem njim, ki niso bili moje ljudstvo: Moje si ljudstvo, in ono poreče: Ti si Bog moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 1, 'In Gospod mi je rekel: Pojdi zopet, ljubi ženo, ki jo ljubi njen prijatelj, ona pa prešeštvuje: kakor ljubi Gospod sinove Izraelove, ki se pa obračajo do drugih bogov in ljubijo grozdne kolače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 2, 'In dobil sem si jo za petnajst srebrnikov in za homer in pol homerja ječmena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 3, 'In dejal sem ji: Veliko dni mi ostani samotna, ne nečistuj in se ne pečaj z nobenim možem; pa tudi jaz bodem enako do tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 4, 'Kajti veliko dni ostanejo sinovi Izraelovi brez kralja in brez kneza, brez klalne daritve in brez poslikanega stebra in brez naramnika in brez hišnih malikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 3, 5, 'Potem se izpreobrnejo sinovi Izraelovi in bodo iskali Gospoda, Boga svojega, in Davida, kralja svojega; in pritrepetajo h Gospodu in k dobroti njegovi v poslednjih dneh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 1, 'Čujte besedo Gospodovo, sinovi Izraelovi! Kajti Gospod ima pravdo s prebivalci dežele, ker ni resnice in ni usmiljenja in ni spoznanja Božjega v deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 2, 'Kletje je tu samo in laž in umor in tatvina in prešeštvovanje; nasilstvo počenjajo in kri za kri prelivajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 3, 'Zato žaluje dežela in medli vse, kar prebiva v njej, i zverine na polju i ptice pod nebom, in tudi ribe v morju ginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 4, 'Samo da jih nihče ne dolži in nihče ne kara! Kajti z ljudstvom tvojim je kakor ž njimi, ki se prepirajo z duhovnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 5, 'In padeš po dnevi in tudi prorok pade s teboj po noči; in uničim mater tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 6, 'Uničuje se ljudstvo moje, ker nima spoznanja; ker si ti zavrgel spoznanje, te tudi jaz zavržem, da mi ne bodeš duhovnik; ker si pozabil svojega Boga postavo, pozabim tudi jaz otroke tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 7, 'Kolikor bolj so se množili, tem bolj so grešili zoper mene: njih slavo izpremenim v sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 8, 'Ljudstva mojega daritve za greh uživajo in hlepé po njega krivici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 9, 'In bode kakor ljudstvo tako duhovnik; in kaznoval jih bom za njih poti in jim poplačam njih dejanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 10, 'In jedli bodo, pa se ne nasitijo, nečistovali bodo, pa se ne pomnože, ker so zapustili Gospoda, da ne bi ga imeli v čislih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 11, 'Nečistost in vino in mošt jemljejo pamet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 12, 'Ljudstvo moje vprašuje za svet svoj les, in palica njegova naj mu napoveduje; kajti duh nečistosti ga je zapeljal, in nečistujejo, ko so opustili Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 13, 'Po vrhovih gorá darujejo in po hribih žgo kadilo, pod hrastom in topolom in terebinto, ker je prijetna njih senca; zato nečistujejo hčere vaše in snahe vaše prešeštvujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 14, 'Ne morem kaznovati hčeri vaših, da nečistujejo, ne snah vaših, da prešeštvujejo, ker vi sami hodite v stran z nečistnicami in darujete skup z ljubodejkami; in ljudstvo, ki je brez razuma, se pogubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 15, 'Ako nečistuješ ti, Izrael, vsaj Juda naj ne greši! In ne hodite v Gilgal ter ne potujte gori v Betaven, tudi ne prisegajte: Res kakor Gospod živi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 16, 'Kajti Izrael se je upiral kakor neukročena junica; sedaj jih bo Gospod pasel kakor jagnje na široki planjavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 17, 'Efraim se je združil z maliki – pústi ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 18, 'Njih pijača se je izpridila; vedno in vedno nečistujejo; strastno ljubijo sramoto zaščitniki njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 4, 19, 'Zajel jih je veter s perutmi svojimi, in osramočeni bodo zavoljo daritev svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 1, 'Čujte to, o duhovniki, in poslušajte, hiša Izraelova, in nagnite ušesa, hiša kraljeva! Kajti vam velja sodba, ker ste bili zadrga v Micpi in mreža razpeta na Taboru;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 2, 'in odpadniki so globoko zabredli v popačenosti. Jaz pa jim bodem strahovalec v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 3, 'Jaz poznam Efraima in Izrael mi ni skrit; kajti sedaj si nečistoval, o Efraim, Izrael se je onečistil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 4, 'Njih dejanja jim ne dopuščajo, da se vrnejo k svojemu Bogu; kajti duh nečistosti je v njih srcu in ne spoznavajo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 5, 'In ošabnost Izraelova pričuje njemu v oči; zato padeta Izrael in Efraim po krivici svoji, tudi Juda pade ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 6, 'S svojo drobnico in s svojimi govedi pojdejo iskat Gospoda, a ga ne najdejo: umaknil se jim je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 7, 'Nezvesto so ravnali zoper Gospoda, kajti rodili so tuje otroke; sedaj jih požre mesec ž njih deleži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 8, 'Zatrobite na rog v Gibei in na trobento v Rami, močno vpijte v Betavenu: Sovražnik ti je za hrbtom, o Benjamin!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 9, 'Efraim postane pustota v dan svojega pokorjenja; o rodovih Izraelovih sem oznanil, kar se res zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 10, 'Knezi Judovi so kakor tisti, ki prestavljajo mejnike; nadnje izlijem srd svoj kakor vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 11, 'Efraim je potlačen, potrt vsled sodbe, ker se mu je ljubilo hoditi po postavi človeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 12, 'In jaz sem Efraimu kakor molj in kakor črvivost hiši Judovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 13, 'Ko je Efraim videl bolezen svojo in Juda rano svojo, je šel Efraim v Asirijo in poslal h kralju Jarebu; ali on vas ne more ozdraviti, tudi ne zaceli rane vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 14, 'Kajti jaz bodem Efraimu kakor lev in hiši Judovi kakor levič: jaz, jaz raztrgam, in odidem; odnesem, in ne bo ga, ki bi otel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 5, 15, 'Odidem in se povrnem na mesto svoje, dokler ne priznajo krivde svoje in ne bodo iskali obličja mojega. V stiski svoji me bodo marljivo iskali in rekli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 1, 'Pridite in povrnimo se h Gospodu! Kajti on nas je raztrgal in nas tudi ozdravi, on nas je udaril in nas tudi obveže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 2, 'Oživi nas po dveh dneh, tretji dan nas vzdigne, da bomo živeli pred njegovim obličjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 3, 'In spoznavajmo Gospoda, prizadevajmo si ga spoznati! Njegov izhod je gotov kakor jutranji svit, in pride nam kakor deževje, kakor pozni dež, ki vlaži zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 4, 'Kaj naj ti storim, o Efraim? kaj naj ti storim, o Juda? kajti vaše bogoljubje je kakor jutranji oblak in kakor rosa, ki hitro izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 5, 'Zato sem jih obtesaval po prorokih, ubijal sem jih z ust svojih besedami; in sodba moja vzhaja kakor luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 6, 'Kajti usmiljenja želim in ne daritve in spoznanja Božjega več nego žgalnih žrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 7, 'Oni pa so kakor Adam prestopili zavezo, ondi so se mi izneverili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 8, 'Gilead je mesto hudodelnikov, polno krvavih sledov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 9, 'In kakor razbojnik preži ob cesti, tako družba duhovnikov: moré na potu v Sihem, da nesramnosti počenjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 10, 'V hiši Izraelovi sem videl strahovito reč: tam je nečistovanje Efraimovo, Izrael oskrunjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 6, 11, 'Tudi tebi, o Juda, je pripravljena žetev, ko nazaj popeljem ujetništvo ljudstva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 1, 'Kadar hočem zdraviti Izraela, se pokaže krivičnost Efraimova in zlobnost Samarije; kajti le laž uganjajo in tat prodira v hišo, zunaj ropa truma razbojnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 2, 'In ne reko si v srcu, da se spominjam vse njih zlobnosti; sedaj so jih že obdala njih dejanja, pred mojim so obličjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 3, 'S hudobo svojo razveseljujejo kralja in kneze z lažmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 4, 'Vsi so prešeštniki, podobni peči, ki jo je pek razbelil: on neha kuriti, ko je umesil testo, dokler se ne prekvasi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 5, 'V dan našega kralja so oboleli poglavarji od vinske vročine; on je podal svojo roko zasmehovalcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 6, 'Kajti pripravili so srce svoje kakor peč, ko kujejo zvijačo; njih pek spi vso noč, zjutraj gori peč kakor plameneč ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 7, 'Vsi so razbeljeni kakor peč in požirajo sodnike svoje. Vsi njih kralji so padli; nihče izmed njih me ne kliče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 8, 'Efraim se meša z ljudstvi; Efraim je kakor podpepelni kolač, ki ni bil obrnjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 9, 'Tujci so použili moč njegovo, on pa tega ne ve; tudi se mu je sivina po glavi razlezla, pa tega ne ve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 10, 'In ošabnost Izraela mu priča v oči; a nočejo se vrniti h Gospodu, svojemu Bogu, ne ga iskati kljub vsemu temu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 11, 'In Efraim je kakor preprost golob, brez razuma: kličejo na pomoč Egipt, gredo v Asirijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 12, 'Kadar pojdejo, razgrnem čeznje mrežo svojo, kakor ptice nebeške jih potegnem doli; kaznoval jih bom tako, kakor se je oznanjalo njih občini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 13, 'Gorje jim! ker so zašli od mene; poguba nadnje! ker so se pregrešili zoper mene. Jaz bi jih rad odkupil, pa oni govore laži zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 14, 'In ne kličejo k meni v svojem srcu, temuč tulijo na ležiščih svojih; zbirajo se zavoljo žita in vina, uporno se stavijo zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 15, 'In jaz sem vadil njih roke in krepčal, a oni izmišljajo hudo zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 7, 16, 'Obračajo se, pa ne gori: so kakor lok, ki strelja napačno. Njih poglavarji padejo zavoljo srditosti svojega jezika: to jim bode v zasmehovanje v deželi Egiptovski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 1, 'Trobento deni na usta! Kakor orel prileti sovražnik na dom Gospodov, ker so prestopili zavezo mojo in se pregrešili zoper postavo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 2, 'Vpili bodo k meni: Bog moj, mi, ki smo Izrael, te poznamo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 3, 'Izrael je zavrgel, kar je dobro: naj ga sovražnik preganja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 4, 'Kralje so postavljali, ali brez mene, nameščali poglavarje, in jaz nisem vedel. Iz srebra in zlata svojega so si delali malike, da bi bili iztrebljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 5, 'Bog je zavrgel tele tvoje, o Samarija! Srd moj je razvnet zoper nje: doklej se še ne bodo mogli očistiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 6, 'Kajti iz Izraela je tudi to tele: umetnik ga je naredil, in ni Bog; res v kosce razpade tele samarijsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 7, 'Kajti veter sejejo in želi bodo vihar; stebla nima njih setev; kar je zraslo, ne da moke; ako bi jo tudi dalo, bi jo tujci požrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 8, 'Požrt je Izrael; sedaj so med poganskimi narodi kakor posoda, ki se je nihče ne veseli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 9, 'Kajti šli so v Asirijo. Divji osel biva sam posebe, Efraim pa si je najel ljubovnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 10, 'Če si jih tudi najemajo med pogani, jih sedaj zberem; in začno se manjšati pod bremenom kralja knezov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 11, 'Ker je Efraim namnožil oltarje za grešenje, so mu bili oltarji v pregreho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 12, 'Naj mu napišem postavo svojo desettisočkrat, vendar jo štejejo za tujo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 13, 'Kot klalščine mojih daril darujejo meso in ga jedo; Gospod se jih ne veseli. Sedaj se spomni njih krivic in bo kaznoval njih grehe: na Egiptovsko se povrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 8, 14, 'Zakaj Izrael je pozabil Stvarnika svojega in si zgradil palače, in Juda je pomnožil utrjena mesta; ali pošljem ogenj v mesta njegova, ki požre gradove njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 1, 'Ne raduj se, o Izrael, da bi poskakoval kakor ljudstva; kajti nečistoval si, ko si se izneveril Bogu svojemu, ljubil si ljubovniško plačilo na vseh gumnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 2, 'Gumno in tlačilnica jim ne dasta živeža in mošta jim bo zmanjkalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 3, 'Ne bodo prebivali v deželi Gospodovi, temuč Efraim se povrne v Egipt, in nečiste jedi bodo jedli v Asiriji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 4, 'Ne bodo Gospodu darovali vina in njih klalne daritve mu ne bodo prijetne, bodo jim kakor kruh žalujočih; vsi, ki bodo od njih jedli, se onečistijo, kajti njih jed je zanje same, ne pride v hišo Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 5, 'Kaj boste počeli v dan prazničnega zbora in v dan praznika Gospodovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 6, 'Kajti glej, ko se preselijo zaradi razdejanja, jih zbere Egipt, Memf jih pokoplje; njih srebrne dragotine si prilasti kopriva, trnje bode v njih šatorih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 7, 'Prišli so dnevi obiskovanja, prišli so dnevi povračila; Izrael bo zvedel. Prorok je blazen, človek, ki ima duha, je zmešane pameti, zato ker je obila krivica tvoja in sovražnost tvoja velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 8, 'Efraim gleda po razodetju zraven mojega Boga; na vseh prorokovih potih je ptičarjeva zanka, sovraštvo v hiši Boga njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 9, 'Globoko so se popačili kakor v času Gibee. Bog se spomni njih krivice, kaznoval bo njih grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 10, 'Našel sem Izraela kakor grozdje v puščavi; videl sem očete vaše kakor prvino smokovega drevesa v zgodnji dobi njegovi. Oni pa so šli v Baal-peor in se posvetili sramoti in so postali gnusobni kakor tisti, katerega so ljubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 11, 'Efraimova slava odleti kakor ptica. Ne bo poroda, ne noseče, ne spočetja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 12, 'in ko bi tudi zredili sinove svoje, storim vendar, da bodo brez otrok, da ne ostane moža; kajti gorje jim, kadar odstopim od njih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 13, 'Efraim je, kakor vidim, zasajen kakor Tir na lepem kraju; toda Efraim mora peljati otroke svoje ven k ubijalcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 14, 'Daj jim, o Gospod – kaj jim hočeš dati? – daj jim nerodovitna telesa in suhe prsi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 15, 'Vsa njih hudobnost izvira v Gilgalu, tako da sem jih tam zasovražil. Zavoljo hudobnosti njih dejanj jih preženem iz hiše svoje; ne bom jih več ljubil; vsi njih poglavarji so odpadniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 16, 'Efraim je udarjen: njih korenina se je posušila, sadu ne obrodé več; celo ko bi rodili, usmrtim ljubčke njih telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 9, 17, 'Bog moj jih zavrže, ker ga niso poslušali; in klatili se bodo med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 1, 'Izrael je košata trta, ki je poganjala sadove svoje. Čim obilneje jim je bilo sadu, tem bolj so množili oltarje; čim boljša njih dežela, tem lepše so delali poslikane stebre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 2, 'Razdeljeno je njih srce, sedaj se bodo pokorili: on razdene njih oltarje, podere njih podobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 3, 'Res, sedaj poreko: Nimamo kralja; kajti Gospoda se nismo bali, in kralj – kaj bo ta nam pomagal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 4, 'Govore prazne besede, prisegajo lažnivo, sklepajo zaveze: zato bo sodba poganjala kakor strupeno zelišče po brazdah na njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 5, 'Prebivalci v Samariji bodo trepetali zavoljo teleta v Betavenu; da, ljudstvo njegovo bo nad njim žalovalo in njegovi mališki duhovniki se bodo zanje tresli, zavoljo slave njegove, ker je šla od njega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 6, 'tudi ono samo prineso v Asirijo v darilo kralju Jarebu. Sram prevzame Efraima in Izrael bo osramočen zavoljo sklepa svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 7, 'Samarija izgine in njen kralj kakor trska na površju vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 8, 'In pokončane bodo višave v Avenu, greh Izraelov; trnje in osat bosta zrasla na njih oltarjih. In poreko goram: Pokrijte nas! in hribom: Padite na nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 9, 'Od tistih dni v Gibei si grešil, o Izrael: tam so obstali. Ne zadene li jih v Gibei boj zoper sinove hudobnosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 10, 'Kakor me bode volja, jih bom strahoval; in ljudstva se zbero zoper nje, kadar jih privežem k njih dvojni pregrehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 11, 'In Efraim je izučena junica, ki rada vrši žito; jaz ji pa stopim na lepi vrat: Efraimu dam jezdeca, Juda bo oral, Jakob vlačil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 12, 'Sejte si za pravičnost, ženjite po usmiljenju, preoravajte si novino: kajti čas je, da iščete Gospoda, dokler ne pride in vam bo dežil pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 13, 'Orali ste krivičnost, pregreho ste želi, sad laži ste jedli; kajti zanašal si se na pota svoja, na množico junakov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 14, 'Zato nastane bojni hrup med ljudstvi tvojimi, in vse trdnjave tvoje bodo razvaljene, kakor je Salman razdejal Betarbelo v dan boja; mati z otroki vred je bila raztrupana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 10, 15, 'To vam napravi Betel zavoljo prevelike hudobnosti vaše; ob jutranjem svitu bo docela pokončan kralj Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 1, 'Ko je bil Izrael mlad, sem ga ljubil, in iz Egipta sem poklical sina svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 2, 'Kadar so jih klicali proroki, so bežali izpred njih: darovali so Baalom in kadilo žgali rezanim podobam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 3, 'Jaz pa sem učil Efraima hoditi; vzel sem si jih na rame, a niso spoznali, da sem jih hotel zdraviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 4, 'S človeškimi vrvicami sem jih vlekel, z vezmi ljubezni; in bil sem jim, kakor kdor jarem od čeljusti privzdiguje, in nežno sem jim podajal jedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 5, 'Ne vrne se v deželo Egiptovsko, ali Asirec mu bode kralj, ker se niso hoteli izpreobrniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 6, 'In meč napade mesta njegova in pokonča zapahe njegove in jih bo požiral zaradi njih sklepov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 7, 'kajti ljudstvo moje se silno drži odpada od mene; in če ga kličejo k Njemu, ki je gori, nihče se ne povzdigne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 8, 'Kako naj bi te opustil, Efraim, tebe li naj izdam, Izrael? kako naj bi te storil kakor Adamo, te naredil enakega Zeboimu? Srce moje se je preobrnilo v meni, razvnelo se mi je vse usmiljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 9, 'Nočem storiti po togoti jeze svoje, nočem zopet pogubiti Efraima; kajti Bog mogočni sem jaz in ne človek, Svetnik sredi tebe. Ne pridem v srdu. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 10, 'Pojdejo za Gospodom, kadar bo rjul kakor lev; kajti on bo rjul, in sinovi bodo pritrepetali od zahoda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 11, 'kakor ptice prilete trepetaje iz Egipta in kakor golobje iz dežele Asirske; in storim, da bodo prebivali v hišah svojih, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 11, 12, 'Efraim me je obdajal z lažjo in hiša Izraelova s prevaro; in Juda še vedno teka semtertja mimo Boga mogočnega in mimo Najsvetejšega, ki je zvest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 1, 'Efraim se žene za vetrom in lovi vzhodni veter; ves dan množi laž in silovitost; zavezo sklepajo z Asirijo in olje nosijo v Egipt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 2, 'Tudi z Judo ima Gospod pravdo, in bo kaznoval Jakoba po potih njegovih, povrne mu po dejanjih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 3, 'V materinem telesu je zgrabil svojega brata peto in v moški moči svoji se je boril z Bogom mogočnim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 4, 'boril se je z angelom in premagal, jokal je in ga milo prosil. V Betelu ga je našel in ondi je govoril z nami –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 5, 'namreč Jehova, Bog nad vojskami; Jehova mu je spominsko ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 6, 'Ti torej se izpreobrni k Bogu svojemu; usmiljenje in pravico ohrani in upaj stanovitno v svojega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 7, 'Efraim je tržec, v roki njegovi je lažniva tehtnica, rad opehari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 8, 'In Efraim govori: Vendar sem obogatel, pridobil sem si imetja. V vsem mojem prislužku se ne najde nič krivičnega, kar bi bilo greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 9, 'Jaz pa sem Gospod, Bog tvoj, od dežele Egiptovske doslej; dam ti zopet stanovati v šatorih kakor ob dneh praznične slovesnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 10, 'In govoril sem prorokom in sem pomnožil prikazni ter po službi prorokov sem govoril v prilikah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 11, 'Ako je Gilead hudobnost, vsi skupaj pridejo v nič. V Gilgalu darujejo junce, zato bodo tudi njih oltarji kakor groblje po brazdah na njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 12, 'In Jakob je zbežal na poljano Aramsko in Izrael je služil za ženo in za ženo je pasel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 13, 'In po proroku je Gospod peljal Izraela gori iz Egipta in po proroku je bil ohranjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 12, 14, 'Efraim ga je bridko dražil v jezo, zato ostane krvava krivda na njem, in zasramovanje njegovo mu povrne njegov Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 1, 'Ko je Efraim govoril, je napravljal strah; povzdignil se je v Izraelu. Ali ko se je pregrešil z Baalom, je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 2, 'Še vedno nakladajo greh na greh in si delajo ulite podobe iz srebra, malike po svojem razumu. Delo umetnikov je vse to; prav o teh pravijo: Ljudje, ki darujejo, poljubljajo teleta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 3, 'Zatorej bodo kakor jutranji oblak in kakor rosa, ki hitro izgine, kakor pleve, ki jih vihar pobere z gumna, in kakor dim iz dimnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 4, 'Jaz pa sem Gospod, Bog tvoj, od dežele Egiptovske doslej; in ne poznaš nobenega boga razen mene in ni ga razen mene rešitelja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 5, 'Poznal sem te v puščavi, v deželi velike suhote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 6, 'Ko so se pasli, so se nasitili, nasitili so se in njih srce se je povzdignilo; zato so me pozabili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 7, 'Tako sem jim postal enak levu; kakor pard prežim ob potu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 8, 'planem nadnje kakor medvedka, ki so ji vzeli mladiče, in raztrgam zaklep njih srca, in tedaj jih požrem kakor lev; poljske zveri jih raztrgajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 9, 'Tvoja poguba je, o Izrael, da si zoper mene, zoper pomoč svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 10, 'Kje je sedaj kralj tvoj, da te reši po vseh mestih tvojih, in kje so sodniki tvoji, ki si rekel o njih: Daj mi kralja in kneze!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 11, 'Dal sem ti kralja v jezi svoji in sem ga vzel v srdu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 12, 'Zvezana je krivica Efraimova, shranjen njegov greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 13, 'Bolečina kakor porodnice pridejo nanj; on je nespameten sin; kajti kadar je čas, ne pride v porod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 14, 'Iz oblasti pekla jih rešim, iz smrti jih odkupim. Kje je tvoj pomor, o smrt? kje je, pekel, tvoja poguba? Kesanje je skrito mojim očem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 15, 'Čeprav je Efraim sadovit med brati svojimi, vendar pride vzhodni veter, veter Gospodov se vzdigne od puščave, in vir njegov usahne in njegov studenec se posuši. On opleni zakladnico vseh dragotin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 13, 16, 'Samarija se bo pokorila za krivdo svojo, ker se je uprla zoper svojega Boga; popadajo pod mečem, njih otroke raztrupajo in njih noseče razparajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 1, 'Povrni se, o Izrael, prav h Gospodu, svojemu Bogu, kajti padel si po pregrehi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 2, 'Vzemite s seboj besede in vrnite se h Gospodu; recite mu: Odpusti vso pregreho in sprejmi nas milostljivo, in bomo prinašali sad ustnic kot daritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 3, 'Asirija nas ne bo rešila; na konjih nočemo jezditi in nikdar več ne porečemo rok svojih izdelku: naš bog si! Kajti pri tebi najde sirota usmiljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 4, 'Ozdravim njih odpad, rad jih hočem ljubiti; kajti jeza moja se je odvrnila od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 5, 'Bodem kakor rosa Izraelu, cvetel bo kakor lilija in poganjal korenine kakor Libanon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 6, 'Razprostro se njegove veje, in lepota njegova bode kakor oljka in duh njegov kakor Libanon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 7, 'Kateri bodo prebivali v senci njegovi, bodo zopet pridelovali žito in zeleneli kakor vinska trta, katere sloves bo kakor vina libanonskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 8, 'Efraim poreče: Kaj hočem še z maliki? – Jaz sem ga uslišal in se nanj oziram. Jaz sem kakor zeleneča cipresa. Iz mene se najde sad na tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (28, 14, 9, 'Kdor je moder, bo razumel to; kdor je razumen, bo to spoznal. Kajti ravna so pota Gospodova in pravični bodo hodili po njih, ali prestopniki padejo na njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 1, 'Beseda Gospodova, ki je prišla Joelu, sinu Petuelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 2, 'Čujte to, starci, in nagnite ušesa, vsi prebivalci dežele! Se li je zgodilo kaj takega v dneh vaših ali v očetov vaših dnevih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 3, 'Pripovedujte o tem otrokom svojim in vaši otroci svojim otrokom in njih otroci prihodnjemu rodu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 4, 'Kar je pustil žerec, je snedla kobilica; in kar je ostalo po kobilici, je snedel glodalec; kar pa je ostalo po glodalcu, je snedel pokončevalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 5, 'Zdramite se, ki ste pijani, in jokajte! in tulite vsi, ki pijete vino, zavoljo novega vina, da je vzeto od vaših ust!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 6, 'Kajti narod je prišel gori v deželo mojo, mogočen in brezštevilen; njegovi zobje so levovi zobje in grizalo ima kakor levinja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 7, 'V pustoto je naredil vinsko trto mojo in polomil smokev mojo; dočista jo je ogolil in na tla pometal; obeljene so veje njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 8, 'Plakaj, dežela, kakor devica, ki je oblečena v raševnik zavoljo zaročenca mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 9, 'Jedilna in pitna daritev je odpravljena iz hiše Gospodove; duhovniki, služabniki Gospodovi, žalujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 10, 'Opustošeno je polje, zemlja žaluje; ker žito je pošlo, novo vino se je posušilo, olje izginilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 11, 'Sram vas bodi, kmetovalci, tulite, o vinogradniki, zaradi pšenice in zaradi ječmena; kajti pokončana je poljska žetev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 12, 'Usahnila je vinska trta, opešala smokev; margarana, tudi palma in jablan in vse drevje na polju je suho, in minilo je veselje otroke človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 13, 'Prepašite se z raševnikom in žalujte, duhovniki; tulíte, strežniki oltarja; pridite, prenočite v raševniku, služabniki mojega Boga! ker je hiši Boga vašega zadržana jedilna in pitna daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 14, 'Posvetite post, razglasite praznično zborovanje, zberite starejšine, vse prebivalce dežele v hišo Gospoda, Boga svojega, in vpijte h Gospodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 15, 'Gorje tega dneva! zakaj dan Gospodov je blizu in pride kakor razdejanje od Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 16, 'Ni li nam pred očmi odvzet živež, veselje in radovanje iz hiše našega Boga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 17, 'Zrnje je zgnilo pod svojimi grudami; založnice so opustošene, skednji razdrti, kajti žito se je posušilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 18, 'Kako ječi živina! goveje črede tavajo klavrno, ker nimajo paše; tudi črede drobnice trpe pokoro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 19, 'O Gospod, k tebi kličem; ker ogenj je požrl pašnike v puščavi in plamen je požgal vse drevje na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 1, 20, 'Pa tudi zveri na polju žejne vpijejo k tebi, ker so posehnili potoki in je ogenj požrl pašnike v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 1, 'Zatrobite na trobento na Sionu in zaženite hrup na gori svetosti moje! Naj trepečejo vsi prebivalci dežele! ker prihaja dan Gospodov, ker se bliža:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 2, 'dan temote in mraka, dan oblakov in noči oblačne. Kakor se zarja razliva po gorah, tako pride ljudstvo mnogoštevilno in mogočno, kakršnega nikdar ni bilo in nikdar več ne bode do let mnogih rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 3, 'Pred njim požira ogenj, za njim pa šviga plamen; kakor vrt edenski je dežela pred njim, za njim pa prazna puščava, in nikomur ni mogoče ubežati pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 4, 'Njih podoba je kakor podoba konj, in kakor konjiki, tako dirjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 5, 'Kakor ropotajoči vozovi skačejo po vrhovih gorá, kakor prasketajoč goreč plamen, ki požira strnišče, kakor mogočno ljudstvo, pripravljeno za boj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 6, 'Spričo njih trepečejo ljudstva, vsi obrazi so bledi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 7, 'Tekajo kakor junaki, kakor vojščaki plezajo na zid; in gredo vsak po svoji poti in ne menjavajo svojih stezá;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 8, 'drug ne tišči drugega, vsak poedinec gre po svojem tiru, in drevé čez orožje in ne pretrgajo svojega vlaka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 9, 'Po mestu tekajo semintja; priplezajo na zid, stopajo v hiše, skozi okna lezejo kakor tat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 10, 'Pred njimi se trese zemlja, nebo se giblje; solnce in mesec otemnevata in zvezde bledé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 11, 'In Gospod grmi z glasom svojim pred vojsko svojo, ker jako veliko je njegovo šatorišče, ker močan je tisti, ki izvršuje besedo njegovo; kajti dan Gospodov je velik in silno strašen: kdo ga more pretrpeti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 12, 'Ali tudi še sedaj, govori Gospod, se izpreobrnite k meni z vsem srcem svojim, s postom in z jokom in žalovanjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 13, 'Raztrgajte si srca, ne pa oblačil, in izpreobrnite se h Gospodu, svojemu Bogu; kajti on je milostiv in poln usmiljenja, počasen za jezo in bogat v milosti in žal mu je hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 14, 'Kdo ve, če se ne obrne in mu bode žal in pusti za seboj blagoslov: jedilno in pitno daritev Gospodu, vašemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 15, 'Zatrobite v trobento na Sionu, posvetite post, razglasite praznično zborovanje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 16, 'Zberite ljudstvo, posvetite zbor, skličite starejšine, zberite otroke in dojenčke pri prsih; ženin naj pride iz svojega hrama in nevesta iz svoje spalnice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 17, 'Duhovniki, služabniki Gospodovi, naj plakajo med vežo in oltarjem in govore: Zanesi, Gospod, svojemu ljudstvu in ne dajaj svoje dediščine v zasramovanje, da bo v zabavljico poganskim narodom! Zakaj bi naj rekali med ljudstvi: Kje je njih Bog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 18, 'Tedaj se je vnel Gospod za deželo svojo in se je usmilil svojega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 19, 'In Gospod je odgovoril in rekel ljudstvu svojemu: Glej, pošljem vam žita in vina in olja, da se nasitite, in ne dam vas več v zasmeh med narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 20, 'In njega, ki pride od severa, odvrnem od vas ter ga zapodim v suho in pusto deželo, njegov prvi voj v vzhodno morje in njegov zadnji voj v zahodno morje, in smrad njegov bo puhtel in duh gnilobe njegove se bo vzdigal, ker je toliko prevzetoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 21, 'Ne boj se, zemlja, raduj in veséli se! kajti Gospod dela velike reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 22, 'Ne bojte se, živali na polju! kajti zelené pašniki v puščavi, kajti drevje rodi svoj sad, smokev in trta kažeta svojo moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 23, 'In vi, sinovi sionski, radujte in veselite se v Gospodu, svojem Bogu! kajti daje vam zgodnjega dežja pravo mero in pošilja vam naliv zgodnjega in poznega dežja kakor poprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 24, 'In gumna bodo polna žita in v kadeh bo preobilo vina in olja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 25, 'In povrnem vam leta, ki so vam v njih vse požrle kobilice, glodalec, pokončevalec in žerec, vojska moja velika, ki sem jo poslal nad vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 26, 'In imeli boste obilo jedi in se boste nasitili ter hvalili ime Gospoda, Boga svojega, ki je čudovito ravnal z vami. In ne bo osramočeno ljudstvo moje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 27, 'In spoznate, da sem jaz sredi Izraela ter da sem jaz, Jehova, Bog vaš in nihče drugi. In ne bo osramočeno ljudstvo moje vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 28, 'In zgodi se potem, da izlijem Duha svojega na vse meso; in sinovi vaši in hčere vaše bodo prorokovali, starci vaši bodo imeli sanje, mladeniči vaši bodo videli prikazni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 29, 'In celo na hlapce in na dekle izlijem Duha svojega v tistih dneh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 30, 'In pokažem čudeže na nebu in na zemlji: kri in ogenj in dimaste stebre;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 31, 'solnce se izpremeni v temo in mesec v kri, preden pride dan Gospodov, veliki in prestrašni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 2, 32, 'Zgodi se pa, da vsak, kdor bo klical ime Gospodovo, bo rešen; kajti na gori Sionu in v Jeruzalemu bode rešitev, kakor je govoril Gospod, in med preostalimi, ki jih pokliče Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 1, 'Kajti glej, v tistih dneh in tisti čas, kadar nazaj pripeljem ujetništvo Judovo in jeruzalemsko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 2, 'tedaj zberem vse poganske narode in jih popeljem v dolino Josafat, in tam se bom ž njimi pravdal za ljudstvo svoje in za dediščino svojo, Izraela, ki so ga razkropili med narode; in deželo mojo so razdelili');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 3, 'in za ljudstvo moje so metali kocko; in dečka so dali za nečistnico in deklico so prodali za vino, da so ga pili. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 4, 'Pa tudi vi, kaj mi hočete, Tir in Sidon in vsi kraji Filisteje? Mi li hočete povrniti, kar sem storil? ali mi hočete nagoditi kaj? Hitro, brž povrnem delo vaše vam na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 5, 'Zato ker ste vzeli srebro in zlato moje in najboljše dragotine moje znesli v svoje malikovalnice');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 6, 'in otroke Judove in otroke jeruzalemske prodajali sinovom Grčije, da jih spravite daleč od njih pokrajine:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 7, 'glejte, jaz jih obudim iz kraja, kamor ste jih prodali, in povrnem delo vaše vam na glavo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 8, 'In prodam vaše sinove in hčere vaše sinovom Judovim v roko, in ti jih prodado možem iz Sabe, ljudstvu daljnemu; kajti Gospod je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 9, 'Razglasite to med narodi, posvetite vojsko, zdramite junake, vsi vojščaki naj pridejo in stopijo sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 10, 'Prekujte svoja orala v meče in kosirje v sulice! Slabič naj reče: Junak sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 11, 'Hitite in pridite, vsi narodi vseokoli, in zberite se! Tja doli pošlji junake svoje, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 12, 'Naj se vzdignejo narodi in pridejo v dolino Josafat, kajti tam bom sedel in sodil vse narode okoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 13, 'Nastavite srpe, ker žetev je dozorela; pridite, stopite, zakaj tlačilnica je polna, kadi so prenapolnjene! Kajti njih hudobnost je velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 14, 'Množice, množice v dolini razsodbe! kajti blizu je dan Gospodov v dolini razsodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 15, 'Solnce in mesec otemnevata in zvezde bledé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 16, 'In Gospod rjove s Siona in grmi z glasom svojim iz Jeruzalema, in gibljeta se nebo in zemlja. A Gospod je pribežališče ljudstvu svojemu in trdnjava sinom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 17, 'In spoznate, da sem jaz, Gospod, Bog vaš, ki prebivam na Sionu, na gori svetosti svoje. In Jeruzalem bode svet, in tujci ne bodo več hodili skozi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 18, 'In zgodi se tisti dan, da bo kapljal mošt z gorá in teklo mleko s hribov, in po vseh strugah Judovih bodo tekle vode; in studenec bo vrel iz hiše Gospodove in namakal dolino Sitimsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 19, 'Egipt bode v pustoto in Edom v prazno puščavo zavoljo silovitosti proti sinovom Judovim, ker so nedolžno kri prelivali v njih deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 20, 'Ali na Judovem bodo prebivalci vekomaj in v Jeruzalemu od roda do roda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (29, 3, 21, 'In očistim njih kri, ki je nisem bil očistil. In Gospod bo prebival na Sionu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 1, 'Besede Amosa, bivšega ovčarja v Tekoi, ki jih je v prikazni slišal za Izraela v dneh Uzija, kralja Judovega, in v dneh Jeroboama, sina Joasa, kralja Izraelovega, dve leti pred potresom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 2, 'In je rekel: Gospod bo rjovel s Siona in grmel z glasom svojim iz Jeruzalema, in žalovali bodo pašniki pastirjev in vrh Karmela se bo posušil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 3, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Damask, ne odvrnem šibe njegove: ker so mlatili Gileada z železnimi mlatilnicami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 4, 'zato pošljem ogenj v hišo Hazaelovo, in požre gradove Ben-hadadove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 5, 'In potarem zapahe v Damasku in iztrebim prebivalce iz doline Avenske in njega, ki drži žezlo, iz hiše edenske; in ljudstvo iz Sirije pojde v sužnost v Kir, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 6, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriva Gaza, ne odvrnem šibe njene: ker so peljali ljudstvo prav vse v ujetništvo, da jih izroče Edomu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 7, 'zato pošljem ogenj v obzidje Gaze, in požre palače njene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 8, 'in iztrebim prebivalca iz Asdoda in njega, ki drži žezlo, iz Askelona; in obrnem roko svojo zoper Ekron, in pogine ostanek Filistejcev, pravi Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 9, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Tir, ne odvrnem šibe njegove: ker so izročili ujetnike Edomu in se niso spomnili bratovske zaveze,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 10, 'zato pošljem Tiru ogenj v obzidje, in požre palače njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 11, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Edom, ne odvrnem šibe njegove: ker je preganjal z mečem brata svojega in zadušil usmiljenje v sebi, in ker je v jezi svoji neprenehoma pobijal in srd svoj vedno razvnemal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 12, 'zato pošljem ogenj v Teman, in požre palače v Bozri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 13, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih so krivi sinovi Amonovi, ne odvrnem šibe od njih: ker so razparali noseče v Gileadu, da razširijo meje svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 14, 'zato zažgem ogenj v zidovju Rabe, in požre palače njene med bojnim vpitjem v dan bitke, v viharju ob dnevi nevihte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 1, 15, 'in njih kralj pojde v ujetništvo, on in knezi njegovi skupaj, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 1, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Moab, ne odvrnem šibe njegove: ker je sežgal kosti kralja edomskega do apna,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 2, 'zato pošljem ogenj nad Moaba, in požre palače v Kerjotu; in Moab umrje v hrupu, med bojnim krikom, med bučanjem trobente;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 3, 'in iztrebim sodnika izmed njega in vse poglavarje njegove umorim ž njim vred, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 4, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Juda, ne odvrnem šibe njegove: ker so zavrgli zakon Gospodov in niso ohranili postav njegovih, njih laži pa, po katerih so živeli njih očetje, so jih zapeljale,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 5, 'zato pošljem ogenj nad Judo, in požre palače jeruzalemske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 6, 'Tako pravi Gospod: Zavoljo treh in zavoljo štirih pregreh, ki jih je kriv Izrael, ne odvrnem šibe njegove: ker so prodali pravičnika za denar in potrebnega za par čevljev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 7, 'oni hrepene po tem, da vidijo prah zemlje na glavi ubožca in krivijo pot krotkim, in sin in oče hodita k enemu dekletu, da bi oskrunila ime svetosti moje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 8, 'in na zastavljenih oblačilih leže pri slehernem oltarju in v hiši Boga svojega pijo vino tistih, ki jim je bila prisojena globa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 9, 'In vendar sem pogubil Amorejca izpred njih, ki je bil visok kakor cedra in močan kakor hrast, vendar sem pogubil njegov sad zgoraj in korenine njegove spodaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 10, 'In jaz sem vas odpeljal iz dežele egiptovske in vas vodil štirideset let v puščavi, da bi posedli deželo Amorejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 11, 'In obudil sem proroke izmed vaših sinov in nazirce iz vaših mladeničev. Ni li prav tako, o sinovi Izraelovi? govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 12, 'Vi pa ste dajali vina piti nazircem in prorokom ste ukazovali: Ne prorokujte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 13, 'Glejte, jaz vas bom tlačil do tal kakor tlači voz, ki je poln snopja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 14, 'In izgine beg hitremu in močnega opusti moč njegova, in junak ne otme življenja svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 15, 'in lokostrelec ne bo mogel stati, in kdor je brzih nog, ne ubeži, in kdor jezdi konja, ne otme življenja svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 2, 16, 'in najpogumnejši med junaki bo nag bežal tisti dan, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 1, 'Čujte to besedo, ki jo Gospod govori zoper vas, sinovi Izraelovi, zoper vso rodovino, ki sem jo peljal gori iz Egipta, ko pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 2, 'Samo vas sem spoznal izmed vseh rodovin na zemlji; zato bom kaznoval nad vami vse krivice vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 3, 'Moreta li dva skupaj hoditi, ako se ne sporazumeta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 4, 'Rjove li lev v gozdu, če nima ropa? Zažene li levič glas svoj iz brloga, ako ni kaj ulovil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 5, 'Zaplete li se mar ptica v mrežo na zemlji, če ji ni nastavljena zanka? Dvigne li se past od zemlje, če se ni nič ujelo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 6, 'Zabuči li trobenta v mestu, in ljudstvo se ne prestraši? Ali se pa v mestu zgodi nesreča, katere bi Gospod ne bil napravil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 7, 'Kajti Gospod Jehova ne stori ničesar, da bi ne razodel skrivnosti svoje služabnikom svojim, prorokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 8, 'Lev je rjovel, kdo naj bi se ne bal? Gospod Jehova je govoril, kdo naj bi ne prorokoval?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 9, 'Razglasite nad palačami v Asdodu in nad palačami po deželi Egiptovski in recite: Zberite se na samarijskih gorah in poglejte, kakšna grozna zmešnjava je v Samariji in koliko zatiranja sredi nje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 10, 'In ne znajo pošteno ravnati, govori Gospod, tisti, ki kopičijo, kar so s krivico in silo pridobili, v palačah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 11, 'Zatorej pravi tako Gospod Jehova: Sovražnik bode okoli vse dežele in zvrne moč tvojo s tebe na tla, in oplenjene bodo palače tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 12, 'Tako pravi Gospod: Kakor pastir otme levu iz žrela dve krači ali konec ušesa, tako bodo oteti sinovi Izraelovi, ki sedé v Samariji v kotu na blazini ali na damastovi počivalnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 13, 'Poslušajte in izpričajte to zoper hišo Jakobovo, govori Gospod Jehova, Bog nad vojskami:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 14, 'tisti dan, kadar bom kaznoval pregrehe Izraelove na njem, obiščem tudi oltarje v Betelu, in odbiti bodo rogovi oltarju, da popadajo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 3, 15, 'In podrem zimsko hišo s poletno hišo vred, in pokončane bodo hiše slonokoščene, velike hiše izginejo, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 1, 'Čujte to besedo, krave basánske, ki ste na gori Samarije, ki tlačite ubožca, tarete potrebnega in pravite svojim gospodarjem: Prinesi, da pijemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 2, 'Prisegel je Gospod Jehova pri svetosti svoji: Glejte, pridejo dnevi nad vas, da vas bodo vlekli stran s trnki in ostanek vaš z vodicami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 3, 'In pojdete ven skozi vrzeli, vsaka naravnost predse, in boste pahnjene v Harmon, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 4, 'Le hodíte v Betel in se pregrešujte, v Gilgalu množite prestopke! In prinašajte vsako jutro klalne daritve, vsak tretji dan desetine svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 5, 'in zažigajte okvašeno v hvalno daritev ter razglašujte prostovoljne darove in jih oznanjajte! To vam je namreč všeč, o sinovi Izraelovi, govori Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 6, 'Saj tudi jaz sem vam dal čiste zobe po vseh mestih vaših in pomanjkanje kruha po vseh krajih vaših, a vendar se niste povrnili prav do mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 7, 'In jaz sem vam tudi zadržal dež, ko je bilo še tri mesece do žetve; in na eno mesto sem dal dežiti, na drugo pa ne, ena njiva je bila z dežjem pomočena, njiva pa, ki nanjo ni dežilo, se je posušila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 8, 'in iz dveh, treh mest so se opotekali do enega mesta, da bi pili vodo, a niso se odžejali. Vendar se niste povrnili prav do mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 9, 'Udaril sem vas snetjo in strupeno roso, množino vaših vrtov in vinogradov in smokev in oljk so požrle kobilice. Vendar se niste povrnili prav do mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 10, 'Poslal sem med vas kugo po načinu egiptovskem; mladeniče vaše sem usmrtil z mečem in obenem sem dal odpeljati vaše konje in storil sem, da je smrad iz vaših šatorišč puhtel prav do vaših nosnic. Vendar se niste povrnili prav do mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 11, 'Razdejal sem nekatere kraje vaše, kakor je Bog razdejal Sodomo in Gomoro; in bili ste kakor glavnja, potegnjena iz ognja. Vendar se niste povrnili prav do mene, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 12, 'Zavoljo tega ti hočem tako storiti, o Izrael; in ker ti to hočem storiti, pripravi se, Izrael, da pojdeš Bogu naproti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 4, 13, 'Kajti, glej, on, ki upodablja gore in ustvarja veter in oznanja človeku, kakšno je mišljenje njegovo, ki dela iz jutranje zarje temo in stopa po višavah zemeljskih: Jehova, Bog nad vojskami, je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 1, 'Čujte to besedo, žalostinko, ki jo pojem nad vami, o hiša Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 2, 'Padla je devica Izraelova, ne vstane več, vržena je ob tla, ni ga, ki bi jo vzdignil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 3, 'Kajti tako pravi Gospod Jehova: Mestu, iz katerega jih je hodilo tisoč, jih preostane sto, in njemu, iz katerega jih je hodilo sto, jih preostane deset za hišo Izraelovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 4, 'Kajti tako pravi Gospod hiši Izraelovi: Iščite me, in boste živeli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 5, 'In ne iščite Betela in ne hodite v Gilgal in ne zahajajte v Bersebo; kajti Gilgal bo gotovo odpeljan v sužnost in Betel pride v nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 6, 'Iščite Gospoda, in boste živeli! Sicer pridere kakor ogenj v hišo Jožefovo in jo požre, in ne bo v Betelu nikogar, ki bi pogasil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 7, 'Vi, ki prevračate pravico v pelin in teptate pravičnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 8, 'iščite njega, ki je naredil gostosevce in rimščice, ki izpreminja smrtno senco v jutro in dan mrači v noč, ki kliče vode iz morja ter jih razliva po površju zemlje: Jehova je ime njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 9, 'ki spravlja naglo potrtje nad močnega, da pokončevanje nastane v trdnjavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 10, 'Oni sovražijo njega, ki pravično razsoja med vrati, in studijo njega, ki govori o brezmadežnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 11, 'Zatorej, ker teptate ubožca in od njega izterjavate davek od žita: sezidali ste hiše iz obdelanih kamenov, a ne boste prebivali v njih, zasadili ste krasne vinograde, a ne boste pili vina iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 12, 'Vem namreč, kako obilni so prestopki vaši in kako mnogoštevilni grehi vaši – da stiskate pravičnika, jemljete podkupila in krivite pravico revežev med vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 13, 'Zato, kdor je moder, molči v tem času, ker čas je hud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 14, 'Iščite dobrega, ne pa hudega, da boste živeli; in tako bode z vami Gospod, Bog nad vojskami, kakor pravite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 15, 'Sovražite hudo in ljubite dobro, uveljavite pravico med vrati; morda se usmili Gospod, Bog nad vojskami ostanka Jožefovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 16, 'Zatorej pravi tako Jehova, Bog nad vojskami, Gospod: Po vseh trgih bo plakanje; in po vseh ulicah bodo vpili: Gorje, gorje! in klicali bodo orača k žalovanju in izučene k žalovanju, naj plakajo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 17, 'in po vseh vinogradih bode plakanje. Kajti pojdem skozi tebe, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 18, 'Gorje vam, ki želite dneva Gospodovega! Čemu naj vam bode dan Gospodov? Tema bode, ne pa luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 19, 'Bode, kakor če kdo beži izpred leva, pa ga sreča medved; in stopi v hišo ter se nasloni na steno z roko, in ga piči kača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 20, 'Ne bode li dan Gospodov tema, ne pa luč? črn mrak, ne pa svetloba?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 21, 'Sovražim, zaničujem praznike vaše in slavnostna zborovanja vaša mi niso všeč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 22, 'ako mi tudi darujete žgalne in jedilne dritve, mi niso prijetne, in na mirovne daritve od vaše pitane živine se ne maram ozreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 23, 'Spravi izpred mene vrišč svojih pesmi, in brenkanja tvojih strun nočem poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 24, 'A naj se privali pravica kakor voda in pravičnost kakor vedno tekoč potok!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 25, 'Ali ste mi darovali v puščavi klalne in jedilne daritve štirideset let, o hiša Izraelova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 26, 'Res, nosili ste šator svojega kralja in kip svojih malikov, zvezdo boga svojega, kar ste si naredili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 5, 27, 'Zato vas prepeljem v ujetništvo onostran Damaska, pravi Gospod, čigar ime Bog nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 1, 'Gorje lahkoživcem na Sionu in brezskrbnežem na gori Samarije, imenitnikom prvega med narodi, h katerim hodi hiša Izraelova!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 2, 'Pojdite tja v Kalne in poglejte, in preidite odondod v veliki Hamat, potem stopite doli v Gat Filistejcev: so li odličnejši nego ta kraljestva, ali pa je njih pokrajina večja od vaše pokrajine?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 3, 'vi, ki želite, da bodi daleč dan nesreče, in stol silovitosti si stavite blizu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 4, 'ki ležite na slonokoščenih posteljah in se raztegujete po svojih počivalnicah in jeste jagnjeta od črede in teleta iz pitalnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 5, 'ki pojete bedaste pesmi z glasom brenkelj, si izmišljate godala kakor David,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 6, 'ki pijete vino iz daritvenih čaš in se mazilite z najboljšimi mazili, a se ne žalostite nad rano Jožefovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 7, 'Zato pojdejo v sužnost na čelu ujetnikov, in preneha vriskanje njih, ki so se lenobno raztegovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 8, 'Gospod, Jehova, je prisegel pri samem sebi, govori Gospod, Bog nad vojskami: Jaz studim ponos Jakobov in sovražim palače njegove, zato izročim sovražniku mesto in vse, kar je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 9, 'In zgodi se, ako ostane deset mož v eni hiši, vendar umrjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 10, 'In kadar koga vzdigne sorodnik njegov, ki mu bo pogrebnik, da spravi kosti iz hiše, in ogovori njega, ki je v notranjem hišnem hramu: Je li še kdo pri tebi? ta pa reče: Nikogar ni več; tedaj poreče: Mólči! ker se ne sme spominjati imena Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 11, 'Kajti glej, Gospod ukaže, in udarijo veliko hišo, da bode v podrtine, in malo hišo, da bode v drobir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 12, 'Morejo li konji dirjati po skalovju, se li more morje orati z voli? da ste izprevrgli pravico v strup in sad pravičnosti v pelin?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 13, 'vi, ki se veselite tega, kar ni nič, ki govorite: Si li nismo po svoji moči dobili rogov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 6, 14, 'Kajti glejte, obudim zoper vas narod, o hiša Izraelova, govori Gospod, Bog nad vojskami, in vas bodo stiskali od vhoda v Hamat prav do potoka nižine Arabe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 1, 'To mi je pokazal Gospod Jehova: Glej, napravljal je roj kobilic, ko je jela poganjati otava; in glej, bila je otava po kraljevi košnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 2, 'In zgodi se, ko so dočista požrle vso travo zemlje, da rečem: O, Gospod Jehova, odpústi, prosim! kako naj obstoji Jakob? saj je majhen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 3, 'Gospodu je bilo žal za to. Ne bo se zgodilo, je rekel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 4, 'To mi je pokazal Gospod Jehova: Glej, Gospod Jehova je klical ogenj, da po njem izvrši sodbo; in požrl je ogenj veliko brezno in je hotel požreti tudi orno zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 5, 'Tedaj rečem: O, Gospod Jehova, odnehaj, prosim! kako naj obstoji Jakob? saj je majhen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 6, 'Gospodu je bilo žal za to. Tudi to se ne zgodi, je rekel Gospod Jehova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 7, 'To mi je pokazal: Glej, Gospod je stal na navpičnem zidu, in v roki njegovi je bila olovnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 8, 'In Gospod mi reče: Kaj vidiš, Amos? In odgovorim: Olovnico. In Gospod reče: Glej, denem olovnico na ljudstvo svoje izraelsko, po sredi njegovi; ne pojdem več mimo njega, prizanašajoč mu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 9, 'In opustošene bodo višave Izakove in svetišča Izraelova bodo razdejana; in z mečem vstanem zoper hišo Jeroboamovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 10, 'Tedaj je poslal Amazija, duhovnik v Betelu, k Jeroboamu, kralju Izraelovemu, in sporočil: Amos je napravil zaroto zoper tebe sredi hiše Izraelove; dežela ne more več prenašati vseh besed njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 11, 'Zakaj tako govori Amos: Jeroboam umrje po meču, in Izraela bodo gotovo odpeljali v ujetništvo iz zemlje njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 12, 'In Amazija veli Amosu: Videc, pojdi, zbeži v deželo Judovo in ondi jej svoj kruh in tam prorokuj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 13, 'ali v Betelu nikdar več ne prorokuj, kajti kraljevo svetišče je in dom kraljev je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 14, 'In odgovori Amos in reče Amaziju: Nisem bil prorok, tudi nisem bil izmed sinov proroških, ampak črednik sem bil in sem obiral divje smokve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 15, 'Vzel pa me je Gospod, ko sem za čredo hodil, in mi je velel Gospod: Pojdi, prorokuj ljudstvu mojemu Izraelu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 16, 'In sedaj poslušaj besedo Gospodovo: Ti praviš: Ne prorokuj o Izraelu in ne govóri zoper hišo Izakovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 7, 17, 'Zato pravi tako Gospod: Žena tvoja postane nečistnica v mestu, in sinovi tvoji in hčere tvoje padejo pod mečem, in zemlja tvoja bo razdeljena z mersko vrvico, ti sam pa umreš v ognušeni zemlji, in Izrael bo gotovo odpeljan v ujetništvo iz dežele svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 1, 'To mi je pokazal Gospod Jehova: Glej, koš z zrelim sadjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 2, 'In reče: Kaj vidiš, Amos? Odgovorim: Koš z zrelim sadjem. In mi reče Gospod: Konec je prišel na ljudstvo moje Izraela; ne pojdem več mimo njega, prizanašajoč mu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 3, 'In petje v palači se izprevrže v plakanje tisti dan, govori Gospod Jehova; trupel bo množica, vsepovsod jih bodo metali natihoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 4, 'Čujte to vi, ki bi hoteli pogoltniti potrebnega in uničiti ubožce v deželi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 5, 'ki govorite: Da bi le že minil mlaj, da bi prodajali žito, in sobota, da odpremo žitnice, da zmanjšamo mero in povišamo ceno in varamo z lažnivo tehtnico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 6, 'da kupimo siromaka za denar in potrebnega za par čevljev in da prodamo pleve za žito!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 7, 'Gospod je prisegel pri ponosu Jakobovem: Gotovo nikdar ne pozabim vseh njih del!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 8, 'Kako naj bi se za to ne tresla dežela in ne žaloval vsak prebivalec v njej? Res se vsa razlije kakor Nil, požene valove in upade kakor reka v Egiptu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 9, 'In zgodi se tisti dan, govori Gospod Jehova, da ukažem solncu zaiti opoldne ter spravim temo nad zemljo ob belem dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 10, 'In izpremenim praznike vaše v žalovanje in vse pesmi vaše v žalostinke in napravim raševnike za vsaka ledja in spravim na vsako glavo plešo, in naredim deželo enako kakor ob žalovanju po edinem sinu in njen konec kakor dan bridkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 11, 'Glej, pridejo dnevi, govori Gospod Jehova, da pošljem lakoto v deželo, a ne bodo lačni kruha in ne žejni vode, ampak da poslušajo besede Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 12, 'In bodo tavali od morja do morja in od severa k vzhodu, tekali bodo semtertja, da iščejo besede Gospodove, pa je ne bodo našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 13, 'Tisti dan bodo lepe device in zali mladeniči omedlevali od žeje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 8, 14, 'kateri prisegajo pri grehu Samarije in govore: Kakor res živi tvoj bog, o Dan! Tudi: Kakor res živi pot v Bersebo! in padejo in ne vstanejo več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 1, 'Videl sem Gospoda stati nad oltarjem, in je velel: Udari na stebrov glavič, da se tresejo pragi, in razbij jih v kosce na glavo njih vseh; in kar jih še preostane, pomorim z mečem: kdor se spusti v beg, ne ubeži, niti eden iz njih se ne reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 2, 'Ko bi pridrli v kraj mrtvih, tudi odtod jih izvleče roka moja, in ko bi stopili v nebesa, jih odondod privedem doli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 3, 'in ko bi se skrili na vrhu Karmela, jih poiščem in vzamem odtod; in ko bi se izpred mojih oči poskrili v globočine morja, tam zapovem kači, da jih piči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 4, 'in ko bi šli v sužnost pred svojimi sovražniki, tam zapovem meču, da jih pomori. In obrnem oko svoje proti njim v hudo in ne v dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 5, 'Kajti Gospod, Jehova nad vojskami, on se dotakne zemlje, in se taja in žalujejo vsi prebivalci na njej in se vsa razlije kakor Nil in zopet upade kakor reka egiptovska;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 6, 'on je zgradil v nebesih zgornji hram svoj in si utrdil obok nad zemljo; on kliče morske vode ter jih razliva po površju zemlje: Jehova je ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 7, 'Ali mi niste, o sinovi Izraelovi, kakor otroci Etiopcev? govori Gospod. Nisem li peljal Izraela iz dežele Egiptovske, Filistejcev pa iz Kaftorja in Sircev iz Kira?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 8, 'Glej, oči Gospoda Jehove so obrnjene zoper to pregrešno kraljestvo, in ga potrebim s površja zemlje; samo da docela ne iztrebim hiše Jakobove, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 9, 'Kajti glej, jaz ukažem, in rešetali bodo sinove Izraelove med vsemi narodi, kakor se trese žito na rešetu; a nobeno zrnce ne pade na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 10, 'Pod mečem umrjo vsi grešniki ljudstva mojega, kateri govore: Ne približa se nam in ne zadene nas nesreča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 11, 'Tisti dan vzdignem šator Davidov, ki je razpadel, in zazidam razpoke njegove in postavim razvaline njegove, in zidal ga bom kakor v dneh starodavnih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 12, 'da dobodo v last ostanek Edoma in vse narode, nad katerimi se je klicalo moje ime, govori Gospod, ki to napravlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 13, 'Glej, pridejo dnevi, govori Gospod, ko bo stopal orač precej za ženjcem in tlačilec grozdja takoj za sejalcem; in z gorá bo kapljalo sladko vino in vsi griči se raztajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 14, 'In pripeljem nazaj ujetništvo ljudstva svojega Izraela; in zgradili bodo opustošena mesta in v njih prebivali, in zasajali bodo vinograde in vino iz njih pili, in narejali bodo vrtove in jedli sadje ž njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (30, 9, 15, 'In zasadim jih na njih zemljo, in ne bodo več izruvani iz zemlje svoje, ki sem jo jim dal, pravi Gospod, Bog tvoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 1, 'Prikazen Obadijeva. Tako pravi Gospod Jehova o Edomu: Oznanilo smo slišali Gospodovo in poslanec je bil poslan med narode: „Vstanite in vzdignimo se v boj zoper njega!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 2, 'Glej, majhnega sem te storil med narodi, silno si zaničevan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 3, 'Prevzetnost srca tvojega te je premotila, ki prebivaš v razpoklinah skalnih, sedež imaš na višavi in v srcu svojem govoriš: Kdo me potegne na tla?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 4, 'Čeprav bi se visoko vznesel kakor orel in ako bi bilo med zvezdami postavljeno gnezdo tvoje: te potegnem doli od tam, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 5, 'Ako bi prišli k tebi tatje ali razbojniki po noči, – kako si pokončan! – ali bi ne kradli, dokler bi jim bilo dovolj? Če bi trgači prišli k tebi, ali bi vsaj paberka ne popustili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 6, 'Kako je preiskano, kar je Ezavovega, kako so se našli skriti zakladi njegovi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 7, 'Vsi zavezniki tvoji so te odpravili nazaj do meje; prekanili, premogli so te, ki so mir sklenili s teboj; kateri jedo kruh tvoj, so nastavili zadrgo pod tebe. Ni razuma pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 8, 'Ne pogubim li tisti dan, govori Gospod, modrih iz Edoma in razumnosti z gore Ezavove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 9, 'In tvoji junaki, o Teman, izgube pogum, zato da bo vsakdo iztrebljen z gore Ezavove v moritvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 10, 'Zavoljo silovitosti, storjene bratu tvojemu Jakobu, te pokrije sramota in iztrebljen boš na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 11, 'Oni dan, ko si stal nasproti, v dan, ko so tujci peljali stran imetje njegovo in so inostranci vstopili skozi vrata in so za Jeruzalem metali kocko, tedaj si tudi tí bil kakor eden od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 12, 'A ti ne bi bil smel všečno gledati dneva brata svojega v dan njegove nesreče in se ne veseliti nad sinovi Judovimi v dan njih pogube, ne se širokoustiti v dan stiske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 13, 'ti ne bi bil smel stopiti v vrata ljudstva mojega v dan nadloge njegove, prav ti ne bi bil smel všečno gledati nesreče njegove v dan nadloge njegove, ne roke iztegniti po blagu njegovem v dan nadloge njegove;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 14, 'ti ne bi bil smel stati ob razpotju, da bi posekal njegove ubežnike, in ne bi bil smel izročiti sovražniku tistih, ki so mu preostali v dan stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 15, 'Kajti dan Gospodov je blizu nad vsemi poganskimi narodi: kakor si storil ti, se bo storilo tebi; dejanje tvoje se ti povrne na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 16, 'Kakor ste namreč pili na gori svetosti moje, tako bodo neprestano pili vsi narodi; da, pili bodo in srkali in bodo kakor taki, ki jih nikdar ni bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 17, 'Ali na gori Sionu bode rešitev, in bode sveta; in v last prejme hiša Jakobova posesti onih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 18, 'In hiša Jakobova bode ogenj in hiša Jožefova plamen, hiša Ezavova pa strnišče; in bosta goreli med njimi in jih požrli, da ne preostane hiši Ezavovi noben ostanek; kajti Gospod je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 19, 'In tisti, ki so proti Jugu, posedejo gorovje Ezavovo, in kateri so na ravnini, Filistejo, tudi posedejo poljane Efraimove in poljane samarijske, Benjamin pa posede Gilead.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 20, 'Kateri pa so bili v sužnost odpeljani iz tega krdela sinov Izraelovih, posedejo, kar je last Kanaancev tja do Sarepte; in odpeljanci v sužnost iz Jeruzalema, ki so v Sefaradu, posedejo mesta na Jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (31, 1, 21, 'In rešitelji pojdejo na goro Sion, da sodijo goro Ezavovo. Kraljestvo pa bode Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 1, 'In prišla je beseda Gospodova Jonu, sinu Amitajevemu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 2, 'Vstani, pojdi v Ninive, mesto veliko, in kliči zoper njega; kajti njih zloba je prišla gori predme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 3, 'Ali Jona vstane, da bi zbežal v Tarsis izpred obličja Gospodovega; in gre doli v Jafo in zaloti ladjo, ki se je peljala v Tarsis; in plača brodnino in stopi vanjo, da bi se peljal ž njimi v Tarsis izpred obličja Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 4, 'A Gospod je zagnal močan veter na morje, in nastal je velik vihar na morju, da je hotelo ladjo razbiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 5, 'In mornarji se zboje in vpijejo vsak k svojemu bogu; in mečejo v morje orodje, ki je bilo na ladji, da bi si olajšali. Jona pa je bil šel na dno ladje in je legel in trdno zaspal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 6, 'Tedaj pristopi k njemu poveljnik ladje in mu reče: Kaj je s tabo, zaspanec? Vstani, kliči k svojemu Bogu! morebiti se nas spomni tvoj Bog, da ne poginemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 7, 'In reko drug drugemu: Pridite, mečimo kocke, da zvemo, zavoljo koga nas je zadela ta nadloga. In mečejo kocke, in kocka pade na Jona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 8, 'Tedaj mu reko: Povej nam, prosimo, zavoljo česa nas je zadela ta nadloga? Kakšno je tvoje opravilo in odkod si prišel? Katera je tvoja dežela in iz katerega si ljudstva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 9, 'In jim reče: Hebrejec sem, in bojim se Gospoda, Boga nebes, ki je naredil morje in suhoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 10, 'Tedaj prevzame može velik strah, in mu reko: Čemu si to storil? Vedeli so namreč možje, da je zbežal izpred obličja Gospodovega, ker jim je bil povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 11, 'In ga vprašajo: Kaj hočemo storiti s teboj, da se morje pomiri proti nam? Kajti morje je vedno bolj divjalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 12, 'In jim reče: Vzemite me in vrzite me v morje, in morje se pomiri proti vam. V svesti sem si namreč, da je zavoljo mene prišel ta veliki vihar nad vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 13, 'A možje so hrabro veslali, da bi pritegnili ladjo nazaj h kopnemu, a niso mogli, ker je morje bolj in bolj divjalo proti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 14, 'Zato kličejo h Gospodu in reko: Ah, Gospod, prosimo, naj ne poginemo zavoljo tega moža duše in ne prištevaj nam nedolžne krvi; zakaj ti, Gospod, si storil, kakor je bila volja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 15, 'Nato vzamejo Jona in ga vržejo v morje. In morje je nehalo besneti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 16, 'Možje pa so se bali z velikim strahom Gospoda, in darovali so klalščino Gospodu in storili obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 1, 17, 'In Gospod je pripravil veliko ribo, da bi požrla Jona. In Jona je bil v ribjem trebuhu tri dni in tri noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 1, 'In molil je Jona h Gospodu, svojemu Bogu, iz ribjega trebuha in rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 2, 'H Gospodu sem klical v stiski svoji, in mi je odgovoril; iz krila smrtnega kraja sem vpil, ti si uslišal glas moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 3, 'Kajti vrgel si me v globočino, v sredino morja, da so me vode objemale; vsi valovi in zagoni tvoji so drli čezme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 4, 'In rekel sem: Pahnjen sem izpred tvojih oči; vendar bom zopet gledal proti templju svetosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 5, 'Vode so me zagrnile do duše, globočina me je objela, morska trava se mi je ovijala okrog glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 6, 'Pogrezal sem se do podzidja gorá, zapahi zemlje so bili zaprti nad menoj za vekomaj. Tedaj si potegnil iz jame življenje moje, o Gospod, Bog moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 7, 'Ko je v meni hirala duša moja, sem se spominjal Gospoda, in molitev moja je prišla k tebi, v hram svetosti tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 8, 'Kateri časté ničemurnosti prazne, opuščajo Boga, milost svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 9, 'Ali jaz ti bom daroval z glasom zahvaljevanja; izpolnim, kar sem obljubil. Pri Gospodu je rešitev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 2, 10, 'In Gospod je velel ribi, in izbljuvala je Jona na kopno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 1, 'In prišla je beseda Gospodova drugič Jonu, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 2, 'Vstani, pojdi v Ninive, mesto veliko, in jim kliči oznanilo, ki ti ga povem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 3, 'Tedaj vstane Jona in gre v Ninive po besedi Gospodovi. Ninive pa so bile mesto veliko pred Bogom, tri dni hoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 4, 'In Jona je šel v mesto en dan hoda in je klical, govoreč: Še štirideset dni, in Ninive bodo razdejane!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 5, 'In ljudstvo v Ninivah je verovalo Bogu, in razglasili so post in se oblekli v raševino vsi, od največjega do najmanjšega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 6, 'In vest je prišla do kralja v Ninivah: in vstane s svojega prestola, sleče svoj plašč in se ogrne z raševnikom, in sede v pepel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 7, 'In da razglasiti v Ninivah: To je ukaz kralja in njegovih velikašev: Ljudje in živali, goved in drobnica naj ničesar ne pokusijo, naj se ne pasejo in ne pijo vode;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 8, 'temuč naj se pokrijejo z raševino ljudje in živali ter naj močno vpijejo k Bogu; in naj se izpreobrne vsakdo od hudobnega pota svojega in od krivice, ki je na rokah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 9, 'Kdo ve? Bog se morda obrne in se usmili in se odvrne od togote jeze svoje, da ne poginemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 3, 10, 'In Bog je videl njih dela, da so se izpreobrnili od hudobnega pota svojega, in mu je bilo žal za hudo, kar je govoril, da jim stori, in ni storil tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 1, 'To je Jona jako bolelo in se je jezil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 2, 'In molil je h Gospodu in rekel: Ah, Gospod, ni li to bila moja beseda, ko sem bil še v deželi svoji? Da se ognem temu, zato sem zbežal v Tarsis, kajti vedel sem, da si Bog mogočni milostljiv in poln usmiljenja, počasen za jezo in obilen v milosti in ti je žal hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 3, 'In sedaj, Gospod, prosim, vzemi dušo mojo od mene, ker mi je bolje umreti nego živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 4, 'Gospod pa reče: Je li prav, da se jeziš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 5, 'In Jona je šel ven iz mesta in je sedel ob vzhodu mestu nasproti. In ondi si napravi senčnico in sedi pod njo v senci, da bi videl, kaj se zgodi z mestom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 6, 'In Gospod, Bog, pripravi kloščevino in stori, da zraste nad Jonom, da mu bode senca nad glavo in ga reši slabe volje. In Jona se veseli kloščevine z velikim veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 7, 'Drugi dan pa ob zori pripravi Bog črva, ki je izpodjedel kloščevino, da je usahnila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 8, 'In zgodi se ob solnčnem vzhodu, da pripravi Bog suh vzhodni veter; in solnce je peklo Jona v glavo, da je obnemogel. In želel je smrti duši svoji in rekel: Bolje mi je umreti nego živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 9, 'Bog pa reče Jonu: Je li prav, da se jeziš zavoljo kloščevine? In odgovori: Prav je, da se jezim do smrti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 10, 'Gospod pa reče: Tebi se smili kloščevina, za katero se nisi trudil in je nisi vzredil, ki je eno noč postala in eno noč poginila:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (32, 4, 11, 'in meni naj se ne smili Niniv, mesta velikega, v katerem je več nego stoindvajset tisoč ljudi, ki ne vedo razločka med desnico in levico svojo, in toliko živine!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 1, 'Beseda Gospodova, ki je prišla Mihu iz Moraste v dneh Jotama, Ahaza in Ezekija, kraljev Judovih, ki jo je v prikazni slišal o Judi in Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 2, 'Čujte, ljudstva vsa, in pazi, o zemlja in vse, kar je na njej! In Gospod Jehova bodi priča zoper vas, Gospod iz templja svoje svetosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 3, 'Kajti glejte, Gospod prihaja iz kraja svojega in pride doli in bo stopal po višavah zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 4, 'In gore se bodo topile pod njim in doline pokale kakor vosek pri ognju, kakor vode, ki se izlivajo po strmini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 5, 'Vse to se zgodi zavoljo pregrehe Jakobove in zavoljo grehov hiše Izraelove. Odkod je pregreha Jakobova? ni li iz Samarije? In odkod so višave Judove? Niso li iz Jeruzalema?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 6, 'Zato naredim Samarijo v grobljo na polju, kakor ko hočejo zasaditi vinograd, in pomečem kamenje njeno v dolino in odkrijem njene temelje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 7, 'In vse njene ulite podobe se razbijejo in vsa njena darila se sežgo z ognjem, in vse malike njene razrušim; kajti nabrala jih je iz vlačugarskega plačila in v vlačugarsko plačilo se povrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 8, 'Zato hočem plakati in tuliti, hoditi kakor oplenjen vsega in nag; zaženem plakanje kakor šakali in žalovanje kakor noji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 9, 'Zakaj rana njena je neozdravljiva; razlezla se je do Jude, sega prav do vrat ljudstva mojega, do Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 10, 'Ne povejte tega v Gatu, nikar ne jokajte! V Betleafri se valjam po pepelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 11, 'Pojdi na ono stran, prebivalka v Šafirju, z odkrito sramoto; prebivalka v Zaananu ni šla ven; plakanje v Betezelu vam ne dopušča, da bi tam počivali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 12, 'Kajti prebivalka v Zarotu trepeta za svoje imetje; ker od Gospoda je prišla nesreča doli k vratom Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 13, 'Naprezi hitre konje v vozove, prebivalka v Lahisu! Ti si bila začetek greha hčeri sionski; kajti v tebi so se našle pregrehe Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 14, 'Zato moraš dati odpovedno darilo Morešetu v Gatu. Hiše v Akzibu bodo v prevaro kraljem Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 15, 'Še ga pripeljem k tebi, prebivalka v Maresi, ki te dobi v last. Prav do Adulama pride slava Izraelova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 1, 16, 'Obrij se in ostrizi se zavoljo otrok svojega veselja; razširi si plešo kakor jastreb! Kajti morali so iti od tebe v sužnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 1, 'Gorje jim, ki izmišljajo krivičnost in pripravljajo hudobnost na ležiščih svojih! Ko zasveti jutro, jo izvršujejo, ker je v moči njih roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 2, 'Želja jih je po njivah, pa jih ugrabijo, in po hišah, pa jih vzemo, in silo delajo možu in hiši njegovi, človeku in dediščini njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 3, 'Zatorej pravi tako Gospod: Glej, namerjam nesrečo zoper to rodovino, ki ji ne odtegnete svojih vratov in pod katero ne boste več ošabno hodili, ker čas je hud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 4, 'Tisti dan začno zabavljico o vas in zapojo žalostinko: „Zgodilo se je!“bodo pravili, „docela smo opustošeni. Delež ljudstva mojega zamenja lastnika; kako ga odjemlje meni! Odpadniku razdeljuje naše njive.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 5, 'Zato ne boš imel nikogar, ki bi zate vrgel mersko vrvico ob žrebanju v zboru Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 6, '„Ne oznanjajte!“oznanjajo lažiproroki. Ako se ne oznanja onim, ne mine sramota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 7, 'Se li bo reklo, hiša Jakobova, da je nagle jeze Gospod? So li takšna dejanja njegova? Niso li besede moje prijazne njemu, ki živi pošteno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 8, 'Še ondan se je uprlo ljudstvo moje kakor sovražnik: iznad suknje jemljete plašč njim, ki gredo brezskrbno mimo, ki so nasprotni vojski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 9, 'Žene ljudstva mojega podite iz hiš njih veselja, njih otročičem kradete moj kras za vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 10, 'Vstanite in pojdite! ker ta dežela ni vam počivališče zavoljo nečednosti, ki uničuje, in to s strašno pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 11, 'Ko bi bil človek, ki se žene za vetrom in sleparsko laže: „Prorokoval ti bom o vinu in močni pijači“, ta bi bil prorok temu ljudstvu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 12, 'Gotovo te zberem, o Jakob, tebe vsega; gotovo skupim ostanek Izraelov; skupaj jih denem kakor ovce v Bozri, kakor čredo na njenem pašniku, da bode velik hrup od množice ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 2, 13, 'Prodiralec pojde gori pred njimi; proderejo in pojdejo skozi vrata in bodo skozi nje hodili ven; in njih kralj pojde pred njimi in Gospod na njih čelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 1, 'In rekel sem: Čujte, prosim, glave Jakobove in knezi hiše Izraelove! Ni li vam dolžnost, da znate pravico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 2, 'ki sovražite dobro in ljubite hudo, trgate kožo ljudem in meso ž njih kosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 3, 'ki žrete ljudstva mojega meso in jim derete kožo in lomite kosti ter jih pripravljate kakor v lonec in kakor meso, ki se deva v kotel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 4, 'Tedaj bodo klicali h Gospodu, pa jim ne odgovori; in skrije jim obličje svoje tisti čas primerno temu, kakor so hudobno delali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 5, 'Tako pravi Gospod o prorokih, ki zapeljavajo ljudstvo moje, ki kličejo, dokler imajo kaj gristi z zobmi: Mir! njemu pa, kdor jim ničesar ne da v usta, napovedujejo vojsko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 6, 'Zato vam pride noč, da ne boste imeli prikazni, in tema, da ne boste prorokovali; in solnce zatone prorokom ter dan jim otemni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 7, 'In sramovali se bodo vidci in osramočeni bodo vedeži, in vsi si zakrijejo ustnice, ker ni odgovora Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 8, 'Jaz pa sem napolnjen z močjo po duhu Gospodovem in s sodbo in hrabrostjo, da bi oznanjal Jakobu pregreho njegovo in Izraelu njegov greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 9, 'Čujte to, pravim, glave hiše Jakobove in knezi hiše Izraelove, ki studite pravo sodbo in zvijate vse, kar je ravno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 10, 'ki zidate Sion s krvjo in Jeruzalem s krivico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 11, 'Mestne glave sodijo za darila in duhovniki v njem uče za plačilo in proroki v njem vedežujejo za denar; vendar se opirajo na Gospoda in govore: Mar ni Gospod med nami? nesreča ne pride nad nas nobena!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 3, 12, 'Zato se bo zavoljo vas oral Sion kakor njiva in Jeruzalem postane groblja in gora hiše božje z gozdom obrastel grič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 1, 'In zgodi se v poslednjih dneh, da bo utrjena gora hiše Gospodove na čelu vseh gorá in povišana nad hribe; in ljudstva bodo vrela k njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 2, 'In mnogi poganski narodi pojdejo in poreko: Pridite in pojdimo na goro Gospodovo in k hiši Boga Jakobovega! In učil nas bo pota svoja, in hodili bomo po njegovih stezah. Kajti s Siona pride postava in beseda Gospodova iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 3, 'In on bode sodnik med mnogimi ljudstvi in bo karal močne poganske narode v daljavi. In prekujejo svoje meče v orala in sulice v kosirje, ne vzdigne narod zoper narod meča in ne bodo se več učili vojske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 4, 'A sedeli bodo vsak pod svojo trto in pod svojo smokvo, in nihče jih ne bo strašil; kajti usta Gospoda nad vojskami so govorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 5, 'Kajti vsa ljudstva hodijo, vsako v imenu svojega boga, mi pa hodimo v imenu Gospoda, Boga svojega, vedno in vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 6, 'Tisti dan, govori Gospod, zberem, kar je šepavo, in spravim vkup, kar je zavrženo, in nje, s katerimi sem hudo ravnal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 7, 'in storim tisto, kar je šepalo, za ostanek, in tisto, kar je bilo daleč zavrženo, v mogočen narod; in Gospod jim bo kraljeval na gori Sionu odslej do vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 8, 'In ti, stolp črede, hrib hčere sionske, do tebe dospe in k tebi pride prejšnje gospostvo, kraljestvo hčere jeruzalemske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 9, 'Sedaj pa zakaj toliko vpiješ? Ni li kralja v tebi? ali pa je poginil svetovalec tvoj, da so te prijele bolečine kakor porodnico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 10, 'Trpi bolečine in trudi se kakor porodnica, o hči sionska! kajti sedaj pojdeš ven iz mesta in boš prebivala na polju in prideš prav do Babela. Ondi boš oteta, ondi te Gospod odkupi iz pesti sovražilcev tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 11, 'In sedaj so se zbrali zoper tebe mnogi narodi, ki pravijo: Bodi oskrunjena in oko naše naj gleda veselje svoje na Sionu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 12, 'Ali oni ne poznajo misli Gospodovih in ne umejo sklepa njegovega; kajti zbral jih je kakor snope na gumno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 4, 13, 'Vstani in mlati, hči sionska! kajti tvoj rog napravim železen in tvoje parklje bronaste, da razmaneš mnoga ljudstva ter da posvetiš njih dobiček Gospodu in njih imetje Gospodarju vse zemlje. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 1, 'Sedaj pa zberi čete svoje, o hči čet! oblego so napravili zoper nas; s palico bodo tepli po licu sodnika Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 2, 'In ti, Betlehem Efrata, premajhen, da bi bil med tisoči Judovimi: iz tebe mi pride tisti, ki ima biti vladar v Izraelu; njega izviri so od starodavnosti, od dni večnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 3, 'Zato jih izroči stiskalcem do časa, ko porodnica porodi; in ostanek bratov njegovih se povrne k sinovom Izraelovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 4, 'In bo stal in pasel čredo svojo v moči Gospodovi, v veličastju imena Gospoda, Boga svojega. In bodo mirno prebivali; kajti sedaj bode velik do koncev zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 5, 'In ta mož bode naš mir. Ko pride Asirec v deželo našo in ko stopi v palače naše, tedaj postavimo zoper njega sedem pastirjev in osem knezov med ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 6, 'In pasli bodo deželo Asirsko z mečem in deželo Nimrodovo med vrati njegovimi; in On otme nas Asircu, ko pride v deželo našo in ko stopi čez naše meje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 7, 'In ostanek Jakobov bode sredi mnogih narodov kakor rosa od Gospoda, kakor dež na travo, kar ne čaka nikogar in ničesar ne pričakuje od otrok človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 8, 'In ostanek Jakobov bode med poganskimi narodi, sredi mnogih ljudstev kakor lev med živalmi v gozdu, kakor mlad lev med čredami ovac, ki jih, ko gre skozi nje, tepta in trga, in ni ga, ki bi otel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 9, 'Povzdignjena bodi roka tvoja nad tvojimi zatiralci in vsi sovražniki tvoji naj bodo iztrebljeni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 10, 'In zgodi se tisti dan, govori Gospod, da iztrebim konje tvoje izsredi tebe in uničim vozove tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 11, 'In razdenem mesta dežele tvoje in vse gradove tvoje razrušim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 12, 'In izničim vedeževanje iz roke tvoje in čarovnikov ne boš več imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 13, 'In odpravim rezane podobe tvoje in poslikane stebre izsredi tebe, in ne boš se več klanjal rok svojih delu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 14, 'In izrujem Ašere, ki so sredi tebe, in pogubim mesta tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 5, 15, 'In maščevanje izvršim v jezi in srdu nad poganskimi narodi, ki niso poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 1, 'Čujte vendar, kar pravi Gospod: Vstani, pravdaj se vpričo gorá in hribi naj slišijo tvoj glas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 2, 'Poslušajte, o gore, pravdo Gospodovo, in vi nepremični temelji zemlje! Zakaj pravdo ima Gospod z ljudstvom svojim in z Izraelom mora obračunati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 3, 'Ljudstvo moje, kaj sem ti storil in s čim sem ti bil nadležen? Izpričaj zoper mene!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 4, 'Kajti pripeljal sem te gori iz dežele Egiptovske in te odrešil iz hiše sužnjev, in poslal sem pred teboj Mojzesa, Arona in Mirjamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 5, 'Ljudstvo moje, spomni se vendar, kaj je imel v mislih Balak, kralj moabski, in kaj mu je odgovoril Balam, sin Beorjev; kaj se je godilo od Sitima do Gilgala, da spoznaš pravična dela Gospodova! –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 6, 'S čim naj stopim pred Gospoda, se priklonim Bogu višave? Naj li stopim predenj z žgalnimi žrtvami, z enoletnimi teleti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 7, 'Ali se bo Gospod veselil tisoč ovnov, desettisoč potokov olja? Ali naj dam prvenca svojega za prestopek svoj, svojega telesa sad za greh duše svoje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 8, 'Naznanil ti je, o človek, kaj je dobro; in kaj zahteva Gospod od tebe, nego da strežeš pravici in ljubiš usmiljenje in da hodiš ponižno z Bogom svojim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 9, 'Glas Gospodov kliče mestu – in mož zdrave pameti se bo bal tvojega imena. Poslušajte šibo in njega, ki jo je pripravil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 10, 'So li še zakladi krivičnosti v hiši brezbožnikovi in premajhna mera, ki je prokleta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 11, '„Bodem li mar čist ob krivični tehtnici in če imam lažnive uteži v mošnji?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 12, 'Njih bogatini so polni silovitosti in njih prebivalci govore laž in imajo prevarljive jezike v ustih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 13, 'Zato te tudi jaz udarim neozdravljivo, te opustošim zavoljo grehov tvojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 14, 'Jedel boš, pa se ne nasitiš, in prazno ti ostane v notranjščini; v stran boš spravljal, a ne otmeš ničesar; in kar otmeš, izročim meču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 15, 'Sejal boš, pa ne boš žel; olivke boš tlačil, a z oljem se ne boš mazilil, tudi mošt, pa vina ne boš pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 6, 16, 'Kajti drže se postav Omrijevih in ravnajo prav kakor hiša Ahabova in žive po njih svetu: zato da te izdam ljudem v strmenje in prebivalce mesta v žvižganje; in nosili boste ljudstva mojega sramoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 1, 'Gorje meni! ker mi je, kakor ko so obrali sadje, kakor ko paberkujejo v vinogradu: ni ga grozda, da bi ga použil, ne zgodnje smokve, ki je želi duša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 2, 'Pobožni je izginil z zemlje in ni ga poštenjaka med ljudmi: vsi skupaj preže na kri, vsak lovi svojega brata z mrežo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 3, 'Po zlu sta iztegnjeni obe roki, da se jim le posreči. Knez zahteva, in sodnik sodi za plačilo, in velikaš izreka pogubo, ki je želi, in tako spletajo vse vkup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 4, 'Najboljši izmed njih je kakor trnov grm, najpoštenejši je kakor trnje v plotu. Dan tvojih stražarjev, tvoje obiskovanje je prišlo; sedaj nastane njih zmešnjava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 5, 'Ne verujte prijatelju, ne zanašajte se na zaupnika; varuj vrata svojih ust pred njo, ki ti leži v naročju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 6, 'Kajti sin se norčuje iz očeta, hči se upira materi, snaha tašči; sovražniki človeku so domačini njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 7, 'A jaz bom gledal na Gospoda, čakal bom Boga rešenja svojega; usliši me Bog moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 8, 'Ne veséli se nad menoj, sovražnica moja! ako sem padel, zopet vstanem; ako sedim v temi, Gospod mi je luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 9, 'Srd Gospodov bom prenašal, kajti grešil sem zoper njega; dokler se ne potegne za pravdo mojo in ne izvrši sodbe zame. Privede me ven na luč, gledal bom pravičnost njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 10, 'In videla bo to sovražnica moja, in sramota jo pokrije, ki mi je rekala: Kje je Gospod, Bog tvoj? Oči moje jo bodo z veseljem gledale: sedaj jo pogaze kakor blato na ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 11, 'Dan pride, ko se zgrade zidovi tvoji. Tisti dan se daleč razširi tvoja meja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 12, 'tisti dan pridejo k tebi iz Asirije in iz mest egiptovskih in od Egipta do velereke in od morja do morja in od gore do gore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 13, 'In zemlja postane puščava zavoljo prebivalcev svojih, zavoljo sadu njih dejanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 14, '„Pasi ljudstvo svoje s palico svojo, čredo svoje dediščine, ki osamela prebiva v gozdu, sredi Karmela; naj se pasejo v Basanu in Gileadu kakor v dneh starodavnih!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 15, 'Dam jim videti čudovita dela kakor v dneh, ko si šel iz dežele Egiptovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 16, 'Poganski narodi bodo to videli in sram jih bode vse moči svoje; polože roke na usta, njih ušesa ogluše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 17, 'prah bodo lizali kakor kače, kakor laznina na zemlji; pritrepetavali bodo iz gradov svojih; s strahom se obrnejo do Gospoda, Boga našega, in bali se bodo spričo tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 18, 'Kdo je, Bog mogočni, enak tebi, ki odpuščaš krivico in izpregleduješ prestopek ostanku dediščine svoje? Ti ne držiš jeze vekomaj, ker se veseliš milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 19, 'Ti se nas vnovič usmiliš, pogaziš krivice naše; ti vržeš v morja globočino vse grehe naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (33, 7, 20, 'Ti izkažeš resnico Jakobu in Abrahamu milost, kakor si jo prisegel očetom našim od dni starodavnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 1, 'Prorokovanje o Ninivah. Knjiga prikazni Nahuma Elkošana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 2, 'Gospod je Bog mogočni, gorečnik in maščevalec; maščevalec je Gospod in poln srda; Gospod vrši maščevanje nad svojimi nasprotniki in ne odpušča sovražnikom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 3, 'Gospod je počasen za jezo in velik v moči, a krivca nikakor ne šteje za nedolžnega. Pot Gospodov je v viharju in nevihti in oblaki so prah nogam njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 4, 'On zapreti morju in ga usuši, in vse reke posuša; Basan in Karmel hirata in cvetje na Libanonu vene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 5, 'Gore se tresejo pred njim in hribi se tajajo; pred obličjem njegovim se giblje zemlja in vesoljni svet in vsi, ki na njem prebivajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 6, 'Kdo more stati vpričo srda njegovega? in kdo obstoji ob gorečnosti jeze njegove? Togota njegova se razliva kakor ogenj in skale se rušijo pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 7, 'Dobrotljiv je Gospod, zavetišče je v dan stiske in pozna nje, ki pribegajo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 8, 'Ali s povodnijo, ki vse poplavi, pokonča njih mesto in sovražnike svoje požene v temo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 9, 'Kaj izmišljate zoper Gospoda? Popoln naredi konec; stiska ne vstane dvakrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 10, 'Kajti čeprav bi bili enaki izprepletenemu trnju in vina pijani, jih docela požre ogenj kakor suho strnišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 11, 'Iz vas, Ninive, je prišel, ki je izmišljal hudo zoper Gospoda, svetovalec Belijalov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 12, 'Tako pravi Gospod: Čeprav so čvrsti in še tako številni, vendar bodo pokošeni in izginejo. Če sem te, Juda, poniževal, ne bom te poniževal več;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 13, 'temuč zlomim sedaj njegov jarem raz tebe in raztrgam spone tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 14, 'In zastran tebe, Asur, je zapovedal Gospod, da se ne sme nič več sejati iz tvojega imena; iz hiše boga tvojega iztrebim rezane in ulite podobe; pripravim ti grob, kajti nič nisi vreden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 1, 15, 'Glej, na gorah noge njega, ki prinaša blagovestje, ki oznanja mir! Praznuj, Juda, praznike svoje, opravljaj obljube svoje! zakaj ničvrednež ne bo več hodil skozi tebe, ves je pokončan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 1, 'Razbijalec gre gori zoper vas, Ninive! Varujte trdnjave, zastražite pot, utrdite si s pasom ledja, silno pokrepčajte svojo moč!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 2, 'Kajti Gospod ponavlja diko Jakobovo kakor diko Izraelovo; zakaj plenilci so jih oplenili in ugonobili njih rozge!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 3, 'Ščiti njegovih junakov so rdeči, hrabri možje njegovi so oblečeni v karmezin, vozovi se z jeklom iskré v dan, ko jih pripravlja, in vojaki sučejo sulice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 4, 'Vozovi ropotajo po ulicah, dirjajo po trgih, videti jih je kakor bakle, privrševajo kakor bliski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 5, 'Spominja se kralj Niniv svojih plemenitnikov: spotikajo se v hoji, hitro planejo na mestni zid, postavijo streho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 6, 'Vrata ob rekah so odprta in voda poplavlja palačo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 7, 'In določeno je: Ninive bodo odkrite, odpeljane; in njih dekleta javkajo kakor z glasom golobic, bijoč se v prsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 8, 'Ninive so bile od nekdaj kakor ribnjak, poln vode; in vendar beže. ‚Stojte, stojte!‘pa nihče se ne obrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 9, 'Ropajte srebro, ropajte zlato! kajti zaloga nima konca, bogastvo vsakovrstnega dragocenega orodja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 10, 'Prazne so in izpraznjene in opustošene! in srce se taja, kolena se šibé, bolečina je v vseh ledjih in obrazi vseh so bledi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 11, 'Kje je zdaj ležišče levov in pašnik levičev, koder se je izprehajal lev, levinja in levič, in nihče jih ni strašil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 12, 'Lev je dovolj nalovil svojim mladičem in podavil svojim levinjam, in napolnil je brloge svoje s plenom in svoja ležišča z ropom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 2, 13, 'Glej, jaz sem zoper tebe, govori Gospod na vojskami, in požgem tvoje vozove, da izginejo v dimu, in tvoje mlade leve požre meč, in iztrebim plen tvoj z zemlje, in tvojih poslancev glas se ne bo nikdar več slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 1, 'Gorje okrvavljenemu mestu, vse polno je laži in silovitosti, ne neha ropati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 2, 'Biči pokajo in kolesa škripljejo, konji dirjajo in vozovi drdrajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 3, 'Konjiki pridirjavajo in meči se svetijo in sulice blesketajo! množica je pobitih in grmada mrtvih in trupel brez konca; čez njih trupla padajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 4, 'zavoljo mnogega nečistovanja preljubke nečistnice, izvedenke v čaranju, ki prodaja narode s svojim nečistovanjem in rodove s svojim čarovništvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 5, 'Glej, jaz sem zoper tebe, govori Gospod nad vojskami, in ti odgrnem rob suknje tvoje na obličje ter pokažem narodom nagoto tvojo in kraljestvom sramoto tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 6, 'In vržem nate blato in te storim ničvredno in te postavim na ogled.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 7, 'In vsak, kdor te bo videl, pobeži od tebe in poreče: Ninive so opustošene! Kdo jih bo pomiloval? Odkod naj ti poiščem tolažnikov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 8, 'Si mar boljši nego mesto Noamon, ki je stalo pri rekah in imelo vode okoli sebe? Morje mu je bilo branišče, zidovi so štrleli iz morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 9, 'Etiopija in Egipt sta bila njegova moč, in to brez konca; Put in Libija sta mu pomagala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 10, 'Tudi ono je bilo odpeljano, je šlo v ujetništvo; tudi njegove otročiče so razbijali po voglih vseh ulic, in za njegove plemenitnike so metali kocko, in vsi njegovi velikaši so bili vkovani v verige.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 11, 'Tudi ti boš upijanjeno, se boš moralo skriti; tudi ti boš iskalo zavetišča pred sovražnikom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 12, 'Vse tvoje trdnjave so kakor smokve z zgodnjimi sadovi: če se potresejo, padejo v usta njemu, kdor jih hoče jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 13, 'Glej, tvoje ljudstvo je kakor žene sredi tebe; sovražnikom tvojim so vrata dežele tvoje široko odprta, ogenj je požrl zapahe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 14, 'Zajmi si vode za čas oblege; popravi utrdbe svoje! Dróbi glino, tlači ilovico, utrdi opekarnico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 15, 'Tam te požre ogenj, te pokonča meč, požre te kakor glodalec, namnóži se, kakor glodalec, namnóži se kakor kobilice!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 16, 'Napravil si več trgovcev, nego je zvezd na nebu; glodalec se spusti na plen, potem odleti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 17, 'Tvoji izbranci so kakor kobilice in tvoji vojaški poveljniki kakor roji kobilic, ki sedé na plotovih, kadar je mraz; ko pa vzide solnce, odlete, in nihče ne ve, kje so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 18, 'Zaspali so pastirji tvoji, o kralj asirski, tvoji mogočneži počivajo; ljudstvo tvoje je razkropljeno po gorah in nikogar ni, ki bi ga zbral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (34, 3, 19, 'Ni ga hladila potrtju tvojemu, rana tvoja je smrtna! Vsi, ki slišijo tvojo zgodbo, ploskajo z rokami nad teboj; kajti na koga se ni razlivala tvoja hudobnost neprestano?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 1, 'Prorokovanje, ki ga je v prikazni prejel Habakuk, prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 2, 'Kako dolgo, o Gospod, sem vpil k tebi, in ne slišiš! Vpijem k tebi o nasilstvu, a ne rešiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 3, 'Zakaj dopuščaš, da vidim krivico, zakaj gledaš nadlogo? Kajti pustošenje in nasilstvo je pred menoj, in nastaja prepir in vnema se boj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 4, 'Zato izgublja postava veljavo in prava sodba ne pride nikdar na dan; kajti brezbožnik obdaja pravičnega, zato prihaja le popačena sodba na svetlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 5, 'Ozrite se v narode in poglejte, in čudite se, strmite; kajti delam v dneh vaših delo, ki ga ne boste verovali, če kdo pripoveduje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 6, 'Glejte, jaz obujam Kaldejce, tisto trdo in hitro ljudstvo, ki hodi po širjavi zemlje, da si lasti domovanja, ki niso njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 7, 'Strašno je in grozovito; sodba in mogočnost njegova izvirata od njega samega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 8, 'Čili so konji njegovi bolj nego pardi in hitrejši nego volkovi na večer; ponosno dirjajo konjiki njegovi, jezdeci njegovi prihajajo oddaleč, lete kakor orel, ki plane na jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 9, 'Vsi prihajajo zavoljo nasilstva! oči jim gledajo naravnost predse in ujetnike grabijo kakor pesek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 10, 'Smeje se to ljudstvo kraljem in knezi so mu v zasmeh; zasmehuje vsako trdnjavo, ker nanosi zemlje in jo vzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 11, 'Potem puhne kakor veter mimo in preide ter se pregreši: ta moč njegova mu je bog!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 12, 'Nisi li ti od vekomaj, Gospod, Bog moj in Svetnik moj? Mi ne umrjemo. O Gospod, za sodbo si ga postavil, o Skala, strahovanje si mu zaukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 13, 'Prečiste so tvoje oči, da bi gledal hudo, in nepravde ne moreš videti: zakaj gledaš na tiste, ki ravnajo izdajalski, molčiš, ko brezbožnik požira pravičnejšega od sebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 14, 'in dopuščaš, da se ravna z ljudmi kakor z morskimi ribami, kakor s črvadjo, ki nima vladarja? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 15, 'Vse jih lovi s trnkom, jih vleče v mreži svoji in zbira v svojo vršo; ob tem se veseli in vriska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 16, 'Zato daruje mreži in žge kadilo vrši svoji; kajti po njej ima debel delež in preobilen živež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 1, 17, 'Sme li zato vedno prazniti mrežo svojo in neprestano moriti narode neusmiljeno?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 1, 'Na svojo čuvajnico stopim in se postavim na stolp in bom oprezoval, da bi videl, kaj bo govoril z menoj in kaj naj odgovorim na svojo tožbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 2, 'In Gospod mi je odgovoril, rekoč: Zapiši prikazen in razločno začrkaj na plošče, da se lahko čita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 3, 'Kajti še velja prikazen za določeni čas in hiti do konca, in varala ne bo. Ako odlaša, je le čakaj; zakaj gotovo pride, se ne zakasni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 4, 'Glej, kdor je prevzeten, duša njegova ni poštena v njem. Pravični pa bo živel po svoji veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 5, 'In vrhutega – koliko prevare je v vinu! Ošabni mož nima obstanka, ki odpira kakor pekel žrelo svoje in kakor smrt ni nikdar sit, in grabi k sebi vse narode in vleče nase vsa ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 6, 'Ali ne začno vsi ti pregovora o njem in zabavljice in uganke o njem? in poreko: „Gorje mu, kdor zase kopiči, kar ni njegovo – doklej bo? in kdor nase deva zastavljeno blago!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 7, 'Ali ne vstanejo naglo, ki te bodo terjali za obresti, se li ne zbude, ki te poženejo s tvojega? in bodeš jim v plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 8, 'Ker si ti oplenil mnoge narode, zato te opleni ves ostanek vseh ljudstev zavoljo človeške krvi in nasilstva, ki si ga storil deželi, mestu in vsem prebivalcem v njem.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 9, 'Gorje mu, kdor grabi kriv dobiček za hišo svojo, da na visokem postavi gnezdo svoje, da se otme iz nesreče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 10, 'Sklenil si, kar je v sramoto hiši tvoji, pokončanje narodov mnogih, in s tem si grešil zoper dušo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 11, 'Kajti kamen bo vpil iz stene in prečnica iz lesovja mu bo odgovarjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 12, 'Gorje mu, kdor gradi mesta s krvjo in ustanavlja gradove s krivico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 13, 'Glej, ni li to od Gospoda nad vojskami, da se ljudstva trudijo za ogenj in narodi mučijo za nič?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 14, 'Kajti zemlja bode polna spoznanja slave Gospodove, kakor vode pokrivajo morja globočino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 15, 'Gorje mu, kdor da pijačo bližnjemu svojemu in jo nameša s svojim žolčem, in ga tako upijani, da bi gledal nagoto njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 16, 'Nasitil si se sramote namesto časti; pij tudi ti in kaži svojo neobrezo! Prideš tudi na vrsto, da prejmeš čašo iz desnice Gospodove, in sramotno pljuvanje pride na slavo tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 17, 'Kajti nasilstvo, storjeno na Libanonu, te pokrije in poguba živali te bo strašila zavoljo človeške krvi in nasilstva, ki si ga storil deželi, mestu in vsem prebivalcem v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 18, 'Kaj pomaga rezana podoba, da jo je izrezal podobar? kaj pomaga ulita podoba in učiteljica laži, da upa obraznik v svoj izdelek in še nareja neme malike?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 19, 'Gorje mu, ki veleva lesu: Zbudi se! nememu kamenu: Vstani! Ta naj uči? Glej, prevlečen je z zlatom in srebrom in še diha ni v njem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 2, 20, 'Ali Gospod je v templju svetosti svoje – mólči pred njim, vsa zemlja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 1, 'Molitev proroka Habakuka, z godbo na strune.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 2, 'Gospod, slišal sem tvoje poročilo in se bojim; Gospod, ožívi delo svoje sredi let, sredi let daj, da bo očitno; v jezi se spominjaj usmiljenja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 3, 'Bog prihaja s Temana in Svetnik z gore Parana. (Sela.) Veličastvo njegovo pokriva nebesa in zemlja je polna hvale njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 4, 'In svetloba nastaja kakor solnčna luč; žarki se mu iskré iz roke, in ondi je skrita njegova moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 5, 'Pred njim gre kuga in tik za njim pomor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 6, 'Postal je in potresel je zemljo, pogledal je in ustrašil narode; in razdrobile so se večne gore, starodavni hribi so se pogreznili; pota njegova so večna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 7, 'V bridkosti sem videl šatore Kušanove, tresle so se preproge šatorov v deželi Madianovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 8, 'Jezen li je Gospod nad rekami? je li mar jeza tvoja nad rekami, srd tvoj nad morjem, da jezdiš na svojih konjih, na vozovih zveličalnih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 9, 'Gol, pripravljen je lok tvoj. Šibe v strahovanje si prisegel z besedo svojo. (Sela.) Zemljo si razklal z rekami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 10, 'Videle so te gore in se tresle; usula se je ploha, brezno je grmelo, visoko je vzdigovalo roke svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 11, 'Solnce in mesec sta stopila v svoje bivališče ob luči tvojih pšic, ko so frčale, ob svetlosti tvoje kliskajoče se sulice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 12, 'V togoti si stopal po zemlji, v srdu si teptal narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 13, 'Izšel si v rešenje svojega ljudstva, v rešenje maziljenca svojega; razbil si glavo iz hiše brezbožneža, odgrnivši ga od tal do vratu. (Sela.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 14, 'Prebodel si z lastnimi mu sulicami glave njegovih vojščakov, ki so prihruli kakor vihar, da bi me razkropili; njih veselje je bilo požreti ubožca na skrivnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 15, 'Na morje si stopil s konji svojimi, med roj velikih vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 16, 'Slišal sem to, in treslo se mi je telo; ustne moje so trepetale ob tistem glasu; trhloba mi je prešinila kosti in tresem se na svojem mestu: da naj počivam ob dnevi stiske, kadar pride zoper ljudstvo tisti, ki ga hoče napasti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 17, 'Kajti smokva ne bo cvetla in pridelka ne bode nič na trtah, oljkova rast bo varala in žitno polje ne donese užitka, iz ograje izgine drobnica in govedi ne bo nič v hlevih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 18, 'a jaz se bom vendar radoval v Gospodu, veselil se bom, da je Bog rešenje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (35, 3, 19, 'Jehova, Gospod, je moja moč, on dela, da so moje noge kakor jelenje, in stori, da bom hodil po višavah svojih. Načelniku godbe, na moje strune.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 1, 'Beseda Gospodova, ki je prišla Zefaniju, sinu Kušija, sina Gedalija, sina Amarija, sina Hezekija, v dneh Josija, sina Amonovega, kralja Judovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 2, 'Docela pokončam vse s površja zemlje, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 3, 'Pokončam ljudi in živino, pokončam ptice nebeške in ribe morske in pohujševanje z brezbožniki vred; in iztrebim ljudi s površja zemlje, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 4, 'In iztegnem roko zoper Judo in zoper vse prebivalce v Jeruzalemu; in iztrebim ostanek Baala iz tega kraja, imena malikovalskih svečenikov z duhovniki vred,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 5, 'in tiste, ki se poklanjajo na strehah vojski nebeški, in molilce, ki prisegajo Gospodu in prisegajo pri Malkomu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 6, 'in nje, ki odstopajo od Gospoda in ki ne iščejo Gospoda in po njem ne vprašujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 7, 'Molčite pred obličjem Gospoda Jehove! kajti blizu je dan Gospodov; ker pripravil je Gospod klalno daritev, posvetil je svoje povabljence.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 8, 'In zgodi se v dan klalne daritve Gospodove, da bom kaznoval poglavarje in sinove kraljeve in vse, ki se oblačijo v inozemsko obleko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 9, 'In kaznoval bom tisti dan vsakega, ki skače čez prag, vse, ki napolnjujejo gospodarja svojega hišo s silovitostjo in prevaro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 10, 'In tisti dan, govori Gospod, se bo slišalo vpitje od Ribjih vrat in tuljenje od dolnjega mesta in veliko podiranje od hribov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 11, 'Tulite, prebivalci v Maktešu! kajti uničeno je vse trgovsko ljudstvo, iztrebljeni so vsi, ki so bili obremenjeni s srebrom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 12, 'In zgodi se tisti čas, da preiščem Jeruzalem s svetilnicami, in kaznoval bom može, ki počivajo na svojih drožeh, ki govore v srcu svojem: Gospod ne stori nič dobrega, pa tudi nič hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 13, 'In njih imetje bode v plen in njih hiše v pustoto; in zidali bodo hiše, a ne bodo prebivali v njih, in sadili vinograde, a ne bodo pili vina iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 14, 'Blizu je veliki dan Gospodov, blizu je in silno hiti. Čuj, dan Gospodov! bridko vpije tam junak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 15, 'Ta dan je dan srda, dan stiske in nadloge, dan pustote in pustošenja, dan teme in mraka, dan oblakov in noči oblačne,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 16, 'dan trombe in bojnega vpitja zoper trdna mesta in zoper visoke utrdbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 17, 'In stiskal bom ljudi, da bodo hodili kakor slepci, ker so grešili zoper Gospoda; in njih kri se razmeče kakor prah in njih meso kakor blato.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 1, 18, 'Tudi njih srebro, tudi njih zlato jih ne bo moglo rešiti ob dnevi jeze Gospodove; in z ognjem gorečnosti njegove bo vsa dežela požrta; zakaj konec, nagel konec naredi vsem prebivalcem dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 1, 'Zberite se, da, zberite se, o narod brezsramni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 2, 'preden se uresniči, kar je ukrenjeno (tisti dan poleti mimo kakor pleve), preden pride nad vas togota srda Gospodovega, preden pride nad vas dan jeze Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 3, 'Iščite Gospoda, vsi krotki v deželi, ki ste vršili sodbo njegovo; iščite pravičnost, iščite ponižnost, morda doboste skrivališče ob dnevi jeze Gospodove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 4, 'Kajti Gaza bo opuščena in Askelon bo puščava, iz Asdoda preženo prebivalce ob belem dne in Ekron bo izruvan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 5, 'Gorje prebivalcem v pokrajini ob morju, narodu Keretejcev! Beseda Gospodova je zoper tebe, o Kanaan, dežela Filistejcev! pogubim te, da ne bode prebivalca!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 6, 'In pokrajina ob morju postane pašnik s kočami za pastirje in z ograjami za drobnico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 7, 'in bode pokrajina za ostanek hiše Judove: po njej bodo pasli, v hišah askelonskih bodo zvečer počivali; kajti obišče jih Gospod, njih Bog, in nazaj pripelje njih ujetništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 8, 'Slišal sem zasmehovanje Moabovo in preklinjanje sinov Amonovih, s katerim so zasmehovali ljudstvo moje in sebe veličili proti njegovemu kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 9, 'Zatorej, kakor res živim, govori Gospod nad vojskami, Bog Izraelov: Gotovo bode Moab kakor Sodoma in sinovi Amonovi kakor Gomora, koprivja posest in solne jame in večna puščava. Ljudstva mojega ostanek jih opleni in preostanek naroda mojega jih dobi v dedno last.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 10, 'To se jim zgodi za njih prevzetnost, ker so zasmehovali ljudstvo Gospoda nad vojskami in se proti njemu veličili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 11, 'Strašen jim bode Gospod, kajti stori, da izginejo vsi bogovi zemlje; in po vseh otokih poganskih narodov ga bodo molili, vsakdo s svojega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 12, 'Tudi vi, Etiopci, boste pobiti z mojim mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 13, 'In on iztegne roko proti severu in uniči Asirijo in Ninive naredi v samoto, suho kakor puščava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 14, 'In ležale bodo sredi mesta črede, vsake vrste živali; tudi pelikani in ježi bodo prenočevali na glavičih njih stebrov. Glas vetra bo pel v oknu, razvaline bodo na pragih, ker odtrgani so cedrovi obložci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 2, 15, 'To je tisto veselo mesto, ki je prebivalo brez skrbi, ki je govorilo v srcu svojem: Jaz sem in nobenega ni razen mene! Kako je postalo v puščavo, v ležišče zverini! Vsak, kdor pojde mimo, bo žvižgal, mahal z roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 1, 'Gorje tisti upornici in gnusnici, temu silovitemu mestu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 2, 'Nobenega glasu ni poslušalo, za nobeno svarilo ni bilo dovzetno; v Gospoda ni upalo, ni se bližalo svojemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 3, 'Njegovi poglavarji sredi njega so rjoveči levi, njegovi sodniki kakor volkovi zvečer, ki še kosti ne ostavijo do jutra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 4, 'Njegovi proroki so bahavci, zvijačni možje; njegovi duhovniki skrunijo svetišče, na zlo zvijajo postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 5, 'Gospod je pravičen sredi njega, krivice ne dela nobene; vsako jutro stavi na svetlo pravico svojo, ne pogreši v tem. Krivičnik pa ne pozna sramu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 6, 'Iztrebil sem poganske narode, njih utrdbe so razvaljene; opustošil sem njih ceste, da nihče ne hodi po njih; njih mesta so razdejana, da v njih ni nikogar, nobenega prebivalca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 7, 'Rekel sem temu mestu: O da bi se le balo mene, da bi sprejelo svarjenje! tedaj bi se ne smelo razdejati bivališče njegovo, izbrisalo bi se vse, kar sem določil o njem. A vendar so že zgodaj pačili vse dejanje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 8, 'Zato me čakajte, govori Gospod, do dne, ko vstanem, da bi plenil! Kajti sklep moj je, da zberem narode, skupim kraljestva, da izlijem nadnje srd svoj, vso gorečo jezo svojo; kajti v ognju gorečnosti moje bo požrta vsa zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 9, 'Kajti takrat izpremenim narodom ustnice, da bodo čiste, da bi vsi klicali ime Gospodovo in mu služili enodušno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 10, 'Z one strani etiopskih rek privedejo molilce moje, hčer razkropljencev mojih, meni v darilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 11, 'Tisti dan se ti ne bode treba sramovati vseh dejanj, s katerimi si se pregrešila zoper mene; kajti takrat odpravim izmed tebe ošabne širokoustneže tvoje, in se ne boš več prevzemala na gori svetosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 12, 'In ostavim sredi tebe ponižno in ubogo ljudstvo, ti bodo upali v ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 13, 'Ostanki Izraelovi ne bodo delali krivice, ne govorili laži in v njih ustih ne bo prevarljivega jezika, temuč bodo pasli in počivali in ga ne bode, ki bi jih strašil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 14, 'Glasno poj, o hči sionska, ukajte, ki ste Izraelovi! veséli se in raduj iz vsega srca, hči jeruzalemska!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 15, 'Odvzel je Gospod sodbe tvoje, odstranil sovražnika tvojega. Kralj Izraelov, Jehova, je sredi tebe, nesreče ne boš več videla nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 16, 'Tisti dan poreko Jeruzalemu: Ne boj se! Sion, tvoje roke naj ne omagajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 17, 'Jehova, tvoj Bog, je sredi tebe, junak, ki hoče rešiti; veseli se te presilno, molči v ljubezni svoji, raduje se nad teboj z glasnim petjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 18, 'Zberem tiste, ki žalujejo po prazničnem zborovanju; iz tebe so bili, sramota jih je težila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 19, 'Glej, jaz bom ravnal tisti čas z vsemi stiskalci tvojimi, in rešim hrome in zberem izvržene in jim napravim hvalo in sloveče ime po vseh deželah, kjer so zdaj v sramoti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (36, 3, 20, 'Tisti čas vas privedem sem in tisti čas vas zberem; kajti v sloveče ime in v hvalo vas storim med vsemi ljudstvi na zemlji, ko nazaj pripeljem ujetništvo vaše pred vašimi očmi, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 1, 'V drugem letu kralja Darija, v šestem mesecu, prvi dan meseca, je prišla beseda Gospodova Zerubabelu, sinu Sealtiela, deželnemu oblastniku na Judovem, in Jozuetu, sinu Jozadakovemu, velikemu duhovniku, in je rekel po proroku Hagaju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 2, 'Tako pravi Gospod nad vojskami: To ljudstvo govori: Ni še prišel čas, čas hiši Gospodovi, da jo zgradimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 3, 'A beseda Gospodova je prišla po proroku Hagaju in je rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 4, 'Za vas same pa je čas, da prebivate v svojih z deskami obitih hišah, hiša ta pa bodi pusta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 5, 'Sedaj pa pravi tako Gospod nad vojskami: Pazite na svoja pota!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 6, 'Veliko ste sejali, a malo ste spravili pod streho; jeste, pa se ne nasitite, pijete, pa se ne napijete; oblačite se, a nihče se ne ogreje; in kdor prisluži plačilo, ga vrže v raztrgano mošnjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 7, 'Tako pravi Gospod nad vojskami: Pazite na svoja pota!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 8, 'Pojdite v gore in pripeljite lesa in zidajte hišo! To mi bode prijetno in se oslavim, pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 9, 'Po velikem ste gledali, in glej, malo je postalo; in če ste kaj prinesli domov, sem to razpihnil. Zakaj to? govori Gospod nad vojskami. Zavoljo hiše moje, ker je pusta, a vi hitite vsak za hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 10, 'Zato je nebo zadržalo roso nad vami in zemlja je zadržala svoj sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 11, 'In poklical sem sušo na deželo in na gore, na žito in vino in olje in na vse, kar rodi zemlja, in na ljudi in na živino in na vse delo rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 12, 'In poslušal je Zerubabel, sin Sealtielov, in Jozue, sin Jozadakov, veliki duhovnik, in ves ostanek ljudstva glas Gospoda, Boga svojega, in besede proroka Hagaja, kakor ga je bil poslal Gospod, njih Bog; in ljudstvo se je balo Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 13, 'Tedaj je rekel Hagaj, poslanec Gospodov, v poročilu Gospodovem ljudstvu: Jaz sem z vami, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 14, 'In Gospod je zbudil duha Zerubabelu, sinu Sealtielovemu, deželnemu oblastniku na Judovem, in duha Jozuetu, sinu Jozadakovemu, velikemu duhovniku, in duha vsemu ostanku ljudstva; in prišli so in se lotili dela pri hiši Gospoda nad vojskami, Boga svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 1, 15, 'štiriindvajseti dan šestega meseca, drugo leto kralja Darija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 1, 'Sedmi mesec, edenindvajseti dan meseca, je prišla beseda Gospodova po proroku Hagaju, in je rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 2, 'Govóri Zerubabelu, sinu Sealtielovemu, deželnemu oblastniku na Judovem, in Jozuetu, sinu Jozadakovemu, velikemu duhovniku, in ostanku ljudstva ter véli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 3, 'Kdo je med vami ostal, ki je videl to hišo v prvi slavi njeni? in kakšno jo vidite sedaj? Ni li prav kakor nič v očeh vaših?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 4, 'Sedaj pa bodi močan, o Zerubabel, govori Gospod, in bodi krepak, o Jozue, sin Jozadakov, veliki duhovnik! in bodi močno, vse ljudstvo dežele, govori Gospod, in delajte! Kajti jaz sem z vami, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 5, 'Beseda, ki sem se ž njo vam zavezal, ko ste šli iz Egipta, velja in duh moj ostane med vami; ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 6, 'Kajti tako pravi Gospod nad vojskami: Še enkrat, malo časa še, pa potresem nebo in zemljo in morje in suhoto;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 7, 'in potresem vse poganske narode, in pridejo dragocenosti vseh narodov, in to hišo napolnim s slavo, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 8, 'Moje je srebro in moje je zlato, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 9, 'Poslednja slava te hiše bode večja nego prva, pravi Gospod nad vojskami; in na tem kraju dam mir, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 10, 'Štiriindvajseti dan devetega meseca v drugem letu Darija je prišla beseda Gospodova proroku Hagaju in je rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 11, 'Tako pravi Gospod nad vojskami: Vprašaj vendar duhovnike glede postave in reci:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 12, 'Glej, če kdo nese sveto meso v krilu obleke svoje, pa se dotakne s krilom kruha ali kuhane jedi ali vina ali olja ali kake druge jestvine, postane li to sveto? In duhovniki so odgovorili in rekli: Ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 13, 'Še reče Hagaj: Če se kdo, ki se je ognusil z mrtvecem, dotakne vsega tega, bo li ognušeno? In duhovniki odgovore, rekoč: Ognušeno bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 14, 'Tedaj odgovori Hagaj in reče: Takšno je to ljudstvo in ves ta narod pred mojim obličjem, govori Gospod, in takšno je vse delo njih rok; in kar tam darujejo, je nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 15, 'In sedaj, pazite vendar na čas od tega dne in poprej, preden se je kamen na kamen pokladal v templju Gospodovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 16, 'Preden se je to godilo, ko je kdo prišel h kopi žita za dvajset mer, jih je bilo le deset; ko je prišel v tlačilnico, da zajame petdeset veder, jih je bilo le dvajset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 17, 'Udaril sem vas s snetjo in strupeno roso in s točo vse delo rok vaših; vendar vas ni bilo k meni, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 18, 'Pazite vendar na čas od tega dne in poprej, od štiriindvajsetega dne devetega meseca, namreč od dne, ko se je položila podstava templju Gospodovemu, pazite na to!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 19, 'Ni li seme še v žitnici? Tako tudi trta, smokva, margarana in oljka niso še obrodile; a od tega dne bom blagoslavljal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 20, 'In beseda Gospodova je prišla v drugič Hagaju, štiriindvajseti dan meseca, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 21, 'Govóri Zerubabelu, deželnemu oblastniku na Judovem, in reci: Jaz potresem nebo in zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 22, 'In prevržem prestole kraljestev in uničim moč kraljestvom poganov in prevrnem bojne vozove in nje, ki se na njih peljejo; in konji in njih jezdeci padejo, drug pod mečem drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (37, 2, 23, 'Tisti dan, govori Gospod nad vojskami, te vzamem, o Zerubabel, sin Sealtielov, služabnika svojega, govori Gospod, ter te naredim kakor za pečatni prstan; kajti tebe sem izvolil, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 1, 'Osmi mesec v drugem letu Darija je prišla beseda Gospodova Zahariju, sinu Berekija, sina Idovega, proroku, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 2, 'Gospod se je silno srdil nad očeti vašimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 3, 'Zato jim reci: Tako pravi Gospod nad vojskami: Izpreobrnite se k meni, govori Gospod nad vojskami, in obrnem se k vam, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 4, 'Ne bodite kakor očetje vaši, ki so jim glasili prejšnji proroki, govoreč: Tako veli Gospod nad vojskami: Izpreobrnite se vendar od hudobnih potov in od hudih dejanj svojih! ali niso poslušali in niso pazili name, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 5, 'Očetje vaši, kje so? in proroki, žive li vekomaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 6, 'Toda besede in postave moje, ki sem jih zapovedal hlapcem svojim prorokom, niso li zadele očetov vaših? In izpreobrnili so se in rekli: Kakor je Gospod nad vojskami namenil nam storiti, po naših potih in po naših dejanjih, tako nam je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 7, 'Štiriindvajseti dan enajstega meseca, ki je mesec Šebat, v drugem letu Darija, je prišla beseda Gospodova Zahariju, sinu Berekija, Idovega sina, proroku, in je rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 8, 'Videl sem po noči, in glej, mož je sedel na rdečem konju in stal med mirtami, ki so rasle v dolini, in za njim so bili konji rdeči, rjavi in beli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 9, 'In rečem: Gospod moj, kdo so ti? In angel, ki je govoril z menoj, mi reče: Pokažem ti, kdo so ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 10, 'In odgovori mož, ki je stal med mirtami, in reče: Ti so, ki jih je Gospod poslal, da prehodijo zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 11, 'In odgovore angelu Gospodovemu, ki je stal med mirtami, rekoč: Obhodili smo zemljo, in glej, vsa zemlja je tiha in počiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 12, 'Tedaj izpregovori angel Gospodov in reče: O Gospod nad vojskami, doklej se ne usmiliš Jeruzalema in mest Judovih, na katera si se srdil že sedemdeset let?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 13, 'In Gospod je odgovoril angelu, ki je z menoj govoril, dobre besede, tolažilne besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 14, 'Angel pa, ki je govoril z menoj, mi reče: Oglási in reci: Tako pravi Gospod nad vojskami: Vnet sem za Jeruzalem in za Sion z veliko gorečnostjo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 15, 'in z velikim srdom se srdim nad lahkoživnimi poganskimi narodi; kajti jezil sem se le malo, oni pa so nesrečo pospeševali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 16, 'Zato pravi tako Gospod: Obrnil sem se zopet k Jeruzalemu z mnogim usmiljenjem; hiša moja se bo zidala v njem, govori Gospod nad vojskami, in merska vrv bo raztegnjena čez Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 17, 'Dalje še oglási in reci: Tako pravi Gospod nad vojskami: Mesta moja bodo zopet imela obilost dobrot; in Gospod zopet potolaži Sion in zopet izvoli Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 18, 'In povzdignem oči in vidim, in glej: štirje rogovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 19, 'In rečem angelu, ki je govoril z menoj: Kaj so ti? In mi reče: To so rogovi, ki so razkropili Judo, Izraela in Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 20, 'Potem mi pokaže Gospod štiri kovače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 1, 21, 'In vprašam: Kaj so ti prišli delat? In mi reče: Oni so rogovi, ki so tako razkropili Judo, da ni nihče več vzdignil glave; ti pa so prišli, da one prestrašijo in da odbijejo rogove narodom, ki so povzdignili rog zoper deželo Judovo, da bi jo razmetali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 1, 'In povzdignem oči in vidim, in glej: mož z mersko vrvjo v roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 2, 'In rečem: Kam greš? In mi reče: Da zmerim Jeruzalem, da vidim, kolika je širjava njegova in kolika dolžina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 3, 'In glej, angel, ki je govoril z menoj, stopi ven, in drugi angel pride njemu naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 4, 'In mu reče: Teci, govóri temu mladeniču in véli: V Jeruzalemu bodo stanovali brez obzidja zavoljo množine ljudi in živine, ki bode v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 5, 'Jaz pa, govori Gospod, mu bodem ognjen zid kroginkrog in v slavo mu bodem sredi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 6, 'Oh, oh, bežite iz severne dežele! govori Gospod; kajti na četvere vetrove neba sem vas razkropil, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 7, 'Oh, Sion, béži, ki prebivaš pri babilonski hčeri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 8, 'Kajti tako pravi Gospod nad vojskami: Da prejmem slavo, me je poslal k poganskim narodom, ki so vas plenili; zakaj kdor se vas dotakne, se dotakne punčice očesa njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 9, 'Kajti, glej, jaz zavihtim roko nad njimi, in bodo v plen tistim, ki so jim sužnjevali; in spoznate, da me je poslal Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 10, 'Glasno poj in veséli se, hči sionska! zakaj jaz, glej, prihajam in bom prebival sredi tebe, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 11, 'In tisti dan se pridruži veliko poganskih narodov h Gospodu in bodo meni za ljudstvo; v tvoji sredi pa bom prebival, in spoznaš, da me je Gospod nad vojskami poslal k tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 12, 'In Gospod prejme v last Judo kot svoj delež v sveti zemlji in zopet si izvoli Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 2, 13, 'Naj molči vse meso pred Gospodom! kajti vstal je iz prebivališča svetosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 1, 'In mi pokaže velikega duhovnika Jozueta, stoječega pred angelom Gospodovim; in satan mu stoji ob desnici, da bi mu bil nasprotnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 2, 'In Gospod reče satanu: Pokara naj te Gospod, satan, da pokaraj te Gospod, ki je izvolil Jeruzalem! Ni li ta mož glavnja, potegnjena iz ognja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 3, 'In Jozue je bil oblečen v umazana oblačila in je stal pred angelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 4, 'In izpregovori angel in veli njim, ki so stali pred njim, rekoč: Vzemite umazana oblačila z njega! In njemu reče: Glej, snel sem s tebe krivice tvoje in oblečem te v praznična oblačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 5, 'In rečem: Naj mu denejo čisto pokrivalo na glavo! In so mu deli čisto pokrivalo na glavo ter ga oblekli v nova oblačila; in angel Gospodov je stal zraven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 6, 'In angel Gospodov izpriča Jozuetu in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 7, 'Tako pravi Gospod nad vojskami: Ako boš hodil po mojih potih in ako boš pridno stregel na straži moji, boš tudi sodil hišo mojo in tudi čuval veže moje, in dam ti prost vhod med temi, ki tu stoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 8, 'Poslušaj, o Jozue, veliki duhovnik, ti in tvoji tovariši, ki sede pred teboj – predpodobe so! Kajti glej, jaz storim, da pride hlapec moj Zemah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 9, 'Kajti glej, kamen, ki sem ga položil pred Jozueta, na tem enem kamenu je sedmero očes – glej, jaz izrežem na njem rezbo, govori Gospod, in odpravim krivico te dežele v enem dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 3, 10, 'Tisti dan, govori Gospod nad vojskami, boste vabili drug drugega pod vinsko trto in pod smokvo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 1, 'In angel, ki je govoril z menoj, se je vrnil in me je zbudil kakor človeka, ki se prebudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 2, 'In mi reče: Kaj vidiš? Rečem: Vidim, glej, svečnik ves iz zlata in oljenko njegovo vrhu njega in sedem svetilnic njegovih na njem in sedem cevi do svetilnic, ki so ob vrhu njegovem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 3, 'in dve oljki zraven njega, ena ob desni strani oljenke in druga ob levi plati njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 4, 'In izpregovorim in rečem angelu, ki je govoril z menoj: Kaj so ti, gospod moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 5, 'In angel, ki je govoril z menoj, odgovori in reče: Ne veš li, kaj so ti? In rečem: Ne, gospod moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 6, 'Tedaj odgovori in mi reče: To je beseda Gospodova Zerubabelu: Ne z vojsko, ne z močjo, ampak po mojem duhu, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 7, 'Kdo si ti, velika gora, pred Zerubabelom? v ravnino bodeš! In on prinese vrhnji kamen z glasnim vpitjem: Milost, milost njemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 8, 'Še mi je prišla beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 9, 'Roke Zerubabelove so položile temelj tej hiši in njegovega roke jo dodelajo; in spoznaš, da me je poslal k vam Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 10, 'Kajti kdo zaničuje dan malih začetkov? ko vendar z veseljem gledajo navpičnik v roki Zerubabelovi oni sedmeri: ki so oči Gospodove, ki letajo po vsej zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 11, 'In izpregovorim ter mu rečem: Kaj sta ti dve oljki ob desni strani svečnika in ob levi njegovi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 12, 'In izpregovorim v drugič in mu rečem: Kaj sta ti dve oljkovi mladici, ki sta poleg tistih dveh zlatih cevi, ki izlivata zlato olje iz sebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 13, 'In mi odgovori in reče: Ali ne veš, kaj sta? [4:14] In rečem: Ne, gospod moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 4, 14, '[4:15] Nato reče: To sta dva sinova olja, ki stojita pri Gospodarju vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 1, 'In zopet povzdignem oči in vidim, glej, zvit list leti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 2, 'In mi reče: Kaj vidiš? Rečem: Vidim zvit list, da leti; dvajset komolcev je dolg in deset komolcev širok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 3, 'In mi reče: To je prokletstvo, ki izhaja nad vso deželo; kdorkoli namreč krade, bo iztrebljen po tem, kar je na tej strani lista pisano; in kdorkoli prisega krivo, bo iztrebljen po tem, kar je pisano na oni strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 4, 'Po mojem povelju je izšlo, govori Gospod nad vojskami, in pride v hišo tatovo in v hišo njega, ki lažnivo prisega v mojem imenu, in se nastani v hiši njegovi ter jo pokonča z lesovjem in kamenjem njenim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 5, 'Angel pa, ki je govoril z menoj, stopi ven in mi reče: Povzdigni, prosim, oči in poglej: kaj je tisto, kar izhaja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 6, 'Jaz pa vprašam: Kaj je to? On reče: To je mernik, ki izhaja. In pridene: Tako jih je videti po vsej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 7, 'In glej, svinčena plošča se vzdigne in je videti ženo, sedečo v merniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 8, 'In reče: To je brezbožnost. In jo vrže v sredo mernika in spusti svinčeno ploščo na odprtino njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 9, 'In povzdignem oči in vidim, glej, dve ženi prideta, in veter je bil v njunih perutnicah, perutnice pa sta imeli kakor štorkljine perutnice, in vzdigneta mernik med zemljo in nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 10, 'In rečem angelu, ki je govoril z menoj: Kam neseta mernik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 5, 11, 'On mi pa reče: Da mu sezidajo hišo v deželi Sinearski; in ko bo pripravljena, ga tam postavijo na njegovo mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 1, 'In zopet povzdignem oči in vidim, glej, štirje vozovi pridejo izmed dveh gorá; in gori sta bili bronasti gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 2, 'Pri prvem vozu so bili rdeči konji, pri drugem vozu pa črni konji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 3, 'in pri tretjem beli konji, pri četrtem pa pisani, krepki konji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 4, 'Tedaj izpregovorim in rečem angelu, ki je govoril z menoj: Kaj so ti, gospod moj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 5, 'Angel odgovori in mi reče: Ti so četveri vetrovi pod nebom, ki izhajajo, ko so se bili postavili pred vse zemlje Gospodarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 6, 'Voz, pri katerem so črni konji, gre v severno deželo, in beli gredo za njimi, pisani pa gredo v južno deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 7, 'In krepki izhajajo in poskušajo iti, da bi predirjali zemljo. In veli: Pojdite, prehodite zemljo! In prehodili so zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 8, 'In me pokliče in govori z menoj, rekoč: Glej, tisti, ki so šli proti severni deželi, napravijo, da se duh moj upokoji v severni deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 9, 'In prišla mi je beseda Gospodova, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 10, 'Vzemi od njih, ki so bili v ujetništvu, od Heldaja in od Tobija in od Jedaja, pa pridi tisti dan in stopi v hišo Josija, Zefanijevega sinu, kamor so prišli iz Babela;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 11, 'vzemi torej od njih srebra in zlata in naredi vence in jih deni na glavo Jozuetu, sinu Jozadakovemu, velikemu duhovniku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 12, 'in mu govóri, rekoč: Tako pravi Gospod nad vojskami: Glej, mož, Odraslek mu je ime, vzraste s svojega kraja in zidal bo tempelj Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 13, 'In on sezida tempelj Gospodov in on bo nosil veličastvo ter sedel in gospodoval na prestolu svojem in bode duhovnik na prestolu svojem, in sklep miru bode med njima obema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 14, 'In venci bodo Helemu in Tobiju in Jedaju in Henu, sinu Zefanijevemu, za spomin v templju Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 6, 15, 'In kateri so daleč, pridejo in bodo zidali pri templju Gospodovem; in spoznate, da me je Gospod nad vojskami poslal k vam. In to se zgodi, ako boste radi poslušali glas Gospoda, Boga svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 1, 'Zgodi se pa v četrtem letu kralja Darija, da je prišla beseda Gospodova Zahariju, četrti dan devetega meseca, Kisleva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 2, 'Takrat so poslali iz Betela Sarezerja in Regemeleka ž njegovimi možmi, da prosijo blagovoljnosti Gospoda');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 3, 'in da govore duhovnikom hiše Gospoda nad vojskami in prorokom: Ali naj še jočem in se zdržujem v petem mesecu, kakor sem že delal veliko let?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 4, 'In prišla mi je beseda Gospoda nad vojskami, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 5, 'Reci vsemu ljudstvu dežele in duhovnikom takole: Ko ste se postili v petem in sedmem mesecu teh sedemdesetih let, ste li se postili meni in zavoljo mene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 6, 'Ko pa jeste in ko pijete, ne jeste li in ne pijete li zase?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 7, 'Ne veste li za besede, ki jih je Gospod oznanjal po prejšnjih prorokih, ko se je še prebivalo v Jeruzalemu, ko je vladal mir v njem in v mestih okoli njega, in se je prebivalo v južni pokrajini in v nižavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 8, 'In prišla je beseda Gospodova Zahariju, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 9, 'Tako pravi Gospod nad vojskami in veleva: Izvršujte sodbe po resnici ter izkazujte milost in usmiljenje drug drugemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 10, 'in ne zatirajte vdove in sirote, tujca in ubožca, in nihče naj ne izmišlja hudega v svojem srcu zoper svojega brata!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 11, 'Ali takrat niso hoteli poslušati in so uporno nastavili pleča in si zatisnili ušesa, da ne bi slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 12, 'In srce so si naredili kakor demant, da ne bi slišali postave in besed, ki jih je Gospod nad vojskami poslal po svojem duhu s prejšnjimi proroki; zato je prišla velika jeza od Gospoda nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 13, 'In zgodilo se je: kakor sem klical jaz, pa niso hoteli poslušati, tako so klicali oni, a nisem hotel slišati, pravi Gospod nad vojskami;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 7, 14, 'ali raznesel sem jih kakor z vetrom med vse narode, ki jih niso poznali; in zemlja je bila opustošena za njimi, da nihče ni hodil po njej; in izpremenili so deželo zaželjeno v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 1, 'In prišla mi je beseda Gospoda nad vojskami, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 2, 'Tako pravi Gospod nad vojskami: Vnet sem za Sion z veliko gorečnostjo in z velikim srdom gorim zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 3, 'Tako pravi Gospod: Vrnem se na Sion in sredi Jeruzalema bom prebival; in Jeruzalem se bo imenoval Mesto resnice in gora Gospoda nad vojskami Gora svetosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 4, 'Tako pravi Gospod nad vojskami: Še bodo posedali po ulicah v Jeruzalemu starčki in starke, vsak s palico v roki zavoljo visoke starosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 5, 'In mestne ulice bodo polne dečkov in deklic, ki se bodo igrali po ulicah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 6, 'Tako pravi Gospod nad vojskami: Ako se bo čudežno zdelo ostankom tega ljudstva v tistih dneh, bo li tudi čudežno v mojih očeh? govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 7, 'Tako pravi Gospod nad vojskami: Glej, jaz rešim ljudstvo svoje iz dežele proti solnčnemu vzhodu in iz dežele proti solnčnemu zahodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 8, 'in privedem jih sem, in bodo prebivali v Jeruzalemu; in bodo mi za ljudstvo in jaz jim bodem za Boga v resnici in pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 9, 'Tako pravi Gospod nad vojskami: Utrdite si roke, kateri slišite v teh dneh te besede iz ust prorokov, ki so bili ob času, ko se je položil temelj hiši Gospoda nad vojskami, templju, da bi se zgradil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 10, 'Kajti pred temi dnevi se ni izplačalo delo ljudem, ne živini; in ni bilo miru spričo zatiralca njemu, ki je odhajal in ki je prihajal, ker sem pustil vsem ljudem, da so se zaletavali drug v drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 11, 'Sedaj pa ne bodem proti ostanku tega ljudstva kakor v prejšnjih dneh, govori Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 12, 'Kajti požene setev miru: vinska trta obrodi svoj sad in zemlja donese letino svojo in nebo da roso svojo; in vse to izročim v dedno last ostanku tega ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 13, 'In zgodi se, kakor ste bili prokletstvo med poganskimi narodi, o hiša Judova in hiša Izraelova, tako vas rešim in bodete blagoslov. Ne bojte se, utrdite si roke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 14, 'Kajti tako pravi Gospod nad vojskami: Kakor sem mislil vam storiti hudo, ko so me dražili v jezo očetje vaši, pravi Gospod nad vojskami, in se nisem kesal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 15, 'tako zopet namerjam v teh dneh storiti dobro Jeruzalemu in hiši Judovi. Ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 16, 'To pa je, kar delajte: Govorite resnico vsak z bližnjim svojim; sodite po resnici in izrekajte razsodbo miru med vrati svojimi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 17, 'in nihče ne izmišljaj v srcu svojem hudega zoper soseda svojega in ne ljubite krive prisege, ker vse to sovražim, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 18, 'In prišla mi je beseda Gospoda nad vojskami, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 19, 'Tako pravi Gospod nad vojskami: Post četrtega in post petega in post sedmega in desetega meseca bode hiši Judovi v radost in veselje in v praznike vesele; samo ljubite resnico in mir!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 20, 'Tako pravi Gospod nad vojskami: Še se zgodi, da pridejo ljudstva in prebivalci mnogih mest;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 21, 'in prebivalci enega mesta pojdejo k drugemu in poreko: „Pojdimo hitro prosit blagovoljnosti Gospodove in iskat Gospoda nad vojskami!“„Tudi jaz pojdem!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 22, 'In pridejo mnoga ljudstva in mogočni poganski narodi, da bi iskali Gospoda nad vojskami v Jeruzalemu in prosili blagovoljnosti Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 8, 23, 'Tako pravi Gospod nad vojskami: Tiste dni zgrabi deset mož iz vseh jezikov poganskih narodov, zgrabijo, pravim, rob suknje judovskega moža in poreko: Z vami pojdemo, kajti slišali smo, da je Bog z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 1, 'Prorokovanje besede Gospodove o deželi Hadrakovi in o Damasku, njegovem počivališču, – ker oko Gospodovo gleda na vse človeštvo in na vse rodove Izraelove –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 2, 'in tudi o Hamatu, ki mejači ž njim, o Tiru in Sidonu, ker je silno moder.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 3, 'In Tir si je zgradil trdnjavo in nakopičil srebra kakor prahu in čistega zlata kakor blata po ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 4, 'Glej, Gospod mu vzame posest in uniči moč njegovo na morju, in njega požre ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 5, 'Askelon bo to videl in se bal, tudi Gaza ter bo silno trepetala, pa tudi Ekron, ker je osramočeno upanje njegovo; in kralj izgine iz Gaze in Askelon ne bo imel prebivalcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 6, 'In v Asdodu bo stanoval mešanec, in pokončam prevzetnost Filistejcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 7, 'In odpravim krvave jedi njegove iz ust njegovih in gnusobe njegove izmed njegovih zob; in tudi on, Filistejec, preostane za našega Boga in bode kakor vojvoda v Judi, in Ekron bode kakor Jebusejec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 8, 'Jaz pa se utaborim okoli hiše svoje zoper vojsko, da ne sme nihče iti mimo ali nazaj; in noben zatiralec ne pride več nadnje; kajti sedaj sem pogledal s svojimi očmi. –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 9, 'Močno se veséli, hči sionska, ukaj, hči jeruzalemska! Glej, kralj tvoj pride k tebi: pravičen je in rešitelj, pohleven in sedeč na oslu, in sicer na mladem osličinem žrebetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 10, 'In iztrebim bojne vozove Efraima in konje iz Jeruzalema, in bojni lok bo zlomljen. In mir ukaže narodom, in gospostvo njegovo bo segalo od morja do morja in od velereke do koncev zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 11, 'Tebi pa izpustim zavoljo krvi zaveze tvoje jetnike tvoje iz jame, v kateri ni vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 12, 'Obrnite se k trdnjavi, ki ste jetniki v upanju! Že danes oznanjam, da ti dvojno povrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 13, 'Kajti napel sem si Judo kakor lok in Efraima nanj položil kakor pšico; in tvoje sinove, o Sion, pobudim nad tvoje sinove, o Grška dežela, in te napravim kakor junakov meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 14, 'In Gospod se prikaže nad njimi, in njegova pšica šine kakor blisk; in Gospod Jehova zatrobi na trobento in pojde z južnimi viharji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 15, 'Gospod nad vojskami jim bode obrana, in jedli bodo in pogazili sovražnike kakor kamenje iz prače, in bodo pili, razgrajali kakor od vina, in polni bodo kakor daritvene čaše, kakor rogovi pri oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 16, 'In Gospod, njih Bog, jim da rešitev tisti dan kot čredi ljudstva svojega; kajti bodo kakor kameni v kroni, ki se leskečejo nad njegovo zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 9, 17, 'Kajti kolika bo njih dobrota in kolika njih lepota! Po žitu bodo uspevali mladeniči in po moštu device.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 1, 'Prosite Gospoda dežja ob času poznega deževja, Gospoda, ki dela bliskavice; in da vam obilo dežja, vsakemu zelenjavo na polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 2, 'Kajti hišni maliki so govorili prazne reči in vedeževalci so videli laži; in govore lažnive sanje, tolažijo brezuspešno. Zato so zbežali kakor čreda, potlačeni so, ker jim ni pastirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 3, 'Nad pastirji se je vnela jeza moja, in kozle bom kaznoval; kajti Gospod nad vojskami obišče čredo svojo, hišo Judovo, in jo enako stori svojemu krasnemu konju v bitki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 4, 'Iz Jude pride vogelni kamen, iz njega šatorov klin, iz njega bojni lok, iz njega vsi čiherni oblastniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 5, 'In bodo kakor junaki, ki v boju gazijo blato po cestah, in bojevali se bodo, ker Gospod je ž njimi, in v sramoto spravijo jezdece na konjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 6, 'In okrepim hišo Judovo in rešim hišo Jožefovo, in dam jim mirno prebivati; kajti njih sem se usmilil in bodo, kakor bi jih ne bil zavrgel. Zakaj jaz sem Jehova, njih Bog, in nje uslišim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 7, 'In Efraim bode kakor junak, in njih srce se bo veselilo kakor od vina; in njih otroci se bodo, videč to, radovali; njih srce se bo veselilo v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 8, 'Zažvižgam jim in jih zberem, ker sem jih odrešil; in razmnože se, kakor so se prej razmnožili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 9, 'In sejal jih bom med ljudstva, a v daljavi se bodo mene spominjali; in bodo živeli z otroki svojimi in se povrnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 10, 'Pripeljem jih nazaj tudi iz Egipta in jih zberem iz Asirije in jih privedem v deželo Gileadsko in na Libanon, in jim ne bo dosti prostora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 11, 'In pojde skozi morje stiske in udari morske valove, in posuše se vse globočine Nila; in potlačena bo prevzetnost Asirije in žezlo Egipta se umakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 10, 12, 'In okrepim jih v Gospodu, da bodo hodili v njegovem imenu, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 1, 'Odpri vrata svoja, o Libanon, da požre ogenj tvoje cedre!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 2, 'Tuli, o jelka, ker je padla cedra, ker so mogočni opustošeni! Tulite, hrastje v Basanu, ker je neprodirni gozd posekan!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 3, 'Glasno tulijo pastirji, ker je njih veličastvo opustošeno; glasi se rjovenje mladih levov, ker pokončana je ošabnost Jordanova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 4, 'Tako je rekel Gospod, Bog moj: Pasi ovce, ki so namenjene v zakol,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 5, 'katerih gospodarji jih moré, pa si ne štejejo v greh; kateri jih pa prodajajo, govore: Hvaljen bodi Gospod, kajti obogatim! in njih pastirji jim ne prizanašajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 6, 'Kajti ne bom več prizanašal prebivalcem dežele, govori Gospod; temuč glej, jaz izročim ljudi, vsakega v pest bližnjemu njegovemu in kralju njegovemu v pest; in razbijejo deželo, in iz njih pesti jih ne otmem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 7, 'In pasel sem ovce namenjene v zakol, torej najmedlejše izmed črede; in vzel sem si dve palici, eno sem imenoval Ljubeznivost, drugo pa Združenje, in pasel sem ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 8, 'In odpravil sem tri pastirje v enem mesecu. A duša moja se je vznevoljila zaradi njih, pa tudi njih duši sem se zgnusil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 9, 'Tedaj sem rekel: Ne bom vas pasel več; kar umira, naj umre, in kar gine, naj pogine, ostali pa naj žro sleherni svojega bližnjega meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 10, 'In vzel sem palico svojo, Ljubeznivost, in jo zlomil, da bi raztrgal zavezo svojo, ki sem jo bil sklenil z vsemi ljudstvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 11, 'In bila je raztrgana tisti dan; in tako so spoznali najmedlejši iz črede, ki so pazile name, da je bila beseda Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 12, 'In sem jim dejal: Če se vam dobro zdi, dajte mi plačilo moje, če pa ne, pustite. Tedaj so odtehtali meni v plačilo trideset srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 13, 'Nato mi veli Gospod: Vrzi jih lončarju, tisto lepo ceno, s katero so me cenili. In vzel sem trideset srebrnikov in jih vrgel v hišo Gospodovo, lončarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 14, 'Nato sem zlomil drugo palico svojo, Združenje, da razdružim bratovščino med Judo in Izraelom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 15, 'Potem mi veli Gospod: Vzemi si še neumnega pastirja pripravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 16, 'Kajti glej, jaz obudim pastirja v deželi, ki ne bo skrbel za tiste, ki ginejo, ne bo iskal razkropljenih, ne bo zdravil ranjenih, tudi zdravega ne bo redil, temuč bo jedel meso pitanih in trgal njih parklje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 11, 17, 'Gorje ničvrednemu pastirju, ki zapušča čredo! Meč pridi nad njegovo ramo in nad desno oko njegovo! Rama njegova usahne docela in desno oko mu oslepi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 1, 'Prorokovanje besede Gospodove o Izraelu. Tako govori Gospod, ki razprostira nebo in ustanavlja zemljo in človeku ustvarja duha v prsih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 2, 'Glej, jaz naredim Jeruzalem za omotično čašo vsem ljudstvom okoli; in tudi Judo zadene to pri obleganju Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 3, 'In zgodi se tisti dan, da storim Jeruzalem za pretežek kamen vsem ljudstvom: vsi, ki ga vzdigujejo, se bodo hudo poškodovali. In vsi narodi zemlje se zbero zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 4, 'Tisti dan, govori Gospod, udarim vse konje, da se bodo plašili, in njih jezdece, da zbesné; a nad hišo Judovo bom imel odprte oči, vse konje narodov pa udarim s slepoto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 5, 'In vojvode Judovi bodo v srcu svojem govorili: Moja moč so prebivalci jeruzalemski po Gospodu nad vojskami, njih Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 6, 'Tisti dan storim vojvode Judove enake goreči peči med lesom in goreči plamenici med snopjem, da požro ob desni in ob levi vsa ljudstva okoli; in Jeruzalemci bodo zopet stanovali na svojem mestu v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 7, 'In Gospod reši najprej šatore Judove, da se krasota hiše Davidove in krasota prebivalcev jeruzalemskih ne poveličuje proti Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 8, 'Tisti dan bode Gospod obrana prebivalcem v Jeruzalemu; in kdor se opoteka med njimi, bode tisti dan kakor David, in hiša Davidova bode kakor Bog, kakor angel Gospodov pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 9, 'In zgodi se tisti dan, da si prizadenem pogubiti vse poganske narode, ki gredo zoper Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 10, 'In izlijem nad hišo Davidovo in nad prebivalce jeruzalemske duha milosti in ponižnih prošenj, in gledali bodo v mene, ki so ga prebodli, in plakali nad njim, kakor plačejo po edincu, in bridko bodo nad njim žalovali, kakor žalujejo bridko nad prvencem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 11, 'Tisti dan bode velik jok v Jeruzalemu kakor jok ob Hadadrimonu v dolini Megidski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 12, 'In plakala bo dežela, vsaka rodovina posebe: rodovina hiše Davidove posebe in njih žene posebe; rodovina hiše Natanove posebe in njih žene posebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 13, 'rodovina hiše Levijeve posebe in njih žene posebe; rodovina Simejskih posebe in njih žene posebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 12, 14, 'takisto vse rodovine, ki preostanejo, vsaka rodovina posebe in njih žene posebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 1, 'Tisti dan bo studenec odprt hiši Davidovi in prebivalcem v Jeruzalemu v očiščenje greha in nečistosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 2, 'In zgodi se tisti dan, govori Gospod nad vojskami, da iztrebim imena malikov iz dežele, in ne bodo se jih več spominjali; pa tudi proroke in duha nečistote odpravim iz dežele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 3, 'In zgodi se, če bo kdo še prorokoval, da mu porečeta oče njegov in mati njegova, ki sta ga rodila: Ne smeš živeti, kajti laž si govoril v imenu Gospodovem! in oče njegov in mati njegova, ki sta ga rodila, ga prebodeta, ko prorokuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 4, 'In zgodi se tisti dan, da se bodo sramovali proroki, vsak za prikazen svojo, ob svojem prorokovanju; tudi se ne bodo ogrinjali z raševnatim plaščem, da bi varali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 5, 'temuč vsak poreče: Nisem prorok, kmetovalec sem; kajti v last si me je kupil človek od mladosti moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 6, 'In če ga kdo vpraša: Kake so te rane na tvojih prsih? tedaj poreče: S temi sem bil ranjen v hiši tistih, ki me ljubijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 7, 'Prebúdi se, o meč, zoper pastirja mojega in zoper moža, ki je moj družnik! govori Gospod nad vojskami; udari pastirja, in čreda se razkropi. A milo obrnem roko svojo do malih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 8, 'In zgodi se po vsej deželi, govori Gospod, da se dva dela v njej iztrebita in premineta; ali tretji del ostane v njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 13, 9, 'In tisti tretji del popeljem skozi ogenj in jih prečistim, kakor se prečiščuje srebro, ter jih preizkusim, kakor se preizkuša zlato. Ti bodo klicali ime moje, in jaz jim odgovorim; porečem: Ta je ljudstvo moje, oni pa reko: Jehova je Bog moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 1, 'Glej, prihaja dan za Gospoda, ko se plen tvoj razdeli sredi tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 2, 'In zberem vse poganske narode v Jeruzalem na boj; in vzamejo mesto, in po hišah bodo plenili in žene oskrunjali; in polovica mesta pojde v ujetništvo, a ostanek ljudstva ne bo iztrebljen iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 3, 'In Gospod pride in se bo vojskoval zoper one pogane, kakor se je vojskoval ob dnevi boja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 4, 'In noge njegove bodo tisti dan stale na Oljski gori, ki je nasproti Jeruzalemu ob vzhodu; in Oljska gora se razkolje po sredi proti vzhodu in proti zahodu, in naredi se jako velika dolina, in polovica gore se umakne proti severu in polovica proti jugu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 5, 'In bežali boste v dolino mojih gorá, kajti dolina med gorami bo segala do Azela; in bežali boste, kakor ste bežali pred potresom v dneh Uzija, kralja Judovega. Tedaj pride Gospod, Bog moj, in vsi sveti ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 6, 'In zgodi se tisti dan, da ne bode luči, sijajne zvezde se strdijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 7, 'In bode en edin dan (Gospodu je znan), ne dan, ne noč; in zgodi se, da bode ob času večera svetloba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 8, 'In zgodi se tisti dan, da poteko žive vode iz Jeruzalema, njih polovica proti vzhodnemu morju in polovica proti zahodnemu morju: po leti in po zimi bodo tekle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 9, 'In Gospod bode kralj nad vso zemljo; tisti dan bode Gospod eden in ime njegovo eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 10, 'In vsa dežela od Gebe do Rimona, ki je južno od Jeruzalema, se izpremeni in bode kakor nižava Araba; in Jeruzalem bo povišan in bodo v njem prebivali na njegovem prejšnjem kraju, od vrat Benjaminovih tja do mesta prvih vrat in do Vogelnih vrat in od stolpa Hananela tja do tlačilnic kraljevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 11, 'In bodo v njem prebivali, in nobenega prokletstva ne bode več, in v Jeruzalemu bo prebivanje na varnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 12, 'To pa bode nadloga, s katero bo Gospod tepel vsa ljudstva, ki so se bojevala z Jeruzalemom: Gnilo jim bo meso vsakemu, ko bo še na nogah stal, in oči mu segnijejo v votlinah in jezik mu strohni v ustih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 13, 'In tisti dan nastane med njimi velika zmešnjava od Gospoda, da zgrabi vsak bližnjega svojega roko in vsak vzdigne roko zoper roko bližnjega svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 14, 'Pa tudi Juda se bo bojeval ob Jeruzalemu; in bogastvo vseh poganskih narodov okoli se skopiči, zlata, srebra in oblačil silno veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 15, 'In prav taka, enaka tej nadlogi, bode nadloga konj, mezgov, velblodov, oslov in vse živine, ki bode v onih vojnih taborih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 16, 'In zgodi se, da bodo vsi, ki preostanejo od vseh narodov, kateri so prišli zoper Jeruzalem, hodili vsako leto, da molijo Kralja, Gospoda nad vojskami, in da praznujejo praznik šatorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 17, 'Ako pa katera iz rodovin zemlje ne pride gori v Jeruzalem molit Kralja, Gospoda nad vojskami: nad to ne pride nič dežja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 18, 'In če egiptovska rodovina ne bo hotela hoditi gori, ali ne pride nadnjo tista nadloga, s katero Gospod udari poganske narode, ki ne bodo hodili gori praznovat praznika šatorov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 19, 'To bode kazen Egiptu in vsem narodom, ki ne bodo hodili gori praznovat praznika šatorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 20, 'Tisti dan bo na konjskih zvoncih zapisano: Sveto Gospodu. In lonci v hiši Gospodovi bodo kakor daritvene čaše pred oltarjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (38, 14, 21, 'in vsak lonec v Jeruzalemu in na Judovem bode svet Gospodu nad vojskami; in prihajali bodo vsi darovalci in jemali iz njih in kuhali v njih. In nobenega Kanaanca ne bode več v hiši Gospoda nad vojskami tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 1, 'Prorokovanje besede Gospodove za Izraela po Malahiju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 2, 'Ljubil sem vas, pravi Gospod. Vi pa pravite: V čem si nas ljubil? Ni li bil Ezav brat Jakobov? govori Gospod; a ljubil sem Jakoba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 3, 'Ezava pa sem sovražil ter sem naredil njegove gore v puščavo in dal njegovo dediščino šakalom v pustinji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 4, 'Ako pravi Edom: Razdrti smo, pa zopet zgradimo, kar je podrtega – pravi tako Gospod nad vojskami: Oni bodo zidali, jaz pa bom podiral; in imenovali se bodo „kraji brezbožnosti“in „ljudstvo, nad katerim se Bog srdi vekomaj“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 5, 'In vaše oči bodo to videle in porečete: Velik je Gospod tudi preko Izraelove meje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 6, 'Sin spoštuje očeta in hlapec gospodarja. Ako sem torej oče, kje je moja čast? in ako sem Gospod, kje je moj strah? pravi Gospod nad vojskami vam, o duhovniki, ki zaničujete moje ime. Vendar še govorite: V čem smo zaničevali tvoje ime?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 7, 'Oskrunjen kruh darujete na oltarju mojem. Vendar govorite: S čim smo te oskrunili? S tem, da pravite: Miza Gospodova se sme prezirati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 8, 'In ko prinašate v daritev slepo živinče, ni nič hudega; in ko prinašate hromo in bolno, tudi ni nič hudega. Prinesi pa to deželnemu oblastniku svojemu! mu li bodeš ugoden? ali se ozre nate? pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 9, 'In sedaj, velim, prosite blagovoljnosti Boga mogočnega, da nam bode milosten! se li, ker je to vaša roka storila, milo ozre na koga izmed vas? pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 10, 'Da bi bil med vami le eden, ki bi zaprl vrata, da ne netite ognja na oltarju mojem brezkoristno! Niste mi nič ugodni, pravi Gospod nad vojskami, in darila ne sprejmem milo iz roke vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 11, 'Kajti od solnčnega vzhoda do zahoda bode moje ime veliko med poganskimi narodi; in na vsakem mestu se bo darovalo kadilo mojemu imenu in čisto darilo; zakaj moje ime bode veliko med poganskimi narodi, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 12, 'A vi ga oskrunjate s tem, da govorite: Miza Gospodova je onečiščena, in jed, ki se dobi ž nje, se sme prezirati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 13, 'In pravite: Glej, koliko truda pri njej! in jo zaničujete, pravi Gospod nad vojskami, ter prinašate, kar ste siloma vzeli, in hromo in bolno, in tako prinašate darilo. Ali naj to milo sprejmem iz roke vaše? pravi Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 1, 14, 'Proklet pa bodi, kdor ravna zvijačno, ko ima samca v čredi, pa stori obljubo in potem daruje Gospodu kaj pokvarjenega! Kajti velik kralj sem jaz, pravi Gospod nad vojskami, in moje ime je strašno med pogani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 1, 'In zdaj, o duhovniki, vam velja ta zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 2, 'Ako nočete poslušati in ako ne boste imeli te skrbi v srcu, da bi dali čast mojemu imenu, pravi Gospod nad vojskami, pošljem prokletstvo med vas in prekolnem blagoslove vaše; saj sem jih že preklel, ker vas to ne skrbi v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 3, 'Glejte, jaz vam pokaram setev in namečem vam gnoja v obraz, gnoja vaših praznikov, in odneso vas ž njim vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 4, 'In spoznate, da sem vam poslal to zapoved, da bi bila zaveza moja z Levijem, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 5, 'Zaveza moja je bila ž njim v življenje in mir, in dal sem mu jo za strah, in bal se je mene in trepetal spričo mojega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 6, 'Postava resnice je bila v ustih njegovih in krivica se mu ni našla v ustih; v miru in poštenosti je hodil z menoj in mnoge je preobrnil od krivičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 7, 'Kajti duhovnikove ustne morajo ohraniti spoznanje in iz njegovih ust naj prejemajo pouk o postavi, zakaj on je poslanec Gospoda nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 8, 'A vi ste odstopili s pota, zakrivili ste, da so se mnogi spoteknili ob postavo; pokvarili ste zavezo Levijevo, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 9, 'Zato sem tudi jaz vas izdal v preziranje in poniževanje vsemu ljudstvu, tako kakor se niste držali potov mojih in ste se ozirali po osebi v rabi postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 10, 'Nimamo li vsi enega očeta? ni li nas ustvaril eden Bog? Zakaj ravnamo nezvesto vsak z bratom svojim, oskrunjajoč s tem očetov svojih zavezo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 11, 'Juda je nezvesto ravnal, in gnusoba se je počenjala v Izraelu in v Jeruzalemu; kajti Juda je oskrunil svetišče Gospodovo, ki Mu je drago, in se zaročil s hčerjo inostranskega boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 12, 'Gospod iztrebi moža, ki to dela, iz šatorov Jakobovih, njega, ki čuje, in njega, ki odgovarja, in njega, ki prinaša darilo Gospodu nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 13, 'In vdrugič delate to: pokrivate oltar Gospodov s solzami, z jokom in zdihovanjem, tako da se nič več ne ozre na darilo, tudi ne sprejme iz roke vaše, kar mu nosite v blagougodje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 14, 'Pa pravite: Zakaj? Zato ker je bil Gospod priča med teboj in ženo mladosti tvoje, proti kateri si nezvesto ravnal, ko je vendar druža tvoja in žena zaveze tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 15, 'Ali ju ni Edini ustvaril? in njegov je bil ostanek duha. In kaj je hotel Edini? Iskal je semena Božjega. Zato pazite na duha svojega in nihče ne ravnaj nezvesto proti ženi mladosti svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 16, 'Kajti sovražim razporoko, pravi Gospod, Bog Izraelov, in njega, ki pokriva obleko svojo s silovitostjo, pravi Gospod nad vojskami. Zato pazite na duha svojega, da ne ravnate nezvesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 2, 17, 'Utrudili ste Gospoda s svojimi besedami. Pa pravite: S čim smo ga utrudili? S tem, da govorite: Kdorkoli dela hudo, je dober v očeh Gospodovih, in taki mu ugajajo; sicer – kje je Bog sodbe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 1, 'Glej, jaz pošiljam poslanca svojega, da pripravi pot pred menoj. In naglo pride v svoj tempelj Gospod, ki ga iščete, in Angel zaveze, ki ga želite: glej, prihaja, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 2, 'Kdo pa more prenesti dan prihoda njegovega in kdo obstoji, kadar se on prikaže? Kajti on bode kakor ogenj topilca in kakor lug belilca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 3, 'In sedel bo kakor topilec, ko čisti srebro, in čistil bo sinove Levijeve in jih prečistil kakor zlato in srebro, da bodo prinašali Gospodu daritve v pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 4, 'Tedaj bode darilo Judovo in jeruzalemsko prijetno Gospodu kakor v dneh starodavnih in kakor v nekdanjih letih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 5, 'In približam se vam s sodbo in bodem nagla priča zoper čarovnike in prešeštnike in krivoprisežnike in zoper nje, ki trgajo najemniku plačilo in silo delajo vdovi in siroti ter kratijo pravico tujcu, mene se pa ne boje, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 6, 'Kajti jaz, Jehova, se ne izpreminjam, zato vi, sinovi Jakobovi, ne boste pokončani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 7, 'Od dni očetov svojih ste odstopali od mojih postav in jih niste izpolnjevali. Vrnite se k meni, in obrnem se k vam, pravi Gospod nad vojskami. Pa pravite: V čem naj se vrnemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 8, 'Ali sme človek ukanjati Boga, da me ukanjate? Pa pravite: V čem smo te ukanili? V desetinah in v povzdigovalnih darilih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 9, 'S prokletstvom ste prokleti, dokler me ukanjate, vsi iz tega naroda!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 10, 'Prinesite vso desetino v žitnice, da bode živeža v hiši moji; in izkusite me vendar v tem, pravi Gospod nad vojskami, če vam ne odprem zatvornic na nebu ter vam izlijem blagoslov do preobilice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 11, 'In pokaram zavoljo vas požrešnika, da vam sadu zemlje več ne pokvari, tudi trta na polju vam ne bode nerodovitna, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 12, 'In vsi narodi vas bodo blagrovali; kajti dežela bodete blagougodja, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 13, 'Trde so bile besede vaše zoper mene, pravi Gospod. Pa pravite: Kaj smo med seboj govorili zoper tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 14, 'Govorili ste: Brezkoristno je služiti Bogu, in kakšen dobiček, da smo stregli na straži njegovi in da smo v žalni obleki hodili pred Gospodom nad vojskami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 15, 'Sedaj torej blagrujemo prevzetneže: ne samo napredujejo, kateri delajo brezbožno, ampak še izkušajo Boga in – so oteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 16, 'Tedaj so se pogovarjali, kateri se boje Gospoda, drug z drugim, in Gospod je pazil in poslušal; in spominska knjiga je bila pisana pred njim za tiste, ki se Gospoda boje, in za nje, ki čislajo ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 17, 'In bodo meni dne, ki ga napravim, pravi Gospod nad vojskami, v dragotino, in jim prizanesem, kakor mož prizanese sinu svojemu, ki mu služi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 3, 18, 'Tedaj se obrnete in boste videli razloček med pravičnim in brezbožnim, med njim, ki služi Bogu, in njim, ki mu ne služi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 1, 'Kajti glej, dan prihaja, ki gori kakor peč, in vsi prevzetniki in vsi, ki delajo brezbožno, bodo strnišče; in dan, ki prihaja, jih sežge, pravi Gospod nad vojskami, da jim ne ostavi ne korenine, ne mladike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 2, 'Vam pa, ki se bojite imena mojega, vzide solnce pravičnosti in ozdravljenje bo pod njegovimi perutmi, in izhajali boste in skakali kakor pitana teleta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 3, 'in pogazite brezbožnike, kajti kakor pepel bodo pod vašimi stopali v dan, ki ga jaz napravim, pravi Gospod nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 4, 'Spominjajte se zakona Mojzesa, hlapca mojega, ki sem mu ga zapovedal na Horebu, postave in sodbe za vsega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 5, 'Glej, jaz vam pošljem Elija proroka, preden pride dan Gospodov, veliki in strašni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (39, 4, 6, 'In on obrne srce očetov k otrokom in srce otrok k njih očetom, da ne pridem in ne udarim dežele s prokletjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 1, 'Knjiga rodu Jezusa Kristusa, sina Davidovega, sina Abrahamovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 2, 'Abraham je rodil Izaka. Izak pa je rodil Jakoba. Jakob pa je rodil Judo in brate njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 3, 'Juda pa je rodil Faresa in Zara s Tamaro. Fares pa je rodil Ezroma. Ezrom pa je rodil Arama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 4, 'Aram pa je rodil Abinadaba. Abinadab pa je rodil Nahsona. Nahson pa je rodil Salmona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 5, 'Salmon pa je rodil Boaza z Rahabo. Boaz pa je rodil Obeda z Ruto. Obed pa je rodil Jeseja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 6, 'A Jesej je rodil Davida kralja. David kralj pa je rodil Salomona z bivšo ženo Urijevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 7, 'Salomon pa je rodil Roboama. Roboam pa je rodil Abija. Abija pa je rodil Aza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 8, 'Aza pa je rodil Jozafata. Jozafat pa je rodil Jorama. Joram pa je rodil Ozija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 9, 'Ozija pa je rodil Joatama. Joatam pa je rodil Ahaza. Ahaz pa je rodil Ezekija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 10, 'Ezekija pa je rodil Manaseja. Manasej pa je rodil Amona. Amon pa je rodil Josija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 11, 'A Josija je rodil Jehonija in brate njegove ob selitvi v Babilon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 12, 'Po preselitvi v Babilon pa: Jehonija je rodil Salatiela. Salatiel pa je rodil Zorobabela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 13, 'Zorobabel pa je rodil Abiuda. Abiud pa je rodil Eliakima. Eliakim pa je rodil Azorja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 14, 'Azor pa je rodil Sadoka. Sadok pa je rodil Ahima. Ahim pa je rodil Eliuda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 15, 'Eliud pa je rodil Eleazarja. Eleazar pa je rodil Matana. Matan pa je rodil Jakoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 16, 'A Jakob je rodil Jožefa, moža Marije, iz katere se je rodil Jezus, ki se imenuje Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 17, 'Vseh rodov torej od Abrahama do Davida je štirinajst rodov, in od Davida do preselitve v Babilon štirinajst rodov, in od preselitve v Babilon do Kristusa štirinajst rodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 18, 'Jezusa Kristusa rojstvo je bilo pa tako: Ko je bila mati njegova Marija zaročena z Jožefom, se pokaže, preden sta se sešla, da je noseča od svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 19, 'Jožef pa, njen mož, ker je bil pravičen in je ni hotel očitno osramotiti, jo je sklenil skrivaj zapustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 20, 'In ko je to premišljeval, glej, prikaže se mu v spanju angel Gospodov, rekoč: Jožef, sin Davidov, ne boj se vzeti k sebi Marije, žene svoje; kajti kar se je v njej zarodilo, je od svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 21, 'Rodila pa bo sina, in imenuj ime njegovo Jezus, zakaj on odreši ljudstvo svoje njih grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 22, 'Vse to pa se je zgodilo, da se izpolni, karje rekel Gospod po preroku, ki pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 23, '„Glej, devica bode noseča in bo rodila sina, in imenovali bodo ime njegovo Emanuel“, kar se tolmači: Bog z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 24, 'Ko se pa prebudi Jožef iz spanja, stori, kakor mu je angel Gospodov ukazal, in vzame k sebi ženo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 1, 25, 'In ni je spoznal, dokler ni rodila sina, in dal mu je ime Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 1, 'Ko se je pa Jezus rodil v Betlehemu Judejskem, v dneh Heroda kralja, glej, pridejo modrijani z Jutrovega v Jeruzalem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 2, 'govoreč: Kje je kralj Judov, ki se je narodil? Kajti videli smo zvezdo njegovo na Jutrovem, pa smo prišli, da se mu poklonimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 3, 'Ko pa to zasliši kralj Herod, se prestraši in ves Jeruzalem ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 4, 'In zbere vse višje duhovnike in pismarje ljudstva ter jih izprašuje, kje se ima Kristus roditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 5, 'Oni mu pa reko: V Betlehemu na Judejskem, kajti tako je pisano po proroku:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 6, '„In ti Betlehem, zemlja Judova, nikakor nisi najmanjši med knezi Judovimi, kajti iz tebe pride vojvoda, ki bo pasel ljudstvo moje, Izraela“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 7, 'Tedaj pokliče Herod skrivaj modrijane in poizve od njih natanko, kdaj se je zvezda prikazala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 8, 'In pošlje jih v Betlehem, rekoč: Pojdite in skrbno vprašujte po detetu, a ko ga najdete, sporočite mi, da tudi jaz pridem in se mu poklonim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 9, 'Oni pa, ko so slišali kralja, odidejo. In glej, zvezda, ki so jo bili videli na Jutrovem, gre pred njimi, dokler ne pride in se ne ustavi nad mestom, kjer je bilo dete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 10, 'Ko pa ugledajo zvezdo, se razvesele s silno velikim veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 11, 'In pridejo v hišo in vidijo dete z Marijo, materjo njegovo, in padejo na tla ter se mu poklonijo, in odpro zaklade svoje ter mu darujejo darove: zlato in kadilo in miro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 12, 'In ker jih Bog v spanju opomni, naj se ne vračajo k Herodu, odidejo po drugi poti v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 13, 'Ko so pa oni odpotovali, glej, prikaže se angel Gospodov Jožefu v spanju, rekoč: Vstani in vzemi dete in mater njegovo, pa beži v Egipt in ostani tam, dokler ti ne povem, kajti Herod bo iskal deteta, da bi ga pogubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 14, 'On pa vstane in vzame dete in mater njegovo po noči in pobegne v Egipt,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 15, 'in ostane tam do Herodove smrti, da se izpolni, kar je rekel Gospod po proroku, ki pravi: „Iz Egipta sem poklical sina svojega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 16, 'Tedaj se Herod, videč, da so ga modrijani prekanili, zelo raztogoti ter pošlje in pomori po Betlehemu in po vsej okolici njegovi vse dečke, stare po dve leti in manj, po času, ki ga je natanko poizvedel od modrijanov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 17, 'Tedaj se je izpolnilo, kar je rekel prorok Jeremija, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 18, '„Glas se je slišal v Rami, jok in velik krik, Rahel je plakala za svojimi otroki in ni se dala utolažiti, ker jih ni“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 19, 'Ko je pa Herod umrl, glej, prikaže se v spanju angel Gospodov Jožefu v Egiptu, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 20, 'Vstani in vzemi dete in mater njegovo in pojdi v zemljo izraelsko, kajti pomrli so, ki so detetu stregli po življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 21, 'On pa vstane in vzame dete in mater njegovo in pride v zemljo izraelsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 22, 'Ko pa sliši, da kraljuje v Judeji Arhelaj namesto Heroda, očeta svojega, se zboji tja iti; ko ga pa Bog v spanju opomni, krene v kraje galilejske;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 2, 23, 'in prišedši tja, se nastani v mestu, ki se imenuje Nazaret, da se izpolni, kar je rečeno po prorokih: „Nazarečan se bo imenoval“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 1, 'V tistih dneh pa pride Janez Krstnik in v puščavi Judejski propoveduje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 2, 'govoreč: Izpokorite se! kajti približalo se je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 3, 'On je namreč tisti, o katerem je povedal prorok Izaija, ki pravi: „Glas vpijočega v puščavi: Pripravite pot Gospodu, poravnajte steze njegove!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 4, 'On pa, Janez, je imel obleko svojo iz velblodje dlake in usnjen pas okoli ledja svojega, a živež njegov je bil: kobilice in divji med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 5, 'Tedaj je prihajal k njemu ves Jeruzalem in vsa Judeja in vsa okolica jordanska,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 6, 'in on jih je krščeval v Jordanu, izpovedujoče grehe svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 7, 'Ko pa vidi mnogo farizejev in saducejev, da gredo h krstu njegovemu, jim reče: Gadja zalega! kdo vas je poučil, da ubežite prihodnji jezi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 8, 'Rodite torej sad, vreden izpokorjenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 9, 'in ne domišljajte si, da bi govorili v sebi: Abrahama imamo za očeta; zakaj pravim vam, da more Bog iz tega kamenja obuditi Abrahamu sinove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 10, 'Nastavljena je pa že tudi sekira drevju pri korenini: vsako drevo torej, ki ne rodi dobrega sadu, se poseka in vrže v ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 11, 'Jaz vas krščujem z vodo za izpokorjenje, a ta, ki gre za menoj, je močnejši od mene, kateremu nisem vreden obuvala nositi: on vas bo krstil s svetim Duhom in ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 12, 'On ima velnico v roki svoji in očedi gumno svoje in pospravi pšenico svojo v žitnico, a pleve sežge z neugasljivim ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 13, 'Tedaj pride Jezus iz Galileje k Janezu na Jordan, da ga on krsti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 14, 'Janez pa mu je branil, rekoč: Meni je treba, da me ti krstiš, pa hodiš ti k meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 15, 'Jezus pa odgovori in mu reče: Pusti sedaj, kajti tako se nama spodobi, izpolniti vso pravičnost. Tedaj mu privoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 16, 'In Jezus, ko je bil krščen, stopi precej iz vode, in glej, nebesa se mu odpro in Duha Božjega vidi, da gre navzdol kakor golob in prihaja nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 3, 17, 'In glej, glas iz nebes govori: Ta je Sin moj ljubljeni, ki je po moji volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 1, 'Tedaj odpelje Duh Jezusa v puščavo, da ga izkuša hudič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 2, 'In ko se je postil štirideset dni in štirideset noči, postane potem lačen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 3, 'Pa pristopi k njemu izkušnjavec in reče: Če si Sin Božji, reci, naj postane to kamenje kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 4, 'On pa odgovori in reče: Pisano je: „Ne bo živel človek ob samem kruhu, temuč od vsake besede, ki izhaja iz ust Božjih“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 5, 'Tedaj ga vzame hudič v sveto mesto in ga postavi na vrh templja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 6, 'in mu reče: Če si Sin Božji, spusti se doli, kajti pisano je: „Angelom svojim bo zapovedal zate, in na rokah te bodo nosili, da se kje z nogo ne udariš ob kamen“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 7, 'Reče mu Jezus: Zopet je pisano: „Ne izkušaj Gospoda, Boga svojega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 8, 'Zopet ga vzame hudič na zelo visoko goro in mu pokaže vsa kraljestva sveta in njih slavo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 9, 'in mu reče: Vse to ti dam, če padeš predme in me moliš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 10, 'Tedaj mu reče Jezus: Poberi se, satan! kajti pisano je: „Moli Gospoda, Boga svojega, in njemu samemu služi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 11, 'Tedaj ga hudič pusti; in glej, angeli pristopijo ter mu strežejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 12, 'Ko pa zasliši Jezus, da je Janez ujet, se umakne v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 13, 'In zapustivši Nazaret, pride in se nastani v Kafarnavmu pri morju, v pokrajinah Zabulona in Neftalima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 14, 'da se izpolni, kar je rečeno po proroku Izaiju, ki pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 15, '„Zemlja Zabulonova in zemlja Neftalimova, na poti k morju, za Jordanom, poganska Galileja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 16, 'narod, ki je sedel v temi, je videl veliko svetlobo, in ki so sedeli v deželi in senci smrti, jim je zasvetila luč“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 17, 'Odslej je jel Jezus propovedovati in praviti: Izpokorite se! kajti približalo se je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 18, 'Hodeč pa ob morju Galilejskem, ugleda Jezus dva brata: Simona, ki se imenuje Peter, in Andreja, brata njegovega, da mečeta mreže v morje; bila sta namreč ribiča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 19, 'In jima reče: Pojdita za menoj, in naredil bom, da bosta lovca ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 20, 'Ona pa precej popustita mreže in gresta za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 21, 'In gredoč odtod dalje, ugleda druga dva brata: Jakoba, sina Zebedejevega, in Janeza, brata njegovega, v ladji z Zebedejem, nju očetom, da popravljata mreže svoje, in ju pokliče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 22, 'Ona pa precej popustita ladjo in očeta svojega in gresta za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 23, 'In Jezus je hodil okoli po vsej Galileji, učeč po njih shodnicah in oznanjujoč evangelij kraljestva in ozdravljajoč vsako bolezen in vsako slabost med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 24, 'In glas o njem se razširi po vsej Siriji, in prineso mu vse bolnike z različnimi boleznimi in mukami, in obsedence in mesečne in mrtvoudne, in jih ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 4, 25, 'In spremljale so ga velike množice iz Galileje in iz Deseteromestja in iz Jeruzalema in iz Judeje in z one strani Jordana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 1, 'Ko pa vidi množice, stopi na goro, in ko sede, pristopijo k njemu učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 2, 'In odpre usta svoja ter jih uči, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 3, 'Blagor ubogim v duhu, ker njih je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 4, 'Blagor jim, ki žalujejo, ker oni bodo potolaženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 5, 'Blagor krotkim, ker oni bodo podedovali zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 6, 'Blagor lačnim in žejnim pravičnosti, ker oni bodo nasičeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 7, 'Blagor usmiljenim, ker oni bodo usmiljenje dosegli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 8, 'Blagor jim, ki so čistega srca, ker oni bodo Boga videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 9, 'Blagor miroljubnim, ker oni se bodo sinovi Božji imenovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 10, 'Blagor preganjanim zaradi pravičnosti, ker njih je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 11, 'Blagor vam, kadar vas zaradi mene sramoté in preganjajo in vse hudo zoper vas govoré, pa lažejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 12, 'Radujte se in veselite, ker veliko je plačilo vaše v nebesih. Kajti tako so preganjali proroke, ki so bili pred vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 13, 'Vi ste sol zemlje. Če se pa sol izpridi, s čim se bo osolila? Za nič več ni, nego da se vrže ven in jo ljudje poteptajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 14, 'Vi ste luč svetu. Mesto, ki stoji vrhu gore, se ne more skriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 15, 'Tudi ne prižigajo sveče in je ne devljejo pod mernik, ampak na svečnik: in sveti vsem, ki so v hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 16, 'Tako naj sveti vaša luč pred ljudmi, da vidijo vaša dobra dela in slavé Očeta vašega, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 17, 'Ne mislite, da sem prišel razveljavljat postavo ali proroke: nisem prišel, da razveljavim, ampak da izpolnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 18, 'Kajti resnično vam pravim: Dokler ne prejdeta nebo in zemlja, ne izgine ni najmanjša črka ali pičica iz postave, dokler se vse ne zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 19, 'Kdorkoli torej popači eno najmanjših teh zapovedi in ljudi tako nauči, se bo imenoval najmanjši v nebeškem kraljestvu; kdor koli jih pa izpolnjuje in uči, ta se bo velik imenoval v nebeškem kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 20, 'Kajti pravim vam, da nikakor ne pridete v nebeško kraljestvo, če ne bo pravičnost vaša večja nego pismarjev in farizejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 21, 'Slišali ste, da je rečeno starim: „Ne ubijaj; kdor pa ubije, zapade sodbi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 22, 'A jaz vam pravim, da vsak, kdor se brez razloga jezi na brata svojega, zapade sodbi; kdorkoli pa reče bratu svojemu: Raka! pride pred veliki zbor; a kdorkoli reče: Bedak! zapade peklenskemu ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 23, 'Če torej prineseš dar svoj k oltarju in se tam spomniš, da ima brat tvoj kaj zoper tebe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 24, 'pusti dar svoj tam pred oltarjem, pa pojdi, spravi se poprej z bratom svojim in potem pridi in daruj dar svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 25, 'Sprijazni se z nasprotnikom svojim hitro, dokler si ž njim na potu, da te nasprotnik ne izroči sodniku in sodnik hlapcu, in boš vržen v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 26, 'Resnično ti pravim: Gotovo ne prideš iz nje, dokler ne plačaš zadnjega vinarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 27, 'Slišali ste, da je rečeno starim: „Ne prešeštvuj“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 28, 'A jaz vam pravim, da vsak, kdor pogleda ženo, da si je poželi, je že prešeštvoval ž njo v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 29, 'Če te pa desno tvoje oko pohujšuje, izderi ga in vrzi od sebe; kajti bolje ti je, da pogine eden udov tvojih, nego da bo vse telo tvoje vrženo v pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 30, 'In če te desna tvoja roka pohujšuje, odsekaj jo in vrzi od sebe; kajti bolje ti je, da pogine eden udov tvojih, nego da bi vse telo tvoje prišlo v pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 31, 'Rečeno je tudi: „Kdorkoli se loči od žene svoje, naj ji da ločilni list“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 32, 'A jaz vam pravim: Kdorkoli pusti ženo svojo, razen če jo zaradi prešeštvovanja, jo zapeljuje v prešeštvovanje; in kdorkoli puščeno vzame, prešeštvuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 33, 'Zopet ste slišali, da je rečeno starim: „Ne prisegaj po krivem, izpolni pa Gospodu prisege svoje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 34, 'A jaz vam pravim, da ne prisegajte nikakor, ne pri nebu, ker je prestol Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 35, 'ne pri zemlji, ker je podnožje nogam njegovim, ne pri Jeruzalemu, ker je mesto velikega Kralja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 36, 'tudi pri glavi svoji ne prisegaj, ker ne moreš ne enega lasu narediti belega ali črnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 37, 'Govorjenje vaše pa bodi: Da, da; ne, ne; kar je pa več od tega, to je od hudega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 38, 'Slišali ste, da je rečeno starim: „Oko za oko, zob za zob“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 39, 'A jaz vam pravim, da se ne upirajte hudemu, temuč če te kdo udari po desnem licu, nastavi mu tudi drugo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 40, 'in kdor se hoče s teboj pravdati in ti suknjo vzeti, pusti mu tudi plašč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 41, 'in če te kdo sili miljo daleč, pojdi ž njim dve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 42, 'Kdor te prosi, daj mu; in kdor hoče od tebe napósodo, ne odreci mu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 43, 'Slišali ste, da je rečeno: „Ljubi bližnjega svojega“in sovraži sovražnika svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 44, 'A jaz vam pravim: Ljubite sovražnike svoje in molite za tiste, ki vas preganjajo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 45, 'da bodete sinovi Očeta svojega, ki je v nebesih, kajti on veleva solncu svojemu, da vzhaja nad hudobnimi in dobrimi, in daje dež pravičnim in nepravičnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 46, 'Kajti če ljubite tiste, ki ljubijo vas, kakšno plačilo vam bode? Ne delajo li tega tudi cestninarji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 47, 'In če pozdravljate samo brate svoje, kaj delate posebnega? Ne delajo li tudi pogani tako?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 5, 48, 'Vi torej bodite popolni, kakor je popoln Oče vaš nebeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 1, 'Pazite, da ne boste izkazovali pravičnosti svoje pred ljudmi, da bi vas oni videli, sicer nimate plačila pri Očetu svojem, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 2, 'Kadar torej daješ miloščino, ne trobi pred seboj, kakor delajo hinavci po shodnicah in po ulicah, da jih hvalijo ljudje. Resnično vam pravim: Prejeli so plačilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 3, 'Ti pa kadar daješ miloščino, naj ne ve levica tvoja, kaj dela desnica tvoja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 4, 'da bode miloščina tvoja na skrivnem, in Oče tvoj, ki vidi na skrivnem, ti povrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 5, 'In kadar molite, ne bodite kakor hinavci, kajti oni radi po shodnicah in uličnih voglih stoječ molijo, da se kažejo ljudem. Resnično vam pravim: Prejeli so plačilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 6, 'Ti pa, kadar moliš, pojdi v izbo svojo in zapri duri svoje ter moli k Očetu svojemu, ki je na skrivnem, in Oče tvoj, ki vidi na skrivnem, ti povrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 7, 'Kadar pa molite, ne govorite mnogo kakor pogani, kajti oni mislijo, da bodo uslišani zaradi obilih besed svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 8, 'Ne delajte se torej njim enakih: kajti Oče vaš ve, česa vam je treba, preden ga vi prosite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 9, 'Vi torej molite takole: Oče naš, ki si v nebesih, posvečeno bodi ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 10, 'Pridi kraljestvo tvoje. Zgodi se volja tvoja kakor v nebesih tako na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 11, 'Kruh naš vsakdanji daj nam danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 12, 'In odpusti nam dolge naše, kakor tudi mi odpuščamo dolžnikom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 13, 'In ne vpelji nas v izkušnjavo, temuč reši nas zlega. Ker tvoje je kraljestvo in moč in slava na vekomaj. Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 14, 'Kajti če odpustite ljudem njih pregreške, odpusti tudi vam Oče vaš nebeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 15, 'Če pa ne odpustite ljudem njih pregreškov, tudi Oče vaš ne odpusti vaših pregreh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 16, 'Kadar se pa postite, ne delajte se žalostnih kakor hinavci; pačijo namreč obraze svoje, da pokažejo ljudem, da se postijo. Resnično vam pravim: Prejeli so plačilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 17, 'Ti pa si, kadar se postiš, pomazili glavo in umij obraz:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 18, 'da te ne bodo videli ljudje, da se postiš, temuč Oče tvoj, ki je na skrivnem; in Oče tvoj, ki vidi na skrivnem, ti povrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 19, 'Ne nabirajte si zakladov na zemlji, kjer molj in rja razjedata in kjer tatovi podkopavajo in kradejo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 20, 'temuč nabirajte si zakladov v nebesih, kjer ne molj, ne rja ne razjedata in kjer tatovi ne podkopavajo in ne kradejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 21, 'Kajti kjer je zaklad tvoj, tam bode tudi srce tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 22, 'Svetilo telesu je oko. Če je torej oko tvoje zdravo, bo svetlo vse telo tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 23, 'Če je pa oko tvoje pokvarjeno, bo temno vse telo tvoje. Če je torej luč, ki je v tebi, tema, kolika je ta tema!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 24, 'Nihče ne more dvema gospodoma služiti; ker ali bo enega mrzil in drugega ljubil, ali bo enemu vdan in bo drugega zaničeval. Ne morete Bogu služiti in mamonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 25, 'Zato vam pravim: Ne skrbite za življenje svoje, kaj boste jedli in kaj boste pili, tudi ne za telo svoje, kaj boste oblekli. Mar ni življenje več nego hrana in telo več nego obleka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 26, 'Poglejte ptice pod nebom: ne sejejo in ne žanjejo in tudi ne spravljajo v žitnice, in Oče vaš nebeški jih živi. Mar niste vi veliko več od njih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 27, 'Kdo izmed vas pa more s svojo skrbjo postavi svoji primakniti en komolec?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 28, 'In za obleko čemu skrbite? Poglejte lilije na polju, kako rastejo: ne trudijo se in ne predejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 29, 'pravim vam pa, da se tudi Salomon v vsej slavi svoji ni oblekel kakor teh ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 30, 'Če pa travo na polju, ki danes stoji in jo jutri vržejo v peč, Bog tako oblači, mar ne bo mnogo bolj vas, maloverni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 31, 'Ne skrbite torej in ne govorite: Kaj bomo jedli? ali kaj bomo pili? ali kaj bomo oblekli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 32, 'Kajti vsega tega iščejo pogani. Saj Oče vaš nebeški ve, da vsega tega potrebujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 33, 'Ampak iščite najprej kraljestva Božjega in njegove pravičnosti, in vse to vam bo pridano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 6, 34, 'Ne skrbite torej za jutri; kajti jutrišnji dan bo skrbel sam zase. Dosti ima vsak dan svojega zla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 1, 'Ne sodite, da ne boste sojeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 2, 'Kajti s kakršno sodbo sodite, s tako bodo sodili vas; in s kakršno mero merite, s tako se bo merilo vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 3, 'Kaj pa vidiš pazder v očesu brata svojega, bruna v očesu svojem pa ne čutiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 4, 'Ali kako porečeš bratu svojemu: Daj, da izderem pazder iz očesa tvojega, in glej, bruno je v očesu tvojem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 5, 'Hinavec, izderi najprej bruno iz očesa svojega in potem izpregledaš, da izdereš pazder iz očesa bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 6, 'Ne dajajte svetega psom in ne mečite biserov svojih pred svinje, da jih ne poteptajo z nogami svojimi in se ne obrnejo ter vas raztrgajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 7, 'Prosite, in dalo se vam bo; iščite, in našli boste; trkajte, in odprlo se vam bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 8, 'Kajti vsak, kdor prosi, prejme; in kdor išče najde; in kdor trka, se mu odpre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 9, 'Ali kdo izmed vas je človek, ki bi dal kamen sinu svojemu, če ga prosi kruha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 10, 'ali če prosi ribe, bi mu dal kačo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 11, 'Če torej vi, ki ste hudobni, znate dobre darove dajati otrokom svojim, koliko več dá Oče vaš, ki je v nebesih, dobrega tistim, ki ga prosijo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 12, 'Vse torej, kar hočete, da ljudje vam storé, tako storite tudi vi njim; zakaj to je postava in proroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 13, 'Pojdite noter skozi tesna vrata: ker prostorna so vrata in široka je pot, ki vodi v pogubljenje, in mnogo jih je, ki po njej hodijo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 14, 'toda tesna so vrata in ozka je pot, ki vodi v življenje, in malo jih je, ki jo najdejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 15, 'Varujte se lažnivih prorokov, ki prihajajo k vam v ovčjih oblačilih, znotraj so pa grabljivi volkovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 16, 'Po njih sadovih jih spoznate. Se li bere s trnja grozdje ali z osata smokve?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 17, 'Tako rodi vsako dobro drevo dober sad, slabo drevo pa rodi slab sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 18, 'Dobro drevo ne more roditi slabega sadu, in slabo drevo ne more roditi dobrega sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 19, 'Vsako drevo, ki ne rodi dobrega sadu, se poseka in vrže na ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 20, 'Torej po njih sadovih jih spoznate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 21, 'Ne pride vsak, kdor mi pravi: Gospod, Gospod, v nebeško kraljestvo, ampak kdor izpolnjuje voljo Očeta mojega, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 22, 'Veliko mi jih poreče tisti dan: Gospod, Gospod, ali nismo prorokovali v tvojem imenu, in hudičev izganjali s tvojim imenom, in mnogo čudežev delali s tvojim imenom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 23, 'In tedaj jim povem očitno: Nikoli vas nisem poznal; poberite se od mene, ki delate krivico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 24, 'Vsak torej, kdor sliši te besede moje in jih izpolnjuje, bo podoben modremu možu, ki je sezidal hišo svojo na skalo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 25, 'in usula se je ploha in pridrle so reke in zapihali so vetrovi in se zagnali v tisto hišo, a ni padla, kajti postavljena je bila na skalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 26, 'In vsak, kdor sliši te moje besede in ne dela po njih, je podoben neumnemu možu, ki je sezidal hišo svojo na pesek;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 27, 'in ulila se je ploha in pridrle so reke in zapihali so vetrovi in udarili ob tisto hišo, in padla je, in njen pad je bil grozen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 28, 'In zgodi se, ko konča Jezus te besede, da se množice silno čudijo nauku njegovemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 7, 29, 'zakaj učil jih je, kakor kdor ima oblast, a ne kakor njih pismarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 1, 'In ko je stopil z gore, so šle za njim velike množice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 2, 'In glej, gobavec pride ter se mu poklanja in reče: Gospod, če hočeš, me moreš očistiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 3, 'In Jezus iztegne roko ter se ga dotakne, rekoč: Hočem, bodi očiščen! In takoj je bil očiščen svojih gob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 4, 'In reče mu Jezus: Glej, da nikomur ne poveš, temuč pojdi, pokaži se duhovniku in opravi daritev, ki jo je ukazal Mojzes, njim v pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 5, 'Ko pa pride v Kafarnavm, pristopi k njemu stotnik, ga zaprosi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 6, 'in reče: Gospod, hlapec moj leži doma mrtvouden in se grozno muči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 7, 'Jezus mu reče: Pridem in ga ozdravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 8, 'In stotnik odgovori in reče: Gospod, nisem vreden, da prideš pod streho mojo, ampak reci le besedo, in hlapec moj ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 9, 'Kajti tudi jaz sem človek pod oblastjo in imam vojake pod seboj, pa velim temu: Pojdi! in gre, in drugemu: Pridi! in pride, in hlapcu svojemu: Stori to! in stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 10, 'Ko pa Jezus to sliši, se začudi in reče tistim, ki so šli za njim: Resnično vam pravim, pri nikomer v Izraelu nisem našel tolike vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 11, 'Pravim vam pa, da jih pride mnogo od vzhoda in zahoda, in sedeli bodo z Abrahamom in Izakom in Jakobom v nebeškem kraljestvu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 12, 'a sinovi kraljestva bodo vrženi v zunanjo temo: tam bo jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 13, 'In Jezus veli stotniku: Pojdi, in kakor si veroval, naj se ti zgodi. In hlapec njegov je ozdravel tisto uro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 14, 'In ko pride Jezus na Petrov dom, vidi taščo njegovo, da leži in jo trese mrzlica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 15, 'In dotakne se njene roke, in mrzlica jo pusti; in je vstala ter mu je stregla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 16, 'Ko se je pa zvečerilo, mu prineso mnogo obsedencev; in izžene duhove z besedo in ozdravi vse bolnike;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 17, 'da se izpolni, kar je rečeno po proroku Izaiju, ki pravi: „On je nase vzel slabosti naše in nosil bolezni naše.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 18, 'Ko pa vidi Jezus mnogo ljudstva okoli sebe, ukaže iti na drugo stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 19, 'Pa pristopi k njemu neki pismar in mu reče: Učenik, hočem za tabo hoditi, kamorkoli pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 20, 'In reče mu Jezus: Lisice imajo brloge in ptice pod nebom gnezda, a Sin človekov nima, kamor bi naslonil glavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 21, 'A nekdo drugi učencev njegovih mu reče: Gospod, dovoli mi najprej, da grem in pokopljem očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 22, 'Jezus mu pa reče: Pojdi za menoj in pusti, naj mrtvi pokopavajo mrliče svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 23, 'In ko vstopi v ladjo, vstopijo za njim učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 24, 'In glej, velik vihar nastane na morju, tolik, da zagrinjajo valovi ladjo: on pa je spal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 25, 'In pristopijo učenci ter ga zbudé, govoreč: Gospod, otmi nas, pogibljemo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 26, 'In jim reče: Kaj ste boječi, maloverni? Tedaj vstane, zapretí vetrovom in morju, in velika tihota nastane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 27, 'Ljudje se pa začudijo in reko: Kdo neki je ta, da so mu tudi vetrovi in morje pokorni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 28, 'In ko pride na drugo stran, v pokrajino Gadarenov, ga srečata dva obsedenca, ki sta prišla iz grobov, in sta bila silno divja, da ni mogel nihče mimo iti po tisti poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 29, 'In glej, zakričita in rečeta: Kaj imaš z nami, Jezus, Sin Božji? Si li sem prišel, da bi nas pred časom mučil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 30, 'In daleč od njiju se je pasla velika čreda svinj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 31, 'Zli duhovi pa ga prosijo, govoreč: Če nas izganjaš, pošlji nas v čredo svinj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 32, 'In jim veli: Pojdite! In oni zapusté obsedenca in odidejo v čredo svinj; in glej, vsa čreda se zakadi z brega v morje in potonejo v vodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 33, 'Pastirji pa zbežé in prišedši v mesto, naznanijo vse, tudi to o obsedencih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 8, 34, 'In glej, vse mesto pride Jezusu naproti, in ko ga ugledajo, zaprosijo, naj odide iz njih krajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 1, 'In stopi v ladjo ter se prepelje in pride v svoje mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 2, 'In glej, prineso mu mrtvoudnega, ki je ležal na postelji. In ko vidi Jezus njih vero, reče mrtvoudnemu: Zaupaj, sin, odpuščeni so grehi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 3, 'In glej, nekateri pismarji reko v sebi: Ta preklinja Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 4, 'In ko vidi Jezus njih misli, reče: Zakaj mislite hudobno v srcih svojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 5, 'Kaj je namreč laže, reči: Odpuščeni so ti grehi, ali reči: Vstani in hodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 6, 'Da boste pa vedeli, da ima Sin človekov oblast, odpuščati na zemlji grehe (nato veli mrtvoudnemu): Vstani in vzemi svojo posteljo in pojdi na svoj dom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 7, 'In vstane ter odide na svoj dom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 8, 'Ko pa množice to vidijo, se prestrašijo in hvalijo Boga, ki je dal ljudem tako oblast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 9, 'In gredé dalje odtod, ugleda človeka, ki sedi na mitnici, Matevža po imenu, in mu reče: Pojdi za menoj! In vstane ter odide za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 10, 'In zgodi se, ko sedi v hiši za mizo, in glej, mnogo cestninarjev in grešnikov pride, in sedé z Jezusom in učenci njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 11, 'In ko farizeji to vidijo, reko njegovim učencem: Zakaj jé učenik vaš z mitarji in grešniki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 12, 'Jezus pa to sliši in reče: Zdravi ne potrebujejo zdravnika, ampak bolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 13, 'Pojdite pa in učite se, kaj se pravi: „Usmiljenja hočem in ne daritve“. Nisem namreč prišel klicat pravičnih, temuč grešnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 14, 'Potem pristopijo k njemu Janezovi učenci, govoreč: Zakaj se mi in farizeji tolikokrat postimo, tvoji učenci pa se ne postijo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 15, 'In reče jim Jezus: Se li morejo svatje žalostiti, dokler je ženin ž njimi? Pridejo pa dnevi, ko se jim odvzame ženin, in tedaj se bodo postili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 16, 'Nihče pa ne prišiva zaplate iz novega sukna na staro obleko, kajti taka zaplata odtrga od obleke še kaj, in luknja bode večja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 17, 'Tudi ne vlivajo novega vina v stare mehove, sicer mehovi popokajo in vino se razlije in mehovi se pokončajo; temuč novo vino vlivajo v nove mehove, in oboje se ohrani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 18, 'Ko jim je to še govoril, glej, pride neki načelnik ter se mu poklanja, govoreč: Hči moja je ravnokar umrla; ali pridi in položi nanjo roko svojo, in oživela bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 19, 'In Jezus vstane in gre za njim in učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 20, 'In glej, žena, ki je imela krvotok dvanajst let, pririne odzadaj in se dotakne roba obleke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 21, 'Kajti dejala je sama pri sebi: Če se obleke njegove le dotaknem, ozdravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 22, 'Jezus se pa obrne in jo ugleda ter reče: Zaupaj, hči, tvoja vera te je rešila. In žena je bila zdrava od te ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 23, 'In ko pride Jezus v načelnikovo hišo, ugleda piskače in hrumeče ljudstvo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 24, 'in jim reče: Odstopite! kajti deklica ni umrla, temuč spi. A oni se mu posmehujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 25, 'Ko pa izžene ljudstvo, gre noter in jo prime za roko: in deklica vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 26, 'In glas o tem se raznese po vsej tisti deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 27, 'In ko gre Jezus dalje odtod, prideta za njim dva slepca in vpijeta, rekoč: Usmili se naju, sin Davidov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 28, 'Ko pa dospe v hišo, pristopita slepca k njemu; in Jezus jima reče: Verujeta li, da morem to storiti? Rečeta mu: Da, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 29, 'Tedaj se dotakne njunih oči, rekoč: Po vajini veri se vama zgódi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 30, 'In njune oči se odpro. In Jezus jima zapreti in veli: Glejta, da nihče ne zve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 31, 'Ona pa izideta in ga razglasita po vsej tisti deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 32, 'Ko pa ta dva odideta, glej, pripeljejo mu mutastega obsedenca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 33, 'In ko izžene zlega duha, mutec izpregovori. In množica se začudi in reče: Nikoli se ni videlo kaj takega v Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 34, 'Farizeji pa reko: S poglavarjem hudičev izganja zle duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 35, 'In hodil je Jezus po vseh mestih in vaseh, učeč po njih shodnicah in oznanjujoč evangelij kraljestva in ozdravljajoč vsako bolezen in vsako slabost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 36, 'Ko pa vidi množice, se mu zasmilijo; kajti bili so izmučeni in razkropljeni kakor ovce, ki nimajo pastirja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 37, 'Tedaj reče učencem svojim: Žetve je sicer mnogo, ali delavcev malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 9, 38, 'Prosite torej Gospodarja žetve, naj pošlje delavcev na žetev svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 1, 'In pokliče svojih dvanajst učencev in jim podeli oblast nad nečistimi duhovi, da jih izganjajo, in da ozdravljajo vsako bolezen in vsako slabost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 2, 'Dvanajsterih apostolov imena so pa ta: Prvi Simon, ki se imenuje Peter, in Andrej, njegov brat; Jakob, sin Zebedejev, in Janez, njegov brat;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 3, 'Filip in Bartolomej; Tomaž in Matevž, cestninar; Jakob, sin Alfejev, in Tadej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 4, 'Simon Kananejec in Juda Iškariot, ki ga je tudi izdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 5, 'Teh dvanajst pošlje Jezus in jim naroči, govoreč: Ne hodite na pot poganov in ne pojdite v mesto Samarijanov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 6, 'marveč pojdite k izgubljenim ovcam Izraelove hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 7, 'Hodeč pa oznanjujte in pravite: Približalo se je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 8, 'Bolnike ozdravljajte, mrtve obujajte, gobavce očiščajte, zle duhove izganjajte. Brezplačno ste prejeli, brezplačno dajajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 9, 'Ne jemljite zlata, ne srebra, ne denarja v pasu svojem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 10, 'ne torbe na pot, ne dveh plaščev, ne obuvala, ne palice: kajti delavec je vreden svoje hrane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 11, 'V katerokoli mesto ali vas pa pridete, poizvedite, kdo v njej je vreden; in pri tem ostanite, dokler ne pojdete naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 12, 'Ko pa pridete v hišo, pozdravite jo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 13, 'In če je hiša vredna, naj pride vaš mir nanjo; če pa ni vredna, naj se vrne vaš mir k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 14, 'In če vas kdo ne sprejme in tudi ne posluša besed vaših, odidite iz tiste hiše ali tistega mesta in otresite prah z nog svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 15, 'Resnično vam pravim: Laže bo Sodomski in Gomorski zemlji v dan sodbe nego tistemu mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 16, 'Glejte, jaz vas pošiljam kakor ovce med volkove: bodite torej previdni kakor kače in preprosti kakor golobje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 17, 'Varujte se pa ljudi, zakaj izročali vas bodo sodiščem in po shodnicah svojih vas bodo bičali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 18, 'Popeljejo vas pa tudi pred vladarje in kralje zaradi mene, njim in narodom v pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 19, 'Kadar vas pa izročé oblasti, ne skrbite, kako in kaj bi govorili, kajti dano vam bo tisto uro, kaj naj govorite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 20, 'Niste namreč vi, ki govorite, ampak Duh Očeta vašega je, ki govori v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 21, 'Izdajal bo pa brat brata v smrt, in oče sina, in otroci bodo vstali zoper roditelje in jih bodo morili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 22, 'In sovražili vas bodo vsi zaradi mojega imena; kdor pa pretrpi do konca, ta bo zveličan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 23, 'Kadar vas pa preganjajo v tem mestu, bežite v drugo. Kajti resnično vam pravim: Ne boste prehodili mest Izraelovih dotlej, ko pride Sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 24, 'Ni ga učenca nad učitelja, tudi ne hlapca nad gospodarja njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 25, 'Dovolj je učencu, da postane kakor njegov učitelj, in hlapec kakor njegov gospodar. Če so pa hišnega gospodarja imenovali Belzebula, koliko bolj bodo domače njegove?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 26, 'Ne bojte se jih torej; kajti nič ni prikritega, kar se ne bo odkrilo, in skrivnega, kar se ne bo zvedelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 27, 'Kar vam pravim v temi, povejte na svetlem, in kar slišite na uho, razglasite s streh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 28, 'In ne bojte se tistih, ki ubijajo telo, duše pa ne morejo ubiti; bojte se marveč tistega, ki more i dušo i telo pogubiti v pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 29, 'Mar ne prodajajo dveh vrabcev za vinar? pa ne eden od njiju ne pade na tla brez Očeta vašega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 30, 'Vam so pa tudi lasje na glavi vsi sešteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 31, 'Ne bojte se torej; vi ste boljši od mnogo vrabcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 32, 'Vsakega torej, kdor pripozna mene pred ljudmi, pripoznam tudi jaz njega pred Očetom svojim, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 33, 'Kdorkoli pa me zataji pred ljudmi, zatajim tudi jaz njega pred Očetom svojim, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 34, 'Ne mislite, da sem prišel, da prinesem mir na zemljo; nisem prišel, da prinesem mir, ampak meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 35, 'Prišel sem namreč, da ločim človeka od njegovega očeta in hčer od matere njene in nevesto od tašče njene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 36, 'in sovražniki človeku bodo domači njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 37, 'Kdor ljubi očeta ali mater bolj nego mene, ni mene vreden, in kdor ljubi sina ali hčer bolj nego mene, ni mene vreden;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 38, 'in kdor ne vzame nase križa svojega in ne gre za menoj, ni mene vreden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 39, 'Kdor najde življenje svoje, ga izgubi, in kdor izgubi življenje svoje zaradi mene, ga najde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 40, 'Kdor sprejme vas, sprejme mene, in kdor sprejme mene, sprejme tistega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 41, 'Kdor sprejme proroka v ime proroka, prejme plačilo proroka; in kdor sprejme pravičnega v ime pravičnega, prejme plačilo pravičnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 10, 42, 'In če kdo napoji enega od teh malih samo s kupico studenčnice v ime učenca, resnično vam pravim, ne izgubi plačila svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 1, 'In zgodi se, ko neha Jezus naročati dvanajsterim učencem svojim, odide odtod, da uči in propoveduje v njih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 2, 'Janez pa v ječi zasliši Kristusova dela in pošlje dva svojih učencev');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 3, 'ter mu sporoči: Si li ti tisti, ki ima priti, ali naj čakamo drugega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 4, 'In Jezus odgovori in jima veli: Pojdita in sporočita Janezu, kar slišita in vidita:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 5, 'Slepci izpregledujejo in hromi hodijo, gobavci se očiščajo in gluhi slišijo, mrtvi vstajajo in ubogim se oznanja evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 6, 'In blagor mu, kdor se nad menoj ne pohujša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 7, 'In ko odideta, začne Jezus govoriti množici o Janezu: Kaj ste šli v puščavo gledat? Trst, ki ga veter maje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 8, 'Ali kaj ste šli, da vidite? Človeka, oblečenega v mehka oblačila? Glejte, kateri nosijo mehka oblačila, so po kraljevih dvorih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 9, 'Ali zakaj ste šli tja? Da vidite proroka? Da, pravim vam, in več nego proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 10, 'Ta je, o katerem je pisano: „Glej, jaz pošiljam angela svojega pred obličjem tvojim, ki pripravi tvojo pot pred teboj“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 11, 'Resnično vam pravim: Ni vstal izmed tistih, ki so rojeni od žen, večji od Janeza Krstnika; kdor je pa najmanjši v nebeškem kraljestvu, je večji od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 12, 'Od dni Janeza Krstnika pa doslej silo trpi nebeško kraljestvo, in siloviteži si ga siloma laste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 13, 'Kajti vsi proroki in zakon so prorokovali do Janeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 14, 'In če hočete sprejeti to: on je Elija, ki ima priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 15, 'Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 16, 'Komu naj pa primerjam ta rod? Podoben je otrokom, ki posedajo po trgu in kličejo tovarišem svojim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 17, 'in pravijo: Piskali smo vam, in niste plesali; žalostinke smo peli, in niste jokali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 18, 'Kajti prišel je Janez, in ne jé in ne pije, pa pravijo: Hudiča ima!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 19, 'Prišel je Sin človekov in jé in in pije, pa pravijo: Glejte človeka požeruha in pijanca, mitarjev in grešnikov prijatelja! A modrost božjo so opravičili njeni otroci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 20, 'Tedaj začne oponašati mestom, v katerih se je zgodilo največ njegovih čudežev, ker se niso izpokorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 21, 'Gorje ti, Korazin! gorje ti, Betsaida! zakaj ko bi se bili v Tiru in Sidonu zgodili čudeži, ki so se zgodili v vaju, bi se bila davno v raševniku in pepelu izpokorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 22, 'Ali pravim vam, Tiru in Sidonu bo v dan sodbe laže nego vama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 23, 'In ti, Kafarnavm, nisi li bil povzdignjen do neba? V pekel boš pahnjen; zakaj ko bi se bili v Sodomi zgodili čudeži, ki so se zgodili v tebi, bi stala še današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 24, 'Ali pravim vam, da bode Sodomski zemlji v dan sodbe laže nego tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 25, 'V ta čas odgovori Jezus in reče: Hvalim te, Oče, Gospodar neba in zemlje, da si to prikril modrim in razumnim in si to razodel nedoraslim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 26, 'da, Oče, ker tako je bila volja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 27, 'Vse mi je izročil Oče moj: in nihče ne pozna Sina nego samo Oče, tudi Očeta ne pozna nihče nego le Sin in komurkoli če Sin razodeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 28, 'Pridite k meni vsi, ki se trudite in ste obremenjeni, in jaz vas upokojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 29, 'Vzemite jarem moj nase in učite se od mene, ker sem krotek in iz srca ponižen: in najdete pokoj dušam svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 11, 30, 'Kajti jarem moj je sladek in breme moje je lahko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 1, 'V tem času je šel Jezus v soboto skozi setve, učenci njegovi pa postanejo lačni in začno klasje trgati in jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 2, 'Ko pa farizeji to vidijo, mu reko: Glej, učenci tvoji delajo, kar se v soboto ne sme delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 3, 'On jim pa reče: Niste li brali, kaj je storil David, ko je bil lačen on in kateri so bili ž njim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 4, 'kako je šel v hišo Božjo in so jedli predložene kruhe, katerih ni smel jesti ne on, ne tisti, ki so bili ž njim, razen samo duhovniki?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 5, 'Ali niste brali v postavi, da duhovniki ob sobotah v templju skrunijo soboto, in so brez greha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 6, 'Pravim vam pa, da je tu večji nego tempelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 7, 'Ko bi pa vedeli, kaj se pravi: „Usmiljenja hočem in ne daritve“, ne bi obsojali nedolžnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 8, 'Kajti Sin človekov je sobote gospodar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 9, 'In odide odondod, in pride v njih shodnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 10, 'In glej, bil je tu človek, ki je imel suho roko. In vprašajo ga, govoreč: Ali se sme v soboto zdraviti? da bi ga zatožili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 11, 'On jim pa reče: Kateri človek je med vami, ki ima eno ovco, in če mu ta pade v soboto v jamo, da je ne zgrabi in ne izvleče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 12, 'In koliko boljši je človek od ovce! Zatorej se sme v soboto dobro delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 13, 'Tedaj veli človeku: Iztegni roko svojo! Pa jo iztegne, in bila je izlečena in zdrava kakor druga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 14, 'Farizeji pa izidejo in se posvetujejo zoper njega, kako bi ga pogubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 15, 'Ko pa Jezus to zazna, se umakne odtod; in mnogo jih gre za njim, in ozdravi jih vse');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 16, 'in jim zapreti, naj ga ne razglašajo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 17, 'da se izpolni, kar je rečeno po proroku Izaiju, ki pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 18, '„Glej, hlapec moj, ki sem ga izvolil, ljubljenec moj, ki je duši moji po volji: Duha svojega položim nanj, in oznanjeval bo sodbo poganskim narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 19, 'Ne bo se prepiral, ne vpil, in nihče ne bo slišal glasu njegovega po ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 20, 'Nalomljenega trsta ne prelomi in tlečega stenja ne ugasi, dokler ne privede sodbe do zmage.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 21, 'In v ime njegovo bodo upali pogani“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 22, 'Tedaj mu pripeljejo obsedenca, ki je bil slep in mutast. In ozdravi ga, da je slepec in mutec videl in govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 23, 'In vse množice so se zavzemale, govoreč: Ali ni ta sin Davidov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 24, 'Ko pa to slišijo farizeji, reko: Ta ne izganja zlih duhov, razen z Belzebulom, poglavarjem hudičev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 25, 'On je pa vedel njih misli in jim reče: Vsako kraljestvo, ki se samo zoper sebe razdvoji, propade, in vsako mesto ali dom, ki se sam zoper sebe razdvoji, ne obstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 26, 'In če satan izganja satana, se je razdvojil sam zoper sebe: kako bo torej obstalo kraljestvo njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 27, 'In če jaz z Belzebulom izganjam zle duhove, s čigavo pomočjo jih izganjajo sinovi vaši? zato vam bodo oni sodniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 28, 'Če pa jaz v moči Duha Božjega izganjam zle duhove, torej je že prišlo k vam kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 29, 'Ali kako more kdo močnemu priti v hišo in mu pohištvo pobrati, če močnega poprej ne zveže? In potem šele oropa hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 30, 'Kdor ni z menoj, je proti meni, in kdor ne zbira z menoj, razsiplje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 31, 'Zato vam pravim: Vsak greh in vsaka kletvina se odpusti ljudem, kletvina zoper Duha pa ne bo odpuščena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 32, 'In če kdo reče besedo zoper Sina človekovega, mu bo odpuščeno, kdor pa reče zoper svetega Duha, ne bo mu odpuščeno ne v tem veku, ne v prihodnjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 33, 'Ali vsadite dobro drevo, in njegov sad bo dober, ali vsadite slabo drevo, in sad njegov bo slab: zakaj drevo se spozna po sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 34, 'Gadja zalega, kako morete govoriti dobro, ko ste hudobni? kajti usta govore, česar je srce prepolno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 35, 'Dobri človek prinaša iz dobrega zaklada dobro, in hudobni človek prinaša iz hudega zaklada hudobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 36, 'Pravim vam pa, da bodo ljudje za vsako prazno besedo, katerokoli reko, dajali odgovor v dan sodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 37, 'Kajti po svojih besedah boš opravičen in po svojih besedah boš obsojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 38, 'Tedaj mu odgovore nekateri pismarjev in farizejev in reko: Učenik, znamenje hočemo od tebe videti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 39, 'On pa odgovori in jim reče: Hudobni in prešeštni rod išče znamenja, a ne bo mu dano znamenje razen znamenja proroka Jona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 40, 'Kakor je bil namreč Jona v trebuhu morskega velikana tri dni in tri noči, tako bode Sin človekov v krilu zemlje tri dni in tri noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 41, 'Možje Ninivljani bodo vstali ob sodbi s tem rodom in ga obsodijo, kajti oni so se izpokorili po propovedi Jonovi, in glej, tu je večji od Jona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 42, 'Južna kraljica bo vstala ob sodbi s tem rodom in ga obsodi, kajti prišla je od kraja sveta, da sliši modrost Salomonovo, in glej, tu je večji od Salomona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 43, 'Kadar pa zapusti nečisti duh človeka, hodi po suhih krajih in išče pokoja, in ga ne najde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 44, 'Tedaj reče: Pojdem nazaj v dom svoj, odkoder sem izšel. In ko pride tja, ga najde praznega, očejenega in olepšanega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 45, 'Tedaj odide in vzame s seboj sedem drugih duhov, hujših od sebe, ter vnidejo in tu prebivajo: in poslednje tega človeka postane hujše od prvega. Tako bode tudi temu hudobnemu rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 46, 'Ko je pa še govoril množici, glej, mati njegova in bratje njegovi so stali zunaj in radi bi bili ž njim govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 47, 'In nekdo mu reče: Glej, mati tvoja in bratje tvoji stojé zunaj in radi bi s teboj govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 48, 'On pa odgovori in reče tistemu, ki mu je povedal: Kdo je mati moja? in kdo so bratje moji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 49, 'In iztegnivši roko svojo na učence svoje, reče: Glej, mati moja in bratje moji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 12, 50, 'Kajti kdorkoli izpolni voljo Očeta mojega, ki je v nebesih, on mi je brat in sestra in mati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 1, 'Tisti dan pa je Jezus šel iz hiše in sedel pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 2, 'In zbere se pri njem veliko ljudstva, toliko, da stopi v ladjo in sede, in vsa množica je stala na bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 3, 'In govori jim v prilikah mnogo in pravi: Glej, sejalec je šel sejat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 4, 'In ko seje, pade nekaj zrnja poleg ceste, in prileté ptice in ga pozobljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 5, 'Drugo pa pade na skalnata tla, kjer nima veliko prsti, in precej požene, ker nima globoke zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 6, 'Ko pa vzide solnce, uvene, in ker nima korenine, usahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 7, 'Drugo pa pade med trnje, in trnje zraste ter ga zaduši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 8, 'Drugo pa pade na dobro zemljo in prinaša sad, nekatero po sto zrn, nekatero po šestdeset, nekatero po trideset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 9, 'Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 10, 'In učenci pristopijo in mu reko: Zakaj jim v prilikah govoriš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 11, 'On pa odgovori in jim reče: Ker vam je dano, da spoznate skrivnosti nebeškega kraljestva, njim pa ni dano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 12, 'Kajti kdor ima, mu bode dano in preobilno bo imel, kdor pa nima, se mu odvzame tudi to, kar ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 13, 'Zato jim govorim v prilikah, ker gledajoč ne vidijo in poslušajoč ne slišijo in ne umejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 14, 'In na njih se izpolnjuje prorokovanje Izaija, katero pravi: „S sluhom boste slišali, a ne boste umeli, in z očmi boste gledali, a ne boste videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 15, 'Kajti temu ljudstvu je srce okamenelo, in z ušesi težko slišijo, in oči svoje so zatisnili: da ne bi kdaj videli z očmi in slišali z ušesi in umeli s srcem in se izpreobrnili, in bi jih jaz ozdravil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 16, 'Blagor pa vašim očem, da vidijo, in vašim ušesom, da slišijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 17, 'Kajti resnično vam pravim, da so mnogi proroki in pravični želeli videti, kar vi vidite, in niso videli, in slišati, kar vi slišite, in niso slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 18, 'Čujte torej vi priliko o sejalcu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 19, 'Vsakemu, kdor sliši besedo o kraljestvu, pa je ne ume, pride hudobni duh in ukrade, kar je posejano v srcu njegovem; ta je, ki je posejan poleg ceste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 20, 'Kdor pa je posejan na skalnatih tleh, ta je, ki besedo posluša in jo precej z veseljem sprejme;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 21, 'toda nima korenine v sebi, temuč je nestanoviten. Kadar pa nastane stiska ali preganjanje zavoljo besede, se precej pohujšuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 22, 'Kdor je pa posejan v trnju, ta je, ki besedo sliši, ali skrb tega sveta in slepilo bogastva uduši besedo in ostane brez sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 23, 'Kdor je pa posejan na dobro zemljo, ta je, ki besedo sliši in umeje; ta torej rodi sad in donaša nekateri stoteren, nekateri pa šestdeseteren, a nekateri trideseteren.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 24, 'Drugo priliko jim predloži, govoreč: Nebeško kraljestvo je podobno človeku, ki je posejal dobro seme na njivi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 25, 'Medtem pa, ko so ljudje spali, pride njegov sovražnik in poseje ljuljke med pšenico in odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 26, 'Ko pa zraste setev in donese sad, se pokaže tudi ljuljka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 27, 'Pridejo pa hišnega gospodarja hlapci in mu reko: Gospod, nisi li dobrega semena posejal na svoji njivi? Odkod je pa prišla vanj ljuljka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 28, 'On pa jim reče: Sovražnik je to storil. Hlapci mu pa reko: Hočeš li torej, da gremo in jo izplevemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 29, 'On pa veli: Ne! da ne bi kdaj, trgaje ljuljko, izrovali ž njo vred pšenice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 30, 'Pustite, naj raste oboje skupaj do žetve, in v čas žetve porečem žanjcem: Poberite najprej ljuljko in zvežite jo v snopke, da se sežge, pšenico pa spravite v žitnico mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 31, 'Drugo priliko jim predloži, govoreč: Nebeško kraljestvo je podobno gorčičnemu zrnu, ki ga človek vzame in vseje na njivi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 32, 'To je res najdrobnejše izmed vseh semen: kadar pa zraste, je večje od zelišč in postane drevo, da prileté ptice nebeške in si delajo gnezda po vejah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 33, 'Drugo priliko jim pove: Nebeško kraljestvo je podobno kvasu, ki ga vzame žena in primesi trem mericam moke, dokler se vse ne skvasi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 34, 'Vse to je govoril Jezus množicam v prilikah, in brez prilike jim ni govoril,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 35, 'da se izpolni, kar je rečeno po proroku, ki pravi: „V prilikah odprem usta svoja, pripovedoval bom, kar je skrito od ustanovitve sveta“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 36, 'Tedaj razpusti ljudstvo in pride domov. In pristopijo k njemu učenci njegovi, rekoč: Razloži nam priliko o ljuljki na njivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 37, 'On pa odgovori in reče: Sejalec dobrega semena je Sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 38, 'Njiva pa je svet, a dobro seme, to so sinovi kraljestva, ljuljka pa so sinovi hudobnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 39, 'sovražnik, ki jo poseva, je hudič; žetev je pa konec sveta, a ženjci so angeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 40, 'Kakor torej ljuljko pobirajo in v ognju sežigajo, tako bode na koncu tega sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 41, 'Sin človekov pošlje angele svoje, in pobero iz kraljestva njegovega vse, kar napravlja pohujšanje, in tiste, ki delajo krivico,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 42, 'in jih vržejo v ognjeno peč: tam bo jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 43, 'Tedaj se bodo svetili pravični kakor solnce v svojega Očeta kraljestvu. Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 44, 'Nebeško kraljestvo je podobno zakladu, skritemu na polju, katerega človek najde in skrije, in od veselja gre in proda vse, kar ima, in kupi tisto polje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 45, 'Zopet je podobno nebeško kraljestvo kupcu, ki išče lepih biserov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 46, 'In ko najde eden dragocen biser, gre in proda vse, kar ima, in ga kupi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 47, 'Zopet je nebeško kraljestvo podobno mreži, ki se vrže v morje in zajme rib vsake vrste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 48, 'Ko se napolni, jo izvlečejo na breg, in sedejo in pobero, kar je dobro, v posode, a kar je slabo, pomečejo proč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 49, 'Tako bode na koncu sveta. Angeli pridejo in ločijo hudobne izmed pravičnih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 50, 'in jih vržejo v ognjeno peč; tam bo jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 51, 'Reče jim: Ste li vse to razumeli? Reko mu: Da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 52, 'On jim pa reče: Zato je vsak pismouk, ki je postal učenec za nebeško kraljestvo, podoben hišnemu gospodarju, ki prinaša iz zaklada svojega staro in novo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 53, 'In zgodi se, ko konča Jezus te prilike, odide odtod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 54, 'In prišedši v domovino svojo, jih uči v njih shodnici, tako da se zavzemajo in govoré: Odkod temu ta modrost in take moči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 55, 'Ali ni ta tesarjev sin? ali se ne imenuje mati njegova Marija in bratje njegovi Jakob in Jožef in Simon in Juda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 56, 'in niso li vse sestre njegove pri nas? Odkod torej temu vse to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 57, 'In pohujševali so se nad njim. Jezus pa jim reče: Nikjer ni prorok brez časti, razen v domovini in na domu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 13, 58, 'In ni storil ondi mnogo čudežev zavoljo njih nevere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 1, 'V tem času zasliši četrtnik Herod glas o Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 2, 'ter reče hlapcem svojim: Ta je Janez Krstnik; on je vstal od mrtvih, in zato delujejo čudežne moči v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 3, 'Herod je bil namreč Janeza ujel in ga vklenil in posadil v ječo zaradi Herodiade, svojega brata Filipa žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 4, 'Zakaj Janez mu je dejal: Ni ti je dovoljeno imeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 5, 'In hotel ga je umoriti, ali zbal se je ljudstva, ker so ga imeli za proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 6, 'Ko pa je bil Herodov rojstni dan, je plesala Herodiadina hči pred družbo in ugodila Herodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 7, 'zato ji s prisego obljubi dati, karkoli bi prosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 8, 'Ona pa, poučena od matere svoje, reče: Daj mi tu v skledi glavo Janeza Krstnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 9, 'In kralju se užali, toda zavoljo prisege in gostov ji ukaže dati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 10, 'In pošlje odsekat Janezu v ječi glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 11, 'In prineso glavo njegovo v skledi in dado dekletu, in jo nese materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 12, 'In pridejo učenci njegovi, vzamejo truplo in ga pokopljejo, ter pridejo in sporoče Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 13, 'Ko pa Jezus to zasliši, odrine odtod na ladji v pust kraj, da bi bil na samem. In ko množice to zvedo, pridejo peš za njim iz mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 14, 'In Jezus izide in ugleda veliko množico, in zasmilijo se mu ter ozdravi njih bolnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 15, 'Ko se pa zvečeri, pristopijo k njemu učenci njegovi, govoreč: Kraj je samoten in ura že pozna, razpusti množice, da odidejo v vasi in si kupijo živeža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 16, 'Jezus pa jim reče: Ni jim treba odhajati, dajte jim vi jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 17, 'Oni mu pa reko: Nimamo tu več nego pet hlebov in dve ribi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 18, 'On pa veli: Prinesite mi jih sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 19, 'Ter ukaže množici, naj sedejo po travi, in vzame petero hlebov in tisti dve ribi, pogleda v nebo in blagoslovi ter prelomi in da hlebe učencem, učenci pa ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 20, 'In jedli so vsi in se nasitili, in pobrali so ostale kosce, polnih dvanajst košev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 21, 'Bilo jih je pa, ki so jedli, kakih pet tisoč mož, brez žen in otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 22, 'In precej prisili učence svoje, naj stopijo v ladjo in se sami prepeljejo na drugo stran, on pa medtem razpusti množice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 23, 'In razpustivši množice, odide sam posebe na goro molit. Ko pa nastane noč, je bil tu sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 24, 'Ladja pa je plula že sredi morja, in valovi so jo premetavali, kajti veter je bil nasproten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 25, 'Ob četrti straži po noči pa odide Jezus k njim, hodeč po morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 26, 'In ko ga učenci ugledajo hodečega po morju, se ustrašijo in reko: Prikazen je! in od strahu zakriče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 27, 'Jezus pa jih takoj ogovori in reče: Bodite srčni! Jaz sem, ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 28, 'Peter mu pa odgovori in reče: Gospod, če si ti, ukaži mi, naj pridem k tebi po vodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 29, 'On pa veli: Pridi! In Peter stopi iz ladje in gre po morju, da pride k Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 30, 'Ko pa vidi, da je veter močan, se uplaši, in ko se začne potapljati, zavpije, rekoč: Gospod, otmi me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 31, 'Jezus pa precej iztegne roko in ga prime ter mu reče: Malovernež, čemu si dvomil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 32, 'In ko stopita v ladjo, veter utihne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 33, 'Tisti pa, ki so bili v ladji, pristopijo ter se mu poklonijo, govoreč: Resnično si Sin Božji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 34, 'In se prepeljejo in pristanejo v Genezaretu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 35, 'In ko ga spoznajo možje tega kraja, pošljejo po vsej tisti okolici, in mu prineso vse bolnike');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 14, 36, 'in ga prosijo, da bi se smeli dotekniti roba obleke njegove. In katerikoli so se doteknili, so ozdraveli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 1, 'Tedaj pridejo k Jezusu iz Jeruzalema pismarji in farizeji, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 2, 'Zakaj prestopajo učenci tvoji izročilo starih? Ne umivajo si namreč rok, kadar jedo kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 3, 'On pa odgovori in reče: Zakaj prestopate tudi vi zapoved Božjo zaradi izročila svojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 4, 'Bog je namreč rekel: „Spoštuj očeta svojega in mater“, in: „Kdor kolne očeta ali mater, naj umrje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 5, 'Vi pa pravite: Če kdo reče očetu ali materi: V daritev bodi, s čimer bi ti jaz pomagal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 6, 'ni več zavezan spoštovati očeta svojega ali matere svoje. In tako ste ovrgli zapoved Božjo zaradi izročila svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 7, 'Hinavci, dobro je o vas prorokoval Izaija, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 8, '„To ljudstvo me časti z ustnicami svojimi, njih srce pa je daleč od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 9, 'Ali zastonj me časté, učeč nauke, zapovedi človeške“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 10, 'In pokliče množico k sebi in jim reče: Poslušajte in umejte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 11, 'Ne skruni človeka to, kar prihaja v usta, temuč kar izhaja iz ust, to skruni človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 12, 'Tedaj pristopijo učenci njegovi in mu reko: Veš li, da so se farizeji, ko so slišali to besedo, spotikali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 13, 'On pa odgovori in reče: Vsaka rastlina, katere ni zasadil Oče moj nebeški, se bo izrovala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 14, 'Pustite jih! Oni so slepcem slepi vodniki. Če pa slepec slepca vodi, padeta oba v jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 15, 'Peter pa odgovori in mu reče: Razloži nam to priliko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 16, 'Jezus pa reče: Ali ste tudi vi še nerazumni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 17, 'Ne umete li, da gre vse, kar prihaja v usta, v trebuh in se meče ven?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 18, 'Kar pa prihaja iz ust, izhaja iz srca, in to skruni človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 19, 'Zakaj iz srca izhajajo hudobne misli, uboji, prešeštva, nečistosti, tatvine, kriva pričevanja, kletvine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 20, 'To je, kar oskrunja človeka; jesti pa z neumitimi rokami ne oskrunja človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 21, 'In Jezus odide odtod in se umakne v okraje tirske in sidonske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 22, 'In glej, žena Kananičanka pride iz teh krajev ter zavpije in reče: Usmili se me, Gospod, sin Davidov; mojo hčer zelo muči zli duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 23, 'On ji pa ne odgovori besede. In pristopijo učenci njegovi in ga prosijo, rekoč: Odpravi jo, ker kriči za nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 24, 'On pa odgovori in reče: Nisem poslan, razen le k izgubljenim ovcam Izraelove hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 25, 'Ona pa pristopi ter pade pred njim, rekoč: Gospod, pomagaj mi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 26, 'On pa odgovori in reče: Ni lepo, da se vzame kruh otrokom in se vrže psičkom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 27, 'Ona pa reče: Da, Gospod, toda tudi psički jedo od drobtinic, ki padajo z mize njih gospodarjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 28, 'Tedaj odgovori Jezus in ji veli: O žena, velika je vera tvoja. Zgodi naj se ti, kakor hočeš. In njena hči je ozdravela tisto uro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 29, 'In Jezus odide odtod in pride h Galilejskemu morju, in stopivši na goro, sede tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 30, 'In pridejo k njemu velike množice, ki so imeli s seboj hrome, slepce, mutce, pohabljene in mnogo drugih, ter jih polože k nogam Jezusovim; in on jih ozdravi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 31, 'tako da se ljudstvo začudi, ko vidijo, da mutci govore in pohabljeni so zdravi in hromi hodijo in slepci vidijo; in so slavili Boga Izraelovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 32, 'Pokliče pa Jezus učence svoje in reče: Ljudstvo se mi smili, ker so že tri dni pri meni in nimajo kaj jesti. A lačnih jih nočem odpraviti, da ne omagajo na poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 33, 'In reko mu učenci njegovi: Odkod bi mi vzeli v puščavi toliko kruha, da bi nasitili toliko ljudstva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 34, 'In reče jim Jezus: Koliko hlebov imate? Oni pa reko: Sedem, in malo ribic.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 35, 'In ukaže množici, naj sedejo po tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 36, 'In vzame sedmero hlebov in ribe in zahvalivši se, prelomi in da učencem, učenci pa ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 37, 'In jedli so vsi in se nasitili; in pobrali so ostale kosce, polnih sedem košev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 38, 'Bilo jih je pa, ki so jedli, štiri tisoč, brez žen in otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 15, 39, 'Razpustivši pa ljudstvo, stopi v ladjo in pride v pokrajino Magadansko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 1, 'In pristopijo k njemu farizeji in saduceji in izkušaje ga zaprosijo, naj jim pokaže znamenje z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 2, 'On pa odgovori in jim reče: Ko se zvečeri, pravite: Vedro bo, kajti žari se nebo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 3, 'in zjutraj pravite: Danes bo nevihta, kajti nebo se žari in oblači. Nebeško lice znate razločevati, znamenj časov pa ne morete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 4, 'Hudobni in prešeštni rod išče znamenja; a ne bo mu dano znamenje razen znamenja proroka Jona. In jih pusti in odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 5, 'In ko se prepeljejo učenci njegovi na drugo stran, so pozabili vzeti kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 6, 'Jezus jim pa reče: Pazite in varujte se kvasu farizejev in saducejev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 7, 'Oni so pa sami pri sebi mislili in govorili: To pravi, ker nismo vzeli kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 8, 'Ko pa Jezus to opazi, jim reče: Kaj premišljujete v sebi, maloverneži, da nimate kruha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 9, 'Ali še ne umete, tudi se ne spominjate petih hlebov petim tisočim in koliko košev ste nabrali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 10, 'tudi ne sedmih hlebov štirim tisočim in koliko košev ste nabrali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 11, 'Kako ne umete, da vam nisem rekel za kruh? Ali varujte se kvasu farizejev in saducejev!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 12, 'Tedaj so razumeli, da ni rekel, naj se varujejo kruhovega kvasu, ampak nauka farizejev in saducejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 13, 'Ko pa pride Jezus v kraje Cesareje Filipove, vpraša učence svoje, rekoč: Kdo pravijo ljudje, da sem jaz, Sin človekov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 14, 'Oni pa reko: Nekateri, da si Janez Krstnik, drugi pa, da si Elija, a drugi, da si Jeremija ali eden prorokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 15, 'Reče jim: Kdo pa pravite vi, da sem jaz?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 16, 'Simon Peter pa odgovori in reče: Ti si Kristus, Sin živega Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 17, 'In Jezus odgovori in mu reče: Blagor ti, Simon, Jonov sin, zakaj meso in kri ti nista tega razodela, ampak Oče moj, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 18, 'Pravim pa tudi jaz tebi: Ti si Peter, in na tej skali sezidam cerkev svojo in vrata peklenska je ne bodo premagala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 19, 'In dam ti ključe nebeškega kraljestva: in karkoli zvežeš na zemlji, bo zvezano v nebesih, in karkoli razvežeš na zemlji, bo razvezano v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 20, 'Tedaj zapove učencem svojim, naj nikomur ne pravijo, da je on Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 21, 'Odslej je jel Jezus kazati učencem svojim, da mora iti v Jeruzalem in mnogo trpeti od starejšin in višjih duhovnikov in pismarjev in umorjen biti in tretji dan od smrti vstati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 22, 'In Peter ga potegne na stran in ga začne odvračati, rekoč: Bog te obvaruj, Gospod! To se ti ne sme zgoditi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 23, 'On pa se obrne in reče Petru: Poberi se od mene, satan! Za pohujšanje si mi, ker ne umeš, kar je Božjega, nego kar je človeško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 24, 'Nato reče Jezus učencem svojim: Če kdo hoče za menoj iti, naj zataji samega sebe in vzame križ svoj nase in gre za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 25, 'Kajti kdor hoče ohraniti življenje svoje, ga izgubi, kdor pa izgubi življenje svoje zaradi mene, ga najde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 26, 'Kaj namreč pomore človeku, če ves svet pridobi, svoji duši pa škoduje? Ali kaj bo dal človek v zameno za dušo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 27, 'Kajti Sin človekov ima priti v slavi Očeta svojega z angeli svojimi, in tedaj povrne vsakemu po delu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 16, 28, 'Resnično vam pravim: Nekateri so med temi, ki stoje tu, ki ne bodo okusili smrti, dokler ne vidijo Sina človekovega, da prihaja v kraljestvu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 1, 'In čez šest dni vzame Jezus s seboj Petra in Jakoba in Janeza, njegovega brata, ter jih pelje same posebe na visoko goro,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 2, 'in se izpremeni pred njimi: njegov obraz se zasveti kakor solnce, a oblačila njegova postanejo bela kakor luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 3, 'In glej, prikažeta se jim Mojzes in Elija ter govorita ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 4, 'Peter pa izpregovori in reče Jezusu: Gospod, dobro nam je tukaj biti! Če hočeš, naredim tu tri šatore, tebi enega, Mojzesu enega in Eliju enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 5, 'Ko je še govoril, glej, jih obsenči svetel oblak, in glej, glas iz oblaka pravi: Ta je Sin moj ljubljeni, ki je po moji volji, njega poslušajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 6, 'Ko slišijo to učenci, padejo na obraz svoj in se zelo prestrašijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 7, 'In pristopi Jezus ter se jih dotakne in veli: Vstanite in ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 8, 'Ko so pa oči povzdignili, niso videli nikogar razen Jezusa samega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 9, 'In ko stopajo z gore, jim zapove Jezus, govoreč: Ne povejte nikomur o tej prikazni, dokler Sin človekov ne vstane od mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 10, 'In učenci njegovi ga vprašajo, rekoč: Kaj pravijo torej pismarji, da mora Elija poprej priti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 11, 'On pa odgovori in reče: Elija res pride in vse vnovič uravna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 12, 'Ali pravim vam: Elija je že prišel in ga niso spoznali, temuč so storili ž njim, kar so hoteli. Tako bo tudi Sin človekov trpel od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 13, 'Tedaj so razumeli učenci, da jim je to rekel o Janezu Krstniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 14, 'In ko pridejo k ljudstvu, pristopi k njemu človek in poklekne pred njim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 15, 'in reče: Gospod, usmili se sina mojega, ker je mesečen in grozno trpi. Velikokrat namreč pade v ogenj in velikokrat v vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 16, 'In pripeljal sem ga učencem tvojim, a niso ga mogli ozdraviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 17, 'Jezus pa odgovori in reče: O neverni in popačeni rod, doklej bodem še z vami? doklej bom vas še trpel? Pripeljite mi ga sem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 18, 'In zapreti mu Jezus, in zli duh izide iz njega, in mladenič je bil zdrav od tiste ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 19, 'Nato pristopijo učenci na samem k Jezusu in reko: Zakaj ga nismo mi mogli izgnati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 20, 'On jim pa reče: Zavoljo malovernosti svoje. Kajti resnično vam pravim, če imate vere za gorčično zrno, porečete tej gori: Premakni se odtod tja! in se premakne, in nič vam ne bode nemogoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 21, 'Ta rod pa ne izide, razen z molitvijo in s postom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 22, 'Ko pa so hodili skupaj po Galileji, jim reče Jezus: Sin človekov bo izdan ljudem v roke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 23, 'in umorili ga bodo, a tretji dan bo obujen. In postanejo silno žalostni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 24, 'Ko pa pridejo v Kafarnavm, pristopijo k Petru tisti, ki so pobirali tempeljski davek, in reko: Ali vaš učenik ne plačuje davka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 25, 'Reče: Pač. In ko pride v hišo, ga prehiti Jezus, rekoč: Kaj se ti zdi, Simon? Od koga pobirajo zemeljski kralji carino ali davek, od sinov svojih ali od tujcev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 26, 'Ko pa Peter odvrne: Od tujcev, mu reče Jezus: Torej so sinovi svobodni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 17, 27, 'Da jih pa ne pohujšamo, pojdi k morju in vrzi trnek, in vzemi prvo ribo, ki se ujame, in ji odpri usta in najdeš v njih srebrnik: tega vzemi in jim daj zame in zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 1, 'Tisto uro pristopijo učenci k Jezusu, govoreč: Kdo je vendar največji v nebeškem kraljestvu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 2, 'In pokliče otroka in ga postavi sredi mednje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 3, 'in reče: Resnično vam pravim, če se ne izpreobrnete in ne postanete kakor otroci, nikakor ne pridete v nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 4, 'Kdor se torej poniža kakor ta otrok, ta je največji v nebeškem kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 5, 'In kdorkoli sprejme enega takšnega otroka v moje ime, sprejme mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 6, 'Kdor pa pohujša enega teh malih, ki verujejo v mene, bi mu bilo bolje, da bi mu obesili mlinski kamen na vrat in bi ga potopili v globočino morja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 7, 'Gorje svetu zavoljo pohujšanja! Pohujšanja sicer morajo priti, toda gorje tistemu človeku, po katerem pride pohujšanje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 8, 'Če te pa pohušuje roka tvoja ali noga tvoja, odsekaj jo in vrzi od sebe; bolje ti je hromemu ali brez roke priti v življenje, nego dve roki in dve nogi imeti in vrženemu biti v večni ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 9, 'In če te pohujšuje oko tvoje, izderi ga in vrzi od sebe; bolje ti je z enim očesom priti v življenje, nego dve očesi imeti in vrženemu biti v peklenski ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 10, 'Glejte, da ne zaničujete enega teh malih! Kajti pravim vam, da njih angeli v nebesih vedno gledajo obličje Očeta mojega, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 11, 'Zakaj Sin človekov je prišel, da zveliča, kar se je izgubilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 12, 'Kaj se vam zdi? Če ima kateri človek sto ovac in ena od njih zajde, ne pusti li on devetindevetdeseterih na gorah in ne pojde, da išče tiste, ki je zašla!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 13, 'In če se zgodi, da jo najde, resnično vam pravim, da se je bolj veseli nego devetindevetdeseterih, ki niso zašle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 14, 'Tako ni volja Očeta vašega, ki je v nebesih, da se pogubi eden teh malih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 15, 'Če se pa pregreši brat zoper tebe, pojdi in mu njegov pregrešek pokaži med seboj in njim samim. Če te posluša, si pridobil brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 16, 'Če pa ne posluša, vzemi s seboj še enega ali dva, da se opira na usta dveh ali treh prič vsaka beseda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 17, 'Če jih pa ne posluša, povej cerkvi; če pa tudi cerkve ne posluša, naj ti bo kakor pogan in cestninar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 18, 'Resnično vam pravim: Karkoli zvežete na zemlji, bo zvezano v nebesih, in karkoli razvežete na zemlji, bo razvezano v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 19, 'Zopet vam pravim: Če se dva izmed vas zedinita na zemlji v čemerkoli, da bosta za to prosila, se jima zgodi od Očeta mojega, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 20, 'Kajti kjer sta dva ali trije zbrani v mojem imenu, tam sem jaz sredi med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 21, 'Tedaj pristopi k njemu Peter in reče: Gospod, kolikokrat, ko se pregreši brat moj zoper mene, naj mu odpustim? Ali do sedemkrat?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 22, 'Jezus mu reče: Ne pravim ti do sedemkrat, marveč do sedemdesetkrat sedemkrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 23, 'Zato je nebeško kraljestvo podobno kralju, ki je hotel napraviti račun s hlapci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 24, 'In ko začne računiti, mu pripeljejo enega, ki je bil dolžen deset tisoč talentov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 25, 'Ker pa ni imel s čim plačati, ukaže gospodar njegov prodati njega in ženo njegovo in otroke in vse, kar ima, in naj se mu plača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 26, 'Hlapec pa pade pred njega ter se mu poklanja, govoreč: Gospod, potrpi z menoj, in vse ti poplačam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 27, 'Gospodar tistega hlapca pa, ganjen usmiljenja, ga oprosti in mu odpusti dolg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 28, 'Ko pa ta hlapec gre od njega, najde enega svojih sohlapcev, ki mu je bil dolžen sto denarjev, ter ga zgrabi in davi, govoreč: Plačaj, kar si dolžen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 29, 'Njegov sohlapec pa pade k nogam njegovim ter ga prosi, rekoč: Potrpi z menoj, in vse ti poplačam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 30, 'On pa noče, temuč ga odvede in vrže v ječo, dokler ne plača dolga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 31, 'Ko pa vidijo sohlapci njegovi, kar se je zgodilo, se jim zelo užali; ter pridejo in natanko sporoče gospodarju svojemu ves dogodek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 32, 'Tedaj ga pokliče gospodar njegov in mu veli: Hudobni hlapec! ves tisti dolg sem ti odpustil, ker si me prosil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 33, 'ali bi ne bilo prav, da se tudi ti usmiliš sohlapca svojega, kakor sem se tudi jaz tebe usmilil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 34, 'In gospodar njegov se razjezi in ga izroči trinogom, dokler ne poplača vsega, kar mu je bil dolžen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 18, 35, 'Tako bo storil tudi Oče moj nebeški vam, ako ne odpustite iz srca svojega vsakteri svojemu bratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 1, 'In zgodi se, ko konča Jezus te besede, da odrine iz Galileje in pride v Judejske kraje onkraj Jordana;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 2, 'in za njim gredo velike množice, in ozdravi jih ondi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 3, 'In pristopijo k njemu farizeji ter ga izkušajo in mu reko: Ali je dovoljeno človeku, ločiti se od žene svoje iz kakršnegakoli vzroka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 4, 'On pa odgovori in jim reče: Ali niste brali, da ju je Stvarnik od začetka ustvaril kot moža in ženo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 5, 'in je rekel: „Zaradi tega zapusti človek očeta in mater in se pridruži ženi svoji, in ta dva bosta eno meso“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 6, 'Tako nista več dva, ampak eno meso. Kar je torej Bog združil, naj človek ne razdružuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 7, 'Reko mu: Zakaj je torej Mojzes zapovedal dati ločitni list in jo pustiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 8, 'Reče jim: Mojzes vam je zaradi trdosrčnosti vaše dovolil ločiti se od svojih žen; od začetka pa ni bilo tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 9, 'Pravim vam pa: Kdorkoli se loči od žene svoje (razen zavoljo nečistosti) in se oženi z drugo, prešeštvuje; in kdor ločeno vzame, prešeštvuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 10, 'Reko mu učenci: Če je taka moževa reč z ženo, ni dobro ženiti se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 11, 'On pa jim reče: Te besede ne razumejo vsi, nego samo ti, katerim je dano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 12, 'So namreč skopljenci, ki so se iz materinega telesa tako rodili; in so skopljenci, ki so jih ljudje skopili; in so skopljenci, ki so se sami skopili zavoljo nebeškega kraljestva. Kdor more razumeti, naj razume!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 13, 'Tedaj prineso k njemu otročiče, naj položi nanje roke in moli; učenci jih pa okarajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 14, 'Jezus pa reče: Pustite otročiče in ne branite jim priti k meni; kajti takih je nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 15, 'In položivši nanje roke, odide odtod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 16, 'In glej, eden pristopi in mu reče: Dobri učenik, kaj dobrega naj storim, da imam večno življenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 17, 'On mu pa reče: Kaj mene vprašuješ po dobrem? Eden je, ki je dober. Če pa hočeš priti v življenje, izpolnjuj zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 18, 'Vpraša ga: Katere? Jezus pa reče: „Ne ubijaj, ne prešeštvuj, ne kradi, ne pričaj po krivem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 19, 'spoštuj očeta svojega in mater svojo, in ljubi bližnjega svojega kakor samega sebe“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 20, 'Mladenič mu reče: Vse to sem izpolnjeval od mladosti svoje; česa mi je še treba?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 21, 'Jezus mu veli: Če hočeš biti popoln, pojdi, prodaj, kar imaš, in daj ubogim, in imel boš zaklad v nebesih, ter pridi in hodi za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 22, 'Ko pa sliši mladenič to besedo, odide žalosten: kajti imel je mnogo premoženja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 23, 'Jezus pa reče učencem svojim: Resnično vam pravim, da težko bogatin pride v nebeško kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 24, 'Zopet vam pravim: Laže je velblodu iti igli skozi uho nego bogatinu priti v kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 25, 'In ko slišijo to učenci njegovi, se silno zavzemo in reko: Kdo se torej more zveličati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 26, 'Jezus pa jih pogleda in jim reče: Pri ljudeh je to nemogoče, toda pri Bogu je vse mogoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 27, 'Tedaj odgovori Peter in mu reče: Glej, mi smo zapustili vse in smo šli za teboj; kaj bode torej nam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 28, 'Jezus jim pa reče: Resnično vam pravim, da boste vi, ki ste šli za menoj, ob prerojenju sveta, ko sede Sin človekov na prestol svoje slave, da boste sedli tudi vi na dvanajst prestolov in sodili dvanajstere rodove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 29, 'In vsak, kdor je zapustil hiše, ali brate, ali sestre, ali očeta, ali mater, ali otroke, ali njive zavoljo imena mojega, prejme stokrat več in podeduje večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 19, 30, 'A mnogi prvi bodo zadnji in zadnji prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 1, 'Kajti nebeško kraljestvo je podobno hišnemu gospodarju, ki je zgodaj zjutraj odšel najemat delavcev v vinograd svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 2, 'In pogodivši se z delavci po denarju na dan, jih pošlje v vinograd svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 3, 'In ko pride ven okoli tretje ure, ugleda druge, da stoje na trgu brez dela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 4, 'in jim reče: Pojdite tudi vi v moj vinograd, in dam vam, kar bo prav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 5, 'In oni odidejo. Ko pride ven zopet ob šesti in deveti uri, stori enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 6, 'Ko pa pride ven okoli enajste ure, najde druge, da postajajo, in jim reče: Kaj stojite tu ves dan brez dela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 7, 'Reko mu: Ker nas ni nihče najel. In veli jim: Pojdite tudi vi v moj vinograd.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 8, 'Ko se je pa zvečerilo, veli gospodar vinogradov oskrbniku svojemu: Pokliči delavce in daj jim plačilo, počenši od zadnjih do prvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 9, 'In prišedši prejmo tisti, ki so bili najeti okoli enajste ure, po denarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 10, 'Ko pa pridejo prvi, mislijo, da bodo prejeli več; a tudi oni prejmo po denarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 11, 'Prejemši ga, pa so godrnjali nad hišnim gospodarjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 12, 'govoreč: Ti poslednji so delali eno uro, in si jih naredil enake nam, ki smo prenašali breme vsega dne in vročino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 13, 'On pa odgovori in reče enemu izmed njih: Prijatelj, ne delam ti krivice. Ali se nisi pogodil z menoj po denarju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 14, 'Vzemi svoje in pojdi! Hočem pa dati temu poslednjemu, kakor tudi tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 15, 'Ali mar ne smem jaz s svojim storiti, kar hočem? Je li oko tvoje hudobno, ker sem jaz dober?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 16, 'Tako bodo zadnji prvi in prvi zadnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 17, 'In ko gre Jezus gori v Jeruzalem, vzame dvanajstere učence na stran in jim na potu reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 18, 'Glejte, gori v Jeruzalem gremo, in Sin človekov bo izdan višjim duhovnikom in pismarjem, in ga obsodijo na smrt,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 19, 'in ga izroče poganom, naj ga zasmehujejo in bičajo in na križ razpno; a tretji dan vstane od smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 20, 'Tedaj pristopi k njemu mati Zebedejevih sinov s svojima sinoma ter se mu poklanja in ga nekaj prosi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 21, 'On ji pa reče: Kaj hočeš? Reče mu: Reci, naj sedita ta dva moja sina, eden na desnici in drugi na levici tvoji, v tvojem kraljestvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 22, 'Jezus pa odgovori in reče: Ne veste, kaj prosite. Ali moreta piti kelih, ki mi ga bode skoraj piti? Rečeta mu: Moreva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 23, 'Reče jima: Kelih moj bosta sicer pila, ali da bi sedela na desnici in na levici moji, ne morem jaz dati, a dá se to tistim, ki jim je pripravljeno od Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 24, 'In ko to slišijo deseteri, se razjeze nad tema dvema bratoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 25, 'Jezus jih pa pokliče k sebi in reče: Veste, da knezi narodov tem gospodujejo in da jih velikaši siloma vladajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 26, 'Ne bode pa tako med vami: ampak kdorkoli hoče postati velik med vami, bodi vam služabnik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 27, 'in kdorkoli hoče biti prvi med vami, bodi vam hlapec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 28, 'Kakor tudi Sin človekov ni prišel, da njemu služijo, ampak da služi in dá življenje svoje v odkupnino za mnoge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 29, 'In ko gredo iz Jeriha, ga spremlja velika množica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 30, 'In glej, dva slepca sedita kraj poti, in ko slišita, da gre Jezus mimo, zakričita, rekoč: Gospod, usmili se naju, ti sin Davidov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 31, 'Množica pa jima preti, da naj umolkneta. Ona pa še bolj zavpijeta, rekoč: Gospod, usmili se naju, ti sin Davidov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 32, 'In Jezus se ustavi in ju pokliče ter reče: Kaj hočeta, da vama storim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 33, 'Rečeta mu: Gospod, da se nama oči odpro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 20, 34, 'Jezus pa, ganjen usmiljenja, se dotakne njunih oči. In precej izpregledata, in šla sta za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 1, 'In ko se približajo Jeruzalemu in pridejo v Betfago k Oljski gori, tedaj pošlje Jezus dva učenca');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 2, 'in jima reče: Pojdita v vas, ki je vama nasproti, in precej najdeta oslico privezano in žrebe ž njo: odvežita ju in pripeljita k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 3, 'In če vama kdo kaj reče, recita: Gospod ju potrebuje; in takoj ju pošlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 4, 'To pa se je zgodilo, da se izpolni, kar je rečeno po proroku, ki pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 5, '„Povejte hčeri sionski: Glej, kralj tvoj prihaja k tebi krotak in sedi na oslici in žrebetu oslice pod jarmom“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 6, 'In učenca gresta ter storita, kakor jima je Jezus ukazal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 7, 'pripeljeta oslico in žrebe. In položijo nanju oblačila svoja, in on sede nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 8, 'Mnogo ljudstva pa pogrne oblačila svoja po poti, a drugi sekajo veje z dreves, ter jih steljejo po poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 9, 'In množice, ki ga spremljajo spredaj in zadaj, kličejo glasno, govoreč: Hosana sinu Davidovemu! Blagoslovljen, ki prihaja v imenu Gospodovem! Hosana na višavah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 10, 'In ko pride v Jeruzalem, se vznemiri vse mesto in govoré: Kdo je ta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 11, 'Ljudstvo pa pravi: Ta je prorok Jezus iz Nazareta v Galileji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 12, 'In Jezus pride v tempelj Božji in izžene vse, ki so v templju prodajali in kupovali, in prevrne mize menjalcem in stole tistim, ki so prodajali golobe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 13, 'in jim reče: Pisano je: „Dom moj naj se imenuje dom molitve“, a vi delate iz njega razbojniško jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 14, 'In pristopijo k njemu v templju slepci in hromci, in jih ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 15, 'Ko pa vidijo višji duhovniki in pismarji čudeže, ki jih dela, in otroke, da kličejo v templju in govoré: Hosana sinu Davidovemu! se razjeze');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 16, 'in mu reko: Slišiš li, kaj ti pravijo? Jezus pa jim reče: Seveda. Ali niste nikoli brali: „Iz ust nedoraslih in dojencev si pripravil sebi hvalo?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 17, 'In jih pusti in gre ven iz mesta v Betanijo, in tu prenoči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 18, 'Zjutraj pa, vračajoč se v mesto, postane lačen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 19, 'In ugledavši kraj poti edino smokvo, pristopi k njej in ničesar ne najde na njej razen samo listje. In ji reče: Nikoli več naj ne bo na tebi sadu na vekomaj! In usahne smokva takoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 20, 'In videč to, se začudijo učenci in reko: Kako naglo je usahnila smokva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 21, 'Jezus pa odgovori in jim reče: Resnično vam pravim: Če imate vero in ne dvomite, ne boste samo storili, kar se je zgodilo na tej smokvi, ampak če tudi rečete tej gori: Vzdigni se in vrzi se v morje! se zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 22, 'In vse, česarkoli v molitvi prosite, če verujete, boste prejeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 23, 'In ko je prišel v tempelj in učil, pristopijo k njemu višji duhovniki in starejšine ljudstva, govoreč: S kakšno oblastjo delaš to? in kdo ti je dal to oblast?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 24, 'Jezus pa odgovori in jim reče: Vprašal vas bom tudi jaz eno besedo, in če mi jo poveste, povem tudi jaz vam, s kakšno oblastjo to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 25, 'Odkod je bil krst Janezov? iz nebes ali od ljudi? Oni pa so sami pri sebi premišljevali in govorili: Če rečemo: Iz nebes, nam poreče: Zakaj mu torej niste verovali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 26, 'Če pa rečemo: Od ljudi – se bojimo ljudstva; kajti vsi imajo Janeza za proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 27, 'In odgovore Jezusu in reko: Ne vemo. Tudi on jim reče: Tudi jaz vam ne povem, s kakšno oblastjo to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 28, 'Kaj se vam pa zdi? Neki človek je imel dva sina, in pristopivši k prvemu, reče: Sin, pojdi, delaj danes v vinogradu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 29, 'On pa odgovori in reče: Nočem. Potem se pa skesa in gre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 30, 'In pristopivši k drugemu, reče ravno tako. On pa odgovori in reče: Pojdem, gospod! A ni šel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 31, 'Kateri teh dveh je izpolnil voljo očetovo? Reko mu: Prvi. Jezus jim reče: Resnično vam pravim, da se rinejo cestninarji in nečistnice pred vami v kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 32, 'Kajti prišel je k vam Janez po poti pravičnosti, in niste mu verjeli; cestninarji in nečistnice pa so mu verjeli. Vi pa, dasi ste to videli, se še potem niste skesali, da bi mu bili verjeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 33, 'Čujte drugo priliko! Bil je hišni gospodar, ki je zasadil vinograd in ga ogradil s plotom in izkopal v njem klet in sezidal stolp ter ga izročil vinogradnikom in odpotoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 34, 'Ko se pa približa čas sadu, pošlje hlapce svoje k vinogradnikom, da prejmo pridelke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 35, 'A vinogradniki zgrabijo hlapce, in enega pretepo, drugega ubijejo, a še drugega posujejo s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 36, 'Zopet pošlje druge hlapce, ki jih je bilo več od prvih, in ž njimi store ravno tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 37, 'Potem pa pošlje k njim sina svojega, rekoč: Sina mojega se bodo bali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 38, 'Ko pa ugledajo vinogradniki sina, reko med seboj: Ta je dedič. Pridite, ubijmo ga in prilastimo si dediščino njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 39, 'Ter ga zgrabijo in vržejo ven iz vinograda in ubijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 40, 'Kadar pride torej gospodar vinogradov, kaj bo storil tem vinogradnikom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 41, 'Reko mu: Hudobneže te hudo pogubi in vinograd svoj izroči drugim vinogradnikom, ki mu bodo dajali sad ob svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 42, 'Jezus jim reče: Ali niste nikoli brali v pismu: „Kamen, ki so ga zidarji zavrgli, ta je postal glava voglu; od Gospoda se je to zgodilo, in čudno je v očeh naših“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 43, 'Zato vam pravim, da se vam odvzame kraljestvo Božje in bo dano narodu, ki prinaša njegove sadove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 44, 'In kdor na ta kamen pade, se razbije, a na kogar on pade, ga razdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 45, 'In ko slišijo višji duhovniki in farizeji prilike njegove, spoznajo, da govori o njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 21, 46, 'In radi bi ga bili ujeli, ali zboje se množic, ker so ga vsi imeli za proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 1, 'In odgovarjaje jim zoper govori Jezus v prilikah, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 2, 'Nebeško kraljestvo je podobno človeku, kralju, ki je napravil svatovščino sinu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 3, 'In pošlje hlapce svoje, naj pokličejo tiste, ki so bili povabljeni na svatovščino; a niso hoteli priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 4, 'Zopet pošlje druge hlapce in veli: Recite povabljencem: Glej, pojedino svojo sem pripravil, junci moji in pitanci so poklani in vse je pripravljeno; pridite na svatovščino!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 5, 'Oni pa niso marali in so odšli, eden na polje svoje, drugi pa po kupčiji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 6, 'Drugi pa so zgrabili hlapce njegove in jih zasramotili in ubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 7, 'Kralj pa se razjezi ter pošlje vojske svoje in pogubi tiste ubijalce in požge njih mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 8, 'Tedaj veli hlapcem svojim: Svatovščina je sicer pripravljena, ali povabljenci niso bili vredni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 9, 'Pojdite torej na razpotja, in kolikorkoli jih najdete, pokličite jih na svatovščino!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 10, 'In tisti hlapci odidejo na ceste in zbero vse, katerekoli najdejo, hudobne in dobre; in svatovska dvorana se napolni z gostmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 11, 'Ko pa pride kralj, da pogleda goste, ugleda tu človeka, ki ni bil oblečen v svatovsko oblačilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 12, 'in mu reče: Prijatelj, kako si prišel sem, ko nimaš svatovskega oblačila? On pa mu umolkne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 13, 'Tedaj reče kralj služabnikom svojim: Zvežite mu roke in noge ter ga vrzite v zunanjo temo; tam bo jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 14, 'Kajti mnogo jih je poklicanih, a malo izvoljenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 15, 'Tedaj odidejo farizeji in se posvetujejo, kako bi ga v besedi ujeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 16, 'In pošljejo k njemu učence svoje s Herodovci, naj reko: Učenik, vemo, da si resničen in pot Božjo v resnici učiš, in mar ti ni nikogar, kajti ne gledaš ljudem na lice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 17, 'Povej nam torej, kaj se ti zdi? Ali je prav dati cesarju davek ali ne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 18, 'Jezus pa, spoznavši njih hudobnost, reče: Kaj me izkušate, hinavci?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 19, 'Pokažite mi davčni denar. In oni mu prineso denar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 20, 'In reče jim: Čigava je ta podoba in napis?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 21, 'Reko mu: Cesarjeva. Tedaj jim reče: Dajte torej cesarju, kar je cesarjevega, in Bogu, kar je Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 22, 'In ko to slišijo, se začudijo, ter ga pusté in odidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 23, 'Tisti dan pristopijo k njemu saduceji, ki pravijo, da ni vstajenja, in ga vprašajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 24, 'rekoč: Učenik! Mojzes je rekel: „Ako kdo umre brez otrok, naj vzame njegov brat ženo njegovo in zbudi seme bratu svojemu“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 25, 'Pri nas pa je bilo sedem bratov. Prvi se oženi in umre, in ker ni imel zaroda, zapusti ženo svojo bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 26, 'Ravno tako tudi drugi in tretji prav do sedmega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 27, 'Nazadnje za vsemi pa umre žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 28, 'Ob vstajenju torej, čigava žena bo od teh sedmerih? kajti vsi so jo imeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 29, 'Jezus pa odgovori in jim reče: Motite se, ker ne poznate ne pisma, ne moči Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 30, 'Ob vstajenju namreč se ne ženijo in ne može, temuč so kakor angeli Božji v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 31, 'Za vstajenje mrtvih pa, ali niste brali, kar vam je rekel Bog, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 32, '„Jaz sem Bog Abrahamov in Bog Izakov in Bog Jakobov“? On ni Bog mrtvih, ampak živih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 33, 'In ko to slišijo množice, se silno čudijo nauku njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 34, 'Ko pa farizeji slišijo, da je saducejem zavezal jezik, se zbero vkup.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 35, 'In eden izmed njih, učenik postave, vpraša, izkušaje ga:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 36, 'Učenik, katera zapoved je v postavi največja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 37, 'Jezus mu pa reče: „Ljubi Gospoda, Boga svojega, iz vsega srca svojega in iz vse duše svoje in iz vse pameti svoje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 38, 'Ta je prva in največja zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 39, 'Druga pa je tej podobna: „Ljubi bližnjega svojega kakor samega sebe“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 40, 'Ob teh dveh zapovedih visi vsa postava in proroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 41, 'Ko se pa farizeji snidejo, jih vpraša Jezus,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 42, 'rekoč: Kaj se vam zdi o Kristusu? Čigav sin je? Reko mu: Davidov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 43, 'Vpraša jih: Kako ga torej David v Duhu imenuje Gospoda, ko pravi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 44, '„Rekel je Gospod Gospodu mojemu: Sedi na desnico mojo, dokler ne položim sovražnikov tvojih nogam tvojim za podnožje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 45, 'Če ga torej David imenuje Gospoda, kako je sin njegov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 22, 46, 'In nihče mu ni mogel odgovoriti besede, in od tega dne si ga ni upal nihče več vprašati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 1, 'Tedaj govori Jezus množici in učencem svojim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 2, 'takole: Na Mojzesov stol so sedli pismarji in farizeji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 3, 'Vse torej, karkoli vam reko, izpolnjujte in delajte; po njih delih pa ne delajte, ker govoré, pa ne delajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 4, 'Vežejo namreč težka in neznosna bremena in jih nakladajo ljudem na pleča, sami jih pa še s svojim prstom nočejo geniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 5, 'Vsa dela svoja pa delajo, da jih vidijo ljudje. Razširjajo si namreč molilne listke in delajo velike robove oblačilom svojim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 6, 'in ljubijo prve prostore pri gostijah in prve stole v shodnicah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 7, 'in pozdrave po ulicah ter da jih ljudje imenujejo: Rabi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 8, 'Vi pa se ne imenujte Rabi; kajti eden je vaš učenik, Kristus, vsi vi ste pa bratje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 9, 'In ne imenujte nikogar na zemlji očeta svojega; kajti eden je vaš Oče, ta, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 10, 'Tudi se ne imenujte voditeljev, kajti eden je vaš voditelj, Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 11, 'A kdor je največji med vami, bodi vam služabnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 12, 'Kdor se pa povišuje, bo ponižan, in kdor se ponižuje, bo povišan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 13, 'Gorje pa vam pismarji in farizeji, hinavci! da zapirate nebeško kraljestvo pred ljudmi; sami namreč ne greste vanje, in kateri hočejo vanje iti, jim ne puščate, da bi šli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 14, 'Gorje vam, pismarji in farizeji, hinavci! da požirate vdovam hiše, ko na videz opravljate dolge molitve; zategadelj prejmete ostrejšo sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 15, 'Gorje vam pismarji in farizeji, hinavci! ker prehodite morje in zemljo, da pridobite enega, ki se pojudi, in ko se pojudi, naredite iz njega peklenskega sinu, dvakrat hujšega od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 16, 'Gorje vam, slepi vodniki, ki pravite: Če kdo priseže pri templju, ni nič; če pa priseže kdo pri templjevem zlatu, je zavezan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 17, 'Bebci in slepci! kaj pa je več, zlato ali tempelj, ki posvečuje zlato?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 18, 'In: Če priseže kdo pri oltarju, ni nič; če pa priseže kdo pri daru, ki je na njem, je zavezan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 19, 'Slepci! kaj pa je več, dar ali oltar, ki posvečuje dar?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 20, 'Kdor torej prisega pri oltarju, prisega pri njem in pri vsem, kar je na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 21, 'In kdor prisega pri templju, prisega pri njem in pri tistem, ki prebiva v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 22, 'In kdor prisega pri nebu, prisega pri prestolu Božjem in pri tistem, ki sedi na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 23, 'Gorje vam, pismarji in farizeji, hinavci! da dajete desetino od mete in kopra in kumina, opuščate pa, kar je važnejše v postavi: sodbo, usmiljenje in vero. To pa je treba delati, a onega ne opuščati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 24, 'Slepi vodniki, ki precejate komarje, velbloda pa požirate!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 25, 'Gorje vam, pismarji in farizeji, hinavci! da čistite kozarec in skledo odzunaj, znotraj pa sta polna ropa in nezmernosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 26, 'Slepi farizej! očisti poprej kozarec in skledo znotraj, da bodeta čista tudi zunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 27, 'Gorje vam, pismarji in farizeji, hinavci! da ste podobni pobeljenim grobom, ki se odzunaj zde lepi, znotraj pa so polni mrtvaških kosti in vse nesnage.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 28, 'Tako se kažete tudi vi ljudem zunaj pravične, znotraj pa ste polni hinavstva in krivičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 29, 'Gorje vam, pismarji in farizeji, hinavci! da zidate prorokom grobe in lepšate pravičnim nagrobne spomenike,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 30, 'in pravite: Da smo živeli v dnevih očetov svojih, ne bi bili ž njimi deležni krvi prorokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 31, 'Tako pričate sami zoper sebe, da ste sinovi teh, ki so morili proroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 32, 'Napolnite le tudi vi mero očetov svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 33, 'Kače, gadja zalega! kako boste ubežali sodbi pekla?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 34, 'Zato, glejte, pošiljam jaz k vam proroke in modrce in pismouke; in nekatere izmed njih pomorite in na križ razpnete, a nekatere boste bičali v shodnicah svojih in preganjali od mesta do mesta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 35, 'da pride na vas vsa pravična kri, ki se je prelila na zemlji, od krvi pravičnega Abela do krvi Zaharija, sinu Barahijevega, ki ste ga umorili med svetiščem in oltarjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 36, 'Resnično vam pravim: Vse to pride na ta rod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 37, 'Jeruzalem, Jeruzalem, ki ubijaš proroke in kamenaš tiste, ki so poslani k tebi! Kolikokrat sem hotel zbrati otroke tvoje, kakor zbira kokla piščeta svoja pod peruti, pa niste hoteli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 38, 'Glej, hiša vaša se vam ostavlja pusta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 23, 39, 'Kajti pravim vam: Ne boste me videli odslej, dokler ne rečete: Blagoslovljen, ki prihaja v imenu Gospodovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 1, 'In Jezus izide in krene proč od templja. In pristopijo učenci njegovi, da mu pokažejo stavbe templja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 2, 'On pa odgovori in jim reče: Ne vidite li vsega tega? Resnično vam pravim: Tu ne ostane kamen na kamenu, ki se ne bi zrušil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 3, 'Ko je pa sedel na Oljski gori, pristopijo k njemu učenci posebej, rekoč: Povej nam, kdaj bode to? In kaj bo znamenje prihodu tvojemu in koncu sveta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 4, 'In Jezus odgovori in jim reče: Varujte se, da vas kdo ne zapelje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 5, 'Mnogo jih namreč pride z imenom mojim, govoreč: Jaz sem Kristus, in mnogo jih zapeljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 6, 'Slišali pa boste o bojih in glasove o bojih. Glejte, da se ne ustrašite; kajti to se mora zgoditi. Ali to še ni konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 7, 'Vstane namreč narod proti narodu in kraljestvo zoper kraljestvo, in bodo lakote in potresi po raznih krajih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 8, 'Vse to je pa začetek nadlogam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 9, 'Tedaj vas bodo izročali stiski in vas morili, in sovražili vas bodo vsi narodi zaradi imena mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 10, 'In tedaj se bodo pohujševali mnogi in drug drugega bodo izdajali in drug drugega sovražili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 11, 'In mnogi lažnivi proroki vstanejo ter jih veliko zapeljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 12, 'In ker se krivičnost razmnoži, omrzne mnogim ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 13, 'Kdor pa pretrpi do konca, ta bo zveličan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 14, 'In ta evangelij kraljestva se bo oznanjeval po vsem svetu, vsem narodom za pričevanje; in tedaj pride konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 15, 'Kadar torej ugledate „gnusobo razdejanja“, ki jo je napovedal prorok Daniel, da stoji na svetem kraju (kdor bere, naj razume!),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 16, 'tedaj naj zbeže tisti, ki so v Judeji, na gore;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 17, 'kdor je na strehi, ne stopaj doli, da vzame kaj iz hiše svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 18, 'in kdor je na polju, naj se ne vrača nazaj, da vzame plašč svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 19, 'Gorje pa nosečim in doječim v tistih dneh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 20, 'Molite pa, da ne bo vaš beg po zimi in ne v soboto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 21, 'Zakaj tedaj bo velika stiska, kakršne ni bilo od začetka sveta doslej in je tudi nikoli ne bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 22, 'In ko se ne bi tisti dnevi prikrajšali, ne bi se rešil noben človek; ali zaradi izvoljencev bodo prikrajšani tisti dnevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 23, 'Tedaj, če vam kdo reče: Glej, tu je Kristus, ali: tam je, ne verujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 24, 'Zakaj vstanejo lažnivi kristusi in lažnivi proroki in kazali bodo velika znamenja in čudeže, da bi zapeljali, ko bi bilo mogoče, tudi izvoljence.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 25, 'Glejte, povedal sem vam vnaprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 26, 'Ako vam torej reko: Glej, v puščavi je! ne hodite ven; glej, v hramih je! ne verujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 27, 'Kajti kakor izhaja blisk od vzhoda in se sveti do zahoda, tako bode prihod Sinu človekovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 28, 'Kjerkoli je mrhovina, tam se bodo zbirali orli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 29, 'Precej pa po stiski tistih dni otemni solnce, in mesec ne dá svetlobe svoje, in zvezde bodo padale z neba, in sile nebeške se bodo gibale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 30, 'In tedaj se prikaže na nebu znamenje Sinu človekovega; in tedaj zaplakajo vsi rodovi zemlje in bodo videli Sina človekovega, da prihaja na nebeških oblakih z močjo in slavo veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 31, 'In pošlje angele svoje z močnim glasom trobente, in zbero izvoljence njegove od četverih vetrov, od konca nebes do njih kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 32, 'Od smokve pa se učite prilike: Kadar se že njene veje omladé in poženo listje, veste, da je blizu poletje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 33, 'tako tudi vi, ko vse to ugledate, vedite, da je on blizu, pri vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 34, 'Resnično vam pravim: Ne preide ta rod, dokler se vse to ne zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 35, 'Nebo in zemlja preideta, a besede moje nikoli ne preidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 36, 'Za tisti dan in uro pa nihče ne ve, ne angeli nebeški, ne Sin, edini Oče sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 37, 'Kajti kakor je bilo v dnevih Noetovih, tako bode o prihodu Sina človekovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 38, 'Kakor so namreč v onih dnevih, pred potopom, žrli in pili, ženili se in možile do tistega dne, ko je stopil Noe v barko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 39, 'in niso spoznali, dokler ni prišla povodenj in jih je vse pobrala; tako bode prihod Sinu človekovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 40, 'Tedaj bodeta dva na njivi: eden bo vzet in eden puščen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 41, 'Dve bosta mleli na mlinu: ena bo vzeta in ena puščena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 42, 'Čujte torej, ker ne veste, katerega dne pride Gospod vaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 43, 'Vedite pa to: ko bi hišni gospodar vedel, ob kateri straži pride tat, bi čul in ne bi dal podkopati hiše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 44, 'Zato bodite tudi vi pripravljeni; kajti Sin človekov pride ob uri, ko se vam ne zdi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 45, 'Kdo neki je zvesti in modri hlapec, ki ga je postavil gospodar njegov nad svojimi posli, da jim daje hrano o pravem času?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 46, 'Blagor tistemu hlapcu, ki ga najde gospodar njegov, kadar pride, da tako dela!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 47, 'Resnično vam pravim, da ga postavi nad vsem premoženjem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 48, 'Ako pa reče ta hudobni hlapec v srcu svojem: Gospodar moj odlaša prihod svoj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 49, 'ter začne pretepati sohlapce svoje, s pijanci pa pojeda in popiva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 50, 'pride gospodar tega hlapca v dan, kadar ne pričakuje, in ob uri, katere ne ve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 24, 51, 'in ga preseka in mu da delež s hinavci: tam bode jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 1, 'Tedaj bode nebeško kraljestvo podobno desetim devicam, ki so vzele svetilnice svoje in šle ženinu naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 2, 'Pet pa jih je bilo nespametnih in pet modrih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 3, 'Zakaj tiste nespametne so vzele svetilnice svoje, olja pa niso vzele s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 4, 'Modre pa so vzele olje v posodah svojih s svetilnicami vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 5, 'Ko se je pa ženin mudil, so vse podremale in zaspale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 6, 'Opolnoči pa nastane hrup: Glej, ženin! Pojdite mu naproti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 7, 'Tedaj vstanejo vse te device in olepšajo svetilnice svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 8, 'Nespametne pa reko modrim: Dajte nam olja svojega, ker naše svetilnice gasnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 9, 'Modre jim pa odgovore in reko: Ne, da morda ne zmanjka nam in vam. Pa pojdite rajše k prodajalcem in si ga kupite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 10, 'Ko pa gredo kupovat, pride ženin, in tiste, ki so bile pripravljene, odidejo ž njim na svatovščino; in vrata se zapro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 11, 'Poslej pa pridejo tudi druge device, rekoč: Gospod, gospod, odpri nam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 12, 'On pa odgovori in reče: Resnično vam pravim, ne poznam vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 13, 'Čujte torej, ker ne veste ne dneva, ne ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 14, 'Kajti bo kakor človek, odpravljajoč se na pot, ki pokliče hlapce svoje in jim izroči premoženje svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 15, 'in dá enemu pet talentov, drugemu pa dva, a drugemu enega, vsakemu po njegovi zmožnosti; in odpotuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 16, 'Zdajci gre tisti, ki je prejel pet talentov, in kupčuje ž njimi, in pridobi drugih pet talentov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 17, 'Tako tudi tisti, ki je prejel dva, pridobi druga dva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 18, 'Tisti pa, ki je prejel enega, odide in ga zakoplje v zemljo in skrije srebro gospodarja svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 19, 'Čez mnogo časa pa pride gospodar teh hlapcev in napravi ž njimi račun.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 20, 'In pristopi tisti, ki je prejel pet talentov, in prinese pet drugih talentov, rekoč: Gospod, pet talentov si mi izročil; glej, pridobil sem ž njimi pet drugih talentov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 21, 'Reče mu gospod njegov: Dobro, vrli in zvesti hlapec, v malem si bil zvest, nad veliko te postavim; pojdi v gospoda svojega veselje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 22, 'Tudi tisti, ki je prejel dva talenta, pristopi in reče: Gospod, dva talenta si mi izročil, glej, pridobil sem ž njima dva druga talenta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 23, 'Reče mu gospod njegov: Dobro, vrli in zvesti hlapec, v malem si bil zvest, nad veliko te postavim; pojdi v gospoda svojega veselje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 24, 'Pristopi pa tudi tisti, ki je prejel en talent, in reče: Gospod, vedel sem, da si trd človek; žanješ, kjer nisi posejal, in pobiraš, kjer nisi raztresel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 25, 'in ker sem se bal, sem šel in skril talent tvoj v zemljo; glej, tu imaš, kar je tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 26, 'Gospodar njegov mu pa odgovori in reče: Hudobni in leni hlapec! vedel si, da žanjem, kjer nisem posejal, in pobiram, kjer nisem raztresel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 27, 'zato bi bil moral dati moje srebro menjalcem, in jaz bi bil po svojem prihodu prejel, kar je mojega, z obrestmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 28, 'Vzemite mu torej talent in dajte tistemu, ki ima deset talentov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 29, 'Kajti vsakemu, kdor ima, se bo dalo, in preobilo bo imel; onemu pa, ki nima, se vzame tudi to, kar ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 30, 'In nepridnega hlapca vrzite v zunanjo temo; tam bode jok in škripanje z zobmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 31, 'Kadar pa pride Sin človekov v slavi svoji in vsi angeli ž njim, tedaj bo sedel na prestol svoje slave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 32, 'In pred njim se zbero vsi narodi, in ločil jih bo enega od drugega, kakor loči pastir ovce od kozlov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 33, 'in postavi ovce sebi na desno, a kozle na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 34, 'Tedaj poreče Kralj tistim na desnici svoji: Pridite, blagoslovljeni Očeta mojega, podedujte kraljestvo, ki vam je pripravljeno od ustanovitve sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 35, 'Kajti lačen sem bil, in dali ste mi jesti; žejen sem bil, in dali ste mi piti; tujec sem bil, in vzeli ste me pod streho;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 36, 'nag, in oblekli ste me; bolan, in obiskali ste me; v ječi sem bil, in prišli ste k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 37, 'Tedaj mu odgovore pravični, rekoč: Gospod, kdaj smo te videli lačnega, in smo te nasitili? ali žejnega, in smo te napojili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 38, 'Kdaj smo te pa videli tujca, in smo te vzeli pod streho? ali nagega, in smo te oblekli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 39, 'Kdaj smo te pa videli bolnega ali v ječi, in smo prišli k tebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 40, 'In Kralj odgovori in jim reče: Resnično vam pravim, karkoli ste storili enemu teh najmanjših mojih bratov, ste storili meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 41, 'Tedaj poreče tudi tistim na levici: Pojdite od mene, prokleti, v večni ogenj, ki je pripravljen hudiču in angelom njegovim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 42, 'Kajti lačen sem bil, in niste mi dali jesti, žejen, in niste mi dali piti; tujec sem bil, in niste me vzeli pod streho;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 43, 'nag, in niste me oblekli; bolan in v ječi, in niste me obiskali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 44, 'Tedaj mu odgovore tudi oni, rekoč: Gospod, kdaj smo te videli lačnega, ali žejnega, ali tujca, ali nagega, ali bolnega, ali v ječi, in ti nismo postregli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 45, 'Nato jim odgovori, rekoč: Resnično vam pravim, česarkoli niste storili enemu teh najmanjših, niste meni storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 25, 46, 'In ti pojdejo v večno trpljenje, pravični pa v večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 1, 'In zgodi se, ko konča Jezus vse te govore, da reče učencem svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 2, 'Veste, da bo čez dva dni Velika noč, in Sin človekov bo izdan, da ga križajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 3, 'Tedaj se zbero višji duhovniki in starejšine ljudstva na dvoru velikega duhovnika, kateremu je bilo ime Kajfa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 4, 'in se posvetujejo, da bi Jezusa z zvijačo ujeli in umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 5, 'Rekli so pa: Ne na praznik, da se ljudstvo ne upre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 6, 'Ko pa je bil Jezus v Betaniji v hiši Simona gobavca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 7, 'pristopi k njemu žena, ki je imela alabastrovo posodo dragocenega mazila, in mu ga izlije na glavo, ko je sedel za mizo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 8, 'Ko pa učenci njegovi to vidijo, se razhudé, govoreč: Čemu ta potrata?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 9, 'To bi se bilo namreč lahko za mnogo prodalo in izkupilo se dalo ubogim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 10, 'Ko pa Jezus to opazi, jim reče: Kaj nadlegujete to ženo? saj je dobro delo storila na meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 11, 'Uboge namreč imate vselej pri sebi, mene pa nimate vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 12, 'Kajti s tem, da je izlila to mazilo na moje telo, me je pripravila za pokop.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 13, 'Resnično vam pravim: Kjerkoli po vsem svetu se bo oznanjal ta evangelij, se bo povedalo tudi to, kar je ona storila, njej v spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 14, 'Tedaj odide eden od dvanajsterih, ki mu je bilo ime Juda Iškariot, k višjim duhovnikom');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 15, 'in reče: Kaj mi hočete dati, in jaz vam ga izdam? Oni pa mu določijo trideset srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 16, 'In odslej je iskal priložnosti, da ga izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 17, 'Prvi dan presnih kruhov pa pristopijo učenci k Jezusu in mu reko: Kje hočeš, da ti pripravimo, da boš jedel velikonočno jagnje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 18, 'On pa reče: Pojdite v mesto k temu in k temu in recite mu: Učenik pravi: Čas moj je blizu; pri tebi bom jedel velikonočno jagnje z učenci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 19, 'In učenci store, kakor jim je Jezus ukazal, in pripravijo, velikonočno jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 20, 'Ko se pa zvečeri, sede za mizo z dvanajsterimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 21, 'In ko so jedli, reče: Resnično vam pravim, da me eden izmed vas izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 22, 'In zelo se užaloste, in ga začno vpraševati, drug za drugim: Ali sem jaz, Gospod?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 23, 'On pa odgovori in reče: Tisti, ki pomaka z menoj roko v skledo, ta me bo izdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 24, 'Sin človekov sicer gre, kakor je pisano o njem, ali gorje tistemu človeku, ki izdaja Sina človekovega! Bolje bi bilo tistemu človeku, da ne bi bil rojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 25, 'Juda pa, izdajalec njegov, odgovori in reče: Sem li mar jaz, Rabi? Reče mu: Ti si rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 26, 'Ko so pa jedli, vzame Jezus kruh, in blagoslovi in ga prelomi ter da učencem, rekoč: Vzemite, jejte; to je moje telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 27, 'In vzame kelih, se zahvali in jim da, rekoč: Pijte iz njega vsi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 28, 'kajti to je moja kri nove zaveze, ki se preliva za mnoge v odpuščenje grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 29, 'Pravim vam pa, da odslej ne bom pil tega trtnega sadu do tistega dne, ko ga bom pil z vami novega v kraljestvu Očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 30, 'In ko so odpeli zahvalnico, odidejo na Oljsko goro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 31, 'Tedaj jim reče Jezus: Vsi vi se boste pohujšali to noč nad menoj. Kajti pisano je: „Pastirja udarim, in razkrope se ovce črede“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 32, 'Po vstajenju svojem pa pojdem pred vami v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 33, 'Peter pa odgovori in mu reče: Če se vsi pohujšajo nad teboj, jaz se nikoli ne pohujšam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 34, 'Jezus mu reče: Resnično ti pravim, še to noč, preden zapoje petelin, me zatajiš trikrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 35, 'Peter mu pravi: In ko bi moral s teboj umreti, te gotovo ne zatajim. Tako govoré tudi vsi učenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 36, 'Tedaj pride ž njimi Jezus v ograd, ki se imenuje Getsemane, in reče učencem: Sedite tu dotlej, da grem tja in pomolim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 37, 'In vzemivši s seboj Petra in Zebedejeva dva sina, se začne žalostiti in trepetati groze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 38, 'Tedaj jim reče: Žalostna je duša moja do smrti; ostanite tukaj in čujte z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 39, 'In odšedši malo dalje, pade na obraz svoj in moli, govoreč: Oče moj, ako je mogoče, naj gre ta kelih mimo mene; toda ne kakor hočem jaz, ampak kakor ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 40, 'In pride k učencem in jih najde speče, ter reče Petru: Torej niste mogli ene ure z menoj prečuti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 41, 'Čujte in molite, da ne zajdete v izkušnjavo; duh je sicer voljan, ali meso je slabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 42, 'Zopet odide drugič in moli, govoreč: Oče moj, ako ne more ta kelih iti mimo mene, nego da ga pijem, zgodi se volja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 43, 'In ko se vrne, zopet jih najde speče, bile so jim namreč oči utrujene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 44, 'In pustivši jih, odide zopet in moli v tretje, govoreč zopet iste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 45, 'Potem pride k učencem svojim in jim reče: Spite dalje in počivajte! Glej, ura se je približala, in Sin človekov se izdaja grešnikom v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 46, 'Vstanite, pojdimo! Glejte, izdajalec moj je blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 47, 'In ko je še govoril, glej, pride Juda, eden dvanajsterih, in ž njim velika truma z meči in koli od višjih duhovnikov in starejšin ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 48, 'Izdajalec njegov pa jim je dal znamenje, rekši: Kogar poljubim, ta je: primite ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 49, 'In precej pristopi k Jezusu in reče: Zdrav bodi, učenik! in ga poljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 50, 'Jezus pa mu reče: Prijatelj, čemu si prišel! Tedaj pristopijo in polože roke na Jezusa in ga zgrabijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 51, 'In glej, eden tistih, ki so bili z Jezusom, iztegne roko in izdere meč svoj ter udari hlapca velikega duhovnika in mu odseka uho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 52, 'Tedaj mu veli Jezus: Vtakni meč svoj na mesto njegovo; kajti vsi, ki primejo za meč, z mečem poginejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 53, 'Ali pa meniš, da ne morem prositi Očeta svojega, in poslal bi mi takoj več nego dvanajst legijonov angelov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 54, 'Kako bi se pa izpolnila pisma, ki pričajo, da mora tako biti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 55, 'V tej uri reče Jezus ljudstvu: Kakor na razbojnika ste prišli z meči in koli, da bi me ujeli! Vsak dan sem sedel pri vas, učeč v templju, in niste me prijeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 56, 'Toda vse to se je zgodilo, da se izpolnijo pisma prorokov. Tedaj ga vsi učenci zapusté in pobegnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 57, 'Tisti pa, ki so Jezusa prijeli, ga odpeljejo k velikemu duhovniku Kajfu, kjer so se zbrali pismarji in starejšine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 58, 'A Peter gre oddaleč za njim do dvora velikega duhovnika in, stopivši noter, sede k služabnikom, da vidi konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 59, 'Višji duhovnik in ves veliki zbor so pa iskali krivega pričevanja zoper Jezusa, da bi ga izročili smrti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 60, 'a ne najdejo ga, dasi pristopi mnogo lažnivih prič. Naposled pa pristopita dva');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 61, 'in rečeta: Ta je rekel: Jaz morem podreti svetišče Božje in ga v treh dneh sezidati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 62, 'In veliki duhovnik vstane in mu reče: Ne odgovarjaš li ničesar? Kaj pričajo ti zoper tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 63, 'Jezus pa je molčal. In veliki duhovnik mu reče: Zaklinjam te pri živem Bogu, povej nam, ali si ti Kristus, Sin Božji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 64, 'Jezus mu reče: Ti si rekel. Toda pravim vam: Odslej boste videli Sina človekovega, da sedi na desnici moči Božje in da prihaja na nebeških oblakih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 65, 'Tedaj raztrga veliki dihovnik oblačila svoja, rekoč: Boga je proklel; kaj nam je še treba prič? Glejte, ravnokar ste slišali kletvino njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 66, 'Kaj se vam zdi? Oni pa odgovore in reko: Smrti je vreden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 67, 'Tedaj mu pljujejo v obraz in ga bijejo s pestmi; a drugi ga tolčejo po licu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 68, 'govoreč: Prorokuj nam, Kristus! Kdo je, ki te je udaril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 69, 'Peter pa je sedel zunaj na dvorišču. Pa pristopi k njemu neka dekla in reče: Tudi ti si bil z Jezusom Galilejcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 70, 'On pa zataji pred vsemi, rekoč: Ne vem, kaj praviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 71, 'Ko pa gre ven v vežo, ga ugleda druga in reče tistim, ki so bili tam: Tudi ta je bil z Jezusom Nazarečanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 72, 'In zopet zataji s prisego: Ne poznam tega človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 73, 'Malo potem pa pristopijo tisti, ki so tu stali, in reko Petru: Resnično, tudi ti si izmed njih, saj te že govorica tvoja izdaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 74, 'Tedaj se začne rotiti in prisegati: Ne poznam tega človeka. In precej zapoje petelin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 26, 75, 'In Peter se spomni besede Jezusove, ki mu je bil rekel: Preden petelin zapoje, me zatajiš trikrat. In gre ven in se bridko razjoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 1, 'Ko pa napoči jutro, se posvetujejo vsi višji duhovniki in starejšine ljudstva zoper Jezusa in sklenejo, da ga izroče smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 2, 'In ga zvežejo in odpeljejo ter izroče deželnemu poglavarju Pilatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 3, 'Tedaj se Juda, izdajalec njegov, videč, da so ga obsodili, skesa in vrne trideset srebrnikov višjim duhovnikom in starejšinam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 4, 'rekoč: Grešil sem, da sem izdal nedolžno kri. Oni pa reko: Kaj nam mar? Ti glej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 5, 'In vrže srebrnike v svetišče in pobegne; ter odide in se obesi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 6, 'Višji duhovniki pa vzemo srebrnike in reko: Ne smemo jih dejati v tempeljski zaklad, ker so krvav denar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 7, 'Posvetovali so se pa in kupili zanje lončarjevo njivo za pokopališče tujcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 8, 'Zato se imenuje tista njiva ‚Krvava njiva‘do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 9, 'Tedaj se je izpolnilo, kar je rečeno po proroku Jeremiju, ki pravi: „In vzeli so trideset srebrnikov, ceno cenjenega, ki so ga cenili nekateri sinov Izraelovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 10, 'in so jih dali za lončarjevo polje, kakor mi je naročil Gospod“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 11, 'A Jezus je stal pred poglavarjem. In vpraša ga poglavar, rekoč: Si ti kralj Judov? Jezus pa mu reče: Ti praviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 12, 'In ko ga višji duhovniki in starejšine tožijo, ne odgovori ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 13, 'Tedaj mu reče Pilat: Ne slišiš li, kaj vse zoper tebe pričajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 14, 'In ni mu odgovoril ne na eno besedo, da se je poglavar zelo čudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 15, 'Na praznik pa je imel poglavar navado, da je izpustil ljudstvu enega jetnika, katerega so hoteli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 16, 'Imeli so pa takrat glasovitega jetnika, ki mu je bilo ime Baraba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 17, 'Ko se torej zbero, jim reče Pilat: Katerega hočete, da vam izpustim? Baraba ali Jezusa, ki se imenuje Kristus?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 18, 'Kajti vedel je, da so mu ga izdali iz zavisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 19, 'Ko pa sedi na sodnem stolu, pošlje k njemu žena njegova, rekoč: Ničesar ne imej opraviti s tem pravičnim, kajti veliko sem pretrpela danes v spanju zavoljo njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 20, 'A višji duhovniki in starejšine pregovore množice, naj zahtevajo Baraba, Jezusa pa pogube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 21, 'Poglavar pa izpregovori in reče: Katerega teh dveh hočete, da vam izpustim? Oni pa reko: Baraba!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 22, 'Reče jim Pilat: Kaj naj storim z Jezusom, ki se imenuje Kristus? Vsi mu reko: Križaj ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 23, 'Poglavar pa reče: Kaj pa je hudega storil? Oni pa še bolj vpijejo: Križaj ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 24, 'Ko torej Pilat vidi, da nič ne opravi, ampak da nastaja še večji hrup, vzame vode in si umije roke pred ljudstvom, rekoč: Nedolžen sem pri krvi tega pravičnega. Vi glejte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 25, 'In vse ljudstvo odgovori in reče: Kri njegova pridi na nas in na naše otroke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 26, 'Tedaj jim izpusti Baraba; Jezusa pa, ko ga je dal bičati, izroči, naj ga križajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 27, 'Tedaj vzemo poglavarjevi vojščaki Jezusa v sodno palačo in zbero zoper njega vso trumo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 28, 'in ga slečejo in mu oblečejo škrlaten plašč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 29, 'In spleto krono iz trnja in mu jo denejo na glavo in trst v desnico njegovo, ter poklekujejo pred njim in ga zasramujejo, govoreč: Zdrav bodi, kralj Judov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 30, 'In pljujejo nanj in vzemo trst in ga bijejo po glavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 31, 'In ko se mu nasmejajo, mu slečejo plašč in mu oblečejo njegovo obleko; ter ga odpeljejo, da ga križajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 32, 'Gredoč pa iz mesta, naleté na človeka iz Cirene, po imenu Simona; tega prisilijo, naj mu ponese križ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 33, 'In ko pridejo na mesto, ki se imenuje Golgota, kar se pravi: Mesto mrtvaške glave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 34, 'mu dado piti vina, mešanega z žolčem; in ko je okusil, ni hotel piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 35, 'Ko ga pa razpno na križ, si razdele obleko njegovo, metaje kocko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 36, 'In sedejo tam in ga stražijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 37, 'In denejo mu nad glavo krivdo njegovo napisano: TA JE JEZUS, KRALJ JUDOV.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 38, 'Tedaj križajo ž njim dva razbojnika, enega na desno in enega na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 39, 'A mimohodeči so ga preklinjali, majoč z glavami svojimi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 40, 'in govoreč: Ti, ki podiraš svetišče in ga v treh dneh postavljaš, pomagaj sam sebi! Če si Sin Božji, stopi s križa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 41, 'Enako so ga pa zasramovali tudi višji duhovniki s pismarji in s starejšinami in govorili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 42, 'Drugim je pomagal, sam sebi ne more pomagati. Kralj Izraelov je, naj stopi sedaj s križa, in verovali mu bomo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 43, 'Zaupal je v Boga, naj ga reši sedaj, če ga ima rad; saj je rekel: Sin Božji sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 44, 'Ravno tako sta ga zasramovala tudi razbojnika, ki sta bila ž njim križana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 45, 'Od šeste ure pa nastane tema po vsej zemlji do devete ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 46, 'A okoli devete ure zavpije Jezus z močnim glasom, rekoč: Eli, Eli, lama sabahtani? to je: Bog moj, Bog moj, zakaj si me zapustil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 47, 'In ko slišijo to nekateri tistih, ki so tam stali, reko: Ta kliče Elija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 48, 'In precej pohiti eden izmed njih in vzame gobo in jo namoči z octom in natakne na trst, ter mu daje piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 49, 'Drugi pa pravijo: Pusti, da vidimo, če pride Elija in ga reši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 50, 'Jezus pa zopet zavpije z močnim glasom in izdahne duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 51, 'In glej, zagrinjalo v svetišču se pretrga na dvoje od vrha do tal; in zemlja se potrese, in skale se razpokajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 52, 'in grobi se odpro in mnoga trupla svetnikov, ki so bili zaspali, se obude,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 53, 'in izšedši iz grobov po vstajenju njegovem, pridejo v sveto mesto in se prikažejo mnogim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 54, 'Stotnik pa in kateri so ž njim stražili Jezusa, videč potres in kar se je godilo, se zelo prestrašijo in reko: Resnično je bil ta Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 55, 'Bile so pa tam in so oddaleč gledale mnoge žene. Te so bile prišle za Jezusom iz Galileje in so mu stregle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 56, 'Med njimi je bila Marija Magdalena in Marija, Jakobova in Jozejeva mati, in mati Zebedejevih sinov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 57, 'Ko se je pa zvečerilo, pride bogat človek iz Arimateje, po imenu Jožef, ki je bil tudi sam Jezusov učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 58, 'Ta pristopi k Pilatu in prosi za Jezusovo truplo. Tedaj zapove Pilat, naj mu ga izroče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 59, 'In Jožef vzame Jezusovo truplo in ga zavije v čisto platno');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 60, 'in ga položi v novi svoj grob, ki ga je bil izsekal v skali, in privalivši velik kamen grobu na vrata, odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 61, 'Bila je pa tam Marija Magdalena in druga Marija, sedeč grobu nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 62, 'Drugi dan pa, ki je za dnem pripravljanja, se zbero višji duhovniki in farizeji pri Pilatu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 63, 'govoreč: Gospod, spomnili smo se, da je ta slepar, ko je še živel, dejal: Čez tri dni vstanem od smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 64, 'Zapovej torej, naj se grob zavaruje do tretjega dne, da morda ne pridejo učenci njegovi in ga ukradejo ter reko ljudstvu: Vstal je od mrtvih; in zadnje sleparstvo bo hujše od prvega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 65, 'Pilat pa jim reče: Vzemite stražo, pojdite, dobro zavarujte, kakor veste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 27, 66, 'Oni pa odidejo in ko zapečatijo kamen, zavarujejo grob s stražo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 1, 'Po sobotnem večeru pa, ko se je svital prvi dan tedna, pride Marija Magdalena in druga Marija, da pogledata na grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 2, 'In glej, velik potres nastane; zakaj angel Gospodov je prišel z neba in pristopivši odvali kamen od vrat in sede nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 3, 'Bilo je pa obličje njegovo kakor blisk in obleka njegova bela kakor sneg.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 4, 'In od strahu pred njim strepetajo stražniki in postanejo kakor mrtvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 5, 'Angel pa izpregovori in reče ženam: Ne bojte se! vem, da iščete Jezusa križanega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 6, 'Ni ga tu; vstal je namreč, kakor je rekel. Pridite in poglejte mesto, kjer je ležal Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 7, 'In pojdite hitro in povejte učencem njegovim, da je vstal od mrtvih; in glejte, pred vami gre v Galilejo, tam ga boste videli. Glejte, povedal sem vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 8, 'In naglo zapuste grob s strahom in z velikim veseljem in teko, da sporoče učencem njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 9, 'In glej, Jezus jim pride naproti in reče: Pozdravljene! One pa pristopijo in se oklenejo nog njegovih ter ga molijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 10, 'Tedaj jim reče Jezus: Ne bojte se! Pojdite, sporočite bratom mojim, naj gredo v Galilejo, in tam me bodo videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 11, 'Medtem pa, ko gredo, glej, pridejo nekateri od straže v mesto in naznanijo višjim duhovnikom vse, kar se je bilo zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 12, 'In oni se zbero s starejšinami in se posvetujejo, ter dado vojakom mnogo denarja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 13, 'rekoč: Recite, da so prišli po noči učenci njegovi in so ga ukradli, ko smo mi spali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 14, 'In če to izve deželni poglavar, pomirimo ga mi, da bodete vi brez skrbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 15, 'Oni pa vzemo denar in storé, kakor so bili poučeni. In razglašena je ta beseda pri Judih do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 16, 'Enajsteri učenci pa odidejo v Galilejo na goro, kamor jim je bil Jezus ukazal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 17, 'In ko ga ugledajo, ga molijo; nekateri pa dvomijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 18, 'In pristopi Jezus ter jim govori in reče: Dana mi je vsa oblast v nebesih in na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 19, 'Pojdite torej in pridobivajte mi v učence vse narode, krščujoč jih v ime Očeta in Sina in svetega Duha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (40, 28, 20, 'učeč jih, naj izpolnjujejo vse, karkoli sem vam zapovedal. In glejte, jaz sem z vami vse dni do konca sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 1, 'Začetek evangelija Jezusa Kristusa, Sina Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 2, 'Kakor je pisano v proroku Izaiju: „Glej, pošiljam angela svojega pred obličjem tvojim, ki pripravi pot tvojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 3, 'Glas vpijočega v puščavi: Pripravite pot Gospodov, poravnajte steze njegove“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 4, 'tako je nastopil Janez Krstnik v puščavi, oznanjujoč krst izpokorjenja v odpuščenje grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 5, 'In k njemu je prihajala vsa Judejska dežela in vsi Jeruzalemci, in krstil jih je v reki Jordanu, pripoznavajoče grehe svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 6, 'Bil je pa Janez oblečen v velblodjo dlako in usnjen pas je imel okoli ledja svojega, in jedel je kobilice in divji med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 7, 'In propovedoval je, govoreč: Močnejši od mene gre za menoj, kateremu nisem vreden, sklonivši se, odvezati jermenov na obuvalu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 8, 'Jaz sem vas krstil z vodo, ali on vas bo krstil s svetim Duhom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 9, 'In zgodi se tiste dni, da pride Jezus iz Nazareta v Galileji, in Janez ga krsti v Jordanu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 10, 'In precej, ko stopi iz vode, zagleda, da se odpirajo nebesa, in Duh kakor golob gre navzdol nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 11, 'In glas se začuje iz nebes: Ti si Sin moj ljubljeni, ti si po moji volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 12, 'In precej ga odvede Duh v puščavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 13, 'In v puščavi je bil štirideset dni, in satan ga je izkušal, in bival je med zvermi; in angeli so mu stregli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 14, 'Ko so pa Janeza izročili Herodu, pride Jezus v Galilejo, oznanjujoč evangelij Božji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 15, 'in govoreč: Čas je dopolnjen in Božje kraljestvo se je približalo. Izpokorite se in verujte v evangelij!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 16, 'Hodeč ob Galilejskem morju, pa ugleda Simona in Andreja, njegovega brata, da mečeta mreže v morje; bila sta namreč ribiča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 17, 'In reče jima Jezus: Pojdita za menoj, in naredim, da postaneta lovca ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 18, 'In popustita precej mreže svoje ter gresta za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 19, 'In prišedši malo dalje, ugleda Jakoba, sina Zebedejevega, in njegovega brata Janeza; tudi ona popravljata v ladji mreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 20, 'In precej ju pokliče, in popustita svojega očeta Zebedeja v ladji z najemniki in odideta za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 21, 'In pridejo v Kafarnavm; in precej v soboto gre v shodnico in uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 22, 'In oni ostrme ob nauku njegovem, kajti uči jih, kakor kdor ima oblast in ne kakor pismarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 23, 'In precej se pokaže, da je v njih shodnici človek, ki ima nečistega duha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 24, 'ta zavpije, rekoč: Kaj imaš z nami, Jezus Nazareški? Prišel si, da nas pogubiš? Poznam te, kdo si: Svetnik Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 25, 'In zapreti mu Jezus, rekoč: Umolkni in izidi iz njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 26, 'In nečisti duh ga strese in zakriči z močnim glasom ter izide iz njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 27, 'In vsi se prestrašijo, tako da vprašujejo drug drugega, govoreč: Kaj je to? Kakšen nov nauk! Z oblastjo ukazuje tudi nečistim duhovom, pa so mu pokorni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 28, 'In precej se raznese glas o njem povsod po vsej Galilejski pokrajini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 29, 'In precej gredo iz shodnice in pridejo v hišo Simonovo in Andrejevo z Jakobom in Janezom vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 30, 'Tašča Simonova pa je ležala mrzlična, in precej mu povedo o njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 31, 'In pristopi, jo prime za roko ter vzdigne, in mrzlica jo pusti, in ona jim je stregla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 32, 'Zvečer pa, ko je solnce zatonilo, so prinašali k njemu vse bolnike in obsedence.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 33, 'In vse mesto je bilo zbrano pri vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 34, 'In ozdravil je mnogo bolnikov različnih bolezni in zlih duhov je mnogo izgnal ter ni dovolil govoriti zlim duhovom, ker so ga poznali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 35, 'In zjutraj, ko je še tema bila, vstane in gre ven ter odide na samoten kraj in tam moli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 36, 'In za njim pohiti Simon in kateri so bili ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 37, 'in ko ga najdejo, mu reko: Vsi te iščejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 38, 'In jim reče: Pojdimo drugam, v bližnje trge, da bom tudi tam propovedoval, kajti zato sem prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 39, 'Ter gre in propoveduje v njih shodnicah po vsej Galileji in izganja zle duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 40, 'In pride k njemu gobavec, ga klečé prosi in mu reče: Če hočeš, me moreš očistiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 41, 'In Jezus, ganjen usmiljenja, iztegne roko svojo in se ga dotakne ter mu reče: Hočem, bodi očiščen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 42, 'In mu precej preide goba in bil je čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 43, 'In ostro mu zapretivši, ga precej odpošlje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 44, 'in mu veli: Glej, da nikomur nič ne poveš, temuč pojdi, pokaži se duhovnikom in daruj za očiščenje svoje, kar je ukazal Mojzes, njim v pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 1, 45, 'On pa, ko izide, začne z vnemo oznanjevati in razglašati reč, tako da ni mogel Jezus nič več očitno priti v mesto, ampak je bival zunaj po samotnih krajih; in prihajali so k njemu od vseh strani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 1, 'In ko pride čez nekoliko dni zopet v Kafarnavm, začujejo, da je doma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 2, 'In precej se jih zbere mnogo, toliko, da niso imeli prostora tudi pred vrati ne. In govoril jim je besedo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 3, 'Pa pridejo in prineso k njemu mrtvoudnega, ki so ga štirje nosili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 4, 'In ko se mu niso mogli približati zavoljo množice, odkrijejo streho, kjer je bil; in ko so jo predrli, spuste doli posteljo, na kateri je mrtvoudni ležal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 5, 'Ko pa vidi Jezus njih vero, reče mrtvoudnemu: Sin, odpuščeni so ti grehi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 6, 'Tam pa je sedelo nekaj pismarjev, ki so premišljali v srcih svojih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 7, 'Kaj ta tako govori? Boga preklinja! Kdo more odpuščati grehe, razen eden, Bog?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 8, 'In spoznavši precej z duhom svojim, da tako premišljajo sami pri sebi, jim reče Jezus: Kaj to premišljate v srcih svojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 9, 'Kaj je laže, reči mrtvoudnemu: Odpuščeni so ti grehi, ali reči: Vstani in vzemi posteljo svojo in hodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 10, 'Da boste pa vedeli, da ima Sin človekov oblast, na zemlji odpuščati grehe (veli mrtvoudnemu):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 11, 'Tebi pravim: Vstani, vzemi posteljo svojo in pojdi na dom svoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 12, 'In vstane in precej vzame posteljo ter odide vpričo vseh, da se vsi čudijo in Boga hvalijo, govoreč: Nikoli nismo kaj takega videli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 13, 'In zopet odide k morju. In vse ljudstvo je prihajalo k njemu, in jih je učil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 14, 'In mimogrede ugleda Levija, sina Alfejevega, sedečega na mitnici, in mu reče: Pojdi za menoj! In vstane in gre za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 15, 'In zgodi se, ko je sedel za mizo v hiši njegovi, da je tudi mnogo cestninarjev in grešnikov sedelo z Jezusom in njegovimi učenci; kajti veliko jih je bilo, in so hodili za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 16, 'In ko pismarji in farizeji vidijo, da jé s cestninarji in grešniki, reko učencem njegovim: Z mitarji in grešniki jé in pije!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 17, 'In ko Jezus to sliši, jim reče: Zdravi ne potrebujejo zdravnika, ampak bolni. Nisem prišel klicat pravičnih, ampak grešnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 18, 'Učenci Janezovi in farizeji pa so se postili; ter pridejo in mu reko: Zakaj se Janezovi in farizejski učenci postijo, tvoji učenci se pa ne postijo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 19, 'In Jezus jim reče: Ali se morejo svatje postiti, kadar je ženin ž njimi? Dokler imajo s seboj ženina, se ne morejo postiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 20, 'Pridejo pa dnevi, ko se jim odvzame ženin; in tedaj se bodo postili tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 21, 'Nihče ne prišiva zaplate iz novega sukna na staro oblačilo, sicer odtrga nova zaplata še kaj od starega in luknja se naredi še hujša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 22, 'In nihče ne deva novega vina v stare mehove, sicer predere novo vino mehove, in vino pride v nič in tudi mehovi; temuč novo vino je vlivati v nove mehove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 23, 'In zgodi se, da je šel v soboto skozi setve, in učenci njegovi začno po poti grede trgati klasje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 24, 'Pa mu reko farizeji: Glej, kaj delajo v soboto, kar se ne sme?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 25, 'In jim reče: Niste li nikoli brali, kaj je storil David, ko je bil v sili in lačen, on in kateri so bili ž njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 26, 'Kako je šel v hišo Božjo, ko je bil Abiatar veliki duhovnik, in je jedel predložene kruhe, ki jih ne sme nihče jesti razen duhovnikov, in je dal tudi tistim, ki so bili ž njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 27, 'In jim reče: Sobota je ustvarjena zaradi človeka, a ne človek zaradi sobote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 2, 28, 'Zato je Sin človekov tudi sobote gospodar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 1, 'In zopet pride v shodnico, in tam je bil človek, ki je imel usehlo roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 2, 'In pazili so nanj, če ga ozdravi v soboto, da bi ga zatožili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 3, 'In reče človeku, ki je imel suho roko: Stopi na sredo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 4, 'In jim reče: Ali se sme v soboto storiti dobro ali hudo? življenje oteti ali pogubiti? Oni pa molčijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 5, 'In jih z jezo pogleda naokrog, pomilujoč zakrknjenost njih srca, in veli človeku: Iztegni roko svojo! In iztegne, in roka njegova je bila zdrava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 6, 'In farizeji izidejo in se precej s Herodovci posvetujejo zoper njega, kako bi ga pogubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 7, 'A Jezus se umakne z učenci svojimi k morju; in velika množica iz Galileje je šla za njim; tudi iz Judeje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 8, 'in iz Jeruzalema in iz Idumeje in z one strani Jordana in od Tira in Sidona, velika množica, ko so slišali, kakšne reči dela, so prišli k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 9, 'In reče učencem svojim, naj mu bode ladjica pripravljena zavoljo množice, da ga ne bi stiskali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 10, 'Kajti mnogo jih je bil ozdravil, zato so se rinili k njemu, da bi se ga doteknili, katerikoli so imeli nadloge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 11, 'In kadar so ga nečisti duhovi videli, so padali pred njim in kričali, govoreč: Ti si Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 12, 'In zelo jim je pretil, naj ga ne razglašajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 13, 'In stopi na goro in pokliče k sebi, katere je sam hotel; in pridejo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 14, 'In postavi jih dvanajst, da bodo ž njim in da jih pošlje propovedovat');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 15, 'ter da imajo oblast izganjati zle duhove:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 16, 'Simona, in mu dá ime Peter,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 17, 'in Jakoba, sina Zebedejevega, in Janeza, brata Jakobovega, in da jima ime Boanerges, to je: sinova groma,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 18, 'in Andreja in Filipa in Jerneja in Matevža in Tomaža in Jakoba, sina Alfejevega, in Tadeja in Simona Kananejca');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 19, 'in Juda Iškariota, ki ga je tudi izdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 20, 'In pridejo v hišo. In zopet se zbere množica, tako da še kruha niso mogli jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 21, 'In ko to slišijo sorodniki njegovi, se napotijo, da bi ga prijeli; pravijo namreč: Ni sam ob sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 22, 'In pismarji, ki so bili prišli iz Jeruzalema, pravijo: Belzebuba ima, in: S poglavarjem hudičev izganja zle duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 23, 'In jih pokliče k sebi in jim govori v prilikah: Kako more satan satana izganjati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 24, 'In če se kraljestvo razdvoji samo zoper sebe, ne more obstati to kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 25, 'In če se dom razdvoji sam zoper sebe, ne bo mogel obstati ta dom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 26, 'In če je vstal satan sam zoper sebe in se je razdvojil, ne more obstati, temuč konec ga je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 27, 'Nasprotno ne more iti nihče v hišo močnemu in mu pobrati pohištva, če poprej ne zveže močnega, in potem šele opleni hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 28, 'Resnično vam pravim, da se vsi grehi odpuste sinovom človeškim, tudi kletvine, s katerimikoli bi prekleli Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 29, 'kdor pa prekolne svetega Duha, nima odpuščenja na vekomaj, temuč je kriv večnega greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 30, 'Kajti govorili so: Nečistega duha ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 31, 'In pridejo bratje njegovi in mati njegova in stoječ zunaj, pošljejo k njemu, da ga pokličejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 32, 'In ljudstvo sedi okoli njega, in mu reko: Glej, mati tvoja in bratje tvoji zunaj vprašujejo po tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 33, 'In odgovori jim, rekoč: Kdo je mati moja ali bratje moji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 34, 'In ozre se okrog po tistih, ki so sedeli okoli njega, in reče: Glej, mati moja in bratje moji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 3, 35, 'Kdorkoli stori voljo Božjo, ta je brat moj in sestra moja in mati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 1, 'In zopet začne učiti ob morju. In zbere se pri njem tako velika množica, da mora stopiti v ladjo in sedeti v njej na morju; in vsa množica se razpostavi kraj morja po tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 2, 'In mnogo jih je učil v prilikah in jim pravil v poučevanju svojem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 3, 'Poslušajte! Glej, sejalec gre sejat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 4, 'In zgodi se, ko seje, da pade nekaj zrnja poleg ceste, in prilete ptice in ga pozobljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 5, 'A drugo pade na skalnata tla, kjer nima veliko prsti, in precej požene, ker nima globoke zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 6, 'Ko pa vzide solnce, uvene, in ker nima korenine, usahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 7, 'In drugo pade v trnje, in trnje vzraste in ga uduši, in ne prinese sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 8, 'In drugo pade na dobro zemljo, in prinaša sad, ki raste in se množi in rodi po tridesetero in po šestdesetero in po stotero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 9, 'In reče: Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 10, 'In ko je bil sam, ga vprašajo tisti, ki so bili pri njem z dvanajsterimi, po prilikah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 11, 'In jim reče: Vam je dana skrivnost kraljestva Božjega, onim pa, ki so zunaj, se vse godi v prilikah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 12, 'da „gledajoč vidijo, pa ne spoznajo, ter poslušajoč slišijo, pa ne razumejo: da se ne bi kdaj izpreobrnili, in bilo bi jim odpuščeno“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 13, 'In jim reče: Ne umete li te prilike? In kako boste vse prilike umeli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 14, 'Sejalec seje besedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 15, 'Ti so pa, ki so poleg ceste: kjer se seje beseda, in ko jo slišijo, precej pride satan in vzame besedo, ki je posejana vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 16, 'In enako so ti, pri katerih je posejano na skalnata tla: ko slišijo besedo, jo precej z veseljem sprejmo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 17, 'pa nimajo korenine v sebi, temuč so nestanovitni; ko potem nastane stiska ali preganjanje zaradi besede, se precej pohujšajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 18, 'In drugi so, pri katerih je posejano v trnje: tisti, ki besedo slišijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 19, 'pa skrbi tega sveta in slepilo bogastva in želje po drugih rečeh se prikradejo in zaduše besedo in ostane brez sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 20, 'In ti so, pri katerih je na dobro zemljo posejano: ki besedo poslušajo in sprejemajo ter prinašajo sad, trideseteren, šestdeseteren in stoteren.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 21, 'In jim reče: Se li mar prinaša sveča, da se postavi pod mernik ali pod posteljo? A ne, da se postavi na svečnik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 22, 'Kajti nič ni skritega, kar se ne bi razodelo, in nič ni tako skrivnega, da ne bi prišlo na svetlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 23, 'Če ima kdo ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 24, 'In jim reče: Pomislite, kaj slišite! S kakršno mero merite, se odmeri vam in še pridene se vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 25, 'Kajti kdor ima, se mu bo dalo, a kdor nima, se mu odvzame tudi to, kar ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 26, 'In reče: Tako je s kraljestvom Božjim, kakor če človek vrže seme v zemljo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 27, 'in spi in vstaja po noči in po dnevi, in seme poganja in raste, da on ne ve kako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 28, 'Zemlja sama od sebe rodi sad: najprej steblo, potem klas, potem polno pšenico v klasu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 29, 'Ko pa sad dozori, precej pošlje srp, kajti prišla je žetev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 30, 'In reče: S čim naj primerjamo kraljestvo Božje? ali v kakšni priliki naj ga upodobimo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 31, 'Ono je kakor gorčično zrno, ki je, ko se vseje v zemljo, manjše od vseh semen na zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 32, 'a ko je vsejano, raste in postane večje od vseh zelišč, in poganja velike veje, da morejo ptice nebeške gnezditi pod senco njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 33, 'In v mnogih takih prilikah jim je govoril besedo, v kolikor so jo mogli poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 34, 'Brez prilike pa jim ni govoril, a na samem je učencem svojim razlagal vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 35, 'In jim reče tisti dan, ko se je zvečerilo: Prepeljimo se na oni kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 36, 'In pusté množico ter ga vzemo s seboj, kakor je bil v ladji; tudi druge ladjice so bile ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 37, 'Kar nastane velik vihar, in valovi so se zaganjali v ladjo, da se je že napolnjevala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 38, 'In on je bil na krmi, speč na blazini; in ga zbude in mu reko: Učenik, ali ti nič ni mar, da pogibljemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 39, 'In prebudivši se, zapreti vetru in reče morju: Umolkni, pomiri se! In preneha veter, in nastane velika tihota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 40, 'In jim reče: Kaj ste tako plašni? ali še nimate vere?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 4, 41, 'In velik strah jih obide, in govore med seboj: Kdo vendar je ta, da sta mu celo veter in morje pokorna?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 1, 'In pridejo na drugo stran morja, v pokrajino Gerazenov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 2, 'In precej, ko stopi iz ladje, ga sreča človek iz grobov, ki je imel nečistega duha');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 3, 'in mu je bilo prebivališče po grobih; in tudi z verigo ga ni mogel nihče več zvezati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 4, 'bil je namreč velikokrat zvezan z oklepi in verigami, pa je verige potrgal in oklepe razdrobil, in nihče ga ni mogel ukrotiti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 5, 'in vedno, po noči in po dnevi, je bival po gorah in po grobih ter kričal in se bil s kamenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 6, 'Ko pa ugleda Jezusa oddaleč, priteče ter se mu prikloni');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 7, 'in na ves glas kričeč, reče: Kaj imam s teboj, Jezus, Sin Boga Najvišjega? Zaklinjam te pri Bogu, ne muči me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 8, 'Pravil mu je namreč: Izidi, nečisti duh, iz tega človeka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 9, 'In ga vpraša: Kako ti je ime? In mu reče: Legijon mi je ime, ker nas je mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 10, 'In prosi ga zelo, naj jih ne izžene iz tega kraja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 11, 'Bila je pa tam pri gori velika čreda svinj, ki so se pasle.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 12, 'In zaprosijo ga, rekoč: Pošlji nas v te svinje, da gremo vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 13, 'In Jezus jim dovoli. In nečisti duhovi izidejo in gredo v svinje, in zakadi se čreda, kakih dvatisoč, z brega v morje, ter potonejo v morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 14, 'In njih pastirji pobegnejo in oznanijo to v mestu in po deželi. In prebivalci gredo pogledat, kaj bi bilo to, kar se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 15, 'In pridejo k Jezusu in ugledajo obsedenca, da sedi in je oblečen in pameten, tistega, ki je imel legijon; in preplašijo se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 16, 'In tisti, ki so videli, jim pripovedujejo, kako se je zgodilo obsedencu, in o svinjah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 17, 'In začno ga prositi, naj odide iz njih krajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 18, 'In ko stopi v ladjo, ga zaprosi oni, ki je bil obseden, da sme ostati ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 19, 'Jezus pa mu ne dopusti, ampak mu reče: Pojdi na svoj dom k svojcem in oznani jim, koliko ti je storil Gospod in kako se te je usmilil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 20, 'In odide in začne oznanjevati po Deseteromestju, koliko mu je storil Jezus; in vsi so se čudili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 21, 'In ko se prepelje Jezus v ladji zopet na drugo stran, se zbere pri njem velika množica; in bil je pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 22, 'In glej, eden načelnikov shodnice, po imenu Jair, pride, in ko ga ugleda, mu pade pred noge');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 23, 'in ga zelo prosi, rekoč: Hčerka mi umira, pridi, položi nanjo roke, da ozdravi in živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 24, 'In odide ž njim; in velika množica ga spremlja in ga stiskajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 25, 'In žena, ki je imela krvotok dvanajst let');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 26, 'in je veliko pretrpela od mnogih zdravnikov in potrošila vse svoje, pa ji ni nič pomagalo, ampak še huje je bilo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 27, 'pride, ko je slišala o Jezusu, med množico odzadaj in se dotakne obleke njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 28, 'Reče si namreč: Če se dotaknem le obleke njegove, ozdravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 29, 'In precej usahne vir krvi njene, in čuti v telesu, da je ozdravela od svoje nadloge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 30, 'In Jezus precej spozna pri sebi, da je šla moč iz njega, in obrnivši se med množico, reče: Kdo se je dotaknil moje obleke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 31, 'In reko mu učenci njegovi: Saj vidiš ljudstvo, da te stiska, pa praviš: Kdo se me je dotaknil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 32, 'In ozira se okoli, da bi ugledal tisto, ki je to storila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 33, 'Žena pa, vedoč, kaj se ji je zgodilo, uplašena in trepetaje pristopi in pade pred njim in mu pove vso resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 34, 'On ji pa reče: Hči, vera tvoja te je rešila; pojdi v miru in bodi zdrava od nadloge svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 35, 'Ko še govori, pridejo od načelnika shodnice, rekoč: Hči tvoja je umrla, čemu še nadleguješ učenika?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 36, 'Jezus pa zasliši to besedo, ko so jo povedali, in reče načelniku shodnice: Ne boj se, le veruj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 37, 'In ne pusti, da bi ga kdo spremljal, razen Peter in Jakob in Janez, Jakobov brat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 38, 'In pridejo v hišo načelnikovo, in vidi hrupno zmešnjavo ter da silno jokajo in žalujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 39, 'In ko vnide, jim reče: Kaj hrumite in jokate? Deklica ni umrla, marveč spi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 40, 'A oni se mu posmehujejo. On pa izžene vse in vzame s seboj otrokovega očeta in mater in svoje spremljevalce ter gre noter, kjer je deklica ležala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 41, 'In prijemši deklico za roko, ji veli: Talita kumi, to se pravi: Deklica, pravim ti, vstani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 42, 'In precej vstane deklica in hodi; imela je namreč dvanajst let. In precej se začudijo na vso moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 5, 43, 'In zapove jim strogo, da nihče ne zve tega, in naroči, naj ji dado jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 1, 'In gre odtod in pride v domovino svojo, in spremljajo ga učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 2, 'In ko pride sobota, začne učiti v shodnici; in mnogi poslušalci so strmeli, govoreč: Odkod temu to? in: Kakšna je ta modrost, ki mu je dana? in toliki čudeži se vrše po rokah njegovih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 3, 'Ali ni ta tesar, sin Marijin in brat Jakobov in Jozejev in Judov in Simonov? in niso li sestre njegove tu pri nas? In pohujševali so se nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 4, 'Jezus jim pa reče: Nikjer ni prorok brez časti, razen v domovini svoji in pri rodbini svoji in na domu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 5, 'In ni mogel ondi nobenega čudeža storiti, razen da je le malo bolnikov, položivši nanje roke, ozdravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 6, 'In čudil se je njih neveri. In hodil je po vaseh v okolišu in učil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 7, 'In pokliče k sebi dvanajstere in jih začne razpošiljati po dva in dva, in da jim oblast nad nečistimi duhovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 8, 'in zapove jim, naj ničesar ne jemljo na pot razen same palice: ne torbe, ne kruha, ne denarja v pasu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 9, 'ampak da naj si obujejo opanke, in veli: ne oblačite dveh sukenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 10, 'In jim reče: Kjerkoli pridete v hišo, tam ostanite, dokler ne pojdete odondod naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 11, 'In v katerem mestu vas ne bi sprejeli in ne poslušali, odondod grede si otresite prah izpod nog njim v pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 12, 'In ko so odšli, so oznanjevali ljudem, naj se izpokore,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 13, 'in so izganjali mnoge zle duhove in mazali z oljem mnoge bolnike in jih ozdravljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 14, 'In kralj Herod zasliši o tem, kajti ime njegovo se je bilo razglasilo, in reče: Janez Krstnik je vstal iz mrtvih in zato delujejo čudežne moči v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 15, 'Drugi pa pravijo: Elija je; a drugi: prorok je, kakor eden izmed starih prorokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 16, 'Ko pa sliši to Herod, reče: Janez, ki sem ga jaz dal obglaviti, je vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 17, 'Kajti ta Herod je bil poslal ujet Janeza ter ga vklenil v ječi zavoljo Herodiade, svojega brata Filipa žene; bil se je ž njo namreč oženil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 18, 'Janez pa je dejal Herodu: Ni ti dovoljeno, imeti svojega brata ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 19, 'Herodiada pa ga je zalezovala in hotela umoriti, pa ga ni mogla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 20, 'Zakaj Herod se je bal Janeza, vedoč, da je pravičen in svet mož, ter ga je varoval; in marsikaj je storil, kakor mu je on rekel, in rad ga je poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 21, 'In je napočil prikladen dan: ko je Herod v spomin svojega rojstva napravil večerjo svojim velikašem in stotnikom in galilejskim prvakom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 22, 'je prišla noter njena, Herodiadina, hči in je plesala, ter se je prikupila Herodu in gostom. Kralj pa reče dekletu: Prosi me, karkoli hočeš, in dam ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 23, 'In ji priseže: Karkoli me poprosiš, ti dam, do polovice kraljestva svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 24, 'Ona pa gre ven in reče materi svoji: Kaj naj si izprosim? Ta pa reče: Glavo Janeza Krstnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 25, 'In gre precej jadrno h kralju in ga zaprosi, rekoč: Hočem, da mi daš pri tej priči v skledi glavo Janeza Krstnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 26, 'In kralj postane silno žalosten, toda zavoljo prisege in gostov ji ni hotel odreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 27, 'In precej pošlje kralj vojaka iz straže svoje in ukaže prinesti glavo njegovo. Ta pa odide in mu odseka v ječi glavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 28, 'in prinese glavo njegovo v skledi in jo da dekletu, a dekle jo da materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 29, 'In ko so to slišali učenci njegovi, pridejo in vzemo truplo njegovo ter ga polože v grob.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 30, 'In snidejo se apostoli pri Jezusu in mu sporočé vse, kar so storili in kar so ljudi naučili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 31, 'In jim reče: Pojdite sami na samoten kraj in malo počijte. Kajti bilo jih je veliko, ki so prihajali in odhajali, da še jesti niso utegnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 32, 'Ter odidejo na ladji v samoten kraj sami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 33, 'In mnogi jih vidijo odhajati, in ko spoznajo, kam so namenjeni, hitro odrinejo tja peš iz vseh mest in jih še prehité.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 34, 'In ko stopi Jezus z ladje, zagleda veliko množico, in se mu zasmilijo, zakaj bili so kakor ovce, ki nimajo pastirja. In začne jih učiti mnogo reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 35, 'In ko je bila ura že pozna, pristopijo k njemu učenci njegovi in reko: Kraj je samoten in ura že pozna;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 36, 'razpusti jih, da odidejo v dvore in vasi, ki so naokoli, ter si kupijo kaj za jed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 37, 'On pa odgovori in jim reče: Dajte jim vi jesti. Pa mu reko: Ali naj gremo in kupimo za dvesto denarjev kruha ter jim damo jesti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 38, 'On jim pa reče: Koliko hlebov imate? Pojdite in poglejte! In ko so izvedeli, reko: Pet in dve ribi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 39, 'In jim ukaže, naj jih posadé vse zaporedoma, omizje za omizjem, po zeleni travi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 40, 'In posedejo v skupinah po sto in po petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 41, 'In vzame petere hlebe in tisti dve ribi in se ozre v nebo in jih blagoslovi, ter razlomi hlebe in podaje učencem svojim, naj polože prednje; tudi dve ribi razdeli vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 42, 'In vsi so jedli in se nasitili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 43, 'In pobrali so koscev dvanajst polnih košev in ostankov od rib.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 44, 'In bilo jih je, ki so jedli hlebe, kakih pet tisoč mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 45, 'In precej prisili učence svoje, naj stopijo v ladjo in se naprej prepeljejo proti Betsaidi, dokler on razpusti množico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 46, 'In poslovivši se od njih, odide na goro molit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 47, 'In ko se zvečeri, je ladja sredi morja in on sam na kopnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 48, 'In zagleda jih, da se mučijo z veslanjem; pihal jim je namreč veter nasproti. In okoli četrte straže po noči pride k njim, hodeč po morju; in hotel je iti mimo njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 49, 'Oni pa, videč ga, da hodi po morju, menijo, da je prikazen, in zakričé;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 50, 'vsi so ga namreč zagledali in se prestrašili. In precej jih ogovori in jim reče: Srčni bodite, jaz sem, ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 51, 'In stopi k njim v ladjo, in veter utihne. In presilno so se sami v sebi zavzemali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 52, 'kajti po tem, kar se je zgodilo pri hlebih, še niso prišli k spoznanju, temuč njih srce je odrevenelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 53, 'In ko se prepeljejo, pridejo na kopno v Genezaret in potisnejo ladjo h kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 54, 'In ko stopijo z ladje, ga ljudje precej spoznajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 55, 'ter obletajo vso tisto okolico in začno na posteljah prinašati bolnike tja, kjer so slišali, da biva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 6, 56, 'In kamorkoli je prišel, v vasi ali v mesta ali v sela, so po ulicah pokladali bolnike in ga prosili, da bi se smeli dotekniti le roba njegove obleke; in katerikoli so se ga doteknili, so ozdraveli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 1, 'In snidejo se pri njem farizeji in nekateri pismarji, ki so prišli iz Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 2, 'Ti so videli nekatere učencev njegovih, da jedo kruh z nečistimi, to je z neumitimi rokami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 3, 'Farizeji in vsi Judje namreč ne jedo, dokler si skrbno ne umijejo rok, izpolnjujoč izročilo starih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 4, 'in kadar pridejo s trga, ne jedo, dokler se ne umijejo; in mnogo drugih reči je, ki so jih sprejeli in jih izpolnjujejo: umivanje kupic in vrčev in kotlov in stolov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 5, 'In vprašajo ga farizeji in pismarji: Zakaj se učenci tvoji ne ravnajo po izročilu starih, ampak jedo kruh z nečistimi rokami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 6, 'On pa jim reče: Dobro je prorokoval Izaija o vas hinavcih, kakor je pisano: „To ljudstvo me z ustnicami spoštuje, njih srce pa je daleč od mene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 7, 'ali zastonj me časté, učeč nauke, zapovedi človeške“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 8, 'Opustivši zapoved Božjo, izpolnjujete postave človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 9, 'In jim reče: Lepo zametujete zapoved Božjo, da ohranite izročilo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 10, 'Mojzes namreč je rekel: „Spoštuj očeta svojega in mater svojo“in: „Kdor preklinja očeta ali mater, naj umre“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 11, 'Vi pa pravite: Če reče kdo očetu ali materi: S čimer bi ti jaz pomagal, bodi korban (to je: daritev) –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 12, 'njemu ne pustite ničesar več storiti očetu svojemu ali materi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 13, 'Tako podirate veljavo besede Božje z izročilom svojim, ki ste ga izročili; in mnogo temu podobnih reči počenjate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 14, 'In pokliče k sebi zopet ljudstvo ter jim reče: Poslušajte me vsi ter umejte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 15, 'Nič ne more človeka oskruniti, kar od zunaj prihaja vanj, marveč to, kar izhaja iz njega, oskrunja človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 16, 'Če ima kdo ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 17, 'In ko odide od ljudstva v hišo, ga vprašajo učenci njegovi o tej priliki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 18, 'Pa jim reče: Ali ste tudi vi tako nerazumni? Ne umete li, da ga vse to, kar od zunaj prihaja v človeka, ne more oskruniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 19, 'ker ne gre v srce njegovo, ampak v trebuh in izhaja ven. S tem je proglasil za čiste vse jedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 20, 'Reče pa: Kar iz človeka izhaja, to ga skruni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 21, 'Kajti od znotraj, iz srca človeškega, izhajajo hudobne misli, nečistosti, tatvine, uboji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 22, 'prešeštva, lakomnost, hudobnost, zvijača, požrešnost, nevoščljivo oko, preklinjanje Boga, napuh, nespametnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 23, 'Vse te hudobne reči izhajajo od znotraj in skrunijo človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 24, 'In vstane in odide odtod, v kraje tirske in sidonske. In ko je stopil v hišo, ni hotel, da bi kdo zvedel o njem, ali ni se mogel prikriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 25, 'Ampak precej, ko je slišala o njem, pride žena, katere hčerka je imela nečistega duha, in mu pade pred noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 26, 'Bila pa je žena Grkinja, Sirofeničanka po rodu. In ga prosi, naj izžene zlega duha iz njene hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 27, 'Jezus pa ji reče: Pusti, da se poprej nasitijo otroci; kajti ni lepo, da se vzame kruh otrokom in se vrže psičkom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 28, 'Ona pa odgovori in mu reče: Da, Gospod, tudi psički pod mizo jedo od drobtinic otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 29, 'In ji reče: Zavoljo te besede pojdi; zli duh je odšel iz tvoje hčere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 30, 'In odide na svoj dom ter najde otroka ležečega na postelji, in zli duh je bil odšel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 31, 'In zopet odide iz tirskih krajev in pride skozi Sidon h Galilejskemu morju sredi po pokrajini Deseteromestja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 32, 'In pripeljejo mu gluhega, ki je nerazločno govoril, ter ga prosijo, naj bi položil nanj roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 33, 'In vzame ga na stran od množice, mu položi prste svoje v ušesa in pljune in se dotakne jezika njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 34, 'in pogledavši na nebo, vzdihne in mu veli: Efata, to je: Odpri se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 35, 'In odpro se ušesa njegova in razveže se vez jezika njegovega, in razločno je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 36, 'In zapove jim, naj nikomur ne povedo; čim bolj jim je pa prepovedoval, tem bolj so razglaševali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 7, 37, 'In presilno so se čudili, govoreč: Vse je prav storil; tudi gluhe napravlja, da slišijo, in neme, da govoré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 1, 'Tiste dni, ko je bilo zopet vse polno ljudstva pri njem in niso imeli kaj jesti, pokliče Jezus učence svoje in jim reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 2, 'Ljudstvo se mi smili, ker že tri dni so pri meni in nimajo kaj jesti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 3, 'in če jih pustim lačne na njih dom, obnemorejo na poti; in nekateri od njih so prišli od daleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 4, 'Pa mu odgovore učenci: Odkod bi jih mogel kdo tu v puščavi nasititi s kruhom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 5, 'In vpraša jih: Koliko imate hlebov? Oni pa reko: Sedem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 6, 'In zapove ljudstvu, naj posedejo po tleh. In vzame sedmere hlebe, zahvali, prelomi in podaje učencem svojim, naj polože prednje; in oni polagajo pred ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 7, 'In imeli so nekaj ribic; in blagoslovi jih in reče, naj polože tudi te prednje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 8, 'In jedli so in se nasitili; in pobrali so ostanke koscev sedem košev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 9, 'Bilo jih je pa kake štiri tisoč. In jih razpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 10, 'In precej stopi v ladjo z učenci svojimi in pride v okraj Dalmanutski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 11, 'In farizeji izidejo in se začno ž njim prepirati, in so ga izkušali ter zahtevali od njega znamenje z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 12, 'In vzdihnivši v duhu svojem, reče: Kaj zahteva ta rod znamenja? Resnično vam pravim: Ne bo se dalo znamenje temu rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 13, 'In pusti jih ter stopi zopet v ladjo in odide na drugo stran.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 14, 'In pozabili so vzeti kruha in niso imeli več nego en hleb s seboj v ladji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 15, 'Naroča jim pa, govoreč: Glejte, varujte se kvasu farizejskega in kvasu Herodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 16, 'In premišljajo sami pri sebi in govore: To pravi, ker kruha nimamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 17, 'In ko Jezus to opazi, jim reče: Kaj premišljujete, da nimate kruha? ali še niste spoznali in še ne umejete? ali vam je še okamenelo srce?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 18, 'Oči imate, in ne vidite? ušesa imate, in ne slišite? in ne pomnite li?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 19, 'Ko sem pet hlebov razlomil med pet tisoč ljudi, koliko polnih košev ste nabrali drobtin? Reko mu: Dvanajst.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 20, 'Ko sem jih pa sedem med štiri tisoč, koliko polnih pletenic ste nabrali drobtin? In reko mu: Sedem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 21, 'In jim reče: Ali še ne umejete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 22, 'In pridejo v Betsaido. In pripeljejo mu slepca in ga prosijo, naj se ga dotakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 23, 'In prime slepca za roko in ga pelje ven iz vasi ter pljune v oči njegove, in položivši roke nanj, ga vpraša, če kaj vidi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 24, 'In izpregleda ter reče: Vidim ljudi, kajti kakor drevesa jih vidim, da okoli hodijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 25, 'Potem mu zopet položi roke na oči, in on vidi razločno, in je ozdravel in videl bistro vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 26, 'In ga odpravi na dom njegov, rekoč: Nikar ne hodi v vas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 27, 'In odide Jezus in učenci njegovi v vasi Cesareje Filipove, in po poti vpraša učence svoje, rekoč jim: Kdo pravijo ljudje, da sem jaz?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 28, 'Oni mu pa povedo, rekoč: Janez Krstnik, in drugi: Elija, drugi pa: eden od prorokov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 29, 'In jih vpraša: Kdo pa pravite vi, da sem jaz? Peter odgovori in mu reče: Ti si Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 30, 'In zapreti jim, naj nikomur ne pripovedujejo o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 31, 'In začne jih učiti, da mora Sin človekov mnogo pretrpeti in biti zavržen od starejšin in višjih duhovnikov in pismarjev in umorjen biti in v treh dneh od smrti vstati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 32, 'In to besedo je govoril prostosrčno. In Peter ga potegne na stran in ga začne odvračati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 33, 'On pa se obrne in pogleda učence svoje in zapreti Petru in reče: Poberi se od mene, satan! ker ne misliš, kar je Božjega, ampak kar je človeškega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 34, 'In pokliče ljudstvo z učenci svojimi ter jim reče: Kdor hoče za menoj iti, naj zataji samega sebe in vzame križ svoj nase in gre za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 35, 'Kajti kdorkoli hoče življenje svoje ohraniti, ga izgubi, kdor pa izgubi življenje svoje zaradi mene in evangelija, ta ga ohrani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 36, 'Kaj namreč pomaga človeku, če ves svet pridobi, duši svoji pa škoduje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 37, 'Kajti kaj more dati človek v zameno za dušo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 8, 38, 'Zakaj kdor se sramuje mene in besed mojih v tem prešeštnem in grešnem rodu, sramoval se bo tudi Sin človekov njega, kadar pride v slavi Očeta svojega s svetimi angeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 1, 'In jim reče: Resnično vam pravim, da so nekateri med tukaj stoječimi, ki ne bodo okusili smrti, dokler ne vidijo kraljestva Božjega, da je prišlo z močjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 2, 'In čez šest dni vzame Jezus Petra in Jakoba in Janeza in jih odpelje na visoko goro same posebe; in izpremeni se pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 3, 'In oblačila njegova postanejo bleščeča in zelo bela kakor sneg, kakor jih noben belilec na zemlji ne more ubeliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 4, 'In prikaže se jim Elija z Mojzesom, in pogovarjata se z Jezusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 5, 'In Peter izpregovori in reče Jezusu: Rabi, dobro nam je tu biti; pa naredimo tri šatore, tebi enega in Mojzesu enega in Eliju enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 6, 'Ni namreč vedel, kaj bi odgovoril, kajti bili so zelo uplašeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 7, 'In nastane oblak in jih obsenči, in glas pride iz oblaka: Ta je Sin moj ljubljeni; njega poslušajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 8, 'In nagloma se ozro in nikogar več ne vidijo razen Jezusa samega s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 9, 'Ko so pa stopali z gore, jim zapove, naj nikomur ne pripovedujejo, kar so videli, dokler Sin človekov ne vstane iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 10, 'In to besedo so ohranili, in vpraševali so med seboj, kaj bi to bilo: vstati iz mrtvih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 11, 'In vprašajo ga, rekoč: Saj pravijo pismarji, da mora Elija poprej priti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 12, 'On pa jim reče: Elija res pride poprej in uravna vse vnovič. A kako je pisano o Sinu človekovem, da mora mnogo pretrpeti in ga bodo za nič šteli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 13, 'Ali pravim vam, da je Elija že prišel, in so mu storili, karkoli so hoteli, kakor je pisano o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 14, 'In ko pridejo k učencem, ugledajo veliko množico okoli njih in pismarje, da se ž njimi prepirajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 15, 'In vsa množica se precej, ko ga ugleda, začudi, in hité k njemu in ga pozdravljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 16, 'In jih vpraša: Kaj se prepirate ž njimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 17, 'In eden iz množice odgovori: Učenik, pripeljal sem k tebi sina svojega, ki ima nemega duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 18, 'In kjerkoli ga zgrabi, ga meče, in on se peni in škriplje z zobmi, in se suši. Pa sem dejal učencem tvojim, naj ga izženo, a niso mogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 19, 'On pa jim odgovori in reče: O neverni rod, doklej bom z vami? doklej vas bom trpel? Pripeljite ga k meni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 20, 'In pripeljejo ga k njemu. Komaj ga pa duh ugleda, ga precej strese, da se zgrudi na tla ter se valja in peni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 21, 'In vpraša očeta njegovega: Koliko časa je, odkar se mu je to zgodilo? Ta pa reče: Od malih nog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 22, 'In mnogokrat ga vrže tudi v ogenj ali v vodo, da ga pogubi. Ali, če moreš kaj, usmili se nas in pomagaj nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 23, 'Jezus pa mu reče: Če moreš kaj! Vse je mogoče tistemu, ki veruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 24, 'Precej zavpije dečkov oče in s solzami reče: Verujem, Gospod, pomagaj neveri moji!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 25, 'Videč pa Jezus, da se steka ljudstvo, zapreti nečistemu duhu, rekoč mu: Duh nemi in gluhi, jaz ti ukazujem, zapusti ga in ne pridi več vanj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 26, 'In zakriči in ga močno strese in izide iz njega. In deček postane kakor mrtev, tako da mnogi pravijo, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 27, 'Jezus pa ga prime za roko in ga vzdigne; in vstal je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 28, 'In ko pride v hišo, ga vprašajo učenci njegovi na samem: Kako, da ga mi nismo mogli izgnati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 29, 'In reče jim: Ta rod ne more iziti z ničimer razen z molitvijo in postom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 30, 'In ko so se odpravili odtod, so šli skozi Galilejo, in ni hotel, da bi kdo zvedel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 31, 'Kajti učil je učence svoje in jim pravil: Sin človekov bo izdan v človeške roke, in umorili ga bodo; in ko bo umorjen, vstane tretji dan od smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 32, 'Oni pa niso umeli tega govora, a bali so se ga vprašati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 33, 'In pridejo v Kafarnavm. In ko so bili v hiši, jih vpraša: Kaj ste se po poti med seboj menili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 34, 'Oni pa molče; spotoma so se bili namreč med seboj prepirali, kdo da je največji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 35, 'In ko sede, pokliče dvanajstere in jim reče: Če kdo hoče biti prvi, bodi najzadnji od vseh in vsem služabnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 36, 'In vzame otročiča ter ga postavi v sredo mednje, in ga vzame v naročje in jim reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 37, 'Kdor sprejme enega takih otročičev v mojem imenu, mene sprejme, in kdor mene sprejme, ne sprejme mene, marveč njega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 38, 'Reče mu Janez: Učenik, videli smo nekoga, ki ne hodi za nami, da je z imenom tvojim izganjal hudiče, in smo mu zabranili, ker ne hodi za nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 39, 'Jezus mu pa reče: Ne branite mu, zakaj nikogar ni, ki bi storil čudež z imenom mojim in bi mogel brž slabo govoriti o meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 40, 'Kdor namreč ni zoper nas, je z nami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 41, 'Kajti kdorkoli vas napoji s kupico vode v imenu mojem, ker ste Kristusovi, resnično vam pravim, ne izgubi plačila svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 42, 'In kdor pohujša enega teh malih, ki verujejo v me, bi mu bilo bolje, da mu obesijo mlinski kamen na vrat in da ga vržejo v morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 43, 'In če te pohujšuje roka tvoja, odsekaj jo; bolje ti je brez roke priti v življenje nego imeti obe roki in oditi v pekel, v ogenj neugasljivi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 44, '§ kjer njih črv ne umira in ogenj ne ugasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 45, 'In če te noga tvoja pohujšuje, odsekaj jo; bolje ti je hromemu priti v življenje nego imeti obe nogi in vrženemu biti v pekel ognjeni');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 46, '§ kjer njih črv ne umira in ogenj ne gasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 47, 'In če te oko tvoje pohujšuje, izderi ga; bolje ti je z enim očesom priti v kraljestvo Božje nego imeti dve očesi in vrženemu biti v pekel ognjeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 48, 'kjer njih črv ne umira in ogenj ne gasne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 49, 'Kajti vsak bo z ognjem osoljen, in vsaka žrtev bo s soljo osoljena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 9, 50, 'Dobra je sol, če pa sol postane neslana, s čim jo boste osolili? Imejte v sebi sol, in mir imejte med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 1, 'In se odpravi odtod in pride v Judejsko pokrajino in za Jordan. In snidejo se zopet množice k njemu, in kakor je imel navado, jih je zopet učil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 2, 'In pristopijo k njemu farizeji in ga vprašajo, izkušajoč ga: Ali je dovoljeno možu, ločiti se od žene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 3, 'On pa odgovori in jim reče: Kaj vam je zapovedal Mojzes?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 4, 'Oni pa reko: Mojzes je dopustil ločitni list napisati in jo pustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 5, 'Jezus pa jim reče: Zavoljo trdosrčnosti vaše vam je napisal to zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 6, 'Od začetka stvarjenja pa ju je kot moža in ženo ustvaril Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 7, '„Zato zapusti človek očeta svojega in mater svojo in se pridruži ženi svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 8, 'in ta dva bodeta eno meso.“Tako nista več dva, temuč eno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 9, 'Kar je torej Bog združil, naj človek ne razdružuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 10, 'In v hiši ga zopet učenci vprašajo o tej reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 11, 'Pa jim reče: Kdor se loči od žene svoje in se oženi z drugo, prešeštvuje zoper njo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 12, 'in ako se žena loči od moža svojega in se omoži z drugim, prešeštvuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 13, 'In prinašali so k njemu otročiče, da bi se jih dotaknil; učenci pa jih okarajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 14, 'Videč pa to Jezus, se razhudi in jim reče: Pustite otročiče, naj pridejo k meni, ne branite jim; zakaj takih je kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 15, 'Resnično vam pravim: Kdor ne sprejme kraljestva Božjega kakor otrok, nikakor ne pride vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 16, 'In jemlje jih v naročje ter polagajoč nanje roke, jih blagoslavlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 17, 'In ko gre ven na cesto, pribeži eden k njemu, poklekne pred njim in ga vpraša: Dobri učenik, kaj naj storim, da podedujem večno življenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 18, 'Jezus pa mu reče: Kaj me imenuješ dobrega? Nihče ni dober razen eden, Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 19, 'Zapovedi znaš: „Ne ubijaj, ne prešeštvuj, ne kradi, ne pričaj po krivem, ne goljufaj, spoštuj očeta svojega in mater“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 20, 'On pa odgovori in mu reče: Učenik, vse to sem izpolnjeval od mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 21, 'Jezus pa pogleda nanj, in ker ga je ljubil, mu reče: Enega ti je še treba. Pojdi, prodaj, karkoli imaš, in daj ubogim, in imel boš zaklad v nebesih; ter pridi in hodi za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 22, 'Njemu pa zagreni ta beseda in odide žalosten, zakaj imel je mnogo premoženja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 23, 'In Jezus pogleda okoli in reče učencem svojim: Kako težko pridejo tisti, ki imajo bogastvo, v kraljestvo Božje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 24, 'Učenci pa so se zavzeli ob besedah njegovih. Jezus pa zopet odgovori in jim reče: Otroci, kako težko je tistim, ki stavijo svoje upanje v bogastvo, priti v kraljestvo Božje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 25, 'Laže je velblodu iti igli skozi ušesce nego bogatemu priti v kraljestvo Božje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 26, 'Oni pa se zelo zgroze in govore med seboj: Kdo se potem more zveličati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 27, 'Jezus pa pogleda nanje in reče: Pri ljudeh je nemogoče, ali ne pri Bogu; kajti vse je mogoče pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 28, 'Peter mu začne praviti: Glej, mi smo zapustili vse in smo šli za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 29, 'Jezus reče: Resnično vam pravim, nikogar ni, ki je zapustil hišo, ali brate, ali sestre, ali očeta, ali mater, ali ženo, ali otroke, ali njive zavoljo mene in evangelija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 30, 'da ne bi prejel sedaj v tem času stokrat toliko: hiš in bratov in sester in mater in otrok in njiv s preganjanjem, in v prihodnjem svetu večnega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 31, 'Mnogi pa, ki so prvi, bodo zadnji, in ki so zadnji, prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 32, 'Bili pa so na poti, grede v Jeruzalem; in Jezus je šel pred učenci, in oni so se čudili. Tisti pa, ki so šli za njim, so se bali. In vzame zopet dvanajstere k sebi in jim začne praviti, kaj se mu ima zgoditi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 33, 'Glejte, gori v Jeruzalem gremo, in Sin človekov bo izdan višjim duhovnikom in pismarjem, in obsodijo ga na smrt in izroče poganom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 34, 'in zasramovali ga bodo in pljuvali nanj in ga bičali in umorili; a tretji dan vstane od smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 35, 'In pristopita k njemu Jakob in Janez, sina Zebedejeva, ter mu rečeta: Učenik, hočeva, da nama storiš, kar bova prosila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 36, 'On pa ju vpraša: Kaj hočeta, da naj vama storim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 37, 'Ona pa mu rečeta: Daj nama, da bova sedela eden tebi na desnici in eden na levici v slavi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 38, 'Jezus pa jima reče: Ne vesta, kaj prosita. Moreta li piti kelih, ki ga pijem jaz, in se krstiti s krstom, ki se jaz krstim ž njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 39, 'Ona pa rečeta: Moreva. A Jezus jima veli: Kelih, ki ga jaz pijem, bosta pila, in s krstom, ki se jaz krstim ž njim, se bosta krstila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 40, 'Da bi pa sedela meni na desnici in na levici, ne morem dati jaz, a dá se to tistim, katerim je pripravljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 41, 'In ko slišijo to deseteri, se začno jeziti nad Jakobom in Janezom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 42, 'Jezus jih pa pokliče in jim reče: Veste, da tisti, ki veljajo za vladarje narodov, nad njimi gospodujejo, in njih velikaši jih siloma vladajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 43, 'Ni pa tako med vami: ampak kdorkoli hoče postati velik med vami, naj vam bode služabnik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 44, 'in kdorkoli hoče med vami biti prvi, bodi vsem hlapec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 45, 'Kajti tudi Sin človekov ni prišel, da njemu služijo, ampak da služi in dá življenje svoje v odkupnino za mnoge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 46, 'In pridejo v Jeriho. In ko so šli iz Jeriha, on in učenci njegovi in obilna množica, je sedel kraj poti slep berač, Bartimej, sin Timejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 47, 'In ko sliši, da je Jezus Nazarečan, začne vpiti in govoriti: Sin Davidov, Jezus, usmili se me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 48, 'In mnogi mu prete, naj umolkne; a on le še bolj kriči: Sin Davidov, usmili se me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 49, 'In Jezus se ustavi in veli: Pokličite ga! In pokličejo slepca in mu reko: Srčen bodi, vstani, kliče te.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 50, 'On pa vrže s sebe plašč svoj, poskoči in pride k Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 51, 'In Jezus mu odgovori in reče: Kaj hočeš, da naj ti storim? Slepec pa mu reče: Rabuni, da izpregledam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 10, 52, 'In Jezus mu veli: Pojdi, vera tvoja te je rešila. In precej je izpregledal, in za Jezusom je šel po poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 1, 'In ko so se približevali Jeruzalemu, Betfagi in Betaniji pri Oljski gori, pošlje dva izmed učencev svojih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 2, 'in jima reče: Pojdita v vas, ki vama je nasproti, in precej, ko prideta vanjo, najdeta žrebe privezano, ki na njem še noben človek ni sedel: odvežita ga in pripeljita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 3, 'In če vama kdo reče: Kaj delata to? recita: Gospod ga potrebuje in precej ga zopet pošlje sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 4, 'In odideta ter najdeta žrebe privezano pri vratih zunaj na ulici in ga odvežeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 5, 'In nekateri tistih, ki so ondi stali, jima reko: Kaj delata, da odvezujeta žrebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 6, 'Ona pa jim rečeta, kakor je bil Jezus naročil; in ju puste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 7, 'In pripeljeta žrebe k Jezusu in denejo nanje oblačila svoja, in on sede nanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 8, 'Mnogi pa pogrnejo oblačila svoja po cesti; a drugi steljejo mladičje, ki so ga nasekali po polju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 9, 'In tisti, ki ga spremljajo spredaj in zadaj, kličejo: Hosana! Blagoslovljen, ki prihaja v imenu Gospodovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 10, 'Blagoslovljeno kraljestvo, ki prihaja, kraljestvo očeta našega Davida! Hosana na višavah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 11, 'In Jezus pride v Jeruzalem in v tempelj; in ko si je vse ogledal, odide, ker je bil že večer, z dvanajsterimi v Betanijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 12, 'In ko so drugi dan šli iz Betanije, postane lačen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 13, 'In ugleda od daleč smokvo, ki je imela listje, pa pride, če morda kaj najde na njej; toda ko pristopi k njej, ne najde ničesar razen listja, kajti še ni bil čas za smokve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 14, 'In Jezus izpregovori in ji reče: Na vekomaj nikoli nihče s tebe sadu ne jej! In slišali so to učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 15, 'In pridejo v Jeruzalem. In ko stopi Jezus v tempelj, začne izganjati tiste, ki so v templju prodajali in kupovali, in prevrne mize menjalcem in stole prodajalcem golobov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 16, 'in ne pusti, da bi kdo nesel posodo skozi tempelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 17, 'In uči jih in jim reče: Mar ni pisano: „Dom moj naj se imenuje dom molitve vsem narodom“? A vi ste naredili iz njega razbojniško jamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 18, 'In slišali so to višji duhovniki in pismarji in so iskali, kako bi ga pogubili; zakaj bali so se ga, ker se je vse ljudstvo čudilo nauku njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 19, 'In vsak večer je šel ven iz mesta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 20, 'In ko gredo zjutraj mimo, ugledajo smokvo, da je suha do korenine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 21, 'In Peter se spomni in mu reče: Rabi, glej, smokva, ki si jo preklel, se je posušila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 22, 'Jezus pa odgovori in jim veli: Imejte vero v Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 23, 'Resnično vam pravim: Če kdo reče tej gori: Vzdigni se in vrzi se v morje, in ne dvomi v srcu svojem, temuč veruje, da se zgodi, kar pravi, zgodilo se mu bode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 24, 'Zato vam pravim: Vse, karkoli v molitvi svoji prosite, verujte, da ste prejeli, in zgodi se vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 25, 'In kadar stopite k molitvi, odpustite, če imate zoper koga kaj, da tudi Oče vaš, ki je v nebesih, vam odpusti vaše pregrehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 26, '§ Če pa vi ne odpustite, tudi vam ne odpusti Oče vaš, ki je v nebesih, vaših pregreškov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 27, 'In pridejo zopet v Jeruzalem. In ko se je v templju izprehajal, pridejo k njemu višji duhovniki in pismarji in starejšine');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 28, 'in mu reko: S kakšno oblastjo delaš to? ali kdo ti je dal to oblast, da to delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 29, 'Jezus pa jim reče: Vprašal vas bom eno besedo, in odgovorite mi, pa vam povem, s kakšno oblastjo to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 30, 'Krst Janezov, je li bil iz nebes ali od ljudi? Odgovorite mi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 31, 'In premišljevali so sami pri sebi, govoreč: Če rečemo: Iz nebes, poreče: Zakaj mu torej niste verovali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 32, 'Če pa rečemo: Od ljudi – bali so se ljudstva; kajti vsi so mislili o Janezu, da je bil res prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 11, 33, 'Pa odgovore Jezusu in reko: Ne vemo. In Jezus jim reče: Tudi jaz vam ne povem, s kakšno oblastjo to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 1, 'In začne jim govoriti v prilikah: Zasadil je človek vinograd in ga ogradil s plotom, in je izkopal klet in je sezidal stolp, in ga je izročil vinogradnikom, ter je odpotoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 2, 'In ko je bilo čas, pošlje k vinogradnikom hlapca, da bi od vinogradnikov prejel pridelkov iz vinograda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 3, 'Oni pa ga zgrabijo in pretepo in pošljejo praznega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 4, 'In zopet pošlje k njim drugega hlapca; in temu razbijejo glavo in ga osramoté.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 5, 'In pošlje drugega, in tega ubijejo, in mnogo drugih, ki jih nekatere pretepo in nekatere ubijejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 6, 'Še enega je imel, sina ljubljenega: tega pošlje naposled k njim, rekoč: Sina mojega se bodo bali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 7, 'Oni pa, vinogradniki, reko med seboj: Ta je dedič. Pridite, ubijmo ga, in naša bo dediščina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 8, 'Ter ga zgrabijo in ubijejo, in ga vržejo ven iz vinograda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 9, 'Kaj bo torej storil gospodar vinograda? Pride in vinogradnike pogubi, in vinograd dá drugim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 10, 'Niste li brali tudi tega pisma: „Kamen, ki so ga zidarji zavrgli, ta je postal glava voglu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 11, 'od Gospoda se je zgodilo to, in čudno je v očeh naših“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 12, 'In gledali so, da bi ga ujeli, ali zbojé se ljudstva. Spoznali so namreč, da je zoper nje povedal to priliko. In pustili so ga ter odšli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 13, 'In pošljejo k njemu nekatere farizejev in Herodovcev, da bi ga ujeli v besedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 14, 'In ko pridejo, mu reko: Učenik, vemo, da si resničen, in ti ni nikogar mar, kajti ne gledaš ljudem na lice, temuč v resnici učiš pot Božjo. Ali je prav dati cesarju davek ali ne? Naj ga damo ali ne damo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 15, 'On pa, ker je spoznal njih hinavstvo, jim reče: Kaj me izkušate? Prinesite mi denar, da pogledam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 16, 'Oni pa prineso. In jim reče: Čigava je ta podoba in napis? Oni mu pa reko: Cesarjeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 17, 'Jezus pa jim veli: Dajte cesarju, kar je cesarjevega, in Bogu, kar je Božjega. In silno se mu začudijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 18, 'In pridejo k njemu saduceji, ki pravijo, da ni vstajenja, in ga vprašajo, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 19, 'Učenik! Mojzes nam je napisal: Če komu brat umre in zapusti ženo, otrok pa ne zapusti, naj vzame njegov brat ženo njegovo in zbudi seme bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 20, 'Bilo je sedem bratov; in prvi vzame ženo in umre, in ne zapusti zaroda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 21, 'In vzame jo drugi in umre, ne zapustivši zaroda. Tudi tretji tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 22, 'In vseh sedem ne zapusti zaroda. Naposled za vsemi umre tudi žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 23, 'Ob vstajenju torej, ko vstanejo, čigava izmed njih bo žena? Kajti sedmeri so jo imeli za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 24, 'Jezus jim reče: Se li ne motite zato, ker ne poznate pisem, ne moči Božje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 25, 'Kadar namreč iz mrtvih vstanejo, se ne ženijo in ne možé, ampak so kakor angeli v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 26, 'Za mrtve pa, da vstajajo, niste li brali v Mojzesovi knjigi, pri grmu, kako mu je Bog govoril, rekoč: „Jaz sem Bog Abrahamov in Bog Izakov in Bog Jakobov“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 27, 'On ni Bog mrtvih, ampak živih. Zelo se motite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 28, 'In pristopi eden pismarjev, ki je slišal, kako so se prepirali, in ker je videl, da jim je dobro odgovoril, ga vpraša: Katera je prva zapoved od vseh?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 29, 'Jezus odgovori: Prva je: „Sliši, Izrael! Gospod, naš Bog, je edini Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 30, 'In ljubi Gospoda, Boga svojega, iz vsega srca svojega in iz vse duše svoje in iz vse pameti svoje in iz vse moči svoje.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 31, 'Druga je ta: „Ljubi bližnjega svojega kakor samega sebe“. Večje od teh ni druge zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 32, 'In reče mu pismar: Dobro, učenik; po resnici si povedal, da je Bog eden, in da ni drugega razen njega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 33, 'in ljubiti ga iz vsega srca in iz vse pameti in iz vse moči, in bližnjega ljubiti kakor samega sebe: to je več od vseh žgalnih žrtev in daritev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 34, 'In Jezus, videč, da je pametno odgovoril, mu reče: Nisi daleč od kraljestva Božjega. In nihče si ga ni upal več vprašati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 35, 'In Jezus odgovori in reče, učeč v templju: Kako pravijo pismarji, da je Kristus sin Davidov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 36, 'Sam David je dejal v svetem Duhu: „Rekel je Gospod Gospodu mojemu: Sedi na desnico mojo, dokler ne položim sovražnikov tvojih nogam tvojim za podnožje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 37, 'Sam David ga imenuje Gospoda; odkod pa je on sin njegov? In preprosto ljudstvo ga je rado poslušalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 38, 'In govoril jim je v nauku svojem: Varujte se pismarjev, ki radi hodijo v dolgih suknjah in ljubijo pozdrave po ulicah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 39, 'in prve stole po shodnicah in prva mesta pri gostijah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 40, 'ki požirajo vdovam hiše in na videz opravljajo dolge molitve. Ti bodo prejeli ostrejšo sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 41, 'In sede Jezus temepljskemu zakladu nasproti in gleda, kako meče ljudstvo denar v zakladnico; in veliko bogatih je metalo mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 42, 'In pride vdova uboga in vrže dva denarca, kar je en vinar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 43, 'In pokliče učence svoje in jim reče: Resnično vam pravim, da je ta vdova uboga vrgla več nego vsi, ki mečejo v zakladnico:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 12, 44, 'kajti vsi so vrgli od obilnosti svoje, ta pa je od uboštva svojega vrgla vse, kar je imela, ves živež svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 1, 'In ko je šel iz templja, mu reče eden učencev njegovih: Učenik, glej, kakšno kamenje in kakšne stavbe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 2, 'In Jezus mu reče: Vidiš te velike stavbe? Ne ostane tu kamen na kamenu, ki bi se ne podrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 3, 'In ko je sedel na Oljski gori templju nasproti, ga vprašajo posebe Peter in Jakob in Janez in Andrej:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 4, 'Povej nam, kdaj bode to? in kaj bode znamenje, ko se ima vse to dopolniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 5, 'Jezus jim pa začne praviti: Varujte se, da vas kdo ne zapelje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 6, 'Kajti veliko jih pride z imenom mojim, govoreč: Jaz sem Kristus, in mnogo jih bodo zapeljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 7, 'Kadar pa zaslišite boje in glasove o bojih, ne ustrašite se; zakaj to mora biti, ali to še ni konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 8, 'Kajti vstane narod zoper narod in kraljestvo zoper kraljestvo; potresi bodo po krajih, in bodo lakote. Začetek nadlogam je to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 9, 'Vi pa varujte sebe! Kajti izročali vas bodo sodiščem in v shodnicah vas bodo pretepali in pred vladarje in kralje vas postavljali zavoljo mene, njim za pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 10, 'In med vsemi narodi se mora poprej oznaniti evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 11, 'Kadar vas pa popeljejo, da vas izroče, ne skrbite naprej, kaj bi govorili, temuč kar vam bo dano tisto uro, to govorite; ker niste vi, ki govorite, ampak sveti Duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 12, 'Izdajal pa bo brat brata na smrt in oče sina, in otroci bodo vstali zoper roditelje in jih bodo morili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 13, 'In vsi vas bodo sovražili zaradi imena mojega. Kdor pa pretrpi do konca, ta bo zveličan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 14, 'A kadar ugledate gnusobo razdejanja, da stoji, kjer ne bi smela (kdor bere, naj razume!), tedaj naj tisti, ki so v Judeji, zbežé na gore;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 15, 'a kdor je na strehi, ne stopaj doli in ne hodi noter, da bi kaj vzel iz hiše svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 16, 'in kdor je na polju, naj se ne vrača, da vzame plašč svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 17, 'Gorje pa nosečim in doječim v tistih dneh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 18, 'Molite pa, da ne bode po zimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 19, 'Kajti tisti dnevi bodo stiska, kakršne ni bilo od začetka stvarjenja, katero je ustvaril Bog, do sedaj in je tudi ne bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 20, 'In ko ne bi bil Gospod prikrajšal teh dni, ne bi se rešil noben človek; ali zavoljo izvoljencev, ki jih je izvolil, je prikrajšal te dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 21, 'In če vam tedaj kdo reče: Glej, tu je Kristus, ali: Glej, ondi je, ne verjemite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 22, 'Kajti lažnivi kristusi in lažnivi proroki bodo vstali in delali znamenja in čudeže, da bi premotili, ko bi bilo mogoče, izvoljence.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 23, 'A vi se varujte; glejte, povedal sem vam vse naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 24, 'Ali v tistih dneh, po tej stiski, otemni solnce in mesec ne bo dajal svetlobe svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 25, 'in zvezde bodo padale z neba, in sile, ki so na nebu, se bodo pregibale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 26, 'In tedaj ugledajo Sina človekovega, da prihaja na oblakih z veliko močjo in slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 27, 'In tedaj pošlje angele svoje in zbere izvoljence svoje od četverih vetrov, od konca zemlje do kraja neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 28, 'Od smokve pa se učite prilike: Kadar se že njena veja omladi in požene listje, veste, da je blizu poletje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 29, 'Tako tudi vi: kadar ugledate, da se te reči gode, vedite, da je on blizu, pri vratih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 30, 'Resnično vam pravim, da ne preide ta rod, dokler se vse te reči ne zgode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 31, 'Nebo in zemlja preideta, a besede moje nikoli ne preidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 32, 'Za tisti dan in tisto uro pa nihče ne ve, tudi angeli v nebesih ne, tudi Sin ne, samo Oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 33, 'Pazite, bedite in molite, kajti ne veste, kdaj je ta čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 34, 'Kakor je človek, ki je odpotoval, zapustil dom svoj in dal hlapcem svojim oblast in vsakemu svoje delo, tudi vratarju zapovedal, da naj čuje –.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 35, 'Čujte torej, kajti ne veste, kdaj pride gospodar hiše: ali zvečer, ali opolnoči, ali o petelinovem petju, ali zjutraj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 36, 'da vas, ko pride nagloma, ne najde spečih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 13, 37, 'Kar pa vam pravim, pravim vsem: Čujte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 1, 'Bila je pa Velika noč in praznik presnih kruhov čez dva dni. In višji duhovniki in pismarji so gledali, kako bi ga z zvijačo ujeli in umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 2, 'Kajti govorili so: Ne na praznik, da se morda ljudstvo ne upre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 3, 'In ko je bil v Betaniji, v hiši Simona gobavca, in je sedel za mizo, pride žena, ki je imela alabastrovo posodo mazila iz čiste, dragocene narde; in razbije posodo in mu ga izlije na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 4, 'Bili pa so tu nekateri, ki so se sami pri sebi hudovali: Čemu se je zgodila ta potrata mazila?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 5, 'Kajti to mazilo bi se bilo lahko prodalo za več nego tristo denarjev in izkupilo dalo ubogim. In so godrnjali nad njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 6, 'Jezus pa reče: Pustite jo! kaj jo nadlegujete? Dobro delo je storila na meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 7, 'Kajti uboge imate vedno pri sebi, in kadar hočete, jim morete dobro storiti, mene pa nimate vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 8, 'Kar je mogla, je storila: vnaprej je pomazilila telo moje za pokop.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 9, 'Resnično pa vam pravim: Kjerkoli po vsem svetu se bo oznanjal ta evangelij, povedalo se bo tudi to, kar je ona storila, njej v spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 10, 'In Juda Iškariot, eden od dvanajsterih, odide k višjim duhovnikom, da jim ga izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 11, 'Oni pa se razvesele, ko to slišijo, in mu obljubijo dati denarja. In iskal je, kako bi ga o priliki izdal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 12, 'In prvi dan presnih kruhov, ko so klali velikonočno jagnje, mu reko učenci njegovi: Kam hočeš, da gremo in pripravimo, da boš jedel velikonočno jagnje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 13, 'In pošlje dva učencev svojih in jima reče: Pojdita v mesto, in srečal vaju bo človek, ki nese vrč vode. Pojdita za njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 14, 'in kjer vnide, recita hišnemu gospodarju: Učenik pravi: Kje je obednica, kjer bom z učenci svojimi jedel velikonočno jagnje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 15, 'In on vama pokaže veliko izbo, pogrnjeno in pripravljeno; tam nam pripravita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 16, 'In učenca odideta in prideta v mesto in najdeta, kakor jima je rekel, ter pripravita jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 17, 'In ko se zvečeri, pride z dvanajsterimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 18, 'In ko so za mizo sedeli in jedli, reče Jezus: Resnično vam pravim, da me eden izmed vas, ki z menoj jé, izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 19, 'Oni se pa začno žalostiti in mu praviti eden za drugim: Ali jaz?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 20, 'On pa jim reče: Eden dvanajsterih, ki omaka z menoj v skledi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 21, 'Sin človekov sicer gre, kakor je pisano o njem; ali gorje tistemu človeku, ki Sina človekovega izdaja! Bolje bi bilo tistemu človeku, da ne bi bil rojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 22, 'In ko so jedli, vzame Jezus kruh in blagoslovi in ga prelomi in jim da in reče: Vzemite! to je moje telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 23, 'In vzame kelih, se zahvali in jim da; in vsi so pili iz njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 24, 'In jim reče: To je moja kri nove zaveze, ki se preliva za mnoge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 25, 'Resnično vam pravim, da ne bom več pil od trtnega sadu do tistega dne, ko ga bom pil novega v kraljestvu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 26, 'In ko so odpeli zahvalnico, odidejo na Oljsko goro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 27, 'In jim reče Jezus: Vsi se boste pohujšali, kajti pisano je: „Pastirja udarim in ovce se razkrope“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 28, 'Ali po vstajenju svojem pojdem pred vami v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 29, 'Peter pa mu reče: Če se tudi vsi pohujšajo, jaz vendar ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 30, 'Pa mu reče Jezus: Resnično ti pravim, da me danes še, to noč, preden petelin dvakrat zapoje, zatajiš trikrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 31, 'On pa govori tem bolj goreče: Ko bi moral s teboj umreti, te gotovo ne zatajim. Tako so pa tudi vsi govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 32, 'In pridejo v ograd, ki mu je ime Getsemane, ter veli učencem svojim: Sedite tu dotlej, da pomolim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 33, 'In vzame Petra in Jakoba in Janeza s seboj. In začne žalovati in trepetati v grozi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 34, 'In jim reče: Žalostna je duša moja do smrti; ostanite tu in čujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 35, 'Ter odide malo dalje in pade na zemljo in moli, naj preide, če je mogoče, ta ura mimo njega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 36, 'in govori: Aba, Oče! vse je mogoče tebi, vzemi ta kelih od mene, toda ne, kar jaz hočem, ampak kar hočeš ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 37, 'In pride in jih najde speče ter reče Petru: Simon, spiš? Ali nisi mogel ene ure prečuti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 38, 'Čujte in molite, da ne zajdete v izkušnjavo; duh je sicer voljan, ali meso je slabo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 39, 'In zopet odide in moli, govoreč iste besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 40, 'In ko se vrne, jih najde zopet speče, bile so jim namreč oči preutrujene; in niso vedeli, kaj bi mu odgovorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 41, 'In pride v tretje in jim reče: Spite dalje in počivajte! Dosti je! ura je prišla. Glej, Sin človekov se izdaja grešnikom v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 42, 'Vstanite, pojdimo! Glejte, izdajalec moj se je približal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 43, 'In precej, ko je še govoril, pride Juda, eden dvanajsterih, in ž njim množica z meči in koli od višjih duhovnikov in pismarjev in starejšin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 44, 'Dal jim je pa njegov izdajalec znamenje, rekoč: Kogar poljubim, ta je; zgrabite ga in peljite varno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 45, 'In pride in pristopi precej k njemu in reče: Rabi! in ga poljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 46, 'Oni pa polože nanj roke svoje in ga zgrabijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 47, 'Eden tistih pa, ki so zraven stali, izdere meč in mahne hlapca velikega duhovnika in mu odseka uho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 48, 'In Jezus izpregovori in jim reče: Kakor na razbojnika ste prišli z meči in koli lovit me?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 49, 'Vsak dan sem bil pri vas, učeč v templju, in niste me zgrabili. Ali da se izpolnijo pisma!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 50, 'In zapuste ga vsi in pobegnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 51, 'In šel je za njim neki mladenič, s platnom ogrnjen po nagem, in ga popadejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 52, 'On pa pusti platno in ubeži nag od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 53, 'In Jezusa odpeljejo k velikemu duhovniku; in snidejo se pri njem vsi višji duhovniki in starejšine in pismarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 54, 'In Peter je šel oddaleč za njim, noter na dvor velikega duhovnika; in je sedel s hlapci, grejoč se pri ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 55, 'A višji duhovniki in ves veliki zbor so iskali pričevanja zoper Jezusa, da bi ga na smrt izdali; ali ne najdejo ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 56, 'Kajti mnogi so pričali po krivem zoper njega, ali njih izpovedbe niso bile enake.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 57, 'In vstanejo nekateri ter pričajo po krivem zoper njega, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 58, 'Mi smo ga slišali, da je dejal: Jaz poderem to svetišče, ki je narejeno z rokami, in v treh dneh sezidam drugo, ne narejeno z rokami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 59, 'Ali tudi to njih pričevanje ni bilo enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 60, 'In veliki duhovnik vstane in stopi na sredo in vpraša Jezusa, rekoč: Ne odgovarjaš li ničesar? Kaj pričajo ti zoper tebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 61, 'On pa je le molčal in ni odgovoril ničesar. Zopet ga vpraša veliki duhovnik in mu reče: Si li ti Kristus, Sin Veleslavnega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 62, 'Jezus pa reče: Jaz sem, in videli boste Sina človekovega, da sedi na desnici moči Božje in da prihaja z oblaki neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 63, 'Veliki duhovnik pa raztrga oblačila svoja in reče: Kaj nam je še treba prič?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 64, 'Slišali ste kletvino zoper Boga; kaj se vam zdi? Oni pa vsi razsodijo, da je vreden smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 65, 'In nekateri začno pljuvati nanj in mu zakrivati obraz in ga biti za uho in mu praviti: Prorokuj! Tudi služabniki so ga sprejeli z udarci po licih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 66, 'In ko je bil Peter doli na dvorišču, pride ena od dekel velikega duhovnika,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 67, 'in videč Petra, da se greje, pogleda nanj in reče: Tudi ti si bil z Nazarečanom Jezusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 68, 'On pa zataji, rekoč: Ne vem in ne umem, kaj praviš. In gre ven v preddvor, in petelin zapoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 69, 'In dekla, videč ga, začne zopet praviti tem, ki so zraven stali: Ta je izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 70, 'On pa zopet taji. In malo potem reko zopet zraven stoječi Petru: Resnično si izmed njih, saj si tudi Galilejec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 71, 'On pa se začne rotiti in prisegati: Ne poznam tega človeka, ki o njem govorite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 14, 72, 'In precej zapoje petelin drugič. In spomni se Peter besede, kako mu je rekel Jezus: Preden petelin dvakrat zapoje, me zatajiš trikrat. In ko to pomisli, se razplače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 1, 'In precej zjutraj se posvetujejo višji duhovniki s starejšinami in pismarji in ves veliki zbor, in zvežejo Jezusa, ga odpeljejo in izroče Pilatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 2, 'In vpraša ga Pilat: Ti si kralj Judov? On pa odgovori in mu reče: Ti praviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 3, 'In višji duhovniki so ga veliko tožili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 4, 'Pilat pa ga zopet vpraša, rekoč: Ne odgovarjaš li ničesar? Glej, kolikih reči te tožijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 5, 'Ali Jezus mu ni nič več odgovoril, tako da se je Pilat čudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 6, 'Ob prazniku pa jim je navadno izpustil enega jetnika, katerega so zahtevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 7, 'Bil pa je takrat vklenjen v ječi eden, po imenu Baraba, z uporniki, ki so bili ob uporu uboj storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 8, 'In ko pride množica gori, začne zahtevati, naj stori, kakor jim je vselej storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 9, 'Pilat pa jim odgovori in reče: Hočete li, da vam izpustim kralja Judov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 10, 'Zaznal je namreč, da so mu ga iz zavisti izročili višji duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 11, 'Višji duhovniki pa podpihajo ljudstvo, naj jim rajši izpusti Baraba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 12, 'Pilat pa zopet odgovori in jim reče: Kaj torej hočete, da naj storim s tem, ki ga imenujete kralja Judov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 13, 'Oni pa zopet zakriče: Križaj ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 14, 'Pilat jim pa reče: Kaj pa je hudega storil? Oni pa še bolj zakriče: Križaj ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 15, 'Pilat pa, hoteč ljudstvu ustreči, jim izpusti Baraba, a Jezusa veli bičati in ga izroči, naj ga križajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 16, 'In vojaki ga odpeljejo noter na dvor, to je v sodno palačo, in skličejo vso trumo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 17, 'In oblečejo mu škrlatno obleko in spleto krono iz trnja in jo denejo nanj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 18, 'in ga začno pozdravljati: Zdrav bodi, kralj Judov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 19, 'In bili so ga po glavi s trstom, in pljuvali so nanj, in pripogibali so kolena ter se mu priklanjali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 20, 'In ko se mu nasmejajo, mu slečejo škrlatno obleko in mu oblečejo lastno njegovo oblačilo; ter ga peljejo ven, da ga križajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 21, 'In prisilijo nekega mimogredočega Simona Cirenca, ki je šel s polja, očeta Aleksandrovega in Rufovega, naj mu ponese križ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 22, 'In pripeljejo ga na kraj Golgoto, kar se tolmači: Mesto mrtvaške glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 23, 'In podajali so mu vina z miro, ali on ni vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 24, 'In razpno ga na križ in delé med seboj obleko njegovo, metaje kocko zanjo, kdo bo kaj vzel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 25, 'Bila pa je ura tri, ko so ga na križ razpeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 26, 'In bil je napis krivde njegove napisan: KRALJ JUDOV.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 27, 'In ž njim križajo dva razbojnika, enega njemu na desno in enega na levo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 28, 'In izpolnilo se je pismo, ki pravi: „In hudodelnikom je bil prištet“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 29, 'In mimogredoči so ga preklinjali in majali z glavami in govorili: Aha, ki podiraš svetišče in ga v treh dneh postavljaš,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 30, 'pomagaj sam sebi in stopi s križa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 31, 'Ravno tako so se mu tudi višji duhovniki posmehovali in govorili med seboj s pismarji: Drugim je pomagal, sam sebi ne more pomagati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 32, 'Kristus, kralj Izraelov, naj stopi sedaj s križa, da bomo videli in verovali. Tudi ona, ki sta bila križana ž njim, sta ga zasramovala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 33, 'In ko je bila ura šest, nastane tema po vsej zemlji do devete ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 34, 'In ob deveti uri zavpije Jezus z močnim glasom: Eloi, Eloi, lama sabahtani? kar se tolmači: „Bog moj, Bog moj, zakaj si me zapustil?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 35, 'In nekateri tistih, ki so zraven stali in slišali to, reko: Glej, Elija kliče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 36, 'Eden pa pohiti in namoči gobo z octom in, nateknivši jo na trst, mu da piti, rekoč: Pustite, bomo videli, če pride Elija, da ga sname.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 37, 'Jezus pa zavpije z močnim glasom in izdahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 38, 'In zagrinjalo v svetišču se pretrga na dvoje, od vrha do tal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 39, 'Ko je pa stotnik, ki je stal njemu nasproti, videl, da je tako zakričavši izdahnil, reče: Resnično je bil ta človek Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 40, 'Bile pa so tu tudi žene, ki so oddaleč gledale, med katerimi je bila Marija Magdalena in Marija, Jakoba manjšega in Jozejeva mati, in Salome,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 41, 'ki so, ko je bil še v Galileji, za njim hodile in mu služile, in mnoge druge, katere so bile ž njim prišle v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 42, 'In ko se je že zvečerilo, ker je bil dan priprave, to se pravi: predsobotni dan,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 43, 'pride Jožef iz Arimateje, velespoštovan svetovalec, ki je tudi pričakoval kraljestva Božjega, in gre srčno k Pilatu in zaprosi Jezusovo truplo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 44, 'Pilat se pa začudi, da je že umrl, in pokliče stotnika ter ga vpraša, je li že kaj časa mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 45, 'In ko zve od stotnika, podari truplo Jožefu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 46, 'In kupivši platna, ga sname in ga zavije v platno in položi v grob, ki je bil izsekan v skali; in privali kamen grobu na vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 15, 47, 'Marija Magdalena in Marija, mati Jozejeva, pa sta gledali, kam je bil položen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 1, 'In ko mine sobota, nakupijo Marija Magdalena in Marija, mati Jakobova, in Salome dišav, da bi prišle in ga pomazilile.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 2, 'In zjutraj zgodaj prvi dan po soboti pridejo h grobu, ko je solnce izšlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 3, 'In pogovarjale so se med seboj: Kdo nam odvali kamen od grobnih vrat?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 4, 'In ko pogledajo, vidijo, da je kamen odvaljen; bil je namreč zelo velik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 5, 'In prišedši v grob, ugledajo mladeniča, da sedi na desni strani in je ogrnjen z belim oblačilom; in prestrašijo se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 6, 'On jim pa reče: Ne bojte se! Jezusa iščete Nazarečana, ki je bil križan; vstal je, ni ga tu. Glejte mesto, kamor so ga bili položili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 7, 'Ali pojdite, povejte učencem njegovim in Petru, da gre pred vami v Galilejo; tam ga boste videli, kakor vam je rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 8, 'In pridejo iz groba in naglo zbeže; zakaj strah in groza sta jih prevzela, in nikomur niso ničesar povedale, ker so se bale. —');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 9, 'Vstavši pa zgodaj prvi dan po soboti, se prikaže Jezus najprej Mariji Magdaleni, iz katere je bil izgnal sedem hudičev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 10, 'Ona odide in sporoči tem, ki so prej bili ž njim, ki so žalovali in jokali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 11, 'In ko slišijo, da živi in da ga je ona videla, niso verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 12, 'Potem se razodene v drugi podobi dvema izmed njih na poti, ko sta šla na deželo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 13, 'In ona odideta in oznanita drugim, ali tudi njima niso verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 14, 'Pozneje se razodene enajsterim, ko so sedeli za mizo, in pograja njih nevero in trdosrčost, da niso verjeli tem, ki so ga videli, da je vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 15, 'In jim reče: Pojdite po vsem svetu in oznanite evangelij vsemu stvarjenju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 16, 'Kdor veruje in je krščen, bo zveličan, a kdor ne veruje, bo obsojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 17, 'Tiste pa, ki verujejo, bodo spremljala ta znamenja: V imenu mojem bodo izganjali zle duhove, govorili bodo nove jezike,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 18, 'kače bodo prijemali, in če izpijo kaj strupenega, ne bo jim škodovalo, na bolnike bodo pokladali roke, in ozdravijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 19, 'In Gospod, potem ko jim je govoril, je bil vzet gori v nebo, in je sedel Bogu na desnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (41, 16, 20, 'Oni pa so šli in oznanjevali so povsodi, in Gospod je sodeloval ž njimi in potrjeval besedo s čudeži, ki so se obenem godili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 1, 'Ker so že mnogi poskusili spisati poročilo o dogodkih, ki so med nami popolnoma izpričani,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 2, 'kakor so nam jih izročili tisti, ki so od začetka vse sami videli in so bili služabniki besede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 3, 'namenil sem se tudi jaz, ko sem vse od začetka skrbno izprašal, po vrsti to pisati tebi, častiti Teofil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 4, 'da spoznaš resničnost besed, v katerih si bil poučen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 5, 'Bil je v dneh Heroda, kralja judejskega, duhovnik po imenu Zaharija, iz vrste Abijeve, in ženo je imel iz hčerá Aronovih, in ime ji je bilo Elizabeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 6, 'Bila sta pa oba pravična pred Bogom, živeč po vseh zapovedih in postavah Gospodovih brez madeža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 7, 'In nista imela otrok, ker je bila Elizabeta nerodovitna, in oba sta se že bila postarala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 8, 'Zgodi se pa, ko je po redu vrste svoje opravljal duhovsko službo pred Bogom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 9, 'da ga zadene žreb, naj zažge kadilo, ko vstopi v svetišče Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 10, 'In vsa množica ljudstva je bila zunaj in je molila ob uri kajenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 11, 'Prikaže pa se mu angel Gospodov, stoječ na desni strani kadilnega oltarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 12, 'In Zaharija se ustraši, ko ga zagleda, in groza ga obide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 13, 'Angel mu pa reče: Ne boj se, Zaharija, kajti uslišana je molitev tvoja, in žena tvoja Elizabeta ti porodi sina, in imenuj ime njegovo Janez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 14, 'In on ti bo v radost in veselje, in veliko se jih bo radovalo rojstva njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 15, 'Kajti velik bo pred Gospodom; in vina in močne pijače ne bo pil in s svetim Duhom bo napolnjen že od materinega telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 16, 'In veliko sinov Izraelovih bo izpreobrnil h Gospodu, njih Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 17, 'Pojde namreč pred njim v duhu in moči Elijevi, da obrne srca očetov k otrokom in nepokorne k razumnosti pravičnih, da postavi Gospodu ljudstvo pripravljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 18, 'Pa reče Zaharija angelu: Po čem naj spoznam to? Jaz sem vendar starec in moja žena je že priletna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 19, 'In angel odgovori in mu reče: Jaz sem Gabriel, ki stojim pred obličjem Božjim in sem poslan, naj govorim s teboj in ti oznanim to veselo vest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 20, 'In glej molčal boš in ne boš mogel govoriti do dne, ko se to zgodi, ker nisi veroval besedam mojim, ki se izpolnijo v svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 21, 'In ljudstvo je čakalo Zaharija, in čudili so se, da se tako dolgo mudi v svetišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 22, 'Ko pa pride ven, ne more jim govoriti, in spoznajo, da je videl prikazen v svetišču; a on jim le namigava in ostane nem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 23, 'In zgodi se, ko se dopolnijo dnevi službe njegove, da odide na dom svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 24, 'A po teh dneh spočne Elizabeta, žena njegova, in se skriva pet mesecev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 25, 'govoreč: Tako mi je storil Gospod v dneh, ko se je ozrl name, da me reši sramote moje med ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 26, 'V šestem mesecu pa pošlje Bog angela Gabriela v mesto galilejsko, ki mu je ime Nazaret,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 27, 'k devici, zaročeni možu, ki mu je bilo ime Jožef, iz hiše Davidove, in devici je bilo ime Marija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 28, '§ In angel pride k njej in reče: Zdrava, z milostjo obdarovana! Gospod je s teboj, blagoslovljena si med ženami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 29, 'Ona pa se prestraši besede njegove in premišljuje, kakšen bi bil ta pozdrav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 30, 'In angel reče: Ne boj se, Marija, kajti našla si milost pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 31, 'In glej, spočela boš v telesu in rodila sina, in imenuj ime njegovo Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 32, 'Ta bode velik in Sin Najvišjega se bo imenoval; in Gospod Bog mu bo dal prestol Davida, očeta njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 33, 'in kraljeval bo v hiši Jakobovi vekomaj in kraljestvu njegovemu ne bo konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 34, 'Marija pa reče angelu: Kako bo to, ko moža ne poznam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 35, 'In angel odgovori in ji reče: Sveti Duh pride nadte in moč Najvišjega te obsenči; zato se bo Sveto, ki se porodi, imenovalo Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 36, 'In glej Elizabeta sorodnica tvoja, tudi ona je spočela sina v starosti svoji; in ta mesec je šesti njej, ki jo imenujejo nerodovitno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 37, 'Kajti nobene besede ne bo pri Bogu, ki se ne bi mogla izpolniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 38, 'Marija pa reče: Glej, dekla sem Gospodova; zgodi se mi po besedi tvoji! In angel odide od nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 39, 'Odpravi pa se Marija te dni in gre jadrno v gore, v mesto Judovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 40, 'ter pride v hišo Zaharijevo in pozdravi Elizabeto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 41, 'In zgodi se, ko začuje Elizabeta pozdrav Marijin, da zaigra dete v telesu njenem; in Elizabeta se napolni svetega Duha');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 42, 'in zakliče z močnim glasom in reče: Blagoslovljena si ti med ženami, in blagoslovljen je sad telesa tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 43, 'In odkod meni to, da je prišla Gospoda mojega mati k meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 44, 'Kajti, glej, ko je prišel glas pozdrava tvojega v ušesa moja, je veselja zaigralo dete v telesu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 45, 'In blagor ji, ki je verovala, ker se dopolni, kar ji je rekel Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 46, 'In Marija reče: Duša moja poveličuje Gospoda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 47, 'in duh moj se je razveselil v Bogu, Zveličarju mojem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 48, 'ker se je ozrl na nizkost dekle svoje. Kajti glej, odslej me bodo blagrovali vsi rodovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 49, 'ker mi je storil velike reči on, ki je mogočen, in sveto je ime njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 50, 'in usmiljenje njegovo traja od roda do roda tistim, ki se ga bojé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 51, 'Pokazal je moč z roko svojo, razkropil je ošabne v misli njih srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 52, 'Pahnil je mogočnike s prestola in ponižne je povišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 53, 'Lačne je nasitil z dobrimi rečmi in bogate je odpravil prazne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 54, 'Sprejel je Izraela, hlapca svojega, da se spomni usmiljenja svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 55, 'Kakor je govoril očetom našim, Abrahamu in semenu njegovemu na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 56, 'Marija pa ostane pri njej kake tri mesece, in se vrne na svoj dom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 57, 'A Elizabeti se dopolni čas, da porodi, in rodi sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 58, 'In njeni sosedje in sorodniki zaslišijo, da je poveličal Gospod usmiljenje svoje na njej, in se radujejo ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 59, 'In zgodi se osmi dan, da pridejo obrezovat dete in ga kličejo po imenu očeta njegovega, Zaharija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 60, 'A mati njegova odgovori in reče: Ne, ampak Janez se bo imenoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 61, 'In reko ji: Saj ni nikogar v sorodstvu tvojem, ki bi mu bilo tako ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 62, 'In pomignejo očetu njegovemu, kako hoče, da bi ga imenovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 63, 'In veli si dati tablico in napiše takole: Janez mu je ime. In vsi se začudijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 64, 'In pri tej priči se odpro usta njegova in jezik se mu razveže, in govori, hvaleč Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 65, 'In strah obide vse njih sosede in po vsem Judejskem pogorju se pripoveduje o vseh teh rečeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 66, 'In vsi, ki jih slišijo, si jih vtisnejo v srce, govoreč: Kaj neki bo iz tega deteta? Zakaj roka Gospodova je bila ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 67, 'In Zaharija, oče njegov, se napolni svetega Duha in prorokuje, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 68, 'Hvaljen Gospod, Bog Izraelov, ki je obiskal ljudstvo svoje in mu pripravil odrešenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 69, 'in nam povzdignil rog zveličanja v hiši Davida, služabnika svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 70, '(kakor je govoril z usti svetih prorokov svojih, ki so bili od nekdaj),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 71, 'rešitev od sovražnikov naših in iz rok vseh, ki nas mrze;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 72, 'da izkaže usmiljenje očetom našim in se spomni svete zaveze svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 73, 'prisege, ki jo je prisegel Abrahamu, očetu našemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 74, 'da nam bo dal, da mu, rešeni iz rok sovražnikov svojih, služimo brez straha');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 75, 'v svetosti in pravičnosti pred njim vse svoje žive dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 76, 'In ti, dete, se boš imenovalo prorok Najvišjega; kajti pojdeš pred obličjem Gospodovim, da mu pripraviš poti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 77, 'in daš ljudstvu njegovemu spoznanje zveličanja, ki je v odpuščenju njih grehov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 78, 'po prisrčnem usmiljenju Boga našega, po katerem, nas je obiskal Vzhod z višave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 79, 'da obsije tiste, ki sedé v temi in v senci smrti, da vodi noge naše na pot miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 1, 80, 'Dete pa je raslo in se krepilo v duhu, in v puščavi je bilo do dne, ko se pokaže Izraelu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 1, 'Zgodi se pa tiste dni, da izide povelje od cesarja Avgusta, naj se popiše ves svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 2, 'To popisovanje je bilo prvo, ko je vladal v Siriji Cirenij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 3, 'In šli so vsi, da se zapišejo, vsak v svoje mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 4, 'Napoti pa se tudi Jožef iz Galileje, iz mesta Nazareta, v Judejo, v mesto Davidovo, ki se imenuje Betlehem, ker je bil iz hiše in rodovine Davidove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 5, 'da se zapiše z Marijo, zaročeno mu ženo, ki je bila noseča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 6, 'Zgodi se pa, ko sta bila tam, da se dopolnijo dnevi, da porodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 7, 'In rodi sina svojega prvenca ter ga povije v plenice in ga položi v jasli, ker jima ni bilo prostora v prenočišču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 8, 'In pastirji so čuli v tistem kraju pod milim nebom in so stražili po noči svojo čredo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 9, 'In angel Gospodov pristopi k njim, in slava Gospodova jih obsije, in silno se prestrašijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 10, 'In angel jim reče: Ne bojte se, kajti glejte, oznanjam vam veliko veselje, ki bo vsemu ljudstvu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 11, 'Ker vam se je danes rodil Zveličar, ki je Kristus Gospod, v mestu Davidovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 12, 'In to vam bodi znamenje: Našli boste dete v plenice povito, ležeče v jaslih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 13, 'In hipoma se pokaže z angelom množica nebeške vojske, ki so hvalili Boga in govorili:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 14, 'Slava na višavah Bogu in na zemlji mir ljudem, ki so mu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 15, 'In zgodi se, ko odidejo angeli od njih v nebesa, pa reko pastirji med seboj: Pojdimo do Betlehema in poglejmo to reč, ki se je zgodila, ki nam jo je oznanil Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 16, 'In pridejo jadrno in najdejo Marijo in Jožefa in dete, da leži v jaslih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 17, 'Ko ga pa vidijo, oznanijo vest, ki jim je bila povedana o tem detetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 18, 'In vsi, ki slišijo, se čudijo temu, kar jim pripovedujejo pastirji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 19, 'Marija pa ohrani vse te besede, premišljujoč jih v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 20, 'In vrnejo se pastirji, slaveč in hvaleč Boga za vse, kar so slišali in videli, kakor jim je bilo povedano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 21, 'In ko se dopolni osem dni, da ga obrežejo, mu dado ime Jezus, katero je bil imenoval angel, preden je bil spočet v telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 22, 'In ko se jima dopolnijo dnevi očiščevanja po postavi Mojzesovi, ga prineso v Jeruzalem, da ga postavijo pred Gospoda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 23, 'kakor je pisano v postavi Gospodovi: „Vsak moški prvorojenec naj se imenuje svet Gospodu“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 24, 'in da opravijo daritev po tem, kar je rečeno v postavi Gospodovi: dve grlici ali dva golobiča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 25, 'In glej, v Jeruzalemu je bil človek, ki mu je bilo ime Simeon, in ta človek je bil pravičen in pobožen in je čakal tolažbe Izraelove, in sveti Duh je bil nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 26, 'In sveti Duh mu je razodel, da ne bo videl smrti, dokler ne zazre Kristusa Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 27, 'In pride po Duhu v tempelj. In ko prineso starši otroka Jezusa v tempelj, da opravita zanj po šegi postave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 28, 'ga vzame tudi on v naročje svoje in hvali Boga in reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 29, 'Sedaj odpuščaš hlapca svojega, Gospod, po besedi svoji v miru,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 30, 'ker so videle oči moje zveličanje tvoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 31, 'ki si ga pripravil pred obličjem vseh narodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 32, 'luč v razsvetljenje poganov in v slavo ljudstva tvojega Izraela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 33, 'In njegov oče in mati njegova se čudita temu, kar se je govorilo o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 34, 'In blagoslovi ju Simeon in reče Mariji, materi njegovi: Glej, ta je postavljen v padec in v vstajenje mnogim v Izraelu in za znamenje, kateremu se bo nasprotovalo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 35, '(a tebi sami presune meč dušo), da se razodenejo misli iz mnogih src.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 36, 'In bila je tu prorokinja Ana, hči Fanuelova, iz Aserjevega rodu. Ta je učakala visoko starost: ko je bila živela z možem sedem let po devištvu svojem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 37, 'je bila zdaj vdova okoli štiriinosemdesetih let. Ona ni odhajala od templja in je s postom in z molitvami služila Bogu noč in dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 38, 'In ta pristopi ravno tisto uro, in je hvalila Gospoda in govorila o njem vsem, ki so čakali odrešitve Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 39, 'In ko vse po postavi Gospodovi izvrše, se vrnejo v Galilejo, v mesto svoje Nazaret.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 40, 'A dete je raslo in se krepilo v duhu in se napolnjevalo modrosti, in milost Božja je bila ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 41, 'In njegovi starši so hodili vsako leto v Jeruzalem na velikonočni praznik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 42, 'In ko mu je bilo dvanajst let in so šli v Jeruzalem po navadi tega praznika, je šel ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 43, 'In ko so dopolnili praznične dni in se napotili domov, je ostal deček Jezus v Jeruzalemu; in njegovi starši tega niso vedeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 44, 'Misleč pa, da je pri potni druščini, preideta dan hodá in ga iščeta pri sorodnikih in pri znancih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 45, 'In ko ga ne najdeta, se vrneta v Jeruzalem in ga iščeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 46, 'In zgodi se po treh dneh, da ga najdeta v templju, kjer je sedel sredi učenikov ter jih poslušal in jih vpraševal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 47, 'Čudili so se pa vsi, ki so ga poslušali, razumu njegovemu in odgovorom njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 48, 'In ko ga ugledata, se zavzameta, in reče mu mati njegova: Sin, kaj si nama storil tako? Glej, oče tvoj in jaz sva te z žalostjo iskala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 49, 'On jima pa reče: Kaj, da sta me iskala? Nista li vedela, da moram biti v tem, kar je Očeta mojega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 50, 'In ona nista razumela besede, ki jo je jima rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 51, 'Ter gre ž njima in pride v Nazaret, in bil jima je pokoren. In mati njegova je hranila vse te besede v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 2, 52, 'In Jezus je napredoval v modrosti in rasti, in v milosti pri Bogu in pri ljudeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 1, 'Petnajstega leta vlade cesarja Tiberija pa, ko je bil Poncij Pilat poglavar v Judeji in Herod četrtnik v Galileji, a Filip, njegov brat, četrtnik v Itureji in v Trahoniški pokrajini in Lizanija četrtnik v Abileni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 2, 'za velikih duhovnikov Ana in Kajfa, pride beseda Božja k Janezu, Zaharijevemu sinu, v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 3, 'In on pride v vso okolico Jordansko in propoveduje krst izpokorjenja v odpuščenje grehov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 4, 'kakor je pisano v knjigi govorov Izaija proroka: „Glas vpijočega v puščavi: Pripravite pot Gospodov, poravnajte steze njegove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 5, 'Vsaka dolina naj se izpolni, in vsaka gora in grič naj se zniža, in kar je krivega, bodi ravno, in ostra pota naj bodo gladka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 6, 'in vse človeštvo bo videlo zveličanje Božje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 7, 'Govoril je torej množicam, ki so prihajale, da bi jih krstil: Gadja zalega, kdo vas je poučil, da ubežite prihodnji jezi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 8, 'Rodite torej sadove, vredne izpokorjenja, in ne poskušajte govoriti v sebi: Za očeta imamo Abrahama; kajti pravim vam, da more Bog iz tega kamenja obuditi Abrahamu otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 9, 'Nastavljena pa je že tudi sekira drevju pri korenini: vsako drevo, ki ne rodi dobrega sadu, se torej poseka in vrže na ogenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 10, 'In vprašujejo ga množice, govoreč: Kaj naj torej storimo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 11, 'Odgovarjajoč pa jim veli: Kdor ima dve suknji, daj tistemu, ki nima, in kdor ima hrane, stori ravno tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 12, 'Pridejo pa tudi cestninarji, da bi jih krstil, in mu reko: Učenik, kaj naj storimo mi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 13, 'On jim pa reče: Ničesar ne terjajte več, nego vam je določeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 14, 'Vprašajo ga pa tudi vojaki, rekoč: In mi, kaj naj storimo? In reče jim: Nikomur ne delajte sile in ne ovajajte, ter bodite zadovoljni s plačo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 15, 'Ko pa je ljudstvo čakalo, in so vsi mislili v srcih svojih o Janezu, če ni nemara on Kristus,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 16, 'odgovori Janez vsem, rekoč: Jaz vas z vodo krščujem, prihaja pa močnejši od mene, ki mu nisem vreden odvezati jermena na obuvalu njegovem: on vas bo krstil s svetim Duhom in ognjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 17, 'On ima velnico v roki svoji, in očedi gumno svoje in pospravi pšenico v žitnico svojo, a pleve sežge z neugasljivim ogljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 18, 'Tudi še z mnogimi drugimi opomini je oznanjeval blagovestje ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 19, 'Herod četrtnik pa, ker ga je svaril zaradi Herodiade, njegovega brata žene, in zaradi vsega, kar je hudega storil Herod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 20, 'stori vrhu vsega tudi še to, da zapre Janeza v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 21, 'Zgodi se pa, ko se krščuje vse ljudstvo in se tudi Jezus krsti in moli: da se odpre nebo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 22, 'in sveti Duh pride nanj v telesni podobi kakor golob, in glas iz nebes se oglasi: Ti si Sin moj ljubljeni, ti si po moji volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 23, 'In on, Jezus, je bil, ko je začel učiti, blizu tridesetih let, sin, kakor se je mislilo Jožefov, Helijev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 24, 'Matatov, Levijev, Melhijev, Janajev, Jožefov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 25, 'Matatijev, Amosov, Nahumov, Eslijev, Nagajev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 26, 'Maatov, Matatijev, Semejev, Josehov, Jodov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 27, 'Joananov, Resov, Zorobabelov, Salatielov, Nerijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 28, 'Melhijev, Adijev, Kozamov, Elmodamov, Erov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 29, 'Jozuetov, Eliezerjev, Jorimov, Matatov, Levijev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 30, 'Simeonov, Judov, Jožefov, Jonamov, Eliakimov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 31, 'Meleov, Menov, Matatajev, Natanov, Davidov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 32, 'Jesejev, Obedov, Boazov, Salmonov, Nahsonov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 33, 'Aminadabov, Aramov, Ezronov, Faresov, Judov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 34, 'Jakobov, Izakov, Abrahamov, Tarov, Nahorov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 35, 'Serugov, Ragavov, Falekov, Eberjev, Salov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 36, 'Kajnanov, Arfaksadov, Semov, Noetov, Lamehov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 37, 'Matuzalemov, Enohov, Jaredov, Maleleelov, Kajnanov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 3, 38, 'Enosov, Setov, Adamov, Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 1, 'Jezus pa, svetega Duha poln, se vrne od Jordana in Duh ga vodi po puščavi štirideset dni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 2, 'in hudič ga izkuša. In ničesar ni jedel v teh dneh; in ko minejo, postane lačen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 3, 'In reče mu hudič: Če si Sin Božji, reci temu kamenu, naj postane kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 4, 'In odgovori mu Jezus: Pisano je: „Ne bo živel človek ob samem kruhu“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 5, 'In pripelje ga hudič na vrh in mu pokaže vsa kraljestva sveta v trenutku časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 6, 'In mu reče hudič: Tebi dam vso to oblast in njih slavo, kajti meni je izročena, in dajem jo, komurkoli hočem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 7, 'Ti torej če se pokloniš pred menoj, bode vse tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 8, 'In odgovori in reče mu Jezus: Pisano je: „Gospoda, Boga svojega, moli in njemu samemu služi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 9, 'In pelje ga v Jeruzalem in ga postavi na vrh templja in mu reče: Če si Sin Božji, spusti se odtod doli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 10, 'kajti pisano je: „Angelom svojim bo zapovedal zate, naj te varujejo“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 11, 'in „Na rokah te bodo nosili, da se kje z nogo ne udariš ob kamen“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 12, 'In odgovori in mu reče Jezus: Rečeno je: „Ne izkušaj Gospoda, Boga svojega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 13, 'In ko je končal hudič vsako izkušnjavo, odstopi od njega do časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 14, 'In Jezus se vrne v moči Duha v Galilejo; in glas o njem se raznese po vsem okolišu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 15, 'In učil je po njih shodnicah, in vsi so ga slavili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 16, 'In pride v Nazaret, kjer je bil vzrejen; in gre po navadi svoji v sobotni dan v shodnico, in vstane, da bere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 17, 'In dado mu knjigo Izaija proroka. In ko razgane knjigo, najde mesto, kjer je pisano:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 18, '„Duh Gospodov je nad menoj, zato ker me je pomazilil, da naj oznanim blagovestje ubogim, poslal me je, da oznanim jetnikom izpuščenje in slepcem izpregled, da izpustim zatirance na svobodo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 19, 'da razglasim milostno leto Gospodovo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 20, 'In zapre knjigo in jo odda strežaju, in sede, in oči vseh v shodnici se vpirajo vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 21, 'In začne jim govoriti: Danes se je izpolnilo to pismo v ušesih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 22, 'In vsi mu pričajo in se čudijo besedam milosti, ki so prihajale iz ust njegovih, in pravijo: Ali ni ta sin Jožefov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 23, 'In reče jim: Gotovo mi porečete ta pregovor: Zdravnik, ozdravi se sam! Karkoli smo slišali, da se je zgodilo v Kafarnavmu, stori tudi tu v domovini svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 24, 'Reče pa: Resnično vam pravim, da noben prorok ni prijeten v domovini svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 25, 'Ali v resnici vam pravim, da je bilo veliko vdov v dneh Elija v Izraelu, ko je bilo nebo zaprto tri leta in šest mesecev, da je nastala velika lakota po vsej zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 26, 'a k nobeni od njih ni bil poslan Elija, razen v Sarepto Sidonsko k ovdoveli ženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 27, 'In veliko gobavcev je bilo za proroka Elizeja v Izraelu. A nobeden od njih ni bil očiščen razen Naamana Sirca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 28, 'In vsi v shodnici se napolnijo jeze, ko to slišijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 29, 'In vstanejo in ga ženo ven iz mesta ter ga peljejo na rob gore, na kateri je bilo njih mesto sezidano, da bi ga doli pahnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 30, 'Ali on gre sredi med njimi, in odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 31, 'In pride v Kafarnavm, mesto galilejsko, in jih uči ob sobotah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 32, 'In čudijo se nauku njegovemu, ker je bila beseda njegova oblastna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 33, 'In v shodnici je bil človek, ki je imel nečistega zlega duha, in zakriči z močnim glasom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 34, 'Ah, kaj imaš z nami, Jezus iz Nazareta? Prišel si, da nas pogubiš? Poznam te, kdo si: Svetnik Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 35, 'In zapreti mu Jezus rekoč: Umolkni in idi iz njega! In trešči ga zli duh na sredo in odide iz njega, in mu ni nič škodoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 36, 'In obide jih groza vse, in pomenkujejo se med seboj, govoreč: Kakšna je ta beseda, da z oblastjo in močjo ukazuje nečistim duhovom, pa izhajajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 37, 'In glas o njem pride v vsako mesto te okolice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 38, 'Vstavši pa gre iz shodnice in pride v hišo Simonovo. Tašča Simonova pa je imela hudo mrzlico; in prosijo ga zanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 39, 'In pristopivši se nagne nadnjo in zapreti mrzlici, in mrzlica jo pusti; ona pa zdajci vstane ter jim streže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 40, 'Ko pa je solnce zahajalo, vsi, ki so imeli bolnike z različnimi boleznimi, jih privedo k njemu; on pa na vsakega izmed njih položi roke ter jih ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 41, 'Izhajali so pa tudi zli duhovi iz mnogih, kričeč in govoreč: Ti si Sin Božji. In jim zagrozi in ne dovoli govoriti, ker so vedeli, da je on Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 42, 'Ko se pa zdani, gre ven in odide na samoten kraj; in množice ga iščejo in pridejo tja k njemu in ga pridržujejo, da ne bi šel od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 43, 'On pa jim reče: Tudi drugim mestom moram oznanjevati evangelij o kraljestvu Božjem, ker zato sem poslan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 4, 44, 'In propovedoval je po shodnicah galilejskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 1, 'Zgodi se pa, ko ga množice obsujejo, da bi poslušali besedo Božjo, da stoji pri jezeru Genezareškem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 2, 'In ugleda dve ladji, ki stojita ob jezeru; ribiči pa so bili izstopili iz njiju in so izpirali mreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 3, 'In vstopi v eno teh ladij, ki je bila Simonova, in ga zaprosi, naj odrine malo od kraja; ter sede in uči iz ladje množico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 4, 'A ko neha govoriti, reče Simonu: Odrini na globoko, in vrzite mreže svoje na lov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 5, 'In Simon odgovori in reče: Učenik, vso noč smo se trudili in ničesar nismo ujeli; ali na besedo tvojo bom vrgel mrežo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 6, 'In storivši to, zajamejo veliko množico rib; trgala pa se jim je mreža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 7, 'In pomignejo tovarišem, ki so bili v drugi ladji, naj jim pridejo pomagat. Pa pridejo in napolnijo obe ladji, tako, da se začneta potapljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 8, 'Videč pa to, pade Simon Peter h kolenom Jezusovim, rekoč: Pojdi od mene, ker sem človek grešnik, Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 9, 'Groza namreč je bila obšla njega in vse, ki so bili ž njim, ob vlaku rib, ki so ga bili zajeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 10, 'ravno tako pa tudi Jakoba in Janeza, sinova Zebedejeva, ki sta bila tovariša Simonova. Pa reče Jezus Simonu: Ne boj se; odslej boš ljudi lovil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 11, 'In potegnivši ladjo h kraju, zapusté vse in odidejo za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 12, 'In zgodi se, ko je bil v enem ondotnih mest, da je tu, glej, mož, ves gobav; in ko ugleda Jezusa, pade na obraz in ga zaprosi, rekoč: Gospod, če hočeš, me moreš očistiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 13, 'In iztegnivši roko, se ga dotakne in reče: Hočem, bodi očiščen! In precej so mu prešle gobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 14, 'In on mu naroči, naj nikomur ne pove, marveč pojdi, mu veli, pokaži se duhovniku in daruj za očiščenje svoje, kakor je ukazal Mojzes, njim za pričevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 15, 'Toda govorica o njem se je še tem bolj razglaševala, in velike množice so se zbirale, da bi ga poslušali in da bi jih ozdravljal njih bolezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 16, 'A on se je umikal v puščavo in je tam molil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 17, 'In zgodi se neki dan, da je učil, in sedeli so tam farizeji in učeniki postave, ki so bili prišli iz vseh vasi galilejskih in judejskih in iz Jeruzalema. In moč Gospodova je bila pričujoča, da bi jih ozdravljal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 18, 'In glej, možje neso na postelji človeka, ki je mrtvouden, in skušajo, kako bi ga prinesli in položili pred njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 19, 'In ko spričo množice ne najdejo, kod bi ga noter nesli, zlezejo na streho in skozi strešnike ga spuste s posteljo vred v sredo pred Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 20, 'In ko vidi njih vero, mu reče: Človek odpuščeni so ti grehi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 21, 'Pa začno premišljevati pismarji in farizeji, govoreč v sebi: Kdo je ta, ki govori bogokletje? Kdo more odpuščati grehe razen Bog sam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 22, 'Jezus, spoznavši njih misli, pa odgovori in jim reče: Kaj premišljate v srcih svojih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 23, 'Kaj je laže, reči: Odpuščeni so ti grehi tvoji, ali reči: Vstani in hodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 24, 'Da pa boste vedeli, da ima oblast Sin človekov, na zemlji odpuščati grehe (veli mrtvoudnemu): Tebi pravim, vstani in vzemi posteljo svojo in pojdi na dom svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 25, 'In takoj vstane pred njimi in vzame, na čemer je ležal, in odide na dom svoj, hvaleč Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 26, 'In groza prevzame vse, in proslavljajo Boga in napolnijo se strahu, govoreč: Nezaslišane reči smo videli danes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 27, 'In potem odide in ugleda cestninarja, po imenu Levija, da sedi na mitnici, in mu veli: Pojdi za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 28, 'In pustivši vse, vstane in odide za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 29, 'In napravi mu Levi veliko pojedino v hiši svoji; in bila je velika množica cestninarjev in drugih, ki so ž njim sedeli za mizo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 30, 'In godrnjajo farizeji in njih pismarji proti učencem in pravijo: Zakaj s cestninarji in grešniki jeste in pijete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 31, 'In odgovori Jezus in reče: Zdravi ne potrebujejo zdravnika, ampak bolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 32, 'Nisem prišel klicat pravičnih, temuč grešnike, da se izpokore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 33, 'A oni mu reko: Učenci Janezovi se pogostoma postijo in opravljajo molitve, prav tako tudi farizejski, tvoji pa jedo in pijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 34, 'Jezus pa jim reče: Morete li zahtevati, da bi se svatje postili, dokler je ženin ž njimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 35, 'Pridejo pa dnevi, in ko se jim ženin odvzame, tedaj se bodo postili, v tistih dnevih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 36, 'Pravil jim je pa tudi priliko: Nihče ne utrga zaplate od nove obleke in je ne prišije na staro obleko, sicer izkazi tudi novo, in stari se ne prilega zaplata od nove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 37, 'In nihče ne deva novega vina v stare mehove, sicer predere novo vino mehove in vino se razlije in mehovi se pokaze;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 38, 'ampak novo vino se mora vlivati v nove mehove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 5, 39, 'In kdor je pil starino, noče precej novega, ker pravi: staro je boljše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 1, 'Zgodi se pa drugo-prvo soboto, da gre skozi setve, in učenci njegovi trgajo klasje, ga manejo z rokami in jedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 2, 'Nekateri farizejev pa reko: Zakaj delate, kar se ne sme delati ob sobotah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 3, 'In odgovori in jim reče Jezus: Ali niste še brali tega, kar je storil David, ko se je ulačnil on in kateri so bili ž njim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 4, 'Kako je šel v hišo Božjo in je vzel predložene kruhe in jih jedel ter dal tudi tistim, ki so bili ž njim: katerih ne sme nihče jesti, razen samo duhovniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 5, 'In reče jim: Sin človekov je tudi sobote gospodar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 6, 'Zgodi se pa v drugo soboto, da gre v shodnico in uči. In tam je bil človek, čigar desna roka je bila usehla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 7, 'Pismarji in farizeji so pa pazili nanj, če bo tudi v soboto ozdravljal, da bi našli tožbo zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 8, 'A on je vedel njih misli; veli pa možu, ki je imel suho roko: Vstani in stopi na sredo! In vstane in se ustopi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 9, 'Jezus pa jim reče: Vprašam vas: kaj velja ob sobotah: dobro delati ali hudo, življenje oteti ali pogubiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 10, 'In pogledavši jih vse okrog, reče človeku: Iztegni roko svojo! In on stori tako, in roka njegova je bila zopet zdrava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 11, 'A oni postanejo togote vsi neumni, in pomenkujejo se med seboj, kaj bi storili Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 12, 'Zgodi se pa tiste dni, da odide na goro molit, in vztraja vso noč v molitvi k Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 13, 'In ko se zdaní, pokliče učence svoje; in izvoli jih dvanajst izmed njih, katerim tudi da ime apostoli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 14, 'Simona, ki mu je tudi dal ime Peter, in Andreja, njegovega brata, Jakoba in Janeza, Filipa in Bartolomeja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 15, 'Matevža in Tomaža, Jakoba Alfejevega in Simona, ki se imenuje Gorečnik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 16, 'Juda Jakobovega in Juda Iškariota, ki je postal izdajalec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 17, 'In gre ž njimi doli in se ustavi na ravnem kraju, in okrog njega velika truma učencev njegovih in velika množica ljudstva iz vse Judeje in iz Jeruzalema in iz Tirskega in Sidonskega primorja, ki so bili prišli, da bi ga slišali in da bi jih ozdravil njih bolezni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 18, 'in tisti, ki so jih mučili nečisti duhovi, so bili ozdravljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 19, 'In vsa množica je iskala, da bi se ga dotikali, ker moč je iz njega šla in ozdravljala vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 20, 'In on, povzdignivši oči na učence svoje, pravi: Blagor vam ubogim, ker vaše je kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 21, 'Blagor vam, ki ste sedaj lačni, ker bodete nasičeni. Blagor vam, ki sedaj jokate, ker se boste smejali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 22, 'Blagor vam, kadar vas ljudje mrzé in kadar vas izobčujejo in sramoté in zametujejo vaše ime kot hudobno zaradi Sina človekovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 23, 'Radujte se tisti dan in poskakujte! Kajti glejte, veliko je plačilo vaše v nebesih; ravno tako namreč so delali prorokom njih očetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 24, 'Toda gorje vam bogatim, kajti prejeli ste tolažbo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 25, 'Gorje vam, ki ste sedaj nasičeni, ker bodete lačni. Gorje vam, ki se sedaj smejete, ker žalovali boste in jokali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 26, 'Gorje vam, kadar dobro o vas govore vsi ljudje; kajti ravno tako so delali njih očetje lažnivim prorokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 27, 'Ali vam, ki poslušate, pravim: Ljubite sovražnike svoje; delajte dobro tem, ki vas mrzé;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 28, 'blagoslavljajte, ki vas preklinjajo, molite za te, ki vas obrekujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 29, 'Kdor te udari po enem licu, nastavi mu tudi drugo, in kdor ti jemlje plašč, ne brani mu vzeti tudi suknje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 30, 'Daj vsakemu, kdor te prosi, in od njega, ki tvoje vzame, ne zahtevaj nazaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 31, 'In kakor hočete, da bi ljudje vam storili, prav tako storite tudi vi njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 32, 'In če ljubite tiste, ki ljubijo vas, kakšna hvala vam gre? Saj tudi grešniki ljubijo tiste, ki nje ljubijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 33, 'In če dobro delate tistim, ki dobro delajo vam, kakšna hvala vam gre? Tudi grešniki delajo ravno tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 34, 'In če posojate tistim, od katerih upate zopet prejeti, kakšna hvala vam gre? Tudi grešniki posojajo grešnikom, da prejmo enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 35, 'Ampak ljubite sovražnike svoje, dobro delajte in posojajte, ne pričakujoč ničesar; in veliko vam bode plačilo, in sinovi bodete Najvišjega: zakaj on je dobrotljiv tudi nehvaležnežem in hudobnežem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 36, 'Bodite torej usmiljeni, kakor je Oče vaš usmiljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 37, 'In ne sodite, in ne bodete sojeni. Ne obsojajte, in ne bodete obsojeni. Odpuščajte, in vam bo odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 38, 'Dajajte, in vam bo dano: mero dobro in natlačeno in potreseno in zvrhano bodo dali v naročje vaše; s kakršno mero namreč merite, s tako se vam bo odmerjalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 39, 'Pove jim pa tudi priliko: More li slepec slepca voditi? Ne padeta li oba v jamo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 40, 'Ni ga učenca nad učitelja svojega; a vsak, kdor se popolnoma izuči, bo kakor učitelj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 41, 'Kaj pa vidiš pazder, ki je v brata tvojega očesu, bruna pa, ki je v očesu tvojem, ne čutiš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 42, 'Kako moreš reči bratu svojemu: Brat, daj, da izderem pazder, ki je v očesu tvojem, ko sam bruna v očesu svojem ne vidiš? Hinavec, izderi najprej bruno iz očesa svojega, in potem izpregledaš, da izdereš pazder, ki je v očesu brata tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 43, 'Ni ga namreč drevesa dobrega, da bi rodilo slab sad, tudi slabega drevesa ne, da bi rodilo dober sad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 44, 'Kajti vsako drevo se spozna po svojem sadu. S trnja namreč ne bero smokev in z robidovja ne trgajo grozdja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 45, 'Dobri človek prinaša iz dobrega zaklada srca svojega dobro, hudobnež pa prinaša iz hudega zaklada hudobno; kajti usta njegova govore iz preobilosti srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 46, 'Kaj pa me imenujete: Gospod, Gospod, pa ne delate, kar pravim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 47, 'Vsak, kdor gre k meni in sliši moje besede in jih izpolnjuje, pokažem vam, komu je podoben:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 48, 'Podoben je človeku, ki zida hišo, in globoko koplje in postavi temelj na skalo; in ko nastane povodenj, zažene se reka ob tisto hišo, a ne more je omajati, ker je trdno sezidana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 6, 49, 'Kdor pa sliši in ne stori, podoben je človeku, ki zida hišo na zemlji brez temelja; in ko se reka zažene vanjo, precej pade, in podrtija te hiše je velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 1, 'Potem pa, ko je končal vse besede svoje pred ljudstvom, ki je poslušalo, pride v Kafarnavm.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 2, 'Nekemu stotniku pa je bil hlapec, katerega je rad imel, bolan in je že umiral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 3, 'Ko pa sliši o Jezusu, pošlje k njemu starešine Judov. Proseč ga, naj pride in mu ozdravi hlapca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 4, 'Ko pa oni pridejo k Jezusu, ga silno prosijo, rekoč: Vreden je, da mu to storiš;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 5, 'ljubi namreč narod naš in shodnico nam je sezidal sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 6, 'In Jezus gre tja ž njimi. In ko že ni daleč od hiše, pošlje k njemu stotnik prijatelje in mu sporoči: Gospod, ne trudi se; zakaj nisem vreden, da stopiš pod streho mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 7, 'Zato se tudi nisem sam vrednega štel, da bi prišel k tebi; temuč reci z besedo, in hlapec moj ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 8, 'Kajti tudi jaz sem človek, pod oblast postavljen, in imam vojake pod seboj, pa velim temu: Pojdi! In gre, in drugemu: Pridi! In pride, in hlapcu svojemu: Stori to! In stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 9, 'Ko pa Jezus to sliši, se mu začudi in, obrnivši se, reče množici, ki je šla za njim: Pravim vam, tudi v Izraelu še nisem našel tolike vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 10, 'In ko se vrnejo domov, ki so bili poslani, najdejo hlapca zdravega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 11, 'In zgodi se potem, da gre v mesto, ki se imenuje Nain, in ž njim gredo učenci njegovi in velika množica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 12, 'Ko se pa približa mestnim vratom, glej, neso ven mrliča, edinega sina matere njegove, in ona je bila vdova; in mnogo ljudstva iz mesta gre ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 13, 'In ko jo Gospod ugleda, se mu zasmili in ji reče: Ne jokaj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 14, 'In pristopivši se dotakne odra, nosilci pa se ustavijo, in veli: Mladenič, pravim ti, vstani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 15, 'In mrlič sede in začne govoriti. In dá ga materi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 16, 'Obide pa jih groza vse, in hvalijo Boga, rekoč: Velik prorok je vstal med nami, in Bog je obiskal ljudstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 17, 'In razglasi se ta beseda o njem po vsej Judeji in vseh sosednjih krajih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 18, 'In o vsem tem so sporočili Janezu učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 19, 'In pokliče dva izmed učencev svojih ter ju pošlje h Gospodu vprašat: Si li ti tisti, ki ima priti, ali naj čakamo druzega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 20, 'Ko torej moža prideta k Jezusu, rečeta: Janez Krstnik naju je poslal k tebi vprašat: Si li ti tisti, ki ima priti, ali naj čakamo druzega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 21, 'Ravno tisto uro pa jih je mnogo ozdravil bolezni in muk in hudobnih duhov in mnogim slepcem je dal vid.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 22, 'In Jezus odgovori in jima reče: Pojdita in sporočita Janezu, kar sta videla in slišala: slepci izpregledujejo, hromci hodijo, gobavci se očiščajo, gluhi slišijo, mrtvi vstajajo, ubogim se oznanja evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 23, 'In blagor mu, kdor se ne pohujša nad menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 24, 'In ko sta poslanca Janezova odšla, začne govoriti množici o Janezu: Kaj ste šli v puščavo gledat? Trst, ki ga veter maje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 25, 'Ali kaj ste šli, da vidite? Človeka, ki se oblači v mehka oblačila? Glej, kateri se oblačijo v gosposko obleko in živé v slasteh, bivajo v kraljevih dvorih. Ali koga ste šli gledat? Proroka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 26, 'Da, pravim vam, in še več nego proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 27, 'Ta je, o katerem je pisano: „Glej, jaz pošiljam angela svojega pred obličjem tvojim, ki pripravi tvojo pot pred teboj.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 28, 'Pravim vam: Nobeden izmed rojenih od žen ni večji od Janeza; a kdor je najmanjši v kraljestvu Božjem, je večji od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 29, 'In vsi ljudje, ki so ga slišali, in cestninarji so priznali pravičnost Bogu, krstivši se s krstom Janezovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 30, 'A farizeji in učeniki postave so zavrgli sklep Božji sami zoper sebe, ko se mu niso dali krstiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 31, 'Komu torej naj primerjam ljudi tega rodu? in komu so podobni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 32, 'Podobni so otrokom, ki posedajo po ulicah in si med seboj kličejo in pravijo: Piskali smo vam, in niste plesali; žalostinke smo vam peli, in niste jokali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 33, 'Janez Krstnik je namreč prišel in ne jé kruha in ne pije vina, pa pravite: Hudiča ima!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 34, 'Prišel je Sin človekov in jé in pije, pa pravite: Glejte ga človeka požeruha in pijanca, mitarjev in grešnikov prijatelja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 35, 'A modrost Božjo so opravičili vsi njeni otroci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 36, 'Prosil ga pa je eden izmed farizejev, naj bi jedel ž njim; in gre v hišo farizejevo ter sede za mizo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 37, 'In glej, žena, ki je bila v mestu grešnica, prinese, ko zve, da sedi za mizo v hiši farizejevi, alabastrovo steklenico mazila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 38, 'in se ustopi jokaje odzadaj k nogam njegovim ter začne močiti noge njegove s solzami in jih otirati z lasmi svoje glave, in mu poljublja noge in jih mazili z mazilom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 39, 'Ko pa to vidi farizej, ki ga je bil povabil, pravi sam pri sebi takole: Ako bi bil ta prorok, bi pač vedel, kdo in kakšna žena je, ki se ga dotika, kajti grešnica je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 40, 'In odgovori Jezus in mu reče: Simon, imam ti nekaj povedati. On pa reče: Učenik, povej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 41, 'Neki upnik ima dva dolžnika; eden mu je dolžen petsto denarjev, a drugi petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 42, 'Ker pa nimata s čim plačati, odpusti obema. Povej torej, kateri od njiju ga bo bolj ljubil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 43, 'Odgovori Simon in reče: Menim, da tisti, kateremu je več odpustil. On pa mu reče: Prav si razsodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 44, 'In obrnivši se k ženi, pravi Simonu: Vidiš to ženo? Prišel sem v hišo tvojo, vode mi nisi podal za noge; a ta mi je s solzami močila noge in jih otirala s svojimi lasmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 45, 'Nisi me poljubil; ta pa ni nehala, odkar sem prišel noter, poljubovati noge moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 46, 'Z oljem nisi mazilil glave moje, a ta mi je z mazilom pomazilila noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 47, 'Zato ti pravim: Odpuščeni so ji mnogi grehi njeni, kajti imela je veliko ljubezen; a komur se malo odpušča, malo ljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 48, 'Njej pa reče: Odpuščeni so ti grehi tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 49, 'In začno, ki so ž njim sedeli pri mizi, govoriti v sebi: Kdo je ta, ki celó grehe odpušča?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 7, 50, 'On pa reče ženi: Vera tvoja te je rešila, pojdi v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 1, 'In zgodi se v naslednjem času, da on hodi po mestih in vaseh, propovedujoč in oznanjujoč blagovestje o kraljestvu Božjem, in ž njim dvanajsteri');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 2, 'in nekatere žene, ki so bile ozdravljene hudobnih duhov in bolezni: Marija, ki se imenuje Magdalena, iz katere je bilo izšlo sedem zlih duhov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 3, 'Joana, žena Huza, oskrbnika Herodovega, in Suzana in mnogo drugih, ki so mu služile z imetjem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 4, 'Ko se je pa velika množica sešla in so se ljudje od mesta do mesta nabirali okrog njega, jim govori v priliki:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 5, 'Sejalec je šel sejat seme svoje. In ko seje, pade nekatero poleg ceste, in ga pogazijo, in ptice nebeške ga pozobljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 6, 'In drugo pade na skalo, in bržko vzraste, usahne, ker nima vlage.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 7, 'In drugo pade sredi trnja, in trnje zraste ž njim vred in ga uduši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 8, 'In drugo pade na dobro zemljo, in ko zraste, prinese stoteren sad. Ko to pravi, zakliče: Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 9, 'Vprašujejo ga pa učenci njegovi, kakšna je ta prilika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 10, 'On pa reče: Vam je dano, da spoznate skrivnosti kraljestva Božjega, drugim pa se daje v prilikah, da gledajo in ne vidijo, ter slišijo in ne umejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 11, 'Ta prilika pa je: Seme je beseda Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 12, 'A kateri so poleg ceste posejani, so ti, ki slišijo, a potem pride hudič in vzame besedo iz njih srca, da ne bi verovali in se zveličali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 13, 'A kateri so na skalo posejani, so ti, ki besedo, ko jo slišijo, z veseljem sprejemajo; a ti nimajo korenine, ker nekaj časa verujejo, a v čas izkušnjave odpadejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 14, 'Kar pa pade v trnje, to so ti, ki slišijo, ali ker hodijo za skrbmi in bogastvom in slastmi življenja, se s tem zaduše in ne obrode dozorelega sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 15, 'Kar pa pade na dobro zemljo, to so ti, ki v dobrem in blagem srcu hranijo besedo, ki so jo slišali, in prinašajo sad v potrpljenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 16, 'Nihče pa sveče, ko jo prižge, ne pokrije s posodo ali je ne dene pod posteljo, marveč jo postavi na svečnik, da tisti, ki prihajajo, vidijo luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 17, 'Kajti nič ni prikritega, kar se ne bo razodelo, tudi skrivnega ne, kar se ne bo zvedelo in prišlo na svetlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 18, 'Glejte torej, kako poslušate! Kajti kdor ima, se mu bo dalo, a kdor nima, se mu vzame tudi to, kar misli, da ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 19, 'Pridejo pa k njemu mati njegova in bratje njegovi; ali spričo množice se ne morejo sniti ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 20, 'In sporoče mu, rekoč: Mati tvoja in bratje tvoji stoje zunaj, in radi bi te videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 21, 'On pa odgovori in jim reče: Mati moja in bratje moji so ti, ki besedo Božjo poslušajo in delajo po njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 22, 'Zgodi se pa nekega teh dni, da stopi v ladjo on in učenci njegovi. In reče jim: Prepeljimo se na oni kraj jezera. In odrinejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 23, 'Med vožnjo pa zaspi. Kar se pripodi silen vihar na jezero in valovi zagrinjajo ladjo, in bili so v nevarnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 24, 'In pristopijo in ga zbude, rekoč: Učenik, učenik, pogibljemo! A on vstane, zapreti vetru in besnečemu valovju, in pomirita se, in nastane tišina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 25, 'Reče pa jim: Kje je vera vaša? Oni pa se boje in čudijo ter govore drug drugemu: Kdo neki je ta, da tudi vetrovom in vodi zapoveduje, in ga poslušajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 26, 'In priplovejo v zemljo Gerazenov, ki je Galileji nasproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 27, 'Ko pa izstopi na kopno, mu pride nasproti mož iz mesta, ki je imel zle duhove in se že dolgo časa ni oblačil v obleko, tudi v hiši ni prebival, temuč v grobih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 28, 'Ko pa ugleda Jezusa, zakriči in pade predenj in kliče z močnim glasom: Kaj imaš z menoj, Jezus, Sin Boga Najvišjega? Prosim te, nikar me ne muči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 29, 'Ukazal je bil namreč nečistemu duhu, naj odide iz tega človeka. Kajti že dolgo časa ga je grabil, in vezali so ga z verigami in železjem ter ga varovali; ali raztrgaval je vezi, in zli duh ga je gonil v puščave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 30, 'Vpraša pa ga Jezus: Kako ti je ime? On pa reče: Legijon; kajti obsedlo ga je bilo mnogo zlih duhov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 31, 'In duhovi ga prosijo, naj jim ne zapove iti v brezno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 32, 'Bila je pa tam velika čreda svinj, ki so se pasle po gori; in ga poprosijo, naj jim dovoli, da gredo vanje. In jim dovoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 33, 'In zli duhovi izidejo iz človeka in gredo v svinje, in čreda se zakadi z brega v jezero, in potonejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 34, 'Pastirji pa, ko so videli, kar se je zgodilo, pobegnejo in sporoče to po mestu in po deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 35, 'Ljudje pa gredo gledat, kaj se je zgodilo; in pridejo k Jezusu in vidijo človeka, iz katerega so bili izšli zli duhovi, oblečenega in da pameten sedi pri nogah Jezusovih; in zbojé se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 36, 'Sporoče pa jim ti, ki so videli, kako je bil obsedenec ozdravljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 37, 'In zaprosi ga vsa množica iz okolice Gerazenov, naj gre od njih: kajti velik strah jih je prevzel. A on stopi v ladjo in se vrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 38, 'Prosi ga pa mož, iz katerega so bili odšli zli duhovi, da bi smel ostati ž njim; ali Jezus ga odpravi, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 39, 'Vrni se na dom svoj in pripoveduj, koliko ti je storil Bog. In on odide in oznanjuje po vsem mestu, koliko mu je storil Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 40, 'Zgodi se pa, ko se vrne Jezus, da ga ljudstvo z veseljem sprejme; kajti vsi so ga pričakovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 41, 'In glej, pride mož, po imenu Jair, in ta je bil načelnik shodnice, in pade Jezusu pred noge in ga prosi, naj pride v hišo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 42, 'Imel je namreč hčer edinico pri dvanajstih letih, in ta je umirala. Ko pa gre tja, ga stiskajo množice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 43, 'In žena, ki je imela krvotok že dvanajst let in je vse imetje svoje potrošila za zdravnike, ki je pa ni mogel nihče ozdraviti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 44, 'se pririne od zadaj in se dotakne robu obleke njegove, in takoj se ustavi vir krvi njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 45, 'In reče Jezus: Kdo je, ki se me je dotaknil? Ko pa vsi zanikavajo, reče Peter in kateri so bili ž njim: Učenik, saj te množica gnete in stiska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 46, 'Jezus pa reče: Nekdo se me je dotaknil, zakaj čutil sem, da je izšla moč od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 47, 'Ko pa vidi žena, da ni ostala prikrita, pristopi trepetaje in pade predenj in mu pove pred vsem ljudstvom, zakaj se ga je doteknila in kako je kar precej ozdravela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 48, 'On ji pa reče: Hči, vera tvoja te je rešila; pojdi v miru!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 49, 'Ko še govori, pride nekdo od načelnika shodnice, rekoč: Umrla je hči tvoja, ne trudi več učenika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 50, 'Jezus pa to zasliši in mu odgovori: Ne boj se, le veruj, in oteta bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 51, 'Ko pa pride v hišo, ne dovoli nikomur, da bi šel ž njim noter, razen Petru in Jakobu in Janezu in očetu in materi deklice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 52, 'Vsi pa so jokali in žalovali za njo. On pa reče: Ne jokajte, ni umrla, ampak spi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 53, 'In posmehujejo se mu, vedoč, da je umrla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 54, 'On pa jo prime za roko ter zakliče, rekoč: Deklica, vstani!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 55, 'In njen duh se vrne, in ona takoj vstane; in ukaže jim, naj ji dado jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 8, 56, 'In njena roditelja se zavzameta; a on jima naroči, naj nikomur ne povesta, kar se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 1, 'Skliče pa dvanajstere učence svoje in jim dá moč in oblast nad vsemi zlimi duhovi in da ozdravljajo bolezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 2, 'In pošlje jih oznanjevat kraljestvo Božje in ozdravljat bolnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 3, 'In reče jim: Ničesar ne jemljite na pot, ne palice, ne torbe, ne kruha, ne denarja; tudi po dve suknji ne imejte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 4, 'In v katerokoli hišo pridete, tam prebivajte, in odtod pojdite dalje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 5, 'In katerikoli vas ne sprejmejo, odidite iz tistega mesta in otresite prah z nog svojih, v pričevanje zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 6, 'In odidejo in hodijo po vaseh, oznanjujoč evangelij in ozdravljajoč povsod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 7, 'Slišal je pa Herod četrtnik vse, kar on dela, in je bil v zadregi, zato ker so nekateri pravili: Janez je vstal iz mrtvih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 8, 'nekateri pa: Elija se je prikazal, drugi pa: Starih prorokov eden je vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 9, 'In reče Herod: Janeza sem jaz obglavil; kdo je pa ta, ki slišim o njem take reči? In želel ga je videti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 10, 'In apostoli se vrnejo in mu pripovedujejo, koliko so storili. In vzame jih s seboj in se umakne v stran k mestu, ki se imenuje Betsaida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 11, 'Ko pa množice to zvedo, odidejo za njim; in sprejme jih in jim govori o kraljestvu Božjem in ozdravlja tiste, ki so potrebovali zdravja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 12, 'A dan se je jel nagibati, in pristopijo dvanajsteri in mu reko: Odpusti ljudstvo, da gredo v sosednje vasi in sela in tam prenočé in dobe živeža; kajti tu smo na samotnem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 13, 'On pa jim reče: Dajte jim vi jesti. A oni reko: Nimamo več nego pet hlebov in dve ribi; razen če gremo morda mi, da kupimo jedi za vse to ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 14, 'Bilo jih je namreč kakih pet tisoč mož. Reče pa učencem svojim: Posadite jih v druščinah po petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 15, 'In storé tako in posade vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 16, 'Vzame pa petere hlebe in tisti dve ribi in pogleda v nebo in jih blagoslovi ter prelomi in podaja učencem svojim, naj polože pred ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 17, 'In jedli so in se nasitili vsi; in pobrali so, kar jim je ostalo od koscev, dvanajst košev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 18, 'In zgodi se, ko je na samem molil, da so bili ž njim učenci njegovi; in vpraša jih, rekoč: Kdo pravijo ljudje, da sem jaz?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 19, 'Oni pa odgovore in reko: Da si Janez Krstnik, drugi pa: Elija, a drugi, da je eden starih prorokov vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 20, 'Pa jim reče: Kdo pa pravite vi, da sem jaz? Peter pa odgovori in reče: Kristus Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 21, 'A on jim zapreti in naroči, naj nikomur ne povedo tega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 22, 'govoreč: Sin človekov mora veliko pretrpeti in biti zavržen od starejšin in višjih duhovnikov in pismarjev in biti umorjen, a tretji dan vstati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 23, 'Pravi pa vsem: Če kdo hoče za menoj iti, naj zataji samega sebe in vzame nase križ svoj vsak dan in gre za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 24, 'Kajti kdor hoče ohraniti življenje svoje, ga izgubi, kdor pa izgubi življenje svoje zaradi mene, ta ga ohrani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 25, 'Kaj namreč pomaga človeku, če pridobi ves svet, samega sebe pa pogubi ali se oškoduje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 26, 'Zakaj kdorkoli se sramuje mene in mojih besed, tega se bo Sin človekov sramoval, kadar pride v svoji in Očetovi in svetih angelov slavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 27, 'Pravim vam pa resnično: So nekateri med tukaj stoječimi, ki ne okusijo smrti, dokler ne vidijo kraljestva Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 28, 'Zgodi se pa kakih osem dni po teh besedah, da vzame s seboj Petra in Jakoba in Janeza ter gre na goro molit.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 29, 'In ko moli, postane podoba obličja njegovega drugačna in oblačilo njegovo belo in svetlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 30, 'In glej, ž njim govorita dva moža, ki sta bila Mojzes in Elija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 31, 'Ta sta se prikazala v slavi in sta govorila o njegovem odhodu s sveta, ki mu ga je bilo izvršiti v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 32, 'A Petra in onadva, ki sta bila ž njim, prevzame spanec. Ko pa se vzdramijo, vidijo slavo njegovo in oba moža, ki sta ž njim stala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 33, 'In zgodi se, ko onadva odhajata od njega, da reče Peter Jezusu: Učenik, dobro nam je tu biti; naredimo pa tri šatore, tebi enega in Mojzesu enega in Eliju enega - ne vedoč, kaj govori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 34, 'Ali ko še govori, nastane oblak in jih obsenči; in zboje se, ko gresta onadva v oblak.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 35, 'In glas pride iz oblaka, ki pravi: Ta je Sin moj ljubljeni, njega poslušajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 36, 'In ko se je bil glas oglasil, najdejo Jezusa samega. In oni to zamolče, in nikomur niso v tistih dnevih povedali nič tega, kar so bili videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 37, 'Zgodi se pa drugi dan, ko pridejo z gore, da ga sreča velika množica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 38, 'In glej, mož izmed množice zavpije, rekoč: Učenik prosim te, ozri se na sina mojega, kajti edinec mi je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 39, 'In glej, duh ga napada, da nenadoma začne kričati, in ga lomi, da se ves peni, in le s težavo ga zapušča, ko ga je hudo zvil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 40, 'In prosil sem učence tvoje, naj bi ga izgnali, a niso mogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 41, 'Odgovori pa Jezus in reče: O rod neverni in popačeni, doklej bom pri vas in vas bom trpel? Pripelji sem sina svojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 42, 'A še medtem, ko gre k njemu, ga zgrabi zli duh in lomi. Jezus pa zapreti nečistemu duhu, in ozdravi dečka in ga spet da očetu njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 43, 'In vsi so se čudili veličastvu Božjemu. Ko so se pa vsi čudili vsemu temu, kar je delal Jezus, reče učencem svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 44, 'Ohranite vi v ušesih svojih te besede; kajti Sin človekov bo izdan v roke človeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 45, 'Oni pa niso umeli te besede, in bila jim je prikrita, da ne bi je razumeli, in bali so se ga poprašati o tej besedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 46, 'Polasti pa se jih razmišljanje, kdo bi bil največji med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 47, 'Jezus pa, vedoč misel njih srca, vzame otroka in ga postavi poleg sebe');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 48, 'in jim reče: Kdorkoli sprejme tega otroka v imenu mojem, mene sprejme; a kdorkoli mene sprejme, sprejme tega, ki me je poslal. Kdor je namreč najmanjši med vami vsemi, ta je velik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 49, 'Odgovori pa Janez in reče: Učenik, videli smo nekoga, ki je z imenom tvojim izganjal zle duhove, in smo mu branili, ker ne hodi z nami za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 50, 'Jezus mu pa reče: Ne branite! kajti kdor ni zoper vas, je za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 51, 'Zgodi se pa, ko so se dopolnjevali dnevi, da bi bil vzet gori, da on trdno nameri obličje svoje na pot v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 52, 'In pošlje poslance pred obličjem svojim; in ti gredo in pridejo v vas Samarijanov, da mu pripravijo prenočišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 53, 'Ali niso ga sprejeli, ker je bilo obličje njegovo namerjeno na pot v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 54, 'Ko pa to vidita učenca njegova Jakob in Janez, rečeta: Gospod, hočeš li, da rečeva, da ogenj pade z neba in jih pokonča, kakor je tudi Elija storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 55, 'On pa se obrne in jim zapreti in reče: Ne veste, kakšnega duha ste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 56, 'Sin človekov namreč ni prišel duš človeških pogubljat, ampak reševat. In šli so v drugo vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 57, 'In ko so šli, mu reče nekdo po poti: Za teboj hočem iti, kamorkoli pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 58, 'In reče mu Jezus: Lisice imajo brloge in ptice nebeške gnezda, a Sin človekov nima, kamor bi naslonil glavo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 59, 'A drugemu veli: Pojdi za menoj! On pa reče: Gospod, dovoli mi, da grem prej pokopat očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 60, 'A Jezus mu veli: Pusti, naj mrtvi pokopavajo mrliče svoje; ti pa pojdi in oznanjuj kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 61, 'Reče pa tudi nekdo drugi: Za teboj hočem iti, Gospod, ali prej mi dovoli, da se poslovim od domačinov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 9, 62, 'Jezus pa mu reče: Nobeden ni pripravljen za kraljestvo Božje, kdor prime z roko za plug, pa se ozira na to, kar je zadaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 1, 'Potem pa izvoli Gospod še drugih sedemdeset in jih pošlje po dva in dva pred obličjem svojim v vsako mesto ali kraj, kamor je imel sam priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 2, 'In pravil jim je: Žetve je sicer mnogo, ali delavcev malo; prosite Gospodarja žetve, naj pošlje delavcev na žetev svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 3, 'Pojdite! Glejte, pošiljam vas kakor jagnjeta med volkove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 4, 'Ne nosite mošnje, ne torbe, ne obuvala, in nikogar na poti ne pozdravljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 5, 'V katerokoli hišo pa pridete, najprej recite: Mir tej hiši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 6, 'In če je tu sin miru, bo počival mir vaš na njem; če pa ne, se vrne zopet k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 7, 'A v tej hiši ostanite in jejte in pijte, kar imajo; kajti vreden je delavec plačila svojega. Ne prehajajte iz hiše v hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 8, 'In v katerokoli mesto pridete in vas sprejmo, jejte, kar vam postavijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 9, 'in ozdravljajte bolnike, ki so v njem, in jim pravite: Približalo se je k vam kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 10, 'A v katerokoli mesto pridete in vas ne sprejmo, pojdite na ulice njegove in recite:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 11, 'Tudi prah iz vašega mesta, ki se nam je nog prijel, otresamo na vas; toda vedite to, da se je približalo kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 12, 'Pravim vam, da bo Sodomi tisti dan laže nego temu mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 13, 'Gorje ti, Korazin! gorje ti, Betsaida! zakaj, ko bi se bili v Tiru in Sidonu zgodili čudeži, ki so se zgodili v vaju, bi se bila davno, v raševniku in pepelu sedeč, izpokorila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 14, 'Ali Tiru in Sidonu bo laže na sodbi nego vama.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 15, 'In ti, Kafarnavm, ali nisi bil povzdignjen do neba? a pahnjen boš do pekla!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 16, 'Kdor vas posluša, mene posluša, in kdor vas zaničuje, mene zaničuje, kdor pa mene zaničuje, zaničuje njega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 17, 'Vrnejo se pa sedemdeseteri z veseljem, govoreč: Gospod, tudi zli duhovi so nam pokorni v imenu tvojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 18, 'On pa jim reče: Videl sem satana, da je padel z neba kakor blisk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 19, 'Glejte, dal sem vam oblast, stopati na kače in škorpijone, in oblast nad vso silo sovražnikovo, in nič vam ne bo škodovalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 20, 'Toda tega se ne veselite, da so vam duhovi pokorni; veselite se marveč, da so imena vaša zapisana v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 21, 'V tisto uro se razveseli Jezus v svetem Duhu in reče: Hvalim te, Oče, Gospodar neba in zemlje! da si to skril modrim in razumnim in razodel nedoraslim; da, Oče, ker tako je bila volja tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 22, 'Vse mi je izročil Oče moj, in nihče ne ve, kdo je Sin, razen Oče, in kdo je Oče, razen Sin in komurkoli hoče Sin razodeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 23, 'In obrnivši se k učencem posebe, reče: Blagor očem, ki vidijo, kar vi vidite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 24, 'Kajti pravim vam, da je veliko prorokov in kraljev želelo videti, kar vi vidite, a niso videli, in slišati, kar vi slišite, a niso slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 25, 'In glej, učenik postave vstane in izkušajoč ga, reče: Učenik, kaj naj storim, da podedujem večno življenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 26, 'On pa mu reče: V zakonu kaj je pisano? kako bereš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 27, 'On pa odgovori in reče: „Ljubi Gospoda, Boga svojega, iz vsega srca svojega in iz vse duše svoje in iz vse moči svoje in iz vse pameti svoje, bližnjega svojega pa kakor samega sebe“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 28, 'Pa mu reče: Prav si odgovoril; to delaj, in živel boš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 29, 'On pa, hoteč samega sebe opravičiti, reče Jezusu: In kdo je moj bližnji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 30, 'Jezus odgovori in reče: Neki človek je šel iz Jeruzalema doli v Jeriho in zajde med razbojnike, ki ga tudi slečejo in ranijo ter odidejo, pustivši ga napol mrtvega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 31, 'Po naključbi pa pride neki duhovnik doli po tisti poti, in ko ga vidi, gre mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 32, 'Enako pa pride tudi levit na tisto mesto in ko ga vidi, gre mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 33, 'Neki Samarijan pa, ko je tod potoval, pride do njega, in ko ga ugleda, se mu zasmili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 34, 'in pristopi ter mu obveže rane in vlije vanje olja in vina; in posadivši ga na svoje živinče, ga pripelje v gostilnico in poskrbi zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 35, 'Drugi dan pa vzame dva denarja iz mošnje in da gostilničarju in mu reče: Skrbi zanj, in karkoli več potrošiš, ti poplačam jaz, kadar se vrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 36, 'Kdo od teh treh, meniš, je bil bližnji temu, ki je zašel med razbojnike?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 37, 'On pa reče: Tisti, ki mu je izkazal usmiljenje. Jezus mu pa veli: Pojdi, tudi ti delaj enako!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 38, 'Ko pa potujejo dalje, pride on v neko vas; a žena, po imenu Marta, ga sprejme v hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 39, 'In ta je imela sestro, ki se je imenovala Marija, ki je tudi sedla k nogam Gospodovim in je poslušala besedo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 40, 'A Marta je bila zadržana, ker si je dala veliko opravka s postrežbo; ter pristopi in reče: Gospod, ali ti nič ni mar, da me je moja sestra samo pustila, da strežem? Reci ji torej, naj mi pomaga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 41, 'Gospod pa odgovori in ji reče: Marta, Marta, skrbiš in trudiš se za mnogo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 10, 42, 'le eno pa je potrebno. Marija si je izvolila dobri del, ki se ji ne odvzame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 1, 'In zgodi se, ko je na nekem kraju molil, da mu reče, ko je nehal, eden učencev njegovih: Gospod, nauči nas moliti, kakor je tudi Janez naučil učence svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 2, '§ On pa jim reče: Kadar molite, recite: Oče naš, ki si v nebesih, posvečeno bodi ime tvoje. Pridi kraljestvo tvoje. Zgodi se volja tvoja kakor v nebesih tudi na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 3, 'Kruh naš vsakdanji daj nam vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 4, '§ In odpusti nam grehe naše, ker tudi mi odpuščamo vsakemu dolžniku svojemu. In ne vpelji nas v izkušnjavo, temuč reši nas zlega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 5, 'In reče jim: Kdo izmed vas ima prijatelja, in pojde k njemu opolnoči in mu poreče: Prijatelj, posodi mi tri hlebe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 6, 'ker je prijatelj moj prišel s pota k meni, pa mu nimam kaj postaviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 7, 'Oni pa bi odznotraj odgovoril in rekel: Ne bodi mi nadležen: duri so že zaprte in otroci moji so z menoj v postelji; ne morem vstati in ti dati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 8, 'Pravim vam, čeprav ne vstane, da bi mu dal zato, ker mu je prijatelj, vstane vsaj zaradi nadležnega moledovanja njegovega in mu da, kolikor potrebuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 9, 'In jaz vam pravim: Prosite, in dalo se vam bo; iščite, in našli boste; trkajte, in odprlo se vam bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 10, 'Kajti vsak, kdor prosi, prejme, in kdor išče, najde, in kdor trka, se mu odpre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 11, 'Kdo izmed vas pa je oče, in če ga prosi sin kruha, pa mu da kamen? ali če prosi ribe, pa mu da namesto ribe kačo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 12, 'ali če prosi jajca, pa mu da škorpijona?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 13, 'Če torej vi, ki ste hudobni, znate dobre darove dajati otrokom svojim, koliko bolj bo dal Oče nebeški svetega Duha tem, ki ga prosijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 14, 'In izganjal je zlega duha, in ta je bil mutast. Zgodi se pa, ko je zli duh izšel, da mutec izpregovori; in množice se začudijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 15, 'A nekateri izmed njih reko: Z Belzebulom, poglavarjem hudičev, izganja zle duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 16, 'Drugi pa, izkušajoč ga, zahtevajo od njega znamenja z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 17, 'On pa, vedoč njih misli, jim reče: Vsako kraljestvo, ki se je samo zoper sebe razdvojilo, propade, in dom, zoper sebe razdvojen, razpade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 18, 'Če se je pa tudi satan zoper sebe razdvojil, kako bo ostalo kraljestvo njegovo? ker pravite, da z Belzebulom izganjam zle duhove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 19, 'A če jaz z Belzebulom izganjam zle duhove, s čigavo pomočjo jih izganjajo sinovi vaši? Zato vam bodo oni sodniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 20, 'Če pa s prstom Božjim izganjam zle duhove, torej je že prišlo k vam kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 21, 'Kadar se močni dobro oboroži in varuje dvor svoj, je v miru imetje njegovo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 22, 'ako pa pride nanj močnejši od njega in ga premaga, mu pobere vse orožje njegovo, v katero je upal, in razdeli njegov plen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 23, 'Kdor ni z menoj, je zoper mene, in kdor ne zbira z menoj, razsiplje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 24, 'Kadar nečisti duh izide iz človeka, hodi po suhih krajih in išče pokoja; in ko ga ne najde, pravi: Vrnil se bom na dom svoj, odkoder sem izšel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 25, 'In ko pride tja, ga najde pometenega in olepšanega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 26, 'Tedaj odide in vzame sedem drugih duhov, hujših od sebe, in gredo vanj in tu prebivajo: in poslednje tega človeka postane hujše od prvega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 27, 'Zgodi se pa, ko je to govoril, da povzdigne neka žena izmed množice glas svoj in mu reče: Blagor telesu, ki te je nosilo, in prsim, ki si jih sesal!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 28, 'On pa veli: Veliko bolj blagor tem, ki besedo Božjo poslušajo in jo hranijo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 29, 'Ko so se pa množice zbirale pri njem, jim začne govoriti: Ta rod je hudoben rod: znamenja išče, ali ne bo se mu dalo znamenje, razen znamenja Jona proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 30, 'Kakor je bil namreč Jona znamenje Ninivljanom, tako bo tudi Sin človekov znamenje temu rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 31, 'Kraljica od juga vstane na sodbo z možmi tega rodu in jih obsodi; kajti prišla je od kraja sveta poslušat modrost Salomonovo; in glej, večji je tu od Salomona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 32, 'Možje Ninivljani vstanejo na sodbo s tem rodom in ga obsodijo; kajti izpokorili so se po propovedi Jonovi; in glej, večji je tu od Jona.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 33, 'Nihče pa ne dene sveče, ko jo prižge, na skrit kraj, tudi ne pod mernik, ampak na svečnik, da vidijo luč, kateri prihajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 34, 'Svetilo telesu tvojemu je oko: kadar je torej oko tvoje zdravo, je svetlo tudi vse telo tvoje; ko pa je pokvarjeno, je temno tudi telo tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 35, 'Zato glej, da ne bo luč, ki je v tebi, tema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 36, 'Če je torej vse telo tvoje svetlo in nima nobenega temnega uda, bo vseskozi svetlo, kakor kadar te svetilnica obsije z jasno svetlobo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 37, 'Medtem pa, ko je govoril, ga zaprosi neki farizej, naj bi obedoval pri njem. Prišedši pa tja, sede za mizo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 38, 'Ko pa to vidi farizej, se začudi, da se ni prej umil pred obedom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 39, 'Gospod mu pa reče: Sedaj vi farizeji čistite kozarec in skledo odzunaj, kar je pa znotraj vas, je polno ropa in hudobije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 40, 'Neumneži, mar ni ta, ki je naredil to, kar je zunaj, naredil tudi tega, kar je znotraj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 41, 'Sicer pa dajte v miloščino tega, kar je notri, in glej, vse vam je čisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 42, 'Ali gorje vam farizejem, da dajete desetino od mete in od rute in od vsakega zelišča, izogibate se pa sodbe in ljubezni Božje: to je bilo treba storiti in onega ne opustiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 43, 'Gorje vam farizejem, da ljubite prve stole v shodnicah in pozdrave po ulicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 44, 'Gorje vam, da ste kakor skriti grobovi, po katerih ljudje hodijo in ne vedo zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 45, 'Odgovori pa eden izmed učenikov postave in mu reče: Učenik, s takimi besedami sramotiš tudi nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 46, 'On pa mu reče: Gorje tudi vam učenikom postave, ker nakladate ljudem neznosne butare, a sami se niti z enim prstom ne dotaknete butar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 47, 'Gorje vam, da zidate grobne spomenike prorokom, očetje vaši pa so jih pobili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 48, 'S tem torej ste priče delom očetov svojih in jih odobravate: kajti oni so jih pobili, a vi jim zidate nadgrobke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 49, 'Zato je tudi modrost Božje rekla: Pošljem k njim proroke in apostole, in nekatere njih umore in preženo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 50, 'da se bo zahtevala od tega rodu vseh prorokov kri, ki se je prelila od začetka sveta,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 51, 'od krvi Abelove, do krvi Zaharijeve, ki je poginil med oltarjem in svetiščem. Da, pravim vam, zahtevala se bo od tega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 52, 'Gorje vam učenikom postave, ker ste vzeli ključ do spoznanja: sami niste šli do njega, a tem, ki so hoteli vstopiti, ste zabranili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 53, 'Ko je pa odšel odtod, začno pismarji in farizeji zelo pritiskati nanj in ga vpraševati o raznoterih rečeh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 11, 54, 'prežeč nanj, da bi kaj ujeli iz ust njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 1, 'Ko se je bilo medtem zbralo na tisoče ljudstva, tako da so drug drugega tiščali, začne govoriti učencem svojim najprej: Varujte se kvasu farizejev, ki je hinavstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 2, 'Nič pa ni skritega, kar se ne bo odkrilo, in skrivnega, kar se ne bo zvedelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 3, 'Zato se bo vse, kar ste pravili v temi, slišalo na svetlem, in kar ste na uho šepetali v kleteh, se bo oznanjevalo na strehah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 4, 'Pravim pa vam, prijateljem svojim: Ne bojte se jih, ki ubijajo telo, a potem ne morejo ničesar več storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 5, 'Pokažem pa vam, koga se bojte: bojte se tistega, ki ima oblast, potem ko usmrti, zagnati v pekel. Da, pravim vam, tega se bojte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 6, 'Ne prodajajo li pet vrabcev po dva vinarja? in ne eden izmed njih ni pozabljen pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 7, 'A vam so tudi lasje na vsi glavi prešteti. Ne bojte se torej; boljši ste od mnogo vrabcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 8, 'Pravim vam pa: Vsakega, kdor pripozna mene pred ljudmi, pripozna tudi Sin človekov pred angeli Božjimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 9, 'kdor pa zataji mene pred ljudmi, zatajen bo pred angeli Božjimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 10, 'In vsakemu, kdor reče besedo zoper Sina človekovega, se odpusti, a kdor preklinja svetega Duha, mu ne bo odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 11, 'Kadar pa vas privlečejo v shodnice in h gosposki in pred oblasti, ne skrbite, kako ali s čim bi se zagovarjali ali kaj bi povedali:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 12, 'zakaj sveti Duh vas nauči v tisti uri, kaj je treba reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 13, 'Reče pa mu nekdo iz množice: Učenik, reci bratu mojemu, naj si razdeli z menoj dedino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 14, 'On mu pa reče: Človek, kdo me je postavil za sodnika ali delilca vama?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 15, 'In jim reče: Glejte in varujte se vsake lakomnosti; zakaj čeprav ima kdo preobilo, življenje mu vendar ne priteka iz imetja njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 16, 'Pove jim pa priliko, rekoč: Nekemu bogatemu človeku je njiva obilo obrodila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 17, 'In premišljuje v sebi in reče: Kaj naj storim, ker nimam kam spraviti letine svoje. Pa reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 18, 'To storim: poderem žitnice svoje in sezidam večje, in tu spravim vse pridelke svoje in blago svoje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 19, 'in porečem duši svoji: Duša, veliko blaga imaš za veliko let; počivaj, jej, pij, veseli se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 20, 'Reče pa mu Bog: Neumnež, to noč bodo zahtevali dušo tvojo od tebe, in kar si pripravil, čigavo bo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 21, 'Tako je s tem, kdor sebi zaklade nabira, pa se ne bogati v Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 22, 'Reče pa učencem svojim: Zato vam pravim: Ne skrbite za življenje svoje, kaj boste jedli, tudi za telo svoje ne, kaj boste oblekli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 23, 'Zakaj življenje je več nego hrana in telo več nego obleka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 24, 'Poglejte krokarje: ne sejejo in ne žanjejo, nimajo kleti, ne žitnice, in Bog jih živi: koliko ste vi boljši od ptic!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 25, 'Kdo izmed vas pa more s svojo skrbjo postavi svoji primekniti en komolec?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 26, 'Če torej tudi najmanjšega ne morete, čemu skrbite za drugo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 27, 'Poglejte lilije, kako rastejo: ne trudijo se in ne predejo; pravim vam pa: tudi Salomon v vsej svoji slavi ni bil oblečen kakor njih ena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 28, 'Če pa travo na polju, ki danes stoji, a jutri jo vržejo v peč, Bog tako oblači, koliko bolj vas, maloverneži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 29, 'Tudi vi ne iščite, kaj boste jedli ali kaj boste pili, in ne vznemirjajte se s takimi skrbmi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 30, 'zakaj vsega tega iščejo narodi tega sveta; a Oče vaš ve, da tega potrebujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 31, 'Marveč iščite kraljestva Božjega, in vse to vam bo pridano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 32, 'Ne boj se, mala čreda! kajti Oče vaš je sklenil, dati vam kraljestvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 33, 'Prodajte imetje svoje in dajajte miloščino. Napravite si mošnje, ki ne ostare, zaklad, ki ne izgine, v nebesih, kjer se tat ne približuje in tudi molj ne razjeda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 34, 'Kajti kjer je zaklad vaš, tam bo tudi srce vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 35, 'Naj vam bodo ledja opasana in sveče prižgane,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 36, 'in bodite podobni ljudem, ki pričakujejo gospodarja svojega, kdaj se vrne z ženitnine, da mu precej odpro, kadar pride in potrka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 37, 'Blagor tistim hlapcem, katere najde gospodar, kadar pride, čujoče. Resnično vam pravim, da se opaše in jih posadi za mizo, ter bo pristopil in jim stregel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 38, 'In če pride ob drugi straži ali če pride ob tretji straži in jih najde tako, blagor tistim hlapcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 39, 'Vedite pa to: Ko bi vedel hišni gospodar, ob kateri uri pride tat, bi čul in ne bi dal podkopati hiše svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 40, 'Zato bodite tudi vi pripravljeni, kajti Sin človekov pride ob uri, ko se vam ne bo dozdevalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 41, 'Reče pa Peter: Gospod, praviš li to priliko za nas ali tudi za vse?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 42, 'Gospod pa reče: Kdo neki je zvesti in modri oskrbnik, ki ga postavi gospodar nad družino svojo, naj jim daje odmerjeno hrano ob svojem času?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 43, 'Blagor tistemu hlapcu, ki ga najde njegov gospodar, kadar pride, da tako dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 44, 'Resnično vam pravim, da ga postavi nad vsem imetjem svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 45, 'Ako pa poreče ta hlapec v srcu svojem: Gospodar moj odlaša prihod svoj, in začne pretepati hlapce in dekle ter jesti in piti in pijančevati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 46, 'pride gospodar tega hlapca ob dnevu, ko ne pričakuje, in ob uri, katere ne ve, in ga preseka in delež mu dá med neverniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 47, 'Tisti hlapec pa, ki je vedel voljo gospodarja svojega, pa se ni pripravil in tudi ni storil po volji njegovi, bo zelo tepen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 48, 'a tisti, ki je ni vedel, pa je storil, kar je kazni vredno, bo malo tepen. Od vsakogar, komur je dano mnogo, se bo mnogo zahtevalo; in komur so izročili mnogo, od tega bodo toliko več zahtevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 49, 'Prišel sem, da vržem ogenj na zemljo, in kaj hočem, če že gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 50, 'S krstom pa imam biti krščen, in kako bridko mi je, dokler se ne dopolni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 51, 'Menite li, da sem prišel, da dam na zemljo mir? Nikakor, pravim vam, marveč razpor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 52, 'Kajti odslej jih bo pet v eni hiši razprtih, trije z dvema in dva s tremi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 53, 'oče se razpre s sinom in sin z očetom, mati s hčerjo in hči z materjo, tašča s snaho svojo in snaha s taščo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 54, 'Pravil je pa tudi množicam: Kadar vidite oblak, da se vzdiga od zahoda, precej pravite: Dež bo! In zgodi se tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 55, 'In kadar čutite, da vleče jug, pravite: Vroče bo! In zgodi se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 56, 'Hinavci, lice zemlje in neba veste presojati, kako pa, da tega časa ne veste presojati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 57, 'Zakaj pa tudi sami od sebe ne sodite, kar je prav?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 58, 'Zato ko greš z nasprotnikom svojim k poglavarju, potrudi se po poti, da se ga rešiš, da te morda ne privleče k sodniku, in sodnik te izroči biriču, in birič te vrže v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 12, 59, 'Pravim ti, nikakor ne prideš iz nje, dokler ne plačaš tudi zadnjega vinarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 1, 'Bili so pa ravno ta čas tu nekateri, ki so mu poročali o Galilejcih, katerih kri je zmešal Pilat ž njih daritvami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 2, 'In Jezus odgovori in jim reče: Menite li, da so bili ti Galilejci največji grešniki med vsemi Galilejci, ker so to pretrpeli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 3, 'Ne, pravim vam, temuč če se ne izpokorite, poginete vsi tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 4, 'Ali tistih osemnajst, na katere je padel stolp v Siloamu in jih pobil: menite li, da so bili ti najbolj krivi med vsemi ljudmi, ki prebivajo v Jeruzalemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 5, 'Ne, pravim vam, temuč če se ne izpokorite, poginete vsi enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 6, 'Pravil je pa to priliko: Nekdo je imel smokvo zasajeno v vinogradu svojem; in prišel je iskat sadu na njej in ga ni našel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 7, 'Reče pa vinogradniku: Glej, tri leta je, odkar hodim iskat sadu na tej smokvi, in ga ne najdem. Posekaj jo torej! Čemu še trati zemljo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 8, 'On pa odgovori in reče: Gospod, pusti jo še to leto, da jo okopljem in ospem z gnojem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 9, 'da li prihodnjič rodi sad; če pa ne, posekaš jo potem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 10, 'Učil je pa v eni njih shodnic v soboto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 11, 'In glej, bila je tu žena, ki je imela duha bolezni osemnajst let in je bila sključena ter se nikakor ni mogla pokoncu vzkloniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 12, 'Ko pa jo Jezus ugleda, jo pokliče in ji reče: Žena, rešena si bolezni svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 13, 'In položi nanjo roke, in ona se pri tej priči zravna ter hvali Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 14, 'Izpregovori pa načelnik shodnice, jezeč se, da je Jezus zdravil v soboto, in reče ljudstvu: Šest dni je, v katerih velja delati; v teh torej pridite in se zdravite, ne pa sobotni dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 15, 'Gospod mu pa odgovori in reče: Hinavci, ali ne odvezuje vsak izmed vas v soboto svojega vola ali osla od jasli in ga ne goni napajat?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 16, 'Te žene pa, ki je hči Abrahamova in ki jo je bil satan zvezal, glej, že osemnajst let, ali je ni bilo treba rešiti te vezi v sobotni dan?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 17, 'In ko to pravi, se sramujejo vsi, ki so mu nasprotovali; vsa množica se pa raduje slavnih del, ki so se godila po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 18, 'Pravil je pa: Čemu je podobno kraljestvo Božje in čemu naj ga primerim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 19, 'Podobno je gorčičnemu zrnu, ki ga človek vzame in vrže na vrt svoj, in ono zraste in postane drevo, in ptice nebeške se nastanijo po vejah njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 20, 'In zopet reče: Čemu naj primerim kraljestvo Božje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 21, 'Podobno je kvasu, ki ga vzame žena in ga vmesi v tri merice moke, dokler se vse ne skvasi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 22, 'In hodil je po mestih in vaseh, učeč in potujoč proti Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 23, 'Reče mu pa nekdo: Gospod, je li pač malo teh, ki se zveličajo? On jim pa reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 24, 'Borite se, da vnidete skozi tesna vrata; zakaj veliko, pravim vam, si jih bo prizadevalo priti noter, pa ne bodo mogli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 25, 'Ko nekoč hišni gospodar vstane in zapre hišna vrata, tedaj začnete zunaj postajati in na vrata trkati, govoreč: Gospod, gospod, odpri nam! pa vam odgovori in poreče: Ne poznam vas, odkod ste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 26, 'Tedaj začnete praviti: Jedli smo pred teboj in pili, in po ulicah naših si učil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 27, 'Pa poreče: Pravim vam, ne poznam vas, odkod ste. Odstopite od mene vsi, ki delate krivico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 28, 'Tam bo jok in škripanje z zobmi, ko boste videli Abrahama in Izaka in Jakoba in vse proroke v kraljestvu Božjem, sebe pa izgnane zunaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 29, 'In pridejo od vzhoda in zahoda, od severa in juga, in bodo sedeli za mizo v kraljestvu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 30, 'In glej, so zadnji, ki bodo prvi, in prvi, ki bodo zadnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 31, 'Ravno to uro pristopijo k njemu nekateri farizeji, veleč mu: Izidi in pojdi odtod, ker Herod te hoče umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 32, 'In reče jim: Pojdite in povejte temu lisjaku: Glej, izganjam zle duhove in ozdravljam danes in jutri, a tretji dan dokončam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 33, 'Sicer pa moram danes in jutri in pojutrišnjem svojo pot nadaljevati, ker ni mogoče proroku poginiti zunaj Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 34, 'Jeruzalem, Jeruzalem, ki ubijaš proroke in kamenaš tiste, ki so k tebi poslani! Kolikokrat sem hotel zbrati otroke tvoje kakor kokla piščeta svoja pod peruti, a niste hoteli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 13, 35, 'Glej, zapušča se vam dom vaš pust. Pravim vam pa, da me ne boste videli, dokler ne pride čas, da porečete: Blagoslovljen, ki prihaja v imenu Gospodovem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 1, 'In zgodi se, ko pride v hišo enega izmed prvakov farizejskih v soboto jest kruh, da so oni nanj pazili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 2, 'In glej, vodeničen človek je bil pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 3, 'In Jezus izpregovori in reče učenikom postave in farizejem: Se li sme v soboto zdraviti ali ne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 4, 'Oni pa umolknejo. In ga prime in ozdravi in odpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 5, 'In jim reče: Kdo izmed vas, če mu pade osel ali vol v vodnjak, ga ne izvleče precej v sobotni dan?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 6, 'In niso mu mogli odgovoriti na to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 7, 'Povedal je pa povabljencem priliko, opazivši, kako si izbirajo prve prostore, govoreč jim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 8, 'Kadar te kdo povabi na svatovščino, ne sedi na prvi prostor, da ne bi bil kdo imenitnejši nego ti povabljen od njega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 9, 'in ne pride ta, ki je tebe in njega povabil, in ti ne reče: Daj temu prostor! in tedaj boš s sramoto sedel na zadnji prostor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 10, 'Ampak, kadar si povabljen, pojdi in sedi na zadnji prostor, da ti, ko pride, ki te je povabil, poreče: Prijatelj, pomakni se više! tedaj ti bo čast pred vsemi, ki sedé s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 11, 'Zakaj vsak, kdor se povišuje, bo ponižan; a kdor se ponižuje, bo povišan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 12, 'Pravil je pa tudi temu, ki ga je bil povabil: Kadar napraviš obed ali večerjo, ne vabi prijateljev svojih, ne bratov svojih, ne sorodnikov svojih, ne bogatih sosedov, da te morda tudi oni ne povabijo in ti povrnejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 13, 'Ampak, kadar napraviš gostijo, povabi siromake, kruljave, hrome, slepce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 14, 'in blagor ti bo, ker ti nimajo s čim povrniti; povrne se ti namreč ob vstajenju pravičnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 15, 'Ko je to slišal nekdo izmed teh, ki so sedeli ž njim za mizo, mu reče: Blagor mu, kdor bo jedel kruh v kraljestvu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 16, 'On pa mu reče: Neki človek je napravil veliko večerjo in mnogo jih je povabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 17, 'In pošlje hlapca svojega ob uri večerje, naj reče povabljencem: Pridite, ker je že vse pripravljeno!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 18, 'In začno se vsi hkratu izgovarjati. Prvi mu reče: Njivo sem kupil in silno mi je treba, da grem in jo ogledam; prosim te, izgovori me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 19, 'A drugi reče: Pet jarmov volov sem kupil in grem jih poskušat; prosim, izgovori me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 20, 'Zopet drugi pa: Oženil sem se, in zato ne morem priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 21, 'In hlapec pride in sporoči to gospodu svojemu. Tedaj se hišni gospodar razjezi in reče hlapcu svojemu: Idi hitro ven na ceste in ulice mestne in pripelji sem siromake in kruljave in hrome in slepce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 22, 'In hlapec reče: Gospod, zgodilo se je, kakor si ukazal, in še je prostora.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 23, 'Pa veli gospodar hlapcu: Pojdi ven na pota in za ograje in sili jih, naj pridejo, da se napolni hiša moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 24, 'Kajti pravim vam, da noben onih mož, ki so bili povabljeni, ne okusi večerje moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 25, 'Šlo je pa ž njim veliko ljudstva; in obrnivši se, jim reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 26, 'Če prihaja kdo k meni, pa ne sovraži očeta svojega in matere, žene in otrok, bratov in sester, da, tudi lastnega življenja svojega, ne more biti moj učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 27, 'Kdor ne nosi križa svojega in ne gre za menoj, ne more biti moj učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 28, 'Kdo namreč izmed vas, ki hoče sezidati stolp, ne sede prej in preračuni stroškov, če ima pač toliko, da ga dodela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 29, 'da se mu, ko bi postavil temelj, pa ne bi mogel dozidati, ne začno vsi, ki to vidijo, posmehovati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 30, 'govoreč: Ta človek je jel zidati, pa ni mogel dokončati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 31, 'Ali kateri kralj, kadar se gre z drugim kraljem vojskovat, ne sede prej in se posvetuje, če se pač more z desetimi tisočmi srečati s tem, ki pride proti njemu z dvajsetimi tisočmi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 32, 'Če pa ne more, pošlje poslance in prosi miru, dokler je še sovražnik daleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 33, 'Tako torej vsak izmed vas, kdor se ne odreče vsemu, kar ima, ne more biti moj učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 34, 'Dobra je sol; ako se pa tudi sol izpridi, s čim se bo osolila?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 14, 35, 'Ne da se rabiti ne za zemljo, ne za gnojišče; vržejo jo proč. Kdor ima ušesa, da sliši, naj sliši!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 1, 'Približevali pa so se mu vsi cestninarji in grešniki, da bi ga poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 2, 'In godrnjali so farizeji in pismarji, govoreč: Ta sprejema grešnike in ž njimi jé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 3, 'A on jim pove tole priliko, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 4, 'Kateri človek izmed vas, ki ima sto ovac in izgubi eno izmed njih, ne pusti devetindevetdeseterih v puščavi, pa gre za izgubljeno, dokler je ne najde?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 5, 'In ko jo najde, jo zadene vesel na rame svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 6, 'in ko pride domov, skliče prijatelje in sosede ter jim reče: Radujte se z menoj! zakaj našel sem ovco svojo, ki se je bila izgubila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 7, 'Pravim vam, da tako bode radost v nebesih večja nad enim grešnikom, ki se izpokori, nego nad devetindevetdeseterimi pravičnimi, katerim ni treba pokore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 8, 'Ali katera žena, ki ima deset srebrnikov, če izgubi en srebrnik, ne prižge sveče in ne pomete hiše ter išče skrbno, dokler ga ne najde?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 9, 'In ko ga najde, skliče prijateljice in sosedinje in reče: Radujte se z menoj! zakaj našla sem srebrnik, ki sem ga bila izgubila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 10, 'Tako, pravim vam, je tudi radost pred angeli Božjimi nad enim grešnikom, ki se izpokori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 11, 'In reče: Neki človek je imel dva sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 12, 'In mlajši reče očetu: Oče, daj mi del premoženja, ki mi pripada. In razdeli jima premoženje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 13, 'In čez nekoliko dni zbere mlajši sin vse in odpotuje v daljno deželo, in tu raztrosi premoženje svoje, živeč samopašno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 14, 'In ko je bil vse potratil, nastane huda lakota v tisti deželi, in on začne stradati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 15, 'In gre in se pridruži enemu izmed meščanov te dežele; in ta ga pošlje na svoje polje svinje past.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 16, 'In želel se je nasititi z rožiči, ki so jih svinje jedle, ali nihče mu jih ni dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 17, 'Ko pa pride sam v se, reče: Koliko najemnikov očeta mojega ima obilo kruha, jaz pa tu lakote pogibljem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 18, 'Vstanem, pojdem k očetu svojemu in mu porečem: Oče, grešil sem zoper nebo in pred teboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 19, 'nisem več vreden, da bi se sin tvoj imenoval: naredi me kakor enega najemnikov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 20, 'In vstane in gre k očetu svojemu. A ko je bil še daleč, ga ugleda oče njegov in se mu v srce zasmili ter priteče in se oklene vratu njegovega in ga poljublja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 21, 'A sin mu reče: Oče, grešil sem zoper nebo in pred teboj, in nisem več vreden, da bi se sin tvoj imenoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 22, 'Oče pa veli hlapcem svojim: Hitro prinesite najlepšo suknjo in oblecite ga; in denite mu prstan na roko in obuvalo na noge;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 23, 'in pripeljite tele pitano in ga zakoljite, in jejmo in se veselimo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 24, 'zakaj ta sin moj je bil mrtev, in je oživel, in izgubljen je bil, in se je našel. In začno se veseliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 25, 'A starejši sin njegov je bil na polju; in ko se gredoč približa hiši, zasliši godbo in ples');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 26, 'ter pokliče enega hlapcev in vpraša, kaj bi to bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 27, 'On mu pa reče: Brat tvoj je prišel, in oče tvoj je zaklal tele pitano, ker ga je zopet dobil zdravega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 28, 'On pa se razjezi in noče iti noter. Tedaj pride ven oče njegov ter ga prosi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 29, 'On pa odgovori in reče očetu svojemu: Glej, toliko let ti služim in nikoli nisem prestopil zapovedi tvoje, a meni nisi dal nikoli kozliča, da bi se s prijatelji svojimi razveselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 30, 'Ko je pa prišel ta sin tvoj, ki je zažrl premoženje tvoje z vlačugami, si mu zaklal tele pitano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 31, 'On mu pa reče: Sin, ti si vsekdar pri meni, in vse moje je tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 15, 32, 'Treba pa se je bilo veseliti in radovati, ker je bil ta brat tvoj mrtev in je oživel, in izgubljen je bil in se je našel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 1, 'Pravil je pa tudi učencem svojim: Bil je bogat človek, ki je imel oskrbnika; in tega so ovadili pri njem, kakor da bi mu razsipal imetje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 2, 'In pokliče ga ter mu reče: Kaj to slišim o tebi? Daj račun o gospodarstvu svojem, zakaj ne moreš mi dalje gospodariti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 3, 'A oskrbnik reče sam v sebi: Kaj naj storim, ker mi gospod moj jemlje oskrbništvo? Kopati ne morem, prositi me je sram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 4, 'Vem, kaj bom storil, da me sprejmo v hiše svoje, kadar bom odstavljen od oskrbništva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 5, 'In pokliče k sebi vse dolžnike svojega gospoda, vsakega posebe, in reče prvemu: Koliko si dolžen gospodu mojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 6, 'On pa reče: Sto meric olja. In reče mu: Vzemi svoje pismo, pa sedi hitro in napiši petdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 7, 'Potem reče drugemu: A ti, koliko si dolžen? On pa reče: Sto korcev pšenice. In veli mu: Vzemi svoje pismo in napiši osemdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 8, 'In gospodar pohvali krivičnega oskrbnika, ker je pametno storil; zakaj sinovi tega sveta so pametnejši v svojem rodu od sinov svetlobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 9, 'Tudi jaz vam pravim: Storite si prijateljev s krivičnim mamonom, da vas, kadar vam poide, sprejmo v večna stanovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 10, 'Kdor je v najmanjšem zvest, je zvest tudi v velikem, in kdor je v najmanjšem krivičen, je krivičen tudi v velikem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 11, 'Če torej v krivičnem mamonu niste bili zvesti, pravo bogastvo, kdo vam zaupa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 12, 'In če v tujem niste bili zvesti, kdo vam da, kar je vašega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 13, 'Noben hlapec ne more dvema gospodoma služiti; kajti ali bo enega sovražil in drugega ljubil, ali bo enemu vdan in bo drugega zaničeval. Ne morete Bogu služiti in mamonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 14, 'Poslušali so pa vse to tudi farizeji, ki so srebro ljubili, ter so ga zasmehovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 15, 'In jim reče: Vi ste tisti, ki se delate pravične pred ljudmi, ali Bog pozna srca vaša; kajti kar je pri ljudeh visoko, je gnusoba pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 16, 'Zakon in proroki so do Janeza, odtlej se oznanjuje blagovestje o kraljestvu Božjem, in vsak s silo tišči vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 17, 'Laže je pa nebu in zemlji preiti nego eni pičici iz postave izginiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 18, 'Vsak, kdor se loči od žene svoje in se oženi z drugo, prešeštvuje; in kdor vzame ločeno od moža, prešeštvuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 19, 'Bil je pa bogat človek in se je oblačil v škrlat in tenčico in se je razveseljeval vsak dan sijajno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 20, 'In bil je ubožec, po imenu Lazar, ki je ležal pred vrati njegovimi poln tvorov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 21, 'in se je želel nasititi z drobtinami, ki so padale z mize bogatinove; ali tudi psi so prihajali ter lizali gnoj njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 22, 'Zgodi se pa, da ubožec umre, in angeli ga odneso v naročje Abrahamovo; umrje pa tudi bogatin in je bil pokopan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 23, 'In v peklu, ko je bil v bolečinah, povzdigne oči svoje in ugleda Abrahama oddaleč in Lazarja v naročju njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 24, 'In zavpije in reče: Oče Abraham, usmili se me in pošlji Lazarja, naj omoči v vodi prsta svojega konec in mi ohladi jezik, ker se mučim v tem plamenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 25, 'Abraham pa reče: Sin, spomni se, da si ti prejel dobrote svoje v življenju svojem, in ravno tako Lazar hudo. Sedaj pa on tu uživa tolažbo, a ti se mučiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 26, 'In vrhu vsega tega, med nami in vami je utrjen velik prepad, da ne morejo, če kateri hočejo, odtod iti k vam, in tudi ne odondod preiti sem k nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 27, 'Pa reče: Prosim te torej, pošlji ga na mojega očeta dom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 28, 'Imam namreč pet bratov: da jim to izpriča, da ne pridejo tudi oni v ta kraj trpljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 29, 'Veli pa Abraham: Mojzesa imajo in proroke, poslušajo naj jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 30, 'On pa reče: Ne, oče Abraham, ampak če kdo od mrtvih pride k njim, se bodo izpokorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 16, 31, 'Pa mu reče: Če Mojzesa in prorokov ne poslušajo, se tudi ne dado prepričati, če kdo iz mrtvih vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 1, 'Reče pa učencem svojim: Ni mogoče, da ne bi bilo prilik za pohujšanje; toda gorje tistemu, po katerem prihajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 2, 'Bolje bi mu bilo, da mu obesijo mlinski kamen na vrat in ga vržejo v morje, nego da pohujša enega teh malih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 3, 'Varujte se! Ako se pregreši brat tvoj, posvari ga; in če se izpokori, odpusti mu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 4, 'In če se pregreši sedemkrat na dan zoper tebe, pa se sedemkrat na dan obrne do tebe, rekoč: Žal mi je! odpusti mu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 5, 'Reko pa apostoli Gospodu: Pomnoži nam vero!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 6, 'Gospod pa reče: Ako bi imeli vero, kolikšno je gorčično zrno, bi rekli tej murvi: Izderi se in presadi se v morje! in poslušala bi vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 7, 'Kdo izmed vas ima pa hlapca, ki orje ali pase, da bi mu, kadar pride s polja, rekel: Precej pojdi in sedi za mizo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 8, 'Ne poreče li mu marveč: Pripravi, kar bom večerjal, in opaši se ter mi strezi, dokler se ne najem in napijem, in potem jej in pij ti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 9, 'Ali se mar zahvali hlapcu, da je storil, kar mu je bilo ukazano? Nikar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 10, 'Tako tudi vi, kadar storite vse, kar vam je ukazano, recite: Nepridni hlapci smo; storili smo le, kar smo bili dolžni storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 11, 'In zgodi se ob njegovem potovanju v Jeruzalem, da gre sredi med Samarijo in Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 12, 'In ko pride v neko vas, ga sreča deset gobavih mož, ki so stali oddaleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 13, 'In ti povzdignejo glas, rekoč: Jezus, učenik, usmili se nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 14, 'In ko jih ugleda, jim reče: Pojdite, pokažite se duhovnikom! In zgodi se, ko so šli, so bili očiščeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 15, 'Eden pa izmed njih, ko je videl, da je ozdravel, se vrne, hvaleč Boga z močnim glasom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 16, 'in pade na obraz pred noge njegove ter se mu zahvali; in ta je bil Samarijan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 17, 'Odgovori pa Jezus in reče: Ali jih ni bilo deset očiščenih, kje pa je onih devet?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 18, 'Ali ni nobenega drugega, ki bi se vrnil, da bi dal Bogu hvalo, razen tega tujca?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 19, 'In reče mu: Vstani, pojdi! vera tvoja te je rešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 20, 'Ko ga pa vprašajo farizeji, kdaj pride kraljestvo Božje, jim odgovori in reče: Kraljestvo Božje ne pride, vzbujajoč pozornost;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 21, 'tudi ne poreko: Glej, tu je! ali: Glej, tam je! Kajti, glejte, kraljestvo Božje je sredi vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 22, 'Reče pa učencem: Pridejo dnevi, ko boste želeli videti enega od dni Sina človekovega, in ne boste videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 23, 'In poreko vam: Glej, tu je! ali: Glej, tam je! Ne hodite tja in tudi ne sledite jim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 24, 'Zakaj kakor blisk, ki švigne z enega kraja neba in se zasveti do drugega kraja neba, tako bode Sin človekov v dan svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 25, 'Ali poprej mora veliko pretrpeti in zavržen biti od tega rodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 26, 'In kakor je bilo v dnevih Noetovih, tako bode tudi v dneh Sina človekovega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 27, 'jedli so, pili so, ženili so se, možile so se, do dneva, ko je stopil Noe v barko ter je prišel potop in vse pogubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 28, 'Enako tudi, kakor je bilo v dnevih Lotovih: jedli so, pili so, kupovali so, prodajali so, sadili so, zidali so;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 29, 'ali tisti dan, ko je šel Lot iz Sodome, je ogenj in žveplo dežilo z neba in je vse pogubilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 30, 'Ravno tako bode tisti dan, ko se razodene Sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 31, 'Tisti dan, kdor bo na strehi, a orodje njegovo v hiši, naj ne stopa doli, da ga vzame; in kdor bo na polju, naj se tudi ne ozira na to, kar je zadaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 32, 'Spominjajte se žene Lotove!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 33, 'Kdorkoli hoče dušo svojo ohraniti, jo izgubi; a kdor jo izgubi, ji pomore v življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 34, 'Pravim vam: Tisto noč bodeta dva na eni postelji: eden bo vzet, a drugi puščen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 35, 'Dve bosta mleli skupaj: ena bo vzeta, a druga puščena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 36, '§ Dva bosta na njivi: eden bo vzet, a drugi puščen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 17, 37, 'In odgovarjajoč mu, reko: Kje, Gospod? A on jim reče: Kjer je truplo, tam se bodo zbirali tudi orli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 1, 'Pravil jim je pa tudi priliko, kako jim je treba vsekdar moliti in ne naveličati se, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 2, 'Bil je v nekem mestu sodnik, ki se ni bal Boga in se ni sramoval ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 3, 'Bila pa je v tistem mestu vdova, in hodila je k njemu, proseč: Izvrši zame pravico nad nasprotnikom mojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 4, 'In dolgo časa ni hotel; potem pa reče sam v sebi: Če se tudi Boga ne bojim in se ne sramujem ljudi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 5, 'vendar zato, ker me tolikanj nadleguje ta vdova, izvršim ji pravico, da naposled ne pride in me ogluši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 6, 'In reče Gospod: Slišite, kaj pravi nepravični sodnik!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 7, 'Ali ne bo tudi Bog izvršil pravice izvoljencem svojim, ki vpijejo k njemu dan in noč, čeprav jim odlaša?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 8, 'Pravim vam, da jim stori pravico v kratkem. Toda, kadar pride Sin človekov, najde li pač to vero na zemlji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 9, 'Pove pa tudi nekaterim, ki so sami v sebe zaupali, da so pravični, a druge so zaničevali, to priliko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 10, 'Dva človeka sta šla gori v tempelj molit, eden je bil farizej, a drugi cestninar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 11, 'Farizej se ustopi in moli sam s seboj tako: Bog, zahvaljujem te, da nisem, kakor drugi ljudje: razbojniki, krivičniki, prešeštniki ali kakor tale cestninar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 12, 'Postim se dvakrat na teden, desetino dajem od vsega, karkoli imam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 13, 'Cestninar pa stoji oddaleč in še oči si ne upa povzdigniti k nebu, temuč trka na prsi svoje, rekoč: Bog, milostljiv mi bodi grešniku!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 14, 'Pravim vam: Ta je šel opravičen na dom svoj, a ne oni: zakaj vsak, kdor se povišuje, bo ponižan, a kdor se ponižuje, bo povišan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 15, 'Prinašali so pa k njemu tudi otročičke svoje, da bi se jih dotikal; videč pa to, jih karajo učenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 16, 'A Jezus jih pokliče k sebi in reče: Pustite otročiče, naj prihajajo k meni, in ne branite jim; zakaj takih je kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 17, 'Resnično vam pravim: Kdorkoli ne sprejme kraljestva Božjega kakor otrok, nikakor ne pride vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 18, 'In vpraša ga neki poglavar, rekoč: Dobri učenik, kaj naj storim, da podedujem večno življenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 19, 'Jezus mu pa reče: Kaj me imenuješ dobrega? Nihče ni dober razen eden, Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 20, 'Zapovedi znaš: „Ne prešeštvuj, ne ubijaj, ne kradi, ne pričaj po krivem, spoštuj očeta svojega in mater svojo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 21, 'On pa reče: Vse to sem izpolnjeval od mladosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 22, 'In ko sliši to, mu Jezus veli: Enega ti je še treba: prodaj vse, karkoli imaš, in razdaj ubogim, in imel boš zaklad v nebesih, ter pridi in hodi za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 23, 'On pa, ko to sliši, se zelo razžalosti, zakaj bil je silno bogat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 24, 'Ko ga pa vidi Jezus žalostnega, reče: Kako težko pridejo v kraljestvo Božje, kateri imajo bogastvo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 25, 'Laže je namreč velblodu priti igli skozi uho, nego bogatinu stopiti v kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 26, 'Pa reko, ki so to slišali: Kdo se potem more zveličati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 27, 'On pa reče: Kar je pri ljudeh nemogoče, mogoče je pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 28, 'A Peter reče: Glej, mi smo zapustili vse svoje in šli za teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 29, 'On jim pa reče: Resnično vam pravim, da ni nikogar, ki je zapustil dom, ali ženo, ali brate, ali roditelje, ali otroke zavoljo kraljestva Božjega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 30, 'ki ne bi prejel mnogokrat več v tem času, a v prihodnjem svetu večnega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 31, 'Vzame pa dvanajstere k sebi in jim reče: Glej, gremo gori v Jeruzalem, in dopolni se Sinu človekovemu vse, kar so napisali proroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 32, 'Izroče ga namreč poganom, in zasmehovali ga bodo in zasramovali in pljuvali nanj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 33, 'in ga bičali in potem umorili; a tretji dan vstane od smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 34, 'In oni niso tega nič umeli, in ta beseda jim je bila skrita, in niso vedeli, kaj se jim je pravilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 35, 'Zgodi se pa, ko se bliža Jerihu, da sedi slepec kraj pota in prosjači.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 36, 'Ko pa sliši, da gre ljudstvo mimo, povprašuje, kaj bi to bilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 37, 'Povedo mu pa, da gre Jezus Nazarečan mimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 38, 'In zavpije rekoč: Jezus, sin Davidov, usmili se me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 39, 'In spredaj gredoči, mu preté, naj umolkne; on pa kriči še veliko bolj: Sin Davidov, usmili se me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 40, 'Jezus se pa ustavi in ukaže, naj ga pripeljejo k njemu; in ko se približa, ga vpraša:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 41, 'Kaj hočeš, naj ti storim? On pa reče: Gospod, da izpregledam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 42, 'In Jezus pa reče: Izpreglej! vera tvoja te je rešila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 18, 43, 'In takoj izpregleda in gre za njim, hvaleč Boga. In vse ljudstvo, ko je to videlo, je dalo hvalo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 1, 'In pride v Jeriho in gre skozi mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 2, 'In glej, mož, po imenu Zahej, in ta je bil višji cestninarjev in je bil bogat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 3, 'in rad bi bil videl Jezusa, kdo da je, pa ni ga mogel spričo množice, ker je bil majhne postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 4, 'In poteče naprej in spleza na murvovo smokvo, da bi ga videl, ker je imel tod mimo iti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 5, 'In Jezus, ko pride na to mesto, se ozre gori ter mu reče: Zahej, pojdi hitro doli! kajti danes moram ostati v tvoji hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 6, 'In hitro zleze doli in ga radosten sprejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 7, 'In ko to vidijo, godrnjajo vsi, govoreč: K človeku grešniku gre gostovat!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 8, 'Pristopi pa Zahej in reče Gospodu: Glej, polovico premoženja svojega, Gospod, dajem ubogim, in če sem koga kaj ukanil, povrnem mu četverno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 9, 'Jezus pa mu reče: Danes je prišlo zveličanje tej hiši, ker je tudi ta sin Abrahamov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 10, 'Sin človekov je namreč prišel iskat in zveličat, kar se je bilo izgubilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 11, 'Ko so pa to poslušali, pristavi in jim pove priliko, zato ker je bil blizu Jeruzalema in so mislili, da se zdajci prikaže kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 12, 'Reče torej: Človek imenitnega rodu je šel v daljno deželo, da prejme zase kraljevo oblast in se zopet vrne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 13, 'In pokliče deset hlapcev svojih ter jim da deset mošenj in jim reče: Kupčujte, dokler se ne vrnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 14, 'Meščani njegovi so ga pa sovražili, ter pošljejo poslance za njim in sporoče: Nočemo, da bi nam ta kraljeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 15, 'In zgodi se, ko je bil kraljevo oblast prejel in se je vrnil, da veli, naj mu pokličejo tiste hlapce, ki jim je bil dal srebra, da bi zvedel, kaj je kdo prikupčeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 16, 'In pride prvi in reče: Gospod, mošnja tvoja je pridobila deset mošenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 17, 'In reče mu: Dobro, vrli hlapec! ker si bil v najmanjšem zvest, imej oblast nad desetimi mesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 18, 'In pride drugi, rekoč: Gospod, mošnja tvoja je napravila pet mošenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 19, 'In tudi temu reče: Tudi ti bodi nad petimi mesti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 20, 'In drugi pride in reče: Gospod, glej, tu je mošnja tvoja, ki sem jo imel v prtu spravljeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 21, 'Kajti bal sem se te, ker si oster človek: jemlješ, česar nisi položil, in žanješ, česar nisi posejal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 22, 'Pa mu reče: Po tvojih besedah te bom sodil, hudobni hlapec! Vedel si, da sem oster človek in jemljem, česar nisem položil, in žanjem, česar nisem posejal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 23, 'zakaj torej nisi dal srebra mojega v menjalnico? In jaz bi ga bil ob prihodu svojem prejel z obrestmi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 24, 'In reče zraven stoječim: Vzemite mu mošnjo in dajte tistemu, ki ima deset mošenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 25, 'In mu reko: Gospod, saj jih ima deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 26, 'Pravim vam, da vsakemu, kdor ima, se bo dalo, a kdor nima, se mu vzame tudi to, kar ima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 27, 'A tiste sovražnike moje, ki niso hoteli, da bi jim kraljeval, pripeljite sem in jih posekajte pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 28, 'In ko je to povedal, se odpravi naprej, gredoč gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 29, 'In zgodi se, ko se približa Betfagi in Betaniji pri gori, ki se imenuje Oljska, da pošlje dva izmed učencev svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 30, 'rekoč: Pojdite v vas, ki je nasproti, v kateri, ko vnideta, najdeta žrebe privezano, na katero ni še nikoli noben človek sedel: odvežita ga in pripeljita sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 31, 'In če vaju kdo vpraša: Zakaj ga odvezujeta? povejta mu tako: Gospod ga potrebuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 32, 'In poslanca odideta in najdeta, kakor jima je bil rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 33, 'Ko pa žrebe odvezujeta, jima reko gospodarji njegovi: Kaj odvezujeta žrebe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 34, 'Ona pa rečeta: Gospod ga potrebuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 35, 'In pripeljeta ga k Jezusu; in polože svoja oblačila na žrebe ter posade nanje Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 36, 'Ko pa jezdi, pogrinjajo svoja oblačila na pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 37, 'In ko se že bliža pobrežju Oljske gore, začne vsa množica učencev radostna Boga hvaliti z močnim glasom za vse čudeže, ki so jih videli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 38, 'govoreč: Blagoslovljen kralj, ki prihaja v imenu Gospodovem! Mir na nebu in slava na višavah!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 39, 'In nekateri farizeji izmed množice mu reko: Učenik, posvari učence svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 40, 'In odgovori in jim reče: Pravim vam, če ti umolknejo, vpilo bo kamenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 41, 'In ko se približa in ugleda mesto, se razjoka nad njim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 42, 'in reče: Ko bi pač tudi ti spoznalo, vsaj v ta dan svoj, kaj je za mir tvoj! Ali sedaj je skrito očem tvojim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 43, 'Kajti pridejo nate dnevi, ko te obdado sovražniki tvoji z nasipom in te bodo oblegali in stiskali od vseh strani;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 44, 'in ob tla razbijejo tebe in otroke tvoje v tebi, in ne kamena na kamenu ne puste v tebi, zato ker nisi spoznalo časa, v katerem si bilo obiskano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 45, 'In ko pride v tempelj, začne izganjati tiste, ki so v njem prodajali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 46, 'rekoč jim: Pisano je: Dom moj je dom molitve, a vi ste naredili iz njega jamo razbojniško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 47, 'In učil je vsak dan v templju; a višji duhovniki in pismarji in prvaki ljudstva so iskali, da bi ga pogubili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 19, 48, 'pa niso našli, kaj bi mu storili: zakaj vse ljudstvo se ga je oklepalo, poslušajoč ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 1, 'In zgodi se enega tistih dni, ko je učil ljudstvo v templju in oznanjeval evangelij, da pridejo višji duhovniki in pismarji s starejšinami');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 2, 'in ga ogovore in reko: Povej nam, s kakšno oblastjo to delaš? ali kdo je, ki ti je dal to oblast?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 3, 'Odgovori pa in jim reče: Vprašal bom tudi jaz vas eno besedo. Povejte mi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 4, 'Krst Janezov je li bil iz nebes ali od ljudi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 5, 'A oni premišljujejo sami pri sebi, govoreč: Ako rečemo: Iz nebes, nam poreče: Zakaj mu niste verovali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 6, 'Ako pa rečemo: Od ljudi, vse ljudstvo nas bo s kamenjem posulo, zakaj prepričano je, da je Janez prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 7, 'In odgovore, da ne vedo, odkod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 8, 'In Jezus jim reče: Tudi jaz vam ne povem, s kakšno oblastjo to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 9, 'Ljudstvu pa začne praviti tole priliko: Nekdo je zasadil vinograd in ga dal vinogradnikom v najem, in odpotoval je za veliko časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 10, 'In ob svojem času pošlje k vinogradnikom hlapca, naj mu dado od sadu vinogradovega; a vinogradniki ga pretepo in odpošljejo praznega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 11, 'In zopet pošlje drugega hlapca; a oni pretepo tudi tega in zasramote ter odpošljejo praznega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 12, 'In zopet pošlje tretjega; in oni ranijo tudi tega in ga izženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 13, 'Reče pa gospodar vinogradov: Kaj naj storim? Pošljem sina svojega ljubljenega; ko bodo tega videli, nemara da se bodo bali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 14, 'Ko ga pa vinogradniki ugledajo, se posvetujejo med seboj, govoreč: Ta je dedič; umorimo ga, da bode dediščina naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 15, 'In vržejo ga ven iz vinograda in umore. Kaj jim bo torej storil gospodar vinogradov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 16, 'Pride in pogubi vinogradnike te in da vinograd drugim. Ko so pa to slišali, reko: Bog ne daj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 17, 'On pa jih pogleda in reče: Kaj je torej to, kar je pisano: „Kamen, ki so ga zidarji zavrgli, ta je postal glava voglu“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 18, 'Vsak, kdor pade na ta kamen, se razbije; na kogar pa on pade, ga razdrobi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 19, 'In pismarji in višji duhovniki bi bili radi položili nanj roke v to uro, ali zboje se ljudstva; spoznali so namreč, da je zanje povedal to priliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 20, 'In zalezujoč ga, pošljejo prežune, ki naj bi se hlinili pravične, da bi ga ujeli v besedi in ga potem izročili gosposki in oblasti poglavarjevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 21, 'In vprašajo ga, rekoč: Učenik, vemo, da prav govoriš in učiš ter ne gledaš ljudem na lice, marveč v resnici učiš pot Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 22, 'Je li prav, da dajemo cesarju davek, ali ne?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 23, 'Ker pa spozna njih zvijačo, jim reče: Kaj me izkušate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 24, 'Pokažite mi denar. Čigavo podobo ima in napis? Pa reko: Cesarjevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 25, 'In on jim veli: Dajte torej cesarju, kar je cesarjevega, in Bogu, kar je Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 26, 'In niso ga mogli ujeti v besedi vpričo ljudstva, in umolknejo, čudeč se odgovoru njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 27, 'In pristopijo nekateri od saducejev, ki pravijo, da ni vstajenja, in ga vprašajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 28, 'rekoč: Učenik! Mojzes nam je napisal: Če komu umre brat, oženjen, pa brez otrok, naj vzame njegov brat ženo njegovo in zbudi seme bratu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 29, 'Bilo je pa sedem bratov. In prvi vzame ženo in umre brez otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 30, 'In drugi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 31, 'in tretji jo vzame, in tako tudi vseh sedem, in pomrjejo, ne da bi bili zapustili otrok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 32, 'Naposled umre tudi žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 33, 'Ta žena torej čigava izmed njih bo ob vstajenju? zakaj sedem jih jo je imelo za ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 34, 'In reče jim Jezus: Sinovi tega sveta se ženijo in možé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 35, 'Ali ti, ki bodo spoznani za vredne, da dosežejo drugi svet in vstajenje iz mrtvih, se ne bodo ne ženili, ne možile;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 36, 'kajti tudi umreti ne morejo več: enaki so namreč angelom in so sinovi Božji, ker so sinovi vstajenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 37, 'Da pa mrtvi vstajajo, je pokazal tudi Mojzes v zgodbi o grmu, ko imenuje Gospoda Boga Abrahamovega in Boga Izakovega in Boga Jakobovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 38, 'Bog pa ni Bog mrtvih, ampak živih; zakaj njemu so vsi živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 39, 'Odgovore pa nekateri pismarji in reko: Učenik, dobro si povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 40, 'Kajti nič več si ga niso upali vpraševati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 41, 'Reče jim pa: Kako pravijo, da je Kristus sin Davidov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 42, 'David sam namreč pravi v knjigi psalmov: „Rekel je Gospod Gospodu mojemu: Sedi na desnici moji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 43, 'dokler ne položim sovražnikov tvojih nogam tvojim za podnožje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 44, 'David ga torej imenuje Gospoda, in kako je sin njegov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 45, 'A ko ga vse ljudstvo posluša, reče učencem svojim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 46, 'Varujte se pismarjev, ki radi hodijo v dolgih oblačilih in ljubijo pozdrave po ulicah in prve stole v shodnicah in prve prostore na gostijah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 20, 47, 'ki požirajo vdovam hiše in opravljajo na videz dolge molitve. Ti prejmejo ostrejšo sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 1, 'Pogleda pa gori in vidi bogatine, da mečejo darove svoje v zakladnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 2, 'Vidi pa tudi vdovo ubožno, da vrže tja dva vinarja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 3, 'ter reče: Resnično vam pravim, da je ta uboga vdova vrgla več nego vsi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 4, 'zakaj vsi ti so vrgli od obilosti svoje v dar Bogu, a ta je od uboštva svojega vrgla ves živež svoj, ki ga je imela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 5, 'In ko so nekateri pravili o templju, da je olepšan z lepim kamenjem in darovi, reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 6, 'Pridejo dnevi, ko od tega, kar vidite, ne ostane kamen na kamenu, ki se ne bi podrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 7, 'In vprašajo ga, rekoč: Učenik, kdaj pa bode to? in kaj bo znamenje, kadar se ima to zgoditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 8, 'On pa reče: Varujte se, da vas ne zapeljejo. Zakaj veliko jih pride z imenom mojim in poreko: Jaz sem! in: Čas se je približal. Ne hodite za njimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 9, 'Kadar boste pa slišali o vojskah in vstajah, ne uplašite se; zakaj to se mora prej zgoditi: ali konec ne pride precej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 10, 'Tedaj jim je pravil: Vstane narod zoper narod in kraljestvo zoper kraljestvo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 11, 'in bodo veliki potresi ter po raznih krajih lakote in kuge, tudi bodo grozote in znamenja velika z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 12, 'A pred vsem tem polože roke svoje na vas in bodo vas preganjali, in izdajali vas bodo shodnicam in ječam in vodili pred kralje in poglavarje zavoljo imena mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 13, 'A to vam dá priložnost za pričanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 14, 'Vtisnite si torej v srce, da vam ni skrbeti naprej, kako se boste zagovarjali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 15, 'zakaj jaz vam dam usta in modrost, kateri se ne bodo mogli upirati, ne ugovarjati vsi nasprotniki vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 16, 'Izdajali vas pa bodo celo roditelji in bratje in sorodniki in prijatelji, in nekatere izmed vas umore;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 17, 'in sovražili vas bodo vsi zavoljo imena mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 18, 'Pa las z glave vam ne pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 19, 'S potrpljenjem svojim pridobivajte duše svoje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 20, 'Kadar boste pa videli, da vojske oblegajo Jeruzalem, tedaj vedite, da se je približalo razdejanje njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 21, 'Takrat naj, kateri so v Judeji, zbeže na gore, in kateri so sredi mesta, naj se izselijo, in kateri so na deželi, naj ne hodijo v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 22, 'Zakaj ti dnevi bodo dnevi maščevanja, da se dopolni vse, kar je pisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 23, 'Gorje pa nosečim in doječim v tistih dneh; kajti velika nadloga bo v tej deželi in jeza božja nad tem narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 24, 'In padali bodo od ostrine meča, in gonili jih bodo v sužnost po vseh narodih, in Jeruzalem bodo teptali pogani, dokler se ne dopolnijo časi poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 25, 'In znamenja bodo na solncu in na mesecu in na zvezdah, in na zemlji strah in obup narodov zavoljo strašnega šumenja morja in valov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 26, 'ljudje bodo omrtvevali od strahu in pričakovanja tega, kar ima priti čez ves svet: zakaj sile nebeške se bodo pregibale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 27, 'In tedaj ugledajo Sina človekovega, da prihaja na oblaku z močjo in slavo veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 28, 'Ko se pa to začne goditi, ozrite se gori in povzdignite glave, ker se približuje odrešitev vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 29, 'In pove jim priliko: Poglejte smokvo in vse drevje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 30, 'videč, da že brstje poganja, sami spoznavate, da je poletje že blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 31, 'Tako tudi vi, kadar vidite, da se to godi, vedite, da je blizu kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 32, 'Resnično vam pravim, da ne preide ta rod, dokler se vse ne zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 33, 'Nebo in zemlja preideta, a besede moje ne preidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 34, 'Pazite pa nase, da ne bodo kdaj vaša srca obtežena s požrešnostjo in pijanstvom in skrbmi tega življenja, in vas ne zadene ta dan iznenada kakor zanka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 35, 'Kajti takó pride na vse, ki prebivajo na licu vse zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 36, 'Bedite torej vsak čas in molite, da boste mogli ubežati vsemu temu, kar se ima zgoditi, in stati pred Sinom človekovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 37, 'In po dnevi je učil v templju, a zvečer je hodil prenočevat na goro, ki se imenuje Oljska.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 21, 38, 'In prihajalo je vse ljudstvo zgodaj k njemu, poslušat ga v templju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 1, 'Bližal se je pa praznik presnih kruhov, ki se imenuje Velika noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 2, 'In višji duhovniki in pismarji so gledali, kako bi ga umorili; bali so se namreč ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 3, 'Satan pa je šel v Juda s priimkom Iškariota, ki je bil iz števila dvanajsterih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 4, 'In odide in se dogovori z višjimi duhovniki in glavarji templja, kako jim ga izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 5, 'In razvesele se in se zavežejo, dati mu denarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 6, 'In da jim besedo in išče pripravnega časa, da jim ga izda v nepričujočnosti množice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 7, 'Pride pa dan presnih kruhov, ko je bilo treba klati velikonočno jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 8, 'In pošlje Petra in Janeza, rekoč: Pojdita, pripravita nam velikonočno jagnje, da bomo jedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 9, 'Ona pa mu rečeta: Kje hočeš, da pripraviva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 10, 'A on jima reče: Glej, ko prideta v mesto, vaju bo srečal človek, ki bo nesel vrč vode; sledita za njim v hišo, v katero pojde,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 11, 'in recita hišnemu gospodarju: Učenik ti pravi: Kje je obednica, kjer bom jedel velikonočno jagnje z učenci svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 12, 'In on vama pokaže veliko izbo pogrnjeno; tam pripravita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 13, 'Pa odideta in najdeta, kakor jima je bil rekel, in pripravita velikonočno jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 14, 'In ko pride ura, sede za mizo in dvanajsteri apostoli ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 15, 'In reče jim: Željno sem hrepenel jesti to velikonočno jagnje z vami, preden bom trpel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 16, 'kajti pravim vam, da ga ne bom več jedel, dokler se v kraljestvu Božjem ne dopolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 17, 'In prejme kelih, zahvali in reče: Vzemite ga in razdelite med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 18, 'Kajti pravim vam, da ne bom več pil od trtnega sadu, dokler ne pride kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 19, 'In vzame kruh, zahvali in prelomivši ga, jim da, rekoč: To je moje telo, ki se za vas daruje. To delajte v moj spomin!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 20, 'Ravno tako tudi kelih po večerji, rekoč: Ta kelih je nova zaveza v moji krvi, ki se za vas preliva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 21, 'Toda glej, izdajalca mojega roka je z menoj na mizi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 22, 'Sin človekov sicer gre, kakor je določeno, ali gorje tistemu človeku, ki ga izdaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 23, 'In oni začno vpraševati med seboj, kdo je mar izmed njih, ki bo to storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 24, 'Vname pa se tudi prepir med njimi, kdo izmed njih velja li za večjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 25, 'On jim pa reče: Kralji narodov tem gospodujejo, in kateri imajo oblast, se imenujejo dobrotniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 26, 'Vi pa ne tako: ampak kdor je največji med vami, bodi kakor najmanjši, in kdor je vodnik, bodi kakor služabnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 27, 'Kdo namreč je večji: kdor sedi za mizo, ali kdor streže? Ali ne, kdor sedi za mizo? Jaz pa sem med vami kakor kdor streže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 28, 'A vi ste, ki ste vztrajali z menoj v izkušnjavah mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 29, 'In jaz vam volim kraljestvo, kakor ga je meni Oče moj volil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 30, 'da jeste in pijete pri mizi moji v kraljestvu mojem in sedite na prestolih ter sodite dvanajstere rodove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 31, 'Simon, Simon! glej, satan si je izprosil, da vas sme presejati kakor pšenico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 32, 'ali jaz sem prosil zate, naj ne izgine vera tvoja; in ti, ko se nekdaj izpreobrneš, potrjuj brate svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 33, 'On pa mu reče: Gospod, pripravljen sem iti s teboj tudi v ječo in v smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 34, 'A on mu reče: Pravim ti, Peter, danes ne zapoje petelin, dokler trikrat ne utajiš, da me poznaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 35, 'In vpraša jih: Ko sem vas poslal brez mošnje in torbe in obuvala, ali vam je česa zmanjkalo? Oni pa odgovore: Ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 36, 'On pa jim reče: Ali sedaj, kdor ima mošnjo, naj jo vzame, ravno tako tudi torbo, a kdor nima meča, naj proda suknjo in si ga kupi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 37, 'Kajti pravim vam, da se mora izpolniti na meni še to, kar je pisano: „In hudodelnikom je bil prištet“. Zakaj to, kar je pisano zame, se bliža dopolnitvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 38, 'Oni pa reko: Gospod glej, tu sta dva meča! A on jim reče: Dosti je!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 39, 'In gre ven in se napoti kakor navadno na Oljsko goro; za njim pa gredo tudi učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 40, 'In ko pride na mesto, jim reče: Molite, da ne zajdete v izkušnjavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 41, 'In sam se odmakne od njih za lučaj kamena in pokleknivši na kolena, moli');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 42, 'in reče: Oče, ako hočeš, vzemi ta kelih od mene, toda ne moja volja, ampak tvoja se zgodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 43, 'Prikaže pa se mu angel iz nebes in ga krepča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 44, 'In ko se bori z grozo smrti, moli še gorečneje; in njegov pot postane kakor kaplje krvi, ki so padale na zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 45, 'In vstane od molitve ter pride k učencem svojim in jih najde speče od žalosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 46, 'In jim reče: Kaj spite? Vstanite in molite, da ne zajdete v izkušnjavo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 47, 'Ko je še govoril, glej, množica in oni, ki se je imenoval Juda, eden dvanajsterih, gre pred njimi in se približa Jezusu, da ga poljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 48, 'Jezus mu pa reče: Juda, s poljubom izdajaš Sina človekovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 49, 'Ko pa vidijo ti, ki so bili okoli njega, kaj da bo, mu reko: Gospod, ali naj udarimo z mečem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 50, 'In eden izmed njih udari hlapca velikega duhovnika in mu odseka desno uho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 51, 'Jezus pa odgovori in reče: Nehajte, dotlej! In doteknivši se ušesa njegovega, ga ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 52, 'A višjim duhovnikom in poglavarjem templja in starejšinam, ki so bili prišli nadenj, reče Jezus: Kakor nad razbojnika ste prišli z meči in koli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 53, 'Ko sem bil vsak dan z vami v templju, niste iztegnili rok zoper mene. Ali to je vaša ura in oblast teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 54, 'In zgrabijo ga in odženo. In peljejo ga v hišo velikega duhovnika. A Peter je šel oddaleč za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 55, 'In ko so bili zanetili ogenj sredi dvorišča in so skupaj sedeli, sede Peter mednje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 56, 'Neka dekla pa, ko ga vidi sedečega pri ognju, ga ostro pogleda in reče: Tudi ta je bil ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 57, 'A on zataji, rekoč: Žena, ne poznam ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 58, 'In malo potem ga ugleda drugi in reče: Tudi ti si izmed njih. A Peter reče: Človek, nisem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 59, 'In eno uro ali nekaj pozneje trdi nekdo drugi, rekoč: Zares, tudi ta je bil ž njim; saj je tudi Galilejec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 60, 'Peter pa reče: Človek, ne vem, kaj praviš. In zdajci, ko še govori, zapoje petelin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 61, 'In Gospod se obrne in pogleda na Petra; in Peter se spomni besede Gospodove, kakor mu je bil rekel: Preden zapoje petelin, me zatajiš trikrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 62, 'In gre ven in se bridko razjoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 63, 'In možje, ki so držali Jezusa, so ga zasramovali in bíli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 64, 'In zakrivali so ga in vpraševali, govoreč: Prorokuj, kdo te je udaril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 65, 'In še veliko drugega so preklinjaje govorili zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 66, 'In ko napoči jutro, se zbere starejšinstvo ljudstva, višji duhovniki in pismarji; in odpeljejo ga v veliki zbor svoj in reko:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 67, 'Če si ti Kristus, povej nam! On pa reče: Ako vam povem, nikakor ne boste verovali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 68, 'ako pa vprašam, gotovo ne odgovorite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 69, 'Odslej pa bo Sin človekov sedel na desnici moči Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 70, 'In reko vsi: Ti si torej Sin Božji? On jim pa reče: Vi pravite, da jaz sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 22, 71, 'A oni reko: Kaj nam je še treba pričevanja? Saj smo sami slišali iz ust njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 1, 'In vstane vsa njih množica ter ga peljejo k Pilatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 2, 'In začno ga tožiti, govoreč: Tega smo našli, da odvrača narod naš in brani cesarju davek dajati in pravi, da je on Kristus kralj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 3, 'A Pilat ga vpraša, rekoč: Si li ti kralj Judov? On pa odgovori in mu reče: Ti praviš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 4, 'Pilat pa reče višjim duhovnikom in ljudstvu: Na tem človeku ne vidim nobene krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 5, 'Oni so pa še bolj silili, govoreč: Ljudstvo hujska, učeč po vsej Judeji, od Galileje, kjer je začel, do sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 6, 'Pilat pa, ko to sliši, vpraša, če je ta človek Galilejec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 7, 'In ko zve, da je izpod oblasti Herodove, ga pošlje k Herodu, ki je tudi bil te dni v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 8, 'Ko pa Herod ugleda Jezusa, se zelo razveseli; zakaj že davno ga je želel videti, ker je bil slišal o njem, in nadejal se je, da bo videl kakšen čudež, storjen od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 9, 'In izprašuje ga z mnogimi besedami, ali on mu ne odgovori ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 10, 'A višji duhovniki in pismarji so stali poleg in ga trdo tožili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 11, 'Herod pa, ko ga je zasramotil z vojaki svojimi in se mu nasmejal, mu obleče sijajno obleko ter ga pošlje nazaj k Pilatu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 12, 'In ta dan sta postala Pilat in Herod prijatelja drug drugemu; poprej namreč sta si bila sovražna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 13, 'A Pilat skliče višje duhovnike in poglavarje in ljudstvo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 14, 'ter jim reče: Pripeljali ste mi tega človeka, kakor da odvrača ljudstvo; in glejte, izprašal sem ga vpričo vas, a nisem našel nobene krivice na tem človeku v tem, za kar ga tožite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 15, 'Pa tudi Herod ne, zakaj poslal nam ga je nazaj; in glejte, storil ni ničesar, kar bi bilo vredno smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 16, 'Kaznoval ga bom torej in izpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 17, '§ Moral jim je pa o prazniku izpustiti enega jetnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 18, 'Vsa množica pa hkratu zavpije, rekoč: Proč s tem, izpusti pa nam Baraba!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 19, 'Tega so bili vrgli v ječo zavoljo neke vstaje, ki je izbruhnila v mestu, in zavoljo uboja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 20, 'Pilat pa jih zopet ogovori, hoteč izpustiti Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 21, 'Oni pa vpijejo: Križaj, križaj ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 22, 'In reče jim v tretje: Kaj pa je ta storil hudega? Ničesar smrti vrednega nisem našel na njem; kaznoval ga bom torej in izpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 23, 'A oni so tiščali vanj z velikim vpitjem, zahtevajoč, naj se razpne na križ. In njih vpitje je zmagalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 24, 'In Pilat razsodi, naj se zgodi, kar zahtevajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 25, 'In izpusti jim tega, ki je bil vržen v ječo zavoljo vstaje in uboja, za katerega so prosili; Jezusa pa izroči njih volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 26, 'In ko so ga peljali iz mesta, zgrabijo nekega Simona Cirenca, ki je šel s polja, in mu zadenejo križ, naj ga ponese za Jezusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 27, 'Šla je pa za njim velika množica ljudstva in žene, ki so jokale in žalovale nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 28, 'Obrnivši se pa k njim, reče Jezus: Hčere jeruzalemske, ne jokajte nad menoj, marveč nad seboj jokajte in nad svojimi otroki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 29, 'Kajti glejte, pridejo dnevi, ob katerih poreko: Blagor nerodovitnim in telesom, ki niso rodila, in prsim, ki niso dojile!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 30, 'Tedaj jamejo praviti goram: Padite na nas! in hribom: Pokrijte nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 31, 'Če namreč z zelenim drevesom tako delajo, kaj se bo zgodilo s suhim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 32, 'Peljali so pa ž njim vred tudi dva druga, hudodelnika, da ju umore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 33, 'In ko pridejo na kraj, ki se imenuje Mrtvaška glava, križajo tu njega in hudodelnika, enega na desni, a drugega na levi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 34, 'A Jezus reče: Oče, odpusti jim! saj ne vedo, kaj delajo. Deleč pa obleko njegovo, vržejo kocko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 35, 'In ljudstvo je stalo in gledalo. Zasmehovali so ga pa ž njimi vred tudi poglavarji, govoreč: Drugim je pomagal, naj pomore sebi, če je ta Kristus, izvoljenec Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 36, 'Posmehovali so se mu pa tudi vojaki, in pristopali so in mu podajali octa');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 37, 'in govorili: Če si ti kralj Judov, pomagaj si!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 38, 'Bil je pa tudi napis nad njim: TA JE KRALJ JUDOV.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 39, 'A eden hudodelnikov, ki sta ž njim visela, ga je preklinjal, govoreč: Če si ti Kristus, pomagaj sebi in nama!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 40, 'Drugi pa odgovori in ga posvari rekoč: Ali se tudi ti ne bojiš Boga, ko si sam prav tako obsojen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 41, 'In midva sicer po pravici, kajti prejemava po delih svojih, kar sva zaslužila; ta pa ni storil nič nepristojnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 42, 'In reče: Jezus, spomni se me, kadar prideš v kraljestvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 43, 'In Jezus mu reče: Resnično ti pravim, danes boš z menoj v raju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 44, 'In bilo je že okoli šeste ure, in nastane tema po vsej zemlji do devete ure,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 45, 'ker je solnce otemnelo; in zagrinjalo v svetišču se pretrga posredi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 46, 'In Jezus zakliče z močnim glasom in reče: Oče, v tvoje roke izročam duha svojega! In rekši to, izdahne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 47, 'Stotnik pa, ko je videl, kar se je zgodilo, je hvalil Boga in rekel: Zares, ta človek je bil pravičen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 48, 'In vsi ljudje, ki so se sešli to gledat, ko vidijo, kaj se godi, si trkajo na prsi ter se vračajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 49, 'Oddaleč pa so stali vsi znanci njegovi in žene, ki so bile ž njim prišle iz Galileje, gledajoč to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 50, 'In glej, mož po imenu Jožef, svetovalec, mož dober in pravičen');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 51, '(ki ni bil privolil v njih svet in dejanje), iz Arimateje, judovskega mesta, ki je tudi pričakoval kraljestva Božjega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 52, 'ta pristopi k Pilatu in zaprosi truplo Jezusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 53, 'In ga sname in zavije v platno, in ga položi v grob, izsekan v skalo, v katerega še nikoli nihče ni bil položen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 54, 'In bil je dan priprave in sobota je nastajala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 55, 'Žene pa, ki so bile ž njim prišle iz Galileje, so šle za mrtvim in si ogledale grob in kako je položeno truplo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 23, 56, 'In ko se vrnejo, pripravijo dišav in mazil; a v soboto so počivale po zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 1, 'A prvi dan tedna, zelo zgodaj, pridejo h grobu in prineso, kar so bile pripravile dišav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 2, 'Najdejo pa kamen odvaljen od groba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 3, 'ko pa stopijo v grob, ne najdejo trupla Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 4, 'In zgodi se, ko se niso mogle načuditi temu, glej, dva moža se postavita poleg njih v svetlih oblačilih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 5, 'Ko so se pa bale in so povesile lica k zemlji, jim rečeta: Kaj iščete živega med mrtvimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 6, 'Ni ga tu, nego vstal je. Spomnite se, kako vam je povedal, ko je bil še v Galileji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 7, 'rekoč: Sin človekov mora biti izdan v roke ljudi grešnikov in biti križan, a vstati tretji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 8, 'In spomnijo se besed njegovih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 9, 'in se vrnejo od groba ter sporoče vse to enajsterim in vsem drugim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 10, 'Bile so pa Marija Magdalena in Joana in Marija, Jakobova mati, in druge ž njimi, ki so to pravile apostolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 11, 'In zdele so se jim njih besede kakor prazno govoričenje, in niso jim verjeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 12, 'A Peter vstane in pohiti h grobu in, sklonivši se, ugleda samo platnene prte. In odide domov, čudeč se, kaj se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 13, 'In glej, dva izmed njih sta šla tisti dan v trg, ki je bil šestdeset tečajev daleč od Jeruzalema in mu je bilo ime Emavs.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 14, 'In pogovarjala sta se med seboj o vsem tem, kar se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 15, 'In prigodi se, ko se tako pogovarjata in drug drugega vprašujeta, da se sam Jezus približa in gre ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 16, 'Ali njune oči so bile zadržane, da ga nista spoznala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 17, 'On jima pa reče: Kaki so to pogovori, ki jih imata gredoč med seboj? In ustavita se, gledaje žalostno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 18, 'Odgovori pa eden, po imenu Kleopa, in mu reče: Si li ti edini tujec v Jeruzalemu, ki ne veš, kaj se je te dni v njem zgodilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 19, 'Pa jima reče: Kaj? Onadva mu pa rečeta: Tisto o Jezusu Nazarečanu, ki je bil mož prorok, mogočen v dejanju in besedi pred Bogom in vsem ljudstvom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 20, 'kako so ga naši višji duhovniki in poglavarji izdali v smrtno obsodbo in ga križali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 21, 'Mi pa smo se nadejali, da je on ta, ki ima odrešiti Izraela. Ali vrhu vsega tega je danes že tretji dan, kar se je to zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 22, 'Pa tudi uplašile so nas neke žene izmed naših, ki so bile zgodaj pri grobu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 23, 'in ko niso našle trupla njegovega, so prišle, pripovedujoč, da so celo videle prikazen angelov, kateri pravijo, da je on živ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 24, 'In nekateri teh, ki so z nami, so šli h grobu in so našli tako, kakor so bile žene povedale, ali njega niso videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 25, 'In on jima veli: O vi nespametneži in lenega srca, da bi verovali vse, kar so govorili proroki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 26, 'Ali ni bilo potrebno, da je Kristus to trpel in tako šel v slavo svojo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 27, 'In začne od Mojzesa in vseh prorokov in jima razlaga, kar je v vseh pismih pisano o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 28, 'In približajo se trgu, v katerega sta šla; in on se dela, kakor da bi hotel dalje iti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 29, 'In prisilita ga, govoreč: Ostani z nama, ker se večeri in dan se je že nagnil. In gre noter, da ostane ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 30, 'In zgodi se, ko je sedel ž njima za mizo, vzame kruh in blagoslovi ter ga prelomi in jima podaje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 31, 'In njune oči se odpro in ga spoznata; a on jima izgine izpred oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 32, 'In rečeta drug drugemu: Ali ni srce gorelo v naju, ko nama je govoril po poti, ko nama je razlagal pisma?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 33, 'In vstaneta še tiso uro in se vrneta v Jeruzalem, in najdeta zbrane enajstere in te, ki so bili ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 34, 'Ti pravijo: Res je vstal Gospod in se je prikazal Simonu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 35, 'In onadva pripovedujeta, kaj se je zgodilo na poti in kako sta ga spoznala, ko je kruh prelomil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 36, 'Ko pa o tem še govore, stopi on sam v sredo mednje in jim reče: Mir vam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 37, 'In oni se uplaše in vsi prestrašeni mislijo, da vidijo duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 38, 'In jim reče: Kaj se plašite? in zakaj dvomljive misli obhajajo vaša srca?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 39, 'Poglejte roke moje in noge moje, da sem jaz sam; potipajte me in poglejte! Saj duh nima mesa in kosti, kakor vidite, da imam jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 40, 'In rekši to, jim pokaže roke in noge svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 41, 'Ker pa še ne verjamejo od veselja in se čudijo, jim reče: Imate li tu kake jedi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 42, 'Oni pa mu dado kos pečene ribe in satovja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 43, 'In vzame in pojé pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 44, 'Reče pa jim: To so besede moje, katere sem vam bil govoril, ko sem bil še z vami, da se mora izpolniti vse, kar je pisano zame v zakonu Mojzesovem in v prorokih in psalmih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 45, 'Tedaj jim odpre um, da bi razumeli pisma;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 46, 'in veli jim: Tako je pisano in tako je moral Kristus trpeti in vstati tretji dan iz mrtvih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 47, 'in se mora oznanjevati v imenu njegovem izpokorjenje in odpuščenje grehov med vsemi narodi, počenši od Jeruzalema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 48, 'Vi pa ste priče temu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 49, 'In glejte, jaz pošljem obljubo Očeta svojega na vas; a vi ostanite v mestu Jeruzalemu, dokler ne boste oblečeni v moč z višave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 50, 'Peljal jih je pa ven, da so bili Betaniji nasproti, in povzdigne roke svoje in jih blagoslovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 51, 'In zgodi se, ko jih blagoslavlja, da se loči od njih, in vznese se v nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 52, 'A oni se mu poklonijo in se vrnejo v Jeruzalem z velikim veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (42, 24, 53, 'In bili so vsekdar v templju, hvaleč Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 1, 'V začetku je bila Beseda, in Beseda je bila pri Bogu, in Bog je bila Beseda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 2, 'Ta je bila v začetku pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 3, 'Vse je po njej postalo, in brez nje ni nič postalo, kar je postalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 4, 'V njej je bilo življenje, in življenje je bilo luč ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 5, 'In luč sveti v temi, in tema se je ni polastila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 6, 'Nastopil je človek, poslan od Boga, ki mu je bilo ime Janez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 7, 'Ta je prišel na pričevanje, da priča za Luč, da bi vsi verovali po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 8, 'On ni bil Luč, ali prišel je, da priča za Luč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 9, 'Prava Luč, ki razsvetljuje vsakega človeka, je že prihajala na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 10, 'Na svetu je bil, in svet je postal po njem, a svet ga ni spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 11, 'V svojo last je prišel, in svojci ga niso sprejeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 12, 'A katerikoli so ga sprejeli, jim je dal oblast, da postanejo otroci Božji, njim, ki verujejo v ime njegovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 13, 'ki se niso rodili iz krvi, ne iz volje mesa, ne iz volje moža, marveč iz Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 14, 'In Beseda je postala meso in je prebivala med nami (in videli smo slavo njeno, slavo kakor Edinorojenega od Očeta), polna milosti in resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 15, 'Janez pričuje zanj in kliče, govoreč: Ta je bil, ki sem rekel o njem: Ta, ki prihaja za menoj, je bil tu pred menoj; kajti bil je prej nego jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 16, 'In od polnosti njegove smo mi vsi prejeli, in to milost za milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 17, 'Kajti postava je bila dana po Mojzesu, milost in resnica je postala po Jezusu Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 18, 'Boga ni nikoli nihče videl; edinorojeni Sin, ki je v naročju Očetovem, on ga je oznanil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 19, 'In to je pričevanje Janezovo, ko so poslali Judje iz Jeruzalema duhovnike in levite, naj ga vprašajo: Kdo si ti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 20, 'In je priznal in ni utajil; in prizna: Jaz nisem Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 21, 'In vprašajo ga: Kaj si torej? Elija si ti? In reče: Nisem. Prorok si ti? In odgovori: Ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 22, 'Reko mu torej: Kdo si? da odgovor damo tem, ki so nas poslali. Kaj praviš sam o sebi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 23, 'Reče: Jaz sem „glas vpijočega v puščavi: Poravnajte pot Gospodov“, kakor je povedal Izaija prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 24, 'Poslanci pa so bili izmed farizejev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 25, 'In ga vprašajo in mu reko: Zakaj torej krščuješ, če nisi Kristus, ne Elija, ne prorok?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 26, 'Odgovori jim Janez, rekoč: Jaz krščujem z vodo; sredi med vami pa stoji, ki ga vi ne poznate,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 27, 'on, ki gre za menoj, ki mu jaz nisem vreden odvezati jermena na obuvalu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 28, 'To se je zgodilo v Betaniji onkraj Jordana, kjer je Janez krščeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 29, 'Drugi dan ugleda Janez Jezusa, da gre k njemu, ter reče: Glej, Jagnje Božje, ki odjemlje greh sveta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 30, 'Ta je, ki sem rekel o njem: Za menoj prihaja mož, ki je bil tu pred menoj; kajti bil je prej nego jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 31, 'In jaz ga nisem poznal; ali da se razodene Izraelu, zato sem prišel krščevat z vodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 32, 'In pričuje Janez, rekoč: Videl sem Duha, da prihaja ko golob z neba, in je ostal na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 33, 'In jaz ga nisem poznal; ali ta, ki me je poslal krščevat z vodo, mi je rekel: Na kogar boš videl, da pride Duh in ostane na njem, ta je, ki krščuje s svetim Duhom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 34, 'In jaz sem ga videl in izpričal, da je ta Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 35, 'Drugi dan je stal zopet Janez in dva izmed učencev njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 36, 'in pogleda Jezusa, ki gre mimo, in reče: Glej, Jagnje Božje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 37, 'In slišala sta ga oba učenca, ko je govoril, ter odideta za Jezusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 38, 'Jezus se pa obrne in ko ju ugleda, da gresta za njim, jima reče: Kaj iščeta? Ona pa mu rečeta: Rabi (kar se pravi, če raztolmačiš: Učenik), kje stanuješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 39, 'Veli jima: Pridita in poglejta! Gresta torej in vidita, kje stanuje, in ostaneta pri njem tisti dan. Bilo je okoli desete ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 40, 'Eden teh dveh, ki sta to slišala od Janeza in sta šla za njim, je bil Andrej, brat Simona Petra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 41, 'Ta najde najprej brata svojega Simona in mu reče: Našli smo Mesija (kar se tolmači: Kristus).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 42, 'Njega pripelje k Jezusu. Jezus pogleda nanj in reče: Ti si Simon, sin Jonov; ti se boš imenoval Kefa (kar se tolmači: Peter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 43, 'Drugi dan je hotel Jezus oditi v Galilejo; in najde Filipa in mu reče: Pojdi za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 44, 'Filip pa je bil iz Betsaide, mesta Andrejevega in Petrovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 45, 'Filip najde Natanaela in mu reče: Našli smo ga, ki je pisal o njem Mojzes v zakonu in proroki, Jezusa iz Nazareta, sina Jožefovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 46, 'Pa mu Natanael reče: More li iz Nazareta priti kaj dobrega? Veli mu Filip: Pridi in poglej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 47, 'Jezus vidi Natanaela, da gre k njemu, ter reče o njem: Glej, pravi Izraelec, v katerem ni zvijače!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 48, 'Reče mu Natanael: Odkod me poznaš? Jezus odgovori in mu reče: Preden te je Filip poklical, ko si bil pod smokvo, sem te videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 49, 'Natanael mu odgovori: Rabi, ti si Sin Božji, ti si kralj Izraelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 50, 'Jezus odgovori in mu veli: Ker sem ti dejal, da sem te videl pod smokvo, veruješ? Večje reči boš videl nego to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 1, 51, 'In mu reče: Resnično, resnično vam pravim: Videli boste nebesa odprta in angele Božje stopati gori in doli do Sina človekovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 1, 'In tretji dan je bila ženitnina v Kani Galilejski, in mati Jezusova je bila tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 2, 'Povabili pa so tudi Jezusa in učence njegove na ženitnino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 3, 'In ko zmanjka vina, reče mati Jezusova njemu: Vina nimajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 4, 'In reče ji Jezus: Kaj imaš z menoj, žena? Moja ura še ni prišla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 5, 'Mati njegova reče služabnikom: Karkoli vam poreče, storite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 6, 'Bilo je pa tam šest kamenenih vrčev, postavljenih po šegi očiščevanja judovskega, ki so držali po dve ali tri mere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 7, 'Veli jim Jezus: Napolnite vrče z vodo. In napolnijo jih do vrha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 8, 'In jim veli: Zajmite sedaj, in nesite starejšini. Ter neso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 9, 'Ko pa okusi starejšina vodo, ki je postala vino (ni pa vedel, odkod je, a služabniki so vedeli, ki so bili zajemali vodo), pokliče starejšina ženina');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 10, 'in mu reče: Vsak človek daje najprej dobro vino, in ko se napijejo, tedaj tisto, ki je slabše: a ti si prihranil dobro vino do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 11, 'Ta začetek čudežev je storil Jezus v Kani Galilejski in je razodel slavo svojo; in verovali so vanj učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 12, 'Potem gre doli v Kafarnavm, on in mati njegova in bratje in učenci njegovi, in tu ostanejo ne veliko dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 13, 'In bila je blizu Velika noč Judov, in Jezus se napoti v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 14, 'In najde v templju prodajalce volov in ovac in golobov ter menjalce, sedeče pri svojih mizah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 15, 'In splete bič iz vrvic in izžene vse iz templja, tudi ovce in vole; in menjalcem raztrese denar in prevrne mize,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 16, 'in tem, ki so prodajali golobe, veli: Odnesite to odtod; ne delajte iz hiše Očeta mojega hiše trgovske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 17, 'Spomnijo pa se učenci njegovi, da je pisano: „Gorečnost za hišo tvojo me razjeda“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 18, 'Judje torej odgovore in mu reko: Kakšno znamenje nam pokažeš, ker delaš to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 19, 'Jezus odgovori in jim reče: Poderite to svetišče, in v treh dneh ga postavim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 20, 'Pa mu reko Judje: Šestinštirideset let so zidali to svetišče, in ti ga postaviš v treh dneh?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 21, 'Ali on je govoril o svetišču telesa svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 22, 'Ko je bil torej vstal iz mrtvih, so se spomnili učenci njegovi, da jim je to pravil; in verovali so pismu in besedi, ki jo je bil Jezus povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 23, 'Ko pa je bil v Jeruzalemu o Veliki noči, ob prazniku, jih je mnogo sprejelo vero v ime njegovo, ko so videli znamenja njegova, ki jih je delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 24, 'On pa, Jezus, se jim ni zaupal, ker jih je vse poznal');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 2, 25, 'in ker mu ni bilo treba, da bi kdo pričal o človeku: sam je namreč vedel, kaj je v človeku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 1, 'Bil pa je človek med farizeji, Nikodem po imenu, poglavar Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 2, 'Ta pride k Jezusu po noči in mu reče: Rabi! vemo, da si od Boga prišel kot učenik; zakaj nihče ne more delati teh znamenj, ki jih ti delaš, če Bog ni ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 3, 'Jezus odgovori in mu reče: Resnično, resnično ti pravim: Če se kdo na novo ne rodi, ne more videti kraljestva Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 4, 'Reče mu Nikodem: Kako se more človek roditi, ko je star? Ali more drugič iti v telo matere svoje in se roditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 5, 'Jezus odgovori: Resnično, resnično ti pravim: Če se kdo ne rodi iz vode in Duha, ne more priti v kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 6, 'Kar se je rodilo iz mesa, je meso, in kar se je rodilo iz Duha, je duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 7, 'Ne čudi se, da sem ti rekel: Treba se vam je na novo roditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 8, 'Veter veje, kjer hoče, in glas njegov slišiš, pa ne veš, odkod prihaja in kam gre: tako je z vsakim, ki je rojen iz Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 9, 'Nikodem odgovori in mu reče: Kako se more to zgoditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 10, 'Jezus pa odgovori in mu reče: Ti si učenik Izraelov, in tega ne veš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 11, 'Resnično, resnično ti pravim: Kar vemo, govorimo, in kar smo videli, pričamo, ali pričevanja našega ne sprejemate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 12, 'Če vam pravim pozemeljske reči, in ne verujete, kako boste verovali, če vam bom pravil nebeške?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 13, 'In nihče ni stopil v nebesa, razen kdor je prišel iz nebes, Sin človekov, ki je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 14, 'In kakor je Mojzes povišal kačo v puščavi, tako mora biti povišan Sin človekov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 15, 'da se ne pogubi, kdorkoli veruje vanj, temuč da ima večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 16, 'Kajti tako je Bog ljubil svet, da je dal Sina svojega edinorojenega, da se ne pogubi, kdorkoli veruje vanj, temuč da ima večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 17, 'Bog namreč ni poslal Sina svojega na svet, da bi svet sodil, marveč da se svet zveliča po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 18, 'Kdor veruje vanj, ne bo sojen; kdor ne veruje, je že obsojen, ker ni veroval v ime edinorojenega Sina Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 19, 'Sodba je pa to, da je luč prišla na svet, ali ljudje so bolj ljubili temo nego luč: zakaj njih dela so bila hudobna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 20, 'Vsak namreč, kdor dela hudobno, sovraži luč in ne hodi k luči, da se ne karajo dela njegova;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 21, 'kdor pa dela resnico, hodi k luči, da se razodenejo dela njegova, ker so v Bogu storjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 22, 'Potem pride Jezus in učenci njegovi v Judejsko deželo, in tu prebiva ž njimi in krščuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 23, 'Krščeval je pa tudi Janez v Enonu blizu Salima, ker je bilo tam mnogo vode, in ljudje so prihajali in se dali krstiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 24, 'Janez namreč še ni bil vržen v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 25, 'Nastane torej prepir med učenci Janezovimi in nekim Judom o očiščevanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 26, 'In pridejo k Janezu in mu reko: Rabi! ta, ki je bil s teboj onkraj Jordana, ki si zanj ti pričal, glej, ta krščuje in vsi gredo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 27, 'Janez odgovori in reče: Človek ne more ničesar vzeti, če mu ni dano iz nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 28, 'Vi sami ste mi priče, da sem rekel: Jaz nisem Kristus, ali poslan sem pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 29, 'Kdor ima nevesto, je ženin; prijatelj pa ženinov, ki stoji in ga posluša, se srčno veseli glasu ženinovega. To veselje moje je torej dopolnjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 30, 'On mora rasti, jaz pa se manjšati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 31, 'Kdor prihaja od zgoraj, ta je nad vsemi. Kdor je iz zemlje, je pozemski in govori zemske reči. Kdor je prišel iz nebes, ta je nad vsemi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 32, 'in kar je videl in slišal, to priča: a njegovega pričevanja nihče ne sprejema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 33, 'Kdor je sprejel njegovo pričevanje, je potrdil, da je Bog resničen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 34, 'Kajti ta, ki ga je poslal Bog, govori besede Božje: zakaj njemu Bog ne daje Duha na mero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 35, 'Oče ljubi sina, in vse mu je dal v roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 3, 36, 'Kdor veruje v Sina, ima večno življenje; a kdor je neveren Sinu, ne bo videl življenja, ampak jeza Božja ostane na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 1, 'Ko torej zve Gospod, da so farizeji slišali, da Jezus dobiva in krščuje več učencev nego Janez');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 2, '(dasi Jezus sam ni krščeval, marveč učenci njegovi),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 3, 'zapusti Judejo in gre zopet v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 4, 'Moral je pa iti skozi Samarijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 5, 'Pride torej do samarijskega mesta, ki se imenuje Sihar, blizu zemljišča, ki ga je dal Jakob Jožefu, sinu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 6, 'Tam pa je bil studenec Jakobov. Jezus torej, truden od pota, kakor je bil, sede k studencu. Bilo je okoli šeste ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 7, 'Kar pride žena iz Samarije zajemat vode. Veli ji Jezus: Daj mi piti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 8, 'Učenci njegovi so namreč odšli v mesto, da kupijo živeža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 9, 'Pa mu žena Samarijanka reče: Kako prosiš ti, ki si Jud, mene, ki sem žena Samarijanka, naj ti dam piti? (Judje namreč se ne pečajo s Samarijani.)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 10, 'Jezus odgovori in ji reče: Ko bi poznala dar Božji in kdo je, ki ti pravi: Daj mi piti, prosila bi ti njega, in dal bi ti žive vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 11, 'Reče mu žena: Gospod, saj še zajeti nimaš s čim, in vodnjak je globok: odkod imaš torej živo vodo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 12, 'Si mar ti večji od našega očeta Jakoba, ki nam je dal ta vodnjak, in je sam iz njega pil in sinovi njegovi in živina njegova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 13, 'Jezus odgovori in ji reče: Vsak, kdor pije od te vode, bo zopet žejen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 14, 'kdorkoli pa se napije vode, ki mu jo jaz dam, ne bo žejen vekomaj, temuč voda, ki mu jo jaz dam, postane v njem studenec vode, ki teče v večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 15, 'Reče mu žena: Gospod, daj mi te vode, da ne bom žejna in da ne bom hodila semkaj zajemat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 16, 'Veli ji Jezus: Pojdi, pokliči moža svojega in pridi sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 17, 'Žena odgovori in reče: Nimam moža. Reče ji Jezus: Prav si povedala: Nimam moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 18, 'Imela si namreč pet mož, in tisti, ki ga imaš sedaj, ni tvoj mož: to si po pravici povedala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 19, 'Reče mu žena: Gospod, vidim, da si prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 20, 'Očetje naši so na tej gori molili; vi pa pravite, da je v Jeruzalemu kraj, kjer se mora moliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 21, 'Reče ji Jezus: Žena, verjemi mi, da prihaja ura, ko ne boste molili Očeta ne na tej gori, ne v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 22, 'Vi molite, česar ne veste; mi molimo, kar vemo: zakaj zveličanje pride od Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 23, 'Ali prihaja ura in je že sedaj, ko bodo pravi molilci molili Očeta v duhu in resnici; saj Oče tudi išče takih, da bi ga molili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 24, 'Bog je duh, in kateri ga molijo, morajo moliti v duhu in resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 25, 'Reče mu žena: Vem, da pride Mesija (ki se imenuje Kristus); kadar on pride, nam vse oznani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 26, 'Reče ji Jezus: Jaz sem, ki govorim s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 27, 'In v tem pridejo učenci njegovi in se čudijo, da se pogovarja z ženo; vendar pa nihče ne reče: Kaj hočeš? ali: Kaj se pogovarjaš ž njo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 28, 'Žena torej pusti svoj vrč in odide v mesto in veli ljudem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 29, 'Pridite, poglejte človeka, ki mi je povedal vse, kar sem storila, ali ni ta Kristus?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 30, 'In gredo iz mesta in pridejo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 31, 'Medtem so ga pa učenci prosili, rekoč: Rabi, jej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 32, 'On jim pa reče: Jaz imam jed, da jo jem, za katero vi ne veste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 33, 'Učenci se torej pomenkujejo med seboj: Ali mu je kdo prinesel jesti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 34, 'Reče jim Jezus: Moja jed je, da izpolnjujem voljo tega, ki me je poslal, in dopolnim delo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 35, 'Ne pravite li vi, da je še štiri mesece, pa pride žetev? Glej, pravim vam, povzdignite oči in poglejte njive, da so že bele za žetev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 36, 'Kdor žanje, prejema plačilo in zbira sad za večno življenje, da se skupaj radujeta, kdor seje in kdor žanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 37, 'Kajti v tem je pregovor resničen: Drugi je, ki seje, in drugi, ki žanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 38, 'Jaz sem vas poslal žet, česar vi niste obdelali; drugi so obdelali, in vi ste prišli v njih delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 39, 'Iz tega mesta je pa mnogo Samarijanov sprejelo vero vanj zavoljo besede žene, ki je pričala: Povedal mi je vse, kar sem storila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 40, 'Ko pridejo torej Samarijani k njemu, ga prosijo, naj ostane pri njih. In ostal je tam dva dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 41, 'In veliko več jih je sprejelo vero zavoljo njegove besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 42, 'A ženi so pravili: Sedaj ne verujemo več zavoljo tvojega govorjenja, kajti sami smo slišali in vemo, da je ta resnično Zveličar sveta, Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 43, 'Po teh dveh dneh pa gre odtod v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 44, 'Kajti Jezus sam je pričal, da prorok nima časti v svoji domovini.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 45, 'Ko pa pride v Galilejo, ga sprejmo Galilejci, ker so videli vse, kar je storil v Jeruzalemu ob prazniku; bili so namreč tudi prišli na praznik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 46, 'In zopet pride Jezus v Kano Galilejsko, kjer je bil izpremenil vodo v vino. In bil je neki kraljev uradnik, čigar sin je bil bolan, v Kafarnavmu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 47, 'Ko ta sliši, da je prišel Jezus iz Judeje v Galilejo, gre k njemu in ga prosi, naj pride doli in mu ozdravi sina; ta je namreč umiral.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 48, 'Reče mu torej Jezus: Če znamenj in čudežev ne vidite, ne boste verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 49, 'Reče mu kraljev uradnik: Gospod, pojdi doli, preden umrje otrok moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 50, 'Veli mu Jezus: Pojdi, sin tvoj je živ. Mož veruje besedi, ki mu jo je Jezus rekel, in gre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 51, 'Ko pa je že na potu doli, ga srečajo hlapci njegovi in mu sporoče, da sin njegov živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 52, 'Vpraša jih torej, obkore mu je odleglo. In mu reko: Včeraj ob sedmi uri ga je pustila mrzlica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 53, 'Tedaj spozna oče, da je bilo tisto uro, ko mu je Jezus rekel: Sin tvoj je živ. In je sprejel vero on in vsa hiša njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 4, 54, 'To je drugi čudež, ki ga je zopet storil Jezus, ko je prišel iz Judeje v Galilejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 1, 'Potem je bil praznik Judov in Jezus se napoti v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 2, 'V Jeruzalemu je pa pri Ovčjih vratih kopel, ki se hebrejski imenuje Betezda, in ima pet lop.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 3, 'V teh je ležala množica bolnikov, slepih, hromih, sušičnih, ki so pričakovali gibanja vode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 4, 'Prihajal je namreč angel ob svojem času v kopel in je kalil vodo; in kdor je prvi stopil v vodo, potem ko se je bila skalila, je ozdravel, katerokoli bolezen je imel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 5, 'Bil je pa tam neki človek, ki je bil osemintrideset let bolan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 6, 'Ko ga Jezus vidi, da leži, in zve, da je že dolgo časa bolan, mu reče: Hočeš li ozdraveti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 7, 'Bolnik mu odgovori: Gospod, nimam človeka, da bi me, kadar se voda skali, posadil v kopel; a preden sam pridem, stopi vanjo drugi pred menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 8, 'Veli mu Jezus: Vstani, vzemi posteljo svojo in hodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 9, 'In precej je mož ozdravel, in vzame posteljo svojo in hodi. Bila pa je tisti dan sobota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 10, 'Zatorej reko Judje ozdravljenemu: Sobota je, in ne smeš postelje nositi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 11, 'On pa jim odgovori: Ta, ki me je ozdravil, mi je rekel: Vzemi posteljo svojo in hodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 12, 'Vprašajo ga: Kdo je tisti človek, ki ti je rekel: Vzemi posteljo in hodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 13, 'Ozdravljenec pa ni vedel, kdo je bil; zakaj Jezus se je umaknil, ker je bilo veliko ljudstva v tem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 14, 'Potem ga najde Jezus v templju in mu reče: Glej, ozdravljen si, ne greši več, da se ti kaj hujšega ne prigodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 15, 'Človek odide in sporoči Judom, da je Jezus tisti, ki ga je ozdravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 16, 'In zato so Judje preganjali Jezusa, ker je to delal v soboto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 17, 'Jezus jim je pa odgovoril: Oče moj dela doslej, tudi jaz delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 18, 'Zato pa so Judje še bolj gledali, da bi ga umorili, ker ni le sobote prelomil, marveč tudi Boga je imenoval svojega Očeta, delajoč se enakega Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 19, 'Jezus torej odgovori in jim reče: Resnično, resnično vam pravim: Sin ne more sam od sebe ničesar delati, razen kar vidi, da dela Oče; karkoli namreč dela on, to tudi Sin dela prav tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 20, 'Kajti Oče ljubi Sina in mu kaže vse, kar sam dela, in še večja dela nego ta mu pokaže, da bi se vi čudili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 21, 'Kakor namreč Oče obuja mrtve in oživlja, tako tudi Sin oživlja, katere hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 22, 'Kajti Oče tudi ne sodi nikogar, temuč vso sodbo je izročil Sinu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 23, 'da bi vsi častili Sina, kakor časté Očeta; kdor ne časti Sina, ne časti Očeta, ki ga je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 24, 'Resnično, resnično vam pravim, kdor posluša mojo besedo in veruje temu, ki me je poslal, ima večno življenje, in ne pride na sodbo, temuč je že prešel iz smrti v življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 25, 'Resnično, resnično vam pravim, da pride ura in je že zdaj, ko mrtvi zaslišijo glas Sinu Božjega, in kateri zaslišijo, bodo živeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 26, 'Zakaj kakor ima Oče življenje v sebi, tako je dal tudi Sinu, da ima življenje v sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 27, 'In dal mu je oblast tudi soditi, ker je sin človečji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 28, 'Ne čudite se temu; kajti pride ura, ob kateri zaslišijo vsi, ki so v grobih, glas njegov');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 29, 'in pridejo ven: kateri so delali dobro, na vstajenje življenja, in kateri so delali hudo, na vstajenje sodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 30, 'Jaz ne morem sam od sebe ničesar delati. Kakor slišim, tako sodim, in sodba moja je pravična, ker ne iščem svoje volje, ampak voljo tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 31, 'Ako sam za sebe pričam, pričevanje moje ni resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 32, 'Drugi je, ki pričuje zame, in vem, da je resnično pričevanje, ki ga daje zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 33, 'Vi ste poslali k Janezu, in on je pričal za resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 34, 'Ali jaz ne sprejemam pričevanja, ki je od človeka; ali pravim to, da se vi zveličate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 35, 'On je bil svetiljka, ki je gorela in svetila: vam pa je bilo po volji, da se nekaj časa veselite svetlobe njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 36, 'Ali jaz imam večje pričevanje nego Janezovo: dela namreč, katera mi je Oče izročil, da jih dopolnim, prav ta dela, ki jih jaz delam, pričajo zame, da me je Oče poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 37, 'In Oče, ki me je poslal, je sam pričal zame. Niste nikoli slišali njegovega glasu, ne videli njegovega obličja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 38, 'in besede njegove nimate, da bi prebivala v vas: ker temu, ki ga je on poslal, ne verujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 39, 'Preiskujete pisma, ker mislite, da imate v njih večno življenje, in ta so, ki pričajo zame;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 40, 'a nočete priti k meni, da bi imeli življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 41, 'Slave od ljudi ne sprejemam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 42, 'Ali poznam vas, da nimate ljubezni Božje v sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 43, 'Jaz sem prišel v Očeta svojega imenu, in me ne sprejemate; če kdo drugi pride v svojem imenu, njega sprejmete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 44, 'Kako morete verovati, ko sprejemate slavo drug od drugega, slave pa, ki je od edinega Boga, ne iščete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 45, 'Ne mislite, da vas bom jaz tožil pri Očetu; je že, ki vas toži: Mojzes, ki ste nanj postavili upanje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 46, 'Ko bi namreč verovali Mojzesu, bi verovali meni; zakaj on je pisal o meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 5, 47, 'Če pa njegovim pismom ne verujete, kako boste mojim besedam verjeli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 1, 'Potem odide Jezus na oni kraj morja Galilejskega ali Tiberijskega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 2, 'In za njim je šla velika množica, ker so videli njegove čudeže, ki jih je delal na bolnikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 3, 'Jezus pa gre na goro in tu sede z učenci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 4, 'Bila je pa blizu Velika noč, praznik Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 5, 'Ko torej povzdigne Jezus oči in vidi, da velika množica prihaja k njemu, reče Filipu: Kje naj kupimo kruha, da bodo ti jedli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 6, 'To pa je rekel, da ga izkuša; kajti on je vedel, kaj hoče storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 7, 'Filip mu odgovori: Za dvesto denarjev kruha jim ni dosti, da bi vsak izmed njih dobil kaj malega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 8, 'Reče mu eden učencev njegovih, Andrej, Simona Petra brat:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 9, 'Deček je tu, ki ima pet ječmenovih hlebov in dve ribi; ali kaj je to med toliko?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 10, 'Jezus veli: Naredite, da se ljudje posadé. Bilo je pa veliko trave na tem mestu. In posadé se možje, kakih pet tisoč po številu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 11, 'Tedaj vzame Jezus hlebe in ko zahvali, jih razdeli učencem, učenci pa tem, ki so sedeli; ravno tako jim dá tudi od ribic, kolikor so hoteli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 12, 'Ko se pa nasitijo, veli učencem svojim: Zberite ostale kosce, da nič ne pogine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 13, 'Zbero torej in napolnijo dvanajst košev koscev od petih hlebov ječmenovih, ki so ostali tem, ki so jedli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 14, 'Ko torej vidijo ljudje čudež, ki ga je Jezus storil, govore: Ta je res prorok, ki ima priti na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 15, 'Jezus torej, ker spozna, da hočejo priti in ga siloma odvesti, da ga postavijo za kralja, se zopet umakne na goro, on sam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 16, 'Ko se pa zvečeri, gredo učenci njegovi k morju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 17, 'in stopivši v ladjo, se popeljejo na oni kraj morja v Kafarnavm. In tema je že nastala, in Jezus še ni prišel k njim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 18, 'in morje je bilo razburkano, ker je pihal močan veter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 19, 'Ko pa veslajo kakih petindvajset ali trideset tečajev daleč, ugledajo Jezusa, da hodi po morju in se približuje ladji, in se preplašijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 20, 'On pa jim reče: Jaz sem; ne bojte se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 21, 'Hočejo ga torej vzeti v ladjo; in precej je bila ladja pri kraju, kamor so se peljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 22, 'Drugi dan, ko vidi ljudstvo, ki je stalo onkraj morja, da ni bilo tam druge ladjice razen tiste ene, ki so vanjo vstopili učenci, in da Jezus ni stopil z učenci svojimi v ladjo, ampak da so bili učenci sami odšli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 23, '(prišle so pa druge ladjice iz Tiberije blizu h kraju, kjer so bili jedli kruh, ko je Gospod zahvalil),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 24, 'ko torej ljudstvo izprevidi, da Jezusa ni tu in tudi učencev njegovih ne: stopijo tudi oni v ladjice in pridejo v Kafarnavm, da poiščejo Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 25, 'In ko ga najdejo onkraj morja, mu reko: Rabi, kdaj si prišel sem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 26, 'Odgovori jim Jezus in reče: Resnično, resnično vam pravim, iščete me ne zato, ker ste videli čudeže, temuč ker ste jedli od hlebov in ste se nasitili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 27, 'Trudite se ne za jed, ki mine, ampak za jed, ki ostane v večno življenje, ki vam jo dá Sin človekov: zakaj njega je potrdil Oče, Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 28, 'Reko mu torej: Kaj naj storimo, da delamo dela Božja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 29, 'Jezus jim odgovori in reče: To je delo Božje, da verujete v tega, ki ga je on poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 30, 'Pa mu reko: Kakšno znamenje torej pokažeš, da bi videli in verovali? kaj delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 31, 'Očetje naši so jedli mano v puščavi, kakor je pisano: „Kruh iz nebes jim je dal jesti“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 32, 'Jezus jim pa reče: Resnično, resnično vam pravim: Ne Mojzes vam je dal kruha iz nebes, marveč Oče moj vam daje pravi kruh iz nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 33, 'Kruh Božji namreč je ta, ki prihaja iz nebes in daje življenje svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 34, 'Reko mu torej: Gospod, daj nam vsekdar tega kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 35, 'Jezus jim reče: Jaz sem kruh življenja: kdor prihaja k meni, ne bo nikoli lačen, in kdor veruje v me, ne bo nikdar žejen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 36, 'Ali povedal sem vam, da ste me videli, in vendar ne verujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 37, 'Vse, kar mi daje Oče, pride k meni, in tega, ki k meni prihaja, ne pahnem ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 38, 'Zakaj stopil sem iz nebes, ne da bi delal svojo voljo, marveč voljo tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 39, 'To pa je volja tega, ki me je poslal, da ničesar ne izgubim od tega, kar mi je dal, temuč da vse to obudim poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 40, 'Kajti to je volja Očeta mojega, da ima večno življenje vsak, kdor vidi Sina in veruje vanj, in jaz ga obudim poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 41, 'Tedaj godrnjajo Judje nad njim, da je rekel: Jaz sem kruh, ki je prišel iz nebes,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 42, 'in govore: Ali ni ta Jezus, sin Jožefov, čigar očeta in mater poznamo? Kako da sedaj pravi: Iz nebes sem prišel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 43, 'Jezus odgovori in reče: Ne godrnjajte med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 44, 'Nihče ne more priti k meni, če ga ne vleče Oče, ki me je poslal, in jaz ga obudim poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 45, 'Pisano je v prorokih: „In vsi bodo učeni od Boga“. Vsak, ki je slišal Očeta in se je naučil, prihaja k meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 46, 'Ne pravim, da je kdo videl Očeta, razen tisti, ki je od Boga: ta je videl Očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 47, 'Resnično, resnično vam pravim: Kdor veruje, ima večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 48, 'Jaz sem kruh življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 49, 'Očetje vaši so jedli mano v puščavi in so pomrli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 50, 'Ta je kruh, ki prihaja iz nebes, da ne umre, kdor jé od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 51, 'Jaz sem živi kruh, ki je prišel iz nebes; če kdo jé od tega kruha, bo živel vekomaj. Kruh pa, ki ga jaz dam, je moje meso, ki ga dam za življenje sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 52, 'Judje se pa prepirajo med seboj, govoreč: Kako nam more ta dati svoje meso jesti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 53, 'Jezus jim pa reče: Resnično, resnično vam pravim: Če ne jeste mesa Sinu človekovega in ne pijete njegove krvi, nimate življenja v sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 54, 'Kdor jé moje meso in pije mojo kri, ima večno življenje, in jaz ga obudim poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 55, 'Kajti meso moje je prava jed in kri moja je prava pijača.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 56, 'Kdor jé moje meso in pije mojo kri, prebiva v meni in jaz v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 57, 'Kakor je mene poslal živi Oče in jaz živim zaradi Očeta: tako bo tudi tisti, ki mene jé, živel zaradi mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 58, 'Ta je kruh, ki je prišel iz nebes; ne kakor so Očetje vaši jedli in so pomrli: kdor jé ta kruh, bo živel vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 59, 'To je povedal v shodnici, ko je učil v Kafarnavmu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 60, 'Mnogi torej učencev njegovih, ko so to slišali, reko: Trda je ta beseda; kdo jo more poslušati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 61, 'Vedoč pa sam v sebi, da učenci njegovi godrnjajo nad tem, jim reče Jezus: To vam je v spotiko?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 62, 'Kaj pa, ko boste videli Sina človekovega, da gre gori, kjer je bil poprej?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 63, 'Duh je to, kar oživlja, meso ne pomaga nič; besede, ki sem vam jih jaz govoril, so duh in so življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 64, 'Toda so med vami nekateri, ki ne verujejo. Jezus je namreč od začetka vedel, kateri so, ki ne verujejo, in kdo je, ki ga izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 65, 'In reče: Zato sem vam rekel, da ne more nihče priti k meni, če mu ni dano od Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 66, 'Vsled tega je mnogo učencev njegovih odstopilo in nič več niso hodili ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 67, 'Reče torej Jezus dvanajsterim: Ali hočete tudi vi oditi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 68, 'Simon Peter mu odgovori: Gospod, h komu pojdemo? Besede večnega življenja imaš ti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 69, 'In mi smo verovali in vemo, da si ti Svetnik Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 70, 'Odgovori jim Jezus: Ali nisem jaz vas dvanajsterih izvolil? In eden izmed vas je hudič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 6, 71, 'To pa je rekel o Judu, sinu Simona Iškariota; kajti ta ga je imel izdati, eden izmed dvanajsterih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 1, 'In poten je Jezus hodil po Galileji; kajti po Judeji ni hotel hoditi, ker so Judje gledali, da bi ga umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 2, 'Bil je pa blizu judovski praznik šatorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 3, 'Zato mu reko bratje njegovi: Idi odtod in pojdi v Judejo, da tudi učenci tvoji vidijo dela tvoja, ki jih delaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 4, 'Zakaj nihče, ki hoče biti javno poznan, ne dela ničesar na skrivnem. Če take reči delaš, pokaži se svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 5, 'Tudi bratje njegovi namreč niso verovali vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 6, 'Reče jim torej Jezus: Moj čas še ni prišel; vaš čas pa je vsekdar prikladen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 7, 'Vas ne more svet sovražiti; mene pa sovraži, ker jaz pričujem o njem, da so dela njegova hudobna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 8, 'Vi pojdite na praznik; jaz še ne grem na ta praznik, ker se moj čas še ni dopolnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 9, 'In ko jim je to povedal, je ostal v Galileji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 10, 'Ko so pa bratje njegovi odšli na praznik, tedaj odide tudi on, ne očitno, temuč kakor skrivaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 11, 'Judje so ga torej iskali ob prazniku in govorili: Kje je tisti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 12, 'In bilo je dosti govorjenja o njem med množicami. Nekateri so pravili: Dober je; drugi pa so trdili: Ne, ampak ljudstvo slepari.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 13, 'Vendar pa nihče ni očitno govoril o njem zavoljo strahu pred Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 14, 'Ko je pa minilo že pol praznika, vstopi Jezus v tempelj in uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 15, 'In Judje se čudijo ter pravijo: Kako je ta učen v pismih, ko se ni šolal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 16, 'Odgovori jim torej Jezus in reče: Moj nauk ni moj, ampak tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 17, 'Če hoče kdo njegovo voljo izpolnjevati, razpozna, je li ta nauk iz Boga ali če jaz sam od sebe govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 18, 'Kdor govori sam od sebe, išče lastne slave; kdor pa išče slave tega, ki ga je poslal, ta je resničen in nepravičnosti ni v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 19, 'Vam li ni Mojzes dal postave? In vendar nihče iz vas ne izpolnjuje postave. Zakaj gledate, da bi me umorili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 20, 'Ljudstvo odgovori: Hudiča imaš! Kdo gleda, da bi te umoril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 21, 'Jezus odgovori in jim reče: Eno delo sem storil, in vsi se čudite temu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 22, 'Mojzes vam je dal obrezo (ne da se je od Mojzesa začela, ampak od očakov), in v soboto obrezujete človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 23, 'Če prejme človek obrezo v soboto, da se ne prelomi postava Mojzesova, zakaj se nad menoj hudujete, da sem celega človeka ozdravil v soboto?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 24, 'Ne sodite po licu, ampak sodite pravično sodbo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 25, 'Tedaj reko nekateri izmed Jeruzalemcev: Ali ni ta tisti, ki gledajo, da bi ga umorili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 26, 'In glejte, očitno govori in nič mu ne reko. Ali so mar poglavarji v resnici spoznali, da je ta Kristus?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 27, 'Toda za tega vemo, odkod je; za Kristusa pa, kadar pride, ne bo nihče vedel, odkod je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 28, 'Jezus torej zakliče, učeč v templju, in reče: Poznate me in tudi veste, odkod sem; in sam od sebe nisem prišel: je pa resničen, ki me je poslal, katerega vi ne poznate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 29, 'Jaz ga poznam, ker sem od njega, in on me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 30, 'Gledali so torej, da bi ga zgrabili; ali nihče ni položil nanj roke, ker ura njegova še ni bila prišla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 31, 'Mnogi pa izmed ljudstva so sprejeli vero vanj; in so govorili: Ali bo Kristus, kadar pride več čudežev storil, nego jih je ta storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 32, 'Farizeji zaslišijo, da si ljudstvo to o njem šepeče; in višji duhovniki in farizeji pošljejo služabnike, naj ga ujemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 33, 'Reče torej Jezus: Še malo časa sem z vami, in pojdem k temu, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 34, 'Iskali me boste, a me ne najdete; in kjer sem jaz, tja vi ne morete priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 35, 'Tedaj reko Judje med seboj: Kam pojde ta, da ga mi ne najdemo? Ali pojde k tem, ki so razkropljeni med Grki, in bo učil Grke?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 36, 'Kakšna je ta beseda, ki jo je rekel: Iskali me boste, a me ne najdete, in kjer sem jaz, vi ne morete priti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 37, 'A poslednji veliki dan praznika je stal Jezus in klical, rekoč: Če je kdo žejen, naj pride k meni in pije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 38, 'Kdor veruje v mene, kakor pravi pismo, reke žive vode poteko iz telesa njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 39, 'To je pa rekel o Duhu, ki so ga imeli prejeti ti, ki so verovali vanj; Duh namreč še ni bil dan, ker Jezus še ni bil oslavljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 40, 'Nekateri iz množice, čujoč te besede, reko torej: Ta je zares prorok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 41, 'Drugi pravijo: Ta je Kristus. Drugi pa govore: Ali pride Kristus iz Galileje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 42, 'Ali ne pravi pismo, da pride Kristus iz semena Davidovega in iz trga Betlehema, kjer je bil David?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 43, 'Nastane torej razpor med ljudstvom zaradi njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 44, 'A nekateri izmed njih so ga hoteli zgrabiti; pa nihče ni položil nanj rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 45, 'In služabniki pridejo k višjim duhovnikom in farizejem; in ti jim reko: Zakaj ga niste pripeljali?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 46, 'Služabniki odgovore: Nikoli noben človek ni tako govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 47, 'Farizeji pa jim odgovore: Ali ste tudi vi zapeljani?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 48, 'Je li kdo izmed prvakov sprejel vero vanj, ali izmed farizejev?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 49, 'Ampak ta druhal, ki ne pozna zakona; prokleti so!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 50, 'Reče jim Nikodem, ki je bil prej prišel k njemu in je bil eden izmed njih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 51, 'Ali postava naša sodi človeka, če ga prej ne zaslišijo in se ne izve, kaj dela?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 52, 'Odgovore in mu reko: Si li mar tudi ti iz Galileje? Preišči in poglej, da iz Galileje ne vstane noben prorok. [');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 7, 53, 'In odidejo vsak na svoj dom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 1, 'Jezus pa gre na Oljsko goro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 2, 'A zjutraj pride zopet v tempelj. In vse ljudstvo se zbere k njemu, in sede ter jih uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 3, 'Pripeljejo pa pismarji in farizeji k njemu ženo, v prešeštvu zasačeno, jo postavijo na sredo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 4, 'in mu reko: Učenik, ta žena je ravnokar v prešeštvu zasačena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 5, 'V postavi pa nam je Mojzes zapovedal, naj take s kamenjem posujemo. Ti torej kaj praviš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 6, 'To pa govore, izkušajoč ga, da bi ga mogli zatožiti. A Jezus se skloni ter piše s prstom po tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 7, 'Ko pa le še vprašujejo, se zravna in jim reče: Kdor je med vami brez greha, naj prvi vrže kamen nanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 8, 'In zopet se skloni in piše po tleh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 9, 'Oni pa, ko so to slišali, odhajajo drug za drugim, počenši od starejših, celo do zadnjih. In Jezus ostane sam in žena, na sredi stoječ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 10, 'Jezus pa, ko se zravna pokonci in razen žene ne vidi nikogar, ji reče: Žena, kje so oni? ali te ni nobeden obsodil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 11, 'Ona pa reče: Nobeden, Gospod. A Jezus ji reče: Tudi jaz te ne obsojam; pojdi in odslej več ne greši!]');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 12, 'Jezus jim torej zopet govori, rekoč: Jaz sem luč sveta; kdor gre za menoj, ne bo hodil po temi, temuč bo imel luč življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 13, 'Reko mu pa farizeji: Ti sam zase pričuješ; pričevanje tvoje ni resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 14, 'Jezus odgovori in jim reče: Čeprav jaz sam zase pričujem, je resnično pričevanje moje, ker vem, odkod sem prišel in kam grem; vi pa ne veste, odkod sem prišel in kam grem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 15, 'Vi po mesu sodite; jaz ne sodim nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 16, 'Če pa tudi sodim, je resnična sodba moja; zakaj nisem sam, marveč jaz in Oče, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 17, 'Pisano pa je tudi v zakonu vašem, da je dveh človekov pričevanje resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 18, 'Jaz sem, ki pričujem sam zase, in pričuje zame Oče, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 19, 'Reko mu tedaj: Kje je tvoj Oče? Jezus odgovori: Niti mene ne poznate niti Očeta mojega; ko bi mene poznali, poznali bi tudi Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 20, 'Te besede je govoril pri zakladnici, učeč v templju; in nihče ga ni zgrabil, ker še ni bila prišla ura njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 21, 'In Jezus jim zopet reče: Jaz odhajam, in iskali me boste in v grehu svojem umrjete. Kamor jaz grem, vi ne morete priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 22, 'Judje torej govore: Ali se sam umori, da pravi: Kamor jaz grem, vi ne morete priti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 23, 'In jim reče: Vi ste od zdolaj, jaz sem odzgoraj; vi ste od tega sveta, jaz nisem od tega sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 24, 'Zatorej sem vam rekel, da umrjete v grehih svojih; če namreč ne boste verovali, da sem jaz, umrjete v grehih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 25, 'Reko mu torej: Kdo si? Reče jim Jezus: To, kar vam že od začetka pravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 26, 'Mnogo imam o vas govoriti in soditi; ali ta, ki me je poslal, je resničen; in jaz govorim svetu to, kar sem od njega slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 27, 'Niso pa spoznali, da jim je govoril o Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 28, 'Zato reče Jezus: Kadar boste povišali Sina človekovega, tedaj spoznate, da sem jaz in da sam od sebe ničesar ne delam, temuč kakor me je naučil Oče moj, to govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 29, 'In ta, ki me je poslal, je z menoj; ni me pustil samega, zakaj jaz delam vsekdar to, kar je njemu pogodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 30, 'Ko je to govoril, jih je mnogo sprejelo vero vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 31, 'Tedaj govori Jezus tistim Judom, ki so mu verovali: Če vi ostanete v besedi moji, bodete zares učenci moji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 32, 'in spoznate resnico, in resnica vas osvobodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 33, 'Odgovore mu: Seme Abrahamovo smo in nikomur še nismo nikdar sužnjevali; kako praviš ti: Postanete svobodni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 34, 'Jezus jim odgovori: Resnično, resnično vam pravim, da vsak, kdor dela greh, je suženj grehu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 35, 'Suženj pa ne ostane v hiši vekomaj; sin ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 36, 'Če vas torej Sin osvobodi, bodete res svobodni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 37, 'Vem, da ste seme Abrahamovo; ali gledate, kako bi me umorili, ker beseda moja nima mesta v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 38, 'Jaz govorim, kar sem videl pri svojem Očetu; tudi vi torej delate, kar ste od svojega očeta slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 39, 'Odgovore in mu reko: Oče naš je Abraham. Reče jim Jezus: Ko bi bili sinovi Abrahamovi, bi delali Abrahamova dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 40, 'Sedaj pa gledate, kako bi me umorili, človeka, ki sem vam povedal resnico, ki sem jo slišal od Boga: tega Abraham ni storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 41, 'Vi delate očeta svojega dela. Pa mu reko: Mi nismo iz nečistosti rojeni; enega Očeta imamo, Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 42, 'Jezus jim reče: Ko bi bil Bog vaš Oče, bi ljubili mene, zakaj jaz sem od Boga izšel in prišel; nisem namreč sam od sebe prišel, temuč on me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 43, 'Zakaj govora mojega ne umete? Ker ne morete moje besede poslušati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 44, 'Vi ste iz očeta hudiča in želje očeta svojega hočete izpolnjevati. On je bil ubijalec ljudi od začetka, in na resnici ne stoji, ker resnice ni v njem. Kadar govori laž, govori iz lastnega, ker je lažnik in oče laži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 45, 'Ker pa jaz govorim resnico, mi ne verujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 46, 'Kdo izmed vas me more dolžiti greha? Če pa resnico govorim, zakaj mi vi ne verujete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 47, 'Kdor je iz Boga, posluša Božje besede; zato vi ne poslušate, ker niste iz Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 48, 'Judje odgovore in mu reko: Ali ne pravimo prav, da si Samarijan in imaš zlega duha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 49, 'Jezus odgovori: Jaz nimam zlega duha, ampak častim Očeta svojega; a vi me onečaščujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 50, 'Jaz pa ne iščem svoje slave; je eden, ki je išče in sodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 51, 'Resnično, resnično vam pravim: ako kdo ohrani besedo mojo, ne bo videl smrti vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 52, 'Reko mu Judje: Sedaj smo spoznali, da imaš zlega duha. Abraham je umrl in proroki, a ti praviš: Ako kdo ohrani besedo mojo, ne okusi smrti vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 53, 'Kaj si nemara ti večji od našega očeta Abrahama, ki je umrl? Tudi proroki so pomrli. Koga se ti sam delaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 54, 'Jezus odgovori: Če se jaz sam slavim, slava moja ni nič: Oče moj je, ki me slavi, o katerem vi pravite, da je vaš Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 55, 'a niste ga spoznali, jaz pa ga poznam, in ko bi rekel, da ga ne poznam, bi bil lažnivec, vam enak. Ali poznam ga in besedo njegovo izpolnjujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 56, 'Abraham, oče vaš, se je veselil, da bo videl moj dan; in videl ga je in se je vzradoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 57, 'Reko mu torej Judje: Petdeset let še nimaš, in Abrahama si videl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 58, 'Jezus jim reče: Resnično, resnično vam pravim: Preden je bil Abraham, sem jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 8, 59, 'Tedaj pograbijo za kamenje, da bi ga lučali vanj. Ali Jezus se skrije in odide iz templja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 1, 'In gredoč mimo, ugleda človeka, ki je bil slep od rojstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 2, 'In vprašajo ga učenci njegovi, rekoč: Rabi, kdo je grešil: ta ali roditelji njegovi, da se je slep rodil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 3, 'Jezus odgovori: Grešil ni ne ta, ne roditelji njegovi, temuč da se razodenejo dela Božja na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 4, 'Jaz moram delati dela tega, ki me je poslal, dokler je dan; pride noč, ko nihče ne bo mogel delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 5, 'Dokler sem na svetu, sem luč sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 6, 'Rekši to, pljune na zemljo in napravi blato iz sline in pomaže z blatom slepcu oči');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 7, 'in mu reče: Pojdi, umij se v kopeli Siloamu (kar se tolmači: Poslan). Odide torej in se umije, ter se vrne z vidom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 8, 'A sosedje, in kateri so ga prej videli, da je bil berač, govore: Ni li ta, ki je sedel in prosjačil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 9, 'Drugi pravijo: On je; drugi pa: Ni, le podoben mu je. Sam pravi: Jaz sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 10, 'Reko mu torej: Kako pa so se ti odprle oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 11, 'On odgovori: Človek, ki se imenuje Jezus, je napravil blato, in mi je pomazal oči in mi rekel: Pojdi v Siloam in umij se. Šel sem torej in se umil, in sem izpregledal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 12, 'Reko mu: Kje je on? Reče: Ne vem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 13, 'Peljejo ga k farizejem, tega, ki je bil nekdaj slep.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 14, 'Bila je pa sobota tisti dan, ko je Jezus naredil blato in mu odprl oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 15, 'Zdaj ga torej vprašujejo tudi farizeji, kako je izpregledal. On jim pa reče: Blato mi je dal na oči, in umil sem se in vidim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 16, 'Tedaj reko nekateri izmed farizejev: Ta človek ni od Boga, ker sobote ne posvečuje. Drugi pravijo: Kako more človek grešnik take čudeže delati? In razpor je bil med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 17, 'Zopet reko slepcu: Kaj ti praviš o njem, ker ti je odprl oči? On pa reče: Prorok je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 18, 'Judje torej niso verjeli, da je bil slep in da je izpregledal, dokler niso poklicali roditeljev tega, ki je izpregledal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 19, 'In jih vprašajo, rekoč: Je li vaš ta sin, ki o njem pravite, da se je slep rodil? Kako pa sedaj vidi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 20, 'Odgovore jim roditelji njegovi in reko: Vemo, da je ta sin naš in da se je slep rodil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 21, 'kako pa sedaj vidi, ne vemo, ali kdo mu je oči odprl, tudi ne vemo. Njega vprašajte, leta ima, naj govori sam zase.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 22, 'To so rekli roditelji njegovi zato, ker so se bali Judov; zakaj Judje so se bili že dogovorili, naj se izobči iz shodnice, kdor bi ga pripoznal za Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 23, 'Zato so roditelji njegovi rekli: Leta ima, njega vprašajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 24, 'Pokličejo torej drugič človeka, ki je bil slep, in mu reko: Daj Bogu čast! mi vemo, da je ta človek grešnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 25, 'On pa odgovori: Če je grešnik, ne vem; eno vem, da sem bil slep, in da sedaj vidim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 26, 'Reko mu torej: Kaj ti je storil? Kako ti je odprl oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 27, 'Odgovori jim: Saj sem vam že povedal, in niste slišali; čemu hočete zopet slišati? Ali hočete tudi vi postati njegovi učenci?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 28, 'Oni pa ga opsujejo in reko: Ti si njegov učenec; mi smo Mojzesovi učenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 29, 'Mi vemo, da je z Mojzesom govoril Bog; za tega pa ne vemo, odkod je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 30, 'Človek odgovori in jim reče: To je pa res čudno, da vi ne veste, odkod je, in vendar mi je odprl oči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 31, 'Vemo pa, da grešnikov Bog ne sliši, ampak če kdo časti Boga in izpolnjuje voljo njegovo, tega sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 32, 'Od vekomaj se ni slišalo, da bi bil kdo odprl oči od rojstva slepemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 33, 'Ko ta ne bi bil od Boga, ne bi mogel ničesar storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 34, 'Odgovore in mu reko: Ves v grehih si se rodil, pa boš ti nas učil? In ga pahnejo ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 35, 'Jezus zasliši, da so ga vrgli ven, in ko ga najde, mu reče: Veruješ li v Sina Božjega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 36, 'On odgovori in reče: In kdo je, Gospod, da bi veroval vanj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 37, 'Jezus mu reče: Videl si ga, in ki s teboj govori, ta je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 38, 'On pa reče: Verujem, Gospod! in ga moli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 39, 'In Jezus veli: Na sodbo sem prišel jaz na ta svet, da izpregledajo, kateri ne vidijo, in kateri vidijo, da oslepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 40, 'In slišijo to izmed farizejev tisti, ki so bili ž njim, in mu reko: Ali smo tudi mi slepi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 9, 41, 'Jezus jim reče: Ko bi bili slepi, ne bi imeli greha; sedaj pa pravite: Vidimo; zato greh vaš ostaja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 1, 'Resnično, resnično vam pravim: Kdor ne vhaja skozi vrata v ovčji hlev, ampak lazi drugod vanj, ta je tat in razbojnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 2, 'Kdor pa vhaja skozi vrata, ta je pastir ovac.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 3, 'Temu vratar odpira, in ovce poslušajo glas njegov, in svoje ovce kliče po imenu in jih vodi na pašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 4, 'Ko vse ovce svoje izpusti, gre pred njimi, in ovce gredo za njim, ker poznajo glas njegov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 5, 'a za tujcem ne gredo, temuč beže od njega, ker ne poznajo glasu tujcev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 6, 'To priliko jim je povedal Jezus, ali oni niso razumeli, kaj bi bilo to, kar jim je pravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 7, 'Jezus jim torej zopet reče: Resnično, resnično vam pravim, da sem jaz vrata k ovcam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 8, 'Vsi, kolikor jih je prišlo pred menoj, so tatje in razbojniki; ali ovce jih niso poslušale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 9, 'Jaz sem vrata: skozi mene če kdo gre noter, bo zveličan, in bo hodil noter in ven in najde pašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 10, 'Tat ne pride, razen da krade in kolje in pokonča; jaz sem prišel, da imajo življenje in da imajo obilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 11, 'Jaz sem dobri pastir. Dobri pastir dá svoje življenje za ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 12, 'Najemnik pa, ki ni pastir, ki mu ovce niso lastne, vidi volka, da gre in zapusti ovce in zbeži, in volk trga in razganja ovce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 13, 'on pa beži, ker je najemnik, in ne mara za ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 14, 'Jaz sem dobri pastir, in poznam svoje in moje poznajo mene:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 15, 'kakor Oče mene pozna in jaz Očeta poznam; in življenje svoje dam za ovce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 16, 'In imam še drugih ovac, ki niso iz tega hleva; tudi te moram pripeljati, in bodo poslušale moj glas, in bode ena čreda, eden pastir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 17, 'Zato me Oče ljubi, ker jaz dam življenje svoje, da ga zopet vzamem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 18, 'Nihče ga ne jemlje od mene, marveč jaz ga dajem sam od sebe. Oblast imam, da ga dam, in oblast imam, da ga zopet vzamem. To zapoved sem prejel od Očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 19, 'Med Judi nastane zopet razpor zavoljo teh besed.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 20, 'Mnogi izmed njih pa govore: Zlega duha ima in ob pamet je, kaj ga poslušate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 21, 'Drugi pravijo: Te besede ne morejo prihajati od obsedenca; ali more zli duh slepcem odpirati oči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 22, 'Bil pa je praznik posvečenja templja v Jeruzalemu, in bila je zima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 23, 'In Jezus se je izprehajal v templju po lopi Salomonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 24, 'Obstopijo ga torej Judje in mu reko: Doklej nas pustiš v negotovosti? Če si ti Kristus, povej nam naravnost!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 25, 'Odgovori jim Jezus: Povedal sem vam, pa ne verujete. Dela, ki jih jaz delam v imenu Očeta svojega, ta pričajo zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 26, 'Toda vi ne verujete, ker niste izmed mojih ovac.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 27, 'Moje ovce poslušajo glas moj, in jaz jih poznam, in za menoj hodijo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 28, 'in jaz jim dajem večno življenje, in nikdar se ne pogube, in nihče jih ne iztrga iz moje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 29, 'Oče moj, ki mi jih je dal, je večji od vsega, in nihče jih ne more iztrgati iz roke Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 30, 'Jaz in Oče sva eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 31, 'Judje zopet pograbijo za kamenje, da bi ga kamenali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 32, 'Odgovori jim Jezus: Veliko dobrih del sem vam pokazal od Očeta svojega; za katero teh del me kamenate?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 33, 'Judje mu odgovore: Za dobro delo te ne kamenamo, ampak za kletvino, in ker se ti, ki si človek, delaš Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 34, 'Jezus jim odgovori: Ni li pisano v zakonu vašem: „Jaz sem rekel: bogovi ste“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 35, 'Če je imenoval bogove tiste, ki je prišla beseda Božja k njim, in pismo se ne more ovreči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 36, 'zakaj pa meni, ki me je Oče posvetil in na svet poslal, pravite vi: Preklinjaš, ker sem rekel: Sin Božji sem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 37, 'Ako ne delam del Očeta svojega, mi ne verujte;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 38, 'ako pa delam, čeprav meni ne verujete, vsaj delom verujte: da spoznate in verujete, da je Oče v meni in jaz v Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 39, 'In zopet poskušajo, da bi ga prijeli, ali umakne se jim izpod rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 40, 'In odide zopet na oni kraj Jordana, na mesto, kjer je prej Janez krščeval; in ostane tu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 41, 'In mnogo jih pride k njemu; in pravijo: Janez res ni storil nobenega čudeža, ali karkoli je Janez povedal za tega, je bilo vse resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 10, 42, 'In mnogo jih je tu sprejelo vero vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 1, 'Bil je pa eden bolan, po imenu Lazar, iz Betanije, iz trga Marije in Marte, njene sestre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 2, 'Marija, katere brat Lazar je bil bolan, pa je bila ta, ki je pomazilila Gospoda z mazilom in mu utrla noge z lasmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 3, 'Sestri torej pošljeta k njemu, rekoč: Gospod, glej, ki ga ti ljubiš, je bolan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 4, 'Ko pa Jezus sliši, reče: Ta bolezen ni za smrt, marveč za slavo Božjo, da se Sin Božji po njej oslavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 5, 'Jezus je pa ljubil Marto in njeno sestro in Lazarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 6, 'Ko torej zasliši, da je bolan, tedaj ostane še dva dni na tistem mestu, kjer je bil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 7, 'Potem šele veli učencem svojim: Pojdimo zopet v Judejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 8, 'Učenci mu reko: Rabi, ravnokar so te hoteli Judje s kamenjem posuti, pa pojdeš zopet tja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 9, 'Jezus odgovori: Nima li dan dvanajst ur? Če kdo po dnevi hodi, se ne spotakne, ker vidi luč tega sveta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 10, 'če pa kdo po noči hodi, se spotakne, ker ni luči v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 11, 'To je povedal, in potem reče: Lazar, prijatelj naš, je zaspal; pa grem, da ga prebudim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 12, 'Reko mu torej učenci njegovi: Gospod, če je zaspal, ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 13, 'Rekel pa je to Jezus o smrti njegovi; a oni so mislili, da pravi o navadnem spanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 14, 'Tedaj jim Jezus razločno pove: Lazar je umrl;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 15, 'in radujem se zavoljo vas, da nisem bil tam, da boste verovali; pa pojdimo k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 16, 'Tedaj reče Tomaž, ki se imenuje Dvojček, součencem: Pojdimo še mi, da umremo ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 17, 'Ko torej Jezus pride, ga najde že štiri dni ležečega v grobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 18, 'Bila je pa Betanija blizu Jeruzalema, kakih petnajst tečajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 19, 'In mnogo izmed Judov jih je bilo prišlo k Marti in Mariji, da bi ju tolažili po njunem bratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 20, 'Ko torej zasliši Marta, da prihaja Jezus, mu gre naproti; a Marija je doma sedela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 21, 'Marta torej reče Jezusu: Gospod, ko bi bil ti tukaj, brat moj ne bi bil umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 22, 'A tudi sedaj vem, karkoli poprosiš Boga, ti Bog da.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 23, 'Reče ji Jezus: Brat tvoj vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 24, 'Marta mu reče: Vem, da vstane ob vstajenju poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 25, 'Reče ji Jezus: Jaz sem vstajenje in življenje; kdor v mene veruje, bo živel, čeprav umre;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 26, 'in vsak, kdor živi in veruje vame, ne umre vekomaj. Veruješ li to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 27, 'Reče mu: Da, Gospod, verujem, da si ti Kristus, Sin Božji, ki je imel priti na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 28, 'In rekši to, odide in pokliče skrivaj Marijo, sestro svojo, rekoč: Učenik je tu in te kliče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 29, 'Ona pa, ko zasliši, hitro vstane in pride k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 30, 'Jezus namreč še ni bil prišel v trg, temuč je bil še na mestu, kjer ga je bila Marta srečala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 31, 'Ko pa vidijo Judje, ki so bili ž njo v hiši in so jo tolažili, da je Marija hitro vstala in odšla, gredo za njo, misleč, da gre h grobu, da bi tam jokala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 32, 'Ko torej pride Marija tja, kjer je Jezus, in ga ugleda, mu pade k nogam in mu reče: Gospod, ko bi bil ti tukaj, brat moj ne bi bil umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 33, 'Jezus pa, ko jo vidi, da joka, in Judje, ki so prišli ž njo, da jokajo, se zgrozi v duhu in postane sam žalosten,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 34, 'in reče: Kam ste ga položili? Reko mu: Pridi in poglej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 35, 'Jezus se razjoka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 36, 'Judje tedaj reko: Glej, kako ga je ljubil!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 37, 'A nekateri izmed njih reko: Ali ni mogel on, ki je slepemu oči odprl, storiti, da bi tudi ta ne bil umrl?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 38, 'In Jezus se zopet zgrozi v sebi in pride h grobu. Bila je pa votlina in kamen je ležal na njej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 39, 'Jezus veli: Vzdignite kamen! Marta, sestra rajnikova, mu reče: Gospod, že smrdi; zakaj štiri dni je že v grobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 40, 'Veli ji Jezus: Ali ti nisem rekel, da boš videla slavo Božjo, če veruješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 41, 'Tedaj odvalijo kamen, kjer je mrtvec ležal. A Jezus povzdigne oči kvišku in reče: Oče, zahvaljujem te, da si me uslišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 42, 'Pa jaz sem vedel, da me vsekdar poslušaš; toda zaradi ljudstva, ki okoli stoji, sem to rekel, da bi verovali, da si me ti poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 43, 'In ko je to rekel, zakliče z močnim glasom: Lazar, pridi ven!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 44, 'In mrtvec izide, povezan na nogah in rokah s povoji, in njegov obraz je bil obvezan s prtom. Veli jim Jezus: Razvežite ga in pustite, naj odide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 45, 'Tedaj jih je veliko izmed Judov, ki so bili prišli k Mariji in so videli, kaj je Jezus storil, sprejelo vero vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 46, 'A nekateri izmed njih odidejo k farizejem in jim povedo, kaj je storil Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 47, 'Višji duhovniki in farizeji torej skličejo veliki zbor in reko: Kaj čemo storiti? kajti ta človek dela veliko čudežev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 48, 'Če ga tako pustimo, bodo vsi verovali vanj; in pridejo Rimljani in nam vzemo i zemljo i narod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 49, 'A eden izmed njih, Kajfa, ki je bil tisto leto veliki duhovnik, jim reče: Vi ničesar ne veste,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 50, 'in tudi ne premišljate, da je bolje za vas, če eden človek umre za ljudstvo, nego da bi ves narod poginil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 51, 'Tega pa ni rekel sam od sebe, temuč, ker je bil tisto leto veliki duhovnik, je prorokoval, da ima Jezus umreti za narod;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 52, 'in ne samo za ta narod, ampak da tudi razkropljene otroke Božje zbere v eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 53, 'Od tega dne torej se posvetujejo, kako naj ga umore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 54, 'Jezus pa ni hodil več očitno med Judi, temuč se je umaknil odtod v kraj blizu puščave, k mestu, ki se imenuje Efraim; in tu je prebival z učenci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 55, 'Bila je pa blizu Velika noč Judov; in veliko jih gre iz dežele gori v Jeruzalem pred Veliko nočjo, da se očistijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 56, 'Iščejo tedaj Jezusa in se pogovarjajo med seboj, stoječ v templju: Kaj se vam zdi? Gotovo ne pride na praznik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 11, 57, 'Izdali pa so višji duhovniki in farizeji zapoved, če kdo zve, kje je, naj to naznani, da bi ga zgrabili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 1, 'Šest dni pred Veliko nočjo pa Pride Jezus v Betanijo, kjer je bil Lazar, ki je bil umrl in ga je Jezus obudil iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 2, 'In napravijo mu tu večerjo; in Marta je stregla, Lazar pa je bil eden med temi, ki so ž njim sedeli za mizo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 3, 'Marija pa vzame libro nardovega mazila, pravega in dragocenega, in pomazili noge Jezusove in mu jih otre z lasmi svojimi; in hiša se napolni z duhom mazila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 4, 'Toda Juda Simonov Iškariot, eden učencev njegovih, ki ga je imel izdati, reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 5, 'Zakaj se ni prodalo to mazilo za tristo denarjev in dalo ubogim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 6, 'To pa je rekel, ne ker ga je bila skrb za uboge, ampak ker je bil tat in je imel mošnjo in nosil, kar so metali vanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 7, 'Jezus pa reče: Pusti jo; za dan pogreba mojega je to prihranila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 8, 'Kajti uboge imate vsekdar pri sebi, a mene nimate vsekdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 9, 'Zvedelo je pa preprosto ljudstvo izmed Judov, da je tukaj, ter pridejo ne samo zaradi Jezusa, ampak da bi tudi videli Lazarja, ki ga je bil obudil iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 10, 'Višji duhovniki pa se posvetujejo, da bi tudi Lazarja umorili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 11, 'ker so mnogi izmed Judov hodili tja zavoljo njega in so sprejemali vero v Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 12, 'Drugi dan zasliši velika množica, ki je bila prišla na praznik, da gre Jezus v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 13, 'In vzemo palmove veje in mu pridejo naproti in vpijejo: Hosana! Blagoslovljen, ki prihaja v imenu Gospodovem, kralj Izraelov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 14, 'In Jezus dobi osliča in sede nanj, kakor je pisano:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 15, '„Ne boj se, hči sionska! glej, kralj tvoj gre, sedeč na žrebetu osličjem.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 16, 'Tega učenci njegovi izprva niso razumeli, ampak ko je bil Jezus oslavljen, tedaj so se spomnili, da je bilo to pisano za njega in da so mu to storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 17, 'Ljudstvo torej, ki je bilo ž njim, ko je Lazarja poklical iz groba in ga obudil iz mrtvih, je pričevalo o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 18, 'Zato mu je tudi množica prišla naproti, ker so slišali, da je storil ta čudež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 19, 'Farizeji reko tedaj med seboj: Vidite, da nič ne opravite! Glej, ves svet leti za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 20, 'Bili so pa nekateri Grki med tistimi, ki so prihajali, da bi molili o prazniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 21, 'Ti torej pristopijo k Filipu, ki je bil iz Betsaide Galilejske, in ga zaprosijo, rekoč: Gospod, Jezusa bi radi videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 22, 'Filip gre in pove to Andreju, in Andrej in Filip povesta Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 23, 'Jezus pa jima odgovori, rekoč: Prišla je ura, da bi bil oslavljen Sin človekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 24, 'Resnično, resnično vam pravim: Pšenično zrno, če pade v zemljo in ne umre, ostane samo; če pa umre, obrodi veliko sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 25, 'Kdor ljubi dušo svojo, jo izgubi; a kdor sovraži dušo svojo na tem svetu, jo ohrani za večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 26, 'Ako mi hoče kdo služiti, naj gre za menoj; in kjer sem jaz, tam bo tudi služabnik moj; in če kdo meni služi, njega počasti Oče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 27, 'Sedaj je duša moja žalostna, in kaj hočem reči? Oče, reši me iz te ure! Toda prav zato sem prišel v to uro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 28, 'Oče, oslavi ime svoje! Tedaj se oglasi glas z neba: Oslavil sem ga, in zopet ga oslavim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 29, 'Ljudstvo torej, ki je zraven stalo in je to slišalo, pravi, da je zagrmelo. Drugi pravijo: Angel mu je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 30, 'Jezus odgovori in reče: Ne zaradi mene je prišel ta glas, ampak zavoljo vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 31, 'Zdaj je sodba tega sveta; zdaj bo vojvoda tega sveta vržen ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 32, 'In jaz, kadar bom povišan od zemlje, vse potegnem k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 33, 'To je pa pravil, da naznači, s kakšno smrtjo mu je umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 34, 'Ljudstvo mu torej odgovori: Mi smo slišali iz zakona, da Kristus ostane vekomaj, in kako praviš ti, da mora biti povišan Sin človekov? Kdo je ta Sin človekov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 35, 'Jezus jim torej reče: Še malo časa je luč med vami. Hodite, dokler imate luč, da vas ne objame tema; in kdor po temi hodi, ne ve, kam gre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 36, 'Dokler imate luč, verujte v luč, da postanete sinovi luči. To je Jezus povedal, in je odšel in se skril pred njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 37, 'In dasi je toliko čudežev storil vpričo njih, niso verovali vanj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 38, 'da se izpolni beseda Izaija proroka, ki jo je rekel: „Gospod, kdo je veroval našemu poročilu? in rama Gospodova komu se je razodela?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 39, 'Verovati pa zato niso mogli, ker je zopet rekel Izaija:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 40, '„Oslepil jim je oči in zakrknil jim je srce, da ne bi z očmi videli in s srcem umeli in se izpreobrnili, in jaz bi jih ozdravil.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 41, 'To je rekel Izaija, ko je videl slavo njegovo in je govoril o njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 42, 'Vendar so pa tudi mnogi izmed prvakov verovali vanj, toda zaradi farizejev niso priznavali, da ne bi bili izobčeni iz shodnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 43, 'Kajti ljubili so slavo pri ljudeh bolj nego slavo pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 44, 'Jezus pa zakliče in reče: Kdor veruje v mene, veruje ne v mene, marveč v tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 45, 'In kdor vidi mene, vidi tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 46, 'Jaz Luč sem prišel na svet, da ne ostane v temi nihče, kdor veruje v mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 47, 'In če kdo sliši moje besede in jih ne hrani, jaz ga ne sodim; zakaj nisem prišel, da bi svet sodil, ampak da zveličam svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 48, 'Kdor zaničuje mene in ne sprejema besed mojih, ima svojega sodnika: beseda, ki sem jo govoril, ona ga bo sodila v poslednji dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 49, 'Kajti jaz nisem sam od sebe govoril, temuč Oče, ki me je poslal, on mi je dal zapoved, kaj naj povem in kaj naj govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 12, 50, 'In vem, da je njegova zapoved večno življenje. Kar torej jaz govorim, govorim tako, kakor mi je Oče rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 1, 'Pred praznikom velikonočnim pa, ko je Jezus vedel, da je prišla njegova ura, da prejde s tega sveta k Očetu: ker je ljubil svoje, ki so bili na svetu, jih je ljubil do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 2, 'In pri večerji, ko je že bil hudič Judu Simonovemu Iškariotu dal v srce, naj ga izda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 3, 'vstane Jezus, vedoč, da mu je dal Oče vse v roke, in da je od Boga izšel in k Bogu gre,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 4, 'od večerje in sleče oblačilo in vzame prt ter se opaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 5, 'Potem vlije vode v medenico in začne umivati učencem noge in otirati s prtom, ki je bil ž njim opasan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 6, 'Pride torej k Simonu Petru. On mu reče: Gospod, ti mi boš umival noge?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 7, 'Jezus odgovori in mu reče: Kar jaz delam, ti sedaj ne veš, ali zvedel boš potem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 8, 'Reče mu Peter: Ne boš mi umival nog, na vekomaj ne! Odgovori mu Jezus: Če te ne umijem, nimaš deleža z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 9, 'Reče mu Simon Peter: Gospod, ne samo nog mojih, ampak tudi roke in glavo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 10, 'Reče mu Jezus: Kdor je bil v kopeli umit, ne potrebuje, samo da si noge umije, sicer je ves čist; in vi ste čisti, ali ne vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 11, 'Poznal je namreč izdajalca svojega; zato je rekel: Niste vsi čisti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 12, 'Ko jim je torej umil noge in je vzel oblačilo svoje, sede zopet za mizo in jim reče: Veste li, kaj sem vam storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 13, 'Vi me zovete: Učenik in Gospod, in prav pravite; kajti to tudi sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 14, 'Če sem torej jaz, Gospod in Učenik, vam umil noge, ste dolžni tudi vi drug drugemu umivati noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 15, 'Zgled sem vam dal namreč, da tudi vi delajte tako, kakor sem vam jaz storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 16, 'Resnično, resnično vam pravim: Hlapec ni večji od gospodarja svojega, tudi poslanec ni večji nego tisti, ki ga je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 17, 'Ako to veste, blagor vam, če to delate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 18, 'Ne govorim o vseh vas; jaz vem, katere sem izvolil. Ali izpolniti se mora pismo: „Ta, ki jé z menoj kruh, je vzdignil peto svojo zoper mene.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 19, 'Že sedaj vam to pravim, preden se je zgodilo, da verujete, kadar se zgodi, da sem jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 20, 'Resnično, resnično vam pravim: Kdor ga sprejme, kogarkoli pošljem, sprejme mene; kdor pa sprejme mene, sprejme tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 21, 'Ko je Jezus to povedal, se razžalosti v duhu, ter zatrdi in reče: Resnično, resnično vam pravim, da me eden izmed vas izda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 22, 'Učenci se tedaj spogledujejo med seboj, pomišljujoč, o katerem pravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 23, 'Slonel je pa za mizo na naročju Jezusovem eden učencev njegovih, ki ga je Jezus ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 24, 'Simon Peter torej namigne temu in mu reče: Povej nam, kdo je, o katerem pravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 25, 'On se nasloni, kakor je, Jezusu na prsi ter mu reče: Gospod, kdo je?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 26, 'Jezus odgovori: Ta je, ki mu grižljaj omočim in podam. Omočivši torej grižljaj, ga vzame in poda Judu Simonovemu Iškariotu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 27, 'In za grižljajem - tedaj vnide vanj satan. Jezus mu torej veli: Kar delaš, stori hitro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 28, 'Tega pa ni razumel nobeden za mizo sedečih, čemu mu je to rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 29, 'Nekateri so namreč mislili, ker je Juda mošnjo imel, da mu Jezus pravi: Nakupi, kar nam je treba za praznik: ali da naj dá kaj ubogim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 30, 'Vzemši torej grižljaj, odide takoj; bila je pa noč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 31, 'Ko je torej odšel, reče Jezus: Sedaj je Sin človekov oslavljen, in Bog je oslavljen v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 32, 'Če je Bog oslavljen v njem, ga tudi Bog oslavi v sebi, in precej ga oslavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 33, 'Otročiči, še malo časa sem z vami. Iskali me boste, a kakor sem Judom povedal: kamor jaz grem, vi ne morete priti, tako pravim sedaj tudi vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 34, 'Novo zapoved vam dajem, da se ljubite med seboj; kakor sem jaz vas ljubil, da se tudi vi ljubite med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 35, 'V tem spoznajo vsi, da ste moji učenci, ako imate ljubezen drug do drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 36, 'Reče mu Simon Peter: Gospod, kam greš? Jezus odgovori: Kamor grem, ne moreš zdaj iti za menoj; pozneje pa pojdeš za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 37, 'Reče mu Peter: Gospod, zakaj ne morem sedaj iti za teboj? Življenje svoje dam zate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 13, 38, 'Jezus odgovori: Življenje svoje daš zame? Resnično, resnično ti pravim: Petelin ne zapoje, dokler me trikrat ne zatajiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 1, 'Ne bodi vam srce plašno. Verujte v Boga, tudi v mene verujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 2, 'V hiši Očeta mojega je veliko prebivališč. Če bi ne bilo, bi vam bil povedal; kajti grem pripravljat vam prostora!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 3, 'In ko odidem in vam pripravim prostor, pridem zopet in vas vzamem k sebi, da boste tudi vi tam, kjer sem jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 4, 'In kam jaz grem, veste, tudi pot veste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 5, 'Reče mu Tomaž: Gospod, ne vemo, kam greš, in kako moremo vedeti pot?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 6, 'Veli mu Jezus: Jaz sem pot in resnica in življenje; nihče ne pride k Očetu razen po meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 7, 'Ko bi bili mene spoznali, bi poznali tudi Očeta mojega. In odsihdob ga poznate, in videli ste ga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 8, 'Reče mu Filip: Gospod, pokaži nam Očeta, in dosti je nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 9, 'Jezus mu dé: Toliko časa sem z vami, in nisi me spoznal, Filip? Kdor je mene videl, je videl Očeta; in kako ti praviš: Pokaži nam Očeta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 10, 'Ne veruješ li, da sem jaz v Očetu in Oče v meni? Besed, ki jih vam jaz pravim, ne govorim sam od sebe, ampak Oče, ki v meni prebiva, on vrši dela svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 11, 'Verujte mi, da sem jaz v Očetu in Oče v meni; če pa ne, verujte mi vsaj zavoljo teh del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 12, 'Resnično, resnično vam pravim: Kdor veruje v mene, bo tudi on vršil dela, ki jih jaz delam, in bo vršil še večja od teh: kajti jaz grem k Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 13, 'In karkoli boste prosili v mojem imenu, to bom storil, da bo oslavljen Oče v Sinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 14, 'Če boste kaj prosili v mojem imenu, jaz bom storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 15, 'Ako me ljubite, boste izpolnjevali zapovedi moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 16, 'In jaz bom prosil Očeta, in drugega Tolažnika vam dá, da ostane z vami vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 17, 'Duha resnice, ki ga svet ne more prejeti, ker ga ne vidi in ga tudi ne pozna; vi ga pa poznate, ker pri vas prebiva, in bode v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 18, 'Ne pustim vas sirot, pridem k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 19, 'Še malo, in svet me več ne bo videl, a vi me boste videli: ker jaz živim, boste tudi vi živeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 20, 'Tisti dan spoznate, da sem jaz v Očetu svojem, in vi v meni, in jaz v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 21, 'Kdor ima zapovedi moje in jih izpolnjuje, on je ta, ki me ljubi; kdor pa mene ljubi, ga bo ljubil Oče moj, in jaz ga bom ljubil in mu razodenem sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 22, 'Reče mu Juda (ne Iškariot): Gospod, kaj se je zgodilo, da hočeš sebe razodeti nam in ne svetu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 23, 'Jezus odgovori in mu reče: Če me kdo ljubi, bo izpolnjeval besedo mojo, in Oče moj ga bo ljubil, in k njemu pridemo in prebivališče si napravimo pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 24, 'Kdor me ne ljubi, mojih besed ne izpolnjuje; in beseda, ki jo slišite, ni moja, marveč Očeta, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 25, 'To sem vam govoril, dokler sem z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 26, 'Tolažnik pa, sveti Duh, ki ga pošlje Oče v imenu mojem, on vas bo vse učil in vas spominjal vsega, kar sem vam povedal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 27, 'Mir vam zapuščam, mir svoj vam dajem; ne dajem vam jaz, kakor daje svet. Ne bodi vam srce plašno in boječe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 28, 'Slišali ste, da sem vam jaz rekel: Grem, a zopet pridem k vam. Ko bi me ljubili, bi se veselili, da grem k Očetu; kajti Oče je večji od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 29, 'In sedaj sem vam povedal, preden se zgodi, da boste verovali, kadar se zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 30, 'Ne bom veliko več govoril z vami: prihaja namreč vojvoda tega sveta, a na meni nima ničesar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 14, 31, 'ampak da svet spozna, da ljubim Očeta, in kakor mi je Oče zapovedal, tako delam. Vstanite, pojdite odtod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 1, 'Jaz sem prava trta, in Oče moj je vinogradnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 2, 'Vsako mladiko na meni, ki ne rodi sadu, odreže; in vsako, ki rodi sad, očiščuje, da bo rodila več sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 3, 'Vi ste že čisti zavoljo besede, ki sem vam jo govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 4, 'Ostanite v meni, in jaz v vas. Kakor mladika sama od sebe ne more roditi sadu, če ne ostane na trti: tako tudi vi ne, če ne ostanete v meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 5, 'Jaz sem trta, vi mladike. Kdor ostaja v meni in jaz v njem, ta rodi veliko sadu: zakaj brez mene ne morete ničesar storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 6, 'Ako kdo ne ostane v meni, bo vržen ven kakor mladika in se posuši: in zbero jih in vržejo na ogenj, in goré.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 7, 'Če ostanete v meni in besede moje ostanejo v vas: prosite, karkoli hočete, in se vam zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 8, 'S tem se bo oslavil Oče moj, da obrodite veliko sadu, in tako bodete moji učenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 9, 'Kakor je Oče mene ljubil, sem tudi jaz ljubil vas: ostanite v tej moji ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 10, 'Če boste izpolnjevali zapovedi moje, ostanete v ljubezni moji; kakor sem jaz izpolnil zapovedi Očeta svojega in ostajam v ljubezni njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 11, 'To sem vam povedal, da moja radost ostane v vas in da se vaša radost dopolni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 12, 'Moja zapoved je ta, da se ljubite med seboj, kakor sem vas jaz ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 13, 'Večje ljubezni od te nima nihče, da kdo dá življenje svoje za prijatelje svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 14, 'Vi ste prijatelji moji, ako delate, kar vam ukazujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 15, 'Ne imenujem vas več hlapcev, ker hlapec ne ve, kaj dela gospodar njegov; toda vas sem imenoval prijatelje, ker sem vam oznanil vse, kar sem slišal od Očeta svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 16, 'Niste izvolili vi mene, temuč jaz sem izvolil vas, in postavil sem vas, da greste in obrodite sad in da sad vaš ostane: da vam dá Oče, karkoli ga boste prosili v mojem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 17, 'To vam zapovedujem, da se ljubite med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 18, 'Če vas svet sovraži, vedite, da je mene prej sovražil nego vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 19, 'Ko bi bili od sveta, svet bi svoje ljubil; ker pa niste od sveta, temuč sem vas jaz odbral iz sveta, zato vas svet sovraži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 20, 'Spominjajte se besede, ki sem jo vam jaz rekel: Hlapec ni večji od gospodarja svojega. Če so mene preganjali, bodo preganjali tudi vas; če so mojo besedo ohranili, ohranijo tudi vašo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 21, 'Ali to vse vam bodo delali zavoljo imena mojega, ker ne poznajo tega, ki me je poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 22, 'Ko ne bi bil prišel in jim ne bi bil govoril, ne bi imeli greha; sedaj pa nimajo izgovora za greh svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 23, 'Kdor mene sovraži, sovraži tudi Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 24, 'Ko ne bi bil storil med njimi del, ki jih nihče drugi ni storil, ne bi imeli greha; sedaj so pa videli in sovražili mene in tudi Očeta mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 25, 'Ali to se godi, da se izpolni beseda, ki je pisana v njih postavi: „Sovražili so me brez vzroka“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 26, 'Kadar pa pride Tolažnik, ki ga vam pošljem od Očeta, Duh resnice, ki izhaja od Očeta, on bo pričeval zame;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 15, 27, 'pa tudi vi pričujete, ker ste od začetka z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 1, 'To sem vam povedal, da se ne pohujšate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 2, 'Izobčijo vas iz shodnic; pride celo ura, da bo vsak, kdor vas bo moril, menil, da s tem opravlja službo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 3, 'In to vam bodo delali, ker niso spoznali Očeta, ne mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 4, 'Ali to sem vam povedal, da bi se, kadar ta ura pride, spomnili tega, da sem vam jaz to rekel. Tega pa vam od začetka nisem povedal, ker sem še bil z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 5, 'A sedaj grem k temu, ki me je poslal, in nobeden izmed vas me ne vpraša: Kam greš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 6, 'Temuč ker sem vam to povedal, je vam žalost napolnila srce.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 7, 'Ali jaz vam pravim resnico: Bolje vam je, da jaz odidem. Zakaj, če ne odidem, ne pride Tolažnik k vam; če pa odidem, ga pošljem k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 8, 'In ko on pride, bo prepričeval svet o grehu in pravičnosti in sodbi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 9, 'o grehu namreč, ker ne verujejo v mene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 10, 'o pravičnosti pa, ker grem k Očetu, in me ne boste več videli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 11, 'o sodbi pa, ker je vojvoda tega sveta obsojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 12, 'Še veliko vam imam povedati, sedaj pa ne morete tega nositi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 13, 'Kadar pa on pride, Duh resnice, vas bo vodil v vso resnico; ne bo namreč govoril sam od sebe, temuč kar bo slišal, bo govoril, in oznanjeval vam bo prihodnje reči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 14, 'On bo mene oslavil, ker od mojega vzame in vam oznani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 15, 'Vse, karkoli ima Oče, je moje; zato sem rekel, da vzame od mojega in vam oznani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 16, 'Malo, in ne boste me več videli, in zopet malo, in boste me videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 17, 'Tedaj reko nekateri učencev njegovih med seboj: Kaj je to, kar nam pravi: Malo, in ne boste me videli, in zopet malo, in boste me videli, in: Grem k Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 18, 'Govore torej: Kaj je to, kar pravi: malo? Ne vemo, kaj pravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 19, 'Jezus pa spozna, da ga hočejo vprašati, in jim reče: Ali se zato poprašujete med seboj, da sem rekel: Malo, in ne boste me videli, in zopet malo, in boste me videli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 20, 'Resnično, resnično vam pravim, da boste jokali vi in plakali, a svet se bo radoval; vi pa bodete žalostni, ali žalost vaša se premeni v radost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 21, 'Žena, kadar rodi, ima žalost, ker je prišla njena ura; toda ko porodi dete, se ne spominja več bridkosti od veselja, da se je rodil človek na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 22, 'Tako tudi vas sedaj objemlje žalost; pa zopet vas bom videl, in srce vaše se bo radovalo, in radosti vaše vam ne odvzame nihče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 23, 'In tisti dan me ne boste ničesar vpraševali. Resnično, resnično vam pravim: Karkoli boste Očeta prosili, dá vam v imenu mojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 24, 'Doslej niste ničesar prosili v imenu mojem. Prosíte in prejmete, da bo radost vaša dopolnjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 25, 'To sem vam povedal v prilikah; ali pride ura, ko vam ne bom več govoril v prilikah, temuč vam bom odkrito oznanjeval o Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 26, 'Tisti dan boste v imenu mojem prosili; in ne pravim vam, da bom jaz prosil Očeta za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 27, 'Zakaj Oče sam vas ljubi, ker ste vi mene ljubili in ste verovali, da sem jaz izšel od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 28, 'Izšel sem od Očeta in prišel sem na svet; zopet zapuščam svet in grem k Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 29, 'Reko mu učenci njegovi: Glej, sedaj odkrito govoriš in ne praviš nobene prilike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 30, 'Sedaj vemo, da veš vse in ti ni treba, da bi te kdo vpraševal. Po tem verujemo, da si od Boga izšel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 31, 'Odgovori jim Jezus: Ali sedaj verujete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 32, 'Glej, pride ura, in že je prišla, da se razkropite vsak na svojo stran in mene pustite samega; a nisem sam, ker je Oče z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 16, 33, 'To sem vam povedal, da imate mir v meni. Na svetu imate bridkost; ali srčni bodite, jaz sem svet premagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 1, 'To je povedal Jezus ter povzdigne oči k nebu in reče: Oče, ura je prišla; oslavi Sina svojega, da tudi Sin tvoj tebe oslavi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 2, 'kakor si mu dal oblast nad vsem človeštvom, da dá večno življenje vsem, ki si mu jih dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 3, 'Večno življenje je pa to, da spoznajo tebe, edinega resničnega Boga, in katerega si poslal, Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 4, 'Jaz sem te oslavil na zemlji; delo sem dokončal, ki si mi ga dal, da ga storim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 5, 'in zdaj oslavi ti, Oče, mene sam pri sebi s slavo, ki sem jo imel pri tebi, preden je bil svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 6, 'Razodel sem ime tvoje ljudem, katere si mi dal od sveta. Tvoji so bili, in meni si jih dal, in besedo tvojo so ohranili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 7, 'Sedaj vedo, da je vse, karkoli si mi dal, od tebe:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 8, 'kajti besede, ki si jih meni dal, sem dal njim; in oni so jih sprejeli in spoznali resnično, da sem od tebe izšel, in so verovali, da si me ti poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 9, 'Jaz prosim zanje; ne prosim za svet, ampak za te, ki si mi jih dal, ker so tvoji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 10, 'in vse moje je tvoje, in tvoje je moje; in oslavljen sem v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 11, 'In nisem več na svetu, a ti so na svetu; jaz pa grem k tebi. Oče sveti! ohrani jih v imenu svojem, katere si mi dal, da bodo eno, kakor mi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 12, 'Dokler sem bil ž njimi, sem jih varoval v imenu tvojem; katere si mi dal, sem ohranil, in nobeden izmed njih ni poginil, razen sin pogube, da se izpolni pismo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 13, 'Sedaj pa grem k tebi, in to govorim na svetu, da imajo radost mojo dopolnjeno v sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 14, 'Jaz sem jim dal besedo tvojo, in svet jih je sovražil, ker niso od sveta, kakor jaz nisem od sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 15, 'Ne prosim, da jih vzemi s sveta, ampak da jih obvaruj zlega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 16, 'Od sveta niso, kakor jaz nisem od sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 17, 'Posveti jih v resnici: tvoja beseda je resnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 18, 'Kakor si mene poslal na svet, sem poslal tudi jaz nje na svet;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 19, 'in zanje sam sebe posvečujem, da bodo tudi oni posvečeni v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 20, 'Ne prosim pa samo za te, ampak tudi za tiste, ki bodo po njih besedi verovali v mene:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 21, 'da bodo vsi eno; kakor ti, Oče, v meni in jaz v tebi, da bodo tudi oni v nas eno, da bi svet veroval, da si me ti poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 22, 'In jaz sem slavo, ki si jo meni dal, dal njim, da bodo eno, kakor smo mi eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 23, 'Jaz v njih in ti v meni, da bodo popolnoma združeni v eno, in da spozna svet, da si me ti poslal in si jih ljubil, kakor si mene ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 24, 'Oče, katere si mi dal, hočem, kjer sem jaz, da bodo tudi oni z menoj, da vidijo mojo slavo, ki si mi jo dal, ker si me ljubil pred začetkom sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 25, 'Oče pravični! svet tebe ni spoznal, a jaz sem te spoznal, in ti so spoznali, da si me ti poslal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 17, 26, 'in oznanil sem jim ime tvoje, in oznanjeval ga bom: da bode ljubezen, s katero si me ljubil, v njih in jaz v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 1, 'Rekši to, gre Jezus z učenci svojimi iz mesta čez potok Cedron, kjer je bil vrt, in nanj krenejo on in učenci njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 2, 'Vedel je pa tudi Juda, njegov izdajalec, o tem kraju, ker je pogostoma Jezus tja zahajal z učenci svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 3, 'Juda torej vzame trumo in služabnike od višjih duhovnikov in farizejev in pride tja s svetilnicami in baklami in orožjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 4, 'Jezus pa, ker je vedel vse, kaj nad njega pride, jim gre naproti in reče: Koga iščete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 5, 'Odgovore mu: Jezusa Nazarečana. Jezus jim reče: Jaz sem. Stal je pa ž njimi tudi Juda, izdajalec njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 6, 'Ko jim je torej rekel: Jaz sem, stopijo nazaj in padejo na tla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 7, 'Vpraša jih torej zopet: Koga iščete? Oni pa reko: Jezusa Nazarečana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 8, 'Jezus odgovori: Rekel sem vam, da sem jaz. Če torej mene iščete, pustite, da ti odidejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 9, 'Da se izpolni beseda, ki jo je bil rekel: Nobenega nisem izgubil izmed teh, ki si mi jih dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 10, 'A Simon Peter je imel meč; izdere ga torej in udari hlapca velikega duhovnika in mu odseka desno uho. Hlapcu pa je bilo ime Malh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 11, 'Jezus pa reče Petru: Vtakni meč svoj v nožnico. Ali naj ne pijem keliha, ki mi ga je dal Oče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 12, 'Tedaj zgrabijo vojaki in tisočnik in služabniki Judov Jezusa in ga zvežejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 13, 'in peljejo ga najprej k Anu; bil je namreč tast Kajfov, ki je bil tisto leto veliki duhovnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 14, 'Bil je pa Kajfa tisti, ki je bil Judom nasvetoval, da je bolje, da umre eden človek za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 15, 'Za Jezusom pa je šel Simon Peter in neki drugi učenec. Ta učenec pa je bil znan z velikim duhovnikom, ter vnide z Jezusom na dvorišče velikega duhovnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 16, 'Peter pa je stal zunaj pri vratih. Tedaj gre ven drugi učenec, znanec velikega duhovnika, in se pomeni z vratarico in pripelje Petra noter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 17, 'Dekla vratarica reče torej Petru. Ali nisi tudi ti izmed učencev tega človeka? On pa reče: Nisem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 18, 'A hlapci in služabniki so bili zanetili ogenj, ker je bilo mraz, ter so se okoli stojé greli; stal je pa tudi Peter med njimi in se grel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 19, 'Veliki duhovnik torej vpraša Jezusa za učence njegove in za nauk njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 20, 'Jezus mu odgovori: Jaz sem očitno govoril svetu; jaz sem vsekdar učil v shodnici in templju, kjer se vsi Judje shajajo, in skrivaj nisem ničesar govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 21, 'Kaj vprašuješ mene? Vprašaj tiste, ki so me slišali, kaj sem jim govoril; glej, oni vedo, kaj sem pravil jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 22, 'Ko je pa to rekel, udari eden služabnikov, ki je stal poleg, Jezusa po licu in reče: Tako odgovarjaš velikemu duhovniku?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 23, 'Jezus mu odgovori: Če sem hudo govoril, izpričaj, da je hudo; če pa dobro, zakaj me biješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 24, 'Ana ga torej pošlje zvezanega k velikemu duhovniku Kajfu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 25, 'Simon Peter pa stoji pri ognju in se greje. Reko mu torej: Ali nisi tudi ti izmed učencev njegovih? On zataji in reče: Nisem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 26, 'Eden izmed hlapcev velikega duhovnika, sorodnik tistega, ki mu je bil Peter odsekal uho, reče: Te li nisem jaz videl ž njim na vrtu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 27, 'Peter pa zopet utaji, in precej zapoje petelin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 28, 'A Jezusa peljejo od Kajfa v sodno palačo. Bilo je pa zjutraj. In oni nočejo stopiti v sodno palačo, da se ne bi oskrunili, temuč da bi jedli velikonočno jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 29, 'Pilat torej pride ven k njim in reče: Kakšno tožbo imate zoper tega človeka?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 30, 'Odgovore in reko: Če ta ne bi bil hudodelnik, ne bi ga bili tebi izročili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 31, 'Reče jim torej Pilat: Vzemite ga vi, in sodite ga po svoji postavi. Judje pa mu reko: Mi ne smemo nikogar umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 32, 'Da se izpolni Jezusova beseda, ki jo je rekel, ko je naznačil, s kakšno smrtjo mu bode umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 33, 'Pilat torej gre zopet v sodno palačo, in pokliče Jezusa in mu reče: Si li ti kralj Judov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 34, 'Jezus mu odgovori: Praviš li to sam od sebe ali so ti drugi rekli o meni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 35, 'Pilat odgovori: Sem mar jaz Jud? Tvoj narod in višji duhovniki so te meni izročili, kaj si storil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 36, 'Jezus odgovori: Moje kraljestvo ni od tega sveta; ko bi bilo moje kraljestvo od tega sveta, bi se moji služabniki vojskovali, da ne bi bil Judom izročen; sedaj pa kraljestvo moje ni odtod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 37, 'Tedaj mu reče Pilat: Torej kralj si ti? Jezus odgovori: Ti praviš, da sem jaz kralj. Jaz sem zato rojen, in zato sem prišel na svet, da pričam za resnico. Vsak, kdor je od resnice, posluša glas moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 38, 'Pilat mu reče: Kaj je resnica? In ko je to rekel, izide zopet k Judom in jim reče: Jaz ne vidim nobene krivice na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 39, 'Je pa navada pri vas, da vam enega izpustim na Veliko noč; hočete li torej, da vam izpustim kralja Judov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 18, 40, 'Nato zavpijejo vsi, rekoč: Ne tega, ampak Baraba. Bil je pa Baraba razbojnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 1, 'Tedaj vzame Pilat Jezusa in ga da bičati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 2, 'In vojaki spleto krono iz trnja in mu jo denejo na glavo, in mu oblečejo škrlaten plašč;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 3, 'in pristopajo k njemu in govore: Zdrav, kralj Judov! in ga bijejo po licu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 4, 'Pilat pa zopet gre ven in jim reče: Glej, pripeljem vam ga ven, da spoznate, da ne vidim na njem nobene krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 5, 'Pride torej Jezus ven, noseč trnjevo krono in škrlatni plašč. In Pilat jim reče: Glejte, človek!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 6, 'Ko ga pa ugledajo višji duhovniki in služabniki, zavpijejo, rekoč: Križaj, križaj ga! Veli jim Pilat: Vzemite ga vi in križajte; kajti jaz ne vidim nobene krivice na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 7, 'Odgovore mu Judje: Mi imamo postavo, in po tej postavi mora umreti, ker je sebe Sina Božjega delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 8, 'Ko pa zasliši Pilat to besedo, se zboji še bolj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 9, 'In gre zopet v sodno palačo in reče Jezusu: Odkod si ti? Jezus pa mu ne odgovori besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 10, 'Reče mu torej Pilat: Meni ne odgovoriš? Ne veš li, da imam oblast te oprostiti in da imam oblast te križati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 11, 'Jezus mu odgovori: Ne bi imel nobene oblasti nad menoj, da ti ni dano od zgoraj; zato ima tisti, ki me je tebi izročil, večji greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 12, 'Vsled tega si Pilat še prizadeva, da bi ga izpustil. A Judje kriče, rekoč: Če tega izpustiš, nisi prijatelj cesarju, zakaj vsak, kdor se dela kralja, nasprotuje cesarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 13, 'Ko torej Pilat zasliši te besede, pripelje ven Jezusa in sede na sodni stol na mestu, ki se imenuje Kameniti tlak, hebrejski pa Gabata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 14, 'Bil je pa dan pripravljanja za Veliko noč, okoli šeste ure. In reče Judom: Glej, kralj vaš!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 15, 'Oni pa zavpijejo: Proč ž njim, proč, križaj ga! Reče jim Pilat: Kralja vašega bom križal? Višji duhovniki odgovore: Nimamo kralja, samo cesarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 16, 'Tedaj jim ga izroči, naj ga križajo. Vzemo torej Jezusa in ga odpeljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 17, 'In nesoč sam križ svoj, gre ven na mesto, imenovano Mrtvaška glava, ki po hebrejski slove Golgota.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 18, 'Tu ga razpno na križ in ž njim dva druga, na vsaki strani enega, v sredi pa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 19, 'Napiše pa Pilat tudi napis in ga dene na križ; bilo je pa pisano: JEZUS NAZAREČAN, KRALJ JUDOV.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 20, 'Ta napis je torej bralo mnogo Judov, ker je bil kraj, kjer so Jezusa razpeli, blizu mesta; in bilo je pisano hebrejski, grški, latinski.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 21, 'Reko torej višji duhovniki Judov Pilatu: Ne piši ‚Kralj Judov‘, ampak da je sam rekel ‚Kralj Judov sem‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 22, 'Pilat odgovori: Kar sem pisal, sem pisal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 23, 'Vojaki pa, ko so bili Jezusa razpeli, vzemo obleko njegovo in napravijo štiri dele, vsakemu vojaku del, in tudi suknjo; suknja pa ni bila šivana, nego od vrha sceloma stkana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 24, 'Zato reko med seboj: Trgali je ne bomo, ampak srečkajmo, čigava bo. Da se izpolni pismo, ki pravi: „Razdelili so obleko mojo med seboj in za suknjo mojo so vrgli kocko“. Vojaki so torej tako storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 25, 'Stale so pa pri križu Jezusovem mati njegova in sestra matere njegove, Marija Klopova, in Marija Magdalena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 26, 'Ko torej ugleda Jezus mater in učenca, katerega je ljubil, da tu stoji, reče materi svoji: Žena, glej, sin tvoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 27, 'Potem reče učencu: Glej, mati tvoja! In od tega časa jo je vzel učenec k sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 28, 'Potem reče Jezus, vedoč, da je že vse dopolnjeno, da se izpolni pismo: Žejen sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 29, 'Stala je tam posoda, polna octa: oni torej nataknejo na izop gobo, namočeno z octom, ter mu jo podado k ustom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 30, 'Ko pa Jezus ocet okusi, reče: Dopolnjeno je! in nakloni glavo in izroči duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 31, 'Da pa ne ostanejo trupla v soboto na križu, ker je bil dan pripravljanja (bil je namreč ta sobotni dan velik), zaprosijo Judje Pilata, naj jim goleni prebijejo in jih snamejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 32, 'Vojaki torej pridejo in prebijejo prvemu goleni in drugemu, ki je bil ž njim križan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 33, 'Ko pa pridejo do Jezusa in vidijo, da je že umrl, mu ne prelomijo goleni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 34, 'temuč eden od vojakov mu prebode s sulico stran, in precej priteče kri in voda iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 35, 'In ta, ki je videl, je izpričal, in pričevanje njegovo je resnično, in on ve, da govori resnico, da bi tudi vi verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 36, 'Kajti to se je zgodilo, da se izpolni pismo: „Nobene kosti mu ne bodo prelomili.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 37, 'In zopet drugo pismo pravi: „Gledali ga bodo, ki so ga prebodli.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 38, 'Potem pa zaprosi Pilata Jožef iz Arimateje, ki je bil učenec Jezusov, toda skrivaj iz strahu pred Judi, da bi snel truplo Jezusovo; in Pilat dovoli. Pride torej in sname truplo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 39, 'Pride pa tudi Nikodem, ki je bil prvič prišel k Jezusu po noči, in prinese zmesi mire in aloe kakih sto liber.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 40, 'Vzameta torej truplo Jezusovo in ga zavijeta v prte z dišavami vred, kakor imajo Judje navado pokopavati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 41, 'Bil je pa vrt v kraju, kjer je bil križan, in na vrtu nov grob, v katerega še nikoli nihče ni bil položen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 19, 42, 'Tu torej, zavoljo judovskega dneva pripravljanja, ker je bil grob blizu, položita Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 1, 'A prvi dan tedna pride Marija Magdalena zgodaj, ko je še tema bilo, h grobu; in ugleda, da je kamen odvaljen od groba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 2, 'Tedaj zbeži in pride k Simonu Petru in k drugemu učencu, ki ga je Jezus ljubil, in jima reče: Vzeli so Gospoda iz groba, in ne vemo, kam so ga položili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 3, 'Peter torej gre ven in drugi učenec, in šla sta h grobu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 4, 'Tečeta pa oba skupaj; a drugi učenec teče hitreje nego Peter in pride prvi h grobu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 5, 'in sklonivši se, ugleda platnene povoje, da leže; toda ne vstopi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 6, 'Tedaj pride tudi Simon Peter za njim, stopi v grob in vidi povoje, da leže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 7, 'in potni prt, ki je bil na glavi njegovi, da ne leži z drugimi prti, temuč je posebe zvit na enem kraju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 8, 'Tedaj stopi noter tudi drugi učenec, ki je bil prvi prišel h grobu, in vidi to in veruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 9, 'Nista še namreč umela pisma, da mora on iz mrtvih vstati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 10, 'In učenca zopet odideta k svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 11, 'Marija pa stoji zunaj pri grobu in joka. Ko pa joka, se skloni v grob');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 12, 'in ugleda dva angela v belih oblačilih, da sedita, eden pri glavi in drugi pri nogah, kjer je bilo ležalo truplo Jezusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 13, 'In ona ji rečeta: Žena, kaj jokaš? Reče jima: Ker so Gospoda mojega vzeli, in ne vem, kam so ga položili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 14, 'To rekši, se obrne in ugleda Jezusa, da tu stoji; pa ne ve, da je Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 15, 'Reče ji Jezus: Žena, kaj jokaš? koga iščeš? Ona, misleč, da je vrtnar, mu reče: Gospod, če si ga ti odnesel, povej mi, kam si ga položil; in jaz ga bom vzela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 16, 'Reče ji Jezus: Marija! Ona se obrne in mu reče hebrejski: Rabuni! (kar se pravi: Učenik).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 17, 'Veli ji Jezus: Ne dotikaj se me, ker še nisem šel gori k Očetu. Pojdi pa k bratom mojim in jim povej: Grem gori k svojemu Očetu in vašemu Očetu in svojemu Bogu in vašemu Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 18, 'Marija Magdalena pride in oznani učencem, da je videla Gospoda in da ji je to rekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 19, 'Ko je pa bil večer tistega dneva, prvega v tednu, in so bile duri zaklenjene, kjer so bili učenci zbrani, zavoljo strahu pred Judi, pride Jezus in stopi v sredo mednje in jim reče: Mir vam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 20, 'In ko je to rekel, jim pokaže roke in svojo stran. Razvesele se tedaj učenci, videč Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 21, 'Jezus jim torej zopet reče: Mir vam! Kakor je Oče mene poslal, tudi jaz pošiljam vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 22, 'In ko je to rekel, dahne vanje, in jim veli: Prejmite svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 23, 'Katerimkoli odpustite grehe, so jim odpuščeni, katerimkoli jih zadržite, so jim zadržani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 24, 'Tomaž pa, eden dvanajsterih, ki se imenuje Dvojček, ni bil ž njimi, ko je Jezus prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 25, 'Pravili so mu torej drugi učenci: Videli smo Gospoda. On jim pa reče: Ako ne vidim na rokah njegovih znamenj od žebljev in ne položim prsta svojega v rano od žebljev in ne denem roke svoje v stran njegovo: ne bom veroval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 26, 'In čez osem dni so zopet učenci njegovi notri, in Tomaž ž njimi. Jezus pride, ko so duri zaklenjene, in stopi v sredo mednje in reče: Mir vam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 27, 'Potem veli Tomažu: Položi prst svoj sem, in poglej roke moje; in podaj roko svojo in položi jo v stran mojo: in ne bodi neveren, ampak veren.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 28, 'Tomaž odgovori in mu reče: Gospod moj in Bog moj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 29, 'Reče mu Jezus: Ker si me videl, Tomaž, veruješ; blagor jim, ki ne vidijo, pa verujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 30, 'In Jezus je storil pred učenci svojimi še veliko drugih znamenj, ki niso zapisana v tej knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 20, 31, 'A ta so zapisana, da verujete: Jezus je Kristus, Sin Božji, in da verujoč imate življenje v imenu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 1, 'Potem se je Jezus zopet razodel učencem pri morju Tiberijskem; razodel se je pa takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 2, 'Bili so skupaj Simon Peter in Tomaž, ki se imenuje Dvojček, in Natanael iz Kane Galilejske in Zebedejeva sina in druga dva izmed učencev njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 3, 'Reče jim Simon Peter: Ribe grem lovit. Reko mu: Tudi mi pojdemo s teboj. Ter gredo in vstopijo v ladjo, in tisto noč niso nič ujeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 4, 'Ko pa že napoči jutro, stoji Jezus na bregu; ali učenci ne vedo, da je Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 5, 'Jezus jim torej reče: Otroci, imate li kake jedi? Odgovore mu: Nimamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 6, 'On jim pa reče: Vrzite mrežo na desno stran ladje, pa najdete. Vržejo torej, a sedaj je ne morejo izvleči zaradi množice rib.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 7, 'Tedaj reče tisti učenec, ki ga je Jezus ljubil, Petru: Gospod je! Simon Peter torej, ko zasliši, da je Gospod, si opaše vrhnjo haljo (bil je namreč nag) in se spusti v morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 8, 'A drugi učenci pridejo z ladjo (niso bili namreč daleč od kopnega, samo kakih dvesto komolcev) in vlečejo mrežo polno rib.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 9, 'Ko pa izstopijo na kopno, ugledajo žerjavico pripravljeno in na njej ribo položeno in kruh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 10, 'Veli jim Jezus: Prinesite od rib, ki ste jih sedaj ujeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 11, 'Simon Peter stopi torej v ladjo in izvleče mrežo na suho, polno velikih rib, sto in triinpetdeset; in dasi jih je bilo toliko, ni se mreža raztrgala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 12, 'Veli jim Jezus: Pridite, obedujte! Nobeden od učencev pa si ga ni upal vprašati: Kdo si ti? vedoč, da je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 13, 'Pride Jezus in vzame kruh in jim ga da, in tako tudi ribo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 14, 'S tem se je že v tretje razodel Jezus učencem, odkar je bil vstal iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 15, 'Ko so torej poobedovali, reče Jezus Simonu Petru: Simon Jonov, ljubiš li me bolj nego ti? Reče mu: Da, gospod, ti veš, da te ljubim. Veli mu: Pasi moja jagnjeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 16, 'Reče mu zopet drugič: Simon Jonov, ali me ljubiš? Reče mu: Da, gospod, ti veš, da te ljubim. Veli mu: Pastiruj mojim ovcam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 17, 'Reče mu v tretje: Simon Jonov, ali me ljubiš? Peter se razžalosti, ker mu je tretjič rekel: Ali me ljubiš? in mu reče: Gospod, ti vse veš; ti znaš, da te ljubim. Veli mu Jezus: Pasi moje ovčice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 18, 'Resnično, resnično ti pravim: Ko si bil mlajši, si se opasoval sam in hodil, kamor si hotel; ko se pa postaraš, raztegneš roke svoje in drugi te opaše in te povleče, kamor ti nočeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 19, 'To je pa povedal, da naznači, s kako smrtjo bo oslavil Boga. In ko je to povedal, mu veli: Pojdi za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 20, 'Obrnivši se pa ugleda Peter učenca, ki ga je Jezus ljubil, da gre za njim, ki je bil tudi pri večerji slonel na prsih njegovih in je rekel: Gospod, kdo je tisti, ki te izda?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 21, 'Ko torej Peter vidi tega, reče Jezusu: Gospod, kaj pa ta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 22, 'Reče mu Jezus: Ako hočem, da ostane dotlej, ko pridem, kaj tebi za to? Ti pojdi za menoj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 23, 'Razglasila se je torej med brati ta beseda: Ta učenec ne umrje. Toda Jezus mu ni rekel, da ne umrje, ampak: Ako hočem, da ostane dotlej, ko pridem, kaj tebi za to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 24, 'Ta učenec je tisti, ki pričuje o tem in je napisal to; in vemo, da je pričevanje njegovo resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (43, 21, 25, 'Je pa še veliko drugega, kar je storil Jezus; ko bi se to vse posamez napisalo, menim, da tudi ves svet ne bi imel prostora za knjige, ki bi se morale napisati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 1, 'Prvo knjigo torej sem napisal, o Teofil, o vsem, kar je začel Jezus delati in učiti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 2, 'do dneva, ko je bil gori vzet, potem ko je dal zapovedi apostolom po svetem Duhu, ki jih je bil izvolil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 3, 'ki se jim je tudi živega izkazal po svojem trpljenju z mnogimi prepričevalnimi znamenji, ko se jim je štirideset dni prikazoval in govoril o kraljestvu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 4, 'In ko je bil ž njimi zbran, jim je zapovedal, naj ne odidejo iz Jeruzalema, temuč naj čakajo obljube Očetove, ‚ki ste jo slišali od mene;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 5, 'kajti Janez je sicer krstil z vodo, ali vi boste krščeni s svetim Duhom ne dolgo po teh dneh‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 6, 'Ti pa, ki so se bili sešli, so ga torej vpraševali, govoreč: Gospod, ali boš v tem času vnovič postavil kraljestvo v Izraelu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 7, 'On pa jim reče: Ni vaša stvar, da bi znali čase in ure, ki jih je določil Oče po svoji samooblasti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 8, 'temuč prejmete moč, ko pride sveti Duh na vas, in boste mi priče v Jeruzalemu in po vsej Judeji in Samariji in do kraja zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 9, 'In ko je to povedal, se je vzdignil vpričo njih; in oblak ga je vzel izpred njih oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 10, 'In ko so strmeli za njim, gredočim v nebo, glej, pristopita k njim dva moža v beli obleki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 11, 'ki tudi rečeta: Možje Galilejci, kaj stojite in zrete na nebo? Ta Jezus, ki je bil vzet od vas gori v nebo, prav tako pride, kakor ste ga videli, da je šel v nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 12, 'Tedaj so se vrnili v Jeruzalem z gore, ki se imenuje Oljska in je blizu Jeruzalema, en sobotni dan hoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 13, 'In ko so prišli v mesto, stopijo v gornjo izbo, kjer so prebivali: Peter in Jakob in Janez in Andrej, Filip in Tomaž, Bartolomej in Matevž, Jakob Alfejev in Simon Gorečnik in Juda Jakobov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 14, 'Vsi ti so bili ene misli stanovitni v molitvi, z ženami in Marijo, materjo Jezusovo, in z brati njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 15, 'In v te dni vstane Peter sredi bratov in reče (bila pa je zbrana množica kakih sto in dvajset oseb):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 16, 'Možje in bratje, moralo se je izpolniti pismo, ki ga je napovedal sveti Duh z usti Davidovimi o Judu, ki je bil vodnik tem, ki so ujeli Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 17, 'Kajti prištet je bil nam in je z nami prejel delež te službe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 18, 'Ta je torej pridobil njivo s plačilom svoje krivičnosti in se je, padši strmoglavo, po sredi razpočil in se je izsul ves drob njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 19, 'In to se je razglasilo med vsemi, ki prebivajo v Jeruzalemu, tako da se imenuje tista njiva v lastnem njih jeziku Akeldama, to je: Krvava njiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 20, 'Pisano je namreč v knjigi psalmov: „Pusto naj postane domovje njegovo, in ne bodi nikogar, ki bi prebival v njem“; in „Škofjo službo njegovo naj prejme drugi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 21, 'Zato mora eden teh mož, ki so z nami hodili ves čas, dokler je Gospod Jezus z nami prebival,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 22, 'začenši od krsta Janezovega prav do dne, ko je bil gori vzet od nas: eden teh mož mora biti z nami vred priča vstajenja njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 23, 'In postavijo dva: Jožefa, ki se imenuje Barsaba, s priimkom Just, in Matija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 24, 'molijo in reko: Ti, Gospod, ki poznaš srca vseh, pokaži, katerega od teh dveh si izvolil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 25, 'da prejme mesto te službe in apostolstva, ki je od njega odstopil Juda, da je šel v svoj kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 1, 26, 'In vržejo kocke zanju, in kocka pade na Matija; in prištet je bil enajsterim apostolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 1, 'In ko pride petdeseti dan, so bili vsi ene misli skupaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 2, 'Kar nastane šum z neba kakor piš silnega vetra in napolni vso hišo, kjer so sedeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 3, 'In se jim prikažejo razdeljeni jeziki kakor ognjeni, in sedejo na slehernega med njimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 4, 'in vsi se napolnijo svetega Duha in začno govoriti v drugih jezikih, kakor jim je Duh dajal izgovarjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 5, 'Bivali so pa takrat v Jeruzalemu Judje, bogaboječi možje, iz vsakega naroda, ki je pod nebom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 6, 'Ko je pa nastal ta šum, se snide množica, in groza jih obide: zakaj vsak izmed njih sliši, da govore v njegovem jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 7, 'In vsi se zavzemajo in čudijo ter govore: Glej, niso li vsi ti, ki govore, Galilejci?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 8, 'In kako mi slišimo vsak svoj jezik, ki smo se v njem rodili?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 9, 'Parčani in Medi in Elamljani, in ki prebivamo v Mezopotamiji, Judeji in Kapadociji, Pontu in Aziji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 10, 'Frigiji in Pamfiliji, v Egiptu in v krajih Libije pri Cireni, in prišleci iz Rima, Judje in pojudenci,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 11, 'Krečani in Arabci: slišimo, da nam govore v naših jezikih velika dela Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 12, 'In vsi se zavzemajo in strmé, drug drugemu govoreč: Kaj če to biti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 13, 'A drugi se posmehujejo in govore: sladkega vinca so se napili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 14, 'Tedaj se ustopi Peter z enajsterimi in povzdigne glas svoj in jih ogovori: Možje Judje in vsi, ki prebivate v Jeruzalemu, to vam bodi na znanje in poslušajte besede moje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 15, 'Ti namreč niso pijani, kakor vi menite, ker je šele tretja ura dne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 16, 'temuč to je, kar je rečeno po proroku Joelu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 17, '„In zgodi se v poslednjih dneh, pravi Bog: izlijem od Duha svojega na vse človeštvo, in prorokovali bodo sinovi vaši in hčere vaše; in mladeniči vaši bodo videli prikazni, in starcem vašim se bodo sanjale sanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 18, 'in tudi na hlapce svoje in na dekle svoje v tistih dneh izlijem od Duha svojega, in bodo prorokovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 19, 'In pokažem čudeže gori na nebu in znamenja doli na zemlji, kri in ogenj in kajenje dima;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 20, 'solnce se spremeni v temo in mesec v kri, preden pride dan Gospodov, veliki in preslavni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 21, 'In zgodi se, da vsak, kdor bo klical ime Gospodovo, bo zveličan“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 22, 'Možje Izraelci, poslušajte te besede: Jezusa Nazarečana, moža, ki ga je Bog potrdil za vas z močmi in čudeži in znamenji, ki jih je Bog po njem storil med vami, kakor sami veste,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 23, 'tega, izdanega po trdno določenem sklepu in previdnosti Božji, ste vzeli in po rokah krivičnikov na križ razpeli in umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 24, 'Njega je Bog obudil, oprostivši ga bolečin smrti; ker tudi ni bilo mogoče, da bi ga bila ona držala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 25, 'David namreč pravi glede njega: „Gledal sem Gospoda vedno pred seboj, ker je na desnici moji, da ne omahnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 26, 'Tega se je razveselilo srce moje in se je obradoval jezik moj, pa še tudi meso moje bo počivalo v upanju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 27, 'ker ne pustiš duše moje v državi smrti in tudi ne daš, da bi Svetnik tvoj videl trohnenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 28, 'Naznanil si mi pota življenja, napolniš me z veseljem pred obličjem svojim“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 29, 'Možje in bratje, naj bo dovoljeno, govoriti vam svobodno o očaku Davidu: da je umrl in bil pokopan, in grob njegov je pri nas do tega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 30, 'Ker pa je bil prorok in je vedel, da se mu je s prisego zavezal Bog, da posadi enega iz plodu ledja njegovega na prestol njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 31, 'je videl naprej in povedal o vstajenju Kristusovem, da se ni pustila duša njegova v državi smrti in tudi meso njegovo ni videlo trohnenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 32, 'Tega Jezusa je Bog obudil, čemur smo mi vsi priče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 33, 'Z desnico Božjo torej povišan in prejemši obljubo svetega Duha od Očeta, je izlil to, kar vi zdaj vidite in slišite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 34, 'Kajti David ni šel gori v nebesa, nego sam pravi: „Rekel je Gospod Gospodu mojemu: Sedi na desnico mojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 35, 'dokler ne položim sovražnikov tvojih nogam tvojim za podnožje.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 36, 'Za gotovo vedi torej vsa hiša Izraelova, da je Bog i za Gospoda i za Kristusa postavil tega Jezusa, ki ste ga vi križali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 37, 'Ko so pa to slišali, jih zbode v srce ter reko Petru in drugim apostolom: Kaj nam je storiti, možje in bratje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 38, 'Peter jim pa reče: Izpokorite se in naj se krsti vsakdo izmed vas v imenu Jezusa Kristusa v odpuščenje grehov svojih, in prejmete dar svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 39, 'Kajti za vas velja ta obljuba in za otroke vaše in za vse, ki so še daleč, kolikorkoli jih pokliče Gospod, Bog naš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 40, 'In z mnogimi drugimi besedami pričuje in jih opominja, rekoč: Rešite se tega popačenega rodu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 41, 'Kateri so torej besedo njegovo radi sprejeli, so bili krščeni; in pridružilo se jih je tisti dan kakih tri tisoč duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 42, 'Bili so pa stanovitni v nauku apostolov in v bratovski zvezi in v lomljenju kruha in v molitvah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 43, 'Obšel je pa vsako dušo strah; in veliko čudežev in znamenj se je godilo po apostolih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 44, 'Vsi pa, ki so bili sprejeli vero, so bili skupaj in vse so imeli skupno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 45, 'in so prodajali lastnine in imetja ter jih razdeljevali vsem, kakor je kdo potreboval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 46, 'In vsak dan so bili stanovitno ene misli v templju, in po hišah so lomili kruh in prejemali jed z veseljem in preprostim srcem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 2, 47, 'hvaleč Boga in imajoč milost pri vsem ljudstvu. Gospod pa jim je prideval vsak dan teh, ki so se zveličevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 1, 'Peter in Janez pa sta šla gori v tempelj ob uri molitve, ob devetih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 2, 'In nosili so nekega moža, ki je bil hrom od materinega telesa, in so ga pokladali vsak dan v templju pred vrata, ki se imenujejo Lepa, da je prosil miloščine teh, ki so hodili v tempelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 3, 'Ko ta vidi Petra in Janeza, da hočeta stopiti v tempelj, prosi, da bi mu dala miloščino.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 4, 'Pogleda pa Peter nanj z Janezom in veli: Poglej na naju!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 5, 'In on vpre oči vanju, misleč, da od nju kaj prejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 6, 'Peter pa veli: Srebra in zlata nimam; kar pa imam, to ti dam. V imenu Jezusa Kristusa Nazarečana vstani in hodi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 7, 'In prime ga za desno roko in ga vzdigne: in takoj se utrde stopala njegova in gležnji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 8, 'In poskočivši, stoji in začne hoditi, in gre ž njima v tempelj, hodeč in poskakujoč in hvaleč Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 9, 'In vidi ga vse ljudstvo, da hodi in hvali Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 10, 'in ga spoznajo, da je tisti, ki je zaradi miloščine sedel pri Lepih vratih templja: in prevzame jih groza in strmenje ob tem, kar se mu je prigodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 11, 'Ko se je pa ta ozdravljenec držal Petra in Janeza, priteče k njim vse ljudstvo zelo prestrašeno v lopo, ki se imenuje Salomonova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 12, 'Videč pa to, odgovori Peter ljudstvu: Možje Izraelci, kaj se čudite temu, ali kaj naju gledate, kakor da bi bila z lastno močjo ali pobožnostjo storila, da ta hodi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 13, 'Bog Abrahamov in Izakov in Jakobov, očetov naših Bog, je oslavil Služabnika svojega Jezusa, ki ste ga vi izdali in zatajili pred obličjem Pilatovim, ko je on sodil, naj se izpusti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 14, 'A vi ste Svetnika in Pravičnika zatajili in ste prosili, naj vam da ubijalca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 15, 'Začetnika življenja pa ste umorili! Tega je Bog obudil iz mrtvih, čemur smo mi priče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 16, 'In po veri v ime njegovo je tega, ki ga vidite in poznate, utrdilo ime njegovo; in vera, ki je po njem, mu je dala to popolno zdravje vpričo vseh vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 17, 'Ali sedaj, bratje, vem, da ste to storili iz nevednosti, kakor tudi poglavarji vaši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 18, 'Bog pa je, kar je naprej oznanil z usti vseh prorokov, da bo njegov Maziljenec trpel, tako dopolnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 19, 'Izpokorite se torej in izpreobrnite, da se izbrišejo grehi vaši, da tako pridejo časi poživljenja od obličja Gospodovega');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 20, 'in pošlje za vas določenega Maziljenca Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 21, 'ki ga sicer mora nebo sprejeti do časov preuredbe vsega, kar je Bog povedal z usti svetih prorokov svojih od nekdaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 22, 'Mojzes je že rekel: „Proroka vam zbudi Gospod, Bog vaš, izmed bratov vaših kakor mene; njega poslušajte v vsem, karkoli vam bo govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 23, 'Zgodi se pa, da se vsaka duša, ki ne bo poslušala tega proroka, iztrebi izmed ljudstva“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 24, 'Pa tudi vsi proroki od Samuela in poznejši, kolikorkoli jih je govorilo, so tudi oznanili te dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 25, 'Vi ste sinovi prorokov in zaveze, ki jo je Bog sklenil z očeti vašimi, govoreč Abrahamu: „In v semenu tvojem bodo blagoslovljene vse rodovine zemlje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 3, 26, 'Vam najprej je zbudil Bog Služabnika svojega Jezusa in ga poslal blagoslavljat vas, da se sleherni izpreobrne od hudobij svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 1, 'Ko sta pa govorila ljudstvu, pristopijo k njima duhovniki in poglavar templja in saduceji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 2, 'ki jih je zelo peklo, da učita ljudstvo in oznanjujeta v Jezusu vstajenje iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 3, 'In polože nanju roke in ju denejo v ječo do jutra; kajti bil je že večer.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 4, 'Mnogo teh pa, ki so slišali njun govor, je sprejelo vero; in število mož je naraslo na kakih pet tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 5, 'Zgodi se pa drugi dan, da se zbero njih poglavarji in starejšine in pismarji v Jeruzalemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 6, 'in Ana, veliki duhovnik, in Kajfa in Janez in Aleksander in kolikor jih je bilo iz višjega duhovskega rodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 7, 'in ko so ju postavili na sredo, vprašajo: S kakšno močjo ali v čigavem imenu sta vidva to storila?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 8, 'Tedaj jim Peter, napolnivši se svetega Duha, reče: Poglavarji naroda in starejšine!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 9, 'Če naju danes izprašujete za dobroto, ki sva jo storila bolnemu človeku, kako je on ozdravel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 10, 'znano bodi vsem vam in vsemu ljudstvu Izraelovemu, da po imenu Jezusa Kristusa Nazarečana, ki ste ga vi križali, ki ga pa je Bog obudil iz mrtvih, po njem stoji ta pred vami zdrav.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 11, 'On je kamen, ki ste ga vi zidarji zavrgli, pa je postal glava voglu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 12, 'In v nikomer drugem ni zveličanja; zakaj ni ga tudi pod nebom ljudem danega drugega imena, po katerem bi se mi mogli zveličati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 13, 'Ko pa vidijo srčnost Petrovo in Janezovo in zaznajo, da sta neučena in preprosta človeka, se začudijo; in ju spoznajo, da sta hodila z Jezusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 14, 'Videč tudi človeka, ki je ozdravel, da stoji ž njima, niso imeli kaj ugovarjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 15, 'Velé jima pa, naj gresta ven iz zbora, in se posvetujejo med seboj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 16, 'govoreč: Kaj bomo storili tema človekoma? kajti da se je očividen čudež po njiju zgodil, je znano vsem, ki prebivajo v Jeruzalemu, in ne moremo utajiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 17, 'Ali da se to ne razglasi dalje med ljudstvom, jima zapretimo, naj nobenemu človeku nikoli več ne govorita o tem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 18, 'In ju pokličejo ter jima zapovedo, naj nikdar več ne zineta in ne učita o imenu Jezusovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 19, 'A Peter in Janez odgovorita in jim rečeta: Ali je prav pred Bogom, da vas bolj poslušava nego Boga, sodite sami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 20, 'Ne moreva namreč, da ne bi govorila tega, kar sva videla in slišala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 21, 'Oni pa jima še bolj zaprete in ju izpuste, ker niso našli, kako bi ju kaznovali, zavoljo ljudstva, ker so vsi hvalili Boga za to, kar se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 22, 'Imel je namreč več nego štirideset let človek, na katerem se je zgodil ta čudež ozdravljenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 23, 'Ko so ju pa izpustili, prideta k svojim in jim sporočita, kar so jima rekli višji duhovniki in starejšine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 24, 'Oni pa, ko so to slišali, povzdignejo ene misli glas k Bogu in reko: O Gospod, ti si Bog, ki si ustvaril nebo in zemljo in morje in vse, kar je v njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 25, 'ki si rekel po svetem Duhu z usti našega Očeta Davida, hlapca svojega: „Zakaj se togote pogani in ljudstva izmišljajo prazne reči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 26, 'Postavljajo se kralji zemlje in poglavarji se zbirajo zoper Gospoda in zoper Maziljenca njegovega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 27, 'Kajti zbrali so se zares v tem mestu zoper svetega Služabnika tvojega, Jezusa, ki si ga pomazilil, Herod in Poncij Pilat s pogani in ljudstvom Izraelovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 28, 'da store, kar je naprej določila roka tvoja in sklep tvoj, da naj se zgodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 29, 'In sedaj, Gospod, poglej na njih pretenje in daj hlapcem svojim, da z vso srčnostjo govore besedo tvojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 30, 's tem, da iztegneš roko svojo na ozdravljanje, in da se znamenja in čudeži gode po imenu svetega Služabnika tvojega, Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 31, 'In ko so odmolili, se potrese mesto, ki so v njem bili zbrani, in vsi se napolnijo svetega Duha; in govorili so besedo Božjo srčno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 32, 'Množica teh pa, ki so sprejeli vero, je bila enega srca in enega duha; tudi nihče ni govoril, da je kaj njegovega od tega, kar je imel, temuč vse jim je bilo skupno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 33, 'In z veliko močjo so dajali apostoli pričevanje za vstajenje Gospoda Jezusa, in milost velika je bila na vseh njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 34, 'Ni ga bilo namreč ubožca med njimi: kajti koliko jih je bilo, ki so imeli njive ali hiše, ti so jih prodajali, in so prinašali izkupiček tega, kar so prodali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 35, 'in pokladali apostolom pred noge: in oddelilo se je vsakemu, kolikor je potreboval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 36, 'Jožef pa, ki so mu apostoli dali priimek Barnaba (kar se tolmači: Sin tolažbe), levit, s Cipra po rodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 4, 37, 'je imel njivo, pa jo je prodal in prinesel denar in ga položil apostolom pred noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 1, 'A neki mož, Ananija po imenu, s Safiro, ženo svojo, je prodal posestvo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 2, 'in nekaj od izkupila je utajil z vednostjo žene svoje; in prinese en del in ga položi apostolom pred noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 3, 'Peter pa reče: Ananija, zakaj je satan napolnil srce tvoje, da si lagal svetemu Duhu, in si utajil nekaj od izkupička njive?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 4, 'Ali ne bi bila, ko bi jo bil obdržal, tebi ostala? in ko je bila prodana, ali ni bila v tvoji oblasti? Kaj, da si to reč položil v srce svoje? Nisi lagal ljudem, ampak Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 5, 'Ko je pa Ananija slišal te besede, pade in izdahne. In velik strah obide vse, ki so to slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 6, 'Mladeniči pa vstanejo ter ga pripravijo k pogrebu, odneso in pokopljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 7, 'Zgodi se pa kake tri ure pozneje, da pride tudi žena njegova, ne vedoč, kaj se je zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 8, 'Peter pa jo ogovori: Povej mi, ali sta za toliko prodala njivo? Ona pa reče: Da, za toliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 9, 'Peter ji pa reče: Zakaj sta se dogovorila, da bosta izkušala Duha Gospodovega? Glej, noge teh, ki so pokopali moža tvojega, so pred durmi in te poneso ven.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 10, 'In pri tej priči mu pade pred noge in izdahne. In ko mladeniči vstopijo, jo najdejo mrtvo in jo odneso ven in pokopljejo poleg moža njenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 11, 'In velik strah je obšel vso cerkev in vse, ki so to slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 12, 'Po rokah apostolov pa se je godilo veliko znamenj in čudežev med ljudstvom; (in vsi so bili ene misli v lopi Salomonovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 13, 'A od drugih se jim ni upal nihče pridružiti; vendar pa jih je ljudstvo visoko čislalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 14, 'In čimdalje več jih je pristopalo, ki so verovali Gospodu, množice mož in žen;)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 15, 'da so celo nosili bolnike na ulice in jih pokladali na postelje in odre, da bi vsaj senca mimoidočega Petra obsenčila koga od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 16, 'Shajala pa se je tudi množica iz sosednjih mest v Jeruzalem, in so prinašali bolnike in tiste, ki so jih mučili nečisti duhovi; in vsi so bili ozdravljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 17, 'Vstane pa veliki duhovnik in vsi njegovi pristaši (ki so ločina saducejev), in napolnijo se zavisti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 18, 'in iztegnejo roke po apostolih in jih denejo v občno ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 19, 'Toda angel Gospodov odpre po noči vrata in jih izpelje iz ječe, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 20, 'Pojdite in ustopite se in govorite v templju ljudstvu vse besede tega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 21, 'Ko so pa to slišali, gredo zjutraj v tempelj ter učé. Pride pa veliki duhovnik in njegovi pristaši, ter skličejo veliki zbor in vse starejšine sinov Izraelovih in pošljejo v ječo, naj jih pripeljejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 22, 'A služabniki, prišedši v ječo, jih ne najdejo; in vrnejo se ter sporoče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 23, 'rekoč: Ječo smo sicer našli z vso skrbjo zaprto in varuhe stoječe pred vrati; ko smo pa odprli, nismo nikogar notri našli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 24, 'Ko pa slišijo te besede poglavar templja in višji duhovniki, pridejo v veliko zadrego zastran njih in vprašajo, kaj neki bo iz tega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 25, 'Pa pride nekdo in jim sporoči, rekoč: Glej, možje, ki ste jih deli v ječo, stoje v templju in uče ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 26, 'Tedaj odide poglavar s služabniki ter jih pripelje, ne siloma, ker so se bali ljudstva, da jih ne bi kamenalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 27, 'In ko jih pripeljejo, jih postavijo pred zbor. In veliki duhovnik jih vpraša,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 28, 'rekoč: Ali vam nismo ostro naročili, da ne smete učiti o tem imenu? In glej, napolnili ste Jeruzalem z naukom svojim in hočete na nas spraviti kri tega človeka!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 29, 'Peter in apostoli odgovore in reko: Boga je treba bolj poslušati nego ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 30, 'Bog očetov naših je obudil Jezusa, ki ste ga vi obesili na les in umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 31, 'Tega je Bog z desnico svojo povišal za Kneza in Zveličarja, da dodeli Izraelu izpokorjenje in odpuščenje grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 32, 'In mi smo mu priče teh reči in tudi sveti Duh, katerega je Bog dal tem, ki so pokorni njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 33, 'Ko so pa to slišali, so se silno srdili, in mislili so jih umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 34, 'Pa vstane v zboru neki farizej, Gamaliel po imenu, učenik postave, spoštovan od vsega ljudstva, in ukaže, naj apostole malo odvedejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 35, 'In jim reče: Možje Izraelci, pazite nase pri teh ljudeh, kaj hočete storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 36, 'Kajti pred temi dnevi je vstal Tevda, govoreč, da je on nekaj, in pridružilo se mu je število mož, kakih štiristo; on je bil ubit in vsi, ki so ga poslušali, so se razpršili in so bili uničeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 37, 'Za tem je vstal Juda Galilejec, v dneh popisovanja, in je potegnil dosti ljudstva za seboj; tudi on je poginil in vsi, ki so ga poslušali, so se razkropili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 38, 'In zato vam sedaj pravim: odstopite od teh ljudi in jih pustite! Zakaj, če je od ljudi ta naklep ali to delo, se razdere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 39, 'če je pa od Boga, ga ne morete razdreti; da se morda ne pokažete Bogu nasprotnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 40, 'In poslušali so ga: in pokličejo apostole in jih pretepo ter jim naroče, naj ne govore o imenu Jezusovem, in jih izpuste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 41, 'Oni gredo torej izpred velikega zbora in se vesele, da so bili spoznani za vredne, trpeti sramoto za ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 5, 42, 'In niso nehali v templju in po hišah vsak dan učiti in oznanjevati evangelija o Jezusu, da je Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 1, 'V teh dnevih pa, ko so se učenci množili, nastane godrnjanje grških Judov zoper Hebrejce, da se pri vsakdanji postrežbi zanemarjajo njih vdove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 2, 'In dvanajsteri skličejo množico učencev in reko: To ne gre, da bi mi besedo Božjo opuščali in oskrbovali mize.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 3, 'Ozrite se torej, bratje, po sedmih možeh izmed sebe, ki so na dobrem glasu, polni svetega Duha in modrosti, da jih postavimo nad tem opravilom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 4, 'a mi se bomo marljivo držali molitve in službe besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 5, 'In ta beseda je bila vsej množici pogodu; ter izvolijo Štefana, moža polnega vere in svetega Duha, in Filipa in Prohora in Nikanora, Timona in Parmena in Nikolaja, pojudenca iz Antiohije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 6, 'Te postavijo pred apostole, in molijo in pokladajo nanje roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 7, 'In beseda Božja je rasla, in število učencev se je silno množilo v Jeruzalemu; tudi precejšnja množica duhovnikov je bila pokorna veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 8, 'Štefan pa, poln milosti in moči, je delal velike čudeže in znamenja med ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 9, 'In vstane jih nekaj iz takoimenovane shodnice Libertinov in Cirencev in Aleksandrijcev, in iz shodnice teh, ki so bili iz Cilicije in Azije, in se prepirajo s Štefanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 10, 'Ali niso se mogli upirati modrosti in Duhu, po katerem je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 11, 'Tedaj nahujskajo može, ki naj bi rekli: Slišali smo ga govoriti kletvine zoper Mojzesa in Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 12, 'Ter razdražijo ljudstvo in starejšine in pismarje, ga napadejo in ga zgrabijo in pripeljejo v veliki zbor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 13, 'In postavijo krive priče, ki izpričajo: Ta človek ne neha govoriti kletvin zoper ta sveti kraj in zoper postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 14, 'Slišali smo ga namreč, da pravi: Ta Jezus Nazarečan razdene to mesto in premeni šege, ki nam jih je izročil Mojzes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 6, 15, 'In ostro ga pogledajo vsi, ki sede v velikem zboru, in vidijo obličje njegovo kakor obličje angela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 1, 'In veliki duhovnik reče: Je li to tako?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 2, 'On pa reče: Možje, bratje in očetje, poslušajte! Bog slave se je prikazal očetu našemu Abrahamu, ko je bil v Mezopotamiji, preden se je nastanil v Haranu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 3, 'in mu je rekel: Odidi iz zemlje svoje in od rodovine svoje, in pojdi v zemljo, ki ti jo pokažem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 4, 'Tedaj je odšel iz zemlje Kaldejske in se je nastanil v Haranu. In odtod, ko je bil oče njegov umrl, ga je Bog preselil v to zemljo, v kateri vi sedaj prebivate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 5, 'In ni mu dal dediščine v njej, še za stopinjo noge ne, in jo je obljubil dati njemu v posest in semenu njegovemu za njim, ko še ni imel sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 6, 'Rekel je pa Bog tako: „Seme tvoje bo priseljeno v tuji zemlji, in sužnosti ga podvržejo in hudo bodo ravnali ž njim štiristo let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 7, 'Toda narod, ki mu bodo sužnjevali, bom sodil jaz, je dejal Bog; in potem izidejo in bodo meni služili na tem mestu“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 8, 'In dal mu je zavezo obreze; in tako je rodil Izaka in ga je obrezal osmi dan, in Izak Jakoba, in Jakob dvanajstere očake.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 9, 'In očaki so iz nevoščljivosti prodali Jožefa v Egipt; a Bog je bil ž njim');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 10, 'in ga je rešil iz vseh nadlog njegovih in mu dal milost in modrost pred Faraonom, kraljem egiptovskim, ki ga je postavil za poglavarja nad Egiptom in vso hišo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 11, 'Prišla pa je lakota nad vso zemljo Egiptovsko in Kanaansko in velika nadloga; in niso našli živeža očetje naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 12, 'Ko pa je slišal Jakob, da je žita v Egiptu, je poslal tja očete naše prvikrat;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 13, 'in v drugo so spoznali Jožefa bratje njegovi, in znana je postala Faraonu rodovina Jožefova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 14, 'Pošlje pa Jožef in pokliče očeta svojega Jakoba in vse sorodstvo svoje, petinsedemdeset duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 15, 'In prišel je Jakob doli v Egipt, in tam je umrl on in očetje naši;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 16, 'in prinesli so jih v Sihem in položili v grob, ki ga je kupil Abraham za ceno v srebru od sinov Hemorjevih v Sihemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 17, 'Ko se je pa bližal čas obljube, ki jo je prisegel Bog Abrahamu, je raslo ljudstvo in se množilo v Egiptu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 18, 'dokler ni začel vladati v Egiptu drug kralj, ki ni poznal Jožefa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 19, 'Ta je zvijačno ravnal z rodom našim in zatiral očete naše, da so morali izpostavljati otroke svoje, da bi ne ostali živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 20, 'V tem času se je rodil Mojzes in je bil prijeten Bogu; in tri mesece so ga redili v hiši očeta njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 21, 'A ko je bil izpostavljen, ga je vzela hči Faraonova in ga je odgojila sebi za sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 22, 'In naučil se je Mojzes vse modrosti Egipčanov, in je bil mogočen v svojih besedah in dejanjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 23, 'Ko je pa dopolnil štirideset let, mu je prišlo na misel, obiskati brate svoje, sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 24, 'In ko je videl nekoga, da trpi krivico, ga je obranil in v maščevanje tega, ki je krivico trpel, je ubil Egipčana.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 25, 'Menil je pa, da njegovi bratje umejo, da jim hoče Bog po njegovi roki dati odrešenje; toda oni niso tega razumeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 26, 'A drugi dan je prišel k njim, ko so se prepirali, in jih je miril, rekoč: Možje, vi ste bratje; zakaj delate krivico drug drugemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 27, 'Tisti pa, ki je delal krivico bližnjemu, ga odpahne, rekoč: „Kdo te je postavil za poglavarja in sodnika nad nami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 28, 'Ali me hočeš ubiti, kakor si včeraj ubil Egipčana?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 29, 'Mojzes je pa pobegnil na to besedo in je bil tujec v zemlji Madianski, kjer je rodil dva sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 30, 'In ko se je dopolnilo štirideset let, se mu je prikazal v puščavi gore Sinajske angel v plamenu gorečega grma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 31, 'Ko je pa Mojzes to videl, se je začudil prikazni; in ko pristopi, da bi pogledal, se mu oglasi glas Gospodov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 32, '„Jaz sem Bog očetov tvojih, Bog Abrahamov in Izakov in Jakobov“. Mojzes pa strepeta in si ne upa tja pogledati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 33, 'Reče pa mu Gospod: „Sezuj obuvalo z nog svojih; kajti mesto, ki na njem stojiš, je sveta zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 34, 'Dobro sem videl stisko ljudstva svojega, ki je v Egiptu, in njih zdihovanje sem slišal; in stopil sem doli, da jih rešim. In sedaj pridi, pošljem te v Egipt“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 35, 'Tega Mojzesa, ki so se ga bili odrekli, rekoč: Kdo te je postavil za poglavarja in sodnika? tega je Bog poslal kot poglavarja in odrešenika s pomočno roko angela, ki se mu je bil prikazal v grmu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 36, 'Ta jih je izpeljal, delajoč čudeže in znamenja v Egiptu in na Rdečem morju in v puščavi štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 37, 'Ta je tisti Mojzes, ki je rekel sinovom Izraelovim: „Proroka vam obudi Gospod Bog izmed bratov vaših kakor mene“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 38, 'Ta je tisti, ki je bil pri zboru v puščavi z angelom, ki mu je govoril na gori Sinajski, in z očeti našimi; tisti, ki je prejel besede življenja, da nam jih da;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 39, 'ki mu pa niso hoteli biti pokorni očetje naši, ampak so ga zavrgli in obrnili srca svoja v Egipt,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 40, 'rekši Aronu: „Naredi nam bogove, ki naj hodijo pred nami; zakaj temu Mojzesu, ki nas je izpeljal iz zemlje Egiptovske, ne vemo, kaj se mu je zgodilo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 41, 'In ulili so tele tiste dni in so darovali daritev maliku in se veselili izdelka svojih rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 42, 'Bog pa se je odvrnil in jih je izdal, naj služijo zvezdam neba, kakor je pisano v knjigi prorokov: „Ali ste mi darovali klalne in žgalne daritve štirideset let v puščavi, hiša Izraelova?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 43, 'temuč nosili ste šator Molohov in boga Remfana zvezdo, podobe, ki ste jih naredili, da se jim poklanjate. Zato pa vas preselim onostran Babilona“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 44, 'Šator pričevanja so imeli očetje naši v puščavi, kakor je ukazal ta, ki je rekel Mojzesu, naj ga naredi po podobi, ki jo je videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 45, 'Ta šator so tudi prejeli očetje naši in so ga sem prinesli z Jozuetom, ko so posedli deželo poganov, ki jih je izgnal Bog izpred obličja očetov naših, do dni Davidovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 46, 'ki je našel milost pred Bogom in je prosil, da bi našel prebivališče Bogu Jakobovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 47, 'A Salomon mu je sezidal hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 48, 'Ali Najvišji ne prebiva v svetiščih, z rokami narejenih, kakor pravi prorok:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 49, '„Nebo mi je stol, a zemlja podnožje nogam mojim. Kakšno hišo mi sezidate? pravi Gospod; ali katero naj bo mesto počivanju mojemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 50, 'Ni li roka moja vsega tega naredila?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 51, 'Trdovratni in neobrezanih src in ušes! Vi se vedno upirate Duhu svetemu, kakor očetje vaši, tako vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 52, 'Katerega od prorokov niso preganjali očetje vaši? In pomorili so te, ki so naprej oznanjali prihod Pravičnika, čigar izdajalci in ubijalci ste sedaj postali vi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 53, 'ki ste prejeli postavo po uredbi angelov, in je niste ohranili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 54, 'Ko so pa to slišali, jih je zbodlo v srce, in škripali so z zobmi zoper njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 55, 'On pa, poln svetega Duha, se ozre na nebo in ugleda slavo Božjo in Jezusa, stoječega na desnici Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 56, 'in reče: Glej nebesa vidim odprta in Sina človekovega, stoječega na desnici Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 57, 'In zakriče z močnim glasom in si zamaše ušesa pa planejo ene misli nanj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 58, 'in ga ženo ven iz mesta in lučajo kamenje vanj. In priče položé oblačila svoja pred noge mladeniču, ki mu je bilo ime Savel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 59, 'In pobijajo s kamenjem Štefana, ki kliče h Gospodu in reče: Gospod Jezus, sprejmi Duha mojega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 7, 60, 'In poklekne in zavpije z močnim glasom: Gospod, ne štej jim tega greha! In rekši to, je zaspal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 1, 'Savel pa se je ž njimi radoval njegove smrti. In nastalo je ta dan veliko preganjanje cerkve, ki je bila v Jeruzalemu; in vsi so se razkropili po judejskih in samarijskih krajih, razen apostolov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 2, 'Pokopali pa so Štefana pobožni možje in so zelo plakali za njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 3, 'A Savel je zatiral cerkev, in je hodil po hišah in vlačil može in žene ter jih izročal v ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 4, 'Tisti pa, ki so se bili razkropili, so hodili okrog, oznanjujoč besedo evangelija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 5, 'A Filip je šel doli v samarijsko mesto in jim je propovedoval Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 6, 'In množica je pazila enega duha na to, kar je pravil Filip, poslušajoč in gledajoč znamenja, ki jih je delal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 7, 'Kajti nečisti duhovi so izhajali iz mnogih obsedencev, vpijoč z močnim glasom; in veliko mrtvoudnih in hromih je ozdravelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 8, 'In nastala je velika radost v tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 9, 'Bil je pa neki mož, po imenu Simon, že dokaj časa v mestu, ki se je pečal s čarovništvom in mamil ljudstvo samarijsko, govoreč, da je on nekaj velikega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 10, 'katerega so vsi poslušali, od najmanjšega do največjega, govoreč: Ta je moč Božja, ki se imenuje velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 11, 'Poslušali so ga pa zato, ker jih je bil dolgo časa mamil s čarodejstvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 12, 'Ko so pa verovali Filipu, ki je oznanjeval evangelij o kraljestvu Božjem in o imenu Jezusa Kristusa, so se dali krstiti možje in žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 13, 'Tudi Simon sam je sprejel vero, in po svojem krstu se je držal Filipa; in videč znamenja in velike čudeže, ki so se godili, je strmel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 14, 'Ko so pa apostoli v Jeruzalemu slišali, da je sprejela Samarija besedo Božjo, pošljejo k njim Petra in Janeza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 15, 'In ko sta prišla doli, sta molila zanje, da bi prejeli svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 16, 'Zakaj na nobenega izmed njih še ni bil prišel, ampak bili so samo krščeni v ime Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 17, 'Tedaj sta pokladala roke nanje, in so prejemali svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 18, 'Videč pa Simon, da se po pokladanju rok apostolov daje sveti Duh, jima prinese denarja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 19, 'in reče: Dajta tudi meni to oblast, da prejme svetega Duha, na kogarkoli položim roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 20, 'Peter pa mu reče: Srebro tvoje naj s teboj vred pogine, ker meniš, da se more dar Božji dobiti za denar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 21, 'Nimaš ga dela, ne deleža v tej reči, kajti srce tvoje ni odkrito proti Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 22, 'Izpokori se torej od te hudobnosti svoje in prosi Gospoda, če bi se ti morda odpustila namera srca tvojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 23, 'Kajti vidim te, da si v žolču grenkobe in v zvezi krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 24, 'Simon pa odgovori in reče: Prosita vidva zame Gospoda, da ne pride name nič tega, kar sta rekla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 25, 'Ona torej, potem ko sta izpričala in govorila besedo Gospodovo, sta se vračala v Jeruzalem in mnogim vasem Samarijanov oznanjevala evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 26, 'Angel Gospodov pa je govoril Filipu in dejal: Vstani in pojdi proti poldnevu, na cesto, ki pelje iz Jeruzalema doli v Gazo; ona je pusta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 27, 'In vstane ter odide. In glej, mož iz Etiopije, komornik in oblastnik Kandake, kraljice etiopske, ki je bil nad vsemi njenimi zakladi in je bil prišel molit v Jeruzalem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 28, 'se vrača domov, in sedeč na vozu svojem, prebira proroka Izaija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 29, 'Duh pa reče Filipu: Pristopi in pridruži se temu vozu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 30, 'Filip pa priteče in ga sliši, da bere proroka Izaija, ter reče: Ali pa umeš, kar bereš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 31, 'On pa reče: Kako bi neki mogel, če me kdo ne napoti? In zaprosi Filipa, naj vstopi in sede k njemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 32, 'Vrsta pisma, ki jo je bral, pa je bila ta: „Pelje se kakor ovca na klanje, in kakor jagnje molči pred strižcem svojim, tako ne odpre ust svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 33, 'V ponižanju njegovem se je preklicala sodba njegova. A rod njegov kdo razloži? kajti življenje njegovo se vzame od zemlje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 34, 'Izpregovori pa komornik in reče: Prosim te, o kom govori to prorok? o sebi ali o kom drugem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 35, 'Filip pa odpre usta in, začenši od tega pisma, mu oznani blagovestje o Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 36, 'Ko se pa tako peljeta po cesti, prideta k vodi; in komornik reče: Glej, voda! kaj brani, da bi bil krščen?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 37, '§ Filip pa reče: Če veruješ iz vsega srca, smeš. In odgovori in reče: Verujem, da je Jezus Kristus Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 38, 'In ukaže ustaviti voz; in oba stopita v vodo, Filip in komornik, in ga krsti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 39, 'Ko pa stopita iz vode, vzame Duh Gospodov Filipa; in ni ga več videl komornik, zakaj nadaljeval je vesel svojo pot.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 8, 40, 'A Filip se je znašel v Azotu, in gredoč dalje, je oznanjeval evangelij vsem mestom, dokler ni prišel v Cezarejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 1, 'Savel pa, še vedno dihteč pretenje in morjenje zoper učence Gospodove, pristopi k velikemu duhovniku');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 2, 'in izprosi od njega pisem v Damask do shodnic, če najde kake pristaše tega pota, bodisi može ali žene, da jih zvezane pripelje v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 3, 'Na poti pa, ko se je že bližal Damasku, se zgodi, da ga nagloma obsije svetloba z neba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 4, 'In pade na zemljo in zasliši glas, da mu pravi: Savel, Savel, kaj me preganjaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 5, 'On pa reče: Kdo si, Gospod? A Gospod reče: Jaz sem Jezus, ki ga ti preganjaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 6, 'Ali vstani in pojdi v mesto, in tam se ti pove, kaj ti je treba storiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 7, 'Možje pa, ki so ž njim šli, se ustavijo in strmé, ko glas sicer slišijo, pa nikogar ne vidijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 8, 'In Savel vstane s tal; ko pa odpre oči, ne vidi ničesar. Tedaj ga primejo za roko in pripeljejo v Damask.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 9, 'In tri dni ni videl, in ni jedel, ne pil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 10, 'Bil je pa neki učenec v Damasku, po imenu Ananija; in Gospod mu veli v prikazni: Ananija! On pa reče: Tu sem, Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 11, 'A Gospod njemu: Vstani in pojdi v ulico, ki se imenuje Ravna, in vprašaj v hiši Judovi po nekem Taršanu, ki se imenuje Savel. Kajti glej, moli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 12, 'in je videl v prikazni moža, po imenu Ananija, da vstopi in položi nanj roke, da bi izpregledal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 13, 'Ananija pa odgovori: Gospod, slišal sem od mnogih o tem možu, koliko hudega je storil svetim tvojim v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 14, 'In tu ima oblast od velikih duhovnikov zvezati vse, ki kličejo ime tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 15, 'Gospod pa mu veli: Pojdi; zakaj posoda izvoljena mi je on, da ponese ime moje pred pogane in kralje in sinove Izraelove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 16, 'Jaz namreč mu pokažem, koliko mora trpeti za moje ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 17, 'In Ananija odide in pride v hišo, ter položivši nanj roke, reče: Savel, brat! Gospod me je poslal, Jezus, ki se ti je prikazal na poti, po kateri si šel, da izpregledaš in se napolniš svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 18, 'In precej padejo z oči njegovih kakor luskine, in takoj izpregleda. In vstane ter se da krstiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 19, 'In vzame jedi in se pokrepča. In bil je nekaj dni z učenci, ki so bili v Damasku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 20, 'In precej je po shodnicah oznanjeval Jezusa, da je on Sin Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 21, 'In zavzemali so se vsi, ki so ga slišali, in so govorili: Ni li ta tisti, ki je zatiral v Jeruzalemu te, ki so klicali to ime? in sem je bil prišel zato, da jih zvezane popelje k višjim duhovnikom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 22, 'Savel pa je čimdalje prihajal močnejši in begal Jude, ki so bili v Damasku, trdno dokazujoč, da je ta Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 23, 'Ko je pa minilo dosti dni, se posvetujejo Judje, kako ga bodo umorili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 24, 'ali Savel zve za njih zalezovanje. Stražijo pa tudi pri vratih noč in dan, da bi ga umorili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 25, 'toda učenci njegovi ga vzemo po noči in ga spuste čez zid po vrvi v košu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 26, 'Ko pa pride v Jeruzalem, se je poskušal pridružiti učencem; ali vsi so se ga bali, ker niso verjeli, da je učenec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 27, 'Barnaba pa ga vzame in pripelje k apostolom in jim razloži, kako je bil na poti videl Gospoda in da je v Damasku srčno govoril v imenu Jezusovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 28, 'In bival je ž njimi, hodeč v Jeruzalemu ven in noter in srčno govoreč v imenu Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 29, 'Govoril je pa tudi in se prepiral z grškimi Judi; a oni so ga nameravali umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 30, 'Ko pa zvedo to bratje, ga odpeljejo doli v Cezarejo in ga pošljejo v Tars.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 31, 'Tako je zdaj cerkev po vsej Judeji in Galileji in Samariji imela mir in je napredovala; in ker je hodila v strahu Gospodovem in v tolažbi svetega Duha, se je razmnoževala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 32, 'Zgodi se pa, ko je Peter obiskoval vse, da pride tudi k svetim, ki so prebivali v Lidi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 33, 'In tu najde nekega človeka, po imenu Eneja, ki je že osem let ležal v postelji, ker je bil mrtvouden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 34, 'In Peter mu veli: Eneja, Jezus Kristus te ozdravlja; vstani in postelji si sam! In precej vstane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 35, 'In videli so ga vsi, ki so prebivali v Lidi in Saronu, in so se izpreobrnili h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 36, 'A v Jopi je bila neka učenka, po imenu Tabita (ki se imenuje, če raztolmačiš: Srna); ta je bila polna dobrih del in miloščin, ki jih je delila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 37, 'Zgodi se pa tiste dni, da zboli in umrje; in omivši jo, jo polože v gornjo izbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 38, 'Ker je pa Lida blizu Jope in so učenci slišali, da je Peter tam, pošljejo k njemu dva moža, proseč, naj ne odlaša priti k njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 39, 'Peter pa vstane in gre ž njima. In ko pride, ga peljejo v gornjo izbo; in vse vdove ga obstopijo, jokajoč in kažoč suknje in oblačila, ki jim jih je delala Srna, dokler je bila ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 40, 'Peter pa izžene vse ven ter poklekne in moli; nato se obrne k truplu in reče: Tabita, vstani! In ona odpre oči, in ko ugleda Petra, sede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 41, 'In podavši ji roko, jo vzdigne; in pokliče svete in vdove ter jim jo pokaže živo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 42, 'In to se razglasi po vsej Jopi, in veliko jih je sprejelo vero v Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 9, 43, 'Zgodi se pa, da je dosti dni prebil v Jopi pri nekem Simonu strojarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 1, 'Bil je pa neki mož v Cezareji, po imenu Kornelij, stotnik čete, ki se je imenovala Laška,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 2, 'pobožen in bogaboječ z vso hišo svojo, ki je dajal veliko miloščine ljudem in je molil k Bogu neprenehoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 3, 'Ta je videl v prikazni razločno, okoli devete ure po dnevi, angela Božjega, da je prišel k njemu in mu rekel: Kornelij!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 4, 'On pa pogleda nanj, se preplaši in reče: Kaj je, Gospod? On pa mu veli: Molitve tvoje in miloščine tvoje so prišle v spomin pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 5, 'In sedaj pošlji v Jopo mož in pokliči Simona, ki ima priimek Peter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 6, 'On gostuje pri nekem Simonu strojarju, čigar hiša je pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 7, 'Ko pa odide angel, ki je govoril ž njim, pokliče dva domačih svojih in pobožnega vojaka izmed teh, ki so mu vedno služili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 8, 'in razloživši jim vse, jih pošlje v Jopo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 9, 'A drugi dan, ko so ti bili na potu in so se mestu bližali, gre Peter na streho molit, okoli šeste ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 10, 'Postane pa lačen in hoče kaj zaužiti; ko pa pripravljajo, se zamakne');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 11, 'in ugleda nebo odprto in da prihaja navzdol nekaka posoda kakor velik prt, in se za četvere vogle spušča na zemljo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 12, 'v njej so bili raznovrstni četveronožci in zveri in golazen zemlje in ptice nebeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 13, 'In veli mu glas: Vstani, Peter, kolji in jej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 14, 'Peter pa reče: Nikakor ne, Gospod, kajti nikoli še nisem jedel kaj nagnusnega ali nečistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 15, 'In glas mu zopet v drugič veli: Kar je Bog očistil, ne imej ti za nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 16, 'To pa se je zgodilo trikrat; in takoj je bila posoda vzeta gori v nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 17, 'Ko pa je Peter sam pri sebi preudarjal, kaj bi neki pomenila ta prikazen, ki jo je videl, glej, možje, ki jih je bil poslal Kornelij, so izprašali hišo Simonovo in so stali pred vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 18, 'In pokličejo ter vprašajo, če Simon, s priimkom Peter, tu gostuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 19, 'Medtem pa, ko Peter še premišljuje o prikazni, mu veli Duh: Glej, trije možje te iščejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 20, 'Vstani torej, stopi doli in pojdi ž njimi brez pomišljevanja; zakaj jaz sem jih poslal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 21, 'In Peter gre doli k možem in jim reče: Glejte, jaz sem, ki ga iščete. Kaj je vzrok, da ste prišli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 22, 'Oni pa reko: Kornelij stotnik, mož pravičen in bogaboječ, ki je na dobrem glasu pri vsem ljudstvu judovskem, je prejel povelje od svetega angela, naj te pokliče v hišo svojo, da sliši besede od tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 23, 'Pokliče jih torej noter in vzame pod streho. A drugi dan vstane in odide ž njimi, in nekaj bratov iz Jope gre ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 24, 'In drugega dne pridejo v Cezarejo. A Kornelij jih je pričakoval, ko je bil sklical sorodnike svoje in bližnje prijatelje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 25, 'In zgodi se, ko gre Peter noter, da mu pride Kornelij naproti in mu pade k nogam ter ga moli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 26, 'Peter pa ga vzdigne, rekoč: Vstani! Tudi jaz sem človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 27, 'In razgovarjaje se ž njim, stopi noter in jih najde veliko zbranih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 28, 'in jim reče: Vi veste, da ni dovoljeno Judu, družiti se ali hoditi k ljudem drugega naroda; a meni je Bog pokazal, naj ne imenujem nikogar nagnusnega ali nečistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 29, 'Zato sem tudi brez ugovora prišel, ko sem bil poklican. Vprašam torej, iz katerega vzroka ste poslali pome?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 30, 'In Kornelij reče: Pred štirimi dnevi do te ure sem molil ob devetih v hiši svoji; in glej, mož se postavi pred menoj v svetlem oblačilu in veli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 31, 'Kornelij, uslišana je molitev tvoja in miloščine tvoje so v spominu pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 32, 'Pošlji torej v Jopo in pokliči Simona s priimkom Peter; on gostuje v hiši Simona strojarja pri morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 33, 'Zato sem precej poslal k tebi, in ti si prav storil, da si prišel. Sedaj torej smo vsi mi tu pred obličjem Božjim, da slišimo vse, kar ti je ukazano od Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 34, 'Tedaj odpre Peter usta in reče: V resnici spoznavam, da Bog ne gleda na lice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 35, 'temuč v vsakem narodu mu je prijeten, kdor se ga boji in dela pravično;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 36, 'po besedi, ki jo je poslal sinovom Izraelovim, oznanjujoč blagovestje o miru po Jezusu Kristusu – ta je vsem Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 37, 'Vi veste, kaj se je godilo po Judeji, počenši od Galileje, po krstu, ki ga je oznanjeval Janez,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 38, 'veste o Jezusu Kristusu iz Nazareta, kako ga je pomazilil Bog s svetim Duhom in z močjo; ki je hodil okrog, deleč dobrote in ozdravljajoč vse, ki so bili obvladani od hudiča, ker je bil Bog ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 39, 'In mi smo priče vsemu, kar je storil v deželi Judov in v Jeruzalemu; ki so ga tudi na les obesili in umorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 40, 'Tega je Bog obudil tretji dan in dal, da so ga videli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 41, 'ne vse ljudstvo, nego priče, poprej izvoljene od Boga, mi, ki smo ž njim jedli in pili, potem ko je bil vstal iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 42, 'In on nam je ukazal, naj propovedujemo ljudstvu in pričamo, da je on od Boga postavljeni sodnik živih in mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 43, 'Temu pričajo vsi proroki, da prejme po imenu njegovem odpuščenje grehov vsak, kdor veruje vanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 44, 'Ko je Peter še govoril te besede, pride sveti Duh na vse, ki so poslušali besedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 45, 'In zavzemo se verniki iz obreze, ki so bili prišli s Petrom, da se je tudi na pogane izlil dar svetega Duha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 46, 'kajti slišali so jih govoriti jezike in poveličevati Boga. Tedaj izpregovori Peter:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 47, 'Ali more kdo zabraniti vodo, da se ne bi krstili ti, ki so prejeli svetega Duha, kakor tudi mi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 10, 48, 'In ukaže jih krstiti v imenu Jezusa Kristusa. Tedaj ga zaprosijo, naj ostane pri njih nekoliko dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 1, 'Zaslišijo pa apostoli in bratje, ki so bivali po Judeji, da so tudi pogani sprejeli besedo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 2, 'Ko pa je prišel Peter v Jeruzalem, so se prepirali ž njim, ki so bili iz obreze,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 3, 'in so dejali: K možem neobrezanim si šel in si jedel ž njimi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 4, 'Peter pa začne in jim razloži vse po vrsti, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 5, 'Molil sem v mestu Jopi, in zamaknjen vidim prikazen: nekaka posoda, kakor velik prt, gre navzdol in se za štiri vogle spušča z neba, in pride do mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 6, 'In ko pogledam vanjo, opazim in ugledam četveronožce in zver in golazen zemlje in ptice nebeške.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 7, 'Zaslišim pa tudi glas, da mi pravi: Vstani, Peter, kolji in jej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 8, 'In rečem: Nikakor ne, Gospod, kajti nič nagnusnega ali nečistega ni nikoli prišlo v usta moja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 9, 'Odgovori mi pa glas z neba v drugič: Kar je Bog očistil, ne imej ti za nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 10, 'To pa se je zgodilo trikrat, in zopet je bilo vse vzeto v nebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 11, 'In glej, v tem trenutku stoje trije možje pred hišo, v kateri sem bil, poslani k meni iz Cezareje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 12, 'In Duh mi veli, naj grem ž njimi brez pomišljevanja. Šlo je pa z menoj tudi tehle šest bratov, in vstopili smo v hišo moževo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 13, 'In povedal nam je, kako je videl angela v hiši svoji, da je pristopil in rekel: Pošlji v Jopo in pokliči Simona s priimkom Peter,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 14, 'ki ti bo govoril besede, po katerih boš zveličan ti in vsa hiša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 15, 'Ko pa jim začnem govoriti, pride sveti Duh nanje, kakor na nas v začetku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 16, 'Tu sem se spomnil besede Gospodove, kakor je povedal: Janez sicer je krstil z vodo, ali vi boste krščeni s svetim Duhom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 17, 'Ko jim je torej dal Bog prav ta dar kakor tudi nam, ko smo sprejeli vero v Gospoda Jezusa Kristusa: kdo pa sem bil jaz, da bi jaz mogel Bogu zabraniti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 18, 'Ko so pa to slišali, so se pomirili, in slavili so Boga, rekoč: Torej tudi poganom je Bog dal izpokorjenje za življenje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 19, 'Tisti pa, ki so se razkropili po stiski, ki je bila nastala spričo Štefana, so prehodili vse kraje prav do Fenicije in Cipra in Antiohije, nikomur ne oznanjujoč besede Božje, razen samo Judom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 20, 'Bili so pa nekateri izmed njih Ciprani in Cirenci, ki so, prišedši v Antiohijo, govorili tudi Grkom in oznanjevali evangelij Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 21, 'In roka Gospodova je bila ž njimi; in veliko število se jih je, sprejemši vero, izpreobrnilo h Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 22, 'In glas o njih pride do ušes cerkvi, ki je bila v Jeruzalemu: in odpošljejo Barnaba, naj gre v Antiohijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 23, 'Ko pride ta in vidi milost Božjo, se razveseli in opominja vse, naj s stanovitnim srcem vztrajajo pri Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 24, 'Bil je namreč dober mož in poln svetega Duha in vere. In veliko ljudstva se tu pridruži Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 25, 'Barnaba pa odide v Tars iskat Savla; in ko ga je našel, ga pripelje v Antiohijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 26, 'Zgodi se pa, da sta bila celo leto pri zborovanjih v cerkvi in sta učila precejšnjo množico, in da so učenci najprvo v Antiohiji bili imenovani Kristjani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 27, 'V tej dneh so pa prišli iz Jeruzalema proroki v Antiohijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 28, 'In vstane eden izmed njih, po imenu Agab, ter oznani po Duhu, da nastane velika lakota po vsem svetu, ki je tudi prišla za Klavdija cesarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 29, 'Tedaj sklenejo učenci, vsak po zmožnosti svoji, poslati v pomoč bratom, ki so prebivali v Judeji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 11, 30, 'to so tudi storili, poslavši starejšinam po roki Barnabovi in Savlovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 1, 'V ta čas pa dvigne Herod kralj roke, da bi mučil nekatere od cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 2, 'In umori Jakoba, brata Janezovega, z mečem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 3, 'In videč, da je to pogodu Judom, seže dalje in ujame Petra. Bili so pa dnevi presnih kruhov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 4, 'In ko ga ujame, ga posadi v ječo in izroči štirim četvoricam vojakov, naj ga stražijo; in po Veliki noči ga je hotel privesti pred ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 5, 'Petra so torej varovali v ječi; a cerkev je molila zanj k Bogu neprenehoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 6, 'Ko ga pa je hotel Herod privesti pred ljudstvo, tisto noč je spal Peter med dvema vojakoma, vkovan v dvojne verige; varuhi pred vrati pa so stražili ječo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 7, 'In glej, angel Gospodov pristopi, in svetloba se zasveti v izbi; in udari Petra v bok in ga zbudi, rekoč: Vstani hitro! In verige mu padejo z rok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 8, 'Angel mu pa veli: Opaši se in obuj opanke svoje. In storí tako. In mu veli: Ogrni si plašč in pojdi za menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 9, 'In izide in gre za njim; in ni vedel, da je resnično, kar se je godilo po angelu, temuč menil je, da vidi prikazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 10, 'Ko pa preideta mimo prve straže in druge, dospeta do železnih vrat, ki so držala v mesto, in ta se jima odpro sama od sebe; ter stopita ven in preideta eno ulico, in precej se loči angel od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 11, 'In Peter se zave in reče: Sedaj vem zares, da je poslal Gospod angela svojega in me je otel iz roke Herodove in vsega, kar je pričakovalo ljudstvo judovsko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 12, 'In razmislivši to, pride do hiše Marije, matere Janeza s priimkom Marko, kjer jih je bilo veliko zbranih, ki so molili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 13, 'Ko pa potrka Peter na vežna vrata, pristopi deklica, po imenu Roda, poslušat, kdo je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 14, 'In spoznavši glas Petrov, od veselja ne odpre vrat, ampak zbeži noter in sporoči, da stoji Peter pred vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 15, 'Oni ji pa reko: Meša se ti. Ali ona trdi, da je tako. Oni pa pravijo: Njegov angel je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 16, 'A Peter čaka in trka. Ko pa odpro, ga ugledajo in ostrme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 17, 'Namignivši pa z roko, naj molče, jim razloži, kako ga je Gospod izpeljal iz ječe, in reče: Sporočite to Jakobu in bratom. In izide in odrine v drug kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 18, 'Ko se je pa zdanilo, ni bil majhen strah med vojaki, kaj da se je s Petrom zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 19, 'Herod pa, ko ga je zahteval in ga ni našel, izpraša varuhe in jih ukaže odpeljati na smrt. In odide iz Judeje v Cezarejo, ter tu prebiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 20, 'Bil je pa jezen na Tirce in Sidonce; a oni ene misli pridejo k njemu in, pregovorivši zase Blasta, komornika kraljevega, prosijo miru, zato ker je njih dežela dobivala živež iz kraljevine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 21, 'A v določeni dan obleče Herod kraljevsko oblačilo in sede na prestol in jim je govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 22, 'Ljudstvo pa mu je vpilo: Božji glas je to, a ne človeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 23, 'Pri tej priči pa ga udari angel Gospodov, zato ker ni dal slave Bogu: in črvi so se ga lotili, in je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 24, 'A beseda Gospodova je rasla in se razširjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 12, 25, 'Barnaba in Pavel pa sta se vrnila iz Jeruzalema, ko sta bila izvršila službo ljubezni, in sta privedla s seboj Janeza s priimkom Marko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 1, 'Bili so pa v cerkvi, ki je bila v Antiohiji, proroki in učitelji: Barnaba in Simeon, ki se je imenoval Niger, in Lucij Cirenc, in Manahem, ki je bil odgojen s Herodom četrtnikom, in Savel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 2, 'Ko so pa oni opravljali službo Gospodu in se postili, veli sveti Duh: Odločite mi Barnaba in Savla za delo, na katero sem ju poklical.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 3, 'Tedaj so ju, ko so se bili postili in molili in položili nanju roke, odpustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 4, 'Ona pa, poslana od svetega Duha, gresta doli v Selevcijo, in odtod se peljeta po morju na Ciper.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 5, 'In ko prideta v Salamino, oznanjujeta besedo Božjo po shodnicah Judov; imela sta pa tudi Janeza s seboj za strežnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 6, 'In ko sta prešla ves otok do Pafa, najdeta nekega čarovnika, lažnivega proroka, ki je bil Jud in mu je bilo ime Barjezus;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 7, 'in bil je pri namestniku Sergiju Pavlu, pametnem možu. Ta je poklical Barnaba in Pavla in želel slišati besedo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 8, 'Ali ustavljal se jima je Elima, čarovnik (tako namreč se tolmači ime njegovo), prizadevajoč si, da bi namestnika odvrnil od vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 9, 'Savel pa, ki se imenuje tudi Pavel, se napolni svetega Duha ter ga ostro pogleda');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 10, 'in reče: O, poln vsakršne zvijače in vsakršne hudobije, sin hudičev, sovražnik vsake pravičnosti, ali ne boš nehal prevračati ravnih potov Gospodovih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 11, 'In sedaj, glej, roka Gospodova je zoper tebe in oslepiš in ne boš videl solnca do nekaj časa. In pri tej priči se zgrneta nanj mrak in tema, in tipajoč okoli, išče, kdo bi ga za roko vodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 12, 'Tedaj je namestnik, videč, kaj se je zgodilo, sprejel vero in se je čudil nauku Gospodovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 13, 'Ko se pa odpeljejo iz Pafa, pridejo Pavel in njegova sopotnika v Pergo v Pamfiliji. Janez pa se loči od njiju in se vrne v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 14, 'Ona pa gresta iz Perge naprej in prideta v Pisidijsko Antiohijo. In v sobotni dan gresta v shodnico in sedeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 15, 'Po branju postave in prorokov pa pošljejo načelniki shodnice k njima s tem poročilom: Moža in brata, če imata besedo opomina in tolažbe za ljudstvo, govorita!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 16, 'Vstane torej Pavel in pomigne z roko, naj umolknejo, ter reče: Možje Izraelci in kateri se bojite Boga, poslušajte!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 17, 'Bog tega naroda, Izraela, je izvolil očete naše in povišal ljudstvo, ko je prebivalo na tujem v zemlji Egiptovski, in s povzdignjeno roko jih je izpeljal iz nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 18, 'In okoli štirideset let je imel potrpljenje ž njih vedenjem v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 19, 'In pokončavši sedem narodov v zemlji Kanaanski, jim je razdelil v dediščino njih zemljo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 20, 'za kakih štiristo in petdeset let. In potem jim je dajal sodnike do Samuela proroka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 21, 'In odtlej so zahtevali kralja, in dal jim je Bog Savla, sinu Kisovega, moža iz rodu Benjaminovega, štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 22, 'In ko je bil tega zavrgel, jim je za kralja obudil Davida, ki mu je tudi pričujoč rekel: Našel sem Davida, sina Jesejevega, moža po srcu svojem, ki bo delal vso voljo mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 23, 'Iz njegovega semena je Bog po svoji obljubi privedel Izraelu Zveličarja, Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 24, 'potem ko je Janez, nastopivši pred javnim prihodom njegovim, oznanil krst izpokorjenja vsemu ljudstvu Izraelovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 25, 'Ko je pa Janez tek svoj dopolnjeval, je dejal: Nisem tisti, ki menite, da sem. Toda glejte, za menoj prihaja, ki mu nisem vreden odvezati obuvala z nog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 26, 'Možje in bratje, sinovi rodu Abrahamovega in kateri se med vami boje Boga: nam se je poslala beseda tega zveličanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 27, 'Zakaj prebivalci v Jeruzalemu in njih poglavarji ga niso spoznali in so s svojo sodbo izpolnili govore prorokov, ki se vsako soboto bero;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 28, 'in dasi niso našli nobene krivde za smrt, so vendar prosili Pilata, naj ga umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 29, 'In ko so dovršili vse, kar je bilo pisano o njem, so ga sneli z lesa in položili v grob,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 30, 'A Bog ga je obudil iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 31, 'In prikazoval se je več dni tem, ki so bili ž njim vred prišli iz Galileje v Jeruzalem, ki so zdaj njegove priče pred ljudstvom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 32, 'In mi vam oznanjujemo blagovestje o obljubi, ki je bila dana očetom, da jo je Bog izpolnil nam, njih otrokom, obudivši Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 33, 'kakor je tudi pisano v drugem psalmu: „Sin moj si ti; jaz sem te danes rodil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 34, 'Da ga je pa obudil iz mrtvih, da se ne vrne več v trohnenje, o tem je rekel tako: „Dam vam obljube Davidove, svete in zanesljive“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 35, 'Zato pravi tudi na drugem mestu: „Ne daš, da bi Svetnik tvoj videl trohnenje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 36, 'David namreč, ko je bil ob svojem času poslužil volji Božji, je zaspal in položili so ga k očetom njegovim in je videl trohnenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 37, 'Ta pa, ki ga je Bog obudil, ni videl trohnenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 38, 'Znano vam torej bodi, možje in bratje, da se vam po njem oznanjuje odpuščenje grehov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 39, 'in vsega, česar se niste mogli opravičiti v Mojzesovi postavi, se v njem opraviči vsak, kdor veruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 40, 'Glejte torej, da ne pride na vas, kar je rečeno v prorokih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 41, '„Glejte, zaničevalci, in čudite se in izginite; zakaj jaz delam delo v dneh vaših, delo, ki ga ne boste verovali, če vam kdo natanko pove.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 42, 'Ko sta pa šla iz shodnice, so ju prosili, naj bi jim še drugo soboto govorila te besede.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 43, 'In ko se je zbor razšel, gre veliko Judov in pobožnih pojudencev za Pavlom in Barnabom, ki ž njimi govorita in jih izpodbujata naj vztrajajo v milosti Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 44, 'A drugo soboto se je skoro vse mesto zbralo, da bi slišali besedo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 45, 'Videč pa Judje množice, se napolnijo zavisti in ugovarjajo temu, kar je pravil Pavel, nasprotujoč in preklinjajoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 46, 'In Pavel in Barnaba srčno rečeta: Vam se je morala najprej govoriti beseda Božja; toda ker jo zametujete in se sami za nevredne štejete večnega življenja, glej, obračava se do poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 47, 'Kajti tako nam je zapovedal Gospod: „Postavil sem te za luč poganom, da bodeš v zveličanje vsem do konca zemlje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 48, 'Ko so pa pogani to slišali, so se veselili in slavili besedo Gospodovo; in sprejeli so vero, kolikor jih je bilo odločenih za večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 49, 'Beseda Gospodova pa se je raznašala po vsej deželi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 50, 'Judje pa naščujejo pobožne in odlične žene in mestne prvake, in provzročijo preganjanje zoper Pavla in Barnaba ter ju izženo iz svojih krajev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 51, 'A ona sta otresla prah z nog svojih nanje, in prišla sta v Ikonijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 13, 52, 'Učenci pa so se napolnjevali veselja in svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 1, 'Zgodi se pa v Ikoniji, da sta skupno šla v judovsko shodnico in sta tako govorila, da je vero sprejela velika množica Judov in Grkov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 2, 'Tisti Judje pa, ki niso verovali, naščujejo in nahujskajo duše poganov zoper brate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 3, 'Ostala sta tam torej dosti časa, srčno govoreč v Gospodu, ki je pričeval za besedo milosti svoje in dajal, da so se znamenja in čudeži godili po njunih rokah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 4, 'Mestna množica se pa razdeli, in eni so bili za Jude, drugi pa za apostola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 5, 'Ko so se pa vzdignili pogani in Judje s poglavarji svojimi, da bi ju sramotili in kamenali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 6, 'zvesta za to in pobegneta v likaonski mesti Listro in Derbo in v okolico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 7, 'in tu sta oznanjevala evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 8, 'In v Listri je sedel neki mož, brez moči v nogah, hrom od materinega telesa, ki ni nikoli hodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 9, 'Ta posluša Pavla, ko govori; on pa vpre oči vanj in videč, da ima vero, da ozdravi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 10, 'reče z močnim glasom: Stopi na noge svoje pokonci! In poskoči in začne hoditi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 11, 'Ko pa vidi ljudstvo, kar je Pavel storil, povzdignejo glas in kličejo likaonski: Bogova sta v človeški podobi prišla doli k nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 12, 'In imenovali so Barnaba Jupitra, a Pavla Merkurja, ker je bil on prvi govornik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 13, 'In duhovnik Jupitra, ki je imel tempelj pred mestom, pripelje juncev in prinese vencev k vratom ter jima hoče z ljudstvom darovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 14, 'Ko pa to zaslišita apostola, Pavel in Barnaba, si raztrgata oblačila in skočita med ljudstvo, kričeč');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 15, 'in govoreč: Možje! kaj to delate? Tudi midva sva človeka, z vami enake narave, in vam oznanjujeva blagovestje, da se od teh ničevih reči obrnete k živemu Bogu, ki je ustvaril nebo in zemljo in morje in vse, kar je v njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 16, 'ki je v preteklih časih pustil vse narode, da so hodili po svojih potih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 17, 'Vendar pa sebe ni pustil brez pričevanja s tem, da je delil dobrote, dajal vam z neba dež in rodovitne čase in napolnjeval srca vaša z jedjo in veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 18, 'In tako govoreč, sta le s težavo ustavila ljudstvo, da jima ni darovalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 19, 'Pride pa tja nekaj Judov iz Antiohije in Ikonije, ki pregovore ljudstvo, da kamenajo Pavla in ga izvlečejo iz mesta, misleč, da je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 20, 'Ko pa ga učenci obstopijo, vstane in pride v mesto. In drugi dan odide z Barnabom v Derbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 21, 'In ko sta oznanila evangelij temu mestu in sta pridobila dosti učencev, sta se vrnila v Listro in Ikonijo in Antiohijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 22, 'potrjujoč duše učencev in jih opominjajoč, da naj vztrajajo v veri in da nam je treba po mnogih stiskah priti v kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 23, 'In postavita jim starejšine v vsaki cerkvi in jih v molitvi in s postom priporočita Gospodu, ki so bili vanj sprejeli vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 24, 'In prehodita Pisidijo in prideta v Pamfilijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 25, 'in ko sta govorila besedo v Pergi, gresta doli v Atalijo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 26, 'in odtod se odpeljeta po morju v Antiohijo, odkoder sta bila izročena milosti Božji na delo, ki sta ga bila izvršila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 27, 'Ko pa dojdeta tja in zbereta cerkev, sporočita, koliko reči je Bog ž njima storil in da je odprl poganom vrata vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 14, 28, 'In prebila sta tu ne malo časa z učenci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 1, 'In pridejo nekateri iz Judeje in uče brate: Če se ne obrežete po šegi Mojzesovi, se ne morete zveličati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 2, 'Ko je torej nastal razpor in sta se Pavel in Barnaba nemalo prepirala ž njimi, sklenejo, da naj gredo Pavel in Barnaba in nekateri drugi izmed njih gori k apostolom in starejšinam v Jeruzalem zaradi tega vprašanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 3, 'Ko jih je torej cerkev spremila, so šli skozi Fenicijo in Samarijo, pripovedujoč izpreobrnjenje poganov, in so s tem napravljali veliko radost vsem bratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 4, 'Ko so pa dospeli v Jeruzalem, so jih ljubeznivo sprejeli cerkev in apostoli in starejšine, in sporočili so, koliko reči je Bog ž njimi storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 5, 'Ali vstane jih nekaj od ločine farizejev, ki so bili vero sprejeli, in reko: Obrezovati se morajo, in naročiti se mora, naj izpolnjujejo postavo Mojzesovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 6, 'In apostoli in starejšine se zbero, da presodijo to reč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 7, 'Ko so se pa že mnogo prepirali, vstane Peter in jim reče: Možje in bratje! Vi veste, da je od prvih dni Bog med vami izbral, da bi po mojih ustih slišali pogani besedo evangelija in sprejeli vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 8, 'In Bog, ki pozna srca, je izpričal zanje, davši jim svetega Duha, kakor tudi nam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 9, 'in nobenega razločka ni postavil med nami in njimi, ko je po veri očistil njih srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 10, 'Sedaj torej, kaj izkušate Boga, da nakladate učencem jarem na vrat, ki ga ne očetje naši, ne mi nismo mogli prenašati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 11, 'Temuč verujemo, da se po milosti Gospoda Jezusa Kristusa zveličamo prav tako, kakor tudi oni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 12, 'Vsa množica pa umolkne; in poslušajo Barnaba in Pavla, ki pripovedujeta, kolika znamenja in čudeže je Bog storil po njiju med pogani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 13, 'Ko sta pa umolknila, izpregovori Jakob in reče: Možje in bratje, čujte me!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 14, 'Simon je povedal, kako je Bog najprvo obiskal pogane, da bi izmed njih prejel ljudstvo imenu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 15, 'In s tem se ujemajo besede prorokov, kakor je pisano:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 16, '„Potem se vrnem in zopet zgradim dom Davidov, ki je padel: in razvaline njegove zopet sezidam in ga postavim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 17, 'da ljudje, ki ostanejo, poiščejo Gospoda in vsi pogani, ki se je nad njimi klicalo ime moje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 18, 'pravi Gospod, ki to, od vekomaj znano, izvršuje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 19, 'Zato sodim jaz, naj se ne nadlegujejo ti, ki se izmed poganov izpreobrnejo k Bogu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 20, 'ali naj se jim piše, da naj se zdržujejo ognušenja z maliki in nečistosti in zadavljenega in krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 21, 'Kajti Mojzes jih ima od starodavnih časov dosti po vseh mestih, ki ga oznanjujejo, ko se vsako soboto njegova postava čita po shodnicah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 22, 'Tedaj so apostoli in starejšine z vso cerkvijo sklenili izvoliti može izmed sebe in poslati v Antiohijo s Pavlom in Barnabom: Juda, s priimkom Barsaba, in Sila, ki sta bila voditelja med brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 23, 'In poslali so po njih to pismo: apostoli in starejšine in bratje pozdravljajo brate izmed poganov, ki so po Antiohiji in Siriji in Ciliciji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 24, 'Slišali smo, da so nekateri izmed nas izšli in so vas zbegali s svojim govorjenjem in zmotili duše vaše, katerim nismo ničesar naročili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 25, 'zato smo sklenili, ene misli zbrani, izvoliti može in poslati k vam z ljubljenima našima Barnabom in Pavlom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 26, 'človekoma, ki sta žrtvovala življenje svoje za ime Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 27, 'Poslali smo torej Juda in Sila, ki bosta tudi sama ustno isto povedala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 28, 'Vzvidelo se je namreč svetemu Duhu in nam, nobenega bremena vam več ne nakladati, razen teh potrebnih reči:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 29, 'da se zdržujte malikom darovanega in krvi in zadavljenega in nečistosti. Če se boste tega varovali, boste prav delali. Zdravi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 30, 'Poslanci so torej, ko so jih bili odpravili, prišli v Antiohijo; pa zbero množico in izroče pismo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 31, 'Ko so ga pa prebrali, so se razveselili te tolažbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 32, 'A Juda in Sila, ki sta bila tudi proroka, sta tolažila in utrjevala brate z mnogimi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 33, 'In ko sta nekaj časa tu prebila, so ju odpustili bratje v miru k tem, ki so ju bili poslali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 34, '§ [Sklenil je pa Sila tam ostati.]');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 35, 'A Pavel in Barnaba sta se pomudila v Antiohiji in sta učila in oznanjevala besedo Gospodovo še z mnogimi drugimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 36, 'Čez nekoliko dni pa reče Pavel Barnabu: Vrniva se in obiščiva brate po vseh mestih, ki sva v njih oznanila besedo Gospodovo, da vidiva, kako se jim godi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 37, 'Barnaba je pa hotel, da bi vzela s seboj tudi Janeza, ki se je imenoval Marko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 38, 'Pavlu pa se je bolje zdelo, da tega, ki se je ločil od njiju v Pamfiliji in ni šel ž njima na delo, ne bi jemala s seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 39, 'In nastane razpor, tako da se ločita drug od drugega, in Barnaba vzame Marka in se odpelje po morju na Ciper.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 40, 'A Pavel si izbere Sila in odpotuje, priporočen milosti Božji od bratov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 15, 41, 'In hodil je po Siriji in Ciliciji in je utrjeval cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 1, 'Pride pa v Derbo in Listro. In glej, neki učenec je bil tu, po imenu Timotej, sin žene Judinje, ki je verovala, očeta pa Grka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 2, 'za njega so dobro pričali bratje, ki so bili v Listri in Ikoniji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 3, 'Tega je hotel Pavel, da bi šel ž njim; in ga vzame in obreže zavoljo Judov, ki so bili v tistih krajih, kajti vsi so vedeli za očeta njegovega, da je bil Grk.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 4, 'Ko so pa hodili po mestih, so izročali bratom naredbe, ki so jih sklenili apostoli in starejšine v Jeruzalemu, naj se po njih ravnajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 5, 'Tako so se cerkve utrjevale v veri in njih število se je množilo vsak dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 6, 'In šli so skozi Frigijsko in Galacijsko deželo, ko jim je zabranil sveti Duh govoriti besedo Božjo v Aziji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 7, 'in ko so prišli proti Miziji, so poskušali iti v Bitinijo: ali Duh Jezusov jim ni pustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 8, 'A ko so prešli mimo Mizije, pridejo doli v Troado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 9, 'In prikaže se Pavlu po noči prikazen. Neki mož, Macedonec, je stal, proseč ga in govoreč: Pridi v Macedonijo in pomagaj nam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 10, 'Ko je pa to prikazen videl, smo si prizadeli precej, da gremo naprej v Macedonijo, prepričani, da nas je Gospod poklical, da jim oznanimo evangelij.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 11, 'Ko smo se torej odpeljali iz Troade, smo prišli naravnost v Samotracijo, in drugi dan v Neapol,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 12, 'in odtod v Filipe, ki so prvo mesto te strani Macedonije in rimska naselbina. V tem mestu pa smo bivali nekoliko dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 13, 'A v sobotni dan smo šli ven za vrata k reki, kjer smo menili, da bo kraj molitve, in smo sedli, in govorili ženam, ki so se bile zbrale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 14, 'In neka žena, po imenu Lidija, prodajalka škrlata, iz mesta Tiatir, ki je častila Boga, je nas poslušala; tej je Gospod odprl srce, da je pazila na to, kar je Pavel govoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 15, 'Ko pa je bila krščena in njena družina, nas je prosila, rekoč: Če ste sodili, da sem verna Gospodu, pridite v hišo mojo in tu ostanite; in nas je primorala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 16, 'Zgodi se pa, ko smo šli na molitveni kraj, nas sreča neka deklica, ki je imela vedeževalnega duha in je veliko dobička donašala gospodarjem svojim z vedeževanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 17, 'Ta je šla za Pavlom in za nami in vpila, govoreč: Ti ljudje so Boga Najvišjega služabniki, ki vam oznanjujejo pot zveličanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 18, 'A to je delala mnogo dni. Pavla je pa bolelo, in obrne se in veli temu duhu: Ukazujem ti po imenu Jezusa Kristusa, da odidi iz nje. In izšel je še tisto uro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 19, 'Ko pa vidijo njeni gospodarji, da jim je minilo upanje do dobička, primejo Pavla in Sila in ju vlečejo na trg k poglavarjem mesta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 20, 'ter ju pripeljejo k uradnikom in reko: Ti ljudje motijo naše mesto, ker so Judje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 21, 'in oznanjujejo šege, ki jih mi ne smemo sprejemati, ne izpolnjevati, ker smo Rimljani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 22, 'In ljudstvo tudi vstane zoper njiju; in uradniki jima raztrgajo oblačila ter ju vele šibati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 23, 'In ko so ju zelo pretepli, ju vržejo v ječo, naročivši ječarju, naj ju skrbno varuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 24, 'Prejemši tako zapoved, ju on vrže v notranjo ječo in jima dene noge v klado.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 25, 'Opolnoči pa sta Pavel in Sila molila in pela hvalnice Bogu, jetniki pa so ju poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 26, 'Kar nastane velik potres, tako da se zgane temelj jetnišnice; in pri tej priči se vsa vrata odpro in vsem jetnikom odpade železje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 27, 'Ko se pa ječar prebudi in vidi vrata ječe odprta, izdere meč in se hoče umoriti, misleč, da so jetniki pobegnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 28, 'Pavel pa zakliče z močnim glasom, rekoč: Ne stori si nič žalega, saj smo vsi tu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 29, 'On pa si veli luč, skoči noter in pade drhteč Pavlu in Silu pred noge,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 30, 'in izpelje ju ven in reče: Gospoda, kaj mi je treba storiti, da se zveličam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 31, 'Ona pa rečeta: Veruj v Gospoda Jezusa, in zveličal se boš ti in hiša tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 32, 'In govorita mu besedo Gospodovo in vsem, ki so bili v hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 33, 'In vzame ju s seboj še tisto nočno uro ter jima izmije rane, in pri tej priči je bil krščen on in vsi njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 34, 'In pelje ju gori v hišo svojo in jima pripravi večerjo in se raduje, ker je postal z vso hišo svojo veren Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 35, 'Ko se je pa zdanilo, pošljejo uradniki biriče, naj reko: Izpusti tista moža:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 36, 'Ječar pa sporoči te besede Pavlu: Poslali so uradniki, naj vaju izpustim. Sedaj torej odidita in potujta v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 37, 'Ali Pavel jim reče: Šibali so naju, ki sva Rimljana, očitno brez pravde in sodbe ter vrgli v ječo, in sedaj naju hočejo skrivaj izgnati? Ne tako, marveč sami naj pridejo in naju izpeljejo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 38, 'Biriči pa sporoče te besede uradnikom. A oni se preplašijo, ko slišijo, da sta Rimljana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 39, 'ter pridejo in jima prijazno prigovarjajo; in ju izpeljajo in prosijo, naj zapustita mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 16, 40, 'Ko sta pa izšla iz ječe, stopita k Lidiji; in tu vidita brate ter jih potolažita in gresta naprej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 1, 'In šla sta skozi Amfipol in Apolonijo in prišla v Solun, kjer je bila shodnica Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 2, 'In Pavel gre po svoji navadi k njim in se razgovarja ž njimi tri sobote na podlagi pisem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 3, 'razodevajoč in dokazujoč, da je moral Kristus trpeti in vstati iz mrtvih, in da ‚ta Jezus, ki ga vam jaz oznanjujem, je Kristus‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 4, 'In nekateri izmed njih so se dali prepričati in so se pridružili Pavlu in Sili, tudi pobožnih Grkov velika množica in imenitnih žen ne malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 5, 'Ali Jude je zavist prevzela, in ko so privzeli nekaj hudobnih mož izmed druhali in zbrali trumo, so napravili vstajo v mestu. In obstopijo hišo Jazonovo in ju iščejo, da bi ju pripeljali pred ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 6, 'Ko pa ju niso našli, privlečejo Jazona in nekatere brate pred mestne poglavarje, vpijoč: Ti, ki ves svet narobe prevračajo, ti so tudi sem prišli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 7, 'in Jazon jih je sprejel; in ti vsi delajo zoper cesarjeve postave, govoreč, da je drug kralj, namreč Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 8, 'Tako vznemirijo ljudstvo in mestne poglavarje, ki so to poslušali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 9, 'A ko so prejeli zadoščenje od Jazona in drugih, so jih pustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 10, 'Bratje pa naglo po noči odpravijo Pavla in Sila v Berejo. Ko prideta tja, gresta v shodnico Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 11, 'Ti so bili blažji od Solunčanov; ti so sprejeli besedo z vsem poželenjem in so vsak dan preiskovali pisma, če je temu tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 12, 'In tako jih je veliko izmed njih sprejelo vero, tudi odličnih grških žen in mož ne malo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 13, 'Ko so pa Judje v Solunu zvedeli, da oznanjuje Pavel besedo Božjo tudi v Bereji, pridejo tudi tja, da nahujskajo in vznemirijo ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 14, 'Ali bratje so tedaj Pavla naglo odpravili, da je šel v primorje; a Sila in Timotej sta ostala tam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 15, 'Ti pa, ki so Pavla spremljali, so ga pripeljali do Aten; in ko so prejeli sporočilo od Sila in Timoteja, naj bi kar najhitreje prišla k njemu, so se vrnili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 16, 'Ko ju je pa Pavel čakal v Atenah, se togoti duh njegov v njem, ko vidi, da je mesto polno malikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 17, 'Razgovarja se torej v shodnici z Judi in pobožnimi ter na trgu vsak dan s tistimi, na katere se je nameril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 18, 'A tudi nekateri izmed epikurejskih in stoiških modrijanov so se prepirali ž njim; in nekateri so govorili: Kaj hoče ta kvasač povedati? A drugi: Zdi se, da je oznanjevalec tujih bogov - ker jim je oznanjeval evangelij o Jezusu in vstajenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 19, 'In ga vzemo in odpeljejo na Areopag, govoreč: Moremo li zvedeti, kakšen je ta novi nauk, ki ga ti oznanjuješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 20, 'Kajti nekaj čudnega nam prinašaš v ušesa; zato hočemo zvedeti, kaj če to biti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 21, 'Vsi Atenčani in tujci, ki so tam bivali, niso pa za nič drugega tolikanj marali, nego pripovedovati ali poslušati kaj novega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 22, 'Ustopivši se pa sredi Areopaga, reče Pavel: Možje Atenčani, po vsem vidim, da ste nekako prebogaboječi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 23, 'Ko sem se namreč izprehajal po mestu in ogledoval svetišča vaša, sem našel tudi oltar, ki je na njem bilo napisano: Nepoznanemu Bogu. Kar torej častite, dasi tega ne poznate, to vam jaz oznanjujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 24, 'Bog, ki je ustvaril svet in vse, kar je na njem, on, ki je neba in zemlje Gospodar, ne prebiva v svetiščih, ki so z rokami narejena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 25, 'tudi se mu ne streže s človeškimi rokami, kakor da bi česa potreboval, ko sam daje vsem življenje in dihanje in vse;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 26, 'in je naredil, da iz ene krvi ves rod človeški prebiva po vsem licu zemlje, določivši odmenjene čase in meje njih prebivanju:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 27, 'da bi iskali Boga, ne bi ga li kako otipali in našli, ko vendar ni daleč nobenemu od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 28, 'Zakaj v njem živimo in se gibljemo in smo, kakor so tudi nekateri vaših pesnikov rekli: Saj tudi rodu njegovega smo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 29, 'Ker smo torej Božjega rodu, ne smemo misliti, da je božanstvo podobno zlatu ali srebru ali kamenu, obdelanemu po umetelnosti in iznajdljivosti človeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 30, 'Bog torej ukazuje sedaj, ne ozirajoč se na čase nevednosti, vsem ljudem povsod, naj se izpokore;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 31, 'zato ker je določil dan, ob katerem bo sodil vesoljni svet v pravičnosti po možu, ki ga je za to odločil, podavši vero vsem s tem, da ga je obudil iz mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 32, 'Ko so pa slišali o vstajenju mrtvih, so se nekateri posmehovali, a drugi so rekli: O tem te bomo v drugič slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 33, 'In tako je Pavel odšel izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 17, 34, 'A nekateri možje so se mu pridružili in sprejeli vero; med njimi je bil tudi Dionizij Areopagit in žena po imenu Damara, in drugi ž njima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 1, 'Potem se je Pavel ločil iz Aten in prišel v Korint.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 2, 'In tu je našel nekega Juda, po imenu Akvila, iz Ponta po rodu, ki je bil nedavno prišel s Priscilo, ženo svojo, iz Italije zato, ker je bil zapovedal Klavdij vsem Judom, naj odidejo iz Rima. In šel je k njima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 3, 'in ker je bil istega rokodelstva, je ostal pri njiju, in delali so skupaj; bila sta namreč po rokodelstvu delavca šatorov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 4, 'In razgovarjal se je v shodnici vsako soboto in prepričeval Jude in Grke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 5, 'Ko sta pa prišla iz Macedonije Sila in Timotej, je bil Pavel ves navdušen za besedo Božjo in je pričeval Judom, da Jezus je Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 6, 'Ko so pa oni nasprotovali in preklinjali, si otrese oblačila in jim reče: Kri vaša vam pridi na glavo. Čist jaz odslej pojdem k poganom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 7, 'In gre odtod in pride v hišo nekega Titija Justa po imenu, ki je častil Boga in čigar hiša je bila tik shodnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 8, 'Krisp pa, načelnik shodnice, je postal veren Gospodu z vso hišo svojo; in veliko Korinčanov, ki so poslušali, je verovalo in se dalo krstiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 9, 'Reče pa Gospod Pavlu po noči v prikazni: Ne boj se, temuč govori in ne molči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 10, 'zakaj jaz sem s teboj, in nihče te ne napade, da ti stori kaj hudega; kajti imam veliko ljudstvo v tem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 11, 'In prebil je tu eno leto in šest mesecev, učeč besedo Božjo med njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 12, 'Ko pa je bil Galion namestnik v Ahaji, so Judje ene misli napadli Pavla; in pripeljejo ga na sodišče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 13, 'govoreč: Ta nagovarja ljudi, naj časte Boga zoper postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 14, 'Ko pa hoče Pavel odpreti usta, reče Galion Judom: Ko bi bila kaka krivica ali hudobno dejanje, o Judje, bi vas poslušal po dolžnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 15, 'ker so pa vprašanja za nauk in za imena in za vašo postavo, glejte sami; jaz nočem biti sodnik v teh rečeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 16, 'In odžene jih od sodišča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 17, 'Tedaj zgrabijo vsi Sostena, načelnika shodnice, in ga bijejo pred sodiščem; ali Galion se ni nič zmenil za to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 18, 'Pavel pa, ko je še dosti dni ostal tu, se poslovi z brati in se odpelje po morju v Sirijo in ž njim Priscila in Akvila, ko si je ostrigel glavo v Kenhrejah: imel je namreč obljubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 19, 'Pridejo pa v Efez, in onadva ostaneta tam. A on gre v shodnico in se razgovarja z Judi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 20, 'Ko ga pa prosijo, naj ostane dalje časa ž njimi, ne privoli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 21, 'ampak poslovi se ž njimi, rekoč: Vrnem se zopet k vam, če Bog hoče. In odpelje se iz Efeza,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 22, 'in ko pristane v Cezareji, gre gori in pozdravi cerkev; potem gre doli v Antiohijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 23, 'In ko se nekaj časa pomudi tu, odide in prehodi zapored Galacijsko stran in Frigijo, utrjujoč vse učence.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 24, 'Prišel pa je v Efez neki Jud, po imenu Apolo, Aleksandrijan po rodu, zgovoren mož; in bil je jako zveden v pismih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 25, 'Ta je bil poučen v potu Gospodovem, in goreč v duhu je govoril in učil pridno to, kar zadeva Jezusa, dasi je poznal samo krst Janezov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 26, 'In ta začne srčno oznanjevati v shodnici. Ko sta ga pa Akvila in Priscila slišala, ga vzameta k sebi in mu še natančneje razložita pot Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 27, 'Ko pa je hotel iti naprej v Ahajo, so ga izpodbujali bratje in pisali tamošnjim učencem, naj ga sprejmo. In ko je prišel tja, je po milosti veliko pripomogel tistim, ki so bili sprejeli vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 18, 28, 'Kajti krepko je zavračeval Jude pred ljudstvom, dokazujoč iz pisem, da Jezus je Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 1, 'Zgodi se pa, ko je bil Apolo v Korintu, da pride Pavel, prehodivši gorenje strani, v Efez in tu najde nekaj učencev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 2, 'in jim reče: Ali ste prejeli svetega Duha, ko ste postali verni? Oni mu pa reko: Saj še slišali nismo, da je sveti Duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 3, 'In reče: Na kaj torej ste bili krščeni? Oni pa reko: Na krst Janezov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 4, 'Pavel pa reče: Janez je krstil s krstom izpokorjenja, govoreč ljudstvu, da naj verujejo v tega, ki prihaja za njim, to je Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 5, 'Ko so pa to slišali, se dado krstiti v ime Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 6, 'In ko poklada Pavel nanje roke, pride sveti Duh nanje, in govore jezike in prorokujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 7, 'Bilo jih je pa vseh skup kakih dvanajst mož.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 8, 'In ko pride v shodnico, srčno oznanjuje in govori tri mesece in prepričava o kraljestvu Božjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 9, 'Ko so se pa nekateri zakrknili in niso hoteli biti pokorni, hudo govoreč o potu Gospodovem pred množico, odstopi od njih in odloči učence, ter govori vsak dan v Tiranovi šoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 10, 'To pa je trpelo dve leti, tako da so slišali besedo Gospodovo vsi, ki so prebivali v Aziji, Judje in Grki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 11, 'In ne male čudeže je delal Bog po rokah Pavlovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 12, 'tako da so na bolnike pokladali celo potne prte ali predpasnike od života njegovega, in bolezni so jih puščale in hudobni duhovi so izhajali iz njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 13, 'Poskusili so pa tudi nekateri izmed Judov, ki so okrog hodili in hudiče rotili, klicati ime Gospoda Jezusa na tiste, ki so imeli hudobne duhove, govoreč: Zaklinjam vas pri Jezusu, ki ga Pavel oznanjuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 14, 'Bilo je pa sedem sinov nekega žida Skeve, višjega duhovnika, ki so to delali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 15, 'Odgovori pa hudobni duh in reče: Jezusa poznam in za Pavla vem; vi pa, kdo ste?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 16, 'In skočivši nanje, premaga človek, v katerem je bil duh hudobni, dva izmed njih in ju zdela tako, da naga in ranjena ubežita iz tiste hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 17, 'To pa je prišlo na znanje vsem, Judom in Grkom, ki so prebivali v Efezu; in strah jih je obšel vse, in ime Gospoda Jezusa se je poveličevalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 18, 'Mnogi tudi teh, ki so bili sprejeli vero, so prihajali ter priznavali in razodevali dela svoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 19, 'A mnogi tistih, ki so uganjali vraže, so znesli knjige in jih sežgali vpričo vseh; in ko so sešteli njih ceno, so našli, da so veljale petdeset tisoč srebrnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 20, 'Tako je beseda Gospodova rasla z močjo in se utrjevala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 21, 'A ko se je to dopolnilo, se nameni Pavel v duhu, da pojde, prehodivši Macedonijo in Ahajo, v Jeruzalem in reče: Potem, ko bom tam, moram videti tudi Rim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 22, 'Pošlje pa v Macedonijo dva od tistih, ki so mu služili, Timoteja in Erasta; sam ostane še nekaj časa v Aziji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 23, 'Nastane pa v ta čas ne majhen hrup zavoljo pota Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 24, 'Neki srebrar namreč, Demetrij po imenu, ki je delal srebrne tempeljčke Diani, je dajal umetnikom ne malo dobička.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 25, 'In skliče te in druge take delavce in reče: Možje, veste, da imamo od tega dela blagostanje svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 26, 'in vidite in slišite, da ne samo v Efezu, temuč skoro po vsej Aziji je ta Pavel veliko ljudstva pregovoril in odvrnil, govoreč, da to niso bogovi, ki so z rokami narejeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 27, 'Ni pa samo nevarnost, da pride to delo naše na nič, ampak tudi, da se bo za nič štel velike boginje Diane tempelj in se skrajša veličastvo te, ki jo časti vsa Azija in vesoljni svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 28, 'Ko so pa to slišali, se napolnijo jeze in zakriče, rekoč: Velika je Diana Efežanov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 29, 'In po vsem mestu zavlada zmešnjava; in zaženo se enodušno na gledališče in zgrabijo s seboj Gaja in Aristarha, Macedonca, sopotovalca Pavlova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 30, 'Ko je pa Pavel hotel iti med ljudstvo, ga niso učenci pustili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 31, 'Pa tudi nekateri azijskih poglavarjev, ki so mu bili prijatelji, so k njemu poslali in ga prosili, naj ne gre v gledališče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 32, 'Vpili so pa eni to, drugi drugo; kajti bil je zbor poln zmešnjave, in največ jih je bilo, ki niso vedeli, zakaj so se sešli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 33, 'A nekateri so izvlekli Aleksandra izmed množice, ko so ga tudi Judje naprej potiskali. Aleksander pa zamahne z roko, naj umolknejo, in hoče ljudstvu govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 34, 'Ko pa spoznajo, da je Jud, vzdignejo vsi en glas in vpijejo kaki dve uri: Velika je Diana Efežanov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 35, 'Mestni pisar pa, ko je množico pomiril, reče: Možje Efežani! kateri človek je, ki bi ne vedel, da mesto Efežanov je varuh svetišču velike Diane in od Jupitra padle podobe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 36, 'Ker se torej temu ne more ugovarjati, je treba, da se umirite in se v ničemer ne prenaglite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 37, 'Kajti pripeljali ste sem ta moža, ki nista ne svetišča oropala, ne boginje naše preklinjala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 38, 'Če imajo pa Demetrij in umetniki, ki so ž njim, tožbo zoper koga, sodišča so in namestniki so; naj tožijo drug drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 39, 'Če pa zahtevate kaj drugega, se to obravna v postavnem zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 40, 'Kajti v nevarnosti smo tudi, da bomo zatoženi zavoljo današnje vstaje, in nobenega nimamo vzroka, s katerim bi mogli dati odgovor za ta hrupni shod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 19, 41, '§ In rekši to, je razpustil zbor.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 1, 'Ko je pa ta hrup nehal, pokliče Pavel učence in jih potolaži, in poslovivši se odide, da potuje v Macedonijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 2, 'In prehodi te strani in opominja učence z mnogimi besedami, in pride v Grško.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 3, 'In prebivši tu tri mesece, sklene vrniti se skozi Macedonijo, ker so ga Judje zalezovali, ko se je hotel po morju odpeljati v Sirijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 4, 'Spremljali pa so ga do Azije: Sopater Pirijev iz Bereje, od Solunčanov pa Aristarh in Sekund, in Gaj iz Derbe in Timotej, od Azijcev pa Tihik in Trofim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 5, 'Ti so bili šli naprej in nas čakali v Troadi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 6, 'A mi smo se po dneh presnih kruhov odpeljali iz Filip, in prišli smo k njim v Troado v petih dneh; tu smo se pomudili sedem dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 7, 'A prvi dan po soboti, ko smo se zbrali, da bi lomili kruh, jim je govoril Pavel, ker je hotel drugi dan odpotovati, in je podaljšal govor svoj do polnoči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 8, 'bilo je pa dosti svetilnic v gornji izbi, kjer smo bili zbrani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 9, 'Sedel je pa neki mladenič, po imenu Evtih, na oknu, in ko je Pavel le še govoril, trdno zaspi; in premagan od spanja, pade s tretjega nadstropja doli, in vzdignejo ga mrtvega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 10, 'Pavel pa gre doli in se skloni nanj ter ga objame in reče: Pomirite se; kajti duša njegova je v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 11, 'Nato gre zopet gori, prelomi kruh in jé, govori ž njimi še mnogo, dokler se ne zdani, in tako odpotuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 12, 'A mladeniča so pripeljali živega, in bili so ne malo potolaženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 13, 'A mi smo že prej stopili na ladjo in se odpeljali v Ason, kjer smo imeli sprejeti Pavla; tako je bil namreč naročil, hoteč sam priti peš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 14, 'Ko se je pa bil v Asonu k nam pridružil in smo ga vzeli na ladjo, smo prišli v Mitileno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 15, 'in odpeljavši se odtod, smo prišli drugi dan Hiju nasproti, in dan pozneje smo pripluli k Samu, in ko smo v Trogiliji prenočili, smo prišli drugi dan v Milet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 16, 'Odločil je bil namreč Pavel, da se bomo peljali mimo Efeza, da se ne bi v Aziji zamudil; kajti hitel je, da bi bil, ako bi mu bilo mogoče, Binkoštni dan v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 17, 'Iz Mileta pa pošlje v Efez in pokliče starejšine cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 18, 'Ko pa pridejo k njemu, jim reče: Vi veste, kako sem od prvega dne, ko sem prišel v Azijo, ves čas bil z vami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 19, 'služeč gospodu z vso ponižnostjo in mnogimi solzami in med izkušnjami, ki so me zadele vsled zalezovanja Judov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 20, 'kako nisem nič koristnega izpustil, da ne bi bil vam oznanil in vas učil očitno in po hišah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 21, 'pričujoč Judom in Grkom izpreobrnjenje k Bogu in vero v Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 22, 'In sedaj, glejte, zvezan v duhu, grem v Jeruzalem, ne vedoč, kaj se mi tam prigodi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 23, 'razen da mi sveti Duh po vseh mestih priča in pravi, da me čakajo vezi in stiske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 24, 'Ali življenja svojega ne štejem vrednega zase niti besede, da le dokončam tek svoj in službo, ki sem jo prejel od Gospoda Jezusa, da popričam evangelij milosti Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 25, 'In sedaj, glejte, jaz vem, da ne boste več videli obličja mojega vi vsi, ki sem med vami hodil, propovedujoč kraljestvo Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 26, 'Zato vam pričujem današnji dan, da sem čist krvi vseh;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 27, 'zakaj ničesar nisem zamolčal, da vam ne bi bil oznanil vse volje Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 28, 'Pazite torej nase in na vso čredo, v kateri vas je sveti Duh postavil za škofe [Škof, da pasete cerkev Božjo, ki si jo je pridobil z lastno krvjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 29, 'Jaz vem, da pridejo po odhodu mojem med vas grabljivi volkovi, ki ne bodo prizanašali čredi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 30, 'in izmed vas samih vstanejo možje, ki bodo govorili popačene nauke, da bi potegnili učence za seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 31, 'Zato čuvajte, spominjajoč se, da tri leta noč in dan nisem nehal s solzami opominjati slehernega iz vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 32, 'In sedaj vas, bratje, priporočam Bogu in besedi milosti njegove, ki more dovršiti vaš napredek in dati delež med vsemi posvečenimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 33, 'Srebra ali zlata ali oblačila nisem od nikogar poželel;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 34, 'sami veste, da so tele roke prislužile, kar je bilo treba meni in tistim, ki so bili z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 35, 'V vsem sem vam dal zgled, da se je treba tako truditi in podpirati slabotne in spominjati se besed Gospoda Jezusa, da je on rekel: Veliko bolje je dati nego vzeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 36, 'In ko je to povedal, poklekne na kolena in moli ž njimi vsemi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 37, 'In velik jok je nastal med vsemi, in oklenivši se vratu Pavlovega, so ga poljubovali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 20, 38, 'žalostni največ zavoljo besede, ki jo je rekel, da ne bodo več videli obličja njegovega. In spremili so ga na ladjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 1, 'Ko smo se pa odtrgali od njih in se odpeljali, smo prišli naravnost v Kon, drugi dan v Rod in odtod v Pataro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 2, 'In ko smo našli ladjo, ki je imela jadrati v Fenicijo, smo stopili nanjo in se peljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 3, 'Ko smo pa ugledali Ciper, smo ga pustili na levi strani in se peljali v Sirijo, in izkrcali smo se v Tiru; tu namreč je imela ladja iztovoriti blago.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 4, 'In ko smo našli učence, smo ostali tu sedem dni; ti so pravili Pavlu po Duhu, naj ne hodi gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 5, 'Ko smo pa te dni dopolnili, smo se odpravili, in spremljali so nas vsi z ženami in otroki ven za mesto; in pokleknivši na bregu, smo molili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 6, 'In ko smo se poslovili drug od drugega, smo stopili na ladjo, a oni so se vrnili domov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 7, 'Mi pa, ko smo vožnjo iz Tira dokončali, smo prišli v Ptolemajdo, in pozdravivši se z brati, smo ostali en dan pri njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 8, 'A drugi dan smo odrinili in prišli v Cezarejo; in šli smo v hišo Filipa evangelista, ki je bil eden izmed sedmerih, in ostali smo pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 9, 'Ta pa je imel štiri hčere device, ki so prorokovale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 10, 'Ko smo se pa več dni mudili, pride iz Judeje neki prorok, po imenu Agab;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 11, 'ko pride ta k nam, vzame pas Pavlov in, zvezavši si roke in noge, reče: To veli sveti Duh: Moža, čigar je ta pas, zvežejo tako Judje v Jeruzalemu in ga izroče poganom v roke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 12, 'Ko smo pa to slišali, smo ga prosili mi in ondišnji, naj ne hodi gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 13, 'Tedaj odgovori Pavel: Kaj delate, da jokate in mi trgate srce? Saj jaz sem pripravljen ne le biti zvezan, ampak tudi umreti v Jeruzalemu za ime Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 14, 'In ko ga nismo mogli pregovoriti, smo umolknili, rekši: Volja Gospodova se zgódi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 15, 'A po teh dneh smo se pripravili in šli gori v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 16, 'Šlo je pa z nami tudi nekaj učencev iz Cezareje, ki so peljali s seboj nekega Mnasona s Cipra, starega učenca, ki smo pri njem imeli gostovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 17, 'Ko smo pa prišli v Jeruzalem, so nas radostno sprejeli bratje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 18, 'A drugi dan je šel Pavel z nami k Jakobu, kjer so se sešli vsi starejšine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 19, 'In ko se je bil ž njimi pozdravil, je pripovedoval vse po vrsti, kaj je storil Bog med pogani po njegovi službi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 20, 'Oni pa, ko so to slišali, so slavili Boga; in njemu reko: Vidiš, brat, koliko tisoč jih je med Judi, ki so sprejeli vero, in vsi so vneti za postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 21, 'Slišali pa so zate, da učiš odstop od Mojzesa vse Jude, ki so med pogani, in praviš, naj ne obrezujejo sinov svojih in se tudi ne ravnajo po starih šegah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 22, 'Kaj je torej storiti? Gotovo [se zbere množica, kajti] zaslišijo, da si prišel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 23, 'To torej stóri, kar ti povemo: So pri nas štirje možje, ki imajo obljubo na sebi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 24, 'te vzemi k sebi in očisti se ž njimi in plačaj zanje, da si ostrižejo glave, in vsi bodo zvedeli, da ni res, kar so o tebi slišali, ampak da tudi sam redno živiš in izpolnjuješ postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 25, 'Glede tistih pa, ki so izmed poganov sprejeli vero, smo sklenili in pisali, da naj se varujejo malikom darovanega in krvi in zadavljenega in nečistosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 26, 'Tedaj vzame k sebi Pavel može, in očistivši se ž njimi drugi dan, gre v tempelj in oznani, kdaj se dopolnijo dnevi očiščevanja, dokler se ni darovala daritev za vsakega od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 27, 'Ko so se pa sedmeri dnevi skoro dokončali, ga ugledajo v templju Judje iz Azije, razdražijo vse ljudstvo ter polože nanj roke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 28, 'kričeč: Možje Izraelci, pomagajte! Ta je tisti človek, ki povsod uči vse zoper naše ljudstvo in postavo in ta kraj, in vrhutega je tudi Grke pripeljal v tempelj in oskrunil ta sveti kraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 29, 'Videli so bili namreč poprej Trofima Efežana ž njim v mestu, in o njem so mislili, da ga je Pavel pripeljal v tempelj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 30, 'In vse mesto se je vzdignilo in ljudstvo je drlo skupaj; in zgrabivši Pavla, so ga vlekli ven iz templja; in precej so zaprli vrata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 31, 'Ko so ga pa že hoteli umoriti, pride glas do tisočnika vojaške trume, da se je vzdignil ves Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 32, 'Ta vzame takoj vojakov in stotnikov in priteče nadnje. Ko pa ugledajo tisočnika in vojake, nehajo bíti Pavla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 33, 'Tedaj se tisočnik približa in ga prime, in veli ga vkleniti v dve verigi, ter vpraša, kdo da je in kaj je storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 34, 'In eni vpijejo to, a drugi drugo med ljudstvom. Ko pa ni mogel nič gotovega zvedeti zavoljo hrupa, ga ukaže odpeljati v grad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 35, 'In ko pride do stopnic, se prigodi, da ga morajo vojaki nesti zavoljo sile druhali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 36, 'kajti šla je za njim množica ljudstva, kričeč: Pogubi ga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 37, 'Ravno pa, ko hočejo Pavla peljati v grad, reče on tisočniku: Ali smem kaj govoriti s teboj? On pa reče: Znaš grški?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 38, 'Nisi li torej tisti Egipčan, ki je pred temi dnevi napravil upor in izpeljal v puščavo štiri tisoč razbojnikov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 39, 'Pavel pa reče: Jaz sem Jud iz Tarsa, meščan ne neznatnega mesta v Ciliciji; prosim pa te, dovoli mi govoriti ljudstvu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 21, 40, 'In ko mu je dovolil, namigne Pavel, stoječ na stopnicah, z roko ljudstvu, naj umolknejo; in ko nastane velika tihota, govori k njim v hebrejskem jeziku takole:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 1, 'Možje, bratje in očetje, poslušajte sedaj moj zagovor proti vam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 2, 'Ko pa slišijo, da jim v hebrejskem jeziku govori, so še bolj tiho. In on reče:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 3, 'Jaz sem mož Jud, rojen v Tarsu v Ciliciji, odgojen pa v tem mestu pri nogah Gamalielovih, poučen po natančnosti postave naših očetov, in bil sem vnet za Boga, kakor ste vsi vi danes,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 4, 'ki sem preganjal ta pot celó do smrti, ko sem može in žene vezal in v ječo izročal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 5, 'kakor mi to more izpričati tudi veliki duhovnik in vse starejšinstvo; od katerih sem prejel tudi pisem do bratov v Damasku in sem tja šel, da bi pripeljal tudi tiste, ki so tam bili, zvezane v Jeruzalem, da bi jih kaznovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 6, 'Zgodi se pa, ko grem in se bližam Damasku, da me okoli poldne nagloma obsije velika svetloba z neba;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 7, 'in padem na tla in slišim glas, da mi pravi: Savel, Savel, kaj me preganjaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 8, 'Jaz pa odgovorim: Kdo si, Gospod? In mi reče: Jaz sem Jezus Nazarečan, ki ga ti preganjaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 9, 'Tisti pa, ki so bili z menoj, so sicer videli svetlobo, ali glasu njega, ki mi je govoril, niso slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 10, 'In rečem: Kaj naj storim, Gospod? Gospod pa mi veli: Vstani in pojdi v Damask, in tam se ti pove o vsem, kar ti je odločeno, da storiš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 11, 'Ko pa nisem videl od bleščeče te svetlobe, so me peljali za roko, ki so bili z menoj, in sem prišel v Damask.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 12, 'Neki Ananija pa, mož pobožen po postavi, ki ima dobro pričevanje od vseh Judov, ki tam prebivajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 13, 'pride k meni, pristopi in mi reče: Savel, brat, izpregledaj! In tisto uro sem izpregledal in pogledal nanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 14, 'On pa reče: Bog očetov naših te je vnaprej določil, da spoznaš voljo njegovo in vidiš Pravičnega in slišiš glas iz ust njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 15, 'kajti priča mu boš pri vseh ljudeh o tem, kar si videl in slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 16, 'In sedaj, kaj se obotavljaš? Vstani, daj se krstiti in operi grehe svoje, kličoč ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 17, 'Zgodi se pa, ko sem se bil vrnil v Jeruzalem in sem v templju molil, da sem se zamaknil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 18, 'in videl sem ga, da mi pravi: Pohiti in odidi naglo iz Jeruzalema, ker ne sprejmo pričevanja tvojega o meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 19, 'In jaz rečem: Gospod, sami vedo, da sem jaz zapiral v ječe in tepel po shodnicah te, ki verujejo v tebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 20, 'in ko se je prelivala kri Štefana, pričevalca tvojega, sem tudi jaz stal zraven in sem se ž njimi veselil smrti njegove ter varoval oblačila tistih, ki so ga pobijali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 21, 'In veli mi: Pojdi, kajti jaz te pošljem daleč tja med pogane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 22, 'In poslušali so ga do te besede, in tu povzdignejo glas in kriče: Proč z zemlje s takšnim! ker ni prav, da živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 23, 'Ko so pa vpili in raz sebe metali oblačila in prah lučali kvišku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 24, 'ga ukaže tisočnik odpeljati v grad, rekši, naj ga mučijo z biči, da bi zvedel, kaj je vzrok, da tako vpijejo nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 25, 'Ko so ga pa z jermeni pritegnili, reče Pavel stotniku, ki je zraven stal: Smete li človeka Rimljana, in to še ne obsojenega bičati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 26, 'Ko pa sliši to stotnik, pristopi in sporoči tisočniku, rekoč: Kaj boš storil? Ta človek namreč je Rimljan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 27, 'Pristopi pa tisočnik in mu reče: Povej mi, če si ti Rimljan? On pa reče: Sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 28, 'In tisočnik odgovori: Jaz sem za veliko denarja pridobil to državljanstvo. A Pavel reče: Jaz sem se pa tudi rodil Rimljan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 29, 'Tedaj precej odstopijo od njega, ki so ga imeli mučiti; pa tudi tisočnik se zboji, ko je zvedel, da je Rimljan in da ga je dal zvezati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 22, 30, 'Drugi dan pa, ker je hotel za gotovo zvedeti, za kaj ga Judje tožijo, ga oprosti vezi in ukaže priti višjim duhovnikom in vsemu velikemu zboru. In pripelje Pavla doli in ga postavi mednje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 1, 'Pavel pa smelo pogleda na veliki zbor in reče: Možje in bratje! Jaz sem z vso dobro vestjo živel pred Bogom do današnjega dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 2, 'Veliki duhovnik Ananija pa ukaže tistim, ki so stali pri njem, naj ga udarijo po ustih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 3, 'Tedaj mu reče Pavel: Udaril te bo Bog, stena pobeljena! Ti tu sediš, da bi me sodil po postavi, in zoper postavo me veliš bíti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 4, 'Tisti pa, ki so zraven stali, reko: Velikega duhovnika Božjega psuješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 5, 'Pavel pa reče: Nisem vedel, bratje, da je veliki duhovnik; pisano je namreč: „Poglavarja naroda svojega ne preklinjaj“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 6, 'Vedoč pa, da jih je nekaj saducejev, nekaj pa farizejev, zavpije Pavel v velikem zboru: Bratje, jaz sem farizej, sin farizejev; zavoljo upanja in vstajenja od mrtvih sem na sodbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 7, 'Ko je pa to rekel, nastane razpor med farizeji in saduceji, in zbor se razdeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 8, 'Saduceji namreč pravijo, da ni vstajenja in tudi angela in duha ne, farizeji pa priznavajo oboje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 9, 'In nastane velik krik; in nekateri pismarji od strani farizejske vstanejo, se prepirajo in reko: Nič hudega ne vidimo na tem človeku; kako pa, če mu je duh govoril ali angel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 10, 'Ko je pa nastal velik razpor, se je bal tisočnik, da ne bi Pavla raztrgali, ter ukaže vojakom, naj pridejo doli in ga siloma potegnejo izmed njih ter odpeljejo v grad.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 11, 'Drugo noč pa pristopi Gospod k njemu in reče: Srčen bodi! Zakaj kakor si v Jeruzalemu pričal zame, tako moraš tudi v Rimu pričati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 12, 'Ko se je pa zdanilo, se zbere nekaj Judov, in se zarote, da ne bodo ne jedli, ne pili, dokler ne ubijejo Pavla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 13, 'Bilo jih je pa več nego štirideset, ki so sklenili tako zaroto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 14, 'Ti pristopijo k višjim duhovnikom in starejšinam in reko: S prisego smo se zakleli, da ne okusimo ničesar, dokler ne ubijemo Pavla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 15, 'Sedaj torej vi z velikim zborom naznanite tisočniku, naj ga jutri pripelje doli k vam, kakor da bi hoteli natančneje preiskati njegovo zadevo; a mi smo pripravljeni, da ga ubijemo, preden se približa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 16, 'Slišal je pa o tem zalezovanju sin sestre Pavlove, ter pride in stopi v grad in sporoči Pavlu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 17, 'Pavel pa pokliče enega od stotnikov in reče: Tega mladeniča odpelji k tisočniku, ima mu namreč nekaj sporočiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 18, 'On ga torej vzame in pripelje k tisočniku ter reče: Jetnik Pavel me je poklical in prosil, naj tega mladeniča popeljem k tebi, ki ima nekaj govoriti s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 19, 'In tisočnik ga prime za roko in odstopi ž njim na stran in vpraša: Kaj je, kar imaš povedati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 20, 'In reče: Judje so se dogovorili, da te poprosijo, da bi jutri pripeljal Pavla v veliki zbor, kakor da bi hotel kaj natančnejšega izprašati zanj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 21, 'Ti jih pa ne poslušaj: zalezuje ga namreč izmed njih več nego štirideset mož, ki so se zarotili, da ne bodo ne jedli, ne pili, dokler ga ne umore; in sedaj so pripravljeni in čakajo obljube tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 22, 'Tedaj tisočnik odpusti mladeniča, naročivši mu: Naj nikomur ne poveš, da si mi to naznanil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 23, 'In pokliče dva stotnika in veli: Pripravite dvesto vojakov, da pojdejo do Cezareje, in sedemdeset konjikov in dvesto suličnikov po tretji uri v noči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 24, 'ukaže tudi, naj imajo živino pripravljeno, da Pavla posade nanjo in ga zdravega pripeljejo k Feliksu, namestniku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 25, 'In napiše pismo, ki se je takole glasilo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 26, 'Klavdij Lizija pozdravlja častitega namestnika Feliksa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 27, 'Tega moža so Judje zgrabili in ga hoteli umoriti; ali prišel sem z vojsko in ga otel, ko sem zvedel, da je Rimljan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 28, 'Hoteč pa zvedeti vzrok, zakaj ga tožijo, sem ga peljal v njih veliki zbor;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 29, 'in našel sem, da ga tožijo za vprašanja svoje postave, da pa nima nobene krivice, za katero bi bil vreden smrti ali spon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 30, 'Ko se mi je pa naznanil naklep, ki so ga kovali zoper tega moža, sem ga poslal zdajci k tebi, sporočivši tudi tožnikom, naj pred teboj povedo, kar imajo zoper njega. Zdrav!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 31, 'Tedaj so vojaki, kakor jim je bilo naročeno, vzeli Pavla in ga odpeljali po noči v Antipatrido.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 32, 'A drugi dan so se vrnili v grad, pustivši konjike, da so šli ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 33, 'Ko pridejo ti v Cezarejo, oddado pismo namestniku in postavijo tudi Pavla predenj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 34, 'Ko pa prebere pismo, ga vpraša, iz katere pokrajine je, in zvedevši, da je iz Cilicije,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 23, 35, 'reče: Zaslišal te bom, kadar pridejo tudi tožniki tvoji. In ukaže, naj ga varujejo v dvorcu Herodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 1, 'Čez pet dni pa pride doli veliki duhovnik Ananija z nekaterimi starejšinami in z nekim govornikom Tertulom; ti pridejo pred namestnika s tožbo zoper Pavla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 2, 'Ko pa je bil ta poklican, začne tožiti Tertul, govoreč: Da imamo veliko miru po tebi in da je tvoja previdnost dala temu narodu izvrstne izboljšave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 3, 'to vselej in povsod, častiti Feliks, pripoznavamo z vso hvaležnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 4, 'Ali da te dalje ne nadlegujem, prosim, da bi nas poslušal ob kratkem po svoji dobroti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 5, 'Našli smo namreč tega človeka, da je kakor kuga in snovač razporov med Judi po vsem svetu in prvoboritelj za krivoverstvo Nazarejcev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 6, 'ki je tudi poskusil oskruniti tempelj. Njega smo tudi zgrabili in po svoji postavi hoteli soditi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 7, 'toda prišel je Lizija tisočnik ter nam ga je z veliko silo iztrgal iz rok,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 8, 'ukazavši tožnikom njegovim, naj gredo k tebi. Od njega moreš sam, ko izprašaš, zvedeti vse to, za kar ga mi tožimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 9, 'In tej tožbi so se pridružili tudi Judje in pritrdili, da je res tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 10, 'Pavel pa odgovori, ko mu je namestnik namignil, da naj govori: Ker vem, da si že mnogo let sodnik temu narodu, se bom zagovarjal toliko srčneje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 11, 'ko lahko zveš, da ni več nego dvanajst dni, kar sem prišel molit v Jeruzalem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 12, 'in niso me našli v templju, da bi se bil s kom prepiral ali da bi bil napravljal hrup med ljudstvom, ne po shodnicah, ne po mestu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 13, 'in tudi dokazati ti ne morejo, za kar me sedaj tožijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 14, 'To ti pa priznavam, da po poti, ki jo imenujejo krivoverstvo, tako služim Bogu naših očetov, da verujem vse, kar je pisano v postavi in v prorokih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 15, 'in da imam upanje v Boga, ki se ga tudi ti sami držé, da bode vstajenje mrtvim, i pravičnim i nepravičnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 16, 'V tem si pa sam prizadevam, da bi vsekdar imel brezmadežno vest pred Bogom in ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 17, 'Čez več let pa sem prišel, da donesem miloščine narodu svojemu in daritve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 18, 'pri tem so me našli očiščenega v templju, ne z množico, ne s hrupom: bili so pa to neki Judje iz Azije,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 19, 'ki bi morali tu pred teboj stati in tožiti, če imajo kaj zoper mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 20, 'Ali naj ti sami povedo, če so našli krivico na meni, ko sem stal pred velikim zborom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 21, 'razen menda tega edinega glasu, ki sem ga zavpil, stoječ med njimi: Zavoljo vstajenja mrtvih me danes sodite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 22, 'Feliks pa odloži njih reč, natančno vedoč, za kaj gre pri tej poti, in reče: Kadar Lizija tisočnik pride doli, razsodim vašo stvar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 23, 'In stotniku ukaže, da je Pavla varovati, in naj se mu polajša in se nikomur izmed njegovih ne brani mu streči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 24, 'A čez nekaj dni pride Feliks z Druzilo, ženo svojo, ki je bila Judinja, in pokliče Pavla predse, in slišal ga je o veri v Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 25, 'Ko pa je govoril o pravičnosti in zdržljivosti in prihodnji sodbi, se prestraši Feliks in odgovori: Za sedaj pojdi; a kadar bom imel priličen čas, te zopet pokličem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 26, 'Zraven se je pa tudi nadejal, da mu Pavel da denarja, zato ga je tudi pogosteje klical k sebi in se ž njim razgovarjal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 24, 27, 'Ko sta se pa dopolnili dve leti, dobi Feliks za naslednika Porcija Festa. Ker si je pa Feliks želel pridobiti hvaležnost Judov, je pustil Pavla zvezanega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 1, 'Ko je bil torej Fest prišel v deželo, se napoti čez tri dni iz Cezareje v Jeruzalem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 2, 'In oglasijo se pri njem višji duhovniki in prvaki Judov kot tožniki zoper Pavla in ga prosijo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 3, 'zahtevajoč to milost zoper njega, da bi ga poslal v Jeruzalem; in so zalezovali, da bi ga umorili na poti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 4, 'Toda Fest odgovori, da Pavla varujejo v Cezareji, in da pojde on sam kmalu zopet tja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 5, 'Kateri so torej med vami pooblaščenci, reče, naj gredo z menoj, in če je kaj nepristojnega na tem možu, naj ga tožijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 6, 'In ko je prebil med njimi ne več kakor osem ali deset dni, odide v Cezarejo; in drugi dan sede na sodni stol in ukaže Pavla pripeljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 7, 'Ko ga pa pripeljejo, ga obstopijo Judje, ki so prišli iz Jeruzalema, in izrekajo zoper njega mnoge in hude dolžitve, ki jih ne morejo dokazati,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 8, 'ko se Pavel zagovarja: Nič se nisem pregrešil zoper postavo Judov, ne zoper tempelj, ne zoper cesarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 9, 'Fest pa, hoteč si pridobiti hvaležnost Judov, izpregovori k Pavlu in reče: Hočeš iti gori v Jeruzalem, da te bom tam sodil za te obtožbe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 10, 'Pavel pa reče: Pred cesarjevim sodnim stolom stojim, kjer moram biti sojen. Judom nisem storil ničesar krivega, kakor tudi sam prav dobro veš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 11, 'Če sem pa kriv in sem storil kaj smrti vrednega, se ne branim umreti; če pa ni nič tega, česar me tožijo, me ne more nihče njim izdati. Na cesarja se sklicujem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 12, 'Tedaj se Fest pogovori s svetovalstvom in odgovori: Na cesarja si se sklical, k cesarju pojdeš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 13, 'Ko je pa minilo nekoliko dni, prideta Agripa kralj in Bernika v Cezarejo pozdravljat Festa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 14, 'Ko sta se pa več dni tam mudila, razloži Fest kralju Pavlovo zadevo, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 15, 'Nekega moža je pustil Feliks v ječi, ki so ga, ko sem bil v Jeruzalemu, prišli tožit višji duhovniki in starejšine Judov, zahtevajoč, naj ga obsodim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 16, 'Tem sem odgovoril, da ni navada pri Rimljanih, da bi se izdal kak človek na smrt, dokler obtoženec nima tožnikov pred licem in se mu ne da priložnost, zagovarjati se zoper obtožbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 17, 'Ko so se torej tukaj sešli, sem sedel brez vsega odlašanja drugi dan na sodni stol in ukazal moža pripeljati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 18, 'Njegovi tožniki pa, ko so nastopili, mu niso očitali nobene take krivice, kakršne sem pričakoval jaz,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 19, 'ampak neka sporna vprašanja o svojem bogočastju so imeli zoper njega in o nekem Jezusu, ki je umrl in je Pavel o njem trdil, da živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 20, 'Jaz pa, ne vedoč, kako bi s preiskavo te pravde postopal, sem rekel, ako bi hotel iti v Jeruzalem in tam sojen biti za to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 21, 'Toda ko se je Pavel oglasil, da naj ga varujemo do cesarjeve sodbe, sem ga ukazal varovati, dokler ga ne pošljem k cesarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 22, 'Agripa pa reče Festu: Rad bi tudi jaz slišal tega človeka. On reče: Jutri ga boš slišal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 23, 'Drugi dan torej prideta Agripa in Bernika z velikim sijajem in vstopita v zasliševalno dvorano s tisočniki in najimenitnejšimi mestnimi možmi; in ko Fest ukaže, pripeljejo Pavla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 24, 'In Fest reče: Kralj Agripa, in vsi možje, ki ste tu z nami! vidite tega, zavoljo katerega me je vsa množica Judov nadlegovala v Jeruzalemu in tu, kričeč, da ne sme več živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 25, 'Jaz pa sem spoznal, da ni storil nič smrti vrednega; ker se je pa on sam sklical na cesarja, sem ga sklenil tja poslati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 26, 'A nimam nič gotovega, kar bi za njega pisal gospodarju. Zato sem ga pripeljal pred vas, in zlasti pred tebe, kralj Agripa, da imam, ko se izpraša, kaj pisati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 25, 27, 'Neumno se mi namreč zdi poslati jetnika, ne da bi hkrati naznanil, česar ga tožijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 1, 'Agripa pa reče Pavlu: Dopušča se ti, da sam zase govoriš. Tedaj Pavel iztegne roko in se zagovarja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 2, 'Srečnega se štejem, kralj Agripa, da se smem danes pred teboj zagovarjati za vse, česar me Judje dolže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 3, 'zlasti ker vem, da poznaš vse šege in prepire pri Judih: zato te prosim, da bi me potrpežljivo poslušal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 4, 'Kar se torej tiče življenja mojega od mladosti, kakšno je bilo od začetka med narodom mojim in v Jeruzalemu, vedo vsi Judje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 5, 'ker me poznajo od začetka, če hočejo pričati, da sem živel po najostrejši ločini bogoslužja našega kot farizej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 6, 'In sedaj stojim pred sodbo zavoljo upanja v obljubo, ki jo je Bog dal očetom našim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 7, 'ki jo dvanajsteri rodovi naši upajo doseči, stanovitno služeč Bogu noč in dan. Zavoljo tega upanja sem, o kralj, tožen od Judov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 8, 'Zakaj se vam zdi neverjetno, da Bog mrtve obuja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 9, 'Tudi jaz sem sicer menil, da moram zoper ime Jezusa Nazarečana storiti veliko nasprotnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 10, 'To sem tudi storil v Jeruzalemu; in veliko svetih sem zaprl v ječe, ko sem bil prejel pooblastilo za to od višjih duhovnikov, in ko so jih morili, sem dajal svoj glas zoper nje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 11, 'In po vseh shodnicah sem jih pogostoma mučil in silil preklinjati Jezusa; in neizmerno sem divjal zoper nje in jih preganjal celo v inostranskih mestih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 12, 'In ko sem zategadelj šel v Damask z oblastjo in dovoljenjem od višjih duhovnikov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 13, 'opoldne na potu sem videl, o kralj, z neba luč, svetlejšo od sončne svetlobe, ki je obsijala mene in tiste, ki so šli z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 14, 'In ko smo vsi popadali na zemljo, sem slišal glas, da mi pravi v hebrejskem jeziku: Savel, Savel, kaj me preganjaš? Težko ti je proti ostnu brcati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 15, 'Jaz sem pa rekel: Kdo si, Gospod? Gospod pa veli: Jaz sem Jezus, ki ga ti preganjaš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 16, 'Ali vstani in stopi na noge. Zato namreč sem se ti prikazal, da te postavim za služabnika in pričo tega, kar si videl, in tega, v čemer se ti bom pokazoval,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 17, 'ko te bom reševal od ljudstva judovskega in poganov, med katere te sedaj pošiljam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 18, 'da jim odpreš oči, da se izpreobrnejo od teme k luči in od oblasti satanove k Bogu: da prejmo odpuščenje grehov in delež med posvečenimi po veri, ki je v mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 19, 'Zato, kralj Agripa, nisem bil nepokoren nebeški prikazni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 20, 'ampak oznanjeval sem najprej tem, ki so bili v Damasku, potem v Jeruzalemu in po vsej deželi Judejski in tudi poganom, naj se izpokore in izpreobrnejo k Bogu, opravljajoč dela, vredna izpokorjenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 21, 'Zato so me Judje v templju zgrabili in poskusili svojeročno umoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 22, 'Ali dobivši pomoč, ki je od Boga, stojim do današnjega dne in pričujem malim in velikim, ne govoreč ničesar drugega, nego kar so govorili proroki in Mojzes, da se bo zgodilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 23, 'namreč, da mora Kristus trpeti in kot prvi iz vstajenja mrtvih luč oznanjevati temu narodu in poganom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 24, 'Ko se pa tako zagovarja, reče Fest z močnim glasom: Meša se ti, Pavel! Velika učenost tvoja ti jemlje um.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 25, 'Pavel pa reče: Ne meša se mi, vrli Fest, temuč besede resnice in razumnosti govorim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 26, 'Saj ve za to stvar kralj, h kateremu tudi prostosrčno govorim; prepričan sem namreč, da mu ni nič tega neznanega, kajti to se ni godilo v zakotju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 27, 'Veruješ, kralj Agripa, prorokom? Vem, da veruješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 28, 'Agripa pa reče Pavlu: Malo, pa me boš pregovoril, da postanem kristjan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 29, 'Pavel pa reče: Želel bi od Boga, bodisi za malo ali za veliko, da ne bi samo ti, ampak tudi vsi, ki me danes poslušajo, bili taki, kakršen sem tudi jaz, izimši te spone.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 30, 'In vstanejo kralj in namestnik in Bernika in kateri so ž njim sedeli,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 31, 'ter odidejo na stran in se razgovarjajo in pravijo: Ta človek ne dela nič smrti ali spon vrednega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 26, 32, 'Agripa pa reče Festu: Lahko bi se bil izpustil ta človek, da se ni sklical na cesarja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 1, 'Ko je bilo pa sklenjeno, da se imamo po morju odpeljati v Italijo, so izročili Pavla in nekaj drugih jetnikov stotniku, po imenu Juliju, od cesarske trume.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 2, 'In stopivši na ladjo iz Adramita, ki je bila namenjena v primorska mesta v Aziji, smo odrinili, in z nami je bil Aristarh, Macedonec iz Soluna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 3, 'In drugi dan smo prišli v Sidon. In Julij je priljudno ravnal s Pavlom in mu je dovolil iti k prijateljem in si dati postreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 4, 'In ko smo odrinili odtod, smo se peljali za Ciprom, ker so nam bili vetrovi nasprotni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 5, 'In ko smo prepluli morje, ki je poleg Cilicije in Pamfilije, smo pripli v Miro v Liciji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 6, 'In tu je našel stotnik ladjo iz Aleksandrije, ki je jadrala v Italijo, in nas je prestavil nanjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 7, 'Ko smo se bili pa mnogo dni počasi vozili in dospeli s težavo proti Knidu, kjer nam je veter branil pristati, smo pluli pod Kreto proti Salmoni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 8, 'In le s težavo se vozeč mimo nje, smo prišli v neki kraj, ki se imenuje Dobro pristanišče, blizu katerega je bilo mesto Laseja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 9, 'Ko je bilo pa veliko časa prešlo in je bila vožnja že nevarna, ker je že tudi post minil, jih je Pavel opominjal');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 10, 'in jim dejal: Možje, vidim, da hoče vožnja biti huda in silno nevarna ne le za blago in ladjo, ampak tudi za življenje naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 11, 'Ali stotnik je bolj verjel krmarju in gospodarju ladje nego temu, kar je pravil Pavel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 12, 'In ker pristanišče ni bilo pripravno za zimovanje, so sklenili skoro vsi, odpeljati se odtod, ne bi li kako mogli dospeti do Fenike, ki je pristanišče na Kreti in leži proti jugu in zahodnemu severu, in tam prezimovati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 13, 'Ko je pa potegnil jug, so odrinili, misleč, da dosežejo svoj namen, in so se peljali ob Kreti, bližje obrežja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 14, 'Toda nedolgo potem zaveje od otoka hud veter, ki se imenuje vzhodni sever.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 15, 'Ko je pa zgrabilo ladjo in se ni mogla vetru upirati, smo jo izročili valovom, in nosili so nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 16, 'Ko nas pa je zaneslo pod neki otočič, po imenu Kavda, smo komaj mogli obdržati čolnič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 17, 'In ko so ga vzdignili, so se poslužili pripomočkov in so ovili ladjo; in boječ se, da ne bi zadeli na kleče, so spustili jadra in so se tako peljali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 18, 'In ker nas je vihar hudo metal, so drugi dan začeli izmetavati blago,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 19, 'in tretji dan so s svojimi rokami izmetali ladijno opravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 20, 'Ko se pa ne solnce, ne zvezde niso pokazale več dni in je silna burja na nas pritiskala, je že izginilo vse upanje, da bi se oteli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 21, 'In ko že dolgo časa niso jedli, tedaj reče Pavel, stoječ sredi njih: Poslušali bi me bili, o možje, in ne odrinili od Krete in tako se obvarovali te nadloge in izgube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 22, 'In sedaj vas opominjam, da bodite srčni: zakaj izgube ne bo nobenega življenja med vami, razen le ladje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 23, 'Stal mi je namreč ob strani to noč angel Boga, čigar sem in ki mu služim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 24, 'rekoč: Ne boj se, Pavel! pred cesarja moraš stopiti; in glej, Bog ti je podaril vse, kar se jih pelje s teboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 25, 'Zatorej bodite srčni, možje! Kajti verujem Bogu, da se res tako zgodi, kakor mi je bilo rečeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 26, 'Moramo se pa nameriti na neki otok.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 27, 'Ko je pa štirinajsta noč prišla in so nas valovi semterja gnali po Jadranskem morju, se je zdelo mornarjem okoli polnoči, da se bližajo neki zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 28, 'In izmerivši globočino, najdejo dvajset sežnjev; in ko pridejo malo dalje in izmerijo globočino, najdejo petnajst sežnjev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 29, 'In boječ se, da ne bi naleteli na skalnata mesta, so vrgli s krme štiri mačke in so želeli, da bi se dan naredil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 30, 'Ko so pa mornarji skušali pobegniti z ladje in so spustili čolnič v morje z izgovorom, da hočejo s prednjega konca mačke vreči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 31, 'reče Pavel stotniku in vojakom: Ako ti ne ostanejo na ladji, se vi ne morete oteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 32, 'Tedaj odsekajo vojaki vrvi čolniču in ga spuste, da je odplul.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 33, 'Dokler bi se pa začelo daniti, prosi Pavel vse, naj vzemo jedi, rekoč: Štirinajsti dan je danes, kar čakate in ste brez jedi, ne uživši ničesar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 34, 'Zato vas prosim, vzemite jedi, zakaj to je za vašo ohranitev. Nikomur od vas namreč se ne pogubi las z glave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 35, 'In rekši to, vzame kruh in zahvali Boga pred vsemi, ter ga prelomi in začne jesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 36, 'Tedaj postanejo vsi srčnejši in vzemo tudi oni jedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 37, 'Bilo nas je pa vseh na ladji dvesto in šestinsedemdeset duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 38, 'In ko so se dositega najedli, so olajšali ladjo, izmetavši žito v morje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 39, 'Ko se je pa zdanilo, niso poznali dežele; ugledajo pa neki zaliv, da ima raven breg, in nanj so mislili, ko bi bilo mogoče, izvleči ladjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 40, 'In odsekajo mačke in jih puste v morju, obenem pa odvežejo vrvi pri krmilih; in razpno prednje jadro po vetru ter se peljejo proti bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 41, 'Ko pa jih je zagnalo na kraj, ki je imel po obeh straneh morje, so zadeli z ladjo ob tla; in prednji konec se je zasadil in trdno obtičal, a krma se je razbijala od sile valovja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 42, 'Vojakov naklep pa je bil, da pomoré jetnike, da ne bi kdo odplaval in pobegnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 43, 'Toda stotnik hoteč ohraniti Pavla, prepreči njih naklep in ukaže, naj tisti, ki znajo plavati, najprej skočijo v vodo in se spravijo na suho,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 27, 44, 'drugi pa nekateri na deskah, a nekateri na kosovih od ladje. In tako se je zgodilo, da so se vsi rešili na suho.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 1, 'In ko smo se bili oteli, smo spoznali, da se otok imenuje Melita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 2, 'Divjaki pa so nam izkazovali ne majhno ljudomilost: zažgali so namreč grmado in sprejeli so nas vse zavoljo dežja, ki je šel, in zavoljo mraza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 3, 'Ko pa nabere Pavel kup hoste in jo dene na ogenj, se priplazi gad vsled vročine in se mu obesi na roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 4, 'Ko pa vidijo divjaki, da mu visi zver na roki, govore med seboj: Gotovo je ta človek ubijalec, ki ga, otetega iz morja, pravica maščevalka ne pusti živeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 5, 'Toda on otrese zver na ogenj, in nič hudega se mu ni zgodilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 6, 'Oni so pa čakali, da oteče ali se hkratu zgrudi in umre. Ko so pa dolgo čakali in videli, da se mu nič hudega ne zgodi, so premenili svoje misli in so dejali, da je bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 7, 'Okoli tega kraja pa so bile pristave poglavarja otoka, Publija po imenu, ki nas je sprejel in tri dni prijazno gostil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 8, 'Zgodi se pa, da je oče Publijev ležal bolan za mrzlico in grižo: k temu gre Pavel in moleč položi nanj roke in ga ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 9, 'In ko se je to zgodilo, so prihajali z otoka tudi drugi, ki so imeli bolezni, in so bili ozdravljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 10, 'Ti so nam tudi izkazovali mnogotere časti, in ko smo odhajali, so nam naložili, kar je bilo potreba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 11, 'A po treh mesecih smo se odpeljali na aleksandrijski ladji, ki je bila prezimila na otoku in je imela znamenje Dvojčkov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 12, 'In pripeljali smo se v Sirakuz in ostali tu tri dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 13, 'Odtod smo se okoli peljali in dospeli v Regijo, in ko je en dan potem potegnil jug, smo prišli drugi dan v Puteole.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 14, 'Tu smo našli bratov, in prosili so nas, naj bi pri njih prebili sedem dni; in tako smo prišli v Rim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 15, 'In odtod, ko so bratje slišali za nas, so nam prišli naproti do Apijevega trga in do Treh krčem; in ko jih je videl Pavel, je zahvalil Boga in se napolnil zaupanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 16, 'Ko smo pa prišli v Rim, [je izročil stotnik jetnike poveljniku cesarske straže, a] Pavlu se je dovolilo prebivati, kjer sam hoče, z vojakom, ki ga je varoval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 17, 'Zgodi se pa po treh dneh, da skliče Pavel prvake Judov. In ko so se sešli, jim je rekel: Možje bratje! dasi jaz ničesar nisem storil zoper naše ljudstvo ali šege očetovske, vendar so me zvezanega iz Jeruzalema izdali v roke Rimljanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 18, 'Ti so me, ko so me bili zaslišali, hoteli izpustiti, zato ker ni bilo nobene smrtne krivice na meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 19, 'Ko so pa Judje ugovarjali, sem bil prisiljen, sklicati se na cesarja, ne kakor da bi imel narod svoj za kaj tožiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 20, 'Zavoljo tega razloga torej sem vas poklical, da bi vas videl in z vami govoril; zakaj zaradi upanja Izraelovega sem vkovan v to verigo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 21, 'Oni mu pa reko: Mi nismo ne pisem zastran tebe prejeli iz Judeje in tudi nobeden izmed bratov ni prišel, da bi sporočil ali govoril kaj hudega o tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 22, 'Želimo pa slišati od tebe, kaj misliš; kajti za to ločino nam je znano, da ji povsod ugovarjajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 23, 'In ko so mu odločili dan, jih je mnogo prišlo k njemu v stanovanje; in jim je razlagal vse ter pričeval o kraljestvu Božjem in jim služil k veri v to, kar se tiče Jezusa, iz postave Mojzesove in prorokov, od zore do mraka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 24, 'In nekateri so verovali temu, kar jim je pravil, a nekateri niso verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 25, 'In ker niso bili složni med seboj, so odhajali, ko je rekel Pavel to eno besedo: Dobro je povedal sveti Duh po Izaiju proroku očetom vašim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 26, 'rekoč: „Pojdi k temu ljudstvu in reci: S sluhom boste slišali, a ne boste umeli, in z očmi boste gledali, a ne boste videli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 27, 'Kajti okamenelo je srce temu ljudstvu, in z ušesi težko slišijo, in oči so si zatisnili: da ne bi kako z očmi videli in z ušesi slišali in s srcem umeli in se spreobrnili, ter bi jih ozdravil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 28, 'Bodi vam torej znano, da je poganom poslano to zveličanje Božje; oni bodo tudi poslušali. [');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 29, '§ In ko je to povedal, so odšli Judje, in so imeli mnogo prepira med seboj.]');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 30, 'On pa je ostal celi dve leti v svojem najetem stanovanju in je sprejemal vse, ki so k njemu prihajali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (44, 28, 31, 'oznanjujoč kraljestvo Božje in učeč to, kar je Gospoda Jezusa Kristusa, z vso srčnostjo, in nihče mu ni branil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 1, 'Pavel, hlapec Jezusa Kristusa, poklican apostol, odločen za evangelij Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 2, 'ki ga je Bog prej obljubil po prorokih svojih v svetih pismih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 3, 'o svojem Sinu, rojenem iz semena Davidovega po mesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 4, 'postavljenem za Sina Božjega v moči po duhu svetosti na podlagi vstajenja od mrtvih, o Jezusu Kristusu, Gospodu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 5, 'Po njem smo prejeli milost in apostolstvo, da se razširi poslušnost veri med vsemi narodi zaradi imena njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 6, 'ki ste med njimi tudi vi, poklicani Jezusa Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 7, 'vsem, ki so v Rimu, ljubljencem Božjim, poklicanim svetim: Milost vam bodi in mir od Boga Očeta našega in Gospoda Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 8, 'Najprej zahvaljujem Boga svojega po Jezusu Kristusu za vse vas, da se o veri vaši oznanja po vsem svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 9, 'Kajti priča mi je Bog, ki mu služim v duhu svojem v evangeliju Sina njegovega, kako se vas neprenehoma spominjam, vsekdar v svojih molitvah proseč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 10, 'da bi se mi kako že posrečilo po volji Božji priti k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 11, 'Zakaj močno vas želim videti, da bi vam podelil kak duhovni dar v potrjenje vaše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 12, 'a to je, da se sredi vas porazveselim z vami vred, po skupni, vaši in svoji veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 13, 'Nočem pa, bratje, da bi ne vedeli, da sem se mnogokrat namenil priti k vam (pa sem bil zadržan do sedaj), da bi kaj sadu dobil tudi med vami, enako kakor med drugimi pogani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 14, 'Dolžnik sem enako vsem: Grkom in divjakom, modrim in neumnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 15, 'Tako torej, kar se mene tiče, sem voljan oznanjati evangelij tudi vam, ki ste v Rimu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 16, 'Kajti ne sramujem se evangelija, ker je moč Božja v zveličanje vsakemu, ki veruje, Judu najprej, pa tudi Grku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 17, 'Zakaj pravičnost Božja se v njem razodeva iz vere v vero, kakor je pisano: „A pravičnik bo živel iz vere“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 18, 'Razodeva se namreč jeza Božja z neba nad vsako brezbožnostjo in krivičnostjo ljudi, ki zadržujejo resnico v krivici,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 19, 'ker to, kar more biti znano o Bogu, je v njih vesti očitno; Bog jim je to namreč razodel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 20, 'Kajti kar se od njega ne more videti, njegova večna moč in božanstvo, to se od ustvarjenja sveta zaznava z umom in vidi po njegovih delih, tako da se ne morejo izgovarjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 21, 'Ker vkljub temu, da so spoznali Boga, ga niso slavili kot Boga, niti se mu zahvalili, temuč so zabredli v ničeve misli in njih nerazumno srce je potemnelo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 22, 'Izdajajoč se za modre, so postali nespametni');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 23, 'in zamenili so slavo netrohljivega Boga s podobo obraza trohljivega človeka in ptic in četveronogih živali in lazečih zveri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 24, 'Zato jih je tudi izročil Bog, v željah njih src, v nečistost, da se skrunijo njih telesa med njimi samimi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 25, 'ki so zamenili resnico Božjo z lažjo in so izkazali večjo čast in službo stvoru nego Stvarniku, ki je hvaljen na veke. Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 26, 'Zato jih je izročil Bog v sramotne strasti: kajti njih ženske so premenile naravno upotrebljevanje v protinaravno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 27, 'a enako so tudi moški zavrgli naravno upotrebljevanje ženske in se vneli v svoji želji drug za drugega ter počenjali nesramnosti moški z moškimi. In tako so prejemali zasluženo plačilo svoje zmote sami na sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 28, 'In kakor niso marali Boga imeti v spoznanju, tako jih je Bog izročil popačeni pameti, da so delali, kar ni spodobno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 29, 'ter so bili napolnjeni vsakršne krivice, malopridnosti, lakomnosti, hudobnosti, polni zavisti, ubojstva, prepira, zvijače, zlobnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 30, 'prišeptavalci, obrekovalci, sovražni Bogu, grozovitniki, ošabneži, bahači, izmišljevalci hudega, roditeljem nepokorni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 31, 'nerazumni, verolomni, brez ljubezni, neusmiljeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 1, 32, 'ki, čeprav dobro poznajo pravno naredbo Božjo, da so vredni smrti, kateri tako delajo, takisto ne samo počenjajo, ampak tudi še hvalijo te, ki tako delajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 1, 'Zato se ne moreš zagovarjati, o človek, kdorkoli si, ki sodiš; kajti v čemer sodiš drugega, obsojaš samega sebe; ker ti, ki sodiš, delaš isto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 2, 'Vemo pa, da sodba Božja zadeva po resnici te, ki delajo taka dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 3, 'Ali pač misliš to, o človek, ki sodiš tiste, ki delajo taka dela, a isto delaš, da ti ubežiš sodbi Božji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 4, 'Ali pa zaničuješ bogastvo njegove dobrote in prizanesljivosti in potrpljivosti, ne vedoč, da te dobrota Božja vodi na izpokorjenje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 5, 'Temuč s svojo trdovratnostjo in z neizpokorljivim srcem sam sebi spravljaš jezo za dan jeze in razodetja pravične sodbe Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 6, 'ki poplača vsakemu po njegovih delih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 7, 'tistim, ki s stanovitnostjo v dobrem delu iščejo slave in časti in nestrohljivosti, dá večno življenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 8, 'a sebičnim in resnici nepokornim, krivici pa pokornim, srd in jezo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 9, 'Stiska in nadloga pride na dušo vsakega človeka, ki dela hudo, najprej na Juda, pa tudi na Grka;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 10, 'a slava in čast in mir vsakemu, ki dela dobro, najprej Judu, pa tudi Grku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 11, 'ker Bog ne gleda, kdo je kdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 12, 'Katerikoli so namreč brez postave grešili, tudi brez postave poginejo; in katerikoli so grešili, imajoč postavo, bodo po postavi sojeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 13, 'Zakaj kateri postavo poslušajo, niso pravični pred Bogom, temuč kateri po postavi delajo, bodo šteti za pravične.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 14, 'Kadar namreč pogani, ki nimajo postave, delajo po naravi, kar zahteva postava, ti so, ne imajoč postave, sami sebi postava;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 15, 'saj sami kažejo, da je zahteva postave zapisana v njih srcih, ker jim to izpričujejo njih vest ter misli, ko se med seboj tožijo ali tudi zagovarjajo; -');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 16, 'v dan, ko bo sodil Bog skrivnosti ljudi, po mojem evangeliju, po Jezusu Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 17, 'Če pa se ti imenuješ Jud in se naslanjaš na postavo in se hvališ z Bogom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 18, 'in poznaš voljo njegovo in presojaš, kaj je boljše, ker si naučen iz postave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 19, 'in zaupaš sebi, da si vodnik slepih, svetlost tistim, ki so v temi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 20, 'gojitelj nerazumnih, učitelj nedoraslih, ker imaš obrazec znanja in resnice v postavi:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 21, 'ki torej učiš drugega, sebe li ne učiš? ki oznanjaš, naj se ne krade, kradeš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 22, 'ki govoriš, naj se ne prešeštvuje, prešeštvuješ? ki so ti mrzki maliki, pleniš svetišče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 23, 'ki se hvališ s postavo, s prestopanjem postave Bogu delaš nečast?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 24, 'Kajti „zavoljo vas se ime Božje preklinja med pogani“, kakor je pisano.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 25, 'Obreza je resda koristna, če izpolnjuješ postavo; ako pa si prestopnik postave, je tvoja obreza postala neobreza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 26, 'Če torej neobrezanec izpolnjuje pravične predpise postave, se li ne bo njegova neobreza štela za obrezo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 27, 'In ne obsodi li neobrezanec po naravi, ki izpolnjuje postavo, tebe, ki si prestopnik postave, čeprav imaš črko in obrezo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 28, 'Ni namreč Jud, ki je po zunanjem Jud, tudi ni obreza, ki je zunaj na mesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 2, 29, 'marveč ta je Jud, ki je znotraj Jud, in prava obreza je obreza srca v duhu, ne v črki; čigar hvala ni od ljudi, ampak od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 1, 'Kaj so torej Judje na boljšem? ali kaj hasni obreza?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 2, 'Mnogo vsekakor. Najprvo, da so se jim zaupali izreki Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 3, 'Pa kaj, če niso verovali nekateri? Odpravi li njih nevera zvestost Božjo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 4, 'Nikakor ne! Temuč Bog naj se izkaže resničnega, a vsak človek lažnivca, kakor je pisano: „Da se opravičiš v svojih besedah in zmagaš, ko te bodo sodili“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 5, 'Če pa naša krivičnost potrjuje Božjo pravičnost, kaj porečemo? Da je Bog nepravičen, ko kaznuje v jezi? (po človeško govorim).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 6, 'Nikakor ne! kajti kako bo sicer Bog sodil svet?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 7, 'Če se je namreč resnica Božja po moji laži povečala v njegovo slavo, zakaj bi bil še tudi jaz sojen kot grešnik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 8, 'In ne smemo li govoriti, kakor nas nekateri obrekujejo in pravijo, da govorimo: Delajmo hudo, da pride iz tega dobro? Tehle čaka pravična sodba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 9, 'Kaj torej? Ali so Judje boljši? Nikakor ne. Kajti prej smo obtožili i Jude i Grke, da so vsi pod grehom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 10, 'kakor je pisano: „Ni pravičnega ne enega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 11, 'ni ga, ki bi bil razumen, ni ga, ki bi iskal Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 12, 'vsi so zašli s pota, vsi skup so se izpridili; ni ga, ki bi delal dobro, ni ga še enega ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 13, 'Odprt grob je njih grlo, s svojimi jeziki varajo; kačji strup je pod njih ustnicami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 14, 'Njih usta so polna kletve in grenkobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 15, 'Hitre so njih noge, da kri prelijó.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 16, 'Pokončevanje in nadloga je na njih potih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 17, 'in poti miru niso spoznali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 18, 'Ni strahu Božjega pred njih očmi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 19, 'Vemo pa, karkoli govori postava, govori tem, ki so pod postavo, da se vsaka usta zamaše in ves svet zapade sodbi Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 20, 'Kajti iz del postave ne bo opravičeno nobeno meso pred njim; zakaj po postavi prihaja spoznanje greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 21, 'Sedaj pa se je brez postave razodela pravičnost Božja, izpričevana od postave in prorokov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 22, 'pravičnost namreč Božja po veri v Jezusa Kristusa vsem in za vse, ki verujejo. Kajti ni nobenega razločka:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 23, 'zakaj vsi so se pregrešili ter nimajo slave Božje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 24, 'in dobivajo opravičenje daroma ž njegovo milostjo po odkupu, ki je v Kristusu Jezusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 25, 'ki ga je predstavil Bog kot sprave daritev po veri v njegovi krvi, da pokaže svojo pravičnost zaradi prizanašanja prejšnjim grehom');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 26, 'v času potrpljenja Božjega, z ozirom na dokaz svoje pravičnosti v sedanjem času, da bi bil Bog sam pravičen in opravičitelj tega, ki je iz vere Jezusove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 27, 'Kje je torej naša hvala? Izključena je. Po kakšni postavi? po postavi del? Ne, ampak po postavi vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 28, 'Sodimo namreč, da se z vero opravičuje človek, brez del postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 29, 'Ali je Bog samo Bog Judov? ni li tudi poganov? Da, tudi poganov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 30, 'ker je le eden Bog, ki opraviči obrezo iz vere in neobrezo po veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 3, 31, 'Ali torej postavo odpravljamo po veri? Nikakor ne, temuč postavo postavljamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 1, 'Kaj torej porečemo, da je dosegel Abraham, naš prednik, po mesu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 2, 'Kajti če je bil Abraham opravičen iz del, se ima s čim hvaliti, ali ne pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 3, 'Ker kaj pravi pismo? „Veroval pa je Abraham Bogu, in zaračunilo se mu je za pravičnost“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 4, 'A tistemu, ki opravlja dela, se ne računi plačilo po milosti, temuč po dolžnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 5, 'Tistemu pa, ki ne opravlja del, a veruje v tega, ki opravičuje brezbožnega, se računi njegova vera za pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 6, 'Kakor tudi David pravi, da je blagor človeku, ki mu Bog računi pravičnost brez del:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 7, '„Blagor jim, ki so se jim odpustile nepostavnosti in ki so jim grehi prikriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 8, 'Blagor možu, ki mu Gospod nič več ne računi greha“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 9, 'Blagrovanje torej to velja li za obrezo ali tudi za neobrezo? Kajti pravimo: Abrahamu se je vera zaračunila za pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 10, 'Kako pa se mu je zaračunila? ko je bil v obrezi ali še v neobrezi? Ne v obrezi, ampak v neobrezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 11, 'In znamenje obreze je prejel kot pečat pravičnosti vere, ki jo je imel v neobrezi, da bi bil oče vsem, ki verujejo v neobrezi, da bi se njim zaračunila pravičnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 12, 'in da bi bil oče obreze tistim, ki so ne samo obrezani, ampak tudi hodijo po stopinjah vere očeta našega Abrahama, ki jo je imel v neobrezi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 13, 'Kajti ni se dala po postavi obljuba Abrahamu ali njegovemu semenu, da bode dedič sveta, ampak po pravičnosti vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 14, 'Zakaj če so dediči ti, ki se drže postave, ničeva je vera in brez veljave obljuba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 15, 'Postava namreč napravlja jezo; kjer pa ni postave, tudi ni prestopka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 16, 'Zato je dediščina iz vere, da bode po milosti, da bi bila obljuba trdna vsemu semenu, ne samo temu, ki je iz postave, ampak tudi temu, ki je iz vere Abrahamove; ta je oče vseh nas');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 17, '(kakor je pisano: „Za očeta mnogih narodov sem te postavil“) pred obličjem Boga, kateremu je veroval, ki oživlja mrtve in kliče to, česar ni, kakor da je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 18, 'On je veroval v upanje, kjer ni bilo ničesar upati, da postane oče mnogih narodov, kakor mu je bilo rečeno: Tako bode seme tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 19, 'In ne oslabevši v veri, ni gledal na svoje že omrtvelo telo, ker je imel blizu sto let, niti na odrevenelo maternico Sarino;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 20, 'glede na obljubo Božjo pa ni dvomil v nejeveri, temuč ojačil se je v veri, in davši čast Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 21, 'je bil popolnoma prepričan, da ima moč tudi storiti, kar je obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 22, 'Zato se mu je tudi zaračunilo za pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 23, 'Ni pa napisano samo zaradi njega, da se mu je zaračunilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 24, 'ampak tudi zaradi nas, katerim ima biti zaračunjeno, ki verujemo v tistega, ki je obudil Jezusa, Gospoda našega, iz mrtvih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 4, 25, 'ta je bil dan v smrt za grehe naše in je bil obujen za opravičenje naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 1, 'Ker smo torej opravičeni po veri, imamo mir z Bogom po Gospodu našem Jezusu Kristusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 2, 'po katerem smo tudi dobili v veri pristop v to milost, ki stojimo v njej, in hvalimo se z upanjem slave Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 3, 'Pa ne samo to, temuč hvalimo se tudi v stiskah, vedoč, da stiska rodi potrpežljivost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 4, 'a potrpežljivost izkušenost, izkušenost pa upanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 5, 'a upanje ne osramočuje, ker je ljubezen Božja izlita v srcih naših po svetem Duhu, ki nam je dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 6, 'Kajti Kristus je svoj čas, ko smo mi bili še slabi, umrl za brezbožne;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 7, 'saj težko da umre kdo za pravičnega, dasi se za dobrega morda kdo odloči umreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 8, 'Dokazuje pa Bog svojo ljubezen do nas s tem, da je Kristus umrl za nas, ko smo bili še grešniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 9, 'Koliko bolj bomo torej, ko smo zdaj opravičeni v krvi njegovi, po njem rešeni jeze božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 10, 'Kajti če smo bili spravljeni z Bogom s smrtjo njegovega Sina, ko smo bili še sovražniki, tem bolj bomo zdaj, ko smo spravljeni, zveličani po življenju njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 11, 'Pa ne samo to, marveč hvalimo se tudi z Bogom po Gospodu svojem Jezusu Kristusu, po katerem smo sedaj dobili spravo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 12, 'Zatorej, kakor je po enem človeku prišel greh na svet in po grehu smrt, in je tako na vse ljudi prišla smrt, zato ker so vsi grešili –;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 13, 'kajti greh je bil že pred postavo na svetu, toda greh se ne računi, dokler ni postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 14, 'Vendar pa je kraljevala smrt od Adama do Mojzesa tudi nad temi, ki niso grešili enako kakor Adam v svojem prestopku; Adam pa je podoba tega, ki je imel priti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 15, 'Ni pa prav enako z darom milosti kakor s pregreho: zakaj če so po pregrehi enega umrli mnogi, veliko bolj se je za mnoge pomnožila milost Božja in dar po milosti enega človeka, Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 16, 'In z darom ni kakor z obsodbo po enem, ki se je pregrešil: zakaj sodba je prišla iz enega v pogubljenje, dar milosti pa vodi iz mnogih pregreh v opravičenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 17, 'Kajti če je po pregrehi enega smrt kraljevala po tem enem, veliko bolj bodo tisti, ki prejemajo obilost milosti in dar pravičnosti, v življenju kraljevali po enem, Jezusu Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 18, 'Kakor je torej po pregrehi enega prišla obsodba na vse ljudi, tako je tudi po pravičnem delu enega prišlo na vse ljudi opravičenje življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 19, 'Kajti kakor so po neposlušnosti enega človeka grešni postali mnogi, tako bodo tudi po poslušnosti enega pravični postali mnogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 20, 'A postava je pristopila zraven, da se pomnoži pregreha. Kjer pa se je pomnožil greh, tam se je še veliko bolj pomnožila milost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 5, 21, 'da bi tako, kakor je greh kraljeval v smrti, kraljevala tudi milost po pravičnosti za večno življenje po Jezusu Kristusu, Gospodu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 1, 'Kaj torej porečemo? Bomo li ostali v grehu, da se milost pomnoži?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 2, 'Nikakor ne! Mi, ki smo umrli grehu, kako bomo še živeli v njem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 3, 'Ali pa ne veste, da smo se, katerikoli smo bili krščeni v Kristusa Jezusa, krstili v smrt njegovo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 4, 'Pokopani smo torej bili ž njim vred po krstu v smrt, da naj tako, kakor je vstal Kristus iz mrtvih po Očetovi slavi, hodimo tudi mi v novem življenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 5, 'Kajti če smo ž njim združeni po podobnosti njegove smrti, bomo tudi po podobnosti njegovega vstajenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 6, 'vedoč to, da je bil stari naš človek ž njim na križ razpet, da se zatare telo greha, da bi več ne sužnjevali grehu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 7, 'Zakaj kdor je umrl, je oproščen greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 8, 'Če smo pa umrli s Kristusom, verujemo, da bomo tudi živeli ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 9, 'ker vemo, da Kristus, obujen iz mrtvih, ne umrje več, smrt nad njim ne gospoduje več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 10, 'Kajti s smrtjo, ki jo je storil, je umrl grehu enkrat za vselej; življenje pa, ki ga živi, živi Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 11, 'Tako tudi vi sodite o sebi, da ste mrtvi grehu, a živi Bogu v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 12, 'Naj torej ne kraljuje greh v vašem smrtnem telesu, da poslušate poželenja njegova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 13, 'Tudi ne dajajte svojih udov grehu za orožje krivice, temuč dajte sebe Bogu, kakor kateri ste bili mrtvi in zdaj ste živi, in ude svoje dajte Bogu za orožje pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 14, 'Kajti greh ne bo nad vami gospodoval, ker niste pod postavo, ampak pod milostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 15, 'Kaj torej? bomo li grešili, ker nismo pod postavo, ampak pod milostjo? Nikakor ne!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 16, 'Ne veste li, če dajete sebe za hlapce v pokorščino, da ste hlapci tistemu, kogar poslušate: ali grehu za smrt, ali pa poslušnosti za pravičnost?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 17, 'A hvala Bogu, da ste bili sužnji grehu, pa ste iz srca postali pokorni obliki nauka, ki ste vanj bili postavljeni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 18, 'osvobojeni pa greha, ste postali služabniki pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 19, 'Po človeško govorim zavoljo slabosti vašega mesa. Kakor ste namreč dali svoje ude v sužnost nečistosti in nepravičnosti, da bi delali nepravičnost, tako dajte sedaj svoje ude v službo pravičnosti v posvečenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 20, 'Kajti ko ste bili sužnji greha, ste bili svobodni glede pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 21, 'Kakšen sad ste torej imeli takrat od tega, česar se sedaj sramujete? Kajti konec tega je smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 22, 'Sedaj pa, ko ste osvobojeni greha in ste postali Božji služabniki, imate sad svoj, ki vodi v posvečenje, a konec večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 6, 23, 'Kajti plačilo za greh je smrt, a milostni dar Božji je večno življenje v Kristusu Jezusu, Gospodu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 1, 'Ali pa ne veste, bratje (govorim namreč tistim, ki poznajo postavo), da postava gospoduje človeku, kolikor časa živi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 2, 'Kajti omožena žena je s postavo privezana na moža, dokler on živi; če ji pa mož umre, je oproščena postave moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 3, 'Zato se bo torej prešeštnica imenovala, če postane žena drugemu možu, dokler njen mož živi; če pa mož umre, je prosta postave, da ne bo prešeštnica, če se omoži z drugim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 4, 'Tako, bratje moji, ste tudi vi umrli postavi po smrti telesa Kristusovega, da boste zvezani z drugim, s tistim namreč, ki je iz mrtvih vstal, da sad obrodimo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 5, 'Kajti ko smo bili v mesu, so delovale v naših udih grešne strasti, zbujene po postavi, da obrode sad smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 6, 'Sedaj pa smo oproščeni postave, ko smo odmrli temu, kar nas je vezalo, tako da služimo v novosti duha in ne v starini črke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 7, 'Kaj torej porečemo? da je postava greh? Nikakor ne! Ali greha nisem spoznal, razen po postavi. Saj tudi za poželenje ne bi bil vedel, ko bi postava ne velela: Ne poželi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 8, 'Ko je pa priložnost dobil greh, je po zapovedi napravil v meni vsakršno poželenje; zakaj greh brez postave je mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 9, 'Jaz pa sem živel brez postave nekdaj; ali ko je prišla zapoved, je greh oživel,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 10, 'jaz pa sem umrl; in pokazalo se je, da mi je ta zapoved, ki naj bi bila za življenje, za smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 11, 'Zakaj greh, dobivši priložnost, me je po zapovedi ukanil in ž njo umoril.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 12, 'Tako je postava res sveta, in zapoved je sveta in pravična in dobra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 13, 'Ali je torej to, kar je dobro, meni postalo smrt? Nikakor ne! Temuč greh mi je postal smrt, da se pokaže kot greh, pripravljajoč mi z dobrim smrt, da tako postane greh čez mero grešen po zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 14, 'Vemo namreč, da je postava duhovna, a jaz sem mesen, suženjski prodan grehu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 15, 'Kajti kar delam, ne umejem: ker kar hočem, tega ne delam, nego kar sovražim, to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 16, 'Če pa to delam, česar nočem, pritrjujem postavi, da je dobra.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 17, 'Sedaj pa ne delam tega več jaz, temuč v meni prebivajoči greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 18, 'Kajti vem, da ne prebiva v meni, to je, v mojem mesu, dobro. Hoteti dobro, to je pač pri meni, ali izvrševati dobro, tega ni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 19, 'Dobrega namreč, kar hočem, ne delam, ampak hudo, česar nočem, prav to delam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 20, 'Če pa to delam, česar nočem, ne delam tega več jaz, temuč v meni prebivajoči greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 21, 'Kaže se mi torej ta postava: kadar hočem dobro delati, se me drži hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 22, 'Kajti veselim se postave Božje po notranjem človeku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 23, 'ali v svojih udih vidim drugačno postavo, ki se ustavlja postavi uma mojega in me ima ujetega v postavi greha, katera je v mojih udih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 24, 'Jaz nesrečni človek! kdo me otme iz telesa te smrti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 7, 25, 'Hvala bodi Bogu po Jezusu Kristusu, Gospodu našem! Tako torej jaz sam z umom služim postavi Božji, a z mesom postavi greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 1, 'Zatorej ni sedaj nobene obsodbe za te, ki so v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 2, 'Zakaj postava Duha življenja v Kristusu Jezusu me je osvobodila postave greha in smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 3, 'Kar je namreč bilo postavi nemogoče, v čemer je bila nezmožna zaradi mesa, to je storil Bog, ko je poslal svojega Sina v podobnosti grešnega mesa in kot daritev za greh, in je greh obsodil v mesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 4, 'da se izpolni pravična zahteva postave v nas, ki živimo ne po mesu, ampak po duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 5, 'Kajti kateri so po mesu, mislijo na to, kar je mesenega, a kateri so po duhu, na to, kar je duhovnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 6, 'Kajti meseno mišljenje je smrt, a duhovno mišljenje je življenje in mir;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 7, 'zato ker je meseno mišljenje sovraštvo do Boga, ker se Božji postavi ne pokorava, saj se tudi ne more.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 8, 'Kateri so pa v mesu, Bogu ne morejo biti prijetni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 9, 'A vi niste v mesu, ampak v duhu, ako Božji Duha prebiva v vas. Če pa kdo Duha Kristusovega nima, ta ni njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 10, 'Če je pa Kristus v vas, je sicer telo mrtvo zavoljo greha, duh pa je življenje zavoljo pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 11, 'Če pa Duh tistega, ki je obudil Jezusa iz mrtvih, prebiva v vas, on, ki je obudil Kristusa Jezusa iz mrtvih, oživi tudi smrtna telesa vaša zaradi Duha svojega, ki prebiva v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 12, 'Tako torej, bratje, nismo dolžniki mesu, da živimo po mesu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 13, 'zakaj če po mesu živite, umrjete, če pa z Duhom morite dejanja mesa, boste živeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 14, 'Kajti katerekoli vodi Duh Božji, ti so sinovi Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 15, 'Niste namreč prejeli duha sužnosti zopet v bojazen, ampak prejeli ste Duha sinovstva, ki v njem kličemo: Aba, Oče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 16, 'Ta Duh sam izpričuje z našim duhom vred, da smo otroci Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 17, 'Če smo pa otroci, smo tudi dediči, in sicer dediči Božji in sodediči Kristusovi, ako ž njim trpimo, da se tudi ž njim oslavimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 18, 'Mislim namreč, da trpljenje sedanjega časa ni vredno, da se primerja prihodnji slavi, ki se ima razodeti na nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 19, 'Kajti koprnenje vseh stvari pričakuje razodetja sinov Božjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 20, 'Zakaj stvari so podvržene ničemurnosti, ne iz lastne volje, ampak zavoljo tistega, ki jih je podvrgel, z upanjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 21, 'da bo tudi stvarstvo samo rešeno iz sužnjevanja minljivosti v svobodo slave otrok Božjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 22, 'Vemo namreč, da vse stvarstvo skupno zdihuje in je v porodnih bolečinah prav do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 23, 'Pa ne samo ono, temuč i mi sami, ki imamo prvine Duha, tudi mi sami v sebi zdihujemo, čakajoč sinovstva, odrešitve svojega telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 24, 'V upanju namreč smo zveličani; upanje pa, ki se vidi, ni upanje; saj če kdo kaj vidi, čemu bi se tega še nadejal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 25, 'Če pa upamo, česar ne vidimo, čakamo tega s potrpežljivostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 26, 'Enako pa pomaga tudi Duh našim slabostim. Kajti česa naj prosimo, kakor je treba, ne vemo; temuč Duh sam prosi za nas z neizrečnimi vzdihi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 27, 'Ta pa, ki preiskuje srca, ve, kaj je misel Duha, ker po volji Božji prosi za svetnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 28, 'Vemo pa, da tem, ki Boga ljubijo, vse služi v dobro, tem, ki so poklicani po sklepu Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 29, 'Kajti katere je naprej spoznal, te je tudi vnaprej odločil, da bodo enaki podobi njegovega Sinu, da bi on prvorojenec bil med mnogimi brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 30, 'In katere je naprej odločil, te je tudi poklical, in katere je poklical, te je tudi opravičil, in katere je opravičil, te je tudi oslavil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 31, 'Kaj torej porečemo na to? Če je Bog z nami, kdo je proti nam?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 32, 'On, ki lastnemu Sinu ni prizanesel, temuč ga je dal za nas vse, kako ne bo tudi ž njim nam vsega podaril?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 33, 'Kdo bo tožil proti izvoljencem Božjim? Bog je, ki jih opravičuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 34, 'Kdo je, ki jih bo obsodil? Kristus Jezus je, ki je umrl, pa je tudi vstal, ki je na desnici Boga, ki tudi prosi za nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 35, 'Kdo nas bo ločil od ljubezni Kristusove? stiska ali nadloga, ali preganjanje, ali lakota, ali nagota, ali nevarnost, ali meč?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 36, 'Kakor je pisano: „Zavoljo tebe nas moré ves dan, imajo nas kakor ovce za klanje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 37, 'Ali v vsem tem slavno premagujemo po tistem, ki nas je ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 38, 'Prepričan sem namreč, da nas ne smrt, ne življenje, ne angeli, ne poglavarstva, ne sile, ne sedanjost, ne prihodnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 8, 39, 'ne višina, ne globočina, ne katera druga stvar ne bo mogla ločiti od ljubezni Božje, ki je v Kristusu Jezusu, Gospodu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 1, 'Resnico govorim v Kristusu, ne lažem, to mi izpričuje moja vest v Duhu svetem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 2, 'da imam veliko žalost in neprestano bolečino v srcu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 3, 'Kajti želel bi, da bi bil jaz sam proklet in ločen od Kristusa za svoje brate, ki so mi v rodu po mesu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 4, 'oni so Izraelci, njim je bilo dano sinovstvo in slava in zaveze in postava in služba božja in obljube,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 5, 'njih so očaki, in iz njih je po mesu Kristus, ki je čez vse, Bog hvaljen na veke. Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 6, 'Ni pa tako, da je beseda Božja izgubila veljavo. Kajti niso vsi Izraelci, ki so od Izraela:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 7, 'niti zato, ker so seme Abrahamovo, niso vsi otroci, temuč: „V Izaku se ti bo imenovalo seme“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 8, 'to je: niso ti, ki so otroci mesa, otroci Božji, marveč otroci obljube se štejejo za seme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 9, 'Kajti beseda obljube je ta: „Ta čas pridem in Sara bo imela sina“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 10, 'Pa ne samo na tej, ampak tudi na Rebeki, ki je z enim imela dva otroka, z Izakom, očetom našim, se kaže isto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 11, 'Zakaj ko se še nista bila narodila, tudi ne storila nič dobrega ali hudega, da bi veljaven ostal sklep Božji po izbiri, ne zavoljo del, temuč zavoljo tistega, ki kliče,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 12, 'se ji je reklo: „Večji bo služil manjšemu“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 13, 'Kakor je pisano: „Jakoba sem ljubil, a Ezava sovražil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 14, 'Kaj torej porečemo? je li mar krivičnost pri Bogu? Nikakor ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 15, 'Kajti Mojzesu pravi: „Milosten bodem, komur sem milosten, in usmilil se ga bom, kogar se usmilim“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 16, 'To torej ni v moči tega, ki hoče, ne tega, ki se trudi, ampak Boga, ki je milosten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 17, 'Kajti pismo pravi Faraonu: „Prav zato sem te obudil, da pokažem na tebi svojo moč in da se razglasi moje ime po vsej zemlji“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 18, 'Tako torej komur hoče, je milosten, a kogar hoče, zakrkne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 19, 'Porečeš mi torej: Zakaj nas še dolži? ker kdo more njegovi volji nasprotovati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 20, 'Toda kdo si ti, o človek, da se pregovarjaš z Bogom? Poreče li izdelek izdelovalcu: Zakaj si me naredil tako?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 21, 'Nima li oblasti lončar nad glino, da iz iste grude naredi eno posodo za čast, a drugo za nečast?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 22, 'Kaj pa, če je Bog, hoteč pokazati jezo in razglasiti moč svojo, prenašal v veliki potrpežljivosti posode jeze, pripravljene za pogubo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 23, 'in da bi razglasil bogastvo slave svoje na posodah usmiljenja, ki jih je naprej pripravil za slavo...?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 24, 'ki jih je tudi poklical, namreč nas, ne samo izmed Judov, ampak tudi iz poganov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 25, 'kakor tudi pri Ozeu pravi: „Imenoval bom nemoje ljudstvo svoje ljudstvo, in neljubico ljubico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 26, 'in zgodi se, da na mestu, kjer se jim je reklo: Vi niste moje ljudstvo, tam se bodo imenovali sinovi Boga živega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 27, 'Izaija pa vpije nad Izraelom: „Ko bi bilo sinov Izraelovih kolikor morskega peska, le ostanek se bo zveličal“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 28, 'Kajti besedo svojo dokonča in ob kratkem izvrši Gospod na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 29, 'In kakor je naprej povedal Izaija: „Ko bi Gospod Sabaot nam ne pustil semena, bi bili postali kakor Sodoma in Gomori bi bili podobni“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 30, 'Kaj torej porečemo? Da so pogani, ki niso iskali pravičnosti, dobili pravičnost, toda pravičnost, ki je iz vere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 31, 'a Izrael, iščoč postave pravičnosti, ni dospel do take postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 32, 'Zakaj? Ker je niso iskali iz vere, ampak tako, kakor da bi bila iz del. Spoteknili so se ob kamen spotike,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 9, 33, 'kakor je pisano: „Glej, polagam v Sionu kamen spotike in skalo pohujšanja; in kdorkoli veruje vanj, ne bo osramočen“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 1, 'Bratje, želja mojega srca in molitev k Bogu za Izraelce je, da bi bili zveličani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 2, 'Kajti pričujem jim, da imajo gorečnost za Boga, ali ne po pravem spoznanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 3, 'Zakaj ne poznavajoč Božje pravičnosti in hoteč utrditi lastno pravičnost, se niso podvrgli pravičnosti Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 4, 'Kajti konec postave je Kristus, da prejme pravičnost vsak, ki veruje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 5, 'Mojzes namreč piše o pravičnosti, ki izvira iz postave: „Človek, ki je to storil, bo živel v njej“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 6, 'Toda pravičnost, ki je iz vere, govori tako: „Ne reci v srcu svojem: Kdo pojde gori v nebo? (to je, da Kristusa doli pripelje),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 7, 'niti: Kdo pojde doli v brezno? (to je, da Kristusa gori pripelje iz mrtvih)“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 8, 'Ali kaj govori? „Blizu tebe je beseda, v ustih tvojih in v srcu tvojem“, to je: beseda vere, ki jo oznanjujemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 9, 'Ker če pripoznaš z usti svojimi Jezusa za Gospoda in veruješ v srcu svojem, da ga je Bog obudil iz mrtvih, boš zveličan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 10, 'S srcem se namreč veruje za pravičnost, a z usti se pripoznava za zveličanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 11, 'Kajti pismo pravi: „Kdorkoli veruje vanj, ne bo osramočen“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 12, 'Ker ni razločka med Judom in pa Grkom, zakaj en in isti je Gospod vsem, bogat za vse, ki ga kličejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 13, 'Kajti „vsak, kdorkoli bo klical ime Gospodovo, bo zveličan“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 14, 'Kako pa bodo klicali tega, ki vanj niso verovali? kako bodo pa verovali, če niso o njem slišali? in kako bodo slišali brez propovednika?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 15, 'A kako bodo propovedovali, ako niso poslani? kakor je pisano: „Kako lepe so noge blagovestnikov miru, oznanjevalcev dobrega“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 16, 'Ali vsi niso bili poslušni evangeliju. Kajti Izaija pravi: „Gospod, kdo je veroval oznanilu, ki ga je slišal od nas?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 17, 'Vera je torej iz slišanega oznanila, oznanilo pa pride po besedi Kristusovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 18, 'Ali pravim: Niso li slišali? Seveda, saj „po vsej zemlji se je razširil njih glas in do koncev naseljenega sveta njih besede“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 19, 'Ali pravim: Ni li razumel Izrael? Prvi je Mojzes, ki pravi: „Jaz vas privedem k zavisti po ljudstvu, ki ni ljudstvo, po ljudstvu nerazumnem vas razjezim“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 20, 'A Izaija govori smelo in pravi: „Našli so me ti, ki me niso iskali, razodet sem bil tem, ki niso vpraševali po meni“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 10, 21, 'Glede Izraela pa pravi: „Ves dan sem iztezal roke svoje k ljudstvu nepokornemu in upornemu“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 1, 'Pravim torej: Je li Bog zavrgel ljudstvo svoje? Nikakor ne. Kajti tudi jaz sem Izraelec, iz semena Abrahamovega, iz rodu Benjaminovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 2, 'Ni zavrgel Bog ljudstva svojega, ki ga je naprej spoznal. Ali ne veste, kaj pravi pismo pri Eliju? kako toži Bogu zoper Izraela, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 3, '„Gospod, proroke tvoje so pomorili in oltarje tvoje so razkopali, in jaz sem ostal sam, in strežejo mi po življenju“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 4, 'Ali kaj pravi njemu Božji odgovor? „Ohranil sem sebi ostanek sedem tisoč mož, ki niso pripognili kolena pred Baalom“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 5, 'Tako je torej tudi v sedanjem času ostanek po izbiri milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 6, 'Če pa je iz milosti, ni več iz del, sicer bi milost več ne bila milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 7, 'Kaj torej? Česar išče Izrael, tega ni dosegel, a izbira je to dosegla; drugi so se pa zakrknili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 8, 'kakor je pisano: „Dal jim je Bog duha nesvesti, oči, da ne vidijo, in ušesa, da ne slišijo, do današnjega dne“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 9, 'In David pravi: „Naj jim postane njih miza za zanko in za lov in za spotiko in za povračilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 10, 'potemne naj jim oči, da ne vidijo, in njih hrbet pripogibaj vselej“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 11, 'Pravim torej: So li se spoteknili, da padejo? Nikakor ne; temuč po njih padcu je prišlo zveličanje poganom, da bi jih pogani zbudili v posnemanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 12, 'Če je pa njih padec bogastvo za svet in njih izguba bogastvo za pogane, koliko več prinese njih polno število?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 13, 'A vam poganom govorim. V kolikor sem torej apostol poganov, hvalim svojo službo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 14, 'ne bi li kako v posnemanje zbudil teh, ki so moje meso, in rešil katere izmed njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 15, 'Kajti če je njih zavrženje prineslo spravo svetu, kaj bode njih sprejetje nego življenje iz mrtvih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 16, 'Če so pa prvine svete, je sveto tudi testo, in če je korenina sveta, so svete tudi veje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 17, 'Če so pa bile nekatere veje odlomljene, in ti, ki si bil divja oljka, si bil vcepljen mednje in si postal sodeležnik oljkove korenine in maščobe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 18, 'ne hvali se proti vejam; če se pa hvališ, pomisli da ne nosiš ti korenine, temuč korenina tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 19, 'Porečeš torej: Odlomljene so bile veje, da bi bil jaz vcepljen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 20, 'Dobro, zavoljo nevere so bile odlomljene, ti pa z vero stojiš. Ne prevzetuj, ampak boj se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 21, 'Zakaj če Bog naravnim vejam ni prizanesel, tudi tebi ne prizanese.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 22, 'Glej torej dobroto in ostrost Božjo: nad temi, ki so padli, ostrost, a nad seboj dobroto, ako vztrajaš v dobroti; če ne, boš tudi ti posekan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 23, 'Oni pa bodo tudi vcepljeni, če ne ostanejo v neveri, zakaj Bog ima moč, da jih zopet vcepi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 24, 'Kajti če si ti bil odsekan od oljke, po naravi divje, in vcepljen proti naravi na plemenito oljko, koliko bolj bodo tile, ki so po naravi veje, vcepljeni na lastno oljko?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 25, 'Kajti nočem, bratje, da bi vi ne vedeli te skrivnosti (da bi se ne zdeli sami sebi razumni): da je trdokornost le deloma zadela Izraela, dokler ne pride polno število poganov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 26, 'in tako bo zveličan ves Izrael, kakor je pisano: „Pride s Siona Rešitelj in odvrne brezbožnosti od Jakoba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 27, 'In to jim je od mene zaveza, kadar odvzamem njih grehe“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 28, 'Z ozirom na evangelij so sicer sovražniki zavoljo vas, a z ozirom na izbiro so ljubljenci zavoljo očetov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 29, 'Bogu namreč ni žal milostnih darov in svojega klicanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 30, 'Kajti kakor vi nekdaj niste bili pokorni Bogu, a sedaj ste usmiljenje dosegli vsled njih nepokornosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 31, 'tako tudi ti sedaj niso poslušali, da bi vsled usmiljenja, ki ste ga vi dosegli, tudi oni dobili usmiljenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 32, 'Zaprl je namreč Bog vse v nepokornost, da bi se vseh usmilil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 33, 'O globočina bogastva in modrosti in znanja Božjega! kako nedoumne so njegove sodbe in kako nezasledljive njegove poti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 34, 'Kajti kdo je spoznal misel Gospodovo? Ali kdo mu je bil svetovalec?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 35, 'ali kdo mu je prej dal kaj, da bi moral dobiti povračilo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 11, 36, 'Kajti iz njega in po njem in za njega je vse. Njemu slava na veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 1, 'Prosim vas torej, bratje, po mnogem usmiljenju Božjem, da podaste telesa svoja za žrtev živo, sveto, prijetno Bogu: to bodi pametno vaše bogoslužje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 2, 'In ne ravnajte se po tem svetu, temuč premenite se po obnovitvi uma svojega, da izkušate, kaj je volja Božja dobra in prijetna in popolna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 3, 'Kajti pravim po milosti, ki mi je dana, vsakemu, kdor je med vami, naj ne misli o sebi več, nego se spodobi misliti, temuč naj pazi, da bi mislil zmerno, kakor je Bog vsakemu podelil mero vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 4, 'Kajti kakor imamo v enem telesu mnoge ude, a vsi udje nimajo istega opravila,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 5, 'tako smo mnogi eno telo v Kristusu, poedini pa smo udje drug drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 6, 'Ker pa imamo razne darove po milosti, ki nam je dana: bodisi proroštvo, prorokujmo po razmeri svoje vere;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 7, 'ali službo, bodimo pridni v službi; ali če kdo uči, bodi marljiv v učenju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 8, 'ali če kdo opominja, v opominjanju; kdor podeljuje, delaj to v preprostosti, kdor je čez kaj postavljen, v skrbljivosti, kdor izkazuje usmiljenje, z veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 9, 'Ljubezen bodi nehinavska. Sovražite hudo, držite se dobrega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 10, 'Z bratovsko ljubeznijo srčno ljubite drug drugega, v spoštovanju dajajte prednost drug drugemu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 11, 'v marljivosti bodite neumorni, v duhu bodite goreči, Gospodu služite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 12, 'v upanju se veselite, v stiski bodite potrpežljivi, v molitvi stanovitni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 13, 'v potrebah pomagajte svetim, gojite gostoljubnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 14, 'Blagoslavljajte tiste, ki vas preganjajo, blagoslavljate, a ne preklinjajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 15, 'Veselite se z veselimi in jokajte z jokajočimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 16, 'Bodite ene misli med seboj; ne mislite visoko, temuč sočustvujte z nizkimi. Ne zdite se razumni sami sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 17, 'Nikomur ne vračajte hudega za hudo. Premišljujte to, kar bi bilo dobro vpričo vseh ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 18, 'Če je mogoče, kolikor je v vaši moči, imejte mir z vsemi ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 19, 'Ne maščujte se sami, ljubljeni, temuč dajte mesta jezi Božji; kajti pisano je: „Moje je maščevanje, jaz povrnem, govori Gospod“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 20, 'Temuč ako je lačen tvoj sovražnik, ga nasiti, ako je žejen, ga napoji; kajti če to delaš, mu nakopičiš žerjavico na glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 12, 21, 'Ne daj se hudemu premagati, ampak premaguj v dobrem hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 1, 'Slednji človek bodi pokoren višjim oblastim; ni je namreč oblasti razen od Boga, in oblasti, katere so, so postavljene od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 2, 'Kdor torej nasprotuje oblasti, se upira naredbi Božji; kateri se pa upirajo, prejmo sebi sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 3, 'Kajti poglavarji niso za strah dobremu delu, ampak hudemu. Hočeš li pa, da ne bi se bal oblasti? Dobro delaj, in imel boš hvalo od nje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 4, 'Božja namreč je služabnica, tebi v dobro. Ako pa delaš hudo, boj se: zakaj zastonj ne nosi meča, ker je Božja služabnica, maščevalka v kaznovanje tega, ki dela hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 5, 'Zato se je treba pokoravati, ne samo zavoljo kazni, ampak tudi zavoljo vesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 6, 'Saj zato tudi plačujete davke; zakaj služabniki so Božji, pa se prav s tem stanovitno pečajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 7, 'Dajte torej vsakemu, kar ste dolžni: komur davek, davek; komur carino, carino; komur strah, strah; komur čast, čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 8, 'Nikomur ne bodite ničesar dolžni, razen da ljubite drug drugega; kajti kdor ljubi drugega, je izpolnil postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 9, 'Kajti: Ne prešeštvuj, ne ubijaj, ne kradi, ne poželi, in če je katera druga zapoved, tale beseda jo obsega: Ljubi bližnjega svojega kakor samega sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 10, 'Ljubezen bližnjemu ne napravlja hudega. Izpolnitev postave je torej ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 11, 'In to delajte, vedoč za čas, da je ura, da se že iz spanja zbudimo; kajti sedaj nam je zveličanje bliže, nego kadar smo sprejeli vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 12, 'Noč je skoraj minila, a dan se je približal. Odvrzimo torej dela tmine, a oblecimo se v orožje svetlosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 13, 'Kakor po dnevi živimo spodobno, ne v požrešnosti in pijančevanju, ne v nečistostih in razuzdanostih, ne v prepiru in zavisti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 13, 14, 'ampak oblecite Gospoda Jezusa Kristusa, in ne delajte si skrbi za meso, da mu strežete v poželenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 1, 'A slabotnega v veri sprejemajte medse, toda ne na presojanje dvomljivih misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 2, 'Eden verjame, da sme vse jesti, kdor pa je slabič, jé le zelenjavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 3, 'Kdor ješ, ne zaničuj tistega, ki ne jé; kdor pa ne ješ, ne sodi tistega, ki jé, kajti Bog ga je sprejel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 4, 'Ti kdo si, da sodiš tujega hlapca? Lastnemu gospodarju stoji ali pade. Saj on vstane, kajti Gospod ga ima moč postaviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 5, 'Eden razloča dan od dneva, a drugi sodi, da so vsi dnevi enaki. Vsak bodi v lastnem razumu popolnoma prepričan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 6, 'Kdor pazi na dan, pazi Gospodu; in kdor jé, jé Gospodu, ker zahvaljuje Boga, in kdor ne jé, ne jé Gospodu, in zahvaljuje Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 7, 'Zakaj nihče nas ne živi sebi, in nihče ne umre sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 8, 'Kajti, če živimo, živimo Gospodu, in če mrjemo, mrjemo Gospodu; če torej živimo, če mrjemo, smo Gospodovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 9, 'zato je namreč Kristus umrl in zopet oživel, da gospoduje i mrtvim i živim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 10, 'Ti pa, zakaj sodiš brata svojega? ali tudi ti, zakaj zaničuješ brata svojega? Saj se vsi postavimo pred sodni stol Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 11, 'Kajti pisano je: „Kakor živim jaz, govori Gospod, meni se bo pripognilo vsako koleno, in vsak jezik bo pripoznaval Boga“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 12, 'Tako bo torej vsakdo izmed nas zase odgovor dajal Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 13, 'Nič več torej ne sodimo drug drugega; presojajte pa tem bolj, kako ne bi dajali spotike bratu ali pohujšanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 14, 'Vem in prepričan sem v Gospodu Jezusu, da ni nič nečisto samo na sebi; samo če kdo misli, da je kaj nečisto, je za njega nečisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 15, 'Kajti če se zavoljo jedi tvoj brat žalosti, ne ravnaš več po ljubezni. Ne pogubljaj s svojo jedjo tistega, ki je zanj umrl Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 16, 'Ne dajte torej, da se preklinja vaša dobrina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 17, 'Zakaj kraljestvo Božje ni jed, ne pijača, ampak pravičnost in mir in radost v svetem Duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 18, 'Kajti kdor v tem služi Kristusu, je prijeten Bogu in cenjen ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 19, 'Tako se torej poganjajmo za to, kar služi v mir in s čimer pospešimo napredek drug drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 20, 'Zavoljo jedi ne razdiraj dela Božjega! Vse je sicer čisto, ali v zlo je človeku, ki uživa s spotiko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 21, 'Dobro je, ne jesti mesa in ne piti vina, ne storiti ničesar, ob čemer bi se brat tvoj spotikal ali pohujševal ali slabil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 22, 'Vero, ki jo ti imaš, sam zase imej pred Bogom. Blagor mu, kdor ne sodi sam sebe v tem, kar ima za dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 14, 23, 'Kdor pa dvomi in vendar jé, je obsojen, ker tega ne dela iz vere; vse pa, kar ni iz vere, je greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 1, 'Dolžni pa smo mi, ki smo močni, nositi slabosti slabotnih in ne samim sebi pogodu delati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 2, 'Vsak izmed vas bodi bližnjemu pogodu, v dobro, za njegov napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 3, 'Kajti tudi Kristus ni sebi pogodu storil, temuč kakor je pisano: „Zasramovanje tistih, ki so tebe zasramovali, je zadelo mene“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 4, 'Karkoli se je namreč poprej napisalo, je pisano nam v pouk, da imamo po potrpežljivosti in po tolažbi pisem upanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 5, 'A Bog potrpežljivosti in tolažbe vam daj ene misli biti med seboj po Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 6, 'da enodušno, z enimi usti slavite Boga in Očeta Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 7, 'Zato sprejemajte drug drugega, kakor je tudi Kristus sprejel vas, Bogu v slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 8, 'Pravim namreč, da je Kristus postal služabnik obreze zavoljo resnice Božje, da bi potrdil obljube, dane očetom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 9, 'pogani pa da zavoljo usmiljenja proslavljajo Boga, kakor je pisano: „Zato te bom pripoznaval med pogani in imenu tvojemu prepeval“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 10, 'In zopet pravi: „Veselite se, pogani, ž njegovim ljudstvom“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 11, 'In zopet: „Hvalite Gospoda, vsi pogani, in slavite ga, vsa ljudstva“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 12, 'In zopet Izaija pravi: „Pride korenina Jesejeva in on, ki vstane, da gospoduje poganom; vanj bodo upali pogani“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 13, 'Bog upanja pa naj vas napolni z vsem veseljem in mirom v verovanju, da ste prebogati v upanju, v moči svetega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 14, 'Prepričan sem pa, bratje moji, tudi jaz sam za vas, da ste tudi vi sami polni dobrote, napolnjeni vsakega znanja, sposobni tudi drug drugega opominjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 15, 'Pa sem vam po nekoliko drzneje pisal, da vam oživim v spominu to, kar že veste, zaradi milosti, ki mi jo je dal Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 16, 'da bi bil služabnik Kristusa Jezusa za pogane, opravljajoč sveto službo evangelija Božjega, da postane daritev poganov prijetna, posvečena v svetem Duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 17, 'Imam se torej s čim hvaliti v Kristusu Jezusu v tem, kar zadeva Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 18, 'Kajti ne drznem se govoriti kaj, česar ni napravil Kristus po meni za izpreobrnjenje poganov k poslušnosti, z besedo in z dejanjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 19, 'v moči znamenj in čudežev, v moči svetega Duha; tako da sem od Jeruzalema in po sosednjih krajih tja do Ilirije povsod razširil evangelij Kristusov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 20, 'pri tem pa mi je bilo najbolj do tega, da ne oznanjam evangelija tam, kjer se je že imenoval Kristus, da bi ne zidal na tuji podlagi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 21, 'marveč kakor je pisano: „Katerim se ni oznanilo o njem, bodo videli, in kateri niso slišali, bodo razumeli“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 22, 'To me je tudi najbolj oviralo, da nisem prišel k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 23, 'Sedaj pa, ko mi ni več mesta v teh krajih, željo pa imam priti k vam že več let,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 24, 'kadar pojdem na Špansko, pridem k vam. Upam vas namreč videti, potujoč skozi Rim, in da me boste spremili tja, ko se pri vas prej nekoliko poživim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 25, 'Sedaj pa potujem v Jeruzalem služit svetim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 26, 'Macedonija in Ahaja sta namreč sklenili nabrati nekak sklad za uboge onih svetih, ki so v Jeruzalemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 27, 'Tako sta sklenili, in tudi dolžni sta jim: kajti če so pogani postali deležniki njih duhovnih stvari, so jim dolžni tudi v telesnih stvareh postreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 28, 'Ko torej to izvršim in jim zapečatim ta sad ljubezni, odpotujem preko vas na Špansko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 29, 'Kadar pa pridem k vam, vem, da pridem v obilosti blagoslova Kristusovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 30, 'Prosim pa vas, bratje, po Gospodu našem Jezusu Kristusu in po ljubezni Duha, da se borite z menoj vred v molitvah zame k Bogu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 31, 'da se rešim tistih, ki ne verujejo v Judeji, in da bode moja služba, ki me pelje v Jeruzalem, prijetna svetim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 32, 'da v radosti pridem k vam po volji Božji in si skupaj z vami odpočijem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 15, 33, 'A Bog miru bodi z vsemi vami. Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 1, 'Priporočam vam pa Febo, sestro našo, ki je služabnica cerkve v Kenhrejah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 2, 'da jo sprejmete v Gospodu, kakor se spodobi svetim, in ji pomorete, v katerikoli stvari bi vas potrebovala; kajti tudi ona je bila pomočnica mnogim, tudi samemu meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 3, 'Pozdravite Prisko in Akvila, sodelavca moja v Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 4, 'ki sta za življenje moje svoj vrat podvrgla, ki sem jima ne samo jaz hvaležen, temuč tudi vse cerkve poganov:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 5, 'pozdravite tudi cerkev, ki se shaja v njiju hiši. Pozdravite Epeneta, ljubljenega mojega, ki je prvina Azije za Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 6, 'Pozdravite Marijo, ki se je veliko potrudila za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 7, 'Pozdravite Andronika in Junija, moja sorodnika in moja sojetnika, ki sta sloveča pri apostolih in ki sta bila tudi pred menoj v Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 8, 'Pozdravite Amplija, ljubljenega mojega v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 9, 'Pozdravite Urbana, sodelavca našega v Kristusu, in Stahija, ljubljenega mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 10, 'Pozdravite Apela, izkušenega v Kristusu. Pozdravita verne iz družine Aristobulove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 11, 'Pozdravite Herodiona, sorodnika mojega. Pozdravite tiste iz družine Narcisove, ki so v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 12, 'Pozdravite Trifeno in Trifozo, ki delujeta v Gospodu. Pozdravite Perzido ljubljeno, ki se je veliko potrudila v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 13, 'Pozdravite Rufa, izbranega v Gospodu, in mater njegovo i mojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 14, 'Pozdravite Asinkrita, Flegonta, Herma, Patroba, Hermeja in brate, ki so ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 15, 'Pozdravite Filologa in Julijo, Nereja in sestro njegovo in Olimpana in vse svete, ki so ž njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 16, 'Pozdravite drug drugega v svetem poljubu. Pozdravljajo vas vse cerkve Kristusove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 17, 'Prosim vas pa, bratje, da gledate na tiste, ki delajo razpore in pohujšanja proti nauku, ki ste se ga vi naučili, in ogibajte se jih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 18, 'Taki namreč ne služijo Gospodu našemu Kristusu, temuč svojemu trebuhu, in z dobrikavim govorom in lepo besedo prekanjujejo srca nedolžnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 19, 'Kajti vaše pokorščine glas se je med vse raznesel. Radujem se torej nad vami, želim pa, da ste modri za dobro, a preprosti za hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 20, 'Bog miru pa potre satana pod vaše noge v kratkem. Milost Gospoda našega Jezusa Kristusa z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 21, 'Pozdravljajo vas: Timotej, moj sodelavec, in Lucij in Jazon in Sosipater, sorodniki moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 22, 'Pozdravljam vas jaz Tercij, ki sem napisal ta list, v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 23, 'Pozdravlja vas Gaj, moj in vse cerkve gostilnik. Pozdravlja vas Erast, mestni blagajnik, in Kvart, brat. [');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 24, 'Milost Gospoda našega Jezusa Kristusa z vsemi vami. Amen.]');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 25, 'Tistemu pa, ki vas more utrditi, kakor obeta evangelij moj in oznanjevanje Jezusa Kristusa v soglasju z odkritjem skrivnosti, ki je bila večne čase zamolčana,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 26, 'a sedaj je razodeta in se po proroških pismih, vsled zapovedi večnega Boga, oznanjuje vsem narodom, da se razširi poslušnost veri -');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (45, 16, 27, 'samemu modremu Bogu, po Jezusu Kristusu, njemu bodi slava na veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 1, 'Pavel, poklican apostol Jezusa Kristusa po volji Božji, in Sosten, brat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 2, 'cerkvi Božji, ki je v Korintu, posvečenim v Kristusu Jezusu, poklicanim svetim, z vsemi, ki kličejo ime Gospoda našega Jezusa Kristusa na vsakem mestu, svojem in našem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 3, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 4, 'Zahvaljujem Boga svojega vsekdar za vas, za milost Božjo, dano vam v Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 5, 'da ste v vsem obogateli v njem, v vsaki besedi in v vsakem spoznanju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 6, 'kakor se je pričevanje Kristusovo utrdilo med vami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 7, 'tako da ne primanjkuje nobenega daru milosti vam, ki pričakujete razodetja Gospoda našega Jezusa Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 8, 'ki vas tudi utrdi do konca, da bodete brez graje v dan Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 9, 'Zvest je Bog, po katerem ste poklicani v deleštvo Sinu njegovega, Jezusa Kristusa, Gospoda našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 10, 'Prosim vas pa, bratje, v imenu Gospoda našega Jezusa Kristusa, da vsi eno govorite in ne bodi razdorov med vami, temuč bodite popolnoma složni v enem umu in eni misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 11, 'Povedali so mi namreč za vas, bratje moji, Hlojini domači, da so prepiri med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 12, 'Menim pa to, da vsak vas govori: Jaz sem Pavlov, jaz pa Apolov, jaz pa Kefov, a jaz Kristusov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 13, 'Je li Kristus razdeljen? je li bil Pavel na križ razpet za vas, ali ste bili v ime Pavlovo krščeni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 14, 'Hvalim Boga, da nisem nikogar vas krstil razen Krispa in Gaja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 15, 'da kdo ne poreče, da ste bili krščeni v moje ime.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 16, 'Krstil sem pa tudi Štefanovo družino; sicer ne vem, če sem še koga krstil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 17, 'Zakaj Kristus me ni poslal krščevat, temuč oznanjevat evangelij, ne v modrosti besede, da se ne uniči moč križa Kristusovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 18, 'Kajti beseda o križu je tistim, ki gredo v pogubo, neumnost, nam pa, ki se zveličujemo, je moč Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 19, 'Kajti pisano je: „Pogubim modrost modrih in razumnost razumnih zavržem“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 20, 'Kje je modrijan? Kje pismouk? Kje preiskovalec tega sveta? Ni li Bog v neumnost preobrnil modrosti tega sveta?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 21, 'Ker namreč svet v modrosti Božji ni spoznal Boga po svoji modrosti, je sklenil Bog po neumnosti oznanjevanja zveličati te, kateri verujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 22, 'Kajti i Judje zahtevajo znamenj, i Grki iščejo modrosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 23, 'Mi pa oznanjujemo Kristusa na križ razpetega, Judom resda pohujšanje, poganom pa neumnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 24, 'ali tistim, ki so poklicani, i Judom i Grkom, Kristusa, Božjo moč in Božjo modrost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 25, 'Ker ‚neumnost‘Božja je modrejša od ljudi in ‚slabost‘Božja močnejša od ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 26, 'Kajti glejte poklic svoj, bratje, da ni poklicanih mnogo modrih po mesu, ne mnogo mogočnih, ne mnogo imenitnih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 27, 'marveč kar je neumnega na tem svetu, to si je Bog izbral, da osramoti modre, in kar je slabotnega na tem svetu, to si je Bog izbral, da osramoti, kar je mogočnega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 28, 'in kar je neimenitno na tem svetu in zaničevano, si je izbral Bog in to, česar ni, da uniči to, kar je:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 29, 'da se ne hvali nobeno meso pred obličjem Božjim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 30, 'Iz njega pa ste vi v Kristusu Jezusu, ki nam je postal modrost od Boga, pa tudi pravičnost in posvečenje in odrešenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 1, 31, 'da, kakor je pisano, „kdor se hvali, v Gospodu naj se hvali“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 1, 'Tudi jaz, ko sem prišel k vam, bratje, nisem prišel z visokostjo besede ali modrosti oznanjevat vam pričevanja Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 2, 'Odločil sem se namreč, da ne bom vedel kaj drugega med vami razen Jezusa Kristusa in tega na križ razpetega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 3, 'In bil sem pri vas v slabosti in v strahu in mnogem trepetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 4, 'In govor moj in propovedovanje moje ni bilo v prepričevalnih besedah človeške modrosti, temuč v dokazovanju Duha in moči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 5, 'da bi vera vaša ne slonela na modrosti človeški, ampak na moči Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 6, 'Vendar pa modrost govorimo med popolnimi, a ne modrosti tega sveta niti poglavarjev tega sveta, kateri ginejo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 7, 'marveč govorimo modrost Božjo v skrivnosti, tisto skrito modrost, ki jo je naprej odločil Bog pred veki za našo slavo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 8, 'ki je ni nihče izmed poglavarjev tega sveta spoznal; ker ko bi jo bili spoznali, ne bi bili Gospoda slave razpeli na križ; temuč kakor je pisano:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 9, '„Česar oko ni videlo in uho ni slišalo in kar v srce človeku ni prišlo, to je pripravil Bog tem, kateri ga ljubijo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 10, 'Nam pa je to Bog razodel po Duhu svojem; kajti Duh vse preiskuje, tudi globočine Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 11, 'Kajti kdo ve izmed ljudi, kaj je v človeku, razen človekovega duha, ki je v njem? Tako tudi ne ve nihče, kaj je v Bogu, razen le Božji Duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 12, 'Mi pa nismo prejeli duha tega sveta, ampak Duha, ki je iz Boga, da vemo, kaj nam je milostno daroval Bog;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 13, 'to tudi govorimo, ne v besedah, ki jih uči človeška modrost, temuč v teh, ki jih uči Duh, in duhovne stvari skladamo z duhovnimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 14, 'Telesni človek pa ne sprejema, kar je Duha Božjega, ker mu je neumnost in ne more tega umeti, ker se mora duhovno razsojati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 15, 'Duhovni človek pa razsoja vse; a njega samega ne razsoja nihče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 2, 16, 'Kajti „kdo je spoznal um Gospodov, da bi ga poučil?“Mi pa imamo um Kristusov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 1, 'Tudi jaz, bratje, nisem mogel govoriti vam kakor duhovnim, temuč kakor mesenim, kakor nedoraslim v Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 2, 'Mleka sem vam dal piti, ne jedi, kajti niste je še zmogli; pa tudi še sedaj je ne zmorete,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 3, 'ker ste še meseni. Kajti kjer je med vami zavist in prepir, niste li meseni in ne postopate li po človeški?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 4, 'Če namreč kdo pravi: ‚Jaz sem Pavlov‘, a drugi: ‚Jaz sem Apolov‘, niste li meseni ljudje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 5, 'Kaj je torej Apolo? in kaj je Pavel? Služabnika sta, po katerih ste vero sprejeli, in to, kakor je Gospod vsakteremu dal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 6, 'jaz sem sadil, Apolo je zalil, ali Bog je dal, da je zraslo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 7, 'Tako ni ne tisti kaj, kateri sadi, ne, kateri zaliva, temuč ki daje rasti, Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 8, 'Ta pa, ki sadi in ki zaliva, sta eno; vsak pa prejme svoje plačilo po lastnem trudu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 9, 'Božji namreč smo sodelavci; Božja njiva, Božje poslopje ste vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 10, 'Po milosti Božji, ki mi je dana, sem položil kakor modri zidar temelj, a drug nanj zida; ali vsak naj gleda, kako nanj zida.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 11, 'Kajti drugega temelja ne more nihče položiti razen tega, ki je položen, ki je Jezus Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 12, 'Če pa kdo zida na ta temelj zlato, srebro, drago kamenje, drva, seno, strn:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 13, 'vsakega delo postane očitno; kajti dan ga razodene, ker se v ognju odkrije, in ogenj preizkusi delo vsakega, kakšno je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 14, 'Če ostane komu delo, katero je postavil na njem, prejme plačilo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 15, 'če komu delo zgori, prejme škodo, sam pa bo zveličan, ali tako, kakor po ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 16, 'Ne veste, da ste tempelj Božji in da Duh Božji prebiva v vas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 17, 'Če kdo pokvari tempelj Božji, tega pogubi Bog; zakaj tempelj Božji je svet, kateri ste vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 18, 'Nihče naj sebe ne slepi! Če kdo misli, da je moder med vami na tem svetu, naj postane neumen, da postane moder.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 19, 'Kajti modrost tega sveta je neumnost pri Bogu. Pisano je namreč: „On zasačuje modre v njih lastni zvijači“;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 20, 'in zopet: „Gospod pozna misli modrih, da so prazne“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 21, 'Tako naj se nihče ne hvali z ljudmi. Kajti vse je vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 22, 'bodi si Pavel ali Apolo ali Kefa, bodisi svet ali življenje ali smrt, bodisi sedanje ali bodoče: vse je vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 3, 23, 'vi pa ste Kristusovi, a Kristus Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 1, 'Tako naj o nas misli človek, kakor da smo služabniki Kristusovi oskrbniki skrivnosti Božjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 2, 'Seveda se tu zahteva od oskrbnikov, da se vsak izkaže zvestega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 3, 'Meni je pa to najmanjše, da me sodite vi ali človeški sodni dan; ali tudi sam sebe ne sodim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 4, 'kajti ničesar nimam sam sebi očitati, ali to me ne opravičuje; sodnik pa mi je Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 5, 'Tako ne sodite ničesar pred časom, dokler ne pride Gospod, ki razsvetli, kar je skritega v temi, in odkrije misli src; in tedaj se hvala zgodi vsakemu od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 6, 'To sem pa, bratje, obrnil nase in na Apola zavoljo vas, da se od naju naučite ne više meriti, nego je pisano, da se nihče ne napihuje, vnet za enega zoper drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 7, 'Ker kdo je, ki te odlikuje? kaj pa imaš, česar nisi prejel? Če si pa tudi prejel, kaj se hvališ, kakor da nisi prejel?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 8, 'Že ste nasičeni, že ste obogateli, brez nas ste zakraljevali; in želim, da bi bili res zakraljevali, da bi mogli tudi mi z vami kraljevati!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 9, 'Mislim namreč, da je Bog nas apostole poslednje postavil kakor tiste, ki so odločeni za smrt, ker smo postali gledišče svetu, i angelom i ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 10, 'Mi smo neumni za voljo Kristusa, a vi razumni v Kristusu, mi slabi, a vi močni, vi slavni, a mi brez časti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 11, 'Prav dosore trpimo lakoto in žejo, in goli smo in bijejo nas za ušesa, in nimamo stalnega mesta');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 12, 'in trudimo se, delajoč z lastnimi rokami; ko nas zmerjajo, blagoslavljamo; ko nas preganjajo, voljno trpimo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 13, 'ko nas preklinjajo, molimo; kakor smeti sveta smo postali, izvržek vseh, prav do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 14, 'Ne pišem tega, da bi vas sramotil, marveč svarim vas kakor svoje ljubljene otroke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 15, 'Zakaj čeprav bi imeli deset tisoč učiteljev v Kristusu, vendar nimate mnogo očetov, ker v Kristusu Jezusu po evangeliju sem vas jaz rodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 16, 'Prosim vas torej, bodite moji posnemalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 17, 'Zato sem vam poslal Timoteja, ki je dete moje ljubljeno in verno v Gospodu, ki vas opomni mojih poti, ki so v Kristusu, kakor učim povsod v vsaki cerkvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 18, 'Nekateri pa so se napihnili, češ, da ne pridem k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 19, 'Ali pridem kmalu k vam, če Gospod hoče, in spoznam ne besed napihnjencev, ampak njih moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 20, 'Kajti ni v besedah kraljestvo Božje, temuč v moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 4, 21, 'Kaj hočete? da naj pridem k vam s šibo, ali z ljubeznijo in v duhu krotkosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 1, 'Sploh se sliši da je nečistost med vami, in to taka nečistost, kakršne še med pogani ni, da ima nekdo svojega očeta ženo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 2, 'In vi ste napihnjeni in niste bili rajši žalostni, da bi se odpravil izmed vas tisti, ki je storil tako delo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 3, 'Kajti jaz, sicer nenavzočen s telesom, a navzočen z duhom, sem že sodil, kakor da sem navzočen, tistega, ki je to tako storil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 4, 'da bodi v imenu Gospoda našega Jezusa, kadar se zberete vi in moj duh, z močjo Gospoda našega Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 5, 'izročen satanu na pogubo mesa, da se duh zveliča na dan Gospoda Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 6, 'Ni dobra hvala vaša. Ne veste li, da malo kvasu skisa vse testo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 7, 'Postrgajte torej stari kvas, da bodete novo testo, kakor ste opresni. Kajti tudi naše velikonočno jagnje je bilo darovano, Kristus:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 8, 'zato praznujmo ne v starem kvasu, tudi ne v kvasu hudobnosti in malopridnosti, temuč v presnini čistote in resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 9, 'Pisal sem vam v listu, da se ne mešajte z nečistniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 10, 'ne sploh z nečistniki tega sveta, ali z lakomniki, ali roparji, ali malikovci, ker bi sicer morali oditi s tega sveta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 11, 'ampak pisal sem vam, meneč, da se ne mešate, če je ta, ki se brat imenuje, nečistnik, ali lakomnik, ali malikovalec, ali opravljivec, ali pijanec, ali ropar: s takim da še ne jeste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 12, 'Kajti kaj je meni mari, da sodim tiste, ki so zunaj? Ne sodite vi tistih, ki so notri?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 5, 13, 'Kateri so pa zunaj, tiste bo sodil Bog. Odpravite hudobnika izmed sebe!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 1, 'Drzne li se kdo izmed vas, ko ima tožbo zoper drugega, pravdati se pred nepravičnimi in ne pred svetimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 2, 'Ali pa ne veste, da bodo sveti sodili svet? In če bo po vas sojen svet, kaj ste nevredni, da sodite najmanjše stvari?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 3, 'Ne veste, da bomo angele sodili? kaj še stvari, ki se tičejo tega življenja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 4, 'Kadar imate torej sodbe, ki se tičejo tega življenja, ali postavljate za sodnike tiste, ki niso nič cenjeni v cerkvi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 5, 'Na sramoto vam govorim. Tako torej ni modrega med vami ne enega, ki bi mogel razsoditi med brati svojimi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 6, 'Ampak brat se z bratom pravda in to pred neverniki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 7, 'Že to je res celo slabo pri vas, da imate sodbe med seboj. Zakaj si ne daste rajši krivice delati? zakaj se rajši ne daste oškodovati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 8, 'Temuč vi delate krivico in napravljate škodo, in to bratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 9, 'Ali pa ne veste, da krivičniki ne podedujejo kraljestva Božjega? Ne motite se: ne nečistniki, ne malikovalci, ne prešeštniki, ne mehkuži, ne moželežniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 10, 'ne tatje, ne lakomniki, ne pijanci, ne obrekovalci, ne roparji ne podedujejo kraljestva Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 11, 'In taki ste bili nekateri; ali umili ste se, ali posvečeni ste bili, ali opravičeni ste bili v imenu Gospoda Jezusa Kristusa in v Duhu Boga našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 12, 'Vse mi je dopuščeno, ali ni vse koristno. Vse mi je dopuščeno, ali jaz se ne dam ničemur obvladati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 13, 'Jedi so za trebuh, a trebuh za jedi, ali Bog bo onega in te pokončal. Telo pa ni za nečistost, nego za Gospoda in Gospod za telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 14, 'Bog je pa Gospoda obudil, pa tudi nas obudi s svojo močjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 15, 'Ne veste, da so vaša telesa udje Kristusovi? Vzamem naj torej ude Kristusove in jih storim ude nečistnice? Nikakor ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 16, 'Ali pa ne veste, kdor se z nečistnico druži, da je eno telo ž njo? Kajti „ta dva“, je dejal, „bodeta eno meso“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 17, 'A kdor se z Gospodom druži, eden je duh ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 18, 'Bežite od nečistosti! Vsak greh, katerega koli stori človek, je zunaj telesa; kdor pa nečistuje, greši na lastnem telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 19, 'Ali pa ne veste, da je vaše telo tempelj svetega Duha, ki prebiva v vas, ki ga imate od Boga, in niste sami svoji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 6, 20, 'Kajti kupljeni ste za drago ceno. Poslavite torej Boga v telesu svojem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 1, 'Zastran tega pa, kar ste mi pisali: Dobro je človeku, žene se ne dotikati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 2, 'A da ne bo nečistosti, zato imej vsak svojo ženo in vsaka imej svojega moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 3, 'Ženi mož izpolnjuj dolžnost, takisto tudi žena možu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 4, 'Žena nad svojim telesom nima oblasti, temuč mož; takisto tudi nad svojim telesom nima oblasti mož, temuč žena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 5, 'Ne odtegujta se drug drugemu, razen z dogovorom za čas, da bi bolj utegnila moliti in bi zopet skupaj bivala, da vaju ne izkuša satan za voljo nezdržljivosti vajine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 6, 'To pa govorim kot dopuščenje, ne kot zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 7, 'Hotel bi pa, da bi bili vsi ljudje, kakor sem jaz; toda vsak ima svoj dar milosti od Boga, ta tako, a drugi tako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 8, 'Pravim pa neoženjenim in vdovam: Dobro jim je, če ostanejo, kakor jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 9, 'Če se pa ne morejo zdržati, naj stopijo v zakon, ker je bolje stopiti v zakon nego pa goreti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 10, 'Zakonskim pa naročam ne jaz, ampak Gospod, naj se ne loči žena od moža');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 11, '(če pa se vendar loči, naj ostane brez moža ali pa naj se spravi z možem), in mož naj ne odpušča žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 12, 'Drugim pa pravim jaz, ne Gospod: Če ima kateri brat ženo nevernico in ona privoljuje prebivati ž njim, naj se ne loči ž njo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 13, 'In žena, če ima moža nevernika in on privoljuje prebivati ž njo, naj se ne loči ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 14, 'Posvečen je namreč mož nevernik po ženi in žena nevernica je posvečena po bratu; ker bi sicer bili nečisti vaši otroci, sedaj pa so sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 15, 'Če se pa hoče nevernik ločiti, naj se loči. Ni suženjski vezan brat ali sestra v takih slučajih; na mir pa nas je poklical Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 16, 'Ker kaj veš, žena, če moža zveličaš? ali kaj veš, mož, če ženo zveličaš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 17, 'Le kakor je vsakemu podelil Gospod, kakor je vsakega poklical Bog, tako naj ravna. In tako velevam po vseh cerkvah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 18, 'Obrezan li je kdo poklican? Naj se ne dela neobrezanega. V neobrezi je kdo poklican? Naj se ne obrezuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 19, 'Obreza ni nič in neobreza ni nič, ampak izpolnjevanje Božjih zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 20, 'Vsak naj ostane v tem poklicu, v katerem je bil poklican.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 21, 'Suženj si bil poklican? Ne maraj; ali če moreš postati svoboden, poprimi se rajši svobode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 22, 'Kajti kdor je v Gospodu poklican suženj, je svobodnik Gospodov, tako tudi kdor je poklican svobodnik, je suženj Kristusov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 23, 'Za drago ceno ste kupljeni; ne postanite sužnji ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 24, 'Vsakdo, bratje, naj ostane pri Bogu v tem, v čemer je bil poklican.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 25, 'Zastran devic pa nimam Gospodove zapovedi, ali dajem svet, kakor kateri sem prejel milost od Gospoda, da bi bil zvest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 26, 'Menim torej, da je to dobro spričo sedanje nuje, namreč da je dobro biti človeku tako, kakor je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 27, 'Si li privezan na ženo, ne išči razveze. Si li prost žene, ne išči žene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 28, 'A če se tudi oženiš, se ne pregrešiš; tudi devica, če se omoži, se ne pregreši; toda telesne nadloge bodo imeli taki; jaz bi vam pa rad prizanesel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 29, 'To pa pravim, bratje: čas je prikrajšan, da bodo odslej tudi tisti, ki imajo žene, kakor bi jih ne imeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 30, 'in kateri jokajo, kakor bi ne jokali; in kateri se vesele, kakor bi se ne veselili; in kateri kupujejo, kakor bi v lasti ne imeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 31, 'in kateri uživajo ta svet, kakor bi ga ne uživali; kajti prehaja obraz tega sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 32, 'Hotel bi pa da ste brez skrbi. Kdor je neoženjen, skrbi za to, kar je Gospodovega, kako bi bil Gospodu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 33, 'Kdor se je pa oženil, skrbi za to, kar je na svetu, kako bi ženi ugajal. Razloček je tudi med ženo in devico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 34, 'Katera je brez moža, skrbi za to, kar je Gospodovega, da bi bila sveta s telesom in z duhom. Omožena pa skrbi za to, kar je na svetu, kako bo ugajala možu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 35, 'To pa govorim vam samim na korist, ne da vržem zanko na vas, temuč da spodobno ravnate in stanovitno služite Gospodu brez ovire.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 36, 'A če kdo meni, da spravi v sramoto devico svojo, ko bi bila v prezreli dobi, in potreba tako zahteva, kar hoče, naj dela, ne greši; naj se možé!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 37, 'Kdor pa stoji trden v srcu svojem in nima potrebe, a ima oblast nad lastno voljo, in je tako odločil v srcu svojem, da obvaruje svojo devico, stori dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 38, 'Tako kdor moži devico svojo, dela tudi dobro, a kdor je ne omoži, stori bolje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 39, 'Žena je vezana, dokler živi njen mož; ako ji pa mož umre, je prosta, da se moži, s komer hoče, samo v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 7, 40, 'Ali srečnejša je po mojem mnenju, če ostane tako; mislim pa, da imam tudi jaz Duha Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 1, 'Zastran maliških žrtev pa vemo, da imamo vsi znanje. Znanje napihuje, a ljubezen pospešuje napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 2, 'Če kdo misli, da kaj pozna, ni še spoznal, kakor je treba spoznati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 3, 'Če pa kdo ljubi Boga, ta je spoznan od njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 4, 'Zastran uživanja maliških žrtev torej vemo, da malik ni nič na svetu in da ni drugega Boga razen enega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 5, 'Kajti čeprav so, kateri se imenujejo bogovi, bodisi na nebu, bodisi na zemlji (kakor je bogov mnogo in gospodov mnogo),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 6, 'ali za nas je eden Bog, Oče, iz katerega je vse in mi za njega; in eden Gospod, Jezus Kristus, po katerem je vse in mi po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 7, 'Ali ni v vseh tega spoznanja; kajti nekateri, doslej si v svesti, da je malik kaj, jedo mališke žrtve kot take, in njih vest, ker je slabotna, se skruni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 8, 'Jed pa nas ne dela prijetnih Bogu; kajti če ne jemo, nismo nič manjši, niti odličnejši, če jemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 9, 'Glejte pa, da ne postane kako ta vaša svobodnost v spotiko slabotnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 10, 'Ako namreč kdo ugleda tebe, ki imaš spoznanje, sedečega za mizo v svetišču malikov, ali se ne bo njegova vest, ker je slaboten, izpodbujala, da tudi jé mališke žrtve?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 11, 'Kajti po tvojem spoznanju se ta slabotni spravlja v pogubo, in to brat, ki je zanj umrl Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 12, 'Tako pa, grešeč zoper brate in bijoč njih slabotno vest, grešite zoper Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 8, 13, 'Zato če jed pohujšuje brata mojega, ne bom jedel mesa nikdar ne, da ne pohujšam brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 1, 'Ali nisem svoboden? nisem li apostol? nisem li videl Jezusa, Gospoda našega? niste li vi moje delo v Gospodu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 2, 'Če drugim nisem apostol, sem pa vsaj vam; kajti pečat mojega apostolstva ste vi v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 3, 'Moj zagovor tem, ki me sodijo, je ta:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 4, 'Nimamo li pravice, da jemo in pijemo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 5, 'Nimamo li pravice, da vodimo sestro kot ženo s seboj, kakor tudi drugi apostoli in bratje Gospodovi in Kefa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 6, 'Ali samo jaz in Barnaba nimava pravice, da nehava delati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 7, 'Kdo služi kdaj za vojnika na svoje stroške? kdo sadi vinograd, pa ne jé njegovega sadu? Ali kdo pase čredo, pa ne jé mleka od črede?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 8, 'Govorim li to po človeško? ali ne govori tega tudi postava?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 9, 'Kajti v Mojzesovi postavi je pisano: „Ne zaveži gobca volu, ko vrši žito“. Skrbi li Bog za vole?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 10, 'Ali pa pravi to vsekakor za nas? Res, za voljo nas je to pisano, ker kdor orje, mora z upanjem orati, in kdor mlati, mlatiti z upanjem, da bo imel svoj delež.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 11, 'Če smo vam mi duhovno posejali, je li kaj velikega, ako bomo mi vaše meseno želi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 12, 'Če so drugi deležni te pravice pri vas, čemu ne tem bolj mi? Ali nismo se poslužili te pravice, marveč prenašamo vse, da ne provzročimo kake ovire evangeliju Kristusovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 13, 'Ne veste li, da ti, kateri opravljajo sveto službo, jedo od templja, in kateri služijo oltarju, imajo delež z oltarjem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 14, 'Tako je naredil tudi Gospod, da naj ti, kateri oznanjujejo evangelij, žive od evangelija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 15, 'Jaz pa se nisem poslužil ničesar tega. Ne pišem pa tega, da bi se tako godilo z menoj; kajti rajši umrem, nego da mi kdo uniči mojo hvalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 16, 'Kajti če oznanjam evangelij, nimam nič hvale, ker to mi je neizogibna dolžnost; da, gorje mi, če evangelija ne oznanjam!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 17, 'Če namreč delam to iz dobre volje, imam plačilo, če pa po sili, mi je poverjeno oskrbništvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 18, 'Kaj je torej moje plačilo? Da oznanjujoč evangelij prinesem brez stroškov evangelij, tako da ne upotrebim pravice svoje v evangeliju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 19, 'Kajti dasi sem bil svoboden od vseh, sem se storil sužnja vsem, da bi jih tem več pridobil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 20, 'In Judom sem postal kakor Jud, da bi Jude pridobil; tistim, ki so pod postavo, kakor bi bil pod postavo, čeprav sam nisem pod postavo, da bi pridobil te, kateri so pod postavo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 21, 'tistim pa, ki so brez postave, kakor bi bil brez postave, dasi nisem brez postave Bogu, temuč v postavi Kristusu, da bi pridobil tiste, ki so brez postave;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 22, 'slabotnim sem postal slabič, da bi pridobil slabiče: vsem sem postal vse, da bi jih vsekakor nekaj zveličal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 23, 'Vse pa delam zavoljo evangelija, da bi prejel delež ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 24, 'Ne veste li, da tisti, ki teko na tekališču, vsi sicer teko, a eden prejme darilo? Tako tecite, da ga dosežete!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 25, 'Vsak pa, ki se tam bori, se zdržuje vsega: oni seveda, da dobe strohljiv venec, mi pa nestrohljivega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 26, 'Jaz torej tečem tako, ne kakor na negotovo; tako se borim, ne kakor bi po zraku mahal,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 9, 27, 'temuč tarem svoje telo in ga usnužnujem, da ne bi kako, ko sem drugim oznanjeval, sam bil zavrgljiv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 1, 'Nočem namreč, bratje, da bi ne vedeli, da so bili naši očetje vsi pod oblakom in da so prešli vsi skozi morje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 2, 'in so bili vsi v Mojzesa krščeni v oblaku in morju');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 3, 'in so vsi jedli isto duhovno jed');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 4, 'in vsi pili isto duhovno pijačo; pili so namreč iz duhovne skale, ki jih je spremljala, a ta skala je bila Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 5, 'Toda večina njih ni bila po volji Bogu; zakaj pobiti so bili v puščavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 6, 'To pa so postali zgledi za nas, da bi ne želeli hudega, kakor so tudi oni poželeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 7, 'Tudi ne bodite malikovalci kot nekateri njih, kakor je pisano: „Sedlo je ljudstvo jest in pit in vstalo igrat“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 8, 'Tudi ne nečistujmo, kakor so nekateri izmed njih nečistovali, in padlo jih je v enem dnevu triindvajset tisoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 9, 'Tudi ne izkušajmo Gospoda, kakor so ga nekateri izmed njih izkušali in so poginili od kač.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 10, 'Tudi ne mrmrajte, kakor so nekateri izmed njih mrmrali in so poginili od pogubnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 11, 'To vse pa se jim je zgodilo kot zgledi, a napisalo se je za svarilo nam, na katere so prišli konci vekov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 12, 'Kdor torej misli, da stoji, naj gleda, da ne pade.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 13, 'Ni vas nobena izkušnjava zadela razen take, ki jo more človek prenesti; zvest pa je Bog, ki vam ne da biti izkušanim nad vašo moč, temuč stori z izkušnjavo tudi izhod iz nje, da jo morete prenesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 14, 'Zatorej, ljubljeni moji, bežite od malikovalstva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 15, 'Kakor pametnim govorim; razsodite vi, kar pravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 16, 'Kelih blagoslova, ki ga blagoslavljamo, ni li deležnost krvi Kristusove? Kruh, ki ga lomimo, ni deležnost telesa Kristusovega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 17, 'Ker je en kruh, smo eno telo mnogi, kajti vsi smo deležni tega enega kruha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 18, 'Glejte Izraela po mesu: niso li, kateri jedo žrtve, deležniki oltarja?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 19, 'Kaj torej pravim? Da je mališka žrtva kaj? ali da je malik kaj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 20, 'Nikakor, temuč kar žrtvujejo pogani, da žrtvujejo zlim duhovom in ne Bogu. Nočem pa, da bodete vi deležniki zlih duhov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 21, 'Ne morete piti keliha Gospodovega in keliha zlih duhov, ne morete biti deležni mize Gospodove in mize zlih duhov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 22, 'Ali pa hočemo dražiti Gospoda? smo li močnejši od njega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 23, 'Vse je dopuščeno, ali ni vse koristno; vse je dopuščeno, ali vse ne pospešuje napredka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 24, 'Nihče naj ne išče svojega, temuč vsak dobro drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 25, 'Vse, kar prodajajo v mesnici, jejte, nič ne povprašujoč zavoljo vesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 26, 'Kajti „Gospodova je zemlja in kar jo napolnjuje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 27, 'Če pa vas povabi kdo nevernikov in hočete iti, jejte vse, kar stavijo pred vas, nič povprašujoč zavoljo vesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 28, 'Ako pa vam kdo poreče: ‚To je mališka žrtva‘, ne jejte zavoljo tistega, ki je to oznanil, in zavoljo vesti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 29, 'ne pravim pa zavoljo vesti tvoje, temuč onega drugega. Kajti čemu naj mojo svobodo sodi tuja vest?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 30, 'Če jaz uživam kaj s hvalo Bogu, zakaj naj bi bil preklinjan ob tem, za kar se zahvaljujem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 31, 'Če torej jeste ali pijete ali karkoli delate, vse delajte Bogu na slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 32, 'Bodite brez spotike Judom in Grkom in cerkvi Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 10, 33, 'kakor delam tudi jaz v vseh rečeh vsem pogodu, ne iščoč, kar je koristno meni, temuč kar je v korist mnogim, da se zveličajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 1, 'Posnemalci moji bodite, kakor sem tudi jaz Kristusov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 2, 'Hvalim vas pa, bratje, da se v vsem mene spominjate in se držite zapovedi, kakor sem vam jih izročil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 3, 'Hočem pa, da veste, da je vsakemu možu glava Kristus, a glava ženi mož, glava pa Kristusu Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 4, 'Vsak mož, ki moli ali prorokuje s pokrito glavo, sramoti svojo glavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 5, 'Vsaka žena pa, ki moli ali prorokuje razoglava, sramoti svojo glavo; zakaj to je toliko, kakor bi bila ostrižena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 6, 'Kajti če se ne pokriva žena, naj se tudi striže; če je pa sramota za ženo striči se ali briti, naj se pokriva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 7, 'Možu namreč ni treba pokrivati glave, ker je podoba in slava Božja; a žena je slava moževa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 8, 'Zakaj mož ni od žene, temuč žena od moža;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 9, 'saj tudi ni ustvarjen mož za voljo žene, temuč žena za voljo moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 10, 'Zato mora imeti žena znamenje moževe oblasti na glavi za voljo angelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 11, 'Sicer pa ni ne mož brez žene, ne žena brez moža v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 12, 'Kajti kakor je žena od moža, tako je tudi mož po ženi, a vse je iz Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 13, 'Sami pri sebi presodite, je li spodobno za ženo, da razoglava moli k Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 14, 'Ali vas ne uči sama narava, da je možu v sramoto, če si goji dolge lase?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 15, 'a ženi, če si goji dolge lase, da je čast? ker so ji lasje dani za pokrivalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 16, 'Če se pa komu zdi, da se mora prepirati: mi te navade nimamo, tudi cerkve Božje ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 17, 'Ko pa to naročam, ne hvalim, da se ne na boljše, temuč na hujše shajate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 18, 'Kajti prvič, kadar se shajate v zboru, slišim da so razpori med vami, in nekoliko verjamem to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 19, 'Zakaj potrebno je, da so tudi krivoverstva med vami, da se pokažejo med vami, kateri so v veri izkušeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 20, 'Ko se torej shajate na en kraj, to ni Gospodovo večerjo jesti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 21, 'kajti ob vaši skupni jedi užije vsak svojo večerjo poprej, in tako je eden lačen, a drugi se opija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 22, 'Nimate li mar hiš, da v njih jeste in pijete? Ali pa zaničujete zbor Božji in sramotite tiste, ki nimajo ničesar? Kaj naj vam rečem? naj vas hvalim? V tem ne hvalim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 23, 'Zakaj jaz sem prejel od Gospoda, kar sem tudi vam izročil: da je Gospod Jezus tisto noč, v kateri je bil izdan, vzel kruh');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 24, 'in, zahvalivši se, ga je prelomil in rekel: Vzemite, jejte: to je moje telo, ki je za vas; to delajte v moj spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 25, 'Tako tudi kelih po večerji, rekoč: Ta kelih je nova zaveza v moji krvi; to delajte, kolikorkolikrat pijete, v moj spomin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 26, 'Kajti kolikorkolikrat jeste ta kruh in pijete ta kelih, oznanjujete smrt Gospodovo, dokler ne pride.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 27, 'Zatorej kdor jé ta kruh in pije kelih Gospodov nevredno, kriv bo telesa in krvi Gospodove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 28, 'Ali človek naj izkuša sam sebe in tako naj jé od kruha in pije od keliha;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 29, 'zakaj kdor jé in pije nevredno, jé in pije sebi sodbo, ker ne razločuje telesa Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 30, 'Zato so mnogi med vami slabi in bolni in dosti jih spi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 31, 'Ko bi pa mi sami sebe razsojali, ne bi bili sojeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 32, 'Ko smo pa sojeni, nas strahuje Gospod, da ne bi bili s svetom obsojeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 33, 'Tako, bratje moji, ko se shajate k jedi, čakajte drug drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 11, 34, 'Je li pa kdo lačen, jej doma, da bi se ne shajali na obsojenje. Drugo pa uredim, kadar pridem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 1, 'A zastran duhovnih darov nočem, bratje, da bi bili nepoučeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 2, 'Veste, da ste zahajali, ko ste bili pogani, k nemim malikom, kamorkoli so vas vodili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 3, 'Zato vam dajem na znanje, da nihče v Duhu Božjem govoreč, ne reče: ‚Proklet bodi Jezus‘, in nihče ne more reči: ‚Jezus je Gospod‘, razen v svetem Duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 4, 'So pa razločki v darovih, ali eden je Duh,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 5, 'in so razločki v službah, ali eden je Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 6, 'in so razločki v delovanju, ali eden je Bog, ki dela vse v vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 7, 'A vsakemu se daje razodevanje Duha v občno korist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 8, 'Enemu se namreč po Duhu daje beseda modrosti, a drugemu beseda znanja po istem Duhu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 9, 'drugemu pa vera v istem Duhu, a drugemu dar ozdravljati v istem Duhu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 10, 'a drugemu dela čudežnih moči, drugemu pa proroštvo, a drugemu razločevanje duhov, drugemu pa raznovrstnost jezikov, a drugemu razkladanje jezikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 11, 'A vse to dela isti edini Duh, podeljujoč vsakemu posebe, kakor hoče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 12, 'Kajti kakor je telo eno in ima mnogo duhov, a vsi udje enega telesa, čeprav jih je mnogo, so eno telo: tako tudi Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 13, 'Z enim Duhom namreč smo mi vsi krščeni v eno telo, bodisi Judje ali Grki, bodisi sužnji ali svobodniki, in vsi smo napojeni enega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 14, 'Saj tudi telo ni eden ud, temuč mnogi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 15, 'Ako reče noga: ‚Ker nisem roka, nisem od telesa‘, ali zato ni od telesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 16, 'In ako reče uho: ‚Ker nisem oko, nisem od telesa‘, ni li zato od telesa?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 17, 'Ko bi bilo celo telo oko, kje bi bil sluh? ko bi bilo celo sluh, kje bi bil voh?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 18, 'Tako pa je Bog postavil ude, slehernega izmed njih po telesu, kakor je hotel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 19, 'Ko bi bili pa vsi eden ud, kje bi bilo telo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 20, 'Tako so pa sicer mnogi udje, a telo eno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 21, 'Nikar ne more oko reči roki: ‚Ni te mi treba‘, ali zopet glava nogama: ‚Ni mi vaju treba‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 22, 'Marveč tisti udje telesa, ki se zde slabejši, so tem bolj potrebni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 23, 'in kateri se nam zde manj častni na telesu, okoli teh stavimo obilnejšo čast, in naši nespodobni dobivajo tem obilnejšo spodobnost;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 24, 'našim spodobnim pa tega ni treba. Ali Bog je zložil telo, davši pomanjkljivemu večjo čast,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 25, 'da bi ne bilo razpora v telesu, ampak da bi udje enako skrbeli drug za drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 26, 'In če trpi eden ud, ž njim trpe vsi udje; a če je en ud v slavi, se vesele ž njim vsi udje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 27, 'Vi pa ste telo Kristusovo in vsakteri zase je ud celote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 28, 'In nekatere si je postavil Bog v cerkvi prvič za apostole, drugič za proroke, tretjič za učitelje, potem je dal čudežne moči, potem darove ozdravljanja, zmožnost pomagati, vladati, raznovrstnost jezikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 29, 'Ali so vsi apostoli? so li vsi preroki? so li vsi učitelji? imajo li vsi one moči?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 30, 'imajo li vsi darove ozdravljanja? ali vsi govore jezike? ali vsi razkladajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 12, 31, 'Hrepenite pa po boljših darovih! In še boljšo pot vam kažem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 1, 'Ko bi govoril človeške jezike in angelske, a ljubezni ne bi imel, bi bil brneča med in zvenčeče cimbale.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 2, 'In ko bi imel proroštvo in bi vedel vse skrivnosti in imel vse spoznanje, in ko bi imel vso vero, tako da bi gore prestavljal, a ljubezni ne bi imel, nič nisem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 3, 'In ko bi porazdal v živež ubogim vse, kar imam, in ko bi dal svoje telo, da zgorim, a ljubezni ne bi imel, nič mi ne koristi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 4, 'Ljubezen je potrpežljiva, dobrotljiva; ljubezen ni nevoščljiva, ljubezen se ne hvali, se ne napihuje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 5, 'ne vede se nespodobno, ne išče svojega, se ne da razdražiti, ne misli hudega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 6, 'ne veseli se krivice, a veseli se resnice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 7, 'vse pokriva, vse veruje, vse upa, vse prenaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 8, 'Ljubezen nikoli ne mine; če pa so darovi proroštva, ponehajo, ali jeziki, umolknejo, ali spoznanje, preide.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 9, 'Le po nekoliko namreč spoznavamo in le po nekoliko prorokujemo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 10, 'kadar pa pride, kar je popolno, tedaj premine ta nepopolnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 11, 'Ko sem bil otrok, sem govoril kakor otrok, mislil kakor otrok, razsojal kakor otrok; odkar sem pa mož, sem opustil, kar je otročjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 12, 'Kajti sedaj vidimo še skozi zrcalo, kakor v uganki, takrat pa bomo z licem v lice; sedaj spoznavam le nekoliko, takrat pa spoznam popolnoma, kakor sem bil tudi jaz spoznan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 13, 13, 'Sedaj pa ostane vera, upanje, ljubezen, to troje; največja od njih pa je ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 1, 'Prizadevajte si za ljubezen, hrepenite pa tudi po duhovnih darovih, a najbolj, da prorokujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 2, 'Kajti kdor govori v tujem jeziku, ne govori ljudem, ampak Bogu; kajti nihče ga ne razume, v duhu pa govori skrivnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 3, 'A kdor prorokuje, govori ljudem, da jim služi v napredovanje in jih tolaži in opominja:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 4, 'Kdor govori v jeziku, streže sebi v napredek, kdor pa prorokuje, pospešuje napredek cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 5, 'Hotel bi pa, da vsi govorite jezike, a veliko bolj, da prorokujete. Večji je, kdor prorokuje, nego kdor govori jezike, razen če bi razkladal, da bi cerkev prejela, kar ji služi v napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 6, 'Tako pa, bratje, če pridem k vam, jezike govoreč, kaj vam bom koristil, ko vam ne govorim ali v razodetju, ali v spoznanju, ali v proroštvu, ali v nauku?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 7, 'Brezdušna godala, bodisi piščal ali citre, naj se tudi glase, če pa razločka nimajo v glasovih, kako bomo umeli, kaj se piska ali citra?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 8, 'Saj tudi če da trobenta nerazločen glas, kdo se pripravi za boj?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 9, 'Tako tudi z vami: če z jezikom ne govorite razumljive besede, kako bodo umeli, kaj pravite? V zrak boste govorili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 10, 'Toliko raznovrstnih glasov, postavim, je na svetu in nobeden ni brez pomena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 11, 'Če torej ne vem pomena glasu, bodem tujec govorečemu in govoreči bode meni tujec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 12, 'Tako tudi z vami: ker ste vneti za duhovne dari, iščite, da jih imate obilo in ž njimi služite v napredovanje cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 13, 'Zato, kdor govori v jeziku, naj moli, da bi mogel razkladati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 14, 'Kajti če molim v jeziku, duh moj moli, a um moj je brez sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 15, 'Kaj torej? Molil bom z duhom, a molil bom tudi z umom; prepeval bom z duhom, a prepeval bom tudi z umom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 16, 'Sicer, če hvališ Boga le z duhom, kako poreče ta, ki je nepoučen, Amen na tvojo zahvalo, ko ne ve, kaj govoriš?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 17, 'Ti se resda lepo zahvaljuješ, ali drugemu ne služiš za napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 18, 'Zahvaljujem Boga, da govorim v jezikih bolj nego vi vsi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 19, 'toda v cerkvi rečem rajši pet besed s svojim umom, da poučim tudi druge, nego pa deset tisoč besed v jeziku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 20, 'Bratje, ne bodite deca v razumu, ampak v zlobi bodite deca, a v razumu bodite popolni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 21, 'V postavi je pisano: „S tujimi jeziki in z ustnami tujcev bom govoril temu ljudstvu, in tudi tako me ne bodo poslušali, pravi Gospod“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 22, 'Jeziki so torej za znamenje ne tem, ki verujejo, temuč nevernim, proroštvo pa ne nevernim, temuč tem, ki verujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 23, 'Ko bi se torej sešla cerkev vsa na en kraj in bi vsi govorili jezike in bi prišli tja tudi nepoučeni ali neverniki, ne poreko li, da norite?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 24, 'Ko pa vsi prorokujejo, a pride tja kak nevernik ali nepoučen človek, ga prepričujejo vsi, ga sodijo vsi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 25, 'skrivnosti njegovega srca se razodevajo, in tako bo padel na obraz in molil Boga in priznaval, da je Bog zares med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 26, 'Kaj torej, bratje? Kadar se shajate, ima vsak vas ali psalm, ali nauk, ali razodetje, ali jezik, ali razkladanje. Vse naj se zgodi tako, da se pospešuje napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 27, 'Če kdo govori v jeziku, naj govorita po dva ali kvečjemu po trije in drug za drugim, in eden naj razklada.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 28, 'Ko bi pa ne bilo razkladalca, naj molči v zboru, a govori naj sebi in Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 29, 'Proroki naj pa govore dva ali trije, drugi naj pa razsojajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 30, 'Ako pa drugi, ki sedi zraven, prejme razodetje, naj molči prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 31, 'Kajti morete vsi, eden po eden, prorokovati, da prejmo vsi pouk in se vsi potolažijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 32, 'In duhovi proroški so pokorni prorokom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 33, 'zakaj Bog ni Bog nereda, ampak miru, kakor po vseh zborih svetniških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 34, 'Žene naj v vaših zborih molče; kajti ni jim dopuščeno govoriti, temuč podložne naj bodo, kakor veli tudi postava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 35, 'A če se hočejo česa naučiti, doma naj vprašajo svoje može; zakaj nespodobno je ženi govoriti v cerkvenem zboru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 36, 'Ali pa je od vas izšla beseda Božja? ali pa je prišla k vam samim?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 37, 'Če kdo misli, da je prorok ali z Duhom obdarovan, naj spozna, kar vam pišem, da je Gospodova zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 38, 'Če pa kdo noče umeti, naj ne ume.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 39, 'Zatorej, bratje moji, gorite za to, da prorokujete, in nikar ne branite govoriti v jezikih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 14, 40, 'Vse naj se spodobno in po redu godi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 1, 'Spominjam vas pa, bratje, evangelija, ki sem vam ga oznanil, ki ste ga tudi sprejeli, ki v njem tudi stojite,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 2, 'ki se po njem tudi zveličujete, ako hranite besedo, kakor sem vam jo oznanil, če le niste zaman verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 3, 'Izročil sem vam namreč najprej to, kar sem tudi prejel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 4, 'da je Kristus umrl za naše grehe po pismih, in da je bil pokopan in da je bil tretji dan obujen po pismih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 5, 'in da se je prikazal Kefu, potem dvanajsterim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 6, 'Potem se je prikazal nad petsto bratom naenkrat, katerih večina še sedaj živi, nekaj jih je pa že pozaspalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 7, 'Potem se je prikazal Jakobu, potem vsem apostolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 8, 'In izmed vseh najnazadnje, kakor kakemu negodno rojenemu, se je prikazal tudi meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 9, 'Kajti jaz sem najmanjši izmed apostolov, ki nisem vreden imenovan biti apostol, ker sem preganjal cerkev Božjo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 10, 'ali po milosti Božji sem, kar sem, in njegova milost, ki mi jo je podelil, ni bila brezuspešna, marveč deloval sem bolj od njih vseh, toda ne jaz, ampak milost Božja, ki je z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 11, 'Bodisi torej jaz ali oni, tako oznanjujemo in tako ste sprejeli vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 12, 'Če se pa oznanjuje, da je Kristus iz mrtvih vstal, kako pravijo nekateri med vami, da ni vstajenja mrtvih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 13, 'Če pa ni vstajenja mrtvih, tudi Kristus ni vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 14, 'A če Kristus ni vstal, prazno je potem naše oznanjevanje, prazna pa tudi vera vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 15, 'Kažemo se pa tudi lažnive priče Božje, ker smo popričali zoper Boga, da je obudil Kristusa, ki ga pa ni obudil, če mrtvi ne vstajajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 16, 'Kajti če mrtvi ne vstajajo, tudi Kristus ni vstal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 17, 'A če Kristus ni vstal, ničeva je vera vaša, še ste v grehih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 18, 'Potemtakem so tudi ti, ki so v Kristusu zaspali, izgubljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 19, 'Če upamo v Kristusa samo v tem življenju, smo vredni pomilovanja najbolj izmed vseh ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 20, 'Res pa je Kristus vstal iz mrtvih, prvina tistih, ki so pozaspali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 21, 'Zakaj ker je po človeku prišla smrt, je po človeku prišlo tudi vstajenje mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 22, 'Kakor namreč v Adamu vsi mrjo, tako bodo tudi v Kristusu vsi oživeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 23, 'Ali vsak v svojem redu: prvina Kristus; potem ti, kateri so Kristusovi, ob prihodu njegovem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 24, 'potem pride konec, kadar on izroči kraljestvo Bogu in Očetu, kadar odpravi vsako poglavarstvo in vsako oblast in moč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 25, 'Kajti on mora kraljevati dotlej, dokler Bog ne dene vseh sovražnikov pod njegove noge.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 26, 'A najzadnji sovražnik, ki se odpravi, je smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 27, 'Vse je namreč položil pod njegove noge. Toda ko pravi: „Vse je podloženo“, je očitno, da vse razen tega, ki mu je vse podložil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 28, 'Kadar se pa vse njemu podloži, tedaj se tudi sam Sin podloži temu, ki mu je vse podložil, da bi Bog bil vse v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 29, 'Sicer pa kaj bodo počeli, kateri se krščujejo za mrtve? Če sploh mrtvi ne vstajajo, kaj se še krščujejo zanje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 30, 'Zakaj se tudi mi nevarnostim izpostavljamo vsako uro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 31, 'Pričam pri hvali zastran vas, bratje, ki jo imam v Kristusu Jezusu, Gospodu našem: vsak dan umiram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 32, 'Če sem se po človeško boril z zvermi v Efezu, kakšno imam korist? Če mrtvi ne vstajajo, „jejmo in pijmo, kajti jutri umremo!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 33, 'Ne dajte se zavesti! Dobre navade pačijo slabi pogovori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 34, 'Predramite se pravično in ne grešite! kajti spoznanja Božjega nekateri nimajo, na sramoto vam to pravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 35, 'Toda poreče kdo: Kako vstajajo mrtvi? in v kakšnem telesu prihajajo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 36, 'Nespametnež, kar ti seješ, ne oživi, če ni prej umrlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 37, 'In kar seješ, ne seješ telesa, katero ima biti, temuč golo zrno, postavim, pšenično ali katero drugo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 38, 'a Bog mu daje telo, kakor hoče, in vsakemu semenu lastno mu telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 39, 'Ni vse meso enako meso, temuč drugo je meso človečje, drugo meso živinsko, drugo ptičje in drugo ribje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 40, 'So tudi telesa nebeška in telesa zemeljska, toda druga je slava nebeških, a druga zemeljskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 41, 'Druga je slava solnca in druga slava meseca in druga slava zvezd, kajti zvezda se od zvezde loči v slavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 42, 'Tako tudi je vstajenje mrtvih. Seje se v trohljivosti, vstaja v netrohljivosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 43, 'seje se v nečasti, vstaja v slavi; seje se v slabosti, vstaja v moči;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 44, 'seje se telo naravno, vstaja telo duhovno. Če je naravno telo, je tudi duhovno telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 45, 'Tako je tudi pisano: „Postal je prvi človek Adam duša živa“. Zadnji Adam je postal duh oživljajoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 46, 'Ali ni prvo duhovno, ampak naravno, potem duhovno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 47, 'Prvi človek je iz zemlje, prstén, drugi človek je iz nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 48, 'Kakršen je prsteni, taki so prsteni, in kakršen nebeški, taki so nebeški.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 49, 'In kakor smo nosili podobo prstenega, nosili bomo tudi podobo nebeškega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 50, 'To pa pravim, bratje, da meso in kri ne moreta podedovati Božjega kraljestva, tudi trohljivost ne deduje netrohljivosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 51, 'Glejte, skrivnost vam govorim: Vsi ne zaspimo, a vsi se izpremenimo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 52, 'v hipu, v trenutku, ob poslednji trobenti; kajti trobenta zatrobi in mrtvi vstanejo netrohljivi, in mi se izpremenimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 53, 'To trohljivo mora namreč obleči netrohljivost in to smrtno obleči nesmrtnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 54, 'Kadar pa to trohljivo obleče netrohljivost in to smrtno obleče nesmrtnost, tedaj se zgodi tista beseda, ki je napisana: „Požrta je smrt v zmagi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 55, 'Kje je, smrt, tvoja zmaga? Kje je, smrt, tvoje želo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 56, 'Želo smrti pa je greh, a moč greha je postava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 57, 'Ali hvala Bogu, ki nam daje zmago po Gospodu našem Jezusu Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 15, 58, 'Zato, bratje moji ljubljeni, bodite stanovitni, nepremični, obilni vsekdar v delu Gospodovem, vedoč, da vaš trud ni prazen v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 1, 'A glede sklada za svete storite tudi vi tako, kakor sem naredil za galacijske cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 2, 'Prvi dan po soboti naj vsak vas pri sebi deva na stran in spravlja po svojih dohodkih, da ne bode zbiranja šele takrat, kadar pridem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 3, 'Kadar pa pridem, pošljem z listi tiste, ki jih za dobre za to spoznate, da odneso vaš dar ljubezni v Jeruzalem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 4, 'ko bi pa vredno bilo, da tudi jaz grem, pojdejo z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 5, 'Pridem pa k vam, kadar prepotujem Macedonijo; pojdem namreč skozi Macedonijo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 6, 'a pri vas se morebiti pomudim ali pa ostanem tudi čez zimo, da me vi spremite, kamor koli pojdem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 7, 'Kajti nočem vas le mimogrede videti, marveč upam, da ostanem nekoliko časa pri vas, če Gospod dovoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 8, 'Ostanem pa v Efezu do Binkošti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 9, 'Zakaj vrata so mi odprta velika in široka in nasprotnikov je mnogo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 10, 'Ako pa pride Timotej, glejte, da bode brez strahu pri vas; kajti opravlja Gospodovo delo kakor i jaz:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 11, 'nihče naj ga torej ne zaničuje. A odpošljite ga v miru, da pride k meni, ker ga pričakujem z brati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 12, 'Kar se pa tiče Apola brata, dosti sem ga prosil, da bi šel k vam z brati; a nikakor ga ni bila volja iti sedaj, toda pride, kadar utegne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 13, 'Čujte, stojte v veri, moški se držite, trdni bodite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 14, 'Vse vaše naj se godi v ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 15, 'Prosim pa vas, bratje: za Štefanov dom veste, da je prvina v Ahaji in da so se za službo svetim odločili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 16, 'da bodite tudi vi podložni takim in vsakemu, ki pomaga v delu in se trudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 17, 'Veselim se pa prihoda Štefanovega in Fortunatovega in Ahaikovega, ker so mi nadomestili, kar sem na vas pogrešal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 18, 'zakaj poživili so mojega duha in vašega. Spoštujte torej take!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 19, 'Pozdravljajo vas cerkve v Aziji. Pozdravljata vas v Gospodu mnogokrat Akvila in Priska s cerkvijo, ki se shaja v njunem domu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 20, 'Pozdravljajo vas bratje vsi. Pozdravite drug drugega v svetem poljubu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 21, 'Pozdrav z mojo, Pavlovo, roko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 22, 'Če kdo ne ljubi Gospoda, proklet bodi! Maran atha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 23, 'Milost Gospoda Jezusa z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (46, 16, 24, 'Moja ljubezen z vami vsemi v Kristusu Jezusu! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 1, 'Pavel, apostol Kristusa Jezusa po volji Božji, in Timotej, brat, cerkvi Božji, ki je v Korintu, z vsemi svetimi, ki bivajo po vsej Ahaji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 2, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 3, 'Hvaljen bodi Bog in Oče Gospoda našega Jezusa Kristusa, Oče usmiljenosti in Bog vsake tolažbe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 4, 'ki nas tolaži v vsaki stiski, da moremo i mi tolažiti tiste, ki so v kakršnikoli stiski s to tolažbo, s katero nas same tolaži Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 5, 'Kajti kakor je obilno trpljenje Kristusovo pri nas, tako je po Kristusu obilna tolažba naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 6, 'Če smo pa stiskani, je to za vašo tolažbo in rešitev; če pa uživamo tolažbo, je to za vašo tolažbo, ki naj vas podpira v prenašanju istega trpljenja, ki ga tudi mi trpimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 7, 'In upanje naše je trdno za vas, ker vemo, da kakor ste deležniki trpljenja, tako ste tudi tolažbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 8, 'Kajti nočemo, da bi ne vedeli, bratje, za stisko našo, ki se nam je dogodila v Aziji, da smo bili hudo preobteženi, nad svojo moč, tako da smo obupali tudi nad življenjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 9, 'da, sami v sebi smo izrekli smrtno obsodbo, – naj bi ne stavili upanja svojega na sebi, ampak na Bogu, ki obuja mrtve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 10, 'ki nas je take smrti otel in otimlje, v katerega upamo, da bo še dalje otimal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 11, 'če pripomagate tudi vi nam z molitvijo, da bi se za dar, ki nam je dodeljen po molitvah mnogih, mnogi zahvaljevali zaradi nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 12, 'Kajti hvala naša je ta: pričevanje vesti naše, da smo živeli v svetosti in čistosti Božji, ne v meseni modrosti, temuč v milosti Božji na svetu, posebno pa pri vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 13, 'Kajti nič drugega vam ne pišemo, nego kar berete in kar morate tudi priznati; upam pa, da boste to do konca priznavali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 14, 'kakor ste tudi priznali nas, vsaj nekoliko, da smo hvala vaša, kakor tudi vi naša v dan Gospoda našega Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 15, 'In s tem zaupanjem sem hotel k vam priti poprej, da bi prejeli dvojno dobroto,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 16, 'in od vas potovati v Macedonijo in zopet iz Macedonije priti k vam in od vas spremljen biti v Judejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 17, 'Ko sem torej to hotel, sem li lahkomiselno ravnal? ali kar sklepam, sklepam po mesu, da bi bilo pri meni hkratu ‚da, da‘in ‚ne, ne‘?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 18, 'Ali zvest je Bog, da beseda naša do vas ni bila ‚da‘in ‚ne‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 19, 'Kajti Božji Sin Jezus Kristus, ki smo ga med vami oznanili jaz in Silvan in Timotej, ni bil ‚da‘in ‚ne‘, temuč v njem je bilo ‚da‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 20, 'Zakaj kolikorkoli je obljub Božjih, v njem so ‚da‘, zato tudi po njem ‚Amen‘Bogu na slavo po nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 21, 'Ta pa, ki nas utrjuje z vami vred v Kristusa in nas je pomazilil, je Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 22, 'ki nas je tudi zapečatil in dal zastavo Duha v srca naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 23, 'A jaz kličem za pričo Boga na svojo dušo, da iz prizanašanja do vas še nisem prišel v Korint.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 1, 24, 'Ne da gospodujemo v veri vaši, temuč sodelavci smo za radost vašo; kajti z vero stojite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 1, 'Sklenil sem pa v sebi to, da zopet ne pridem z žalostjo k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 2, 'Kajti če jaz žalostim vas, kdo je, ki bi me razveselil, če ne ta, ki sem ga jaz užalostil?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 3, 'In napisal sem vam prav to, da ne bi žalosti imel, ko pridem, s temi, nad katerimi bi se imel radovati; nadejajoč se za vas vse, da je moja radost vseh vas radost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 4, 'Kajti z veliko stisko in srčno težavo sem vam pisal, z mnogimi solzami, ne da se žalostite, marveč da spoznate ljubezen, ki je imam obilo do vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 5, 'Če je pa kdo povzročil žalost, ni mene užalostil, temuč nekoliko (da ga preveč ne obtežim) vse vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 6, 'Dosti je takemu ta kazen, ki ga je zadela od večine:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 7, 'nasproti zdaj storite bolje, da mu odpustite in ga potolažite, da bi prevelika žalost morda ne pogoltnila takega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 8, 'Zato vas prosim, da potrdite ljubezen do njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 9, 'Kajti zato sem tudi pisal, da vas preizkusim in spoznam, ste li v vsem poslušni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 10, 'Komur pa kaj odpustite, njemu tudi jaz; saj tudi kar sem jaz odpustil, če sem kaj odpustil, za voljo vas sem to storil pred obličjem Kristusovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 11, 'da bi nas ne ukanil satan; kajti niso nam njegove misli neznane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 12, 'A ko sem prišel v Troado zavoljo evangelija Kristusovega in so mi bila vrata odprta v Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 13, 'nisem imel miru v duhu svojem, ker nisem našel Tita, brata svojega; temuč sem vzel slovo od njih in odšel v Macedonijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 14, 'Ali hvala Bogu, ki nam vsekdar zmago daje v Kristusu in vonjavo spoznanja svojega razodeva po nas na vsakem mestu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 15, 'Kajti Kristusova prijetna dišava smo Bogu v teh, ki se zveličujejo, in v tistih, ki gredo v pogubo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 16, 'enim vonjava iz smrti za smrt, a drugim vonjava iz življenja za življenje. In kdo je zmožen za to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 2, 17, 'Kajti nismo kakor mnogi, ki pokvarjajo besedo Božjo, temuč kakor iz čistote, kakor iz Boga, vpričo Boga govorimo v Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 1, 'Začenjamo li zopet sami sebe priporočati? ali potrebujemo li, kakor nekateri, priporočilnih listov do vas ali od vas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 2, 'List nas ste vi, napisan v srcih naših, ki ga poznajo in bero vsi ljudje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 3, 'ker se kažete, da ste list Kristusov, napravljen po naši službi, pisan ne s črnilom, ampak z Duhom Boga živega, ne na kamenitih pločah, ampak na mesenih pločah srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 4, 'Tako zaupanje pa imamo po Kristusu do Boga:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 5, 'Ne da bi bili zmožni, sami po sebi misliti kaj kakor sami iz sebe, temuč naša zmožnost je od Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 6, 'ki nas je storil tudi zmožne, da smo služabniki nove zaveze, ne črke, ampak Duha; kajti črka ubija, a Duh oživlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 7, 'Če je pa služba smrti, v črkah in vrezana v kamene, bila polna slave, tako da niso mogli pogledati sinovi Izraelovi v obličje Mojzesovo zavoljo slave obličja njegovega, ki pa je bila minljiva:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 8, 'kako naj bi ne bila veliko bolj polna slave služba Duha?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 9, 'Zakaj ako je bila služba obsojanja slavna, veliko bolj je obila v slavi služba pravičnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 10, 'saj proti tej preveliki slavi nove zaveze, kakor da bi ne bila oslavljena stara zaveza, ki je pač bila oslavljena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 11, 'če je v slavi, kar je minljivo, veliko bolj je v slavi, kar je trajno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 12, 'Ker imamo torej toliko upanje, govorimo z veliko prostosrčnostjo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 13, 'in ne delamo kakor Mojzes, ki si je deval zagrinjalo na obličje, da ne bi videli sinovi Izraelovi konca temu, kar je minljivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 14, 'Ali njih misli so odrevenele. Kajti prav do današnjega dne ostaja isto zagrinjalo pri branju stare zaveze neodgrnjeno, ker se le v Kristusu odpravlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 15, 'A do danes, kadarkoli se čita Mojzes, leži zagrinjalo na njih srcih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 16, 'Kadar se pa zgodi izpreobrnjenje v Gospodu, se sname zagrinjalo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 17, 'Gospod pa je Duh; kjer pa je Duh Gospodov, tam je svoboda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 3, 18, 'A mi vsi, ki z odkritim obličjem gledamo kot v zrcalu slavo Gospodovo, se premenjujemo v isto podobo od slave v slavo, kakor od Gospodovega Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 1, 'Zatorej, ker opravljamo to službo, kakor smo dobili usmiljenje, ne izgubljamo srca;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 2, 'ampak odrekli smo se skrivnim delom sramu ter ne ravnamo z zvijačami, tudi ne preobračamo besede Božje, marveč se z razodevanjem resnice priporočamo vesti vseh ljudi vpričo Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 3, 'Če je pa tudi zakrit evangelij naš, zakrit je tistim, ki gredo v pogubo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 4, 'ki jim je bog tega sveta nevernim oslepil misli, da jim ne zasveti svetlost evangelija slave Kristusa, ki je podoba Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 5, 'Kajti ne oznanjujemo sebe, temuč Kristusa Jezusa, da je Gospod, mi pa vaši služabniki zaradi Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 6, 'Ker Bog, ki je rekel: „Iz teme naj zasveti luč“, on je, ki je zasvetil v srcih naših, da dodeli svetlo spoznanje slave Božje v obličju Kristusovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 7, 'Imamo pa ta zaklad v lončenih posodah, da bi bila preobilnost moči iz Boga in ne iz nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 8, 'Od vseh strani nas stiskajo, ali nismo na tesnem; v zadregah smo, ali ne obupujemo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 9, 'preganjajo nas, ali nismo zapuščeni; pobijajo nas, ali ne ginemo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 10, 'vsekdar nosimo umiranje Jezusovo s seboj na telesu, da bi se tudi življenje Jezusovo pokazalo na našem telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 11, 'Kajti vedno smo mi, ki živimo, izročani na smrt zavoljo Jezusa, da bi se tudi življenje Jezusovo pokazalo na smrtnem mesu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 12, 'Tako smrt deluje v nas, a življenje v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 13, 'A imajoč istega duha vere po tem, kar je pisano: „Veroval sem, zato sem govoril“, tudi mi verujemo, zato tudi govorimo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 14, 'vedoč, da kateri je obudil Gospoda Jezusa, obudi tudi nas z Jezusom in postavi pred seboj z vami vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 15, 'Vse je namreč za voljo vas, da bi milost, pomnožena po mnogih prejemalcih, povečala zahvalo v slavo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 16, 'Zato ne izgubljamo srca; ali čeprav se zunanji naš človek pokončuje, pa se notranji obnavlja od dne do dne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 17, 'Kajti sedanja kratka in lahka stiska naša nam napravlja nad vse obilno večno množino slave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 4, 18, 'ko ne gledamo na to, kar se vidi, marveč na to, kar se ne vidi; zakaj to, kar se vidi, je začasno, a kar se ne vidi, je večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 1, 'Vemo namreč, če razpade zemeljska hiša našega prebivanja, da imamo prebivališče od Boga, hišo, ne z rokami napravljeno, večno, v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 2, 'Kajti v tem tudi zdihujemo, želeč, povrhu se obleči v prebivališče svoje, ki je iz nebes;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 3, 'če se le pokaže, da smo tudi oblečeni, ne goli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 4, 'Kajti kateri smo v tem šatoru, zdihujemo obteženi, ker se ne želimo sleči, ampak po vrhu se obleči, da življenje pogoltne to, kar je smrtnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 5, 'Kateri nas je pa ravno za to pripravil, je Bog, ki nam je tudi dal zastavo Duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 6, 'Dobre volje smo torej vsekdar in vemo, dokler stanujemo v telesu, potujemo na tujem daleč od Gospoda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 7, '(zakaj po veri živimo, ne po tem, kar gledamo);');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 8, 'dobre volje smo pa in želimo rajši preseliti se iz telesa in biti doma pri Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 9, 'Zato si tudi prizadevamo, bodisi da stanujemo v telesu ali da se selimo, da smo njemu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 10, 'Zakaj vsi se moramo pokazati pred sodnim stolom Kristusovim, da prejme vsak po tem, kar je storil v telesu, bodisi dobro ali hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 11, 'Vedoč torej za strah Gospodov, prepričujemo ljudi, a Bogu smo razodeti; upam pa, da smo tudi v vaših vesteh razodeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 12, 'Ne priporočamo vam zopet sami sebe, temuč vam dajemo priložnost, hvaliti se z nami, da imate kaj proti tem, kateri se z zunanjim hvalijo in ne s tem kar je v srcu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 13, 'Kajti ako smo predaleč stopili, se je zgodilo za Boga; ako smo zmerni, smo za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 14, 'Zakaj ljubezen Kristusova priganja nas, ki smo tako sodili: če je eden umrl za vse, so umrli vsi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 15, 'in za vse je umrl, da bi ti, kateri žive, nič več ne živeli zase, ampak za tega, ki je zanje umrl in je bil obujen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 16, 'Zatorej mi od sedaj nikogar ne poznamo po mesu; če smo pa tudi poznali po mesu Kristusa, ali sedaj ga več ne poznamo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 17, 'Zato če je kdo v Kristusu, je novo stvarjenje; staro je prešlo, glej, postalo je novo vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 18, 'A vse to je iz Boga, ki nas je spravil s seboj po Kristusu in nam je dal službo sprave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 19, 'Bog je namreč bil v Kristusu in je svet spravil s seboj in jim ni zaračunil njih grehov, in poveril je nam besedo sprave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 20, 'Namesto Kristusa smo torej poslani, kakor da bi Bog opominjal po nas. Prosimo namesto Kristusa: Spravite se z Bogom!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 5, 21, 'Tega, ki ni poznal greha, je storil zaradi nas v greh, da bi postali mi pravičnost Božja v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 1, 'A kakor sodelavci Božji vas tudi opominjamo, da bi ne bili zaman prejeli milosti Božje –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 2, 'govori namreč: „Ob času prijetnem sem te uslišal in v dan zveličanja sem ti pomogel“. Glej, sedaj je čas jako prijeten, glej, sedaj je dan zveličanja; –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 3, 'nikomur v ničemer ne dajemo spotike, da se naši službi nič ne očita,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 4, 'temuč v vsem se izkazujemo kakor Božje služabnike v mnogem potrpljenju, v stiskah, v potrebah, v težavah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 5, 'v udarcih, v ječah, v uporih, v trudih, v nespavanju, v postu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 6, 'v čistosti, v znanju, v prizanesljivosti, v dobrotljivosti, v svetem Duhu, v nehinavski ljubezni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 7, 'v besedi resnice, v moči Božji; z orožjem pravičnosti na desno in levo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 8, 'pri slavi in nečasti, na slabem in dobrem glasu, kakor zapeljivci, in vendar resnični,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 9, 'kakor neznani, a dobro znani, kakor umirajoči, in glej, živimo, kakor kaznjeni, in vendar ne umorjeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 10, 'kakor žalosteči se, a vedno se veselimo, kakor siromaki, a mnoge bogatimo, kakor ničesar neimajoči, pa imamo vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 11, 'Naša usta so odprta k vam, Korinčani, srce naše je razširjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 12, 'Vam ni tesno v nas, ali vam je tesno v srcih vaših;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 13, 'a da nam isto povrnete (kakor svojim otrokom govorim), razširite se tudi vi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 14, 'Ne vlecite tujega jarma z neverniki. Kako se namreč druži pravica s krivico? ali kakšno tovarištvo ima svetlost s temo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 15, 'Kakšno pa soglasje Kristusa z Belijalom? ali kakšen delež ima vernik z nevernikom?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 16, 'A kakšna je zveza templja Božjega z maliki? Kajti mi smo tempelj Boga živega, kakor je rekel Bog: „Prebival bom v njih in med njimi bom hodil, in bodem njih Bog in oni bodo moje ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 17, 'Zato odidite izmed njih in se ločite, govori Gospod, in nečistega se ne dotikujte, in jaz vas sprejmem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 6, 18, 'in bodem vam Oče in vi bodete meni sinovi in hčere, pravi Gospod Vsemogočni“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 1, 'Ker imamo torej te obljube, ljubljeni, očistimo se vsakega madeža mesa in duha ter dopolnjujmo svetost v strahu Božjem!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 2, 'Dajte nam mesta v srcu! Nikomur nismo storili krivice, nikogar nismo popačili, nikogar nismo prekanili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 3, 'Ne govorim tega v vašo obsodbo; saj sem poprej rekel, da ste v srcih naših, da bi radi z vami vred umrli in vkup živeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 4, 'Velika je moja zaupljivost v govoru do vas, velika moja hvala o vas; napolnjen sem tolažbe, preobilo imam radosti ob vsej stiski naši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 5, 'Kajti tudi ko smo prišli v Macedonijo, ni imelo nič počitka meso naše, temuč z vseh strani smo bili stiskani: zunaj so bili boji, znotraj strah in bojazen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 6, 'Ali Bog, ki tolaži ponižne, nas je potolažil s prihodom Titovim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 7, 'toda ne samo s prihodom njegovim, ampak tudi s tolažbo, s katero se je on potolažil nad vami. Ko nam je pripovedoval vaše hrepenenje, vaš jok, vašo vnetost za mene, sem se tem bolj obveselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 8, 'Zakaj čeprav sem vas razžalostil z listom, ni mi žal, dasi mi je žal bilo; vidim namreč, da vas je oni list res razžalostil, čeprav začasno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 9, 'Sedaj se radujem, ne da ste se razžalostili, temuč da ste se razžalostili na izpokorjenje; razžalostili ste se namreč Bogu po volji, da bi v ničemer ne imeli škode od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 10, 'Kajti žalost, ki je po volji Bogu, rodi izpokorjenje na zveličanje, ki se ga nikdar ni kesati; a žalost sveta rodi smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 11, 'Zakaj glejte, prav to, da ste se po volji Bogu razžalostili, kolikšno vam je obrodilo marljivost, pa zagovarjanje, pa nevoljo, pa strah, pa hrepenenje, pa gorečnost, pa maščevanje! V vsem ste se pokazali, da ste čisti v tej zadevi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 12, 'Torej čeprav sem vam pisal, sem pisal ne za voljo tistega, ki je storil krivico, tudi ne za voljo tistega, ki se mu je krivica storila, marveč da se pri vas pokaže marljivost vaša za nas v pričo Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 13, 'Zato smo bili potolaženi. V svoji tolažbi pa smo se še obilneje obveselili vsled radosti Titove, ker njegov duh je bil poživljen po vas vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 14, 'Ker ako sem se v čem njemu pohvalil z vami, nisem osramočen; ampak kakor smo vam vse v resnici govorili, tako se je tudi pohvala naša proti Titu izkazala resnična.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 15, 'In srce njegovo vam je še bolj vdano, ko se spominja poslušnosti vseh vas, kako ste ga s strahom in trepetom sprejeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 7, 16, 'Vesel sem torej, da se smem v vsem zanašati na vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 1, 'A na znanje vam, bratje, dajemo milost Božjo, ki je dana v cerkvah macedonskih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 2, 'da se je vkljub mnogim stiskam, v katerih so bili preizkušeni, obilost njih radosti in njih prevelika revščina povzpela do bogate radodarnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 3, 'Kajti po svoji moči, da, pričam, čez svojo moč so dali dobrovoljno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 4, 'z mnogo prošnjo nas proseč te milosti, da se smejo udeležiti službe za svete;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 5, 'in ne samo to, kakor smo upali, marveč sebe so dali najprej Gospodu in nam po volji Božji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 6, 'tako da smo zaprosili Tita, da bi, kakor je prej započel, tako tudi dokončal pri vas tudi to milost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 7, 'Ali kakor ste v vsem bogati: v veri in besedi in spoznanju in vsaki marljivosti in svoji ljubezni do nas, bogati bodite tudi v tej milosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 8, 'Ne govorim po zapovedi, temuč da po marljivosti drugih izkusim resničnost vaše ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 9, 'Kajti poznate milost Gospoda našega Jezusa Kristusa, da je, ko je bil bogat, zavoljo vas obubožal, da bi vi po njegovem uboštvu obogateli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 10, 'In v tem vam dajem svet: to je namreč na prid vam, ki ste prvi, od lani, započeli ne samo to delati, ampak tudi hoteti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 11, 'Sedaj pa dokončajte tudi dejanje; kakor je bila dobra volja hoteti, tako naj bode tudi izvršitev po tem, kar imate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 12, 'Kajti če je dobra volja, prijetna je po tem, kar kdo ima, ne po tem, česar nima.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 13, 'Ne mislim namreč, da naj imajo drugi olajšavo, a vi stisko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 14, 'temuč po načelu enakosti: vaša obilost v sedanjem času naj služi za njih pomanjkanje, da bi tudi onih obilost služila za vaše pomanjkanje, da bode enakost;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 15, 'kakor je pisano: „Kdor je mnogo nabral, ni imel preobilo, in kdor je malo, ni mu manjkalo.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 16, 'Hvala pa Bogu, ki je dal isto marljivost za vas v srce Titovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 17, 'da je našo prošnjo sprejel, a ker je sam bil silno marljiv, je radovoljno odšel k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 18, 'Poslali pa smo ž njim vred brata, čigar hvala zaradi službe v evangeliju je po vseh cerkvah;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 19, 'a ne samo to, ampak cerkve so ga tudi izvolile za sopotnika našega s tem milodarom, ki ga oskrbujemo za samega Gospoda slavo in v dokaz naše dobre volje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 20, 'ogibajoč se tega, da nam kdo kaj ne očita glede te bogate miloščine, ki jo oskrbujemo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 21, 'skrbimo namreč za poštenost ne samo pred Gospodom, ampak tudi pred ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 22, 'Poslali smo pa ž njima vred brata svojega, ki smo ga izkusili v mnogih stvareh mnogokrat, da je marljiv, sedaj pa da je mnogo marljivejši po mnogem zaupanju, ki ga ima do vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 23, 'Kar se pa tiče Tita, on je moj tovariš in sodelavec za vas; kar se tiče naših bratov, ona sta poslanca cerkva, slava Kristusova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 8, 24, 'Pokažite torej v pričo cerkva do njih dokaz svoje ljubezni in naše hvale z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 1, 'Kajti zastran službe, ki je za svete, mi ni treba pisati vam;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 2, 'zakaj znana mi je vaša dobra volja, s katero se z vami hvalim Macedoncem, da je Ahaja pripravljena že od lani; in vaša gorečnost jih je prav mnogo izpodbodla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 3, 'A brate sem poslal, da ne bode hvala naša z vami zaman v tej zadevi, da bodete, kakor sem govoril, res pripravljeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 4, 'da se, ako pridejo z menoj Macedonci in vas najdejo nepripravljene, kako ne osramotimo mi (da ne rečem, vi) v tem svojem zaupanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 5, 'Potrebno se mi je torej zazdelo, poprositi brate, da bi šli pred mano k vam in prej pripravili vaš poprej obljubljeni blagoslov, da bode gotov, kakor resničen blagoslov in ne kakor skopost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 6, 'To pa pomnite: Kdor skopo seje, bo tudi skopo žel, in kdor seje bogato, bo tudi bogato žel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 7, 'Vsak naj da, kakor je v srcu namenil, ne z žalostjo ali po sili; kajti veselega dajalca ljubi Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 8, 'Bog pa more čez vas razliti obilo vsake milosti, da imate v vsem vsekdar vso obilost in ste bogati za vsako dobro delo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 9, 'kakor je pisano: „Razsipal je, dal je ubogim, njegova pravičnost ostane na vek.“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 10, 'Ta pa, ki daje seme sejalcu in kruh za jed, vam dodeli in razmnoži setev vašo ter dá, da bodo rasli sadovi pravičnosti vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 11, 'da obogatite v vsem za vsako radodarnost, ki napravlja po nas zahvalo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 12, 'Kajti služba tega opravila ne dopolnjuje samo pomanjkanja svetih, ampak prinaša tudi po zahvalah od mnogih obilen sad Bogu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 13, 'ker po preizkušnji te službe hvalijo Boga za vaše pokorno pripoznanje evangelija Kristusovega in za vaše radodarno podeljevanje njim in vsem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 14, 'ter molijo za vas tisti, ki hrepene po vas zavoljo premnoge milosti Božje v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 9, 15, 'Hvala Bogu za njegov neizrečni dar!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 1, 'Jaz Pavel sam pa vas opominjam po krotkosti in tihosti Kristusovi, ki sem vpričo vas resda ponižen med vami, a kadar me ni pri vas, pa drzen proti vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 2, 'Prosim pa, da mi ne bo treba, kadar bodem pri vas, drzen biti s to zaupnostjo, s katero mislim, da se smem zdrzniti na nekatere, ki mislijo, kakor da živimo po mesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 3, 'Kajti čeprav živimo v mesu, ne vojskujemo se po mesu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 4, '(zakaj orožje našega vojskovanja ni meseno, ampak močno po Bogu za razrušenje trdnjav),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 5, 'ko razdevamo sovražne naklepe in vsako visokost, ki se vzdiguje zoper spoznanje Božje, in vodimo vsako misel v sužnost pokorščine do Kristusa');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 6, 'in imamo pripravljeno maščevanje za vsako neposlušnost, kadar se izpolni vaša poslušnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 7, 'Gledate li na to, kar je pred očmi? Če kdo zaupa sebi, da je Kristusov, pomisli naj zopet v sebi to: kakor je on Kristusov, prav tako smo tudi mi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 8, 'Kajti ko bi se tudi kaj obilneje hvalil z oblastjo našo, ki jo je nam dal Gospod za zidanje in ne za razdevanje vaše, ne bom se osramotil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 9, 'da se ne bo videlo, kakor da vas strašim z listi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 10, 'Kajti ‚listi njegovi‘, pravijo, ‚so tehtni in krepki, ali ko je navzočen s telesom, je slaboten in beseda mu je šibka‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 11, 'To naj misli, kdor tako govori, da kakršni smo nenavzočni v besedi po listih, taki smo tudi navzočni v dejanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 12, 'Kajti ne drznemo se pridružiti se k nekaterim ali primerjati se ž njimi, ki sami sebe priporočajo; kateri pa, ko se sami po sebi merijo in primerjajo sami sebe s seboj, ničesar ne umejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 13, 'A mi se ne bomo čez vso mero hvalili, temuč po meri delokroga, ki nam ga je Bog podelil za mero, da naj dospemo tudi do vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 14, 'Kajti mi se ne iztezamo predaleč, kakor da bi ne mogli doseči do vas, zakaj tudi prav do vas smo prišli v evangeliju Kristusovem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 15, 'in ne hvalimo se čez mero ali s tujimi trudi, temuč imamo upanje, da se, ker raste vera vaša, poveličamo med vami v soglasju z delokrogom svojim na še večjo obilnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 16, 'tako da še onkraj vas oznanimo evangelij, ne da bi se hvalili s tem, kar je v delokrogu drugega že napravljenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 17, 'Kdor se pa hvali, v Gospodu naj se hvali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 10, 18, 'Kajti kdor sam sebe priporoča, ni preizkušen, ampak ta, kogar Gospod priporoča.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 1, 'O, da bi me trpeli malo v moji nespameti! Pa saj me tudi potrpite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 2, 'Kajti vnet sem za vas z Božjo gorečnostjo, ker sem vas zaročil enemu možu, da vas privedem kot čisto devico Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 3, 'Bojim se pa, da se ne bi, kakor je kača Evo ukanila z zvijačo svojo, nekako tudi pokvarile misli vaše in se odvrnile od preprostosti in čistosti, ki je v srcu do Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 4, 'Kajti ko bi ta, ki prihaja, oznanjeval drugega Jezusa, ki ga mi nismo oznanili, ali ko bi prejemali drugega duha, ki ga niste prej prejeli, ali drugačen evangelij, ki ga niste sprejeli, lepo bi to trpeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 5, 'Mislim namreč, da v ničemer nisem manjši od onih prevelikih apostolov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 6, 'Čeprav pa sem neuk v govoru, vendar nisem v znanju; ali v vsem smo znani pri vseh med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 7, 'Ali pa sem storil greh, sam sebe ponižujoč, da se vi povišate, ker sem vam brezplačno oznanil Božji evangelij?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 8, 'Druge cerkve sem slekel, vzemši plačilo od njih, da morem služiti vam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 9, 'in ko sem bil pri vas in sem stradal, nisem bil nikomur nadležen. Kolikor mi je namreč manjkalo, so doložili bratje, ki so prišli od Macedonije; in v vsem sem se zdržal brez nadlege vam in se še zdržim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 10, 'Kakor je resnica Kristusova v meni, te hvale mi nihče ne vzame v krajih ahajskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 11, 'Zakaj? ker vas ne ljubim? Bog ve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 12, 'Kar pa delam, še bom delal, da odvzamem priložnost tistim, ki priložnosti iščejo, da bi se, v čemer se hvalijo, pokazali take kakor tudi mi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 13, 'Kajti taki so krivi apostoli, ukanljivi delavci, izpreminjajoči se v apostole Kristusove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 14, 'In ni čuda, zakaj sam satan se izpreminja v angela svetlobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 15, 'Ni torej nič velikega, če se tudi služabniki njegovi izpreminjajo v služabnike pravičnosti; katerih konec bode po njih delih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 16, 'Zopet pravim: Nihče naj ne misli, da sem nespameten. Če pa vendar mislite, pa me tudi sprejmite kakor nespametnega, da se nekoliko tudi jaz pohvalim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 17, 'Kar zdaj govorim, ne govorim po Gospodu, ampak kakor v nespameti, v svesti si, da se smem hvaliti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 18, 'Ko se mnogi hvalijo po mesu, naj se tudi jaz pohvalim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 19, 'Kajti radi prenašate nespametne, ko ste sami pametni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 20, 'Prenašate namreč, če vas kdo usužnuje, če vam kdo pojeda, če kdo jemlje, če se kdo povzdiguje, če vas kdo v lice bije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 21, 'Na sramoto priznavam: za to smo pa bili preslabi. V čemer je pa kdo drzen (po nespameti govorim), drzen sem tudi jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 22, 'Hebrejci so? Tudi jaz sem. Izraelci so? Tudi jaz sem. Seme Abrahamovo so? Tudi jaz sem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 23, 'Služabniki Kristusovi so? (Ne govorim po pameti:) Še bolj jaz: v trudih sem bil obilneje, v ječah obilneje, v udarcih neizmerneje, v smrti mnogokrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 24, 'Od Judov sem jih dobil petkrat po štirideset brez ene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 25, 'trikrat so me šibali, enkrat kamenali, trikrat se je z menoj ladja razbila, noč in dan sem prebil sredi valov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 26, 'potoval sem mnogokrat, bil sem v nevarnostih od voda, v nevarnostih od razbojnikov, v nevarnostih od rojakov, v nevarnostih od poganov, v nevarnostih v mestu, v nevarnostih v puščavi, v nevarnostih na morju, v nevarnostih med krivimi brati:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 27, 'v trudu in težavi, dostikrat v nespavanju, v lakoti in žeji, čestokrat v postu, v mrazu in goloti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 28, 'Razen tega, kar je zunanjega, je vsakdanji naval do mene, skrb za vse cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 29, 'Kdo oslabi, da bi tudi jaz ne oslabel? Kdo se pohujšuje, da bi tudi mene ne skelelo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 30, 'Če se je treba hvaliti, hvalil se bom s tem, kar se tiče moje slabosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 31, 'Bog in Oče Gospoda našega Jezusa, ki je hvaljen na veke, ve, da ne lažem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 32, 'V Damasku je dal namestnik kralja Areta zastražiti mesto Damaščanov, hoteč me ujeti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 11, 33, 'pa skozi okno v košu so me po zidu spustili, in tako sem ubežal njegovim rokam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 1, 'Hvaliti se mi je treba, dasi nič ne koristi; pridem pa zdaj do prikazni in razodetij Gospodovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 2, 'Poznam človeka v Kristusu, ki je bil pred štirinajstimi leti (ali v telesu, ne vem, ali izven telesa, ne vem; Bog ve), vzet tja v tretja nebesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 3, 'In poznam takega človeka (ali v telesu, ali izven telesa, ne vem; Bog ve),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 4, 'da je bil vzet v raj in je slišal neizrečne besede, katerih ne sme človek govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 5, 'S takim se bom hvalil, sam s seboj se pa ne bom hvalil, razen s slabostmi svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 6, 'Kajti ko bi se hotel pohvaliti, ne bi bil nespameten, ker bi govoril resnico; zdržim se pa, da ne bi kdo več o meni mislil, nego kar vidi na meni ali kar sliši od mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 7, 'In zavoljo visokih razodetij, da bi se ne prevzel, mi je dan trn v meso, angel satanov, da me za uho bije, da se ne prevzamem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 8, 'Zavoljo tega sem trikrat prosil Gospoda, da bi odstopil od mene,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 9, 'a dejal mi je: Dosti ti je moja milost; zakaj moč moja se v slabosti izkazuje popolna. Torej se bom najrajši hvalil s slabostmi svojimi, da se ušatori nad mano moč Kristusova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 10, 'Zato sem dobre volje v slabostih, v zasramovanju, v potrebah, v preganjanju, v težavah, za Kristusa; zakaj kadar sem slab, tedaj sem močan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 11, 'Postal sem nespameten, hvaleč se; vi ste me prisilili. Kajti mene bi bili morali vi hvaliti, ker nisem bil nič manjši od onih prevelikih apostolov, čeprav nisem nič.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 12, 'Saj so se znamenja apostola godila med vami v vsem potrpljenju, v znamenjih in čudežih in močeh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 13, 'Kaj namreč je, v čemer ste bili prikrajšani nasproti drugim cerkvam, razen le, da vas jaz sam nisem nadlegoval? Odpustite mi to krivico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 14, 'Glej, tretjič sem pripravljen priti k vam in ne bom vas nadlegoval; kajti ne iščem, kar je vašega, marveč vas. Niso namreč otroci dolžni roditeljem zakladov zbirati, ampak roditelji otrokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 15, 'A jaz prav rad potrošim vse in sebe žrtvujem za duše vaše. Če vas obilneje ljubim, me li tem manj ljubite?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 16, 'Ali naj bo, jaz vam nisem bil nadležen; toda ‚zvit človek sem vas z zvijačo pridobil‘.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 17, 'Sem li vas mar opeharil po katerem teh, ki sem jih k vam poslal?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 18, 'Naprosil sem Tita in ž njim poslal brata: ali vas je mar Tit opeharil? Nismo li v enem Duhu hodili? ne po enih stopinjah?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 19, 'Ves ta čas mislite, da se vam zagovarjamo. Pred Bogom v Kristusu govorimo, a vse to, ljubljeni, da pospešimo vaš napredek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 20, 'Kajti bojim se, da vas morda, kadar pridem, ne najdem takih, kakršne hočem, in da mene najdete takega, kakršnega nočete; da morda bodo med vami prepiri, zavist, srd, svade, opravljanje, prišeptavanje, hujskanje, neredi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 12, 21, 'da me, ko zopet pridem, poniža Bog moj pri vas in da se bom žalostil zaradi mnogih, ki so prej grešili in se niso kesali za nečistost in nesramnost in pohotnost, ki so jo počeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 1, 'Sedaj grem tretjič k vam. Na tem, kar povesta dve priči ali tri, bo stala vsaka beseda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 2, 'Prej sem povedal in prej pravim, kakor drugič navzočen in sedaj nenavzočen, tem, kateri so prej grešili, in vsem drugim: kadar pridem zopet, ne bom prizanašal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 3, 'ker iščete dokaza, da v meni govori Kristus, ki za vas ni slaboten, temuč je močan med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 4, 'Kajti čeprav je bil na križ razpet po slabosti, vendar živi po moči Božji. In tako smo tudi mi slabotni v njem, ali živeli bomo ž njim po moči Božji za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 5, 'Sami sebe izkušajte, če ste v veri, sami sebe ogledujte! Ali pa ne poznate sami sebe, da je Jezus Kristus v vas? razen če ste morda odvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 6, 'Upam pa, da boste spoznali, da mi nismo odvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 7, 'Molimo pa k Bogu, da ne storite nič hudega, ne da se mi pokažemo preizkušene, ampak da vi dobro delate, čeprav bomo mi kakor odvrženi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 8, 'Kajti ničesar ne moremo zoper resnico, ampak vse za resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 9, 'Veselimo se namreč, kadar smo mi slabotni, a vi močni; da, zato tudi molimo: za vašo popolnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 10, 'Zato pišem to nenavzočen, da mi v navzočnosti ne bo treba biti ostremu po oblasti, ki mi jo je dal Gospod na zidanje in ne na razdevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 11, 'Sicer se pa, bratje, radujte, bodite popolni, tolažite se, ene misli bodite, v miru živite; in Bog ljubezni in miru bode z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 12, 'Pozdravite drug drugega v svetem poljubu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 13, 'Pozdravljajo vas vsi sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (47, 13, 14, 'Milost Gospoda Jezusa Kristusa in ljubezen Božja in deleštvo svetega Duha z vsemi vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 1, 'Pavel, apostol (ne od ljudi, tudi ne po človeku, ampak po Jezusu Kristusu in po Bogu Očetu, ki ga je obudil iz mrtvih),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 2, 'in vsi bratje, ki so z menoj, cerkvam v Galaciji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 3, 'Milost vam in mir od Boga Očeta in Gospoda našega Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 4, 'ki je dal samega sebe za grehe naše, da nas otme iz sedanjega hudega veka po volji Boga in Očeta našega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 5, 'ki mu bodi slava na veke vekomaj! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 6, 'Čudim se, da ste se tako hitro odvrnili od tega, ki vas je poklical po milosti Kristusovi, na drugačen evangelij,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 7, 'ko vendar ni drugega evangelija, samo da so nekateri, ki vas motijo in hočejo preobrniti evangelij Kristusov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 8, 'Ali ko bi vam tudi mi ali angel iz nebes oznanjeval evangelij drugače, kakor smo vam ga mi oznanili, bodi proklet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 9, 'Kakor smo poprej rekli, tudi sedaj zopet pravim: Če vam kdo oznanjuje evangelij drugače, kakor ste ga prejeli, bodi proklet!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 10, 'Govorim li sedaj, da se prikupim ljudem ali Bogu? Ali pa skušam biti ljudem pogodu? Ko bi še ljudem bil pogodu, ne bi bil Kristusov služabnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 11, 'Kajti na znanje vam dajem, bratje, da evangelij, ki sem ga jaz oznanil, ni po človeku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 12, 'saj ga tudi jaz nisem prejel od človeka, niti se ga naučil, temuč po razodetju Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 13, 'Kajti slišali ste o mojem nekdanjem vedenju v judovstvu, da sem čez mero preganjal cerkev Božjo in jo zatiral,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 14, 'in sem napredoval v judovstvu bolj od mnogih vrstnikov v rodu svojem in bil sem preobilo vnet za očetov svojih izročila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 15, 'Ko se je pa vzvidelo Bogu, ki me je odločil zase od telesa matere moje in poklical po milosti svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 16, 'da razodene Sina svojega v meni, da oznanim blagovestje o njem med pogani: precej nisem za svet poprašal mesa in krvi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 17, 'tudi nisem šel gori v Jeruzalem k tistim, ki so bili pred menoj apostoli, ampak odšel sem v Arabijo in zopet sem se povrnil v Damask.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 18, 'Potem čez tri leta sem šel gori v Jeruzalem, da obiščem Petra, in ostal sem pri njem petnajst dni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 19, 'Drugega pa izmed apostolov nisem videl, razen Jakoba, brata Gospodovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 20, 'A kar vam pišem, glejte, vpričo Boga: ne lažem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 21, 'Potem sem prišel v kraje sirske in cilicijske.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 22, 'Bil sem pa neznan po licu cerkvam v Judeji, ki so v Kristusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 23, 'samo slišali so, da tisti, ki nas je nekdaj preganjal, sedaj kot blagovestje oznanjuje vero, ki jo je nekdaj zatiral,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 1, 24, 'in slavili so zavoljo mene Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 1, 'Potem čez štirinajst let sem zopet šel gori v Jeruzalem z Barnabom in vzel s seboj tudi Tita.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 2, 'Šel sem pa gori po razodetju in sem jim razložil evangelij, ki ga propovedujem med pogani, a posebe njim, ki so kaj veljali, da bi ne bil moj trud prej ali slej zaman.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 3, 'Ali tudi Tit, ki je bil z menoj in je bil Grk, ni bil prisiljen, da se obreže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 4, 'To pa zavoljo krivih bratov, ki so se prikradli in vmes vrinili, oprezovat svobodo našo, ki jo imamo v Kristusu Jezusu, da bi nas zasužnjili;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 5, 'katerim se niti za uro nismo vdali in podvrgli, da bi resnica evangelija ostala pri vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 6, 'Od tistih pa, ki so kaj veljali (kakšni so bili nekdaj, zato mi nič ni; Bog ne gleda, kdo je kdo), ti namreč, ki so kaj veljali, niso meni nič pridali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 7, 'temuč nasprotno, videč, da je meni zaupan evangelij za neobrezo kakor Petru za obrezo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 8, '(kajti On, ki je v Petru deloval za apostolstvo obreze, je deloval tudi v meni za pogane),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 9, 'in spoznavši milost, ki mi je dana, so podali Jakob in Kefa in Janez, ki so veljali za stebre, desnice meni in Barnabu v potrjenje tovarištva, naj greva midva med pogane, a oni med obrezo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 10, 'samo da se spominjava ubogih; za to sem se tudi potrudil, da se tako stori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 11, 'Ko pa je prišel Kefa v Antiohijo, sem ga iz oči v oči karal, ker je bil graje vreden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 12, 'Kajti preden so prišli nekateri od Jakoba, je jedel s pogani; ko so pa prišli, se je umikal in se ločil, boječ se tistih, ki so bili iz obreze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 13, 'In ž njim vred so se hlinili tudi drugi Judje, tako da je tudi Barnaba zavedlo njih hlinjenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 14, 'Ali ko sem videl, da ne hodijo prav po resnici evangelija, sem rekel Kefu pred vsemi: Če ti, ki si Jud, poganski živiš in ne judovski, zakaj siliš pogane, da žive judovski? –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 15, 'Mi smo po rodu Judje in ne iz poganov grešniki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 16, 'ker pa vemo, da se ne opravičuje človek iz del postave, nego samo po veri v Jezusa Kristusa, smo sprejeli tudi mi vero v Kristusa Jezusa, da bi bili opravičeni iz vere Kristusove in ne iz del postave, ker se iz del postave ne opraviči nobeno meso.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 17, 'Ako smo pa mi pri tem, ko iščemo biti opravičeni v Kristusu, tudi sami spoznani za grešnike, je li torej Kristus grehu služabnik? Nikakor ne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 18, 'Zakaj če zidam zopet to, kar sem podrl, se kažem sam, da sem prestopnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 19, 'Jaz sem namreč po postavi umrl postavi, da Bogu živim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 20, 'S Kristusom sem na križ razpet. Živim pa ne več jaz, marveč Kristus živi v meni; kolikor pa sedaj živim v mesu, živim v veri Sinu Božjega, ki me je ljubil in dal samega sebe zame.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 2, 21, 'Ne zametam milosti Božje, kajti če je po postavi pravičnost, je Kristus zastonj umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 1, 'O nespametni Galati! kdo vas je očaral? Vam je bil vendar pred očmi opisan Jezus Kristus, na križ razpeti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 2, 'To samo hočem zvedeti od vas: Ste li po delih postave prejeli Duha ali s poslušanjem vere?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 3, 'Ste li tako nespametni? začenši v Duhu, sedaj v mesu dokončujete?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 4, 'Toliko ste zastonj pretrpeli? če bi le bilo tudi zastonj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 5, 'On torej, ki vam daje Duha in dela čudeže med vami, dela li to po delih postave ali po poslušanju vere?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 6, 'Kakor „je Abraham veroval Bogu, in zaračunilo se mu je za pravičnost“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 7, 'Spoznajte torej, da so tisti, ki so iz vere, sinovi Abrahamovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 8, 'Ker pa je pismo naprej videlo, da Bog iz vere opravičuje pogane, je naprej oznanilo Abrahamu blagovestje: „V tebi bodo blagoslovljeni vsi narodi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 9, 'Tako so tisti, ki so iz vere, blagoslovljeni z vernim Abrahamom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 10, 'Katerikoli so namreč iz del postave, so pod kletvijo; kajti pisano je: „Proklet vsak, kdor ne ostane v vsem, kar je pisano v knjigi postave, da naj stori“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 11, 'Da se pa po postavi nihče ne opraviči pred Bogom, je očitno, zakaj: „Pravični bo iz vere živel“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 12, 'A postava ne sloni na veri, temuč: „kdor zapovedi izpolnjuje, bo živel po njih“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 13, 'Kristus nas je odkupil iz kletve postave, ko je postal za nas kletev, kajti pisano je: „Proklet vsak, kdor visi na lesu“:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 14, 'da pride nad pogane blagoslov Abrahamov v Kristusu Jezusu, da prejmemo obljubo Duha po veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 15, 'Bratje, po človeško govorim: Najsi bo le človeška zaveza, vendar, ko je potrjena, je nihče ne zameta ali ji kaj prideva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 16, 'Abrahamu pa so bile dane obljube in semenu njegovemu. Ne pravi: „In semenom“, kakor da bi jih bilo več, temuč kakor za enega: „In semenu tvojemu“, ki je Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 17, 'To pa pravim: Zaveze, ki jo je prej potrdil Bog, štiristo in trideset let pozneje dana postava ne razveljavlja, da se obljuba tako odpravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 18, 'Kajti če je iz postave dediščina, ni več iz obljube; toda Abrahamu jo je po obljubi milostno podaril Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 19, 'Čemu torej postava? Zavoljo prestopkov se je pridodala, dokler ne pride seme, ki mu je dana obljuba, in je bila urejena po angelih, po roki srednika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 20, 'Ali srednik ne posreduje pri enem, Bog pa je eden.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 21, 'Je li torej postava zoper obljube Božje? Nikakor ne; kajti ko bi se bila dala postava, ki bi mogla oživiti, zares bi bila iz postave pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 22, 'Toda pismo je vse zaklenilo pod greh, da bi se obljuba na podlagi vere v Jezusa Kristusa dala tem, ki verujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 23, 'Preden je pa prišla vera, smo bili pod postavo, ki nas je stražila, zaklenjeni za vero, ki se je imela razodeti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 24, 'Tako je bila postava voditeljica naša do Kristusa, da bi bili iz vere opravičeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 25, 'A ko je vera prišla, nismo več pod voditeljico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 26, 'Zakaj vsi ste sinovi Božji po veri, v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 27, 'Kajti katerikoli ste bili krščeni v Kristusa, ste Kristusa oblekli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 28, 'Ni tu Juda, ne Grka, ni tu sužnja, ne svobodnega, ni tu moškega, ne ženske: zakaj vi vsi ste eden v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 3, 29, 'Če ste pa Kristusovi, potem ste Abrahamovo seme, in po obljubi dediči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 1, 'Pravim pa, dokler je dedič nedoleten, se nič ne razločuje od sužnja, čeprav je vsega gospodar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 2, 'marveč je pod varuhi in oskrbniki do dne, postavljenega po očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 3, 'Tako smo bili tudi mi, dokler smo bili nedoletni, pod prvim ukom sveta zasužnjeni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 4, 'ko pa je bil dopolnjen čas, je odposlal Bog Sina svojega, rojenega iz žene, podvrženega postavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 5, 'da odkupi tiste, ki so bili pod postavo, da prejmemo sinovstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 6, 'Ker ste pa sinovi, je odposlal Bog Duha Sina svojega v vaša srca, ki kliče: Abá, Oče!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 7, 'Tako nisi več suženj, ampak sin; ako pa si sin, si tudi dedič po Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 8, 'Ali takrat ste, seveda ne poznavajoč Boga, sužnjevali tistim, ki po naravi niso bogovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 9, 'a sedaj, spoznavši Boga, še bolj pa spoznani od Boga, kako da se zopet vračate k prvim naukom, medlim in ubornim, ki jim hočete vnovič sužnjevati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 10, 'Dneve obhajate in mesece in čase in leta!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 11, 'Bojim se za vas, da bi se ne bil morda zastonj trudil za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 12, 'Bodite kakor sem jaz, ker sem tudi jaz kakor vi, bratje, prosim vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 13, 'Nobene krivice mi niste storili; veste pa, da sem vam v slabosti mesa najprvo oznanjeval evangelij,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 14, 'in me niste vzlic svoji izkušnjavi na mesu mojem zaničevali, ne zavrgli, marveč kakor angela Božjega ste me sprejeli, kakor Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 15, 'Kje je torej vaše tedanje blaženstvo? kajti pričam vam, da bi bili, ko bi bilo mogoče, oči svoje izdrli in jih meni dali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 16, 'Tako sem torej postal vaš sovražnik, govoreč vam resnico?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 17, 'Vnemajo se za vas, pa ne kakor je prav, temuč izkleniti vas hočejo od mene, da bi se vi zanje vnemali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 18, 'Dobro pa je, vnemati se v dobrem vsekdar, in ne samo, kadar sem jaz pri vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 19, 'Otroci moji, ki jih zopet z bolečinami porajam, dokler se ne upodobi Kristus v vas –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 20, 'želel bi pa biti sedaj pri vas in premeniti glas svoj, ker sem v zadregi zastran vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 21, 'Recite mi, kateri hočete biti pod postavo, ne slišite li postave?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 22, 'Kajti pisano je, da je imel Abraham dva sina, enega od dekle in enega od svobodnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 23, 'Toda kateri je bil od sužnje, se je narodil po mesu, a kateri od svobodne, po obljubi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 24, 'To pa je v prispodobi govorjeno: ti dve ženi sta namreč dve zavezi, ena z gore Sinajske, ki rodi za sužnost, in ta je Agara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 25, 'Agara pa pomeni goro Sinaj v Arabiji in stoji v eni vrsti s sedanjim Jeruzalemom, ki sužnjuje z otroki svojimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 26, 'A gornji Jeruzalem je svobodnica, in ta je naša mati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 27, 'Kajti pisano je: „Razveseli se, nerodovitna, ki ne porajaš; zaukaj in kliči, ki nisi v porodnih bolečinah; zakaj mnogo več je otrok te, ki je osamljena, nego one, ki ima moža“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 28, 'Mi pa smo, bratje, kakor Izak, otroci obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 29, 'Ali kakor je takrat tisti, ki se je po mesu narodil, preganjal tega, ki je bil po Duhu rojen, tako tudi sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 30, 'Toda kaj pravi pismo? „Spodi deklo in nje sina; zakaj ne bo dedoval sin sužnje s sinom svobodnice“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 4, 31, 'Zato, bratje, nismo otroci sužnje, ampak svobodne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 1, 'Za svobodo nas je Kristus osvobodil; stojte torej trdno in ne vprezite se zopet v jarem sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 2, 'Glejte, jaz Pavel vam pravim: ako sprejmete obrezo, vam Kristus ne bo nič pomagal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 3, 'A pričam zopet vsakemu človeku, ki se obreže, da je dolžen celo postavo izpolniti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 4, 'Ločeni ste od Kristusa, katerikoli se po postavi hočete opravičiti, iz milosti ste padli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 5, 'Mi namreč po Duhu na podlagi vere čakamo upanja pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 6, 'Kajti v Kristusu Jezusu nič ne koristi ne obreza niti neobreza, ampak vera, ki deluje po ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 7, 'Tekli ste dobro; kdo vas je ustavil, da niste resnici pokorni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 8, 'To pregovarjanje ni od tega, ki vas kliče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 9, 'Malo kvasu skisa vse testo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 10, 'Jaz se zanašam na vas v Gospodu, da ne boste nič drugega mislili; kdor pa vas moti, bo svojo obsodbo nosil, bodisi kdorkoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 11, 'Ali, bratje, če jaz obrezo še oznanjam, zakaj me še preganjajo? Saj je potem odpravljeno pohujšanje križa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 12, 'O da bi se sami odrezali tisti, kateri vas v zmešnjavo zavajajo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 13, 'Kajti vi ste poklicani na svobodo, bratje; samo naj svoboda ne bode za priložnost mesu, temuč po ljubezni služite drug drugemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 14, 'Zakaj vsa postava se izpolnjuje v eni besedi, v tejle: „Ljubi bližnjega svojega kakor samega sebe“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 15, 'Če pa drug drugega grizete in ujedate, gledite, da drug drugega ne iztrebite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 16, 'Pravim pa: Po Duhu živite, in poželenja mesa ne boste izpolnjevali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 17, 'Kajti meso želi zoper Duha, a Duh zoper meso; ta sta namreč nasprotna drug drugemu, da ne delate, kar hočete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 18, 'Če se pa daste Duhu voditi, niste pod postavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 19, 'Očitna so pa dela mesa, katera so: prešeštvo, nečistost, pohotnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 20, 'malikovalstvo, čarodejstvo, sovraštvo, prepiri, zavist, maščevanje, svade, razprtije, razkolništva,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 21, 'nevoščljivosti, ubojstva, pijanstvo, požrešnost in kar je temu podobnega; o čemer vam naprej pravim, kakor sem tudi naprej povedal, da tisti, ki to delajo, ne bodo podedovali kraljestva Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 22, 'Sad Duha je pa ljubezen, radost, mir, potrpežljivost, prijaznost, dobrotljivost, zvestost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 23, 'krotkost, zdržljivost; zoper take ni postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 24, 'Kateri so pa Kristusovi Jezusovi, so meso na križ razpeli s slami in željami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 25, 'Če živimo po Duhu, po Duhu tudi ravnajmo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 5, 26, 'Ne iščimo prazne slave, da ne dražimo drug drugega, da nismo drug drugemu nevoščljivi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 1, 'Bratje, če bi tudi bil človek prenagljen od kake pregrehe, takemu vi, ki ste duhovni, pomagajte v pravi stan v duhu krotkosti, in glej sam nase, da tudi ti ne boš izkušan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 2, 'Drug drugega nosite bremena, in tako izpolnite postavo Kristusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 3, 'Zakaj če kdo misli, da je kaj, a ni nič, slepi sam sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 4, 'A svoje delo naj vsakdo izkuša, in tedaj bo imel na samem sebi kaj hvaliti in ne na drugem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 5, 'Vsak namreč bo nosil svoje breme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 6, 'A kdor se uči besede, naj deli vse dobrote s tem, ki ga uči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 7, 'Ne motite se, Bog se ne da zasmehovati; kajti kar človek seje, to bo tudi žel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 8, 'Ker kdor seje v meso svoje, od mesa bo žel pogubo, a kdor seje v Duha, od Duha bo žel življenje večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 9, 'Dobro delati se pa nikar ne utrudimo; zakaj ob svojem času bomo želi, če ne obnemoremo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 10, 'Dokler torej nam je časa, delajmo dobro vsem, a najbolj tem, ki smo si ž njimi domači po veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 11, 'Vidite, koliko sem vam napisal s svojo roko!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 12, 'Kateri se hočejo nazunaj prijetne kazati po mesu, vas silijo, da se obrezujte, samo da ne bodo zavoljo križa Kristusovega preganjani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 13, 'Zakaj tisti, ki se obrezujejo, še sami ne držé postave, temuč hočejo, da se vi obrezujete, da bi se z vašim mesom hvalili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 14, 'A Bog ne daj, da bi se jaz hvalil, razen s križem Gospoda našega Jezusa Kristusa, po katerem je meni svet na križ razpet in jaz svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 15, 'Kajti obreza ne velja nič niti neobreza, ampak novo stvarjenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 16, 'In kolikor jih bo živelo po tem vodilu, mir nanje in usmiljenje in na Izraela Božjega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 17, 'A nadalje mi nihče ne bodi nadležen, kajti jaz nosim rane Gospoda Jezusa na telesu svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (48, 6, 18, 'Milost Gospoda našega Jezusa Kristusa bodi z duhom vašim, bratje! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 1, 'Pavel, apostol Kristusa Jezusa po volji Božji, svetim, ki so v Efezu, in vernim v Kristusu Jezusu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 2, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 3, 'Hvaljen bodi Bog in Oče Gospoda našega Jezusa Kristusa, ki nas je blagoslovil z vsakim blagoslovom duhovnim v nebesih v Kristusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 4, 'kakor nas je izvolil v njem pred ustanovitvijo sveta, da bodimo sveti in brezmadežni pred obličjem njegovim v ljubezni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 5, 'odmenivši nas naprej za sinovstvo po Jezusu Kristusu za sebe, kakor je ugajalo volji njegovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 6, 'v hvalo slave milosti svoje, s katero nas je pomilostil v svojem Ljubljencu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 7, 'V katerem imamo odrešenje po krvi njegovi, odpuščenje grehov, po bogastvu milosti njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 8, 'katere nam je preobilo podelil v vsej modrosti in razumnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 9, 'razodevši nam skrivnost volje svoje po blagovoljnem sklepu svojem, ki ga je sklenil v sebi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 10, 'za uravnavo izpolnitve časov, da vse zedini pod eno glavo v Kristusu, kar je na nebesih in kar je na zemlji, v njem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 11, 'v katerem smo tudi dobili delež kot naprej odmenjeni po sklepu njega, ki vse dela po ukrepu volje svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 12, 'da bodimo v hvalo slave njegove, ki smo prej stavili upanje v Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 13, 'V katerem ste tudi vi, ko ste slišali besedo resnice, evangelij zveličanja svojega, v katerem ste tudi, sprejemši vero, bili zapečateni s svetim Duhom obljube,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 14, 'ki je zastava dediščine naše, v odrešitev lastnine božje, v hvalo slave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 15, 'Zatorej se tudi jaz, ko sem zvedel za vero, ki je pri vas v Gospoda Jezusa, in za ljubezen do vseh svetih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 16, 'zahvaljujem neprestano za vas, spominjajoč se vas v molitvah svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 17, 'da vam dá Bog Gospoda našega Jezusa Kristusa, Oče slave, duha modrosti in razodetja v spoznanju njegovem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 18, 'razsvetljene oči srca vašega, da veste, kakšno je upanje poklica njegovega in kakšno bogastvo slave dediščine njegove v svetih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 19, 'in kakšna presilna velikost moči njegove do nas verujočih po delovanju silne moči njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 20, 'ki jo je pokazal v Kristusu, zbudivši ga izmed mrtvih in posadivši ga na desnico svojo v nebesih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 21, 'nad vsako poglavarstvo in oblast in moč in gospostvo, in nad vsako ime, ki se imenuje ne samo na tem svetu, ampak tudi v prihodnjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 22, 'in vse je položil pod noge njegove in njega je dal kot glavo nad vsem cerkvi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 1, 23, 'ki je telo njegovo, izpolnitev njega, ki vse v vsem izpolnjuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 1, 'Tudi vas je oživil, ki ste bili mrtvi po prestopkih in grehih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 2, 'v katerih ste nekdaj hodili po navadi tega sveta, po knezu oblasti v zraku, po duhu, ki deluje zdaj v sinovih nepokorščine;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 3, 'med katerimi smo tudi mi vsi nekdaj živeli v poželjivostih mesa svojega ter delali želje mesa in misli, in bili smo po naravi otroci jeze Božje, kakor tudi drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 4, 'Bog pa, bogat v usmiljenju, zaradi velike ljubezni svoje, ki nas je ž njo ljubil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 5, 'nas je, ko smo tudi bili mrtvi po grehih, oživil s Kristusom vred (po milosti ste rešeni)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 6, 'in ž njim vred obudil in posadil v nebesih v Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 7, 'da pokaže v prihodnjih vekih presilno bogastvo milosti svoje v dobrotljivosti do nas v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 8, 'Kajti iz milosti ste rešeni po veri, in to ni iz vas, dar Božji je to;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 9, 'ne iz del, da se nihče ne hvali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 10, 'Njegovo namreč smo delo, ustvarjeni v Kristusu Jezusu za dobra dela, ki jih je Bog naprej pripravil, da živimo v njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 11, 'Zatorej pomnite, da ste bili nekdaj vi, pogani v mesu, ki jih imenuje neobrezo tako imenovana obreza, ki pa je le na mesu, z roko storjena,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 12, 'da ste bili v tistem času brez Kristusa, izključeni od meščanstva Izraelovega in tujci zavezam obljube, ne imajoč upanja in brez Boga na svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 13, 'Sedaj pa, v Kristusu Jezusu, ste vi, ki ste bili nekdaj daleč, postavljeni blizu po krvi Kristusovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 14, 'Kajti on je mir naš, ki je naredil iz obojega eno in podrl ločilno pregrajo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 15, 's tem, da je v mesu svojem odpravil sovraštvo, postavo zapovedi, obseženo v poveljih, da bi ta dva v sebi ustvaril v enega novega človeka, storivši mir,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 16, 'in oba v enem telesu z Bogom spravil po križu, umorivši sovraštvo na njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 17, 'In je prišel in oznanjal mir vam, ki ste bili daleč, in mir njim, ki so bili blizu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 18, 'ker po njem le imamo, oboji v enem Duhu, pristop k Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 19, 'Tako torej niste več tujci in priseljenci, marveč ste someščani svetih in domačini Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 20, 'sezidani na temelju apostolov in prorokov, vogelni kamen pa je Jezus Kristus sam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 21, 'v katerem je vse poslopje točno sestavljeno in raste v svet tempelj v Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 2, 22, 'v katerem se tudi vi z drugimi vred vzidavate v bivališče Božje v Duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 1, 'Zategadelj jaz, Pavel, jetnik Kristusa Jezusa za vas pogane –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 2, 'ako ste sicer slišali o oskrbništvu milosti Božje, ki mi je dana za vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 3, 'da se mi je po razodetju naznanila skrivnost (kakor sem prej pisal ob kratkem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 4, 'iz česar morete, ko berete, spoznati razumevanje moje skrivnosti Kristusove),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 5, 'ki se v drugih rodovih ni naznanila sinovom človeškim, kakor se je zdaj razodela svetim apostolom njegovim in prorokom po Duhu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 6, 'namreč, da so pogani sodediči in soudje telesa in sodeležniki obljube v Kristusu Jezusu po evangeliju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 7, 'katerega služabnik sem postal po daru milosti Božje, podeljene mi po delovanju moči njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 8, 'Meni najmanjšemu izmed vseh svetih je dana milost ta, oznanjati poganom nezasledljivo bogastvo Kristusovo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 9, 'in razsvetliti vse, kakšno je oskrbovanje skrivnosti, od vekomaj skrite v Bogu, ki je vse ustvaril,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 10, 'zato da se naznani zdaj poglavarstvom in oblastim v nebesih po cerkvi mnogotera modrost Božja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 11, 'po sklepu od vekomaj, ki ga je storil v Kristusu Jezusu, Gospodu našem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 12, 'v katerem imamo srčnost in pristop v zaupanju po veri v njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 13, 'Zato prosim, da ne opešate v stiskah mojih za vas, kar je vaša čast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 14, 'Zategadelj pripogibljem kolena pred Očetom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 15, 'po katerem se imenuje sleherna rodovina v nebesih in na zemlji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 16, 'da vam dá po bogastvu slave svoje, da se okrepčate v moči po Duhu njegovem v notranjem človeku,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 17, 'da se Kristus po veri vseli v srca vaša, ko ste ukoreninjeni in utrjeni v ljubezni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 18, 'da morete razumeti z vsemi svetimi, kaj je širjava in dolžina ter globočina in visočina,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 19, 'in spoznati ljubezen Kristusovo, ki presega spoznanje, da se napolnite do vse polnosti Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 20, 'Njemu pa, ki more nad vso mero storiti, preobilo več nego kar prosimo ali umemo, po moči, ki deluje v nas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 3, 21, 'njemu slava v cerkvi in v Kristusu Jezusu na vse rodove na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 1, 'Prosim vas torej jaz, jetnik v Gospodu, da živite dostojno poklicu, ki ste ž njim bili poklicani,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 2, 'z vso ponižnostjo in krotkostjo, s potrpežljivostjo, prenašajoč se med seboj v ljubezni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 3, 'skrbno si prizadevajoč, ohraniti edinost Duha v vezi miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 4, 'Eno je telo in en Duh, kakor ste tudi bili poklicani v enem upanju poklica svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 5, 'en Gospod, ena vera, en krst;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 6, 'en Bog in Oče vseh, ki je nad vsemi in po vseh in v vseh nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 7, 'Vsakemu pa izmed nas je dana milost po meri daru Kristusovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 8, 'Zato pravi: „Šel je v višavo, ujete pripeljal jetnike, dal je dari ljudem“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 9, 'Tisto pa: Šel je v višavo, kaj je drugega, nego da je tudi šel prej doli v spodnje kraje zemlje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 10, 'On, ki je šel doli, je tisti, ki je šel tudi gori nad vsa nebesa, da bi vse napolnil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 11, 'In on je dal nekatere za apostole, nekatere za proroke, nekatere za evangeliste, nekatere za pastirje in učenike,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 12, 'v pripravo svetih, za delo službe, za zdelovanje telesa Kristusovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 13, 'dokler ne dospemo vsi do edinosti vere in spoznanja Sinu Božjega, do moža doraslega, do mere dovršene rasti polnosti Kristusove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 14, 'da ne bodemo več deca in nas ne bo semtertja metala in gonila vsaka sapa nauka, ki prihaja po zvijačnosti ljudi, po prekanjenosti za zvito zapeljevanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 15, 'temuč da rastemo, držeč se resnice v ljubezni, v vsem do njega, ki je glava, Kristus;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 16, 'iz katerega vse telo, združeno in zedinjeno po pripomoči slehernega člena, po delovanju v meri vsakega uda rast telesa vrši v napredek svoj, v ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 17, 'To torej pravim in pričam v Gospodu, da ne živite več tako, kakor žive tudi pogani v ničemurnosti srca svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 18, 'otemnjeni v razumu, odtujeni življenju Božjemu zaradi nevednosti, ki je v njih, vsled otrplosti njih srca,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 19, 'ki so se, ko so postali brezčutni, vdali razuzdanosti, da strežejo sleherni nečistosti z lakomnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 20, 'Vi pa se niste tako naučili Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 21, 'ako ste ga slišali in ste bili poučeni v njem, kakor je resnica v Jezusu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 22, 'da ste slekli z ozirom na prejšnje življenje starega človeka, ki gine po slah prevare,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 23, 'a da se obnavljate v duhu uma svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 24, 'in ste oblekli novega človeka, ustvarjenega po Bogu v pravičnosti in svetosti resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 25, 'Zato, iznebivši se laži, govorite resnico vsak z bližnjim svojim, ker smo udje med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 26, 'Jezite se, a ne grešite! Solnce naj ne zaide nad jezo vašo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 27, 'in ne dajte prostora hudiču.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 28, 'Kdor je kradel, ne kradi več, temuč trudi se, delajoč dobro z lastnimi rokami, da ima kaj podeliti potrebnemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 29, 'Nobena gnila beseda ne izidi iz vaših ust, ampak če je katera dobra za napredek, kjer je treba, da dá milost poslušalcem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 30, 'In ne žalite svetega Duha Božjega, ki ste ž njim zapečateni za odrešenja dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 31, 'Vsaka bridkost in srd in jeza in vpitje in preklinjanje izgini od vas z vso hudobnostjo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 4, 32, 'Bodite pa med seboj blagi, milosrčni, odpuščajte drug drugemu, kakor je tudi Bog v Kristusu vam odpustil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 1, 'Bodite torej posnemalci Boga, kakor otroci ljubljeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 2, 'in živite v ljubezni, kakor je tudi Kristus ljubil nas in je dal sebe za nas kot daritev in žrtev Bogu v prijetno dišavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 3, 'Nesramnost pa in sleherna nečistost ali lakomnost naj se še imenuje ne med vami, kakor se spodobi svetim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 4, 'tudi ne nečedno vedenje in nespametne besede ali norčevanje, kar je nespodobno, ampak rajši zahvaljevanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 5, 'To namreč veste, da noben nesramnik, ali nečistnik, ali lakomnik, ki je malikovalec, nima dediščine v kraljestvu Kristusovem in Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 6, 'Nihče vas ne varaj s praznimi besedami; kajti zavoljo teh pregreh prihaja jeza Božja na sinove nepokorščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 7, 'Ne bodite torej njih deležniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 8, 'Bili ste namreč nekdaj tema, zdaj pa ste svetloba v Gospodu: kakor svetlobe otroci živite');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 9, '(kajti sad svetlobe je v sleherni dobroti in pravičnosti in resnici),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 10, 'in presojajte, kaj je Gospodu po volji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 11, 'in ne udeležujte se nerodovitnih del teme, marveč še grajajte jih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 12, 'kar namreč počenjajo skrivaj, grdo je celo samo praviti to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 13, 'Vse to pa se razodene, ko to graja svetloba; kajti vse razodeto je svetloba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 14, 'Zato pravi: Zbudi se, ki spiš, in vstani izmed mrtvih, in prisveti ti Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 15, 'Glejte torej, da živite previdno, ne kakor nemodri, ampak kakor modri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 16, 'in skrbno rabite čas, ker dnevi so hudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 17, 'Zatorej ne bodite nespametni, marveč umejte, kaj je volja Gospodova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 18, 'In ne upijanjajte se z vinom, v čemer je razuzdanost, temuč napolnjujte se z Duhom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 19, 'govoreč med seboj v psalmih, slavospevih in pesmih duhovnih, pojoč in citrajoč s srcem svojim Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 20, 'zahvaljujoč se vedno za vse v imenu Gospoda našega Jezusa Kristusa Bogu in Očetu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 21, 'pokorni bodite drug drugemu v strahu Kristusovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 22, 'Žene, svojim možem bodite pokorne kakor Gospodu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 23, 'kajti mož je glava ženi, kakor tudi Kristus glava cerkvi; on je tudi rešitelj telesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 24, 'Ali kakor je cerkev pokorna Kristusu, tako bodite tudi žene svojim možem v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 25, 'Možje, ljubite žene svoje, kakor je tudi Kristus ljubil cerkev in je samega sebe dal zanjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 26, 'da jo posveti, očistivši jo v kopeli vode, z besedo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 27, 'da pripravi sam sebi slavno cerkev, ki nima madeža ali gube ali kaj enakega, ampak da bode sveta in brezmadežna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 28, 'Tako so možje dolžni ljubiti žene kakor telesa svoja. Kdor ljubi ženo svojo, ljubi sebe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 29, 'kajti nihče ni nikoli sovražil svojega mesa, temuč hrani in goji ga kakor tudi Kristus cerkev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 30, 'ker udje smo telesa njegovega [iz mesa njegovega in iz kosti njegovih].');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 31, '„Zato zapusti človek očeta svojega in mater svojo ter se pridruži ženi svoji, in oba bodeta eno meso“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 32, 'Ta skrivnost je velika: jaz pa pravim za Kristusa in za cerkev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 5, 33, 'Toda tudi vi, vsak posamezni naj ljubi ženo svojo tako kakor sebe; žena pa se boj moža.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 1, 'Otroci, bodite poslušni roditeljem svojim v Gospodu; zakaj to je pravično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 2, '„Spoštuj očeta svojega in mater svojo“, ta je zapoved prva z obljubo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 3, '„da se ti bo dobro godilo in boš dolgo živel na zemlji“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 4, 'In očetje, ne dražite svojih otrok, temuč vzrejajte jih v strahu in svarjenju Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 5, 'Hlapci, bodite poslušni telesnim gospodarjem svojim s strahom in trepetom, v preprostosti srca svojega kakor Kristusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 6, 'ne služite le na oko, kakor bi hoteli ugajati ljudem, temuč kakor hlapci Kristusovi, delajoč voljo Božjo iz duše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 7, 'z dobro voljo opravljajoč službo, kakor Gospodu in ne ljudem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 8, 'vedoč, da kar kdo stori dobrega, prejme to od Gospoda, bodisi hlapec, bodisi svobodnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 9, 'In gospodarji, ravnajte istotako ž njimi in opuščajte pretenje, vedoč, da je i njih i vaš Gospod v nebesih in da licegledja ni pri njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 10, 'Sicer pa, ojačite se v Gospodu in v krepkosti moči njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 11, 'Odenite se z vsem orožjem Božjim, da boste mogli stati zoper zvijačne naklepe hudičeve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 12, 'Kajti vojskovati se nam ni zoper kri in meso, ampak zoper poglavarstva, zoper oblasti, zoper svetovne mogočnike te teme, zoper duhovne vojske hudobnosti v nebeških prostorih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 13, 'Zato primite za vse orožje Božje, da se morete v bran postaviti ob hudem dnevi in, vse premagavši, stati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 14, 'Stojte torej, opasani okoli ledij z resnico in oblečeni z oklepom pravičnosti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 15, 'in obuti na nogah s pripravljenostjo, oznanjati evangelij miru,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 16, 'vrhutega zgrabite ščit vere, s katerim boste mogli pogasiti vse goreče strele Hudobnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 17, 'In vzemite čelado zveličanja in meč Duha, ki je beseda Božja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 18, 'in s sleherno molitvijo in prošnjo molite vsak čas v Duhu in bedite za to v vsej stanovitnosti in prošnji za vse svete,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 19, 'tudi zame, da se mi dá beseda, ko odprem usta, da s srčnostjo oznanjam skrivnost evangelija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 20, 'ki sem zanj poslanec v sponah, da v njem srčno govorim, kakor mi je govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 21, 'Da pa veste tudi vi, kar zadeva mene, kako se mi godi, naznani vam vse Tihik, ljubljeni brat in zvesti služabnik v Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 22, 'ki sem ga poslal k vam prav zato, da zveste, kako je z nami, in da potolaži srca vaša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 23, 'Mir bodi bratom in ljubezen z vero od Boga Očeta in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (49, 6, 24, 'Milost z vsemi, ki ljubijo Gospoda našega Jezusa Kristusa v neminljivosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 1, 'Pavel in Timotej, hlapca Kristusa Jezusa, vsem svetim v Kristusu Jezusu, ki bivajo v Filipih, s škofi in diakoni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 2, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 3, 'Zahvaljujem se Bogu svojemu, kadarkoli se vas spominjam,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 4, 'vedno v sleherni molitvi za vas vse, ko opravljam molitev z veseljem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 5, 'da ste se udeleževali širjenja evangelija od prvega do današnjega dne,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 6, 'ker sem prepričan prav o tem, da on, ki je začel v vas dobro delo, ga dokonča do dne Jezusa Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 7, 'kakor je tudi meni spodobno, misliti to za vas vse, ker vas imam v srcu svojem kot take, ki ste vsi i v sponah mojih i v zagovarjanju in utrjevanju evangelija sodeležniki milosti z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 8, 'Kajti priča mi je Bog, kako hrepenim po vas vseh v srčni ljubezni Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 9, 'In za to molim, da naj ljubezen vaša še bolj in bolj raste v spoznanju in slehernem razumu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 10, 'da presojate, kaj je boljše in kaj ne; da bodete čisti in brez spotikljaja za dan Kristusov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 11, 'napolnjeni s sadom pravičnosti, ki se množi po Jezusu Kristusu, v slavo in hvalo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 12, 'Želim pa, da spoznate, bratje, da je pripomoglo še bolj v prospeh evangeliju to, kar me je zadelo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 13, 'tako da so spone moje postale očitne, da so za Kristusa, vsej cesarski straži in vsem drugim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 14, 'in da si večina bratov, v Gospodu dobivši zaupanje po mojih sponah, upa bolj brez strahu govoriti besedo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 15, 'Nekateri sicer oznanjajo Kristusa tudi iz zavisti in prepirljivosti, nekateri pa tudi iz dobre volje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 16, 'Ti, ki to delajo iz ljubezni, vedo, da sem postavljen v zagovarjanje evangelija;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 17, 'drugi pa oznanjajo Kristusa iz strankarstva, ne iz čistega namena, ker menijo, da mi povzročijo stisko v sponah mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 18, 'Ali kaj na tem? Saj se tako ali tako, bodisi s pretvezo, bodisi v resnici oznanja Kristus, in tega se veselim, da, bom se še veselil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 19, 'Vem namreč, da mi to posluži v rešitev po prošnji vaši in podpori Duha Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 20, 'po trdnem pričakovanju in upanju mojem, da ne bom v ničemer osramočen, marveč da se bo v vsej srčnosti pričevanja kakor vedno, tudi sedaj poveličeval Kristus v mojem telesu, bodisi z življenjem ali s smrtjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 21, 'Zakaj meni je življenje Kristus, in smrt dobiček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 22, 'Ako pa mi je še živeti v mesu, to mi pomnoži sad dela; in kaj naj izvolim, ne vem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 23, 'Pritiska me pa oboje: želja me je, ločiti se in biti s Kristusom, zakaj to je veliko, veliko boljše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 24, 'toda ostati v mesu je potrebnejše za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 25, 'In v tem zaupanju vem, da ostanem in z vami vsemi ostanem za vaš prospeh in veselje v veri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 26, 'da bode hvala vaša preobila v Kristusu Jezusu zaradi mene, vsled zopetnega prihoda mojega k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 27, 'Samo naj bode življenje vaše, kakor se spodobi evangeliju Kristusovemu, da bom vedel, bodisi da pridem in vas vidim, bodisi da v daljavi slišim, kako je pri vas, da stojite trdno v enem duhu, enodušno in skupno se boreč za vero evangelija,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 28, 'in da vas nikakor ne morejo zastrašiti nasprotniki; kar je njim očitno znamenje pogube, vam pa zveličanja, in to od Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 29, 'ker vam je iz milosti dano za Kristusa, da ne samo verujete vanj, ampak tudi zanj trpite,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 1, 30, 'imajoč isti boj, ki ste ga videli na meni in zdaj slišite o meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 1, 'Če je torej pri vas kako izpodbujanje v Kristusu, če je kaka tolažba ljubezni, če kaka sodeležnost Duha, če kako usmiljenje in milovanje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 2, 'napolnite mi veselje s tem, da ste složni, da imate eno ljubezen, enodušno ravnate, za eno skrbite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 3, 'ničesar ne delajte iz sebičnosti ali praznega slavoljubja, temuč po ponižnosti cenite drug drugega više od sebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 4, 'Ne glejte vsak na svoje, ampak vsak tudi na to, kar je drugega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 5, 'To mišljenje bodi v vas, ki je bilo v Kristusu Jezusu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 6, 'kateri, ko je bil v podobi Božji, ni štel za rop biti enak Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 7, 'temuč samega sebe je izpraznil in je nase vzel podobo hlapca in postal enak človeku; in po zunanjosti spoznan za človeka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 8, 'se je ponižal in je bil pokoren do smrti, smrti pa na križu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 9, 'Zato ga je tudi Bog visoko povišal in mu podelil ime, ki je nad vsako ime;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 10, 'da se naj v imenu Jezusa pripogiblje vsako koleno teh, ki so v nebesih in na zemlji in pod zemljo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 11, 'in vsak jezik pripoznava, da Jezus Kristus je Gospod, v slavo Boga Očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 12, 'Zatorej, ljubljeni moji, kakor ste bili vsekdar poslušni, ne samo v pričujočnosti moji, temuč mnogo bolj sedaj v nepričujočnosti moji, v strahu in trepetu vršite zveličanje svoje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 13, 'Bog namreč je, ki dela v vas i voljo i delovanje, po svoji dobri volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 14, 'Vse delajte brez godrnjanja in pomišljanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 15, 'da bodete brez pogreška in čisti, otroci Božji brez madeža sredi sključenega in spačenega rodú, med katerimi se svetite kakor nebeške luči na svetu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 16, 'in jim predstavljate besedo življenja; da imam hvalo za dan Kristusov, da nisem zastonj tekal in ne trudil se zastonj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 17, 'Ali ko bi bil tudi darovan nad daritvijo in službo vere vaše, veselim se in z vami vsemi vred se veselim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 18, 'Enako pa se veselite tudi vi in veselite se z menoj vred!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 19, 'Upam pa v Gospoda Jezusa, da vam skoraj pošljem Timoteja, da bodem tudi jaz mirnega srca, ko zvem, kako je pri vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 20, 'Nikogar namreč nimam enakega mišljenja, ki bo pošteno skrbel za vaše zadeve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 21, 'zakaj vsi iščejo svojega, ne kar je Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 22, 'Preizkušenost pa poznate njegovo, da je, kakor otrok z očetom, z menoj služil za širjenje evangelija.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 23, 'Tega torej upam poslati, precej ko izprevidim, kako bo z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 24, 'Trdno se pa nadejam v Gospodu, da tudi sam pridem skoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 25, 'Potrebno se mi je pa zdelo poslati k vam Epafrodita, brata in sodelavca in sovojaka mojega, vašega pa poslanca in služabnika potrebe moje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 26, 'kajti hrepenel je po vas vseh in se žalostil, ker ste slišali, da je zbolel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 27, 'In res, da je zbolel in je bil blizu smrti; ali Bog se ga je usmilil, a ne samo njega, ampak tudi mene, da ne bi imel žalosti nad žalost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 28, 'Tem hitreje torej sem ga poslal, da ga vidite ter se veselite in da bodem jaz manj žalosten.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 29, 'Sprejmite ga torej v Gospodu z vsem veseljem, in take imejte v čislih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 2, 30, 'kajti zaradi dela Kristusovega se je bil približal smrti, vnemar pustivši življenje, da bi nadomestil, s čimer mi vi niste mogli poslužiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 1, 'Sicer pa, bratje moji, veselite se v Gospodu! Eno in isto vam pisati ni sitno meni, vam pa je v potrjenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 2, 'Pazite se psov, pazite se slabih delavcev, pazite se razreze!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 3, 'Kajti mi smo obreza, ki v Božjem Duhu služimo Bogu in se hvalimo v Kristusu Jezusu in ne stavimo upanja v meso,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 4, 'dasi imam jaz lahko tudi v meso zaupanje. Če meni kdo drugi zaupati v meso, jaz tem bolj:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 5, 'obrezan osmi dan, iz rodu Izraelovega, rodovine Benjaminove, Hebrejec iz Hebrejcev, po postavi farizej,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 6, 'po gorečnosti preganjalec cerkve, po pravičnosti, ki sloni na postavi, brez pogreška.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 7, 'Ali kar mi je bilo dobiček, to sem imel zaradi Kristusa za izgubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 8, 'Ali zares, tudi zdaj imam vse za izgubo, ker je mnogo boljše spoznanje Kristusa Jezusa, Gospoda mojega, zaradi katerega sem vse izgubil in imam to za smeti, da pridobim Kristusa');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 9, 'in se najdem v njem, ne imajoč svoje pravičnosti, ki izvira iz postave, ampak tiste, ki je po veri v Kristusa, iz Boga pravičnosti, na podlagi vere,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 10, 'da spoznam njega in moč vstajenja njegovega in sodeleštvo njegovega trpljenja, ko sem njegovi smrti podoben,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 11, 'da kako dospem do vstajenja izmed mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 12, 'Ne da sem že dosegel ali da sem že dovršen, a ženem se, da kako dosežem, za kar sem bil tudi dosežen od Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 13, 'Bratje, jaz ne mislim sam zase, da sem že dosegel; eno pa delam: pozabivši, kar je zadaj, a vzpenjajoč se po tem, kar je spredaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 14, 'hitim proti cilju za darilom nebeškega poklica Božjega v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 15, 'Kolikor nas je torej popolnih, bodimo teh misli; in če ste v čem drugih misli, tudi to vam razodene Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 16, 'Toda do česar smo dospeli, po tem stopajmo naprej!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 17, 'Posnemalci moji bodite, bratje, in glejte na one, ki tako žive, kakor imate nas za zgled.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 18, 'Zakaj veliko jih živi, ki sem jih vam mnogokrat imenoval, zdaj pa jih tudi jokajoč imenujem sovražnike križa Kristusovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 19, 'katerih konec poguba, katerih Bog trebuh in njih slava v njih sramoti, ki jim je zemeljsko v mislih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 20, 'Kajti naša domovna država je v nebesih, odkoder tudi pričakujemo Zveličarja, Gospoda Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 3, 21, 'ki preobrazi telo ponižanja našega, da bode podobno telesu slave njegove, po moči, s katero si more tudi vse podvreči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 1, 'Zatorej, bratje moji ljubljeni in zaželjeni, veselje in venec moj, tako stojte trdno v Gospodu, ljubljeni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 2, 'Evodijo opominjam in Sintiho opominjam, da bodita enih misli v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 3, 'In prosim tudi tebe, moj tovariš zvesti, pomagaj jima, ki sta se z menoj borili v evangeliju, tudi s Klementom in drugimi sodelavci mojimi, katerih imena so v knjigi življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 4, 'Veselite se vedno v Gospodu! še enkrat pravim: Veselite se!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 5, 'Krotkost vaša bodi znana vsem ljudem. Gospod je blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 6, 'Nič ne skrbite, temuč v vsem naj se Bogu naznanjajo želje vaše v molitvi in prošnji z zahvaljevanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 7, 'In mir Božji, ki presega ves razum, bo čuval in ohranil srca vaša in misli vaše v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 8, 'Sicer pa, bratje, kar je resnično, kar čestito, kar pravično, kar čisto, kar ljubeznivo, kar sloveče, če je kaka čednost in če kaka hvala, to premišljajte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 9, 'Kar ste se tudi naučili in prejeli in slišali in videli na meni, to delajte, in Bog miru bode z vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 10, 'Razveselil sem se pa silno v Gospodu, da je končno zopet ozelenela vaša skrb zame; na to ste sicer tudi mislili, a prilike niste imeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 11, 'Ne da bi dejal to zaradi pomanjkanja; jaz sem se namreč naučil, zadovoljen biti s tem, kar imam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 12, 'Znam se tudi ponižati, znam tudi v obilosti živeti; sleherne in vsake stvari sem vajen, sit biti in lačen, v obilosti živeti in v pomanjkanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 13, 'Vse morem v njem, ki me krepča, v Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 14, 'Vendar ste prav storili, da ste pokazali sočutje z mojo stisko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 15, 'Veste pa tudi sami, Filipljani, da se v začetku širjenja evangelija, ko sem odšel iz Macedonije, ni udeležila nobena cerkev z menoj na račun dajanja in prejemanja, razen vas samih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 16, 'saj tudi v Solun ste mi poslali enkrat in dvakrat za potrebo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 17, 'Ne da bi iskal daru, marveč sadu iščem, ki naj se množi vam na račun.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 18, 'Imam pa vsega dovolj in preobilo; napolnjen sem, dobivši od Epafrodita vaše dari, sladko dišavo, prijetno daritev, Bogu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 19, 'Bog moj pa napolni vsako potrebo vašo po bogastvu svojem v slavi v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 20, 'Bogu pa in Očetu našemu slava na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 21, 'Pozdravite vsakega svetega v Kristusu Jezusu. Pozdravljajo vas bratje, ki so z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 22, 'Pozdravljajo vas vsi sveti, posebno pa oni iz cesarjeve hiše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (50, 4, 23, 'Milost Gospoda Jezusa Kristusa z duhom vašim!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 1, 'Pavel, apostol Kristusa Jezusa po volji Božji, in Timotej, brat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 2, 'svetim v Kolosah in vernim bratom v Kristusu: Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 3, 'Zahvaljujemo Boga, Očeta Gospoda našega Jezusa Kristusa, in molimo vedno za vas, ker smo slišali za vero vašo v Kristusu Jezusu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 4, 'in za ljubezen, ki jo imate do vseh svetih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 5, 'zaradi upanja, ki se vam hrani v nebesih in ki ste o njem prej slišali v besedi resnice evangelija;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 6, 'ta je prišel k vam, kakor je tudi po vsem svetu razširjen in rodi sad in raste, kakor tudi med vami, od dne, ko ste čuli in spoznali milost Božjo v resnici;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 7, 'kakor ste se jo naučili znati od Epafra, ljubljenega sohlapca našega, ki je zvest služabnik Kristusov za vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 8, 'ki nam je tudi naznanil ljubezen vašo v Duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 9, 'Zato molimo tudi mi od dne, ko smo to slišali, neprestano za vas in prosimo, da se napolnite s spoznanjem volje njegove v vsej modrosti in razumnosti duhovni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 10, 'da živite dostojno Gospoda, v vsem njemu po volji, in rodite sad v vsakem dobrem delu ter rastete po spoznanju Božjem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 11, 'z vso močjo krepčani po krepkosti slave njegove za vso stanovitnost in potrpežljivost, z radostjo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 12, 'zahvaljujoč Očeta, ki nas je storil sposobne za delež dediščine svetih v luči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 13, 'ki nas je rešil iz teme oblasti in prestavil v kraljestvo Sina ljubezni svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 14, 'v katerem imamo odrešenje, odpuščenje grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 15, 'On je podoba Boga nevidnega, prvorojenec vse stvaritve,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 16, 'ker v njem je bilo ustvarjeno vse, v nebesih in na zemlji, vidno in nevidno, ali prestoli, ali gospostva, ali poglavarstva, ali oblastva: vse je ustvarjeno po njem in zanj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 17, 'in on je pred vsem in vse ima obstanek v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 18, 'In on je glava telesa, cerkve; on, ki je začetek, prvorojenec izmed mrtvih, da bi bil on v vsem prvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 19, 'Kajti vzvidelo se je Očetu, da v njem prebiva vsa polnost');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 20, 'in da po njem spravi vse s seboj, storivši mir po krvi križa njegovega, po njem, bodisi kar je na zemlji, bodisi kar je v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 21, 'Tudi vas, ki ste bili nekdaj odtujeni in sovražni v mišljenju pri svojih delih hudobnih, – zdaj pa vas je spravil');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 22, 'v telesu mesa njegovega, po njegovi smrti, da vas postavi svete in brezmadežne in brez graje pred seboj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 23, 'ako le vztrajate v veri, utrjeni in stanovitni, in se ne ganete od upanja evangelija, ki ste ga slišali, oznanjevanega vsemu stvarjenju pod nebom; tega evangelija sem jaz Pavel postal služabnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 24, 'Sedaj se veselim v trpljenju svojem za vas in dopolnjujem, kar zaostaja od stisk Kristusovih, na mesu svojem za telo njegovo, ki je cerkev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 25, 'katere sem jaz postal služabnik po oskrbništvu Božjem, ki mi je dano za vas, da izpolnim besedo Božjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 26, 'skrivnost, ki je bila skrita od vekov in od rodov, zdaj pa je bila razodeta svetim njegovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 27, 'ki jim je Bog hotel naznaniti, kakšno je bogastvo slave te skrivnosti med pogani, ki je Kristus v vas, upanje slave;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 28, 'njega mi oznanjamo, opominjajoč vsakega človeka in učeč vsakega človeka v vsej modrosti, da napravimo vsakega človeka popolnega v Kristusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 1, 29, 'za to se tudi trudim, boreč se po krepkosti njegovi, ki deluje v meni z močjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 1, 'Hočem namreč, da veste, kako hud boj imam za vas in zanje, ki so v Laodiceji, in za vse, ki niso videli obličja mojega v mesu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 2, 'da prejmejo njih srca tolažbo, da so združeni v ljubezni in za vse bogastvo popolnega prepričanja razuma, da prav spoznajo skrivnost Božjo, Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 3, 'v katerem so skriti vsi zakladi modrosti in spoznanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 4, 'To pa pravim, da vas nihče ne prevara z dozdevno pametnimi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 5, 'Kajti čeprav sem po mesu daleč, v duhu sem vendar z vami, radujoč se in gledajoč vašo rednost in trdnost vere vaše v Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 6, 'Kakor ste torej sprejeli Kristusa Jezusa, Gospoda, tako živite v njem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 7, 'ukoreninjeni in sezidani v njem in utrjeni v veri, kakor ste bili poučeni, in bodite po njej obilni v zahvaljevanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 8, 'Pazite, da vas kdo ne upleni z modrijanstvom in prazno prevaro, po izročilu človeškem, po začetnih naukih sveta in ne po Kristusu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 9, 'ker v njem prebiva vsa polnost božanstva telesno');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 10, 'in v njem ste dopolnjeni, ki je glava vsakega gospodstva in vsake oblasti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 11, 'ki ste bili v njem tudi obrezani z obrezo, ne storjeno z rokami, ko ste slekli telo mesa, z obrezo Kristusovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 12, 'pokopani ž njim vred v krstu, v katerem ste tudi vstali ž njim od smrti po veri v delovanje Boga, ki ga je obudil izmed mrtvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 13, 'In vas, ki ste bili mrtvi v grehih in neobrezi mesa svojega, tudi vas je oživil ž njim vred, ko nam je odpustil vse grehe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 14, 'in izbrisal rokopis zoper nas, ki nam je bil po poveljih nasproten, in ga je odpravil, pribivši ga z žeblji na križ,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 15, 'in je razorožil poglavarstva in oblasti in jih postavil očitno na ogled in slavil zmago nad njimi v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 16, 'Naj vas torej ne sodi kdo v jedi ali pijači, ali glede praznika ali mlaja ali sobote;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 17, 'to vse je senca prihodnjih reči, telo pa je Kristusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 18, 'Nihče naj vas ne pripravi ob zmagovalcev plačilo s tem, da svoji volji ugaja v ponižnosti in češčenju angelov, ko se peča s tem, česar ni videl, ker ga za nič napihuje mišljenje mesa njegovega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 19, 'in ker se ne drži Glave, iz katere raste vse telo, po členovju in vezeh podpirano in zvezano, v rasti Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 20, 'Če ste torej umrli s Kristusom začetnim naukom sveta, zakaj se, kakor da bi še v svetu živeli, pokorite poveljem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 21, '„Ne dotakni se, in ne pokusi, in ne potipaj!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 22, '(kar je vse v pogubo določeno po rabi) po zapovedih in naukih človeških?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 2, 23, 'To ima sicer videz modrosti v svojevoljni službi Božji in ponižnosti in neprizanesljivosti proti telesu, a nima nič vrednosti in služi le v zadovoljitev mesa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 1, 'Če ste torej bili obujeni s Kristusom vred, iščite, kar je gori, kjer je Kristus, sedeč na desnici Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 2, 'V mislih imejte, kar je gori, ne, kar je na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 3, 'Kajti umrli ste, in življenje vaše je skrito s Kristusom v Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 4, 'Kadar se prikaže Kristus, ki je življenje naše, tedaj se prikažete tudi vi ž njim v slavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 5, 'Morite torej ude svoje, ki so na zemlji: nesramnost, nečistost, strast, hudo poželenje in lakomnost, ki je malikovanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 6, 'zavoljo katerih grehov prihaja jeza Božja nad sinove nepokorščine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 7, 'ki ste med njimi tudi vi hodili nekdaj, ko ste živeli v teh grehih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 8, 'Sedaj pa odložite tudi vi vse to: jezo, srd, hudobnost, preklinjanje, nečedno besedovanje iz svojih ust;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 9, 'ne lažite drug drugemu; ker ste slekli starega človeka z dejanji njegovimi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 10, 'in oblekli novega, ki se obnavlja v spoznanje po podobi njega, ki ga je ustvaril;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 11, 'kjer ni Grka in Juda, obreze in neobreze, tujca, Scita, hlapca, svobodnega, marveč vse in v vseh Kristus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 12, 'Oblecite torej kot izvoljeni Božji, sveti in ljubljeni, srčno usmiljenje, blagovoljnost, ponižnost, krotkost, potrpežljivost;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 13, 'prenašajte drug drugega in si odpuščajte, če ima kdo tožbo zoper koga, kakor je tudi Kristus odpustil vam, tako tudi vi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 14, 'vrhu vsega tega pa oblecite ljubezen, ki je popolnosti vez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 15, 'In mir Kristusov naj vlada v srcih vaših, ki ste bili vanj tudi poklicani v enem telesu; in hvaležni bodite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 16, 'Beseda Kristusova prebivaj v vas obilno z vso modrostjo; učite in opominjajte se med seboj s psalmi in hvalospevi in pesmami duhovnimi, v milosti pojoč v srcu svojem Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 17, 'In vse, kar počenjate v besedi in dejanju, vse delajte v imenu Gospoda Jezusa, zahvaljujoč Boga Očeta po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 18, 'Žene, bodite pokorne svojim možem, kakor se spodobi, v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 19, 'Možje, ljubite žene svoje in ne bodite osorni proti njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 20, 'Otroci, bodite poslušni roditeljem v vsem, kajti to je ugodljivo v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 21, 'Očetje, ne dražite otrok svojih, da ne bodo malosrčni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 22, 'Hlapci, bodite poslušni v vsem gospodarjem po mesu, ne služite le na oko, kakor ljudem ugajajoč, temuč v preprostosti srca, boječ se Gospoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 23, 'Vse, kar storite, delajte iz duše, kakor Gospodu in ne ljudem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 24, 'vedoč, da od Gospoda prejmete povračilo dediščine; Gospodu Kristusu hlapčujete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 3, 25, 'Krivičnik pa prejme, kar je krivičnega storil; in ni ga licegledja pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 1, 'Gospodarji, pravičnost in blagodušnost izkazujte hlapcem, vedoč, da imate tudi vi Gospodarja v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 2, 'V molitvi bodite stanovitni in čujte v njej z zahvaljevanjem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 3, 'molite obenem tudi za nas, da nam Bog odpre vrata za besedo, da govorimo skrivnost Kristusovo, za katero sem tudi v sponah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 4, 'da jo razodevam, kakor sem dolžan govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 5, 'V modrosti živite ž njimi, ki so zunaj, in skrbno rabite čas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 6, 'Beseda vaša bodi vedno v milosti, s soljo zabeljena, da veste, kako vam je vsakemu odgovarjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 7, 'Kako je pri meni, vam naznani vse Tihik, ljubljeni brat in zvesti služabnik in sohlapec v Gospodu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 8, 'ki ga prav zato pošiljam k vam, da zveste, kako je pri nas, in da izpodbudi srca vaša,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 9, 'z Onezimom, zvestim in ljubljenim bratom, ki je izmed vas: ta vam naznanita vse, kako je tukaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 10, 'Pozdravlja vas Aristarh, sojetnik moj, in Marko, nečak Barnabov (zastran katerega ste dobili ukaze; če pride k vam, sprejmite ga),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 11, 'in Jezus, imenovan Just, ki sta, iz obreze ta dva sama, sodelavca za kraljestvo Božje, ki sta mi bila v tolažbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 12, 'Pozdravlja vas Epafra, ki je od vas, hlapec Kristusa Jezusa, ki se vedno za vas bori v molitvah, da stojite popolni in trdno prepričani v vsej volji Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 13, 'Pričam mu namreč, da ima mnogo truda za vas in zanje, ki so v Laodiceji, in zanje, ki so v Hierapolu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 14, 'Pozdravlja vas Lukež, zdravnik ljubljeni, in Dema.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 15, 'Pozdravite brate v Laodiceji, in Nimfa in cerkev, ki se shaja v njih hiši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 16, 'In ko pri vas ta list preberete, dejte, da se bo bral tudi v cerkvi laodicejski, in list iz Laodiceje da boste tudi vi brali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 17, 'In recite Arhipu: Glej na službo, ki si jo prejel v Gospodu, da jo izpolnjuješ.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (51, 4, 18, 'Pozdrav z roko mojo, Pavlovo. Spominjajte se vezi mojih! Milost z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 1, 'Pavel in Silvan in Timotej cerkvi Solunčanov v Bogu Očetu in Gospodu, Jezusu Kristusu: Milost vam in mir!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 2, 'Zahvaljujemo Boga vedno za vas vse, ko vas omenjamo v molitvah svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 3, 'neprestano spominjajoč se dela vašega v veri in truda v ljubezni in stanovitnosti v upanju v Gospoda našega Jezusa Kristusa pred Bogom in Očetom našim;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 4, 'ker vemo, bratje, ljubljeni od Boga, za izvoljenje vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 5, 'da evangelij naš ni prišel samo v besedi do vas, ampak tudi v moči in v svetem Duhu in v mnogem prepričanju; kakor veste, kakšni smo se med vami izkazali zaradi vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 6, 'In vi ste postali posnemalci naši in Gospodovi, sprejemši besedo v mnogi stiski z veseljem svetega Duha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 7, 'tako da ste postali zgled vsem, ki verujejo v Macedoniji in Ahaji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 8, 'Zakaj od vas je zadonela beseda Gospodova ne samo po Macedoniji in Ahaji, temuč se je v vsakem kraju razglasila vera vaša v Boga, tako da nam ni treba kaj govoriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 9, 'Sami namreč oznanjajo o nas, kakšen smo imeli prihod k vam in kako ste se obrnili k Bogu od malikov, služit Bogu živemu in pravemu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 1, 10, 'in čakat Sina njegovega iz nebes, ki ga je obudil izmed mrtvih, Jezusa, ki nas rešuje prihodnje jeze.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 1, 'Saj sami veste, bratje, za naš prihod k vam, da ni bil prazen:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 2, 'temuč, dasi smo trpeli prej in smo bili zasramovani, kakor veste, v Filipih, osrčili smo se v Bogu našem, da govorimo k vam evangelij Božji v mnogem boju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 3, 'Kajti opominjanje naše ni iz zmotnjave, ne iz nečistosti, ne v zvijači,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 4, 'temuč kakor nas je Bog za vredne spoznal izročiti nam evangelij, tako govorimo; ne da bi bili ljudem po volji, ampak Bogu, ki presoja srca naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 5, 'Kajti s prilizljivo besedo nismo nastopili nikdar, kakor veste, niti s kako pretvezo za lakomnost, Bog je priča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 6, 'tudi nismo iskali slave od ljudi, ne od vas, ne od drugih, dasi bi bili lahko imenitni kakor apostoli Kristusovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 7, 'Ampak bili smo krotki sredi vas, kakor pač dojka goji otroke svoje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 8, 'prav tako, milo hrepeneč po vas, nas je bila volja, ne samo podati vam evangelij Božji, ampak tudi duše svoje, ker smo si vas jako priljubili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 9, 'Saj se spominjate, bratje, truda našega in težave: ker noč in dan smo delali, da bi ne bili nadležni komu izmed vas, ko smo vam oznanjali evangelij Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 10, 'Vi ste priče, pa tudi Bog, kako sveto in pravično in brez graje smo se vedli do vas, ki verujete;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 11, 'da smo, kakor veste, slehernega izmed vas kakor oče otroke svoje opominjali, izpodbujali in rotili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 12, 'da živite dostojno Boga, ki vas kliče v svoje kraljestvo in slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 13, 'Zato tudi mi zahvaljujemo Boga neprestano, da ste, prejemši od nas besedo oznanila Božjega, jo sprejeli ne kot besedo človeško, ampak, kakor je resnično, kot besedo Božjo, ki tudi deluje v vas verujočih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 14, 'Zakaj vi ste postali, bratje, posnemalci cerkva Božjih, ki so v Judeji v Kristusu Jezusu, ker ste tudi vi isto trpeli od lastnih rojakov, kakor tudi oni od Judov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 15, 'ti so i Gospoda Jezusa umorili i proroke in nas pregnali, in Bogu niso prijetni in vsem ljudem so zoprni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 16, 'nam branijo govoriti poganom, da bi se zveličali, da tako vsekdar napolnijo mero grehov svojih. Prišla pa je nadnje jeza Božja do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 17, 'Mi pa, bratje, osiroteli za vami za nekaj časa, po obličju, ne po srcu, smo si tolikanj bolj prizadevali videti obličje vaše z mnogim hrepenenjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 18, 'Zato smo hoteli priti k vam, jaz Pavel enkrat, dvakrat, a branil nam je satan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 19, 'Kajti kdo je naše upanje, ali veselje, ali slave venec? Ali ne tudi vi pred Gospodom našim Jezusom Kristusom o prihodu njegovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 2, 20, 'Vi ste zares slava naša in veselje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 1, 'Zato, ko nismo mogli več strpeti, smo sklenili rajši sami ostati v Atenah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 2, 'in smo poslali Timoteja, brata našega in služabnika Božjega v evangeliju Kristusovem, utrjevat vas in opominjat zaradi vere vaše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 3, 'da se nihče ne da zbegati v teh stiskah; sami namreč veste, da smo namenjeni za to.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 4, 'Saj smo tudi, ko smo bili pri vas, naprej vam povedali, da pridemo v stiske, kakor se je tudi zgodilo in veste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 5, 'Zato sem tudi jaz, ker nisem mogel več strpeti, poslal pozvedovat za vero vašo, ni li vas morda izkušal izkušnjavec, in bi bil tako zaman naš trud.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 6, 'Ko je pa ravnokar Timotej k nam prišel od vas in nam prinesel blago vest o veri in ljubezni vaši in da nas imate vedno v dobrem spominu, hrepeneč videti nas, kakor tudi mi vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 7, 'zato smo bili, bratje, za vas potolaženi ob vsej stiski in sili svoji po veri vaši:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 8, 'ker zdaj živimo, če vi stojite trdno v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 9, 'Kajti kako zahvalo moremo Bogu vrniti za vas, za vse veselje, s katerim se radujemo zaradi vas pred Bogom svojim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 10, 'noč in dan presilno proseč, da bi videli obličje vaše in dopolnili pogreške vere vaše?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 11, 'On pa, Bog in Oče naš, in Gospod naš Jezus naj vodi pot našo k vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 12, 'Vas pa naj Gospod napolni in obogati z ljubeznijo drug do drugega in do vseh, kakor smo tudi mi do vas;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 3, 13, 'da utrdi srca vaša, da so brez graje v svetosti pred Bogom in Očetom našim o prihodu Gospoda našega Jezusa z vsemi njegovimi svetimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 1, 'Sicer pa, bratje, vas prosimo in opominjamo v Gospodu Jezusu: kakor ste prejeli od nas, kako vam je živeti in Bogu ugajati, kakor tudi že živite, da v tem čimdalje bolj rastete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 2, 'Saj veste, kake zapovedi smo vam dali po Gospodu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 3, 'To namreč je volja Božja, posvečenje vaše, da se zdržujete nečistosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 4, 'da ve vsak izmed vas posodo svojo pridobiti si v posvečenju in časti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 5, 'ne v strasti poželenja kakor pogani, ki ne poznajo Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 6, 'in da nihče ne prestopa pravic brata svojega in ga ne prekanja v opravilu, ker Gospod je maščevalec vsega tega, kakor smo vam tudi naprej povedali in pričali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 7, 'Kajti Bog nas ni poklical k nečistosti, ampak v posvečenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 8, 'Zatorej, kdor to zameta, ne zameta človeka, marveč Boga, ki je tudi dal svetega Duha svojega v vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 9, 'O bratoljubju pa ni treba, da vam pišemo; zakaj sami ste od Boga poučeni, da se ljubite med seboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 10, 'saj tudi ravnate tako z vsemi brati po vsej Macedoniji. Opominjamo pa vas, bratje, da v tem vedno bolj rastete');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 11, 'in da si prizadevate mirno živeti in da opravljate svoje in delate s svojimi rokami, kakor smo vam zapovedali;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 12, 'da živite spodobno pred njimi, ki so zunaj, in ne potrebujete nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 13, 'Nočemo pa, da bi ne vedeli, bratje, za pokojne, da se ne žalostite kakor tudi drugi, ki nimajo upanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 14, 'Kajti če verujemo, da je Jezus umrl in vstal, tako bo Bog tudi tiste, ki so zaspali po Jezusu, pripeljal ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 15, 'To namreč vam pravimo po besedi Gospodovi, da mi živeči, ki preostanemo za prihod Gospodov, nikakor ne prehitimo teh, ki so zaspali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 16, 'Kajti Gospod sam stopi doli iz nebes s poveljem, z glasom nadangela in s trobento Božjo, in mrtvi v Kristusu vstanejo najprej;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 17, 'potem bomo mi živeči, ki preostanemo, ž njimi vred vzeti v oblakih Gospodu naproti v zrak; in tako bodemo vedno z Gospodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 4, 18, 'Zato se tolažite med seboj s temi besedami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 1, 'O časih pa in urah, bratje, ni treba, da se vam piše;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 2, 'zakaj sami veste natanko, da pride dan Gospodov tako kakor tat po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 3, 'Ko pravijo: Mir in varnost, tedaj jih mahoma doleti poguba, kakor porodne bolečine nosečo; in ušli ne bodo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 4, 'Vi pa, bratje, niste v temi, da vas ta dan zagrabi kakor tat;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 5, 'kajti vi vsi ste luči sinovi in sinovi dneva; nismo od noči, ne od teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 6, 'Zatorej ne spimo kakor drugi, marveč čujmo in trezni bodimo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 7, 'Zakaj speči spe po noči in tisti, ki se upijanjajo, se upijanjajo po noči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 8, 'Mi pa, ker smo od dneva, bodimo trezni, oblečeni z oklepom vere in ljubezni ter za čelado imajoč upanje zveličanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 9, 'Kajti Bog nas ni odločil za jezo, ampak da dosežemo zveličanje po Gospodu našem Jezusu Kristusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 10, 'ki je umrl za nas, da ž njim vred živimo, naj čujemo ali spimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 11, 'Zato se opominjajte med seboj in služite drug drugemu v napredek, kakor tudi delate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 12, 'Prosimo pa vas, bratje, pripoznajte nje, ki se trudijo med vami in so vam predpostavljeni v Gospodu in vas svare,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 13, 'in jih visoko čislajte v ljubezni zavoljo njih dela. Živite v miru med seboj!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 14, 'Opominjamo pa vas, bratje, svarite neredne, prigovarjajte malodušnim, podpirajte slabotne, potrpežljivi bodite z vsemi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 15, 'Glejte, da ne vrne kdo komu hudega za hudo, temuč vedno hodite za dobrim med seboj in do vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 16, 'Vselej se veselite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 17, 'neprestano molite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 18, 'hvaležni bodite v vsem: kajti to je volja Božja v Kristusu Jezusu za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 19, 'Duha ne gasite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 20, 'prorokovanj ne zaničujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 21, 'Vse pa izkusite; kar je dobrega, ohranite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 22, 'Vsakršnega hudega se zdržujte.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 23, 'On pa, Bog miru, naj vas posveti popolnoma, in popoln naj se vam ohrani duh in duša in telo, da bo brez graje o prihodu Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 24, 'Zvest je, ki vas kliče, ki bo to tudi storil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 25, 'Bratje, molite za nas!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 26, 'Pozdravite vse brate v svetem poljubu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 27, 'Rotim vas pri Gospodu, da se naj ta list bere vsem svetim bratom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (52, 5, 28, 'Milost Gospoda našega Jezusa Kristusa z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 1, 'Pavel in Silvan in Timotej cerkvi Solunčanov v Bogu Očetu našem in Gospodu Jezusu Kristusu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 2, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 3, 'Zahvaljevati Boga smo dolžni vedno za vas, bratje, kakor je spodobno, ker močno raste vera vaša in se množi ljubezen vsakega izmed vas do vseh med seboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 4, 'tako da se mi sami hvalimo z vami po cerkvah Božjih zaradi stanovitnosti vaše in vere v vseh preganjanjih vaših in stiskah, ki jih prenašate;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 5, 'to je očitno znamenje pravične sodbe Božje, da bi bili za vredne spoznani kraljestva Božjega, ki zanje tudi trpite;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 6, 'ker je res pravično pri Bogu, da povrne stisko njim, ki vas stiskajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 7, 'in vam stiskanim počitek z nami, kadar se razodene Gospod Jezus z neba z angeli moči svoje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 8, 'v plamenečem ognju, ko bo kaznoval tiste, ki ne poznajo Boga in niso pokorni evangeliju Gospoda našega Jezusa:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 9, 'ki bodo trpeli kazen, večno pogubo izpred obličja Gospodovega in izpred slave moči njegove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 10, 'kadar pride, da se oslavi v svetih svojih in se pokaže čudovitega v vseh, ki so sprejeli vero (ker se je verovalo pričevanje naše pri vas), v tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 11, 'Za to tudi vedno molimo za vas, da vas spozna vredne poklica Bog naš in dovrši vsako blagougodje v dobroti in vsako delo vere z močjo svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 1, 12, 'da se oslavi ime Gospoda našega Jezusa v vas in vi v njem, po milosti Boga našega in Gospoda Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 1, 'Prosimo pa vas, bratje, zaradi prihoda Gospoda našega Jezusa Kristusa in shoda našega ž njim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 2, 'da se ne daste hitro premekniti od zdravega uma in se ne ustrašite ne po duhu, ne po besedi, ne po listu, kakor da je od nas, da je že nastopil dan Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 3, 'Naj vas nikakor nihče ne preslepi: kajti tega dneva ne bo, če prej ne pride odpad in se ne razodene ‚človek greha‘, ‚pogube sin‘,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 4, 'ki se upira in povzdiguje zoper vse, kar se zove Bog ali kar se po božje časti, tako da samega sebe posadi v svetišče Božje in kaže sebe, da je Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 5, 'Ali se ne spominjate, da sem vam, ko sem bil še pri vas, rekel to?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 6, 'In sedaj veste, kaj ga zadržuje, da bi bil razodet ob svojem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 7, 'Kajti skrivnost krivice je že delavna; treba samo, da bo odpravljen, ki ga zadržuje sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 8, 'In tedaj se razodene Krivičnik, ki ga Gospod Jezus uniči z dihom svojih ust in pokonča s prikaznijo prihoda svojega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 9, 'njega, ki pride po delovanju satanovem z vso močjo in z znamenji in čudeži lažnivimi');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 10, 'in s sleherno prevaro krivice za te, ki gredo v pogubo, zato ker niso sprejeli ljubezni resnice, da bi se rešili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 11, 'In zato jim pošilja Bog močno delovanje zmote, da verujejo laži;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 12, 'da bodo sojeni vsi, ki niso verovali resnici, ampak jim je ugajala krivica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 13, 'Mi pa smo dolžni zahvaljevati Boga vedno za vas, bratje ljubljeni od Gospoda, da vas je Bog izvolil od začetka za zveličanje v posvečenju Duha in v veri v resnico;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 14, 'za kar vas je poklical po evangeliju našem, da dosežete slavo Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 15, 'Zatorej stojte trdno, bratje, in hranite izročila, ki ste se jih naučili bodisi po besedi ali po listu našem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 16, 'Sam pa Gospod naš Jezus Kristus in Bog Oče naš, ki nas je ljubil in nam dal večno tolažbo in dobro upanje po milosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 2, 17, 'naj potolaži srca vaša in vas utrdi v slehernem dobrem delu in govoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 1, 'Sicer pa, bratje, molite za nas, da se širi beseda Gospodova in slavi, kakor tudi pri vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 2, 'in da se rešimo nespametnih in hudobnih ljudi; vera namreč ni last vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 3, 'Zvest pa je Gospod, ki vas bo utrdil in branil zlega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 4, 'Zaupamo pa vam v Gospodu, da delate in boste delali, kar vam zapovedujemo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 5, 'Gospod pa naj vodi srca vaša v ljubezen Božjo in v stanovitnost Kristusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 6, 'Zapovedujemo pa vam, bratje, v imenu Gospoda našega Jezusa Kristusa, da se ogibljete vsakega brata, ki živi neredno in ne po izročilu, ki ste ga prejeli od nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 7, 'Kajti sami veste, kako je treba nas posnemati: nismo se namreč vedli neredno med vami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 8, 'tudi nismo kruha jedli daroma od koga, ampak s trudom in težavo smo delali noč in dan, da bi ne nadlegovali nikogar od vas;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 9, 'ne ker bi ne imeli za to pravice, temuč da vam bodemo zgled, da nas posnemate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 10, 'Saj smo tudi, ko smo bili pri vas, to zapovedali vam: Če kdo noče delati, naj tudi ne jé.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 11, 'Čujemo namreč, da nekateri med vami žive neredno in ne delajo nič, ampak se pečajo z nepotrebnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 12, 'Takim pa zapovedujemo in jih opominjamo v Gospodu Jezusu Kristusu, da naj v miru delajo in svoj kruh jedo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 13, 'Vi pa, bratje, ne opešajte v dobrem dejanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 14, 'Če pa kdo ne sluša besede naše po listu, tega si oznamenite, da nimate družbe ž njim, da ga bode sram.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 15, 'A ne imejte ga za sovražnika, marveč svarite ga kakor brata.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 16, 'On pa, Gospod miru, vam daj mir vsekdar in povsod! Gospod z vami vsemi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 17, 'Pozdrav z mojo roko, Pavlovo, kar je znamenje v vsakem listu; tako pišem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (53, 3, 18, 'Milost Gospoda našega Jezusa Kristusa z vami vsemi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 1, 'Pavel, apostol Kristusa Jezusa po povelju Boga, Rešitelja našega, in Kristusa Jezusa, upanja našega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 2, 'Timoteju, pravemu otroku svojemu v veri: Milost, usmiljenje, mir od Boga Očeta in Kristusa Jezusa, Gospoda našega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 3, 'Kakor sem te prosil, potujoč v Macedonijo, da ostani v Efezu, da zapoveš nekaterim, naj ne uče drugačnega nauka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 4, 'tudi naj se ne ubijajo z basnimi in brezkončnimi rodopisi, ki pospešujejo bolj prepire nego oskrbovanje službe Božje, ki je v veri, tako te prosim zdaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 5, 'Namen zapovedi pa je ljubezen iz čistega srca in dobre vesti in nehinavske vere,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 6, 'kar so nekateri zgrešili in se obrnili k praznemu besedovanju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 7, 'hoteč biti učeniki postave, dasi ne umejo, ne kaj govore, ne kaj trdijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 8, 'Vemo pa, da je postava dobra, če jo kdo postavno rabi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 9, 'v svesti si, da za pravičnega ni postavljena postava, ampak za nepravične in uporne, brezbožne in grešnike, nesvete in skrunilce svetega, ubijalce očeta in matere, ljudomorce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 10, 'nečistnike, moželežnike, ljudokradce, lažnike, krivoprisežnike in če je še kaj drugega nasprotnega zdravemu uku;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 11, 'kakor priča evangelij slave blaženega Boga, ki je bil poverjen meni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 12, 'Hvaležen sem njemu, ki mi je dal moč, Kristusu Jezusu, Gospodu našemu, da me je za zvestega imel in me postavil v službo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 13, 'ki sem bil prej preklinjalec in preganjalec in silovitnik; ali usmiljenje sem zadobil, ker sem delal to iz nevednosti v neveri;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 14, 'preobilo pa se je pomnožila milost Gospoda našega z vero in ljubeznijo, ki je v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 15, 'Resnična je ta beseda in vsekakor vredna, da se sprejme: da je Kristus Jezus prišel na svet rešit grešnike, katerih prvi sem jaz.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 16, 'Ali zato sem zadobil usmiljenje, da bi na meni prvem Kristus Jezus pokazal vso svojo potrpežljivost, za zgled njim, ki bodo verovali vanj za večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 17, 'Kralju vekov pa, neminljivemu, nevidnemu, edinemu Bogu, čast in slava na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 18, 'To zapoved ti izročam, moj otrok Timotej, po prejšnjih prorokovanjih o tebi, da biješ po njih dobri boj');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 19, 'in ohraniš vero in dobro vest, ki so jo nekateri pahnili od sebe ter se ponesrečili v veri;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 1, 20, 'med katerimi sta Himenej in Aleksander, ki sem ju izročil satanu, da se po kazni naučita ne preklinjati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 1, 'Opominjam torej pred vsem, naj se opravljajo prošnje, molitve, klici, zahvale za vse ljudi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 2, 'za kralje in vse prvake, da živimo mirno in tiho življenje v vsej pobožnosti in poštenosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 3, 'To je dobro in prijetno pred Bogom, Rešiteljem našim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 4, 'ki hoče, da se rešijo vsi ljudje in pridejo do spoznanja resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 5, 'Zakaj eden je Bog, eden tudi srednik med Bogom in ljudmi, človek Kristus Jezus,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 6, 'ki je dal samega sebe v odkupnino za vse, v pričevanje ob svojem času;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 7, 'za kar sem bil jaz postavljen kot glasnik in apostol (resnico govorim, ne lažem), učitelj poganov v veri in resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 8, 'Hočem torej, da molijo možje v vsakem kraju, dvigajoč svete roke brez jeze in dvoma.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 9, 'Istotako tudi žene v spodobni opravi, naj se dičijo s sramežljivostjo in zmernostjo, ne s kitami ali z zlatom ali z biseri ali z drago obleko,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 10, 'marveč (kakor se spodobi ženskam, ki pripoznavajo bogaboječnost) z dobrimi deli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 11, 'Žena naj se na tihem uči v vsej podložnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 12, 'Ženi pa učiti ne dovoljujem, ne gospodovati možu, nego naj živi na tihem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 13, 'Kajti Adam je bil prvi ustvarjen, potem Eva;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 14, 'in Adam ni bil prevaran, žena pa je prevarana padla v pregreho;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 2, 15, 'rešena pa bo v rojenju otrok, ako ostane v veri in ljubezni in posvečenju z zmernostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 1, 'Resnica je beseda: Če kdo išče škofovske službe, želi lepega dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 2, 'Škof torej treba, da je brez oponosa, ene žene mož, trezen, zmeren, spodoben, gostoljuben, dober učitelj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 3, 'ne pijanec, ne pretepač, ampak krotak, ne prepirljiv, ne denarja lakomen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 4, 'svoji hiši dober gospodar, otroke strahujoč, da so pokorni, z vso resnobo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 5, '(če pa kdo svoji hiši ne zna gospodariti, kako bo skrbel za cerkev Božjo?)');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 6, 'ne novinec, da napihnjen ne pade v obsodbo hudičevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 7, 'Treba pa tudi, da ima dobro pričevanje od teh, ki so zunaj, da ne pade v očitanje in past hudičevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 8, 'Diakoni istotako treba, da so resnobni, ne dvojezični, ne mnogemu vinu vdani, ne grdega dobička željni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 9, 'ki hranijo skrivnost vere v čisti vesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 10, 'A tudi ti naj se najprej preizkusijo; potem naj služijo kot diakoni, ako so brez graje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 11, 'Žene istotako, da so resnobne, ne obrekljive, trezne, zveste v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 12, 'Diakoni naj bodo ene žene možje, otrokom in svojim hišam dobri gospodarji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 13, 'Kateri so namreč dobro opravljali diakonsko službo, si pridobé lepo stopnjo in veliko srčnost v veri, ki je v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 14, 'To ti pišem, upajoč, da skoro pridem k tebi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 15, 'ako se pa zamudim, da veš, kako se je treba vesti v hiši Božji, ki je cerkev Boga živega, stolp in podstavek resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 3, 16, 'In kakor vsi priznavamo, velika je skrivnost pobožnosti: on, ki je bil razodet v mesu, je bil opravičen v duhu, prikazal se je angelom, je bil oznanjevan poganom, verovalo se mu je na svetu, gori je bil vzet v slavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 1, 'Duh pa razločno pravi, da bodo v poslednjih časih nekateri odpadli od vere in poslušali zapeljive duhove in nauke hudobnih duhov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 2, 'vsled licemerstva lažigovornikov, ki nosijo vžgano znamenje v svoji vesti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 3, 'ki branijo ženiti se in možiti in zapovedujejo zdrževati se jedil, katera je Bog ustvaril, da jih z zahvaljevanjem uživajo verni in ti, ki so spoznali resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 4, 'Kajti vsaka stvar Božja je dobra in ničesar ni, da bi zametali, ako prejemljemo z zahvaljevanjem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 5, 'posvečuje se namreč po besedi Božji in molitvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 6, 'To naročajoč bratom, bodeš dober služabnik Kristusa Jezusa, vzrejen v besedah vere in dobrega nauka, ki si mu doslej sledil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 7, 'Posvetne in starobabje basni pa zavračaj. Vadi se pa v pobožnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 8, 'zakaj telesna vaja je za malo koristna, pobožnost pa je za vse koristna, ker ima obljubo življenja sedanjega in prihodnjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 9, 'Resnična je ta beseda in vsekakor vredna, da se sprejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 10, 'Kajti zato se tudi trudimo in nas sramoté, ker smo upanje svoje postavili na živega Boga, ki je Rešitelj vseh ljudi, sosebno vernih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 11, 'Zapoveduj to in úči!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 12, 'Nihče naj ne zaničuje mladosti tvoje; marveč zgled bodi vernim v besedi, v vedenju, v ljubezni, v veri, v čistosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 13, 'Dokler ne pridem, bodi priden v branju, opominjanju, poučevanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 14, 'Ne zanemarjaj daru milosti, ki je v tebi, ki ti je bil dan po proroštvu s pokladanjem rok starejšinstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 15, 'Za to skrbi, v tem bivaj, da bode napredek tvoj očiten vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 4, 16, 'Pazi nase in na svoj nauk. Stanoviten bodi v tem; kajti to delajoč, boš rešil sebe in nje, ki te poslušajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 1, 'Starejšega ne prijemlji trdo, temuč opominjaj ga kakor očeta, mlajše kakor brate,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 2, 'žene starejše kakor matere, mlajše kakor sestre, v vsej čistosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 3, 'Vdove spoštuj, ki so res vdove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 4, 'Ako pa ima kaka vdova otroke ali vnuke, ti naj se uče najprej izkazovati spoštovanje do svoje hiše in povračati roditeljem; zakaj to je prijetno pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 5, 'Katera je pa res vdova in osamela, je postavila upanje svoje na Boga in je stanovitna v prošnjah in molitvah noč in dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 6, 'Razuzdana pa je mrtva, dasi še živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 7, 'Tudi to zapoveduj, da bodo brez oponosa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 8, 'Ako pa kdo ne skrbi za svoje, zlasti pa za domače, je zatajil vero in je hujši od nevernika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 9, 'Vdova naj se ne sprejme pod šestdesetimi leti v imenik, ki je bila enega moža žena');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 10, 'in je na dobrem glasu zaradi dobrih del, če je vzredila otroke, če je sprejemala tujce, če je svetim umivala noge, če je pomagala stiskanim, če si je prizadevala za sleherno dobro delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 11, 'Mlajših vdov pa ne sprejmi v imenik; ko so namreč pohotne postale zoper Kristusa, se hočejo možiti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 12, 'in si nakopljejo sodbo, ker so se izneverile prvi veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 13, 'Zraven pa se tudi navadijo brez dela pohajkovati po hišah; in ne samo brez dela, ampak tudi jezične in vedečne so, govoreč, česar ni potreba.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 14, 'Hočem torej, da naj se mlajše možé, otroke rode, gospodinjijo in nobenega povoda ne dajo nasprotniku za obrekovanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 15, 'Kajti že se jih je nekaj odvrnilo za satanom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 16, 'Če ima kateri vernik ali vernica vdove, naj jim pomaga, in cerkev ne imej težave, da more pomagati pravim vdovam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 17, 'Starejšine, ki so dobri predstojniki, naj štejejo za dvojne časti vredne, zlasti nje, ki se trudijo v besedi in poučevanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 18, 'Pismo namreč govori: „Ne zaveži gobca volu, ki vrši žito“, in: Vreden je delavec svojega plačila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 19, 'Zoper starejšino ne sprejmi tožbe, razen na dve priči ali tri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 20, 'Tiste, ki greše, svari vpričo vseh, da bodo imeli tudi drugi strah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 21, 'Rotim te pred Bogom in Kristusom Jezusom in angeli izvoljenimi, da hraniš to brez predsodka in ne storiš ničesar po lastnem nagnjenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 22, 'Rok nikomur prenaglo ne pokladaj in ne udeležuj se tujih grehov. Ohrani samega sebe čistega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 23, 'Ne pij več same vode, ampak uživaj malo vina, zaradi želodca svojega in pogostnih slabosti svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 24, 'Nekaterih ljudi grehi so očitni in gredo pred njimi v sodbo; nekaterim pa tudi slede šele pozneje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 5, 25, 'Tako so tudi dobra dela očitna, in ona, ki je drugače ž njimi, se ne dado skriti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 1, 'Vsi, ki so kot hlapci pod jarmom, naj imajo svoje gospodarje za vse časti vredne, da se ne govori grdo o imenu Božjem in nauku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 2, 'Kateri pa imajo verne gospodarje, naj jih ne zaničujejo, ker so bratje; ampak tem rajši naj služijo, ker so verni in ljubljeni, kateri prejemajo to dobroto. To uči in opominjaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 3, 'Ako kdo drugače uči in noče pristati na zdrave besede, besede Gospoda našega Jezusa Kristusa, in na nauk, ki vodi k pobožnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 4, 'je napihnjen in ničesar ne ume, marveč boleha za pregovarjanjem in besednimi prepiri, iz katerih se izcimi zavist, pričkanje, preklinjanje, natolcevanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 5, 'neprestano besedičenje ljudi, popačenih na umu in brez resnice, ki mislijo, da je pobožnost dobiček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 6, 'Je pa velik dobiček pobožnost, združena z zadovoljnostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 7, 'Zakaj ničesar nismo prinesli na svet, ker tudi odnesti ne moremo ničesar;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 8, 'če pa imamo hrane in odeje, bodimo s tem zadovoljni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 9, 'Kateri pa hočejo biti bogati, padejo v izkušnjavo in past in v mnoga poželenja, nespametna in škodljiva, ki pogrezajo ljudi v pogubljenje in pogin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 10, 'Korenina vsega zlega namreč je srebroljubje; njemu vdani, so nekateri zabredli od vere in sami so se presunili z mnogimi bolečinami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 11, 'Ti pa, o človek Božji, beži od tega; hodi pa za pravičnostjo, pobožnostjo, vero, ljubeznijo, stanovitnostjo, krotkostjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 12, 'Bij dobri boj vere, poprimi se večnega življenja, ki si bil zanje poklican in si pripoznal lepo veroizpoved pred mnogimi pričami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 13, 'Zapovedujem ti pred Bogom, ki vse oživlja, in Kristusom Jezusom, ki je izpričal pred Poncijem Pilatom lepo izpoved,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 14, 'da hraniš zapoved brez madeža, brez graje do prikazni Gospoda našega Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 15, 'ki jo pokaže ob svojem času blaženi in edini Vladar, Kralj kraljujočih in gospodujočih Gospod,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 16, 'ki ima sam neumrjočnost in biva v nedostopni svetlobi, ki ga ni videl ljudi nobeden in ga tudi videti ne more; njemu čast in moč večna! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 17, 'Bogatinom v sedanjem svetu zapoveduj, naj se ne prevzemajo, niti ne stavijo upa v bogastva negotovost, ampak v živega Boga, ki nam deli vsega obilo za uživanje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 18, 'naj dobro delajo, bogaté v dobrih delih, naj bodo radodarni, sočutni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 19, 'nabirajoč si zaklade v dobro podstavo za prihodnost, da se poprimejo resničnega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 20, 'O Timotej, hrani to, kar ti je poverjeno, ogibajoč se posvetnega govoričenja in nasprotij znanosti, ki se po krivem tako imenuje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (54, 6, 21, 'katero si pripisujoč, so nekateri zgrešili vero. Milost bodi z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 1, 'Pavel, apostol Kristusa Jezusa po volji Božji za obljubo življenja, ki je v Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 2, 'Timoteju, ljubljenemu otroku svojemu: Milost, usmiljenje, mir od Boga Očeta in Kristusa Jezusa, Gospoda našega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 3, 'Hvaležen sem Bogu, ki mu služim od pradedov svojih s čisto vestjo, kakor te imam neprestano v spominu v molitvah svojih ter po noči in po dne,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 4, 'spominjajoč se solz tvojih, hrepenim videti te, da se napolnim veselja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 5, 'ker imam v mislih nelicemersko vero tvojo, ki je bivala najprej v babici tvoji Loidi in materi tvoji Evniki, preverjen sem pa, da je tudi v tebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 6, 'Zategadelj te spominjam, da razpihaš milosti dar Božji, ki je v tebi po pokladanju rok mojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 7, 'Kajti Bog nam ni dal duha boječnosti, ampak moči in ljubezni in samostrahovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 8, 'Ne sramuj se torej pričevanja Gospoda našega, ne mene, jetnika njegovega, temuč udeleži se trpljenja za evangelij po moči Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 9, 'ki nas je rešil in poklical s svetim poklicem, ne po delih naših, ampak po lastnem sklepu in milosti svoji, ki nam je bila dana v Kristusu Jezusu pred večnimi časi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 10, 'a sedaj je bila razodeta po prihodu Rešitelja našega Kristusa Jezusa, ki je uničil smrt in na svetlo privedel življenje in neminljivost po evangeliju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 11, 'za katerega sem bil jaz postavljen za glasnika in apostola in učitelja poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 12, 'Zategadelj tudi to trpim, toda ni me sram; vem namreč, komu sem veroval, in preverjen sem, da je zmožen hraniti, kar sem mu izročil, za tisti dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 13, 'Drži se vzora zdravih besed, ki si jih slišal od mene, v veri in ljubezni, ki je v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 14, 'Dobri zaklad, ki ti je bil izročen, hrani po svetem Duhu, ki prebiva v nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 15, 'To veš, da so se odvrnili od mene vsi v Aziji, med katerimi sta Figel in Hermogen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 16, 'Usmiljenje daj Gospod hiši Oneziforjevi, ker me je mnogokrat poživil in se ni sramoval spon mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 17, 'temuč me je, ko je bil v Rimu, z gorečnostjo iskal in našel');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 1, 18, '(Gospod mu daj, da najde usmiljenje pri Gospodu tisti dan); in koliko je služboval v Efezu, sam najbolje veš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 1, 'Ti torej, otrok moj, ojači se v milosti, ki je v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 2, 'In kar si slišal od mene pred mnogimi pričami, to izroči zvestim ljudem, ki bodo zmožni tudi druge učiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 3, 'Udeleži se trpljenja kakor dober vojak Kristusa Jezusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 4, 'Noben vojak, ko je v službi, se ne zapleta v opravila življenja, da je po volji temu, ki ga je najel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 5, 'Ako se pa kdo tudi bojuje, ne dobi venca, ako se ne bojuje postavno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 6, 'Poljedelec, ki se trudi, užije naj prvi pridelkov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 7, 'Premisli, kar pravim; Gospod ti namreč da razum v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 8, 'Spominjaj se Jezusa Kristusa, ki je vstal od mrtvih, ki je iz semena Davidovega, po evangeliju mojem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 9, 'ki v njegovi službi trpim nadloge in sem celo vklenjen kakor hudodelnik; ali beseda Božja ni vklenjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 10, 'Zato trpim vse zaradi izvoljenih, da tudi oni zadobe zveličanje, ki je v Kristusu Jezusu, z večno slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 11, 'Resnična je ta beseda: če smo namreč ž njim umrli, bomo tudi ž njim živeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 12, 'če trpimo, bomo tudi ž njim kraljevali; če ga zatajimo, nas tudi on zataji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 13, 'če smo nezvesti, on ostane zvest, kajti zatajiti samega sebe ne more.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 14, 'Tega jih spominjaj, roteč pred Gospodom, naj se ne prepirajo za besede, kar nič ne koristi, a je v pogubo poslušajočim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 15, 'Prizadevaj si preizkušenega se izkazati Bogu, kot delavca, ki se mu ni sramovati, ki prav ravna z besedo resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 16, 'Posvetnega govoričenja pa se ogiblji; zakaj vedno bolj bodo napredovali v brezbožnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 17, 'in njih beseda bo razjedala krog sebe kakor rak: izmed katerih sta Himenej in Filet,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 18, 'ki sta zgrešila resnico, govoreč, da je že bilo vstajenje, in izpodkopavata nekaterim vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 19, 'Toda trdni temelj Božji stoji ter ima ta pečat: Gospod pozna svoje, in: Odstopi naj od krivice vsak, kdor imenuje ime Gospodovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 20, 'V veliki hiši pa niso samo zlate in srebrne posode, ampak tudi lesene in lončene, in nekatere v čast, nekatere v nečast.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 21, 'Ako se torej kdo očisti od takih, bode posoda v čast, posvečena, koristna Gospodarju, pripravljena za sleherno dobro delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 22, 'Od mladostnih poželenj pa beži, a hodi za pravičnostjo, vero, ljubeznijo, mirom ž njimi, ki kličejo Gospoda iz čistega srca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 23, 'Nespametnih in neslanih prepirov pa se ogibaj, vedoč, da rode boje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 24, 'Hlapec Gospodov pa se ne sme bojevati, ampak krotak bodi do vseh, dober učitelj, strpljiv;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 25, 'v krotkosti naj svari nasprotnike, če bi jim morda dal Bog izpokorjenje v spoznanje resnice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 2, 26, 'in bi se iztreznili in ušli iz pasti hudičeve, ko jih je bil ujel v voljo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 1, 'To pa vedi, da v zadnjih dneh nastanejo nevarni časi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 2, 'Kajti ljudje bodo samoljubni, lakomni, širokoustni, prevzetni, opravljivi, roditeljem nepokorni, nehvaležni, nesveti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 3, 'brezsrčni, nespravljivi, obrekljivi, nezmerni, surovi, nedobroljubni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 4, 'izdajalci, vrtoglavi, napihnjeni, veselje bolj ljubeči nego Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 5, 'ki sicer hranijo podobo pobožnosti, njeno moč pa so zatajili; in teh se ogiblji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 6, 'Izmed teh namreč so tisti, ki se plazijo v hiše in love ženščine, obložene z grehi, katere goni mnogotero poželenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 7, 'ki se vedno uče in nikdar ne morejo priti do spoznanja resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 8, 'Enako pa, kakor sta se Janez in Jambrez upirala Mojzesu, tako se tudi ti upirajo resnici, ljudje popačeni na umu, malopridni za vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 9, 'Ali dalje ne bodo napredovali: zakaj njih nespamet bode vsem očita, kakor je bila tudi onih dveh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 10, 'Ti pa si hodil za menoj v nauku, vedenju, mišljenju, veri, prizanesljivosti, ljubezni, stanovitnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 11, 'preganjanju, trpljenju, kakršno me je zadelo v Antiohiji, v Ikoniji, v Listri. Kakšna preganjanja sem prebil, in iz vseh me je otel Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 12, 'Pa tudi vsi, ki hočejo pobožno živeti v Kristusu Jezusu, bodo preganjani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 13, 'Hudobni ljudje pa in sleparji bodo napredovali v slabem, varali bodo in bodo varani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 14, 'Ti pa ostani v tem, česar si se naučil in o čemer si se prepričal, ker veš, od koga si se učil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 15, 'in ker od mladih nog znaš sveta pisma, ki so te zmožna zmodriti za zveličanje po veri, ki je v Kristusu Jezusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 16, 'Vsako pismo je od Boga navdihnjeno in koristno za pouk, za prepričanje, za poboljšanje, za vzgojo v pravičnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 3, 17, 'da bode popoln človek Božji, docela pripraven za vsako dobro delo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 1, 'Rotim te torej pred Bogom in Kristusom Jezusom, ki bo sodil žive in mrtve, in pri prihodu njegovem in kraljestvu njegovem:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 2, 'Oznanjaj besedo, ne odnehaj o priliki, nepriliki; prepričuj, kaznuj, opominjaj z vso potrpežljivostjo in s poučevanjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 3, 'Kajti pride čas, ko ne bodo prenašali zdravega nauka, temuč po lastnem poželenju si kopičili učitelje, po tem, kakor jih ušesa srbe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 4, 'in od resnice bodo odvračali ušesa in se obračali k basnim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 5, 'Ti pa bodi trezen v vsem, trpi nadloge, opravljaj delo evangelista, izpolnjuj službo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 6, 'Kajti jaz bom skoraj žrtvovan, in ločitve moje čas je blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 7, 'Bojeval sem dobri boj, dokončal tek, ohranil vero;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 8, 'že mi je pripravljen pravičnosti venec, ki mi ga podeli Gospod tisti dan, pravični sodnik; a ne samo meni, ampak tudi vsem, ki so ljubili prihod njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 9, 'Prizadeni si, da prideš skoraj k meni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 10, 'zakaj Dema me je zapustil, iz ljubezni do tega sveta, in je potoval v Solun, Krescent v Galacijo, Tit v Dalmacijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 11, 'Lukež je sam pri meni. Marka vzemi in pripelji s seboj, kajti koristen mi je za službo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 12, 'Tihika pa sem poslal v Efez.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 13, 'Plašč, ki sem ga pustil v Troadi pri Karpu, prinesi s seboj, kadar prideš, in knjige, zlasti pergamente.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 14, 'Aleksander kovač mi je storil mnogo hudega; Gospod mu povrne po delih njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 15, 'Njega se tudi ti pazi; kajti silno je nasprotoval besedam našim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 16, 'O prvem zagovarjanju mojem mi ni bilo nikogar na strani, ampak vsi so me zapustili: naj se jim ne všteva!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 17, 'Gospod pa mi je bil na pomoč in me je ojačil, da se po meni slavno dovrši oznanjevanje in ga čujejo vsi pogani; in otet sem bil levu iz žrela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 18, 'Gospod me otme vsakega hudega dela in reši v kraljestvo svoje nebeško. Njemu slava na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 19, 'Pozdravi Prisko in Akvila in Oneziforjevo hišo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 20, 'Erast je ostal v Korintu, Trofima pa sem pustil bolnega v Miletu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 21, 'Prizadeni si, da prideš pred zimo. Pozdravljajo te Evbul in Pudent in Lin in Klavdija in bratje vsi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (55, 4, 22, 'Gospod bodi z duhom tvojim! Milost z vami!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 1, 'Pavel, hlapec Božji, apostol pa Jezusa Kristusa, po veri izvoljencev Božjih in spoznanju resnice, ki vodi k pobožnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 2, 'na podlagi upanja večnega življenja, ki ga je obljubil pred večnimi časi Bog, ki nikoli ne laže,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 3, 'a ob svojem času je razodel besedo svojo v oznanilu, ki mi je bilo poverjeno po povelju Rešitelja našega, Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 4, 'Titu, pravemu otroku svojemu po naši skupni veri: Milost in mir od Boga Očeta in Kristusa Jezusa, Zveličarja našega!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 5, 'Zato sem te pustil na Kreti, da urediš, kar je še pomanjkljivega, in nastaviš po mestih starejšine, kakor sem ti ukazal:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 6, 'če je kdo brez oponosa, ene žene mož, ima verne otroke, ki niso na glasu razuzdanosti ali nepokorni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 7, 'Škof namreč mora biti brez oponosa, kakor oskrbnik Božji; ne samovšečen, ne nagle jeze, ne pijanec, ne pretepač, ne grdega dobička željen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 8, 'ampak gostoljuben, dobrega prijatelj, zmeren, pravičen, svet, zdržljiv,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 9, 'držeč se zveste besede, ki je v soglasju z naukom, da bode zmožen opominjati v zdravem uku in prepričevati nasprotno govoreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 10, 'Kajti mnogo jih je upornih, blebetačev in sleparjev, zlasti iz obreze,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 11, 'ki jim je treba usta zamašiti; kateri cele hiše narobe obračajo, učeč, česar ne bi smeli, za grd dobiček.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 12, 'Rekel je nekdo izmed njih, njih lastni prorok: Krečani so vedno lažniki, grde zveri, leni trebuhi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 13, 'To izpričevalo je resnično. Zato jih ostro svari, da bodo zdravi v veri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 14, 'ne poslušajoč basni judovskih in ukazov ljudi, ki se obračajo od resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 15, 'Vse je čisto čistim; oskrunjenim pa in nevernim ni nič čisto, temuč oskrunjena sta njih um in njih vest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 1, 16, 'Proglašajo, da poznajo Boga, v delih pa ga zatajujejo, ker so ostudni in nepokorni in za vsako dobro delo nesposobni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 1, 'Ti pa govori, kar se spodobi zdravemu nauku.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 2, 'Starci da naj bodo trezni, resnobni, zmerni, zdravi v veri, ljubezni, stanovitnosti;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 3, 'starke enako, da so v vedenju, kakor se svetim spodobi, ne obrekljive, ne mnogopitju vdane, dobrega učiteljice,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 4, 'da napeljavajo k redu mlajše žene, naj ljubijo može in otroke svoje');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 5, 'in naj bodo zmerne, čiste, pridne gospodinje, dobrotljive, pokorne svojim možem, da se ne preklinja Božja beseda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 6, 'Mlajše može istotako opominjaj, da naj bodo zmerni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 7, 'stavi sebe v vseh rečeh za zgled dobrih del, v uku tvojem naj se kaže čistost, dostojnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 8, 'zdrava beseda, ki se ne more zavreči, da se nasprotnik osramoti, ker nima kaj slabega reči o nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 9, 'Hlapce opominjaj, naj bodo pokorni svojim gospodarjem, v vsem jim pogodu, naj ne ugovarjajo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 10, 'ničesar ne izmikajo, ampak kažejo v vsem največjo zvestobo, da tako lepšajo nauk Rešitelja našega Boga v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 11, 'Kajti prikazala se je milost Božja zveličalna vsem ljudem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 12, 'učeč nas, da se odpovejmo brezbožnosti in posvetnim poželenjem ter živimo zmerno in pravično in pobožno v sedanjem svetu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 13, 'čakajoč blaženega upanja in prikazni slave velikega Boga in Zveličarja našega Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 14, 'ki je dal samega sebe za nas, da bi nas rešil sleherne nepostavnosti in očistil sebi za lastno ljudstvo, goreče za vsa dobra dela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 2, 15, 'To govóri in opominjaj in svari z vsem poudarkom. Nihče naj te ne zaničuje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 1, 'Spominjaj jih, da naj se pokoravajo poglavarstvom in oblastem, naj bodo poslušni, pripravljeni za vsako dobro delo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 2, 'o nikomer naj grdo ne govore, naj ne bodo prepirljivi, ampak odjenljivi, kažejo naj sleherno krotkost proti vsem ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 3, 'Bili smo namreč tudi mi nekdaj nespametni, neposlušni, tavajoči, služeči mnogoteremu poželenju in razveseljevanju, živeči v hudobnosti in zavisti, sovraštva vredni, sovražeč se med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 4, 'Ko se je pa prikazala dobrota in ljudoljubnost Rešitelja našega Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 5, 'nas je rešil ne iz del v pravičnosti, ki smo jih mi storili, ampak po usmiljenju svojem, po kopeli preporoda in obnovitve svetega Duha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 6, 'ki ga je obilo razlil nad nas po Jezusu Kristusu, Zveličarju našem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 7, 'da bi, opravičeni po milosti njegovi, postali dediči po upanju večnega življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 8, 'Resnična je ta beseda; in hočem, da o tem krepko pričaš, zato da bode verujoče v Boga skrb, delati dobra dela. To je dobro in koristno ljudem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 9, 'A nespametnih preiskav in rodopisov in prepirov in bojev o postavi se ogiblji; brez koristi so namreč in brez veljave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 10, 'Krivovernega človeka zavrni, posvarivši ga enkrat ali dvakrat,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 11, 'vedoč, da je tak človek popačen in greši, z lastno sodbo obsojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 12, 'Kadar pošljem Artema k tebi ali Tihika, si prizadeni, da prideš k meni v Nikopol; tam namreč sem sklenil prezimiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 13, 'Zena postavouka in Apola skrbno odpravi na pot, da ne bosta ničesar pogrešala.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 14, 'Uče naj se pa tudi naši dobra dela opravljati za nujne potrebe, da ne bodo brez sadu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (56, 3, 15, 'Pozdravljajo te vsi, ki so pri meni. Pozdravi nje, ki nas ljubijo v veri. Milost z vami vsemi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 1, 'Pavel, jetnik Kristusa Jezusa, in Timotej brat Filemonu, ljubljencu in sodelavcu našemu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 2, 'in Afiji sestri in Arhipu, sovojaku našemu, in cerkvi, ki se zbira v hiši tvoji:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 3, 'Milost vam in mir od Boga Očeta našega in Gospoda Jezusa Kristusa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 4, 'Zahvaljujem Boga svojega vsekdar, spominjajoč se tebe v molitvah svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 5, 'ker slišim o ljubezni tvoji in veri, ki jo imaš v Gospoda Jezusa in do vseh svetih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 6, 'da se deleštvo vere tvoje izkaže delavno v pripoznanju vsega dobrega, kar je v nas za Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 7, 'Kajti v veliko radost in tolažbo mi je bila ljubezen tvoja, ker so se srca svetih poživila po tebi, brat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 8, 'Zato, čeprav si dosti v Kristusu upam ukazati ti, kar je spodobno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 9, 'vendar te zaradi ljubezni rajši prosim, tak, kakršen sem, Pavel stari, sedaj pa tudi jetnik Jezusa Kristusa –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 10, 'prosim te za dete svoje, ki sem ga rodil v sponah svojih, Onezima,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 11, 'ki ti je bil nekdaj nekoristen, sedaj pa je tebi in meni koristen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 12, 'ki ti ga nazaj pošiljam, njega, to je: srce moje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 13, 'Jaz bi ga bil rad obdržal pri sebi, da bi mi zate služil v sponah evangelija;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 14, 'toda brez tvojega privoljenja nisem hotel ničesar storiti, da dobrota tvoja ne bode kakor po sili, ampak prostovoljna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 15, 'Kajti lahko da je bil zato nekaj časa ločen od tebe, da bi ga imel vekomaj,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 16, 'ne več za hlapca, ampak nad hlapca, za brata ljubljenega, sosebno meni, koliko bolj pa tebi, i po mesu i v Gospodu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 17, 'Če imaš torej mene za tovariša, sprejmi ga kakor mene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 18, 'Če ti je pa storil kaj žalega ali ti je dolžan, tisto vštej meni:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 19, 'jaz Pavel pišem s svojo roko, jaz to poplačam – da ti ne rečem, da si mi tudi še samega sebe dolžan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 20, 'Da, brat, da bi jaz imel korist od tebe v Gospodu! Poživi srce moje v Kristusu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 21, 'Zaupajoč v pokorščino tvojo, ti pišem, vedoč, da boš še več storil, nego pravim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 22, 'Zraven tega pa mi pripravi tudi stanovanje; kajti upam, da vam bom podarjen po molitvah vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 23, 'Pozdravlja te Epafra, sojetnik moj v Kristusu Jezusu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 24, 'in Marko, Aristarh, Dema, Lukež, sodelavci moji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (57, 1, 25, 'Milost Gospoda našega Jezusa Kristusa z duhom vašim! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 1, 'Potem ko je Bog nekdaj mnogokrat in na razne načine govoril očetom po prorokih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 2, 'nam je v teh zadnjih dneh govoril po Sinu, ki ga je postavil za dediča vseh stvari, ki je po njem naredil tudi svetove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 3, 'ki je odsvit slave in podoba bitja njegovega in vzdržuje vse z besedo moči svoje; ki je, potem ko je po sebi izvršil očiščenje grehov naših, sedel na desnico veličastva v višavah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 4, 'in je tolikanj višji postal od angelov, kolikor odličnejše ime je podedoval mimo njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 5, 'Kajti kateremu izmed angelov je kdaj rekel: „Sin moj si ti, jaz sem te danes rodil“, in zopet: „Jaz mu bodem za očeta in on mi bode za sina“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 6, 'In ko bo prvorojenca zopet vpeljal v svet, pravi: „In molijo naj ga vsi angeli Božji“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 7, 'In o angelih sicer pravi: „On dela angele svoje za vetrove in služabnike svoje za ognja plamen“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 8, 'o Sinu pa: „Prestol tvoj, o Bog, na veka vek. Pravičnosti žezlo je kraljestva tvojega žezlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 9, 'Ljubil si pravico in sovražil krivico. Zato te je pomazilil Bog, Bog tvoj, z oljem veselja bolj nego sodeležnike tvoje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 10, 'In: „Ti si v začetku, Gospod, ustanovil zemljo, in rok tvojih dela so nebesa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 11, 'njih bode konec, ti pa ostaneš; in vsa se bodo postarala kakor obleka,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 12, 'in kakor plašč jih boš zvil, in izpremenila se bodo; ti pa si isti, in let tvojih ne bode konec“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 13, 'Kateremu izmed angelov pa je kdaj rekel: „Sedi na desnico mojo, dokler ne položim sovražnikov tvojih za podnožje nogam tvojim“?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 1, 14, 'Niso li vsi služabni duhovi, v službo pošiljani zaradi njih, ki imajo podedovati zveličanje?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 1, 'Zato nam treba tolikanj bolj paziti na to, kar smo slišali, da ne zgrešimo zveličanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 2, 'Če je namreč beseda, po angelih govorjena, postala trdna in je vsak prestopek in neposluh dobil pravično plačilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 3, 'kako uidemo mi, pustivši vnemar toliko zveličanje? ki ga je iz početka oznanjal Gospod, in oni, ki so čuli, so nam ga potrdili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 4, 'pri čemer je tudi Bog ž njimi vred pričal z znamenji in čudeži in mnogoterimi močmi in s podeljevanjem svetega Duha po volji svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 5, 'Kajti angelom ni podložil sveta prihodnjega, o katerem govorimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 6, 'Pričal pa je nekdo nekje, govoreč: „Kaj je človek, da se ga spominjaš, ali sin človekov, da ga obiskuješ?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 7, 'Za malo časa si ga ponižal pod angele; s slavo in častjo si ga venčal in postavil si ga nad dela rok svojih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 8, 'vse si podložil pod noge njegove.“Ker mu je pa vse podložil, torej ni pustil ničesar njemu nepodloženega. Sedaj pa ne vidimo še, da bi mu bilo vse podloženo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 9, 'vidimo pa Jezusa, ki je bil za malo časa ponižan pod angele, zaradi trpljenja smrti venčanega s slavo in častjo, da po milosti Božji okusi smrt za vsakega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 10, 'Kajti spodobilo se je njemu, za katerega je vse in po katerem je vse, ko je mnogo sinov peljal v slavo, začetnika njih zveličanja popolnega storiti po trpljenju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 11, 'Kajti i ta, ki posvečuje, i oni, ki se posvečujejo, vsi so iz enega; iz tega vzroka se ne sramuje imenovati jih brate, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 12, '„Oznanjal bom ime tvoje bratom svojim, sredi zbora ti bom peval hvalo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 13, 'In zopet: „Nanj naslonim upanje svoje“, in zopet: „Glej, jaz in otročiči, katere mi je dal Bog“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 14, 'Ker so torej otročiči deležni mesa in krvi, se je tudi on tega podobno udeležil, da bi s svojo smrtjo uničil njega, ki ima smrti oblast, to je: hudiča,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 15, 'in osvobodil tiste, ki so v strahu smrti vse življenje bili v sponah sužnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 16, 'Saj se pač ne poteza za angele, ampak za seme Abrahamovo se poteza.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 17, 'Zato se je moral v vsem enakega storiti bratom, da postane usmiljen in zvest veliki duhovnik pred Bogom, da poravna ljudstva grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 2, 18, 'Kajti v kolikor je sam trpel in izkušan bil, v toliko tudi more pomagati izkušanim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 1, 'Zatorej, bratje sveti, poklica nebeškega deležni, pazljivo glejte na poslanca in velikega duhovnika naše veroizpovedi, Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 2, 'ki je zvest njemu, ki ga je naredil, kakor je bil tudi Mojzes zvest v vsej hiši njegovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 3, 'Večje slave namreč je bil ta za vrednega spoznan od Mojzesa, v kolikor ima večjo čast od hiše tisti, ki jo je napravil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 4, 'Kajti vsako hišo napravi kdo; on pa, ki je vse napravil, je Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 5, 'In Mojzes je bil zvest v vsej hiši njegovi kakor služabnik, v pričanje tistega, kar se je imelo pozneje oznanjati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 6, 'Kristus pa je zvest kakor sin, vladajoč hiši svoji; čigar hiša smo mi, ako srčno zaupnost in hvalo upanja ohranimo trdno do konca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 7, 'Zatorej, kakor govori sveti Duh: „Danes, ko začujete glas njegov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 8, 'ne zakrknite src svojih, kakor v razdražbi ob dnevi izkušnjave v puščavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 9, 'kjer so me izkušali očetje vaši s preizkušanjem in gledali dela moja štirideset let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 10, 'Zato sem se razsrdil nad tem rodom in rekel: Vedno tavajo v srcu; ali oni niso spoznali potov mojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 11, 'tako da sem prisegel v jezi svoji: Ne pridejo v pokoj moj!“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 12, 'Glejte, bratje, da ne bode v kom izmed vas hudobnega srca nevere, ki odpade od Boga živega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 13, 'marveč opominjate se vsak dan, dokler se še kliče „danes“, da ne zakrkne kdo izmed vas vsled prevare greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 14, 'Kajti postali smo sodeležniki Kristusa, ako le začetek zaupanja trdno ohranimo do konca;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 15, 'dokler se pravi: „Danes, ko začujete glas njegov, ne zakrknite src svojih kakor v razdražbi“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 16, 'Kajti kdo so bili tisti, ki so slišali in napravili razdražbo? Ne li pa vsi, ki so izšli iz Egipta po Mojzesu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 17, 'Nad katerimi pa se je srdil štirideset let? Mar ne nad njimi, ki so bili grešili, ki so jim telesa popadala v puščavi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 18, 'Katerim pa je prisegel, da ne pridejo v pokoj njegov, če ne njim, ki so bili nepokorni?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 3, 19, 'In vidimo, da niso mogli priti vanj zaradi nevere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 1, 'Bojmo se torej, da se, ko še ostaja obljuba, da pridemo v pokoj njegov, ne vidi, da je kdo izmed vas zaostal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 2, 'Kajti blagovestje smo prejeli mi kakor tudi oni; ali onim ni koristila slišana beseda, ker ni bila združena z vero njih, ki so jo slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 3, 'Kajti v pokoj prihajamo mi, ki smo vero sprejeli; kakor je rekel: „V jezi svoji sem prisegel: Ne pridejo v pokoj moj!“In vendar so bila dela Božja končana od ustanovitve sveta;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 4, 'saj je rekel nekje o sedmem dne tako: „In počival je Bog sedmi dan od vseh del svojih“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 5, 'In tukaj zopet: „Ne pridejo v pokoj moj“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 6, 'Ker je torej še pričakovati, da pridejo nekateri vanj, in oni, kateri so najprvo prejeli blagovestje, niso prišli vanj zaradi nepokorščine,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 7, 'določa zopet neki dan, ko pravi v Davidu „danes“čez toliko časa, kakor je prej rečeno: „Danes, ko začujete glas njegov, ne zakrknite src svojih“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 8, 'Kajti ako bi jih bil Jozue vpeljal v pokoj, ne bi potem Bog govoril o drugem dnevu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 9, 'Torej ostaja še sobotni počitek ljudstvu Božjemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 10, 'Kajti kdor je prišel v pokoj njegov, počiva tudi sam od svojih del kakor Bog od lastnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 11, 'Prizadenimo si torej, da pridemo v oni pokoj, da ne pade kdo po enakem zgledu nepokorščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 12, 'Živa je namreč beseda Božja in krepka in ostrejša nego vsak dvorezen meč, in prodira prav do ločitve duše in duha, členovja in mozga, in je sodnik naklepov in misli srca;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 13, 'in stvari ni skrite pred njim, temuč vse je golo in razodeto očem njega, ki imamo ž njim opravek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 14, 'Ker imamo torej tako vzvišenega velikega duhovnika, ki je šel skozi nebesa, Jezusa, Sinu Božjega, držimo se svoje veroizpovedi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 15, 'Kajti nimamo velikega duhovnika, ki bi ne mogel z nami čutiti slabosti naših, ampak izkušan je v vsem kakor mi, a brez greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 4, 16, 'Bližajmo se torej s srčno zaupnostjo prestolu milosti, da dobimo usmiljenje in najdemo milost za pravočasno pomoč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 1, 'Kajti vsak veliki duhovnik se jemlje izmed ljudi in se postavlja za ljudi v to, kar zadeva Boga, da prinaša darila in žrtve za grehe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 2, 'ki more potrpljenje imeti z nevednimi in tavajočimi, ker je tudi sam obdan s slabostjo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 3, 'in zaradi te mora kakor za ljudstvo tako tudi zase darovati za grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 4, 'In sam si nihče ne prisvaja te časti, nego kdor je poklican od Boga, kakor tudi Aron.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 5, 'Tako tudi Kristus ni sam sebe počastil, da bi postal veliki duhovnik, nego on, ki mu je govoril: „Sin moj si ti, jaz sem te danes rodil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 6, 'Kakor tudi drugje pravi: „Ti si duhovnik na vek po redu Melhizedekovem“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 7, 'On je v dneh mesa svojega prinašal prošnje in molitve s silnim vpitjem in s solzami k onemu, ki ga je mogel oteti smrti, in je bil uslišan zavoljo svoje vdanosti Bogu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 8, 'in se je, dasi Sin, učil po trpljenju pokorščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 9, 'In tako je postal popoln in večnega zveličanja ustanovitelj njim vsem, ki so mu poslušni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 10, 'in Bog ga proglasil za velikega duhovnika po redu Melhizedekovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 11, 'O tem bi nam bilo mnogo govoriti, a je težko pojasniti, ker ste počasni postali na sluhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 12, 'Zakaj po času bi morali biti že učitelji, pa je treba, da vas kdo zopet uči, katere so začetne prvine izrekov Božjih, in postali ste mleka potrebni in ne močne hrane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 13, 'Kajti vsak, kdor dobiva mleka, je nevešč besedi pravičnosti, ker je dete.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 5, 14, 'Popolnim pa se daje močna hrana, namreč njim, ki imajo po izkušnji vajene čute, da razločujejo dobro in hudo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 1, 'Zato se, pustivši začetek besede Kristusove, obrnimo k popolnosti, da ne polagamo zopet temelja z izpreobrnjenjem od mrtvih del in z vero v Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 2, 'z naukom o krstih in o pokladanju rok in o vstajenju mrtvih in o večni sodbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 3, 'In to bomo storili, ako le Bog privoli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 4, 'Kajti nemogoče je take, ki so bili enkrat razsvetljeni in so okusili dar nebeški in so postali deležni svetega Duha');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 5, 'in okusili dobro besedo Božjo in prihodnjega sveta moči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 6, 'in so odpadli, zopet obnoviti v izpokorjenje, ker sami zase iznova križajo Sina Božjega in ga očitno sramote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 7, 'Kajti zemlja, katera pije dež, ki često nanjo pada, in rodi koristno zelišče tistim, zaradi katerih se tudi obdeluje, dobiva blagoslov od Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 8, 'Ako pa rodi trnje in osat, je zavržena in blizu prokletja, ki mu je konec požig.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 9, 'Prepričani pa smo o vas, ljubljeni, da ste v boljšem stanju, ki pospešuje vaše zveličanje, čeprav tako govorimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 10, 'Kajti Bog ni krivičen, da bi pozabil delo vaše in ljubezen, ki ste jo pokazali do imena njegovega s tem, da ste služili svetim in še služite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 11, 'Želimo pa, da vsak izmed vas kaže isto gorečnost, da ohrani popolno gotovost upanja do konca:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 12, 'da se ne polenite, temuč postanete posnemalci njih, ki so po veri in stanovitnosti podedovali obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 13, 'Kajti ko je Bog dal Abrahamu obljubo, je prisegel pri samem sebi, ker ni imel pri kom večjem priseči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 14, 'govoreč: „Resnično, blagoslavljaje te bom blagoslovil in množeč te bom množil“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 15, 'In tako je Abraham, stanovitno čakajoč, dosegel izpolnitev obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 16, 'Ljudje namreč prisegajo pri kom večjem, in vsakega njih prepira konec je prisega v potrditev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 17, 'Zato je tudi Bog, hoteč tolikanj obilneje pokazati dedičem obljube neizpremenljivost sklepa svojega, porabil za sredstvo prisego,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 18, 'da bi po teh dveh neizpremenljivih rečeh, v katerih ni mogoče, da bi Bog lagal, imeli krepko tolažilo mi, ki smo pribežali oprijet se ponujenega nam upanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 19, 'ki ga imamo kakor sidro duše, ki je zanesljivo in trdno in prodira v notranje svetišče za pregrinjalo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 6, 20, 'kamor je kot predhodnik za nas vstopil Jezus, postavši po redu Melhizedekovem veliki duhovnik na vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 1, 'Ta Melhizedek namreč, kralj v Salemu, duhovnik Boga Najvišjega, ki je bil naproti prišel Abrahamu, vračajočemu se s poboja kraljev, in ga blagoslovil,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 2, 'ki mu je tudi Abraham podelil desetino od vsega, (njegovo ime se najprej tolmači: ‚kralj pravičnosti‘, potem pa tudi kralj Salema, to je: ‚kralj miru‘,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 3, 'brez očeta je, brez matere, brez rodopisa, nima niti začetka dni niti življenja konca, prispodobljen pa je Sinu Božjemu), ostaja duhovnik za vedno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 4, 'Preudarite pa, kako velik je bil ta, ki mu je Abraham očak dal desetino od najboljšega plena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 5, 'In tisti sinovi Levijevi, ki prejemajo duhovništvo, imajo zapoved, odesetiniti ljudstvo po postavi, to je: brate svoje, dasi so ti tudi izšli iz Abrahamovega ledja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 6, 'on pa, ki ni iz njih rodu, je odesetinil Abrahama in blagoslovil njega, ki je imel obljube.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 7, 'A brez vsakega ugovora blagoslavlja večji manjšega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 8, 'In tukaj jemljejo desetine umrjoči ljudje, tam pa on, o katerem se priča, da živi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 9, 'In takorekoč po Abrahamu je bil sam Levi, ki prejema desetine, odesetinjen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 10, 'kajti bil je še v očetovih ledjih, ko mu je prišel Melhizedek naproti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 11, 'Ako se je torej dosegla popolnost po Levijem duhovništvu (na podlagi tega je namreč ljudstvo prejelo postavo), kaka potreba je bila še, da se postavi drugačen duhovnik „po redu Melhizedekovem“in se ne imenuje po redu Aronovem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 12, 'Kajti če se premeni duhovništvo, nastane neogibno tudi izpremena postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 13, 'Ta namreč, ki se o njem to pravi, je iz drugega rodu, iz katerega ni nihče služil oltarju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 14, 'Kajti znano je, da se je rodil Gospod naš iz Jude, kateremu rodu ni Mojzes ničesar govoril zastran duhovništva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 15, 'In ta premena se še jasneje vidi, če je po podobi Melhizedekovi postavljen drugačen duhovnik,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 16, 'ki ni postal duhovnik po pravilu mesene zapovedi, temuč po moči neminljivega življenja;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 17, 'kajti priča se o njem: „Ti si duhovnik na vekomaj po redu Melhizedekovem“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 18, 'S tem je torej odpravljena prejšnja zapoved, ker je bila slabotna in nekoristna,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 19, '(kajti postava ni storila ničesar popolnega), vpeljano pa je boljše upanje, po katerem se bližamo Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 20, 'In v kolikor to ni brez prisege');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 21, '(oni namreč so postali duhovniki brez prisege, ta pa s prisego po njem, ki je rekel: „Prisegel je Gospod in ne bo se kesal: Ti si duhovnik na vek po redu Melhizedekovem“),');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 22, 'toliko boljše zaveze porok je postal Jezus.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 23, 'In onih je mnogo postalo duhovnikov, ker je smrt branila enemu vedno ostati;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 24, 'ta pa, ker ostane na vekomaj, ima duhovništvo nepremenljivo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 25, 'Zato more tudi popolnoma rešiti tiste, ki se po njem bližajo Bogu, ker vedno živi, da se poteguje zanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 26, 'Kajti tak velik duhovnik se nam je tudi spodobil: svet, nedolžen, brezmadežen, ločen od grešnikov in vzvišen nad nebesa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 27, 'ki mu ni vsak dan potreba, kakor onim velikim duhovnikom, darovati žrtve najprej za svoje, potem za ljudstva grehe: kajti to je storil enkrat za vselej, ko je samega sebe daroval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 7, 28, 'Postava namreč postavlja za velike duhovnike ljudi, podvržene slabostim, beseda prisege, storjene šele po postavi, pa Sina, popolnoma dovršenega za vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 1, 'Poglavitno pa pri tem, o čemer govorimo, je to: takega imamo velikega duhovnika, ki je sedel na desnico prestola veličastva v nebesih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 2, 'in je oskrbnik svetišča in šatora pravega, ki ga je postavil Gospod in ne človek.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 3, 'Kajti vsak veliki duhovnik je postavljen, da prinaša dari in žrtve; zato je potreba, da ima tudi ta kaj, kar bi prinašal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 4, 'Ako bi bil namreč na zemlji, bi še duhovnik ne bil, ker so tu duhovniki, ki dari prinašajo po postavi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 5, 'Oni služijo podobi in senci stvari nebeških; kakor je bilo Mojzesu ukazano, ko je napravljal šator; kajti: „Glej“, veli, „da narediš vse po zgledu, pokazanem ti na gori“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 6, 'Sedaj pa je Jezus dobil tem odličnejšo službo, kolikor boljša je zaveza, ki je njen srednik, ki je zakonito ustanovljena tudi na boljših obljubah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 7, 'Ako bi namreč ona prva zaveza bila brez pogreška, ne bi se iskalo mesto drugi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 8, 'Kajti grajajoč jim pravi: „Glej, dnevi pridejo, govori Gospod, in s hišo Izraelovo in s hišo Judovo sklenem novo zavezo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 9, 'ne po zavezi, ki sem jo storil ž njih očeti, ko sem jih prijel za roko, da bi jih izpeljal iz zemlje Egiptovske; ker oni niso ostali v zavezi moji, in jaz sem jih vnemar pustil, govori Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 10, 'Kajti to je zaveza, ki jo sklenem s hišo Izraelovo po tistih dneh, govori Gospod: Postave svoje dam v njih misli in v njih srca jih napišem, in bodem jim za Boga, in oni mi bodo za ljudstvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 11, 'In naj ne uče vsak svojega bližnjega in vsak svojega brata, rekoč: Spoznaj Gospoda! zakaj poznali me bodo vsi, od njih malega do njih velikega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 12, 'Kajti milosten bodem njih krivicam in njih grehov in pregreškov se ne bom spominjal več“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 8, 13, 'Ko pravi: „novo zavezo“, je proglasil prvo za staro; kar pa se stara in je zastarelo, se bliža koncu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 1, 'Imela je pač tudi prva zaveza predpise za službo božjo in pozemeljsko svetišče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 2, 'Šator namreč je bil napravljen – prvi, v katerem so bili svečnik in miza in razpostava kruhov; ta se imenuje Sveto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 3, 'Za drugim zagrinjalom pa je bil šator, imenovan Najsvetejše,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 4, 'imajoč zlato kadilnico in skrinjo zaveze, od vseh strani z zlatom okovano, v kateri je bil zlati vrč z mano in zeleneča palica Aronova in plošči zaveze,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 5, 'nad njo pa keruba slave, obsenčujoča pokrov sprave..., o čemer sedaj ni govoriti podrobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 6, 'Ker je torej to tako napravljeno, hodijo v prvi šator vedno duhovniki opravljat službo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 7, 'v drugi šator pa enkrat na leto sam veliki duhovnik, a ne brez krvi, ki jo prinaša zase in za grehe nevednosti ljudstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 8, 'S tem sveti Duh kaže, da pot do svetišča ni še razodeta, dokler stoji prvi šator,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 9, 'ki je podoba za sedanjo dobo; v katerem se darujejo darovi in žrtve, ki ne morejo v vesti popolnoma pomiriti tistega, ki opravlja službo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 10, 'ker so samo mesene naredbe (z jedili in pijačami ter z različnim umivanjem vred) naložene do časa poprave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 11, 'Kristus pa je nastopil kot veliki duhovnik prihodnjih dobrot in je šel skozi večji in popolnejši šator, ki ni z roko narejen, to je, ki ni tega stvarjenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 12, 'tudi ne po krvi kozlov in telet, ampak po svoji lastni krvi, enkrat za vselej v svetišče, ko je bil pridobil večno rešitev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 13, 'Kajti če bikov in kozlov kri in junice pepel, ki pokropi onečiščene, posvečuje za čistost mesa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 14, 'kolikanj bolj bo kri Kristusa, ki je po Duhu večnem daroval samega sebe brez madeža Bogu, očistila vest vašo mrtvih del, da služite Bogu živemu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 15, 'In zato je nove zaveze srednik: da dobé, ko se je smrt zgodila za odrešenje prestopkov, storjenih za prve zaveze, obljubo večne dediščine tisti, ki so poklicani.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 16, 'Kajti kjer je oporoka, je treba, da nastopi oporočnikova smrt;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 17, 'zakaj oporoka je šele pri mrtvih veljavna, ker nikdar nima moči, dokler živi oporočnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 18, 'Zato tudi prva zaveza ni bila posvečena brez krvi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 19, 'Ko je bil namreč Mojzes vsako zapoved po postavi oznanil vsemu ljudstvu, je vzel kri telet in kozlov z vodo in škrlatno volno in z izopom ter je pokropil knjigo samo in vse ljudstvo, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 20, '„To je kri zaveze, ki jo je vam Bog zapovedal“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 21, 'In tudi šator in vse orodje službe božje je enako pokropil s krvjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 22, 'In s krvjo se skoraj vse očišča po postavi, in brez prelitja krvi se ne zgodi odpuščenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 23, 'Potrebno je torej bilo, da se ‚podobe nebeških stvari‘očiščajo s takimi, nebeške stvari same pa z boljšimi žrtvami mimo teh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 24, 'Kajti Kristus ni šel v svetišče z roko narejeno, ki je le pravega svetišča podoba, temuč v samo nebo, da se sedaj kaže obličju Božjemu za nas;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 25, 'tudi ni šel samega sebe večkrat darovat, kakor veliki duhovnik prihaja v svetišče vsako leto s tujo krvjo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 26, '(sicer bi bil moral mnogokrat trpeti od ustanovitve sveta): sedaj pa na konci vekov se je enkrat prikazal v izbrisanje greha po žrtvi svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 27, 'In kakor je človeku namenjeno enkrat umreti, potem pa sodba,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 9, 28, 'tako se je tudi Kristus enkrat daroval, da bi odvzel mnogih grehe, v drugič pa se prikaže ne zaradi greha, temuč v zveličanje njim, ki ga pričakujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 1, 'Kajti ker ima postava le senco prihodnjih dobrot, ne prave podobe stvari, ne more vsako leto z istimi žrtvami, ki jih neprenehoma darujejo, nikdar popolne storiti teh, ki ž njimi pristopajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 2, 'Ali bi jih sicer ne nehali darovati, ker bi službo opravljajoči, enkrat očiščeni, več ne imeli zavesti grehov?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 3, 'A prav s temi žrtvami se obnovi spomin grehov vsako leto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 4, 'Nemogoče je namreč, da bi kri bikov in kozlov odvzemala grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 5, 'Zato govori Kristus, prihajajoč na svet: „Žrtve in daru nisi hotel, telo pa si mi pripravil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 6, 'žgalne daritve in daritve za grehe ti niso bile po volji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 7, 'tedaj sem rekel: Glej, prihajam (na čelu knjige je pisano o meni), da izpolnim, o Bog, voljo tvojo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 8, 'Govoreč prej: „Žrtev in darov in žgalnih daritev in daritev za greh“(ki se vendar darujejo po postavi) „nisi hotel in ti niso bile po volji“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 9, 'je rekel dalje: „Glej, prihajam, da izpolnim voljo tvojo“. Prvo odpravlja, da postavi drugo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 10, 'Na podlagi te volje smo posvečeni po daritvi telesa Jezusa Kristusa enkrat za vselej.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 11, 'In vsak duhovnik stoji vsak dan v službi in daruje večkrat iste žrtve, ki nikdar ne morejo odvzeti grehov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 12, 'on pa je potem, ko je daroval eno samo žrtev za grehe, sedel za večno na desnico Božjo');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 13, 'in čaka odslej, da bodo sovražniki njegovi položeni za podnožje nogam njegovim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 14, 'Kajti z eno daritvijo je za večno popolne storil tiste, ki se posvečujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 15, 'Izpričuje nam pa to tudi sveti Duh; ko je bil namreč rekel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 16, '„To je zaveza, ki jo bom sklenil ž njim po tistih dneh“, govori Gospod: „Postave svoje dam v njih srca in v njih misli jih zapišem');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 17, 'in njih grehov in pregreškov se ne bom spominjal več“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 18, 'Kjer je pa odpuščenje teh, ni več daritve za grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 19, 'Ker imamo torej, bratje, trdno zaupanje, da nam je prost vhod v svetišče po krvi Jezusovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 20, 'kateri vhod nam je posvetil kakor novo in živo pot skozi zagrinjalo, to je meso svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 21, 'in ker imamo duhovnika velikega čez hišo Božjo:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 22, 'pristopimo z resničnim srcem, v popolni gotovosti vere, v srcih pokropljeni in očiščeni slabe vesti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 23, 'in po telesu umiti s čisto vodo. Držimo se izpovedi svojega upanja neomahljivo; kajti zvest je on, ki je obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 24, 'In opazujmo se med seboj, da se izpodbujamo k ljubezni in k dobrim delom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 25, 'in ne opuščajmo zbora svojega, kakor je nekaterim navada, marveč opominjajmo drug drugega, in to tolikanj bolj, kolikor bolj vidite, da se bliža dan Gospodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 26, 'Ako namreč prostovoljno grešimo, potem ko smo prejeli spoznanje resnice, ni nobene žrtve več za grehe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 27, 'ampak neko strašno pričakovanje sodbe in gorečnost ognja, ki bo ugonabljal nasprotnike.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 28, 'Kdor prelomi postavo Mojzesovo, umre brez usmiljenja po izpovedbi dveh ali treh prič:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 29, 'koliko hujšo kazen, menite, zasluži, kdor je Sina Božjega teptal in zaničeval kri zaveze, ki je bil ž njo posvečen, in grdil Duha milosti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 30, 'Poznamo namreč njega, ki je rekel: „Moje je maščevanje, jaz bom povračal, govori Gospod“; in zopet: „Gospod bo sodil ljudstvo svoje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 31, 'Strašno je pasti v roke živega Boga!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 32, 'Spominjajte se pa prejšnjih dni, v katerih ste, potem ko ste bili razsvetljeni, prestali mnogi boj trpljenja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 33, 'zdaj v sramoti in stiski na ogled postavljeni, zdaj tesno združeni ž njimi, ki se jim je enako godilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 34, 'Kajti tudi z jetniki ste imeli sočutje in rop imetja svojega ste z veseljem trpeli, vedoč, da imate boljše imetje in stalno v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 35, 'Ne mečite torej od sebe srčne zaupnosti svoje, ki ima veliko plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 36, 'Stanovitnosti vam je namreč potreba, da dobite obljubo, storivši voljo Božjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 37, 'Kajti „malo, malo še, in pride on, ki ima priti, in ne bo se mudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 38, 'Pravičnik moj bo pa živel iz vere“, in: „Ako se umakne, duši moji ne bode po volji“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 10, 39, 'Mi pa nismo izmed onih, ki se umikajo in se pogube, temuč ki verujejo in ohranijo dušo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 1, 'Vera pa je trdno pričakovanje tistega, kar upamo, uverjenje o stvareh, ki jih ne vidimo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 2, 'Po njej so namreč predniki prejeli pričanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 3, 'Po veri umemo, da so bili svetovi osnovani po besedi Božji, tako da ni iz prikazujočega se postalo, kar je sedaj vidno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 4, 'Po veri je daroval Abel Bogu boljšo žrtev mimo Kajna; po njej je bil izpričan za pravičnega, ker je Bog sam pričal o njegovih darovih, in po njej govori še, dasi je umrl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 5, 'Po veri je bil Enoh umaknjen, da ni videl smrti, in „ni ga bilo najti, ker ga je Bog umaknil“; kajti preden je bil umaknjen, je dobil pričanje, da „je Bogu po volji“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 6, 'Brez vere pa je nemogoče biti Bogu po volji; kajti kdor se bliža Bogu, mora verovati, da je Bog in da bo plačevalec tistim, ki ga iščejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 7, 'Po veri je prejel Noe vest po tem, kar se še ni videlo, in boječ se, je napravil barko v rešenje hiše svoje; po njej je obsodil svet in postal dedič pravičnosti, ki je po veri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 8, 'Po veri je slušal Abraham, ko je bil poklican, naj odide v kraj, ki ga je imel dobiti v dediščino, in odšel je, ne vedoč, kam pride.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 9, 'Po veri se je preselil v deželo obljube kakor v tujino in stanoval v šatorih z Izakom in Jakobom, sodedičema iste obljube;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 10, 'čakal je namreč mesta, stoječega na trdnih temeljih, katerega zidar in stvarnik je Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 11, 'Po veri je tudi sama Sara zadobila moč, ustanoviti zarod, in je rodila zunaj prave dobe starosti, ker je za zvestega imela njega, ki je bil obljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 12, 'Zato se jih je tudi od enega, in to takega, čigar telo je bilo omrtvelo, rodilo mnogo kakor zvezd na nebu in brez števila kakor peska ob morskem bregu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 13, 'V veri so umrli ti vsi in niso prejeli izpolnitve obljub, temuč so jih od daleč gledali, jih pozdravljali in pripoznavali, da so tujci in priseljenci na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 14, 'Kateri namreč tako govore, kažejo, da iščejo domovine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 15, 'In ko bi se bili spominjali tiste, iz katere so bili izšli, bi bili imeli časa povrniti se.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 16, 'Sedaj pa hrepene po boljši, to je po nebeški domovini. Zato se jih Bog ne sramuje, imenovati se njih Boga; zakaj pripravil jim je mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 17, 'Po veri je daroval Abraham Izaka, ko je bil izkušan, in edinorojenca je daroval on, ki je bil sprejel obljube,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 18, 'kateremu se je govorilo: „V Izaku se ti bo imenovalo seme“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 19, 'ker je pomislil, da more Bog zbujati tudi iz mrtvih; zaradi tega ga je tudi prejel kakor od mrtvih obujenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 20, 'Po veri je blagoslovil Izak Jakoba in Ezava tudi za prihodnjost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 21, 'Po veri je Jakob umiraje blagoslovil obadva sinova Jožefova in „je molil, sklonjen ob vrh palice svoje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 22, 'Po veri je Jožef na smrtni postelji spominjal na izhod sinov Izraelovih in je naročal za kosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 23, 'Po veri so Mojzesa, ko je bil rojen, njegovi roditelji skrivali tri mesece, ker so videli, da je dete zalo, in niso se bali ukaza kraljevega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 24, 'Po veri se je Mojzes, ko je bil odrastel, branil imenovan biti sin hčere Faraonove,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 25, 'ker je rajši hotel zlo trpeti z ljudstvom Božjim nego imeti začasen užitek od greha,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 26, 'in je imel sramoto Kristusovo za večje bogastvo nad zaklade egiptovske: kajti gledal je na povračilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 27, 'Po veri je zapustil Egipt, ne boječ se jeze kraljeve; stanoviten je bil namreč, kakor da bi videl Nevidnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 28, 'Po veri je napravil velikonočno jagnje in škropljenje s krvjo, da bi se moritelj ne dotaknil njih prvorojencev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 29, 'Po veri so Izraelci prešli Rdeče morje kakor po suhem; Egipčani pa so bili, poskusivši to, pogoltnjeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 30, 'Po veri je padlo zidovje Jeriha po sedemdnevnem obkroževanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 31, 'Po veri nečistnica Rahab ni poginila z nevernimi, ker je sprejela oglednike v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 32, 'In kaj bi še govoril? Časa namreč mi bo primanjkalo, ko bi pripovedoval o Gideonu, Baraku in Samsonu in Jefteju, Davidu in Samuelu in prorokih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 33, 'ki so po veri premagovali kraljestva, izvrševali pravičnost, dobivali obljube, mašili levom žrela,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 34, 'gasili ognja moč, ubežavali osti meča, v slabosti prejemali moč, junaki postajali v vojski, odbijali napade tujcev;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 35, 'žene so dobivale mrtve svoje od mrtvih obujene; drugi pa so bili mučeni in niso marali oproščenja, da zadobe boljše vstajenje;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 36, 'drugi pa so trpeli zasramovanje in bičanje, vrhu tega pa spone in ječe;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 37, 'bili so kamenani, izkušani, razrezani, umrli so smrti z mečem; hodili so v ovčjih in kozjih kožah, v potrebi, v stiskah in težavah');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 38, '(njih ni bil svet vreden!), po puščavah tavajoč in po gorah in brlogih in podzemeljskih jamah.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 39, 'In vsi ti, dobivši pričanje po veri, niso prejeli izpolnitve obljube,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 11, 40, 'ker je bil Bog nekaj boljšega določil za nas, da bi oni ne dosegli popolnosti brez nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 1, 'Zatorej tudi mi, ker imamo tak oblak prič okrog sebe, vrzimo raz sebe vsako breme in greh, ki nas lahko oklene, in tecimo s potrpežljivostjo v naloženem nam boju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 2, 'ozirajoč se v začetnika in dovrševalca vere, v Jezusa, ki je za namenjeno mu veselje pretrpel križ, ne meneč se za sramoto, in je sedel na desnico Božjega prestola.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 3, 'Pomislite vendar nanj, ki je prestal od grešnikov toliko nasprotovanja proti sebi, da ne omagate, pešajoč v dušah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 4, 'Niste se še do krvi ustavljali v boju z grehom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 5, 'in pozabili ste tolažbe, ki govori z vami kakor s sinovi: „Sin moj, ne preziraj strahovanja Gospodovega in ne omaguj, ko te kara.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 6, 'Kogar namreč ljubi Gospod, tega strahuje in tepe vsakega sina, katerega sprejema“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 7, 'Ako trpite, je vam v odgojo. Bog se vam kaže kakor otrokom; kajti kje je sin, ki ga ne bi strahoval oče?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 8, 'Ako ste pa brez strahovanja, ki so ga deležni postali vsi, torej ste nezakonski otroci in ne sinovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 9, 'Dalje, ako smo imeli telesne roditelje, ki so nas strahovali, in smo se jih bali, ali se ne bomo mnogo bolj pokorili Očetu duhov, da bomo živeli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 10, 'Oni so nas namreč strahovali za malo dni, kakor se jim je prav zdelo, ta pa nam v korist, da bodemo deležni svetosti njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 11, 'Vsako strahovanje seveda se nam za sedaj ne zdi veselje, ampak žalost, pozneje pa daje njim, ki jih je vadilo, miru poln sad pravičnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 12, 'Zato „dvignite omagujoče roke in šibeča se kolena“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 13, 'in „ravne tire delajte svojim nogam“, da se hromo še bolj ne pohabi, temuč ozdravi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 14, 'Iščite miru z vsemi in posvečenja, brez katerega ne bo nihče videl Gospoda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 15, 'pazite, da se kdo ne odvrne od milosti Božje in da ne požene kaka korenina bridkosti in ne dela napotja in jih mnogo ne skruni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 16, 'da ne bode kdo nečistnik ali skrunilec svetega kakor Ezav, ki je za eno jed prodal prvorojenstvo svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 17, 'Kajti veste, da je bil tudi, ko je hotel pozneje zadobiti blagoslov, zavržen (ni dosegel namreč izpremene misli), dasi ga je želel s solzami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 18, 'Kajti niste pristopili k dotakljivi gori in h gorečemu ognju in k oblačju in temi in nevihti');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 19, 'in k trombe donenju in glasu besed, katerega poslušalci so prosili, da se jim nobena beseda več ne govori');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 20, '(niso namreč mogli prenesti ukaza: „Tudi če se žival dotakne gore, bodi s kamenjem pobita“,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 21, 'in tako strašna je bila prikazen, da je Mojzes rekel: V strahu sem in trepetu):');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 22, 'temuč pristopili ste h gori Sionu in k mestu Boga živega, Jeruzalemu nebeškemu, k nebrojni množici angelov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 23, 'k velikemu zborovanju in cerkvi prvorojencev, zapisanih v nebesih, in k Bogu, sodniku vseh, in k duhovom pravičnih, ki so dosegli popolnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 24, 'in k sredniku nove zaveze, Jezusu, in h krvi pokropljenja, ki govori boljše kakor Abelova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 25, 'Glejte, da se ne branite govorečega; kajti če niso ubežali kazni oni, ki so se branili njega, ki je oznanjal Božje ukaze na zemlji, veliko manj ubežimo mi, ako se obračamo od njega, ki govori z nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 26, 'Glas njegov je potresel zemljo tedaj, sedaj pa je obljubil, govoreč: „Še enkrat potresem ne samo zemlje, ampak tudi nebo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 27, 'To: „še enkrat“pomeni premembo tistega, kar je bilo potreseno kakor kaj narejenega, da ostane, kar je nepotreseno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 28, 'Zato, ker prejemamo kraljestvo nepotresljivo, imejmo milost, po kateri služimo po volji Bogu, s svetim strahom in grozo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 12, 29, 'kajti tudi „naš Bog je ogenj, ki uničuje“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 1, 'Bratoljubje ostani med vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 2, 'Gostoljubnosti ne pozabite: ž njo so namreč nevedoma nekateri vzeli pod streho angele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 3, 'Spominjajte se jetnikov, kakor da ste sojetniki, teh, ki se jim krivica godi, kakor da tudi sami še živite v telesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 4, 'Častit bodi zakon pri vseh in postelja neoskrunjena; kajti nečistnike in prešeštnike bo sodil Bog.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 5, 'Življenje bodi brez lakomnosti; zadovoljni bodite s tem, kar imate; kajti on je rekel: „Ne odtegnem se ti in ne zapustim te“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 6, 'Tako da lahko smelo govorimo: „Gospod mi je pomočnik, ne bom se bal; kaj mi bo storil človek?“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 7, 'Spominjajte se vodnikov svojih, ki so vam oznanjali besedo Božjo; ozirajoč se v izhod njih življenja, posnemajte njih vero.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 8, 'Jezus Kristus je isti včeraj in danes in na veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 9, 'Mnogoterim in tujim naukom se ne dajte motiti; kajti dobro je, da se srce utrjuje z milostjo, ne z jedmi, od katerih niso imeli koristi, ki so se ž njimi pečali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 10, 'Imamo oltar, ki ž njega ne smejo jesti, kateri služijo šatoru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 11, 'Kajti katerih živali kri nosi veliki duhovnik za grehe v svetišče, tistih trupla se sežigajo zunaj šatorišča;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 12, 'zato je tudi Jezus, da bi z lastno krvjo posvetil ljudstvo, trpel zunaj vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 13, 'Zatorej izidimo k njemu ven za šatorišče, noseč sramoto njegovo!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 14, 'Nimamo namreč tu mesta stalnega, temuč iščemo prihodnjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 15, 'Po njem torej prinašajmo vedno hvalno daritev Bogu, to je „sad ustnic“, ki proslavljajo ime njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 16, 'Dobrodelnosti pa in podeljevanja ne zabite: take daritve namreč so Bogu po volji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 17, 'Slušajte voditelje svoje in hodite za njimi, oni namreč so čuvaji dušam vašim kot taki, ki bodo odgovor dajali, da to veseli opravljajo in ne zdihujoč; kajti to bi vam bilo nekoristno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 18, 'Molite za nas; kajti prepričani smo, da imamo dobro vest, ker hočemo pošteno živeti in ravnati v vsem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 19, 'Tolikanj bolj pa vas prosim, da delate to, da vam bom tem hitreje povrnjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 20, 'Bog miru pa, on, ki je od mrtvih nazaj pripeljal velikega pastirja ovac po krvi večne zaveze, Gospoda našega Jezusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 21, 'stori vas popolne v slehernem dobrem delu, da izpolnite voljo njegovo, in delaj v vas, kar je prijetno njemu, po Jezusu Kristusu, ki mu bodi slava na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 22, 'Prosim pa vas, bratje, sprejmite blagovoljno to besedo opominjanja; kajti ob kratkem sem vam pisal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 23, 'Vedite, da je brat Timotej oproščen, s katerim, ako skoraj pride, vas bova videla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 24, 'Pozdravite vse vodnike svoje in vse svete! Pozdravljajo vas oni iz Italije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (58, 13, 25, 'Milost z vami vsemi! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 1, 'Jakob, Boga in Gospoda Jezusa Kristusa hlapec, pozdravlja dvanajstere rodove, ki so razkropljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 2, 'Zgolj v veselje si štejte, bratje moji, kadar pridete v mnogotere izkušnjave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 3, 'ker veste, da preizkušnja vere vaše rodi stanovitnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 4, 'Stanovitnost pa imej za delo popolno, da bodete popolni in dovršeni, v ničemer pogrešni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 5, 'Če pa ima kdo izmed vas premalo modrosti, naj je prosi Boga, ki vsem daje obilo in nikomur ne oponaša; in dala se mu bo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 6, 'Prosi pa naj v veri in nič ne dvomi; zakaj kdor dvomi, je podoben valu morskemu, ki ga veter žene in premetava.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 7, 'Naj vendar ne misli tisti človek, da kaj dobi od Gospoda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 8, 'mož dvojnih misli, nestanoviten na vseh potih svojih!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 9, 'Ponaša pa naj se nizki brat v visokosti svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 10, 'a bogati v ponižanju svojem, kajti mine kakor trave cvet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 11, 'Vzide namreč solnce z vročino in posuši travo, in njen cvet odpade in lepota lica njenega izgine: tako tudi bogatin zvene v svojih podjetjih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 12, 'Blagor možu, ki pretrpi izkušnjavo; ker ko bo preizkušen, prejme venec življenja, ki ga je obljubil Gospod tem, ki ga ljubijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 13, 'Nihče naj ne reče, ko je v izkušnjavi: Bog me izkuša; zakaj Bog ne more biti izkušan v hudo, sam pa tudi ne izkuša nikogar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 14, 'Sleherni pa je izkušan, ko ga lastne želje vlečejo in vabijo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 15, 'potem, ko želja spočne, rodi greh, greh pa, ko je dovršen, rodi smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 16, 'Ne tavajte, bratje moji ljubljeni!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 17, 'Vsak dober dar in vsako popolno darilo je od zgoraj in prihaja od Očeta luči, pri katerem ni izpremembe ali sence vsled obrata svetil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 18, 'Iz svoje volje nas je rodil po besedi resnice, da bodimo neka prvina stvari njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 19, 'Veste to, bratje moji ljubljeni. Bodi pa vsak človek hiter za poslušanje, počasen za govorjenje, počasen za jezo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 20, 'kajti jeza človekova ne dela pravičnosti Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 21, 'Zato odloživši sleherno nesnago in obilnost hudobnosti, v krotkosti sprejmite vsajeno besedo, ki more rešiti duše vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 22, 'Bodite pa delavci besede in ne samo poslušalci, ki sami sebe slepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 23, 'Kajti če je kdo poslušalec besede, ne pa delavec, ta je podoben možu, ki ogleduje v zrcalu svojega rojstva obličje:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 24, 'pogleda se namreč in odide, in hitro pozabi, kakšen da je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 25, 'Kdor pa prav pogleda v popolno postavo, postavo svobode, in pri njej vztraja ter ne pozabi, kar sliši, ampak dejanski izvršuje to, ta bode blažen v dejanju svojem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 26, 'Če meni kdo, da služi Bogu, pa ne brzda jezika svojega, temuč vara srce svoje, njegovo bogoslužje je ničevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 1, 27, 'Bogoslužje čisto in neoskrunjeno pred Bogom in Očetom je to: skrbeti za sirote in vdove v njih stiski in se ohraniti neomadeževanega od sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 1, 'Bratje moji, v veri našega Gospoda slave, Jezusa Kristusa, ne ozirajte se na to, kdo je kdo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 2, 'Ako pride namreč v vaš zbor mož z zlatim prstanom, v sijajni obleki, pride pa tudi ubožec v umazani obleki,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 3, 'in pogledate njega, ki ima sijajno obleko, in mu rečete: Ti sedi sem lepo, in ubožcu rečete: Ti stoj tam ali pa sedi sem pod podnožje moje –');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 4, 'niste li napravili razločka med seboj in ste postali sodniki po slabih mislih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 5, 'Čujte, bratje moji ljubljeni: Ni si li Bog izbral ubožcev pred svetom, da bodo bogati v veri in dediči kraljestva, ki ga je obljubil njim, ki ga ljubijo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 6, 'Vi pa ste zaničevali ubožca. Ali niso bogatini, ki vas zatirajo, in niso li oni, ki vas vlačijo pred sodbe?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 7, 'Niso li oni, ki preklinjajo slavno ime, ki je bilo klicano nad vami?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 8, 'Toda če res izpolnjujete kraljevo postavo, po pismu: „Ljubi bližnjega svojega kakor sebe“, prav delate;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 9, 'če pa gledate na zunanjost, delate greh, in postava vam izpričuje, da ste prestopniki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 10, 'Kajti kdor bi izpolnjeval vso postavo, pa bi se pregrešil zoper eno zapoved, je postal kriv vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 11, 'On namreč, ki je rekel: „Ne prešeštvuj“, je tudi rekel: „Ne ubijaj“; če pa ne prešeštvuješ, a ubijaš, si postal prestopnik postave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 12, 'Tako govorite in tako ravnajte kakor ljudje, ki boste sojeni po postavi svobode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 13, 'Kajti sodba bode neusmiljena njemu, ki ni delal usmiljenja; usmiljenje se hvali zoper sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 14, 'Kaj pomaga, bratje moji, če kdo pravi, da ima vero, del pa nima? More li ga ta vera rešiti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 15, 'Ako je brat nag ali sestra in pogrešata vsakdanje hrane,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 16, 'pa jima kdo izmed vas reče: Pojdita v miru, ogrejta se in nasitita! A jima ne podelite, kar je potrebno telesu, kaj to pomaga?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 17, 'Tako tudi vera, ako nima del, je mrtva sama ob sebi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 18, 'Ali poreče kdo: Ti imaš vero, in jaz imam dela; pokaži mi vero svojo brez del, in jaz ti pokažem vero iz svojih del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 19, 'Ti veruješ, da je Bog eden; prav delaš. Tudi zli duhovi to verujejo in groza jih je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 20, 'Hočeš pa vedeti, človek ničemurni, da je vera brez del mrtva?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 21, 'Ali ni bil Abraham, oče naš, opravičen iz del, ko je daroval Izaka, sina svojega, na oltarju?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 22, 'Vidiš torej, da je vera sodelovala z deli njegovimi, in iz del je bila vera popolna,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 23, 'in izpolnilo se je pismo: „Abraham pa je veroval Bogu, in vštelo se mu je za pravičnost“in „prijatelj Božji“je bil imenovan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 24, 'Vidite, da se iz del opravičuje človek in ne samo iz vere.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 25, 'Istotako se li ni tudi Rahab nečistnica opravičila iz del, ko je sprejela poslanca in ju odpravila po drugi poti?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 2, 26, 'Kakor je namreč telo brez duha mrtvo, tako je tudi vera brez del mrtva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 1, 'Ne bodite mnogi učitelji, bratje moji, ker veste, da prejmemo težjo sodbo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 2, 'V mnogem namreč napačno delamo vsi. Če kdo v besedi ne stori napačno, ta je popoln mož, zmožen brzdati tudi vse telo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 3, 'Ako devamo konjem uzde v gobce, da so nam poslušni, vladamo tudi ves njih život.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 4, 'Glej, tudi ladje, če so še tako velike in jih silni vetrovi gonijo, obrača i najmanjše krmilo, kamorkoli hoče vodnikova namera.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 5, 'Tako je tudi jezik majhen ud in se veliko ponaša. Glej, majhen ogenj, kolikšen gozd zažge!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 6, 'Tudi jezik je ogenj; kot svet krivice se kaže jezik med udi našimi, ki oskrunja vse telo in zažiga kolo življenja, njega pa zažiga pekel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 7, 'Kajti sleherno pleme zveri in ptičev, golazni in morskih živali kroti in je ukrotil rod človeški,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 8, 'jezika pa ne more ukrotiti noben človek; zlo neukrotno je poln smrtnega strupa!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 9, 'Ž njim blagoslavljamo Gospoda in Očeta in ž njim preklinjamo ljudi, ustvarjene po podobi Božji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 10, 'iz istih ust prihaja blagoslov in kletev. To, bratje moji, se ne sme tako goditi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 11, 'Saj pač studenec iz iste votline ne bruha sladke in grenke vode?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 12, 'More li, bratje moji, smokva roditi olive ali trta smokve? Tudi slana voda ne more delati sladke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 13, 'Kdo je moder in razumen med vami? Kaže naj z lepim vedenjem dela svoja v modri krotkosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 14, 'Če pa imate grenko zavist in sebičnost v srcu svojem, nikar se ne hvalite in ne lažite zoper resnico!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 15, 'To ni modrost, ki prihaja od zgoraj, ampak zemeljska, živalska, vražja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 16, 'Kjer je namreč zavist in sebičnost, tam je nerednost in vse zlo dejanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 17, 'Modrost pa, ki je od zgoraj, je prvič čista, potem miroljubna, nežnočutna, dovzetna, polna usmiljenja in dobrega sadu, dvoma prosta, brez hinavščine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 3, 18, 'Sad pravičnosti pa se seje v miru njim, ki napravljajo mir.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 1, 'Odkod prihajajo vojske in odkod bitke med vami? Ne li odtod, namreč od želj vaših, vojskujočih se v vaših udih?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 2, 'Želite, a nimate; morite in želite zavidno, a ne morete doseči; borite se in vojskujete; nimate, ker ne prosite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 3, 'Prosite, a ne dobite, ker slabo prosite, da bi zapravljali v slah svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 4, 'Prešeštnice, ali ne veste, da je prijateljstvo sveta sovraštvo do Boga? Kdorkoli torej hoče biti svetu prijatelj, postane Bogu sovražnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 5, 'Ali menite, da pismo prazno govori? Zavistno li želi Duh, ki ga je Bog naselil v nas?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 6, 'Daje pa toliko večjo milost. Zato pravi pismo: „Bog se upira prevzetnim, ponižnim pa daje milost“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 7, 'Podložni torej bodite Bogu. Uprite se pa hudiču, in bežal bo od vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 8, 'Približajte se Bogu in približa se vam. Očedite si roke, grešniki, in očistite si srca, ki ste dvojnih misli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 9, 'Čutite svoje gorjé in žalujte in jokajte; smeh vaš naj se izpreobrne v žalovanje in radost v potrtost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 10, 'Ponižajte se pred Gospodom, in on vas poviša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 11, 'Ne obrekujte drug drugega, bratje. Kdor obrekuje brata ali sodi brata svojega, obrekuje postavo in sodi postavo; če pa sodiš postavo, nisi izpolnjevalec postave, ampak sodnik.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 12, 'Eden je zakonodajec in sodnik, ki more rešiti in pogubiti; ti pa kdo si, ki sodiš bližnjega?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 13, 'Dejte torej vi, ki pravite: Danes ali jutri odpotujemo v to mesto in ostanemo ondi eno leto ter bomo tržili in pridobivali,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 14, 'pa ne veste, kaj bode jutri. Kakšno je življenje vaše? Hlap namreč ste, ki se za malo časa prikaže, potem pa izgine.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 15, 'Morali bi govoriti: Ako Gospod hoče, bomo živeli in to ali ono storili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 16, 'Sedaj pa se ponašate v širokoustju svojem; vsako tako ponašanje je hudobno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 4, 17, 'Kdor torej zna dobro delati, pa ne dela, njemu je greh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 1, 'Dejte torej vi, bogatini, jokajte in javkajte nad bedami, ki vas zadenejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 2, 'Bogastvo vaše je strohnelo in oblačila vaša so snedli molji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 3, 'Zlato vaše in srebro je zarjavelo, in njiju rja bode v pričanje zoper vas in bo žrla meso vaše kakor ogenj. Zaklade ste si nabrali v zadnjih dneh!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 4, 'Glejte, plačilo delavcev, ki so poželi polje vaše, pa ste ga jim utrgali, kriči; in vpitje ženjcev je prišlo do ušes Gospoda nad vojskami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 5, 'V požrešnosti ste na zemlji živeli in razkošnosti; srca svoja ste redili v dan klanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 6, 'Obsodili, umorili ste pravičnega, ne ustavlja se vam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 7, 'Bodite torej potrpežljivi, bratje, do prihoda Gospodovega. Glejte, orač pričakuje dragega sadu zemlje, potrpežljiv zanj, dokler ne dobi zgodnjega in poznega dežja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 8, 'Bodite potrpežljivi tudi vi; pokrepčajte srca svoja, ker prihod Gospodov se je približal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 9, 'Ne zdihujte drug zoper drugega, bratje, da ne boste sojeni; glejte, sodnik stoji pred vrati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 10, 'Za zgled trpljenja in potrpežljivosti vzemite, bratje, proroke, ki so govorili v imenu Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 11, 'Glejte, blagrujemo tiste, ki so bili stanovitni v trpljenju. O stanovitnosti Jobovi ste čuli in konec Gospodov ste videli; kajti bogat v usmiljenju je Gospod in milosrčen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 12, 'Predvsem pa, bratje moji, ne prisegajte, ne pri nebu, ne pri zemlji, ne kake druge prisege; vaš ‚da‘pa bodi ‚da‘in ‚ne‘bodi ‚ne‘, da ne zapadete sodbi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 13, 'Trpi li kdo med vami, naj moli. Je li kdo dobre volje, naj prepeva hvalnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 14, 'Je li kdo bolan med vami, naj pokliče k sebi starejšine cerkve, in molijo naj nad njim ter ga mazilijo z oljem v imenu Gospodovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 15, 'In molitev vere bo pomagala bolniku, in Gospod ga ozdravi; in ako je storil grehe, mu bo odpuščeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 16, 'Izpovedujte torej drug drugemu grehe in molite drug za drugega, da ozdravite. Mnogo zmore goreča molitev pravičnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 17, 'Elija je bil človek, podvržen enakim slabostim kakor mi, in v molitvi je molil, naj ne dežuje, in deževalo ni na zemlji tri leta in šest mesecev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 18, 'In zopet je molil, in nebo je dalo dežja in zemlja je rodila sad svoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 19, 'Bratje moji, ako kdo izmed vas zabrede od resnice in ga kdo nazaj pripelje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (59, 5, 20, 'vedi, da kdor nazaj pripelje grešnika s krive poti njegove, reši dušo njegovo iz smrti in pokrije množico grehov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 1, 'Peter, apostol Jezusa Kristusa, izvoljenim tujcem, razkropljenim po Pontu, Galaciji, Kapadociji, Aziji in Bitiniji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 2, 'izvoljenim po previdnosti Boga Očeta, v posvečenju Duha, k pokorščini in pokropljenju s krvjo Jezusa Kristusa: Milost vam in mir naj se pomnoži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 3, 'Hvaljen bodi Bog in Oče Gospoda našega Jezusa Kristusa, ki nas je po obilem usmiljenju svojem prerodil v živo upanje po vstajenju Jezusa Kristusa iz mrtvih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 4, 'v prejem dediščine neminljive in neoskrunjene in nevenljive, shranjene v nebesih za vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 5, 'ki vas moč Božja čuva in po veri ohrani za zveličanje, pripravljeno, da se razodene v poslednjem času.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 6, 'V katerem se radujete, čeprav ste ravnokar nekaj časa (ako je treba) v žalosti po mnogoterih izkušnjavah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 7, 'da se preizkušnja vere vaše, vrednejša nego preizkušnja minljivega, a v ognju izkušenega zlata, izkaže vam v hvalo in čast in slavo pri razodetju Jezusa Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 8, 'ki ga ljubite, dasi ga niste videli, ki ga sedaj ne gledate, a vendar vanj verujete in se v njem radujete z veseljem neizrečnim in polnim slave,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 9, 'prejemajoč konec vere svoje, zveličanje duš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 10, 'O katerem zveličanju so preiskavali in ga izsledovali proroki, ki so prorokovali o milosti vam namenjeni,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 11, 'preiskujoč, za kateri in za kakšen čas je oznanjal Duh Kristusov, ki je bil v njih in je najprej pričal za trpljenja Kristusova in veliko jim sledečo slavo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 12, 'Njim se je razodelo, da tistega niso podajali sebi, ampak vam, kar se vam je sedaj oznanilo po njih, ki so vam propovedovali evangelij v svetem Duhu, poslanem iz nebes; v kar angeli žele gledati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 13, 'Zato opašite ledja razuma svojega, bodite trezni in stavite svoje upanje popolnoma na milost, ki se vam prinaša v razodetju Jezusa Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 14, 'kakor otroci pokorščine se ne ravnajte po prejšnjih željah v času nevednosti svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 15, 'marveč po Svetem, ki vas je poklical, bodite tudi vi sveti v vsem svojem vedenju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 16, 'kajti pisano je: „Sveti bodite, ker sem jaz svet“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 17, 'In če Očeta kličete njega, ki sodi brez licegledja slehernega po njegovem delu, živite v strahu ves čas tujčevanja svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 18, 'vedoč, da niste odkupljeni z minljivimi rečmi, s srebrom ali zlatom, iz praznega življenja svojega, podedovanega od očetov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 19, 'ampak z drago krvjo kakor jagnjeta brez hibe in brez madeža, Kristusa;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 20, 'ki je bil naprej spoznan pred ustanovitvijo sveta, razodel se je pa ob koncu časov zaradi vas,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 21, 'ki po njem verujete v Boga, ki ga je obudil iz mrtvih in mu dal slavo, tako da je vera vaša tudi upanje v Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 22, 'Ker ste očistili duše svoje v pokorščini resnice za nehlinjeno bratoljubje, ljubite se iz čistega srca med seboj iskreno,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 23, 'ker ste prerojeni ne iz minljivega semena, ampak neminljivega, po besedi Božji, ki živi in večno ostane.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 24, 'Kajti „vse meso je kakor trava in vsa slava njegova kakor trave cvet; posuši se trava in cvet ji odpade,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 1, 25, 'beseda Gospodova pa ostane vekomaj“. To pa je beseda blagovestja, ki se vam je oznanila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 1, 'Odloživši torej vso hudobnost in vso zvijačnost in licemerstvo in zavist in vse obrekovanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 2, 'hrepenite kakor novorojena deteta po nepokvarjenem mleku iz besede Božje, da po njem rastete v zveličanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 3, 'če ste res okusili, da je Gospod dobrotljiv.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 4, 'K njemu pristopajoč, kamenu živemu, ki so ga sicer zavrgli ljudje, pri Bogu pa je izvoljen in dragocen,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 5, 'se sezidavate tudi vi kot živi kameni v hišo duhovno, sveto duhovništvo, da darujete duhovne daritve, prijetne Bogu po Jezusu Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 6, 'Kajti pisano je v pismu: „Glej, polagam na Sionu vogelni kamen, izvoljen, dragocen, in kdor veruje vanj, ne bo osramočen“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 7, 'Vam torej, ki verujete, je čast; nevernim pa je „ta kamen, ki so ga zavrgli zidarji, postal za glavo voglu“');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 8, 'in „kamen spotike in skala pohujšanja“; kateri se, ker so nepokorni besedi, spotikajo, za kar so bili tudi postavljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 9, 'Vi pa ste rod izvoljeni, kraljevsko duhovništvo, svet narod, ljudstvo Bogu za last, da oznanjate kreposti njega, ki vas je poklical iz teme v čudovito svetlobo svojo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 10, 'ki nekdaj niste bili ljudstvo, sedaj pa ste ljudstvo Božje, nekdaj ne deležni milosti, sedaj pa pomiloščeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 11, 'Ljubljeni, opominjam vas kot tujce in popotnike, da se zdržujete mesenih poželenj, ki se vojskujejo zoper dušo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 12, 'vedenje vaše med pogani bodi lepo, da bodo v tem, v čemer vas obrekujejo kakor hudodelnike, slavili zaradi vaših dobrih del, ki jih vidijo, Boga v dan obiskovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 13, 'Pokorite se vsaki naredbi človeški zavoljo Gospoda: bodisi kralju kakor najvišjemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 14, 'bodisi poglavarjem kakor od njega poslanim v kaznovanje hudodelnikov in v pohvalo teh, ki delajo dobro.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 15, 'Kajti taka je volja Božja, da z dobrimi deli zavežite jezik nevednosti nespametnih ljudi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 16, 'kakor svobodni, a ne za pokrivalo hudobnosti imajoč svobodo, temveč kakor hlapci Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 17, 'Vse spoštujte, bratovščino ljubite, Boga se bojte, kralja častite!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 18, 'Hlapci, bodite pokorni v vsem strahu gospodarjem, ne samo dobrim in krotkim, ampak tudi osornim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 19, 'Kajti to je milost, ako kdo iz vestnosti do Boga prenaša težave, po krivem trpeč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 20, 'Kakšna namreč hvala, če boste grešeč in zato tepeni trpeli? Ampak če ste, dobro delajoč in pri tem trpeč, stanovitni, to je prijetno pri Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 21, 'Kajti za to ste bili poklicani, ker je tudi Kristus trpel za vas in vam zapustil zgled, da hodite po sledovih njegovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 22, 'on ni storil greha, tudi zvijača se ni našla v ustih njegovih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 23, 'on psovan ni psoval, trpeč ni pretil, temuč vse je prepuščal tistemu, ki sodi pravično;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 24, 'on je grehe naše sam na telesu svojem nesel na les, da bi grehom odmrli in živeli pravičnosti; ž njegovimi ranami ste bili ozdravljeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 2, 25, 'Bili ste namreč kakor ovce tavajoče, ali povrnili ste se zdaj k Pastirju in Škofu duš svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 1, 'Enako žene, pokorne bodite svojim možem, da jih, če kateri niso poslušni besedi, pridobite s svojim vedenjem brez besede,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 2, 'ko vidijo bogaboječe in čisto življenje vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 3, 'Lepotičje vaše ne bodi vnanje, spletanje las in obešanje zlatnine ali oblačenje kril,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 4, 'ampak skriti človek srca, v neminljivem krasu krotkega in mirnega duha, ki je dragocen pred Bogom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 5, 'Tako namreč so se nekdaj dičile tudi svete žene, ki so upale v Boga, podložne svojim možem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 6, 'kakor je bila Sara poslušna Abrahamu, imenujoč ga gospoda; njene hčerke ste postale ve, če delate dobro in se ne bojite nobenega strahu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 7, 'Možje takisto, živite z ženami svojimi po spoznanju, kakor s slabšo posodo, in jim dajajte čast, ker so tudi sodednice milosti življenja, da nimajo zaprek molitve vaše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 8, 'Slednjič pa, vsi bodite enega mišljenja, sočutni, bratoljubni, milosrčni, ponižni;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 9, 'ne vračajte hudega za hudo ali psovanja za psovanje, ampak rajši blagoslavljajte, kajti za to ste poklicani, da podedujete blagoslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 10, 'Zakaj „kdor hoče življenje ljubiti in videti dobre dni, brzda naj jezik pred hudim in ustne svoje, da ne govoré zvijače;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 11, 'ogiblje se naj hudega in dela dobro; išče naj mirú in hodi za njim“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 12, 'Ker „oči Gospodove so obrnjene v pravične in ušesa njegova k njih molitvam, obličje Gospodovo pa zoper nje, ki delajo hudo“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 13, 'In kdo je, da bi vam kaj hudega storil, ako bodete vneti za dobro?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 14, 'Ali ko bi tudi trpeli za pravičnost, blagor vam. Ne bojte pa se jih in se ne plašite,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 15, 'Kristusa pa kot Gospoda posvečujte v srcih svojih. Pripravljeni bodite vsekdar na odgovor vsakemu, ki vas vpraša za vzroke upanja, ki je v vas, toda s krotkostjo in strahom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 16, 'In dobro vest imejte, da se v tem, za kar vas obrekujejo, osramote tisti, ki grdijo vaše lepo vedenje v Kristusu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 17, 'Bolje namreč, da trpite, če hoče volja Božja, pri dobrih delih nego pri hudih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 18, 'Ker tudi Kristus je enkrat trpel za grehe, pravični za krivične, da nas pripelje Bogu, usmrčen v mesu, oživljen pa v duhu;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 19, 'v katerem je tudi šel in oznanjal duhovom v ječi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 20, 'ki so bili nekdaj neposlušni, ko je potrpežljivost Božja čakala v dneh Noetovih, ko se je napravljala barka, ki se je v njej malo, to je osem duš na varno rešilo po vodi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 21, 'temu podoben tudi vas zdaj rešuje krst, ne umitje mesene nesnage, ampak zaupljivo sklicevanje dobre vesti na Boga po vstajenju Jezusa Kristusa,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 3, 22, 'ki je po svojem vnebohodu na desnici Božji, in podrejeni so mu angeli in oblasti in moči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 1, 'Ker je torej Kristus trpel v mesu, oborožite se tudi vi z istim mišljenjem, ker kdor je trpel v mesu, je pri koncu z grehom:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 2, 'da ne živite več človeškim slam, ampak volji Božji ostali čas v mesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 3, 'Dosti namreč bodi pretekli čas življenja, ko ste delali voljo poganov, živeč v razuzdanosti, pohotnosti, pijanosti, požrešnosti, nezmernem popivanju in nespodobnem malikovanju;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 4, 'zato se jim zdi čudno, da ne letate ž njimi v isto razuzdanost nezmernosti, in vas obrekujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 5, 'Ti bodo odgovor dajali njemu, ki je pripravljen soditi žive in mrtve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 6, 'Zato se je namreč tudi mrtvim oznanil evangelij, da bi bili sojeni po človeško v mesu, živeli pa bi po Božje v duhu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 7, 'Vsega konec pa se je približal. Bodite torej pametni in trezni za molitve;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 8, 'predvsem pa imejte iskreno ljubezen med seboj, ker ljubezen pokriva grehov obilost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 9, 'Gostoljubni bodite med seboj brez godrnjanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 10, 'Kakor je vsakteri prejel dar, služite si ž njim med seboj kot dobri oskrbniki mnogotere milosti Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 11, 'Če kdo govori, naj govori kakor izreke Božje; če kdo služi, naj služi kakor iz moči, ki jo deli Bog; da se v vsem oslavlja Bog po Jezusu Kristusu, ki mu je slava in moč na vekov veke. Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 12, 'Ljubljeni, nikar se ne čudite ognjenemu žaru, ki vas objemlje zaradi izkušnje, kakor da se vam godi kaj tujega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 13, 'temuč veselite se, v kolikor ste deležni trpljenja Kristusovega, da bi se tudi v razodetju slave njegove radovali z velikim veseljem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 14, 'Če vas psujejo zaradi imena Kristusovega, blagor vam; zakaj Duh slave in Duh Božji počiva nad vami.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 15, 'Nihče izmed vas naj pa ne trpi kot morilec, ali tat, ali hudodelnik, ali kot tak, ki se meša v tuja opravila;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 16, 'če pa trpi kot kristjan, ne bodi ga sram, a slavi naj Boga v tem imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 17, 'Kajti čas je, da se začne sodba pri hiši Božji: če pa najprej pri nas, kaj bo konec tistih, ki so neposlušni evangeliju Božjemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 18, 'In če se iztežka reši pravični, kje ostane brezbožni in grešnik?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 4, 19, 'Zato naj tudi, kateri trpe po volji Božji, zvestemu stvarniku izročajo duše svoje, pridni v dobrih delih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 1, 'Starejšine med vami torej opominjam jaz, sostarejšina in priča trpljenja Kristusovega in tudi deležnik slave, ki se ima razodeti:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 2, 'Pasite čredo Božjo, ki je pri vas, nadzorujoč jo ne po sili, ampak prostovoljno, po Bogu; tudi ne za grd dobiček, ampak radovoljno;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 3, 'tudi ne kakor gospodovalci svoje posesti, temuč tako, da ste zgledi čredi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 4, 'In ko se prikaže višji Pastir, prejmete nevenljivi venec slave.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 5, 'Enako mlajši, pokorite se starejšim; vsi pa si opašite ponižnost, da služite drug drugemu, ker „Bog se upira prevzetnim, ponižnim pa daje milost“.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 6, 'Ponižajte se torej pod mogočno roko Božjo, da vas poviša ob času svojem;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 7, 'vso skrb svojo zvrnite nanj, ker on skrbi za vas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 8, 'Bodite trezni, bedite: nasprotnik vaš, hudič, hodi kakor rjoveč lev okrog in išče, koga bi pogoltnil;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 9, 'njemu se upirajte, trdni v veri, vedoč, da isto trpljenje prenaša bratovščina vaša razkropljena po svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 10, 'Bog vse milosti pa, ki vas je poklical v večno slavo svojo v Kristusu, vas sam po kratkem trpljenju napravi popolne, utrdi, pokrepča, ustanoviti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 11, 'Njemu moč na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 12, 'Po Silvanu, zvestem bratu, kakor sodim, vam pišem na kratko, opominjajoč in pričajoč, da je ta prava milost Božja, v kateri stojite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 13, 'Pozdravlja vas cerkev, z vami izvoljena, ki je v Babilonu, in Marko, sin moj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (60, 5, 14, 'Pozdravljajte se med seboj s poljubom ljubezni! Mir vam vsem, ki ste v Kristusu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 1, 'Simon Peter, hlapec in apostol Jezusa Kristusa, njim, ki so zadobili z nami enako dragoceno vero po pravičnosti Boga našega in Zveličarja Jezusa Kristusa:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 2, 'Milost vam in mir naj se pomnoži v spoznanju Boga in Jezusa Gospoda našega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 3, 'kakor nam je Božja moč njegova podarila vse, kar služi v življenje in pobožnost, po spoznanju njega, ki nas je poklical po lastni slavi in kreposti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 4, 'po čemer nam je podaril dragocene in največje obljube, da postanete po njih deležniki Božje narave, ko ste ubežali pogubi, ki jo na svetu provzroča poželenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 5, 'Prav zato si prizadevajte z vso gorečnostjo ter kažite v veri svoji krepost, v kreposti pa spoznanje, v spoznanju pa zmernost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 6, 'v zmernosti pa stanovitnost, v stanovitnosti pa pobožnost,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 7, 'v pobožnosti pa bratoljubje, v bratoljubju pa ljubezen do vseh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 8, 'Kajti če so te čednosti v vas in se množe, napravljajo, da niste nedelavni in nerodovitni v spoznanju Gospoda našega Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 9, 'Kdor namreč nima teh, je slep, kratkoviden, ker je pozabil, da je bil očiščen starih grehov svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 10, 'Zato se, bratje, tem bolj trudite, da utrdite poklic svoj in izvoljenje; kajti če tako delate, ne spotaknete se nikdar.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 11, 'Tako namreč vam bo dan zmagoslaven vhod v večno kraljestvo Gospoda našega in Zveličarja Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 12, 'Zato ne bom vnemar pustil, vedno vas spominjati tega, dasi to veste in ste utrjeni v dani vam resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 13, 'Menim pa, da je prav, dokler sem v tej koči, da vas izpodbujam, kličoč vam to v spomin,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 14, 'ker vem, da moram skoraj odložiti kočo svojo, kakor mi je tudi Gospod naš Jezus Kristus naznanil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 15, 'Potrudim se pa, da se morete tudi vsak čas po mojem odhodu spominjati tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 16, 'Kajti nismo se držali izmišljenih basni, ko smo vam oznanili Gospoda našega Jezusa Kristusa moč in prihod, marveč sami smo videli in bili priče njegovega veličastva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 17, 'Prejel je namreč od Boga Očeta čast in slavo, ko mu je prišel tak glas od veličastne slave: Ta je Sin moj ljubljeni, ki je po moji volji;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 18, 'in ta glas smo mi slišali, da je prišel z neba, ko smo bili ž njim na sveti gori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 19, 'In imamo besedo proroško tem trdnejšo; in prav delate, da pazite nanjo kakor na svetilnico, ki sveti v temnem kraju, dokler ne prisije dan in danica vzide v srcih vaših;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 20, 'to najprej spoznavajoč, da se nobeno prorokovanje pisma ne godi po lastnem razlaganju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 1, 21, 'Zakaj prorokovanje ni nikdar prišlo po volji človeški, temuč od Boga so govorili ljudje, kakor jih je vodil sveti Duh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 1, 'Nastopili so pa tudi lažnivi proroki v ljudstvu, kakor bodo tudi med vami lažnivi učitelji, ki bodo vtihotapljali pogubne krive nauke in zatajevali celo Gospoda, ki jih je odkupil, in s tem si pripravljali naglo pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 2, 'In mnogo jih bo hodilo za njih razuzdanostmi, zavoljo katerih se bo preklinjala pot resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 3, 'In v lakomnosti vas bodo izkoriščali z izmišljenimi besedami; katerim sodba že zdavnaj ne odlaša, in poguba njih ne dremlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 4, 'Kajti Bog ni prizanesel angelom, ki so grešili, temuč jih je z verigami teme pahnil v brezno in jih dal hraniti za sodbo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 5, 'in prvemu svetu ni prizanesel, temuč je kot osmega ohranil Noeta, glasnika pravičnosti, ko je poslal potop čez svet brezbožnih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 6, 'in mesti Sodomo in Gomoro je obsodil v razpad ter ju upepelil, s čimer ju je za zgled postavil tistim, ki bodo brezbožno živeli;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 7, 'in pravičnega Lota, trpečega od razuzdanega vedenja krivičnikov, je otel');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 8, '(kajti s pogledom in sluhom je ta pravičnik dan na dan mučil pravično dušo svojo ž njih nepostavnimi deli, prebivajoč med njimi).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 9, 'Gospod ve pobožne rešiti iz izkušnjave, krivične pa za dan sodbe hraniti v kaznovanje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 10, 'najbolj pa nje, ki hodijo za mesom v poželenju oskrumbe in zaničujejo gospostvo. Predrzneži, svojevoljneži, ne boje se preklinjati veličanstev,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 11, 'ko vendar angeli, po krepkosti in moči večji, ne izrekajo zoper nje pred Gospodom preklinjajoče sodbe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 12, 'Ti pa kakor nespametne živali, po naravi rojene za lov in klanje, ker preklinjajo, česar ne poznajo, se bodo pogubili v pogubi svoji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 13, 'prejemši krivice plačilo. Njim se veselje zdi požrešnost po dnevi, nesnage so in grdobe, razkošno žive v sleparstvih svojih in se goste z vami,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 14, 'oči imajo polne prešeštvovanja in nikdar ne sitih greha, vabijo duše neutrjene, imajo srce vajeno v lakomnosti in so prokletstva otroci;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 15, 'zapustili so ravno pot ter tavali in hodili po poti Balaama, sina Bosorjevega, ki je ljubil krivice plačilo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 16, 'a prejel posvarilo za lastno nepostavnost: brezglasno vprežno živinče je izpregovorilo s človeškim glasom ter zabranilo prorokovo nespamet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 17, 'Ti so studenci brez vode in megle, ki jih goni vihar, ki jim je shranjen mrak večne teme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 18, 'Kajti prešerno in ničemurno govoreč, vabijo s poželenjem mesa, z razuzdanostmi one, ki so komaj ubežali njim, ki hodijo v zmotnjavi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 19, 'obetajoč jim svobodo, ko so sami sužnji pogube; zakaj od kogar je kdo premagan, tistemu je postal suženj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 20, 'Če se namreč taki, ki so ubežali oskrumbam sveta po spoznanju Gospoda in Zveličarja Jezusa Kristusa, zopet zapleto vanje in so premagani, je postalo njih poslednje hujše od prvega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 21, 'Kajti bolje bi jim bilo, da bi ne bili spoznali pota pravičnosti, nego pa da so se po spoznanju obrnili zopet od dane jim svete zapovedi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 2, 22, 'Prigodilo se jim je pa po resničnem pregovoru: Pes se vrne k temu, kar je izbljuval, in svinja omita v lužo blatno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 1, 'Tu vam, ljubljeni, pišem že drugi list in v obeh zbujam z opominom vaše čisto mišljenje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 2, 'da se spominjate prej govorjenih besed svetih prorokov in zapovedi Gospoda in Zveličarja, ki ste jo prejeli od svojih apostolov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 3, 'to najprej vedoč, da pridejo v zadnjih dneh posmehovalci z zasmehovanjem, ki žive po lastnih svojih poželenjih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 4, 'in govoré: Kje je obljuba prihoda njegovega? Saj odkar so zaspali očetje, je vse, kakor je bilo od začetka stvaritve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 5, 'Hotoma namreč ne vedo tega, da so bila od nekdaj nebesa in zemlja, ki je postala iz vode in z vodo po besedi Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 6, 'po kateri je tedanji svet poginil z vodo potopljen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 7, 'sedanja nebesa pa in zemlja so bila po isti besedi shranjena za ogenj in se vzdržujejo za dan sodbe in pogube brezbožnih ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 8, 'To eno pa vam ne bodi skrito, ljubljeni, da je en dan pred Gospodom kakor tisoč let in tisoč let kakor en dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 9, 'Gospod ne odlaša obljube, kar imajo nekateri za odlašanje; temuč potrpežljiv je z vami, ker noče, da se kdo pogubi, ampak da vsi pridejo do izpokorjenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 10, 'Pride pa dan Gospodov kakor tat, v katerem preidejo nebesa z velikim ropotom in prvine razpadejo v požaru in zemlja in vsa dela na njej zgore.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 11, 'Ker ima torej vse to razpasti, koliki morate biti vi v svetem življenju in pobožnosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 12, 'ki čakate in pospešujete prihod dneva Božjega, spričo katerega razpadejo nebesa v ognju in se prvine goreč raztope.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 13, 'Novih pa nebes in nove zemlje pričakujemo po obljubi njegovi, v katerih prebiva pravičnost.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 14, 'Zato, ljubljeni, trudite se, tega čakajoč, da se pokažete brez madeža in brez hibe pred njim v miru.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 15, 'In potrpežljivost Gospoda našega imejte za zveličanje; kakor vam je tudi ljubljeni brat naš Pavel pisal po dani mu modrosti,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 16, 'kakor i v vseh listih svojih, govoreč v njih o teh rečeh; ki je v njih nekaj težko umljivega, kar nevedni in neutrjeni zavijajo, kakor tudi druga pisma, v lastno pogubo svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 17, 'Vi torej, ljubljeni, ki to naprej veste, pazite, da vas pregrešnih zmota ne potegne za seboj in ne padete iz lastnega trdnega stanja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (61, 3, 18, 'temuč rastite v milosti in spoznanju Gospoda našega in Zveličarja Jezusa Kristusa. Njemu slava i sedaj i na dan večnosti!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 1, 'Kar je bilo od začetka, kar smo slišali, kar smo videli na svoje oči, kar smo gledali in so tipale naše roke, o Besedi življenja');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 2, '(in življenje se je razodelo, in videli smo in pričamo in oznanjujemo vam večno življenje, ki je bilo pri Očetu in se je razodelo nam);');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 3, 'kar smo videli in slišali, oznanjamo vam, da imate tudi vi deleštvo z nami; deleštvo naše pa je z Očetom in Sinom njegovim Jezusom Kristusom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 4, 'In to pišemo, da bode veselje vaše popolno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 5, 'In to je oznanilo, ki smo ga slišali od njega in ga vam oznanjamo: da je Bog luč, in teme v njem ni nobene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 6, 'Ako pravimo, da imamo deleštvo ž njim, pa živimo v temi, lažemo in ne delamo resnice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 7, 'če pa živimo v luči, kakor je on v luči, imamo deleštvo med seboj, in kri Jezusa Kristusa, Sina njegovega, nas očiščuje slehernega greha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 8, 'Ako pravimo, da nimamo greha, sami sebe slepimo, in resnice ni v nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 9, 'Če pripoznavamo grehe svoje, je zvest in pravičen, da nam odpusti grehe in nas očisti sleherne krivice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 1, 10, 'Ako pravimo, da nismo grešili, ga delamo za lažnika, in besede njegove ni v nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 1, 'Otročiči moji, to vam pišem, da ne grešite. Ako se pa kdo pregreši, imamo Odvetnika pri Očetu, Jezusa Kristusa pravičnega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 2, 'in on je sprava za grehe naše, ne pa samo za naše, ampak tudi za vsega sveta grehe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 3, 'In po tem vemo, da smo ga spoznali, ako držimo zapovedi njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 4, 'Kdor pravi: Spoznal sem ga, a ne drži zapovedi njegovih, je lažnik in v njem ni resnice;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 5, 'kdor pa izpolnjuje besedo njegovo, v njem je resnično ljubezen Božja dopolnjena. Po tem vemo, da smo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 6, 'Kdor pravi, da v njem ostaja, mora tudi tako živeti, kakor je on živel.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 7, 'Ljubljeni, ne pišem vam nove zapovedi, ampak zapoved staro, ki ste jo imeli od začetka. Stara zapoved je beseda, ki ste jo slišali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 8, 'Zopet vam pišemo novo zapoved, kar je resnično v njem in v vas; ker tema gine in prava luč že sveti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 9, 'Kdor pravi, da je v luči, pa sovraži brata svojega, je v temi še do sedaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 10, 'Kdor ljubi brata svojega, ostaja v luči in pohujšanja ni v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 11, 'Kdor pa sovraži brata svojega, je v temi in hodi po temi in ne ve, kam gre, ker tema je oslepila oči njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 12, 'Pišem vam, otročiči, ker so vam grehi odpuščeni zaradi imena njegovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 13, 'Pišem vam, očetje, ker ste spoznali njega, ki je od začetka. Pišem vam, mladeniči, ker ste premagali Hudobnega. Pisal sem vam, otročiči, ker ste spoznali Očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 14, 'Pisal sem vam, očetje, ker ste spoznali njega, ki je od začetka. Pisal sem vam, mladeniči, ker ste krepki, in beseda Božja ostaja v vas, in premagali ste Hudobnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 15, 'Ne ljubite sveta, ne tega, kar je na svetu. Če kdo ljubi svet, ni ljubezni Očetove v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 16, 'Zakaj vse, kar je na svetu: poželenje mesa in poželenje oči in življenja napuh, ni iz Očeta, temuč je iz sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 17, 'In svet gine in poželenje njegovo; kdor pa dela voljo Božjo, ostane vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 18, 'Otročiči, poslednja ura je, in kakor ste slišali, da se antikrist bliža, so že sedaj vstali mnogi antikristi: odtod spoznavamo, da je poslednja ura.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 19, 'Izmed nas so izšli, ali niso bili iz nas; kajti ko bi bili iz nas, bi bili ostali z nami: toda odšli so, da se pokažejo, da niso vsi iz nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 20, 'In vi imate maziljenje od Svetega in veste vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 21, 'Nisem vam pisal, ker ne znate resnice, ampak ker jo znate in ker ni nobene laži iz resnice.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 22, 'Kdo je lažnik, če ne tisti, kdor taji, da Jezus je Kristus? Ta je antikrist, ki taji Očeta in Sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 23, 'Vsak, ki taji Sina, tudi Očeta nima; kdor pripoznava Sina, ima tudi Očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 24, 'Vi pa – kar ste slišali od začetka, to naj ostane v vas. Če ostane v vas, kar ste slišali od začetka, tudi vi ostanete v Sinu in v Očetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 25, 'In ta je obljuba, ki nam jo je obljubil: večno življenje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 26, 'To sem vam pisal za tiste, ki vas slepe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 27, 'In za vas: maziljenje, ki ste ga prejeli od njega, ostaja v vas, in treba ni, da bi vas kdo učil; temuč kakor vas maziljenje njegovo uči vsega in je resnično in ni laž, in kakor vas je poučilo, tako ostanite v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 28, 'In sedaj, otročiči, ostanite v njem, da imamo, če se on prikaže, trdno zaupanje in ne bomo osramočeni pred njim ob prihodu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 2, 29, 'Ako veste, da je pravičen, spoznajte, da je vsak, ki dela pravičnost, iz njega rojen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 1, 'Poglejte, koliko ljubezen nam je dal Oče, da se imenujemo otroci Božji, in smo tudi. Zato nas svet ne spoznava, ker njega ni spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 2, 'Ljubljeni, sedaj smo otroci Božji, a ni se še pokazalo, kaj bodemo. Vemo pa, da bodemo, ko se prikaže, njemu podobni, ker ga bomo videli, kakor je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 3, 'In vsak, kdor ima to upanje vanj, očiščuje sebe, kakor je on čist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 4, 'Vsak, kdor dela greh, dela tudi protizakonje; in greh je protizakonje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 5, 'In veste, da se je on prikazal, da odvzame grehe naše; in greha ni v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 6, 'Kdorkoli ostaja v njem, ne greši; kdorkoli greši, ga ni videl in ga ni spoznal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 7, 'Otročiči, nihče naj vas ne slepi: kdor dela pravičnost, je pravičen, kakor je on pravičen;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 8, 'kdor dela greh, je iz hudiča, ker hudič greši od začetka. Zato se je prikazal Sin Božji, da razdene dela hudičeva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 9, 'Kdorkoli je rojen iz Boga, ne dela greha, ker seme njegovo ostaja v njem, in grešiti ne more, ker je rojen iz Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 10, 'V tem so očitni otroci Božji in otroci hudičevi: kdorkoli ne dela pravičnosti, ni iz Boga, in kdor ne ljubi brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 11, 'Kajti to je oznanilo, ki ste ga slišali od začetka: naj se ljubimo med seboj;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 12, 'ne kakor Kajn, ki je bil iz Hudobnega in je ubil brata svojega. In zakaj ga je ubil? Ker so bila hudobna dela njegova, dela brata njegovega pa pravična.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 13, 'Ne čudite se, bratje moji, če vas svet sovraži.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 14, 'Mi vemo, da smo prešli iz smrti v življenje, ker ljubimo brate. Kdor ne ljubi, ostaja v smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 15, 'Vsak, kdor sovraži brata svojega, je ljudomorec; in veste, da noben ljudomorec nima večnega življenja, ki bi prebivalo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 16, 'V tem smo spoznali ljubezen, da je on dal življenje za nas; tudi mi moramo dati življenje za brate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 17, 'Kdor pa ima premoženje tega sveta in vidi brata svojega, da je v potrebi, a zapre srce svoje pred njim, kako prebiva ljubezen Božja v njem?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 18, 'Otročiči moji, ne ljubimo z besedo, tudi ne z jezikom, marveč v dejanju in resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 19, 'In v tem spoznamo, da smo iz resnice, in pred njim bomo pomirili srca svoja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 20, 'da, ako nas srce naše obsoja, je Bog večji od srca našega in pozna vse.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 21, 'Ljubljeni, če nas srce naše ne obsoja, imamo trdno zaupanje do Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 22, 'in karkoli prosimo, prejmemo od njega, ker držimo zapovedi njegove in delamo, kar je prijetno pred njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 23, 'In ta je zapoved njegova, da verujmo v ime Sina njegovega, Jezusa Kristusa, in se ljubimo med seboj, kakor nam je dal zapoved.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 3, 24, 'In kdor drži zapovedi njegove, ostaja v Njem in On v njem. In v tem spoznavamo, da ostaja v nas, iz Duha namreč, ki ga nam je dal.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 1, 'Ljubljeni, ne verujte vsakemu duhu, ampak presojajte duhove, ali so iz Boga; ker mnogo lažnivih prorokov je prišlo na svet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 2, 'V tem spoznate Duha Božjega: vsak duh, ki pripoznava Jezusa Kristusa, da je prišel v mesu, je iz Boga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 3, '§ in vsak duh, ki ne pripoznava Jezusa, da je prišel v mesu, ni iz Boga, in ta je duh antikristov, o katerem ste slišali, da se bliža, in sedaj je že na svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 4, 'Vi ste iz Boga, otročiči, in premagali ste jih; ker večji je on, ki je v vas, nego on, ki je v svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 5, 'Oni so iz sveta; zato govore, kar je iz sveta, in svet jih posluša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 6, 'Mi smo iz Boga; kdor poznava Boga, posluša nas, kdor ni iz Boga, nas ne posluša. Iz tega spoznavamo duha resnice in duha zmote.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 7, 'Ljubljeni, ljubimo se med seboj; kajti ljubezen je iz Boga, in vsak, kdor ljubi, je rojen iz Boga in spoznava Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 8, 'Kdor ne ljubi, ni spoznal Boga, ker Bog je ljubezen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 9, 'V tem se je razodela ljubezen Božja v nas, da je Bog poslal Sina svojega edinorojenega na svet, da bi živeli po njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 10, 'V tem je ljubezen, ne da smo mi ljubili Boga, temuč da je on ljubil nas in poslal Sina svojega v spravo za grehe naše.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 11, 'Ljubljeni, če nas je Bog tako ljubil, dolžni smo tudi mi ljubiti se med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 12, 'Boga ni nihče nikdar videl; če se ljubimo med seboj, ostaja Bog v nas in ljubezen njegova je dopolnjena v nas.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 13, 'V tem spoznavamo, da ostajamo v njem in on v nas, ker nam je dal od Duha svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 14, 'In mi smo videli in pričujemo, da je Oče poslal Sina kot Zveličarja sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 15, 'Kdor pripoznava, da je Jezus Sin Božji, v njem ostaja Bog in on v Bogu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 16, 'In mi smo spoznali in verovali ljubezen, ki jo ima Bog do nas. Bog je ljubezen, in kdor ostaja v ljubezni, ostaja v Bogu in Bog v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 17, 'V tem se je dopolnila ljubezen pri nas, da imamo trdno zaupanje ob dnevi sodbe; ker kakor je on, smo tudi mi na tem svetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 18, 'Strahu ni v ljubezni, temuč popolna ljubezen izganja strah, ker strah povzroča trpljenje; kdor pa se boji, ni popoln v ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 19, 'Mi ga ljubimo, ker nas je on prvi ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 20, 'Ako kdo pravi: Boga ljubim, pa sovraži brata svojega, je lažnik; kdor namreč ne ljubi brata svojega, katerega vidi, kako more ljubiti Boga, ki ga ne vidi?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 4, 21, 'In to zapoved imamo od njega, da kdor ljubi Boga, naj ljubi tudi brata svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 1, 'Vsak, kdor veruje, da Jezus je Kristus, je rojen iz Boga; in vsak, kdor ljubi njega, ki ga je rodil, ljubi tudi tega, ki je rojen iz njega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 2, 'V tem spoznavamo, da ljubimo otroke Božje, ako ljubimo Boga in izpolnjujemo zapovedi njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 3, 'Kajti to je ljubezen Božja, da držimo zapovedi njegove; in zapovedi njegove niso težke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 4, 'Ker vse, kar je rojeno iz Boga, premaga svet; in to je zmaga, ki je premagala svet: vera naša.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 5, 'Kdo je, ki premaga svet, če ne tisti, ki veruje, da je Jezus Sin Božji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 6, 'Ta je, ki je prišel po vodi in krvi, Jezus Kristus; ne z vodo samo, ampak z vodo in s krvjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 7, 'In Duh je, ki pričuje, ker Duh je resnica.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 8, 'Kajti trije so, ki pričajo: Duh in voda in kri, in ti trije so eno v svojem pričanju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 9, 'Če sprejemamo pričevanje ljudi, pričevanje Božje je večje: kajti to je pričevanje Božje, da je pričal za Sina svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 10, 'Kdor veruje v Sina Božjega, ima pričevanje v sebi; kdor ne veruje Bogu, ga je naredil za lažnika, ker ni veroval v pričevanje, ki ga je Bog pričal za Sina svojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 11, 'In to je pričevanje: da nam je Bog dal večno življenje, in to življenje je v Sinu njegovem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 12, 'Kdor ima Sina ima življenje; kdor nima Sina Božjega, nima življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 13, 'To sem vam pisal, da veste, da imate večno življenje, kateri verujete v ime Sina Božjega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 14, 'In to je trdno zaupanje, ki ga imamo do njega, da nas sliši, ako kaj prosimo po volji njegovi;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 15, 'in če vemo, da nas sliši, česarkoli prosimo, vemo, da nam je izpolnjeno, česar smo ga prosili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 16, 'Ako kdo vidi brata svojega, da greši, a ne greha za smrt, bo prosil, in dá mu Bog življenje, njim namreč, ki ne greše za smrt. Je greh za smrt; ne za tega, pravim, naj prosi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 17, 'Sleherna krivica je greh; a je greh, ki ni za smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 18, 'Vemo, da kdorkoli je rojen iz Boga, ne greši; temuč kdor je bil rojen iz Boga, varuje sebe in Hudobni se ga ne dotakne.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 19, 'Vemo, da smo iz Boga, in ves svet leži v Hudobnem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 20, 'Vemo pa, da je Sin Božji prišel in nam dal razum, da spoznamo Resničnega; in smo v Resničnem, v Sinu njegovem Jezusu Kristusu. Ta je resnični Bog in življenje večno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (62, 5, 21, 'Otročiči, varujte se malikov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 1, 'Starejšina izvoljeni gospe in otrokom njenim, ki jih jaz ljubim v resnici, in ne jaz sam, ampak tudi vsi, ki so spoznali resnico,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 2, 'zaradi resnice, ki ostaja v nas in z nami bode vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 3, 'Z nami bode milost, usmiljenje, mir od Boga Očeta in od Jezusa Kristusa, Sinu Očetovega, v resnici in ljubezni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 4, 'Zelo sem se veselil, ker sem našel nekatere izmed otrok tvojih, ki žive v resnici, kakor smo zapoved prejeli od Očeta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 5, 'In sedaj te prosim, gospa, ne kakor da bi ti pisal novo zapoved, temuč katero smo imeli od začetka, da se ljubimo med seboj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 6, 'In to je ljubezen, da živimo po zapovedih njegovih. To je zapoved, kakor ste slišali od začetka, da v njej živite.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 7, 'Kajti mnogi sleparji so prišli na svet, ki ne pripoznavajo Jezusa Kristusa, da je prišel v mesu. Ta je slepar in antikrist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 8, 'Pazite nase, da ne izgubite, kar ste pridelali, temuč prejmete popolno plačilo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 9, 'Kdorkoli prestopa in ne ostaja v nauku Kristusovem, nima Boga; kdor ostaja v nauku, ta ima i Očeta i Sina.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 10, 'Če kdo prihaja k vam in ne prinaša tega nauka, ne sprejemajte ga v hišo in ne pozdravljajte ga;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 11, 'kajti kdor ga pozdravlja, se udeležuje hudobnih del njegovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 12, 'Mnogo sem vam imel pisati, a nisem hotel na papir in s črnilom; ali upam priti k vam in iz ust do ust govoriti, da bode veselje vaše popolno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (63, 1, 13, 'Pozdravljajo te otroci sestre tvoje izvoljene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 1, 'Starejšina Gaju ljubljenemu, ki ga ljubim v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 2, 'Ljubljeni, želim, da se ti v vsem dobro godi in da si zdrav, kakor se dobro godi duši tvoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 3, 'Zelo sem se veselil, ko so prišli bratje in so pričali za resnico tvojo, kakor ti živiš v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 4, 'Večjega veselja nimam od tega, da slišim, da otroci moji žive v resnici.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 5, 'Ljubljeni, zvesto ravnaš v tem, karkoli delaš za brate, in to tujce,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 6, 'ki so pričali za ljubezen tvojo pred cerkvijo; in dobro boš delal, če jih odpravljaš na pot, kakor je vredno Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 7, 'Kajti zaradi imena njegovega so šli na pot, ničesar ne jemajoč od poganov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 8, 'Mi torej smo dolžni sprejemati take, da jim bodemo sodelavci za resnico.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 9, 'Pisal sem nekaj vaši cerkvi, ali Diotrefej, ki hoče prvakovati med njimi, nas ne sprejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 10, 'Zato, ako pridem, ga spomnim del njegovih, ki jih dela, s hudobnimi besedami blebetajoč zoper nas; in ne zadovoljen s tem, ne samo sam ne sprejema bratov, ampak brani tudi njim, ki hočejo sprejemati, in jih izobčuje iz cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 11, 'Ljubljeni, ne posnemaj slabega, marveč dobro. Kdor dobro dela, je iz Boga; kdor slabo dela, ni videl Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 12, 'Demetrij ima dobro pričevanje od vseh in od same resnice; in tudi mi pričamo zanj, in veš, da je pričevanje naše resnično.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 13, 'Mnogo sem imel pisati, ali nočem ti pisati s črnilom in peresom;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (64, 1, 14, 'upam pa te videti skoraj in govorila bova iz ust do ust. [1:15] Mir tebi! Pozdravljajo te prijatelji. Pozdravi prijatelje po imenu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 1, 'Juda, Jezusa Kristusa hlapec, a brat Jakobov, poklicanim, v Bogu Očetu ljubljenim in za Jezusa Kristusa hranjenim:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 2, 'Usmiljenje vam in mir in ljubezen naj se pomnoži!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 3, 'Ljubljeni, ko sem si mnogo prizadeval, pisati vam v skupnem nam zveličanju, se mi je potrebno videlo, pisati vam opominjaje, da se vrlo borite za vero, ki je enkrat za vselej izročena svetim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 4, 'Kajti priplazili so se neki ljudje, zdavnaj naprej zapisani za to sodbo, brezbožni, ki milost Boga našega krivo rabijo v razuzdanost in taje edinega Vladarja in Gospoda našega, Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 5, 'Spomniti pa vas hočem, čeprav zdaj vse to že veste, da je Gospod, ko je rešil ljudstvo iz dežele Egiptovske, pozneje pogubil tiste, ki niso verovali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 6, 'In angele, ki niso hranili poglavarstva svojega, temuč so zapustili lastno domovje, je shranil za sodbo velikega dneva z večnimi vezmi pod temo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 7, 'Kakor Sodoma in Gomora in mesta okoli njiju, ki so enako kakor oni nečistovala in hodila za drugim mesom, so postavljena za zgled, ker trpe kazen večnega ognja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 8, 'Enako torej tudi ti, praznim sanjam se vdajajoč, oskrunjajo meso, zaničujejo gospostvo, preklinjajo veličanstva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 9, 'Mihael pa, nadangel, ko se je s hudičem prepiral in prerekal o truplu Mojzesovem, si ni upal izreči sodbe preklinjevanja, marveč je rekel: Kaznuj te Gospod!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 10, 'Ti pa preklinjajo, česarkoli ne vedo; kar pa po naravi znajo, kakor nespametne živali, v tem se pogubljajo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 11, 'Gorje jim! ker so hodili po potu Kajnovem in so zabredli v zmoto Balaamovo zaradi plačila in so poginili v Korejevem uporu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 12, 'Ti so pri bratovskih pojedinah vaših zapreke, ko se goste z vami in brez strahu sami sebe paso; so oblaki brez vode, ki jih gonijo vetrovi, drevesa poznojesenska, brez sadu, dvakrat mrtva, izkoreninjena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 13, 'divji morski valovi, ki izpenjavajo lastno sramoto; zvezde tavajoče, katerim je mrak teme shranjen vekomaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 14, 'Prorokoval je pa tudi tem sedmi od Adama, Enoh, govoreč: Glej, prišel je Gospod z miriadami svetih svojih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 15, 'izvršit sodbo nad vsemi in kaznovat vse brezbožne za vsa dela brezbožnosti, ki so jih brezbožno storili, in za vse trde besede, ki so jih govorili zoper njega grešniki brezbožni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 16, 'Ti so godrnjači, pritoževalci, ki hodijo po svojih poželenjih, in usta njih govore šopirno, občudujoč osebe zaradi koristi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 17, 'Vi pa, ljubljeni, spominjajte se besed, ki so jih naprej govorili apostoli Gospoda našega Jezusa Kristusa, da so vam rekli:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 18, 'V zadnjem času bodo posmehovalci, živeči po svojih poželenjih brezbožnosti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 19, 'Ti so, ki napravljajo razkole, živinski, ne imajoč duha.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 20, 'Vi pa, ljubljeni, sezidavajte se na presveti veri svoji in molite v svetem Duhu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 21, 'ohranite se v ljubezni Božji, pričakujte usmiljenja Gospoda našega Jezusa Kristusa, za večno življenje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 22, 'In nekatere prepričujte, ki so v dvomih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 23, 'nekatere pa rešite, potegnivši jih iz ognja, nekatere pa s strahom milujte, sovražeč tudi obleko, oskrunjeno po mesu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 24, 'Njemu pa, ki vas more obvarovati brez spotike in postaviti pred obličje slave svoje brez madeža v radovanju,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (65, 1, 25, 'edinemu Bogu, Rešitelju našemu, po Jezusu Kristusu Gospodu našem slava, veličastvo, moč in oblast pred vsem časom in zdaj in na vse veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 1, 'Razodetje Jezusa Kristusa, ki mu ga je dal Bog, da pokaže hlapcem svojim, kaj se ima skoraj zgoditi; in je poslal angela svojega in po njem to v znamenjih oznanil hlapcu svojemu Janezu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 2, 'ki je izpričal besedo Božjo in pričevanje Jezusa Kristusa, karkoli je videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 3, 'Blagor mu, kdor bere in njim, ki slišijo besede prorokovanja in hranijo, kar je v njem pisano, kajti čas je blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 4, 'Janez sedmerim cerkvam, ki so v Aziji: Milost vam in mir od njega, ki je in ki je bil in ki prihaja, in od sedmerih Duhov, ki so pred prestolom njegovim,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 5, 'in od Jezusa Kristusa, ki je zvesta priča, prvorojenec izmed mrtvih in poglavar kraljev zemlje. Njemu, ki nas ljubi in nas je omil grehov naših v krvi svoji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 6, 'in nas je storil v kraljestvo in za duhovnike Bogu in Očetu svojemu, njemu slava in moč na vekov veke! Amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 7, 'Glej, prihaja z oblaki; in videlo ga bo vsako oko in tisti, ki so ga prebodli, in žalovali bodo nad njim vsi rodovi zemlje. Gotovo, amen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 8, 'Jaz sem Alfa in Omega, začetek in konec, govori Gospod, Bog, ki je in ki je bil in ki prihaja, Vsemogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 9, 'Jaz Janez, brat vaš in sodeležnik v stiski in v kraljestvu in stanovitnosti v Jezusu, sem bil na otoku, imenovanem Patmu, zavoljo besede Božje in pričevanja Jezusovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 10, 'Bil sem v Duhu ob dnevi Gospodnjem, in sem slišal za seboj velik glas kakor trombe,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 11, 'govoreče: Kar vidiš, zapiši v knjigo in pošlji sedmerim cerkvam: v Efez in v Smirno in v Pergam in v Tiatire in v Sarde in v Filadelfijo in v Laodicejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 12, 'In obrnil sem se, da bi videl glas, ki je govoril z menoj; in obrnivši se, sem videl sedem svečnikov zlatih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 13, 'in sredi svečnikov podobnega sinu človečjemu, oblečenega v obleko do tal in opasanega na prsih z zlatim pasom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 14, 'Glava pa njegova in lasje beli kakor bela volna, kakor sneg, in oči njegove kakor plamen ognja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 15, 'in noge njegove podobne svetlemu bronu, kakor v peči razbeljenemu, in glas njegov kakor glas mnogih voda;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 16, 'in v desni roki je imel sedem zvezd, in iz ust njegovih je izhajal dvorezen, oster meč, in obličje njegovo je bilo, kakor ko solnce sije v moči svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 17, 'In ko sem ga videl, sem padel pred noge njegove kakor mrtev; in položil je name desnico svojo, rekoč: Ne boj se; jaz sem Prvi in Poslednji');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 18, 'in Živi, in bil sem mrtev, in glej, živ sem na vekov veke, in ključe imam od smrti in smrtne države.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 19, 'Zapiši torej, kar si videl in kar je in kar se ima zgoditi potem,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 1, 20, 'skrivnost sedmerih zvezd, ki si jih videl v desnici moji, in sedmero svečnikov zlatih. Sedmere zvezde so angeli sedmerih cerkva, in sedmeri svečniki so sedmere cerkve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 1, 'Angelu cerkve v Efezu piši: To pravi on, ki drži sedmero zvezd v desnici svoji, ki hodi sredi sedmerih svečnikov zlatih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 2, 'Vem za dela tvoja in trud tvoj in stanovitnost tvojo, in da ne moreš prenašati hudobnih in si preizkusil nje, ki se imenujejo apostole, a niso, in si jih spoznal kot lažnike;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 3, 'in stanovitnost imaš in za ime moje si mnogo prenesel in se nisi utrudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 4, 'Toda imam zoper tebe, da si opustil prvo ljubezen svojo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 5, 'Spominjaj se torej, odkod si padel, in izpokóri se in delaj prva dela; ako pa ne, ti pridem in premaknem svečnik tvoj z mesta njegovega, če se ne izpokoriš.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 6, 'Ali to imaš, da sovražiš dela Nikolajcev, ki jih tudi jaz sovražim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 7, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, dam jesti z drevesa življenja, ki je v raju Božjem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 8, 'In angelu cerkve v Smirni piši: To pravi Prvi in Poslednji, ki je bil mrtev in je oživel:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 9, 'Vem za stisko tvojo in uboštvo tvoje (bogat pa si!) in za preklinjanje njih, ki pravijo, da so Judje, a niso, ampak so zbornica Satanova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 10, 'Nič se ne boj tega, kar ti bode trpeti. Glej, hudič bo vrgel nekatere izmed vas v ječo, da boste izkušeni, in imeli boste stisko deset dni. Bodi zvest do smrti, in dam ti venec življenja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 11, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, se nič žalega ne zgodi od druge smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 12, 'In angelu cerkve v Pergamu piši: To pravi on, ki ima meč dvorezni, ostri:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 13, 'Vem, kje prebivaš, namreč kjer je prestol satanov; in se trdno držiš imena mojega in nisi zatajil vere moje tudi v dneh Antipa, priče moje, zvestega mojega, ki je bil umorjen pri vas, kjer satan prebiva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 14, 'Toda imam zoper tebe nekaj malega, da imaš tam nekatere, ki se drže uka Balaamovega, ki je poučil Balaka, naj postavi pohujšanje pred sinove Izraelove, da jedo malikove žrtve in nečistujejo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 15, 'Tako jih imaš tudi ti, ki se drže nauka Nikolajcev po podobnem načinu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 16, 'Izpokóri se torej; ako pa ne, ti pridem hitro in vojskoval se bom ž njimi z mečem svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 17, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam. Njemu, kdor premaga, dam mane skrite, in mu dam bel kamen in na kamenu zapisano novo ime, ki ga nihče ne pozna, razen kdor ga prejme.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 18, 'In angelu cerkve v Tiatirih piši: To pravi Sin Božji, ki ima oči kakor plamen ognja, in noge njegove so podobne svetlemu bronu:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 19, 'Vem za dela tvoja in ljubezen in vero in službo in stanovitnost tvojo ter da je zadnjih del tvojih več nego prvih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 20, 'Toda imam zoper tebe, da trpiš ženo Jezabelo, ki se sama imenuje prorokinjo in uči in zapeljuje hlapce moje, da nečistujejo in jedo malikove žrtve.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 21, 'In dal sem ji časa, da se izpokori, a se noče izpokoriti od nečistosti svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 22, 'Glej, vržem jo na posteljo in tiste, ki prešuštvujejo ž njo, v stisko veliko, če se ne izpokore od del njenih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 23, 'in otroke njene pomorim s smrtjo; in spoznajo vse cerkve, da sem jaz, ki preiskujem obisti in srca, in dam vam vsakemu po delih vaših.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 24, 'Vam pa pravim, ostalim v Tiatirih, vsem, ki nimajo tega nauka, ki niso spoznali, kakor oni pravijo, globočin satanovih: Ne vržem na vas druge teže.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 25, 'Toda kar imate, trdno držite, dokler ne pridem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 26, 'In njemu, kdor premaga in kdor ohrani do konca dela moja, dam oblast nad narodi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 27, 'in pasel jih bo s palico železno, kakor lončarjeve posode bodo strti, kakor sem tudi jaz prejel od Očeta svojega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 28, 'in mu dam zvezdo jutranjo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 2, 29, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 1, 'In angelu cerkve v Sardih piši: To pravi on, ki ima sedmero Duhov Božjih in zvezd sedmero: Vem za dela tvoja, da imaš ime, da živiš, in si mrtev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 2, 'Zbudi se in utrdi ostalo, kar je že umiralo. Kajti del tvojih nisem našel popolnih pred Bogom svojim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 3, 'Spominjaj se torej, kako si prejel in slišal, ter hrani to in se izpokóri. Ako se torej ne zbudiš, pridem kakor tat in ne boš vedel, ob kateri uri pridem nad tebe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 4, 'Ali imaš malo imen v Sardih, kateri niso oskrunili svojih oblačil, in hodili bodo z menoj v belih, ker so vredni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 5, 'Kdor premaga, bo tako oblečen v bela oblačila, in nikakor ne izbrišem imena njegovega iz knjige življenja, a pripoznam ime njegovo pred Očetom svojim in pred angeli njegovimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 6, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 7, 'In angelu cerkve v Filadelfiji piši: To pravi Sveti, Resnični, ki ima ključ Davidov, ki odpira, in nihče ne zapre, in zapira, in nihče ne odpre.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 8, 'Vem za dela tvoja. Glej, postavil sem pred teboj vrata odprta, in nihče jih ne more zapreti, ker majhno imaš moč, in ohranil si besedo mojo in nisi zatajil imena mojega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 9, 'Glej, dajem ti jih iz zbornice satanove, ki pravijo, da so Judje, a niso, ampak lažejo; glej, storil bom, da pridejo in pokleknejo pred noge tvoje, in spoznajo, da sem te jaz ljubil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 10, 'Ker si ohranil besedo stanovitnosti moje, te ohranim tudi jaz iz ure izkušnjave, ki ima priti na vesoljni svet, izkušat te, ki prebivajo na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 11, 'Hitro pridem; trdno drži, kar imaš, da ti nihče ne vzame venca.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 12, 'Njega, kdor premaga, naredim za steber v templju Boga svojega, in ven ne pojde več, in zapišem nanj ime Boga svojega in ime mesta Boga svojega, novega Jeruzalema, ki z neba doli gre od Boga mojega, in ime svoje novo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 13, 'Kdor ima uho, naj sliši, kaj Duh govori cerkvam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 14, 'In angelu cerkve v Laodiceji piši: To pravi, ki je Amen, priča zvesta in resnična, začetek stvarjenja Božjega:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 15, 'Vem za dela tvoja, da nisi ne mrzel, ne gorak. Da bi bil mrzel ali gorak!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 16, 'Tako pa, ker si mlačen in ne mrzel, ne gorak, te hočem izpljuniti iz svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 17, 'Ker praviš: Bogat sem in obogatel sem in ničesar ne potrebujem, in ne veš, da si revež in pomilovanja vreden in ubog in slep in nag,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 18, 'ti svetujem, da kupiš od mene zlata, očiščenega v ognju, da obogatiš, in bela oblačila, da se oblečeš in da se ne pokaže sramota nagote tvoje, in mazila, da si ž njim pomažeš oči, da bi videl.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 19, 'Jaz, katerekoli ljubim, svarim in pokorim; razvnemi se torej in se izpokori!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 20, 'Glej, pri vratih stojim in trkam; če kdo čuje glas moj in odpre vrata, vstopim k njemu, in večerjal bom ž njim in on z menoj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 21, 'Njemu, kdor premaga, dam sedeti z menoj na prestolu svojem, kakor sem tudi jaz premagal in sedel z Očetom svojim na prestol njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 3, 22, 'Kdor ima uho, naj sliši, kaj govori Duh cerkvam.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 1, 'Potem sem videl, in glej: duri odprte na nebu, in prvi glas, ki sem ga slišal kakor glas trombe govoriti z menoj, je dejal: Stopi sem gori, in pokažem ti, kaj se ima zgoditi potem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 2, 'Precej sem bil v Duhu; in glej: prestol je postavljen v nebesih');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 3, 'in na prestolu sedi eden; in sedeči je videti podoben kamenu jaspidu in sardu, in mavrica okrog prestola je videti podobna smaragdu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 4, 'In okrog prestola štiriindvajset prestolov, in na prestolih vidim štiriindvajsetero starejšin sedečih, oblečenih v bela oblačila, in na njih glavah vence zlate.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 5, 'In iz prestola izhajajo bliski in glasovi in gromi; in sedem bakel ognjenih gorí pred prestolom, katere so sedmeri Duhovi Božji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 6, 'In pred prestolom je kakor morje stekleno, podobno kristalu, in sredi prestola in okrog prestola štiri živali, polne očes spredaj in zadaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 7, 'In prva žival je podobna levu, in druga žival podobna teletu, in tretja žival ima obličje kakor človek, in četrta žival podobna orlu letečemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 8, 'In četvere živali, vsaka zase, imajo po šest peruti in so naokolo in znotraj polne očes; in pokoja nimajo noč in dan, govoreč: Svet, svet, svet, Gospod Bog, Vsegamogočni, ki je bil in ki je in ki prihaja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 9, 'In kadar bodo dale živali slavo in čast in hvalo sedečemu na prestolu, živečemu na vekov veke,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 10, 'bodo padli štiriindvajseteri starejšine pred njega, ki sedi na prestolu, in ga molili, ki živi na vekov veke, in bodo metali vence svoje pred prestol, govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 4, 11, 'Vreden si, Gospod in Bog naš, prejemati slavo in čast in moč, zakaj ti si ustvaril vse, in zaradi volje tvoje je bilo vse in je bilo ustvarjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 1, 'In videl sem v desnici sedečega na prestolu knjigo popisano znotraj in zadaj, zapečateno s sedmimi pečati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 2, 'In videl sem mogočnega angela, oznanjujočega z velikim glasom: Kdo je vreden odpreti knjigo in odtrgati pečate njene?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 3, 'In nihče ni mogel ne v nebesih, ne na zemlji, ne pod zemljo odpreti knjige, ne gledati je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 4, 'In jaz sem jokal silno, da ni bil nihče za vrednega spoznan odpreti knjige, ne gledati je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 5, 'In eden izmed starejšin mi reče: Ne jokaj; glej, zmagal je lev, ki je iz roda Judovega, korenina Davidova, da odpre knjigo in sedmere pečate njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 6, 'In videl sem sredi prestola in četverih živali in sredi starejšin Jagnje stoječe, kakor zaklano, ki je imelo sedem rogov in očes sedem, katera so sedmeri Duhovi Božji, poslani na vso zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 7, 'In pride in vzame knjigo iz desnice sedečega na prestolu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 8, 'In ko je vzelo knjigo, padejo četvere živali in štiriindvajseteri starejšine pred Jagnjetom, imajoč vsak strune in zlate čaše, polne kadil, ki so molitve svetnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 9, 'In pojo pesem novo, govoreč: Vreden si prejeti knjigo in odpreti pečate njene; kajti bilo si zaklano in si jih odkupilo Bogu s krvjo svojo iz vsakega rodu in jezika in ljudstva in naroda,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 10, 'in si jih storilo našemu Bogu v kraljestvo in za duhovnike, in kraljevali bodo na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 11, 'In videl sem in slišal sem glas mnogih angelov okrog prestola in živali in starejšin, in njih število je bilo miriad miriade in tisočev tisoči,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 12, 'govorečih z velikim glasom: Vredno je Jagnje, ki je bilo zaklano, prejeti moč in bogastvo in modrost in krepkost in čast in slavo in blagoslov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 13, 'In vsako stvar, ki je v nebesih in na zemlji in pod zemljo in na morju, in vse, kar je v njih, sem čul govoreče: Sedečemu na prestolu in Jagnjetu blagoslov in čast in slava in moč na vekov veke!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 5, 14, 'In četvere živali so rekle: Amen! In štiriindvajseteri starejšine so padli in so molili.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 1, 'In videl sem, ko je Jagnje odprlo enega izmed sedmerih pečatov, in slišal sem eno izmed četverih živali govoriti kakor groma glas: Pridi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 2, 'In videl sem, in glej: bel konj, in sedeči na njem je imel lok; in dan mu je bil venec, in izšel je zmagovit in da zmaga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 3, 'In ko je odprlo drugi pečat, sem slišal drugo žival govoriti: Pridi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 4, 'In izšel je drug konj, rjav, in sedečemu na njem je bilo dano vzeti mir z zemlje in da naj se koljejo med seboj; in mu je bil dan velik meč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 5, 'In ko je odprlo tretji pečat, sem slišal tretjo žival govoriti: Pridi! In videl sem, in glej: črn konj, in sedeči na njem je imel tehtnico v roki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 6, 'In slišal sem kakor glas sredi četverih živali, ki je rekel: Merica pšenice za en denar in tri merice ječmena za en denar; a olju in vinu ne stóri hudega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 7, 'In ko je odprlo četrti pečat, sem slišal glas četrte živali govoriti: Pridi!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 8, 'In videl sem, in glej: bled konj, in sedeči na njem, ime mu Smrt, in smrtno kraljestvo ga spremlja. In mu je bila dana oblast, pomoriti četrtino zemlje z mečem in lakoto in kugo in od zveri zemeljskih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 9, 'In ko je odprlo peti pečat, sem videl pod oltarjem duše zaklanih zavoljo besede Božje in zavoljo pričevanja, ki so ga imeli.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 10, 'In zavpijejo z glasom velikim, rekoč: Doklej, o Gospod, sveti in resnični, ne sodiš in ne maščuješ krvi naše nad njimi, ki prebivajo na zemlji?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 11, 'In dali so jim vsakemu belo oblačilo in so jim rekli, naj počivajo še malo časa, dokler ne bodo dopolnjeni tudi sohlapci njih in bratje njih, ki imajo biti umorjeni kakor tudi oni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 12, 'In videl sem, ko je odprlo šesti pečat, in nastal je velik potres, in solnce je počrnelo kakor vreča raševa, in mesec je pordel ves kakor kri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 13, 'in zvezde nebeške so padale na zemljo, kakor trebi smokva nezrelo sadje svoje, ko jo trese velik veter.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 14, 'In nebo je izginilo kakor knjiga, ko se zvije, in vse gore in otoki so se premeknili s svojih mest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 15, 'In kralji zemlje in velikaši in vojaški poveljniki in bogatini in mogočniki in vsak hlapec in svobodnik so se skrili v jame in skalne razpokline po gorah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 16, 'in reko goram in skalam: Padite na nas in skrijte nas pred obličjem njega, ki sedi na prestolu, in pred jezo Jagnjetovo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 6, 17, 'kajti prišel je velik dan njiju jeze, in kdo more stati?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 1, 'In potem sem videl štiri angele, stoječe na četverih voglih zemlje, držeče četvere vetrove zemlje, da ne veje veter po zemlji, ne po morju, ne čez nobeno drevo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 2, 'In videl sem drugega angela, stopajočega gori od solnčnega vzhoda, ki je imel pečat Boga živega; in je zaklical z glasom velikim četverim angelom, ki jim je bilo dano kaziti zemljo in morje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 3, 'rekoč: Ne kazite zemlje, ne morja, ne dreves, dokler ne zapečatimo hlapcev Boga našega na njih čelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 4, 'In slišal sem število zapečatenih: stoinštiriinštirideset tisoš zapečatenih iz vseh rodov sinov Izraelovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 5, 'Iz rodu Judovega dvanajst tisoč zapečatenih, iz rodu Rubenovega dvanajst tisoč zapečatenih, iz rodu Gadovega dvanajst tisoč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 6, 'iz rodu Aserjevega dvanajst tisoč, iz rodu Neftalimovega dvanajst tisoč, iz rodu Manasejevega dvanajst tisoč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 7, 'iz rodu Simeonovega dvanajst tisoč, iz rodu Levijevega dvanajst tisoč, iz rodu Isaharjevega dvanajst tisoč,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 8, 'iz rodu Zabulonovega dvanajst tisoč, iz rodu Jožefovega dvanajst tisoč, iz rodu Benjaminovega dvanajst tisoč zapečatenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 9, 'Potem sem videl, in glej: velika množica, ki je nihče ni mogel sešteti, iz vsakega naroda in iz vseh rodov in ljudstev in jezikov, stoječe pred prestolom in pred Jagnjetom, oblečene z belimi oblačili in palme v njih rokah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 10, 'in kličejo z glasom velikim, rekoč: Zveličanje Bogu našemu, sedečemu na prestolu, in Jagnjetu!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 11, 'In vsi angeli so stali okrog prestola in starejšin in četverih živali in so padli pred prestolom na obličje in so molili Boga,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 12, 'rekoč: Amen! Blagoslov in slava in modrost in zahvala in čast in moč in krepkost Bogu našemu na vekov veke! Amen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 13, 'In izpregovori eden izmed starejšin, rekoč mi: Kdo so ti, oblečeni z belimi oblačili, in odkod so prišli?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 14, 'In mu rečem: Gospod moj, ti veš. In mi reče: To so tisti, ki prihajajo iz stiske velike in so oprali oblačila svoja in jih pobelili v krvi Jagnjetovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 15, 'Zato so pred prestolom Božjim in mu služijo noč in dan v svetišču njegovem, in sedeči na prestolu razpne svoj šator nad njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 16, 'Lačni ne bodo več, ne žejni več, tudi solnce jih ne zadene, ne vročina nobena;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 7, 17, 'kajti Jagnje, ki je sredi prestola, jih bo paslo in jih vodilo k studencem voda življenja; in Bog obriše vsako solzo ž njih oči.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 1, 'In ko je odprlo sedmi pečat, je nastal molk v nebesih za kake pol ure.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 2, 'In videl sem sedmere angele, ki stoje pred Bogom; in bilo jim je danih sedem tromb.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 3, 'In drug angel je prišel in stopil pred oltar, držeč zlato kadilnico; in mu je bilo dano mnogo kadil, da jih daruje z molitvami vseh svetih na oltarju zlatem pred prestolom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 4, 'In šel je kvišku dim kadil z molitvami svetih iz roke angelove pred Boga.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 5, 'In angel vzame kadilnico in jo napolni z ognjem z oltarja in vrže na zemljo; in nastali so gromi in glasovi in bliski in potres.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 6, 'In sedmeri angeli, ki so imeli sedmere trombe, se pripravijo, da zatrobijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 7, 'In prvi zatrobi in nastane toča in ogenj, namešana s krvjo, in je bila vržena na zemljo; in tretjina zemlje je pogorela in tretjina dreves je pogorela in vsa trava zelena je pogorela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 8, 'In drugi angel zatrobi, in kakor gora velika, z ognjem goreča, je bila vržena v morje; in tretjina morja postane kri,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 9, 'in tretjina stvari, ki so v morju in imajo življenje, pomrje in tretjina ladij se razbije.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 10, 'In tretji angel zatrobi, in z neba pade zvezda velika, goreča kakor bakla, in pade na tretjino rek in na studence vodá;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 11, 'in ime zvezde se imenuje Pelin, in tretjina voda postane pelin in mnogo ljudi je umrlo od voda, ker so bile ogrenele.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 12, 'In četrti angel zatrobi, in udarjena je bila tretjina solnca in tretjina meseca in tretjina zvezd, da otemni tretjina njih in dan ne sije, tretjina njegova, in noč enako.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 8, 13, 'In videl sem in slišal sem enega orla, letečega po sredi neba, govoriti z glasom velikim: Gorje, gorje, gorje prebivalcem na zemlji zaradi ostalih glasov trombe treh angelov, ki imajo še trobiti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 1, 'In peti angel zatrobi, in videl sem zvezdo, z neba padlo na zemljo, in dan ji je bil ključ k žrelu brezna.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 2, 'In odpre žrelo brezna; in privali se dim iz žrela kakor dim peči velike, in solnce in zrak otemnita od dima iz žrela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 3, 'In iz dima izidejo kobilice na zemljo, in dá se jim oblast, kakor imajo oblast škorpijoni zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 4, 'In reče se jim, naj ne store hudega travi zemlje, ne kaki zelenjavi, ne kakemu drevesu, razen ljudem samim, ki nimajo pečata Božjega na čelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 5, 'In dá se jim, da naj jih ne pomore, temuč da naj jih mučijo pet mesecev; in njih mučenje je kakor mučenje škorpijona, kadar piči človeka.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 6, 'In v tistih dneh bodo iskali ljudje smrti, a ne bodo je našli; in želeli bodo umreti, a smrt bo bežala od njih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 7, 'In podobe kobilic so bile enake konjem, pripravljenim na vojsko, in na njih glavah kakor venci, podobni zlatu, in obličja njih kakor obličja človeška;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 8, 'in lase so imele kakor lase ženske in njih zobje so bili kakor levov;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 9, 'in imele so oklepe kakor oklepe železne; in šum njih peruti kakor ropotanje mnogih voz s konji, tekočimi v vojsko;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 10, 'in imajo repe enake škorpijonom in žela; in v repih jim je njih oblast, škodovati ljudem mesecev pet.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 11, 'In nad seboj imajo za kralja angela brezna; ime mu je po hebrejsko: Abadon, in po grško ima ime: Apolion.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 12, 'Gorje eno je prešlo; glej, še dvoje Gorje potem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 13, 'In šesti angel zatrobi, in slišal sem eden glas iz četverih rogov oltarja zlatega pred Bogom,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 14, 'kateri je rekel šestemu angelu, ki je imel trombo: Reši četvere angele, zvezane ob reki veliki, Evfratu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 15, 'In odvezani so bili četveri angeli, ki so bili pripravljeni na uro in dan in mesec in leto, da pomore tretjino ljudi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 16, 'In število vojsk konjištva je bilo dve miriadi miriad; slišal sem njih število.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 17, 'In tako sem videl konje v prikazni in na njih sedeče, ki so imeli oklepe ognjene in temnordeče in žveplene; in glave konj kakor glave levov in iz njih ust izhaja ogenj in dim in žveplo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 18, 'Te tri šibe so pomorile tretjino ljudi, ogenj in dim in žveplo, ki izhaja iz njih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 19, 'Kajti moč konj je v njih ustih in v njih repih; njih repi namreč so enaki kačam, imajo glave in s temi škodijo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 20, 'In ostali ljudje, ki niso bili pomorjeni s temi šibami, se še niso izpokorili od del svojih rok, da bi ne molili zlih duhov in malikov zlatih in srebrnih in bronastih in kamenitih in lesenih, kateri ne morejo ne gledati ne slišati, ne hoditi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 9, 21, 'in niso se izpokorili od moritev svojih, ne od čaranj in ne od nečistosti in ne od tatvin svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 1, 'In videl sem drugega angela mogočnega iti doli z neba, ogrnjenega z oblakom, in mavrica na glavi njegovi, in obličje njegovo kakor solnce in nogi njegovi kakor stebra ognjena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 2, 'In imel je v roki knjižico odprto. In postavil je desno nogo na morje, levo pa na zemljo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 3, 'in je zavpil z glasom velikim, kakor rjove lev. In ko je zavpil, so govorili sedmeri gromovi glasove svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 4, 'In ko so sedmeri gromovi dogovorili, sem hotel pisati; a slišal sem glas z neba, govoreč: Zapečati, kar so govorili sedmeri gromovi, in ne piši tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 5, 'In angel, ki sem ga videl stoječega na morju in na zemlji, vzdigne roko proti nebu');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 6, 'in priseže pri njem, ki živi na vekov veke, ki je ustvaril nebo in kar je na njem, in zemljo in kar je na njej, in morje in kar je v njem: Podaljšanja časa ne bo več,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 7, 'temuč v dneh glasu sedmega angela, ko bo trobil, se tudi dopolni skrivnost Božja, kakor je oznanil v blagovestju hlapcem svojim prorokom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 8, 'In glas, ki sem ga slišal z neba, je zopet govoril z menoj in rekel: Pojdi, vzemi knjižico, odprto v roki angela, stoječega na morju in na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 9, 'In šel sem k angelu in mu rekel, naj mi da knjižico. In mi reče: Vzemi in pojej jo! in zagrenila ti bo trebuh, a v ustih tvojih bode sladka kakor med.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 10, 'In vzamem knjižico iz roke angelove in jo pojem; in bila je v ustih mojih kakor med sladka, a ko sem jo bil pojedel, mi je zagrenel trebuh.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 10, 11, 'In mi reče: Zopet moraš prorokovati o ljudstvih in narodih in jezikih in kraljih mnogih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 1, 'In dan mi je bil trst, podoben palici, in mi je bilo rečeno: Vstani in izmeri svetišče Božje in oltar in tiste, ki molijo v njem.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 2, 'A dvor, ki je zunaj svetišča, vrzi ven in ga ne meri; ker je bil dan poganom in bodo teptali sveto mesto dvainštirideset mesecev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 3, 'In dal bom dvema pričama svojima, in prorokovala bosta tisoč dvesto šestdeset dni, oblečena v raševnika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 4, 'To sta oljki dve in svečnika dva, stoječa pred Gospodom zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 5, 'In če jima hoče kdo storiti kaj žalega, izide jima ogenj iz ust in požre njune sovražnike; in če jima bo hotel kdo kaj žalega storiti, mora enako biti umorjen.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 6, 'Ta imata oblast, nebo zapreti, da ne dežuje v dneh njunega prorokovanja; in oblast imata nad vodami, izpremeniti jih v kri in udariti zemljo z vsako šibo, kolikorkrat bosta hotela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 7, 'In kadar dokončata pričevanje svoje, napravi zver, ki prihaja gori iz brezna, vojsko ž njima in ju zmaga in umori.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 8, 'In trupli njuni bosta ležali na ulicah mesta velikega, ki se imenuje duhovno Sodoma in Egipt, kjer je bil tudi njiju Gospod križan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 9, 'In gledali bodo nekateri iz ljudstev in rodov in jezikov in narodov trupli njuni tri dni in pol, in trupel njunih ne bodo pustili dejati v grobe.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 10, 'In prebivalci na zemlji se bodo veselili nad njima in se radovali, in dari si bodo pošiljali med seboj, ker sta ta dva proroka mučila prebivalce na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 11, 'In po treh dneh in pol je prišel življenja duh iz Boga vanju in sta stopila na noge, in strah velik je prešel tiste, ki so ju gledali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 12, 'In slišala sta glas velik z neba, rekoč jima: Pojdita sem gori! In šla sta gori na nebo v oblaku, in videli so ju sovražniki njuni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 13, 'In v tisti uri je nastal potres velik, in desetina mesta je padla, in pobitih je bilo v potresu sedem tisoč ljudi; in kar jih je ostalo, so se prestrašili in so dali slavo Bogu nebes.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 14, 'Gorje drugo je prešlo; glej, Gorje tretje pride hitro!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 15, 'In sedmi angel zatrobi, in nastanejo glasovi veliki v nebesih, govoreči: Kraljestvo sveta je postalo kraljestvo Gospoda našega in Kristusa njegovega, in kraljeval bo na vekov veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 16, 'In štiriindvajseteri starejšine, ki sede pred Bogom na prestolih svojih, so padli na obličja in molili Boga, rekoč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 17, 'Zahvaljujemo te, Gospod Bog, Vsegamogočni, ki si in ki si bil, da si prejel moč veliko svojo in si zakraljeval.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 18, 'In narodi so se razsrdili, in prišla je jeza tvoja in čas mrtvih, da bodo sojeni, in da se dá plačilo hlapcem tvojim prorokom in svetnikom in njim, ki se boje imena tvojega, malim in velikim, in da se pogube, kateri pogubljajo zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 11, 19, 'In odpre se svetišče Božje, ki je v nebesih, in skrinja zaveze njegove se je videla v svetišču njegovem; in nastali so bliski in glasovi in gromovi in potres in toča velika.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 1, 'In znamenje veliko se je videlo na nebu: žena, oblečena s solncem, in mesec pod njenimi nogami in na njeni glavi venec dvanajsterih zvezd;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 2, 'in noseča je in kriči v bolečinah in mukah porodnih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 3, 'In videlo se je drugo znamenje na nebu, in glej: zmaj velik, ognjen, imajoč sedem glav in rogov deset, in na glavah njegovih sedem diademov,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 4, 'in rep njegov potegne s seboj tretjino zvezd nebeških in jih vrže na zemljo. In zmaj stopi pred ženo, ki ima poroditi, da požre dete njeno, ko ga porodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 5, 'In rodila je sina, moža, ki bo pasel vse narode s palico železno; in njeno dete je bilo vzeto k Bogu in k prestolu njegovemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 6, 'In žena je bežala v puščavo, kjer ima kraj pripravljen od Boga, da jo tam žive dni tisoč dvesto šestdeset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 7, 'In nastala je vojska v nebesih: Mihael in angeli njegovi so se vojskovali zoper zmaja. In zmaj se je vojskoval in angeli njegovi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 8, 'a niso zmogli; tudi njih mesto se ni več našlo v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 9, 'In vržen je bil zmaj veliki in kača stara, ki se imenuje Hudič in Satan, ki zapeljava vesoljni svet, vržen je bil na zemljo, in angeli njegovi so bili vrženi ž njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 10, 'In slišal sem glas velik v nebesih, govoreč: Zdaj je prišlo zveličanje in moč in kraljestvo Boga našega in oblast Kristusa njegovega, ker vržen je doli naših bratov tožnik, ki jih je tožil pred Bogom našim noč in dan.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 11, 'In oni so ga premagali zavoljo krvi Jagnjetove in zavoljo besede pričevanja svojega, in niso ljubili življenja svojega prav do smrti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 12, 'Zato veselite se, nebesa in kateri stanujete v njih! Gorje zemlji in morju, ker doli je šel Hudič k vam, z veliko jezo, ker ve, da ima malo časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 13, 'In ko je videl zmaj, da je vržen na zemljo, je preganjal ženo, ki je rodila moškega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 14, 'In dali so ženi dve peruti orla velikega, da poleti v puščavo, na kraj svoj, kjer se živi čas in dva časa in pol časa, daleč od obličja kače.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 15, 'In kača je vrgla iz ust svojih zadaj za ženo vodo kakor reko, da bi jo reka odnesla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 16, 'A pomogla je ženi zemlja, in odprla je zemlja usta svoja in popila reko, ki jo je bil vrgel zmaj iz svojih ust.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 12, 17, 'In razsrdi se zmaj nad ženo in gre napravljat vojsko z ostalimi semena njenega, ki hranijo zapovedi Božje in imajo pričevanje Jezusa Kristusa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 1, 'In postavi se na pesku morskem. In videl sem iz morja zver vzhajajočo, ki je imela deset rogov in sedem glav, in na rogovih njenih deset diademov in na glavah njenih imena preklinjevanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 2, 'In zver, ki sem jo videl, je bila podobna pardalu, in noge njene kakor medvedove in usta njena kakor usta levova. In dal ji je zmaj moč svojo in prestol svoj in oblast veliko.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 3, 'In videl sem eno izmed glav njenih kakor zaklano na smrt. In njena smrtna rana se je zacelila, in vsa zemlja se je čudila zadaj za zverjo;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 4, 'in molili so zmaja, ker je bil dal oblast zveri, in molili so zver, govoreč: Kdo je zveri enak? In kdo se more vojskovati ž njo?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 5, 'In dana so ji usta, govoreča stvari velike in preklinjevanja, in dana ji je bila oblast, da deluje štirideset mesecev in dva.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 6, 'In odprla je usta svoja v preklinjanje proti Bogu, preklinjajoča ime njegovo in šator njegov in nje, ki stanujejo v nebesih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 7, 'In dano ji je bilo napraviti vojsko s svetimi in jih premagati; in dana ji je oblast nad vsakim rodom in ljudstvom in jezikom in narodom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 8, 'In molili jo bodo vsi, ki prebivajo na zemlji, vsak, čigar ime ni zapisano v knjigi življenja Jagnjeta zaklanega od ustanovitve sveta.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 9, 'Če ima kdo uho, naj sliši.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 10, 'Če kdo v robstvo vodi, v robstvo hodi. Če bo kdo z mečem moril, mora umorjen biti z mečem. Tukaj je stanovitnost in vera svetnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 11, 'In videl sem drugo zver vzhajajočo iz zemlje, in imela je dva rogova, kakor jagnje, a govorila je kakor zmaj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 12, 'In vso oblast prve zveri izvršuje pred njo. In dela, da zemlja in prebivalci njeni molijo prvo zver, ki se ji je bila zacelila rana smrti njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 13, 'In dela znamenja velika, da napravi tudi, da šviga ogenj z neba na zemljo pred ljudmi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 14, 'In zapeljava prebivalce na zemlji z znamenji, katera ji je bilo dano delati pred zverjo, rekoč prebivalcem na zemlji, naj narede podobo zveri, ki je imela rano od meča in je oživela.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 15, 'In dano ji je bilo vdihniti duha podobi zveri, da tudi govori podoba zveri in stori, da bodo pomorjeni, katerikoli ne molijo podobe zveri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 16, 'In stori, da si dado vsi, mali in veliki, bogati in ubogi, svobodni in hlapci, znamenje na desno roko ali na čelo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 17, 'in da nihče ne more kupovati ali prodajati, razen kdor ima znamenje, ime zveri ali število imena njenega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 13, 18, 'Tukaj je modrost. Kdor ima razum, naj izračuni število zveri; je namreč število človeka. In število njegovo je šeststo šestdeset in šest.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 1, 'In videl sem, in glej: Jagnje stoječe na gori Sionu in ž njim stoštiriinštirideset tisoči, ki imajo ime njegovo in ime Očeta njegovega zapisano na čelih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 2, 'In slišal sem glas iz nebes kakor glas mnogih vodá in kakor groma velikega glas; in glas, ki sem ga slišal, je bil kakor citralcev, citrajočih na citre svoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 3, 'In pojo kakor pesem novo pred prestolom in pred četverimi živalmi in starejšinami; in nihče se ni mogel naučiti pesmi razen stoštiriinštiridesetih tisoči, ki so odkupljeni od zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 4, 'Ti so, kateri se niso oskrunili z ženami; device so namreč. Ti so, ki hodijo za jagnjetom, kamorkoli gre. Ti so bili odkupljeni izmed ljudi, prvina Bogu in Jagnjetu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 5, 'In v njih ustih se ni našla laž, brez madeža so.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 6, 'In videl sem drugega angela, letečega po sredi neba, ki je imel večen evangelij, da ga oznani prebivalcem na zemlji in vsakemu narodu in rodu in jeziku in ljudstvu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 7, 'govorečega z glasom velikim: Bojte se Boga in dajte mu slavo, kajti prišla je ura sodbe njegove; in molite njega, ki je naredil nebo in zemljo in morje in studence vodá.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 8, 'In drug je šel za njim, drugi angel, govoreč: Padel je, padel Babilon, mesto véliko, ki je z vinom srda nečistosti svoje napojilo vse narode.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 9, 'In drug pride za njima, tretji angel, govoreč z glasom velikim: Če kdo moli zver in podobo njeno in vzame njeno znamenje na čelo ali na roko svojo,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 10, 'bo tudi on pil od vina srda Božjega, ki je čisto pripravljeno v čaši jeze njegove, in se bo mučil v ognju in žveplu pred svetimi angeli in pred Jagnjetom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 11, 'In njih mučenja dim vzhaja na vekov veke, in pokoja nimajo noč in dan, kateri molijo zver in podobo njeno in kdor sprejme znamenje njenega imena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 12, 'Tukaj je stanovitnost svetnikov, kateri hranijo zapovedi Božje in vero Jezusovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 13, 'In slišal sem glas z neba, rekoč: Piši: Blagor mrtvim, ki umrjejo v Gospodu od sedaj. Da, pravi Duh, odpočijejo se naj od trudov svojih, zakaj njih dela gredo za njimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 14, 'In videl sem, in glej: bel oblak in na oblaku sedeč eden, podoben sinu človečjemu, imajoč na glavi venec zlat in v roki oster srp.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 15, 'In drug angel pride iz svetišča, vpijoč z glasom velikim sedečemu na oblaku: Spusti srp svoj in žanji, kajti prišla je žetve ura, ker prezrela je žetev zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 16, 'In sedeči na oblaku vrže srp svoj na zemljo, in požeta je bila zemlja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 17, 'In drug angel pride iz svetišča, ki je v nebesih, in tudi on ima oster srp.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 18, 'In drug angel pride od oltarja, imajoč oblast nad ognjem, in zavpije z glasom velikim njemu, ki ima srp ostri, rekoč: Spusti srp svoj ostri in odreži grozdje trte zemeljske, kajti dozorele so jagode njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 19, 'In angel vrže srp svoj na zemljo, in rezal je grozdje trte zemeljske in metal v veliko tlačilnico jeze Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 14, 20, 'In tlačila se je tlačilnica zunaj mesta, in tekla je kri iz tlačilnice prav do vajetov konj tisoč šeststo tečajev daleč.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 1, 'In videl sem drugo znamenje v nebesih, veliko in čudovito: sedem angelov, imajočih sedmero šib poslednjih, ker se je v njih dopolnila jeza Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 2, 'In videl sem kakor morje stekleno, namešano z ognjem, in zmagovalce nad zverjo in nad podobo njeno in nad številom njenega imena, stoječe ob morju steklenem s citrami Božjimi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 3, 'In pojo pesem Mojzesa, hlapca Božjega, in pesem Jagnjetovo, govoreč: Velika in čudovita so dela tvoja, o Gospod Bog, Vsegamogočni, pravična in resnična pota tvoja, o Kralj narodov!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 4, 'Kdo bi se te ne bal, Gospod, in ne slavil tvojega imena? ker sam si svet; kajti vsi narodi bodo prišli in molili pred teboj, ker razodela so se pravična dela tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 5, 'In potem sem videl, in odpre se svetišče šatora pričevanja v nebesih,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 6, 'in pridejo iz svetišča sedmeri angeli, ki imajo sedmero šib, oblečeni v platno čisto in svetlo ter opasani okoli prsi z zlatimi pasi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 7, 'In ena iz četverih živali dá sedmerim angelom sedem čaš zlatih, polnih jeze Boga živega na vekov veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 15, 8, 'In napolni se svetišče dima od slave Božje in od moči njegove; in nihče ni mogel iti v svetišče, dokler se ne dokončajo sedmere šibe sedmerih angelov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 1, 'In slišal sem glas velik iz svetišča, govoreč sedmerim angelom: pojdite in izlijte sedmere čaše jeze Božje na zemljo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 2, 'In odide prvi ter izlije čašo svojo na zemljo; in pride uljé hudo in strupeno na ljudi, ki so imeli znamenje zveri in ki so molili podobo njeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 3, 'In drugi angel izlije čašo svojo v morje; in postane kri kakor kri mrliča, in umrje vsaka duša živa, kar jih je v morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 4, 'In tretji angel izlije čašo svojo v reke in studence vodá, in naredi se kri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 5, 'In slišal sem angela vodá govorečega: Pravičen si, Gospod, ki si in ki si bil, Sveti, da si tako sodil:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 6, 'ker kri svetnikov in prerokov so prelivali, in krvi si jim dal piti; vredni so tega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 7, 'In slišal sem oltar reči: Da, Gospod, Bog, Vsegamogočni, resnične in pravične so sodbe tvoje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 8, 'In četrti angel izlije čašo svojo na solnce; in dalo se mu je sežgati ljudi v ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 9, 'In žgali so se ljudje v silni vročini in preklinjali ime Boga, ki ima oblast do teh šib, in niso se izpokorili, da bi mu slavo dajali.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 10, 'In peti izlije čašo svojo na prestol zveri; in kraljestvo njeno je otemnelo, in grizli so si jezike od muke');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 11, 'in preklinjali Boga nebeškega od muk in od uljés svojih, in niso se izpokorili od svojih del.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 12, 'In šesti izlije čašo svojo na reko veliko, Evfrat; in posuši se voda njena, da se pripravi pot kraljem, ki pridejo od solnčnega vzhoda.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 13, 'In videl sem izhajati iz ust zmajevih in iz ust zveri in iz ust lažiproroka tri nečiste duhove, enake žabam;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 14, 'so namreč duhovi hudičev, ki delajo znamenja; ti izhajajo na kralje vesoljnega sveta, da jih zbero na vojsko tistega velikega dne Boga, Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 15, '(Glej, pridem kakor tat; blagor mu, kdor čuje in hrani oblačila svoja, da ne hodi nag in ne gledajo sramote njegove).');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 16, 'In zbrali so jih na kraj, imenovan po hebrejsko: Harmagedon.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 17, 'In sedmi izlije čašo svojo v zrak; in prišel je glas velik iz svetišča, od prestola, rekoč: Zgodilo se je!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 18, 'In nastanejo bliski in glasovi in gromi, in nastane potres velik, kakršnega ni bilo, odkar so bili ljudje na zemlji, tolik potres, tako grozen!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 19, 'In mesto veliko se raztrga na tri dele, in mesta narodov padejo; in Babilon veliki je prišel v spomin pred Bogom, da se mu da čaša vina srda in jeze njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 20, 'In vsi otoki so bežali in gorá ni bilo najti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 16, 21, 'In toča velika, kakor talent težka, pada z neba na ljudi; in ljudje so preklinjali Boga zaradi šibe toče, ker silno težka je šiba njena.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 1, 'In prišel je eden iz sedmerih angelov, ki imajo sedmere čaše, in je govoril z menoj, rekoč: Sem! pokažem ti sodbo nečistnice vélike, sedeče na mnogih vodah,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 2, 's katero so nečistovali kralji zemeljski, in z vinom nečistosti njene so se opijanili zemlje prebivalci.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 3, 'In odnese me v puščavo v Duhu; in videl sem ženo, sedečo na zveri škrlatni, polni imen preklinjanja, imajoči sedem glav in rogov deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 4, 'In žena je bila oblečena v bager in v škrlat in pozlačena z zlatom in dragim kamenjem in biseri; imela je zlat kozarec v roki, poln gnusob in nečistosti kurbarstva svojega;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 5, 'in na čelu ji je bilo ime zapisano, skrivnost: Babilon véliki, mati nečistnic in gnusob zemlje!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 6, 'In videl sem to ženo pijano krvi svetnikov in krvi pričevalcev Jezusovih. In videč jo, sem se silno čudil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 7, 'In angel mi reče: Zakaj se čudiš? Jaz ti povem skrivnost žene in zveri, ki jo nosi, ki ima sedem glav in rogov deset.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 8, 'Zver, ki si jo videl, je bila in je ni, in priti ima gori iz brezna in iti v pogubo; in prebivalci na zemlji, katerih imena niso zapisana v knjigi življenja od ustanovitve sveta, se bodo čudili, gledajoč zver, da je bila in je ni, a zopet pride.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 9, 'Tukaj razum, ki ima modrost: sedmero glav je sedem gorá, kjer žena sedi na njih;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 10, 'in je kraljev sedem: pet jih je padlo in eden je, drugi še ni prišel, in kadar pride, sme malo časa ostati.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 11, 'In zver, ki je bila in je ni, je sam tudi osmi in je izmed sedmerih in gre v pogubo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 12, 'In desetero rogov, ki si jih videl, je deset kraljev, ki še niso prejeli kraljestva, ali prejmo oblast kot kralji za eno uro z zverjo vred.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 13, 'Ti imajo eno misel, in moč in oblast svojo izročé zveri.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 14, 'Ti se bodo vojskovali z Jagnjetom, in Jagnje jih bo zmagalo, ker je gospodov Gospod in kraljev Kralj, in ž njim bodo zmagali poklicani in izvoljeni in zvesti.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 15, 'In reče mi: Vode, ki si jih videl, kjer sedi nečistnica, so ljudstva in množice in narodi in jeziki.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 16, 'In deseteri rogovi, ki si jih videl, in zver, ti bodo sovražili nečistnico in jo naredili pusto in nago ter meso njeno pojedli in njo sežgali v ognju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 17, 'Kajti Bog je dal v njih srca, da storé misel njegovo in da store eno misel in dado kraljestvo svoje zveri, dokler se ne izvršé besede Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 17, 18, 'In žena, ki si jo videl, je mesto véliko, ki ima kraljestvo nad kralji zemlje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 1, 'Potem sem videl drugega angela iti doli z neba, ki je imel oblast veliko; in zemlja se je razsvetlila od slave njegove.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 2, 'In zavpije z močnim glasom, rekoč: Padel je, padel Babilon veliki, in postal je prebivališče hudičev in ječa vseh nečistih duhov in ječa vseh nečistih in sovraženih ptičev.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 3, 'Kajti od vina srda nečistosti njene so pili vsi narodi, in kralji zemeljski so nečistovali ž njo, in trgovci zemlje so obogateli od silne bujnosti njene.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 4, 'In slišal sem drug glas z nebes, govoreč: Izidite iz nje, ljudstvo moje, da se ne udeležite grehov njenih in da ne prejmete od njenih šib;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 5, 'kajti grehi njeni so se nakopičili do neba, in Bog se je spomnil krivic njenih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 6, 'Vrnite ji, kakor je tudi ona vračala, in podvojite ji dvojno po delih njenih; v kozarec, v katerega je mešala, namešajte ji dvojno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 7, 'Kolikor se je poveličala in prešerno živela, toliko ji dajte muke in žalosti. Kajti v srcu svojem govori: Kraljica sedim in vdova nisem, in žalosti ne bom videla.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 8, 'Zato pridejo v enem dnevu šibe njene, smrt in žalost in lakota, in v ognju bo sežgana; kajti močan je Gospod, Bog, ki jo je sodil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 9, 'In jokali bodo in žalovali zanjo kralji zemlje, kateri so nečistovali ž njo in prešerno živeli, ko bodo videli dim požara njenega,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 10, 'od daleč stoječ v strahu pred muko njeno in govoreč: Gorje, gorje, mesto veliko, Babilon, mesto močno! ker v eni uri je prišla sodba tvoja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 11, 'In trgovci zemlje jokajo in žalujejo za njo, ker njih blaga ne kupuje nihče več:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 12, 'blaga iz zlata in srebra in dragega kamenja in biserov in tenčice in bagra in svile in škrlata, in vsakterega lesa dišečega in vsakterega orodja slonokoščenega in vsakterega orodja iz lesa predragega in brona in železa in marmorja,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 13, 'in sladke skorje in tujih korenin in dišav in mire in kadila, in vina in olja in bele moke in pšenice, in goved in ovac, in konj in voz in sužnjev in duš človeških.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 14, 'In sadje, ki si ga je želela duša tvoja, je odšlo od tebe, in vse tolsto in sijajno ti je izginilo, in nikdar več jih nihče ne najde.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 15, 'Trgovci s temi rečmi, ki so obogateli od nje, bodo stali oddaleč v strahu pred muko njeno, jokajoč in žalujoč in govoreč:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 16, 'Gorje, gorje, mesto véliko, ki je bilo oblečeno v tenčico in v bager in škrlat in pozlačeno z zlatom in dragim kamenjem in biseri!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 17, 'kajti v eni uri je izničeno toliko bogastvo. In vsi krmarji in vsak, kdor se kam vozi v ladji, in brodniki in katerikoli imajo opravila na morju, so stali oddaleč');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 18, 'in vpili, videč dim požara njenega, in govorili: Katero je enako temu mestu vélikemu?');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 19, 'In vrgli so si prahu na glave in so vpili, jokajoč in žalujoč in govoreč: Gorje, gorje, mesto véliko, v katerem so obogateli vsi, ki imajo ladje na morju, vsled potratnosti njegove! kajti v eni uri je opustošeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 20, 'Veselite se njega, nebesa, in svetniki in apostoli in proroki, ker je Bog sodil sodbo vašo nad njim.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 21, 'In en angel, močan, je vzdignil kamen, velik kakor mlinski kamen, in ga vrgel v morje, rekoč: Tako siloma bo doli vržen Babilon, mesto veliko, in ne bode ga več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 22, 'In glas citralcev in godcev in piskačev in trobentačev se ne bo nikdar več slišal v tebi, in noben umetnik kake umetnosti se ne prikaže nikdar več v tebi, in mlina glas se ne bo nikdar več čul v tebi,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 23, 'in svetilnice luč nikoli več ne bo svetila v tebi, in glas ženina in neveste se ne bo nikdar več čul v tebi; kajti trgovci tvoji so bili velikaši zemlje; in s čarodejstvom tvojim so bili zapeljani vsi narodi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 18, 24, 'In v njem se je našla kri prorokov in svetnikov in vseh, ki so bili zaklani na zemlji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 1, 'In potem sem slišal kakor močan glas velike množice v nebesih, rekoč: Aleluja! zveličanje in slava in moč Bogu našemu,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 2, 'kajti resnične in pravične so sodbe njegove; zakaj sodil je nečistnico véliko, ki je pačila zemljo z nečistostjo svojo, in hlapcev svojih kri je maščeval na roki njeni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 3, 'In drugič so rekli: Aleluja! In dim njen vzhaja na vekov veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 4, 'In padli so starejšine štiriindvajseteri in četvere živali in so molili Boga, sedečega na prestolu, rekoč: Amen, Aleluja!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 5, 'In glas je prišel od prestola, govoreč: Hvalite Boga našega, vsi hlapci njegovi, ki se ga bojite, mali in véliki!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 6, 'In slišal sem kakor glas množice velike in kakor glas mnogih vodá in kakor glas močnih gromov, govorečih: Aleluja! ker zakraljeval je Gospod, Bog naš, Vsegamogočni.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 7, 'Veselimo se in radujmo in dajajmo slavo njemu; ker prišlo je ženitvovanje Jagnjetovo, in nevesta njegova se je pripravila.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 8, 'In dano ji je bilo, da se obleče v tenčico, svetlo in čisto; tenčica namreč so pravična dela svetnikov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 9, 'In mi veli: Piši: Blagor jim, kateri so poklicani k večerji ženitvovanja Jagnjetovega! In mi reče: To so resnične besede Božje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 10, 'In padel sem pred noge njegove, da ga molim. In mi reče: Glej, da tega ne storiš! hlapec sem s teboj vred in s tvojimi brati, ki imajo pričevanje Jezusovo, Boga móli! Kajti pričevanje Jezusovo je duh prorokovanja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 11, 'In videl sem nebesa odprta, in glej: bel konj in sedeči na njem imenovan Zvesti in Resnični, in v pravičnosti sodi ter se vojskuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 12, 'Oči njegove pa so plamen ognjen, in na glavi njegovi mnogi diademi, in zapisano ima ime, ki ga nihče ne zna razen njega samega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 13, 'In ogrnjen je z oblačilom, omočenim s krvjo, in imenuje se ime njegovo: Beseda Božja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 14, 'In vojske, ki so v nebesih, so šle za njim na belih konjih, oblečene v tenčico belo in čisto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 15, 'In iz ust njegovih izhaja oster meč, da ž njim udarja narode; in on jih bo pasel s šibo železno, in on tlači tlačilnico vina srda in jeze Boga, Vsegamogočnega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 16, 'In ima na obleki in na bedru svojem ime zapisano: KRALJ KRALJEV IN Gospodov Gospod.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 17, 'in videl sem enega angela, stoječega v solncu, in zavpil je z glasom velikim, rekoč vsem ptičem, ki letajo po sredi neba: Pridite in zberite se k veliki večerji Božji,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 18, 'da jeste meso kraljev in meso vojaških poveljnikov in meso mogočnih in meso konj in sedečih na njih in meso vseh, svobodnih in hlapcev, malih in velikih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 19, 'In videl sem zver in kralje zemlje in njih vojske zbrane, da se vojskujejo s sedečim na konju in z vojsko njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 20, 'In zgrabljena je bila zver in ž njo lažiprorok, ki je delal pred njo znamenja, s katerimi je zapeljeval nje, ki so bili sprejeli znamenje zveri in ki so molili podobo njeno; živa sta bila vržena ta dva v jezero ognjeno, z žveplom goreče.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 19, 21, 'In drugi so bili pomorjeni z mečem sedečega na konju, s tistim, ki je izhajal iz ust njegovih; in vsi ptiči so se napasli ž njih mesom.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 1, 'In videl sem angela iti doli iz nebes, imajočega ključ od brezna in verigo veliko na roki svoji.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 2, 'In zgrabi zmaja, staro kačo, ki je hudič in satan; in zveže ga za tisoč let in ga vrže v brezno in zapre in zapečati nad njim, da ne zapeljuje več narodov, dokler se ne izpolni tisoč let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 3, 'Potem se mora izpustiti za malo časa.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 4, 'In videl sem prestole, in sedli so nanje in dana jim je bila sodba; in videl sem duše obglavljenih zaradi pričevanja Jezusovega in zaradi besede Božje in tiste, ki niso molili zveri, ne podobe njene, in niso sprejeli znamenja na čelo in na roko svojo: in oživeli so ter kraljevali s Kristusom tisoč let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 5, 'Drugi mrtvi pa niso oživeli, dokler se ne izpolni tisoč let. To je vstajenje prvo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 6, 'Blažen in svet, kdor ima delež v prvem vstajenju; do teh druga smrt nima oblasti, marveč duhovniki bodo Božji in Kristusovi, in bodo ž njim kraljevali tisoč let.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 7, 'In ko se izpolni tisoč let, bo izpuščen satan iz ječe svoje,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 8, 'in izide zapeljevat narode, ki so na četverih voglih zemlje, Goga in Magoga, da jih zbere na vojsko; katerih število je kakor peska v morju.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 9, 'In šli so gori na zemlje širjavo in so obkrožili šatorišče svetnikov in mesto ljubljeno; in prišel je ogenj od Boga z neba in požrl jih je.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 10, 'In hudič, ki jih je zapeljaval, je bil vržen v jezero ognjeno in žvepleno, kjer sta tudi zver in lažiprorok; in mučili se bodo noč in dan na vekov veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 11, 'In videl sem bel prestol, velik, in sedečega na njem, ki mu je izpred obličja bežala zemlja in nebo, in ni se jima našlo mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 12, 'In videl sem mrtve, velike in male, stoječe pred prestolom, in knjige so se odprle; in druga knjiga se je odprla, ki je knjiga življenja. In sojeni so bili mrtvi po tem, kar je bilo pisano v knjigah, po delih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 13, 'In dalo je morje mrtve, ki so bili v njem, in smrt in smrtna država sta dali mrtve, ki so bili v njiju, in sojeni so bili, vsak po delih svojih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 14, 'In smrt in smrtna država sta bili vrženi v jezero ognjeno. To je smrt druga, jezero ognjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 20, 15, 'In če koga niso našli zapisanega v knjigi življenja, je bil vržen v jezero ognjeno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 1, 'In videl sem novo nebo in zemljo novo; kajti prvo nebo in prva zemlja sta bila prešla, in morja ni več.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 2, 'In videl sem mesto sveto, Jeruzalem novi, da gre navzdol od Boga iz nebes, napravljeno kakor nevesta, odičena ženinu svojemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 3, 'In slišal sem glas velik od prestola, da govori: Glej, šator Božji z ljudmi, in prebival bo ž njimi; in oni bodo ljudstva njegova, in Bog sam bode med njimi, njih Bog,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 4, 'in obriše vse solze ž njih oči; in smrti ne bode več, ne žalovanja, ne vpitja, ne bolečine ne bode več; kajti prvo je prešlo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 5, 'In rekel je sedeči na prestolu: Glej, novo delam vse. In mi veli: Piši, ker te besede so resnične in zveste.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 6, 'In mi reče: Zgodilo se je. Jaz sem Alfa in Omega, začetek in konec. Jaz bom dal žejnemu iz studenca vode življenja brezplačno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 7, 'Kdor premaga, bo to podedoval, in bodem mu Bog in on mi bode sin.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 8, 'Strahopetnim pa in nevernim in ostudnim in morilcem in nečistnikom in čarovnikom in malikovalcem in vsem lažnivcem, njim je delež v jezeru, gorečem z ognjem in žveplom, kar je druga smrt.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 9, 'In pride eden izmed sedmerih angelov, ki so imeli sedmero čaš, polnih sedmerih šib poslednjih, in je govoril z menoj, rekoč: Sem! pokažem ti nevesto, ženo Jagnjetovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 10, 'In odnese me v Duhu na goro veliko in visoko in mi pokaže sveto mesto, Jeruzalem, ki gre doli od Boga iz nebes,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 11, 'imajoč slavo Božjo. In svetloba njegova je enaka kamenu predragemu, kakor kamenu jaspidu, čistemu kot kristal;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 12, 'ima zid velik in visok in ima dvanajstero vrat, in ob vratih angelov dvanajst in imena na njih zapisana, katera so dvanajsterih rodov sinov Izraelovih:');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 13, 'proti vzhodu troje vrat, proti severu troje vrat, proti jugu troje vrat, proti zahodu troje vrat.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 14, 'In zid mestni ima temeljnih kamenov dvanajst, in na njih dvanajst imen dvanajsterih apostolov Jagnjetovih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 15, 'In z menoj govoreči je imel merilo zlato, da izmeri mesto in vrata njegova in zid njegov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 16, 'In mesto je zidano na štiri vogle, in dolžina njegova tolikšna, kolikršna tudi širjava. In izmeril je mesto z merilom na dvanajst tisoč tečajev; dolžina in širjava in višava so enake.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 17, 'In izmeril je zid njegov na stoinštiriinštirideset lahti, po človeški meri, ki je angelova.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 18, 'In zid njegov je zidan iz jaspida, in mesto je čisto zlato, enako steklu čistemu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 19, 'Temeljni kameni zidu mestnega so odičeni z vsakovrstnim dragim kamenjem: temelj prvi jaspid, drugi safir, tretji kalcedon, četrti smaragd,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 20, 'peti sardoniks, šesti sard, sedmi hrizolit, osmi beril, deveti topaz, deseti hrizopraz, enajsti hiacint, dvanajsti ametist.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 21, 'In dvanajstera vrata dvanajst biserov; vsaka vrata so bila iz enega bisera. In ulice mestne čisto zlato, kakor steklo prozorno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 22, 'A svetišča nisem videl v njem, kajti Gospod, Bog, Vsegamogočni, je svetišče njegovo in Jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 23, 'In mesto ne potrebuje solnca, ne meseca, da svetita v njem; zakaj slava Božja ga je razsvetlila, in svetilnica njegova je Jagnje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 24, 'In narodi bodo hodili po svetlobi njegovi, in kralji zemlje nosijo slavo svojo vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 25, 'In vrata njegova se ne zaklenejo podnevi, noči namreč tam ne bode;');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 26, 'in zneso slavo in čast narodov vanje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 21, 27, 'In ne pride vanje nič nečistega, ne kdor dela gnusobo in laž, samo kateri so zapisani v življenja knjigi Jagnjetovi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 1, 'In pokazal mi je reko vode življenja, svetlo kakor kristal, izhajajočo iz prestola Božjega in Jagnjetovega.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 2, 'Sredi ulic njegovih ter na to in ono stran reke je drevo življenja, ki rodi sadov dvanajst, vsak mesec dajoč sad svoj, in listje drevesno je v ozdravljenje narodov.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 3, 'In nobenega prokletstva ne bode več. In prestol Božji in Jagnjetov bode v njem; in hlapci njegovi mu bodo služili,');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 4, 'in gledali bodo obličje njegovo, in ime njegovo bo na njih čelih.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 5, 'In noči ne bode več, in potreba jim ni svetilnice in luči solnčne, ker jim bo svetil Gospod, Bog; in kraljevali bodo na vekov veke.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 6, 'In reče mi: Te besede so zveste in resnične, in Gospod, Bog duhov proroških, je poslal angela svojega, pokazat hlapcem svojim, kaj se ima zgoditi skoraj.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 7, 'In glej, hitro pridem. Blagor mu, kdor hrani besede prorokovanja te knjige!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 8, 'In jaz Janez sem, ki sem videl to in slišal. In ko sem slišal in videl, sem padel pred nogami angela, ki mi je to kazal, da bi ga molil.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 9, 'In reče mi: Glej, da tega ne storiš! hlapec sem s teboj vred in z brati tvojimi proroki in ž njimi, ki hranijo besede te knjige; Boga móli!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 10, 'In mi veli: Ne zapečati besed prorokovanja te knjige, ker čas je blizu.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 11, 'Kdor dela krivico, naj jo dela še, in kdor je nesnažen, bodi še nesnažen; in kdor je pravičen, delaj še bolj pravico, in sveti naj se še bolj posvečuje.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 12, 'Glej, pridem hitro in plačilo moje z menoj, da povrnem vsakemu, kakor je delo njegovo.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 13, 'Jaz sem Alfa in Omega, prvi in poslednji, začetek in konec.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 14, 'Blagor jim, ki pero oblačila svoja, da imajo oblast do drevesa življenja in da gredo skozi vrata v mesto.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 15, 'Zunaj bodo psi in čarovniki in nečistniki in morilci in malikovalci in vsak, kdor ljubi in dela laž.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 16, 'Jaz Jezus sem poslal angela svojega, pričat vam to po cerkvah. Jaz sem korenina in rod Davidov, svetla zvezda jutranja.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 17, 'In Duh in nevesta govorita: Pridi! In kdor sliši, naj reče: Pridi! In kdor je žejen, pridi; kdor hoče, vzemi vodo življenja brezplačno.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 18, 'Pričam vsakemu, kdor sliši besede prorokovanja te knjige: Ako kdo k temu kaj pristavi, njemu pridene Bog šib, ki so zapisane v tej knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 19, 'In ako kdo kaj odvzame od besed knjige tega prorokovanja, odvzame Bog delež njegov od drevesa življenja in iz mesta svetega, od tega, kar je pisano v tej knjigi.');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 20, 'On, ki to priča, pravi: Gotovo, pridem hitro. Amen, pridi, Gospod Jezus!');
INSERT INTO `SloChraska_verses` (`book_id`, `chapter`, `verse`, `text`) VALUES (66, 22, 21, 'Milost Gospoda Jezusa bodi z vsemi svetimi. Amen.');
